accessxi_paths = accessxi_paths or {};

accessxi_paths.normalize = function (path)
    local value = tostring(path or ''):gsub('/', '\\');
    value = value:gsub('[\\/]+$', '');
    return value;
end

accessxi_paths.join = function (...)
    local parts = { ... };
    local output = '';
    for _, part in ipairs(parts) do
        local value = tostring(part or '');
        if (value ~= '') then
            value = value:gsub('/', '\\');
            if (output == '') then
                output = value:gsub('[\\/]+$', '');
            else
                value = value:gsub('^[\\/]+', ''):gsub('[\\/]+$', '');
                if (value ~= '') then
                    output = output .. '\\' .. value;
                end
            end
        end
    end
    return output;
end

accessxi_paths.parent = function (path)
    local value = accessxi_paths.normalize(path);
    local parent = value:match('^(.*)\\[^\\]+$');
    if (parent == nil or parent == '') then
        return '';
    end
    return parent;
end

accessxi_paths.file_exists = function (path)
    if (path == nil or tostring(path) == '') then
        return false;
    end
    local f = io.open(tostring(path), 'rb');
    if (f ~= nil) then
        f:close();
        return true;
    end
    return false;
end

accessxi_paths.raw_addon_root = function ()
    local raw_addon = rawget(_G, 'addon');
    if (type(raw_addon) ~= 'table') then
        raw_addon = rawget(_G, '_addon');
    end
    if (type(raw_addon) == 'table' and tostring(raw_addon.path or '') ~= '') then
        return accessxi_paths.normalize(raw_addon.path);
    end
    return '';
end

function accessxi_boot_trace(text)
    pcall(function ()
        local boot_root = accessxi_paths.raw_addon_root();
        local boot_path = 'ffxi-menu-reader.boot.log';
        if (boot_root ~= '') then
            boot_path = accessxi_paths.join(boot_root, 'ffxi-menu-reader.boot.log');
        end
        local f = io.open(boot_path, 'a');
        if (f ~= nil) then
            f:write(os.date('%Y-%m-%d %H:%M:%S'), ' ', tostring(text or ''), '\n');
            f:close();
        end
    end);
end

