accessxi_paths.find_ashita_root = function ()
    local ok, path = pcall(function ()
        if (AshitaCore ~= nil and AshitaCore.GetInstallPath ~= nil) then
            return AshitaCore:GetInstallPath();
        end
        return '';
    end);
    if (ok and tostring(path or '') ~= '') then
        return accessxi_paths.normalize(path);
    end

    local addon_root = accessxi_paths.raw_addon_root();
    local addons_root = accessxi_paths.parent(addon_root);
    local ashita_root = accessxi_paths.parent(addons_root);
    return accessxi_paths.normalize(ashita_root);
end

accessxi_paths.default_ffxi_root_candidates = function ()
    local candidates = {};
    local seen = {};
    local roots = {
        os.getenv('ACCESSXI_FFXI_ROOT') or '',
        os.getenv('FFXI_INSTALL_DIR') or '',
        os.getenv('ProgramFiles(x86)') or '',
        os.getenv('ProgramW6432') or '',
        os.getenv('ProgramFiles') or '',
    };
    local subdirs = {
        { 'PlayOnline', 'SquareEnix', 'FINAL FANTASY XI' },
        { 'SquareEnix', 'FINAL FANTASY XI' },
    };

    for _, root in ipairs(roots) do
        root = accessxi_paths.normalize(root);
        if (root ~= '') then
            local direct_key = root:lower();
            if (seen[direct_key] ~= true) then
                seen[direct_key] = true;
                candidates[#candidates + 1] = root;
            end
            for _, subdir in ipairs(subdirs) do
                local candidate = root;
                for _, part in ipairs(subdir) do
                    candidate = accessxi_paths.join(candidate, part);
                end
                local key = candidate:lower();
                if (seen[key] ~= true) then
                    seen[key] = true;
                    candidates[#candidates + 1] = candidate;
                end
            end
        end
    end

    return candidates;
end

accessxi_paths.find_ffxi_root = function ()
    local ok, path = pcall(function ()
        if (ashita ~= nil and ashita.fs ~= nil and ashita.fs.get_install_dir ~= nil) then
            return ashita.fs.get_install_dir(2, 1);
        end
        return '';
    end);
    local normalized = accessxi_paths.normalize(ok and path or '');
    if (normalized ~= '' and accessxi_paths.ffxi_root_has_core_dat(normalized)) then
        return normalized;
    end

    local candidates = accessxi_paths.default_ffxi_root_candidates();
    for _, candidate in ipairs(candidates) do
        local value = accessxi_paths.normalize(candidate);
        if (accessxi_paths.ffxi_root_has_core_dat(value)) then
            return value;
        end
    end
    return '';
end

accessxi_paths.resolved_addon_root = function ()
    local value = '';
    if (type(addon) == 'table') then
        value = accessxi_paths.normalize(addon.path or '');
    end
    if (value ~= '') then
        return value;
    end
    return accessxi_paths.raw_addon_root();
end

accessxi_paths.ffxi_root_has_core_dat = function (path)
    path = accessxi_paths.normalize(path);
    return path ~= ''
        and accessxi_paths.file_exists(accessxi_paths.join(path, 'ROM', '97', '40.DAT'))
        and accessxi_paths.file_exists(accessxi_paths.join(path, 'ROM', '176', '60.DAT'));
end

accessxi_paths.addon_root = accessxi_paths.resolved_addon_root();
accessxi_paths.ashita_root = accessxi_paths.find_ashita_root();
accessxi_paths.ffxi_root = accessxi_paths.find_ffxi_root();

accessxi_paths.addon_path = function (...)
    return accessxi_paths.join(accessxi_paths.addon_root, ...);
end

accessxi_paths.ashita_path = function (...)
    return accessxi_paths.join(accessxi_paths.ashita_root, ...);
end

accessxi_paths.ffxi_path = function (...)
    if (accessxi_paths.ffxi_root == '') then
        return '';
    end
    return accessxi_paths.join(accessxi_paths.ffxi_root, ...);
end

