local function tick()
    return ashita.time.clock()['ms'];
end

function accessxi.debug_probe_logging_active()
    if (accessxi.debug_probe_logging_enabled ~= true) then
        return false;
    end

    local until_tick = tonumber(accessxi.debug_probe_logging_until) or 0;
    if (until_tick > 0 and tick() >= until_tick) then
        accessxi.debug_probe_logging_enabled = false;
        accessxi.debug_probe_logging_until = 0;
        return false;
    end

    return true;
end

local function log_line(text)
    local f = io.open(accessxi.log_path, 'a');
    if (f ~= nil) then
        f:write(os.date('%Y-%m-%d %H:%M:%S'), ' ', text, '\n');
        f:close();
    end
end

local function log_state(text)
    if (text == accessxi.last_state_log) then
        return;
    end
    accessxi.last_state_log = text;
    log_line(text);
end

function accessxi.install_reload_hotkey()
    local ok, err = pcall(function ()
        local chat = AshitaCore:GetChatManager();
        if (chat == nil) then
            error('chat manager unavailable');
        end
        chat:QueueCommand(1, '/bind ^+r /addon reload accessxi_reader');
    end);
    log_line(ok and 'reload hotkey installed key="Ctrl+Shift+R"' or ('reload hotkey install failed error="' .. tostring(err or '') .. '"'));
end

