function accessxi.is_foreground_process()
    local ok, hwnd = pcall(function () return kernel32.GetForegroundWindow(); end);
    if (not ok) then
        return false;
    end
    if (hwnd == nil) then
        return false;
    end

    local pid = ffi.new('DWORD[1]', 0);
    pcall(function () return kernel32.GetWindowThreadProcessId(hwnd, pid); end);
    local foreground_pid = tonumber(pid[0]) or 0;
    if (foreground_pid == 0) then
        return false;
    end

    return foreground_pid == (tonumber(kernel32.GetCurrentProcessId()) or -1);
end

function accessxi.load_module_file_table(path, label, fallback)
    path = tostring(path or '');
    label = tostring(label or path);
    if (path == '') then
        return fallback or T{};
    end

    local chunk, load_err = loadfile(path);
    if (type(chunk) ~= 'function') then
        log_line(('module load failed label="%s" path="%s" err="%s"'):fmt(label, path, tostring(load_err)));
        return fallback or T{};
    end

    local env = T{};
    env.accessxi = accessxi;
    setmetatable(env, { __index = _G });

    local ok_env, env_err = pcall(function ()
        setfenv(chunk, env);
    end);
    if (not ok_env) then
        log_line(('module env failed label="%s" path="%s" err="%s"'):fmt(label, path, tostring(env_err)));
        return fallback or T{};
    end

    local ok, data = pcall(chunk);
    if (ok and type(data) == 'table') then
        return data;
    end

    log_line(('module load failed label="%s" path="%s" err="%s"'):fmt(label, path, tostring(data)));
    return fallback or T{};
end

function accessxi.load_module_table(name, fallback)
    name = tostring(name or ''):gsub('[^A-Za-z0-9_%-]', '');
    if (name == '') then
        return fallback or T{};
    end

    local path = accessxi_paths.addon_path('modules', name .. '.lua');
    return accessxi.load_module_file_table(path, ('module:%s'):fmt(name), fallback);
end

