    end

    local path = accessxi_paths.addon_path('modules', 'menus', name .. '.lua');
    return accessxi.load_module_file_table(path, ('menu:%s'):fmt(name), fallback);
end

function accessxi.load_code_module(name, env)
    name = tostring(name or ''):gsub('[^A-Za-z0-9_%-]', '');
    if (name == '') then
        return false;
    end

    local path = accessxi_paths.addon_path('modules', name .. '.lua');
    local chunk, load_err = loadfile(path);
    if (type(chunk) ~= 'function') then
        log_line(('module code load failed label="code:%s" path="%s" err="%s"'):fmt(name, path, tostring(load_err)));
        return false;
    end

    env = env or T{};
    env.accessxi = accessxi;
    setmetatable(env, { __index = _G });
    local ok_env, env_err = pcall(function () setfenv(chunk, env); end);
    if (not ok_env) then
        log_line(('module code env failed label="code:%s" path="%s" err="%s"'):fmt(name, path, tostring(env_err)));
        return false;
    end

    local ok_run, run_err = pcall(chunk);
    if (not ok_run) then
        log_line(('module code run failed label="code:%s" path="%s" err="%s"'):fmt(name, path, tostring(run_err)));
        return false;
    end
    return true;
end

