local function utf8_to_wide(text)
    local needed = kernel32.MultiByteToWideChar(CP_UTF8, 0, text, #text, nil, 0);
    if (needed <= 0) then
        return nil;
    end

    local wide = ffi.new('wchar_t[?]', needed + 1);
    kernel32.MultiByteToWideChar(CP_UTF8, 0, text, #text, wide, needed);
    wide[needed] = 0;
    return wide;
end

function accessxi.prism_error_text(code)
    code = tonumber(code) or -1;
    if (speech.prism ~= nil) then
        local ok, value = pcall(function ()
            local err = speech.prism.prism_error_string(code);
            if (err ~= nil) then
                return ffi.string(err);
            end
            return nil;
        end);
        if (ok and value ~= nil and value ~= '') then
            return value;
        end
    end
    return tostring(code);
end

function accessxi.prism_reset_speech()
    if (speech.prism ~= nil and speech.backend ~= nil) then
        pcall(function () speech.prism.prism_backend_stop(speech.backend); end);
    end
    if (speech.prism ~= nil and speech.backend ~= nil) then
        pcall(function () speech.prism.prism_backend_free(speech.backend); end);
    end
    speech.backend = nil;
    speech.backend_name = '';

    if (speech.prism ~= nil and speech.ctx ~= nil) then
        pcall(function () speech.prism.prism_shutdown(speech.ctx); end);
    end
    speech.ctx = nil;
end

function accessxi.prism_note_error(message)
    message = tostring(message or '');
    accessxi.prism_last_error = message;
    accessxi.prism_retry_after = tick() + 3000;
    if (message ~= '' and message ~= accessxi.prism_last_error_log) then
        accessxi.prism_last_error_log = message;
        log_line('speech prism error ' .. message);
    end
end

function accessxi.prism_init_speech(force)
    if (speech.backend ~= nil) then
        return true;
    end

    if (not force and tick() < (accessxi.prism_retry_after or 0)) then
        return false;
    end

    if (speech.prism == nil) then
        local ok, lib = pcall(ffi.load, accessxi.prism_dll_path);
        if (not ok or lib == nil) then
            accessxi.prism_note_error('load failed: ' .. tostring(lib));
            return false;
        end
        speech.prism = lib;
    end

    local ok_ctx, ctx = pcall(function () return speech.prism.prism_init(nil); end);
    if (not ok_ctx or ctx == nil) then
        accessxi.prism_note_error('init failed: ' .. tostring(ctx));
        accessxi.prism_reset_speech();
        return false;
    end
    speech.ctx = ctx;

    local ok_backend, backend = pcall(function () return speech.prism.prism_registry_create_best(speech.ctx); end);
    if (not ok_backend or backend == nil) then
        accessxi.prism_note_error('no available backend: ' .. tostring(backend));
        accessxi.prism_reset_speech();
        return false;
    end
    speech.backend = backend;

    local ok_name, name = pcall(function ()
        local ptr = speech.prism.prism_backend_name(speech.backend);
        if (ptr ~= nil) then
            return ffi.string(ptr);
        end
        return '';
    end);
    speech.backend_name = (ok_name and name ~= nil and name ~= '') and name or 'unknown';
    accessxi.prism_last_error = '';
    accessxi.prism_retry_after = 0;
    log_line('speech prism backend=' .. speech.backend_name);
    return true;
end

function accessxi.load_searchhook()
    if (accessxi.searchhook == nil) then
        local ok, lib = pcall(ffi.load, accessxi.searchhook_dll_path);
        if (not ok or lib == nil) then
            accessxi.searchhook_last_error = tostring(lib);
            log_line(('searchhook load failed error="%s"'):fmt(accessxi.escape_probe_log_text(accessxi.searchhook_last_error)));
            return false, 0;
        end
        accessxi.searchhook = lib;
    end

    local ran, result = pcall(function ()
        return accessxi.searchhook.accessxi_searchhook_init();
    end);
    if (not ran) then
        accessxi.searchhook_last_error = tostring(result);
        log_line(('searchhook init failed error="%s"'):fmt(accessxi.escape_probe_log_text(accessxi.searchhook_last_error)));
        return false, 0;
    end

    local dumps = 0;
    pcall(function ()
        dumps = tonumber(accessxi.searchhook.accessxi_searchhook_dump_count()) or 0;
    end);
    log_line(('searchhook init result=%d dumps=%d'):fmt(tonumber(result) or -1, dumps));
    return (tonumber(result) or 0) > 0, dumps;
end

function accessxi.unload_searchhook()
    if (accessxi.searchhook == nil) then
        return;
    end

    local ran, result = pcall(function ()
        return accessxi.searchhook.accessxi_searchhook_shutdown();
    end);
    if (not ran) then
        log_line(('searchhook shutdown failed error="%s"'):fmt(accessxi.escape_probe_log_text(result)));
    else
        log_line(('searchhook shutdown result=%d'):fmt(tonumber(result) or -1));
    end
end

function accessxi.speech_output_text(text)
    text = tostring(text or ''):gsub('%z.*$', '');
    local out = T{};
    local last_space = false;
    for i = 1, #text do
        local b = text:byte(i) or 0;
        if (b >= 32 and b <= 126) then
            out:append(string.char(b));
            last_space = (b == 32);
        elseif (b == 9 or b == 10 or b == 13) then
            if (not last_space) then
                out:append(' ');
                last_space = true;
            end
        elseif (not last_space) then
            out:append(' ');
            last_space = true;
        end
    end
    local normalized = out:concat(''):gsub('%s+', ' '):trim();
    normalized = (' ' .. normalized .. ' ')
        :gsub('([^%w])FoV([^%w])', '%1F O V%2')
        :gsub('([^%w])GoV([^%w])', '%1G O V%2')
        :sub(2, -2);
    normalized = normalized:gsub('%.%s*%.+', '.');
    return normalized;
end

local function speak(text, cancel)
    text = accessxi.speech_output_text(text);
    if (text == nil or text == '') then
        return 'empty';
    end

    if (accessxi.prism_init_speech(false)) then
        local ok_speak, result_speak = pcall(function ()
            return speech.prism.prism_backend_output(speech.backend, text, cancel ~= false);
        end);
        if (ok_speak and tonumber(result_speak) == 0) then
            return ('prism backend=%s output=0'):fmt(speech.backend_name ~= '' and speech.backend_name or 'unknown');
        end

        local error_text = ok_speak and accessxi.prism_error_text(result_speak) or tostring(result_speak);
        accessxi.prism_note_error(('backend=%s output=%s'):fmt(speech.backend_name ~= '' and speech.backend_name or 'unknown', error_text));
        accessxi.prism_reset_speech();

        if (accessxi.prism_init_speech(true)) then
            local ok_retry, result_retry = pcall(function ()
                return speech.prism.prism_backend_output(speech.backend, text, cancel ~= false);
            end);
            if (ok_retry and tonumber(result_retry) == 0) then
                return ('prism-retry backend=%s output=0'):fmt(speech.backend_name ~= '' and speech.backend_name or 'unknown');
            end
            local retry_text = ok_retry and accessxi.prism_error_text(result_retry) or tostring(result_retry);
            accessxi.prism_note_error(('retry backend=%s output=%s'):fmt(speech.backend_name ~= '' and speech.backend_name or 'unknown', retry_text));
            accessxi.prism_reset_speech();
        end
    end

    print('[AccessXI] ' .. text);
    return 'print prism-unavailable';
end

local function get_menu_obj(ptr, t)
    if (ptr == nil or ptr == 0) then
        return nil;
    end
    ptr = ashita.memory.read_uint32(ptr);
    if (ptr == 0) then
        return nil;
    end
    ptr = ashita.memory.read_uint32(ptr);
    if (ptr == 0) then
        return nil;
    end
    return ffi.cast(t .. '*', ptr);
end

local function get_menu_name()
    local ptr = AshitaCore:GetPointerManager():Get('menu');
    if (ptr == 0) then
        return nil;
    end
    ptr = ashita.memory.read_uint32(ptr);
    if (ptr == 0) then
        return nil;
    end
    ptr = ashita.memory.read_uint32(ptr);
    if (ptr == 0) then
        return nil;
    end
    ptr = ashita.memory.read_uint32(ptr + 0x04);
    if (ptr == 0) then
        return nil;
    end
    return ashita.memory.read_string(ptr + 0x46, 16):trim();
end

local function get_current_menu_object_ptr()
    local ptr = AshitaCore:GetPointerManager():Get('menu');
    if (ptr == 0) then
        return 0;
    end

    ptr = ashita.memory.read_uint32(ptr);
    if (ptr == 0) then
        return 0;
    end

    ptr = ashita.memory.read_uint32(ptr);
    if (ptr == 0) then
        return 0;
    end

    return ptr;
end

local function read_i32(addr)
    if (addr == nil or addr == 0) then
        return nil;
    end

    local ok, value = pcall(ashita.memory.read_int32, addr);
    if (not ok) then
        return nil;
    end
    return value;
end

local function read_u32(addr)
    if (addr == nil or addr == 0) then
        return nil;
    end

    local ok, value = pcall(ashita.memory.read_uint32, addr);
    if (not ok) then
        return nil;
    end
    return tonumber(value);
end

local function read_u16(addr)
    if (addr == nil or addr == 0) then
        return nil;
    end

    local ok, value = pcall(ashita.memory.read_uint16, addr);
    if (not ok) then
        return nil;
    end
    return tonumber(value);
end

local function read_u8(addr)
    if (addr == nil or addr == 0) then
        return nil;
    end

    local ok, value = pcall(ashita.memory.read_uint8, addr);
    if (not ok) then
        return nil;
    end
    return tonumber(value);
end

local function safe_call(fn, default)
    local ok, value = pcall(fn);
    if (not ok or value == nil) then
        return default;
    end
    return value;
end

local function get_ffximain_base()
    local handle = safe_call(function () return kernel32.GetModuleHandleA('FFXiMain.dll'); end, nil);
    if (handle == nil) then
        return 0;
    end

    local value = tonumber(ffi.cast('uintptr_t', handle)) or 0;
    return value;
end

local function clean_probe_text(text)
    if (text == nil) then
        return '';
    end

    text = tostring(text):gsub('%z.*$', ''):gsub('[%c]', ''):trim();
    return text;
end

local function read_probe_string(ptr, length)
    ptr = tonumber(ptr) or 0;
    if (ptr < 0x10000) then
        return '';
    end

    length = tonumber(length) or 96;
    if (length < 1 or length > 512) then
        length = 96;
    end

    local ok, text = pcall(ashita.memory.read_string, ptr, length);
    if (not ok) then
        return '';
    end
    return clean_probe_text(text);
end

function accessxi.is_probe_pointer(ptr)
    ptr = tonumber(ptr) or 0;
    return ptr >= 0x01000000 and ptr < 0x7FFF0000;
end

function accessxi.probe_strings_at(ptr)
    ptr = tonumber(ptr) or 0;
    if (not accessxi.is_probe_pointer(ptr)) then
        return '';
    end

    local parts = T{};
    for _, off in ipairs(T{ 0x00, 0x04, 0x08, 0x0C, 0x10, 0x14, 0x18, 0x20, 0x24, 0x28, 0x30, 0x40, 0x46, 0x50, 0x60, 0x80 }) do
        local text = read_probe_string(ptr + off);
        if (text ~= '') then
            if (#parts < 10) then
                parts:append(('+%02X="%s"'):fmt(off, text));
            end
        end
    end

    return parts:concat(' ');
end

function accessxi.memory_page_readable(protect)
    protect = tonumber(protect) or 0;
    if (bit.band(protect, 0x100) ~= 0 or bit.band(protect, 0x01) ~= 0) then
        return false;
    end

    local page = bit.band(protect, 0xFF);
    return page == 0x02
        or page == 0x04
        or page == 0x08
        or page == 0x20
        or page == 0x40
        or page == 0x80;
end

function accessxi.memory_page_executable(protect)
    protect = tonumber(protect) or 0;
    local page = bit.band(protect, 0xFF);
    return page == 0x10
        or page == 0x20
        or page == 0x40
        or page == 0x80;
end

function accessxi.memory_page_search_scan_allowed(base, protect)
    base = tonumber(base) or 0;
    if (base < 0x01000000) then
        return false;
    end
    if (accessxi.memory_page_executable(protect)) then
        return false;
    end
    return accessxi.memory_page_readable(protect);
end

function accessxi.live_ixff_scan_allowed(base, protect)
    base = tonumber(base) or 0;
    if (base < 0x01000000 or base >= 0x7FFF0000) then
        return false;
    end
    return accessxi.memory_page_readable(protect);
end

function accessxi.live_ixff_pointer_probe(ptr)
    ptr = tonumber(ptr) or 0;
    if (not accessxi.is_probe_pointer(ptr)) then
        return '';
    end

    local parts = T{};
    for off = -0x10, 0x40, 4 do
        local value = read_u32(ptr + off) or 0;
        if (value ~= 0 and (accessxi.is_probe_pointer(value) or value == 0x46465849)) then
            parts:append(('%+03X=0x%08X'):fmt(off, value));
        end
    end
    return parts:concat(' ');
end

function accessxi.live_ixff_packet_shape(blob, pos)
    blob = tostring(blob or '');
    pos = tonumber(pos) or 0;
    if (pos < 5 or (pos + 3) > #blob) then
        return false, 0;
    end

    local b0 = blob:byte(pos - 4) or 0;
    local b1 = blob:byte(pos - 3) or 0;
    local r0 = blob:byte(pos - 2) or 0;
    local r1 = blob:byte(pos - 1) or 0;
    local length = b0 + (b1 * 256);
    if (r0 ~= 0 or r1 ~= 0) then
        return false, length;
    end
    if (length < 0x40 or length > 0x2000) then
        return false, length;
    end
    if ((pos - 4 + length - 1) > #blob) then
        return false, length;
    end
    return true, length;
end

function accessxi.live_ixff_skip_text_hit(ascii)
    ascii = tostring(ascii or ''):lower();
    if (ascii:find('search ixff', 1, true) ~= nil
        or ascii:find('searchmem', 1, true) ~= nil
        or ascii:find('menu    scresult', 1, true) ~= nil
        or ascii:find('error written', 1, true) ~= nil
        or ascii:find('scan written', 1, true) ~= nil) then
        return true;
    end
    return false;
end

function accessxi.log_live_ixff_scan(reason)
    local started = tick();
    local max_ms = 1100;
    local max_bytes = 80 * 1024 * 1024;
    local chunk_size = 0x20000;
    local overlap = 8;
    local max_hits = 48;
    local process = kernel32.GetCurrentProcess();
    local mbi = ffi.new('MEMORY_BASIC_INFORMATION[1]');
    local mbi_size = ffi.sizeof('MEMORY_BASIC_INFORMATION');
    local buffer = ffi.new('char[?]', chunk_size);
    local bytes_read = ffi.new('SIZE_T[1]');
    local needle = 'IXFF';
    local hits = 0;
    local packet_hits = 0;
    local non_packet_hits = 0;
    local max_non_packet_hits = 12;
    local skipped_text = 0;
    local regions = 0;
    local readable = 0;
    local scanned = 0;
    local timed_out = false;
    local addr = 0x01000000;

    log_line(('searchixff begin reason="%s"'):fmt(accessxi.escape_probe_log_text(reason or '')));
    while (addr < 0x7FFF0000 and scanned < max_bytes and hits < max_hits) do
        if ((tick() - started) > max_ms) then
            timed_out = true;
            break;
        end

        local ok, result = pcall(function ()
            return kernel32.VirtualQuery(ffi.cast('const void*', addr), mbi, mbi_size);
        end);
        local queried = ok and tonumber(result) or 0;
        if (queried == 0) then
            addr = addr + 0x10000;
        else
            local base = tonumber(ffi.cast('uintptr_t', mbi[0].BaseAddress)) or addr;
            local size = tonumber(mbi[0].RegionSize) or 0;
            local state = tonumber(mbi[0].State) or 0;
            local protect = tonumber(mbi[0].Protect) or 0;
            local next_addr = base + math.max(size, 0x1000);
            regions = regions + 1;

            if (size > 0 and state == 0x1000 and accessxi.live_ixff_scan_allowed(base, protect)) then
                readable = readable + 1;
                local region_offset = 0;
                local carry = '';
                while (region_offset < size and scanned < max_bytes and hits < max_hits) do
                    if ((tick() - started) > max_ms) then
                        timed_out = true;
                        break;
                    end

                    local want = math.min(chunk_size, size - region_offset, max_bytes - scanned);
                    if (want <= 0) then
                        break;
                    end

                    local chunk_addr = base + region_offset;
                    bytes_read[0] = 0;
                    local read_ok = kernel32.ReadProcessMemory(process, ffi.cast('const void*', chunk_addr), buffer, want, bytes_read) ~= 0;
                    local got = tonumber(bytes_read[0]) or 0;
                    if (read_ok and got > 0) then
                        local blob = carry .. ffi.string(buffer, got);
                        scanned = scanned + got;
                        local start_at = 1;
                        while (hits < max_hits) do
                            local pos = blob:find(needle, start_at, true);
                            if (pos == nil) then
                                break;
                            end

                            local absolute = chunk_addr + pos - #carry - 1;
                            local context_start = math.max(1, pos - 24);
                            local context_end = math.min(#blob, pos + 72);
                            local context = blob:sub(context_start, context_end);
                            local around = accessxi.packet_hex_limit(context, 96);
                            local ascii = accessxi.packet_ascii_preview(context, 96);
                            local packet_like, frame_length = accessxi.live_ixff_packet_shape(blob, pos);
                            if ((not packet_like)
                                and (accessxi.live_ixff_skip_text_hit(ascii) or non_packet_hits >= max_non_packet_hits)) then
                                skipped_text = skipped_text + 1;
                                start_at = pos + 1;
                            else
                                if (packet_like) then
                                    packet_hits = packet_hits + 1;
                                else
                                    non_packet_hits = non_packet_hits + 1;
                                end
                                local ptrs = accessxi.live_ixff_pointer_probe(absolute);
                                hits = hits + 1;
                                log_line(('searchixff hit index=%d packet=%s frameLen=%d addr=0x%08X region=0x%08X protect=0x%X exec=%s ptrs="%s" ascii="%s" hex="%s"'):fmt(
                                    hits,
                                    tostring(packet_like),
                                    frame_length,
                                    absolute,
                                    base,
                                    protect,
                                    tostring(accessxi.memory_page_executable(protect)),
                                    accessxi.escape_probe_log_text(ptrs),
                                    accessxi.escape_probe_log_text(ascii),
                                    around));
                                start_at = pos + 1;
                            end
                        end
                        carry = blob:sub(math.max(1, #blob - overlap + 1));
                    end

                    if (want <= overlap) then
                        region_offset = region_offset + want;
                    else
                        region_offset = region_offset + want - overlap;
                    end
                end
            end

            addr = next_addr;
        end
    end

    log_line(('searchixff end hits=%d packetHits=%d nonPacketHits=%d skippedText=%d regions=%d readable=%d scanned=%d timedOut=%s'):fmt(
        hits,
        packet_hits,
        non_packet_hits,
        skipped_text,
        regions,
        readable,
        scanned,
        tostring(timed_out)));
    return hits;
end

function accessxi.scan_context_text(bytes)
    bytes = tostring(bytes or ''):gsub('%z', '.');
    bytes = bytes:gsub('[\r\n\t]+', ' '):gsub('[%c]', ' ');
    bytes = bytes:gsub('"', "'");
    bytes = bytes:gsub('%s+', ' '):trim();
    if (#bytes > 120) then
        bytes = bytes:sub(1, 120);
    end
    return bytes;
end

function accessxi.utf16le_pattern(text)
    text = tostring(text or '');
    local out = {};
    for i = 1, #text do
        out[#out + 1] = string.char(text:byte(i));
        out[#out + 1] = string.char(0);
    end
    return table.concat(out);
end

function accessxi.add_unique_scan_term(terms, seen, term)
    term = accessxi.survival_guide_text(term or '');
    if (#term < 3) then
        return;
    end

    local key = term:lower();
    if (seen[key] == true) then
        return;
    end

    seen[key] = true;
    terms:append(term);
end

function accessxi.sgscan_source_for_context(context)
    local lower_context = tostring(context or ''):lower();
    if (lower_context:find('sgscan begin', 1, true) ~= nil
        or lower_context:find('sgscan hit', 1, true) ~= nil
        or lower_context:find('ascii:', 1, true) ~= nil
        or lower_context:find('utf16le:', 1, true) ~= nil
        or lower_context:find('terms=', 1, true) ~= nil
        or lower_context:find('movement|pcs and npcs', 1, true) ~= nil
        or lower_context:find('selectedcandidate', 1, true) ~= nil
        or lower_context:find('candidates=', 1, true) ~= nil
        or lower_context:find('source=candidate ctx', 1, true) ~= nil
        or lower_context:find('memory_basic_information', 1, true) ~= nil
        or lower_context:find('accessxi_reader', 1, true) ~= nil
        or lower_context:find('c:\\users\\', 1, true) ~= nil
        or lower_context:find('addons\\', 1, true) ~= nil
        or lower_context:find('ffximain.dll', 1, true) ~= nil
        or lower_context:find('getmodulehandlea', 1, true) ~= nil
        or lower_context:find('nav_', 1, true) ~= nil
        or lower_context:find('navpositiont', 1, true) ~= nil
        or lower_context:find('accessxi', 1, true) ~= nil
        or lower_context:find('survival_guide_', 1, true) ~= nil
        or lower_context:find('function ', 1, true) ~= nil
        or lower_context:find('label =', 1, true) ~= nil
        or lower_context:find("label='%s'", 1, true) ~= nil
        or lower_context:find('menuid=%d', 1, true) ~= nil
        or lower_context:find('waiting for survival guide menu packet', 1, true) ~= nil) then
        return 'self-suspect';
    end
    return 'candidate';
end

function accessxi.ascii_runs_from_blob(blob, limit)
    blob = tostring(blob or '');
    limit = tonumber(limit) or 24;

    local runs = T{};
    local run = {};
    for i = 1, #blob do
        local b = blob:byte(i);
        if (b >= 32 and b <= 126) then
            run[#run + 1] = string.char(b);
        else
            if (#run >= 4) then
                local text = table.concat(run):gsub('"', "'"):gsub('%s+', ' '):trim();
                if (text ~= '' and text:find('sgscan ', 1, true) == nil and text:find('ascii:', 1, true) == nil) then
                    runs:append(text);
                    if (runs:len() >= limit) then
                        return runs;
                    end
                end
            end
            run = {};
        end
    end

    if (#run >= 4 and runs:len() < limit) then
        local text = table.concat(run):gsub('"', "'"):gsub('%s+', ' '):trim();
        if (text ~= '' and text:find('sgscan ', 1, true) == nil and text:find('ascii:', 1, true) == nil) then
            runs:append(text);
        end
    end

    return runs;
end

function accessxi.survival_guide_memory_scan_terms(extra_terms)
    local terms = T{};
    local seen = {};

    extra_terms = accessxi.survival_guide_text(extra_terms or '');
    if (extra_terms ~= '') then
        for term in extra_terms:gmatch('[^|]+') do
            accessxi.add_unique_scan_term(terms, seen, term);
        end
    end

    return terms;
end

function accessxi.adventuring_primer_guide01_find_terms()
    local function s(bytes)
        local chars = T{};
        for _, b in ipairs(bytes) do
            chars:append(string.char(b));
        end
        return chars:concat('');
    end

    return T{
        s(T{ 77, 111, 118, 101, 109, 101, 110, 116 }),
        s(T{ 80, 67, 115, 32, 97, 110, 100, 32, 78, 80, 67, 115 }),
        s(T{ 84, 97, 114, 103, 101, 116, 105, 110, 103 }),
        s(T{ 65, 99, 116, 105, 111, 110, 32, 67, 111, 109, 109, 97, 110, 100, 115 }),
        s(T{ 67, 104, 97, 116, 116, 105, 110, 103 }),
        s(T{ 67, 97, 109, 101, 114, 97 }),
        s(T{ 76, 111, 103, 32, 87, 105, 110, 100, 111, 119, 115 }),
        s(T{ 83, 99, 114, 101, 101, 110, 115, 104, 111, 116, 115 }),
    }:concat('|');
end

function accessxi.log_survival_guide_memory_scan(seq, reason, extra_terms)
    seq = tonumber(seq) or 0;

    local terms = accessxi.survival_guide_memory_scan_terms(extra_terms);
    if (terms:len() == 0) then
        log_line(('sgscan seq=%d reason=%s skipped no terms'):fmt(seq, tostring(reason or '')));
        return 0;
    end

    local patterns = T{};
    for _, term in ipairs(terms) do
        patterns:append(T{ term = term, enc = 'ascii', bytes = term });
        patterns:append(T{ term = term, enc = 'utf16le', bytes = accessxi.utf16le_pattern(term) });
    end

    local mbi = ffi.new('MEMORY_BASIC_INFORMATION[1]');
    local mbi_size = ffi.sizeof('MEMORY_BASIC_INFORMATION');
    local addr = 0x10000;
    local stop_addr = 0x7FFF0000;
    local max_ms = 650;
    local max_bytes = 96 * 1024 * 1024;
    local max_regions = 2048;
    local max_hits = 80;
    local chunk_size = 256 * 1024;
    local process = kernel32.GetCurrentProcess();
    local buffer = ffi.new('char[?]', chunk_size);
    local bytes_read = ffi.new('SIZE_T[1]');
    local started = tick();
    local scanned_bytes = 0;
    local regions = 0;
    local readable_regions = 0;
    local hits = 0;
    local timed_out = false;
    local hit_keys = {};

    log_line(('sgscan begin seq=%d reason=%s terms="%s"'):fmt(seq, tostring(reason or ''), terms:concat('|')));

    while (addr < stop_addr and regions < max_regions and scanned_bytes < max_bytes and hits < max_hits) do
        if ((tick() - started) > max_ms) then
            timed_out = true;
            break;
        end

        local ok, result = pcall(function ()
            return kernel32.VirtualQuery(ffi.cast('const void*', addr), mbi, mbi_size);
        end);
        local queried = ok and tonumber(result) or 0;
        if (queried == 0) then
            addr = addr + 0x10000;
        else
            local base = tonumber(ffi.cast('uintptr_t', mbi[0].BaseAddress)) or addr;
            local size = tonumber(mbi[0].RegionSize) or 0;
            local state = tonumber(mbi[0].State) or 0;
            local protect = tonumber(mbi[0].Protect) or 0;
            local mem_type = tonumber(mbi[0].Type) or 0;
            local next_addr = base + math.max(size, 0x1000);
            regions = regions + 1;

            if (size > 0 and state == 0x1000 and accessxi.memory_page_readable(protect)) then
                readable_regions = readable_regions + 1;

                local region_offset = 0;
                while (region_offset < size and scanned_bytes < max_bytes and hits < max_hits) do
                    if ((tick() - started) > max_ms) then
                        timed_out = true;
                        break;
                    end

                    local want = math.min(chunk_size, size - region_offset, max_bytes - scanned_bytes);
                    local chunk_addr = base + region_offset;
                    bytes_read[0] = 0;
                    local read_ok = kernel32.ReadProcessMemory(process, ffi.cast('const void*', chunk_addr), buffer, want, bytes_read) ~= 0;
                    local got = tonumber(bytes_read[0]) or 0;

                    if (read_ok and got > 0) then
                        local blob = ffi.string(buffer, got);
                        scanned_bytes = scanned_bytes + got;
                        for _, pattern in ipairs(patterns) do
                            local start_at = 1;
                            local term_hits = 0;
                            while (term_hits < 4 and hits < max_hits) do
                                local found = blob:find(pattern.bytes, start_at, true);
                                if (found == nil) then
                                    break;
                                end

                                local absolute = chunk_addr + found - 1;
                                local key = ('%s:%s:%08X'):fmt(pattern.enc, pattern.term, absolute);
                                if (hit_keys[key] ~= true) then
                                    hit_keys[key] = true;
                                    local context_start = math.max(1, found - 48);
                                    local context_end = math.min(#blob, found + #pattern.bytes + 48);
                                    local context = accessxi.scan_context_text(blob:sub(context_start, context_end));
                                    local source = accessxi.sgscan_source_for_context(context);
                                    hits = hits + 1;
                                    term_hits = term_hits + 1;
                                    log_line(('sgscan hit seq=%d term="%s" enc=%s addr=0x%08X region=0x%08X protect=0x%X type=0x%X source=%s ctx="%s"'):fmt(
                                        seq,
                                        pattern.term:gsub('"', "'"),
                                        pattern.enc,
                                        absolute,
                                        base,
                                        protect,
                                        mem_type,
                                        source,
                                        context));
                                    if (source == 'candidate') then
                                        local nearby_start = math.max(1, found - 384);
                                        local nearby_end = math.min(#blob, found + #pattern.bytes + 384);
                                        local runs = accessxi.ascii_runs_from_blob(blob:sub(nearby_start, nearby_end), 28);
                                        if (runs:len() > 0) then
                                            log_line(('sgscan strings seq=%d addr=0x%08X strings="%s"'):fmt(seq, absolute, runs:concat('|')));
                                        end
                                    end
                                end

                                start_at = found + 1;
                            end
                        end
                    else
                        scanned_bytes = scanned_bytes + want;
                    end

                    region_offset = region_offset + want;
                end
            end

            if (next_addr <= addr) then
                addr = addr + 0x1000;
            else
                addr = next_addr;
            end
        end
    end

    log_line(('sgscan end seq=%d regions=%d readable=%d scanned=%d hits=%d timeout=%s'):fmt(
        seq,
        regions,
        readable_regions,
        scanned_bytes,
        hits,
        tostring(timed_out)));
    return hits;
end

function accessxi.address_in_range(addr, base, length)
    addr = tonumber(addr) or 0;
    base = tonumber(base) or 0;
    length = tonumber(length) or 0;
    return base > 0 and length > 0 and addr >= base and addr < (base + length);
end

function accessxi.chat_log_visible_scan_terms(ptr, length, limit)
    ptr = tonumber(ptr) or 0;
    local terms = T{};
    local seen = {};
    if (not accessxi.is_probe_pointer(ptr)) then
        return terms;
    end

    length = tonumber(length) or 0x1000;
    limit = tonumber(limit) or 10;
    local off = 0;
    while (off < length and terms:len() < limit) do
        local marker_len = accessxi.chat_log_probe_timestamp_marker_len(ptr + off);
        if (marker_len > 0) then
            local raw = accessxi.chat_log_ascii_text_from_ptr(ptr + off, accessxi.chat_log_max_line_len);
            local text = accessxi.chat_log_speech_text(raw);
            if (#text >= 8 and text:find('%a') ~= nil) then
                accessxi.add_unique_scan_term(terms, seen, text);
            end
            off = off + marker_len;
        else
            off = off + 1;
        end
    end

    return terms;
end

function accessxi.chat_log_scan_source_for_hit(context, absolute, render_ranges)
    absolute = tonumber(absolute) or 0;
    if (type(render_ranges) == 'table') then
        for _, range in ipairs(render_ranges) do
            if (accessxi.address_in_range(absolute, range.base, range.length)) then
                return range.name or 'render';
            end
        end
    end

    local source = accessxi.sgscan_source_for_context(context);
    if (source == 'self-suspect') then
        return source;
    end

    local lower_context = tostring(context or ''):lower();
    if (lower_context:find('accessxi', 1, true) ~= nil
        or lower_context:find('chatbufscan', 1, true) ~= nil
        or lower_context:find('can hit seq=', 1, true) ~= nil
        or lower_context:find('/axi ', 1, true) ~= nil
        or lower_context:find('state chatlog', 1, true) ~= nil
        or lower_context:find('chat text mode=', 1, true) ~= nil
        or lower_context:find('2026-', 1, true) ~= nil) then
        return 'self-suspect';
    end

    if (lower_context:find('menu    fulllog', 1, true) ~= nil
        or lower_context:find('menu    inline', 1, true) ~= nil) then
        return 'menu-structure';
    end

    if (context:find('Q[', 1, true) ~= nil
        or context:find('q[', 1, true) ~= nil
        or context:find('[%d%d:%d%d:%d%d]') ~= nil) then
        return 'ffxi-chat-record';
    end

    return 'candidate';
end

function accessxi.u32_pattern(value)
    value = tonumber(value) or 0;
    return string.char(
        bit.band(value, 0xFF),
        bit.band(bit.rshift(value, 8), 0xFF),
        bit.band(bit.rshift(value, 16), 0xFF),
        bit.band(bit.rshift(value, 24), 0xFF));
end

function accessxi.is_scan_address(address)
    address = tonumber(address) or 0;
    return address >= 0x00010000 and address < 0x7FFF0000;
end

function accessxi.log_chat_log_pointer_scan(seq, reason, address)
    seq = tonumber(seq) or 0;
    address = tonumber(address) or 0;
    if (not accessxi.is_scan_address(address)) then
        log_line(('chatptrscan seq=%d reason=%s skipped invalid address=0x%08X'):fmt(seq, tostring(reason or ''), address));
        return 0;
    end

    local targets = T{};
    local seen_targets = {};
    for _, delta in ipairs(T{ 0, -4, -8, -0x10, -0x20, -0x30, -0x40, 4, 8, 0x10, 0x20, 0x40 }) do
        local target = address + delta;
        if (accessxi.is_scan_address(target) and seen_targets[target] ~= true) then
            seen_targets[target] = true;
            targets:append(T{ addr = target, delta = delta, bytes = accessxi.u32_pattern(target) });
        end
    end

    log_line(('chatptrscan begin seq=%d reason=%s address=0x%08X targets="%s" aroundBytes=%s aroundDwords=%s'):fmt(
        seq,
        tostring(reason or ''),
        address,
        (function ()
            local parts = T{};
            for _, target in ipairs(targets) do
                parts:append(('0x%08X(%+d)'):fmt(target.addr, target.delta));
            end
            return parts:concat('|');
        end)(),
        accessxi.format_probe_bytes(address - 0x80, 0, 0x180),
        accessxi.format_probe_dwords(address - 0x80, 0, 48)));

    local mbi = ffi.new('MEMORY_BASIC_INFORMATION[1]');
    local mbi_size = ffi.sizeof('MEMORY_BASIC_INFORMATION');
    local addr = 0x10000;
    local stop_addr = 0x7FFF0000;
    local max_ms = 900;
    local max_bytes = 128 * 1024 * 1024;
    local max_regions = 2048;
    local max_hits = 80;
    local chunk_size = 256 * 1024;
    local process = kernel32.GetCurrentProcess();
    local buffer = ffi.new('char[?]', chunk_size);
    local bytes_read = ffi.new('SIZE_T[1]');
    local started = tick();
    local scanned_bytes = 0;
    local regions = 0;
    local readable_regions = 0;
    local hits = 0;
    local timed_out = false;
    local hit_keys = {};

    while (addr < stop_addr and regions < max_regions and scanned_bytes < max_bytes and hits < max_hits) do
        if ((tick() - started) > max_ms) then
            timed_out = true;
            break;
        end

        local ok, result = pcall(function ()
            return kernel32.VirtualQuery(ffi.cast('const void*', addr), mbi, mbi_size);
        end);
        local queried = ok and tonumber(result) or 0;
        if (queried == 0) then
            addr = addr + 0x10000;
        else
            local base = tonumber(ffi.cast('uintptr_t', mbi[0].BaseAddress)) or addr;
            local size = tonumber(mbi[0].RegionSize) or 0;
            local state = tonumber(mbi[0].State) or 0;
            local protect = tonumber(mbi[0].Protect) or 0;
            local mem_type = tonumber(mbi[0].Type) or 0;
            local next_addr = base + math.max(size, 0x1000);
            regions = regions + 1;

            if (size > 0 and state == 0x1000 and accessxi.memory_page_readable(protect)) then
                readable_regions = readable_regions + 1;
                local region_offset = 0;
                while (region_offset < size and scanned_bytes < max_bytes and hits < max_hits) do
                    if ((tick() - started) > max_ms) then
                        timed_out = true;
                        break;
                    end

                    local want = math.min(chunk_size, size - region_offset, max_bytes - scanned_bytes);
                    local chunk_addr = base + region_offset;
                    bytes_read[0] = 0;
                    local read_ok = kernel32.ReadProcessMemory(process, ffi.cast('const void*', chunk_addr), buffer, want, bytes_read) ~= 0;
                    local got = tonumber(bytes_read[0]) or 0;

                    if (read_ok and got > 0) then
                        local blob = ffi.string(buffer, got);
                        scanned_bytes = scanned_bytes + got;
                        for _, target in ipairs(targets) do
                            local start_at = 1;
                            local target_hits = 0;
                            while (target_hits < 8 and hits < max_hits) do
                                local found = blob:find(target.bytes, start_at, true);
                                if (found == nil) then
                                    break;
                                end

                                local absolute = chunk_addr + found - 1;
                                local key = ('%08X:%08X'):fmt(target.addr, absolute);
                                if (hit_keys[key] ~= true) then
                                    hit_keys[key] = true;
                                    hits = hits + 1;
                                    target_hits = target_hits + 1;
                                    local context_start = math.max(1, found - 64);
                                    local context_end = math.min(#blob, found + 96);
                                    local context = accessxi.scan_context_text(blob:sub(context_start, context_end));
                                    local nearby = absolute - 0x40;
                                    log_line(('chatptrscan hit seq=%d target=0x%08X delta=%+d ref=0x%08X region=0x%08X protect=0x%X type=0x%X ctx="%s" bytes=%s dwords=%s'):fmt(
                                        seq,
                                        target.addr,
                                        target.delta,
                                        absolute,
                                        base,
                                        protect,
                                        mem_type,
                                        context,
                                        accessxi.format_probe_bytes(nearby, 0, 0xC0),
                                        accessxi.format_probe_dwords(nearby, 0, 32)));
                                end

                                start_at = found + 1;
                            end
                        end
                    else
                        scanned_bytes = scanned_bytes + want;
                    end

                    region_offset = region_offset + want;
                end
            end

            if (next_addr <= addr) then
                addr = addr + 0x1000;
            else
                addr = next_addr;
            end
        end
    end

    log_line(('chatptrscan end seq=%d regions=%d readable=%d scanned=%d hits=%d timeout=%s'):fmt(
        seq,
        regions,
        readable_regions,
        scanned_bytes,
        hits,
        tostring(timed_out)));
    return hits;
end

function accessxi.blob_timestamp_marker_len(blob, pos)
    blob = tostring(blob or '');
    pos = tonumber(pos) or 0;
    if (pos < 1 or pos > #blob or blob:byte(pos) ~= 0x5B) then
        return 0;
    end

    local function digit_at(index)
        local value = blob:byte(index);
        return value ~= nil and value >= 0x30 and value <= 0x39;
    end

    local b2 = blob:byte(pos + 2);
    if (digit_at(pos + 1) and b2 == 0x3A and digit_at(pos + 3) and digit_at(pos + 4)) then
        if (blob:byte(pos + 5) == 0x3A and digit_at(pos + 6) and digit_at(pos + 7) and blob:byte(pos + 8) == 0x5D) then
            return 9;
        end
        if (blob:byte(pos + 5) == 0x5D) then
            return 6;
        end
    end

    if (digit_at(pos + 1) and digit_at(pos + 2) and blob:byte(pos + 3) == 0x3A and digit_at(pos + 4) and digit_at(pos + 5)) then
        if (blob:byte(pos + 6) == 0x3A and digit_at(pos + 7) and digit_at(pos + 8) and blob:byte(pos + 9) == 0x5D) then
            return 10;
        end
        if (blob:byte(pos + 6) == 0x5D) then
            return 7;
        end
    end

    return 0;
end

function accessxi.blob_printable_run_around(blob, pos)
    blob = tostring(blob or '');
    pos = tonumber(pos) or 0;
    if (pos < 1 or pos > #blob) then
        return nil;
    end

    local function printable(index)
        local value = blob:byte(index);
        return value ~= nil and value >= 32 and value <= 126;
    end

    if (not printable(pos)) then
        return nil;
    end

    local first = pos;
    while (first > 1 and printable(first - 1)) do
        first = first - 1;
    end

    local last = pos;
    while (last < #blob and printable(last + 1)) do
        last = last + 1;
    end

    local text = blob:sub(first, last):gsub('"', "'"):gsub('%s+', ' '):trim();
    if (text == '') then
        return nil;
    end

    return T{ first = first, last = last, text = text };
end

function accessxi.log_chat_log_record_scan(seq, reason, address)
    seq = tonumber(seq) or 0;
    address = tonumber(address) or 0;
    if (not accessxi.is_scan_address(address)) then
        log_line(('chatrecscan seq=%d reason=%s skipped invalid address=0x%08X'):fmt(seq, tostring(reason or ''), address));
        return 0;
    end

    local mbi = ffi.new('MEMORY_BASIC_INFORMATION[1]');
    local mbi_size = ffi.sizeof('MEMORY_BASIC_INFORMATION');
    local queried = kernel32.VirtualQuery(ffi.cast('const void*', address), mbi, mbi_size);
    if (tonumber(queried) == 0) then
        log_line(('chatrecscan seq=%d reason=%s skipped no region address=0x%08X'):fmt(seq, tostring(reason or ''), address));
        return 0;
    end

    local base = tonumber(ffi.cast('uintptr_t', mbi[0].BaseAddress)) or 0;
    local size = tonumber(mbi[0].RegionSize) or 0;
    local state = tonumber(mbi[0].State) or 0;
    local protect = tonumber(mbi[0].Protect) or 0;
    local mem_type = tonumber(mbi[0].Type) or 0;
    if (base == 0 or size <= 0 or state ~= 0x1000 or not accessxi.memory_page_readable(protect)) then
        log_line(('chatrecscan seq=%d reason=%s skipped unreadable address=0x%08X region=0x%08X size=0x%X state=0x%X protect=0x%X type=0x%X'):fmt(
            seq,
            tostring(reason or ''),
            address,
            base,
            size,
            state,
            protect,
            mem_type));
        return 0;
    end

    local window_start = math.max(base, address - 0x8000);
    local window_end = math.min(base + size, address + 0x8000);
    local want = math.max(0, window_end - window_start);
    want = math.min(want, 0x10000);
    if (want <= 0) then
        log_line(('chatrecscan seq=%d reason=%s skipped empty window address=0x%08X region=0x%08X size=0x%X'):fmt(seq, tostring(reason or ''), address, base, size));
        return 0;
    end

    local process = kernel32.GetCurrentProcess();
    local buffer = ffi.new('char[?]', want);
    local bytes_read = ffi.new('SIZE_T[1]');
    bytes_read[0] = 0;
    local read_ok = kernel32.ReadProcessMemory(process, ffi.cast('const void*', window_start), buffer, want, bytes_read) ~= 0;
    local got = tonumber(bytes_read[0]) or 0;
    if (not read_ok or got <= 0) then
        log_line(('chatrecscan seq=%d reason=%s skipped read failed address=0x%08X window=0x%08X+0x%X got=%d'):fmt(seq, tostring(reason or ''), address, window_start, want, got));
        return 0;
    end

    local blob = ffi.string(buffer, got);
    local anchor_pos = address - window_start + 1;
    local anchor = accessxi.blob_printable_run_around(blob, anchor_pos);
    local anchor_text = anchor ~= nil and anchor.text or '';
    log_line(('chatrecscan begin seq=%d reason=%s address=0x%08X region=0x%08X size=0x%X protect=0x%X type=0x%X window=0x%08X+0x%X anchor="%s"'):fmt(
        seq,
        tostring(reason or ''),
        address,
        base,
        size,
        protect,
        mem_type,
        window_start,
        got,
        accessxi.escape_probe_log_text(anchor_text)));

    local hits = 0;
    if (anchor ~= nil and #anchor.text >= 6 and anchor.text:find('%a') ~= nil) then
        local start_at = 1;
        local anchor_hits = 0;
        while (anchor_hits < 24) do
            local found = blob:find(anchor.text, start_at, true);
            if (found == nil) then
                break;
            end

            anchor_hits = anchor_hits + 1;
            hits = hits + 1;
            local absolute = window_start + found - 1;
            local ctx_start = math.max(1, found - 96);
            local ctx_end = math.min(#blob, found + #anchor.text + 96);
            log_line(('chatrecscan anchor seq=%d addr=0x%08X delta=%+d ctx="%s"'):fmt(
                seq,
                absolute,
                absolute - address,
                accessxi.scan_context_text(blob:sub(ctx_start, ctx_end))));
            start_at = found + 1;
        end
    end

    local timestamps = T{};
    local pos = 1;
    while (pos <= #blob and timestamps:len() < 64) do
        local marker_len = accessxi.blob_timestamp_marker_len(blob, pos);
        if (marker_len > 0) then
            local absolute = window_start + pos - 1;
            local ctx_start = math.max(1, pos - 96);
            local ctx_end = math.min(#blob, pos + 192);
            local ctx = accessxi.scan_context_text(blob:sub(ctx_start, ctx_end));
            timestamps:append(absolute);
            hits = hits + 1;
            log_line(('chatrecscan timestamp seq=%d addr=0x%08X marker="%s" prevDelta=%s ctx="%s"'):fmt(
                seq,
                absolute,
                blob:sub(pos, pos + marker_len - 1):gsub('"', "'"),
                timestamps:len() > 1 and tostring(absolute - timestamps[timestamps:len() - 1]) or 'none',
                ctx));
            pos = pos + marker_len;
        else
            pos = pos + 1;
        end
    end

    local run_count = 0;
    local run_start = nil;
    for i = 1, #blob + 1 do
        local b = i <= #blob and blob:byte(i) or 0;
        local printable = b >= 32 and b <= 126;
        if (printable and run_start == nil) then
            run_start = i;
        elseif ((not printable) and run_start ~= nil) then
            local run_len = i - run_start;
            if (run_len >= 8 and run_count < 80) then
                local text = blob:sub(run_start, i - 1):gsub('"', "'"):gsub('%s+', ' '):trim();
                local lower = text:lower();
                if (text:find('%a') ~= nil
                    and lower:find('chatrecscan', 1, true) == nil
                    and lower:find('chatbufscan', 1, true) == nil
                    and lower:find('chatptrscan', 1, true) == nil
                    and lower:find('accessxi', 1, true) == nil) then
                    local absolute = window_start + run_start - 1;
                    run_count = run_count + 1;
                    hits = hits + 1;
                    log_line(('chatrecscan run seq=%d addr=0x%08X len=%d text="%s"'):fmt(
                        seq,
                        absolute,
                        run_len,
                        accessxi.escape_probe_log_text(text)));
                end
            end
            run_start = nil;
        end
    end

    log_line(('chatrecscan end seq=%d bytes=%d hits=%d timestamps=%d runs=%d'):fmt(seq, got, hits, timestamps:len(), run_count));
    return hits;
end

function accessxi.chat_log_decode_row_record(base)
    base = tonumber(base) or 0;
    if (not accessxi.is_scan_address(base)) then
        return nil;
    end

    local text_len = read_u32(base + 0x3C) or -1;
    if (text_len < 1 or text_len > (tonumber(accessxi.chat_log_max_line_len) or 150)) then
        return nil;
    end

    local terminator = read_u8(base + 0x40 + text_len);
    if (terminator ~= 0) then
        return nil;
    end

    local text = accessxi.chat_log_ascii_text_from_ptr(base + 0x40, text_len + 1);
    text = accessxi.chat_log_speech_text(text);
    if (not accessxi.chat_log_plain_text_quality_ok(text, true)) then
        return nil;
    end

    local lower = text:lower();
    if (lower:find('/axi ', 1, true) ~= nil
        or lower:find('/addon ', 1, true) ~= nil
        or lower:find('chatbufscan', 1, true) ~= nil
        or lower:find('chatrecscan', 1, true) ~= nil
        or lower:find('chatrowscan', 1, true) ~= nil
        or lower:find('accessxi', 1, true) ~= nil) then
        return nil;
    end

    return T{
        base = base,
        text_ptr = base + 0x40,
        text_len = text_len,
        flags = read_u32(base + 0x30) or 0,
        hash = read_u32(base + 0x38) or 0,
        text = text,
    };
end

function accessxi.chat_log_row_candidates_for_text_hit(address)
    address = tonumber(address) or 0;
    local rows = T{};
    if (not accessxi.is_scan_address(address)) then
        return rows;
    end

    local seen = {};
    for offset = 0x20, 0x80, 4 do
        local row = accessxi.chat_log_decode_row_record(address - offset);
        if (row ~= nil) then
            local key = ('%08X'):fmt(row.base or 0);
            if (seen[key] ~= true) then
                seen[key] = true;
                row.hit_offset = offset;
                rows:append(row);
            end
        end
    end

    return rows;
end

function accessxi.log_chat_log_row_scan(seq, reason, address)
    seq = tonumber(seq) or 0;
    address = tonumber(address) or 0;
    if (not accessxi.is_scan_address(address)) then
        log_line(('chatrowscan seq=%d reason=%s skipped invalid address=0x%08X'):fmt(seq, tostring(reason or ''), address));
        return 0;
    end

    local base_guess = address - 0x40;
    local decoded = accessxi.chat_log_decode_row_record(base_guess);
    log_line(('chatrowscan begin seq=%d reason=%s address=0x%08X baseGuess=0x%08X decoded=%s dwords=%s bytes=%s'):fmt(
        seq,
        tostring(reason or ''),
        address,
        base_guess,
        decoded ~= nil and ('len=%d flags=0x%08X hash=0x%08X text="%s"'):fmt(decoded.text_len, decoded.flags, decoded.hash, accessxi.escape_probe_log_text(decoded.text)) or 'no',
        accessxi.format_probe_dwords(base_guess, 0, 24),
        accessxi.format_probe_bytes(base_guess, 0, 0x90)));

    local mbi = ffi.new('MEMORY_BASIC_INFORMATION[1]');
    local mbi_size = ffi.sizeof('MEMORY_BASIC_INFORMATION');
    local queried = kernel32.VirtualQuery(ffi.cast('const void*', address), mbi, mbi_size);
    if (tonumber(queried) == 0) then
        log_line(('chatrowscan end seq=%d hits=0 reason=no-region'):fmt(seq));
        return 0;
    end

    local region_base = tonumber(ffi.cast('uintptr_t', mbi[0].BaseAddress)) or 0;
    local region_size = tonumber(mbi[0].RegionSize) or 0;
    local state = tonumber(mbi[0].State) or 0;
    local protect = tonumber(mbi[0].Protect) or 0;
    if (region_base == 0 or region_size <= 0 or state ~= 0x1000 or not accessxi.memory_page_readable(protect)) then
        log_line(('chatrowscan end seq=%d hits=0 reason=unreadable region=0x%08X size=0x%X state=0x%X protect=0x%X'):fmt(seq, region_base, region_size, state, protect));
        return 0;
    end

    local scan_start = math.max(region_base, base_guess - 0x8000);
    local scan_end = math.min(region_base + region_size - 0x80, base_guess + 0x8000);
    local hits = T{};
    local seen = {};
    for base = scan_start, scan_end, 4 do
        local row = accessxi.chat_log_decode_row_record(base);
        if (row ~= nil) then
            local key = ('%08X:%s'):fmt(row.base, row.text:lower());
            if (seen[key] ~= true) then
                seen[key] = true;
                hits:append(row);
            end
        end
    end

    table.sort(hits, function (a, b)
        return (a.base or 0) < (b.base or 0);
    end);

    for i, row in ipairs(hits) do
        if (i > 80) then
            break;
        end
        log_line(('chatrowscan row seq=%d index=%d base=0x%08X text=0x%08X len=%d flags=0x%08X hash=0x%08X delta=%+d text="%s"'):fmt(
            seq,
            i,
            row.base,
            row.text_ptr,
            row.text_len,
            row.flags,
            row.hash,
            row.text_ptr - address,
            accessxi.escape_probe_log_text(row.text)));
    end

    log_line(('chatrowscan end seq=%d region=0x%08X size=0x%X hits=%d'):fmt(seq, region_base, region_size, hits:len()));
    return hits:len();
end

function accessxi.log_chat_log_row_owner_scan(seq, reason, address)
    seq = tonumber(seq) or 0;
    address = tonumber(address) or 0;
    if (not accessxi.is_scan_address(address)) then
        log_line(('chatownerscan seq=%d reason=%s skipped invalid address=0x%08X'):fmt(seq, tostring(reason or ''), address));
        return 0;
    end

    local row = accessxi.chat_log_decode_row_record(address - 0x40);
    local base = address - 0x40;
    if (row == nil) then
        row = accessxi.chat_log_decode_row_record(address);
        base = address;
    end
    if (row == nil) then
        log_line(('chatownerscan begin seq=%d reason=%s address=0x%08X decoded=no baseGuess=0x%08X dwords=%s bytes=%s'):fmt(
            seq,
            tostring(reason or ''),
            address,
            address - 0x40,
            accessxi.format_probe_dwords(address - 0x40, 0, 32),
            accessxi.format_probe_bytes(address - 0x40, 0, 0xC0)));
        return 0;
    end

    log_line(('chatownerscan begin seq=%d reason=%s address=0x%08X base=0x%08X text=0x%08X len=%d flags=0x%08X hash=0x%08X text="%s" dwords=%s bytes=%s'):fmt(
        seq,
        tostring(reason or ''),
        address,
        base,
        row.text_ptr,
        row.text_len,
        row.flags,
        row.hash,
        accessxi.escape_probe_log_text(row.text),
        accessxi.format_probe_dwords(base, 0, 40),
        accessxi.format_probe_bytes(base, 0, 0x100)));

    local hits = 0;
    local seen = {};
    for _, off in ipairs(T{ 0x00, 0x08, 0x0C, 0x10, 0x14, 0x1C, 0x20, 0x24, 0x28, 0x2C, 0x30, 0x34 }) do
        local ptr = read_u32(base + off) or 0;
        if (accessxi.is_scan_address(ptr) and seen[ptr] ~= true) then
            seen[ptr] = true;
            hits = hits + 1;
            local runs = '';
            if (accessxi.collect_probe_ascii_runs ~= nil) then
                runs = accessxi.collect_probe_ascii_runs(ptr, 0x300, 8, 24):concat('|');
            end
            log_line(('chatownerscan ptr seq=%d index=%d field=+0x%02X ptr=0x%08X dwords=%s bytes=%s runs="%s"'):fmt(
                seq,
                hits,
                off,
                ptr,
                accessxi.format_probe_dwords(ptr, 0, 32),
                accessxi.format_probe_bytes(ptr, 0, 0xC0),
                accessxi.escape_probe_log_text(runs)));

            local near_rows = T{};
            local scan_start = math.max(0x10000, ptr - 0x400);
            local scan_end = ptr + 0x800;
            local seen_row = {};
            for candidate_base = scan_start, scan_end, 4 do
                local candidate = accessxi.chat_log_decode_row_record(candidate_base);
                if (candidate ~= nil and seen_row[candidate.base] ~= true) then
                    seen_row[candidate.base] = true;
                    near_rows:append(candidate);
                end
            end
            table.sort(near_rows, function (a, b)
                return (a.base or 0) < (b.base or 0);
            end);
            for i, candidate in ipairs(near_rows) do
                if (i > 12) then
                    break;
                end
                log_line(('chatownerscan nearrow seq=%d field=+0x%02X index=%d base=0x%08X text=0x%08X len=%d flags=0x%08X hash=0x%08X delta=%+d text="%s"'):fmt(
                    seq,
                    off,
                    i,
                    candidate.base,
                    candidate.text_ptr,
                    candidate.text_len,
                    candidate.flags,
                    candidate.hash,
                    candidate.base - base,
                    accessxi.escape_probe_log_text(candidate.text)));
            end
        end
    end

    log_line(('chatownerscan end seq=%d fields=%d'):fmt(seq, hits));
    return hits;
end

function accessxi.log_chat_log_buffer_scan(seq, reason, extra_terms)
    seq = tonumber(seq) or 0;

    local obj = get_current_menu_object_ptr();
    local line_block = obj ~= 0 and (read_u32(obj + 0x08) or 0) or 0;
    local visible = obj ~= 0 and (read_u32(obj + 0x88) or 0) or 0;
    local terms = T{};
    local seen = {};

    extra_terms = accessxi.survival_guide_text(extra_terms or '');
    if (extra_terms ~= '') then
        for term in extra_terms:gmatch('[^|]+') do
            accessxi.add_unique_scan_term(terms, seen, term);
        end
    end

    if (terms:len() == 0) then
        local visible_terms = accessxi.chat_log_visible_scan_terms(visible, 0x1000, 10);
        for _, term in ipairs(visible_terms) do
            accessxi.add_unique_scan_term(terms, seen, term);
        end
    end

    if (terms:len() == 0) then
        log_line(('chatbufscan seq=%d reason=%s skipped no visible terms obj=0x%08X visible=0x%08X'):fmt(
            seq,
            tostring(reason or ''),
            obj,
            visible));
        return 0;
    end

    local patterns = T{};
    for _, term in ipairs(terms) do
        patterns:append(T{ term = term, enc = 'ascii', bytes = term });
        patterns:append(T{ term = term, enc = 'utf16le', bytes = accessxi.utf16le_pattern(term) });
    end

    local render_ranges = T{};
    if (accessxi.is_probe_pointer(visible)) then
        render_ranges:append(T{ name = 'render-visible', base = visible, length = 0x2000 });
    end
    if (accessxi.is_probe_pointer(line_block)) then
        render_ranges:append(T{ name = 'line-block', base = line_block, length = 0x4000 });
    end

    local mbi = ffi.new('MEMORY_BASIC_INFORMATION[1]');
    local mbi_size = ffi.sizeof('MEMORY_BASIC_INFORMATION');
    local addr = 0x10000;
    local stop_addr = 0x7FFF0000;
    local max_ms = 900;
    local max_bytes = 128 * 1024 * 1024;
    local max_regions = 2048;
    local max_hits = 120;
    local chunk_size = 256 * 1024;
    local process = kernel32.GetCurrentProcess();
    local buffer = ffi.new('char[?]', chunk_size);
    local bytes_read = ffi.new('SIZE_T[1]');
    local started = tick();
    local scanned_bytes = 0;
    local regions = 0;
    local readable_regions = 0;
    local hits = 0;
    local candidate_hits = 0;
    local record_hits = 0;
    local timed_out = false;
    local hit_keys = {};
    local owner_scan_logged = false;

    log_line(('chatbufscan begin seq=%d reason=%s menu="%s" obj=0x%08X visible=0x%08X lineBlock=0x%08X terms="%s"'):fmt(
        seq,
        tostring(reason or ''),
        get_menu_name() or '',
        obj,
        visible,
        line_block,
        terms:concat('|')));

    while (addr < stop_addr and regions < max_regions and scanned_bytes < max_bytes and hits < max_hits) do
        if ((tick() - started) > max_ms) then
            timed_out = true;
            break;
        end

        local ok, result = pcall(function ()
            return kernel32.VirtualQuery(ffi.cast('const void*', addr), mbi, mbi_size);
        end);
        local queried = ok and tonumber(result) or 0;
        if (queried == 0) then
            addr = addr + 0x10000;
        else
            local base = tonumber(ffi.cast('uintptr_t', mbi[0].BaseAddress)) or addr;
            local size = tonumber(mbi[0].RegionSize) or 0;
            local state = tonumber(mbi[0].State) or 0;
            local protect = tonumber(mbi[0].Protect) or 0;
            local mem_type = tonumber(mbi[0].Type) or 0;
            local next_addr = base + math.max(size, 0x1000);
            regions = regions + 1;

            if (size > 0 and state == 0x1000 and accessxi.memory_page_readable(protect)) then
                readable_regions = readable_regions + 1;

                local region_offset = 0;
                while (region_offset < size and scanned_bytes < max_bytes and hits < max_hits) do
                    if ((tick() - started) > max_ms) then
                        timed_out = true;
                        break;
                    end

                    local want = math.min(chunk_size, size - region_offset, max_bytes - scanned_bytes);
                    local chunk_addr = base + region_offset;
                    bytes_read[0] = 0;
                    local read_ok = kernel32.ReadProcessMemory(process, ffi.cast('const void*', chunk_addr), buffer, want, bytes_read) ~= 0;
                    local got = tonumber(bytes_read[0]) or 0;

                    if (read_ok and got > 0) then
                        local blob = ffi.string(buffer, got);
                        scanned_bytes = scanned_bytes + got;
                        for _, pattern in ipairs(patterns) do
                            local start_at = 1;
                            local term_hits = 0;
                            while (term_hits < 8 and hits < max_hits) do
                                local found = blob:find(pattern.bytes, start_at, true);
                                if (found == nil) then
                                    break;
                                end

                                local absolute = chunk_addr + found - 1;
                                local key = ('%s:%s:%08X'):fmt(pattern.enc, pattern.term, absolute);
                                if (hit_keys[key] ~= true) then
                                    hit_keys[key] = true;
                                    local context_start = math.max(1, found - 64);
                                    local context_end = math.min(#blob, found + #pattern.bytes + 96);
                                    local context = accessxi.scan_context_text(blob:sub(context_start, context_end));
                                    local source = accessxi.chat_log_scan_source_for_hit(context, absolute, render_ranges);
                                    hits = hits + 1;
                                    term_hits = term_hits + 1;
                                    if (source == 'candidate' or source == 'ffxi-chat-record') then
                                        candidate_hits = candidate_hits + 1;
                                    end
                                    if (source == 'ffxi-chat-record') then
                                        record_hits = record_hits + 1;
                                    end
                                    log_line(('chatbufscan hit seq=%d term="%s" enc=%s addr=0x%08X region=0x%08X protect=0x%X type=0x%X source=%s ctx="%s"'):fmt(
                                        seq,
                                        pattern.term:gsub('"', "'"),
                                        pattern.enc,
                                        absolute,
                                        base,
                                        protect,
                                        mem_type,
                                        source,
                                        context));
                                    if (accessxi.chat_log_row_candidates_for_text_hit ~= nil) then
                                        local rows = accessxi.chat_log_row_candidates_for_text_hit(absolute);
                                        for _, row in ipairs(rows) do
                                            log_line(('chatbufscan rowcandidate seq=%d source=%s hit=0x%08X offset=0x%02X base=0x%08X text=0x%08X len=%d flags=0x%08X hash=0x%08X text="%s"'):fmt(
                                                seq,
                                                source,
                                                absolute,
                                                tonumber(row.hit_offset) or 0,
                                                row.base,
                                                row.text_ptr,
                                                row.text_len,
                                                row.flags,
                                                row.hash,
                                                accessxi.escape_probe_log_text(row.text)));
                                            if (owner_scan_logged ~= true
                                                and source == 'ffxi-chat-record'
                                                and (tonumber(row.flags) or 0) ~= 0) then
                                                owner_scan_logged = true;
                                                accessxi.log_chat_log_row_owner_scan(seq, 'chatbufscan-rowcandidate', row.text_ptr);
                                            end
                                        end
                                    end
                                    if (source == 'ffxi-chat-record') then
                                        log_line(('chatbufscan record seq=%d addr=0x%08X bytesBefore=%s dwordsBefore=%s'):fmt(
                                            seq,
                                            absolute,
                                            accessxi.format_probe_bytes(absolute - 0x40, 0, 0xA0),
                                            accessxi.format_probe_dwords(absolute - 0x40, 0, 24)));
                                    end
                                    if (source == 'candidate' or source == 'ffxi-chat-record') then
                                        local nearby_start = math.max(1, found - 512);
                                        local nearby_end = math.min(#blob, found + #pattern.bytes + 512);
                                        local runs = accessxi.ascii_runs_from_blob(blob:sub(nearby_start, nearby_end), 36);
                                        if (runs:len() > 0) then
                                            log_line(('chatbufscan strings seq=%d addr=0x%08X strings="%s"'):fmt(seq, absolute, runs:concat('|')));
                                        end
                                    end
                                end

                                start_at = found + 1;
                            end
                        end
                    else
                        scanned_bytes = scanned_bytes + want;
                    end

                    region_offset = region_offset + want;
                end
            end

            if (next_addr <= addr) then
                addr = addr + 0x1000;
            else
                addr = next_addr;
            end
        end
    end

    log_line(('chatbufscan end seq=%d regions=%d readable=%d scanned=%d hits=%d candidates=%d records=%d timeout=%s'):fmt(
        seq,
        regions,
        readable_regions,
        scanned_bytes,
        hits,
        candidate_hits,
        record_hits,
        tostring(timed_out)));
    return hits;
end

local function hex32(value)
    value = tonumber(value) or 0;
    if (value < 0) then
        value = value + 0x100000000;
    end
    return ('%08X'):fmt(value);
end

local function current_target_snapshot()
    local target = AshitaCore:GetMemoryManager():GetTarget();
    if (target == nil) then
        return 'target=nil';
    end

    local help_string_ptr = safe_call(function () return target:GetWindowHelpString(); end, 0);
    local help_title_ptr = safe_call(function () return target:GetWindowHelpTitle(); end, 0);

    return ('menuOpen=%s mode=%s lock=%s focus=%s winLoaded=%s win="%s" helpTitlePtr=0x%08X helpTitle="%s" helpPtr=0x%08X help="%s" ankNum=%s ank=(%s,%s) sub=%s subAnk=(%s,%s)'):fmt(
        tostring(safe_call(function () return target:GetIsMenuOpen(); end, -1)),
        tostring(safe_call(function () return target:GetDefaultMode(); end, -1)),
        tostring(safe_call(function () return target:GetMenuTargetLock(); end, -1)),
        tostring(safe_call(function () return target:GetFocusTargetIndex(); end, -1)),
        tostring(safe_call(function () return target:GetWindowIsWindowLoaded(); end, -1)),
        clean_probe_text(safe_call(function () return target:GetWindowName(); end, '')),
        tonumber(help_title_ptr) or 0,
        read_probe_string(help_title_ptr),
        tonumber(help_string_ptr) or 0,
        read_probe_string(help_string_ptr),
        tostring(safe_call(function () return target:GetWindowAnkNum(); end, -1)),
        tostring(safe_call(function () return target:GetWindowAnkX(); end, -1)),
        tostring(safe_call(function () return target:GetWindowAnkY(); end, -1)),
        tostring(safe_call(function () return target:GetWindowSub(); end, -1)),
        tostring(safe_call(function () return target:GetWindowSubAnkX(); end, -1)),
        tostring(safe_call(function () return target:GetWindowSubAnkY(); end, -1)));
end

local function log_ingame_target_probe(reason)
    if (not accessxi.debug_probe_logging_active()) then
        return;
    end

    local target = AshitaCore:GetMemoryManager():GetTarget();
    if (target == nil) then
        return;
    end

    local is_menu_open = safe_call(function () return target:GetIsMenuOpen(); end, -1);
    local default_mode = safe_call(function () return target:GetDefaultMode(); end, -1);
    local menu_lock = safe_call(function () return target:GetMenuTargetLock(); end, -1);
    local focus_index = safe_call(function () return target:GetFocusTargetIndex(); end, -1);
    local window_loaded = safe_call(function () return target:GetWindowIsWindowLoaded(); end, -1);
    local window_name = clean_probe_text(safe_call(function () return target:GetWindowName(); end, ''));
    local help_string_ptr = safe_call(function () return target:GetWindowHelpString(); end, 0);
    local help_title_ptr = safe_call(function () return target:GetWindowHelpTitle(); end, 0);
    local help_string = read_probe_string(help_string_ptr);
    local help_title = read_probe_string(help_title_ptr);
    local ank_num = safe_call(function () return target:GetWindowAnkNum(); end, -1);
    local ank_x = safe_call(function () return target:GetWindowAnkX(); end, -1);
    local ank_y = safe_call(function () return target:GetWindowAnkY(); end, -1);
    local sub = safe_call(function () return target:GetWindowSub(); end, -1);
    local sub_x = safe_call(function () return target:GetWindowSubAnkX(); end, -1);
    local sub_y = safe_call(function () return target:GetWindowSubAnkY(); end, -1);

    local line = ('ingame probe reason=%s menuOpen=%s mode=%s lock=%s focus=%s winLoaded=%s win="%s" helpTitlePtr=0x%08X helpTitle="%s" helpPtr=0x%08X help="%s" ankNum=%s ank=(%s,%s) sub=%s subAnk=(%s,%s)'):fmt(
        reason or '',
        tostring(is_menu_open),
        tostring(default_mode),
        tostring(menu_lock),
        tostring(focus_index),
        tostring(window_loaded),
        window_name,
        tonumber(help_title_ptr) or 0,
        help_title,
        tonumber(help_string_ptr) or 0,
        help_string,
        tostring(ank_num),
        tostring(ank_x),
        tostring(ank_y),
        tostring(sub),
        tostring(sub_x),
        tostring(sub_y));

    if (line ~= accessxi.last_ingame_probe_log) then
        accessxi.last_ingame_probe_log = line;
        log_line(line);
    end
end

local function log_unknown_menu_probe(name)
    if (not accessxi.debug_probe_logging_active()) then
        return;
    end

    local obj = get_current_menu_object_ptr();
    local parts = T{};
    if (obj ~= 0) then
        for _, off in ipairs(T{ 0x10, 0x14, 0x18, 0x1C, 0x20, 0x24, 0x28, 0x2C, 0x30, 0x34, 0x38, 0x3C }) do
            local value = read_i32(obj + off);
            if (value ~= nil and value >= -1 and value <= 128) then
                parts:append(('+%02X=%d'):fmt(off, value));
            end
        end
    end

    local line = ('unknown menu name="%s" obj=0x%08X %s'):fmt(name, obj, parts:concat(' '));
    if (line ~= accessxi.last_unknown_menu_log) then
        accessxi.last_unknown_menu_log = line;
        log_line(line);
    end

    local target = AshitaCore:GetMemoryManager():GetTarget();
    local window_name = accessxi.survival_guide_text(target ~= nil and safe_call(function () return target:GetWindowName(); end, '') or '');
    if (window_name:eq('Survival Guide', true)
        and (name:eq('menu    inline', true) or name:eq('menu    rem4li2', true))) then
        local key = ('%s:%08X'):fmt(name, obj);
        if (key ~= accessxi.last_survival_guide_transient_probe_key) then
            accessxi.last_survival_guide_transient_probe_key = key;
            accessxi.menu_dump_sequence = (accessxi.menu_dump_sequence or 0) + 1;
            local seq = accessxi.menu_dump_sequence;
            log_line(('menudump begin seq=%d reason=transient-survival-guide menu="%s" obj=0x%08X'):fmt(seq, name, obj));
            if (accessxi.log_survival_guide_native_text_probe ~= nil) then
                accessxi.log_survival_guide_native_text_probe(seq, obj, 'transient');
            end
            log_line(('menudump end seq=%d'):fmt(seq));
        end
    end
end

local function append_probe_part(parts, value, limit)
    if (#parts >= limit) then
        return;
    end
    parts:append(value);
end

local function log_deep_native_menu_probe(name)
    local obj = get_current_menu_object_ptr();
    if (obj == 0) then
        return;
    end

    local small32 = T{};
    local bytes = T{};
    local ptrs = T{};

    for off = 0, 0xE0, 4 do
        local svalue = read_i32(obj + off);
        if (svalue ~= nil and svalue >= -1 and svalue <= 512) then
            append_probe_part(small32, ('+%02X=%d'):fmt(off, svalue), 80);
        end

        local uvalue = read_u32(obj + off);
        if (uvalue ~= nil) then
            for byte_index = 0, 3 do
                local byte_value = bit.band(bit.rshift(uvalue, byte_index * 8), 0xFF);
                if (byte_value <= 64) then
                    append_probe_part(bytes, ('+%02X.%d=%d'):fmt(off, byte_index, byte_value), 96);
                end
            end

            if (uvalue >= 0x10000 and uvalue < 0x7FFFFFFF) then
                append_probe_part(ptrs, ('+%02X->0x%08X'):fmt(off, uvalue), 32);
            end
        end
    end

    local line = ('menuprobe name="%s" obj=0x%08X small32=%s bytes=%s ptrs=%s'):fmt(
        name,
        obj,
        small32:concat(' '),
        bytes:concat(' '),
        ptrs:concat(' | '));

    if (line ~= accessxi.last_deep_menu_probe_log) then
        accessxi.last_deep_menu_probe_log = line;
        log_line(line);
    end
end

local function read_current_native_menu_index(offset)
    local obj = get_current_menu_object_ptr();
    if (obj == 0) then
        return 0;
    end

    local selected = read_i32(obj + (offset or 0x4C));
    selected = tonumber(selected) or 0;
    if (selected < 0 or selected > 64) then
        return 0;
    end
    return selected;
end

function accessxi.log_menu_dispatch_probe(name, previous_menu_name)
    if (not accessxi.debug_probe_logging_active()) then
        return;
    end

    local obj = get_current_menu_object_ptr();
    local selected, page, raw, child, count = 0, 0, 0, 0, 0;
    if (accessxi.survival_guide_query_child_state_for_obj ~= nil) then
        selected, page, raw, child, count = accessxi.survival_guide_query_child_state_for_obj(obj);
    end
    selected = tonumber(selected) or 0;
    page = tonumber(page) or 0;
    raw = tonumber(raw) or 0;
    child = tonumber(child) or 0;
    count = tonumber(count) or 0;

    local index_parts = T{};
    for _, offset in ipairs(T{ 0x24, 0x28, 0x30, 0x34, 0x4C, 0x50, 0x58, 0x64 }) do
        index_parts:append(('%02X=%d'):fmt(offset, tonumber(read_current_native_menu_index(offset)) or 0));
    end

    if (selected <= 0) then
        selected = tonumber(read_current_native_menu_index(0x4C)) or 0;
    end
    if (count <= 0 or count > 256) then
        count = math.max(
            tonumber(read_current_native_menu_index(0x24)) or 0,
            tonumber(read_current_native_menu_index(0x28)) or 0,
            tonumber(read_current_native_menu_index(0x58)) or 0);
    end

    local entry = 0;
    if (accessxi.is_probe_pointer(obj)) then
        entry = read_u32(obj + 0x08) or 0;
    end

    local window_name = '';
    local help_title = '';
    local help_string = '';
    local target = safe_call(function () return AshitaCore:GetMemoryManager():GetTarget(); end, nil);
    if (target ~= nil) then
        window_name = clean_probe_text(safe_call(function () return target:GetWindowName(); end, '') or '');
        local help_title_ptr = safe_call(function () return target:GetWindowHelpTitle(); end, 0);
        local help_string_ptr = safe_call(function () return target:GetWindowHelpString(); end, 0);
        help_title = read_probe_string(help_title_ptr);
        help_string = read_probe_string(help_string_ptr);
    end

    local function field(text)
        return clean_probe_text(text or ''):gsub('\\', '\\\\'):gsub('"', '\\"');
    end

    local line = ('state menu-dispatch-probe menu="%s" previous="%s" obj=0x%08X child=0x%08X entry=0x%08X selected=%d count=%d page=%d raw=0x%08X idx="%s" win="%s" helpTitle="%s" help="%s"'):fmt(
        field(name),
        field(previous_menu_name),
        tonumber(obj) or 0,
        child,
        entry,
        selected,
        count,
        page,
        raw,
        index_parts:concat(' '),
        field(window_name),
        field(help_title),
        field(help_string));
    if (line ~= accessxi.last_menu_dispatch_probe_log) then
        accessxi.last_menu_dispatch_probe_log = line;
        log_line(line);
    end
end

local function option_from_index(options, index)
    local option = options[index + 1];
    if (option == nil) then
        return '';
    end
    return option;
end

local function option_from_one_based_index(options, index)
    local option = options[index];
    if (option == nil) then
        return '';
    end
    return option;
end

function accessxi.packet_byte(data, pos)
    return string.byte(data or '', pos) or 0;
end

function accessxi.packet_u16(data, pos)
    local b1 = accessxi.packet_byte(data, pos);
    local b2 = accessxi.packet_byte(data, pos + 1);
    return b1 + (b2 * 256);
end

function accessxi.packet_u32(data, pos)
    local b1 = accessxi.packet_byte(data, pos);
    local b2 = accessxi.packet_byte(data, pos + 1);
    local b3 = accessxi.packet_byte(data, pos + 2);
    local b4 = accessxi.packet_byte(data, pos + 3);
    return b1 + (b2 * 256) + (b3 * 65536) + (b4 * 16777216);
end

function accessxi.packet_i32(data, pos)
    local value = accessxi.packet_u32(data, pos);
    if (value >= 2147483648) then
        return value - 4294967296;
    end
    return value;
end

function accessxi.packet_bit_count(data)
    local count = 0;
    for i = 1, #(data or '') do
        local value = string.byte(data, i) or 0;
        while (value > 0) do
            if (bit.band(value, 1) ~= 0) then
                count = count + 1;
            end
            value = bit.rshift(value, 1);
        end
    end
    return count;
end

function accessxi.packet_has_bit(data, position)
    position = tonumber(position) or -1;
    if (position < 0) then
        return false;
    end

    local byte = string.byte(data or '', math.floor(position / 8) + 1) or 0;
    return bit.band(byte, bit.lshift(1, position % 8)) ~= 0;
end

function accessxi.packet_bits_le(data, position, width)
    position = tonumber(position) or 0;
    width = tonumber(width) or 0;
    local value = 0;
    for index = 0, width - 1 do
        if (accessxi.packet_has_bit(data, position + index)) then
            value = value + math.pow(2, index);
        end
    end
    return value;
end

function accessxi.packet_bits_be(data, position, width)
    position = tonumber(position) or 0;
    width = tonumber(width) or 0;
    local value = 0;
    for index = 0, width - 1 do
        local byte = string.byte(data or '', math.floor((position + index) / 8) + 1) or 0;
        local mask = bit.lshift(1, 7 - ((position + index) % 8));
        if (bit.band(byte, mask) ~= 0) then
            value = value + math.pow(2, width - index - 1);
        end
    end
    return value;
end

function accessxi.packet_hex(data)
    local parts = T{};
    for i = 1, #(data or '') do
        parts:append(('%02X'):fmt(string.byte(data, i) or 0));
    end
    return parts:concat(' ');
end

function accessxi.packet_hex_limit(data, limit)
    local parts = T{};
    limit = math.max(1, math.min(tonumber(limit) or 96, #(data or '')));
    for i = 1, limit do
        parts:append(('%02X'):fmt(string.byte(data, i) or 0));
    end
    return parts:concat(' ');
end

function accessxi.packet_hex_to_bytes(hex)
    local parts = T{};
    for pair in tostring(hex or ''):gmatch('%x%x') do
        parts:append(string.char(tonumber(pair, 16) or 0));
    end
    return parts:concat('');
end

function accessxi.packet_nonzero_words(data, start_pos, end_pos)
    data = data or '';
    start_pos = math.max(1, tonumber(start_pos) or 1);
    end_pos = math.min(#data, tonumber(end_pos) or #data);
    local parts = T{};
    for pos = start_pos, end_pos, 2 do
        local value = accessxi.packet_u16(data, pos);
        if (value ~= 0) then
            parts:append(('+%02X=0x%04X'):fmt(pos - 1, value));
        end
    end
    return parts:concat(',');
end

function accessxi.packet_ascii_preview(data, limit)
    local chars = T{};
    limit = math.max(1, math.min(tonumber(limit) or 96, #(data or '')));
    for i = 1, limit do
        local b = string.byte(data, i) or 0;
        if (b >= 32 and b <= 126) then
            chars:append(string.char(b));
        else
            chars:append('.');
        end
    end
    return chars:concat('');
end

function accessxi.packet_ascii_z_at(data, pos, max_len)
    data = data or '';
    pos = tonumber(pos) or 1;
    max_len = math.max(1, math.min(tonumber(max_len) or 32, 64));
    if (pos < 1 or pos > #data) then
        return '';
    end

    local chars = T{};
    local limit = math.min(#data, pos + max_len - 1);
    for i = pos, limit do
        local b = string.byte(data, i) or 0;
        if (b == 0) then
            break;
        end
        if (b < 32 or b > 126) then
            return '';
        end
        chars:append(string.char(b));
    end

    local value = chars:concat(''):gsub('^%s+', ''):gsub('%s+$', '');
    if (#value < 2) then
        return '';
    end
    return value;
end

function accessxi.packet_event_string(e, field, size_field)
    local value = nil;
    local ok = pcall(function () value = e[field]; end);
    if (ok and type(value) == 'string' and #value > 0) then
        return value;
    end

    local ptr = nil;
    ok = pcall(function () ptr = e[field .. '_raw']; end);
    if (ok and ptr ~= nil and ffi ~= nil) then
        local size_value = 0;
        pcall(function () size_value = tonumber(e[size_field or 'size']) or 0; end);
        if (size_value > 0 and size_value <= 4096) then
            local raw_ok, raw = pcall(function () return ffi.string(ptr, size_value); end);
            if (raw_ok and type(raw) == 'string' and #raw > 0) then
                return raw;
            end
        end
    end

    return '';
end

function accessxi.packet_from_hex(hex)
    local chars = T{};
    for byte in tostring(hex or ''):gmatch('%x%x') do
        chars:append(string.char(tonumber(byte, 16) or 0));
    end
    return chars:concat('');
end

function accessxi.save_mission_packet_cache()
    local packet = accessxi.mission_packet_main or {};
    if ((tonumber(packet.port) or 0) ~= 0xFFFF) then
        return;
    end

    local player_name = accessxi.current_player_name();
    local server_id = tonumber(accessxi.current_player_server_id()) or 0;
    if (player_name == '' or server_id <= 0) then
        return;
    end

    local f = io.open(accessxi.mission_packet_cache_path, 'w');
    if (f == nil) then
        return;
    end

    f:write(('player=%s\n'):fmt(player_name));
    f:write(('server_id=%d\n'):fmt(server_id));
    f:write(('saved_at=%d\n'):fmt(os.time()));
    for _, key in ipairs(T{ 'nation', 'nation_mission', 'zilart', 'cop', 'cop_status', 'addons', 'tales', 'soa', 'rov', 'port', 'port_raw' }) do
        f:write(('%s=%d\n'):fmt(key, tonumber(packet[key]) or 0));
    end
    local ahturghan = accessxi.mission_packet_ahturghan or {};
    for _, key in ipairs(T{ 'assault', 'toau', 'wotg', 'campaign', 'port' }) do
        f:write(('ahturghan_%s=%d\n'):fmt(key, tonumber(ahturghan[key]) or 0));
    end
    local assault_complete = accessxi.mission_packet_ahturghan_complete or {};
    for index = 1, 4 do
        f:write(('assault_complete%d=%d\n'):fmt(index - 1, tonumber(assault_complete[index]) or 0));
    end
    f:close();
end

function accessxi.restore_mission_packet_cache_if_needed()
    if (accessxi.mission_packet_cache_loaded == true or tonumber((accessxi.mission_packet_main or {}).cop) ~= nil) then
        return;
    end
    accessxi.mission_packet_cache_loaded = true;

    local f = io.open(accessxi.mission_packet_cache_path, 'r');
    if (f == nil) then
        return;
    end

    local values = {};
    for line in f:lines() do
        local key, value = tostring(line or ''):match('^([^=]+)=(.*)$');
        if (key ~= nil) then
            values[key] = value or '';
        end
    end
    f:close();

    local cached_player = tostring(values.player or '');
    local cached_server_id = tonumber(values.server_id) or 0;
    local player_name = accessxi.current_player_name();
    local current_server_id = tonumber(accessxi.current_player_server_id()) or 0;
    local player_identity = accessxi.current_player_identity();
    if (cached_player == '' or player_name == '' or cached_player ~= player_name
        or cached_server_id <= 0 or current_server_id <= 0 or cached_server_id ~= current_server_id
        or player_identity == '') then
        log_line(('mission packet cache ignored cachedPlayer="%s" player="%s" cachedServerId=%d serverId=%d'):fmt(
            accessxi.escape_probe_log_text(cached_player),
            accessxi.escape_probe_log_text(player_name),
            cached_server_id,
            current_server_id));
        return;
    end
    local saved_at = tonumber(values.saved_at);
    local now = os.time();
    local max_age = 120;
    if (saved_at == nil or saved_at <= 0 or (now - saved_at) > max_age) then
        log_line(('mission packet cache ignored stale age=%d maxAge=%d player="%s"'):fmt(
            saved_at ~= nil and (now - saved_at) or -1,
            max_age,
            accessxi.escape_probe_log_text(cached_player)));
        return;
    end

    local info = {};
    local has_value = false;
    for _, key in ipairs(T{ 'nation', 'nation_mission', 'zilart', 'cop', 'cop_status', 'addons', 'tales', 'soa', 'rov', 'port', 'port_raw' }) do
        info[key] = tonumber(values[key]) or 0;
        if (info[key] ~= 0) then
            has_value = true;
        end
    end
    if (not has_value or (tonumber(info.port) or 0) ~= 0xFFFF) then
        return;
    end

    accessxi.mission_packet_main = info;
    accessxi.mission_packet_player = player_name;
    accessxi.mission_packet_identity = player_identity;
    accessxi.mission_packet_source = 'cache';
    accessxi.mission_packet_tick = tick();
    if (values.ahturghan_toau ~= nil or values.ahturghan_wotg ~= nil or values.ahturghan_assault ~= nil or values.ahturghan_campaign ~= nil) then
        accessxi.mission_packet_ahturghan = {
            assault = tonumber(values.ahturghan_assault) or 0,
            toau = tonumber(values.ahturghan_toau) or 0,
            wotg = tonumber(values.ahturghan_wotg) or 0,
            campaign = tonumber(values.ahturghan_campaign) or 0,
            port = tonumber(values.ahturghan_port) or 0,
        };
        accessxi.mission_packet_ahturghan_tick = accessxi.mission_packet_tick;
        accessxi.mission_packet_ahturghan_identity = player_identity;
        accessxi.mission_packet_ahturghan_source = 'cache';
    end
    if (values.assault_complete0 ~= nil or values.assault_complete1 ~= nil or values.assault_complete2 ~= nil or values.assault_complete3 ~= nil) then
        accessxi.mission_packet_ahturghan_complete = T{
            tonumber(values.assault_complete0) or 0,
            tonumber(values.assault_complete1) or 0,
            tonumber(values.assault_complete2) or 0,
            tonumber(values.assault_complete3) or 0
        };
        accessxi.mission_packet_ahturghan_complete_tick = accessxi.mission_packet_tick;
        accessxi.mission_packet_ahturghan_complete_identity = player_identity;
        accessxi.mission_packet_ahturghan_complete_source = 'cache';
    end
    log_line(('mission packet cache restored player="%s" cop=%d copStatus=0x%08X rov=%d'):fmt(
        accessxi.escape_probe_log_text(cached_player),
        tonumber(info.cop) or 0,
        tonumber(info.cop_status) or 0,
        tonumber(info.rov) or 0));
end

function accessxi.quest_packet_data_words(data)
    local words = T{};
    local base = 0x04;
    for index = 1, 8 do
        words[index] = accessxi.packet_u32(data, base + ((index - 1) * 4) + 1);
    end
    return words;
end

function accessxi.quest_packet_log_for_port(port)
    port = tonumber(port) or 0;
    local ports = accessxi.quests_menu_data.quest_log_ports or T{};
    for area_key, info in pairs(ports) do
        local current = tonumber(info.current) or -1;
        local completed = tonumber(info.completed) or -1;
        if (port == current) then
            return tostring(area_key or ''), 'current';
        elseif (port == completed) then
            return tostring(area_key or ''), 'completed';
        end
    end
    return '', '';
end

function accessxi.quest_packet_entry_key(area_key, mode)
    return ('%s:%s'):fmt(tostring(area_key or ''), tostring(mode or ''));
end

function accessxi.save_quest_packet_cache()
    local logs = accessxi.quest_packet_logs or {};
    local player_name = accessxi.current_player_name();
    local server_id = tonumber(accessxi.current_player_server_id()) or 0;
    if (player_name == '' or server_id <= 0) then
        return;
    end

    local f = io.open(accessxi.quest_packet_cache_path, 'w');
    if (f == nil) then
        return;
    end

    f:write(('player=%s\n'):fmt(player_name));
    f:write(('server_id=%d\n'):fmt(server_id));
    f:write(('saved_at=%d\n'):fmt(os.time()));
    for key, entry in pairs(logs) do
        if (type(entry) == 'table' and type(entry.words) == 'table') then
            local parts = T{};
            for index = 1, 8 do
                parts:append(tostring(tonumber(entry.words[index]) or 0));
            end
            f:write(('packet=%s\t%d\t%s\t%s\t%s\n'):fmt(
                tostring(key or ''),
                tonumber(entry.port) or 0,
                tostring(entry.area_key or ''),
                tostring(entry.mode or ''),
                parts:concat(',')));
        end
    end
    f:close();
end

function accessxi.restore_quest_packet_cache_if_needed()
    if (accessxi.quest_packet_cache_loaded == true) then
        return;
    end
    accessxi.quest_packet_cache_loaded = true;

    local f = io.open(accessxi.quest_packet_cache_path, 'r');
    if (f == nil) then
        return;
    end

    local values = {};
    local packet_lines = T{};
    for line in f:lines() do
        local packet = tostring(line or ''):match('^packet=(.*)$');
        if (packet ~= nil) then
            packet_lines:append(packet);
        else
            local key, value = tostring(line or ''):match('^([^=]+)=(.*)$');
            if (key ~= nil) then
                values[key] = value or '';
            end
        end
    end
    f:close();

    local cached_player = tostring(values.player or '');
    local cached_server_id = tonumber(values.server_id) or 0;
    local player_name = accessxi.current_player_name();
    local current_server_id = tonumber(accessxi.current_player_server_id()) or 0;
    local player_identity = accessxi.current_player_identity();
    if (cached_player == '' or player_name == '' or cached_player ~= player_name
        or cached_server_id <= 0 or current_server_id <= 0 or cached_server_id ~= current_server_id
        or player_identity == '') then
        log_line(('quest packet cache ignored cachedPlayer="%s" player="%s" cachedServerId=%d serverId=%d'):fmt(
            accessxi.escape_probe_log_text(cached_player),
            accessxi.escape_probe_log_text(player_name),
            cached_server_id,
            current_server_id));
        return;
    end
    local saved_at = tonumber(values.saved_at);
    local now = os.time();
    local max_age = 120;
    if (saved_at == nil or saved_at <= 0 or (now - saved_at) > max_age) then
        log_line(('quest packet cache ignored stale age=%d maxAge=%d player="%s"'):fmt(
            saved_at ~= nil and (now - saved_at) or -1,
            max_age,
            accessxi.escape_probe_log_text(cached_player)));
        return;
    end

    accessxi.quest_packet_logs = {};
    for _, line in ipairs(packet_lines) do
        local key, port, area_key, mode, words_text = tostring(line or ''):match('^([^\t]*)\t([^\t]*)\t([^\t]*)\t([^\t]*)\t(.*)$');
        if (key ~= nil and key ~= '') then
            local words = T{};
            for value in tostring(words_text or ''):gmatch('[^,]+') do
                words:append(tonumber(value) or 0);
            end
            if (words:len() == 8) then
                accessxi.quest_packet_logs[key] = {
                    port = tonumber(port) or 0,
                    area_key = tostring(area_key or ''),
                    mode = tostring(mode or ''),
                    words = words,
                    source = 'cache',
                    identity = player_identity,
                };
            end
        end
    end
    accessxi.quest_packet_tick = tick();
    accessxi.quest_packet_player = player_name;
    accessxi.quest_packet_identity = player_identity;
    accessxi.quest_packet_source = 'cache';
    log_line(('quest packet cache restored player="%s" logs=%d'):fmt(
        accessxi.escape_probe_log_text(cached_player),
        accessxi.table_count(accessxi.quest_packet_logs or {})));
end

function accessxi.capture_quest_packet(e)
    if (e == nil or e.id ~= 0x056) then
        return;
    end

    local data = accessxi.packet_event_string(e, 'data_modified', 'size');
    if (data == '') then
        data = accessxi.packet_event_string(e, 'data', 'size');
    end
    if (data == '') then
        local ok, value = pcall(function () return e.data_modified; end);
        if (ok and type(value) == 'string') then
            data = value;
        end
    end
    if (data == '') then
        local ok, value = pcall(function () return e.data; end);
        if (ok and type(value) == 'string') then
            data = value;
        end
    end
    if (#data < 0x2C) then
        return;
    end

    local port = accessxi.packet_u16(data, 0x24 + 1);
    local area_key, mode = accessxi.quest_packet_log_for_port(port);
    if (area_key == '' or mode == '') then
        return;
    end
    if (type(accessxi.nav_mission_quest_sync_character) == 'function') then
        accessxi.nav_mission_quest_sync_character('quest-packet');
    end

    local quest_player = accessxi.current_player_name();
    local quest_identity = accessxi.current_player_identity();
    local quest_session_epoch = accessxi.current_objective_session_epoch();
    local words = accessxi.quest_packet_data_words(data);
    local key = accessxi.quest_packet_entry_key(area_key, mode);
    accessxi.quest_packet_logs = accessxi.quest_packet_logs or {};
    accessxi.quest_packet_logs[key] = {
        port = port,
        area_key = area_key,
        mode = mode,
        words = words,
        source = 'packet_in_056',
        identity = quest_identity,
        session_epoch = quest_session_epoch,
    };
    accessxi.quest_packet_tick = tick();
    if (quest_player ~= '') then
        accessxi.quest_packet_player = quest_player;
    end
    accessxi.quest_packet_identity = quest_identity;
    accessxi.quest_packet_source = 'packet_in_056';
    accessxi.quest_packet_session_epoch = quest_session_epoch;
    accessxi.quest_packet_cache_loaded = true;
    accessxi.save_quest_packet_cache();

    local words_text = T{};
    for index = 1, 8 do
        words_text:append(('%08X'):fmt(tonumber(words[index]) or 0));
    end
    local log_key = ('%04X:%s'):fmt(port, words_text:concat(','));
    if (log_key ~= tostring(accessxi.last_quest_packet_key or '')) then
        accessxi.last_quest_packet_key = log_key;
        log_line(('quest packet id=0x%03X len=%d port=0x%04X area="%s" mode="%s" words="%s"'):fmt(
            tonumber(e.id) or 0,
            #data,
            port,
            area_key,
            mode,
            words_text:concat(',')));
        if (type(accessxi.queue_mission_quest_state_change) == 'function') then
            accessxi.queue_mission_quest_state_change(
                'quest', ('packet-0x056-%04X'):fmt(port));
        end
    end
end

function accessxi.save_roe_active_packet_cache()
    local rows = accessxi.roe_active_records;
    if (type(rows) ~= 'table' or #rows <= 0) then
        return;
    end

    local player_name = accessxi.current_player_name();
    if (player_name == '') then
        return;
    end

    local f = io.open(accessxi.roe_active_cache_path, 'w');
    if (f == nil) then
        return;
    end

    f:write(('player=%s\n'):fmt(player_name));
    f:write(('saved_at=%d\n'):fmt(os.time()));
    for index, row in ipairs(rows) do
        if (type(row) == 'table' and (tonumber(row.id) or 0) > 0) then
            f:write(('row=%d\t%d\t%d\t%d\t%d\n'):fmt(
                index,
                tonumber(row.slot) or 0,
                tonumber(row.id) or 0,
                tonumber(row.progress) or 0,
                row.timed == true and 1 or 0));
        end
    end
    f:close();
end

function accessxi.restore_roe_active_packet_cache_if_needed()
    if (accessxi.roe_active_cache_loaded == true or #(accessxi.roe_active_records or {}) > 0) then
        return;
    end
    accessxi.roe_active_cache_loaded = true;

    local player_name = accessxi.current_player_name();
    if (player_name == '') then
        return;
    end

    local f = io.open(accessxi.roe_active_cache_path, 'r');
    if (f == nil) then
        return;
    end

    local values = {};
    local row_lines = T{};
    for line in f:lines() do
        local row = tostring(line or ''):match('^row=(.*)$');
        if (row ~= nil) then
            row_lines:append(row);
        else
            local key, value = tostring(line or ''):match('^([^=]+)=(.*)$');
            if (key ~= nil) then
                values[key] = value or '';
            end
        end
    end
    f:close();

    local cached_player = tostring(values.player or '');
    if (cached_player == '' or cached_player ~= player_name) then
        log_line(('roe active packet cache ignored cachedPlayer="%s" player="%s"'):fmt(
            accessxi.escape_probe_log_text(cached_player),
            accessxi.escape_probe_log_text(player_name)));
        return;
    end

    local saved_at = tonumber(values.saved_at);
    local now = os.time();
    local max_age = 1800;
    if (saved_at == nil or saved_at <= 0 or (now - saved_at) > max_age) then
        log_line(('roe active packet cache ignored stale age=%d maxAge=%d player="%s"'):fmt(
            saved_at ~= nil and (now - saved_at) or -1,
            max_age,
            accessxi.escape_probe_log_text(cached_player)));
        return;
    end

    local by_index = {};
    local max_index = 0;
    for _, line in ipairs(row_lines) do
        local index, slot, record_id, progress, timed = tostring(line or ''):match('^([^\t]*)\t([^\t]*)\t([^\t]*)\t([^\t]*)\t([^\t]*)$');
        index = tonumber(index) or 0;
        record_id = tonumber(record_id) or 0;
        if (index > 0 and index <= 64 and record_id > 0) then
            by_index[index] = {
                id = record_id,
                progress = tonumber(progress) or 0,
                slot = tonumber(slot) or 0,
                timed = (tonumber(timed) or 0) ~= 0,
            };
            if (index > max_index) then
                max_index = index;
            end
        end
    end

    local rows = T{};
    for index = 1, max_index do
        if (type(by_index[index]) == 'table') then
            rows:append(by_index[index]);
        end
    end
    if (rows:len() <= 0) then
        return;
    end

    accessxi.roe_active_records = rows;
    accessxi.roe_active_tick = tick();
    accessxi.roe_active_player = player_name;
    log_line(('roe active packet cache restored player="%s" active=%d age=%d'):fmt(
        accessxi.escape_probe_log_text(player_name),
        rows:len(),
        saved_at ~= nil and (now - saved_at) or -1));
end

function accessxi.capture_roe_packet(e)
    if (e == nil or (e.id ~= 0x111 and e.id ~= 0x112)) then
        return;
    end

    local data = accessxi.packet_event_string(e, 'data_modified', 'size');
    if (data == '') then
        data = accessxi.packet_event_string(e, 'data', 'size');
    end
    if (data == '') then
        local ok, value = pcall(function () return e.data_modified; end);
        if (ok and type(value) == 'string') then
            data = value;
        end
    end
    if (data == '') then
        local ok, value = pcall(function () return e.data; end);
        if (ok and type(value) == 'string') then
            data = value;
        end
    end

    if (e.id == 0x111) then
        if (#data < 0x104) then
            return;
        end

        local active = T{};
        local timed_packed = accessxi.packet_u32(data, 0x04 + (63 * 4) + 1);
        local timed_id = bit.band(timed_packed, 0x0FFF);
        local timed_progress = bit.rshift(timed_packed, 12);
        if (timed_id > 0) then
            active:append({ id = timed_id, progress = timed_progress, slot = 64, timed = true });
        end

        for index = 0, 29 do
            local packed = accessxi.packet_u32(data, 0x04 + (index * 4) + 1);
            local record_id = bit.band(packed, 0x0FFF);
            local progress = bit.rshift(packed, 12);
            if (record_id > 0) then
                active:append({ id = record_id, progress = progress, slot = index + 1 });
            end
        end

        accessxi.roe_active_records = active;
        accessxi.roe_active_tick = tick();
        accessxi.roe_active_player = accessxi.current_player_name();
        accessxi.roe_active_cache_loaded = true;
        accessxi.save_roe_active_packet_cache();

        local parts = T{};
        for _, row in ipairs(active) do
            local suffix = row.timed == true and 't' or '';
            parts:append(('%d:%d/%d%s'):fmt(row.slot, row.id, row.progress, suffix));
            if (parts:len() >= 32) then
                break;
            end
        end
        local key = parts:concat(',');
        if (key ~= tostring(accessxi.last_roe_active_packet_key or '')) then
            accessxi.last_roe_active_packet_key = key;
            log_line(('roe packet id=0x111 len=%d active=%d rows="%s"'):fmt(
                #data,
                active:len(),
                accessxi.escape_probe_log_text_wide(key)));
        end
    elseif (e.id == 0x112) then
        if (#data < 0x88) then
            return;
        end

        local offset = accessxi.packet_u16(data, 0x84 + 1);
        local completed = T{};
        for byte_index = 0, 127 do
            local value = accessxi.packet_byte(data, 0x04 + byte_index + 1);
            if (value ~= 0) then
                for bit_index = 0, 7 do
                    if (bit.band(value, bit.lshift(1, bit_index)) ~= 0) then
                        completed:append((offset * 1024) + (byte_index * 8) + bit_index);
                    end
                end
            end
        end

        accessxi.roe_complete_pages = accessxi.roe_complete_pages or {};
        accessxi.roe_complete_pages[offset] = completed;
        accessxi.roe_complete_tick = tick();

        local parts = T{};
        for index, record_id in ipairs(completed) do
            parts:append(tostring(record_id));
            if (index >= 32) then
                break;
            end
        end
        local key = ('%d:%s'):fmt(offset, parts:concat(','));
        if (key ~= tostring(accessxi.last_roe_complete_packet_key or '')) then
            accessxi.last_roe_complete_packet_key = key;
            log_line(('roe packet id=0x112 len=%d offset=%d completed=%d ids="%s"'):fmt(
                #data,
                offset,
                completed:len(),
                accessxi.escape_probe_log_text_wide(parts:concat(','))));
        end
    end
end

function accessxi.capture_mission_packet(e)
    if (e == nil or e.id ~= 0x056) then
        return;
    end

    local data = accessxi.packet_event_string(e, 'data_modified', 'size');
    if (data == '') then
        data = accessxi.packet_event_string(e, 'data', 'size');
    end
    if (data == '') then
        local ok, value = pcall(function () return e.data_modified; end);
        if (ok and type(value) == 'string') then
            data = value;
        end
    end
    if (data == '') then
        local ok, value = pcall(function () return e.data; end);
        if (ok and type(value) == 'string') then
            data = value;
        end
    end
    if (#data < 0x2C) then
        log_line(('mission packet short len=%d hex="%s"'):fmt(#data, accessxi.packet_hex_limit(data, 80)));
        return;
    end

    local base = 0x04;
    local packet_port = accessxi.packet_u16(data, 0x24 + 1);
    local info = {
        nation = accessxi.packet_u32(data, base + 0x00 + 1),
        nation_mission = accessxi.packet_u32(data, base + 0x04 + 1),
        zilart = accessxi.packet_u32(data, base + 0x08 + 1),
        cop = accessxi.packet_u32(data, base + 0x0C + 1),
        cop_status = accessxi.packet_u32(data, base + 0x10 + 1),
        addons = accessxi.packet_u16(data, base + 0x14 + 1),
        tales = accessxi.packet_u16(data, base + 0x16 + 1),
        soa = accessxi.packet_u32(data, base + 0x18 + 1),
        rov = accessxi.packet_u32(data, base + 0x1C + 1),
        port = packet_port,
        port_raw = packet_port,
    };
    local key = accessxi.packet_hex_limit(data, 96);
    local mission_state_packet = packet_port == 0xFFFF or packet_port == 0x0080
        or packet_port == 0x00C0 or packet_port == 0x00D0;
    if (mission_state_packet and type(accessxi.nav_mission_quest_sync_character) == 'function') then
        accessxi.nav_mission_quest_sync_character('mission-packet');
    end
    local previous_main = mission_state_packet and accessxi.mission_packet_main or nil;
    local previous_identity = mission_state_packet
        and tostring(accessxi.mission_packet_identity or ''):lower() or '';
    local previous_session_epoch = mission_state_packet
        and tonumber(accessxi.mission_packet_session_epoch) or 0;
    local mission_player = accessxi.current_player_name();
    local mission_identity = accessxi.current_player_identity();
    local mission_session_epoch = accessxi.current_objective_session_epoch();
    if (mission_state_packet and mission_player ~= '') then
        accessxi.mission_packet_player = mission_player;
    end
    if (mission_state_packet) then
        accessxi.mission_packet_session_epoch = mission_session_epoch;
    end
    if (packet_port == 0xFFFF) then
        accessxi.mission_packet_main = info;
        accessxi.mission_packet_identity = mission_identity;
        accessxi.mission_packet_source = 'packet_in_056';
        accessxi.mission_packet_tick = tick();
        accessxi.mission_packet_hex = key;
        accessxi.mission_packet_cache_loaded = true;
        accessxi.save_mission_packet_cache();
        local nations = { [0] = "San d'Oria", [1] = 'Bastok', [2] = 'Windurst' };
        local previous_nation = tonumber(type(previous_main) == 'table'
            and previous_main.nation or nil);
        local previous_mission = tonumber(type(previous_main) == 'table'
            and previous_main.nation_mission or nil);
        local current_nation = tonumber(info.nation);
        local current_mission = tonumber(info.nation_mission);
        local previous_context = nations[previous_nation];
        local current_context = nations[current_nation];
        if (previous_context ~= nil and current_context ~= nil
            and previous_mission ~= nil and previous_mission >= 0
            and current_mission ~= nil and current_mission >= 0
            and (previous_nation ~= current_nation
                or previous_mission ~= current_mission)
            and mission_identity ~= '' and mission_session_epoch > 0
            and previous_identity == tostring(mission_identity):lower()
            and previous_session_epoch == mission_session_epoch
            and type(accessxi.nav_mission_quest_reduce_signal) == 'function') then
            local world_id = tonumber(accessxi.current_player_world_id()) or 0;
            if (world_id > 0) then
                if (tonumber(accessxi.objective_signal_session_epoch)
                    ~= mission_session_epoch) then
                    accessxi.objective_signal_session_epoch = mission_session_epoch;
                    accessxi.objective_signal_sequence = 0;
                end
                local sequence = (tonumber(accessxi.objective_signal_sequence) or 0) + 1;
                accessxi.objective_signal_sequence = sequence;
                pcall(accessxi.nav_mission_quest_reduce_signal, {
                    kind = 'native-objective-state', category = 'mission',
                    previous_native_key = ('mission:%s:%d'):fmt(
                        previous_context, previous_mission + 1),
                    current_native_key = ('mission:%s:%d'):fmt(
                        current_context, current_mission + 1),
                    previous_state = 'active', current_state = 'replaced',
                    scope_complete = true,
                    character_identity = mission_identity, world_id = world_id,
                    session_epoch = mission_session_epoch, sequence = sequence,
                    tick = tick(),
                    corpus_revision = tonumber(accessxi.nav_catalog_revision) or 0,
                });
            end
        end
    elseif (packet_port == 0x0080) then
        accessxi.mission_packet_ahturghan = {
            assault = accessxi.packet_u32(data, base + 0x10 + 1),
            toau = accessxi.packet_u32(data, base + 0x14 + 1),
            wotg = accessxi.packet_u32(data, base + 0x18 + 1),
            campaign = accessxi.packet_u32(data, base + 0x1C + 1),
            port = packet_port,
        };
        accessxi.mission_packet_ahturghan_tick = tick();
        accessxi.mission_packet_ahturghan_identity = mission_identity;
        accessxi.mission_packet_ahturghan_source = 'packet_in_056';
        accessxi.save_mission_packet_cache();
    elseif (packet_port == 0x00C0) then
        accessxi.mission_packet_ahturghan_complete = T{
            accessxi.packet_u32(data, base + 0x10 + 1),
            accessxi.packet_u32(data, base + 0x14 + 1),
            accessxi.packet_u32(data, base + 0x18 + 1),
            accessxi.packet_u32(data, base + 0x1C + 1)
        };
        accessxi.mission_packet_ahturghan_complete_tick = tick();
        accessxi.mission_packet_ahturghan_complete_identity = mission_identity;
        accessxi.mission_packet_ahturghan_complete_source = 'packet_in_056';
        accessxi.save_mission_packet_cache();
    elseif (packet_port == 0x00D0) then
        accessxi.mission_packet_nations_complete = accessxi.quest_packet_data_words(data);
        accessxi.mission_packet_nations_complete_tick = tick();
        accessxi.mission_packet_nations_complete_player = mission_player;
        accessxi.mission_packet_nations_complete_identity = mission_identity;
        accessxi.mission_packet_nations_complete_source = 'packet_in_056';
    end

    if (not mission_state_packet) then
        return;
    end

    local log_key = ('%04X:%s'):fmt(packet_port, key);
    if (log_key ~= tostring(accessxi.last_mission_packet_key or '')) then
        accessxi.last_mission_packet_key = log_key;
        local assault_complete = accessxi.mission_packet_ahturghan_complete or {};
        log_line(('mission packet id=0x%03X len=%d port=0x%04X rawPort=0x%04X nation=%d nationMission=%d zilart=%d cop=%d copStatus=0x%08X addons=0x%08X tales=0x%08X soa=%d rov=%d ahturghanAssault=%d ahturghanToau=%d ahturghanWotg=%d assaultComplete=%08X,%08X,%08X,%08X hex="%s"'):fmt(
            tonumber(e.id) or 0,
            #data,
            info.port,
            info.port_raw,
            info.nation,
            info.nation_mission,
            info.zilart,
            info.cop,
            info.cop_status,
            info.addons,
            info.tales,
            info.soa,
            info.rov,
            packet_port == 0x0080 and accessxi.packet_u32(data, base + 0x10 + 1) or -1,
            packet_port == 0x0080 and accessxi.packet_u32(data, base + 0x14 + 1) or -1,
            packet_port == 0x0080 and accessxi.packet_u32(data, base + 0x18 + 1) or -1,
            tonumber(assault_complete[1]) or 0,
            tonumber(assault_complete[2]) or 0,
            tonumber(assault_complete[3]) or 0,
            tonumber(assault_complete[4]) or 0,
            key));
        if (mission_state_packet
            and type(accessxi.queue_mission_quest_state_change) == 'function') then
            accessxi.queue_mission_quest_state_change(
                'mission', ('packet-0x056-%04X'):fmt(packet_port));
        end
    end
end

