function accessxi.current_cop_mission_value()
    accessxi.restore_mission_packet_cache_if_needed();
    local packet = accessxi.mission_packet_main or {};
    local cop = tonumber(packet.cop);
    local age = -1;
    if ((tonumber(accessxi.mission_packet_tick) or 0) > 0) then
        age = math.floor(tick() - (tonumber(accessxi.mission_packet_tick) or 0));
    end

    return cop, age;
end

function accessxi.cop_rom_u32(data, offset)
    offset = tonumber(offset) or 0;
    local b0 = string.byte(data, offset + 1) or 0;
    local b1 = string.byte(data, offset + 2) or 0;
    local b2 = string.byte(data, offset + 3) or 0;
    local b3 = string.byte(data, offset + 4) or 0;
    return b0 + (b1 * 0x100) + (b2 * 0x10000) + (b3 * 0x1000000);
end

function accessxi.cop_rom_decoded_u32(data, offset)
    offset = tonumber(offset) or 0;
    local b0 = 255 - (string.byte(data, offset + 1) or 255);
    local b1 = 255 - (string.byte(data, offset + 2) or 255);
    local b2 = 255 - (string.byte(data, offset + 3) or 255);
    local b3 = 255 - (string.byte(data, offset + 4) or 255);
    return b0 + (b1 * 0x100) + (b2 * 0x10000) + (b3 * 0x1000000);
end

function accessxi.cop_rom_decoded_text(data, offset, max_len)
    offset = tonumber(offset) or 0;
    max_len = tonumber(max_len) or 0;
    local chars = T{};
    for i = 0, max_len - 1 do
        local raw = string.byte(data, offset + i + 1);
        if (raw == nil) then
            break;
        end
        local value = 255 - raw;
        if (value == 0) then
            break;
        end
        chars:append(string.char(value));
    end

    local text = chars:concat('');
    text = text:gsub('^_+', '');
    return accessxi.plain_native_menu_label(accessxi.survival_guide_text(text));
end

function accessxi.cop_rom_decoded_text_runs(data, offset, max_len)
    offset = tonumber(offset) or 0;
    max_len = tonumber(max_len) or 0;

    local runs = T{};
    local chars = T{};
    local run_offset = 0;
    local function flush()
        if (chars:len() <= 0) then
            return;
        end
        local text = accessxi.survival_guide_text(chars:concat(''));
        text = text:gsub('^_+', ''):gsub('^%s+', ''):gsub('%s+$', '');
        if (text ~= '' and #text <= 240 and text:match('^[%p%s]+$') == nil) then
            runs:append(T{ offset = run_offset, text = text });
        end
        chars = T{};
    end

    for i = 0, max_len - 1 do
        local raw = string.byte(data, offset + i + 1);
        if (raw == nil) then
            break;
        end
        local value = 255 - raw;
        if (value == 0 or value < 0x20) then
            flush();
        else
            if (chars:len() == 0) then
                run_offset = i;
            end
            chars:append(string.char(value));
        end
    end
    flush();

    return runs;
end

function accessxi.mission_rom_order_text_from_runs(runs)
    if (type(runs) ~= 'table') then
        return '', '', T{};
    end

    local heading = '';
    local body = T{};
    local headingless_body = T{};
    local collecting = false;
    local seen_label = false;
    for _, run in ipairs(runs) do
        local text = accessxi.survival_guide_text(tostring(run.text or ''));
        text = text:gsub('^%s+', ''):gsub('%s+$', '');
        if (text ~= '') then
            if (seen_label and not collecting) then
                headingless_body:append(text);
            end
            if (collecting) then
                body:append(text);
            elseif (text:eq('Mission Orders:', true) or text:eq('Mission Orders', true)) then
                heading = text:gsub(':%s*$', '');
                collecting = true;
            elseif (text:lower():find('^mission orders:%s*') ~= nil) then
                heading = 'Mission Orders';
                local inline_body = text:gsub('^[Mm]ission [Oo]rders:%s*', '');
                if (inline_body ~= '') then
                    body:append(inline_body);
                end
                collecting = true;
            end
            seen_label = true;
        end
    end

    if (heading == '' and body:len() == 0 and headingless_body:len() > 0) then
        return '', accessxi.survival_guide_text(headingless_body:concat(' ')), headingless_body;
    end
    if (heading == '' or body:len() == 0) then
        return '', '', T{};
    end

    return heading, accessxi.survival_guide_text(body:concat(' ')), body;
end

accessxi.mission_rom_tables = T{
    ["San d'Oria"] = { path = accessxi.ffxi_path('ROM\\176\\67.DAT'), packet = 'nation_mission' },
    ['Bastok'] = { path = accessxi.ffxi_path('ROM\\176\\68.DAT'), packet = 'nation_mission' },
    ['Windurst'] = { path = accessxi.ffxi_path('ROM\\176\\69.DAT'), packet = 'nation_mission' },
    ['Rise of the Zilart'] = { path = accessxi.ffxi_path('ROM\\176\\70.DAT'), packet = 'zilart' },
    ['Chains of Promathia'] = { path = accessxi.ffxi_path('ROM\\176\\71.DAT'), packet = 'cop' },
    ['Assault'] = { path = accessxi.ffxi_path('ROM\\176\\72.DAT'), packet = 'ahturghan_assault' },
    ['Treasures of Aht Urhgan'] = { path = accessxi.ffxi_path('ROM\\176\\73.DAT'), packet = 'ahturghan_toau' },
    ['Campaign'] = { path = accessxi.ffxi_path('ROM\\196\\6.DAT'), packet = '' },
    ['Wings of the Goddess'] = { path = accessxi.ffxi_path('ROM\\196\\7.DAT'), packet = 'ahturghan_wotg' },
    ['Seekers of Adoulin'] = { path = accessxi.ffxi_path('ROM\\293\\69.DAT'), packet = 'soa' },
    ["Rhapsodies of Vana'diel"] = { path = accessxi.ffxi_path('ROM\\333\\4.DAT'), packet = 'rov' },
    ['The Voracious Resurgence'] = { path = accessxi.ffxi_path('ROM\\364\\36.DAT'), packet = 'tales' },
    ['A Crystalline Prophecy'] = { path = accessxi.ffxi_path('ROM\\222\\18.DAT'), packet = 'acp' },
    ["A Moogle Kupo d'Etat"] = { path = accessxi.ffxi_path('ROM\\223\\12.DAT'), packet = 'mkd' },
    ['A Shantotto Ascension'] = { path = accessxi.ffxi_path('ROM\\223\\13.DAT'), packet = 'asa' },
};

function accessxi.mission_rom_table_for_context(context)
    return accessxi.mission_rom_tables[tostring(context or '')];
end

function accessxi.mission_rom_relpath(path)
    return tostring(path or ''):match('FINAL FANTASY XI\\(.+)$') or tostring(path or '');
end

function accessxi.mission_menu_resource_text(label)
    label = tostring(label or '');
    if (label == '') then
        return nil, '';
    end
    if (accessxi.mission_menu_resource_texts == nil) then
        accessxi.mission_menu_resource_texts = {};
        local path = accessxi.ffxi_path('ROM\\97\\40.DAT');
        local f = io.open(path, 'rb');
        if (f ~= nil) then
            local data = f:read('*all') or '';
            f:close();
            for text in data:gmatch('([^%z]+)') do
                text = accessxi.plain_native_menu_label(text);
                if (text == 'No current missions.' or text == 'No completed missions.' or text == 'Not allowed under current allegiance.') then
                    accessxi.mission_menu_resource_texts[text] = text;
                end
            end
            accessxi.mission_menu_resource_texts_path = path;
        end
    end

    local text = accessxi.mission_menu_resource_texts[label];
    if (text == nil) then
        return nil, '';
    end
    return text, ('%s mission menu text "%s"'):fmt(accessxi.mission_rom_relpath(tostring(accessxi.mission_menu_resource_texts_path or '')), text);
end

function accessxi.missions_menu_visible_span(child)
    child = tonumber(child) or 0;
    if (not accessxi.is_probe_pointer(child)) then
        return 0, 0;
    end
    local visible_last = read_u32(child + 0x40) or 0;
    local total_last = read_u32(child + 0x44) or 0;
    if (visible_last < 0 or visible_last > 0xFFFF) then
        visible_last = 0;
    end
    if (total_last < 0 or total_last > 0xFFFF) then
        total_last = 0;
    end
    return visible_last, total_last;
end

function accessxi.missions_menu_runtime_slot(child, raw)
    child = tonumber(child) or 0;
    raw = tonumber(raw) or 0;
    if (not accessxi.is_probe_pointer(child)) then
        return nil, nil, 0, -1, 'mission-native-runtime-no-child';
    end

    local raw_lo = bit.band(raw, 0xFFFF);
    if (raw_lo < 0 or raw_lo > 0x7F) then
        return nil, nil, 0, raw_lo, 'mission-native-runtime-slot-out-of-range';
    end

    local block = read_u32(child + 0x20) or 0;
    if (not accessxi.is_probe_pointer(block)) then
        return nil, nil, block, raw_lo, 'mission-native-runtime-no-block';
    end

    local offset = block + (raw_lo * 8);
    local row_id = read_i32(offset);
    local flags = read_u32(offset + 4);
    if (row_id == nil or flags == nil) then
        return nil, nil, block, raw_lo, 'mission-native-runtime-unreadable-slot';
    end

    return tonumber(row_id) or 0, tonumber(flags) or 0, block, raw_lo, '';
end

function accessxi.missions_menu_runtime_row(context, rows, child, raw, kind, current_age)
    if (type(rows) ~= 'table') then
        return nil, '', false;
    end

    kind = tostring(kind or ''):lower();
    local row_id, flags, block, raw_lo, miss = accessxi.missions_menu_runtime_slot(child, raw);
    if (row_id == nil) then
        return nil, tostring(miss or ''), false;
    end

    local source_prefix = ('mission-native-runtime-%s'):fmt(kind ~= '' and kind or 'row');
    if (kind == 'current' and row_id == -3) then
        local blocked_row, blocked_source = accessxi.missions_menu_resource_status_row('Not allowed under current allegiance.', 'mission-native-runtime-current-not-allowed-resource', current_age);
        if (blocked_row ~= nil) then
            return blocked_row, ('%s-not-allowed:slot=%d id=%d flags=0x%08X block=0x%08X:%s'):fmt(source_prefix, raw_lo, row_id, flags, block, blocked_source), true;
        end
        return nil, ('%s-not-allowed-resource-missing:slot=%d id=%d flags=0x%08X block=0x%08X'):fmt(source_prefix, raw_lo, row_id, flags, block), true;
    elseif (kind == 'current' and row_id == -4) then
        local empty_row, empty_source = accessxi.missions_menu_resource_empty_row('current', child, current_age);
        if (empty_row ~= nil) then
            return empty_row, ('%s-empty:slot=%d id=%d flags=0x%08X block=0x%08X:%s'):fmt(source_prefix, raw_lo, row_id, flags, block, empty_source), true;
        end
        return nil, ('%s-empty-resource-missing:slot=%d id=%d flags=0x%08X block=0x%08X'):fmt(source_prefix, raw_lo, row_id, flags, block), true;
    elseif (kind == 'completed' and row_id == -5) then
        local empty_row, empty_source = accessxi.missions_menu_resource_empty_row('completed', child, current_age);
        if (empty_row ~= nil) then
            return empty_row, ('%s-empty:slot=%d id=%d flags=0x%08X block=0x%08X:%s'):fmt(source_prefix, raw_lo, row_id, flags, block, empty_source), true;
        end
        return nil, ('%s-empty-resource-missing:slot=%d id=%d flags=0x%08X block=0x%08X'):fmt(source_prefix, raw_lo, row_id, flags, block), true;
    elseif (row_id < 0) then
        return nil, ('%s-sentinel:slot=%d id=%d flags=0x%08X block=0x%08X'):fmt(source_prefix, raw_lo, row_id, flags, block), true;
    end

    local ordinal = row_id + 1;
    local row = rows[ordinal];
    if (row == nil) then
        return nil, ('%s-missing-row:slot=%d id=%d ordinal=%d count=%d flags=0x%08X block=0x%08X'):fmt(source_prefix, raw_lo, row_id, ordinal, tonumber(rows.count) or 0, flags, block), true;
    end

    if (accessxi.missions_menu_rom_placeholder_label(row.label or '')) then
        return nil, ('%s-placeholder-row:slot=%d id=%d ordinal=%d label="%s" flags=0x%08X block=0x%08X'):fmt(
            source_prefix,
            raw_lo,
            row_id,
            ordinal,
            accessxi.escape_probe_log_text(row.label or ''),
            flags,
            block), true;
    end

    return row, ('%s-row:slot=%d id=%d ordinal=%d flags=0x%08X block=0x%08X'):fmt(source_prefix, raw_lo, row_id, ordinal, flags, block), true;
end

function accessxi.missions_menu_resource_status_row(label_key, status_source, current_age)
    local label, source = accessxi.mission_menu_resource_text(label_key);
    if (label == nil or label == '') then
        return nil, '';
    end
    return {
        label = label,
        status = '',
        status_age = tonumber(current_age) or -1,
        status_source = tostring(status_source or ''),
        mission_id = 0,
        next_mission_id = 0,
        source = source
    }, source;
end

function accessxi.missions_menu_resource_empty_row(kind, child, current_age)
    kind = tostring(kind or ''):lower();
    local label_key = '';
    local status_source = '';
    if (kind == 'current') then
        label_key = 'No current missions.';
        status_source = 'mission-empty-current-resource';
    elseif (kind == 'completed') then
        label_key = 'No completed missions.';
        status_source = 'mission-empty-completed-resource';
    else
        return nil, '';
    end

    return accessxi.missions_menu_resource_status_row(label_key, status_source, current_age);
end

function accessxi.missions_menu_empty_row_allowed(context, kind)
    context = tostring(context or '');
    kind = tostring(kind or ''):lower();
    if (kind == 'current') then
        return context:eq('Assault', true)
            or context:eq('Campaign', true);
    end
    if (kind == 'completed') then
        return context:eq('Campaign', true)
            or context:eq('The Voracious Resurgence', true);
    end
    return false;
end

function accessxi.missions_menu_nation_context_id(context)
    context = tostring(context or '');
    if (context:eq('San d\'Oria', true)) then
        return 0;
    elseif (context:eq('Bastok', true)) then
        return 1;
    elseif (context:eq('Windurst', true)) then
        return 2;
    end
    return nil;
end

function accessxi.missions_menu_nation_current_sentinel_row(context, current_value, current_age)
    if ((tonumber(current_value) or -1) ~= 65535) then
        return nil, '';
    end

    local context_id = accessxi.missions_menu_nation_context_id(context);
    if (context_id == nil) then
        return nil, '';
    end

    accessxi.restore_mission_packet_cache_if_needed();
    local nation = tonumber((accessxi.mission_packet_main or {}).nation);
    if (nation == nil) then
        return nil, 'mission-nation-current-sentinel-no-allegiance';
    end

    local label_key = 'Not allowed under current allegiance.';
    local status_source = 'mission-nation-current-not-allowed-resource';
    if (nation == context_id) then
        label_key = 'No current missions.';
        status_source = 'mission-nation-current-empty-resource';
    end

    local row, source = accessxi.missions_menu_resource_status_row(label_key, status_source, current_age);
    if (row == nil) then
        return nil, '';
    end
    return row, ('mission-nation-current-sentinel:context=%s nation=%d value=%d:%s'):fmt(tostring(context or ''), nation, tonumber(current_value) or -1, source);
end

function accessxi.missions_menu_nation_completed_empty_row(context, ordinal, child, current_value, current_age)
    if ((tonumber(current_value) or -1) ~= 65535 or (tonumber(ordinal) or 0) ~= 1) then
        return nil, '';
    end
    if (accessxi.missions_menu_nation_context_id(context) == nil) then
        return nil, '';
    end

    local visible_last = accessxi.missions_menu_visible_span(child);
    if (visible_last <= 0 or visible_last > 4) then
        return nil, '';
    end

    local row, source = accessxi.missions_menu_resource_empty_row('completed', child, current_age);
    if (row == nil) then
        return nil, '';
    end
    return row, ('mission-nation-completed-empty:visibleLast=%d value=%d:%s'):fmt(visible_last, tonumber(current_value) or -1, source);
end

function accessxi.missions_menu_rom_placeholder_label(label)
    label = tostring(label or '');
    if (label == '') then
        return true;
    end
    if (label:match('^AS~') ~= nil or label:match('^ATV') ~= nil or label:match('^ZL') ~= nil) then
        return true;
    end
    return false;
end

function accessxi.missions_menu_has_leading_title_row(context, rows)
    if (type(rows) ~= 'table') then
        return false;
    end
    local row = rows[1];
    if (row == nil or (tonumber(row.mission_id) or 0) ~= 0) then
        return false;
    end
    return tostring(row.label or ''):eq(tostring(context or ''), true);
end

function accessxi.missions_menu_completed_row_from_progress(context, rows, selected, ordinal, current_value, current_age, child)
    if (type(rows) ~= 'table') then
        return nil, '';
    end
    context = tostring(context or '');
    selected = tonumber(selected) or 0;
    ordinal = tonumber(ordinal) or 0;
    current_value = tonumber(current_value);
    if (current_value == nil) then
        return nil, 'mission-rom-completed-progress-missing';
    end

    local context_id = accessxi.missions_menu_nation_context_id(context);
    if (context_id ~= nil and current_value == 65535) then
        accessxi.restore_mission_packet_cache_if_needed();
        local nation = tonumber((accessxi.mission_packet_main or {}).nation);
        if (nation ~= nil and nation ~= context_id) then
            current_value = 0;
        end
    end

    local completed = T{};
    if (current_value > 0) then
        for i = 1, tonumber(rows.count) or 0 do
            local row = rows[i];
            local mission_id = row ~= nil and (tonumber(row.mission_id) or 0) or 0;
            local next_id = row ~= nil and (tonumber(row.next_mission_id) or 0) or 0;
            local label = row ~= nil and tostring(row.label or '') or '';
            local include = false;
            if (i == 1 and mission_id == 0 and accessxi.missions_menu_has_leading_title_row(context, rows)) then
                include = true;
            elseif (mission_id > 0) then
                if (current_value == 65535) then
                    include = true;
                elseif (next_id > 0) then
                    include = current_value >= next_id;
                else
                    include = current_value > mission_id;
                end
            end

            if (include and not accessxi.missions_menu_rom_placeholder_label(label)) then
                completed:append(row);
            end
        end
    end

    if (completed:len() == 0) then
        if (ordinal == 1) then
            local visible_last = accessxi.missions_menu_visible_span(child);
            if (visible_last > 0 and visible_last <= 4) then
                local empty_row, empty_source = accessxi.missions_menu_resource_empty_row('completed', child, current_age);
                if (empty_row ~= nil) then
                    return empty_row, ('mission-rom-completed-progress-empty:%s value=%d age=%d'):fmt(empty_source, current_value, tonumber(current_age) or -1);
                end
            end
        end
        return nil, ('mission-rom-completed-progress-empty:value=%d age=%d'):fmt(current_value, tonumber(current_age) or -1);
    end

    local row = completed[ordinal];
    if (row == nil) then
        return nil, ('mission-rom-completed-progress-out-of-range:ordinal=%d count=%d value=%d age=%d'):fmt(ordinal, completed:len(), current_value, tonumber(current_age) or -1);
    end
    return row, ('mission-rom-completed-progress-row:selected=%d ordinal=%d value=%d age=%d'):fmt(selected, ordinal, current_value, tonumber(current_age) or -1);
end

function accessxi.missions_menu_zilart_current_row(rows, current_value)
    if (type(rows) ~= 'table') then
        return nil, '';
    end
    current_value = tonumber(current_value) or 0;
    if (current_value <= 0) then
        return nil, '';
    end

    local ordinal = current_value + 1;
    local row = rows[ordinal];
    if (row == nil or accessxi.missions_menu_rom_placeholder_label(row.label)) then
        return nil, ('mission-rom-zilart-current-ordinal-placeholder:%d'):fmt(ordinal);
    end
    return row, ('mission-rom-zilart-current-ordinal:value=%d ordinal=%d'):fmt(current_value, ordinal);
end

function accessxi.missions_menu_zero_progress_current_row(context, rows, current_value)
    if (type(rows) ~= 'table') then
        return nil, '';
    end
    current_value = tonumber(current_value);
    if (current_value ~= 0) then
        return nil, '';
    end
    if (accessxi.missions_menu_nation_context_id(context) ~= nil) then
        return nil, '';
    end

    local row = rows[1];
    if (row == nil or accessxi.missions_menu_rom_placeholder_label(row.label)) then
        return nil, '';
    end
    if ((tonumber(row.mission_id) or 0) ~= 0) then
        return nil, '';
    end
    return row, 'mission-rom-current-zero-progress-row:value=0 ordinal=1';
end

function accessxi.missions_menu_assault_completed_ids()
    accessxi.restore_mission_packet_cache_if_needed();
    local words = accessxi.mission_packet_ahturghan_complete or {};
    local saw_packet = false;
    for index = 1, 4 do
        if (tonumber(words[index]) ~= nil) then
            saw_packet = true;
        end
    end
    if (not saw_packet) then
        return nil, -1;
    end

    local ids = T{};
    for mission_id = 1, 127 do
        local word = tonumber(words[math.floor(mission_id / 32) + 1]) or 0;
        local mask = bit.lshift(1, mission_id % 32);
        if (bit.band(word, mask) ~= 0) then
            ids:append(mission_id);
        end
    end

    local age = -1;
    if ((tonumber(accessxi.mission_packet_ahturghan_complete_tick) or 0) > 0) then
        age = math.floor(tick() - (tonumber(accessxi.mission_packet_ahturghan_complete_tick) or 0));
    end
    return ids, age;
end

function accessxi.missions_menu_assault_completed_row(rows, selected, ordinal, child)
    if (type(rows) ~= 'table') then
        return nil, '';
    end
    selected = tonumber(selected) or 0;
    ordinal = tonumber(ordinal) or 0;

    local completed_ids, completed_age = accessxi.missions_menu_assault_completed_ids();
    local completed_count = (type(completed_ids) == 'table') and (tonumber(completed_ids:len()) or 0) or -1;
    if (ordinal == 1) then
        if (completed_count == 0) then
            local empty_row, empty_source = accessxi.missions_menu_resource_empty_row('completed', child, completed_age);
            if (empty_row ~= nil) then
                return empty_row, ('mission-rom-assault-completed-empty:%s'):fmt(empty_source);
            end
        end
    end

    if (type(completed_ids) ~= 'table') then
        return nil, 'mission-rom-assault-completed-packet-missing';
    end

    local mission_id = tonumber(completed_ids[ordinal]) or 0;
    if (mission_id <= 0) then
        return nil, ('mission-rom-assault-completed-out-of-range:%d'):fmt(ordinal);
    end

    local row = rows.by_mission_id ~= nil and rows.by_mission_id[mission_id] or nil;
    if (row == nil or accessxi.missions_menu_rom_placeholder_label(row.label)) then
        return nil, ('mission-rom-assault-completed-placeholder:%d'):fmt(mission_id);
    end
    return row, ('mission-rom-assault-visible-completed-row:selected=%d missionId=%d age=%d'):fmt(selected, mission_id, completed_age);
end

function accessxi.load_mission_rom_rows(context)
    local info = accessxi.mission_rom_table_for_context(context);
    if (info == nil) then
        return nil;
    end
    if (info.rows ~= nil) then
        return info.rows;
    end
    if (info.load_tried == true) then
        return nil;
    end
    info.load_tried = true;

    local path = tostring(info.path or '');
    local f = io.open(path, 'rb');
    if (f == nil) then
        log_line(('mission rom unavailable context="%s" path="%s"'):fmt(accessxi.escape_probe_log_text(tostring(context or '')), path));
        return nil;
    end
    local data = f:read('*all') or '';
    f:close();

    if (data:sub(1, 5) ~= 'd_msg') then
        log_line(('mission rom invalid context="%s" path="%s" magic="%s"'):fmt(accessxi.escape_probe_log_text(tostring(context or '')), path, accessxi.escape_probe_log_text(data:sub(1, 8))));
        return nil;
    end

    local stride = accessxi.cop_rom_u32(data, 0x20);
    local base = accessxi.cop_rom_u32(data, 0x18);
    local count = accessxi.cop_rom_u32(data, 0x28);
    if (stride <= 0 or base <= 0 or count <= 0 or (base + (stride * count)) > #data) then
        log_line(('mission rom invalid layout context="%s" path="%s" base=0x%X stride=%d count=%d len=%d'):fmt(
            accessxi.escape_probe_log_text(tostring(context or '')),
            path,
            base,
            stride,
            count,
            #data));
        return nil;
    end

    local rows = T{};
    rows.by_mission_id = T{};
    rows.path = path;
    rows.relpath = accessxi.mission_rom_relpath(path);
    rows.count = count;
    for ordinal = 1, count do
        local rec = base + ((ordinal - 1) * stride);
        local label = accessxi.cop_rom_decoded_text(data, rec + 0x3C, stride - 0x3C);
        local text_runs = accessxi.cop_rom_decoded_text_runs(data, rec + 0x3C, stride - 0x3C);
        local orders_heading, orders, orders_lines = accessxi.mission_rom_order_text_from_runs(text_runs);
        local mission_id = accessxi.cop_rom_decoded_u32(data, rec + 0x1C);
        if (label ~= '') then
            local row = {
                label = label,
                source = ('%s _msg xor row %d missionId=%d'):fmt(rows.relpath, ordinal, mission_id),
                mission_id = mission_id,
                rom_ordinal = ordinal,
                orders_heading = orders_heading,
                orders = orders,
                orders_lines = orders_lines,
                orders_source = orders ~= '' and ('%s _msg xor row %d mission orders'):fmt(rows.relpath, ordinal) or '',
            };
            rows[ordinal] = row;
            if ((tonumber(mission_id) or 0) > 0) then
                rows.by_mission_id[mission_id] = row;
            end
        end
    end
    for ordinal = 1, count do
        local row = rows[ordinal];
        local next_row = rows[ordinal + 1];
        if (row ~= nil and next_row ~= nil) then
            row.next_mission_id = tonumber(next_row.mission_id) or 0;
        end
    end

    info.rows = rows;
    log_line(('loaded mission rom context="%s" path="%s" count=%d stride=%d'):fmt(accessxi.escape_probe_log_text(tostring(context or '')), path, count, stride));
    return rows;
end

function accessxi.load_cop_mission_rom_rows()
    if (accessxi.cop_mission_rom_rows ~= nil) then
        return accessxi.cop_mission_rom_rows;
    end
    if (accessxi.cop_mission_rom_rows_load_tried == true) then
        return nil;
    end
    accessxi.cop_mission_rom_rows_load_tried = true;

    local path = accessxi.ffxi_path('ROM\\176\\71.DAT');
    local f = io.open(path, 'rb');
    if (f == nil) then
        log_line(('cop mission rom unavailable path="%s"'):fmt(path));
        return nil;
    end
    local data = f:read('*all') or '';
    f:close();

    if (data:sub(1, 5) ~= 'd_msg') then
        log_line(('cop mission rom invalid path="%s" magic="%s"'):fmt(path, accessxi.escape_probe_log_text(data:sub(1, 8))));
        return nil;
    end

    local stride = accessxi.cop_rom_u32(data, 0x20);
    local base = accessxi.cop_rom_u32(data, 0x18);
    local count = accessxi.cop_rom_u32(data, 0x28);
    if (stride <= 0 or base <= 0 or count <= 0 or (base + (stride * count)) > #data) then
        log_line(('cop mission rom invalid layout path="%s" base=0x%X stride=%d count=%d len=%d'):fmt(
            path,
            base,
            stride,
            count,
            #data));
        return nil;
    end

    local rows = T{};
    rows.by_mission_id = T{};
    rows.path = path;
    rows.count = count;
    for ordinal = 1, count do
        local rec = base + ((ordinal - 1) * stride);
        local label = accessxi.cop_rom_decoded_text(data, rec + 0x3C, stride - 0x3C);
        local text_runs = accessxi.cop_rom_decoded_text_runs(data, rec + 0x3C, stride - 0x3C);
        local orders_heading, orders, orders_lines = accessxi.mission_rom_order_text_from_runs(text_runs);
        local mission_id = accessxi.cop_rom_decoded_u32(data, rec + 0x1C);
        if (label ~= '') then
            local row = {
                label = label,
                source = ('ROM\\176\\71.DAT _msg xor row %d missionId=%d'):fmt(ordinal, mission_id),
                mission_id = mission_id,
                rom_ordinal = ordinal,
                orders_heading = orders_heading,
                orders = orders,
                orders_lines = orders_lines,
                orders_source = orders ~= '' and ('ROM\\176\\71.DAT _msg xor row %d mission orders'):fmt(ordinal) or '',
            };
            rows[ordinal] = row;
            if ((tonumber(mission_id) or 0) > 0) then
                rows.by_mission_id[mission_id] = row;
            end
        end
    end
    for ordinal = 1, count do
        local row = rows[ordinal];
        local next_row = rows[ordinal + 1];
        if (row ~= nil and next_row ~= nil) then
            row.next_mission_id = tonumber(next_row.mission_id) or 0;
        end
    end

    accessxi.cop_mission_rom_rows = rows;
    log_line(('loaded cop mission rom path="%s" count=%d stride=%d'):fmt(path, count, stride));
    return rows;
end

function accessxi.cop_mission_rom_ordinal_for_selected(selected)
    selected = tonumber(selected) or 0;
    if (selected <= 0) then
        return 0, 'cop-rom-invalid-selected';
    end

    local ordinal = selected;
    local client_section_rows = T{ 34, 40, 46 };
    for _, section_row in ipairs(client_section_rows) do
        if (selected == section_row) then
            return 0, ('cop-rom-client-section-row:%d'):fmt(section_row);
        end
        if (selected > section_row) then
            ordinal = ordinal - 1;
        end
    end

    return ordinal, 'cop-rom-selected-minus-client-section-rows';
end

function accessxi.cop_mission_rom_visible_ordinal(raw, page)
    raw = tonumber(raw);
    page = tonumber(page) or 0;
    if (raw == nil or page ~= 0) then
        return nil, '';
    end

    local raw_lo = bit.band(raw, 0xFFFF);
    if (raw_lo == 1) then
        return -1, 'cop-rom-visible-current-row';
    end
    if (raw_lo == 2) then
        return 0, 'cop-rom-visible-completed-section-row';
    end
    if (raw_lo >= 3) then
        return raw_lo - 2, 'cop-rom-visible-completed-row';
    end

    return nil, '';
end

function accessxi.current_mission_value_for_context(context)
    local info = accessxi.mission_rom_table_for_context(context);
    if (info == nil) then
        return nil, -1;
    end

    local packet_key = tostring(info.packet or '');
    if (packet_key == 'ahturghan_assault') then
        local packet = accessxi.mission_packet_ahturghan or {};
        local age = -1;
        if ((tonumber(accessxi.mission_packet_ahturghan_tick) or 0) > 0) then
            age = math.floor(tick() - (tonumber(accessxi.mission_packet_ahturghan_tick) or 0));
        end
        return tonumber(packet.assault), age;
    elseif (packet_key == 'ahturghan_toau') then
        local packet = accessxi.mission_packet_ahturghan or {};
        local age = -1;
        if ((tonumber(accessxi.mission_packet_ahturghan_tick) or 0) > 0) then
            age = math.floor(tick() - (tonumber(accessxi.mission_packet_ahturghan_tick) or 0));
        end
        return tonumber(packet.toau), age;
    elseif (packet_key == 'ahturghan_wotg') then
        local packet = accessxi.mission_packet_ahturghan or {};
        local age = -1;
        if ((tonumber(accessxi.mission_packet_ahturghan_tick) or 0) > 0) then
            age = math.floor(tick() - (tonumber(accessxi.mission_packet_ahturghan_tick) or 0));
        end
        return tonumber(packet.wotg), age;
    end

    accessxi.restore_mission_packet_cache_if_needed();
    local packet = accessxi.mission_packet_main or {};
    local age = -1;
    if ((tonumber(accessxi.mission_packet_tick) or 0) > 0) then
        age = math.floor(tick() - (tonumber(accessxi.mission_packet_tick) or 0));
    end
    local addons = tonumber(packet.addons);
    if (packet_key == 'acp') then
        if (addons == nil) then
            return nil, age;
        end
        return bit.band(addons, 0x000F), age;
    elseif (packet_key == 'mkd') then
        if (addons == nil) then
            return nil, age;
        end
        return math.floor(bit.band(addons, 0x00F0) / 0x10), age;
    elseif (packet_key == 'asa') then
        if (addons == nil) then
            return nil, age;
        end
        return math.floor(bit.band(addons, 0xFF00) / 0x100), age;
    end
    return tonumber(packet[packet_key]), age;
end

function accessxi.cop_mission_rom_current_row(rows, packet_cop)
    if (type(rows) ~= 'table') then
        return nil;
    end
    packet_cop = tonumber(packet_cop) or 0;
    if (packet_cop <= 0) then
        return nil;
    end

    local best = nil;
    for i = 1, tonumber(rows.count) or 0 do
        local row = rows[i];
        local mission_id = row ~= nil and (tonumber(row.mission_id) or 0) or 0;
        local next_id = row ~= nil and (tonumber(row.next_mission_id) or 0) or 0;
        if (mission_id > 0 and packet_cop >= mission_id and (next_id <= 0 or packet_cop < next_id)) then
            return row;
        elseif (mission_id > 0 and packet_cop >= mission_id) then
            best = row;
        end
    end

    return best;
end

function accessxi.mission_rom_current_row(rows, current_value)
    if (type(rows) ~= 'table') then
        return nil;
    end
    current_value = tonumber(current_value) or 0;
    if (current_value <= 0) then
        return nil;
    end

    local best = nil;
    for i = 1, tonumber(rows.count) or 0 do
        local row = rows[i];
        local mission_id = row ~= nil and (tonumber(row.mission_id) or 0) or 0;
        local next_id = row ~= nil and (tonumber(row.next_mission_id) or 0) or 0;
        if (mission_id > 0 and current_value >= mission_id and (next_id <= 0 or current_value < next_id)) then
            return row;
        elseif (mission_id > 0 and current_value >= mission_id) then
            best = row;
        end
    end

    return best;
end

function accessxi.cop_mission_rom_status(row)
    if (row == nil) then
        return '', -1, '';
    end

    local mission_id = tonumber(row.mission_id) or 0;
    local next_id = tonumber(row.next_mission_id) or 0;
    local packet_cop, packet_age = accessxi.current_cop_mission_value();
    if (packet_cop == nil or packet_cop <= 0 or mission_id <= 0) then
        return '', packet_age, 'no-current-cop-packet';
    end
    if (packet_cop < mission_id) then
        return 'Not yet reached', packet_age, 'mission-after-current-cop';
    end
    if (next_id > 0 and packet_cop >= next_id) then
        return 'Completed', packet_age, 'mission-before-current-cop';
    end
    return 'Current', packet_age, 'mission-current-cop-range';
end

function accessxi.mission_rom_status(context, row)
    if (row == nil) then
        return '', -1, '';
    end

    local mission_id = tonumber(row.mission_id) or 0;
    local next_id = tonumber(row.next_mission_id) or 0;
    local current_value, current_age = accessxi.current_mission_value_for_context(context);
    if (current_value == nil or current_value <= 0 or mission_id <= 0) then
        return '', current_age, 'no-current-mission-packet';
    end
    if (current_value < mission_id) then
        return 'Not yet reached', current_age, 'mission-after-current';
    end
    if (next_id > 0 and current_value >= next_id) then
        return 'Completed', current_age, 'mission-before-current';
    end
    return 'Current', current_age, 'mission-current-range';
end

function accessxi.mission_rom_row(context, selected, raw, page, child)
    local rows = accessxi.load_mission_rom_rows(context);
    if (type(rows) ~= 'table') then
        return nil, 'mission-rom-unavailable';
    end

    local current_value, current_age = accessxi.current_mission_value_for_context(context);
    local ordinal, source = accessxi.cop_mission_rom_visible_ordinal(raw, page);
    local visible_last = accessxi.missions_menu_visible_span(child);
    local row = nil;
    if (ordinal == -1) then
        local runtime_row, runtime_source, runtime_authoritative = accessxi.missions_menu_runtime_row(context, rows, child, raw, 'current', current_age);
        if (runtime_authoritative) then
            if (runtime_row == nil) then
                return nil, runtime_source;
            end
            row = runtime_row;
            source = runtime_source;
        elseif (context:eq('Rise of the Zilart', true)) then
            row, source = accessxi.missions_menu_zilart_current_row(rows, current_value);
            if (row ~= nil) then
                source = ('%s age=%d'):fmt(source, current_age);
            end
        end
        if (accessxi.missions_menu_empty_row_allowed(context, 'current') and visible_last > 0 and visible_last <= 6) then
            local empty_row, empty_source = accessxi.missions_menu_resource_empty_row('current', child, current_age);
            if (empty_row ~= nil) then
                return empty_row, ('mission-rom-visible-current-row-empty:%s'):fmt(empty_source);
            end
        end
        local nation_row, nation_source = accessxi.missions_menu_nation_current_sentinel_row(context, current_value, current_age);
        if (nation_row ~= nil) then
            return nation_row, nation_source;
        elseif (tostring(nation_source or '') ~= '') then
            return nil, nation_source;
        end
        if (row == nil) then
            row, source = accessxi.missions_menu_zero_progress_current_row(context, rows, current_value);
            if (row ~= nil) then
                source = ('%s age=%d'):fmt(source, current_age);
            end
        end
        if (row == nil) then
            row = accessxi.mission_rom_current_row(rows, current_value);
            if (row ~= nil) then
                source = ('mission-rom-visible-current-row:value=%d age=%d'):fmt(current_value, current_age);
            end
        end
        if (row == nil) then
            if (source == '') then
                source = 'mission-rom-visible-current-row-no-packet';
            end
            return nil, source;
        end
    elseif (ordinal == 0) then
        source = source:gsub('^cop%-rom', 'mission-rom');
        return {
            label = 'Completed',
            status = '',
            status_age = current_age,
            status_source = 'mission-completed-section-row',
            mission_id = 0,
            next_mission_id = 0,
            source = source
        }, source;
    elseif (ordinal ~= nil) then
        if ((not context:eq('Assault', true)) and ordinal > 0) then
            local runtime_authoritative = false;
            row, source, runtime_authoritative = accessxi.missions_menu_runtime_row(context, rows, child, raw, 'completed', current_age);
            if (runtime_authoritative) then
                return row, source;
            end
        end
        if (context:eq('Assault', true) and ordinal > 0) then
            row, source = accessxi.missions_menu_assault_completed_row(rows, selected, ordinal, child);
            if (row == nil and tostring(source or '') ~= '') then
                return nil, source;
            end
        elseif (ordinal > 0) then
            row, source = accessxi.missions_menu_completed_row_from_progress(context, rows, selected, ordinal, current_value, current_age, child);
            if (row ~= nil or tostring(source or '') ~= '') then
                return row, source;
            end
        end
        if (accessxi.missions_menu_empty_row_allowed(context, 'completed') and ordinal == 1 and visible_last > 0 and visible_last <= 4) then
            local empty_row, empty_source = accessxi.missions_menu_resource_empty_row('completed', child, current_age);
            if (empty_row ~= nil) then
                return empty_row, ('mission-rom-visible-completed-row-empty:%s'):fmt(empty_source);
            end
        end
        if (row == nil) then
            local nation_empty_row, nation_empty_source = accessxi.missions_menu_nation_completed_empty_row(context, ordinal, child, current_value, current_age);
            if (nation_empty_row ~= nil) then
                return nation_empty_row, nation_empty_source;
            end
        end
    end

    if (row == nil) then
        return nil, source;
    end

    local mission_id = tonumber(row.mission_id) or 0;
    if (accessxi.missions_menu_empty_row_allowed(context, 'completed') and ordinal == 1 and mission_id == 0 and visible_last > 0 and visible_last <= 4) then
        local empty_row, empty_source = accessxi.missions_menu_resource_empty_row('completed', child, current_age);
        if (empty_row ~= nil) then
            return empty_row, ('mission-rom-visible-completed-row-empty:%s'):fmt(empty_source);
        end
    end
    if (ordinal == 1 and mission_id == 0) then
        local nation_empty_row, nation_empty_source = accessxi.missions_menu_nation_completed_empty_row(context, ordinal, child, current_value, current_age);
        if (nation_empty_row ~= nil) then
            return nation_empty_row, nation_empty_source;
        end
    end

    if (current_value ~= nil and current_value > 0 and mission_id > 0 and mission_id > current_value and tostring(source or ''):find('mission%-native%-runtime%-', 1, false) == nil) then
        return nil, ('mission-rom-gated:value=%d age=%d missionId=%d'):fmt(current_value, current_age, mission_id);
    end

    local status, status_age, status_source = accessxi.mission_rom_status(context, row);
    if (tostring(source or ''):find('mission%-rom%-visible%-current%-boundary', 1, false) ~= nil) then
        status = 'Current';
        status_source = 'mission-current-visible-boundary';
    elseif (tostring(source or ''):find('mission%-rom%-sandoria%-visible%-completed%-row', 1, false) ~= nil) then
        status = 'Completed';
        status_source = 'mission-visible-completed-row';
    elseif (tostring(source or ''):find('mission%-rom%-windurst%-visible%-completed%-row', 1, false) ~= nil) then
        status = 'Completed';
        status_source = 'mission-visible-completed-row';
    end
    row.status = status;
    row.status_age = status_age;
    row.status_source = status_source;

    return row, source;
end

function accessxi.cop_mission_rom_row(selected, raw, page)
    local rows = accessxi.load_cop_mission_rom_rows();
    if (type(rows) ~= 'table') then
        return nil, 'cop-rom-unavailable';
    end

    local packet_cop, packet_age = accessxi.current_cop_mission_value();
    local ordinal, source = accessxi.cop_mission_rom_visible_ordinal(raw, page);
    local row = nil;
    if (ordinal == -1) then
        row = accessxi.cop_mission_rom_current_row(rows, packet_cop);
        if (row ~= nil) then
            source = ('cop-rom-visible-current-row:cop=%d age=%d'):fmt(packet_cop, packet_age);
        else
            return nil, 'cop-rom-visible-current-row-no-packet';
        end
    elseif (ordinal == 0) then
        return nil, source;
    elseif (ordinal ~= nil) then
        row = rows[ordinal];
    end

    if (row == nil) then
        ordinal, source = accessxi.cop_mission_rom_ordinal_for_selected(selected);
        row = rows[ordinal];
    end
    if (row == nil and packet_cop ~= nil and rows.by_mission_id ~= nil) then
        row = accessxi.cop_mission_rom_current_row(rows, packet_cop);
        if (row ~= nil) then
            source = ('cop-rom-current-packet:cop=%d age=%d'):fmt(packet_cop, packet_age);
        end
    end
    if (row == nil) then
        return nil, source;
    end

    local mission_id = tonumber(row.mission_id) or 0;
    if (packet_cop ~= nil and mission_id > 0 and mission_id > packet_cop) then
        return nil, ('cop-rom-gated:cop=%d age=%d missionId=%d'):fmt(packet_cop, packet_age, mission_id);
    end

    local status, status_age, status_source = accessxi.cop_mission_rom_status(row);
    row.status = status;
    row.status_age = status_age;
    row.status_source = status_source;

    return row, source;
end

function accessxi.missions_menu_contextual_row(context, selected, raw, page, child)
    context = tostring(context or '');
    selected = tonumber(selected) or 0;
    if (accessxi.mission_rom_table_for_context(context) ~= nil) then
        return accessxi.mission_rom_row(context, selected, raw, page, child);
    end

    if (context:eq('Chains of Promathia static fallback', true)) then
        return nil, 'cop-static-fallback-disabled';
    end

    return nil, '';
end

function accessxi.missions_menu_native_row_label(child, selected, count)
    local label, mode = accessxi.native_query_label_for_selection(child, selected, count, 'mission-row');
    label = accessxi.plain_native_menu_label(label or '');
    if (label == '') then
        return '', mode;
    end
    if (label:eq('Missions', true) or accessxi.is_missions_menu_category_label(label)) then
        return '', tostring(mode or '') .. ':non-row';
    end
    return label, mode;
end

function accessxi.missions_menu_should_prefer_native_row(context_row, native_label)
    native_label = tostring(native_label or ''):trim();
    if (native_label == '') then
        return false;
    end

    local lower = native_label:lower();
    if (lower:find('no ', 1, true) ~= nil and lower:find('mission', 1, true) ~= nil) then
        return true;
    end
    if (context_row == nil) then
        return false;
    end
    if (tostring(context_row.status_source or '') == 'mission-completed-section-row') then
        return true;
    end

    return false;
end

function accessxi.missions_menu_native_row(context, native_label, native_mode, raw)
    native_label = tostring(native_label or ''):trim();
    local raw_lo = bit.band(tonumber(raw) or 0, 0xFFFF);
    local lower = native_label:lower();
    local status = '';
    local status_source = 'mission-native-visible-row';
    if (raw_lo == 1 and lower:find('no ', 1, true) == nil) then
        status = 'Current';
        status_source = 'mission-native-visible-current-row';
    elseif (lower:find('completed', 1, true) ~= nil and lower:find('no ', 1, true) == nil) then
        status_source = 'mission-native-visible-completed-row';
    end

    return {
        label = native_label,
        status = status,
        status_age = -1,
        status_source = status_source,
        mission_id = 0,
        next_mission_id = 0,
        source = ('mission-native-visible-row:%s'):fmt(tostring(native_mode or ''))
    };
end

function accessxi.missions_menu_detail_section_active(desc_id, context_row, entry)
    desc_id = tonumber(desc_id) or 0;
    if (type(context_row) ~= 'table') then
        return false;
    end
    if (tostring(context_row.orders or '') == '') then
        return false;
    end
    if (desc_id == 0x5A) then
        return true;
    end

    entry = tonumber(entry) or 0;
    if (not accessxi.is_probe_pointer(entry)) then
        return false;
    end

    local detail_flags = read_u32(entry + 0x48) or 0;
    local detail_panel = bit.band(detail_flags, 0x00010000) == 0;
    if (not detail_panel) then
        return false;
    end
    if (desc_id == 0x73 or desc_id == 0x8C or desc_id == 0xA5 or desc_id == 0xBE) then
        return true;
    end
    return false;
end

function accessxi.missions_menu_detail_speech(title, context, row)
    if (type(row) ~= 'table') then
        return nil;
    end

    local label = tostring(row.label or '');
    local heading = tostring(row.orders_heading or 'Mission Orders');
    local orders = tostring(row.orders or '');
    if (label == '' or orders == '') then
        return nil;
    end

    heading = heading:gsub(':%s*$', '');
    local parts = T{};
    parts:append(tostring(title or 'Missions'));
    parts:append(label);
    if (heading ~= '') then
        parts:append(heading);
    end
    parts:append(orders);
    return accessxi.sentence_fragment(parts:concat('. '));
end

function accessxi.mission_detail_summary_lines(row)
    if (type(row) ~= 'table' or type(row.orders_lines) ~= 'table') then
        return nil, 'missing-mission-order-lines';
    end

    local label = tostring(row.label or ''):trim();
    if (label == '') then
        return nil, 'missing-mission-label';
    end

    local lines = T{};
    lines:append(label);
    local heading = tostring(row.orders_heading or ''):gsub(':%s*$', ''):trim();
    if (heading ~= '') then
        lines:append(heading);
    end
    for _, value in ipairs(row.orders_lines) do
        local text = tostring(value or ''):trim();
        if (text ~= '') then
            lines:append(text);
        end
    end
    if (#lines <= 1) then
        return nil, 'empty-mission-order-lines';
    end
    return lines, 'mission-rom-order-lines';
end

function accessxi.mission_detail_summary_surface_key(menu_name, context, row, obj)
    if (type(row) ~= 'table') then
        return '';
    end
    obj = tonumber(obj) or 0;
    if (not accessxi.is_probe_pointer(obj)) then
        return '';
    end
    local label = tostring(row.label or ''):trim();
    if (label == '') then
        return '';
    end
    return ('mission-summary:%s:0x%08X:%s:%d:%d:%s'):fmt(
        tostring(menu_name or ''),
        obj,
        tostring(context or ''),
        tonumber(row.mission_id) or 0,
        tonumber(row.rom_ordinal) or 0,
        label);
end

function accessxi.reset_mission_detail_summary_surface()
    if (type(accessxi.detail_summary_navigation) == 'table'
        and type(accessxi.detail_summary_navigation.reset) == 'function') then
        accessxi.detail_summary_navigation.reset(accessxi.mission_detail_summary_state);
    end
    accessxi.last_missions_menu_detail_summary_surface_key = '';
    accessxi.last_missions_menu_detail_row = nil;
    accessxi.last_missions_menu_detail_summary_tick = 0;
    accessxi.last_missions_menu_detail_summary_obj = 0;
    accessxi.last_missions_menu_detail_summary_context = '';
end

function accessxi.begin_mission_detail_summary_surface(menu_name, context, row, obj, desc_id)
    if (type(accessxi.detail_summary_navigation) ~= 'table'
        or type(accessxi.detail_summary_navigation.begin_surface) ~= 'function') then
        return '';
    end
    obj = tonumber(obj) or get_current_menu_object_ptr();
    local position = tonumber(read_current_native_menu_index(0x4C)) or 0;
    local surface_key = accessxi.mission_detail_summary_surface_key(menu_name, context, row, obj);
    if (surface_key == '' or position <= 0) then
        return '';
    end

    if (surface_key ~= tostring(accessxi.last_missions_menu_detail_summary_surface_key or '')) then
        accessxi.detail_summary_navigation.begin_surface(
            accessxi.mission_detail_summary_state, surface_key, position);
    end
    accessxi.last_missions_menu_detail_summary_surface_key = surface_key;
    accessxi.last_missions_menu_detail_row = row;
    accessxi.last_missions_menu_detail_summary_tick = tick();
    accessxi.last_missions_menu_detail_summary_obj = obj;
    accessxi.last_missions_menu_detail_summary_context = tostring(context or '');
    accessxi.last_missions_menu_detail_summary_desc_id = tonumber(desc_id) or 0;
    return surface_key;
end

function accessxi.missions_menu_detail_hold_ms(text)
    local len = #accessxi.speech_output_text(text or '');
    local ms = len * 55;
    if (ms < 3000) then
        ms = 3000;
    elseif (ms > 12000) then
        ms = 12000;
    end
    return ms;
end

