function accessxi.missions_menu_category_from_surface_text(text)
    text = tostring(text or '');
    if (text == '') then
        return '';
    end

    local lower = text:lower();
    for _, row in ipairs(accessxi.missions_menu_category_surface_aliases) do
        local label = tostring(row.label or '');
        if (accessxi.mission_rom_table_for_context(label) ~= nil) then
            for _, alias in ipairs(row.aliases or T{}) do
                alias = tostring(alias or '');
                if (alias ~= '' and lower:find(alias:lower(), 1, true) ~= nil) then
                    return label;
                end
            end
        end
    end

    return '';
end

function accessxi.missions_menu_category_surface_context(child, raw)
    local raw_lo = bit.band(tonumber(raw) or 0, 0xFFFF);
    if (raw_lo ~= 1) then
        return '', 0, '';
    end

    child = tonumber(child) or 0;
    if (not accessxi.is_probe_pointer(child)) then
        return '', 0, '';
    end

    local surface = read_u32(child + 0x20) or 0;
    if (not accessxi.is_probe_pointer(surface)) then
        return '', surface, '';
    end

    accessxi.missions_menu_surface_context_cache = accessxi.missions_menu_surface_context_cache or {};
    local cache = accessxi.missions_menu_surface_context_cache;
    local cached = cache[surface];
    if (cached ~= nil) then
        return tostring(cached.label or ''), surface, tostring(cached.text or '');
    end

    local parts = T{};
    local function append_probe_text(ptr, length)
        ptr = tonumber(ptr) or 0;
        if (not accessxi.is_probe_pointer(ptr)) then
            return;
        end
        parts:append(accessxi.probe_runs_to_text(accessxi.collect_probe_ascii_runs(ptr, length, 2, 24)));
        parts:append(accessxi.probe_runs_to_text(accessxi.collect_probe_utf16_runs(ptr, length, 2, 16)));
        parts:append(accessxi.probe_runs_to_text(accessxi.collect_probe_ffxi_utf16_runs(ptr, length, 2, 16)));
    end

    append_probe_text(surface, 0x240);
    if (accessxi.is_probe_pointer(surface - 0x80)) then
        append_probe_text(surface - 0x80, 0x300);
    end

    local text = parts:concat(' | ');
    local label = accessxi.missions_menu_category_from_surface_text(text);
    local cache_count = (tonumber(accessxi.missions_menu_surface_context_cache_count) or 0) + 1;
    if (cache_count > 96) then
        cache = {};
        accessxi.missions_menu_surface_context_cache = cache;
        cache_count = 1;
    end
    cache[surface] = { label = label, text = text };
    accessxi.missions_menu_surface_context_cache_count = cache_count;
    return label, surface, text;
end

function accessxi.missions_menu_context_from_runtime(fallback, category, raw_category, surface_category, pointer_category, signature_category, header_category, index_category)
    fallback = tostring(fallback or '');
    category = tostring(category or '');
    raw_category = tostring(raw_category or '');
    surface_category = tostring(surface_category or '');
    pointer_category = tostring(pointer_category or '');
    signature_category = tostring(signature_category or '');
    header_category = tostring(header_category or '');
    index_category = tostring(index_category or '');

    if (index_category ~= '' and accessxi.mission_rom_table_for_context(index_category) ~= nil) then
        return index_category, 'mission-category-native-index';
    end

    if (raw_category ~= '' and accessxi.mission_rom_table_for_context(raw_category) ~= nil) then
        return raw_category, 'mission-category-raw';
    end

    if (category ~= '' and accessxi.mission_rom_table_for_context(category) ~= nil) then
        return category, 'mission-category';
    end

    if (pointer_category ~= '' and accessxi.mission_rom_table_for_context(pointer_category) ~= nil) then
        return pointer_category, 'mission-category-native-pointer';
    end

    if (fallback ~= '' and accessxi.mission_rom_table_for_context(fallback) ~= nil) then
        return fallback, 'parent-context';
    end

    if (accessxi.missions_menu_category_probe_enabled == true and surface_category ~= '' and accessxi.mission_rom_table_for_context(surface_category) ~= nil) then
        return surface_category, 'mission-category-surface-probe';
    end

    return fallback, 'parent-context';
end

function accessxi.log_missions_menu_category_signal(menu_name, title, selected, count, raw, entry, context, context_source, fallback_context, category_ptr, category, raw_category, surface_category, surface_ptr, desc_id, desc_rec)
    menu_name = tostring(menu_name or '');
    if (not menu_name:eq('menu    miss00', true)) then
        return;
    end

    context = tostring(context or '');
    if (context == '' and tostring(category or '') == '' and tostring(raw_category or '') == '') then
        return;
    end

    selected = tonumber(selected) or 0;
    count = tonumber(count) or 0;
    raw = tonumber(raw) or 0;
    entry = tonumber(entry) or 0;
    category_ptr = tonumber(category_ptr) or 0;
    surface_ptr = tonumber(surface_ptr) or 0;
    desc_id = tonumber(desc_id) or 0;
    desc_rec = tonumber(desc_rec) or 0;

    local key = ('%s:%d:%d:0x%08X:0x%08X:%s:%s:%s:%s:0x%08X:0x%08X'):fmt(
        menu_name,
        selected,
        count,
        raw,
        entry,
        tostring(context or ''),
        tostring(category or ''),
        tostring(raw_category or ''),
        tostring(surface_category or ''),
        surface_ptr,
        desc_id);
    if (key == tostring(accessxi.last_missions_menu_category_signal_key or '')) then
        return;
    end
    accessxi.last_missions_menu_category_signal_key = key;

    log_state(('state missions category-signal menu="%s" title="%s" select=%d count=%d raw=0x%08X rawLo=%d entry=0x%08X context="%s" contextSource="%s" fallbackContext="%s" categoryPtr=0x%08X category="%s" categoryRaw="%s" surface=0x%08X surfaceCategory="%s" descId=0x%08X entry040="%s" recDwords="%s"'):fmt(
        menu_name,
        accessxi.escape_probe_log_text(tostring(title or '')),
        selected,
        count,
        raw,
        bit.band(raw, 0xFFFF),
        entry,
        accessxi.escape_probe_log_text(context),
        accessxi.escape_probe_log_text(tostring(context_source or '')),
        accessxi.escape_probe_log_text(tostring(fallback_context or '')),
        category_ptr,
        accessxi.escape_probe_log_text(tostring(category or '')),
        accessxi.escape_probe_log_text(tostring(raw_category or '')),
        surface_ptr,
        accessxi.escape_probe_log_text(tostring(surface_category or '')),
        desc_id,
        accessxi.escape_probe_log_text(accessxi.format_probe_dwords(entry, 0x40, 8)),
        accessxi.escape_probe_log_text(accessxi.format_probe_dwords(desc_rec, 0x00, 12))));
end

function accessxi.log_missions_menu_category_surface(menu_name, title, selected, count, raw, child, entry, surface_category)
    menu_name = tostring(menu_name or '');
    if (not menu_name:eq('menu    miss00', true)) then
