        accessxi.escape_probe_log_text(accessxi.status_menu_probe_inline_strings(surface)),
        accessxi.escape_probe_log_text(accessxi.status_menu_probe_runs(surface, 0x100)),
        accessxi.escape_probe_log_text(accessxi.status_menu_probe_pointer_fields(surface))));
end

function accessxi.missions_menu_native_ank_shape_summary(shape)
    shape = tonumber(shape) or 0;
    if (not accessxi.is_probe_pointer(shape)) then
        return '', '', '', '', '';
    end

    local strings = accessxi.status_menu_probe_inline_strings(shape);
    local runs = accessxi.status_menu_probe_runs(shape, 0x100);
    local bytes = accessxi.format_probe_bytes(shape, 0x00, 0x50);
    local ptrs = T{};
    local seen = {};
    for _, off in ipairs(T{ 0x04, 0x08, 0x0C, 0x10, 0x14, 0x18, 0x1C, 0x20, 0x24, 0x28, 0x2C, 0x30, 0x34, 0x38, 0x3C, 0x40, 0x48, 0x50, 0x58, 0x60, 0x68, 0x70, 0x78, 0x80 }) do
        local ptr = read_u32(shape + off) or 0;
        if (accessxi.is_probe_pointer(ptr) and seen[ptr] ~= true) then
            seen[ptr] = true;
            ptrs:append(('+%02X=0x%08X d="%s" text="%s" runs="%s"'):fmt(
                off,
                ptr,
                accessxi.format_probe_dwords(ptr, 0x00, 6),
                accessxi.escape_probe_log_text(accessxi.status_menu_probe_inline_strings(ptr)),
                accessxi.escape_probe_log_text(accessxi.status_menu_probe_runs(ptr, 0x80))));
            if (ptrs:len() >= 6) then
                break;
            end
        end
    end

    return accessxi.format_probe_dwords(shape, 0x00, 12),
        strings,
        runs,
        bytes,
        ptrs:concat(' | ');
end

function accessxi.log_missions_menu_native_ank_shape_signal(menu_name, title, selected, count, page, raw, child, entry, ank_num, target)
    menu_name = tostring(menu_name or '');
    if (not menu_name:eq('menu    miss00', true)) then
        return 0;
    end

    target = target or AshitaCore:GetMemoryManager():GetTarget();
    ank_num = tonumber(ank_num) or -1;
    if (target == nil or ank_num < 0 or ank_num > 16) then
        return 0;
    end

    local shape = tonumber(safe_call(function () return target:GetWindowAnkShape(ank_num); end, 0)) or 0;
    if (shape == 0) then
        return 0;
    end

    local dwords, strings, runs, bytes, ptrs = accessxi.missions_menu_native_ank_shape_summary(shape);
    local key = ('%s:%d:%d:%d:0x%08X:0x%08X:0x%08X:%d:0x%08X:%s:%s:%s'):fmt(
        menu_name,
        tonumber(selected) or 0,
        tonumber(count) or 0,
        tonumber(page) or 0,
        tonumber(raw) or 0,
        tonumber(child) or 0,
        tonumber(entry) or 0,
        ank_num,
        shape,
        dwords,
        tostring(strings or ''),
        tostring(runs or ''));
    if (key == tostring(accessxi.last_missions_menu_native_ank_shape_key or '')) then
        return shape;
    end
    accessxi.last_missions_menu_native_ank_shape_key = key;

    log_state(('state missions native-ank-shape menu="%s" title="%s" select=%d count=%d page=%d raw=0x%08X rawLo=%d child=0x%08X entry=0x%08X ank=%d shape=0x%08X dwords="%s" strings="%s" runs="%s" ptrs="%s" bytes="%s"'):fmt(
        menu_name,
        accessxi.escape_probe_log_text(tostring(title or '')),
        tonumber(selected) or 0,
        tonumber(count) or 0,
        tonumber(page) or 0,
        tonumber(raw) or 0,
        bit.band(tonumber(raw) or 0, 0xFFFF),
        tonumber(child) or 0,
        tonumber(entry) or 0,
        ank_num,
        shape,
        accessxi.escape_probe_log_text(dwords),
        accessxi.escape_probe_log_text(strings),
        accessxi.escape_probe_log_text(runs),
        accessxi.escape_probe_log_text_wide(ptrs),
        accessxi.escape_probe_log_text_wide(bytes)));
    return shape;
end

function accessxi.is_missions_menu_category_label(label)
    label = tostring(label or '');
    if (label == '' or accessxi.mission_rom_table_for_context(label) == nil) then
        return false;
    end

    for _, known in ipairs(accessxi.missions_menu_category_labels or T{}) do
        if (label:eq(tostring(known or ''), true)) then
            return true;
        end
    end

    return false;
end

function accessxi.note_missions_menu_category_label_pointer(label, ptr, source)
    label = tostring(label or '');
    ptr = tonumber(ptr) or 0;
    if (not accessxi.is_missions_menu_category_label(label) or not accessxi.is_probe_pointer(ptr)) then
        return false;
    end

    local actual = accessxi.plain_native_menu_label(read_probe_string(ptr, 180));
    if (actual ~= '' and not actual:eq(label, true)) then
        return false;
    end

    if (accessxi.missions_menu_category_label_pointers == nil) then
        accessxi.missions_menu_category_label_pointers = T{};
    end
    if (accessxi.missions_menu_category_pointer_labels == nil) then
        accessxi.missions_menu_category_pointer_labels = T{};
    end

    local was_new = accessxi.missions_menu_category_pointer_labels[ptr] == nil;
    accessxi.missions_menu_category_label_pointers[label] = ptr;
    accessxi.missions_menu_category_pointer_labels[ptr] = label;
    if (was_new) then
        accessxi.last_missions_menu_category_pointer_count = (tonumber(accessxi.last_missions_menu_category_pointer_count) or 0) + 1;
    end

    local key = ('%s:0x%08X:%s'):fmt(label, ptr, tostring(source or ''));
    if (key ~= tostring(accessxi.last_missions_menu_category_pointer_note_key or '')) then
        accessxi.last_missions_menu_category_pointer_note_key = key;
        log_state(('state missions category-pointer-cache label="%s" ptr=0x%08X source="%s"'):fmt(
            accessxi.escape_probe_log_text(label),
            ptr,
            accessxi.escape_probe_log_text(tostring(source or ''))));
    end
    return true;
end

function accessxi.scan_near_missions_menu_category_label_pointer(seed_ptr)
    seed_ptr = tonumber(seed_ptr) or 0;
    if (not accessxi.is_probe_pointer(seed_ptr)) then
        return;
    end

    local bucket = seed_ptr - (seed_ptr % 0x1000);
    local start_addr = bucket - 0x2000;
    if (start_addr < 0) then
        start_addr = 0;
    end
    start_addr = start_addr - (start_addr % 4);
    local end_addr = bucket + 0x4000;
    local region_key = ('0x%08X-0x%08X'):fmt(start_addr, end_addr);
    if (accessxi.missions_menu_category_near_scan_regions == nil) then
        accessxi.missions_menu_category_near_scan_regions = T{};
    end
    if (accessxi.missions_menu_category_near_scan_regions[region_key] == true) then
        return;
    end
    accessxi.missions_menu_category_near_scan_regions[region_key] = true;

    local hits = T{};
    for addr = start_addr, end_addr, 4 do
        local label = accessxi.plain_native_menu_label(read_probe_string(addr, 180));
        if (accessxi.is_missions_menu_category_label(label)) then
            if (accessxi.note_missions_menu_category_label_pointer(label, addr, 'near-native-label-scan')) then
                hits:append(('%s=0x%08X'):fmt(label, addr));
            end
        end
    end

    if (#hits > 0) then
        log_state(('state missions category-pointer-near-scan seed=0x%08X region="%s" hits="%s"'):fmt(
            seed_ptr,
            accessxi.escape_probe_log_text(region_key),
            accessxi.escape_probe_log_text(hits:concat(' | '))));
    end
end

function accessxi.missions_menu_cached_category_for_pointer(ptr)
    ptr = tonumber(ptr) or 0;
    if (not accessxi.is_probe_pointer(ptr)) then
        return '';
    end

    local cached = accessxi.missions_menu_category_pointer_labels ~= nil and tostring(accessxi.missions_menu_category_pointer_labels[ptr] or '') or '';
    if (cached ~= '' and accessxi.is_missions_menu_category_label(cached)) then
        return cached;
    end

    local label = accessxi.plain_native_menu_label(read_probe_string(ptr, 180));
    if (accessxi.is_missions_menu_category_label(label)) then
        accessxi.note_missions_menu_category_label_pointer(label, ptr, 'direct-native-label-pointer');
        return label;
    end

    return '';
end

function accessxi.scan_missions_menu_category_pointer_nested_record(base, prefix, max_bytes, hits, seen, seen_records)
    base = tonumber(base) or 0;
    max_bytes = tonumber(max_bytes) or 0;
    if (not accessxi.is_probe_pointer(base) or max_bytes <= 0) then
        return;
    end

    if (seen_records[base] == true) then
        return;
    end
    seen_records[base] = true;

    for offset = 0, max_bytes, 4 do
        local ptr = read_u32(base + offset) or 0;
        local label = accessxi.missions_menu_cached_category_for_pointer(ptr);
        if (label ~= '') then
            local key = ('%s:0x%08X'):fmt(label, ptr);
            if (seen[key] ~= true) then
                seen[key] = true;
                hits:append(('%s+%03X=%s@0x%08X'):fmt(prefix, offset, label, ptr));
            end
        end
    end
end

function accessxi.scan_missions_menu_category_pointer_block(base, prefix, max_bytes, hits, seen, seen_records, nested_bytes)
    base = tonumber(base) or 0;
    max_bytes = tonumber(max_bytes) or 0;
    if (not accessxi.is_probe_pointer(base) or max_bytes <= 0) then
        return;
    end
    nested_bytes = tonumber(nested_bytes) or 0;

    for offset = 0, max_bytes, 4 do
        local ptr = read_u32(base + offset) or 0;
        local label = accessxi.missions_menu_cached_category_for_pointer(ptr);
        if (label ~= '') then
            local key = ('%s:0x%08X'):fmt(label, ptr);
            if (seen[key] ~= true) then
                seen[key] = true;
                hits:append(('%s+%03X=%s@0x%08X'):fmt(prefix, offset, label, ptr));
            end
        elseif (nested_bytes > 0 and accessxi.is_probe_pointer(ptr)) then
            accessxi.scan_missions_menu_category_pointer_nested_record(ptr, ('%s+%03X*'):fmt(prefix, offset), nested_bytes, hits, seen, seen_records);
        end
    end
end

function accessxi.missions_menu_category_pointer_context(menu_name, title, obj, selected, count, page, raw, child, entry)
    menu_name = tostring(menu_name or '');
    if (not menu_name:eq('menu    miss00', true)) then
        return '', 0, '';
    end

    obj = tonumber(obj) or 0;
    child = tonumber(child) or 0;
    entry = tonumber(entry) or 0;

    local target = AshitaCore:GetMemoryManager():GetTarget();
    local ank_num = target ~= nil and (tonumber(safe_call(function () return target:GetWindowAnkNum(); end, -1)) or -1) or -1;
    local ank_shape = 0;
    if (target ~= nil and ank_num >= 0 and ank_num <= 16) then
        ank_shape = tonumber(safe_call(function () return target:GetWindowAnkShape(ank_num); end, 0)) or 0;
    end
    local surface = accessxi.is_probe_pointer(child) and (read_u32(child + 0x20) or 0) or 0;
    local desc04 = accessxi.is_probe_pointer(entry) and (read_u32(entry + 0x04) or 0) or 0;
    local desc0c = accessxi.is_probe_pointer(entry) and (read_u32(entry + 0x0C) or 0) or 0;

    local hits = T{};
    local seen = T{};
    local seen_records = T{};
    accessxi.scan_missions_menu_category_pointer_block(obj, 'obj', 0x140, hits, seen, seen_records, 0x80);
    accessxi.scan_missions_menu_category_pointer_block(child, 'child', 0x100, hits, seen, seen_records, 0x80);
    accessxi.scan_missions_menu_category_pointer_block(entry, 'entry', 0x120, hits, seen, seen_records, 0x80);
    accessxi.scan_missions_menu_category_pointer_block(surface, 'surface', 0x100, hits, seen, seen_records, 0x80);
    accessxi.scan_missions_menu_category_pointer_block(ank_shape, 'ankShape', 0x100, hits, seen, seen_records, 0x80);
    accessxi.scan_missions_menu_category_pointer_block(desc04, 'desc04', 0x80, hits, seen, seen_records, 0x40);
    accessxi.scan_missions_menu_category_pointer_block(desc0c, 'desc0C', 0x80, hits, seen, seen_records, 0x40);
    if (target ~= nil) then
        for i = 0, 16 do
            local shape = tonumber(safe_call(function () return target:GetWindowAnkShape(i); end, 0)) or 0;
            if (shape ~= 0) then
                accessxi.scan_missions_menu_category_pointer_block(shape, ('shape%d'):fmt(i), 0x100, hits, seen, seen_records, 0x60);
            end
        end
    end

    if (#hits <= 0) then
        return '', 0, '';
    end

    local first = tostring(hits[1] or '');
    local label, ptr = first:match('=(.-)@0x([0-9A-Fa-f]+)$');
    label = tostring(label or '');
    ptr = tonumber(ptr or '0', 16) or 0;
    local source = 'mission-category-native-pointer:' .. first;
    local key = ('%s:%d:%d:%d:0x%08X:0x%08X:0x%08X:%d:0x%08X:%s'):fmt(
        menu_name,
        tonumber(selected) or 0,
        tonumber(count) or 0,
        tonumber(page) or 0,
        tonumber(raw) or 0,
        obj,
        entry,
        ank_num,
        ank_shape,
        hits:concat('|'));
    if (key ~= tostring(accessxi.last_missions_menu_category_pointer_context_key or '')) then
        accessxi.last_missions_menu_category_pointer_context_key = key;
        log_state(('state missions category-pointer-context menu="%s" title="%s" select=%d count=%d page=%d raw=0x%08X obj=0x%08X child=0x%08X entry=0x%08X surface=0x%08X ank=%d ankShape=0x%08X label="%s" ptr=0x%08X hits="%s"'):fmt(
            menu_name,
            accessxi.escape_probe_log_text(tostring(title or '')),
            tonumber(selected) or 0,
            tonumber(count) or 0,
            tonumber(page) or 0,
            tonumber(raw) or 0,
            obj,
            child,
            entry,
            surface,
            ank_num,
            ank_shape,
            accessxi.escape_probe_log_text(label),
            ptr,
            accessxi.escape_probe_log_text(hits:concat(' | '))));
    end

    if (accessxi.is_missions_menu_category_label(label)) then
        return label, ptr, source;
    end
    return '', 0, '';
end

function accessxi.missions_menu_native_signature(obj)
    obj = tonumber(obj) or 0;
    if (not accessxi.is_probe_pointer(obj)) then
        return '';
    end

    local ptr14 = read_u32(obj + 0x14) or 0;
    local ptr18 = read_u32(obj + 0x18) or 0;
    if (not accessxi.is_probe_pointer(ptr14) or not accessxi.is_probe_pointer(ptr18)) then
        return '';
    end

    return ('obj14=0x%08X,obj18=0x%08X'):fmt(ptr14, ptr18);
end

function accessxi.note_missions_menu_native_signature(signature, label, source)
    signature = tostring(signature or '');
    label = tostring(label or '');
    if (signature == '' or not accessxi.is_missions_menu_category_label(label)) then
        return false;
    end

    if (accessxi.missions_menu_native_signature_labels == nil) then
        accessxi.missions_menu_native_signature_labels = T{};
    end

    local previous = tostring(accessxi.missions_menu_native_signature_labels[signature] or '');
    accessxi.missions_menu_native_signature_labels[signature] = label;

    local key = ('%s:%s:%s'):fmt(signature, label, tostring(source or ''));
    if (key ~= tostring(accessxi.last_missions_menu_native_signature_note_key or '')) then
        accessxi.last_missions_menu_native_signature_note_key = key;
        log_state(('state missions native-signature-cache label="%s" signature="%s" previous="%s" source="%s"'):fmt(
            accessxi.escape_probe_log_text(label),
            accessxi.escape_probe_log_text(signature),
            accessxi.escape_probe_log_text(previous),
            accessxi.escape_probe_log_text(tostring(source or ''))));
    end
    return true;
end

function accessxi.missions_menu_native_signature_context(menu_name, title, obj, selected, count, page, raw)
    menu_name = tostring(menu_name or '');
    if (not menu_name:eq('menu    miss00', true)) then
        return '', '', '';
    end

    local signature = accessxi.missions_menu_native_signature(obj);
    if (signature == '') then
        return '', '', '';
    end

    local label = accessxi.missions_menu_native_signature_labels ~= nil and tostring(accessxi.missions_menu_native_signature_labels[signature] or '') or '';
    if (not accessxi.is_missions_menu_category_label(label)) then
        return '', signature, '';
    end

    local source = 'mission-category-native-signature:' .. signature;
    local key = ('%s:%d:%d:%d:0x%08X:%s:%s'):fmt(
        menu_name,
        tonumber(selected) or 0,
        tonumber(count) or 0,
        tonumber(page) or 0,
        tonumber(raw) or 0,
        signature,
        label);
    if (key ~= tostring(accessxi.last_missions_menu_native_signature_context_key or '')) then
        accessxi.last_missions_menu_native_signature_context_key = key;
        log_state(('state missions native-signature-context menu="%s" title="%s" select=%d count=%d page=%d raw=0x%08X label="%s" signature="%s"'):fmt(
            menu_name,
            accessxi.escape_probe_log_text(tostring(title or '')),
            tonumber(selected) or 0,
            tonumber(count) or 0,
            tonumber(page) or 0,
            tonumber(raw) or 0,
            accessxi.escape_probe_log_text(label),
            accessxi.escape_probe_log_text(signature)));
    end

    return label, signature, source;
end

function accessxi.missions_menu_category_text_at_pointer(ptr)
    ptr = tonumber(ptr) or 0;
    if (not accessxi.is_probe_pointer(ptr)) then
        return '', '';
    end

    local direct = accessxi.plain_native_menu_label(read_probe_string(ptr, 180));
    if (accessxi.is_missions_menu_category_label(direct)) then
        return direct, direct;
    end

    local text = ('%s | %s'):fmt(
        accessxi.status_menu_probe_inline_strings(ptr),
        accessxi.status_menu_probe_runs(ptr, 0x160));
    local label = accessxi.missions_menu_category_from_surface_text(text);
    return label, text;
end

function accessxi.missions_menu_compact_pointer_samples(candidates)
    local parts = T{};
    local seen = {};
    for _, candidate in ipairs(candidates or T{}) do
        local ptr = tonumber(candidate.ptr) or 0;
        if (accessxi.is_probe_pointer(ptr) and seen[ptr] ~= true) then
            seen[ptr] = true;
            local inline = accessxi.status_menu_probe_inline_strings(ptr);
            local runs = accessxi.status_menu_probe_runs(ptr, 0x120);
            local text = tostring(inline or '');
            if (text == '') then
                text = tostring(runs or '');
            elseif (runs ~= '') then
                text = text .. ' ' .. runs;
            end
            if (text ~= '') then
                parts:append(('%s=0x%08X{%s}'):fmt(
                    tostring(candidate.source or ''),
                    ptr,
                    accessxi.escape_probe_log_text_wide(text)));
                if (parts:len() >= 8) then
                    break;
                end
            end
        end
    end
    return parts:concat(' | ');
end

function accessxi.append_missions_menu_header_candidate(candidates, seen, source, ptr)
    ptr = tonumber(ptr) or 0;
    if (not accessxi.is_probe_pointer(ptr) or seen[ptr] == true) then
        return;
    end
    seen[ptr] = true;
    candidates:append({ source = tostring(source or ''), ptr = ptr });
end

function accessxi.missions_menu_header_category_context(menu_name, title, obj, selected, count, page, raw, child, entry, native_signature)
    menu_name = tostring(menu_name or '');
    if (not menu_name:eq('menu    miss00', true)) then
        return '', '';
    end

    obj = tonumber(obj) or 0;
    child = tonumber(child) or 0;
    entry = tonumber(entry) or 0;
    local target = AshitaCore:GetMemoryManager():GetTarget();
    local ank_num = target ~= nil and (tonumber(safe_call(function () return target:GetWindowAnkNum(); end, -1)) or -1) or -1;
    local ank_shape = 0;
    if (target ~= nil and ank_num >= 0 and ank_num <= 16) then
        ank_shape = tonumber(safe_call(function () return target:GetWindowAnkShape(ank_num); end, 0)) or 0;
    end

    local surface = accessxi.is_probe_pointer(child) and (read_u32(child + 0x20) or 0) or 0;
    local candidates = T{};
    local seen = T{};
    accessxi.append_missions_menu_header_candidate(candidates, seen, 'obj', obj);
    accessxi.append_missions_menu_header_candidate(candidates, seen, 'child', child);
    accessxi.append_missions_menu_header_candidate(candidates, seen, 'entry', entry);
    accessxi.append_missions_menu_header_candidate(candidates, seen, 'surface', surface);
    accessxi.append_missions_menu_header_candidate(candidates, seen, 'ankShape', ank_shape);

    local owners = T{
        { name = 'obj', ptr = obj },
        { name = 'child', ptr = child },
        { name = 'entry', ptr = entry },
        { name = 'surface', ptr = surface },
        { name = 'ankShape', ptr = ank_shape },
    };
    for _, owner in ipairs(owners) do
        local owner_ptr = tonumber(owner.ptr) or 0;
        if (accessxi.is_probe_pointer(owner_ptr)) then
            for _, off in ipairs(T{ 0x04, 0x08, 0x0C, 0x10, 0x14, 0x18, 0x1C, 0x20, 0x24, 0x28, 0x2C, 0x30, 0x34, 0x38, 0x3C, 0x40, 0x44, 0x48, 0x4C, 0x50, 0x54, 0x58, 0x5C, 0x60, 0x64, 0x68, 0x6C, 0x70, 0x74, 0x78, 0x7C, 0x80, 0x84, 0x88, 0x8C, 0x90 }) do
                accessxi.append_missions_menu_header_candidate(candidates, seen, ('%s+%02X'):fmt(owner.name, off), read_u32(owner_ptr + off) or 0);
            end
        end
    end

    if (target ~= nil) then
        for i = 0, 5 do
            local shape = tonumber(safe_call(function () return target:GetWindowAnkShape(i); end, 0)) or 0;
            accessxi.append_missions_menu_header_candidate(candidates, seen, ('shape%d'):fmt(i), shape);
        end
    end

    local hits = T{};
    local first_label = '';
    local first_source = '';
    for _, candidate in ipairs(candidates) do
        local label, text = accessxi.missions_menu_category_text_at_pointer(candidate.ptr);
        if (accessxi.is_missions_menu_category_label(label)) then
            local hit = ('%s=0x%08X:%s'):fmt(candidate.source, candidate.ptr, label);
            hits:append(hit);
            if (first_label == '') then
                first_label = label;
                first_source = 'mission-category-native-header:' .. hit;
            end
        elseif (#hits < 4 and tostring(text or '') ~= '') then
            local text_label = accessxi.missions_menu_category_from_surface_text(text);
            if (accessxi.is_missions_menu_category_label(text_label)) then
                local hit = ('%s=0x%08X:%s'):fmt(candidate.source, candidate.ptr, text_label);
                hits:append(hit);
                if (first_label == '') then
                    first_label = text_label;
                    first_source = 'mission-category-native-header:' .. hit;
                end
            end
        end
        if (#hits >= 8) then
            break;
        end
    end

    local snapshot_key = ('%s:%d:%d:%d:0x%08X:0x%08X:0x%08X:0x%08X:0x%08X:%s:%s'):fmt(
        menu_name,
        tonumber(selected) or 0,
        tonumber(count) or 0,
        tonumber(page) or 0,
        tonumber(raw) or 0,
        obj,
        child,
        entry,
        surface,
        tostring(native_signature or ''),
        hits:concat('|'));
    if (snapshot_key ~= tostring(accessxi.last_missions_menu_header_snapshot_key or '')) then
        accessxi.last_missions_menu_header_snapshot_key = snapshot_key;
        local samples = first_label == '' and accessxi.missions_menu_compact_pointer_samples(candidates) or '';
        log_state(('state missions category-header-snapshot menu="%s" title="%s" select=%d count=%d page=%d raw=0x%08X rawLo=%d label="%s" source="%s" obj=0x%08X child=0x%08X entry=0x%08X surface=0x%08X ank=%d ankShape=0x%08X signature="%s" hits="%s" obj040="%s" obj080="%s" child000="%s" child040="%s" entry040="%s" samples="%s" surfacePtrs="%s"'):fmt(
            menu_name,
            accessxi.escape_probe_log_text(tostring(title or '')),
            tonumber(selected) or 0,
            tonumber(count) or 0,
            tonumber(page) or 0,
            tonumber(raw) or 0,
            bit.band(tonumber(raw) or 0, 0xFFFF),
            accessxi.escape_probe_log_text(first_label),
            accessxi.escape_probe_log_text(first_source),
            obj,
            child,
            entry,
            surface,
            ank_num,
            ank_shape,
            accessxi.escape_probe_log_text(tostring(native_signature or '')),
            accessxi.escape_probe_log_text_wide(hits:concat(' | ')),
            accessxi.escape_probe_log_text_wide(accessxi.format_probe_dwords(obj, 0x40, 12)),
            accessxi.escape_probe_log_text_wide(accessxi.format_probe_dwords(obj, 0x80, 12)),
            accessxi.escape_probe_log_text_wide(accessxi.format_probe_dwords(child, 0x00, 12)),
            accessxi.escape_probe_log_text_wide(accessxi.format_probe_dwords(child, 0x40, 12)),
            accessxi.escape_probe_log_text_wide(accessxi.format_probe_dwords(entry, 0x40, 12)),
            accessxi.escape_probe_log_text_wide(samples),
            accessxi.escape_probe_log_text_wide(accessxi.status_menu_probe_pointer_fields(surface))));
    end

    return first_label, first_source;
end

function accessxi.missions_menu_category_from_index(index)
    index = tonumber(index);
    if (index == nil or index < 0) then
        return '';
    end

    local label = tostring((accessxi.missions_menu_category_labels or T{})[index + 1] or '');
    if (accessxi.is_missions_menu_category_label(label)) then
        return label;
    end
    return '';
end

function accessxi.missions_menu_category_index_context(menu_name, title, child, selected, count, page, raw)
    menu_name = tostring(menu_name or '');
    if (not menu_name:eq('menu    miss00', true)) then
        return '', -1, '';
    end

    child = tonumber(child) or 0;
    if (not accessxi.is_probe_pointer(child)) then
        return '', -1, '';
    end

    local index = tonumber(read_u32(child + 0x6C)) or -1;
    local label = accessxi.missions_menu_category_from_index(index);
    local source = '';
    if (label ~= '') then
        source = ('mission-category-native-index:child+6C=%d'):fmt(index);
    end

    local key = ('%s:%d:%d:%d:0x%08X:0x%08X:%d:%s'):fmt(
        menu_name,
        tonumber(selected) or 0,
        tonumber(count) or 0,
        tonumber(page) or 0,
        tonumber(raw) or 0,
        child,
        index,
        label);
    if (key ~= tostring(accessxi.last_missions_menu_category_index_key or '')) then
        accessxi.last_missions_menu_category_index_key = key;
        log_state(('state missions category-index-signal menu="%s" title="%s" select=%d count=%d page=%d raw=0x%08X rawLo=%d child=0x%08X index=%d label="%s" child040="%s"'):fmt(
            menu_name,
            accessxi.escape_probe_log_text(tostring(title or '')),
            tonumber(selected) or 0,
            tonumber(count) or 0,
            tonumber(page) or 0,
            tonumber(raw) or 0,
            bit.band(tonumber(raw) or 0, 0xFFFF),
            child,
            index,
            accessxi.escape_probe_log_text(label),
            accessxi.escape_probe_log_text_wide(accessxi.format_probe_dwords(child, 0x40, 12))));
    end

    return label, index, source;
end

function accessxi.log_missions_menu_native_signal(menu_name, title, obj, selected, count, page, raw, child, entry)
    menu_name = tostring(menu_name or '');
    if (not menu_name:eq('menu    miss00', true)) then
        return;
    end

    obj = tonumber(obj) or 0;
    child = tonumber(child) or 0;
    entry = tonumber(entry) or 0;
    selected = tonumber(selected) or 0;
    count = tonumber(count) or 0;
    page = tonumber(page) or 0;
    raw = tonumber(raw) or 0;

    local target = AshitaCore:GetMemoryManager():GetTarget();
    local ank_num = target ~= nil and (tonumber(safe_call(function () return target:GetWindowAnkNum(); end, -1)) or -1) or -1;
    local ank_x = target ~= nil and (tonumber(safe_call(function () return target:GetWindowAnkX(); end, -1)) or -1) or -1;
    local ank_y = target ~= nil and (tonumber(safe_call(function () return target:GetWindowAnkY(); end, -1)) or -1) or -1;
    local sub = target ~= nil and (tonumber(safe_call(function () return target:GetWindowSub(); end, -1)) or -1) or -1;
    local sub_x = target ~= nil and (tonumber(safe_call(function () return target:GetWindowSubAnkX(); end, -1)) or -1) or -1;
    local sub_y = target ~= nil and (tonumber(safe_call(function () return target:GetWindowSubAnkY(); end, -1)) or -1) or -1;
    local ank_shape = accessxi.log_missions_menu_native_ank_shape_signal(menu_name, title, selected, count, page, raw, child, entry, ank_num, target);

    local index_parts = T{};
    for _, offset in ipairs(T{ 0x24, 0x28, 0x2C, 0x30, 0x34, 0x38, 0x3C, 0x40, 0x44, 0x48, 0x4C, 0x50, 0x54, 0x58, 0x5C, 0x60, 0x64, 0x68, 0x6C, 0x70 }) do
        index_parts:append(('%02X=%d'):fmt(offset, tonumber(read_current_native_menu_index(offset)) or 0));
    end

    local surface = accessxi.is_probe_pointer(child) and (read_u32(child + 0x20) or 0) or 0;
    local key = ('%s:%d:%d:%d:0x%08X:0x%08X:0x%08X:%d:%d:%s'):fmt(
        menu_name,
        selected,
        count,
        page,
        raw,
        obj,
        entry,
        ank_num,
        sub,
        index_parts:concat(','));
    if (key == tostring(accessxi.last_missions_menu_native_signal_key or '')) then
        return;
    end
    accessxi.last_missions_menu_native_signal_key = key;

    log_state(('state missions native-signal menu="%s" title="%s" select=%d count=%d page=%d raw=0x%08X rawLo=%d obj=0x%08X child=0x%08X entry=0x%08X surface=0x%08X ank=%d ankShape=0x%08X ankXY=(%d,%d) sub=%d subAnk=(%d,%d) idx="%s" objDwords="%s" childDwords="%s" entryDwords="%s"'):fmt(
        menu_name,
        accessxi.escape_probe_log_text(tostring(title or '')),
        selected,
        count,
        page,
        raw,
        bit.band(raw, 0xFFFF),
        obj,
        child,
        entry,
        surface,
        ank_num,
        ank_shape,
        ank_x,
        ank_y,
        sub,
        sub_x,
        sub_y,
        accessxi.escape_probe_log_text(index_parts:concat(',')),
        accessxi.escape_probe_log_text(accessxi.format_probe_dwords(obj, 0x00, 18)),
        accessxi.escape_probe_log_text(accessxi.format_probe_dwords(child, 0x00, 18)),
        accessxi.escape_probe_log_text(accessxi.format_probe_dwords(entry, 0x00, 18))));
end

function accessxi.log_missions_menu_resource_probe(context, selected)
    if (accessxi.missions_menu_resource_probe_enabled ~= true) then
        return;
    end

    context = tostring(context or '');
    selected = tonumber(selected) or 0;
    if (not context:eq('Chains of Promathia', true)) then
        return;
    end

    local key = ('%s:%d'):fmt(context, selected);
    if (key == tostring(accessxi.last_missions_menu_resource_probe_key or '')) then
        return;
    end
    accessxi.last_missions_menu_resource_probe_key = key;

    local resources = safe_call(function () return AshitaCore:GetResourceManager(); end, nil);
    if (resources == nil) then
        log_state(('state nativemenu mission-resource-probe context="%s" select=%d status="no-resource-manager"'):fmt(
            accessxi.escape_probe_log_text(context),
            selected));
        return;
    end

    local packet = accessxi.mission_packet_main or {};
    local tables = T{
        'missions',
        'missions.names',
        'missions.descriptions',
        'mission.names',
        'mission.descriptions',
        'missionlog',
        'missionlog.names',
        'missionlog.descriptions',
        'mission.cop',
        'missions.cop',
        'quests.missions',
    };
    local ids = T{
        selected,
        selected + 1,
        selected + 100,
        selected + 101,
        tonumber(packet.cop) or -1,
        818,
        828,
        840,
        850,
    };
    local hits = T{};
    local seen = T{};
    for _, table_name in ipairs(tables) do
        for _, id in ipairs(ids) do
            id = tonumber(id) or -1;
            local probe_key = ('%s:%d'):fmt(table_name, id);
            if (id >= 0 and seen[probe_key] ~= true) then
                seen[probe_key] = true;
                local text = safe_call(function () return resources:GetString(table_name, id); end, '') or '';
                text = accessxi.plain_native_menu_label(accessxi.survival_guide_text(text));
                if (text ~= '' and not text:eq('Unknown', true)) then
                    hits:append(('%s[%d]="%s"'):fmt(
                        table_name,
                        id,
                        accessxi.escape_probe_log_text(text)));
                end
            end
        end
    end

    log_state(('state nativemenu mission-resource-probe context="%s" select=%d packetCop=%d hits="%s"'):fmt(
        accessxi.escape_probe_log_text(context),
        selected,
        tonumber(packet.cop) or -1,
        accessxi.escape_probe_log_text(hits:concat(' | '))));
end

function accessxi.missions_menu_category_label(entry)
    entry = tonumber(entry) or 0;
    if (not accessxi.is_probe_pointer(entry)) then
        return '', 0, '';
    end

    local category_ptr = read_u32(entry + 0xAC) or 0;
    local raw_category = accessxi.plain_native_menu_label(read_probe_string(category_ptr, 160));
    if (raw_category == '') then
        return '', category_ptr, '';
    end

    for _, label in ipairs(accessxi.missions_menu_category_labels) do
        if (raw_category:eq(label, true)) then
            return label, category_ptr, raw_category;
        end
    end

    return '', category_ptr, raw_category;
end

function accessxi.missions_menu_descriptor_row(entry)
    entry = tonumber(entry) or 0;
    if (not accessxi.is_probe_pointer(entry)) then
        return nil, 0, '', 0, 0, '', 0, '';
    end

    local category, category_ptr, raw_category = accessxi.missions_menu_category_label(entry);

    local desc = read_u32(entry + 0x0C) or 0;
    if (not accessxi.is_probe_pointer(desc)) then
        return nil, 0, '', desc, 0, category, category_ptr, raw_category;
    end

    local rec = read_u32(desc + 0x00) or 0;
    if (not accessxi.is_probe_pointer(rec)) then
        return nil, 0, '', desc, rec, category, category_ptr, raw_category;
    end

    local id = read_u32(rec + 0x04) or 0;
    local tag = read_probe_string(rec + 0x24, 48);
    if (not tostring(tag or ''):eq('menu    quest   -1', true)) then
        return nil, id, tag, desc, rec, category, category_ptr, raw_category;
    end

    return accessxi.missions_menu_descriptor_rows[id], id, tag, desc, rec, category, category_ptr, raw_category;
end

function accessxi.packet_set_bits(data, max_position)
    local bits = T{};
    max_position = tonumber(max_position) or ((#(data or '') * 8) - 1);
    for bit_index = 0, max_position do
        if (accessxi.packet_has_bit(data, bit_index)) then
            bits:append(tostring(bit_index));
        end
    end
    return bits:concat(',');
end

function accessxi.current_player_name()
    local mm = safe_call(function () return AshitaCore:GetMemoryManager(); end, nil);
    local party = mm ~= nil and safe_call(function () return mm:GetParty(); end, nil) or nil;
    local name = party ~= nil and clean_probe_text(safe_call(function () return party:GetMemberName(0); end, '')) or '';
    return tostring(name or ''):match('^[A-Za-z0-9_%-]+') or '';
end

function accessxi.current_player_server_id()
    if (type(accessxi.combat_player_server_id) ~= 'function') then
        return 0;
    end
    local server_id = tonumber(accessxi.combat_player_server_id()) or 0;
    return server_id > 0 and server_id or 0;
end

function accessxi.current_player_world_id()
    local player_name = clean_probe_text(accessxi.current_player_name()):lower();
    if (player_name == '') then return 0; end

    local account = safe_call(function () return require('ffxi.account'); end, nil);
    if (type(account) ~= 'table') then return 0; end
    local function account_call(name, index, fallback)
        local callback = account[name];
        if (type(callback) ~= 'function') then return fallback; end
        return safe_call(function ()
            if (index == nil) then return callback(); end
            return callback(index);
        end, fallback);
    end
    local count = math.max(0, math.floor(tonumber(
        account_call('get_character_count', nil, 0)) or 0));
    local selected = math.floor(tonumber(
        account_call('get_selected_character_index', nil, -1)) or -1);
    local function slot_identity(index)
        if (index < 0 or index >= count) then return '', 0; end
        local name = clean_probe_text(
            account_call('get_login_character_name', index, '')):lower();
        local world_id = tonumber(
            account_call('get_login_world_id', index, 0)) or 0;
        return name, world_id > 0 and math.floor(world_id) or 0;
    end

    local selected_name, selected_world = slot_identity(selected);
    if (selected_name == player_name and selected_world > 0) then
        return selected_world;
    end
    local unique_world, matches = 0, 0;
    for index = 0, count - 1 do
        local name, world_id = slot_identity(index);
        if (name == player_name) then
            matches = matches + 1;
            unique_world = world_id;
        end
    end
    return matches == 1 and unique_world > 0 and unique_world or 0;
end

function accessxi.current_player_identity()
    local player_name = accessxi.current_player_name();
    local world_id = accessxi.current_player_world_id();
    if (player_name == '' or world_id <= 0) then
        return '';
    end
    return ('%s:%d'):fmt(player_name:lower(), world_id);
end

function accessxi.current_objective_session_epoch()
    local identity = tostring(accessxi.current_player_identity() or ''):lower();
    local tracked_identity = tostring(accessxi.objective_session_identity or ''):lower();
    local epoch = tonumber(accessxi.objective_session_epoch) or 0;
    local generation = math.max(0,
        tonumber(accessxi.objective_session_generation) or epoch);
    local identity_lost = identity == '' and (tracked_identity ~= '' or epoch > 0);
    local identity_changed = identity ~= '' and tracked_identity ~= ''
        and identity ~= tracked_identity;
    if (identity_lost or identity_changed) then
        accessxi.mission_packet_main = {};
        accessxi.mission_packet_source = '';
        accessxi.mission_packet_session_epoch = 0;
        accessxi.quest_packet_logs = {};
        accessxi.quest_packet_source = '';
        accessxi.quest_packet_session_epoch = 0;
        accessxi.key_items_packet_tables = {};
        accessxi.key_items_packet_source = '';
        accessxi.key_items_packet_session_epoch = 0;
        accessxi.objective_inventory_counts = {};
        accessxi.inventory_packet_source = '';
        accessxi.inventory_packet_session_epoch = 0;
        accessxi.inventory_packet_key = '';
        if (type(accessxi.nav_mission_quest_reduce_signal) == 'function') then
            pcall(accessxi.nav_mission_quest_reduce_signal, { kind = 'identity-loss' });
        end
    end
    if (identity == '') then
        accessxi.objective_session_identity = '';
        accessxi.objective_session_epoch = 0;
        return 0;
    end
    if (tracked_identity ~= identity or epoch <= 0) then
        generation = math.max(generation + 1,
            math.floor(tonumber(os.time()) or 1), 1);
        accessxi.objective_session_generation = generation;
        accessxi.objective_session_identity = identity;
        accessxi.objective_session_epoch = generation;
        epoch = generation;
    end
    return epoch;
end

function accessxi.current_nation_mission_rank_state()
    local identity = accessxi.current_player_identity();
    if (identity == '') then
        return nil;
    end
    local mm = safe_call(function () return AshitaCore:GetMemoryManager(); end, nil);
    local player = mm ~= nil and safe_call(function () return mm:GetPlayer(); end, nil) or nil;
    if (player == nil) then
        return nil;
    end
    local nation = tonumber(safe_call(function () return player:GetNation(); end, nil));
    local rank = tonumber(safe_call(function () return player:GetRank(); end, nil));
    local rank_points = tonumber(safe_call(function () return player:GetRankPoints(); end, nil));
    if (nation == nil or nation < 0 or nation > 2
        or rank == nil or rank < 1 or rank > 10
        or rank_points == nil or rank_points < 0 or rank_points >= 65535) then
        return nil;
    end
    return T{
        nation = nation,
        rank = rank,
        rank_points = rank_points,
        identity = identity,
    };
end

function accessxi.table_count(values)
    local count = 0;
    for _, _ in pairs(values or {}) do
        count = count + 1;
    end
    return count;
end

function accessxi.key_items_packet_bit_count()
    local count = 0;
    for _, entry in pairs(accessxi.key_items_packet_tables or {}) do
        if (type(entry) == 'table') then
            count = count + accessxi.packet_bit_count(tostring(entry.flags or ''));
        end
    end
    return count;
end

function accessxi.key_items_packet_cache_key()
    local parts = T{};
    local indices = T{};
    for table_index, _ in pairs(accessxi.key_items_packet_tables or {}) do
        indices:append(tonumber(table_index) or -1);
    end
    table.sort(indices);
    for _, table_index in ipairs(indices) do
        local entry = (accessxi.key_items_packet_tables or {})[table_index];
        if (type(entry) == 'table') then
            parts:append(('%d:%s:%s'):fmt(
                table_index,
                accessxi.packet_hex(tostring(entry.flags or '')),
                accessxi.packet_hex(tostring(entry.seen or ''))));
        end
    end
    return parts:concat('|');
end

function accessxi.key_items_packet_freshness_key()
    local parts = T{
        tostring(accessxi.key_items_packet_source or ''),
        tostring(accessxi.key_items_packet_identity or ''):lower(),
        tostring(tonumber(accessxi.key_items_packet_session_epoch) or 0),
    };
    local indices = T{};
    for table_index, _ in pairs(accessxi.key_items_packet_tables or {}) do
        indices:append(tonumber(table_index) or -1);
    end
    table.sort(indices);
    for _, table_index in ipairs(indices) do
        local entry = (accessxi.key_items_packet_tables or {})[table_index];
        if (type(entry) == 'table') then
            parts:append(('%d:%s:%s:%d'):fmt(
                table_index,
                tostring(entry.source or ''),
                tostring(entry.identity or ''):lower(),
                tonumber(entry.session_epoch) or 0));
        end
    end
    return parts:concat('|');
end

function accessxi.save_key_items_packet_cache()
    local tables = accessxi.key_items_packet_tables or {};
    local player_name = accessxi.current_player_name();
    local server_id = tonumber(accessxi.current_player_server_id()) or 0;
    if (player_name == '' or server_id <= 0 or next(tables) == nil) then
        return;
    end

    local indices = T{};
    for table_index, _ in pairs(tables) do
        indices:append(tonumber(table_index) or -1);
    end
    table.sort(indices);

    local f = io.open(accessxi.key_items_packet_cache_path, 'w');
    if (f == nil) then
        return;
    end
    f:write(('time\t%d\n'):fmt(os.time()));
    f:write(('player\t%s\n'):fmt(player_name));
    f:write(('server_id\t%d\n'):fmt(server_id));
    for _, table_index in ipairs(indices) do
        local entry = tables[table_index];
        if (type(entry) == 'table' and #(tostring(entry.flags or '')) == 64) then
            f:write(('table\t%d\t%s\t%s\n'):fmt(
                table_index,
                accessxi.packet_hex(tostring(entry.flags or '')),
                accessxi.packet_hex(tostring(entry.seen or ''))));
        end
    end
    f:close();
end

function accessxi.restore_key_items_packet_cache_if_needed()
    if (accessxi.key_items_packet_cache_loaded == true or next(accessxi.key_items_packet_tables or {}) ~= nil) then
        return;
    end

    local player_name = accessxi.current_player_name();
    local current_server_id = tonumber(accessxi.current_player_server_id()) or 0;
    local player_identity = accessxi.current_player_identity();
    if (player_name == '' or current_server_id <= 0 or player_identity == '') then
        return;
    end
    accessxi.key_items_packet_cache_loaded = true;

    local f = io.open(accessxi.key_items_packet_cache_path, 'r');
    if (f == nil) then
        return;
    end

    local cached_time = 0;
    local cached_player = '';
    local cached_server_id = 0;
    local tables = {};
    for line in f:lines() do
        local key, rest = line:match('^([^\t]+)\t(.*)$');
        if (key == 'time') then
            cached_time = tonumber(rest) or 0;
        elseif (key == 'player') then
            cached_player = tostring(rest or '');
        elseif (key == 'server_id') then
            cached_server_id = tonumber(rest) or 0;
        elseif (key == 'table') then
            local table_index, flags_hex, seen_hex = rest:match('^(%d+)\t([%x%s]+)\t([%x%s]*)$');
            table_index = tonumber(table_index) or -1;
            local flags = accessxi.packet_hex_to_bytes(flags_hex);
            local seen = accessxi.packet_hex_to_bytes(seen_hex);
            if (table_index >= 0 and table_index <= 7 and #flags == 64) then
                tables[table_index] = {
                    flags = flags,
                    seen = seen,
                    tick = tick(),
                    source = 'cache',
                    identity = player_identity,
                };
            end
        end
    end
    f:close();

    if (cached_time <= 0 or (os.time() - cached_time) > 86400) then
        return;
    end
    if (cached_player ~= player_name or cached_server_id <= 0 or cached_server_id ~= current_server_id) then
        return;
    end
    if (next(tables) == nil) then
        return;
    end

    accessxi.key_items_packet_tables = tables;
    accessxi.key_items_packet_player = player_name;
    accessxi.key_items_packet_identity = player_identity;
    accessxi.key_items_packet_source = 'cache';
    accessxi.key_items_packet_key = accessxi.key_items_packet_cache_key();
    accessxi.key_items_packet_freshness = accessxi.key_items_packet_freshness_key();
    log_line(('key items packet cache restored player="%s" tables=%d ownedBits=%d'):fmt(
        player_name,
        accessxi.table_count(tables),
        accessxi.key_items_packet_bit_count()));
end

function accessxi.key_items_packet_has_id(id)
    id = tonumber(id) or -1;
    if (id < 0) then
        return false;
    end
    accessxi.restore_key_items_packet_cache_if_needed();

    local table_index = math.floor(id / 512);
    local bit_index = id % 512;
    local entry = (accessxi.key_items_packet_tables or {})[table_index];
    if (type(entry) ~= 'table' or #(tostring(entry.flags or '')) < 64) then
        return false;
    end
    return accessxi.packet_has_bit(tostring(entry.flags or ''), bit_index);
end

function accessxi.capture_key_items_packet(e)
    if (e == nil or e.id ~= 0x055) then
        return;
    end

    local data = e.data_modified or e.data or '';
    if (#data < 0x88) then
        log_line(('key items packet short len=%d'):fmt(#data));
        return;
    end

    local table_index = accessxi.packet_u16(data, 0x84 + 1);
    if (table_index < 0 or table_index > 7) then
        log_line(('key items packet invalid table=%d len=%d'):fmt(table_index, #data));
        return;
    end

    if (type(accessxi.nav_mission_quest_sync_character) == 'function') then
        accessxi.nav_mission_quest_sync_character('key-items-packet');
    end
    local player_name = accessxi.current_player_name();
    local player_identity = accessxi.current_player_identity();
    local key_item_session_epoch = accessxi.current_objective_session_epoch();
    local previous_entry = type(accessxi.key_items_packet_tables) == 'table'
        and accessxi.key_items_packet_tables[table_index] or nil;
    local previous_flags = type(previous_entry) == 'table'
        and tostring(previous_entry.flags or '') or '';
    local previous_complete = #previous_flags == 64
        and tostring(accessxi.key_items_packet_source or '') == 'packet_in_055'
        and tostring(accessxi.key_items_packet_identity or ''):lower()
            == tostring(player_identity or ''):lower()
        and tonumber(accessxi.key_items_packet_session_epoch) == key_item_session_epoch
        and tostring(previous_entry.source or '') == 'packet_in_055'
        and tostring(previous_entry.identity or ''):lower()
            == tostring(player_identity or ''):lower()
        and tonumber(previous_entry.session_epoch) == key_item_session_epoch;
    if (player_identity ~= '' and tostring(accessxi.key_items_packet_identity or '') ~= ''
        and player_identity ~= tostring(accessxi.key_items_packet_identity or '')) then
        accessxi.key_items_packet_tables = {};
        accessxi.key_items_packet_key = '';
        accessxi.key_items_owned_cache = {};
    end
    if (player_name ~= '') then
        accessxi.key_items_packet_player = player_name;
    end
    accessxi.key_items_packet_identity = player_identity;
    accessxi.key_items_packet_source = 'packet_in_055';
    accessxi.key_items_packet_session_epoch = key_item_session_epoch;

    local previous_key = tostring(accessxi.key_items_packet_key or '');
    local previous_freshness = type(accessxi.key_items_packet_freshness_key) == 'function'
        and accessxi.key_items_packet_freshness_key() or '';
    accessxi.key_items_packet_tables = accessxi.key_items_packet_tables or {};
    accessxi.key_items_packet_tables[table_index] = {
        flags = data:sub(0x04 + 1, 0x04 + 64),
        seen = data:sub(0x44 + 1, 0x44 + 64),
        tick = tick(),
        source = 'packet_in_055',
        identity = player_identity,
        session_epoch = key_item_session_epoch,
    };
    accessxi.key_items_owned_cache = {};
    accessxi.key_items_packet_cache_loaded = true;

    local key = accessxi.key_items_packet_cache_key();
    local freshness = accessxi.key_items_packet_freshness_key();
    accessxi.key_items_packet_freshness = freshness;
    if (key ~= previous_key) then
        accessxi.key_items_packet_key = key;
        accessxi.save_key_items_packet_cache();
        log_line(('key items packet id=0x%03X table=%d tables=%d ownedBits=%d player="%s" hex="%s"'):fmt(
            e.id,
            table_index,
            accessxi.table_count(accessxi.key_items_packet_tables),
            accessxi.key_items_packet_bit_count(),
            player_name,
            accessxi.packet_hex_limit(data, 32)));
    end
    if ((key ~= previous_key or freshness ~= previous_freshness)
        and type(accessxi.queue_mission_quest_state_change) == 'function') then
        accessxi.queue_mission_quest_state_change(
            'objective', ('packet-0x055-%d'):fmt(table_index));
    end
    if (previous_complete and player_identity ~= '' and key_item_session_epoch > 0
        and type(accessxi.nav_mission_quest_reduce_signal) == 'function') then
        local current_flags = tostring(
            accessxi.key_items_packet_tables[table_index].flags or '');
        local world_id = tonumber(accessxi.current_player_world_id()) or 0;
        if (world_id > 0) then
            for bit_index = 0, 511 do
                local before_owned = accessxi.packet_has_bit(previous_flags, bit_index) == true;
                local after_owned = accessxi.packet_has_bit(current_flags, bit_index) == true;
                if (not before_owned and after_owned) then
                    local key_item_id = (table_index * 512) + bit_index;
                    local key_item_name = type(accessxi.objective_key_item_name_for_id)
                        == 'function' and tostring(
                            accessxi.objective_key_item_name_for_id(key_item_id) or '') or '';
                    if (key_item_name ~= '') then
                        if (tonumber(accessxi.objective_signal_session_epoch)
                            ~= key_item_session_epoch) then
                            accessxi.objective_signal_session_epoch = key_item_session_epoch;
                            accessxi.objective_signal_sequence = 0;
                        end
                        local sequence = (tonumber(accessxi.objective_signal_sequence) or 0) + 1;
                        accessxi.objective_signal_sequence = sequence;
                        pcall(accessxi.nav_mission_quest_reduce_signal, {
                            kind = 'key-item-delta', key_item_id = key_item_id,
                            key_item_name = key_item_name,
                            before_owned = false, after_owned = true,
                            snapshot_complete = true,
                            character_identity = player_identity, world_id = world_id,
                            session_epoch = key_item_session_epoch,
                            sequence = sequence, tick = tick(),
                            corpus_revision = tonumber(accessxi.nav_catalog_revision) or 0,
                        });
                    end
                end
            end
        end
    end
end

function accessxi.merit_packet_preview(entries, max_parts)
    local parts = T{};
    entries = entries or accessxi.merit_packet_entries or {};
    max_parts = tonumber(max_parts) or 32;
    local ids = T{};
    for id, _ in pairs(entries) do
        ids:append(tonumber(id) or 0);
    end
    table.sort(ids);
    for _, id in ipairs(ids) do
        local entry = entries[id];
        if (entry ~= nil) then
            local label = accessxi.merit_resource_label(id);
            if (label == '') then
                label = tostring(id);
            end
            parts:append(('%d:%s rank=%d next=%d'):fmt(
                id,
                label,
                tonumber(entry.value) or 0,
                tonumber(entry.next_cost) or 0));
            if (parts:len() >= max_parts) then
                break;
            end
        end
    end
    return parts:concat(' | ');
end

function accessxi.save_merit_packet_cache()
    local entries = accessxi.merit_packet_entries or {};
    local player_name = accessxi.current_player_name();
    if (player_name == '') then
        return;
    end

    local ids = T{};
    for id, _ in pairs(entries) do
        ids:append(tonumber(id) or 0);
    end
    if (ids:len() <= 0) then
        return;
    end
    table.sort(ids);

    local f = io.open(accessxi.merit_packet_cache_path, 'w');
    if (f == nil) then
        return;
    end
    f:write(('time\t%d\n'):fmt(os.time()));
    f:write(('player\t%s\n'):fmt(player_name));
    for _, id in ipairs(ids) do
        local entry = entries[id];
        if (entry ~= nil) then
            f:write(('entry\t%d\t%d\t%d\n'):fmt(
                id,
                tonumber(entry.next_cost) or 0,
                tonumber(entry.value) or 0));
        end
    end
    f:close();
end

function accessxi.restore_merit_packet_cache_if_needed()
    if (accessxi.merit_packet_cache_loaded == true or next(accessxi.merit_packet_entries or {}) ~= nil) then
        return;
    end

    local player_name = accessxi.current_player_name();
    if (player_name == '') then
        return;
    end
    accessxi.merit_packet_cache_loaded = true;

    local f = io.open(accessxi.merit_packet_cache_path, 'r');
    if (f == nil) then
        return;
    end

    local cached_time = 0;
    local cached_player = '';
    local entries = {};
    for line in f:lines() do
        local key, rest = line:match('^([^\t]+)\t(.*)$');
        if (key == 'time') then
            cached_time = tonumber(rest) or 0;
        elseif (key == 'player') then
            cached_player = tostring(rest or '');
        elseif (key == 'entry') then
            local id, next_cost, value = rest:match('^(%d+)\t(%d+)\t(%d+)$');
            id = tonumber(id) or 0;
            if (id > 0) then
                entries[id] = {
                    id = id,
                    next_cost = tonumber(next_cost) or 0,
                    value = tonumber(value) or 0,
                    tick = tick(),
                    source = 'cache',
                };
            end
        end
    end
    f:close();

    if (cached_time <= 0 or (os.time() - cached_time) > 86400) then
        return;
    end
    if (cached_player ~= player_name) then
        return;
    end
    if (next(entries) == nil) then
        return;
    end

    accessxi.merit_packet_entries = entries;
    accessxi.merit_packet_tick = tick();
    accessxi.merit_packet_player = player_name;
    log_line(('merit packet cache restored player="%s" count=%d preview="%s"'):fmt(
        player_name,
        accessxi.table_count(entries),
        accessxi.escape_probe_log_text(accessxi.merit_packet_preview(entries, 20))));
end

function accessxi.capture_merit_packet(e)
    if (e == nil or e.id ~= 0x08C) then
        return;
    end

    local data = e.data_modified or e.data or '';
    if (#data < 0x0C) then
        log_line(('merit packet short len=%d'):fmt(#data));
        return;
    end

    local player_name = accessxi.current_player_name();
    if (player_name ~= '' and tostring(accessxi.merit_packet_player or '') ~= '' and player_name ~= tostring(accessxi.merit_packet_player or '')) then
        accessxi.merit_packet_entries = {};
        accessxi.merit_packet_key = '';
    end
    if (player_name ~= '') then
        accessxi.merit_packet_player = player_name;
    end

    local count = accessxi.packet_byte(data, 0x04 + 1);
    local entries = accessxi.merit_packet_entries or {};
    local changed = 0;
    for i = 0, math.min(count - 1, 255) do
        local off = 0x08 + (i * 4);
        if (#data < (off + 4)) then
            break;
        end
        local id = accessxi.packet_u16(data, off + 1);
        local next_cost = accessxi.packet_byte(data, off + 0x02 + 1);
        local value = accessxi.packet_byte(data, off + 0x03 + 1);
        if (id > 0) then
            entries[id] = {
                id = id,
                next_cost = next_cost,
                value = value,
                tick = tick(),
                source = 'packet_in_08c',
            };
            changed = changed + 1;
        end
    end

    if (next(entries) == nil or changed <= 0) then
        return;
    end

    local key_parts = T{};
    local ids = T{};
    for id, _ in pairs(entries) do
        ids:append(tonumber(id) or 0);
    end
    table.sort(ids);
    for _, id in ipairs(ids) do
        local entry = entries[id];
        key_parts:append(('%d:%d:%d'):fmt(id, tonumber(entry.value) or 0, tonumber(entry.next_cost) or 0));
    end
    local key = key_parts:concat(',');

    accessxi.merit_packet_entries = entries;
    accessxi.merit_packet_tick = tick();
    accessxi.merit_packet_cache_loaded = true;
    accessxi.save_merit_packet_cache();
    if (key ~= tostring(accessxi.merit_packet_key or '')) then
        accessxi.merit_packet_key = key;
        log_line(('merit packet id=0x%03X count=%d entries=%d player="%s" preview="%s" hex="%s"'):fmt(
            e.id,
            count,
            accessxi.table_count(entries),
            player_name,
            accessxi.escape_probe_log_text(accessxi.merit_packet_preview(entries, 32)),
            accessxi.packet_hex(data)));
    end
end

function accessxi.capture_merit_misc_packet(e)
    if (e == nil or e.id ~= 0x063) then
        return;
    end

    local data = e.data_modified or e.data or '';
    if (#data < 0x0D) then
        return;
    end

    local packet_type = accessxi.packet_u16(data, 0x04 + 1);
    if (packet_type ~= 0x02) then
        return;
    end

    local limit_points = accessxi.packet_u16(data, 0x08 + 1);
    local packed = accessxi.packet_u16(data, 0x0A + 1);
    local merit_points = bit.band(packed, 0x007F);
    local blu_bonus = bit.band(bit.rshift(packed, 7), 0x003F);
    local flags = bit.rshift(packed, 13);
    local max_merit_points = accessxi.packet_byte(data, 0x0C + 1);
    local key = ('%d:%d:%d:%d:%d'):fmt(limit_points, merit_points, blu_bonus, flags, max_merit_points);

    accessxi.merit_misc_limit_points = limit_points;
    accessxi.merit_misc_merit_points = merit_points;
    accessxi.merit_misc_blu_bonus = blu_bonus;
    accessxi.merit_misc_flags = flags;
    accessxi.merit_misc_max_merit_points = max_merit_points;
    accessxi.merit_misc_tick = tick();
    if (key ~= tostring(accessxi.merit_misc_key or '')) then
        accessxi.merit_misc_key = key;
        log_line(('merit misc packet id=0x%03X type=0x%04X limit=%d merits=%d max=%d bluBonus=%d flags=0x%X hex="%s"'):fmt(
            e.id,
            packet_type,
            limit_points,
            merit_points,
            max_merit_points,
            blu_bonus,
            flags,
            accessxi.packet_hex(data)));
    end
end

function accessxi.job_point_packet_preview(entries, max_parts)
    local parts = T{};
    entries = entries or accessxi.job_point_packet_entries or {};
    max_parts = tonumber(max_parts) or 32;
    local ids = T{};
    for id, _ in pairs(entries) do
        ids:append(tonumber(id) or 0);
    end
    table.sort(ids);
    for _, id in ipairs(ids) do
        local entry = entries[id];
        if (entry ~= nil) then
            local label = accessxi.job_point_resource_label(id);
            if (label == '') then
                label = tostring(id);
            end
            parts:append(('%d:%s rank=%d next=%d'):fmt(
                id,
                label,
                tonumber(entry.value) or 0,
                tonumber(entry.next_cost) or 0));
            if (parts:len() >= max_parts) then
                break;
            end
        end
    end
    return parts:concat(' | ');
end

function accessxi.capture_job_point_packet(e)
    if (e == nil or e.id ~= 0x08D) then
        return;
    end

    local data = e.data_modified or e.data or '';
    if (#data < 0x08) then
        log_line(('jobpoint packet short len=%d'):fmt(#data));
        return;
    end

    local entries = accessxi.job_point_packet_entries or {};
    local changed = 0;
    for i = 0, 63 do
        local off = 0x04 + (i * 4);
        if (#data < (off + 4)) then
            break;
        end
        local packed_id = accessxi.packet_u16(data, off + 1);
        local packed_state = accessxi.packet_u16(data, off + 0x02 + 1);
        local index = bit.band(packed_id, 0x1F);
        local job_id = bit.rshift(packed_id, 5);
        local next_cost = bit.band(packed_state, 0x03FF);
        local value = bit.rshift(packed_state, 10);
        local id = (job_id * 32) + index;
        if (job_id >= 1 and job_id <= 22 and index >= 0 and index <= 9 and id > 0) then
            entries[id] = {
                id = id,
                job = job_id,
                index = index,
                next_cost = next_cost,
                value = value,
                tick = tick(),
                source = 'packet_in_08d',
            };
            changed = changed + 1;
        end
    end

    if (changed <= 0) then
        return;
    end

    local key_parts = T{};
    local ids = T{};
    for id, _ in pairs(entries) do
        ids:append(tonumber(id) or 0);
    end
    table.sort(ids);
    for _, id in ipairs(ids) do
        local entry = entries[id];
        key_parts:append(('%d:%d:%d'):fmt(id, tonumber(entry.value) or 0, tonumber(entry.next_cost) or 0));
    end
    local key = key_parts:concat(',');

    accessxi.job_point_packet_entries = entries;
    accessxi.job_point_packet_tick = tick();
    if (key ~= tostring(accessxi.job_point_packet_key or '')) then
        accessxi.job_point_packet_key = key;
        log_line(('jobpoint packet id=0x%03X changed=%d entries=%d preview="%s" hex="%s"'):fmt(
            e.id,
            changed,
            accessxi.table_count(entries),
            accessxi.escape_probe_log_text(accessxi.job_point_packet_preview(entries, 32)),
            accessxi.packet_hex(data)));
    end
end

function accessxi.capture_job_point_misc_packet(e)
    if (e == nil or e.id ~= 0x063) then
        return;
    end

    local data = e.data_modified or e.data or '';
    if (#data < 0x12) then
        return;
    end

    local packet_type = accessxi.packet_u16(data, 0x04 + 1);
    if (packet_type ~= 0x05) then
        return;
    end

    local access = accessxi.packet_byte(data, 0x08 + 1);
    local jobs = {};
    local key_parts = T{};
    for job_id = 1, 22 do
        local off = 0x0C + (job_id * 6);
        if (#data < (off + 6)) then
            break;
        end
        local capacity_points = accessxi.packet_u16(data, off + 1);
        local current_jp = accessxi.packet_u16(data, off + 0x02 + 1);
        local total_spent = accessxi.packet_u16(data, off + 0x04 + 1);
        jobs[job_id] = {
            job = job_id,
            capacity_points = capacity_points,
            current_jp = current_jp,
            total_spent = total_spent,
            tick = tick(),
        };
        key_parts:append(('%d:%d:%d:%d'):fmt(job_id, capacity_points, current_jp, total_spent));
    end

    local key = ('%d:%s'):fmt(access, key_parts:concat(','));
    accessxi.job_point_misc_access = access;
    accessxi.job_point_misc_jobs = jobs;
    accessxi.job_point_misc_tick = tick();
    if (key ~= tostring(accessxi.job_point_misc_key or '')) then
        accessxi.job_point_misc_key = key;
        local preview = T{};
        for job_id = 1, 22 do
            local row = jobs[job_id];
            if (row ~= nil and ((tonumber(row.capacity_points) or 0) > 0 or (tonumber(row.current_jp) or 0) > 0 or (tonumber(row.total_spent) or 0) > 0)) then
                preview:append(('%s cp=%d jp=%d spent=%d'):fmt(
                    accessxi.job_name(job_id),
                    tonumber(row.capacity_points) or 0,
                    tonumber(row.current_jp) or 0,
                    tonumber(row.total_spent) or 0));
            end
            if (preview:len() >= 12) then
                break;
            end
        end
        log_line(('jobpoint misc packet id=0x%03X type=0x%04X access=%d jobs=%d preview="%s" hex="%s"'):fmt(
            e.id,
            packet_type,
            access,
            accessxi.table_count(jobs),
            accessxi.escape_probe_log_text(preview:concat(' | ')),
            accessxi.packet_hex(data)));
    end
end

function accessxi.trace_job_point_packet(e, direction)
    if (e == nil or (tonumber(accessxi.job_point_packet_trace_until) or 0) < tick()) then
        return;
    end

    local id = tonumber(e.id) or 0;
    if (id ~= 0x08D and id ~= 0x063 and id ~= 0x0BF and id ~= 0x0C0) then
        return;
    end

    local data = e.data_modified or e.data or '';
    local detail = '';
    if (id == 0x08D) then
        detail = 'jobpoint-ranks';
    elseif (id == 0x063) then
        detail = ('type=0x%04X'):fmt(accessxi.packet_u16(data, 0x04 + 1));
    elseif (id == 0x0BF) then
        detail = ('spendIndex=%d'):fmt(accessxi.packet_u16(data, 0x04 + 1));
    elseif (id == 0x0C0) then
        detail = 'request';
    end

    local key = ('%s:%03X:%s:%s'):fmt(tostring(direction or ''), id, detail, accessxi.packet_hex(data));
    if (key == tostring(accessxi.job_point_packet_trace_key or '')) then
        return;
    end
    accessxi.job_point_packet_trace_key = key;
    log_line(('jobpoint packet trace direction=%s id=0x%03X %s hex="%s"'):fmt(
        tostring(direction or ''),
        id,
        detail,
        accessxi.packet_hex(data)));
end

function accessxi.trace_merit_packet(e, direction)
    if (e == nil or (tonumber(accessxi.merit_packet_trace_until) or 0) < tick()) then
        return;
    end

    local id = tonumber(e.id) or 0;
    if (id ~= 0x08C and id ~= 0x063 and id ~= 0x0BE and id ~= 0x0C0) then
        return;
    end

    local data = e.data_modified or e.data or '';
    local detail = '';
    if (id == 0x08C) then
        detail = ('count=%d'):fmt(accessxi.packet_byte(data, 0x04 + 1));
    elseif (id == 0x063) then
        detail = ('type=0x%04X'):fmt(accessxi.packet_u16(data, 0x04 + 1));
    elseif (id == 0x0BE) then
        detail = ('mode=%d flag=%d merit=%d'):fmt(
            accessxi.packet_byte(data, 0x04 + 1),
            accessxi.packet_byte(data, 0x05 + 1),
            accessxi.packet_u16(data, 0x06 + 1));
    end

    local key = ('%s:%03X:%s:%s'):fmt(tostring(direction or ''), id, detail, accessxi.packet_hex(data));
    if (key ~= tostring(accessxi.merit_packet_trace_key or '')) then
        accessxi.merit_packet_trace_key = key;
        log_line(('merit packet trace dir=%s id=0x%03X len=%d %s hex="%s"'):fmt(
            tostring(direction or ''),
            id,
            #data,
            detail,
            accessxi.packet_hex(data)));
    end
end

function accessxi.trace_help_desk_packet(e, direction)
    if (e == nil or (tonumber(accessxi.help_desk_packet_trace_until) or 0) < tick()) then
        return;
    end

    if ((tonumber(accessxi.help_desk_packet_trace_count) or 0) >= (tonumber(accessxi.help_desk_packet_trace_limit) or 0)) then
        return;
    end

    local id = tonumber(e.id) or 0;
    if (id ~= 0x0B5 and id ~= 0x0D4) then
        return;
    end

    local data = e.data_modified or e.data or '';
    local detail = '';
    if (id == 0x0B5) then
        detail = ('unknown1="%s" opens=%d unknown2=0x%08X nonzero="%s" ascii="%s"'):fmt(
            accessxi.packet_hex_limit(data:sub(0x04 + 1, 0x17 + 1), 0x14),
            accessxi.packet_u32(data, 0x18 + 1),
            accessxi.packet_u32(data, 0x1C + 1),
            accessxi.packet_nonzero_words(data, 0x04 + 1, 0x1F + 1),
            accessxi.escape_probe_log_text(accessxi.packet_ascii_preview(data, 64)));
    elseif (id == 0x0D4) then
        detail = ('opens=%d nonzero="%s" ascii="%s"'):fmt(
            accessxi.packet_u32(data, 0x04 + 1),
            accessxi.packet_nonzero_words(data, 0x04 + 1, math.min(#data, 0x10)),
            accessxi.escape_probe_log_text(accessxi.packet_ascii_preview(data, 64)));
    end

    local key = ('%s:%03X:%s:%s'):fmt(tostring(direction or ''), id, detail, accessxi.packet_hex(data));
    if (key == tostring(accessxi.help_desk_packet_trace_key or '')) then
        return;
    end

    accessxi.help_desk_packet_trace_key = key;
    accessxi.help_desk_packet_trace_count = (tonumber(accessxi.help_desk_packet_trace_count) or 0) + 1;
    log_line(('helpdesk packet trace dir=%s id=0x%03X len=%d %s hex="%s"'):fmt(
        tostring(direction or ''),
        id,
        #data,
        detail,
        accessxi.packet_hex(data)));
end

function accessxi.friend_list_packet_name_record(data, id)
    data = data or '';
    if ((tonumber(id) or 0) ~= 0x00E or #data < (0x34 + 2)) then
        return nil;
    end

    local name = accessxi.packet_ascii_z_at(data, 0x34 + 1, 24);
    if (name == '') then
        return nil;
    end

    local key_parts = T{};
    for pos = 0x04 + 1, 0x0B + 1 do
        key_parts:append(('%02X'):fmt(accessxi.packet_byte(data, pos)));
    end

    return {
        name = name,
        key = key_parts:concat(''),
        word00 = accessxi.packet_u16(data, 0x00 + 1),
        word02 = accessxi.packet_u16(data, 0x02 + 1),
        word04 = accessxi.packet_u16(data, 0x04 + 1),
        word06 = accessxi.packet_u16(data, 0x06 + 1),
        word08 = accessxi.packet_u16(data, 0x08 + 1),
        word0A = accessxi.packet_u16(data, 0x0A + 1),
        word32 = accessxi.packet_u16(data, 0x32 + 1),
    };
end

function accessxi.friend_list_packet_cache_record(record)
    if (record == nil or tostring(record.key or '') == '') then
        return 0;
    end

    accessxi.friend_list_packet_records_by_key = accessxi.friend_list_packet_records_by_key or {};
    accessxi.friend_list_packet_record_order = accessxi.friend_list_packet_record_order or T{};

    local existing = accessxi.friend_list_packet_records_by_key[record.key];
    if (existing ~= nil) then
        record.ordinal = tonumber(existing.ordinal) or 0;
        accessxi.friend_list_packet_records_by_key[record.key] = record;
        return record.ordinal;
    end

    local ordinal = #(accessxi.friend_list_packet_record_order or {}) + 1;
    record.ordinal = ordinal;
    accessxi.friend_list_packet_record_order:append(record.key);
    accessxi.friend_list_packet_records_by_key[record.key] = record;
    return ordinal;
end

function accessxi.capture_friend_list_packet(e, direction)
    if (e == nil) then
        return;
    end

    local data = e.data_modified or e.data or accessxi.packet_event_string(e, 'data_modified', 'size') or accessxi.packet_event_string(e, 'data', 'size') or '';
    local record = accessxi.friend_list_packet_name_record(data, tonumber(e.id) or 0);
    if (record == nil) then
        return;
    end

    record.direction = tostring(direction or '');
    record.tick = tick();
    accessxi.friend_list_packet_cache_record(record);
    accessxi.friend_list_packet_cache_tick = tick();
end

function accessxi.friend_list_packet_cache_count()
    return #(accessxi.friend_list_packet_record_order or {});
end

function accessxi.friend_list_packet_record_by_ordinal(ordinal)
    ordinal = tonumber(ordinal) or 0;
    if (ordinal <= 0) then
        return nil;
    end

    local order = accessxi.friend_list_packet_record_order or T{};
    local key = order[ordinal];
    if (key == nil or tostring(key) == '') then
        return nil;
    end

    return (accessxi.friend_list_packet_records_by_key or {})[key];
end

function accessxi.friend_list_packet_selected_label(menu_name, selected, count)
    selected = tonumber(selected) or 0;
    count = tonumber(count) or 0;
    if (not tostring(menu_name or ''):eq('menu    friend', true) or selected <= 0 or count <= 0) then
        return '', '';
    end

    local cache_age = tick() - (tonumber(accessxi.friend_list_packet_cache_tick) or 0);
    local packet_count = accessxi.friend_list_packet_cache_count();
    if (packet_count <= 0 or cache_age > 120000) then
        if (accessxi.friend_list_any_probe_active()) then
            local miss_key = ('%s:%d:%d:%d:%d'):fmt(tostring(menu_name or ''), selected, count, packet_count, cache_age);
            if (miss_key ~= tostring(accessxi.last_friend_list_packet_map_miss_key or '')) then
                accessxi.last_friend_list_packet_map_miss_key = miss_key;
                log_state(('state friend-list packet-map-missing menu="%s" select=%d count=%d packets=%d age=%d note="no recent packet-backed names; no fallback"'):fmt(
                    tostring(menu_name or ''),
                    selected,
                    count,
                    packet_count,
                    cache_age));
            end
        end
        return '', '';
    end

    local ordinal = 0;
    local mapping = '';
    if (packet_count == count) then
        ordinal = selected;
        mapping = 'direct';
    elseif (packet_count == (count - 1) and selected > 1) then
        ordinal = selected - 1;
        mapping = 'after-category-toggle';
    else
        if (accessxi.friend_list_any_probe_active()) then
            local miss_key = ('%s:%d:%d:%d'):fmt(tostring(menu_name or ''), selected, count, packet_count);
            if (miss_key ~= tostring(accessxi.last_friend_list_packet_map_count_key or '')) then
                accessxi.last_friend_list_packet_map_count_key = miss_key;
                log_state(('state friend-list packet-map-refused menu="%s" select=%d count=%d packets=%d note="visible row count does not match packet list; no fallback"'):fmt(
                    tostring(menu_name or ''),
                    selected,
                    count,
                    packet_count));
            end
        end
        return '', '';
    end

    local record = accessxi.friend_list_packet_record_by_ordinal(ordinal);
    local label = accessxi.plain_native_menu_label((record ~= nil) and tostring(record.name or '') or '');
    if (label == '') then
        return '', '';
    end

    if (accessxi.friend_list_any_probe_active()) then
        local key = ('%s:%d:%d:%d:%s:%s'):fmt(tostring(menu_name or ''), selected, count, ordinal, mapping, label);
        if (key ~= tostring(accessxi.last_friend_list_packet_map_key or '')) then
            accessxi.last_friend_list_packet_map_key = key;
            log_state(('state friend-list packet-map menu="%s" select=%d count=%d packets=%d ordinal=%d mapping="%s" label="%s" key="%s"'):fmt(
                tostring(menu_name or ''),
                selected,
                count,
                packet_count,
                ordinal,
                mapping,
                accessxi.escape_probe_log_text(label),
                accessxi.escape_probe_log_text(tostring((record ~= nil) and record.key or ''))));
        end
    end

    return label, ('packet-0x00E:%s:%d'):fmt(mapping, ordinal);
end

function accessxi.trace_friend_list_packet(e, direction)
    if (e == nil or (tonumber(accessxi.friend_list_packet_trace_until) or 0) < tick()) then
        return;
    end

    local trace_count = tonumber(accessxi.friend_list_packet_trace_count) or 0;
    local trace_limit = tonumber(accessxi.friend_list_packet_trace_limit) or 80;
    if (trace_count >= trace_limit) then
        return;
    end

    local data = e.data_modified or e.data or accessxi.packet_event_string(e, 'data_modified', 'size') or accessxi.packet_event_string(e, 'data', 'size') or '';
    local id = tonumber(e.id) or 0;
    local selected = read_current_native_menu_index(0x4C);
    local count = read_current_native_menu_index(0x58);
    local menu_name = tostring(get_menu_name() or '');
    local window_name = '';
    local target = safe_call(function () return AshitaCore:GetMemoryManager():GetTarget(); end, nil);
    if (target ~= nil) then
        window_name = accessxi.plain_native_menu_label(safe_call(function () return target:GetWindowName(); end, '') or '');
    end

    local key = ('%s:%03X:%d:%s:%s'):fmt(
        tostring(direction or ''),
        id,
        #(data or ''),
        menu_name,
        accessxi.packet_hex_limit(data, 32));
    if (key == tostring(accessxi.friend_list_packet_trace_key or '')) then
        return;
    end

    accessxi.friend_list_packet_trace_key = key;
    accessxi.friend_list_packet_trace_count = trace_count + 1;
    local record = accessxi.friend_list_packet_name_record(data, id);
    if (record ~= nil) then
        local ordinal = accessxi.friend_list_packet_cache_record(record);
        log_line(('state friend-list packet-name dir=%s n=%d ordinal=%d menu="%s" window="%s" selected=%d count=%d key="%s" name="%s" len=%d w00=0x%04X w02=0x%04X w04=0x%04X w06=0x%04X w08=0x%04X w0A=0x%04X w32=0x%04X'):fmt(
            tostring(direction or ''),
            trace_count + 1,
            ordinal,
            accessxi.escape_probe_log_text(menu_name),
            accessxi.escape_probe_log_text(window_name),
            selected,
            count,
            accessxi.escape_probe_log_text(record.key),
            accessxi.escape_probe_log_text(record.name),
            #record.name,
            record.word00,
            record.word02,
            record.word04,
            record.word06,
            record.word08,
            record.word0A,
            record.word32));
    end
    log_line(('friend packet trace dir=%s n=%d id=0x%03X len=%d menu="%s" window="%s" selected=%d count=%d nonzero="%s" ascii="%s" hex="%s"'):fmt(
        tostring(direction or ''),
        trace_count + 1,
        id,
        #(data or ''),
        accessxi.escape_probe_log_text(menu_name),
        accessxi.escape_probe_log_text(window_name),
        selected,
        count,
        accessxi.escape_probe_log_text(accessxi.packet_nonzero_words(data, 1, math.min(#data, 96))),
        accessxi.escape_probe_log_text(accessxi.packet_ascii_preview(data, 120)),
        accessxi.packet_hex_limit(data, 192)));
end

function accessxi.merit_packet_entry(id)
    id = tonumber(id) or 0;
    if (id <= 0) then
        return nil;
    end
    accessxi.restore_merit_packet_cache_if_needed();
    return (accessxi.merit_packet_entries or {})[id];
end

function accessxi.merit_point_phrase(count)
    count = tonumber(count) or 0;
    if (count == 1) then
        return '1 merit point';
    end
    return ('%s merit points'):fmt(accessxi.status_number(count));
end

function accessxi.job_point_phrase(count)
    count = tonumber(count) or 0;
    if (count == 1) then
        return '1 job point';
    end
    return ('%s job points'):fmt(accessxi.status_number(count));
end

function accessxi.current_merit_mode_setting()
    local flags = tonumber(accessxi.merit_misc_flags) or 0;
    if ((tonumber(accessxi.merit_misc_tick) or 0) <= 0) then
        return '';
    end
    if (bit.band(flags, 0x04) ~= 0) then
        return 'Limit points';
    end
    if (bit.band(flags, 0x01) ~= 0) then
        return 'Experience points';
    end
    return '';
end

function accessxi.merit_option_state_parts(id)
    local entry = accessxi.merit_packet_entry(id);
    if (entry == nil) then
        return '', '', nil;
    end

    local rank = tonumber(entry.value) or 0;
    local next_cost = tonumber(entry.next_cost) or 0;
    local rank_text = ('Rank %d'):fmt(rank);
    local cost_text = '';
    if (next_cost > 0) then
        cost_text = ('Next cost %s'):fmt(accessxi.merit_point_phrase(next_cost));
    end
    return rank_text, cost_text, entry;
end

accessxi.currency_menu_data = accessxi.load_menu_module_table('currencies', T{
    packet_113_fields = T{},
    packet_113_display_names = T{},
    packet_118_fields = T{},
    packet_118_display_names = T{},
    item_labels = {},
    help_indices = {},
});
accessxi.currency_packet_113_fields = accessxi.currency_menu_data.packet_113_fields or T{};

function accessxi.currency_build_display_fields(fields, names)
    local by_name = {};
    for _, field in ipairs(fields or T{}) do
        if (field ~= nil and field.name ~= nil) then
            by_name[tostring(field.name)] = field;
        end
    end

    local ordered = T{};
    for _, name in ipairs(names or T{}) do
        local field = by_name[tostring(name)];
        if (field ~= nil) then
            ordered:append(field);
        end
    end
    return ordered;
end

accessxi.currency_packet_113_display_fields = accessxi.currency_build_display_fields(
    accessxi.currency_packet_113_fields,
    accessxi.currency_menu_data.packet_113_display_names or T{});

accessxi.currency_packet_118_fields = accessxi.currency_menu_data.packet_118_fields or T{};

function accessxi.currency_packet_118_display_names()
    return accessxi.currency_menu_data.packet_118_display_names or T{};
end

accessxi.currency_packet_118_display_fields = accessxi.currency_build_display_fields(
    accessxi.currency_packet_118_fields,
    accessxi.currency_packet_118_display_names());

function accessxi.currency_packet_value(data, field)
    data = data or '';
    local off = (tonumber(field.off) or 0) + 0x04 + 1;
    local size = tonumber(field.size) or 0;
    if (tostring(field.size or '') == 'bits') then
        local bit_offset = tonumber(field.bit_offset) or 0;
        local bits = tonumber(field.bits) or 0;
        local last_byte = off + math.floor((bit_offset + bits - 1) / 8);
        if (bits <= 0 or #data < last_byte) then
            return nil;
        end
        local value = 0;
        for i = 0, bits - 1 do
            local absolute_bit = bit_offset + i;
            local byte_value = accessxi.packet_byte(data, off + math.floor(absolute_bit / 8));
            if (bit.band(byte_value, bit.lshift(1, absolute_bit % 8)) ~= 0) then
                value = value + (2 ^ i);
            end
        end
        return value;
    end
    if (#data < off + size - 1) then
        return nil;
    end
    if (size == 1) then
        return accessxi.packet_byte(data, off);
    elseif (size == 2) then
        return accessxi.packet_u16(data, off);
    elseif (size == 4) then
        return accessxi.packet_i32(data, off);
    end
    return nil;
end

function accessxi.format_currency_number(value)
    value = tonumber(value) or 0;
    local negative = value < 0;
    value = math.abs(math.floor(value));
    local text = tostring(value);
    while true do
        local replaced;
        text, replaced = text:gsub('^(-?%d+)(%d%d%d)', '%1,%2');
        if (replaced == 0) then
            break;
        end
    end
    if (negative) then
        return '-' .. text;
    end
    return text;
end

function accessxi.currency_packet_field_label(field)
    field = field or {};
    local label = tostring(field.label or '');
    if (label ~= '') then
        return label;
    end

    local name = tostring(field.name or '');
    if (name == '') then
        return '';
    end

    local text = name:gsub('_', ' ');
    local replacements = T{
        { from = 'sandoria', to = "San d'Oria" },
        { from = 'mamool ja', to = 'M.J.T.G.' },
        { from = 'leujaoam', to = 'Leujaoam Sanctum' },
        { from = 'lebros', to = 'Lebros Cavern' },
        { from = 'periqia', to = 'Periqia' },
        { from = 'ilrusi', to = 'Ilrusi Atoll' },
        { from = 'aman', to = 'A.M.A.N.' },
        { from = 'rems', to = "Rem's" },
        { from = 'mweya', to = 'Mweya' },
        { from = 'escha', to = 'Escha' },
    };
    for _, replacement in ipairs(replacements) do
        text = text:gsub(replacement.from, replacement.to);
    end
    text = text:gsub('(%a)([%w\']*)', function(first, rest)
        if (#first == 0) then
            return '';
        end
        local word = first .. rest;
        if (word:find('%.', 1, true) ~= nil or word == "d'Oria" or word == "Rem's") then
            return word;
        end
        return first:upper() .. rest;
    end);
    return text;
end

function accessxi.currency_packet_summary(data, fields, include_zero, max_parts)
    local parts = T{};
    include_zero = include_zero == true;
    max_parts = tonumber(max_parts) or 64;
    for _, field in ipairs(fields or T{}) do
        local value = accessxi.currency_packet_value(data, field);
        if (value ~= nil and (include_zero or value ~= 0)) then
            parts:append(('%s=%d@%02X'):fmt(tostring(field.name or ''), tonumber(value) or 0, tonumber(field.off) or 0));
            if (parts:len() >= max_parts) then
                break;
            end
        end
    end
    return parts:concat(' | ');
end

function accessxi.currency_packet_named_summary(data, fields, names)
    local by_name = {};
    for _, field in ipairs(fields or T{}) do
        if (field ~= nil and field.name ~= nil) then
            by_name[tostring(field.name)] = field;
        end
    end

    local parts = T{};
    for _, name in ipairs(names or T{}) do
        local field = by_name[tostring(name)];
        local value = nil;
        if (field ~= nil) then
            value = accessxi.currency_packet_value(data, field);
        end
        parts:append(('%s=%s@%02X'):fmt(
            tostring(name),
            value ~= nil and tostring(value) or 'nil',
            field ~= nil and (tonumber(field.off) or 0) or 0));
    end
    return parts:concat(' | ');
end

function accessxi.log_currency_packet_cache(reason, force)
    local data113 = tostring(accessxi.currency_packet_113 or '');
    local data118 = tostring(accessxi.currency_packet_118 or '');
    local summary113 = accessxi.currency_packet_summary(data113, accessxi.currency_packet_113_fields, false, 80);
    local summary118 = accessxi.currency_packet_summary(data118, accessxi.currency_packet_118_fields, false, 80);
    local focus113 = accessxi.currency_packet_named_summary(data113, accessxi.currency_packet_113_fields, T{
        'fire_crystals_stored',
        'ice_crystals_stored',
        'wind_crystals_stored',
        'earth_crystals_stored',
        'lightning_crystals_stored',
        'water_crystals_stored',
        'light_crystals_stored',
        'dark_crystals_stored',
        'guild_points_fishing',
        'guild_points_woodworking',
        'guild_points_smithing',
        'guild_points_goldsmithing',
        'guild_points_weaving',
        'guild_points_leathercraft',
        'guild_points_bonecraft',
        'guild_points_alchemy',
        'guild_points_cooking',
        'deeds',
        'unity_accolades',
        'rems_tale_chapter_1_stored',
        'rems_tale_chapter_10_stored',
        'login_points',
    });
    local key = ('%s:%s:%s'):fmt(summary113, summary118, focus113);
    if (force ~= true and key == tostring(accessxi.last_currency_packet_log_key or '')) then
        return;
    end
    accessxi.last_currency_packet_log_key = key;
    log_line(('currencypacket reason="%s" p113_len=%d p113_age=%d p113="%s" p113_focus="%s" p118_len=%d p118_age=%d p118="%s"'):fmt(
        tostring(reason or ''),
        #data113,
        math.max(0, tick() - (tonumber(accessxi.currency_packet_113_tick) or 0)),
        accessxi.escape_probe_log_text(summary113),
        accessxi.escape_probe_log_text(focus113),
        #data118,
        math.max(0, tick() - (tonumber(accessxi.currency_packet_118_tick) or 0)),
        accessxi.escape_probe_log_text(summary118)));
end

function accessxi.capture_currency_packet(e)
    if (e == nil or (e.id ~= 0x0113 and e.id ~= 0x0118)) then
        return;
    end

    local data = e.data_modified or e.data or '';
    if (e.id == 0x0113) then
        accessxi.currency_packet_113 = data;
        accessxi.currency_packet_113_tick = tick();
    else
        accessxi.currency_packet_118 = data;
        accessxi.currency_packet_118_tick = tick();
    end
    accessxi.log_currency_packet_cache(('packet_in_0x%03X'):fmt(e.id), false);
end

function accessxi.conquest_region_packet_offset(region_id)
    region_id = tonumber(region_id) or -1;
    if (region_id < 4) then
        return 0;
    end

    local offset = (region_id * 4) + 11;
    if (offset == 99) then
        offset = 95;
    elseif (offset == 107) then
        offset = 99;
    end
    if (offset < 1 or offset > 0x62 + 1) then
        return 0;
    end
    return offset;
end

function accessxi.conquest_nation_name(id)
    id = tonumber(id) or -1;
    if (id == 0) then
        return 'Neutral';
    elseif (id == 1) then
        return "San d'Oria";
    elseif (id == 2) then
        return 'Bastok';
    elseif (id == 3) then
        return 'Windurst';
    elseif (id == 4) then
        return 'Beastmen';
    elseif (id == 0xFF) then
        return 'Jeuno';
    end
    return '';
end

function accessxi.conquest_strength_name(id)
    id = tonumber(id) or -1;
    if (id == 0) then
        return 'Minimal';
    elseif (id == 1) then
        return 'Minor';
    elseif (id == 2) then
        return 'Major';
    elseif (id == 3) then
        return 'Dominant';
    end
    return '';
end

function accessxi.conquest_packet_summary_for_region(region_id)
    region_id = tonumber(region_id) or -1;
    local data = tostring(accessxi.conquest_packet_data or '');
    if (#data < (0x94 + 1)) then
        return nil;
    end
    if ((tick() - (tonumber(accessxi.conquest_packet_tick) or 0)) > 30000) then
        return nil;
    end

    local offset = accessxi.conquest_region_packet_offset(region_id);
    if (offset <= 0 or #data < (offset + 3)) then
        return nil;
    end

    local region_name = accessxi.region_name_for_id(region_id);
    if (region_name == '') then
        return nil;
    end

    local packed = accessxi.packet_u32(data, offset);
    local strength_byte = accessxi.packet_byte(data, offset + 2);
    local owner_id = accessxi.packet_byte(data, offset + 3);
    local owner = accessxi.conquest_nation_name(owner_id);
    local sandoria = accessxi.packet_byte(data, 0x86 + 1);
    local bastok = accessxi.packet_byte(data, 0x87 + 1);
    local windurst = accessxi.packet_byte(data, 0x88 + 1);
    local beastmen = accessxi.packet_byte(data, 0x94 + 1);
    local computed_beastmen = 100 - sandoria - bastok - windurst;
    if (computed_beastmen >= 0 and computed_beastmen <= 100) then
        beastmen = computed_beastmen;
    end
    local days = accessxi.packet_byte(data, 0x8C + 1);
    local strengths = T{};
    local sandoria_strength = accessxi.conquest_strength_name(bit.band(strength_byte, 0x03));
    local bastok_strength = accessxi.conquest_strength_name(bit.band(bit.rshift(strength_byte, 2), 0x03));
    local windurst_strength = accessxi.conquest_strength_name(bit.band(bit.rshift(strength_byte, 4), 0x03));
    local beastmen_strength = accessxi.conquest_strength_name(bit.band(bit.rshift(strength_byte, 6), 0x03));
    if (sandoria_strength ~= '') then
        strengths:append(("San d'Oria %s"):fmt(sandoria_strength));
    end
    if (bastok_strength ~= '') then
        strengths:append(('Bastok %s'):fmt(bastok_strength));
    end
    if (windurst_strength ~= '') then
        strengths:append(('Windurst %s'):fmt(windurst_strength));
    end
    if (beastmen_strength ~= '') then
        strengths:append(('Beastmen %s'):fmt(beastmen_strength));
    end

    local parts = T{};
    parts:append(region_name);
    if (owner ~= '') then
        parts:append(('Controlled by %s'):fmt(owner));
    end
    parts:append(("Regional influence: San d'Oria %d percent, Bastok %d percent, Windurst %d percent, Beastmen %d percent"):fmt(
        sandoria,
        bastok,
        windurst,
        beastmen));
    if (#strengths > 0) then
        parts:append(('Influence strength: %s'):fmt(strengths:concat(', ')));
    end
    if (days > 0 and days < 32) then
        parts:append(('Conquest tally in %d days'):fmt(days));
    end

    return {
        region_id = region_id,
        region_name = region_name,
        owner_id = owner_id,
        owner = owner,
        packed = packed,
        sandoria = sandoria,
        bastok = bastok,
        windurst = windurst,
        beastmen = beastmen,
        days = days,
        text = parts:concat('. '),
    };
end

function accessxi.capture_conquest_packet(e)
    if (e == nil or e.id ~= 0x05E) then
        return;
    end

    local data = e.data_modified or e.data or '';
    if (#data < (0x94 + 1)) then
        log_line(('conquest packet short len=%d'):fmt(#data));
        return;
    end

    accessxi.conquest_packet_data = data;
    accessxi.conquest_packet_tick = tick();
    local region_id = tonumber(accessxi.current_region_info_region_id) or -1;
    local summary = accessxi.conquest_packet_summary_for_region(region_id);
    local key = ('%d:%s'):fmt(region_id, accessxi.packet_hex_limit(data, 32));
    if (key ~= tostring(accessxi.conquest_packet_log_key or '')) then
        accessxi.conquest_packet_log_key = key;
        if (summary ~= nil) then
            log_line(('conquest packet id=0x%03X len=%d regionId=%d region="%s" owner=%d ownerName="%s" sandoria=%d bastok=%d windurst=%d beastmen=%d days=%d packed=0x%08X hex="%s"'):fmt(
                e.id,
                #data,
                region_id,
                accessxi.escape_probe_log_text(summary.region_name),
                summary.owner_id,
                accessxi.escape_probe_log_text(summary.owner),
                summary.sandoria,
                summary.bastok,
                summary.windurst,
                summary.beastmen,
                summary.days,
                summary.packed,
                accessxi.packet_hex_limit(data, 80)));
        else
            log_line(('conquest packet id=0x%03X len=%d regionId=%d no-summary hex="%s"'):fmt(
                e.id,
                #data,
                region_id,
                accessxi.packet_hex_limit(data, 80)));
        end
    end
end

function accessxi.job_traits_packet_bits_preview(bits)
    local parts = T{};
    local traits = accessxi.load_job_traits_resource();
    if (traits == nil or tostring(bits or '') == '') then
        return '';
    end

    for id = 0, 255 do
        if (accessxi.packet_has_bit(bits, id)) then
            local info = traits[id];
            local name = info ~= nil and tostring(info.en or info.name or '') or '';
            if (name ~= '') then
                parts:append(('%d:%s'):fmt(id, name));
                if (parts:len() >= 24) then
                    break;
                end
            end
        end
    end
    return parts:concat(' | ');
end

function accessxi.job_abilities_packet_bits_preview(bits)
    local parts = T{};
    if (tostring(bits or '') == '') then
        return '';
    end

    for base_id = 0, 511 do
        if (accessxi.packet_has_bit(bits, base_id)) then
            local info = accessxi.ability_resource_info(base_id + 512);
            local name = info ~= nil and tostring(info.name or '') or '';
            if (name ~= '') then
                parts:append(('%d:%s'):fmt(base_id, accessxi.escape_probe_log_text(name)));
                if (parts:len() >= 32) then
                    break;
                end
            end
        end
    end
    return parts:concat(' | ');
end

function accessxi.save_job_abilities_packet_cache()
    local bits = tostring(accessxi.job_abilities_packet_bits or '');
    if (#bits ~= 0x40) then
        return;
    end

    local f = io.open(accessxi.job_abilities_packet_cache_path, 'w');
    if (f == nil) then
        return;
    end
    f:write(('time\t%d\n'):fmt(os.time()));
    f:write(('bits\t%s\n'):fmt(accessxi.packet_hex(bits)));
    f:close();
end

function accessxi.restore_job_abilities_packet_cache_if_needed()
    if (accessxi.job_abilities_packet_cache_loaded or #(tostring(accessxi.job_abilities_packet_bits or '')) == 0x40) then
        return;
    end
    accessxi.job_abilities_packet_cache_loaded = true;

    local f = io.open(accessxi.job_abilities_packet_cache_path, 'r');
    if (f == nil) then
        return;
    end

    local values = {};
    for line in f:lines() do
        local key, value = line:match('^([^\t]+)\t(.*)$');
        if (key ~= nil) then
            values[key] = value;
        end
    end
    f:close();

    local cached_time = tonumber(values.time) or 0;
    if (cached_time <= 0 or (os.time() - cached_time) > 86400) then
        return;
    end

    local bits = accessxi.packet_from_hex(values.bits or '');
    if (#bits ~= 0x40) then
        return;
    end

    accessxi.job_abilities_packet_bits = bits;
    accessxi.job_abilities_packet_tick = tick();
    accessxi.ability_packet_job_ability_order_cache = nil;
    log_line(('jobabilities packet cache restored bits=%s count=%d set="%s" preview="%s"'):fmt(
        accessxi.packet_hex(bits),
        accessxi.packet_bit_count(bits),
        accessxi.packet_set_bits(bits, 511),
        accessxi.escape_probe_log_text(accessxi.job_abilities_packet_bits_preview(bits))));
end

function accessxi.capture_job_abilities_packet_bits(packet_id, bits)
    bits = tostring(bits or '');
    if (#bits ~= 0x40) then
        return;
    end

    local key = accessxi.packet_hex(bits);
    accessxi.job_abilities_packet_bits = bits;
    accessxi.job_abilities_packet_tick = tick();
    accessxi.ability_known_cache = nil;
    accessxi.ability_known_cache_key = '';
    accessxi.ability_packet_job_ability_order_cache = nil;
    accessxi.save_job_abilities_packet_cache();

    if (key ~= tostring(accessxi.job_abilities_packet_key or '')) then
        accessxi.job_abilities_packet_key = key;
        log_line(('jobabilities packet id=0x%03X bits=%s count=%d set="%s" preview="%s"'):fmt(
            tonumber(packet_id) or 0,
            key,
            accessxi.packet_bit_count(bits),
            accessxi.packet_set_bits(bits, 511),
            accessxi.escape_probe_log_text(accessxi.job_abilities_packet_bits_preview(bits))));
    end
end

