function accessxi.capture_job_traits_packet(e)
    if (e == nil or e.id ~= 0x0AC) then
        return;
    end

    local data = e.data_modified or e.data or '';
    if (#data < (0xC4 + 0x20)) then
        log_line(('jobtraits packet short len=%d'):fmt(#data));
        return;
    end

    local job_bits = data:sub(0x44 + 1, 0x44 + 0x40);
    accessxi.capture_job_abilities_packet_bits(e.id, job_bits);

    local bits = data:sub(0xC4 + 1, 0xC4 + 0x20);
    if (#bits ~= 0x20) then
        return;
    end

    local key = accessxi.packet_hex(bits);
    accessxi.job_traits_packet_bits = bits;
    accessxi.job_traits_packet_tick = tick();
    accessxi.ability_known_cache = nil;
    accessxi.ability_known_cache_key = '';
    accessxi.save_job_traits_packet_cache();

    if (key ~= tostring(accessxi.job_traits_packet_key or '')) then
        accessxi.job_traits_packet_key = key;
        log_line(('jobtraits packet id=0x%03X bits=%s count=%d set="%s" preview="%s"'):fmt(
            e.id,
            key,
            accessxi.packet_bit_count(bits),
            accessxi.packet_set_bits(bits, 255),
            accessxi.escape_probe_log_text(accessxi.job_traits_packet_bits_preview(bits))));
    end
end

function accessxi.native_menu_index(offset)
    local obj = get_current_menu_object_ptr();
    if (obj == 0) then
        return 0;
    end

    local selected = read_i32(obj + (offset or 0x4C));
    selected = tonumber(selected) or 0;
    if (selected < 0 or selected > 64) then
        return 0;
    end
    return selected;
end

function accessxi.current_zone_id()
    local party = safe_call(function () return AshitaCore:GetMemoryManager():GetParty(); end, nil);
    if (party == nil) then
        return 0;
    end

    local zone = tonumber(safe_call(function () return party:GetMemberZone(0); end, 0)) or 0;
    if (zone == 0) then
        zone = tonumber(safe_call(function () return party:GetMemberZone2(0); end, 0)) or 0;
    end
    return zone;
end

function accessxi.apply_survival_guide_packet(menu_id, zone, params, source)
    menu_id = tonumber(menu_id) or 0;
    zone = tonumber(zone) or 0;
    params = tostring(params or '');
    if (menu_id ~= 8500 and menu_id ~= 8501) then
        return false;
    end

    accessxi.survival_guide_menu_id = menu_id;
    accessxi.survival_guide_zone = zone;
    accessxi.survival_guide_thrifty = menu_id == 8501;
    accessxi.survival_guide_last_packet_tick = tick();

    if (#params >= 32) then
        accessxi.survival_guide_params = params;
        accessxi.survival_guide_current_index = accessxi.packet_byte(params, 5);
        accessxi.survival_guide_tabs = accessxi.packet_u16(params, 7);
        accessxi.survival_guide_gil = accessxi.packet_u32(params, 9);
        accessxi.survival_guide_unlocks = params:sub(13, 28);
        accessxi.survival_guide_expansions = params:sub(29, 30);
        accessxi.survival_guide_unlocked_count = accessxi.packet_bit_count(params:sub(13, 28));
    end

    if (source ~= nil and source ~= '') then
        log_line(('survival guide packet restored source=%s menu=%d zone=%d current=%d gil=%d tabs=%d unlocked=%d params=%s'):fmt(
            tostring(source or ''),
            menu_id,
            zone,
            tonumber(accessxi.survival_guide_current_index) or -1,
            tonumber(accessxi.survival_guide_gil) or 0,
            tonumber(accessxi.survival_guide_tabs) or 0,
            tonumber(accessxi.survival_guide_unlocked_count) or 0,
            accessxi.packet_hex(params)));
    end
    return true;
end

function accessxi.save_survival_guide_packet_cache()
    local params = tostring(accessxi.survival_guide_params or '');
    if (#params < 32) then
        return;
    end

    local f = io.open(accessxi.survival_guide_cache_path, 'w');
    if (f == nil) then
        return;
    end

    f:write(('time\t%d\n'):fmt(os.time()));
    f:write(('menu\t%d\n'):fmt(tonumber(accessxi.survival_guide_menu_id) or 0));
    f:write(('zone\t%d\n'):fmt(tonumber(accessxi.survival_guide_zone) or 0));
    f:write(('params\t%s\n'):fmt(accessxi.packet_hex(params)));
    f:close();
end

function accessxi.restore_survival_guide_packet_cache_if_needed()
    if ((tonumber(accessxi.survival_guide_menu_id) or 0) ~= 0 or accessxi.survival_guide_cache_loaded) then
        return;
    end
    accessxi.survival_guide_cache_loaded = true;

    local f = io.open(accessxi.survival_guide_cache_path, 'r');
    if (f == nil) then
        return;
    end

    local values = {};
    for line in f:lines() do
        local key, value = line:match('^([^\t]+)\t(.*)$');
        if (key ~= nil) then
            values[key] = value;
        end
    end
    f:close();

    local cached_time = tonumber(values.time) or 0;
    if (cached_time <= 0 or (os.time() - cached_time) > 21600) then
        return;
    end

    local zone = tonumber(values.zone) or 0;
    local current_zone = accessxi.current_zone_id();
    if (zone ~= 0 and current_zone ~= 0 and zone ~= current_zone) then
        return;
    end

    local params = accessxi.packet_from_hex(values.params or '');
    if (#params < 32) then
        return;
    end

    accessxi.apply_survival_guide_packet(tonumber(values.menu) or 0, zone, params, 'cache');
end

function accessxi.capture_survival_guide_packet(e)
    if (e == nil or (e.id ~= 0x0032 and e.id ~= 0x0034)) then
        return;
    end

    local data = e.data_modified or e.data or '';
    local menu_id = 0;
    local zone = 0;
    local params = '';

    if (e.id == 0x0034) then
        params = data:sub(0x08 + 1, 0x08 + 32);
        zone = accessxi.packet_u16(data, 0x2A + 1);
        menu_id = accessxi.packet_u16(data, 0x2C + 1);
    else
        zone = accessxi.packet_u16(data, 0x0A + 1);
        menu_id = accessxi.packet_u16(data, 0x0C + 1);
    end

    if (menu_id ~= 8500 and menu_id ~= 8501) then
        return;
    end

    accessxi.apply_survival_guide_packet(menu_id, zone, params, '');
    accessxi.survival_guide_cache_loaded = true;
    accessxi.save_survival_guide_packet_cache();

    local key = ('%d:%d:%d:%d:%d:%d'):fmt(
        menu_id,
        zone,
        tonumber(accessxi.survival_guide_current_index) or -1,
        tonumber(accessxi.survival_guide_gil) or 0,
        tonumber(accessxi.survival_guide_tabs) or 0,
        tonumber(accessxi.survival_guide_unlocked_count) or 0);
    if (key ~= accessxi.survival_guide_last_packet_key) then
        accessxi.survival_guide_last_packet_key = key;
        log_line(('survival guide packet id=0x%03X menu=%d zone=%d current=%d gil=%d tabs=%d unlocked=%d thrifty=%d params=%s'):fmt(
            e.id,
            menu_id,
            zone,
            tonumber(accessxi.survival_guide_current_index) or -1,
            tonumber(accessxi.survival_guide_gil) or 0,
            tonumber(accessxi.survival_guide_tabs) or 0,
            tonumber(accessxi.survival_guide_unlocked_count) or 0,
            accessxi.survival_guide_thrifty and 1 or 0,
            accessxi.packet_hex(params)));
    end
end

function accessxi.capture_survival_guide_outgoing_packet(e)
    if (e == nil or (e.id ~= 0x005B and e.id ~= 0x005C and e.id ~= 0x0114)) then
        return;
    end
    if (not accessxi.survival_guide_recent()) then
        return;
    end

    local data = e.data_modified or e.data or '';
    local selected = 0;
    local visible = 0;
    local page = 0;
    local marker = 0;
    local child = 0;
    local child_count = 0;
    pcall(function ()
        selected, page, marker, child, child_count = accessxi.survival_guide_query_child_state();
    end);
    local remembered_label = tostring(accessxi.survival_guide_last_label or '');
    local remembered_mode = tostring(accessxi.survival_guide_last_mode or '');
    if ((tonumber(selected) or 0) <= 0) then
        selected = tonumber(accessxi.survival_guide_last_selected) or 0;
        child_count = tonumber(accessxi.survival_guide_last_child_count) or child_count or 0;
        page = tonumber(accessxi.survival_guide_last_page) or page or 0;
    end

    local key = ('%03X:%s:%d:%d:%d:%s'):fmt(
        tonumber(e.id) or 0,
        accessxi.packet_hex(data),
        tonumber(selected) or 0,
        tonumber(child_count) or 0,
        tonumber(accessxi.survival_guide_current_index) or -1,
        tostring(accessxi.survival_guide_context or '') .. ':' .. remembered_mode .. ':' .. remembered_label);
    if (key == accessxi.survival_guide_last_out_key) then
        return;
    end
    accessxi.survival_guide_last_out_key = key;

    if (e.id == 0x005B) then
        log_line(('survival guide packet_out id=0x%03X selected=%d visible=%d page=%d count=%d context=%s mode=%s label="%s" menu=%d zone=%d current=%d target=0x%08X target_index=%d option=%d unknown1=0x%04X automated=%d packet_zone=%d packet_menu=%d hex=%s'):fmt(
            e.id,
            tonumber(selected) or 0,
            tonumber(marker) or 0,
            tonumber(page) or 0,
            tonumber(child_count) or 0,
            tostring(accessxi.survival_guide_context or ''),
            remembered_mode,
            remembered_label,
            tonumber(accessxi.survival_guide_menu_id) or 0,
            tonumber(accessxi.survival_guide_zone) or 0,
            tonumber(accessxi.survival_guide_current_index) or -1,
            accessxi.packet_u32(data, 0x04 + 1),
            accessxi.packet_u16(data, 0x08 + 1),
            accessxi.packet_u16(data, 0x0A + 1),
            accessxi.packet_u16(data, 0x0C + 1),
            accessxi.packet_byte(data, 0x0E + 1),
            accessxi.packet_u16(data, 0x10 + 1),
            accessxi.packet_u16(data, 0x12 + 1),
            accessxi.packet_hex(data)));
        return;
    end

    log_line(('survival guide packet_out id=0x%03X selected=%d visible=%d page=%d count=%d context=%s mode=%s label="%s" menu=%d zone=%d current=%d hex=%s'):fmt(
        e.id,
        tonumber(selected) or 0,
        tonumber(marker) or 0,
        tonumber(page) or 0,
        tonumber(child_count) or 0,
        tostring(accessxi.survival_guide_context or ''),
        remembered_mode,
        remembered_label,
        tonumber(accessxi.survival_guide_menu_id) or 0,
        tonumber(accessxi.survival_guide_zone) or 0,
        tonumber(accessxi.survival_guide_current_index) or -1,
        accessxi.packet_hex(data)));
end

function accessxi.survival_guide_state_summary()
    if ((tonumber(accessxi.survival_guide_menu_id) or 0) == 0) then
        return 'Waiting for Survival Guide menu packet.';
    end

    local cost = accessxi.survival_guide_thrifty and 'free with Thrifty Transit' or 'normally 200 or 1000 gil, or 10 or 50 tabs depending on Rhapsodies progress';
    return ('Current guide index %d. %d registered guides. %d gil. %d tabs. Travel is %s.'):fmt(
        tonumber(accessxi.survival_guide_current_index) or -1,
        tonumber(accessxi.survival_guide_unlocked_count) or 0,
        tonumber(accessxi.survival_guide_gil) or 0,
        tonumber(accessxi.survival_guide_tabs) or 0,
        cost);
end

function accessxi.survival_guide_recent()
    local menu_id = tonumber(accessxi.survival_guide_menu_id) or 0;
    return (menu_id == 8500 or menu_id == 8501) and ((tick() - (accessxi.survival_guide_last_packet_tick or 0)) < 45000);
end

function accessxi.survival_guide_text(text)
    text = tostring(text or ''):gsub('[\t\r\n]', ' ');
    text = text:gsub('%s+', ' '):trim();
    return text;
end

accessxi.home_point_data = accessxi.load_menu_module_table('home_points', T{ points = T{} });
accessxi.home_point_points = accessxi.home_point_data.points or T{};

function accessxi.is_home_point_menu_id(menu_id)
    menu_id = tonumber(menu_id) or 0;
    return menu_id >= 8700 and menu_id <= 8704;
end

function accessxi.home_point_label_key(label)
    label = accessxi.survival_guide_text(label or ''):lower();
    label = label:gsub("'", '');
    label = label:gsub('[^%w%s]', ' ');
    label = label:gsub('%s+', ' '):trim();
    return label;
end

function accessxi.home_point_point_by_index(index)
    index = tonumber(index) or -1;
    for _, point in ipairs(accessxi.home_point_points or T{}) do
        if ((tonumber(point.index) or -2) == index) then
            return point;
        end
    end
    return nil;
end

function accessxi.home_point_points_by_zone_label(label)
    local key = accessxi.home_point_label_key(label);
    local points = T{};
    if (key == '') then
        return points;
    end

    for _, point in ipairs(accessxi.home_point_points or T{}) do
        if (accessxi.home_point_label_key(point.zone_label or '') == key) then
            points:append(point);
        end
    end

    table.sort(points, function (left, right)
        local left_number = tonumber(left ~= nil and left.number or 0) or 0;
        local right_number = tonumber(right ~= nil and right.number or 0) or 0;
        if (left_number == right_number) then
            return (tonumber(left ~= nil and left.index or 0) or 0) < (tonumber(right ~= nil and right.index or 0) or 0);
        end
        return left_number < right_number;
    end);

    return points;
end

function accessxi.home_point_remember_area_label(label)
    label = accessxi.survival_guide_text(label or '');
    if (label == '') then
        return;
    end

    local points = accessxi.home_point_points_by_zone_label(label);
    if (points:len() == 0) then
        return;
    end

    accessxi.home_point_last_area_label = label;
    accessxi.home_point_last_area_tick = tick();
end

function accessxi.home_point_origin_text()
    local point = accessxi.home_point_point_by_index(accessxi.home_point_origin_index);
    if (point == nil) then
        accessxi.home_point_origin_label = '';
        accessxi.home_point_origin_number = 0;
        return;
    end

    accessxi.home_point_origin_label = accessxi.survival_guide_text(point.zone_label or '');
    accessxi.home_point_origin_number = tonumber(point.number) or 0;
end

function accessxi.apply_home_point_packet(menu_id, zone, params, source)
    menu_id = tonumber(menu_id) or 0;
    zone = tonumber(zone) or 0;
    params = tostring(params or '');
    if (not accessxi.is_home_point_menu_id(menu_id)) then
        return false;
    end

    accessxi.home_point_menu_id = menu_id;
    accessxi.home_point_zone = zone;
    accessxi.home_point_last_packet_tick = tick();

    if (#params >= 32) then
        accessxi.home_point_params = params;
        accessxi.home_point_gil = accessxi.packet_u32(params, 0x14 + 1);
        local packed = accessxi.packet_u32(params, 0x1C + 1);
        accessxi.home_point_origin_index = bit.band(packed, 0xFF);
        accessxi.home_point_layout = bit.band(bit.rshift(packed, 18), 1);
        accessxi.home_point_origin_text();
    end

    if (source ~= nil and source ~= '') then
        log_line(('homepoint packet restored source=%s menu=%d zone=%d origin=%d origin_label="%s" origin_number=%d gil=%d layout=%d params=%s'):fmt(
            tostring(source or ''),
            menu_id,
            zone,
            tonumber(accessxi.home_point_origin_index) or -1,
            accessxi.escape_probe_log_text(accessxi.home_point_origin_label or ''),
            tonumber(accessxi.home_point_origin_number) or 0,
            tonumber(accessxi.home_point_gil) or 0,
            tonumber(accessxi.home_point_layout) or 0,
            accessxi.packet_hex(params)));
    end
    return true;
end

function accessxi.capture_home_point_packet(e)
    if (e == nil or (e.id ~= 0x0032 and e.id ~= 0x0034)) then
        return;
    end

    local data = e.data_modified or e.data or '';
    local menu_id = 0;
    local zone = 0;
    local params = '';

    if (e.id == 0x0034) then
        params = data:sub(0x08 + 1, 0x08 + 32);
        zone = accessxi.packet_u16(data, 0x2A + 1);
        menu_id = accessxi.packet_u16(data, 0x2C + 1);
    else
        zone = accessxi.packet_u16(data, 0x0A + 1);
        menu_id = accessxi.packet_u16(data, 0x0C + 1);
    end

    if (not accessxi.is_home_point_menu_id(menu_id)) then
        return;
    end

    accessxi.apply_home_point_packet(menu_id, zone, params, '');
    local key = ('%03X:%d:%d:%d:%d:%d:%s'):fmt(
        tonumber(e.id) or 0,
        menu_id,
        zone,
        tonumber(accessxi.home_point_origin_index) or -1,
        tonumber(accessxi.home_point_gil) or 0,
        tonumber(accessxi.home_point_layout) or 0,
        accessxi.packet_hex(params));
    if (key ~= tostring(accessxi.home_point_last_packet_key or '')) then
        accessxi.home_point_last_packet_key = key;
        log_line(('homepoint packet id=0x%03X menu=%d zone=%d origin=%d origin_label="%s" origin_number=%d gil=%d layout=%d params=%s'):fmt(
            e.id,
            menu_id,
            zone,
            tonumber(accessxi.home_point_origin_index) or -1,
            accessxi.escape_probe_log_text(accessxi.home_point_origin_label or ''),
            tonumber(accessxi.home_point_origin_number) or 0,
            tonumber(accessxi.home_point_gil) or 0,
            tonumber(accessxi.home_point_layout) or 0,
            accessxi.packet_hex(params)));
    end
end

function accessxi.capture_home_point_outgoing_packet(e)
    if (e == nil or (e.id ~= 0x005B and e.id ~= 0x005C and e.id ~= 0x0114)) then
        return;
    end
    if (not accessxi.is_home_point_menu_id(accessxi.home_point_menu_id)
        or ((tick() - (tonumber(accessxi.home_point_last_packet_tick) or 0)) > 45000)) then
        return;
    end

    local data = e.data_modified or e.data or '';
    local key = ('%03X:%s'):fmt(tonumber(e.id) or 0, accessxi.packet_hex(data));
    if (key == tostring(accessxi.home_point_last_out_key or '')) then
        return;
    end
    accessxi.home_point_last_out_key = key;

    if (e.id == 0x005B) then
        log_line(('homepoint packet_out id=0x%03X menu=%d zone=%d origin=%d origin_label="%s" target=0x%08X target_index=%d option=%d unknown1=0x%04X automated=%d packet_zone=%d packet_menu=%d hex=%s'):fmt(
            e.id,
            tonumber(accessxi.home_point_menu_id) or 0,
            tonumber(accessxi.home_point_zone) or 0,
            tonumber(accessxi.home_point_origin_index) or -1,
            accessxi.escape_probe_log_text(accessxi.home_point_origin_label or ''),
            accessxi.packet_u32(data, 0x04 + 1),
            accessxi.packet_u16(data, 0x08 + 1),
            accessxi.packet_u16(data, 0x0A + 1),
            accessxi.packet_u16(data, 0x0C + 1),
            accessxi.packet_byte(data, 0x0E + 1),
            accessxi.packet_u16(data, 0x10 + 1),
            accessxi.packet_u16(data, 0x12 + 1),
            accessxi.packet_hex(data)));
        return;
    end

    log_line(('homepoint packet_out id=0x%03X menu=%d zone=%d origin=%d origin_label="%s" hex=%s'):fmt(
        e.id,
        tonumber(accessxi.home_point_menu_id) or 0,
        tonumber(accessxi.home_point_zone) or 0,
        tonumber(accessxi.home_point_origin_index) or -1,
        accessxi.escape_probe_log_text(accessxi.home_point_origin_label or ''),
        accessxi.packet_hex(data)));
end

function accessxi.home_point_destination_row_label(selected)
    selected = tonumber(selected) or 0;
    if (selected < 2) then
        return '';
    end

    local area_label = tostring(accessxi.home_point_last_area_label or '');
    if (area_label ~= '' and (tick() - (tonumber(accessxi.home_point_last_area_tick) or 0)) > 120000) then
        area_label = '';
    end

    local hp_number = selected - 1;
    local point = nil;
    if (area_label ~= '') then
        local points = accessxi.home_point_points_by_zone_label(area_label);
        point = points[hp_number];
        if (point ~= nil) then
            hp_number = tonumber(point.number) or hp_number;
        end
    end

    local label = ('Home Point #%d'):fmt(hp_number);
    if (point ~= nil and (tonumber(point.index) or -2) == (tonumber(accessxi.home_point_origin_index) or -1)) then
        label = label .. ' (M)';
    end
    return label;
end

function accessxi.home_point_label_is_destination_row(label)
    label = accessxi.survival_guide_text(label or '');
    if (label:eq('Home Point', true)) then
        return true;
    end
    return label:match('^Home Point%s+') ~= nil;
end

accessxi.survival_guide_data = accessxi.load_menu_module_table('survival_guide', T{
    destinations = T{},
    region_groups = T{},
    category_content = T{},
    visible_destination_indices = T{},
});
accessxi.survival_guide_destinations = accessxi.survival_guide_data.destinations;
accessxi.survival_guide_region_groups = accessxi.survival_guide_data.region_groups;

function accessxi.survival_guide_category_content(index)
    return accessxi.survival_guide_data.category_content[tonumber(index) or 0];
end

function accessxi.survival_guide_visible_destination_indices(category)
    return accessxi.survival_guide_data.visible_destination_indices[tonumber(category) or 0];
end

function accessxi.survival_guide_category_destination_allowed(category, point)
    category = tonumber(category) or 0;
    if (point == nil) then
        return false;
    end

    local visible = accessxi.survival_guide_visible_destination_indices(category);
    if (visible == nil) then
        return true;
    end

    local point_index = tonumber(point.index) or -1;
    for _, index in ipairs(visible) do
        if ((tonumber(index) or -2) == point_index) then
            return true;
        end
    end

    return false;
end

function accessxi.survival_guide_region_label(region)
    local region_id = tonumber(region ~= nil and region.region_id or -1) or -1;
    if (region_id >= 0) then
        local label = safe_call(function ()
            return AshitaCore:GetResourceManager():GetString('regions', region_id) or '';
        end, '');
        label = accessxi.survival_guide_text(label);
        if (label ~= '') then
            return label;
        end
    end
    return accessxi.survival_guide_text(region ~= nil and region.label or '');
end

function accessxi.survival_guide_region_index_for_native_label(label)
    local key = accessxi.survival_guide_label_key(label);
    if (key == '') then
        return 0;
    end

    for index, region in ipairs(accessxi.survival_guide_region_groups) do
        if (accessxi.survival_guide_label_key(accessxi.survival_guide_region_label(region)) == key) then
            return index;
        end
    end

    return 0;
end

function accessxi.survival_guide_destination_by_index(index)
    index = tonumber(index) or -1;
    for _, point in ipairs(accessxi.survival_guide_destinations) do
        if ((tonumber(point.index) or -2) == index) then
            return point;
        end
    end
    return nil;
end

function accessxi.survival_guide_zone_label(point)
    local zone = tonumber(point ~= nil and point.zone or 0) or 0;
    local label = safe_call(function ()
        return AshitaCore:GetResourceManager():GetString('zones.names', zone) or '';
    end, '');
    label = accessxi.survival_guide_text(label);
    if (label ~= '') then
        return label;
    end
    return ('Zone %d'):fmt(zone);
end

function accessxi.survival_guide_entry_from_point(point)
    if (point == nil) then
        return nil;
    end

    return T{
        label = accessxi.survival_guide_zone_label(point),
        index = point.index,
        unlock_bit = point.unlock_bit,
        zone = point.zone,
        content = point.content,
    };
end

function accessxi.survival_guide_destination_label_by_index(index)
    local point = accessxi.survival_guide_destination_by_index(index);
    if (point == nil) then
        return '';
    end

    return accessxi.survival_guide_zone_label(point);
end

function accessxi.survival_guide_clean_native_destination_label(label, expected_count, selected)
    label = accessxi.survival_guide_text(label or '');
    expected_count = tonumber(expected_count) or 0;
    selected = tonumber(selected) or 0;
    if (label == ''
        or expected_count == 15
        or expected_count == 27) then
        return label;
    end

    local normalized = label:lower();
    normalized = normalized:gsub("'", '');
    normalized = normalized:gsub('[^%w%s]', ' ');
    normalized = normalized:gsub('%s+', ' '):trim();

    if (normalized:match('^nowhere') ~= nil) then
        if (selected == 1) then
            return 'Nowhere for now';
        end
        return label;
    end
    if (normalized:match('^next page') ~= nil) then
        if (selected >= math.max(expected_count - 2, 1)) then
            return 'Next Page';
        end
        return label;
    end
    if (normalized:match('^previous page') ~= nil) then
        return 'Previous Page';
    end

    local zone_patterns = T{
        { 'northern san oria', 0 },
        { 'northern san doria', 0 },
        { 'bastok mines', 1 },
        { 'bastok', 1 },
        { 'port windurst', 2 },
        { 'ru lude gardens', 3 },
        { 'rulude gardens', 3 },
        { 'tavnazian safehold', 4 },
        { 'carpenters landing', 15 },
        { 'carpenters', 15 },
        { 'bibiki bay', 31 },
        { 'oldton movalpolos', 65 },
        { 'newton movalpolos', 65 },
        { 'lufaise meadows', 66 },
        { 'misareaux coast', 67 },
        { 'phomiuna aqueducts', 68 },
        { 'phomiuna aquaducts', 68 },
        { 'sacrarium', 69 },
        { 'west ronfaure', 6 },
        { 'east ronfaure', 7 },
        { 'ghelsba', 7 },
        { 'bostaunieux oubliette', 8 },
        { 'king ranperre tomb', 9 },
        { 'king ranperres tomb', 9 },
        { 'la theine plateau', 10 },
        { 'valkurm dunes', 11 },
        { 'konschtat', 12 },
        { 'ordelles caves', 13 },
        { 'ordelle caves', 13 },
        { 'ordelle', 13 },
        { 'gusgen mines', 14 },
        { 'jugner forest', 16 },
        { 'batallia downs', 17 },
        { 'davoi', 18 },
        { 'eldieme necropolis', 19 },
        { 'north gustaberg', 20 },
        { 'zeruhn mines', 21 },
        { 'dangruf wadi', 23 },
        { 'pashhow marshlands', 24 },
        { 'rolanberry fields', 25 },
        { 'crawlers nest', 26 },
        { 'beadeaux', 27 },
        { 'west sarutabaruta', 28 },
        { 'toraimarai canal', 29 },
        { 'inner horutoto', 30 },
        { 'tahrongi canyon', 32 },
        { 'buburimu peninsula', 33 },
        { 'maze of shakhrami', 34 },
        { 'meriphataud mountains', 36 },
        { 'sauromugue champaign', 37 },
        { 'castle oztroja', 38 },
        { 'garlaige citadel', 39 },
        { 'garlaige', 39 },
        { 'ranguemont pass', 41 },
        { 'xarcabard', 42 },
        { 'castle zvahl baileys', 43 },
        { 'castle zvahl', 43 },
        { 'qufim', 44 },
        { 'behemoth dominion', 45 },
        { 'lower delkfutt tower', 46 },
        { 'beaucedine glacier', 40 },
        { 'the eldieme necropolis', 18 },
    };

    for _, rule in ipairs(zone_patterns) do
        local needle = tostring(rule[1] or '');
        if (needle ~= '' and normalized:find(needle, 1, true) ~= nil) then
            local resource_label = accessxi.survival_guide_destination_label_by_index(rule[2]);
            if (resource_label ~= '') then
                return resource_label;
            end
        end
    end

    return label;
end

function accessxi.survival_guide_destination_available(point)
    if (point == nil) then
        return false;
    end

    local unlocks = accessxi.survival_guide_unlocks or '';
    if (#unlocks == 0) then
        return true;
    end

    return accessxi.packet_has_bit(unlocks, point.unlock_bit);
end

function accessxi.survival_guide_area_control_entries()
    return T{
        T{ label = 'Nowhere for now', control = 'cancel' },
        T{ label = 'Select from amongst favorites', control = 'favorites' },
    };
end

function accessxi.survival_guide_destination_page_entries(destinations, trailing_control)
    local visible = T{ T{ label = 'Nowhere for now', control = 'cancel' } };
    for _, entry in ipairs(destinations or T{}) do
        visible:append(entry);
    end
    if (trailing_control ~= nil and tostring(trailing_control or '') ~= '') then
        visible:append(T{ label = tostring(trailing_control), control = tostring(trailing_control):lower() });
    end
    return visible;
end

function accessxi.survival_guide_content_destination_entries(category)
    local content = accessxi.survival_guide_category_content(category);
    if (content == nil) then
        return T{}, -1;
    end

    local all = T{};
    local unlocked = T{};
    local visible = accessxi.survival_guide_visible_destination_indices(category);
    for _, point in ipairs(accessxi.survival_guide_destinations) do
        local category_point = false;
        if (visible ~= nil) then
            category_point = accessxi.survival_guide_category_destination_allowed(category, point);
        else
            category_point = ((tonumber(point.content) or -1) == content);
        end
        if (category_point) then
            local entry = accessxi.survival_guide_entry_from_point(point);
            all:append(entry);
            if (accessxi.survival_guide_destination_available(point)) then
                unlocked:append(entry);
            end
        end
    end

    if ((accessxi.survival_guide_unlocks or '') ~= '') then
        return unlocked, content;
    end
    return all, content;
end

function accessxi.survival_guide_label_key(label)
    label = accessxi.survival_guide_text(label or ''):lower();
    label = label:gsub("'", '');
    label = label:gsub('[^%w%s]', ' ');
    label = label:gsub('%s+', ' '):trim();
    return label;
end

function accessxi.survival_guide_destination_index_by_label(destinations, label)
    local key = accessxi.survival_guide_label_key(label);
    if (key == '') then
        return 0;
    end

    for i, destination in ipairs(destinations or T{}) do
        if (accessxi.survival_guide_label_key(destination ~= nil and destination.label or '') == key) then
            return i;
        end
    end

    return 0;
end

function accessxi.survival_guide_content_label_is_known(category, label)
    local content = accessxi.survival_guide_category_content(category);
    if (content == nil) then
        return false;
    end

    local key = accessxi.survival_guide_label_key(label);
    if (key == '') then
        return false;
    end

    local visible = accessxi.survival_guide_visible_destination_indices(category);
    for _, point in ipairs(accessxi.survival_guide_destinations) do
        local category_point = false;
        if (visible ~= nil) then
            category_point = accessxi.survival_guide_category_destination_allowed(category, point);
        else
            category_point = ((tonumber(point.content) or -1) == content);
        end
        if (category_point) then
            local resource_label = accessxi.survival_guide_zone_label(point);
            if (accessxi.survival_guide_label_key(resource_label) == key) then
                return true;
            end
        end
    end

    return false;
end

function accessxi.survival_guide_update_destination_start_from_native(category, child, child_count, context)
    category = tonumber(category) or 0;
    child_count = tonumber(child_count) or 0;
    if (category <= 0 or child_count <= 0) then
        return;
    end

    local destinations = nil;
    destinations = accessxi.survival_guide_content_destination_entries(category);
    if (destinations == nil or destinations:len() == 0) then
        return;
    end

    local items = nil;
    items = accessxi.native_query_items_for_child(child, child_count, context);
    if (items == nil or items:len() == 0) then
        return;
    end

    local votes = {};
    local best_start = 0;
    local best_votes = 0;
    local max_row = math.min(child_count, items:len(), 21);
    for row = 2, max_row do
        local item = items[row];
        local label = tostring(item ~= nil and item.label or '');
        label = accessxi.survival_guide_clean_native_destination_label(label, child_count, row);
        local key = accessxi.survival_guide_label_key(label);
        if (key ~= ''
            and key ~= 'nowhere for now'
            and key ~= 'next page'
            and key ~= 'previous page'
            and key ~= 'previous') then
            local destination_index = accessxi.survival_guide_destination_index_by_label(destinations, label);
            if (destination_index > 0) then
                local start_index = destination_index - (row - 2);
                if (start_index > 0) then
                    votes[start_index] = (votes[start_index] or 0) + 1;
                    if (votes[start_index] > best_votes) then
                        best_votes = votes[start_index];
                        best_start = start_index;
                    end
                end
            end
        end
    end

    if (best_start > 0 and best_votes >= 2) then
        accessxi.survival_guide_destination_start_index = best_start;
        local first_page_slots = 19;
        local later_page_slots = 18;
        if (best_start <= 1) then
            accessxi.survival_guide_destination_page_index = 0;
        elseif (best_start <= first_page_slots + 1) then
            accessxi.survival_guide_destination_page_index = 1;
        else
            accessxi.survival_guide_destination_page_index = math.floor((best_start - first_page_slots - 1) / later_page_slots) + 1;
        end
        local line = ('survival guide destination start category=%d count=%d start=%d page=%d votes=%d'):fmt(
            category,
            child_count,
            best_start,
            tonumber(accessxi.survival_guide_destination_page_index) or 0,
            best_votes);
        if (line ~= accessxi.survival_guide_last_destination_start_log) then
            accessxi.survival_guide_last_destination_start_log = line;
            log_line(line);
        end
    end
end

function accessxi.survival_guide_destination_page_label(category, selected, child_count)
    selected = tonumber(selected) or 0;
    child_count = math.min(math.max(tonumber(child_count) or 0, 0), 21);
    if (selected <= 0 or child_count <= 0) then
        return nil, 'invalid', -1;
    end

    local destinations, content = accessxi.survival_guide_content_destination_entries(category);
    if (destinations == nil or destinations:len() == 0) then
        return nil, 'content-empty', content;
    end

    local first_page_slots = 19;
    local later_page_slots = 18;
    local start_index = math.max(tonumber(accessxi.survival_guide_destination_start_index) or 1, 1);
    if (start_index > destinations:len()) then
        start_index = 1;
        accessxi.survival_guide_destination_start_index = 1;
    end

    local page_index = 0;
    if (start_index > 1) then
        if (start_index <= first_page_slots + 1) then
            page_index = 1;
        else
            page_index = math.floor((start_index - first_page_slots - 1) / later_page_slots) + 1;
        end
    end

    if (selected == 1) then
        return 'Nowhere for now', ('content-page-%d-control'):fmt(page_index), content;
    end

    local has_previous = start_index > 1;
    local available_slots = math.max(child_count - 1, 0);
    if (has_previous) then
        available_slots = math.max(available_slots - 1, 0);
    end

    local remaining = math.max(destinations:len() - start_index + 1, 0);
    local has_next = remaining > available_slots;
    if (has_next) then
        available_slots = math.max(available_slots - 1, 0);
    end

    if (has_next and selected == child_count) then
        return 'Next Page', ('content-page-%d-control'):fmt(page_index), content;
    end
    if (has_previous and selected == child_count) then
        return 'Previous Page', ('content-page-%d-control'):fmt(page_index), content;
    end

    local destination_index = start_index + selected - 2;
    local destination = destinations[destination_index];
    if (destination ~= nil and tostring(destination.label or '') ~= '') then
        return destination.label, ('content-page-%d'):fmt(page_index), content;
    end

    return nil, ('content-page-%d-missing'):fmt(page_index), content;
end

function accessxi.survival_guide_remember_selection(selected, child_count, page, label, mode)
    accessxi.survival_guide_last_selected = tonumber(selected) or 0;
    accessxi.survival_guide_last_child_count = tonumber(child_count) or 0;
    accessxi.survival_guide_last_page = tonumber(page) or 0;
    accessxi.survival_guide_last_label = tostring(label or '');
    accessxi.survival_guide_last_mode = tostring(mode or '');
end

function accessxi.survival_guide_destination_list(category, expected_count)
    local content = accessxi.survival_guide_category_content(category);
    if (content == nil) then
        return T{}, 'none', -1;
    end

    local visible = accessxi.survival_guide_visible_destination_indices(category);
    local visible_lookup = T{};
    if (visible ~= nil) then
        for _, index in ipairs(visible) do
            visible_lookup[tonumber(index) or -1] = true;
        end
    end

    local all = T{};
    local unlocked = T{};
    for _, point in ipairs(accessxi.survival_guide_destinations) do
        local point_index = tonumber(point.index) or -1;
        local category_point = false;
        if (visible ~= nil) then
            category_point = (visible_lookup[point_index] == true);
        else
            category_point = ((tonumber(point.content) or -1) == content);
        end
        if (category_point) then
            local entry = accessxi.survival_guide_entry_from_point(point);
            all:append(entry);
            if (accessxi.survival_guide_destination_available(point)) then
                unlocked:append(entry);
            end
        end
    end

    expected_count = tonumber(expected_count) or 0;
    if (expected_count > 0 and (unlocked:len() + 2) == expected_count) then
        return accessxi.survival_guide_destination_page_entries(unlocked, 'Next Page'), 'visible-controls-unlocked-native', content;
    end
    if (expected_count > 0 and (all:len() + 2) == expected_count) then
        return accessxi.survival_guide_destination_page_entries(all, 'Next Page'), 'visible-controls-all-native', content;
    end
    if (expected_count > 0 and tonumber(category) == 3 and all:len() == expected_count) then
        return accessxi.survival_guide_destination_prefix_page_entries(all, expected_count, 'Next Page'), 'visible-controls-original-prefix-native', content;
    end
    if (expected_count > 0 and unlocked:len() == expected_count) then
        return unlocked, 'visible-unlocked-native', content;
    end
    if (expected_count > 0 and all:len() == expected_count) then
        return all, 'visible-all-native', content;
    end
    if (expected_count > 0 and unlocked:len() ~= expected_count) then
        return T{}, ('visible-ambiguous-unlocked-%d-native-%d'):fmt(unlocked:len(), expected_count), content;
    end
    return unlocked, 'visible-unlocked', content;
end

function accessxi.survival_guide_region_list(expected_count)
    local all = accessxi.survival_guide_area_control_entries();
    local unlocked = accessxi.survival_guide_area_control_entries();
    for index, region in ipairs(accessxi.survival_guide_region_groups) do
        local has_unlocked = false;
        for _, point_index in ipairs(region.indices) do
            local point = accessxi.survival_guide_destination_by_index(point_index);
            if (accessxi.survival_guide_destination_available(point)) then
                has_unlocked = true;
                break;
            end
        end
        local entry = T{ label = accessxi.survival_guide_region_label(region), index = index, indices = region.indices };
        all:append(entry);
        if (has_unlocked) then
            unlocked:append(entry);
        end
    end

    expected_count = tonumber(expected_count) or 0;
    if (expected_count > 0 and unlocked:len() == expected_count) then
        return unlocked, 'region-unlocked';
    end
    if (expected_count > 0 and all:len() == expected_count) then
        return all, 'region-all-native';
    end
    if (expected_count > 0 and all:len() > expected_count) then
        local visible = T{};
        for i = 1, expected_count do
            visible:append(all[i]);
        end
        return visible, ('region-visible-prefix-%d-unlocked-%d'):fmt(expected_count, unlocked:len());
    end
    return T{}, ('region-ambiguous-unlocked-%d-native-%d'):fmt(unlocked:len(), expected_count);
end

function accessxi.survival_guide_region_destination_list(region_index, expected_count)
    local region = accessxi.survival_guide_region_groups[tonumber(region_index) or 0];
    if (region == nil) then
        return T{}, 'region-none';
    end

    local all = T{};
    local unlocked = T{};
    for _, point_index in ipairs(region.indices) do
        local point = accessxi.survival_guide_destination_by_index(point_index);
        local entry = accessxi.survival_guide_entry_from_point(point);
        if (entry ~= nil) then
            all:append(entry);
            if (accessxi.survival_guide_destination_available(point)) then
                unlocked:append(entry);
            end
        end
    end

    expected_count = tonumber(expected_count) or 0;
    if (expected_count > 0 and (unlocked:len() + 2) == expected_count) then
        local controls = accessxi.survival_guide_area_control_entries();
        local visible = T{};
        for _, entry in ipairs(controls) do
            visible:append(entry);
        end
        for _, entry in ipairs(unlocked) do
            visible:append(entry);
        end
        return visible, 'region-dest-controls-unlocked-native';
    end
    if (expected_count > 0 and (all:len() + 2) == expected_count) then
        local controls = accessxi.survival_guide_area_control_entries();
        local visible = T{};
        for _, entry in ipairs(controls) do
            visible:append(entry);
        end
        for _, entry in ipairs(all) do
            visible:append(entry);
        end
        return visible, 'region-dest-controls-all-native';
    end
    if (expected_count > 0 and unlocked:len() == expected_count) then
        return unlocked, 'region-dest-unlocked-native';
    end
    if (expected_count > 0 and all:len() == expected_count) then
        return all, 'region-dest-all-native';
    end
    if (expected_count > 0 and unlocked:len() ~= expected_count) then
        return T{}, ('region-dest-ambiguous-unlocked-%d-native-%d'):fmt(unlocked:len(), expected_count);
    end
    return unlocked, 'region-dest-unlocked';
end

function accessxi.survival_guide_teleport_count()
    return 8;
end

function accessxi.survival_guide_query_child_state_for_obj(obj)
    obj = tonumber(obj) or 0;
    if (obj == 0) then
        return 0, 0, 0, 0;
    end

    local child = read_u32(obj + 0x0C) or 0;
    if (not accessxi.is_probe_pointer(child)) then
        return 0, 0, 0, child;
    end

    local raw = read_u32(child + 0x30) or 0;
    local count = tonumber(read_i32(child + 0x24)) or 0;
    local count2 = tonumber(read_i32(child + 0x28)) or 0;
    if (count2 > count) then
        count = count2;
    end
    if (count < 0 or count > 256) then
        count = 0;
    end

    local zero_based = bit.band(raw, 0xFFFF);
    local page = bit.rshift(raw, 16);
    if (zero_based < 0 or zero_based > 255 or page > 255) then
        return 0, page, raw, child, count;
    end

    return zero_based + 1, page, raw, child, count;
end

function accessxi.survival_guide_query_child_state()
    return accessxi.survival_guide_query_child_state_for_obj(get_current_menu_object_ptr());
end

function accessxi.native_query_label_fragment_penalty(label)
    label = accessxi.survival_guide_text(label or '');
    if (label == '') then
        return 0;
    end

    local penalty = 0;
    if (label:match(':%s*/') ~= nil) then
        penalty = penalty + 120;
    end
    if (#label <= 6 and label:find('%s') == nil and label:match('^%a+$') ~= nil and label:match('%l%u') ~= nil) then
        penalty = penalty + 100;
    end

    return penalty;
end

function accessxi.native_query_label_looks_real(label)
    label = accessxi.survival_guide_text(label or '');
    if (label == '' or #label > 80) then
        return false;
    end

    for i = 1, #label do
        local byte_value = label:byte(i) or 0;
        if (byte_value < 0x20 or byte_value > 0x7E) then
            return false;
        end
    end
    for _, token in ipairs(T{ '_', '{', '}', '[', ']', '|', '<', '>', '@', '\\' }) do
        if (label:find(token, 1, true) ~= nil) then
            return false;
        end
    end
    if (accessxi.native_query_label_fragment_penalty(label) >= 90) then
        return false;
    end

    local letters = 0;
    for _ in label:gmatch('%a') do
        letters = letters + 1;
    end
    if (letters < 2) then
        return false;
    end

    return true;
end

function accessxi.native_query_candidate_label_from_text(text, context)
    local label = accessxi.survival_guide_native_label_for_speech(text or '', context or '');
    if (label ~= '' and accessxi.native_query_label_looks_real(label)) then
        return accessxi.native_query_normalize_phrase(label, context);
    end

    label = accessxi.survival_guide_native_visible_label_text(text or '');
    if (label ~= ''
        and accessxi.native_query_label_looks_real(label)
        and not accessxi.survival_guide_native_label_is_polluted(label)) then
        return accessxi.native_query_normalize_phrase(label, context);
    end

    return '';
end

function accessxi.native_query_visible_text_from_ptr(ptr)
    ptr = tonumber(ptr) or 0;
    if (not accessxi.is_probe_pointer(ptr) or accessxi.survival_guide_text == nil) then
        return '';
    end

    local count = tonumber(read_u8(ptr + 0x106));
    if (count == nil or count < 1 or count > 63) then
        return '';
    end

    local units = T{};
    for index = 0, count - 1 do
        local lo = read_u8(ptr + 0x04 + (index * 2));
        local hi = read_u8(ptr + 0x04 + (index * 2) + 1);
        if (lo == nil or hi == nil) then
            return '';
        end
        units:append(T{ lo = lo, hi = hi });
    end

    local raw = T{};
    local consumed_units = 0;
    for _, unit in ipairs(units) do
        local lo = unit.lo;
        local hi = unit.hi;
        local decoded = nil;
        consumed_units = consumed_units + 1;
        if (hi == 0 and lo == 0x9C) then
            raw:append('claimed');
        elseif (hi == 0 and lo >= 0 and lo <= 0x1F) then
            decoded = lo + 0x20;
        elseif (hi == 0 and lo >= 0x21 and lo <= 0x3A) then
            decoded = bit.bxor(lo, 0x60);
        elseif (hi == 0 and lo >= 0x20 and lo <= 0x7E) then
            decoded = lo;
        elseif (hi == 0xFE and (lo == 0xFD or lo == 0xFE or lo == 0xFF)) then
            -- Native framing/style unit: counted, but not visible.
        else
            return '';
        end

        if (decoded ~= nil) then
            raw:append(string.char(decoded));
        end
    end

    if (consumed_units ~= count) then
        return '';
    end

    local text = accessxi.survival_guide_text(raw:concat(''));
    if (text == '') then
        return '';
    end
    return text;
end

function accessxi.native_query_text_object_is_framed(ptr)
    ptr = tonumber(ptr) or 0;
    if (not accessxi.is_probe_pointer(ptr)) then
        return false;
    end

    local native_style = read_u8(ptr + 0x104);
    local native_reserved = read_u8(ptr + 0x105);
    local native_frame = read_u8(ptr + 0x107);
    return native_style ~= nil
        and native_style ~= 0
        and native_reserved == 0
        and native_frame == 1;
end

function accessxi.native_query_phrase_from_ptr(ptr, context)
    local visible = accessxi.native_query_visible_text_from_ptr(ptr);
    if (visible == '') then
        return '';
    end

    local parts = T{};
    for word in visible:gmatch('%S+') do
        if (word ~= '.' and word ~= '/') then
            local roman = word:match('^[IVXLCDM]+[%p]?$') ~= nil;
            if (not roman and word:upper() == word and #word > 1) then
                word = word:sub(1, 1) .. word:sub(2):lower();
            end
            parts:append(word);
        end
    end

    if (parts:len() == 0) then
        return '';
    end

    local phrase = parts:concat(' ');
    phrase = phrase:gsub('^%(claimed%)%s*', 'Claimed. ');
    phrase = phrase:gsub('^Claimed%. Copper A%.m%.a%.n%. Voucher X7: 10%.$',
        'Claimed. Copper A.M.A.N. voucher X7: 10.');
    phrase = phrase:gsub('^Claimed%. Themis Orb: 40%.$', 'Claimed. Themis orb: 40.');
    phrase = phrase:gsub("^Tu'lia%.$", "Tu'Lia.");
    phrase = phrase:gsub('^Never Mind%.$', 'Never mind.');
    phrase = phrase:gsub('^On Second Thought, None%.$', 'On second thought, none.');
    phrase = phrase:gsub('^N Second Thought None$', 'On second thought, none');
    phrase = phrase:gsub('^On Second Thought None$', 'On second thought, none');
    phrase = phrase:gsub('^Select From Amongst Favorites$', 'Select from amongst favorites');
    phrase = phrase:gsub('^O Nfaure$', 'Ronfaure');
    phrase = phrase:gsub('^Nfaure$', 'Ronfaure');
    phrase = phrase:gsub('^Oria$', "San d'Oria");
    phrase = phrase:gsub('^San Oria$', "San d'Oria");
    phrase = phrase:gsub('^Jeuno From Amongst Favorites$', 'Jeuno');
    phrase = phrase:gsub('^Tavnazia Tion Assistance$', 'Tavnazia');
    phrase = phrase:gsub('^Adoulin Isles Assistance ww$', 'Adoulin Isles');
    phrase = phrase:gsub('^Ronfaure Ught None$', 'Ronfaure');
    phrase = phrase:gsub('^Zulkheim Ta ww$', 'Zulkheim');
    phrase = phrase:gsub('^Norvallen ww$', 'Norvallen');
    phrase = phrase:gsub('^Sarutabaruta Ongst Favorites$', 'Sarutabaruta');
    phrase = phrase:gsub('^Kolshushu Es$', 'Kolshushu');
    phrase = phrase:gsub('^Aragoneu On Assistance$', 'Aragoneu');
    phrase = phrase:gsub('^Elshimo Low Assistance$', 'Elshimo Lowlands');
    phrase = phrase:gsub('^Elshimo Up Ries None ww$', 'Elshimo Uplands');
    phrase = phrase:gsub('^Tu Lia Di$', "Tu'Lia");
    phrase = phrase:gsub('^On Second Thought None ww$', 'On second thought, none');
    phrase = phrase:gsub('^Arrapago Is Assistance$', 'Arrapago Islands');
    phrase = phrase:gsub('^Ronfaure Front Gst Favorites$', 'Ronfaure Front');
    phrase = phrase:gsub('^Norvallen Front St Favorites$', 'Norvallen Front');
    phrase = phrase:gsub('^Gustaberg Front None$', 'Gustaberg Front');
    phrase = phrase:gsub('^Derfland Front None$', 'Derfland Front');
    phrase = phrase:gsub('^Fauregandi Front None$', 'Fauregandi Front');
    phrase = phrase:gsub('^Valdeaunia Front ww$', 'Valdeaunia Front');
    phrase = phrase:gsub('^Other Mysteries$', 'Other Mysteries');
    phrase = phrase:gsub('^Teleportation Assistance$', 'Teleportation Assistance');
    phrase = accessxi.survival_guide_text(phrase);

    if (phrase:eq('On second thought, none', true) and accessxi.native_query_label_looks_real(phrase)) then
        return phrase;
    end
    if (accessxi.native_query_text_object_is_framed(ptr)
        and (phrase:eq('No.', true) or phrase:eq('No', true))
        and accessxi.native_query_label_looks_real(phrase)) then
        return phrase;
    end

    if (phrase ~= '' and accessxi.native_query_label_looks_real(phrase) and not accessxi.survival_guide_native_label_is_polluted(phrase)) then
        return phrase;
    end

    return '';
end

function accessxi.home_point_query_normalize_phrase(phrase)
    phrase = accessxi.survival_guide_text(phrase or '');
    if (phrase == '') then
        return '';
    end

    local exact = T{
        ['Travel To Another Home Point'] = 'Travel to another home point',
        ['Set This As Your Home Point'] = 'Set this as your home point',
        ['Other Settings Never Mind'] = 'Other Settings',
        ['Other Settings Oddess Area'] = 'Other Settings',
        ['On Second Thought Never Mind'] = 'On second thought, never mind',
        ['On Second Thought None hV'] = 'On second thought, none',
        ['On Second Thought None'] = 'On second thought, none',
        ['Select From Favorites'] = 'Select from favorites',
        ['Select By Region Hia Area'] = 'Select by Region',
        ['Select By Expansion Point'] = 'Select by Expansion',
        ['Current Region Home Point'] = 'Current region',
