function accessxi.native_query_normalize_phrase(phrase, context)
    phrase = accessxi.survival_guide_text(phrase or '');
    if (phrase == '') then
        return '';
    end

    context = tostring(context or '');
    if (context:eq('homepoint', true)) then
        return accessxi.home_point_query_normalize_phrase(phrase);
    end
    if (context:eq('plain', true) or context:eq('main-menu', true) or context:eq('config-visible', true)) then
        return accessxi.plain_native_menu_label(phrase);
    end
    if (context:eq('chapter', true)) then
        if (phrase:match('^None%s') ~= nil or phrase:eq('None', true)) then
            return 'None';
        end
        if (phrase:match('^Teleportation%s+Assistance') ~= nil) then
            return 'Teleportation Assistance';
        end
        if (phrase:match('^Other%s+Mysteries') ~= nil) then
            return 'Other Mysteries';
        end
    end

    local exact = T{
        ['N Second Thought None'] = 'On second thought, none',
        ['On Second Thought None'] = 'On second thought, none',
        ['On Second Thought None ww'] = 'On second thought, none',
        ['Nowhere Urhgan'] = 'Nowhere for now',
        ['Nowhere For Now'] = 'Nowhere for now',
        ['Nowhere For Now None'] = 'Nowhere for now',
        ['Nowhere For Now Areas'] = 'Nowhere for now',
        ['Select From Amongst Favorites'] = 'Select from amongst favorites',
        ['Select By Region'] = 'Select by Region',
        ['Select By Content'] = 'Select by Content',
        ['Select By Content Areas'] = 'Select by Content',
        ['O Nfaure'] = 'Ronfaure',
        ['Nfaure'] = 'Ronfaure',
        ['Oria'] = "San d'Oria",
        ['San Oria'] = "San d'Oria",
        ['Other Mysteries'] = 'Other Mysteries',
        ['Teleportation Assistance'] = 'Teleportation Assistance',
        ['Original Release Areas'] = 'Original release areas',
        ['Original Release Areas Tes'] = 'Original release areas',
        ['Rise Of The Zilart Areas'] = 'Rise of the Zilart areas',
        ['Rise Of The Zilart Areas Tes'] = 'Rise of the Zilart areas',
        ['Chains Of Promathia Areas'] = 'Chains of Promathia areas',
        ['Chains Of Promathia Areas Es'] = 'Chains of Promathia areas',
        ['Treasures Of Aht Urhgan Areas'] = 'Treasures of Aht Urhgan areas',
        ['Treasures Of Aht Urhgan Areas Gil'] = 'Treasures of Aht Urhgan areas',
        ['Wings Of The Goddess Areas'] = 'Wings of the Goddess areas',
        ['Seekers Of Adoulin Areas'] = 'Seekers of Adoulin areas',
        ['Seekers Of Adoulin Areas Tes'] = 'Seekers of Adoulin areas',
    };
    if (exact[phrase] ~= nil) then
        return exact[phrase];
    end
    if (phrase:match('^Bostaunieux%s+Oubliette') ~= nil) then
        return 'Bostaunieux Oubliette';
    end
    if (phrase:match('^King%s+Ranperre%s+Tomb') ~= nil) then
        return 'King Ranperre Tomb';
    end

    for _, prefix in ipairs(T{
        'On second thought, none',
        'Nowhere for now',
        'Select from amongst favorites',
        'Select by Region',
        'Select By Region',
        'Select by Content',
        'Select By Content',
        'Original release areas',
        'Original Release Areas',
        'Rise of the Zilart areas',
        'Rise Of The Zilart Areas',
        'Chains of Promathia areas',
        'Chains Of Promathia Areas',
        'Treasures of Aht Urhgan areas',
        'Treasures Of Aht Urhgan Areas',
        'Wings of the Goddess areas',
        'Wings Of The Goddess Areas',
        'Seekers of Adoulin areas',
        'Seekers Of Adoulin Areas',
        "San d'Oria",
        'Bastok',
        'Windurst',
        'Jeuno',
        'Tavnazia',
        'West Aht Urhgan',
        'West',
        'Adoulin Isles',
        'Ronfaure Front',
        'Norvallen Front',
        'Gustaberg Front',
        'Derfland Front',
        'Sarutabaruta Front',
        'Aragoneu Front',
        'Fauregandi Front',
        'Valdeaunia Front',
        'Ronfaure',
        'Zulkheim',
        'Norvallen',
        'Gustaberg',
        'Derfland',
        'Sarutabaruta',
        'Kolshushu',
        'Aragoneu',
        'Fauregandi',
        'Valdeaunia',
        'Qufim',
        'Li Telor',
        'Kuzotz',
        'Vollbow',
        'Elshimo Lowlands',
        'Elshimo Uplands',
        'Elshimo',
        "Tu'Lia",
        'Tu Lia',
        'Movalpolos',
        'Tavnazian Archipelago',
        'Tavnazian Arch',
        'Mamool Ja',
        'Mamool',
        'Arrapago Islands',
        'Arrapago',
        'Bostaunieux Oubliette',
        'King Ranperre Tomb',
        'Previous Page',
        'Next Page',
    }) do
        if (phrase:eq(prefix, true) or phrase:match('^' .. prefix:gsub("([%^%$%(%)%%%.%[%]%*%+%-%?])", "%%%1") .. '%s') ~= nil) then
            if (prefix == 'Original Release Areas') then
                return 'Original release areas';
            end
            if (prefix == 'Rise Of The Zilart Areas') then
                return 'Rise of the Zilart areas';
            end
            if (prefix == 'Chains Of Promathia Areas') then
                return 'Chains of Promathia areas';
            end
            if (prefix == 'Treasures Of Aht Urhgan Areas') then
                return 'Treasures of Aht Urhgan areas';
            end
            if (prefix == 'Wings Of The Goddess Areas') then
                return 'Wings of the Goddess areas';
            end
            if (prefix == 'Seekers Of Adoulin Areas') then
                return 'Seekers of Adoulin areas';
            end
            if (prefix == 'Select By Region') then
                return 'Select by Region';
            end
            if (prefix == 'Select By Content') then
                return 'Select by Content';
            end
            if (prefix == 'Tu Lia') then
                return "Tu'Lia";
            end
            if (prefix == 'Tavnazian Arch') then
                return 'Tavnazian Archipelago';
            end
            if (prefix == 'Mamool') then
                return 'Mamool Ja';
            end
            if (prefix == 'Arrapago') then
                return 'Arrapago Islands';
            end
            if (prefix == 'Elshimo' and phrase:contains('Up', true)) then
                return 'Elshimo Uplands';
            end
            if (prefix == 'Elshimo' and phrase:contains('Low', true)) then
                return 'Elshimo Lowlands';
            end
            return prefix;
        end
    end

    phrase = phrase:gsub('%s+Ysteries$', '');
    phrase = phrase:gsub('%s+Stance$', '');
    phrase = phrase:gsub('%s+Assistance$', '');
    phrase = phrase:gsub('%s+Amongst Favorites$', '');
    phrase = phrase:gsub('%s+Ongst Favorites$', '');
    phrase = phrase:gsub('%s+Favorites$', '');
    phrase = phrase:gsub('%s+Avorites$', '');
    phrase = phrase:gsub('%s+Front St Favorites$', '');
    phrase = phrase:gsub('%s+Front None$', '');
    phrase = phrase:gsub('%s+Ght None$', '');
    phrase = phrase:gsub('%s+Ont None$', '');
    phrase = phrase:gsub('%s+Ht None$', '');
    phrase = phrase:gsub('%s+Ries None$', '');
    phrase = phrase:gsub('%s+None$', '');
    phrase = phrase:gsub('%s+Ance$', '');
    phrase = phrase:gsub('%s+Lin Areas$', '');
    phrase = phrase:gsub('%s+Thia Areas$', '');
    phrase = phrase:gsub('%s+Es Of Aht Urhgan Areas$', '');
    phrase = phrase:gsub('%s+Eas$', '');
    phrase = phrase:gsub('%s+One$', '');
    phrase = phrase:gsub('%s+ww$', '');
    phrase = accessxi.survival_guide_text(phrase);
    return phrase;
end

function accessxi.plain_native_menu_label(label)
    label = accessxi.survival_guide_text(label or '');
    if (label == '') then
        return '';
    end

    label = label:gsub('^["\']+', ''):gsub('["\']+$', '');
    label = label:gsub('%s+ww$', '');
    label = accessxi.survival_guide_text(label);
    if (label == '' or #label > 80) then
        return '';
    end
    if (label:match('^[%p%s]+$') ~= nil) then
        return '';
    end
    if (not accessxi.native_query_label_looks_real(label)) then
        return '';
    end

    return label;
end

function accessxi.plain_native_menu_help(text)
    text = accessxi.survival_guide_text(text or '');
    if (text == '') then
        return '';
    end

    text = text:gsub('^["\']+', ''):gsub('["\']+$', '');
    text = accessxi.survival_guide_text(text);
    if (text == '' or #text > 160) then
        return '';
    end
    if (text:match('^[%p%s]+$') ~= nil) then
        return '';
    end
    if (text:find('menu    ', 1, true) ~= nil or text:find('anc     ', 1, true) ~= nil) then
        return '';
    end
    return text;
end

function accessxi.plain_native_menu_prompt(text)
    text = accessxi.survival_guide_text(text or '');
    if (text == '') then
        return '';
    end

    text = text:gsub('^["\']+', ''):gsub('["\']+$', '');
    text = accessxi.survival_guide_text(text);
    if (text == '' or #text > 260) then
        return '';
    end
    if (text:match('^[%p%s]+$') ~= nil) then
        return '';
    end
    if (text:find('menu    ', 1, true) ~= nil or text:find('anc     ', 1, true) ~= nil) then
        return '';
    end
    return text;
end

function accessxi.sentence_fragment(text)
    text = accessxi.survival_guide_text(text or '');
    if (text == '') then
        return '';
    end
    if (text:match('[%.%!%?]$') ~= nil) then
        return text;
    end
    return text .. '.';
end

function accessxi.menu_row_speech_without_repeated_title(text, menu_name, key)
    text = tostring(text or '');
    menu_name = tostring(menu_name or '');
    key = tostring(key or '');
    local title = accessxi.survival_guide_text(accessxi.current_menu_speech_title or '');
    if (text == '' or title == '') then
        return text;
    end

    local prefix = title .. '.';
    if (text:sub(1, #prefix) ~= prefix) then
        return text;
    end

    local spoken = text:sub(#prefix + 1):gsub('^%s+', '');
    if (spoken == '') then
        return text;
    end

    local transition_tick = tonumber(accessxi.last_menu_transition_tick) or 0;
    local prefix_key = ('%s:%s:%d'):fmt(menu_name, title, transition_tick);
    if (prefix_key ~= tostring(accessxi.menu_title_prefix_spoken_key or '')) then
        accessxi.menu_title_prefix_spoken_key = prefix_key;
        accessxi.menu_title_prefix_spoken_title = title;
        accessxi.menu_title_prefix_spoken_tick = tick();
        log_state(('state menu-title-prefix announced menu="%s" key="%s" prefix="%s" text="%s"'):fmt(
            accessxi.escape_probe_log_text(menu_name),
            accessxi.escape_probe_log_text(key),
            accessxi.escape_probe_log_text(title),
            accessxi.escape_probe_log_text(text)));
        return text;
    end

    log_state(('state menu-title-prefix suppressed menu="%s" key="%s" prefix="%s" original="%s" spoken="%s"'):fmt(
        accessxi.escape_probe_log_text(menu_name),
        accessxi.escape_probe_log_text(key),
        accessxi.escape_probe_log_text(title),
        accessxi.escape_probe_log_text(text),
        accessxi.escape_probe_log_text(spoken)));
    return spoken;
end

function accessxi.native_query_label_for_position(label, expected_count, selected, context)
    context = tostring(context or 'teleport');
    label = accessxi.native_query_normalize_phrase(label or '', context);
    expected_count = tonumber(expected_count) or 0;
    selected = tonumber(selected) or 0;
    if (label == '') then
        return '';
    end

    if (context:eq('plain', true) or context:eq('main-menu', true) or context:eq('config-visible', true)) then
        return accessxi.plain_native_menu_label(label);
    end

    label = accessxi.survival_guide_clean_native_destination_label(label, expected_count, selected);

    if (expected_count == 27) then
        if (selected == 8 and label:eq('West', true)) then
            return 'West Aht Urhgan';
        end
        if (selected == 10 and label:eq('Ronfaure Front', true)) then
            return 'Ronfaure';
        end
        if (selected == 12 and label:eq('Norvallen Front', true)) then
            return 'Norvallen';
        end
        if (selected == 24 and label:eq('Elshimo', true)) then
            return 'Elshimo Lowlands';
        end
        if (selected == 25 and label:eq('Elshimo', true)) then
            return 'Elshimo Uplands';
        end
        if (selected == 26 and label:eq('Favorites', true)) then
            return "Tu'Lia";
        end
    elseif (expected_count == 15) then
        if (selected == 13 and label:eq('Fauregandi', true)) then
            return 'Fauregandi Front';
        end
        if (selected == 14 and label:eq('Valdeaunia', true)) then
            return 'Valdeaunia Front';
        end
    elseif (expected_count == 4) then
        if (selected == 1 and (label:eq('Nowhere', true) or label:match('^Nowhere%s') ~= nil)) then
            return 'Nowhere for now';
        end
        if (selected == 3 and label:match('^Bostaunieux%s+Oubliette') ~= nil) then
            return 'Bostaunieux Oubliette';
        end
    end

    return label;
end

function accessxi.native_query_candidate_score(label, source_offset, expected_count, selected, context)
    context = tostring(context or 'teleport');
    label = accessxi.native_query_label_for_position(label, expected_count, selected, context);
    if (label == '') then
        return -1000;
    end

    local score = 10;
    source_offset = tonumber(source_offset) or 0;
    if (source_offset == 0x10) then
        score = score + 5;
    elseif (source_offset == 0x38 or source_offset == 0x88 or source_offset == 0x100) then
        score = score + 3;
    end

    if (context:eq('plain', true) or context:eq('main-menu', true) or context:eq('config-visible', true)) then
        for _, bad in ipairs(T{ 'Scrubber', 'Control', 'Outline', 'Hover', 'StrengthReduce' }) do
            if (label:contains(bad, true)) then
                score = score - 60;
            end
        end
        if (#label > 48) then
            score = score - 10;
        end
        return score;
    end

    accessxi.native_query_clean_labels = accessxi.native_query_clean_labels or T{
        'On second thought, none', 'Nowhere for now', 'Select from amongst favorites',
        'Original release areas', 'Rise of the Zilart areas', 'Chains of Promathia areas',
        'Treasures of Aht Urhgan areas', 'Wings of the Goddess areas', 'Seekers of Adoulin areas',
        "San d'Oria", 'Bastok', 'Windurst', 'Jeuno', 'Tavnazia', 'West Aht Urhgan',
        'Adoulin Isles', 'Ronfaure', 'Zulkheim', 'Norvallen', 'Gustaberg',
        'Derfland', 'Sarutabaruta', 'Kolshushu', 'Aragoneu', 'Fauregandi',
        'Valdeaunia', 'Qufim', 'Li Telor', 'Kuzotz', 'Vollbow',
        'Elshimo Lowlands', 'Elshimo Uplands', "Tu'Lia", 'Movalpolos',
        'Tavnazian Archipelago', 'Mamool Ja', 'Arrapago Islands',
        'Ronfaure Front', 'Norvallen Front', 'Gustaberg Front', 'Derfland Front',
        'Sarutabaruta Front', 'Aragoneu Front', 'Fauregandi Front',
        'Valdeaunia Front', 'Bostaunieux Oubliette', 'King Ranperre Tomb',
        'Previous Page', 'Next Page',
    };
    for _, clean in ipairs(accessxi.native_query_clean_labels) do
        if (label:eq(clean, true)) then
            score = score + 60;
            break;
        end
    end

    accessxi.native_query_bad_fragments = accessxi.native_query_bad_fragments or T{
        'Orites', 'Scrubber', 'Control', 'Outline', 'Hover', 'StrengthReduce', 'Assistance ww', 'None ww',
    };
    for _, bad in ipairs(accessxi.native_query_bad_fragments) do
        if (label:contains(bad, true)) then
            score = score - 60;
        end
    end
    if (label:eq('West', true)) then
        score = score - 20;
    end
    if (expected_count > accessxi.survival_guide_teleport_count()) then
        if (label:eq('Nowhere for now', true) and selected ~= 1) then
            score = score - 90;
        end
        if (label:eq('Next Page', true) and selected < math.max(expected_count - 2, 1)) then
            score = score - 90;
        end
    end
    if (#label > 40) then
        score = score - 20;
    end

    return score;
end

function accessxi.native_query_candidate_label_from_ptr(ptr, context)
    ptr = tonumber(ptr) or 0;
    if (not accessxi.is_probe_pointer(ptr)) then
        return '';
    end

    local recognized_native_text = accessxi.native_query_text_object_is_framed(ptr);
    if (recognized_native_text) then
        local phrase = accessxi.native_query_phrase_from_ptr(ptr, context);
        if (phrase ~= '') then
            return accessxi.native_query_normalize_phrase(phrase, context);
        end
        return '';
    end

    for _, off in ipairs(T{ 0x00, 0x04, 0x10, 0x14, 0x18, 0x20 }) do
        local text = read_probe_string(ptr + off);
        local label = accessxi.native_query_candidate_label_from_text(text, context);
        if (label ~= '') then
            return label;
        end
    end

    if (accessxi.collect_probe_ffxi_utf16_entries ~= nil) then
        local entries = accessxi.collect_probe_ffxi_utf16_entries(ptr, 0x180, 2, 12);
        for _, entry in ipairs(entries) do
            local label = accessxi.native_query_candidate_label_from_text(entry.text or '', context);
            if (label ~= '') then
                return label;
            end
        end
    end

    return '';
end

function accessxi.native_query_candidate_label_from_node(node, context, expected_count, selected)
    node = tonumber(node) or 0;
    if (not accessxi.is_probe_pointer(node)) then
        return '';
    end

    local best_label = '';
    local best_score = -1000;
    for _, off in ipairs(T{ 0x10, 0x38, 0x88, 0x100, 0x00, 0x04, 0x28, 0x2C }) do
        local ptr = read_u32(node + off) or 0;
        if (accessxi.is_probe_pointer(ptr)) then
            local label = accessxi.native_query_candidate_label_from_ptr(ptr, context);
            if (label ~= '') then
                label = accessxi.native_query_label_for_position(label, expected_count, selected, context);
                local score = accessxi.native_query_candidate_score(label, off, expected_count, selected, context);
                if (score > best_score) then
                    best_score = score;
                    best_label = label;
                end
            end
        end
    end

    return best_label;
end

function accessxi.native_query_collect_items_with_next(first, expected_count, next_off, context)
    local items = T{};
    local seen = {};
    local node = tonumber(first) or 0;
    local limit = math.min(math.max(tonumber(expected_count) or 0, 4), 64);

    for _ = 1, limit do
        if (not accessxi.is_probe_pointer(node) or seen[node] == true) then
            break;
        end

        seen[node] = true;
        local position = items:len() + 1;
        local label = accessxi.native_query_candidate_label_from_node(node, context, expected_count, position);
        local index = read_u16(node + 0x104) or 0;
        items:append({
            ptr = node,
            label = label,
            index = index,
        });

        local next_node = read_u32(node + next_off) or 0;
        if (not accessxi.is_probe_pointer(next_node)) then
            break;
        end
        node = next_node;
    end

    return items;
end

function accessxi.native_query_score_items(items, expected_count)
    expected_count = tonumber(expected_count) or 0;
    if (items == nil or items:len() == 0) then
        return 0;
    end

    local score = 0;
    local labels = 0;
    local indexed = 0;
    local last_index = -1;
    for _, item in ipairs(items) do
        local label = tostring(item.label or '');
        if (label ~= '') then
            labels = labels + 1;
            score = score + 10;
            local fragment_penalty = accessxi.native_query_label_fragment_penalty(label);
            if (fragment_penalty > 0) then
                score = score - math.min(fragment_penalty, 90);
            else
                if (label:find('%s') ~= nil) then
                    score = score + 3;
                end
                if (#label >= 8) then
                    score = score + 2;
                end
            end
        end
        local index = tonumber(item.index) or 0;
        if (index > 0 and index >= last_index) then
            indexed = indexed + 1;
            score = score + 2;
            last_index = index;
        end
    end

    if (expected_count > 0 and items:len() == expected_count) then
        score = score + 50;
    elseif (expected_count > 0 and items:len() > expected_count) then
        score = score - 10;
    end

    if (labels == 0) then
        return 0;
    end

    return score + indexed;
end

function accessxi.native_query_items_are_expansion_sort(items, expected_count)
    expected_count = tonumber(expected_count) or 0;
    if (expected_count ~= 8 or items == nil or items:len() ~= 8) then
        return false;
    end

    local hits = 0;
    local positional_hits = 0;
    for i, item in ipairs(items) do
        local label = accessxi.native_query_normalize_phrase(tostring(item.label or ''), 'teleport');
        local expected = accessxi.native_query_expansion_sort_label(i);
        if (expected ~= '' and label:eq(expected, true)) then
            positional_hits = positional_hits + 1;
        end
        if (label:eq('Original release areas', true)
            or label:eq('Rise of the Zilart areas', true)
            or label:eq('Chains of Promathia areas', true)
            or label:eq('Treasures of Aht Urhgan areas', true)
            or label:eq('Wings of the Goddess areas', true)
            or label:eq('Seekers of Adoulin areas', true)) then
            hits = hits + 1;
        end
    end

    return positional_hits >= 2 or hits >= 3;
end

function accessxi.native_query_expansion_sort_label(selected)
    selected = tonumber(selected) or 0;
    local labels = T{
        'Nowhere for now',
        'Select from amongst favorites',
        'Original release areas',
        'Rise of the Zilart areas',
        'Chains of Promathia areas',
        'Treasures of Aht Urhgan areas',
        'Wings of the Goddess areas',
        'Seekers of Adoulin areas',
    };
    return labels[selected] or '';
end

function accessxi.native_query_node_debug(ptr, label)
    ptr = tonumber(ptr) or 0;
    label = tostring(label or 'node');
    if (not accessxi.is_probe_pointer(ptr)) then
        return ('%s=0x%08X unreadable'):fmt(label, ptr);
    end

    local ptrs = T{};
    for _, off in ipairs(T{ 0x00, 0x04, 0x08, 0x0C, 0x10, 0x14, 0x18, 0x1C, 0x20, 0x24, 0x28, 0x2C, 0x30, 0x38, 0x40, 0x84, 0x88, 0x100, 0x104, 0x108 }) do
        local value = read_u32(ptr + off) or 0;
        if (accessxi.is_probe_pointer(value)) then
            local strings = accessxi.probe_strings_at(value);
            if (strings ~= '') then
                ptrs:append(('+%03X->0x%08X %s'):fmt(off, value, strings:gsub('"', "'")));
            else
                ptrs:append(('+%03X->0x%08X'):fmt(off, value));
            end
        elseif (off >= 0x100) then
            ptrs:append(('+%03X=0x%08X'):fmt(off, value));
        end
    end

    return ('%s=0x%08X %s ptrs="%s"'):fmt(
        label,
        ptr,
        accessxi.format_probe_bytes ~= nil and accessxi.format_probe_bytes(ptr, 0, 0x50) or '',
        ptrs:concat(' | '));
end

function accessxi.native_query_items_for_child(child, expected_count, context)
    child = tonumber(child) or 0;
    expected_count = tonumber(expected_count) or 0;
    if (not accessxi.is_probe_pointer(child) or expected_count <= 0 or expected_count > 256) then
        return T{}, 'invalid';
    end

    local first = read_u32(child + 0x14) or 0;
    local last = read_u32(child + 0x18) or 0;
    local key = ('0x%08X:%d:0x%08X:0x%08X:%s'):fmt(child, expected_count, first, last, tostring(context or ''));
    if (accessxi.native_query_list_cache_key == key and accessxi.native_query_list_cache_items ~= nil) then
        return accessxi.native_query_list_cache_items, accessxi.native_query_list_cache_mode;
    end

    local best_items = T{};
    local best_mode = 'empty';
    local best_score = 0;
    local summaries = T{};
    for _, next_off in ipairs(T{ 0x00, 0x84, 0x88, 0x100, 0x108, 0x10, 0x14, 0x18, 0x1C, 0x20 }) do
        local items = accessxi.native_query_collect_items_with_next(first, expected_count, next_off, context);
        local score = accessxi.native_query_score_items(items, expected_count);
        local sample = T{};
        for i = 1, math.min(items:len(), 6) do
            local item = items[i];
            sample:append(('%d:%s'):fmt(i, tostring(item.label or ''):gsub('"', "'")));
        end
        summaries:append(('+%03X len=%d score=%d [%s]'):fmt(next_off, items:len(), score, sample:concat(' | ')));
        if (score > best_score) then
            best_score = score;
            best_items = items;
            best_mode = ('next+%03X'):fmt(next_off);
        end
    end

    if (best_score == 0) then
        local item = {
            ptr = first,
            label = accessxi.native_query_candidate_label_from_node(first, context, expected_count, 1),
            index = read_u16(first + 0x104) or 0,
        };
        if (item.label ~= '') then
            best_items = T{ item };
            best_mode = 'first-node';
        end
    end

    accessxi.native_query_list_cache_key = key;
    accessxi.native_query_list_cache_items = best_items;
    accessxi.native_query_list_cache_mode = best_mode;

    local labels = T{};
    for i = 1, math.min(best_items:len(), 12) do
        local item = best_items[i];
        labels:append(('%d:%s#%d'):fmt(i, tostring(item.label or ''):gsub('"', "'"), tonumber(item.index) or 0));
    end
    local line = ('native query list child=0x%08X count=%d first=0x%08X last=0x%08X mode=%s best=%d labels="%s" tries="%s"'):fmt(
        child,
        expected_count,
        first,
        last,
        best_mode,
        best_score,
        labels:concat(' | '),
        summaries:concat(' ; '));
    if (line ~= accessxi.native_query_list_last_log) then
        accessxi.native_query_list_last_log = line;
        log_line(line);
        local debug = T{};
        debug:append(accessxi.native_query_node_debug(first, 'first'));
        debug:append(accessxi.native_query_node_debug(read_u32(first + 0x00) or 0, 'first+000'));
        debug:append(accessxi.native_query_node_debug(read_u32(first + 0x10) or 0, 'first+010'));
        debug:append(accessxi.native_query_node_debug(read_u32(first + 0x88) or 0, 'first+088'));
        log_line(('native query debug child=0x%08X %s'):fmt(child, debug:concat(' || ')));
    end

    return best_items, best_mode;
end

function accessxi.native_query_label_for_selection(child, selected, expected_count, context)
    selected = tonumber(selected) or 0;
    expected_count = tonumber(expected_count) or 0;
    if (selected <= 0 or expected_count <= 0) then
        return '', 'invalid';
    end

    local items, mode = accessxi.native_query_items_for_child(child, expected_count, context);
    if (items == nil or items:len() == 0) then
        return '', mode;
    end

    local item = items[selected];
    if (item ~= nil and tostring(item.label or '') ~= '') then
        local label = accessxi.native_query_label_for_position(tostring(item.label or ''), expected_count, selected, context);
        if (label ~= tostring(item.label or '')) then
            return label, mode .. ':order-clean';
        end
        return label, mode .. ':order';
    end

    return '', mode .. ':missing';
end

function accessxi.is_help_desk_menu_name(name)
    name = tostring(name or '');
    return name:eq('menu    faqsub', true) or name:eq('menu    faqmain', true);
end

function accessxi.help_desk_node_label(node, expected_count, selected)
    node = tonumber(node) or 0;
    if (not accessxi.is_probe_pointer(node)) then
        return '';
    end

    local best_label = '';
    local best_score = -1000;
    for _, off in ipairs(T{ 0x08, 0x40, 0x44, 0x10, 0x38, 0x88, 0x100, 0x00, 0x04 }) do
        local ptr = read_u32(node + off) or 0;
        if (accessxi.is_probe_pointer(ptr)) then
            local label = accessxi.native_query_candidate_label_from_ptr(ptr, 'help-desk');
            label = accessxi.plain_native_menu_label(label or '');
            if (label ~= '') then
                label = accessxi.native_query_label_for_position(label, expected_count, selected, 'help-desk');
                local score = accessxi.native_query_candidate_score(label, off, expected_count, selected, 'help-desk');
                if (off == 0x08 or off == 0x40 or off == 0x44) then
                    score = score + 25;
                end
                if (score > best_score) then
                    best_score = score;
                    best_label = label;
                end
            end
        end
    end

    return best_label;
end

function accessxi.help_desk_top_resource_items(page, raw)
    page = tonumber(page) or 0;
    raw = tonumber(raw) or 0;
    if (not ((page == 28417 and raw == 0x6F010019) or (page == 1 and raw == 0x00010019))) then
        return nil;
    end

    -- Client resource rows from ROM\165\72.DAT for the top Help Desk page.
    return T{
        { label = 'Q&A', dat = 'ROM\\165\\72.DAT', row = 195 },
        { label = 'Adventuring Primer', dat = 'ROM\\165\\72.DAT', row = 299 },
        { label = 'Mentor Search', dat = 'ROM\\165\\72.DAT', row = 207 },
        { label = 'Help Desk', dat = 'ROM\\165\\72.DAT', row = 197 },
        { label = 'Config', dat = 'ROM\\165\\72.DAT', row = 198 },
        { label = 'Back', dat = 'ROM\\165\\72.DAT', row = 199 },
    };
end

function accessxi.help_desk_config_resource_items(page, raw, expected_count)
    page = tonumber(page) or 0;
    raw = tonumber(raw) or 0;
    expected_count = tonumber(expected_count) or 0;
