function accessxi.merit_menu_native_index(selected, child, max_count)
    selected = tonumber(selected) or 0;
    child = tonumber(child) or 0;
    max_count = tonumber(max_count) or 0;
    if (selected <= 0) then
        return 0, 0, 0;
    end

    local scroll_raw = 0;
    local scroll_top = 0;
    if (accessxi.is_probe_pointer(child)) then
        scroll_raw = read_u32(child + 0x18) or 0;
        scroll_top = bit.rshift(scroll_raw, 16);
        if (scroll_top < 0 or scroll_top > 512) then
            scroll_top = 0;
        end
    end

    if (max_count > 0 and max_count <= 13 and selected <= max_count) then
        return selected, 0, scroll_raw;
    end

    local logical = scroll_top + selected;
    if (max_count > 0 and (logical < 1 or logical > max_count)) then
        logical = selected;
        scroll_top = 0;
    end
    return logical, scroll_top, scroll_raw;
end

function accessxi.merit_resource_label(id)
    id = tonumber(id) or -1;
    if (id < 0 or id > 4096) then
        return '';
    end

    local entry = accessxi.merit_resource_entry(id);
    if (entry ~= nil) then
        local text = accessxi.plain_native_menu_label(accessxi.survival_guide_text(entry.en or entry.english or entry.name or ''));
        if (text ~= '') then
            return text;
        end
    end

    local resources = safe_call(function () return AshitaCore:GetResourceManager(); end, nil);
    if (resources == nil) then
        return '';
    end

    local text = safe_call(function () return resources:GetString('merits', id); end, '') or '';
    text = accessxi.plain_native_menu_label(accessxi.survival_guide_text(text));
    if (text == ''
        or text:eq('Unknown', true)
        or text:match('^MeripoName%d+$') ~= nil
        or text:match('^Meripo %d+ help text%.$') ~= nil) then
        return '';
    end
    return text;
end

function accessxi.load_merit_points_resource()
    if (accessxi.merit_points_resource ~= nil) then
        return accessxi.merit_points_resource;
    end
    if (accessxi.merit_points_resource_load_tried == true) then
        return nil;
    end
    accessxi.merit_points_resource_load_tried = true;

    local paths = T{
        accessxi.resource_path('windower', 'merit_points.lua'),
    };
    for _, path in ipairs(paths) do
        local f = io.open(path, 'rb');
        if (f ~= nil) then
            f:close();
            local ok, data = pcall(function ()
                return loadfile(path)();
            end);
            if (ok and type(data) == 'table') then
                accessxi.merit_points_resource = data;
                accessxi.merit_points_resource_path = path;
                log_line(('loaded merit points resource path="%s"'):fmt(path));
                return accessxi.merit_points_resource;
            end
            log_line(('merit points resource load failed path="%s" err="%s"'):fmt(path, tostring(data)));
        end
    end

    log_line('merit points resource unavailable');
    return nil;
end

function accessxi.merit_resource_entry(id)
    id = tonumber(id) or -1;
    local resource = accessxi.load_merit_points_resource();
    if (type(resource) ~= 'table') then
        return nil;
    end
    local entry = resource[id];
    if (type(entry) ~= 'table') then
        return nil;
    end
    return entry;
end

function accessxi.merit_resource_help(id)
    local entry = accessxi.merit_resource_entry(id);
    if (entry == nil) then
