    end

    local option_label = tostring(accessxi.current_job_point_category_label or '');
    if (option_label == '') then
        option_label = accessxi.job_point_resource_label(packet_id);
    end
    if (option_label == '') then
        option_label = 'this job point category';
    end

    local packet_entry = accessxi.job_point_packet_entry(packet_id);
    local rank = packet_entry ~= nil and (tonumber(packet_entry.value) or 0) or -1;
    local next_cost = packet_entry ~= nil and (tonumber(packet_entry.next_cost) or 0) or 0;
    local prompt = '';
    if (next_cost > 0) then
        prompt = ('Use %s to raise your "%s" by one level?'):fmt(accessxi.job_point_phrase(next_cost), option_label);
    else
        prompt = ('Use job points to raise your "%s" by one level?'):fmt(option_label);
    end

    accessxi.last_native_menu_name = menu_name;
    accessxi.last_native_menu_label = choice;
    accessxi.last_native_menu_selected = selected;
    accessxi.last_native_menu_tick = tick();
    accessxi.current_speech_key = ('native-known-jobpoint-confirmation:%s:%d:%d:0x%08X:%d:%s:%s:%d:%d'):fmt(
        menu_name,
        selected,
        count,
        entry,
        packet_id,
        option_label,
        choice,
        rank,
        next_cost);
    log_state(('state nativemenu jobpoint-confirmation-dat menu="%s" title="%s" select=%d count=%d entry=0x%08X choice="%s" prompt="%s" option="%s" jpId=%d resourceId=%d rank=%d nextCost=%d job=%d jobLabel="%s" optionHelp="%s" source="ROM\\97\\38.DAT#116; ROM\\97\\37.DAT#106-107; packet 0x08D next cost"'):fmt(
        menu_name,
        tostring(title or ''),
        selected,
        count,
        entry,
        choice,
        accessxi.escape_probe_log_text(prompt),
        accessxi.escape_probe_log_text(option_label),
        packet_id,
        accessxi.job_point_resource_id(packet_id),
        rank,
        next_cost,
        tonumber(accessxi.current_job_point_job_id) or 0,
        accessxi.escape_probe_log_text(accessxi.current_job_point_job_label or ''),
        accessxi.escape_probe_log_text(accessxi.current_job_point_category_help or '')));
    return accessxi.sentence_fragment(('Job point confirmation. %s. %s'):fmt(choice, prompt));
end

function accessxi.merit_adjustment_speech(menu_name, title, selected, count, entry)
    menu_name = tostring(menu_name or '');
    if (not menu_name:eq('menu    merit3', true)) then
        return nil;
    end

    selected = tonumber(selected) or 0;
    count = tonumber(count) or 0;
    local description, row2, desc = accessxi.status_menu_native_description_for_entry(entry);
    if (description == '') then
        log_state(('state nativemenu merit-adjustment missing menu="%s" title="%s" select=%d count=%d entry=0x%08X'):fmt(
            menu_name,
            tostring(title or ''),
            selected,
            count,
            tonumber(entry) or 0));
        return nil;
    end

    accessxi.last_native_menu_name = menu_name;
    accessxi.last_native_menu_label = description;
    accessxi.last_native_menu_selected = selected;
    accessxi.last_native_menu_tick = tick();
    accessxi.current_merit_adjustment_label = accessxi.merit_adjustment_label_from_description(description);
    accessxi.current_merit_adjustment_help = description;
    accessxi.current_merit_adjustment_tick = tick();
    accessxi.current_speech_key = ('native-known-merit-adjustment:%s:%d:%d:0x%08X:0x%08X:%s'):fmt(
        menu_name,
        selected,
        count,
        tonumber(entry) or 0,
        tonumber(row2) or 0,
        description);
    log_state(('state nativemenu merit-adjustment menu="%s" title="%s" select=%d count=%d entry=0x%08X desc=0x%08X row2=0x%08X text="%s"'):fmt(
        menu_name,
        tostring(title or ''),
        selected,
        count,
        tonumber(entry) or 0,
        tonumber(desc) or 0,
        tonumber(row2) or 0,
        accessxi.escape_probe_log_text(description)));
    return ('Merit adjustment. %s'):fmt(accessxi.sentence_fragment(description));
end

function accessxi.merit_mode_switch_speech(menu_name, title, selected, count, entry)
    menu_name = tostring(menu_name or '');
    if (not menu_name:eq('menu    merit2', true)) then
        return nil;
    end

    selected = tonumber(selected) or 0;
    count = tonumber(count) or 0;
    entry = tonumber(entry) or 0;
    local description, row2, desc = accessxi.status_menu_native_description_for_entry(entry);
    description = tostring(description or ''):gsub('%s+', ' '):trim();
    if (description == '') then
        return nil;
    end

    local lower = description:lower();
    local label = '';
    if (lower:find('limit points', 1, true) ~= nil and lower:find('merit points', 1, true) ~= nil) then
        label = 'Limit points';
    elseif (lower:find('experience points', 1, true) ~= nil) then
        label = 'Experience points';
    else
        return nil;
    end

    accessxi.last_native_menu_name = menu_name;
    accessxi.last_native_menu_label = label;
    accessxi.last_native_menu_selected = selected;
    accessxi.last_native_menu_tick = tick();
    accessxi.current_speech_key = ('native-known-merit-mode:%s:%d:%d:0x%08X:0x%08X:%s:%s'):fmt(
        menu_name,
        selected,
        count,
        entry,
        tonumber(row2) or 0,
        label,
        description);
    log_state(('state nativemenu merit-mode menu="%s" title="%s" select=%d count=%d entry=0x%08X desc=0x%08X row2=0x%08X label="%s" text="%s"'):fmt(
        menu_name,
        tostring(title or ''),
        selected,
        count,
        entry,
        tonumber(desc) or 0,
        tonumber(row2) or 0,
        accessxi.escape_probe_log_text(label),
        accessxi.escape_probe_log_text(description)));
    return ('Merit point mode. %s. %s'):fmt(label, accessxi.sentence_fragment(description));
end

function accessxi.merit_option_speech(menu_name, title, selected, count, child, entry, obj)
    selected = tonumber(selected) or 0;
    count = tonumber(count) or 0;
    obj = tonumber(obj) or 0;
    local category_logical = tonumber(accessxi.current_merit_category_logical) or 0;
    local category_label = tostring(accessxi.current_merit_category_label or '');
    local category_source = 'context';
    if (category_logical <= 0) then
        category_logical = accessxi.merit_category_from_menu_name(menu_name);
        local row = accessxi.merit_category_dat_rows[category_logical];
        if (row ~= nil and tostring(row.label or '') ~= '') then
            category_label = tostring(row.label or '');
            category_source = 'menu-name';
            accessxi.current_merit_category_logical = category_logical;
            accessxi.current_merit_category_label = category_label;
        end
    end
    if (category_logical <= 0) then
        log_state(('state nativemenu merit-option missing-category menu="%s" title="%s" select=%d count=%d child=0x%08X entry=0x%08X'):fmt(
            tostring(menu_name or ''),
            tostring(title or ''),
            selected,
            count,
            tonumber(child) or 0,
            tonumber(entry) or 0));
        return nil;
    end

    local options = accessxi.merit_options_for_category(category_logical);
    local visual_rows = accessxi.merit_visual_rows_for_options(category_logical, options);
    local logical, scroll_top, scroll_raw = 0, 0, 0;
    local option = nil;
    local header_label = '';
    local header_help = '';
    if (visual_rows ~= nil) then
        local visual_logical = 0;
        visual_logical, scroll_top, scroll_raw = accessxi.merit_menu_native_index(selected, child, visual_rows:len());
        local visual_row = visual_rows[visual_logical];
        if (visual_row ~= nil and visual_row.header == true) then
            header_label = tostring(visual_row.label or '');
            header_help = tostring(visual_row.help or '');
            logical = visual_logical;
        elseif (visual_row ~= nil and visual_row.option ~= nil) then
            option = visual_row.option;
            logical = tonumber(visual_row.logical) or visual_logical;
        else
            logical = visual_logical;
        end
    else
        logical, scroll_top, scroll_raw = accessxi.merit_menu_native_index(selected, child, options:len());
        option = options[logical];
    end
    local visible_label = '';
    if (obj ~= 0 and selected > 0) then
        local visible_labels, visible_child = accessxi.merit_category_native_visible_labels(obj);
        if (visible_labels ~= nil and visible_labels:len() >= selected) then
            visible_label = accessxi.merit_category_native_label_text(visible_labels[selected] or '');
        end
        accessxi.log_merit_category_visible_probe(menu_name, title, obj, selected, count, visible_labels, visible_child, 'merit-option-visible');
    end

    if (header_label ~= '') then
        local label = accessxi.sentence_fragment(header_label);
        local help = accessxi.sentence_fragment(header_help);
        accessxi.last_native_menu_name = tostring(menu_name or '');
        accessxi.last_native_menu_label = header_label;
        accessxi.last_native_menu_selected = logical;
        accessxi.last_native_menu_tick = tick();
        accessxi.current_speech_key = ('native-known-merit-header:%s:%d:%d:%d:%d:%08X:%s:%s'):fmt(
            tostring(menu_name or ''),
            category_logical,
            selected,
            logical,
            visual_rows ~= nil and visual_rows:len() or 0,
            scroll_raw,
            header_label,
            header_help);
        log_state(('state nativemenu merit-option-header menu="%s" title="%s" category=%d categoryLabel="%s" visual=%d logical=%d scrollTop=%d scrollRaw=0x%08X count=%d rows=%d label="%s" help="%s" visible="%s"'):fmt(
            tostring(menu_name or ''),
            tostring(title or ''),
            category_logical,
            accessxi.escape_probe_log_text(category_label),
            selected,
            logical,
            scroll_top,
            scroll_raw,
            count,
            visual_rows ~= nil and visual_rows:len() or 0,
            accessxi.escape_probe_log_text(header_label),
            accessxi.escape_probe_log_text(header_help),
            accessxi.escape_probe_log_text(visible_label)));
        if (help ~= '') then
            return ('%s merits. %s %s'):fmt(category_label ~= '' and category_label or tostring(title or 'Merit options'), label, help);
        end
        return ('%s merits. %s'):fmt(category_label ~= '' and category_label or tostring(title or 'Merit options'), label);
    end

    local visible_match = nil;
    if (visual_rows == nil) then
        visible_match = accessxi.merit_option_match_from_label(visible_label, category_logical);
    end
    if (visible_match ~= nil and visible_match ~= false) then
        category_logical = tonumber(visible_match.category) or category_logical;
        local category_row = accessxi.merit_category_dat_rows[category_logical];
        if (category_row ~= nil and tostring(category_row.label or '') ~= '') then
            category_label = tostring(category_row.label or '');
            accessxi.current_merit_category_logical = category_logical;
            accessxi.current_merit_category_label = category_label;
        end
        options = accessxi.merit_options_for_category(category_logical);
        for i = 1, options:len() do
            if ((tonumber(options[i].id) or -1) == (tonumber(visible_match.id) or -2)) then
                logical = i;
                option = options[i];
                category_source = 'visible-label';
                break;
            end
        end
    end
    if (option == nil or tostring(option.label or '') == '') then
        if (options:len() > 0 and logical > options:len()) then
            accessxi.current_speech_key = ('native-known-merit-option-blank:%s:%d:%d:%d:%d:%08X'):fmt(
                tostring(menu_name or ''),
                category_logical,
                selected,
                logical,
                options:len(),
                scroll_raw);
            log_state(('state nativemenu merit-option blank menu="%s" title="%s" category=%d categoryLabel="%s" visual=%d logical=%d scrollTop=%d scrollRaw=0x%08X count=%d options=%d visible="%s"'):fmt(
                tostring(menu_name or ''),
                tostring(title or ''),
                category_logical,
                accessxi.escape_probe_log_text(category_label),
                selected,
                logical,
                scroll_top,
                scroll_raw,
                count,
                options:len(),
                accessxi.escape_probe_log_text(visible_label)));
            return '';
        end
        log_state(('state nativemenu merit-option missing-option menu="%s" title="%s" category=%d categoryLabel="%s" visual=%d logical=%d scrollTop=%d scrollRaw=0x%08X count=%d options=%d visible="%s"'):fmt(
            tostring(menu_name or ''),
            tostring(title or ''),
            category_logical,
            accessxi.escape_probe_log_text(category_label),
            selected,
            logical,
            scroll_top,
            scroll_raw,
            count,
            options:len(),
            accessxi.escape_probe_log_text(visible_label)));
        return nil;
    end

    local description = '';
    local row2 = 0;
    local desc = 0;
    description, row2, desc = accessxi.status_menu_native_description_for_entry(entry);
    if (description:contains('Select the category you would like to adjust', true)
        or description:contains('Displays the list of adjustable categories', true)) then
        description = '';
    end
    if (description == '') then
        description = tostring(option.help or '');
    end

    local label_text = tostring(option.label or ''):gsub('%s+', ' '):trim();
    local help_text = tostring(description or ''):gsub('%s+', ' '):trim();
    local rank_text, cost_text, merit_packet_entry = accessxi.merit_option_state_parts(tonumber(option.id) or 0);
    local state_parts = T{};
    if (rank_text ~= '') then
        state_parts:append(rank_text);
    end
    if (cost_text ~= '') then
        state_parts:append(cost_text);
    end
    local state_text = state_parts:concat('. ');
    accessxi.last_native_menu_name = tostring(menu_name or '');
    accessxi.last_native_menu_label = label_text;
    accessxi.last_native_menu_selected = logical;
    accessxi.last_native_menu_tick = tick();
    accessxi.current_merit_option_label = label_text;
    accessxi.current_merit_option_help = help_text;
    accessxi.current_merit_option_category_label = tostring(category_label or '');
    accessxi.current_merit_option_id = tonumber(option.id) or 0;
    accessxi.current_merit_option_tick = tick();
    accessxi.current_speech_key = ('native-known-merit-option:%s:%d:%d:%d:%d:%08X:%s:%s:%s'):fmt(
        tostring(menu_name or ''),
        category_logical,
        tonumber(option.id) or 0,
        selected,
        logical,
        scroll_raw,
        label_text,
        help_text,
        state_text);
    log_state(('state nativemenu merit-option menu="%s" title="%s" category=%d categoryLabel="%s" categorySource="%s" visual=%d logical=%d scrollTop=%d scrollRaw=0x%08X count=%d options=%d meritId=%d rank=%d nextCost=%d packetAge=%d label="%s" visible="%s" desc="%s" row2=0x%08X descPtr=0x%08X'):fmt(
        tostring(menu_name or ''),
        tostring(title or ''),
        category_logical,
        accessxi.escape_probe_log_text(category_label),
        category_source,
        selected,
        logical,
        scroll_top,
        scroll_raw,
        count,
        options:len(),
        tonumber(option.id) or 0,
        merit_packet_entry ~= nil and (tonumber(merit_packet_entry.value) or 0) or -1,
        merit_packet_entry ~= nil and (tonumber(merit_packet_entry.next_cost) or 0) or -1,
        merit_packet_entry ~= nil and math.max(0, tick() - (tonumber(merit_packet_entry.tick) or tick())) or -1,
        accessxi.escape_probe_log_text(label_text),
        accessxi.escape_probe_log_text(visible_label),
        accessxi.escape_probe_log_text(help_text),
        tonumber(row2) or 0,
        tonumber(desc) or 0));
    accessxi.log_merit_option_native_probe(menu_name, title, obj, child, entry, selected, count, logical, scroll_raw, option, row2, desc);
    accessxi.log_merit_state_probe(menu_name, obj, child, entry, selected, logical, option, row2, desc, category_logical);

    local group = tonumber(option.group) or 0;
    local group_text = '';
    if (group == 1) then
        group_text = 'Group 1';
    elseif (group == 2) then
        group_text = 'Group 2';
    end
    local context = category_label ~= '' and (category_label .. ' merits') or tostring(title or 'Merit options');
    if (group_text ~= '') then
        context = context .. ', ' .. group_text;
    end
    local speech_parts = T{};
    if (label_text ~= '') then
        speech_parts:append(label_text);
    end
    if (state_text ~= '') then
        speech_parts:append(state_text);
    end
    if (context ~= '') then
        speech_parts:append(context);
    end
    if (help_text ~= '') then
        speech_parts:append(help_text);
    end
    return accessxi.sentence_fragment(speech_parts:concat('. '));
end

function accessxi.job_point_menu_speech(menu_name, title, selected, count, child, entry, obj)
    menu_name = tostring(menu_name or '');
    title = tostring(title or 'Job Points');
    selected = tonumber(selected) or 0;
    count = tonumber(count) or 0;
    child = tonumber(child) or 0;
    entry = tonumber(entry) or 0;

    local label_ptr = accessxi.is_probe_pointer(entry) and (read_u32(entry + 0x44) or 0) or 0;
    local help_ptr = accessxi.is_probe_pointer(entry) and (read_u32(entry + 0x40) or 0) or 0;
    local direct_label = accessxi.plain_native_menu_label(read_probe_string(label_ptr));
    local direct_help = accessxi.plain_native_menu_help(read_probe_string(help_ptr, 260));
    local description, row2, desc = accessxi.status_menu_native_description_for_entry(entry);
    if (direct_help == '') then
        direct_help = description;
    end
    local is_job_point_option_menu = menu_name:eq('menu    jbpcat', true);
    local target = AshitaCore:GetMemoryManager():GetTarget();
    local ank_num = tonumber(target ~= nil and safe_call(function () return target:GetWindowAnkNum(); end, -1) or -1) or -1;
    local ank_x = tonumber(target ~= nil and safe_call(function () return target:GetWindowAnkX(); end, -1) or -1) or -1;
    local ank_y = tonumber(target ~= nil and safe_call(function () return target:GetWindowAnkY(); end, -1) or -1) or -1;
    local jbpcat_scroll_raw = 0;
    local jbpcat_scroll_top = 0;
    local jbpcat_native_surface = 0;
    local jbpcat_has_native_surface = false;
    if (is_job_point_option_menu and accessxi.is_probe_pointer(child)) then
        jbpcat_scroll_raw = read_u32(child + 0x18) or 0;
        jbpcat_scroll_top = bit.rshift(jbpcat_scroll_raw, 16);
        if (jbpcat_scroll_top < 0 or jbpcat_scroll_top > 512) then
            jbpcat_scroll_top = 0;
        end
        jbpcat_native_surface = read_u32(child + 0x58) or 0;
        jbpcat_has_native_surface = true;
    end
    local jbpcat_surface = tostring(accessxi.current_job_point_jbpcat_surface or '');
    local jbpcat_surface_child = tonumber(accessxi.current_job_point_jbpcat_child) or 0;
    local jbpcat_surface_obj = tonumber(accessxi.current_job_point_jbpcat_obj) or 0;
    local jbpcat_surface_tick = tonumber(accessxi.current_job_point_jbpcat_tick) or 0;
    local remembered_gift_surface = is_job_point_option_menu
        and jbpcat_surface:eq('gifts', true)
        and jbpcat_surface_child == child
        and jbpcat_surface_obj == obj
        and (tick() - jbpcat_surface_tick) < 120000;
    local is_job_point_gift_screen = is_job_point_option_menu
        and ((jbpcat_has_native_surface and jbpcat_native_surface == 1)
            or ((not jbpcat_has_native_surface) and ((ank_num >= 4 and ank_x < 0) or jbpcat_scroll_top > 0 or remembered_gift_surface)));
    if (is_job_point_gift_screen) then
        if (description ~= '') then
            local status_label, row0, row_code = accessxi.status_menu_native_label_for_description(description, desc);
            if (status_label ~= '') then
                local spoken_description = ('%s. %s'):fmt(status_label, description);
                if (status_label:eq('Currencies 2', true)) then
                    accessxi.current_currency_menu_page = 2;
                    accessxi.current_currency_menu_page_tick = tick();
                    accessxi.currency_native_remember_help_bank(row2);
                elseif (status_label:eq('Currencies', true)) then
                    accessxi.current_currency_menu_page = 1;
                    accessxi.current_currency_menu_page_tick = tick();
                    accessxi.currency_native_remember_help_bank(row2);
                elseif (status_label:eq('Unity', true)) then
                    accessxi.unity_menu_context_until = tick() + 120000;
                elseif (status_label:eq('Merit Points', true)) then
                    accessxi.merit_menu_context_until = tick() + 120000;
                elseif (status_label:eq('Job Points', true)) then
                    accessxi.job_point_menu_context_until = tick() + 120000;
                end
                if (description:contains('View your profile', true)) then
                    accessxi.status_profile_pending_until = tick() + 2500;
                end
                accessxi.last_native_menu_name = menu_name;
                accessxi.last_native_menu_label = spoken_description;
                accessxi.last_native_menu_selected = selected;
                accessxi.last_native_menu_tick = tick();
                accessxi.current_speech_key = ('native-known-jobpoint-status-side:%s:%d:0x%08X:0x%08X:0x%08X:%s:%s'):fmt(
                    menu_name,
                    selected,
                    entry,
                    tonumber(row0) or 0,
                    row2,
                    status_label,
                    description);
                log_state(('state nativemenu jobpoint-status-side menu="%s" title="%s" select=%d count=%d entry=0x%08X desc=0x%08X row0=0x%08X rowCode=0x%08X row2=0x%08X label="%s" text="%s"'):fmt(
                    menu_name,
                    title,
                    selected,
                    count,
                    entry,
                    tonumber(desc) or 0,
                    tonumber(row0) or 0,
                    tonumber(row_code) or 0,
                    tonumber(row2) or 0,
                    accessxi.escape_probe_log_text(status_label),
                    accessxi.escape_probe_log_text(description)));
                return ('Status menu. %s'):fmt(accessxi.sentence_fragment(spoken_description));
            end
        end

        local preferred_job = tonumber(accessxi.current_job_point_job_id) or 0;
        local job_source = 'context';
        if (preferred_job <= 0) then
            preferred_job = accessxi.job_point_unique_active_job_id();
            job_source = preferred_job > 0 and 'unique-active-packet' or 'none';
        end
        local gift, logical, scroll_top, scroll_raw = accessxi.job_point_gift_from_selection(selected, child, preferred_job);
        local packet_id_for_probe, option_scroll_top_for_probe, option_scroll_raw_for_probe = accessxi.job_point_option_from_selection(selected, child, preferred_job);
        local option_label_for_probe = packet_id_for_probe > 0 and accessxi.job_point_resource_label(packet_id_for_probe) or '';
        local option_help_for_probe = packet_id_for_probe > 0 and accessxi.job_point_resource_help(packet_id_for_probe) or '';
        accessxi.log_job_point_category_probe(
            menu_name,
            title,
            selected,
            count,
            child,
            entry,
            obj,
            preferred_job,
            direct_label,
            direct_help,
            description,
            gift ~= nil and tostring(gift.label or '') or '',
            option_label_for_probe,
            option_help_for_probe,
            scroll_raw ~= 0 and scroll_raw or option_scroll_raw_for_probe,
            scroll_top ~= 0 and scroll_top or option_scroll_top_for_probe);
        if (gift == nil) then
            local missing_key = ('gift:%s:%d:%d:0x%08X:0x%08X:%d:%s:%s'):fmt(
                menu_name,
                selected,
                count,
                entry,
                child,
                preferred_job,
                direct_label,
                direct_help);
            if (missing_key ~= tostring(accessxi.last_job_point_missing_key or '')) then
                accessxi.last_job_point_missing_key = missing_key;
                log_state(('state nativemenu jobpoint-gift missing menu="%s" title="%s" select=%d count=%d entry=0x%08X child=0x%08X preferredJob=%d jobSource="%s" direct="%s" help="%s"'):fmt(
                    menu_name,
                    title,
                    selected,
                    count,
                    entry,
                    child,
                    preferred_job,
                    job_source,
                    accessxi.escape_probe_log_text(direct_label),
                    accessxi.escape_probe_log_text(direct_help)));
            end
            return nil;
        end

        local job_label = accessxi.job_name(preferred_job);
        local label = tostring(gift.label or '');
        local help = tostring(gift.help or '');
        local parts = T{};
        if (job_label ~= '') then
            parts:append(job_label);
        end
        if (label ~= '') then
            parts:append(label);
        end
        if (gift.header == true) then
            local state_text = accessxi.job_point_job_state_text(preferred_job);
            if (state_text ~= '') then
                parts:append(state_text);
            end
        elseif (tonumber(gift.jp_needed) ~= nil and (tonumber(gift.jp_needed) or 0) > 0) then
            parts:append(('Requires %d total job points'):fmt(tonumber(gift.jp_needed) or 0));
        end
        if (help ~= '') then
            parts:append(help);
        end
        if (parts:len() <= 0) then
            return nil;
        end

        accessxi.current_job_point_category_id = tonumber(gift.dat_index) or 0;
        accessxi.current_job_point_category_label = label;
        accessxi.current_job_point_category_help = help;
        accessxi.current_job_point_job_id = preferred_job;
        accessxi.current_job_point_job_label = job_label;
        accessxi.current_job_point_tick = tick();
        accessxi.current_job_point_jbpcat_surface = 'gifts';
        accessxi.current_job_point_jbpcat_child = child;
        accessxi.current_job_point_jbpcat_obj = obj;
        accessxi.current_job_point_jbpcat_tick = tick();
        accessxi.last_native_menu_name = menu_name;
        accessxi.last_native_menu_label = label;
        accessxi.last_native_menu_selected = selected;
        accessxi.last_native_menu_tick = tick();

        local speech_key = ('native-known-jobpoint-gift:%s:%d:%d:%d:%d:%08X:%s:%s'):fmt(
            menu_name,
            preferred_job,
            logical,
            selected,
            count,
            scroll_raw,
            label,
            help);
        accessxi.current_speech_key = speech_key;
        if (speech_key == tostring(accessxi.last_job_point_row_speech_key or '')) then
            return nil;
        end
        accessxi.last_job_point_row_speech_key = speech_key;
        log_state(('state nativemenu jobpoint-gift menu="%s" title="%s" select=%d logical=%d count=%d entry=0x%08X child=0x%08X job=%d jobSource="%s" jobLabel="%s" datIndex=%d jpNeeded=%d scrollTop=%d scrollRaw=0x%08X label="%s" help="%s" direct="%s"'):fmt(
            menu_name,
            title,
            selected,
            logical,
            count,
            entry,
            child,
            preferred_job,
            job_source,
            accessxi.escape_probe_log_text(job_label),
            tonumber(gift.dat_index) or -1,
            tonumber(gift.jp_needed) or -1,
            scroll_top,
            scroll_raw,
            accessxi.escape_probe_log_text(label),
            accessxi.escape_probe_log_text(help),
            accessxi.escape_probe_log_text(direct_label)));

        return ('%s. %s'):fmt(title, accessxi.sentence_fragment(parts:concat('. ')));
    elseif (is_job_point_option_menu) then
        local preferred_job_for_probe = tonumber(accessxi.current_job_point_job_id) or 0;
        if (preferred_job_for_probe <= 0) then
            preferred_job_for_probe = accessxi.job_point_unique_active_job_id();
        end
        local gift_for_probe = nil;
        local gift_scroll_top_for_probe = 0;
        local gift_scroll_raw_for_probe = 0;
        if (preferred_job_for_probe > 0) then
            gift_for_probe, _, gift_scroll_top_for_probe, gift_scroll_raw_for_probe = accessxi.job_point_gift_from_selection(selected, child, preferred_job_for_probe);
        end
        local packet_id_for_probe, option_scroll_top_for_probe, option_scroll_raw_for_probe = accessxi.job_point_option_from_selection(selected, child, preferred_job_for_probe);
        local option_label_for_probe = packet_id_for_probe > 0 and accessxi.job_point_resource_label(packet_id_for_probe) or '';
        local option_help_for_probe = packet_id_for_probe > 0 and accessxi.job_point_resource_help(packet_id_for_probe) or '';
        accessxi.log_job_point_category_probe(
            menu_name,
            title,
            selected,
            count,
            child,
            entry,
            obj,
            preferred_job_for_probe,
            direct_label,
            direct_help,
            description,
            gift_for_probe ~= nil and tostring(gift_for_probe.label or '') or '',
            option_label_for_probe,
            option_help_for_probe,
            jbpcat_scroll_raw ~= 0 and jbpcat_scroll_raw or (gift_scroll_raw_for_probe ~= 0 and gift_scroll_raw_for_probe or option_scroll_raw_for_probe),
            jbpcat_scroll_top ~= 0 and jbpcat_scroll_top or (gift_scroll_top_for_probe ~= 0 and gift_scroll_top_for_probe or option_scroll_top_for_probe));
        log_state(('state nativemenu jobpoint-jbpcat-mode menu="%s" title="%s" select=%d count=%d entry=0x%08X child=0x%08X ankNum=%d ank=(%d,%d) scrollTop=%d scrollRaw=0x%08X surface=0x%08X mode="categories"'):fmt(
            menu_name,
            title,
            selected,
            count,
            entry,
            child,
            ank_num,
            ank_x,
            ank_y,
            jbpcat_scroll_top,
            jbpcat_scroll_raw,
            jbpcat_native_surface));
        accessxi.current_job_point_jbpcat_surface = 'categories';
        accessxi.current_job_point_jbpcat_child = child;
        accessxi.current_job_point_jbpcat_obj = obj;
        accessxi.current_job_point_jbpcat_tick = tick();
    end

    local option_mode = is_job_point_option_menu;
    local selected_job_id, selected_logical, selected_scroll_top, selected_scroll_raw = 0, 0, 0, 0;
    if (not option_mode) then
        selected_job_id, selected_logical, selected_scroll_top, selected_scroll_raw = accessxi.job_point_job_from_native_selection(selected, child);
    end
    local job_id = selected_job_id;
    local source = 'job-resource-order';
    if (job_id <= 0) then
        source = 'native-label';
        job_id = accessxi.job_point_job_id_from_label(direct_label);
    end
    if (job_id <= 0) then
        source = 'native-help';
        job_id = accessxi.job_point_job_id_from_help(direct_help);
    end
    if (job_id <= 0) then
        source = 'native-description';
        job_id = accessxi.job_point_job_id_from_help(description);
    end
    if (job_id > 0) then
        local job_label = accessxi.job_name(job_id);
        local state_text = accessxi.job_point_job_state_text(job_id);
        local help_text = direct_help;
        if (help_text == '' or help_text:contains('Select the job for which you wish to expend job points', true)) then
            help_text = 'Select the job for which you wish to expend job points.';
        end

        accessxi.current_job_point_job_id = job_id;
        accessxi.current_job_point_job_label = job_label;
        accessxi.current_job_point_tick = tick();
        accessxi.current_job_point_jbpcat_surface = '';
        accessxi.current_job_point_jbpcat_child = 0;
        accessxi.current_job_point_jbpcat_obj = 0;
        accessxi.current_job_point_jbpcat_tick = 0;
        accessxi.last_native_menu_name = menu_name;
        accessxi.last_native_menu_label = job_label;
        accessxi.last_native_menu_selected = selected;
        accessxi.last_native_menu_tick = tick();
        local speech_key = ('native-known-jobpoint-job:%s:%d:%d:%d:%d:%s:%s'):fmt(
            menu_name,
            selected,
            selected_logical,
            count,
            job_id,
            job_label,
            state_text);
        accessxi.current_speech_key = speech_key;
        if (speech_key == tostring(accessxi.last_job_point_row_speech_key or '')) then
            return nil;
        end
        accessxi.last_job_point_row_speech_key = speech_key;
        log_state(('state nativemenu jobpoint-job menu="%s" title="%s" select=%d logical=%d count=%d scrollTop=%d scrollRaw=0x%08X entry=0x%08X labelPtr=0x%08X helpPtr=0x%08X source="%s" job=%d label="%s" state="%s" help="%s" packetAge=%d miscAge=%d desc=0x%08X row2=0x%08X'):fmt(
            menu_name,
            title,
            selected,
            selected_logical,
            count,
            selected_scroll_top,
            selected_scroll_raw,
            entry,
            label_ptr,
            help_ptr,
            source,
            job_id,
            accessxi.escape_probe_log_text(job_label),
            accessxi.escape_probe_log_text(state_text),
            accessxi.escape_probe_log_text(help_text),
            math.max(0, tick() - (tonumber(accessxi.job_point_packet_tick) or tick())),
            math.max(0, tick() - (tonumber(accessxi.job_point_misc_tick) or tick())),
            tonumber(desc) or 0,
            tonumber(row2) or 0));

        local parts = T{ job_label };
        if (state_text ~= '') then
            parts:append(state_text);
        end
        if (help_text ~= '') then
            parts:append(help_text);
        end
        return ('%s. %s'):fmt(title, accessxi.sentence_fragment(parts:concat('. ')));
    end

    local preferred_job = tonumber(accessxi.current_job_point_job_id) or 0;
    if (not option_mode) then
        preferred_job = 0;
    end
    local packet_id = accessxi.job_point_id_from_label(direct_label, preferred_job);
    local source = 'native-label';
    local scroll_top, scroll_raw = 0, 0;
    if (packet_id <= 0 and preferred_job > 0 and option_mode) then
        packet_id, scroll_top, scroll_raw = accessxi.job_point_option_from_selection(selected, child, preferred_job);
        source = 'dat-index';
    end
    if (packet_id <= 0) then
        local missing_key = ('%s:%d:%d:0x%08X:0x%08X:%s:%s:%d'):fmt(
            menu_name,
            selected,
            count,
            entry,
            child,
            direct_label,
            direct_help,
            preferred_job);
        if (missing_key ~= tostring(accessxi.last_job_point_missing_key or '')) then
            accessxi.last_job_point_missing_key = missing_key;
            log_state(('state nativemenu jobpoint missing menu="%s" title="%s" select=%d count=%d entry=0x%08X child=0x%08X direct="%s" help="%s" preferredJob=%d'):fmt(
                menu_name,
                title,
                selected,
                count,
                entry,
                child,
                accessxi.escape_probe_log_text(direct_label),
                accessxi.escape_probe_log_text(direct_help),
                preferred_job));
        end
        return nil;
    end

    local option_label = accessxi.job_point_resource_label(packet_id);
    local option_help = accessxi.job_point_resource_help(packet_id);
    if (direct_help ~= '' and not direct_help:contains('Select the job for which you wish to expend job points', true)) then
        option_help = direct_help;
    end
    local option_job = math.floor(packet_id / 32);
    if (preferred_job <= 0) then
        preferred_job = option_job;
    end
    local job_label = accessxi.job_name(preferred_job);
    local rank_text, cost_text, packet_entry = accessxi.job_point_state_parts(packet_id);

    accessxi.current_job_point_job_id = preferred_job;
    accessxi.current_job_point_job_label = job_label;
    accessxi.current_job_point_category_id = packet_id;
    accessxi.current_job_point_category_label = option_label;
    accessxi.current_job_point_category_help = option_help;
    accessxi.current_job_point_tick = tick();
    accessxi.last_native_menu_name = menu_name;
    accessxi.last_native_menu_label = option_label;
    accessxi.last_native_menu_selected = selected;
    accessxi.last_native_menu_tick = tick();

    local state_parts = T{};
    if (rank_text ~= '') then
        state_parts:append(rank_text);
    end
    if (cost_text ~= '') then
        state_parts:append(cost_text);
    end
    local state_text = state_parts:concat('. ');
    local speech_scroll_raw = is_job_point_option_menu and 0 or scroll_raw;
    local speech_key = ('native-known-jobpoint-option:%s:%d:%d:%d:%d:0x%08X:%08X:%s:%s:%s'):fmt(
        menu_name,
        preferred_job,
        packet_id,
        selected,
        count,
        entry,
        speech_scroll_raw,
        source,
        option_label,
        state_text);
    accessxi.current_speech_key = speech_key;
    if (speech_key == tostring(accessxi.last_job_point_row_speech_key or '')) then
        return nil;
    end
    accessxi.last_job_point_row_speech_key = speech_key;
    log_state(('state nativemenu jobpoint-option menu="%s" title="%s" select=%d count=%d entry=0x%08X child=0x%08X source="%s" job=%d jobLabel="%s" jpId=%d resourceId=%d rank=%d nextCost=%d packetAge=%d scrollTop=%d scrollRaw=0x%08X direct="%s" label="%s" help="%s"'):fmt(
        menu_name,
        title,
        selected,
        count,
        entry,
        child,
        source,
        preferred_job,
        accessxi.escape_probe_log_text(job_label),
        packet_id,
        accessxi.job_point_resource_id(packet_id),
        packet_entry ~= nil and (tonumber(packet_entry.value) or 0) or -1,
        packet_entry ~= nil and (tonumber(packet_entry.next_cost) or 0) or -1,
        packet_entry ~= nil and math.max(0, tick() - (tonumber(packet_entry.tick) or tick())) or -1,
        scroll_top,
        scroll_raw,
        accessxi.escape_probe_log_text(direct_label),
        accessxi.escape_probe_log_text(option_label),
        accessxi.escape_probe_log_text(option_help)));

    local parts = T{};
    if (option_label ~= '') then
        parts:append(option_label);
    end
    if (state_text ~= '') then
        parts:append(state_text);
    end
    if (job_label ~= '') then
        parts:append(job_label);
    end
    if (option_help ~= '') then
        parts:append(option_help);
    end
    if (parts:len() <= 0) then
        return nil;
    end
    return ('%s. %s'):fmt(title, accessxi.sentence_fragment(parts:concat('. ')));
end

function accessxi.merit_category_collect_visible_labels_from_ptr(labels, seen, ptr)
    ptr = tonumber(ptr) or 0;
    if (labels == nil or seen == nil or not accessxi.is_probe_pointer(ptr) or accessxi.collect_probe_ffxi_utf16_entries == nil) then
        return;
    end

    local entries = accessxi.collect_probe_ffxi_utf16_entries(ptr, 0x1400, 2, 128);
    local words = T{};
    local last_offset = -9999;

    local function flush()
        if (#words == 0) then
            return;
        end

        local label = accessxi.merit_category_native_label_text(words:concat(' '));
        local key = label:lower();
        if (label ~= '' and seen[key] ~= true) then
            seen[key] = true;
            labels:append(label);
        end
        words = T{};
    end

    for _, entry in ipairs(entries) do
        local offset = tonumber(entry.offset) or 0;
        local text = accessxi.merit_category_native_label_text(entry.text or '');
        if (text ~= '') then
            if (#words > 0 and (offset - last_offset) > 0x28) then
                flush();
            end
            words:append(text);
            last_offset = offset;
        end
    end
    flush();
end

function accessxi.merit_category_native_visible_labels(obj)
    obj = tonumber(obj) or 0;
    if (obj == 0) then
        return T{}, 0;
    end

    local child = read_u32(obj + 0x0C) or 0;
    if (not accessxi.is_probe_pointer(child)) then
        return T{}, child;
    end

    local labels = T{};
    local seen = {};
    local seen_ptr = {};
    local function scan_ptr(ptr)
        ptr = tonumber(ptr) or 0;
        if (accessxi.is_probe_pointer(ptr) and seen_ptr[ptr] ~= true) then
            seen_ptr[ptr] = true;
            accessxi.merit_category_collect_visible_labels_from_ptr(labels, seen, ptr);
        end
    end

    for _, off in ipairs(T{ 0x14, 0x18 }) do
        local holder = read_u32(child + off) or 0;
        if (accessxi.is_probe_pointer(holder)) then
            scan_ptr(read_u32(holder + 0x10) or 0);
            for holder_off = 0x00, 0x30, 4 do
                scan_ptr(read_u32(holder + holder_off) or 0);
            end
        end
    end

    return labels, child;
end

function accessxi.log_merit_category_visible_probe(menu_name, title, obj, selected, count, labels, child, mode)
    menu_name = tostring(menu_name or '');
    title = tostring(title or '');
    selected = tonumber(selected) or 0;
    count = tonumber(count) or 0;
    obj = tonumber(obj) or 0;
    child = tonumber(child) or 0;
    local parts = T{};
    if (labels ~= nil) then
        local max_labels = math.min(labels:len(), 24);
        for i = 1, max_labels do
            parts:append(('%d=%s'):fmt(i, tostring(labels[i] or '')));
        end
    end
    local key = ('%s:0x%08X:%d:%d:%s:%s'):fmt(menu_name, obj, selected, count, tostring(mode or ''), parts:concat('|'));
    if (key == (accessxi.last_merit_category_visible_probe_key or '')) then
        return;
    end
    accessxi.last_merit_category_visible_probe_key = key;
    log_state(('state nativemenu meritcat-visible menu="%s" title="%s" obj=0x%08X child=0x%08X select=%d count=%d labels=%d mode="%s" list="%s"'):fmt(
        menu_name,
        title,
        obj,
        child,
        selected,
        count,
        labels ~= nil and labels:len() or 0,
        tostring(mode or ''),
        accessxi.escape_probe_log_text_wide(parts:concat(' | '))));
end

function accessxi.merit_option_probe_text(ptr, length, limit)
    ptr = tonumber(ptr) or 0;
    if (not accessxi.is_probe_pointer(ptr)) then
        return '';
    end

    length = tonumber(length) or 0x400;
    limit = tonumber(limit) or 16;
    local parts = T{};
    local seen = {};
    local function add(kind, offset, text)
        text = accessxi.survival_guide_text(text or ''):gsub('%s+', ' '):trim();
        if (text == '' or #text > 80) then
            return;
        end
        local lower = text:lower();
        if (lower:find('menu    ', 1, true) ~= nil
            or lower:find('windowps', 1, true) ~= nil
            or lower:find('keytops', 1, true) ~= nil
            or lower:find('shell32', 1, true) ~= nil) then
            return;
        end
        local key = ('%s:%03X:%s'):fmt(kind, tonumber(offset) or 0, lower);
        if (seen[key] == true) then
            return;
        end
        seen[key] = true;
        parts:append(('%s+%03X=%s'):fmt(kind, tonumber(offset) or 0, accessxi.escape_probe_log_text(text)));
    end

    if (accessxi.collect_probe_ffxi_utf16_entries ~= nil) then
        for _, entry in ipairs(accessxi.collect_probe_ffxi_utf16_entries(ptr, length, 1, limit)) do
            add('ffxi', tonumber(entry.offset) or 0, entry.text or '');
            if (parts:len() >= limit) then
                return parts:concat(' | ');
            end
        end
    end
    if (accessxi.collect_probe_ascii_runs ~= nil) then
        for _, run in ipairs(accessxi.collect_probe_ascii_runs(ptr, length, 2, limit)) do
            local off_text, text = tostring(run or ''):match('^%+(%x+)="(.*)"$');
            add('ascii', tonumber(off_text or '0', 16) or 0, text or tostring(run or ''));
            if (parts:len() >= limit) then
                return parts:concat(' | ');
            end
        end
    end
    if (accessxi.collect_probe_utf16_runs ~= nil) then
        for _, run in ipairs(accessxi.collect_probe_utf16_runs(ptr, length, 2, limit)) do
            local off_text, text = tostring(run or ''):match('^%+(%x+)="(.*)"$');
            add('utf16', tonumber(off_text or '0', 16) or 0, text or tostring(run or ''));
            if (parts:len() >= limit) then
                return parts:concat(' | ');
            end
        end
    end

    return parts:concat(' | ');
end

function accessxi.merit_option_raw_text_probe(ptr, length, limit)
    ptr = tonumber(ptr) or 0;
    if (not accessxi.is_probe_pointer(ptr)) then
        return '';
    end

    length = tonumber(length) or 0x180;
    limit = tonumber(limit) or 18;
    local parts = T{};
    local seen = {};
    local function candidate_ok(text)
        text = tostring(text or ''):gsub('%s+', ' '):trim();
        if (text == '' or #text > 48) then
            return false;
        end
        if (text:match('^[%w%s%p]+$') == nil) then
            return false;
        end
        local lower = text:lower();
        if (lower:find('menu    ', 1, true) ~= nil
            or lower:find('windowps', 1, true) ~= nil
            or lower:find('keytops', 1, true) ~= nil
            or lower:find('shell32', 1, true) ~= nil
            or lower:find('__index', 1, true) ~= nil) then
            return false;
        end
        if (#text <= 2 and text:match('^%p+$') ~= nil) then
            return false;
        end
        return true;
    end
    local function add(kind, offset, text)
        text = tostring(text or ''):gsub('%z', ''):gsub('%s+', ' '):trim();
        if (not candidate_ok(text)) then
            return;
        end
        local key = ('%s:%03X:%s'):fmt(kind, tonumber(offset) or 0, text:lower());
        if (seen[key] == true) then
            return;
        end
        seen[key] = true;
        parts:append(('%s+%03X=%s'):fmt(kind, tonumber(offset) or 0, accessxi.escape_probe_log_text(text)));
    end

    local run = T{};
    local run_start = 0;
    for off = 0, length do
        local byte_value = off < length and read_u8(ptr + off) or nil;
        if (byte_value ~= nil and accessxi.probe_printable_ascii(byte_value)) then
            if (#run == 0) then
                run_start = off;
            end
            run:append(string.char(byte_value));
        else
            add('ascii', run_start, run:concat(''));
            if (parts:len() >= limit) then
                return parts:concat(' | ');
            end
            run = T{};
        end
    end

    for phase = 0, 1 do
        run = T{};
        run_start = phase;
        for off = phase, length - 2, 2 do
            local lo = read_u8(ptr + off);
            local hi = read_u8(ptr + off + 1);
            if (lo ~= nil and hi == 0 and accessxi.probe_printable_ascii(lo)) then
                if (#run == 0) then
                    run_start = off;
                end
                run:append(string.char(lo));
            else
                add('utf16', run_start, run:concat(''));
                if (parts:len() >= limit) then
                    return parts:concat(' | ');
                end
                run = T{};
            end
        end
        add('utf16', run_start, run:concat(''));
        if (parts:len() >= limit) then
            return parts:concat(' | ');
        end
    end

    return parts:concat(' | ');
end

function accessxi.merit_option_selected_render_probe(shape_rec)
    shape_rec = tonumber(shape_rec) or 0;
    if (not accessxi.is_probe_pointer(shape_rec)) then
        return '';
    end

    local parts = T{};
    local seen = {};
    local function scan(ptr, source, depth)
        ptr = tonumber(ptr) or 0;
        depth = tonumber(depth) or 0;
        if (not accessxi.is_probe_pointer(ptr) or seen[ptr] == true or parts:len() >= 18) then
            return;
        end
        seen[ptr] = true;
        parts:append(('%s=0x%08X d="%s" raw="%s"'):fmt(
            tostring(source or ''),
            ptr,
            accessxi.format_probe_dwords(ptr, 0x00, 12),
            accessxi.escape_probe_log_text_wide(accessxi.merit_option_raw_text_probe(ptr, 0x220, 12))));
        if (depth <= 0) then
            return;
        end
        for off = 0, 0x80, 4 do
            local child_ptr = read_u32(ptr + off) or 0;
            if (accessxi.is_probe_pointer(child_ptr)) then
                scan(child_ptr, ('%s+%02X'):fmt(source, off), depth - 1);
                if (parts:len() >= 18) then
                    return;
                end
            end
        end
    end

    for off = 0, 0x10, 4 do
        local ptr = read_u32(shape_rec + off) or 0;
        if (accessxi.is_probe_pointer(ptr)) then
            scan(ptr, ('shape+%02X'):fmt(off), 1);
        end
    end
    return parts:concat(' || ');
end

function accessxi.log_merit_option_render_nodes(menu_name, selected, option, shape_rec)
    if ((tonumber(accessxi.merit_option_probe_until) or 0) < tick()) then
        return;
    end

    shape_rec = tonumber(shape_rec) or 0;
    if (not accessxi.is_probe_pointer(shape_rec)) then
        return;
    end

    menu_name = tostring(menu_name or '');
    selected = tonumber(selected) or 0;
    local option_id = option ~= nil and (tonumber(option.id) or 0) or 0;
    local option_label = option ~= nil and tostring(option.label or '') or '';
    for _, off in ipairs(T{ 0x00, 0x04, 0x08, 0x0C, 0x10 }) do
        local ptr = read_u32(shape_rec + off) or 0;
        if (accessxi.is_probe_pointer(ptr)) then
            local child_parts = T{};
            for child_off = 0, 0x60, 4 do
                local child_ptr = read_u32(ptr + child_off) or 0;
                if (accessxi.is_probe_pointer(child_ptr)) then
                    child_parts:append(('+%02X=0x%08X d=%s raw="%s" bytes="%s"'):fmt(
                        child_off,
                        child_ptr,
                        accessxi.format_probe_dwords(child_ptr, 0x00, 12),
                        accessxi.escape_probe_log_text_wide(accessxi.merit_option_raw_text_probe(child_ptr, 0x300, 16)),
                        accessxi.escape_probe_log_text_wide(accessxi.format_probe_bytes(child_ptr, 0x00, 0x80))));
                end
            end
            log_state(('state nativemenu merit-render-node menu="%s" selected=%d meritId=%d label="%s" shapeRec=0x%08X off=0x%02X ptr=0x%08X d="%s" raw="%s" bytes="%s" children="%s"'):fmt(
                menu_name,
                selected,
                option_id,
                accessxi.escape_probe_log_text(option_label),
                shape_rec,
                off,
                ptr,
                accessxi.format_probe_dwords(ptr, 0x00, 24),
                accessxi.escape_probe_log_text_wide(accessxi.merit_option_raw_text_probe(ptr, 0x400, 24)),
                accessxi.escape_probe_log_text_wide(accessxi.format_probe_bytes(ptr, 0x00, 0x100)),
                accessxi.escape_probe_log_text_wide(child_parts:concat(' || '))));
        end
    end
end

function accessxi.log_merit_option_native_probe(menu_name, title, obj, child, entry, selected, count, logical, scroll_raw, option, row2, desc)
    if ((tonumber(accessxi.merit_option_probe_until) or 0) < tick()) then
        return;
    end

    menu_name = tostring(menu_name or '');
    obj = tonumber(obj) or 0;
    child = tonumber(child) or 0;
    entry = tonumber(entry) or 0;
    selected = tonumber(selected) or 0;
    count = tonumber(count) or 0;
    logical = tonumber(logical) or 0;
    scroll_raw = tonumber(scroll_raw) or 0;
    row2 = tonumber(row2) or 0;
    desc = tonumber(desc) or 0;
    local option_id = option ~= nil and (tonumber(option.id) or 0) or 0;
    local option_label = option ~= nil and tostring(option.label or '') or '';

    local shape = accessxi.is_probe_pointer(entry) and (read_u32(entry + 0x0C) or 0) or 0;
    local shape_base = shape;
    if (selected > 1 and accessxi.is_probe_pointer(shape)) then
        shape_base = shape - ((selected - 1) * 0x14);
    end
    local desc_base = desc;
    if (selected > 1 and accessxi.is_probe_pointer(desc)) then
        desc_base = desc - ((selected - 1) * 0x14);
    end

    local row_parts = T{};
    local selected_render = '';
    for delta = -2, 2 do
        local row_index = selected + delta;
        if (row_index >= 1) then
            local shape_rec = accessxi.is_probe_pointer(shape_base) and (shape_base + ((row_index - 1) * 0x14)) or 0;
            local desc_rec = accessxi.is_probe_pointer(desc_base) and (desc_base + ((row_index - 1) * 0x14)) or 0;
            if (row_index == selected) then
                selected_render = accessxi.merit_option_selected_render_probe(shape_rec);
                accessxi.log_merit_option_render_nodes(menu_name, selected, option, shape_rec);
            end
            row_parts:append(('r%d shape=0x%08X[%s] desc=0x%08X[%s] descText="%s"'):fmt(
                row_index,
                shape_rec,
                accessxi.format_probe_dwords(shape_rec, 0x00, 5),
                desc_rec,
                accessxi.format_probe_dwords(desc_rec, 0x00, 5),
                accessxi.escape_probe_log_text_wide(accessxi.merit_option_probe_text(desc_rec, 0x120, 8))));
        end
    end

    local text_parts = T{};
    text_parts:append(('obj="%s"'):fmt(accessxi.escape_probe_log_text_wide(accessxi.merit_option_probe_text(obj, 0x300, 12))));
    text_parts:append(('child="%s"'):fmt(accessxi.escape_probe_log_text_wide(accessxi.merit_option_probe_text(child, 0x500, 16))));
    text_parts:append(('entry="%s"'):fmt(accessxi.escape_probe_log_text_wide(accessxi.merit_option_probe_text(entry, 0x300, 12))));
    text_parts:append(('shape="%s"'):fmt(accessxi.escape_probe_log_text_wide(accessxi.merit_option_probe_text(shape, 0x300, 12))));
    text_parts:append(('row2="%s"'):fmt(accessxi.escape_probe_log_text_wide(accessxi.merit_option_probe_text(row2, 0x300, 12))));
    text_parts:append(('desc="%s"'):fmt(accessxi.escape_probe_log_text_wide(accessxi.merit_option_probe_text(desc, 0x300, 12))));

    local key = ('%s:%08X:%08X:%08X:%d:%d:%d:%08X:%s:%s:%s'):fmt(
        menu_name,
        obj,
        child,
        entry,
        selected,
        logical,
        option_id,
        scroll_raw,
        row_parts:concat('|'),
        text_parts:concat('|'),
        selected_render);
    if (key == tostring(accessxi.last_merit_option_native_probe_key or '')) then
        return;
    end
    accessxi.last_merit_option_native_probe_key = key;
    log_state(('state nativemenu merit-option-native-probe menu="%s" title="%s" obj=0x%08X child=0x%08X entry=0x%08X shape=0x%08X shapeBase=0x%08X row2=0x%08X desc=0x%08X descBase=0x%08X selected=%d logical=%d count=%d scrollRaw=0x%08X meritId=%d label="%s" objD="%s" childD="%s" entryD="%s" shapeD="%s" row2D="%s" descD="%s" rows="%s" render="%s" texts="%s"'):fmt(
        menu_name,
        tostring(title or ''),
        obj,
        child,
        entry,
        shape,
        shape_base,
        row2,
        desc,
        desc_base,
        selected,
        logical,
        count,
        scroll_raw,
        option_id,
        accessxi.escape_probe_log_text(option_label),
        accessxi.format_probe_dwords(obj, 0x00, 24),
        accessxi.format_probe_dwords(child, 0x00, 24),
        accessxi.format_probe_dwords(entry, 0x00, 24),
        accessxi.format_probe_dwords(shape, 0x00, 24),
        accessxi.format_probe_dwords(row2, 0x00, 16),
        accessxi.format_probe_dwords(desc, 0x00, 16),
        accessxi.escape_probe_log_text_wide(row_parts:concat(' || ')),
        accessxi.escape_probe_log_text_wide(selected_render),
        accessxi.escape_probe_log_text_wide(text_parts:concat(' ; '))));
end

function accessxi.merit_state_probe_add_ptr(ptrs, seen, ptr, source)
    ptr = tonumber(ptr) or 0;
    if (not accessxi.is_probe_pointer(ptr) or seen[ptr] == true) then
        return;
    end
    seen[ptr] = true;
    ptrs:append({ ptr = ptr, source = tostring(source or '') });
end

function accessxi.merit_state_probe_collect_ptrs(obj, child, entry, shape, row2, desc)
    local ptrs = T{};
    local seen = {};
    local roots = T{
        { ptr = tonumber(obj) or 0, source = 'obj' },
        { ptr = tonumber(child) or 0, source = 'child' },
        { ptr = tonumber(entry) or 0, source = 'entry' },
        { ptr = tonumber(shape) or 0, source = 'shape' },
        { ptr = tonumber(row2) or 0, source = 'row2' },
        { ptr = tonumber(desc) or 0, source = 'desc' },
    };

    for _, root in ipairs(roots) do
        accessxi.merit_state_probe_add_ptr(ptrs, seen, root.ptr, root.source);
    end

    for _, root in ipairs(roots) do
        local base = tonumber(root.ptr) or 0;
        if (accessxi.is_probe_pointer(base)) then
            for off = 0, 0xA0, 4 do
                local ptr = read_u32(base + off) or 0;
                accessxi.merit_state_probe_add_ptr(ptrs, seen, ptr, ('%s+%02X'):fmt(root.source, off));
                if (ptrs:len() >= 72) then
                    return ptrs;
                end
            end
        end
    end

    return ptrs;
end

function accessxi.merit_state_probe_needles(option, category_logical)
    option = option or {};
    local id = tonumber(option.id) or 0;
    local needles = T{};
    local seen = {};
    local function add(value, label)
        value = tonumber(value) or 0;
        if (value <= 0 or seen[value] == true) then
            return;
        end
        seen[value] = true;
        needles:append({ value = value, label = tostring(label or value) });
    end

    add(id, 'id');
    if (id > 0) then
        add(math.floor(id / 2), 'id_half');
        add(id - 0x40, 'id_minus_40');
        add(id - 0x80, 'id_minus_80');
    end

    local options = accessxi.merit_options_for_category(tonumber(category_logical) or 0);
    if (options ~= nil) then
        for i = 1, math.min(options:len(), 16) do
            local option_id = tonumber(options[i].id) or 0;
            if (option_id > 0) then
                add(option_id, ('cat_id_%d'):fmt(i));
                add(math.floor(option_id / 2), ('cat_half_%d'):fmt(i));
            end
        end
    end

    return needles;
end

function accessxi.merit_state_probe_scan_ptr(ptr, needles, limit)
    ptr = tonumber(ptr) or 0;
    if (not accessxi.is_probe_pointer(ptr)) then
        return T{};
    end

    local hits = T{};
    limit = tonumber(limit) or 0x700;
    for off = 0, limit - 2 do
        local b = read_u8(ptr + off) or -1;
        if (b >= 0) then
            for _, needle in ipairs(needles) do
                local value = tonumber(needle.value) or -1;
                if (value >= 0 and value <= 0xFF and b == value) then
                    hits:append({
                        kind = 'u8',
                        off = off,
                        value = value,
                        label = tostring(needle.label or ''),
                    });
                end
            end
        end

        local w = read_u16(ptr + off) or -1;
        if (w >= 0) then
            for _, needle in ipairs(needles) do
                local value = tonumber(needle.value) or -1;
                if (value >= 0 and value <= 0xFFFF and w == value) then
                    hits:append({
                        kind = 'u16',
                        off = off,
                        value = value,
                        label = tostring(needle.label or ''),
                    });
                end
            end
        end

        if (hits:len() >= 18) then
            return hits;
        end
    end

    return hits;
end

function accessxi.log_merit_state_probe(menu_name, obj, child, entry, selected, logical, option, row2, desc, category_logical)
    if ((tonumber(accessxi.merit_state_probe_until) or 0) < tick()) then
        return;
    end

    option = option or {};
    local option_id = tonumber(option.id) or 0;
    local option_label = tostring(option.label or '');
    local shape = accessxi.is_probe_pointer(entry) and (read_u32(entry + 0x0C) or 0) or 0;
    local needles = accessxi.merit_state_probe_needles(option, category_logical);
    local ptrs = accessxi.merit_state_probe_collect_ptrs(obj, child, entry, shape, row2, desc);
    local parts = T{};

    for _, rec in ipairs(ptrs) do
        local ptr = tonumber(rec.ptr) or 0;
        local hits = accessxi.merit_state_probe_scan_ptr(ptr, needles, 0x700);
        if (hits:len() > 0) then
            local hit_parts = T{};
            for i = 1, math.min(hits:len(), 8) do
                local hit = hits[i];
                local start = math.max(0, (tonumber(hit.off) or 0) - 0x10);
                hit_parts:append(('%s+%03X=%d/%s bytes[%03X]=%s d[%03X]=%s'):fmt(
                    tostring(hit.kind or ''),
                    tonumber(hit.off) or 0,
                    tonumber(hit.value) or 0,
                    accessxi.escape_probe_log_text(hit.label or ''),
                    start,
                    accessxi.escape_probe_log_text(accessxi.format_probe_bytes(ptr, start, 0x40)),
                    start,
                    accessxi.format_probe_dwords(ptr, start, 8)));
            end
            parts:append(('%s=0x%08X %s'):fmt(
                tostring(rec.source or ''),
                ptr,
                accessxi.escape_probe_log_text_wide(hit_parts:concat(' || '))));
        end
        if (parts:len() >= 10) then
            break;
        end
    end

    local key = ('%s:%d:%d:%d:%08X:%s'):fmt(
        tostring(menu_name or ''),
        tonumber(selected) or 0,
        tonumber(logical) or 0,
        option_id,
        tonumber(shape) or 0,
        parts:concat(' | '));
    if (key == tostring(accessxi.last_merit_state_probe_key or '')) then
        return;
    end
    accessxi.last_merit_state_probe_key = key;
    local needle_parts = T{};
    for _, needle in ipairs(needles) do
        needle_parts:append(('%s=%d'):fmt(tostring(needle.label or ''), tonumber(needle.value) or 0));
    end
    log_state(('state nativemenu merit-state-probe menu="%s" selected=%d logical=%d category=%d meritId=%d label="%s" obj=0x%08X child=0x%08X entry=0x%08X shape=0x%08X row2=0x%08X desc=0x%08X needles="%s" hits="%s"'):fmt(
        tostring(menu_name or ''),
        tonumber(selected) or 0,
        tonumber(logical) or 0,
        tonumber(category_logical) or 0,
        option_id,
        accessxi.escape_probe_log_text(option_label),
        tonumber(obj) or 0,
        tonumber(child) or 0,
        tonumber(entry) or 0,
        tonumber(shape) or 0,
        tonumber(row2) or 0,
        tonumber(desc) or 0,
        accessxi.escape_probe_log_text_wide(needle_parts:concat(',')),
        accessxi.escape_probe_log_text_wide(parts:concat(' | '))));
end

function accessxi.meritcat_shape_probe_ptr(source, ptr)
    ptr = tonumber(ptr) or 0;
    if (not accessxi.is_probe_pointer(ptr)) then
        return ('%s=0x%08X'):fmt(tostring(source or ''), ptr);
    end

    return ('%s=0x%08X d00="%s" d40="%s" text="%s"'):fmt(
        tostring(source or ''),
        ptr,
        accessxi.format_probe_dwords(ptr, 0x00, 12),
        accessxi.format_probe_dwords(ptr, 0x40, 12),
        accessxi.escape_probe_log_text_wide(accessxi.probe_strings_at(ptr)));
end

