function accessxi.poll_meritcat_native_action_probe()
    local menu_name = tostring(get_menu_name() or '');
    if (not menu_name:eq('menu    meritcat', true)) then
        accessxi.last_meritcat_action_probe_key = '';
        return false;
    end

    local obj = get_current_menu_object_ptr();
    obj = tonumber(obj) or 0;
    if (not accessxi.is_probe_pointer(obj)) then
        accessxi.last_meritcat_action_probe_key = '';
        return false;
    end

    local selected, page, raw, child, count = accessxi.survival_guide_query_child_state_for_obj(obj);
    selected = tonumber(selected) or 0;
    count = tonumber(count) or 0;
    child = tonumber(child) or 0;
    local entry = read_u32(obj + 0x08) or 0;
    local shape = accessxi.is_probe_pointer(entry) and (read_u32(entry + 0x0C) or 0) or 0;
    local desc = accessxi.is_probe_pointer(entry) and (read_u32(entry + 0x04) or 0) or 0;

    local action50 = read_u32(obj + 0x50) or 0;
    local action54 = read_u32(obj + 0x54) or 0;
    local action58 = read_u32(obj + 0x58) or 0;
    local action5c = read_u32(obj + 0x5C) or 0;
    local action60 = read_u32(obj + 0x60) or 0;
    local action64 = read_u32(obj + 0x64) or 0;
    local action68 = read_u32(obj + 0x68) or 0;

    local obj_d40 = accessxi.format_probe_dwords(obj, 0x40, 16);
    local obj_d80 = accessxi.format_probe_dwords(obj, 0x80, 16);
    local child_d00 = accessxi.is_probe_pointer(child) and accessxi.format_probe_dwords(child, 0x00, 16) or '';
    local child_d80 = accessxi.is_probe_pointer(child) and accessxi.format_probe_dwords(child, 0x80, 16) or '';
    local entry_d00 = accessxi.is_probe_pointer(entry) and accessxi.format_probe_dwords(entry, 0x00, 16) or '';
    local entry_d40 = accessxi.is_probe_pointer(entry) and accessxi.format_probe_dwords(entry, 0x40, 16) or '';
    local shape_d00 = accessxi.is_probe_pointer(shape) and accessxi.format_probe_dwords(shape, 0x00, 16) or '';
    local desc_text = accessxi.is_probe_pointer(desc) and accessxi.survival_guide_text(read_probe_string(desc + 0x46, 180)) or '';

    local key = ('%d:%d:%08X:%08X:%08X:%08X:%08X:%08X:%08X:%08X:%08X:%08X:%08X:%s:%s:%s:%s:%s:%s:%s'):fmt(
        selected,
        count,
        obj,
        child,
        entry,
        shape,
        action50,
        action54,
        action58,
        action5c,
        action60,
        action64,
        action68,
        obj_d40,
        obj_d80,
        child_d00,
        child_d80,
        entry_d00,
        entry_d40,
        shape_d00);
    if (key == tostring(accessxi.last_meritcat_action_probe_key or '')) then
        return false;
    end
    accessxi.last_meritcat_action_probe_key = key;

    log_state(('state nativemenu meritcat-action menu="%s" select=%d count=%d page=%d raw=0x%08X category=%d obj=0x%08X child=0x%08X entry=0x%08X shape=0x%08X desc=0x%08X a50=0x%08X a54=0x%08X a58=0x%08X a5c=0x%08X a60=0x%08X a64=0x%08X a68=0x%08X text="%s" objD40="%s" objD80="%s" childD00="%s" childD80="%s" entryD00="%s" entryD40="%s" shapeD00="%s"'):fmt(
        menu_name,
        selected,
        count,
        tonumber(page) or 0,
        tonumber(raw) or 0,
        tonumber(accessxi.current_merit_category_logical) or 0,
        obj,
        child,
        entry,
        shape,
        desc,
        action50,
        action54,
        action58,
        action5c,
        action60,
        action64,
        action68,
        accessxi.escape_probe_log_text(desc_text),
        accessxi.escape_probe_log_text_wide(obj_d40),
        accessxi.escape_probe_log_text_wide(obj_d80),
        accessxi.escape_probe_log_text_wide(child_d00),
        accessxi.escape_probe_log_text_wide(child_d80),
        accessxi.escape_probe_log_text_wide(entry_d00),
        accessxi.escape_probe_log_text_wide(entry_d40),
        accessxi.escape_probe_log_text_wide(shape_d00)));
    return false;
end

function accessxi.merit_category_raw_text_from_ptr(ptr, source, seen_texts, parts)
    ptr = tonumber(ptr) or 0;
    if (not accessxi.is_probe_pointer(ptr) or parts == nil or seen_texts == nil) then
        return;
    end

    local function add_text(kind, offset, text)
        text = accessxi.survival_guide_text(text or '');
        if (text == '' or #text > 96) then
            return;
        end
        local lower = text:lower();
        if (lower:find('menu    ', 1, true) ~= nil
            or lower:find('windowps', 1, true) ~= nil
            or lower:find('keytops', 1, true) ~= nil
            or lower:find('shell32', 1, true) ~= nil
            or lower:find('combobox', 1, true) ~= nil
            or lower:find('vnd.ms', 1, true) ~= nil) then
            return;
        end
        local key = lower;
        if (seen_texts[key] == true) then
            return;
        end
        seen_texts[key] = true;
        parts:append(('%s:%s+%03X=%s'):fmt(tostring(source or ''), kind, tonumber(offset) or 0, text));
    end

    for _, entry in ipairs(accessxi.collect_probe_ffxi_utf16_entries(ptr, 0x300, 2, 24)) do
        add_text('ffxi', tonumber(entry.offset) or 0, entry.text or '');
        if (parts:len() >= 32) then return; end
    end
    for _, run in ipairs(accessxi.collect_probe_ascii_runs(ptr, 0x300, 3, 16)) do
        local off_text, text = tostring(run or ''):match('^%+(%x+)="(.*)"$');
        add_text('ascii', tonumber(off_text or '0', 16) or 0, text or tostring(run or ''));
        if (parts:len() >= 32) then return; end
    end
    for _, run in ipairs(accessxi.collect_probe_utf16_runs(ptr, 0x300, 3, 16)) do
        local off_text, text = tostring(run or ''):match('^%+(%x+)="(.*)"$');
        add_text('utf16', tonumber(off_text or '0', 16) or 0, text or tostring(run or ''));
        if (parts:len() >= 32) then return; end
    end
end

function accessxi.log_merit_category_deep_text_probe(menu_name, title, obj, selected, count, child)
    menu_name = tostring(menu_name or '');
    if (not menu_name:eq('menu    meritcat', true)) then
        return;
    end

    obj = tonumber(obj) or 0;
    selected = tonumber(selected) or 0;
    count = tonumber(count) or 0;
    child = tonumber(child) or 0;
    local key = ('0x%08X:%d:%d:%08X'):fmt(obj, selected, count, child);
    if (key == (accessxi.last_merit_category_deep_probe_key or '')) then
        return;
    end
    accessxi.last_merit_category_deep_probe_key = key;

    local parts = T{};
    local seen_texts = {};
    local seen_ptrs = {};
    local function scan_ptr(ptr, source, depth)
        ptr = tonumber(ptr) or 0;
        depth = tonumber(depth) or 0;
        if (not accessxi.is_probe_pointer(ptr) or seen_ptrs[ptr] == true or parts:len() >= 32) then
            return;
        end
        seen_ptrs[ptr] = true;
        accessxi.merit_category_raw_text_from_ptr(ptr, source, seen_texts, parts);
        if (depth <= 0 or parts:len() >= 32) then
            return;
        end
        for off = 0, 0x120, 4 do
            local p = read_u32(ptr + off) or 0;
            if (accessxi.is_probe_pointer(p)) then
                scan_ptr(p, ('%s+%03X'):fmt(source, off), depth - 1);
                if (parts:len() >= 32) then
                    return;
                end
            end
        end
    end

    local entry = accessxi.is_probe_pointer(obj) and (read_u32(obj + 0x08) or 0) or 0;
    local desc = accessxi.is_probe_pointer(entry) and (read_u32(entry + 0x0C) or 0) or 0;
    scan_ptr(obj, 'obj', 1);
    scan_ptr(child, 'child', 2);
    scan_ptr(entry, 'entry', 2);
    scan_ptr(desc, 'desc', 2);

    log_state(('state nativemenu meritcat-deep menu="%s" title="%s" obj=0x%08X child=0x%08X entry=0x%08X desc=0x%08X select=%d count=%d texts=%d list="%s"'):fmt(
        menu_name,
        tostring(title or ''),
        obj,
        child,
        entry,
        desc,
        selected,
        count,
        parts:len(),
        accessxi.escape_probe_log_text_wide(parts:concat(' | '))));
end

function accessxi.merit_category_native_visible_speech(menu_name, title, obj, selected, count)
    local labels, child = accessxi.merit_category_native_visible_labels(obj);
    selected = tonumber(selected) or 0;
    count = tonumber(count) or 0;
    if (selected >= 1 and labels:len() >= selected) then
        local label = accessxi.merit_category_native_label_text(labels[selected] or '');
        if (label ~= '') then
            accessxi.last_native_menu_name = tostring(menu_name or '');
            accessxi.last_native_menu_label = label;
            accessxi.last_native_menu_selected = selected;
            accessxi.last_native_menu_tick = tick();
            accessxi.current_speech_key = ('native-known-meritcat-visible:%s:%d:%d:%s'):fmt(
                tostring(menu_name or ''),
                selected,
                labels:len(),
                label);
            accessxi.log_merit_category_visible_probe(menu_name, title, obj, selected, count, labels, child, 'native-visible');
            return ('%s. %s'):fmt(tostring(title or 'Merit categories'), accessxi.sentence_fragment(label));
        end
    end

    accessxi.log_merit_category_visible_probe(menu_name, title, obj, selected, count, labels, child, 'missing-visible');
    accessxi.log_merit_category_deep_text_probe(menu_name, title, obj, selected, count, child);
    return nil;
end

function accessxi.survival_guide_probe_line(name, window_name, count, selected, selected_offset)
    local obj = get_current_menu_object_ptr();
    local parts = T{};
    if (obj ~= 0) then
        for _, off in ipairs(T{ 0x20, 0x24, 0x28, 0x2C, 0x30, 0x34, 0x38, 0x3C, 0x40, 0x44, 0x48, 0x4C, 0x50, 0x54, 0x58, 0x5C, 0x60, 0x64, 0x68, 0x6C, 0x70 }) do
            local value = read_i32(obj + off);
            if (value ~= nil and value >= -1 and value <= 128) then
                parts:append(('+%02X=%d'):fmt(off, value));
            end
        end
    end

    local target = AshitaCore:GetMemoryManager():GetTarget();
    local ank_num = target ~= nil and (tonumber(safe_call(function () return target:GetWindowAnkNum(); end, 0)) or 0) or 0;
    local ank_x = target ~= nil and (tonumber(safe_call(function () return target:GetWindowAnkX(); end, 0)) or 0) or 0;
    local ank_y = target ~= nil and (tonumber(safe_call(function () return target:GetWindowAnkY(); end, 0)) or 0) or 0;
    local marker = obj ~= 0 and (read_u32(obj + 0x58) or 0) or 0;
    local line = ('survival guide probe context="%s" menu="%s" win="%s" obj=0x%08X ankNum=%d ank=(%d,%d) select=%d count=%d off=0x%X scroll=0x%08X values=%s'):fmt(
        accessxi.survival_guide_context or '',
        name or '',
        window_name or '',
        obj,
        ank_num,
        ank_x,
        ank_y,
        selected or 0,
        count or 0,
        selected_offset or 0,
        marker,
        parts:concat(' '));
    if (line ~= accessxi.survival_guide_last_probe_log) then
        accessxi.survival_guide_last_probe_log = line;
        log_line(line);
    end
end

function accessxi.survival_guide_selected_index(count)
    for _, off in ipairs(T{ 0x4C, 0x48, 0x44, 0x40, 0x3C, 0x38, 0x34, 0x30, 0x2C }) do
        local value = accessxi.native_menu_index(off);
        if (value >= 1 and (count <= 0 or value <= count)) then
            return value, off;
        end
    end

    return 0, 0;
end

function accessxi.survival_guide_menu_speech(name)
    local menu_name = tostring(name or '');
    if (not menu_name:eq('menu    query', true)) then
        return nil;
    end

    if (get_current_menu_object_ptr() == 0) then
        return nil;
    end

    local target = AshitaCore:GetMemoryManager():GetTarget();
    local window_name = accessxi.survival_guide_text(target ~= nil and safe_call(function () return target:GetWindowName(); end, '') or '');
    if (not window_name:eq('Survival Guide', true)) then
        return nil;
    end

    accessxi.restore_survival_guide_packet_cache_if_needed();

    local count = accessxi.native_menu_index(0x24);
    local count2 = accessxi.native_menu_index(0x28);
    if (count2 > count) then
        count = count2;
    end
    if (count <= 0) then
        count = tonumber(safe_call(function () return target:GetWindowAnkNum(); end, 0)) or 0;
    end

    local selected, selected_offset = accessxi.survival_guide_selected_index(count);
    accessxi.survival_guide_probe_line(menu_name, window_name, count, selected, selected_offset);

    local obj = get_current_menu_object_ptr();
    local menu_kind = accessxi.survival_guide_menu_kind_for_obj(obj);
    local live_travel_surface = (menu_kind == 19) or accessxi.survival_guide_child_text_contains(obj, 'WHERE WILL YOU TRAVEL');
    local effective_context = accessxi.survival_guide_context or '';
    if (live_travel_surface and effective_context ~= 'sort') then
        effective_context = 'teleport';
    end

    local query_selected, query_page, query_raw, query_child, query_count = accessxi.survival_guide_query_child_state();
    if ((tonumber(query_count) or 0) > 0) then
        local visible_selected = accessxi.native_menu_index(0x4C);
        local visible_row = visible_selected;
        if (visible_row <= 0 or visible_row > 4) then
            visible_row = query_selected;
        end

        local native_label, native_mode = accessxi.native_query_label_for_selection(query_child, query_selected, query_count, effective_context);
        local native_rows = T{};
        if (native_label == '') then
            native_label, native_mode, native_rows = accessxi.survival_guide_native_label_for_query(obj, visible_row, query_selected, query_count, effective_context);
        end

        local expansion_sort_label = accessxi.native_query_expansion_sort_label(query_selected);
        local is_expansion_sort_menu = ((tonumber(query_count) or 0) == accessxi.survival_guide_teleport_count()
            and expansion_sort_label ~= ''
            and tostring(native_label or ''):eq(expansion_sort_label, true));
        if (is_expansion_sort_menu
            and query_selected >= 3
            and query_selected <= 8) then
            accessxi.survival_guide_last_area_category = query_selected;
            accessxi.survival_guide_last_region_category = 0;
            accessxi.survival_guide_destination_page_index = 0;
            accessxi.survival_guide_destination_start_index = 1;
            accessxi.survival_guide_pending_page_turn = '';
            accessxi.survival_guide_last_query_list_signature = '';
        end

        local is_region_picker = false;
        if ((tonumber(query_count) or 0) > accessxi.survival_guide_teleport_count()
            and not is_expansion_sort_menu) then
            local region_index = accessxi.survival_guide_region_index_for_native_label(native_label);
            if (region_index > 0) then
                is_region_picker = true;
                native_mode = ('%s+native-region-context'):fmt(tostring(native_mode or ''));
                accessxi.survival_guide_last_area_category = 0;
                accessxi.survival_guide_last_region_category = region_index;
                accessxi.survival_guide_destination_page_index = 0;
                accessxi.survival_guide_destination_start_index = 1;
                accessxi.survival_guide_pending_page_turn = '';
                accessxi.survival_guide_last_query_list_signature = '';
            end
        end

        local has_destination_context = ((tonumber(accessxi.survival_guide_last_area_category) or 0) > 0
            or (tonumber(accessxi.survival_guide_last_region_category) or 0) > 0);
        if ((not is_region_picker)
            and (((tonumber(query_count) or 0) > accessxi.survival_guide_teleport_count())
            or (has_destination_context and not is_expansion_sort_menu))) then
            accessxi.survival_guide_apply_pending_page_turn(query_child, query_count);
            accessxi.survival_guide_update_destination_start_from_native(accessxi.survival_guide_last_area_category, query_child, query_count, effective_context);
        else
            accessxi.survival_guide_pending_page_turn = '';
            accessxi.survival_guide_last_query_list_signature = '';
        end

        local spoken = native_label;
        if (spoken == '') then
            accessxi.current_speech_key = ('survival-guide-native-missing:%s:%d:%d:%d:%d'):fmt(
                menu_name,
                tonumber(query_selected) or 0,
                tonumber(visible_row) or 0,
                tonumber(query_page) or 0,
                tonumber(query_count) or 0);
            log_state(('state survivalguide native-missing menu="%s" win="%s" context="%s" select=%d visible=%d row=%d page=%d count=%d mode="%s" raw=0x%08X child=0x%08X'):fmt(
                menu_name,
                window_name,
                tostring(effective_context or ''),
                tonumber(query_selected) or 0,
                tonumber(visible_selected) or 0,
                tonumber(visible_row) or 0,
                tonumber(query_page) or 0,
                tonumber(query_count) or 0,
                tostring(native_mode or ''),
                tonumber(query_raw) or 0,
                tonumber(query_child) or 0));
            return nil;
        end
        if ((not is_region_picker)
            and (((tonumber(query_count) or 0) > accessxi.survival_guide_teleport_count())
            or (has_destination_context and not is_expansion_sort_menu))) then
            accessxi.survival_guide_remember_possible_page_turn(spoken);
        end

        accessxi.current_speech_key = ('survival-guide-native:%s:%d:%d:%d:%d:%s'):fmt(
            menu_name,
            tonumber(query_selected) or 0,
            tonumber(visible_row) or 0,
            tonumber(query_page) or 0,
            tonumber(query_count) or 0,
            tostring(native_label or ''));
        local row_log = ('state survivalguide native menu="%s" win="%s" context="%s" select=%d visible=%d row=%d page=%d count=%d mode="%s" raw=0x%08X child=0x%08X label="%s" rows="%s"'):fmt(
            menu_name,
            window_name,
            tostring(effective_context or ''),
            tonumber(query_selected) or 0,
            tonumber(visible_selected) or 0,
            tonumber(visible_row) or 0,
            tonumber(query_page) or 0,
            tonumber(query_count) or 0,
            tostring(native_mode or ''),
            tonumber(query_raw) or 0,
            tonumber(query_child) or 0,
            tostring(native_label or ''),
            accessxi.survival_guide_format_native_row_candidates(native_rows));
        if (row_log ~= accessxi.survival_guide_last_native_row_log) then
            accessxi.survival_guide_last_native_row_log = row_log;
            log_state(row_log);
        end
        if (accessxi.log_survival_guide_selection_structure ~= nil) then
            accessxi.log_survival_guide_selection_structure(
                obj,
                query_child,
                query_selected,
                visible_selected,
                query_page,
                query_count,
                query_raw,
                ('native:%s'):fmt(tostring(native_mode or '')));
        end
        accessxi.survival_guide_remember_selection(query_selected, query_count, query_page, native_label, 'native');
        return ('Survival Guide. %s.'):fmt(spoken);
    end

    do
        accessxi.current_speech_key = ('survival-guide-native-missing-child:%s:%d:%d:%d'):fmt(
            menu_name,
            tonumber(selected) or 0,
            tonumber(count) or 0,
            tonumber(accessxi.survival_guide_menu_id) or 0);
        log_state(('state survivalguide native-missing-child menu="%s" win="%s" select=%d count=%d off=0x%X menuId=%d'):fmt(
            menu_name,
            window_name,
            tonumber(selected) or 0,
            tonumber(count) or 0,
            tonumber(selected_offset) or 0,
            tonumber(accessxi.survival_guide_menu_id) or 0));
        accessxi.survival_guide_remember_selection(selected, count, 0, '', 'native-missing-child');
        return nil;
    end

end

