function accessxi.menu_name_in_list(name, list)
    name = tostring(name or '');
    for _, candidate in ipairs(list or T{}) do
        if (name:eq(tostring(candidate or ''), true)) then
            return true;
        end
    end
    return false;
end

function accessxi.resolve_mog_house_zone_flag_pointers()
    if (accessxi.mog_house_zone_flags_resolve_tried == true) then
        return (tonumber(accessxi.ptrs.zone_info_global) or 0) ~= 0 and (tonumber(accessxi.ptrs.zone_flags_offset) or 0) ~= 0;
    end
    accessxi.mog_house_zone_flags_resolve_tried = true;

    accessxi.ptrs.moghouse_check = safe_call(function ()
        return ashita.memory.find(0, 0, '0544FE00000FBF2925FFFF00003BC5????4283C10283FA04', 0x00, 0x00);
    end, 0) or 0;
    accessxi.ptrs.zone_flags_func = safe_call(function ()
        return ashita.memory.find(0, 0, '8B8C24040100008B90????????0BD18990????????8B15????????8B82', 0x00, 0x00);
    end, 0) or 0;

    if ((tonumber(accessxi.ptrs.zone_flags_func) or 0) ~= 0) then
        accessxi.ptrs.zone_info_global = read_u32(accessxi.ptrs.zone_flags_func + 0x17) or 0;
        accessxi.ptrs.zone_flags_offset = read_u32(accessxi.ptrs.zone_flags_func + 0x09) or 0;
    end

    local opcode = 0;
    if ((tonumber(accessxi.ptrs.moghouse_check) or 0) ~= 0) then
        opcode = read_u8(accessxi.ptrs.moghouse_check + 0x0F) or 0;
    end
    log_line(('moghouse-state resolver check=0x%08X branch=0x%02X zoneFunc=0x%08X zoneGlobal=0x%08X flagsOff=0x%X'):fmt(
        tonumber(accessxi.ptrs.moghouse_check) or 0,
        opcode,
        tonumber(accessxi.ptrs.zone_flags_func) or 0,
        tonumber(accessxi.ptrs.zone_info_global) or 0,
        tonumber(accessxi.ptrs.zone_flags_offset) or 0));

    return (tonumber(accessxi.ptrs.zone_info_global) or 0) ~= 0 and (tonumber(accessxi.ptrs.zone_flags_offset) or 0) ~= 0;
end

function accessxi.current_mog_house_zone_flag()
    if (not accessxi.resolve_mog_house_zone_flag_pointers()) then
        return false, 0, 0, 'unresolved';
    end

    local zone_info = read_u32(accessxi.ptrs.zone_info_global) or 0;
    local offset = tonumber(accessxi.ptrs.zone_flags_offset) or 0;
    if (zone_info == 0 or offset <= 0 or offset > 0x100000) then
        return false, 0, zone_info, 'missing-zone-info';
    end

    local flags_addr = zone_info + offset;
    if (not accessxi.is_probe_pointer(flags_addr)) then
        return false, 0, zone_info, ('bad-flags-address:0x%08X'):fmt(flags_addr);
    end

    local flags = read_u32(flags_addr);
    if (flags == nil) then
        return false, 0, zone_info, ('unreadable-flags:0x%08X'):fmt(flags_addr);
    end

    return bit.band(flags, 0x0100) == 0x0100, flags, zone_info, ('zone-flags+0x%X@0x%08X'):fmt(offset, flags_addr);
end

function accessxi.current_player_residence()
    local player = safe_call(function () return AshitaCore:GetMemoryManager():GetPlayer(); end, nil);
    if (player == nil) then
        return -1;
    end
    return tonumber(safe_call(function () return player:GetResidence(); end, -1)) or -1;
end

function accessxi.load_main_menu_dat_rows()
    if (type(accessxi.main_menu_dat_rows) == 'table') then
        return accessxi.main_menu_dat_rows;
    end
    if (accessxi.main_menu_dat_rows_load_tried == true) then
        return nil;
    end
    accessxi.main_menu_dat_rows_load_tried = true;

    local config = accessxi.native_menus_data.main_menu_resources or T{};
    local label_dat = config.label_dat or T{};
    local help_dat = config.help_dat or T{};
    local label_id = tonumber(label_dat.id) or 0;
    local help_id = tonumber(help_dat.id) or 0;
    local label_path = tostring(label_dat.path or '');
    local help_path = tostring(help_dat.path or '');
    local path = accessxi.dat_index_path();
    local rows = T{ labels = T{}, help = T{} };

    local f = io.open(path, 'rb');
    if (f ~= nil) then
        for line in f:lines() do
            local dat_id, dat_type, dat_path, index, text = line:match('^(%d+)\t([^\t]+)\t([^\t]+)\t(%d+)\t(.*)$');
            local id = tonumber(dat_id) or 0;
            local row = tonumber(index) or -1;
            if (id == label_id and dat_path == label_path and row >= 0) then
                local cleaned = accessxi.plain_native_menu_label(accessxi.survival_guide_text(tostring(text or ''):gsub('\r', '')));
                if (cleaned ~= '') then
                    rows.labels[row] = cleaned;
                end
            elseif (id == help_id and dat_path == help_path and row >= 0) then
                local cleaned = accessxi.plain_native_menu_help(accessxi.survival_guide_text(tostring(text or ''):gsub('\r', '')));
                if (cleaned ~= '') then
                    rows.help[row] = cleaned;
                end
            end
        end
        f:close();
    end

    if (next(rows.labels) == nil and next(rows.help) == nil) then
        log_line(('main menu DAT resource unavailable path="%s" labelDat="%s" helpDat="%s"'):fmt(path, label_path, help_path));
        return nil;
    end

    accessxi.main_menu_dat_rows = rows;
    log_line(('loaded main menu DAT resource path="%s" labels=%d help=%d labelDat="%s" helpDat="%s"'):fmt(
        path,
        accessxi.table_count(rows.labels),
        accessxi.table_count(rows.help),
        label_path,
        help_path));
    return rows;
end

function accessxi.main_menu_dat_entry(label)
    label = accessxi.plain_native_menu_label(label or '');
    if (label == '') then
        return nil, 'missing-label';
    end

    local config = accessxi.native_menus_data.main_menu_resources or T{};
    local specs = config.rows or T{};
    local spec = specs[label];
    if (spec == nil) then
        return nil, 'unmapped-label';
    end

    local rows = accessxi.load_main_menu_dat_rows();
    if (type(rows) ~= 'table') then
        return nil, 'resource-missing';
    end

    local label_row = tonumber(spec.label) or -1;
    local help_row = tonumber(spec.help) or -1;
    local dat_label = accessxi.plain_native_menu_label(rows.labels[label_row] or '');
    if (dat_label == '' or not dat_label:eq(label, true)) then
        return nil, 'label-mismatch';
    end

    local dat_help = '';
    if (help_row >= 0) then
        dat_help = accessxi.plain_native_menu_help(rows.help[help_row] or '');
    end

    local label_path = tostring((config.label_dat or T{}).path or '');
    local help_path = tostring((config.help_dat or T{}).path or '');
    local source = ('label=%s:%d'):fmt(label_path, label_row);
    if (help_row >= 0) then
        source = source .. (' help=%s:%d'):fmt(help_path, help_row);
    end

    return T{
        label = dat_label,
        help = dat_help,
        source = source,
        label_row = label_row,
        help_row = help_row,
    }, 'dat';
end

function accessxi.main_menu_module_context()
