function accessxi.config_menu_descriptor_resource_row(menu_name, selected, entry, child)
    menu_name = tostring(menu_name or '');
    selected = tonumber(selected) or 0;
    local logical, desc0c, record, record_base, scroll_top, scroll_raw = accessxi.config_menu_descriptor_resource_logical_row(menu_name, selected, entry, child);

    if (menu_name:eq('menu    cfilter', true)) then
        local row_id = accessxi.config_chat_filter_resource_row_id(logical);
        if (row_id >= 0) then
            return 'label', row_id, 'ROM\\165\\74.DAT', logical, desc0c, record, record_base, scroll_top, scroll_raw;
        end
        return '', 0, '', logical, desc0c, record, record_base, scroll_top, scroll_raw;
    end

    if (menu_name:eq('menu    fxfilter', true)) then
        if (logical >= 1 and logical <= 19) then
            return 'label', 153 + logical - 1, 'ROM\\165\\74.DAT', logical, desc0c, record, record_base, scroll_top, scroll_raw;
        end
        return '', 0, '', logical, desc0c, record, record_base, scroll_top, scroll_raw;
    end

    return '', 0, '', logical, desc0c, record, record_base, scroll_top, scroll_raw;
end

function accessxi.config_chat_filter_clear_pending_states(source)
    accessxi.config_chat_filter_pending_states = T{};
    accessxi.config_chat_filter_pending_clear_source = tostring(source or '');
end

function accessxi.config_chat_filter_pending_state(logical)
    logical = math.floor(tonumber(logical) or 0);
    if (logical < 1 or type(accessxi.config_chat_filter_pending_states) ~= 'table') then
        return '';
    end

    local entry = accessxi.config_chat_filter_pending_states[logical];
    if (type(entry) ~= 'table') then
        return '';
    end

    local now = tick();
    if ((now - (tonumber(entry.tick) or 0)) > 300000) then
        accessxi.config_chat_filter_pending_states[logical] = nil;
        return '';
    end

    local state = tostring(entry.state or '');
    if (state ~= 'On' and state ~= 'Off') then
        return '';
    end

    accessxi.config_chat_filter_state_debug = tostring(entry.source or 'pending');
    return state;
end

function accessxi.config_chat_filter_set_pending_state(logical, state, source)
    logical = math.floor(tonumber(logical) or 0);
    state = tostring(state or '');
    if (logical < 1 or (state ~= 'On' and state ~= 'Off')) then
        return false;
    end

    if (type(accessxi.config_chat_filter_pending_states) ~= 'table') then
        accessxi.config_chat_filter_pending_states = T{};
    end

    accessxi.config_chat_filter_pending_states[logical] = T{
        state = state,
        tick = tick(),
        source = tostring(source or 'pending'),
    };
    return true;
end

function accessxi.config_chat_filter_enter_probe_snapshot(logical, current_state, next_state)
    logical = math.floor(tonumber(logical) or 0);
    local ctx = accessxi.config_chat_filter_current_probe_context;
    if (type(ctx) ~= 'table') then
        ctx = T{};
    end

    local entry = tonumber(ctx.entry) or 0;
    local child = tonumber(ctx.child) or 0;
    local desc0c = tonumber(ctx.desc0c) or 0;
    local record = tonumber(ctx.record) or 0;
    local record_base = tonumber(ctx.record_base) or 0;
    local desc04 = accessxi.is_probe_pointer(entry) and (read_u32(entry + 0x04) or 0) or 0;
    local desc_record = accessxi.is_probe_pointer(desc0c) and (read_u32(desc0c + 0x00) or 0) or 0;
    local base_record = 0;
    if (accessxi.is_probe_pointer(record_base) and logical >= 1) then
        base_record = record_base + ((logical - 1) * 0x40);
    end

    log_state(('state config chat-filter-enter-probe phase="%s" seq=%d elapsed=%d menu="%s" title="%s" select=%d count=%d logical=%d row=%d text="%s" current="%s" next="%s" stateDebug="%s" pendingBefore="%s" scrollTop=%d scrollRaw=0x%08X page=%d raw=0x%08X child=0x%08X entry=0x%08X desc04=0x%08X desc0C=0x%08X descRecord=0x%08X record=0x%08X recordBase=0x%08X baseRecord=0x%08X entryD00="%s" entryD40="%s" childD00="%s" childD40="%s" desc0CD00="%s" recordD00="%s" recordBytes="%s" baseRecordD00="%s"'):fmt(
        accessxi.escape_probe_log_text(tostring(accessxi.config_chat_filter_enter_probe_phase or 'keydown')),
        tonumber(accessxi.config_chat_filter_enter_probe_seq) or 0,
        tick() - (tonumber(accessxi.config_chat_filter_enter_probe_start_tick) or tick()),
        accessxi.escape_probe_log_text(tostring(ctx.menu_name or '')),
        accessxi.escape_probe_log_text(tostring(ctx.title or 'Config')),
        tonumber(ctx.selected) or 0,
        tonumber(ctx.count) or 0,
        logical,
        tonumber(ctx.row_id) or -1,
        accessxi.escape_probe_log_text(tostring(ctx.text or accessxi.config_chat_filter_current_text or '')),
        accessxi.escape_probe_log_text(tostring(current_state or '')),
        accessxi.escape_probe_log_text(tostring(next_state or '')),
        accessxi.escape_probe_log_text(tostring(ctx.state_debug or accessxi.config_chat_filter_state_debug or '')),
        accessxi.escape_probe_log_text(accessxi.config_chat_filter_pending_state(logical)),
        tonumber(ctx.scroll_top) or 0,
        tonumber(ctx.scroll_raw) or 0,
        tonumber(ctx.page) or 0,
        tonumber(ctx.raw) or 0,
        child,
        entry,
        desc04,
        desc0c,
        desc_record,
        record,
        record_base,
        base_record,
        accessxi.escape_probe_log_text(accessxi.format_probe_dwords(entry, 0x00, 24)),
        accessxi.escape_probe_log_text(accessxi.format_probe_dwords(entry, 0x40, 24)),
        accessxi.escape_probe_log_text(accessxi.format_probe_dwords(child, 0x00, 24)),
        accessxi.escape_probe_log_text(accessxi.format_probe_dwords(child, 0x40, 24)),
        accessxi.escape_probe_log_text(accessxi.format_probe_dwords(desc0c, 0x00, 16)),
        accessxi.escape_probe_log_text(accessxi.format_probe_dwords(record, 0x00, 24)),
        accessxi.escape_probe_log_text(accessxi.format_probe_bytes(record, 0x00, 0x40)),
        accessxi.escape_probe_log_text(accessxi.format_probe_dwords(base_record, 0x00, 24))));
end

function accessxi.config_chat_filter_schedule_enter_probe(logical, current_state, next_state)
    accessxi.config_chat_filter_enter_probe_seq = (tonumber(accessxi.config_chat_filter_enter_probe_seq) or 0) + 1;
    accessxi.config_chat_filter_enter_probe_start_tick = tick();
    accessxi.config_chat_filter_enter_probe_pending = T{
        seq = tonumber(accessxi.config_chat_filter_enter_probe_seq) or 0,
        logical = math.floor(tonumber(logical) or 0),
        current_state = tostring(current_state or ''),
        next_state = tostring(next_state or ''),
        count = 0,
        next_tick = tick() + 50,
    };
end

function accessxi.poll_config_chat_filter_enter_probe()
    local pending = accessxi.config_chat_filter_enter_probe_pending;
    if (type(pending) ~= 'table') then
        return false;
    end

    local now = tick();
    if (now < (tonumber(pending.next_tick) or 0)) then
        return false;
    end

    local count = (tonumber(pending.count) or 0) + 1;
    pending.count = count;
    accessxi.config_chat_filter_enter_probe_seq = tonumber(pending.seq) or tonumber(accessxi.config_chat_filter_enter_probe_seq) or 0;
    accessxi.config_chat_filter_enter_probe_phase = ('after-%d'):fmt(count);
    accessxi.config_chat_filter_enter_probe_snapshot(pending.logical, pending.current_state, pending.next_state);
    accessxi.config_chat_filter_enter_probe_phase = '';

    if (count >= 4 or ((now - (tonumber(accessxi.config_chat_filter_enter_probe_start_tick) or now)) > 1200)) then
        accessxi.config_chat_filter_enter_probe_pending = nil;
        return true;
    end

    local delays = T{ 90, 180, 360, 540 };
    pending.next_tick = now + (tonumber(delays[count]) or 250);
    return true;
end

function accessxi.config_chat_filter_note_confirm_key_up(key)
    key = tonumber(key) or 0;
    if (key == VK_RETURN) then
        accessxi.config_chat_filter_confirm_down = false;
    end
end

function accessxi.config_chat_filter_note_confirm_key(key)
    key = tonumber(key) or 0;
    if (key ~= VK_RETURN) then
        return false;
    end
    if (accessxi.config_chat_filter_confirm_down == true) then
        return false;
    end
    if (not tostring(get_menu_name() or ''):eq('menu    cfilter', true)) then
        return false;
    end

    accessxi.config_chat_filter_confirm_down = true;

    local logical = math.floor(tonumber(accessxi.config_chat_filter_current_logical) or 0);
    if (logical < 1 or ((tick() - (tonumber(accessxi.config_chat_filter_current_tick) or 0)) > 1500)) then
        return false;
    end

    local current = accessxi.config_chat_filter_pending_state(logical);
    if (current == '') then
        current = tostring(accessxi.config_chat_filter_current_state or '');
    end

    local next_state = '';
    if (current == 'On') then
        next_state = 'Off';
    elseif (current == 'Off') then
        next_state = 'On';
    end
    if (next_state == '') then
        return false;
    end

    local confirm_source = tostring(accessxi.config_chat_filter_confirm_source or '');
    if (confirm_source == '') then
        confirm_source = 'keydown';
    end
    accessxi.config_chat_filter_enter_probe_phase = confirm_source;
    accessxi.config_chat_filter_enter_probe_snapshot(logical, current, next_state);
    accessxi.config_chat_filter_enter_probe_phase = '';
    accessxi.config_chat_filter_schedule_enter_probe(logical, current, next_state);
    accessxi.config_chat_filter_set_pending_state(logical, next_state, 'confirm-key');
    accessxi.last_key = '';
    accessxi.last_log_key = '';
    log_state(('state config chat-filter-pending-toggle logical=%d from="%s" to="%s" text="%s"'):fmt(
        logical,
        accessxi.escape_probe_log_text(current),
        accessxi.escape_probe_log_text(next_state),
        accessxi.escape_probe_log_text(tostring(accessxi.config_chat_filter_current_text or ''))));
    return true;
end

function accessxi.poll_config_chat_filter_confirm_key()
    if (not tostring(get_menu_name() or ''):eq('menu    cfilter', true)) then
        accessxi.config_chat_filter_confirm_poll_down = false;
        return false;
    end

    local down = bit.band(kernel32.GetAsyncKeyState(VK_RETURN), 0x8000) ~= 0;
    if (not down) then
        accessxi.config_chat_filter_confirm_poll_down = false;
        accessxi.config_chat_filter_note_confirm_key_up(VK_RETURN);
        return false;
    end

    if (accessxi.config_chat_filter_confirm_poll_down == true) then
        return false;
    end

    accessxi.config_chat_filter_confirm_poll_down = true;
    accessxi.config_chat_filter_confirm_source = 'poll-keydown';
    local handled = accessxi.config_chat_filter_note_confirm_key(VK_RETURN);
    accessxi.config_chat_filter_confirm_source = '';
    if (handled) then
        log_state('state config chat-filter-confirm-poll source="GetAsyncKeyState" key="VK_RETURN" handled=true');
    end
    return handled;
end

function accessxi.config_chat_filter_state(logical)
    logical = math.floor(tonumber(logical) or 0);
    if (logical < 1) then
        accessxi.config_chat_filter_state_debug = '';
        return '';
    end

    local pending = accessxi.config_chat_filter_pending_state(logical);
    if (pending ~= '') then
        return pending;
    end

    local ok, word0, word1, word2 = pcall(function ()
        if (accessxi.config_chat_filter_state_ptr == nil) then
            local ptr = tonumber(safe_call(function ()
                return ashita.memory.find(0, 0, 'C3C74004000000008B0D????????81C1', 0x0A, 0);
            end, 0)) or 0;
            if (ptr == 0) then
                return nil, nil, nil;
            end
            accessxi.config_chat_filter_state_ptr = ffi.cast('uint32_t**', ptr);
            accessxi.config_chat_filter_state_offset = ffi.cast('uint32_t*', ffi.cast('uint8_t*', accessxi.config_chat_filter_state_ptr) + 0x06);
        end

        if (accessxi.config_chat_filter_state_ptr == nil or accessxi.config_chat_filter_state_offset == nil) then
            return nil, nil, nil;
        end

        local base = tonumber(accessxi.config_chat_filter_state_ptr[0][0]) or 0;
        if (base == 0) then
            return nil, nil, nil;
        end

        local offset = tonumber(accessxi.config_chat_filter_state_offset[0]) or 0;
        local data = ffi.cast('uint32_t*', base + offset);
        return tonumber(data[0]) or 0, tonumber(data[1]) or 0, tonumber(data[2]) or 0;
    end);

    if (not ok or word0 == nil) then
        accessxi.config_chat_filter_state_debug = '';
        return '';
    end

    local bit_index = logical - 1;
    local word_index = math.floor(bit_index / 32);
    local bit_offset = bit_index % 32;
    local value = 0;
    if (word_index == 0) then
        value = tonumber(word0) or 0;
    elseif (word_index == 1) then
        value = tonumber(word1) or 0;
    elseif (word_index == 2) then
        value = tonumber(word2) or 0;
    else
        accessxi.config_chat_filter_state_debug = '';
        return '';
    end

    accessxi.config_chat_filter_state_debug = ('word=%d bit=%d masks=0x%08X,0x%08X,0x%08X'):fmt(
        word_index,
        bit_offset,
        tonumber(word0) or 0,
        tonumber(word1) or 0,
        tonumber(word2) or 0);

    if (bit.band(value, bit.lshift(1, bit_offset)) ~= 0) then
        return 'On';
    end
    return 'Off';
end

function accessxi.config_fxfilter_state(raw, logical)
    raw = tonumber(raw) or 0;
    logical = math.floor(tonumber(logical) or 0);
    if (logical < 1 or logical > 16) then
        return '';
    end

    local mask = bit.lshift(1, logical - 1);
    if (bit.band(raw, mask) ~= 0) then
        return 'On';
    end
    return 'Off';
end

function accessxi.config_menu_descriptor_resource_speech(menu_name, title, selected, count, entry, page, raw, child)
    if (not accessxi.config_menu_uses_descriptor_resource_rows(menu_name)) then
        return nil;
    end

    selected = tonumber(selected) or 0;
    count = tonumber(count) or 0;
    entry = tonumber(entry) or 0;
    child = tonumber(child) or 0;
    if (selected <= 0 or count <= 0 or selected > count) then
        return nil;
    end

    local kind, row_id, dat_path, logical, desc0c, record, record_base, scroll_top, scroll_raw = accessxi.config_menu_descriptor_resource_row(menu_name, selected, entry, child);
    if (kind == '' or row_id < 0) then
        return nil;
    end

    local rows = accessxi.load_config_filter_resource_rows();
    if (type(rows) ~= 'table') then
        return nil;
    end

    local text = '';
    if (kind == 'label') then
        text = accessxi.config_filter_label_text(rows.labels[row_id] or '');
    elseif (kind == 'chat_label') then
        text = accessxi.config_filter_label_text(rows.chat_labels[row_id] or '');
    elseif (kind == 'chat_filter_label') then
        text = accessxi.config_filter_label_text(rows.chat_filter_labels[row_id] or '');
    else
        text = accessxi.plain_native_menu_help(rows.help[row_id] or '');
    end
    if (text == '') then
        log_state(('state config descriptor-resource-missing menu="%s" title="%s" select=%d count=%d logical=%d scrollTop=%d scrollRaw=0x%08X page=%d raw=0x%08X child=0x%08X entry=0x%08X desc0C=0x%08X record=0x%08X recordBase=0x%08X dat="%s" kind="%s" row=%d rawText="%s"'):fmt(
            tostring(menu_name or ''),
            accessxi.escape_probe_log_text(tostring(title or 'Config')),
            selected,
            count,
            tonumber(logical) or 0,
            tonumber(scroll_top) or 0,
            tonumber(scroll_raw) or 0,
            tonumber(page) or 0,
            tonumber(raw) or 0,
            child,
            entry,
            tonumber(desc0c) or 0,
            tonumber(record) or 0,
            tonumber(record_base) or 0,
            dat_path,
            kind,
            row_id,
            accessxi.escape_probe_log_text(tostring((kind == 'chat_filter_label' and rows.chat_filter_labels[row_id]) or (kind == 'chat_label' and rows.chat_labels[row_id]) or (kind == 'label' and rows.labels[row_id]) or rows.help[row_id] or ''))));
        return nil;
    end

    local state = '';
    local state_debug = '';
    if (menu_name:eq('menu    cfilter', true)) then
        state = accessxi.config_chat_filter_state(logical);
        state_debug = tostring(accessxi.config_chat_filter_state_debug or '');
        accessxi.config_chat_filter_current_logical = tonumber(logical) or 0;
        accessxi.config_chat_filter_current_state = state;
        accessxi.config_chat_filter_current_text = text;
        accessxi.config_chat_filter_current_tick = tick();
        accessxi.config_chat_filter_current_probe_context = T{
            menu_name = tostring(menu_name or '');
            title = tostring(title or 'Config');
            selected = tonumber(selected) or 0;
            count = tonumber(count) or 0;
            kind = tostring(kind or '');
            row_id = tonumber(row_id) or -1;
            dat_path = tostring(dat_path or '');
            logical = tonumber(logical) or 0;
            desc0c = tonumber(desc0c) or 0;
            record = tonumber(record) or 0;
            record_base = tonumber(record_base) or 0;
            scroll_top = tonumber(scroll_top) or 0;
            scroll_raw = tonumber(scroll_raw) or 0;
            page = tonumber(page) or 0;
            raw = tonumber(raw) or 0;
            child = tonumber(child) or 0;
            entry = tonumber(entry) or 0;
            text = tostring(text or '');
            state = tostring(state or '');
            state_debug = tostring(state_debug or '');
            tick = tick();
        };
    elseif (menu_name:eq('menu    fxfilter', true)) then
        state = accessxi.config_fxfilter_state(raw, logical);
    end

    log_state(('state config descriptor-resource menu="%s" title="%s" select=%d count=%d logical=%d scrollTop=%d scrollRaw=0x%08X page=%d raw=0x%08X child=0x%08X entry=0x%08X desc0C=0x%08X record=0x%08X recordBase=0x%08X dat="%s" kind="%s" row=%d state="%s" stateDebug="%s" text="%s"'):fmt(
        tostring(menu_name or ''),
        accessxi.escape_probe_log_text(tostring(title or 'Config')),
        selected,
        count,
        tonumber(logical) or 0,
        tonumber(scroll_top) or 0,
        tonumber(scroll_raw) or 0,
        tonumber(page) or 0,
        tonumber(raw) or 0,
        child,
        entry,
        tonumber(desc0c) or 0,
        tonumber(record) or 0,
        tonumber(record_base) or 0,
        dat_path,
        kind,
        row_id,
        accessxi.escape_probe_log_text(state),
        accessxi.escape_probe_log_text(state_debug),
        accessxi.escape_probe_log_text(text)));
    accessxi.last_native_menu_name = tostring(menu_name or '');
    accessxi.last_native_menu_label = text;
    accessxi.last_native_menu_selected = selected;
    accessxi.last_native_menu_tick = tick();
    accessxi.current_speech_key = ('native-known-config-descriptor-resource:%s:%d:%d:%s:%d:%s:%s'):fmt(
        tostring(menu_name or ''),
        selected,
        count,
        kind,
        row_id,
        state,
        text);
    if (state ~= '') then
        return ('%s. %s %s'):fmt(tostring(title or 'Config'), accessxi.sentence_fragment(state), accessxi.sentence_fragment(text));
    end
    return ('%s. %s'):fmt(tostring(title or 'Config'), accessxi.sentence_fragment(text));
end

function accessxi.config_log_window_designation_speech(menu_name, title, selected, count, entry, page, raw, child)
    if (not tostring(menu_name or ''):eq('menu    conf11s', true)) then
        return nil;
    end

    selected = tonumber(selected) or 0;
    count = tonumber(count) or 0;
    if (selected <= 0 or count <= 0 or selected > count) then
        return nil;
    end

    local category = tonumber(accessxi.config_log_window_category) or 0;
    if (category <= 0 or (tonumber(accessxi.config_log_window_category_tick) or 0) < tick()) then
        log_state(('state config log-window-designation-missing-category menu="%s" title="%s" select=%d count=%d page=%d raw=0x%08X child=0x%08X entry=0x%08X'):fmt(
            tostring(menu_name or ''),
            accessxi.escape_probe_log_text(tostring(title or 'Config')),
            selected,
            count,
            tonumber(page) or 0,
            tonumber(raw) or 0,
            tonumber(child) or 0,
            tonumber(entry) or 0));
        return nil;
    end

    local row_ids = accessxi.config_log_window_designation_row_ids(category);
    if (type(row_ids) ~= 'table') then
        return nil;
    end

    local logical = selected + ((tonumber(page) or 0) * 18);
    local row_id = tonumber(row_ids[logical]) or -1;
    if (row_id < 0) then
        log_state(('state config log-window-designation-missing-row menu="%s" title="%s" category=%d select=%d logical=%d count=%d page=%d raw=0x%08X child=0x%08X entry=0x%08X'):fmt(
            tostring(menu_name or ''),
            accessxi.escape_probe_log_text(tostring(title or 'Config')),
            category,
            selected,
            logical,
            count,
            tonumber(page) or 0,
            tonumber(raw) or 0,
            tonumber(child) or 0,
            tonumber(entry) or 0));
        return nil;
    end

    local rows = accessxi.load_config_filter_resource_rows();
    if (type(rows) ~= 'table') then
        return nil;
    end

    local text = accessxi.config_filter_label_text(rows.labels[row_id] or '');
    if (text == '') then
        log_state(('state config log-window-designation-missing-text menu="%s" title="%s" category=%d select=%d logical=%d row=%d count=%d page=%d raw=0x%08X child=0x%08X entry=0x%08X'):fmt(
            tostring(menu_name or ''),
            accessxi.escape_probe_log_text(tostring(title or 'Config')),
            category,
            selected,
            logical,
            row_id,
            count,
            tonumber(page) or 0,
            tonumber(raw) or 0,
            tonumber(child) or 0,
            tonumber(entry) or 0));
        return nil;
    end

    local state = accessxi.config_log_window_designation_state(raw, category, logical);

    log_state(('state config log-window-designation menu="%s" title="%s" category=%d select=%d logical=%d count=%d page=%d raw=0x%08X child=0x%08X entry=0x%08X dat="ROM\\165\\74.DAT" row=%d state="%s" text="%s"'):fmt(
        tostring(menu_name or ''),
        accessxi.escape_probe_log_text(tostring(title or 'Config')),
        category,
        selected,
        logical,
        count,
        tonumber(page) or 0,
        tonumber(raw) or 0,
        tonumber(child) or 0,
        tonumber(entry) or 0,
        row_id,
        accessxi.escape_probe_log_text(state),
        accessxi.escape_probe_log_text(text)));
    accessxi.last_native_menu_name = tostring(menu_name or '');
    accessxi.last_native_menu_label = text;
    accessxi.last_native_menu_selected = selected;
    accessxi.last_native_menu_tick = tick();
    accessxi.config_log_window_designation_current_category = tonumber(category) or 0;
    accessxi.config_log_window_designation_current_logical = tonumber(logical) or 0;
    accessxi.config_log_window_designation_current_state = state;
    accessxi.config_log_window_designation_current_text = text;
    accessxi.config_log_window_designation_current_tick = tick();
    accessxi.current_speech_key = ('native-known-config-log-window-designation:%s:%d:%d:%d:%d:%s:%s'):fmt(
        tostring(menu_name or ''),
        category,
        selected,
        logical,
        row_id,
        state,
        text);
    if (state ~= '') then
        return ('%s. %s %s'):fmt(tostring(title or 'Config'), accessxi.sentence_fragment(state), accessxi.sentence_fragment(text));
    end
    return ('%s. %s'):fmt(tostring(title or 'Config'), accessxi.sentence_fragment(text));
end

function accessxi.log_config_descriptor_resource_probe(menu_name, title, selected, count, page, raw, child, entry)
    if (not accessxi.config_menu_uses_descriptor_resource_rows(menu_name)) then
        return;
    end

    selected = tonumber(selected) or 0;
    count = tonumber(count) or 0;
    child = tonumber(child) or 0;
    entry = tonumber(entry) or 0;
    local desc04 = accessxi.is_probe_pointer(entry) and (read_u32(entry + 0x04) or 0) or 0;
    local desc0c = accessxi.is_probe_pointer(entry) and (read_u32(entry + 0x0C) or 0) or 0;
    local desc_base = 0;
    if (accessxi.is_probe_pointer(desc0c) and selected > 0 and selected <= 64) then
        desc_base = desc0c - (selected * 0x14);
    end

    local key = ('%s:%d:%d:%08X:%08X:%08X'):fmt(
        tostring(menu_name or ''),
        selected,
        count,
        entry,
        child,
        desc0c);
    if (key == tostring(accessxi.config_descriptor_resource_probe_last_key or '')) then
        return;
    end
    accessxi.config_descriptor_resource_probe_last_key = key;

    log_state(('state config descriptor-probe marker="config-menu-descriptor-probe" source="native-known-config-descriptor" menu="%s" title="%s" select=%d count=%d page=%d raw=0x%08X child=0x%08X entry=0x%08X desc04=0x%08X desc0C=0x%08X descBase=0x%08X desc04Dwords="%s" desc0CDwords="%s" desc0CBytes="%s" descTable="%s"'):fmt(
        tostring(menu_name or ''),
        accessxi.escape_probe_log_text(tostring(title or 'Config')),
        selected,
        count,
        tonumber(page) or 0,
        tonumber(raw) or 0,
        child,
        entry,
        desc04,
        desc0c,
        desc_base,
        accessxi.escape_probe_log_text(accessxi.format_probe_dwords(desc04, 0, 8)),
        accessxi.escape_probe_log_text(accessxi.format_probe_dwords(desc0c, 0, 8)),
        accessxi.escape_probe_log_text(accessxi.format_probe_bytes(desc0c, 0, 0x20)),
        accessxi.escape_probe_log_text_wide(accessxi.config_menu_descriptor_probe_table(desc_base, count))));
end

function accessxi.log_config_menu_probe(menu_name, title, obj, selected, count, page, raw, child, entry, mode, reason)
    if (not accessxi.is_config_menu_name(menu_name)) then
        return;
    end

    selected = tonumber(selected) or 0;
    count = tonumber(count) or 0;
    obj = tonumber(obj) or 0;
    child = tonumber(child) or 0;
    entry = tonumber(entry) or 0;
    local desc04 = accessxi.is_probe_pointer(entry) and (read_u32(entry + 0x04) or 0) or 0;
    local desc0c = accessxi.is_probe_pointer(entry) and (read_u32(entry + 0x0C) or 0) or 0;
    local label_ptr = accessxi.is_probe_pointer(entry) and (read_u32(entry + 0x44) or 0) or 0;
    local help_ptr = accessxi.is_probe_pointer(entry) and (read_u32(entry + 0x40) or 0) or 0;
    local table_addr = accessxi.ffximain_rebased_va(0x1062FBF8);
    local key = ('%s:%d:%d:0x%08X:0x%08X:%s'):fmt(
        tostring(reason or ''),
        selected,
        count,
        entry,
        child,
        tostring(mode or ''));
    if (key == tostring(accessxi.config_menu_probe_last_key or '')) then
        return;
    end
    accessxi.config_menu_probe_last_key = key;

    log_state(('state config native-probe menu="%s" title="%s" reason="%s" select=%d count=%d page=%d raw=0x%08X obj=0x%08X child=0x%08X entry=0x%08X mode="%s" desc04=0x%08X desc0C=0x%08X labelPtr=0x%08X label="%s" helpPtr=0x%08X help="%s" table=0x%08X tableDwords="%s" objDwords="%s" childDwords="%s" entryDwords000="%s" entryDwords040="%s" entryDwords080="%s" entryRuns="%s" entryInline="%s" entryPtrs="%s" desc04Runs="%s" desc0CRuns="%s" nearbyRuns="%s" nearbyInline="%s"'):fmt(
        tostring(menu_name or ''),
        accessxi.escape_probe_log_text(tostring(title or '')),
        accessxi.escape_probe_log_text(tostring(reason or '')),
        selected,
        count,
        tonumber(page) or 0,
        tonumber(raw) or 0,
        obj,
        child,
        entry,
        accessxi.escape_probe_log_text(tostring(mode or '')),
        desc04,
        desc0c,
        label_ptr,
        accessxi.escape_probe_log_text(accessxi.plain_native_menu_label(read_probe_string(label_ptr, 180))),
        help_ptr,
        accessxi.escape_probe_log_text(accessxi.plain_native_menu_help(read_probe_string(help_ptr, 260))),
        table_addr,
        accessxi.escape_probe_log_text(accessxi.format_probe_dwords(table_addr, 0x00, 16)),
        accessxi.escape_probe_log_text(accessxi.format_probe_dwords(obj, 0x00, 24)),
        accessxi.escape_probe_log_text(accessxi.format_probe_dwords(child, 0x00, 24)),
        accessxi.escape_probe_log_text(accessxi.format_probe_dwords(entry, 0x00, 24)),
        accessxi.escape_probe_log_text(accessxi.format_probe_dwords(entry, 0x40, 24)),
        accessxi.escape_probe_log_text(accessxi.format_probe_dwords(entry, 0x80, 16)),
        accessxi.escape_probe_log_text_wide(accessxi.status_menu_probe_runs(entry, 0x180)),
        accessxi.escape_probe_log_text_wide(accessxi.status_menu_probe_inline_strings(entry)),
        accessxi.escape_probe_log_text_wide(accessxi.status_menu_probe_pointer_fields(entry)),
        accessxi.escape_probe_log_text_wide(accessxi.status_menu_probe_runs(desc04, 0x180)),
        accessxi.escape_probe_log_text_wide(accessxi.status_menu_probe_runs(desc0c, 0x180)),
        accessxi.escape_probe_log_text_wide(accessxi.status_menu_probe_runs(entry - 0x240, 0x700)),
        accessxi.escape_probe_log_text_wide(accessxi.status_menu_probe_inline_strings(entry - 0x240))));
end

function accessxi.config_menu_native_label_speech(menu_name, title, selected, count, obj, child)
    if (not accessxi.is_config_menu_name(menu_name)) then
        return nil;
    end
    if (tostring(menu_name or ''):eq('menu    cfilter', true)) then
        return nil;
    end

    selected = tonumber(selected) or 0;
    count = tonumber(count) or 0;
    if (selected <= 0 or count <= 0 or selected > count) then
        return nil;
    end

    local seen = {};
    for _, source in ipairs(T{
        T{ name = 'child', ptr = tonumber(child) or 0 },
        T{ name = 'object', ptr = tonumber(obj) or 0 },
    }) do
        local ptr = tonumber(source.ptr) or 0;
        if (accessxi.is_probe_pointer(ptr) and seen[ptr] ~= true) then
            seen[ptr] = true;
            local label, mode = accessxi.native_query_label_for_selection(ptr, selected, count, 'config-visible');
            label = accessxi.plain_native_menu_label(label or '');
            if (label ~= '') then
                accessxi.last_native_menu_name = tostring(menu_name or '');
                accessxi.last_native_menu_label = label;
                accessxi.last_native_menu_selected = selected;
                accessxi.last_native_menu_tick = tick();
                accessxi.current_speech_key = ('native-known-config-label:%s:%d:%d:0x%08X:%s:%s'):fmt(
                    tostring(menu_name or ''),
                    selected,
                    count,
                    ptr,
                    tostring(source.name or ''),
                    label);
                log_state(('state config native-label menu="%s" title="%s" select=%d count=%d source="%s" ptr=0x%08X mode="%s" label="%s"'):fmt(
                    tostring(menu_name or ''),
                    accessxi.escape_probe_log_text(tostring(title or 'Config')),
                    selected,
                    count,
                    tostring(source.name or ''),
                    ptr,
                    tostring(mode or ''),
                    accessxi.escape_probe_log_text(label)));
                return ('%s. %s'):fmt(tostring(title or 'Config'), accessxi.sentence_fragment(label));
            end
        end
    end

    return nil;
end

function accessxi.config_volume_slider_help_repeat(menu_name, selected, entry, help_text)
    menu_name = tostring(menu_name or '');
    help_text = accessxi.plain_native_menu_help(help_text or '');
    selected = tonumber(selected) or 0;
    entry = tonumber(entry) or 0;
    local is_volume_slider = (menu_name:eq('menu    conf2win', true)
        and ((selected == 3 and help_text:eq('Set the volume of sound effects.', true))
            or (selected == 4 and help_text:eq('Set the volume of the background music.', true))));
    if (not is_volume_slider) then
        accessxi.config_volume_slider_help_context = '';
        return false;
    end

    local context = ('%s:%d:0x%08X:%s'):fmt(menu_name, selected, entry, help_text);
    if (context == tostring(accessxi.config_volume_slider_help_context or '')) then
        return true;
    end
    accessxi.config_volume_slider_help_context = context;
    return false;
end

function accessxi.config_menu_horizontal_choice_probe_values(ptr, offsets)
    ptr = tonumber(ptr) or 0;
    if (not accessxi.is_scan_address(ptr)) then
        return '';
    end

    local parts = T{};
    for _, off in ipairs(offsets or T{}) do
        local byte_value = read_u8(ptr + off);
        local word_value = read_u16(ptr + off);
        local dword_value = read_i32(ptr + off);
        parts:append(('+%02X=b%s/w%s/d%s'):fmt(
            off,
            byte_value ~= nil and tostring(byte_value) or '?',
            word_value ~= nil and tostring(word_value) or '?',
            dword_value ~= nil and tostring(dword_value) or '?'));
    end
    return parts:concat(' ');
end

function accessxi.config_menu_horizontal_choice_probe(menu_name, title, selected, count, entry, child, obj, page, raw, help_text, label_ptr)
    local key = ('%s:%d:%d:0x%08X:0x%08X:0x%08X:0x%08X:%s'):fmt(
        tostring(menu_name or ''),
        tonumber(selected) or 0,
        tonumber(count) or 0,
        tonumber(entry) or 0,
        tonumber(child) or 0,
        tonumber(obj) or 0,
        tonumber(raw) or 0,
        tostring(help_text or ''));
    if (key == tostring(accessxi.config_horizontal_choice_probe_last_key or '')) then
        return;
    end
    accessxi.config_horizontal_choice_probe_last_key = key;

    local offsets = T{ 0x00, 0x04, 0x08, 0x0C, 0x10, 0x14, 0x18, 0x1C, 0x20, 0x24, 0x28, 0x2C, 0x30, 0x34, 0x38, 0x3C, 0x40, 0x44, 0x48, 0x4C, 0x50, 0x54, 0x58, 0x5C, 0x60, 0x64, 0x68, 0x6C, 0x70, 0x74, 0x78, 0x7C };
    local target = safe_call(function () return AshitaCore:GetMemoryManager():GetTarget(); end, nil);
    local ank_num = target ~= nil and (tonumber(safe_call(function () return target:GetWindowAnkNum(); end, 0)) or 0) or 0;
    local ank_shapes = T{};
    if (target ~= nil) then
        for i = 0, math.min(tonumber(ank_num) or 0, 24) - 1 do
            local shape = tonumber(safe_call(function () return target:GetWindowAnkShape(i); end, 0)) or 0;
            ank_shapes:append(('%d=0x%08X'):fmt(i, shape));
        end
    end

    log_state(('state config horizontal-choice-probe menu="%s" title="%s" select=%d count=%d page=%d entry=0x%08X child=0x%08X obj=0x%08X raw=0x%08X labelPtr=0x%08X help="%s" entryv="%s" childv="%s" objv="%s" rawv="%s" entryD00="%s" entryD40="%s" childD00="%s" objD00="%s" rawD00="%s" ankNum=%d ankShapes="%s"'):fmt(
        tostring(menu_name or ''),
        accessxi.escape_probe_log_text(tostring(title or 'Config')),
        tonumber(selected) or 0,
        tonumber(count) or 0,
        tonumber(page) or 0,
        tonumber(entry) or 0,
        tonumber(child) or 0,
        tonumber(obj) or 0,
        tonumber(raw) or 0,
        tonumber(label_ptr) or 0,
        accessxi.escape_probe_log_text(tostring(help_text or '')),
        accessxi.escape_probe_log_text(accessxi.config_menu_horizontal_choice_probe_values(entry, offsets)),
        accessxi.escape_probe_log_text(accessxi.config_menu_horizontal_choice_probe_values(child, offsets)),
        accessxi.escape_probe_log_text(accessxi.config_menu_horizontal_choice_probe_values(obj, offsets)),
        accessxi.escape_probe_log_text(accessxi.config_menu_horizontal_choice_probe_values(raw, offsets)),
        accessxi.escape_probe_log_text(accessxi.format_probe_dwords(entry, 0x00, 32)),
        accessxi.escape_probe_log_text(accessxi.format_probe_dwords(entry, 0x40, 32)),
        accessxi.escape_probe_log_text(accessxi.format_probe_dwords(child, 0x00, 32)),
        accessxi.escape_probe_log_text(accessxi.format_probe_dwords(obj, 0x00, 32)),
        accessxi.escape_probe_log_text(accessxi.format_probe_dwords(raw, 0x00, 32)),
        ank_num,
        accessxi.escape_probe_log_text(ank_shapes:concat(' '))));

    accessxi.config_horizontal_choice_probe_seq = (tonumber(accessxi.config_horizontal_choice_probe_seq) or 0) + 1;
    local seq = tonumber(accessxi.config_horizontal_choice_probe_seq) or 0;
    if (target ~= nil) then
        for i = 0, math.min(tonumber(ank_num) or 0, 8) - 1 do
            local shape = tonumber(safe_call(function () return target:GetWindowAnkShape(i); end, 0)) or 0;
            if (accessxi.is_probe_pointer(shape)) then
                log_state(('state config horizontal-choice-shape seq=%d shape=%d ptr=0x%08X d00="%s" d40="%s" bytes00="%s"'):fmt(
                    seq,
                    i,
                    shape,
                    accessxi.escape_probe_log_text(accessxi.format_probe_dwords(shape, 0x00, 16)),
                    accessxi.escape_probe_log_text(accessxi.format_probe_dwords(shape, 0x40, 16)),
                    accessxi.escape_probe_log_text(accessxi.format_probe_bytes(shape, 0x00, 0x60))));
                accessxi.log_probe_short_text_runs(seq, ('conf4.choice.shape%d'):fmt(i), shape, 0x280, 1, 24);
                accessxi.log_probe_pointer_text_targets(seq, ('conf4.choice.shape%d'):fmt(i), shape, 0x00, 0x17C, 18);
            end
        end
    end
end

function accessxi.config_menu_horizontal_choice_value(help_text, selected)
    help_text = accessxi.plain_native_menu_help(help_text or '');
    selected = tonumber(selected) or 0;
    if (help_text:eq('Filter out words that could be interpreted as offensive.', true)) then
        return 'Language Filtering Tool', T{ [1] = 'On', [2] = 'Off' }[selected] or '';
    end
    if (help_text:eq('Automatically disconnect from server after specified time.', true)) then
        return 'Auto-disconnect', T{
            [3] = '10 minutes',
            [4] = '20 minutes',
            [5] = '30 minutes',
            [6] = '40 minutes',
            [7] = '50 minutes',
            [8] = '60 minutes',
            [9] = 'Off',
        }[selected] or '';
    end
    return '', '';
end

function accessxi.config_menu_horizontal_choice_speech(menu_name, title, selected, count, entry, child, obj, page, raw, help_text)
    menu_name = tostring(menu_name or '');
    help_text = accessxi.plain_native_menu_help(help_text or '');
    selected = tonumber(selected) or 0;
    count = tonumber(count) or 0;
    entry = tonumber(entry) or 0;
    if (not menu_name:eq('menu    conf4', true)) then
        return nil;
    end
    if (not (help_text:eq('Filter out words that could be interpreted as offensive.', true)
        or help_text:eq('Automatically disconnect from server after specified time.', true))) then
        return nil;
    end
    if (not accessxi.is_probe_pointer(entry)) then
        return nil;
    end

    local native_label, native_value = accessxi.config_menu_horizontal_choice_value(help_text, selected);
    if (native_label ~= '' and native_value ~= '') then
        accessxi.last_native_menu_name = menu_name;
        accessxi.last_native_menu_label = native_label;
        accessxi.last_native_menu_selected = selected;
        accessxi.last_native_menu_tick = tick();
        accessxi.current_speech_key = ('native-known-config-horizontal-choice-index:%s:%d:%d:0x%08X:%s:%s:%s'):fmt(
            menu_name,
            selected,
            count,
            entry,
            native_label,
            native_value,
            help_text);
        log_state(('state config horizontal-choice-index menu="%s" title="%s" select=%d count=%d entry=0x%08X label="%s" value="%s" help="%s"'):fmt(
            menu_name,
            accessxi.escape_probe_log_text(tostring(title or 'Config')),
            selected,
            count,
            entry,
            accessxi.escape_probe_log_text(native_label),
            accessxi.escape_probe_log_text(native_value),
            accessxi.escape_probe_log_text(help_text)));
        return ('%s. %s. %s.'):fmt(
            tostring(title or 'Config'),
            native_label,
            native_value);
    end

    local label_ptr = read_u32(entry + 0x44) or 0;
    local label = accessxi.plain_native_menu_label(read_probe_string(label_ptr, 180));
    if (label == '') then
        log_state(('state config horizontal-choice-missing-label menu="%s" title="%s" select=%d count=%d entry=0x%08X labelPtr=0x%08X help="%s"'):fmt(
            menu_name,
            accessxi.escape_probe_log_text(tostring(title or 'Config')),
            selected,
            count,
            entry,
            tonumber(label_ptr) or 0,
            accessxi.escape_probe_log_text(help_text)));
        return nil;
    end

    accessxi.last_native_menu_name = menu_name;
    accessxi.last_native_menu_label = label;
    accessxi.last_native_menu_selected = selected;
    accessxi.last_native_menu_tick = tick();
    accessxi.current_speech_key = ('native-known-config-horizontal-choice:%s:%d:%d:0x%08X:%s:%s'):fmt(
        menu_name,
        selected,
        count,
        entry,
        label,
        help_text);
    log_state(('state config horizontal-choice menu="%s" title="%s" select=%d count=%d entry=0x%08X labelPtr=0x%08X label="%s" help="%s"'):fmt(
        menu_name,
        accessxi.escape_probe_log_text(tostring(title or 'Config')),
        selected,
        count,
        entry,
        tonumber(label_ptr) or 0,
        accessxi.escape_probe_log_text(label),
        accessxi.escape_probe_log_text(help_text)));
    return ('%s. %s. %s'):fmt(
        tostring(title or 'Config'),
        label,
        accessxi.sentence_fragment(help_text));
end

function accessxi.config_menu_native_value_speech(menu_name, title, selected, count, entry, child, help_text)
    menu_name = tostring(menu_name or '');
    help_text = accessxi.plain_native_menu_help(help_text or '');
    selected = tonumber(selected) or 0;
    count = tonumber(count) or 0;
    entry = tonumber(entry) or 0;

    local spec = nil;
    for _, candidate in ipairs(T{
        T{
            menu = 'menu    conf3win',
            selected = 11,
            normal_count = 17,
            max_value = 50,
            help = 'Limit the number of characters shown on screen to improve frame rate.',
        },
        T{
            menu = 'menu    conf6win',
            selected = 1,
            normal_count = 17,
            max_value = 25,
            help = 'Adjust the distance of the back clipping plane of the 3D view.',
        },
        T{
            menu = 'menu    conf6win',
            selected = 4,
            normal_count = 17,
            max_value = 3,
            special_values = T{ [17] = 'Min' },
            help = 'Limit character animation rate to maintain frame rate.',
        },
        T{
            menu = 'menu    conf6win',
            selected = 7,
            normal_count = 17,
            min_value = 0,
            max_value = 5,
            value_child_offset = 0x24,
            special_values = T{
                [0] = '(4:3)',
                [1] = '(15:9)',
                [2] = '(15:10)',
                [3] = '(16:9)',
                [4] = '(16:10)',
                [5] = '(5:4)',
            },
            help = 'Adjust the background screen proportions to match your monitor\'s aspect ratio. Recommended for monitors with an aspect ratio other than 4:3.',
        },
    }) do
        if (menu_name:eq(candidate.menu, true)
            and selected == (tonumber(candidate.selected) or -1)
            and help_text:eq(candidate.help, true)) then
            spec = candidate;
            break;
        end
    end

    if (spec == nil) then
        accessxi.config_native_value_observed_key = '';
        accessxi.config_native_value_observed_count = nil;
        accessxi.config_native_value_observed_valid = false;
        accessxi.config_native_value_last_spoken_key = '';
        accessxi.config_native_value_last_spoken_context = '';
        accessxi.config_native_value_help_suppress_until = 0;
        return nil;
    end
    local normal_count = tonumber(spec.normal_count) or -1;
    local context_key = ('%s:%d:%s'):fmt(menu_name, selected, help_text);
    local min_value = tonumber(spec.min_value) or 0;
    local max_value = tonumber(spec.max_value) or 0;
    local value_source = 'child-count';
    local child_offset = tonumber(spec.value_child_offset);
    if (child_offset ~= nil and accessxi.is_probe_pointer(tonumber(child) or 0)) then
        local child_value = read_u32((tonumber(child) or 0) + child_offset);
        if (child_value ~= nil) then
            count = tonumber(child_value) or count;
            value_source = ('child+0x%02X'):fmt(child_offset);
        end
    end
    if (count < 0) then
        accessxi.config_native_value_last_spoken_key = '';
        accessxi.config_native_value_last_spoken_context = '';
        accessxi.config_native_value_help_suppress_until = 0;
        return nil;
    end
    local has_special_value = false;
    if (type(spec.special_values) == 'table'
        and spec.special_values[count] ~= nil
        and tostring(spec.special_values[count] or '') ~= '') then
        has_special_value = true;
    end
    if ((count < min_value or count > max_value) and not has_special_value) then
        accessxi.config_native_value_observed_key = context_key;
        accessxi.config_native_value_observed_count = count;
        accessxi.config_native_value_observed_valid = false;
        accessxi.config_native_value_last_spoken_key = '';
        accessxi.config_native_value_last_spoken_context = '';
        accessxi.config_native_value_help_suppress_until = 0;
        return nil;
    end

    local previous_context = tostring(accessxi.config_native_value_observed_key or '');
    local observed_active = previous_context == context_key;
    local observed_count = tonumber(accessxi.config_native_value_observed_count);
    local observed_valid = accessxi.config_native_value_observed_valid == true;
    if (not observed_active) then
        accessxi.config_native_value_last_spoken_key = '';
        accessxi.config_native_value_last_spoken_context = '';
        accessxi.config_native_value_help_suppress_until = 0;
    end
    accessxi.config_native_value_observed_key = context_key;
    accessxi.config_native_value_observed_count = count;
    accessxi.config_native_value_observed_valid = true;
    local speak_initial_value = (not observed_active
        and spec.speak_initial_value == true
        and count ~= normal_count);
    if ((not observed_active and not speak_initial_value) or (observed_valid and observed_count == count)) then
        local stable_key = ('%s:%d'):fmt(context_key, count);
        if (stable_key == tostring(accessxi.config_native_value_last_spoken_key or '')
            and context_key == tostring(accessxi.config_native_value_last_spoken_context or '')) then
            return false;
        end
        return nil;
    end

    local value_text = tostring(count);
    if (has_special_value and type(spec.special_values) == 'table') then
        local special_value = spec.special_values[count];
        value_text = tostring(special_value);
        value_source = ('%s-special'):fmt(value_source);
    elseif (tonumber(spec.percent_min) ~= nil and tonumber(spec.percent_max) ~= nil) then
        local percent_min = tonumber(spec.percent_min) or 0;
        local percent_max = tonumber(spec.percent_max) or percent_min;
        if (percent_max ~= percent_min) then
            local percent = math.floor((((count - percent_min) * 100) / (percent_max - percent_min)) + 0.5);
            if (percent < 0) then
                percent = 0;
            elseif (percent > 100) then
                percent = 100;
            end
            value_text = tostring(percent);
            value_source = ('%s-percent'):fmt(value_source);
        end
    end

    accessxi.last_native_menu_name = menu_name;
    accessxi.last_native_menu_label = help_text;
    accessxi.last_native_menu_selected = selected;
    accessxi.last_native_menu_tick = tick();
    accessxi.current_speech_key = ('native-known-config-value:%s:%d:%s:0x%08X:%s'):fmt(
        menu_name,
        selected,
        value_text,
        entry,
        help_text);
    log_state(('state config native-value menu="%s" title="%s" select=%d value=%d valueText="%s" entry=0x%08X help="%s" source="%s"'):fmt(
        menu_name,
        accessxi.escape_probe_log_text(tostring(title or 'Config')),
        selected,
        count,
        accessxi.escape_probe_log_text(value_text),
        entry,
        accessxi.escape_probe_log_text(help_text),
        value_source));
    accessxi.config_native_value_last_spoken_key = ('%s:%d'):fmt(context_key, count);
    accessxi.config_native_value_last_spoken_context = context_key;
    accessxi.config_native_value_help_suppress_until = 0;
    if (spec.value_first == true) then
        return ('%s. %s. %s'):fmt(
            tostring(title or 'Config'),
            value_text,
            accessxi.sentence_fragment(help_text));
    end
    return ('%s. %s %s.'):fmt(
        tostring(title or 'Config'),
        accessxi.sentence_fragment(help_text),
        value_text);
end

function accessxi.config_menu_speech(menu_name, title, selected, count, entry, obj, child, page, raw)
    if (not accessxi.is_config_menu_name(menu_name)) then
        return nil;
    end

    selected = tonumber(selected) or 0;
    count = tonumber(count) or 0;
    entry = tonumber(entry) or 0;

    local help_ptr = accessxi.is_probe_pointer(entry) and (read_u32(entry + 0x40) or 0) or 0;
    local help_text = accessxi.plain_native_menu_help(read_probe_string(help_ptr, 260));
    if (help_text ~= '') then
        local key_selected = selected;
        local key_count = count;
        if (key_selected < 0 or key_selected > 64) then
            key_selected = 0;
        end
        if (key_count < 0 or key_count > 256) then
            key_count = 0;
        end

        accessxi.last_native_menu_name = tostring(menu_name or '');
        accessxi.last_native_menu_label = help_text;
        accessxi.last_native_menu_selected = key_selected;
        accessxi.last_native_menu_tick = tick();
        accessxi.current_speech_key = ('native-known-config-help:%s:%d:%d:0x%08X:0x%08X:%s'):fmt(
            tostring(menu_name or ''),
            key_selected,
            key_count,
            entry,
            tonumber(help_ptr) or 0,
            help_text);
        log_state(('state config native-help menu="%s" title="%s" select=%d count=%d entry=0x%08X helpPtr=0x%08X text="%s"'):fmt(
            tostring(menu_name or ''),
            accessxi.escape_probe_log_text(tostring(title or 'Config')),
            key_selected,
            key_count,
            entry,
            tonumber(help_ptr) or 0,
            accessxi.escape_probe_log_text(help_text)));
        if (tostring(menu_name or ''):eq('menu    conf11l', true)) then
            accessxi.remember_config_log_window_category(key_selected, help_text);
        end
        local horizontal_choice_speech = accessxi.config_menu_horizontal_choice_speech(menu_name, title, key_selected, key_count, entry, child, obj, page, raw, help_text);
        if (horizontal_choice_speech ~= nil) then
            return horizontal_choice_speech;
        end
        local value_speech = accessxi.config_menu_native_value_speech(menu_name, title, key_selected, key_count, entry, child, help_text);
        if (value_speech ~= nil) then
            if (value_speech == false) then
                return nil;
            end
            return value_speech;
        end
        if (accessxi.config_volume_slider_help_repeat(menu_name, key_selected, entry, help_text)) then
            return nil;
        end
        return ('%s. %s'):fmt(tostring(title or 'Config'), accessxi.sentence_fragment(help_text));
    end

    if (selected <= 0 or count <= 0 or selected > count) then
        return nil;
    end

    if (accessxi.config_menu_uses_descriptor_resource_rows(menu_name)) then
        local label_speech = accessxi.config_menu_native_label_speech(menu_name, title, selected, count, obj, child);
        if (label_speech ~= nil) then
            return label_speech;
        end

        local resource_speech = accessxi.config_menu_descriptor_resource_speech(menu_name, title, selected, count, entry, page, raw, child);
        if (resource_speech ~= nil) then
            return resource_speech;
        end
        accessxi.log_config_descriptor_resource_probe(menu_name, title, selected, count, page, raw, child, entry);
        return nil;
    end

    local log_window_speech = accessxi.config_log_window_designation_speech(menu_name, title, selected, count, entry, page, raw, child);
    if (log_window_speech ~= nil) then
        return log_window_speech;
    end

    local label_speech = accessxi.config_menu_native_label_speech(menu_name, title, selected, count, obj, child);
    if (label_speech ~= nil) then
        return label_speech;
    end
    accessxi.log_config_menu_probe(menu_name, title, obj, selected, count, page, raw, child, entry, 'blank-help', 'blank-help');
    return nil;
end

function accessxi.status_menu_probe_desc_table(desc, selected)
    desc = tonumber(desc) or 0;
    selected = tonumber(selected) or 0;
    if (not accessxi.is_probe_pointer(desc)) then
        return '';
    end

    local base = desc;
    if (selected > 0 and selected <= 64) then
        base = desc - (selected * 0x14);
    end

    local parts = T{};
    for index = 0, 17 do
        local ptr = base + (index * 0x14);
        if (accessxi.is_probe_pointer(ptr) and parts:len() < 20) then
            parts:append(('%02d@0x%08X[%s] "%s"'):fmt(
                index,
                ptr,
                accessxi.escape_probe_log_text(accessxi.format_probe_dwords(ptr, 0, 5)),
                accessxi.escape_probe_log_text(accessxi.status_menu_probe_runs(ptr, 0x80))));
        end
    end
    return parts:concat(' || ');
end

function accessxi.status_menu_probe_string_offsets(ptr)
    ptr = tonumber(ptr) or 0;
    if (not accessxi.is_probe_pointer(ptr)) then
        return '';
    end

    local parts = T{};
    for _, off in ipairs(T{ 0x00, 0x04, 0x08, 0x0C, 0x10, 0x14, 0x18, 0x1C, 0x20, 0x24, 0x28, 0x2C, 0x30, 0x34, 0x38, 0x40, 0x46, 0x48, 0x50, 0x60, 0x70, 0x80, 0x90, 0xA0, 0xC0 }) do
        local text = clean_probe_text(read_probe_string(ptr + off));
        if (#text >= 2 and parts:len() < 28) then
            parts:append(('+%03X="%s"'):fmt(off, text:gsub('"', "'")));
        end
    end
    return parts:concat(' | ');
end

function accessxi.status_menu_probe_resource_record(menu_name, selected, label, ptr)
    ptr = tonumber(ptr) or 0;
    if (not accessxi.is_probe_pointer(ptr)) then
        return;
    end

    log_line(('statusres menu="%s" selected=%d %s=0x%08X dwords="%s" strings="%s" runs="%s"'):fmt(
        menu_name,
        selected,
        tostring(label or ''),
        ptr,
        accessxi.format_probe_dwords(ptr, 0, 48),
        accessxi.status_menu_probe_string_offsets(ptr),
        accessxi.status_menu_probe_runs(ptr, 0x180)));
    if (tostring(label or ''):eq('row2', true)) then
        return;
    end

    local desc = read_u32(ptr + 0x04) or 0;
    if (accessxi.is_probe_pointer(desc)) then
        log_line(('statusresdesc menu="%s" selected=%d %s=0x%08X desc=0x%08X dwords="%s" strings="%s" runs="%s"'):fmt(
            menu_name,
            selected,
            tostring(label or ''),
            ptr,
            desc,
            accessxi.format_probe_dwords(desc, 0, 48),
            accessxi.status_menu_probe_string_offsets(desc),
            accessxi.status_menu_probe_runs(desc, 0x180)));
    else
        log_line(('statusresdesc menu="%s" selected=%d %s=0x%08X desc=0x%08X'):fmt(
            menu_name,
            selected,
            tostring(label or ''),
            ptr,
            desc));
    end

end

function accessxi.currency_menu_probe_fields(ptr)
    ptr = tonumber(ptr) or 0;
    if (not accessxi.is_probe_pointer(ptr)) then
        return '';
    end

    local parts = T{};
    for _, off in ipairs(T{ 0x04, 0x08, 0x0C, 0x14, 0x18, 0x24, 0x28, 0x2C, 0x30, 0x34, 0x38, 0x40, 0x44, 0x48, 0x4C, 0x50, 0x54, 0x58, 0x5C, 0x60, 0x64, 0x6C, 0x78, 0x94, 0x98, 0xDC, 0xF8, 0x11C, 0x134, 0x13C, 0x140, 0x144, 0x14C }) do
        local value = read_i32(ptr + off);
        if (value ~= nil and value >= -100000000 and value <= 100000000) then
            parts:append(('+%03X=%d'):fmt(off, value));
        end
    end
    return parts:concat(' ');
end

function accessxi.currency_menu_probe_pointer(label, ptr)
    label = tostring(label or 'ptr');
    ptr = tonumber(ptr) or 0;
    if (not accessxi.is_probe_pointer(ptr)) then
        return ('%s=0x%08X'):fmt(label, ptr);
    end

    local desc04 = read_u32(ptr + 0x04) or 0;
    local desc0c = read_u32(ptr + 0x0C) or 0;
    return ('%s=0x%08X dwords000="%s" dwords040="%s" dwords080="%s" dwords0C0="%s" inline="%s" runs="%s" ptrs="%s" desc04=0x%08X desc0c=0x%08X'):fmt(
        label,
        ptr,
        accessxi.escape_probe_log_text_wide(accessxi.format_probe_dwords(ptr, 0x00, 16)),
        accessxi.escape_probe_log_text_wide(accessxi.format_probe_dwords(ptr, 0x40, 16)),
        accessxi.escape_probe_log_text_wide(accessxi.format_probe_dwords(ptr, 0x80, 16)),
        accessxi.escape_probe_log_text_wide(accessxi.format_probe_dwords(ptr, 0xC0, 16)),
        accessxi.escape_probe_log_text(accessxi.status_menu_probe_inline_strings(ptr)),
        accessxi.escape_probe_log_text(accessxi.status_menu_probe_runs(ptr, 0x180)),
        accessxi.escape_probe_log_text(accessxi.status_menu_probe_pointer_fields(ptr)),
        desc04,
        desc0c);
end

function accessxi.currency_probe_resource_label(resources, table_name, id)
    resources = resources;
    table_name = tostring(table_name or '');
    id = tonumber(id) or 0;
    if (resources == nil or table_name == '' or id < 0 or id > 65535) then
        return '';
    end

    local text = safe_call(function () return resources:GetString(table_name, id); end, '');
    text = accessxi.plain_native_menu_label(accessxi.survival_guide_text(text or ''));
    return text;
end

function accessxi.log_currency_resource_string_search(needle, max_index)
    needle = tostring(needle or ''):lower():trim();
    if (needle == '') then
        needle = 'crystal';
    end
    max_index = math.max(0, math.min(tonumber(max_index) or 1024, 65535));

    local hits = 0;
    log_line(('currencystrings begin needle="%s" max=%d'):fmt(
        accessxi.escape_probe_log_text(needle),
        max_index));

    local function log_hit(source, index, text)
        hits = hits + 1;
        log_line(('currencystrings hit source="%s" index=%d text="%s"'):fmt(
            accessxi.escape_probe_log_text(source),
            tonumber(index) or -1,
            accessxi.escape_probe_log_text(text)));
    end

    local help_bank = tonumber(accessxi.currency_native_help_bank) or 0;
    local label_bank = accessxi.currency_native_find_label_bank(help_bank);
    if (accessxi.is_probe_pointer(label_bank)) then
        for index = 0, math.min(max_index, 512) do
            local label = accessxi.currency_native_dmsg_entry(label_bank, index, 'label');
            if (label ~= '' and label:lower():find(needle, 1, true) ~= nil) then
                log_hit('currency-label-bank', index, label);
            end
            local help = accessxi.currency_native_dmsg_entry(help_bank, index, 'help');
            if (help ~= '' and help:lower():find(needle, 1, true) ~= nil) then
                log_hit('currency-help-bank', index, help);
            end
        end
    else
        log_line(('currencystrings bank unavailable helpBank=0x%08X'):fmt(help_bank));
    end

    local resources = safe_call(function () return AshitaCore:GetResourceManager(); end, nil);
    if (resources ~= nil) then
        local tables = T{
            'commands.help',
            'keyitems.names',
            'keyitems.descriptions',
            'jobpoints',
            'merits',
            'mounts.names',
            'mounts.descriptions',
            'zones.names',
            'regions',
        };
        for _, table_name in ipairs(tables) do
            for index = 0, max_index do
                local text = safe_call(function () return resources:GetString(table_name, index); end, '') or '';
                text = accessxi.plain_native_menu_label(accessxi.survival_guide_text(text));
                if (text ~= '' and text:lower():find(needle, 1, true) ~= nil) then
                    log_hit(('resource:%s'):fmt(table_name), index, text);
                end
                if (hits >= 250) then
                    log_line(('currencystrings truncated hits=%d max=%d'):fmt(hits, max_index));
                    log_line(('currencystrings end needle="%s" hits=%d max=%d'):fmt(
                        accessxi.escape_probe_log_text(needle),
                        hits,
                        max_index));
                    return hits;
                end
            end
        end
    else
        log_line('currencystrings resource-manager unavailable');
    end

    log_line(('currencystrings end needle="%s" hits=%d max=%d'):fmt(
        accessxi.escape_probe_log_text(needle),
        hits,
        max_index));
    return hits;
end

function accessxi.log_currency_native_string_range(start_index, end_index)
    start_index = math.max(0, math.min(tonumber(start_index) or 0, 65535));
    end_index = math.max(0, math.min(tonumber(end_index) or start_index, 65535));
    if (end_index < start_index) then
        local tmp = start_index;
        start_index = end_index;
        end_index = tmp;
    end
    if ((end_index - start_index) > 128) then
        end_index = start_index + 128;
    end

    local help_bank = tonumber(accessxi.currency_native_help_bank) or 0;
    local label_bank = accessxi.currency_native_find_label_bank(help_bank);
    log_line(('currencyrange begin start=%d end=%d labelBank=0x%08X helpBank=0x%08X'):fmt(
        start_index,
        end_index,
        tonumber(label_bank) or 0,
        tonumber(help_bank) or 0));

    if (not accessxi.is_probe_pointer(label_bank)) then
        log_line('currencyrange unavailable reason="missing-label-bank"');
        return 0;
    end

    local rows = 0;
    for index = start_index, end_index do
        local label, label_ptr = accessxi.currency_native_dmsg_entry(label_bank, index, 'label');
        local help, help_ptr = accessxi.currency_native_dmsg_entry(help_bank, index, 'help');
        log_line(('currencyrange index=%d labelPtr=0x%08X label="%s" helpPtr=0x%08X help="%s"'):fmt(
            index,
            tonumber(label_ptr) or 0,
            accessxi.escape_probe_log_text(label or ''),
            tonumber(help_ptr) or 0,
            accessxi.escape_probe_log_text(help or '')));
        rows = rows + 1;
    end
    log_line(('currencyrange end start=%d end=%d rows=%d'):fmt(start_index, end_index, rows));
    return rows;
end

function accessxi.currency_probe_item_label(resources, id)
    resources = resources;
    id = tonumber(id) or 0;
    if (resources == nil or id <= 0 or id > 65535) then
        return '';
    end

    local item = safe_call(function () return resources:GetItemById(id); end, nil);
    if (item == nil or item.Name == nil) then
        return '';
    end
    local name = accessxi.plain_native_menu_label(accessxi.survival_guide_text(item.Name[1] or ''));
    if (name == '') then
        return '';
    end
    return ('%s type=%d'):fmt(name, tonumber(item.Type) or 0);
end

function accessxi.log_currency_resource_candidates(selected, raw, entry, desc, row0)
    selected = tonumber(selected) or 0;
    raw = tonumber(raw) or 0;
    entry = tonumber(entry) or 0;
    desc = tonumber(desc) or 0;
    row0 = tonumber(row0) or 0;
    if (selected <= 0 or not accessxi.is_probe_pointer(entry)) then
        return;
    end

    local row_code = accessxi.is_probe_pointer(row0) and (read_u32(row0 + 0x04) or 0) or 0;
    local entry_code = read_u32(entry + 0x24) or 0;
    local entry_code2 = read_u32(entry + 0x48) or 0;
    local entry_code3 = read_u32(entry + 0x84) or 0;
    local entry_code4 = read_u32(entry + 0x98) or 0;
    local key = ('%d:%08X:%08X:%08X:%08X:%08X:%08X:%08X:%08X'):fmt(
        selected,
        raw,
        entry,
        desc,
        row_code,
        entry_code,
        entry_code2,
        entry_code3,
        entry_code4);
    if (key == tostring(accessxi.last_currency_candidate_probe_key or '')) then
        return;
    end
    accessxi.last_currency_candidate_probe_key = key;

    local resources = safe_call(function () return AshitaCore:GetResourceManager(); end, nil);
    local candidates = T{};
    local seen = {};
    local function add_candidate(name, value)
        value = tonumber(value) or 0;
        if (value < 0 or value > 65535) then
            return;
        end
        local dedupe = tostring(value);
        if (seen[dedupe] == true) then
            return;
        end
        seen[dedupe] = true;
        candidates:append(T{ name = tostring(name or ''), value = value });
    end

    add_candidate('selected', selected);
    add_candidate('raw', raw);
    add_candidate('raw+1', raw + 1);
    add_candidate('rowCode', row_code);
    add_candidate('entry24.low16', bit.band(entry_code, 0xFFFF));
    add_candidate('entry24.mid8', bit.band(bit.rshift(entry_code, 8), 0xFF));
    add_candidate('entry24.hi16', bit.band(bit.rshift(entry_code, 16), 0xFFFF));
    add_candidate('entry48.hi8', bit.band(bit.rshift(entry_code2, 24), 0xFF));
    add_candidate('entry84.low16', bit.band(entry_code3, 0xFFFF));
    add_candidate('entry98.low16', bit.band(entry_code4, 0xFFFF));

    local parts = T{};
    for _, candidate in ipairs(candidates) do
        local id = tonumber(candidate.value) or 0;
        local currency = accessxi.currency_probe_resource_label(resources, 'items.currency', id);
        if (currency ~= '') then
            parts:append(('%s=%d currency="%s"'):fmt(
                tostring(candidate.name or ''),
                id,
                accessxi.escape_probe_log_text(currency)));
        end
    end

    log_line(('currencyres selected=%d raw=0x%08X entry=0x%08X desc=0x%08X row0=0x%08X rowCode=0x%08X entry24=0x%08X entry48=0x%08X entry84=0x%08X entry98=0x%08X hits="%s"'):fmt(
        selected,
        raw,
        entry,
        desc,
        row0,
        row_code,
        entry_code,
        entry_code2,
        entry_code3,
        entry_code4,
        accessxi.escape_probe_log_text(parts:concat(' || '))));
end

function accessxi.log_currency_text_graph_probe(selected, raw, obj, child, entry, desc, row0, row1, row2)
    selected = tonumber(selected) or 0;
    raw = tonumber(raw) or 0;
    obj = tonumber(obj) or 0;
    child = tonumber(child) or 0;
    entry = tonumber(entry) or 0;
    desc = tonumber(desc) or 0;
    row0 = tonumber(row0) or 0;
    row1 = tonumber(row1) or 0;
    row2 = tonumber(row2) or 0;
    if (selected <= 0 or not accessxi.is_probe_pointer(obj)) then
        return;
    end

    local entry_code = accessxi.is_probe_pointer(entry) and (read_u32(entry + 0x24) or 0) or 0;
    local row_code = accessxi.is_probe_pointer(row0) and (read_u32(row0 + 0x04) or 0) or 0;
    local key = ('%d:%08X:%08X:%08X:%08X:%08X:%08X:%08X:%08X:%08X'):fmt(
        selected,
        raw,
        obj,
        child,
        entry,
        desc,
        row0,
        row1,
        entry_code,
        row_code);
    if (key == tostring(accessxi.last_currency_text_graph_probe_key or '')) then
        return;
    end
    accessxi.last_currency_text_graph_probe_key = key;

    accessxi.menu_dump_sequence = (accessxi.menu_dump_sequence or 0) + 1;
    local seq = accessxi.menu_dump_sequence;
    local old_textptr_budget = accessxi.menu_dump_textptr_budget;
    local old_render_budget = accessxi.menu_dump_render_node_budget;
    accessxi.menu_dump_textptr_budget = 96;
    accessxi.menu_dump_render_node_budget = 18;

    local seeds = T{};
    local seen = {};
    local function add_seed(label, ptr)
        ptr = tonumber(ptr) or 0;
        if (accessxi.is_probe_pointer(ptr) and seen[ptr] ~= true and seeds:len() < 44) then
            seen[ptr] = true;
            seeds:append(T{ label = tostring(label or 'ptr'), ptr = ptr });
        end
    end
    local function add_pointer_fields(prefix, ptr, start_offset, end_offset, max_count)
        ptr = tonumber(ptr) or 0;
        if (not accessxi.is_probe_pointer(ptr)) then
            return;
        end
        local count = 0;
        for off = start_offset, end_offset, 4 do
            if (count >= max_count or seeds:len() >= 44) then
                break;
            end
            local target = read_u32(ptr + off) or 0;
            if (accessxi.is_probe_pointer(target) and seen[target] ~= true) then
                add_seed(('%s+%03X'):fmt(prefix, off), target);
                count = count + 1;
            end
        end
    end

    add_seed('obj', obj);
    add_seed('child', child);
    add_seed('entry', entry);
    add_seed('desc', desc);
    add_seed('row0', row0);
    add_seed('row1', row1);
    add_seed('row2', row2);
    add_pointer_fields('obj', obj, 0x00, 0x180, 14);
    add_pointer_fields('child', child, 0x00, 0x140, 14);
    add_pointer_fields('entry', entry, 0x00, 0x180, 14);
    add_pointer_fields('desc', desc, 0x00, 0x180, 22);
    add_pointer_fields('row0', row0, 0x00, 0x140, 10);
    add_pointer_fields('row1', row1, 0x00, 0x140, 10);

    log_line(('currencytext seq=%d begin selected=%d raw=0x%08X obj=0x%08X child=0x%08X entry=0x%08X desc=0x%08X row0=0x%08X row1=0x%08X row2=0x%08X entry24=0x%08X rowCode=0x%08X seeds=%d'):fmt(
        seq,
        selected,
        raw,
        obj,
        child,
        entry,
        desc,
        row0,
        row1,
        row2,
        entry_code,
        row_code,
        seeds:len()));

    for i, seed in ipairs(seeds) do
        local label = ('currency.%02d.%s'):fmt(i, tostring(seed.label or 'ptr'));
        local ptr = tonumber(seed.ptr) or 0;
        log_line(('currencytext seq=%d seed=%d label="%s" ptr=0x%08X strings="%s" utf16="%s" dwords=%s'):fmt(
            seq,
            i,
            accessxi.escape_probe_log_text(tostring(seed.label or 'ptr')),
            ptr,
            accessxi.probe_strings_at(ptr),
            accessxi.probe_utf16le_runs_at(ptr, 0x180, 10),
            accessxi.format_probe_dwords(ptr, 0, 24)));
        accessxi.log_probe_short_text_runs(seq, label, ptr, 0x300, 2, 14);
        accessxi.log_probe_pointer_text_targets(seq, label, ptr, 0x00, 0x17C, 12);
        if (i <= 4 or tostring(seed.label or ''):match('^child')) then
            accessxi.log_survival_guide_render_node_probe(seq, label .. '.render', ptr, 0);
        end
    end

    log_line(('currencytext seq=%d end seeds=%d'):fmt(seq, seeds:len()));
    accessxi.menu_dump_textptr_budget = old_textptr_budget;
    accessxi.menu_dump_render_node_budget = old_render_budget;
end

function accessxi.currency_probe_index_hits(label, ptr, raw, selected, count)
    label = tostring(label or 'ptr');
    ptr = tonumber(ptr) or 0;
    raw = tonumber(raw) or 0;
    selected = tonumber(selected) or 0;
    count = tonumber(count) or 0;
    if (not accessxi.is_probe_pointer(ptr)) then
        return '';
    end

    local parts = T{};
    for off = 0x00, 0x180, 4 do
        local value = read_i32(ptr + off);
        if (value ~= nil) then
            if (value == raw) then
                parts:append(('%s+%03X=raw'):fmt(label, off));
            elseif (value == selected) then
                parts:append(('%s+%03X=sel'):fmt(label, off));
            elseif (count > 0 and value == count) then
                parts:append(('%s+%03X=count'):fmt(label, off));
            end
        end
        if (parts:len() >= 24) then
            break;
        end
    end
    return parts:concat(' ');
end

function accessxi.currency_probe_stride_candidates(list_ptr, raw)
    list_ptr = tonumber(list_ptr) or 0;
    raw = tonumber(raw) or 0;
    if (not accessxi.is_probe_pointer(list_ptr) or raw < 0 or raw > 256) then
        return '';
    end

    local parts = T{};
    for _, stride in ipairs(T{ 4, 8, 12, 16, 20, 24, 28, 32, 40, 48 }) do
        local ptr = list_ptr + (raw * stride);
        if (accessxi.is_probe_pointer(ptr)) then
            parts:append(('s%d@0x%08X[%s] "%s" ptrs="%s"'):fmt(
                stride,
                ptr,
                accessxi.escape_probe_log_text(accessxi.format_probe_dwords(ptr, 0x00, 8)),
                accessxi.escape_probe_log_text(accessxi.status_menu_probe_runs(ptr, 0x80)),
                accessxi.escape_probe_log_text(accessxi.status_menu_probe_pointer_fields(ptr))));
        end
    end
    return parts:concat(' || ');
end

function accessxi.currency_probe_ascii_entries(ptr, length, limit)
    ptr = tonumber(ptr) or 0;
    if (not accessxi.is_probe_pointer(ptr)) then
        return T{};
    end

    length = tonumber(length) or 0x400;
    limit = tonumber(limit) or 64;
    local entries = T{};
    local run = T{};
    local run_start = 0;
    for off = 0, length do
        local byte_value = off < length and read_u8(ptr + off) or nil;
        if (byte_value ~= nil and accessxi.probe_printable_ascii(byte_value)) then
            if (#run == 0) then
                run_start = off;
            end
            run:append(string.char(byte_value));
        else
            local text = accessxi.decode_ffxi_menu_text_fragment(run:concat(''));
            if (accessxi.probe_text_candidate_ok(text, 3)) then
                entries:append(T{ offset = run_start, text = text });
                if (#entries >= limit) then
                    return entries;
                end
            end
            run = T{};
        end
    end
    return entries;
end

function accessxi.currency_probe_ascii_entry_summary(ptr, raw, top)
    ptr = tonumber(ptr) or 0;
    raw = tonumber(raw) or 0;
    top = tonumber(top) or 0;
    if (not accessxi.is_probe_pointer(ptr)) then
        return '';
    end

    local scan_ptr = ptr;
    local base_adjust = 0;
    if (ptr >= 0x01000020) then
        scan_ptr = ptr - 0x20;
        base_adjust = -0x20;
    end

    local entries = accessxi.currency_probe_ascii_entries(scan_ptr, 0x500, 96);
    local parts = T{};
    for i, entry in ipairs(entries) do
        if (i <= 20 or math.abs((i - 1) - raw) <= 3 or math.abs((i - 1) - top) <= 3) then
            parts:append(('%d@%+04X="%s"'):fmt(
                i - 1,
                (tonumber(entry.offset) or 0) + base_adjust,
                accessxi.escape_probe_log_text(entry.text or '')));
        end
        if (parts:len() >= 36) then
            break;
        end
    end
    return parts:concat(' | ');
end

function accessxi.log_currency_row_record_probe(selected, raw, entry, desc, row0, row1, child)
    selected = tonumber(selected) or 0;
    raw = tonumber(raw) or 0;
    entry = tonumber(entry) or 0;
    desc = tonumber(desc) or 0;
    row0 = tonumber(row0) or 0;
    row1 = tonumber(row1) or 0;
    child = tonumber(child) or 0;
    if (selected <= 0 or not accessxi.is_probe_pointer(row0)) then
        return;
    end

    local row_code = read_u32(row0 + 0x04) or 0;
    local entry_code = accessxi.is_probe_pointer(entry) and (read_u32(entry + 0x24) or 0) or 0;
    local entry_flag = accessxi.is_probe_pointer(entry) and (read_u32(entry + 0x48) or 0) or 0;
    local key = ('%d:%08X:%08X:%08X:%08X:%08X:%08X'):fmt(
        selected,
        raw,
        entry,
        desc,
        row0,
        row_code,
        entry_flag);
    if (key == tostring(accessxi.last_currency_row_record_probe_key or '')) then
        return;
    end
    accessxi.last_currency_row_record_probe_key = key;

    log_line(('currencyrow selected=%d raw=0x%08X entry=0x%08X desc=0x%08X row0=0x%08X row1=0x%08X child=0x%08X rowCode=0x%08X entry24=0x%08X entry48=0x%08X row0_000="%s" row0_080="%s" row0_0C0="%s" row0_100="%s" row0_140="%s" row0_runs="%s" row1_runs="%s" child080="%s" child0C0="%s"'):fmt(
        selected,
        raw,
        entry,
        desc,
        row0,
        row1,
        child,
        row_code,
        entry_code,
        entry_flag,
        accessxi.escape_probe_log_text_wide(accessxi.format_probe_dwords(row0, 0x00, 24)),
        accessxi.escape_probe_log_text_wide(accessxi.format_probe_dwords(row0, 0x80, 24)),
        accessxi.escape_probe_log_text_wide(accessxi.format_probe_dwords(row0, 0xC0, 24)),
        accessxi.escape_probe_log_text_wide(accessxi.format_probe_dwords(row0, 0x100, 24)),
        accessxi.escape_probe_log_text_wide(accessxi.format_probe_dwords(row0, 0x140, 24)),
        accessxi.escape_probe_log_text(accessxi.status_menu_probe_runs(row0, 0x1A0)),
        accessxi.escape_probe_log_text(accessxi.status_menu_probe_runs(row1, 0x180)),
        accessxi.escape_probe_log_text_wide(accessxi.format_probe_dwords(child, 0x80, 24)),
        accessxi.escape_probe_log_text_wide(accessxi.format_probe_dwords(child, 0xC0, 24))));

    local function currency_probe_ascii_dword(value)
        value = tonumber(value) or 0;
        if (value <= 0) then
            return false;
        end
        for i = 0, 3 do
            local b = math.floor(value / (256 ^ i)) % 256;
            if (b < 0x20 or b > 0x7E) then
                return false;
            end
        end
        return true;
    end

    local function currency_probe_real_pointer(value)
        value = tonumber(value) or 0;
        return (value >= 0x04000000
            and value < 0x70000000
            and accessxi.is_probe_pointer(value)
            and not currency_probe_ascii_dword(value));
    end

    local seen = {};
    local parts = T{};
    local function add_pointer(source, ptr)
        ptr = tonumber(ptr) or 0;
        if (currency_probe_real_pointer(ptr) and seen[ptr] ~= true and parts:len() < 18) then
            seen[ptr] = true;
            parts:append(('%s->0x%08X dwords="%s" runs="%s" ptrs="%s"'):fmt(
                tostring(source or ''),
                ptr,
                accessxi.escape_probe_log_text(accessxi.format_probe_dwords(ptr, 0, 12)),
                accessxi.escape_probe_log_text(accessxi.status_menu_probe_runs(ptr, 0x120)),
                accessxi.escape_probe_log_text(accessxi.status_menu_probe_pointer_fields(ptr))));
        end
    end
    for off = 0x00, 0x180, 4 do
        add_pointer(('row0+%03X'):fmt(off), read_u32(row0 + off) or 0);
    end
    for off = 0x00, 0x100, 4 do
        add_pointer(('entry+%03X'):fmt(off), accessxi.is_probe_pointer(entry) and (read_u32(entry + off) or 0) or 0);
    end
    if (parts:len() > 0) then
        log_line(('currencyrowptr selected=%d raw=0x%08X %s'):fmt(
            selected,
            raw,
            parts:concat(' || ')));
    end

    local function currency_frame_name_at(ptr)
        ptr = tonumber(ptr) or 0;
        if (not accessxi.is_probe_pointer(ptr)) then
            return '';
        end

        local text = accessxi.status_menu_probe_runs(ptr, 0x100);
        local names = T{
            'menu    cnqframe',
            'menu    conquer1',
            'menu    conq6sta',
            'menu    conq3pts',
            'menu    beseige1',
            'menu    beseige2',
            'menu    imperial',
            'menu    allied',
            'menu    colopoin',
        };
        for _, name in ipairs(names) do
            if (text:contains(name, true)) then
                return name;
            end
        end
        return '';
    end

    local function currency_frame_hits_for_ptr(label, ptr, seen_hits)
        ptr = tonumber(ptr) or 0;
        if (not accessxi.is_probe_pointer(ptr)) then
            return '';
        end

        seen_hits = seen_hits or {};
        local hits = T{};
        local function add_hit(source, target, name)
            target = tonumber(target) or 0;
            name = tostring(name or '');
            if (name == '' or target == 0) then
                return;
            end
            local key = ('%s:%08X:%s'):fmt(source, target, name);
            if (seen_hits[key] == true or hits:len() >= 16) then
                return;
            end
            seen_hits[key] = true;
            hits:append(('%s->0x%08X "%s"'):fmt(source, target, accessxi.escape_probe_log_text(name)));
        end

        for off = 0x00, 0x180, 4 do
            local direct = read_u32(ptr + off) or 0;
            local direct_name = currency_frame_name_at(direct);
            add_hit(('%s+%03X'):fmt(label, off), direct, direct_name);

            if (currency_probe_real_pointer(direct)) then
                for index = 0, 15 do
                    local nested = read_u32(direct + (index * 4)) or 0;
                    local nested_name = currency_frame_name_at(nested);
                    add_hit(('%s+%03X[%02d]'):fmt(label, off, index), nested, nested_name);
                end
            end
        end

        return hits:concat(' | ');
    end

    local top = accessxi.is_probe_pointer(child) and (tonumber(read_i32(child + 0x38)) or 0) or 0;
    local row_base = row0;
    local selected_offset = (selected - 1) * 0x40;
    if (selected_offset > 0 and row0 > selected_offset) then
        row_base = row0 - selected_offset;
    end
    if (accessxi.is_probe_pointer(row_base)) then
        local logical = row_base + (raw * 0x40);
        local visual = row_base + ((selected - 1) * 0x40);
        local top_row = row_base + (top * 0x40);
        local previous = raw > 0 and (row_base + ((raw - 1) * 0x40)) or 0;
        local next_row = row_base + ((raw + 1) * 0x40);
        local function row_summary(label, ptr)
            ptr = tonumber(ptr) or 0;
            if (not accessxi.is_probe_pointer(ptr)) then
                return ('%s=0x%08X'):fmt(label, ptr);
            end
            return ('%s=0x%08X code=0x%08X visual=%d word14=0x%08X word18=0x%08X menu="%s" runs="%s" ptrs="%s" dwords="%s"'):fmt(
                label,
                ptr,
                read_u32(ptr + 0x04) or 0,
                read_u16(ptr + 0x10) or 0,
                read_u32(ptr + 0x14) or 0,
                read_u32(ptr + 0x18) or 0,
                accessxi.escape_probe_log_text(clean_probe_text(read_probe_string(ptr + 0x24))),
                accessxi.escape_probe_log_text(accessxi.status_menu_probe_runs(ptr, 0x80)),
                accessxi.escape_probe_log_text(accessxi.status_menu_probe_pointer_fields(ptr)),
                accessxi.escape_probe_log_text(accessxi.format_probe_dwords(ptr, 0, 16)));
        end
        log_line(('currencyrowlogical selected=%d raw=0x%08X top=%d base=0x%08X %s || %s || %s || %s || %s'):fmt(
            selected,
            raw,
            top,
            row_base,
            row_summary('logical', logical),
            row_summary('visual', visual),
            row_summary('top', top_row),
            row_summary('previous', previous),
            row_summary('next', next_row)));

        local frame_seen = {};
        local frame_hits = T{};
        local function append_frame_hits(label, ptr)
            local hits = currency_frame_hits_for_ptr(label, ptr, frame_seen);
            if (hits ~= '') then
                frame_hits:append(hits);
            end
        end
        append_frame_hits('logical', logical);
        append_frame_hits('visual', visual);
        append_frame_hits('top', top_row);
        append_frame_hits('previous', previous);
        append_frame_hits('next', next_row);
        if (accessxi.is_probe_pointer(row1)) then
            append_frame_hits('row1', row1);
        end
        if (frame_hits:len() > 0) then
            log_line(('currencyrowframes selected=%d raw=0x%08X top=%d base=0x%08X %s'):fmt(
                selected,
                raw,
                top,
                row_base,
                frame_hits:concat(' || ')));
        end

        if (accessxi.is_probe_pointer(row1)) then
            local ref_seen = {};
            local ref_parts = T{};
            for off = 0x00, 0x180, 4 do
                local ptr = read_u32(row1 + off) or 0;
                if (currency_probe_real_pointer(ptr) and ref_seen[ptr] ~= true) then
                    ref_seen[ptr] = true;
                    local direct = clean_probe_text(read_probe_string(ptr, 96));
                    local plus24 = clean_probe_text(read_probe_string(ptr + 0x24, 96));
                    local plus46 = clean_probe_text(read_probe_string(ptr + 0x46, 96));
                    local runs = accessxi.status_menu_probe_runs(ptr, 0x180);
                    if ((direct ~= '' or plus24 ~= '' or plus46 ~= '' or runs ~= '') and ref_parts:len() < 18) then
                        ref_parts:append(('+%03X=0x%08X s="%s" s24="%s" s46="%s" dwords="%s" runs="%s"'):fmt(
                            off,
                            ptr,
                            accessxi.escape_probe_log_text(direct),
                            accessxi.escape_probe_log_text(plus24),
                            accessxi.escape_probe_log_text(plus46),
                            accessxi.escape_probe_log_text(accessxi.format_probe_dwords(ptr, 0, 12)),
                            accessxi.escape_probe_log_text(runs)));
                    end
                end
            end
            if (ref_parts:len() > 0) then
                log_line(('currencyrowrefs selected=%d raw=0x%08X row1=0x%08X %s'):fmt(
                    selected,
                    raw,
                    row1,
                    ref_parts:concat(' || ')));
            end
        end

        if (accessxi.is_probe_pointer(row1)) then
            local chain_seen = {};
            local chain_parts = T{};
            local function pointer_detail(label, ptr)
                ptr = tonumber(ptr) or 0;
                if (not currency_probe_real_pointer(ptr) or chain_seen[ptr] == true or chain_parts:len() >= 18) then
                    return;
                end
                chain_seen[ptr] = true;
                chain_parts:append(('%s=0x%08X s="%s" s24="%s" s46="%s" dwords="%s" runs="%s" ptrs="%s"'):fmt(
                    tostring(label or ''),
                    ptr,
                    accessxi.escape_probe_log_text(clean_probe_text(read_probe_string(ptr, 96))),
                    accessxi.escape_probe_log_text(clean_probe_text(read_probe_string(ptr + 0x24, 96))),
                    accessxi.escape_probe_log_text(clean_probe_text(read_probe_string(ptr + 0x46, 96))),
                    accessxi.escape_probe_log_text(accessxi.format_probe_dwords(ptr, 0, 16)),
                    accessxi.escape_probe_log_text(accessxi.status_menu_probe_runs(ptr, 0x180)),
                    accessxi.escape_probe_log_text(accessxi.status_menu_probe_pointer_fields(ptr))));
            end

            for off = 0x00, 0x180, 4 do
                local ptr = read_u32(row1 + off) or 0;
                if (currency_frame_name_at(ptr) == 'menu    cnqframe') then
                    pointer_detail(('row1+%03X'):fmt(off), ptr);
                    for child_off = 0x00, 0x80, 4 do
                        pointer_detail(('row1+%03X+%03X'):fmt(off, child_off), read_u32(ptr + child_off) or 0);
                    end
                end
            end
            if (chain_parts:len() > 0) then
                log_line(('currencyrowframechain selected=%d raw=0x%08X row1=0x%08X %s'):fmt(
                    selected,
                    raw,
                    row1,
                    chain_parts:concat(' || ')));
            end
        end
    end
end

function accessxi.log_currency_logical_probe(selected, count, raw, obj, child, entry)
    selected = tonumber(selected) or 0;
    count = tonumber(count) or 0;
    raw = tonumber(raw) or 0;
    obj = tonumber(obj) or 0;
    child = tonumber(child) or 0;
    entry = tonumber(entry) or 0;

    local hits = T{};
    local obj_hits = accessxi.currency_probe_index_hits('obj', obj, raw, selected, count);
    local child_hits = accessxi.currency_probe_index_hits('child', child, raw, selected, count);
    local entry_hits = accessxi.currency_probe_index_hits('entry', entry, raw, selected, count);
    local child_list = read_u32(child + 0x64) or 0;
    if (obj_hits ~= '') then hits:append(obj_hits); end
    if (child_hits ~= '') then hits:append(child_hits); end
    if (entry_hits ~= '') then hits:append(entry_hits); end

    local top = read_i32(child + 0x38) or 0;
    log_line(('currencylogic selected=%d count=%d raw=0x%08X obj=0x%08X child=0x%08X entry=0x%08X obj24=%d obj28=%d obj4C=%d obj58=0x%08X child24=%d child28=%d child30=0x%08X child34=0x%08X child38=%d child3C=%d child48=%d child58=0x%08X child5C=0x%08X child64=0x%08X entry24=0x%08X entry40=0x%08X entry44=0x%08X hits="%s" child000="%s" child040="%s" list000="%s" list080="%s" asciiEntries="%s" stride="%s"'):fmt(
        selected,
        count,
        raw,
        obj,
        child,
        entry,
        read_i32(obj + 0x24) or -999,
        read_i32(obj + 0x28) or -999,
        read_i32(obj + 0x4C) or -999,
        read_u32(obj + 0x58) or 0,
        read_i32(child + 0x24) or -999,
        read_i32(child + 0x28) or -999,
        read_u32(child + 0x30) or 0,
        read_u32(child + 0x34) or 0,
        top,
        read_i32(child + 0x3C) or -999,
        read_i32(child + 0x48) or -999,
        read_u32(child + 0x58) or 0,
        read_u32(child + 0x5C) or 0,
        child_list,
        read_u32(entry + 0x24) or 0,
        read_u32(entry + 0x40) or 0,
        read_u32(entry + 0x44) or 0,
        accessxi.escape_probe_log_text_wide(hits:concat(' ')),
        accessxi.escape_probe_log_text_wide(accessxi.format_probe_dwords(child, 0x00, 16)),
        accessxi.escape_probe_log_text_wide(accessxi.format_probe_dwords(child, 0x40, 16)),
        accessxi.escape_probe_log_text_wide(accessxi.format_probe_dwords(child_list, 0x00, 32)),
        accessxi.escape_probe_log_text_wide(accessxi.format_probe_dwords(child_list, 0x80, 32)),
        accessxi.escape_probe_log_text_wide(accessxi.currency_probe_ascii_entry_summary(child_list, raw, top)),
        accessxi.escape_probe_log_text_wide(accessxi.currency_probe_stride_candidates(child_list, raw))));
end

function accessxi.log_currency_menu_probe(menu_name, title, obj, selected, count, page, raw, child, entry, reason)
    menu_name = tostring(menu_name or '');
    if (not menu_name:eq('menu    evitem', true)) then
        return;
    end
    local now = tick();
    if (now >= (tonumber(accessxi.currency_probe_until) or 0)) then
        return;
    end

    obj = tonumber(obj) or 0;
    if (not accessxi.is_probe_pointer(obj)) then
        return;
    end

    selected = tonumber(selected) or 0;
    count = tonumber(count) or 0;
    page = tonumber(page) or 0;
    raw = tonumber(raw) or 0;
    child = tonumber(child) or 0;
    entry = tonumber(entry) or 0;

    local fields = accessxi.currency_menu_probe_fields(obj);
    local key = ('%s:0x%08X:%d:%d:%d:0x%08X:0x%08X:0x%08X:%s'):fmt(
        menu_name,
        obj,
        selected,
        count,
        page,
        raw,
        child,
        entry,
        fields);
    if (key == tostring(accessxi.last_currency_menu_probe_key or '')
        and (now - (tonumber(accessxi.last_currency_menu_probe_tick) or 0)) < 1000) then
        return;
    end
    accessxi.last_currency_menu_probe_key = key;
    accessxi.last_currency_menu_probe_tick = now;

    log_line(('currencyprobe menu="%s" title="%s" reason="%s" obj=0x%08X selected=%d count=%d page=%d raw=0x%08X child=0x%08X entry=0x%08X fields="%s"'):fmt(
        menu_name,
        tostring(title or ''),
        tostring(reason or ''),
        obj,
        selected,
        count,
        page,
        raw,
        child,
        entry,
        accessxi.escape_probe_log_text(fields)));

    accessxi.log_currency_packet_cache('currencyprobe-menu', false);
    accessxi.log_currency_logical_probe(selected, count, raw, obj, child, entry);
    log_line(('currencyprobe obj %s'):fmt(accessxi.currency_menu_probe_pointer('obj', obj)));
    if (accessxi.is_probe_pointer(entry)) then
        log_line(('currencyprobe entry %s'):fmt(accessxi.currency_menu_probe_pointer('entry', entry)));
        local desc = read_u32(entry + 0x0C) or 0;
        if (accessxi.is_probe_pointer(desc)) then
            local row0 = read_u32(desc + 0x00) or 0;
            local row1 = read_u32(desc + 0x04) or 0;
            local row2 = read_u32(desc + 0x08) or 0;
            if (accessxi.currency_packet_menu_speech_enabled == true) then
                accessxi.log_currency_resource_candidates(selected, raw, entry, desc, row0);
            end
            accessxi.log_currency_row_record_probe(selected, raw, entry, desc, row0, row1, child);
            if (now < (tonumber(accessxi.currency_text_probe_until) or 0)) then
                accessxi.log_currency_text_graph_probe(selected, raw, obj, child, entry, desc, row0, row1, row2);
            end
            log_line(('currencyprobe desc %s row0=0x%08X row1=0x%08X row2=0x%08X'):fmt(
                accessxi.currency_menu_probe_pointer('desc', desc),
                row0,
                row1,
                row2));
            if (accessxi.is_probe_pointer(row0)) then
                log_line(('currencyprobe row0 %s'):fmt(accessxi.currency_menu_probe_pointer('row0', row0)));
            end
            if (accessxi.is_probe_pointer(row1)) then
                log_line(('currencyprobe row1 %s'):fmt(accessxi.currency_menu_probe_pointer('row1', row1)));
            end
            if (accessxi.is_probe_pointer(row2)) then
                log_line(('currencyprobe row2 %s'):fmt(accessxi.currency_menu_probe_pointer('row2', row2)));
            end
        end
    end
    if (accessxi.is_probe_pointer(child)) then
        log_line(('currencyprobe child %s'):fmt(accessxi.currency_menu_probe_pointer('child', child)));
    end
end

function accessxi.log_currency_order_probe(menu_name, title, obj, selected, count, page, raw, child, entry, reason)
    menu_name = tostring(menu_name or '');
    if (not menu_name:eq('menu    evitem', true)) then
        return;
    end
    local now = tick();
    if (now >= (tonumber(accessxi.currency_order_probe_until) or 0)) then
        return;
    end

    obj = tonumber(obj) or 0;
    selected = tonumber(selected) or 0;
    count = tonumber(count) or 0;
    page = tonumber(page) or 0;
    raw = tonumber(raw) or 0;
    child = tonumber(child) or 0;
    entry = tonumber(entry) or 0;

    local label_ptr = accessxi.is_probe_pointer(entry) and (read_u32(entry + 0x44) or 0) or 0;
    local help_ptr = accessxi.is_probe_pointer(entry) and (read_u32(entry + 0x40) or 0) or 0;
    local direct_label = accessxi.plain_native_menu_label(read_probe_string(label_ptr, 220));
    local direct_help = accessxi.plain_native_menu_help(read_probe_string(help_ptr, 260));
    local desc_help, row2, desc = accessxi.status_menu_native_description_for_entry(entry);
    local child_label = '';
    local child_mode = '';
    if (accessxi.is_probe_pointer(child) and selected > 0 and count > 0 and selected <= count) then
        child_label, child_mode = accessxi.native_query_label_for_selection(child, selected, count, 'plain');
        child_label = accessxi.plain_native_menu_label(child_label or '');
    end
    local mapped = '';
    if (accessxi.currency_packet_menu_speech_enabled == true) then
        local info = accessxi.currency_menu_resource_for_entry(entry, title, selected, raw);
        if (info ~= nil) then
            mapped = ('packet=0x%03X id=%d off=0x%02X field="%s" label="%s" value=%s page=%d'):fmt(
                tonumber(info.resource_type) or 0,
                tonumber(info.id) or 0,
                tonumber(info.resource_id) or 0,
                accessxi.escape_probe_log_text(info.field or ''),
                accessxi.escape_probe_log_text(info.label or ''),
                accessxi.format_currency_number(info.value),
                tonumber(info.page) or 0);
        end
    end
    local logical_id = accessxi.currency_menu_native_logical_id(child, raw);
    local dmsg_candidates = accessxi.currency_native_label_candidates_for_logical(logical_id);
    accessxi.log_currency_known_label_probe();

    local key = ('%s:%d:%d:%d:%d:%s:0x%08X:%s:%s:%s:%s:%s'):fmt(
        menu_name,
        selected,
        count,
        page,
        raw,
        tostring(logical_id or ''),
        entry,
        direct_label,
        direct_help,
        desc_help,
        mapped,
        dmsg_candidates);
    if (key == tostring(accessxi.last_currency_order_probe_key or '')) then
        return;
    end
    accessxi.last_currency_order_probe_key = key;

    log_line(('currencyorder reason="%s" menu="%s" title="%s" selected=%d count=%d page=%d raw=%d logical=%d obj=0x%08X child=0x%08X entry=0x%08X desc=0x%08X row2=0x%08X labelPtr=0x%08X helpPtr=0x%08X childMode="%s" childLabel="%s" directLabel="%s" directHelp="%s" descHelp="%s" mapped="%s" dmsg="%s"'):fmt(
        tostring(reason or ''),
        menu_name,
        accessxi.escape_probe_log_text(title or ''),
        selected,
        count,
        page,
        raw,
        tonumber(logical_id) or -1,
        obj,
        child,
        entry,
        tonumber(desc) or 0,
        tonumber(row2) or 0,
        label_ptr,
        help_ptr,
        accessxi.escape_probe_log_text(child_mode or ''),
        accessxi.escape_probe_log_text(child_label or ''),
        accessxi.escape_probe_log_text(direct_label or ''),
        accessxi.escape_probe_log_text(direct_help or ''),
        accessxi.escape_probe_log_text(desc_help or ''),
        mapped,
        accessxi.escape_probe_log_text(dmsg_candidates or '')));

    accessxi.log_currency_native_id_probe(selected, count, raw, child);
    accessxi.log_currency_native_idproof_probe(selected, count, raw, child);
    accessxi.log_currency_visible_rows_probe(selected, count, raw, child, desc);
    accessxi.log_currency_visible_render_probe(obj, child, selected, count, raw);
    accessxi.log_currency_native_record_probe(selected, count, raw, obj, child, entry, desc);
end

function accessxi.log_currency_native_pointer_probe(selected, count, raw, obj, child, entry, desc, row2)
    selected = tonumber(selected) or 0;
    count = tonumber(count) or 0;
    raw = tonumber(raw) or 0;
    obj = tonumber(obj) or 0;
    child = tonumber(child) or 0;
    entry = tonumber(entry) or 0;
    desc = tonumber(desc) or 0;
    row2 = tonumber(row2) or 0;

    local seen = {};
    local parts = T{};
    local function pointerish(value)
        value = tonumber(value) or 0;
        if (not accessxi.is_probe_pointer(value)) then
            return false;
        end
        -- Skip common packed ASCII/glyph words. Real pointers here include the
        -- static 04A/04B d_msg pools and live row/script heaps.
        local printable = true;
        for i = 0, 3 do
            local b = math.floor(value / (256 ^ i)) % 256;
            if (b < 0x20 or b > 0x7E) then
                printable = false;
                break;
            end
        end
        return not printable;
    end
    local function add_ptr(source, ptr)
        ptr = tonumber(ptr) or 0;
        if (not pointerish(ptr) or seen[ptr] == true or parts:len() >= 28) then
            return;
        end
        seen[ptr] = true;
        local s0 = clean_probe_text(read_probe_string(ptr, 260));
        local s24 = clean_probe_text(read_probe_string(ptr + 0x24, 220));
        local s46 = clean_probe_text(read_probe_string(ptr + 0x46, 220));
        local runs = accessxi.status_menu_probe_runs(ptr, 0x160);
        parts:append(('%s=0x%08X s="%s" s24="%s" s46="%s" dwords="%s" runs="%s"'):fmt(
            tostring(source or ''),
            ptr,
            accessxi.escape_probe_log_text(s0),
            accessxi.escape_probe_log_text(s24),
            accessxi.escape_probe_log_text(s46),
            accessxi.escape_probe_log_text(accessxi.format_probe_dwords(ptr, 0, 12)),
            accessxi.escape_probe_log_text(runs)));
    end
    local function scan_owner(label, ptr, limit)
        ptr = tonumber(ptr) or 0;
        limit = tonumber(limit) or 0;
        if (not accessxi.is_probe_pointer(ptr)) then
            return;
        end
        for off = 0, limit, 4 do
            add_ptr(('%s+%03X'):fmt(label, off), read_u32(ptr + off) or 0);
        end
        local inline = accessxi.status_menu_probe_inline_strings(ptr);
        if (inline ~= '') then
            parts:append(('%s.inline="%s"'):fmt(label, accessxi.escape_probe_log_text(inline)));
        end
    end

    scan_owner('entry', entry, 0x100);
    scan_owner('desc', desc, 0x80);
    scan_owner('row2', row2, 0x80);
    scan_owner('child', child, 0x100);
    scan_owner('obj', obj, 0x80);

    if (parts:len() > 0) then
        log_line(('currencyptr selected=%d count=%d raw=%d entry=0x%08X desc=0x%08X row2=0x%08X %s'):fmt(
            selected,
            count,
            raw,
            entry,
            desc,
            row2,
            parts:concat(' || ')));
    end
end

function accessxi.currency_native_probe_text(ptr, length)
    ptr = tonumber(ptr) or 0;
    length = tonumber(length) or 180;
    if (not accessxi.is_probe_pointer(ptr)) then
        return '';
    end

    local text = clean_probe_text(read_probe_string(ptr, length));
    if (text == '' or #text > 220) then
        return '';
    end

    return text;
end

function accessxi.currency_native_probe_static_refs(label, ptr, limit)
    label = tostring(label or 'ptr');
    ptr = tonumber(ptr) or 0;
    limit = tonumber(limit) or 0xC0;
    if (not accessxi.is_probe_pointer(ptr)) then
        return '';
    end

    local seen = {};
    local parts = T{};
    for off = 0, limit, 4 do
        local target = read_u32(ptr + off) or 0;
        if (target >= 0x04A20000 and target < 0x04C00000 and seen[target] ~= true) then
            local text = accessxi.currency_native_probe_text(target, 220);
            if (text ~= '' and text ~= '0') then
                seen[target] = true;
                parts:append(('%s+%03X->0x%08X "%s"'):fmt(
                    label,
                    off,
                    target,
                    accessxi.escape_probe_log_text(text)));
                if (parts:len() >= 10) then
                    break;
                end
            end
        end
    end

    return parts:concat(' | ');
end

function accessxi.currency_native_probe_child_graph(child)
    child = tonumber(child) or 0;
    if (not accessxi.is_probe_pointer(child)) then
        return '';
    end

    local parts = T{};
    parts:append(('child080="%s"'):fmt(accessxi.escape_probe_log_text_wide(accessxi.format_probe_dwords(child, 0x80, 24))));
    parts:append(('child0C0="%s"'):fmt(accessxi.escape_probe_log_text_wide(accessxi.format_probe_dwords(child, 0xC0, 24))));
    parts:append(('child090bytes="%s"'):fmt(accessxi.escape_probe_log_text_wide(accessxi.format_probe_bytes(child, 0x90, 0x60))));

    local child_runs = accessxi.status_menu_probe_runs(child, 0x180);
    if (child_runs ~= '') then
        parts:append(('childRuns="%s"'):fmt(accessxi.escape_probe_log_text(child_runs)));
    end

    local child_inline = accessxi.status_menu_probe_inline_strings(child);
    if (child_inline ~= '') then
        parts:append(('childInline="%s"'):fmt(accessxi.escape_probe_log_text(child_inline)));
    end

    local seen = {};
    local target_parts = T{};
    local function add_target(source, ptr)
        ptr = tonumber(ptr) or 0;
        if (not accessxi.is_probe_pointer(ptr) or seen[ptr] == true or target_parts:len() >= 16) then
            return;
        end
        seen[ptr] = true;

        local direct = accessxi.currency_native_probe_text(ptr, 180);
        local strings = accessxi.probe_strings_at(ptr);
        local runs = accessxi.status_menu_probe_runs(ptr, 0x180);
        local refs = accessxi.currency_native_probe_static_refs(source, ptr, 0x100);
        local bytes = accessxi.format_probe_bytes(ptr, 0x00, 0x40);
        if (direct ~= '' or strings ~= '' or runs ~= '' or refs ~= '') then
            target_parts:append(('%s=0x%08X direct="%s" strings="%s" runs="%s" refs="%s" bytes="%s"'):fmt(
                tostring(source or ''),
                ptr,
                accessxi.escape_probe_log_text(direct),
                accessxi.escape_probe_log_text(strings),
                accessxi.escape_probe_log_text(runs),
                accessxi.escape_probe_log_text(refs),
                accessxi.escape_probe_log_text_wide(bytes)));
        end
    end

    for _, off in ipairs(T{ 0x58, 0x5C, 0x60, 0x64, 0x68, 0x6C, 0x70, 0x74, 0x78, 0x7C, 0x80, 0x84, 0x88, 0x8C, 0x90, 0x94, 0x98, 0x9C, 0xA0, 0xA4, 0xA8, 0xAC, 0xB0, 0xB4, 0xB8, 0xBC, 0xC0, 0xC4, 0xC8, 0xCC }) do
        local ptr = read_u32(child + off) or 0;
        add_target(('child+%03X'):fmt(off), ptr);
    end

    if (target_parts:len() > 0) then
        parts:append(('targets="%s"'):fmt(target_parts:concat(' || ')));
    end

    return parts:concat(' ');
end

function accessxi.currency_native_u16_list_for_log(child, first, last, label_bank, help_bank)
    child = tonumber(child) or 0;
    first = tonumber(first) or 0;
    last = tonumber(last) or first;
    label_bank = tonumber(label_bank) or 0;
    help_bank = tonumber(help_bank) or 0;
    if (not accessxi.is_probe_pointer(child)) then
        return '';
    end

    if (first < 0) then first = 0; end
    if (last > 96) then last = 96; end
    if (last < first) then last = first; end

    local parts = T{};
    for i = first, last do
        local value = tonumber(read_u16(child + 0xA8 + (i * 2))) or -1;
        local code = tonumber(read_u16(child + 0xD8 + (i * 2))) or -1;
        local label = '';
        local help = '';
        if (accessxi.is_probe_pointer(label_bank) and value >= 0 and value <= 512) then
            label = accessxi.currency_native_dmsg_entry(label_bank, value, 'label');
        end
        if (accessxi.is_probe_pointer(help_bank) and value >= 0 and value <= 512) then
            help = accessxi.currency_native_dmsg_entry(help_bank, value + 2, 'help');
        end
        if (label ~= '' or help ~= '') then
            parts:append(('%d=%d d8=%d label="%s" help="%s"'):fmt(
                i,
                value,
                code,
                accessxi.escape_probe_log_text(label),
                accessxi.escape_probe_log_text(help)));
        else
            parts:append(('%d=%d d8=%d'):fmt(i, value, code));
        end
    end
    return parts:concat(' | ');
end

function accessxi.currency_native_child_small_fields_for_log(child)
    child = tonumber(child) or 0;
    if (not accessxi.is_probe_pointer(child)) then
        return '';
    end

    local parts = T{};
    for _, off in ipairs(T{
        0x24, 0x28, 0x2C, 0x30, 0x34, 0x38, 0x3C, 0x40, 0x44, 0x48,
        0x4C, 0x50, 0x54, 0x58, 0x5C, 0x80, 0x84, 0x88, 0x8C, 0x90,
        0x94, 0x98, 0x9C, 0xA0, 0xA4
    }) do
        local value = read_i32(child + off);
        if (value ~= nil and value >= -4096 and value <= 4096) then
            parts:append(('+%03X=%d'):fmt(off, value));
        else
            local raw = read_u32(child + off) or 0;
            if (raw ~= 0 and (off >= 0x80 and off <= 0xA4)) then
                parts:append(('+%03X=0x%08X'):fmt(off, raw));
            end
        end
    end
    return parts:concat(' ');
end

function accessxi.log_currency_native_id_probe(selected, count, raw, child)
    selected = tonumber(selected) or 0;
    count = tonumber(count) or 0;
    raw = tonumber(raw) or 0;
    child = tonumber(child) or 0;
    if (not accessxi.is_probe_pointer(child)) then
        return;
    end

    local first = raw - 8;
    local last = raw + 10;
    if (first < 0) then first = 0; end
    if (last < first) then last = first; end
    local help_bank = tonumber(accessxi.currency_native_help_bank) or 0;
    local label_bank = accessxi.currency_native_find_label_bank(help_bank);
    local around = accessxi.currency_native_u16_list_for_log(child, first, last, label_bank, help_bank);
    local head = accessxi.currency_native_u16_list_for_log(child, 0, 31, 0, 0);
    local small = accessxi.currency_native_child_small_fields_for_log(child);
    local bytes = accessxi.format_probe_bytes(child, 0x88, 0x78);
    local key = ('%d:%d:%d:%08X:%s:%s'):fmt(selected, count, raw, child, around, small);
    if (key == tostring(accessxi.last_currency_id_probe_key or '')) then
        return;
    end
    accessxi.last_currency_id_probe_key = key;

    log_line(('currencyids selected=%d count=%d raw=%d child=0x%08X helpBank=0x%08X labelBank=0x%08X fields="%s" around="%s" head="%s" bytes="%s"'):fmt(
        selected,
        count,
        raw,
        child,
        help_bank,
        tonumber(label_bank) or 0,
        accessxi.escape_probe_log_text(small),
        accessxi.escape_probe_log_text_wide(around),
        accessxi.escape_probe_log_text_wide(head),
        accessxi.escape_probe_log_text_wide(bytes)));
end

function accessxi.log_currency_native_idproof_probe(selected, count, raw, child)
    selected = tonumber(selected) or 0;
    count = tonumber(count) or 0;
    raw = tonumber(raw) or 0;
    child = tonumber(child) or 0;
    if (selected <= 0 or count <= 0 or not accessxi.is_probe_pointer(child)) then
        return;
    end

    local help_bank = tonumber(accessxi.currency_native_help_bank) or 0;
    local label_bank = accessxi.currency_native_find_label_bank(help_bank);
    if (not accessxi.is_probe_pointer(label_bank)) then
        return;
    end

    local top = tonumber(read_i32(child + 0x38)) or 0;
    local rows = T{};
    local selected_label = '';
    local selected_help = '';
    local selected_logical = -1;
    local visible_count = math.min(count, 12);
    for i = 0, visible_count - 1 do
        local raw_index = top + i;
        local logical = tonumber(read_u16(child + 0xA8 + (raw_index * 2))) or -1;
        local code = tonumber(read_u16(child + 0xD8 + (raw_index * 2))) or -1;
        local label = '';
        local help = '';
        if (logical >= 0 and logical <= 512) then
            label = accessxi.currency_native_dmsg_entry(label_bank, logical, 'label');
            if (accessxi.is_probe_pointer(help_bank)) then
                help = accessxi.currency_native_dmsg_entry(help_bank, logical + 2, 'help');
            end
        end
        if ((i + 1) == selected) then
            selected_label = label;
            selected_help = help;
            selected_logical = logical;
        end
        rows:append(('%d raw=%d logical=%d code=%d label="%s" help="%s"'):fmt(
            i + 1,
            raw_index,
            logical,
            code,
            accessxi.escape_probe_log_text(label),
            accessxi.escape_probe_log_text(help)));
    end

    local key = ('%d:%d:%d:%d:%08X:%s'):fmt(
        selected,
        count,
        raw,
        top,
        child,
        rows:concat('|'));
    if (key == tostring(accessxi.last_currency_idproof_probe_key or '')) then
        return;
    end
    accessxi.last_currency_idproof_probe_key = key;

    log_line(('currencyidproof selected=%d count=%d raw=%d top=%d logical=%d child=0x%08X helpBank=0x%08X labelBank=0x%08X selectedLabel="%s" selectedHelp="%s" visible="%s"'):fmt(
        selected,
        count,
        raw,
        top,
        selected_logical,
        child,
        help_bank,
        tonumber(label_bank) or 0,
        accessxi.escape_probe_log_text(selected_label),
        accessxi.escape_probe_log_text(selected_help),
        accessxi.escape_probe_log_text_wide(rows:concat(' || '))));
end

function accessxi.currency_native_visible_row_summary(desc, child, selected, count)
    desc = tonumber(desc) or 0;
    child = tonumber(child) or 0;
    selected = tonumber(selected) or 0;
    count = tonumber(count) or 0;
    if (not accessxi.is_probe_pointer(desc) or count <= 0) then
        return '', '';
    end

    local rows = T{};
    local selected_detail = '';
    local visible_count = math.min(count, 12);
    local base = desc;
    if (selected > 1) then
        base = desc - ((selected - 1) * 0x14);
    end
    local top = accessxi.is_probe_pointer(child) and (tonumber(read_i32(child + 0x38)) or 0) or 0;
    for i = 0, visible_count - 1 do
        local rec = base + (i * 0x14);
        local row0 = read_u32(rec + 0x00) or 0;
        local row1 = read_u32(rec + 0x04) or 0;
        local row2 = read_u32(rec + 0x08) or 0;
        local id_index = top + i;
        local logical = accessxi.is_probe_pointer(child) and (tonumber(read_u16(child + 0xA8 + (id_index * 2))) or -1) or -1;
        local code = accessxi.is_probe_pointer(row0) and (read_u32(row0 + 0x04) or 0) or 0;
        local word14 = accessxi.is_probe_pointer(row0) and (read_u32(row0 + 0x14) or 0) or 0;
        local word18 = accessxi.is_probe_pointer(row0) and (read_u32(row0 + 0x18) or 0) or 0;
        local menu = accessxi.is_probe_pointer(row0) and clean_probe_text(read_probe_string(row0 + 0x24, 48)) or '';
        local row1_name = '';
        if (accessxi.is_probe_pointer(row1)) then
            local row1_desc = read_u32(row1 + 0x04) or 0;
            if (accessxi.is_probe_pointer(row1_desc)) then
                row1_name = clean_probe_text(read_probe_string(row1_desc + 0x46, 48));
            end
        end
        rows:append(('%d raw=%d logical=%d row0=0x%08X code=0x%08X w14=0x%08X w18=0x%08X row1=0x%08X row1name="%s" menu="%s"'):fmt(
            i + 1,
            id_index,
            logical,
            row0,
            code,
            word14,
            word18,
            row1,
            accessxi.escape_probe_log_text(row1_name),
            accessxi.escape_probe_log_text(menu)));
        if ((i + 1) == selected) then
            local refs = T{};
            if (accessxi.is_probe_pointer(row0)) then
                local row0_runs = accessxi.status_menu_probe_runs(row0, 0x180);
                local row0_refs = accessxi.currency_native_probe_static_refs('row0', row0, 0x180);
                refs:append(('row0runs="%s" row0refs="%s" row0dwords="%s"'):fmt(
                    accessxi.escape_probe_log_text(row0_runs),
                    accessxi.escape_probe_log_text(row0_refs),
                    accessxi.escape_probe_log_text(accessxi.format_probe_dwords(row0, 0, 16))));
            end
            if (accessxi.is_probe_pointer(row1)) then
                local row1_runs = accessxi.status_menu_probe_runs(row1, 0x180);
                local row1_refs = accessxi.currency_native_probe_static_refs('row1', row1, 0x180);
                refs:append(('row1runs="%s" row1refs="%s" row1dwords="%s"'):fmt(
                    accessxi.escape_probe_log_text(row1_runs),
                    accessxi.escape_probe_log_text(row1_refs),
                    accessxi.escape_probe_log_text(accessxi.format_probe_dwords(row1, 0, 16))));
            end
            if (accessxi.is_probe_pointer(row2)) then
                refs:append(('row2=0x%08X row2text="%s"'):fmt(
                    row2,
                    accessxi.escape_probe_log_text(accessxi.status_menu_probe_runs(row2, 0x100))));
            end
            selected_detail = refs:concat(' ');
        end
    end

    return rows:concat(' || '), selected_detail;
end

function accessxi.log_currency_visible_rows_probe(selected, count, raw, child, desc)
    selected = tonumber(selected) or 0;
    count = tonumber(count) or 0;
    raw = tonumber(raw) or 0;
    child = tonumber(child) or 0;
    desc = tonumber(desc) or 0;
    if (not accessxi.is_probe_pointer(desc) or count <= 0) then
        return;
    end

    local rows, selected_detail = accessxi.currency_native_visible_row_summary(desc, child, selected, count);
    if (rows == '') then
        return;
    end
    local base = desc;
    if (selected > 1) then
        base = desc - ((selected - 1) * 0x14);
    end
    local top = accessxi.is_probe_pointer(child) and (tonumber(read_i32(child + 0x38)) or 0) or 0;
    local key = ('%d:%d:%d:%d:%08X:%08X:%s:%s'):fmt(selected, count, raw, top, desc, base, rows, selected_detail);
    if (key == tostring(accessxi.last_currency_visible_rows_probe_key or '')) then
        return;
    end
    accessxi.last_currency_visible_rows_probe_key = key;
    log_line(('currencyvisrows selected=%d count=%d raw=%d top=%d child=0x%08X desc=0x%08X base=0x%08X rows="%s" selectedDetail="%s"'):fmt(
        selected,
        count,
        raw,
        top,
        child,
        desc,
        base,
        accessxi.escape_probe_log_text_wide(rows),
        accessxi.escape_probe_log_text_wide(selected_detail)));
end

function accessxi.currency_native_probe_desc_name(ptr)
    ptr = tonumber(ptr) or 0;
    if (not accessxi.is_probe_pointer(ptr)) then
        return '', 0;
    end

    local desc = read_u32(ptr + 0x04) or 0;
    if (not accessxi.is_probe_pointer(desc)) then
        return '', desc;
    end

    return clean_probe_text(read_probe_string(desc + 0x46)), desc;
end

function accessxi.currency_native_probe_compound_text(ptr, length, limit)
    ptr = tonumber(ptr) or 0;
    if (not accessxi.is_probe_pointer(ptr)) then
        return '';
    end

    length = tonumber(length) or 0x300;
    limit = tonumber(limit) or 8;

    local parts = T{};
    if (accessxi.collect_probe_ascii_runs ~= nil and accessxi.probe_runs_to_text ~= nil) then
        local ascii = accessxi.probe_runs_to_text(accessxi.collect_probe_ascii_runs(ptr, length, 3, limit));
        if (ascii ~= '') then
            parts:append(('ascii=%s'):fmt(accessxi.escape_probe_log_text(ascii)));
        end
    end
    if (accessxi.collect_probe_utf16_runs ~= nil and accessxi.probe_runs_to_text ~= nil) then
        local utf16 = accessxi.probe_runs_to_text(accessxi.collect_probe_utf16_runs(ptr, length, 3, limit));
        if (utf16 ~= '') then
            parts:append(('utf16=%s'):fmt(accessxi.escape_probe_log_text(utf16)));
        end
    end
    if (accessxi.collect_probe_ffxi_utf16_entries ~= nil) then
        local entries = accessxi.collect_probe_ffxi_utf16_entries(ptr, length, 3, limit);
        local words = T{};
        for _, entry in ipairs(entries) do
            local text = accessxi.survival_guide_text(entry.text or '');
            if (text ~= '') then
                words:append(('+%03X=%s'):fmt(
                    tonumber(entry.offset) or 0,
                    accessxi.escape_probe_log_text(text)));
            end
        end
        if (words:len() > 0) then
            parts:append(('ffxi=%s'):fmt(words:concat(' | ')));
        end
    end

    return parts:concat(' ; ');
end

function accessxi.log_currency_render_shape_probe(selected, count, raw)
    selected = tonumber(selected) or 0;
    count = tonumber(count) or 0;
    raw = tonumber(raw) or 0;
    if (raw > 3 and raw < 96 and (raw % 20) ~= 0) then
        return;
    end

    local key = ('%d:%d:%d'):fmt(selected, count, raw);
    if (key == tostring(accessxi.last_currency_shape_probe_key or '')) then
        return;
    end
    accessxi.last_currency_shape_probe_key = key;

    local target = AshitaCore:GetMemoryManager():GetTarget();
    if (target == nil) then
        return;
    end

    local parts = T{};
    for i = 0, 31 do
        local shape = safe_call(function () return target:GetWindowAnkShape(i); end, nil);
        local ptr = tonumber(shape) or 0;
        if (accessxi.is_probe_pointer(ptr)) then
            local text = accessxi.currency_native_probe_compound_text(ptr, 0x300, 10);
            if (text ~= '') then
                local desc_name = accessxi.currency_native_probe_desc_name(ptr);
                parts:append(('shape%d=0x%08X name="%s" dwords="%s" text="%s"'):fmt(
                    i,
                    ptr,
                    accessxi.escape_probe_log_text(desc_name),
                    accessxi.escape_probe_log_text(accessxi.format_probe_dwords(ptr, 0, 12)),
                    accessxi.escape_probe_log_text_wide(text)));
                if (parts:len() >= 12) then
                    break;
                end
            end
        end
    end

    log_line(('currencyshape selected=%d count=%d raw=%d shapes="%s"'):fmt(
        selected,
        count,
        raw,
        parts:concat(' || ')));
end

function accessxi.currency_visible_render_entries_for_log(ptr, length, limit)
    ptr = tonumber(ptr) or 0;
    if (not accessxi.is_probe_pointer(ptr) or accessxi.collect_probe_ffxi_utf16_entries == nil) then
        return '';
    end

    length = tonumber(length) or 0x1000;
    limit = tonumber(limit) or 32;
    local entries = accessxi.collect_probe_ffxi_utf16_entries(ptr, length, 2, limit);
    if (entries == nil or entries:len() == 0) then
        return '';
    end

    local parts = T{};
    for _, entry in ipairs(entries) do
        local text = accessxi.survival_guide_text(entry.text or '');
        if (text ~= '') then
            parts:append(('+%03X="%s"'):fmt(
                tonumber(entry.offset) or 0,
                accessxi.escape_probe_log_text(text)));
        end
    end
    return parts:concat(' | ');
end

function accessxi.log_currency_visible_render_probe(obj, child, selected, count, raw)
    obj = tonumber(obj) or 0;
    child = tonumber(child) or 0;
    selected = tonumber(selected) or 0;
    count = tonumber(count) or 0;
    raw = tonumber(raw) or 0;
    if (not accessxi.is_probe_pointer(obj) or not accessxi.is_probe_pointer(child)) then
        return;
    end

    local holder14 = read_u32(child + 0x14) or 0;
    local holder18 = read_u32(child + 0x18) or 0;
    local render14 = accessxi.is_probe_pointer(holder14) and (read_u32(holder14 + 0x10) or 0) or 0;
    local render18 = accessxi.is_probe_pointer(holder18) and (read_u32(holder18 + 0x10) or 0) or 0;
    local key = ('%08X:%08X:%d:%d:%d:%08X:%08X:%08X:%08X'):fmt(
        obj,
        child,
        selected,
        count,
        raw,
        holder14,
        holder18,
        render14,
        render18);
    if (key == tostring(accessxi.last_currency_visible_render_probe_key or '')) then
        return;
    end
    accessxi.last_currency_visible_render_probe_key = key;

    local parts = T{};
    for _, source in ipairs(T{
        T{ label = 'child', ptr = child, len = 0x280 },
        T{ label = 'holder14', ptr = holder14, len = 0x240 },
        T{ label = 'holder18', ptr = holder18, len = 0x240 },
        T{ label = 'render14', ptr = render14, len = 0x1800 },
        T{ label = 'render18', ptr = render18, len = 0x1800 },
    }) do
        local ptr = tonumber(source.ptr) or 0;
        if (accessxi.is_probe_pointer(ptr)) then
            local entries = accessxi.currency_visible_render_entries_for_log(ptr, source.len, 40);
            if (entries ~= '') then
                parts:append(('%s=0x%08X {%s}'):fmt(
                    tostring(source.label or ''),
                    ptr,
                    entries));
            end
        end
    end

    log_line(('currencyrender selected=%d count=%d raw=%d obj=0x%08X child=0x%08X holders=0x%08X/0x%08X renders=0x%08X/0x%08X text="%s"'):fmt(
        selected,
        count,
        raw,
        obj,
        child,
        holder14,
        holder18,
        render14,
        render18,
        accessxi.escape_probe_log_text_wide(parts:concat(' || '))));
end

function accessxi.log_currency_native_compound_probe(selected, count, raw, obj, child, entry, desc)
    selected = tonumber(selected) or 0;
    count = tonumber(count) or 0;
    raw = tonumber(raw) or 0;
    obj = tonumber(obj) or 0;
    child = tonumber(child) or 0;
    entry = tonumber(entry) or 0;
    desc = tonumber(desc) or 0;
    if (not accessxi.is_probe_pointer(obj)) then
        return;
    end
    if (raw > 12 and (raw % 10) ~= 0) then
        return;
    end

    local key = ('%d:%d:%d:%08X:%08X:%08X:%08X'):fmt(
        selected,
        count,
        raw,
        obj,
        child,
        entry,
        desc);
    if (key == tostring(accessxi.last_currency_compound_probe_key or '')) then
        return;
    end
    accessxi.last_currency_compound_probe_key = key;

    local seen = {};
    local seeds = T{};
    local function add_seed(source, ptr)
        ptr = tonumber(ptr) or 0;
        if (not accessxi.is_probe_pointer(ptr) or seen[ptr] == true or seeds:len() >= 48) then
            return;
        end
        seen[ptr] = true;
        seeds:append(T{ source = tostring(source or ''), ptr = ptr });
    end

    add_seed('obj', obj);
    add_seed('child', child);
    add_seed('entry', entry);
    add_seed('desc', desc);

    for delta = -0x3A0, 0x3A0, 0xE8 do
        add_seed(('near%+d'):fmt(delta), obj + delta);
    end

    for _, owner in ipairs(T{
        T{ label = 'obj', ptr = obj },
        T{ label = 'child', ptr = child },
        T{ label = 'entry', ptr = entry },
        T{ label = 'desc', ptr = desc },
    }) do
        local owner_ptr = tonumber(owner.ptr) or 0;
        if (accessxi.is_probe_pointer(owner_ptr)) then
            for _, off in ipairs(T{ 0x00, 0x04, 0x08, 0x0C, 0x10, 0x14, 0x18, 0x1C, 0x20, 0x24, 0x28, 0x2C, 0x30, 0x34, 0x38, 0x3C, 0x40, 0x44, 0x48, 0x4C, 0x50, 0x54, 0x58, 0x5C, 0x60, 0x64, 0x68, 0x6C, 0x70, 0x74, 0x78, 0x7C, 0x80, 0x84, 0x88, 0x8C, 0x90, 0x94, 0x98, 0x9C, 0xA0, 0xA4, 0xA8, 0xAC, 0xB0, 0xB4, 0xB8, 0xBC, 0xC0, 0xC4, 0xC8, 0xCC, 0xD0, 0xD4, 0xD8, 0xDC, 0xE0, 0xE4, 0xE8, 0xEC, 0xF0, 0xF4, 0xF8, 0xFC, 0x100, 0x104, 0x108, 0x10C, 0x110, 0x114, 0x118, 0x11C, 0x120, 0x124, 0x128, 0x12C, 0x130, 0x134, 0x138, 0x13C, 0x140, 0x144, 0x148, 0x14C, 0x150, 0x154, 0x158, 0x15C, 0x160, 0x164, 0x168, 0x16C, 0x170, 0x174, 0x178, 0x17C }) do
                local ptr = read_u32(owner_ptr + off) or 0;
                if (accessxi.is_probe_pointer(ptr)) then
                    local desc_name = accessxi.currency_native_probe_desc_name(ptr);
                    if (desc_name ~= '') then
                        add_seed(('%s+%03X'):fmt(owner.label, off), ptr);
                    end
                end
            end
        end
    end

    local parts = T{};
    for _, seed in ipairs(seeds) do
        if (parts:len() >= 28) then
            break;
        end

        local ptr = tonumber(seed.ptr) or 0;
        local desc_name, node_desc = accessxi.currency_native_probe_desc_name(ptr);
        local node_child = read_u32(ptr + 0x0C) or 0;
        local node_selected, node_page, node_raw, _, node_count = accessxi.survival_guide_query_child_state_for_obj(ptr);
        local obj_selected = tonumber(read_i32(ptr + 0x4C)) or -9999;
        local obj_count = tonumber(read_i32(ptr + 0x24)) or -9999;
        local obj_count2 = tonumber(read_i32(ptr + 0x28)) or -9999;
        local indexes = accessxi.format_probe_index_fields(ptr, 0x00, 0xA0);
        local text = accessxi.currency_native_probe_compound_text(ptr, 0x280, 8);
        local static_refs = accessxi.currency_native_probe_static_refs(seed.source or '', ptr, 0x180);

        if (desc_name ~= ''
            or text ~= ''
            or static_refs ~= ''
            or (obj_count >= 0 and obj_count <= 256)
            or (obj_count2 >= 0 and obj_count2 <= 256)
            or (obj_selected >= 0 and obj_selected <= 256)) then
            parts:append(('%s=0x%08X desc=0x%08X name="%s" objSel=%d objCount=%d/%d child=0x%08X qSel=%d qRaw=%d qPage=%d qCount=%d idx="%s" refs="%s" text="%s"'):fmt(
                tostring(seed.source or ''),
                ptr,
                tonumber(node_desc) or 0,
                accessxi.escape_probe_log_text(desc_name),
                obj_selected,
                obj_count,
                obj_count2,
                node_child,
                tonumber(node_selected) or 0,
                tonumber(node_raw) or 0,
                tonumber(node_page) or 0,
                tonumber(node_count) or 0,
                accessxi.escape_probe_log_text(indexes),
                accessxi.escape_probe_log_text(static_refs),
                accessxi.escape_probe_log_text_wide(text)));
        end
    end

    log_line(('currencycompound selected=%d count=%d raw=%d obj=0x%08X child=0x%08X entry=0x%08X desc=0x%08X candidates="%s"'):fmt(
        selected,
        count,
        raw,
        obj,
        child,
        entry,
        desc,
        parts:concat(' || ')));
    accessxi.log_currency_render_shape_probe(selected, count, raw);
end

function accessxi.log_currency_native_record_probe(selected, count, raw, obj, child, entry, desc)
    selected = tonumber(selected) or 0;
    count = tonumber(count) or 0;
    raw = tonumber(raw) or 0;
    obj = tonumber(obj) or 0;
    child = tonumber(child) or 0;
    entry = tonumber(entry) or 0;
    desc = tonumber(desc) or 0;
    if (selected <= 0 or not accessxi.is_probe_pointer(entry)) then
        return;
    end

    local key = ('%d:%d:%d:%08X:%08X:%08X:%08X'):fmt(
        selected,
        count,
        raw,
        obj,
        child,
        entry,
        desc);
    if (key == tostring(accessxi.last_currency_native_record_key or '')) then
        return;
    end
    accessxi.last_currency_native_record_key = key;

    local entry_parts = T{};
    for off = 0x00, 0x100, 4 do
        local ptr = read_u32(entry + off) or 0;
        local direct = accessxi.currency_native_probe_text(ptr, 160);
        local refs = accessxi.currency_native_probe_static_refs(('entry+%03X'):fmt(off), ptr, 0x90);
        if ((direct ~= '' or refs ~= '') and entry_parts:len() < 14) then
            entry_parts:append(('+%03X=0x%08X text="%s" refs="%s"'):fmt(
                off,
                ptr,
                accessxi.escape_probe_log_text(direct),
                accessxi.escape_probe_log_text(refs)));
        end
    end

    local record_parts = T{};
    if (accessxi.is_probe_pointer(desc)) then
        for index = 0, 14 do
            local rec = desc + (index * 0x14);
            local a = read_u32(rec + 0x00) or 0;
            local b = read_u32(rec + 0x04) or 0;
            local c = read_u32(rec + 0x08) or 0;
            local d = read_u32(rec + 0x0C) or 0;
            local e = read_u32(rec + 0x10) or 0;
            local a_refs = accessxi.currency_native_probe_static_refs(('rec%d.a'):fmt(index), a, 0x80);
            local b_refs = accessxi.currency_native_probe_static_refs(('rec%d.b'):fmt(index), b, 0x80);
            local c_text = accessxi.currency_native_probe_text(c, 220);
            local c_refs = accessxi.currency_native_probe_static_refs(('rec%d.c'):fmt(index), c, 0x80);
            local b_inline = clean_probe_text(read_probe_string(b + 0x04, 48));
            local a_inline = clean_probe_text(read_probe_string(a + 0x24, 48));
            if ((a_refs ~= '' or b_refs ~= '' or c_text ~= '' or c_refs ~= '' or b_inline ~= '' or a_inline ~= '') and record_parts:len() < 12) then
                record_parts:append(('rec%d a=0x%08X b=0x%08X c=0x%08X d=0x%08X e=0x%08X aText="%s" bText="%s" cText="%s" aRefs="%s" bRefs="%s" cRefs="%s"'):fmt(
                    index,
                    a,
                    b,
                    c,
                    d,
                    e,
                    accessxi.escape_probe_log_text(a_inline),
                    accessxi.escape_probe_log_text(b_inline),
                    accessxi.escape_probe_log_text(c_text),
                    accessxi.escape_probe_log_text(a_refs),
                    accessxi.escape_probe_log_text(b_refs),
                    accessxi.escape_probe_log_text(c_refs)));
            end
        end
    end

    local child_graph = accessxi.currency_native_probe_child_graph(child);
    accessxi.log_currency_native_compound_probe(selected, count, raw, obj, child, entry, desc);

    log_line(('currencynative selected=%d count=%d raw=%d obj=0x%08X child=0x%08X entry=0x%08X desc=0x%08X entryRefs="%s" records="%s" childGraph="%s"'):fmt(
        selected,
        count,
        raw,
        obj,
        child,
        entry,
        desc,
        entry_parts:concat(' || '),
        record_parts:concat(' || '),
        child_graph));
end

function accessxi.log_currency_resource_manager_probe()
    local resources = safe_call(function () return AshitaCore:GetResourceManager(); end, nil);
    if (resources == nil) then
        log_line('currencyres resource-manager unavailable');
        return;
    end

    local function resource_text(value)
        if (value == nil) then
            return '';
        end

        if (type(value) == 'table' or type(value) == 'userdata') then
            local localized = safe_call(function () return value[1]; end, nil);
            if (localized ~= nil) then
                return clean_probe_text(localized);
            end
        end

        return clean_probe_text(value);
    end

    local function maybe_field(item, field)
        return safe_call(function () return item[field]; end, nil);
    end

    local names = T{
        'items.currency',
        'items.currency.names',
        'currency',
        'currency.names',
        'currencies',
    };
    local total = 0;
    for _, table_name in ipairs(names) do
        local hits = T{};
        for id = 0, 900 do
            local text = safe_call(function () return resources:GetString(table_name, id); end, '') or '';
            text = clean_probe_text(text);
            if (text ~= ''
                and not text:eq('Unknown', true)
                and not text:eq('None', true)
                and hits:len() < 160) then
                hits:append(('%d="%s"'):fmt(id, accessxi.escape_probe_log_text(text)));
            end
        end
        total = total + hits:len();
        log_line(('currencyres table="%s" hits=%d %s'):fmt(
            table_name,
            hits:len(),
            hits:concat(' | ')));
    end

    local item_hits = T{};
    for _, id in ipairs(T{ 91, 113, 118, 2060, 4064, 4065, 4066, 4067, 4068, 4069, 4070, 4071, 4072, 4073, 65535 }) do
        local item = safe_call(function () return resources:GetItemById(id); end, nil);
        if (item ~= nil) then
            local name = resource_text(maybe_field(item, 'Name'));
            local description = resource_text(maybe_field(item, 'Description'));
            local category = safe_call(function () return tonumber(item.Category) or 0; end, 0) or 0;
            local stack = safe_call(function () return tonumber(item.StackSize) or 0; end, 0) or 0;
            local flags = safe_call(function () return tonumber(item.Flags) or 0; end, 0) or 0;
            if (name ~= '' or description ~= '') then
                item_hits:append(('%d name="%s" desc="%s" cat=%d stack=%d flags=0x%X'):fmt(
                    id,
                    accessxi.escape_probe_log_text(name),
                    accessxi.escape_probe_log_text(description),
                    category,
                    stack,
                    flags));
            end
        end
    end
    log_line(('currencyres item-sample hits=%d %s'):fmt(item_hits:len(), item_hits:concat(' | ')));

    log_line(('currencyres done totalStringHits=%d'):fmt(total));
end

function accessxi.currency_menu_resource_for_entry(entry, title, selected, raw)
    entry = tonumber(entry) or 0;
    if (not accessxi.is_probe_pointer(entry)) then
        return nil;
    end

    -- The evitem row object does not expose the final text pointer. Live logs do
    -- expose the native logical row index, and packet 0x113/0x118 layouts are
    -- documented by LandSandBoat/XiPackets. Require that native raw index here;
    -- never fall back to visible slot number.
    local title_text = tostring(title or '');
    local page = tonumber(accessxi.current_currency_menu_page) or 1;
    if (title_text:contains('2', true)) then
        page = 2;
    end
    local now = tick();
    local currency_context_tick = tonumber(accessxi.current_currency_menu_page_tick) or 0;
    local currency_context_age = now - currency_context_tick;
    if (currency_context_tick <= 0 or currency_context_age > 120000) then
        local stale_key = ('%s:%d:%d:%d'):fmt(title_text, tonumber(selected) or 0, tonumber(raw) or -1, page);
        if (stale_key ~= tostring(accessxi.last_currency_context_stale_key or '')
            or (now - (tonumber(accessxi.last_currency_context_stale_tick) or 0)) >= 1000) then
            accessxi.last_currency_context_stale_key = stale_key;
            accessxi.last_currency_context_stale_tick = now;
            log_state(('state nativemenu currency-context stale menu="%s" title="%s" select=%d raw=%d page=%d age=%d'):fmt(
                'menu    evitem',
                title_text,
                tonumber(selected) or 0,
                tonumber(raw) or -1,
                page,
                currency_context_age));
        end
        return nil;
    end
    if (page ~= 2 and currency_context_age > 6000) then
        page = 1;
    end
    local fields_113 = accessxi.currency_packet_113_fields;
    local count_113 = fields_113 ~= nil and fields_113:len() or 0;
    local fields_118 = accessxi.currency_packet_118_display_fields or accessxi.currency_packet_118_fields;
    local count_118 = fields_118 ~= nil and fields_118:len() or 0;
    local raw_index = tonumber(raw);
    local selected_index = (tonumber(selected) or 1) - 1;
    local packet_id = 0x0113;
    local index = raw_index;

    if (raw_index == nil or raw_index < 0) then
        log_state(('state nativemenu currency-index missing-native-raw menu="%s" title="%s" select=%d raw=%d'):fmt(
            'menu    evitem',
            title_text,
            tonumber(selected) or 0,
            tonumber(raw) or -1));
        return nil;
    end

    if (page == 2) then
        packet_id = 0x0118;
    end

    local data = packet_id == 0x0118 and tostring(accessxi.currency_packet_118 or '') or tostring(accessxi.currency_packet_113 or '');
    local fields = packet_id == 0x0118 and fields_118 or fields_113;
    local field_count = fields ~= nil and fields:len() or 0;
    if (index < 0 or index >= field_count) then
        log_state(('state nativemenu currency-index unavailable menu="%s" title="%s" select=%d raw=%d packet=0x%03X index=%d count113=%d count118=%d'):fmt(
            'menu    evitem',
            title_text,
            tonumber(selected) or 0,
            tonumber(raw) or -1,
            packet_id,
            tonumber(index) or -1,
            count_113,
            count_118));
        return nil;
    end

    local field = fields[index + 1];
    if (field == nil) then
        log_state(('state nativemenu currency-packet unavailable menu="%s" title="%s" select=%d raw=%d packet=0x%03X dataLen=%d'):fmt(
            'menu    evitem',
            title_text,
            tonumber(selected) or 0,
            tonumber(raw) or -1,
            packet_id,
            #data));
        return nil;
    end
    if (data == '') then
        log_state(('state nativemenu currency-packet amount-missing menu="%s" title="%s" select=%d raw=%d packet=0x%03X dataLen=%d'):fmt(
            'menu    evitem',
            title_text,
            tonumber(selected) or 0,
            tonumber(raw) or -1,
            packet_id,
            #data));
    end

    return {
        id = index + 1,
        resource_id = tonumber(field.off) or 0,
        resource_type = packet_id,
        row_code = accessxi.is_probe_pointer(entry) and (read_u32(entry + 0x24) or 0) or 0,
        row_visual_code = tonumber(raw) or 0,
        raw_index = raw_index or -1,
        selected_index = selected_index,
        page = page,
        label = accessxi.currency_packet_field_label(field),
        value = accessxi.currency_packet_value(data, field),
        field = tostring(field.name or ''),
        description = ('packet=0x%03X off=0x%02X size=%d name=%s'):fmt(
            packet_id,
            tonumber(field.off) or 0,
            tonumber(field.size) or 0,
            tostring(field.name or '')),
    };
end

function accessxi.currency_native_remember_help_bank(ptr)
    ptr = tonumber(ptr) or 0;
    if (not accessxi.is_probe_pointer(ptr)) then
        return false;
    end

    local text = read_probe_string(ptr, 96);
    if (not tostring(text or ''):contains('Displays the currencies earned', true)) then
        return false;
    end

    if (tonumber(accessxi.currency_native_help_bank) ~= ptr) then
        accessxi.currency_native_help_bank = ptr;
        accessxi.currency_native_label_bank = 0;
        accessxi.currency_native_entry_cache = {};
    end
    return true;
end

function accessxi.currency_native_label_text(text)
    text = accessxi.plain_native_menu_label(text or '');
    if (text == '' or text:find('menu    ', 1, true) ~= nil) then
        return '';
    end
    return text;
end

function accessxi.currency_native_help_text(text)
    text = accessxi.survival_guide_text(text or '');
    text = tostring(text or ''):gsub('^["\']+', ''):gsub('["\']+$', ''):trim();
    if (text == '' or #text > 280) then
        return '';
    end
    if (text:match('^[%p%s]+$') ~= nil) then
        return '';
    end
    if (text:find('menu    ', 1, true) ~= nil or text:find('anc     ', 1, true) ~= nil) then
        return '';
    end
    return text;
end

function accessxi.currency_help_looks_like_currency(help)
    help = tostring(help or ''):lower();
    if (help == '') then
        return false;
    end

    local rejects = T{
        'displays the list of jobs',
        'select the job',
        'remove or store items',
        'select a form of storage',
        'display equipment',
        'on auction',
        'targeting function',
        'refine search',
        'view alchemy materials',
        'view miscellaneous items',
    };
    for _, phrase in ipairs(rejects) do
        if (help:find(phrase, 1, true) ~= nil) then
            return false;
        end
    end

    local markers = T{
        'currency earned',
        'currency used',
        'number of',
        'amount of',
        'items needed',
        'stored with',
        'applicable npc',
        'slowly replenish',
        'participating in',
        'redeemable at',
        'trading crystals',
        'ponzes of cinder',
        'charged ',
        'total of your points',
        'gobbie mystery boxes',
        'sacred city of adoulin',
        'colonization',
        'coalition',
        'abyssea',
        'voidwatch',
        'ambuscade',
        'domain invasion',
        'odyssey',
        'sortie',
        'limbus',
    };
    for _, marker in ipairs(markers) do
        if (help:find(marker, 1, true) ~= nil) then
            return true;
        end
    end

    return false;
end

function accessxi.currency_native_dmsg_raw_length(ptr, max_len)
    ptr = tonumber(ptr) or 0;
    max_len = tonumber(max_len) or 512;
    if (not accessxi.is_probe_pointer(ptr)) then
        return 0;
    end

    for i = 0, max_len do
        local value = read_u8(ptr + i);
        if (value == nil) then
            return 0;
        end
        if (value == 0) then
            return i;
        end
    end
    return max_len;
end

function accessxi.currency_native_dmsg_candidate(ptr, kind)
    ptr = tonumber(ptr) or 0;
    kind = tostring(kind or 'label');
    if (not accessxi.is_probe_pointer(ptr)) then
        return '';
    end

    if (kind:eq('help', true)) then
        return accessxi.currency_native_help_text(read_probe_string(ptr, 320));
    end
    return accessxi.currency_native_label_text(read_probe_string(ptr, 120));
end

function accessxi.currency_native_dmsg_next(ptr, kind)
    ptr = tonumber(ptr) or 0;
    if (not accessxi.is_probe_pointer(ptr)) then
        return 0;
    end

    local raw_len = accessxi.currency_native_dmsg_raw_length(ptr, 512);
    if (raw_len <= 0 or raw_len >= 512) then
        return 0;
    end

    local start = ptr + raw_len + 1;
    for off = 0, 0x120 do
        local candidate = start + off;
        local b = read_u8(candidate) or 0;
        if (b >= 0x20 and b <= 0x7E) then
            local text = accessxi.currency_native_dmsg_candidate(candidate, kind);
            if (text ~= '') then
                return candidate;
            end
        end
    end
    return 0;
end

function accessxi.currency_native_dmsg_entry(base, index, kind)
    base = tonumber(base) or 0;
    index = tonumber(index) or 0;
    kind = tostring(kind or 'label');
    if (not accessxi.is_probe_pointer(base) or index < 0 or index > 512) then
        return '', 0;
    end

    local cache = accessxi.currency_native_entry_cache;
    if (type(cache) ~= 'table') then
        cache = {};
        accessxi.currency_native_entry_cache = cache;
    end
    local key = ('%s:%08X:%d'):fmt(kind, base, index);
    local cached = cache[key];
    if (type(cached) == 'table') then
        return tostring(cached.text or ''), tonumber(cached.ptr) or 0;
    end

    local ptr = base;
    local base_key = ('%s:%08X:%d'):fmt(kind, base, 0);
    if (cache[base_key] == nil) then
        cache[base_key] = { text = accessxi.currency_native_dmsg_candidate(base, kind), ptr = base };
    end
    for current = 0, index - 1 do
        local next_key = ('%s:%08X:%d'):fmt(kind, base, current + 1);
        local next_cached = cache[next_key];
        if (type(next_cached) == 'table') then
            ptr = tonumber(next_cached.ptr) or 0;
        else
            ptr = accessxi.currency_native_dmsg_next(ptr, kind);
            if (ptr == 0) then
                cache[next_key] = { text = '', ptr = 0 };
                cache[key] = { text = '', ptr = 0 };
                return '', 0;
            end
            cache[next_key] = { text = accessxi.currency_native_dmsg_candidate(ptr, kind), ptr = ptr };
        end
    end

    cached = cache[key];
    if (type(cached) == 'table') then
        return tostring(cached.text or ''), tonumber(cached.ptr) or 0;
    end

    local text = accessxi.currency_native_dmsg_candidate(ptr, kind);
    cache[key] = { text = text, ptr = ptr };
    return text, ptr;
end

function accessxi.currency_native_find_label_bank(help_bank)
    help_bank = tonumber(help_bank) or tonumber(accessxi.currency_native_help_bank) or 0;
    if (not accessxi.is_probe_pointer(help_bank)) then
        return 0;
    end

    local cached = tonumber(accessxi.currency_native_label_bank) or 0;
    if (accessxi.is_probe_pointer(cached)
        and accessxi.currency_native_label_text(read_probe_string(cached, 120)):eq("Conquest Points (San d'Oria)", true)) then
        return cached;
    end

    local predicted = help_bank + 0x101AC;
    for off = -0x400, 0x400, 4 do
        local candidate = predicted + off;
        local text = accessxi.currency_native_label_text(read_probe_string(candidate, 120));
        if (text:eq("Conquest Points (San d'Oria)", true)) then
            accessxi.currency_native_label_bank = candidate;
            return candidate;
        end
    end

    for off = 0xF000, 0x12000, 4 do
        local candidate = help_bank + off;
        local text = accessxi.currency_native_label_text(read_probe_string(candidate, 120));
        if (text:eq("Conquest Points (San d'Oria)", true)) then
            accessxi.currency_native_label_bank = candidate;
            return candidate;
        end
    end
    return 0;
end

function accessxi.currency_menu_native_logical_id(child, raw)
    child = tonumber(child) or 0;
    raw = tonumber(raw) or -1;
    if (not accessxi.is_probe_pointer(child) or raw < 0 or raw > 255) then
        return nil;
    end

    local logical = read_u16(child + 0xA8 + (raw * 2));
    logical = tonumber(logical);
    if (logical == nil or logical < 0 or logical > 512) then
        return nil;
    end
    return logical;
end

function accessxi.currency_native_label_candidates_for_logical(logical_id)
    logical_id = tonumber(logical_id);
    if (logical_id == nil or logical_id < 0) then
        return '';
    end

    local help_bank = tonumber(accessxi.currency_native_help_bank) or 0;
    local label_bank = accessxi.currency_native_find_label_bank(help_bank);
    if (not accessxi.is_probe_pointer(label_bank)) then
        return ('bank-missing helpBank=0x%08X labelBank=0x%08X'):fmt(
            tonumber(help_bank) or 0,
            tonumber(accessxi.currency_native_label_bank) or 0);
    end

    local parts = T{};
    for delta = -8, 18 do
        local label_index = logical_id + delta;
        if (label_index >= 0) then
            local label, label_ptr = accessxi.currency_native_dmsg_entry(label_bank, label_index, 'label');
            if (label ~= '') then
                parts:append(('%+d:%d:0x%08X="%s"'):fmt(
                    delta,
                    label_index,
                    tonumber(label_ptr) or 0,
                    accessxi.escape_probe_log_text(label)));
            end
        end
    end
    return parts:concat(' | ');
end

function accessxi.log_currency_known_label_probe()
    local help_bank = tonumber(accessxi.currency_native_help_bank) or 0;
    local label_bank = accessxi.currency_native_find_label_bank(help_bank);
    local key = ('%08X:%08X'):fmt(help_bank, tonumber(label_bank) or 0);
    if (key == tostring(accessxi.last_currency_known_label_probe_key or '')) then
        return;
    end
    accessxi.last_currency_known_label_probe_key = key;

    if (not accessxi.is_probe_pointer(label_bank)) then
        log_line(('currencylabels helpBank=0x%08X labelBank=0x%08X labels="bank-missing"'):fmt(
            help_bank,
            tonumber(label_bank) or 0));
        return;
    end

    local wanted = T{
        'Fire Crystal',
        'Fire Crystals',
        'Ice Crystal',
        'Ice Crystals',
        'Wind Crystal',
        'Wind Crystals',
        'Earth Crystal',
        'Earth Crystals',
        'Lightning Crystal',
        'Lightning Crystals',
        'Water Crystal',
        'Water Crystals',
        'Light Crystal',
        'Light Crystals',
        'Dark Crystal',
        'Dark Crystals',
        'Deeds',
        'Deeds of Heroism',
        'Login Points',
        'Login Campaign',
        "Rem's Tale",
        "Rem's Tale Ch.1",
        "Rem's Tale Ch.10",
    };
    local found = {};
    local remaining = #wanted;
    local samples = T{};
    for index = 0, 512 do
        local label, label_ptr = accessxi.currency_native_dmsg_entry(label_bank, index, 'label');
        if (label ~= '') then
            if ((index % 24) == 0 or index >= 180) then
                samples:append(('%d:0x%08X="%s"'):fmt(
                    index,
                    tonumber(label_ptr) or 0,
                    accessxi.escape_probe_log_text(label)));
            end
            local lower_label = tostring(label):lower();
            for i = 1, #wanted do
                local target = tostring(wanted[i] or '');
                if (found[target] == nil) then
                    local lower_target = target:lower();
                    if (lower_label == lower_target or lower_label:find(lower_target, 1, true) ~= nil) then
                        found[target] = ('%d@0x%08X="%s"'):fmt(
                            index,
                            tonumber(label_ptr) or 0,
                            accessxi.escape_probe_log_text(label));
                        remaining = remaining - 1;
                    end
                end
            end
            if (remaining <= 0 and index >= 220) then
                break;
            end
        end
    end

    local parts = T{};
    for i = 1, #wanted do
        local target = tostring(wanted[i] or '');
        parts:append(('%s=%s'):fmt(target, tostring(found[target] or 'missing')));
    end
    log_line(('currencylabels helpBank=0x%08X labelBank=0x%08X labels="%s"'):fmt(
        help_bank,
        tonumber(label_bank) or 0,
        accessxi.escape_probe_log_text_wide(parts:concat(' | '))));
    log_line(('currencylabelsamples helpBank=0x%08X labelBank=0x%08X samples="%s"'):fmt(
        help_bank,
        tonumber(label_bank) or 0,
        accessxi.escape_probe_log_text_wide(samples:concat(' | '))));
end

function accessxi.currency_native_label_index_for_logical(logical_id)
    logical_id = tonumber(logical_id);
    if (logical_id == nil or logical_id < 0) then
        return nil;
    end

    -- child+0xA8 is the client-side filtered currency ID list. The client uses
    -- that ID to read the localized currency label from the items.currency DAT.
    -- Do not substitute the visible row number here; filtered/missing currencies
    -- make row order diverge from resource ID order.
    return logical_id;
end

function accessxi.currency_help_matches_label(label, help)
    label = tostring(label or ''):lower();
    help = tostring(help or ''):lower();
    if (label == '' or help == '') then
        return false;
    end
    if (accessxi.currency_help_looks_like_currency(help)) then
        return true;
    end

    local ignored = {
        stored = true,
        points = true,
        point = true,
        currency = true,
        chapters = true,
        chapter = true,
        team = true,
    };
    for word in label:gmatch('[a-z][a-z\']+') do
        if (#word >= 5 and ignored[word] ~= true and help:find(word, 1, true) ~= nil) then
            return true;
        end
    end
    return false;
end

function accessxi.currency_label_matches_packet_field(label, field)
    local field_name = '';
    if (field ~= nil) then
        field_name = tostring(field.name or ''):lower();
    end
    if (tostring(label or '') == '' or field_name == '') then
        return false;
    end

    local label_text = tostring(label or ''):lower();
    local label_key = label_text:gsub('[^a-z0-9]+', '');
    local label_tokens = {};
    for word in label_text:gmatch('[a-z0-9]+') do
        label_tokens[word] = true;
    end

    local crystal_element = field_name:match('^([a-z]+)_crystals_stored$');
    if (crystal_element ~= nil) then
        return label_tokens[crystal_element] == true
            and (label_tokens.crystal == true or label_tokens.crystals == true);
    end
    if (field_name == 'op_credits') then
        return label_tokens.op == true or label_key:find('opcredits', 1, true) ~= nil;
    end
    if (field_name == 'assault_points_leujaoam') then
        return label_tokens.assault == true and (label_key:find('lsanctum', 1, true) ~= nil or label_tokens.leujaoam == true);
    end
    if (field_name == 'assault_points_mamool_ja') then
        return label_tokens.assault == true and (label_key:find('mjtg', 1, true) ~= nil or label_key:find('mamoolja', 1, true) ~= nil);
    end
    if (field_name == 'assault_points_lebros') then
        return label_tokens.assault == true and (label_key:find('lcavern', 1, true) ~= nil or label_tokens.lebros == true);
    end

    local ignored = {
        stored = true,
        point = true,
        points = true,
        currency = true,
        currencies = true,
        chapter = true,
        chapters = true,
        number = true,
        amount = true,
        total = true,
        the = true,
        ['and'] = true,
        with = true,
        credits = true,
        crystal = true,
        crystals = true,
    };

    local checked = 0;
    for word in field_name:gmatch('[a-z0-9]+') do
        if (((#word >= 3) or word:match('^%d+$')) and ignored[word] ~= true) then
            checked = checked + 1;
            local matched = label_tokens[word] == true;
            if (not matched and word == 'beastman') then
                matched = label_tokens.beastmen == true or label_key:find('beastmen', 1, true) ~= nil;
            end
            if (not matched and #word >= 5 and word:sub(-1) == 's') then
                matched = label_tokens[word:sub(1, -2)] == true;
            end
            if (not matched and (word == 'sandoria' or word == 'mamoolja' or word == 'aman' or word == 'rem' or word == 'rems')) then
                matched = label_key:find(word, 1, true) ~= nil;
                if (not matched and word == 'rems') then
                    matched = label_key:find('rem', 1, true) ~= nil;
                end
            end
            if (not matched) then
                return false;
            end
        end
    end

    return checked > 0;
end

function accessxi.currency_packet_field_name(field)
    if (field == nil) then
        return '';
    end
    return tostring(field.name or ''):lower();
end

function accessxi.currency_packet_field_by_name(name, page)
    name = tostring(name or ''):lower();
    if (name == '') then
        return nil;
    end

    local fields = tonumber(page) == 2 and accessxi.currency_packet_118_fields or accessxi.currency_packet_113_fields;
    for _, field in ipairs(fields or T{}) do
        if (accessxi.currency_packet_field_name(field) == name) then
            return field;
        end
    end
    return nil;
end

function accessxi.currency_packet_value_for_field(field, page)
    if (field == nil) then
        return nil;
    end

    local data = tonumber(page) == 2 and tostring(accessxi.currency_packet_118 or '') or tostring(accessxi.currency_packet_113 or '');
    if (data == '') then
        return nil;
    end
    return accessxi.currency_packet_value(data, field);
end

function accessxi.currency_packet_field_for_native_label(label, page)
    label = tostring(label or ''):trim();
    if (label == '') then
        return nil;
    end

    local fields = tonumber(page) == 2 and accessxi.currency_packet_118_fields or accessxi.currency_packet_113_fields;
    for _, field in ipairs(fields or T{}) do
        if (accessxi.currency_label_matches_packet_field(label, field)) then
            return field;
        end
    end
    return nil;
end

function accessxi.currency_native_label_for_field(label_bank, help_bank, field)
    label_bank = tonumber(label_bank) or 0;
    help_bank = tonumber(help_bank) or 0;
    local field_name = field ~= nil and tostring(field.name or '') or '';
    if (field_name == '' or not accessxi.is_probe_pointer(label_bank)) then
        return '', -1, 0, '', 0;
    end
    if (field_name:match('^[a-z]+_crystals_stored$') ~= nil) then
        return '', -1, 0, '', 0;
    end

    local cache = accessxi.currency_native_entry_cache;
    if (type(cache) ~= 'table') then
        cache = {};
        accessxi.currency_native_entry_cache = cache;
    end
    local key = ('fieldlabel:%08X:%08X:%s'):fmt(label_bank, help_bank, field_name);
    local cached = cache[key];
    if (type(cached) == 'table') then
        return tostring(cached.label or ''), tonumber(cached.index) or -1, tonumber(cached.label_ptr) or 0, tostring(cached.help or ''), tonumber(cached.help_ptr) or 0;
    end

    local best = nil;
    local expected_label_key = accessxi.currency_packet_field_label(field):lower():gsub('[^a-z0-9]+', '');
    for index = 0, 220 do
        local label, label_ptr = accessxi.currency_native_dmsg_entry(label_bank, index, 'label');
        if (label ~= '' and accessxi.currency_label_matches_packet_field(label, field)) then
            local help = '';
            local help_ptr = 0;
            local candidate_help, candidate_help_ptr = accessxi.currency_native_dmsg_entry(help_bank, index + 2, 'help');
            if (accessxi.currency_help_matches_label(label, candidate_help)) then
                help = candidate_help;
                help_ptr = candidate_help_ptr;
            end
            local label_key = label:lower():gsub('[^a-z0-9]+', '');
            local score = 1;
            if (help ~= '') then
                score = score + 20;
            end
            if (expected_label_key ~= '' and label_key == expected_label_key) then
                score = score + 8;
            end
            if (best == nil or score > (tonumber(best.score) or 0)) then
                best = {
                    score = score,
                    label = label,
                    index = index,
                    label_ptr = label_ptr,
                    help = help,
                    help_ptr = help_ptr,
                };
            end
        end
    end

    if (best ~= nil) then
        cache[key] = {
            label = best.label,
            index = best.index,
            label_ptr = best.label_ptr,
            help = best.help,
            help_ptr = best.help_ptr,
        };
        return best.label, best.index, best.label_ptr, best.help, best.help_ptr;
    end

    cache[key] = {
        label = '',
        index = -1,
        label_ptr = 0,
        help = '',
        help_ptr = 0,
    };
    return '', -1, 0, '', 0;
end

function accessxi.log_currency_display_order_with_help(page)
    page = tonumber(page) or 1;
    local fields = page == 2 and (accessxi.currency_packet_118_display_fields or accessxi.currency_packet_118_fields) or accessxi.currency_packet_113_display_fields;
    local data = page == 2 and tostring(accessxi.currency_packet_118 or '') or tostring(accessxi.currency_packet_113 or '');
    local help_bank = tonumber(accessxi.currency_native_help_bank) or 0;
    local label_bank = accessxi.currency_native_find_label_bank(help_bank);
    if (not accessxi.is_probe_pointer(label_bank)) then
        log_line(('currencydisplay page=%d unavailable reason="missing-label-bank" helpBank=0x%08X'):fmt(
            page,
            help_bank));
        return;
    end

    log_line(('currencydisplay page=%d fields=%d labelBank=0x%08X helpBank=0x%08X dataLen=%d'):fmt(
        page,
        fields ~= nil and fields:len() or 0,
        tonumber(label_bank) or 0,
        help_bank,
        #data));

    for raw = 0, math.min((fields ~= nil and fields:len() or 0) - 1, 140) do
        local field = fields[raw + 1];
        local value = nil;
        if (field ~= nil and data ~= '') then
            value = accessxi.currency_packet_value(data, field);
        end

        local label, label_index, label_ptr, help, help_ptr = accessxi.currency_native_label_for_field(label_bank, help_bank, field);
        if (help == '') then
            local mapped_help, mapped_help_ptr = accessxi.currency_item_help_for_packet_field(field, help_bank);
            if (mapped_help ~= '') then
                help = mapped_help;
                help_ptr = mapped_help_ptr;
            end
        end
        local source = 'native-field';
        if (label == '') then
            local item_label = accessxi.currency_item_label_for_packet_field(field);
            if (item_label ~= '') then
                label = item_label;
                source = 'item';
                help, help_ptr = accessxi.currency_item_help_for_packet_field(field, help_bank);
            else
                label = accessxi.currency_packet_field_label(field);
                source = 'packet-schema';
                if (help == '') then
                    help, help_ptr = accessxi.currency_item_help_for_packet_field(field, help_bank);
                end
            end
            label_index = -1;
            label_ptr = 0;
        end

        local row_label_index = raw;
        if (page == 1 and raw >= 19) then
            row_label_index = raw - 8;
        end
        local row_label, row_label_ptr = accessxi.currency_native_dmsg_entry(label_bank, row_label_index, 'label');
        local row_help, row_help_ptr = accessxi.currency_native_dmsg_entry(help_bank, row_label_index + 2, 'help');

        log_line(('currencydisplay row=%d page=%d field="%s" value="%s" source="%s" labelIndex=%d labelPtr=0x%08X label="%s" helpPtr=0x%08X help="%s" rowLabelIndex=%d rowLabelPtr=0x%08X rowLabel="%s" rowHelpPtr=0x%08X rowHelp="%s"'):fmt(
            raw,
            page,
            field ~= nil and accessxi.escape_probe_log_text(field.name or '') or '',
            value ~= nil and accessxi.format_currency_number(value) or '',
            source,
            tonumber(label_index) or -1,
            tonumber(label_ptr) or 0,
            accessxi.escape_probe_log_text(label or ''),
            tonumber(help_ptr) or 0,
            accessxi.escape_probe_log_text(help or ''),
            row_label_index,
            tonumber(row_label_ptr) or 0,
            accessxi.escape_probe_log_text(row_label or ''),
            tonumber(row_help_ptr) or 0,
            accessxi.escape_probe_log_text(row_help or '')));
    end
end

function accessxi.currency_item_label_for_packet_field(field)
    local field_name = '';
    if (field ~= nil) then
        field_name = tostring(field.name or ''):lower();
    end
    if (field_name == '') then
        return '', 0;
    end

    local crystal_set_labels = accessxi.currency_menu_data.item_labels or {};
    local label = tostring(crystal_set_labels[field_name] or '');
    if (label == '') then
        return '', 0;
    end
    return label, 0;
end

function accessxi.currency_item_help_for_packet_field(field, help_bank)
    local field_name = '';
    if (field ~= nil) then
        field_name = tostring(field.name or ''):lower();
    end
    help_bank = tonumber(help_bank) or tonumber(accessxi.currency_native_help_bank) or 0;
    if (field_name == '' or not accessxi.is_probe_pointer(help_bank)) then
        return '', 0;
    end

    -- These are native d_msg help-bank indices from the Currencies UI string
    -- table, discovered from the live client. They are only used to fill help
    -- text for packet-backed rows where the adjacent native help slot is blank.
    local help_indices = accessxi.currency_menu_data.help_indices or {};
    local index = tonumber(help_indices[field_name]) or -1;
    if (index < 0) then
        return '', 0;
    end

    local help, help_ptr = accessxi.currency_native_dmsg_entry(help_bank, index, 'help');
    if (help == '' or not accessxi.currency_help_looks_like_currency(help)) then
        return '', 0;
    end
    return help, help_ptr;
end

function accessxi.currency_native_value_for_logical(logical_id, title, raw_index)
    logical_id = tonumber(logical_id);
    if (logical_id == nil or logical_id < 0) then
        return nil;
    end
    raw_index = tonumber(raw_index);

    local title_text = tostring(title or '');
    local page = tonumber(accessxi.current_currency_menu_page) or 1;
    if (title_text:contains('2', true)) then
        page = 2;
    end
    local page_age = tick() - (tonumber(accessxi.current_currency_menu_page_tick) or 0);
    if (page ~= 2 and page_age > 6000) then
        page = 1;
    end

    local packet_id = page == 2 and 0x0118 or 0x0113;
    local fields = page == 2 and (accessxi.currency_packet_118_display_fields or accessxi.currency_packet_118_fields) or (accessxi.currency_packet_113_display_fields or accessxi.currency_packet_113_fields);
    local data = page == 2 and tostring(accessxi.currency_packet_118 or '') or tostring(accessxi.currency_packet_113 or '');
    local index = raw_index;
    if (index == nil or index < 0) then
        index = logical_id;
    end
    local count = fields ~= nil and fields:len() or 0;
    if (index >= count) then
        return nil;
    end

    local field = fields[index + 1];
    if (field == nil or data == '') then
        return nil;
    end

    local value = accessxi.currency_packet_value(data, field);
    if (value == nil) then
        return nil;
    end

    return value, field, packet_id, page;
end

function accessxi.currency_native_menu_text(menu_name, title, selected, count, entry, raw, child)
    local help_bank = tonumber(accessxi.currency_native_help_bank) or 0;
    if (not accessxi.currency_native_remember_help_bank(help_bank)) then
        return nil;
    end

    local label_bank = accessxi.currency_native_find_label_bank(help_bank);
    if (not accessxi.is_probe_pointer(label_bank)) then
        return nil;
    end

    local raw_index = bit.band(tonumber(raw) or -1, 0xFFFF);
    local logical_id = accessxi.currency_menu_native_logical_id(child, raw_index);
    if (logical_id == nil) then
        log_state(('state nativemenu currency-native missing-logical menu="%s" title="%s" select=%d count=%d raw=%d child=0x%08X'):fmt(
            tostring(menu_name or ''),
            tostring(title or ''),
            tonumber(selected) or 0,
            tonumber(count) or 0,
            tonumber(raw) or -1,
            tonumber(child) or 0));
        return nil;
    end

    local label_index = accessxi.currency_native_label_index_for_logical(logical_id);
    if (label_index == nil) then
        local unresolved_key = ('%s:%s:%d:%d:%d:%d:%08X:%08X'):fmt(
            tostring(menu_name or ''),
            tostring(title or ''),
            tonumber(selected) or 0,
            tonumber(count) or 0,
            tonumber(raw) or -1,
            tonumber(logical_id) or -1,
            tonumber(child) or 0,
            tonumber(entry) or 0);
        if (unresolved_key ~= tostring(accessxi.last_currency_unresolved_key or '')) then
            accessxi.last_currency_unresolved_key = unresolved_key;
            log_state(('state nativemenu currency-native unresolved-logical menu="%s" title="%s" select=%d count=%d raw=%d logical=%d child=0x%08X entry=0x%08X helpBank=0x%08X labelBank=0x%08X'):fmt(
                tostring(menu_name or ''),
                tostring(title or ''),
                tonumber(selected) or 0,
                tonumber(count) or 0,
                tonumber(raw) or -1,
                tonumber(logical_id) or -1,
                tonumber(child) or 0,
                tonumber(entry) or 0,
                tonumber(help_bank) or 0,
                tonumber(label_bank) or 0));
        end
        return nil;
    end

    local label, label_ptr = accessxi.currency_native_dmsg_entry(label_bank, label_index, 'label');
    if (label == '') then
        log_state(('state nativemenu currency-native missing-label menu="%s" title="%s" select=%d count=%d raw=%d logical=%d labelIndex=%d labelBank=0x%08X'):fmt(
            tostring(menu_name or ''),
            tostring(title or ''),
            tonumber(selected) or 0,
            tonumber(count) or 0,
            tonumber(raw) or -1,
            tonumber(logical_id) or -1,
            tonumber(label_index) or -1,
            tonumber(label_bank) or 0));
    end

    local help = '';
    local help_ptr = 0;
    local candidate_help, candidate_help_ptr = accessxi.currency_native_dmsg_entry(help_bank, logical_id + 2, 'help');
    if (accessxi.currency_help_matches_label(label, candidate_help)) then
        help = candidate_help;
        help_ptr = candidate_help_ptr;
    end
    local value, value_field, value_packet, value_page = accessxi.currency_native_value_for_logical(logical_id, title, raw_index);
    local native_row_label = label;
    local native_row_help = help;
    local native_row_label_index = label_index;
    local native_row_label_ptr = label_ptr;
    local native_row_help_ptr = help_ptr;
    local native_label_field = accessxi.currency_packet_field_for_native_label(native_row_label, value_page);
    local native_label_matches_value_field = native_label_field ~= nil
        and value_field ~= nil
        and accessxi.currency_packet_field_name(native_label_field) == accessxi.currency_packet_field_name(value_field);
    local value_text = '';
    if (value ~= nil) then
        value_text = accessxi.format_currency_number(value);
    end
    local item_label_source = '';
    local item_label_id = 0;
    local field_label, field_label_index, field_label_ptr, field_help, field_help_ptr = accessxi.currency_native_label_for_field(label_bank, help_bank, value_field);
    if (field_label ~= '') then
        label = field_label;
        label_index = field_label_index;
        label_ptr = field_label_ptr;
        help = field_help;
        help_ptr = field_help_ptr;
    end
    if (help == '') then
        local mapped_help, mapped_help_ptr = accessxi.currency_item_help_for_packet_field(value_field, help_bank);
        if (mapped_help ~= '') then
            help = mapped_help;
            help_ptr = mapped_help_ptr;
        end
    end
    local field_item_label, field_item_id = accessxi.currency_item_label_for_packet_field(value_field);
    if (field_label == '' and field_item_label ~= '') then
        label = field_item_label;
        label_ptr = 0;
        help, help_ptr = accessxi.currency_item_help_for_packet_field(value_field, help_bank);
        item_label_source = 'currency-stored';
        item_label_id = field_item_id;
    end
    if (field_label == ''
        and field_item_label == ''
        and value_field ~= nil
        and not native_label_matches_value_field) then
        local packet_label = accessxi.currency_packet_field_label(value_field);
        if (packet_label ~= '') then
            label = packet_label;
            label_index = native_row_label_index;
            label_ptr = 0;
            help, help_ptr = accessxi.currency_item_help_for_packet_field(value_field, help_bank);
            item_label_source = 'packet-schema';
            item_label_id = 0;
        end
    end
    local label_matches_value_field = item_label_source == 'item'
        or item_label_source == 'packet-schema'
        or accessxi.currency_label_matches_packet_field(label, value_field);
    if ((value_field ~= nil and label_matches_value_field ~= true)
        or (value_field == nil and help == '')) then
        local rejected_key = ('%s:%d:%d:%d:%s:%s'):fmt(
            tostring(menu_name or ''),
            tonumber(selected) or 0,
            tonumber(raw) or -1,
            tonumber(logical_id) or -1,
            label,
            value_field ~= nil and tostring(value_field.name or '') or '');
        if (rejected_key ~= tostring(accessxi.last_currency_rejected_label_key or '')) then
            accessxi.last_currency_rejected_label_key = rejected_key;
            log_state(('state nativemenu currency-native rejected-label menu="%s" title="%s" select=%d count=%d raw=%d logical=%d labelIndex=%d child=0x%08X entry=0x%08X valuePacket=0x%03X valuePage=%d valueField="%s" value="%s" labelSource="%s" itemId=%d label="%s" help="%s" reason="%s"'):fmt(
                tostring(menu_name or ''),
                tostring(title or ''),
                tonumber(selected) or 0,
                tonumber(count) or 0,
                tonumber(raw) or -1,
                tonumber(logical_id) or -1,
                tonumber(label_index) or -1,
                tonumber(child) or 0,
                tonumber(entry) or 0,
                tonumber(value_packet) or 0,
                tonumber(value_page) or 0,
                value_field ~= nil and tostring(value_field.name or '') or '',
                value_text,
                item_label_source,
                tonumber(item_label_id) or 0,
                accessxi.escape_probe_log_text(label),
                accessxi.escape_probe_log_text(help),
                value_field ~= nil and 'label-field-mismatch' or 'unproven-empty-help'));
        end
        return nil;
    end

    local key = ('%s:%d:%d:%d:%s:%s'):fmt(
        tostring(menu_name or ''),
        tonumber(selected) or 0,
        tonumber(raw) or -1,
        tonumber(label_index) or -1,
        label,
        help .. ':' .. value_text);
    local now = tick();
    if (key ~= tostring(accessxi.last_currency_resource_key or '')
        or (now - (tonumber(accessxi.last_currency_resource_tick) or 0)) >= 1000) then
        accessxi.last_currency_resource_key = key;
        accessxi.last_currency_resource_tick = now;
        log_state(('state nativemenu currency-native menu="%s" title="%s" select=%d count=%d raw=%d logical=%d labelIndex=%d child=0x%08X entry=0x%08X helpBank=0x%08X labelBank=0x%08X labelPtr=0x%08X helpPtr=0x%08X valuePacket=0x%03X valuePage=%d valueField="%s" value="%s" labelSource="%s" itemId=%d label="%s" help="%s"'):fmt(
            tostring(menu_name or ''),
            tostring(title or ''),
            tonumber(selected) or 0,
            tonumber(count) or 0,
            tonumber(raw) or -1,
            tonumber(logical_id) or -1,
            tonumber(label_index) or -1,
            tonumber(child) or 0,
            tonumber(entry) or 0,
            tonumber(help_bank) or 0,
            tonumber(label_bank) or 0,
            tonumber(label_ptr) or 0,
            tonumber(help_ptr) or 0,
            tonumber(value_packet) or 0,
            tonumber(value_page) or 0,
            value_field ~= nil and tostring(value_field.name or '') or '',
            value_text,
            item_label_source,
            tonumber(item_label_id) or 0,
            accessxi.escape_probe_log_text(label),
            accessxi.escape_probe_log_text(help)));
    end

    accessxi.last_native_menu_name = tostring(menu_name or '');
    accessxi.last_native_menu_label = label;
    accessxi.last_native_menu_selected = tonumber(selected) or 0;
    accessxi.last_native_menu_tick = tick();
    accessxi.current_speech_key = ('native-known-currency:%s:%d:%d:%d:%s'):fmt(
        tostring(menu_name or ''),
        tonumber(selected) or 0,
        tonumber(raw) or -1,
        tonumber(label_index) or -1,
        label);
    local amount = '';
    if (value_text ~= '') then
        amount = accessxi.sentence_fragment(value_text);
    end
    if (amount ~= '' and help ~= '') then
        return ('%s. %s %s %s'):fmt(tostring(title or 'Currencies'), accessxi.sentence_fragment(label), amount, accessxi.sentence_fragment(help));
    elseif (amount ~= '') then
        return ('%s. %s %s'):fmt(tostring(title or 'Currencies'), accessxi.sentence_fragment(label), amount);
    elseif (help ~= '') then
        return ('%s. %s %s'):fmt(tostring(title or 'Currencies'), accessxi.sentence_fragment(label), accessxi.sentence_fragment(help));
    end
    return ('%s. %s'):fmt(tostring(title or 'Currencies'), accessxi.sentence_fragment(label));
end

function accessxi.currency_menu_speech(menu_name, title, selected, count, entry, raw, child)
    local now = tick();
    local key_items_context_tick = tonumber(accessxi.key_items_context_until) or 0;
    local currency_context_tick = tonumber(accessxi.current_currency_menu_page_tick) or 0;
    if (tostring(menu_name or ''):eq('menu    evitem', true)
        and key_items_context_tick >= now
        and (currency_context_tick <= 0 or (now - currency_context_tick) > 120000)) then
        return nil;
    end

    local native_text = accessxi.currency_native_menu_text(menu_name, title, selected, count, entry, raw, child);
    if (native_text ~= nil) then
        return native_text;
    end

    if (accessxi.currency_packet_menu_speech_enabled ~= true) then
        log_state(('state nativemenu currency-resource disabled-native-only menu="%s" title="%s" select=%d count=%d entry=0x%08X raw=%d'):fmt(
            tostring(menu_name or ''),
            tostring(title or ''),
            tonumber(selected) or 0,
            tonumber(count) or 0,
            tonumber(entry) or 0,
            tonumber(raw) or -1));
        return nil;
    end

    local info = accessxi.currency_menu_resource_for_entry(entry, title, selected, raw);
    if (info == nil) then
        local key = ('%s:%s:%d:%d:%08X:%d'):fmt(
            tostring(menu_name or ''),
            tostring(title or ''),
            tonumber(selected) or 0,
            tonumber(count) or 0,
            tonumber(entry) or 0,
            tonumber(raw) or -1);
        local now = tick();
        if (key ~= tostring(accessxi.last_currency_unresolved_key or '')
            or (now - (tonumber(accessxi.last_currency_unresolved_tick) or 0)) >= 1000) then
            accessxi.last_currency_unresolved_key = key;
            accessxi.last_currency_unresolved_tick = now;
            log_state(('state nativemenu currency-resource unresolved-native-only menu="%s" title="%s" select=%d count=%d raw=%d entry=0x%08X'):fmt(
                tostring(menu_name or ''),
                tostring(title or ''),
                tonumber(selected) or 0,
                tonumber(count) or 0,
                tonumber(raw) or -1,
                tonumber(entry) or 0));
        end
        return nil;
    end

    local label = tostring(info.label or '');
    local key = ('%s:%d:%d:%08X:%08X:%s'):fmt(
        tostring(menu_name or ''),
        tonumber(selected) or 0,
        tonumber(info.id) or 0,
        tonumber(info.row_code or info.code) or 0,
        tonumber(info.row_visual_code) or 0,
        label);
    local now = tick();
    if (key ~= tostring(accessxi.last_currency_resource_key or '')
        or (now - (tonumber(accessxi.last_currency_resource_tick) or 0)) >= 1000) then
        accessxi.last_currency_resource_key = key;
        accessxi.last_currency_resource_tick = now;
        local value_text = info.value ~= nil and tostring(tonumber(info.value) or 0) or '';
        log_state(('state nativemenu currency-resource menu="%s" title="%s" page=%d select=%d count=%d raw=%d rawIndex=%d selectedIndex=%d entry=0x%08X desc=0x%08X row0=0x%08X rowCode=0x%08X rowVisual=0x%08X id=%d resourceId=%d type=%d label="%s" value="%s" desc="%s"'):fmt(
            tostring(menu_name or ''),
            tostring(title or ''),
            tonumber(info.page) or 0,
            tonumber(selected) or 0,
            tonumber(count) or 0,
            tonumber(raw) or -1,
            tonumber(info.raw_index) or -1,
            tonumber(info.selected_index) or -1,
            tonumber(entry) or 0,
            tonumber(info.desc) or 0,
            tonumber(info.row0) or 0,
            tonumber(info.row_code or info.code) or 0,
            tonumber(info.row_visual_code) or 0,
            tonumber(info.id) or 0,
            tonumber(info.resource_id) or 0,
            tonumber(info.resource_type) or 0,
            accessxi.escape_probe_log_text(label),
            value_text,
            accessxi.escape_probe_log_text(info.description or '')));
    end
    if (label == '') then
        return nil;
    end

    accessxi.last_native_menu_name = tostring(menu_name or '');
    accessxi.last_native_menu_label = label;
    accessxi.last_native_menu_selected = tonumber(selected) or 0;
    accessxi.last_native_menu_tick = tick();
    accessxi.current_speech_key = ('native-known-currency-resource:%s:%d:%d:%s'):fmt(
        tostring(menu_name or ''),
        tonumber(selected) or 0,
        tonumber(info.row_code or info.code) or 0,
        label);
    local speech_title = tonumber(info.resource_type) == 0x0118 and 'Currencies 2' or tostring(title or 'Currencies');
    local amount = info.value ~= nil and accessxi.format_currency_number(info.value) or '';
    if (amount ~= '') then
        return ('%s. %s %s.'):fmt(
            speech_title,
            accessxi.sentence_fragment(label),
            amount);
    end
    return ('%s. %s.'):fmt(
        speech_title,
        accessxi.sentence_fragment(label));
end

function accessxi.log_key_items_parent_probe(menu_name, title, selected, count, page, raw, child, entry, reason)
    menu_name = tostring(menu_name or '');
    if (not menu_name:eq('menu    evitem', true)) then
        return;
    end

    selected = tonumber(selected) or 0;
    count = tonumber(count) or 0;
    page = tonumber(page) or 0;
    raw = tonumber(raw) or 0;
    child = tonumber(child) or 0;
    entry = tonumber(entry) or 0;

    local label_ptr = accessxi.is_probe_pointer(entry) and (read_u32(entry + 0x44) or 0) or 0;
    local help_ptr = accessxi.is_probe_pointer(entry) and (read_u32(entry + 0x40) or 0) or 0;
    local desc_ptr = accessxi.is_probe_pointer(entry) and (read_u32(entry + 0x0C) or 0) or 0;
    local obj = get_current_menu_object_ptr();
    local target = AshitaCore:GetMemoryManager():GetTarget();
    local window_name = '';
    local window_loaded = -1;
    if (target ~= nil) then
        window_name = clean_probe_text(safe_call(function () return target:GetWindowName(); end, ''));
        window_loaded = tonumber(safe_call(function () return target:GetWindowIsWindowLoaded(); end, -1)) or -1;
    end
    local desc_base = 0;
    if (accessxi.is_probe_pointer(desc_ptr) and selected > 0) then
        desc_base = desc_ptr - ((selected - 1) * 0x14);
    end
    local key = ('%s:%s:%d:%d:%d:%d:%08X:%08X:%08X:%08X:%08X'):fmt(
        menu_name,
        tostring(reason or ''),
        selected,
        count,
        page,
        raw,
        child,
        entry,
        label_ptr,
        help_ptr,
        desc_ptr);
    if (key == tostring(accessxi.last_key_items_parent_probe_key or '')) then
        return;
    end
    accessxi.last_key_items_parent_probe_key = key;

    log_state(('state key-items parent-probe reason="%s" menu="%s" title="%s" window="%s" windowLoaded=%d selected=%d count=%d page=%d raw=0x%08X obj=0x%08X child=0x%08X entry=0x%08X labelPtr=0x%08X label="%s" helpPtr=0x%08X help="%s" desc=0x%08X descBase=0x%08X objDwords="%s" childDwords="%s" entryDwords="%s" descDwords="%s" descBytes="%s" descBaseDwords="%s" descInline="%s" childInline="%s" entryInline="%s" childRuns="%s" entryRuns="%s" descPtrs="%s" childPtrs="%s" entryPtrs="%s"'):fmt(
        tostring(reason or ''),
        menu_name,
        accessxi.escape_probe_log_text(tostring(title or '')),
        accessxi.escape_probe_log_text(window_name),
        window_loaded,
        selected,
        count,
        page,
        raw,
        tonumber(obj) or 0,
        child,
        entry,
        label_ptr,
        accessxi.escape_probe_log_text(read_probe_string(label_ptr, 160)),
        help_ptr,
        accessxi.escape_probe_log_text(read_probe_string(help_ptr, 220)),
        desc_ptr,
        desc_base,
        accessxi.escape_probe_log_text_wide(accessxi.format_probe_dwords(obj, 0x00, 36)),
        accessxi.escape_probe_log_text_wide(accessxi.format_probe_dwords(child, 0x00, 32)),
        accessxi.escape_probe_log_text_wide(accessxi.format_probe_dwords(entry, 0x00, 32)),
        accessxi.escape_probe_log_text_wide(accessxi.format_probe_dwords(desc_ptr, 0x00, 12)),
        accessxi.escape_probe_log_text_wide(accessxi.format_probe_bytes(desc_ptr, 0x00, 0x60)),
        accessxi.escape_probe_log_text_wide(accessxi.format_probe_dwords(desc_base, 0x00, 50)),
        accessxi.escape_probe_log_text(accessxi.status_menu_probe_inline_strings(desc_ptr)),
        accessxi.escape_probe_log_text(accessxi.status_menu_probe_inline_strings(child)),
        accessxi.escape_probe_log_text(accessxi.status_menu_probe_inline_strings(entry)),
        accessxi.escape_probe_log_text(accessxi.status_menu_probe_runs(child, 0x180)),
        accessxi.escape_probe_log_text(accessxi.status_menu_probe_runs(entry, 0x180)),
        accessxi.escape_probe_log_text(accessxi.status_menu_probe_pointer_fields(desc_ptr)),
        accessxi.escape_probe_log_text(accessxi.status_menu_probe_pointer_fields(child)),
        accessxi.escape_probe_log_text(accessxi.status_menu_probe_pointer_fields(entry))));
end

function accessxi.key_items_context_active()
    local now = tick();
    if ((tonumber(accessxi.key_items_context_until) or 0) < now) then
        return false;
    end
    local currency_context_tick = tonumber(accessxi.current_currency_menu_page_tick) or 0;
    if (currency_context_tick > 0 and (now - currency_context_tick) <= 120000) then
        return false;
    end
    return true;
end

function accessxi.key_items_native_view_kind(child)
    child = tonumber(child) or 0;
    if (not accessxi.is_probe_pointer(child)) then
        return nil, -1;
    end
    -- Ghidra: FFXiMain FUN_102292d0 builds native category headers and stores
    -- state 1 at +0x90. FUN_10229ec0 builds the selected category's item rows,
    -- and FUN_1022a600 stores state 2. Counts and scroll ranges can be identical
    -- in the two views, so they must never be used as the view identity.
    local native_state = tonumber(read_i32(child + 0x90)) or -1;
    local dynamic = accessxi.load_key_items_dynamic_rows();
    if (type(dynamic) ~= 'table' or type(dynamic.classify_native_view) ~= 'function') then
        return nil, native_state;
    end
    return dynamic.classify_native_view(native_state), native_state;
end

function accessxi.key_items_parent_native_shape(child, count)
    local view_kind = accessxi.key_items_native_view_kind(child);
    return tostring(view_kind or ''):eq('categories', true);
end

function accessxi.key_items_sublist_context_active(count, child)
    count = tonumber(count) or 0;
    child = tonumber(child) or 0;
    if (count <= 0 or not accessxi.is_probe_pointer(child)) then
        return false;
    end
    if (not accessxi.key_items_context_active()) then
        return false;
    end
    local view_kind = accessxi.key_items_native_view_kind(child);
    if (not tostring(view_kind or ''):eq('items', true)) then
        return false;
    end
    if (tostring(accessxi.key_items_current_category_label or '') == '') then
        return false;
    end
    return true;
end

function accessxi.key_items_set_current_category(index, label)
    index = tonumber(index) or -1;
    label = tostring(label or '');
    if (label == '') then
        return;
    end
    accessxi.key_items_current_category_index = index;
    accessxi.key_items_current_category_label = label;
    accessxi.key_items_current_category_tick = tick();
    accessxi.key_items_context_until = tick() + 120000;
end

function accessxi.load_key_items_resource()
    if (accessxi.key_items_resource ~= nil) then
        return accessxi.key_items_resource;
    end
    if (accessxi.key_items_resource_load_tried == true) then
        return nil;
    end
    accessxi.key_items_resource_load_tried = true;

    local paths = T{
        accessxi.resource_path('windower', 'key_items.lua'),
    };
    for _, path in ipairs(paths) do
        local f = io.open(path, 'rb');
        if (f ~= nil) then
            f:close();
            local ok, data = pcall(function ()
                return loadfile(path)();
            end);
            if (ok and type(data) == 'table') then
                accessxi.key_items_resource = data;
                accessxi.key_items_resource_path = path;
                log_line(('loaded key items resource path="%s"'):fmt(path));
                return accessxi.key_items_resource;
            end
            log_line(('key items resource load failed path="%s" err="%s"'):fmt(path, tostring(data)));
        end
    end

    log_line('key items resource unavailable');
    return nil;
end

function accessxi.load_key_items_dat_order()
    if (type(accessxi.key_items_dat_order) == 'table') then
        return accessxi.key_items_dat_order;
    end
    if (accessxi.key_items_dat_order_load_tried == true) then
        return nil;
    end
    accessxi.key_items_dat_order_load_tried = true;

    local data = accessxi.load_module_table('key_items_dat_order', nil);
    if (type(data) == 'table' and next(data) ~= nil) then
        accessxi.key_items_dat_order = data;
        log_line('loaded key items native DAT order module');
        return accessxi.key_items_dat_order;
    end

    log_line('key items native DAT order unavailable');
    return nil;
end

function accessxi.load_key_items_dat_details()
    if (type(accessxi.key_items_dat_details) == 'table') then
        return accessxi.key_items_dat_details;
    end
    if (accessxi.key_items_dat_details_load_tried == true) then
        return nil;
    end
    accessxi.key_items_dat_details_load_tried = true;

    local data = accessxi.load_module_table('key_items_dat_details', nil);
    if (type(data) == 'table' and next(data) ~= nil) then
        accessxi.key_items_dat_details = data;
        log_line('loaded key items native DAT details module');
        return accessxi.key_items_dat_details;
    end

    log_line('key items native DAT details unavailable');
    return nil;
end

function accessxi.load_key_items_dynamic_rows()
    if (type(accessxi.key_items_dynamic_rows) == 'table') then
        return accessxi.key_items_dynamic_rows;
    end
    if (accessxi.key_items_dynamic_rows_load_tried == true) then
        return nil;
    end
    accessxi.key_items_dynamic_rows_load_tried = true;

    local data = accessxi.load_module_table('key_items_dynamic_rows', nil);
    if (type(data) == 'table'
        and type(data.build_owned_rows) == 'function'
        and type(data.resolve_selected_row) == 'function'
        and type(data.build_category_rows) == 'function'
        and type(data.classify_native_view) == 'function') then
        accessxi.key_items_dynamic_rows = data;
        log_line('loaded dynamic key items identity resolver');
        return accessxi.key_items_dynamic_rows;
    end

    log_line('dynamic key items identity resolver unavailable');
    return nil;
end

function accessxi.key_items_parent_category_rows()
    if (type(accessxi.key_items_parent_category_rows_cache) == 'table') then
        return accessxi.key_items_parent_category_rows_cache;
    end

    local resource = accessxi.load_key_items_resource();
    local order = accessxi.load_key_items_dat_order();
    local dynamic = accessxi.load_key_items_dynamic_rows();
    if (type(resource) ~= 'table' or type(order) ~= 'table' or type(dynamic) ~= 'table'
        or type(dynamic.build_category_rows) ~= 'function') then
        return nil;
    end

    local built_rows = dynamic.build_category_rows(resource, order);
    if (type(built_rows) ~= 'table' or #built_rows <= 0) then
        return nil;
    end

    local rows = T{};
    for _, row in ipairs(built_rows) do
        local label = accessxi.plain_native_menu_label(tostring(row.label or ''));
        local display_order = tonumber(row.order);
        if (label == '' or display_order == nil) then
            return nil;
        end
        rows:append({
            label = label,
            order = display_order,
        });
    end
    accessxi.key_items_parent_category_rows_cache = rows;
    return rows;
end

function accessxi.key_items_current_item_age()
    return tick() - (tonumber(accessxi.key_items_current_item_tick) or 0);
end

function accessxi.key_items_current_item_detail()
    local id = tonumber(accessxi.key_items_current_item_id) or 0;
    if (id <= 0 or accessxi.key_items_current_item_age() < 0 or accessxi.key_items_current_item_age() > 120000) then
        return nil;
    end
    if (not accessxi.key_items_packet_has_id(id)) then
        return nil;
    end
    local details = accessxi.load_key_items_dat_details();
    if (type(details) ~= 'table') then
        return nil;
    end
    local detail = details[id];
    if (type(detail) ~= 'table') then
        return nil;
    end
    local label = tostring(accessxi.key_items_current_item_label or '');
    if (label == '') then
        label = accessxi.key_items_resource_label(detail);
    end
    if (label == '') then
        label = tostring(detail.name or '');
    end
    label = accessxi.plain_native_menu_label(label);
    local description = accessxi.plain_native_menu_help(tostring(detail.description or ''));
    if (label == '' and description == '') then
        return nil;
    end
    return {
        id = id,
        label = label,
        description = description,
    };
end

function accessxi.key_items_effective_category(id, category)
    id = tonumber(id) or -1;
    category = tostring(category or '');
    -- The client displays White Card under Permanent Key Items even though
    -- Windower's generated category currently tags it as Temporary.
    if (id == 349) then
        return 'Permanent Key Items';
    end
    -- Cipher bracelet is present in the live DAT and ownership packet, but is
    -- absent from Windower's generated key-items resource.
    if (id == 3361) then
        return 'Permanent Key Items';
    end
    return category;
end

function accessxi.key_items_display_order(category, id)
    id = tonumber(id) or 0;
    local order = accessxi.load_key_items_dat_order();
    if (type(order) ~= 'table') then
        return nil;
    end
    return tonumber(order[id]);
end

function accessxi.key_items_resource_label(entry)
    if (type(entry) ~= 'table') then
        return '';
    end
    local text = tostring(entry.en or entry.english or entry.name or '');
    if (text == '') then
        return '';
    end
    text = text:gsub('\226\128\153', "'");
    text = text:gsub('\226\128\152', "'");
    text = text:gsub('\226\128\156', '"');
    text = text:gsub('\226\128\157', '"');
    text = text:gsub('\226\136\174', '');
    text = text:gsub('\226\153\170', '');
    text = text:gsub('%s+', ' '):trim();
    return accessxi.plain_native_menu_label(accessxi.survival_guide_text(text));
end

function accessxi.objective_key_item_name_key(value)
    local text = tostring(value or ''):lower();
    -- Treat typographic apostrophes, quotes, and dashes exactly like their
    -- ASCII punctuation counterparts before collapsing punctuation/spacing.
    text = text:gsub('\226\128\152', ' ');
    text = text:gsub('\226\128\153', ' ');
    text = text:gsub('\226\128\156', ' ');
    text = text:gsub('\226\128\157', ' ');
    text = text:gsub('\226\128\144', ' ');
    text = text:gsub('\226\128\145', ' ');
    text = text:gsub('\226\128\146', ' ');
    text = text:gsub('\226\128\147', ' ');
    text = text:gsub('\226\128\148', ' ');
    text = text:gsub('\226\128\149', ' ');
    text = text:gsub('[%p%s]+', ' ');
    return text:gsub('^%s+', ''):gsub('%s+$', '');
end

function accessxi.objective_key_item_name_index()
    if (type(accessxi.objective_key_item_name_index_cache) == 'table') then
        return accessxi.objective_key_item_name_index_cache;
    end
    local resource = accessxi.load_key_items_resource();
    if (type(resource) ~= 'table') then
        return nil;
    end

    local index = {};
    for resource_id, entry in pairs(resource) do
        if (type(entry) == 'table') then
            local id = tonumber(entry.id or resource_id) or -1;
            local key = accessxi.objective_key_item_name_key(
                entry.en or entry.english or entry.name or '');
            if (id >= 0 and key ~= '') then
                local previous_id = index[key];
                if (previous_id == nil) then
                    index[key] = id;
                elseif (previous_id ~= id) then
                    index[key] = false;
                end
            end
        end
    end
    accessxi.objective_key_item_name_index_cache = index;
    return index;
end

function accessxi.objective_key_item_name_for_id(id)
    id = tonumber(id) or -1;
    if (id < 0) then return ''; end
    local resource = accessxi.load_key_items_resource();
    local entry = type(resource) == 'table' and resource[id] or nil;
    return accessxi.key_items_resource_label(entry);
end

function accessxi.objective_key_item_current_session_has_id(id)
    id = tonumber(id) or -1;
    local identity = type(accessxi.current_player_identity) == 'function'
        and tostring(accessxi.current_player_identity() or ''):lower() or '';
    local epoch = type(accessxi.current_objective_session_epoch) == 'function'
        and (tonumber(accessxi.current_objective_session_epoch()) or 0) or 0;
    if (id < 0 or identity == '' or epoch <= 0
        or tostring(accessxi.key_items_packet_source or '') ~= 'packet_in_055'
        or tostring(accessxi.key_items_packet_identity or ''):lower() ~= identity
        or tonumber(accessxi.key_items_packet_session_epoch) ~= epoch) then
        return false;
    end

    local table_index = math.floor(id / 512);
    local bit_index = id % 512;
    local entry = (accessxi.key_items_packet_tables or {})[table_index];
    if (type(entry) ~= 'table'
        or tostring(entry.source or '') ~= 'packet_in_055'
        or tostring(entry.identity or ''):lower() ~= identity
        or tonumber(entry.session_epoch) ~= epoch) then
        return false;
    end
    local flags = tostring(entry.flags or '');
    if (#flags < 64 or type(accessxi.packet_has_bit) ~= 'function') then
        return false;
    end
    return accessxi.packet_has_bit(flags, bit_index) == true;
end

function accessxi.objective_key_item_owned_by_name(name)
    local key = accessxi.objective_key_item_name_key(name);
    if (key == '') then
        return false, nil;
    end
    local index = accessxi.objective_key_item_name_index();
    if (type(index) ~= 'table') then
        return false, nil;
    end
    local id = index[key];
    if (type(id) ~= 'number') then
        return false, nil;
    end
    return accessxi.objective_key_item_current_session_has_id(id), id;
end

function accessxi.key_items_resource_row_for_id(id, category, resource)
    id = tonumber(id) or -1;
    category = tostring(category or '');
    if (id < 0 or category == '') then
        return nil;
    end
    resource = resource or accessxi.load_key_items_resource();
    if (type(resource) ~= 'table') then
        return nil;
    end
    local entry = resource[id];
    if (type(entry) ~= 'table') then
        return nil;
    end
    if (not accessxi.key_items_packet_has_id(id)) then
        return nil;
    end
    local effective_category = accessxi.key_items_effective_category(id, entry.category or '');
    if (not effective_category:eq(category, true)) then
        return nil;
    end
    local label = accessxi.key_items_resource_label(entry);
    if (label == '') then
        return nil;
    end
    local order = accessxi.key_items_display_order(effective_category, id);
    if (order == nil) then
        return nil;
    end
    return {
        id = id,
        label = label,
        order = order,
    };
end

function accessxi.key_items_native_id_rows_for_category(category, child, native_total)
    category = tostring(category or '');
    child = tonumber(child) or 0;
    native_total = tonumber(native_total) or 0;
    if (category == '' or native_total <= 0 or native_total > 256 or not accessxi.is_probe_pointer(child)) then
        return nil, 'invalid';
    end
    accessxi.restore_key_items_packet_cache_if_needed();
    if (next(accessxi.key_items_packet_tables or {}) == nil) then
        return nil, 'no-packet-cache';
    end

    local cache_key = ('%s:%08X:%d:%s'):fmt(category, child, native_total, accessxi.key_items_packet_cache_key());
    accessxi.key_items_native_order_cache = accessxi.key_items_native_order_cache or {};
    if (accessxi.key_items_native_order_cache[cache_key] ~= nil) then
        local cached = accessxi.key_items_native_order_cache[cache_key];
        return cached.rows, cached.mode;
    end

    do
        local dat_rows, dat_mode = accessxi.key_items_owned_rows_for_category(category);
        if (dat_rows ~= nil) then
            dat_mode = tostring(dat_mode or 'packet-owned+dat-order+identity-complete');
            accessxi.key_items_native_order_cache[cache_key] = { rows = dat_rows, mode = dat_mode };
            local sample = T{};
            for i = 1, math.min(dat_rows:len(), 8) do
                local row = dat_rows[i];
                sample:append(('%d:%d:%s'):fmt(i, tonumber(row.id) or 0, tostring(row.label or ''):gsub('"', "'")));
            end
            log_line(('key items native DAT order category="%s" child=0x%08X total=%d sample="%s"'):fmt(
                accessxi.escape_probe_log_text(category),
                child,
                native_total,
                accessxi.escape_probe_log_text(sample:concat(' | '))));
            return dat_rows, dat_mode;
        end

        local probe_active = ((tonumber(accessxi.key_items_order_probe_until) or 0) >= tick());
        local dat_count = dat_rows ~= nil and dat_rows:len() or -1;
        if (probe_active == true) then
            log_state(('state key-items dat-order-mismatch category="%s" child=0x%08X nativeTotal=%d datRows=%d'):fmt(
                accessxi.escape_probe_log_text(category),
                child,
                native_total,
                dat_count));
        end
        dat_mode = tostring(dat_mode or 'unresolved-owned-identity');
        accessxi.key_items_native_order_cache[cache_key] = { rows = nil, mode = dat_mode };
        return nil, dat_mode;
    end

end

function accessxi.key_items_owned_rows_for_category(category)
    category = tostring(category or '');
    if (category == '') then
        return nil, 'category-missing';
    end
    accessxi.restore_key_items_packet_cache_if_needed();
    if (next(accessxi.key_items_packet_tables or {}) == nil) then
        return nil, 'no-packet-cache';
    end

    local cache_key = accessxi.key_items_packet_cache_key();
    local memo_key = ('%s:%s'):fmt(category, cache_key);
    accessxi.key_items_owned_cache = accessxi.key_items_owned_cache or {};
    if (accessxi.key_items_owned_cache[memo_key] ~= nil) then
        return accessxi.key_items_owned_cache[memo_key], 'packet-owned+dat-order+identity-complete';
    end

    local resource = accessxi.load_key_items_resource();
    local details = accessxi.load_key_items_dat_details();
    local order = accessxi.load_key_items_dat_order();
    local dynamic = accessxi.load_key_items_dynamic_rows();
    if (type(resource) ~= 'table' or type(details) ~= 'table'
        or type(order) ~= 'table' or type(dynamic) ~= 'table') then
        return nil, 'key-item-identity-source-missing';
    end

    local owned_ids = T{};
    for id = 0, 4095 do
        if (accessxi.key_items_packet_has_id(id)) then
            owned_ids:append(id);
        end
    end
    local category_overrides = T{
        [349] = 'Permanent Key Items',
        [3361] = 'Permanent Key Items',
    };
    local built_rows, unresolved = dynamic.build_owned_rows(
        owned_ids,
        resource,
        details,
        order,
        category_overrides,
        category);
    local _, safety_mode = dynamic.resolve_selected_row(built_rows, 0, unresolved);
    if (tostring(safety_mode or ''):eq('unresolved-owned-identity', true)) then
        local ids = T{};
        for _, row in ipairs(unresolved or {}) do
            ids:append(tostring(tonumber(row.id) or -1));
        end
        local unresolved_key = ('%s:%s'):fmt(cache_key, ids:concat(','));
        if (unresolved_key ~= tostring(accessxi.last_key_items_unresolved_identity_key or '')) then
            accessxi.last_key_items_unresolved_identity_key = unresolved_key;
            log_state(('state key-items unresolved-owned-identities ids="%s" safety="silence-without-row-shift"'):fmt(
                accessxi.escape_probe_log_text(ids:concat(','))));
        end
        return nil, 'unresolved-owned-identity';
    end

    local rows = T{};
    for _, row in ipairs(built_rows or {}) do
        local label = accessxi.key_items_resource_label({ en = tostring(row.label or '') });
        if (label == '') then
            return nil, 'key-item-label-missing';
        end
        rows:append({
            id = tonumber(row.id) or 0,
            label = label,
            order = tonumber(row.order),
        });
    end

    accessxi.key_items_owned_cache[memo_key] = rows;
    return rows, 'packet-owned+dat-order+identity-complete';
end -- key_items_owned_rows_for_category

function accessxi.key_items_native_total(child)
    child = tonumber(child) or 0;
    if (not accessxi.is_probe_pointer(child)) then
        return 0;
    end
    return tonumber(read_i32(child + 0x40)) or 0;
end

function accessxi.key_items_order_probe_hits(rows, ptr, name, max_offset)
    ptr = tonumber(ptr) or 0;
    name = tostring(name or 'ptr');
    max_offset = tonumber(max_offset) or 0;
    if (not accessxi.is_probe_pointer(ptr) or rows == nil) then
        return '';
    end

    local by_id = {};
    for _, row in ipairs(rows) do
        local id = tonumber(row ~= nil and row.id or -1) or -1;
        if (id >= 0) then
            by_id[id] = tostring(row.label or '');
        end
    end

    local hits = T{};
    for off = 0, max_offset, 2 do
        local value = read_u16(ptr + off) or -1;
        local label = by_id[value];
        if (label ~= nil and label ~= '') then
            hits:append(('%s+%03X=u16:%d:%s'):fmt(name, off, value, label));
            if (hits:len() >= 16) then
                break;
            end
        end
    end
    return hits:concat(' | ');
end

function accessxi.key_items_probe_pointer_text(ptr)
    ptr = tonumber(ptr) or 0;
    if (not accessxi.is_probe_pointer(ptr)) then
        return '';
    end

    local parts = T{};
    local strings = accessxi.status_menu_probe_inline_strings(ptr);
    if (strings ~= '') then
        parts:append(('strings{%s}'):fmt(strings));
    end
    local runs = accessxi.status_menu_probe_runs(ptr, 0x100);
    if (runs ~= '') then
        parts:append(('runs{%s}'):fmt(runs));
    end
    local ptrs = accessxi.status_menu_probe_pointer_fields(ptr);
    if (ptrs ~= '') then
        parts:append(('ptrs{%s}'):fmt(ptrs));
    end
    return parts:concat(' ');
end

function accessxi.key_items_order_probe_selected_row(menu_name, category, selected, count, raw, desc_base, child, entry)
    desc_base = tonumber(desc_base) or 0;
    child = tonumber(child) or 0;
    entry = tonumber(entry) or 0;
    selected = tonumber(selected) or 0;
    count = tonumber(count) or 0;
    raw = tonumber(raw) or 0;
    if (not accessxi.is_probe_pointer(desc_base) or selected <= 0 or selected > count) then
        return;
    end

    local top = accessxi.is_probe_pointer(child) and (tonumber(read_u32(child + 0x38)) or 0) or 0;
    local slot = selected - 1;
    local rec = desc_base + (slot * 0x14);
    local p0 = read_u32(rec + 0x00) or 0;
    local p1 = read_u32(rec + 0x04) or 0;
    log_state(('state key-items selected-row-probe menu="%s" category="%s" selected=%d count=%d raw=%d top=%d slot=%d slotRaw=%d rec=0x%08X p0=0x%08X p1=0x%08X entry=0x%08X recD="%s" p0D="%s" p1D="%s" entryD="%s" p0T="%s" p1T="%s" entryT="%s" entryPtrs="%s" p1B="%s"'):fmt(
        tostring(menu_name or ''),
        accessxi.escape_probe_log_text(tostring(category or '')),
        selected,
        count,
        raw,
        top,
        slot,
        top + slot,
        rec,
        p0,
        p1,
        entry,
        accessxi.escape_probe_log_text_wide(accessxi.format_probe_dwords(rec, 0x00, 5)),
        accessxi.escape_probe_log_text_wide(accessxi.format_probe_dwords(p0, 0x00, 16)),
        accessxi.escape_probe_log_text_wide(accessxi.format_probe_dwords(p1, 0x00, 20)),
        accessxi.escape_probe_log_text_wide(accessxi.format_probe_dwords(entry, 0x00, 32)),
        accessxi.escape_probe_log_text_wide(accessxi.key_items_probe_pointer_text(p0)),
        accessxi.escape_probe_log_text_wide(accessxi.key_items_probe_pointer_text(p1)),
        accessxi.escape_probe_log_text_wide(accessxi.key_items_probe_pointer_text(entry)),
        accessxi.escape_probe_log_text_wide(accessxi.status_menu_probe_pointer_fields(entry)),
        accessxi.escape_probe_log_text_wide(accessxi.format_probe_bytes(p1, 0x00, 0x80))));
end

function accessxi.log_key_items_order_probe(menu_name, category, selected, count, page, raw, child, entry, native_total, rows, guessed_row)
    if ((tonumber(accessxi.key_items_order_probe_until) or 0) < tick()) then
        return;
    end
    if ((tonumber(accessxi.key_items_order_probe_count) or 0) >= (tonumber(accessxi.key_items_order_probe_limit) or 0)) then
        return;
    end

    selected = tonumber(selected) or 0;
    count = tonumber(count) or 0;
    page = tonumber(page) or 0;
    raw = tonumber(raw) or 0;
    child = tonumber(child) or 0;
    entry = tonumber(entry) or 0;
    local desc = accessxi.is_probe_pointer(entry) and (read_u32(entry + 0x0C) or 0) or 0;
    local desc_base = 0;
    if (accessxi.is_probe_pointer(desc) and selected > 0) then
        desc_base = desc - ((selected - 1) * 0x14);
    end
    local obj = get_current_menu_object_ptr();
    local key = ('%s:%s:%d:%d:%d:%d:%08X:%08X:%08X'):fmt(
        tostring(menu_name or ''),
        tostring(category or ''),
        selected,
        count,
        page,
        raw,
        child,
        entry,
        desc);
    if (key == tostring(accessxi.last_key_items_order_probe_key or '')) then
        return;
    end
    accessxi.last_key_items_order_probe_key = key;
    accessxi.key_items_order_probe_count = (tonumber(accessxi.key_items_order_probe_count) or 0) + 1;

    local row_id = tonumber(guessed_row ~= nil and guessed_row.id or 0) or 0;
    local row_label = tostring(guessed_row ~= nil and guessed_row.label or '');
    local hits = T{};
    hits:append(accessxi.key_items_order_probe_hits(rows, obj, 'obj', 0x120));
    hits:append(accessxi.key_items_order_probe_hits(rows, child, 'child', 0x220));
    hits:append(accessxi.key_items_order_probe_hits(rows, entry, 'entry', 0x180));
    hits:append(accessxi.key_items_order_probe_hits(rows, desc, 'desc', 0x160));
    hits:append(accessxi.key_items_order_probe_hits(rows, desc_base, 'descBase', 0x180));

    accessxi.key_items_order_probe_selected_row(menu_name, category, selected, count, raw, desc_base, child, entry);

    log_state(('state key-items order-probe menu="%s" category="%s" selected=%d count=%d page=%d raw=%d child=0x%08X entry=0x%08X desc=0x%08X descBase=0x%08X nativeTotal=%d guessedId=%d guessedLabel="%s" hits="%s" child30="%s" entry00="%s" desc00="%s" descBase00="%s"'):fmt(
        tostring(menu_name or ''),
        accessxi.escape_probe_log_text(tostring(category or '')),
        selected,
        count,
        page,
        raw,
        child,
        entry,
        desc,
        desc_base,
        tonumber(native_total) or 0,
        row_id,
        accessxi.escape_probe_log_text(row_label),
        accessxi.escape_probe_log_text(hits:concat(' || ')),
        accessxi.escape_probe_log_text_wide(accessxi.format_probe_dwords(child, 0x30, 20)),
        accessxi.escape_probe_log_text_wide(accessxi.format_probe_dwords(entry, 0x00, 28)),
        accessxi.escape_probe_log_text_wide(accessxi.format_probe_dwords(desc, 0x00, 20)),
        accessxi.escape_probe_log_text_wide(accessxi.format_probe_dwords(desc_base, 0x00, 30))));
end

function accessxi.key_items_parent_category_speech(menu_name, selected, count, raw, child)
    menu_name = tostring(menu_name or '');
    if (not menu_name:eq('menu    evitem', true)) then
        return nil;
    end
    selected = tonumber(selected) or 0;
    count = tonumber(count) or 0;
    if (selected <= 0 or selected > count or not accessxi.is_probe_pointer(child)) then
        return nil;
    end
    if (not accessxi.key_items_context_active() or not accessxi.key_items_parent_native_shape(child, count)) then
        return nil;
    end

    local index = tonumber(raw);
    if (index == nil or index < 0) then
        return nil;
    end
    local category_rows = accessxi.key_items_parent_category_rows();
    local category_row = category_rows ~= nil and category_rows[index + 1] or nil;
    local label = category_row ~= nil and tostring(category_row.label or '') or '';
    if (label == '') then
        return nil;
    end
    accessxi.key_items_set_current_category(index, label);
    accessxi.key_items_current_item_id = 0;
    accessxi.key_items_current_item_label = '';
    accessxi.key_items_current_item_category = '';
    accessxi.key_items_current_item_index = -1;
    accessxi.key_items_current_item_entry = 0;
    accessxi.key_items_current_item_tick = 0;
    accessxi.key_items_inline_detail_candidate_until = 0;
    accessxi.key_items_inline_detail_candidate_id = 0;

    accessxi.last_native_menu_name = menu_name;
    accessxi.last_native_menu_label = label;
    accessxi.last_native_menu_selected = selected;
    accessxi.last_native_menu_tick = tick();
    accessxi.current_speech_key = ('native-known-key-items-parent:%s:%d:%d:%d:%s'):fmt(
        menu_name,
        selected,
        count,
        index,
        label);
    local key = accessxi.current_speech_key;
    if (key ~= tostring(accessxi.last_key_items_parent_label_key or '')) then
        accessxi.last_key_items_parent_label_key = key;
        log_state(('state nativemenu key-items-parent menu="%s" select=%d count=%d raw=%d child=0x%08X label="%s" source="windower-key-items-category+live-menu-order"'):fmt(
            menu_name,
            selected,
            count,
            index,
            tonumber(child) or 0,
            accessxi.escape_probe_log_text(label)));
    end
    return accessxi.menu_selection_speech(label);
end

function accessxi.key_items_sublist_speech(menu_name, title, selected, count, page, raw, child, entry)
    menu_name = tostring(menu_name or '');
    if (not menu_name:eq('menu    evitem', true)) then
        return nil;
    end
    selected = tonumber(selected) or 0;
    count = tonumber(count) or 0;
    local index = tonumber(raw);
    local absolute_detail_selected = (index ~= nil and count > 0 and selected > count and selected == (index + 1));
    if (selected <= 0 or (selected > count and not absolute_detail_selected) or not accessxi.key_items_sublist_context_active(count, child)) then
        return nil;
    end

    if (index == nil or index < 0) then
        accessxi.log_key_items_parent_probe(menu_name, title, selected, count, page, raw, child, entry, 'key-item-sublist-missing-native-raw');
        return nil;
    end

    local category = tostring(accessxi.key_items_current_category_label or '');
    local native_total = accessxi.key_items_native_total(child);
    local rows, row_mode = accessxi.key_items_native_id_rows_for_category(category, child, native_total);
    local probe_rows = rows;
    if (probe_rows == nil and ((tonumber(accessxi.key_items_order_probe_until) or 0) >= tick())) then
        probe_rows = accessxi.key_items_owned_rows_for_category(category);
    end
    accessxi.log_key_items_order_probe(menu_name, category, selected, count, page, index, child, entry, native_total, probe_rows, probe_rows ~= nil and probe_rows[index + 1] or nil);
    if (rows ~= nil and index < rows:len()) then
        local row = rows[index + 1];
        local label = row ~= nil and tostring(row.label or '') or '';
        local key_item_id = row ~= nil and (tonumber(row.id) or 0) or 0;
        if (label ~= '') then
            accessxi.key_items_context_until = tick() + 120000;
            local top_index = tonumber(read_i32((tonumber(child) or 0) + 0x38)) or 0;
            local expected_selected = index - top_index + 1;
            local now_tick = tick();
            local selection_detail = expected_selected >= 1 and expected_selected <= count and selected ~= expected_selected;
            local previous_item_id = tonumber(accessxi.key_items_current_item_id) or 0;
            local previous_item_index = tonumber(accessxi.key_items_current_item_index) or -1;
            local previous_item_entry = tonumber(accessxi.key_items_current_item_entry) or 0;
            local previous_item_age = now_tick - (tonumber(accessxi.key_items_current_item_tick) or 0);
            local entry_detail = (previous_item_id == key_item_id)
                and (previous_item_index == index)
                and previous_item_entry ~= 0
                and (tonumber(entry) or 0) ~= 0
                and previous_item_entry ~= (tonumber(entry) or 0)
                and previous_item_age >= 0
                and previous_item_age <= 8000;
            selection_detail = selection_detail and not absolute_detail_selected;
            if (selection_detail or entry_detail) then
                accessxi.key_items_current_item_id = key_item_id;
                accessxi.key_items_current_item_label = label;
                accessxi.key_items_current_item_category = category;
                accessxi.key_items_current_item_tick = now_tick;
                local detail = accessxi.key_items_current_item_detail();
                local description = detail ~= nil and tostring(detail.description or '') or '';
                if (description ~= '') then
                    accessxi.last_native_menu_name = menu_name;
                    accessxi.last_native_menu_label = label;
                    accessxi.last_native_menu_selected = selected;
                    accessxi.last_native_menu_tick = tick();
                    accessxi.current_speech_key = ('native-known-key-items-inline-detail:%s:%s:%d:%d:%d:%d:0x%08X:%s:%s'):fmt(
                        menu_name,
                        category,
                        selected,
                        count,
                        index,
                        key_item_id,
                        tonumber(entry) or 0,
                        label,
                        description);
                    local detail_key = accessxi.current_speech_key;
                    if (detail_key ~= tostring(accessxi.last_key_items_detail_key or '')) then
                        accessxi.last_key_items_detail_key = detail_key;
                        log_state(('state nativemenu key-item-inline-detail menu="%s" category="%s" select=%d expected=%d count=%d raw=%d top=%d child=0x%08X entry=0x%08X previousEntry=0x%08X keyItemId=%d label="%s" text="%s" source="ROM\\175\\35.DAT+evitem-detail-focus" detailSignal="%s"'):fmt(
                            menu_name,
                            accessxi.escape_probe_log_text(category),
                            selected,
                            expected_selected,
                            count,
                            index,
                            top_index,
                            tonumber(child) or 0,
                            tonumber(entry) or 0,
                            previous_item_entry,
                            key_item_id,
                            accessxi.escape_probe_log_text(label),
                            accessxi.escape_probe_log_text(description),
                            entry_detail and 'entry-change' or 'selected-offset'));
                    end
                    return accessxi.menu_selection_detail_speech(label, description);
                end
            end
            if (absolute_detail_selected) then
                return nil;
            end
            accessxi.last_native_menu_name = menu_name;
            accessxi.last_native_menu_label = label;
            accessxi.last_native_menu_selected = selected;
            accessxi.last_native_menu_tick = tick();
            accessxi.key_items_current_item_id = key_item_id;
            accessxi.key_items_current_item_label = label;
            accessxi.key_items_current_item_category = category;
            accessxi.key_items_current_item_index = index;
            accessxi.key_items_current_item_entry = tonumber(entry) or 0;
            accessxi.key_items_current_item_tick = tick();
            accessxi.key_items_inline_detail_candidate_until = tick() + 60000;
            accessxi.key_items_inline_detail_candidate_id = key_item_id;
            accessxi.last_key_items_detail_key = '';
            accessxi.last_key_items_candidate_detail_speech_key = '';
            accessxi.last_key_items_candidate_detail_state_key = '';
            accessxi.current_speech_key = ('native-known-key-items-entry:%s:%s:%d:%d:%d:%d:0x%08X:%s'):fmt(
                menu_name,
                category,
                selected,
                count,
                index,
                key_item_id,
                tonumber(entry) or 0,
                label);
            local key = accessxi.current_speech_key;
            if (key ~= tostring(accessxi.last_key_items_entry_label_key or '')) then
                accessxi.last_key_items_entry_label_key = key;
                log_state(('state nativemenu key-items-entry menu="%s" category="%s" select=%d count=%d page=%d raw=%d rowIndex=%d child=0x%08X entry=0x%08X keyItemId=%d label="%s" ownedCount=%d nativeTotal=%d source="%s"'):fmt(
                    menu_name,
                    accessxi.escape_probe_log_text(category),
                    selected,
                    count,
                    tonumber(page) or 0,
                    index,
                    index,
                    tonumber(child) or 0,
                    tonumber(entry) or 0,
                    key_item_id,
                    accessxi.escape_probe_log_text(label),
                    rows:len(),
                    native_total,
                    accessxi.escape_probe_log_text(row_mode or 'native-id-array')));
            end
            return accessxi.menu_selection_speech(label);
        end
    elseif (native_total > 0) then
        local row_count = rows ~= nil and rows:len() or 0;
        local missing_key = ('%s:%d:%d:%d:%s'):fmt(category, row_count, native_total, index, tostring(row_mode or ''));
        if (missing_key ~= tostring(accessxi.last_key_items_entry_label_key or '')) then
            accessxi.last_key_items_entry_label_key = missing_key;
            log_state(('state nativemenu key-items-entry-mismatch menu="%s" category="%s" select=%d count=%d raw=%d ownedCount=%d nativeTotal=%d source="%s"'):fmt(
                menu_name,
                accessxi.escape_probe_log_text(category),
                selected,
                count,
                index,
                row_count,
                native_total,
                accessxi.escape_probe_log_text(tostring(row_mode or accessxi.key_items_resource_path or ''))));
        end
        return nil;
    end
    accessxi.log_key_items_parent_probe(menu_name, title, selected, count, page, raw, child, entry, 'key-item-sublist-packet-count-guard-missing');
    return nil;
end

function accessxi.key_items_menu_native_label_speech(menu_name, title, selected, count, page, raw, child, entry)
    menu_name = tostring(menu_name or '');
    if (not menu_name:eq('menu    evitem', true)) then
        return nil;
    end
    selected = tonumber(selected) or 0;
    count = tonumber(count) or 0;
    local raw_index = tonumber(raw);
    local absolute_detail_selected = (raw_index ~= nil and count > 0 and selected > count and selected == (raw_index + 1));
    if (selected <= 0 or count <= 0 or (selected > count and not absolute_detail_selected) or not accessxi.is_probe_pointer(child)) then
        return nil;
    end

    local parent_speech = accessxi.key_items_parent_category_speech(menu_name, selected, count, raw, child);
    if (parent_speech ~= nil) then
        return parent_speech;
    end
    if (accessxi.key_items_parent_native_shape(child, count)) then
        return nil;
    end

    local sublist_speech = accessxi.key_items_sublist_speech(menu_name, title, selected, count, page, raw, child, entry);
    if (sublist_speech ~= nil) then
        return sublist_speech;
    end
    if (accessxi.key_items_sublist_context_active(count, child)) then
        return nil;
    end

    local label, mode = accessxi.native_query_label_for_selection(child, selected, count, 'plain');
    label = accessxi.plain_native_menu_label(label or '');
    if (label == '') then
        accessxi.log_key_items_parent_probe(menu_name, title, selected, count, page, raw, child, entry, mode or 'native-label-missing');
        return nil;
    end

    local field = accessxi.currency_packet_field_for_native_label(label, page);
    if (field ~= nil) then
        return nil;
    end

    accessxi.last_native_menu_name = menu_name;
    accessxi.last_native_menu_label = label;
    accessxi.last_native_menu_selected = selected;
    accessxi.last_native_menu_tick = tick();
    accessxi.current_speech_key = ('native-known-key-items:%s:%d:%d:%d:%s'):fmt(
        menu_name,
        selected,
        tonumber(page) or 0,
        tonumber(raw) or -1,
        label);
    log_state(('state nativemenu key-items-native menu="%s" select=%d count=%d page=%d raw=0x%08X child=0x%08X mode="%s" label="%s"'):fmt(
        menu_name,
        selected,
        count,
        tonumber(page) or 0,
        tonumber(raw) or 0,
        tonumber(child) or 0,
        tostring(mode or ''),
        accessxi.escape_probe_log_text(label)));
    return accessxi.menu_selection_speech(label);
end

function accessxi.key_items_detail_menu_speech(menu_name, title, obj, selected, count, page, raw, child, entry)
    menu_name = tostring(menu_name or '');
    if (not menu_name:eq('menu    evitem01', true)) then
        return nil;
    end

    local detail = accessxi.key_items_current_item_detail();
    if (detail == nil) then
        return nil;
    end

    obj = tonumber(obj) or 0;
    selected = tonumber(selected) or 0;
    local raw_index = tonumber(raw);
    local yes_no_index = (raw_index ~= nil and raw_index >= 0 and raw_index <= 1) and raw_index or -1;
    if (yes_no_index < 0 and selected >= 1 and selected <= 2) then
        yes_no_index = selected - 1;
    end
    if (yes_no_index < 0 or selected < 1 or selected > 2) then
        local probe_key = ('%s:%d:%d:%d:0x%08X:0x%08X'):fmt(
            menu_name,
            selected,
            yes_no_index,
            tonumber(count) or 0,
            tonumber(child) or 0,
            tonumber(entry) or 0);
        if (probe_key ~= tostring(accessxi.last_key_items_detail_key or '')) then
            accessxi.last_key_items_detail_key = probe_key;
            log_state(('state nativemenu key-item-evitem01-nonconfirm menu="%s" title="%s" select=%d yesNo=%d count=%d page=%d raw=0x%08X child=0x%08X entry=0x%08X label="%s" source="evitem01-shape"'):fmt(
                menu_name,
                tostring(title or ''),
                selected,
                yes_no_index,
                tonumber(count) or 0,
                tonumber(page) or 0,
                tonumber(raw) or 0,
                tonumber(child) or 0,
                tonumber(entry) or 0,
                accessxi.escape_probe_log_text(tostring(detail.label or ''))));
        end
        local label = tostring(detail.label or '');
        local description = tostring(detail.description or '');
        if (label ~= '' and description ~= '') then
            accessxi.last_native_menu_name = menu_name;
            accessxi.last_native_menu_label = label;
            accessxi.last_native_menu_selected = selected;
            accessxi.last_native_menu_tick = tick();
            accessxi.current_speech_key = ('native-known-key-item-evitem01-detail:%s:%d:%d:%d:0x%08X:%s:%s'):fmt(
                menu_name,
                tonumber(detail.id) or 0,
                selected,
                tonumber(count) or 0,
                tonumber(entry) or 0,
                label,
                description);
            return accessxi.menu_selection_detail_speech(label, description);
        end
        return nil;
    end
    local choice = '';
    if (yes_no_index == 0) then
        choice = 'Yes';
    elseif (yes_no_index == 1) then
        choice = 'No';
    end

    local label = tostring(detail.label or '');
    local prompt = label ~= '' and ('Examine %s?'):fmt(label) or 'Examine key item?';
    local text = prompt;
    if (choice ~= '') then
        text = ('%s %s'):fmt(prompt, choice);
    end

    accessxi.last_native_menu_name = menu_name;
    accessxi.last_native_menu_label = label ~= '' and label or prompt;
    accessxi.last_native_menu_selected = selected;
    accessxi.last_native_menu_tick = tick();
    accessxi.current_speech_key = ('native-known-key-item-confirm:%s:%d:%d:%d:%d:%s'):fmt(
        menu_name,
        tonumber(detail.id) or 0,
        yes_no_index,
        selected,
        tonumber(count) or 0,
        text);
    local key = accessxi.current_speech_key;
    if (key ~= tostring(accessxi.last_key_items_detail_key or '')) then
        accessxi.last_key_items_detail_key = key;
        log_state(('state nativemenu key-item-confirm menu="%s" title="%s" select=%d yesNo=%d count=%d page=%d raw=0x%08X child=0x%08X entry=0x%08X keyItemId=%d label="%s" text="%s" source="evitem01+current-key-item"'):fmt(
            menu_name,
            tostring(title or ''),
            selected,
            yes_no_index,
            tonumber(count) or 0,
            tonumber(page) or 0,
            tonumber(raw) or 0,
            tonumber(child) or 0,
            tonumber(entry) or 0,
            tonumber(detail.id) or 0,
            accessxi.escape_probe_log_text(label),
            accessxi.escape_probe_log_text(text)));
    end

    return accessxi.menu_selection_speech(text);
end

function accessxi.key_items_inline_detail_speech(menu_name, previous_menu_name)
    menu_name = tostring(menu_name or '');
    previous_menu_name = tostring(previous_menu_name or '');
    if (not menu_name:eq('menu    inline', true)) then
        return nil;
    end
    local transition_from = tostring(accessxi.last_menu_transition_from or previous_menu_name);
    local candidate_ok = (tonumber(accessxi.key_items_inline_detail_candidate_until) or 0) >= tick()
        and (tonumber(accessxi.key_items_inline_detail_candidate_id) or 0) == (tonumber(accessxi.key_items_current_item_id) or 0);
    local transition_ok = previous_menu_name:eq('menu    evitem', true)
        or previous_menu_name:eq('menu    evitem01', true)
        or transition_from:eq('menu    evitem', true)
        or transition_from:eq('menu    evitem01', true)
        or candidate_ok;
    if (not transition_ok) then
        local reject_key = ('transition:%s:%s:%d'):fmt(
            menu_name,
            transition_from,
            tonumber(accessxi.key_items_current_item_id) or 0);
        if (reject_key ~= tostring(accessxi.last_key_items_inline_detail_reject_key or '')) then
            accessxi.last_key_items_inline_detail_reject_key = reject_key;
            log_state(('state nativemenu key-item-inline-window-reject reason="transition" menu="%s" previous="%s" transitionFrom="%s" currentId=%d currentLabel="%s" currentAge=%d'):fmt(
                menu_name,
                accessxi.escape_probe_log_text(previous_menu_name),
                accessxi.escape_probe_log_text(transition_from),
                tonumber(accessxi.key_items_current_item_id) or 0,
                accessxi.escape_probe_log_text(tostring(accessxi.key_items_current_item_label or '')),
                tonumber(accessxi.key_items_current_item_age()) or -1));
        end
        return nil;
    end

    local detail = accessxi.key_items_current_item_detail();
    if (detail == nil) then
        local reject_key = ('detail:%s:%s:%d:%d'):fmt(
            menu_name,
            transition_from,
            tonumber(accessxi.key_items_current_item_id) or 0,
            tonumber(accessxi.key_items_current_item_age()) or -1);
        if (reject_key ~= tostring(accessxi.last_key_items_inline_detail_reject_key or '')) then
            accessxi.last_key_items_inline_detail_reject_key = reject_key;
            log_state(('state nativemenu key-item-inline-window-reject reason="detail" menu="%s" previous="%s" transitionFrom="%s" currentId=%d currentLabel="%s" currentAge=%d'):fmt(
                menu_name,
                accessxi.escape_probe_log_text(previous_menu_name),
                accessxi.escape_probe_log_text(transition_from),
                tonumber(accessxi.key_items_current_item_id) or 0,
                accessxi.escape_probe_log_text(tostring(accessxi.key_items_current_item_label or '')),
                tonumber(accessxi.key_items_current_item_age()) or -1));
        end
        return nil;
    end
    local label = tostring(detail.label or '');
    local description = tostring(detail.description or '');
    if (label == '' or description == '') then
        return nil;
    end

    local obj = get_current_menu_object_ptr();
    local selected, page, raw, child, count = accessxi.survival_guide_query_child_state_for_obj(obj);
    accessxi.last_native_menu_name = menu_name;
    accessxi.last_native_menu_label = label;
    accessxi.last_native_menu_selected = tonumber(selected) or 0;
    accessxi.last_native_menu_tick = tick();
    accessxi.current_speech_key = ('native-known-key-item-inline-detail:%s:%d:%d:%d:%d:0x%08X:%s:%s'):fmt(
        menu_name,
        tonumber(detail.id) or 0,
        tonumber(selected) or 0,
        tonumber(count) or 0,
        tonumber(raw) or 0,
        tonumber(obj) or 0,
        label,
        description);
    local key = accessxi.current_speech_key;
    if (key ~= tostring(accessxi.last_key_items_detail_key or '')) then
        accessxi.last_key_items_detail_key = key;
        log_state(('state nativemenu key-item-inline-window-detail menu="%s" transitionFrom="%s" selected=%d count=%d page=%d raw=0x%08X child=0x%08X obj=0x%08X keyItemId=%d label="%s" text="%s" source="ROM\\175\\35.DAT+menu-inline"'):fmt(
            menu_name,
            accessxi.escape_probe_log_text(transition_from),
            tonumber(selected) or 0,
            tonumber(count) or 0,
            tonumber(page) or 0,
            tonumber(raw) or 0,
            tonumber(child) or 0,
            tonumber(obj) or 0,
            tonumber(detail.id) or 0,
            accessxi.escape_probe_log_text(label),
            accessxi.escape_probe_log_text(description)));
    end
    return accessxi.menu_selection_detail_speech(label, description);
end

function accessxi.poll_key_items_inline_detail_speech(menu_name)
    menu_name = tostring(menu_name or get_menu_name() or '');
    if (not menu_name:eq('menu    inline', true)) then
        return false;
    end
    if ((tonumber(accessxi.key_items_inline_detail_candidate_until) or 0) < tick()) then
        return false;
    end

    accessxi.current_speech_key = '';
    local text = accessxi.key_items_inline_detail_speech(menu_name, tostring(accessxi.current_menu_name or ''));
    local key = tostring(accessxi.current_speech_key or '');
    if (text == nil or text == '' or key == '') then
        return false;
    end
    if (key == tostring(accessxi.last_key or '')) then
        return true;
    end

    accessxi.last = text;
    accessxi.last_key = key;
    local speak_result = speak(text, false);
    log_state(('state nativemenu key-item-inline-window-poll-speak result="%s" key="%s" text="%s"'):fmt(
        accessxi.escape_probe_log_text(speak_result or ''),
        accessxi.escape_probe_log_text(key),
        accessxi.escape_probe_log_text(text)));
    if (text ~= accessxi.last_log or key ~= accessxi.last_log_key) then
        accessxi.last_log = text;
        accessxi.last_log_key = key;
        log_line(text);
    end
    return true;
end

function accessxi.log_key_items_detail_surface_probe(reason)
    reason = tostring(reason or '');
    local menu_name = get_menu_name() or '';
    local obj = get_current_menu_object_ptr();
    local selected, page, raw, query_child, count = accessxi.survival_guide_query_child_state_for_obj(obj);
    selected = tonumber(selected) or 0;
    page = tonumber(page) or 0;
    raw = tonumber(raw) or 0;
    query_child = tonumber(query_child) or 0;
    count = tonumber(count) or 0;
    local entry = accessxi.is_probe_pointer(obj) and (read_u32(obj + 0x08) or 0) or 0;
    local obj_child = accessxi.is_probe_pointer(obj) and (read_u32(obj + 0x0C) or 0) or 0;
    local native24 = read_current_native_menu_index(0x24);
    local native28 = read_current_native_menu_index(0x28);
    local native4c = read_current_native_menu_index(0x4C);
    local detail = accessxi.key_items_current_item_detail();
    local current_id = tonumber(accessxi.key_items_current_item_id) or 0;
    local current_label = tostring(accessxi.key_items_current_item_label or '');
    local current_category = tostring(accessxi.key_items_current_item_category or accessxi.key_items_current_category_label or '');
    local current_index = tonumber(accessxi.key_items_current_item_index) or -1;
    local current_entry = tonumber(accessxi.key_items_current_item_entry) or 0;
    local current_age = accessxi.key_items_current_item_age();
    local detail_label = detail ~= nil and tostring(detail.label or '') or '';
    local detail_description = detail ~= nil and tostring(detail.description or '') or '';

    log_state(('state key-item-detail-probe reason="%s" menu="%s" obj=0x%08X selected=%d count=%d page=%d raw=0x%08X native24=%d native28=%d native4C=%d objChild=0x%08X queryChild=0x%08X entry=0x%08X currentId=%d currentLabel="%s" currentCategory="%s" currentIndex=%d currentEntry=0x%08X currentAge=%d detailLabel="%s" detailText="%s"'):fmt(
        accessxi.escape_probe_log_text(reason),
        accessxi.escape_probe_log_text(menu_name),
        tonumber(obj) or 0,
        selected,
        count,
        page,
        raw,
        tonumber(native24) or 0,
        tonumber(native28) or 0,
        tonumber(native4c) or 0,
        obj_child,
        query_child,
        entry,
        current_id,
        accessxi.escape_probe_log_text(current_label),
        accessxi.escape_probe_log_text(current_category),
        current_index,
        current_entry,
        tonumber(current_age) or -1,
        accessxi.escape_probe_log_text(detail_label),
        accessxi.escape_probe_log_text(detail_description)));

    log_state(('state key-item-detail-probe-memory reason="%s" obj=0x%08X obj00="%s" obj80="%s" objInline="%s" objPtrs="%s" child=0x%08X child00="%s" childInline="%s" entry=0x%08X entry00="%s" entryInline="%s" currentEntry=0x%08X currentEntry00="%s"'):fmt(
        accessxi.escape_probe_log_text(reason),
        tonumber(obj) or 0,
        accessxi.escape_probe_log_text_wide(accessxi.format_probe_dwords(obj, 0x00, 32)),
        accessxi.escape_probe_log_text_wide(accessxi.format_probe_dwords(obj, 0x80, 32)),
        accessxi.escape_probe_log_text(accessxi.status_menu_probe_inline_strings(obj)),
        accessxi.escape_probe_log_text(accessxi.status_menu_probe_pointer_fields(obj)),
        obj_child,
        accessxi.escape_probe_log_text_wide(accessxi.format_probe_dwords(obj_child, 0x00, 32)),
        accessxi.escape_probe_log_text(accessxi.status_menu_probe_inline_strings(obj_child)),
        entry,
        accessxi.escape_probe_log_text_wide(accessxi.format_probe_dwords(entry, 0x00, 32)),
        accessxi.escape_probe_log_text(accessxi.status_menu_probe_inline_strings(entry)),
        current_entry,
        accessxi.escape_probe_log_text_wide(accessxi.format_probe_dwords(current_entry, 0x00, 32))));
end

function accessxi.poll_key_items_candidate_detail_speech(menu_name)
    local now = tick();
    if ((tonumber(accessxi.key_items_inline_detail_candidate_until) or 0) < now) then
        return;
    end

    menu_name = tostring(menu_name or get_menu_name() or '');
    local obj = get_current_menu_object_ptr();
    local selected, page, raw, query_child, count = accessxi.survival_guide_query_child_state_for_obj(obj);
    local entry = accessxi.is_probe_pointer(obj) and (read_u32(obj + 0x08) or 0) or 0;
    local obj_child = accessxi.is_probe_pointer(obj) and (read_u32(obj + 0x0C) or 0) or 0;
    local key = ('%s:0x%08X:%d:%d:%d:%d:0x%08X:0x%08X:%d:%s'):fmt(
        menu_name,
        tonumber(obj) or 0,
        tonumber(selected) or 0,
        tonumber(count) or 0,
        tonumber(page) or 0,
        tonumber(raw) or 0,
        tonumber(obj_child) or 0,
        tonumber(entry) or 0,
        tonumber(accessxi.key_items_current_item_id) or 0,
        tostring(accessxi.key_items_current_item_label or ''));
    if (key == tostring(accessxi.last_key_items_candidate_detail_state_key or '')) then
        return;
    end
    accessxi.last_key_items_candidate_detail_state_key = key;

    local raw_index = tonumber(raw);
    local current_index = tonumber(accessxi.key_items_current_item_index) or -1;
    local current_entry = tonumber(accessxi.key_items_current_item_entry) or 0;
    local current_id = tonumber(accessxi.key_items_current_item_id) or 0;
    local detail_shape = menu_name:eq('menu    evitem', true)
        and raw_index ~= nil
        and raw_index >= 0
        and raw_index == current_index
        and (tonumber(selected) or 0) == (raw_index + 1)
        and current_entry ~= 0
        and (tonumber(entry) or 0) ~= 0
        and (tonumber(entry) or 0) ~= current_entry;
    if (not detail_shape) then
        return;
    end
    accessxi.key_items_inline_detail_candidate_until = now + 60000;

    local detail = accessxi.key_items_current_item_detail();
    local label = detail ~= nil and tostring(detail.label or '') or '';
    local description = detail ~= nil and tostring(detail.description or '') or '';
    if (label == '' or description == '') then
        return;
    end

    local speech_key = ('native-known-key-item-candidate-detail:%s:%d:%d:0x%08X:0x%08X:%s:%s'):fmt(
        menu_name,
        current_id,
        current_index,
        tonumber(current_entry) or 0,
        tonumber(entry) or 0,
        label,
        description);
    if (speech_key == tostring(accessxi.last_key_items_candidate_detail_speech_key or '')) then
        return;
    end
    accessxi.last_key_items_candidate_detail_speech_key = speech_key;
    accessxi.last_key_items_detail_key = speech_key;
    accessxi.current_speech_key = speech_key;
    local text = ('Key item. %s. %s'):fmt(
        accessxi.sentence_fragment(label),
        accessxi.sentence_fragment(description));
    accessxi.last = text;
    accessxi.last_key = speech_key;
    local speak_result = speak(text, false);
    log_state(('state nativemenu key-item-candidate-detail menu="%s" selected=%d raw=%d entry=0x%08X currentEntry=0x%08X keyItemId=%d label="%s" text="%s" result="%s" source="ROM\\175\\35.DAT+evitem-candidate-detail"'):fmt(
        menu_name,
        tonumber(selected) or 0,
        tonumber(raw_index) or -1,
        tonumber(entry) or 0,
        tonumber(current_entry) or 0,
        current_id,
        accessxi.escape_probe_log_text(label),
        accessxi.escape_probe_log_text(description),
        accessxi.escape_probe_log_text(speak_result or '')));
    if (text ~= accessxi.last_log or speech_key ~= accessxi.last_log_key) then
        accessxi.last_log = text;
        accessxi.last_log_key = speech_key;
        log_line(text);
    end
    return true;
end

function accessxi.log_status_menu_probe(menu_name, reason)
    menu_name = tostring(menu_name or '');
    if (menu_name:eq('menu    mount', true)) then
        return;
    end
    if (menu_name:eq('menu    ability', true) and accessxi.ability_current_category_label():eq('Job Traits', true)) then
        return;
    end

    if (not menu_name:eq('menu    statcom2', true)
        and not menu_name:eq('menu    mgcmenu', true)
        and not menu_name:eq('menu    magic', true)
        and not menu_name:eq('menu    abimenu', true)
        and not menu_name:eq('menu    ability', true)
        and not menu_name:eq('menu    ut_menu', true)
        and not menu_name:eq('menu    merit1', true)
        and not menu_name:contains('menu    merit', true)) then
        return;
    end

    local obj = get_current_menu_object_ptr();
    if (obj == 0) then
        return;
    end

    local selected = read_current_native_menu_index(0x4C);
    local key = ('%s:0x%08X:%d:%s'):fmt(menu_name, obj, selected, tostring(reason or ''));
    if (menu_name:eq('menu    magic', true)) then
        local now = tick();
        if (key == tostring(accessxi.last_magic_status_menu_probe_key or '')
            and ((now - (tonumber(accessxi.last_magic_status_menu_probe_tick) or 0)) < 5000)) then
            return;
        end
        accessxi.last_magic_status_menu_probe_key = key;
        accessxi.last_magic_status_menu_probe_tick = now;
    end
    if (key == (accessxi.last_status_menu_probe_key or '')) then
        return;
    end
    accessxi.last_status_menu_probe_key = key;

    local child = read_u32(obj + 0x0C) or 0;
    local entry = read_u32(obj + 0x08) or 0;
    local selected_child, page, raw, query_child, query_count = accessxi.survival_guide_query_child_state_for_obj(obj);
    if (selected <= 0) then
        selected = tonumber(selected_child) or 0;
    end
    log_line(('statusprobe menu="%s" reason="%s" obj=0x%08X selected=%d querySelected=%d page=%d count=%d raw=0x%08X child=0x%08X entry=0x%08X'):fmt(
        menu_name,
        tostring(reason or ''),
        obj,
        selected,
        tonumber(selected_child) or 0,
        tonumber(page) or 0,
        tonumber(query_count) or 0,
        tonumber(raw) or 0,
        tonumber(query_child) or 0,
        entry));

    local small = T{};
    for off = 0, 0x160, 4 do
        local value = read_i32(obj + off);
        if (value ~= nil and value >= -4096 and value <= 4096) then
            small:append(('+%03X=%d'):fmt(off, value));
        end
    end
    log_line(('statusprobe small menu="%s" obj=0x%08X %s'):fmt(menu_name, obj, small:concat(' ')));

    log_line(('statusprobe obj menu="%s" obj=0x%08X dwords="%s" inline="%s" ptrs="%s"'):fmt(
        menu_name,
        obj,
        accessxi.escape_probe_log_text(accessxi.format_probe_dwords(obj, 0, 48)),
        accessxi.escape_probe_log_text(accessxi.status_menu_probe_inline_strings(obj)),
        accessxi.escape_probe_log_text(accessxi.status_menu_probe_pointer_fields(obj))));

    if (accessxi.is_probe_pointer(entry)) then
        local desc = read_u32(entry + 0x0C) or 0;
        log_line(('statusentry menu="%s" selected=%d entry=0x%08X dwords="%s" inline="%s" runs="%s" before="%s" after="%s" ptrs="%s"'):fmt(
            menu_name,
            selected,
            entry,
            accessxi.escape_probe_log_text(accessxi.format_probe_dwords(entry, 0, 64)),
            accessxi.escape_probe_log_text(accessxi.status_menu_probe_inline_strings(entry)),
            accessxi.escape_probe_log_text(accessxi.status_menu_probe_runs(entry, 0x220)),
            accessxi.escape_probe_log_text(accessxi.status_menu_probe_runs(entry - 0x180, 0x180)),
            accessxi.escape_probe_log_text(accessxi.status_menu_probe_runs(entry + 0x180, 0x180)),
            accessxi.escape_probe_log_text(accessxi.status_menu_probe_pointer_fields(entry))));
        if (accessxi.is_probe_pointer(desc)) then
            local row0 = read_u32(desc + 0x00) or 0;
            local row1 = read_u32(desc + 0x04) or 0;
            local row2 = read_u32(desc + 0x08) or 0;
            log_line(('statusdesc menu="%s" selected=%d entry=0x%08X desc=0x%08X dwords="%s" inline="%s" runs="%s" desc46="%s" table="%s" ptrs="%s"'):fmt(
                menu_name,
                selected,
                entry,
                desc,
                accessxi.escape_probe_log_text(accessxi.format_probe_dwords(desc, 0, 48)),
                accessxi.escape_probe_log_text(accessxi.status_menu_probe_inline_strings(desc)),
                accessxi.escape_probe_log_text(accessxi.status_menu_probe_runs(desc - 0x80, 0x200)),
                accessxi.escape_probe_log_text(read_probe_string(desc + 0x46)),
                accessxi.escape_probe_log_text(accessxi.status_menu_probe_desc_table(desc, selected)),
                accessxi.escape_probe_log_text(accessxi.status_menu_probe_pointer_fields(desc))));
            accessxi.status_menu_probe_resource_record(menu_name, selected, 'row0', row0);
            accessxi.status_menu_probe_resource_record(menu_name, selected, 'row1', row1);
            accessxi.status_menu_probe_resource_record(menu_name, selected, 'row2', row2);
        end
    end

    if (accessxi.is_probe_pointer(child)) then
        log_line(('statuschild menu="%s" selected=%d child=0x%08X dwords="%s" inline="%s" runs="%s" ptrs="%s"'):fmt(
            menu_name,
            selected,
            child,
            accessxi.escape_probe_log_text(accessxi.format_probe_dwords(child, 0, 48)),
            accessxi.escape_probe_log_text(accessxi.status_menu_probe_inline_strings(child)),
            accessxi.escape_probe_log_text(accessxi.status_menu_probe_runs(child, 0x180)),
            accessxi.escape_probe_log_text(accessxi.status_menu_probe_pointer_fields(child))));
    end
end

function accessxi.quests_menu_main_descriptor_table_probe(desc, selected, count)
    desc = tonumber(desc) or 0;
    selected = tonumber(selected) or 0;
    count = tonumber(count) or 0;
    if (not accessxi.is_probe_pointer(desc) or selected <= 0 or count <= 0 or count > 32) then
        return '';
    end

    local base = desc - ((selected - 1) * 0x14);
    if (not accessxi.is_probe_pointer(base)) then
        return '';
    end

    local parts = T{};
    local limit = math.min(count, 12);
    for index = 1, limit do
        local rec = base + ((index - 1) * 0x14);
        if (accessxi.is_probe_pointer(rec)) then
            parts:append(('%02d@0x%08X dwords="%s" inline="%s" runs="%s" ptrs="%s"'):fmt(
                index,
                rec,
                accessxi.escape_probe_log_text_wide(accessxi.format_probe_dwords(rec, 0x00, 5)),
                accessxi.escape_probe_log_text(accessxi.status_menu_probe_inline_strings(rec)),
                accessxi.escape_probe_log_text(accessxi.status_menu_probe_runs(rec, 0x80)),
                accessxi.escape_probe_log_text(accessxi.status_menu_probe_pointer_fields(rec))));
        end
    end
    return parts:concat(' || ');
end

accessxi.quests_menu_data = accessxi.load_menu_module_table('quests', T{
    main_resource_path = '',
    main_categories = T{},
});
accessxi.records_of_eminence_data = accessxi.load_menu_module_table('records_of_eminence', T{
    records = T{},
});

function accessxi.quests_menu_load_resource(path)
    path = tostring(path or accessxi.quests_menu_data.main_resource_path or '');
    if (path == '') then
        return nil, 'missing-path';
    end
    if (accessxi.quests_menu_resource_loaded == true and tostring(accessxi.quests_menu_resource_path or '') == path) then
        return accessxi.quests_menu_resource_blob, accessxi.quests_menu_resource_blob ~= nil and 'cached' or 'missing';
    end

    accessxi.quests_menu_resource_loaded = true;
    accessxi.quests_menu_resource_path = path;
    accessxi.quests_menu_resource_blob = nil;

    local file = io.open(path, 'rb');
    if (file == nil) then
        return nil, 'open-failed';
    end
    local data = file:read('*a');
    file:close();
    if (data == nil or data == '') then
        return nil, 'empty';
    end

    accessxi.quests_menu_resource_blob = data;
    return data, 'loaded';
end

function accessxi.quests_menu_resource_row(selected, count)
    selected = tonumber(selected) or 0;
    count = tonumber(count) or 0;
    local rows = accessxi.quests_menu_data.main_categories or T{};
    local row_count = rows.len ~= nil and rows:len() or #rows;
    if (selected <= 0 or count <= 0 or selected > count or count ~= row_count) then
        return nil, 'count-mismatch';
    end

    local row = rows[selected];
    if (row == nil) then
        return nil, 'missing-row';
    end

    local label = tostring(row.label or '');
    if (label == '') then
        return nil, 'bad-row';
    end

    local source = tostring(row.evidence or '');
    local offset = tonumber(row.offset) or -1;
    if (offset >= 0) then
        local path = tostring(row.path or accessxi.quests_menu_data.main_resource_path or '');
        local blob, reason = accessxi.quests_menu_load_resource(path);
        if (blob == nil) then
            return nil, tostring(reason or 'resource-missing');
        end

        local start_pos = offset + 1;
        local resource_label = blob:sub(start_pos, start_pos + #label - 1);
        if (resource_label ~= label) then
            return nil, 'resource-mismatch';
        end
        source = ('%s@0x%04X'):fmt(path:gsub('^.*FINAL FANTASY XI\\', ''), offset);
    end

    local prefix = tostring(row.prefix or '');
    local prefix_offset = tonumber(row.prefix_offset) or -1;
    if (prefix ~= '' and prefix_offset >= 0) then
        local prefix_path = tostring(row.prefix_path or '');
        local prefix_blob, prefix_reason = accessxi.quests_menu_load_resource(prefix_path);
        if (prefix_blob == nil) then
            return nil, tostring(prefix_reason or 'prefix-resource-missing');
        end
        local prefix_pos = prefix_offset + 1;
        local resource_prefix = prefix_blob:sub(prefix_pos, prefix_pos + #prefix - 1);
        if (resource_prefix ~= prefix) then
            return nil, 'prefix-resource-mismatch';
        end
        source = source .. (' prefix=%s@0x%04X'):fmt(prefix_path:gsub('^.*FINAL FANTASY XI\\', ''), prefix_offset);
    end

    if (source == '') then
        return nil, 'missing-evidence';
    end

    row.source = source;
    return row, 'resource';
end

function accessxi.quests_menu_main_resource_speech(menu_name, title, selected, count, page, raw, child, entry)
    if (not tostring(menu_name or ''):eq('menu    quest00', true)) then
        return nil;
    end

    local row, reason = accessxi.quests_menu_resource_row(selected, count);
    if (row == nil) then
        local missing_key = ('%s:%d:%d:%s'):fmt(tostring(menu_name or ''), tonumber(selected) or 0, tonumber(count) or 0, tostring(reason or ''));
        if (missing_key ~= tostring(accessxi.quests_menu_last_resource_key or '')) then
            accessxi.quests_menu_last_resource_key = missing_key;
            log_state(('state quests main-resource-missing menu="%s" title="%s" select=%d count=%d reason="%s"'):fmt(
                tostring(menu_name or ''),
                accessxi.escape_probe_log_text(tostring(title or '')),
                tonumber(selected) or 0,
                tonumber(count) or 0,
                accessxi.escape_probe_log_text(tostring(reason or ''))));
        end
        return nil;
    end

    local label = tostring(row.label or '');
    if (tostring(row.prefix or '') ~= '') then
        label = ('%s. %s'):fmt(tostring(row.prefix or ''), label);
    end
    if (selected == 1) then
        accessxi.quests_menu_mode = 'current';
        accessxi.quests_menu_mode_tick = tick();
        accessxi.quests_menu_context = 'quest-log';
        accessxi.quests_menu_context_tick = tick();
    elseif (selected == 2) then
        accessxi.quests_menu_mode = 'completed';
        accessxi.quests_menu_mode_tick = tick();
        accessxi.quests_menu_context = 'quest-log';
        accessxi.quests_menu_context_tick = tick();
    elseif (tostring(row.prefix or ''):eq('Records of Eminence', true) and label:eq('Records of Eminence. Current', true)) then
        accessxi.quests_menu_mode = 'current';
        accessxi.quests_menu_mode_tick = tick();
        accessxi.quests_menu_context = 'records-of-eminence';
        accessxi.quests_menu_context_tick = tick();
    elseif (tostring(row.context or '') ~= '') then
        accessxi.quests_menu_mode = '';
        accessxi.quests_menu_mode_tick = 0;
        accessxi.quests_menu_context = tostring(row.context or '');
        accessxi.quests_menu_context_tick = tick();
    else
        accessxi.quests_menu_mode = '';
        accessxi.quests_menu_mode_tick = 0;
        accessxi.quests_menu_context = tostring(row.prefix or ''):eq('Records of Eminence', true) and 'records-of-eminence' or 'other';
        accessxi.quests_menu_context_tick = tick();
    end
    local source = tostring(row.source or '');
    accessxi.last_native_menu_name = tostring(menu_name or '');
    accessxi.last_native_menu_label = label;
    accessxi.last_native_menu_selected = tonumber(selected) or 0;
    accessxi.last_native_menu_tick = tick();
    accessxi.current_speech_key = ('native-known-quest-main-resource:%s:%d:%d:%d:%s'):fmt(
        tostring(menu_name or ''),
        tonumber(selected) or 0,
        tonumber(page) or 0,
        tonumber(count) or 0,
        label);
    log_state(('state quests main-resource menu="%s" title="%s" select=%d page=%d count=%d raw=0x%08X child=0x%08X entry=0x%08X label="%s" source="%s"'):fmt(
        tostring(menu_name or ''),
        accessxi.escape_probe_log_text(tostring(title or '')),
        tonumber(selected) or 0,
        tonumber(page) or 0,
        tonumber(count) or 0,
        tonumber(raw) or 0,
        tonumber(child) or 0,
        tonumber(entry) or 0,
        accessxi.escape_probe_log_text(label),
        accessxi.escape_probe_log_text(source)));
    return ('%s. %s'):fmt(tostring(title or ''), accessxi.sentence_fragment(label));
end

function accessxi.quest_rom_rows_for_area(area_key)
    area_key = tostring(area_key or '');
    if (area_key == '') then
        return nil, 'missing-area';
    end

    local cache = accessxi.quests_menu_quest_rom_cache;
    if (type(cache) ~= 'table') then
        cache = {};
        accessxi.quests_menu_quest_rom_cache = cache;
    end
    if (cache[area_key] ~= nil) then
        return cache[area_key].rows, tostring(cache[area_key].reason or 'cached');
    end

    local resources = accessxi.quests_menu_data.quest_log_resources or T{};
    local resource = resources[area_key];
    if (resource == nil) then
        cache[area_key] = { rows = nil, reason = 'missing-resource' };
        return nil, 'missing-resource';
    end

    local path = tostring(resource.path or '');
    local file = io.open(path, 'rb');
    if (file == nil) then
        cache[area_key] = { rows = nil, reason = 'open-failed' };
        return nil, 'open-failed';
    end
    local data = file:read('*a') or '';
    file:close();
    if (data == '') then
        cache[area_key] = { rows = nil, reason = 'empty' };
        return nil, 'empty';
    end

    local rows = T{};
    local len = #data;
    local slots = accessxi.quests_menu_data.quest_rom_title_slot_offsets or T{};
    for _, slot in ipairs(slots) do
        local title_offset = tonumber(slot.title_offset) or -1;
        local id_offset = tonumber(slot.id_offset) or -1;
        local stride = tonumber(slot.stride) or 0;
        if (title_offset >= 0 and id_offset >= 0 and stride > 0) then
            local index = 0;
            while ((title_offset + (index * stride)) < len) do
                local current_title_offset = title_offset + (index * stride);
                local current_id_offset = id_offset + (index * stride);
                local label = accessxi.cop_rom_decoded_text(data, current_title_offset, math.min(96, len - current_title_offset));
                local quest_id = 255 - (string.byte(data, current_id_offset + 1) or 255);
                local lower = label:lower();
                if (quest_id >= 0 and quest_id <= 0xFFFF
                    and #label >= 3
                    and label:sub(1, 1) ~= ' '
                    and not lower:find('^client:')
                    and not lower:find('^clients:')
                    and not lower:find('^summary:')
                    and not lower:find('^g%d+$')) then
                    label = label:gsub('^%+', '');
                    local row = {
                        id = quest_id,
                        slot = index,
                        stride = stride,
                        title_offset = title_offset,
                        label = label,
                        area = tostring(resource.label or area_key),
                        area_key = area_key,
                        offset = current_title_offset,
                        path = path,
                        source = ('%s@0x%04X id=%d slot=%d'):fmt(accessxi.mission_rom_relpath(path), current_title_offset, quest_id, index),
                    };
                    rows[quest_id] = row;
                    if (rows.by_slot == nil) then
                        rows.by_slot = T{};
                    end
                    rows.by_slot[index] = row;
                end
                index = index + 1;
            end
        end
    end

    cache[area_key] = { rows = rows, reason = 'loaded' };
    return rows, 'loaded';
end

function accessxi.quest_rom_detail_parts_for_row(row)
    if (type(row) ~= 'table') then
        return nil, 'missing-row';
    end

    if (type(row.detail_parts) == 'table' and #row.detail_parts > 0) then
        return row.detail_parts, 'quest-rom-detail-parts-cache';
    end

    local path = tostring(row.path or '');
    local label = tostring(row.label or '');
    local slot = tonumber(row.slot) or -1;
    local stride = tonumber(row.stride) or 0;
    local title_offset = tonumber(row.title_offset) or -1;
    if (path == '' or label == '' or slot < 0 or stride <= 0 or title_offset < 0) then
        return nil, 'missing-row-fields';
    end

    local file = io.open(path, 'rb');
    if (file == nil) then
        return nil, 'open-failed';
    end
    local data = file:read('*a') or '';
    file:close();
    if (data == '') then
        return nil, 'empty';
    end

    local record_base = slot * stride;
    local start_offset = record_base + title_offset;
    local max_len = stride - title_offset;
    local runs = accessxi.cop_rom_decoded_text_runs(data, start_offset, max_len);
    if (type(runs) ~= 'table' or runs:len() <= 0) then
        return nil, 'missing-runs';
    end

    local parts = T{};
    for _, run in ipairs(runs) do
        local text = tostring(run.text or ''):trim();
        if (text ~= '' and not text:eq(label, true)) then
            parts:append(text);
        end
    end
    if (parts:len() <= 0) then
        return nil, 'missing-detail-text';
    end

    row.detail_parts = parts;
    return parts, 'quest-rom-detail-parts';
end

function accessxi.quest_rom_detail_for_row(row)
    local parts, reason = accessxi.quest_rom_detail_parts_for_row(row);
    if (type(parts) ~= 'table' or #parts <= 0) then
        return nil, tostring(reason or 'missing-detail-text');
    end
    return parts:concat('. '), 'quest-rom-detail', parts;
end

function accessxi.quests_menu_resource_candidates(quest_id)
    quest_id = tonumber(quest_id);
    if (quest_id == nil or quest_id < 0) then
        return T{};
    end

    local candidates = T{};
    for area_key, _ in pairs(accessxi.quests_menu_data.quest_log_resources or {}) do
        local rows = accessxi.quest_rom_rows_for_area(area_key);
        local row = rows ~= nil and rows[quest_id] or nil;
        if (row ~= nil and tostring(row.label or '') ~= '') then
            candidates:append(row);
        end
    end
    return candidates;
end

function accessxi.quests_menu_category_area(child)
    child = tonumber(child) or 0;
    if (not accessxi.is_probe_pointer(child)) then
        return '', -1;
    end

    local index = tonumber(read_u32(child + 0x6C)) or -1;
    local order = accessxi.quests_menu_data.quest_log_order or T{};
    local area_key = tostring(order[index + 1] or '');
    return area_key, index;
end

function accessxi.quest_packet_entry(area_key, mode)
    accessxi.restore_quest_packet_cache_if_needed();
    area_key = tostring(area_key or '');
    mode = tostring(mode or '');
    if (area_key == '' or mode == '') then
        return nil, 'missing-context';
    end

    local logs = accessxi.quest_packet_logs or {};
    local entry = logs[accessxi.quest_packet_entry_key(area_key, mode)];
    if (entry == nil) then
        return nil, 'missing-packet';
    end
    return entry, 'packet';
end

function accessxi.quest_packet_has_id(entry, quest_id)
    if (type(entry) ~= 'table' or type(entry.words) ~= 'table') then
        return false;
    end
    quest_id = tonumber(quest_id) or -1;
    if (quest_id < 0 or quest_id > 255) then
        return false;
    end

    local word_index = math.floor(quest_id / 32) + 1;
    local bit_index = quest_id % 32;
    local word = tonumber(entry.words[word_index]) or 0;
    return bit.band(word, bit.lshift(1, bit_index)) ~= 0;
end

function accessxi.quests_menu_effective_mode()
    local mode = tostring(accessxi.quests_menu_mode or '');
    local context = tostring(accessxi.quests_menu_context or '');
    local age = (tonumber(accessxi.quests_menu_mode_tick) or 0) > 0 and (tick() - (tonumber(accessxi.quests_menu_mode_tick) or 0)) or 999999;
    local context_age = (tonumber(accessxi.quests_menu_context_tick) or 0) > 0 and (tick() - (tonumber(accessxi.quests_menu_context_tick) or 0)) or 999999;
    if (context == 'quest-log' and context_age < 300000 and (mode == 'current' or mode == 'completed') and age < 300000) then
        return mode, 'main-menu';
    end
    if (context ~= '' and context ~= 'quest-log' and context_age < 300000) then
        return '', context;
    end
    return '', 'missing-mode';
end

function accessxi.quests_menu_runtime_resource_row(menu_name, title, selected, count, page, raw, child, entry)
    if (not tostring(menu_name or ''):eq('menu    quest01', true)) then
        return nil;
    end

    selected = tonumber(selected) or 0;
    raw = tonumber(raw) or 0;
    child = tonumber(child) or 0;
    entry = tonumber(entry) or 0;
    if (selected <= 0 or not accessxi.is_probe_pointer(child)) then
        return nil;
    end

    local visible_count = tonumber(read_u32(child + 0x40)) or 0;
    if (visible_count > 0 and selected > visible_count) then
        return nil;
    end

    local mode, mode_source = accessxi.quests_menu_effective_mode();
    if (mode == '') then
        if (mode_source == 'records-of-eminence'
            or mode_source == 'records-of-eminence-objective-list'
            or mode_source == 'records-of-eminence-objective-category'
            or mode_source == 'records-of-eminence-objective-catalog'
            or mode_source == 'other') then
            return nil;
        end
        local missing_key = ('%s:mode:%d:%d:%s'):fmt(
            tostring(menu_name or ''),
            selected,
            visible_count,
            tostring(mode_source or ''));
        if (missing_key ~= tostring(accessxi.last_quests_menu_runtime_row_key or '')) then
            accessxi.last_quests_menu_runtime_row_key = missing_key;
            log_state(('state quests runtime-row-missing menu="%s" title="%s" select=%d visible=%d raw=%d modeSource="%s" reason="missing-mode"'):fmt(
                tostring(menu_name or ''),
                accessxi.escape_probe_log_text(tostring(title or '')),
                selected,
                visible_count,
                raw,
                accessxi.escape_probe_log_text(tostring(mode_source or ''))));
        end
        return nil;
    end

    local area_key, category_index = accessxi.quests_menu_category_area(child);
    local slot_id, slot_flags, slot_block, raw_lo, slot_reason = accessxi.quests_menu_runtime_slot(child, raw);
    local rows, rows_reason = accessxi.quest_rom_rows_for_area(area_key);
    local row = rows ~= nil and rows.by_slot ~= nil and rows.by_slot[tonumber(slot_id) or -1] or nil;
    if (slot_id == nil or rows == nil or row == nil) then
        local missing_key = ('%s:%s:%s:%d:%d:%s:%s'):fmt(
            tostring(menu_name or ''),
            tostring(area_key or ''),
            tostring(mode or ''),
            selected,
            visible_count,
            tostring(slot_reason or rows_reason or 'missing-slot-row'),
            tostring(mode_source or ''));
        if (missing_key ~= tostring(accessxi.last_quests_menu_runtime_row_key or '')) then
            accessxi.last_quests_menu_runtime_row_key = missing_key;
            log_state(('state quests runtime-row-missing menu="%s" title="%s" select=%d visible=%d raw=%d category=%d area="%s" mode="%s" modeSource="%s" slotId=%d slotFlags=0x%08X slotBlock=0x%08X reason="%s" packetAge=%d'):fmt(
                tostring(menu_name or ''),
                accessxi.escape_probe_log_text(tostring(title or '')),
                selected,
                visible_count,
                tonumber(raw_lo) or -1,
                tonumber(category_index) or -1,
                accessxi.escape_probe_log_text(tostring(area_key or '')),
                accessxi.escape_probe_log_text(tostring(mode or '')),
                accessxi.escape_probe_log_text(tostring(mode_source or '')),
                tonumber(slot_id) or -1,
                tonumber(slot_flags) or 0,
                tonumber(slot_block) or 0,
                accessxi.escape_probe_log_text(tostring(slot_reason or rows_reason or 'missing-slot-row')),
                (tonumber(accessxi.quest_packet_tick) or 0) > 0 and math.floor(tick() - (tonumber(accessxi.quest_packet_tick) or 0)) or -1));
        end
        return nil;
    end

    local quest_id = tonumber(row ~= nil and row.id or -1) or -1;
    if (tostring(row.label or '') == '') then
        local missing_key = ('%s:%s:%s:%d:%d:missing-rom:%d'):fmt(
            tostring(menu_name or ''),
            tostring(area_key or ''),
            tostring(mode or ''),
            selected,
            visible_count,
            quest_id);
        if (missing_key ~= tostring(accessxi.last_quests_menu_runtime_row_key or '')) then
            accessxi.last_quests_menu_runtime_row_key = missing_key;
            log_state(('state quests runtime-row-missing menu="%s" title="%s" select=%d visible=%d raw=%d category=%d area="%s" mode="%s" questId=%d reason="missing-rom"'):fmt(
                tostring(menu_name or ''),
                accessxi.escape_probe_log_text(tostring(title or '')),
                selected,
                visible_count,
                tonumber(raw_lo) or -1,
                tonumber(category_index) or -1,
                accessxi.escape_probe_log_text(tostring(area_key or '')),
                accessxi.escape_probe_log_text(tostring(mode or '')),
                quest_id));
        end
        return nil;
    end

    local resource = (accessxi.quests_menu_data.quest_log_resources or T{})[area_key] or {};
    local area_label = tostring(resource.label or row.area or area_key);
    local status = mode == 'completed' and 'Completed' or 'Current';
    local label = tostring(row.label or '');
    local packet_entry = accessxi.quest_packet_entry(area_key, mode);
    local packet_has_id = packet_entry ~= nil and accessxi.quest_packet_has_id(packet_entry, quest_id);
    accessxi.last_native_menu_name = tostring(menu_name or '');
    accessxi.last_native_menu_label = label;
    accessxi.last_native_menu_selected = selected;
    accessxi.last_native_menu_tick = tick();
    accessxi.last_quests_menu_detail_row = row;
    accessxi.last_quests_menu_detail_row.area_label = area_label;
    accessxi.last_quests_menu_detail_row.status = status;
    accessxi.last_quests_menu_detail_row.selected = selected;
    accessxi.last_quests_menu_detail_row.visible_count = visible_count;
    accessxi.last_quests_menu_detail_tick = tick();
    accessxi.current_speech_key = ('native-known-quest-runtime:%s:%s:%s:%d:%d:%d:%s'):fmt(
        tostring(menu_name or ''),
        tostring(area_key or ''),
        tostring(mode or ''),
        selected,
        visible_count,
        quest_id,
        label);
    log_state(('state quests runtime-row menu="%s" title="%s" select=%d visible=%d count=%d raw=%d page=%d category=%d area="%s" areaLabel="%s" mode="%s" status="%s" slotId=%d slotFlags=0x%08X slotBlock=0x%08X questId=%d packetHasId=%s label="%s" source="%s" packetAge=%d'):fmt(
        tostring(menu_name or ''),
        accessxi.escape_probe_log_text(tostring(title or '')),
        selected,
        visible_count,
        tonumber(count) or 0,
        tonumber(raw_lo) or -1,
        tonumber(page) or 0,
        tonumber(category_index) or -1,
        accessxi.escape_probe_log_text(tostring(area_key or '')),
        accessxi.escape_probe_log_text(area_label),
        accessxi.escape_probe_log_text(mode),
        status,
        tonumber(slot_id) or -1,
        tonumber(slot_flags) or 0,
        tonumber(slot_block) or 0,
        quest_id,
        packet_has_id and 'true' or 'false',
        accessxi.escape_probe_log_text(label),
        accessxi.escape_probe_log_text(tostring(row.source or '')),
        (tonumber(accessxi.quest_packet_tick) or 0) > 0 and math.floor(tick() - (tonumber(accessxi.quest_packet_tick) or 0)) or -1));
    return ('%s. %s. %s'):fmt(area_label, status, accessxi.sentence_fragment(label));
end

function accessxi.records_of_eminence_descriptor_probe(entry, selected, visible_count)
    entry = tonumber(entry) or 0;
    selected = tonumber(selected) or 0;
    visible_count = tonumber(visible_count) or 0;
    if (not accessxi.is_probe_pointer(entry)) then
        return '';
    end

    local desc = read_u32(entry + 0x0C) or 0;
    if (not accessxi.is_probe_pointer(desc)) then
        return '';
    end

    local parts = T{};
    parts:append(('entryDesc=0x%08X selected=%d visible=%d dwords="%s" recordProbe="%s"'):fmt(
        desc,
        selected,
        visible_count,
        accessxi.escape_probe_log_text(accessxi.format_probe_dwords(desc, 0x00, 6)),
        accessxi.escape_probe_log_text(accessxi.records_of_eminence_descriptor_record_probe(desc, selected))));
    return parts:concat(' || ');
end

function accessxi.records_of_eminence_pointer_text_probe(ptr)
    ptr = tonumber(ptr) or 0;
    if (not accessxi.is_probe_pointer(ptr)) then
        return '';
    end

    local strings = accessxi.probe_strings_at(ptr);
    local runs = accessxi.status_menu_probe_runs(ptr, 0x120);
    return ('s=%s runs=%s'):fmt(
        accessxi.escape_probe_log_text(strings),
        accessxi.escape_probe_log_text(runs));
end

function accessxi.records_of_eminence_record_pointer_probe(ptr)
    ptr = tonumber(ptr) or 0;
    if (not accessxi.is_probe_pointer(ptr)) then
        return '';
    end

    return accessxi.escape_probe_log_text(accessxi.format_probe_dwords(ptr, 0x00, 6));
end

function accessxi.records_of_eminence_descriptor_record_probe(desc, selected)
    desc = tonumber(desc) or 0;
    selected = tonumber(selected) or 0;
    if (not accessxi.is_probe_pointer(desc)) then
        return '';
    end

    local rec = desc;
    local ptr0 = read_u32(rec + 0x00) or 0;
    local ptr1 = read_u32(rec + 0x04) or 0;
    local value2 = read_u32(rec + 0x08) or 0;
    local value3 = read_u32(rec + 0x0C) or 0;
    local value4 = read_u32(rec + 0x10) or 0;
    return ('slot=1 rec=0x%08X p1=0x%08X p1Text=%s p1Words=%s p0=0x%08X p0Words=%s tail=%08X,%08X,%08X'):fmt(
        rec,
        ptr1,
        accessxi.records_of_eminence_pointer_text_probe(ptr1),
        accessxi.records_of_eminence_record_pointer_probe(ptr1),
        ptr0,
        accessxi.records_of_eminence_record_pointer_probe(ptr0),
        value2,
        value3,
        value4);
end

function accessxi.records_of_eminence_objective_category_label_allowed(label, parent_label)
    label = accessxi.plain_native_menu_label(label or '');
    if (label == '') then
        return '';
    end

    local lower = label:lower();
    local parent = accessxi.plain_native_menu_label(parent_label or ''):lower();
    if (lower == parent
        or lower:match('^menu%s+')
        or lower:match('^quest%s*%-?%d+$')
        or lower == 'ro'
        or lower == 'quest'
        or lower == 'quests'
        or lower == 'objective list'
        or lower == 'records of eminence'
        or lower == 'menu quest') then
        return '';
    end
    for _, bad in ipairs(T{
        'menu    quest',
        'vana\'versary nomad mog bonanza',
        'collection period',
        'loaded plugin',
        'bound:',
    }) do
        if (lower:contains(bad, true)) then
            return '';
        end
    end

    return label;
end

function accessxi.records_of_eminence_objective_category_candidate_label_from_ptr(ptr, parent_label)
    ptr = tonumber(ptr) or 0;
    if (not accessxi.is_probe_pointer(ptr)) then
        return '';
    end

    local label = accessxi.native_query_candidate_label_from_ptr(ptr, 'plain');
    label = accessxi.records_of_eminence_objective_category_label_allowed(label, parent_label);
    if (label ~= '') then
        return label;
    end

    for _, off in ipairs(T{ 0x00, 0x04, 0x08, 0x0C, 0x10, 0x14, 0x18, 0x20, 0x24, 0x28, 0x30, 0x40, 0x44 }) do
        label = accessxi.records_of_eminence_objective_category_label_allowed(read_probe_string(ptr + off, 180), parent_label);
        if (label ~= '') then
            return label;
        end
    end

    return '';
end

function accessxi.records_of_eminence_objective_category_descriptor_ptrs(entry, child)
    entry = tonumber(entry) or 0;
    child = tonumber(child) or 0;
    local candidates = T{};
    local seen = {};
    local function add(ptr, source)
        ptr = tonumber(ptr) or 0;
        if (not accessxi.is_probe_pointer(ptr) or seen[ptr] == true) then
            return;
        end
        seen[ptr] = true;
        candidates:append({
            ptr = ptr,
            source = tostring(source or ''),
        });
    end

    if (accessxi.is_probe_pointer(entry)) then
        add(entry, 'entry');
        for _, off in ipairs(T{ 0x00, 0x04, 0x08, 0x0C, 0x10, 0x14, 0x18, 0x1C, 0x20, 0x40, 0x44, 0x58 }) do
            add(read_u32(entry + off) or 0, ('entry+0x%02X'):fmt(off));
        end
        local desc = read_u32(entry + 0x0C) or 0;
        if (accessxi.is_probe_pointer(desc)) then
            for off = 0x00, 0x38, 4 do
                add(read_u32(desc + off) or 0, ('desc+0x%02X'):fmt(off));
            end
        end
    end

    if (accessxi.is_probe_pointer(child)) then
        add(child, 'child');
        for _, off in ipairs(T{ 0x14, 0x18, 0x20, 0x24, 0x30, 0x40, 0x44, 0x58, 0x80, 0x84, 0x88 }) do
            add(read_u32(child + off) or 0, ('child+0x%02X'):fmt(off));
        end
    end

    return candidates;
end

function accessxi.records_of_eminence_objective_category_descriptor_text_probe(entry, child, selected, visible_count, parent_label)
    local candidates = accessxi.records_of_eminence_objective_category_descriptor_ptrs(entry, child);
    if (candidates == nil or candidates:len() == 0) then
        return '';
    end

    local parts = T{};
    for index = 1, math.min(candidates:len(), 14) do
        local candidate = candidates[index];
        local ptr = tonumber(candidate.ptr) or 0;
        local label = accessxi.records_of_eminence_objective_category_candidate_label_from_ptr(ptr, parent_label);
        local strings = accessxi.probe_strings_at(ptr);
        local runs = '';
        if (accessxi.status_menu_probe_runs ~= nil) then
            runs = accessxi.status_menu_probe_runs(ptr, 0x120);
        end
        parts:append(('%s=0x%08X label="%s" strings="%s" runs="%s" dwords="%s"'):fmt(
            accessxi.escape_probe_log_text(tostring(candidate.source or '')),
            ptr,
            accessxi.escape_probe_log_text(label),
            accessxi.escape_probe_log_text_wide(strings),
            accessxi.escape_probe_log_text_wide(runs),
            accessxi.escape_probe_log_text(accessxi.format_probe_dwords(ptr, 0x00, 8))));
    end

    return ('selected=%d visible=%d candidates="%s"'):fmt(
        tonumber(selected) or 0,
        tonumber(visible_count) or 0,
        parts:concat(' || '));
end

function accessxi.records_of_eminence_packet_row(selected)
    selected = tonumber(selected) or 0;
    if (selected <= 0) then
        return nil, 'bad-selection';
    end

    accessxi.restore_roe_active_packet_cache_if_needed();

    local rows = accessxi.roe_active_records;
    if (type(rows) ~= 'table') then
        return nil, 'missing-active-packet';
    end

    local packet_player = tostring(accessxi.roe_active_player or '');
    local player_name = accessxi.current_player_name();
    if (packet_player ~= '' and player_name ~= '' and packet_player ~= player_name) then
        return nil, 'wrong-player-active-packet';
    end

    local packet_tick = tonumber(accessxi.roe_active_tick) or 0;
    if (packet_tick <= 0) then
        return nil, 'stale-active-packet';
    end

    local row = rows[selected];
    if (type(row) ~= 'table') then
        return nil, 'missing-active-row';
    end

    local record_id = tonumber(row.id) or 0;
    if (record_id <= 0) then
        return nil, 'empty-active-row';
    end

    local records = accessxi.records_of_eminence_data.records or T{};
    local record = records[record_id];
    return row, 'packet-active', record;
end

function accessxi.records_of_eminence_active_record_id(record_id)
    record_id = tonumber(record_id) or 0;
    if (record_id <= 0) then
        return false, 'bad-record-id';
    end

    accessxi.restore_roe_active_packet_cache_if_needed();

    local rows = accessxi.roe_active_records;
    if (type(rows) ~= 'table') then
        return false, 'missing-active-packet';
    end

    local packet_player = tostring(accessxi.roe_active_player or '');
    local player_name = accessxi.current_player_name();
    if (packet_player ~= '' and player_name ~= '' and packet_player ~= player_name) then
        return false, 'wrong-player-active-packet';
    end

    local packet_tick = tonumber(accessxi.roe_active_tick) or 0;
    if (packet_tick <= 0) then
        return false, 'stale-active-packet';
    end

    for _, row in ipairs(rows) do
        if (type(row) == 'table' and (tonumber(row.id) or 0) == record_id) then
            return true, 'packet-active-record', row;
        end
    end

    return false, 'not-active-record';
end

function accessxi.records_of_eminence_completed_record_id(record_id)
    record_id = tonumber(record_id) or 0;
    if (record_id <= 0) then
        return false, 'bad-record-id';
    end

    local complete_tick = tonumber(accessxi.roe_complete_tick) or 0;
    if (complete_tick <= 0) then
        return false, 'missing-complete-packet';
    end

    local pages = accessxi.roe_complete_pages;
    if (type(pages) ~= 'table') then
        return false, 'missing-complete-pages';
    end

    for _, page in pairs(pages) do
        if (type(page) == 'table') then
            for _, completed_id in ipairs(page) do
                if ((tonumber(completed_id) or 0) == record_id) then
                    return true, 'packet-completed-record';
                end
            end
        end
    end

    return false, 'not-completed-record';
end

function accessxi.records_of_eminence_progress_fragment(progress, goal)
    progress = tonumber(progress) or 0;
    goal = tonumber(goal) or 0;
    if (goal > 0) then
        return ('Progress %d of %d'):fmt(progress, goal);
    end
    return ('Progress %d'):fmt(progress);
end

function accessxi.remember_records_of_eminence_detail_row(selected, visible_count, record_id, progress, goal, label, record, source, timed)
    if (type(record) ~= 'table' or (tonumber(record_id) or 0) <= 0 or tostring(label or '') == '') then
        return;
    end

    accessxi.last_records_of_eminence_detail_row = {
        selected = tonumber(selected) or 0,
        visible_count = tonumber(visible_count) or 0,
        record_id = record_id,
        progress = progress,
        goal = goal,
        label = tostring(label or ''),
        record = record,
        source = tostring(source or ''),
        timed = timed == true,
    };
    accessxi.last_records_of_eminence_detail_tick = tick();
    if (timed == true) then
        accessxi.last_records_of_eminence_timed_detail_row = accessxi.last_records_of_eminence_detail_row;
        accessxi.last_records_of_eminence_timed_detail_tick = accessxi.last_records_of_eminence_detail_tick;
    end
end

function accessxi.records_of_eminence_record_is_timed(row, record)
    return (type(row) == 'table' and row.timed == true)
        or (type(record) == 'table' and (record.timed == true or record.limited_time == true));
end

function accessxi.log_records_of_eminence_timed_surface_probe(menu_name, row, record, reason)
    if (type(row) ~= 'table' or type(record) ~= 'table') then
        return;
    end
    if (not accessxi.records_of_eminence_record_is_timed(row, record)) then
        return;
    end

    local record_id = tonumber(row.record_id) or 0;
    if (record_id == 0) then
        return;
    end
    local selected = tonumber(row.selected) or 0;
    local obj = get_current_menu_object_ptr();
    local target = safe_call(function () return AshitaCore:GetMemoryManager():GetTarget(); end, nil);
    local ank = target ~= nil and (tonumber(safe_call(function () return target:GetWindowAnkNum(); end, -1)) or -1) or -1;
    local ank_x = target ~= nil and (tonumber(safe_call(function () return target:GetWindowAnkX(); end, -1)) or -1) or -1;
    local ank_y = target ~= nil and (tonumber(safe_call(function () return target:GetWindowAnkY(); end, -1)) or -1) or -1;
    local indexes = T{};
    local detail_index = -1;
    if (obj ~= 0) then
        for _, offset in ipairs(T{ 0x24, 0x28, 0x2C, 0x30, 0x34, 0x4C, 0x50, 0x58, 0x64 }) do
            local value = tonumber(read_i32(obj + offset)) or 0;
            if (offset == 0x4C) then
                detail_index = value;
            end
            indexes:append(('%02X=%d'):fmt(offset, value));
        end
    end

    local key = ('%s:%s:%d:%d:0x%08X:%d:%d,%d,%d:%s'):fmt(
        tostring(menu_name or ''),
        tostring(reason or ''),
        record_id,
        selected,
        obj,
        detail_index,
        ank,
        ank_x,
        ank_y,
        indexes:concat(','));
    if (key == tostring(accessxi.last_records_of_eminence_timed_surface_probe_key or '')) then
        return;
    end
    accessxi.last_records_of_eminence_timed_surface_probe_key = key;
    log_state(('state records-of-eminence timed-surface menu="%s" reason="%s" recordId=%d selected=%d detailIndex=%d label="%s" obj=0x%08X ank=%d,%d,%d idx="%s"'):fmt(
        tostring(menu_name or ''),
        accessxi.escape_probe_log_text(tostring(reason or '')),
        record_id,
        selected,
        detail_index,
        accessxi.escape_probe_log_text(tostring(row.label or record.label or '')),
        obj,
        ank,
        ank_x,
        ank_y,
        accessxi.escape_probe_log_text(indexes:concat(','))));
end

function accessxi.log_records_of_eminence_detail_surface_probe(menu_name, reason)
    local now = tick();
    if ((tonumber(accessxi.records_of_eminence_text_probe_until) or 0) < now
        and (tonumber(accessxi.records_of_eminence_detail_probe_until) or 0) < now) then
        return;
    end
    local last_nonblank = tostring(accessxi.last_nonblank_menu_name or '');
    if (not (last_nonblank:eq('menu    quest01', true) or last_nonblank:eq('menu    comyn', true) or last_nonblank:eq('menu    inline', true))) then
        return;
    end

    local row = accessxi.last_records_of_eminence_detail_row;
    local row_age = (tonumber(accessxi.last_records_of_eminence_detail_tick) or 0) > 0 and (tick() - (tonumber(accessxi.last_records_of_eminence_detail_tick) or 0)) or 999999;
    if (type(row) ~= 'table' or row_age > 300000 or type(row.record) ~= 'table') then
        return;
    end

    local record = row.record;
    local record_id = tonumber(row.record_id) or tonumber(record.id) or 0;
    if (record_id == 0) then
        return;
    end

    local obj = get_current_menu_object_ptr();
    local target = safe_call(function () return AshitaCore:GetMemoryManager():GetTarget(); end, nil);
    local ank = target ~= nil and (tonumber(safe_call(function () return target:GetWindowAnkNum(); end, -1)) or -1) or -1;
    local ank_x = target ~= nil and (tonumber(safe_call(function () return target:GetWindowAnkX(); end, -1)) or -1) or -1;
    local ank_y = target ~= nil and (tonumber(safe_call(function () return target:GetWindowAnkY(); end, -1)) or -1) or -1;
    local sub = target ~= nil and (tonumber(safe_call(function () return target:GetWindowSub(); end, -1)) or -1) or -1;
    local sub_x = target ~= nil and (tonumber(safe_call(function () return target:GetWindowSubAnkX(); end, -1)) or -1) or -1;
    local sub_y = target ~= nil and (tonumber(safe_call(function () return target:GetWindowSubAnkY(); end, -1)) or -1) or -1;
    local indexes = T{};
    local detail_index = -1;
    if (obj ~= 0) then
        for _, offset in ipairs(T{ 0x24, 0x28, 0x2C, 0x30, 0x34, 0x4C, 0x50, 0x58, 0x64 }) do
            local value = tonumber(read_i32(obj + offset)) or 0;
            if (offset == 0x4C) then
                detail_index = value;
            end
            indexes:append(('%02X=%d'):fmt(offset, value));
        end
    end

    local key = ('%s:%s:%d:%d:0x%08X:%d:%d,%d,%d:%d,%d,%d:%s'):fmt(
        tostring(menu_name or ''),
        tostring(reason or ''),
        record_id,
        tonumber(row.selected) or 0,
        obj,
        detail_index,
        ank,
        ank_x,
        ank_y,
        sub,
        sub_x,
        sub_y,
        indexes:concat(','));
    if (key == tostring(accessxi.last_records_of_eminence_detail_surface_probe_key or '')) then
        return;
    end
    accessxi.last_records_of_eminence_detail_surface_probe_key = key;
    log_state(('state records-of-eminence detail-surface menu="%s" lastMenu="%s" reason="%s" recordId=%d selected=%d timed=%s detailIndex=%d label="%s" obj=0x%08X ank=%d,%d,%d sub=%d,%d,%d idx="%s"'):fmt(
        tostring(menu_name or ''),
        accessxi.escape_probe_log_text(last_nonblank),
        accessxi.escape_probe_log_text(tostring(reason or '')),
        record_id,
        tonumber(row.selected) or 0,
        tostring(accessxi.records_of_eminence_record_is_timed(row, record)),
        detail_index,
        accessxi.escape_probe_log_text(tostring(row.label or record.label or '')),
        obj,
        ank,
        ank_x,
        ank_y,
        sub,
        sub_x,
        sub_y,
        accessxi.escape_probe_log_text(indexes:concat(','))));
end

function accessxi.records_of_eminence_record_rewards_fragment(record, detail)
    if (type(detail) == 'table' and tostring(detail.rewards or '') ~= '') then
        local rewards = tostring(detail.rewards or '');
        if (detail.not_repeatable == true or (type(record) == 'table' and record.not_repeatable == true)) then
            return ('Rewards. (Not Repeatable) %s'):fmt(rewards);
        end
        return ('Rewards. %s'):fmt(rewards);
    end

    local rewards = type(record) == 'table' and record.rewards or nil;
    if (type(rewards) ~= 'table') then
        return '';
    end

    local parts = T{};
    if ((tonumber(rewards.sparks) or 0) > 0) then
        parts:append(('%d Spa.'):fmt(tonumber(rewards.sparks) or 0));
    end
    if ((tonumber(rewards.exp) or 0) > 0) then
        parts:append(('%d EXP'):fmt(tonumber(rewards.exp) or 0));
    end
    if ((tonumber(rewards.accolades) or 0) > 0) then
        parts:append(('%d Acc.'):fmt(tonumber(rewards.accolades) or 0));
    end
    if (#parts == 0) then
        return '';
    end
    if (type(record) == 'table' and record.not_repeatable == true) then
        return ('Rewards. (Not Repeatable) %s'):fmt(parts:concat(' '));
    end
    return ('Rewards. %s'):fmt(parts:concat(' '));
end

function accessxi.records_of_eminence_record_number_required_fragment(row, record)
    local goal = type(record) == 'table' and (tonumber(record.goal) or 0) or 0;
    if (goal <= 0 and type(row) == 'table') then
        goal = tonumber(row.goal) or 0;
    end
    if (goal <= 0) then
        return '';
    end
    local record_id = 0;
    if (type(row) == 'table') then
        record_id = tonumber(row.record_id) or tonumber(row.id) or 0;
    end
    if (record_id <= 0 and type(record) == 'table') then
        record_id = tonumber(record.id) or 0;
    end

    local progress = nil;
    if (record_id > 0) then
        local active, _, active_row = accessxi.records_of_eminence_active_record_id(record_id);
        if (active == true and type(active_row) == 'table') then
            local active_progress = tonumber(active_row.progress);
            if (active_progress ~= nil and active_progress >= 0) then
                progress = active_progress;
            end
        end
    end

    if (progress == nil and type(row) == 'table') then
        local source = tostring(row.source or '');
        local row_progress = tonumber(row.progress);
        if (row_progress ~= nil and row_progress >= 0 and (source:find('packet', 1, true) ~= nil or source:find('active-row', 1, true) ~= nil)) then
            progress = row_progress;
        end
    end

    if (progress == nil and record_id > 0) then
        local completed = accessxi.records_of_eminence_completed_record_id(record_id);
        if (completed == true) then
            progress = goal;
        end
    end

    if (progress ~= nil) then
        return ('Number Required. %d/%d'):fmt(progress, goal);
    end
    return ('Number Required. %d'):fmt(goal);
end

function accessxi.records_of_eminence_wrap_detail_line(line, max_width)
    local chunks = T{};
    local clean = accessxi.sentence_fragment(line);
    max_width = tonumber(max_width) or 48;
    if (clean == '') then
        return chunks;
    end

    while (#clean > max_width) do
        local cut = 0;
        for i = math.min(#clean, max_width), 28, -1 do
            local ch = clean:sub(i, i);
            if (ch == ' ' or ch == ',' or ch == ';') then
                cut = i;
                break;
            end
        end
        if (cut <= 0) then
            cut = max_width;
        end
        local chunk = accessxi.sentence_fragment(clean:sub(1, cut));
        if (chunk ~= '') then
            chunks:append(chunk);
        end
        clean = accessxi.sentence_fragment(clean:sub(cut + 1));
    end
    if (clean ~= '') then
        chunks:append(clean);
    end
    return chunks;
end

function accessxi.records_of_eminence_record_detail_parts(row, record)
    if (type(record) ~= 'table') then
        return T{}, nil;
    end

    local description = tostring(record.description or '');
    if (description == '') then
        return T{}, nil;
    end

    local parts = T{};
    for line in description:gmatch('[^\r\n]+') do
        local clean = accessxi.sentence_fragment(line);
        if (clean ~= '') then
            for _, chunk in ipairs(accessxi.records_of_eminence_wrap_detail_line(clean, 48)) do
                if (chunk ~= '') then
                    parts:append(chunk);
                end
            end
        end
    end
    if (#parts <= 0) then
        return T{}, nil;
    end

    return parts, {
        source = tostring(record.source or ''),
        description = description,
    };
end

function accessxi.records_of_eminence_record_display_detail_parts(row, record)
    if (type(record) ~= 'table') then
        return T{}, nil;
    end

    local parts = T{};
    local kinds = T{};
    local function append_part(text, kind, wrap)
        text = accessxi.sentence_fragment(text);
        if (text == '') then
            return;
        end
        if (wrap == true) then
            for _, chunk in ipairs(accessxi.records_of_eminence_wrap_detail_line(text, 48)) do
                if (chunk ~= '') then
                    parts:append(chunk);
                    kinds:append(kind);
                end
            end
            return;
        end
        parts:append(text);
        kinds:append(kind);
    end

    append_part(tostring(row ~= nil and row.label or record.label or ''), 'title', false);
    for line in tostring(record.description or ''):gmatch('[^\r\n]+') do
        append_part(line, 'description', true);
    end
    append_part(accessxi.records_of_eminence_record_number_required_fragment(row, record), 'number-required', false);
    append_part(accessxi.records_of_eminence_record_rewards_fragment(record, nil), 'rewards', false);

    if (#parts <= 0) then
        return T{}, nil;
    end
    return parts, {
        source = tostring(record.source or ''),
        description = tostring(record.description or ''),
        kinds = kinds,
    };
end

function accessxi.records_of_eminence_detail_line_fragment(parts, index, row)
    if (type(parts) ~= 'table' or #parts <= 0) then
        return '';
    end
    index = tonumber(index) or 0;
    if (index <= 0) then
        return '';
    end
    local selected = type(row) == 'table' and (tonumber(row.selected) or 0) or 0;
    if (selected >= 20 and index <= 8) then
        local tail_start = 8 - #parts + 1;
        local mapped_index = index - tail_start + 1;
        if (mapped_index >= 1 and mapped_index <= #parts) then
            return tostring(parts[mapped_index] or '');
        end
        return '';
    end
    if (index > #parts) then
        return '';
    end
    return tostring(parts[index] or '');
end

function accessxi.records_of_eminence_should_start_with_full_detail(row, reason)
    if (tostring(reason or '') ~= 'confirm-return') then
        return false;
    end
    if (type(row) ~= 'table') then
        return false;
    end
    return (tonumber(row.selected) or 0) >= 20;
end

function accessxi.records_of_eminence_recent_objective_detail_row(row)
    if (type(row) ~= 'table' or type(row.record) ~= 'table') then
        return false;
    end

    local row_age = (tonumber(accessxi.last_records_of_eminence_detail_tick) or 0) > 0
        and (tick() - (tonumber(accessxi.last_records_of_eminence_detail_tick) or 0))
        or 999999;
    if (row_age > 30000) then
        return false;
    end

    local context = tostring(accessxi.quests_menu_context or '');
    local context_age = (tonumber(accessxi.quests_menu_context_tick) or 0) > 0
        and (tick() - (tonumber(accessxi.quests_menu_context_tick) or 0))
        or 999999;
    return context_age <= 300000
        and (context == 'records-of-eminence-objective-catalog'
            or context == 'records-of-eminence-objective-category'
            or context == 'records-of-eminence');
end

function accessxi.records_of_eminence_recent_detail_row_for_surface(row)
    if (type(row) ~= 'table' or type(row.record) ~= 'table') then
        return false;
    end

    local row_age = (tonumber(accessxi.last_records_of_eminence_detail_tick) or 0) > 0
        and (tick() - (tonumber(accessxi.last_records_of_eminence_detail_tick) or 0))
        or 999999;
    if (row_age > 30000) then
        return false;
    end

    local record_id = tonumber(row.record_id) or 0;
    local selected = tonumber(row.selected) or 0;
    return record_id > 0 and selected > 0;
end

function accessxi.records_of_eminence_quest01_centered_detail_surface(menu_name)
    menu_name = tostring(menu_name or get_menu_name() or '');
    if (not menu_name:eq('menu    quest01', true)) then
        return false;
    end

    local signal = accessxi.records_of_eminence_quest01_row_signal();
    if (type(signal) ~= 'table'
        or (tonumber(signal.record_id) or 0) <= 0
        or (tonumber(signal.visible_count) or 0) < 20
        or (tonumber(signal.slot_id) or 0) < 0xE001
        or (tonumber(signal.slot_id) or 0) > 0xFFFF) then
        return false;
    end

    local target = safe_call(function () return AshitaCore:GetMemoryManager():GetTarget(); end, nil);
    if (target == nil) then
        return false;
    end

    local ank = tonumber(safe_call(function () return target:GetWindowAnkNum(); end, -1)) or -1;
    local ank_x = tonumber(safe_call(function () return target:GetWindowAnkX(); end, -1)) or -1;
    local ank_y = tonumber(safe_call(function () return target:GetWindowAnkY(); end, -1)) or -1;
    if (ank < 3 or ank_x < 940 or ank_x > 980 or ank_y < 240 or ank_y > 460) then
        return false;
    end

    local obj = get_current_menu_object_ptr();
    if (obj == 0) then
        return false;
    end

    local detail_index = tonumber(read_i32(obj + 0x4C)) or 0;
    local idx24 = tonumber(read_i32(obj + 0x24)) or -1;
    local idx28 = tonumber(read_i32(obj + 0x28)) or -2;
    return detail_index > 0
        and detail_index <= 64
        and idx24 > 0
        and idx24 == idx28;
end

function accessxi.records_of_eminence_quest01_motion_detail_surface(menu_name)
    menu_name = tostring(menu_name or get_menu_name() or '');
    if (not menu_name:eq('menu    quest01', true)) then
        return false;
    end

    local signal = accessxi.records_of_eminence_quest01_row_signal();
    local selected = type(signal) == 'table' and (tonumber(signal.selected) or 0) or 0;
    if (type(signal) ~= 'table'
        or selected <= 0
        or (tonumber(signal.record_id) or 0) <= 0
        or (tonumber(signal.visible_count) or 0) < 20
        or (tonumber(signal.slot_id) or 0) < 0xE001
        or (tonumber(signal.slot_id) or 0) > 0xFFFF) then
        return false;
    end

    local target = safe_call(function () return AshitaCore:GetMemoryManager():GetTarget(); end, nil);
    if (target == nil) then
        return false;
    end

    local ank = tonumber(safe_call(function () return target:GetWindowAnkNum(); end, -1)) or -1;
    local ank_x = tonumber(safe_call(function () return target:GetWindowAnkX(); end, -1)) or -1;
    local ank_y = tonumber(safe_call(function () return target:GetWindowAnkY(); end, -1)) or -1;
    local zero_origin_motion = (ank == 0 or ank == 1) and ank_x == 0 and ank_y == 0;
    local positioned_motion = ank == 0 and ank_x >= 940 and ank_x <= 1040 and ank_y >= 240 and ank_y <= 500;
    local positioned_ank_motion = ank == 1 and ank_x >= 940 and ank_x <= 1040 and ank_y >= 240 and ank_y <= 500;
    if (not (zero_origin_motion or positioned_motion or positioned_ank_motion)) then
        return false;
    end

    local obj = get_current_menu_object_ptr();
    if (obj == 0) then
        return false;
    end

    local detail_index = tonumber(read_i32(obj + 0x4C)) or 0;
    local idx24 = tonumber(read_i32(obj + 0x24)) or -1;
    local idx28 = tonumber(read_i32(obj + 0x28)) or -2;
    return detail_index > 0
        and detail_index <= 64
        and detail_index ~= selected
        and idx24 > 0
        and idx24 == idx28;
end

function accessxi.records_of_eminence_quest01_detail_surface_active(menu_name)
    menu_name = tostring(menu_name or get_menu_name() or '');
    local quest01_surface = menu_name:eq('menu    quest01', true);
    local quest00_transition = false;
    local quest00_recent_detail_surface = false;
    if (menu_name:eq('menu    quest00', true)) then
        local watched_confirm = tostring(accessxi.records_of_eminence_detail_watch_reason or '') == 'confirm-return'
            and (tonumber(accessxi.records_of_eminence_detail_watch_until) or 0) > tick();
        local fresh_objective_detail = accessxi.records_of_eminence_recent_objective_detail_row(accessxi.last_records_of_eminence_detail_row);
        local fresh_detail_row = accessxi.records_of_eminence_recent_detail_row_for_surface(accessxi.last_records_of_eminence_detail_row);
        local last_nonblank = tostring(accessxi.last_nonblank_menu_name or '');
        local transition_age = (tonumber(accessxi.last_menu_transition_tick) or 0) > 0
            and (tick() - (tonumber(accessxi.last_menu_transition_tick) or 0))
            or 999999;
        quest00_transition = (watched_confirm or fresh_objective_detail)
            and (last_nonblank:eq('menu    quest01', true)
                or (tostring(accessxi.last_menu_transition_from or ''):eq('menu    quest01', true)
                    and tostring(accessxi.last_menu_transition_to or ''):eq('menu    quest00', true)
                    and transition_age <= 5000));
        quest00_recent_detail_surface = fresh_detail_row
            and (last_nonblank:eq('menu    quest01', true)
                or last_nonblank:eq('menu    inline', true)
                or (tostring(accessxi.last_menu_transition_from or ''):eq('menu    quest01', true)
                    and tostring(accessxi.last_menu_transition_to or ''):eq('menu    quest00', true)
                    and transition_age <= 5000)
                or (tostring(accessxi.last_menu_transition_from or ''):eq('menu    inline', true)
                    and tostring(accessxi.last_menu_transition_to or ''):eq('menu    quest00', true)
                    and transition_age <= 5000));
    end
    if (not (quest01_surface or quest00_transition or quest00_recent_detail_surface)) then
        return false;
    end

    local target = safe_call(function () return AshitaCore:GetMemoryManager():GetTarget(); end, nil);
    if (target == nil) then
        return false;
    end

    local ank = tonumber(safe_call(function () return target:GetWindowAnkNum(); end, -1)) or -1;
    local ank_x = tonumber(safe_call(function () return target:GetWindowAnkX(); end, -1)) or -1;
    local ank_y = tonumber(safe_call(function () return target:GetWindowAnkY(); end, -1)) or -1;
    local detail_index = 0;
    local obj = get_current_menu_object_ptr();
    local detail_object_active = false;
    local detail_row_shape_active = false;
    if (obj ~= 0) then
        detail_index = tonumber(read_i32(obj + 0x4C)) or 0;
        local idx24 = tonumber(read_i32(obj + 0x24)) or -1;
        local idx28 = tonumber(read_i32(obj + 0x28)) or -2;
        local flags50 = tonumber(read_i32(obj + 0x50)) or 0;
        detail_row_shape_active = detail_index > 0
            and detail_index <= 64
            and idx24 > 0
            and idx24 == idx28;
        detail_object_active = detail_row_shape_active
            and bit.band(flags50, 1048576) ~= 0;
    end
    local zero_origin_detail = ank_x == 0 and ank_y == 0 and detail_object_active;
    local signal = quest01_surface and accessxi.records_of_eminence_quest01_row_signal() or nil;
    local live_objective_detail = accessxi.records_of_eminence_dat_objective_signal(signal);
    local centered_detail = false;
    local signal_selected = type(signal) == 'table' and (tonumber(signal.selected) or 0) or 0;
    local zero_origin_motion = (ank == 0 or ank == 1) and ank_x == 0 and ank_y == 0;
    local positioned_motion = ank == 0 and ank_x >= 940 and ank_x <= 1040 and ank_y >= 240 and ank_y <= 500;
    local positioned_ank_motion = ank == 1 and ank_x >= 940 and ank_x <= 1040 and ank_y >= 240 and ank_y <= 500;
    local zero_origin_motion_detail = live_objective_detail
        and (zero_origin_motion or positioned_motion or positioned_ank_motion)
        and signal_selected > 0
        and detail_index ~= signal_selected
        and detail_row_shape_active;
    local zero_origin_objective_detail = live_objective_detail
        and signal_selected > 0
        and zero_origin_detail;
    local native_motion_detail = accessxi.records_of_eminence_native_motion_detail_active_for_signal(signal, detail_index);
    local catalog_detail_signal = accessxi.records_of_eminence_catalog_detail_signal_active(signal, detail_index);
    if (quest01_surface) then
        return native_motion_detail or catalog_detail_signal or centered_detail or zero_origin_motion_detail or zero_origin_objective_detail;
    end
    if (quest00_recent_detail_surface and detail_object_active) then
        return true;
    end
    return (ank >= 2 and ank_y >= 150) or zero_origin_detail or detail_object_active;
end

function accessxi.records_of_eminence_probe_text_equals(left, right)
    left = clean_probe_text(left):lower();
    right = clean_probe_text(right):lower();
    return (left ~= '' and right ~= '' and left == right);
end

function accessxi.records_of_eminence_parse_probe_run(run)
    local off_text, text = tostring(run or ''):match('^%+(%x+)="(.*)"$');
    if (off_text == nil) then
        return nil, '';
    end
    return tonumber(off_text or '0', 16) or 0, tostring(text or '');
end

function accessxi.log_records_of_eminence_text_buffer_run(seq, seed_label, owner, off, target, record_id, selected, label, reason, native_pos, family, run)
    local slot, text = accessxi.records_of_eminence_parse_probe_run(run);
    if (slot == nil or text == '') then
        return;
    end

    local detail_index = tonumber(tostring(native_pos or ''):match('detailIndex=(%-?%d+)') or '-1') or -1;
    local context_offset = math.max(0, slot - 0x10);
    local match_label = accessxi.records_of_eminence_probe_text_equals(text, label) and 1 or 0;
    local clean_label = clean_probe_text(label):lower();
    local clean_text = clean_probe_text(text):lower();
    local label_contains_text = (clean_label ~= '' and clean_text ~= '' and clean_label:find(clean_text, 1, true) ~= nil) and 1 or 0;
    local text_contains_label = (clean_label ~= '' and clean_text ~= '' and clean_text:find(clean_label, 1, true) ~= nil) and 1 or 0;
    if (match_label ~= 1
        and label_contains_text ~= 1
        and text_contains_label ~= 1
        and not accessxi.records_of_eminence_native_detail_description_marker(text)
        and not accessxi.records_of_eminence_native_detail_summary_marker(text)) then
        return;
    end
    log_state(('state records-of-eminence text-buffer-slot seq=%d recordId=%d selected=%d detailIndex=%d label="%s" reason="%s" seed="%s" owner=0x%08X off=0x%03X target=0x%08X family="%s" slot=0x%03X matchLabel=%d labelContainsText=%d textContainsLabel=%d text="%s" dwords="%s" bytes="%s"'):fmt(
        tonumber(seq) or 0,
        tonumber(record_id) or 0,
        tonumber(selected) or 0,
        detail_index,
        accessxi.escape_probe_log_text(label),
        accessxi.escape_probe_log_text(reason),
        accessxi.escape_probe_log_text(seed_label),
        tonumber(owner) or 0,
        tonumber(off) or 0,
        tonumber(target) or 0,
        accessxi.escape_probe_log_text(family),
        slot,
        match_label,
        label_contains_text,
        text_contains_label,
        accessxi.escape_probe_log_text(text),
        accessxi.escape_probe_log_text_wide(accessxi.format_probe_dwords(target, context_offset, 8)),
        accessxi.escape_probe_log_text_wide(accessxi.format_probe_bytes(target, context_offset, 0x40))));
end

function accessxi.log_records_of_eminence_text_buffer_slots(seq, seed_label, owner, off, target, record_id, selected, label, reason, native_pos)
    target = tonumber(target) or 0;
    if (not accessxi.is_probe_pointer(target)) then
        return;
    end

    local slots = T{};
    for _, slot in ipairs(T{ 0x030, 0x03A, 0x07C, 0x084, 0x0C1, 0x0CA, 0x0FD, 0x109, 0x111, 0x120, 0x13A, 0x212, 0x2A4 }) do
        local text = clean_probe_text(read_probe_string(target + slot, 80));
        if (text ~= '') then
            slots:append(('+%03X="%s"'):fmt(slot, accessxi.escape_probe_log_text(text)));
        end
    end

    local ascii = accessxi.collect_probe_ascii_runs(target, 0x340, 4, 18);
    local utf16 = accessxi.collect_probe_utf16_runs(target, 0x340, 3, 12);
    local ffxi = accessxi.collect_probe_ffxi_utf16_runs(target, 0x340, 3, 12);
    for _, run in ipairs(ascii) do
        accessxi.log_records_of_eminence_text_buffer_run(seq, seed_label, owner, off, target, record_id, selected, label, reason, native_pos, 'ascii', run);
    end
    for _, run in ipairs(utf16) do
        accessxi.log_records_of_eminence_text_buffer_run(seq, seed_label, owner, off, target, record_id, selected, label, reason, native_pos, 'utf16', run);
    end
    for _, run in ipairs(ffxi) do
        accessxi.log_records_of_eminence_text_buffer_run(seq, seed_label, owner, off, target, record_id, selected, label, reason, native_pos, 'ffxi', run);
    end
    log_state(('state records-of-eminence text-buffer seq=%d recordId=%d selected=%d label="%s" reason="%s" seed="%s" owner=0x%08X off=0x%03X target=0x%08X nativePos="%s" slots="%s" ascii="%s" utf16="%s" ffxi="%s" bytes100="%s" bytes200="%s"'):fmt(
        tonumber(seq) or 0,
        tonumber(record_id) or 0,
        tonumber(selected) or 0,
        accessxi.escape_probe_log_text(label),
        accessxi.escape_probe_log_text(reason),
        accessxi.escape_probe_log_text(seed_label),
        tonumber(owner) or 0,
        tonumber(off) or 0,
        target,
        accessxi.escape_probe_log_text(native_pos),
        accessxi.escape_probe_log_text_wide(slots:concat(' ')),
        accessxi.escape_probe_log_text_wide(ascii:concat(' ')),
        accessxi.escape_probe_log_text_wide(utf16:concat(' ')),
        accessxi.escape_probe_log_text_wide(ffxi:concat(' ')),
        accessxi.escape_probe_log_text_wide(accessxi.format_probe_bytes(target, 0x100, 0x80)),
        accessxi.escape_probe_log_text_wide(accessxi.format_probe_bytes(target, 0x200, 0xC0))));
end

function accessxi.records_of_eminence_text_buffer_probe_should_log(seed_label, off, target, label)
    seed_label = tostring(seed_label or '');
    off = tonumber(off) or 0;
    target = tonumber(target) or 0;
    if (seed_label ~= 'roetext.obj+018' or not accessxi.is_probe_pointer(target)) then
        return false;
    end
    if (off == 0x10) then
        return true;
    end

    local runs = accessxi.status_menu_probe_runs(target, 0x240);
    local text = tostring(runs or ''):lower();
    local row_label = tostring(label or ''):lower();
    if (row_label ~= '' and text:find(row_label, 1, true) ~= nil) then
        return true;
    end
    return text:find('number required', 1, true) ~= nil
        or text:find('reward', 1, true) ~= nil
        or text:find('rewards', 1, true) ~= nil
        or text:find('sparks', 1, true) ~= nil
        or text:find('accolades', 1, true) ~= nil;
end

function accessxi.records_of_eminence_native_detail_text_candidate(text)
    text = accessxi.plain_native_menu_help(text or '');
    if (text == '' or #text < 4 or #text > 180) then
        return '';
    end

    local lower = text:lower();
    if (lower:find('accessxi', 1, true) ~= nil
        or lower:find('ssxi_reader', 1, true) ~= nil
        or lower:find('keytops', 1, true) ~= nil
        or lower:find('controller', 1, true) ~= nil
        or lower:find('misc    ', 1, true) ~= nil
        or lower:find('white   ', 1, true) ~= nil
        or lower:find('menu    ', 1, true) ~= nil
        or lower:match('^menu%s+[%w_%-]+$') ~= nil) then
        return '';
    end
    if (lower:match('^[%p%s%d]+$') ~= nil) then
        return '';
    end
    if (text:find(' ', 1, true) == nil) then
        return '';
    end
    return text;
end

function accessxi.records_of_eminence_add_native_detail_candidate(lines, seen, text, source, offset)
    if (type(lines) ~= 'table' or type(seen) ~= 'table') then
        return;
    end
    text = accessxi.records_of_eminence_native_detail_text_candidate(text);
    if (text == '') then
        return;
    end
    local key = text:lower();
    if (seen[key] == true) then
        return;
    end
    seen[key] = true;
    lines:append({
        text = text,
        source = tostring(source or ''),
        group = tostring(source or ''),
        offset = tonumber(offset) or 0,
    });
end

function accessxi.records_of_eminence_collect_native_detail_runs_from_ptr(lines, seen, ptr, length, limit, source)
    ptr = tonumber(ptr) or 0;
    if (not accessxi.is_probe_pointer(ptr)) then
        return;
    end
    length = tonumber(length) or 0x340;
    limit = tonumber(limit) or 32;
    source = tostring(source or '');

    for _, run in ipairs(accessxi.collect_probe_ascii_runs(ptr, length, 4, limit)) do
        local off, text = accessxi.records_of_eminence_parse_probe_run(run);
        accessxi.records_of_eminence_add_native_detail_candidate(lines, seen, text, source .. ':ascii', off);
    end
    for _, run in ipairs(accessxi.collect_probe_utf16_runs(ptr, length, 3, limit)) do
        local off, text = accessxi.records_of_eminence_parse_probe_run(run);
        accessxi.records_of_eminence_add_native_detail_candidate(lines, seen, text, source .. ':utf16', off);
    end
    for _, run in ipairs(accessxi.collect_probe_ffxi_utf16_runs(ptr, length, 3, limit)) do
        local off, text = accessxi.records_of_eminence_parse_probe_run(run);
        accessxi.records_of_eminence_add_native_detail_candidate(lines, seen, text, source .. ':ffxi', off);
    end
end

function accessxi.records_of_eminence_detail_label_match(text, label)
    text = accessxi.plain_native_menu_help(text or ''):lower():gsub('%s+', ' '):trim();
    label = accessxi.plain_native_menu_help(label or ''):lower():gsub('%s+', ' '):trim();
    if (text == '' or label == '') then
        return false;
    end
    return text == label or text:find(label, 1, true) ~= nil or label:find(text, 1, true) ~= nil;
end

function accessxi.records_of_eminence_detail_label_exact_match(text, label)
    text = accessxi.plain_native_menu_help(text or ''):lower():gsub('%s+', ' '):trim();
    label = accessxi.plain_native_menu_help(label or ''):lower():gsub('%s+', ' '):trim();
    if (text == '' or label == '') then
        return false;
    end
    return text == label;
end

function accessxi.records_of_eminence_detail_label_token_match(text, label)
    text = accessxi.plain_native_menu_help(text or ''):lower():gsub('%s+', ' '):trim();
    label = accessxi.plain_native_menu_help(label or ''):lower():gsub('%s+', ' '):trim();
    if (text == '' or label == '') then
        return false;
    end
    if (text == label) then
        return true;
    end
    if (#text < 8 or #label < 8 or text:find(' ', 1, true) == nil or label:find(' ', 1, true) == nil) then
        return false;
    end

    local function boundary_contains(haystack, needle)
        local start = 1;
        while (start <= #haystack) do
            local first, last = haystack:find(needle, start, true);
            if (first == nil) then
                return false;
            end
            local before = first <= 1 and '' or haystack:sub(first - 1, first - 1);
            local after = last >= #haystack and '' or haystack:sub(last + 1, last + 1);
            local before_ok = before == '' or before:match('%w') == nil;
            local after_ok = after == '' or after:match('%w') == nil;
            if (before_ok and after_ok) then
                return true;
            end
            start = first + 1;
        end
        return false;
    end

    return boundary_contains(text, label) or boundary_contains(label, text);
end

function accessxi.records_of_eminence_detail_label_fragment_match(text, label)
    text = accessxi.records_of_eminence_normalized_detail_text(text or ''):lower();
    label = accessxi.records_of_eminence_normalized_detail_text(label or ''):lower();
    if (text == '' or label == '' or #text < 8 or #label < 8) then
        return false;
    end
    if (text:find(' ', 1, true) == nil or text:match('%a') == nil) then
        return false;
    end
    if (text:find('skills', 1, true) ~= nil
        or text:find('white mage', 1, true) ~= nil
        or text:find('black mage', 1, true) ~= nil) then
        return false;
    end
    return label:find(text, 1, true) ~= nil;
end

function accessxi.records_of_eminence_normalized_detail_text(text)
    text = accessxi.plain_native_menu_help(text or '');
    if (text == '') then
        return '';
    end
    return text:gsub('%s+', ' '):trim();
end

function accessxi.records_of_eminence_known_display_title(text)
    text = accessxi.records_of_eminence_normalized_detail_text(text);
    if (text == '') then
        return '';
    end

    local lower = text:lower();
    local records = accessxi.records_of_eminence_data.records or T{};
    for _, rec in pairs(records) do
        if (type(rec) == 'table') then
            local label = accessxi.records_of_eminence_normalized_detail_text(rec.label or '');
            if (label ~= '' and lower == label:lower()) then
                return text;
            end
        end
    end
    return '';
end

function accessxi.records_of_eminence_native_detail_group_key(line)
    local group = '';
    if (type(line) == 'table') then
        group = tostring(line.group or line.source or '');
    else
        group = tostring(line or '');
    end
    if (group:match('^obj%+018%+%x%x%x:') ~= nil or group:match('^obj%+018:') ~= nil) then
        return 'obj+018';
    end
    return group;
end

function accessxi.records_of_eminence_native_detail_seed_group(raw_group)
    raw_group = tostring(raw_group or '');
    local prefix, offset_text = raw_group:match('^(obj%+018)%+(%x+):');
    if (prefix == nil) then
        prefix, offset_text = raw_group:match('^(obj%+014)%+(%x+):');
    end
    if (prefix == nil or offset_text == nil) then
        return '', -1;
    end
    return prefix, tonumber(offset_text, 16) or -1;
end

function accessxi.records_of_eminence_native_detail_seed_pair_exists(groups, family, seed_prefix, seed_offset, direction)
    if (type(groups) ~= 'table') then
        return false;
    end
    family = tostring(family or '');
    seed_prefix = tostring(seed_prefix or '');
    seed_offset = tonumber(seed_offset) or -1;
    direction = tostring(direction or '');
    if (family == '' or seed_prefix == '' or seed_offset < 0) then
        return false;
    end

    for _, delta in ipairs(T{ 0x20, 0x28, 0x30 }) do
        local paired_offset = seed_offset;
        if (direction == 'before') then
            paired_offset = seed_offset - delta;
        elseif (direction == 'after') then
            paired_offset = seed_offset + delta;
        else
            return false;
        end
        if (groups[('%s:%s:%d'):fmt(family, seed_prefix, paired_offset)] == true) then
            return true;
        end
    end
    return false;
end

function accessxi.records_of_eminence_native_detail_display_line_index(detail_index, row)
    detail_index = tonumber(detail_index) or 0;
    local selected = type(row) == 'table' and (tonumber(row.selected) or 0) or 0;
    if (selected == 1 and detail_index > selected) then
        return detail_index - selected;
    end
    if (selected > 1 and detail_index > selected) then
        return detail_index - selected + 1;
    end
    return detail_index;
end

function accessxi.records_of_eminence_native_detail_summary_marker(text)
    local lower = accessxi.plain_native_menu_help(text or ''):lower();
    if (lower == '') then
        return false;
    end
    return lower:find('number required', 1, true) ~= nil
        or lower:find('reward', 1, true) ~= nil
        or lower:find('rewards', 1, true) ~= nil
        or lower:find('progress', 1, true) ~= nil
        or lower:find('sparks', 1, true) ~= nil
        or lower:find('accolades', 1, true) ~= nil
        or lower:find(' exp', 1, true) ~= nil
        or lower:find('exp ', 1, true) ~= nil
        or lower:find(' spa', 1, true) ~= nil
        or lower:find('spa ', 1, true) ~= nil
        or lower:find(' acc', 1, true) ~= nil
        or lower:find('acc ', 1, true) ~= nil;
end

function accessxi.records_of_eminence_native_detail_description_marker(text)
    text = accessxi.records_of_eminence_normalized_detail_text(text);
    if (text == '') then
        return false;
    end

    local lower = text:lower();
    if (lower:find('records of eminence', 1, true) ~= nil
        or lower:find('objective list', 1, true) ~= nil
        or lower:find('set objective', 1, true) ~= nil
        or lower:find('cancel objective', 1, true) ~= nil) then
        return false;
    end
    if (accessxi.records_of_eminence_known_display_title(text) ~= '') then
        return false;
    end
    if (#text < 18) then
        return false;
    end

    return lower:find('defeat ', 1, true) ~= nil
        or lower:find('obtain ', 1, true) ~= nil
        or lower:find('speak to ', 1, true) ~= nil
        or lower:find('synthesize ', 1, true) ~= nil
        or lower:find('successfully ', 1, true) ~= nil
        or lower:find('complete ', 1, true) ~= nil
        or lower:find('clear ', 1, true) ~= nil
        or lower:find('use ', 1, true) ~= nil
        or lower:find('deal ', 1, true) ~= nil
        or lower:find('take ', 1, true) ~= nil
        or lower:find('heal ', 1, true) ~= nil
        or lower:find('earn ', 1, true) ~= nil
        or lower:find('participate ', 1, true) ~= nil
        or lower:find('exchange ', 1, true) ~= nil
        or lower:find('vanquish ', 1, true) ~= nil
        or lower:find(' damage', 1, true) ~= nil;
end

function accessxi.records_of_eminence_native_detail_speakable_line(text, label)
    text = accessxi.records_of_eminence_normalized_detail_text(text or '');
    if (text == '') then
        return false;
    end
    if (text:match('[%z\001-\031]') ~= nil
        or text:find('&H', 1, true) ~= nil
        or text:find('checkpoint', 1, true) ~= nil) then
        return false;
    end
    if (text:match('^[%.,;:%)%]]') ~= nil) then
        return false;
    end
    if (text:match('^[a-z]') ~= nil
        and not accessxi.records_of_eminence_native_detail_description_marker(text)
        and not accessxi.records_of_eminence_native_detail_summary_marker(text)) then
        return false;
    end

    if (accessxi.records_of_eminence_detail_label_exact_match(text, label)) then
        return true;
    end
    return accessxi.records_of_eminence_native_detail_description_marker(text)
        or accessxi.records_of_eminence_native_detail_summary_marker(text);
end

function accessxi.records_of_eminence_native_detail_display_anchor_label(lines, fallback_label)
    if (type(lines) ~= 'table') then
        return accessxi.records_of_eminence_normalized_detail_text(fallback_label or ''), '';
    end

    local groups = {};
    local order = T{};
    for _, line in ipairs(lines) do
        if (type(line) == 'table') then
            local group = accessxi.records_of_eminence_native_detail_group_key(line);
            if (groups[group] == nil) then
                groups[group] = {
                    fallback = false,
                    title = '',
                    marker = false,
                    description = false,
                };
                order:append(group);
            end
            local text = tostring(line.text or '');
            if (accessxi.records_of_eminence_detail_label_match(text, fallback_label)
                or accessxi.records_of_eminence_detail_label_fragment_match(text, fallback_label)) then
                groups[group].fallback = true;
            end
            local title = accessxi.records_of_eminence_known_display_title(text);
            if (title ~= '') then
                groups[group].title = title;
            end
            if (accessxi.records_of_eminence_native_detail_summary_marker(text)) then
                groups[group].marker = true;
            end
            if (accessxi.records_of_eminence_native_detail_description_marker(text)) then
                groups[group].description = true;
            end
        end
    end

    local fallback = accessxi.records_of_eminence_normalized_detail_text(fallback_label or '');
    local fallback_lower = fallback:lower();
    local first_fallback = '';
    local fragment_fallback = false;
    local surface = false;
    local summary = T{};
    for _, group in ipairs(order) do
        local state = groups[group];
        if (type(state) == 'table') then
            summary:append(('%s[fallback=%s title="%s" marker=%s description=%s]'):fmt(
                accessxi.escape_probe_log_text(group),
                tostring(state.fallback == true),
                accessxi.escape_probe_log_text(tostring(state.title or '')),
                tostring(state.marker == true),
                tostring(state.description == true)));
            if (state.marker == true or state.description == true) then
                surface = true;
            end
            if (state.fallback == true and fallback ~= '') then
                fragment_fallback = true;
            end
            if (state.marker == true or state.description == true) then
                local title = tostring(state.title or '');
                if (title ~= '') then
                    if (fallback_lower ~= '' and title:lower() == fallback_lower) then
                        if (first_fallback == '') then
                            first_fallback = title;
                        end
                    end
                elseif (state.fallback == true and fallback ~= '' and first_fallback == '') then
                    first_fallback = fallback;
                end
            end
        end
    end
    if (first_fallback ~= '') then
        return first_fallback, summary:concat(' || ');
    end
    if (fragment_fallback == true and surface == true and fallback ~= '') then
        return fallback, summary:concat(' || ');
    end
    return '', summary:concat(' || ');
end

function accessxi.records_of_eminence_native_detail_filter_summary_groups(lines, label)
    if (type(lines) ~= 'table') then
        return T{}, false, '';
    end
    local families = {};
    local family_order = T{};
    local raw_groups = {};
    for _, line in ipairs(lines) do
        if (type(line) == 'table') then
            local raw_group = tostring(line.group or line.source or '');
            local family = accessxi.records_of_eminence_native_detail_group_key(line);
            if (families[family] == nil) then
                families[family] = {
                    label = false,
                    marker = false,
                    description = false,
                };
                family_order:append(family);
            end
            if (raw_groups[raw_group] == nil) then
                local seed_prefix, seed_offset = accessxi.records_of_eminence_native_detail_seed_group(raw_group);
                raw_groups[raw_group] = {
                    label = false,
                    marker = false,
                    description = false,
                    family = family,
                    seed_prefix = seed_prefix,
                    seed_offset = seed_offset,
                };
            end
            local text = tostring(line.text or '');
            if (accessxi.records_of_eminence_detail_label_match(text, label)
                or accessxi.records_of_eminence_detail_label_fragment_match(text, label)) then
                families[family].label = true;
                raw_groups[raw_group].label = true;
            end
            if (accessxi.records_of_eminence_native_detail_summary_marker(text)) then
                families[family].marker = true;
                raw_groups[raw_group].marker = true;
            end
            if (accessxi.records_of_eminence_native_detail_description_marker(text)) then
                families[family].description = true;
                raw_groups[raw_group].description = true;
            end
        end
    end

    local label_seed_groups = {};
    local summary_seed_groups = {};
    for _, state in pairs(raw_groups) do
        if (type(state) == 'table') then
            local seed_prefix = tostring(state.seed_prefix or '');
            local seed_offset = tonumber(state.seed_offset) or -1;
            if (seed_prefix ~= '' and seed_offset >= 0) then
                if (state.label == true) then
                    label_seed_groups[('%s:%s:%d'):fmt(tostring(state.family or ''), seed_prefix, seed_offset)] = true;
                end
                if (state.marker == true or state.description == true) then
                    summary_seed_groups[('%s:%s:%d'):fmt(tostring(state.family or ''), seed_prefix, seed_offset)] = true;
                end
            end
        end
    end

    local has_label_family = false;
    local has_summary_family = false;
    local allowed_families = {};
    for _, family in ipairs(family_order) do
        local state = families[family];
        if (type(state) == 'table') then
            if (state.label == true) then
                has_label_family = true;
            end
            if (state.marker == true or state.description == true) then
                has_summary_family = true;
            end
            if (state.label == true and (state.marker == true or state.description == true)) then
                allowed_families[family] = true;
            end
        end
    end
    if (has_label_family == true and has_summary_family == true) then
        for _, family in ipairs(family_order) do
            local state = families[family];
            if (family == 'window-shapes' and type(state) == 'table' and (state.marker == true or state.description == true)) then
                allowed_families[family] = true;
            end
        end
    end

    local filtered = T{};
    for _, line in ipairs(lines) do
        if (type(line) == 'table') then
            local raw_group = tostring(line.group or line.source or '');
            local state = raw_groups[raw_group];
            local family = type(state) == 'table' and tostring(state.family or '') or accessxi.records_of_eminence_native_detail_group_key(line);
            if (allowed_families[family] == true) then
                local text = tostring(line.text or '');
                local raw_has_label = type(state) == 'table' and state.label == true;
                local raw_has_summary = type(state) == 'table' and (state.marker == true or state.description == true);
                local same_raw_summary = raw_has_label == true and raw_has_summary == true;
                local shape_summary = raw_group == 'window-shapes' and raw_has_summary == true and has_label_family == true;
                local paired_seed_summary = false;
                local paired_seed_label = false;
                if (type(state) == 'table') then
                    local seed_prefix = tostring(state.seed_prefix or '');
                    local seed_offset = tonumber(state.seed_offset) or -1;
                    if (seed_prefix ~= '' and seed_offset >= 0) then
                        if (seed_prefix ~= 'obj+018') then
                            paired_seed_summary = raw_has_summary == true
                                and accessxi.records_of_eminence_native_detail_seed_pair_exists(
                                    label_seed_groups, family, seed_prefix, seed_offset, 'before');
                            paired_seed_label = raw_has_label == true
                                and accessxi.records_of_eminence_native_detail_seed_pair_exists(
                                    summary_seed_groups, family, seed_prefix, seed_offset, 'after');
                        end
                    end
                end
                if ((same_raw_summary == true or shape_summary == true or paired_seed_summary == true or paired_seed_label == true)
                    and accessxi.records_of_eminence_native_detail_speakable_line(text, label)) then
                    filtered:append(line);
                end
            end
        end
    end

    local summary = T{};
    for _, group in ipairs(family_order) do
        local state = families[group];
        if (type(state) == 'table') then
            summary:append(('%s[label=%s marker=%s description=%s]'):fmt(
                accessxi.escape_probe_log_text(group),
                tostring(state.label == true),
                tostring(state.marker == true),
                tostring(state.description == true)));
        end
    end
    return filtered, #filtered > 0, summary:concat(' || ');
end

function accessxi.records_of_eminence_native_detail_candidate_summary(lines, limit)
    if (type(lines) ~= 'table') then
        return '';
    end
    limit = tonumber(limit) or 10;
    local parts = T{};
    for i, line in ipairs(lines) do
        if (i > limit) then
            parts:append(('...+%d'):fmt(#lines - limit));
            break;
        end
        if (type(line) == 'table') then
            parts:append(('%s+%03X="%s"'):fmt(
                tostring(line.source or ''),
                tonumber(line.offset) or 0,
                accessxi.escape_probe_log_text(tostring(line.text or ''))));
        else
            parts:append(accessxi.escape_probe_log_text(tostring(line or '')));
        end
    end
    return parts:concat(' || ');
end

function accessxi.records_of_eminence_append_target_help_line(lines, seen, text, source)
    if (type(lines) ~= 'table' or type(seen) ~= 'table') then
        return;
    end
    text = accessxi.plain_native_menu_help(text or '');
    if (text == '' or #text < 2 or #text > 260) then
        return;
    end
    local key = text:lower();
    if (seen[key] == true) then
        return;
    end
    seen[key] = true;
    lines:append({
        text = text,
        source = tostring(source or 'target-help'),
        group = 'target-help',
        offset = 0,
    });
end

function accessxi.records_of_eminence_append_target_help_chunks(lines, seen, text, source)
    text = accessxi.plain_native_menu_help(text or '');
    if (text == '') then
        return;
    end

    local emitted = false;
    local start_index = 1;
    while (start_index <= #text) do
        local stop_index = text:find('%.%s+', start_index);
        local part = nil;
        if (stop_index ~= nil) then
            part = text:sub(start_index, stop_index);
            start_index = stop_index + 2;
        else
            part = text:sub(start_index);
            start_index = #text + 1;
        end
        part = tostring(part or ''):trim();
        if (part ~= '') then
            emitted = true;
            while (#part > 240) do
                local cut = 220;
                for i = 220, 120, -1 do
                    if (part:sub(i, i) == ' ') then
                        cut = i;
                        break;
                    end
                end
                accessxi.records_of_eminence_append_target_help_line(lines, seen, part:sub(1, cut):trim(), source);
                part = part:sub(cut + 1):trim();
            end
            accessxi.records_of_eminence_append_target_help_line(lines, seen, part, source);
        end
    end

    if (not emitted) then
        accessxi.records_of_eminence_append_target_help_line(lines, seen, text, source);
    end
end

function accessxi.records_of_eminence_target_help_detail_surface(label)
    label = tostring(label or '');
    local target = AshitaCore:GetMemoryManager():GetTarget();
    if (target == nil) then
        return {
            lines = T{},
            matched = false,
            summary = 'target=nil',
        };
    end

    local help_string_ptr = safe_call(function () return target:GetWindowHelpString(); end, 0);
    local help_title_ptr = safe_call(function () return target:GetWindowHelpTitle(); end, 0);
    local window_name = clean_probe_text(safe_call(function () return target:GetWindowName(); end, ''));
    local help_title = accessxi.plain_native_menu_help(read_probe_string(help_title_ptr, 260));
    local help_string = accessxi.plain_native_menu_help(read_probe_string(help_string_ptr, 512));
    local title_matches = accessxi.records_of_eminence_detail_label_match(help_title, label);

    local lines = T{};
    local seen = {};
    if (title_matches and help_string ~= '') then
        accessxi.records_of_eminence_append_target_help_line(lines, seen, help_title, 'target-help-title');
        accessxi.records_of_eminence_append_target_help_chunks(lines, seen, help_string, 'target-help-string');
    end

    return {
        lines = lines,
        matched = title_matches and #lines > 1,
        title_ptr = tonumber(help_title_ptr) or 0,
        help_ptr = tonumber(help_string_ptr) or 0,
        title = help_title,
        help = help_string,
        window_name = window_name,
        summary = ('win="%s" helpTitlePtr=0x%08X helpTitle="%s" helpPtr=0x%08X help="%s" matched=%s lines=%d'):fmt(
            accessxi.escape_probe_log_text(window_name),
            tonumber(help_title_ptr) or 0,
            accessxi.escape_probe_log_text(help_title),
            tonumber(help_string_ptr) or 0,
            accessxi.escape_probe_log_text(help_string),
            tostring(title_matches == true),
            #lines),
    };
end

function accessxi.records_of_eminence_seed_native_summary_lines(label, seed_offset, seed_name, scan_limit)
    label = tostring(label or '');
    local obj = get_current_menu_object_ptr();
    if (not accessxi.is_probe_pointer(obj)) then
        return {
            lines = T{},
            matched = false,
            summary = 'obj=nil',
        };
    end

    seed_offset = tonumber(seed_offset) or 0;
    seed_name = tostring(seed_name or ('obj+%03X'):fmt(seed_offset));
    scan_limit = tonumber(scan_limit) or 0x240;
    local seed = read_u32(obj + seed_offset) or 0;
    if (not accessxi.is_probe_pointer(seed)) then
        return {
            lines = T{},
            matched = false,
            summary = ('%s=0x%08X'):fmt(seed_name, tonumber(seed) or 0),
        };
    end

    local target_seen = {};
    for off = 0x00, scan_limit, 4 do
        local target = read_u32(seed + off) or 0;
        if (accessxi.is_probe_pointer(target) and target_seen[target] ~= true) then
            target_seen[target] = true;
            local source = ('%s+%03X'):fmt(seed_name, off);
            local raw_lines = T{};
            local raw_seen = {};
            accessxi.records_of_eminence_collect_native_detail_runs_from_ptr(raw_lines, raw_seen, target, 0x700, 96, source);

            local title = '';
            local has_summary = false;
            for _, line in ipairs(raw_lines) do
                if (type(line) == 'table') then
                    local text = accessxi.records_of_eminence_normalized_detail_text(line.text or '');
                    if (title == '' and accessxi.records_of_eminence_detail_label_token_match(text, label)) then
                        title = text;
                    elseif (accessxi.records_of_eminence_native_detail_description_marker(text)
                        or accessxi.records_of_eminence_native_detail_summary_marker(text)) then
                        has_summary = true;
                    end
                end
            end

            if (title ~= '' and has_summary == true) then
                local lines = T{};
                local seen = {};
                accessxi.records_of_eminence_append_target_help_line(lines, seen, title, source .. ':title');
                for _, line in ipairs(raw_lines) do
                    if (type(line) == 'table') then
                        local text = accessxi.records_of_eminence_normalized_detail_text(line.text or '');
                        local known_title = accessxi.records_of_eminence_known_display_title(text);
                        if (text ~= ''
                            and known_title == ''
                            and not accessxi.records_of_eminence_detail_label_token_match(text, label)
                            and (accessxi.records_of_eminence_native_detail_description_marker(text)
                                or accessxi.records_of_eminence_native_detail_summary_marker(text))) then
                            accessxi.records_of_eminence_append_target_help_chunks(lines, seen, text, tostring(line.source or source));
                        end
                    end
                end
                if (#lines > 1) then
                    return {
                        lines = lines,
                        matched = true,
                        source = source,
                        target = target,
                        summary = accessxi.records_of_eminence_native_detail_candidate_summary(raw_lines, 16),
                    };
                end
            end
        end
    end

    return {
        lines = T{},
        matched = false,
        summary = ('%s=0x%08X no matched summary'):fmt(seed_name, tonumber(seed) or 0),
    };
end

function accessxi.records_of_eminence_obj014_native_summary_lines(label)
    return accessxi.records_of_eminence_seed_native_summary_lines(label, 0x14, 'obj+014', 0x700);
end

function accessxi.records_of_eminence_obj018_native_summary_lines(label)
    return accessxi.records_of_eminence_seed_native_summary_lines(label, 0x18, 'obj+018', 0x700);
end

function accessxi.records_of_eminence_current_entry_native_detail_lines(label)
    label = tostring(label or '');
    local obj = get_current_menu_object_ptr();
    if (not accessxi.is_probe_pointer(obj)) then
        return {
            lines = T{},
            matched = false,
            summary = 'obj=nil',
        };
    end

    local entry = read_u32(obj + 0x08) or 0;
    if (not accessxi.is_probe_pointer(entry)) then
        return {
            lines = T{},
            matched = false,
            summary = ('entry=0x%08X'):fmt(tonumber(entry) or 0),
        };
    end

    local raw_lines = T{};
    local raw_seen = {};
    local ptr_seen = {};
    local function collect(ptr, source, length)
        ptr = tonumber(ptr) or 0;
        if (not accessxi.is_probe_pointer(ptr) or ptr_seen[ptr] == true) then
            return;
        end
        ptr_seen[ptr] = true;
        accessxi.records_of_eminence_collect_native_detail_runs_from_ptr(raw_lines, raw_seen, ptr, tonumber(length) or 0x340, 36, source);
    end

    collect(entry, 'entry', 0x240);
    for off = 0x00, 0x90, 4 do
        local ptr = read_u32(entry + off) or 0;
        collect(ptr, ('entry+%03X'):fmt(off), 0x340);
    end

    local groups = {};
    local order = T{};
    for _, line in ipairs(raw_lines) do
        if (type(line) == 'table') then
            local group = tostring(line.group or line.source or '');
            if (groups[group] == nil) then
                groups[group] = {
                    lines = T{},
                    other_title = false,
                    has_detail = false,
                };
                order:append(group);
            end
            local state = groups[group];
            local text = accessxi.records_of_eminence_normalized_detail_text(line.text or '');
            local known_title = accessxi.records_of_eminence_known_display_title(text);
            if (known_title ~= '' and not accessxi.records_of_eminence_detail_label_match(known_title, label)) then
                state.other_title = true;
            end
            if (text ~= ''
                and known_title == ''
                and not accessxi.records_of_eminence_detail_label_match(text, label)
                and (accessxi.records_of_eminence_native_detail_description_marker(text)
                    or accessxi.records_of_eminence_native_detail_summary_marker(text))) then
                state.has_detail = true;
                state.lines:append({
                    text = text,
                    source = tostring(line.source or group),
                    group = group,
                    offset = tonumber(line.offset) or 0,
                });
            end
        end
    end

    local lines = T{};
    local seen = {};
    local source = '';
    for _, group in ipairs(order) do
        local state = groups[group];
        if (type(state) == 'table' and state.has_detail == true and state.other_title ~= true) then
            source = group;
            for _, line in ipairs(state.lines) do
                accessxi.records_of_eminence_append_target_help_chunks(lines, seen, tostring(line.text or ''), tostring(line.source or group));
            end
            if (#lines > 0) then
                break;
            end
        end
    end

    return {
        lines = lines,
        matched = #lines > 0,
        source = source,
        target = entry,
        summary = accessxi.records_of_eminence_native_detail_candidate_summary(raw_lines, 18),
    };
end

function accessxi.records_of_eminence_obj0f0_native_summary_lines(label)
    label = tostring(label or '');
    local obj = get_current_menu_object_ptr();
    if (not accessxi.is_probe_pointer(obj)) then
        return {
            lines = T{},
            matched = false,
            summary = 'obj=nil',
        };
    end

    local target = read_u32(obj + 0xF0) or 0;
    if (not accessxi.is_probe_pointer(target)) then
        return {
            lines = T{},
            matched = false,
            summary = ('obj+0F0=0x%08X'):fmt(tonumber(target) or 0),
        };
    end

    local raw_lines = T{};
    local raw_seen = {};
    accessxi.records_of_eminence_collect_native_detail_runs_from_ptr(raw_lines, raw_seen, target, 0x700, 64, 'obj+0F0');

    local lines = T{};
    local seen = {};
    for _, line in ipairs(raw_lines) do
        if (type(line) == 'table') then
            local text = accessxi.records_of_eminence_normalized_detail_text(line.text or '');
            local known_title = accessxi.records_of_eminence_known_display_title(text);
            if (text ~= ''
                and known_title == ''
                and not accessxi.records_of_eminence_detail_label_match(text, label)
                and (accessxi.records_of_eminence_native_detail_description_marker(text)
                    or accessxi.records_of_eminence_native_detail_summary_marker(text))) then
                accessxi.records_of_eminence_append_target_help_chunks(lines, seen, text, tostring(line.source or 'obj+0F0'));
            end
        end
    end

    return {
        lines = lines,
        matched = #lines > 0,
        source = 'obj+0F0',
        target = target,
        summary = accessxi.records_of_eminence_native_detail_candidate_summary(raw_lines, 16),
    };
end

function accessxi.records_of_eminence_collect_native_detail_buffer_lines(obj, label)
    obj = tonumber(obj) or 0;
    local lines = T{};
    local text_seen = {};
    local ptr_seen = {};
    local anchor_found = false;
    label = tostring(label or '');

    local function collect(ptr, source)
        ptr = tonumber(ptr) or 0;
        if (not accessxi.is_probe_pointer(ptr) or ptr_seen[ptr] == true) then
            return;
        end
        ptr_seen[ptr] = true;
        local before = #lines;
        accessxi.records_of_eminence_collect_native_detail_runs_from_ptr(lines, text_seen, ptr, 0x340, 40, source);
        for i = before + 1, #lines do
            local line = lines[i];
            if (type(line) == 'table' and accessxi.records_of_eminence_detail_label_match(line.text, label)) then
                anchor_found = true;
            end
        end
    end

    local function collect_field(owner, off, source)
        owner = tonumber(owner) or 0;
        if (not accessxi.is_probe_pointer(owner)) then
            return;
        end
        collect(read_u32(owner + off) or 0, ('%s+%03X'):fmt(tostring(source or 'ptr'), tonumber(off) or 0));
    end

    for _, off in ipairs(T{ 0x08, 0x0C, 0x10, 0x14, 0x18, 0x20, 0x24, 0x28, 0x30, 0x34, 0x40, 0x44, 0x4C, 0x50, 0x58, 0x64, 0x80, 0x84, 0x88, 0xA0, 0xA4, 0xA8 }) do
        collect_field(obj, off, 'obj');
    end

    local seed = read_u32(obj + 0x18) or 0;
    if (accessxi.is_probe_pointer(seed)) then
        for off = 0x00, 0x120, 4 do
            collect_field(seed, off, 'obj+018');
        end
    end

    return lines, anchor_found;
end

function accessxi.records_of_eminence_native_detail_shape_candidate(text)
    text = accessxi.plain_native_menu_help(text or '');
    if (text == '' or #text < 4 or #text > 260) then
        return '';
    end
    if (text:match('%a') == nil or text:match('^[%p%s%d]+$') ~= nil) then
        return '';
    end

    local lower = text:lower();
    if (lower:find('menu    ', 1, true) ~= nil
        or lower:find('keytops', 1, true) ~= nil
        or lower:find('ssxi_reader', 1, true) ~= nil
        or lower:find('accessxi_reader', 1, true) ~= nil
        or lower:find('misc    ws', 1, true) ~= nil
        or lower:find('controller', 1, true) ~= nil) then
        return '';
    end

    return text;
end

function accessxi.records_of_eminence_collect_native_detail_shape_lines(label)
    local target = safe_call(function () return AshitaCore:GetMemoryManager():GetTarget(); end, nil);
    local lines = T{};
    local summaries = T{};
    if (target == nil) then
        return lines, false, 'target=nil';
    end

    local ank_num = tonumber(safe_call(function () return target:GetWindowAnkNum(); end, -1)) or -1;
    local ank_x = tonumber(safe_call(function () return target:GetWindowAnkX(); end, -1)) or -1;
    local ank_y = tonumber(safe_call(function () return target:GetWindowAnkY(); end, -1)) or -1;
    local shape_limit = math.min(15, math.max(4, ank_num + 4));
    local text_seen = {};
    local ptr_seen = {};
    local anchor_found = false;

    local function add_line(text, source, offset)
        text = accessxi.records_of_eminence_native_detail_shape_candidate(text);
        if (text == '') then
            return;
        end
        local key = text:lower();
        if (text_seen[key] == true) then
            return;
        end
        text_seen[key] = true;
        if (accessxi.records_of_eminence_detail_label_match(text, label)) then
            anchor_found = true;
        end
        lines:append({
            text = text,
            source = tostring(source or 'shape'),
            group = 'window-shapes',
            offset = tonumber(offset) or 0,
        });
    end

    local function collect_runs(ptr, source, length)
        ptr = tonumber(ptr) or 0;
        if (not accessxi.is_probe_pointer(ptr) or ptr_seen[ptr] == true) then
            return;
        end
        ptr_seen[ptr] = true;
        source = tostring(source or 'shape');
        length = tonumber(length) or 0x260;

        add_line(read_probe_string(ptr, 260), source .. ':direct', 0);
        for _, run in ipairs(accessxi.collect_probe_ascii_runs(ptr, length, 4, 28)) do
            local off, text = accessxi.records_of_eminence_parse_probe_run(run);
            add_line(text, source .. ':ascii', off);
        end
        for _, run in ipairs(accessxi.collect_probe_utf16_runs(ptr, length, 3, 28)) do
            local off, text = accessxi.records_of_eminence_parse_probe_run(run);
            add_line(text, source .. ':utf16', off);
        end
        for _, run in ipairs(accessxi.collect_probe_ffxi_utf16_runs(ptr, length, 3, 28)) do
            local off, text = accessxi.records_of_eminence_parse_probe_run(run);
            add_line(text, source .. ':ffxi', off);
        end
    end

    for i = 0, shape_limit do
        local shape = tonumber(safe_call(function () return target:GetWindowAnkShape(i); end, 0)) or 0;
        if (accessxi.is_probe_pointer(shape)) then
            local before = #lines;
            collect_runs(shape, ('shape%d'):fmt(i), 0x300);
            for off = 0, 0x100, 4 do
                local ptr = read_u32(shape + off) or 0;
                if (accessxi.is_probe_pointer(ptr)) then
                    collect_runs(ptr, ('shape%d+%03X'):fmt(i, off), 0x260);
                end
            end
            local added = #lines - before;
            summaries:append(('%d=0x%08X added=%d runs="%s"'):fmt(
                i,
                shape,
                added,
                accessxi.escape_probe_log_text_wide(accessxi.status_menu_probe_runs(shape, 0x180))));
        elseif (shape ~= 0) then
            summaries:append(('%d=0x%08X'):fmt(i, shape));
        end
    end

    return lines, anchor_found, ('ankNum=%d ank=(%d,%d) lines=%d shapes=%s'):fmt(
        ank_num,
        ank_x,
        ank_y,
        #lines,
        summaries:concat(' || '));
end

function accessxi.log_records_of_eminence_text_candidates(seq, seed_label, ptr, record_id, selected, label, reason, native_pos, limit)
    ptr = tonumber(ptr) or 0;
    if (not accessxi.is_probe_pointer(ptr)) then
        return;
    end

    limit = tonumber(limit) or 12;
    local seen = {};
    local logged = 0;
    for off = 0x00, 0x140, 4 do
        if (logged >= limit) then
            return;
        end

        local target = read_u32(ptr + off);
        if (target ~= nil and accessxi.is_probe_pointer(target) and seen[target] ~= true) then
            seen[target] = true;
            local strings = accessxi.probe_strings_at(target);
            local ascii = accessxi.collect_probe_ascii_runs(target, 0x300, 3, 10);
            local utf16 = accessxi.collect_probe_utf16_runs(target, 0x300, 3, 10);
            local ffxi = accessxi.collect_probe_ffxi_utf16_runs(target, 0x300, 3, 10);
            if (strings ~= '' or #ascii > 0 or #utf16 > 0 or #ffxi > 0) then
                logged = logged + 1;
                log_state(('state records-of-eminence text-candidate seq=%d recordId=%d selected=%d label="%s" reason="%s" seed="%s" owner=0x%08X off=0x%03X target=0x%08X nativePos="%s" strings="%s" ascii="%s" utf16="%s" ffxi="%s"'):fmt(
                    tonumber(seq) or 0,
                    tonumber(record_id) or 0,
                    tonumber(selected) or 0,
                    accessxi.escape_probe_log_text(label),
                    accessxi.escape_probe_log_text(reason),
                    accessxi.escape_probe_log_text(seed_label),
                    ptr,
                    off,
                    target,
                    accessxi.escape_probe_log_text(native_pos),
                    accessxi.escape_probe_log_text_wide(strings),
                    accessxi.escape_probe_log_text_wide(ascii:concat(' ')),
                    accessxi.escape_probe_log_text_wide(utf16:concat(' ')),
                    accessxi.escape_probe_log_text_wide(ffxi:concat(' '))));
                if (accessxi.records_of_eminence_text_buffer_probe_should_log(seed_label, off, target, label)) then
                    accessxi.log_records_of_eminence_text_buffer_slots(seq, seed_label, ptr, off, target, record_id, selected, label, reason, native_pos);
                end
            end
        end
    end
end

function accessxi.log_records_of_eminence_text_probe(menu_name, row, record, reason, native_pos, force)
    local now = tick();
    force = force == true;
    if (not force and (tonumber(accessxi.records_of_eminence_text_probe_until) or 0) < now) then
        return;
    end
    if (not force and (tonumber(accessxi.records_of_eminence_text_probe_count) or 0) >= (tonumber(accessxi.records_of_eminence_text_probe_limit) or 24)) then
        return;
    end
    if (type(row) ~= 'table' or type(record) ~= 'table') then
        return;
    end

    menu_name = tostring(menu_name or '');
    reason = tostring(reason or '');
    native_pos = tostring(native_pos or '');

    local obj = get_current_menu_object_ptr();
    local target = AshitaCore:GetMemoryManager():GetTarget();
    local ank_num = target ~= nil and (tonumber(safe_call(function () return target:GetWindowAnkNum(); end, -1)) or -1) or -1;
    local sub = target ~= nil and (tonumber(safe_call(function () return target:GetWindowSub(); end, -1)) or -1) or -1;
    local record_id = tonumber(row.record_id) or 0;
    local selected = tonumber(row.selected) or 0;
    local label = tostring(row.label or record.label or '');
    local key = ('%s:%s:0x%08X:%d:%d:%d:%s'):fmt(
        menu_name,
        reason,
        obj,
        record_id,
        selected,
        ank_num,
        native_pos);
    if (key == tostring(accessxi.last_records_of_eminence_text_probe_key or '')) then
        return;
    end
    accessxi.last_records_of_eminence_text_probe_key = key;
    accessxi.records_of_eminence_text_probe_count = (tonumber(accessxi.records_of_eminence_text_probe_count) or 0) + 1;

    accessxi.menu_dump_sequence = (accessxi.menu_dump_sequence or 0) + 1;
    local seq = accessxi.menu_dump_sequence;
    local old_textptr_budget = accessxi.menu_dump_textptr_budget;
    accessxi.menu_dump_textptr_budget = 56;

    log_state(('state records-of-eminence text-probe seq=%d reason="%s" menu="%s" recordId=%d selected=%d label="%s" obj=0x%08X ank=%d sub=%d nativePos="%s" sample=%d until=%d'):fmt(
        seq,
        accessxi.escape_probe_log_text(reason),
        menu_name,
        record_id,
        selected,
        accessxi.escape_probe_log_text(label),
        obj,
        ank_num,
        sub,
        accessxi.escape_probe_log_text(native_pos),
        tonumber(accessxi.records_of_eminence_text_probe_count) or 0,
        tonumber(accessxi.records_of_eminence_text_probe_until) or 0));

    local seeds = T{};
    local seen = {};
    local function add_seed(seed_label, ptr)
        ptr = tonumber(ptr) or 0;
        if (not accessxi.is_probe_pointer(ptr) or seen[ptr] == true or seeds:len() >= 24) then
            return;
        end
        seen[ptr] = true;
        seeds:append(T{ label = tostring(seed_label or ''), ptr = ptr });
    end
    local function add_field(owner_label, owner, off)
        owner = tonumber(owner) or 0;
        if (not accessxi.is_probe_pointer(owner)) then
            return;
        end
        add_seed(('%s+%03X'):fmt(owner_label, off), read_u32(owner + off) or 0);
    end

    add_seed('obj', obj);
    for _, off in ipairs(T{ 0x08, 0x0C, 0x10, 0x14, 0x18, 0x20, 0x24, 0x28, 0x30, 0x34, 0x40, 0x44, 0x4C, 0x50, 0x58, 0x64, 0x80, 0x84, 0x88, 0xA0, 0xA4, 0xA8 }) do
        add_field('obj', obj, off);
    end
    log_line(('menudump seq=%d roetext begin seeds=%d recordId=%d selected=%d label="%s" reason="%s"'):fmt(
        seq,
        seeds:len(),
        record_id,
        selected,
        accessxi.escape_probe_log_text(label),
        accessxi.escape_probe_log_text(reason)));

    for _, seed in ipairs(seeds) do
        local seed_label = 'roetext.' .. tostring(seed.label or '');
        local ptr = tonumber(seed.ptr) or 0;
        log_line(('menudump seq=%d %s ptr=0x%08X dwords=%s strings="%s"'):fmt(
            seq,
            seed_label,
            ptr,
            accessxi.format_probe_dwords(ptr, 0, 20),
            accessxi.escape_probe_log_text(accessxi.probe_strings_at(ptr))));
        accessxi.log_probe_short_text_runs(seq, seed_label, ptr, 0x280, 2, 16);
        accessxi.log_probe_pointer_text_targets(seq, seed_label, ptr, 0x00, 0x140, 14);
        if (seed.label == 'obj' or seed.label == 'obj+00C' or seed.label == 'obj+014' or seed.label == 'obj+018') then
            accessxi.log_records_of_eminence_text_candidates(seq, seed_label, ptr, record_id, selected, label, reason, native_pos, 16);
        end
    end

    accessxi.menu_dump_textptr_budget = old_textptr_budget;
    log_line(('menudump seq=%d roetext end samples=%d'):fmt(seq, tonumber(accessxi.records_of_eminence_text_probe_count) or 0));
end

function accessxi.records_of_eminence_detail_probe_needles(row, record)
    local needles = T{};
    local seen = {};
    local function add(text)
        text = tostring(text or ''):lower():gsub('%s+', ' '):trim();
        if (text == '' or seen[text] == true) then
            return;
        end
        seen[text] = true;
        needles:append(text);
    end

    add('number required');
    add('rewards');
    add('sparks');
    add('experience');
    add('accolades');
    add('progress');
    local function records_of_eminence_detail_probe_add_number(value)
        value = tonumber(value) or 0;
        if (value <= 0) then
            return;
        end
        add(tostring(value));
    end
    records_of_eminence_detail_probe_add_number(row ~= nil and row.record_id or 0);
    records_of_eminence_detail_probe_add_number(row ~= nil and row.progress or 0);
    records_of_eminence_detail_probe_add_number(row ~= nil and row.goal or 0);
    add(record ~= nil and record.label or '');
    add(record ~= nil and record.description or '');

    local label = tostring(record ~= nil and record.label or row ~= nil and row.label or '');
    local description = tostring(record ~= nil and record.description or '');
    for word in (label .. ' ' .. description):gmatch('[%w][%w%.\'%-]+') do
        word = tostring(word or ''):lower();
        if (#word >= 4) then
            add(word);
        end
        if (needles:len() >= 28) then
            break;
        end
    end

    return needles;
end

function accessxi.records_of_eminence_detail_probe_matches(text, needles)
    text = tostring(text or ''):lower();
    if (text == '' or type(needles) ~= 'table') then
        return '';
    end
    local matches = T{};
    local seen = {};
    for _, needle in ipairs(needles) do
        needle = tostring(needle or '');
        if (needle ~= '' and seen[needle] ~= true and text:find(needle, 1, true) ~= nil) then
            seen[needle] = true;
            matches:append(needle);
            if (matches:len() >= 10) then
                break;
            end
        end
    end
    return matches:concat(',');
end

function accessxi.records_of_eminence_detail_probe_pointer_value_ascii(ptr)
    ptr = tonumber(ptr) or 0;
    local printable = 0;
    local alpha = 0;
    for shift = 0, 24, 8 do
        local b = bit.band(bit.rshift(ptr, shift), 0xFF);
        if (b >= 0x20 and b <= 0x7E) then
            printable = printable + 1;
            if ((b >= 0x41 and b <= 0x5A) or (b >= 0x61 and b <= 0x7A)) then
                alpha = alpha + 1;
            end
        end
    end
    return printable == 4 and alpha >= 2;
end

function accessxi.records_of_eminence_detail_probe_pointer_allowed(ptr)
    ptr = tonumber(ptr) or 0;
    if (not accessxi.is_probe_pointer(ptr)) then
        return false;
    end
    if (accessxi.records_of_eminence_detail_probe_pointer_value_ascii(ptr)) then
        return false;
    end

    local mbi = ffi.new('MEMORY_BASIC_INFORMATION[1]');
    local mbi_size = ffi.sizeof('MEMORY_BASIC_INFORMATION');
    local ok, queried = pcall(function ()
        return kernel32.VirtualQuery(ffi.cast('const void*', ptr), mbi, mbi_size);
    end);
    if (not ok or (tonumber(queried) or 0) == 0) then
        return false;
    end

    local state = tonumber(mbi[0].State) or 0;
    local protect = tonumber(mbi[0].Protect) or 0;
    if (state ~= 0x1000 or not accessxi.memory_page_readable(protect)) then
        return false;
    end
    if (accessxi.memory_page_executable(protect)) then
        return false;
    end

    return true;
end

function accessxi.records_of_eminence_detail_probe_text_useful(strings, runs)
    local text = (tostring(strings or '') .. ' ' .. tostring(runs or '')):lower();
    return text:find('%a%a%a%a') ~= nil;
end

function accessxi.records_of_eminence_detail_probe_add_ptr(nodes, seen, ptr, source, depth)
    ptr = tonumber(ptr) or 0;
    if (not accessxi.records_of_eminence_detail_probe_pointer_allowed(ptr) or seen[ptr] == true or nodes:len() >= 96) then
        return;
    end
    seen[ptr] = true;
    nodes:append({
        ptr = ptr,
        source = tostring(source or ''),
        depth = tonumber(depth) or 0,
    });
end

function accessxi.log_records_of_eminence_detail_deep_probe(menu_name, row, record, reason, native_pos, force)
    local now = tick();
    force = force == true;
    if (not force and (tonumber(accessxi.records_of_eminence_detail_probe_until) or 0) < now) then
        return;
    end
    if (not force and (tonumber(accessxi.records_of_eminence_detail_probe_count) or 0) >= (tonumber(accessxi.records_of_eminence_detail_probe_limit) or 16)) then
        return;
    end
    if (type(row) ~= 'table' or type(record) ~= 'table') then
        return;
    end

    menu_name = tostring(menu_name or '');
    reason = tostring(reason or '');
    native_pos = tostring(native_pos or '');
    local obj = get_current_menu_object_ptr();
    local record_id = tonumber(row.record_id) or 0;
    local selected = tonumber(row.selected) or 0;
    local label = tostring(row.label or record.label or '');
    local native_pos_key = native_pos:gsub('%s+', ' ');
    local key = ('%s:%s:0x%08X:%d:%d:%s'):fmt(menu_name, reason, obj, record_id, selected, native_pos_key);
    if (key == tostring(accessxi.last_records_of_eminence_detail_probe_key or '')) then
        return;
    end
    accessxi.last_records_of_eminence_detail_probe_key = key;
    accessxi.records_of_eminence_detail_probe_count = (tonumber(accessxi.records_of_eminence_detail_probe_count) or 0) + 1;

    accessxi.menu_dump_sequence = (accessxi.menu_dump_sequence or 0) + 1;
    local seq = accessxi.menu_dump_sequence;
    local needles = accessxi.records_of_eminence_detail_probe_needles(row, record);
    local nodes = T{};
    local seen = {};
    accessxi.records_of_eminence_detail_probe_add_ptr(nodes, seen, obj, 'obj', 0);
    for _, off in ipairs(T{ 0x08, 0x0C, 0x10, 0x14, 0x18, 0x20, 0x24, 0x28, 0x30, 0x34, 0x3C, 0x40, 0x44, 0x48, 0x4C, 0x50, 0x54, 0x58, 0x5C, 0x60, 0x64, 0x68, 0x6C, 0x70, 0x78, 0x80, 0x84, 0x88, 0x8C, 0x90, 0x94, 0x98, 0x9C, 0xA0, 0xA4, 0xA8, 0xAC, 0xB0, 0xB4, 0xB8, 0xBC, 0xC0 }) do
        accessxi.records_of_eminence_detail_probe_add_ptr(nodes, seen, read_u32(obj + off) or 0, ('obj+%03X'):fmt(off), 1);
    end

    local index = 1;
    while (index <= nodes:len() and nodes:len() < 96) do
        local node = nodes[index];
        local ptr = tonumber(node.ptr) or 0;
        local depth = tonumber(node.depth) or 0;
        if (depth < 2) then
            for off = 0, 0x100, 4 do
                accessxi.records_of_eminence_detail_probe_add_ptr(nodes, seen, read_u32(ptr + off) or 0, ('%s+%03X'):fmt(tostring(node.source or ''), off), depth + 1);
                if (nodes:len() >= 96) then
                    break;
                end
            end
        end
        index = index + 1;
    end

    local detail_index = tonumber(select(2, accessxi.records_of_eminence_detail_position_signature(menu_name, reason))) or 0;
    log_state(('state records-of-eminence detail-deep-probe seq=%d menu="%s" reason="%s" recordId=%d selected=%d detailIndex=%d label="%s" obj=0x%08X nodes=%d nativePos="%s" needles="%s"'):fmt(
        seq,
        menu_name,
        accessxi.escape_probe_log_text(reason),
        record_id,
        selected,
        detail_index,
        accessxi.escape_probe_log_text(label),
        obj,
        nodes:len(),
        accessxi.escape_probe_log_text(native_pos),
        accessxi.escape_probe_log_text(needles:concat(','))));

    local logged = 0;
    for _, node in ipairs(nodes) do
        if (logged >= 48) then
            break;
        end
        local ptr = tonumber(node.ptr) or 0;
        local strings = accessxi.probe_strings_at(ptr);
        local runs = accessxi.status_menu_probe_runs(ptr, 0x220);
        local combined = strings .. ' ' .. runs;
        local matches = accessxi.records_of_eminence_detail_probe_matches(combined, needles);
        if (matches ~= '' or accessxi.records_of_eminence_detail_probe_text_useful(strings, runs) or tonumber(node.depth) == 0) then
            logged = logged + 1;
            log_state(('state records-of-eminence detail-deep-node seq=%d recordId=%d selected=%d detailIndex=%d source="%s" depth=%d ptr=0x%08X match="%s" dwords="%s" strings="%s" runs="%s" bytes="%s"'):fmt(
                seq,
                record_id,
                selected,
                detail_index,
                accessxi.escape_probe_log_text(tostring(node.source or '')),
                tonumber(node.depth) or 0,
                ptr,
                accessxi.escape_probe_log_text(matches),
                accessxi.escape_probe_log_text(accessxi.format_probe_dwords(ptr, 0, 16)),
                accessxi.escape_probe_log_text(strings),
                accessxi.escape_probe_log_text(runs),
                accessxi.escape_probe_log_text_wide(accessxi.format_probe_bytes(ptr, 0, 0xC0))));
        end
    end
end

function accessxi.records_of_eminence_log_missing_detail(menu_name, row, record, reason)
    if (type(row) ~= 'table' or type(record) ~= 'table') then
        return;
    end

    local label = tostring(row.label or record.label or '');
    local record_id = tonumber(row.record_id) or 0;
    if (record_id <= 0 or label == '') then
        return;
    end

    local native_pos = accessxi.records_of_eminence_detail_position_signature(menu_name, reason);
    accessxi.log_records_of_eminence_text_probe(menu_name, row, record, reason, native_pos);
    accessxi.log_records_of_eminence_detail_deep_probe(menu_name, row, record, reason, native_pos);
    local key = ('%s:%s:%d:%d:%s'):fmt(
        tostring(menu_name or ''),
        tostring(reason or ''),
        record_id,
        tonumber(row.selected) or 0,
        native_pos);
    if (key == tostring(accessxi.last_records_of_eminence_detail_key or '')) then
        return;
    end
    accessxi.last_records_of_eminence_detail_key = key;
    log_state(('state records-of-eminence detail-missing reason="%s" menu="%s" recordId=%d selected=%d label="%s" nativePos="%s" source="%s"'):fmt(
        accessxi.escape_probe_log_text(tostring(reason or '')),
        tostring(menu_name or ''),
        record_id,
        tonumber(row.selected) or 0,
        accessxi.escape_probe_log_text(label),
        accessxi.escape_probe_log_text(native_pos),
        accessxi.escape_probe_log_text(tostring(row.source or record.source or ''))));
end

function accessxi.records_of_eminence_arm_row_suppression(row, speech)
    if (type(row) ~= 'table') then
        return;
    end

    local record_id = tonumber(row.record_id) or 0;
