    accessxi.records_of_eminence_suppress_row_record_id = record_id;
    accessxi.records_of_eminence_suppress_row_selected = selected;
    accessxi.records_of_eminence_suppress_row_until = tick() + 600;
end

function accessxi.records_of_eminence_arm_detail_list_speech_suppression(row, speech)
