function accessxi.records_of_eminence_arm_summary_return_row(row)
    if (type(row) ~= 'table') then
        return;
    end

    local record_id = tonumber(row.record_id) or 0;
    local selected = tonumber(row.selected) or 0;
    if (record_id <= 0 or selected <= 0) then
        return;
    end

    accessxi.records_of_eminence_summary_return_record_id = record_id;
    accessxi.records_of_eminence_summary_return_selected = selected;
    accessxi.records_of_eminence_summary_return_until = tick() + 12000;
end

function accessxi.records_of_eminence_summary_return_matches_list_row(key)
    local until_tick = tonumber(accessxi.records_of_eminence_summary_return_until) or 0;
    if (until_tick <= tick()) then
        accessxi.records_of_eminence_summary_return_record_id = 0;
        accessxi.records_of_eminence_summary_return_selected = 0;
        accessxi.records_of_eminence_summary_return_until = 0;
        return false;
    end

    key = tostring(key or '');
    local selected, record_id = key:match('^native%-known%-records%-of%-eminence%-objective%-catalog:[^:]+:(%d+):%d+:%d+:(%d+):');
    selected = tonumber(selected) or 0;
    record_id = tonumber(record_id) or 0;
    if (record_id > 0
        and selected > 0
        and record_id == (tonumber(accessxi.records_of_eminence_summary_return_record_id) or 0)
        and selected == (tonumber(accessxi.records_of_eminence_summary_return_selected) or 0)) then
        accessxi.records_of_eminence_summary_return_record_id = 0;
        accessxi.records_of_eminence_summary_return_selected = 0;
        accessxi.records_of_eminence_summary_return_until = 0;
        return true;
    end

    return false;
end

