function accessxi.records_of_eminence_clear_detail_watch(reason)
    accessxi.records_of_eminence_detail_watch_until = 0;
    accessxi.records_of_eminence_detail_watch_record_id = 0;
    accessxi.records_of_eminence_detail_watch_selected = 0;
    accessxi.records_of_eminence_detail_watch_reason = '';
    accessxi.records_of_eminence_detail_watch_key = '';
    accessxi.records_of_eminence_clear_native_detail_summary_cache(reason);
    accessxi.records_of_eminence_detail_line_hold_until = 0;
    accessxi.records_of_eminence_detail_line_hold_record_id = 0;
    accessxi.records_of_eminence_detail_line_hold_selected = 0;
    accessxi.records_of_eminence_confirm_detail_record_id = 0;
    accessxi.records_of_eminence_confirm_detail_until = 0;
    accessxi.records_of_eminence_suppress_row_record_id = 0;
    accessxi.records_of_eminence_suppress_row_selected = 0;
    accessxi.records_of_eminence_suppress_row_until = 0;
    log_state(('state records-of-eminence detail-watch-clear reason="%s"'):fmt(
        accessxi.escape_probe_log_text(tostring(reason or ''))));
end

function accessxi.records_of_eminence_clear_native_detail_summary_cache(reason)
    local had_cache = type(accessxi.records_of_eminence_native_detail_summary_cache) == 'table'
        or tostring(accessxi.records_of_eminence_native_detail_miss_key or '') ~= ''
        or (tonumber(accessxi.records_of_eminence_native_detail_miss_tick) or 0) ~= 0;
    accessxi.records_of_eminence_native_detail_summary_cache = nil;
    accessxi.records_of_eminence_native_detail_miss_key = '';
    accessxi.records_of_eminence_native_detail_miss_tick = 0;
    if (had_cache) then
        log_state(('state records-of-eminence native-detail-summary-cache-clear reason="%s"'):fmt(
            accessxi.escape_probe_log_text(tostring(reason or ''))));
    end
end

function accessxi.records_of_eminence_suppress_detail_poll(reason, duration_ms)
    local now = tick();
    local duration = tonumber(duration_ms) or 450;
    accessxi.records_of_eminence_detail_poll_suppress_until = math.max(
        tonumber(accessxi.records_of_eminence_detail_poll_suppress_until) or 0,
        now + math.max(150, duration));
    accessxi.records_of_eminence_detail_watch_key = '';
    accessxi.records_of_eminence_clear_native_detail_summary_cache(reason);
    local log_bucket = math.floor(now / 1000);
    local key = ('%s:%d'):fmt(tostring(reason or ''), log_bucket);
    if (key ~= tostring(accessxi.last_records_of_eminence_detail_poll_suppress_key or '')) then
        accessxi.last_records_of_eminence_detail_poll_suppress_key = key;
        log_state(('state records-of-eminence detail-poll-suppress reason="%s" until=%d'):fmt(
            accessxi.escape_probe_log_text(tostring(reason or '')),
            tonumber(accessxi.records_of_eminence_detail_poll_suppress_until) or 0));
    end
end

function accessxi.records_of_eminence_detail_poll_suppressed()
