        return false;
    end

    local selected = tonumber(signal.selected) or 0;
    local visible_count = tonumber(signal.visible_count) or 0;
    local slot_id = tonumber(signal.slot_id) or 0;
    local record_id = tonumber(signal.record_id) or 0;
    if (selected <= 0 or visible_count <= 0 or record_id <= 0) then
        return false;
    end

    local row = accessxi.records_of_eminence_objective_catalog_row_from_slot(slot_id, selected, visible_count);
    return type(row) == 'table' and type(row.record) == 'table' and (tonumber(row.record_id) or 0) == record_id;
end

function accessxi.records_of_eminence_catalog_detail_signal_active(signal, detail_index)
    if (type(signal) ~= 'table') then
        return false;
    end

    local selected = tonumber(signal.selected) or 0;
    local visible_count = tonumber(signal.visible_count) or 0;
    local slot_id = tonumber(signal.slot_id) or 0;
    local record_id = tonumber(signal.record_id) or 0;
    detail_index = tonumber(detail_index) or read_current_native_menu_index(0x4C);
    if (selected <= 0 or visible_count <= 0 or visible_count >= 20
        or slot_id < 0xE001 or slot_id > 0xFFFF
        or record_id <= 0 or detail_index <= 0 or detail_index > 64) then
        return false;
    end
    if (not accessxi.records_of_eminence_dat_objective_signal(signal)) then
        return false;
    end

    local context = tostring(accessxi.quests_menu_context or '');
    local context_age = (tonumber(accessxi.quests_menu_context_tick) or 0) > 0
        and (tick() - (tonumber(accessxi.quests_menu_context_tick) or 0))
        or 999999;
    if (context_age > 300000 or context ~= 'records-of-eminence-objective-catalog') then
        return false;
    end

    local catalog_age = (tonumber(accessxi.records_of_eminence_last_objective_catalog_tick) or 0) > 0
        and (tick() - (tonumber(accessxi.records_of_eminence_last_objective_catalog_tick) or 0))
        or 999999;
    if (catalog_age > 30000
        or (tonumber(accessxi.records_of_eminence_last_objective_catalog_record_id) or 0) ~= record_id
        or (tonumber(accessxi.records_of_eminence_last_objective_catalog_selected) or 0) ~= selected) then
        return false;
    end

    if (accessxi.records_of_eminence_recent_transition_key ~= nil
        and accessxi.records_of_eminence_recent_transition_key(VK_RETURN, 250, 2000)) then
        accessxi.records_of_eminence_catalog_detail_signal_until = tick() + 12000;
        accessxi.records_of_eminence_catalog_detail_signal_record_id = record_id;
        accessxi.records_of_eminence_catalog_detail_signal_selected = selected;
        return true;
    end

    if ((tonumber(accessxi.records_of_eminence_catalog_detail_signal_until) or 0) > tick()
        and (tonumber(accessxi.records_of_eminence_catalog_detail_signal_record_id) or 0) == record_id
        and (tonumber(accessxi.records_of_eminence_catalog_detail_signal_selected) or 0) == selected
        and detail_index ~= selected) then
        accessxi.records_of_eminence_catalog_detail_signal_until = tick() + 12000;
        return true;
    end

    local previous_selected = tonumber(accessxi.records_of_eminence_detail_native_signal_selected) or 0;
    local previous_record_id = tonumber(accessxi.records_of_eminence_detail_native_signal_record_id) or 0;
    local previous_detail_index = tonumber(accessxi.records_of_eminence_detail_native_signal_detail_index) or 0;
    local same_signal_motion = previous_selected == selected
        and previous_record_id == record_id
        and previous_detail_index > 0
        and previous_detail_index ~= detail_index
        and detail_index ~= selected;
    if (same_signal_motion) then
        accessxi.records_of_eminence_catalog_detail_signal_until = tick() + 4000;
        accessxi.records_of_eminence_catalog_detail_signal_record_id = record_id;
        accessxi.records_of_eminence_catalog_detail_signal_selected = selected;
        return true;
    end

    return false;
end

function accessxi.records_of_eminence_summary_open_blocks_list_row(signal)
    if ((tonumber(accessxi.records_of_eminence_summary_open_list_block_until) or 0) <= tick()) then
        return false;
    end
    if (type(signal) ~= 'table') then
        signal = accessxi.records_of_eminence_quest01_row_signal();
    end
    if (type(signal) ~= 'table') then
        return false;
    end

    return (tonumber(signal.record_id) or 0) > 0
        and (tonumber(signal.selected) or 0) > 0
        and (tonumber(signal.record_id) or 0) == (tonumber(accessxi.records_of_eminence_summary_open_list_block_record_id) or 0)
        and (tonumber(signal.selected) or 0) == (tonumber(accessxi.records_of_eminence_summary_open_list_block_selected) or 0);
end

function accessxi.records_of_eminence_native_motion_detail_active_for_signal(signal, detail_index)
    if (type(signal) ~= 'table') then
        return false;
    end

    local selected = tonumber(signal.selected) or 0;
    local record_id = tonumber(signal.record_id) or 0;
    detail_index = tonumber(detail_index) or read_current_native_menu_index(0x4C);
    local now = tick();
    local motion_live = (tonumber(accessxi.records_of_eminence_native_motion_detail_until) or 0) > now;
    local native_signal_live = tostring(accessxi.records_of_eminence_detail_native_signal_state or '') == 'objective-detail-candidate'
        and ((tonumber(accessxi.records_of_eminence_detail_native_signal_tick) or 0) > 0)
        and (now - (tonumber(accessxi.records_of_eminence_detail_native_signal_tick) or 0)) <= 5000
        and selected == (tonumber(accessxi.records_of_eminence_detail_native_signal_selected) or 0)
        and record_id == (tonumber(accessxi.records_of_eminence_detail_native_signal_record_id) or 0)
        and detail_index == (tonumber(accessxi.records_of_eminence_detail_native_signal_detail_index) or 0);
    return selected > 0
        and record_id > 0
        and accessxi.records_of_eminence_dat_objective_signal(signal)
        and detail_index > 0
        and detail_index <= 64
        and detail_index ~= selected
        and selected == (tonumber(accessxi.records_of_eminence_native_motion_detail_selected) or 0)
        and record_id == (tonumber(accessxi.records_of_eminence_native_motion_detail_record_id) or 0)
        and (motion_live or native_signal_live);
end

function accessxi.records_of_eminence_native_motion_detail_active(menu_name)
    menu_name = tostring(menu_name or get_menu_name() or '');
    if (not menu_name:eq('menu    quest01', true)) then
        return false;
    end
    local signal = accessxi.records_of_eminence_quest01_row_signal();
    return accessxi.records_of_eminence_native_motion_detail_active_for_signal(signal, read_current_native_menu_index(0x4C));
end

function accessxi.records_of_eminence_quest01_row_signal()
    local menu_name = tostring(get_menu_name() or '');
    if (not menu_name:eq('menu    quest01', true)) then
        return nil;
    end

    local obj = get_current_menu_object_ptr();
    if (obj == 0) then
        return nil;
    end

    local selected, page, raw, child, count = accessxi.survival_guide_query_child_state_for_obj(obj);
    selected = tonumber(selected) or 0;
    child = tonumber(child) or 0;
    count = tonumber(count) or 0;
    if (selected <= 0 or not accessxi.is_probe_pointer(child)) then
        return nil;
    end

    local visible_count = tonumber(read_u32(child + 0x40)) or 0;
    if (visible_count <= 0) then
        visible_count = count;
    end
    if (visible_count <= 0 or visible_count > 64 or selected > visible_count) then
        return nil;
    end

    local slot_id, slot_flags, slot_block, raw_lo = accessxi.quests_menu_runtime_slot(child, raw);
    local record_id = 0;
    slot_id = tonumber(slot_id) or 0;
    if (slot_id >= 0xE001 and slot_id <= 0xFFFF) then
        record_id = slot_id - 0xE000;
    end

    return T{
        selected = selected,
        page = tonumber(page) or 0,
        raw = tonumber(raw) or 0,
        child = child,
        count = count,
        visible_count = visible_count,
        slot_id = slot_id,
        slot_flags = tonumber(slot_flags) or 0,
        slot_block = tonumber(slot_block) or 0,
        raw_lo = tonumber(raw_lo) or -1,
        record_id = record_id,
    };
end

function accessxi.records_of_eminence_quest01_row_signal_mismatches(row, reason)
    if (type(row) ~= 'table') then
        return false;
    end

    local signal = accessxi.records_of_eminence_quest01_row_signal();
    if (type(signal) ~= 'table') then
        return false;
    end

    local row_selected = tonumber(row.selected) or 0;
    local row_record_id = tonumber(row.record_id) or 0;
    local signal_selected = tonumber(signal.selected) or 0;
    local signal_record_id = tonumber(signal.record_id) or 0;
    local mismatch = false;
    local mismatch_reason = '';
    if (signal_record_id > 0 and row_record_id > 0 and signal_record_id ~= row_record_id) then
        mismatch = true;
        mismatch_reason = 'record-id';
    elseif (signal_record_id > 0 and row_selected > 0 and signal_selected > 0 and signal_selected ~= row_selected) then
        mismatch = true;
        mismatch_reason = 'selected';
    end

    if (not mismatch) then
        return false;
    end

    local key = ('%s:%d:%d:%d:%d:%d:%s'):fmt(
        tostring(reason or ''),
        row_record_id,
        row_selected,
        signal_record_id,
        signal_selected,
        tonumber(signal.visible_count) or 0,
        mismatch_reason);
    if (key ~= tostring(accessxi.last_records_of_eminence_detail_row_signal_mismatch_key or '')) then
        accessxi.last_records_of_eminence_detail_row_signal_mismatch_key = key;
        log_state(('state records-of-eminence detail-row-signal-mismatch reason="%s" mismatch="%s" rowRecordId=%d rowSelected=%d signalRecordId=%d signalSelected=%d visible=%d count=%d raw=0x%08X rawLo=%d slotId=0x%04X flags=0x%08X block=0x%08X'):fmt(
            accessxi.escape_probe_log_text(tostring(reason or '')),
            accessxi.escape_probe_log_text(mismatch_reason),
            row_record_id,
            row_selected,
            signal_record_id,
            signal_selected,
            tonumber(signal.visible_count) or 0,
            tonumber(signal.count) or 0,
            tonumber(signal.raw) or 0,
            tonumber(signal.raw_lo) or -1,
            tonumber(signal.slot_id) or 0,
            tonumber(signal.slot_flags) or 0,
            tonumber(signal.slot_block) or 0));
    end
    return true;
end

