function accessxi.records_of_eminence_recent_catalog_after_direct_detail(row)
    if (type(row) ~= 'table') then
        return false;
    end

    local now = tick();
    local direct_tick = tonumber(accessxi.records_of_eminence_last_direct_detail_tick) or 0;
    local catalog_tick = tonumber(accessxi.records_of_eminence_last_objective_catalog_tick) or 0;
    if (direct_tick <= 0 or catalog_tick <= direct_tick or (now - catalog_tick) > 2500) then
        return false;
    end

    local record_id = tonumber(row.record_id) or 0;
    local selected = tonumber(row.selected) or 0;
    if (record_id <= 0 or selected <= 0) then
        return false;
    end
    if ((tonumber(accessxi.records_of_eminence_last_direct_detail_record_id) or 0) ~= record_id
        or (tonumber(accessxi.records_of_eminence_last_objective_catalog_record_id) or 0) ~= record_id
        or (tonumber(accessxi.records_of_eminence_last_objective_catalog_selected) or 0) ~= selected) then
        return false;
    end

    local detail_index = tonumber(accessxi.records_of_eminence_last_objective_catalog_detail_index) or 0;
    return detail_index > 0 and detail_index <= (selected + 1);
end

function accessxi.records_of_eminence_direct_objective_detail_surface(row)
    local signal = accessxi.records_of_eminence_quest01_row_signal();
    local detail_index = read_current_native_menu_index(0x4C);
    local fence_motion_detail = type(signal) == 'table'
        and (tonumber(signal.record_id) or 0) > 0
        and (tonumber(signal.visible_count) or 0) >= 20
        and (tonumber(signal.slot_id) or 0) >= 0xE001
        and (tonumber(signal.slot_id) or 0) <= 0xFFFF
        and (tonumber(signal.selected) or 0) > 0
        and detail_index > 0
        and detail_index <= 64
        and detail_index ~= (tonumber(signal.selected) or 0);
    if ((tonumber(accessxi.records_of_eminence_direct_detail_list_until) or 0) > tick()
        and not fence_motion_detail) then
        return false;
    end
    if (type(signal) == 'table' and (tonumber(signal.record_id) or 0) > 0) then
        local record_id = tonumber(row.record_id) or 0;
        local selected = tonumber(row.selected) or 0;
        local obj = get_current_menu_object_ptr();
        local idx24 = -1;
        local idx28 = -1;
        local flags50 = 0;
        if (obj ~= 0) then
            idx24 = tonumber(read_i32(obj + 0x24)) or -1;
            idx28 = tonumber(read_i32(obj + 0x28)) or -1;
            flags50 = tonumber(read_i32(obj + 0x50)) or 0;
        end
        local target = safe_call(function () return AshitaCore:GetMemoryManager():GetTarget(); end, nil);
        local ank = target ~= nil and (tonumber(safe_call(function () return target:GetWindowAnkNum(); end, -1)) or -1) or -1;
        local detail_active = accessxi.records_of_eminence_detail_line_surface_active_for_row(row, true);
        local target_label = tostring(row.label or ((type(row.record) == 'table' and row.record.label) or '') or '');
        local target_help = accessxi.records_of_eminence_target_help_detail_surface(target_label);
        local target_matched = type(target_help) == 'table' and target_help.matched == true;
        local target_summary = '';
        if (type(target_help) == 'table') then
            target_summary = tostring(target_help.summary or '');
        end
        local signal_matches_row = (tonumber(signal.record_id) or 0) == record_id
            and (tonumber(signal.selected) or 0) == selected;
        local native_motion_detail = accessxi.records_of_eminence_native_motion_detail_active_for_signal(signal, detail_index);
        local key = ('%d:%d:%d:%d:%d'):fmt(
            record_id,
            selected,
            tonumber(signal.record_id) or 0,
            tonumber(signal.selected) or 0,
            tonumber(signal.visible_count) or 0);
        key = ('%s:%d:%d:%d:%d:%s'):fmt(
            key,
            tonumber(detail_index) or 0,
            tonumber(idx24) or -1,
            tonumber(idx28) or -1,
            tonumber(ank) or -1,
            tostring(target_matched == true));
        local list_surface_log_tick = tonumber(accessxi.last_records_of_eminence_direct_detail_list_surface_log_tick) or 0;
        if (key ~= tostring(accessxi.last_records_of_eminence_direct_detail_list_surface_key or '')
            and (tick() - list_surface_log_tick) >= 1000) then
            accessxi.last_records_of_eminence_direct_detail_list_surface_key = key;
            accessxi.last_records_of_eminence_direct_detail_list_surface_log_tick = tick();
            log_state(('state records-of-eminence direct-detail-refused-list-surface rowRecordId=%d rowSelected=%d signalRecordId=%d signalSelected=%d visible=%d slotId=0x%04X detailIndex=%d idx24=%d idx28=%d flags50=0x%08X ank=%d active=%s targetMatched=%s target="%s"'):fmt(
                record_id,
                selected,
                tonumber(signal.record_id) or 0,
                tonumber(signal.selected) or 0,
                tonumber(signal.visible_count) or 0,
                tonumber(signal.slot_id) or 0,
                tonumber(detail_index) or 0,
                tonumber(idx24) or -1,
                tonumber(idx28) or -1,
                tonumber(flags50) or 0,
                tonumber(ank) or -1,
                tostring(detail_active == true),
                tostring(target_matched == true),
                accessxi.escape_probe_log_text(target_summary)));
        end
        if ((tonumber(signal.visible_count) or 0) >= 20
            and target_matched ~= true
            and not (signal_matches_row and detail_active and native_motion_detail)
            and not (signal_matches_row and detail_active)) then
            return false;
        end
        if (not (signal_matches_row and detail_active)) then
            if (not signal_matches_row) then
                accessxi.records_of_eminence_clear_detail_watch('direct-detail-signal-close');
            end
            return false;
        end
        if (native_motion_detail) then
            return true;
        end
    end
    if (accessxi.records_of_eminence_quest01_row_signal_mismatches(row, 'direct-detail')) then
        return false;
    end
    if (accessxi.records_of_eminence_recent_catalog_after_direct_detail(row)) then
        return false;
    end
    return accessxi.records_of_eminence_recent_objective_detail_row(row)
        and accessxi.records_of_eminence_detail_line_surface_active_for_row(row, true);
end

function accessxi.records_of_eminence_poll_detail_native_signal()
    if (is_chat_input_open ~= nil and is_chat_input_open()) then
        return;
    end

    local menu_name = tostring(get_menu_name() or '');
    if (not menu_name:eq('menu    quest01', true)) then
        if (tostring(accessxi.records_of_eminence_detail_native_signal_state or '') ~= '') then
            log_state(('state records-of-eminence detail-native-signal-close menu="%s" previous="%s" reason="menu-left"'):fmt(
                menu_name,
                accessxi.escape_probe_log_text(tostring(accessxi.records_of_eminence_detail_native_signal_state or ''))));
            accessxi.records_of_eminence_detail_native_signal_state = '';
            accessxi.records_of_eminence_detail_native_signal_key = '';
            accessxi.records_of_eminence_clear_detail_watch('native-signal-menu-left');
        end
        return;
    end

    local obj = get_current_menu_object_ptr();
    local signal = accessxi.records_of_eminence_quest01_row_signal();
    local selected = type(signal) == 'table' and (tonumber(signal.selected) or 0) or 0;
    local record_id = type(signal) == 'table' and (tonumber(signal.record_id) or 0) or 0;
    local visible_count = type(signal) == 'table' and (tonumber(signal.visible_count) or 0) or 0;
    local slot_id = type(signal) == 'table' and (tonumber(signal.slot_id) or 0) or 0;
    local child = type(signal) == 'table' and (tonumber(signal.child) or 0) or 0;
    local raw = type(signal) == 'table' and (tonumber(signal.raw) or 0) or 0;
    local raw_lo = type(signal) == 'table' and (tonumber(signal.raw_lo) or -1) or -1;
    local detail_index = read_current_native_menu_index(0x4C);
    local entry = accessxi.is_probe_pointer(obj) and (read_u32(obj + 0x08) or 0) or 0;
    local target = safe_call(function () return AshitaCore:GetMemoryManager():GetTarget(); end, nil);
    local ank = target ~= nil and (tonumber(safe_call(function () return target:GetWindowAnkNum(); end, -1)) or -1) or -1;
    local ank_x = target ~= nil and (tonumber(safe_call(function () return target:GetWindowAnkX(); end, -1)) or -1) or -1;
    local ank_y = target ~= nil and (tonumber(safe_call(function () return target:GetWindowAnkY(); end, -1)) or -1) or -1;
    local sub = target ~= nil and (tonumber(safe_call(function () return target:GetWindowSub(); end, -1)) or -1) or -1;
    local sub_x = target ~= nil and (tonumber(safe_call(function () return target:GetWindowSubAnkX(); end, -1)) or -1) or -1;
    local sub_y = target ~= nil and (tonumber(safe_call(function () return target:GetWindowSubAnkY(); end, -1)) or -1) or -1;
    local fields = T{};
    if (obj ~= 0) then
        for _, offset in ipairs(T{ 0x18, 0x20, 0x24, 0x28, 0x2C, 0x30, 0x34, 0x40, 0x44, 0x48, 0x4C, 0x50, 0x54, 0x58, 0x5C, 0x60, 0x64, 0x68, 0x6C, 0x70 }) do
            fields:append(('%02X=%d'):fmt(offset, tonumber(read_i32(obj + offset)) or 0));
        end
    end

    local state = 'none';
    local detail_surface_active = false;

    local previous_selected = tonumber(accessxi.records_of_eminence_detail_native_signal_selected) or 0;
    local previous_record_id = tonumber(accessxi.records_of_eminence_detail_native_signal_record_id) or 0;
    local previous_detail_index = tonumber(accessxi.records_of_eminence_detail_native_signal_detail_index) or 0;
    local previous_state = tostring(accessxi.records_of_eminence_detail_native_signal_state or '');
    local idx24 = obj ~= 0 and (tonumber(read_i32(obj + 0x24)) or -1) or -1;
    local idx28 = obj ~= 0 and (tonumber(read_i32(obj + 0x28)) or -2) or -2;
    local native_motion_detail = visible_count >= 20
        and selected > 0
        and record_id > 0
        and slot_id >= 0xE001
        and slot_id <= 0xFFFF
        and previous_selected == selected
        and previous_record_id == record_id
        and previous_detail_index > 0
        and detail_index > 0
        and detail_index <= 64
        and detail_index ~= selected
        and previous_detail_index ~= detail_index;
    if (native_motion_detail) then
        accessxi.records_of_eminence_native_motion_detail_until = tick() + 1600;
        accessxi.records_of_eminence_native_motion_detail_record_id = record_id;
        accessxi.records_of_eminence_native_motion_detail_selected = selected;
        accessxi.records_of_eminence_detail_poll_suppress_until = 0;
        local motion_key = ('%d:%d:%d:%d'):fmt(record_id, selected, previous_detail_index, tonumber(detail_index) or 0);
        if (motion_key ~= tostring(accessxi.records_of_eminence_native_motion_detail_log_key or '')) then
            accessxi.records_of_eminence_native_motion_detail_log_key = motion_key;
            log_state(('state records-of-eminence native-motion-detail-surface recordId=%d selected=%d previousDetailIndex=%d detailIndex=%d slotId=0x%04X idx24=%d idx28=%d'):fmt(
                record_id,
                selected,
                previous_detail_index,
                tonumber(detail_index) or 0,
                slot_id,
                idx24,
                idx28));
        end
    elseif (detail_index == selected or record_id ~= (tonumber(accessxi.records_of_eminence_native_motion_detail_record_id) or 0)
        or selected ~= (tonumber(accessxi.records_of_eminence_native_motion_detail_selected) or 0)) then
        accessxi.records_of_eminence_native_motion_detail_until = 0;
    end
    detail_surface_active = accessxi.records_of_eminence_quest01_detail_surface_active(menu_name);
    local dat_objective_signal = accessxi.records_of_eminence_dat_objective_signal(signal);
    local catalog_detail_signal = accessxi.records_of_eminence_catalog_detail_signal_active(signal, detail_index);
    if (dat_objective_signal and detail_index > 0 and (detail_surface_active or catalog_detail_signal)) then
        state = 'objective-detail-candidate';
    elseif (visible_count >= 20 and record_id > 0) then
        state = 'objective-list';
    elseif (visible_count > 0) then
        state = 'category-or-parent-list';
    end
    local same_objective_detail_motion = state == 'objective-detail-candidate'
        and selected > 0
        and record_id > 0
        and previous_selected == selected
        and previous_record_id == record_id
        and previous_detail_index > 0
        and detail_index > 0
        and (detail_surface_active or catalog_detail_signal)
        and previous_detail_index ~= detail_index;
    accessxi.records_of_eminence_detail_native_signal_selected = selected;
    accessxi.records_of_eminence_detail_native_signal_record_id = record_id;
    accessxi.records_of_eminence_detail_native_signal_detail_index = tonumber(detail_index) or 0;

    local key = ('%s:0x%08X:0x%08X:0x%08X:%d:%d:%d:%d:0x%04X:%d:%d:%d:%d:%d:%d:%s'):fmt(
        menu_name,
        obj,
        child,
        entry,
        selected,
        record_id,
        visible_count,
        raw,
        slot_id,
        raw_lo,
        tonumber(detail_index) or 0,
        ank,
        ank_x,
        ank_y,
        sub,
        fields:concat(','));
    if (key ~= tostring(accessxi.records_of_eminence_detail_native_signal_key or '')) then
        accessxi.records_of_eminence_detail_native_signal_key = key;
        accessxi.records_of_eminence_detail_native_signal_state = state;
        accessxi.records_of_eminence_detail_native_signal_tick = tick();
        local native_signal_log_tick = tonumber(accessxi.records_of_eminence_detail_native_signal_log_tick) or 0;
        if ((tick() - native_signal_log_tick) >= 300) then
            accessxi.records_of_eminence_detail_native_signal_log_tick = tick();
            log_state(('state records-of-eminence detail-native-signal state="%s" menu="%s" obj=0x%08X child=0x%08X entry=0x%08X selected=%d recordId=%d visible=%d raw=0x%08X rawLo=%d slotId=0x%04X detailIndex=%d ank=%d,%d,%d sub=%d,%d,%d fields="%s"'):fmt(
                state,
                menu_name,
                obj,
                child,
                entry,
                selected,
                record_id,
                visible_count,
                raw,
                raw_lo,
                slot_id,
                tonumber(detail_index) or 0,
                ank,
                ank_x,
                ank_y,
                sub,
                sub_x,
                sub_y,
                accessxi.escape_probe_log_text(fields:concat(','))));
        end
    end
    if (state == 'objective-detail-candidate') then
        accessxi.records_of_eminence_detail_native_signal_state = state;
        accessxi.records_of_eminence_detail_native_signal_tick = tick();
    end
    accessxi.log_records_of_eminence_transition_probe(
        menu_name,
        state,
        signal,
        detail_index,
        ank,
        ank_x,
        ank_y,
        sub,
        sub_x,
        sub_y,
        obj,
        child,
        entry,
        fields:concat(','));

    local command_motion_probe = same_objective_detail_motion
        and ((tonumber(accessxi.records_of_eminence_text_probe_until) or 0) >= tick()
            or (tonumber(accessxi.records_of_eminence_detail_probe_until) or 0) >= tick());
    if (command_motion_probe) then
        local records = accessxi.records_of_eminence_data.records or T{};
        local record = records[record_id];
        if (type(record) == 'table') then
            local label = tostring(record.label or '');
            local row = T{
                selected = selected,
                visible_count = visible_count,
                record_id = record_id,
                label = label,
                record = record,
                source = 'native-detail-motion',
            };
            local native_pos = accessxi.records_of_eminence_detail_position_signature(menu_name, 'native-detail-motion');
            local motion_key = ('%d:%d:%d:%d:%s'):fmt(
                record_id,
                selected,
                previous_detail_index,
                tonumber(detail_index) or 0,
                tostring(native_pos or ''));
            if (motion_key ~= tostring(accessxi.records_of_eminence_detail_native_motion_probe_key or '')) then
                accessxi.records_of_eminence_detail_native_motion_probe_key = motion_key;
                log_state(('state records-of-eminence native-detail-motion-probe menu="%s" recordId=%d selected=%d detailIndex=%d previousDetailIndex=%d label="%s" nativePos="%s"'):fmt(
                    menu_name,
                    record_id,
                    selected,
                    tonumber(detail_index) or 0,
                    previous_detail_index,
                    accessxi.escape_probe_log_text(label),
                    accessxi.escape_probe_log_text(tostring(native_pos or ''))));
                accessxi.log_records_of_eminence_text_probe(menu_name, row, record, 'native-detail-motion', native_pos);
                accessxi.log_records_of_eminence_detail_deep_probe(menu_name, row, record, 'native-detail-motion', native_pos);
            end
        end
    end

    if (state == 'category-or-parent-list' or state == 'none') then
        accessxi.records_of_eminence_clear_native_detail_summary_cache(('native-signal-%s'):fmt(state));
        local suppress_key = ('%s:%d:%d:%d:0x%04X:%d'):fmt(
            state,
            selected,
            record_id,
            visible_count,
            slot_id,
            tonumber(detail_index) or 0);
        if (previous_state ~= state
            or suppress_key ~= tostring(accessxi.last_records_of_eminence_native_signal_suppress_key or '')) then
            accessxi.last_records_of_eminence_native_signal_suppress_key = suppress_key;
            accessxi.records_of_eminence_suppress_detail_poll(('native-signal-%s'):fmt(state), 450);
        end
        if ((tonumber(accessxi.records_of_eminence_detail_watch_until) or 0) > tick()) then
            accessxi.records_of_eminence_clear_detail_watch(('native-signal-%s'):fmt(state));
        end
    end
end

function accessxi.records_of_eminence_transition_key_name(key)
    key = tonumber(key) or 0;
    if (key == VK_RETURN) then
        return 'return';
    elseif (key == VK_ESCAPE) then
        return 'escape';
    elseif (key == VK_UP) then
        return 'up';
    elseif (key == VK_DOWN) then
        return 'down';
    elseif (key == VK_LEFT) then
        return 'left';
    elseif (key == VK_RIGHT) then
        return 'right';
    end
    return ('0x%02X'):fmt(key);
end

function accessxi.records_of_eminence_note_transition_key(key)
    key = tonumber(key) or 0;
    if (key ~= VK_RETURN and key ~= VK_ESCAPE and key ~= VK_UP and key ~= VK_DOWN and key ~= VK_LEFT and key ~= VK_RIGHT) then
        return;
    end

    local menu_name = tostring(get_menu_name() or '');
    if (not (menu_name:eq('menu    quest01', true) or menu_name:eq('menu    quest00', true) or menu_name:eq('menu    comyn', true) or menu_name:eq('menu    inline', true))) then
        return;
    end

    accessxi.records_of_eminence_transition_probe_key = key;
    accessxi.records_of_eminence_transition_probe_key_name = accessxi.records_of_eminence_transition_key_name(key);
    accessxi.records_of_eminence_transition_probe_key_tick = tick();
    accessxi.records_of_eminence_transition_probe_last_state_key = '';
    if ((tonumber(accessxi.records_of_eminence_transition_probe_until) or 0) <= tick()) then
        return;
    end
    log_state(('state records-of-eminence transition-key menu="%s" key="%s" raw=0x%02X'):fmt(
        menu_name,
        accessxi.escape_probe_log_text(tostring(accessxi.records_of_eminence_transition_probe_key_name or '')),
        key));
end

function accessxi.records_of_eminence_recent_transition_key(key, min_age_ms, max_age_ms)
    if ((tonumber(accessxi.records_of_eminence_transition_probe_key) or 0) ~= (tonumber(key) or 0)) then
        return false;
    end

    local key_tick = tonumber(accessxi.records_of_eminence_transition_probe_key_tick) or 0;
    if (key_tick <= 0) then
        return false;
    end

    local age = tick() - key_tick;
    return age >= (tonumber(min_age_ms) or 0) and age <= (tonumber(max_age_ms) or 0);
end

function accessxi.log_records_of_eminence_transition_probe(menu_name, state, signal, detail_index, ank, ank_x, ank_y, sub, sub_x, sub_y, obj, child, entry, fields)
    if ((tonumber(accessxi.records_of_eminence_transition_probe_until) or 0) <= tick()) then
        return;
    end
    local key_tick = tonumber(accessxi.records_of_eminence_transition_probe_key_tick) or 0;
    if (key_tick > 0 and (tick() - key_tick) > 3500) then
        return;
    end
    if ((tonumber(accessxi.records_of_eminence_transition_probe_count) or 0) >= (tonumber(accessxi.records_of_eminence_transition_probe_limit) or 80)) then
        return;
    end

    local key_name = tostring(accessxi.records_of_eminence_transition_probe_key_name or '');
    if (key_name == '') then
        key_name = 'poll';
    end

    local selected = type(signal) == 'table' and (tonumber(signal.selected) or 0) or 0;
    local record_id = type(signal) == 'table' and (tonumber(signal.record_id) or 0) or 0;
    local visible_count = type(signal) == 'table' and (tonumber(signal.visible_count) or 0) or 0;
    local slot_id = type(signal) == 'table' and (tonumber(signal.slot_id) or 0) or 0;
    local raw = type(signal) == 'table' and (tonumber(signal.raw) or 0) or 0;
    local raw_lo = type(signal) == 'table' and (tonumber(signal.raw_lo) or -1) or -1;
    local shape_surface = accessxi.records_of_eminence_quest01_detail_surface_active(menu_name) == true;
    local state_key = ('%s:%s:%s:%d:%d:%d:%d:0x%04X:%d:%d:%d:%d:%d'):fmt(
        tostring(menu_name or ''),
        key_name,
        tostring(state or ''),
        selected,
        record_id,
        visible_count,
        tonumber(raw) or 0,
        slot_id,
        raw_lo,
        tonumber(detail_index) or 0,
        tonumber(ank) or -1,
        tonumber(ank_x) or -1,
        tonumber(ank_y) or -1);
    if (state_key == tostring(accessxi.records_of_eminence_transition_probe_last_state_key or '')) then
        return;
    end
    accessxi.records_of_eminence_transition_probe_last_state_key = state_key;
    accessxi.records_of_eminence_transition_probe_count = (tonumber(accessxi.records_of_eminence_transition_probe_count) or 0) + 1;
    log_state(('state records-of-eminence transition-probe key="%s" menu="%s" state="%s" obj=0x%08X child=0x%08X entry=0x%08X selected=%d recordId=%d visible=%d raw=0x%08X rawLo=%d slotId=0x%04X detailIndex=%d ank=%d,%d,%d sub=%d,%d,%d surface=%s fields="%s"'):fmt(
        accessxi.escape_probe_log_text(key_name),
        tostring(menu_name or ''),
        accessxi.escape_probe_log_text(tostring(state or '')),
        tonumber(obj) or 0,
        tonumber(child) or 0,
        tonumber(entry) or 0,
        selected,
        record_id,
        visible_count,
        raw,
        raw_lo,
        slot_id,
        tonumber(detail_index) or 0,
        tonumber(ank) or -1,
        tonumber(ank_x) or -1,
        tonumber(ank_y) or -1,
        tonumber(sub) or -1,
        tonumber(sub_x) or -1,
        tonumber(sub_y) or -1,
        tostring(shape_surface),
        accessxi.escape_probe_log_text(tostring(fields or ''))));
end

function accessxi.log_records_of_eminence_transition_list_row(menu_name, text, speech_key)
    if ((tonumber(accessxi.records_of_eminence_transition_probe_until) or 0) <= tick()) then
        return;
    end

    local signal = accessxi.records_of_eminence_quest01_row_signal();
    local target = safe_call(function () return AshitaCore:GetMemoryManager():GetTarget(); end, nil);
    local window_name = target ~= nil and clean_probe_text(safe_call(function () return target:GetWindowName(); end, '') or '') or '';
    local loaded = target ~= nil and (tonumber(safe_call(function () return target:GetWindowIsWindowLoaded(); end, -1)) or -1) or -1;
    local server_id = target ~= nil and (tonumber(safe_call(function () return target:GetWindowServerId(); end, -1)) or -1) or -1;
    local obj = get_current_menu_object_ptr();
    local child04 = accessxi.is_probe_pointer(obj) and (read_u32(obj + 0x04) or 0) or 0;
    local child08 = accessxi.is_probe_pointer(obj) and (read_u32(obj + 0x08) or 0) or 0;
    local child0c = accessxi.is_probe_pointer(obj) and (read_u32(obj + 0x0C) or 0) or 0;
    local detail_index = accessxi.is_probe_pointer(obj) and (tonumber(read_i32(obj + 0x4C)) or 0) or 0;
    local key = ('%s:%s:%s:%d:%d:%d:%d:%08X:%08X:%08X:%08X'):fmt(
        tostring(menu_name or ''),
        tostring(speech_key or ''),
        tostring(text or ''),
        type(signal) == 'table' and (tonumber(signal.selected) or 0) or 0,
        type(signal) == 'table' and (tonumber(signal.record_id) or 0) or 0,
        type(signal) == 'table' and (tonumber(signal.visible_count) or 0) or 0,
        detail_index,
        tonumber(obj) or 0,
        tonumber(child04) or 0,
        tonumber(child08) or 0,
        tonumber(child0c) or 0);
    if (key == tostring(accessxi.last_records_of_eminence_transition_list_row_key or '')) then
        return;
    end
    accessxi.last_records_of_eminence_transition_list_row_key = key;

    log_state(('state records-of-eminence transition-list-row menu="%s" win="%s" loaded=%d serverId=%d obj=0x%08X child04=0x%08X child08=0x%08X child0C=0x%08X selected=%d recordId=%d visible=%d raw=0x%08X rawLo=%d slotId=0x%04X detailIndex=%d key="%s" text="%s" objD00="%s" child04D00="%s" child08D00="%s" child0CD00="%s"'):fmt(
        tostring(menu_name or ''),
        accessxi.escape_probe_log_text(window_name),
        loaded,
        server_id,
        tonumber(obj) or 0,
        tonumber(child04) or 0,
        tonumber(child08) or 0,
        tonumber(child0c) or 0,
        type(signal) == 'table' and (tonumber(signal.selected) or 0) or 0,
        type(signal) == 'table' and (tonumber(signal.record_id) or 0) or 0,
        type(signal) == 'table' and (tonumber(signal.visible_count) or 0) or 0,
        type(signal) == 'table' and (tonumber(signal.raw) or 0) or 0,
        type(signal) == 'table' and (tonumber(signal.raw_lo) or -1) or -1,
        type(signal) == 'table' and (tonumber(signal.slot_id) or 0) or 0,
        detail_index,
        accessxi.escape_probe_log_text(tostring(speech_key or '')),
        accessxi.escape_probe_log_text(tostring(text or '')),
        accessxi.escape_probe_log_text(accessxi.is_probe_pointer(obj) and accessxi.format_probe_dwords(obj, 0x00, 20) or ''),
        accessxi.escape_probe_log_text(accessxi.is_probe_pointer(child04) and accessxi.format_probe_dwords(child04, 0x00, 16) or ''),
        accessxi.escape_probe_log_text(accessxi.is_probe_pointer(child08) and accessxi.format_probe_dwords(child08, 0x00, 16) or ''),
        accessxi.escape_probe_log_text(accessxi.is_probe_pointer(child0c) and accessxi.format_probe_dwords(child0c, 0x00, 16) or '')));
end

function accessxi.records_of_eminence_poll_transition_surface_probe(menu_name)
    if ((tonumber(accessxi.records_of_eminence_transition_probe_until) or 0) <= tick()) then
        return;
    end
    menu_name = tostring(menu_name or get_menu_name() or '');
    if (not (menu_name:eq('menu    quest01', true)
        or menu_name:eq('menu    quest00', true)
        or menu_name:eq('menu    comyn', true)
        or menu_name:eq('menu    inline', true))) then
        return;
    end

    local obj = get_current_menu_object_ptr();
    local child = 0;
    local entry = 0;
    local detail_index = 0;
    local fields = T{};
    if (obj ~= 0) then
        child = read_u32(obj + 0x0C) or 0;
        entry = read_u32(obj + 0x08) or 0;
        detail_index = tonumber(read_i32(obj + 0x4C)) or 0;
        for _, offset in ipairs(T{ 0x08, 0x0C, 0x18, 0x20, 0x24, 0x28, 0x2C, 0x30, 0x34, 0x40, 0x44, 0x48, 0x4C, 0x50, 0x54, 0x58, 0x5C, 0x60, 0x64, 0x68, 0x6C, 0x70, 0xE8, 0xF0 }) do
            fields:append(('%02X=%d'):fmt(offset, tonumber(read_i32(obj + offset)) or 0));
        end
    end
    local target = safe_call(function () return AshitaCore:GetMemoryManager():GetTarget(); end, nil);
    local ank = target ~= nil and (tonumber(safe_call(function () return target:GetWindowAnkNum(); end, -1)) or -1) or -1;
    local ank_x = target ~= nil and (tonumber(safe_call(function () return target:GetWindowAnkX(); end, -1)) or -1) or -1;
    local ank_y = target ~= nil and (tonumber(safe_call(function () return target:GetWindowAnkY(); end, -1)) or -1) or -1;
    local sub = target ~= nil and (tonumber(safe_call(function () return target:GetWindowSub(); end, -1)) or -1) or -1;
    local sub_x = target ~= nil and (tonumber(safe_call(function () return target:GetWindowSubAnkX(); end, -1)) or -1) or -1;
    local sub_y = target ~= nil and (tonumber(safe_call(function () return target:GetWindowSubAnkY(); end, -1)) or -1) or -1;
    local signal = accessxi.records_of_eminence_quest01_row_signal();
    local state = 'surface-poll';
    if (menu_name:eq('menu    quest01', true)) then
        local record_id = type(signal) == 'table' and (tonumber(signal.record_id) or 0) or 0;
        local visible_count = type(signal) == 'table' and (tonumber(signal.visible_count) or 0) or 0;
        if (visible_count >= 20
            and record_id > 0
            and detail_index > 0
            and accessxi.records_of_eminence_quest01_detail_surface_active(menu_name)) then
            state = 'objective-detail-candidate';
        elseif (visible_count >= 20 and record_id > 0) then
            state = 'objective-list';
        elseif (visible_count > 0) then
            state = 'category-or-parent-list';
        end
    end
    accessxi.log_records_of_eminence_transition_probe(
        menu_name,
        state,
        signal,
        detail_index,
        ank,
        ank_x,
        ank_y,
        sub,
        sub_x,
        sub_y,
        obj,
        child,
        entry,
        fields:concat(','));
end

function accessxi.records_of_eminence_clear_stale_detail_watch_for_list_row(record_id, selected)
    record_id = tonumber(record_id) or 0;
    selected = tonumber(selected) or 0;
    if (record_id <= 0 or selected <= 0) then
        return false;
    end
    if ((tonumber(accessxi.records_of_eminence_detail_watch_until) or 0) <= tick()) then
        return false;
    end

    local watched_record_id = tonumber(accessxi.records_of_eminence_detail_watch_record_id) or 0;
    local watched_selected = tonumber(accessxi.records_of_eminence_detail_watch_selected) or 0;
    if (watched_record_id <= 0 or watched_selected <= 0) then
        return false;
    end
    if (watched_record_id == record_id and watched_selected == selected) then
        return false;
    end
    if (tostring(accessxi.records_of_eminence_detail_watch_reason or '') == 'confirm-return'
        and accessxi.records_of_eminence_detail_line_surface_active_for_selected(watched_selected)) then
        return false;
    end

    accessxi.records_of_eminence_clear_detail_watch(('list-row:%d:%d'):fmt(record_id, selected));
    return true;
end

function accessxi.records_of_eminence_timed_detail_line_ready(row)
    if (type(row) ~= 'table') then
        return false;
    end
    local signal = accessxi.records_of_eminence_quest01_row_signal();
    if (type(signal) == 'table' and (tonumber(signal.record_id) or 0) > 0) then
        return false;
    end

    local selected = tonumber(row.selected) or 0;
    local detail_index = read_current_native_menu_index(0x4C);
    return detail_index > 0
        and detail_index <= 64
        and selected > 0
        and detail_index ~= selected;
end

function accessxi.arm_records_of_eminence_detail_position_watch(menu_name, row, record, reason, speech)
    reason = tostring(reason or '');
    if (not (reason == 'confirm-return' or reason == 'comyn-detail' or reason == 'inline-detail')) then
        return;
    end
    if (type(row) ~= 'table' or type(record) ~= 'table') then
        return;
    end

    local record_id = tonumber(row.record_id) or 0;
    local selected = tonumber(row.selected) or 0;
    local label = tostring(row.label or record.label or '');
    local description = tostring(record.description or '');
    if (record_id <= 0 or selected <= 0 or label == '' or description == '') then
        return;
    end

    local previous_record_id = tonumber(accessxi.records_of_eminence_detail_watch_record_id) or 0;
    local previous_selected = tonumber(accessxi.records_of_eminence_detail_watch_selected) or 0;
    local previous_reason = tostring(accessxi.records_of_eminence_detail_watch_reason or '');
    accessxi.records_of_eminence_detail_watch_until = tick() + math.max(12000, accessxi.missions_menu_detail_hold_ms(tostring(speech or description)));
    accessxi.records_of_eminence_detail_watch_record_id = record_id;
    accessxi.records_of_eminence_detail_watch_selected = selected;
    accessxi.records_of_eminence_detail_watch_reason = reason;
    if (previous_record_id ~= record_id or previous_selected ~= selected or previous_reason ~= reason) then
        accessxi.records_of_eminence_detail_watch_key = '';
    end
    log_state(('state records-of-eminence detail-watch menu="%s" reason="%s" recordId=%d selected=%d label="%s" until=%d'):fmt(
        tostring(menu_name or ''),
        accessxi.escape_probe_log_text(reason),
        record_id,
        selected,
        accessxi.escape_probe_log_text(label),
        tonumber(accessxi.records_of_eminence_detail_watch_until) or 0));
end

function accessxi.records_of_eminence_detail_line_speech(menu_name, row, record, reason, parts, detail)
    reason = tostring(reason or '');
    if (not (reason == 'confirm-return' or reason == 'comyn-detail' or reason == 'inline-detail' or reason == 'timed-active-row' or reason == 'confirm-return-quest00' or reason == 'direct-detail')) then
        return nil;
    end
    if (reason == 'inline-detail') then
        return nil;
    end
    if ((tostring(menu_name or ''):eq('menu    quest01', true) or tostring(menu_name or ''):eq('menu    quest00', true))
        and not accessxi.records_of_eminence_quest01_detail_surface_active(menu_name)) then
        return nil;
    end
    if (type(parts) ~= 'table' or #parts <= 0 or type(detail) ~= 'table') then
        return nil;
    end

    local native_pos, detail_index = accessxi.records_of_eminence_detail_position_signature(menu_name, reason);
    accessxi.log_records_of_eminence_text_probe(menu_name, row, record, reason, native_pos);
    accessxi.log_records_of_eminence_detail_deep_probe(menu_name, row, record, reason, native_pos);
    log_state(('state records-of-eminence dat-detail-refused menu="%s" reason="%s" recordId=%d selected=%d detailIndex=%d source="%s" nativePos="%s"'):fmt(
        tostring(menu_name or ''),
        accessxi.escape_probe_log_text(reason),
        tonumber(row.record_id) or 0,
        tonumber(row.selected) or 0,
        tonumber(detail_index) or 0,
        accessxi.escape_probe_log_text(type(detail) == 'table' and tostring(detail.source or '') or ''),
        accessxi.escape_probe_log_text(tostring(native_pos or ''))));
    return nil;
end

function accessxi.records_of_eminence_record_source_is_roe_dat(source)
    source = tostring(source or '');
    if (source:find('ROM/307/16.DAT', 1, true) == nil) then
        return false;
    end

    return source:find('dat:ROM/307/16.DAT', 1, true) == 1
        or source:find('dat-native-title-id:ROM/307/16.DAT', 1, true) == 1;
end

function accessxi.log_records_of_eminence_summary_open_refused(menu_name, reason, row, record, cause)
    local now = tick();
    local record_id = type(row) == 'table' and (tonumber(row.record_id) or 0) or 0;
    local selected = type(row) == 'table' and (tonumber(row.selected) or 0) or 0;
    local visible_count = type(row) == 'table' and (tonumber(row.visible_count) or 0) or 0;
    local source = '';
    local label = '';
    local description_len = 0;
    if (type(row) == 'table') then
        source = tostring(row.source or '');
        label = tostring(row.label or '');
    end
    if (type(record) == 'table') then
        if (source == '') then
            source = tostring(record.source or '');
        end
        if (label == '') then
            label = tostring(record.label or '');
        end
        description_len = #tostring(record.description or '');
    end
    local signal = accessxi.records_of_eminence_quest01_row_signal();
    local signal_record_id = type(signal) == 'table' and (tonumber(signal.record_id) or 0) or 0;
    local signal_selected = type(signal) == 'table' and (tonumber(signal.selected) or 0) or 0;
    local signal_visible = type(signal) == 'table' and (tonumber(signal.visible_count) or 0) or 0;
    local signal_slot_id = type(signal) == 'table' and (tonumber(signal.slot_id) or 0) or 0;
    local detail_index = read_current_native_menu_index(0x4C);
    local key = ('%s:%s:%s:%d:%d:%d:%s:%d:%d:%d:%d:0x%04X:%d'):fmt(
        tostring(menu_name or ''),
        tostring(reason or ''),
        tostring(cause or ''),
        record_id,
        selected,
        visible_count,
        source,
        signal_record_id,
        signal_selected,
        signal_visible,
        tonumber(detail_index) or 0,
        signal_slot_id,
        description_len);
    if (key == tostring(accessxi.last_records_of_eminence_summary_open_refused_key or '')
        and (now - (tonumber(accessxi.last_records_of_eminence_summary_open_refused_tick) or 0)) <= 1000) then
        return;
    end
    accessxi.last_records_of_eminence_summary_open_refused_key = key;
    accessxi.last_records_of_eminence_summary_open_refused_tick = now;
    log_state(('state records-of-eminence summary-open-refused menu="%s" reason="%s" cause="%s" rowRecordId=%d rowSelected=%d visible=%d source="%s" label="%s" descriptionLen=%d signalRecordId=%d signalSelected=%d signalVisible=%d slotId=0x%04X detailIndex=%d'):fmt(
        tostring(menu_name or ''),
        accessxi.escape_probe_log_text(tostring(reason or '')),
        accessxi.escape_probe_log_text(tostring(cause or '')),
        record_id,
        selected,
        visible_count,
        accessxi.escape_probe_log_text(source),
        accessxi.escape_probe_log_text(label),
        description_len,
        signal_record_id,
        signal_selected,
        signal_visible,
        signal_slot_id,
        tonumber(detail_index) or 0));
end

function accessxi.records_of_eminence_summary_open_speech(menu_name, row, record, reason)
    menu_name = tostring(menu_name or '');
    reason = tostring(reason or '');
    if (not (reason == 'direct-detail' or reason == 'confirm-return' or reason == 'confirm-return-quest00')) then
        accessxi.log_records_of_eminence_summary_open_refused(menu_name, reason, row, record, 'invalid-reason');
        return false;
    end
    if (not (menu_name:eq('menu    quest01', true) or menu_name:eq('menu    quest00', true))) then
        accessxi.log_records_of_eminence_summary_open_refused(menu_name, reason, row, record, 'unsupported-menu');
        return false;
    end
    if (type(row) ~= 'table' or type(record) ~= 'table') then
        accessxi.log_records_of_eminence_summary_open_refused(menu_name, reason, row, record, 'missing-row');
        return false;
    end

    local record_id = tonumber(row.record_id) or 0;
    local selected = tonumber(row.selected) or 0;
    if (record_id <= 0 or selected <= 0) then
        accessxi.log_records_of_eminence_summary_open_refused(menu_name, reason, row, record, 'invalid-id');
        return false;
    end
    local source = tostring(row.source or record.source or '');
    if (not accessxi.records_of_eminence_record_source_is_roe_dat(source)) then
        accessxi.log_records_of_eminence_summary_open_refused(menu_name, reason, row, record, 'non-dat-source');
        return false;
    end

    local parts = T{};
    local function append(text)
        text = accessxi.sentence_fragment(text);
        if (text ~= '') then
            parts:append(text);
        end
    end

    append(tostring(row.label or record.label or ''));
    for line in tostring(record.description or ''):gmatch('[^\r\n]+') do
        append(line);
    end
    append(accessxi.records_of_eminence_record_number_required_fragment(row, record));
    append(accessxi.records_of_eminence_record_rewards_fragment(record, nil));

    local text = accessxi.speech_output_text(parts:concat(' '));
    if (text == '') then
        accessxi.log_records_of_eminence_summary_open_refused(menu_name, reason, row, record, 'empty-text');
        return false;
    end

    local obj = get_current_menu_object_ptr();
    local now = tick();
    local recent_key = ('%s:%s:%d:%d:0x%08X:%s'):fmt(
        menu_name,
        reason,
        record_id,
        selected,
        tonumber(obj) or 0,
        text);
    if (recent_key == tostring(accessxi.records_of_eminence_summary_open_recent_key or '')
        and (now - (tonumber(accessxi.records_of_eminence_summary_open_recent_tick) or 0)) <= 6000) then
        local suppress_key = ('%s:%d'):fmt(recent_key, math.floor(now / 1000));
        if (suppress_key ~= tostring(accessxi.last_records_of_eminence_summary_open_repeat_suppressed_key or '')) then
            accessxi.last_records_of_eminence_summary_open_repeat_suppressed_key = suppress_key;
            log_state(('state records-of-eminence summary-open-repeat-suppressed menu="%s" reason="%s" recordId=%d selected=%d key="%s"'):fmt(
                menu_name,
                accessxi.escape_probe_log_text(reason),
                record_id,
                selected,
                accessxi.escape_probe_log_text(recent_key)));
        end
        return false;
    end

    local key = ('native-records-of-eminence-summary-open:%s:%s:%d:%d:0x%08X:%s'):fmt(
        menu_name,
        reason,
        record_id,
        selected,
        tonumber(obj) or 0,
        text);
    if (key == tostring(accessxi.records_of_eminence_summary_open_speech_key or '')) then
        accessxi.summary_open_duplicate_key = key;
        return false;
    end

    accessxi.records_of_eminence_summary_open_speech_key = key;
    accessxi.records_of_eminence_summary_open_recent_key = recent_key;
    accessxi.records_of_eminence_summary_open_recent_tick = now;
    accessxi.records_of_eminence_summary_open_list_block_until = now + 2500;
    accessxi.records_of_eminence_summary_open_list_block_record_id = record_id;
    accessxi.records_of_eminence_summary_open_list_block_selected = selected;
    accessxi.records_of_eminence_detail_watch_key = key;
    accessxi.last = text;
    accessxi.last_key = key;
    local speak_result = speak(text);
    if (reason ~= 'direct-detail') then
        accessxi.records_of_eminence_arm_detail_list_speech_suppression(row, text);
    end
    accessxi.records_of_eminence_arm_summary_return_row(row);
    log_state(('state records-of-eminence summary-open-speak menu="%s" reason="%s" result="%s" recordId=%d selected=%d key="%s" text="%s"'):fmt(
        menu_name,
        accessxi.escape_probe_log_text(reason),
        accessxi.escape_probe_log_text(speak_result or ''),
        record_id,
        selected,
        accessxi.escape_probe_log_text(key),
        accessxi.escape_probe_log_text(text)));
    if (text ~= accessxi.last_log or key ~= accessxi.last_log_key) then
        accessxi.last_log = text;
        accessxi.last_log_key = key;
        log_line(text);
    end
    return true;
end

function accessxi.poll_records_of_eminence_summary_open_speech(menu_name)
    if (is_chat_input_open ~= nil and is_chat_input_open()) then
        return false;
    end

    menu_name = tostring(menu_name or get_menu_name() or '');
    if (not (menu_name:eq('menu    quest01', true) or menu_name:eq('menu    quest00', true))) then
        accessxi.records_of_eminence_summary_open_speech_key = '';
        return false;
    end

    if (menu_name:eq('menu    quest01', true)
        and accessxi.records_of_eminence_recent_transition_key(VK_RETURN, 250, 1500)) then
        local signal = accessxi.records_of_eminence_quest01_row_signal();
        local signal_row = accessxi.records_of_eminence_objective_detail_row_from_signal(signal);
        if (type(signal_row) == 'table'
            and type(signal_row.record) == 'table'
            and accessxi.records_of_eminence_direct_objective_detail_surface(signal_row)) then
            if (accessxi.records_of_eminence_summary_open_speech(menu_name, signal_row, signal_row.record, 'direct-detail')) then
                return true;
            end
        end
    end

    if (not accessxi.records_of_eminence_quest01_detail_surface_active(menu_name)) then
        return false;
    end

    local row, record, reason = accessxi.records_of_eminence_detail_context_for_menu(menu_name);
    if (accessxi.records_of_eminence_summary_open_speech(menu_name, row, record, reason)) then
        return true;
    end

    return false;
end

function accessxi.records_of_eminence_surface_dat_summary_speech(menu_name, row, record, reason, detail_index, native_pos_text, miss_reason)
    menu_name = tostring(menu_name or '');
    reason = tostring(reason or '');
    miss_reason = tostring(miss_reason or '');
    if (not (menu_name:eq('menu    quest01', true) or menu_name:eq('menu    quest00', true) or menu_name:eq('menu    comyn', true))) then
        return nil, false;
    end
    if (reason ~= 'direct-detail' and reason ~= 'confirm-return' and reason ~= 'confirm-return-quest00' and reason ~= 'comyn-detail') then
        return nil, false;
    end
    if ((menu_name:eq('menu    quest01', true) or menu_name:eq('menu    quest00', true))
        and not accessxi.records_of_eminence_quest01_detail_surface_active(menu_name)) then
        return nil, false;
    end
    if (type(row) ~= 'table' or type(record) ~= 'table') then
        return nil, false;
    end

    local row_record_id = tonumber(row.record_id) or 0;
    local row_selected = tonumber(row.selected) or 0;
    if (row_record_id <= 0 or row_selected <= 0) then
        return nil, false;
    end

    local is_quest01 = menu_name:eq('menu    quest01', true);
    local quest01_signal;
    if (is_quest01) then
        quest01_signal = accessxi.records_of_eminence_quest01_row_signal();
        local navigation = accessxi.records_of_eminence_detail_navigation;
        local signal_matches;
        if (type(navigation) == 'table' and type(navigation.signal_matches_row) == 'function') then
            signal_matches = navigation.signal_matches_row(quest01_signal, row) == true;
        else
            -- Safe fallback: same dynamic rules as the module, no fixed row count.
            signal_matches = type(quest01_signal) == 'table'
                and (tonumber(quest01_signal.record_id) or 0) == row_record_id
                and (tonumber(quest01_signal.selected) or 0) == row_selected
                and (tonumber(quest01_signal.visible_count) or 0) > 0
                and (tonumber(quest01_signal.slot_id) or 0) >= 0xE001;
        end
        if (not signal_matches) then
            return nil, false;
        end
    end

    local source = tostring(record.source or '');
    if (not accessxi.records_of_eminence_record_source_is_roe_dat(source)) then
        return nil, false;
    end
    local parts, detail = accessxi.records_of_eminence_record_display_detail_parts(row, record);
    if (type(parts) ~= 'table' or #parts <= 0 or type(detail) ~= 'table') then
        return nil, false;
    end

    detail_index = tonumber(detail_index) or 0;
    local kinds = type(detail.kinds) == 'table' and detail.kinds or T{};
    local effective_display_index = 0;
    local text = '';
    local handled = false;

    local navigation = accessxi.records_of_eminence_detail_navigation;
    if (is_quest01) then
        local resolved_text, resolved_index, resolve_reason, resolved_handled;
        if (type(navigation) == 'table' and type(navigation.resolve_dat_line) == 'function') then
            resolved_text, resolved_index, resolve_reason, resolved_handled =
                navigation.resolve_dat_line(detail_index, parts, kinds, quest01_signal, row);
        end
        handled = resolved_handled == true;
        if (not handled) then
            return nil, false;
        end
        effective_display_index = tonumber(resolved_index) or 0;
        if (resolved_text ~= nil) then
            text = tostring(resolved_text);
        else
            miss_reason = tostring(resolve_reason or miss_reason);
        end
    else
        local display_index = accessxi.records_of_eminence_native_detail_display_line_index(detail_index, row);
        local bottom_start = 0;
        for index, kind in ipairs(kinds) do
            kind = tostring(kind or '');
            if (kind == 'number-required' or kind == 'rewards') then
                bottom_start = index;
                break;
            end
        end
        effective_display_index = display_index;
        if (bottom_start > 0 and bottom_start >= 5 and display_index >= 3) then
            effective_display_index = bottom_start + (display_index - 3);
        end
        if (effective_display_index >= 1 and effective_display_index <= #parts) then
            text = tostring(parts[effective_display_index] or '');
        elseif (detail_index <= 0 and #parts > 0) then
            text = parts:concat('. ');
        end
        -- quest00/comyn: verified DAT mapping attempt has occurred regardless of outcome.
        handled = true;
    end

    text = accessxi.plain_native_menu_help(text);
    if (text == '') then
        local refused_key = ('%s:%s:%d:%d:%d:%d:%d'):fmt(
            menu_name,
            miss_reason,
            row_record_id,
            row_selected,
            detail_index,
            effective_display_index,
            #parts);
        if (refused_key ~= tostring(accessxi.last_records_of_eminence_dat_summary_refused_key or '')) then
            accessxi.last_records_of_eminence_dat_summary_refused_key = refused_key;
            log_state(('state records-of-eminence dat-summary-surface-refused menu="%s" reason="%s" miss="%s" recordId=%d selected=%d detailIndex=%d displayIndex=%d lines=%d source="%s" nativePos="%s"'):fmt(
                menu_name,
                accessxi.escape_probe_log_text(reason),
                accessxi.escape_probe_log_text(miss_reason),
                row_record_id,
                row_selected,
                detail_index,
                effective_display_index,
                #parts,
                accessxi.escape_probe_log_text(source),
                accessxi.escape_probe_log_text(tostring(native_pos_text or ''))));
        end
        return nil, handled;
    end

    local kind = tostring(kinds[effective_display_index] or '');
    local key_detail_index = detail_index;
    local key = ('native-records-of-eminence-resource-detail-surface:%s:%s:%s:%d:%d:%d:%s'):fmt(
        menu_name,
        reason,
        miss_reason,
        row_record_id,
        row_selected,
        key_detail_index,
        text);
    accessxi.last_native_menu_name = menu_name;
    accessxi.last_native_menu_label = text;
    accessxi.last_native_menu_selected = detail_index;
    accessxi.last_native_menu_tick = tick();
    accessxi.current_speech_key = key;
    if (key ~= tostring(accessxi.records_of_eminence_detail_watch_key or '')
        and key ~= tostring(accessxi.last_key or '')) then
        log_state(('state records-of-eminence resource-detail-surface menu="%s" reason="%s" miss="%s" recordId=%d selected=%d detailIndex=%d displayIndex=%d lines=%d kind="%s" text="%s" source="%s" nativePos="%s"'):fmt(
            menu_name,
            accessxi.escape_probe_log_text(reason),
            accessxi.escape_probe_log_text(miss_reason),
            row_record_id,
            row_selected,
            detail_index,
            effective_display_index,
            #parts,
            accessxi.escape_probe_log_text(kind),
            accessxi.escape_probe_log_text(text),
            accessxi.escape_probe_log_text(source),
            accessxi.escape_probe_log_text(tostring(native_pos_text or ''))));
    end
    return text, handled;
end

function accessxi.records_of_eminence_row_detail_speech(menu_name, row, record, reason)
    if (type(row) ~= 'table' or type(record) ~= 'table') then
        return nil;
    end
    if (tostring(reason or '') == 'inline-detail') then
        return nil;
    end

    local label = tostring(row.label or record.label or '');
    if (label == '') then
        return nil;
    end

    local parts, detail = accessxi.records_of_eminence_record_detail_parts(row, record);
    if (type(detail) ~= 'table' or #parts <= 0) then
        accessxi.records_of_eminence_log_missing_detail(menu_name, row, record, reason);
        return nil;
    end
    local native_pos = accessxi.records_of_eminence_detail_position_signature(menu_name, reason);
    accessxi.log_records_of_eminence_text_probe(menu_name, row, record, reason, native_pos);
    accessxi.log_records_of_eminence_detail_deep_probe(menu_name, row, record, reason, native_pos);
    if (not accessxi.records_of_eminence_should_start_with_full_detail(row, reason)) then
        local line_text = accessxi.records_of_eminence_detail_line_speech(menu_name, row, record, reason, parts, detail);
        if (line_text ~= nil and line_text ~= '') then
            return line_text;
        end
    end
    if (tostring(reason or '') == 'timed-active-row') then
        return nil;
    end
    log_state(('state records-of-eminence dat-detail-full-refused menu="%s" reason="%s" recordId=%d selected=%d label="%s" source="%s"'):fmt(
        tostring(menu_name or ''),
        accessxi.escape_probe_log_text(tostring(reason or '')),
        tonumber(row.record_id) or 0,
        tonumber(row.selected) or 0,
        accessxi.escape_probe_log_text(label),
        accessxi.escape_probe_log_text(tostring(detail.source or ''))));
    return nil;
end

function accessxi.records_of_eminence_native_detail_surface_speech(menu_name, row, record, reason)
    menu_name = tostring(menu_name or '');
    reason = tostring(reason or '');
    if (type(row) ~= 'table' or type(record) ~= 'table') then
        return nil;
    end

    if ((menu_name:eq('menu    quest01', true) or menu_name:eq('menu    quest00', true))
        and not accessxi.records_of_eminence_quest01_detail_surface_active(menu_name)) then
        return nil;
    end

    if (menu_name:eq('menu    quest01', true)) then
        local signal = accessxi.records_of_eminence_quest01_row_signal();
        if (type(signal) == 'table' and (tonumber(signal.record_id) or 0) > 0) then
            local row_record_id = tonumber(row.record_id) or 0;
            local row_selected = tonumber(row.selected) or 0;
            local signal_record_id = tonumber(signal.record_id) or 0;
            local signal_selected = tonumber(signal.selected) or 0;
            if (signal_record_id ~= row_record_id or signal_selected ~= row_selected) then
                log_state(('state records-of-eminence native-detail-refused-list-surface menu="%s" reason="%s" rowRecordId=%d rowSelected=%d signalRecordId=%d signalSelected=%d visible=%d slotId=0x%04X'):fmt(
                    menu_name,
                    accessxi.escape_probe_log_text(reason),
                    row_record_id,
                    row_selected,
                    signal_record_id,
                    signal_selected,
                    tonumber(signal.visible_count) or 0,
                    tonumber(signal.slot_id) or 0));
                return nil;
            end
        end
    end

    local label = tostring(row.label or record.label or '');
    local native_pos, detail_index = accessxi.records_of_eminence_detail_position_signature(menu_name, reason);
    local native_pos_text = tostring(native_pos or '');
    local function surface_dat_summary(miss_reason)
        return accessxi.records_of_eminence_surface_dat_summary_speech(menu_name, row, record, reason, detail_index, native_pos_text, miss_reason);
    end
    local structured_dat_text, structured_dat_handled = surface_dat_summary('native-structured-detail');
    if (structured_dat_handled == true) then
        return structured_dat_text or '';
    end
    if (structured_dat_text ~= nil and structured_dat_text ~= '') then
        return structured_dat_text;
    end
    local target_help = accessxi.records_of_eminence_target_help_detail_surface(label);
    if (type(target_help) == 'table' and target_help.matched == true and type(target_help.lines) == 'table') then
        local lines = T{};
        for _, line in ipairs(target_help.lines) do
            lines:append(tostring(type(line) == 'table' and line.text or line or ''));
        end

        local text = '';
        detail_index = tonumber(detail_index) or 0;
        local display_index = accessxi.records_of_eminence_native_detail_display_line_index(detail_index, row);
        if (display_index >= 1 and display_index <= #lines) then
            text = tostring(lines[display_index] or '');
        elseif (#lines == 1 and detail_index <= 1) then
            text = tostring(lines[1] or '');
        elseif (detail_index <= 0) then
            text = lines:concat('. ');
        end
        text = accessxi.plain_native_menu_help(text);
        if (text ~= '') then
            local key = ('native-records-of-eminence-target-help:%s:%s:%d:%d:%d:%s'):fmt(
                menu_name,
                reason,
                tonumber(row.record_id) or 0,
                tonumber(row.selected) or 0,
                detail_index,
                text);
            accessxi.last_native_menu_name = menu_name;
            accessxi.last_native_menu_label = text;
            accessxi.last_native_menu_selected = detail_index;
            accessxi.last_native_menu_tick = tick();
            accessxi.current_speech_key = key;
            log_state(('state records-of-eminence native-detail-target-help menu="%s" reason="%s" recordId=%d selected=%d detailIndex=%d lines=%d text="%s" target="%s" nativePos="%s"'):fmt(
                menu_name,
                accessxi.escape_probe_log_text(reason),
                tonumber(row.record_id) or 0,
                tonumber(row.selected) or 0,
                detail_index,
                #lines,
                accessxi.escape_probe_log_text(text),
                accessxi.escape_probe_log_text_wide(tostring(target_help.summary or '')),
                accessxi.escape_probe_log_text(native_pos_text)));
            return text;
        end
    end
    if (menu_name:eq('menu    quest01', true)
        and (reason == 'direct-detail' or reason == 'native-detail-motion' or reason == 'confirm-return')) then
        local detail_obj = get_current_menu_object_ptr();
        local summary_cache_key = ('%s:%d:%d:0x%08X:%s'):fmt(
            menu_name,
            tonumber(row.record_id) or 0,
            tonumber(row.selected) or 0,
            tonumber(detail_obj) or 0,
            label);
        local function render_cached_summary(lines, cache_source, log_tag, native_source, native_target, native_summary)
            if (type(lines) ~= 'table' or #lines <= 0) then
                return nil;
            end
            local display_lines = T{};
            for _, line in ipairs(lines) do
                display_lines:append(tostring(type(line) == 'table' and line.text or line or ''));
            end

            local text = '';
            detail_index = tonumber(detail_index) or 0;
            local display_index = accessxi.records_of_eminence_native_detail_display_line_index(detail_index, row);
            if (detail_index == 1 and #display_lines > 1 and reason == 'direct-detail') then
                text = display_lines:concat('. ');
            elseif (display_index >= 1 and display_index <= #display_lines) then
                text = tostring(display_lines[display_index] or '');
            elseif (detail_index <= 0 and #display_lines > 0) then
                text = display_lines:concat('. ');
            end
            text = accessxi.plain_native_menu_help(text);
            if (text == '') then
                return nil;
            end

            local key = ('native-records-of-eminence-%s:%s:%s:%d:%d:%d:%s'):fmt(
                tostring(cache_source or 'summary'),
                menu_name,
                reason,
                tonumber(row.record_id) or 0,
                tonumber(row.selected) or 0,
                detail_index,
                text);
            accessxi.last_native_menu_name = menu_name;
            accessxi.last_native_menu_label = text;
            accessxi.last_native_menu_selected = detail_index;
            accessxi.last_native_menu_tick = tick();
            accessxi.current_speech_key = key;
            if (key ~= tostring(accessxi.records_of_eminence_detail_watch_key or '')) then
                log_state(('state records-of-eminence %s menu="%s" reason="%s" recordId=%d selected=%d detailIndex=%d lines=%d text="%s" source="%s" target=0x%08X summary="%s" nativePos="%s"'):fmt(
                    tostring(log_tag or 'native-detail-cached-summary'),
                    menu_name,
                    accessxi.escape_probe_log_text(reason),
                    tonumber(row.record_id) or 0,
                    tonumber(row.selected) or 0,
                    detail_index,
                    #display_lines,
                    accessxi.escape_probe_log_text(text),
                    accessxi.escape_probe_log_text(tostring(native_source or '')),
                    tonumber(native_target) or 0,
                    accessxi.escape_probe_log_text_wide(tostring(native_summary or '')),
                    accessxi.escape_probe_log_text(native_pos_text)));
            end
            return text;
        end
        local cached_summary = accessxi.records_of_eminence_native_detail_summary_cache;
        if (type(cached_summary) == 'table'
            and tostring(cached_summary.key or '') == summary_cache_key
            and (tick() - (tonumber(cached_summary.tick) or 0)) <= 8000) then
            local cached_text = render_cached_summary(
                cached_summary.lines,
                tostring(cached_summary.cache_source or 'cached-summary'),
                'native-detail-cached-summary',
                cached_summary.source,
                cached_summary.target,
                cached_summary.summary);
            if (cached_text ~= nil) then
                return cached_text;
            end
        end
        local miss_key = ('%s:%d'):fmt(summary_cache_key, tonumber(detail_index) or 0);
        if (tostring(accessxi.records_of_eminence_native_detail_miss_key or '') == miss_key
            and (tick() - (tonumber(accessxi.records_of_eminence_native_detail_miss_tick) or 0)) <= 1200) then
            return nil;
        end
        local obj0f0_summary = accessxi.records_of_eminence_obj0f0_native_summary_lines(label);
        if (type(obj0f0_summary) == 'table' and obj0f0_summary.matched == true and type(obj0f0_summary.lines) == 'table') then
            local lines = T{};
            for _, line in ipairs(obj0f0_summary.lines) do
                lines:append(tostring(type(line) == 'table' and line.text or line or ''));
            end

            local text = '';
            detail_index = tonumber(detail_index) or 0;
            if (detail_index > 1 and (detail_index - 1) <= #lines) then
                text = tostring(lines[detail_index - 1] or '');
            elseif (detail_index <= 0 and #lines > 0) then
                text = lines:concat('. ');
            end
            text = accessxi.plain_native_menu_help(text);
            if (text ~= '') then
                local key = ('native-records-of-eminence-obj0f0-summary:%s:%s:%d:%d:%d:%s'):fmt(
                    menu_name,
                    reason,
                    tonumber(row.record_id) or 0,
                    tonumber(row.selected) or 0,
                    detail_index,
                    text);
                accessxi.last_native_menu_name = menu_name;
                accessxi.last_native_menu_label = text;
                accessxi.last_native_menu_selected = detail_index;
                accessxi.last_native_menu_tick = tick();
                accessxi.current_speech_key = key;
                log_state(('state records-of-eminence native-detail-obj0f0-summary menu="%s" reason="%s" recordId=%d selected=%d detailIndex=%d lines=%d text="%s" source="%s" target=0x%08X summary="%s" nativePos="%s"'):fmt(
                    menu_name,
                    accessxi.escape_probe_log_text(reason),
                    tonumber(row.record_id) or 0,
                    tonumber(row.selected) or 0,
                    detail_index,
                    #lines,
                    accessxi.escape_probe_log_text(text),
                    accessxi.escape_probe_log_text(tostring(obj0f0_summary.source or '')),
                    tonumber(obj0f0_summary.target) or 0,
                    accessxi.escape_probe_log_text_wide(tostring(obj0f0_summary.summary or '')),
                    accessxi.escape_probe_log_text(native_pos_text)));
                return text;
            end
        end

        local obj014_summary = accessxi.records_of_eminence_obj014_native_summary_lines(label);
        if (type(obj014_summary) == 'table' and obj014_summary.matched == true and type(obj014_summary.lines) == 'table') then
            accessxi.records_of_eminence_native_detail_summary_cache = {
                key = summary_cache_key,
                tick = tick(),
                lines = obj014_summary.lines,
