            };
            local lines = T{};
            for _, line in ipairs(obj014_summary.lines) do
                lines:append(tostring(type(line) == 'table' and line.text or line or ''));
            end

            local text = '';
            detail_index = tonumber(detail_index) or 0;
            local display_index = accessxi.records_of_eminence_native_detail_display_line_index(detail_index, row);
            if (detail_index == 1 and #lines > 1 and reason == 'direct-detail') then
                text = lines:concat('. ');
            elseif (display_index >= 1 and display_index <= #lines) then
                text = tostring(lines[display_index] or '');
            elseif (detail_index <= 0 and #lines > 0) then
                text = lines:concat('. ');
            end
            text = accessxi.plain_native_menu_help(text);
            if (text ~= '') then
                local key = ('native-records-of-eminence-obj014-summary:%s:%s:%d:%d:%d:%s'):fmt(
                    menu_name,
                    reason,
                    tonumber(row.record_id) or 0,
                    tonumber(row.selected) or 0,
                    detail_index,
                    text);
                accessxi.last_native_menu_name = menu_name;
                accessxi.last_native_menu_label = text;
                accessxi.last_native_menu_selected = detail_index;
                accessxi.last_native_menu_tick = tick();
                accessxi.current_speech_key = key;
                log_state(('state records-of-eminence native-detail-obj014-summary menu="%s" reason="%s" recordId=%d selected=%d detailIndex=%d lines=%d text="%s" source="%s" target=0x%08X summary="%s" nativePos="%s"'):fmt(
                    menu_name,
                    accessxi.escape_probe_log_text(reason),
                    tonumber(row.record_id) or 0,
                    tonumber(row.selected) or 0,
                    detail_index,
                    #lines,
                    accessxi.escape_probe_log_text(text),
                    accessxi.escape_probe_log_text(tostring(obj014_summary.source or '')),
                    tonumber(obj014_summary.target) or 0,
                    accessxi.escape_probe_log_text_wide(tostring(obj014_summary.summary or '')),
                    accessxi.escape_probe_log_text(native_pos_text)));
                return text;
            end
        end

        local obj018_summary = accessxi.records_of_eminence_obj018_native_summary_lines(label);
        if (type(obj018_summary) == 'table' and obj018_summary.matched == true and type(obj018_summary.lines) == 'table') then
            accessxi.records_of_eminence_native_detail_summary_cache = {
                key = summary_cache_key,
                tick = tick(),
                lines = obj018_summary.lines,
                cache_source = 'obj018-summary',
                source = tostring(obj018_summary.source or ''),
                target = tonumber(obj018_summary.target) or 0,
                summary = tostring(obj018_summary.summary or ''),
            };
            local lines = T{};
            for _, line in ipairs(obj018_summary.lines) do
                lines:append(tostring(type(line) == 'table' and line.text or line or ''));
            end

            local text = '';
            detail_index = tonumber(detail_index) or 0;
            local display_index = accessxi.records_of_eminence_native_detail_display_line_index(detail_index, row);
            if (detail_index == 1 and #lines > 1 and reason == 'direct-detail') then
                text = lines:concat('. ');
            elseif (display_index >= 1 and display_index <= #lines) then
                text = tostring(lines[display_index] or '');
            elseif (detail_index <= 0 and #lines > 0) then
                text = lines:concat('. ');
            end
            text = accessxi.plain_native_menu_help(text);
            if (text ~= '') then
                local key = ('native-records-of-eminence-obj018-summary:%s:%s:%d:%d:%d:%s'):fmt(
                    menu_name,
                    reason,
                    tonumber(row.record_id) or 0,
                    tonumber(row.selected) or 0,
                    detail_index,
                    text);
                accessxi.last_native_menu_name = menu_name;
                accessxi.last_native_menu_label = text;
                accessxi.last_native_menu_selected = detail_index;
                accessxi.last_native_menu_tick = tick();
                accessxi.current_speech_key = key;
                log_state(('state records-of-eminence native-detail-obj018-summary menu="%s" reason="%s" recordId=%d selected=%d detailIndex=%d lines=%d text="%s" source="%s" target=0x%08X summary="%s" nativePos="%s"'):fmt(
