        local entry_summary = accessxi.records_of_eminence_current_entry_native_detail_lines(label);
        if (type(entry_summary) == 'table' and entry_summary.matched == true and type(entry_summary.lines) == 'table') then
            local lines = T{};
            for _, line in ipairs(entry_summary.lines) do
                lines:append(tostring(type(line) == 'table' and line.text or line or ''));
            end

            local text = accessxi.plain_native_menu_help(lines:concat('. '));
            if (text ~= '') then
                local key = ('native-records-of-eminence-entry-line:%s:%s:%d:%d:%d:%s'):fmt(
                    menu_name,
                    reason,
                    tonumber(row.record_id) or 0,
