                    #lines,
                    accessxi.escape_probe_log_text(text),
                    accessxi.escape_probe_log_text(tostring(entry_summary.source or '')),
                    tonumber(entry_summary.target) or 0,
                    accessxi.escape_probe_log_text_wide(tostring(entry_summary.summary or '')),
                    accessxi.escape_probe_log_text(native_pos_text)));
                return text;
            end
        elseif (tonumber(detail_index) > 3) then
            local entry_miss_key = ('%s:%s:%d:%d:%d:%s'):fmt(
                menu_name,
                reason,
                tonumber(row.record_id) or 0,
                tonumber(row.selected) or 0,
                tonumber(detail_index) or 0,
                tostring(type(entry_summary) == 'table' and entry_summary.summary or ''));
            if (entry_miss_key ~= tostring(accessxi.records_of_eminence_entry_line_miss_key or '')) then
                accessxi.records_of_eminence_entry_line_miss_key = entry_miss_key;
                log_state(('state records-of-eminence native-detail-entry-line-miss menu="%s" reason="%s" recordId=%d selected=%d detailIndex=%d matched=%s lines=%d source="%s" target=0x%08X summary="%s" nativePos="%s"'):fmt(
                    menu_name,
                    accessxi.escape_probe_log_text(reason),
                    tonumber(row.record_id) or 0,
                    tonumber(row.selected) or 0,
                    tonumber(detail_index) or 0,
                    tostring(type(entry_summary) == 'table' and entry_summary.matched == true),
                    type(entry_summary) == 'table' and #(entry_summary.lines or T{}) or 0,
                    accessxi.escape_probe_log_text(type(entry_summary) == 'table' and tostring(entry_summary.source or '') or ''),
                    type(entry_summary) == 'table' and (tonumber(entry_summary.target) or 0) or 0,
                    accessxi.escape_probe_log_text_wide(type(entry_summary) == 'table' and tostring(entry_summary.summary or '') or ''),
                    accessxi.escape_probe_log_text(native_pos_text)));
            end
        end
        accessxi.records_of_eminence_native_detail_miss_key = miss_key;
        accessxi.records_of_eminence_native_detail_miss_tick = tick();
    end
    if (menu_name:eq('menu    quest01', true) and reason == 'direct-detail') then
        local shape_lines, _, shape_line_summary = accessxi.records_of_eminence_collect_native_detail_shape_lines(label);
        local native_line_summary = accessxi.records_of_eminence_native_detail_candidate_summary(shape_lines, 20);
        log_state(('state records-of-eminence native-detail-target-help-unmatched-direct menu="%s" reason="%s" recordId=%d selected=%d label="%s" detailIndex=%d target="%s" shapeLines="%s" nativePos="%s"'):fmt(
            menu_name,
            accessxi.escape_probe_log_text(reason),
            tonumber(row.record_id) or 0,
            tonumber(row.selected) or 0,
            accessxi.escape_probe_log_text(label),
            tonumber(detail_index) or 0,
            accessxi.escape_probe_log_text_wide(type(target_help) == 'table' and tostring(target_help.summary or '') or ''),
            accessxi.escape_probe_log_text_wide(native_line_summary),
            accessxi.escape_probe_log_text(native_pos_text)));
