    local allow_zero_origin_detail = menu_name:eq('menu    quest01', true)
        and (accessxi.records_of_eminence_quest01_detail_surface_active(menu_name)
            or accessxi.records_of_eminence_native_motion_detail_active(menu_name));
    if (native_pos_text:match('ank=%-?%d+,0,0') ~= nil and not allow_zero_origin_detail) then
        local stale_shape_lines, _, stale_shape_summary = accessxi.records_of_eminence_collect_native_detail_shape_lines(label);
        local stale_shape_line_summary = accessxi.records_of_eminence_native_detail_candidate_summary(stale_shape_lines, 20);
        log_state(('state records-of-eminence native-detail-refused-stale-position menu="%s" reason="%s" recordId=%d selected=%d label="%s" detailIndex=%d shape="%s" shapeLines="%s" nativePos="%s"'):fmt(
            menu_name,
            accessxi.escape_probe_log_text(reason),
            tonumber(row.record_id) or 0,
            tonumber(row.selected) or 0,
            accessxi.escape_probe_log_text(label),
            tonumber(detail_index) or 0,
            accessxi.escape_probe_log_text_wide(tostring(stale_shape_summary or '')),
            accessxi.escape_probe_log_text_wide(stale_shape_line_summary),
            accessxi.escape_probe_log_text(native_pos_text)));
        return nil;
    end
    if (native_pos_text:match('ank=0,') ~= nil and not allow_zero_origin_detail) then
        local stale_shape_lines, _, stale_shape_summary = accessxi.records_of_eminence_collect_native_detail_shape_lines(label);
        local stale_shape_line_summary = accessxi.records_of_eminence_native_detail_candidate_summary(stale_shape_lines, 20);
        log_state(('state records-of-eminence native-detail-refused-stale-position menu="%s" reason="%s" recordId=%d selected=%d label="%s" detailIndex=%d shape="%s" shapeLines="%s" nativePos="%s"'):fmt(
            menu_name,
            accessxi.escape_probe_log_text(reason),
            tonumber(row.record_id) or 0,
            tonumber(row.selected) or 0,
            accessxi.escape_probe_log_text(label),
            tonumber(detail_index) or 0,
            accessxi.escape_probe_log_text_wide(tostring(stale_shape_summary or '')),
            accessxi.escape_probe_log_text_wide(stale_shape_line_summary),
            accessxi.escape_probe_log_text(native_pos_text)));
        return nil;
    end

    local obj = get_current_menu_object_ptr();
    if (not accessxi.is_probe_pointer(obj)) then
        log_state(('state records-of-eminence native-detail-refused-no-object menu="%s" reason="%s" recordId=%d selected=%d label="%s" target="%s" nativePos="%s"'):fmt(
            menu_name,
            accessxi.escape_probe_log_text(reason),
            tonumber(row.record_id) or 0,
            tonumber(row.selected) or 0,
            accessxi.escape_probe_log_text(label),
            accessxi.escape_probe_log_text_wide(type(target_help) == 'table' and tostring(target_help.summary or '') or ''),
            accessxi.escape_probe_log_text(tostring(native_pos or ''))));
        return nil;
    end

    local child = read_u32(obj + 0x04) or 0;
    local entry = read_u32(obj + 0x08) or 0;
    local lines, anchor_found = accessxi.records_of_eminence_collect_native_detail_buffer_lines(obj, label);
    local shape_lines, shape_anchor, shape_line_summary = accessxi.records_of_eminence_collect_native_detail_shape_lines(label);
    if (type(shape_lines) == 'table') then
        for _, line in ipairs(shape_lines) do
            lines:append(line);
        end
    end
    anchor_found = anchor_found == true or shape_anchor == true;
    local seen = {};
    local candidates = T{};
    accessxi.inline_info_collect_strings(obj, 'obj', seen, candidates, 'records-of-eminence');
    accessxi.inline_info_collect_strings(child, 'child', seen, candidates, 'records-of-eminence');
    accessxi.inline_info_collect_strings(entry, 'entry', seen, candidates, 'records-of-eminence');
    local shape_summary = accessxi.inline_info_collect_window_shape_strings(seen, candidates, 'records-of-eminence');

    local native_line_summary = accessxi.records_of_eminence_native_detail_candidate_summary(lines, 14);
    local shape_native_line_summary = accessxi.records_of_eminence_native_detail_candidate_summary(shape_lines, 20);
    if (#lines <= 0) then
        accessxi.log_inline_info_menu_probe(menu_name, 'Records of Eminence Detail', obj, tonumber(row.selected) or 0, #lines, 0, 0, child, entry, ('roe-native-detail-missing:%s'):fmt(reason), candidates:concat(' || '), shape_summary);
        log_state(('state records-of-eminence native-detail-refused-missing menu="%s" reason="%s" recordId=%d selected=%d label="%s" target="%s" shape="%s" shapeLines="%s" nativePos="%s"'):fmt(
            menu_name,
            accessxi.escape_probe_log_text(reason),
            tonumber(row.record_id) or 0,
            tonumber(row.selected) or 0,
            accessxi.escape_probe_log_text(label),
            accessxi.escape_probe_log_text_wide(type(target_help) == 'table' and tostring(target_help.summary or '') or ''),
            accessxi.escape_probe_log_text_wide(tostring(shape_line_summary or '')),
            accessxi.escape_probe_log_text_wide(shape_native_line_summary),
            accessxi.escape_probe_log_text(native_pos_text)));
        local dat_text = surface_dat_summary('native-missing');
        if (dat_text ~= nil and dat_text ~= '') then
            return dat_text;
        end
        return nil;
    end
    local anchor_label, anchor_summary = accessxi.records_of_eminence_native_detail_display_anchor_label(lines, label);
    if (anchor_label ~= '') then
        if (not accessxi.records_of_eminence_detail_label_match(anchor_label, label)) then
            log_state(('state records-of-eminence native-detail-display-anchor menu="%s" reason="%s" recordId=%d selected=%d rowLabel="%s" anchorLabel="%s" detailIndex=%d anchors="%s" nativePos="%s"'):fmt(
                menu_name,
                accessxi.escape_probe_log_text(reason),
                tonumber(row.record_id) or 0,
                tonumber(row.selected) or 0,
                accessxi.escape_probe_log_text(label),
                accessxi.escape_probe_log_text(anchor_label),
                tonumber(detail_index) or 0,
                accessxi.escape_probe_log_text_wide(tostring(anchor_summary or '')),
                accessxi.escape_probe_log_text(tostring(native_pos or ''))));
        end
        label = anchor_label;
        anchor_found = true;
    end
    if (anchor_found ~= true) then
        log_state(('state records-of-eminence native-detail-refused-unanchored menu="%s" reason="%s" recordId=%d selected=%d label="%s" detailIndex=%d target="%s" shape="%s" shapeLines="%s" anchors="%s" nativeLines="%s" candidates="%s" nativePos="%s"'):fmt(
            menu_name,
            accessxi.escape_probe_log_text(reason),
            tonumber(row.record_id) or 0,
            tonumber(row.selected) or 0,
            accessxi.escape_probe_log_text(label),
            tonumber(detail_index) or 0,
            accessxi.escape_probe_log_text_wide(type(target_help) == 'table' and tostring(target_help.summary or '') or ''),
            accessxi.escape_probe_log_text_wide(tostring(shape_line_summary or '')),
            accessxi.escape_probe_log_text_wide(shape_native_line_summary),
            accessxi.escape_probe_log_text_wide(tostring(anchor_summary or '')),
            accessxi.escape_probe_log_text_wide(native_line_summary),
            accessxi.escape_probe_log_text_wide(candidates:concat(' || ')),
            accessxi.escape_probe_log_text(native_pos_text)));
        local dat_text = surface_dat_summary('native-unanchored');
        if (dat_text ~= nil and dat_text ~= '') then
            return dat_text;
        end
        return nil;
    end
    local summary_lines, summary_ok, group_summary = accessxi.records_of_eminence_native_detail_filter_summary_groups(lines, label);
    if (summary_ok ~= true) then
        local dat_text = surface_dat_summary('native-no-summary');
        if (dat_text ~= nil and dat_text ~= '') then
            return dat_text;
        end
        local refusal_native_line_summary = native_line_summary;
        if ((tonumber(detail_index) or 0) > 3) then
            refusal_native_line_summary = accessxi.records_of_eminence_native_detail_candidate_summary(lines, 80);
        end
        log_state(('state records-of-eminence native-detail-refused-no-summary-surface menu="%s" reason="%s" recordId=%d selected=%d label="%s" detailIndex=%d target="%s" shape="%s" shapeLines="%s" anchors="%s" groups="%s" nativeLines="%s" candidates="%s" nativePos="%s"'):fmt(
            menu_name,
            accessxi.escape_probe_log_text(reason),
            tonumber(row.record_id) or 0,
            tonumber(row.selected) or 0,
            accessxi.escape_probe_log_text(label),
            tonumber(detail_index) or 0,
            accessxi.escape_probe_log_text_wide(type(target_help) == 'table' and tostring(target_help.summary or '') or ''),
            accessxi.escape_probe_log_text_wide(tostring(shape_line_summary or '')),
            accessxi.escape_probe_log_text_wide(shape_native_line_summary),
            accessxi.escape_probe_log_text_wide(tostring(anchor_summary or '')),
            accessxi.escape_probe_log_text_wide(group_summary),
            accessxi.escape_probe_log_text_wide(refusal_native_line_summary),
            accessxi.escape_probe_log_text_wide(candidates:concat(' || ')),
            accessxi.escape_probe_log_text(native_pos_text)));
        return nil;
    end
    lines = summary_lines;
    native_line_summary = accessxi.records_of_eminence_native_detail_candidate_summary(lines, 14);
    local display_lines = T{};
    for _, line in ipairs(lines) do
        display_lines:append(tostring(type(line) == 'table' and line.text or line or ''));
    end
    lines = display_lines;

    local text = '';
    detail_index = tonumber(detail_index) or 0;
    local display_index = accessxi.records_of_eminence_native_detail_display_line_index(detail_index, row);
    if (display_index >= 1 and display_index <= #lines) then
        text = tostring(lines[display_index] or '');
    elseif (#lines == 1 and detail_index <= 1) then
        text = tostring(lines[1] or '');
    elseif (detail_index <= 0) then
        text = lines:concat('. ');
    end
    text = accessxi.plain_native_menu_help(text);
    if (text == '') then
        local dat_text = surface_dat_summary('native-empty-line');
        if (dat_text ~= nil and dat_text ~= '') then
            return dat_text;
        end
        return nil;
    end

    local key = ('native-records-of-eminence-detail-text:%s:%s:%d:%d:%d:%s'):fmt(
        menu_name,
        reason,
        tonumber(row.record_id) or 0,
        tonumber(row.selected) or 0,
        detail_index,
        text);
    accessxi.last_native_menu_name = menu_name;
    accessxi.last_native_menu_label = text;
    accessxi.last_native_menu_selected = detail_index;
    accessxi.last_native_menu_tick = tick();
    accessxi.current_speech_key = key;
    log_state(('state records-of-eminence native-detail menu="%s" reason="%s" recordId=%d selected=%d anchorLabel="%s" detailIndex=%d lines=%d text="%s" nativeLines="%s" shape="%s" candidates="%s" nativePos="%s"'):fmt(
        menu_name,
        accessxi.escape_probe_log_text(reason),
        tonumber(row.record_id) or 0,
        tonumber(row.selected) or 0,
        accessxi.escape_probe_log_text(label),
        detail_index,
        #lines,
        accessxi.escape_probe_log_text(text),
        accessxi.escape_probe_log_text_wide(native_line_summary),
        accessxi.escape_probe_log_text_wide(tostring(shape_line_summary or '')),
        accessxi.escape_probe_log_text_wide(candidates:concat(' || ')),
        accessxi.escape_probe_log_text(tostring(native_pos or ''))));
    return text;
end

function accessxi.records_of_eminence_pending_confirm_detail(row)
    if (type(row) ~= 'table') then
        return false;
    end
    local record_id = tonumber(row.record_id) or 0;
    if (record_id <= 0 or record_id ~= (tonumber(accessxi.records_of_eminence_confirm_detail_record_id) or 0)) then
        return false;
    end
    if ((tonumber(accessxi.records_of_eminence_confirm_detail_until) or 0) <= tick()) then
        return false;
    end
    accessxi.records_of_eminence_confirm_detail_record_id = 0;
    accessxi.records_of_eminence_confirm_detail_until = 0;
    return true;
end

function accessxi.records_of_eminence_inline_transition_from_quest01()
    local transition_age = (tonumber(accessxi.last_menu_transition_tick) or 0) > 0 and (tick() - (tonumber(accessxi.last_menu_transition_tick) or 0)) or 999999;
    return tostring(accessxi.last_menu_transition_from or ''):eq('menu    quest01', true)
        and tostring(accessxi.last_menu_transition_to or ''):eq('menu    inline', true)
        and transition_age <= 30000;
end

function accessxi.records_of_eminence_inline_context_row()
    if (is_chat_input_open ~= nil and is_chat_input_open()) then
        return nil;
    end
    if (not accessxi.records_of_eminence_inline_transition_from_quest01()) then
        return nil;
    end

    local context_age = (tonumber(accessxi.quests_menu_context_tick) or 0) > 0 and (tick() - (tonumber(accessxi.quests_menu_context_tick) or 0)) or 999999;
    local context = tostring(accessxi.quests_menu_context or '');
    local context_ok = context_age <= 300000
        and (context == 'records-of-eminence'
            or context == 'records-of-eminence-objective-catalog'
            or context == 'records-of-eminence-objective-category');
    local transition_ok = accessxi.records_of_eminence_inline_transition_from_quest01();

    local row = accessxi.last_records_of_eminence_detail_row;
    local row_age = (tonumber(accessxi.last_records_of_eminence_detail_tick) or 0) > 0 and (tick() - (tonumber(accessxi.last_records_of_eminence_detail_tick) or 0)) or 999999;
    local rows = accessxi.roe_active_records;
    local packet_tick = tonumber(accessxi.roe_active_tick) or 0;
    local packet_row = type(rows) == 'table' and rows[1] or nil;
    if (type(row) == 'table'
        and transition_ok
        and row_age <= 30000) then
        local row_record = row.record;
        local record_id = tonumber(row.record_id) or 0;
        local label = tostring(row.label or (type(row_record) == 'table' and row_record.label or '') or '');
        if (type(row_record) == 'table' and record_id > 0 and label ~= '') then
            local inline_key = ('%d:%s:%s:%s'):fmt(record_id, label, context, tostring(transition_ok == true));
            local inline_tick = tonumber(accessxi.last_records_of_eminence_inline_context_log_tick) or 0;
            if (inline_key ~= tostring(accessxi.last_records_of_eminence_inline_context_log_key or '')
                or (tick() - inline_tick) > 1500) then
                accessxi.last_records_of_eminence_inline_context_log_key = inline_key;
                accessxi.last_records_of_eminence_inline_context_log_tick = tick();
                log_state(('state records-of-eminence inline-context-detail-row recordId=%d label="%s" source="%s" context="%s" transition=%s'):fmt(
                    record_id,
                    accessxi.escape_probe_log_text(label),
                    accessxi.escape_probe_log_text(tostring(row.source or row_record.source or '')),
                    accessxi.escape_probe_log_text(context),
                    tostring(transition_ok == true)));
            end
            return row;
        end
    end

    if (not context_ok and not transition_ok) then
        return nil;
    end

    if (type(rows) ~= 'table' or packet_tick <= 0 or (tick() - packet_tick) > 300000) then
        return nil;
    end

    if (type(packet_row) ~= 'table' or packet_row.timed ~= true) then
        return nil;
    end

    local record_id = tonumber(packet_row.id) or 0;
    local records = accessxi.records_of_eminence_data.records or T{};
    local record = records[record_id];
    if (type(record) ~= 'table' or not accessxi.records_of_eminence_record_is_timed(packet_row, record) or tostring(record.description or '') == '') then
        return nil;
    end

    local label = tostring(record.label or '');
    if (label == '') then
        return nil;
    end

    accessxi.remember_records_of_eminence_detail_row(
        1,
        0,
        record_id,
        tonumber(packet_row.progress) or 0,
        tonumber(record.goal) or 0,
        label,
        record,
        tostring(record.source or 'packet:0x111 dat'),
        true);
    log_state(('state records-of-eminence inline-context-row recordId=%d label="%s" source="%s"'):fmt(
        record_id,
        accessxi.escape_probe_log_text(label),
        accessxi.escape_probe_log_text(tostring(record.source or ''))));
    return accessxi.last_records_of_eminence_detail_row;
end

function accessxi.records_of_eminence_detail_position_signature(menu_name, reason)
    local obj = get_current_menu_object_ptr();
    local target = safe_call(function () return AshitaCore:GetMemoryManager():GetTarget(); end, nil);
    local ank = target ~= nil and (tonumber(safe_call(function () return target:GetWindowAnkNum(); end, -1)) or -1) or -1;
    local ank_x = target ~= nil and (tonumber(safe_call(function () return target:GetWindowAnkX(); end, -1)) or -1) or -1;
    local ank_y = target ~= nil and (tonumber(safe_call(function () return target:GetWindowAnkY(); end, -1)) or -1) or -1;
    local sub = target ~= nil and (tonumber(safe_call(function () return target:GetWindowSub(); end, -1)) or -1) or -1;
    local sub_x = target ~= nil and (tonumber(safe_call(function () return target:GetWindowSubAnkX(); end, -1)) or -1) or -1;
    local sub_y = target ~= nil and (tonumber(safe_call(function () return target:GetWindowSubAnkY(); end, -1)) or -1) or -1;
    local indexes = T{};
    local detail_index = 0;
    if (obj ~= 0) then
        for _, offset in ipairs(T{ 0x24, 0x28, 0x2C, 0x30, 0x34, 0x4C, 0x50, 0x58, 0x64 }) do
            local value = tonumber(read_i32(obj + offset)) or 0;
            if (offset == 0x4C and value >= 0 and value <= 64) then
                detail_index = value;
            end
            indexes:append(('%02X=%d'):fmt(offset, value));
        end
    end

    local signature = ('obj=0x%08X ank=%d,%d,%d sub=%d,%d,%d detailIndex=%d idx=%s'):fmt(
        obj,
        ank,
        ank_x,
        ank_y,
        sub,
        sub_x,
        sub_y,
        detail_index,
        indexes:concat(','));
    local key = ('%s:%s:%s'):fmt(tostring(menu_name or ''), tostring(reason or ''), signature);
    if (key ~= tostring(accessxi.last_records_of_eminence_detail_position_key or '')) then
        accessxi.last_records_of_eminence_detail_position_key = key;
        log_state(('state records-of-eminence detail-position menu="%s" reason="%s" nativePos="%s"'):fmt(
            tostring(menu_name or ''),
            accessxi.escape_probe_log_text(tostring(reason or '')),
            accessxi.escape_probe_log_text(signature)));
    end
    return signature, detail_index;
end

function accessxi.records_of_eminence_comyn_stage(menu_name, row, record)
    if (not tostring(menu_name or ''):eq('menu    comyn', true)) then
        return '';
    end
    if (accessxi.records_of_eminence_record_is_timed(row, record)) then
        accessxi.last_records_of_eminence_comyn_stage = 'detail';
        accessxi.last_records_of_eminence_comyn_record_id = tonumber(row.record_id) or 0;
        accessxi.last_records_of_eminence_comyn_obj = get_current_menu_object_ptr();
        return 'detail';
    end
    local completed_record = accessxi.records_of_eminence_completed_record_id(tonumber(row.record_id) or 0);
    if (completed_record == true) then
        accessxi.last_records_of_eminence_comyn_stage = 'detail';
        accessxi.last_records_of_eminence_comyn_record_id = tonumber(row.record_id) or 0;
        accessxi.last_records_of_eminence_comyn_obj = get_current_menu_object_ptr();
        return 'detail';
    end

    local obj = get_current_menu_object_ptr();
    local record_id = tonumber(row.record_id) or 0;
    local last_obj = tonumber(accessxi.last_records_of_eminence_comyn_obj) or 0;
    local last_record_id = tonumber(accessxi.last_records_of_eminence_comyn_record_id) or 0;
    local last_stage = tostring(accessxi.last_records_of_eminence_comyn_stage or '');
    local stage = last_stage;
    if (record_id ~= last_record_id) then
        stage = 'confirmation';
    elseif (obj ~= last_obj and last_stage == 'confirmation') then
        stage = 'detail';
    elseif (obj ~= last_obj) then
        stage = 'confirmation';
    elseif (stage == '') then
        stage = 'confirmation';
    end

    accessxi.last_records_of_eminence_comyn_stage = stage;
    accessxi.last_records_of_eminence_comyn_record_id = record_id;
    accessxi.last_records_of_eminence_comyn_obj = obj;
    return stage;
end

function accessxi.records_of_eminence_confirmation_selected_label(set_objective)
    local options = T{ 'Yes', 'No' };
    if (set_objective == true) then
        options = T{ 'No', 'Yes' };
    end
    local candidates = T{ 0x4C, 0x50, 0x30, 0x34, 0x64 };
    for _, offset in ipairs(candidates) do
        local selected = tonumber(read_current_native_menu_index(offset)) or 0;
        local label = option_from_index(options, selected);
        if (label ~= '') then
            return label, selected, offset;
        end
    end
    return '', -1, 0;
end

function accessxi.records_of_eminence_confirmation_speech(menu_name, row)
    local label = tostring(row.label or '');
    local record_id = tonumber(row.record_id) or 0;
    accessxi.records_of_eminence_confirm_detail_record_id = record_id;
    accessxi.records_of_eminence_confirm_detail_until = tick() + 12000;
    local active_record, active_reason = accessxi.records_of_eminence_active_record_id(record_id);
    local prompt = active_record == true and 'Remove objective?' or 'Set objective?';
    local selected_label, selected, selected_offset = accessxi.records_of_eminence_confirmation_selected_label(active_record ~= true);
    local key = ('native-known-records-of-eminence-confirm:%s:%d:selected=%d:%s:%s'):fmt(
        tostring(menu_name or ''),
        record_id,
        tonumber(selected) or -1,
        prompt,
        label);
    accessxi.last_native_menu_name = tostring(menu_name or '');
    accessxi.last_native_menu_label = selected_label ~= '' and selected_label or label;
    accessxi.last_native_menu_selected = tonumber(selected) or tonumber(row.selected) or 0;
    accessxi.last_native_menu_tick = tick();
    accessxi.current_speech_key = key;
    if (key ~= tostring(accessxi.last_records_of_eminence_detail_key or '')) then
        accessxi.last_records_of_eminence_detail_key = key;
        log_state(('state records-of-eminence confirm menu="%s" recordId=%d label="%s" prompt="%s" activeReason="%s" selected=%d selectedOffset=0x%02X selectedLabel="%s"'):fmt(
            tostring(menu_name or ''),
            record_id,
            accessxi.escape_probe_log_text(label),
            accessxi.escape_probe_log_text(prompt),
            accessxi.escape_probe_log_text(tostring(active_reason or '')),
            tonumber(selected) or -1,
            tonumber(selected_offset) or 0,
            accessxi.escape_probe_log_text(selected_label)));
    end
    if (selected_label ~= '') then
        return ('Records of Eminence. %s. %s %s.'):fmt(
            accessxi.sentence_fragment(label),
            prompt,
            accessxi.sentence_fragment(selected_label));
    end
    return ('Records of Eminence. %s. %s Yes or No.'):fmt(accessxi.sentence_fragment(label), prompt);
end

function accessxi.records_of_eminence_inline_detail_speech(menu_name)
    if (not tostring(menu_name or ''):eq('menu    inline', true)) then
        return nil;
    end

    return nil;
end

function accessxi.records_of_eminence_detail_speech(menu_name)
    if (not tostring(menu_name or ''):eq('menu    comyn', true)) then
        return nil;
    end

    local row = accessxi.last_records_of_eminence_detail_row;
    local row_age = (tonumber(accessxi.last_records_of_eminence_detail_tick) or 0) > 0 and (tick() - (tonumber(accessxi.last_records_of_eminence_detail_tick) or 0)) or 999999;
    if (type(row) ~= 'table' or row_age > 30000) then
        return nil;
    end

    local record = row.record;
    if (type(record) ~= 'table') then
        return nil;
    end

    local stage = accessxi.records_of_eminence_comyn_stage(menu_name, row, record);
    if (stage == 'confirmation') then
        return accessxi.records_of_eminence_confirmation_speech(menu_name, row);
    end

    return nil;
end

function accessxi.records_of_eminence_detail_context_for_menu(menu_name)
    menu_name = tostring(menu_name or '');
    if (menu_name:eq('menu    inline', true)) then
        return nil, nil, '';
    end

    if (menu_name:eq('menu    quest01', true)) then
        local signal = accessxi.records_of_eminence_quest01_row_signal();
        if (type(signal) == 'table'
            and accessxi.records_of_eminence_dat_objective_signal(signal)
            and accessxi.records_of_eminence_detail_line_surface_active_for_selected(tonumber(signal.selected) or 0, true)
            and accessxi.records_of_eminence_quest01_detail_surface_active(menu_name)) then
            local signal_row = accessxi.records_of_eminence_objective_detail_row_from_signal(signal);
            if (type(signal_row) == 'table'
                and type(signal_row.record) == 'table'
                and accessxi.records_of_eminence_direct_objective_detail_surface(signal_row)) then
                return signal_row, signal_row.record, 'direct-detail';
            end
        end
    end

    local row = accessxi.last_records_of_eminence_detail_row;
    local row_age = (tonumber(accessxi.last_records_of_eminence_detail_tick) or 0) > 0 and (tick() - (tonumber(accessxi.last_records_of_eminence_detail_tick) or 0)) or 999999;
    if (type(row) ~= 'table' or row_age > 30000 or type(row.record) ~= 'table') then
        return nil, nil, '';
    end

    if (menu_name:eq('menu    comyn', true)) then
        local stage = accessxi.records_of_eminence_comyn_stage(menu_name, row, row.record);
        if (stage == 'detail') then
            return row, row.record, 'comyn-detail';
        end
        return nil, nil, '';
    end

    local quest_detail_surface = (menu_name:eq('menu    quest01', true) or menu_name:eq('menu    quest00', true))
        and accessxi.records_of_eminence_quest01_detail_surface_active(menu_name);
    if (quest_detail_surface and accessxi.records_of_eminence_pending_confirm_detail(row)) then
        local reason = 'confirm-return';
        if (menu_name:eq('menu    quest00', true)) then
            reason = 'confirm-return-quest00';
        end
        return row, row.record, reason;
    end

    if (quest_detail_surface
        and menu_name:eq('menu    quest01', true)
        and accessxi.records_of_eminence_direct_objective_detail_surface(row)) then
        return row, row.record, 'direct-detail';
    end

    if (quest_detail_surface
        and tostring(accessxi.records_of_eminence_detail_watch_reason or '') == 'confirm-return'
        and (tonumber(accessxi.records_of_eminence_detail_watch_until) or 0) > tick()
        and (tonumber(accessxi.records_of_eminence_detail_watch_record_id) or 0) == (tonumber(row.record_id) or 0)
        and (tonumber(accessxi.records_of_eminence_detail_watch_selected) or 0) == (tonumber(row.selected) or 0)
        and (accessxi.records_of_eminence_should_suppress_row(tonumber(row.record_id) or 0, tonumber(row.selected) or 0)
            or accessxi.records_of_eminence_detail_line_surface_active_for_row(row))) then
        local reason = 'confirm-return';
        if (menu_name:eq('menu    quest00', true)) then
            reason = 'confirm-return-quest00';
        end
        return row, row.record, reason;
    end

    return nil, nil, '';
end

function accessxi.records_of_eminence_menu_speech(menu_name, title, selected, count, page, raw, child, entry)
    if (not tostring(menu_name or ''):eq('menu    quest01', true)) then
        return nil;
    end

    local roe_mode, context = accessxi.quests_menu_effective_mode();
    if (context ~= 'records-of-eminence') then
        return nil;
    end

    selected = tonumber(selected) or 0;
    count = tonumber(count) or 0;
    child = tonumber(child) or 0;
    entry = tonumber(entry) or 0;
    raw = tonumber(raw) or 0;
    if (selected <= 0 or not accessxi.is_probe_pointer(child)) then
        return nil;
    end

    local visible_count = tonumber(read_u32(child + 0x40)) or 0;
    if (visible_count <= 0) then
        visible_count = count;
    end
    if (visible_count <= 0 or visible_count > 64 or selected > visible_count) then
        return nil;
    end

    local packet_row, packet_reason, record = accessxi.records_of_eminence_packet_row(selected);
    local label = '';
    local mode = 'empty-list';
    local first = read_u32(child + 0x14) or 0;
    local last = read_u32(child + 0x18) or 0;
    if (accessxi.is_probe_pointer(first) or accessxi.is_probe_pointer(last)) then
        label, mode = accessxi.native_query_label_for_selection(child, selected, visible_count, 'plain');
    end
    label = accessxi.plain_native_menu_label(label or '');
    if (label == '') then
        if (packet_row ~= nil) then
            local record_id = tonumber(packet_row.id) or 0;
            local progress = tonumber(packet_row.progress) or 0;
            local goal = type(record) == 'table' and (tonumber(record.goal) or 0) or 0;
            local source = type(record) == 'table' and tostring(record.source or '') or 'packet:0x111';
            local packet_label = type(record) == 'table' and tostring(record.label or '') or '';
            if (packet_label == '') then
                packet_label = ('Records of Eminence objective ID %d'):fmt(record_id);
                source = 'packet:0x111 id-only';
            end
            label = packet_label;
            accessxi.records_of_eminence_clear_stale_detail_watch_for_list_row(record_id, selected);
            accessxi.remember_records_of_eminence_detail_row(selected, visible_count, record_id, progress, goal, label, record, source, packet_row.timed == true);
            accessxi.last_records_of_eminence_comyn_obj = 0;
            accessxi.last_records_of_eminence_comyn_record_id = 0;
            accessxi.last_records_of_eminence_comyn_stage = '';
            local detail_row = accessxi.last_records_of_eminence_detail_row;
            accessxi.log_records_of_eminence_timed_surface_probe(menu_name, detail_row, record, 'timed-active-row');
            if (accessxi.records_of_eminence_detail_watch_blocks_list_row(menu_name, detail_row)) then
                return nil;
            end
            if (accessxi.records_of_eminence_should_suppress_row(record_id, selected)) then
                return nil;
            end
            local progress_text = accessxi.records_of_eminence_progress_fragment(progress, goal);
            accessxi.last_native_menu_name = tostring(menu_name or '');
            accessxi.last_native_menu_label = label;
            accessxi.last_native_menu_selected = selected;
            accessxi.last_native_menu_tick = tick();
            accessxi.current_speech_key = ('native-known-records-of-eminence-packet:%s:%d:%d:%d:%d:%d:%s'):fmt(
                tostring(menu_name or ''),
                selected,
                tonumber(page) or 0,
                visible_count,
                record_id,
                progress,
                label);
            log_state(('state records-of-eminence active-row menu="%s" title="%s" select=%d visible=%d count=%d mode="%s" recordId=%d progress=%d goal=%d label="%s" source="%s"'):fmt(
                tostring(menu_name or ''),
                accessxi.escape_probe_log_text(tostring(title or '')),
                selected,
                visible_count,
                count,
                accessxi.escape_probe_log_text(tostring(roe_mode or '')),
                record_id,
                progress,
                goal,
                accessxi.escape_probe_log_text(label),
                accessxi.escape_probe_log_text(source)));
            return ('%s. %s. %s.'):fmt(tostring(title or ''), accessxi.sentence_fragment(label), progress_text);
        end

        local missing_key = ('%s:%d:%d:%d:0x%08X:0x%08X:%s'):fmt(
            tostring(menu_name or ''),
            selected,
            visible_count,
            count,
            child,
            entry,
            tostring(mode or ''));
        if (missing_key ~= tostring(accessxi.last_records_of_eminence_row_key or '')) then
            accessxi.last_records_of_eminence_row_key = missing_key;
            local child_dwords = accessxi.is_probe_pointer(child) and accessxi.format_probe_dwords(child, 0x00, 32) or '';
            local entry_dwords = accessxi.is_probe_pointer(entry) and accessxi.format_probe_dwords(entry, 0x00, 32) or '';
            local entry_runs = accessxi.is_probe_pointer(entry) and accessxi.status_menu_probe_runs(entry, 0x120) or '';
            local desc = accessxi.is_probe_pointer(entry) and (read_u32(entry + 0x0C) or 0) or 0;
            local roe_ptr0 = accessxi.is_probe_pointer(desc) and (read_u32(desc + 0x00) or 0) or 0;
            local roe_ptr1 = accessxi.is_probe_pointer(desc) and (read_u32(desc + 0x04) or 0) or 0;
            local desc_probe = accessxi.records_of_eminence_descriptor_probe(entry, selected, visible_count);
            log_state(('state records-of-eminence row-missing menu="%s" title="%s" select=%d visible=%d count=%d raw=0x%08X child=0x%08X entry=0x%08X desc=0x%08X roeP0=0x%08X roeP1=0x%08X roeP1Text="%s" roeP1Words="%s" mode="%s" packetReason="%s" childDwords="%s" entryDwords="%s" entryRuns="%s" descProbe="%s"'):fmt(
                tostring(menu_name or ''),
                accessxi.escape_probe_log_text(tostring(title or '')),
                selected,
                visible_count,
                count,
                raw,
                child,
                entry,
                desc,
                roe_ptr0,
                roe_ptr1,
                accessxi.escape_probe_log_text_wide(accessxi.records_of_eminence_pointer_text_probe(roe_ptr1)),
                accessxi.escape_probe_log_text_wide(accessxi.records_of_eminence_record_pointer_probe(roe_ptr1)),
                accessxi.escape_probe_log_text(tostring(mode or '')),
                accessxi.escape_probe_log_text(tostring(packet_reason or '')),
                accessxi.escape_probe_log_text_wide(child_dwords),
                accessxi.escape_probe_log_text_wide(entry_dwords),
                accessxi.escape_probe_log_text(entry_runs),
                accessxi.escape_probe_log_text_wide(desc_probe)));
        end
        return nil;
    end

    if (packet_row ~= nil and type(record) == 'table') then
        local record_id = tonumber(packet_row.id) or 0;
        local progress = tonumber(packet_row.progress) or 0;
        local goal = tonumber(record.goal) or 0;
        local source = tostring(record.source or 'packet:0x111');
        accessxi.records_of_eminence_clear_stale_detail_watch_for_list_row(record_id, selected);
        accessxi.remember_records_of_eminence_detail_row(selected, visible_count, record_id, progress, goal, label, record, source, packet_row.timed == true);
        accessxi.last_records_of_eminence_comyn_obj = 0;
        accessxi.last_records_of_eminence_comyn_record_id = 0;
        accessxi.last_records_of_eminence_comyn_stage = '';
        local detail_row = accessxi.last_records_of_eminence_detail_row;
        accessxi.log_records_of_eminence_timed_surface_probe(menu_name, detail_row, record, 'timed-active-row');
        if (accessxi.records_of_eminence_should_suppress_row(record_id, selected)) then
            return nil;
        end
    end

    accessxi.last_native_menu_name = tostring(menu_name or '');
    accessxi.last_native_menu_label = label;
    accessxi.last_native_menu_selected = selected;
    accessxi.last_native_menu_tick = tick();
    accessxi.current_speech_key = ('native-known-records-of-eminence:%s:%d:%d:%d:%s'):fmt(
        tostring(menu_name or ''),
        selected,
        tonumber(page) or 0,
        visible_count,
        label);
    log_state(('state records-of-eminence row menu="%s" title="%s" select=%d visible=%d count=%d page=%d raw=0x%08X child=0x%08X mode="%s" label="%s"'):fmt(
        tostring(menu_name or ''),
        accessxi.escape_probe_log_text(tostring(title or '')),
        selected,
        visible_count,
        count,
        tonumber(page) or 0,
        raw,
        child,
        accessxi.escape_probe_log_text(tostring(mode or '')),
        accessxi.escape_probe_log_text(label)));
    return ('Records of Eminence. %s'):fmt(accessxi.sentence_fragment(label));
end

function accessxi.records_of_eminence_objective_list_rows_for_visible(visible_count)
    visible_count = tonumber(visible_count) or 0;
    local data = accessxi.records_of_eminence_data or {};
    local rows = data.objective_list_categories or T{};
    local row_count = rows.len ~= nil and rows:len() or #rows;
    if (visible_count <= 0 or row_count <= 0 or visible_count > row_count) then
        return nil, row_count;
    end
    if (visible_count == row_count) then
        return rows, row_count;
    end

    local optional_indices = data.objective_list_optional_category_indices or T{};
    local omit_count = row_count - visible_count;
    if (omit_count <= 0 or omit_count > (optional_indices.len ~= nil and optional_indices:len() or #optional_indices)) then
        return nil, row_count;
    end

    local omitted = T{};
    for i = 1, omit_count do
        local index = tonumber(optional_indices[i]) or 0;
        if (index <= 0 or rows[index] == nil or rows[index].optional ~= true) then
            return nil, row_count;
        end
        omitted[index] = true;
    end

    local visible_rows = T{};
    for index = 1, row_count do
        if (omitted[index] ~= true) then
            visible_rows:append(rows[index]);
        end
    end
    local visible_row_count = visible_rows.len ~= nil and visible_rows:len() or #visible_rows;
    if (visible_row_count ~= visible_count) then
        return nil, row_count;
    end
    return visible_rows, visible_row_count;
end

function accessxi.records_of_eminence_objective_list_row_from_slot(slot_id, visible_count)
    slot_id = tonumber(slot_id) or 0;
    visible_count = tonumber(visible_count) or 0;
    if (slot_id < 0xF210 or slot_id > 0xF21F or visible_count <= 0) then
        return nil, 0;
    end

    local data = accessxi.records_of_eminence_data or {};
    local rows = data.objective_list_categories or T{};
    local row_count = rows.len ~= nil and rows:len() or #rows;
    local category_index = slot_id - 0xF210 + 1;
    if (category_index <= 0 or category_index > row_count) then
        return nil, 0;
    end

    local category_row = rows[category_index];
    local label = type(category_row) == 'table' and tostring(category_row.label or '') or '';
    if (label == '') then
        return nil, 0;
    end

    return T{
        label = label,
        source = ('roe-category-slot:0x%04X %s'):fmt(slot_id, tostring(category_row.source or '')),
        category_key = tostring(category_row.category_key or ''),
        category_index = category_index,
    }, category_index;
end

function accessxi.log_records_of_eminence_objective_category_block_probe(menu_name, title, parent_label, parent_index, selected, visible_count, raw_lo, block, reason, slot_id)
    block = tonumber(block) or 0;
    slot_id = tonumber(slot_id) or 0;
    visible_count = tonumber(visible_count) or 0;
    if (not accessxi.is_probe_pointer(block) or visible_count <= 0) then
        return;
    end

    local key = ('%s:%s:%d:%d:%d:%d:0x%08X:0x%04X:%s'):fmt(
        tostring(menu_name or ''),
        tostring(parent_label or ''),
        tonumber(parent_index) or -1,
        tonumber(selected) or 0,
        visible_count,
        tonumber(raw_lo) or -1,
        block,
        slot_id,
        tostring(reason or ''));
    if (key == tostring(accessxi.last_records_of_eminence_objective_category_block_probe_key or '')) then
        return;
    end
    accessxi.last_records_of_eminence_objective_category_block_probe_key = key;

    local length = math.max(0x100, math.min(0x300, (visible_count * 0x20) + 0x80));
    local byte_length = math.min(length, 0x180);
    local dword_count = math.min(64, math.floor(length / 4));
    local ascii = '';
    local utf16 = '';
    local ffxi16 = '';
    if (accessxi.collect_probe_ascii_runs ~= nil and accessxi.probe_runs_to_text ~= nil) then
        ascii = accessxi.probe_runs_to_text(accessxi.collect_probe_ascii_runs(block, length, 2, 24));
    end
    if (accessxi.collect_probe_utf16_runs ~= nil and accessxi.probe_runs_to_text ~= nil) then
        utf16 = accessxi.probe_runs_to_text(accessxi.collect_probe_utf16_runs(block, length, 2, 24));
    end
    if (accessxi.collect_probe_ffxi_utf16_runs ~= nil and accessxi.probe_runs_to_text ~= nil) then
        ffxi16 = accessxi.probe_runs_to_text(accessxi.collect_probe_ffxi_utf16_runs(block, length, 2, 24));
    end

    log_state(('state records-of-eminence objective-category-block-probe menu="%s" title="%s" parent="%s" parentIndex=%d select=%d visible=%d rawLo=%d block=0x%08X slotId=0x%04X len=0x%X dwords="%s" bytes="%s" ascii="%s" utf16="%s" ffxi16="%s" reason="%s"'):fmt(
        tostring(menu_name or ''),
        accessxi.escape_probe_log_text(tostring(title or '')),
        accessxi.escape_probe_log_text(tostring(parent_label or '')),
        tonumber(parent_index) or -1,
        tonumber(selected) or 0,
        visible_count,
        tonumber(raw_lo) or -1,
        block,
        slot_id,
        length,
        accessxi.escape_probe_log_text_wide(accessxi.format_probe_dwords(block, 0x00, dword_count)),
        accessxi.escape_probe_log_text_wide(accessxi.format_probe_bytes(block, 0x00, byte_length)),
        accessxi.escape_probe_log_text_wide(ascii),
        accessxi.escape_probe_log_text_wide(utf16),
        accessxi.escape_probe_log_text_wide(ffxi16),
        accessxi.escape_probe_log_text(tostring(reason or ''))));
end

function accessxi.records_of_eminence_objective_catalog_row_from_slot(slot_id, selected, visible_count)
    local data = accessxi.records_of_eminence_data or T{};
    local records = data.records or T{};
    slot_id = tonumber(slot_id) or 0;
    selected = tonumber(selected) or 0;
    visible_count = tonumber(visible_count) or 0;
    if (slot_id < 0xE001 or slot_id > 0xFFFF or selected <= 0 or visible_count <= 0) then
        return nil, 0;
    end

    local record_id = slot_id - 0xE000;
    local record = records[record_id];
    local label = type(record) == 'table' and tostring(record.label or '') or '';
    if (label == '') then
        return nil, record_id;
    end

    return T{
        selected = selected,
        visible_count = visible_count,
        record_id = record_id,
        progress = 0,
        goal = tonumber(record.goal) or 0,
        label = label,
        record = record,
        source = 'dat-native-title-id:ROM/307/16.DAT',
        timed = record.timed == true,
        daily = record.daily == true,
    }, record_id;
end

function accessxi.records_of_eminence_objective_detail_row_from_signal(signal, source)
    if (type(signal) ~= 'table') then
        return nil;
    end

    local selected = tonumber(signal.selected) or 0;
    local visible_count = tonumber(signal.visible_count) or 0;
    local slot_id = tonumber(signal.slot_id) or 0;
    local detail_index = read_current_native_menu_index(0x4C);
    if (selected <= 0 or visible_count <= 0 or detail_index <= 0 or detail_index > 64) then
        return nil;
    end

    local row = nil;
    row = accessxi.records_of_eminence_objective_catalog_row_from_slot(slot_id, selected, visible_count);
    if (type(row) ~= 'table' or type(row.record) ~= 'table') then
        return nil;
    end

    local record_id = tonumber(row.record_id) or 0;
    if (record_id <= 0 or record_id ~= (tonumber(signal.record_id) or 0)) then
        return nil;
    end

    row.source = tostring(source or row.source or 'native-objective-detail-signal');
    accessxi.quests_menu_context = 'records-of-eminence-objective-catalog';
    accessxi.quests_menu_context_tick = tick();
    accessxi.remember_records_of_eminence_detail_row(
        selected,
        visible_count,
        record_id,
        tonumber(row.progress) or 0,
        tonumber(row.goal) or 0,
        row.label,
        row.record,
        row.source,
        row.timed == true);
    return accessxi.last_records_of_eminence_detail_row;
end

function accessxi.records_of_eminence_objective_catalog_speech(menu_name, title, selected, visible_count, count, page, raw, slot_id, slot_flags, slot_block, raw_lo, parent_label, parent_index, reason)
    local row, record_id = accessxi.records_of_eminence_objective_catalog_row_from_slot(slot_id, selected, visible_count);
    if (row == nil) then
        return nil, record_id;
    end

    local record = row.record;
    accessxi.quests_menu_context = 'records-of-eminence-objective-catalog';
    accessxi.quests_menu_context_tick = tick();
    accessxi.current_records_of_eminence_objective_catalog_block = tonumber(slot_block) or 0;
    accessxi.current_records_of_eminence_objective_catalog_tick = tick();
    accessxi.mark_records_of_eminence_objective_catalog_row(row);
    accessxi.last_native_menu_name = tostring(menu_name or '');
    accessxi.last_native_menu_label = row.label;
    accessxi.last_native_menu_selected = selected;
    accessxi.last_native_menu_tick = tick();
    accessxi.records_of_eminence_clear_stale_detail_watch_for_list_row(record_id, selected);
    accessxi.remember_records_of_eminence_detail_row(
        selected,
        visible_count,
        record_id,
        tonumber(row.progress) or 0,
        tonumber(row.goal) or 0,
        row.label,
        record,
        row.source,
        row.timed == true);
    accessxi.last_records_of_eminence_comyn_obj = 0;
    accessxi.last_records_of_eminence_comyn_record_id = 0;
    accessxi.last_records_of_eminence_comyn_stage = '';
    accessxi.current_speech_key = ('native-known-records-of-eminence-objective-catalog:%s:%d:%d:%d:%d:%s'):fmt(
        tostring(menu_name or ''),
        selected,
        tonumber(page) or 0,
        visible_count,
        record_id,
        row.label);
    local log_key = ('%s:%d:%d:%d:%d:0x%04X:%s'):fmt(
        tostring(menu_name or ''),
        selected,
        visible_count,
        tonumber(page) or 0,
        record_id,
        tonumber(slot_id) or 0,
        tostring(reason or ''));
    local log_tick = tonumber(accessxi.last_records_of_eminence_objective_catalog_log_tick) or 0;
    if (log_key ~= tostring(accessxi.last_records_of_eminence_objective_catalog_log_key or '')
        or (tick() - log_tick) > 1500) then
        accessxi.last_records_of_eminence_objective_catalog_log_key = log_key;
        accessxi.last_records_of_eminence_objective_catalog_log_tick = tick();
        log_state(('state records-of-eminence objective-catalog-row menu="%s" title="%s" parent="%s" parentIndex=%d select=%d visible=%d count=%d page=%d raw=0x%08X rawLo=%d block=0x%08X nativeId=0x%04X flags=0x%08X recordId=%d label="%s" source="%s" reason="%s"'):fmt(
            tostring(menu_name or ''),
            accessxi.escape_probe_log_text(tostring(title or '')),
            accessxi.escape_probe_log_text(tostring(parent_label or '')),
            tonumber(parent_index) or -1,
            selected,
            visible_count,
            tonumber(count) or 0,
            tonumber(page) or 0,
            tonumber(raw) or 0,
            tonumber(raw_lo) or -1,
            tonumber(slot_block) or 0,
            tonumber(slot_id) or 0,
            tonumber(slot_flags) or 0,
            record_id,
            accessxi.escape_probe_log_text(row.label),
            accessxi.escape_probe_log_text(row.source),
            accessxi.escape_probe_log_text(tostring(reason or ''))));
    end
    return ('Records of Eminence. %s.'):fmt(accessxi.sentence_fragment(row.label));
end

function accessxi.records_of_eminence_rotate_right_byte(value, shift)
    value = tonumber(value) or 0;
    shift = tonumber(shift) or 0;
    if (shift <= 0 or shift >= 8) then
        return value % 256;
    end
    local low = math.floor(value / (2 ^ shift));
    local high = (value * (2 ^ (8 - shift))) % 256;
    return (low + high) % 256;
end

function accessxi.records_of_eminence_decode_rotated_ascii(data, shift, max_len)
    data = tostring(data or '');
    shift = tonumber(shift) or 0;
    max_len = math.min(tonumber(max_len) or #data, #data);
    local chars = T{};
    for i = 1, max_len do
        local value = accessxi.records_of_eminence_rotate_right_byte(string.byte(data, i) or 0, shift);
        if (value == 0) then
            break;
        end
        if (value == 0x07 or value == 0x0A or value == 0x0D) then
            chars:append(' ');
        elseif (value >= 0x20 and value <= 0x7E) then
            chars:append(string.char(value));
        end
    end

    local text = accessxi.plain_native_menu_label(chars:concat(''));
    text = text:gsub('%s+', ' '):gsub('^%s+', ''):gsub('%s+$', '');
    return text;
end

function accessxi.records_of_eminence_objective_category_dat_label(record_id)
    record_id = tonumber(record_id) or -1;
    if (record_id < 0 or record_id > 0x3FF) then
        return nil, 'record-range', 0;
    end

    local cache = accessxi.records_of_eminence_objective_category_dat_cache;
    if (type(cache) ~= 'table') then
        cache = {};
        accessxi.records_of_eminence_objective_category_dat_cache = cache;
    end
    if (cache[record_id] ~= nil) then
        local cached = cache[record_id];
        if (type(cached) == 'table' and tostring(cached.label or '') ~= '') then
            return cached.label, cached.source, tonumber(cached.offset) or 0;
        end
        return nil, tostring(type(cached) == 'table' and cached.reason or 'cached-missing'), 0;
    end

    local path = accessxi.ffxi_path('ROM\\307\\24.DAT');
    if (tostring(path or '') == '') then
        cache[record_id] = { reason = 'missing-ffxi-root' };
        return nil, 'missing-ffxi-root', 0;
    end

    local offset = (record_id * 0x0C00) + 0x280;
    local file = io.open(path, 'rb');
    if (file == nil) then
        cache[record_id] = { reason = 'open-failed' };
        return nil, 'open-failed', offset;
    end
    file:seek('set', offset);
    local data = file:read(0x100) or '';
    file:close();
    if (data == '') then
        cache[record_id] = { reason = 'empty' };
        return nil, 'empty', offset;
    end

    local label = accessxi.records_of_eminence_decode_rotated_ascii(data, 5, 0x80);
    if (label == '' or not accessxi.records_of_eminence_objective_category_label_allowed(label)) then
        cache[record_id] = { reason = 'bad-label', offset = offset };
        return nil, 'bad-label', offset;
    end

    local source = ('dat-native-category-id:ROM\\307\\24.DAT record=0x%02X offset=0x%06X transform=rotate-right-5'):fmt(record_id, offset);
    cache[record_id] = { label = label, source = source, offset = offset };
    return label, source, offset;
end

function accessxi.records_of_eminence_objective_category_row_from_slot(slot_id, parent_label)
    slot_id = tonumber(slot_id) or 0;
    if (slot_id < 0xF200 or slot_id > 0xF2FF) then
        return nil, 'slot-range';
    end

    local record_id = slot_id - 0xF200;
    local label, source, offset = accessxi.records_of_eminence_objective_category_dat_label(record_id);
    if (label == nil or label == '') then
        return nil, tostring(source or 'missing-label');
    end
    if (not accessxi.records_of_eminence_objective_category_label_allowed(label, parent_label)) then
        return nil, 'label-filtered';
    end

    return T{
        label = label,
        source = source,
        native_id = slot_id,
        record_id = record_id,
        offset = tonumber(offset) or 0,
    }, 'dat-native-category-id';
end

function accessxi.records_of_eminence_objective_category_speech(menu_name, title, selected, count, page, raw, child, entry)
    if (not tostring(menu_name or ''):eq('menu    quest01', true)) then
        return nil;
    end

    local _, context = accessxi.quests_menu_effective_mode();
    if (context ~= 'records-of-eminence-objective-category'
        and context ~= 'records-of-eminence-objective-catalog') then
        return nil;
    end

    selected = tonumber(selected) or 0;
    count = tonumber(count) or 0;
    child = tonumber(child) or 0;
    entry = tonumber(entry) or 0;
    raw = tonumber(raw) or 0;
    if (selected <= 0 or not accessxi.is_probe_pointer(child)) then
        return nil;
    end

    local visible_count = tonumber(read_u32(child + 0x40)) or 0;
    if (visible_count <= 0) then
        visible_count = count;
    end
    if (visible_count <= 0 or visible_count > 64 or selected > visible_count) then
        return nil;
    end

    local slot_id, slot_flags, slot_block, raw_lo, slot_reason = accessxi.quests_menu_runtime_slot(child, raw);
    local parent_label = tostring(accessxi.current_records_of_eminence_objective_list_category_label or '');
    local parent_index = tonumber(accessxi.current_records_of_eminence_objective_list_category_index) or -1;
    local objective_rows, objective_row_count = accessxi.records_of_eminence_objective_list_rows_for_visible(visible_count);
    local defer_objective_list_return = false;
    if (objective_rows ~= nil and selected <= visible_count and count >= visible_count) then
        local catalog_speech = accessxi.records_of_eminence_objective_catalog_speech(
            menu_name,
            title,
            selected,
            visible_count,
            count,
            page,
            raw,
            slot_id,
            slot_flags,
            slot_block,
            raw_lo,
            parent_label,
            parent_index,
            'catalog-before-objective-list-shape');
        if (catalog_speech ~= nil) then
            return catalog_speech;
        end
        if (context == 'records-of-eminence-objective-catalog') then
            defer_objective_list_return = true;
        else
            accessxi.quests_menu_mode = '';
            accessxi.quests_menu_mode_tick = 0;
            accessxi.quests_menu_context = 'records-of-eminence-objective-list';
            accessxi.quests_menu_context_tick = tick();
            accessxi.current_records_of_eminence_objective_catalog_block = 0;
            accessxi.current_records_of_eminence_objective_catalog_tick = 0;
            local transition_key = ('%s:%d:%d:%d:%d'):fmt(tostring(menu_name or ''), selected, visible_count, count, objective_row_count);
            if (transition_key ~= tostring(accessxi.last_records_of_eminence_objective_list_return_key or '')) then
                accessxi.last_records_of_eminence_objective_list_return_key = transition_key;
                log_state(('state records-of-eminence objective-list-return menu="%s" title="%s" select=%d visible=%d count=%d rows=%d reason="objective-list-shape"'):fmt(
                    tostring(menu_name or ''),
                    accessxi.escape_probe_log_text(tostring(title or '')),
                    selected,
                    visible_count,
                    count,
                    tonumber(objective_row_count) or 0));
            end
            return accessxi.records_of_eminence_objective_list_speech(menu_name, title, selected, count, page, raw, child, entry);
        end
    end

    local label, mode = accessxi.native_query_label_for_selection(child, selected, visible_count, 'plain');
    label = accessxi.plain_native_menu_label(label or '');
    if (label == '') then
        local category_row, category_reason = accessxi.records_of_eminence_objective_category_row_from_slot(slot_id, parent_label);
        if (category_row ~= nil) then
            accessxi.quests_menu_context = 'records-of-eminence-objective-category';
            accessxi.quests_menu_context_tick = tick();
            accessxi.last_native_menu_name = tostring(menu_name or '');
            accessxi.last_native_menu_label = category_row.label;
            accessxi.last_native_menu_selected = selected;
            accessxi.last_native_menu_tick = tick();
            accessxi.current_speech_key = ('native-known-records-of-eminence-objective-category-dat:%s:%d:%d:%d:0x%04X:%s'):fmt(
                tostring(menu_name or ''),
                selected,
                tonumber(page) or 0,
                visible_count,
                tonumber(category_row.native_id) or 0,
                category_row.label);
            log_state(('state records-of-eminence objective-category-dat-row menu="%s" title="%s" parent="%s" parentIndex=%d select=%d visible=%d count=%d page=%d raw=0x%08X rawLo=%d block=0x%08X nativeId=0x%04X record=0x%02X offset=0x%06X label="%s" source="%s" reason="%s"'):fmt(
                tostring(menu_name or ''),
                accessxi.escape_probe_log_text(tostring(title or '')),
                accessxi.escape_probe_log_text(parent_label),
                parent_index,
                selected,
                visible_count,
                count,
                tonumber(page) or 0,
                raw,
                tonumber(raw_lo) or -1,
                tonumber(slot_block) or 0,
                tonumber(category_row.native_id) or 0,
                tonumber(category_row.record_id) or 0,
                tonumber(category_row.offset) or 0,
                accessxi.escape_probe_log_text(category_row.label),
                accessxi.escape_probe_log_text(category_row.source),
                accessxi.escape_probe_log_text(tostring(category_reason or ''))));
            return ('Records of Eminence. %s.'):fmt(accessxi.sentence_fragment(category_row.label));
        end
        if (context == 'records-of-eminence-objective-catalog') then
            local catalog_speech = accessxi.records_of_eminence_objective_catalog_speech(
                menu_name,
                title,
                selected,
                visible_count,
                count,
                page,
                raw,
                slot_id,
                slot_flags,
                slot_block,
                raw_lo,
                parent_label,
                parent_index,
                'catalog-context');
            if (catalog_speech ~= nil) then
                return catalog_speech;
            end
            accessxi.quests_menu_context = 'records-of-eminence-objective-category';
            accessxi.quests_menu_context_tick = tick();
        end
        -- These category menus are character-dependent; without native text, stay silent and log a probe.
        local catalog_speech = accessxi.records_of_eminence_objective_catalog_speech(
            menu_name,
            title,
            selected,
            visible_count,
            count,
            page,
            raw,
            slot_id,
            slot_flags,
            slot_block,
            raw_lo,
            parent_label,
            parent_index,
            'category-missing-native-title-id');
        if (catalog_speech ~= nil) then
            return catalog_speech;
        end
        if (defer_objective_list_return == true) then
            accessxi.quests_menu_mode = '';
            accessxi.quests_menu_mode_tick = 0;
            accessxi.quests_menu_context = 'records-of-eminence-objective-list';
            accessxi.quests_menu_context_tick = tick();
            accessxi.current_records_of_eminence_objective_catalog_block = 0;
            accessxi.current_records_of_eminence_objective_catalog_tick = 0;
            local transition_key = ('%s:%d:%d:%d:%d'):fmt(tostring(menu_name or ''), selected, visible_count, count, objective_row_count);
            if (transition_key ~= tostring(accessxi.last_records_of_eminence_objective_list_return_key or '')) then
                accessxi.last_records_of_eminence_objective_list_return_key = transition_key;
                log_state(('state records-of-eminence objective-list-return menu="%s" title="%s" select=%d visible=%d count=%d rows=%d reason="objective-list-shape-after-category-check"'):fmt(
                    tostring(menu_name or ''),
                    accessxi.escape_probe_log_text(tostring(title or '')),
                    selected,
                    visible_count,
                    count,
                    tonumber(objective_row_count) or 0));
            end
            return accessxi.records_of_eminence_objective_list_speech(menu_name, title, selected, count, page, raw, child, entry);
        end

        local missing_key = ('%s:%d:%d:%d:0x%08X:0x%08X:%s'):fmt(
            tostring(menu_name or ''),
            selected,
            visible_count,
            count,
            child,
            entry,
            tostring(mode or ''));
        if (missing_key ~= tostring(accessxi.last_records_of_eminence_row_key or '')) then
            accessxi.last_records_of_eminence_row_key = missing_key;
            local desc_probe = accessxi.records_of_eminence_descriptor_probe(entry, selected, visible_count);
            local descriptor_text_probe = accessxi.records_of_eminence_objective_category_descriptor_text_probe(entry, child, selected, visible_count, parent_label);
            if (descriptor_text_probe ~= '') then
                desc_probe = ('%s || categoryText=%s'):fmt(desc_probe, descriptor_text_probe);
            end
            accessxi.log_records_of_eminence_objective_category_block_probe(
                menu_name,
                title,
                parent_label,
                parent_index,
                selected,
                visible_count,
                raw_lo,
                slot_block,
                'missing-label',
                slot_id);
            log_state(('state records-of-eminence objective-category-missing menu="%s" title="%s" parent="%s" parentIndex=%d select=%d visible=%d count=%d raw=0x%08X rawLo=%d child=0x%08X entry=0x%08X block=0x%08X slotId=%d flags=0x%08X slotReason="%s" mode="%s" descProbe="%s" childDwords="%s" entryDwords="%s" reason="missing-label"'):fmt(
                tostring(menu_name or ''),
                accessxi.escape_probe_log_text(tostring(title or '')),
                accessxi.escape_probe_log_text(parent_label),
                parent_index,
                selected,
                visible_count,
                count,
                raw,
                tonumber(raw_lo) or -1,
                child,
                entry,
                tonumber(slot_block) or 0,
                tonumber(slot_id) or -1,
                tonumber(slot_flags) or 0,
                accessxi.escape_probe_log_text(tostring(slot_reason or '')),
                accessxi.escape_probe_log_text(tostring(mode or '')),
                accessxi.escape_probe_log_text_wide(desc_probe),
                accessxi.escape_probe_log_text_wide(accessxi.format_probe_dwords(child, 0x00, 24)),
                accessxi.escape_probe_log_text_wide(accessxi.format_probe_dwords(entry, 0x00, 24))));
        end
        accessxi.log_quests_menu_submenu_probe(
            menu_name,
            title,
            get_current_menu_object_ptr(),
            selected,
            count,
            page,
            raw,
            child,
            entry,
            'objective-category-missing-label');
        return nil;
    end

    accessxi.last_native_menu_name = tostring(menu_name or '');
    accessxi.last_native_menu_label = label;
    accessxi.last_native_menu_selected = selected;
    accessxi.last_native_menu_tick = tick();
    accessxi.mark_records_of_eminence_direct_detail_list_row('objective-category-row');
    accessxi.current_speech_key = ('native-known-records-of-eminence-objective-category:%s:%d:%d:%d:%s'):fmt(
        tostring(menu_name or ''),
        selected,
        tonumber(page) or 0,
        visible_count,
        label);
    log_state(('state records-of-eminence objective-category-row menu="%s" title="%s" select=%d visible=%d count=%d page=%d raw=0x%08X child=0x%08X mode="%s" label="%s"'):fmt(
        tostring(menu_name or ''),
        accessxi.escape_probe_log_text(tostring(title or '')),
        selected,
        visible_count,
        count,
        tonumber(page) or 0,
        raw,
        child,
        accessxi.escape_probe_log_text(tostring(mode or '')),
        accessxi.escape_probe_log_text(label)));
    return ('Records of Eminence. %s'):fmt(accessxi.sentence_fragment(label));
end

function accessxi.records_of_eminence_objective_list_native_row(entry, child, selected, visible_count)
    entry = tonumber(entry) or 0;
    child = tonumber(child) or 0;
    selected = tonumber(selected) or 0;
    visible_count = tonumber(visible_count) or 0;
    if (selected <= 0 or visible_count <= 0 or selected > visible_count) then
        return nil, 0, '';
    end

    local label_ptr = accessxi.is_probe_pointer(entry) and (read_u32(entry + 0x44) or 0) or 0;
    local label = accessxi.plain_native_menu_label(read_probe_string(label_ptr, 180));
    local source = 'native-entry-label';
    local mode = '';
    if (label == '' and accessxi.is_probe_pointer(child)) then
        label, mode = accessxi.native_query_label_for_selection(child, selected, visible_count, 'roe-objective-list');
        label = accessxi.plain_native_menu_label(label or '');
        source = ('native-query:%s'):fmt(tostring(mode or ''));
    end
    if (label == '') then
        local missing_key = ('%d:%d:0x%08X:0x%08X:0x%08X:%s'):fmt(
            selected,
            visible_count,
            entry,
            child,
            label_ptr,
            tostring(mode or ''));
        if (missing_key ~= tostring(accessxi.last_records_of_eminence_objective_list_native_missing_key or '')) then
            accessxi.last_records_of_eminence_objective_list_native_missing_key = missing_key;
            log_state(('state records-of-eminence objective-list-native-missing select=%d visible=%d entry=0x%08X child=0x%08X labelPtr=0x%08X mode="%s"'):fmt(
                selected,
                visible_count,
                entry,
                child,
                label_ptr,
                accessxi.escape_probe_log_text(tostring(mode or ''))));
        end
        return nil, 0, '';
    end

    local data = accessxi.records_of_eminence_data or T{};
    local rows = data.objective_list_categories or T{};
    local row_count = rows.len ~= nil and rows:len() or #rows;
    for index = 1, row_count do
        local row = rows[index];
        local row_label = type(row) == 'table' and accessxi.plain_native_menu_label(tostring(row.label or '')) or '';
        if (row_label ~= '' and row_label:eq(label, true)) then
            return T{
                label = tostring(row.label or label),
                source = ('%s %s'):fmt(tostring(row.source or 'roe-category-index:objective-list'), source),
                category_key = tostring(row.category_key or ''),
                category_index = index,
            }, index, label;
        end
    end

    return T{
        label = label,
        source = source,
        category_key = '',
        category_index = selected,
    }, selected, label;
end

function accessxi.records_of_eminence_objective_list_speech(menu_name, title, selected, count, page, raw, child, entry)
    if (not tostring(menu_name or ''):eq('menu    quest01', true)) then
        return nil;
    end

    local _, context = accessxi.quests_menu_effective_mode();
    if (context ~= 'records-of-eminence-objective-list') then
        return nil;
    end

    selected = tonumber(selected) or 0;
    count = tonumber(count) or 0;
    child = tonumber(child) or 0;
    entry = tonumber(entry) or 0;
    local visible_count = 0;
    if (accessxi.is_probe_pointer(child)) then
        visible_count = tonumber(read_u32(child + 0x40)) or 0;
    end
    if (visible_count <= 0) then
        visible_count = count;
    end
    local rows, row_count = accessxi.records_of_eminence_objective_list_rows_for_visible(visible_count);
    local parent_category_index = tonumber(accessxi.current_records_of_eminence_objective_list_category_index) or -1;
    local parent_category_label = tostring(accessxi.current_records_of_eminence_objective_list_category_label or '');
    local slot_id, slot_flags, slot_block, raw_lo = accessxi.quests_menu_runtime_slot(child, raw);
    if (rows == nil and row_count > 0 and count == row_count and parent_category_index > 0 and parent_category_label ~= '' and selected <= visible_count and visible_count <= 64) then
        accessxi.quests_menu_mode = '';
        accessxi.quests_menu_mode_tick = 0;
        accessxi.quests_menu_context = 'records-of-eminence-objective-category';
        accessxi.quests_menu_context_tick = tick();
        local transition_key = ('%s:%d:%d:%d:%d'):fmt(tostring(menu_name or ''), selected, visible_count, count, row_count);
        if (transition_key ~= tostring(accessxi.last_records_of_eminence_objective_category_key or '')) then
            accessxi.last_records_of_eminence_objective_category_key = transition_key;
            log_state(('state records-of-eminence objective-category-transition menu="%s" title="%s" parent="%s" parentIndex=%d select=%d visible=%d count=%d objectiveRows=%d reason="visible-not-objective-list"'):fmt(
                tostring(menu_name or ''),
                accessxi.escape_probe_log_text(tostring(title or '')),
                accessxi.escape_probe_log_text(parent_category_label),
                parent_category_index,
                selected,
                visible_count,
                count,
                row_count));
        end
        return accessxi.records_of_eminence_objective_category_speech(menu_name, title, selected, count, page, raw, child, entry);
    end
    local catalog_speech = accessxi.records_of_eminence_objective_catalog_speech(
        menu_name,
        title,
        selected,
        visible_count,
        count,
        page,
        raw,
        slot_id,
        slot_flags,
        slot_block,
        raw_lo,
        parent_category_label,
        parent_category_index,
        'objective-list-native-title-id');
    if (catalog_speech ~= nil) then
        return catalog_speech;
    end

    local row, row_category_index = accessxi.records_of_eminence_objective_list_row_from_slot(slot_id, visible_count);
    if (row == nil) then
        row, row_category_index = accessxi.records_of_eminence_objective_list_native_row(entry, child, selected, visible_count);
    end
    if (row == nil) then
        local missing_key = ('%s:%d:%d:%d:%d'):fmt(tostring(menu_name or ''), selected, visible_count, count, row_count);
        if (missing_key ~= tostring(accessxi.last_records_of_eminence_row_key or '')) then
            accessxi.last_records_of_eminence_row_key = missing_key;
            log_state(('state records-of-eminence objective-list-missing menu="%s" title="%s" select=%d visible=%d count=%d expected=%d reason="shape-mismatch"'):fmt(
                tostring(menu_name or ''),
                accessxi.escape_probe_log_text(tostring(title or '')),
                selected,
                visible_count,
                count,
                row_count));
        end
        accessxi.log_quests_menu_submenu_probe(
            menu_name,
            title,
            get_current_menu_object_ptr(),
            selected,
            count,
            page,
            raw,
            child,
            entry,
            'objective-list-shape-mismatch');
        return nil;
    end

    local label = row ~= nil and tostring(row.label or '') or '';
    if (label == '') then
        return nil;
    end

    accessxi.last_native_menu_name = tostring(menu_name or '');
    accessxi.last_native_menu_label = label;
    accessxi.last_native_menu_selected = selected;
    accessxi.last_native_menu_tick = tick();
    accessxi.current_records_of_eminence_objective_list_category_label = label;
    accessxi.current_records_of_eminence_objective_list_category_index = tonumber(row.category_index) or row_category_index;
    accessxi.current_records_of_eminence_objective_list_category_visible = visible_count;
    accessxi.current_records_of_eminence_objective_list_category_block = 0;
    accessxi.current_records_of_eminence_objective_list_category_tick = tick();
    accessxi.current_records_of_eminence_objective_catalog_block = 0;
    accessxi.current_records_of_eminence_objective_catalog_tick = 0;
    accessxi.mark_records_of_eminence_direct_detail_list_row('objective-list-row');
    accessxi.current_speech_key = ('native-known-records-of-eminence-objective-list:%s:%d:%d:%d:%s'):fmt(
        tostring(menu_name or ''),
        selected,
        tonumber(page) or 0,
        visible_count,
        label);
    log_state(('state records-of-eminence objective-list-row menu="%s" title="%s" select=%d visible=%d count=%d label="%s" source="%s" raw=0x%08X child=0x%08X entry=0x%08X'):fmt(
        tostring(menu_name or ''),
        accessxi.escape_probe_log_text(tostring(title or '')),
        selected,
        visible_count,
        count,
        accessxi.escape_probe_log_text(label),
        accessxi.escape_probe_log_text(tostring(row.source or '')),
        tonumber(raw) or 0,
        child,
        entry));
    return ('%s. %s.'):fmt(tostring(title or 'Quests'), accessxi.sentence_fragment(label));
end

function accessxi.quests_menu_detail_resource_speech(menu_name, title, selected, count, page, raw, child, entry)
    if (not tostring(menu_name or ''):eq('menu    quest01', true)) then
        return nil;
    end

    selected = tonumber(selected) or 0;
    count = tonumber(count) or 0;
    child = tonumber(child) or 0;
    entry = tonumber(entry) or 0;
    if (selected <= 0 or not accessxi.is_probe_pointer(child) or not accessxi.is_probe_pointer(entry)) then
        return nil;
    end

    local mode = accessxi.quests_menu_effective_mode();
    if (mode == '') then
        return nil;
    end

    local row = accessxi.last_quests_menu_detail_row;
    local row_age = (tonumber(accessxi.last_quests_menu_detail_tick) or 0) > 0 and (tick() - (tonumber(accessxi.last_quests_menu_detail_tick) or 0)) or 999999;
    if (type(row) ~= 'table' or row_age > 30000) then
        return nil;
    end

    local detail_flags = read_u32(entry + 0x48) or 0;
    local detail_panel = bit.band(detail_flags, 0x00010000) == 0;
    if (not detail_panel) then
        return nil;
    end

    local speech, key, detail, label, detail_row, reason = accessxi.quests_menu_cached_detail_speech(title);
    if (speech == nil or speech == '') then
        local missing_label = tostring(label or (row ~= nil and row.label or ''));
        local missing_key = ('%s:%s:%s:%d'):fmt(tostring(menu_name or ''), missing_label, tostring(reason or 'missing-detail'), tonumber(row ~= nil and row.slot or -1) or -1);
        if (missing_key ~= tostring(accessxi.last_quests_menu_detail_key or '')) then
            accessxi.last_quests_menu_detail_key = missing_key;
            log_state(('state quests detail-missing menu="%s" title="%s" select=%d count=%d rowLabel="%s" slot=%d reason="%s"'):fmt(
                tostring(menu_name or ''),
                accessxi.escape_probe_log_text(tostring(title or '')),
                selected,
                count,
                accessxi.escape_probe_log_text(missing_label),
                tonumber(row ~= nil and row.slot or -1) or -1,
                accessxi.escape_probe_log_text(tostring(reason or 'missing-detail'))));
        end
        return nil;
    end

    accessxi.last_native_menu_name = tostring(menu_name or '');
    accessxi.last_native_menu_label = label;
    accessxi.last_native_menu_selected = selected;
    accessxi.last_native_menu_tick = tick();
    accessxi.current_speech_key = key;
    if (key ~= tostring(accessxi.last_quests_menu_detail_key or '')) then
        accessxi.last_quests_menu_detail_key = key;
        log_state(('state quests detail menu="%s" title="%s" select=%d count=%d entry=0x%08X detailFlags=0x%08X area="%s" status="%s" slot=%d questId=%d label="%s" detail="%s" source="%s"'):fmt(
            tostring(menu_name or ''),
            accessxi.escape_probe_log_text(tostring(title or '')),
            selected,
            count,
            entry,
            detail_flags,
            accessxi.escape_probe_log_text(tostring(detail_row.area_label or detail_row.area or detail_row.area_key or '')),
            accessxi.escape_probe_log_text(tostring(detail_row.status or '')),
            tonumber(detail_row.slot) or -1,
            tonumber(detail_row.id) or -1,
            accessxi.escape_probe_log_text(label),
            accessxi.escape_probe_log_text(detail),
            accessxi.escape_probe_log_text(tostring(detail_row.source or ''))));
    end
    accessxi.begin_quest_detail_summary_surface(menu_name, detail_row);
    return speech;
end

function accessxi.quests_menu_cached_detail_speech(title)
    local row = accessxi.last_quests_menu_detail_row;
    local row_age = (tonumber(accessxi.last_quests_menu_detail_tick) or 0) > 0 and (tick() - (tonumber(accessxi.last_quests_menu_detail_tick) or 0)) or 999999;
    if (type(row) ~= 'table' or row_age > 30000) then
        return nil, '', '', '', row, 'missing-fresh-row';
    end

    local detail, reason = accessxi.quest_rom_detail_for_row(row);
    local label = tostring(row.label or '');
    if (detail == nil or detail == '' or label == '') then
        return nil, '', tostring(detail or ''), label, row, tostring(reason or 'missing-detail');
    end

    local speech = accessxi.sentence_fragment(('%s. %s. %s'):fmt(tostring(title or 'Quests'), label, detail));
    local key = ('native-known-quest-detail:%s:%d:%d:%s'):fmt(
        tostring(row.area_key or ''),
        tonumber(row.slot) or -1,
        tonumber(row.id) or -1,
        label);
    return speech, key, detail, label, row, 'quest-rom-detail';
end

function accessxi.quest_detail_summary_lines(row)
    if (type(row) ~= 'table') then
        return nil, 'missing-quest-row';
    end
    local label = tostring(row.label or ''):trim();
    if (label == '') then
        return nil, 'missing-quest-label';
    end

    local parts, reason = accessxi.quest_rom_detail_parts_for_row(row);
    if (type(parts) ~= 'table' or #parts <= 0) then
        return nil, tostring(reason or 'missing-quest-detail-parts');
    end

    local lines = T{};
    lines:append(label);
    for _, value in ipairs(parts) do
        local text = tostring(value or ''):trim();
        if (text ~= '') then
            lines:append(text);
        end
    end
    if (#lines <= 1) then
        return nil, 'empty-quest-detail-parts';
    end
    return lines, tostring(reason or 'quest-rom-detail-parts');
end

function accessxi.quest_detail_summary_surface_key(menu_name, row, obj)
    if (type(row) ~= 'table') then
        return '';
    end
    obj = tonumber(obj) or 0;
    if (not accessxi.is_probe_pointer(obj)) then
        return '';
    end
    local label = tostring(row.label or ''):trim();
    if (label == '') then
        return '';
    end
    return ('quest-summary:%s:0x%08X:%s:%d:%d:%s'):fmt(
        tostring(menu_name or ''),
        obj,
        tostring(row.area_key or ''),
        tonumber(row.slot) or -1,
        tonumber(row.id) or -1,
        label);
end

function accessxi.reset_quest_detail_summary_surface()
    if (type(accessxi.detail_summary_navigation) == 'table'
        and type(accessxi.detail_summary_navigation.reset) == 'function') then
        accessxi.detail_summary_navigation.reset(accessxi.quest_detail_summary_state);
    end
    accessxi.last_quests_menu_detail_summary_surface_key = '';
end

function accessxi.begin_quest_detail_summary_surface(menu_name, row)
    if (type(accessxi.detail_summary_navigation) ~= 'table'
        or type(accessxi.detail_summary_navigation.begin_surface) ~= 'function') then
        return '';
    end
    local obj = get_current_menu_object_ptr();
    local position = tonumber(read_current_native_menu_index(0x4C)) or 0;
    local surface_key = accessxi.quest_detail_summary_surface_key(menu_name, row, obj);
    if (surface_key == '' or position <= 0) then
        return '';
    end

    if (surface_key ~= tostring(accessxi.last_quests_menu_detail_summary_surface_key or '')) then
        accessxi.detail_summary_navigation.begin_surface(
            accessxi.quest_detail_summary_state, surface_key, position);
    end
    accessxi.last_quests_menu_detail_summary_surface_key = surface_key;
    return surface_key;
end

function accessxi.speak_detail_summary_position_line(kind, menu_name, surface_key, position, line_index, text)
    kind = tostring(kind or 'detail');
    menu_name = tostring(menu_name or '');
    surface_key = tostring(surface_key or '');
    position = tonumber(position) or 0;
    line_index = tonumber(line_index) or 0;
    text = tostring(text or ''):trim();
    if (surface_key == '' or position <= 0 or line_index <= 0 or text == '') then
        return false;
    end

    local key = ('native-%s-summary-position:%s:%s:%d:%d:%s'):fmt(
        kind, menu_name, surface_key, position, line_index, text);
    if (key == tostring(accessxi.last_key or '')) then
        return true;
    end
    accessxi.last_native_menu_name = menu_name;
    accessxi.last_native_menu_label = text;
    accessxi.last_native_menu_selected = position;
    accessxi.last_native_menu_tick = tick();
    accessxi.current_speech_key = key;
    accessxi.last = text;
    accessxi.last_key = key;
    local speak_result = speak(text, false);
    log_state(('state %s summary-position-speak menu="%s" position=%d line=%d result="%s" key="%s" text="%s"'):fmt(
        kind,
        accessxi.escape_probe_log_text(menu_name),
        position,
        line_index,
        accessxi.escape_probe_log_text(speak_result or ''),
        accessxi.escape_probe_log_text(key),
        accessxi.escape_probe_log_text(text)));
    if (text ~= accessxi.last_log or key ~= accessxi.last_log_key) then
        accessxi.last_log = text;
        accessxi.last_log_key = key;
        log_line(text);
    end
    return true;
end

function accessxi.poll_quests_menu_detail_position_speech(menu_name)
    menu_name = tostring(menu_name or get_menu_name() or '');
    if (not menu_name:eq('menu    quest01', true)) then
        accessxi.reset_quest_detail_summary_surface();
        return false;
    end

    local mode = accessxi.quests_menu_effective_mode();
    local row = accessxi.last_quests_menu_detail_row;
    local row_age = (tonumber(accessxi.last_quests_menu_detail_tick) or 0) > 0
        and (tick() - (tonumber(accessxi.last_quests_menu_detail_tick) or 0))
        or 999999;
    if ((mode ~= 'current' and mode ~= 'completed') or type(row) ~= 'table' or row_age > 30000) then
        accessxi.reset_quest_detail_summary_surface();
        return false;
    end

    local obj = get_current_menu_object_ptr();
    if (not accessxi.is_probe_pointer(obj)) then
        accessxi.reset_quest_detail_summary_surface();
        return false;
    end
    local entry = read_u32(obj + 0x08);
    if (not accessxi.is_probe_pointer(entry)) then
        accessxi.reset_quest_detail_summary_surface();
        return false;
    end
    local detail_flags = read_u32(entry + 0x48);
    if (detail_flags == nil or bit.band(detail_flags, 0x00010000) ~= 0) then
        accessxi.reset_quest_detail_summary_surface();
        return false;
    end

    local position = tonumber(read_current_native_menu_index(0x4C)) or 0;
    local lines, lines_reason = accessxi.quest_detail_summary_lines(row);
    local surface_key = accessxi.quest_detail_summary_surface_key(menu_name, row, obj);
    if (position <= 0 or type(lines) ~= 'table' or #lines <= 0 or surface_key == '') then
        accessxi.reset_quest_detail_summary_surface();
        return false;
    end
    accessxi.last_quests_menu_detail_tick = tick();

    if (surface_key ~= tostring(accessxi.last_quests_menu_detail_summary_surface_key or '')) then
        accessxi.detail_summary_navigation.begin_surface(
            accessxi.quest_detail_summary_state, surface_key, position);
        accessxi.quests_menu_detail_speech_protect_until = 0;
        return false;
    end

    local text, line_index, reason = accessxi.detail_summary_navigation.current_line(
        accessxi.quest_detail_summary_state, surface_key, position, lines);
    if (text == nil or text == '') then
        if (reason ~= 'unchanged-position') then
            local quiet_key = ('%s:%d:%s:%s'):fmt(surface_key, position, tostring(reason or ''), tostring(lines_reason or ''));
            if (quiet_key ~= tostring(accessxi.last_quest_detail_summary_quiet_key or '')) then
                accessxi.last_quest_detail_summary_quiet_key = quiet_key;
                log_state(('state quest summary-position-quiet menu="%s" position=%d lines=%d reason="%s" source="%s"'):fmt(
                    accessxi.escape_probe_log_text(menu_name),
                    position,
                    #lines,
                    accessxi.escape_probe_log_text(tostring(reason or '')),
                    accessxi.escape_probe_log_text(tostring(lines_reason or ''))));
            end
        end
        return true;
    end

    return accessxi.speak_detail_summary_position_line(
        'quest', menu_name, surface_key, position, line_index, text);
end

function accessxi.clear_quests_menu_detail_deferred_speech()
    accessxi.quests_menu_detail_deferred_text = '';
    accessxi.quests_menu_detail_deferred_key = '';
    accessxi.quests_menu_detail_deferred_due = 0;
    accessxi.quests_menu_detail_deferred_selected = -1;
    accessxi.quests_menu_detail_deferred_count = -1;
end

function accessxi.queue_quests_menu_detail_enter_speech()
    if (not tostring(get_menu_name() or ''):eq('menu    quest01', true)) then
        return false;
    end

    local speech, key, detail, label, row, reason = accessxi.quests_menu_cached_detail_speech('Quests');
    if (speech == nil or speech == '' or key == '') then
        local missing_key = ('enter:%s:%s:%d'):fmt(tostring(label or ''), tostring(reason or 'missing-detail'), tonumber(row ~= nil and row.slot or -1) or -1);
        if (missing_key ~= tostring(accessxi.last_quests_menu_detail_key or '')) then
            accessxi.last_quests_menu_detail_key = missing_key;
            log_state(('state quests detail-enter-missing label="%s" slot=%d reason="%s"'):fmt(
                accessxi.escape_probe_log_text(tostring(label or '')),
                tonumber(row ~= nil and row.slot or -1) or -1,
                accessxi.escape_probe_log_text(tostring(reason or 'missing-detail'))));
        end
        return false;
    end

    local now = tick();
    accessxi.quests_menu_detail_deferred_text = speech;
    accessxi.quests_menu_detail_deferred_key = key;
    accessxi.quests_menu_detail_deferred_due = now + 350;
    accessxi.quests_menu_detail_deferred_selected = tonumber(row.selected) or -1;
    accessxi.quests_menu_detail_deferred_count = tonumber(row.visible_count) or -1;
    log_state(('state quests detail-enter-queue selected=%d count=%d label="%s" detail="%s" source="%s" due=%d'):fmt(
        tonumber(row.selected) or -1,
        tonumber(row.visible_count) or -1,
        accessxi.escape_probe_log_text(label),
        accessxi.escape_probe_log_text(detail),
        accessxi.escape_probe_log_text(tostring(row.source or '')),
        tonumber(accessxi.quests_menu_detail_deferred_due) or 0));
    return true;
end

function accessxi.poll_quests_menu_detail_deferred_speech()
    local text = tostring(accessxi.quests_menu_detail_deferred_text or '');
    local key = tostring(accessxi.quests_menu_detail_deferred_key or '');
    if (text == '' or key == '') then
        return false;
    end

    local now = tick();
    if (now < (tonumber(accessxi.quests_menu_detail_deferred_due) or 0)) then
        return false;
    end

    if (not tostring(get_menu_name() or ''):eq('menu    quest01', true)) then
        accessxi.clear_quests_menu_detail_deferred_speech();
        return false;
    end

    accessxi.clear_quests_menu_detail_deferred_speech();
    if (key == tostring(accessxi.quests_menu_detail_deferred_spoken_key or '')
        and (now - (tonumber(accessxi.quests_menu_detail_deferred_spoken_tick) or 0)) < 1000) then
        return false;
    end

    accessxi.quests_menu_detail_deferred_spoken_key = key;
    accessxi.quests_menu_detail_deferred_spoken_tick = now;
    accessxi.last = text;
    accessxi.last_key = key;
    accessxi.quests_menu_detail_speech_protect_until = now + accessxi.missions_menu_detail_hold_ms(text);
    local speak_result = speak(text, false);
    log_state(('state quests detail-enter-speak result="%s" text="%s" key="%s"'):fmt(
        accessxi.escape_probe_log_text(speak_result or ''),
        accessxi.escape_probe_log_text(text),
        accessxi.escape_probe_log_text(key)));
    if (text ~= accessxi.last_log or key ~= accessxi.last_log_key) then
        accessxi.last_log = text;
        accessxi.last_log_key = key;
        log_line(text);
    end
    return true;
end

function accessxi.poll_quests_menu_detail_enter_key()
    accessxi.quests_menu_detail_enter_poll_down = false;
    return false;
end

function accessxi.poll_quests_menu_detail_cancel_key()
    accessxi.quests_menu_detail_cancel_poll_key = 0;
    return false;
end

function accessxi.quests_menu_runtime_slot(child, raw)
    child = tonumber(child) or 0;
    raw = tonumber(raw) or 0;
    if (not accessxi.is_probe_pointer(child)) then
        return nil, nil, 0, -1, 'no-child';
    end

    local raw_lo = bit.band(raw, 0xFFFF);
    if (raw_lo < 0 or raw_lo > 0xFF) then
        return nil, nil, 0, raw_lo, 'slot-out-of-range';
    end

    local block = read_u32(child + 0x20) or 0;
    if (not accessxi.is_probe_pointer(block)) then
        return nil, nil, block, raw_lo, 'no-block';
    end

    local offset = block + (raw_lo * 8);
    local row_id = read_i32(offset);
    local flags = read_u32(offset + 4);
    if (row_id == nil or flags == nil) then
        return nil, nil, block, raw_lo, 'unreadable-slot';
    end

    return tonumber(row_id) or 0, tonumber(flags) or 0, block, raw_lo, '';
end

function accessxi.log_quests_menu_submenu_runtime(menu_name, title, selected, count, raw, child, entry, reason)
    local row_id, flags, block, raw_lo, miss = accessxi.quests_menu_runtime_slot(child, raw);
    if (row_id == nil) then
        log_state(('state quests submenu-runtime-missing menu="%s" title="%s" reason="%s" select=%d count=%d raw=%d child=0x%08X entry=0x%08X block=0x%08X miss="%s"'):fmt(
            tostring(menu_name or ''),
            accessxi.escape_probe_log_text(tostring(title or '')),
            accessxi.escape_probe_log_text(tostring(reason or '')),
            tonumber(selected) or 0,
            tonumber(count) or 0,
            tonumber(raw_lo) or -1,
            tonumber(child) or 0,
            tonumber(entry) or 0,
            tonumber(block) or 0,
            accessxi.escape_probe_log_text(tostring(miss or ''))));
        return;
    end

    local candidate_parts = T{};
    local candidates = accessxi.quests_menu_resource_candidates(row_id);
    for _, row in ipairs(candidates) do
        candidate_parts:append(('%s="%s" source="%s"'):fmt(
            tostring(row.area_key or ''),
            accessxi.escape_probe_log_text(tostring(row.label or '')),
            accessxi.escape_probe_log_text(tostring(row.source or ''))));
        log_state(('state quests submenu-resource-candidate menu="%s" title="%s" reason="%s" select=%d count=%d raw=%d rowId=%d flags=0x%08X area="%s" label="%s" source="%s"'):fmt(
            tostring(menu_name or ''),
            accessxi.escape_probe_log_text(tostring(title or '')),
            accessxi.escape_probe_log_text(tostring(reason or '')),
            tonumber(selected) or 0,
            tonumber(count) or 0,
            tonumber(raw_lo) or -1,
            tonumber(row_id) or 0,
            tonumber(flags) or 0,
            accessxi.escape_probe_log_text(tostring(row.area or row.area_key or '')),
            accessxi.escape_probe_log_text(tostring(row.label or '')),
            accessxi.escape_probe_log_text(tostring(row.source or ''))));
    end

    log_state(('state quests submenu-runtime menu="%s" title="%s" reason="%s" select=%d count=%d raw=%d child=0x%08X entry=0x%08X block=0x%08X rowId=%d flags=0x%08X candidates="%s"'):fmt(
        tostring(menu_name or ''),
        accessxi.escape_probe_log_text(tostring(title or '')),
        accessxi.escape_probe_log_text(tostring(reason or '')),
        tonumber(selected) or 0,
        tonumber(count) or 0,
        tonumber(raw_lo) or -1,
        tonumber(child) or 0,
        tonumber(entry) or 0,
        tonumber(block) or 0,
        tonumber(row_id) or 0,
        tonumber(flags) or 0,
        accessxi.escape_probe_log_text_wide(candidate_parts:concat(' | '))));
end

function accessxi.log_quests_menu_main_descriptor_records(menu_name, title, desc, selected, count, reason)
    desc = tonumber(desc) or 0;
    selected = tonumber(selected) or 0;
    count = tonumber(count) or 0;
    if (not accessxi.is_probe_pointer(desc) or selected <= 0 or count <= 0 or count > 32) then
        return;
    end

    local base = desc - ((selected - 1) * 0x14);
    if (not accessxi.is_probe_pointer(base)) then
        return;
    end

    local key = ('%s:%s:0x%08X:%d'):fmt(tostring(menu_name or ''), tostring(reason or ''), base, count);
    if (key == tostring(accessxi.last_quests_menu_main_desc_records_key or '')) then
        return;
    end
    accessxi.last_quests_menu_main_desc_records_key = key;

    local limit = math.min(count, 12);
    for index = 1, limit do
        local rec = base + ((index - 1) * 0x14);
        if (accessxi.is_probe_pointer(rec)) then
            local p0 = read_u32(rec + 0x00) or 0;
            local p4 = read_u32(rec + 0x04) or 0;
            log_state(('state quests main-desc-record menu="%s" title="%s" reason="%s" row=%d count=%d rec=0x%08X dwords="%s" p0=0x%08X p0Text="%s" p0Dwords="%s" p0Runs="%s" p0Ptrs="%s" p4=0x%08X p4Text="%s" p4Dwords="%s" p4Runs="%s" p4Ptrs="%s"'):fmt(
                tostring(menu_name or ''),
                accessxi.escape_probe_log_text(tostring(title or '')),
                accessxi.escape_probe_log_text(tostring(reason or '')),
                index,
                count,
                rec,
                accessxi.escape_probe_log_text_wide(accessxi.format_probe_dwords(rec, 0x00, 5)),
                p0,
                accessxi.escape_probe_log_text(read_probe_string(p0, 180)),
                accessxi.escape_probe_log_text_wide(accessxi.format_probe_dwords(p0, 0x00, 16)),
                accessxi.escape_probe_log_text(accessxi.status_menu_probe_runs(p0, 0x120)),
                accessxi.escape_probe_log_text(accessxi.status_menu_probe_pointer_fields(p0)),
                p4,
                accessxi.escape_probe_log_text(read_probe_string(p4, 180)),
                accessxi.escape_probe_log_text_wide(accessxi.format_probe_dwords(p4, 0x00, 16)),
                accessxi.escape_probe_log_text(accessxi.status_menu_probe_runs(p4, 0x120)),
                accessxi.escape_probe_log_text(accessxi.status_menu_probe_pointer_fields(p4))));
        end
    end
end

function accessxi.log_quests_menu_submenu_descriptor_records(menu_name, title, desc, selected, count, reason)
    desc = tonumber(desc) or 0;
    selected = tonumber(selected) or 0;
    count = tonumber(count) or 0;
    if (not accessxi.is_probe_pointer(desc) or selected <= 0 or count <= 0 or count > 64) then
        return;
    end

    local base = desc - ((selected - 1) * 0x14);
    if (not accessxi.is_probe_pointer(base)) then
        return;
    end

    local key = ('%s:%s:0x%08X:%d'):fmt(tostring(menu_name or ''), tostring(reason or ''), base, count);
    if (key == tostring(accessxi.last_quests_menu_submenu_desc_records_key or '')) then
        return;
    end
