        accessxi.escape_probe_log_text_wide(accessxi.format_probe_dwords(entry, 0x00, 40)),
        accessxi.escape_probe_log_text(accessxi.status_menu_probe_inline_strings(obj)),
        accessxi.escape_probe_log_text(accessxi.status_menu_probe_inline_strings(child)),
        accessxi.escape_probe_log_text(accessxi.status_menu_probe_inline_strings(entry)),
        accessxi.escape_probe_log_text(accessxi.status_menu_probe_runs(obj, 0x1C0)),
        accessxi.escape_probe_log_text(accessxi.status_menu_probe_runs(child, 0x1C0)),
        accessxi.escape_probe_log_text(accessxi.status_menu_probe_runs(entry, 0x1C0)),
