        accessxi.escape_probe_log_text(accessxi.status_menu_probe_pointer_fields(entry))));
end

function accessxi.log_missions_menu_probe(menu_name, title, obj, selected, count, page, raw, child, entry, reason)
    menu_name = tostring(menu_name or '');
    if (not menu_name:eq('menu    miss00', true)) then
        return;
    end
    if (accessxi.missions_menu_category_probe_enabled ~= true) then
        return;
    end

    obj = tonumber(obj) or 0;
    child = tonumber(child) or 0;
    entry = tonumber(entry) or 0;
    selected = tonumber(selected) or 0;
    count = tonumber(count) or 0;
    page = tonumber(page) or 0;
    raw = tonumber(raw) or 0;

    local target = AshitaCore:GetMemoryManager():GetTarget();
    local window_name = target ~= nil and clean_probe_text(safe_call(function () return target:GetWindowName(); end, '')) or '';
    local ank_num = target ~= nil and (tonumber(safe_call(function () return target:GetWindowAnkNum(); end, -1)) or -1) or -1;
    local ank_x = target ~= nil and (tonumber(safe_call(function () return target:GetWindowAnkX(); end, -1)) or -1) or -1;
    local ank_y = target ~= nil and (tonumber(safe_call(function () return target:GetWindowAnkY(); end, -1)) or -1) or -1;
    local sub = target ~= nil and (tonumber(safe_call(function () return target:GetWindowSub(); end, -1)) or -1) or -1;
    local sub_x = target ~= nil and (tonumber(safe_call(function () return target:GetWindowSubAnkX(); end, -1)) or -1) or -1;
    local sub_y = target ~= nil and (tonumber(safe_call(function () return target:GetWindowSubAnkY(); end, -1)) or -1) or -1;

    local key = ('%s:%s:0x%08X:%d:%d:%d:0x%08X:0x%08X:0x%08X:%d:%d:%d:%d:%d:%d'):fmt(
        menu_name,
        tostring(reason or ''),
        obj,
        selected,
        count,
        page,
        raw,
        child,
        entry,
        ank_num,
        ank_x,
        ank_y,
        sub,
        sub_x,
        sub_y);
    if (key == tostring(accessxi.last_missions_menu_probe_key or '')) then
        return;
    end
    accessxi.last_missions_menu_probe_key = key;

    local label_ptr = accessxi.is_probe_pointer(entry) and (read_u32(entry + 0x44) or 0) or 0;
    local help_ptr = accessxi.is_probe_pointer(entry) and (read_u32(entry + 0x40) or 0) or 0;
    local desc04 = accessxi.is_probe_pointer(entry) and (read_u32(entry + 0x04) or 0) or 0;
    local desc0c = accessxi.is_probe_pointer(entry) and (read_u32(entry + 0x0C) or 0) or 0;
    local desc_rec = accessxi.is_probe_pointer(desc0c) and (read_u32(desc0c + 0x00) or 0) or 0;
    local desc_id = accessxi.is_probe_pointer(desc_rec) and (read_u32(desc_rec + 0x04) or 0) or 0;
    local desc_tag = accessxi.is_probe_pointer(desc_rec) and read_probe_string(desc_rec + 0x24, 48) or '';
    local category, category_ptr, raw_category = accessxi.missions_menu_category_label(entry);
    local context = tostring(accessxi.last_missions_menu_context_label or '');
    local context_age = (tonumber(accessxi.last_missions_menu_context_tick) or 0) > 0 and math.floor(tick() - (tonumber(accessxi.last_missions_menu_context_tick) or 0)) or -1;
    local packet = accessxi.mission_packet_main or {};

    log_state(('state missions probe reason="%s" menu="%s" title="%s" win="%s" obj=0x%08X selected=%d count=%d page=%d raw=0x%08X child=0x%08X entry=0x%08X labelPtr=0x%08X label="%s" helpPtr=0x%08X help="%s" desc04=0x%08X desc04Name="%s" desc0C=0x%08X desc0CName="%s" ank=%d ank=(%d,%d) sub=%d subAnk=(%d,%d)'):fmt(
        tostring(reason or ''),
        menu_name,
        accessxi.escape_probe_log_text(tostring(title or '')),
        accessxi.escape_probe_log_text(window_name),
        obj,
        selected,
        count,
        page,
        raw,
        child,
        entry,
        label_ptr,
        accessxi.escape_probe_log_text(read_probe_string(label_ptr, 160)),
        help_ptr,
        accessxi.escape_probe_log_text(read_probe_string(help_ptr, 220)),
        desc04,
        accessxi.escape_probe_log_text(read_probe_string(desc04 + 0x46, 160)),
        desc0c,
        accessxi.escape_probe_log_text(read_probe_string(desc0c + 0x46, 160)),
        ank_num,
        ank_x,
        ank_y,
        sub,
        sub_x,
        sub_y));

    log_state(('state missions probe row-descriptor selected=%d raw=0x%08X context="%s" contextAge=%d categoryPtr=0x%08X category="%s" categoryRaw="%s" desc0C=0x%08X descRec=0x%08X descId=0x%08X descTag="%s" recDwords="%s" packetAge=%d packetPort=0x%04X packetNation=%d packetNationMission=%d packetZilart=%d packetCop=%d packetCopStatus=0x%08X packetAddons=0x%08X packetTales=0x%08X packetSoa=%d packetRov=%d'):fmt(
        selected,
        raw,
        accessxi.escape_probe_log_text(context),
        context_age,
        tonumber(category_ptr) or 0,
        accessxi.escape_probe_log_text(tostring(category or '')),
        accessxi.escape_probe_log_text(tostring(raw_category or '')),
        desc0c,
        desc_rec,
        desc_id,
        accessxi.escape_probe_log_text(desc_tag),
        accessxi.escape_probe_log_text(accessxi.format_probe_dwords(desc_rec, 0x00, 16)),
        (tonumber(accessxi.mission_packet_tick) or 0) > 0 and math.floor(tick() - (tonumber(accessxi.mission_packet_tick) or 0)) or -1,
        tonumber(packet.port) or 0,
        tonumber(packet.nation) or -1,
        tonumber(packet.nation_mission) or -1,
        tonumber(packet.zilart) or -1,
        tonumber(packet.cop) or -1,
        tonumber(packet.cop_status) or 0,
        tonumber(packet.addons) or 0,
        tonumber(packet.tales) or 0,
        tonumber(packet.soa) or -1,
        tonumber(packet.rov) or -1));

    log_state(('state missions probe memory obj000=%s obj040=%s obj080=%s child000=%s child040=%s child080=%s entry000=%s entry040=%s entry080=%s'):fmt(
        accessxi.escape_probe_log_text(accessxi.format_probe_dwords(obj, 0x00, 16)),
        accessxi.escape_probe_log_text(accessxi.format_probe_dwords(obj, 0x40, 16)),
        accessxi.escape_probe_log_text(accessxi.format_probe_dwords(obj, 0x80, 16)),
        accessxi.escape_probe_log_text(accessxi.format_probe_dwords(child, 0x00, 16)),
        accessxi.escape_probe_log_text(accessxi.format_probe_dwords(child, 0x40, 16)),
        accessxi.escape_probe_log_text(accessxi.format_probe_dwords(child, 0x80, 16)),
        accessxi.escape_probe_log_text(accessxi.format_probe_dwords(entry, 0x00, 16)),
        accessxi.escape_probe_log_text(accessxi.format_probe_dwords(entry, 0x40, 16)),
        accessxi.escape_probe_log_text(accessxi.format_probe_dwords(entry, 0x80, 16))));

    local function is_missions_probe_priority_offset(off)
        return off == 0x04
            or off == 0x08
            or off == 0x0C
            or off == 0x14
            or off == 0x18
            or off == 0x1C
            or off == 0x20
            or off == 0x24
            or off == 0x84
            or off == 0x88
            or off == 0x8C
            or off == 0x90
            or off == 0x94
            or off == 0xA0
            or off == 0xA4
            or off == 0xA8
            or off == 0xAC
            or off == 0xC0;
    end

    local function missions_probe_owner_ptrs(owner, max_offset)
        owner = tonumber(owner) or 0;
        if (not accessxi.is_probe_pointer(owner)) then
            return ('owner=0x%08X unreadable'):fmt(owner);
        end

        local parts = T{};
        local seen = {};
        max_offset = math.max(0, math.min(tonumber(max_offset) or 0xC0, 0x180));
        for off = 0, max_offset, 4 do
            local ptr = read_u32(owner + off) or 0;
            if (accessxi.is_probe_pointer(ptr) and seen[ptr] ~= true) then
                seen[ptr] = true;
                local strings = accessxi.status_menu_probe_inline_strings(ptr);
                local runs = accessxi.status_menu_probe_runs(ptr, 0x180);
                local fields = accessxi.status_menu_probe_pointer_fields(ptr);
                if (is_missions_probe_priority_offset(off) or strings ~= '' or runs ~= '' or fields ~= '') then
                    parts:append(('+%03X=0x%08X dwords=%s strings="%s" runs="%s" ptrs="%s"'):fmt(
                        off,
                        ptr,
                        accessxi.escape_probe_log_text(accessxi.format_probe_dwords(ptr, 0x00, 8)),
                        accessxi.escape_probe_log_text(strings),
                        accessxi.escape_probe_log_text(runs),
                        accessxi.escape_probe_log_text(fields)));
                    if (parts:len() >= 18) then
                        break;
                    end
                end
            elseif (ptr ~= 0 and is_missions_probe_priority_offset(off)) then
                parts:append(('+%03X=0x%08X'):fmt(off, ptr));
                if (parts:len() >= 18) then
                    break;
                end
            end
        end

        return parts:concat(' | ');
    end

    log_state(('state missions probe obj-ptrs %s'):fmt(missions_probe_owner_ptrs(obj, 0xC0)));
    log_state(('state missions probe child-ptrs %s'):fmt(missions_probe_owner_ptrs(child, 0xC0)));

    local function missions_probe_text_block(label, ptr)
        ptr = tonumber(ptr) or 0;
        if (not accessxi.is_probe_pointer(ptr)) then
            log_state(('state missions probe text-block label="%s" ptr=0x%08X unreadable'):fmt(
                accessxi.escape_probe_log_text(tostring(label or '')),
                ptr));
            return;
        end

        log_state(('state missions probe text-block label="%s" ptr=0x%08X d000=%s d040=%s d080=%s d0C0=%s d100=%s runs="%s" inline="%s" ptrs="%s"'):fmt(
            accessxi.escape_probe_log_text(tostring(label or '')),
            ptr,
            accessxi.escape_probe_log_text(accessxi.format_probe_dwords(ptr, 0x00, 16)),
            accessxi.escape_probe_log_text(accessxi.format_probe_dwords(ptr, 0x40, 16)),
            accessxi.escape_probe_log_text(accessxi.format_probe_dwords(ptr, 0x80, 16)),
            accessxi.escape_probe_log_text(accessxi.format_probe_dwords(ptr, 0xC0, 16)),
            accessxi.escape_probe_log_text(accessxi.format_probe_dwords(ptr, 0x100, 16)),
            accessxi.escape_probe_log_text(accessxi.status_menu_probe_runs(ptr, 0x300)),
            accessxi.escape_probe_log_text(accessxi.status_menu_probe_inline_strings(ptr)),
            accessxi.escape_probe_log_text(accessxi.status_menu_probe_pointer_fields(ptr))));
        log_state(('state missions probe text-bytes label="%s" ptr=0x%08X b020=%s b0D0=%s'):fmt(
            accessxi.escape_probe_log_text(tostring(label or '')),
            ptr,
            accessxi.escape_probe_log_text(accessxi.format_probe_bytes(ptr, 0x20, 0xA0)),
            accessxi.escape_probe_log_text(accessxi.format_probe_bytes(ptr, 0xD0, 0xA0))));
    end

    missions_probe_text_block('obj+088', read_u32(obj + 0x88) or 0);

    local ptrs = T{};
    if (accessxi.is_probe_pointer(entry)) then
        for off = 0, 0xC0, 4 do
            local ptr = read_u32(entry + off) or 0;
            if (accessxi.is_probe_pointer(ptr)) then
                local strings = accessxi.status_menu_probe_inline_strings(ptr);
                local runs = accessxi.status_menu_probe_runs(ptr, 0x180);
                local fields = accessxi.status_menu_probe_pointer_fields(ptr);
                if (strings ~= '' or runs ~= '' or fields ~= '') then
                    ptrs:append(('+%03X=0x%08X strings="%s" runs="%s" ptrs="%s"'):fmt(
                        off,
                        ptr,
                        accessxi.escape_probe_log_text(strings),
                        accessxi.escape_probe_log_text(runs),
                        accessxi.escape_probe_log_text(fields)));
                    if (ptrs:len() >= 16) then
                        break;
                    end
                end
            end
        end
    end
    log_state(('state missions probe entry-ptrs %s'):fmt(ptrs:concat(' | ')));

    local shapes = T{};
    if (target ~= nil) then
        local max_shapes = math.min(16, math.max(0, ank_num + 4));
        for i = 0, max_shapes do
            local shape = tonumber(safe_call(function () return target:GetWindowAnkShape(i); end, 0)) or 0;
            if (accessxi.is_probe_pointer(shape)) then
                shapes:append(('%d=0x%08X dwords=%s strings="%s" runs="%s" ptrs="%s"'):fmt(
                    i,
                    shape,
                    accessxi.escape_probe_log_text(accessxi.format_probe_dwords(shape, 0x00, 10)),
                    accessxi.escape_probe_log_text(accessxi.status_menu_probe_inline_strings(shape)),
                    accessxi.escape_probe_log_text(accessxi.status_menu_probe_runs(shape, 0x180)),
                    accessxi.escape_probe_log_text(accessxi.status_menu_probe_pointer_fields(shape))));
            elseif (shape ~= 0) then
                shapes:append(('%d=0x%08X'):fmt(i, shape));
            end
        end
    end
    log_state(('state missions probe shapes %s'):fmt(shapes:concat(' | ')));
end

function accessxi.log_missions_menu_native_text_probe(menu_name, title, obj, selected, count, page, raw, child, entry, context, context_row, native_row_label, native_row_mode, reason)
    menu_name = tostring(menu_name or '');
    if (not menu_name:eq('menu    miss00', true)) then
        return;
    end

    local now = tick();
    if ((tonumber(accessxi.missions_menu_text_probe_until) or 0) < now) then
        return;
    end
    if ((tonumber(accessxi.missions_menu_text_probe_count) or 0) >= (tonumber(accessxi.missions_menu_text_probe_limit) or 32)) then
        return;
    end

    obj = tonumber(obj) or 0;
    child = tonumber(child) or 0;
    entry = tonumber(entry) or 0;
    selected = tonumber(selected) or 0;
    count = tonumber(count) or 0;
    page = tonumber(page) or 0;
    raw = tonumber(raw) or 0;
    context = tostring(context or '');

    local target = AshitaCore:GetMemoryManager():GetTarget();
    local ank_num = target ~= nil and (tonumber(safe_call(function () return target:GetWindowAnkNum(); end, -1)) or -1) or -1;
    local sub = target ~= nil and (tonumber(safe_call(function () return target:GetWindowSub(); end, -1)) or -1) or -1;
    local rom_label = context_row ~= nil and tostring(context_row.label or '') or '';
    local rom_source = context_row ~= nil and tostring(context_row.source or '') or '';
    local key = ('%s:0x%08X:0x%08X:0x%08X:%d:%d:%d:0x%08X:%s:%s:%s:%d:%d'):fmt(
        menu_name,
        obj,
        child,
        entry,
        selected,
        count,
        page,
        raw,
        context,
        tostring(native_row_label or ''),
        rom_label,
        ank_num,
        sub);
    if (key == tostring(accessxi.last_missions_menu_text_probe_key or '')) then
        return;
    end
    accessxi.last_missions_menu_text_probe_key = key;
    accessxi.missions_menu_text_probe_count = (tonumber(accessxi.missions_menu_text_probe_count) or 0) + 1;

    accessxi.menu_dump_sequence = (accessxi.menu_dump_sequence or 0) + 1;
    local seq = accessxi.menu_dump_sequence;
    local old_textptr_budget = accessxi.menu_dump_textptr_budget;
    accessxi.menu_dump_textptr_budget = 28;

    log_state(('state missions native-text-probe seq=%d reason="%s" menu="%s" title="%s" context="%s" select=%d count=%d page=%d raw=0x%08X rawLo=%d obj=0x%08X child=0x%08X entry=0x%08X ank=%d sub=%d nativeLabel="%s" nativeMode="%s" romLabel="%s" romSource="%s" sample=%d until=%d'):fmt(
        seq,
        accessxi.escape_probe_log_text(tostring(reason or '')),
        menu_name,
        accessxi.escape_probe_log_text(tostring(title or '')),
        accessxi.escape_probe_log_text(context),
        selected,
        count,
        page,
        raw,
        bit.band(raw, 0xFFFF),
        obj,
        child,
        entry,
        ank_num,
        sub,
        accessxi.escape_probe_log_text(tostring(native_row_label or '')),
        accessxi.escape_probe_log_text(tostring(native_row_mode or '')),
        accessxi.escape_probe_log_text(rom_label),
        accessxi.escape_probe_log_text(rom_source),
        tonumber(accessxi.missions_menu_text_probe_count) or 0,
        tonumber(accessxi.missions_menu_text_probe_until) or 0));

    local seeds = T{};
    local seen = {};
    local function add_seed(label, ptr)
        ptr = tonumber(ptr) or 0;
        if (not accessxi.is_probe_pointer(ptr) or seen[ptr] == true or seeds:len() >= 20) then
            return;
        end
        seen[ptr] = true;
        seeds:append(T{ label = tostring(label or ''), ptr = ptr });
    end
    local function add_field(owner_label, owner, off)
        owner = tonumber(owner) or 0;
        if (not accessxi.is_probe_pointer(owner)) then
            return;
        end
        add_seed(('%s+%03X'):fmt(owner_label, off), read_u32(owner + off) or 0);
    end

    add_seed('obj', obj);
    add_seed('child', child);
    add_seed('entry', entry);
    add_field('obj', obj, 0x08);
    add_field('obj', obj, 0x0C);
    add_field('obj', obj, 0x88);
    add_field('child', child, 0x14);
    add_field('child', child, 0x18);
    add_field('child', child, 0x20);
    local holder14 = accessxi.is_probe_pointer(child) and (read_u32(child + 0x14) or 0) or 0;
    local holder18 = accessxi.is_probe_pointer(child) and (read_u32(child + 0x18) or 0) or 0;
    add_field('holder14', holder14, 0x10);
    add_field('holder18', holder18, 0x10);
    for _, off in ipairs(T{ 0x04, 0x0C, 0x40, 0x44, 0x58, 0x5C, 0x6C, 0x74, 0x84, 0x88, 0xA8, 0xAC }) do
        add_field('entry', entry, off);
    end

    if (target ~= nil) then
        for i = math.max(0, ank_num - 2), math.min(18, ank_num + 4) do
            add_seed(('shape%d'):fmt(i), tonumber(safe_call(function () return target:GetWindowAnkShape(i); end, 0)) or 0);
        end
    end

    log_line(('menudump seq=%d missiontext begin seeds=%d selected=%d count=%d raw=0x%08X context="%s" native="%s" rom="%s"'):fmt(
        seq,
        seeds:len(),
        selected,
        count,
        raw,
        accessxi.escape_probe_log_text(context),
        accessxi.escape_probe_log_text(tostring(native_row_label or '')),
        accessxi.escape_probe_log_text(rom_label)));

    for _, seed in ipairs(seeds) do
        local label = 'missiontext.' .. tostring(seed.label or '');
        local ptr = tonumber(seed.ptr) or 0;
        log_line(('menudump seq=%d %s ptr=0x%08X dwords=%s strings="%s"'):fmt(
            seq,
            label,
            ptr,
            accessxi.format_probe_dwords(ptr, 0, 20),
            accessxi.escape_probe_log_text(accessxi.probe_strings_at(ptr))));
        accessxi.log_probe_short_text_runs(seq, label, ptr, 0x260, 2, 14);
        accessxi.log_probe_pointer_text_targets(seq, label, ptr, 0x00, 0xC0, 8);
    end

    accessxi.menu_dump_textptr_budget = old_textptr_budget;
    log_line(('menudump seq=%d missiontext end samples=%d'):fmt(seq, tonumber(accessxi.missions_menu_text_probe_count) or 0));
end

function accessxi.log_missions_menu_section_signal(menu_name, title, obj, selected, count, page, raw, child, entry, context, context_row, context_source, desc_id, desc_rec)
    menu_name = tostring(menu_name or '');
    context = tostring(context or '');
    if (not menu_name:eq('menu    miss00', true) or accessxi.mission_rom_table_for_context(context) == nil) then
        return;
    end

    obj = tonumber(obj) or 0;
    child = tonumber(child) or 0;
    entry = tonumber(entry) or 0;
    selected = tonumber(selected) or 0;
    count = tonumber(count) or 0;
    page = tonumber(page) or 0;
    raw = tonumber(raw) or 0;
    desc_id = tonumber(desc_id) or 0;
    desc_rec = tonumber(desc_rec) or 0;
    context_row = context_row or {};

    local target = AshitaCore:GetMemoryManager():GetTarget();
    local window_name = target ~= nil and clean_probe_text(safe_call(function () return target:GetWindowName(); end, '')) or '';
    local ank_num = target ~= nil and (tonumber(safe_call(function () return target:GetWindowAnkNum(); end, -1)) or -1) or -1;
    local ank_x = target ~= nil and (tonumber(safe_call(function () return target:GetWindowAnkX(); end, -1)) or -1) or -1;
    local ank_y = target ~= nil and (tonumber(safe_call(function () return target:GetWindowAnkY(); end, -1)) or -1) or -1;
    local sub = target ~= nil and (tonumber(safe_call(function () return target:GetWindowSub(); end, -1)) or -1) or -1;
    local sub_x = target ~= nil and (tonumber(safe_call(function () return target:GetWindowSubAnkX(); end, -1)) or -1) or -1;
    local sub_y = target ~= nil and (tonumber(safe_call(function () return target:GetWindowSubAnkY(); end, -1)) or -1) or -1;

    local holder14 = accessxi.is_probe_pointer(child) and (read_u32(child + 0x14) or 0) or 0;
    local holder18 = accessxi.is_probe_pointer(child) and (read_u32(child + 0x18) or 0) or 0;
    local render14 = accessxi.is_probe_pointer(holder14) and (read_u32(holder14 + 0x10) or 0) or 0;
    local render18 = accessxi.is_probe_pointer(holder18) and (read_u32(holder18 + 0x10) or 0) or 0;
    local label = tostring(context_row.label or '');
    local mission_id = tonumber(context_row.mission_id) or 0;

    local ank_probe_key = ('%s:0x%08X:0x%08X:0x%08X:%d:%d:%d:0x%08X:%d'):fmt(
        menu_name,
        obj,
        child,
        entry,
        selected,
        count,
        page,
        raw,
        ank_num);
    if (accessxi.missions_menu_category_probe_enabled == true and ank_probe_key ~= tostring(accessxi.last_missions_menu_ank_probe_key or '')) then
        accessxi.last_missions_menu_ank_probe_key = ank_probe_key;
        accessxi.log_missions_menu_native_ank_shape_signal(menu_name, title, selected, count, page, raw, child, entry, ank_num, target);
    end

    local key = ('%s:%s:%d:%d:%d:0x%08X:0x%08X:0x%08X:0x%08X:%s:%d:%d:%d:%d:%d'):fmt(
        menu_name,
        context,
        selected,
        count,
        page,
        raw,
        obj,
        child,
        entry,
        label,
        mission_id,
        ank_num,
        ank_x,
        sub,
        sub_y);
    if (key == tostring(accessxi.last_missions_menu_section_signal_key or '')) then
        return;
    end
    accessxi.last_missions_menu_section_signal_key = key;

    log_state(('state missions section-signal menu="%s" title="%s" win="%s" context="%s" source="%s" select=%d count=%d page=%d raw=0x%08X rawLo=%d obj=0x%08X child=0x%08X entry=0x%08X holder14=0x%08X holder18=0x%08X render14=0x%08X render18=0x%08X ank=%d ank=(%d,%d) sub=%d subAnk=(%d,%d) label="%s" missionId=%d status="%s" statusSource="%s" descId=0x%08X obj080="%s" child000="%s" child010="%s" entry000="%s" entry040="%s" recDwords="%s"'):fmt(
        menu_name,
        accessxi.escape_probe_log_text(tostring(title or '')),
        accessxi.escape_probe_log_text(window_name),
        accessxi.escape_probe_log_text(context),
        accessxi.escape_probe_log_text(tostring(context_source or '')),
        selected,
        count,
        page,
        raw,
        bit.band(raw, 0xFFFF),
        obj,
        child,
        entry,
        holder14,
        holder18,
        render14,
        render18,
        ank_num,
        ank_x,
        ank_y,
        sub,
        sub_x,
        sub_y,
        accessxi.escape_probe_log_text(label),
        mission_id,
        accessxi.escape_probe_log_text(tostring(context_row.status or '')),
        accessxi.escape_probe_log_text(tostring(context_row.status_source or '')),
        desc_id,
        accessxi.escape_probe_log_text(accessxi.format_probe_dwords(obj, 0x80, 8)),
        accessxi.escape_probe_log_text(accessxi.format_probe_dwords(child, 0x00, 8)),
        accessxi.escape_probe_log_text(accessxi.format_probe_dwords(child, 0x10, 8)),
        accessxi.escape_probe_log_text(accessxi.format_probe_dwords(entry, 0x00, 8)),
        accessxi.escape_probe_log_text(accessxi.format_probe_dwords(entry, 0x40, 8)),
        accessxi.escape_probe_log_text(accessxi.format_probe_dwords(desc_rec, 0x00, 12))));
end

