function accessxi.mogpost_receive_fragment_probe(ptr, max_records)
    ptr = tonumber(ptr) or 0;
    if (not accessxi.is_probe_pointer(ptr)) then
        return '';
    end

    max_records = math.max(1, math.min(tonumber(max_records) or 14, 24));
    local parts = T{};
    for index = 0, max_records - 1 do
        local off = index * 0x18;
        local font_ptr = read_u32(ptr + off) or 0;
        local text_ptr1 = read_u32(ptr + off + 0x04) or 0;
        local len1 = read_u32(ptr + off + 0x08) or 0;
        local text_ptr2 = read_u32(ptr + off + 0x0C) or 0;
        local len2 = read_u32(ptr + off + 0x10) or 0;
        local flags = read_u32(ptr + off + 0x14) or 0;

        if (font_ptr == 0 and text_ptr1 == 0 and len1 == 0 and text_ptr2 == 0 and len2 == 0 and flags == 0) then
            parts:append(('%02d@+%02X empty'):fmt(index + 1, off));
        else
            local read_len1 = math.max(1, math.min(len1, 160));
            local read_len2 = math.max(1, math.min(len2, 160));
            local text1 = accessxi.is_probe_pointer(text_ptr1) and read_probe_string(text_ptr1, read_len1) or '';
            local text2 = accessxi.is_probe_pointer(text_ptr2) and read_probe_string(text_ptr2, read_len2) or '';
            parts:append(('%02d@+%02X font=0x%08X p1=0x%08X l1=%d t1="%s" p2=0x%08X l2=%d t2="%s" flags=0x%08X'):fmt(
                index + 1,
                off,
                font_ptr,
                text_ptr1,
                len1,
                accessxi.escape_probe_log_text_wide(text1),
                text_ptr2,
                len2,
                accessxi.escape_probe_log_text_wide(text2),
                flags));
        end
    end

    return parts:concat(' || ');
end

function accessxi.log_mogpost_receive_selected_probe(menu_name, title, obj, selected, count, page, raw, child, entry, reason)
    menu_name = tostring(menu_name or '');
    if (not accessxi.is_mogpost_receive_menu_name(menu_name)) then
        return;
    end

    selected = tonumber(selected) or 0;
    if (selected < 1 or selected > 10) then
        return;
    end

    child = tonumber(child) or 0;
    if (not accessxi.is_probe_pointer(child)) then
        return;
    end

    local row_ptr = read_u32(child + 0x70 + ((selected - 1) * 4)) or 0;
    local row_ptrs = T{};
    for slot = 1, 10 do
        row_ptrs:append(('%02d=0x%08X'):fmt(slot, read_u32(child + 0x70 + ((slot - 1) * 4)) or 0));
    end

    local key = ('%s:%s:%d:%d:0x%08X:0x%08X:0x%08X'):fmt(
        menu_name,
        tostring(reason or ''),
        selected,
        tonumber(count) or 0,
        child,
        tonumber(entry) or 0,
        row_ptr);
    if (key == tostring(accessxi.last_mogpost_receive_selected_probe_key or '')) then
        return;
    end
    accessxi.last_mogpost_receive_selected_probe_key = key;

    log_state(('state mogpost receive-selected reason="%s" title="%s" obj=0x%08X select=%d count=%d page=%d raw=0x%08X child=0x%08X entry=0x%08X row=0x%08X rowPtrs="%s"'):fmt(
        tostring(reason or ''),
        tostring(title or ''),
        tonumber(obj) or 0,
        selected,
        tonumber(count) or 0,
        tonumber(page) or 0,
        tonumber(raw) or 0,
        child,
        tonumber(entry) or 0,
        row_ptr,
        row_ptrs:concat(' ')));

    if (accessxi.is_probe_pointer(row_ptr)) then
        log_state(('state mogpost receive-selected-fragments select=%d ptr=0x%08X fragments="%s"'):fmt(
            selected,
            row_ptr,
            accessxi.mogpost_receive_fragment_probe(row_ptr, 16)));

        log_state(('state mogpost receive-selected-row select=%d ptr=0x%08X dwords000=%s dwords040=%s inline="%s" runs="%s" ptrs="%s"'):fmt(
            selected,
            row_ptr,
            accessxi.escape_probe_log_text_wide(accessxi.format_probe_dwords(row_ptr, 0x00, 16)),
            accessxi.escape_probe_log_text_wide(accessxi.format_probe_dwords(row_ptr, 0x40, 16)),
            accessxi.escape_probe_log_text_wide(accessxi.status_menu_probe_inline_strings(row_ptr)),
            accessxi.escape_probe_log_text_wide(accessxi.status_menu_probe_runs(row_ptr, 0x100)),
            accessxi.escape_probe_log_text_wide(accessxi.status_menu_probe_pointer_fields(row_ptr))));

        local near = row_ptr - 0x80;
        if (accessxi.is_probe_pointer(near)) then
            log_state(('state mogpost receive-selected-near select=%d ptr=0x%08X near=0x%08X dwords000=%s inline="%s" runs="%s" ptrs="%s"'):fmt(
                selected,
                row_ptr,
                near,
                accessxi.escape_probe_log_text_wide(accessxi.format_probe_dwords(near, 0x00, 24)),
                accessxi.escape_probe_log_text_wide(accessxi.status_menu_probe_inline_strings(near)),
                accessxi.escape_probe_log_text_wide(accessxi.status_menu_probe_runs(near, 0x180)),
                accessxi.escape_probe_log_text_wide(accessxi.status_menu_probe_pointer_fields(near))));
        end
    end

    entry = tonumber(entry) or 0;
    if (accessxi.is_probe_pointer(entry)) then
        log_state(('state mogpost receive-selected-entry select=%d entry=0x%08X dwords000=%s dwords040=%s inline="%s" runs="%s" ptrs="%s"'):fmt(
            selected,
            entry,
            accessxi.escape_probe_log_text_wide(accessxi.format_probe_dwords(entry, 0x00, 16)),
            accessxi.escape_probe_log_text_wide(accessxi.format_probe_dwords(entry, 0x40, 16)),
            accessxi.escape_probe_log_text_wide(accessxi.status_menu_probe_inline_strings(entry)),
            accessxi.escape_probe_log_text_wide(accessxi.status_menu_probe_runs(entry, 0x120)),
            accessxi.escape_probe_log_text_wide(accessxi.status_menu_probe_pointer_fields(entry))));
    end
end

function accessxi.log_mogpost_receive_rows_probe(menu_name, title, obj, selected, count, page, raw, child, entry, reason)
    menu_name = tostring(menu_name or '');
    if (not accessxi.is_mogpost_receive_menu_name(menu_name)) then
        return;
    end

    child = tonumber(child) or 0;
    if (not accessxi.is_probe_pointer(child)) then
        return;
    end

    selected = tonumber(selected) or 0;
    local ptrs = T{};
    for slot = 1, 10 do
        local ptr = read_u32(child + 0x70 + ((slot - 1) * 4)) or 0;
        ptrs:append(('%02d=0x%08X'):fmt(slot, ptr));
    end

    local key = ('%s:%s:%d:%d:0x%08X:%s'):fmt(
        menu_name,
        tostring(reason or ''),
        selected,
        tonumber(count) or 0,
        child,
        ptrs:concat(','));
    if (key == tostring(accessxi.last_mogpost_receive_rows_probe_key or '')) then
        return;
    end
    accessxi.last_mogpost_receive_rows_probe_key = key;

    log_state(('state mogpost receive-rows reason="%s" title="%s" obj=0x%08X selected=%d count=%d page=%d raw=0x%08X child=0x%08X entry=0x%08X rowPtrs="%s"'):fmt(
        tostring(reason or ''),
        tostring(title or ''),
        tonumber(obj) or 0,
        selected,
        tonumber(count) or 0,
        tonumber(page) or 0,
        tonumber(raw) or 0,
        child,
        tonumber(entry) or 0,
        ptrs:concat(' ')));

    for slot = 1, 10 do
        local ptr = read_u32(child + 0x70 + ((slot - 1) * 4)) or 0;
        if (accessxi.is_probe_pointer(ptr)) then
            log_state(('state mogpost receive-row slot=%d ptr=0x%08X selected=%d dwords000=%s dwords040=%s inline="%s" runs="%s" ptrs="%s"'):fmt(
                slot,
                ptr,
                slot == selected and 1 or 0,
                accessxi.escape_probe_log_text_wide(accessxi.format_probe_dwords(ptr, 0x00, 12)),
                accessxi.escape_probe_log_text_wide(accessxi.format_probe_dwords(ptr, 0x40, 12)),
                accessxi.escape_probe_log_text_wide(accessxi.status_menu_probe_inline_strings(ptr)),
                accessxi.escape_probe_log_text_wide(accessxi.status_menu_probe_runs(ptr, 0x100)),
                accessxi.escape_probe_log_text_wide(accessxi.status_menu_probe_pointer_fields(ptr))));

            local near = ptr - 0x80;
            if (slot == selected and accessxi.is_probe_pointer(near)) then
                log_state(('state mogpost receive-row-near slot=%d ptr=0x%08X near=0x%08X dwords000=%s inline="%s" runs="%s" ptrs="%s"'):fmt(
                    slot,
                    ptr,
                    near,
                    accessxi.escape_probe_log_text_wide(accessxi.format_probe_dwords(near, 0x00, 24)),
                    accessxi.escape_probe_log_text_wide(accessxi.status_menu_probe_inline_strings(near)),
                    accessxi.escape_probe_log_text_wide(accessxi.status_menu_probe_runs(near, 0x180)),
                    accessxi.escape_probe_log_text_wide(accessxi.status_menu_probe_pointer_fields(near))));
            end
        end
    end
end

function accessxi.log_mogpost_menu_probe(menu_name, title, obj, selected, count, page, raw, child, entry, reason)
    menu_name = tostring(menu_name or '');
    if (not accessxi.is_mogpost_menu_name(menu_name)) then
        return;
    end

    local now = tick();
    if (now >= (tonumber(accessxi.mogpost_probe_until) or 0)) then
        return;
    end

    obj = tonumber(obj) or 0;
    if (not accessxi.is_probe_pointer(obj)) then
        return;
    end

    selected = tonumber(selected) or 0;
    count = tonumber(count) or 0;
    page = tonumber(page) or 0;
    raw = tonumber(raw) or 0;
    child = tonumber(child) or 0;
    entry = tonumber(entry) or 0;

    local target = safe_call(function () return AshitaCore:GetMemoryManager():GetTarget(); end, nil);
    local ank_num = target ~= nil and (tonumber(safe_call(function () return target:GetWindowAnkNum(); end, -1)) or -1) or -1;
    local ank_x = target ~= nil and (tonumber(safe_call(function () return target:GetWindowAnkX(); end, -1)) or -1) or -1;
    local ank_y = target ~= nil and (tonumber(safe_call(function () return target:GetWindowAnkY(); end, -1)) or -1) or -1;
    local sub = target ~= nil and (tonumber(safe_call(function () return target:GetWindowSub(); end, -1)) or -1) or -1;
    local sub_x = target ~= nil and (tonumber(safe_call(function () return target:GetWindowSubAnkX(); end, -1)) or -1) or -1;
    local sub_y = target ~= nil and (tonumber(safe_call(function () return target:GetWindowSubAnkY(); end, -1)) or -1) or -1;
    local indexes = T{};
    for _, off in ipairs(T{ 0x10, 0x1C, 0x20, 0x24, 0x28, 0x2C, 0x30, 0x34, 0x38, 0x3C, 0x40, 0x44, 0x48, 0x4C, 0x50, 0x54, 0x58, 0x5C, 0x60, 0x64, 0x68, 0x6C, 0x70, 0x74, 0x78, 0x7C, 0x80 }) do
        local value = read_i32(obj + off);
        if (value ~= nil and value >= -4 and value <= 256) then
            indexes:append(('+%02X=%d'):fmt(off, value));
        end
    end

    local key = ('%s:%s:0x%08X:%d:%d:%d:0x%08X:0x%08X:0x%08X:0x%08X:%d:%d:%d:%d:%d:%d:%s'):fmt(
        menu_name,
        tostring(reason or ''),
        obj,
        selected,
        count,
        page,
        raw,
        child,
        entry,
        accessxi.is_probe_pointer(entry) and (read_u32(entry + 0x0C) or 0) or 0,
        ank_num,
        ank_x,
        ank_y,
        sub,
        sub_x,
        sub_y,
        indexes:concat(' '));
    if (key == tostring(accessxi.last_mogpost_menu_probe_key or '')) then
        return;
    end
    accessxi.last_mogpost_menu_probe_key = key;

    log_state(('state mogpost probe reason="%s" title="%s" obj=0x%08X selected=%d count=%d page=%d raw=0x%08X child=0x%08X entry=0x%08X ankNum=%d ank=(%d,%d) sub=%d subAnk=(%d,%d) indexes="%s"'):fmt(
        tostring(reason or ''),
        tostring(title or ''),
        obj,
        selected,
        count,
        page,
        raw,
        child,
        entry,
        ank_num,
        ank_x,
        ank_y,
        sub,
        sub_x,
        sub_y,
        indexes:concat(' ')));

    accessxi.log_mogpost_receive_rows_probe(menu_name, title, obj, selected, count, page, raw, child, entry, reason);

    log_state(('state mogpost probe obj dwords000=%s dwords040=%s dwords080=%s inline="%s" ptrs="%s"'):fmt(
        accessxi.escape_probe_log_text_wide(accessxi.format_probe_dwords(obj, 0x00, 16)),
        accessxi.escape_probe_log_text_wide(accessxi.format_probe_dwords(obj, 0x40, 16)),
        accessxi.escape_probe_log_text_wide(accessxi.format_probe_dwords(obj, 0x80, 16)),
        accessxi.escape_probe_log_text_wide(accessxi.status_menu_probe_inline_strings(obj)),
        accessxi.escape_probe_log_text_wide(accessxi.status_menu_probe_pointer_fields(obj))));

    if (accessxi.is_probe_pointer(child)) then
        log_state(('state mogpost probe child dwords000=%s dwords040=%s dwords080=%s inline="%s" runs="%s" ptrs="%s"'):fmt(
            accessxi.escape_probe_log_text_wide(accessxi.format_probe_dwords(child, 0x00, 16)),
            accessxi.escape_probe_log_text_wide(accessxi.format_probe_dwords(child, 0x40, 16)),
            accessxi.escape_probe_log_text_wide(accessxi.format_probe_dwords(child, 0x80, 16)),
            accessxi.escape_probe_log_text_wide(accessxi.status_menu_probe_inline_strings(child)),
            accessxi.escape_probe_log_text_wide(accessxi.status_menu_probe_runs(child, 0x240)),
            accessxi.escape_probe_log_text_wide(accessxi.status_menu_probe_pointer_fields(child))));
    end

    if (accessxi.is_probe_pointer(entry)) then
        local desc = read_u32(entry + 0x0C) or 0;
        log_state(('state mogpost probe entry desc=0x%08X labelPtr=0x%08X helpPtr=0x%08X dwords000=%s dwords040=%s inline="%s" runs="%s" ptrs="%s"'):fmt(
            desc,
            read_u32(entry + 0x44) or 0,
            read_u32(entry + 0x40) or 0,
            accessxi.escape_probe_log_text_wide(accessxi.format_probe_dwords(entry, 0x00, 16)),
            accessxi.escape_probe_log_text_wide(accessxi.format_probe_dwords(entry, 0x40, 16)),
            accessxi.escape_probe_log_text_wide(accessxi.status_menu_probe_inline_strings(entry)),
            accessxi.escape_probe_log_text_wide(accessxi.status_menu_probe_runs(entry - 0x100, 0x300)),
            accessxi.escape_probe_log_text_wide(accessxi.status_menu_probe_pointer_fields(entry))));
        if (accessxi.is_probe_pointer(desc)) then
            log_state(('state mogpost probe desc dwords000=%s dwords040=%s inline="%s" runs="%s" desc46="%s" table="%s" ptrs="%s"'):fmt(
                accessxi.escape_probe_log_text_wide(accessxi.format_probe_dwords(desc, 0x00, 16)),
                accessxi.escape_probe_log_text_wide(accessxi.format_probe_dwords(desc, 0x40, 16)),
                accessxi.escape_probe_log_text_wide(accessxi.status_menu_probe_inline_strings(desc)),
                accessxi.escape_probe_log_text_wide(accessxi.status_menu_probe_runs(desc - 0x100, 0x300)),
                accessxi.escape_probe_log_text_wide(read_probe_string(desc + 0x46)),
                accessxi.escape_probe_log_text_wide(accessxi.status_menu_probe_desc_table(desc, selected)),
                accessxi.escape_probe_log_text_wide(accessxi.status_menu_probe_pointer_fields(desc))));
        end
    end

    if (target ~= nil) then
        local max_shapes = math.min(12, math.max(0, ank_num + 4));
        for i = 0, max_shapes do
            local shape = tonumber(safe_call(function () return target:GetWindowAnkShape(i); end, 0)) or 0;
            if (shape ~= 0) then
                log_state(('state mogpost probe shape%d=0x%08X dwords000=%s dwords040=%s inline="%s" runs="%s" ptrs="%s"'):fmt(
                    i,
                    shape,
                    accessxi.escape_probe_log_text_wide(accessxi.format_probe_dwords(shape, 0x00, 16)),
                    accessxi.escape_probe_log_text_wide(accessxi.format_probe_dwords(shape, 0x40, 16)),
                    accessxi.escape_probe_log_text_wide(accessxi.status_menu_probe_inline_strings(shape)),
                    accessxi.escape_probe_log_text_wide(accessxi.status_menu_probe_runs(shape, 0x220)),
                    accessxi.escape_probe_log_text_wide(accessxi.status_menu_probe_pointer_fields(shape))));
            end
        end
    end
end

function accessxi.synthesis_probe_pointer_strings(ptr)
    ptr = tonumber(ptr) or 0;
    if (not accessxi.is_probe_pointer(ptr)) then
        return '';
    end

    local parts = T{};
    for _, off in ipairs(T{ 0x00, 0x04, 0x08, 0x0C, 0x10, 0x14, 0x18, 0x1C, 0x20, 0x24, 0x28, 0x2C, 0x30, 0x34, 0x38, 0x3C, 0x40, 0x44, 0x48, 0x4C, 0x50, 0x54, 0x58, 0x5C, 0x60, 0x64, 0x68, 0x6C, 0x70, 0x74, 0x78, 0x7C, 0x80, 0x84, 0x88, 0x8C, 0x90, 0x94, 0x98, 0x9C, 0xA0, 0xA4, 0xA8, 0xAC, 0xB0, 0xB4, 0xB8, 0xBC, 0xC0 }) do
        local candidate = read_u32(ptr + off) or 0;
        if (accessxi.is_probe_pointer(candidate)) then
            local direct = read_probe_string(candidate, 160);
            local plus40 = read_probe_string(candidate + 0x40, 160);
            local plus44 = read_probe_string(candidate + 0x44, 160);
            local plus46 = read_probe_string(candidate + 0x46, 160);
            local run = accessxi.probe_runs_to_text(accessxi.collect_probe_ascii_runs(candidate, 0x180, 3, 5));
            if (direct ~= '' or plus40 ~= '' or plus44 ~= '' or plus46 ~= '' or run ~= '') then
                parts:append(('+%03X=0x%08X text="%s" +40="%s" +44="%s" +46="%s" runs="%s"'):fmt(
                    off,
                    candidate,
                    accessxi.escape_probe_log_text_wide(direct),
                    accessxi.escape_probe_log_text_wide(plus40),
                    accessxi.escape_probe_log_text_wide(plus44),
                    accessxi.escape_probe_log_text_wide(plus46),
                    accessxi.escape_probe_log_text_wide(run)));
            end
        end
    end
    return parts:concat(' || ');
end

function accessxi.log_synthesis_selected_entry_probe(obj, selected, entry)
    obj = tonumber(obj) or 0;
    selected = tonumber(selected) or 0;
    entry = tonumber(entry) or 0;
    if (not accessxi.is_probe_pointer(entry)) then
        return;
    end

    local direct = T{};
    for _, off in ipairs(T{ 0x40, 0x44, 0x58, 0x5C, 0x60, 0x68, 0x6C, 0xA8, 0xAC, 0xB8, 0xBC, 0xC0, 0xD4, 0x110, 0x114, 0x150, 0x154 }) do
        local ptr = read_u32(entry + off) or 0;
        local text = accessxi.plain_native_menu_label(read_probe_string(ptr, 220));
        if (accessxi.is_probe_pointer(ptr) or text ~= '') then
            direct:append(('+%03X=0x%08X "%s"'):fmt(
                off,
                ptr,
                accessxi.escape_probe_log_text_wide(text)));
        end
    end
    log_line(('synthentry-direct selected=%d entry=0x%08X %s'):fmt(
        selected,
        entry,
        direct:concat(' | ')));

    log_line(('synthentry selected=%d obj=0x%08X entry=0x%08X d000=%s d040=%s d080=%s d0C0=%s d100=%s d140=%s'):fmt(
        selected,
        obj,
        entry,
        accessxi.format_probe_dwords(entry, 0x00, 16),
        accessxi.format_probe_dwords(entry, 0x40, 16),
        accessxi.format_probe_dwords(entry, 0x80, 16),
        accessxi.format_probe_dwords(entry, 0xC0, 16),
        accessxi.format_probe_dwords(entry, 0x100, 16),
        accessxi.format_probe_dwords(entry, 0x140, 16)));

    log_line(('synthentry-text selected=%d entry=0x%08X inline="%s" runs="%s" ptrs="%s"'):fmt(
        selected,
        entry,
        accessxi.escape_probe_log_text_wide(accessxi.status_menu_probe_inline_strings(entry)),
        accessxi.escape_probe_log_text_wide(accessxi.status_menu_probe_runs(entry, 0x260)),
        accessxi.escape_probe_log_text_wide(accessxi.synthesis_probe_pointer_strings(entry))));

    local desc = read_u32(entry + 0x04) or 0;
    if (accessxi.is_probe_pointer(desc)) then
        log_line(('synthentry-desc selected=%d entry=0x%08X desc=0x%08X d000=%s d040=%s d080=%s text="%s" runs="%s" ptrs="%s"'):fmt(
            selected,
            entry,
            desc,
            accessxi.format_probe_dwords(desc, 0x00, 16),
            accessxi.format_probe_dwords(desc, 0x40, 16),
            accessxi.format_probe_dwords(desc, 0x80, 16),
            accessxi.escape_probe_log_text_wide(accessxi.status_menu_probe_inline_strings(desc)),
            accessxi.escape_probe_log_text_wide(accessxi.status_menu_probe_runs(desc, 0x260)),
            accessxi.escape_probe_log_text_wide(accessxi.synthesis_probe_pointer_strings(desc))));
    end
end

function accessxi.log_synthesis_cmbmenu_probe(menu_name, title, selected, count, page, raw, child, reason)
    menu_name = tostring(menu_name or '');
    if (accessxi.synthesis_cmbmenu_probe_enabled ~= true) then
        return;
    end
    if (not menu_name:eq('menu    cmbmenu', true) or not tostring(title or ''):eq('Synthesis', true)) then
        return;
    end

    local obj = get_current_menu_object_ptr();
    if (obj == 0) then
        return;
    end

    selected = tonumber(selected) or 0;
    count = tonumber(count) or 0;
    local entry = read_u32(obj + 0x08) or 0;
    local key = ('%s:0x%08X:%d:%d:0x%08X:0x%08X:%s'):fmt(
        menu_name,
        obj,
        selected,
        count,
        tonumber(child) or 0,
        entry,
        tostring(reason or ''));
    if (key == (accessxi.last_synthesis_cmbmenu_probe_key or '')) then
        return;
    end
    accessxi.last_synthesis_cmbmenu_probe_key = key;

    local small = T{};
    for off = 0, 0x1C0, 4 do
        local value = read_i32(obj + off);
        if (value ~= nil and value >= -4096 and value <= 4096) then
            small:append(('+%03X=%d'):fmt(off, value));
        end
    end

    log_line(('synthprobe menu="%s" reason="%s" obj=0x%08X selected=%d count=%d page=%d raw=0x%08X child=0x%08X entry=0x%08X small="%s"'):fmt(
        menu_name,
        tostring(reason or ''),
        obj,
        selected,
        count,
        tonumber(page) or 0,
        tonumber(raw) or 0,
        tonumber(child) or 0,
        entry,
        accessxi.escape_probe_log_text(small:concat(' '))));

    log_line(('synthprobe obj obj=0x%08X dwords000="%s" dwords040="%s" dwords080="%s" dwords0C0="%s" dwords100="%s" inline="%s" runs="%s" ptrs="%s"'):fmt(
        obj,
        accessxi.format_probe_dwords(obj, 0x00, 16),
        accessxi.format_probe_dwords(obj, 0x40, 16),
        accessxi.format_probe_dwords(obj, 0x80, 16),
        accessxi.format_probe_dwords(obj, 0xC0, 16),
        accessxi.format_probe_dwords(obj, 0x100, 16),
        accessxi.escape_probe_log_text(accessxi.status_menu_probe_inline_strings(obj)),
        accessxi.escape_probe_log_text(accessxi.status_menu_probe_runs(obj, 0x240)),
        accessxi.escape_probe_log_text(accessxi.status_menu_probe_pointer_fields(obj))));

    accessxi.log_synthesis_selected_entry_probe(obj, selected, entry);

    local seen = {};
    local logged = 0;
    for off = 0, 0x220, 4 do
        if (logged >= 8) then
            break;
        end
        local ptr = read_u32(obj + off) or 0;
        if (accessxi.is_probe_pointer(ptr) and seen[ptr] ~= true) then
            seen[ptr] = true;
            local desc = read_u32(ptr + 0x04) or 0;
            local desc_name = accessxi.is_probe_pointer(desc) and read_probe_string(desc + 0x46) or '';
            local inline = accessxi.status_menu_probe_inline_strings(ptr);
            local runs = accessxi.status_menu_probe_runs(ptr, 0x240);
            local ptrs = accessxi.status_menu_probe_pointer_fields(ptr);
            if (desc_name ~= '' or inline ~= '' or runs ~= '' or ptrs ~= '') then
                logged = logged + 1;
                log_line(('synthptr obj=0x%08X +%03X->0x%08X desc=0x%08X descName="%s" dwords="%s" inline="%s" runs="%s" ptrs="%s"'):fmt(
                    obj,
                    off,
                    ptr,
                    desc,
                    accessxi.escape_probe_log_text(desc_name),
                    accessxi.escape_probe_log_text(accessxi.format_probe_dwords(ptr, 0, 24)),
                    accessxi.escape_probe_log_text(inline),
                    accessxi.escape_probe_log_text(runs),
                    accessxi.escape_probe_log_text(ptrs)));
            end
        end
    end

    if (accessxi.is_probe_pointer(child)) then
        log_line(('synthchild child=0x%08X dwords="%s" inline="%s" runs="%s" ptrs="%s"'):fmt(
            tonumber(child) or 0,
            accessxi.escape_probe_log_text(accessxi.format_probe_dwords(child, 0, 32)),
            accessxi.escape_probe_log_text(accessxi.status_menu_probe_inline_strings(child)),
            accessxi.escape_probe_log_text(accessxi.status_menu_probe_runs(child, 0x240)),
            accessxi.escape_probe_log_text(accessxi.status_menu_probe_pointer_fields(child))));
    end
end

function accessxi.status_menu_native_description_for_entry(entry)
    entry = tonumber(entry) or 0;
    if (not accessxi.is_probe_pointer(entry)) then
        return '', 0, 0;
    end

    local desc = read_u32(entry + 0x0C) or 0;
    if (not accessxi.is_probe_pointer(desc)) then
        return '', 0, desc;
    end

    local row2 = read_u32(desc + 0x08) or 0;
    if (not accessxi.is_probe_pointer(row2)) then
        return '', row2, desc;
    end

    local text = accessxi.status_menu_native_description_text(read_probe_string(row2, 220));
    if (text == '') then
        return '', row2, desc;
    end

    return text, row2, desc;
end

function accessxi.status_menu_native_row_code(desc)
    desc = tonumber(desc) or 0;
    if (not accessxi.is_probe_pointer(desc)) then
        return 0, 0;
    end

    local row0 = read_u32(desc + 0x00) or 0;
    if (not accessxi.is_probe_pointer(row0)) then
        return 0, row0;
    end

    return read_u32(row0 + 0x04) or 0, row0;
end

function accessxi.status_menu_native_label_for_description(description, desc)
    description = accessxi.status_menu_native_description_text(description or '');
    if (description == '') then
        return '', 0, 0;
    end

    local row_code, row0 = accessxi.status_menu_native_row_code(desc);
    if (description:contains('View your profile including current allegiance and title.', true)) then
        return 'Profile', row0, row_code;
    end
    if (description:contains('View all job levels achieved so far.', true)) then
        return 'Job Levels', row0, row_code;
    end
    if (description:contains('View all master levels achieved so far.', true)) then
        return 'Master Levels', row0, row_code;
    end
    if (description:contains('View current combat skills.', true)) then
        return 'Combat Skills', row0, row_code;
    end
    if (description:contains('View current magic skills.', true)) then
        return 'Magic Skills', row0, row_code;
    end
    if (description:contains('View current craft skills.', true)) then
        return 'Craft Skills', row0, row_code;
    end
    if (description:contains('Displays the currencies earned from various pieces of content.', true)) then
        if (row_code == 0x76) then
            return 'Currencies 2', row0, row_code;
        end
        return 'Currencies', row0, row_code;
    end
    if (description:contains('Display a list of items related to Unity Concord.', true)) then
        return 'Unity', row0, row_code;
    end
    if (description:contains('Display total time spent in Vana', true)) then
        return 'Play Time', row0, row_code;
    end
    if (description:contains('Specialize your character by trading merit points', true)) then
        return 'Merit Points', row0, row_code;
    end
    if (description:contains('Displays the list of jobs to which you may apply job points.', true)) then
        return 'Job Points', row0, row_code;
    end
    if (description:contains('alter ego points may be spent to increase attributes.', true)) then
        return 'Alter Ego Points', row0, row_code;
    end

    return '', row0, row_code;
end

function accessxi.magic_menu_label_from_description(description)
    description = accessxi.status_menu_native_description_text(description or '');
    if (description == '') then
        return '';
    end

    local label = description:match('^[Vv]iew list of ([^%.]+)%.') or '';
    if (label == '') then
        label = description:match('^[Dd]isplay a list of ([^%.]+)%.') or '';
    end
    if (label == '') then
        return '';
    end

    label = accessxi.survival_guide_text(label);
    if (label == '') then
        return '';
    end

    label = label:gsub('(%a)([%w\']*)', function (first, rest)
        return first:upper() .. rest:lower();
    end);
    return label;
end

function accessxi.ability_menu_label_from_description(description)
    description = accessxi.status_menu_native_description_text(description or '');
    if (description == '') then
        return '';
    end

    if (description:contains('View bonuses and other traits of current jobs.', true)) then
        return 'Job Traits';
    end
    if (description:contains('Activate special abilities of current jobs.', true)) then
        return 'Job Abilities';
    end
    if (description:contains('Use TP to perform special attacks associated with equipped weapon type.', true)) then
        return 'Weapon Skills';
    end
    if (description:contains('Attack current target with ranged weapon.', true)) then
        return 'Ranged Attack';
    end
    if (description:contains('Issue command to pet monster.', true)) then
        return 'Pet Commands';
    end
    if (description:contains('Call forth your mount.', true)) then
        return 'Mounts';
    end

    return '';
end

function accessxi.unity_menu_label_from_description(description)
    description = accessxi.status_menu_native_description_text(description or '');
    if (description == '') then
        return '';
    end

    if (description:contains('Display information about your Unity.', true)) then
        return 'Unity';
    end
    if (description:contains('Display information about Unity rankings.', true)) then
        return 'Unity Rankings';
    end
    if (description:contains('Display the members logged in to the designated Unity.', true)) then
        return 'Unity Members';
    end

    return '';
end

function accessxi.magic_category_type(label)
    label = tostring(label or '');
    if (label:eq('White Magic', true)) then
        return 1;
    end
    if (label:eq('Black Magic', true)) then
        return 2;
    end
    if (label:eq('Summoning Magic', true)) then
        return 3;
    end
    if (label:eq('Ninjutsu', true)) then
        return 4;
    end
    if (label:eq('Songs', true) or label:eq('Bard Song', true) or label:eq('Bard Songs', true)) then
        return 5;
    end
    if (label:eq('Blue Magic', true)) then
        return 6;
    end
    if (label:eq('Geomancy', true)) then
        return 7;
    end
    if (label:eq('Trust Magic', true) or label:eq('Trust', true)) then
        return 8;
    end
    return 0;
end

function accessxi.magic_spell_description_text(text)
    text = accessxi.survival_guide_text(text or '');
    if (text == '') then
        return '';
    end

    text = text:gsub('^["\']+', ''):gsub('["\']+$', '');
    text = text:gsub('%s+ww$', '');
    text = accessxi.survival_guide_text(text);
    if (text == '' or #text > 260) then
        return '';
    end
    if (text:match('^menu%s+') ~= nil or text:match('keytops') ~= nil or text:match('windowps') ~= nil) then
        return '';
    end
    if (text:match('^[%p%s]+$') ~= nil) then
        return '';
    end

    return text;
end

function accessxi.magic_spell_element_name(element)
    element = tonumber(element);
    if (element == 0) then return 'Fire'; end
    if (element == 1) then return 'Ice'; end
    if (element == 2) then return 'Wind'; end
    if (element == 3) then return 'Earth'; end
    if (element == 4) then return 'Lightning'; end
    if (element == 5) then return 'Water'; end
    if (element == 6) then return 'Light'; end
    if (element == 7) then return 'Dark'; end
    return '';
end

function accessxi.magic_spell_geomancy_level(spell)
    if (spell == nil or spell.LevelRequired == nil) then
        return 0;
    end
    return tonumber(spell.LevelRequired[21 + 1]) or 0;
end

function accessxi.magic_spell_level_required(spell, job)
    job = tonumber(job) or 0;
    if (spell == nil or spell.LevelRequired == nil or job < 0 or job > 23) then
        return -1;
    end
    return tonumber(spell.LevelRequired[job + 1]) or -1;
end

function accessxi.magic_spell_resource_info(id)
    id = tonumber(id) or 0;
    if (id <= 0 or id > 2048) then
        return nil;
    end

    local resources = AshitaCore:GetResourceManager();
    if (resources == nil) then
        return nil;
    end

    local spell = safe_call(function () return resources:GetSpellById(id); end, nil);
    if (spell == nil or spell.Name == nil) then
        return nil;
    end

    local name = accessxi.plain_native_menu_label(accessxi.survival_guide_text(spell.Name[1] or ''));
    if (name == '' or name:eq('Unknown', true)) then
        return nil;
    end

    local description = spell.Description ~= nil and accessxi.magic_spell_description_text(spell.Description[1] or '') or '';
    local levels = T{};
    for job = 0, 23 do
        levels[job] = accessxi.magic_spell_level_required(spell, job);
    end
    return T{
        id = id,
        index = tonumber(spell.Index) or id,
        sort_id = tonumber(spell.Id) or id,
        name = name,
        description = description,
        type = tonumber(spell.Type) or 0,
        element = tonumber(spell.Element) or 15,
        geomancy_level = accessxi.magic_spell_geomancy_level(spell),
        skill = tonumber(spell.Skill) or 0,
        mp = tonumber(spell.ManaCost) or 0,
        job_point_mask = tonumber(spell.JobPointMask) or 0,
        levels = levels,
    };
end

function accessxi.magic_current_category_label()
    local label = tostring(accessxi.current_magic_category_label or '');
    if (label ~= '') then
        return label;
    end

    label = tostring(accessxi.last_magic_category_label or '');
    if (label ~= '') then
        return label;
    end

    return '';
end

function accessxi.ability_current_category_label()
    local label = tostring(accessxi.current_ability_category_label or '');
    if (label ~= '') then
        return label;
    end

    label = tostring(accessxi.last_ability_category_label or '');
    if (label ~= '') then
        return label;
    end

    return '';
end

function accessxi.ability_effective_category_label()
    if (accessxi.ability_shortcut_list_active == true) then
        local shortcut_label = tostring(accessxi.ability_shortcut_active_category_label or '');
        if (shortcut_label:eq('Weapon Skills', true)) then
            return 'Weapon Skills', 'shortcut';
        end
        if (shortcut_label:eq('Job Abilities', true)) then
            return 'Job Abilities', 'shortcut';
        end
        return '', 'direct';
    end

    local label = accessxi.ability_current_category_label();
    if (label ~= '') then
        return label, 'category';
    end

    return '', '';
end

function accessxi.magic_known_spell_list_for_category(label)
    local wanted_type = accessxi.magic_category_type(label);
    if (wanted_type <= 0) then
        return T{}, wanted_type;
    end

    local cache_key = tostring(label or ''):lower();
    local now = tick();
    if (accessxi.magic_known_cache ~= nil
        and tostring(accessxi.magic_known_cache_key or '') == cache_key
        and tonumber(accessxi.magic_known_cache_type) == wanted_type
        and (now - (tonumber(accessxi.magic_known_cache_tick) or 0)) < 1000) then
        return accessxi.magic_known_cache, wanted_type;
    end

    local player = AshitaCore:GetMemoryManager():GetPlayer();
    if (player == nil) then
        return T{}, wanted_type;
    end

    local spells = T{};
    for id = 0, 2048 do
        if (safe_call(function () return player:HasSpell(id); end, false) == true) then
            local info = accessxi.magic_spell_resource_info(id);
            if (info ~= nil and info.type == wanted_type) then
                spells:append(info);
            end
        end
    end

    spells:sort(function (a, b)
        return (tonumber(a.id) or 0) < (tonumber(b.id) or 0);
    end);
    accessxi.magic_known_cache = spells;
    accessxi.magic_known_cache_key = cache_key;
    accessxi.magic_known_cache_type = wanted_type;
    accessxi.magic_known_cache_tick = now;
    return spells, wanted_type;
end

function accessxi.magic_category_list_context()
    if (accessxi.magic_category_list_active ~= true) then
        return '', nil, 0;
    end

    local label = tostring(accessxi.magic_category_list_label or '');
    if (label == '') then
        return '', nil, 0;
    end

    local spells, wanted_type = accessxi.magic_known_spell_list_for_category(label);
    if (wanted_type <= 0 or spells == nil or spells:len() <= 0) then
        return label, spells or T{}, wanted_type;
    end

    return label, spells, wanted_type;
end

function accessxi.magic_category_spell_for_selected(selected)
    selected = tonumber(selected) or 0;
    local label, spells, wanted_type = accessxi.magic_category_list_context();
    if (label == '') then
        return nil, nil, '', 0;
    end
    if (selected <= 0 or spells == nil or selected > spells:len()) then
        return nil, spells or T{}, label, wanted_type;
    end
    return spells[selected], spells, label, wanted_type;
end

function accessxi.magic_known_spell_list_all()
    local now = tick();
    if (accessxi.magic_known_all_cache ~= nil
        and (now - (tonumber(accessxi.magic_known_all_cache_tick) or 0)) < 1000) then
        return accessxi.magic_known_all_cache;
    end

    local player = AshitaCore:GetMemoryManager():GetPlayer();
    local spells = T{};
    if (player == nil) then
        accessxi.magic_known_all_cache = spells;
        accessxi.magic_known_all_cache_tick = now;
        return spells;
    end

    for id = 0, 2048 do
        if (safe_call(function () return player:HasSpell(id); end, false) == true) then
            local info = accessxi.magic_spell_resource_info(id);
            if (info ~= nil) then
                spells:append(info);
            end
        end
    end

    spells:sort(function (a, b)
        return (tonumber(a.id) or 0) < (tonumber(b.id) or 0);
    end);
    accessxi.magic_known_all_cache = spells;
    accessxi.magic_known_all_cache_tick = now;
    return spells;
end

function accessxi.magic_spell_level_unlocked(player, info, job, level)
    player = player or AshitaCore:GetMemoryManager():GetPlayer();
    info = info or T{};
    job = tonumber(job) or 0;
    level = tonumber(level) or 0;
    if (job <= 0 or level <= 0 or info.levels == nil) then
        return false, -1;
    end

    local required = tonumber(info.levels[job]) or -1;
    if (required < 0) then
        return false, required;
    end
    if (required <= 99) then
        return level >= required, required;
    end

    local mask = tonumber(info.job_point_mask) or 0;
    if (bit.band(mask, bit.lshift(1, bit.band(job, 0x1F))) == 0) then
        return false, required;
    end
    local spent = tonumber(safe_call(function () return player:GetJobPointsSpent(job); end, 0)) or 0;
    return spent >= required, required;
end

function accessxi.magic_spell_currently_usable(player, info, main_job, main_level, sub_job, sub_level)
    player = player or AshitaCore:GetMemoryManager():GetPlayer();
    info = info or T{};
    local main_ok, main_req = accessxi.magic_spell_level_unlocked(player, info, main_job, main_level);
    local sub_ok, sub_req = accessxi.magic_spell_level_unlocked(player, info, sub_job, sub_level);
    return main_ok or sub_ok, main_req, sub_req;
end

function accessxi.magic_usable_spell_list_all()
    local now = tick();
    if (accessxi.magic_usable_all_cache ~= nil
        and (now - (tonumber(accessxi.magic_usable_all_cache_tick) or 0)) < 1000) then
        return accessxi.magic_usable_all_cache,
            tonumber(accessxi.magic_usable_main_job) or 0,
            tonumber(accessxi.magic_usable_main_level) or 0,
            tonumber(accessxi.magic_usable_sub_job) or 0,
            tonumber(accessxi.magic_usable_sub_level) or 0;
    end

    local player = AshitaCore:GetMemoryManager():GetPlayer();
    local spells = T{};
    local main_job = 0;
    local main_level = 0;
    local sub_job = 0;
    local sub_level = 0;
    if (player ~= nil) then
        main_job = tonumber(safe_call(function () return player:GetMainJob(); end, 0)) or 0;
        main_level = tonumber(safe_call(function () return player:GetMainJobLevel(); end, 0)) or 0;
        sub_job = tonumber(safe_call(function () return player:GetSubJob(); end, 0)) or 0;
        sub_level = tonumber(safe_call(function () return player:GetSubJobLevel(); end, 0)) or 0;

        for id = 0, 2048 do
            if (safe_call(function () return player:HasSpell(id); end, false) == true) then
                local info = accessxi.magic_spell_resource_info(id);
                local usable, main_req, sub_req = accessxi.magic_spell_currently_usable(player, info, main_job, main_level, sub_job, sub_level);
                if (usable == true and info ~= nil) then
                    info.main_req = main_req;
                    info.sub_req = sub_req;
                    spells:append(info);
                end
            end
        end
    end

    accessxi.magic_usable_all_cache = spells;
    accessxi.magic_usable_all_cache_tick = now;
    accessxi.magic_usable_main_job = main_job;
    accessxi.magic_usable_main_level = main_level;
    accessxi.magic_usable_sub_job = sub_job;
    accessxi.magic_usable_sub_level = sub_level;
    return spells, main_job, main_level, sub_job, sub_level;
end

function accessxi.magic_sorted_spell_copy(spells, mode)
    local out = T{};
    if (spells ~= nil) then
        for _, spell in ipairs(spells) do
            out:append(spell);
        end
    end

    mode = tostring(mode or 'id');
    out:sort(function (a, b)
        if (mode == 'magic-list') then
            local ar = accessxi.magic_spell_display_type_rank(a);
            local br = accessxi.magic_spell_display_type_rank(b);
            if (ar ~= br) then return ar < br; end
        end
        if (mode == 'type-auto') then
            local at = tonumber(a.type) or 0;
            local bt = tonumber(b.type) or 0;
            if (at ~= bt) then return at < bt; end
        end
        if (mode == 'index') then
            local ai = tonumber(a.index) or 0;
            local bi = tonumber(b.index) or 0;
            if (ai ~= bi) then return ai < bi; end
        elseif (mode == 'auto' or mode == 'type-auto' or mode == 'magic-list') then
            local asort = tonumber(a.sort_id) or 0;
            local bsort = tonumber(b.sort_id) or 0;
            if (asort ~= bsort) then return asort < bsort; end
        end
        return (tonumber(a.id) or 0) < (tonumber(b.id) or 0);
    end);
    return out;
end

function accessxi.magic_spell_order_window(spells, selected)
    selected = tonumber(selected) or 0;
    local parts = T{};
    if (spells ~= nil and selected > 0) then
        for idx = math.max(1, selected - 2), math.min(spells:len(), selected + 2) do
            local spell = spells[idx];
            if (spell ~= nil) then
                parts:append(('%d:%d:%s/t%d/i%d/s%d/m%d/u%d'):fmt(
                    idx,
                    tonumber(spell.id) or 0,
                    accessxi.escape_probe_log_text(spell.name or ''),
                    tonumber(spell.type) or 0,
                    tonumber(spell.index) or 0,
                    tonumber(spell.sort_id) or 0,
                    tonumber(spell.main_req) or -1,
                    tonumber(spell.sub_req) or -1));
            end
        end
    end
    return parts:concat(' | ');
end

function accessxi.magic_spell_order_at(spells, selected)
    selected = tonumber(selected) or 0;
    if (spells == nil or selected <= 0 or selected > spells:len()) then
        return ('%d:none'):fmt(selected);
    end

    local spell = spells[selected];
    if (spell == nil) then
        return ('%d:none'):fmt(selected);
    end

    return ('%d:%d:%s/t%d/i%d/s%d/m%d/u%d'):fmt(
        selected,
        tonumber(spell.id) or 0,
        accessxi.escape_probe_log_text(spell.name or ''),
        tonumber(spell.type) or 0,
        tonumber(spell.index) or 0,
        tonumber(spell.sort_id) or 0,
        tonumber(spell.main_req) or -1,
        tonumber(spell.sub_req) or -1);
end

function accessxi.magic_usable_order_probe(selected)
    selected = tonumber(selected) or 0;
    local spells, main_job, main_level, sub_job, sub_level = accessxi.magic_usable_spell_list_all();
    local id_order = accessxi.magic_sorted_spell_copy(spells, 'id');
    local sort_order = accessxi.magic_sorted_spell_copy(spells, 'auto');
    local type_order = accessxi.magic_sorted_spell_copy(spells, 'type-auto');
    local index_order = accessxi.magic_sorted_spell_copy(spells, 'index');
    return ('usableProbe main=%d/%d sub=%d/%d total=%d selected=%d idAt="%s" sortAt="%s" typeAt="%s" indexAt="%s"'):fmt(
        tonumber(main_job) or 0,
        tonumber(main_level) or 0,
        tonumber(sub_job) or 0,
        tonumber(sub_level) or 0,
        spells ~= nil and spells:len() or 0,
        selected,
        accessxi.magic_spell_order_at(id_order, selected),
        accessxi.magic_spell_order_at(sort_order, selected),
        accessxi.magic_spell_order_at(type_order, selected),
        accessxi.magic_spell_order_at(index_order, selected));
end

function accessxi.magic_known_spell_preview(spells)
    local parts = T{};
    if (spells == nil) then
        return '';
    end
    for i = 1, math.min(spells:len(), 12) do
        local spell = spells[i];
        parts:append(('%d:%s/t%d/s%d'):fmt(
            tonumber(spell.id) or 0,
            accessxi.escape_probe_log_text(spell.name or ''),
            tonumber(spell.type) or 0,
            tonumber(spell.skill) or 0));
    end
    return parts:concat(' | ');
end

function accessxi.magic_known_all_probe(selected)
    selected = tonumber(selected) or 0;
    local spells = accessxi.magic_known_spell_list_all();
    return ('allKnown=%d idAt="%s"'):fmt(
        spells ~= nil and spells:len() or 0,
        accessxi.magic_spell_order_at(spells, selected));
end

function accessxi.magic_spell_display_type_rank(spell)
    local spell_type = tonumber(spell ~= nil and spell.type or nil) or 0;
    if (spell_type == 1) then return 1; end -- White Magic
    if (spell_type == 2) then return 2; end -- Black Magic
    if (spell_type == 5) then return 3; end -- Bard Songs
    if (spell_type == 4) then return 4; end -- Ninjutsu
    if (spell_type == 7) then return 5; end -- Geomancy
    if (spell_type == 6) then return 6; end -- Blue Magic
    if (spell_type == 3) then return 7; end -- Summoning Magic
    if (spell_type == 8) then return 8; end -- Trust Magic
    return 100 + spell_type;
end

function accessxi.magic_known_type_auto_spell_for_selected(selected)
    selected = tonumber(selected) or 0;
    if (selected <= 0) then
        return nil, T{}, 'invalid';
    end

    local spells = accessxi.magic_known_spell_list_all();
    local ordered = accessxi.magic_sorted_spell_copy(spells, 'magic-list');
    if (ordered == nil or selected > ordered:len()) then
        return nil, ordered or T{}, 'range';
    end

    local spell = ordered[selected];
    if (spell == nil or tostring(spell.name or '') == '') then
        return nil, ordered, 'empty';
    end
    if (accessxi.magic_known_flag_for_id(spell.id) ~= true) then
        return nil, ordered, 'not-known';
    end

    return spell, ordered, '';
end

function accessxi.magic_known_type_auto_order_probe(selected)
    selected = tonumber(selected) or 0;
    local spell, ordered, reason = accessxi.magic_known_type_auto_spell_for_selected(selected);
    return ('knownMagicList total=%d selected=%d reason="%s" at="%s" window="%s"'):fmt(
        ordered ~= nil and ordered:len() or 0,
        selected,
        accessxi.escape_probe_log_text(reason or ''),
        spell ~= nil and accessxi.magic_spell_order_at(ordered, selected) or '',
        accessxi.magic_spell_order_window(ordered, selected));
end

function accessxi.magic_effective_selected(raw_selected, total, page, raw, entry)
    raw_selected = tonumber(raw_selected) or 0;
    total = tonumber(total) or 0;
    page = tonumber(page) or 0;
    raw = tonumber(raw) or 0;
    entry = tonumber(entry) or 0;
    if (raw_selected <= 0) then
        return raw_selected, 0;
    end

    local now = tick();
    local last_tick = tonumber(accessxi.magic_selected_unwrap_tick) or 0;
    if ((now - last_tick) > 10000) then
        accessxi.magic_selected_unwrap_base = 0;
        accessxi.magic_selected_unwrap_last_raw = 0;
        accessxi.magic_selected_unwrap_last_effective = 0;
    end

    local base = tonumber(accessxi.magic_selected_unwrap_base) or 0;
    local last_raw = tonumber(accessxi.magic_selected_unwrap_last_raw) or 0;
    local last_effective = tonumber(accessxi.magic_selected_unwrap_last_effective) or 0;
    local last_entry = tonumber(accessxi.magic_selected_unwrap_last_entry) or 0;
    local nav_dir = 0;
    local raw_low = bit.band(raw, 0xFFFF);
    local changed_sample = (raw_selected ~= last_raw or entry ~= last_entry);
    local effective = raw_selected;

    if (entry ~= last_entry and last_entry ~= 0 and base > 0) then
        base = 0;
        effective = raw_selected;
    end

    if (changed_sample and last_raw > 0) then
        local delta = raw_selected - last_raw;
        if (delta > 128) then
            nav_dir = -1;
        elseif (delta < -128) then
            nav_dir = 1;
        elseif (delta > 0) then
            nav_dir = 1;
        elseif (delta < 0) then
            nav_dir = -1;
        end
    end

    if (base > 0 and last_effective >= 240 and raw_low < 0x100 and raw_selected <= 20) then
        base = 0;
        effective = raw_selected;
    elseif (raw_low >= 0x100 and (total <= 0 or raw_low <= total)) then
        effective = raw_low;
        base = effective - raw_selected;
        if (base < 0) then
            base = 0;
        end
    elseif (base > 0 and nav_dir ~= 0 and changed_sample and last_effective >= 240 and raw_selected <= 20 and last_raw <= 20) then
        effective = last_effective + nav_dir;
        if (effective < 1) then
            effective = 1;
        elseif (total > 0 and effective > total) then
            effective = total;
        end
        base = effective - raw_selected;
        if (base < 0) then
            base = 0;
        end
    elseif (base > 0 and nav_dir ~= 0 and changed_sample and last_effective >= 240 and raw_selected >= 240 and raw_selected <= (last_effective + 1)) then
        effective = last_effective + nav_dir;
        if (effective < 1) then
            effective = 1;
        elseif (total > 0 and effective > total) then
            effective = total;
        end
        base = effective - raw_selected;
        if (base < 0) then
            base = 0;
        end
    elseif (raw_selected >= 240) then
        base = 0;
        effective = raw_selected;
    elseif (last_raw >= 240 and raw_selected <= 20 and last_effective >= 240 and (total <= 0 or last_effective < (total - 20))) then
        base = last_effective + 1 - raw_selected;
        if (base < 0) then
            base = 0;
        end
        effective = raw_selected + base;
    elseif (base > 0 and raw_selected <= 80) then
        effective = raw_selected + base;
        if (total > 0 and effective > total) then
            base = 0;
            effective = raw_selected;
        end
    end

    accessxi.magic_selected_unwrap_base = base;
    accessxi.magic_selected_unwrap_last_raw = raw_selected;
    accessxi.magic_selected_unwrap_last_effective = effective;
    accessxi.magic_selected_unwrap_last_entry = entry;
    accessxi.magic_selected_unwrap_last_page = page;
    accessxi.magic_selected_unwrap_last_raw_dword = raw;
    accessxi.magic_selected_unwrap_tick = now;
    return effective, base;
end

function accessxi.magic_mix_order_paths()
    local paths = {};
    local seen = {};
    local function add(path)
        path = tostring(path or '');
        if (path == '') then
            return;
        end
        local key = path:lower();
        if (seen[key] == true) then
            return;
        end
        seen[key] = true;
        if (accessxi_paths.file_exists(path)) then
            paths[#paths + 1] = path;
        end
    end

    local profile_dir = safe_call(function ()
        local dir = accessxi.macro_active_profile();
        return tostring(dir or '');
    end, '');
    profile_dir = tostring(profile_dir or ''):gsub('[\\/]+$', '');
    if (profile_dir ~= '') then
        add(profile_dir .. '\\mix.dat');
    end

    return paths;
end

function accessxi.magic_mix_u16le(data, offset)
    offset = tonumber(offset) or 0;
    local index = offset + 1;
    local a, b = string.byte(data or '', index, index + 1);
    if (a == nil or b == nil) then
        return nil;
    end
    return a + (b * 256);
end

function accessxi.magic_mix_read_file(path)
    local ok, data = pcall(function ()
        local f = io.open(path, 'rb');
        if (f == nil) then
            return nil;
        end
        local value = f:read('*all');
        f:close();
        return value;
    end);
    if (not ok) then
        return nil;
    end
    return data;
end

function accessxi.magic_mix_parse_order(data, start_offset)
    local ids = T{};
    local seen = {};
    local duplicate = 0;
    local raw = 0;
    local zero_run = 0;
    start_offset = tonumber(start_offset) or 0x98;
    data = data or '';

    for off = start_offset, #data - 2, 2 do
        local id = accessxi.magic_mix_u16le(data, off);
        if (id == nil) then
            break;
        end

        if (id == 0) then
            zero_run = zero_run + 1;
            if (ids:len() > 0 and zero_run >= 8) then
                break;
            end
        else
            zero_run = 0;
            raw = raw + 1;
            local info = accessxi.magic_spell_resource_info(id);
            if (info ~= nil and tostring(info.name or '') ~= '') then
                if (seen[id] == true) then
                    duplicate = duplicate + 1;
                end
                seen[id] = true;
                ids:append(id);
            end
        end
    end

    return ids, raw, duplicate;
end

function accessxi.magic_mix_read_order()
    local now = tick();
    local cache = accessxi.magic_mix_order_cache;
    if (cache ~= nil and (now - (tonumber(cache.tick) or 0)) < 5000) then
        return cache;
    end

    local result = T{
        tick = now,
        path = '',
        offset = 0x98,
        bytes = 0,
        ids = T{},
        raw = 0,
        duplicate = 0,
        error = 'unread',
    };

    for _, path in ipairs(accessxi.magic_mix_order_paths()) do
        local data = accessxi.magic_mix_read_file(path);
        if (data ~= nil and #data >= 0xA0) then
            local ids, raw, duplicate = accessxi.magic_mix_parse_order(data, 0x98);
            if (ids ~= nil and ids:len() > 0) then
                result.path = path;
                result.bytes = #data;
                result.ids = ids;
                result.raw = raw;
                result.duplicate = duplicate;
                result.error = '';
                break;
            end
        end
    end

    accessxi.magic_mix_order_cache = result;
    return result;
end

function accessxi.magic_trust_name_key(name)
    name = accessxi.plain_native_menu_label(clean_probe_text(name or ''));
    return tostring(name or ''):lower():gsub('[^a-z0-9]', '');
end

function accessxi.magic_active_trust_name_keys()
    local now = tick();
    local cache = accessxi.magic_active_trust_cache;
    if (cache ~= nil and (now - (tonumber(cache.tick) or 0)) < 750) then
        return cache.keys or {};
    end

    local keys = {};
    local mm = safe_call(function () return AshitaCore:GetMemoryManager(); end, nil);
    local party = mm ~= nil and safe_call(function () return mm:GetParty(); end, nil) or nil;
    if (party ~= nil) then
        for i = 1, 17 do
            local active = tonumber(safe_call(function () return party:GetMemberIsActive(i); end, 0)) or 0;
            local name = clean_probe_text(safe_call(function () return party:GetMemberName(i); end, ''));
            local key = accessxi.magic_trust_name_key(name);
            if (active ~= 0 and key ~= '') then
                keys[key] = true;
            end
        end
    end

    accessxi.magic_active_trust_cache = T{ tick = now, keys = keys };
    return keys;
end

function accessxi.magic_spell_is_active_trust(info, active_keys)
    if (info == nil or tonumber(info.type) ~= 8 or active_keys == nil) then
        return false;
    end

    local key = accessxi.magic_trust_name_key(info.name or '');
    return key ~= '' and active_keys[key] == true;
end

function accessxi.magic_append_known_spells_missing_from_mix(spells, seen, player, label, allow_trust_magic)
    spells = spells or T{};
    seen = seen or {};
    if (player == nil) then
        return spells;
    end

    label = tostring(label or '');
    local known_spells = nil;
    local wanted_type = 0;
    if (label ~= '') then
        known_spells, wanted_type = accessxi.magic_known_spell_list_for_category(label);
    else
        known_spells = accessxi.magic_known_spell_list_all();
    end

    for _, info in ipairs(known_spells or T{}) do
        local id = tonumber(info ~= nil and info.id or nil) or 0;
        local info_type = tonumber(info ~= nil and info.type or nil) or 0;
        if (id > 0
            and seen[id] ~= true
            and (wanted_type <= 0 or info_type == wanted_type)
            and not (allow_trust_magic ~= true and info_type == 8)
            and safe_call(function () return player:HasSpell(id); end, false) == true) then
            seen[id] = true;
            spells:append(info);
        end
    end

    return spells;
end

function accessxi.magic_mix_category_spell_list(label)
    label = tostring(label or '');
    local wanted_type = accessxi.magic_category_type(label);
    local order = accessxi.magic_mix_read_order();
    local spells = T{};
    if (wanted_type <= 0) then
        return spells, wanted_type, order, 'type';
    end
    if (order == nil or order.ids == nil or order.ids:len() == 0) then
        return spells, wanted_type, order, 'order';
    end

    local cache_key = ('%s:%d:%s:%d:%d:%d'):fmt(
        label:lower(),
        wanted_type,
        tostring(order.path or ''),
        tonumber(order.bytes) or 0,
        tonumber(order.raw) or 0,
        tonumber(order.duplicate) or 0);
    local now = tick();
    if (wanted_type ~= 8
        and accessxi.magic_mix_category_cache ~= nil
        and tostring(accessxi.magic_mix_category_cache_key or '') == cache_key
        and tonumber(accessxi.magic_mix_category_cache_type) == wanted_type
        and (now - (tonumber(accessxi.magic_mix_category_cache_tick) or 0)) < 1000) then
        spells = accessxi.magic_mix_category_cache;
        return spells, wanted_type, order, '';
    end

    local memory = AshitaCore:GetMemoryManager();
    local player = memory ~= nil and memory:GetPlayer() or nil;
    if (player == nil) then
        return spells, wanted_type, order, 'player';
    end

    local seen = {};
    for _, value in ipairs(order.ids) do
        local id = tonumber(value) or 0;
        if (id > 0 and seen[id] ~= true) then
            seen[id] = true;
            local info = accessxi.magic_spell_resource_info(id);
            if (info ~= nil
                and tonumber(info.type) == wanted_type
                and safe_call(function () return player:HasSpell(id); end, false) == true) then
                spells:append(info);
            end
        end
    end

    if (wanted_type ~= 6) then
        accessxi.magic_append_known_spells_missing_from_mix(spells, seen, player, label, wanted_type == 8);
    end

    if (wanted_type ~= 8) then
        accessxi.magic_mix_category_cache = spells;
        accessxi.magic_mix_category_cache_key = cache_key;
        accessxi.magic_mix_category_cache_type = wanted_type;
        accessxi.magic_mix_category_cache_tick = now;
    end
    return spells, wanted_type, order, '';
end

function accessxi.blue_magic_mix_spell_list()
    local order = accessxi.magic_mix_read_order();
    local spells = T{};
    if (order == nil or tostring(order.path or '') == '') then
        return spells, order, 'order';
    end

    local cache_key = ('%s:%d:%d:%d'):fmt(
        tostring(order.path or ''),
        tonumber(order.bytes) or 0,
        tonumber(order.raw) or 0,
        tonumber(order.duplicate) or 0);
    local now = tick();
    if (accessxi.blue_magic_mix_cache ~= nil
        and tostring(accessxi.blue_magic_mix_cache_key or '') == cache_key
        and (now - (tonumber(accessxi.blue_magic_mix_cache_tick) or 0)) < 1000) then
        return accessxi.blue_magic_mix_cache, order, tostring(accessxi.blue_magic_mix_cache_reason or '');
    end

    local memory = AshitaCore:GetMemoryManager();
    local player = memory ~= nil and memory:GetPlayer() or nil;
    if (player == nil) then
        return spells, order, 'player';
    end

    local data = accessxi.magic_mix_read_file(tostring(order.path or ''));
    if (data == nil or #data < 0xA0) then
        return spells, order, 'file';
    end

    local seen = {};
    local mix_index = 0;
    local start_offset = tonumber(order.offset) or 0x98;
    for off = start_offset, #data - 2, 2 do
        local raw_id = accessxi.magic_mix_u16le(data, off);
        if (raw_id == nil) then
            break;
        end

        mix_index = mix_index + 1;
        if (raw_id ~= 0) then
            local id = raw_id + 512;
            if (id > 0 and id <= 2048 and seen[id] ~= true) then
                local info = accessxi.magic_spell_resource_info(id);
                if (info ~= nil
                    and tonumber(info.type) == 6
                    and safe_call(function () return player:HasSpell(id); end, false) == true) then
                    seen[id] = true;
                    info.raw_id = raw_id;
                    info.mix_index = mix_index;
                    info.mix_offset = off;
                    spells:append(info);
                end
            end
        end
    end

    accessxi.blue_magic_mix_cache = spells;
    accessxi.blue_magic_mix_cache_key = cache_key;
    accessxi.blue_magic_mix_cache_tick = now;
    accessxi.blue_magic_mix_cache_reason = '';
    return spells, order, '';
end

function accessxi.magic_mix_category_spell_for_selected(label, selected)
    label = tostring(label or '');
    selected = tonumber(selected) or 0;
    local spells, wanted_type, order, reason = accessxi.magic_mix_category_spell_list(label);
    if (selected <= 0) then
        return nil, spells, wanted_type, order, 'selected';
    end
    if (tostring(reason or '') ~= '') then
        return nil, spells, wanted_type, order, reason;
    end
    if (selected > spells:len()) then
        return nil, spells, wanted_type, order, 'range';
    end
    return spells[selected], spells, wanted_type, order, '';
end

function accessxi.magic_mix_format_at(ids, index)
    index = tonumber(index) or 0;
    if (ids == nil or index <= 0 or index > ids:len()) then
        return ('%d:none'):fmt(index);
    end

    local id = tonumber(ids[index]) or 0;
    local info = accessxi.magic_spell_resource_info(id);
    if (info == nil) then
        return ('%d:%d:unknown'):fmt(index, id);
    end

    local known = false;
    if (accessxi.magic_known_flag_for_id ~= nil) then
        known = accessxi.magic_known_flag_for_id(id);
    end

    return ('%d:%d:%s/k%d/t%d/s%d'):fmt(
        index,
        id,
        accessxi.escape_probe_log_text(info.name or ''),
        known and 1 or 0,
        tonumber(info.type) or 0,
        tonumber(info.skill) or 0);
end

function accessxi.magic_mix_order_window(ids, selected)
    local parts = T{};
    selected = tonumber(selected) or 0;
    if (ids == nil or ids:len() == 0 or selected <= 0) then
        return '';
    end

    local first = math.max(1, selected - 3);
    local last = math.min(ids:len(), selected + 5);
    for index = first, last do
        parts:append(accessxi.magic_mix_format_at(ids, index));
    end
    return parts:concat(' | ');
end

function accessxi.magic_mix_order_probe(selected)
    selected = tonumber(selected) or 0;
    local order = accessxi.magic_mix_read_order();
    if (order == nil or order.ids == nil or order.ids:len() == 0) then
        return 'mixProbe error=unread';
    end

    local path = tostring(order.path or '');
    local short_path = path:match('FINAL FANTASY XI\\(.+)$') or path;
    return ('mixProbe path="%s" off=0x%X bytes=%d total=%d raw=%d dup=%d selected=%d idAt="%s" window="%s"'):fmt(
        accessxi.escape_probe_log_text(short_path),
        tonumber(order.offset) or 0,
        tonumber(order.bytes) or 0,
        order.ids:len(),
        tonumber(order.raw) or 0,
        tonumber(order.duplicate) or 0,
        selected,
        accessxi.magic_mix_format_at(order.ids, selected),
        accessxi.escape_probe_log_text(accessxi.magic_mix_order_window(order.ids, selected)));
end

function accessxi.magic_mix_direct_spell_list(allow_trust_magic)
    local order = accessxi.magic_mix_read_order();
    local spells = T{};
    if (order == nil or order.ids == nil or order.ids:len() == 0) then
        return spells, order, 'order';
    end

    local memory = AshitaCore:GetMemoryManager();
    local player = memory ~= nil and memory:GetPlayer() or nil;
    if (player == nil) then
        return spells, order, 'player';
    end

    local seen = {};
    for _, value in ipairs(order.ids) do
        local id = tonumber(value) or 0;
        if (id > 0 and seen[id] ~= true) then
            seen[id] = true;
            local info = accessxi.magic_spell_resource_info(id);
            if (info ~= nil
                and (allow_trust_magic == true or tonumber(info.type) ~= 8)
                and safe_call(function () return player:HasSpell(id); end, false) == true) then
                spells:append(info);
            end
        end
    end

    accessxi.magic_append_known_spells_missing_from_mix(spells, seen, player, nil, allow_trust_magic);

    return spells, order, '';
end

function accessxi.magic_mix_spell_for_selected(selected, allow_trust_magic)
    selected = tonumber(selected) or 0;
    if (selected <= 0) then
        return nil, 0, nil, 'selected';
    end

    local spells, order, reason = accessxi.magic_mix_direct_spell_list(allow_trust_magic);
    if (tostring(reason or '') ~= '') then
        return nil, 0, order, reason;
    end
    if (selected > spells:len()) then
        return nil, 0, order, 'range';
    end

    local info = spells[selected];
    local id = tonumber(info ~= nil and info.id or nil) or 0;
    if (info == nil or id <= 0 or tostring(info.name or '') == '') then
        return nil, id, order, 'resource';
    end
    if (allow_trust_magic ~= true and tonumber(info.type) == 8) then
        return nil, id, order, 'type';
    end

    return info, id, order, '';
end

function accessxi.magic_menu_index_probe(obj, child)
    obj = tonumber(obj) or 0;
    child = tonumber(child) or 0;
    local parts = T{};
    parts:append(('native=24:%d,28:%d,30:%d,34:%d,4C:%d,50:%d,58:%d,64:%d'):fmt(
        tonumber(read_current_native_menu_index(0x24)) or 0,
        tonumber(read_current_native_menu_index(0x28)) or 0,
        tonumber(read_current_native_menu_index(0x30)) or 0,
        tonumber(read_current_native_menu_index(0x34)) or 0,
        tonumber(read_current_native_menu_index(0x4C)) or 0,
        tonumber(read_current_native_menu_index(0x50)) or 0,
        tonumber(read_current_native_menu_index(0x58)) or 0,
        tonumber(read_current_native_menu_index(0x64)) or 0));

    if (accessxi.is_probe_pointer(obj)) then
        parts:append(('obj=24:%d,28:%d,30:%d,34:%d,4C:%d,50:%d,58:%d,64:%d'):fmt(
            tonumber(read_i32(obj + 0x24)) or 0,
            tonumber(read_i32(obj + 0x28)) or 0,
            tonumber(read_i32(obj + 0x30)) or 0,
            tonumber(read_i32(obj + 0x34)) or 0,
            tonumber(read_i32(obj + 0x4C)) or 0,
            tonumber(read_i32(obj + 0x50)) or 0,
            tonumber(read_i32(obj + 0x58)) or 0,
            tonumber(read_i32(obj + 0x64)) or 0));
    end

    if (accessxi.is_probe_pointer(child)) then
        parts:append(('child=20:0x%08X,24:%d,28:%d,30:%d,34:%d,4C:%d,50:%d,58:%d,64:%d'):fmt(
            tonumber(read_u32(child + 0x20)) or 0,
            tonumber(read_i32(child + 0x24)) or 0,
            tonumber(read_i32(child + 0x28)) or 0,
            tonumber(read_i32(child + 0x30)) or 0,
            tonumber(read_i32(child + 0x34)) or 0,
            tonumber(read_i32(child + 0x4C)) or 0,
            tonumber(read_i32(child + 0x50)) or 0,
            tonumber(read_i32(child + 0x58)) or 0,
            tonumber(read_i32(child + 0x64)) or 0));
    end

    return parts:concat(' ');
end

function accessxi.magic_shortcut_resolve()
    local ptr = tonumber(accessxi.magic_shortcut_patchsite) or 0;
    if (accessxi.is_probe_pointer(ptr)) then
        return ptr, tonumber(accessxi.magic_shortcut_call_target) or 0;
    end

    -- Same Ctrl+M shortcut spell-list site used by the local trimspells addon.
    ptr = tonumber(ashita.memory.find(0, 0, '68000100006A??6A00E8????????83C40CB801000000C3', 0, 0)) or 0;
    if (not accessxi.is_probe_pointer(ptr)) then
        return 0, 0;
    end

    accessxi.magic_shortcut_patchsite = ptr;
    local call_addr = ptr + 0x09;
    local rel = read_i32(call_addr + 0x01);
    if (rel ~= nil) then
        accessxi.magic_shortcut_call_target = call_addr + 0x05 + rel;
    else
        accessxi.magic_shortcut_call_target = 0;
    end

    return accessxi.magic_shortcut_patchsite, accessxi.magic_shortcut_call_target;
end

function accessxi.magic_shortcut_native_probe(selected, count)
    local patchsite, call_target = accessxi.magic_shortcut_resolve();
    if (not accessxi.is_probe_pointer(patchsite)) then
        return 'shortcutPatch=missing';
    end

    local trim_flag = read_u8(patchsite + 0x06) or -1;
    return ('shortcutPatch=0x%08X flag=%d call=0x%08X'):fmt(
        patchsite,
        trim_flag,
        tonumber(call_target) or 0);
end

function accessxi.magic_shortcut_spell_candidates(label, ptr, require_known, limit)
    local groups = accessxi.collect_magic_spell_candidate_details_for_ptr(label, ptr, require_known, limit or 18);
    if (groups == nil or groups:len() == 0) then
        return '';
    end
    return accessxi.format_magic_spell_candidates(groups);
end

function accessxi.magic_shortcut_target_details()
    local _, call_target = accessxi.magic_shortcut_resolve();
    call_target = tonumber(call_target) or 0;
    if (not accessxi.is_probe_pointer(call_target)) then
        return 'builder=missing';
    end

    local global_addr = 0;
    local global_value = 0;
    if ((read_u8(call_target) or 0) == 0xA1) then
        global_addr = read_u32(call_target + 0x01) or 0;
        if (accessxi.is_probe_pointer(global_addr)) then
            global_value = read_u32(global_addr) or 0;
        end
    end

    local static_arg = 0;
    if ((read_u8(call_target + 0x0D) or 0) == 0x68) then
        static_arg = read_u32(call_target + 0x0E) or 0;
    end

    local ecx_arg = 0;
    if ((read_u8(call_target + 0x12) or 0) == 0xB9) then
        ecx_arg = read_u32(call_target + 0x13) or 0;
    end

    local inner_call = 0;
    if ((read_u8(call_target + 0x17) or 0) == 0xE8) then
        local rel = read_i32(call_target + 0x18);
        if (rel ~= nil) then
            inner_call = call_target + 0x1C + rel;
        end
    end

    return ('builder=0x%08X inner=0x%08X globalAddr=0x%08X globalValue=0x%08X static=0x%08X ecx=0x%08X globalD="%s" globalValueD="%s" staticD="%s" ecxD="%s"'):fmt(
        call_target,
        tonumber(inner_call) or 0,
        global_addr,
        global_value,
        static_arg,
        ecx_arg,
        accessxi.escape_probe_log_text(accessxi.format_probe_dwords(global_addr, 0, 4)),
        accessxi.escape_probe_log_text(accessxi.format_probe_dwords(global_value, 0, 8)),
        accessxi.escape_probe_log_text(accessxi.format_probe_dwords(static_arg, 0, 8)),
        accessxi.escape_probe_log_text(accessxi.format_probe_dwords(ecx_arg, 0, 8)));
end

function accessxi.log_magic_shortcut_target_probe()
    if (not accessxi.debug_probe_logging_active()) then
        return;
    end

    if (accessxi.magic_shortcut_target_probe_logged == true) then
        return;
    end

    local _, call_target = accessxi.magic_shortcut_resolve();
    call_target = tonumber(call_target) or 0;
    if (not accessxi.is_probe_pointer(call_target)) then
        return;
    end

    local global_addr = 0;
    local global_value = 0;
    if ((read_u8(call_target) or 0) == 0xA1) then
        global_addr = read_u32(call_target + 0x01) or 0;
        if (accessxi.is_probe_pointer(global_addr)) then
            global_value = read_u32(global_addr) or 0;
        end
    end

    local static_arg = 0;
    if ((read_u8(call_target + 0x0D) or 0) == 0x68) then
        static_arg = read_u32(call_target + 0x0E) or 0;
    end

    local ecx_arg = 0;
    if ((read_u8(call_target + 0x12) or 0) == 0xB9) then
        ecx_arg = read_u32(call_target + 0x13) or 0;
    end

    local inner_call = 0;
    if ((read_u8(call_target + 0x17) or 0) == 0xE8) then
        local rel = read_i32(call_target + 0x18);
        if (rel ~= nil) then
            inner_call = call_target + 0x1C + rel;
        end
    end

    local menu_global_addr = 0;
    local menu_global_value = 0;
    if ((read_u8(call_target + 0x2A) or 0) == 0x8B and (read_u8(call_target + 0x2B) or 0) == 0x0D) then
        menu_global_addr = read_u32(call_target + 0x2C) or 0;
        if (accessxi.is_probe_pointer(menu_global_addr)) then
            menu_global_value = read_u32(menu_global_addr) or 0;
        end
    end

    local resource_global_addr = 0;
    local resource_global_value = 0;
    if ((read_u8(call_target + 0x11E) or 0) == 0x8B and (read_u8(call_target + 0x11F) or 0) == 0x3D) then
        resource_global_addr = read_u32(call_target + 0x120) or 0;
        if (accessxi.is_probe_pointer(resource_global_addr)) then
            resource_global_value = read_u32(resource_global_addr) or 0;
        end
    end

    accessxi.magic_shortcut_target_probe_logged = true;
    log_line(('magicshortcuttarget builder=0x%08X inner=0x%08X globalAddr=0x%08X globalValue=0x%08X static=0x%08X ecx=0x%08X menuGlobalAddr=0x%08X menuGlobalValue=0x%08X resourceGlobalAddr=0x%08X resourceGlobalValue=0x%08X'):fmt(
        call_target,
        tonumber(inner_call) or 0,
        global_addr,
        global_value,
        static_arg,
        ecx_arg,
        menu_global_addr,
        menu_global_value,
        resource_global_addr,
        resource_global_value));

    local targets = T{
        T{ label = 'static', ptr = static_arg, length = 0x100 },
        T{ label = 'ecx', ptr = ecx_arg, length = 0x100 },
        T{ label = 'globalValue', ptr = global_value, length = 0x80 },
        T{ label = 'menuGlobalValue', ptr = menu_global_value, length = 0x80 },
        T{ label = 'resourceGlobalValue', ptr = resource_global_value, length = 0x80 },
    };
    for _, target in ipairs(targets) do
        local ptr = tonumber(target.ptr) or 0;
        if (accessxi.is_probe_pointer(ptr)) then
            for off = 0, (tonumber(target.length) or 0) - 1, 0x10 do
                log_line(('magicshortcuttargethex target=%s base=0x%08X off=0x%03X hex=%s'):fmt(
                    tostring(target.label or ''),
                    ptr,
                    off,
                    accessxi.format_probe_hex_bytes(ptr, off, 0x10)));
            end
        end
    end
end

function accessxi.magic_model_probe_candidates(label, ptr, span)
    ptr = tonumber(ptr) or 0;
    span = tonumber(span) or 0;
    if (not accessxi.is_probe_pointer(ptr)) then
        return '';
    end

    local parts = T{};
    local seen = {};
    for off = 0, span - 2, 2 do
        local id = read_u16(ptr + off) or 0;
        if (id > 0 and id <= 2048 and seen[('u16:%d'):fmt(id)] ~= true) then
            local info = accessxi.magic_spell_resource_info(id);
            if (info ~= nil and tostring(info.name or '') ~= '') then
                seen[('u16:%d'):fmt(id)] = true;
                parts:append(('%s+%03X:u16=%d:%s'):fmt(
                    tostring(label or ''),
                    off,
                    id,
                    accessxi.escape_probe_log_text(info.name or '')));
            end
        end
    end
    for off = 0, span - 4, 4 do
        local id = read_u32(ptr + off) or 0;
        if (id > 0 and id <= 2048 and seen[('u32:%d'):fmt(id)] ~= true) then
            local info = accessxi.magic_spell_resource_info(id);
            if (info ~= nil and tostring(info.name or '') ~= '') then
                seen[('u32:%d'):fmt(id)] = true;
                parts:append(('%s+%03X:u32=%d:%s'):fmt(
                    tostring(label or ''),
                    off,
                    id,
                    accessxi.escape_probe_log_text(info.name or '')));
            end
        end
    end

    return parts:concat(' | ');
end

function accessxi.log_magic_model_pointer(label, ptr, selected, span)
    ptr = tonumber(ptr) or 0;
    span = tonumber(span) or 0;
    if (not accessxi.is_probe_pointer(ptr)) then
        return;
    end

    log_line(('magicmodel ptr label=%s selected=%d base=0x%08X candidates="%s"'):fmt(
        tostring(label or ''),
        tonumber(selected) or 0,
        ptr,
        accessxi.magic_model_probe_candidates(label, ptr, math.min(span, 0x100))));
    for off = 0, span - 1, 0x20 do
        log_line(('magicmodelhex label=%s selected=%d base=0x%08X off=0x%03X hex=%s'):fmt(
            tostring(label or ''),
            tonumber(selected) or 0,
            ptr,
            off,
            accessxi.format_probe_hex_bytes(ptr, off, math.min(0x20, span - off))));
    end
end

function accessxi.log_magic_model_probe(obj, child, entry, selected, count, desc, row0, row1)
    selected = tonumber(selected) or 0;
    if (selected <= 0) then
        return;
    end
    if (accessxi.magic_model_probe_seen == nil) then
        accessxi.magic_model_probe_seen = {};
        accessxi.magic_model_probe_count = 0;
    end
    if ((tonumber(accessxi.magic_model_probe_count) or 0) >= 6) then
        return;
    end

    obj = tonumber(obj) or 0;
    child = tonumber(child) or 0;
    entry = tonumber(entry) or 0;
    desc = tonumber(desc) or 0;
    row0 = tonumber(row0) or 0;
    row1 = tonumber(row1) or 0;
    local child20 = accessxi.is_probe_pointer(child) and (read_u32(child + 0x20) or 0) or 0;
    local key = ('%d:0x%08X:0x%08X:0x%08X:0x%08X'):fmt(selected, obj, child, child20, entry);
    if (accessxi.magic_model_probe_seen[key] == true) then
        return;
    end
    accessxi.magic_model_probe_seen[key] = true;
    accessxi.magic_model_probe_count = (tonumber(accessxi.magic_model_probe_count) or 0) + 1;

    log_line(('magicmodel begin selected=%d count=%d obj=0x%08X child=0x%08X child20=0x%08X entry=0x%08X desc=0x%08X row0=0x%08X row1=0x%08X childFields="%s" objFields="%s"'):fmt(
        selected,
        tonumber(count) or 0,
        obj,
        child,
        child20,
        entry,
        desc,
        row0,
        row1,
        accessxi.magic_probe_offsets('child', child, T{ 0x00, 0x08, 0x14, 0x20, 0x30, 0x34, 0x38, 0x48 }),
        accessxi.magic_probe_offsets('obj', obj, T{ 0x08, 0x0C, 0x10, 0x14, 0x20, 0x24, 0x28, 0x34, 0x38, 0x40, 0x58 })));
    accessxi.log_magic_model_pointer('obj', obj, selected, 0xC0);
    accessxi.log_magic_model_pointer('child', child, selected, 0xC0);
    accessxi.log_magic_model_pointer('child20', child20, selected, 0x160);
    accessxi.log_magic_model_pointer('entry', entry, selected, 0x80);
    accessxi.log_magic_model_pointer('desc', desc, selected, 0x60);
    accessxi.log_magic_model_pointer('row0', row0, selected, 0x60);
    accessxi.log_magic_model_pointer('row1', row1, selected, 0x60);
end

function accessxi.magic_shortcut_code_probe()
    if (accessxi.magic_shortcut_code_probe_logged == true) then
        return;
    end

    local _, call_target = accessxi.magic_shortcut_resolve();
    call_target = tonumber(call_target) or 0;
    if (not accessxi.is_probe_pointer(call_target)) then
        return;
    end

    local inner_call = 0;
    if ((read_u8(call_target + 0x17) or 0) == 0xE8) then
        local rel = read_i32(call_target + 0x18);
        if (rel ~= nil) then
            inner_call = call_target + 0x1C + rel;
        end
    end

    accessxi.magic_shortcut_code_probe_logged = true;
    log_line(('magiccodehex begin builder=0x%08X inner=0x%08X'):fmt(
        call_target,
        tonumber(inner_call) or 0));

    for off = 0, 0x17F, 0x10 do
        log_line(('magiccodehex target=builder base=0x%08X off=0x%03X hex=%s'):fmt(
            call_target,
            off,
            accessxi.format_probe_hex_bytes(call_target, off, 0x10)));
    end
    if (accessxi.is_probe_pointer(inner_call)) then
        for off = 0, 0x21F, 0x10 do
            log_line(('magiccodehex target=inner base=0x%08X off=0x%03X hex=%s'):fmt(
                inner_call,
                off,
                accessxi.format_probe_hex_bytes(inner_call, off, 0x10)));
        end
    end
end

function accessxi.magic_usable_spell_id_set(spells)
    local set = {};
    if (spells ~= nil) then
        for _, spell in ipairs(spells) do
            local id = tonumber(spell.id) or 0;
            if (id > 0) then
                set[id] = true;
            end
        end
    end
    return set;
end

function accessxi.magic_shortcut_probe_targets(obj, child, entry)
    local targets = T{};
    local seen = {};
    local function add(label, ptr)
        ptr = tonumber(ptr) or 0;
        if (accessxi.is_probe_pointer(ptr) and seen[ptr] ~= true and targets:len() < 22) then
            seen[ptr] = true;
            targets:append(T{ label = tostring(label or ''), ptr = ptr });
        end
    end

    local _, call_target = accessxi.magic_shortcut_resolve();
    call_target = tonumber(call_target) or 0;
    add('builder', call_target);

    local global_addr = 0;
    local global_value = 0;
    if (accessxi.is_probe_pointer(call_target) and (read_u8(call_target) or 0) == 0xA1) then
        global_addr = read_u32(call_target + 0x01) or 0;
        global_value = accessxi.is_probe_pointer(global_addr) and (read_u32(global_addr) or 0) or 0;
        add('globalAddr', global_addr);
        add('globalValue', global_value);
    end

    if (accessxi.is_probe_pointer(call_target) and (read_u8(call_target + 0x0D) or 0) == 0x68) then
        add('static', read_u32(call_target + 0x0E) or 0);
    end
    if (accessxi.is_probe_pointer(call_target) and (read_u8(call_target + 0x12) or 0) == 0xB9) then
        add('ecx', read_u32(call_target + 0x13) or 0);
    end

    add('obj', obj);
    add('child', child);
    add('child20', accessxi.is_probe_pointer(child) and (read_u32(child + 0x20) or 0) or 0);
    add('entry', entry);

    local function add_pointer_fields(prefix, base, offsets)
        base = tonumber(base) or 0;
        if (not accessxi.is_probe_pointer(base)) then
            return;
        end
        for _, off in ipairs(offsets) do
            add(('%s+%02X'):fmt(prefix, off), read_u32(base + off) or 0);
        end
    end

    add_pointer_fields('globalValue', global_value, T{ 0x00, 0x04, 0x10, 0x14, 0x18, 0x1C, 0x20, 0x24, 0x28 });
    add_pointer_fields('ecx', read_u32(call_target + 0x13) or 0, T{ 0x00, 0x04, 0x08, 0x0C, 0x1C, 0x20, 0x24 });
    add_pointer_fields('obj', obj, T{ 0x08, 0x0C, 0x10, 0x14, 0x20, 0x34, 0x38, 0x40, 0x58 });
    add_pointer_fields('child', child, T{ 0x00, 0x08, 0x14, 0x20 });
    return targets;
end

function accessxi.magic_backing_read_id(base, offset, width)
    base = tonumber(base) or 0;
    offset = tonumber(offset) or 0;
    width = tonumber(width) or 2;
    if (not accessxi.is_probe_pointer(base)) then
        return 0;
    end
    if (width == 4) then
        local raw = read_u32(base + offset) or 0;
        if (raw > 0 and raw <= 2048) then
            return raw;
        end
        return 0;
    end
    return read_u16(base + offset) or 0;
end

function accessxi.magic_format_backing_window(hit, selected)
    if (hit == nil or hit.ids == nil) then
        return '';
    end

    selected = tonumber(selected) or 0;
    local parts = T{};
    local start = math.max(1, selected - 2);
    local stop = math.min(hit.ids:len(), selected + 2);
    if (selected <= 0) then
        start = 1;
        stop = math.min(hit.ids:len(), 5);
    end

    for idx = start, stop do
        local id = tonumber(hit.ids[idx]) or 0;
        local info = accessxi.magic_spell_resource_info(id);
        parts:append(('%d:%d:%s'):fmt(
            idx,
            id,
            accessxi.escape_probe_log_text(info ~= nil and (info.name or '') or '')));
    end
    return parts:concat(' | ');
end

function accessxi.magic_scan_backing_spell_ids(label, base, width, usable_set)
    base = tonumber(base) or 0;
    width = tonumber(width) or 2;
    if (not accessxi.is_probe_pointer(base)) then
        return nil;
    end

    local best = nil;
    local step = width;
    local max_offset = 0x160;
    local sample_count = 18;
    for off = 0, max_offset, step do
        local ids = T{};
        local unique = {};
        local known = 0;
        local usable = 0;
        local duplicate = 0;
        for i = 0, sample_count - 1 do
            local id = accessxi.magic_backing_read_id(base, off + (i * width), width);
            ids:append(id);
            local info = accessxi.magic_spell_resource_info(id);
            if (info ~= nil and tostring(info.name or '') ~= '') then
                known = known + 1;
                if (usable_set[id] == true) then
                    usable = usable + 1;
                end
                if (unique[id] == true) then
                    duplicate = duplicate + 1;
                end
                unique[id] = true;
            end
        end

        local score = (usable * 3) + known - (duplicate * 2);
        if (((usable >= 8 and known >= 12) or (known >= 5 and usable >= 2)) and (best == nil or score > best.score)) then
            best = T{
                label = tostring(label or ''),
                base = base,
                offset = off,
                width = width,
                score = score,
                known = known,
                usable = usable,
                duplicate = duplicate,
                ids = ids,
                quality = (usable >= 8 and known >= 12) and 'strong' or 'weak',
            };
        end
    end
    return best;
end

function accessxi.magic_backing_target_summary(targets)
    local parts = T{};
    if (targets ~= nil) then
        for _, target in ipairs(targets) do
            if (parts:len() < 10) then
                parts:append(('%s=0x%08X'):fmt(tostring(target.label or ''), tonumber(target.ptr) or 0));
            end
        end
    end
    return parts:concat(' ');
end

function accessxi.magic_backing_list_probe(obj, child, entry, selected, count)
    local now = tick();
    selected = tonumber(selected) or 0;
    count = tonumber(count) or 0;
    obj = tonumber(obj) or 0;
    child = tonumber(child) or 0;
    entry = tonumber(entry) or 0;

    local cache = accessxi.magic_backing_probe_cache;
    if (cache ~= nil and (now - (tonumber(cache.tick) or 0)) < 2500) then
        if (cache.best ~= nil) then
            return ('backingProbe cached=1 best="%s" window="%s"'):fmt(
                accessxi.escape_probe_log_text(cache.summary or ''),
                accessxi.escape_probe_log_text(accessxi.magic_format_backing_window(cache.best, selected)));
        end
        return 'backingProbe cached=1 best=none';
    end

    local spells = accessxi.magic_usable_spell_list_all();
    local usable_set = accessxi.magic_usable_spell_id_set(spells);
    local targets = accessxi.magic_shortcut_probe_targets(obj, child, entry);
    local hits = T{};
    for _, target in ipairs(targets) do
        local hit16 = accessxi.magic_scan_backing_spell_ids(target.label, target.ptr, 2, usable_set);
        if (hit16 ~= nil) then
            hits:append(hit16);
        end
        local hit32 = accessxi.magic_scan_backing_spell_ids(target.label, target.ptr, 4, usable_set);
        if (hit32 ~= nil) then
            hits:append(hit32);
        end
    end

    hits:sort(function (a, b)
        if ((tonumber(a.score) or 0) ~= (tonumber(b.score) or 0)) then
            return (tonumber(a.score) or 0) > (tonumber(b.score) or 0);
        end
        return tostring(a.label or '') < tostring(b.label or '');
    end);

    local best = hits[1];
    local summary = 'none';
    if (best ~= nil) then
        summary = ('%s %s base=0x%08X off=0x%03X width=%d score=%d known=%d usable=%d dup=%d'):fmt(
            tostring(best.quality or 'weak'),
            tostring(best.label or ''),
            tonumber(best.base) or 0,
            tonumber(best.offset) or 0,
            tonumber(best.width) or 0,
            tonumber(best.score) or 0,
            tonumber(best.known) or 0,
            tonumber(best.usable) or 0,
            tonumber(best.duplicate) or 0);
    end

    accessxi.magic_backing_probe_cache = T{ tick = now, best = best, summary = summary };
    if (best == nil) then
        return ('backingProbe scanned=%d best=none targets="%s"'):fmt(
            targets:len(),
            accessxi.escape_probe_log_text(accessxi.magic_backing_target_summary(targets)));
    end
    return ('backingProbe scanned=%d best="%s" window="%s"'):fmt(
        targets:len(),
        accessxi.escape_probe_log_text(summary),
        accessxi.escape_probe_log_text(accessxi.magic_format_backing_window(best, selected)));
end

function accessxi.magic_known_flag_for_id(id)
    id = tonumber(id) or 0;
    if (id <= 0 or id > 2048) then
        return false;
    end

    local memory = AshitaCore:GetMemoryManager();
    local player = memory ~= nil and memory:GetPlayer() or nil;
    if (player == nil) then
        return false;
    end

    return safe_call(function () return player:HasSpell(id); end, false) == true;
end

function accessxi.magic_entry_id_decode_add_candidate(out, seen, source, id)
    id = tonumber(id) or 0;
    if (id <= 0 or id > 2048) then
        return;
    end

    local info = accessxi.magic_spell_resource_info(id);
    if (info == nil or tostring(info.name or '') == '') then
        return;
    end

    local key = tostring(id) .. ':' .. tostring(source or '');
    if (seen[key] == true) then
        return;
    end
    seen[key] = true;

    out:append(('%s=%d:%s/t%d/s%d:%s'):fmt(
        tostring(source or ''),
        id,
        accessxi.escape_probe_log_text(info.name or ''),
        tonumber(info.type) or 0,
        tonumber(info.skill) or 0,
        accessxi.magic_known_flag_for_id(id) and 'known' or 'unknown'));
end

function accessxi.magic_entry_id_decode_for_offset(entry, off)
    entry = tonumber(entry) or 0;
    off = tonumber(off) or 0;
    if (not accessxi.is_probe_pointer(entry)) then
        return '';
    end

    local b0 = read_u8(entry + off) or 0;
    local b1 = read_u8(entry + off + 1) or 0;
    local b2 = read_u8(entry + off + 2) or 0;
    local b3 = read_u8(entry + off + 3) or 0;
    local raw = read_u32(entry + off) or 0;
    local candidates = T{};
    local seen = {};

    accessxi.magic_entry_id_decode_add_candidate(candidates, seen, 'raw32', raw);
    accessxi.magic_entry_id_decode_add_candidate(candidates, seen, 'le16a', b0 + (b1 * 0x100));
    accessxi.magic_entry_id_decode_add_candidate(candidates, seen, 'be16a', b1 + (b0 * 0x100));
    accessxi.magic_entry_id_decode_add_candidate(candidates, seen, 'le16b', b2 + (b3 * 0x100));
    accessxi.magic_entry_id_decode_add_candidate(candidates, seen, 'be16b', b3 + (b2 * 0x100));
    accessxi.magic_entry_id_decode_add_candidate(candidates, seen, 'b0', b0);
    accessxi.magic_entry_id_decode_add_candidate(candidates, seen, 'b1', b1);
    accessxi.magic_entry_id_decode_add_candidate(candidates, seen, 'b2', b2);
    accessxi.magic_entry_id_decode_add_candidate(candidates, seen, 'b3', b3);

    return ('entry+%03X raw=%08X bytes=%02X-%02X-%02X-%02X ids="%s"'):fmt(
        off,
        raw,
        b0,
        b1,
        b2,
        b3,
        candidates:concat(' | '));
end

function accessxi.magic_entry_id_decode_probe(entry)
    entry = tonumber(entry) or 0;
    if (not accessxi.is_probe_pointer(entry)) then
        return 'entryIdDecode=""';
    end

    local parts = T{};
    for _, off in ipairs(T{ 0x24, 0x3C, 0x48, 0x60, 0x64 }) do
        parts:append(accessxi.magic_entry_id_decode_for_offset(entry, off));
    end

    return ('entryIdDecode="%s"'):fmt(accessxi.escape_probe_log_text(parts:concat(' || ')));
end

function accessxi.magic_pointer_window(label, ptr, dword_count)
    ptr = tonumber(ptr) or 0;
    dword_count = tonumber(dword_count) or 0;
    if (not accessxi.is_probe_pointer(ptr) or dword_count <= 0) then
        return ('%s=0x%08X{}'):fmt(tostring(label or ''), ptr);
    end

    return ('%s=0x%08X{%s}'):fmt(
        tostring(label or ''),
        ptr,
        accessxi.escape_probe_log_text(accessxi.format_probe_dwords(ptr, 0, dword_count)));
end

function accessxi.magic_pointer_fields_probe(label, ptr, offsets)
    ptr = tonumber(ptr) or 0;
    if (not accessxi.is_probe_pointer(ptr)) then
        return '';
    end

    local parts = T{};
    for _, off in ipairs(offsets) do
        off = tonumber(off) or 0;
        local value = read_u32(ptr + off) or 0;
        if (accessxi.is_probe_pointer(value)) then
            parts:append(accessxi.magic_pointer_window(('%s+%03X'):fmt(tostring(label or ''), off), value, 8));
        end
    end
    return parts:concat(' | ');
end

function accessxi.magic_shortcut_model_probe(obj, child, entry, desc, row0, row1)
    obj = tonumber(obj) or 0;
    child = tonumber(child) or 0;
    entry = tonumber(entry) or 0;
    desc = tonumber(desc) or 0;
    row0 = tonumber(row0) or 0;
    row1 = tonumber(row1) or 0;

    local child_model = accessxi.is_probe_pointer(child) and (read_u32(child + 0x20) or 0) or 0;
    local parts = T{};
    parts:append(accessxi.magic_pointer_window('child20', child_model, 16));
    parts:append(accessxi.magic_pointer_window('entry00', entry, 16));
    parts:append(accessxi.magic_pointer_window('entry40', accessxi.is_probe_pointer(entry) and entry + 0x40 or 0, 8));
    parts:append(accessxi.magic_pointer_window('desc', desc, 8));
    parts:append(accessxi.magic_pointer_window('row0', row0, 8));
    parts:append(accessxi.magic_pointer_window('row1', row1, 8));
    parts:append(('objPtrs=[%s]'):fmt(accessxi.escape_probe_log_text(accessxi.magic_pointer_fields_probe('obj', obj, T{ 0x08, 0x0C }))));
    parts:append(('childPtrs=[%s]'):fmt(accessxi.escape_probe_log_text(accessxi.magic_pointer_fields_probe('child', child, T{ 0x08, 0x14, 0x20 }))));
    return ('modelProbe="%s"'):fmt(accessxi.escape_probe_log_text(parts:concat(' || ')));
end

function accessxi.log_magic_shortcut_model_dump(child)
    child = tonumber(child) or 0;
    if (not accessxi.is_probe_pointer(child)) then
        return;
    end

    local model = read_u32(child + 0x20) or 0;
    if (not accessxi.is_probe_pointer(model)) then
        return;
    end

    local key = ('0x%08X:0x%08X'):fmt(child, model);
    if (key == tostring(accessxi.last_magic_shortcut_model_dump_key or '')) then
        return;
    end
    accessxi.last_magic_shortcut_model_dump_key = key;

    accessxi.menudump_seq = (tonumber(accessxi.menudump_seq) or 0) + 1;
    local seq = accessxi.menudump_seq;
    log_line(('menudump seq=%d magicmodel begin child=0x%08X model=0x%08X'):fmt(seq, child, model));
    accessxi.log_probe_bytes(seq, 'magicmodel.child20', model, 0x100);
    log_line(('menudump seq=%d magicmodel end'):fmt(seq));
end

function accessxi.log_magic_entry_dump_once(entry, desc, row0, row1, selected)
    entry = tonumber(entry) or 0;
    desc = tonumber(desc) or 0;
    row0 = tonumber(row0) or 0;
    row1 = tonumber(row1) or 0;
    selected = tonumber(selected) or 0;
    if (not accessxi.is_probe_pointer(entry)) then
        return;
    end

    if (accessxi.magic_entry_dump_seen == nil) then
        accessxi.magic_entry_dump_seen = {};
        accessxi.magic_entry_dump_count = 0;
    end
    if ((tonumber(accessxi.magic_entry_dump_count) or 0) >= 6) then
        return;
    end

    local key = ('0x%08X'):fmt(entry);
    if (accessxi.magic_entry_dump_seen[key] == true) then
        return;
    end
    accessxi.magic_entry_dump_seen[key] = true;
    accessxi.magic_entry_dump_count = (tonumber(accessxi.magic_entry_dump_count) or 0) + 1;

    accessxi.menudump_seq = (tonumber(accessxi.menudump_seq) or 0) + 1;
    local seq = accessxi.menudump_seq;
    log_line(('menudump seq=%d magicentry begin selected=%d entry=0x%08X desc=0x%08X row0=0x%08X row1=0x%08X texts="%s" ptrText="%s"'):fmt(
        seq,
        selected,
        entry,
        desc,
        row0,
        row1,
        accessxi.escape_probe_log_text_wide(T{
            accessxi.magic_compact_text_probe('entry', entry, 0x120, 4),
            accessxi.magic_compact_text_probe('desc', desc, 0x80, 4),
            accessxi.magic_compact_text_probe('row0', row0, 0x100, 4),
            accessxi.magic_compact_text_probe('row1', row1, 0x140, 4),
        }:concat(' || ')),
        accessxi.escape_probe_log_text_wide(T{
            accessxi.magic_pointer_text_targets('entry', entry, 0x00, 0x80, 4),
            accessxi.magic_pointer_text_targets('desc', desc, 0x00, 0x40, 4),
        }:concat(' || '))));
    accessxi.log_probe_bytes(seq, 'magicentry.entry', entry, 0xA0);
    if (accessxi.is_probe_pointer(desc)) then
        accessxi.log_probe_bytes(seq, 'magicentry.desc', desc, 0x60);
    end
    if (accessxi.is_probe_pointer(row0)) then
        accessxi.log_probe_bytes(seq, 'magicentry.row0', row0, 0x80);
    end
    if (accessxi.is_probe_pointer(row1)) then
        accessxi.log_probe_bytes(seq, 'magicentry.row1', row1, 0xC0);
    end
    log_line(('menudump seq=%d magicentry end'):fmt(seq));
end

function accessxi.magic_spell_from_known_list(selected)
    selected = tonumber(selected) or 0;
    if (selected <= 0) then
        return nil, T{}, 0, '';
    end

    local category = accessxi.magic_current_category_label();
    local spells, wanted_type = accessxi.magic_known_spell_list_for_category(category);
    if (spells:len() <= 0 or selected > spells:len()) then
        return nil, spells, wanted_type, category;
    end

    return spells[selected], spells, wanted_type, category;
end

function accessxi.ability_resource_info(id)
    id = tonumber(id) or 0;
    if (id <= 0 or id > 2048) then
        return nil;
    end

    local resources = AshitaCore:GetResourceManager();
    if (resources == nil) then
        return nil;
    end

    local ability = safe_call(function () return resources:GetAbilityById(id); end, nil);
    if (ability == nil or ability.Name == nil) then
        return nil;
    end

    local name = accessxi.plain_native_menu_label(accessxi.survival_guide_text(ability.Name[1] or ''));
    if (name == '' or name:eq('Unknown', true)) then
        return nil;
    end

    local description = ability.Description ~= nil and accessxi.magic_spell_description_text(ability.Description[1] or '') or '';
    return T{
        id = id,
        name = name,
        description = description,
        type = tonumber(ability.Type) or 0,
        category = tonumber(ability.MenuCategoryId) or 0,
        element = tonumber(ability.Element) or 15,
        mp = tonumber(ability.ManaCost) or 0,
        tp = tonumber(ability.TPCost) or 0,
        recast = tonumber(ability.RecastTimerId) or 0,
        targets = tonumber(ability.Targets) or 0,
    };
end

function accessxi.ability_is_pet_command_type(ability_type)
    ability_type = tonumber(ability_type) or -1;
    return ability_type == 2 or ability_type == 6 or ability_type == 10 or ability_type == 18;
end

function accessxi.ability_is_job_command_type(ability_type)
    ability_type = tonumber(ability_type) or -1;
    return ability_type == 1
        or ability_type == 2
        or ability_type == 6
        or ability_type == 8
        or ability_type == 9
        or ability_type == 10
        or ability_type == 11
        or ability_type == 12
        or ability_type == 13
        or ability_type == 14
        or ability_type == 15
        or ability_type == 16
        or ability_type == 17
        or ability_type == 18
        or ability_type == 19
        or ability_type == 21
        or ability_type == 22
        or ability_type == 23;
end

function accessxi.player_has_job_command(player, id, info)
    if (player == nil) then
        return false;
    end

    local has = safe_call(function () return player:HasAbility(id); end, false);
    if (has == true or has == 1) then
        return true;
    end

    if (info ~= nil and accessxi.ability_is_pet_command_type(info.type)) then
        local has_pet = safe_call(function () return player:HasPetCommand(id); end, false);
        return (has_pet == true or has_pet == 1);
    end

    return false;
end

function accessxi.ability_format_seconds(total)
    total = math.max(tonumber(total) or 0, 0);
    local hours = math.floor(total / 3600);
    local minutes = math.floor((total % 3600) / 60);
    local seconds = math.floor(total % 60);
    if (hours > 0) then
        if (minutes > 0) then
            return ('%d hours %d minutes'):fmt(hours, minutes);
        end
        return ('%d hours'):fmt(hours);
    end
    if (minutes > 0) then
        if (seconds > 0) then
            return ('%d minutes %d seconds'):fmt(minutes, seconds);
        end
        return ('%d minutes'):fmt(minutes);
    end
    return ('%d seconds'):fmt(seconds);
end

function accessxi.ability_current_recast_seconds(info)
    if (info == nil) then
        return 0;
    end

    local recast_id = tonumber(info.recast) or -1;
    local recast = AshitaCore:GetMemoryManager():GetRecast();
    if (recast == nil) then
        return 0;
    end

    for i = 0, 31 do
        local timer_id = tonumber(safe_call(function () return recast:GetAbilityTimerId(i); end, -1)) or -1;
        local timer = tonumber(safe_call(function () return recast:GetAbilityTimer(i); end, 0)) or 0;
        if ((timer_id == recast_id or (i == 0 and recast_id == 0)) and timer > 0) then
            local seconds = math.ceil(timer / 60);
            if (seconds > 0 and seconds <= 86400) then
                return seconds;
            end
        end
    end

    return 0;
end

function accessxi.ability_recast_speech(ability, category)
    if (ability == nil) then
        return '';
    end

    category = tostring(category or '');
    if (category:eq('Weapon Skills', true)) then
        return '';
    end

    local base_recast = accessxi.ability_base_recast_seconds(ability);
    if (base_recast <= 0) then
        return '';
    end

    local current_recast = accessxi.ability_current_recast_seconds(ability);
    if (current_recast > 0) then
        return ('Ready in %s. Recast %s.'):fmt(
            accessxi.ability_format_seconds(current_recast),
            accessxi.ability_format_seconds(base_recast));
    end

    return ('Recast %s.'):fmt(accessxi.ability_format_seconds(base_recast));
end

function accessxi.ability_resource_matches_category(info, category)
    if (info == nil) then
        return false, 0;
    end

    category = tostring(category or '');
    local wanted_type = 0;
    if (category:eq('Job Abilities', true)) then
        wanted_type = 1;
    elseif (category:eq('Job Traits', true)) then
        wanted_type = 4;
    elseif (category:eq('Weapon Skills', true)) then
        wanted_type = 3;
    else
        return false, wanted_type;
    end

    if (category:eq('Job Abilities', true)) then
        return accessxi.ability_is_job_command_type(info.type), wanted_type;
    end

    return (tonumber(info.type) or 0) == wanted_type, wanted_type;
end

function accessxi.ability_known_list_for_category(category)
    category = tostring(category or '');
    local now = tick();
    if (accessxi.ability_known_cache ~= nil
        and tostring(accessxi.ability_known_cache_key or '') == category
        and (now - (tonumber(accessxi.ability_known_cache_tick) or 0)) < 1000) then
        return accessxi.ability_known_cache, tonumber(accessxi.ability_known_cache_type) or 0;
    end

    local player = AshitaCore:GetMemoryManager():GetPlayer();
    if (player == nil) then
        return T{}, 0;
    end

    local abilities = T{};
    local wanted_type = 0;
    for id = 0, 2048 do
        local known = false;
        local info = nil;
        if (category:eq('Job Traits', true)) then
            local has = safe_call(function () return player:HasTrait(id); end, false);
            known = (has == true or has == 1);
        elseif (category:eq('Weapon Skills', true)) then
            local has = safe_call(function () return player:HasWeaponSkill(id); end, false);
            known = (has == true or has == 1);
        elseif (category:eq('Job Abilities', true)) then
            info = accessxi.ability_resource_info(id);
            local matches = false;
            matches, wanted_type = accessxi.ability_resource_matches_category(info, category);
            if (matches and info ~= nil) then
                known = accessxi.player_has_job_command(player, id, info);
            end
        else
            local has = safe_call(function () return player:HasAbility(id); end, false);
            known = (has == true or has == 1);
        end

        if (known) then
            if (info == nil) then
                info = accessxi.ability_resource_info(id);
            end
            local matches = false;
            matches, wanted_type = accessxi.ability_resource_matches_category(info, category);
            if (matches and info ~= nil and info.name ~= '') then
                abilities:append(info);
            end
        end
    end

    abilities:sort(function (a, b)
        return (tonumber(a.id) or 0) < (tonumber(b.id) or 0);
    end);
    accessxi.ability_known_cache = abilities;
    accessxi.ability_known_cache_key = category;
    accessxi.ability_known_cache_type = wanted_type;
    accessxi.ability_known_cache_tick = now;
    return abilities, wanted_type;
end

function accessxi.job_ability_known_preview(abilities)
    local parts = T{};
    if (abilities == nil) then
        return '';
    end
    for i = 1, math.min(abilities:len(), 16) do
        local ability = abilities[i];
        parts:append(('%d:%s/t%d/c%d/r%d'):fmt(
            tonumber(ability.id) or 0,
            accessxi.escape_probe_log_text(ability.name or ''),
            tonumber(ability.type) or 0,
            tonumber(ability.category) or 0,
            tonumber(ability.recast) or 0));
    end
    return parts:concat(' | ');
end

function accessxi.ability_direct_child_state(child)
    child = tonumber(child) or 0;
    if (not accessxi.is_probe_pointer(child)) then
        return '';
    end

    local parts = T{};
    for _, off in ipairs(T{ 0x30, 0x34, 0x38, 0x3C, 0x40, 0x44, 0x48, 0x60, 0x64, 0x74, 0x7C, 0xE2 }) do
        parts:append(('+%02X=%d'):fmt(tonumber(off) or 0, tonumber(read_u32(child + off)) or 0));
    end
    return parts:concat(' ');
end

function accessxi.ability_direct_aix_probe_summary(category, selected, child)
    category = tostring(category or '');
    selected = tonumber(selected) or 0;
    if (category:eq('Weapon Skills', true)) then
        local order = accessxi.ability_aix_read_weapon_order();
        if (order == nil or order.ids == nil or order.ids:len() <= 0) then
            return 'weapon order unavailable';
        end
        return ('weapon path="%s" offset=0x%X ids=%d childType=%d window="%s"'):fmt(
            accessxi.escape_probe_log_text(order.path or ''),
            tonumber(order.offset) or 0,
            order.ids:len(),
            accessxi.ability_child_menu_type(child),
            accessxi.escape_probe_log_text(accessxi.ability_aix_order_window(order.ids, selected)));
    end

    if (category:eq('Job Abilities', true)) then
        local order = accessxi.ability_aix_read_known_order('Job Abilities');
        if (order == nil or order.ids == nil or order.ids:len() <= 0) then
            return 'job order unavailable';
        end
        return ('job path="%s" offset=0x%X ids=%d window="%s" note="diagnostic-only"'):fmt(
            accessxi.escape_probe_log_text(order.path or ''),
            tonumber(order.offset) or 0,
            order.ids:len(),
            accessxi.escape_probe_log_text(accessxi.ability_aix_order_window(order.ids, selected)));
    end

    return '';
end

function accessxi.log_ability_direct_state_probe(menu_name, title, obj, child, entry, selected, count, page, raw, direct_category, child_menu_type, aix_reason, native_label)
    local key = ('%s:%s:%d:%d:%d:0x%08X:0x%08X:%s:%s'):fmt(
        tostring(menu_name or ''),
        tostring(direct_category or ''),
        tonumber(selected) or 0,
        tonumber(count) or 0,
        tonumber(child_menu_type) or -1,
        tonumber(child) or 0,
        tonumber(entry) or 0,
        tostring(aix_reason or ''),
        tostring(native_label or ''));
    if (key == tostring(accessxi.last_ability_direct_state_probe_key or '')) then
        return;
    end
    accessxi.last_ability_direct_state_probe_key = key;

    direct_category = tostring(direct_category or '');
    local player = AshitaCore:GetMemoryManager():GetPlayer();
    local has_data = player ~= nil and safe_call(function () return player:HasAbilityData(); end, false) or false;
    local main_job = tonumber(player ~= nil and safe_call(function () return player:GetMainJob(); end, 0) or 0) or 0;
    local main_level = tonumber(player ~= nil and safe_call(function () return player:GetMainJobLevel(); end, 0) or 0) or 0;
    local sub_job = tonumber(player ~= nil and safe_call(function () return player:GetSubJob(); end, 0) or 0) or 0;
    local sub_level = tonumber(player ~= nil and safe_call(function () return player:GetSubJobLevel(); end, 0) or 0) or 0;
    local known = accessxi.ability_known_list_for_category(direct_category);

    log_state(('state ability-direct-probe menu="%s" title="%s" directCategory="%s" selected=%d count=%d page=%d raw=0x%08X obj=0x%08X child=0x%08X entry=0x%08X childType=%d hasAbilityData=%s main=%d/%d sub=%d/%d known=%d knownPreview="%s" childState="%s" packet="%s" aix="%s" aixReason="%s" nativeLabel="%s" windowHelp="%s" note="compact diagnostic only; no ordinal fallback"'):fmt(
        tostring(menu_name or ''),
        accessxi.escape_probe_log_text(title or ''),
        accessxi.escape_probe_log_text(direct_category),
        tonumber(selected) or 0,
        tonumber(count) or 0,
        tonumber(page) or 0,
        tonumber(raw) or 0,
        tonumber(obj) or 0,
        tonumber(child) or 0,
        tonumber(entry) or 0,
        tonumber(child_menu_type) or -1,
        tostring(has_data),
        main_job,
        main_level,
        sub_job,
        sub_level,
        known ~= nil and known:len() or 0,
        accessxi.escape_probe_log_text(accessxi.job_ability_known_preview(known)),
        accessxi.escape_probe_log_text(accessxi.ability_direct_child_state(child)),
        accessxi.escape_probe_log_text(accessxi.last_job_ability_packet_probe or ''),
        accessxi.escape_probe_log_text(accessxi.ability_direct_aix_probe_summary(direct_category, selected, child)),
        accessxi.escape_probe_log_text(aix_reason or ''),
        accessxi.escape_probe_log_text(native_label or ''),
        accessxi.escape_probe_log_text(accessxi.last_ability_window_help_probe or '')));
end

function accessxi.ability_dancer_probe_dnc_candidate_summary(order)
    local _, by_job = accessxi.load_job_ability_metadata();
    local records = by_job ~= nil and by_job[19] or nil;
    if (records == nil) then
        return '';
    end

    local record_by_resource = {};
    for _, record in ipairs(records) do
        local resource_id = tonumber(record.resource_id) or 0;
        if (resource_id > 0 and record_by_resource[resource_id] == nil) then
            record_by_resource[resource_id] = record;
        end
    end

    local bits = tostring(accessxi.job_abilities_packet_bits or '');
    local parts = T{};
    local seen = {};
    local function append_candidate(id, source_index)
        id = tonumber(id) or 0;
        if (id <= 0 or seen[id] == true) then
            return;
        end

        local record = record_by_resource[id];
        local info = accessxi.ability_resource_info(id);
        if (record == nil or info == nil or tostring(info.name or '') == '') then
            return;
        end

        seen[id] = true;
        local base_id = tonumber(record.base_id) or 0;
        local packet_bit = (#bits == 0x40 and accessxi.packet_has_bit(bits, base_id)) and 1 or 0;
        parts:append(('%d:%d:%s/t%d/c%d/l%d/rt%d/rid%d/base%d/bit%d/ord%d'):fmt(
            tonumber(source_index) or parts:len() + 1,
            id,
            accessxi.escape_probe_log_text(info.name or ''),
            tonumber(info.type) or 0,
            tonumber(info.category) or 0,
            tonumber(record.level) or 0,
            tonumber(record.recast_time) or 0,
            tonumber(record.recast_id) or 0,
            base_id,
            packet_bit,
            tonumber(record.order) or 0));
    end

    if (order ~= nil and order.ids ~= nil) then
        for i = 1, order.ids:len() do
            append_candidate(order.ids[i], i);
            if (parts:len() >= 48) then
                return parts:concat(' | ');
            end
        end
    end

    if (parts:len() <= 0) then
        for _, record in ipairs(records) do
            append_candidate(record.resource_id, tonumber(record.order) or 0);
            if (parts:len() >= 48) then
                break;
            end
        end
    end

    return parts:concat(' | ');
end

function accessxi.log_ability_dancer_state_probe(menu_name, title, obj, child, entry, selected, count, page, raw, ability, reason)
    if (ability == nil or not accessxi.ability_dancer_category_label_is_supported(ability.name)) then
        return;
    end
    if ((tonumber(accessxi.ability_dancer_state_probe_count) or 0) >= 120) then
        return;
    end

    local child_state = accessxi.ability_direct_child_state(child);
    local child_d20 = accessxi.is_scan_address(child) and accessxi.format_probe_dwords(child, 0x20, 16) or '';
    local child_d60 = accessxi.is_scan_address(child) and accessxi.format_probe_dwords(child, 0x60, 16) or '';
    local child_dA0 = accessxi.is_scan_address(child) and accessxi.format_probe_dwords(child, 0xA0, 16) or '';
    local key = ('%s:%d:%d:0x%08X:0x%08X:%d:%s:%s'):fmt(
        tostring(menu_name or ''),
        tonumber(selected) or 0,
        tonumber(count) or 0,
        tonumber(child) or 0,
        tonumber(entry) or 0,
        tonumber(ability.id) or 0,
        tostring(reason or ''),
        tostring(child_state or '') .. ':' .. tostring(child_d20 or '') .. ':' .. tostring(child_d60 or '') .. ':' .. tostring(child_dA0 or ''));
    if (key == tostring(accessxi.last_ability_dancer_state_probe_key or '')) then
        return;
    end
    accessxi.last_ability_dancer_state_probe_key = key;
    accessxi.ability_dancer_state_probe_count = (tonumber(accessxi.ability_dancer_state_probe_count) or 0) + 1;

    local order = accessxi.ability_aix_read_known_order('Job Abilities');
    local ability_aix_index = 0;
    if (order ~= nil and order.ids ~= nil) then
        local ability_id = tonumber(ability.id) or 0;
        for i = 1, order.ids:len() do
            if ((tonumber(order.ids[i]) or 0) == ability_id) then
                ability_aix_index = i;
                break;
            end
        end
    end

    local id_map = accessxi.ability_direct_probe_known_id_map();
    local dnc_candidates = accessxi.ability_dancer_probe_dnc_candidate_summary(order);
    log_state(('state nativemenu dancer-state-probe menu="%s" title="%s" select=%d count=%d page=%d raw=0x%08X obj=0x%08X child=0x%08X entry=0x%08X abilityId=%d label="%s" menuCategory=%d recastId=%d reason="%s" childState="%s" childD20="%s" childD60="%s" childDA0="%s" slots060="%s" slots0A0="%s" dncCandidates="%s" aixPath="%s" aixIds=%d selectedWindow="%s" abilityAixIndex=%d abilityWindow="%s" note="diagnostic only; no guessed speech"'):fmt(
        tostring(menu_name or ''),
        accessxi.escape_probe_log_text(title or ''),
        tonumber(selected) or 0,
        tonumber(count) or 0,
        tonumber(page) or 0,
        tonumber(raw) or 0,
        tonumber(obj) or 0,
        tonumber(child) or 0,
        tonumber(entry) or 0,
        tonumber(ability.id) or 0,
        accessxi.escape_probe_log_text(ability.name or ''),
        tonumber(ability.category) or 0,
        tonumber(ability.recast) or 0,
        accessxi.escape_probe_log_text(reason or ''),
        accessxi.escape_probe_log_text(child_state or ''),
        accessxi.escape_probe_log_text(child_d20 or ''),
        accessxi.escape_probe_log_text(child_d60 or ''),
        accessxi.escape_probe_log_text(child_dA0 or ''),
        accessxi.escape_probe_log_text(accessxi.ability_direct_probe_slot_window(child, 0x60, 0x9E, id_map)),
        accessxi.escape_probe_log_text(accessxi.ability_direct_probe_slot_window(child, 0xA0, 0xE0, id_map)),
        accessxi.escape_probe_log_text_wide(dnc_candidates or ''),
        accessxi.escape_probe_log_text(order ~= nil and tostring(order.path or '') or ''),
        (order ~= nil and order.ids ~= nil) and order.ids:len() or 0,
        accessxi.escape_probe_log_text((order ~= nil and order.ids ~= nil) and accessxi.ability_aix_order_window(order.ids, selected) or ''),
        ability_aix_index,
        accessxi.escape_probe_log_text((order ~= nil and order.ids ~= nil and ability_aix_index > 0) and accessxi.ability_aix_order_window(order.ids, ability_aix_index) or '')));
end

function accessxi.ability_aix_order_paths()
    local paths = T{};
    local seen = {};
    local function add(path)
        path = tostring(path or '');
        if (path == '' or seen[path:lower()] == true) then
            return;
        end
        seen[path:lower()] = true;
        paths:append(path);
    end

    local profile_dir = '';
    profile_dir = safe_call(function ()
        local dir = accessxi.macro_active_profile();
        return tostring(dir or '');
    end, '');
    if (profile_dir ~= '') then
        add(profile_dir:gsub('[\\/]+$', '') .. '\\aix.dat');
    end

    return paths;
end

function accessxi.ability_aix_parse_weapon_order(data)
    data = data or '';
    local player = AshitaCore:GetMemoryManager():GetPlayer();
    if (player == nil or #data < 4) then
        return T{}, 0, 0, 0;
    end

    local best = T{};
    local best_offset = 0;
    local current = T{};
    local current_offset = 0;
    local duplicate = 0;
    local seen = {};

    local function finish_run()
        if (current:len() > best:len()) then
            best = current;
            best_offset = current_offset;
        end
        current = T{};
        current_offset = 0;
    end

    for off = 0, #data - 2, 2 do
        local id = accessxi.magic_mix_u16le(data, off);
        local info = accessxi.ability_resource_info(id);
        local matches = false;
        matches = accessxi.ability_resource_matches_category(info, 'Weapon Skills');
        local known = false;
        if (matches) then
            local has = safe_call(function () return player:HasWeaponSkill(id); end, false);
            known = (has == true or has == 1);
        end

        if (matches and known) then
            if (current:len() == 0) then
                current_offset = off;
            end
            if (seen[id] == true) then
                duplicate = duplicate + 1;
            end
            seen[id] = true;
            current:append(id);
        else
            finish_run();
        end
    end
    finish_run();

    return best, best_offset, best:len(), duplicate;
end

function accessxi.ability_aix_read_weapon_order()
    local now = tick();
    local player = AshitaCore:GetMemoryManager():GetPlayer();
    local main_job = tonumber(player ~= nil and safe_call(function () return player:GetMainJob(); end, 0) or 0) or 0;
    local main_level = tonumber(player ~= nil and safe_call(function () return player:GetMainJobLevel(); end, 0) or 0) or 0;
    local sub_job = tonumber(player ~= nil and safe_call(function () return player:GetSubJob(); end, 0) or 0) or 0;
    local sub_level = tonumber(player ~= nil and safe_call(function () return player:GetSubJobLevel(); end, 0) or 0) or 0;
    local cache_key = ('%d:%d:%d:%d'):fmt(main_job, main_level, sub_job, sub_level);
    local cache = accessxi.ability_aix_weapon_order_cache;
    if (cache ~= nil and tostring(cache.key or '') == cache_key and (now - (tonumber(cache.tick) or 0)) < 1000) then
        return cache;
    end

    local result = T{
        key = cache_key,
        tick = now,
        path = '',
        offset = 0,
        bytes = 0,
        ids = T{},
        duplicate = 0,
        error = 'unread',
        main_job = main_job,
        main_level = main_level,
        sub_job = sub_job,
        sub_level = sub_level,
    };

    for _, path in ipairs(accessxi.ability_aix_order_paths()) do
        local data = accessxi.magic_mix_read_file(path);
        if (data ~= nil and #data >= 0x1C0) then
            local ids, offset, raw, duplicate = accessxi.ability_aix_parse_weapon_order(data);
            if (ids ~= nil and ids:len() >= 1) then
                result.path = path;
                result.offset = offset;
                result.bytes = #data;
                result.ids = ids;
                result.raw = raw;
                result.duplicate = duplicate;
                result.error = '';
                break;
            end
        end
    end

    accessxi.ability_aix_weapon_order_cache = result;
    return result;
end

function accessxi.ability_aix_parse_known_order(data, category)
    data = data or '';
    category = tostring(category or '');
    if (#data < 4 or category == '') then
        return T{}, 0;
    end

    local known_set, known_list = accessxi.ability_known_id_set_for_category(category);
    if (known_set == nil or known_list == nil or known_list:len() <= 0) then
        return T{}, 0;
    end

    local ids = T{};
    local seen = {};
    local first_offset = 0;
    for off = 0, #data - 2, 2 do
        local id = accessxi.magic_mix_u16le(data, off);
        if (known_set[id] == true and seen[id] ~= true) then
            local info = accessxi.ability_resource_info(id);
            local matches = false;
            matches = accessxi.ability_resource_matches_category(info, category);
            if (matches and info ~= nil and tostring(info.name or '') ~= '') then
                if (ids:len() == 0) then
                    first_offset = off;
                end
                seen[id] = true;
                ids:append(id);
            end
        end
    end

    return ids, first_offset;
end

function accessxi.ability_aix_read_known_order(category)
    category = tostring(category or '');
    local now = tick();
    local cache = accessxi.ability_aix_known_order_cache;
    if (cache ~= nil
        and tostring(cache.category or ''):eq(category, true)
        and (now - (tonumber(cache.tick) or 0)) < 60000) then
        return cache;
    end

    local result = T{
        tick = now,
        category = category,
        path = '',
        offset = 0,
        bytes = 0,
        ids = T{},
        error = 'unread',
    };

    for _, path in ipairs(accessxi.ability_aix_order_paths()) do
        local data = accessxi.magic_mix_read_file(path);
        if (data ~= nil and #data >= 0x1C0) then
            local ids, offset = accessxi.ability_aix_parse_known_order(data, category);
            if (ids ~= nil and ids:len() > result.ids:len()) then
                result.path = path;
                result.offset = offset;
                result.bytes = #data;
                result.ids = ids;
                result.error = '';
            end
        end
    end

    accessxi.ability_aix_known_order_cache = result;
    return result;
end

function accessxi.ability_aix_known_ability_for_selected(selected, category)
    selected = tonumber(selected) or 0;
    category = tostring(category or '');
    if (selected <= 0 or category == '') then
        return nil, '', 0, 'selected';
    end

    local order = accessxi.ability_aix_read_known_order(category);
    if (order == nil or order.ids == nil or order.ids:len() <= 0) then
        return nil, '', 0, 'order';
    end
    if (selected > order.ids:len()) then
        return nil, '', order.ids:len(), ('range selected=%d'):fmt(selected);
    end

    local id = tonumber(order.ids[selected]) or 0;
    local info = accessxi.ability_resource_info(id);
    local matches = false;
    matches = accessxi.ability_resource_matches_category(info, category);
    if (not matches or info == nil or tostring(info.name or '') == '') then
        return nil, '', order.ids:len(), 'resource';
    end

    local known_set = accessxi.ability_known_id_set_for_category(category);
    if (known_set == nil or known_set[id] ~= true) then
        return nil, '', order.ids:len(), 'known';
    end

    local summary = ('aix path=%s offset=0x%X bytes=%d row=%d window="%s"'):fmt(
        tostring(order.path or ''),
        tonumber(order.offset) or 0,
        tonumber(order.bytes) or 0,
        selected,
        accessxi.escape_probe_log_text(accessxi.ability_aix_order_window(order.ids, selected)));
    return info, summary, order.ids:len(), '';
end
function accessxi.ability_child_menu_type(child)
    child = tonumber(child) or 0;
    if (not accessxi.is_probe_pointer(child)) then
        return -1;
    end
    return tonumber(read_u32(child + 0x64)) or -1;
end

function accessxi.ability_direct_live_count(count, child)
    count = tonumber(count) or 0;
    child = tonumber(child) or 0;
    if (accessxi.is_probe_pointer(child)) then
        local child_count = tonumber(read_u32(child + 0x40)) or 0;
        if (child_count > 0 and child_count <= 64) then
            return child_count, 'child+40';
        end
    end
    return count, 'generic';
end

function accessxi.ability_aix_format_at(ids, index)
    index = tonumber(index) or 0;
    if (ids == nil or index <= 0 or index > ids:len()) then
        return ('%d:none'):fmt(index);
    end

    local id = tonumber(ids[index]) or 0;
    local info = accessxi.ability_resource_info(id);
    if (info == nil) then
        return ('%d:%d:unknown'):fmt(index, id);
    end
    return ('%d:%d:%s/t%d/c%d'):fmt(
        index,
        id,
        accessxi.escape_probe_log_text(info.name or ''),
        tonumber(info.type) or 0,
        tonumber(info.category) or 0);
end

function accessxi.ability_aix_order_window(ids, selected)
    local parts = T{};
    selected = tonumber(selected) or 0;
    local first = math.max(1, selected - 2);
    local last = selected + 2;
    if (ids ~= nil and ids:len() > 0) then
        last = math.min(ids:len(), last);
    end
    for index = first, last do
        parts:append(accessxi.ability_aix_format_at(ids, index));
    end
    return parts:concat(' | ');
end

function accessxi.ability_aix_weapon_skill_for_selected(selected, child)
    selected = tonumber(selected) or 0;
    child = tonumber(child) or 0;
    if (selected <= 0 or not accessxi.is_probe_pointer(child)) then
        return nil, '', 0, 'selected';
    end

    local order = accessxi.ability_aix_read_weapon_order();
    if (order == nil or order.ids == nil or order.ids:len() <= 0) then
        return nil, '', 0, 'order';
    end

    local menu_type = accessxi.ability_child_menu_type(child);
    if (menu_type ~= 3) then
        return nil, '', order.ids:len(), ('type=%d'):fmt(menu_type);
    end

    local live_count, count_source = accessxi.ability_direct_live_count(0, child);
    if (live_count <= 0 or order.ids:len() ~= live_count) then
        return nil, '', order.ids:len(), ('count live=%d aix=%d source=%s'):fmt(
            live_count,
            order.ids:len(),
            tostring(count_source or ''));
    end

    local known_list = accessxi.ability_known_list_for_category('Weapon Skills');
    if (known_list == nil or known_list:len() ~= order.ids:len()) then
        return nil, '', order.ids:len(), ('known-count live=%d aix=%d'):fmt(
            known_list ~= nil and known_list:len() or 0,
            order.ids:len());
    end

    local known_set = {};
    for _, known_ability in ipairs(known_list) do
        local known_id = tonumber(known_ability.id) or 0;
        if (known_id > 0) then
            known_set[known_id] = true;
        end
    end
    local covered = {};
    for i = 1, order.ids:len() do
        local ordered_id = tonumber(order.ids[i]) or 0;
        if (known_set[ordered_id] ~= true or covered[ordered_id] == true) then
            return nil, '', order.ids:len(), ('known-set row=%d id=%d'):fmt(i, ordered_id);
        end
        covered[ordered_id] = true;
    end

    local anchor = tonumber(read_u16(child + 0x7C)) or 0;
    local anchor_index = 0;
    for i = 1, order.ids:len() do
        if ((tonumber(order.ids[i]) or 0) == anchor) then
            anchor_index = i;
            break;
        end
    end
    local validation = 'anchor';
    if (anchor_index <= 0) then
        if (anchor == 0 or anchor == 0xFFFF) then
            validation = 'live-count-known-set';
        else
            return nil, '', order.ids:len(), ('anchor=%d not-in-aix'):fmt(anchor);
        end
    end

    local raw_index = tonumber(read_u32(child + 0x60)) or -1;
    local row = selected;
    if (row <= 0 or row > order.ids:len()) then
        return nil, '', order.ids:len(), ('range selected=%d rawIndex=%d'):fmt(selected, raw_index);
    end

    local id = tonumber(order.ids[row]) or 0;
    local info = accessxi.ability_resource_info(id);
    local matches = false;
    matches = accessxi.ability_resource_matches_category(info, 'Weapon Skills');
    if (not matches or info == nil or tostring(info.name or '') == '') then
        return nil, '', order.ids:len(), 'resource';
    end

    local player = AshitaCore:GetMemoryManager():GetPlayer();
    local has = player ~= nil and safe_call(function () return player:HasWeaponSkill(id); end, false) or false;
    local known = (has == true or has == 1);
    if (not known) then
        return nil, '', order.ids:len(), 'known';
    end

    local summary = ('aix path=%s offset=0x%X bytes=%d rawIndex=%d row=%d liveCount=%d countSource=%s knownCount=%d validation=%s anchor=child+7C:%d anchorIndex=%d window="%s"'):fmt(
        tostring(order.path or ''),
        tonumber(order.offset) or 0,
        tonumber(order.bytes) or 0,
        raw_index,
        row,
        live_count,
        tostring(count_source or ''),
        known_list:len(),
        validation,
        anchor,
        anchor_index,
        accessxi.escape_probe_log_text(accessxi.ability_aix_order_window(order.ids, row)));
    return info, summary, order.ids:len(), '';
end

function accessxi.load_job_ability_metadata()
    if (accessxi.job_ability_metadata ~= nil and accessxi.job_ability_metadata_by_job ~= nil and accessxi.job_ability_metadata_by_resource ~= nil) then
        return accessxi.job_ability_metadata, accessxi.job_ability_metadata_by_job, accessxi.job_ability_metadata_path, accessxi.job_ability_metadata_by_resource;
    end
    if (accessxi.job_ability_metadata_load_tried == true) then
        return T{}, {}, accessxi.job_ability_metadata_path, {};
    end
    accessxi.job_ability_metadata_load_tried = true;

    local path = tostring(accessxi.job_ability_metadata_path or '');
    local f = io.open(path, 'r');
    if (f == nil) then
        log_line(('job ability metadata unavailable path="%s"'):fmt(path));
        return T{}, {}, path, {};
    end

    local all = T{};
    local by_job = {};
    local by_resource = {};
    local order = 0;
    for line in f:lines() do
        local base_id, name, job, level, valid_target, recast_time, recast_id, message1, message2, animation, animation_time, cast_time, action_type =
            tostring(line or ''):match("^INSERT INTO `abilities` VALUES %((%d+),'([^']*)',(%d+),(%d+),(%d+),(%d+),(%d+),(%d+),(%d+),(%d+),(%d+),(%d+),(%d+),");
        if (base_id ~= nil) then
            order = order + 1;
            local record = T{
                base_id = tonumber(base_id) or 0,
                resource_id = (tonumber(base_id) or 0) + 512,
                sql_name = tostring(name or ''),
                job = tonumber(job) or 0,
                level = tonumber(level) or 0,
                valid_target = tonumber(valid_target) or 0,
                recast_time = tonumber(recast_time) or 0,
                recast_id = tonumber(recast_id) or 0,
                message1 = tonumber(message1) or 0,
                message2 = tonumber(message2) or 0,
                animation = tonumber(animation) or 0,
                animation_time = tonumber(animation_time) or 0,
                cast_time = tonumber(cast_time) or 0,
                action_type = tonumber(action_type) or 0,
                order = order,
            };
            all:append(record);
            if (by_job[record.job] == nil) then
                by_job[record.job] = T{};
            end
            by_job[record.job]:append(record);
            if (record.resource_id > 0 and by_resource[record.resource_id] == nil) then
                by_resource[record.resource_id] = record;
            end
        end
    end
    f:close();

    for _, list in pairs(by_job) do
        list:sort(function (a, b)
            local a_level = tonumber(a.level) or 0;
            local b_level = tonumber(b.level) or 0;
            if (a_level == b_level) then
                return (tonumber(a.order) or 0) < (tonumber(b.order) or 0);
            end
            return a_level < b_level;
        end);
    end

    accessxi.job_ability_metadata = all;
    accessxi.job_ability_metadata_by_job = by_job;
    accessxi.job_ability_metadata_by_resource = by_resource;
    log_line(('loaded job ability metadata path="%s" count=%d'):fmt(path, all:len()));
    return accessxi.job_ability_metadata, accessxi.job_ability_metadata_by_job, path, accessxi.job_ability_metadata_by_resource;
end

function accessxi.job_ability_metadata_record_for_resource_id(resource_id)
    resource_id = tonumber(resource_id) or 0;
    if (resource_id <= 0) then
        return nil;
    end

    local _, _, _, by_resource = accessxi.load_job_ability_metadata();
    if (by_resource ~= nil and by_resource[resource_id] ~= nil) then
        return by_resource[resource_id];
    end

    return nil;
end

function accessxi.ability_base_recast_seconds(ability)
    if (ability == nil) then
        return 0;
    end

    local record = accessxi.job_ability_metadata_record_for_resource_id(tonumber(ability.id) or 0);
    if (record == nil) then
        return 0;
    end

    return tonumber(record.recast_time) or 0;
end

function accessxi.ability_packet_is_top_level_job_record(record, info)
    if (record == nil or info == nil) then
        return false;
    end

    local job = tonumber(record.job) or 0;
    local recast_time = tonumber(record.recast_time) or 0;
    -- Dancer's direct Job Abilities menu shows grouped command headings; child actions live in those submenus.
    if (job == 19 and recast_time > 0) then
        return false;
    end

    return true;
end

function accessxi.ability_dancer_category_label_is_supported(label)
    label = tostring(label or '');
    return label:eq('Sambas', true)
        or label:eq('Waltzes', true)
        or label:eq('Jigs', true)
        or label:eq('Steps', true)
        or label:eq('Flourishes I', true)
        or label:eq('Flourishes II', true)
        or label:eq('Flourishes III', true);
end

function accessxi.ability_dancer_resource_matches_heading(info, label, category_id)
    if (info == nil or not accessxi.ability_dancer_category_label_is_supported(label)) then
        return false;
    end

    category_id = tonumber(category_id) or 0;
    if (category_id <= 0) then
        return false;
    end

    return (tonumber(info.type) or 0) == category_id;
end

function accessxi.ability_dancer_anchor_from_child(child)
    child = tonumber(child) or 0;
    if (not accessxi.is_probe_pointer(child)) then
        return nil, 0, 'child';
    end

    local anchor_id = tonumber(read_u16(child + 0x74)) or 0;
    if (anchor_id <= 0) then
        return nil, 0, 'anchor';
    end

    local info = accessxi.ability_resource_info(anchor_id);
    if (info == nil or not accessxi.ability_dancer_category_label_is_supported(info.name)) then
        return nil, anchor_id, 'resource';
    end

    return info, anchor_id, '';
end

function accessxi.ability_dancer_category_order_probe_summary(label, category_id, selected)
    local order, reason = accessxi.ability_packet_dancer_category_order(label, category_id);
    if (order == nil or order.ids == nil) then
        return ('reason="%s" label="%s" category=%d'):fmt(
            accessxi.escape_probe_log_text(tostring(reason or '')),
            accessxi.escape_probe_log_text(label or ''),
            tonumber(category_id) or 0);
    end

    return ('reason="" label="%s" category=%d rows=%d level=%d bits=%d window="%s"'):fmt(
        accessxi.escape_probe_log_text(order.label or label or ''),
        tonumber(order.category_id) or tonumber(category_id) or 0,
        order.ids:len(),
        tonumber(order.dancer_level) or 0,
        tonumber(order.bit_count) or 0,
        accessxi.escape_probe_log_text(accessxi.ability_aix_order_window(order.ids, selected)));
end

function accessxi.log_ability_dancer_anchor_signal_probe(menu_name, title, obj, child, entry, selected, count, page, raw, reason)
    if ((tonumber(accessxi.ability_dancer_anchor_probe_count) or 0) >= 180) then
        return;
    end

    local anchor, anchor_id, anchor_reason = accessxi.ability_dancer_anchor_from_child(child);
    if (anchor == nil) then
        return;
    end

    local child_d00 = accessxi.is_scan_address(child) and accessxi.format_probe_dwords(child, 0x00, 16) or '';
    local child_d40 = accessxi.is_scan_address(child) and accessxi.format_probe_dwords(child, 0x40, 16) or '';
    local child_d80 = accessxi.is_scan_address(child) and accessxi.format_probe_dwords(child, 0x80, 16) or '';
    local child_dC0 = accessxi.is_scan_address(child) and accessxi.format_probe_dwords(child, 0xC0, 16) or '';
    local obj_d00 = accessxi.is_scan_address(obj) and accessxi.format_probe_dwords(obj, 0x00, 16) or '';
    local entry_d00 = accessxi.is_scan_address(entry) and accessxi.format_probe_dwords(entry, 0x00, 16) or '';
    local child_state = accessxi.ability_direct_child_state(child);
    local key = ('%s:%d:%d:0x%08X:0x%08X:%d:%d:%s:%s:%s:%s:%s'):fmt(
        tostring(menu_name or ''),
        tonumber(selected) or 0,
        tonumber(count) or 0,
        tonumber(child) or 0,
        tonumber(entry) or 0,
        tonumber(anchor_id) or 0,
        tonumber(anchor.category) or 0,
        tostring(reason or ''),
        tostring(child_state or ''),
        tostring(child_d40 or ''),
        tostring(child_d80 or ''),
        tostring(child_dC0 or ''));
    if (key == tostring(accessxi.last_ability_dancer_anchor_probe_key or '')) then
        return;
    end

    accessxi.last_ability_dancer_anchor_probe_key = key;
    accessxi.ability_dancer_anchor_probe_count = (tonumber(accessxi.ability_dancer_anchor_probe_count) or 0) + 1;

    local category_rows = accessxi.ability_dancer_category_order_probe_summary(anchor.name, tonumber(anchor.category) or 0, selected);
    log_state(('state nativemenu dancer-anchor-probe menu="%s" title="%s" select=%d count=%d page=%d raw=0x%08X obj=0x%08X child=0x%08X entry=0x%08X anchorId=%d anchorLabel="%s" anchorCategory=%d anchorReason="%s" reason="%s" childState="%s" childD00="%s" childD40="%s" childD80="%s" childDC0="%s" objD00="%s" entryD00="%s" slots060="%s" slots0A0="%s" categoryRows="%s" note="diagnostic only; no guessed speech"'):fmt(
        tostring(menu_name or ''),
        accessxi.escape_probe_log_text(title or ''),
        tonumber(selected) or 0,
        tonumber(count) or 0,
        tonumber(page) or 0,
        tonumber(raw) or 0,
        tonumber(obj) or 0,
        tonumber(child) or 0,
        tonumber(entry) or 0,
        tonumber(anchor_id) or 0,
        accessxi.escape_probe_log_text(anchor.name or ''),
        tonumber(anchor.category) or 0,
        accessxi.escape_probe_log_text(anchor_reason or ''),
        accessxi.escape_probe_log_text(reason or ''),
        accessxi.escape_probe_log_text(child_state or ''),
        accessxi.escape_probe_log_text(child_d00 or ''),
        accessxi.escape_probe_log_text(child_d40 or ''),
        accessxi.escape_probe_log_text(child_d80 or ''),
        accessxi.escape_probe_log_text(child_dC0 or ''),
        accessxi.escape_probe_log_text(obj_d00 or ''),
        accessxi.escape_probe_log_text(entry_d00 or ''),
        accessxi.escape_probe_log_text(accessxi.ability_direct_probe_slot_window(child, 0x60, 0x9E, accessxi.ability_direct_probe_known_id_map())),
        accessxi.escape_probe_log_text(accessxi.ability_direct_probe_slot_window(child, 0xA0, 0xE0, accessxi.ability_direct_probe_known_id_map())),
        accessxi.escape_probe_log_text_wide(category_rows or '')));
end

function accessxi.ability_packet_dancer_category_for_anchor_child(child)
    child = tonumber(child) or 0;
    local anchor, anchor_id, anchor_reason = accessxi.ability_dancer_anchor_from_child(child);
    if (anchor == nil) then
        return nil, ('dancer child unavailable reason="%s" anchor=%d'):fmt(
            accessxi.escape_probe_log_text(tostring(anchor_reason or '')),
            tonumber(anchor_id) or 0), 0, tostring(anchor_reason or 'anchor'), '';
    end

    local child_count = tonumber(read_u32(child + 0x40)) or 0;
    local child_selected = (tonumber(read_u32(child + 0x30)) or -1) + 1;
    local category_signal = tonumber(read_u32(child + 0x64)) or 0;
    if (category_signal ~= (tonumber(anchor.category) or 0)) then
        return nil, ('dancer child unavailable reason="inactive" anchor=%d label="%s" category=%d signal=%d selected=%d count=%d'):fmt(
            tonumber(anchor_id) or 0,
            accessxi.escape_probe_log_text(anchor.name or ''),
            tonumber(anchor.category) or 0,
            category_signal,
            child_selected,
            child_count), 0, 'inactive', tostring(anchor.name or '');
    end

    if (child_count <= 0 or child_count > 64) then
        return nil, ('dancer child unavailable reason="count" anchor=%d label="%s" category=%d signal=%d selected=%d count=%d'):fmt(
            tonumber(anchor_id) or 0,
            accessxi.escape_probe_log_text(anchor.name or ''),
            tonumber(anchor.category) or 0,
            category_signal,
            child_selected,
            child_count), 0, 'count', tostring(anchor.name or '');
    end

    if (child_selected <= 0 or child_selected > child_count) then
        return nil, ('dancer child unavailable reason="selected" anchor=%d label="%s" category=%d signal=%d selected=%d count=%d'):fmt(
            tonumber(anchor_id) or 0,
            accessxi.escape_probe_log_text(anchor.name or ''),
            tonumber(anchor.category) or 0,
            category_signal,
            child_selected,
            child_count), child_count, 'selected', tostring(anchor.name or '');
    end

    local ability, summary, known_total, reason = accessxi.ability_packet_dancer_category_for_selected(child_selected, child_count, anchor.name);
    if (ability == nil) then
        return nil, ('dancer child native anchor=child+74:%d label="%s" category=%d signal=child+64:%d row=child+30+1:%d count=child+40:%d reason="%s" summary="%s"'):fmt(
            tonumber(anchor_id) or 0,
            accessxi.escape_probe_log_text(anchor.name or ''),
            tonumber(anchor.category) or 0,
            category_signal,
            child_selected,
            child_count,
            accessxi.escape_probe_log_text(tostring(reason or '')),
            accessxi.escape_probe_log_text(summary or '')), tonumber(known_total) or 0, tostring(reason or 'order'), tostring(anchor.name or '');
    end

    local child_summary = ('dancer-child native anchor=child+74:%d label="%s" category=%d signal=child+64:%d row=child+30+1:%d count=child+40:%d %s'):fmt(
        tonumber(anchor_id) or 0,
        accessxi.escape_probe_log_text(anchor.name or ''),
        tonumber(anchor.category) or 0,
        category_signal,
        child_selected,
        child_count,
        accessxi.escape_probe_log_text(summary or ''));
    return ability, child_summary, tonumber(known_total) or 0, '', tostring(anchor.name or '');
end

function accessxi.ability_packet_clear_dancer_heading()
    accessxi.ability_dancer_category_label = '';
    accessxi.ability_dancer_category_id = 0;
    accessxi.ability_dancer_category_tick = 0;
end

function accessxi.ability_packet_dancer_heading_is_fresh()
    if (not accessxi.ability_dancer_category_label_is_supported(accessxi.ability_dancer_category_label)) then
        return false;
    end
    if ((tonumber(accessxi.ability_dancer_category_id) or 0) <= 0) then
        return false;
    end
    local age = tick() - (tonumber(accessxi.ability_dancer_category_tick) or 0);
    return age >= 0 and age <= 8000;
end

function accessxi.ability_packet_is_dancer_heading(record, info)
    if (record == nil or info == nil) then
        return false;
    end
    return (tonumber(record.job) or 0) == 19
        and (tonumber(record.recast_time) or 0) == 0
        and (tonumber(info.category) or 0) > 0
        and accessxi.ability_dancer_category_label_is_supported(info.name);
end

function accessxi.ability_packet_note_dancer_heading(ability, record)
    if (not accessxi.ability_packet_is_dancer_heading(record, ability)) then
        return false;
    end

    accessxi.ability_dancer_category_label = tostring(ability.name or '');
    accessxi.ability_dancer_category_id = tonumber(ability.category) or 0;
    accessxi.ability_dancer_category_tick = tick();
    return true;
end

function accessxi.ability_packet_top_level_job_ability_count()
    local order = accessxi.ability_packet_job_ability_order();
    if (order == nil or order.ids == nil) then
        return 0;
    end
    return order.ids:len();
end

function accessxi.ability_packet_job_record_available(player, record, info)
    if (record == nil or info == nil) then
        return false;
    end

    local job = tonumber(record.job) or 0;
    local recast_time = tonumber(record.recast_time) or 0;
    if (job == 19 and recast_time == 0) then
        return true;
    end

    return player ~= nil and accessxi.player_has_job_command(player, tonumber(record.resource_id) or 0, info) or false;
end

function accessxi.ability_packet_record_menu_category_ok(record, info)
    if (record == nil or info == nil) then
        return false;
    end

    local job = tonumber(record.job) or 0;
    local recast_time = tonumber(record.recast_time) or 0;
    if (job == 19 and recast_time == 0) then
        return true;
    end

    return (tonumber(info.category) or 0) == 0;
end

function accessxi.ability_packet_dancer_category_order(label, category_id)
    accessxi.restore_job_abilities_packet_cache_if_needed();

    label = tostring(label or '');
    category_id = tonumber(category_id) or 0;
    if (label == '') then
        label = tostring(accessxi.ability_dancer_category_label or '');
    end
    if (category_id <= 0) then
        category_id = tonumber(accessxi.ability_dancer_category_id) or 0;
    end
    if (not accessxi.ability_dancer_category_label_is_supported(label) or category_id <= 0) then
        return nil, 'category';
    end

    local bits = tostring(accessxi.job_abilities_packet_bits or '');
    if (#bits ~= 0x40) then
        return nil, 'bits';
    end

    local player = AshitaCore:GetMemoryManager():GetPlayer();
    if (player == nil) then
        return nil, 'player';
    end

    local main_job = tonumber(safe_call(function () return player:GetMainJob(); end, 0)) or 0;
    local main_level = tonumber(safe_call(function () return player:GetMainJobLevel(); end, 0)) or 0;
    local sub_job = tonumber(safe_call(function () return player:GetSubJob(); end, 0)) or 0;
    local sub_level = tonumber(safe_call(function () return player:GetSubJobLevel(); end, 0)) or 0;
    local dancer_level = 0;
    if (main_job == 19) then
        dancer_level = main_level;
    elseif (sub_job == 19) then
        dancer_level = sub_level;
    end
    if (dancer_level <= 0) then
        return nil, 'job';
    end

    local cache_key = ('%s:%s:%d:%d'):fmt(accessxi.packet_hex(bits), label:lower(), category_id, dancer_level);
    local cache = accessxi.ability_dancer_category_order_cache;
    if (cache ~= nil and tostring(cache.key or '') == cache_key and (tick() - (tonumber(cache.tick) or 0)) < 1000) then
        return cache, '';
    end

    local _, by_job, metadata_path = accessxi.load_job_ability_metadata();
    local records = by_job ~= nil and by_job[19] or nil;
    if (records == nil) then
        return nil, 'metadata';
    end

    local order = T{
        key = cache_key,
        tick = tick(),
        ids = T{},
        abilities = T{},
        records = T{},
        label = label,
        category_id = category_id,
        dancer_level = dancer_level,
        bit_count = accessxi.packet_bit_count(bits),
        bits = bits,
        metadata_path = tostring(metadata_path or ''),
    };
    local seen = {};
    for _, record in ipairs(records) do
        local base_id = tonumber(record.base_id) or 0;
        local resource_id = tonumber(record.resource_id) or 0;
        local required_level = tonumber(record.level) or 0;
        local recast_time = tonumber(record.recast_time) or 0;
        if (base_id >= 0
            and base_id < 512
            and resource_id > 0
            and (tonumber(record.job) or 0) == 19
            and recast_time > 0
            and dancer_level >= required_level
            and accessxi.packet_has_bit(bits, base_id)
            and seen[resource_id] ~= true) then
            local info = accessxi.ability_resource_info(resource_id);
            local matches = accessxi.ability_resource_matches_category(info, 'Job Abilities');
            if (matches
                and info ~= nil
                and accessxi.ability_dancer_resource_matches_heading(info, label, category_id)
                and tostring(info.name or '') ~= ''
                and accessxi.player_has_job_command(player, resource_id, info)) then
                seen[resource_id] = true;
                order.ids:append(resource_id);
                order.abilities:append(info);
                order.records:append(T{
                    base_id = base_id,
                    resource_id = resource_id,
                    job = 19,
                    level = required_level,
                    order = tonumber(record.order) or 0,
                    recast_time = recast_time,
                    recast_id = tonumber(record.recast_id) or 0,
                    action_type = tonumber(record.action_type) or 0,
                });
            end
        end
    end
    accessxi.ability_packet_sort_order_by_metadata(order);

    accessxi.ability_dancer_category_order_cache = order;
    return order, '';
end

function accessxi.ability_packet_dancer_category_for_selected(selected, count, label)
    selected = tonumber(selected) or 0;
    count = tonumber(count) or 0;
    if (selected <= 0) then
        return nil, '', 0, 'selected';
    end

    local category_label = tostring(label or '');
    local category_id = 0;
    if (category_label ~= '') then
        local heading_order = accessxi.ability_packet_job_ability_order();
        if (heading_order ~= nil and heading_order.abilities ~= nil) then
            for i, ability in ipairs(heading_order.abilities) do
                if (ability ~= nil and tostring(ability.name or ''):eq(category_label, true)) then
                    category_id = tonumber(ability.category) or 0;
                    break;
                end
            end
        end
    else
        if (not accessxi.ability_packet_dancer_heading_is_fresh()) then
            return nil, ('dancer category unavailable reason="stale" label="%s" category=%d bits=%d'):fmt(
                accessxi.escape_probe_log_text(tostring(accessxi.ability_dancer_category_label or '')),
                tonumber(accessxi.ability_dancer_category_id) or 0,
                accessxi.packet_bit_count(tostring(accessxi.job_abilities_packet_bits or ''))), 0, 'stale';
        end
        local top_level_count = accessxi.ability_packet_top_level_job_ability_count();
        if (top_level_count > 0 and count == top_level_count) then
            return nil, ('dancer category unavailable reason="top-level" label="%s" category=%d rows=%d bits=%d'):fmt(
                accessxi.escape_probe_log_text(tostring(accessxi.ability_dancer_category_label or '')),
                tonumber(accessxi.ability_dancer_category_id) or 0,
                top_level_count,
                accessxi.packet_bit_count(tostring(accessxi.job_abilities_packet_bits or ''))), top_level_count, 'top-level';
        end
        category_label = tostring(accessxi.ability_dancer_category_label or '');
        category_id = tonumber(accessxi.ability_dancer_category_id) or 0;
    end

    local order, reason = accessxi.ability_packet_dancer_category_order(category_label, category_id);
    if (order == nil or order.ids == nil or order.ids:len() <= 0) then
        return nil, ('dancer category unavailable reason="%s" label="%s" category=%d bits=%d'):fmt(
            tostring(reason or ''),
            accessxi.escape_probe_log_text(category_label),
            category_id,
            accessxi.packet_bit_count(tostring(accessxi.job_abilities_packet_bits or ''))), 0, tostring(reason or 'order');
    end

    local summary = ('dancer-category packet0AC offset=0x44 label="%s" category=%d bits=%d rows=%d liveCount=%d row=%d level=%d path="%s" window="%s"'):fmt(
        accessxi.escape_probe_log_text(order.label or ''),
        tonumber(order.category_id) or 0,
        tonumber(order.bit_count) or 0,
        order.ids:len(),
        count,
        selected,
        tonumber(order.dancer_level) or 0,
        accessxi.escape_probe_log_text(order.metadata_path or ''),
        accessxi.escape_probe_log_text(accessxi.ability_aix_order_window(order.ids, selected)));

    if (count > 0 and order.ids:len() ~= count) then
        return nil, summary, order.ids:len(), 'count';
    end
    if (selected > order.ids:len()) then
        return nil, summary, order.ids:len(), 'range';
    end

    local ability = order.abilities[selected];
    if (ability == nil or tostring(ability.name or '') == '') then
        return nil, summary, order.ids:len(), 'resource';
    end

    local record = order.records ~= nil and order.records[selected] or nil;
    if (accessxi.ability_packet_note_dancer_heading(ability, record) ~= true and count > 0 and order.ids:len() == count) then
        accessxi.ability_packet_clear_dancer_heading();
    end

    return ability, summary, order.ids:len(), '';
end

function accessxi.ability_packet_append_job_records(out, seen, records, job, level, source)
    if (records == nil) then
        return;
    end
    level = tonumber(level) or 0;
    local player = AshitaCore:GetMemoryManager():GetPlayer();
    for _, record in ipairs(records) do
        local base_id = tonumber(record.base_id) or 0;
        local resource_id = tonumber(record.resource_id) or 0;
        local required_level = tonumber(record.level) or 0;
        if (base_id >= 0
            and base_id < 512
            and resource_id > 0
            and level >= required_level
            and not (tostring(source or ''):eq('sub', true) and required_level == 0)
            and accessxi.packet_has_bit(accessxi.job_abilities_packet_bits, base_id)
            and seen[resource_id] ~= true) then
            local info = accessxi.ability_resource_info(resource_id);
            local matches = false;
            matches = accessxi.ability_resource_matches_category(info, 'Job Abilities');
            local has_command = accessxi.ability_packet_job_record_available(player, record, info);
            if (matches
                and info ~= nil
                and accessxi.ability_packet_record_menu_category_ok(record, info)
                and accessxi.ability_packet_is_top_level_job_record(record, info)
                and tostring(info.name or '') ~= ''
                and has_command) then
                seen[resource_id] = true;
                out.ids:append(resource_id);
                out.abilities:append(info);
                out.records:append(T{
                    base_id = base_id,
                    resource_id = resource_id,
                    source = tostring(source or ''),
                    job = tonumber(job) or 0,
                    level = required_level,
                    order = tonumber(record.order) or 0,
                    recast_time = tonumber(record.recast_time) or 0,
                    recast_id = tonumber(record.recast_id) or 0,
                    action_type = tonumber(record.action_type) or 0,
                });
            end
        end
    end
end

function accessxi.ability_packet_sort_order_by_metadata(order)
    if (order == nil or order.ids == nil or order.abilities == nil or order.records == nil) then
        return order;
    end

    local items = T{};
    for i = 1, order.ids:len() do
        local record = order.records[i];
        items:append(T{
            id = order.ids[i],
            ability = order.abilities[i],
            record = record,
            order = record ~= nil and (tonumber(record.order) or 0) or 0,
        });
    end

    items:sort(function (a, b)
        local a_order = tonumber(a.order) or 0;
        local b_order = tonumber(b.order) or 0;
        if (a_order == b_order) then
            return (tonumber(a.id) or 0) < (tonumber(b.id) or 0);
        end
        return a_order < b_order;
    end);

    order.ids = T{};
    order.abilities = T{};
    order.records = T{};
    for _, item in ipairs(items) do
        order.ids:append(item.id);
        order.abilities:append(item.ability);
        order.records:append(item.record);
    end
    return order;
end

function accessxi.ability_packet_job_ability_order()
    accessxi.restore_job_abilities_packet_cache_if_needed();

    local bits = tostring(accessxi.job_abilities_packet_bits or '');
    if (#bits ~= 0x40) then
        return nil, 'bits';
    end

    local player = AshitaCore:GetMemoryManager():GetPlayer();
    if (player == nil) then
        return nil, 'player';
    end

    local main_job = tonumber(safe_call(function () return player:GetMainJob(); end, 0)) or 0;
    local main_level = tonumber(safe_call(function () return player:GetMainJobLevel(); end, 0)) or 0;
    local sub_job = tonumber(safe_call(function () return player:GetSubJob(); end, 0)) or 0;
    local sub_level = tonumber(safe_call(function () return player:GetSubJobLevel(); end, 0)) or 0;
    if (main_job <= 0 or main_level <= 0) then
        return nil, 'job';
    end

    local cache_key = ('%s:%d:%d:%d:%d'):fmt(accessxi.packet_hex(bits), main_job, main_level, sub_job, sub_level);
    local cache = accessxi.ability_packet_job_ability_order_cache;
    if (cache ~= nil and tostring(cache.key or '') == cache_key and (tick() - (tonumber(cache.tick) or 0)) < 1000) then
        return cache, '';
    end

    local _, by_job, metadata_path = accessxi.load_job_ability_metadata();
    if (by_job == nil) then
        return nil, 'metadata';
    end

    local order = T{
        key = cache_key,
        tick = tick(),
        ids = T{},
        abilities = T{},
        records = T{},
        main_job = main_job,
        main_level = main_level,
        sub_job = sub_job,
        sub_level = sub_level,
        bit_count = accessxi.packet_bit_count(bits),
        bits = bits,
        metadata_path = tostring(metadata_path or ''),
    };
    local seen = {};
    accessxi.ability_packet_append_job_records(order, seen, by_job[main_job], main_job, main_level, 'main');
    if (sub_job > 0 and sub_level > 0) then
        accessxi.ability_packet_append_job_records(order, seen, by_job[sub_job], sub_job, sub_level, 'sub');
    end
    accessxi.ability_packet_sort_order_by_metadata(order);

    accessxi.ability_packet_job_ability_order_cache = order;
    return order, '';
end

function accessxi.ability_packet_job_ability_for_selected(selected, count, child)
    selected = tonumber(selected) or 0;
    count = tonumber(count) or 0;
    local live_count, count_source = accessxi.ability_direct_live_count(count, child);
    if (selected <= 0) then
        accessxi.last_job_ability_packet_probe = 'selected';
        return nil, '', 0, 'selected';
    end

    local order, reason = accessxi.ability_packet_job_ability_order();
    if (order == nil or order.ids == nil or order.ids:len() <= 0) then
        accessxi.last_job_ability_packet_probe = ('packet unavailable reason="%s" bits=%d'):fmt(
            tostring(reason or ''),
            accessxi.packet_bit_count(tostring(accessxi.job_abilities_packet_bits or '')));
        return nil, accessxi.last_job_ability_packet_probe, 0, tostring(reason or 'order');
    end

    local summary = ('packet0AC offset=0x44 bits=%d rows=%d liveCount=%d countSource="%s" genericCount=%d row=%d main=%d/%d sub=%d/%d path="%s" window="%s"'):fmt(
        tonumber(order.bit_count) or 0,
        order.ids:len(),
        live_count,
        count_source,
        count,
        selected,
        tonumber(order.main_job) or 0,
        tonumber(order.main_level) or 0,
        tonumber(order.sub_job) or 0,
        tonumber(order.sub_level) or 0,
        accessxi.escape_probe_log_text(order.metadata_path or ''),
        accessxi.escape_probe_log_text(accessxi.ability_aix_order_window(order.ids, selected)));
    accessxi.last_job_ability_packet_probe = summary;

    if (live_count > 0 and order.ids:len() ~= live_count) then
        return nil, summary, order.ids:len(), 'count';
    end
    if (selected > order.ids:len()) then
        return nil, summary, order.ids:len(), 'range';
    end

    local ability = order.abilities[selected];
    if (ability == nil or tostring(ability.name or '') == '') then
        return nil, summary, order.ids:len(), 'resource';
    end

    local record = order.records ~= nil and order.records[selected] or nil;
    if (accessxi.ability_packet_note_dancer_heading(ability, record) ~= true) then
        accessxi.ability_packet_clear_dancer_heading();
    end

    return ability, summary, order.ids:len(), '';
end

function accessxi.load_job_traits_resource()
    if (accessxi.job_traits_resource ~= nil) then
        return accessxi.job_traits_resource;
    end
    if (accessxi.job_traits_resource_load_tried == true) then
        return nil;
    end
    accessxi.job_traits_resource_load_tried = true;

    local paths = T{
        accessxi.resource_path('windower', 'job_traits.lua'),
    };
    for _, path in ipairs(paths) do
        local f = io.open(path, 'rb');
        if (f ~= nil) then
            f:close();
            local ok, data = pcall(function ()
                return loadfile(path)();
            end);
            if (ok and type(data) == 'table') then
                accessxi.apply_job_traits_overlay(data);
                accessxi.job_traits_resource = data;
                accessxi.job_traits_resource_path = path;
                log_line(('loaded job traits resource path="%s"'):fmt(path));
                return accessxi.job_traits_resource;
            end
            log_line(('job traits resource load failed path="%s" err="%s"'):fmt(path, tostring(data)));
        end
    end

    log_line('job traits resource unavailable');
    return nil;
end

function accessxi.apply_job_traits_overlay(traits)
    if (type(traits) ~= 'table') then
        return;
    end

    local data = accessxi.load_menu_module_table('job_traits', T{ descriptions = {} });

    local descriptions = data.descriptions or data;
    local count = 0;
    for id, entry in pairs(descriptions) do
        local trait_id = tonumber(id) or 0;
        if (trait_id > 0 and type(entry) == 'table') then
            if (type(traits[trait_id]) ~= 'table') then
                traits[trait_id] = { id = trait_id };
            end
            for key, value in pairs(entry) do
                traits[trait_id][key] = value;
            end
            count = count + 1;
        end
    end

    log_line(('loaded job traits overlay module="menus/job_traits" count=%d'):fmt(count));
end

function accessxi.job_trait_id_from_row_code(row_code)
    row_code = tonumber(row_code) or 0;
    if (bit.band(row_code, 0xFF) ~= 1) then
        return 0;
    end

    local id = bit.band(bit.rshift(row_code, 8), 0xFF);
    if (id <= 0 or id > 512) then
        return 0;
    end
    return id;
end

function accessxi.job_trait_info_by_id(id)
    id = tonumber(id) or 0;
    if (id <= 0) then
        return nil;
    end

    local traits = accessxi.load_job_traits_resource();
    if (traits == nil) then
        return nil;
    end

    local info = traits[id];
    if (type(info) ~= 'table') then
        return nil;
    end
    return info;
end

function accessxi.job_traits_known_list()
    local now = tick();
    if (accessxi.ability_known_cache ~= nil
        and tostring(accessxi.ability_known_cache_key or '') == 'Job Traits'
        and (now - (tonumber(accessxi.ability_known_cache_tick) or 0)) < 1000) then
        return accessxi.ability_known_cache;
    end

    accessxi.restore_job_traits_packet_cache_if_needed();
    local traits_resource = accessxi.load_job_traits_resource();
    if (traits_resource == nil) then
        return T{};
    end

    local traits = T{};
    local bits = tostring(accessxi.job_traits_packet_bits or '');
    if (#bits == 0x20) then
        for id = 0, 255 do
            if (accessxi.packet_has_bit(bits, id)) then
                local info = accessxi.job_trait_info_by_id(id);
                local name = info ~= nil and tostring(info.en or info.name or '') or '';
                if (name ~= '') then
                    traits:append(T{
                        id = id,
                        name = name,
                        info = info,
                    });
                end
            end
        end
    end

    traits:sort(function (a, b)
        return (tonumber(a.id) or 0) < (tonumber(b.id) or 0);
    end);
    accessxi.ability_known_cache = traits;
    accessxi.ability_known_cache_key = 'Job Traits';
    accessxi.ability_known_cache_type = 2;
    accessxi.ability_known_cache_tick = now;
    return traits;
end

function accessxi.job_traits_row_payload_probe(label, ptr)
    ptr = tonumber(ptr) or 0;
    if (not accessxi.is_probe_pointer(ptr)) then
        return ('%s=0x%08X'):fmt(tostring(label or 'row'), ptr);
    end

    return ('%s=0x%08X dw="%s" inline="%s" runs="%s" ptrs="%s"'):fmt(
        tostring(label or 'row'),
        ptr,
        accessxi.escape_probe_log_text(accessxi.format_probe_dwords(ptr, 0, 40)),
        accessxi.escape_probe_log_text(accessxi.status_menu_probe_inline_strings(ptr)),
        accessxi.escape_probe_log_text(accessxi.status_menu_probe_runs(ptr, 0x160)),
        accessxi.escape_probe_log_text(accessxi.status_menu_probe_pointer_fields(ptr)));
end

function accessxi.job_traits_descriptor_table_probe(desc)
    desc = tonumber(desc) or 0;
    if (not accessxi.is_probe_pointer(desc)) then
        return '';
    end

    local parts = T{};
    for i = 0, 13 do
        local base = desc - ((i) * 0x14);
        if (accessxi.is_probe_pointer(base)) then
            local row0 = read_u32(base + 0x00) or 0;
            local row1 = read_u32(base + 0x04) or 0;
            local a = read_u32(base + 0x08) or 0;
            local b = read_u32(base + 0x0C) or 0;
            local c = read_u32(base + 0x10) or 0;
            if (accessxi.is_probe_pointer(row0) or accessxi.is_probe_pointer(row1)) then
                parts:append(('-%.2d:0x%08X,0x%08X,%08X,%08X,%08X'):fmt(i, row0, row1, a, b, c));
            end
        end
    end
    return parts:concat(' | ');
end

function accessxi.job_traits_shifted_packet_preview()
    local bits = tostring(accessxi.job_traits_packet_bits or '');
    local traits_resource = accessxi.load_job_traits_resource();
    if (#bits ~= 0x20 or traits_resource == nil) then
        return '';
    end

    local parts = T{};
    for bit_index = 0, 255 do
        if (accessxi.packet_has_bit(bits, bit_index)) then
            local id = bit_index + 1;
            local info = traits_resource[id];
            local name = info ~= nil and tostring(info.en or info.name or '') or '';
            if (name ~= '') then
                parts:append(('%d:%s'):fmt(id, name));
                if (parts:len() >= 24) then
                    break;
                end
            end
        end
    end
    return parts:concat(' | ');
end

function accessxi.job_traits_known_preview(traits)
    local parts = T{};
    if (traits == nil) then
        return '';
    end
    for i = 1, math.min(traits:len(), 24) do
        local trait = traits[i];
        parts:append(('%d:%s'):fmt(
            tonumber(trait.id) or 0,
            accessxi.escape_probe_log_text(trait.name or '')));
    end
    return parts:concat(' | ');
end

function accessxi.job_trait_from_known_list(selected)
    selected = tonumber(selected) or 0;
    if (selected <= 0) then
        return nil, T{};
    end

    local traits = accessxi.job_traits_known_list();
    if (selected > traits:len()) then
        return nil, traits;
    end

    return traits[selected], traits;
end

function accessxi.job_trait_from_entry(entry)
    entry = tonumber(entry) or 0;
    if (not accessxi.is_probe_pointer(entry)) then
        return nil, 0, 0;
    end

    local row_code = read_u32(entry + 0x24) or 0;
    local trait_id = accessxi.job_trait_id_from_row_code(row_code);
    if (trait_id <= 0) then
        return nil, trait_id, row_code;
    end

    return accessxi.job_trait_info_by_id(trait_id), trait_id, row_code;
end

function accessxi.job_traits_probe_player_sample()
    local player = AshitaCore:GetMemoryManager():GetPlayer();
    if (player == nil) then
        return 'player=nil';
    end

    local parts = T{};
    local has_data = safe_call(function () return player:HasAbilityData(); end, 'err');
    parts:append(('hasAbilityData=%s'):fmt(tostring(has_data)));
    for _, id in ipairs(T{ 1, 2, 3, 4, 5, 8, 10, 12, 13, 24, 97, 110, 116, 125, 295, 296, 297 }) do
        local has = safe_call(function () return player:HasTrait(id); end, 'err');
        local info = accessxi.ability_resource_info(id);
        parts:append(('%d:%s:%s/t%d'):fmt(
            id,
            tostring(has),
            accessxi.escape_probe_log_text(info ~= nil and tostring(info.name or '') or ''),
            info ~= nil and (tonumber(info.type) or 0) or 0));
    end
    return parts:concat(' | ');
end

function accessxi.log_job_traits_compact_probe(menu_name, title, selected, count, page, raw, child, entry)
    if (not tostring(accessxi.ability_current_category_label() or ''):eq('Job Traits', true)) then
        return;
    end

    local obj = get_current_menu_object_ptr();
    local key = ('%s:%d:%d:%d:0x%08X:0x%08X:0x%08X:0x%08X'):fmt(
        tostring(menu_name or ''),
        tonumber(selected) or 0,
        tonumber(count) or 0,
        tonumber(page) or 0,
        tonumber(obj) or 0,
        tonumber(raw) or 0,
        tonumber(child) or 0,
        tonumber(entry) or 0);
    if (key == tostring(accessxi.last_job_traits_probe_key or '')) then
        return;
    end
    accessxi.last_job_traits_probe_key = key;

    local row_code = accessxi.is_probe_pointer(entry) and (read_u32(entry + 0x24) or 0) or 0;

    log_line(('jobtraitsprobe menu="%s" title="%s" obj=0x%08X selected=%d count=%d page=%d raw=0x%08X child=0x%08X entry=0x%08X rowCode=0x%08X'):fmt(
        tostring(menu_name or ''),
        accessxi.escape_probe_log_text(title or ''),
        tonumber(obj) or 0,
        tonumber(selected) or 0,
        tonumber(count) or 0,
        tonumber(page) or 0,
        tonumber(raw) or 0,
        tonumber(child) or 0,
        tonumber(entry) or 0,
        tonumber(row_code) or 0));

    accessxi.restore_job_traits_packet_cache_if_needed();
    log_line(('jobtraitspacket selected=%d bitsLen=%d count=%d set="%s" direct="%s" shifted="%s"'):fmt(
        tonumber(selected) or 0,
        #(tostring(accessxi.job_traits_packet_bits or '')),
        accessxi.packet_bit_count(accessxi.job_traits_packet_bits or ''),
        accessxi.packet_set_bits(accessxi.job_traits_packet_bits or '', 255),
        accessxi.escape_probe_log_text(accessxi.job_traits_packet_bits_preview(accessxi.job_traits_packet_bits or '')),
        accessxi.escape_probe_log_text(accessxi.job_traits_shifted_packet_preview())));
end

function accessxi.job_ability_from_known_list(selected, category)
    selected = tonumber(selected) or 0;
    if (selected <= 0) then
        return nil, T{}, 0, '';
    end

    category = tostring(category or '');
    if (category == '') then
        category = accessxi.ability_effective_category_label();
    end
    local abilities, wanted_type = accessxi.ability_known_list_for_category(category);
    if (abilities:len() <= 0 or selected > abilities:len()) then
        return nil, abilities, wanted_type, category;
    end

    return abilities[selected], abilities, wanted_type, category;
end

function accessxi.ability_signal_scan_terms()
    local terms = T{};
    local seen = {};
    accessxi.add_unique_scan_term(terms, seen, 'Abilities');
    accessxi.add_unique_scan_term(terms, seen, 'Job Abilities');
    accessxi.add_unique_scan_term(terms, seen, 'Weapon Skills');

    local job_abilities = accessxi.ability_known_list_for_category('Job Abilities');
    for i = 1, math.min(job_abilities:len(), 6) do
        accessxi.add_unique_scan_term(terms, seen, job_abilities[i].name or '');
    end

    local weapon_skills = accessxi.ability_known_list_for_category('Weapon Skills');
    for i = 1, math.min(weapon_skills:len(), 6) do
        accessxi.add_unique_scan_term(terms, seen, weapon_skills[i].name or '');
    end

    return terms:concat('|'), job_abilities, weapon_skills;
end

function accessxi.ability_known_id_set_for_category(category)
    local abilities, wanted_type = accessxi.ability_known_list_for_category(category);
    local set = {};
    if (abilities ~= nil) then
        for _, ability in ipairs(abilities) do
            local id = tonumber(ability.id) or 0;
            if (id > 0) then
                set[id] = true;
            end
        end
    end
    return set, abilities, wanted_type;
end

function accessxi.ability_probe_targets(obj, child, entry)
    local targets = T{};
    local seen = {};
    local function add(label, ptr)
        ptr = tonumber(ptr) or 0;
        if (accessxi.is_probe_pointer(ptr) and seen[ptr] ~= true and targets:len() < 28) then
            seen[ptr] = true;
            targets:append(T{ label = tostring(label or ''), ptr = ptr });
        end
    end

    add('obj', obj);
    add('child', child);
    add('entry', entry);

    local function add_pointer_fields(prefix, base, offsets)
        base = tonumber(base) or 0;
        if (not accessxi.is_probe_pointer(base)) then
            return;
        end
        for _, off in ipairs(offsets) do
            add(('%s+%02X'):fmt(prefix, tonumber(off) or 0), read_u32(base + off) or 0);
        end
    end

    add_pointer_fields('obj', obj, T{ 0x04, 0x08, 0x0C, 0x10, 0x14, 0x18, 0x20, 0x24, 0x28, 0x34, 0x38, 0x40, 0x58, 0x5C });
    add_pointer_fields('child', child, T{ 0x00, 0x04, 0x08, 0x0C, 0x10, 0x14, 0x18, 0x20, 0x24, 0x28, 0x34, 0x38, 0x40, 0x58, 0x5C });
    add_pointer_fields('entry', entry, T{ 0x00, 0x04, 0x08, 0x0C, 0x10, 0x14, 0x18, 0x20, 0x24, 0x28, 0x34, 0x38, 0x40, 0x58, 0x5C });

    return targets;
end

function accessxi.ability_backing_read_id(base, offset, width)
    base = tonumber(base) or 0;
    offset = tonumber(offset) or 0;
    width = tonumber(width) or 2;
    if (not accessxi.is_probe_pointer(base)) then
        return 0;
    end
    if (width == 4) then
        local raw = read_u32(base + offset) or 0;
        if (raw > 0 and raw <= 2048) then
            return raw;
        end
        return 0;
    end
    return read_u16(base + offset) or 0;
end

function accessxi.ability_scan_backing_ids(label, base, width, job_set, weapon_set)
    base = tonumber(base) or 0;
    width = tonumber(width) or 2;
    if (not accessxi.is_probe_pointer(base)) then
        return nil;
    end

    local best = nil;
    local sample_count = 18;
    for off = 0, 0x220, width do
        local ids = T{};
        local unique = {};
        local known = 0;
        local job_known = 0;
        local weapon_known = 0;
        local resource_known = 0;
        local duplicate = 0;
        for i = 0, sample_count - 1 do
            local id = accessxi.ability_backing_read_id(base, off + (i * width), width);
            ids:append(id);
            local info = accessxi.ability_resource_info(id);
            if (info ~= nil and tostring(info.name or '') ~= '') then
                resource_known = resource_known + 1;
                if (job_set[id] == true) then
                    known = known + 1;
                    job_known = job_known + 1;
                end
                if (weapon_set[id] == true) then
                    known = known + 1;
                    weapon_known = weapon_known + 1;
                end
                if (unique[id] == true) then
                    duplicate = duplicate + 1;
                end
                unique[id] = true;
            end
        end

        local category = '';
        local pure = false;
        if (weapon_known >= 2 and job_known == 0) then
            category = 'Weapon Skills';
            pure = true;
        elseif (job_known >= 3 and weapon_known == 0) then
            category = 'Job Abilities';
            pure = true;
        elseif (weapon_known > job_known and weapon_known >= 2) then
            category = 'Weapon Skills';
        elseif (job_known > weapon_known and job_known >= 3) then
            category = 'Job Abilities';
        end

        local score = (known * 5) + (resource_known * 2) - (duplicate * 3);
        local acceptable = (pure == true and ((weapon_known >= 2) or (job_known >= 3)));
        if (acceptable and (best == nil or score > best.score)) then
            best = T{
                label = tostring(label or ''),
                base = base,
                offset = off,
                width = width,
                score = score,
                known = known,
                jobKnown = job_known,
                weaponKnown = weapon_known,
                resourceKnown = resource_known,
                duplicate = duplicate,
                category = category,
                quality = (weapon_known >= 2 and job_known == 0) and 'short-strong' or 'strong',
                ids = ids,
            };
        end
    end
    return best;
end

function accessxi.ability_format_backing_window(hit, selected)
    if (hit == nil or hit.ids == nil) then
        return '';
    end

    selected = tonumber(selected) or 0;
    local parts = T{};
    local start = math.max(1, selected - 2);
    local stop = math.min(hit.ids:len(), selected + 2);
    if (selected <= 0) then
        start = 1;
        stop = math.min(hit.ids:len(), 5);
    end

    for idx = start, stop do
        local id = tonumber(hit.ids[idx]) or 0;
        local info = accessxi.ability_resource_info(id);
        parts:append(('%d:%d:%s/t%d'):fmt(
            idx,
            id,
            accessxi.escape_probe_log_text(info ~= nil and (info.name or '') or ''),
            info ~= nil and (tonumber(info.type) or 0) or 0));
    end
    return parts:concat(' | ');
end

function accessxi.ability_backing_target_summary(targets)
    local parts = T{};
    if (targets ~= nil) then
        for _, target in ipairs(targets) do
            if (parts:len() < 12) then
                parts:append(('%s=0x%08X'):fmt(tostring(target.label or ''), tonumber(target.ptr) or 0));
            end
        end
    end
    return parts:concat(' ');
end

function accessxi.ability_backing_list_probe(obj, child, entry, selected, category_filter)
    local now = tick();
    selected = tonumber(selected) or 0;
    obj = tonumber(obj) or 0;
    child = tonumber(child) or 0;
    entry = tonumber(entry) or 0;
    category_filter = tostring(category_filter or '');

    local cache_key = ('0x%08X:0x%08X:0x%08X:%s'):fmt(obj, child, entry, category_filter);
    local cache = accessxi.ability_backing_probe_cache;
    if (cache ~= nil and tostring(cache.key or '') == cache_key and (now - (tonumber(cache.tick) or 0)) < 1500) then
        return cache.best, cache.summary, cache.targets;
    end

    local job_set = {};
    local weapon_set = {};
    if (category_filter == '' or category_filter:eq('Job Abilities', true)) then
        job_set = accessxi.ability_known_id_set_for_category('Job Abilities');
    end
    if (category_filter == '' or category_filter:eq('Weapon Skills', true)) then
        weapon_set = accessxi.ability_known_id_set_for_category('Weapon Skills');
    end

    local targets = accessxi.ability_probe_targets(obj, child, entry);
    local hits = T{};
    for _, target in ipairs(targets) do
        local hit16 = accessxi.ability_scan_backing_ids(target.label, target.ptr, 2, job_set, weapon_set);
        if (hit16 ~= nil and (category_filter == '' or tostring(hit16.category or ''):eq(category_filter, true))) then
            hits:append(hit16);
        end
        local hit32 = accessxi.ability_scan_backing_ids(target.label, target.ptr, 4, job_set, weapon_set);
        if (hit32 ~= nil and (category_filter == '' or tostring(hit32.category or ''):eq(category_filter, true))) then
            hits:append(hit32);
        end
    end

    hits:sort(function (a, b)
        if ((tonumber(a.score) or 0) ~= (tonumber(b.score) or 0)) then
            return (tonumber(a.score) or 0) > (tonumber(b.score) or 0);
        end
        return tostring(a.label or '') < tostring(b.label or '');
    end);

    local best = hits[1];
    local summary = 'none';
    if (best ~= nil) then
        summary = ('%s %s category="%s" base=0x%08X off=0x%03X width=%d score=%d known=%d job=%d weapon=%d res=%d dup=%d window="%s"'):fmt(
            tostring(best.quality or 'weak'),
            tostring(best.label or ''),
            accessxi.escape_probe_log_text(best.category or ''),
            tonumber(best.base) or 0,
            tonumber(best.offset) or 0,
            tonumber(best.width) or 0,
            tonumber(best.score) or 0,
            tonumber(best.known) or 0,
            tonumber(best.jobKnown) or 0,
            tonumber(best.weaponKnown) or 0,
            tonumber(best.resourceKnown) or 0,
            tonumber(best.duplicate) or 0,
            accessxi.escape_probe_log_text(accessxi.ability_format_backing_window(best, selected)));
    end

    accessxi.ability_backing_probe_cache = T{ tick = now, key = cache_key, best = best, summary = summary, targets = targets };
    return best, summary, targets;
end

function accessxi.ability_from_backing_model(obj, child, entry, selected, category_filter)
    local best, summary, targets = accessxi.ability_backing_list_probe(obj, child, entry, selected, category_filter);
    local selected_id = 0;
    local ability = nil;
    local category = '';
    local known_total = 0;

    if (best ~= nil and best.ids ~= nil) then
        selected_id = tonumber(best.ids[tonumber(selected) or 0]) or 0;
        ability = accessxi.ability_resource_info(selected_id);
        category = tostring(best.category or '');
        if (ability ~= nil and tostring(category or '') ~= '') then
            local matches = accessxi.ability_resource_matches_category(ability, category);
            local known_set, known_list = accessxi.ability_known_id_set_for_category(category);
            known_total = known_list ~= nil and known_list:len() or 0;
            if (matches ~= true or known_set[selected_id] ~= true) then
                ability = nil;
            end
        end
    end

    local key = ('0x%08X:%d:%s:%d:%s'):fmt(
        tonumber(entry) or 0,
        tonumber(selected) or 0,
        tostring(category_filter or ''),
        selected_id,
        tostring(summary or ''));
    if (key ~= tostring(accessxi.last_ability_backing_probe_key or '')) then
        accessxi.last_ability_backing_probe_key = key;
        log_state(('state ability-backing-probe select=%d entry=0x%08X filter="%s" selectedId=%d accepted=%s summary="%s" targets="%s"'):fmt(
            tonumber(selected) or 0,
            tonumber(entry) or 0,
            accessxi.escape_probe_log_text(category_filter or ''),
            selected_id,
            tostring(ability ~= nil),
            accessxi.escape_probe_log_text(summary or 'none'),
            accessxi.escape_probe_log_text(accessxi.ability_backing_target_summary(targets))));
    end

    if (ability ~= nil) then
        return ability, category, summary, known_total;
    end
    return nil, category, summary, known_total;
end

function accessxi.ability_direct_probe_known_id_map()
    local map = {};
    for _, category in ipairs(T{ 'Job Abilities', 'Weapon Skills' }) do
        local abilities = accessxi.ability_known_list_for_category(category);
        if (abilities ~= nil) then
            for _, ability in ipairs(abilities) do
                local id = tonumber(ability.id) or 0;
                local name = tostring(ability.name or '');
                if (id > 0 and name ~= '') then
                    map[id] = ('%s:%s'):fmt(category, name);
                end
            end
        end
    end
    return map;
end

function accessxi.ability_direct_probe_id_hits(ptr, length, id_map, limit)
    ptr = tonumber(ptr) or 0;
    length = tonumber(length) or 0;
    limit = tonumber(limit) or 16;
    if (not accessxi.is_scan_address(ptr) or length <= 0 or id_map == nil) then
        return '';
    end

    local hits = T{};
    local seen = {};
    for off = 0, math.max(0, length - 2) do
        local value = read_u16(ptr + off) or 0;
        if (id_map[value] ~= nil) then
            local key = ('u16:%03X:%d'):fmt(off, value);
            if (seen[key] ~= true) then
                seen[key] = true;
                hits:append(('+%03X:u16=%d:%s'):fmt(off, value, accessxi.escape_probe_log_text(id_map[value])));
                if (hits:len() >= limit) then
                    return hits:concat(' | ');
                end
            end
        end
    end

    for off = 0, math.max(0, length - 4) do
        local value = read_u32(ptr + off) or 0;
        if (id_map[value] ~= nil) then
            local key = ('u32:%03X:%d'):fmt(off, value);
            if (seen[key] ~= true) then
                seen[key] = true;
                hits:append(('+%03X:u32=%d:%s'):fmt(off, value, accessxi.escape_probe_log_text(id_map[value])));
                if (hits:len() >= limit) then
                    return hits:concat(' | ');
                end
            end
        end
    end

    return hits:concat(' | ');
end

function accessxi.ability_direct_probe_text_summary(ptr, length)
    ptr = tonumber(ptr) or 0;
    length = tonumber(length) or 0;
    if (not accessxi.is_scan_address(ptr) or length <= 0) then
        return '';
    end

    local parts = T{};
    if (accessxi.collect_probe_ascii_runs ~= nil and accessxi.probe_runs_to_text ~= nil) then
        local ascii = accessxi.probe_runs_to_text(accessxi.collect_probe_ascii_runs(ptr, length, 3, 6));
        if (ascii ~= '') then
            parts:append(('ascii="%s"'):fmt(accessxi.escape_probe_log_text(ascii)));
        end
    end
    if (accessxi.collect_probe_ffxi_utf16_runs ~= nil and accessxi.probe_runs_to_text ~= nil) then
        local ffxi16 = accessxi.probe_runs_to_text(accessxi.collect_probe_ffxi_utf16_runs(ptr, length, 3, 6));
        if (ffxi16 ~= '') then
            parts:append(('ffxi16="%s"'):fmt(accessxi.escape_probe_log_text(ffxi16)));
        end
    end

    return parts:concat(' ');
end

function accessxi.ability_direct_probe_pointer_summary(label, base, id_map)
    base = tonumber(base) or 0;
    if (not accessxi.is_probe_pointer(base)) then
        return '';
    end

    local parts = T{};
    for off = 0x00, 0x90, 4 do
        local ptr = read_u32(base + off) or 0;
        if (accessxi.is_probe_pointer(ptr)) then
            local id_hits = accessxi.ability_direct_probe_id_hits(ptr, 0x120, id_map, 4);
            local text = accessxi.ability_direct_probe_text_summary(ptr, 0x120);
            if (id_hits ~= '' or text ~= '') then
                parts:append(('%s+%02X=0x%08X ids="%s" %s'):fmt(
                    tostring(label or ''),
                    off,
                    ptr,
                    accessxi.escape_probe_log_text(id_hits),
                    text));
                if (parts:len() >= 10) then
                    break;
                end
            end
        end
    end

    return parts:concat(' || ');
end

function accessxi.ability_direct_probe_known_preview(id_map)
    local parts = T{};
    for id = 1, 2048 do
        if (id_map[id] ~= nil) then
            parts:append(('%d:%s'):fmt(id, accessxi.escape_probe_log_text(id_map[id])));
            if (parts:len() >= 18) then
                break;
            end
        end
    end
    return parts:concat(' | ');
end

function accessxi.ability_direct_probe_slot_window(ptr, start_offset, end_offset, id_map)
    ptr = tonumber(ptr) or 0;
    if (not accessxi.is_scan_address(ptr)) then
        return '';
    end

    local parts = T{};
    for off = tonumber(start_offset) or 0, tonumber(end_offset) or 0, 2 do
        local value16 = read_u16(ptr + off) or 0;
        local value32 = read_u32(ptr + off) or 0;
        local label16 = id_map ~= nil and id_map[value16] or nil;
        local label32 = id_map ~= nil and id_map[value32] or nil;
        if (value16 ~= 0 or label16 ~= nil or label32 ~= nil) then
            local part = ('+%03X:u16=%d'):fmt(off, value16);
            if (label16 ~= nil) then
                part = part .. (':%s'):fmt(accessxi.escape_probe_log_text(label16));
            end
            if (label32 ~= nil) then
                part = part .. (' u32=%d:%s'):fmt(value32, accessxi.escape_probe_log_text(label32));
            end
            parts:append(part);
        end
        if (parts:len() >= 36) then
            break;
        end
    end
    return parts:concat(' | ');
end

function accessxi.log_ability_direct_raw_probe(menu_name, title, obj, child, entry, selected, count, page, raw, reason)
    entry = tonumber(entry) or 0;
    if (not accessxi.is_probe_pointer(entry)) then
        return;
    end

    if (accessxi.ability_direct_raw_seen == nil) then
        accessxi.ability_direct_raw_seen = {};
        accessxi.ability_direct_raw_count = 0;
    end
    if ((tonumber(accessxi.ability_direct_raw_count) or 0) >= 8) then
        return;
    end

    local key = ('%s:%d:%d:0x%08X:0x%08X:%s'):fmt(
        tostring(menu_name or ''),
        tonumber(selected) or 0,
        tonumber(count) or 0,
        entry,
        tonumber(raw) or 0,
        tostring(reason or ''));
    if (accessxi.ability_direct_raw_seen[key] == true) then
        return;
    end
    accessxi.ability_direct_raw_seen[key] = true;
    accessxi.ability_direct_raw_count = (tonumber(accessxi.ability_direct_raw_count) or 0) + 1;

    local id_map = accessxi.ability_direct_probe_known_id_map();
    accessxi.menu_dump_sequence = (accessxi.menu_dump_sequence or 0) + 1;
    local seq = accessxi.menu_dump_sequence;
    obj = tonumber(obj) or 0;
    child = tonumber(child) or 0;
    local prev_entry = entry - 0x7B8;
    local next_entry = entry + 0x7B8;

    log_state(('state ability-direct-raw begin seq=%d reason="%s" menu="%s" title="%s" select=%d count=%d page=%d raw=0x%08X obj=0x%08X child=0x%08X entry=0x%08X prev=0x%08X next=0x%08X knownPreview="%s" note="diagnostic only; no ordinal fallback"'):fmt(
        seq,
        accessxi.escape_probe_log_text(reason or ''),
        tostring(menu_name or ''),
        accessxi.escape_probe_log_text(title or ''),
        tonumber(selected) or 0,
        tonumber(count) or 0,
        tonumber(page) or 0,
        tonumber(raw) or 0,
        obj,
        child,
        entry,
        prev_entry,
        next_entry,
        accessxi.escape_probe_log_text(accessxi.ability_direct_probe_known_preview(id_map))));

    local targets = T{
        T{ label = 'obj', ptr = obj, len = 0xC0 },
        T{ label = 'child', ptr = child, len = 0x120 },
        T{ label = 'entry', ptr = entry, len = 0x180 },
        T{ label = 'entry-prev7B8', ptr = prev_entry, len = 0x100 },
        T{ label = 'entry-next7B8', ptr = next_entry, len = 0x100 },
    };

    for _, target in ipairs(targets) do
        local ptr = tonumber(target.ptr) or 0;
        local length = tonumber(target.len) or 0;
        if (accessxi.is_scan_address(ptr)) then
            local id_hits = accessxi.ability_direct_probe_id_hits(ptr, length, id_map, 12);
            local text = accessxi.ability_direct_probe_text_summary(ptr, length);
            local dwords = accessxi.format_probe_dwords(ptr, 0x00, math.min(24, math.floor(length / 4)));
            log_state(('state ability-direct-raw target seq=%d label="%s" ptr=0x%08X len=0x%X ids="%s" dwords="%s" %s'):fmt(
                seq,
                tostring(target.label or ''),
                ptr,
                length,
                accessxi.escape_probe_log_text(id_hits),
                accessxi.escape_probe_log_text(dwords),
                text));
            if (target.label == 'entry') then
                accessxi.log_probe_bytes(seq, 'abilitydirect.entry', ptr, 0x100);
            elseif (target.label == 'child') then
                accessxi.log_probe_bytes(seq, 'abilitydirect.child', ptr, 0x120);
            end
        end
    end

    if (accessxi.is_scan_address(child)) then
        log_state(('state ability-direct-raw child-slots seq=%d child=0x%08X slots060="%s" slots0A0="%s"'):fmt(
            seq,
            child,
            accessxi.escape_probe_log_text(accessxi.ability_direct_probe_slot_window(child, 0x60, 0x9E, id_map)),
            accessxi.escape_probe_log_text(accessxi.ability_direct_probe_slot_window(child, 0xA0, 0xE0, id_map))));
    end

    local obj_ptrs = accessxi.ability_direct_probe_pointer_summary('obj', obj, id_map);
    local child_ptrs = accessxi.ability_direct_probe_pointer_summary('child', child, id_map);
    local entry_ptrs = accessxi.ability_direct_probe_pointer_summary('entry', entry, id_map);
    log_state(('state ability-direct-raw ptrs seq=%d obj="%s" child="%s" entry="%s"'):fmt(
        seq,
        accessxi.escape_probe_log_text_wide(obj_ptrs),
        accessxi.escape_probe_log_text_wide(child_ptrs),
        accessxi.escape_probe_log_text_wide(entry_ptrs)));
end

function accessxi.log_ability_menu_signal_scan(menu_name, title, selected, count, page, raw, child, entry, obj, reason)
    local now = tick();
    if (now < (tonumber(accessxi.ability_signal_scan_suppress_until) or 0)) then
        return;
    end

    local key = ('%s:%d:%d:0x%08X:0x%08X:0x%08X'):fmt(
        tostring(menu_name or ''),
        tonumber(selected) or 0,
        tonumber(count) or 0,
        tonumber(obj) or 0,
        tonumber(child) or 0,
        tonumber(entry) or 0);
    if (key == tostring(accessxi.last_ability_signal_scan_key or '')) then
        return;
    end

    accessxi.last_ability_signal_scan_key = key;
    accessxi.ability_signal_scan_suppress_until = now + 3500;
    local terms, job_abilities, weapon_skills = accessxi.ability_signal_scan_terms();
    accessxi.menu_dump_sequence = (accessxi.menu_dump_sequence or 0) + 1;
    local seq = accessxi.menu_dump_sequence;
    log_state(('state ability-signal-scan begin seq=%d reason="%s" menu="%s" title="%s" select=%d count=%d page=%d raw=0x%08X obj=0x%08X child=0x%08X entry=0x%08X jobKnown=%d weaponKnown=%d jobPreview="%s" weaponPreview="%s" terms="%s"'):fmt(
        seq,
        accessxi.escape_probe_log_text(reason or ''),
        tostring(menu_name or ''),
        accessxi.escape_probe_log_text(title or ''),
        tonumber(selected) or 0,
        tonumber(count) or 0,
        tonumber(page) or 0,
        tonumber(raw) or 0,
        tonumber(obj) or 0,
        tonumber(child) or 0,
        tonumber(entry) or 0,
        job_abilities ~= nil and job_abilities:len() or 0,
        weapon_skills ~= nil and weapon_skills:len() or 0,
        accessxi.escape_probe_log_text(accessxi.job_ability_known_preview(job_abilities)),
        accessxi.escape_probe_log_text(accessxi.job_ability_known_preview(weapon_skills)),
        accessxi.escape_probe_log_text(terms)));
    accessxi.log_survival_guide_memory_scan(seq, 'ability-signal', terms);
end

function accessxi.ability_exact_info_from_label(label, category)
    label = accessxi.plain_native_menu_label(label or '');
    if (label == '') then
        return nil, '', 0, 0;
    end

    local categories = T{};
    category = tostring(category or '');
    if (category:eq('Job Abilities', true) or category:eq('Weapon Skills', true)) then
        categories:append(category);
    else
        categories:append('Job Abilities');
        categories:append('Weapon Skills');
    end

    for _, candidate_category in ipairs(categories) do
        local abilities, wanted_type = accessxi.ability_known_list_for_category(candidate_category);
        local matched = nil;
        local match_count = 0;
        for _, ability in ipairs(abilities) do
            if (label:eq(ability.name or '', true)) then
                matched = ability;
                match_count = match_count + 1;
            end
        end
        if (match_count == 1 and matched ~= nil) then
            return matched, candidate_category, wanted_type, abilities:len();
        end
    end

    return nil, category, 0, 0;
end

function accessxi.ability_from_native_row_label(entry, child, selected, count, category)
    local rendered_label = accessxi.magic_rendered_row_text(entry, selected);
    local rendered_label_source = 'rendered-row';
    if (rendered_label == '' and accessxi.is_probe_pointer(child) and accessxi.native_query_label_for_selection ~= nil) then
        local queried_label, queried_mode = accessxi.native_query_label_for_selection(child, selected, count, 'plain');
        queried_label = accessxi.plain_native_menu_label(queried_label or '');
        if (queried_label ~= '') then
            rendered_label = queried_label;
            rendered_label_source = tostring(queried_mode or 'native-query');
        end
    end

    local ability, ability_category, wanted_type, known_total = accessxi.ability_exact_info_from_label(rendered_label, category);
    if (ability == nil) then
        return nil, ability_category, rendered_label_source, rendered_label, known_total, wanted_type;
    end

    local source_name = tostring(ability_category or ''):eq('Weapon Skills', true) and 'rendered-exact-weapon-skill' or 'rendered-exact-ability';
    if (rendered_label_source ~= 'rendered-row') then
        source_name = tostring(ability_category or ''):eq('Weapon Skills', true) and 'native-query-exact-weapon-skill' or 'native-query-exact-ability';
    end
    return ability, ability_category, source_name, rendered_label, known_total, wanted_type;
end

function accessxi.ability_current_window_help_text()
    local target = safe_call(function () return AshitaCore:GetMemoryManager():GetTarget(); end, nil);
    if (target == nil) then
        return '', '', 0, 0, '';
    end

    local title_ptr = tonumber(safe_call(function () return target:GetWindowHelpTitle(); end, 0)) or 0;
    local help_ptr = tonumber(safe_call(function () return target:GetWindowHelpString(); end, 0)) or 0;
    local window_name = accessxi.survival_guide_text(safe_call(function () return target:GetWindowName(); end, '') or '');
    local title = accessxi.plain_native_menu_label(read_probe_string(title_ptr, 160));
    local help = accessxi.magic_spell_description_text(read_probe_string(help_ptr, 300));
    return title, help, title_ptr, help_ptr, window_name;
end

function accessxi.ability_from_window_help(category)
    category = tostring(category or '');
    local title, help, title_ptr, help_ptr, window_name = accessxi.ability_current_window_help_text();
    local title_ability, title_category, _, title_known_total = accessxi.ability_exact_info_from_label(title, category);
    if (title_ability ~= nil) then
        local description = accessxi.magic_spell_description_text(title_ability.description or '');
        if (help == '' or (description ~= '' and description:eq(help, true))) then
            accessxi.last_ability_window_help_probe = ('source=window-title-exact win="%s" titlePtr=0x%08X title="%s" helpPtr=0x%08X help="%s"'):fmt(
                accessxi.escape_probe_log_text(window_name or ''),
                tonumber(title_ptr) or 0,
                accessxi.escape_probe_log_text(title or ''),
                tonumber(help_ptr) or 0,
                accessxi.escape_probe_log_text(help or ''));
            return title_ability, title_category, 'window-title-exact', title, help, title_ptr, help_ptr, window_name, title_known_total;
        end
    end

    if (help == '') then
        accessxi.last_ability_window_help_probe = ('source=window-help-empty win="%s" titlePtr=0x%08X title="%s" helpPtr=0x%08X'):fmt(
            accessxi.escape_probe_log_text(window_name or ''),
            tonumber(title_ptr) or 0,
            accessxi.escape_probe_log_text(title or ''),
            tonumber(help_ptr) or 0);
        return nil, category, 'window-help-empty', title, help, title_ptr, help_ptr, window_name, 0;
    end

    local categories = T{};
    if (category:eq('Job Abilities', true) or category:eq('Weapon Skills', true)) then
        categories:append(category);
    else
        categories:append('Job Abilities');
        categories:append('Weapon Skills');
    end

    local matches = T{};
    local title_matches = T{};
    for _, candidate_category in ipairs(categories) do
        local abilities = accessxi.ability_known_list_for_category(candidate_category);
        for _, ability in ipairs(abilities) do
            local description = accessxi.magic_spell_description_text(ability.description or '');
            if (description ~= '' and description:eq(help, true)) then
                local match = T{
                    ability = ability,
                    category = candidate_category,
                    known_total = abilities:len(),
                };
                matches:append(match);
                if (title ~= '' and title:eq(ability.name or '', true)) then
                    title_matches:append(match);
                end
            end
        end
    end

    local selected_match = nil;
    local source = 'window-help-ambiguous';
    if (title_matches:len() == 1) then
        selected_match = title_matches[1];
        source = 'window-title-help-exact';
    elseif (matches:len() == 1) then
        selected_match = matches[1];
        source = 'window-help-exact';
    end

    accessxi.last_ability_window_help_probe = ('source=%s matches=%d titleMatches=%d win="%s" titlePtr=0x%08X title="%s" helpPtr=0x%08X help="%s"'):fmt(
        source,
        matches:len(),
        title_matches:len(),
        accessxi.escape_probe_log_text(window_name or ''),
        tonumber(title_ptr) or 0,
        accessxi.escape_probe_log_text(title or ''),
        tonumber(help_ptr) or 0,
        accessxi.escape_probe_log_text(help or ''));

    if (selected_match ~= nil) then
        return selected_match.ability,
            selected_match.category,
            source,
            title ~= '' and title or help,
            help,
            title_ptr,
            help_ptr,
            window_name,
            tonumber(selected_match.known_total) or 0;
    end

    return nil, category, source, title, help, title_ptr, help_ptr, window_name, matches:len();
end

function accessxi.ability_row_speech(menu_name, title, category, category_source, selected, count, entry, ability, source_name, rendered_label, known_total)
    if (ability == nil or tostring(ability.name or '') == '') then
        return nil;
    end

    local ability_name = tostring(ability.name or '');
    local ability_id = tonumber(ability.id) or 0;
    local row_kind = tostring(category or ''):eq('Weapon Skills', true) and 'weapon-skill' or 'job-ability';
    accessxi.last_native_menu_name = menu_name;
    accessxi.last_native_menu_label = ability_name;
    accessxi.last_native_menu_selected = selected;
    accessxi.last_native_menu_tick = tick();
    accessxi.current_speech_key = ('native-%s-rendered-row:%s:%s:%d:%d:%s:%s'):fmt(
        row_kind,
        menu_name,
        tostring(category_source or ''),
        tonumber(selected) or 0,
        ability_id,
        ability_name,
        tostring(source_name or ''));
    local base_recast = accessxi.ability_base_recast_seconds(ability);
    local current_recast = accessxi.ability_current_recast_seconds(ability);
    local recast_text = accessxi.ability_recast_speech(ability, category);
    log_state(('state nativemenu %s-row menu="%s" title="%s" category="%s" categorySource="%s" select=%d count=%d entry=0x%08X abilityId=%d type=%d menuCategory=%d recastId=%d baseRecast=%d currentRecast=%d source="%s" label="%s" rendered="%s" renderCells="%s" known=%d descLen=%d'):fmt(
        row_kind,
        menu_name,
        title,
        tostring(category or ''),
        tostring(category_source or ''),
        tonumber(selected) or 0,
        tonumber(count) or 0,
        tonumber(entry) or 0,
        ability_id,
        tonumber(ability.type) or 0,
        tonumber(ability.category) or 0,
        tonumber(ability.recast) or 0,
        tonumber(base_recast) or 0,
        tonumber(current_recast) or 0,
        tostring(source_name or 'rendered-exact-label'),
        accessxi.escape_probe_log_text(ability_name),
        accessxi.escape_probe_log_text(rendered_label or ''),
        accessxi.escape_probe_log_text(accessxi.last_magic_render_cells or ''),
        tonumber(known_total) or 0,
        #(tostring(ability.description or ''))));
    local spoken_parts = T{
        accessxi.sentence_fragment(ability_name),
    };
    if (recast_text ~= '') then
        spoken_parts:append(accessxi.sentence_fragment(recast_text));
    end
    if (tostring(ability.description or '') ~= '') then
        spoken_parts:append(accessxi.sentence_fragment(ability.description));
    end
    return ('%s. %s'):fmt(tostring(category or 'Job Abilities'), spoken_parts:concat(' '));
end

function accessxi.magic_spell_name_by_id(id)
    id = tonumber(id) or 0;
    if (id <= 0 or id > 2048) then
        return '', false;
    end

    local info = accessxi.magic_spell_resource_info(id);
    if (info == nil) then
        return '', false;
    end

    local player = AshitaCore:GetMemoryManager():GetPlayer();
    local known = player ~= nil and safe_call(function () return player:HasSpell(id); end, false) == true;
    return info.name, known, info;
end

function accessxi.append_magic_spell_candidate(out, seen, source, offset, kind, id, require_known)
    id = tonumber(id) or 0;
    if (id <= 0 or id > 2048) then
        return;
    end

    local name, known, info = accessxi.magic_spell_name_by_id(id);
    if (name == '') then
        return;
    end
    if (require_known and not known) then
        return;
    end

    local key = ('%d:%s'):fmt(id, name);
    if (seen[key]) then
        return;
    end
    seen[key] = true;
    out:append(T{
        id = id,
        name = name,
        known = known,
        type = info ~= nil and info.type or 0,
        skill = info ~= nil and info.skill or 0,
        source = tostring(source or ''),
        offset = tonumber(offset) or 0,
        kind = tostring(kind or ''),
    });
end

function accessxi.magic_entry_row_pointers(entry)
    entry = tonumber(entry) or 0;
    if (not accessxi.is_probe_pointer(entry)) then
        return 0, 0, 0;
    end

    local desc = read_u32(entry + 0x0C) or 0;
    if (not accessxi.is_probe_pointer(desc)) then
        return desc, 0, 0;
    end

    return desc, read_u32(desc + 0x00) or 0, read_u32(desc + 0x04) or 0;
end

function accessxi.magic_rendered_row_cells(entry, selected, scan_radius, include_empty_text)
    entry = tonumber(entry) or 0;
    selected = tonumber(selected) or 0;
    if (not accessxi.is_probe_pointer(entry) or selected <= 0) then
        return T{};
    end

    local cells = T{};
    local seen = {};
    local parent = read_u32(entry + 0x5C) or 0;
    local function add_cell(cell)
        cell = tonumber(cell) or 0;
        if (not accessxi.is_probe_pointer(cell) or seen[cell] == true) then
            return;
        end
        if ((read_u32(cell + 0x58) or 0) ~= cell) then
            return;
        end
        if (accessxi.is_probe_pointer(parent) and (read_u32(cell + 0x5C) or 0) ~= parent) then
            return;
        end

        local row_code = read_u32(cell + 0x38) or 0;
        local row_index = math.floor(row_code / 0x10000);
        if (row_index ~= selected) then
            return;
        end

        local text = accessxi.search_result_rendered_cell_text(cell);
        if (text == '' and include_empty_text ~= true) then
            return;
        end

        seen[cell] = true;
        cells:append(T{
            ptr = cell,
            order = row_code % 0x10000,
            text = text,
        });
    end

    add_cell(entry);
    scan_radius = math.min(math.max(tonumber(scan_radius) or 16, 0), 64);
    for delta = -scan_radius, scan_radius do
        add_cell(entry + (delta * 0x68));
    end

    cells:sort(function (a, b)
        if (a.order == b.order) then
            return (tonumber(a.ptr) or 0) < (tonumber(b.ptr) or 0);
        end
        return (tonumber(a.order) or 0) < (tonumber(b.order) or 0);
    end);

    return cells;
end

function accessxi.magic_rendered_row_text(entry, selected)
    local cells = accessxi.magic_rendered_row_cells(entry, selected, 16, false);
    if (cells:len() == 0) then
        accessxi.last_magic_render_cells = '';
        return '';
    end

    local parts = T{};
    local details = T{};
    local last = '';
    for _, cell in ipairs(cells) do
        local text = tostring(cell.text or '');
        if (text ~= '' and text ~= last) then
            parts:append(text);
            last = text;
        end
        details:append(('+%04X@0x%08X="%s"'):fmt(
            tonumber(cell.order) or 0,
            tonumber(cell.ptr) or 0,
            accessxi.escape_probe_log_text(cell.text or '')));
    end

    accessxi.last_magic_render_cells = details:concat(' | ');
    return accessxi.plain_native_menu_label(parts:concat(' '):gsub('%s+', ' '):trim());
end

function accessxi.magic_spell_from_rendered_label(label)
    label = accessxi.plain_native_menu_label(label or '');
    if (label == '') then
        return nil, '', 0, 0;
    end

    local category = accessxi.magic_current_category_label();
    local spells, wanted_type = accessxi.magic_known_spell_list_for_category(category);
    if (wanted_type <= 0 or spells:len() <= 0) then
        return nil, category, wanted_type, 0;
    end

    for _, spell in ipairs(spells) do
        if (label:eq(spell.name or '', true)) then
            return spell, category, wanted_type, spells:len();
        end
    end

    return nil, category, wanted_type, spells:len();
end

function accessxi.magic_spell_from_exact_label_any(label)
    label = accessxi.plain_native_menu_label(label or '');
    if (label == '') then
        return nil, 0;
    end

    local player = safe_call(function () return AshitaCore:GetMemoryManager():GetPlayer(); end, nil);
    local matches = T{};
    for id = 1, 2048 do
        local info = accessxi.magic_spell_resource_info(id);
        if (info ~= nil and label:eq(info.name or '', true)) then
            local known = true;
            if (player ~= nil) then
                known = safe_call(function () return player:HasSpell(id); end, false) == true;
            end
            if (known == true) then
                matches:append(info);
            end
        end
    end

    if (matches:len() == 1) then
        return matches[1], matches:len();
    end
    return nil, matches:len();
end

function accessxi.magic_current_window_help_text()
    local target = safe_call(function () return AshitaCore:GetMemoryManager():GetTarget(); end, nil);
    if (target == nil) then
        return '', '', 0, 0, '';
    end

    local title_ptr = tonumber(safe_call(function () return target:GetWindowHelpTitle(); end, 0)) or 0;
    local help_ptr = tonumber(safe_call(function () return target:GetWindowHelpString(); end, 0)) or 0;
    local window_name = accessxi.survival_guide_text(safe_call(function () return target:GetWindowName(); end, '') or '');
    local title = accessxi.plain_native_menu_label(read_probe_string(title_ptr, 160));
    local help = accessxi.magic_spell_description_text(read_probe_string(help_ptr, 300));
    return title, help, title_ptr, help_ptr, window_name;
end

function accessxi.magic_spell_from_window_help()
    local title, help, title_ptr, help_ptr, window_name = accessxi.magic_current_window_help_text();
    local title_spell, title_count = accessxi.magic_spell_from_exact_label_any(title);
    if (title_spell ~= nil and (help == '' or tostring(title_spell.description or ''):eq(help, true))) then
        return title_spell, 1, 'window-title-exact', title, help, title_ptr, help_ptr, window_name, title_count;
    end

    if (help == '') then
        return nil, 0, 'window-help-empty', title, help, title_ptr, help_ptr, window_name, title_count or 0;
    end

    local spells = accessxi.magic_known_spell_list_all();
    local matches = T{};
    local title_matches = T{};
    for _, spell in ipairs(spells) do
        local description = accessxi.magic_spell_description_text(spell.description or '');
        if (description ~= '' and description:eq(help, true)) then
            matches:append(spell);
            if (title ~= '' and title:eq(spell.name or '', true)) then
                title_matches:append(spell);
            end
        end
    end

    if (title_matches:len() == 1) then
        return title_matches[1], matches:len(), 'window-title-help-exact', title, help, title_ptr, help_ptr, window_name, title_count or 0;
    end
    if (matches:len() == 1) then
        return matches[1], matches:len(), 'window-help-exact', title, help, title_ptr, help_ptr, window_name, title_count or 0;
    end

    return nil, matches:len(), 'window-help-ambiguous', title, help, title_ptr, help_ptr, window_name, title_count or 0;
end

function accessxi.magic_compact_text_probe(label, ptr, length, limit)
    ptr = tonumber(ptr) or 0;
    if (not accessxi.is_probe_pointer(ptr)) then
        return '';
    end

    length = tonumber(length) or 0x180;
    limit = tonumber(limit) or 8;
    local parts = T{};

    if (accessxi.collect_probe_ffxi_utf16_entries ~= nil) then
        for _, entry in ipairs(accessxi.collect_probe_ffxi_utf16_entries(ptr, length, 3, limit)) do
            local text = accessxi.survival_guide_text(entry.text or ''):gsub('%s+', ' '):trim();
            if (text ~= '') then
                parts:append(('%s.ffxi16+%03X="%s"'):fmt(
                    tostring(label or ''),
                    tonumber(entry.offset) or 0,
                    accessxi.escape_probe_log_text(text)));
            end
            if (parts:len() >= limit) then
                return parts:concat(' | ');
            end
        end
    end

    if (accessxi.collect_probe_ascii_runs ~= nil) then
        for _, run in ipairs(accessxi.collect_probe_ascii_runs(ptr, length, 3, limit)) do
            parts:append(('%s.ascii%s'):fmt(tostring(label or ''), tostring(run or '')));
            if (parts:len() >= limit) then
                return parts:concat(' | ');
            end
        end
    end

    return parts:concat(' | ');
end

function accessxi.magic_pointer_text_targets(label, ptr, start_offset, end_offset, limit)
    ptr = tonumber(ptr) or 0;
    if (not accessxi.is_probe_pointer(ptr)) then
        return '';
    end

    start_offset = tonumber(start_offset) or 0;
    end_offset = tonumber(end_offset) or 0x80;
    limit = tonumber(limit) or 8;
    local parts = T{};
    local seen = {};
    for off = start_offset, end_offset, 4 do
        if (parts:len() >= limit) then
            break;
        end
        local target = read_u32(ptr + off) or 0;
        if (accessxi.is_probe_pointer(target) and seen[target] ~= true) then
            seen[target] = true;
            local text = accessxi.magic_compact_text_probe(('%s+%03X'):fmt(tostring(label or ''), off), target, 0x180, 4);
            if (text ~= '') then
                parts:append(('0x%08X{%s}'):fmt(target, text));
            end
        end
    end

    return parts:concat(' || ');
end

function accessxi.magic_text_runs(label, ptr, length, min_len, limit)
    ptr = tonumber(ptr) or 0;
    if (not accessxi.is_probe_pointer(ptr)) then
        return '';
    end

    length = tonumber(length) or 0x120;
    min_len = tonumber(min_len) or 2;
    limit = tonumber(limit) or 6;

    local parts = T{};
    if (accessxi.collect_probe_ascii_runs ~= nil) then
        local ascii = accessxi.collect_probe_ascii_runs(ptr, length, min_len, limit);
        if (#ascii > 0) then
            parts:append(('%s.ascii=%s'):fmt(tostring(label or ''), ascii:concat(' ')));
        end
    end
    if (accessxi.collect_probe_utf16_runs ~= nil) then
        local utf16 = accessxi.collect_probe_utf16_runs(ptr, length, min_len, limit);
        if (#utf16 > 0) then
            parts:append(('%s.utf16=%s'):fmt(tostring(label or ''), utf16:concat(' ')));
        end
    end
    if (accessxi.collect_probe_ffxi_utf16_runs ~= nil) then
        local ffxi = accessxi.collect_probe_ffxi_utf16_runs(ptr, length, min_len, limit);
        if (#ffxi > 0) then
            parts:append(('%s.ffxi=%s'):fmt(tostring(label or ''), ffxi:concat(' ')));
        end
    end

    return parts:concat(' | ');
end

function accessxi.magic_row_cell_probe(entry, selected)
    local cells = accessxi.magic_rendered_row_cells(entry, selected, 32, true);
    if (cells:len() == 0) then
        return 'cells=0';
    end

    local parts = T{};
    for _, cell in ipairs(cells) do
        local ptr = tonumber(cell.ptr) or 0;
        parts:append(('cell=0x%08X order=0x%04X inline="%s" dwords="%s" bytes3C="%s" text="%s" ptrText="%s"'):fmt(
            ptr,
            tonumber(cell.order) or 0,
            accessxi.escape_probe_log_text(cell.text or ''),
            accessxi.escape_probe_log_text(accessxi.format_probe_dwords(ptr, 0x00, 28)),
            accessxi.escape_probe_log_text(accessxi.format_probe_bytes(ptr, 0x3C, 0x50)),
            accessxi.escape_probe_log_text(accessxi.magic_text_runs('cell', ptr, 0x140, 2, 8)),
            accessxi.escape_probe_log_text(accessxi.magic_pointer_text_targets('cell', ptr, 0x00, 0x80, 6))));
        if (parts:len() >= 4) then
            break;
        end
    end

    return parts:concat(' || ');
end

function accessxi.magic_list_state_probe(child)
    child = tonumber(child) or 0;
    if (not accessxi.is_probe_pointer(child)) then
        return '';
    end

    local state = read_u32(child + 0x20) or 0;
    if (not accessxi.is_probe_pointer(state)) then
        return ('child+020=0x%08X'):fmt(state);
    end

    return ('child+020=0x%08X d000="%s" d080="%s" text="%s" ptrText="%s"'):fmt(
        state,
        accessxi.escape_probe_log_text(accessxi.format_probe_dwords(state, 0x00, 32)),
        accessxi.escape_probe_log_text(accessxi.format_probe_dwords(state, 0x80, 32)),
        accessxi.escape_probe_log_text(accessxi.magic_text_runs('list', state, 0x220, 2, 12)),
        accessxi.escape_probe_log_text(accessxi.magic_pointer_text_targets('list', state, 0x00, 0x140, 12)));
end

function accessxi.magic_owner_state_probe(child)
    child = tonumber(child) or 0;
    if (not accessxi.is_probe_pointer(child)) then
        return '';
    end

    local owner = read_u32(child + 0x14) or 0;
    if (not accessxi.is_probe_pointer(owner)) then
        return ('child+014=0x%08X'):fmt(owner);
    end

    return ('child+014=0x%08X d000="%s" d080="%s" text="%s" ptrText="%s"'):fmt(
        owner,
        accessxi.escape_probe_log_text(accessxi.format_probe_dwords(owner, 0x00, 24)),
        accessxi.escape_probe_log_text(accessxi.format_probe_dwords(owner, 0x80, 24)),
        accessxi.escape_probe_log_text(accessxi.magic_text_runs('owner', owner, 0x180, 3, 10)),
        accessxi.escape_probe_log_text(accessxi.magic_pointer_text_targets('owner', owner, 0x00, 0x100, 10)));
end

function accessxi.magic_ank_shape_probe()
    local target = safe_call(function () return AshitaCore:GetMemoryManager():GetTarget(); end, nil);
    if (target == nil) then
        return 'target=nil';
    end

    local help_title, help_text, help_title_ptr, help_ptr, window_name = accessxi.magic_current_window_help_text();
    local ank_num = tonumber(safe_call(function () return target:GetWindowAnkNum(); end, -1)) or -1;
    local ank_x = tonumber(safe_call(function () return target:GetWindowAnkX(); end, -1)) or -1;
    local ank_y = tonumber(safe_call(function () return target:GetWindowAnkY(); end, -1)) or -1;
    local start_index = math.max(0, ank_num - 4);
    local end_index = math.min(24, math.max(ank_num + 4, 8));
    local parts = T{};

    for i = start_index, end_index do
        local shape = tonumber(safe_call(function () return target:GetWindowAnkShape(i); end, 0)) or 0;
        if (shape ~= 0) then
            local text = '';
            local ptrs = '';
            if (accessxi.is_probe_pointer(shape)) then
                text = accessxi.magic_text_runs(('shape%d'):fmt(i), shape, 0x120, 3, 4);
                ptrs = accessxi.magic_pointer_text_targets(('shape%d'):fmt(i), shape, 0x00, 0x80, 4);
            end
            parts:append(('%d=0x%08X text="%s" ptrText="%s"'):fmt(
                i,
                shape,
                accessxi.escape_probe_log_text(text),
                accessxi.escape_probe_log_text(ptrs)));
        end
    end

    return ('win="%s" helpTitlePtr=0x%08X helpTitle="%s" helpPtr=0x%08X help="%s" ank=%d xy=(%d,%d) shapes="%s"'):fmt(
        accessxi.escape_probe_log_text(window_name),
        tonumber(help_title_ptr) or 0,
        accessxi.escape_probe_log_text(help_title),
        tonumber(help_ptr) or 0,
        accessxi.escape_probe_log_text(help_text),
        ank_num,
        ank_x,
        ank_y,
        parts:concat(' || '));
end

function accessxi.magic_query_surface_add_candidate(out, seen, label, ptr, selected, count)
    ptr = tonumber(ptr) or 0;
    selected = tonumber(selected) or 0;
    count = tonumber(count) or 0;
    if (not accessxi.is_probe_pointer(ptr) or seen[ptr] == true or out:len() >= 8) then
        return;
    end
    seen[ptr] = true;

    local first = read_u32(ptr + 0x14) or 0;
    local last = read_u32(ptr + 0x18) or 0;
    if (not accessxi.is_probe_pointer(first)) then
        return;
    end
    if (last ~= 0 and not accessxi.is_probe_pointer(last)) then
        return;
    end

    local child_count = tonumber(read_i32(ptr + 0x24)) or 0;
    local child_count2 = tonumber(read_i32(ptr + 0x28)) or 0;
    local expected = math.max(child_count, child_count2, count);
    if (expected <= 0 or expected > 64) then
        expected = count;
    end
    if (expected <= 0 or expected > 64) then
        return;
    end

    local row_label, mode = accessxi.native_query_label_for_selection(ptr, selected, expected, 'magic');
    row_label = accessxi.plain_native_menu_label(row_label or '');
    local spell, spell_count = accessxi.magic_spell_from_exact_label_any(row_label);
    out:append(('%s=0x%08X first=0x%08X last=0x%08X cnt=%d/%d mode=%s label="%s" spellMatches=%d spellId=%d'):fmt(
        tostring(label or ''),
        ptr,
        first,
        last,
        child_count,
        child_count2,
        tostring(mode or ''),
        accessxi.escape_probe_log_text(row_label),
        tonumber(spell_count) or 0,
        spell ~= nil and (tonumber(spell.id) or 0) or 0));
end

function accessxi.magic_query_surface_probe(obj, child, entry, desc, row0, row1, selected, count)
    obj = tonumber(obj) or 0;
    child = tonumber(child) or 0;
    entry = tonumber(entry) or 0;
    desc = tonumber(desc) or 0;
    row0 = tonumber(row0) or 0;
    row1 = tonumber(row1) or 0;
    selected = tonumber(selected) or 0;
    count = tonumber(count) or 0;
    local out = T{};
    local seen = {};
    local function add(label, ptr)
        accessxi.magic_query_surface_add_candidate(out, seen, label, ptr, selected, count);
    end
    local function scan(label, base, first, last)
        base = tonumber(base) or 0;
        if (not accessxi.is_probe_pointer(base)) then
            return;
        end
        first = tonumber(first) or 0;
        last = tonumber(last) or 0xC0;
        for off = first, last, 4 do
            if (out:len() >= 8) then
                return;
            end
            add(('%s+%03X'):fmt(tostring(label or ''), off), read_u32(base + off) or 0);
        end
    end

    add('obj', obj);
    add('child', child);
    add('entry', entry);
    add('desc', desc);
    add('row0', row0);
    add('row1', row1);
    scan('obj', obj, 0x00, 0x80);
    scan('child', child, 0x00, 0xC0);
    scan('entry', entry, 0x00, 0x80);
    scan('desc', desc, 0x00, 0x60);
    scan('row0', row0, 0x00, 0xC0);
    scan('row1', row1, 0x00, 0x140);
    return out:concat(' || ');
end

function accessxi.log_magic_menu_text_probe(menu_name, title, obj, child, entry, selected, count, desc, row0, row1, rendered_label)
    if (not tostring(menu_name or ''):eq('menu    magic', true)) then
        return;
    end

    selected = tonumber(selected) or 0;
    count = tonumber(count) or 0;
    obj = tonumber(obj) or 0;
    child = tonumber(child) or 0;
    entry = tonumber(entry) or 0;
    desc = tonumber(desc) or 0;
    row0 = tonumber(row0) or 0;
    row1 = tonumber(row1) or 0;
    local row2 = accessxi.is_probe_pointer(desc) and (read_u32(desc + 0x08) or 0) or 0;
    local key = ('%s:%d:%d:0x%08X:0x%08X:0x%08X:0x%08X:%s'):fmt(
        tostring(menu_name or ''),
        selected,
        count,
        entry,
        child,
        row1,
        row2,
        tostring(rendered_label or ''));
    local now = tick();
    if (key == tostring(accessxi.last_magic_text_probe_key or '')
        or (now - (tonumber(accessxi.last_magic_text_probe_tick) or 0)) < 250) then
        return;
    end
    accessxi.last_magic_text_probe_key = key;
    accessxi.last_magic_text_probe_tick = now;

    log_state(('state magic-text-probe-lite menu="%s" title="%s" select=%d count=%d obj=0x%08X child=0x%08X entry=0x%08X desc=0x%08X row0=0x%08X row1=0x%08X row2=0x%08X category="%s" rendered="%s" row0Text="%s" row1Text="%s" descPtrs="%s" querySurface="%s"'):fmt(
        tostring(menu_name or ''),
        tostring(title or ''),
        selected,
        count,
        obj,
        child,
        entry,
        desc,
        row0,
        row1,
        row2,
        accessxi.escape_probe_log_text(accessxi.magic_current_category_label()),
        accessxi.escape_probe_log_text(rendered_label or ''),
        accessxi.escape_probe_log_text_wide(accessxi.magic_compact_text_probe('row0', row0, 0x180, 8)),
        accessxi.escape_probe_log_text_wide(accessxi.magic_compact_text_probe('row1', row1, 0x240, 10)),
        accessxi.escape_probe_log_text_wide(accessxi.magic_pointer_text_targets('desc', desc, 0x00, 0x40, 6)),
        accessxi.escape_probe_log_text_wide(accessxi.magic_query_surface_probe(obj, child, entry, desc, row0, row1, selected, count))));
end

function accessxi.collect_magic_spell_candidates_for_ptr(out, seen, source, ptr, require_known)
    ptr = tonumber(ptr) or 0;
    if (not accessxi.is_probe_pointer(ptr)) then
        return;
    end

    for off = 0, 0x120, 2 do
        accessxi.append_magic_spell_candidate(out, seen, source, off, 'u16', read_u16(ptr + off) or 0, require_known);
    end
    for off = 0, 0x120, 4 do
        accessxi.append_magic_spell_candidate(out, seen, source, off, 'u32', read_u32(ptr + off) or 0, require_known);
    end
end

function accessxi.append_magic_spell_candidate_detail(out, seen, source, offset, kind, id, require_known)
    id = tonumber(id) or 0;
    if (id <= 0 or id > 2048) then
        return;
    end

    local name, known, info = accessxi.magic_spell_name_by_id(id);
    if (name == '') then
        return;
    end
    if (require_known and not known) then
        return;
    end

    local key = ('%s:%03X:%s:%d:%s'):fmt(tostring(source or ''), tonumber(offset) or 0, tostring(kind or ''), id, name);
    if (seen[key]) then
        return;
    end
    seen[key] = true;
    out:append(T{
        id = id,
        name = name,
        known = known,
        type = info ~= nil and info.type or 0,
        skill = info ~= nil and info.skill or 0,
        source = tostring(source or ''),
        offset = tonumber(offset) or 0,
        kind = tostring(kind or ''),
    });
end

function accessxi.collect_magic_spell_candidate_details_for_ptr(source, ptr, require_known, limit)
    local out = T{};
    local seen = {};
    ptr = tonumber(ptr) or 0;
    limit = tonumber(limit) or 24;
    if (not accessxi.is_probe_pointer(ptr)) then
        return out;
    end

    for off = 0, 0x120, 2 do
        accessxi.append_magic_spell_candidate_detail(out, seen, source, off, 'u16', read_u16(ptr + off) or 0, require_known);
        if (out:len() >= limit) then
            return out;
        end
    end
    for off = 0, 0x120, 4 do
        accessxi.append_magic_spell_candidate_detail(out, seen, source, off, 'u32', read_u32(ptr + off) or 0, require_known);
        if (out:len() >= limit) then
            return out;
        end
    end

    return out;
end

function accessxi.magic_spell_candidate_details_from_entry(entry, require_known)
    local desc, row0, row1 = accessxi.magic_entry_row_pointers(entry);
    local groups = T{};
    groups:append(T{ source = 'entry', ptr = tonumber(entry) or 0, candidates = accessxi.collect_magic_spell_candidate_details_for_ptr('entry', entry, require_known, 24) });
    groups:append(T{ source = 'desc', ptr = tonumber(desc) or 0, candidates = accessxi.collect_magic_spell_candidate_details_for_ptr('desc', desc, require_known, 24) });
    groups:append(T{ source = 'row0', ptr = tonumber(row0) or 0, candidates = accessxi.collect_magic_spell_candidate_details_for_ptr('row0', row0, require_known, 24) });
    groups:append(T{ source = 'row1', ptr = tonumber(row1) or 0, candidates = accessxi.collect_magic_spell_candidate_details_for_ptr('row1', row1, require_known, 32) });
    return groups, desc, row0, row1;
end

function accessxi.format_magic_spell_candidates(candidates)
    local parts = T{};
    if (candidates == nil) then
        return '';
    end

    for _, candidate in ipairs(candidates) do
        parts:append(('%s+%03X/%s=%d:%s/t%d/s%d:%s'):fmt(
            tostring(candidate.source or ''),
            tonumber(candidate.offset) or 0,
            tostring(candidate.kind or ''),
            tonumber(candidate.id) or 0,
            accessxi.escape_probe_log_text(candidate.name or ''),
            tonumber(candidate.type) or 0,
            tonumber(candidate.skill) or 0,
            candidate.known and 'known' or 'unknown'));
    end

    return parts:concat(' | ');
end

function accessxi.format_magic_spell_candidate_groups(groups)
    local parts = T{};
    if (groups == nil) then
        return '';
    end

    for _, group in ipairs(groups) do
        local candidates = group.candidates;
        if (candidates ~= nil and candidates:len() > 0) then
            parts:append(('%s@0x%08X[%s]'):fmt(
                tostring(group.source or ''),
                tonumber(group.ptr) or 0,
                accessxi.format_magic_spell_candidates(candidates)));
        end
    end

    return parts:concat(' || ');
end

function accessxi.magic_spell_candidates_from_entry(entry, require_known)
    local candidates = T{};
    local seen = {};
    local desc, row0, row1 = accessxi.magic_entry_row_pointers(entry);
    if (not accessxi.is_probe_pointer(desc)) then
        return candidates, desc, 0, 0;
    end

    accessxi.collect_magic_spell_candidates_for_ptr(candidates, seen, 'row1', row1, require_known);
    if (candidates:len() == 0) then
        accessxi.collect_magic_spell_candidates_for_ptr(candidates, seen, 'desc', desc, require_known);
        accessxi.collect_magic_spell_candidates_for_ptr(candidates, seen, 'row0', row0, require_known);
        accessxi.collect_magic_spell_candidates_for_ptr(candidates, seen, 'entry', entry, require_known);
    end

    return candidates, desc, row0, row1;
end

function accessxi.magic_spell_label_from_entry(entry)
    local candidates, desc, row0, row1 = accessxi.magic_spell_candidates_from_entry(entry, true);
    if (candidates:len() == 1) then
        return candidates[1].name, candidates[1].id, desc, row0, row1, candidates;
    end

    return '', 0, desc, row0, row1, candidates;
end

function accessxi.magic_spell_from_selected_entry(entry)
    local desc, row0, row1 = accessxi.magic_entry_row_pointers(entry);
    -- entry+0x3A/row0+0x12 looked spell-like for the first page only; live wrap proved it is not a stable spell id.
    return nil, desc, row0, row1, 0, 0, 'disabled-row-index-field';
end

function accessxi.magic_dynamic_spell_from_entry(entry, selected, child)
    local desc, row0, row1 = accessxi.magic_entry_row_pointers(entry);
    child = tonumber(child) or 0;
    selected = tonumber(selected) or 0;
    local rendered_label = accessxi.magic_rendered_row_text(entry, selected);
    local category_label, category_spells, category_type = accessxi.magic_category_list_context();
    local rendered_spell, rendered_count = nil, 0;
    if (category_label ~= '') then
        rendered_label = accessxi.plain_native_menu_label(rendered_label or '');
        if (rendered_label ~= '' and category_spells ~= nil) then
            for _, spell in ipairs(category_spells) do
                if (rendered_label:eq(spell.name or '', true)) then
                    rendered_spell = spell;
                    rendered_count = 1;
                    break;
                end
            end
        end
    else
        rendered_spell, rendered_count = accessxi.magic_spell_from_exact_label_any(rendered_label);
    end
    if (rendered_spell ~= nil) then
        return rendered_spell, desc, row0, row1, tonumber(rendered_spell.id) or 0, 1, 'rendered-exact', rendered_label, category_label, tonumber(rendered_spell.type) or 0, rendered_count;
    end

    local help_spell, help_count, help_source, help_title, help_text, help_title_ptr, help_ptr, window_name, title_count = accessxi.magic_spell_from_window_help();
    accessxi.last_magic_window_help_probe = ('source=%s matches=%d titleMatches=%d win="%s" titlePtr=0x%08X title="%s" helpPtr=0x%08X help="%s"'):fmt(
        tostring(help_source or ''),
        tonumber(help_count) or 0,
        tonumber(title_count) or 0,
        accessxi.escape_probe_log_text(window_name or ''),
        tonumber(help_title_ptr) or 0,
        accessxi.escape_probe_log_text(help_title or ''),
        tonumber(help_ptr) or 0,
        accessxi.escape_probe_log_text(help_text or ''));
    if (help_spell ~= nil and (category_label == '' or tonumber(help_spell.type) == tonumber(category_type))) then
        return help_spell, desc, row0, row1, tonumber(help_spell.id) or 0, tonumber(help_count) or 1, tostring(help_source or 'window-help-exact'), rendered_label, category_label, tonumber(help_spell.type) or 0, 1;
    end

    if (category_label:eq('Blue Magic', true)) then
        local cast_spell, cast_spells, cast_order, cast_reason, set_count, extra_count, extra_reason = accessxi.blue_magic_current_cast_spell_for_selected(selected);
        local cast_total = cast_spells ~= nil and cast_spells:len() or 0;
        accessxi.last_magic_known_type_auto_probe = ('blueCast category="%s" set=%d extra=%d total=%d selected=%d reason="%s" extraReason="%s" path="%s"'):fmt(
            accessxi.escape_probe_log_text(category_label),
            tonumber(set_count) or 0,
            tonumber(extra_count) or 0,
            cast_total,
            selected,
            accessxi.escape_probe_log_text(cast_reason or ''),
            accessxi.escape_probe_log_text(extra_reason or ''),
            accessxi.escape_probe_log_text(cast_order ~= nil and tostring(cast_order.path or '') or ''));
        if (cast_spell ~= nil) then
            return cast_spell,
                desc,
                row0,
                row1,
                tonumber(cast_spell.id) or 0,
                1,
                selected <= (tonumber(set_count) or 0) and 'native-blue-set-mix' or 'native-blue-unbridled-mix',
                rendered_label,
                category_label,
                tonumber(cast_spell.type) or 6,
                cast_total;
        end
        return nil, desc, row0, row1, 0, 0, 'native-blue-cast-range', rendered_label, category_label, 6, cast_total;
    end

    if (category_label ~= '') then
        local mix_category_spell, mix_category_spells, mix_category_type, mix_category_order, mix_category_reason = accessxi.magic_mix_category_spell_for_selected(category_label, selected);
        local mix_category_total = mix_category_spells ~= nil and mix_category_spells:len() or 0;
        accessxi.last_magic_known_type_auto_probe = ('mixCategory category="%s" type=%d total=%d selected=%d reason="%s" path="%s"'):fmt(
            accessxi.escape_probe_log_text(category_label),
            tonumber(mix_category_type) or 0,
            mix_category_total,
            selected,
            accessxi.escape_probe_log_text(mix_category_reason or ''),
            accessxi.escape_probe_log_text(mix_category_order ~= nil and tostring(mix_category_order.path or '') or ''));
        if (mix_category_spell ~= nil) then
            return mix_category_spell,
                desc,
                row0,
                row1,
                tonumber(mix_category_spell.id) or 0,
                1,
                'mix-magic-category',
                rendered_label,
                category_label,
                tonumber(mix_category_spell.type) or 0,
                mix_category_total;
        end
        if (category_label:eq('Blue Magic', true)) then
            return nil, desc, row0, row1, 0, 0, 'mix-magic-category-range', rendered_label, category_label, tonumber(mix_category_type) or tonumber(category_type) or 0, mix_category_total;
        end
        if (category_label:eq('Trust Magic', true)) then
            local trust_known_total = category_spells ~= nil and category_spells:len() or 0;
            accessxi.last_magic_known_type_auto_probe = ('trustMagic category="%s" type=%d known=%d mixTotal=%d selected=%d reason="unverified-native-row; sorted-known-fallback-blocked"'):fmt(
                accessxi.escape_probe_log_text(category_label),
                tonumber(category_type) or tonumber(mix_category_type) or 8,
                trust_known_total,
                mix_category_total,
                selected);
            return nil, desc, row0, row1, 0, 0, 'trust-magic-category-unverified', rendered_label, category_label, tonumber(category_type) or tonumber(mix_category_type) or 8, trust_known_total;
        end
    end

    local category_spell, category_spells, category_label, category_type = accessxi.magic_category_spell_for_selected(selected);
    if (category_label ~= '') then
        local category_total = category_spells ~= nil and category_spells:len() or 0;
        accessxi.last_magic_known_type_auto_probe = ('categoryList category="%s" type=%d known=%d selected=%d'):fmt(
            accessxi.escape_probe_log_text(category_label),
            tonumber(category_type) or 0,
            category_total,
            selected);
        if (category_spell ~= nil) then
            return category_spell,
                desc,
                row0,
                row1,
                tonumber(category_spell.id) or 0,
                1,
                'known-magic-category',
                rendered_label,
                category_label,
                tonumber(category_spell.type) or 0,
                category_total;
        end
        return nil, desc, row0, row1, 0, 0, 'known-magic-category-range', rendered_label, category_label, tonumber(category_type) or 0, category_total;
    end

    accessxi.last_magic_known_type_auto_probe = ('knownMagicList selected=%d reason="unverified-native-row; sorted-known-fallback-blocked" rendered="%s"'):fmt(
        selected,
        accessxi.escape_probe_log_text(rendered_label or ''));
    return nil, desc, row0, row1, 0, rendered_count or 0, 'magic-list-unverified', rendered_label, '', 0, 0;
end

function accessxi.magic_probe_offsets(label, ptr, offsets)
    local parts = T{};
    ptr = tonumber(ptr) or 0;
    if (not accessxi.is_probe_pointer(ptr)) then
        return '';
    end

    for _, off in ipairs(offsets) do
        off = tonumber(off) or 0;
        local value = read_u32(ptr + off) or 0;
        parts:append(('%s+%03X=%08X'):fmt(tostring(label or ''), off, value));
    end
    return parts:concat(' ');
end

function accessxi.magic_probe_u16_offsets(label, ptr, offsets)
    local parts = T{};
    ptr = tonumber(ptr) or 0;
    if (not accessxi.is_probe_pointer(ptr)) then
        return '';
    end

    for _, off in ipairs(offsets) do
        off = tonumber(off) or 0;
        local value = read_u16(ptr + off) or 0;
        local name = '';
        local info = accessxi.magic_spell_resource_info(value);
        if (info ~= nil and tostring(info.name or '') ~= '') then
            name = ':' .. accessxi.escape_probe_log_text(info.name or '');
        end
        parts:append(('%s+%03X=%d%s'):fmt(tostring(label or ''), off, value, name));
    end
    return parts:concat(' ');
end

function accessxi.magic_known_window_probe(selected)
    local category = accessxi.magic_current_category_label();
    local spells, wanted_type = accessxi.magic_known_spell_list_for_category(category);
    selected = tonumber(selected) or 0;
    if (spells == nil or spells:len() <= 0 or selected <= 0) then
        return ('category="%s" type=%d known=%d window=""'):fmt(
            accessxi.escape_probe_log_text(category),
            tonumber(wanted_type) or 0,
            spells ~= nil and spells:len() or 0);
    end

    local parts = T{};
    for idx = math.max(1, selected - 2), math.min(spells:len(), selected + 2) do
        local spell = spells[idx];
        parts:append(('%d:%d:%s'):fmt(
            idx,
            tonumber(spell.id) or 0,
            accessxi.escape_probe_log_text(spell.name or '')));
    end
    return ('category="%s" type=%d known=%d window="%s"'):fmt(
        accessxi.escape_probe_log_text(category),
        tonumber(wanted_type) or 0,
        spells:len(),
        parts:concat(' | '));
end

function accessxi.magic_known_category_counts_probe(selected)
    selected = tonumber(selected) or 0;
    local labels = T{ 'White Magic', 'Black Magic', 'Summoning Magic', 'Ninjutsu', 'Songs', 'Blue Magic', 'Geomancy', 'Trust Magic' };
    local parts = T{};
    for _, label in ipairs(labels) do
        local spells, wanted_type = accessxi.magic_known_spell_list_for_category(label);
        local selected_name = '';
        if (selected > 0 and spells ~= nil and selected <= spells:len()) then
            selected_name = tostring(spells[selected].name or '');
        end
        parts:append(('%s:type%d:known%d:selected="%s"'):fmt(
            accessxi.escape_probe_log_text(label),
            tonumber(wanted_type) or 0,
            spells ~= nil and spells:len() or 0,
            accessxi.escape_probe_log_text(selected_name)));
    end
    return parts:concat(' | ');
end

function accessxi.magic_child20_spell_id(child20, index)
    child20 = tonumber(child20) or 0;
    index = tonumber(index) or 0;
    if (index <= 0 or not accessxi.is_probe_pointer(child20)) then
        return 0, 0;
    end

    local offset = 0x08 + ((index - 1) * 0x08);
    local id = read_u32(child20 + offset) or 0;
    if (id <= 0 or id > 2048) then
        return 0, offset;
    end
    return id, offset;
end

function accessxi.magic_child20_known_ordinal_slots(child20, player)
    child20 = tonumber(child20) or 0;
    local now = tick();
    if (not accessxi.is_probe_pointer(child20) or player == nil) then
        return T{};
    end

    local cache_key = ('0x%08X'):fmt(child20);
    if (accessxi.magic_child20_known_slots_cache ~= nil
        and tostring(accessxi.magic_child20_known_slots_cache_key or '') == cache_key
        and (now - (tonumber(accessxi.magic_child20_known_slots_cache_tick) or 0)) < 1000) then
        return accessxi.magic_child20_known_slots_cache;
    end

    local slots = T{};
    for index = 1, 2048 do
        local id, offset = accessxi.magic_child20_spell_id(child20, index);
        if (id > 0) then
            local info = accessxi.magic_spell_resource_info(id);
            if (info ~= nil and safe_call(function () return player:HasSpell(id); end, false) == true) then
                slots:append(T{ ordinal = slots:len() + 1, index = index, offset = offset, id = id, info = info });
            end
        end
    end

    for _, slot in ipairs(slots) do
        slot.total = slots:len();
    end

    accessxi.magic_child20_known_slots_cache = slots;
    accessxi.magic_child20_known_slots_cache_key = cache_key;
    accessxi.magic_child20_known_slots_cache_tick = now;
    return slots;
end

function accessxi.magic_child20_known_ordinal_slot(child20, ordinal, player)
    ordinal = tonumber(ordinal) or 0;
    if (ordinal <= 0) then
        return nil;
    end

    local slots = accessxi.magic_child20_known_ordinal_slots(child20, player);
    if (slots ~= nil and ordinal <= slots:len()) then
        return slots[ordinal];
    end
    return nil;
end

function accessxi.magic_child20_known_ordinal_window(child20, selected, player)
    selected = tonumber(selected) or 0;
    if (selected <= 0 or player == nil) then
        return '';
    end

    local slots = accessxi.magic_child20_known_ordinal_slots(child20, player);
    local parts = T{};
    for ordinal = math.max(1, selected - 3), selected + 3 do
        local slot = (slots ~= nil and ordinal <= slots:len()) and slots[ordinal] or nil;
        if (slot ~= nil) then
            parts:append(('%d=>idx%d:+%03X=%d:%s'):fmt(
                ordinal,
                tonumber(slot.index) or 0,
                tonumber(slot.offset) or 0,
                tonumber(slot.id) or 0,
                accessxi.escape_probe_log_text(slot.info ~= nil and slot.info.name or '')));
        else
            parts:append(('%d=>none'):fmt(ordinal));
        end
    end
    return parts:concat(' | ');
end

function accessxi.magic_child20_known_ordinal_probe(child, selected)
    child = tonumber(child) or 0;
    selected = tonumber(selected) or 0;
    if (selected <= 0 or not accessxi.is_probe_pointer(child)) then
        return '';
    end

    local child20 = read_u32(child + 0x20) or 0;
    local player = safe_call(function () return AshitaCore:GetMemoryManager():GetPlayer(); end, nil);
    local slots = accessxi.magic_child20_known_ordinal_slots(child20, player);
    local current = '';
    local slot = (slots ~= nil and selected <= slots:len()) and slots[selected] or nil;
    if (slot ~= nil and slot.info ~= nil) then
        current = ('%d=>idx%d:+%03X=%d:%s'):fmt(
            selected,
            tonumber(slot.index) or 0,
            tonumber(slot.offset) or 0,
            tonumber(slot.id) or 0,
            accessxi.escape_probe_log_text(slot.info.name or ''));
    else
        current = ('%d=>none'):fmt(selected);
    end

    return ('child20=0x%08X knownTotal=%d current="%s" window="%s"'):fmt(
        child20,
        slots ~= nil and slots:len() or 0,
        current,
        accessxi.magic_child20_known_ordinal_window(child20, selected, player));
end

function accessxi.magic_model_map_probe(menu_name, title, child, selected, count)
    if (not tostring(menu_name or ''):eq('menu    magic', true)) then
        return;
    end

    selected = tonumber(selected) or 0;
    count = tonumber(count) or 0;
    child = tonumber(child) or 0;
    if (selected <= 0 or not accessxi.is_probe_pointer(child)) then
        return;
    end

    local child20 = read_u32(child + 0x20) or 0;
    local player = safe_call(function () return AshitaCore:GetMemoryManager():GetPlayer(); end, nil);
    local main_job = tonumber(player ~= nil and safe_call(function () return player:GetMainJob(); end, 0) or 0) or 0;
    local main_level = tonumber(player ~= nil and safe_call(function () return player:GetMainJobLevel(); end, 0) or 0) or 0;
    local sub_job = tonumber(player ~= nil and safe_call(function () return player:GetSubJob(); end, 0) or 0) or 0;
    local sub_level = tonumber(player ~= nil and safe_call(function () return player:GetSubJobLevel(); end, 0) or 0) or 0;

    local function format_slot(index, include_flags)
        local id, offset = accessxi.magic_child20_spell_id(child20, index);
        local info = accessxi.magic_spell_resource_info(id);
        local name = (info ~= nil) and tostring(info.name or '') or '';
        local known = false;
        local usable = false;
        local main_req = -1;
        local sub_req = -1;
        if (player ~= nil and info ~= nil) then
            known = safe_call(function () return player:HasSpell(id); end, false) == true;
            usable, main_req, sub_req = accessxi.magic_spell_currently_usable(player, info, main_job, main_level, sub_job, sub_level);
        end

        if (include_flags == true) then
            return ('%d:+%03X=%d:%s:t%d:i%d:s%d:mp%d:known%d:usable%d:req%d/%d'):fmt(
                index,
                tonumber(offset) or 0,
                id,
                accessxi.escape_probe_log_text(name),
                info ~= nil and (tonumber(info.type) or 0) or 0,
                info ~= nil and (tonumber(info.index) or 0) or 0,
                info ~= nil and (tonumber(info.sort_id) or 0) or 0,
                info ~= nil and (tonumber(info.mp) or 0) or 0,
                known and 1 or 0,
                usable and 1 or 0,
                tonumber(main_req) or -1,
                tonumber(sub_req) or -1);
        end

        return ('%d:%d:%s:%d%d'):fmt(
            index,
            id,
            accessxi.escape_probe_log_text(name),
            known and 1 or 0,
            usable and 1 or 0);
    end

    local current_id, current_offset = accessxi.magic_child20_spell_id(child20, selected);
    local current_info = accessxi.magic_spell_resource_info(current_id);
    local current_known = false;
    local current_usable = false;
    if (player ~= nil and current_info ~= nil) then
        current_known = safe_call(function () return player:HasSpell(current_id); end, false) == true;
        current_usable = accessxi.magic_spell_currently_usable(player, current_info, main_job, main_level, sub_job, sub_level);
    end
    local ordinal_slot = accessxi.magic_child20_known_ordinal_slot(child20, selected, player);
    local ordinal_text = 'none';
    if (ordinal_slot ~= nil) then
        ordinal_text = ('idx%d:+%03X=%d:%s'):fmt(
            tonumber(ordinal_slot.index) or 0,
            tonumber(ordinal_slot.offset) or 0,
            tonumber(ordinal_slot.id) or 0,
            accessxi.escape_probe_log_text(ordinal_slot.info ~= nil and ordinal_slot.info.name or ''));
    end

    local window = T{};
    for idx = math.max(1, selected - 3), selected + 3 do
        window:append(format_slot(idx, true));
    end

    local first = T{};
    local first_count = math.min(32, math.max(14, selected + 8));
    for idx = 1, first_count do
        first:append(format_slot(idx, false));
    end

    log_line(('magicmodelmap menu="%s" title="%s" selected=%d count=%d child=0x%08X child20=0x%08X cursor0=%d prev0=%d jobs=%d/%d,%d/%d current="+%03X=%d:%s:known%d:usable%d" ordinalCurrent="%s" window="%s" ordinalWindow="%s" first="%s"'):fmt(
        tostring(menu_name or ''),
        accessxi.escape_probe_log_text(title or ''),
        selected,
        count,
        child,
        child20,
        read_u32(child + 0x30) or 0,
        read_u32(child + 0x34) or 0,
        main_job,
        main_level,
        sub_job,
        sub_level,
        tonumber(current_offset) or 0,
        current_id,
        accessxi.escape_probe_log_text(current_info ~= nil and current_info.name or ''),
        current_known and 1 or 0,
        current_usable and 1 or 0,
        ordinal_text,
        window:concat(' | '),
        accessxi.magic_child20_known_ordinal_window(child20, selected, player),
        first:concat(' | ')));
end

function accessxi.log_magic_scroll_probe(menu_name, title, obj, child, entry, selected, count, desc, row0, row1)
    if (not tostring(menu_name or ''):eq('menu    magic', true)) then
        return;
    end

    selected = tonumber(selected) or 0;
    count = tonumber(count) or 0;
    obj = tonumber(obj) or 0;
    child = tonumber(child) or 0;
    entry = tonumber(entry) or 0;
    desc = tonumber(desc) or 0;
    row0 = tonumber(row0) or 0;
    row1 = tonumber(row1) or 0;
    local key = ('%s:%d:%d:0x%08X:0x%08X:0x%08X:0x%08X'):fmt(
        tostring(menu_name or ''),
        selected,
        count,
        obj,
        child,
        entry,
        desc);
    if (key == tostring(accessxi.last_magic_scroll_probe_key or '')) then
        return;
    end
    accessxi.last_magic_scroll_probe_key = key;
    local rendered_label = accessxi.magic_rendered_row_text(entry, selected);
    log_line(('magicrowprobe menu="%s" title="%s" selected=%d count=%d entry=0x%08X desc=0x%08X row0=0x%08X row1=0x%08X rendered="%s" renderCells="%s" index="%s" mix="%s" usable="%s" known="%s" entry24="%s" entryBytes="%s" shortcut="%s" %s'):fmt(
        tostring(menu_name or ''),
        accessxi.escape_probe_log_text(title or ''),
        selected,
        count,
        entry,
        desc,
        row0,
        row1,
        accessxi.escape_probe_log_text(rendered_label),
        accessxi.escape_probe_log_text(accessxi.last_magic_render_cells or ''),
        accessxi.escape_probe_log_text(accessxi.magic_menu_index_probe(obj, child)),
        accessxi.escape_probe_log_text_wide(accessxi.magic_mix_order_probe(selected)),
        accessxi.escape_probe_log_text_wide(accessxi.magic_usable_order_probe(selected)),
        accessxi.escape_probe_log_text_wide(accessxi.magic_known_all_probe(selected)),
        accessxi.escape_probe_log_text_wide(accessxi.magic_entry_id_decode_for_offset(entry, 0x24)),
        accessxi.escape_probe_log_text_wide(accessxi.format_probe_bytes(entry, 0x20, 0x50)),
        accessxi.escape_probe_log_text(accessxi.magic_shortcut_native_probe(selected, count)),
        accessxi.magic_entry_id_decode_probe(entry)));
end

function accessxi.log_magic_visible_probe(menu_name, title, obj, child, entry, selected, count, reason)
    if (not tostring(menu_name or ''):eq('menu    magic', true)) then
        return;
    end

    selected = tonumber(selected) or 0;
    count = tonumber(count) or 0;
    obj = tonumber(obj) or 0;
    child = tonumber(child) or 0;
    entry = tonumber(entry) or 0;
    local key = ('%s:%d:%d:0x%08X:0x%08X:0x%08X:%s'):fmt(
        tostring(menu_name or ''),
        selected,
        count,
        obj,
        child,
        entry,
        tostring(reason or ''));
    if (key == tostring(accessxi.last_magic_visible_probe_key or '')) then
        return;
    end
    accessxi.last_magic_visible_probe_key = key;

    accessxi.magic_visible_probe_count = (tonumber(accessxi.magic_visible_probe_count) or 0) + 1;
    if (accessxi.magic_visible_probe_count > 12) then
        return;
    end

    accessxi.menu_dump_sequence = (tonumber(accessxi.menu_dump_sequence) or 0) + 1;
    local seq = accessxi.menu_dump_sequence;
    local target = safe_call(function () return AshitaCore:GetMemoryManager():GetTarget(); end, nil);
    local window_name = target ~= nil and accessxi.survival_guide_text(safe_call(function () return target:GetWindowName(); end, '') or '') or '';
    local loaded = target ~= nil and (tonumber(safe_call(function () return target:GetWindowIsWindowLoaded(); end, -1)) or -1) or -1;
    local help_title_ptr = target ~= nil and (tonumber(safe_call(function () return target:GetWindowHelpTitle(); end, 0)) or 0) or 0;
    local help_ptr = target ~= nil and (tonumber(safe_call(function () return target:GetWindowHelpString(); end, 0)) or 0) or 0;
    local ank_num = target ~= nil and (tonumber(safe_call(function () return target:GetWindowAnkNum(); end, -1)) or -1) or -1;
    local ank_x = target ~= nil and (tonumber(safe_call(function () return target:GetWindowAnkX(); end, -1)) or -1) or -1;
    local ank_y = target ~= nil and (tonumber(safe_call(function () return target:GetWindowAnkY(); end, -1)) or -1) or -1;
    local sub = target ~= nil and (tonumber(safe_call(function () return target:GetWindowSub(); end, -1)) or -1) or -1;
    local sub_x = target ~= nil and (tonumber(safe_call(function () return target:GetWindowSubAnkX(); end, -1)) or -1) or -1;
    local sub_y = target ~= nil and (tonumber(safe_call(function () return target:GetWindowSubAnkY(); end, -1)) or -1) or -1;

    log_line(('magicvisprobe begin seq=%d reason="%s" menu="%s" title="%s" selected=%d count=%d obj=0x%08X child=0x%08X entry=0x%08X loaded=%d win="%s" helpTitlePtr=0x%08X helpTitle="%s" helpPtr=0x%08X help="%s" ank=%d ankXY=(%d,%d) sub=%d subXY=(%d,%d) index="%s" mix="%s" objIdx="%s" childIdx="%s" objD00="%s" childD00="%s" entryD00="%s"'):fmt(
        seq,
        accessxi.escape_probe_log_text(reason or ''),
        tostring(menu_name or ''),
        accessxi.escape_probe_log_text(title or ''),
        selected,
        count,
        obj,
        child,
        entry,
        loaded,
        accessxi.escape_probe_log_text(window_name),
        help_title_ptr,
        accessxi.escape_probe_log_text(read_probe_string(help_title_ptr, 180)),
        help_ptr,
        accessxi.escape_probe_log_text(read_probe_string(help_ptr, 320)),
        ank_num,
        ank_x,
        ank_y,
        sub,
        sub_x,
        sub_y,
        accessxi.escape_probe_log_text(accessxi.magic_menu_index_probe(obj, child)),
        accessxi.escape_probe_log_text_wide(accessxi.magic_mix_order_probe(selected)),
        accessxi.escape_probe_log_text(accessxi.format_probe_index_fields(obj, 0x00, 0x90)),
        accessxi.escape_probe_log_text(accessxi.format_probe_index_fields(child, 0x00, 0x90)),
        accessxi.escape_probe_log_text(accessxi.format_probe_dwords(obj, 0x00, 16)),
        accessxi.escape_probe_log_text(accessxi.format_probe_dwords(child, 0x00, 16)),
        accessxi.escape_probe_log_text(accessxi.format_probe_dwords(entry, 0x00, 16))));

    do
        local groups, desc, row0, row1 = accessxi.magic_spell_candidate_details_from_entry(entry, false);
        log_line(('magicvisprobe row seq=%d selected=%d entry=0x%08X desc=0x%08X row0=0x%08X row1=0x%08X entry24=0x%08X descD00="%s" row0D00="%s" row1D00="%s" candidates="%s"'):fmt(
            seq,
            selected,
            entry,
            tonumber(desc) or 0,
            tonumber(row0) or 0,
            tonumber(row1) or 0,
            accessxi.is_probe_pointer(entry) and (read_u32(entry + 0x24) or 0) or 0,
            accessxi.escape_probe_log_text(accessxi.format_probe_dwords(desc, 0x00, 16)),
            accessxi.escape_probe_log_text(accessxi.format_probe_dwords(row0, 0x00, 16)),
            accessxi.escape_probe_log_text(accessxi.format_probe_dwords(row1, 0x00, 16)),
            accessxi.escape_probe_log_text_wide(accessxi.format_magic_spell_candidate_groups(groups))));
        log_line(('magicvisprobe end seq=%d'):fmt(seq));
        return;
    end

    accessxi.menu_dump_textptr_budget = 28;
    accessxi.log_probe_short_text_runs(seq, 'magic.obj', obj, 0x340, 3, 18);
    accessxi.log_probe_pointer_text_targets(seq, 'magic.obj', obj, 0x00, 0x17C, 10);
    accessxi.log_probe_short_text_runs(seq, 'magic.child', child, 0x340, 3, 18);
    accessxi.log_probe_pointer_text_targets(seq, 'magic.child', child, 0x00, 0x17C, 10);
    accessxi.log_probe_short_text_runs(seq, 'magic.entry', entry, 0x200, 3, 12);
    accessxi.log_probe_pointer_text_targets(seq, 'magic.entry', entry, 0x00, 0xFC, 8);

    if (target ~= nil and ank_num > 0) then
        for i = 0, math.min(ank_num - 1, 11) do
            local shape = tonumber(safe_call(function () return target:GetWindowAnkShape(i); end, 0)) or 0;
            if (accessxi.is_probe_pointer(shape)) then
                log_line(('magicvisprobe seq=%d shape%d ptr=0x%08X dwords="%s" idx="%s"'):fmt(
                    seq,
                    i,
                    shape,
                    accessxi.escape_probe_log_text(accessxi.format_probe_dwords(shape, 0x00, 12)),
                    accessxi.escape_probe_log_text(accessxi.format_probe_index_fields(shape, 0x00, 0x90))));
                accessxi.log_probe_short_text_runs(seq, ('magic.shape%d'):fmt(i), shape, 0x260, 3, 10);
                accessxi.log_probe_pointer_text_targets(seq, ('magic.shape%d'):fmt(i), shape, 0x00, 0xFC, 6);
            end
        end
    end

    accessxi.menu_dump_textptr_budget = nil;
    log_line(('magicvisprobe end seq=%d'):fmt(seq));
end

function accessxi.log_magic_spell_candidate_probe(menu_name, selected, entry, desc)
    local key = ('%s:%d:0x%08X:0x%08X'):fmt(
        tostring(menu_name or ''),
        0,
        tonumber(entry) or 0,
        tonumber(desc) or 0);
    if (accessxi.magic_spell_probe_seen == nil) then
        accessxi.magic_spell_probe_seen = {};
    end
    if (accessxi.magic_spell_probe_seen[key] == true) then
        return;
    end
    accessxi.magic_spell_probe_seen[key] = true;

    local groups, _, row0, row1 = accessxi.magic_spell_candidate_details_from_entry(entry, false);
    local rendered_label = accessxi.magic_rendered_row_text(entry, selected);
    local category = accessxi.magic_current_category_label();
    local spells, wanted_type = accessxi.magic_known_spell_list_for_category(category);
    log_line(('magicspellprobe menu="%s" selected=%d entry=0x%08X desc=0x%08X row0=0x%08X row1=0x%08X category="%s" type=%d known=%d rendered="%s" renderCells="%s" knownPreview="%s" allSources="%s"'):fmt(
        tostring(menu_name or ''),
        tonumber(selected) or 0,
        tonumber(entry) or 0,
        tonumber(desc) or 0,
        tonumber(row0) or 0,
        tonumber(row1) or 0,
        accessxi.escape_probe_log_text(category),
        tonumber(wanted_type) or 0,
        spells ~= nil and spells:len() or 0,
        accessxi.escape_probe_log_text(rendered_label),
        accessxi.escape_probe_log_text(accessxi.last_magic_render_cells or ''),
        accessxi.magic_known_spell_preview(spells),
        accessxi.format_magic_spell_candidate_groups(groups)));
end

function accessxi.mount_resource_string(table_name, id)
    id = tonumber(id) or 0;
    if (id <= 0 or id > 4096) then
        return '';
    end

    local resources = AshitaCore:GetResourceManager();
    if (resources == nil) then
        return '';
    end

    local text = safe_call(function () return resources:GetString(table_name, id); end, '') or '';
    text = accessxi.plain_native_menu_label(accessxi.survival_guide_text(text));
    if (text == '' or text:eq('Unknown', true) or #text > 160) then
        return '';
    end

    return text;
end

function accessxi.keyitem_resource_string(id)
    id = tonumber(id) or 0;
    if (id <= 0 or id > 4096) then
        return '';
    end

    local resources = AshitaCore:GetResourceManager();
    if (resources == nil) then
        return '';
    end

    local text = safe_call(function () return resources:GetString('keyitems.names', id); end, '') or '';
    text = accessxi.plain_native_menu_label(accessxi.survival_guide_text(text));
    if (text == '' or text:eq('Unknown', true) or #text > 160) then
        return '';
    end

    return text;
end

function accessxi.mount_name_from_keyitem(keyitem_id, mount_id)
    mount_id = tonumber(mount_id) or 0;
    if (mount_id > 0) then
        return accessxi.mount_resource_string('mounts.names', mount_id);
    end

    local text = accessxi.keyitem_resource_string(keyitem_id);
    text = text:gsub('^[^%a]+', ''):gsub('%s+companion$', ''):gsub('%s+whistle$', ''):gsub('%s+key$', ''):trim();
    return text;
end

function accessxi.mount_owned_list()
    local now = tick();
    if (accessxi.mount_owned_cache ~= nil and (now - (accessxi.mount_owned_cache_tick or 0)) < 1000) then
        return accessxi.mount_owned_cache;
    end

    local mounts = T{};
    local mm = safe_call(function () return AshitaCore:GetMemoryManager(); end, nil);
    local player = (mm ~= nil) and safe_call(function () return mm:GetPlayer(); end, nil) or nil;
    if (player == nil) then
        accessxi.mount_owned_cache = mounts;
        accessxi.mount_owned_cache_tick = now;
        return mounts;
    end

    for mount_id = 0, 96 do
        local keyitem_id = 3072 + mount_id;
        local has = safe_call(function () return player:HasKeyItem(keyitem_id); end, false);
        if (has == true or has == 1) then
            local native_mount_name = (mount_id > 0) and accessxi.mount_resource_string('mounts.names', mount_id) or '';
            local keyitem_name = accessxi.keyitem_resource_string(keyitem_id);
            if (native_mount_name ~= '' or keyitem_name:contains('companion', true) or keyitem_name:contains('whistle', true) or keyitem_name:contains(' key', true)) then
                local name = accessxi.mount_name_from_keyitem(keyitem_id, mount_id);
                if (name ~= '') then
                    local description = '';
                    if (mount_id > 0) then
                        description = accessxi.mount_resource_string('mounts.descriptions', mount_id);
                    end
                    mounts:append(T{ id = mount_id, keyitem = keyitem_id, name = name, description = description });
                end
            end
        end
    end

    accessxi.mount_owned_cache = mounts;
    accessxi.mount_owned_cache_tick = now;
    return mounts;
end

function accessxi.mount_owned_label_for_selected(selected)
    selected = tonumber(selected) or 0;
    if (selected <= 0) then
        return '', '', 0, 0, 0;
    end

    local mounts = accessxi.mount_owned_list();
    local row = mounts[selected];
    if (row == nil) then
        return '', '', 0, 0, mounts:len();
    end

    return tostring(row.name or ''), tostring(row.description or ''), tonumber(row.id) or 0, tonumber(row.keyitem) or 0, mounts:len();
end

function accessxi.mount_resource_table_probe_once()
    if (accessxi.mount_resource_table_probe_done == true) then
        return;
    end
    accessxi.mount_resource_table_probe_done = true;

    local parts = T{};
    for id = 1, 512 do
        local name = accessxi.mount_resource_string('mounts.names', id);
        if (name ~= '') then
            parts:append(('%d:%s'):fmt(id, accessxi.escape_probe_log_text(name)));
        end
    end

    log_line(('mounttableprobe names="%s"'):fmt(parts:concat(' | ')));
end

function accessxi.mount_row_code_candidate_ids(row_code, selected)
    row_code = tonumber(row_code) or 0;
    selected = tonumber(selected) or 0;

    local values = T{};
    local seen = {};
    local function add(source, value)
        value = tonumber(value) or 0;
        if (value <= 0 or value > 4096) then
            return;
        end

        local key = tostring(value);
        if (seen[key]) then
            return;
        end
        seen[key] = true;
        values:append(T{ source = tostring(source or ''), value = value });
    end

    local b0 = bit.band(row_code, 0xFF);
    local b1 = bit.band(bit.rshift(row_code, 8), 0xFF);
    local low16 = bit.band(row_code, 0xFFFF);
    local low_swap = bit.bor(bit.lshift(bit.band(low16, 0xFF), 8), bit.rshift(low16, 8));

    add('selected', selected);
    add('b0', b0);
    add('b1', b1);
    add('low16', low16);
    add('lowSwap', low_swap);
    add('b1-128', b1 - 128);
    add('b1-160', b1 - 160);
    add('b1-192', b1 - 192);
    add('b1-200', b1 - 200);
    add('b1-204', b1 - 204);
    add('b1-206', b1 - 206);
    add('b1-240', b1 - 240);
    add('b1-242', b1 - 242);
    add('b1-244', b1 - 244);

    return values;
end

function accessxi.mount_candidate_probe_text(row_code, selected)
    local parts = T{};
    for _, candidate in ipairs(accessxi.mount_row_code_candidate_ids(row_code, selected)) do
        local name = accessxi.mount_resource_string('mounts.names', candidate.value);
        if (name ~= '') then
            parts:append(('%s=%d:%s'):fmt(
                tostring(candidate.source or ''),
                tonumber(candidate.value) or 0,
                accessxi.escape_probe_log_text(name)));
        end
    end

    return parts:concat(' | ');
end

function accessxi.mount_probe_id_runs(ptr, length)
    ptr = tonumber(ptr) or 0;
    length = tonumber(length) or 0;
    if (not accessxi.is_probe_pointer(ptr) or length <= 0) then
        return '';
    end

    local runs = T{};
    local start_off = -1;
    local current = T{};
    local function flush()
        if (start_off >= 0 and current:len() >= 3 and runs:len() < 10) then
            runs:append(('+%03X=%s'):fmt(start_off, current:concat(',')));
        end
        start_off = -1;
        current = T{};
    end

    for off = 0, length - 1 do
        local id = read_u8(ptr + off) or 0;
        local name = accessxi.mount_resource_string('mounts.names', id);
        if (name ~= '') then
            if (start_off < 0) then
                start_off = off;
            end
            current:append(('%d:%s'):fmt(id, name));
        else
            flush();
        end
    end
    flush();

    return runs:concat(' | ');
end

function accessxi.mount_probe_pointer_id_runs(ptr)
    ptr = tonumber(ptr) or 0;
    if (not accessxi.is_probe_pointer(ptr)) then
        return '';
    end

    local parts = T{};
    local seen = {};
    for off = 0, 0x180, 4 do
        local candidate = read_u32(ptr + off) or 0;
        if (accessxi.is_probe_pointer(candidate) and seen[candidate] ~= true and parts:len() < 12) then
            seen[candidate] = true;
            local runs = accessxi.mount_probe_id_runs(candidate, 0x100);
            if (runs ~= '') then
                parts:append(('+%03X->0x%08X %s'):fmt(off, candidate, runs));
            end
        end
    end

    return parts:concat(' || ');
end

function accessxi.mount_known_id_hits(ptr, length)
    ptr = tonumber(ptr) or 0;
    length = tonumber(length) or 0;
    if (not accessxi.is_probe_pointer(ptr) or length <= 0) then
        return '';
    end

    local hits = T{};
    local seen = {};
    local function add(off, kind, id)
        id = tonumber(id) or 0;
        if (id <= 0 or id > 512) then
            return;
        end
        local name = accessxi.mount_resource_string('mounts.names', id);
        if (name == '') then
            return;
        end
        local key = ('%03X:%s:%d'):fmt(off, kind, id);
        if (seen[key] == true) then
            return;
        end
        seen[key] = true;
        if (hits:len() < 24) then
            hits:append(('+%03X%s=%d:%s'):fmt(off, kind, id, name));
        end
    end

    for off = 0, length - 1 do
        local b = read_u8(ptr + off);
        add(off, 'b', b);
        if (off <= length - 2) then
            local lo = read_u16(ptr + off);
            add(off, 'w', lo);
        end
        if (off <= length - 4) then
            local d = read_u32(ptr + off);
            add(off, 'd', d);
        end
    end

    return hits:concat(' ');
end

function accessxi.log_mount_object_probe(menu_name, selected, obj, entry, child)
    obj = tonumber(obj) or 0;
    if (not accessxi.is_probe_pointer(obj)) then
        return;
    end

    local key = ('0x%08X:%d:0x%08X'):fmt(obj, tonumber(selected) or 0, tonumber(entry) or 0);
    if (key == (accessxi.last_mount_object_probe_key or '')) then
        return;
    end
    accessxi.last_mount_object_probe_key = key;

    log_line(('mountobjprobe menu="%s" selected=%d obj=0x%08X entry=0x%08X child=0x%08X obj000="%s" obj040="%s" obj080="%s" obj0C0="%s" obj100="%s" obj140="%s" objRuns="%s" objPtrRuns="%s" childRuns="%s" entryRuns="%s"'):fmt(
        tostring(menu_name or ''),
        tonumber(selected) or 0,
        obj,
        tonumber(entry) or 0,
        tonumber(child) or 0,
        accessxi.escape_probe_log_text(accessxi.format_probe_dwords(obj, 0x00, 16)),
        accessxi.escape_probe_log_text(accessxi.format_probe_dwords(obj, 0x40, 16)),
        accessxi.escape_probe_log_text(accessxi.format_probe_dwords(obj, 0x80, 16)),
        accessxi.escape_probe_log_text(accessxi.format_probe_dwords(obj, 0xC0, 16)),
        accessxi.escape_probe_log_text(accessxi.format_probe_dwords(obj, 0x100, 16)),
        accessxi.escape_probe_log_text(accessxi.format_probe_dwords(obj, 0x140, 16)),
        accessxi.escape_probe_log_text(accessxi.mount_probe_id_runs(obj, 0x180)),
        accessxi.escape_probe_log_text(accessxi.mount_probe_pointer_id_runs(obj)),
        accessxi.escape_probe_log_text(accessxi.mount_probe_id_runs(child, 0x180)),
        accessxi.escape_probe_log_text(accessxi.mount_probe_id_runs(entry, 0x180))));
end

function accessxi.log_mount_visible_row_probe(menu_name, selected, obj, child, entry, desc)
    desc = tonumber(desc) or 0;
    selected = tonumber(selected) or 0;
    if (not accessxi.is_probe_pointer(desc) or selected <= 0 or selected > 8) then
        return;
    end

    local base = desc - ((selected - 1) * 0x14);
    if (not accessxi.is_probe_pointer(base)) then
        return;
    end

    local key = ('0x%08X:%d:0x%08X'):fmt(tonumber(obj) or 0, selected, tonumber(entry) or 0);
    if (key == (accessxi.last_mount_visible_probe_key or '')) then
        return;
    end
    accessxi.last_mount_visible_probe_key = key;

    log_line(('mountrowprobe menu="%s" selected=%d obj=0x%08X child=0x%08X entry=0x%08X desc=0x%08X base=0x%08X obj30="%s" child30="%s" child80="%s" entry20="%s" entry60="%s"'):fmt(
        tostring(menu_name or ''),
        selected,
        tonumber(obj) or 0,
        tonumber(child) or 0,
        tonumber(entry) or 0,
        desc,
        base,
        accessxi.format_probe_dwords(obj, 0x30, 12),
        accessxi.format_probe_dwords(child, 0x30, 12),
        accessxi.format_probe_dwords(child, 0x80, 12),
        accessxi.format_probe_dwords(entry, 0x20, 12),
        accessxi.format_probe_dwords(entry, 0x60, 12)));
end

function accessxi.log_mount_entry_compact_probe(menu_name, selected, count, entry, row_code, mount_id, name)
    entry = tonumber(entry) or 0;
    if (not accessxi.is_probe_pointer(entry)) then
        return;
    end

    local key = ('%s:%d:0x%08X:0x%08X'):fmt(tostring(menu_name or ''), tonumber(selected) or 0, entry, tonumber(row_code) or 0);
    if (key == (accessxi.last_mount_entry_compact_probe_key or '')) then
        return;
    end
    accessxi.last_mount_entry_compact_probe_key = key;

    log_line(('mountentrycompact menu="%s" selected=%d count=%d entry=0x%08X rowCode=0x%08X mountId=%d label="%s" e20="%s" e40="%s" e60="%s" e80="%s"'):fmt(
        tostring(menu_name or ''),
        tonumber(selected) or 0,
        tonumber(count) or 0,
        entry,
        tonumber(row_code) or 0,
        tonumber(mount_id) or 0,
        accessxi.escape_probe_log_text(name or ''),
        accessxi.format_probe_dwords(entry, 0x20, 8),
        accessxi.format_probe_dwords(entry, 0x40, 8),
        accessxi.format_probe_dwords(entry, 0x60, 8),
        accessxi.format_probe_dwords(entry, 0x80, 8)));
end

function accessxi.mount_visible_row_probe(desc, selected)
    desc = tonumber(desc) or 0;
    selected = tonumber(selected) or 0;
    if (not accessxi.is_probe_pointer(desc) or selected <= 0 or selected > 8) then
        return '';
    end

    local base = desc - ((selected - 1) * 0x14);
    if (not accessxi.is_probe_pointer(base)) then
        return '';
    end

    local rows = T{};
    for row = 1, 5 do
        local row_desc = base + ((row - 1) * 0x14);
        local row0 = read_u32(row_desc + 0x00) or 0;
        local row1 = read_u32(row_desc + 0x04) or 0;
        local row2 = read_u32(row_desc + 0x08) or 0;
        local row0_word04 = accessxi.is_probe_pointer(row0) and (read_u32(row0 + 0x04) or 0) or 0;
        local row0_word10 = accessxi.is_probe_pointer(row0) and (read_u32(row0 + 0x10) or 0) or 0;
        local row1_word08 = accessxi.is_probe_pointer(row1) and (read_u32(row1 + 0x08) or 0) or 0;
        local row1_word20 = accessxi.is_probe_pointer(row1) and (read_u32(row1 + 0x20) or 0) or 0;
        rows:append(('%d:desc=0x%08X row0=0x%08X row1=0x%08X row2=0x%08X r0+04=0x%08X r0+10=0x%08X r1+08=0x%08X r1+20=0x%08X'):fmt(
            row,
            row_desc,
            row0,
            row1,
            row2,
            row0_word04,
            row0_word10,
            row1_word08,
            row1_word20));
    end

    return rows:concat(' | ');
end

function accessxi.mount_pointer_neighborhood_probe(obj, child, entry, desc)
    local roots = T{
        T{ name = 'obj', ptr = tonumber(obj) or 0 },
        T{ name = 'child', ptr = tonumber(child) or 0 },
        T{ name = 'entry', ptr = tonumber(entry) or 0 },
        T{ name = 'desc', ptr = tonumber(desc) or 0 },
    };

    local parts = T{};
    for _, root in ipairs(roots) do
        if (accessxi.is_probe_pointer(root.ptr)) then
            local scalars = T{};
            for off = 0, 0x80, 4 do
                local v = read_i32(root.ptr + off);
                if (v ~= nil and v >= -1 and v <= 512) then
                    scalars:append(('+%03X=%d'):fmt(off, v));
                end
            end
            if (scalars:len() > 0) then
                parts:append(('%s{%s}'):fmt(root.name, scalars:concat(' ')));
            end
        end
    end

    return parts:concat(' || ');
end

function accessxi.mount_id_from_row_code(row_code)
    row_code = tonumber(row_code) or 0;
    if (bit.band(row_code, 0xFF) ~= 1) then
        return 0;
    end

    local id = bit.band(bit.rshift(row_code, 8), 0xFF);
    if (id <= 0) then
        return 0;
    end

    return id;
end

function accessxi.mount_label_from_entry(entry)
    entry = tonumber(entry) or 0;
    if (not accessxi.is_probe_pointer(entry)) then
        return '', '', 0, 0;
    end

    local row_code = read_u32(entry + 0x24) or 0;
    local mount_id = accessxi.mount_id_from_row_code(row_code);
    if (mount_id <= 0) then
        return '', '', 0, row_code;
    end

    local name = accessxi.mount_resource_string('mounts.names', mount_id);
    local description = accessxi.mount_resource_string('mounts.descriptions', mount_id);
    return name, description, mount_id, row_code;
end

function accessxi.mount_lite_field_text(ptr, offsets)
    ptr = tonumber(ptr) or 0;
    if (not accessxi.is_probe_pointer(ptr)) then
        return '';
    end

    local parts = T{};
    for _, off in ipairs(offsets or T{}) do
        off = tonumber(off) or 0;
        parts:append(('+%03X=0x%08X'):fmt(off, read_u32(ptr + off) or 0));
    end
    return parts:concat(' ');
end

function accessxi.mount_lite_id_text(value)
    value = tonumber(value) or 0;
    if (value < 0) then
        value = 0;
    end

    local low16 = bit.band(value, 0xFFFF);
    local high16 = bit.band(bit.rshift(value, 16), 0xFFFF);
    local low_swap = bit.bor(bit.lshift(bit.band(low16, 0xFF), 8), bit.rshift(low16, 8));
    local high_swap = bit.bor(bit.lshift(bit.band(high16, 0xFF), 8), bit.rshift(high16, 8));
    return ('raw=0x%08X low16=%d high16=%d lowSwap=%d highSwap=%d b0=%d b1=%d b2=%d b3=%d'):fmt(
        value,
        low16,
        high16,
        low_swap,
        high_swap,
        bit.band(value, 0xFF),
        bit.band(bit.rshift(value, 8), 0xFF),
        bit.band(bit.rshift(value, 16), 0xFF),
        bit.band(bit.rshift(value, 24), 0xFF));
end

function accessxi.log_mount_lite_probe(menu_name, selected, obj, entry, child)
    accessxi.mount_resource_table_probe_once();

    entry = tonumber(entry) or 0;
    local desc = accessxi.is_probe_pointer(entry) and (read_u32(entry + 0x0C) or 0) or 0;
    local row0 = accessxi.is_probe_pointer(desc) and (read_u32(desc + 0x00) or 0) or 0;
    local row1 = accessxi.is_probe_pointer(desc) and (read_u32(desc + 0x04) or 0) or 0;
    local row2 = accessxi.is_probe_pointer(desc) and (read_u32(desc + 0x08) or 0) or 0;
    local row_code = accessxi.is_probe_pointer(entry) and (read_u32(entry + 0x24) or 0) or 0;
    local direct_label = accessxi.is_probe_pointer(entry) and accessxi.plain_native_menu_label(read_probe_string(read_u32(entry + 0x44) or 0)) or '';
    local direct_help = accessxi.is_probe_pointer(entry) and accessxi.plain_native_menu_label(read_probe_string(read_u32(entry + 0x40) or 0)) or '';

    local mount_name, mount_description, mount_id = accessxi.mount_label_from_entry(entry);
    accessxi.log_mount_visible_row_probe(menu_name, selected, obj, child, entry, desc);

    log_line(('mountliteprobe menu="%s" selected=%d obj=0x%08X entry=0x%08X child=0x%08X desc=0x%08X row0=0x%08X row1=0x%08X row2=0x%08X mountId=%d mountName="%s" mountDesc="%s" candidates="%s" id="%s" entryFields="%s" descFields="%s" visibleRows="%s" nearby="%s" row0="%s" row1="%s" childFields="%s" directLabel="%s" directHelp="%s"'):fmt(
        tostring(menu_name or ''),
        tonumber(selected) or 0,
        tonumber(obj) or 0,
        entry,
        tonumber(child) or 0,
        tonumber(desc) or 0,
        tonumber(row0) or 0,
        tonumber(row1) or 0,
        tonumber(row2) or 0,
        tonumber(mount_id) or 0,
        accessxi.escape_probe_log_text(mount_name),
        accessxi.escape_probe_log_text(mount_description),
        accessxi.escape_probe_log_text(accessxi.mount_candidate_probe_text(row_code, selected)),
        accessxi.mount_lite_id_text(row_code),
        accessxi.escape_probe_log_text(accessxi.mount_lite_field_text(entry, T{ 0x00, 0x04, 0x0C, 0x10, 0x14, 0x24, 0x28, 0x2C, 0x30, 0x34, 0x3C, 0x40, 0x44, 0x58, 0x5C, 0x60 })),
        accessxi.escape_probe_log_text(accessxi.mount_lite_field_text(desc, T{ 0x00, 0x04, 0x08, 0x0C, 0x10, 0x14, 0x18, 0x1C, 0x20 })),
        accessxi.escape_probe_log_text(accessxi.mount_visible_row_probe(desc, selected)),
        accessxi.escape_probe_log_text(accessxi.mount_pointer_neighborhood_probe(obj, child, entry, desc)),
        accessxi.escape_probe_log_text(accessxi.format_probe_dwords(row0, 0, 18)),
        accessxi.escape_probe_log_text(accessxi.format_probe_dwords(row1, 0, 18)),
        accessxi.escape_probe_log_text(accessxi.mount_lite_field_text(child, T{ 0x00, 0x08, 0x0C, 0x14, 0x1C, 0x20, 0x24, 0x54, 0x58, 0x5C, 0x60, 0x64, 0x6C })),
        accessxi.escape_probe_log_text(direct_label),
        accessxi.escape_probe_log_text(direct_help)));
end

function accessxi.mount_menu_speech(menu_name, title, selected, count, entry)
    selected = tonumber(selected) or 0;
    count = tonumber(count) or 0;

    local name, description, mount_id, keyitem_id, owned_count = accessxi.mount_owned_label_for_selected(selected);
    local row_code = accessxi.is_probe_pointer(entry) and (read_u32(entry + 0x24) or 0) or 0;

    if (name == '') then
        log_state(('state mount native-missing menu="%s" title="%s" select=%d count=%d owned=%d entry=0x%08X rowCode=0x%08X mountId=%d'):fmt(
            tostring(menu_name or ''),
            tostring(title or ''),
            selected,
            count,
            tonumber(owned_count) or 0,
            tonumber(entry) or 0,
            tonumber(row_code) or 0,
            tonumber(mount_id) or 0));
        return nil;
    end

    local text = name;
    if (description ~= '' and not description:eq(name, true)) then
        text = ('%s. %s'):fmt(name, accessxi.sentence_fragment(description));
    end

    accessxi.last_native_menu_name = tostring(menu_name or '');
    accessxi.last_native_menu_label = text;
    accessxi.last_native_menu_selected = selected;
    accessxi.last_native_menu_tick = tick();
    accessxi.current_speech_key = ('mount-native:%s:keyitem:%d:%d:%d:0x%08X:%s'):fmt(
        tostring(menu_name or ''),
        selected,
        tonumber(mount_id) or 0,
        tonumber(keyitem_id) or 0,
        tonumber(row_code) or 0,
        name);
    log_state(('state mount native menu="%s" title="%s" select=%d count=%d owned=%d source="keyitem" entry=0x%08X rowCode=0x%08X mountId=%d keyitem=%d label="%s" text="%s"'):fmt(
        tostring(menu_name or ''),
        tostring(title or ''),
        selected,
        count,
        tonumber(owned_count) or 0,
        tonumber(entry) or 0,
        tonumber(row_code) or 0,
        tonumber(mount_id) or 0,
        tonumber(keyitem_id) or 0,
        accessxi.escape_probe_log_text(name),
        accessxi.escape_probe_log_text(text)));
    return ('%s. %s'):fmt(tostring(title or 'Mounts'), accessxi.sentence_fragment(text));
end

function accessxi.status_menu_native_description_text(text)
    text = accessxi.survival_guide_text(text or '');
    if (text == '') then
        return '';
    end

    text = text:gsub('^["\']+', ''):gsub('["\']+$', '');
    text = text:gsub('%s+ww$', '');
    text = accessxi.survival_guide_text(text);
    if (text == '' or #text > 180) then
        return '';
    end
    if (text:match('^menu%s+') ~= nil or text:match('keytops') ~= nil or text:match('windowps') ~= nil) then
        return '';
    end
    if (text:match('^[%p%s]+$') ~= nil) then
        return '';
    end

    local letters = 0;
    for i = 1, #text do
        local byte_value = text:byte(i) or 0;
        if (byte_value < 0x20 or byte_value > 0x7E) then
            return '';
        end
    end
    for _ in text:gmatch('%a') do
        letters = letters + 1;
    end
    if (letters < 2) then
        return '';
    end

    return text;
end

function accessxi.job_name(job_id)
    job_id = tonumber(job_id) or 0;
    accessxi.entity_names_data = accessxi.entity_names_data or accessxi.load_module_table('entity_names_data', T{ jobs = {}, nations = {}, unities = {} });
    local names = accessxi.entity_names_data.jobs or {};
    return names[job_id] or ('Job %d'):fmt(job_id);
end

function accessxi.change_jobs_menu_speech(menu_name, title, selected, count, entry, child)
    menu_name = tostring(menu_name or '');
    title = tostring(title or 'Change Jobs');
    selected = tonumber(selected) or 0;
    count = tonumber(count) or 0;
    entry = tonumber(entry) or 0;
    child = tonumber(child) or 0;

    if (menu_name:eq('menu    jobchang', true)) then
        local label = '';
        if (selected == 1) then
            label = 'Main Job';
        elseif (selected == 2) then
            label = 'Support Job';
        end
        if (label ~= '') then
            accessxi.last_native_menu_name = menu_name;
            accessxi.last_native_menu_label = label;
            accessxi.last_native_menu_selected = selected;
            accessxi.last_native_menu_tick = tick();
            accessxi.current_speech_key = ('change-jobs-top:%d:%s'):fmt(selected, label);
            log_state(('state changejobs top menu="%s" title="%s" select=%d count=%d entry=0x%08X child=0x%08X label="%s"'):fmt(
                menu_name,
                title,
                selected,
                count,
                entry,
                child,
                accessxi.escape_probe_log_text(label)));
            return ('%s. %s.'):fmt(title, label);
        end
        log_state(('state changejobs top-missing menu="%s" title="%s" select=%d count=%d entry=0x%08X child=0x%08X'):fmt(
            menu_name,
            title,
            selected,
            count,
            entry,
            child));
        return nil;
    end

    if (menu_name:eq('menu    jobcselu', true)) then
        local job_id, logical, scroll_top, scroll_raw = accessxi.job_point_job_from_native_selection(selected, child);
        local label = job_id > 0 and accessxi.job_name(job_id) or '';
        if (label ~= '') then
            accessxi.last_native_menu_name = menu_name;
            accessxi.last_native_menu_label = label;
            accessxi.last_native_menu_selected = selected;
            accessxi.last_native_menu_tick = tick();
            accessxi.current_speech_key = ('change-jobs-job:%d:%d:%d:%s'):fmt(selected, logical, job_id, label);
            log_state(('state changejobs job menu="%s" title="%s" select=%d logical=%d count=%d scrollTop=%d scrollRaw=0x%08X entry=0x%08X child=0x%08X job=%d label="%s"'):fmt(
                menu_name,
                title,
                selected,
                logical,
                count,
                scroll_top,
                scroll_raw,
                entry,
                child,
                job_id,
                accessxi.escape_probe_log_text(label)));
            return ('%s. %s.'):fmt(title, label);
        end
        log_state(('state changejobs job-missing menu="%s" title="%s" select=%d count=%d entry=0x%08X child=0x%08X'):fmt(
            menu_name,
            title,
            selected,
            count,
            entry,
            child));
        return nil;
    end

    return nil;
end

function accessxi.nation_name(nation_id)
    nation_id = tonumber(nation_id) or -1;
    accessxi.entity_names_data = accessxi.entity_names_data or accessxi.load_module_table('entity_names_data', T{ jobs = {}, nations = {}, unities = {} });
    local names = accessxi.entity_names_data.nations or {};
    return names[nation_id] or ('Nation %d'):fmt(nation_id);
end

function accessxi.unity_name(unity_id)
    unity_id = tonumber(unity_id) or 0;
    accessxi.entity_names_data = accessxi.entity_names_data or accessxi.load_module_table('entity_names_data', T{ jobs = {}, nations = {}, unities = {} });
    local names = accessxi.entity_names_data.unities or {};
    if (unity_id <= 0) then
        return 'None';
    end
    return names[unity_id] or ('Unity %d'):fmt(unity_id);
end

function accessxi.status_number(value)
    value = tonumber(value);
    if (value == nil) then
        return '';
    end

    local sign = value < 0 and '-' or '';
    local text = tostring(math.floor(math.abs(value)));
    local left, right = text, '';
    while (#left > 3) do
        right = ',' .. left:sub(-3) .. right;
        left = left:sub(1, -4);
    end
    return sign .. left .. right;
end

function accessxi.status_stat_text(name, base, modifier)
    base = tonumber(base);
    modifier = tonumber(modifier) or 0;
    if (base == nil) then
        return '';
    end
    if (modifier > 0) then
        return ('%s %d plus %d'):fmt(name, base, modifier);
    elseif (modifier < 0) then
        return ('%s %d minus %d'):fmt(name, base, math.abs(modifier));
    end
    return ('%s %d'):fmt(name, base);
end

function accessxi.status_item_level(value)
    value = tonumber(value) or 0;
    if (value > 0 and value < 100) then
        return value + 100;
    end
    return value;
end

function accessxi.status_overview_native_summary(title)
    local mm = safe_call(function () return AshitaCore:GetMemoryManager(); end, nil);
    if (mm == nil) then
        return nil;
    end

    local player = safe_call(function () return mm:GetPlayer(); end, nil);
    if (player == nil) then
        return nil;
    end

    local party = safe_call(function () return mm:GetParty(); end, nil);
    local function num(fn, default)
        return tonumber(safe_call(fn, default)) or default;
    end
    local function text(fn, default)
        local value = clean_probe_text(safe_call(fn, default or ''));
        return value;
    end
    local function add(parts, value)
        value = tostring(value or ''):trim();
        if (value ~= '') then
            parts:append(value);
        end
    end

    local name = party ~= nil and text(function () return party:GetMemberName(0); end, '') or '';
    local main_job = num(function () return player:GetMainJob(); end, 0);
    local main_level = num(function () return player:GetMainJobLevel(); end, 0);
    local sub_job = num(function () return player:GetSubJob(); end, 0);
    local sub_level = num(function () return player:GetSubJobLevel(); end, 0);
    local hp = party ~= nil and num(function () return party:GetMemberHP(0); end, -1) or -1;
    local mp = party ~= nil and num(function () return party:GetMemberMP(0); end, -1) or -1;
    local tp = party ~= nil and num(function () return party:GetMemberTP(0); end, -1) or -1;
    local hp_max = num(function () return player:GetHPMax(); end, -1);
    local mp_max = num(function () return player:GetMPMax(); end, -1);
    local exp_current = num(function () return player:GetExpCurrent(); end, -1);
    local exp_needed = num(function () return player:GetExpNeeded(); end, -1);
    local attack = num(function () return player:GetAttack(); end, -1);
    local defense = num(function () return player:GetDefense(); end, -1);
    local item_level = num(function () return player:GetItemLevel(); end, -1);
    local highest_item_level = num(function () return player:GetHighestItemLevel(); end, -1);
    local superior = num(function () return player:GetSuLevel(); end, -1);
    local mastery_job = num(function () return player:GetMasteryJob(); end, 0);
    local mastery_level = num(function () return player:GetMasteryJobLevel(); end, -1);
    local limit_points = num(function () return player:GetLimitPoints(); end, -1);
    local merit_points = num(function () return player:GetMeritPoints(); end, -1);
    local rank = num(function () return player:GetRank(); end, -1);
    local nation = num(function () return player:GetNation(); end, -1);
    local gil = tonumber(safe_call(function () return accessxi.current_inventory_gil(); end, nil));

    local stat_names = accessxi.status_menu_data.stat_names or T{};
    local stat_parts = T{};
    local stat_key_parts = T{};
    for i = 1, stat_names:len() do
        local value = num(function () return player:GetStat(i - 1); end, -9999);
        local modifier = num(function () return player:GetStatModifier(i - 1); end, 0);
        if (value ~= -9999) then
            stat_parts:append(accessxi.status_stat_text(stat_names[i], value, modifier));
            stat_key_parts:append(('%d:%d'):fmt(value, modifier));
        end
    end

    local parts = T{};
    local summary_title = tostring(title or 'Status'):trim();
    if (summary_title == '') then
        summary_title = 'Status';
    end
    add(parts, summary_title);
    if (name ~= '') then
        add(parts, name);
    end
    add(parts, ('Level %d %s'):fmt(main_level, accessxi.job_name(main_job)));
    if (sub_job > 0) then
        add(parts, ('Support job %s level %d'):fmt(accessxi.job_name(sub_job), sub_level));
    end
    if (superior > 0) then
        add(parts, ('Superior level %d'):fmt(superior));
    end
    if (hp >= 0 and hp_max >= 0) then
        add(parts, ('HP %s of %s'):fmt(accessxi.status_number(hp), accessxi.status_number(hp_max)));
    end
    if (mp >= 0 and mp_max >= 0) then
        add(parts, ('MP %s of %s'):fmt(accessxi.status_number(mp), accessxi.status_number(mp_max)));
    end
    if (tp >= 0) then
        add(parts, ('TP %s'):fmt(accessxi.status_number(tp)));
    end
    if (gil ~= nil and gil >= 0) then
        add(parts, ('Gil %s'):fmt(accessxi.status_number(gil)));
    end
    if (exp_current >= 0 and exp_needed >= 0) then
        add(parts, ('Experience %s of %s'):fmt(accessxi.status_number(exp_current), accessxi.status_number(exp_needed)));
    end
    if (limit_points >= 0) then
        add(parts, ('Limit points %s'):fmt(accessxi.status_number(limit_points)));
    end
    if (merit_points >= 0) then
        add(parts, ('Merit points %s'):fmt(accessxi.status_number(merit_points)));
    end
    if (mastery_job > 0 and mastery_level > 0) then
        add(parts, ('Master level %d for %s'):fmt(mastery_level, accessxi.job_name(mastery_job)));
    end
    local visible_item_level = accessxi.status_item_level(math.max(item_level, highest_item_level));
    if (visible_item_level > 0) then
        add(parts, ('Item level %d'):fmt(visible_item_level));
    end
    if (attack >= 0) then
        add(parts, ('Attack %d'):fmt(attack));
    end
    if (defense >= 0) then
        add(parts, ('Defense %d'):fmt(defense));
    end
    if (stat_parts:len() > 0) then
        add(parts, stat_parts:concat(', '));
    end
    if (rank >= 0) then
        add(parts, ('Rank %d'):fmt(rank));
    end

    local key = ('%s:%s:%d:%d:%d:%d:%d:%d:%d:%d:%d:%d:%d:%d:%d:%d:%d:%d:%s'):fmt(
        summary_title,
        name,
        main_job,
        main_level,
        sub_job,
        sub_level,
        hp,
        mp,
        tp,
        hp_max,
        mp_max,
        exp_current,
        exp_needed,
        attack,
        defense,
        item_level,
        rank,
        gil or -1,
        stat_key_parts:concat(','));
    accessxi.status_overview_last_key = key;
    log_state(('state status-overview native title="%s" name="%s" mainJob=%d mainLevel=%d subJob=%d subLevel=%d hp=%d hpMax=%d mp=%d mpMax=%d tp=%d gil=%d exp=%d expNeed=%d attack=%d defense=%d itemLevel=%d highestItemLevel=%d visibleItemLevel=%d su=%d masteryJob=%d masteryLevel=%d limit=%d merits=%d nation=%d rank=%d stats="%s"'):fmt(
        summary_title,
        name,
        main_job,
        main_level,
        sub_job,
        sub_level,
        hp,
        hp_max,
        mp,
        mp_max,
        tp,
        gil or -1,
        exp_current,
        exp_needed,
        attack,
        defense,
        item_level,
        highest_item_level,
        visible_item_level,
        superior,
        mastery_job,
        mastery_level,
        limit_points,
        merit_points,
        nation,
        rank,
        stat_key_parts:concat(',')));
    return parts:concat('. ') .. '.';
end

function accessxi.status_player()
    local mm = safe_call(function () return AshitaCore:GetMemoryManager(); end, nil);
    if (mm == nil) then
        return nil, nil;
    end
    return safe_call(function () return mm:GetPlayer(); end, nil), safe_call(function () return mm:GetParty(); end, nil);
end

function accessxi.status_add(parts, value)
    value = tostring(value or ''):trim();
    if (value ~= '') then
        parts:append(value);
    end
end

function accessxi.status_get_number(fn, default)
    return tonumber(safe_call(fn, default)) or default;
end

function accessxi.status_detail_profile_summary(player, party)
    local parts = T{ 'Profile' };
    local name = party ~= nil and clean_probe_text(safe_call(function () return party:GetMemberName(0); end, '')) or '';
    if (name ~= '') then
        accessxi.status_add(parts, name);
    end
    local nation = accessxi.status_get_number(function () return player:GetNation(); end, -1);
    local rank = accessxi.status_get_number(function () return player:GetRank(); end, -1);
    local title = accessxi.status_get_number(function () return player:GetTitle(); end, -1);
    local homepoint = accessxi.status_get_number(function () return player:GetHomepoint(); end, -1);
    local residence = accessxi.status_get_number(function () return player:GetResidence(); end, -1);
    if (nation >= 0) then
        accessxi.status_add(parts, ('Allegiance %s'):fmt(accessxi.nation_name(nation)));
    end
    if (rank >= 0) then
        accessxi.status_add(parts, ('Rank %d'):fmt(rank));
    end
    if (title >= 0) then
        accessxi.status_add(parts, ('Title %d'):fmt(title));
    end
    if (homepoint >= 0) then
        accessxi.status_add(parts, ('Home point %d'):fmt(homepoint));
    end
    if (residence >= 0) then
        accessxi.status_add(parts, ('Residence %d'):fmt(residence));
    end
    return parts:concat('. ') .. '.';
end

function accessxi.status_detail_job_levels_summary(player)
    local parts = T{ 'Job Levels' };
    for job = 1, 22 do
        local level = accessxi.status_get_number(function () return player:GetJobLevel(job); end, 0);
        if (level > 0) then
            parts:append(('%s %d'):fmt(accessxi.job_name(job), level));
        end
    end
    return parts:concat('. ') .. '.';
end

function accessxi.status_detail_master_levels_summary(player)
    local parts = T{ 'Master Levels' };
    local count = 0;
    for job = 1, 22 do
        local level = accessxi.status_get_number(function () return player:GetJobMasterLevel(job); end, 0);
        if (level > 0) then
            count = count + 1;
            parts:append(('%s %d'):fmt(accessxi.job_name(job), level));
        end
    end
    if (count == 0) then
        parts:append('No master levels');
    end
    return parts:concat('. ') .. '.';
end

function accessxi.status_skill_value(skill)
    if (skill == nil) then
        return nil, false;
    end
    local value = tonumber(safe_call(function () return skill:GetSkill(); end, nil));
    local capped = safe_call(function () return skill:IsCapped(); end, false) == true;
    return value, capped;
end

function accessxi.status_detail_skill_summary(player, title, entries, craft)
    local parts = T{ title };
    local count = 0;
    for _, entry in ipairs(entries) do
        local index = tonumber(entry[1]) or 0;
        local name = tostring(entry[2] or '');
        local skill = nil;
        if (craft == true) then
            skill = safe_call(function () return player:GetCraftSkill(index); end, nil);
        else
            skill = safe_call(function () return player:GetCombatSkill(index); end, nil);
        end
        local value, capped = accessxi.status_skill_value(skill);
        if (value ~= nil and value > 0) then
            count = count + 1;
            parts:append(('%s %d%s'):fmt(name, value, capped and ' capped' or ''));
        end
    end
    if (count == 0) then
        parts:append('No visible skill values');
    end
    return parts:concat('. ') .. '.';
end

function accessxi.status_detail_unity_summary(player)
    local parts = T{ 'Unity' };
    local faction = accessxi.status_get_number(function () return player:GetUnityFaction(); end, 0);
    local points = accessxi.status_get_number(function () return player:GetUnityPoints(); end, -1);
    local personal = accessxi.status_get_number(function () return player:GetUnityPersonalEvaluationPoints(); end, -1);
    accessxi.status_add(parts, accessxi.unity_name(faction));
    if (points >= 0) then
        accessxi.status_add(parts, ('Unity accolades %s'):fmt(accessxi.status_number(points)));
    end
    if (personal >= 0) then
        accessxi.status_add(parts, ('Personal evaluation %s'):fmt(accessxi.status_number(personal)));
    end
    return parts:concat('. ') .. '.';
end

function accessxi.status_detail_play_time_summary()
    return 'Play Time. The game writes play time to the chat log for this command.';
end

function accessxi.status_detail_native_summary(label, row_code)
    label = tostring(label or '');
    row_code = tonumber(row_code) or 0;
    local player, party = accessxi.status_player();
    if (player == nil) then
        return nil, '';
    end

    local text = nil;
    if (label == 'Profile') then
        text = accessxi.status_detail_profile_summary(player, party);
    elseif (label == 'Job Levels') then
        text = accessxi.status_detail_job_levels_summary(player);
    elseif (label == 'Master Levels') then
        text = accessxi.status_detail_master_levels_summary(player);
    elseif (label == 'Combat Skills') then
        text = accessxi.status_detail_skill_summary(player, 'Combat Skills', T{
            T{ 1, 'Hand-to-Hand' }, T{ 2, 'Dagger' }, T{ 3, 'Sword' }, T{ 4, 'Great Sword' },
            T{ 5, 'Axe' }, T{ 6, 'Great Axe' }, T{ 7, 'Scythe' }, T{ 8, 'Polearm' },
            T{ 9, 'Katana' }, T{ 10, 'Great Katana' }, T{ 11, 'Club' }, T{ 12, 'Staff' },
            T{ 25, 'Archery' }, T{ 26, 'Marksmanship' }, T{ 27, 'Throwing' },
            T{ 28, 'Guarding' }, T{ 29, 'Evasion' }, T{ 30, 'Shield' }, T{ 31, 'Parrying' },
            T{ 22, 'Automaton Melee' }, T{ 23, 'Automaton Ranged' }, T{ 24, 'Automaton Magic' },
        }, false);
    elseif (label == 'Magic Skills') then
        text = accessxi.status_detail_skill_summary(player, 'Magic Skills', T{
            T{ 32, 'Divine Magic' }, T{ 33, 'Healing Magic' }, T{ 34, 'Enhancing Magic' },
            T{ 35, 'Enfeebling Magic' }, T{ 36, 'Elemental Magic' }, T{ 37, 'Dark Magic' },
            T{ 38, 'Summoning Magic' }, T{ 39, 'Ninjutsu' }, T{ 40, 'Singing' },
            T{ 41, 'String Instrument' }, T{ 42, 'Wind Instrument' }, T{ 43, 'Blue Magic' },
            T{ 44, 'Geomancy' }, T{ 45, 'Handbell' },
        }, false);
    elseif (label == 'Craft Skills') then
        text = accessxi.status_detail_skill_summary(player, 'Craft Skills', T{
            T{ 0, 'Fishing' }, T{ 1, 'Woodworking' }, T{ 2, 'Smithing' }, T{ 3, 'Goldsmithing' },
            T{ 4, 'Clothcraft' }, T{ 5, 'Leathercraft' }, T{ 6, 'Bonecraft' }, T{ 7, 'Alchemy' },
            T{ 8, 'Cooking' }, T{ 9, 'Synergy' }, T{ 10, 'Chocobo Riding' }, T{ 11, 'Chocobo Digging' },
        }, true);
    elseif (label == 'Unity') then
        text = accessxi.status_detail_unity_summary(player);
    elseif (label == 'Play Time') then
        text = accessxi.status_detail_play_time_summary();
    elseif (label == 'Currencies' or label == 'Currencies 2') then
        text = label .. '. Native currency detail is visible, but the full currency table is not exposed through the current player API yet.';
    end

    if (text == nil or text == '') then
        return nil, '';
    end
    return text, ('%s:%08X:%s'):fmt(label, row_code, text);
end

function accessxi.schedule_status_overview_screen_read(reason, delay_ms)
    local now = tick();
    accessxi.status_overview_pending_due = now + (tonumber(delay_ms) or 300);
    accessxi.status_overview_pending_until = now + 2500;
    accessxi.status_overview_pending_reason = tostring(reason or 'status-profile');
    log_state(('state status-overview pending reason="%s" due=%d until=%d lastMenu="%s" lastLabel="%s"'):fmt(
        accessxi.status_overview_pending_reason,
        accessxi.status_overview_pending_due,
        accessxi.status_overview_pending_until,
        accessxi.last_native_menu_name or '',
        accessxi.escape_probe_log_text(accessxi.last_native_menu_label or '')));
end

function accessxi.current_status_menu_selection()
    local menu_name = tostring(get_menu_name() or '');
    if (not menu_name:eq('menu    statcom2', true)) then
        return nil;
    end

    local obj = get_current_menu_object_ptr();
    if (obj == 0) then
        return nil;
    end
    local entry = read_u32(obj + 0x08) or 0;
    if (not accessxi.is_probe_pointer(entry)) then
        return nil;
    end

    local selected = read_current_native_menu_index(0x4C);
    local description, row2, desc = accessxi.status_menu_native_description_for_entry(entry);
    if (description == '') then
        return nil;
    end
    local label, row0, row_code = accessxi.status_menu_native_label_for_description(description, desc);
    if (label == '') then
        return nil;
    end

    return T{
        menu_name = menu_name,
        obj = obj,
        entry = entry,
        selected = selected,
        description = description,
        label = label,
        row0 = row0,
        row2 = row2,
        desc = desc,
        row_code = row_code,
    };
end

function accessxi.status_detail_label_supported(label)
    label = tostring(label or '');
    return label == 'Profile'
        or label == 'Job Levels'
        or label == 'Master Levels'
        or label == 'Combat Skills'
        or label == 'Magic Skills'
        or label == 'Craft Skills'
        or label == 'Unity';
end

function accessxi.schedule_status_detail_screen_read(selection, reason, delay_ms)
    if (selection == nil or not accessxi.status_detail_label_supported(selection.label)) then
        return false;
    end

    local now = tick();
    accessxi.status_overview_pending_due = 0;
    accessxi.status_overview_pending_until = 0;
    accessxi.status_detail_pending_due = now + (tonumber(delay_ms) or 450);
    accessxi.status_detail_pending_until = now + 3000;
    accessxi.status_detail_suppress_status_menu_until = accessxi.status_detail_pending_due + 450;
    accessxi.status_detail_pending_label = tostring(selection.label or '');
    accessxi.status_detail_pending_row_code = tonumber(selection.row_code) or 0;
    log_state(('state status-detail pending reason="%s" label="%s" rowCode=0x%08X selected=%d due=%d until=%d'):fmt(
        tostring(reason or ''),
        accessxi.status_detail_pending_label,
        accessxi.status_detail_pending_row_code,
        tonumber(selection.selected) or 0,
        accessxi.status_detail_pending_due,
        accessxi.status_detail_pending_until));
    return true;
end

function accessxi.party_label_probe_text_summary(ptr, length)
    ptr = tonumber(ptr) or 0;
    length = tonumber(length) or 0x180;
    if (not accessxi.is_probe_pointer(ptr)) then
        return '';
    end

    local parts = T{};
    local strings = accessxi.probe_strings_at(ptr);
    if (strings ~= '') then
        parts:append(('strings="%s"'):fmt(accessxi.escape_probe_log_text(strings)));
    end
    local inline = accessxi.status_menu_probe_inline_strings(ptr);
    if (inline ~= '') then
        parts:append(('inline="%s"'):fmt(accessxi.escape_probe_log_text(inline)));
    end
    local runs = accessxi.status_menu_probe_runs(ptr, length);
    if (runs ~= '') then
        parts:append(('runs="%s"'):fmt(accessxi.escape_probe_log_text(runs)));
    end
    local ffxi_runs = accessxi.collect_probe_ffxi_utf16_runs(ptr, length, 2, 12);
    if (#ffxi_runs > 0) then
        parts:append(('ffxi="%s"'):fmt(accessxi.escape_probe_log_text(ffxi_runs:concat(' '))));
    end
    return parts:concat(' ');
end

function accessxi.log_party_label_probe_record(seq, label, ptr, selected, count)
    ptr = tonumber(ptr) or 0;
    if (not accessxi.is_probe_pointer(ptr)) then
        return;
    end

    local desc = read_u32(ptr + 0x04) or 0;
    local desc_name = accessxi.is_probe_pointer(desc) and clean_probe_text(read_probe_string(desc + 0x46)) or '';
    log_line(('partylabel seq=%d %s ptr=0x%08X desc=0x%08X descName="%s" indexes="%s" dwords=%s text=%s'):fmt(
        seq,
        tostring(label or ''),
        ptr,
        desc,
        accessxi.escape_probe_log_text(desc_name),
        accessxi.format_probe_index_fields(ptr, 0x00, 0xA0),
        accessxi.format_probe_dwords(ptr, 0x00, 24),
        accessxi.party_label_probe_text_summary(ptr, 0x240)));

    accessxi.log_probe_value_hits(seq, ('partylabel.%s'):fmt(tostring(label or 'ptr')), ptr, 0x140, T{
        (tonumber(selected) or 0) - 1,
        tonumber(selected) or 0,
        tonumber(count) or 0
    });

    local logged = 0;
    for off = 0, 0xC0, 4 do
        if (logged >= 12) then
            return;
        end
        local child = read_u32(ptr + off) or 0;
        if (accessxi.is_probe_pointer(child)) then
            local summary = accessxi.party_label_probe_text_summary(child, 0x180);
            if (summary ~= '') then
                logged = logged + 1;
                local child_desc = read_u32(child + 0x04) or 0;
                local child_desc_name = accessxi.is_probe_pointer(child_desc) and clean_probe_text(read_probe_string(child_desc + 0x46)) or '';
                log_line(('partylabel seq=%d %s child +%03X=0x%08X desc=0x%08X descName="%s" dwords=%s text=%s'):fmt(
                    seq,
                    tostring(label or ''),
                    off,
                    child,
                    child_desc,
                    accessxi.escape_probe_log_text(child_desc_name),
                    accessxi.format_probe_dwords(child, 0x00, 16),
                    summary));
            end
        end
    end
end

function accessxi.log_party_label_probe_snapshot(reason, menu_name, title, selected, count, entry, help_ptr, help_text)
    menu_name = tostring(menu_name or get_menu_name() or '');
    if (not menu_name:eq('menu    prty1', true)
        and not menu_name:eq('menu    alarm', true)
        and not menu_name:eq('menu    prty5us', true)) then
        return false;
    end

    local obj = get_current_menu_object_ptr();
    entry = tonumber(entry) or 0;
    if (not accessxi.is_probe_pointer(entry)) then
        entry = accessxi.is_probe_pointer(obj) and (read_u32(obj + 0x08) or 0) or 0;
    end
    if (not accessxi.is_probe_pointer(entry)) then
        return false;
    end

    selected = tonumber(selected) or 0;
    count = tonumber(count) or 0;
    if (selected <= 0 or count <= 0) then
        local sel2, _, _, _, count2 = accessxi.survival_guide_query_child_state_for_obj(obj);
        selected = selected > 0 and selected or (tonumber(sel2) or 0);
        count = count > 0 and count or (tonumber(count2) or 0);
    end

    help_ptr = tonumber(help_ptr) or (read_u32(entry + 0x40) or 0);
    help_text = tostring(help_text or accessxi.plain_native_menu_help(read_probe_string(help_ptr, 260)) or '');
    local shape = read_u32(entry + 0x0C) or 0;
    local shape_base = shape;
    if (selected > 1 and accessxi.is_probe_pointer(shape)) then
        shape_base = shape - ((selected - 1) * 0x14);
    end

    local key = ('%s:%08X:%08X:%d:%d:%08X:%08X:%s'):fmt(
        tostring(reason or ''),
        obj,
        entry,
        selected,
        count,
        shape,
        help_ptr,
        help_text);
    if (key == tostring(accessxi.party_label_probe_last_key or '')) then
        return true;
    end
    accessxi.party_label_probe_last_key = key;
    accessxi.menu_dump_sequence = (accessxi.menu_dump_sequence or 0) + 1;
    local seq = accessxi.menu_dump_sequence;

    local target = AshitaCore:GetMemoryManager():GetTarget();
    local ank_num = tonumber(target ~= nil and safe_call(function () return target:GetWindowAnkNum(); end, -1) or -1) or -1;
    local shapes = T{};
    if (target ~= nil) then
        for i = 0, math.min(31, math.max(0, ank_num + 4)) do
            local value = tonumber(safe_call(function () return target:GetWindowAnkShape(i); end, 0)) or 0;
            if (value ~= 0) then
                shapes:append(('%d=0x%08X'):fmt(i, value));
            end
        end
    end

    log_line(('partylabel begin seq=%d reason="%s" menu="%s" title="%s" selected=%d count=%d obj=0x%08X entry=0x%08X shape=0x%08X shapeBase=0x%08X helpPtr=0x%08X help="%s" ank=%d shapes="%s"'):fmt(
        seq,
        tostring(reason or ''),
        menu_name,
        tostring(title or ''),
        selected,
        count,
        obj,
        entry,
        shape,
        shape_base,
        help_ptr,
        accessxi.escape_probe_log_text(help_text),
        ank_num,
        shapes:concat(' ')));

    accessxi.log_party_label_probe_record(seq, 'obj', obj, selected, count);
    accessxi.log_party_label_probe_record(seq, 'entry', entry, selected, count);
    accessxi.log_party_label_probe_record(seq, 'entry.shape', shape, selected, count);
    if (target ~= nil) then
        for i = 0, math.min(31, math.max(0, ank_num + 4)) do
            local value = tonumber(safe_call(function () return target:GetWindowAnkShape(i); end, 0)) or 0;
            if (accessxi.is_probe_pointer(value)) then
                accessxi.log_party_label_probe_record(seq, ('ank%d'):fmt(i), value, selected, count);
            end
        end
    end

    if (accessxi.is_probe_pointer(shape_base)) then
        local max_rows = count;
        if (max_rows <= 0 or max_rows > 16) then
            max_rows = 12;
        end
        for row = 1, max_rows do
            local rec = shape_base + ((row - 1) * 0x14);
            local target_ptr = read_u32(rec + 0x00) or 0;
            local aux_ptr = read_u32(rec + 0x04) or 0;
            local row_help_ptr = read_u32(rec + 0x08) or 0;
            local row_help = accessxi.plain_native_menu_help(read_probe_string(row_help_ptr, 220));
            log_line(('partylabel seq=%d row=%d rec=0x%08X target=0x%08X aux=0x%08X helpPtr=0x%08X help="%s" recDwords=%s'):fmt(
                seq,
                row,
                rec,
                target_ptr,
                aux_ptr,
                row_help_ptr,
                accessxi.escape_probe_log_text(row_help),
                accessxi.format_probe_dwords(rec, 0x00, 5)));
            accessxi.log_party_label_probe_record(seq, ('row%d.target'):fmt(row), target_ptr, selected, count);
            accessxi.log_party_label_probe_record(seq, ('row%d.aux'):fmt(row), aux_ptr, selected, count);
        end
    end

    log_line(('partylabel end seq=%d'):fmt(seq));
    return true;
end

function accessxi.enable_party_label_probe(reason)
    accessxi.party_label_probe_until = tick() + 30000;
    accessxi.party_label_probe_last_key = '';
    local ok = accessxi.log_party_label_probe_snapshot(reason or 'command');
    speak(ok and 'Party label probe enabled for 30 seconds.' or 'Party label probe enabled. Open the Party menu and arrow through it.');
    log_line(('partylabel enabled for 30 seconds reason=%s initial=%s'):fmt(tostring(reason or 'command'), tostring(ok)));
end

function accessxi.party_runtime_state()
    local mm = AshitaCore:GetMemoryManager();
    local party = mm ~= nil and safe_call(function () return mm:GetParty(); end, nil) or nil;
    if (party == nil) then
        return nil;
    end

    return T{
        visible1 = tonumber(safe_call(function () return party:GetAlliancePartyVisible1(); end, -1)) or -1,
        invited = tonumber(safe_call(function () return party:GetAllianceInvited(); end, -1)) or -1,
        invite_party = tonumber(safe_call(function () return party:GetAllianceInviteParty(); end, -1)) or -1,
        member_flags = tonumber(safe_call(function () return party:GetMemberFlagMask(0); end, -1)) or -1,
        status_mask = tonumber(safe_call(function () return party:GetStatusIconsBitMask(0); end, -1)) or -1,
    };
end

function accessxi.party_runtime_state_summary(state)
    if (state == nil) then
        return 'unavailable';
    end

    return ('visible1=%d invited=%d inviteParty=%d memberFlags=0x%08X statusMask=0x%08X'):fmt(
        tonumber(state.visible1) or -1,
        tonumber(state.invited) or -1,
        tonumber(state.invite_party) or -1,
        math.max(tonumber(state.member_flags) or 0, 0),
        math.max(tonumber(state.status_mask) or 0, 0));
end

function accessxi.party_toggle_raw_state(entry)
    entry = tonumber(entry) or 0;
    if (not accessxi.is_probe_pointer(entry)) then
        return nil;
    end

    local state_a = read_u32(entry + 0x10) or 0;
    local state_b = read_u32(entry + 0x14) or state_a;
    if (state_a ~= state_b) then
        return nil;
    end

    return state_a;
end

function accessxi.party_selected_row_help(selected, entry)
    selected = tonumber(selected) or 0;
    entry = tonumber(entry) or 0;
    if (selected <= 0 or not accessxi.is_probe_pointer(entry)) then
        return 0, '';
    end

    local shape = read_u32(entry + 0x0C) or 0;
    if (not accessxi.is_probe_pointer(shape)) then
        return 0, '';
    end

    local shape_base = shape;
    if (selected > 1) then
        shape_base = shape - ((selected - 1) * 0x14);
    end
    if (not accessxi.is_probe_pointer(shape_base)) then
        return 0, '';
    end

    local selected_rec = shape_base + ((selected - 1) * 0x14);
    if (not accessxi.is_probe_pointer(selected_rec)) then
        return 0, '';
    end

    local row_help_ptr = read_u32(selected_rec + 0x08) or 0;
    local row_help = accessxi.plain_native_menu_help(read_probe_string(row_help_ptr, 260));
    return row_help_ptr, row_help;
end

accessxi.party_menu_data = accessxi.load_menu_module_table('party', T{ toggle_help_rows = T{} });

function accessxi.party_toggle_label_for_help(help_text, entry, state_trusted)
    help_text = tostring(help_text or '');
    for _, row in ipairs(accessxi.party_menu_data.toggle_help_rows or T{}) do
        if (help_text == tostring(row.help or '')) then
            return tostring(row.label or '');
        end
    end
    return '';
end

function accessxi.party_toggle_key_for_help(help_text)
    help_text = tostring(help_text or '');
    for _, row in ipairs(accessxi.party_menu_data.toggle_help_rows or T{}) do
        if (help_text == tostring(row.help or '')) then
            return tostring(row.key or '');
        end
    end
    return '';
end

function accessxi.party_config_bool_text(value)
    if (value == true) then
        return 'On';
    end
    if (value == false) then
        return 'Off';
    end
    return '';
end

function accessxi.party_config_state_for_key(key)
    key = tostring(key or '');
    local state = accessxi.party_config_state;
    if (state == nil or key == '') then
        return '';
    end

    return accessxi.party_config_bool_text(state[key]);
end

function accessxi.party_toggle_state_for_help(help_text, entry, state_trusted)
    if (state_trusted == false) then
        return '';
    end

    return accessxi.party_config_state_for_key(accessxi.party_toggle_key_for_help(help_text));
end

function accessxi.party_config_summary()
    local state = accessxi.party_config_state or {};
    return ('invite=%s autoParty=%s recruit=%s source=%s'):fmt(
        accessxi.party_config_bool_text(state.invite),
        accessxi.party_config_bool_text(state.auto_party),
        accessxi.party_config_bool_text(state.recruit),
        tostring(state.source or ''));
end

function accessxi.party_config_apply_flags(flags, source)
    flags = tonumber(flags);
    if (flags == nil) then
        return false;
    end

    accessxi.party_config_state = accessxi.party_config_state or {};
    local state = accessxi.party_config_state;
    local old = accessxi.party_config_summary();
    state.invite = bit.band(flags, 0x00000001) ~= 0;
    state.auto_party = bit.band(flags, 0x00008000) ~= 0;
    state.recruit = bit.band(flags, 0x20000000) ~= 0;
    state.source = tostring(source or '');
    state.flags = flags;
    state.tick = tick();
    return old ~= accessxi.party_config_summary();
end

function accessxi.party_config_apply_set_flags(flags, set_flag, source)
    flags = tonumber(flags);
    set_flag = tonumber(set_flag) or 0;
    if (flags == nil or (set_flag ~= 1 and set_flag ~= 2)) then
        return false;
    end

    accessxi.party_config_state = accessxi.party_config_state or {};
    local state = accessxi.party_config_state;
    local old = accessxi.party_config_summary();
    local value = set_flag == 1;
    if (bit.band(flags, 0x00000001) ~= 0) then
        state.invite = value;
    end
    if (bit.band(flags, 0x00008000) ~= 0) then
        state.auto_party = value;
    end
    if (bit.band(flags, 0x20000000) ~= 0) then
        state.recruit = value;
    end
    state.source = tostring(source or '');
    state.flags = flags;
    state.set_flag = set_flag;
    state.tick = tick();
    return old ~= accessxi.party_config_summary();
end

function accessxi.capture_party_config_outgoing_packet(e)
    if (e == nil or e.id ~= 0x00DC) then
        return;
    end

    local data = e.data_modified or e.data or '';
    if (#data < 0x11) then
        return;
    end

    local flags = accessxi.packet_u32(data, 0x04 + 1);
    local set_flag = accessxi.packet_byte(data, 0x10 + 1);
    local changed = accessxi.party_config_apply_set_flags(flags, set_flag, 'packet_out_0dc');
    local key = ('out:%08X:%02X:%s'):fmt(flags, set_flag, accessxi.party_config_summary());
    if (changed or key ~= tostring(accessxi.party_config_last_out_key or '')) then
        accessxi.party_config_last_out_key = key;
        log_state(('state party config packet_out flags=0x%08X set=%d %s hex=%s'):fmt(
            flags,
            set_flag,
            accessxi.party_config_summary(),
            accessxi.packet_hex(data)));
    end
end

function accessxi.capture_party_config_incoming_packet(e)
    if (e == nil or e.id ~= 0x00B4) then
        return;
    end

    accessxi.config_chat_filter_clear_pending_states('packet_in_0b4');

    local data = e.data_modified or e.data or '';
    if (#data < 0x08) then
        return;
    end

    local flags = accessxi.packet_u32(data, 0x04 + 1);
    local changed = accessxi.party_config_apply_flags(flags, 'packet_in_0b4');
    local key = ('in:%08X:%s'):fmt(flags, accessxi.party_config_summary());
    if (changed or key ~= tostring(accessxi.party_config_last_in_key or '')) then
        accessxi.party_config_last_in_key = key;
        log_state(('state party config packet_in flags=0x%08X %s hex=%s'):fmt(
            flags,
            accessxi.party_config_summary(),
            accessxi.packet_hex(data)));
    end
end

function accessxi.log_party_toggle_probe_snapshot(menu_name, title, selected, count, entry, help_ptr, help_text, runtime_state)
    menu_name = tostring(menu_name or '');
    if (not menu_name:eq('menu    prty1', true)) then
        return;
    end

    local toggle_label = accessxi.party_toggle_label_for_help(help_text, entry);
    if (toggle_label == '') then
        return;
    end

    selected = tonumber(selected) or 0;
    count = tonumber(count) or 0;
    entry = tonumber(entry) or 0;
    if (selected <= 0 or not accessxi.is_probe_pointer(entry)) then
        return;
    end

    local obj = get_current_menu_object_ptr();
    local shape = read_u32(entry + 0x0C) or 0;
    local shape_base = shape;
    if (selected > 1 and accessxi.is_probe_pointer(shape)) then
        shape_base = shape - ((selected - 1) * 0x14);
    end

    local selected_rec = shape;
    if (accessxi.is_probe_pointer(shape_base)) then
        selected_rec = shape_base + ((selected - 1) * 0x14);
    end

    local target_ptr = accessxi.is_probe_pointer(selected_rec) and (read_u32(selected_rec + 0x00) or 0) or 0;
    local aux_ptr = accessxi.is_probe_pointer(selected_rec) and (read_u32(selected_rec + 0x04) or 0) or 0;
    local row_help_ptr = accessxi.is_probe_pointer(selected_rec) and (read_u32(selected_rec + 0x08) or 0) or 0;
    local row_help = accessxi.plain_native_menu_help(read_probe_string(row_help_ptr, 260));
    local runtime = accessxi.party_runtime_state_summary(runtime_state);

    local entry_dwords = accessxi.format_probe_dwords(entry, 0x00, 32);
    local entry_tail = accessxi.format_probe_dwords(entry, 0x80, 24);
    local obj_dwords = accessxi.format_probe_dwords(obj, 0x00, 48);
    local rec_dwords = accessxi.format_probe_dwords(selected_rec, 0x00, 12);
    local target_dwords = accessxi.format_probe_dwords(target_ptr, 0x00, 24);
    local aux_dwords = accessxi.format_probe_dwords(aux_ptr, 0x00, 24);
    local shape_dwords = accessxi.format_probe_dwords(shape, 0x00, 20);
    local base_dwords = accessxi.format_probe_dwords(shape_base, 0x00, math.min(math.max(count, 1) * 5, 60));

    local key = ('%s:%d:%d:%08X:%08X:%08X:%08X:%08X:%08X:%s:%s:%s:%s:%s:%s'):fmt(
        menu_name,
        selected,
        count,
        obj,
        entry,
        shape,
        selected_rec,
        target_ptr,
        aux_ptr,
        runtime,
        entry_dwords,
        obj_dwords,
        rec_dwords,
        target_dwords,
        aux_dwords);
    local now = tick();
    if (key == tostring(accessxi.party_toggle_probe_last_key or '')
        and now < (tonumber(accessxi.party_toggle_probe_last_tick) or 0) + 900) then
        return;
    end
    accessxi.party_toggle_probe_last_key = key;
    accessxi.party_toggle_probe_last_tick = now;
    accessxi.menu_dump_sequence = (accessxi.menu_dump_sequence or 0) + 1;
    local seq = accessxi.menu_dump_sequence;

    log_line(('partytoggle seq=%d menu="%s" title="%s" selected=%d count=%d label="%s" runtime="%s" obj=0x%08X entry=0x%08X shape=0x%08X shapeBase=0x%08X rec=0x%08X target=0x%08X aux=0x%08X helpPtr=0x%08X rowHelpPtr=0x%08X help="%s" rowHelp="%s"'):fmt(
        seq,
        menu_name,
        tostring(title or ''),
        selected,
        count,
        accessxi.escape_probe_log_text(toggle_label),
        accessxi.escape_probe_log_text(runtime),
        obj,
        entry,
        shape,
        shape_base,
        selected_rec,
        target_ptr,
        aux_ptr,
        help_ptr,
        row_help_ptr,
        accessxi.escape_probe_log_text(help_text),
        accessxi.escape_probe_log_text(row_help)));
    log_line(('partytoggle seq=%d entryDwords=%s entryTail=%s entryBytes=%s'):fmt(
        seq,
        entry_dwords,
        entry_tail,
        accessxi.escape_probe_log_text(accessxi.format_probe_bytes(entry, 0, 0xC0))));
    log_line(('partytoggle seq=%d objDwords=%s recDwords=%s shapeDwords=%s baseDwords=%s'):fmt(
        seq,
        obj_dwords,
        rec_dwords,
        shape_dwords,
        base_dwords));
    log_line(('partytoggle seq=%d targetDwords=%s targetText=%s auxDwords=%s auxText=%s'):fmt(
        seq,
        target_dwords,
        accessxi.escape_probe_log_text(accessxi.party_label_probe_text_summary(target_ptr, 0x180)),
        aux_dwords,
        accessxi.escape_probe_log_text(accessxi.party_label_probe_text_summary(aux_ptr, 0x180))));
end

function accessxi.party_menu_speech(menu_name, title, selected, count, entry)
    menu_name = tostring(menu_name or '');
    if (not menu_name:eq('menu    prty1', true)
        and not menu_name:eq('menu    alarm', true)
        and not menu_name:eq('menu    prty5us', true)) then
        return nil;
    end

    title = tostring(title or '');
    if (title == '') then
        if (menu_name:eq('menu    alarm', true)) then
            title = 'Alarm';
        elseif (menu_name:eq('menu    prty5us', true)) then
            title = 'Party language';
        else
            title = 'Party';
        end
    end
    selected = tonumber(selected) or 0;
    count = tonumber(count) or 0;
    entry = tonumber(entry) or 0;
    if (not accessxi.is_probe_pointer(entry)) then
        return nil;
    end

    local help_ptr = read_u32(entry + 0x40) or 0;
    local text = accessxi.plain_native_menu_help(read_probe_string(help_ptr, 260));
    local state_trusted = true;
    local row_help_ptr = 0;
    local row_text = '';
    if (menu_name:eq('menu    prty1', true)) then
        row_help_ptr, row_text = accessxi.party_selected_row_help(selected, entry);
        if (row_text ~= '' and row_text ~= text) then
            local stale_key = ('%s:%d:0x%08X:0x%08X:%s:%s'):fmt(
                menu_name,
                selected,
                entry,
                row_help_ptr,
                text,
                row_text);
            local now = tick();
            if (stale_key ~= tostring(accessxi.party_stale_entry_last_key or '')
                or now > (tonumber(accessxi.party_stale_entry_last_tick) or 0) + 1000) then
                accessxi.party_stale_entry_last_key = stale_key;
                accessxi.party_stale_entry_last_tick = now;
                log_state(('state party stale-entry menu="%s" select=%d entry=0x%08X helpPtr=0x%08X rowHelpPtr=0x%08X entryText="%s" rowText="%s"'):fmt(
                    menu_name,
                    selected,
                    entry,
                    help_ptr,
                    row_help_ptr,
                    accessxi.escape_probe_log_text(text),
                    accessxi.escape_probe_log_text(row_text)));
            end
            text = row_text;
            help_ptr = row_help_ptr;
            state_trusted = false;
        end
    end
    if (text == '') then
        log_state(('state party native-missing menu="%s" select=%d count=%d entry=0x%08X'):fmt(
            menu_name,
            selected,
            count,
            entry));
        return nil;
    end

    local toggle_label = accessxi.party_toggle_label_for_help(text, entry, state_trusted);
    local runtime_state = nil;
    local toggle_state = '';
    if (menu_name:eq('menu    prty1', true) and toggle_label ~= '') then
        runtime_state = accessxi.party_runtime_state();
        toggle_state = accessxi.party_toggle_state_for_help(text, entry, state_trusted);
    end

    local spoken_text = accessxi.sentence_fragment(text);
    if (toggle_label ~= '') then
        spoken_text = accessxi.sentence_fragment(toggle_label) .. ' ' .. spoken_text;
        if (toggle_state ~= '') then
            spoken_text = spoken_text .. ' ' .. accessxi.sentence_fragment(toggle_state);
        end
    end

    accessxi.last_native_menu_name = menu_name;
    accessxi.last_native_menu_label = (toggle_label ~= '' and toggle_label or text);
    accessxi.last_native_menu_selected = selected;
    accessxi.last_native_menu_tick = tick();
    local base_speech_key = ('party-native:%s:%d:%d:0x%08X:0x%08X:%s:%s'):fmt(
        menu_name,
        selected,
        count,
        entry,
        help_ptr,
        toggle_label,
        text);
    accessxi.current_speech_key = ('%s:%s'):fmt(
        base_speech_key,
        toggle_state);
    if (tick() < (accessxi.party_label_probe_until or 0)) then
        accessxi.log_party_label_probe_snapshot('poll', menu_name, title, selected, count, entry, help_ptr, text);
    end
    log_state(('state party native menu="%s" title="%s" select=%d count=%d entry=0x%08X helpPtr=0x%08X label="%s" toggleState="%s" config="%s" runtime="%s" text="%s"'):fmt(
        menu_name,
        title,
        selected,
        count,
        entry,
        help_ptr,
        accessxi.escape_probe_log_text(toggle_label),
        accessxi.escape_probe_log_text(toggle_state),
        accessxi.escape_probe_log_text(accessxi.party_config_summary()),
        accessxi.escape_probe_log_text(accessxi.party_runtime_state_summary(runtime_state)),
        accessxi.escape_probe_log_text(text)));
    return ('%s. %s'):fmt(title, spoken_text);
end

function accessxi.search_result_clean_text(text)
    text = accessxi.survival_guide_text(text);
    text = text:gsub('%s+', ' '):trim();
    if (text == '' or #text < 3) then
        return '';
    end
    if (text:find('[%z\001-\008\011-\031\127-\255]') ~= nil) then
        return '';
    end
    if (text:eq('Search Results', true)
        or text:eq('For Search Results', true)
        or text:contains('Search result:', true)
        or text:contains('list of people found has been truncated', true)) then
        return '';
    end
    if (text:match('^%p+$') ~= nil or text:match('^%d+$') ~= nil) then
        return '';
    end
    if (text:match('%a%a%a') == nil) then
        return '';
    end
    if (text:contains('Scrubber', true)
        or text:contains('Control', true)
        or text:contains('Outline', true)
        or text:contains('Hover', true)) then
        return '';
    end
    return text;
end

function accessxi.search_result_remember_chat_summary(text)
    text = tostring(text or ''):gsub('%s+', ' '):trim();
    local total = text:match('^Search result:%s*(%d+)%s+people found');
    if (total == nil) then
        if (text:contains('list of people found has been truncated', true)) then
            accessxi.search_result_observed_truncated = true;
            accessxi.search_result_observed_truncated_tick = tick();
        end
        return false;
    end

    accessxi.search_result_observed_total = tonumber(total) or 0;
    accessxi.search_result_observed_total_tick = tick();
    accessxi.search_result_packet_rows = nil;
    accessxi.search_result_packet_total = 0;
    accessxi.search_result_packet_tick = 0;
    accessxi.search_result_packet_source = '';
    log_line(('search result summary total=%d text="%s"'):fmt(
        tonumber(accessxi.search_result_observed_total) or 0,
        accessxi.escape_probe_log_text(text)));
    if (tick() <= (tonumber(accessxi.search_result_ixff_watch_until) or 0)) then
        accessxi.search_result_ixff_watch_until = 0;
        log_line('searchixff watch trigger=search-summary');
        local ran, result = pcall(function ()
            return accessxi.log_live_ixff_scan('watch-search-summary');
        end);
        if (not ran) then
            log_line(('searchixff watch error="%s"'):fmt(accessxi.escape_probe_log_text(result)));
            speak('Search IXFF watch scan failed. Error written.');
        else
            speak(('Search IXFF watch scan written. %d hits.'):fmt(tonumber(result) or 0));
        end
    end
    return true;
end

function accessxi.search_result_player_name_looks_valid(name)
    name = tostring(name or ''):trim();
    if (#name < 3 or #name > 15) then
        return false;
    end
    return name:match('^[A-Za-z][A-Za-z]*$') ~= nil;
end

function accessxi.search_result_row_looks_valid(row)
    if (row == nil or not accessxi.search_result_player_name_looks_valid(row.name)) then
        return false;
    end

    local zone = tonumber(row.zone) or 0;
    local main_job = tonumber(row.main_job) or 0;
    local sub_job = tonumber(row.sub_job) or 0;
    local main_level = tonumber(row.main_level) or 0;
    local sub_level = tonumber(row.sub_level) or 0;
    if (zone < 1 or zone > 2048) then
        return false;
    end
    if (main_job < 0 or main_job > 31 or sub_job < 0 or sub_job > 31) then
        return false;
    end
    if (main_level < 0 or main_level > 255 or sub_level < 0 or sub_level > 255) then
        return false;
    end

    return true;
end

function accessxi.search_result_candidate_total_looks_plausible(total, expected_total)
    total = tonumber(total) or 0;
    expected_total = tonumber(expected_total) or 0;
    if (total <= 0 or total > 10000) then
        return false;
    end

    if (expected_total > 0 and total == expected_total) then
        return true;
    end

    -- The visible search-results menu is a truncated page/list.  The chat line
    -- can report thousands of hits while the resident row buffer is much smaller.
    return total <= 128;
end

function accessxi.search_result_candidate_from_ptr(ptr, context)
    ptr = tonumber(ptr) or 0;
    context = tostring(context or 'plain');
    if (not accessxi.is_probe_pointer(ptr)) then
        return '';
    end

    local direct = accessxi.search_result_clean_text(accessxi.native_query_candidate_label_from_ptr(ptr, context));
    if (direct ~= '') then
        return direct;
    end

    for _, off in ipairs(T{ 0x00, 0x04, 0x08, 0x0C, 0x10, 0x14, 0x18, 0x20, 0x28, 0x2C, 0x38, 0x40, 0x44, 0x88, 0x100, 0x104 }) do
        local raw = accessxi.search_result_clean_text(read_probe_string(ptr + off, 220));
        if (raw ~= '') then
            return raw;
        end
        local target = read_u32(ptr + off) or 0;
        if (accessxi.is_probe_pointer(target)) then
            local text = accessxi.search_result_clean_text(read_probe_string(target, 220));
            if (text ~= '') then
                return text;
            end
            text = accessxi.search_result_clean_text(accessxi.native_query_candidate_label_from_ptr(target, context));
            if (text ~= '') then
                return text;
            end
        end
    end

    if (accessxi.collect_probe_ffxi_utf16_entries ~= nil) then
        local entries = accessxi.collect_probe_ffxi_utf16_entries(ptr, 0x240, 2, 12);
        for _, entry in ipairs(entries) do
            local text = accessxi.search_result_clean_text(entry.text or '');
            if (text ~= '') then
                return text;
            end
        end
    end

    return '';
end

function accessxi.search_result_zone_name(zone_id)
    zone_id = tonumber(zone_id) or 0;
    if (zone_id <= 0) then
        return '';
    end

    local text = accessxi.survival_guide_text(safe_call(function ()
        return AshitaCore:GetResourceManager():GetString('zones.names', zone_id) or '';
    end, '') or ''):gsub('%s+', ' '):trim();
    if (text ~= '') then
        return text;
    end

    return ('Zone %d'):fmt(zone_id);
end

function accessxi.search_result_row_speech(row)
    if (row == nil or tostring(row.name or '') == '') then
        return '';
    end

    local parts = T{ tostring(row.name or '') };
    local main_job = tonumber(row.main_job) or 0;
    local sub_job = tonumber(row.sub_job) or 0;
    local main_level = tonumber(row.main_level) or 0;
    local sub_level = tonumber(row.sub_level) or 0;
    if (main_job > 0 and main_level > 0) then
        parts:append(('%s level %d'):fmt(accessxi.job_name(main_job), main_level));
    elseif (main_job > 0) then
        parts:append(accessxi.job_name(main_job));
    end
    if (sub_job > 0 and sub_level > 0) then
        parts:append(('support %s level %d'):fmt(accessxi.job_name(sub_job), sub_level));
    elseif (sub_job > 0) then
        parts:append(('support %s'):fmt(accessxi.job_name(sub_job)));
    end

    local zone = accessxi.search_result_zone_name(row.zone);
    if (zone ~= '') then
        parts:append(zone);
    end

    return parts:concat('. ');
end

function accessxi.search_result_decode_packet_at(data, base_pos, source)
    data = tostring(data or '');
    base_pos = tonumber(base_pos) or 1;
    if (#data < (base_pos + 0x20)) then
        return nil;
    end

    local size_field = accessxi.packet_u16(data, base_pos + 0x08);
    local final_flag = accessxi.packet_byte(data, base_pos + 0x0A);
    local marker = accessxi.packet_byte(data, base_pos + 0x0B);
    local total = accessxi.packet_u16(data, base_pos + 0x0E);
    if (marker ~= 0x80 or size_field <= 0 or (base_pos + size_field - 1) > #data) then
        return nil;
    end

    local packet = data:sub(base_pos, base_pos + size_field - 1);
    local bitpos = 192;
    local rows = T{};
    while ((bitpos / 8) < size_field and #rows < 24) do
        local size_byte_index = math.floor(bitpos / 8) + 1;
        local record_size = accessxi.packet_byte(packet, size_byte_index);
        if (record_size <= 0) then
            break;
        end

        local record_end = bitpos + ((record_size + 1) * 8);
        bitpos = bitpos + 8;
        if (record_end > (size_field * 8)) then
            break;
        end

        local row = T{ name = '' };
        while (bitpos + 5 <= record_end) do
            local field = accessxi.packet_bits_be(packet, bitpos, 5);
            bitpos = bitpos + 5;
            if (field == 0x00 and bitpos + 4 <= record_end) then
                local length = accessxi.packet_bits_be(packet, bitpos, 4);
                bitpos = bitpos + 4;
                if (length <= 0) then
                    bitpos = record_end;
                    break;
                end
                local chars = T{};
                for _ = 1, length do
                    if (bitpos + 7 > record_end) then
                        break;
                    end
                    local ch = accessxi.packet_bits_be(packet, bitpos, 7);
                    bitpos = bitpos + 7;
                    if (ch >= 32 and ch <= 126) then
                        chars:append(string.char(ch));
                    end
                end
                local name = chars:concat('');
                if (name ~= '') then
                    row.name = name;
                end
            elseif (field == 0x01 and bitpos + 10 <= record_end) then
                row.zone = accessxi.packet_bits_be(packet, bitpos, 10);
                bitpos = bitpos + 10;
            elseif (field == 0x02 and bitpos + 2 <= record_end) then
                row.nation = accessxi.packet_bits_be(packet, bitpos, 2);
                bitpos = bitpos + 2;
            elseif (field == 0x03 and bitpos + 10 <= record_end) then
                row.main_job = accessxi.packet_bits_be(packet, bitpos, 5);
                row.sub_job = accessxi.packet_bits_be(packet, bitpos + 5, 5);
                bitpos = bitpos + 10;
            elseif (field == 0x04 and bitpos + 16 <= record_end) then
                row.main_level = accessxi.packet_bits_be(packet, bitpos, 8);
                row.sub_level = accessxi.packet_bits_be(packet, bitpos + 8, 8);
                bitpos = bitpos + 16;
            elseif (field == 0x05 and bitpos + 4 <= record_end) then
                row.race = accessxi.packet_bits_be(packet, bitpos, 4);
                bitpos = bitpos + 4;
            elseif (field == 0x06 and bitpos + 16 <= record_end) then
                row.flags1 = accessxi.packet_bits_be(packet, bitpos, 16);
                bitpos = bitpos + 16;
            elseif (field == 0x08 and bitpos + 20 <= record_end) then
                row.id = accessxi.packet_bits_be(packet, bitpos, 20);
                bitpos = bitpos + 20;
            elseif ((field == 0x0A or field == 0x0B or field == 0x0C or field == 0x0D or field == 0x10) and bitpos + 8 <= record_end) then
                row[('field_%02X'):fmt(field)] = accessxi.packet_bits_be(packet, bitpos, 8);
                bitpos = bitpos + 8;
            elseif ((field == 0x0E or field == 0x11 or field == 0x16) and bitpos + 32 <= record_end) then
                row[('field_%02X'):fmt(field)] = accessxi.packet_bits_be(packet, bitpos, 32);
                bitpos = bitpos + 32;
            elseif (field == 0x17 and bitpos + 16 <= record_end) then
                row.language = accessxi.packet_bits_be(packet, bitpos, 16);
                bitpos = bitpos + 16;
            elseif (field == 0x13 and bitpos + 8 <= record_end) then
                row.linkshell2 = accessxi.packet_bits_be(packet, bitpos, 8);
                bitpos = bitpos + 8;
            else
                row.unknown_field = field;
                bitpos = record_end;
                break;
            end
        end

        bitpos = record_end;
        row.speech = accessxi.search_result_row_speech(row);
        if (row.speech ~= '' and accessxi.search_result_row_looks_valid(row)) then
            rows:append(row);
        end
        if ((bitpos % 8) ~= 0) then
            bitpos = bitpos + (8 - (bitpos % 8));
        end
    end

    if (#rows == 0) then
        return nil;
    end

    return T{
        rows = rows,
        total = total,
        final = final_flag ~= 0,
        size = size_field,
        source = tostring(source or ''),
        base = base_pos,
    };
end

function accessxi.search_result_decode_packet(data, source)
    data = tostring(data or '');
    local decoded = accessxi.search_result_decode_packet_at(data, 1, source);
    if (decoded ~= nil) then
        return decoded;
    end

    for pos = 1, math.max(1, #data - 0x20) do
        if (accessxi.packet_byte(data, pos + 0x0B) == 0x80) then
            decoded = accessxi.search_result_decode_packet_at(data, pos, source);
            if (decoded ~= nil) then
                return decoded;
            end
        end
    end

    return nil;
end

function accessxi.search_result_cache_packet(decoded)
    if (decoded == nil or decoded.rows == nil or #decoded.rows == 0) then
        return false;
    end

    accessxi.search_result_packet_rows = decoded.rows;
    accessxi.search_result_packet_total = tonumber(decoded.total) or #decoded.rows;
    accessxi.search_result_packet_tick = tick();
    accessxi.search_result_packet_focus_until = tick() + 5000;
    accessxi.search_result_packet_source = tostring(decoded.source or '');
    local preview = T{};
    for index, row in ipairs(decoded.rows) do
        if (index > 5) then
            break;
        end
        preview:append(tostring(row.speech or row.name or ''));
    end
    log_line(('search packet decoded source=%s base=%d rows=%d total=%d final=%s preview="%s"'):fmt(
        tostring(decoded.source or ''),
        tonumber(decoded.base) or 0,
        #decoded.rows,
        tonumber(decoded.total) or 0,
        tostring(decoded.final),
        accessxi.escape_probe_log_text(preview:concat(' | '))));
    return true;
end

function accessxi.search_result_load_searchhook_bundle()
    local path = tostring(accessxi.searchhook_bundle_path or '');
    if (path == '') then
        return false;
    end

    local ok_open, file = pcall(io.open, path, 'rb');
    if (not ok_open or file == nil) then
        return false;
    end

    local ok_read, data = pcall(function ()
        local bytes = file:read('*a');
        file:close();
        return bytes;
    end);
    if (not ok_read or type(data) ~= 'string' or #data < 12) then
        return false;
    end
    if (data:sub(1, 8) ~= 'AXSRB001') then
        return false;
    end

    local sig = ('%d:%s:%s'):fmt(
        #data,
        accessxi.packet_hex_limit(data, 32),
        accessxi.packet_hex_limit(data:sub(math.max(1, #data - 31)), 32));
    if (sig == tostring(accessxi.searchhook_last_bundle_sig or '')
        and accessxi.search_result_packet_rows ~= nil
        and tostring(accessxi.search_result_packet_source or ''):find('searchhook%-bundle', 1, false) == 1) then
        return false;
    end
    accessxi.searchhook_last_bundle_sig = sig;

    local rows = T{};
    local seen_packets = {};
    local total = 0;
    local final = false;
    local pos = 9;
    local packet_count = 0;
    while (pos + 4 <= #data) do
        local packet_len = accessxi.packet_u32(data, pos);
        pos = pos + 4;
        if (packet_len <= 0 or (pos + packet_len - 1) > #data) then
            break;
        end

        local packet = data:sub(pos, pos + packet_len - 1);
        pos = pos + packet_len;
        local packet_sig = ('%d:%s:%s'):fmt(
            #packet,
            accessxi.packet_hex_limit(packet, 32),
            accessxi.packet_hex_limit(packet:sub(math.max(1, #packet - 31)), 32));
        if (seen_packets[packet_sig] ~= true) then
            seen_packets[packet_sig] = true;
            local decoded = accessxi.search_result_decode_packet(packet, ('searchhook-bundle:%d'):fmt(packet_count + 1));
            if (decoded ~= nil and decoded.rows ~= nil and #decoded.rows > 0) then
                packet_count = packet_count + 1;
                total = math.max(total, tonumber(decoded.total) or 0);
                final = final or decoded.final == true;
                for _, row in ipairs(decoded.rows) do
                    rows:append(row);
                end
            end
        end
    end

    if (#rows == 0) then
        return false;
    end

    return accessxi.search_result_cache_packet(T{
        rows = rows,
        total = total > 0 and total or #rows,
        final = final,
        size = #data,
        source = ('searchhook-bundle:%d'):fmt(packet_count),
        base = 1,
    });
end

function accessxi.search_result_load_searchhook_packet()
    if (accessxi.search_result_load_searchhook_bundle()) then
        return true;
    end

    local path = tostring(accessxi.searchhook_plain_path or '');
    if (path == '') then
        return false;
    end

    local ok_open, file = pcall(io.open, path, 'rb');
    if (not ok_open or file == nil) then
        return false;
    end

    local ok_read, data = pcall(function ()
        local bytes = file:read('*a');
        file:close();
        return bytes;
    end);
    if (not ok_read or type(data) ~= 'string' or #data < 0x20) then
        return false;
    end

    local sig = ('%d:%s:%s'):fmt(
        #data,
        accessxi.packet_hex_limit(data, 32),
        accessxi.packet_hex_limit(data:sub(math.max(1, #data - 31)), 32));
    if (sig == tostring(accessxi.searchhook_last_plain_sig or '') and accessxi.search_result_packet_rows ~= nil) then
        return false;
    end
    accessxi.searchhook_last_plain_sig = sig;

    local decoded = accessxi.search_result_decode_packet(data, 'searchhook-latest');
    if (decoded == nil) then
        log_line(('searchhook latest decode failed size=%d head="%s"'):fmt(
            #data,
            accessxi.packet_hex_limit(data, 64)));
        return false;
    end

    return accessxi.search_result_cache_packet(decoded);
end

function accessxi.search_result_native_scroll_offset(child)
    if (not accessxi.is_probe_pointer(child)) then
        return 0, 0, 0;
    end

    local window = tonumber(read_u32(child + 0x18) or 0) or 0;
    local visible = bit.band(window, 0xFFFF);
    local offset = bit.rshift(window, 16);
    local packed = tonumber(read_u32(child + 0x20) or 0) or 0;
    local total_entries = bit.band(packed, 0xFFFF);
    local remaining_below = bit.rshift(packed, 16);
    if (visible <= 0 or total_entries <= 0 or offset > total_entries) then
        return 0, total_entries, remaining_below;
    end

    return offset, total_entries, remaining_below;
end

function accessxi.search_result_scan_memory_packets(reason)
    local started = tick();
    local max_ms = 1400;
    local max_bytes = 96 * 1024 * 1024;
    local chunk_size = 0x20000;
    local overlap = 0x500;
    local max_candidates = 160;
    local max_markers = 12000;
    local process = kernel32.GetCurrentProcess();
    local mbi = ffi.new('MEMORY_BASIC_INFORMATION[1]');
    local mbi_size = ffi.sizeof('MEMORY_BASIC_INFORMATION');
    local buffer = ffi.new('char[?]', chunk_size);
    local bytes_read = ffi.new('SIZE_T[1]');
    local start_addr = 0x01000000;
    local start_seed = 0;
    local function consider_start_seed(value)
        value = tonumber(value) or 0;
        if (accessxi.is_probe_pointer(value) and value >= 0x10000000 and (start_seed == 0 or value < start_seed)) then
            start_seed = value;
        end
    end

    local search_entry = tonumber(accessxi.last_search_result_entry) or 0;
    local search_obj = tonumber(accessxi.last_search_result_obj) or 0;
    local search_child = tonumber(accessxi.last_search_result_child) or 0;
    consider_start_seed(search_obj);
    consider_start_seed(search_child);
    consider_start_seed(search_entry);
    if (accessxi.is_probe_pointer(search_obj)) then
        consider_start_seed(read_u32(search_obj + 0x08) or 0);
        consider_start_seed(read_u32(search_obj + 0x0C) or 0);
        consider_start_seed(read_u32(search_obj + 0x10) or 0);
    end
    if (accessxi.is_probe_pointer(search_child)) then
        consider_start_seed(read_u32(search_child + 0x00) or 0);
        consider_start_seed(read_u32(search_child + 0x0C) or 0);
        consider_start_seed(read_u32(search_child + 0x34) or 0);
        consider_start_seed(read_u32(search_child + 0x50) or 0);
    end
    if (accessxi.is_probe_pointer(search_entry)) then
        consider_start_seed(read_u32(search_entry + 0x04) or 0);
        consider_start_seed(read_u32(search_entry + 0x0C) or 0);
        consider_start_seed(read_u32(search_entry + 0x70) or 0);
        consider_start_seed(read_u32(search_entry + 0x74) or 0);
    end
    if (start_seed ~= 0) then
        start_addr = math.floor(math.max(0x01000000, start_seed - 0x400000) / 0x10000) * 0x10000;
    end

    local addr = start_addr;
    local scanned_bytes = 0;
    local regions = 0;
    local readable_regions = 0;
    local skipped_low_regions = 0;
    local skipped_executable_regions = 0;
    local skipped_unreadable_regions = 0;
    local candidates = 0;
    local markers_seen = 0;
    local decoded_count = 0;
    local timed_out = false;
    local rejected_total = 0;
    local rejected_decode = 0;
    local candidate_log_count = 0;
    local expected_total = tonumber(accessxi.search_result_observed_total) or 0;
    local expected_age = tick() - (tonumber(accessxi.search_result_observed_total_tick) or 0);
    if (expected_total <= 0 or expected_age > 120000) then
        expected_total = 0;
    end

    while (addr < 0x7FFF0000 and scanned_bytes < max_bytes and candidates < max_candidates and markers_seen < max_markers) do
        if ((tick() - started) > max_ms) then
            timed_out = true;
            break;
        end

        local ok, result = pcall(function ()
            return kernel32.VirtualQuery(ffi.cast('const void*', addr), mbi, mbi_size);
        end);
        local queried = ok and tonumber(result) or 0;
        if (queried == 0) then
            addr = addr + 0x10000;
        else
            local base = tonumber(ffi.cast('uintptr_t', mbi[0].BaseAddress)) or addr;
            local size = tonumber(mbi[0].RegionSize) or 0;
            local state = tonumber(mbi[0].State) or 0;
            local protect = tonumber(mbi[0].Protect) or 0;
            local next_addr = base + math.max(size, 0x1000);
            regions = regions + 1;

            if (size > 0 and state == 0x1000 and accessxi.memory_page_search_scan_allowed(base, protect)) then
                readable_regions = readable_regions + 1;
                local region_offset = 0;
                while (region_offset < size and scanned_bytes < max_bytes and candidates < max_candidates and markers_seen < max_markers) do
                    if ((tick() - started) > max_ms) then
                        timed_out = true;
                        break;
                    end

                    local want = math.min(chunk_size, size - region_offset, max_bytes - scanned_bytes);
                    if (want <= 0) then
                        break;
                    end

                    local chunk_addr = base + region_offset;
                    bytes_read[0] = 0;
                    local read_ok = kernel32.ReadProcessMemory(process, ffi.cast('const void*', chunk_addr), buffer, want, bytes_read) ~= 0;
                    local got = tonumber(bytes_read[0]) or 0;
                    if (read_ok and got > 0) then
                        local blob = ffi.string(buffer, got);
                        scanned_bytes = scanned_bytes + got;
                        local start_at = 1;
                        while (candidates < max_candidates and markers_seen < max_markers) do
                            local marker_pos = blob:find(string.char(0x80), start_at, true);
                            if (marker_pos == nil) then
                                break;
                            end
                            markers_seen = markers_seen + 1;

                            local packet_base = marker_pos - 0x0B;
                            if (packet_base >= 1) then
                                local size_field = accessxi.packet_u16(blob, packet_base + 0x08);
                                local marker = accessxi.packet_byte(blob, packet_base + 0x0B);
                                local total = accessxi.packet_u16(blob, packet_base + 0x0E);
                                if (marker == 0x80 and size_field >= 0x20 and size_field <= 1024 and (packet_base + size_field - 1) <= #blob) then
                                    local candidate_addr = chunk_addr + packet_base - 1;
                                    local reject_reason = '';
                                    if (not accessxi.search_result_candidate_total_looks_plausible(total, expected_total)) then
                                        rejected_total = rejected_total + 1;
                                        if (total <= 0 or total > 10000) then
                                            reject_reason = 'total-range';
                                        else
                                            reject_reason = ('total-not-page expected=%d'):fmt(expected_total);
                                        end
                                    else
                                        candidates = candidates + 1;
                                        local decoded = accessxi.search_result_decode_packet_at(blob, packet_base, ('memory@0x%08X'):fmt(candidate_addr));
                                        if (decoded ~= nil and decoded.rows ~= nil and #decoded.rows > 0) then
                                            decoded_count = decoded_count + 1;
                                            decoded.memory_address = candidate_addr;
                                            log_line(('searchmem decoded reason="%s" addr=0x%08X size=%d rows=%d total=%d final=%s expectedTotal=%d'):fmt(
                                                accessxi.escape_probe_log_text(reason or ''),
                                                tonumber(decoded.memory_address) or 0,
                                                tonumber(decoded.size) or 0,
                                                #decoded.rows,
                                                tonumber(decoded.total) or 0,
                                                tostring(decoded.final),
                                                expected_total));
                                            accessxi.search_result_cache_packet(decoded);
                                            return true, decoded_count, candidates;
                                        end
                                        rejected_decode = rejected_decode + 1;
                                        reject_reason = 'decode-empty';
                                    end

                                    if (candidate_log_count < 14 and (candidates > 0 or rejected_total <= 8 or reject_reason == 'decode-empty')) then
                                        candidate_log_count = candidate_log_count + 1;
                                        log_line(('searchmem candidate reject reason="%s" addr=0x%08X size=%d total=%d expectedTotal=%d head="%s"'):fmt(
                                            accessxi.escape_probe_log_text(reject_reason),
                                            tonumber(candidate_addr) or 0,
                                            tonumber(size_field) or 0,
                                            tonumber(total) or 0,
                                            expected_total,
                                            accessxi.packet_hex_limit(blob:sub(packet_base, math.min(#blob, packet_base + math.min(size_field, 48) - 1)), 48)));
                                    end
                                end
                            end

                            start_at = marker_pos + 1;
                        end
                    end

                    if (got <= overlap) then
                        region_offset = region_offset + math.max(got, 0x1000);
                    else
                        region_offset = region_offset + got - overlap;
                    end
                end
            elseif (size > 0 and state == 0x1000) then
                if (base < 0x01000000) then
                    skipped_low_regions = skipped_low_regions + 1;
                elseif (accessxi.memory_page_executable(protect)) then
                    skipped_executable_regions = skipped_executable_regions + 1;
                elseif (not accessxi.memory_page_readable(protect)) then
                    skipped_unreadable_regions = skipped_unreadable_regions + 1;
                end
            end

            addr = next_addr;
        end
    end

    log_line(('searchmem done reason="%s" decoded=%d candidates=%d markers=%d maxMarkers=%d expectedTotal=%d rejectedTotal=%d rejectedDecode=%d regions=%d readable=%d skippedLow=%d skippedExec=%d skippedUnreadable=%d scanned=%d start=0x%08X seed=0x%08X timedOut=%s'):fmt(
        accessxi.escape_probe_log_text(reason or ''),
        decoded_count,
        candidates,
        markers_seen,
        max_markers,
        expected_total,
        rejected_total,
        rejected_decode,
        regions,
        readable_regions,
        skipped_low_regions,
        skipped_executable_regions,
        skipped_unreadable_regions,
        scanned_bytes,
        start_addr,
        start_seed,
        tostring(timed_out)));
    return false, decoded_count, candidates;
end

function accessxi.search_result_rendered_cell_text(cell)
    cell = tonumber(cell) or 0;
    if (not accessxi.is_probe_pointer(cell)) then
        return '';
    end

    local chars = T{};
    for off = 0x3D, 0x58 do
        local byte_value = read_u8(cell + off);
        if (byte_value == nil or byte_value == 0) then
            break;
        end
        if (byte_value >= 0x20 and byte_value <= 0x7E) then
            chars:append(string.char(byte_value));
        elseif (#chars > 0) then
            break;
        end
    end

    local text = accessxi.survival_guide_text(chars:concat('')):gsub('%s+', ' '):trim();
    if (text == '' or #text < 2) then
        return '';
    end
    if (text:match('^[%p%d%s]+$') ~= nil) then
        return '';
    end
    return text;
end

function accessxi.search_player_options_module_context()
    return {
        is_pointer = accessxi.is_probe_pointer,
        read_u32 = read_u32,
        read_string = function (ptr) return read_probe_string(ptr, 260); end,
        clean_help = accessxi.plain_native_menu_help,
        escape_log_text = function (text)
            if type(accessxi.escape_probe_log_text) == 'function' then
                return accessxi.escape_probe_log_text(text);
            end
            return tostring(text or ''):gsub('\\', '\\\\'):gsub('"', '\\"');
        end,
        log_state = log_state,
        tick = tick,
    };
end

accessxi.load_menu_code_module('search_player_options', accessxi.search_player_options_module_context());

function accessxi.search_result_rendered_label_looks_useful(label)
    label = tostring(label or ''):gsub('%s+', ' '):trim();
    if (label == '' or #label < 6) then
        return false;
    end

    local useful = false;
    for token in label:gmatch('[%w]+') do
        if (#token >= 4) then
            useful = true;
            break;
        end
    end
    if (not useful) then
        return false;
    end

    local lower = label:lower();
    if (lower:eq('ne uly', true)
        or lower:eq('urn uly', true)
        or lower:eq('uly', true)
        or lower:eq('(ma urn b0e', true)
        or lower:eq('ne (ma uly', true)) then
        return false;
    end

    return true;
end

function accessxi.search_result_rendered_row_text(entry, selected)
    entry = tonumber(entry) or 0;
    selected = tonumber(selected) or 0;
    if (not accessxi.is_probe_pointer(entry) or selected <= 0) then
        return '';
    end

    local cells = T{};
    local seen = T{};
    local parent = read_u32(entry + 0x5C) or 0;
    local function add_cell(cell)
        cell = tonumber(cell) or 0;
        if (not accessxi.is_probe_pointer(cell) or seen[cell]) then
            return;
        end
        if ((read_u32(cell + 0x58) or 0) ~= cell) then
            return;
        end
        if (accessxi.is_probe_pointer(parent) and (read_u32(cell + 0x5C) or 0) ~= parent) then
            return;
        end

        local row_code = read_u32(cell + 0x38) or 0;
        local row_index = math.floor(row_code / 0x10000);
        if (row_index ~= selected) then
            return;
        end

        local text = accessxi.search_result_rendered_cell_text(cell);
        if (text == '') then
            return;
        end

        seen[cell] = true;
        cells:append({
            ptr = cell,
            order = row_code % 0x10000,
            text = text,
        });
    end

    add_cell(entry);
    for delta = -64, 64 do
        add_cell(entry + (delta * 0x68));
    end

    if (#cells == 0) then
        accessxi.last_search_result_render_cells = '';
        return '';
    end
    table.sort(cells, function (a, b)
        if (a.order == b.order) then
            return a.ptr < b.ptr;
        end
        return a.order < b.order;
    end);

    local parts = T{};
    local last = '';
    for _, cell in ipairs(cells) do
        local text = tostring(cell.text or '');
        if (text ~= '' and text ~= last) then
            parts:append(text);
            last = text;
        end
    end

    local label = parts:concat(' '):gsub('%s+', ' '):trim();
    local details = T{};
    for _, cell in ipairs(cells) do
        details:append(('+%04X@0x%08X="%s"'):fmt(
            tonumber(cell.order) or 0,
            tonumber(cell.ptr) or 0,
            accessxi.escape_probe_log_text(cell.text or '')));
    end
    accessxi.last_search_result_render_cells = details:concat(' | ');

    if (label:match('%a%a') == nil or not accessxi.search_result_rendered_label_looks_useful(label)) then
        return '';
    end
    return label;
end

function accessxi.log_search_result_menu_probe(menu_name, title, selected, count, page, raw, child, entry, item_ptr, label, mode, reason)
    local key = ('%s:%d:%d:%08X:%08X:%08X:%s:%s'):fmt(
        tostring(menu_name or ''),
        tonumber(selected) or 0,
        tonumber(count) or 0,
        tonumber(child) or 0,
        tonumber(entry) or 0,
        tonumber(item_ptr) or 0,
        tostring(label or ''),
        tostring(reason or ''));
    if (key == tostring(accessxi.last_search_result_probe_key or '')) then
        return;
    end
    accessxi.last_search_result_probe_key = key;

    local obj = get_current_menu_object_ptr();
    accessxi.last_search_result_menu_name = tostring(menu_name or '');
    accessxi.last_search_result_title = tostring(title or '');
    accessxi.last_search_result_obj = tonumber(obj) or 0;
    accessxi.last_search_result_child = tonumber(child) or 0;
    accessxi.last_search_result_raw = tonumber(raw) or 0;
    accessxi.last_search_result_entry = tonumber(entry) or 0;
    accessxi.last_search_result_selected = tonumber(selected) or 0;
    accessxi.last_search_result_count = tonumber(count) or 0;
    accessxi.last_search_result_page = tonumber(page) or 0;
    accessxi.last_search_result_tick = tick();

    local item_runs = accessxi.status_menu_probe_runs(item_ptr, 0x240);
    local entry_runs = accessxi.status_menu_probe_runs(entry, 0x240);
    local child_runs = accessxi.status_menu_probe_runs(child, 0x240);
    local obj_dwords = accessxi.format_probe_dwords(obj, 0, 56);
    local child_dwords = accessxi.format_probe_dwords(child, 0, 40);
    local raw_dwords = accessxi.format_probe_dwords(raw, 0, 40);
    local entry_dwords = accessxi.format_probe_dwords(entry, 0, 48);
    local compact_rows = accessxi.search_result_compact_row_summary(entry, selected, count);
    local render_neighbors = accessxi.search_result_rendered_neighbor_summary(entry, selected);
    local entry_ptrs = accessxi.search_result_pointer_field_summary(entry);
    log_state(('state search-result menu="%s" title="%s" select=%d count=%d page=%d raw=0x%08X child=0x%08X entry=0x%08X item=0x%08X mode="%s" reason="%s" label="%s" itemRuns="%s" entryRuns="%s" renderCells="%s" renderNeighbors="%s" rowData="%s" entryPtrs="%s" childRuns="%s" objDwords="%s" childDwords="%s" rawDwords="%s" entryDwords="%s"'):fmt(
        tostring(menu_name or ''),
        tostring(title or ''),
        tonumber(selected) or 0,
        tonumber(count) or 0,
        tonumber(page) or 0,
        tonumber(raw) or 0,
        tonumber(child) or 0,
        tonumber(entry) or 0,
        tonumber(item_ptr) or 0,
        tostring(mode or ''),
        tostring(reason or ''),
        accessxi.escape_probe_log_text(label or ''),
        accessxi.escape_probe_log_text(item_runs),
        accessxi.escape_probe_log_text(entry_runs),
        accessxi.escape_probe_log_text(accessxi.last_search_result_render_cells or ''),
        accessxi.escape_probe_log_text_wide(render_neighbors),
        accessxi.escape_probe_log_text_wide(compact_rows),
        accessxi.escape_probe_log_text_wide(entry_ptrs),
        accessxi.escape_probe_log_text(child_runs),
        accessxi.escape_probe_log_text_wide(obj_dwords),
        accessxi.escape_probe_log_text_wide(child_dwords),
        accessxi.escape_probe_log_text_wide(raw_dwords),
        accessxi.escape_probe_log_text_wide(entry_dwords)));
end

function accessxi.search_result_menu_speech(menu_name, title, selected, count, page, raw, child, entry)
    local label = '';
    local mode = '';
    local item_ptr = 0;

    accessxi.search_result_load_searchhook_packet();

    local packet_rows = accessxi.search_result_packet_rows;
    local packet_age = tick() - (tonumber(accessxi.search_result_packet_tick) or 0);
    local scroll_offset, scroll_total, scroll_remaining = accessxi.search_result_native_scroll_offset(child);
    if (selected == 1 and (tonumber(scroll_offset) or 0) <= 0) then
        label = 'Add condition to search.';
        mode = 'search-condition-bar';
    elseif (packet_rows ~= nil and selected > 0 and packet_age >= 0 and packet_age <= 300000) then
        local packet_index = (tonumber(scroll_offset) or 0) + selected - 1;
        if (packet_rows[packet_index] ~= nil) then
            label = accessxi.search_result_row_speech(packet_rows[packet_index]);
            mode = ('search-packet-cache:%d+%d/%d/%d'):fmt(
                packet_index,
                tonumber(scroll_offset) or 0,
                tonumber(scroll_remaining) or 0,
                tonumber(scroll_total) or 0);
        end
    end

    if (accessxi.is_probe_pointer(child) and selected > 0 and count > 0 and selected <= count) then
        if (label == '') then
            local items, list_mode = accessxi.native_query_items_for_child(child, count, 'plain');
            mode = tostring(list_mode or '');
            if (items ~= nil) then
                local item = items[selected];
                if (item ~= nil) then
                    item_ptr = tonumber(item.ptr) or 0;
                    label = accessxi.search_result_clean_text(item.label or '');
                    if (label == '') then
                        label = accessxi.search_result_candidate_from_ptr(item_ptr, 'plain');
                    end
                end
            end
        end
    end

    if (label == '') then
        label = accessxi.search_result_clean_text(accessxi.search_result_rendered_row_text(entry, selected));
        if (label ~= '') then
            mode = 'rendered-row-cells';
        end
    end

    if (label == '') then
        local label_ptr = accessxi.is_probe_pointer(entry) and (read_u32(entry + 0x44) or 0) or 0;
        local help_ptr = accessxi.is_probe_pointer(entry) and (read_u32(entry + 0x40) or 0) or 0;
        label = accessxi.search_result_clean_text(read_probe_string(label_ptr, 220));
        if (label == '') then
            label = accessxi.search_result_clean_text(read_probe_string(help_ptr, 220));
        end
    end

    local reason = label ~= '' and 'native-row' or 'missing-row';
    accessxi.log_search_result_menu_probe(menu_name, title, selected, count, page, raw, child, entry, item_ptr, label, mode, reason);
    if (label == '') then
        return nil;
    end

    accessxi.last_native_menu_name = menu_name;
    accessxi.last_native_menu_label = label;
    accessxi.last_native_menu_selected = selected;
    accessxi.last_native_menu_tick = tick();
    accessxi.current_speech_key = ('search-result:%s:%d:%d:%d:0x%08X:%s'):fmt(
        tostring(menu_name or ''),
        tonumber(selected) or 0,
        tonumber(page) or 0,
        tonumber(count) or 0,
        tonumber(item_ptr) ~= 0 and tonumber(item_ptr) or tonumber(entry) or 0,
        label);
    return ('%s %s'):fmt(accessxi.sentence_fragment(title), accessxi.sentence_fragment(label));
end

function accessxi.trace_search_result_packet(e, direction)
    if (e == nil or tick() > (tonumber(accessxi.search_result_packet_trace_until) or 0)) then
        return;
    end

    if (not accessxi.search_result_event_fields_logged) then
        accessxi.search_result_event_fields_logged = true;
        local fields = T{};
        pcall(function ()
            for k, v in pairs(e) do
                fields:append(('%s:%s'):fmt(tostring(k), type(v)));
            end
        end);
        log_line(('search packet event fields "%s"'):fmt(accessxi.escape_probe_log_text(fields:concat(', '))));
    end

    local variants = T{};
    local function add_variant(name, value)
        if (type(value) == 'string' and #value > 0) then
            variants:append(T{ name = name, data = value });
        end
    end
    add_variant('data_modified', e.data_modified);
    add_variant('data', e.data);
    add_variant('data_modified_raw', accessxi.packet_event_string(e, 'data_modified', 'size'));
    add_variant('data_raw', accessxi.packet_event_string(e, 'data', 'size'));
    add_variant('data_chunk', accessxi.packet_event_string(e, 'data_chunk', 'size_chunk'));
    add_variant('dataChunk', accessxi.packet_event_string(e, 'dataChunk', 'sizeChunk'));
    add_variant('chunk', accessxi.packet_event_string(e, 'chunk', 'size'));
    add_variant('packet_chunk', accessxi.packet_event_string(e, 'packet_chunk', 'size_chunk'));

    for _, variant in ipairs(variants) do
        local decoded = accessxi.search_result_decode_packet(variant.data, variant.name);
        if (decoded ~= nil and accessxi.search_result_cache_packet(decoded)) then
            break;
        end
    end

    local data = e.data_modified or e.data or '';
    local id = tonumber(e.id) or 0;
    local final_flag = #data >= 0x0B and accessxi.packet_byte(data, 0x0A + 1) or -1;
    local marker = #data >= 0x0C and accessxi.packet_byte(data, 0x0B + 1) or -1;
    local total = #data >= 0x10 and accessxi.packet_u16(data, 0x0E + 1) or -1;
    local size_field = #data >= 0x0A and accessxi.packet_u16(data, 0x08 + 1) or -1;
    local candidate = (#data >= 0x20 and marker == 0x80 and size_field > 0 and size_field <= #data);
    local key = ('%s:%03X:%d:%d:%d:%d:%s'):fmt(
        tostring(direction or ''),
        id,
        #data,
        final_flag,
        marker,
        total,
        accessxi.packet_hex_limit(data, candidate and 96 or 24));
    local trace_count = tonumber(accessxi.search_result_packet_trace_count) or 0;
    local trace_limit = tonumber(accessxi.search_result_packet_trace_limit) or 160;
    local should_log = candidate or trace_count < trace_limit;
    if (not should_log and data ~= '') then
        local ascii = accessxi.packet_ascii_preview(data, 140):lower();
        should_log = ascii:contains('search') or ascii:contains('people') or ascii:contains('found');
    end
    if (should_log) then
        accessxi.search_result_packet_trace_count = trace_count + 1;
        accessxi.last_search_result_packet_trace_key = key;
        log_line(('search packet trace dir=%s n=%d id=0x%03X len=%d size=%d final=0x%02X marker=0x%02X total=%d candidate=%s ascii="%s" hex="%s"'):fmt(
            tostring(direction or ''),
            trace_count + 1,
            id,
            #data,
            size_field,
            final_flag,
            marker,
            total,
            tostring(candidate),
            accessxi.escape_probe_log_text(accessxi.packet_ascii_preview(data, 96)),
            accessxi.packet_hex_limit(data, 160)));
    end
end

function accessxi.search_result_inline_runs(ptr)
    ptr = tonumber(ptr) or 0;
    if (not accessxi.is_probe_pointer(ptr)) then
        return '';
    end
    local ascii = accessxi.collect_probe_ascii_runs(ptr, 0x68, 2, 8);
    local ffxi16 = accessxi.collect_probe_ffxi_utf16_runs(ptr, 0x68, 2, 4);
    local parts = T{};
    if (#ascii > 0) then
        parts:append(('ascii=%s'):fmt(ascii:concat(' ')));
    end
    if (#ffxi16 > 0) then
        parts:append(('ffxi16=%s'):fmt(ffxi16:concat(' ')));
    end
    return parts:concat(' ');
end

function accessxi.search_result_control_fragments(ptr, length, limit)
    ptr = tonumber(ptr) or 0;
    if (not accessxi.is_probe_pointer(ptr)) then
        return '';
    end

    length = tonumber(length) or 0x80;
    limit = tonumber(limit) or 12;
    local parts = T{};
    local run = T{};
    local run_start = 0;

    local function flush()
        local text = run:concat(''):gsub('%s+', ' '):trim();
        if (#text >= 2 and text:match('%a') ~= nil) then
            parts:append(('+%03X="%s"'):fmt(run_start, accessxi.escape_probe_log_text(text)));
        end
        run = T{};
    end

    for off = 0, length do
        local byte_value = off < length and read_u8(ptr + off) or nil;
        if (byte_value ~= nil and byte_value >= 0x20 and byte_value <= 0x7E) then
            if (#run == 0) then
                run_start = off;
            end
            run:append(string.char(byte_value));
        else
            flush();
            if (#parts >= limit) then
                return parts:concat(' | ');
            end
        end
    end

    return parts:concat(' | ');
end

function accessxi.search_result_compact_row_summary(entry, selected, count)
    entry = tonumber(entry) or 0;
    selected = tonumber(selected) or 0;
    count = tonumber(count) or 0;
    if (not accessxi.is_probe_pointer(entry) or selected <= 0) then
        return '';
    end

    local row_ptr = read_u32(entry + 0x0C) or 0;
    if (not accessxi.is_probe_pointer(row_ptr)) then
        return '';
    end

    local stride = 0x14;
    local base = row_ptr - ((selected - 1) * stride);
    if (not accessxi.is_probe_pointer(base)) then
        base = row_ptr;
    end

    local start_index = math.max(1, selected - 2);
    local end_index = selected + 2;
    if (count > 0 and count <= 128) then
        end_index = math.min(count, end_index);
    end

    local parts = T{};
    for index = start_index, end_index do
        local rec = base + ((index - 1) * stride);
        if (accessxi.is_probe_pointer(rec)) then
            local ptrs = T{};
            for off = 0, 0x10, 4 do
                local value = read_u32(rec + off) or 0;
                if (accessxi.is_probe_pointer(value)) then
                    local text = accessxi.probe_runs_to_text(accessxi.collect_probe_ascii_runs(value, 0xA0, 2, 3));
                    ptrs:append(('+%02X=0x%08X[%s]'):fmt(off, value, accessxi.escape_probe_log_text(text)));
                end
            end

            parts:append(('#%02d@0x%08X d=%s bytes=%s ascii="%s" ptrs="%s"'):fmt(
                index,
                rec,
                accessxi.format_probe_dwords(rec, 0, 5),
                accessxi.format_probe_bytes(rec, 0, 0x20),
                accessxi.escape_probe_log_text(accessxi.search_result_control_fragments(rec, 0x80, 6)),
                accessxi.escape_probe_log_text(ptrs:concat(' '))));
        end
    end

    return parts:concat(' || ');
end

function accessxi.search_result_rendered_neighbor_summary(entry, selected)
    entry = tonumber(entry) or 0;
    selected = tonumber(selected) or 0;
    if (not accessxi.is_probe_pointer(entry)) then
        return '';
    end

    local parent = read_u32(entry + 0x5C) or 0;
    local parts = T{};
    for delta = -4, 4 do
        local cell = entry + (delta * 0x68);
        if (accessxi.is_probe_pointer(cell)) then
            local row_code = read_u32(cell + 0x38) or 0;
            local row_index = math.floor(row_code / 0x10000);
            local self_ptr = read_u32(cell + 0x58) or 0;
            local cell_parent = read_u32(cell + 0x5C) or 0;
            local row_data = read_u32(cell + 0x0C) or 0;
            local direct = accessxi.search_result_control_fragments(cell + 0x30, 0x60, 4);
            if (row_index == selected or delta == 0 or direct ~= '') then
                parts:append(('d%+d ptr=0x%08X row=%d order=0x%04X self=0x%08X parent=0x%08X match=%s rowData=0x%08X text="%s"'):fmt(
                    delta,
                    cell,
                    row_index,
                    bit.band(row_code, 0xFFFF),
                    self_ptr,
                    cell_parent,
                    tostring(parent ~= 0 and cell_parent == parent),
                    row_data,
                    accessxi.escape_probe_log_text(direct)));
            end
        end
    end

    return parts:concat(' || ');
end

function accessxi.search_result_pointer_field_summary(entry)
    entry = tonumber(entry) or 0;
    if (not accessxi.is_probe_pointer(entry)) then
        return '';
    end

    local parts = T{};
    for _, off in ipairs(T{ 0x00, 0x04, 0x0C, 0x40, 0x44, 0x58, 0x5C, 0x68, 0x6C, 0x70, 0x74, 0x78, 0x7C, 0x80, 0x84, 0x88, 0x8C }) do
        local value = read_u32(entry + off) or 0;
        if (accessxi.is_probe_pointer(value)) then
            local strings = accessxi.probe_strings_at(value);
            local ascii = accessxi.probe_runs_to_text(accessxi.collect_probe_ascii_runs(value, 0x180, 2, 8));
            local utf16 = accessxi.probe_runs_to_text(accessxi.collect_probe_utf16_runs(value, 0x180, 2, 4));
            local bytes = accessxi.format_probe_bytes(value, 0, 0x40);
            parts:append(('+%02X=0x%08X strings="%s" ascii="%s" utf16="%s" d=%s bytes=%s'):fmt(
                off,
                value,
                accessxi.escape_probe_log_text(strings),
                accessxi.escape_probe_log_text(ascii),
                accessxi.escape_probe_log_text(utf16),
                accessxi.format_probe_dwords(value, 0, 12),
                accessxi.escape_probe_log_text_wide(bytes)));
        end
    end

    return parts:concat(' || ');
end

function accessxi.log_search_result_pointer_target(seq, label, ptr)
    ptr = tonumber(ptr) or 0;
    if (not accessxi.is_probe_pointer(ptr)) then
        return;
    end

    log_line(('searchdump seq=%d %s ptr=0x%08X strings="%s" runs="%s" dwords=%s bytes=%s'):fmt(
        tonumber(seq) or 0,
        tostring(label or ''),
        ptr,
        accessxi.escape_probe_log_text(accessxi.probe_strings_at(ptr)),
        accessxi.escape_probe_log_text(accessxi.status_menu_probe_runs(ptr, 0x180)),
        accessxi.escape_probe_log_text_wide(accessxi.format_probe_dwords(ptr, 0, 40)),
        accessxi.escape_probe_log_text_wide(accessxi.format_probe_bytes(ptr, 0, 0x80))));
end

function accessxi.log_search_result_deep_dump(reason)
    accessxi.menu_dump_sequence = (accessxi.menu_dump_sequence or 0) + 1;
    local seq = accessxi.menu_dump_sequence;
    local menu_name = get_menu_name() or '';
    local obj = get_current_menu_object_ptr();
    local selected, page, raw, child, count = accessxi.survival_guide_query_child_state_for_obj(obj);
    local source = 'current';
    local cached_age = tick() - (tonumber(accessxi.last_search_result_tick) or 0);
    local cached_obj = tonumber(accessxi.last_search_result_obj) or 0;
    if ((not tostring(menu_name or ''):eq('menu    scresult', true))
        and cached_age >= 0
        and cached_age <= 120000
        and accessxi.is_probe_pointer(cached_obj)) then
        source = 'cached-search-result';
        menu_name = tostring(accessxi.last_search_result_menu_name or 'menu    scresult');
        obj = cached_obj;
        child = tonumber(accessxi.last_search_result_child) or 0;
        raw = tonumber(accessxi.last_search_result_raw) or 0;
        selected = tonumber(accessxi.last_search_result_selected) or 0;
        count = tonumber(accessxi.last_search_result_count) or 0;
        page = tonumber(accessxi.last_search_result_page) or 0;
    end
    selected = tonumber(selected) or 0;
    count = tonumber(count) or 0;
    local raw_selected = selected;
    if (selected <= 0) then
        selected = read_current_native_menu_index(0x4C);
    end
    if (count <= 0 or count > 64) then
        count = math.max(tonumber(accessxi.native_menu_index(0x24)) or 0, tonumber(accessxi.native_menu_index(0x28)) or 0);
    end
    local entry = 0;
    if (source == 'cached-search-result') then
        entry = tonumber(accessxi.last_search_result_entry) or 0;
    end
    if (entry == 0) then
        entry = accessxi.is_probe_pointer(obj) and (read_u32(obj + 0x08) or 0) or 0;
    end

    log_line(('searchdump begin seq=%d reason="%s" source="%s" cacheAge=%d menu="%s" obj=0x%08X child=0x%08X raw=0x%08X entry=0x%08X selected=%d count=%d page=%d'):fmt(
        seq,
        accessxi.escape_probe_log_text(reason or ''),
        source,
        cached_age,
        tostring(menu_name or ''),
        tonumber(obj) or 0,
        tonumber(child) or 0,
        tonumber(raw) or 0,
        tonumber(entry) or 0,
        selected,
        count,
        tonumber(page) or 0));

    accessxi.log_search_result_pointer_target(seq, 'obj', obj);
    accessxi.log_search_result_pointer_target(seq, 'child', child);
    accessxi.log_search_result_pointer_target(seq, 'raw', raw);
    accessxi.log_search_result_pointer_target(seq, 'entry', entry);

    for _, base_spec in ipairs(T{
        T{ label = 'obj', ptr = obj, max = 0x90 },
        T{ label = 'child', ptr = child, max = 0x90 },
        T{ label = 'entry', ptr = entry, max = 0x80 },
    }) do
        local base_ptr = tonumber(base_spec.ptr) or 0;
        if (accessxi.is_probe_pointer(base_ptr)) then
            for off = 0, tonumber(base_spec.max) or 0, 4 do
                local target = read_u32(base_ptr + off) or 0;
                if (accessxi.is_probe_pointer(target)) then
                    accessxi.log_search_result_pointer_target(seq, ('%s+%03X'):fmt(base_spec.label, off), target);
                end
            end
        end
    end

    if (accessxi.is_probe_pointer(entry)) then
        log_line(('searchdump seq=%d compactRows "%s"'):fmt(
            seq,
            accessxi.escape_probe_log_text_wide(accessxi.search_result_compact_row_summary(entry, selected, count))));
        log_line(('searchdump seq=%d renderNeighbors "%s"'):fmt(
            seq,
            accessxi.escape_probe_log_text_wide(accessxi.search_result_rendered_neighbor_summary(entry, selected))));
        log_line(('searchdump seq=%d entryPtrs "%s"'):fmt(
            seq,
            accessxi.escape_probe_log_text_wide(accessxi.search_result_pointer_field_summary(entry))));
        for delta = -8, 12 do
            local ptr = entry + (delta * 0x68);
            if (accessxi.is_probe_pointer(ptr)) then
                log_line(('searchdump seq=%d entryCell delta=%+d ptr=0x%08X runs="%s" dwords=%s bytes=%s'):fmt(
                    seq,
                    delta,
                    ptr,
                    accessxi.escape_probe_log_text(accessxi.search_result_inline_runs(ptr)),
                    accessxi.escape_probe_log_text_wide(accessxi.format_probe_dwords(ptr, 0, 12)),
                    accessxi.escape_probe_log_text_wide(accessxi.format_probe_bytes(ptr, 0x20, 0x50))));
            end
        end
    end

    log_line(('searchdump end seq=%d'):fmt(seq));
end

function accessxi.is_search_condition_unity_label(label)
    label = tostring(label or ''):trim();
    if (label == '') then
        return false;
    end

    local lower = label:lower();
    if (lower:find('designate a unity', 1, true) ~= nil) then
        return true;
    end
    if (lower:eq('no unity', true)) then
        return true;
    end

    accessxi.entity_names_data = accessxi.entity_names_data or accessxi.load_module_table('entity_names_data', T{ jobs = {}, nations = {}, unities = {} });
    for _, name in pairs(accessxi.entity_names_data.unities or {}) do
        if (lower == tostring(name or ''):lower()) then
            return true;
        end
    end

    return false;
end

function accessxi.search_condition_unity_option_name(option_index, option_total)
    option_index = tonumber(option_index) or 0;
    option_total = tonumber(option_total) or 0;
    if (option_index <= 0) then
        return '';
    end

    if (option_total == 12 and option_index == 12) then
        return 'No Unity';
    end

    return accessxi.unity_name(option_index);
end

function accessxi.search_condition_unity_context_active()
    local now = tick();
    if (now <= (tonumber(accessxi.search_condition_unity_context_until) or 0)) then
        return true;
    end
    if (accessxi.is_search_condition_unity_label(accessxi.search_condition_unity_context_label or '')) then
        return true;
    end
    if (accessxi.is_search_condition_unity_label(accessxi.last_native_menu_label or '')) then
        return true;
    end
    return false;
end

function accessxi.log_search_condition_arealist_cursor(menu_name, selected, count, child, ank, scroll_offset, scroll_total, scroll_remaining, source)
    if (not tostring(menu_name or ''):eq('menu    arealist', true)) then
        return;
    end

    local obj = get_current_menu_object_ptr();
    local child18 = accessxi.is_probe_pointer(child) and (read_u32(child + 0x18) or 0) or 0;
    local child20 = accessxi.is_probe_pointer(child) and (read_u32(child + 0x20) or 0) or 0;
    local child30 = accessxi.is_probe_pointer(child) and (read_i32(child + 0x30) or 0) or 0;
    local key = ('%s:%d:%d:%d:%d:%d:%d:%d:%d:%d:%d:%d:%d:%d:%d:%s'):fmt(
        tostring(menu_name or ''),
        tonumber(obj) or 0,
        tonumber(selected) or 0,
        tonumber(count) or 0,
        tonumber(ank) or -1,
        read_current_native_menu_index(0x24),
        read_current_native_menu_index(0x28),
        read_current_native_menu_index(0x30),
        read_current_native_menu_index(0x34),
        read_current_native_menu_index(0x4C),
        read_current_native_menu_index(0x50),
        read_current_native_menu_index(0x64),
        tonumber(scroll_offset) or 0,
        tonumber(scroll_total) or 0,
        tonumber(scroll_remaining) or 0,
        tostring(source or ''));
    if (key == tostring(accessxi.last_search_condition_arealist_cursor_log or '')) then
        return;
    end
    accessxi.last_search_condition_arealist_cursor_log = key;

    log_state(('state search-condition arealist-cursor menu="%s" select=%d count=%d ank=%d obj=0x%08X obj24=%d obj28=%d obj30=%d obj34=%d obj4C=%d obj50=%d obj64=%d child=0x%08X child18=0x%08X child20=0x%08X child30=%d scrollOffset=%d scrollTotal=%d scrollRemaining=%d source="%s" context=%s lastLabel="%s" contextLabel="%s"'):fmt(
        tostring(menu_name or ''),
        tonumber(selected) or 0,
        tonumber(count) or 0,
        tonumber(ank) or -1,
        tonumber(obj) or 0,
        read_current_native_menu_index(0x24),
        read_current_native_menu_index(0x28),
        read_current_native_menu_index(0x30),
        read_current_native_menu_index(0x34),
        read_current_native_menu_index(0x4C),
        read_current_native_menu_index(0x50),
        read_current_native_menu_index(0x64),
        tonumber(child) or 0,
        tonumber(child18) or 0,
        tonumber(child20) or 0,
        tonumber(child30) or 0,
        tonumber(scroll_offset) or 0,
        tonumber(scroll_total) or 0,
        tonumber(scroll_remaining) or 0,
        accessxi.escape_probe_log_text(source or ''),
        tostring(accessxi.search_condition_unity_context_active()),
        accessxi.escape_probe_log_text(accessxi.last_native_menu_label or ''),
        accessxi.escape_probe_log_text(accessxi.search_condition_unity_context_label or '')));
end

function accessxi.search_condition_menu_speech(menu_name, title, selected, count, entry, child)
    local target = AshitaCore:GetMemoryManager():GetTarget();
    local ank = tonumber(target ~= nil and safe_call(function () return target:GetWindowAnkNum(); end, -1) or -1) or -1;
    local label_ptr = accessxi.is_probe_pointer(entry) and (read_u32(entry + 0x44) or 0) or 0;
    local help_ptr = accessxi.is_probe_pointer(entry) and (read_u32(entry + 0x40) or 0) or 0;
    local native_label = accessxi.plain_native_menu_label(read_probe_string(label_ptr));
    local native_help = accessxi.plain_native_menu_label(read_probe_string(help_ptr));
    local source = 'direct';

    local list_label = '';
    local list_mode = '';
    if (accessxi.is_probe_pointer(child) and selected > 0 and count > 0 and count <= 256) then
        list_label, list_mode = accessxi.native_query_label_for_selection(child, selected, count, 'plain');
        list_label = accessxi.search_result_clean_text(list_label);
        if (list_label ~= '') then
            native_label = list_label;
            native_help = '';
            source = ('child-list:%s'):fmt(tostring(list_mode or ''));
        end
    end

    if (native_label == '') then
        native_label = accessxi.search_result_clean_text(accessxi.search_result_candidate_from_ptr(label_ptr, 'plain'));
        if (native_label ~= '') then
            source = 'label-candidate';
        end
    end
    if (native_help == '') then
        native_help = accessxi.search_result_clean_text(accessxi.search_result_candidate_from_ptr(help_ptr, 'plain'));
        if (native_help ~= '') then
            if (native_label == '') then
                source = 'help-candidate';
            else
                source = source .. '+help-candidate';
            end
        end
    end

    local label_lc = native_label:lower();
    if (label_lc:find('designate a unity', 1, true) ~= nil) then
        accessxi.search_condition_unity_context_until = tick() + 30000;
        accessxi.search_condition_unity_context_label = native_label;
        log_state(('state search-condition unity-context set menu="%s" label="%s" until=%d'):fmt(
            tostring(menu_name or ''),
            accessxi.escape_probe_log_text(native_label),
            tonumber(accessxi.search_condition_unity_context_until) or 0));
    end

    local scroll_offset = 0;
    local scroll_total = 0;
    local scroll_remaining = 0;
    if (tostring(menu_name or ''):eq('menu    arealist', true) and accessxi.is_probe_pointer(child)) then
        scroll_offset, scroll_total, scroll_remaining = accessxi.search_result_native_scroll_offset(child);
        scroll_offset = tonumber(scroll_offset) or 0;
        scroll_total = tonumber(scroll_total) or 0;
        scroll_remaining = tonumber(scroll_remaining) or 0;
    end

    if (native_label == ''
        and tostring(menu_name or ''):eq('menu    arealist', true)
        and accessxi.search_condition_unity_context_active()) then
        local unity_index = math.max((tonumber(scroll_offset) or 0) + (tonumber(selected) or 0), 0);
        local unity_label = accessxi.search_condition_unity_option_name(unity_index, scroll_total);
        if (unity_index > 0 and unity_label ~= '' and not unity_label:match('^Unity%s+%d+$')) then
            native_label = unity_label;
            native_help = '';
            source = ('unity-dat:%d+%d'):fmt(tonumber(scroll_offset) or 0, tonumber(selected) or 0);
            accessxi.search_condition_unity_context_until = tick() + 30000;
            accessxi.search_condition_unity_context_label = unity_label;
        end
    elseif (native_label == '' and tostring(menu_name or ''):eq('menu    arealist', true)) then
        log_state(('state search-condition unity-context inactive menu="%s" select=%d count=%d until=%d lastLabel="%s"'):fmt(
            tostring(menu_name or ''),
            tonumber(selected) or 0,
            tonumber(count) or 0,
            tonumber(accessxi.search_condition_unity_context_until) or 0,
            accessxi.escape_probe_log_text(accessxi.last_native_menu_label or '')));
    end

    accessxi.log_search_condition_arealist_cursor(menu_name, selected, count, child, ank, scroll_offset, scroll_total, scroll_remaining, source);

    if (native_label ~= '' or native_help ~= '') then
        if (native_label == '') then
            native_label = native_help;
            native_help = '';
        elseif (native_help:eq(native_label, true)) then
            native_help = '';
        end
        accessxi.last_native_menu_name = tostring(menu_name or '');
        accessxi.last_native_menu_label = native_label;
        accessxi.last_native_menu_selected = tonumber(selected) or 0;
        accessxi.last_native_menu_tick = tick();
        accessxi.current_speech_key = ('search-condition-native:%s:%08X:%08X:%08X:%s:%s'):fmt(
            tostring(menu_name or ''),
            tonumber(entry) or 0,
            tonumber(label_ptr) or 0,
            tonumber(help_ptr) or 0,
            native_label,
            native_help);
        log_state(('state search-condition native menu="%s" title="%s" select=%d count=%d entry=0x%08X child=0x%08X ank=%d labelPtr=0x%08X helpPtr=0x%08X label="%s" help="%s" source="%s" entryRuns="%s" helpRuns="%s"'):fmt(
            tostring(menu_name or ''),
            tostring(title or ''),
            tonumber(selected) or 0,
            tonumber(count) or 0,
            tonumber(entry) or 0,
            tonumber(child) or 0,
            ank,
            tonumber(label_ptr) or 0,
            tonumber(help_ptr) or 0,
            accessxi.escape_probe_log_text(native_label),
            accessxi.escape_probe_log_text(native_help),
            accessxi.escape_probe_log_text(source),
            accessxi.escape_probe_log_text(accessxi.search_result_inline_runs(entry)),
            accessxi.escape_probe_log_text(accessxi.search_result_inline_runs(help_ptr))));

        local title_speech = accessxi.sentence_fragment(title);
        local label_speech = accessxi.sentence_fragment(native_label);
        if (native_help ~= '') then
            return ('%s %s %s'):fmt(title_speech, label_speech, accessxi.sentence_fragment(native_help));
        end
        return ('%s %s'):fmt(title_speech, label_speech);
    end

    log_state(('state search-condition missing-native menu="%s" title="%s" select=%d count=%d entry=0x%08X child=0x%08X ank=%d labelPtr=0x%08X helpPtr=0x%08X listMode="%s" entryRuns="%s" helpRuns="%s" helpBytes="%s"'):fmt(
        tostring(menu_name or ''),
        tostring(title or ''),
        tonumber(selected) or 0,
        tonumber(count) or 0,
        tonumber(entry) or 0,
        tonumber(child) or 0,
        ank,
        tonumber(label_ptr) or 0,
        tonumber(help_ptr) or 0,
        accessxi.escape_probe_log_text(list_mode or ''),
        accessxi.escape_probe_log_text(accessxi.search_result_inline_runs(entry)),
        accessxi.escape_probe_log_text(accessxi.search_result_inline_runs(help_ptr)),
        accessxi.escape_probe_log_text_wide(accessxi.format_probe_bytes(help_ptr, 0, 0x50))));
    return nil;
end

function accessxi.linkshell_probe_text_summary(ptr)
    ptr = tonumber(ptr) or 0;
    if (not accessxi.is_probe_pointer(ptr)) then
        return '';
    end

    local parts = T{};
    local direct = accessxi.search_result_clean_text(accessxi.search_result_candidate_from_ptr(ptr, 'plain'));
    if (direct ~= '') then
        parts:append(('candidate="%s"'):fmt(accessxi.escape_probe_log_text(direct)));
    end

    local strings = accessxi.probe_strings_at(ptr);
    if (strings ~= '') then
        parts:append(('strings="%s"'):fmt(accessxi.escape_probe_log_text(strings)));
    end

    local ascii = accessxi.probe_runs_to_text(accessxi.collect_probe_ascii_runs(ptr, 0x240, 3, 6));
    if (ascii ~= '') then
        parts:append(('ascii="%s"'):fmt(accessxi.escape_probe_log_text(ascii)));
    end

    local utf16 = accessxi.probe_runs_to_text(accessxi.collect_probe_utf16_runs(ptr, 0x240, 3, 6));
    if (utf16 ~= '') then
        parts:append(('utf16="%s"'):fmt(accessxi.escape_probe_log_text(utf16)));
    end

    local ffxi16 = accessxi.probe_runs_to_text(accessxi.collect_probe_ffxi_utf16_runs(ptr, 0x240, 3, 8));
    if (ffxi16 ~= '') then
        parts:append(('ffxi16="%s"'):fmt(accessxi.escape_probe_log_text(ffxi16)));
    end

    return parts:concat(' ');
end

function accessxi.log_linkshell_probe_pointer_fields(seq, label, ptr, max_fields)
    ptr = tonumber(ptr) or 0;
    if (not accessxi.is_probe_pointer(ptr)) then
        return;
    end

    max_fields = tonumber(max_fields) or 10;
    local logged = 0;
    local seen = {};
    for off = 0, 0x120, 4 do
        if (logged >= max_fields) then
            return;
        end

        local target = read_u32(ptr + off) or 0;
        if (accessxi.is_probe_pointer(target) and not seen[target]) then
            seen[target] = true;
            local summary = accessxi.linkshell_probe_text_summary(target);
            local desc = read_u32(target + 0x04) or 0;
            local desc_summary = accessxi.linkshell_probe_text_summary(desc);
            if (summary ~= '' or desc_summary ~= '') then
                logged = logged + 1;
                log_state(('state linkshell-probe seq=%d %s+%03X ptr=0x%08X desc=0x%08X dwords=%s text=%s descText=%s'):fmt(
                    tonumber(seq) or 0,
                    tostring(label or ''),
                    off,
                    target,
                    desc,
                    accessxi.format_probe_dwords(target, 0, 16),
                    accessxi.escape_probe_log_text_wide(summary),
                    accessxi.escape_probe_log_text_wide(desc_summary)));
            end
        end
    end
end

function accessxi.log_linkshell_menu_probe(menu_name, title, obj, selected, count, page, raw, child, entry, reason)
    menu_name = tostring(menu_name or '');
    if (not menu_name:eq('menu    link5', true) and not accessxi.is_linkshell_action_family_menu(menu_name)) then
        return;
    end

    obj = tonumber(obj) or 0;
    child = tonumber(child) or 0;
    entry = tonumber(entry) or 0;
    selected = tonumber(selected) or 0;
    count = tonumber(count) or 0;
    local child14 = accessxi.is_probe_pointer(child) and (read_u32(child + 0x14) or 0) or 0;
    local child18 = accessxi.is_probe_pointer(child) and (read_u32(child + 0x18) or 0) or 0;
    local child20 = accessxi.is_probe_pointer(child) and (read_u32(child + 0x20) or 0) or 0;
    local child30 = accessxi.is_probe_pointer(child) and (read_u32(child + 0x30) or 0) or 0;
    local entry0c = accessxi.is_probe_pointer(entry) and (read_u32(entry + 0x0C) or 0) or 0;
    local entry40 = accessxi.is_probe_pointer(entry) and (read_u32(entry + 0x40) or 0) or 0;
    local entry44 = accessxi.is_probe_pointer(entry) and (read_u32(entry + 0x44) or 0) or 0;
    local key = ('%s:%d:%d:%d:%08X:%08X:%08X:%08X:%08X:%08X'):fmt(
        menu_name,
        selected,
        count,
        tonumber(page) or 0,
        tonumber(raw) or 0,
        child,
        entry,
        child14,
        child18,
        entry0c);
    if (key == tostring(accessxi.last_linkshell_menu_probe_key or '')) then
        return;
    end
    accessxi.last_linkshell_menu_probe_key = key;

    accessxi.menu_dump_sequence = (tonumber(accessxi.menu_dump_sequence) or 0) + 1;
    local seq = accessxi.menu_dump_sequence;
    local target = AshitaCore:GetMemoryManager():GetTarget();
    local ank = tonumber(target ~= nil and safe_call(function () return target:GetWindowAnkNum(); end, -1) or -1) or -1;
    local desc = accessxi.is_probe_pointer(obj) and (read_u32(obj + 0x04) or 0) or 0;
    log_state(('state linkshell-probe seq=%d reason="%s" menu="%s" title="%s" select=%d count=%d page=%d raw=0x%08X ank=%d obj=0x%08X desc=0x%08X child=0x%08X entry=0x%08X child14=0x%08X child18=0x%08X child20=0x%08X child30=0x%08X entry0C=0x%08X entry40=0x%08X entry44=0x%08X objIdx="%s" childIdx="%s" entryIdx="%s"'):fmt(
        seq,
        accessxi.escape_probe_log_text(reason or ''),
        menu_name,
        accessxi.escape_probe_log_text(title or ''),
        selected,
        count,
        tonumber(page) or 0,
        tonumber(raw) or 0,
        ank,
        obj,
        desc,
        child,
        entry,
        child14,
        child18,
        child20,
        child30,
        entry0c,
        entry40,
        entry44,
        accessxi.format_probe_index_fields(obj, 0, 0xA0),
        accessxi.format_probe_index_fields(child, 0, 0xA0),
        accessxi.format_probe_index_fields(entry, 0, 0xA0)));

    local roots = T{
        T{ label = 'obj', ptr = obj },
        T{ label = 'desc', ptr = desc },
        T{ label = 'child', ptr = child },
        T{ label = 'entry', ptr = entry },
        T{ label = 'entry0C', ptr = entry0c },
        T{ label = 'entry40', ptr = entry40 },
        T{ label = 'entry44', ptr = entry44 },
        T{ label = 'child14', ptr = child14 },
        T{ label = 'child18', ptr = child18 },
    };
    for _, root in ipairs(roots) do
        local ptr = tonumber(root.ptr) or 0;
        if (accessxi.is_probe_pointer(ptr)) then
            log_state(('state linkshell-probe seq=%d root=%s ptr=0x%08X dwords000=%s dwords040=%s text=%s'):fmt(
                seq,
                tostring(root.label or ''),
                ptr,
                accessxi.format_probe_dwords(ptr, 0, 16),
                accessxi.format_probe_dwords(ptr, 0x40, 16),
                accessxi.escape_probe_log_text_wide(accessxi.linkshell_probe_text_summary(ptr))));
        end
    end

    accessxi.log_linkshell_probe_pointer_fields(seq, 'obj', obj, 12);
    accessxi.log_linkshell_probe_pointer_fields(seq, 'child', child, 12);
    accessxi.log_linkshell_probe_pointer_fields(seq, 'entry', entry, 12);
    accessxi.log_linkshell_probe_pointer_fields(seq, 'entry0C', entry0c, 8);
end

function accessxi.linkshell_native_status_text(child)
    child = tonumber(child) or 0;
    if (not accessxi.is_probe_pointer(child)) then
        return '';
    end

    for _, off in ipairs(T{ 0x3C, 0x60, 0x64, 0x68 }) do
        local ptr = read_u32(child + off) or 0;
        local text = accessxi.search_result_clean_text(read_probe_string(ptr, 180));
        if (text:contains('linkshell', true) or text:contains('linkpearl', true) or text:contains('pearl', true)) then
            return text;
        end
    end

    return '';
end

function accessxi.linkshell_context_name(child)
    child = tonumber(child) or 0;
    if (not accessxi.is_probe_pointer(child)) then
        return '';
    end

    for _, off in ipairs(T{ 0x58, 0x5C, 0x60 }) do
        local ptr = read_u32(child + off) or 0;
        if (accessxi.is_probe_pointer(ptr)) then
            for _, inner in ipairs(T{ 0x00, 0x03, 0x04, 0x18, 0x1A }) do
                local text = accessxi.search_result_clean_text(read_probe_string(ptr + inner, 80));
                if (text ~= ''
                    and not text:contains('linkshell', true)
                    and not text:contains('inventory', true)
                    and not text:contains('messages', true)
                    and not text:contains('listener', true)) then
                    return text;
                end
            end
        end
    end

    return '';
end

function accessxi.parse_linkshell_name_extra(data, offset)
    if (data == nil or type(data) ~= 'string') then
        return '';
    end

    offset = tonumber(offset) or 0;
    local alphabet = 'abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ';
    local out = T{};
    local acc = 0;
    local bits = 0;
    for i = offset + 1, #data do
        acc = (acc * 256) + (string.byte(data, i) or 0);
        bits = bits + 8;
        while (bits >= 6) do
            local shift = bits - 6;
            local div = 2 ^ shift;
            local value = math.floor(acc / div) % 64;
            bits = bits - 6;
            acc = acc % (2 ^ bits);
            if (value >= 1 and value <= #alphabet) then
                out:append(alphabet:sub(value, value));
            end
        end
    end

    return table.concat(out):trim();
end

function accessxi.linkshell_selected_item_speech(selected, child)
    selected = tonumber(selected) or 0;
    local inv = AshitaCore:GetMemoryManager():GetInventory();
    local resources = AshitaCore:GetResourceManager();
    if (inv == nil) then
        return nil;
    end

    local selected_id = tonumber(safe_call(function () return inv:GetSelectedItemId(); end, 0)) or 0;
    local selected_index = tonumber(safe_call(function () return inv:GetSelectedItemIndex(); end, -1)) or -1;
    local display_slot = tonumber(safe_call(function () return inv:GetDisplayItemSlot(); end, -1)) or -1;
    local selected_name = accessxi.search_result_clean_text(safe_call(function () return inv:GetSelectedItemName(); end, '') or '');
    local item_name = selected_name;
    if (resources ~= nil and selected_id > 0) then
        local res = safe_call(function () return resources:GetItemById(selected_id); end, nil);
        if (res ~= nil and res.Name ~= nil) then
            local res_name = accessxi.search_result_clean_text(res.Name[1] or '');
            if (res_name ~= '') then
                item_name = res_name;
            end
        end
    end

    local container = -1;
    local container_slot = -1;
    local link_name = accessxi.linkshell_context_name(child);
    if (selected_index >= 0 and accessxi.inventory_context ~= 'vendor_shop_item_list') then
        container = math.floor(bit.band(selected_index, 0xFF00) / 0x0100);
        container_slot = bit.band(selected_index, 0x00FF);
        local item = safe_call(function () return inv:GetContainerItem(container, container_slot); end, nil);
        local parsed = accessxi.parse_linkshell_name_extra(item ~= nil and item.Extra or nil, 0x09);
        if (parsed ~= '') then
            link_name = parsed;
        end
    end

    if (item_name == '' and selected >= 1 and selected <= 3) then
        item_name = selected == 1 and 'Current linkshell' or (selected == 2 and 'Pearlsack' or 'Linkpearl');
    elseif (item_name:eq('Linkshell', true) and selected == 1) then
        item_name = 'Current linkshell';
    end
    if (item_name == '') then
        return nil;
    end

    local speech = item_name;
    if (link_name ~= '') then
        speech = ('%s. %s'):fmt(item_name, link_name);
    end

    return T{
        speech = speech,
        id = selected_id,
        index = selected_index,
        display_slot = display_slot,
        container = container,
        container_slot = container_slot,
        item_name = item_name,
        link_name = link_name,
    };
end

function accessxi.linkshell_menu_speech(menu_name, title, selected, count, child, entry)
    selected = tonumber(selected) or 0;
    local row_info = accessxi.linkshell_selected_item_speech(selected, child);
    local status = accessxi.linkshell_native_status_text(child);
    if (row_info ~= nil) then
        accessxi.current_speech_key = ('linkshell-row:%d:%d:0x%04X:%d:%s:%s:%s'):fmt(
            selected,
            tonumber(row_info.display_slot) or -1,
            tonumber(row_info.index) or 0,
            tonumber(row_info.id) or 0,
            tostring(row_info.item_name or ''),
            tostring(row_info.link_name or ''),
            status);
        log_state(('state linkshell row menu="%s" title="%s" select=%d count=%d entry=0x%08X child=0x%08X id=%d index=0x%04X displaySlot=%d container=%d containerSlot=%d item="%s" link="%s" context="%s" status="%s"'):fmt(
            tostring(menu_name or ''),
            tostring(title or ''),
            selected,
            tonumber(count) or 0,
            tonumber(entry) or 0,
            tonumber(child) or 0,
            tonumber(row_info.id) or 0,
            tonumber(row_info.index) or 0,
            tonumber(row_info.display_slot) or -1,
            tonumber(row_info.container) or -1,
            tonumber(row_info.container_slot) or -1,
            accessxi.escape_probe_log_text(tostring(row_info.item_name or '')),
            accessxi.escape_probe_log_text(tostring(row_info.link_name or '')),
            accessxi.escape_probe_log_text(accessxi.linkshell_context_name(child)),
            accessxi.escape_probe_log_text(status)));
        return ('%s. %s'):fmt(title, tostring(row_info.speech or ''));
    end

    if (status ~= '') then
        accessxi.current_speech_key = ('linkshell-status:%d:%d:%s'):fmt(
            selected,
            tonumber(count) or 0,
            status);
        log_state(('state linkshell native-status menu="%s" title="%s" select=%d count=%d entry=0x%08X child=0x%08X text="%s"'):fmt(
            tostring(menu_name or ''),
            tostring(title or ''),
            selected,
            tonumber(count) or 0,
            tonumber(entry) or 0,
            tonumber(child) or 0,
            accessxi.escape_probe_log_text(status)));
        return ('%s. %s'):fmt(title, accessxi.sentence_fragment(status));
    end

    return nil;
end

function accessxi.linkshell_action_menu_speech(menu_name, title, selected, count, entry)
    selected = tonumber(selected) or 0;
    count = tonumber(count) or 0;
    entry = tonumber(entry) or 0;
    if (not accessxi.is_probe_pointer(entry)) then
        return nil;
    end

    local label_ptr = read_u32(entry + 0x44) or 0;
    local label_text = accessxi.plain_native_menu_label(read_probe_string(label_ptr, 120));
    if (label_text == '') then
        label_text = accessxi.search_result_clean_text(accessxi.search_result_candidate_from_ptr(label_ptr, 'plain'));
    end

    local help_ptr = read_u32(entry + 0x40) or 0;
    local help_text = accessxi.plain_native_menu_label(read_probe_string(help_ptr, 220));
    if (help_text == '') then
        help_text = accessxi.search_result_clean_text(accessxi.search_result_candidate_from_ptr(help_ptr, 'plain'));
    end
    if (label_text == '' and help_text == '') then
        log_state(('state linkshell action-missing menu="%s" title="%s" select=%d count=%d entry=0x%08X labelPtr=0x%08X helpPtr=0x%08X labelRuns="%s" helpRuns="%s"'):fmt(
            tostring(menu_name or ''),
            tostring(title or ''),
            selected,
            count,
            entry,
            tonumber(label_ptr) or 0,
            tonumber(help_ptr) or 0,
            accessxi.escape_probe_log_text(accessxi.search_result_inline_runs(label_ptr)),
            accessxi.escape_probe_log_text(accessxi.search_result_inline_runs(help_ptr))));
        return nil;
    end

    local speech_text = label_text;
    if (speech_text == '') then
        speech_text = help_text;
    elseif (help_text ~= '' and not help_text:eq(label_text, true)) then
        speech_text = ('%s %s'):fmt(accessxi.sentence_fragment(label_text), accessxi.sentence_fragment(help_text));
    end

    accessxi.last_native_menu_name = tostring(menu_name or '');
    accessxi.last_native_menu_label = speech_text;
    accessxi.last_native_menu_selected = selected;
    accessxi.last_native_menu_tick = tick();
    accessxi.current_speech_key = ('linkshell-action:%s:%d:%d:0x%08X:0x%08X:0x%08X:%s:%s'):fmt(
        tostring(menu_name or ''),
        selected,
        count,
        entry,
        tonumber(label_ptr) or 0,
        tonumber(help_ptr) or 0,
        label_text,
        help_text);
    log_state(('state linkshell action menu="%s" title="%s" select=%d count=%d entry=0x%08X labelPtr=0x%08X helpPtr=0x%08X label="%s" help="%s"'):fmt(
        tostring(menu_name or ''),
        tostring(title or ''),
        selected,
        count,
        entry,
        tonumber(label_ptr) or 0,
        tonumber(help_ptr) or 0,
        accessxi.escape_probe_log_text(label_text),
        accessxi.escape_probe_log_text(help_text)));
    return ('%s. %s'):fmt(title, accessxi.sentence_fragment(speech_text));
end

function accessxi.log_region_info_menu_probe(menu_name, title, selected, count, child, entry, reason)
    menu_name = tostring(menu_name or '');
    if (not menu_name:eq('menu    region', true)) then
        return;
    end

    selected = tonumber(selected) or 0;
    count = tonumber(count) or 0;
    child = tonumber(child) or 0;
    entry = tonumber(entry) or 0;
    local desc = accessxi.is_probe_pointer(entry) and (read_u32(entry + 0x0C) or 0) or 0;
    local row0 = accessxi.is_probe_pointer(desc) and (read_u32(desc + 0x00) or 0) or 0;
    local row2 = accessxi.is_probe_pointer(desc) and (read_u32(desc + 0x08) or 0) or 0;
    local label_ptr = accessxi.is_probe_pointer(entry) and (read_u32(entry + 0x44) or 0) or 0;
    local help_ptr = accessxi.is_probe_pointer(entry) and (read_u32(entry + 0x40) or 0) or 0;
    local key = ('%s:%d:%d:%08X:%08X:%08X:%s'):fmt(
        menu_name,
        selected,
        count,
        entry,
        desc,
        child,
        tostring(reason or ''));
    if (key == tostring(accessxi.last_region_info_probe_key or '')) then
        return;
    end
    accessxi.last_region_info_probe_key = key;

    log_state(('state region-probe reason="%s" menu="%s" title="%s" select=%d count=%d child=0x%08X entry=0x%08X desc=0x%08X row0=0x%08X row2=0x%08X labelPtr=0x%08X helpPtr=0x%08X entryDwords="%s" descDwords="%s" row0Text="%s" row2Text="%s" entryRuns="%s" descRuns="%s" entryFields="%s" descFields="%s" childDwords="%s" childRuns="%s" childFields="%s"'):fmt(
        accessxi.escape_probe_log_text(reason or ''),
        menu_name,
        accessxi.escape_probe_log_text(title or ''),
        selected,
        count,
        child,
        entry,
        desc,
        row0,
        row2,
        label_ptr,
        help_ptr,
        accessxi.escape_probe_log_text(accessxi.format_probe_dwords(entry, 0, 24)),
        accessxi.escape_probe_log_text(accessxi.format_probe_dwords(desc, 0, 16)),
        accessxi.escape_probe_log_text(read_probe_string(row0, 180)),
        accessxi.escape_probe_log_text(read_probe_string(row2, 220)),
        accessxi.escape_probe_log_text(accessxi.status_menu_probe_runs(entry, 0x180)),
        accessxi.escape_probe_log_text(accessxi.status_menu_probe_runs(desc, 0x180)),
        accessxi.escape_probe_log_text(accessxi.status_menu_probe_pointer_fields(entry)),
        accessxi.escape_probe_log_text(accessxi.status_menu_probe_pointer_fields(desc)),
        accessxi.escape_probe_log_text(accessxi.format_probe_dwords(child, 0, 32)),
        accessxi.escape_probe_log_text(accessxi.status_menu_probe_runs(child, 0x180)),
        accessxi.escape_probe_log_text(accessxi.status_menu_probe_pointer_fields(child))));
end

function accessxi.region_info_menu_speech(menu_name, title, selected, count, child, entry)
    selected = tonumber(selected) or 0;
    count = tonumber(count) or 0;
    entry = tonumber(entry) or 0;
    if (not accessxi.is_probe_pointer(entry)) then
        return nil;
    end

    local label_ptr = read_u32(entry + 0x44) or 0;
    local help_ptr = read_u32(entry + 0x40) or 0;
    local label = accessxi.plain_native_menu_label(read_probe_string(label_ptr, 140));
    local help = accessxi.plain_native_menu_label(read_probe_string(help_ptr, 220));
    local description, row2, desc = accessxi.status_menu_native_description_for_entry(entry);
    local generic_help = 'View the balance of power for each region.';
    if (help:eq(generic_help, true)) then
        help = '';
    end
    if (description:eq(generic_help, true)) then
        description = '';
    end

    local row0 = accessxi.is_probe_pointer(desc) and (read_u32(desc + 0x00) or 0) or 0;
    local region_id = accessxi.is_probe_pointer(row0) and (read_u32(row0 + 0x04) or -1) or -1;
    local region_name = accessxi.region_name_for_id(region_id);
    if (region_name ~= '') then
        accessxi.current_region_info_region_id = region_id;
        accessxi.current_region_info_region_name = region_name;
        accessxi.current_region_info_tick = tick();
    end

    local speech = '';
    if (region_name ~= '') then
        speech = region_name;
    elseif (label ~= '') then
        speech = label;
        if (help ~= '' and not help:eq(label, true)) then
            speech = ('%s %s'):fmt(accessxi.sentence_fragment(label), accessxi.sentence_fragment(help));
        end
    elseif (description ~= '') then
        speech = description;
    elseif (help ~= '') then
        speech = help;
    end

    if (speech == '') then
        accessxi.log_region_info_menu_probe(menu_name, title, selected, count, child, entry, 'generic-or-empty');
        return nil;
    end

    if (speech ~= '') then
        accessxi.last_native_menu_name = tostring(menu_name or '');
        accessxi.last_native_menu_label = speech;
        accessxi.last_native_menu_selected = selected;
        accessxi.last_native_menu_tick = tick();
        accessxi.current_speech_key = ('region-info:%s:%d:%d:0x%08X:0x%08X:0x%08X:%d:%s'):fmt(
            tostring(menu_name or ''),
            selected,
            count,
            entry,
            tonumber(label_ptr) or 0,
            tonumber(row2) or 0,
            tonumber(region_id) or -1,
            speech);
        log_state(('state region native menu="%s" title="%s" select=%d count=%d entry=0x%08X labelPtr=0x%08X helpPtr=0x%08X desc=0x%08X row0=0x%08X row2=0x%08X regionId=%d regionName="%s" label="%s" help="%s" text="%s"'):fmt(
            tostring(menu_name or ''),
            tostring(title or ''),
            selected,
            count,
            entry,
            tonumber(label_ptr) or 0,
            tonumber(help_ptr) or 0,
            tonumber(desc) or 0,
            tonumber(row0) or 0,
            tonumber(row2) or 0,
            tonumber(region_id) or -1,
            accessxi.escape_probe_log_text(region_name),
            accessxi.escape_probe_log_text(label),
            accessxi.escape_probe_log_text(help),
            accessxi.escape_probe_log_text(speech)));
        return ('%s. %s'):fmt(title, accessxi.sentence_fragment(speech));
    end

    accessxi.log_region_info_menu_probe(menu_name, title, selected, count, child, entry, 'missing-native');
    return nil;
end

function accessxi.inline_info_text_candidate(text, mode)
    text = accessxi.survival_guide_text(text or '');
    if (text == '' or #text < 4 or #text > 180) then
        return '';
    end
    if (text:find('menu    ', 1, true) ~= nil or text:find('keytops', 1, true) ~= nil) then
        return '';
    end
    if (text:match('^[%p%s%d]+$') ~= nil) then
        return '';
    end
    local lower = text:lower();
    if (lower:find('controller', 1, true) ~= nil) then
        return '';
    end
    if (tostring(mode or '') == 'records-of-eminence') then
        if (text:match('%a') == nil) then
            return '';
        end
        if (text:find(' ', 1, true) == nil and #text < 10) then
            return '';
        end
        return accessxi.plain_native_menu_help(text);
    end
    local regionish = lower:find('conquest', 1, true) ~= nil
        or lower:find('region', 1, true) ~= nil
        or lower:match('%f[%a]control%f[^%a]') ~= nil
        or lower:match('%f[%a]controlled%f[^%a]') ~= nil
        or lower:find('influence', 1, true) ~= nil
        or lower:find('point', 1, true) ~= nil
        or lower:find('san d', 1, true) ~= nil
        or lower:find('bastok', 1, true) ~= nil
        or lower:find('windurst', 1, true) ~= nil
        or lower:find('beastmen', 1, true) ~= nil;
    if (not regionish) then
        return '';
    end
    return accessxi.plain_native_menu_help(text);
end

function accessxi.inline_info_collect_strings(ptr, label, seen, parts, mode)
    ptr = tonumber(ptr) or 0;
    if (not accessxi.is_probe_pointer(ptr)) then
        return;
    end
    seen = seen or {};
    parts = parts or T{};
    if (seen[ptr] == true) then
        return;
    end
    seen[ptr] = true;

    local direct = accessxi.inline_info_text_candidate(read_probe_string(ptr, 180), mode);
    if (direct ~= '') then
        parts:append(('%s+000="%s"'):fmt(label, direct));
    end

    local ascii_runs = accessxi.collect_probe_ascii_runs(ptr, 0x220, 4, 12);
    for _, run in ipairs(ascii_runs) do
        local text = tostring(run or ''):match('="(.*)"$') or '';
        text = accessxi.inline_info_text_candidate(text, mode);
        if (text ~= '') then
            parts:append(('%s%s'):fmt(label, run:gsub('=".*"$', ('="%s"'):fmt(accessxi.escape_probe_log_text(text)))));
        end
    end

    local utf16_entries = accessxi.collect_probe_ffxi_utf16_entries(ptr, 0x220, 4, 12);
    for _, entry in ipairs(utf16_entries) do
        local text = accessxi.inline_info_text_candidate(entry.text or '', mode);
        if (text ~= '') then
            parts:append(('%s+%03X="%s"'):fmt(label, tonumber(entry.offset) or 0, accessxi.escape_probe_log_text(text)));
        end
    end
end

function accessxi.inline_info_collect_window_shape_strings(seen, parts, mode)
    local target = safe_call(function () return AshitaCore:GetMemoryManager():GetTarget(); end, nil);
    if (target == nil) then
        return '';
    end

    local ank_num = tonumber(safe_call(function () return target:GetWindowAnkNum(); end, -1)) or -1;
    local ank_x = tonumber(safe_call(function () return target:GetWindowAnkX(); end, -1)) or -1;
    local ank_y = tonumber(safe_call(function () return target:GetWindowAnkY(); end, -1)) or -1;
    local shape_limit = math.min(15, math.max(4, ank_num + 4));
    local summaries = T{};
    for i = 0, shape_limit do
        local shape = tonumber(safe_call(function () return target:GetWindowAnkShape(i); end, 0)) or 0;
        if (shape ~= 0) then
            local dwords = '';
            local runs = '';
            local fields = '';
            if (accessxi.is_probe_pointer(shape)) then
                accessxi.inline_info_collect_strings(shape, ('shape%d'):fmt(i), seen, parts, mode);
                dwords = accessxi.format_probe_dwords(shape, 0, 12);
                runs = accessxi.status_menu_probe_runs(shape, 0x180);
                fields = accessxi.status_menu_probe_pointer_fields(shape);
            end
            summaries:append(('%d=0x%08X d="%s" runs="%s" fields="%s"'):fmt(
                i,
                shape,
                accessxi.escape_probe_log_text(dwords),
                accessxi.escape_probe_log_text_wide(runs),
                accessxi.escape_probe_log_text_wide(fields)));
        end
    end

    return ('ankNum=%d ank=(%d,%d) shapes=%s'):fmt(ank_num, ank_x, ank_y, summaries:concat(' || '));
end

function accessxi.inline_info_candidate_value(candidate)
    candidate = tostring(candidate or '');
    return candidate:match('="(.*)"$') or candidate:match("='(.*)'$") or '';
end

function accessxi.records_of_eminence_inline_text_fragment_ok(text, row)
    text = accessxi.plain_native_menu_help(text or '');
    if (text == '' or #text < 4) then
        return false;
    end

    local source = accessxi.sgscan_source_for_context(text);
    if (source ~= 'candidate') then
        return false;
    end

    local lower = text:lower();
    for _, token in ipairs(T{
        'settings', 'connection', 'screenshot', 'config', 'controller', 'cambria',
        'accessxi', 'ffxi-menu-reader', 'menu    ', 'menu inline',
    }) do
        if (lower:find(token, 1, true) ~= nil) then
            return false;
        end
    end
    if (text:match('^%s*[%x,]+%s*$') ~= nil or text:match('%x%x,%x%x,%x%x,%x%x') ~= nil) then
        return false;
    end

    local label = tostring(type(row) == 'table' and (row.label or (type(row.record) == 'table' and row.record.label or '') or '') or '');
    if (label ~= '' and lower:find(label:lower(), 1, true) ~= nil) then
        return true;
    end
    if (lower:find('records of', 1, true) ~= nil
        or lower:find('eminence', 1, true) ~= nil
        or lower:find('objective', 1, true) ~= nil
        or lower:find('challenge', 1, true) ~= nil) then
        return true;
    end

    return false;
end

function accessxi.records_of_eminence_inline_summary_from_candidates(candidates, row)
    if (type(candidates) ~= 'table') then
        return '', '';
    end

    local parts = T{};
    for _, candidate in ipairs(candidates) do
        local candidate_text = accessxi.inline_info_candidate_value(candidate);
        if (accessxi.records_of_eminence_inline_text_fragment_ok(candidate_text, row)) then
            local duplicate = false;
            for _, existing in ipairs(parts) do
                if (tostring(existing or '') == candidate_text) then
                    duplicate = true;
                    break;
                end
            end
            if (not duplicate) then
                parts:append(candidate_text);
            end
        end
    end

    if (#parts <= 0) then
        return '', '';
    end

    local joined = accessxi.plain_native_menu_help(parts:concat(' '));
    if (joined == '') then
        return '', '';
    end

    local lower_joined = joined:lower();
    local label = tostring(type(row) == 'table' and (row.label or (type(row.record) == 'table' and row.record.label or '') or '') or '');
    local anchored = lower_joined:find('records of', 1, true) ~= nil
        or lower_joined:find('eminence', 1, true) ~= nil
        or lower_joined:find('objective', 1, true) ~= nil
        or lower_joined:find('challenge', 1, true) ~= nil
        or (label ~= '' and lower_joined:find(label:lower(), 1, true) ~= nil);
    if (not anchored) then
        return '', parts:concat(' | ');
    end

    return joined, parts:concat(' | ');
end

function accessxi.log_inline_info_menu_probe(menu_name, title, obj, selected, count, page, raw, child, entry, reason, candidates, shape_summary)
    obj = tonumber(obj) or 0;
    child = tonumber(child) or 0;
    entry = tonumber(entry) or 0;
    local key = ('%s:%08X:%08X:%08X:%d:%d:%s:%s'):fmt(
        tostring(menu_name or ''),
        obj,
        child,
        entry,
        tonumber(selected) or 0,
        tonumber(count) or 0,
        tostring(reason or ''),
        tostring(candidates or ''));
    if (key == tostring(accessxi.last_inline_info_probe_key or '')) then
        return;
    end
    accessxi.last_inline_info_probe_key = key;

    log_state(('state inline-info-probe reason="%s" menu="%s" title="%s" select=%d count=%d page=%d raw=0x%08X obj=0x%08X child=0x%08X entry=0x%08X objDwords="%s" childDwords="%s" entryDwords="%s" objRuns="%s" childRuns="%s" entryRuns="%s" objFields="%s" childFields="%s" entryFields="%s" shapes="%s" candidates="%s"'):fmt(
        accessxi.escape_probe_log_text(reason or ''),
        tostring(menu_name or ''),
        accessxi.escape_probe_log_text(title or ''),
        tonumber(selected) or 0,
        tonumber(count) or 0,
        tonumber(page) or 0,
        tonumber(raw) or 0,
        obj,
        child,
        entry,
        accessxi.escape_probe_log_text(accessxi.format_probe_dwords(obj, 0, 40)),
        accessxi.escape_probe_log_text(accessxi.format_probe_dwords(child, 0, 40)),
        accessxi.escape_probe_log_text(accessxi.format_probe_dwords(entry, 0, 40)),
        accessxi.escape_probe_log_text_wide(accessxi.status_menu_probe_runs(obj, 0x220)),
        accessxi.escape_probe_log_text_wide(accessxi.status_menu_probe_runs(child, 0x220)),
        accessxi.escape_probe_log_text_wide(accessxi.status_menu_probe_runs(entry, 0x220)),
        accessxi.escape_probe_log_text_wide(accessxi.status_menu_probe_pointer_fields(obj)),
        accessxi.escape_probe_log_text_wide(accessxi.status_menu_probe_pointer_fields(child)),
        accessxi.escape_probe_log_text_wide(accessxi.status_menu_probe_pointer_fields(entry)),
        accessxi.escape_probe_log_text_wide(shape_summary or ''),
        accessxi.escape_probe_log_text_wide(candidates or '')));
end

function accessxi.inline_info_menu_speech(menu_name, title, selected, count, page, raw, child, entry, obj)
    local seen = {};
    local candidates = T{};
    local roe_inline_row = accessxi.records_of_eminence_inline_context_row ~= nil and accessxi.records_of_eminence_inline_context_row() or nil;
    local mode = type(roe_inline_row) == 'table' and 'records-of-eminence' or '';
    accessxi.inline_info_collect_strings(obj, 'obj', seen, candidates, mode);
    if (mode ~= 'records-of-eminence') then
        accessxi.inline_info_collect_strings(child, 'child', seen, candidates, mode);
        accessxi.inline_info_collect_strings(entry, 'entry', seen, candidates, mode);
    end
    local shape_summary = accessxi.inline_info_collect_window_shape_strings(seen, candidates, mode);

    local speech = '';
    local roe_fragments = '';
    if (mode == 'records-of-eminence') then
        speech, roe_fragments = accessxi.records_of_eminence_inline_summary_from_candidates(candidates, roe_inline_row);
    elseif (#candidates > 0) then
        local first = tostring(candidates[1] or '');
        speech = accessxi.inline_info_candidate_value(first);
    end

    if (speech ~= '') then
        accessxi.last_native_menu_name = tostring(menu_name or '');
        accessxi.last_native_menu_label = speech;
        accessxi.last_native_menu_selected = tonumber(selected) or 0;
        accessxi.last_native_menu_tick = tick();
        accessxi.current_speech_key = ('inline-info:%s:%s:%d:%d:0x%08X:0x%08X:0x%08X:%s'):fmt(
            tostring(menu_name or ''),
            mode,
            tonumber(selected) or 0,
            tonumber(count) or 0,
            tonumber(obj) or 0,
            tonumber(child) or 0,
            tonumber(entry) or 0,
            speech);
        log_state(('state inline-info native menu="%s" title="%s" select=%d count=%d obj=0x%08X child=0x%08X entry=0x%08X text="%s" candidates="%s"'):fmt(
            tostring(menu_name or ''),
            tostring(title or ''),
            tonumber(selected) or 0,
            tonumber(count) or 0,
            tonumber(obj) or 0,
            tonumber(child) or 0,
            tonumber(entry) or 0,
            accessxi.escape_probe_log_text(speech),
            accessxi.escape_probe_log_text_wide(candidates:concat(' | '))));
        return ('%s. %s'):fmt(title, accessxi.sentence_fragment(speech));
    end

    if (mode == 'records-of-eminence' and #candidates > 0) then
        log_state(('state inline-info roe-refused menu="%s" title="%s" select=%d count=%d obj=0x%08X child=0x%08X entry=0x%08X fragments="%s" candidates="%s"'):fmt(
            tostring(menu_name or ''),
            accessxi.escape_probe_log_text(title or ''),
            tonumber(selected) or 0,
            tonumber(count) or 0,
            tonumber(obj) or 0,
            tonumber(child) or 0,
            tonumber(entry) or 0,
            accessxi.escape_probe_log_text_wide(tostring(roe_fragments or '')),
            accessxi.escape_probe_log_text_wide(candidates:concat(' | '))));
    end
    accessxi.log_inline_info_menu_probe(menu_name, title, obj, selected, count, page, raw, child, entry, 'missing-inline-text', candidates:concat(' | '), shape_summary);
    return nil;
end

function accessxi.log_mog_door_shape_probe(menu_name, title, obj, selected, count, page, raw, child, entry, ank_num, display_selected, display_count, destination)
    if (tick() >= (tonumber(accessxi.mog_door_probe_until) or 0)) then
        return;
    end

    local target = safe_call(function () return AshitaCore:GetMemoryManager():GetTarget(); end, nil);
    local key = ('%s:%d:%d:%d:0x%08X:0x%08X:0x%08X:%s'):fmt(
        tostring(menu_name or ''),
        tonumber(ank_num) or -1,
        tonumber(display_selected) or -1,
        tonumber(display_count) or -1,
        tonumber(obj) or 0,
        tonumber(child) or 0,
        tonumber(entry) or 0,
        tostring(title or ''));
    if (key == tostring(accessxi.last_mog_door_probe_key or '')) then
        return;
    end
    accessxi.last_mog_door_probe_key = key;

    log_line(('mogdoorprobe core menu="%s" title="%s" destination="%s" ank=%d option=%d count=%d selected=%d nativeCount=%d page=%d raw=0x%08X obj=0x%08X child=0x%08X entry=0x%08X'):fmt(
        tostring(menu_name or ''),
        accessxi.escape_probe_log_text(title or ''),
        accessxi.escape_probe_log_text(destination or ''),
        tonumber(ank_num) or -1,
        tonumber(display_selected) or -1,
        tonumber(display_count) or -1,
        tonumber(selected) or 0,
        tonumber(count) or 0,
        tonumber(page) or 0,
        tonumber(raw) or 0,
        tonumber(obj) or 0,
        tonumber(child) or 0,
        tonumber(entry) or 0));

    local function small_fields(ptr, max_off)
        ptr = tonumber(ptr) or 0;
        if (not accessxi.is_scan_address(ptr)) then
            return '';
        end

        local parts = T{};
        for off = 0, max_off or 0x180, 4 do
            local svalue = read_i32(ptr + off);
            local uvalue = read_u32(ptr + off);
            if (svalue ~= nil and svalue >= -16 and svalue <= 512) then
                parts:append(('+%03X=%d'):fmt(off, svalue));
            elseif (uvalue ~= nil) then
                local b0 = bit.band(uvalue, 0xFF);
                local b1 = bit.band(bit.rshift(uvalue, 8), 0xFF);
                local b2 = bit.band(bit.rshift(uvalue, 16), 0xFF);
                local b3 = bit.band(bit.rshift(uvalue, 24), 0xFF);
                if (b0 <= 16 or b1 <= 16 or b2 <= 16 or b3 <= 16) then
                    parts:append(('+%03X.bytes=%d,%d,%d,%d'):fmt(off, b0, b1, b2, b3));
                end
            end
            if (parts:len() >= 96) then
                break;
            end
        end
        return parts:concat(' ');
    end

    log_line(('mogdoorprobe fields obj="%s" child="%s" entry="%s"'):fmt(
        accessxi.escape_probe_log_text(small_fields(obj, 0x1C0)),
        accessxi.escape_probe_log_text(small_fields(child, 0x120)),
        accessxi.escape_probe_log_text(small_fields(entry, 0x180))));

    local sources = T{
        { name = 'obj', ptr = tonumber(obj) or 0 },
        { name = 'child', ptr = tonumber(child) or 0 },
        { name = 'entry', ptr = tonumber(entry) or 0 },
    };
    for _, source in ipairs(sources) do
        local ptr = tonumber(source.ptr) or 0;
        if (accessxi.is_scan_address(ptr)) then
            log_line(('mogdoorprobe %s ptr=0x%08X dwords000=%s dwords080=%s bytes000="%s" inline="%s" runs="%s" ptrs="%s"'):fmt(
                tostring(source.name or ''),
                ptr,
                accessxi.escape_probe_log_text(accessxi.format_probe_dwords(ptr, 0x00, 32)),
                accessxi.escape_probe_log_text(accessxi.format_probe_dwords(ptr, 0x80, 32)),
                accessxi.escape_probe_log_text(accessxi.format_probe_bytes(ptr, 0x00, 0x80)),
                accessxi.escape_probe_log_text(accessxi.status_menu_probe_inline_strings(ptr)),
                accessxi.escape_probe_log_text(accessxi.status_menu_probe_runs(ptr, 0x360)),
                accessxi.escape_probe_log_text(accessxi.status_menu_probe_pointer_fields(ptr))));
        end
    end

    if (target ~= nil) then
        for i = 0, 15 do
            local shape = tonumber(safe_call(function () return target:GetWindowAnkShape(i); end, 0)) or 0;
            if (shape ~= 0) then
                if (accessxi.is_scan_address(shape)) then
                    log_line(('mogdoorprobe shape index=%d ptr=0x%08X dwords000=%s dwords080=%s inline="%s" runs="%s" ptrs="%s"'):fmt(
                        i,
                        shape,
                        accessxi.escape_probe_log_text(accessxi.format_probe_dwords(shape, 0x00, 32)),
                        accessxi.escape_probe_log_text(accessxi.format_probe_dwords(shape, 0x80, 32)),
                        accessxi.escape_probe_log_text(accessxi.status_menu_probe_inline_strings(shape)),
                        accessxi.escape_probe_log_text(accessxi.status_menu_probe_runs(shape, 0x360)),
                        accessxi.escape_probe_log_text(accessxi.status_menu_probe_pointer_fields(shape))));
                    if (accessxi.log_probe_ffxi_menu_text ~= nil) then
                        accessxi.menu_dump_sequence = (accessxi.menu_dump_sequence or 0) + 1;
                        accessxi.log_probe_ffxi_menu_text(accessxi.menu_dump_sequence, ('mogdoor-shape%d'):fmt(i), shape, 0x360, 2, 12);
                    end
                else
                    log_line(('mogdoorprobe shape index=%d value=0x%08X'):fmt(i, shape));
                end
            end
        end
    end
end

function accessxi.log_mog_door_signal_probe(menu_name, title, obj, selected, count, page, raw, child, entry, native_cursor, area_mode, area_reason, area_count)
    if (not tostring(menu_name or ''):eq('menu    mogdoor', true)) then
        return;
    end

    obj = tonumber(obj) or 0;
    child = tonumber(child) or 0;
    entry = tonumber(entry) or 0;
    local target = safe_call(function () return AshitaCore:GetMemoryManager():GetTarget(); end, nil);
    local myroom_callback = tonumber(target ~= nil and safe_call(function () return target:GetMyroomCallback(); end, 0) or 0) or 0;
    local action_callback = tonumber(target ~= nil and safe_call(function () return target:GetActionCallback(); end, 0) or 0) or 0;
    local cancel_callback = tonumber(target ~= nil and safe_call(function () return target:GetCancelCallback(); end, 0) or 0) or 0;
    local server_id = tonumber(target ~= nil and safe_call(function () return target:GetWindowServerId(); end, 0) or 0) or 0;
    local loaded = tonumber(target ~= nil and safe_call(function () return target:GetWindowIsWindowLoaded(); end, 0) or 0) or 0;
