    local sub_y = tonumber(target ~= nil and safe_call(function () return target:GetWindowSubAnkY(); end, -1) or -1) or -1;
    local window_raw = accessxi.mog_door_target_window_raw_signature(target);
    local label_ptr = accessxi.is_probe_pointer(entry) and (read_u32(entry + 0x44) or 0) or 0;
    local help_ptr = accessxi.is_probe_pointer(entry) and (read_u32(entry + 0x40) or 0) or 0;
    local shape = accessxi.is_probe_pointer(entry) and (read_u32(entry + 0x0C) or 0) or 0;
    local desc = accessxi.is_probe_pointer(entry) and (read_u32(entry + 0x04) or 0) or 0;
    local selected2, page2, raw2, child2, count2 = accessxi.survival_guide_query_child_state_for_obj(obj);

    local obj_d00 = accessxi.is_probe_pointer(obj) and accessxi.format_probe_dwords(obj, 0x00, 24) or '';
    local obj_d40 = accessxi.is_probe_pointer(obj) and accessxi.format_probe_dwords(obj, 0x40, 24) or '';
    local obj_d80 = accessxi.is_probe_pointer(obj) and accessxi.format_probe_dwords(obj, 0x80, 24) or '';
    local obj_dc0 = accessxi.is_probe_pointer(obj) and accessxi.format_probe_dwords(obj, 0xC0, 24) or '';
    local child_d00 = accessxi.is_probe_pointer(child) and accessxi.format_probe_dwords(child, 0x00, 24) or '';
    local child_d40 = accessxi.is_probe_pointer(child) and accessxi.format_probe_dwords(child, 0x40, 24) or '';
    local child_d80 = accessxi.is_probe_pointer(child) and accessxi.format_probe_dwords(child, 0x80, 24) or '';
    local entry_d00 = accessxi.is_probe_pointer(entry) and accessxi.format_probe_dwords(entry, 0x00, 24) or '';
    local entry_d40 = accessxi.is_probe_pointer(entry) and accessxi.format_probe_dwords(entry, 0x40, 24) or '';
    local shape_d00 = accessxi.is_probe_pointer(shape) and accessxi.format_probe_dwords(shape, 0x00, 16) or '';
    local desc_text = accessxi.is_probe_pointer(desc) and accessxi.survival_guide_text(read_probe_string(desc + 0x46, 180)) or '';
    local label = accessxi.plain_native_menu_label(read_probe_string(label_ptr, 120));
    local help = accessxi.plain_native_menu_help(read_probe_string(help_ptr, 180));

    local key = ('%d:%d:%d:%d:%d:%d:%08X:%08X:%08X:%08X:%08X:%08X:%08X:%d:%d:%d:%d:%d:%s:%s:%s:%s:%s:%s:%s:%s:%s:%s:%s:%s:%s'):fmt(
