    log_state(('state mogdoor signal menu="%s" title="%s" mode="%s" reason="%s" selected=%d count=%d page=%d raw=0x%08X qSelected=%d qCount=%d qPage=%d qRaw=0x%08X native=%d areaCount=%d ank=%d sub=%d subXY=(%d,%d) myroomCb=0x%08X actionCb=0x%08X cancelCb=0x%08X server=%d loaded=%d hp=%d death=%d obj=0x%08X child=0x%08X qChild=0x%08X entry=0x%08X shape=0x%08X desc=0x%08X labelPtr=0x%08X helpPtr=0x%08X objD00="%s" objD40="%s" objD80="%s" objDC0="%s" childD00="%s" childD40="%s" childD80="%s" entryD00="%s" entryD40="%s" shapeD00="%s" descText="%s" label="%s" help="%s" idx24=%d idx28=%d idx30=%d idx34=%d idx48=%d idx4C=%d idx50=%d idx54=%d idx58=%d idx5C=%d idx60=%d idx64=%d idx68=%d'):fmt(
        tostring(menu_name or ''),
        accessxi.escape_probe_log_text(title or ''),
        area_mode and 'area-list' or 'parent',
        accessxi.escape_probe_log_text(area_reason or ''),
        tonumber(selected) or 0,
        tonumber(count) or 0,
        tonumber(page) or 0,
        tonumber(raw) or 0,
        tonumber(selected2) or 0,
        tonumber(count2) or 0,
        tonumber(page2) or 0,
        tonumber(raw2) or 0,
        tonumber(native_cursor) or 0,
        tonumber(area_count) or 0,
        ank,
        sub,
        sub_x,
        sub_y,
        myroom_callback,
        action_callback,
        cancel_callback,
        server_id,
        loaded,
        hp,
        death,
        obj,
        child,
        tonumber(child2) or 0,
        entry,
        shape,
        desc,
        label_ptr,
        help_ptr,
        accessxi.escape_probe_log_text_wide(obj_d00),
        accessxi.escape_probe_log_text_wide(obj_d40),
        accessxi.escape_probe_log_text_wide(obj_d80),
        accessxi.escape_probe_log_text_wide(obj_dc0),
        accessxi.escape_probe_log_text_wide(child_d00),
        accessxi.escape_probe_log_text_wide(child_d40),
        accessxi.escape_probe_log_text_wide(child_d80),
        accessxi.escape_probe_log_text_wide(entry_d00),
        accessxi.escape_probe_log_text_wide(entry_d40),
        accessxi.escape_probe_log_text_wide(shape_d00),
        accessxi.escape_probe_log_text(desc_text),
        accessxi.escape_probe_log_text(label),
        accessxi.escape_probe_log_text(help),
        read_current_native_menu_index(0x24),
        read_current_native_menu_index(0x28),
