end

accessxi.mog_door_menu_data = accessxi.load_menu_module_table('mog_door', T{
    parent_choices = T{},
    area_return_choice = { label = 'Area you entered from.', dat = '' },
    area_families = T{},
});

function accessxi.mog_door_dat_choice_for_row(row)
    row = tonumber(row) or -1;
    local choices = accessxi.mog_door_menu_data.parent_choices or T{};
    if (row < 1 or row > choices:len()) then
        return nil;
    end

    local choice = choices[row];
    if (choice == nil) then
        return nil;
    end

    return {
        row = row,
        label = accessxi.plain_native_menu_label(choice.label),
        dat = choice.dat,
    };
end

function accessxi.mog_door_dat_choice_for_ank(ank_num)
    ank_num = tonumber(ank_num) or -1;
    if (ank_num < 0 or ank_num > 5) then
        return nil;
    end
    return accessxi.mog_door_dat_choice_for_row(math.floor(ank_num / 2) + 1);
end

function accessxi.mog_door_zone_name(zone)
    zone = tonumber(zone) or 0;
    if (zone <= 0) then
        return '';
    end

    return accessxi.plain_native_menu_label(safe_call(function () return AshitaCore:GetResourceManager():GetString('zones.names', zone); end, '') or '');
end

function accessxi.mog_door_area_choices_for_zone(zone)
    zone = tonumber(zone) or 0;
    local family = '';
    local rows = nil;

    for _, row in ipairs(accessxi.mog_door_menu_data.area_families or T{}) do
        if (accessxi.menu_name_in_list(tostring(zone), row.zones or T{})) then
            family = tostring(row.family or '');
            rows = row.zones;
            break;
        end
    end

    if (rows == nil) then
        return nil, '';
    end

    local return_choice = accessxi.mog_door_menu_data.area_return_choice or { label = 'Area you entered from.', dat = '' };
    local choices = T{ return_choice };
    for _, dat_row in ipairs(rows) do
        local label = accessxi.mog_door_zone_name(dat_row);
        if (label ~= '') then
            choices:append({
                label = label,
                dat = ('ROM\\97\\53.DAT:%d; ROM\\165\\84.DAT:%d'):fmt(dat_row, dat_row),
            });
        end
    end

    return choices, family;
end

function accessxi.mog_door_area_choice_for_row(row, zone)
    row = tonumber(row) or -1;
    local choices, family = accessxi.mog_door_area_choices_for_zone(zone);
    if (choices == nil or row < 1 or row > #choices) then
        return nil;
    end

    local choice = choices[row];
    if (choice == nil) then
        return nil;
    end

    return {
        row = row,
        label = accessxi.plain_native_menu_label(choice.label),
        dat = choice.dat,
        family = family,
    };
end

function accessxi.mog_door_native_state(ank_num)
    local base = get_ffximain_base();
    if (base == 0) then
        return { valid = false, reason = 'no-base' };
    end

    local obj = read_u32(base + 0x6306BC) or 0;
    if (not accessxi.is_probe_pointer(obj)) then
        return { valid = false, reason = 'no-object', obj = obj };
    end

    local vtable = read_u32(obj) or 0;
    local expected_vtable = base + 0x338460;
    if (vtable ~= expected_vtable) then
        return {
            valid = false,
            reason = 'bad-vtable',
            obj = obj,
            vtable = vtable,
            expected_vtable = expected_vtable,
        };
    end

    local control = read_u32(obj + 0x08) or 0;
    local mode = read_u8(obj + 0x18) or 0;
    local count = read_u8(obj + 0x16) or 0;
    local selected_action = read_u8(obj + 0x15) or 0;
    local area_table = read_u32(obj + 0x1C) or 0;
    local cursor4c = accessxi.is_probe_pointer(control) and (read_i32(control + 0x4C) or 0) or 0;
    local cursor5e = accessxi.is_probe_pointer(control) and (read_u16(control + 0x5E) or 0) or 0;
    local row = tonumber(cursor4c) or 0;
    local ank = tonumber(ank_num) or -1;

    if (mode ~= 0 and count > 0) then
        if (row < 1 or row > count) then
            local zero_based = tonumber(cursor5e) or -1;
            if (zero_based >= 0 and zero_based < count) then
                row = zero_based + 1;
            end
        end
        if ((row < 1 or row > count) and ank >= 1 and ank <= count) then
            row = ank;
        end
        if ((row < 1 or row > count) and ank >= 0 and (ank + 1) <= count) then
            row = ank + 1;
        end
    end

    return {
        valid = true,
        obj = obj,
        vtable = vtable,
        control = control,
        mode = mode,
        count = count,
        selected_action = selected_action,
        area_table = area_table,
        cursor4c = tonumber(cursor4c) or 0,
        cursor5e = tonumber(cursor5e) or 0,
        row = tonumber(row) or 0,
    };
end

function accessxi.mog_door_native_area_choice_for_row(row, state)
    row = tonumber(row) or 0;
    state = state or accessxi.mog_door_native_state();
    if (not state.valid or (tonumber(state.mode) or 0) == 0) then
        return nil;
    end

    local count = tonumber(state.count) or 0;
    local table_ptr = tonumber(state.area_table) or 0;
    if (row < 1 or row > count or not accessxi.is_probe_pointer(table_ptr)) then
        return nil;
    end

    local code = read_u16(table_ptr + ((row - 1) * 2)) or 0;
    local label = '';
    local dat = ('mogdoor+0x1C[%d]=0x%04X'):fmt(row, code);
    if (code == 0x0118) then
        label = 'Area you entered from.';
        dat = dat .. '; ROM\\97\\37.DAT:70; ROM\\165\\72.DAT:70';
    elseif (code > 0) then
        label = accessxi.mog_door_zone_name(code);
        dat = dat .. ('; zones.names:%d'):fmt(code);
    end

    label = accessxi.plain_native_menu_label(label);
    if (label == '') then
        return nil;
    end

    return {
        row = row,
        code = code,
        label = label,
        dat = dat,
        family = 'native',
    };
end

function accessxi.mog_door_clear_area_state(reason)
    reason = tostring(reason or '');
    accessxi.mog_door_area_list_until = 0;
    accessxi.mog_door_area_list_obj = 0;
    accessxi.mog_door_area_list_child = 0;
    accessxi.mog_door_area_list_sub = -1;
    accessxi.mog_door_area_list_sub_x = -1;
    accessxi.mog_door_area_list_sub_y = -1;
    accessxi.mog_door_area_list_proof_tick = 0;
    accessxi.mog_door_area_escape_hold = reason:eq('escape', true) and 1 or 0;
    accessxi.mog_door_area_hold_reason = reason;
    accessxi.mog_door_area_pending_until = 0;
    accessxi.mog_door_blank_area_active_until = 0;
    accessxi.mog_door_blank_area_last_row = 0;
    accessxi.mog_door_area_ank_mode_until = 0;
    accessxi.mog_door_area_ank_mode_row = 0;
    accessxi.last_mog_door_area_arm_key = '';
    if (reason:eq('escape', true)) then
        accessxi.mog_door_need_parent_row4 = 1;
    end
    log_state(('state mogdoor area-clear reason="%s"'):fmt(accessxi.escape_probe_log_text(reason)));
end

function accessxi.mog_door_arm_area_state(reason, obj, child, sub, sub_x, sub_y, duration)
    local now = tick();
    accessxi.mog_door_area_list_until = now + (tonumber(duration) or 3000);
    accessxi.mog_door_area_list_obj = tonumber(obj) or 0;
    accessxi.mog_door_area_list_child = tonumber(child) or 0;
    accessxi.mog_door_area_list_sub = tonumber(sub) or -1;
    accessxi.mog_door_area_list_sub_x = tonumber(sub_x) or -1;
    accessxi.mog_door_area_list_sub_y = tonumber(sub_y) or -1;
    accessxi.mog_door_area_list_proof_tick = now;
    accessxi.mog_door_area_escape_hold = 0;
    accessxi.mog_door_area_hold_reason = '';
    accessxi.mog_door_area_pending_until = 0;

    local key = ('%s:%08X:%08X:%d:%d:%d'):fmt(
        tostring(reason or ''),
        tonumber(obj) or 0,
        tonumber(child) or 0,
        tonumber(sub) or -1,
        tonumber(sub_x) or -1,
        tonumber(sub_y) or -1);
    if (key ~= tostring(accessxi.last_mog_door_area_arm_key or '')) then
        accessxi.last_mog_door_area_arm_key = key;
        log_state(('state mogdoor area-arm reason="%s" obj=0x%08X child=0x%08X sub=%d subXY=(%d,%d) until=%d'):fmt(
            accessxi.escape_probe_log_text(reason or ''),
            tonumber(obj) or 0,
            tonumber(child) or 0,
            tonumber(sub) or -1,
            tonumber(sub_x) or -1,
            tonumber(sub_y) or -1,
            tonumber(accessxi.mog_door_area_list_until) or 0));
    end
end

function accessxi.mog_door_remember_cursor(native_cursor, mode)
    accessxi.mog_door_last_cursor4c = tonumber(native_cursor) or 0;
    accessxi.mog_door_last_cursor_mode = tostring(mode or '');
    accessxi.mog_door_last_cursor_tick = tick();
end

function accessxi.mog_door_target_window_raw_signature(target)
    if (target == nil) then
        return '';
    end

    local raw = safe_call(function () return target:GetRawStructureWindow(); end, nil);
    if (raw == nil) then
        return '';
    end

    local function field(name, default)
        return safe_call(function () return raw[name]; end, default);
    end

    local function num_field(name)
        return tonumber(field(name, 0)) or 0;
    end

    local function ptr_field(name)
        return tonumber(safe_call(function ()
            return ffi.cast('uintptr_t', field(name, nil));
        end, 0)) or 0;
    end

    local raw_name = safe_call(function ()
        local value = raw.Name;
        if (type(value) == 'string') then
            return value;
        end
        return ffi.string(value);
    end, '');

    return ('vt=0x%08X base=0x%08X parent=0x%08X input=%d unk0D=%d save=%d repo=%d rawName="%s" server=%d loaded=%d help=0x%08X helpTitle=0x%08X sub=%d ank=%d ankXY=(%d,%d) subXY=(%d,%d)'):fmt(
        ptr_field('VTablePointer'),
        ptr_field('m_BaseObj'),
        ptr_field('m_pParentMCD'),
        num_field('m_InputEnable'),
        num_field('unknown000D'),
        num_field('m_SaveCursol'),
        num_field('m_Reposition'),
        accessxi.escape_probe_log_text(clean_probe_text(raw_name)),
        num_field('ServerId'),
        num_field('IsWindowLoaded'),
        num_field('HelpString'),
        num_field('HelpTitle'),
        num_field('m_Sub'),
        num_field('m_AnkNum'),
        num_field('m_AnkX'),
        num_field('m_AnkY'),
        num_field('m_SubAnkX'),
        num_field('m_SubAnkY'));
end

function accessxi.mog_door_target_window_parent_ptr(target)
    if (target == nil) then
        return 0;
    end

    local raw = safe_call(function () return target:GetRawStructureWindow(); end, nil);
    if (raw == nil) then
        return 0;
    end

    return tonumber(safe_call(function ()
        return ffi.cast('uintptr_t', raw.m_pParentMCD);
    end, 0)) or 0;
end

function accessxi.mog_door_blank_parent_scan(parent)
    parent = tonumber(parent) or 0;
    if (not accessxi.is_probe_pointer(parent)) then
        return '';
    end

    local texts = T{};
    for off = 0, 0x1C0, 4 do
        local ptr = read_u32(parent + off) or 0;
        if (accessxi.is_probe_pointer(ptr)) then
            local found = accessxi.probe_strings_at(ptr);
            if (found ~= '') then
                texts:append(('+%03X=0x%08X{%s}'):fmt(off, ptr, accessxi.escape_probe_log_text_wide(found)));
                if (#texts >= 12) then
                    break;
                end
            end
        end
    end

    return ('parent=0x%08X texts="%s" d00="%s" d40="%s" d80="%s" dC0="%s"'):fmt(
        parent,
        texts:concat(' | '),
        accessxi.format_probe_dwords(parent, 0x00, 16),
        accessxi.format_probe_dwords(parent, 0x40, 16),
        accessxi.format_probe_dwords(parent, 0x80, 16),
        accessxi.format_probe_dwords(parent, 0xC0, 16));
end

function accessxi.log_mog_door_blank_signal_probe(reason, target, obj, ank, ank_x, ank_y, sub, sub_x, sub_y, loaded, server_id, current_zone, area_count, window_name, target_name)
    if ((tonumber(accessxi.mog_door_probe_until) or 0) <= tick()) then
        return;
    end

    local parent = accessxi.mog_door_target_window_parent_ptr(target);
    local raw = accessxi.mog_door_target_window_raw_signature(target);
    local shapes = T{};
    if (target ~= nil) then
        for i = 0, 15 do
            local shape = tonumber(safe_call(function () return target:GetWindowAnkShape(i); end, 0)) or 0;
            if (shape ~= 0) then
                shapes:append(('%d=0x%08X'):fmt(i, shape));
            end
        end
    end

    local parent_summary = '';
    if (accessxi.is_probe_pointer(parent)) then
        parent_summary = ('d00=%s d40=%s d80=%s dC0=%s d100=%s'):fmt(
            accessxi.format_probe_dwords(parent, 0x00, 16),
            accessxi.format_probe_dwords(parent, 0x40, 16),
            accessxi.format_probe_dwords(parent, 0x80, 16),
            accessxi.format_probe_dwords(parent, 0xC0, 16),
            accessxi.format_probe_dwords(parent, 0x100, 16));
    end

    local key = ('%s:%08X:%08X:%d:%d:%d:%d:%d:%d:%d:%d:%d:%s:%s'):fmt(
        tostring(reason or ''),
        tonumber(obj) or 0,
        tonumber(parent) or 0,
        tonumber(ank) or -1,
        tonumber(ank_x) or -1,
        tonumber(ank_y) or -1,
        tonumber(sub) or -1,
        tonumber(sub_x) or -1,
        tonumber(sub_y) or -1,
        tonumber(loaded) or 0,
        tonumber(server_id) or 0,
        tonumber(current_zone) or 0,
        tostring(shapes:concat(',')),
        parent_summary);
    if (key == tostring(accessxi.last_mog_door_blank_signal_key or '')) then
        return;
    end
    accessxi.last_mog_door_blank_signal_key = key;

    log_state(('state mogdoor blank-signal reason="%s" zone=%d areaCount=%d menuObj=0x%08X parent=0x%08X ank=%d ankXY=(%d,%d) sub=%d subXY=(%d,%d) loaded=%d server=%d window="%s" target="%s" raw="%s" shapes="%s" parent="%s"'):fmt(
        accessxi.escape_probe_log_text(reason or ''),
        tonumber(current_zone) or 0,
        tonumber(area_count) or 0,
        tonumber(obj) or 0,
        tonumber(parent) or 0,
        tonumber(ank) or -1,
        tonumber(ank_x) or -1,
        tonumber(ank_y) or -1,
        tonumber(sub) or -1,
        tonumber(sub_x) or -1,
        tonumber(sub_y) or -1,
        tonumber(loaded) or 0,
        tonumber(server_id) or 0,
        accessxi.escape_probe_log_text(window_name or ''),
        accessxi.escape_probe_log_text(target_name or ''),
        accessxi.escape_probe_log_text(raw),
        accessxi.escape_probe_log_text(shapes:concat(',')),
        accessxi.escape_probe_log_text(parent_summary)));
end

function accessxi.mog_door_pointer_text_scan(base, max_offset, max_found)
    base = tonumber(base) or 0;
    max_offset = tonumber(max_offset) or 0x140;
    max_found = tonumber(max_found) or 10;
    if (not accessxi.is_probe_pointer(base)) then
        return '';
    end

    local texts = T{};
    for off = 0, max_offset, 4 do
        local ptr = read_u32(base + off) or 0;
        if (accessxi.is_probe_pointer(ptr)) then
            local found = accessxi.probe_strings_at(ptr);
            if (found ~= '') then
                texts:append(('+%03X=0x%08X{%s}'):fmt(off, ptr, accessxi.escape_probe_log_text_wide(found)));
                if (#texts >= max_found) then
                    break;
                end
            end
        end
    end
    return texts:concat(' | ');
end

function accessxi.log_mog_door_parent_text_probe(parent, reason)
    local now = tick();
    if ((tonumber(accessxi.mog_door_probe_until) or 0) <= now
        and (tonumber(accessxi.mog_door_signal_probe_until) or 0) <= now) then
        return;
    end

    parent = tonumber(parent) or 0;
    if (not accessxi.is_probe_pointer(parent)) then
        return;
    end

    local texts = accessxi.mog_door_pointer_text_scan(parent, 0x1C0, 16);
    local key = ('%s:0x%08X:%s'):fmt(tostring(reason or ''), parent, texts);
    if (key == tostring(accessxi.last_mog_door_parent_text_probe_key or '')) then
        return;
    end
    accessxi.last_mog_door_parent_text_probe_key = key;

    log_state(('state mogdoor parent-text reason="%s" parent=0x%08X texts="%s"'):fmt(
        accessxi.escape_probe_log_text(reason or ''),
        parent,
        accessxi.escape_probe_log_text_wide(texts)));
    log_state(('state mogdoor parent-dwords reason="%s" parent=0x%08X d00="%s" d40="%s" d80="%s" dC0="%s" d100="%s" d140="%s"'):fmt(
        accessxi.escape_probe_log_text(reason or ''),
        parent,
        accessxi.escape_probe_log_text_wide(accessxi.format_probe_dwords(parent, 0x00, 16)),
        accessxi.escape_probe_log_text_wide(accessxi.format_probe_dwords(parent, 0x40, 16)),
        accessxi.escape_probe_log_text_wide(accessxi.format_probe_dwords(parent, 0x80, 16)),
        accessxi.escape_probe_log_text_wide(accessxi.format_probe_dwords(parent, 0xC0, 16)),
        accessxi.escape_probe_log_text_wide(accessxi.format_probe_dwords(parent, 0x100, 16)),
        accessxi.escape_probe_log_text_wide(accessxi.format_probe_dwords(parent, 0x140, 16))));
end

function accessxi.log_mog_door_row_text_probe(menu_name, title, obj, child, entry, selected, count, display_selected, display_count, native_cursor, mode, reason)
    if ((tonumber(accessxi.mog_door_signal_probe_until) or 0) <= tick()) then
        return;
    end

    obj = tonumber(obj) or 0;
    child = tonumber(child) or 0;
    entry = tonumber(entry) or 0;
    selected = tonumber(selected) or 0;
    count = tonumber(count) or 0;
    display_selected = tonumber(display_selected) or 0;
    display_count = tonumber(display_count) or 0;
    native_cursor = tonumber(native_cursor) or 0;

    local label_ptr = accessxi.is_probe_pointer(entry) and (read_u32(entry + 0x44) or 0) or 0;
    local help_ptr = accessxi.is_probe_pointer(entry) and (read_u32(entry + 0x40) or 0) or 0;
    local desc04 = accessxi.is_probe_pointer(entry) and (read_u32(entry + 0x04) or 0) or 0;
    local desc0c = accessxi.is_probe_pointer(entry) and (read_u32(entry + 0x0C) or 0) or 0;
    local desc24 = accessxi.is_probe_pointer(entry) and (read_u32(entry + 0x24) or 0) or 0;
    local label = accessxi.plain_native_menu_label(read_probe_string(label_ptr, 160));
    local help = accessxi.plain_native_menu_help(read_probe_string(help_ptr, 260));
    local d04 = accessxi.is_probe_pointer(desc04) and clean_probe_text(read_probe_string(desc04 + 0x46, 180)) or '';
    local d0c = accessxi.is_probe_pointer(desc0c) and clean_probe_text(read_probe_string(desc0c + 0x46, 180)) or '';
    local d24 = accessxi.is_probe_pointer(desc24) and clean_probe_text(read_probe_string(desc24 + 0x46, 180)) or '';
    local q_display, q_display_mode = accessxi.native_query_label_for_selection(child, display_selected, display_count, 'plain');
    local q_native, q_native_mode = accessxi.native_query_label_for_selection(child, native_cursor, count, 'plain');
    q_display = accessxi.plain_native_menu_label(q_display or '');
    q_native = accessxi.plain_native_menu_label(q_native or '');

    local entry_texts = accessxi.mog_door_pointer_text_scan(entry, 0x180, 12);
    local child_texts = accessxi.mog_door_pointer_text_scan(child, 0x180, 12);
    local key = ('0x%08X:0x%08X:0x%08X:%d:%d:%d:%d:%s:%s:%s:%s:%s:%s:%s:%s'):fmt(
        obj,
        child,
        entry,
        selected,
        count,
        display_selected,
        display_count,
        tostring(mode or ''),
        tostring(reason or ''),
        label,
        help,
        d04,
        d0c,
        q_display,
        q_native);
    if (key == tostring(accessxi.last_mog_door_row_text_probe_key or '')) then
        return;
    end
    accessxi.last_mog_door_row_text_probe_key = key;

    log_state(('state mogdoor row-text menu="%s" title="%s" mode="%s" reason="%s" selected=%d count=%d display=%d/%d cursor4C=%d obj58=%d obj=0x%08X child=0x%08X entry=0x%08X labelPtr=0x%08X helpPtr=0x%08X desc04=0x%08X desc0C=0x%08X desc24=0x%08X label="%s" help="%s" desc04Text="%s" desc0CText="%s" desc24Text="%s" queryDisplay="%s" queryDisplayMode="%s" queryNative="%s" queryNativeMode="%s"'):fmt(
        accessxi.escape_probe_log_text(menu_name or ''),
        accessxi.escape_probe_log_text(title or ''),
        accessxi.escape_probe_log_text(mode or ''),
        accessxi.escape_probe_log_text(reason or ''),
        selected,
        count,
        display_selected,
        display_count,
        native_cursor,
        read_current_native_menu_index(0x58),
        obj,
        child,
        entry,
        label_ptr,
        help_ptr,
        desc04,
        desc0c,
        desc24,
        accessxi.escape_probe_log_text(label),
        accessxi.escape_probe_log_text(help),
        accessxi.escape_probe_log_text(d04),
        accessxi.escape_probe_log_text(d0c),
        accessxi.escape_probe_log_text(d24),
        accessxi.escape_probe_log_text(q_display),
        accessxi.escape_probe_log_text(q_display_mode or ''),
        accessxi.escape_probe_log_text(q_native),
        accessxi.escape_probe_log_text(q_native_mode or '')));
    log_state(('state mogdoor row-text-ptrs obj=0x%08X child=0x%08X entry=0x%08X entryTexts="%s" childTexts="%s" entryD40="%s" entryD80="%s" childD00="%s" childD40="%s"'):fmt(
        obj,
        child,
        entry,
        accessxi.escape_probe_log_text_wide(entry_texts),
        accessxi.escape_probe_log_text_wide(child_texts),
        accessxi.is_probe_pointer(entry) and accessxi.escape_probe_log_text_wide(accessxi.format_probe_dwords(entry, 0x40, 16)) or '',
        accessxi.is_probe_pointer(entry) and accessxi.escape_probe_log_text_wide(accessxi.format_probe_dwords(entry, 0x80, 16)) or '',
        accessxi.is_probe_pointer(child) and accessxi.escape_probe_log_text_wide(accessxi.format_probe_dwords(child, 0x00, 16)) or '',
        accessxi.is_probe_pointer(child) and accessxi.escape_probe_log_text_wide(accessxi.format_probe_dwords(child, 0x40, 16)) or ''));
end

function accessxi.mog_door_blank_menu_probe(reason)
    local target = safe_call(function () return AshitaCore:GetMemoryManager():GetTarget(); end, nil);
    if (target == nil) then
        return false;
    end

    local now = tick();
    local window_name = accessxi.plain_native_menu_label(safe_call(function () return target:GetWindowName(); end, '') or '');
    local target_name = tostring(accessxi.last_target_name or '');
    local myroom_callback = tonumber(safe_call(function () return target:GetMyroomCallback(); end, 0) or 0) or 0;
    local is_door_context = window_name:eq('Door: Back to Town', true)
        or target_name:eq('Door: Back to Town', true)
        or target_name:eq('Door. Back to Town', true);
    if (not is_door_context) then
        accessxi.mog_door_blank_area_active_until = 0;
        accessxi.mog_door_blank_area_last_row = 0;
        accessxi.mog_door_area_ank_mode_until = 0;
        accessxi.mog_door_area_ank_mode_row = 0;
        return false;
    end

    local probe_active = ((tonumber(accessxi.mog_door_signal_probe_until) or 0) > now);
    local skip_diag = false;
    if (not probe_active) then
        if ((tonumber(accessxi.last_mog_door_blank_probe_tick) or 0) + 1000 > now) then
            skip_diag = true;
        else
            accessxi.last_mog_door_blank_probe_tick = now;
        end
    end

    local ank = tonumber(safe_call(function () return target:GetWindowAnkNum(); end, -1) or -1) or -1;
    local ank_x = tonumber(safe_call(function () return target:GetWindowAnkX(); end, -1) or -1) or -1;
    local ank_y = tonumber(safe_call(function () return target:GetWindowAnkY(); end, -1) or -1) or -1;
    local sub = tonumber(safe_call(function () return target:GetWindowSub(); end, -1) or -1) or -1;
    local sub_x = tonumber(safe_call(function () return target:GetWindowSubAnkX(); end, -1) or -1) or -1;
    local sub_y = tonumber(safe_call(function () return target:GetWindowSubAnkY(); end, -1) or -1) or -1;
    local loaded = tonumber(safe_call(function () return target:GetWindowIsWindowLoaded(); end, 0) or 0) or 0;
    local server_id = tonumber(safe_call(function () return target:GetWindowServerId(); end, 0) or 0) or 0;
    local obj = get_current_menu_object_ptr();
    local current_zone = accessxi.current_zone_id();
    local area_choices, area_family = accessxi.mog_door_area_choices_for_zone(current_zone);
    local area_count = (area_choices ~= nil) and #area_choices or 0;
    local last_cursor = tonumber(accessxi.mog_door_last_cursor4c) or 0;
    local last_cursor_mode = tostring(accessxi.mog_door_last_cursor_mode or '');
    local last_cursor_tick = tonumber(accessxi.mog_door_last_cursor_tick) or 0;
    accessxi.log_mog_door_blank_signal_probe(reason, target, obj, ank, ank_x, ank_y, sub, sub_x, sub_y, loaded, server_id, current_zone, area_count, window_name, target_name);

    local native_state = accessxi.mog_door_native_state(ank);
    if (native_state.valid) then
        local native_mode = tonumber(native_state.mode) or 0;
        if (native_mode ~= 0) then
            local native_row = tonumber(native_state.row) or 0;
            local native_count = tonumber(native_state.count) or 0;
            if (native_row >= 1 and native_count > 0 and native_row <= native_count) then
                local area_choice = accessxi.mog_door_native_area_choice_for_row(native_row, native_state);
                if (area_choice ~= nil and tostring(area_choice.label or '') ~= '') then
                    local area_label = tostring(area_choice.label or '');
                    local speech_key = ('mogdoor-native-blank-area:%d:%s'):fmt(native_row, area_label);
                    if (speech_key ~= tostring(accessxi.current_speech_key or '')) then
                        log_state(('state mogdoor native-blank-area reason="%s" obj=0x%08X ctl=0x%08X mode=%d row=%d count=%d table=0x%08X code=0x%04X dat="%s" label="%s"'):fmt(
                            accessxi.escape_probe_log_text(reason or ''),
                            tonumber(native_state.obj) or 0,
                            tonumber(native_state.control) or 0,
                            native_mode,
                            native_row,
                            native_count,
                            tonumber(native_state.area_table) or 0,
                            tonumber(area_choice.code) or 0,
                            accessxi.escape_probe_log_text(area_choice.dat or ''),
                            accessxi.escape_probe_log_text(area_label)));
                    end
                    accessxi.current_speech_key = speech_key;
                    accessxi.mog_door_area_list_obj = tonumber(native_state.obj) or 0;
                    accessxi.mog_door_area_list_child = tonumber(native_state.control) or 0;
                    accessxi.mog_door_area_list_until = now + 3000;
                    accessxi.mog_door_area_pending_until = 0;
                    accessxi.mog_door_area_escape_hold = 0;
                    accessxi.mog_door_area_hold_reason = '';
                    accessxi.mog_door_remember_cursor(native_row, 'area-list');
                    return ('Door. %s'):fmt(accessxi.sentence_fragment(area_label));
                end
            end
        else
            local had_area_state = ((tonumber(accessxi.mog_door_area_pending_until) or 0) > now)
                or ((tonumber(accessxi.mog_door_blank_area_active_until) or 0) > now)
                or ((tonumber(accessxi.mog_door_area_ank_mode_until) or 0) > now);
            if (had_area_state) then
                accessxi.mog_door_clear_area_state('native-blank-parent-state');
            end
        end
    end

    if (obj == 0) then
        local had_area_state = ((tonumber(accessxi.mog_door_area_pending_until) or 0) > now)
            or ((tonumber(accessxi.mog_door_blank_area_active_until) or 0) > now)
            or ((tonumber(accessxi.mog_door_area_ank_mode_until) or 0) > now);
        if (had_area_state) then
            accessxi.mog_door_clear_area_state('blank-no-object');
        end
    end

    if (skip_diag) then
        return true;
    end

    local shape_parts = T{};
    if (probe_active) then
        for i = 0, 6 do
            local shape = tonumber(safe_call(function () return target:GetWindowAnkShape(i); end, 0)) or 0;
            if (shape ~= 0) then
                shape_parts:append(('%d=0x%08X:%s'):fmt(
                    i,
                    shape,
                    accessxi.escape_probe_log_text_wide(accessxi.status_menu_probe_runs(shape, 0x100))));
            end
        end
    end

    local raw_sig = probe_active and accessxi.mog_door_target_window_raw_signature(target) or '';
    local parent_ptr = probe_active and accessxi.mog_door_target_window_parent_ptr(target) or 0;
    local parent_scan = probe_active and accessxi.mog_door_blank_parent_scan(parent_ptr) or '';
    if (probe_active) then
        accessxi.log_mog_door_parent_text_probe(parent_ptr, tostring(reason or 'blank-window'));
    end
    local key = ('%s:%s:%s:%08X:%d:%d:%d:%d:%d:%d:%d:%d:%s:%s'):fmt(
        tostring(reason or ''),
        window_name,
        target_name,
        obj,
        myroom_callback,
        loaded,
        server_id,
        ank,
        ank_x,
        ank_y,
        sub,
        sub_x,
        sub_y,
        raw_sig,
        parent_scan);
    if (key == tostring(accessxi.last_mog_door_blank_probe_key or '')) then
        return true;
    end
    accessxi.last_mog_door_blank_probe_key = key;

    log_state(('state mogdoor blank-window reason="%s" menu="" target="%s" window="%s" obj=0x%08X myroomCb=0x%08X loaded=%d server=%d ank=%d ankXY=(%d,%d) sub=%d subXY=(%d,%d) raw="%s" parentScan="%s" shapes="%s"'):fmt(
        accessxi.escape_probe_log_text(reason or ''),
        accessxi.escape_probe_log_text(target_name),
        accessxi.escape_probe_log_text(window_name),
        obj,
        myroom_callback,
        loaded,
        server_id,
        ank,
        ank_x,
        ank_y,
        sub,
        sub_x,
        sub_y,
        accessxi.escape_probe_log_text(raw_sig),
        accessxi.escape_probe_log_text_wide(parent_scan),
        accessxi.escape_probe_log_text_wide(shape_parts:concat(' | '))));
    return true;
end

function accessxi.mog_door_packet_summary(id, data)
    id = tonumber(id) or 0;
    data = data or '';
    if (id == 0x032) then
        return ('npc=0x%08X npcIndex=%d zone=%d menuId=%d unk1=%d dupeZone=%d'):fmt(
            accessxi.packet_u32(data, 5),
            accessxi.packet_u16(data, 9),
            accessxi.packet_u16(data, 11),
            accessxi.packet_u16(data, 13),
            accessxi.packet_u16(data, 15),
            accessxi.packet_byte(data, 17));
    elseif (id == 0x034) then
        return ('npc=0x%08X npcIndex=%d zone=%d menuId=%d unk1=%d dupeZone=%d params="%s"'):fmt(
            accessxi.packet_u32(data, 5),
            accessxi.packet_u16(data, 41),
            accessxi.packet_u16(data, 43),
            accessxi.packet_u16(data, 45),
            accessxi.packet_u16(data, 47),
            accessxi.packet_u16(data, 49),
            accessxi.packet_hex_limit(data:sub(9, 40), 32));
    elseif (id == 0x05B) then
        return ('target=0x%08X option=%d unk1=%d targetIndex=%d auto=%d unk2=%d zone=%d menuId=%d'):fmt(
            accessxi.packet_u32(data, 5),
            accessxi.packet_u16(data, 9),
            accessxi.packet_u16(data, 11),
            accessxi.packet_u16(data, 13),
            accessxi.packet_byte(data, 15),
            accessxi.packet_byte(data, 16),
            accessxi.packet_u16(data, 17),
            accessxi.packet_u16(data, 19));
    elseif (id == 0x067) then
        return ('spawnX=%.3f spawnZ=%.3f spawnY=%.3f entityId=0x%08X index=%d type=%d unk1=%d'):fmt(
            accessxi.packet_i32(data, 5) / 1000,
            accessxi.packet_i32(data, 9) / 1000,
            accessxi.packet_i32(data, 13) / 1000,
            accessxi.packet_u32(data, 17),
            accessxi.packet_u16(data, 21),
            accessxi.packet_byte(data, 23),
            accessxi.packet_byte(data, 24));
    elseif (id == 0x00D) then
        return ('seq=0x%04X v04=0x%08X v08=0x%04X v0A=0x%04X v0C=0x%04X v20=0x%04X v22=0x%04X nonzero="%s"'):fmt(
            accessxi.packet_u16(data, 3),
            accessxi.packet_u32(data, 5),
            accessxi.packet_u16(data, 9),
            accessxi.packet_u16(data, 11),
            accessxi.packet_u16(data, 13),
            accessxi.packet_u16(data, 33),
            accessxi.packet_u16(data, 35),
            accessxi.packet_nonzero_words(data, 1, 80));
    elseif (id == 0x015) then
        return ('seq=0x%04X posX=0x%08X posY=0x%08X mode=0x%04X arg=0x%04X tick=0x%08X nonzero="%s"'):fmt(
            accessxi.packet_u16(data, 3),
            accessxi.packet_u32(data, 5),
            accessxi.packet_u32(data, 13),
            accessxi.packet_u16(data, 19),
            accessxi.packet_u16(data, 21),
            accessxi.packet_u32(data, 25),
            accessxi.packet_nonzero_words(data, 1, 40));
    end
    return '';
end

function accessxi.trace_mog_door_packet(e, direction)
    local now = tick();
    local id = tonumber(e.id) or 0;
    local menu_name = tostring(get_menu_name() or '');
    if ((tonumber(accessxi.mog_door_packet_trace_until) or 0) <= now) then
        return;
    end

    local trace_count = tonumber(accessxi.mog_door_packet_trace_count) or 0;
    local trace_limit = tonumber(accessxi.mog_door_packet_trace_limit) or 160;
    if (trace_count >= trace_limit) then
        return;
    end

    local data = e.data_modified or e.data or accessxi.packet_event_string(e, 'data_modified', 'size') or accessxi.packet_event_string(e, 'data', 'size') or '';
    local target_name = tostring(accessxi.last_target_name or '');
    local window_name = '';
    local target = safe_call(function () return AshitaCore:GetMemoryManager():GetTarget(); end, nil);
    if (target ~= nil) then
        window_name = accessxi.plain_native_menu_label(safe_call(function () return target:GetWindowName(); end, '') or '');
    end
    local myroom_callback = tonumber(target ~= nil and safe_call(function () return target:GetMyroomCallback(); end, 0) or 0) or 0;

    local is_mog_door = menu_name:eq('menu    mogdoor', true)
        or target_name:eq('Door: Back to Town', true)
        or target_name:eq('Door. Back to Town', true)
        or window_name:eq('Door: Back to Town', true);
    if (not is_mog_door) then
        return;
    end

    local preview_limit = 96;
    local hex_limit = 160;
    if (id == 0x015) then
        preview_limit = 40;
        hex_limit = 40;
    elseif (id == 0x00D) then
        preview_limit = 80;
        hex_limit = 80;
    end

    accessxi.mog_door_packet_trace_count = trace_count + 1;
    log_line(('mogdoor packet trace dir=%s n=%d id=0x%03X len=%d menu="%s" target="%s" window="%s" myroomCb=0x%08X cursor4C=%d obj24=%d obj28=%d obj50=%d obj58=%d obj64=%d active=%s fields="%s" ascii="%s" hex="%s"'):fmt(
        tostring(direction or ''),
        trace_count + 1,
        id,
        #(data or ''),
        accessxi.escape_probe_log_text(menu_name),
        accessxi.escape_probe_log_text(target_name),
        accessxi.escape_probe_log_text(window_name),
        myroom_callback,
        read_current_native_menu_index(0x4C),
        read_current_native_menu_index(0x24),
        read_current_native_menu_index(0x28),
        read_current_native_menu_index(0x50),
        read_current_native_menu_index(0x58),
        read_current_native_menu_index(0x64),
        tostring(menu_name:eq('menu    mogdoor', true) or target_name:eq('Door: Back to Town', true) or window_name:eq('Door: Back to Town', true)),
        accessxi.escape_probe_log_text(accessxi.mog_door_packet_summary(id, data)),
        accessxi.escape_probe_log_text(accessxi.packet_ascii_preview(data, preview_limit)),
        accessxi.packet_hex_limit(data, hex_limit)));
end

function accessxi.capture_mog_door_outgoing_packet(e)
    local id = tonumber(e ~= nil and e.id or 0) or 0;
    if (id ~= 0x005B and id ~= 0x015) then
        return;
    end

    local menu_name = tostring(get_menu_name() or '');
    local target_name = tostring(accessxi.last_target_name or '');
    local window_name = '';
    local target = safe_call(function () return AshitaCore:GetMemoryManager():GetTarget(); end, nil);
    if (target ~= nil) then
        window_name = accessxi.plain_native_menu_label(safe_call(function () return target:GetWindowName(); end, '') or '');
    end

    local is_mog_door = menu_name:eq('menu    mogdoor', true)
        or window_name:eq('Door: Back to Town', true)
        or target_name:eq('Door: Back to Town', true)
        or target_name:eq('Door. Back to Town', true);
    if (not is_mog_door) then
        return;
    end

    local data = e.data_modified or e.data or accessxi.packet_event_string(e, 'data_modified', 'size') or accessxi.packet_event_string(e, 'data', 'size') or '';
    local native_cursor = read_current_native_menu_index(0x4C);
    local native_count = read_current_native_menu_index(0x58);
    local area_choices = accessxi.mog_door_area_choices_for_zone(accessxi.current_zone_id());
    local area_count = (area_choices ~= nil) and #area_choices or 0;

    if (id == 0x015) then
        -- 0x015 fires while the Door parent row is merely highlighted, so it is
        -- not a reliable area-list transition signal.
        return;
    end

    local key = ('%d:%d:%d:%s'):fmt(
        native_cursor,
        area_count,
        get_current_menu_object_ptr(),
        accessxi.packet_hex_limit(data, 24));
    if (key ~= tostring(accessxi.last_mog_door_submit_packet_key or '')) then
        accessxi.last_mog_door_submit_packet_key = key;
        log_state(('state mogdoor packet-submit id=0x%03X cursor4C=%d nativeCount=%d areaCount=%d menu="%s" target="%s" window="%s" hex=%s'):fmt(
            id,
            native_cursor,
            native_count,
            area_count,
            accessxi.escape_probe_log_text(menu_name),
            accessxi.escape_probe_log_text(target_name),
            accessxi.escape_probe_log_text(window_name),
            accessxi.packet_hex_limit(data, 80)));
    end

    if (native_cursor ~= 4) then
        return;
    end

    log_state(('state mogdoor area-submit-probe reason="packet-out-05b-row4" cursor4C=%d nativeCount=%d areaCount=%d'):fmt(
        native_cursor,
        native_count,
        area_count));
    if (area_count > 0) then
        accessxi.mog_door_area_pending_until = tick() + 3500;
    end
end

function accessxi.capture_mog_door_incoming_packet(e)
    local id = tonumber(e ~= nil and e.id or 0) or 0;
    if (id ~= 0x067) then
        return;
    end

    local menu_name = tostring(get_menu_name() or '');
    local target_name = tostring(accessxi.last_target_name or '');
    local window_name = '';
    local target = safe_call(function () return AshitaCore:GetMemoryManager():GetTarget(); end, nil);
    if (target ~= nil) then
        window_name = accessxi.plain_native_menu_label(safe_call(function () return target:GetWindowName(); end, '') or '');
    end

    local is_mog_door = menu_name:eq('menu    mogdoor', true)
        or window_name:eq('Door: Back to Town', true)
        or target_name:eq('Door: Back to Town', true)
        or target_name:eq('Door. Back to Town', true);
    if (not is_mog_door) then
        return;
    end

    local now = tick();
    local trace_active = ((tonumber(accessxi.mog_door_packet_trace_until) or 0) > now)
        or ((tonumber(accessxi.mog_door_probe_until) or 0) > now)
        or ((tonumber(accessxi.mog_door_signal_probe_until) or 0) > now);
    if (not trace_active) then
        return;
    end

    local native_cursor = read_current_native_menu_index(0x4C);
    local area_choices = accessxi.mog_door_area_choices_for_zone(accessxi.current_zone_id());
    local area_count = (area_choices ~= nil) and #area_choices or 0;
    local data = e.data_modified or e.data or accessxi.packet_event_string(e, 'data_modified', 'size') or accessxi.packet_event_string(e, 'data', 'size') or '';
    local hex80 = accessxi.packet_hex_limit(data, 80);
    local key = ('%03X:%d:%d:%08X:%s'):fmt(
        id,
        native_cursor,
        area_count,
        get_current_menu_object_ptr(),
        accessxi.packet_hex_limit(data, 32));
    if (key ~= tostring(accessxi.last_mog_door_067_candidate_key or '')) then
        accessxi.last_mog_door_067_candidate_key = key;
        log_state(('state mogdoor packet-067-candidate id=0x%03X cursor4C=%d nativeCount=%d areaCount=%d menu="%s" target="%s" window="%s" hex=%s'):fmt(
            id,
            native_cursor,
            read_current_native_menu_index(0x58),
            area_count,
            accessxi.escape_probe_log_text(menu_name),
            accessxi.escape_probe_log_text(target_name),
            accessxi.escape_probe_log_text(window_name),
            hex80));
    end

    if (native_cursor ~= 4) then
        return;
    end

    if (key ~= tostring(accessxi.last_mog_door_in_packet_key or '')) then
        accessxi.last_mog_door_in_packet_key = key;
        log_state(('state mogdoor area-reply-probe reason="packet-in-067-row4" id=0x%03X cursor4C=%d nativeCount=%d areaCount=%d menu="%s" target="%s" window="%s" hex=%s'):fmt(
            id,
            native_cursor,
            read_current_native_menu_index(0x58),
            area_count,
            accessxi.escape_probe_log_text(menu_name),
            accessxi.escape_probe_log_text(target_name),
            accessxi.escape_probe_log_text(window_name),
            hex80));
    end
end

function accessxi.mog_door_note_key(key)
    key = tonumber(key) or 0;
    local menu_name = tostring(get_menu_name() or '');
    if (key == VK_ESCAPE and not menu_name:eq('menu    mogdoor', true)) then
        local target = safe_call(function () return AshitaCore:GetMemoryManager():GetTarget(); end, nil);
        local window_name = '';
        if (target ~= nil) then
            window_name = accessxi.plain_native_menu_label(safe_call(function () return target:GetWindowName(); end, '') or '');
        end
        local target_name = tostring(accessxi.last_target_name or '');
        if (window_name:eq('Door: Back to Town', true)
            or target_name:eq('Door: Back to Town', true)
            or target_name:eq('Door. Back to Town', true)) then
            accessxi.mog_door_clear_area_state('escape');
            return true;
        end
    end
    if (not menu_name:eq('menu    mogdoor', true)) then
        return false;
    end

    if (key == VK_ESCAPE) then
        local cursor4c = read_current_native_menu_index(0x4C);
        local native_count = read_current_native_menu_index(0x58);
        local diag_key = ('%d:%d:%d:%08X'):fmt(
            key,
            cursor4c,
            native_count,
            get_current_menu_object_ptr());
        if (diag_key ~= tostring(accessxi.last_mog_door_key_diag or '')) then
            accessxi.last_mog_door_key_diag = diag_key;
            log_state(('state mogdoor key key=0x%02X cursor4C=%d nativeCount=%d obj=0x%08X parent4=0x%08X areaObj=0x%08X areaUntil=%d'):fmt(
                key,
                cursor4c,
                native_count,
                get_current_menu_object_ptr(),
                tonumber(accessxi.mog_door_parent_row4_entry) or 0,
                tonumber(accessxi.mog_door_area_list_obj) or 0,
                tonumber(accessxi.mog_door_area_list_until) or 0));
        end
    end

    if (key == VK_ESCAPE) then
        accessxi.mog_door_clear_area_state('escape');
        return true;
    end

    return false;
end

function accessxi.mog_door_area_mode_for_state(native_cursor, entry, obj, child, sub, sub_x, sub_y, area_count, ank_num, native_state)
    native_cursor = tonumber(native_cursor) or 0;
    entry = tonumber(entry) or 0;
    obj = tonumber(obj) or 0;
    child = tonumber(child) or 0;
    sub = tonumber(sub) or -1;
    sub_x = tonumber(sub_x) or -1;
    sub_y = tonumber(sub_y) or -1;
    area_count = tonumber(area_count) or 0;
    ank_num = tonumber(ank_num) or -1;

    local now = tick();
    native_state = native_state or accessxi.mog_door_native_state(ank_num);
    if (native_state.valid) then
        if ((tonumber(native_state.mode) or 0) ~= 0) then
            local native_count = tonumber(native_state.count) or 0;
            local row = tonumber(native_state.row) or 0;
            if ((row < 1 or (native_count > 0 and row > native_count))
                and native_cursor >= 1
                and (native_count <= 0 or native_cursor <= native_count)) then
                row = native_cursor;
            end
            accessxi.mog_door_area_list_obj = tonumber(native_state.obj) or 0;
            accessxi.mog_door_area_list_child = tonumber(native_state.control) or 0;
            accessxi.mog_door_area_list_until = now + 3000;
            accessxi.mog_door_area_pending_until = 0;
            accessxi.mog_door_area_escape_hold = 0;
            accessxi.mog_door_area_hold_reason = '';
            accessxi.mog_door_remember_cursor(row, 'area-list');
            return true, 'native-mogdoor-state', row;
        end

        if ((tonumber(accessxi.mog_door_area_list_obj) or 0) ~= 0
            or (tonumber(accessxi.mog_door_area_pending_until) or 0) > now
            or (tonumber(accessxi.mog_door_area_ank_mode_until) or 0) > now) then
            accessxi.mog_door_clear_area_state('native-parent-state');
        end
        accessxi.mog_door_remember_cursor(native_cursor, 'parent');
        return false, 'native-mogdoor-parent', native_cursor;
    end

    accessxi.mog_door_remember_cursor(native_cursor, 'parent');
    return false, tostring(native_state.reason or 'native-mogdoor-missing'), native_cursor;
end

function accessxi.mog_door_menu_speech(menu_name, title, obj, selected, count, page, raw, child, entry)
    local target = safe_call(function () return AshitaCore:GetMemoryManager():GetTarget(); end, nil);
    local myroom_callback = tonumber(target ~= nil and safe_call(function () return target:GetMyroomCallback(); end, 0) or 0) or 0;
    local action_callback = tonumber(target ~= nil and safe_call(function () return target:GetActionCallback(); end, 0) or 0) or 0;
    local cancel_callback = tonumber(target ~= nil and safe_call(function () return target:GetCancelCallback(); end, 0) or 0) or 0;
    local ank_num = tonumber(target ~= nil and safe_call(function () return target:GetWindowAnkNum(); end, -1) or -1) or -1;
    local ank_x = tonumber(target ~= nil and safe_call(function () return target:GetWindowAnkX(); end, -1) or -1) or -1;
    local ank_y = tonumber(target ~= nil and safe_call(function () return target:GetWindowAnkY(); end, -1) or -1) or -1;
    local sub = tonumber(target ~= nil and safe_call(function () return target:GetWindowSub(); end, -1) or -1) or -1;
    local sub_x = tonumber(target ~= nil and safe_call(function () return target:GetWindowSubAnkX(); end, -1) or -1) or -1;
    local sub_y = tonumber(target ~= nil and safe_call(function () return target:GetWindowSubAnkY(); end, -1) or -1) or -1;
    local window_name = accessxi.survival_guide_text(target ~= nil and safe_call(function () return target:GetWindowName(); end, '') or '');
    if (window_name ~= '') then
        title = window_name;
    end
    local speech_title = 'Door';
    local destination = '';
    if (tostring(title or '') ~= '') then
        destination = tostring(title or ''):match('^%s*Door:%s*(.-)%s*$') or '';
    end

    local shape_parts = T{};
    if (target ~= nil) then
        for i = 0, 6 do
            local shape = tonumber(safe_call(function () return target:GetWindowAnkShape(i); end, 0)) or 0;
            if (shape ~= 0) then
                local direct = accessxi.is_probe_pointer(shape) and accessxi.status_menu_probe_runs(shape, 0x100) or '';
                shape_parts:append(('%d=0x%08X:%s'):fmt(
                    i,
                    shape,
                    accessxi.escape_probe_log_text_wide(direct)));
            end
        end
    end

    local current_zone = accessxi.current_zone_id();
    local current_zone_name = accessxi.mog_door_zone_name(current_zone);
    local area_choices, area_family = accessxi.mog_door_area_choices_for_zone(current_zone);
    local area_count = (area_choices ~= nil) and #area_choices or 0;
    local native_cursor = read_current_native_menu_index(0x4C);
    local native_area_count = read_current_native_menu_index(0x58);
    local native_state = accessxi.mog_door_native_state(ank_num);
    local native_state_count = native_state.valid and (tonumber(native_state.count) or 0) or 0;
    local area_mode, area_reason, area_row = accessxi.mog_door_area_mode_for_state(native_cursor, entry, obj, child, sub, sub_x, sub_y, area_count, ank_num, native_state);
    local display_selected = area_mode and (tonumber(area_row) or native_cursor) or native_cursor;
    local display_count = area_mode and math.max(native_state_count, area_count, native_area_count, 1) or 4;
    if (display_selected < 1 or display_selected > display_count) then
        display_selected = 0;
    end

        local key = ('%s:%d:%d:%08X:%08X:%08X:%08X:%08X:%08X:%s'):fmt(
        menu_name,
        display_selected,
        display_count,
        tonumber(obj) or 0,
        tonumber(child) or 0,
        tonumber(entry) or 0,
        myroom_callback,
        action_callback,
        cancel_callback,
        tostring(title or ''));
    if (key ~= tostring(accessxi.last_mog_door_key or '')) then
        accessxi.last_mog_door_key = key;
        log_state(('state mogdoor native menu="%s" title="%s" mode="%s" reason="%s" zone=%d zoneName="%s" areaFamily="%s" areaCount=%d nativeObj=0x%08X nativeMode=%d nativeRows=%d nativeRow=%d nativeCtl=0x%08X nativeAreaTable=0x%08X ank=%d ankXY=(%d,%d) sub=%d subXY=(%d,%d) myroomCb=0x%08X actionCb=0x%08X cancelCb=0x%08X option=%d count=%d selected=%d nativeCount=%d cursor4C=%d obj24=%d obj28=%d obj30=%d obj34=%d obj50=%d obj58=%d obj64=%d page=%d raw=0x%08X obj=0x%08X child=0x%08X entry=0x%08X parent1=0x%08X parent4=0x%08X areaObj=0x%08X areaChild=0x%08X areaSub=%d areaSubXY=(%d,%d) areaUntil=%d pendingUntil=%d hold=%d holdReason="%s" shapes="%s"'):fmt(
            menu_name,
            accessxi.escape_probe_log_text(title or ''),
            area_mode and 'area-list' or 'parent',
            tostring(area_reason or ''),
            current_zone,
            accessxi.escape_probe_log_text(current_zone_name),
            accessxi.escape_probe_log_text(area_family or ''),
            area_count,
            tonumber(native_state.obj) or 0,
            tonumber(native_state.mode) or -1,
            tonumber(native_state.count) or 0,
            tonumber(native_state.row) or 0,
            tonumber(native_state.control) or 0,
            tonumber(native_state.area_table) or 0,
            ank_num,
            ank_x,
            ank_y,
            sub,
            sub_x,
            sub_y,
            myroom_callback,
            action_callback,
            cancel_callback,
            display_selected,
            display_count,
            selected,
            count,
            native_cursor,
            read_current_native_menu_index(0x24),
            read_current_native_menu_index(0x28),
            read_current_native_menu_index(0x30),
            read_current_native_menu_index(0x34),
            read_current_native_menu_index(0x50),
            read_current_native_menu_index(0x58),
            read_current_native_menu_index(0x64),
            tonumber(page) or 0,
            tonumber(raw) or 0,
            tonumber(obj) or 0,
            tonumber(child) or 0,
            tonumber(entry) or 0,
            tonumber(accessxi.mog_door_parent_row1_entry) or 0,
            tonumber(accessxi.mog_door_parent_row4_entry) or 0,
            tonumber(accessxi.mog_door_area_list_obj) or 0,
            tonumber(accessxi.mog_door_area_list_child) or 0,
            tonumber(accessxi.mog_door_area_list_sub) or -1,
            tonumber(accessxi.mog_door_area_list_sub_x) or -1,
            tonumber(accessxi.mog_door_area_list_sub_y) or -1,
            tonumber(accessxi.mog_door_area_list_until) or 0,
            tonumber(accessxi.mog_door_area_pending_until) or 0,
            tonumber(accessxi.mog_door_area_escape_hold) or 0,
            accessxi.escape_probe_log_text(accessxi.mog_door_area_hold_reason or ''),
            accessxi.escape_probe_log_text_wide(shape_parts:concat(' | '))));
    end

    if ((tonumber(accessxi.mog_door_signal_probe_until) or 0) > tick()) then
        accessxi.log_mog_door_signal_probe(menu_name, title, obj, selected, count, page, raw, child, entry, native_cursor, area_mode, area_reason, area_count);
    end

    if (display_selected <= 0) then
        return nil;
    end

    local parent_ptr = target ~= nil and accessxi.mog_door_target_window_parent_ptr(target) or 0;
    accessxi.log_mog_door_parent_text_probe(parent_ptr, 'active-row');
    accessxi.log_mog_door_row_text_probe(
        menu_name,
        title,
        obj,
        child,
        entry,
        selected,
        count,
        display_selected,
        display_count,
        native_cursor,
        area_mode and 'area-list' or 'parent',
        area_reason);

    local label_ptr = accessxi.is_probe_pointer(entry) and (read_u32(entry + 0x44) or 0) or 0;
    local help_ptr = accessxi.is_probe_pointer(entry) and (read_u32(entry + 0x40) or 0) or 0;
    local direct_label = accessxi.plain_native_menu_label(read_probe_string(label_ptr, 120));
    local help_text = accessxi.plain_native_menu_help(read_probe_string(help_ptr, 220));
    if (direct_label ~= '' and not area_mode) then
        accessxi.last_native_menu_name = menu_name;
        accessxi.last_native_menu_label = direct_label;
        accessxi.last_native_menu_selected = display_selected;
        accessxi.last_native_menu_tick = tick();
        accessxi.current_speech_key = ('mogdoor-label:%d:%d:0x%08X:%s:%s'):fmt(
            display_selected,
            display_count,
            tonumber(label_ptr) or 0,
            direct_label,
            help_text);
        log_state(('state mogdoor label menu="%s" title="%s" ank=%d option=%d count=%d entry=0x%08X labelPtr=0x%08X helpPtr=0x%08X label="%s" help="%s"'):fmt(
            menu_name,
            accessxi.escape_probe_log_text(title or ''),
            ank_num,
            display_selected,
            display_count,
            tonumber(entry) or 0,
            tonumber(label_ptr) or 0,
            tonumber(help_ptr) or 0,
            accessxi.escape_probe_log_text(direct_label),
            accessxi.escape_probe_log_text(help_text)));
        if (help_text ~= '') then
            return ('%s. %s %s'):fmt(speech_title, accessxi.sentence_fragment(direct_label), accessxi.sentence_fragment(help_text));
        end
        return ('%s. %s'):fmt(speech_title, accessxi.sentence_fragment(direct_label));
    end

    if (area_mode) then
        local area_choice = accessxi.mog_door_native_area_choice_for_row(display_selected, native_state);
        if (area_choice ~= nil and tostring(area_choice.label or '') ~= '') then
            local area_row = tonumber(area_choice.row) or 0;
            local area_label = tostring(area_choice.label or '');
            accessxi.last_native_menu_name = menu_name;
            accessxi.last_native_menu_label = area_label;
            accessxi.last_native_menu_selected = area_row;
            accessxi.last_native_menu_tick = tick();
            local speech_key = ('mogdoor-area:%d:%s'):fmt(
                area_row,
                area_label);
            if (speech_key ~= tostring(accessxi.current_speech_key or '')) then
                log_state(('state mogdoor area-dat-label menu="%s" title="%s" reason="%s" zone=%d zoneName="%s" family="%s" ank=%d cursor4C=%d row=%d count=%d dat="%s" label="%s"'):fmt(
                    menu_name,
                    accessxi.escape_probe_log_text(title or ''),
                    tostring(area_reason or ''),
                    current_zone,
                    accessxi.escape_probe_log_text(current_zone_name),
                    accessxi.escape_probe_log_text(area_choice.family or ''),
                    ank_num,
                    native_cursor,
                    area_row,
                    display_count,
                    accessxi.escape_probe_log_text(area_choice.dat or ''),
                    accessxi.escape_probe_log_text(area_label)));
            end
            accessxi.current_speech_key = speech_key;
            accessxi.log_mog_door_shape_probe(menu_name, title, obj, selected, count, page, raw, child, entry, ank_num, display_selected, display_count, destination);
            return ('%s. %s'):fmt(speech_title, accessxi.sentence_fragment(area_label));
        end

        log_state(('state mogdoor area-unmapped menu="%s" title="%s" reason="%s" zone=%d zoneName="%s" row=%d count=%d'):fmt(
            menu_name,
            accessxi.escape_probe_log_text(title or ''),
            tostring(area_reason or ''),
            current_zone,
            accessxi.escape_probe_log_text(current_zone_name),
            display_selected,
            display_count));
        accessxi.log_mog_door_shape_probe(menu_name, title, obj, selected, count, page, raw, child, entry, ank_num, display_selected, display_count, destination);
        return nil;
    end

    local dat_choice = accessxi.mog_door_dat_choice_for_row(display_selected);
    if (dat_choice ~= nil and tostring(dat_choice.label or '') ~= '') then
        local dat_row = tonumber(dat_choice.row) or 0;
        local dat_label = tostring(dat_choice.label or '');
        accessxi.last_native_menu_name = menu_name;
        accessxi.last_native_menu_label = dat_label;
        accessxi.last_native_menu_selected = dat_row;
        accessxi.last_native_menu_tick = tick();
        local speech_key = ('mogdoor-dat:%d:%s'):fmt(
            dat_row,
            dat_label);
        if (speech_key ~= tostring(accessxi.current_speech_key or '')) then
            log_state(('state mogdoor dat-label menu="%s" title="%s" ank=%d cursor4C=%d row=%d count=%d dat="%s" label="%s"'):fmt(
                menu_name,
                accessxi.escape_probe_log_text(title or ''),
                ank_num,
                native_cursor,
                dat_row,
                display_count,
                accessxi.escape_probe_log_text(dat_choice.dat or ''),
                accessxi.escape_probe_log_text(dat_label)));
        end
        accessxi.current_speech_key = speech_key;
        accessxi.log_mog_door_shape_probe(menu_name, title, obj, selected, count, page, raw, child, entry, ank_num, display_selected, display_count, destination);
        return ('%s. %s'):fmt(speech_title, accessxi.sentence_fragment(dat_label));
    end

    local list_label, list_mode = accessxi.native_query_label_for_selection(child, display_selected, display_count, 'plain');
    if ((list_label == nil or list_label == '') and count > display_count and display_selected <= count) then
        list_label, list_mode = accessxi.native_query_label_for_selection(child, display_selected, count, 'plain');
    end
    list_label = accessxi.plain_native_menu_label(list_label or '');
    if (list_label ~= '') then
        accessxi.last_native_menu_name = menu_name;
        accessxi.last_native_menu_label = list_label;
        accessxi.last_native_menu_selected = display_selected;
        accessxi.last_native_menu_tick = tick();
        accessxi.current_speech_key = ('mogdoor-list:%d:%d:%s:%s'):fmt(
            display_selected,
            display_count,
            tostring(list_mode or ''),
            list_label);
        log_state(('state mogdoor list-label menu="%s" title="%s" ank=%d option=%d count=%d nativeCount=%d mode="%s" label="%s"'):fmt(
            menu_name,
            accessxi.escape_probe_log_text(title or ''),
            ank_num,
            display_selected,
            display_count,
            count,
            tostring(list_mode or ''),
            accessxi.escape_probe_log_text(list_label)));
        return ('%s. %s'):fmt(speech_title, accessxi.sentence_fragment(list_label));
    end

    accessxi.log_mog_door_shape_probe(menu_name, title, obj, selected, count, page, raw, child, entry, ank_num, display_selected, display_count, destination);

    if (destination ~= '') then
        local speech = ('%s. %s'):fmt(speech_title, accessxi.sentence_fragment(destination));
        accessxi.last_native_menu_name = menu_name;
        accessxi.last_native_menu_label = destination;
        accessxi.last_native_menu_selected = display_selected;
        accessxi.last_native_menu_tick = tick();
        accessxi.current_speech_key = ('mogdoor-window:%s:%s'):fmt(menu_name, destination);
        log_state(('state mogdoor window-title menu="%s" title="%s" ank=%d option=%d count=%d destination="%s"'):fmt(
            menu_name,
            accessxi.escape_probe_log_text(title or ''),
            ank_num,
            display_selected,
            display_count,
            accessxi.escape_probe_log_text(destination)));
        return speech;
    end

    local probe_key = ('0x%08X:0x%08X'):fmt(tonumber(entry) or 0, tonumber(child) or 0);
    if (probe_key ~= tostring(accessxi.last_mog_door_deep_key or '')) then
        accessxi.last_mog_door_deep_key = probe_key;
        log_line(('mogdoorprobe menu="%s" title="%s" destination="%s" ank=%d option=%d count=%d obj=0x%08X child=0x%08X entry=0x%08X entryDwords="%s" entryInline="%s" entryRuns="%s" entryPtrs="%s" childDwords="%s" childInline="%s" childRuns="%s" childPtrs="%s"'):fmt(
            menu_name,
            accessxi.escape_probe_log_text(title or ''),
            accessxi.escape_probe_log_text(destination),
            ank_num,
            display_selected,
            display_count,
            tonumber(obj) or 0,
            tonumber(child) or 0,
            tonumber(entry) or 0,
            accessxi.escape_probe_log_text(accessxi.format_probe_dwords(entry, 0, 64)),
            accessxi.escape_probe_log_text(accessxi.status_menu_probe_inline_strings(entry)),
            accessxi.escape_probe_log_text(accessxi.status_menu_probe_runs(entry, 0x260)),
            accessxi.escape_probe_log_text(accessxi.status_menu_probe_pointer_fields(entry)),
            accessxi.escape_probe_log_text(accessxi.format_probe_dwords(child, 0, 64)),
            accessxi.escape_probe_log_text(accessxi.status_menu_probe_inline_strings(child)),
            accessxi.escape_probe_log_text(accessxi.status_menu_probe_runs(child, 0x260)),
            accessxi.escape_probe_log_text(accessxi.status_menu_probe_pointer_fields(child))));
    end

    local suppressed_key = ('%s:%s:%d'):fmt(menu_name, destination, display_count);
    if (suppressed_key ~= tostring(accessxi.last_mog_door_suppressed_key or '')) then
        accessxi.last_mog_door_suppressed_key = suppressed_key;
        log_state(('state mogdoor suppressed menu="%s" title="%s" destination="%s" reason="native-label-missing"'):fmt(
            menu_name,
            accessxi.escape_probe_log_text(title or ''),
            accessxi.escape_probe_log_text(destination)));
    end
    return nil;
end

function accessxi.mog_roomlist_menu_speech(menu_name, title, obj, selected, count, page, raw, child, entry)
    local target = safe_call(function () return AshitaCore:GetMemoryManager():GetTarget(); end, nil);
    local ank_num = tonumber(target ~= nil and safe_call(function () return target:GetWindowAnkNum(); end, -1) or -1) or -1;
    local window_name = accessxi.survival_guide_text(target ~= nil and safe_call(function () return target:GetWindowName(); end, '') or '');
    if (window_name ~= '') then
        title = window_name;
    end
    if (tostring(title or '') == '') then
        title = 'Area';
    end

    local native_cursor = read_current_native_menu_index(0x4C);
    local display_selected = native_cursor;
    local display_count = tonumber(count) or 0;
    if (display_count <= 0 or display_count > 32) then
        display_count = math.max(
            tonumber(read_current_native_menu_index(0x24)) or 0,
            tonumber(read_current_native_menu_index(0x28)) or 0);
    end
    if (display_count <= 0 or display_count > 32) then
        display_count = 0;
    end
    if (display_selected < 1 or (display_count > 0 and display_selected > display_count)) then
        display_selected = tonumber(selected) or 0;
    end

    local key = ('%s:%d:%d:%08X:%08X:%08X:%s'):fmt(
        menu_name,
        tonumber(display_selected) or 0,
        tonumber(display_count) or 0,
        tonumber(obj) or 0,
        tonumber(child) or 0,
        tonumber(entry) or 0,
        tostring(title or ''));
    if (key ~= tostring(accessxi.last_mog_roomlist_key or '')) then
        accessxi.last_mog_roomlist_key = key;
        log_state(('state roomlist native menu="%s" title="%s" ank=%d option=%d count=%d selected=%d nativeCount=%d cursor4C=%d obj24=%d obj28=%d obj30=%d obj34=%d obj50=%d obj64=%d page=%d raw=0x%08X obj=0x%08X child=0x%08X entry=0x%08X'):fmt(
            menu_name,
            accessxi.escape_probe_log_text(title or ''),
            ank_num,
            tonumber(display_selected) or 0,
            tonumber(display_count) or 0,
            tonumber(selected) or 0,
            tonumber(count) or 0,
            native_cursor,
            read_current_native_menu_index(0x24),
            read_current_native_menu_index(0x28),
            read_current_native_menu_index(0x30),
            read_current_native_menu_index(0x34),
            read_current_native_menu_index(0x50),
            read_current_native_menu_index(0x64),
            tonumber(page) or 0,
            tonumber(raw) or 0,
            tonumber(obj) or 0,
            tonumber(child) or 0,
            tonumber(entry) or 0));
    end

    if (display_selected <= 0 or display_count <= 0) then
        return nil;
    end

    local label_ptr = accessxi.is_probe_pointer(entry) and (read_u32(entry + 0x44) or 0) or 0;
    local help_ptr = accessxi.is_probe_pointer(entry) and (read_u32(entry + 0x40) or 0) or 0;
    local direct_label = accessxi.plain_native_menu_label(read_probe_string(label_ptr, 160));
    local help_text = accessxi.plain_native_menu_help(read_probe_string(help_ptr, 220));
    if (direct_label ~= '') then
        accessxi.last_native_menu_name = menu_name;
        accessxi.last_native_menu_label = direct_label;
        accessxi.last_native_menu_selected = display_selected;
        accessxi.last_native_menu_tick = tick();
        accessxi.current_speech_key = ('roomlist-label:%d:%d:0x%08X:%s:%s'):fmt(
            display_selected,
            display_count,
            tonumber(label_ptr) or 0,
            direct_label,
            help_text);
        log_state(('state roomlist label menu="%s" title="%s" ank=%d option=%d count=%d entry=0x%08X labelPtr=0x%08X helpPtr=0x%08X label="%s" help="%s"'):fmt(
            menu_name,
            accessxi.escape_probe_log_text(title or ''),
            ank_num,
            display_selected,
            display_count,
            tonumber(entry) or 0,
            tonumber(label_ptr) or 0,
            tonumber(help_ptr) or 0,
            accessxi.escape_probe_log_text(direct_label),
            accessxi.escape_probe_log_text(help_text)));
        if (help_text ~= '') then
            return ('%s. %s %s'):fmt(title, accessxi.sentence_fragment(direct_label), accessxi.sentence_fragment(help_text));
        end
        return ('%s. %s'):fmt(title, accessxi.sentence_fragment(direct_label));
    end

    local list_label, list_mode = accessxi.native_query_label_for_selection(child, display_selected, display_count, 'plain');
    list_label = accessxi.plain_native_menu_label(list_label or '');
    if (list_label ~= '') then
        accessxi.last_native_menu_name = menu_name;
        accessxi.last_native_menu_label = list_label;
        accessxi.last_native_menu_selected = display_selected;
        accessxi.last_native_menu_tick = tick();
        accessxi.current_speech_key = ('roomlist-list:%d:%d:%s:%s'):fmt(
            display_selected,
            display_count,
            tostring(list_mode or ''),
            list_label);
        log_state(('state roomlist list-label menu="%s" title="%s" ank=%d option=%d count=%d nativeCount=%d mode="%s" label="%s"'):fmt(
            menu_name,
            accessxi.escape_probe_log_text(title or ''),
            ank_num,
            display_selected,
            display_count,
            tonumber(count) or 0,
            tostring(list_mode or ''),
            accessxi.escape_probe_log_text(list_label)));
        return ('%s. %s'):fmt(title, accessxi.sentence_fragment(list_label));
    end

    log_state(('state roomlist native-missing-label menu="%s" title="%s" ank=%d option=%d count=%d mode="%s" raw=0x%08X child=0x%08X entry=0x%08X'):fmt(
        menu_name,
        accessxi.escape_probe_log_text(title or ''),
        ank_num,
        display_selected,
        display_count,
        tostring(list_mode or ''),
        tonumber(raw) or 0,
        tonumber(child) or 0,
        tonumber(entry) or 0));
    return nil;
end

function accessxi.map_menu_entry_text(entry, selected)
    entry = tonumber(entry) or 0;
    selected = tonumber(selected) or 0;
    if (not accessxi.is_probe_pointer(entry)) then
        return '', 'none';
    end

    local rendered = '';
    if (accessxi.search_result_rendered_row_text ~= nil) then
        rendered = accessxi.plain_native_menu_label(accessxi.search_result_rendered_row_text(entry, selected));
        if (rendered ~= '') then
            return rendered, 'rendered-row';
        end
    end

    local label_ptr = read_u32(entry + 0x44) or 0;
    local help_ptr = read_u32(entry + 0x40) or 0;
    local label = accessxi.plain_native_menu_label(read_probe_string(label_ptr, 160));
    if (label ~= '') then
        return label, 'entry+44';
    end

    label = accessxi.plain_native_menu_label(read_probe_string(help_ptr, 220));
    if (label ~= '') then
        return label, 'entry+40';
    end

    return '', 'empty';
end

accessxi.map_menu_data = accessxi.load_menu_module_table('map', T{ main_rows = T{} });

function accessxi.map_menu_static_entry(selected)
    selected = tonumber(selected) or 0;
    local rows = accessxi.map_menu_data.main_rows or T{};

    if (selected < 1 or selected > rows:len()) then
        local target = safe_call(function () return AshitaCore:GetMemoryManager():GetTarget(); end, nil);
        local ank = target ~= nil and (tonumber(safe_call(function () return target:GetWindowAnkNum(); end, -1)) or -1) or -1;
        if (ank >= 0 and ank < rows:len()) then
            selected = ank + 1;
        end
    end

    return rows[selected];
end

function accessxi.map_current_zone_name()
    local zone = tonumber(accessxi.current_zone_id()) or 0;
    if (zone <= 0) then
        return '';
    end

    return accessxi.plain_native_menu_label(safe_call(function ()
        return AshitaCore:GetResourceManager():GetString('zones.names', zone);
    end, '') or '');
end

function accessxi.map_clean_native_label(text)
    text = accessxi.survival_guide_text(text or '');
    if (text == '') then
        return '';
    end

    text = text:gsub('%z.*$', ''):gsub('[%c]', ''):gsub('%s+', ' '):trim();
    text = text:gsub('^["\']+', ''):gsub('["\']+$', '');
    if (text == '' or #text > 80) then
        return '';
    end
    if (text:match('^[%p%s]+$') ~= nil) then
        return '';
    end
    if (text:find('menu    ', 1, true) ~= nil or text:find('anc     ', 1, true) ~= nil) then
        return '';
    end
    return text;
end

function accessxi.map_native_window_label()
    local target = safe_call(function () return AshitaCore:GetMemoryManager():GetTarget(); end, nil);
    if (target == nil) then
        return '';
    end

    local window_name = accessxi.map_clean_native_label(safe_call(function ()
        return target:GetWindowName();
    end, '') or '');
    if (window_name == '' or window_name:eq('Map', true) or window_name:eq('Markers', true)) then
        return '';
    end
    return window_name;
end

function accessxi.ffximain_rebased_va(static_va)
    static_va = tonumber(static_va) or 0;
    local base = get_ffximain_base();
    if (base == 0 or static_va < 0x10000000) then
        return 0;
    end
    return base + (static_va - 0x10000000);
end

function accessxi.ffximain_global_ptr(static_va)
    local addr = accessxi.ffximain_rebased_va(static_va);
    if (not accessxi.is_probe_pointer(addr)) then
        return 0;
    end

    local ptr = read_u32(addr) or 0;
    if (not accessxi.is_probe_pointer(ptr)) then
        return 0;
    end
    return ptr;
end

function accessxi.map_controller_ptr()
    return accessxi.ffximain_global_ptr(0x10630D68);
end

function accessxi.missions_menu_runtime_ptr(static_va)
    local addr = accessxi.ffximain_rebased_va(static_va);
    if (not accessxi.is_probe_pointer(addr)) then
        return 0, addr;
    end

    local ptr = read_u32(addr) or 0;
    if (not accessxi.is_probe_pointer(ptr)) then
        return 0, addr;
    end
    return ptr, addr;
end

function accessxi.missions_menu_runtime_vtable(ptr, count)
    ptr = tonumber(ptr) or 0;
    count = math.max(1, math.min(tonumber(count) or 12, 24));
    if (not accessxi.is_probe_pointer(ptr)) then
        return 0, '';
    end

    local vtbl = read_u32(ptr) or 0;
    if (not accessxi.is_probe_pointer(vtbl)) then
        return vtbl, '';
    end
    return vtbl, accessxi.format_probe_dwords(vtbl, 0, count);
end

function accessxi.log_missions_menu_runtime_category_table()
    if (accessxi.missions_menu_object_probe_table_logged == true) then
        return;
    end
    accessxi.missions_menu_object_probe_table_logged = true;

    local table_base = accessxi.ffximain_rebased_va(0x10634F70);
    if (not accessxi.is_probe_pointer(table_base)) then
        log_state(('state missions runtime-category-table base=0x%08X unreadable'):fmt(table_base));
        return;
    end

    local static_ids = T{ 0x49, 0x4A, 0x4B, 0x4C, 0x4D, 0x4E, 0x4F, 0x50, 0x54, 0x55, 0x56, 0x51, 0x52, 0x53, 0x00 };
    log_state(('state missions runtime-category-table base=0x%08X stride=0x94 count=15'):fmt(table_base));
    for index = 0, 14 do
        local entry = table_base + (index * 0x94);
        local static_id = tonumber(static_ids[index + 1]) or 0;
        log_state(('state missions runtime-category-entry index=%d staticId=0x%02X addr=0x%08X d000="%s" d040="%s" d080="%s" runs="%s" inline="%s" ptrs="%s"'):fmt(
            index,
            static_id,
            entry,
            accessxi.escape_probe_log_text(accessxi.format_probe_dwords(entry, 0x00, 16)),
            accessxi.escape_probe_log_text(accessxi.format_probe_dwords(entry, 0x40, 16)),
            accessxi.escape_probe_log_text(accessxi.format_probe_dwords(entry, 0x80, 5)),
            accessxi.escape_probe_log_text_wide(accessxi.status_menu_probe_runs(entry, 0x94)),
            accessxi.escape_probe_log_text_wide(accessxi.status_menu_probe_inline_strings(entry)),
            accessxi.escape_probe_log_text_wide(accessxi.status_menu_probe_pointer_fields(entry))));
    end
end

function accessxi.log_missions_menu_runtime_block_probe(sample, label, ptr)
    ptr = tonumber(ptr) or 0;
    label = tostring(label or '');
    if (not accessxi.is_probe_pointer(ptr)) then
        log_state(('state missions runtime-block sample=%d label="%s" ptr=0x%08X unreadable'):fmt(
            tonumber(sample) or 0,
            accessxi.escape_probe_log_text(label),
            ptr));
        return;
    end

    log_state(('state missions runtime-block sample=%d label="%s" ptr=0x%08X d000="%s" d040="%s" d080="%s" d0C0="%s" d100="%s" runs="%s" inline="%s" ptrs="%s"'):fmt(
        tonumber(sample) or 0,
        accessxi.escape_probe_log_text(label),
        ptr,
        accessxi.escape_probe_log_text(accessxi.format_probe_dwords(ptr, 0x00, 16)),
        accessxi.escape_probe_log_text(accessxi.format_probe_dwords(ptr, 0x40, 16)),
        accessxi.escape_probe_log_text(accessxi.format_probe_dwords(ptr, 0x80, 16)),
        accessxi.escape_probe_log_text(accessxi.format_probe_dwords(ptr, 0xC0, 16)),
        accessxi.escape_probe_log_text(accessxi.format_probe_dwords(ptr, 0x100, 16)),
        accessxi.escape_probe_log_text_wide(accessxi.status_menu_probe_runs(ptr, 0x180)),
        accessxi.escape_probe_log_text_wide(accessxi.status_menu_probe_inline_strings(ptr)),
        accessxi.escape_probe_log_text_wide(accessxi.status_menu_probe_pointer_fields(ptr))));

    local seen = {};
    local details = T{};
    for off = 0, 0x80, 4 do
        local child_ptr = read_u32(ptr + off) or 0;
        if (accessxi.is_probe_pointer(child_ptr) and seen[child_ptr] ~= true) then
            seen[child_ptr] = true;
            details:append(('+%03X=0x%08X d000="%s" runs="%s" inline="%s"'):fmt(
                off,
                child_ptr,
                accessxi.escape_probe_log_text(accessxi.format_probe_dwords(child_ptr, 0x00, 10)),
                accessxi.escape_probe_log_text_wide(accessxi.status_menu_probe_runs(child_ptr, 0x100)),
                accessxi.escape_probe_log_text_wide(accessxi.status_menu_probe_inline_strings(child_ptr))));
            if (details:len() >= 10) then
                break;
            end
        end
    end

    log_state(('state missions runtime-block-ptrs sample=%d label="%s" ptr=0x%08X details="%s"'):fmt(
        tonumber(sample) or 0,
        accessxi.escape_probe_log_text(label),
        ptr,
        accessxi.escape_probe_log_text_wide(details:concat(' | '))));
end

function accessxi.log_missions_menu_runtime_pair_probe(sample, ptr, selected, raw, context)
    ptr = tonumber(ptr) or 0;
    if (not accessxi.is_probe_pointer(ptr)) then
        return;
    end

    selected = tonumber(selected) or 0;
    raw = tonumber(raw) or 0;
    local raw_lo = bit.band(raw, 0xFFFF);
    local around_start = math.max(0, raw_lo - 4);
    local around_end = math.min(47, raw_lo + 8);
    local first = T{};
    local around = T{};

    local function pair_text(slot)
        local off = slot * 8;
        local id = read_i32(ptr + off);
        local flags = read_u32(ptr + off + 4);
        if (id == nil or flags == nil) then
            return ('%02d=?'):fmt(slot);
        end
        return ('%02d:%d,0x%08X'):fmt(slot, tonumber(id) or 0, tonumber(flags) or 0);
    end

    local function slot_fields(slot)
        local off = slot * 8;
        local id = read_i32(ptr + off);
        local flags = read_u32(ptr + off + 4);
        if (id == nil or flags == nil) then
            return ('s%02d_id=? s%02d_flags=? s%02d_lo=? s%02d_hi=?'):fmt(slot, slot, slot, slot);
        end

        flags = tonumber(flags) or 0;
        return ('s%02d_id=%d s%02d_flags=0x%08X s%02d_lo=0x%04X s%02d_hi=0x%04X'):fmt(
            slot,
            tonumber(id) or 0,
            slot,
            flags,
            slot,
            bit.band(flags, 0xFFFF),
            slot,
            bit.band(bit.rshift(flags, 16), 0xFFFF));
    end

    for slot = 0, 15 do
        first:append(pair_text(slot));
    end
    for slot = around_start, around_end do
        around:append(pair_text(slot));
    end

    log_state(('state missions runtime-pairs sample=%d context="%s" select=%d raw=0x%08X rawLo=%d ptr=0x%08X first="%s" around="%s"'):fmt(
        tonumber(sample) or 0,
        accessxi.escape_probe_log_text(tostring(context or '')),
        selected,
        raw,
        raw_lo,
        ptr,
        accessxi.escape_probe_log_text_wide(first:concat(' | ')),
        accessxi.escape_probe_log_text_wide(around:concat(' | '))));

    local head = T{};
    for slot = 0, 7 do
        head:append(slot_fields(slot));
    end
    log_state(('state missions runtime-slots-head sample=%d context="%s" select=%d rawLo=%d ptr=0x%08X %s'):fmt(
        tonumber(sample) or 0,
        accessxi.escape_probe_log_text(tostring(context or '')),
        selected,
        raw_lo,
        ptr,
        head:concat(' ')));

    local selected_slots = T{};
    local seen = {};
    local function add_slot(slot)
        slot = tonumber(slot) or 0;
        if (slot >= 0 and slot <= 47 and seen[slot] ~= true) then
            seen[slot] = true;
            selected_slots:append(slot_fields(slot));
        end
    end
    add_slot(raw_lo - 2);
    add_slot(raw_lo - 1);
    add_slot(raw_lo);
    add_slot(raw_lo + 1);
    add_slot(raw_lo + 2);
    add_slot(raw_lo + 3);
    add_slot(selected - 2);
    add_slot(selected - 1);
    add_slot(selected);
    add_slot(selected + 1);
    add_slot(selected + 2);
    log_state(('state missions runtime-slots-selected sample=%d context="%s" select=%d rawLo=%d ptr=0x%08X %s'):fmt(
        tonumber(sample) or 0,
        accessxi.escape_probe_log_text(tostring(context or '')),
        selected,
        raw_lo,
        ptr,
        selected_slots:concat(' ')));
end

function accessxi.log_missions_menu_runtime_object_probe(menu_name, title, obj, selected, count, page, raw, child, entry, context, context_source, context_row, native_row_label, native_row_mode)
    if (not tostring(menu_name or ''):eq('menu    miss00', true)) then
        return;
    end

    local now = tick();
    if ((tonumber(accessxi.missions_menu_object_probe_until) or 0) < now) then
        return;
    end
    if ((tonumber(accessxi.missions_menu_object_probe_count) or 0) >= (tonumber(accessxi.missions_menu_object_probe_limit) or 24)) then
        return;
    end

    selected = tonumber(selected) or 0;
    count = tonumber(count) or 0;
    page = tonumber(page) or 0;
    raw = tonumber(raw) or 0;
    obj = tonumber(obj) or 0;
    child = tonumber(child) or 0;
    entry = tonumber(entry) or 0;
    context = tostring(context or '');
    context_source = tostring(context_source or '');

    local mission_obj, mission_obj_global = accessxi.missions_menu_runtime_ptr(0x10635858);
    local missionm_obj, missionm_obj_global = accessxi.missions_menu_runtime_ptr(0x1063585C);
    local ffximain_base = get_ffximain_base();
    local target = safe_call(function () return AshitaCore:GetMemoryManager():GetTarget(); end, nil);
    local ank_num = target ~= nil and (tonumber(safe_call(function () return target:GetWindowAnkNum(); end, -1)) or -1) or -1;
    local sub = target ~= nil and (tonumber(safe_call(function () return target:GetWindowSub(); end, -1)) or -1) or -1;
    local child_category_index = accessxi.is_probe_pointer(child) and (read_u32(child + 0x6C) or 0) or 0;
    local row_label = context_row ~= nil and tostring(context_row.label or '') or '';
    local row_source = context_row ~= nil and tostring(context_row.source or '') or '';

    local key = ('%d:%d:%d:0x%08X:0x%08X:0x%08X:0x%08X:0x%08X:0x%08X:%s:%s:%s:%s:%s:%d:%d'):fmt(
        selected,
        count,
        page,
        raw,
        obj,
        child,
        entry,
        mission_obj,
        missionm_obj,
        context,
        context_source,
        row_label,
        tostring(native_row_label or ''),
        tostring(native_row_mode or ''),
        ank_num,
        sub);
    if (key == tostring(accessxi.last_missions_menu_object_probe_key or '')) then
        return;
    end
    accessxi.last_missions_menu_object_probe_key = key;
    accessxi.missions_menu_object_probe_count = (tonumber(accessxi.missions_menu_object_probe_count) or 0) + 1;

    local mission_vtbl, mission_vtbl_words = accessxi.missions_menu_runtime_vtable(mission_obj, 16);
    local missionm_vtbl, missionm_vtbl_words = accessxi.missions_menu_runtime_vtable(missionm_obj, 8);
    local sample = tonumber(accessxi.missions_menu_object_probe_count) or 0;

    log_state(('state missions runtime-object sample=%d menu="%s" title="%s" select=%d count=%d page=%d raw=0x%08X rawLo=%d context="%s" contextSource="%s" rowLabel="%s" rowSource="%s" nativeLabel="%s" nativeMode="%s" obj=0x%08X child=0x%08X entry=0x%08X childCategory=%d ank=%d sub=%d ffximain=0x%08X missGlobal=0x%08X missObj=0x%08X missionmGlobal=0x%08X missionmObj=0x%08X'):fmt(
        sample,
        tostring(menu_name or ''),
        accessxi.escape_probe_log_text(tostring(title or '')),
        selected,
        count,
        page,
        raw,
        bit.band(raw, 0xFFFF),
        accessxi.escape_probe_log_text(context),
        accessxi.escape_probe_log_text(context_source),
        accessxi.escape_probe_log_text(row_label),
        accessxi.escape_probe_log_text(row_source),
        accessxi.escape_probe_log_text(tostring(native_row_label or '')),
        accessxi.escape_probe_log_text(tostring(native_row_mode or '')),
        obj,
        child,
        entry,
        tonumber(child_category_index) or 0,
        ank_num,
        sub,
        ffximain_base,
        mission_obj_global,
        mission_obj,
        missionm_obj_global,
        missionm_obj));

    log_state(('state missions runtime-missobj ptr=0x%08X vtbl=0x%08X vtblWords="%s" d000="%s" d040="%s" d070="%s" runs="%s" inline="%s" ptrs="%s"'):fmt(
        mission_obj,
        mission_vtbl,
        accessxi.escape_probe_log_text(mission_vtbl_words),
        accessxi.escape_probe_log_text(accessxi.format_probe_dwords(mission_obj, 0x00, 16)),
        accessxi.escape_probe_log_text(accessxi.format_probe_dwords(mission_obj, 0x40, 12)),
        accessxi.escape_probe_log_text(accessxi.format_probe_dwords(mission_obj, 0x70, 8)),
        accessxi.escape_probe_log_text_wide(accessxi.status_menu_probe_runs(mission_obj, 0xA0)),
        accessxi.escape_probe_log_text_wide(accessxi.status_menu_probe_inline_strings(mission_obj)),
        accessxi.escape_probe_log_text_wide(accessxi.status_menu_probe_pointer_fields(mission_obj))));

    log_state(('state missions runtime-missionm ptr=0x%08X vtbl=0x%08X vtblWords="%s" d000="%s" runs="%s" inline="%s" ptrs="%s"'):fmt(
        missionm_obj,
        missionm_vtbl,
        accessxi.escape_probe_log_text(missionm_vtbl_words),
        accessxi.escape_probe_log_text(accessxi.format_probe_dwords(missionm_obj, 0x00, 8)),
        accessxi.escape_probe_log_text_wide(accessxi.status_menu_probe_runs(missionm_obj, 0x40)),
        accessxi.escape_probe_log_text_wide(accessxi.status_menu_probe_inline_strings(missionm_obj)),
        accessxi.escape_probe_log_text_wide(accessxi.status_menu_probe_pointer_fields(missionm_obj))));

    local category_block = accessxi.is_probe_pointer(mission_obj) and (read_u32(mission_obj + 0x20) or 0) or 0;
    accessxi.log_missions_menu_runtime_block_probe(sample, 'missObj+020', category_block);
    accessxi.log_missions_menu_runtime_pair_probe(sample, category_block, selected, raw, context);
    accessxi.log_missions_menu_runtime_category_table();
end

function accessxi.map_mode_label(mode)
    mode = tonumber(mode) or -1;
    if (mode == 0) then
        return 'Markers mode';
    elseif (mode == 1) then
        return 'Marker actions mode';
    elseif (mode == 2) then
        return 'Wide Scan mode';
    elseif (mode == 3) then
        return 'Scan mode';
    end
    return 'Markers mode';
end

function accessxi.map_selected_record_ptr(controller, selected, mode)
    controller = tonumber(controller) or 0;
    selected = tonumber(selected) or 0;
    mode = tonumber(mode) or 0;
    if (not accessxi.is_probe_pointer(controller) or selected < 1 or selected > 32) then
        return 0;
    end

    local index = selected - 1;
    local base = 0x6E8;
    if (mode == 1) then
        base = 0x7C4;
    elseif (mode == 2 or mode == 3) then
        index = index + (mode * 10);
    end
    return controller + base + (index * 0x16);
end

function accessxi.map_record_label_is_useful(label)
    label = accessxi.map_clean_native_label(label or '');
    if (label == '') then
        return false;
    end

    local lower = label:lower();
    if (#label < 3
        or lower == 'marker'
        or lower == 'markers'
        or lower == 'rker'
        or lower == 'ker'
        or lower == 'enu'
        or lower == 'men'
        or lower == 'menu'
        or lower:find('marker', 1, true) ~= nil
        or lower:find('menu', 1, true) ~= nil) then
        return false;
    end
    return true;
end

function accessxi.map_record_label(record)
    record = tonumber(record) or 0;
    if (not accessxi.is_probe_pointer(record)) then
        return '';
    end

    for _, off in ipairs(T{ 0x01, 0x02, 0x04, 0x06, 0x08 }) do
        local label = accessxi.map_clean_native_label(read_probe_string(record + off, 18));
        if (accessxi.map_record_label_is_useful(label)) then
            return label;
        end
    end
    return '';
end

function accessxi.map_marker_slot_label(selected, count, mode)
    selected = tonumber(selected) or 0;
    count = tonumber(count) or 0;
    mode = tonumber(mode) or 0;
    if (selected <= 0 or (mode ~= 0 and mode ~= 1)) then
        return '';
    end
    if (count > 0 and count <= 32) then
        return ('Marker %d of %d'):fmt(selected, count);
    end
    return ('Marker %d'):fmt(selected);
end

function accessxi.map_current_area_surface_label(selected, count)
    local parts = T{};
    local zone_name = accessxi.map_current_zone_name();
    local controller = accessxi.map_controller_ptr();
    local mode = accessxi.is_probe_pointer(controller) and (read_u16(controller + 0x106) or 0) or 0;
    local record = accessxi.map_selected_record_ptr(controller, selected, mode);
    local record_label = accessxi.map_record_label(record);
    local window_name = accessxi.map_native_window_label();
    local slot_label = accessxi.map_marker_slot_label(selected, count, mode);

    parts:append(accessxi.map_mode_label(mode));
    if (record_label ~= '') then
        parts:append(record_label);
    elseif (window_name ~= '') then
        parts:append(window_name);
    elseif (slot_label ~= '') then
        parts:append(slot_label);
    end
    if (zone_name ~= '') then
        parts:append(zone_name);
    end

    return accessxi.map_clean_native_label(parts:concat('. ')), mode;
end

function accessxi.log_map_menu_probe(menu_name, title, obj, selected, count, page, raw, child, entry, label, mode)
    local key = ('%s:%d:%d:%08X:%08X:%08X:%08X:%s:%s'):fmt(
        tostring(menu_name or ''),
        tonumber(selected) or 0,
        tonumber(count) or 0,
        tonumber(obj) or 0,
        tonumber(child) or 0,
        tonumber(entry) or 0,
        tonumber(raw) or 0,
        tostring(label or ''),
        tostring(mode or ''));
    if (key == tostring(accessxi.last_map_menu_probe_key or '')) then
        return;
    end
    accessxi.last_map_menu_probe_key = key;

    local target = safe_call(function () return AshitaCore:GetMemoryManager():GetTarget(); end, nil);
    local ank_num = target ~= nil and (tonumber(safe_call(function () return target:GetWindowAnkNum(); end, -1)) or -1) or -1;
    local ank_x = target ~= nil and (tonumber(safe_call(function () return target:GetWindowAnkX(); end, -1)) or -1) or -1;
    local ank_y = target ~= nil and (tonumber(safe_call(function () return target:GetWindowAnkY(); end, -1)) or -1) or -1;
    local win = target ~= nil and clean_probe_text(safe_call(function () return target:GetWindowName(); end, '')) or '';
    local controller = accessxi.map_controller_ptr();
    local map_mode = accessxi.is_probe_pointer(controller) and (read_u16(controller + 0x106) or 0) or -1;
    local map_kind = accessxi.is_probe_pointer(controller) and (read_u16(controller + 0x104) or 0) or -1;
    local map_zone = accessxi.is_probe_pointer(controller) and (read_u16(controller + 0x100) or 0) or -1;
    local record = accessxi.map_selected_record_ptr(controller, selected, map_mode);

    log_state(('state map-menu menu="%s" title="%s" select=%d count=%d page=%d raw=0x%08X obj=0x%08X child=0x%08X entry=0x%08X mode="%s" label="%s" win="%s" ankNum=%d ank=(%d,%d) ctrl=0x%08X mapMode=%d mapKind=%d mapZone=%d rec=0x%08X recBytes="%s" recRuns="%s" objDwords="%s" childDwords="%s" entryDwords="%s" entryRuns="%s" entryPtrs="%s"'):fmt(
        tostring(menu_name or ''),
        accessxi.escape_probe_log_text(title or ''),
        tonumber(selected) or 0,
        tonumber(count) or 0,
        tonumber(page) or 0,
        tonumber(raw) or 0,
        tonumber(obj) or 0,
        tonumber(child) or 0,
        tonumber(entry) or 0,
        accessxi.escape_probe_log_text(mode or ''),
        accessxi.escape_probe_log_text(label or ''),
        accessxi.escape_probe_log_text(win),
        ank_num,
        ank_x,
        ank_y,
        tonumber(controller) or 0,
        tonumber(map_mode) or -1,
        tonumber(map_kind) or -1,
        tonumber(map_zone) or -1,
        tonumber(record) or 0,
        accessxi.escape_probe_log_text_wide(accessxi.format_probe_bytes(record, 0, 0x16)),
        accessxi.escape_probe_log_text_wide(accessxi.status_menu_probe_runs(record, 0x40)),
        accessxi.escape_probe_log_text(accessxi.format_probe_dwords(obj, 0, 40)),
        accessxi.escape_probe_log_text(accessxi.format_probe_dwords(child, 0, 40)),
        accessxi.escape_probe_log_text(accessxi.format_probe_dwords(entry, 0, 48)),
        accessxi.escape_probe_log_text_wide(accessxi.status_menu_probe_runs(entry, 0x220)),
        accessxi.escape_probe_log_text_wide(accessxi.status_menu_probe_pointer_fields(entry))));
end

function accessxi.map_menu_speech(menu_name, title, obj, selected, count, page, raw, child, entry)
    menu_name = tostring(menu_name or '');
    title = tostring(title or 'Map');
    selected = tonumber(selected) or 0;
    count = tonumber(count) or 0;

    local label = '';
    local mode = '';
    local help = '';

    if (menu_name:eq('menu    map0', true)) then
        local row = accessxi.map_menu_static_entry(selected);
        if (row ~= nil) then
            label = tostring(row.label or '');
            help = tostring(row.help or '');
            mode = 'dat-map0';
        end
    else
        label, mode = accessxi.map_menu_entry_text(entry, selected);
        if (label == '' and accessxi.is_probe_pointer(child) and selected > 0 and count > 0 and count <= 64) then
            local query_label, query_mode = accessxi.native_query_label_for_selection(child, selected, count, 'plain');
            query_label = accessxi.plain_native_menu_label(query_label or '');
            if (query_label ~= '') then
                label = query_label;
                mode = 'native-query:' .. tostring(query_mode or '');
            end
        end
        if (label == ''
            and (menu_name:eq('menu    mapv3', true) or menu_name:eq('menu    mapframe', true))) then
            local native_map_mode = 0;
            label, native_map_mode = accessxi.map_current_area_surface_label(selected, count);
            if (label ~= '') then
                mode = ('native-window:%d'):fmt(tonumber(native_map_mode) or 0);
            end
        end
    end

    accessxi.log_map_menu_probe(menu_name, title, obj, selected, count, page, raw, child, entry, label, mode);
    if (label == '') then
        return nil;
    end

    accessxi.last_native_menu_name = menu_name;
    accessxi.last_native_menu_label = label;
    accessxi.last_native_menu_selected = selected;
    accessxi.last_native_menu_tick = tick();
    accessxi.current_speech_key = ('map-menu:%s:%d:%d:%d:%s:%s'):fmt(
        menu_name,
        selected,
        tonumber(page) or 0,
        count,
        tostring(mode or ''),
        label);

    if (help ~= '') then
        return ('%s. %s %s'):fmt(title, accessxi.sentence_fragment(label), accessxi.sentence_fragment(help));
    end
    return ('%s. %s'):fmt(title, accessxi.sentence_fragment(label));
end

function accessxi.home_point_query_menu_speech(menu_name, title, obj)
    menu_name = tostring(menu_name or '');
    title = tostring(title or '');
    obj = tonumber(obj) or 0;
    if (title == '') then
        local target = safe_call(function () return AshitaCore:GetMemoryManager():GetTarget(); end, nil);
        title = accessxi.survival_guide_text(target ~= nil and safe_call(function () return target:GetWindowName(); end, '') or '');
    end
    if (not menu_name:eq('menu    query', true) or obj == 0 or not title:contains('Home Point', true)) then
        return nil;
    end

    local selected, page, raw, child, count = accessxi.survival_guide_query_child_state_for_obj(obj);
    selected = tonumber(selected) or 0;
    count = tonumber(count) or 0;
    if (selected <= 0) then
        selected = read_current_native_menu_index(0x4C);
    end
    if (count <= 0 or count > 64) then
        count = math.max(accessxi.native_menu_index(0x24), accessxi.native_menu_index(0x28));
    end

    local label, mode = accessxi.native_query_label_for_selection(child, selected, count, 'plain');
    label = accessxi.home_point_query_normalize_phrase(label or '');
    if (selected >= 2 and accessxi.home_point_label_is_destination_row(label)) then
        label = accessxi.home_point_destination_row_label(selected);
    elseif (label ~= '') then
        accessxi.home_point_remember_area_label(label);
    end
    local key = ('%s:%d:%d:%d:%08X:%s:%s'):fmt(
        menu_name,
        selected,
        count,
        tonumber(page) or 0,
        tonumber(child) or 0,
        tostring(mode or ''),
        label);
    if (key ~= tostring(accessxi.last_home_point_query_log_key or '')) then
        accessxi.last_home_point_query_log_key = key;
        log_state(('state homepoint query menu="%s" title="%s" select=%d count=%d page=%d raw=0x%08X child=0x%08X mode="%s" label="%s"'):fmt(
            menu_name,
            accessxi.escape_probe_log_text(title),
            selected,
            count,
            tonumber(page) or 0,
            tonumber(raw) or 0,
            tonumber(child) or 0,
            tostring(mode or ''),
            accessxi.escape_probe_log_text(label)));
    end
    if (label == '') then
        return nil;
    end

    accessxi.last_native_menu_name = menu_name;
    accessxi.last_native_menu_label = label;
    accessxi.last_native_menu_selected = selected;
    accessxi.last_native_menu_tick = tick();
    accessxi.current_speech_key = ('homepoint-query:%s:%d:%d:%d:%s'):fmt(
        menu_name,
        selected,
        tonumber(page) or 0,
        count,
        label);
    return ('%s. %s'):fmt(title, accessxi.sentence_fragment(label));
end

accessxi.festive_moogle_menu_data = accessxi.load_menu_module_table('festive_moogle', T{
    query_label_tail_patterns = T{},
    query_contains_labels = T{},
    query_exact_labels = T{},
});

function accessxi.festive_moogle_clean_query_label(label)
    label = accessxi.plain_native_menu_label(label or '');
    if (label == '') then
        return '';
    end

    for _, pattern in ipairs(accessxi.festive_moogle_menu_data.query_label_tail_patterns or T{}) do
        label = label:gsub(pattern, '');
    end
    label = label:gsub('%s+', ' '):trim();

    for _, row in ipairs(accessxi.festive_moogle_menu_data.query_contains_labels or T{}) do
        local contains = tostring(row ~= nil and row.contains or '');
        local clean = tostring(row ~= nil and row.label or '');
        if (contains ~= '' and clean ~= '' and label:contains(contains, true)) then
            return clean;
        end
    end

    for raw, clean in pairs(accessxi.festive_moogle_menu_data.query_exact_labels or {}) do
        if (label:eq(tostring(raw or ''), true)) then
            return tostring(clean or label);
        end
    end

    for _, row in ipairs(accessxi.festive_moogle_menu_data.query_dynamic_labels or T{}) do
        local pattern = tostring(row ~= nil and row.pattern or '');
        local kind = tostring(row ~= nil and row.kind or ''):lower();
        local capture = nil;
        if (pattern ~= '') then
            capture = label:match(pattern);
        end
        if (capture ~= nil) then
            capture = accessxi.survival_guide_text(capture);
            if (kind == 'cipher-alter-ego' and capture ~= '') then
                return ("Cipher of %s's alter ego"):fmt(capture);
            elseif (kind == 'none') then
                return 'None';
            end
        end
    end

    return label;
end

function accessxi.festive_moogle_query_menu_speech(menu_name, title, obj)
    menu_name = tostring(menu_name or '');
    title = tostring(title or '');
    obj = tonumber(obj) or 0;
    if (title == '') then
        local target = safe_call(function () return AshitaCore:GetMemoryManager():GetTarget(); end, nil);
        title = accessxi.survival_guide_text(target ~= nil and safe_call(function () return target:GetWindowName(); end, '') or '');
    end
    if (not menu_name:eq('menu    query', true) or obj == 0 or not title:contains('Festive Moogle', true)) then
        return nil;
    end

    local selected, page, raw, child, count = accessxi.survival_guide_query_child_state_for_obj(obj);
    selected = tonumber(selected) or 0;
    count = tonumber(count) or 0;
    if (selected <= 0) then
        selected = read_current_native_menu_index(0x4C);
    end
    if (count <= 0 or count > 64) then
        count = math.max(accessxi.native_menu_index(0x24), accessxi.native_menu_index(0x28));
    end

    local label, mode = accessxi.native_query_label_for_selection(child, selected, count, 'plain');
    label = accessxi.festive_moogle_clean_query_label(label or '');
    local key = ('%s:%s:%d:%d:%d:%08X:%s:%s'):fmt(
        menu_name,
        title,
        selected,
        count,
        tonumber(page) or 0,
        tonumber(child) or 0,
        tostring(mode or ''),
        label);
    if (key ~= tostring(accessxi.last_festive_moogle_query_log_key or '')) then
        accessxi.last_festive_moogle_query_log_key = key;
        log_state(('state festive-moogle query menu="%s" title="%s" select=%d count=%d page=%d raw=0x%08X child=0x%08X mode="%s" label="%s"'):fmt(
            menu_name,
            accessxi.escape_probe_log_text(title),
            selected,
            count,
            tonumber(page) or 0,
            tonumber(raw) or 0,
            tonumber(child) or 0,
            tostring(mode or ''),
            accessxi.escape_probe_log_text(label)));
    end
    if (label == '') then
        return nil;
    end

    accessxi.last_native_menu_name = menu_name;
    accessxi.last_native_menu_label = label;
    accessxi.last_native_menu_selected = selected;
    accessxi.last_native_menu_tick = tick();
    accessxi.current_speech_key = ('festive-moogle-query:%s:%d:%d:%d:%s'):fmt(
        menu_name,
        selected,
        tonumber(page) or 0,
        count,
        label);
    return ('%s. %s'):fmt(title, accessxi.sentence_fragment(label));
end

function accessxi.generic_query_module_context()
    return T{
        generic_query_context = T{
            safe_call = safe_call,
            read_u8 = read_u8,
            read_u32 = read_u32,
            read_probe_string = read_probe_string,
            read_current_native_menu_index = read_current_native_menu_index,
            log_line = log_line,
            log_state = log_state,
            tick = tick,
        },
    };
end
accessxi.load_menu_code_module('generic_query', accessxi.generic_query_module_context());
function accessxi.log_help_desk_menu_probe(menu_name, title, obj, selected, count, page, raw, child, entry, reason)
    menu_name = tostring(menu_name or '');
    if (not accessxi.is_help_desk_menu_name(menu_name)) then
        return;
    end

    obj = tonumber(obj) or 0;
    child = tonumber(child) or 0;
    entry = tonumber(entry) or 0;
    selected = tonumber(selected) or 0;
    count = tonumber(count) or 0;
    local target = safe_call(function () return AshitaCore:GetMemoryManager():GetTarget(); end, nil);
    local window_name = accessxi.plain_native_menu_label(target ~= nil and safe_call(function () return target:GetWindowName(); end, '') or '');
    local ank_num = target ~= nil and (tonumber(safe_call(function () return target:GetWindowAnkNum(); end, -1)) or -1) or -1;
    local sub = target ~= nil and (tonumber(safe_call(function () return target:GetWindowSub(); end, -1)) or -1) or -1;
    local sub_x = target ~= nil and (tonumber(safe_call(function () return target:GetWindowSubAnkX(); end, -1)) or -1) or -1;
    local sub_y = target ~= nil and (tonumber(safe_call(function () return target:GetWindowSubAnkY(); end, -1)) or -1) or -1;
    local key = ('%s:%08X:%08X:%08X:%d:%d:%d:%08X:%d:%d:%d:%d:%s'):fmt(
        menu_name,
        obj,
        child,
        entry,
        selected,
        count,
        tonumber(page) or 0,
        tonumber(raw) or 0,
        ank_num,
        sub,
        sub_x,
        sub_y,
        tostring(reason or ''));
    if (key == tostring(accessxi.last_help_desk_menu_probe_key or '')) then
        return;
    end
    accessxi.last_help_desk_menu_probe_key = key;

    accessxi.menu_dump_sequence = (tonumber(accessxi.menu_dump_sequence) or 0) + 1;
    local seq = accessxi.menu_dump_sequence;
    log_line(('menudump begin seq=%d reason=help-desk-%s menu="%s" title="%s" window="%s" selected=%d count=%d page=%d raw=0x%08X obj=0x%08X child=0x%08X entry=0x%08X ank=%d sub=%d subXY=(%d,%d) objIdx="%s" childIdx="%s" objD00=%s childD00=%s entryD00=%s'):fmt(
        seq,
        tostring(reason or ''),
        menu_name,
        accessxi.escape_probe_log_text(title or ''),
        accessxi.escape_probe_log_text(window_name),
        selected,
        count,
        tonumber(page) or 0,
        tonumber(raw) or 0,
        obj,
        child,
        entry,
        ank_num,
        sub,
        sub_x,
        sub_y,
        accessxi.format_probe_index_fields(obj, 0x00, 0x80),
        accessxi.format_probe_index_fields(child, 0x00, 0x80),
        accessxi.format_probe_dwords(obj, 0x00, 16),
        accessxi.format_probe_dwords(child, 0x00, 16),
        accessxi.format_probe_dwords(entry, 0x00, 16)));

    accessxi.log_probe_short_text_runs(seq, 'helpdesk.obj', obj, 0x300, 2, 18);
    accessxi.log_probe_pointer_text_targets(seq, 'helpdesk.obj', obj, 0x00, 0x17C, 18);
    accessxi.log_probe_short_text_runs(seq, 'helpdesk.child', child, 0x300, 2, 18);
    accessxi.log_probe_pointer_text_targets(seq, 'helpdesk.child', child, 0x00, 0x17C, 18);
    accessxi.log_probe_short_text_runs(seq, 'helpdesk.entry', entry, 0x180, 2, 12);
    accessxi.log_probe_pointer_text_targets(seq, 'helpdesk.entry', entry, 0x00, 0xFC, 12);

    if (target ~= nil and ank_num > 0) then
        for i = 0, math.min(ank_num - 1, 5) do
            local shape = tonumber(safe_call(function () return target:GetWindowAnkShape(i); end, 0)) or 0;
            if (accessxi.is_probe_pointer(shape)) then
                log_line(('menudump seq=%d helpdesk.shape%d ptr=0x%08X dwords=%s'):fmt(
                    seq,
                    i,
                    shape,
                    accessxi.format_probe_dwords(shape, 0x00, 12)));
                accessxi.log_probe_short_text_runs(seq, ('helpdesk.shape%d'):fmt(i), shape, 0x220, 2, 10);
                accessxi.log_probe_pointer_text_targets(seq, ('helpdesk.shape%d'):fmt(i), shape, 0x00, 0xFC, 10);
            end
        end
    end

    log_line(('menudump end seq=%d'):fmt(seq));
end

function accessxi.log_help_desk_shape_trace(menu_name, title, selected, count, page, raw, child, entry, ank_num, target)
    menu_name = tostring(menu_name or '');
    if (not accessxi.is_help_desk_menu_name(menu_name)) then
        return 0;
    end

    target = target or safe_call(function () return AshitaCore:GetMemoryManager():GetTarget(); end, nil);
    ank_num = tonumber(ank_num) or -1;
    if (target == nil or ank_num < 0 or ank_num > 16) then
        return 0;
    end

    local shape = tonumber(safe_call(function () return target:GetWindowAnkShape(ank_num); end, 0)) or 0;
    if (shape == 0) then
        return 0;
    end

    local ptr_parts = T{};
    for _, off in ipairs(T{ 0x04, 0x08, 0x0C, 0x10, 0x14, 0x18, 0x1C, 0x20, 0x24, 0x28, 0x2C, 0x30, 0x34, 0x38, 0x3C, 0x40 }) do
        local ptr = read_u32(shape + off) or 0;
        if (accessxi.is_probe_pointer(ptr)) then
            ptr_parts:append(('+%02X=0x%08X:%s'):fmt(off, ptr, accessxi.format_probe_dwords(ptr, 0x00, 6)));
        end
    end

    local d00 = accessxi.format_probe_dwords(shape, 0x00, 16);
    local d40 = accessxi.format_probe_dwords(shape, 0x40, 12);
    local key = ('%s:%d:%d:%d:0x%08X:0x%08X:0x%08X:%d:0x%08X:%s:%s:%s'):fmt(
        menu_name,
        tonumber(selected) or 0,
        tonumber(count) or 0,
        tonumber(page) or 0,
        tonumber(raw) or 0,
        tonumber(child) or 0,
        tonumber(entry) or 0,
        ank_num,
        shape,
        d00,
        d40,
        ptr_parts:concat(' | '));
    if (key == tostring(accessxi.last_help_desk_shape_trace_key or '')) then
        return shape;
    end
    accessxi.last_help_desk_shape_trace_key = key;

    log_state(('state helpdesk shape menu="%s" title="%s" selected=%d count=%d page=%d raw=0x%08X child=0x%08X entry=0x%08X ank=%d shape=0x%08X d00="%s" d40="%s" ptrs="%s"'):fmt(
        menu_name,
        accessxi.escape_probe_log_text(title or ''),
        tonumber(selected) or 0,
        tonumber(count) or 0,
        tonumber(page) or 0,
        tonumber(raw) or 0,
        tonumber(child) or 0,
        tonumber(entry) or 0,
        ank_num,
        shape,
        accessxi.escape_probe_log_text(d00),
        accessxi.escape_probe_log_text(d40),
        accessxi.escape_probe_log_text_wide(ptr_parts:concat(' | '))));
    return shape;
end

function accessxi.log_help_desk_shape_grid_trace(menu_name, selected, count, raw, child, entry, ank_num, target)
    menu_name = tostring(menu_name or '');
    if (not accessxi.is_help_desk_menu_name(menu_name)) then
        return;
    end

    target = target or safe_call(function () return AshitaCore:GetMemoryManager():GetTarget(); end, nil);
    if (target == nil) then
        return;
    end

    local now = tick();
    local session_key = ('%s:0x%08X:0x%08X:0x%08X'):fmt(
        menu_name,
        tonumber(raw) or 0,
        tonumber(child) or 0,
        tonumber(entry) or 0);
    if (session_key ~= tostring(accessxi.help_desk_shape_grid_session_key or '')) then
        accessxi.help_desk_shape_grid_session_key = session_key;
        accessxi.help_desk_shape_grid_until = now + 30000;
        accessxi.help_desk_shape_grid_next = 0;
        accessxi.help_desk_shape_grid_count = 0;
        accessxi.help_desk_shape_grid_last_line = '';
    end

    if (now > (tonumber(accessxi.help_desk_shape_grid_until) or 0)
        or now < (tonumber(accessxi.help_desk_shape_grid_next) or 0)) then
        return;
    end

    accessxi.help_desk_shape_grid_next = now + 150;

    local shape_parts = T{};
    for i = 0, 8 do
        local shape = tonumber(safe_call(function () return target:GetWindowAnkShape(i); end, 0)) or 0;
        if (shape ~= 0) then
            shape_parts:append(('%d=0x%08X d00=%s d40=%s'):fmt(
                i,
                shape,
                accessxi.format_probe_dwords(shape, 0x00, 8),
                accessxi.format_probe_dwords(shape, 0x40, 6)));
        else
            shape_parts:append(('%d=0x00000000'):fmt(i));
        end
    end

    local shape_line = shape_parts:concat(' | ');
    if (shape_line == tostring(accessxi.help_desk_shape_grid_last_line or '')) then
        return;
    end
    accessxi.help_desk_shape_grid_last_line = shape_line;
    accessxi.help_desk_shape_grid_count = (tonumber(accessxi.help_desk_shape_grid_count) or 0) + 1;

    log_state(('state helpdesk shape-grid n=%d menu="%s" selected=%d count=%d raw=0x%08X child=0x%08X entry=0x%08X ank=%d shapes="%s"'):fmt(
        tonumber(accessxi.help_desk_shape_grid_count) or 0,
        menu_name,
        tonumber(selected) or 0,
        tonumber(count) or 0,
        tonumber(raw) or 0,
        tonumber(child) or 0,
        tonumber(entry) or 0,
        tonumber(ank_num) or -1,
        accessxi.escape_probe_log_text_wide(shape_line)));
end

function accessxi.log_help_desk_shape_probe(reason, key)
    local now = tick();
    if (now > (tonumber(accessxi.help_desk_shape_probe_until) or 0)) then
        return;
    end
    key = tonumber(key) or 0;
    if (tostring(reason or ''):eq('speech', true) and key <= 0) then
        return;
    end
    if ((tonumber(accessxi.help_desk_shape_probe_count) or 0) >= (tonumber(accessxi.help_desk_shape_probe_limit) or 0)) then
        return;
    end
    if (now < (tonumber(accessxi.help_desk_shape_probe_next) or 0)) then
        return;
    end

    local menu_name = tostring(get_menu_name() or '');
    if (not accessxi.is_help_desk_menu_name(menu_name)) then
        return;
    end

    local obj = get_current_menu_object_ptr();
    if (obj == 0) then
        return;
    end

    local selected, page, raw, child, count = accessxi.survival_guide_query_child_state_for_obj(obj);
    local entry = accessxi.is_probe_pointer(obj) and (read_u32(obj + 0x08) or 0) or 0;
    local target = safe_call(function () return AshitaCore:GetMemoryManager():GetTarget(); end, nil);
    local ank_num = target ~= nil and (tonumber(safe_call(function () return target:GetWindowAnkNum(); end, -1)) or -1) or -1;
    local sub = target ~= nil and (tonumber(safe_call(function () return target:GetWindowSub(); end, -1)) or -1) or -1;
    local sub_x = target ~= nil and (tonumber(safe_call(function () return target:GetWindowSubAnkX(); end, -1)) or -1) or -1;
    local sub_y = target ~= nil and (tonumber(safe_call(function () return target:GetWindowSubAnkY(); end, -1)) or -1) or -1;
    local focus_index = target ~= nil and (tonumber(safe_call(function () return target:GetFocusTargetIndex(); end, -1)) or -1) or -1;
    local focus_server = target ~= nil and (tonumber(safe_call(function () return target:GetFocusTargetServerId(); end, -1)) or -1) or -1;
    local help_title_ptr = target ~= nil and (tonumber(safe_call(function () return target:GetWindowHelpTitle(); end, 0)) or 0) or 0;
    local help_ptr = target ~= nil and (tonumber(safe_call(function () return target:GetWindowHelpString(); end, 0)) or 0) or 0;
    local shape = 0;
    if (target ~= nil and ank_num >= 0 and ank_num <= 16) then
        shape = tonumber(safe_call(function () return target:GetWindowAnkShape(ank_num); end, 0)) or 0;
    end

    accessxi.help_desk_shape_probe_next = now + 120;
    accessxi.help_desk_shape_probe_count = (tonumber(accessxi.help_desk_shape_probe_count) or 0) + 1;
    accessxi.menu_dump_sequence = (accessxi.menu_dump_sequence or 0) + 1;
    local seq = accessxi.menu_dump_sequence;

    local idx_parts = T{};
    for _, off in ipairs(T{ 0x24, 0x28, 0x2C, 0x30, 0x34, 0x38, 0x3C, 0x40, 0x44, 0x48, 0x4C, 0x50, 0x54, 0x58, 0x5C, 0x60, 0x64, 0x68, 0x6C, 0x70, 0x74, 0x78, 0x7C, 0x80, 0x84, 0x88, 0x8C, 0x90 }) do
        idx_parts:append(('%02X=%d'):fmt(off, tonumber(read_current_native_menu_index(off)) or 0));
    end

    log_state(('state helpdesk shape-probe seq=%d n=%d reason="%s" key=%d menu="%s" selected=%d count=%d page=%d raw=0x%08X obj=0x%08X child=0x%08X entry=0x%08X ank=%d shape=0x%08X sub=%d subXY=(%d,%d) focus=%d server=%d helpTitlePtr=0x%08X helpPtr=0x%08X helpTitle="%s" help="%s" idx="%s"'):fmt(
        seq,
        tonumber(accessxi.help_desk_shape_probe_count) or 0,
        accessxi.escape_probe_log_text(reason or ''),
        key,
        menu_name,
        tonumber(selected) or 0,
        tonumber(count) or 0,
        tonumber(page) or 0,
        tonumber(raw) or 0,
        tonumber(obj) or 0,
        tonumber(child) or 0,
        tonumber(entry) or 0,
        ank_num,
        shape,
        sub,
        sub_x,
        sub_y,
        focus_index,
        focus_server,
        help_title_ptr,
        help_ptr,
        accessxi.escape_probe_log_text(read_probe_string(help_title_ptr)),
        accessxi.escape_probe_log_text(read_probe_string(help_ptr)),
        idx_parts:concat(' ')));

    accessxi.menu_dump_textptr_budget = 80;
    accessxi.log_probe_short_text_runs(seq, 'helpdesk.probe.obj', obj, 0x240, 2, 12);
    accessxi.log_probe_pointer_text_targets(seq, 'helpdesk.probe.obj', obj, 0x00, 0x120, 14);
    accessxi.log_probe_short_text_runs(seq, 'helpdesk.probe.child', child, 0x240, 2, 12);
    accessxi.log_probe_pointer_text_targets(seq, 'helpdesk.probe.child', child, 0x00, 0x120, 14);
    accessxi.log_probe_short_text_runs(seq, 'helpdesk.probe.entry', entry, 0x180, 2, 8);
    accessxi.log_probe_pointer_text_targets(seq, 'helpdesk.probe.entry', entry, 0x00, 0xC0, 10);

    if (accessxi.is_probe_pointer(shape)) then
        log_line(('menudump seq=%d helpdesk.probe.shape ptr=0x%08X d00=%s d40=%s d80=%s'):fmt(
            seq,
            shape,
            accessxi.format_probe_dwords(shape, 0x00, 16),
            accessxi.format_probe_dwords(shape, 0x40, 16),
            accessxi.format_probe_dwords(shape, 0x80, 12)));
        accessxi.log_probe_short_text_runs(seq, 'helpdesk.probe.shape', shape, 0x260, 2, 12);
        accessxi.log_probe_pointer_text_targets(seq, 'helpdesk.probe.shape', shape, 0x00, 0x100, 18);

        for _, off in ipairs(T{ 0x04, 0x08, 0x0C, 0x10, 0x14, 0x18, 0x1C, 0x20, 0x24, 0x28, 0x2C, 0x30, 0x34, 0x38, 0x3C, 0x40, 0x44, 0x48, 0x4C, 0x50, 0x54, 0x58, 0x5C, 0x60 }) do
            local ptr = read_u32(shape + off) or 0;
            if (accessxi.is_probe_pointer(ptr)) then
                log_line(('menudump seq=%d helpdesk.probe.shapeptr +%02X=0x%08X d00=%s d40=%s'):fmt(
                    seq,
                    off,
                    ptr,
                    accessxi.format_probe_dwords(ptr, 0x00, 12),
                    accessxi.format_probe_dwords(ptr, 0x40, 8)));
                accessxi.log_probe_short_text_runs(seq, ('helpdesk.probe.shapeptr+%02X'):fmt(off), ptr, 0x200, 2, 8);
                accessxi.log_probe_pointer_text_targets(seq, ('helpdesk.probe.shapeptr+%02X'):fmt(off), ptr, 0x00, 0xC0, 8);
            end
        end
    end
    if (tostring(reason or ''):eq('speech', true)) then
        accessxi.help_desk_shape_probe_last_key = 0;
    end
end

function accessxi.log_help_desk_any_menu_probe(reason, key)
    local now = tick();
    if (now > (tonumber(accessxi.help_desk_shape_probe_until) or 0)) then
        return;
    end
    if ((tonumber(accessxi.help_desk_any_probe_count) or 0) >= (tonumber(accessxi.help_desk_shape_probe_limit) or 0)) then
        return;
    end

    local menu_name = tostring(get_menu_name() or '');
    local obj = get_current_menu_object_ptr();
    local selected, page, raw, child, count = accessxi.survival_guide_query_child_state_for_obj(obj);
    local entry = accessxi.is_probe_pointer(obj) and (read_u32(obj + 0x08) or 0) or 0;
    local target = safe_call(function () return AshitaCore:GetMemoryManager():GetTarget(); end, nil);
    local ank_num = target ~= nil and (tonumber(safe_call(function () return target:GetWindowAnkNum(); end, -1)) or -1) or -1;
    local sub = target ~= nil and (tonumber(safe_call(function () return target:GetWindowSub(); end, -1)) or -1) or -1;
    local sub_x = target ~= nil and (tonumber(safe_call(function () return target:GetWindowSubAnkX(); end, -1)) or -1) or -1;
    local sub_y = target ~= nil and (tonumber(safe_call(function () return target:GetWindowSubAnkY(); end, -1)) or -1) or -1;
    local help_title_ptr = target ~= nil and (tonumber(safe_call(function () return target:GetWindowHelpTitle(); end, 0)) or 0) or 0;
    local help_ptr = target ~= nil and (tonumber(safe_call(function () return target:GetWindowHelpString(); end, 0)) or 0) or 0;

    local idx_parts = T{};
    for _, off in ipairs(T{ 0x24, 0x28, 0x2C, 0x30, 0x34, 0x38, 0x3C, 0x40, 0x44, 0x48, 0x4C, 0x50, 0x54, 0x58, 0x5C, 0x60 }) do
        idx_parts:append(('%02X=%d'):fmt(off, tonumber(read_current_native_menu_index(off)) or 0));
    end
    local idx_line = idx_parts:concat(' ');
    local sig = ('%s|%08X|%08X|%08X|%d|%d|%d|%08X|%d|%s'):fmt(
        menu_name,
        tonumber(obj) or 0,
        tonumber(child) or 0,
        tonumber(entry) or 0,
        tonumber(selected) or 0,
        tonumber(count) or 0,
        tonumber(page) or 0,
        tonumber(raw) or 0,
        ank_num,
        idx_line);
    if (sig == tostring(accessxi.help_desk_any_probe_last_sig or '')) then
        return;
    end
    accessxi.help_desk_any_probe_last_sig = sig;
    accessxi.help_desk_any_probe_count = (tonumber(accessxi.help_desk_any_probe_count) or 0) + 1;
    log_state(('state helpdesk any-probe n=%d reason="%s" key=%d menu="%s" known=%d selected=%d count=%d page=%d raw=0x%08X obj=0x%08X child=0x%08X entry=0x%08X ank=%d sub=%d subXY=(%d,%d) helpTitlePtr=0x%08X helpPtr=0x%08X helpTitle="%s" help="%s" idx="%s"'):fmt(
        tonumber(accessxi.help_desk_any_probe_count) or 0,
        accessxi.escape_probe_log_text(reason or ''),
        tonumber(key) or 0,
        accessxi.escape_probe_log_text(menu_name),
        accessxi.is_help_desk_menu_name(menu_name) and 1 or 0,
        tonumber(selected) or 0,
        tonumber(count) or 0,
        tonumber(page) or 0,
        tonumber(raw) or 0,
        tonumber(obj) or 0,
        tonumber(child) or 0,
        tonumber(entry) or 0,
        ank_num,
        sub,
        sub_x,
        sub_y,
        help_title_ptr,
        help_ptr,
        accessxi.escape_probe_log_text(read_probe_string(help_title_ptr)),
        accessxi.escape_probe_log_text(read_probe_string(help_ptr)),
        idx_line));
end

function accessxi.log_help_desk_diff_probe(menu_name, obj, child, entry, selected, count, page, raw, ank_num, target)
    if ((tonumber(accessxi.help_desk_diff_probe_until) or 0) < tick()) then
        return;
    end
    menu_name = tostring(menu_name or '');
    if (not accessxi.is_help_desk_menu_name(menu_name)) then
        return;
    end

    local now = tick();
    if (now < (tonumber(accessxi.help_desk_diff_probe_next) or 0)) then
        return;
    end
    if ((tonumber(accessxi.help_desk_diff_probe_count) or 0) >= (tonumber(accessxi.help_desk_diff_probe_limit) or 0)) then
        return;
    end
    accessxi.help_desk_diff_probe_next = now + 90;
    accessxi.help_desk_diff_probe_count = (tonumber(accessxi.help_desk_diff_probe_count) or 0) + 1;

    target = target or safe_call(function () return AshitaCore:GetMemoryManager():GetTarget(); end, nil);
    ank_num = tonumber(ank_num) or -1;
    local shape = 0;
    if (target ~= nil and ank_num >= 0 and ank_num <= 16) then
        shape = tonumber(safe_call(function () return target:GetWindowAnkShape(ank_num); end, 0)) or 0;
    end

    accessxi.help_desk_diff_probe_seen = accessxi.help_desk_diff_probe_seen or {};
    local session = accessxi.help_desk_diff_probe_seen;
    accessxi.menu_dump_sequence = (tonumber(accessxi.menu_dump_sequence) or 0) + 1;
    local seq = accessxi.menu_dump_sequence;

    local function snapshot_region(name, ptr, bytes)
        ptr = tonumber(ptr) or 0;
        bytes = tonumber(bytes) or 0;
        if (not accessxi.is_probe_pointer(ptr) or bytes <= 0 or bytes > 0x500) then
            return;
        end

        local key = ('%s:0x%08X:%03X'):fmt(name, ptr, bytes);
        local prev = session[key];
        local next_values = {};
        local changes = T{};
        for off = 0, bytes - 4, 4 do
            local value = read_u32(ptr + off) or 0;
            next_values[off] = value;
            if (prev ~= nil and prev[off] ~= nil and prev[off] ~= value) then
                changes:append(('+%03X:%08X>%08X'):fmt(off, tonumber(prev[off]) or 0, value));
                if (changes:len() >= 24) then
                    break;
                end
            end
        end
        session[key] = next_values;

        if (prev == nil) then
            log_state(('state helpdesk diff-baseline seq=%d region=%s ptr=0x%08X bytes=0x%03X d00="%s"'):fmt(
                seq,
                name,
                ptr,
                bytes,
                accessxi.escape_probe_log_text(accessxi.format_probe_dwords(ptr, 0x00, math.min(16, math.floor(bytes / 4))))));
            return;
        end
        if (changes:len() > 0) then
            log_state(('state helpdesk diff seq=%d region=%s ptr=0x%08X selected=%d count=%d page=%d raw=0x%08X ank=%d changes="%s"'):fmt(
                seq,
                name,
                ptr,
                tonumber(selected) or 0,
                tonumber(count) or 0,
                tonumber(page) or 0,
                tonumber(raw) or 0,
                ank_num,
                changes:concat(' ')));
        end
    end

    snapshot_region('obj', obj, 0x180);
    snapshot_region('child', child, 0x240);
    snapshot_region('entry', entry, 0x180);
    snapshot_region('shape', shape, 0x140);

    local first = accessxi.is_probe_pointer(child) and (read_u32(child + 0x14) or 0) or 0;
    snapshot_region('first', first, 0x180);
    for off = 0, 0x40, 4 do
        local node = accessxi.is_probe_pointer(first) and (read_u32(first + off) or 0) or 0;
        if (accessxi.is_probe_pointer(node)) then
            snapshot_region(('node+%02X'):fmt(off), node, 0x120);
        end
    end

    local idx_parts = T{};
    for _, off in ipairs(T{ 0x24, 0x28, 0x2C, 0x30, 0x34, 0x38, 0x3C, 0x40, 0x44, 0x48, 0x4C, 0x50, 0x54, 0x58, 0x5C, 0x60, 0x64, 0x68, 0x6C, 0x70, 0x74, 0x78, 0x7C, 0x80, 0x84, 0x88, 0x8C, 0x90 }) do
        idx_parts:append(('%02X=%d'):fmt(off, tonumber(read_current_native_menu_index(off)) or 0));
    end
    local idx_line = idx_parts:concat(' ');
    if (idx_line ~= tostring(accessxi.help_desk_diff_probe_last_idx or '')) then
        accessxi.help_desk_diff_probe_last_idx = idx_line;
        log_state(('state helpdesk diff-index seq=%d selected=%d count=%d page=%d raw=0x%08X ank=%d obj=0x%08X child=0x%08X entry=0x%08X shape=0x%08X idx="%s"'):fmt(
            seq,
            tonumber(selected) or 0,
            tonumber(count) or 0,
            tonumber(page) or 0,
            tonumber(raw) or 0,
            ank_num,
            tonumber(obj) or 0,
            tonumber(child) or 0,
            tonumber(entry) or 0,
            shape,
            idx_line));
    end
end

function accessxi.help_desk_small_i32_fields(ptr, offsets)
    ptr = tonumber(ptr) or 0;
    local parts = T{};
    if (not accessxi.is_probe_pointer(ptr)) then
        return '';
    end

    for _, off in ipairs(offsets) do
        local value = read_i32(ptr + off);
        if (value ~= nil) then
            value = tonumber(value) or 0;
            if (value >= -1 and value <= 65535) then
                parts:append(('%03X=%d'):fmt(off, value));
            end
        end
    end

    return parts:concat(' ');
end

