function accessxi.poll_help_desk_shape_probe()
    if (tick() > (tonumber(accessxi.help_desk_shape_probe_until) or 0)) then
        return;
    end

    accessxi.log_help_desk_light_probe('poll');
end

function accessxi.help_desk_menu_speech(menu_name, title, obj, selected, count, page, raw, child, entry)
    menu_name = tostring(menu_name or '');
    if (not accessxi.is_help_desk_menu_name(menu_name)) then
        return nil;
    end

    selected = tonumber(selected) or 0;
    count = tonumber(count) or 0;
    local raw_selected = selected;
    if (selected <= 0) then
        selected = read_current_native_menu_index(0x4C);
    end
    if (count <= 0 or count > 64) then
        count = math.max(tonumber(accessxi.native_menu_index(0x24)) or 0, tonumber(accessxi.native_menu_index(0x28)) or 0);
    end

    local rows, mode = accessxi.help_desk_menu_items(menu_name, child, count, page, raw);
    local config_submenu_state = false;
    local target = safe_call(function () return AshitaCore:GetMemoryManager():GetTarget(); end, nil);
    local ank_num = target ~= nil and (tonumber(safe_call(function () return target:GetWindowAnkNum(); end, -1)) or -1) or -1;
    local sub = target ~= nil and (tonumber(safe_call(function () return target:GetWindowSub(); end, -1)) or -1) or -1;
    local sub_x = target ~= nil and (tonumber(safe_call(function () return target:GetWindowSubAnkX(); end, -1)) or -1) or -1;
    local sub_y = target ~= nil and (tonumber(safe_call(function () return target:GetWindowSubAnkY(); end, -1)) or -1) or -1;
    local focus_index = target ~= nil and (tonumber(safe_call(function () return target:GetFocusTargetIndex(); end, -1)) or -1) or -1;
    local focus_server = target ~= nil and (tonumber(safe_call(function () return target:GetFocusTargetServerId(); end, -1)) or -1) or -1;
    local menu_lock = target ~= nil and (tonumber(safe_call(function () return target:GetMenuTargetLock(); end, -1)) or -1) or -1;
    local window_loaded = target ~= nil and (tonumber(safe_call(function () return target:GetWindowIsWindowLoaded(); end, -1)) or -1) or -1;
    local help_title_ptr = target ~= nil and (tonumber(safe_call(function () return target:GetWindowHelpTitle(); end, 0)) or 0) or 0;
    local help_ptr = target ~= nil and (tonumber(safe_call(function () return target:GetWindowHelpString(); end, 0)) or 0) or 0;
    local help_title = read_probe_string(help_title_ptr);
    local help_text = read_probe_string(help_ptr);
    local probe_active = tick() <= (tonumber(accessxi.help_desk_shape_probe_until) or 0);
    local active_shape = 0;
    if (probe_active) then
        active_shape = accessxi.log_help_desk_shape_trace(menu_name, title, selected, count, page, raw, child, entry, ank_num, target);
        accessxi.log_help_desk_shape_grid_trace(menu_name, selected, count, raw, child, entry, ank_num, target);
        if (menu_name:eq('menu    faqmain', true)) then
            accessxi.log_help_desk_shape_probe('active', tonumber(accessxi.help_desk_shape_probe_last_key) or 0);
        else
            accessxi.log_help_desk_shape_probe('speech', tonumber(accessxi.help_desk_shape_probe_last_key) or 0);
        end
    end
    accessxi.log_help_desk_diff_probe(menu_name, obj, child, entry, selected, count, page, raw, ank_num, target);
    local native_4c = read_current_native_menu_index(0x4C);
    if (probe_active) then
        local cursor_parts = T{};
        for _, off in ipairs(T{ 0x24, 0x28, 0x2C, 0x30, 0x34, 0x38, 0x3C, 0x40, 0x44, 0x48, 0x4C, 0x50, 0x54, 0x58, 0x5C, 0x60, 0x64, 0x68, 0x6C, 0x70, 0x74, 0x78, 0x7C, 0x80 }) do
            cursor_parts:append(('%02X=%d'):fmt(off, tonumber(read_current_native_menu_index(off)) or 0));
        end
        local cursor_line = cursor_parts:concat(' ');
        local cursor_key = ('%s:%d:%d:0x%08X:0x%08X:0x%08X:%d:%d:%d:%d:%d:%d:%d:%d:0x%08X:0x%08X:%s:%s:%s'):fmt(
            menu_name,
            selected,
            count,
            tonumber(obj) or 0,
            tonumber(child) or 0,
            tonumber(entry) or 0,
            ank_num,
            sub,
            sub_x,
            sub_y,
            focus_index,
            focus_server,
            menu_lock,
            window_loaded,
            help_title_ptr,
            help_ptr,
            help_title,
            help_text,
            cursor_line);
        if (cursor_key ~= tostring(accessxi.last_help_desk_cursor_trace_key or '')) then
            accessxi.last_help_desk_cursor_trace_key = cursor_key;
            log_state(('state helpdesk cursor menu="%s" selected=%d count=%d obj=0x%08X child=0x%08X entry=0x%08X ank=%d shape=0x%08X sub=%d subXY=(%d,%d) focus=%d server=%d lock=%d loaded=%d helpTitlePtr=0x%08X helpPtr=0x%08X helpTitle="%s" help="%s" idx="%s"'):fmt(
                menu_name,
                selected,
                count,
                tonumber(obj) or 0,
                tonumber(child) or 0,
                tonumber(entry) or 0,
                ank_num,
                active_shape,
                sub,
                sub_x,
                sub_y,
                focus_index,
                focus_server,
                menu_lock,
                window_loaded,
                help_title_ptr,
                help_ptr,
                accessxi.escape_probe_log_text(help_title),
                accessxi.escape_probe_log_text(help_text),
                cursor_line));
        end
    end
    local cursor_source = 'native';
    local helpdesk_row0 = -1;
    local suppress_config_body_text = false;
    local config_body_row0 = -1;
    local config_body_line_count = 0;
    local config_body_visible_rows = 0;
    local first = accessxi.is_probe_pointer(child) and (read_u32(child + 0x14) or 0) or 0;
    local config_field_state = false;
    if (accessxi.is_probe_pointer(first)) then
        helpdesk_row0 = tonumber(read_u32(first + 0x128)) or -1;
        if (rows ~= nil and rows:len() > 0 and helpdesk_row0 >= 0 and helpdesk_row0 < rows:len()) then
            selected = helpdesk_row0 + 1;
            cursor_source = 'first+128';
        end
        config_field_state = accessxi.is_help_desk_config_submenu_field_state(menu_name, count, page, raw, first, helpdesk_row0, raw_selected);
        if (not config_field_state) then
            accessxi.help_desk_config_column_state = '';
            accessxi.help_desk_config_active = false;
        end
        if (config_field_state) then
            local config_row0 = tonumber(read_i32(first + 0x154)) or -1;
            config_body_line_count = tonumber(read_i32(first + 0x110)) or 0;
            config_body_visible_rows = tonumber(read_i32(first + 0x150)) or 0;
            local config_region = tonumber(read_i32(first + 0x158)) or -1;
            local config_region_low = config_region >= 0 and (config_region % 65536) or -1;
            local action_rows = accessxi.help_desk_config_resource_items(page, raw, count);
            local action_len = action_rows ~= nil and action_rows:len() or 0;
            local config_surface_shape = config_body_visible_rows == 5
                and (config_region == 655361 or config_region == 655360)
                and (config_body_line_count == 14 or config_body_line_count == 3);
            local config_left_action_region = false;
            local config_back_region = false;
            if (config_surface_shape
                and config_body_line_count == 14
                and config_row0 >= 0
                and config_row0 < action_len) then
                config_submenu_state = true;
                accessxi.help_desk_config_active = true;
                config_left_action_region = true;
                accessxi.help_desk_config_column_state = 'action';
            elseif (config_surface_shape and config_body_line_count == 3) then
                config_submenu_state = true;
                config_back_region = true;
                accessxi.help_desk_config_active = false;
                accessxi.help_desk_config_column_state = '';
            elseif (config_surface_shape) then
                config_submenu_state = true;
                accessxi.help_desk_config_active = true;
                accessxi.help_desk_config_column_state = 'body';
            else
                config_submenu_state = false;
                accessxi.help_desk_config_column_state = '';
                accessxi.help_desk_config_active = false;
            end
            if (config_submenu_state) then
                accessxi.log_help_desk_config_cursor_state(menu_name, first, selected, raw_selected, count, page, raw, child, entry, rows ~= nil and rows:len() or 0, cursor_source);
                if (config_left_action_region) then
                    if (action_rows ~= nil and action_rows:len() > 0) then
                        rows = action_rows;
                        mode = 'dat-resource:165/72:config-action';
                        if (config_row0 >= 0 and config_row0 < action_rows:len()) then
                            selected = config_row0 + 1;
                            helpdesk_row0 = config_row0;
                            cursor_source = 'first+154-action';
                        else
                            suppress_config_body_text = true;
                            config_body_row0 = config_row0;
                        end
                    end
                elseif (config_back_region) then
                    rows = T{ { label = 'Back', dat = 'ROM\\165\\72.DAT', row = 199 } };
                    selected = 1;
                    helpdesk_row0 = config_row0;
                    cursor_source = 'first+154-back';
                    mode = 'dat-resource:165/72:config-back';
                    accessxi.help_desk_config_active = false;
                elseif (config_body_line_count == 14 or config_region_low == 0) then
                    accessxi.help_desk_config_column_state = 'body';
                    suppress_config_body_text = true;
                    config_body_row0 = config_row0;
                elseif (rows ~= nil and rows:len() > 0 and config_row0 >= 0 and config_row0 < rows:len()) then
                    selected = config_row0 + 1;
                    helpdesk_row0 = config_row0;
                    cursor_source = 'first+154';
                end
                accessxi.help_desk_config_row0 = config_row0;
                accessxi.help_desk_config_region = config_region;
                accessxi.help_desk_config_idx5c = read_current_native_menu_index(0x5C);
            end
        end
    end
    -- ANK state in the Help Desk Config submenu appears to describe the
    -- renderer's active shape, not the selected row. Keep it probe-only until
    -- a stable native cursor field is identified.
    if (menu_name:eq('menu    faqmain', true) and rows ~= nil and rows:len() > 0) then
        local faqmain_row0 = tonumber(read_i32(child + 0x14)) or -1;
        if (faqmain_row0 >= 0 and faqmain_row0 < rows:len()) then
            selected = faqmain_row0 + 1;
            cursor_source = 'child+14';
        end
    end
    if ((selected <= 0 or rows == nil or selected > rows:len())
        and native_4c > 0 and rows ~= nil and native_4c <= rows:len()) then
        selected = native_4c;
        cursor_source = 'obj+4c';
    end
    if (suppress_config_body_text) then
        local body_key = ('%s:%d:%d:%d:0x%08X:%d'):fmt(
            menu_name,
            selected,
            count,
            tonumber(page) or 0,
            tonumber(raw) or 0,
            config_body_row0);
        if (body_key ~= tostring(accessxi.last_help_desk_config_body_key or '')) then
            accessxi.last_help_desk_config_body_key = body_key;
            log_state(('state helpdesk config-body-silent menu="%s" selected=%d row0=%d ank=%d bodyLines=%d visibleRows=%d count=%d page=%d raw=0x%08X child=0x%08X entry=0x%08X'):fmt(
                menu_name,
                selected,
                config_body_row0,
                ank_num,
                config_body_line_count,
                config_body_visible_rows,
                count,
                tonumber(page) or 0,
                tonumber(raw) or 0,
                tonumber(child) or 0,
                tonumber(entry) or 0));
        end
        return nil;
    end
    if (rows ~= nil and rows:len() > 0 and selected > rows:len() and menu_name:eq('menu    faqsub', true) and not config_submenu_state) then
        selected = rows:len();
        cursor_source = cursor_source .. '-clamped';
    end
    local row = rows ~= nil and rows[selected] or nil;
    local label = row ~= nil and accessxi.plain_native_menu_label(row.label or '') or '';
    local key = ('%s:%d:%d:%d:0x%08X:%s:%s'):fmt(
        menu_name,
        selected,
        count,
        tonumber(page) or 0,
        tonumber(raw) or 0,
        tostring(mode or ''),
        label);
    if (key ~= tostring(accessxi.last_help_desk_menu_log_key or '')) then
        accessxi.last_help_desk_menu_log_key = key;
        log_state(('state helpdesk native menu="%s" title="%s" select=%d source="%s" row0=%d ank=%d idx4c=%d count=%d rowCount=%d page=%d raw=0x%08X child=0x%08X entry=0x%08X mode="%s" label="%s"'):fmt(
            menu_name,
            accessxi.escape_probe_log_text(title or ''),
            selected,
            cursor_source,
            helpdesk_row0,
            ank_num,
            native_4c,
            count,
            rows ~= nil and rows:len() or 0,
            tonumber(page) or 0,
            tonumber(raw) or 0,
            tonumber(child) or 0,
            tonumber(entry) or 0,
            tostring(mode or ''),
            accessxi.escape_probe_log_text(label)));
    end

    if (label == '') then
        accessxi.log_help_desk_faqmain_missing_text(menu_name, title, obj, selected, count, page, raw, child, entry, mode);
        local compact_key = ('%s:%d:%d:0x%08X:0x%08X:0x%08X:%s'):fmt(
            menu_name,
            selected,
            count,
            tonumber(obj) or 0,
            tonumber(child) or 0,
            tonumber(entry) or 0,
            tostring(mode or ''));
        if (compact_key ~= tostring(accessxi.last_help_desk_missing_compact_key or '')) then
            accessxi.last_help_desk_missing_compact_key = compact_key;
            log_state(('state helpdesk missing-compact menu="%s" selected=%d count=%d objIdx="%s" childIdx="%s" entryD00=%s mode="%s"'):fmt(
                menu_name,
                selected,
                count,
                accessxi.format_probe_index_fields(tonumber(obj) or 0, 0x00, 0x80),
                accessxi.format_probe_index_fields(tonumber(child) or 0, 0x00, 0x80),
                accessxi.format_probe_dwords(tonumber(entry) or 0, 0x00, 16),
                tostring(mode or '')));
        end
        return nil;
    end

    accessxi.last_native_menu_name = menu_name;
    accessxi.last_native_menu_label = label;
    accessxi.last_native_menu_selected = selected;
    accessxi.last_native_menu_tick = tick();
    accessxi.current_speech_key = ('helpdesk-native:%s:%d:%d:%d:%s'):fmt(
        menu_name,
        selected,
        tonumber(page) or 0,
        count,
        label);
    return ('%s. %s.'):fmt(title, label);
end

function accessxi.adventuring_primer_entry_probe(entry)
    entry = tonumber(entry) or 0;
    if (not accessxi.is_probe_pointer(entry)) then
        return 'entry-unreadable';
    end

    local parts = T{};
    for _, off in ipairs(T{ 0x00, 0x04, 0x08, 0x0C, 0x10, 0x14, 0x18, 0x1C, 0x20, 0x24, 0x28, 0x2C, 0x30, 0x34, 0x38, 0x3C, 0x40, 0x44, 0x48, 0x4C, 0x50, 0x54, 0x58, 0x5C, 0x60, 0x64, 0x68, 0x6C, 0x70, 0x74, 0x78, 0x7C, 0x80 }) do
        local value = read_u32(entry + off) or 0;
        if (accessxi.is_probe_pointer(value)) then
            local direct = accessxi.plain_native_menu_help(read_probe_string(value, 220));
            local nested = accessxi.probe_strings_at(value);
            if (direct ~= '' or nested ~= '') then
                parts:append(('+%02X=0x%08X direct="%s" nested="%s"'):fmt(
                    off,
                    value,
                    accessxi.escape_probe_log_text(direct),
                    accessxi.escape_probe_log_text(nested)));
            end
        end
    end

    return parts:len() > 0 and parts:concat(' | ') or 'no-text-pointers';
end

function accessxi.adventuring_primer_descriptor_probe(desc)
    desc = tonumber(desc) or 0;
    if (not accessxi.is_probe_pointer(desc)) then
        return 'desc-unreadable';
    end

    local parts = T{};
    for _, off in ipairs(T{ 0x00, 0x04, 0x08, 0x0C, 0x10, 0x14, 0x18, 0x1C, 0x20, 0x24, 0x28, 0x2C, 0x30, 0x34, 0x38, 0x3C, 0x40, 0x44, 0x48, 0x4C, 0x50, 0x54, 0x58, 0x5C, 0x60, 0x64, 0x68, 0x6C, 0x70, 0x74, 0x78, 0x7C, 0x80, 0x84, 0x88, 0x8C, 0x90, 0x94, 0x98, 0x9C, 0xA0 }) do
        local value = read_u32(desc + off) or 0;
        if (accessxi.is_probe_pointer(value)) then
            local direct = accessxi.plain_native_menu_help(read_probe_string(value, 220));
            local nested = accessxi.probe_strings_at(value);
            if (direct ~= '' or nested ~= '') then
                parts:append(('+%02X=0x%08X direct="%s" nested="%s"'):fmt(
                    off,
                    value,
                    accessxi.escape_probe_log_text(direct),
                    accessxi.escape_probe_log_text(nested)));
            end
        end
    end

    local near = accessxi.collect_probe_ffxi_utf16_runs(desc - 0x80, 0x240, 3, 16);
    if (#near > 0) then
        parts:append(('nearText="%s"'):fmt(near:concat(' ')));
    end

    local ascii = accessxi.collect_probe_ascii_runs(desc - 0x80, 0x240, 3, 16);
    if (#ascii > 0) then
        parts:append(('nearAscii="%s"'):fmt(ascii:concat(' ')));
    end

    return parts:len() > 0 and parts:concat(' | ') or 'desc-no-text';
end

function accessxi.adventuring_primer_render_text_probe()
    local target = safe_call(function () return AshitaCore:GetMemoryManager():GetTarget(); end, nil);
    if (target == nil) then
        return 'no-target';
    end

    local ank_num = tonumber(safe_call(function () return target:GetWindowAnkNum(); end, -1)) or -1;
    local limit = math.min(math.max(ank_num, 0), 8);
    local parts = T{};
    local seen = {};

    local function add_text(label, ptr)
        ptr = tonumber(ptr) or 0;
        if (not accessxi.is_probe_pointer(ptr) or seen[ptr] == true or parts:len() >= 18) then
            return;
        end
        seen[ptr] = true;

        local ffxi16 = '';
        if (accessxi.collect_probe_ffxi_utf16_runs ~= nil) then
            ffxi16 = accessxi.probe_runs_to_text(accessxi.collect_probe_ffxi_utf16_runs(ptr, 0x320, 2, 10));
        end
        local utf16 = accessxi.probe_utf16le_runs_at(ptr, 0x240, 8);
        local strings = accessxi.probe_strings_at(ptr);
        local text = T{};
        if (ffxi16 ~= '') then
            text:append(('ffxi="%s"'):fmt(accessxi.escape_probe_log_text(ffxi16)));
        end
        if (utf16 ~= '') then
            text:append(('utf16="%s"'):fmt(accessxi.escape_probe_log_text(utf16)));
        end
        if (strings ~= '') then
            text:append(('strings="%s"'):fmt(accessxi.escape_probe_log_text(strings)));
        end
        if (text:len() > 0) then
            parts:append(('%s@0x%08X{%s}'):fmt(tostring(label or 'ptr'), ptr, text:concat(' ')));
        end
    end

    local function scan_shape(index)
        index = tonumber(index) or 0;
        if (index < 0 or index > 16) then
            return;
        end
        local shape = tonumber(safe_call(function () return target:GetWindowAnkShape(index); end, 0)) or 0;
        if (not accessxi.is_probe_pointer(shape)) then
            return;
        end
        add_text(('shape%d'):fmt(index), shape);
        for off = 0x00, 0x80, 4 do
            local ptr = read_u32(shape + off) or 0;
            if (accessxi.is_probe_pointer(ptr)) then
                add_text(('shape%d+%02X'):fmt(index, off), ptr);
            end
        end
    end

    if (ank_num >= 0 and ank_num <= 16) then
        scan_shape(ank_num);
    end
    for i = 0, limit do
        scan_shape(i);
    end

    return parts:len() > 0 and parts:concat(' || ') or ('no-render-text ank=%d'):fmt(ank_num);
end

function accessxi.adventuring_primer_child_pointer_probe(child)
    child = tonumber(child) or 0;
    if (not accessxi.is_probe_pointer(child)) then
        return 'child-unreadable';
    end

    local parts = T{};
    local seen = {};
    for _, off in ipairs(T{ 0xF0, 0xF4, 0xF8, 0xFC, 0x100, 0x104, 0x108, 0x10C, 0x110, 0x114, 0x118, 0x11C }) do
        local ptr = read_u32(child + off) or 0;
        if (accessxi.is_probe_pointer(ptr) and seen[ptr] ~= true) then
            seen[ptr] = true;
            local d00 = accessxi.format_probe_dwords(ptr, 0x00, 16);
            local d40 = accessxi.format_probe_dwords(ptr, 0x40, 8);
            local fragments = accessxi.adventuring_primer_render_fragment_probe(ptr, 10);
            parts:append(('+%03X=0x%08X d00="%s" d40="%s" rows="%s"'):fmt(
                off,
                ptr,
                accessxi.escape_probe_log_text_wide(d00),
                accessxi.escape_probe_log_text_wide(d40),
                accessxi.escape_probe_log_text_wide(fragments)));
            if (parts:len() >= 4) then
                break;
            end
        end
    end

    return parts:len() > 0 and parts:concat(' || ') or 'no-child-pointers';
end

function accessxi.adventuring_primer_render_fragment_probe(ptr, max_records)
    ptr = tonumber(ptr) or 0;
    if (not accessxi.is_probe_pointer(ptr)) then
        return '';
    end

    max_records = math.max(1, math.min(tonumber(max_records) or 8, 12));
    local parts = T{};
    for index = 0, max_records - 1 do
        local off = index * 0x18;
        local font_ptr = read_u32(ptr + off) or 0;
        local text_ptr1 = read_u32(ptr + off + 0x04) or 0;
        local len1 = read_u32(ptr + off + 0x08) or 0;
        local text_ptr2 = read_u32(ptr + off + 0x0C) or 0;
        local len2 = read_u32(ptr + off + 0x10) or 0;
        local flags = read_u32(ptr + off + 0x14) or 0;
        if (font_ptr == 0 and text_ptr1 == 0 and len1 == 0 and text_ptr2 == 0 and len2 == 0 and flags == 0) then
            parts:append(('%02d empty'):fmt(index + 1));
        else
            local read_len1 = math.max(1, math.min(len1 + 2, 180));
            local read_len2 = math.max(1, math.min(len2 + 2, 180));
            local text1 = accessxi.is_probe_pointer(text_ptr1) and read_probe_string(text_ptr1, read_len1) or '';
            local text2 = accessxi.is_probe_pointer(text_ptr2) and read_probe_string(text_ptr2, read_len2) or '';
            parts:append(('%02d p1=0x%08X l1=%d t1="%s" p2=0x%08X l2=%d t2="%s" flags=0x%08X'):fmt(
                index + 1,
                text_ptr1,
                len1,
                accessxi.escape_probe_log_text(text1),
                text_ptr2,
                len2,
                accessxi.escape_probe_log_text(text2),
                flags));
        end
    end

    return parts:concat(' | ');
end

function accessxi.adventuring_primer_render_fragment_label(ptr, visible_index)
    ptr = tonumber(ptr) or 0;
    visible_index = tonumber(visible_index) or 0;
    if (not accessxi.is_probe_pointer(ptr) or visible_index < 1 or visible_index > 12) then
        return '', '', 0, 0, '', 0, 0, 0, 0;
    end

    local row_off = (visible_index - 1) * 0x18;
    local text_ptr1 = read_u32(ptr + row_off + 0x04) or 0;
    local len1 = read_u32(ptr + row_off + 0x08) or 0;
    local text_ptr2 = read_u32(ptr + row_off + 0x0C) or 0;
    local len2 = read_u32(ptr + row_off + 0x10) or 0;
    local flags = read_u32(ptr + row_off + 0x14) or 0;
    local text1 = accessxi.is_probe_pointer(text_ptr1) and read_probe_string(text_ptr1, math.max(1, math.min(len1 + 2, 180))) or '';
    local text2 = accessxi.is_probe_pointer(text_ptr2) and read_probe_string(text_ptr2, math.max(1, math.min(len2 + 2, 180))) or '';
    local label = accessxi.plain_native_menu_label(text2);
    if (label == '') then
        label = accessxi.plain_native_menu_label(text1);
    end

    return label, text1, text_ptr1, len1, text2, text_ptr2, len2, flags, row_off;
end

function accessxi.adventuring_primer_visible_row_label(child, visible_index)
    child = tonumber(child) or 0;
    visible_index = tonumber(visible_index) or 0;
    if (not accessxi.is_probe_pointer(child) or visible_index < 1 or visible_index > 12) then
        return '', '', 0, 0, '', 0, 0, 0, 0, 0, 0;
    end

    local row_ptr_address = child + 0xF0 + ((visible_index - 1) * 4);
    local row_ptr = read_u32(row_ptr_address) or 0;
    if (not accessxi.is_probe_pointer(row_ptr)) then
        return '', '', 0, 0, '', 0, 0, 0, 0, row_ptr, row_ptr_address;
    end

    local label, text1, text_ptr1, len1, text2, text_ptr2, len2, flags, row_off = accessxi.adventuring_primer_render_fragment_label(row_ptr, 1);
    return label, text1, text_ptr1, len1, text2, text_ptr2, len2, flags, row_off, row_ptr, row_ptr_address;
end

function accessxi.adventuring_primer_logical_row_label(child, logical_index)
    child = tonumber(child) or 0;
    logical_index = tonumber(logical_index) or 0;
    if (not accessxi.is_probe_pointer(child) or logical_index < 1 or logical_index > 128) then
        return '', '', 0, 0, '', 0, 0, 0, 0, 0, 0;
    end

    local row_ptr_address = child + 0xF0 + ((logical_index - 1) * 4);
    local row_ptr = read_u32(row_ptr_address) or 0;
    if (not accessxi.is_probe_pointer(row_ptr)) then
        return '', '', 0, 0, '', 0, 0, 0, 0, row_ptr, row_ptr_address;
    end

    local label, text1, text_ptr1, len1, text2, text_ptr2, len2, flags, row_off = accessxi.adventuring_primer_render_fragment_label(row_ptr, 1);
    return label, text1, text_ptr1, len1, text2, text_ptr2, len2, flags, row_off, row_ptr, row_ptr_address;
end

function accessxi.log_adventuring_primer_guide01_probe(menu_name, title, obj, selected, count, page, raw, child, entry, reason)
    menu_name = tostring(menu_name or '');
    if (not menu_name:eq('menu    guide01', true)) then
        return;
    end

    obj = tonumber(obj) or 0;
    child = tonumber(child) or 0;
    entry = tonumber(entry) or 0;
    selected = tonumber(selected) or 0;
    count = tonumber(count) or 0;
    page = tonumber(page) or 0;
    raw = tonumber(raw) or 0;
    local obj4c = read_current_native_menu_index(0x4C);
    local child40 = 0;
    local child44 = 0;
    local child4c = 0;
    local child30 = 0;
    local child3c = 0;
    local child64 = 0;
    if (accessxi.is_probe_pointer(child)) then
        child30 = read_i32(child + 0x30) or 0;
        child3c = read_i32(child + 0x3C) or 0;
        child40 = read_i32(child + 0x40) or 0;
        child44 = read_i32(child + 0x44) or 0;
        child4c = read_i32(child + 0x4C) or 0;
        child64 = read_i32(child + 0x64) or 0;
    end
    local desc = accessxi.is_probe_pointer(entry) and (read_u32(entry + 0x0C) or 0) or 0;
    local label, text1, text_ptr1, len1, text2, text_ptr2, len2, flags, row_off, row_ptr, row_ptr_address = accessxi.adventuring_primer_visible_row_label(child, obj4c);
    local key = ('%s:%d:%d:%d:%08X:%08X:%08X:%08X:%d:%d:%d:%d:%d:%d:%s'):fmt(
        tostring(reason or ''),
        selected,
        count,
        raw,
        obj,
        child,
        entry,
        desc,
        obj4c,
        child30,
        child3c,
        child40,
        child4c,
        child64,
        label);
    if (key == tostring(accessxi.last_adventuring_primer_guide01_probe_key or '')) then
        return;
    end
    accessxi.last_adventuring_primer_guide01_probe_key = key;

    log_state(('state adventuring-primer guide01-selected menu="%s" title="%s" reason="%s" select=%d count=%d page=%d raw=0x%08X obj4c=%d child30=%d child3c=%d child40=%d child44=%d child4c=%d child64=%d obj=0x%08X child=0x%08X entry=0x%08X desc=0x%08X rowPtrAddr=0x%08X rowPtr=0x%08X rowOff=0x%02X label="%s" p1=0x%08X l1=%d t1="%s" p2=0x%08X l2=%d t2="%s" flags=0x%08X'):fmt(
        menu_name,
        accessxi.escape_probe_log_text(tostring(title or '')),
        accessxi.escape_probe_log_text(tostring(reason or '')),
        selected,
        count,
        page,
        raw,
        obj4c,
        child30,
        child3c,
        child40,
        child44,
        child4c,
        child64,
        obj,
        child,
        entry,
        desc,
        row_ptr_address,
        row_ptr,
        row_off,
        accessxi.escape_probe_log_text(label),
        text_ptr1,
        len1,
        accessxi.escape_probe_log_text(text1),
        text_ptr2,
        len2,
        accessxi.escape_probe_log_text(text2),
         flags));
end

function accessxi.log_adventuring_primer_guide01_native_probe(menu_name, title, obj, selected, count, page, raw, child, entry, reason)
    menu_name = tostring(menu_name or '');
    if (not menu_name:eq('menu    guide01', true)) then
        return;
    end

    obj = tonumber(obj) or 0;
    child = tonumber(child) or 0;
    entry = tonumber(entry) or 0;
    selected = tonumber(selected) or 0;
    count = tonumber(count) or 0;
    page = tonumber(page) or 0;
    raw = tonumber(raw) or 0;

    local target = safe_call(function () return AshitaCore:GetMemoryManager():GetTarget(); end, nil);
    local window_name = accessxi.plain_native_menu_label(target ~= nil and safe_call(function () return target:GetWindowName(); end, '') or '');
    local ank_num = target ~= nil and (tonumber(safe_call(function () return target:GetWindowAnkNum(); end, -1)) or -1) or -1;
    local sub = target ~= nil and (tonumber(safe_call(function () return target:GetWindowSub(); end, -1)) or -1) or -1;
    local sub_x = target ~= nil and (tonumber(safe_call(function () return target:GetWindowSubAnkX(); end, -1)) or -1) or -1;
    local sub_y = target ~= nil and (tonumber(safe_call(function () return target:GetWindowSubAnkY(); end, -1)) or -1) or -1;
    local help_title_ptr = target ~= nil and (tonumber(safe_call(function () return target:GetWindowHelpTitle(); end, 0)) or 0) or 0;
    local help_ptr = target ~= nil and (tonumber(safe_call(function () return target:GetWindowHelpString(); end, 0)) or 0) or 0;
    local shape = 0;
    if (target ~= nil and ank_num >= 0 and ank_num <= 16) then
        shape = tonumber(safe_call(function () return target:GetWindowAnkShape(ank_num); end, 0)) or 0;
    end

    local obj4c = read_current_native_menu_index(0x4C);
    local child30 = accessxi.is_probe_pointer(child) and (read_i32(child + 0x30) or 0) or 0;
    local child3c = accessxi.is_probe_pointer(child) and (read_i32(child + 0x3C) or 0) or 0;
    local child40 = accessxi.is_probe_pointer(child) and (read_i32(child + 0x40) or 0) or 0;
    local child64 = accessxi.is_probe_pointer(child) and (read_i32(child + 0x64) or 0) or 0;
    local compact_key = ('%s:%d:%d:%d:%08X:%08X:%08X:%d:%d:%d:%d:%d'):fmt(
        tostring(reason or ''),
        selected,
        count,
        raw,
        obj,
        child,
        entry,
        obj4c,
        child30,
        child3c,
        child40,
        child64);
    if (compact_key ~= tostring(accessxi.last_adventuring_primer_guide01_native_probe_key or '')) then
        accessxi.last_adventuring_primer_guide01_native_probe_key = compact_key;
        log_state(('state adventuring-primer guide01-native menu="%s" title="%s" reason="%s" selected=%d count=%d page=%d raw=0x%08X obj4c=%d child30=%d child3c=%d child40=%d child64=%d obj=0x%08X child=0x%08X entry=0x%08X ank=%d shape=0x%08X sub=%d subXY=(%d,%d) window="%s" helpTitle=0x%08X "%s" help=0x%08X "%s" note="child+0xF0 rejected; screenshot rows differ"'):fmt(
            menu_name,
            accessxi.escape_probe_log_text(tostring(title or '')),
            accessxi.escape_probe_log_text(tostring(reason or '')),
            selected,
            count,
            page,
            raw,
            obj4c,
            child30,
            child3c,
            child40,
            child64,
            obj,
            child,
            entry,
            ank_num,
            shape,
            sub,
            sub_x,
            sub_y,
            accessxi.escape_probe_log_text(window_name),
            help_title_ptr,
            accessxi.escape_probe_log_text(read_probe_string(help_title_ptr)),
            help_ptr,
            accessxi.escape_probe_log_text(read_probe_string(help_ptr))));
    end

    local now = tick();
    local manual_probe = ((tonumber(accessxi.adventuring_primer_guide01_probe_until) or 0) >= now);
    local auto_session_key = ('%s:%d:%d:%08X:%08X:%d'):fmt(menu_name, count, page, obj, child, child64);
    if (auto_session_key ~= tostring(accessxi.adventuring_primer_guide01_auto_probe_session_key or '')) then
        accessxi.adventuring_primer_guide01_auto_probe_session_key = auto_session_key;
        accessxi.adventuring_primer_guide01_auto_probe_count = 0;
        accessxi.adventuring_primer_guide01_auto_probe_last_key = '';
        accessxi.adventuring_primer_guide01_auto_probe_next = 0;
    end

    local auto_probe = false;
    if ((not manual_probe)
        and (compact_key ~= tostring(accessxi.adventuring_primer_guide01_auto_probe_last_key or ''))
        and ((tonumber(accessxi.adventuring_primer_guide01_auto_probe_count) or 0) < 6)
        and (now >= (tonumber(accessxi.adventuring_primer_guide01_auto_probe_next) or 0))) then
        auto_probe = true;
        accessxi.adventuring_primer_guide01_auto_probe_last_key = compact_key;
        accessxi.adventuring_primer_guide01_auto_probe_next = now + 150;
    end

    if ((not manual_probe) and (not auto_probe)) then
        return;
    end

    local probe_mode = auto_probe and 'auto-row' or 'command';
    local probe_count = 0;
    if (manual_probe) then
        if (now < (tonumber(accessxi.adventuring_primer_guide01_probe_next) or 0)) then
            return;
        end
        if ((tonumber(accessxi.adventuring_primer_guide01_probe_count) or 0) >= (tonumber(accessxi.adventuring_primer_guide01_probe_limit) or 0)) then
            return;
        end
        accessxi.adventuring_primer_guide01_probe_next = now + 150;
        accessxi.adventuring_primer_guide01_probe_count = (tonumber(accessxi.adventuring_primer_guide01_probe_count) or 0) + 1;
        probe_count = tonumber(accessxi.adventuring_primer_guide01_probe_count) or 0;
    else
        accessxi.adventuring_primer_guide01_auto_probe_count = (tonumber(accessxi.adventuring_primer_guide01_auto_probe_count) or 0) + 1;
        probe_count = tonumber(accessxi.adventuring_primer_guide01_auto_probe_count) or 0;
    end

    accessxi.menu_dump_sequence = (tonumber(accessxi.menu_dump_sequence) or 0) + 1;
    local seq = accessxi.menu_dump_sequence;
    log_state(('state adventuring-primer guide01-probe seq=%d n=%d mode="%s" menu="%s" selected=%d count=%d page=%d raw=0x%08X obj=0x%08X child=0x%08X entry=0x%08X ank=%d shape=0x%08X idx="%s" render="%s" childPointers="%s"'):fmt(
        seq,
        probe_count,
        probe_mode,
        menu_name,
        selected,
        count,
        page,
        raw,
        obj,
        child,
        entry,
        ank_num,
        shape,
        accessxi.escape_probe_log_text(accessxi.format_probe_index_fields(obj, 0x00, 0x90)),
        accessxi.escape_probe_log_text_wide(accessxi.adventuring_primer_render_text_probe()),
        accessxi.escape_probe_log_text_wide(accessxi.adventuring_primer_child_pointer_probe(child))));

    accessxi.menu_dump_textptr_budget = 90;
    accessxi.log_probe_short_text_runs(seq, 'guide01.obj', obj, 0x260, 2, 14);
    accessxi.log_probe_pointer_text_targets(seq, 'guide01.obj', obj, 0x00, 0x140, 16);
    accessxi.log_probe_short_text_runs(seq, 'guide01.child', child, 0x300, 2, 16);
    accessxi.log_probe_pointer_text_targets(seq, 'guide01.child', child, 0x00, 0x180, 18);
    accessxi.log_probe_short_text_runs(seq, 'guide01.entry', entry, 0x180, 2, 10);
    accessxi.log_probe_pointer_text_targets(seq, 'guide01.entry', entry, 0x00, 0x100, 12);
    if (accessxi.is_probe_pointer(shape)) then
        log_line(('menudump seq=%d guide01.shape ptr=0x%08X d00=%s d40=%s d80=%s'):fmt(
            seq,
            shape,
            accessxi.format_probe_dwords(shape, 0x00, 16),
            accessxi.format_probe_dwords(shape, 0x40, 16),
            accessxi.format_probe_dwords(shape, 0x80, 12)));
        accessxi.log_probe_short_text_runs(seq, 'guide01.shape', shape, 0x300, 2, 16);
        accessxi.log_probe_pointer_text_targets(seq, 'guide01.shape', shape, 0x00, 0x140, 20);
    end
end

function accessxi.adventuring_primer_menu_speech(menu_name, title, obj, selected, count, page, raw, child, entry)
    menu_name = tostring(menu_name or '');
    if (not menu_name:eq('menu    guide00', true)) then
        return nil;
    end

    selected = tonumber(selected) or 0;
    count = tonumber(count) or 0;
    entry = tonumber(entry) or 0;
    local raw_index = tonumber(raw) or 0;
    local items = accessxi.adventuring_primer_top_items(page, raw_index, count);
    local item = (items ~= nil) and items[selected] or nil;
    if (item == nil or tostring(item.label or '') == '') then
        return nil;
    end

    local desc = accessxi.is_probe_pointer(entry) and (read_u32(entry + 0x0C) or 0) or 0;
    if (not accessxi.is_probe_pointer(desc)) then
        return nil;
    end

    local label = tostring(item.label or '');
    accessxi.adventuring_primer_current_category_label = label;
    accessxi.adventuring_primer_current_category_selected = selected;
    accessxi.adventuring_primer_current_category_tick = tick();
    accessxi.last_native_menu_name = menu_name;
    accessxi.last_native_menu_label = label;
    accessxi.last_native_menu_selected = selected;
    accessxi.last_native_menu_tick = tick();
    accessxi.current_speech_key = ('adventuring-primer:%s:%d:%d:%d:%d:%s'):fmt(
        menu_name,
        selected,
        tonumber(page) or 0,
        raw_index,
        count,
        label);
    local key = accessxi.current_speech_key;
    if (key ~= tostring(accessxi.last_adventuring_primer_row_key or '')) then
        accessxi.last_adventuring_primer_row_key = key;
        log_state(('state adventuring-primer native-row menu="%s" title="%s" select=%d count=%d page=%d raw=%d child=0x%08X entry=0x%08X desc=0x%08X label="%s" evidence="%s"'):fmt(
            menu_name,
            accessxi.escape_probe_log_text(tostring(title or '')),
            selected,
            count,
            tonumber(page) or 0,
            raw_index,
            tonumber(child) or 0,
            entry,
            desc,
            accessxi.escape_probe_log_text(label),
            accessxi.escape_probe_log_text(tostring(item.evidence or ''))));
    end
    return ('%s. %s.'):fmt(title, label);
end

function accessxi.adventuring_primer_guide01_menu_speech(menu_name, title, obj, selected, count, page, raw, child, entry)
    menu_name = tostring(menu_name or '');
    if (not menu_name:eq('menu    guide01', true)) then
        return nil;
    end

    selected = tonumber(selected) or 0;
    local raw_index = tonumber(raw) or 0;
    local category_label, category_index, category_source = accessxi.adventuring_primer_guide01_category_label(child);
    if (category_label ~= '') then
        accessxi.adventuring_primer_current_category_label = category_label;
        accessxi.adventuring_primer_current_category_selected = (tonumber(category_index) or -1) + 1;
        accessxi.adventuring_primer_current_category_tick = tick();
    else
        category_label = tostring(accessxi.adventuring_primer_current_category_label or '');
        category_source = 'guide00-current';
    end
    local record_id, position, source = accessxi.adventuring_primer_guide01_record_id(category_label, selected, raw_index);
    if (record_id <= 0 or record_id > 239) then
        local blocked_key = ('%s:%s:%d:%d:%d:%d'):fmt(menu_name, category_label, record_id, selected, raw_index, tonumber(count) or 0);
        if (blocked_key ~= tostring(accessxi.last_adventuring_primer_guide01_blocked_key or '')) then
            accessxi.last_adventuring_primer_guide01_blocked_key = blocked_key;
            log_state(('state adventuring-primer guide01-position-unmapped menu="%s" title="%s" category="%s" categoryIndex=%d categorySource="%s" selected=%d count=%d page=%d raw=%d position=%d source="%s" note="no DAT-backed article id; no fallback"'):fmt(
                menu_name,
                accessxi.escape_probe_log_text(tostring(title or '')),
                accessxi.escape_probe_log_text(category_label),
                tonumber(category_index) or -1,
                accessxi.escape_probe_log_text(tostring(category_source or '')),
                selected,
                tonumber(count) or 0,
                tonumber(page) or 0,
                raw_index,
                tonumber(position) or 0,
                accessxi.escape_probe_log_text(tostring(source or ''))));
        end
        return nil;
    end

    local titles = accessxi.load_adventuring_primer_article_titles();
    local label = (type(titles) == 'table') and tostring(titles[record_id] or '') or '';
    if (label == '') then
        local missing_key = ('%s:%d:%d:%d:%d'):fmt(menu_name, record_id, selected, raw_index, tonumber(count) or 0);
        if (missing_key ~= tostring(accessxi.last_adventuring_primer_guide01_missing_key or '')) then
            accessxi.last_adventuring_primer_guide01_missing_key = missing_key;
            log_state(('state adventuring-primer guide01-dat-missing menu="%s" title="%s" selected=%d count=%d page=%d raw=%d record=%d dat="ROM\\332\\48.DAT" note="blank DAT title slot; no fallback"'):fmt(
                menu_name,
                accessxi.escape_probe_log_text(tostring(title or '')),
                selected,
                tonumber(count) or 0,
                tonumber(page) or 0,
                raw_index,
                record_id));
        end
        return nil;
    end

    accessxi.remember_adventuring_primer_detail_candidate(record_id, label);
    accessxi.last_native_menu_name = menu_name;
    accessxi.last_native_menu_label = label;
    accessxi.last_native_menu_selected = record_id;
    accessxi.last_native_menu_tick = tick();
    accessxi.current_speech_key = ('adventuring-primer-guide01:%s:%s:%d:%d:%d:%d:%s'):fmt(
        menu_name,
        category_label,
        record_id,
        selected,
        raw_index,
        tonumber(count) or 0,
        label);
    local key = accessxi.current_speech_key;
    if (key ~= tostring(accessxi.last_adventuring_primer_guide01_dat_key or '')) then
        accessxi.last_adventuring_primer_guide01_dat_key = key;
        log_state(('state adventuring-primer guide01-dat-row menu="%s" title="%s" category="%s" categoryIndex=%d categorySource="%s" selected=%d count=%d page=%d raw=%d position=%d record=%d source="%s" dat="ROM\\332\\48.DAT" label="%s" evidence="record_base=record*0x0C00 title_offset=0x50 shift=5"'):fmt(
            menu_name,
            accessxi.escape_probe_log_text(tostring(title or '')),
            accessxi.escape_probe_log_text(category_label),
            tonumber(category_index) or -1,
            accessxi.escape_probe_log_text(tostring(category_source or '')),
            selected,
            tonumber(count) or 0,
            tonumber(page) or 0,
            raw_index,
            tonumber(position) or 0,
            record_id,
            accessxi.escape_probe_log_text(tostring(source or '')),
            accessxi.escape_probe_log_text(label)));
    end
    return ('%s. %s.'):fmt(title, label);
end

