        tostring(label or ''),
        tostring(reason or ''));

    if (now < (tonumber(accessxi.adventuring_primer_detail_probe_next) or 0)) then
        return;
    end
    if ((tonumber(accessxi.adventuring_primer_detail_probe_count) or 0) >= (tonumber(accessxi.adventuring_primer_detail_probe_limit) or 0)) then
        return;
    end
    accessxi.adventuring_primer_detail_probe_next = now + 250;
    accessxi.adventuring_primer_detail_probe_count = (tonumber(accessxi.adventuring_primer_detail_probe_count) or 0) + 1;
    key = key .. (':manual:%d'):fmt(tonumber(accessxi.adventuring_primer_detail_probe_count) or 0);
    accessxi.last_adventuring_primer_detail_probe_key = key;

    accessxi.menu_dump_sequence = (tonumber(accessxi.menu_dump_sequence) or 0) + 1;
    local seq = tonumber(accessxi.menu_dump_sequence) or 0;
    local obj = get_current_menu_object_ptr();
    local selected, page, raw, child, count = accessxi.survival_guide_query_child_state_for_obj(obj);
    local target = safe_call(function () return AshitaCore:GetMemoryManager():GetTarget(); end, nil);
    local ank_num = tonumber(safe_call(function () return target:GetWindowAnkNum(); end, -1)) or -1;
    local shape = 0;
    if (target ~= nil and ank_num >= 0 and ank_num <= 16) then
        shape = tonumber(safe_call(function () return target:GetWindowAnkShape(ank_num); end, 0)) or 0;
    end
    local sub = tonumber(safe_call(function () return target:GetWindowSubPointer(); end, 0)) or 0;
    local sub_x = tonumber(safe_call(function () return target:GetWindowSubX(); end, -1)) or -1;
    local sub_y = tonumber(safe_call(function () return target:GetWindowSubY(); end, -1)) or -1;
    local win = tostring(safe_call(function () return target:GetWindowName(); end, '') or '');
    local resource_name, resource_source = accessxi.adventuring_primer_detail_resource_name();

    log_state(('state adventuring-primer detail-probe seq=%d mode="%s" menu="%s" reason="%s" record=%d label="%s" resource="%s" resourceSource="%s" selected=%d count=%d page=%d raw=0x%08X obj=0x%08X child=0x%08X ank=%d shape=0x%08X sub=0x%08X subXY=(%d,%d) window="%s" objDwords="%s" childDwords="%s" shapeDwords="%s" render="%s"'):fmt(
        seq,
        manual_probe and 'manual' or 'auto',
        tostring(menu_name or ''),
        accessxi.escape_probe_log_text(tostring(reason or '')),
        tonumber(record_id) or 0,
        accessxi.escape_probe_log_text(tostring(label or '')),
        accessxi.escape_probe_log_text(resource_name),
        accessxi.escape_probe_log_text(resource_source),
        tonumber(selected) or 0,
        tonumber(count) or 0,
        tonumber(page) or 0,
        tonumber(raw) or 0,
        tonumber(obj) or 0,
        tonumber(child) or 0,
        ank_num,
        tonumber(shape) or 0,
        tonumber(sub) or 0,
        sub_x,
        sub_y,
        accessxi.escape_probe_log_text(win),
        accessxi.escape_probe_log_text_wide(accessxi.format_probe_dwords(obj, 0x00, 32)),
        accessxi.escape_probe_log_text_wide(accessxi.format_probe_dwords(child, 0x00, 32)),
        accessxi.escape_probe_log_text_wide(accessxi.format_probe_dwords(shape, 0x00, 32)),
        accessxi.escape_probe_log_text_wide(accessxi.adventuring_primer_render_text_probe())));

    if (not manual_probe) then
        return;
    end

    accessxi.menu_dump_textptr_budget = 80;
    accessxi.log_probe_short_text_runs(seq, 'primerdetail.obj', obj, 0x360, 2, 18);
    accessxi.log_probe_pointer_text_targets(seq, 'primerdetail.obj', obj, 0x00, 0x180, 24);
    accessxi.log_probe_short_text_runs(seq, 'primerdetail.child', child, 0x360, 2, 20);
    accessxi.log_probe_pointer_text_targets(seq, 'primerdetail.child', child, 0x00, 0x1C0, 28);
    accessxi.log_probe_short_text_runs(seq, 'primerdetail.shape', shape, 0x360, 2, 20);
    accessxi.log_probe_pointer_text_targets(seq, 'primerdetail.shape', shape, 0x00, 0x180, 28);
    accessxi.menu_dump_textptr_budget = nil;
end

function accessxi.find_adventuring_primer_resource_name_at(ptr, length)
    ptr = tonumber(ptr) or 0;
    length = tonumber(length) or 0;
    local token = 'cntguidecg_';
    local token_len = #token;
    if (not accessxi.is_probe_pointer(ptr) or length < token_len) then
        return '', -1;
    end

    for off = 0, length - token_len do
        local matched = true;
        for i = 1, token_len do
            if ((read_u8(ptr + off + i - 1) or -1) ~= token:byte(i)) then
                matched = false;
                break;
            end
        end

        if (matched) then
            local chars = T{};
            for run_off = off, math.min(length - 1, off + 63) do
                local byte_value = read_u8(ptr + run_off);
                if (byte_value == nil or not accessxi.probe_printable_ascii(byte_value)) then
                    break;
                end
                chars:append(string.char(byte_value));
            end
            local text = chars:concat('');
            local resource = text:match('^(cntguidecg_[A-Za-z0-9_]+)') or '';
            if (resource ~= '') then
                return resource, off;
            end
        end
    end

    return '', -1;
end

function accessxi.adventuring_primer_detail_resource_name()
    local obj = get_current_menu_object_ptr();
    if (not accessxi.is_probe_pointer(obj)) then
        return '', '';
    end

    local direct, direct_off = accessxi.find_adventuring_primer_resource_name_at(obj, 0x220);
    if (direct ~= '') then
        return direct, ('obj+%03X'):fmt(direct_off);
    end

    local seen = {};
    for off = 0x00, 0x80, 4 do
        local target = read_u32(obj + off);
        if (target ~= nil and accessxi.is_probe_pointer(target) and not seen[target]) then
            seen[target] = true;
            local resource, resource_off = accessxi.find_adventuring_primer_resource_name_at(target, 0x300);
            if (resource ~= '') then
                return resource, ('obj+%03X->+%03X'):fmt(off, resource_off);
            end
        end
    end

    return '', '';
end

function accessxi.is_adventuring_primer_texture_surface()
    local resource_name = accessxi.adventuring_primer_detail_resource_name();
    if (tostring(resource_name or ''):sub(1, 11):eq('cntguidecg_', true)) then
        return true;
    end

    local now = tick();
    if (now > (tonumber(accessxi.adventuring_primer_detail_surface_until) or 0)) then
        return false;
    end

    local menu_name = tostring(safe_call(function () return get_menu_name(); end, '') or '');
    if (not menu_name:eq('menu    mapframe', true)) then
        return false;
    end

    local transition_age = (tonumber(accessxi.last_menu_transition_tick) or 0) > 0
        and (now - (tonumber(accessxi.last_menu_transition_tick) or 0))
        or 999999;
    local transition_from = tostring(accessxi.last_menu_transition_from or '');
    local transition_to = tostring(accessxi.last_menu_transition_to or '');
    return transition_from:eq('menu    guide01', true)
        and transition_to:eq('menu    mapframe', true)
        and transition_age >= 0
        and transition_age <= 60000;
end

function accessxi.adventuring_primer_detail_surface_speech(menu_name, previous_menu_name)
    menu_name = tostring(menu_name or '');
    previous_menu_name = tostring(previous_menu_name or '');
    if (not (menu_name:eq('menu    inline', true)
        or menu_name:eq('menu    mapframe', true)
        or menu_name:eq('menu    hfr1', true))) then
        return nil;
    end

    local now = tick();
    if ((tonumber(accessxi.adventuring_primer_detail_probe_until) or 0) >= now) then
        local probe_record_id = tonumber(accessxi.adventuring_primer_detail_candidate_record_id) or 0;
        local probe_label = tostring(accessxi.adventuring_primer_detail_candidate_label or '');
        if (probe_label == '') then
            probe_label = tostring(accessxi.last_native_menu_label or '');
        end
        accessxi.log_adventuring_primer_detail_probe(menu_name, probe_record_id, probe_label, 'manual-surface');
    end

    if ((tonumber(accessxi.adventuring_primer_detail_candidate_until) or 0) < now) then
        return nil;
    end

    local transition_age = (tonumber(accessxi.last_menu_transition_tick) or 0) > 0
        and (now - (tonumber(accessxi.last_menu_transition_tick) or 0))
        or 999999;
    local transition_from = tostring(accessxi.last_menu_transition_from or previous_menu_name);
    local transition_to = tostring(accessxi.last_menu_transition_to or menu_name);
    local transition_ok = transition_from:eq('menu    guide01', true)
        and transition_to:eq(menu_name, true)
        and transition_age >= 0
        and transition_age <= 60000;
    if (not transition_ok) then
        return nil;
    end

    local record_id = tonumber(accessxi.adventuring_primer_detail_candidate_record_id) or 0;
    local label = tostring(accessxi.adventuring_primer_detail_candidate_label or '');
    local description = tostring(accessxi.adventuring_primer_detail_candidate_description or '');
    if (record_id <= 0 or label == '') then
        return nil;
    end
    local resource_name, resource_source = accessxi.adventuring_primer_detail_resource_name();

    local key = ('adventuring-primer-detail:%s:%d:%s:%s'):fmt(menu_name, record_id, label, description);
    accessxi.last_native_menu_name = menu_name;
    accessxi.last_native_menu_label = label;
    accessxi.last_native_menu_selected = record_id;
    accessxi.last_native_menu_tick = now;
    accessxi.adventuring_primer_detail_surface_until = now + 60000;
    accessxi.current_speech_key = key;
    if (key ~= tostring(accessxi.last_adventuring_primer_detail_key or '')) then
        accessxi.last_adventuring_primer_detail_key = key;
        log_state(('state adventuring-primer detail menu="%s" transitionFrom="%s" transitionAge=%d record=%d label="%s" text="%s" source="%s" resource="%s" resourceSource="%s"'):fmt(
            menu_name,
            accessxi.escape_probe_log_text(transition_from),
            transition_age,
            record_id,
            accessxi.escape_probe_log_text(label),
            accessxi.escape_probe_log_text(description),
            accessxi.escape_probe_log_text(tostring(accessxi.adventuring_primer_detail_candidate_source or '')),
            accessxi.escape_probe_log_text(resource_name),
            accessxi.escape_probe_log_text(resource_source)));
    end
    accessxi.log_adventuring_primer_detail_probe(menu_name, record_id, label, 'detail-surface');

    local parts = T{ 'Adventuring Primer', label };
    if (description ~= '') then
        parts:append(description);
    end
    return accessxi.sentence_fragment(parts:concat('. '));
end

function accessxi.friend_list_menu_speech(menu_name, title, selected, count, page, raw, child, entry)
    if (not tostring(menu_name or ''):eq('menu    flistmai', true)) then
        return nil;
    end

    selected = math.floor(tonumber(selected) or 0);
    local rows = accessxi.native_menus_data.friend_list_rows or T{};
    local row = rows[selected];
    if (row == nil) then
        log_state(('state friend-list native-missing-resource menu="%s" title="%s" select=%d count=%d page=%d raw=0x%08X child=0x%08X entry=0x%08X'):fmt(
            tostring(menu_name or ''),
            accessxi.escape_probe_log_text(tostring(title or '')),
            selected,
            tonumber(count) or 0,
            tonumber(page) or 0,
            tonumber(raw) or 0,
            tonumber(child) or 0,
            tonumber(entry) or 0));
        return nil;
    end

    local label = accessxi.plain_native_menu_label(row.label or '');
    local help_text = accessxi.plain_native_menu_help(row.help or '');
    if (label == '') then
        log_state(('state friend-list native-empty-resource menu="%s" title="%s" select=%d labelSource="%s" helpSource="%s"'):fmt(
            tostring(menu_name or ''),
            accessxi.escape_probe_log_text(tostring(title or '')),
            selected,
            accessxi.escape_probe_log_text(tostring(row.label_source or '')),
            accessxi.escape_probe_log_text(tostring(row.help_source or ''))));
        return nil;
    end

    accessxi.last_native_menu_name = menu_name;
    accessxi.last_native_menu_label = label;
    accessxi.last_native_menu_selected = selected;
    accessxi.last_native_menu_tick = tick();
    accessxi.current_speech_key = ('native-known-friend-list-resource:%d:%s:%s'):fmt(
        selected,
        label,
        help_text);
    log_state(('state friend-list resource menu="%s" title="%s" select=%d count=%d page=%d label="%s" help="%s" labelSource="%s" helpSource="%s"'):fmt(
        tostring(menu_name or ''),
        accessxi.escape_probe_log_text(tostring(title or '')),
        selected,
        tonumber(count) or 0,
        tonumber(page) or 0,
        accessxi.escape_probe_log_text(label),
        accessxi.escape_probe_log_text(help_text),
        accessxi.escape_probe_log_text(tostring(row.label_source or '')),
        accessxi.escape_probe_log_text(tostring(row.help_source or ''))));
    if (help_text ~= '') then
        return ('%s. %s %s'):fmt(title, accessxi.sentence_fragment(label), accessxi.sentence_fragment(help_text));
    end
    return ('%s. %s'):fmt(title, accessxi.sentence_fragment(label));
end

function accessxi.friend_list_dynamic_candidate_ok(text)
    text = accessxi.survival_guide_text(text or ''):gsub('%s+', ' '):trim();
    if (text == '' or #text < 3 or #text > 48 or text:match('%a') == nil) then
        return false;
    end
    if (text:match("^[%w%s%-%_'%.]+$") == nil) then
        return false;
    end

    local lower = text:lower();
    if (lower:eq('hx3', true)
        or lower:eq('h=6', true)
        or lower:eq('p:6', true)
        or lower:eq('x<6', true)
        or lower:eq('0m!', true)
        or lower:eq('0m', true)
        or lower:eq('p}', true)
        or lower:contains('menu    ', true)
        or lower:contains('windowps', true)
        or lower:contains('framesus', true)
        or lower:contains('moogle', true)
        or lower:contains('locker', true)
        or lower:contains('lease', true)) then
        return false;
    end

    return true;
end

function accessxi.friend_list_dynamic_candidate_records(ptr, length, limit, source)
    ptr = tonumber(ptr) or 0;
    length = tonumber(length) or 0x180;
    limit = tonumber(limit) or 12;
    source = tostring(source or '');
    if (not accessxi.is_probe_pointer(ptr)) then
        return T{};
    end

    local out = T{};
    local seen = {};
    local function add(kind, offset, text)
        text = accessxi.survival_guide_text(text or ''):gsub('%s+', ' '):trim();
        if (not accessxi.friend_list_dynamic_candidate_ok(text)) then
            return;
        end
        local key = text:lower();
        if (seen[key] == true) then
            return;
        end
        seen[key] = true;
        out:append(T{
            source = source,
            kind = tostring(kind or ''),
            offset = tonumber(offset) or 0,
            text = text,
        });
    end

    for _, off in ipairs(T{ 0x00, 0x04, 0x08, 0x0C, 0x10, 0x14, 0x18, 0x20, 0x24, 0x28, 0x30, 0x3D, 0x40, 0x46, 0x50, 0x58, 0x5C, 0x60, 0x80, 0xA0, 0xC0, 0x100, 0x128, 0x12C, 0x168 }) do
        if (off < length) then
            add('str', off, read_probe_string(ptr + off, math.min(96, length - off)));
        end
        if (#out >= limit) then
            return out;
        end
    end

    if (accessxi.collect_probe_ascii_runs ~= nil) then
        for _, run in ipairs(accessxi.collect_probe_ascii_runs(ptr, length, 3, limit)) do
            local off_text, text = tostring(run or ''):match('^%+(%x+)="(.*)"$');
            add('ascii', tonumber(off_text or '0', 16) or 0, text or tostring(run or ''));
            if (#out >= limit) then
                return out;
            end
        end
    end

    if (accessxi.collect_probe_utf16_runs ~= nil) then
        for _, run in ipairs(accessxi.collect_probe_utf16_runs(ptr, length, 3, limit)) do
            local off_text, text = tostring(run or ''):match('^%+(%x+)="(.*)"$');
            add('utf16', tonumber(off_text or '0', 16) or 0, text or tostring(run or ''));
            if (#out >= limit) then
                return out;
            end
        end
    end

    if (accessxi.collect_probe_ffxi_utf16_entries ~= nil) then
        for _, entry in ipairs(accessxi.collect_probe_ffxi_utf16_entries(ptr, length, 3, limit)) do
            add('ffxi16', tonumber(entry.offset) or 0, entry.text or '');
            if (#out >= limit) then
                return out;
            end
        end
    end

    return out;
end

function accessxi.friend_list_dynamic_candidate_summary(candidates)
    local parts = T{};
    for _, item in ipairs(candidates or T{}) do
        local text = tostring(item.text or '');
        parts:append(('%s:%s+%03X len=%d text="%s"'):fmt(
            tostring(item.source or ''),
            tostring(item.kind or ''),
            tonumber(item.offset) or 0,
            #text,
            accessxi.escape_probe_log_text(text)));
    end
    return parts:concat(' | ');
end

function accessxi.friend_list_memscan_source_for_context(context)
    local lower = tostring(context or ''):lower();
    if (lower:find('friendmem ', 1, true) ~= nil
        or lower:find('friend-list ', 1, true) ~= nil
        or lower:find('friendraw ', 1, true) ~= nil
        or lower:find('menudump ', 1, true) ~= nil
        or lower:find('ffxi-menu-reader', 1, true) ~= nil
        or lower:find('accessxi_reader', 1, true) ~= nil
        or lower:find('c:\\users\\', 1, true) ~= nil
        or lower:find('addons\\', 1, true) ~= nil
        or lower:find('.lua', 1, true)) then
        return 'diagnostic-noise';
    end
    return 'candidate';
end

function accessxi.friend_list_memscan_add_term(terms, seen, term)
    term = accessxi.survival_guide_text(term or '');
    if (#term < 3) then
        return;
    end
    local key = term:lower();
    if (seen[key] == true) then
        return;
    end
    seen[key] = true;
    terms:append(term);
end

function accessxi.friend_list_memscan_terms(text)
    local terms = T{};
    local seen = {};
    text = tostring(text or ''):gsub(',', '|'):gsub(';', '|');
    for term in text:gmatch('[^|]+') do
        term = accessxi.survival_guide_text(term);
        if (term ~= '') then
            accessxi.friend_list_memscan_add_term(terms, seen, term);
            local bare = term:gsub('^%(', ''):gsub('%)$', ''):trim();
            accessxi.friend_list_memscan_add_term(terms, seen, bare);
            if (bare ~= '' and bare == term and term:sub(1, 1) ~= '<') then
                accessxi.friend_list_memscan_add_term(terms, seen, ('(%s)'):fmt(term));
            end
        end
    end
    return terms;
end

function accessxi.log_friend_list_memory_scan(reason, text)
    accessxi.menu_dump_sequence = (accessxi.menu_dump_sequence or 0) + 1;
    local seq = accessxi.menu_dump_sequence;
    local terms = accessxi.friend_list_memscan_terms(text);
    if (terms:len() == 0) then
        log_line(('friendmem seq=%d reason="%s" skipped no terms'):fmt(
            seq,
            accessxi.escape_probe_log_text(tostring(reason or ''))));
        return 0;
    end

    local patterns = T{};
    for _, term in ipairs(terms) do
        patterns:append(T{ term = term, enc = 'ascii', bytes = term });
        patterns:append(T{ term = term, enc = 'utf16le', bytes = accessxi.utf16le_pattern(term) });
    end

    local mbi = ffi.new('MEMORY_BASIC_INFORMATION[1]');
    local mbi_size = ffi.sizeof('MEMORY_BASIC_INFORMATION');
    local addr = 0x10000;
    local stop_addr = 0x7FFF0000;
    local max_ms = 650;
    local max_bytes = 72 * 1024 * 1024;
    local max_regions = 2048;
    local max_hits = 64;
    local chunk_size = 192 * 1024;
    local process = kernel32.GetCurrentProcess();
    local buffer = ffi.new('char[?]', chunk_size);
    local bytes_read = ffi.new('SIZE_T[1]');
    local started = tick();
    local scanned_bytes = 0;
    local regions = 0;
    local readable_regions = 0;
    local hits = 0;
    local timed_out = false;
    local hit_keys = {};

    log_line(('friendmem begin seq=%d reason="%s" terms="%s"'):fmt(
        seq,
        accessxi.escape_probe_log_text(tostring(reason or '')),
        accessxi.escape_probe_log_text(terms:concat('|'))));

    while (addr < stop_addr and regions < max_regions and scanned_bytes < max_bytes and hits < max_hits) do
        if ((tick() - started) > max_ms) then
            timed_out = true;
            break;
        end

        local ok, result = pcall(function ()
            return kernel32.VirtualQuery(ffi.cast('const void*', addr), mbi, mbi_size);
        end);
        local queried = ok and tonumber(result) or 0;
        if (queried == 0) then
            addr = addr + 0x10000;
        else
            local base = tonumber(ffi.cast('uintptr_t', mbi[0].BaseAddress)) or addr;
            local size = tonumber(mbi[0].RegionSize) or 0;
            local state = tonumber(mbi[0].State) or 0;
            local protect = tonumber(mbi[0].Protect) or 0;
            local mem_type = tonumber(mbi[0].Type) or 0;
            local next_addr = base + math.max(size, 0x1000);
            regions = regions + 1;

            if (size > 0 and state == 0x1000 and accessxi.memory_page_search_scan_allowed(base, protect)) then
                readable_regions = readable_regions + 1;
                local region_offset = 0;
                while (region_offset < size and scanned_bytes < max_bytes and hits < max_hits) do
                    if ((tick() - started) > max_ms) then
                        timed_out = true;
                        break;
                    end

                    local want = math.min(chunk_size, size - region_offset, max_bytes - scanned_bytes);
                    local chunk_addr = base + region_offset;
                    bytes_read[0] = 0;
                    local read_ok = kernel32.ReadProcessMemory(process, ffi.cast('const void*', chunk_addr), buffer, want, bytes_read) ~= 0;
                    local got = tonumber(bytes_read[0]) or 0;

                    if (read_ok and got > 0) then
                        local blob = ffi.string(buffer, got);
                        scanned_bytes = scanned_bytes + got;
                        for _, pattern in ipairs(patterns) do
                            local start_at = 1;
                            local term_hits = 0;
                            while (term_hits < 5 and hits < max_hits) do
                                local found = blob:find(pattern.bytes, start_at, true);
                                if (found == nil) then
                                    break;
                                end

                                local absolute = chunk_addr + found - 1;
                                local key = ('%s:%s:%08X'):fmt(pattern.enc, pattern.term, absolute);
                                if (hit_keys[key] ~= true) then
                                    hit_keys[key] = true;
                                    local context_start = math.max(1, found - 64);
                                    local context_end = math.min(#blob, found + #pattern.bytes + 96);
                                    local context_blob = blob:sub(context_start, context_end);
                                    local context = accessxi.scan_context_text(context_blob);
                                    local source = accessxi.friend_list_memscan_source_for_context(context);
                                    local nearby_start = math.max(1, found - 256);
                                    local nearby_end = math.min(#blob, found + #pattern.bytes + 256);
                                    local strings = accessxi.ascii_runs_from_blob(blob:sub(nearby_start, nearby_end), 18):concat('|');
                                    hits = hits + 1;
                                    term_hits = term_hits + 1;
                                    log_line(('friendmem hit seq=%d term="%s" enc=%s addr=0x%08X region=0x%08X protect=0x%X type=0x%X source=%s ctx="%s" strings="%s" hex="%s"'):fmt(
                                        seq,
                                        accessxi.escape_probe_log_text(pattern.term),
                                        pattern.enc,
                                        absolute,
                                        base,
                                        protect,
                                        mem_type,
                                        source,
                                        accessxi.escape_probe_log_text(context),
                                        accessxi.escape_probe_log_text(strings),
                                        accessxi.packet_hex_limit(context_blob, 96)));
                                end

                                start_at = found + 1;
                            end
                        end
                    else
                        scanned_bytes = scanned_bytes + want;
                    end

                    region_offset = region_offset + want;
                end
            end

            if (next_addr <= addr) then
                addr = addr + 0x1000;
            else
                addr = next_addr;
            end
        end
    end

    log_line(('friendmem end seq=%d hits=%d terms=%d regions=%d readable=%d scanned=%d timedOut=%s elapsed=%d'):fmt(
        seq,
        hits,
        terms:len(),
        regions,
        readable_regions,
        scanned_bytes,
        tostring(timed_out),
        tick() - started));
    return hits;
end

function accessxi.friend_list_cell_candidate_probe(entry, selected)
    entry = tonumber(entry) or 0;
    selected = tonumber(selected) or 0;
    if (not accessxi.is_probe_pointer(entry) or selected <= 0) then
        return '', T{};
    end

    local parent = read_u32(entry + 0x5C) or 0;
    local seen = {};
    local records = T{};
    local function add_cell(cell, delta)
        cell = tonumber(cell) or 0;
        if (not accessxi.is_probe_pointer(cell) or seen[cell] == true) then
            return;
        end
        seen[cell] = true;
        if ((read_u32(cell + 0x58) or 0) ~= cell) then
            return;
        end
        if (accessxi.is_probe_pointer(parent) and (read_u32(cell + 0x5C) or 0) ~= parent) then
            return;
        end

        local row_code = read_u32(cell + 0x38) or 0;
        local row_index = math.floor(row_code / 0x10000);
        local order = row_code % 0x10000;
        local candidates = accessxi.friend_list_dynamic_candidate_records(cell, 0x68, 8, ('cell%+d'):fmt(tonumber(delta) or 0));
        for _, item in ipairs(candidates) do
            if (#tostring(item.text or '') >= 4) then
                item.cell = cell;
                item.row = row_index;
                item.order = order;
                item.match = (row_index == selected);
                records:append(item);
            end
        end
    end

    add_cell(entry, 0);
    for delta = -18, 18 do
        if (delta ~= 0) then
            add_cell(entry + (delta * 0x68), delta);
        end
    end

    table.sort(records, function (a, b)
        if ((tonumber(a.row) or 0) == (tonumber(b.row) or 0)) then
            if ((tonumber(a.order) or 0) == (tonumber(b.order) or 0)) then
                return (tonumber(a.offset) or 0) < (tonumber(b.offset) or 0);
            end
            return (tonumber(a.order) or 0) < (tonumber(b.order) or 0);
        end
        return (tonumber(a.row) or 0) < (tonumber(b.row) or 0);
    end);

    local parts = T{};
    for _, item in ipairs(records) do
        local text = tostring(item.text or '');
        parts:append(('row=%d order=0x%04X match=%s cell=0x%08X %s:%s+%03X len=%d text="%s"'):fmt(
            tonumber(item.row) or 0,
            tonumber(item.order) or 0,
            tostring(item.match == true),
            tonumber(item.cell) or 0,
            tostring(item.source or ''),
            tostring(item.kind or ''),
            tonumber(item.offset) or 0,
            #text,
            accessxi.escape_probe_log_text(text)));
        if (#parts >= 18) then
            break;
        end
    end

    return parts:concat(' | '), records;
end

function accessxi.friend_list_any_probe_active()
    local now = tick();
    return ((tonumber(accessxi.friend_list_dynamic_probe_until) or 0) >= now
        or (tonumber(accessxi.friend_list_raw_probe_until) or 0) >= now
        or (tonumber(accessxi.friend_list_table_probe_until) or 0) >= now
        or (tonumber(accessxi.friend_list_name_buffer_probe_until) or 0) >= now
        or (tonumber(accessxi.friend_list_glyph_probe_until) or 0) >= now);
end

function accessxi.friend_list_dynamic_selected_label(menu_name, selected, count, child, entry)
    selected = tonumber(selected) or 0;
    count = tonumber(count) or 0;

    local query_label = '';
    local query_mode = 'not-run';
    if (accessxi.is_probe_pointer(child) and selected > 0 and count > 0 and accessxi.native_query_label_for_selection ~= nil) then
        query_label, query_mode = accessxi.native_query_label_for_selection(child, selected, count, 'plain');
        query_label = accessxi.plain_native_menu_label(query_label or '');
        if (accessxi.friend_list_any_probe_active()) then
            local query_key = ('%s:%d:%d:%s:%s'):fmt(
                tostring(menu_name or ''),
                selected,
                count,
                tostring(query_mode or ''),
                query_label);
            if (query_key ~= tostring(accessxi.last_friend_list_native_query_key or '')) then
                accessxi.last_friend_list_native_query_key = query_key;
                log_state(('state friend-list native-query menu="%s" select=%d count=%d child=0x%08X label="%s" mode="%s"'):fmt(
                    tostring(menu_name or ''),
                    selected,
                    count,
                    tonumber(child) or 0,
                    accessxi.escape_probe_log_text(query_label),
                    accessxi.escape_probe_log_text(tostring(query_mode or ''))));
            end
        end
        if (query_label ~= '') then
            return query_label, ('native-query:%s'):fmt(tostring(query_mode or ''));
        end
    end

    local packet_label, packet_source = accessxi.friend_list_packet_selected_label(menu_name, selected, count);
    if (packet_label ~= '') then
        return packet_label, packet_source;
    end

    if (not accessxi.friend_list_any_probe_active()) then
        return '', 'native-query-missing';
    end

    local candidates = T{};
    local function collect(ptr, source, length)
        for _, item in ipairs(accessxi.friend_list_dynamic_candidate_records(ptr, length or 0x180, 12, source)) do
            candidates:append(item);
        end
    end

    collect(entry, 'entry', 0x68);
    if (accessxi.is_probe_pointer(child) and selected > 0) then
        for _, base in ipairs(T{ 0x60, 0x70, 0x80, 0x90, 0xA0, 0xA8, 0xB0, 0xC0 }) do
            local ptr = read_u32(child + base + ((selected - 1) * 4)) or 0;
            collect(ptr, ('child+%03X[%02d]'):fmt(base, selected - 1), 0x300);
        end
    end

    local key = ('%s:%d:%s'):fmt(tostring(menu_name or ''), selected, accessxi.friend_list_dynamic_candidate_summary(candidates));
    if (key ~= tostring(accessxi.last_friend_list_dynamic_candidate_key or '')) then
        accessxi.last_friend_list_dynamic_candidate_key = key;
        log_state(('state friend-list dynamic-candidates menu="%s" select=%d child=0x%08X entry=0x%08X candidates="%s"'):fmt(
            tostring(menu_name or ''),
            selected,
            tonumber(child) or 0,
            tonumber(entry) or 0,
            accessxi.escape_probe_log_text_wide(accessxi.friend_list_dynamic_candidate_summary(candidates))));
    end

    local unique = T{};
    local seen = {};
    for _, item in ipairs(candidates) do
        local text = tostring(item.text or '');
        local key_text = text:lower();
        if (text ~= '' and seen[key_text] ~= true) then
            seen[key_text] = true;
            unique:append(item);
        end
    end

    local cell_summary, cell_records = accessxi.friend_list_cell_candidate_probe(entry, selected);
    local cell_key = ('%s:%d:%s'):fmt(tostring(menu_name or ''), selected, cell_summary);
    if (cell_key ~= tostring(accessxi.last_friend_list_cell_candidate_key or '')) then
        accessxi.last_friend_list_cell_candidate_key = cell_key;
        log_state(('state friend-list cell-candidates menu="%s" select=%d entry=0x%08X candidates="%s"'):fmt(
            tostring(menu_name or ''),
            selected,
            tonumber(entry) or 0,
            accessxi.escape_probe_log_text_wide(cell_summary)));
    end

    local matched = T{};
    local matched_seen = {};
    for _, item in ipairs(cell_records or T{}) do
        local text = tostring(item.text or '');
        local key_text = text:lower();
        if (item.match == true and text ~= '' and matched_seen[key_text] ~= true) then
            matched_seen[key_text] = true;
            matched:append(item);
        end
    end

    if (#matched >= 1) then
        local label_parts = T{};
        local source_parts = T{};
        for _, item in ipairs(matched) do
            local text = tostring(item.text or '');
            if (text ~= '') then
                label_parts:append(text);
                source_parts:append(('%s:%s+%03X'):fmt(tostring(item.source or ''), tostring(item.kind or ''), tonumber(item.offset) or 0));
            end
        end
        if (#label_parts > 0) then
            local refused_key = ('%s:%d:%s'):fmt(tostring(menu_name or ''), selected, source_parts:concat(','));
            if (refused_key ~= tostring(accessxi.last_friend_list_cell_refused_key or '')) then
                accessxi.last_friend_list_cell_refused_key = refused_key;
                log_state(('state friend-list cell-row-refused menu="%s" select=%d count=%d source="%s" reason="diagnostic-only"'):fmt(
                    tostring(menu_name or ''),
                    selected,
                    count,
                    accessxi.escape_probe_log_text(source_parts:concat(','))));
            end
        end
    end
    return '', 'native-query-missing';
end

function accessxi.friend_list_dynamic_menu_speech(menu_name, title, obj, selected, count, page, raw, child, entry)
    if (not tostring(menu_name or ''):eq('menu    friend', true)) then
        return nil;
    end

    local label, source = accessxi.friend_list_dynamic_selected_label(menu_name, selected, count, child, entry);
    if (label == '') then
        return nil;
    end

    accessxi.last_native_menu_name = menu_name;
    accessxi.last_native_menu_label = label;
    accessxi.last_native_menu_selected = selected;
    accessxi.last_native_menu_tick = tick();
    accessxi.current_speech_key = ('native-known-friend-list-dynamic:%d:%s:%s'):fmt(
        tonumber(selected) or 0,
        label,
        tostring(source or ''));
    log_state(('state friend-list dynamic-speech menu="%s" title="%s" select=%d count=%d page=%d label="%s" source="%s"'):fmt(
        tostring(menu_name or ''),
        accessxi.escape_probe_log_text(tostring(title or '')),
        tonumber(selected) or 0,
        tonumber(count) or 0,
        tonumber(page) or 0,
        accessxi.escape_probe_log_text(label),
        accessxi.escape_probe_log_text(tostring(source or ''))));
    return ('%s. %s'):fmt(title, accessxi.sentence_fragment(label));
end

function accessxi.friend_list_dynamic_shape_probe(target, ank_num)
    local parts = T{};
    target = target or AshitaCore:GetMemoryManager():GetTarget();
    ank_num = tonumber(ank_num) or -1;
    if (target == nil or ank_num < 0 or ank_num > 16) then
        return '';
    end

    for i = 0, math.min(ank_num, 8) do
        local shape = tonumber(safe_call(function () return target:GetWindowAnkShape(i); end, 0)) or 0;
        if (accessxi.is_probe_pointer(shape)) then
            parts:append(('%d:0x%08X d="%s" strings="%s" runs="%s" ptrs="%s"'):fmt(
                i,
                shape,
                accessxi.escape_probe_log_text(accessxi.format_probe_dwords(shape, 0x00, 10)),
                accessxi.escape_probe_log_text(accessxi.status_menu_probe_inline_strings(shape)),
                accessxi.escape_probe_log_text(accessxi.status_menu_probe_runs(shape, 0x100)),
                accessxi.escape_probe_log_text(accessxi.status_menu_probe_pointer_fields(shape))));
        end
    end

    return parts:concat(' || ');
end

function accessxi.dat_index_row_text(dat_path, row, text_kind)
    dat_path = tostring(dat_path or '');
    row = tonumber(row) or -1;
    if (dat_path == '' or row < 0) then
        return '';
    end

    accessxi.dat_index_row_text_cache = accessxi.dat_index_row_text_cache or {};
    local key = ('%s:%d'):fmt(dat_path, row);
    local cached = accessxi.dat_index_row_text_cache[key];
    if (cached ~= nil) then
        return cached;
    end

    local text = '';
    local path = accessxi.dat_index_path();
    local f = io.open(path, 'rb');
    if (f ~= nil) then
        for line in f:lines() do
            local _, _, line_dat_path, index, value = line:match('^(%d+)\t([^\t]+)\t([^\t]+)\t(%d+)\t(.*)$');
            if (line_dat_path == dat_path and (tonumber(index) or -1) == row) then
                if (text_kind == 'prompt') then
                    text = accessxi.plain_native_menu_prompt(accessxi.survival_guide_text(tostring(value or ''):gsub('\r', '')));
                elseif (text_kind == 'help') then
                    text = accessxi.plain_native_menu_help(accessxi.survival_guide_text(tostring(value or ''):gsub('\r', '')));
                else
                    text = accessxi.plain_native_menu_label(accessxi.survival_guide_text(tostring(value or ''):gsub('\r', '')));
                end
                break;
            end
        end
        f:close();
    end

    accessxi.dat_index_row_text_cache[key] = text;
    return text;
end

function accessxi.playermo_entity_state_from_index(entity, index, source)
    index = tonumber(index) or -1;
    if (entity == nil or index < 0) then
        return nil;
    end

    local name = clean_probe_text(safe_call(function () return entity:GetName(index); end, ''));
    local server_id = tonumber(safe_call(function () return entity:GetServerId(index); end, 0)) or 0;
    if (name == '' and server_id == 0) then
        return nil;
    end

    return T{
        index = index,
        source = tostring(source or ''),
        name = name,
        server_id = server_id,
        type = tonumber(safe_call(function () return entity:GetType(index); end, -1)) or -1,
        hp = tonumber(safe_call(function () return entity:GetHPPercent(index); end, -1)) or -1,
        status = tonumber(safe_call(function () return entity:GetStatus(index); end, -1)) or -1,
        claim = tonumber(safe_call(function () return entity:GetClaimStatus(index); end, -1)) or -1,
        spawn_flags = tonumber(safe_call(function () return entity:GetSpawnFlags(index); end, 0)) or 0,
        name_color = tonumber(safe_call(function () return entity:GetNameColor(index); end, 0)) or 0,
    };
end

function accessxi.playermo_target_state_context(target, menu_title)
    target = target or safe_call(function () return AshitaCore:GetMemoryManager():GetTarget(); end, nil);
    local ctx = T{
        kind = 'unknown',
        source = 'none',
        index = -1,
        name = '',
        server_id = 0,
        type = -1,
        hp = -1,
        status = -1,
        claim = -1,
        spawn_flags = 0,
        name_color = 0,
        focus_index = -1,
        focus_server = 0,
        window_server = 0,
        window_loaded = 0,
        window_hp = -1,
        window_death = -1,
        window_name = '',
        player_name = accessxi.current_player_name(),
    };
    if (target == nil) then
        ctx.source = 'target=nil';
        return ctx;
    end

    ctx.focus_index = tonumber(safe_call(function () return target:GetFocusTargetIndex(); end, -1)) or -1;
    ctx.focus_server = tonumber(safe_call(function () return target:GetFocusTargetServerId(); end, 0)) or 0;
    ctx.window_server = tonumber(safe_call(function () return target:GetWindowServerId(); end, 0)) or 0;
    ctx.window_loaded = tonumber(safe_call(function () return target:GetWindowIsWindowLoaded(); end, 0)) or 0;
    ctx.window_hp = tonumber(safe_call(function () return target:GetWindowHPPercent(); end, -1)) or -1;
    ctx.window_death = tonumber(safe_call(function () return target:GetWindowDeathFlag(); end, -1)) or -1;
    ctx.window_name = clean_probe_text(safe_call(function () return target:GetWindowName(); end, ''));

    local entity = safe_call(function () return AshitaCore:GetMemoryManager():GetEntity(); end, nil);
    local state = nil;
    for slot = 0, 7 do
        local active = tonumber(safe_call(function () return target:GetIsActive(slot); end, 0)) or 0;
        local arrow = tonumber(safe_call(function () return target:GetIsArrowActive(slot); end, 0)) or 0;
        local target_index = tonumber(safe_call(function () return target:GetTargetIndex(slot); end, -1)) or -1;
        if ((active ~= 0 or arrow ~= 0) and target_index >= 0) then
            state = accessxi.playermo_entity_state_from_index(entity, target_index, ('slot%d'):fmt(slot));
            if (state ~= nil) then
                break;
            end
        end
    end
    if (state == nil and ctx.focus_index >= 0) then
        state = accessxi.playermo_entity_state_from_index(entity, ctx.focus_index, 'focus');
    end

    if (state ~= nil) then
        for key, value in pairs(state) do
            ctx[key] = value;
        end
    end

    local title = clean_probe_text(menu_title or '');
    if (ctx.player_name ~= '' and (title:eq(ctx.player_name, true) or ctx.name:eq(ctx.player_name, true))) then
        ctx.kind = 'self';
        return ctx;
    end

    local flags = tonumber(ctx.spawn_flags) or 0;
    local entity_type = tonumber(ctx.type) or -1;
    if (entity_type == 0 or bit.band(flags, 0x0001) == 0x0001) then
        ctx.kind = 'player';
        return ctx;
    end
    if (entity_type == 1 or bit.band(flags, 0x0002) == 0x0002 or bit.band(flags, 0x1000) ~= 0) then
        ctx.kind = 'npc';
        return ctx;
    end
    if (entity_type == 2 or bit.band(flags, 0x0010) ~= 0) then
        ctx.kind = 'enemy';
        return ctx;
    end
    if (state ~= nil and (tonumber(ctx.hp) or -1) > 0) then
        ctx.kind = 'enemy';
        return ctx;
    end

    return ctx;
end

function accessxi.playermo_native_help_entry(target, menu_title)
    if (target == nil) then
        return nil, 'target=nil';
    end

    local title_ptr = tonumber(safe_call(function () return target:GetWindowHelpTitle(); end, 0)) or 0;
    local help_ptr = tonumber(safe_call(function () return target:GetWindowHelpString(); end, 0)) or 0;
    local raw_title = read_probe_string(title_ptr, 160);
    local raw_help = read_probe_string(help_ptr, 260);
    local label = accessxi.plain_native_menu_label(raw_title);
    local help = accessxi.plain_native_menu_help(raw_help);
    local window_name = accessxi.plain_native_menu_label(safe_call(function () return target:GetWindowName(); end, '') or '');
    local menu_label = accessxi.plain_native_menu_label(menu_title or '');

    if (label ~= '' and ((menu_label ~= '' and label:eq(menu_label, true)) or (window_name ~= '' and label:eq(window_name, true)))) then
        return nil, 'title-is-target', title_ptr, help_ptr, raw_title, raw_help;
    end
    if (label == '') then
        return nil, 'empty-label', title_ptr, help_ptr, raw_title, raw_help;
    end

    return T{
        label = label,
        help = help,
        title_ptr = title_ptr,
        help_ptr = help_ptr,
        raw_title = raw_title,
        raw_help = raw_help,
    }, 'ok';
end

function accessxi.playermo_label_looks_safe(label)
    label = accessxi.plain_native_menu_label(label or '');
    if (label == '') then
        return false;
    end
    if (label:match('^,%a,%a$') ~= nil) then
        return false;
    end

    local lower_label = label:lower():gsub('%s+', ' ');
    if (lower_label:match('^menu%s') ~= nil or lower_label:find(' menu', 1, true) ~= nil) then
        return false;
    end
    if (lower_label:find('font', 1, true) ~= nil or lower_label:find('fon', 1, true) ~= nil) then
        return false;
    end

    return true;
end

function accessxi.playermo_compact_probe_text(text, limit)
    text = clean_probe_text(text or '');
    text = text:gsub('"', "'");
    limit = tonumber(limit) or 96;
    if (#text > limit) then
        text = text:sub(1, limit) .. '...';
    end
    return text;
end

function accessxi.playermo_command_pointer_field_probe(command_ptr, field_offset)
    command_ptr = tonumber(command_ptr) or 0;
    field_offset = tonumber(field_offset) or 0;
    if (not accessxi.is_probe_pointer(command_ptr)) then
        return '';
    end

    local ptr = read_u32(command_ptr + field_offset) or 0;
    if (not accessxi.is_probe_pointer(ptr)) then
        return ('+%02X=0x%08X'):fmt(field_offset, ptr);
    end

    return ('+%02X=0x%08X d="%s" runs="%s" inline="%s" ptrs="%s"'):fmt(
        field_offset,
        ptr,
        accessxi.playermo_compact_probe_text(accessxi.format_probe_dwords(ptr, 0x00, 12), 120),
        accessxi.playermo_compact_probe_text(accessxi.status_menu_probe_runs(ptr, 0xC0), 120),
        accessxi.playermo_compact_probe_text(accessxi.status_menu_probe_inline_strings(ptr), 120),
        accessxi.playermo_compact_probe_text(accessxi.status_menu_probe_pointer_fields(ptr), 160));
end

function accessxi.playermo_command_pointer_probe(command_ptr)
    command_ptr = tonumber(command_ptr) or 0;
    if (not accessxi.is_probe_pointer(command_ptr)) then
        return '';
    end

    local parts = T{};
    local seen = {};
    for off = 0, 0x10, 4 do
        local ptr = read_u32(command_ptr + off) or 0;
        if (accessxi.is_probe_pointer(ptr) and seen[ptr] ~= true) then
            seen[ptr] = true;
            parts:append(accessxi.playermo_command_pointer_field_probe(command_ptr, off));
        end
    end
    return parts:concat(' || ');
end

function accessxi.playermo_probe_words(ptr)
    ptr = tonumber(ptr) or 0;
    if (not accessxi.is_probe_pointer(ptr)) then
        return '';
    end

    local interesting = {
        [0x10] = true,
        [0x1C] = true,
        [0x20] = true,
        [0x24] = true,
        [0x28] = true,
        [0x2C] = true,
        [0x4C] = true,
        [0x58] = true,
    };
    local parts = T{};
    for off = 0, 0x100, 2 do
        local value = read_u16(ptr + off);
        if (value ~= nil and (interesting[off] == true or (value > 0 and value <= 0x80))) then
            parts:append(('+%03X=%d/0x%04X'):fmt(off, value, value));
            if (parts:len() >= 48) then
                break;
            end
        end
    end
    return parts:concat(' ');
end

function accessxi.playermo_dynamic_command_id(child, selected, visible_count)
    child = tonumber(child) or 0;
    selected = tonumber(selected) or 0;
    visible_count = tonumber(visible_count) or 0;

    if (not accessxi.is_probe_pointer(child)) then
        return 0, 'missing-child';
    end
    if (selected < 1 or visible_count < 1 or selected > visible_count or visible_count > 16) then
        return 0, 'invalid-selection';
    end

    local command_id = read_u16(child + 0x1A + (selected * 2)) or 0;
    if (command_id <= 0 or command_id > 0x80) then
        return 0, 'invalid-command-id';
    end

    return command_id, 'child-command-word';
end

function accessxi.load_auto_translates_resource()
    if (accessxi.auto_translates_resource ~= nil) then
        return accessxi.auto_translates_resource;
    end
    if (accessxi.auto_translates_resource_load_tried == true) then
        return nil;
    end
    accessxi.auto_translates_resource_load_tried = true;

    local paths = T{
        accessxi.resource_path('windower', 'auto_translates.lua'),
    };
    for _, path in ipairs(paths) do
        local f = io.open(path, 'rb');
        if (f ~= nil) then
            f:close();
            local ok, data = pcall(function ()
                return loadfile(path)();
            end);
            if (ok and type(data) == 'table') then
                accessxi.auto_translates_resource = data;
                accessxi.auto_translates_resource_path = path;
                log_line(('loaded auto-translate resource path="%s"'):fmt(path));
                return accessxi.auto_translates_resource;
            end
            log_line(('auto-translate resource load failed path="%s" err="%s"'):fmt(path, tostring(data)));
        end
    end

    log_line('auto-translate resource unavailable');
    return nil;
end

function accessxi.auto_translate_label(id)
    id = tonumber(id) or -1;
    if (id < 0) then
        return '';
    end
    local resource = accessxi.load_auto_translates_resource();
    if (type(resource) ~= 'table') then
        return '';
    end
    local entry = resource[id];
    if (type(entry) ~= 'table') then
        return '';
    end
    return accessxi.plain_native_menu_label(accessxi.survival_guide_text(entry.en or entry.english or entry.name or ''));
end

function accessxi.playermo_command_id_dat_entry(command_id)
    command_id = tonumber(command_id) or 0;

    local rows = {
        [1] = { label_dat = 'ROM\\165\\74.DAT', label_row = 112, help_dat = 'ROM\\165\\75.DAT', help_row = 31 },
        [5] = { label_dat = 'ROM\\165\\76.DAT', label_row = 129, help_dat = 'ROM\\165\\75.DAT', help_row = 22 },
        [18] = { label_auto_translate = 2111, help_dat = 'ROM\\165\\75.DAT', help_row = 37 },
        [8] = { label_dat = 'ROM\\165\\74.DAT', label_row = 114, help_dat = 'ROM\\165\\75.DAT', help_row = 25 },
        [7] = { label_dat = 'ROM\\165\\74.DAT', label_row = 115, help_dat = 'ROM\\165\\75.DAT', help_row = 24 },
        [25] = { help_dat = 'ROM\\165\\75.DAT', help_row = 718 },
        [26] = { help_dat = 'ROM\\165\\75.DAT', help_row = 719 },
        [9] = { label_dat = 'ROM\\165\\74.DAT', label_row = 113, help_dat = 'ROM\\165\\75.DAT', help_row = 26 },
        [19] = { label_dat = 'ROM\\165\\76.DAT', label_row = 10, help_dat = 'ROM\\165\\75.DAT', help_row = 38 },
        [10] = { label_dat = 'ROM\\165\\74.DAT', label_row = 122, help_dat = 'ROM\\165\\75.DAT', help_row = 30 },
        [3] = { label_auto_translate = 2101, help_dat = 'ROM\\165\\75.DAT', help_row = 32 },
        [11] = { label_dat = 'ROM\\165\\74.DAT', label_row = 122, help_dat = 'ROM\\165\\75.DAT', help_row = 30 },
    };

    local spec = rows[command_id];
    if (spec == nil) then
        return nil, 'unmapped-command-id';
    end

    local label = accessxi.plain_native_menu_label(tostring(spec.label or ''));
    if (label == '' and spec.label_dat ~= nil) then
        label = accessxi.dat_index_row_text(spec.label_dat, spec.label_row, 'label');
    end
    if (label == '' and spec.label_auto_translate ~= nil) then
        label = accessxi.auto_translate_label(spec.label_auto_translate);
    end

    local help = accessxi.plain_native_menu_help(tostring(spec.help or ''));
    if (help == '' and spec.help_dat ~= nil) then
        help = accessxi.dat_index_row_text(spec.help_dat, spec.help_row, 'help');
    end

    if (label == '' and help == '') then
        return nil, 'empty-command-text';
    end

    return {
        label = label,
        help = help,
        command_id = command_id,
    }, 'ok';
end

function accessxi.playermo_command_menu_dat_entry(selected, command_ptr)
    selected = tonumber(selected) or 0;
    command_ptr = tonumber(command_ptr) or 0;

    local rows = {
        [1] = { label_dat = 'ROM\\165\\76.DAT', label_row = 129, help = '' },
        [2] = { label_dat = 'ROM\\165\\76.DAT', label_row = 77, help_dat = 'ROM\\165\\75.DAT', help_row = 25 },
        [3] = { label_dat = 'ROM\\165\\76.DAT', label_row = 68, help_dat = 'ROM\\165\\75.DAT', help_row = 24 },
        [4] = { help_dat = 'ROM\\165\\75.DAT', help_row = 718 },
        [5] = { label_dat = 'ROM\\165\\76.DAT', label_row = 2, help = '' },
        [6] = { label_dat = 'ROM\\165\\76.DAT', label_row = 10, help_dat = 'ROM\\165\\75.DAT', help_row = 38 },
        [7] = { label_dat = 'ROM\\165\\74.DAT', label_row = 122, help_dat = 'ROM\\165\\75.DAT', help_row = 30 },
    };
    local spec = rows[selected];
    if (spec == nil) then
        return nil, 'unmapped-selected';
    end
    if (command_ptr <= 0) then
        return nil, 'missing-command';
    end
    local command_base = command_ptr - ((selected - 1) * 0x14);

    local label = accessxi.plain_native_menu_label(tostring(spec.label or ''));
    if (label == '' and spec.label_dat ~= nil) then
        label = accessxi.dat_index_row_text(spec.label_dat, spec.label_row, 'label');
    end
    local help = accessxi.plain_native_menu_help(tostring(spec.help or ''));
    if (help == '' and spec.help_dat ~= nil) then
        help = accessxi.dat_index_row_text(spec.help_dat, spec.help_row, 'help');
    end
    if (label == '' and help == '') then
        return nil, 'empty-command-text';
    end

    return {
        label = label,
        help = help,
        source = ('command=0x%08X base=0x%08X'):fmt(command_ptr, command_base),
        base = command_base,
    }, 'ok';
end

function accessxi.playermo_command_context_label(command_label, command_help)
    command_label = accessxi.plain_native_menu_label(command_label or '');
    if (command_label ~= '') then
        return command_label;
    end

    command_help = accessxi.plain_native_menu_help(command_help or '');
    local lower_help = command_help:lower();
    if (lower_help:find('trust magic', 1, true) ~= nil) then
        return 'Trust Magic';
    end
    if (lower_help:find('release an alter ego', 1, true) ~= nil) then
        return 'Release';
    end
    return command_help;
end

function accessxi.playermo_menu_speech(menu_name, title, obj, selected, count, page, raw, child, entry)
    menu_name = tostring(menu_name or '');
    if (not menu_name:eq('menu    playermo', true)) then
        return nil;
    end

    selected = tonumber(selected) or 0;
    count = tonumber(count) or 0;
    page = tonumber(page) or 0;
    raw = tonumber(raw) or 0;
    obj = tonumber(obj) or 0;
    child = tonumber(child) or 0;
    entry = tonumber(entry) or 0;
    title = tostring(title or '');

    local target = safe_call(function () return AshitaCore:GetMemoryManager():GetTarget(); end, nil);
    local ank_num = target ~= nil and (tonumber(safe_call(function () return target:GetWindowAnkNum(); end, -1)) or -1) or -1;
    local ank_shape = 0;
    if (target ~= nil and ank_num >= 0) then
        ank_shape = tonumber(safe_call(function () return target:GetWindowAnkShape(ank_num); end, 0)) or 0;
    end

    local row_ptr = accessxi.is_probe_pointer(entry) and (read_u32(entry + 0x04) or 0) or 0;
    local command_ptr = accessxi.is_probe_pointer(entry) and (read_u32(entry + 0x0C) or 0) or 0;
    local row_desc_ptr = accessxi.is_probe_pointer(row_ptr) and (read_u32(row_ptr + 0x04) or 0) or 0;
    local obj_plus8 = accessxi.is_probe_pointer(obj) and (read_u32(obj + 0x08) or 0) or 0;
    local obj_command_word = accessxi.is_probe_pointer(obj) and (read_u16(obj + 0x4C) or 0) or 0;
    local obj_visible_count_word = accessxi.is_probe_pointer(obj) and (read_u16(obj + 0x58) or 0) or 0;
    local child_command_word = accessxi.is_probe_pointer(child) and (read_u16(child + 0x4C) or 0) or 0;
    local child_visible_count_word = accessxi.is_probe_pointer(child) and (read_u16(child + 0x58) or 0) or 0;
    local target_context = accessxi.playermo_target_state_context(target, title);

