function accessxi.inspect_menu_native_grid(native_cursor)
    native_cursor = tonumber(native_cursor) or 0;
    if (native_cursor < 1 or native_cursor > 16) then
        return -1;
    end

    local value = native_cursor - 1;
    return (bit.band(value, 0x03) * 4) + math.floor(value / 4);
end

function accessxi.inspect_menu_selected_slot(native_cursor)
    local grid = accessxi.inspect_menu_native_grid(native_cursor);
    if (grid < 0) then
        return -1, grid;
    end

    return tonumber(accessxi.inspect_equipment_grid_slot_order[grid]) or -1, grid;
end

function accessxi.inspect_check_item_label(item_id)
    item_id = tonumber(item_id) or 0;
    if (item_id <= 0 or item_id >= 65535) then
        return '';
    end

    local info = nil;
    if (type(accessxi.resource_item_info) == 'function') then
        info = accessxi.resource_item_info(item_id);
    end
    local label = '';
    if (type(info) == 'table') then
        label = accessxi.plain_native_menu_label(tostring(info.name or ''));
    end
    if (label == '') then
        local resources = safe_call(function () return AshitaCore:GetResourceManager(); end, nil);
        local res = resources ~= nil and safe_call(function () return resources:GetItemById(item_id); end, nil) or nil;
        if (res ~= nil and res.Name ~= nil) then
            label = accessxi.plain_native_menu_label(tostring(res.Name[1] or ''));
        end
    end

    return label;
end

function accessxi.inspect_check_character_summary(title)
    log_state(('state inspect check-summary disabled title="%s" reason="unsafe-bundled-getters"'):fmt(
        accessxi.escape_probe_log_text(tostring(title or ''))));
    return nil;
end

function accessxi.inspect_check_character_summary_unsafe(title)
    local mm = safe_call(function () return AshitaCore:GetMemoryManager(); end, nil);
    if (mm == nil) then
        return nil;
    end

    local inv = safe_call(function () return mm:GetInventory(); end, nil);
    if (inv == nil) then
        return nil;
    end

    local target = safe_call(function () return mm:GetTarget(); end, nil);
    local target_name = '';
    if (target ~= nil) then
        target_name = accessxi.plain_native_menu_label(clean_login_text(safe_call(function () return target:GetWindowName(); end, '') or ''));
    end

    local function num(fn, default)
        return tonumber(safe_call(fn, default)) or default;
    end
    local function add(parts, value)
        value = tostring(value or ''):trim();
        if (value ~= '') then
            parts:append(value);
        end
    end

    local main_job = num(function () return inv:GetCheckMainJob(); end, 0);
    local main_level = num(function () return inv:GetCheckMainJobLevel(); end, 0);
    local sub_job = num(function () return inv:GetCheckSubJob(); end, 0);
    local sub_level = num(function () return inv:GetCheckSubJobLevel(); end, 0);
    local main_job2 = num(function () return inv:GetCheckMainJob2(); end, 0);
    local mastery_level = num(function () return inv:GetCheckMasteryLevel(); end, 0);
    local mastery_flags = num(function () return inv:GetCheckMasteryFlags(); end, 0);
    local check_flags = num(function () return inv:GetCheckFlags(); end, 0);
    local server_id = num(function () return inv:GetCheckServerId(); end, 0);
    local target_index = num(function () return inv:GetCheckTargetIndex(); end, 0);

    if (main_job <= 0 and sub_job <= 0 and target_name == '') then
        return nil;
    end

    local parts = T{};
    local summary_title = tostring(title or 'Check'):trim();
    if (summary_title == '') then
        summary_title = 'Check';
    end
    add(parts, summary_title);
    add(parts, target_name);
    if (main_job > 0 and main_level > 0) then
        add(parts, ('Level %d %s'):fmt(main_level, accessxi.job_name(main_job)));
    elseif (main_job > 0) then
        add(parts, accessxi.job_name(main_job));
    end
    if (sub_job > 0 and sub_level > 0) then
        add(parts, ('Support job %s level %d'):fmt(accessxi.job_name(sub_job), sub_level));
    elseif (sub_job > 0) then
        add(parts, ('Support job %s'):fmt(accessxi.job_name(sub_job)));
    end
    if (main_job2 > 0 and main_job2 ~= main_job) then
        add(parts, ('Alternate main job %s'):fmt(accessxi.job_name(main_job2)));
    end
    if (mastery_level > 0) then
        add(parts, ('Master level %d'):fmt(mastery_level));
    end

    local gear_parts = T{};
    for slot = 0, 15 do
        local check_item = safe_call(function () return inv:GetCheckEquippedItem(slot); end, nil);
        local item_id = check_item ~= nil and (tonumber(check_item.ItemId) or 0) or 0;
        if (item_id > 0 and item_id < 65535) then
            local label = accessxi.inspect_check_item_label(item_id);
            if (label ~= '') then
                gear_parts:append(('%s %s'):fmt(accessxi.inspect_equipment_slot_names[slot] or ('Slot %d'):fmt(slot + 1), label));
            end
        end
    end
    if (gear_parts:len() > 0) then
        add(parts, ('Equipment: %s'):fmt(gear_parts:concat(', ')));
    end

    local text = parts:concat('. ') .. '.';
    accessxi.inspect_check_summary_last_key = ('%s:%s:%d:%d:%d:%d:%d:%d:%d:%d:%s:%s'):fmt(
        summary_title,
        target_name,
        main_job,
        main_level,
        sub_job,
        sub_level,
        main_job2,
        mastery_level,
        check_flags,
        server_id,
        tostring(target_index),
        gear_parts:concat('|'));
    log_state(('state inspect check-summary title="%s" target="%s" mainJob=%d mainLevel=%d subJob=%d subLevel=%d mainJob2=%d masteryLevel=%d masteryFlags=%d checkFlags=0x%08X serverId=%d targetIndex=%d native64=%d gearCount=%d text="%s"'):fmt(
        accessxi.escape_probe_log_text(summary_title),
        accessxi.escape_probe_log_text(target_name),
        main_job,
        main_level,
        sub_job,
        sub_level,
        main_job2,
        mastery_level,
        mastery_flags,
        check_flags,
        server_id,
        target_index,
        tonumber(read_current_native_menu_index(0x64)) or 0,
        gear_parts:len(),
        accessxi.escape_probe_log_text(text)));
    return text;
end

function accessxi.inspect_manual_summary_suppresses_row(native_cursor, obj, now)
    now = tonumber(now) or tick();
    local hold_until = tonumber(accessxi.inspect_manual_summary_hold_until) or 0;
    if (now >= hold_until) then
        return false;
    end

    local global_until = tonumber(accessxi.inspect_manual_summary_global_hold_until) or 0;
    if (now < global_until) then
        return true;
    end

    native_cursor = tonumber(native_cursor) or -999;
    local hold_cursor = tonumber(accessxi.inspect_manual_summary_native_cursor) or -1;
    if (hold_cursor < 0 or native_cursor ~= hold_cursor) then
        return false;
    end

    obj = tonumber(obj) or 0;
    local hold_obj = tonumber(accessxi.inspect_manual_summary_menu_obj) or 0;
    return (hold_obj == 0 or obj == 0 or obj == hold_obj);
end

function accessxi.inspect_menu_equipment_speech(menu_name, native_cursor)
    menu_name = tostring(menu_name or '');
    if (not menu_name:eq('menu    inspect', true)) then
        return nil;
    end

    native_cursor = tonumber(native_cursor) or 0;
    accessxi.last_inspect_menu_tick = tick();
    accessxi.last_inspect_native_cursor = native_cursor;
    accessxi.last_inspect_menu_obj = get_current_menu_object_ptr();
    local slot, grid = accessxi.inspect_menu_selected_slot(native_cursor);
    if (slot < 0) then
        return nil;
    end

    local inv = safe_call(function () return AshitaCore:GetMemoryManager():GetInventory(); end, nil);
    if (inv == nil) then
        return nil;
    end

    local check_item = safe_call(function () return inv:GetCheckEquippedItem(slot); end, nil);
    if (check_item == nil) then
        return nil;
    end

    local item_id = tonumber(check_item.ItemId) or 0;
    local slot_name = accessxi.inspect_equipment_slot_names[slot] or ('Slot %d'):fmt(slot + 1);
    local label = accessxi.inspect_check_item_label(item_id);
    local speech = '';
    local info = nil;
    if (label ~= '') then
        if (type(accessxi.inspect_check_item_detail_speech) == 'function') then
            speech, info = accessxi.inspect_check_item_detail_speech(slot_name, item_id, check_item);
        end
        if (speech == nil or speech == '') then
            speech = ('Check. %s. %s.'):fmt(slot_name, label);
        end
    elseif (item_id == 0) then
        speech = ('Check. %s. Empty.'):fmt(slot_name);
    else
        return nil;
    end

    accessxi.current_speech_key = ('inspect-equipment:%d:%d:%d:%s'):fmt(native_cursor, grid, item_id, label);
    if (info ~= nil) then
        accessxi.capture_current_gear_detail(menu_name, info, T{
            index = slot,
            slot_name = slot_name,
            source = 'inspect',
        });
    end
    log_state(('state inspect equipment-row menu="%s" native4c=%d grid=%d slot=%d slotName="%s" itemId=%d label="%s" extraLen=%d'):fmt(
        menu_name,
        native_cursor,
        grid,
        slot,
        accessxi.escape_probe_log_text(slot_name),
        item_id,
        accessxi.escape_probe_log_text(label),
        #(tostring(check_item.Extra or ''))));
    return accessxi.speech_output_text(speech);
end

function accessxi.inspect_menu_probe_speech(menu_name, title, obj, selected, count, page, raw, child, entry, reason)
    menu_name = tostring(menu_name or '');
    if (not menu_name:eq('menu    inspect', true)) then
        return nil;
    end
    accessxi.last_inspect_menu_tick = tick();

    obj = tonumber(obj) or get_current_menu_object_ptr();
    if (obj == 0) then
        return nil;
    end
    accessxi.last_inspect_menu_obj = obj;
    accessxi.last_inspect_native_cursor = tonumber(read_current_native_menu_index(0x4C)) or tonumber(accessxi.last_inspect_native_cursor) or 0;

    selected = tonumber(selected) or 0;
    count = tonumber(count) or 0;
    page = tonumber(page) or 0;
    raw = tonumber(raw) or 0;
    child = tonumber(child) or 0;
    entry = tonumber(entry) or 0;
    if (child == 0 or entry == 0) then
        local q_selected, q_page, q_raw, q_child, q_count = accessxi.survival_guide_query_child_state_for_obj(obj);
        if (selected <= 0) then
            selected = tonumber(q_selected) or 0;
        end
        if (count <= 0) then
            count = tonumber(q_count) or 0;
        end
        if (page <= 0) then
            page = tonumber(q_page) or 0;
        end
        if (raw == 0) then
            raw = tonumber(q_raw) or 0;
        end
        if (child == 0) then
            child = tonumber(q_child) or 0;
        end
    end
    if (entry == 0 and accessxi.is_probe_pointer(obj)) then
        entry = read_u32(obj + 0x08) or 0;
    end

    local native_cursor = read_current_native_menu_index(0x4C);
    if (accessxi.inspect_manual_summary_suppresses_row(native_cursor, obj)) then
        local suppress_key = ('%s:%d:0x%08X'):fmt(menu_name, tonumber(native_cursor) or 0, tonumber(obj) or 0);
        if (suppress_key ~= accessxi.inspect_manual_summary_suppress_log_key) then
            accessxi.inspect_manual_summary_suppress_log_key = suppress_key;
            log_state(('state inspect equipment-row suppressed reason="manual-check-summary hold" menu="%s" native4c=%d obj=0x%08X until=%d'):fmt(
                accessxi.escape_probe_log_text(menu_name),
                tonumber(native_cursor) or 0,
                tonumber(obj) or 0,
                tonumber(accessxi.inspect_manual_summary_hold_until) or 0));
        end
        return nil;
    end
    local equipment_speech = accessxi.inspect_menu_equipment_speech(menu_name, native_cursor);
    if (equipment_speech ~= nil) then
        return equipment_speech;
    end

    local index_parts = T{};
    for _, offset in ipairs(T{ 0x24, 0x28, 0x2C, 0x30, 0x34, 0x38, 0x3C, 0x40, 0x44, 0x48, 0x4C, 0x50, 0x54, 0x58, 0x5C, 0x60, 0x64, 0x68 }) do
        index_parts:append(('%02X=%d'):fmt(offset, tonumber(read_current_native_menu_index(offset)) or 0));
    end

    local target = safe_call(function () return AshitaCore:GetMemoryManager():GetTarget(); end, nil);
    local target_name = '';
    local ank_num = -1;
    local ank_x = -1;
    local ank_y = -1;
    local sub = -1;
    local sub_x = -1;
    local sub_y = -1;
    local ank_shape = 0;
    if (target ~= nil) then
        target_name = accessxi.plain_native_menu_label(safe_call(function () return target:GetWindowName(); end, '') or '');
        ank_num = tonumber(safe_call(function () return target:GetWindowAnkNum(); end, -1)) or -1;
        ank_x = tonumber(safe_call(function () return target:GetWindowAnkX(); end, -1)) or -1;
        ank_y = tonumber(safe_call(function () return target:GetWindowAnkY(); end, -1)) or -1;
        sub = tonumber(safe_call(function () return target:GetWindowSub(); end, -1)) or -1;
        sub_x = tonumber(safe_call(function () return target:GetWindowSubAnkX(); end, -1)) or -1;
        sub_y = tonumber(safe_call(function () return target:GetWindowSubAnkY(); end, -1)) or -1;
        if (ank_num >= 0 and ank_num <= 16) then
            ank_shape = tonumber(safe_call(function () return target:GetWindowAnkShape(ank_num); end, 0)) or 0;
        end
    end

    local key = ('%s:%d:%d:%d:0x%08X:0x%08X:0x%08X:%s'):fmt(
        menu_name,
        selected,
        count,
        page,
        raw,
        child,
        entry,
        index_parts:concat(','));
    local now = tick();
    if (key ~= tostring(accessxi.last_inspect_menu_probe_key or '')
        and ((now - (tonumber(accessxi.last_inspect_menu_probe_tick) or 0)) >= 120)) then
        accessxi.last_inspect_menu_probe_key = key;
        accessxi.last_inspect_menu_probe_tick = now;
        log_state(('state inspect probe reason="%s" menu="%s" title="%s" target="%s" select=%d count=%d page=%d raw=0x%08X obj=0x%08X child=0x%08X entry=0x%08X ank=%d ankXY=(%d,%d) sub=%d subXY=(%d,%d) ankShape=0x%08X idx="%s" objDwords="%s" childDwords="%s" entryDwords="%s" ankStrings="%s" childStrings="%s" entryStrings="%s"'):fmt(
            accessxi.escape_probe_log_text(tostring(reason or '')),
            menu_name,
            accessxi.escape_probe_log_text(tostring(title or '')),
            accessxi.escape_probe_log_text(target_name),
            selected,
            count,
            page,
            raw,
            obj,
            child,
            entry,
            ank_num,
            ank_x,
            ank_y,
            sub,
            sub_x,
            sub_y,
            ank_shape,
            accessxi.escape_probe_log_text(index_parts:concat(',')),
            accessxi.escape_probe_log_text(accessxi.format_probe_dwords(obj, 0x00, 20)),
            accessxi.escape_probe_log_text(accessxi.format_probe_dwords(child, 0x00, 20)),
            accessxi.escape_probe_log_text(accessxi.format_probe_dwords(entry, 0x00, 20)),
            accessxi.escape_probe_log_text(accessxi.status_menu_probe_inline_strings(ank_shape)),
            accessxi.escape_probe_log_text(accessxi.status_menu_probe_inline_strings(child)),
            accessxi.escape_probe_log_text(accessxi.status_menu_probe_inline_strings(entry))));
    end

    return nil;
end

function accessxi.friend_list_dynamic_text_probe(ptr, length, limit)
    ptr = tonumber(ptr) or 0;
    if (not accessxi.is_probe_pointer(ptr)) then
        return '';
    end

    length = tonumber(length) or 0x240;
    limit = tonumber(limit) or 8;
    local parts = T{};
    local seen = {};

    local function add_text(kind, offset, text)
        text = accessxi.survival_guide_text(text or ''):gsub('%s+', ' '):trim();
        if (text == '' or #text < 2 or #text > 96 or text:match('%a') == nil) then
            return;
        end

        local lower = text:lower();
        if (lower:find('menu    ', 1, true) ~= nil
            or lower:find('windowps', 1, true) ~= nil
            or lower:find('keytops', 1, true) ~= nil
            or lower:find('shell32', 1, true) ~= nil
            or lower:find('accessxi', 1, true) ~= nil) then
            return;
        end

        local key = lower;
        if (seen[key] == true) then
            return;
        end
        seen[key] = true;
        parts:append(('%s+%03X=%s'):fmt(
            tostring(kind or ''),
            tonumber(offset) or 0,
            accessxi.escape_probe_log_text(text)));
    end

    for _, off in ipairs(T{ 0x00, 0x04, 0x08, 0x0C, 0x10, 0x14, 0x18, 0x20, 0x24, 0x28, 0x30, 0x3D, 0x40, 0x46, 0x50, 0x58, 0x60, 0x80 }) do
        add_text('str', off, read_probe_string(ptr + off, 96));
        if (parts:len() >= limit) then
            return parts:concat(' | ');
        end
    end

    if (accessxi.collect_probe_ffxi_utf16_entries ~= nil) then
        for _, entry in ipairs(accessxi.collect_probe_ffxi_utf16_entries(ptr, length, 2, limit)) do
            add_text('ffxi', tonumber(entry.offset) or 0, entry.text or '');
            if (parts:len() >= limit) then
                return parts:concat(' | ');
            end
        end
    end

    if (accessxi.collect_probe_ascii_runs ~= nil) then
        for _, run in ipairs(accessxi.collect_probe_ascii_runs(ptr, length, 2, limit)) do
            local off_text, text = tostring(run or ''):match('^%+(%x+)="(.*)"$');
            add_text('ascii', tonumber(off_text or '0', 16) or 0, text or tostring(run or ''));
            if (parts:len() >= limit) then
                return parts:concat(' | ');
            end
        end
    end

    if (accessxi.collect_probe_utf16_runs ~= nil) then
        for _, run in ipairs(accessxi.collect_probe_utf16_runs(ptr, length, 2, limit)) do
            local off_text, text = tostring(run or ''):match('^%+(%x+)="(.*)"$');
            add_text('utf16', tonumber(off_text or '0', 16) or 0, text or tostring(run or ''));
            if (parts:len() >= limit) then
                return parts:concat(' | ');
            end
        end
    end

    return parts:concat(' | ');
end

function accessxi.friend_list_pointer_text_targets(ptr)
    ptr = tonumber(ptr) or 0;
    if (not accessxi.is_probe_pointer(ptr)) then
        return '';
    end

    local parts = T{};
    local seen = {};
    for off = 0, 0x100, 4 do
        local target = read_u32(ptr + off) or 0;
        if (accessxi.is_probe_pointer(target) and seen[target] ~= true and parts:len() < 8) then
            seen[target] = true;
            local desc = read_u32(target + 0x04) or 0;
            local desc_name = accessxi.is_probe_pointer(desc) and clean_probe_text(read_probe_string(desc + 0x46, 64)) or '';
            local text = accessxi.friend_list_dynamic_text_probe(target, 0x180, 4);
            if (desc_name ~= '' or text ~= '') then
                parts:append(('+%03X->0x%08X desc="%s" text="%s"'):fmt(
                    off,
                    target,
                    accessxi.escape_probe_log_text(desc_name),
                    accessxi.escape_probe_log_text(text)));
            end
        end
    end
    return parts:concat(' || ');
end

function accessxi.friend_list_row_chain_probe(row_rec)
    row_rec = tonumber(row_rec) or 0;
    if (not accessxi.is_probe_pointer(row_rec)) then
        return '';
    end

    local parts = T{};
    for slot = -1, 4 do
        local rec = row_rec + (slot * 0x14);
        if (accessxi.is_probe_pointer(rec)) then
            local window = read_u32(rec + 0x00) or 0;
            local data = read_u32(rec + 0x04) or 0;
            local window_name = accessxi.is_probe_pointer(window) and clean_probe_text(read_probe_string(window + 0x24, 48)) or '';
            local window_text = accessxi.friend_list_dynamic_text_probe(window, 0x180, 4);
            local data_text = accessxi.friend_list_dynamic_text_probe(data, 0x300, 8);
            local data_ptrs = accessxi.friend_list_pointer_text_targets(data);
            parts:append(('slot%+d rec=0x%08X win=0x%08X name="%s" data=0x%08X dataD="%s" winText="%s" dataText="%s" dataPtrs="%s"'):fmt(
                slot,
                rec,
                window,
                accessxi.escape_probe_log_text(window_name),
                data,
                accessxi.escape_probe_log_text(accessxi.format_probe_dwords(data, 0, 12)),
                accessxi.escape_probe_log_text(window_text),
                accessxi.escape_probe_log_text(data_text),
                accessxi.escape_probe_log_text(data_ptrs)));
        end
    end
    return parts:concat(' || ');
end

function accessxi.friend_list_fragment_probe(ptr, max_records)
    ptr = tonumber(ptr) or 0;
    if (not accessxi.is_probe_pointer(ptr)) then
        return '';
    end

    max_records = math.max(1, math.min(tonumber(max_records) or 8, 12));
    local parts = T{};
    for index = 0, max_records - 1 do
        local off = index * 0x18;
        local font_ptr = read_u32(ptr + off) or 0;
        local text_ptr1 = read_u32(ptr + off + 0x04) or 0;
        local len1 = read_u32(ptr + off + 0x08) or 0;
        local text_ptr2 = read_u32(ptr + off + 0x0C) or 0;
        local len2 = read_u32(ptr + off + 0x10) or 0;
        local flags = read_u32(ptr + off + 0x14) or 0;
        if (font_ptr ~= 0 or text_ptr1 ~= 0 or len1 ~= 0 or text_ptr2 ~= 0 or len2 ~= 0 or flags ~= 0) then
            local read_len1 = math.max(1, math.min(len1 + 2, 120));
            local read_len2 = math.max(1, math.min(len2 + 2, 120));
            local text1 = accessxi.is_probe_pointer(text_ptr1) and read_probe_string(text_ptr1, read_len1) or '';
            local text2 = accessxi.is_probe_pointer(text_ptr2) and read_probe_string(text_ptr2, read_len2) or '';
            parts:append(('%02d@+%02X font=0x%08X p1=0x%08X l1=%d t1="%s" p2=0x%08X l2=%d t2="%s" flags=0x%08X'):fmt(
                index + 1,
                off,
                font_ptr,
                text_ptr1,
                len1,
                accessxi.escape_probe_log_text(text1),
                text_ptr2,
                len2,
                accessxi.escape_probe_log_text(text2),
                flags));
            if (parts:len() >= max_records) then
                break;
            end
        end
    end
    return parts:concat(' || ');
end

function accessxi.friend_list_render_records_summary(ptr, length, max_records)
    ptr = tonumber(ptr) or 0;
    if (not accessxi.is_probe_pointer(ptr)) then
        return '';
    end

    length = math.max(0x40, math.min(tonumber(length) or 0x300, 0x800));
    max_records = math.max(1, math.min(tonumber(max_records) or 24, 60));
    local parts = T{};
    local seen = {};

    local function u16(addr)
        return tonumber(read_u16(addr)) or 0;
    end

    local function u32(addr)
        return tonumber(read_u32(addr)) or 0;
    end

    for off = 0, length - 8 do
        if (parts:len() >= max_records) then
            break;
        end

        local name = read_probe_string(ptr + off, 16);
        if (name:sub(1, 8) == 'menu    ') then
            local start = off - 4;
            if (start >= 0 and seen[start] ~= true) then
                seen[start] = true;
                local tex = clean_probe_text(name);
                local head0 = u16(ptr + start + 0x00);
                local head1 = u16(ptr + start + 0x02);
                local p18 = u32(ptr + start + 0x18);
                local f1 = u16(ptr + start + 0x1C);
                local f2 = u16(ptr + start + 0x1E);
                local sig0 = u16(ptr + start + 0x20);
                local sig1 = u16(ptr + start + 0x22);
                local pos0 = u16(ptr + start + 0x24);
                local pos1 = u16(ptr + start + 0x26);
                parts:append(('+%03X tex="%s" head=%04X/%04X p18=0x%08X f=%04X,%04X sig=%04X,%04X pos=%04X,%04X'):fmt(
                    start,
                    accessxi.escape_probe_log_text(tex),
                    head0,
                    head1,
                    p18,
                    f1,
                    f2,
                    sig0,
                    sig1,
                    pos0,
                    pos1));
            end
        end
    end

    return parts:concat(' || ');
end

function accessxi.log_friend_list_current_render_records(menu_name, selected, count, entry, row_rec, row_data, row_index, order, reason)
    row_data = tonumber(row_data) or 0;
    if (not accessxi.is_probe_pointer(row_data)) then
        return;
    end

    local function u16(addr)
        return tonumber(read_u16(addr)) or 0;
    end

    local function u32(addr)
        return tonumber(read_u32(addr)) or 0;
    end

    local seen = {};
    local emitted = 0;
    local max_records = 72;
    for off = 0, 0x780 do
        if (emitted >= max_records) then
            break;
        end

        local name = read_probe_string(row_data + off, 16);
        if (name:sub(1, 8) == 'menu    ') then
            local start = off - 4;
            if (start >= 0 and seen[start] ~= true) then
                seen[start] = true;
                emitted = emitted + 1;
                local tex = clean_probe_text(name);
                log_line(('state friend-list current-record menu="%s" select=%d count=%d rowIndex=%d order=0x%04X entry=0x%08X rowRec=0x%08X rowData=0x%08X reason="%s" rec=%02d off=0x%03X tex="%s" head=%04X/%04X p18=0x%08X f=%04X,%04X sig=%04X,%04X pos=%04X,%04X d=%08X,%08X,%08X,%08X,%08X,%08X,%08X,%08X,%08X,%08X'):fmt(
                    tostring(menu_name or ''),
                    tonumber(selected) or 0,
                    tonumber(count) or 0,
                    tonumber(row_index) or 0,
                    tonumber(order) or 0,
                    tonumber(entry) or 0,
                    tonumber(row_rec) or 0,
                    row_data,
                    accessxi.escape_probe_log_text(tostring(reason or '')),
                    emitted,
                    start,
                    accessxi.escape_probe_log_text(tex),
                    u16(row_data + start + 0x00),
                    u16(row_data + start + 0x02),
                    u32(row_data + start + 0x18),
                    u16(row_data + start + 0x1C),
                    u16(row_data + start + 0x1E),
                    u16(row_data + start + 0x20),
                    u16(row_data + start + 0x22),
                    u16(row_data + start + 0x24),
                    u16(row_data + start + 0x26),
                    u32(row_data + start + 0x00),
                    u32(row_data + start + 0x04),
                    u32(row_data + start + 0x08),
                    u32(row_data + start + 0x0C),
                    u32(row_data + start + 0x10),
                    u32(row_data + start + 0x14),
                    u32(row_data + start + 0x18),
                    u32(row_data + start + 0x1C),
                    u32(row_data + start + 0x20),
                    u32(row_data + start + 0x24)));
            end
        end
    end

    log_line(('state friend-list current-record-end menu="%s" select=%d count=%d entry=0x%08X rowData=0x%08X emitted=%d capped=%s'):fmt(
        tostring(menu_name or ''),
        tonumber(selected) or 0,
        tonumber(count) or 0,
        tonumber(entry) or 0,
        row_data,
        emitted,
        tostring(emitted >= max_records)));
end

function accessxi.friend_list_row_render_records_summary(entry)
    entry = tonumber(entry) or 0;
    if (not accessxi.is_probe_pointer(entry)) then
        return '';
    end

    local row_rec = read_u32(entry + 0x0C) or 0;
    if (not accessxi.is_probe_pointer(row_rec)) then
        return '';
    end

    local parts = T{};
    local seen_data = {};
    for slot = -1, 6 do
        local rec = row_rec + (slot * 0x14);
        if (accessxi.is_probe_pointer(rec)) then
            local win = read_u32(rec + 0x00) or 0;
            local data = read_u32(rec + 0x04) or 0;
            if (accessxi.is_probe_pointer(data) and seen_data[data] ~= true) then
                seen_data[data] = true;
                local win_name = accessxi.is_probe_pointer(win) and clean_probe_text(read_probe_string(win + 0x24, 48)) or '';
                local records = accessxi.friend_list_render_records_summary(data, 0x380, 32);
                if (records ~= '') then
                    parts:append(('slot%+d rec=0x%08X win=0x%08X winName="%s" data=0x%08X records="%s"'):fmt(
                        slot,
                        rec,
                        win,
                        accessxi.escape_probe_log_text(win_name),
                        data,
                        accessxi.escape_probe_log_text_wide(records)));
                end
            end
        end
    end

    return parts:concat(' || ');
end

function accessxi.log_friend_list_render_records_probe(menu_name, selected, count, entry, reason)
    if (not tostring(menu_name or ''):eq('menu    friend', true)) then
        return;
    end

    selected = tonumber(selected) or 0;
    count = tonumber(count) or 0;
    entry = tonumber(entry) or 0;
    if (selected <= 0 or not accessxi.is_probe_pointer(entry)) then
        return;
    end

    accessxi.friend_list_glyph_probe_count = tonumber(accessxi.friend_list_glyph_probe_count) or 0;
    accessxi.friend_list_glyph_probe_limit = tonumber(accessxi.friend_list_glyph_probe_limit) or 80;
    if (accessxi.friend_list_glyph_probe_count >= accessxi.friend_list_glyph_probe_limit) then
        return;
    end

    local row_rec = read_u32(entry + 0x0C) or 0;
    local row_data = accessxi.is_probe_pointer(row_rec) and (read_u32(row_rec + 0x04) or 0) or 0;
    local key = ('%s:%d:%d:0x%08X:0x%08X:%s'):fmt(
        tostring(menu_name or ''),
        selected,
        count,
        entry,
        row_data,
        tostring(reason or ''));
    if (key == tostring(accessxi.last_friend_list_glyph_probe_key or '')) then
        return;
    end
    accessxi.last_friend_list_glyph_probe_key = key;
    accessxi.friend_list_glyph_probe_count = accessxi.friend_list_glyph_probe_count + 1;

    local row_code = read_u32(entry + 0x38) or 0;
    local row_index = math.floor(row_code / 0x10000);
    local order = row_code % 0x10000;
    accessxi.log_friend_list_current_render_records(menu_name, selected, count, entry, row_rec, row_data, row_index, order, reason);
    local records = accessxi.friend_list_row_render_records_summary(entry);
    log_state(('state friend-list render-records menu="%s" select=%d count=%d rowIndex=%d order=0x%04X entry=0x%08X rowRec=0x%08X rowData=0x%08X reason="%s" records="%s"'):fmt(
        tostring(menu_name or ''),
        selected,
        count,
        row_index,
        order,
        entry,
        row_rec,
        row_data,
        accessxi.escape_probe_log_text(tostring(reason or '')),
        accessxi.escape_probe_log_text_wide(records)));
end

function accessxi.friend_list_glyph_entries_summary(ptr, length, min_len, limit)
    ptr = tonumber(ptr) or 0;
    if (not accessxi.is_probe_pointer(ptr) or accessxi.chat_log_rendered_glyph_entries_from_ptr == nil) then
        return '';
    end

    local entries = accessxi.chat_log_rendered_glyph_entries_from_ptr(
        ptr,
        tonumber(length) or 0x180,
        tonumber(min_len) or 2,
        tonumber(limit) or 8);
    local parts = T{};
    for _, entry in ipairs(entries or T{}) do
        local text = tostring(entry.text or ''):gsub('%s+', ' '):trim();
        if (text ~= '') then
            parts:append(('+%03X="%s"'):fmt(
                tonumber(entry.offset) or 0,
                accessxi.escape_probe_log_text(text)));
        end
    end
    return parts:concat(' | ');
end

function accessxi.friend_list_source_glyph_text(ptr)
    ptr = tonumber(ptr) or 0;
    if (not accessxi.is_probe_pointer(ptr) or accessxi.chat_log_decode_selected_source_glyph_text == nil) then
        return '';
    end

    local text = accessxi.chat_log_decode_selected_source_glyph_text(ptr);
    text = tostring(text or ''):gsub('%s+', ' '):trim();
    if (text == '' or #text > 96) then
        return '';
    end
    return text;
end

function accessxi.friend_list_glyph_target_summary(label, ptr)
    ptr = tonumber(ptr) or 0;
    if (not accessxi.is_probe_pointer(ptr)) then
        return '';
    end

    local plain = accessxi.friend_list_dynamic_text_probe(ptr, 0x220, 4);
    local rendered = accessxi.friend_list_glyph_entries_summary(ptr, 0x240, 2, 8);
    local source = accessxi.friend_list_source_glyph_text(ptr);
    local probe = '';
    if (accessxi.chat_log_selected_source_glyph_probe ~= nil) then
        probe = accessxi.chat_log_selected_source_glyph_probe(ptr);
    end
    if (plain == '' and rendered == '' and source == '' and probe == '') then
        return '';
    end

    return ('%s=0x%08X d="%s" plain="%s" rendered="%s" source="%s" probe="%s"'):fmt(
        tostring(label or 'ptr'),
        ptr,
        accessxi.escape_probe_log_text(accessxi.format_probe_dwords(ptr, 0, 8)),
        accessxi.escape_probe_log_text(plain),
        accessxi.escape_probe_log_text(rendered),
        accessxi.escape_probe_log_text(source),
        accessxi.escape_probe_log_text(probe));
end

function accessxi.friend_list_selected_row_glyph_probe(child, entry, selected)
    child = tonumber(child) or 0;
    entry = tonumber(entry) or 0;
    selected = tonumber(selected) or 0;
    if (selected <= 0) then
        return '';
    end

    local parts = T{};
    local seen = {};
    local function add(label, ptr)
        ptr = tonumber(ptr) or 0;
        if (not accessxi.is_probe_pointer(ptr) or seen[ptr] == true or #parts >= 24) then
            return;
        end
        seen[ptr] = true;
        local summary = accessxi.friend_list_glyph_target_summary(label, ptr);
        if (summary ~= '') then
            parts:append(summary);
        end
    end

    local row_rec = accessxi.is_probe_pointer(entry) and (read_u32(entry + 0x0C) or 0) or 0;
    local row_data = accessxi.is_probe_pointer(row_rec) and (read_u32(row_rec + 0x04) or 0) or 0;
    add('entry', entry);
    add('rowData', row_data);

    if (accessxi.is_probe_pointer(child)) then
        for _, base in ipairs(T{ 0x60, 0x70, 0x80, 0x90, 0xA0, 0xA8, 0xB0, 0xC0 }) do
            local ptr = read_u32(child + base + ((selected - 1) * 4)) or 0;
            add(('child+%03X[%02d]'):fmt(base, selected - 1), ptr);
            if (accessxi.is_probe_pointer(ptr)) then
                for record = 0, 5 do
                    local off = record * 0x18;
                    for _, field in ipairs(T{ 0x04, 0x08, 0x0C, 0x10 }) do
                        local target = read_u32(ptr + off + field) or 0;
                        add(('child+%03X[%02d].frag%02d+%02X'):fmt(base, selected - 1, record, field), target);
                    end
                end
            end
        end
    end

    if (accessxi.is_probe_pointer(row_data)) then
        for off = 0, 0x7C, 4 do
            local target = read_u32(row_data + off) or 0;
            add(('rowData+%02X'):fmt(off), target);
        end
    end

    return parts:concat(' || ');
end

function accessxi.log_friend_list_selected_row_glyph_targets(menu_name, child, entry, selected, count)
    child = tonumber(child) or 0;
    entry = tonumber(entry) or 0;
    selected = tonumber(selected) or 0;
    count = tonumber(count) or 0;
    if (selected <= 0) then
        return;
    end

    local row_rec = accessxi.is_probe_pointer(entry) and (read_u32(entry + 0x0C) or 0) or 0;
    local row_data = accessxi.is_probe_pointer(row_rec) and (read_u32(row_rec + 0x04) or 0) or 0;
    local seen = {};
    local logged = 0;
    local function add(label, ptr, depth)
        ptr = tonumber(ptr) or 0;
        depth = tonumber(depth) or 0;
        if (not accessxi.is_probe_pointer(ptr) or seen[ptr] == true or logged >= 36) then
            return;
        end
        seen[ptr] = true;

        local plain = accessxi.friend_list_dynamic_text_probe(ptr, 0x320, 8);
        local rendered = accessxi.friend_list_glyph_entries_summary(ptr, 0x320, 2, 10);
        local source = accessxi.friend_list_source_glyph_text(ptr);
        local ascii = accessxi.probe_runs_to_text(accessxi.collect_probe_ascii_runs(ptr, 0x320, 3, 10));
        local utf16 = accessxi.probe_runs_to_text(accessxi.collect_probe_utf16_runs(ptr, 0x240, 3, 6));
        local ffxi16 = accessxi.probe_runs_to_text(accessxi.collect_probe_ffxi_utf16_runs(ptr, 0x240, 3, 6));
        if (plain ~= '' or rendered ~= '' or source ~= '' or ascii ~= '' or utf16 ~= '' or ffxi16 ~= '') then
            logged = logged + 1;
            log_state(('state friend-list glyph-target menu="%s" select=%d count=%d label="%s" ptr=0x%08X depth=%d d="%s" plain="%s" rendered="%s" source="%s" ascii="%s" utf16="%s" ffxi16="%s"'):fmt(
                tostring(menu_name or ''),
                selected,
                count,
                accessxi.escape_probe_log_text(tostring(label or '')),
                ptr,
                depth,
                accessxi.escape_probe_log_text(accessxi.format_probe_dwords(ptr, 0, 10)),
                accessxi.escape_probe_log_text_wide(plain),
                accessxi.escape_probe_log_text_wide(rendered),
                accessxi.escape_probe_log_text(source),
                accessxi.escape_probe_log_text_wide(ascii),
                accessxi.escape_probe_log_text_wide(utf16),
                accessxi.escape_probe_log_text_wide(ffxi16)));
        end

        if (depth >= 1) then
            return;
        end
        for off = 0, 0x7C, 4 do
            local target = read_u32(ptr + off) or 0;
            if (accessxi.is_probe_pointer(target)) then
                add(('%s+%02X'):fmt(tostring(label or 'ptr'), off), target, depth + 1);
            end
        end
    end

    add('entry', entry, 0);
    add('rowData', row_data, 0);
    if (accessxi.is_probe_pointer(child)) then
        for _, base in ipairs(T{ 0x60, 0x70, 0x80, 0x90, 0xA0, 0xA8, 0xB0, 0xC0 }) do
            local ptr = read_u32(child + base + ((selected - 1) * 4)) or 0;
            add(('child+%03X[%02d]'):fmt(base, selected - 1), ptr, 0);
        end
    end
end

function accessxi.friend_list_child_row_pointer_probe(child, selected)
    child = tonumber(child) or 0;
    selected = tonumber(selected) or 0;
    if (not accessxi.is_probe_pointer(child) or selected <= 0) then
        return '';
    end

    local parts = T{};
    for _, base in ipairs(T{ 0x60, 0x70, 0x80, 0x90, 0xA0, 0xA8, 0xB0, 0xC0 }) do
        for _, index in ipairs(T{ selected - 1, selected, selected + 1 }) do
            if (index >= 0 and index <= 24) then
                local ptr = read_u32(child + base + (index * 4)) or 0;
                if (accessxi.is_probe_pointer(ptr)) then
                    local text = accessxi.friend_list_dynamic_text_probe(ptr, 0x300, 6);
                    local fragments = accessxi.friend_list_fragment_probe(ptr, 6);
                    parts:append(('+%03X[%02d]=0x%08X d="%s" text="%s" fragments="%s"'):fmt(
                        base,
                        index,
                        ptr,
                        accessxi.escape_probe_log_text(accessxi.format_probe_dwords(ptr, 0, 10)),
                        accessxi.escape_probe_log_text(text),
                        accessxi.escape_probe_log_text(fragments)));
                    if (parts:len() >= 16) then
                        return parts:concat(' || ');
                    end
                end
            end
        end
    end
    return parts:concat(' || ');
end

function accessxi.friend_list_probe_pointer_allowed(ptr)
    ptr = tonumber(ptr) or 0;
    if (not accessxi.is_probe_pointer(ptr)) then
        return false;
    end
    if (accessxi.records_of_eminence_detail_probe_pointer_value_ascii ~= nil
        and accessxi.records_of_eminence_detail_probe_pointer_value_ascii(ptr)) then
        return false;
    end

    local mbi = ffi.new('MEMORY_BASIC_INFORMATION[1]');
    local mbi_size = ffi.sizeof('MEMORY_BASIC_INFORMATION');
    local ok, queried = pcall(function ()
        return kernel32.VirtualQuery(ffi.cast('const void*', ptr), mbi, mbi_size);
    end);
    if (not ok or (tonumber(queried) or 0) == 0) then
        return false;
    end

    local state = tonumber(mbi[0].State) or 0;
    local protect = tonumber(mbi[0].Protect) or 0;
    if (state ~= 0x1000 or not accessxi.memory_page_readable(protect)) then
        return false;
    end
    if (accessxi.memory_page_executable(protect)) then
        return false;
    end

    return true;
end

function accessxi.friend_list_name_buffer_summary(ptr, source)
    local items = accessxi.friend_list_dynamic_candidate_records(ptr, 0x340, 18, source);
    local parts = T{};
    local seen = {};
    for _, item in ipairs(items or T{}) do
        local text = tostring(item.text or '');
        local key = text:lower();
        if (text ~= '' and seen[key] ~= true) then
            seen[key] = true;
            parts:append(('%s+%03X="%s"'):fmt(
                tostring(item.kind or ''),
                tonumber(item.offset) or 0,
                accessxi.escape_probe_log_text(text)));
        end
    end
    return parts:concat(' | ');
end

function accessxi.friend_list_name_buffer_record_probe(ptr, source)
    ptr = tonumber(ptr) or 0;
    source = tostring(source or '');
    if (not accessxi.friend_list_probe_pointer_allowed(ptr)) then
        return T{};
    end

    local records = accessxi.friend_list_dynamic_candidate_records(ptr, 0x520, 32, source);
    local out = T{};
    local seen = {};
    for _, item in ipairs(records or T{}) do
        local text = tostring(item.text or ''):gsub('%s+', ' '):trim();
        local lower = text:lower();
        local off = tonumber(item.offset) or 0;
        if (text ~= '' and #text >= 4 and seen[lower] ~= true) then
            seen[lower] = true;
            local start = math.max(0, off - 0x20);
            local rel = off - start;
            out:append(T{
                kind = tostring(item.kind or ''),
                offset = off,
                text = text,
                start = start,
                rel = rel,
                bytes = accessxi.format_probe_bytes(ptr + start, 0, math.min(0x30, 0x520 - start)),
                dwords = accessxi.format_probe_dwords(ptr + start, 0, math.min(12, math.floor((0x520 - start) / 4))),
            });
        end
        if (#out >= 12) then
            break;
        end
    end

    return out;
end

function accessxi.log_friend_list_name_buffer_probe(menu_name, selected, count, child, entry, reason)
    if (not tostring(menu_name or ''):eq('menu    friend', true)) then
        return;
    end

    selected = tonumber(selected) or 0;
    count = tonumber(count) or 0;
    child = tonumber(child) or 0;
    entry = tonumber(entry) or 0;
    if (selected <= 0 or count <= 0 or not accessxi.is_probe_pointer(child)) then
        return;
    end

    local key = ('%s:%d:%d:0x%08X:0x%08X:%s'):fmt(
        tostring(menu_name or ''),
        selected,
        count,
        child,
        entry,
        tostring(reason or ''));
    if (key == tostring(accessxi.last_friend_list_name_buffer_probe_key or '')) then
        return;
    end
    accessxi.last_friend_list_name_buffer_probe_key = key;

    local emitted = 0;
    local max_lines = math.max(2, math.min(tonumber(accessxi.friend_list_name_buffer_probe_limit) or 12, 32));
    for _, base in ipairs(T{ 0x60, 0x70, 0x80, 0x90 }) do
        for index = 0, math.max(8, math.min(count + 6, 24)) - 1 do
            if (emitted >= max_lines) then
                log_state(('state friend-list name-buffer-end menu="%s" select=%d count=%d child=0x%08X emitted=%d capped=true'):fmt(
                    tostring(menu_name or ''),
                    selected,
                    count,
                    child,
                    emitted));
                return;
            end

            local ptr = read_u32(child + base + (index * 4)) or 0;
            if (accessxi.friend_list_probe_pointer_allowed(ptr)) then
                local source = ('child+%03X[%02d]'):fmt(base, index);
                local records = accessxi.friend_list_name_buffer_record_probe(ptr, source);
                if (#records > 0) then
                    emitted = emitted + 1;
                    log_state(('state friend-list name-buffer menu="%s" select=%d count=%d child=0x%08X entry=0x%08X base=0x%03X index=%02d selectedSlot=%s ptr=0x%08X recordCount=%d reason="%s"'):fmt(
                        tostring(menu_name or ''),
                        selected,
                        count,
                        child,
                        entry,
                        base,
                        index,
                        tostring(index == (selected - 1)),
                        ptr,
                        #records,
                        accessxi.escape_probe_log_text(tostring(reason or ''))));
                    for _, rec in ipairs(records) do
                        log_state(('state friend-list name-buffer-record menu="%s" select=%d count=%d child=0x%08X entry=0x%08X base=0x%03X index=%02d selectedSlot=%s ptr=0x%08X kind="%s" off=0x%03X start=0x%03X rel=0x%02X text="%s" dwords="%s" bytes="%s" reason="%s"'):fmt(
                            tostring(menu_name or ''),
                            selected,
                            count,
                            child,
                            entry,
                            base,
                            index,
                            tostring(index == (selected - 1)),
                            ptr,
                            accessxi.escape_probe_log_text(tostring(rec.kind or '')),
                            tonumber(rec.offset) or 0,
                            tonumber(rec.start) or 0,
                            tonumber(rec.rel) or 0,
                            accessxi.escape_probe_log_text(tostring(rec.text or '')),
                            accessxi.escape_probe_log_text_wide(tostring(rec.dwords or '')),
                            accessxi.escape_probe_log_text_wide(tostring(rec.bytes or '')),
                            accessxi.escape_probe_log_text(tostring(reason or ''))));
                    end
                end
            end
        end
    end

    log_state(('state friend-list name-buffer-end menu="%s" select=%d count=%d child=0x%08X emitted=%d capped=false'):fmt(
        tostring(menu_name or ''),
        selected,
        count,
        child,
        emitted));
end

function accessxi.log_friend_list_child_table_probe(menu_name, selected, count, child, entry, reason)
    if (not tostring(menu_name or ''):eq('menu    friend', true)) then
        return;
    end

    selected = tonumber(selected) or 0;
    count = tonumber(count) or 0;
    child = tonumber(child) or 0;
    entry = tonumber(entry) or 0;
    if (selected <= 0 or count <= 0 or not accessxi.is_probe_pointer(child)) then
        return;
    end

    local key = ('%s:%d:%d:0x%08X:0x%08X:%s'):fmt(
        tostring(menu_name or ''),
        selected,
        count,
        child,
        entry,
        tostring(reason or ''));
    if (key == tostring(accessxi.last_friend_list_child_table_probe_key or '')) then
        return;
    end
    accessxi.last_friend_list_child_table_probe_key = key;

    local max_lines = math.max(4, math.min(tonumber(accessxi.friend_list_child_table_probe_limit) or 28, 64));
    local emitted = 0;
    local max_index = math.max(8, math.min(count + 6, 28));
    for _, base in ipairs(T{ 0x60, 0x70, 0x80, 0x90, 0xA0, 0xB0, 0xC0 }) do
        for index = 0, max_index - 1 do
            if (emitted >= max_lines) then
                log_state(('state friend-list child-table-end menu="%s" select=%d count=%d child=0x%08X emitted=%d capped=true'):fmt(
                    tostring(menu_name or ''),
                    selected,
                    count,
                    child,
                    emitted));
                return;
            end

            local ptr = read_u32(child + base + (index * 4)) or 0;
            if (accessxi.friend_list_probe_pointer_allowed(ptr)) then
                local source = ('child+%03X[%02d]'):fmt(base, index);
                local names = accessxi.friend_list_name_buffer_summary(ptr, source);
                local selected_slot = (index == (selected - 1));
                if (names ~= '' or selected_slot) then
                    emitted = emitted + 1;
                    log_state(('state friend-list child-table menu="%s" select=%d count=%d child=0x%08X entry=0x%08X base=0x%03X index=%02d selectedSlot=%s ptr=0x%08X d="%s" names="%s" reason="%s"'):fmt(
                        tostring(menu_name or ''),
                        selected,
                        count,
                        child,
                        entry,
                        base,
                        index,
                        tostring(selected_slot),
                        ptr,
                        accessxi.escape_probe_log_text_wide(accessxi.format_probe_dwords(ptr, 0x00, 10)),
                        accessxi.escape_probe_log_text_wide(names),
                        accessxi.escape_probe_log_text(tostring(reason or ''))));
                end
            elseif (index == (selected - 1) and ptr ~= 0) then
                emitted = emitted + 1;
                log_state(('state friend-list child-table menu="%s" select=%d count=%d child=0x%08X entry=0x%08X base=0x%03X index=%02d selectedSlot=true ptr=0x%08X unreadable=true reason="%s"'):fmt(
                    tostring(menu_name or ''),
                    selected,
                    count,
                    child,
                    entry,
                    base,
                    index,
                    ptr,
                    accessxi.escape_probe_log_text(tostring(reason or ''))));
            end
        end
    end

    log_state(('state friend-list child-table-end menu="%s" select=%d count=%d child=0x%08X emitted=%d capped=false'):fmt(
        tostring(menu_name or ''),
        selected,
        count,
        child,
        emitted));
end

function accessxi.friend_list_compact_cell_probe(entry, selected)
    entry = tonumber(entry) or 0;
    selected = tonumber(selected) or 0;
    if (not accessxi.is_probe_pointer(entry) or selected <= 0) then
        return '';
    end

    local parent = read_u32(entry + 0x5C) or 0;
    local parts = T{};
    local seen = {};
    for delta = -8, 8 do
        local cell = entry + (delta * 0x68);
        if (accessxi.is_probe_pointer(cell) and seen[cell] ~= true and (read_u32(cell + 0x58) or 0) == cell) then
            seen[cell] = true;
            local cell_parent = read_u32(cell + 0x5C) or 0;
            local row_code = read_u32(cell + 0x38) or 0;
            local row_index = math.floor(row_code / 0x10000);
            local order = row_code % 0x10000;
            local texts = T{};
            for _, item in ipairs(accessxi.friend_list_dynamic_candidate_records(cell, 0x68, 4, ('cell%+d'):fmt(delta))) do
                local text = tostring(item.text or '');
                if (text ~= '') then
                    texts:append(('%s+%03X="%s"'):fmt(
                        tostring(item.kind or ''),
                        tonumber(item.offset) or 0,
                        accessxi.escape_probe_log_text(text)));
                end
            end
            parts:append(('d%+d ptr=0x%08X row=%d order=0x%04X match=%s parentMatch=%s text="%s"'):fmt(
                delta,
                cell,
                row_index,
                order,
                tostring(row_index == selected),
                tostring(parent ~= 0 and cell_parent == parent),
                accessxi.escape_probe_log_text(texts:concat(' | '))));
            if (#parts >= 12) then
                break;
            end
        end
    end
    return parts:concat(' || ');
end

function accessxi.log_friend_list_row_render_probe(menu_name, selected, count, entry, reason)
    if (not tostring(menu_name or ''):eq('menu    friend', true)) then
        return;
    end

    selected = tonumber(selected) or 0;
    count = tonumber(count) or 0;
    entry = tonumber(entry) or 0;
    if (selected <= 0 or not accessxi.is_probe_pointer(entry)) then
        return;
    end

    local row_rec = read_u32(entry + 0x0C) or 0;
    local row_window = accessxi.is_probe_pointer(row_rec) and (read_u32(row_rec + 0x00) or 0) or 0;
    local row_data = accessxi.is_probe_pointer(row_rec) and (read_u32(row_rec + 0x04) or 0) or 0;
    local key = ('%s:%d:%d:0x%08X:0x%08X:0x%08X:%s'):fmt(
        tostring(menu_name or ''),
        selected,
        count,
        entry,
        row_window,
        row_data,
        tostring(reason or ''));
    if (key == tostring(accessxi.last_friend_list_row_render_probe_key or '')) then
        return;
    end
    accessxi.last_friend_list_row_render_probe_key = key;

    local row_window_text = accessxi.friend_list_dynamic_text_probe(row_window, 0x280, 10);
    local row_data_text = accessxi.friend_list_dynamic_text_probe(row_data, 0x500, 16);
    local row_window_fragments = accessxi.friend_list_fragment_probe(row_window, 10);
    local row_data_fragments = accessxi.friend_list_fragment_probe(row_data, 12);
    local row_window_ptrs = accessxi.friend_list_pointer_text_targets(row_window);
    local row_data_ptrs = accessxi.friend_list_pointer_text_targets(row_data);

    log_state(('state friend-list row-render menu="%s" reason="%s" select=%d count=%d entry=0x%08X rowRec=0x%08X rowWindow=0x%08X rowData=0x%08X rowRecD="%s" rowWindowD="%s" rowDataD="%s" rowWindowText="%s" rowDataText="%s" rowWindowFragments="%s" rowDataFragments="%s" rowWindowPtrs="%s" rowDataPtrs="%s"'):fmt(
        tostring(menu_name or ''),
        accessxi.escape_probe_log_text(tostring(reason or '')),
        selected,
        count,
        entry,
        row_rec,
        row_window,
        row_data,
        accessxi.escape_probe_log_text_wide(accessxi.format_probe_dwords(row_rec, 0x00, 8)),
        accessxi.escape_probe_log_text_wide(accessxi.format_probe_dwords(row_window, 0x00, 16)),
        accessxi.escape_probe_log_text_wide(accessxi.format_probe_dwords(row_data, 0x00, 24)),
        accessxi.escape_probe_log_text_wide(row_window_text),
        accessxi.escape_probe_log_text_wide(row_data_text),
        accessxi.escape_probe_log_text_wide(row_window_fragments),
        accessxi.escape_probe_log_text_wide(row_data_fragments),
        accessxi.escape_probe_log_text_wide(row_window_ptrs),
        accessxi.escape_probe_log_text_wide(row_data_ptrs)));
end

function accessxi.log_friend_list_raw_row_probe(menu_name, selected, count, child, entry, reason)
    if (not tostring(menu_name or ''):eq('menu    friend', true)) then
        return;
    end

    selected = tonumber(selected) or 0;
    count = tonumber(count) or 0;
    child = tonumber(child) or 0;
    entry = tonumber(entry) or 0;
    if (selected <= 0 or not accessxi.is_probe_pointer(entry)) then
        return;
    end

    local key = ('%s:%d:%d:0x%08X:0x%08X:%s'):fmt(
        tostring(menu_name or ''),
        selected,
        count,
        child,
        entry,
        tostring(reason or ''));
    if (key == tostring(accessxi.last_friend_list_raw_row_probe_key or '')) then
        return;
    end
    accessxi.last_friend_list_raw_row_probe_key = key;

    accessxi.menu_dump_sequence = (tonumber(accessxi.menu_dump_sequence) or 0) + 1;
    local seq = tonumber(accessxi.menu_dump_sequence) or 0;
    local row_rec = read_u32(entry + 0x0C) or 0;
    local row_window = accessxi.is_probe_pointer(row_rec) and (read_u32(row_rec + 0x00) or 0) or 0;
    local row_data = accessxi.is_probe_pointer(row_rec) and (read_u32(row_rec + 0x04) or 0) or 0;
    local row_code = read_u32(entry + 0x38) or 0;
    local row_index = math.floor(row_code / 0x10000);
    local order = row_code % 0x10000;

    log_line(('menudump seq=%d friendraw begin menu="%s" reason="%s" select=%d count=%d child=0x%08X entry=0x%08X rowIndex=%d order=0x%04X rowRec=0x%08X rowWindow=0x%08X rowData=0x%08X'):fmt(
        seq,
        tostring(menu_name or ''),
        accessxi.escape_probe_log_text(tostring(reason or '')),
        selected,
        count,
        child,
        entry,
        row_index,
        order,
        row_rec,
        row_window,
        row_data));
    accessxi.log_probe_bytes(seq, 'friendraw.entry', entry, 0xE0);
    accessxi.log_probe_bytes(seq, 'friendraw.rowRec', row_rec, 0x80);
    accessxi.log_probe_bytes(seq, 'friendraw.rowWindow', row_window, 0x80);
    accessxi.log_probe_bytes(seq, 'friendraw.rowData', row_data, 0x160);
    if (accessxi.is_probe_pointer(child)) then
        accessxi.log_probe_bytes(seq, 'friendraw.child', child, 0xE0);
        for _, base in ipairs(T{ 0x60, 0x70, 0x80, 0x90, 0xA0, 0xA8, 0xB0, 0xC0 }) do
            local ptr = read_u32(child + base + ((selected - 1) * 4)) or 0;
            if (accessxi.is_probe_pointer(ptr)) then
                accessxi.log_probe_bytes(seq, ('friendraw.child%03X'):fmt(base), ptr, 0xC0);
            end
        end
    end
    log_line(('menudump seq=%d friendraw end'):fmt(seq));
end

function accessxi.log_friend_list_row_signature_probe(menu_name, title, obj, selected, count, page, raw, child, entry, ank_num, reason)
    if (not tostring(menu_name or ''):eq('menu    friend', true)) then
        return;
    end

    selected = tonumber(selected) or 0;
    entry = tonumber(entry) or 0;
    child = tonumber(child) or 0;
    obj = tonumber(obj) or 0;
    local row_rec = accessxi.is_probe_pointer(entry) and (read_u32(entry + 0x0C) or 0) or 0;
    local row_window = accessxi.is_probe_pointer(row_rec) and (read_u32(row_rec + 0x00) or 0) or 0;
    local row_data = accessxi.is_probe_pointer(row_rec) and (read_u32(row_rec + 0x04) or 0) or 0;
    local row_window_name = accessxi.is_probe_pointer(row_window) and clean_probe_text(read_probe_string(row_window + 0x24, 48)) or '';
    local parent = accessxi.is_probe_pointer(entry) and (read_u32(entry + 0x5C) or 0) or 0;
    local self = accessxi.is_probe_pointer(entry) and (read_u32(entry + 0x58) or 0) or 0;
    local row_code = accessxi.is_probe_pointer(entry) and (read_u32(entry + 0x38) or 0) or 0;
    local row_index = math.floor(row_code / 0x10000);
    local order = row_code % 0x10000;
    local label_ptr = accessxi.is_probe_pointer(entry) and (read_u32(entry + 0x44) or 0) or 0;
    local help_ptr = accessxi.is_probe_pointer(entry) and (read_u32(entry + 0x40) or 0) or 0;
    local surface = accessxi.is_probe_pointer(child) and (read_u32(child + 0x20) or 0) or 0;

    log_state(('state friend-list row-signature menu="%s" title="%s" reason="%s" select=%d count=%d page=%d raw=0x%08X rawLo=%d obj=0x%08X child=0x%08X entry=0x%08X self=0x%08X parent=0x%08X rowCode=0x%08X rowIndex=%d order=0x%04X rowRec=0x%08X rowWindow=0x%08X rowWindowName="%s" rowData=0x%08X surface=0x%08X ank=%d labelPtr=0x%08X label="%s" helpPtr=0x%08X help="%s" objCounts="%s" childFields="%s" entryFields="%s" rowDataD="%s" cells="%s"'):fmt(
        tostring(menu_name or ''),
        accessxi.escape_probe_log_text(tostring(title or '')),
        accessxi.escape_probe_log_text(tostring(reason or '')),
        selected,
        tonumber(count) or 0,
        tonumber(page) or 0,
        tonumber(raw) or 0,
        bit.band(tonumber(raw) or 0, 0xFFFF),
        obj,
        child,
        entry,
        self,
        parent,
        row_code,
        row_index,
        order,
        row_rec,
        row_window,
        accessxi.escape_probe_log_text(row_window_name),
        row_data,
        surface,
        tonumber(ank_num) or -1,
        label_ptr,
        accessxi.escape_probe_log_text(accessxi.plain_native_menu_label(read_probe_string(label_ptr, 180))),
        help_ptr,
        accessxi.escape_probe_log_text(accessxi.plain_native_menu_help(read_probe_string(help_ptr, 260))),
        accessxi.escape_probe_log_text(accessxi.format_probe_dwords(obj, 0x20, 18)),
        accessxi.escape_probe_log_text(accessxi.format_probe_dwords(child, 0x20, 18)),
        accessxi.escape_probe_log_text(accessxi.format_probe_dwords(entry, 0x00, 40)),
        accessxi.escape_probe_log_text(accessxi.format_probe_dwords(row_data, 0x00, 20)),
        accessxi.escape_probe_log_text_wide(accessxi.friend_list_compact_cell_probe(entry, selected))));
    accessxi.log_friend_list_row_render_probe(menu_name, selected, count, entry, reason);
    if ((tonumber(accessxi.friend_list_glyph_probe_until) or 0) >= tick()) then
        accessxi.log_friend_list_render_records_probe(menu_name, selected, count, entry, reason);
    end
end

function accessxi.log_friend_list_dynamic_probe(menu_name, title, obj, selected, count, page, raw, child, entry, reason)
    if (not tostring(menu_name or ''):eq('menu    friend', true)) then
        return;
    end
    if (not accessxi.friend_list_any_probe_active()) then
        return;
    end

    local target = AshitaCore:GetMemoryManager():GetTarget();
    local ank_num = target ~= nil and (tonumber(safe_call(function () return target:GetWindowAnkNum(); end, -1)) or -1) or -1;
    local key = ('%s:%d:%d:%d:0x%08X:0x%08X:0x%08X:0x%08X:%s'):fmt(
        tostring(menu_name or ''),
        tonumber(selected) or 0,
        tonumber(count) or 0,
        tonumber(page) or 0,
        tonumber(raw) or 0,
        tonumber(child) or 0,
        tonumber(entry) or 0,
        tonumber(obj) or 0,
        tostring(reason or ''));
    if (key == tostring(accessxi.last_friend_list_dynamic_probe_key or '')) then
        return;
    end
    accessxi.last_friend_list_dynamic_probe_key = key;

    if (true) then
        accessxi.log_friend_list_row_signature_probe(menu_name, title, obj, selected, count, page, raw, child, entry, ank_num, reason);
        if ((tonumber(accessxi.friend_list_raw_probe_until) or 0) >= tick()) then
            accessxi.log_friend_list_raw_row_probe(menu_name, selected, count, child, entry, reason);
        end
        if ((tonumber(accessxi.friend_list_table_probe_until) or 0) >= tick()) then
            accessxi.log_friend_list_child_table_probe(menu_name, selected, count, child, entry, reason);
        end
        if ((tonumber(accessxi.friend_list_name_buffer_probe_until) or 0) >= tick()) then
            accessxi.log_friend_list_name_buffer_probe(menu_name, selected, count, child, entry, reason);
        end
        if ((tonumber(accessxi.friend_list_dynamic_probe_until) or 0) >= tick()) then
            local probe_key = ('%s:%d:%d:0x%08X:0x%08X:%s'):fmt(
                tostring(menu_name or ''),
                tonumber(selected) or 0,
                tonumber(count) or 0,
                tonumber(child) or 0,
                tonumber(entry) or 0,
                tostring(reason or ''));
            if (probe_key ~= tostring(accessxi.last_friend_list_dynamic_child_probe_key or '')) then
                accessxi.last_friend_list_dynamic_child_probe_key = probe_key;
                log_state(('state friend-list child-row-probe menu="%s" select=%d count=%d child=0x%08X entry=0x%08X childRows="%s" glyphs="%s" rendered="%s" renderCells="%s" renderNeighbors="%s"'):fmt(
                    tostring(menu_name or ''),
                    tonumber(selected) or 0,
                    tonumber(count) or 0,
                    tonumber(child) or 0,
                    tonumber(entry) or 0,
                    accessxi.escape_probe_log_text_wide(accessxi.friend_list_child_row_pointer_probe(child, selected)),
                    accessxi.escape_probe_log_text_wide(accessxi.friend_list_selected_row_glyph_probe(child, entry, selected)),
                    accessxi.escape_probe_log_text(accessxi.search_result_rendered_row_text ~= nil and accessxi.search_result_rendered_row_text(entry, selected) or ''),
                    accessxi.escape_probe_log_text(tostring(accessxi.last_search_result_render_cells or '')),
                    accessxi.escape_probe_log_text_wide(accessxi.search_result_rendered_neighbor_summary ~= nil and accessxi.search_result_rendered_neighbor_summary(entry, selected) or '')));
                accessxi.log_friend_list_selected_row_glyph_targets(menu_name, child, entry, selected, count);
            end
        end
        return;
    end

    local label_ptr = accessxi.is_probe_pointer(entry) and (read_u32(entry + 0x44) or 0) or 0;
    local help_ptr = accessxi.is_probe_pointer(entry) and (read_u32(entry + 0x40) or 0) or 0;
    local row_rec = accessxi.is_probe_pointer(entry) and (read_u32(entry + 0x0C) or 0) or 0;
    local surface = accessxi.is_probe_pointer(child) and (read_u32(child + 0x20) or 0) or 0;
    local rendered_label = '';
    local rendered_cells = '';
    local rendered_neighbors = '';
    if (accessxi.search_result_rendered_row_text ~= nil) then
        rendered_label = accessxi.search_result_rendered_row_text(entry, selected);
        rendered_cells = tostring(accessxi.last_search_result_render_cells or '');
    end
    if (accessxi.search_result_rendered_neighbor_summary ~= nil) then
        rendered_neighbors = accessxi.search_result_rendered_neighbor_summary(entry, selected);
    end
    local child_row_candidates = accessxi.friend_list_child_row_pointer_probe(child, selected);
    log_state(('state friend-list dynamic-probe menu="%s" title="%s" reason="%s" select=%d count=%d page=%d raw=0x%08X rawLo=%d obj=0x%08X child=0x%08X entry=0x%08X rowRec=0x%08X labelPtr=0x%08X label="%s" helpPtr=0x%08X help="%s" surface=0x%08X ank=%d objD="%s" childD="%s" entryD00="%s" entryD40="%s" entryD80="%s" rowD00="%s" rowStrings="%s" rowRuns="%s" rowPtrs="%s" rowChain="%s" entryStrings="%s" entryRuns="%s" entryPtrs="%s" childStrings="%s" childRuns="%s" childPtrs="%s" surfaceStrings="%s" surfaceRuns="%s" shapes="%s"'):fmt(
        tostring(menu_name or ''),
        accessxi.escape_probe_log_text(tostring(title or '')),
        accessxi.escape_probe_log_text(tostring(reason or '')),
        tonumber(selected) or 0,
        tonumber(count) or 0,
        tonumber(page) or 0,
        tonumber(raw) or 0,
        bit.band(tonumber(raw) or 0, 0xFFFF),
        tonumber(obj) or 0,
        tonumber(child) or 0,
        tonumber(entry) or 0,
        row_rec,
        label_ptr,
        accessxi.escape_probe_log_text(accessxi.plain_native_menu_label(read_probe_string(label_ptr, 180))),
        help_ptr,
        accessxi.escape_probe_log_text(accessxi.plain_native_menu_help(read_probe_string(help_ptr, 260))),
        surface,
        ank_num,
        accessxi.escape_probe_log_text(accessxi.format_probe_dwords(obj, 0x00, 24)),
        accessxi.escape_probe_log_text(accessxi.format_probe_dwords(child, 0x00, 24)),
        accessxi.escape_probe_log_text(accessxi.format_probe_dwords(entry, 0x00, 24)),
        accessxi.escape_probe_log_text(accessxi.format_probe_dwords(entry, 0x40, 24)),
        accessxi.escape_probe_log_text(accessxi.format_probe_dwords(entry, 0x80, 16)),
        accessxi.escape_probe_log_text(accessxi.format_probe_dwords(row_rec, 0x00, 32)),
        accessxi.escape_probe_log_text(accessxi.status_menu_probe_inline_strings(row_rec)),
        accessxi.escape_probe_log_text(accessxi.status_menu_probe_runs(row_rec, 0x180)),
        accessxi.escape_probe_log_text(accessxi.status_menu_probe_pointer_fields(row_rec)),
        accessxi.escape_probe_log_text_wide(accessxi.friend_list_row_chain_probe(row_rec)),
        accessxi.escape_probe_log_text(accessxi.status_menu_probe_inline_strings(entry)),
        accessxi.escape_probe_log_text(accessxi.status_menu_probe_runs(entry, 0x180)),
        accessxi.escape_probe_log_text(accessxi.status_menu_probe_pointer_fields(entry)),
        accessxi.escape_probe_log_text(accessxi.status_menu_probe_inline_strings(child)),
        accessxi.escape_probe_log_text(accessxi.status_menu_probe_runs(child, 0x180)),
        accessxi.escape_probe_log_text(accessxi.status_menu_probe_pointer_fields(child)),
        accessxi.escape_probe_log_text(accessxi.status_menu_probe_inline_strings(surface)),
        accessxi.escape_probe_log_text(accessxi.status_menu_probe_runs(surface, 0x180)),
        accessxi.escape_probe_log_text_wide(accessxi.friend_list_dynamic_shape_probe(target, ank_num))));
    log_state(('state friend-list dynamic-row-sources menu="%s" select=%d count=%d child=0x%08X entry=0x%08X renderedLabel="%s" renderedCells="%s" renderedNeighbors="%s" childRows="%s"'):fmt(
        tostring(menu_name or ''),
        selected,
        tonumber(count) or 0,
        tonumber(child) or 0,
        tonumber(entry) or 0,
        accessxi.escape_probe_log_text(rendered_label),
        accessxi.escape_probe_log_text(rendered_cells),
        accessxi.escape_probe_log_text_wide(rendered_neighbors),
        accessxi.escape_probe_log_text_wide(child_row_candidates)));
end

function accessxi.ability_category_label_is_supported(label)
    label = tostring(label or '');
    return label:eq('Job Traits', true)
        or label:eq('Job Abilities', true)
        or label:eq('Weapon Skills', true)
        or label:eq('Ranged Attack', true)
        or label:eq('Pet Commands', true)
        or label:eq('Mounts', true)
        or accessxi.ability_dancer_category_label_is_supported(label);
end

function accessxi.chatctrl_dat_label_for_selection(selected, count)
    selected = tonumber(selected) or 0;
    count = tonumber(count) or 0;
    if (selected <= 0 or count ~= 10) then
        return '', '';
    end

    local dat_rows = {
        [1] = 0,   -- Say
        [2] = 2,   -- Tell
        [3] = 3,   -- Party
        [4] = 4,   -- Linkshell
        [5] = 5,   -- Linkshell 2
        [6] = 8,   -- Unity
        [7] = 1,   -- Shout
    };
    local dat_row = tonumber(dat_rows[selected]) or -1;
    if (dat_row < 0) then
        return '', '';
    end

    local label = accessxi.dat_index_row_text('ROM\\165\\74.DAT', dat_row, 'label');
    if (label == '') then
        return '', '';
    end
    return label, ('dat:ROM\\165\\74.DAT:%d'):fmt(dat_row);
end

function accessxi.player_command_submenu_speech(menu_name, title, obj, selected, count, page, raw, child, entry)
    menu_name = tostring(menu_name or '');
    title = tostring(title or '');
    selected = tonumber(selected) or 0;
    count = tonumber(count) or 0;

    if (selected <= 0) then
        selected = read_current_native_menu_index(0x4C);
    end
    if (count <= 0 or count > 64) then
        count = math.max(tonumber(accessxi.native_menu_index(0x24)) or 0, tonumber(accessxi.native_menu_index(0x28)) or 0);
    end
    if (selected <= 0 or count <= 0) then
        return nil;
    end

    local label = '';
    local description = '';
    local row2 = 0;
    local label_source = '';

    if (menu_name:eq('menu    magselec', true) or menu_name:eq('menu    abiselec', true)) then
        description, row2 = accessxi.status_menu_native_description_for_entry(entry);
        if (description ~= '') then
            local description_label = '';
            if (menu_name:eq('menu    magselec', true)) then
                description_label = accessxi.magic_menu_label_from_description(description);
            else
                description_label = accessxi.ability_menu_label_from_description(description);
            end
            if (label == '' and description_label ~= '') then
                label = description_label;
                label_source = 'native-description';
            end
        end
    elseif (accessxi.is_probe_pointer(child) and accessxi.native_query_label_for_selection ~= nil) then
        local queried_label, queried_mode = accessxi.native_query_label_for_selection(child, selected, count, 'plain');
        queried_label = accessxi.plain_native_menu_label(queried_label or '');
        if (queried_label ~= '') then
            label = queried_label;
            label_source = tostring(queried_mode or 'native-query');
        end
    end

    if (label == '' and menu_name:eq('menu    chatctrl', true)) then
        label, label_source = accessxi.chatctrl_dat_label_for_selection(selected, count);
    end

    if (label == '') then
        log_state(('state nativemenu player-submenu-missing menu="%s" title="%s" select=%d count=%d page=%d raw=0x%08X obj=0x%08X child=0x%08X entry=0x%08X row2=0x%08X desc="%s" note="no native label; no fallback"'):fmt(
            menu_name,
            title,
            selected,
            count,
            tonumber(page) or 0,
            tonumber(raw) or 0,
            tonumber(obj) or 0,
            tonumber(child) or 0,
            tonumber(entry) or 0,
            tonumber(row2) or 0,
            accessxi.escape_probe_log_text(description)));
        return nil;
    end

    local category_label = '';
    if (menu_name:eq('menu    magselec', true)) then
        if (accessxi.magic_category_type(label) <= 0) then
            log_state(('state nativemenu player-submenu-reject menu="%s" title="%s" select=%d count=%d label="%s" source="%s" note="native label is not a supported magic category"'):fmt(
                menu_name,
                title,
                selected,
                count,
                accessxi.escape_probe_log_text(label),
                accessxi.escape_probe_log_text(label_source)));
            return nil;
        end
        accessxi.last_magic_category_label = label;
        accessxi.current_magic_category_label = label;
        accessxi.magic_known_cache = nil;
        accessxi.magic_known_cache_key = '';
        accessxi.magic_known_cache_type = 0;
        accessxi.magic_known_cache_tick = 0;
        category_label = label;
    elseif (menu_name:eq('menu    abiselec', true)) then
        if (not accessxi.ability_category_label_is_supported(label)) then
            log_state(('state nativemenu player-submenu-reject menu="%s" title="%s" select=%d count=%d label="%s" source="%s" note="native label is not a supported ability category"'):fmt(
                menu_name,
                title,
                selected,
                count,
                accessxi.escape_probe_log_text(label),
                accessxi.escape_probe_log_text(label_source)));
            return nil;
        end
        accessxi.last_ability_category_label = label;
        accessxi.current_ability_category_label = label;
        accessxi.ability_shortcut_active_category_label = label;
        category_label = label;
    end

    local spoken = label;
    if (description ~= '' and (menu_name:eq('menu    magselec', true) or menu_name:eq('menu    abiselec', true))) then
        spoken = ('%s. %s'):fmt(label, description);
    end

    accessxi.last_native_menu_name = menu_name;
    accessxi.last_native_menu_label = spoken;
    accessxi.last_native_menu_selected = selected;
    accessxi.last_native_menu_tick = tick();
    accessxi.current_speech_key = ('native-known-player-submenu:%s:%d:%d:0x%08X:%s:%s'):fmt(
        menu_name,
        selected,
        count,
        tonumber(entry) or 0,
        label_source,
        spoken);
    log_state(('state nativemenu player-submenu menu="%s" title="%s" select=%d count=%d page=%d raw=0x%08X obj=0x%08X child=0x%08X entry=0x%08X row2=0x%08X label="%s" category="%s" source="%s" text="%s"'):fmt(
        menu_name,
        title,
        selected,
        count,
        tonumber(page) or 0,
        tonumber(raw) or 0,
        tonumber(obj) or 0,
        tonumber(child) or 0,
        tonumber(entry) or 0,
        tonumber(row2) or 0,
        accessxi.escape_probe_log_text(label),
        accessxi.escape_probe_log_text(category_label),
        accessxi.escape_probe_log_text(label_source),
        accessxi.escape_probe_log_text(spoken)));
    return ('%s. %s'):fmt(title, accessxi.sentence_fragment(spoken));
end

