function accessxi.alter_ego_points_category_entry(selected)
    selected = math.floor(tonumber(selected) or 0);
    return accessxi.alter_ego_points_category_rows[selected];
end

function accessxi.alter_ego_points_subcategory_entry(category_id, selected)
    category_id = math.floor(tonumber(category_id) or 0);
    selected = math.floor(tonumber(selected) or 0);
    local category = accessxi.alter_ego_points_subcategory_rows_by_category[category_id];
    if (category == nil or category.rows == nil) then
        return nil, nil, 0;
    end
    return category.rows[selected], category, category.rows:len();
end

function accessxi.current_alter_ego_points_category_id()
    local category_id = math.floor(tonumber(accessxi.alter_ego_points_category_id) or 0);
    local category_tick = tonumber(accessxi.alter_ego_points_category_tick) or 0;
    if (category_id < 1 or category_id > 3 or (tick() - category_tick) > 120000) then
        return 0;
    end
    return category_id;
end

function accessxi.current_alter_ego_points_subcategory_context()
    local now = tick();
    local category_id = math.floor(tonumber(accessxi.alter_ego_points_subcategory_category_id) or 0);
    local selected = math.floor(tonumber(accessxi.alter_ego_points_subcategory_id) or 0);
    local label = tostring(accessxi.alter_ego_points_subcategory_label or '');
    local category_label = tostring(accessxi.alter_ego_points_subcategory_category_label or '');
    local help = tostring(accessxi.alter_ego_points_subcategory_help or '');
    local source = tostring(accessxi.alter_ego_points_subcategory_source or '');
    local age = now - (tonumber(accessxi.alter_ego_points_subcategory_tick) or 0);
    if (category_id < 1 or category_id > 3 or selected <= 0 or label == '' or age < 0 or age > 120000) then
        return nil, 'missing-subcategory-context';
    end

    local transition_age = now - (tonumber(accessxi.last_menu_transition_tick) or 0);
    local transition_from = tostring(accessxi.last_menu_transition_from or '');
    local transition_to = tostring(accessxi.last_menu_transition_to or '');
    if (transition_age < 0 or transition_age > 120000
        or not transition_from:eq('menu    fp_cat2', true)
        or not transition_to:eq('menu    merityn', true)) then
        return nil, 'wrong-transition';
    end

    local row = accessxi.alter_ego_points_subcategory_entry(category_id, selected);
    if (row == nil or tostring(row.label or '') ~= label) then
        return nil, 'stale-subcategory-context';
    end

    return {
        category_id = category_id,
        selected = selected,
        label = label,
        category_label = category_label,
        help = help,
        source = source,
        age = age,
        transition_age = transition_age,
        transition_from = transition_from,
        transition_to = transition_to,
    }, '';
end

function accessxi.alter_ego_points_category_speech(menu_name, title, obj, selected, count, page, raw, child, entry)
    menu_name = tostring(menu_name or '');
    title = tostring(title or '');
    if (title == '') then
        title = 'Alter Ego Points';
    end
    obj = tonumber(obj) or 0;

    local child_selected, child_page, child_raw, child_ptr, child_count = accessxi.survival_guide_query_child_state_for_obj(obj);
    child_selected = tonumber(child_selected) or 0;
    child_count = tonumber(child_count) or 0;
    child_page = tonumber(child_page) or 0;
    child_raw = tonumber(child_raw) or 0;
    child_ptr = tonumber(child_ptr) or 0;

    local native_selected = math.floor(tonumber(selected) or 0);
    local native_count = tonumber(count) or 0;
    local effective_selected = 0;
    local cursor_source = '';
    if (child_count == 3 and child_selected >= 1 and child_selected <= 3) then
        effective_selected = child_selected;
        cursor_source = 'child-list';
    elseif (native_selected >= 1 and native_selected <= 3) then
        effective_selected = native_selected;
        cursor_source = 'native-cursor4c';
    end

    if (effective_selected < 1 or effective_selected > 3) then
        log_state(('state nativemenu alterego-categories quiet menu="%s" title="%s" selected=%d count=%d page=%d raw=0x%08X obj=0x%08X child=0x%08X entry=0x%08X fallbackSelected=%d fallbackCount=%d reason="unverified-cursor" prompt="%s" promptSource="%s"'):fmt(
            menu_name,
            title,
            child_selected,
            child_count,
            child_page,
            child_raw,
            obj,
            child_ptr,
            tonumber(entry) or 0,
            native_selected,
            native_count,
            accessxi.escape_probe_log_text(accessxi.alter_ego_points_category_prompt.text),
            accessxi.escape_probe_log_text(accessxi.alter_ego_points_category_prompt.source)));
        return nil;
    end

    local row = accessxi.alter_ego_points_category_entry(effective_selected);
    if (row == nil or tostring(row.label or '') == '') then
        return nil;
    end

    local label = tostring(row.label or '');
    local help = tostring(row.help or '');
    local source = tostring(row.source or '');
    local prompt = tostring(accessxi.alter_ego_points_category_prompt.text or '');
    local prompt_source = tostring(accessxi.alter_ego_points_category_prompt.source or '');
    local speech_parts = T{ label };
    if (help ~= '') then
        speech_parts:append(help);
    end
    local spoken = accessxi.sentence_fragment(speech_parts:concat('. '));

    accessxi.alter_ego_points_category_id = effective_selected;
    accessxi.alter_ego_points_category_label = label;
    accessxi.alter_ego_points_category_tick = tick();
    accessxi.last_native_menu_name = menu_name;
    accessxi.last_native_menu_label = spoken;
    accessxi.last_native_menu_selected = effective_selected;
    accessxi.last_native_menu_tick = tick();
    accessxi.current_speech_key = ('native-known-alterego-cat:%s:%d:%s:%s:%s'):fmt(
        menu_name,
        effective_selected,
        cursor_source,
        label,
        help);
    log_state(('state nativemenu alterego-categories menu="%s" title="%s" select=%d count=3 cursorSource="%s" childSelect=%d childCount=%d nativeSelect=%d nativeCount=%d page=%d raw=0x%08X obj=0x%08X child=0x%08X entry=0x%08X label="%s" help="%s" source="%s" prompt="%s" promptSource="%s"'):fmt(
        menu_name,
        title,
        effective_selected,
        cursor_source,
        child_selected,
        child_count,
        native_selected,
        native_count,
        child_page,
        child_raw,
        obj,
        child_ptr,
        tonumber(entry) or 0,
        accessxi.escape_probe_log_text(label),
        accessxi.escape_probe_log_text(help),
        accessxi.escape_probe_log_text(source),
        accessxi.escape_probe_log_text(prompt),
        accessxi.escape_probe_log_text(prompt_source)));
    return ('%s. %s'):fmt(title, spoken);
end

function accessxi.alter_ego_points_subcategory_speech(menu_name, title, obj, selected, count, page, raw, child, entry)
    menu_name = tostring(menu_name or '');
    title = tostring(title or '');
    if (title == '') then
        title = 'Alter Ego Points';
    end

    local category_id = accessxi.current_alter_ego_points_category_id();
    local selected_index = math.floor(tonumber(selected) or 0);
    local native_count = tonumber(count) or 0;
    local category_label = tostring(accessxi.alter_ego_points_category_label or '');
    if (category_id <= 0) then
        log_state(('state nativemenu alterego-subcategories quiet menu="%s" title="%s" select=%d count=%d obj=0x%08X child=0x%08X entry=0x%08X reason="missing-category-context" lastCategory=%d lastLabel="%s"'):fmt(
            menu_name,
            title,
            selected_index,
            native_count,
            tonumber(obj) or 0,
            tonumber(child) or 0,
            tonumber(entry) or 0,
            tonumber(accessxi.alter_ego_points_category_id) or 0,
            accessxi.escape_probe_log_text(category_label)));
        return nil;
    end

    local row, category, row_count = accessxi.alter_ego_points_subcategory_entry(category_id, selected_index);
    if (row == nil or tostring(row.label or '') == '') then
        log_state(('state nativemenu alterego-subcategories quiet menu="%s" title="%s" categoryId=%d category="%s" select=%d count=%d obj=0x%08X child=0x%08X entry=0x%08X reason="unverified-subcategory-cursor"'):fmt(
            menu_name,
            title,
            category_id,
            accessxi.escape_probe_log_text(category_label),
            selected_index,
            native_count,
            tonumber(obj) or 0,
            tonumber(child) or 0,
            tonumber(entry) or 0));
        return nil;
    end

    local subcategory_title = tostring(category.title or category_label or '');
    local label = tostring(row.label or '');
    local help = tostring(row.help or '');
    local source = tostring(row.source or '');
    local speech_parts = T{};
    if (subcategory_title ~= '') then
        speech_parts:append(subcategory_title);
    end
    speech_parts:append(label);
    if (help ~= '') then
        speech_parts:append(help);
    end
    local spoken = accessxi.sentence_fragment(speech_parts:concat('. '));

    accessxi.last_native_menu_name = menu_name;
    accessxi.last_native_menu_label = spoken;
    accessxi.last_native_menu_selected = selected_index;
    accessxi.last_native_menu_tick = tick();
    accessxi.alter_ego_points_subcategory_id = selected_index;
    accessxi.alter_ego_points_subcategory_label = label;
    accessxi.alter_ego_points_subcategory_help = help;
    accessxi.alter_ego_points_subcategory_source = source;
    accessxi.alter_ego_points_subcategory_category_id = category_id;
    accessxi.alter_ego_points_subcategory_category_label = subcategory_title;
    accessxi.alter_ego_points_subcategory_tick = tick();
    accessxi.current_speech_key = ('native-known-alterego-subcat:%s:%d:%d:%d:%s:%s'):fmt(
        menu_name,
        category_id,
        selected_index,
        row_count,
        label,
        help);
    log_state(('state nativemenu alterego-subcategories menu="%s" title="%s" categoryId=%d category="%s" select=%d count=%d nativeCount=%d obj=0x%08X child=0x%08X entry=0x%08X label="%s" help="%s" source="%s"'):fmt(
        menu_name,
        title,
        category_id,
        accessxi.escape_probe_log_text(subcategory_title),
        selected_index,
        row_count,
        native_count,
        tonumber(obj) or 0,
        tonumber(child) or 0,
        tonumber(entry) or 0,
        accessxi.escape_probe_log_text(label),
        accessxi.escape_probe_log_text(help),
        accessxi.escape_probe_log_text(source)));
    return ('%s. %s'):fmt(title, spoken);
end

function accessxi.alter_ego_points_confirmation_speech(menu_name, title, selected, count, entry)
    menu_name = tostring(menu_name or '');
    if (not menu_name:eq('menu    merityn', true)) then
        return nil;
    end

    selected = math.floor(tonumber(selected) or 0);
    count = tonumber(count) or 0;
    entry = tonumber(entry) or 0;

    local context, reason = accessxi.current_alter_ego_points_subcategory_context();
    if (context == nil) then
        log_state(('state nativemenu alterego-confirmation quiet menu="%s" title="%s" select=%d count=%d entry=0x%08X reason="%s" defaultReason="missing-subcategory-context" lastCategory=%d lastSubcategory=%d lastLabel="%s" transitionFrom="%s" transitionTo="%s"'):fmt(
            menu_name,
            tostring(title or ''),
            selected,
            count,
            entry,
            tostring(reason or 'missing-subcategory-context'),
            tonumber(accessxi.alter_ego_points_subcategory_category_id) or 0,
            tonumber(accessxi.alter_ego_points_subcategory_id) or 0,
            accessxi.escape_probe_log_text(accessxi.alter_ego_points_subcategory_label or ''),
            accessxi.escape_probe_log_text(accessxi.last_menu_transition_from or ''),
            accessxi.escape_probe_log_text(accessxi.last_menu_transition_to or '')));
        return nil;
    end

    local choice = '';
    if (selected == 1) then
        choice = 'Yes';
    elseif (selected == 2) then
        choice = 'No';
    else
        log_state(('state nativemenu alterego-confirmation unsupported-row menu="%s" title="%s" select=%d count=%d entry=0x%08X categoryId=%d category="%s" option="%s" optionHelp="%s"'):fmt(
            menu_name,
            tostring(title or ''),
            selected,
            count,
            entry,
            tonumber(context.category_id) or 0,
            accessxi.escape_probe_log_text(context.category_label or ''),
            accessxi.escape_probe_log_text(context.label or ''),
            accessxi.escape_probe_log_text(context.help or '')));
        return nil;
    end

    local prompt = ('Use 1 alter ego point to raise your "%s" by one level?'):fmt(tostring(context.label or ''));
    local prompt_source = 'dat:ROM\\97\\38.DAT:123';
    local choice_source = 'ROM\\97\\37.DAT#106-107';

    accessxi.last_native_menu_name = menu_name;
    accessxi.last_native_menu_label = choice;
    accessxi.last_native_menu_selected = selected;
    accessxi.last_native_menu_tick = tick();
    accessxi.current_speech_key = ('native-known-alterego-confirmation:%s:%d:%d:0x%08X:%d:%d:%s:%s'):fmt(
        menu_name,
        selected,
        count,
        entry,
        tonumber(context.category_id) or 0,
        tonumber(context.selected) or 0,
        tostring(context.label or ''),
        choice);
    log_state(('state nativemenu alterego-confirmation-dat menu="%s" title="%s" select=%d count=%d entry=0x%08X choice="%s" prompt="%s" categoryId=%d category="%s" optionId=%d option="%s" optionHelp="%s" optionSource="%s" promptSource="%s; %s" transitionFrom="%s" transitionAge=%d"'):fmt(
        menu_name,
        tostring(title or ''),
        selected,
        count,
        entry,
        choice,
        accessxi.escape_probe_log_text(prompt),
        tonumber(context.category_id) or 0,
        accessxi.escape_probe_log_text(context.category_label or ''),
        tonumber(context.selected) or 0,
        accessxi.escape_probe_log_text(context.label or ''),
        accessxi.escape_probe_log_text(context.help or ''),
        accessxi.escape_probe_log_text(context.source or ''),
        prompt_source,
        choice_source,
        accessxi.escape_probe_log_text(context.transition_from or ''),
        tonumber(context.transition_age) or 0));
    return accessxi.sentence_fragment(('Alter Ego Points. %s. %s'):fmt(choice, prompt));
end

function accessxi.item_sort_menu_speech(menu_name, title, obj, selected, count, page, raw, child, entry)
    menu_name = tostring(menu_name or '');
    if (not menu_name:eq('menu    itmsort2', true)
        and not menu_name:eq('menu    blusortw', true)
        and not menu_name:eq('menu    mgcsortw', true)) then
        return nil;
    end

    title = accessxi.plain_native_menu_label(title or '');
    if (title == '') then
        title = 'Sort';
    end
    obj = tonumber(obj) or 0;
    child = tonumber(child) or 0;
    entry = tonumber(entry) or 0;
    selected = tonumber(selected) or 0;
    count = tonumber(count) or 0;
    page = tonumber(page) or 0;
    raw = tonumber(raw) or 0;

    if (selected <= 0) then
        selected = read_current_native_menu_index(0x4C);
    end
    if (count <= 0 or count > 64) then
        count = math.max(tonumber(accessxi.native_menu_index(0x24)) or 0, tonumber(accessxi.native_menu_index(0x28)) or 0);
    end

    local is_magic_sort_menu = (menu_name:eq('menu    blusortw', true)
        or menu_name:eq('menu    mgcsortw', true));
    if (is_magic_sort_menu) then
        accessxi.current_blue_magic_sort_category_label = accessxi.magic_current_category_label();
        accessxi.current_blue_magic_sort_category_tick = tick();
    end

    local label = '';
    local label_source = '';
    local query_mode = '';
    if (accessxi.is_probe_pointer(child)
        and selected > 0
        and count > 0
        and count <= 64
        and selected <= count
        and accessxi.native_query_label_for_selection ~= nil) then
        label, query_mode = accessxi.native_query_label_for_selection(child, selected, count, 'plain');
        label = accessxi.plain_native_menu_label(label or '');
        if (label ~= '') then
            label_source = ('native-query:%s'):fmt(tostring(query_mode or ''));
        end
    end

    local label_ptr = accessxi.is_probe_pointer(entry) and (read_u32(entry + 0x44) or 0) or 0;
    local help_ptr = accessxi.is_probe_pointer(entry) and (read_u32(entry + 0x40) or 0) or 0;
    local entry_label = accessxi.plain_native_menu_label(read_probe_string(label_ptr, 160));
    local help = accessxi.plain_native_menu_help(read_probe_string(help_ptr, 260));
    local help_source = help ~= '' and 'entry+40' or '';
    if (label == '' and entry_label ~= '') then
        label = entry_label;
        label_source = 'entry+44';
    end

    if (label == '') then
        accessxi.current_item_sort_label = '';
        accessxi.current_item_sort_help = '';
        accessxi.current_item_sort_title = '';
        accessxi.current_item_sort_selected = 0;
        accessxi.current_item_sort_tick = 0;
        log_state(('state nativemenu item-sort-native-missing menu="%s" title="%s" select=%d count=%d page=%d raw=0x%08X obj=0x%08X child=0x%08X entry=0x%08X labelPtr=0x%08X helpPtr=0x%08X entryLabel="%s" help="%s" mode="%s" note="dynamic item sort menu; no fixed-row fallback"'):fmt(
            menu_name,
            title,
            selected,
            count,
            page,
            raw,
            obj,
            child,
            entry,
            label_ptr,
            help_ptr,
            accessxi.escape_probe_log_text(entry_label),
            accessxi.escape_probe_log_text(help),
            accessxi.escape_probe_log_text(tostring(query_mode or ''))));
        return nil;
    end

    local speech_parts = T{ title, label };
    if (help ~= '' and not help:eq(label, true)) then
        speech_parts:append(help);
    end
    local speech = accessxi.speech_output_text(speech_parts:concat('. '));
    if (speech == '') then
        return nil;
    end

    accessxi.last_native_menu_name = menu_name;
    accessxi.last_native_menu_label = label;
    accessxi.last_native_menu_selected = selected;
    accessxi.last_native_menu_tick = tick();
    accessxi.current_item_sort_label = label;
    accessxi.current_item_sort_help = help;
    accessxi.current_item_sort_title = title;
    accessxi.current_item_sort_selected = selected;
    accessxi.current_item_sort_tick = tick();
    accessxi.current_speech_key = ('native-itemsort:%s:%d:%d:0x%08X:0x%08X:%s:%s:%s'):fmt(
        menu_name,
        selected,
        count,
        label_ptr,
        help_ptr,
        label_source,
        label,
        help);
    log_state(('state nativemenu item-sort-native menu="%s" title="%s" select=%d count=%d page=%d raw=0x%08X obj=0x%08X child=0x%08X entry=0x%08X labelPtr=0x%08X helpPtr=0x%08X label="%s" entryLabel="%s" help="%s" labelSource="%s" helpSource="%s" mode="%s"'):fmt(
        menu_name,
        title,
        selected,
        count,
        page,
        raw,
        obj,
        child,
        entry,
        label_ptr,
        help_ptr,
        accessxi.escape_probe_log_text(label),
        accessxi.escape_probe_log_text(entry_label),
        accessxi.escape_probe_log_text(help),
        accessxi.escape_probe_log_text(label_source),
        accessxi.escape_probe_log_text(help_source),
        accessxi.escape_probe_log_text(tostring(query_mode or ''))));
    return speech;
end

function accessxi.blue_magic_set_clean_native_label(label)
    label = accessxi.plain_native_menu_label(label or ''):gsub('%s+', ' '):trim();
    if (label == '') then
        return '';
    end

    if (label:eq('(Remove All)', true) or label:eq('Remove All', true)) then
        return '(Remove All)';
    end

    local cleaned = label:gsub('^%s*[%[%(%{]?%d%d?[%]%)}]?[%s:%.-]+', ''):gsub('%s+', ' '):trim();
    if (cleaned ~= '' and not cleaned:match('^%d%d%d')) then
        return cleaned;
    end
    return label;
end

function accessxi.blue_magic_spell_from_exact_label(label)
    label = accessxi.blue_magic_set_clean_native_label(label or '');
    if (label == '' or label:eq('(Remove All)', true)) then
        return nil, 0, 'empty';
    end

    local spells = accessxi.magic_known_spell_list_for_category('Blue Magic');
    local matches = T{};
    if (spells ~= nil) then
        for _, spell in ipairs(spells) do
            if (label:eq(spell.name or '', true)) then
                matches:append(spell);
            end
        end
    end

    if (matches:len() == 1) then
        return matches[1], matches:len(), 'known-blue-exact';
    end
    return nil, matches:len(), matches:len() > 1 and 'known-blue-ambiguous' or 'known-blue-missing';
end

function accessxi.blue_magic_inventory_native_entry_segments(entry, selected)
    entry = tonumber(entry) or 0;
    selected = tonumber(selected) or 0;
    if (not accessxi.is_probe_pointer(entry) or selected <= 0) then
        return T{}, '';
    end

    local cells = accessxi.magic_rendered_row_cells(entry, selected, 16, true);
    local segments = T{};
    local details = T{};
    local seen = {};

    local function add_segment(source, ptr, offset, text)
        text = accessxi.magic_spell_description_text(text or '');
        if (text == '' or #text < 16) then
            return;
        end
        if (text:match('^Job Trait:') ~= nil or text:find('menu    ', 1, true) ~= nil) then
            return;
        end

        local key = text:lower();
        if (seen[key] == true) then
            return;
        end
        seen[key] = true;
        segments:append(T{
            source = tostring(source or ''),
            ptr = tonumber(ptr) or 0,
            offset = tonumber(offset) or 0,
            text = text,
        });
        details:append(('%s@0x%08X+%03X="%s"'):fmt(
            tostring(source or ''),
            tonumber(ptr) or 0,
            tonumber(offset) or 0,
            accessxi.escape_probe_log_text(text)));
    end

    local function scan_ascii_runs(source, ptr)
        ptr = tonumber(ptr) or 0;
        if (not accessxi.is_probe_pointer(ptr)) then
            return;
        end

        local run = T{};
        local run_start = 0;
        for off = 0, 0x240 do
            local byte_value = off < 0x240 and read_u8(ptr + off) or nil;
            if (byte_value ~= nil and accessxi.probe_printable_ascii(byte_value)) then
                if (#run == 0) then
                    run_start = off;
                end
                run:append(string.char(byte_value));
            else
                if (#run >= 8) then
                    add_segment(source, ptr, run_start, run:concat(''));
                end
                run = T{};
            end
        end
    end

    for _, cell in ipairs(cells) do
        local ptr = tonumber(cell.ptr) or 0;
        if (accessxi.is_probe_pointer(ptr)) then
            add_segment('rendered-cell', ptr, tonumber(cell.order) or 0, cell.text or '');
            scan_ascii_runs('native-entry-ascii', ptr);
            if (accessxi.collect_probe_ffxi_utf16_entries ~= nil) then
                for _, item in ipairs(accessxi.collect_probe_ffxi_utf16_entries(ptr, 0x240, 8, 16)) do
                    add_segment('native-entry-ffxi16', ptr, tonumber(item.offset) or 0, item.text or '');
                end
            end
        end
    end

    return segments, details:concat(' | ');
end

function accessxi.blue_magic_inventory_detail_match_score(segment_text, spell)
    local detail = accessxi.magic_spell_description_text(segment_text or '');
    local description = accessxi.magic_spell_description_text(spell ~= nil and spell.description or '');
    if (detail == '' or description == '' or #detail < 16 or #description < 16) then
        return 0;
    end

    local detail_lower = detail:lower();
    local description_lower = description:lower();
    if (detail_lower == description_lower) then
        return #description + 100;
    end
    if (#detail >= 24 and description_lower:find(detail_lower, 1, true) ~= nil) then
        return #detail;
    end
    if (#description >= 24 and detail_lower:find(description_lower, 1, true) ~= nil) then
        return #description;
    end
    return 0;
end

function accessxi.blue_magic_inventory_spell_from_native_entry(entry, selected)
    local segments, details = accessxi.blue_magic_inventory_native_entry_segments(entry, selected);
    if (segments:len() == 0) then
        return nil, 0, 'native-entry-empty', details, '', 0, 0;
    end

    local player = safe_call(function () return AshitaCore:GetMemoryManager():GetPlayer(); end, nil);
    local spells = accessxi.magic_known_spell_list_for_category('Blue Magic');
    local best_spell = nil;
    local best_segment = nil;
    local best_score = 0;
    local best_count = 0;
    local match_count = 0;
    local second_score = 0;

    for _, spell in ipairs(spells or T{}) do
        if (spell ~= nil and tonumber(spell.type) == 6
            and (player == nil or safe_call(function () return player:HasSpell(spell.id); end, false) == true)) then
            local spell_score = 0;
            local spell_segment = nil;
            for _, segment in ipairs(segments) do
                local score = accessxi.blue_magic_inventory_detail_match_score(segment.text or '', spell);
                if (score > spell_score) then
                    spell_score = score;
                    spell_segment = segment;
                end
            end

            if (spell_score > 0) then
                match_count = match_count + 1;
                if (spell_score > best_score) then
                    second_score = best_score;
                    best_score = spell_score;
                    best_count = 1;
                    best_spell = spell;
                    best_segment = spell_segment;
                elseif (spell_score == best_score) then
                    best_count = best_count + 1;
                elseif (spell_score > second_score) then
                    second_score = spell_score;
                end
            end
        end
    end

    if (best_spell ~= nil and best_count == 1 and best_score >= 24 and second_score == 0) then
        return best_spell, best_count, 'native-entry-details', details, best_segment ~= nil and tostring(best_segment.text or '') or '', best_score, second_score;
    end

    if (match_count > 1 or best_count > 1) then
        return nil, match_count, 'ambiguous-native-entry', details, best_segment ~= nil and tostring(best_segment.text or '') or '', best_score, second_score;
    end
    return nil, match_count, 'native-entry-missing', details, '', best_score, second_score;
end

function accessxi.blue_magic_set_log_missing(menu_name, title, selected, count, page, raw, obj, child, entry, labels, reason)
    labels = labels or T{};
    local label_text = T{};
    for _, item in ipairs(labels) do
        label_text:append(('%s="%s"'):fmt(
            accessxi.escape_probe_log_text(item.source or ''),
            accessxi.escape_probe_log_text(item.label or '')));
    end

    local key = ('%s:%d:%d:%08X:%08X:%08X:%s:%s'):fmt(
        tostring(menu_name or ''),
        tonumber(selected) or 0,
        tonumber(count) or 0,
        tonumber(obj) or 0,
        tonumber(child) or 0,
        tonumber(entry) or 0,
        tostring(reason or ''),
        label_text:concat('|'));
    if (key == tostring(accessxi.last_blue_magic_set_missing_key or '')) then
        return;
    end
    accessxi.last_blue_magic_set_missing_key = key;
    log_state(('state nativemenu blue-magic-set-missing menu="%s" title="%s" select=%d count=%d page=%d raw=0x%08X obj=0x%08X child=0x%08X entry=0x%08X reason="%s" labels="%s" renderCells="%s" childIdx="%s" objIdx="%s" note="no fixed-row fallback"'):fmt(
        tostring(menu_name or ''),
        tostring(title or ''),
        tonumber(selected) or 0,
        tonumber(count) or 0,
        tonumber(page) or 0,
        tonumber(raw) or 0,
        tonumber(obj) or 0,
        tonumber(child) or 0,
        tonumber(entry) or 0,
        accessxi.escape_probe_log_text(reason or ''),
        accessxi.escape_probe_log_text_wide(label_text:concat(' | ')),
        accessxi.escape_probe_log_text(accessxi.last_magic_render_cells or ''),
        accessxi.escape_probe_log_text(accessxi.format_probe_index_fields(child, 0x00, 0x90)),
        accessxi.escape_probe_log_text(accessxi.format_probe_index_fields(obj, 0x00, 0x90))));
end

function accessxi.blue_magic_set_native_offset()
    if ((tonumber(accessxi.blue_magic_set_native_offset_cache) or 0) > 0) then
        return tonumber(accessxi.blue_magic_set_native_offset_cache) or 0, 'cache';
    end

    local ptr = tonumber(safe_call(function ()
        return ashita.memory.find(0, 0, 'C1E1032BC8B0018D????????????B9????????F3A55F5E5B', 10, 0);
    end, 0)) or 0;
    if (ptr == 0) then
        return 0, 'signature-missing';
    end

    local offset = read_u32(ptr) or 0;
    if (offset <= 0 or offset > 0x100000) then
        return 0, ('bad-offset-0x%08X'):fmt(offset);
    end

    accessxi.blue_magic_set_native_offset_cache = offset;
    accessxi.blue_magic_set_native_offset_ptr = ptr;
    return offset, 'signature';
end

function accessxi.load_blue_magic_set_points()
    if (type(accessxi.blue_magic_set_points) == 'table') then
        return accessxi.blue_magic_set_points;
    end
    if (accessxi.blue_magic_set_points_load_tried == true) then
        return T{};
    end

    accessxi.blue_magic_set_points_load_tried = true;
    local data = accessxi.load_module_table('blue_magic_set_points', T{});
    if (type(data) == 'table') then
        accessxi.blue_magic_set_points = data;
        return data;
    end
    return T{};
end

function accessxi.blue_magic_set_point_cost(spell_id)
    spell_id = tonumber(spell_id) or 0;
    if (spell_id <= 0) then
        return 0;
    end

    local costs = accessxi.load_blue_magic_set_points();
    local cost = tonumber(costs[spell_id]) or 0;
    if (cost > 0 and cost <= 99) then
        return cost;
    end
    return 0;
end

function accessxi.blue_magic_set_points_base()
    local ptr = tonumber(accessxi.blue_magic_set_points_signature_ptr) or 0;
    local source = 'cache';
    if (ptr == 0) then
        ptr = tonumber(safe_call(function ()
            return ashita.memory.find(0, 0, 'A1????????33C98A4E5E33D28A565D5F5E8950148948185B83C414C20400', 1, 0);
        end, 0)) or 0;
        source = 'signature';
    end
    if (ptr == 0) then
        return 0, 'signature-missing';
    end

    local root = read_u32(ptr) or 0;
    if (not accessxi.is_probe_pointer(root)) then
        return 0, ('root-missing-0x%08X'):fmt(root);
    end

    local points = read_u32(root) or 0;
    if (not accessxi.is_probe_pointer(points)) then
        return 0, ('points-missing-0x%08X'):fmt(points);
    end

    accessxi.blue_magic_set_points_signature_ptr = ptr;
    return points, source;
end

function accessxi.blue_magic_set_points_info()
    local base, source = accessxi.blue_magic_set_points_base();
    if (base == 0) then
        return nil, source;
    end

    local spent = tonumber(read_u8(base + 0x14)) or 0;
    local max_points = tonumber(read_u8(base + 0x18)) or 0;
    if (max_points <= 0 or max_points > 99 or spent > 99) then
        return nil, ('invalid-points-%d-%d:%s'):fmt(spent, max_points, tostring(source or ''));
    end

    return T{
        spent = spent,
        max = max_points,
        available = math.max(0, max_points - spent),
        source = source,
    }, source;
end

function accessxi.blue_magic_set_points_text()
    local info = accessxi.blue_magic_set_points_info();
    if (info == nil) then
        return '';
    end
    return ('Blue Magic Points %d of %d spent, %d available'):fmt(
        tonumber(info.spent) or 0,
        tonumber(info.max) or 0,
        tonumber(info.available) or 0);
end

function accessxi.blue_magic_set_append_spell_details(parts, spell)
    if (parts == nil or spell == nil) then
        return;
    end

    local set_cost = accessxi.blue_magic_set_point_cost(spell.id);
    if (set_cost > 0) then
        parts:append(('Set point cost %d'):fmt(set_cost));
    end
    if ((tonumber(spell.mp) or 0) > 0) then
        parts:append(('MP cost %d'):fmt(tonumber(spell.mp) or 0));
    end

    local points_text = accessxi.blue_magic_set_points_text();
    if (points_text ~= '') then
        parts:append(points_text);
    end
    if (tostring(spell.description or '') ~= '') then
        parts:append(spell.description);
    end
end

function accessxi.blue_magic_set_current_pane_active(obj, child, selected)
    obj = tonumber(obj) or 0;
    child = tonumber(child) or 0;
    selected = tonumber(selected) or 0;
    if (selected <= 0 or selected > 20 or not accessxi.is_probe_pointer(obj)) then
        return false, 'invalid-selection';
    end

    local pane = tonumber(read_i32(obj + 0x5C)) or 0;
    local visible = tonumber(read_i32(obj + 0x58)) or 0;
    local child_packed = accessxi.is_probe_pointer(child) and (tonumber(read_u32(child + 0x18)) or 0) or 0;
    local child_visible_a = accessxi.is_probe_pointer(child) and (tonumber(read_i32(child + 0x18)) or 0) or 0;
    local child_visible_b = accessxi.is_probe_pointer(child) and (tonumber(read_i32(child + 0x1C)) or 0) or 0;
    if (pane == 1 and visible > 0 and visible <= 20 and child_visible_a > 0 and child_visible_a <= 20 and child_visible_a == child_visible_b) then
        local slot_base = math.max(0, visible - child_visible_a);
        accessxi.blue_magic_set_last_slot_base = slot_base;
        return true,
            ('pane=%d visible=%d childVisible=%d/%d'):fmt(pane, visible, child_visible_a, child_visible_b),
            slot_base;
    end
    if (pane == 1 and child_packed > 0xFFFF) then
        local child_packed_base = math.floor(child_packed / 0x10000);
        local child_packed_visible = child_packed - (child_packed_base * 0x10000);
        if (child_packed_base >= 0 and child_packed_base <= 10
            and child_packed_visible > 0 and child_packed_visible <= 20
            and selected <= child_packed_visible
            and selected + child_packed_base <= 20) then
            accessxi.blue_magic_set_last_slot_base = child_packed_base;
            return true,
                ('pane=%d visible=%d childPacked=0x%08X base=%d childVisible=%d'):fmt(
                    pane,
                    visible,
                    child_packed,
                    child_packed_base,
                    child_packed_visible),
                child_packed_base;
        end
    end
    if (pane == 1 and visible >= 0 and visible <= 20 and child_visible_a == 0 and child_visible_b == 0) then
        local slot_base = tonumber(accessxi.blue_magic_set_last_slot_base) or 0;
        if (visible > 10) then
            slot_base = visible - 10;
        elseif (visible > 0) then
            slot_base = 0;
        end
        if (slot_base < 0) then
            slot_base = 0;
        elseif (slot_base > 10) then
            slot_base = 10;
        end
        accessxi.blue_magic_set_last_slot_base = slot_base;
        return true,
            ('pane=%d visible=%d childVisible=%d/%d relaxed-child'):fmt(pane, visible, child_visible_a, child_visible_b),
            slot_base;
    end

    return false, ('pane=%d visible=%d childVisible=%d/%d'):fmt(pane, visible, child_visible_a, child_visible_b), 0;
end

function accessxi.blue_magic_set_native_slot_base()
    local player = safe_call(function () return AshitaCore:GetMemoryManager():GetPlayer(); end, nil);
    if (player == nil) then
        return 0, 0, 'player-missing';
    end

    local main_job = tonumber(safe_call(function () return player:GetMainJob(); end, 0)) or 0;
    local sub_job = tonumber(safe_call(function () return player:GetSubJob(); end, 0)) or 0;
    if (main_job ~= 16 and sub_job ~= 16) then
        return 0, 0, ('not-blu-job-%d-%d'):fmt(main_job, sub_job);
    end

    local offset, offset_source = accessxi.blue_magic_set_native_offset();
    if (offset <= 0) then
        return 0, 0, offset_source;
    end

    local inventory_ptr = tonumber(safe_call(function () return AshitaCore:GetPointerManager():Get('inventory'); end, 0)) or 0;
    if (inventory_ptr == 0) then
        return 0, offset, 'inventory-pointer-missing';
    end

    local root = read_u32(inventory_ptr) or 0;
    if (root == 0) then
        return 0, offset, 'inventory-root-missing';
    end
    local inventory = read_u32(root) or 0;
    if (inventory == 0) then
        return 0, offset, 'inventory-buffer-missing';
    end

    local base = inventory + offset + ((main_job == 16) and 0x04 or 0xA0);
    return base, offset, ('%s:%s'):fmt(main_job == 16 and 'main' or 'sub', offset_source);
end

function accessxi.blue_magic_set_current_spell_for_slot(slot)
    slot = tonumber(slot) or 0;
    if (slot <= 0 or slot > 20) then
        return nil, 0, 0, 0, 'slot-out-of-range';
    end

    local base, offset, base_source = accessxi.blue_magic_set_native_slot_base();
    if (base == 0) then
        return nil, 0, offset, 0, base_source;
    end

    local raw_id = read_u8(base + (slot - 1)) or 0;
    if (raw_id <= 0) then
        return nil, raw_id, offset, base, 'empty-slot';
    end

    local spell_id = raw_id + 512;
    local spell = accessxi.magic_spell_resource_info(spell_id);
    if (spell == nil or tonumber(spell.type) ~= 6) then
        return nil, raw_id, offset, base, ('bad-spell-%d'):fmt(spell_id);
    end

    local player = safe_call(function () return AshitaCore:GetMemoryManager():GetPlayer(); end, nil);
    if (player ~= nil and safe_call(function () return player:HasSpell(spell.id); end, false) ~= true) then
        return nil, raw_id, offset, base, ('unknown-spell-%d'):fmt(spell_id);
    end

    return spell, raw_id, offset, base, base_source;
end

function accessxi.blue_magic_current_set_spell_list()
    local set_ids = {};
    local slots = T{};
    local set_count = 0;
    local native_offset = 0;
    local native_base = 0;
    local native_source = '';
    for slot = 1, 20 do
        local spell, raw_id, offset, base, source = accessxi.blue_magic_set_current_spell_for_slot(slot);
        if (slot == 1) then
            native_offset = tonumber(offset) or 0;
            native_base = tonumber(base) or 0;
            native_source = tostring(source or '');
        end
        if (spell ~= nil and (tonumber(spell.id) or 0) > 0) then
            local spell_id = tonumber(spell.id) or 0;
            set_ids[spell_id] = true;
            set_count = set_count + 1;
            slots:append(('%d:%d:%s'):fmt(
                slot,
                spell_id,
                accessxi.escape_probe_log_text(spell.name or '')));
        elseif ((tonumber(raw_id) or 0) > 0) then
            slots:append(('%d:raw%d:%s'):fmt(
                slot,
                tonumber(raw_id) or 0,
                accessxi.escape_probe_log_text(source or '')));
        end
    end

    local mix_order = accessxi.magic_mix_read_order();
    local spells = T{};
    if (mix_order ~= nil and mix_order.ids ~= nil) then
        for _, id in ipairs(mix_order.ids) do
            id = tonumber(id) or 0;
            if (set_ids[id] == true) then
                local spell = accessxi.magic_spell_resource_info(id);
                if (spell ~= nil and tonumber(spell.type) == 6 and tostring(spell.name or '') ~= '') then
                    spells:append(spell);
                end
            end
        end
    end

    local reason = '';
    if (set_count <= 0) then
        reason = 'set-empty';
    elseif (mix_order == nil or mix_order.ids == nil or mix_order.ids:len() <= 0) then
        reason = 'mix-order-missing';
    elseif (spells:len() ~= set_count) then
        reason = ('set-mix-mismatch-%d-%d'):fmt(set_count, spells:len());
    end

    if (reason ~= '') then
        return T{}, mix_order, set_count, reason, slots, native_base, native_offset, native_source;
    end
    return spells, mix_order, set_count, '', slots, native_base, native_offset, native_source;
end

function accessxi.blue_magic_current_set_spell_for_selected(selected)
    selected = tonumber(selected) or 0;
    local spells, mix_order, set_count, reason = accessxi.blue_magic_current_set_spell_list();
    if (reason ~= '') then
        return nil, spells, mix_order, reason, set_count;
    end
    if (selected <= 0 or selected > spells:len()) then
        return nil, spells, mix_order, ('range-%d-of-%d'):fmt(selected, spells:len()), set_count;
    end
    return spells[selected], spells, mix_order, '', set_count;
end

function accessxi.blue_magic_spell_is_unbridled(spell)
    local spell_id = spell ~= nil and (tonumber(spell.id) or 0) or 0;
    return spell ~= nil
        and tonumber(spell.type) == 6
        and spell_id >= 736
        and spell_id <= 753;
end

function accessxi.blue_magic_current_cast_spell_list()
    local set_spells, set_order, set_count, set_reason = accessxi.blue_magic_current_set_spell_list();
    if (set_reason ~= '') then
        return T{}, set_order, set_count, 0, set_reason, '';
    end

    local spells = T{};
    local seen = {};
    for _, spell in ipairs(set_spells) do
        local spell_id = tonumber(spell.id) or 0;
        if (spell_id > 0 and seen[spell_id] ~= true) then
            seen[spell_id] = true;
            spells:append(spell);
        end
    end

    local learned_spells, learned_type, learned_order, learned_reason = accessxi.magic_mix_category_spell_list('Blue Magic');
    if (learned_reason ~= '') then
        return spells, set_order, set_count, 0, '', learned_reason;
    end
    if (tonumber(learned_type) ~= 6) then
        return spells, learned_order or set_order, set_count, 0, '', ('learned-type-%d'):fmt(tonumber(learned_type) or 0);
    end

    local extra_count = 0;
    for _, spell in ipairs(learned_spells) do
        local spell_id = tonumber(spell.id) or 0;
        if (accessxi.blue_magic_spell_is_unbridled(spell) and seen[spell_id] ~= true) then
            seen[spell_id] = true;
            spells:append(spell);
            extra_count = extra_count + 1;
        end
    end

    return spells, learned_order or set_order, set_count, extra_count, '', '';
end

function accessxi.blue_magic_current_cast_spell_for_selected(selected)
    selected = tonumber(selected) or 0;
    local spells, mix_order, set_count, extra_count, reason, extra_reason = accessxi.blue_magic_current_cast_spell_list();
    if (reason ~= '') then
        return nil, spells, mix_order, reason, set_count, extra_count, extra_reason;
    end
    if (selected <= 0 or selected > spells:len()) then
        local range_reason = ('range-%d-of-%d'):fmt(selected, spells:len());
        if (extra_reason ~= '') then
            range_reason = ('%s;extra-%s'):fmt(range_reason, extra_reason);
        end
        return nil, spells, mix_order, range_reason, set_count, extra_count, extra_reason;
    end
    return spells[selected], spells, mix_order, '', set_count, extra_count, extra_reason;
end

function accessxi.blue_magic_current_cast_probe_text()
    local spells, mix_order, set_count, extra_count, reason, extra_reason = accessxi.blue_magic_current_cast_spell_list();
    local extra_rows = T{};
    for index, spell in ipairs(spells or T{}) do
        if index > (tonumber(set_count) or 0) then
            extra_rows:append(('%d:%s'):fmt(
                tonumber(spell.id) or 0,
                accessxi.escape_probe_log_text(spell.name or '')));
        end
    end
    return ('setCount=%d extraCount=%d total=%d reason="%s" extraReason="%s" mixPath="%s" extras="%s"'):fmt(
        tonumber(set_count) or 0,
        tonumber(extra_count) or 0,
        spells:len(),
        accessxi.escape_probe_log_text(reason or ''),
        accessxi.escape_probe_log_text(extra_reason or ''),
        accessxi.escape_probe_log_text(mix_order ~= nil and mix_order.path or ''),
        accessxi.escape_probe_log_text(extra_rows:concat(' | ')));
end

function accessxi.blue_magic_current_set_probe_text()
    local spells, mix_order, set_count, reason, slots, native_base, native_offset, native_source = accessxi.blue_magic_current_set_spell_list();
    local filtered = T{};
    for _, spell in ipairs(spells or T{}) do
        filtered:append(('%d:%s'):fmt(
            tonumber(spell.id) or 0,
            accessxi.escape_probe_log_text(spell.name or '')));
    end

    return ('setCount=%d filteredCount=%d reason="%s" base=0x%08X offset=0x%08X source="%s" mixPath="%s" slots="%s" filtered="%s"'):fmt(
        set_count,
        filtered:len(),
        accessxi.escape_probe_log_text(reason),
        native_base,
        native_offset,
        accessxi.escape_probe_log_text(native_source),
        accessxi.escape_probe_log_text(mix_order ~= nil and mix_order.path or ''),
        accessxi.escape_probe_log_text(slots:concat(' | ')),
        accessxi.escape_probe_log_text(filtered:concat(' | ')));
end

function accessxi.blue_magic_inventory_record_anchor(native_slot, selected, spell)
    native_slot = tonumber(native_slot) or 0;
    selected = tonumber(selected) or 0;
    if (native_slot <= 0 or selected <= 0 or spell == nil or tonumber(spell.id) == nil) then
        return;
    end

    accessxi.blue_magic_inventory_anchor = T{
        native_slot = native_slot,
        set_selected = selected,
        spell_id = tonumber(spell.id) or 0,
        spell_name = tostring(spell.name or ''),
        tick = tick(),
        list_obj = 0,
        list_selected = 0,
    };
end

function accessxi.blue_magic_inventory_anchor_visible_count(obj, child)
    obj = tonumber(obj) or 0;
    child = tonumber(child) or 0;

    local obj_visible = accessxi.is_probe_pointer(obj) and (tonumber(read_i32(obj + 0x58)) or 0) or 0;
    if (obj_visible > 0 and obj_visible <= 64) then
        return obj_visible, 'obj+58';
    end

    local child_visible = 0;
    if (accessxi.is_probe_pointer(child)) then
        child_visible = bit.band(read_u32(child + 0x18) or 0, 0xFFFF);
    end
    if (child_visible > 0 and child_visible <= 64) then
        return child_visible, 'child+18.low';
    end

    return 0, 'missing';
end

function accessxi.blue_magic_inventory_native_scroll_selected(child, selected)
    child = tonumber(child) or 0;
    selected = tonumber(selected) or 0;
    if (selected <= 0 or not accessxi.is_probe_pointer(child)) then
        return 0, 0, 0, 0, 0, 'child-or-selected';
    end

    local child_window = read_u32(child + 0x18) or 0;
    local child_window2 = read_u32(child + 0x1C) or 0;
    local visible_count = bit.band(child_window, 0xFFFF);
    local window_start = math.floor(child_window / 0x10000);
    local window2_start = math.floor(child_window2 / 0x10000);
    local window2_low = bit.band(child_window2, 0xFFFF);

    if (window_start <= 0 or visible_count <= 0 or visible_count > 64) then
        return 0, window_start, visible_count, child_window, child_window2, 'window-range';
    end
    if (selected > visible_count) then
        return 0, window_start, visible_count, child_window, child_window2, 'selected-outside-visible';
    end
    if (window2_start ~= window_start) then
        return 0, window_start, visible_count, child_window, child_window2, 'window-start-mismatch';
    end
    if (window2_low ~= window_start + visible_count) then
        return 0, window_start, visible_count, child_window, child_window2, 'window-end-mismatch';
    end

    local scroll_selected = window_start + selected - 1;
    if (scroll_selected <= 0) then
        return 0, window_start, visible_count, child_window, child_window2, 'scroll-selected-range';
    end

    return scroll_selected, window_start, visible_count, child_window, child_window2, 'child-window';
end

function accessxi.blue_magic_inventory_spell_from_native_scroll(obj, child, selected)
    obj = tonumber(obj) or 0;
    child = tonumber(child) or 0;
    selected = tonumber(selected) or 0;

    local scroll_selected, window_start, visible_count, child_window, child_window2, scroll_reason = accessxi.blue_magic_inventory_native_scroll_selected(child, selected);
    if (scroll_selected <= 0) then
        return nil, scroll_selected, window_start, visible_count, child_window, child_window2, nil, tostring(scroll_reason or ''), 0, 0;
    end

    local spell, spells, wanted_type, order, reason = accessxi.magic_mix_category_spell_for_selected('Blue Magic', scroll_selected);
    local total = spells ~= nil and spells:len() or 0;
    if (tostring(reason or '') ~= '') then
        return nil, scroll_selected, window_start, visible_count, child_window, child_window2, order, tostring(reason or ''), total, wanted_type;
    end
    if (spell == nil) then
        return nil, scroll_selected, window_start, visible_count, child_window, child_window2, order, 'range', total, wanted_type;
    end
    if (tonumber(spell.type) ~= 6) then
        return nil, scroll_selected, window_start, visible_count, child_window, child_window2, order, 'not-blue-magic', total, wanted_type;
    end

    local player = safe_call(function () return AshitaCore:GetMemoryManager():GetPlayer(); end, nil);
    if (player ~= nil and safe_call(function () return player:HasSpell(spell.id); end, false) ~= true) then
        return nil, scroll_selected, window_start, visible_count, child_window, child_window2, order, 'not-known', total, wanted_type;
    end

    return spell, scroll_selected, window_start, visible_count, child_window, child_window2, order, 'native-scroll-blue-category-mix', total, wanted_type;
end

function accessxi.blue_magic_inventory_spell_from_anchor(obj, child, entry, selected)
    obj = tonumber(obj) or 0;
    child = tonumber(child) or 0;
    entry = tonumber(entry) or 0;
    selected = tonumber(selected) or 0;
    local anchor = accessxi.blue_magic_inventory_anchor;
    if (selected <= 0 or type(anchor) ~= 'table') then
        return nil, 0, 0, 0, 0, 'no-anchor';
    end

    local anchor_spell_id = tonumber(anchor.spell_id) or 0;
    if (anchor_spell_id <= 0) then
        return nil, 0, 0, 0, 0, 'anchor-spell';
    end

    local now = tick();
    local anchor_age = now - (tonumber(anchor.tick) or 0);
    if (anchor_age < 0 or anchor_age > 300000) then
        return nil, 0, 0, 0, anchor_spell_id, 'anchor-stale';
    end

    local visible_count, visible_source = accessxi.blue_magic_inventory_anchor_visible_count(obj, child);
    if (tonumber(anchor.list_obj) ~= obj) then
        anchor.list_obj = obj;
        anchor.list_selected = selected;
        anchor.list_entry = entry;
        anchor.last_selected = selected;
        anchor.last_entry = entry;
        anchor.last_global_index = 0;
        anchor.edge_scroll_window_tick = 0;
        anchor.edge_scroll_window_index = 0;
        anchor.last_scroll_window_start = 0;
        anchor.unsafe = false;
        anchor.unsafe_reason = '';
        anchor.visible_count = visible_count;
        anchor.visible_source = visible_source;
        anchor.list_tick = now;
    end

    local anchor_selected = tonumber(anchor.list_selected) or 0;
    if (anchor_selected <= 0) then
        anchor_selected = selected;
        anchor.list_selected = anchor_selected;
    end
    anchor.visible_count = visible_count;
    anchor.visible_source = visible_source;

    local row_entry_shifted = (selected == tonumber(anchor.last_selected)
        and entry ~= 0
        and tonumber(anchor.last_entry) ~= 0
        and entry ~= tonumber(anchor.last_entry));
    local stationary_row = (selected == tonumber(anchor.last_selected)
        and (entry == 0 or tonumber(anchor.last_entry) == 0 or entry == tonumber(anchor.last_entry)));
    local last_global_index = tonumber(anchor.last_global_index) or 0;
    if (stationary_row ~= true) then
        anchor.edge_scroll_window_tick = 0;
        anchor.edge_scroll_window_index = 0;
    end

    if (anchor.unsafe == true) then
        return nil, 0, anchor_selected, 0, anchor_spell_id, tostring(anchor.unsafe_reason or 'anchor-unsafe');
    end

    local spells, wanted_type, order, reason = accessxi.magic_mix_category_spell_list('Blue Magic');
    if (tostring(reason or '') ~= '') then
        return nil, 0, anchor_selected, 0, anchor_spell_id, ('anchor-order-%s'):fmt(tostring(reason or ''));
    end
    if (spells == nil or spells:len() <= 0) then
        return nil, 0, anchor_selected, 0, anchor_spell_id, 'anchor-order-empty';
    end

    local anchor_base_index = 0;
    for index, spell in ipairs(spells) do
        if (spell ~= nil and tonumber(spell.id) == anchor_spell_id) then
            anchor_base_index = index;
            break;
        end
    end
    if (anchor_base_index <= 0) then
        return nil, 0, anchor_selected, 0, anchor_spell_id, 'anchor-spell-not-in-order';
    end

    local expected_global_index = anchor_base_index + selected - anchor_selected;
    local global_index = expected_global_index;
    local source = 'native-set-slot-mix-order';

    local scroll_selected, scroll_window_start = accessxi.blue_magic_inventory_native_scroll_selected(child, selected);
    scroll_selected = tonumber(scroll_selected) or 0;
    scroll_window_start = tonumber(scroll_window_start) or 0;
    local previous_selected = tonumber(anchor.last_selected) or selected;
    local previous_window_start = tonumber(anchor.last_scroll_window_start) or 0;
    local selected_delta = selected - previous_selected;
    local window_delta = 0;
    if (scroll_window_start > 0 and previous_window_start > 0) then
        window_delta = scroll_window_start - previous_window_start;
    end
    local selected_motion_limit = math.max(tonumber(visible_count) or 0, 1);
    local page_motion_limit = spells:len();
    local window_motion_limit = math.max((tonumber(visible_count) or 0) * 3, 24);
    if (page_motion_limit > window_motion_limit) then
        window_motion_limit = page_motion_limit;
    end
    local native_motion_delta = 0;
    if (window_delta ~= 0) then
        native_motion_delta = window_delta + selected_delta;
    end

    local motion_delta = 0;
    if (last_global_index > 0) then
        if (window_delta ~= 0
            and native_motion_delta ~= 0
            and math.abs(window_delta) <= window_motion_limit
            and math.abs(native_motion_delta) <= window_motion_limit) then
            local edge_window_motion = ((selected <= 1 and window_delta < 0)
                or (visible_count > 0 and selected >= visible_count and window_delta > 0));
            if (edge_window_motion == true or math.abs(window_delta) > math.abs(selected_delta)) then
                motion_delta = native_motion_delta;
            end
        end
        if (motion_delta == 0 and selected_delta ~= 0 and math.abs(selected_delta) <= selected_motion_limit) then
            motion_delta = selected_delta;
        elseif (motion_delta == 0 and row_entry_shifted == true) then
            if (selected <= 1) then
                motion_delta = -1;
            elseif (visible_count > 0 and selected >= visible_count) then
                motion_delta = 1;
            end
        end
    end
    anchor.last_scroll_selected = scroll_selected;
    anchor.last_scroll_window_start_previous = previous_window_start;
    anchor.last_selected_delta = selected_delta;
    anchor.last_window_delta = window_delta;
    anchor.last_native_motion_delta = native_motion_delta;
    anchor.last_motion_delta = motion_delta;
    anchor.last_window_motion_limit = window_motion_limit;

    if (last_global_index > 0 and motion_delta ~= 0) then
        global_index = last_global_index + motion_delta;
        source = 'native-set-slot-cursor-motion';
        anchor.edge_scroll_window_tick = now;
        anchor.edge_scroll_window_index = global_index;
    elseif (row_entry_shifted == true) then
        anchor.unsafe = true;
        anchor.unsafe_reason = 'anchor-row-entry-shift-unresolved';
        anchor.last_selected = selected;
        anchor.last_entry = entry;
        if (scroll_window_start > 0) then
            anchor.last_scroll_window_start = scroll_window_start;
        end
        return nil, 0, anchor_selected, anchor_base_index, anchor_spell_id, tostring(anchor.unsafe_reason or 'anchor-unsafe');
    end

    if (global_index <= 0 or global_index > spells:len()) then
        anchor.last_selected = selected;
        anchor.last_entry = entry;
        if (scroll_window_start > 0) then
            anchor.last_scroll_window_start = scroll_window_start;
        end
        return nil, global_index, anchor_selected, anchor_base_index, anchor_spell_id, 'anchor-range';
    end

    local spell = spells[global_index];
    if (spell == nil or tonumber(spell.type) ~= 6) then
        anchor.last_selected = selected;
        anchor.last_entry = entry;
        if (scroll_window_start > 0) then
            anchor.last_scroll_window_start = scroll_window_start;
        end
        return nil, global_index, anchor_selected, anchor_base_index, anchor_spell_id, 'anchor-not-blue-magic';
    end

    local player = safe_call(function () return AshitaCore:GetMemoryManager():GetPlayer(); end, nil);
    if (player ~= nil and safe_call(function () return player:HasSpell(spell.id); end, false) ~= true) then
        anchor.last_selected = selected;
        anchor.last_entry = entry;
        if (scroll_window_start > 0) then
            anchor.last_scroll_window_start = scroll_window_start;
        end
        return nil, global_index, anchor_selected, anchor_base_index, anchor_spell_id, 'anchor-not-known';
    end

    anchor.last_selected = selected;
    anchor.last_entry = entry;
    anchor.last_global_index = global_index;
    if (scroll_window_start > 0) then
        anchor.last_scroll_window_start = scroll_window_start;
    end
    anchor.spell_id = tonumber(spell.id) or anchor_spell_id;
    anchor.list_selected = selected;
    anchor_selected = selected;
    anchor_base_index = global_index;
    anchor_spell_id = tonumber(spell.id) or anchor_spell_id;

    return spell, global_index, anchor_selected, anchor_base_index, anchor_spell_id, source;
end

function accessxi.blue_magic_set_menu_speech(menu_name, title, obj, selected, count, page, raw, child, entry)
    menu_name = tostring(menu_name or '');
    if (not menu_name:eq('menu    bluequip', true)) then
        return nil;
    end

    title = accessxi.plain_native_menu_label(title or '');
    if (title == '') then
        title = 'Blue Magic';
    end
    obj = tonumber(obj) or 0;
    child = tonumber(child) or 0;
    entry = tonumber(entry) or 0;
    selected = tonumber(selected) or 0;
    count = tonumber(count) or 0;
    page = tonumber(page) or 0;
    raw = tonumber(raw) or 0;

    local obj_selected = read_current_native_menu_index(0x4C);
    if (obj_selected > 0) then
        selected = obj_selected;
    end
    if (count <= 0 or count > 64) then
        count = math.max(tonumber(accessxi.native_menu_index(0x24)) or 0, tonumber(accessxi.native_menu_index(0x28)) or 0);
    end

    local labels = T{};
    local seen_labels = {};
    local function add_label(source, label)
        label = accessxi.blue_magic_set_clean_native_label(label or '');
        if (label == '') then
            return;
        end
        local key = label:lower();
        if (seen_labels[key] == true) then
            return;
        end
        seen_labels[key] = true;
        labels:append(T{ source = tostring(source or ''), label = label });
    end

    local rendered_label = accessxi.magic_rendered_row_text(entry, selected);
    add_label('rendered-row', rendered_label);

    if (accessxi.is_probe_pointer(entry)) then
        local label_ptr = read_u32(entry + 0x44) or 0;
        local help_ptr = read_u32(entry + 0x40) or 0;
        add_label('entry+44', read_probe_string(label_ptr, 160));
        add_label('entry+40', read_probe_string(help_ptr, 220));
    end

    local current_pane, pane_reason, slot_base = accessxi.blue_magic_set_current_pane_active(obj, child, selected);
    if (current_pane == true) then
        local native_slot = selected + (tonumber(slot_base) or 0);
        local slot_spell, raw_id, native_offset, slot_base_ptr, slot_source = accessxi.blue_magic_set_current_spell_for_slot(native_slot);
        if (slot_spell ~= nil) then
            accessxi.blue_magic_inventory_record_anchor(native_slot, selected, slot_spell);
            local parts = T{ title, ('Set slot %d'):fmt(native_slot), slot_spell.name };
            accessxi.blue_magic_set_append_spell_details(parts, slot_spell);
            local speech = accessxi.speech_output_text(parts:concat('. '));
            if (speech ~= '') then
                accessxi.last_native_menu_name = menu_name;
                accessxi.last_native_menu_label = slot_spell.name;
                accessxi.last_native_menu_selected = selected;
                accessxi.last_native_menu_tick = tick();
                accessxi.current_speech_key = ('native-bluequip-set-slot:%s:%d:%d:%d:%d:%s'):fmt(
                    menu_name,
                    selected,
                    native_slot,
                    tonumber(raw_id) or 0,
                    tonumber(slot_spell.id) or 0,
                    tostring(slot_spell.name or ''));
                local point_info = accessxi.blue_magic_set_points_info();
                local set_cost = accessxi.blue_magic_set_point_cost(slot_spell.id);
                log_state(('state nativemenu blue-magic-set-native-slot menu="%s" title="%s" select=%d nativeSlot=%d count=%d page=%d raw=0x%08X entry=0x%08X spellId=%d rawId=%d type=%d setCost=%d mp=%d bluSpent=%d bluMax=%d bluAvailable=%d descLen=%d base=0x%08X offset=0x%08X source="%s" pane="%s" labels="%s"'):fmt(
                    menu_name,
                    title,
                    selected,
                    native_slot,
                    count,
                    page,
                    raw,
                    entry,
                    tonumber(slot_spell.id) or 0,
                    tonumber(raw_id) or 0,
                    tonumber(slot_spell.type) or 0,
                    tonumber(set_cost) or 0,
                    tonumber(slot_spell.mp) or 0,
                    point_info ~= nil and (tonumber(point_info.spent) or 0) or 0,
                    point_info ~= nil and (tonumber(point_info.max) or 0) or 0,
                    point_info ~= nil and (tonumber(point_info.available) or 0) or 0,
                    #(tostring(slot_spell.description or '')),
                    tonumber(slot_base_ptr) or 0,
                    tonumber(native_offset) or 0,
                    accessxi.escape_probe_log_text(slot_source or ''),
                    accessxi.escape_probe_log_text(pane_reason or ''),
                    accessxi.escape_probe_log_text(accessxi.last_magic_render_cells or '')));
                return speech;
            end
        end

        if (tostring(slot_source or ''):eq('empty-slot', true)) then
            local points_text = accessxi.blue_magic_set_points_text();
            local speech_text = ('%s. Set slot %d. Empty.'):fmt(title, native_slot);
            if (points_text ~= '') then
                speech_text = speech_text .. ' ' .. points_text .. '.';
            end
            local speech = accessxi.speech_output_text(speech_text);
            if (speech ~= '') then
                accessxi.last_native_menu_name = menu_name;
                accessxi.last_native_menu_label = 'Empty';
                accessxi.last_native_menu_selected = selected;
                accessxi.last_native_menu_tick = tick();
                accessxi.current_speech_key = ('native-bluequip-empty-slot:%s:%d:%d'):fmt(menu_name, selected, native_slot);
                local point_info = accessxi.blue_magic_set_points_info();
                log_state(('state nativemenu blue-magic-set-native-slot menu="%s" title="%s" select=%d nativeSlot=%d count=%d entry=0x%08X rawId=%d bluSpent=%d bluMax=%d bluAvailable=%d base=0x%08X offset=0x%08X source="empty-slot" pane="%s"'):fmt(
                    menu_name,
                    title,
                    selected,
                    native_slot,
                    count,
                    entry,
                    tonumber(raw_id) or 0,
                    point_info ~= nil and (tonumber(point_info.spent) or 0) or 0,
                    point_info ~= nil and (tonumber(point_info.max) or 0) or 0,
                    point_info ~= nil and (tonumber(point_info.available) or 0) or 0,
                    tonumber(slot_base_ptr) or 0,
                    tonumber(native_offset) or 0,
                    accessxi.escape_probe_log_text(pane_reason or '')));
                return speech;
            end
        end

        log_state(('state nativemenu blue-magic-set-quiet menu="%s" title="%s" select=%d nativeSlot=%d count=%d entry=0x%08X reason="native-slot-missing" rawId=%d base=0x%08X offset=0x%08X source="%s" pane="%s" labels="%s"'):fmt(
            menu_name,
            title,
            selected,
            native_slot,
            count,
            entry,
            tonumber(raw_id) or 0,
            tonumber(slot_base_ptr) or 0,
            tonumber(native_offset) or 0,
            accessxi.escape_probe_log_text(slot_source or ''),
            accessxi.escape_probe_log_text(pane_reason or ''),
            accessxi.escape_probe_log_text(accessxi.last_magic_render_cells or '')));
        return nil;
    end

    local remove_all_item = nil;
    local spell_matches = T{};
    local seen_spell_ids = {};
    for _, item in ipairs(labels) do
        if (tostring(item.label or ''):eq('(Remove All)', true)) then
            remove_all_item = item;
        else
            local spell, match_count, match_source = accessxi.blue_magic_spell_from_exact_label(item.label);
            local player = safe_call(function () return AshitaCore:GetMemoryManager():GetPlayer(); end, nil);
            if (spell ~= nil) then
                local known = player ~= nil and safe_call(function () return player:HasSpell(spell.id); end, false) == true;
                if (known == true and tonumber(spell.type) == 6) then
                    local spell_id = tonumber(spell.id) or 0;
                    if (seen_spell_ids[spell_id] ~= true) then
                        seen_spell_ids[spell_id] = true;
                        spell_matches:append(T{
                            spell = spell,
                            item = item,
                            match_count = match_count,
                            match_source = match_source,
                        });
                    end
                else
                    log_state(('state nativemenu blue-magic-set-quiet menu="%s" title="%s" select=%d count=%d entry=0x%08X reason="spell-not-known-blue" spellId=%d type=%d known=%s label="%s" source="%s"'):fmt(
                        menu_name,
                        title,
                        selected,
                        count,
                        entry,
                        tonumber(spell.id) or 0,
                        tonumber(spell.type) or 0,
                        tostring(known),
                        accessxi.escape_probe_log_text(item.label or ''),
                        accessxi.escape_probe_log_text(item.source or '')));
                end
            end
        end
    end

    if (spell_matches:len() > 1) then
        accessxi.blue_magic_set_log_missing(menu_name, title, selected, count, page, raw, obj, child, entry, labels, 'ambiguous-native-blue-spells');
        return nil;
    end

    if (spell_matches:len() == 1) then
        local match = spell_matches[1];
        local spell = match.spell;
        local item = match.item or T{};
        local parts = T{ title, spell.name };
        accessxi.blue_magic_set_append_spell_details(parts, spell);
        local speech = accessxi.speech_output_text(parts:concat('. '));
        if (speech ~= '') then
            accessxi.last_native_menu_name = menu_name;
            accessxi.last_native_menu_label = spell.name;
            accessxi.last_native_menu_selected = selected;
            accessxi.last_native_menu_tick = tick();
            accessxi.current_speech_key = ('native-bluequip-spell:%s:%d:%d:%d:%s:%s'):fmt(
                menu_name,
                selected,
                count,
                tonumber(spell.id) or 0,
                tostring(item.source or ''),
                tostring(spell.name or ''));
            local point_info = accessxi.blue_magic_set_points_info();
            local set_cost = accessxi.blue_magic_set_point_cost(spell.id);
            log_state(('state nativemenu blue-magic-set-native-row menu="%s" title="%s" select=%d count=%d page=%d raw=0x%08X entry=0x%08X spellId=%d type=%d setCost=%d source="%s" matchSource="%s" matchCount=%d label="%s" cleaned="%s" mp=%d bluSpent=%d bluMax=%d bluAvailable=%d descLen=%d renderCells="%s"'):fmt(
                menu_name,
                title,
                selected,
                count,
                page,
                raw,
                entry,
                tonumber(spell.id) or 0,
                tonumber(spell.type) or 0,
                tonumber(set_cost) or 0,
                accessxi.escape_probe_log_text(item.source or ''),
                accessxi.escape_probe_log_text(match.match_source or ''),
                tonumber(match.match_count) or 0,
                accessxi.escape_probe_log_text(item.label or ''),
                accessxi.escape_probe_log_text(spell.name or ''),
                tonumber(spell.mp) or 0,
                point_info ~= nil and (tonumber(point_info.spent) or 0) or 0,
                point_info ~= nil and (tonumber(point_info.max) or 0) or 0,
                point_info ~= nil and (tonumber(point_info.available) or 0) or 0,
                #(tostring(spell.description or '')),
                accessxi.escape_probe_log_text(accessxi.last_magic_render_cells or '')));
            return speech;
        end
    end

    if (remove_all_item ~= nil) then
        local prompt = accessxi.dat_index_row_text('ROM\\97\\37.DAT', 226, 'label');
        if (prompt == '') then
            prompt = accessxi.dat_index_row_text('ROM\\97\\37.DAT', 226, 'help');
        end
        local parts = T{ title, 'Remove All' };
        if (prompt ~= '' and not prompt:eq('Remove All', true)) then
            parts:append(prompt);
        end
        local speech = accessxi.speech_output_text(parts:concat('. '));
        if (speech ~= '') then
            accessxi.last_native_menu_name = menu_name;
            accessxi.last_native_menu_label = 'Remove All';
            accessxi.last_native_menu_selected = selected;
            accessxi.last_native_menu_tick = tick();
            accessxi.current_speech_key = ('native-bluequip-remove-all:%s:%d:%d:%s'):fmt(menu_name, selected, count, prompt);
            log_state(('state nativemenu blue-magic-set-native-row menu="%s" title="%s" select=%d count=%d entry=0x%08X label="Remove All" source="%s" prompt="%s"'):fmt(
                menu_name,
                title,
                selected,
                count,
                entry,
                accessxi.escape_probe_log_text(remove_all_item.source or ''),
                accessxi.escape_probe_log_text(prompt)));
            return speech;
        end
    end

    local help_spell, help_count, help_source, help_title, help_text, help_title_ptr, help_ptr, window_name = accessxi.magic_spell_from_window_help();
    if (help_spell ~= nil) then
        local player = safe_call(function () return AshitaCore:GetMemoryManager():GetPlayer(); end, nil);
        local known = player ~= nil and safe_call(function () return player:HasSpell(help_spell.id); end, false) == true;
        if (known == true and tonumber(help_spell.type) == 6) then
            local parts = T{ title, help_spell.name };
            accessxi.blue_magic_set_append_spell_details(parts, help_spell);
            local speech = accessxi.speech_output_text(parts:concat('. '));
            if (speech ~= '') then
                accessxi.last_native_menu_name = menu_name;
                accessxi.last_native_menu_label = help_spell.name;
                accessxi.last_native_menu_selected = selected;
                accessxi.last_native_menu_tick = tick();
                accessxi.current_speech_key = ('native-bluequip-window-help:%s:%d:%d:%d:%s'):fmt(
                    menu_name,
                    selected,
                    count,
                    tonumber(help_spell.id) or 0,
                    tostring(help_source or ''));
                log_state(('state nativemenu blue-magic-set-native-row menu="%s" title="%s" select=%d count=%d entry=0x%08X spellId=%d source="%s" helpTitlePtr=0x%08X helpTitle="%s" helpPtr=0x%08X help="%s" win="%s" matches=%d'):fmt(
                    menu_name,
                    title,
                    selected,
                    count,
                    entry,
                    tonumber(help_spell.id) or 0,
                    accessxi.escape_probe_log_text(help_source or ''),
                    tonumber(help_title_ptr) or 0,
                    accessxi.escape_probe_log_text(help_title or ''),
                    tonumber(help_ptr) or 0,
                    accessxi.escape_probe_log_text(help_text or ''),
                    accessxi.escape_probe_log_text(window_name or ''),
                    tonumber(help_count) or 0));
                return speech;
            end
        end
    end

    accessxi.blue_magic_set_log_missing(menu_name, title, selected, count, page, raw, obj, child, entry, labels, 'no-exact-native-blue-spell');
    return nil;
end

function accessxi.blue_magic_inventory_log_missing(menu_name, title, selected, count, page, raw, obj, child, entry, labels, reason)
    labels = labels or T{};
    local label_text = T{};
    for _, item in ipairs(labels) do
        label_text:append(('%s="%s"'):fmt(
            accessxi.escape_probe_log_text(item.source or ''),
            accessxi.escape_probe_log_text(item.label or '')));
    end

    local key = ('%s:%d:%d:%08X:%08X:%08X:%s:%s'):fmt(
        tostring(menu_name or ''),
        tonumber(selected) or 0,
        tonumber(count) or 0,
        tonumber(obj) or 0,
        tonumber(child) or 0,
        tonumber(entry) or 0,
        tostring(reason or ''),
        label_text:concat('|'));
    if (key == tostring(accessxi.last_blue_magic_inventory_missing_key or '')) then
        return;
    end
    accessxi.last_blue_magic_inventory_missing_key = key;
    log_state(('state nativemenu blue-magic-inventory-missing menu="%s" title="%s" select=%d count=%d page=%d raw=0x%08X obj=0x%08X child=0x%08X entry=0x%08X reason="%s" labels="%s" renderCells="%s" childIdx="%s" objIdx="%s" note="no fixed-row fallback"'):fmt(
        tostring(menu_name or ''),
        tostring(title or ''),
        tonumber(selected) or 0,
        tonumber(count) or 0,
        tonumber(page) or 0,
        tonumber(raw) or 0,
        tonumber(obj) or 0,
        tonumber(child) or 0,
        tonumber(entry) or 0,
        accessxi.escape_probe_log_text(reason or ''),
        accessxi.escape_probe_log_text_wide(label_text:concat(' | ')),
        accessxi.escape_probe_log_text(accessxi.last_magic_render_cells or ''),
        accessxi.escape_probe_log_text(accessxi.format_probe_index_fields(child, 0x00, 0x90)),
        accessxi.escape_probe_log_text(accessxi.format_probe_index_fields(obj, 0x00, 0x90))));
end

function accessxi.blue_magic_inventory_row_cell_probe(entry, selected)
    local cells = accessxi.magic_rendered_row_cells(entry, selected, 64, true);
    if (cells:len() == 0) then
        return 'cells=0';
    end

    local parts = T{};
    for _, cell in ipairs(cells) do
        local ptr = tonumber(cell.ptr) or 0;
        parts:append(('cell=0x%08X order=0x%04X inline="%s" dwords="%s" bytes3C="%s" text="%s" ptrText="%s"'):fmt(
            ptr,
            tonumber(cell.order) or 0,
            accessxi.escape_probe_log_text(cell.text or ''),
            accessxi.escape_probe_log_text(accessxi.format_probe_dwords(ptr, 0x00, 28)),
            accessxi.escape_probe_log_text(accessxi.format_probe_bytes(ptr, 0x3C, 0x50)),
            accessxi.escape_probe_log_text(accessxi.magic_text_runs('cell', ptr, 0x140, 2, 8)),
            accessxi.escape_probe_log_text(accessxi.magic_pointer_text_targets('cell', ptr, 0x00, 0x80, 6))));
        if (parts:len() >= 8) then
            break;
        end
    end

    return parts:concat(' || ');
end

function accessxi.blue_magic_inventory_child_row_probe(child, entry, selected)
    child = tonumber(child) or 0;
    entry = tonumber(entry) or 0;
    selected = tonumber(selected) or 0;
    if (selected <= 0) then
        return '';
    end

    local parts = T{};
    if (accessxi.friend_list_child_row_pointer_probe ~= nil and accessxi.is_probe_pointer(child)) then
        local child_rows = accessxi.friend_list_child_row_pointer_probe(child, selected);
        if (child_rows ~= '') then
            parts:append(('rows{%s}'):fmt(child_rows));
        end
    end
    if (accessxi.friend_list_selected_row_glyph_probe ~= nil) then
        local glyphs = accessxi.friend_list_selected_row_glyph_probe(child, entry, selected);
        if (glyphs ~= '') then
            parts:append(('glyphs{%s}'):fmt(glyphs));
        end
    end

    return parts:concat(' || ');
end

function accessxi.blue_magic_inventory_rendered_cell_scan_probe(obj, child, entry, selected, count, seq)
    obj = tonumber(obj) or 0;
    child = tonumber(child) or 0;
    entry = tonumber(entry) or 0;
    selected = tonumber(selected) or 0;
    count = tonumber(count) or 0;
    seq = tonumber(seq) or 0;
    if (not accessxi.is_probe_pointer(entry) or selected <= 0) then
        return 0;
    end

    local entry_parent = read_u32(entry + 0x5C) or 0;
    local emitted = 0;
    local max_lines = 40;
    local seen = {};

    local function log_cell(delta, cell, source)
        if (emitted >= max_lines) then
            return;
        end
        cell = tonumber(cell) or 0;
        if (not accessxi.is_probe_pointer(cell) or seen[cell] == true) then
            return;
        end

        local self_ptr = read_u32(cell + 0x58) or 0;
        if (self_ptr ~= cell) then
            return;
        end

        local row_code = read_u32(cell + 0x38) or 0;
        local row_index = math.floor(row_code / 0x10000);
        local order = bit.band(row_code, 0xFFFF);
        local parent = read_u32(cell + 0x5C) or 0;
        local row_data = read_u32(cell + 0x0C) or 0;
        local text = accessxi.search_result_rendered_cell_text(cell);
        local direct = accessxi.search_result_control_fragments(cell + 0x30, 0x80, 8);
        local runs = accessxi.probe_runs_to_text(accessxi.collect_probe_ascii_runs(cell, 0x120, 2, 8));
        seen[cell] = true;
        emitted = emitted + 1;

        log_state(('state nativemenu blue-magic-inventory-cell-probe seq=%d delta=%+d source="%s" ptr=0x%08X row=%d order=0x%04X parent=0x%08X obj=0x%08X child=0x%08X entryParent=0x%08X rowData=0x%08X parentObj=%s parentEntry=%s selected=%s count=%d text="%s" direct="%s" runs="%s" bytes3C="%s" note="probe-only no-speech-fallback"'):fmt(
            seq,
            tonumber(delta) or 0,
            accessxi.escape_probe_log_text(source or ''),
            cell,
            row_index,
            order,
            parent,
            obj,
            child,
            entry_parent,
            row_data,
            tostring(obj ~= 0 and parent == obj),
            tostring(entry_parent ~= 0 and parent == entry_parent),
            tostring(row_index == selected),
            count,
            accessxi.escape_probe_log_text(text or ''),
            accessxi.escape_probe_log_text(direct or ''),
            accessxi.escape_probe_log_text_wide(runs or ''),
            accessxi.escape_probe_log_text(accessxi.format_probe_bytes(cell, 0x3C, 0x40))));
    end

    local function scan(source, predicate)
        for delta = -96, 96 do
            if (emitted >= max_lines) then
                return;
            end
            local cell = entry + (delta * 0x68);
            if (accessxi.is_probe_pointer(cell) and seen[cell] ~= true) then
                local self_ptr = read_u32(cell + 0x58) or 0;
                if (self_ptr == cell) then
                    local row_code = read_u32(cell + 0x38) or 0;
                    local row_index = math.floor(row_code / 0x10000);
                    local parent = read_u32(cell + 0x5C) or 0;
                    local text = accessxi.search_result_rendered_cell_text(cell);
                    local direct = accessxi.search_result_control_fragments(cell + 0x30, 0x80, 4);
                    if (predicate(cell, row_index, parent, text, direct)) then
                        log_cell(delta, cell, source);
                    end
                end
            end
        end
    end

    scan('obj-parent-rows', function (_, row_index, parent)
        return obj ~= 0 and parent == obj and row_index >= 1 and (count <= 0 or row_index <= count);
    end);
    scan('entry-parent-rows', function (_, row_index, parent)
        return entry_parent ~= 0 and parent == entry_parent and row_index >= 1 and (count <= 0 or row_index <= count);
    end);
    scan('selected-row-any-parent', function (_, row_index)
        return row_index == selected;
    end);
    scan('text-row-any-parent', function (_, row_index, _, text, direct)
        return row_index >= 1 and (count <= 0 or row_index <= count) and (text ~= '' or direct ~= '');
    end);

    if (emitted == 0) then
        log_state(('state nativemenu blue-magic-inventory-cell-probe seq=%d result="none" obj=0x%08X child=0x%08X entry=0x%08X entryParent=0x%08X selected=%d count=%d note="probe-only no-speech-fallback"'):fmt(
            seq,
            obj,
            child,
            entry,
            entry_parent,
            selected,
            count));
    end

    return emitted;
end

function accessxi.blue_magic_inventory_offset_probe(obj, child, entry, selected, count, seq)
    obj = tonumber(obj) or 0;
    child = tonumber(child) or 0;
    entry = tonumber(entry) or 0;
    selected = tonumber(selected) or 0;
    count = tonumber(count) or 0;
    seq = tonumber(seq) or 0;

    if (not accessxi.is_probe_pointer(obj) and not accessxi.is_probe_pointer(child) and not accessxi.is_probe_pointer(entry)) then
        return 0;
    end

    local function field_summary(ptr, offsets)
        ptr = tonumber(ptr) or 0;
        if (not accessxi.is_probe_pointer(ptr)) then
            return '';
        end

        local parts = T{};
        for _, off in ipairs(offsets) do
            local u = read_u32(ptr + off) or 0;
            local i = read_i32(ptr + off) or 0;
            local lo = bit.band(u, 0xFFFF);
            local hi = math.floor(u / 0x10000);
            parts:append(('+%03X.u=%u/+%08X +%03X.i=%d +%03X.lo=%u +%03X.hi=%u'):fmt(
                off,
                u,
                u,
                off,
                i,
                off,
                lo,
                off,
                hi));
        end
        return parts:concat(' | ');
    end

    local obj_start_raw = accessxi.is_probe_pointer(obj) and (read_i32(obj + 0x30) or 0) or 0;
    local objStartCandidate = 0;
    local objGlobalCandidate = 0;
    if (obj_start_raw >= 1 and obj_start_raw <= 512 and selected >= 1) then
        objStartCandidate = obj_start_raw;
        objGlobalCandidate = objStartCandidate + selected - 1;
    end

    local childPackedSelected = accessxi.is_probe_pointer(child) and (read_u32(child + 0x24) or 0) or 0;
    local childPackedLow = bit.band(childPackedSelected, 0xFFFF);
    local childPackedHigh = math.floor(childPackedSelected / 0x10000);

    log_state(('state nativemenu blue-magic-inventory-offset-probe seq=%d select=%d count=%d obj=0x%08X child=0x%08X entry=0x%08X objFields="%s" childFields="%s" entryFields="%s" objStartRaw=%d objStartCandidate=%d objGlobalCandidate=%d childPackedSelected=0x%08X childPackedLow=%u childPackedHigh=%u note="probe-only no-speech-fallback"'):fmt(
        seq,
        selected,
        count,
        obj,
        child,
        entry,
        accessxi.escape_probe_log_text(field_summary(obj, T{ 0x24, 0x28, 0x2C, 0x30, 0x34, 0x4C, 0x54, 0x58, 0x5C })),
        accessxi.escape_probe_log_text(field_summary(child, T{ 0x18, 0x1C, 0x20, 0x24, 0x28, 0x2C, 0x30, 0xA4, 0xA8, 0xAC, 0xB0 })),
        accessxi.escape_probe_log_text(field_summary(entry, T{ 0x24, 0x38, 0x48, 0x58, 0x5C })),
        obj_start_raw,
        objStartCandidate,
        objGlobalCandidate,
        childPackedSelected,
        childPackedLow,
        childPackedHigh));

    return 1;
end

function accessxi.blue_magic_inventory_blue_mix_probe(obj, child, entry, selected, count, seq)
    obj = tonumber(obj) or 0;
    child = tonumber(child) or 0;
    entry = tonumber(entry) or 0;
    selected = tonumber(selected) or 0;
    count = tonumber(count) or 0;
    seq = tonumber(seq) or 0;

    local spells, order, reason = accessxi.blue_magic_mix_spell_list();
    local mix_count = (spells ~= nil) and spells:len() or 0;
    local by_raw = {};
    local by_id = {};
    if (spells ~= nil) then
        for index, spell in ipairs(spells) do
            local raw_id = tonumber(spell.raw_id) or 0;
            if (raw_id > 0) then
                by_raw[raw_id] = T{ index = index, spell = spell };
            end
            local spell_id = tonumber(spell.id) or 0;
            if (spell_id > 0) then
                by_id[spell_id] = index;
            end
        end
    end

    local function format_spell(index, spell)
        if (spell == nil) then
            return ('%d:none'):fmt(tonumber(index) or 0);
        end
        return ('%d:raw%d:id%d:%s'):fmt(
            tonumber(index) or 0,
            tonumber(spell.raw_id) or 0,
            tonumber(spell.id) or 0,
            accessxi.escape_probe_log_text(spell.name or ''));
    end

    local function add_index_candidate(out, source, index)
        index = tonumber(index) or 0;
        if (index <= 0) then
            return;
        end

        local spell = (spells ~= nil and index <= mix_count) and spells[index] or nil;
        out:append(('%s=%s'):fmt(tostring(source or ''), format_spell(index, spell)));
    end

    local function add_raw_candidate(out, seen, source, raw_id)
        raw_id = tonumber(raw_id) or 0;
        local item = by_raw[raw_id];
        if (item == nil) then
            return;
        end

        local spell = item.spell;
        local key = ('%s:%d'):fmt(tostring(source or ''), raw_id);
        if (seen[key] == true) then
            return;
        end
        seen[key] = true;
        out:append(('%s=raw%d:%s'):fmt(
            tostring(source or ''),
            raw_id,
            format_spell(tonumber(item.index) or 0, spell)));
    end

    local function candidate_window(center)
        center = tonumber(center) or 0;
        if (spells == nil or mix_count <= 0 or center <= 0) then
            return '';
        end

        local parts = T{};
        local first = math.max(1, center - 2);
        local last = math.min(mix_count, center + 2);
        for index = first, last do
            parts:append(format_spell(index, spells[index]));
        end
        return parts:concat(' | ');
    end

    local function byte_summary(ptr, label, offsets)
        ptr = tonumber(ptr) or 0;
        if (not accessxi.is_probe_pointer(ptr)) then
            return '';
        end

        local parts = T{};
        for _, off in ipairs(offsets) do
            local byte_value = read_u8(ptr + off);
            if (byte_value ~= nil) then
                parts:append(('%s+%02X=%02X'):fmt(tostring(label or ''), off, byte_value));
            end
        end
        return parts:concat(' ');
    end

    local child_packed = accessxi.is_probe_pointer(child) and (read_u32(child + 0x24) or 0) or 0;
    local child_low = bit.band(child_packed, 0xFFFF);
    local child_high = math.floor(child_packed / 0x10000);
    local entry_row_code = accessxi.is_probe_pointer(entry) and (read_u32(entry + 0x38) or 0) or 0;
    local entry_row_index = math.floor(entry_row_code / 0x10000);
    local entry_row_order = bit.band(entry_row_code, 0xFFFF);

    local index_candidates = T{};
    add_index_candidate(index_candidates, 'selected', selected);
    add_index_candidate(index_candidates, 'childLow', child_low);
    add_index_candidate(index_candidates, 'childHigh', child_high);
    add_index_candidate(index_candidates, 'childHighPlusSelectedMinus1', child_high + selected - 1);
    add_index_candidate(index_candidates, 'entryRowIndex', entry_row_index);

    local raw_candidates = T{};
    local seen_raw_candidates = {};
    local function scan_bytes(ptr, label, offsets)
        ptr = tonumber(ptr) or 0;
        if (not accessxi.is_probe_pointer(ptr)) then
            return;
        end
        for _, off in ipairs(offsets) do
            if (raw_candidates:len() >= 8) then
                return;
            end
            add_raw_candidate(raw_candidates, seen_raw_candidates, ('%s+%02X.b'):fmt(tostring(label or ''), off), read_u8(ptr + off));
        end
    end

    local entry_offsets = T{ 0x20, 0x21, 0x22, 0x23, 0x24, 0x25, 0x26, 0x27, 0x38, 0x39, 0x3A, 0x3B, 0x40, 0x44, 0x48, 0x4C, 0x50, 0x54, 0x58, 0x5C };
    local child_offsets = T{ 0x18, 0x19, 0x1A, 0x1B, 0x20, 0x21, 0x22, 0x23, 0x24, 0x25, 0x26, 0x27, 0x28, 0x2C, 0x30 };
    local obj_offsets = T{ 0x24, 0x28, 0x2C, 0x30, 0x34, 0x4C, 0x54, 0x58, 0x5C };
    scan_bytes(entry, 'entry', entry_offsets);
    scan_bytes(child, 'child', child_offsets);
    scan_bytes(obj, 'obj', obj_offsets);

    local anchor = accessxi.blue_magic_inventory_anchor;
    local anchor_spell_id = type(anchor) == 'table' and (tonumber(anchor.spell_id) or 0) or 0;
    local anchor_mix_index = anchor_spell_id > 0 and (tonumber(by_id[anchor_spell_id]) or 0) or 0;
    local anchor_name = '';
    if (anchor_spell_id > 0) then
        local anchor_info = accessxi.magic_spell_resource_info(anchor_spell_id);
        anchor_name = anchor_info ~= nil and tostring(anchor_info.name or '') or '';
    end

    local packed_index = child_high + selected - 1;
    local bytes = T{};
    local entry_bytes = byte_summary(entry, 'entry', entry_offsets);
    local child_bytes = byte_summary(child, 'child', child_offsets);
    local obj_bytes = byte_summary(obj, 'obj', obj_offsets);
    if (entry_bytes ~= '') then bytes:append(entry_bytes); end
    if (child_bytes ~= '') then bytes:append(child_bytes); end
    if (obj_bytes ~= '') then bytes:append(obj_bytes); end

    log_state(('state nativemenu blue-magic-inventory-blue-mix-probe seq=%d select=%d count=%d obj=0x%08X child=0x%08X entry=0x%08X mixCount=%d mixPath="%s" mixReason="%s" childPacked=0x%08X childLow=%u childHigh=%u entryRowIndex=%d entryRowOrder=0x%04X anchorSpellId=%d anchorMixIndex=%d anchorName="%s" indexCandidates="%s" rawCandidates="%s" selectedWindow="%s" packedWindow="%s" bytes="%s" note="probe-only no-speech-fallback"'):fmt(
        seq,
        selected,
        count,
        obj,
        child,
        entry,
        mix_count,
        accessxi.escape_probe_log_text(order ~= nil and tostring(order.path or '') or ''),
        accessxi.escape_probe_log_text(reason or ''),
        child_packed,
        child_low,
        child_high,
        entry_row_index,
        entry_row_order,
        anchor_spell_id,
        anchor_mix_index,
        accessxi.escape_probe_log_text(anchor_name),
        accessxi.escape_probe_log_text_wide(index_candidates:concat(' | ')),
        accessxi.escape_probe_log_text_wide(raw_candidates:concat(' | ')),
        accessxi.escape_probe_log_text_wide(candidate_window(selected)),
        accessxi.escape_probe_log_text_wide(candidate_window(packed_index)),
        accessxi.escape_probe_log_text(bytes:concat(' | '))));

    return 1;
end

function accessxi.blue_magic_inventory_scroll_probe(obj, child, entry, selected, count, seq)
    obj = tonumber(obj) or 0;
    child = tonumber(child) or 0;
    entry = tonumber(entry) or 0;
    selected = tonumber(selected) or 0;
    count = tonumber(count) or 0;
    seq = tonumber(seq) or 0;

    local spells = accessxi.blue_magic_mix_spell_list();
    local mix_count = (spells ~= nil) and spells:len() or 0;
    local max_value = math.max(mix_count + 20, count + 20, 128);

    local function word_fields(ptr, label, start_offset, end_offset, limit)
        ptr = tonumber(ptr) or 0;
        if (not accessxi.is_probe_pointer(ptr)) then
            return '';
        end

        local parts = T{};
        for off = tonumber(start_offset) or 0, tonumber(end_offset) or 0, 2 do
            local value = read_u16(ptr + off);
            if (value ~= nil and value > 0 and value <= max_value) then
                parts:append(('%s+%03X=%d'):fmt(tostring(label or ''), off, value));
                if (parts:len() >= (tonumber(limit) or 36)) then
                    break;
                end
            end
        end
        return parts:concat(' ');
    end

    local function byte_fields(ptr, label, start_offset, end_offset, limit)
        ptr = tonumber(ptr) or 0;
        if (not accessxi.is_probe_pointer(ptr)) then
            return '';
        end

        local parts = T{};
        for off = tonumber(start_offset) or 0, tonumber(end_offset) or 0 do
            local value = read_u8(ptr + off);
            if (value ~= nil and value > 0 and value <= max_value) then
                parts:append(('%s+%03X=%d'):fmt(tostring(label or ''), off, value));
                if (parts:len() >= (tonumber(limit) or 36)) then
                    break;
                end
            end
        end
        return parts:concat(' ');
    end

    local function dword_fields(ptr, label, start_offset, end_offset, limit)
        ptr = tonumber(ptr) or 0;
        if (not accessxi.is_probe_pointer(ptr)) then
            return '';
        end

        local parts = T{};
        for off = tonumber(start_offset) or 0, tonumber(end_offset) or 0, 4 do
            local value = read_u32(ptr + off);
            if (value ~= nil and value > 0 and value <= max_value) then
                parts:append(('%s+%03X=%d'):fmt(tostring(label or ''), off, value));
                if (parts:len() >= (tonumber(limit) or 24)) then
                    break;
                end
            end
        end
        return parts:concat(' ');
    end

    local child_packed = accessxi.is_probe_pointer(child) and (read_u32(child + 0x24) or 0) or 0;
    local child_low = bit.band(child_packed, 0xFFFF);
    local child_high = math.floor(child_packed / 0x10000);
    local entry_row_code = accessxi.is_probe_pointer(entry) and (read_u32(entry + 0x38) or 0) or 0;
    local entry_row_index = math.floor(entry_row_code / 0x10000);
    local entry_row_order = bit.band(entry_row_code, 0xFFFF);

    log_state(('state nativemenu blue-magic-inventory-scroll-probe seq=%d select=%d count=%d mixCount=%d obj=0x%08X child=0x%08X entry=0x%08X childPacked=0x%08X childLow=%u childHigh=%u entryRowIndex=%d entryRowOrder=0x%04X objD="%s" childD="%s" entryD="%s" objW="%s" childW="%s" entryW="%s" objB="%s" childB="%s" entryB="%s" note="probe-only no-speech-fallback"'):fmt(
        seq,
        selected,
        count,
        mix_count,
        obj,
        child,
        entry,
        child_packed,
        child_low,
        child_high,
        entry_row_index,
        entry_row_order,
        accessxi.escape_probe_log_text(dword_fields(obj, 'obj', 0x00, 0xC0, 24)),
        accessxi.escape_probe_log_text(dword_fields(child, 'child', 0x00, 0xE0, 24)),
        accessxi.escape_probe_log_text(dword_fields(entry, 'entry', 0x00, 0xC0, 24)),
        accessxi.escape_probe_log_text(word_fields(obj, 'obj', 0x00, 0xC0, 36)),
        accessxi.escape_probe_log_text(word_fields(child, 'child', 0x00, 0xE0, 36)),
        accessxi.escape_probe_log_text(word_fields(entry, 'entry', 0x00, 0xC0, 36)),
        accessxi.escape_probe_log_text(byte_fields(obj, 'obj', 0x00, 0xC0, 36)),
        accessxi.escape_probe_log_text(byte_fields(child, 'child', 0x00, 0xE0, 36)),
        accessxi.escape_probe_log_text(byte_fields(entry, 'entry', 0x00, 0xC0, 36))));

    return 1;
end

function accessxi.blue_magic_inventory_edge_scroll_probe(obj, child, entry, selected, count, page, raw)
    obj = tonumber(obj) or 0;
    child = tonumber(child) or 0;
    entry = tonumber(entry) or 0;
    selected = tonumber(selected) or 0;
    count = tonumber(count) or 0;
    page = tonumber(page) or 0;
    raw = tonumber(raw) or 0;

    local visible_count, visible_source = accessxi.blue_magic_inventory_anchor_visible_count(obj, child);
    visible_count = tonumber(visible_count) or 0;
    if (selected <= 0 or visible_count <= 0) then
        return 0;
    end
    if (selected > 1 and selected < visible_count) then
        return 0;
    end

    local edge_count = tonumber(accessxi.blue_magic_inventory_edge_probe_count) or 0;
    if (edge_count >= 80) then
        return 0;
    end

    local now = tick();
    local child_packed = accessxi.is_probe_pointer(child) and (read_u32(child + 0x24) or 0) or 0;
    local child_low = bit.band(child_packed, 0xFFFF);
    local child_high = math.floor(child_packed / 0x10000);
    local entry_row_code = accessxi.is_probe_pointer(entry) and (read_u32(entry + 0x38) or 0) or 0;
    local entry_row_index = math.floor(entry_row_code / 0x10000);
    local entry_row_order = bit.band(entry_row_code, 0xFFFF);
    local obj_cursor = accessxi.is_probe_pointer(obj) and (read_i32(obj + 0x4C) or 0) or 0;
    local obj_count_a = accessxi.is_probe_pointer(obj) and (read_i32(obj + 0x24) or 0) or 0;
    local obj_count_b = accessxi.is_probe_pointer(obj) and (read_i32(obj + 0x28) or 0) or 0;
    local obj_visible = accessxi.is_probe_pointer(obj) and (read_i32(obj + 0x58) or 0) or 0;
    local obj_state = accessxi.is_probe_pointer(obj) and (read_i32(obj + 0x5C) or 0) or 0;
    local child_window = accessxi.is_probe_pointer(child) and (read_u32(child + 0x18) or 0) or 0;
    local child_window2 = accessxi.is_probe_pointer(child) and (read_u32(child + 0x1C) or 0) or 0;
    local entry_key_a = accessxi.is_probe_pointer(entry) and (read_u32(entry + 0x24) or 0) or 0;
    local entry_key_b = accessxi.is_probe_pointer(entry) and (read_u32(entry + 0x54) or 0) or 0;

    local key = ('%d:%d:%d:%d:%d:%d:%08X:%08X:%08X:%08X:%08X:%08X'):fmt(
        selected,
        visible_count,
        page,
        raw,
        obj_cursor,
        obj_visible,
        child_packed,
        entry_row_code,
        child_window,
        child_window2,
        entry_key_a,
        entry_key_b);
    if (key == tostring(accessxi.last_blue_magic_inventory_edge_probe_key or '')
        and (now - (tonumber(accessxi.last_blue_magic_inventory_edge_probe_tick) or 0)) < 250) then
        return 0;
    end
    accessxi.last_blue_magic_inventory_edge_probe_key = key;
    accessxi.last_blue_magic_inventory_edge_probe_tick = now;

    edge_count = edge_count + 1;
    accessxi.blue_magic_inventory_edge_probe_count = edge_count;

    local function field_summary(ptr, label, offsets)
        ptr = tonumber(ptr) or 0;
        if (not accessxi.is_probe_pointer(ptr)) then
            return '';
        end
        local parts = T{};
        for _, off in ipairs(offsets) do
            local value = read_u32(ptr + off);
            if (value ~= nil) then
                parts:append(('%s+%02X=%u/0x%08X'):fmt(tostring(label or ''), off, value, value));
            end
        end
        return parts:concat(' ');
    end

    local function byte_summary(ptr, label, offsets)
        ptr = tonumber(ptr) or 0;
        if (not accessxi.is_probe_pointer(ptr)) then
            return '';
        end
        local parts = T{};
        for _, off in ipairs(offsets) do
            local value = read_u8(ptr + off);
            if (value ~= nil) then
                parts:append(('%s+%02X=%02X'):fmt(tostring(label or ''), off, value));
            end
        end
        return parts:concat(' ');
    end

    local spells = accessxi.blue_magic_mix_spell_list();
    local mix_count = (spells ~= nil) and spells:len() or 0;
    log_state(('state nativemenu blue-magic-inventory-edge-scroll-watch seq=%d select=%d visible=%d visibleSource="%s" count=%d page=%d raw=0x%08X obj=0x%08X child=0x%08X entry=0x%08X objCursor=%d objCountA=%d objCountB=%d objVisible=%d objState=%d childPacked=0x%08X childLow=%u childHigh=%u childWindow=0x%08X childWindow2=0x%08X entryRowIndex=%d entryRowOrder=0x%04X mixCount=%d objFields="%s" childFields="%s" entryFields="%s" entryBytes="%s" note="probe-only no-speech-fallback"'):fmt(
        edge_count,
        selected,
        visible_count,
        accessxi.escape_probe_log_text(visible_source or ''),
        count,
        page,
        raw,
        obj,
        child,
        entry,
        obj_cursor,
        obj_count_a,
        obj_count_b,
        obj_visible,
        obj_state,
        child_packed,
        child_low,
        child_high,
        child_window,
        child_window2,
        entry_row_index,
        entry_row_order,
        mix_count,
        accessxi.escape_probe_log_text(field_summary(obj, 'obj', T{ 0x24, 0x28, 0x34, 0x4C, 0x50, 0x54, 0x58, 0x5C, 0x60, 0x64 })),
        accessxi.escape_probe_log_text(field_summary(child, 'child', T{ 0x18, 0x1C, 0x20, 0x24, 0x28, 0x2C, 0x30 })),
        accessxi.escape_probe_log_text(field_summary(entry, 'entry', T{ 0x20, 0x24, 0x28, 0x38, 0x3C, 0x40, 0x44, 0x48, 0x4C, 0x50, 0x54, 0x58, 0x5C })),
        accessxi.escape_probe_log_text(byte_summary(entry, 'entry', T{ 0x20, 0x21, 0x22, 0x23, 0x24, 0x25, 0x26, 0x27, 0x38, 0x39, 0x3A, 0x3B, 0x54, 0x55, 0x56, 0x57 }))));
    return 1;
end

function accessxi.log_blue_magic_inventory_probe(menu_name, title, selected, count, page, raw, obj, child, entry, labels, reason)
    labels = labels or T{};
    local label_text = T{};
    for _, item in ipairs(labels) do
        label_text:append(('%s="%s"'):fmt(
            accessxi.escape_probe_log_text(item.source or ''),
            accessxi.escape_probe_log_text(item.label or '')));
    end

    obj = tonumber(obj) or 0;
    child = tonumber(child) or 0;
    entry = tonumber(entry) or 0;
    selected = tonumber(selected) or 0;
    count = tonumber(count) or 0;
    page = tonumber(page) or 0;
    raw = tonumber(raw) or 0;

    local key = ('%s:%d:%d:%d:%08X:%08X:%08X:%s:%s'):fmt(
        tostring(menu_name or ''),
        selected,
        count,
        page,
        obj,
        child,
        entry,
        tostring(reason or ''),
        label_text:concat('|'));
    accessxi.blue_magic_inventory_edge_scroll_probe(obj, child, entry, selected, count, page, raw);
    if (key == tostring(accessxi.last_blue_magic_inventory_probe_key or '')) then
        return;
    end
    accessxi.last_blue_magic_inventory_probe_key = key;

    local probe_count = tonumber(accessxi.blue_magic_inventory_probe_count) or 0;
    if (probe_count >= 80) then
        return;
    end
    probe_count = probe_count + 1;
    accessxi.blue_magic_inventory_probe_count = probe_count;

    log_state(('state nativemenu blue-magic-inventory-probe seq=%d menu="%s" title="%s" select=%d count=%d page=%d raw=0x%08X reason="%s" obj=0x%08X child=0x%08X entry=0x%08X labels="%s" note="compact probe-only no-speech-fallback"'):fmt(
        probe_count,
        tostring(menu_name or ''),
        tostring(title or ''),
        selected,
        count,
        page,
        raw,
        accessxi.escape_probe_log_text(reason or ''),
        obj,
        child,
        entry,
        accessxi.escape_probe_log_text_wide(label_text:concat(' | '))));
    local blue_magic_inventory_offset_probe_lines = accessxi.blue_magic_inventory_offset_probe(obj, child, entry, selected, count, probe_count);
    if ((tonumber(blue_magic_inventory_offset_probe_lines) or 0) <= 0) then
        log_state(('state nativemenu blue-magic-inventory-offset-probe seq=%d result="none" obj=0x%08X child=0x%08X entry=0x%08X note="probe-only no-speech-fallback"'):fmt(
            probe_count,
            obj,
            child,
            entry));
    end
    local blue_magic_inventory_blue_mix_probe_lines = accessxi.blue_magic_inventory_blue_mix_probe(obj, child, entry, selected, count, probe_count);
    if ((tonumber(blue_magic_inventory_blue_mix_probe_lines) or 0) <= 0) then
        log_state(('state nativemenu blue-magic-inventory-blue-mix-probe seq=%d result="none" obj=0x%08X child=0x%08X entry=0x%08X note="probe-only no-speech-fallback"'):fmt(
            probe_count,
            obj,
            child,
            entry));
    end
    local blue_magic_inventory_scroll_probe_lines = accessxi.blue_magic_inventory_scroll_probe(obj, child, entry, selected, count, probe_count);
    if ((tonumber(blue_magic_inventory_scroll_probe_lines) or 0) <= 0) then
        log_state(('state nativemenu blue-magic-inventory-scroll-probe seq=%d result="none" obj=0x%08X child=0x%08X entry=0x%08X note="probe-only no-speech-fallback"'):fmt(
            probe_count,
            obj,
            child,
            entry));
    end
end

function accessxi.blue_magic_inventory_menu_speech(menu_name, title, obj, selected, count, page, raw, child, entry)
    menu_name = tostring(menu_name or '');
    if (not menu_name:eq('menu    bluinven', true)) then
        return nil;
    end

    title = accessxi.plain_native_menu_label(title or '');
    if (title == '') then
        title = 'Blue Magic';
    end
    obj = tonumber(obj) or 0;
    child = tonumber(child) or 0;
    entry = tonumber(entry) or 0;
    selected = tonumber(selected) or 0;
    count = tonumber(count) or 0;
    page = tonumber(page) or 0;
    raw = tonumber(raw) or 0;

    local obj_selected = read_current_native_menu_index(0x4C);
    if (obj_selected > 0) then
        selected = obj_selected;
    end
    if (count <= 0 or count > 64) then
        count = math.max(tonumber(accessxi.native_menu_index(0x24)) or 0, tonumber(accessxi.native_menu_index(0x28)) or 0);
    end

    local labels = T{};
    local seen_labels = {};
    local function add_label(source, label)
        label = accessxi.blue_magic_set_clean_native_label(label or '');
        if (label == '') then
            return;
        end
        local key = label:lower();
        if (seen_labels[key] == true) then
            return;
        end
        seen_labels[key] = true;
        labels:append(T{ source = tostring(source or ''), label = label });
    end

    local rendered_label = accessxi.magic_rendered_row_text(entry, selected);
    add_label('rendered-row', rendered_label);

    if (accessxi.is_probe_pointer(entry)) then
        local label_ptr = read_u32(entry + 0x44) or 0;
        local help_ptr = read_u32(entry + 0x40) or 0;
        add_label('entry+44', read_probe_string(label_ptr, 160));
        add_label('entry+40', read_probe_string(help_ptr, 220));
    end

    local player = safe_call(function () return AshitaCore:GetMemoryManager():GetPlayer(); end, nil);
    for _, item in ipairs(labels) do
        local spell, match_count, match_source = accessxi.blue_magic_spell_from_exact_label(item.label);
        if (spell ~= nil
            and tonumber(spell.type) == 6
            and (player == nil or safe_call(function () return player:HasSpell(spell.id); end, false) == true)) then
            local parts = T{ title, spell.name };
            accessxi.blue_magic_set_append_spell_details(parts, spell);
            local speech = accessxi.speech_output_text(parts:concat('. '));
            if (speech ~= '') then
                accessxi.last_native_menu_name = menu_name;
                accessxi.last_native_menu_label = spell.name;
                accessxi.last_native_menu_selected = selected;
                accessxi.last_native_menu_tick = tick();
                accessxi.current_speech_key = ('native-blue-inventory-row:%s:%d:%d:%s:%s'):fmt(
                    menu_name,
                    selected,
                    tonumber(spell.id) or 0,
                    tostring(item.source or ''),
                    tostring(spell.name or ''));
                local point_info = accessxi.blue_magic_set_points_info();
                local set_cost = accessxi.blue_magic_set_point_cost(spell.id);
                log_state(('state nativemenu blue-magic-inventory-native-row menu="%s" title="%s" select=%d count=%d page=%d raw=0x%08X entry=0x%08X spellId=%d type=%d setCost=%d mp=%d bluSpent=%d bluMax=%d bluAvailable=%d source="%s" matchSource="%s" matchCount=%d label="%s" rendered="%s" descLen=%d renderCells="%s"'):fmt(
                    menu_name,
                    title,
                    selected,
                    count,
                    page,
                    raw,
                    entry,
                    tonumber(spell.id) or 0,
                    tonumber(spell.type) or 0,
                    tonumber(set_cost) or 0,
                    tonumber(spell.mp) or 0,
                    point_info ~= nil and (tonumber(point_info.spent) or 0) or 0,
                    point_info ~= nil and (tonumber(point_info.max) or 0) or 0,
                    point_info ~= nil and (tonumber(point_info.available) or 0) or 0,
                    accessxi.escape_probe_log_text(item.source or ''),
                    accessxi.escape_probe_log_text(match_source or ''),
                    tonumber(match_count) or 0,
                    accessxi.escape_probe_log_text(item.label or ''),
                    accessxi.escape_probe_log_text(rendered_label or ''),
                    #(tostring(spell.description or '')),
                    accessxi.escape_probe_log_text(accessxi.last_magic_render_cells or '')));
                return speech;
            end
        end
    end

    local anchor_spell, anchor_index, anchor_selected, anchor_base_index, anchor_spell_id, anchor_reason = accessxi.blue_magic_inventory_spell_from_anchor(obj, child, entry, selected);
    if (anchor_spell ~= nil) then
        local parts = T{ title, anchor_spell.name };
        accessxi.blue_magic_set_append_spell_details(parts, anchor_spell);
        local speech = accessxi.speech_output_text(parts:concat('. '));
        if (speech ~= '') then
            accessxi.last_native_menu_name = menu_name;
            accessxi.last_native_menu_label = anchor_spell.name;
            accessxi.last_native_menu_selected = anchor_index;
            accessxi.last_native_menu_tick = tick();
            accessxi.current_speech_key = ('native-blue-inventory-anchor:%s:%d:%d:%d:%d:%s'):fmt(
                menu_name,
                selected,
                tonumber(anchor_index) or 0,
                tonumber(anchor_base_index) or 0,
                tonumber(anchor_spell.id) or 0,
                tostring(anchor_spell.name or ''));
            local point_info = accessxi.blue_magic_set_points_info();
            local set_cost = accessxi.blue_magic_set_point_cost(anchor_spell.id);
            local anchor_state = accessxi.blue_magic_inventory_anchor or {};
            log_state(('state nativemenu blue-magic-inventory-anchor menu="%s" title="%s" select=%d anchorSelected=%d anchorIndex=%d globalIndex=%d anchorSpellId=%d spellId=%d type=%d setCost=%d mp=%d bluSpent=%d bluMax=%d bluAvailable=%d obj=0x%08X child=0x%08X entry=0x%08X visibleCount=%d visibleSource="%s" scrollSelect=%d scrollStart=%d previousScrollStart=%d selectedDelta=%d windowDelta=%d nativeMotionDelta=%d motionDelta=%d windowMotionLimit=%d source="%s" rendered="%s" descLen=%d renderCells="%s"'):fmt(
                menu_name,
                title,
                selected,
                tonumber(anchor_selected) or 0,
                tonumber(anchor_base_index) or 0,
                tonumber(anchor_index) or 0,
                tonumber(anchor_spell_id) or 0,
                tonumber(anchor_spell.id) or 0,
                tonumber(anchor_spell.type) or 0,
                tonumber(set_cost) or 0,
                tonumber(anchor_spell.mp) or 0,
                point_info ~= nil and (tonumber(point_info.spent) or 0) or 0,
                point_info ~= nil and (tonumber(point_info.max) or 0) or 0,
                point_info ~= nil and (tonumber(point_info.available) or 0) or 0,
                obj,
                child,
                entry,
                tonumber(anchor_state.visible_count) or 0,
                accessxi.escape_probe_log_text(anchor_state.visible_source or ''),
                tonumber(anchor_state.last_scroll_selected) or 0,
                tonumber(anchor_state.last_scroll_window_start) or 0,
                tonumber(anchor_state.last_scroll_window_start_previous) or 0,
                tonumber(anchor_state.last_selected_delta) or 0,
                tonumber(anchor_state.last_window_delta) or 0,
                tonumber(anchor_state.last_native_motion_delta) or 0,
                tonumber(anchor_state.last_motion_delta) or 0,
                tonumber(anchor_state.last_window_motion_limit) or 0,
                accessxi.escape_probe_log_text(anchor_reason or ''),
                accessxi.escape_probe_log_text(rendered_label or ''),
                #(tostring(anchor_spell.description or '')),
                accessxi.escape_probe_log_text(accessxi.last_magic_render_cells or '')));
            return speech;
        end
    end

    local scroll_spell, scroll_selected, scroll_start, scroll_visible, scroll_window, scroll_window2, scroll_order, scroll_reason, scroll_total, scroll_type = accessxi.blue_magic_inventory_spell_from_native_scroll(obj, child, selected);
    if (scroll_spell ~= nil) then
        local quiet_key = ('scroll-candidate:%s:%d:%d:%d:%d:%d:%s'):fmt(
            menu_name,
            selected,
            tonumber(scroll_selected) or 0,
            tonumber(scroll_start) or 0,
            tonumber(scroll_visible) or 0,
            tonumber(scroll_spell.id) or 0,
            tostring(scroll_reason or ''));
        if (quiet_key ~= tostring(accessxi.last_blue_magic_inventory_scroll_quiet_key or '')) then
            accessxi.last_blue_magic_inventory_scroll_quiet_key = quiet_key;
            local point_info = accessxi.blue_magic_set_points_info();
            local set_cost = accessxi.blue_magic_set_point_cost(scroll_spell.id);
            local scroll_path = scroll_order ~= nil and tostring(scroll_order.path or '') or '';
            local scroll_short_path = scroll_path:match('FINAL FANTASY XI\\(.+)$') or scroll_path;
            log_state(('state nativemenu blue-magic-inventory-native-scroll-candidate menu="%s" title="%s" visibleSelect=%d scrollSelect=%d windowStart=%d visible=%d childWindow=0x%08X childWindow2=0x%08X count=%d page=%d raw=0x%08X entry=0x%08X spellId=%d type=%d setCost=%d mp=%d bluSpent=%d bluMax=%d bluAvailable=%d total=%d source="%s" path="%s" label="%s" rendered="%s" descLen=%d renderCells="%s" note="probe-only no-speech-fallback"'):fmt(
                menu_name,
                title,
                selected,
                tonumber(scroll_selected) or 0,
                tonumber(scroll_start) or 0,
                tonumber(scroll_visible) or 0,
                tonumber(scroll_window) or 0,
                tonumber(scroll_window2) or 0,
                count,
                page,
                raw,
                entry,
                tonumber(scroll_spell.id) or 0,
                tonumber(scroll_spell.type) or 0,
                tonumber(set_cost) or 0,
                tonumber(scroll_spell.mp) or 0,
                point_info ~= nil and (tonumber(point_info.spent) or 0) or 0,
                point_info ~= nil and (tonumber(point_info.max) or 0) or 0,
                point_info ~= nil and (tonumber(point_info.available) or 0) or 0,
                tonumber(scroll_total) or 0,
                accessxi.escape_probe_log_text(scroll_reason or ''),
                accessxi.escape_probe_log_text(scroll_short_path),
                accessxi.escape_probe_log_text(scroll_spell.name or ''),
                accessxi.escape_probe_log_text(rendered_label or ''),
                #(tostring(scroll_spell.description or '')),
                accessxi.escape_probe_log_text(accessxi.last_magic_render_cells or '')));
        end
    elseif (tostring(scroll_reason or '') ~= '' and not tostring(scroll_reason or ''):eq('child-or-selected', true)) then
        local quiet_key = ('scroll:%s:%d:%d:%d:%d:%s'):fmt(
            menu_name,
            selected,
            tonumber(scroll_selected) or 0,
            tonumber(scroll_start) or 0,
            tonumber(scroll_visible) or 0,
            tostring(scroll_reason or ''));
        if (quiet_key ~= tostring(accessxi.last_blue_magic_inventory_scroll_quiet_key or '')) then
            accessxi.last_blue_magic_inventory_scroll_quiet_key = quiet_key;
            log_state(('state nativemenu blue-magic-inventory-native-scroll-quiet menu="%s" title="%s" visibleSelect=%d scrollSelect=%d windowStart=%d visible=%d childWindow=0x%08X childWindow2=0x%08X count=%d entry=0x%08X type=%d total=%d reason="%s" note="no fixed-row fallback"'):fmt(
                menu_name,
                title,
                selected,
                tonumber(scroll_selected) or 0,
                tonumber(scroll_start) or 0,
                tonumber(scroll_visible) or 0,
                tonumber(scroll_window) or 0,
                tonumber(scroll_window2) or 0,
                count,
                entry,
                tonumber(scroll_type) or 0,
                tonumber(scroll_total) or 0,
                accessxi.escape_probe_log_text(scroll_reason or '')));
        end
    end

    local entry_spell, entry_match_count, entry_match_source, entry_details, entry_segment, entry_score, entry_second_score = accessxi.blue_magic_inventory_spell_from_native_entry(entry, selected);
    if (entry_spell ~= nil
        and tonumber(entry_spell.type) == 6
        and (player == nil or safe_call(function () return player:HasSpell(entry_spell.id); end, false) == true)) then
        local quiet_key = ('entry:%s:%d:%08X:%d:%d:%d:%s'):fmt(
            menu_name,
            selected,
            entry,
            tonumber(entry_spell.id) or 0,
            tonumber(entry_score) or 0,
            tonumber(entry_second_score) or 0,
            tostring(entry_segment or ''));
        if (quiet_key ~= tostring(accessxi.last_blue_magic_inventory_entry_quiet_key or '')) then
            accessxi.last_blue_magic_inventory_entry_quiet_key = quiet_key;
            local point_info = accessxi.blue_magic_set_points_info();
            local set_cost = accessxi.blue_magic_set_point_cost(entry_spell.id);
            log_state(('state nativemenu blue-magic-inventory-native-entry-quiet menu="%s" title="%s" select=%d count=%d page=%d raw=0x%08X entry=0x%08X reason="native-entry-detail-unsafe" spellId=%d type=%d setCost=%d mp=%d bluSpent=%d bluMax=%d bluAvailable=%d source="%s" matchSource="%s" matchCount=%d bestScore=%d secondScore=%d bestDetail="%s" details="%s" rendered="%s" descLen=%d renderCells="%s" note="probe-only no-speech-fallback"'):fmt(
                menu_name,
                title,
                selected,
                count,
                page,
                raw,
                entry,
                tonumber(entry_spell.id) or 0,
                tonumber(entry_spell.type) or 0,
                tonumber(set_cost) or 0,
                tonumber(entry_spell.mp) or 0,
                point_info ~= nil and (tonumber(point_info.spent) or 0) or 0,
                point_info ~= nil and (tonumber(point_info.max) or 0) or 0,
                point_info ~= nil and (tonumber(point_info.available) or 0) or 0,
                'native-entry-details',
                accessxi.escape_probe_log_text(entry_match_source or ''),
                tonumber(entry_match_count) or 0,
                tonumber(entry_score) or 0,
                tonumber(entry_second_score) or 0,
                accessxi.escape_probe_log_text(entry_segment or ''),
                accessxi.escape_probe_log_text_wide(entry_details or ''),
                accessxi.escape_probe_log_text(rendered_label or ''),
                #(tostring(entry_spell.description or '')),
                accessxi.escape_probe_log_text(accessxi.last_magic_render_cells or '')));
        end
    elseif (tostring(entry_match_source or ''):eq('ambiguous-native-entry', true)) then
        local quiet_key = ('entry-ambiguous:%s:%d:%08X:%d:%d:%s'):fmt(
            menu_name,
            selected,
            entry,
            tonumber(entry_score) or 0,
            tonumber(entry_second_score) or 0,
            tostring(entry_segment or ''));
        if (quiet_key ~= tostring(accessxi.last_blue_magic_inventory_entry_quiet_key or '')) then
            accessxi.last_blue_magic_inventory_entry_quiet_key = quiet_key;
            log_state(('state nativemenu blue-magic-inventory-quiet menu="%s" title="%s" select=%d count=%d entry=0x%08X reason="ambiguous-native-entry" matchCount=%d bestScore=%d secondScore=%d detail="%s" details="%s" rendered="%s" note="probe-only no-speech-fallback"'):fmt(
                menu_name,
                title,
                selected,
                count,
                entry,
                tonumber(entry_match_count) or 0,
                tonumber(entry_score) or 0,
                tonumber(entry_second_score) or 0,
                accessxi.escape_probe_log_text(entry_segment or ''),
                accessxi.escape_probe_log_text_wide(entry_details or ''),
                accessxi.escape_probe_log_text(rendered_label or '')));
        end
    end

    local help_spell, help_count, help_source, help_title, help_text, help_title_ptr, help_ptr, window_name = accessxi.magic_spell_from_window_help();
    if (help_spell ~= nil
        and tonumber(help_spell.type) == 6
        and (player == nil or safe_call(function () return player:HasSpell(help_spell.id); end, false) == true)) then
        local parts = T{ title, help_spell.name };
        accessxi.blue_magic_set_append_spell_details(parts, help_spell);
        local speech = accessxi.speech_output_text(parts:concat('. '));
        if (speech ~= '') then
            accessxi.last_native_menu_name = menu_name;
            accessxi.last_native_menu_label = help_spell.name;
            accessxi.last_native_menu_selected = selected;
            accessxi.last_native_menu_tick = tick();
            accessxi.current_speech_key = ('native-blue-inventory-help:%s:%d:%d:%s'):fmt(
                menu_name,
                selected,
                tonumber(help_spell.id) or 0,
                tostring(help_source or ''));
            log_state(('state nativemenu blue-magic-inventory-window-help menu="%s" title="%s" select=%d count=%d entry=0x%08X spellId=%d source="%s" helpTitlePtr=0x%08X helpTitle="%s" helpPtr=0x%08X help="%s" window="%s" matches=%d'):fmt(
                menu_name,
                title,
                selected,
                count,
                entry,
                tonumber(help_spell.id) or 0,
                accessxi.escape_probe_log_text(help_source or ''),
                tonumber(help_title_ptr) or 0,
                accessxi.escape_probe_log_text(help_title or ''),
                tonumber(help_ptr) or 0,
                accessxi.escape_probe_log_text(help_text or ''),
                accessxi.escape_probe_log_text(window_name or ''),
                tonumber(help_count) or 0));
            return speech;
        end
    end

    if (tostring(anchor_reason or '') ~= 'no-anchor') then
        local anchor_state = accessxi.blue_magic_inventory_anchor or {};
        local quiet_key = ('anchor:%s:%d:%08X:%s:%d:%d:%d'):fmt(
            menu_name,
            selected,
            entry,
            tostring(anchor_reason or ''),
            tonumber(anchor_selected) or 0,
            tonumber(anchor_index) or 0,
            tonumber(anchor_spell_id) or 0);
        if (quiet_key ~= tostring(accessxi.last_blue_magic_inventory_anchor_quiet_key or '')) then
            accessxi.last_blue_magic_inventory_anchor_quiet_key = quiet_key;
        log_state(('state nativemenu blue-magic-inventory-anchor-quiet menu="%s" title="%s" select=%d reason="%s" anchorSelected=%d anchorIndex=%d globalIndex=%d anchorSpellId=%d obj=0x%08X child=0x%08X entry=0x%08X visibleCount=%d visibleSource="%s" note="no fixed-row fallback"'):fmt(
            menu_name,
            title,
            selected,
            accessxi.escape_probe_log_text(anchor_reason or ''),
            tonumber(anchor_selected) or 0,
            tonumber(anchor_base_index) or 0,
            tonumber(anchor_index) or 0,
            tonumber(anchor_spell_id) or 0,
            obj,
            child,
            entry,
            tonumber(anchor_state.visible_count) or 0,
            accessxi.escape_probe_log_text(anchor_state.visible_source or '')));
        end
    end

    accessxi.log_blue_magic_inventory_probe(menu_name, title, selected, count, page, raw, obj, child, entry, labels, 'no-exact-native-blue-spell');
    accessxi.blue_magic_inventory_log_missing(menu_name, title, selected, count, page, raw, obj, child, entry, labels, 'no-exact-native-blue-spell');
    return nil;
end

function accessxi.current_item_sort_confirmation_context()
    local now = tick();
    local label = tostring(accessxi.current_item_sort_label or '');
    local help = tostring(accessxi.current_item_sort_help or '');
    local title = tostring(accessxi.current_item_sort_title or '');
    local selected = tonumber(accessxi.current_item_sort_selected) or 0;
    local sort_age = now - (tonumber(accessxi.current_item_sort_tick) or 0);
    if (label == '' or sort_age < 0 or sort_age > 120000) then
        return nil, 'missing-item-sort-context';
    end

    local transition_age = now - (tonumber(accessxi.last_menu_transition_tick) or 0);
    local transition_from = tostring(accessxi.last_menu_transition_from or '');
    local transition_to = tostring(accessxi.last_menu_transition_to or '');
    if (transition_age < 0 or transition_age > 120000
        or not (transition_from:eq('menu    itmsort2', true) or transition_from:eq('menu    blusortw', true) or transition_from:eq('menu    mgcsortw', true))
        or not transition_to:eq('menu    sortyn', true)) then
        return nil, 'not-item-sort-transition';
    end

    return {
        label = label,
        help = help,
        title = title,
        selected = selected,
        sort_age = sort_age,
        transition_from = transition_from,
        transition_to = transition_to,
        transition_age = transition_age,
    }, '';
end

function accessxi.item_sort_confirmation_speech(menu_name, title, selected, count, entry)
    menu_name = tostring(menu_name or '');
    if (not menu_name:eq('menu    sortyn', true)) then
        return nil;
    end

    selected = tonumber(selected) or 0;
    count = tonumber(count) or 0;
    entry = tonumber(entry) or 0;
    if (selected <= 0) then
        selected = read_current_native_menu_index(0x4C);
    end

    local context, context_reason = accessxi.current_item_sort_confirmation_context();
    if (context == nil) then
        log_state(('state nativemenu item-sort-confirmation quiet menu="%s" title="%s" select=%d count=%d entry=0x%08X reason="%s" itemSortLabel="%s" transitionFrom="%s" transitionTo="%s"'):fmt(
            menu_name,
            tostring(title or ''),
            selected,
            count,
            entry,
            accessxi.escape_probe_log_text(context_reason or ''),
            accessxi.escape_probe_log_text(accessxi.current_item_sort_label or ''),
            accessxi.escape_probe_log_text(accessxi.last_menu_transition_from or ''),
            accessxi.escape_probe_log_text(accessxi.last_menu_transition_to or '')));
        return nil;
    end

    local prompt = accessxi.dat_index_row_text('ROM\\97\\40.DAT', 60, 'help');
    if (prompt == '') then
        log_state(('state nativemenu item-sort-confirmation quiet menu="%s" title="%s" select=%d count=%d entry=0x%08X reason="missing-prompt-dat" itemSortLabel="%s" source="ROM\\97\\40.DAT#60"'):fmt(
            menu_name,
            tostring(title or ''),
            selected,
            count,
            entry,
            accessxi.escape_probe_log_text(context.label or '')));
        return nil;
    end

    local choice = '';
    local choice_source = '';
    if (selected == 1) then
        choice = accessxi.dat_index_row_text('ROM\\97\\37.DAT', 106, 'label');
        choice_source = 'ROM\\97\\37.DAT#106';
    elseif (selected == 2) then
        choice = accessxi.dat_index_row_text('ROM\\97\\37.DAT', 107, 'label');
        choice_source = 'ROM\\97\\37.DAT#107';
    else
        log_state(('state nativemenu item-sort-confirmation unsupported-row menu="%s" title="%s" select=%d count=%d entry=0x%08X itemSortLabel="%s" prompt="%s"'):fmt(
            menu_name,
            tostring(title or ''),
            selected,
            count,
            entry,
            accessxi.escape_probe_log_text(context.label or ''),
            accessxi.escape_probe_log_text(prompt)));
        return nil;
    end
    if (choice == '') then
        log_state(('state nativemenu item-sort-confirmation quiet menu="%s" title="%s" select=%d count=%d entry=0x%08X reason="missing-choice-dat" itemSortLabel="%s" prompt="%s" source="%s"'):fmt(
            menu_name,
            tostring(title or ''),
            selected,
            count,
            entry,
            accessxi.escape_probe_log_text(context.label or ''),
            accessxi.escape_probe_log_text(prompt),
            choice_source));
        return nil;
    end

    local speech_parts = T{};
    speech_parts:append(context.label);
    speech_parts:append(prompt);
    speech_parts:append(choice);
    local speech = accessxi.speech_output_text(speech_parts:concat('. '));
    if (speech == '') then
        return nil;
    end

    accessxi.last_native_menu_name = menu_name;
    accessxi.last_native_menu_label = choice;
    accessxi.last_native_menu_selected = selected;
    accessxi.last_native_menu_tick = tick();
    accessxi.current_speech_key = ('native-itemsort-confirmation:%s:%d:%d:%s:%s:%s'):fmt(
        menu_name,
        selected,
        count,
        tostring(context.label or ''),
        prompt,
        choice);
    log_state(('state nativemenu item-sort-confirmation menu="%s" title="%s" select=%d count=%d entry=0x%08X itemSortLabel="%s" itemSortHelp="%s" choice="%s" prompt="%s" transitionFrom="%s" transitionTo="%s" transitionAge=%d source="ROM\\97\\40.DAT#60; %s"'):fmt(
        menu_name,
        tostring(title or ''),
        selected,
        count,
        entry,
        accessxi.escape_probe_log_text(context.label or ''),
        accessxi.escape_probe_log_text(context.help or ''),
        accessxi.escape_probe_log_text(choice),
        accessxi.escape_probe_log_text(prompt),
        accessxi.escape_probe_log_text(context.transition_from or ''),
        accessxi.escape_probe_log_text(context.transition_to or ''),
        tonumber(context.transition_age) or 0,
        choice_source));
    return speech;
end

function accessxi.current_item_use_confirmation_context()
    local now = tick();
    local action_label = tostring(accessxi.current_item_use_action_label or '');
    local item_name = tostring(accessxi.current_item_use_item_name or '');
    local action_selected = tonumber(accessxi.current_item_use_action_selected) or 0;
    local action_offset = tonumber(accessxi.current_item_use_action_offset) or 0;
    local action_age = now - (tonumber(accessxi.current_item_use_action_tick) or 0);
    if (action_label == '' or action_selected <= 0 or action_age < 0 or action_age > 120000) then
        return nil, 'missing-item-use-context';
    end
    if (not action_label:eq('Drop', true)) then
        return nil, 'not-drop-action';
    end

    local transition_age = now - (tonumber(accessxi.last_menu_transition_tick) or 0);
    local transition_from = tostring(accessxi.last_menu_transition_from or '');
    local transition_to = tostring(accessxi.last_menu_transition_to or '');
    if (transition_age < 0 or transition_age > 120000
        or not transition_from:eq('menu    iuse', true)
        or not transition_to:eq('menu    sortyn', true)) then
        return nil, 'not-item-use-transition';
    end

    return {
        action_label = action_label,
        item_name = item_name,
        action_selected = action_selected,
        action_offset = action_offset,
        action_age = action_age,
        transition_from = transition_from,
        transition_to = transition_to,
        transition_age = transition_age,
    }, '';
end

function accessxi.item_use_confirmation_speech(menu_name, title, selected, count, entry)
    menu_name = tostring(menu_name or '');
