            accessxi.escape_probe_log_text(accessxi.current_item_use_action_label or ''),
            accessxi.escape_probe_log_text(accessxi.current_item_use_item_name or ''),
            accessxi.escape_probe_log_text(accessxi.last_menu_transition_from or ''),
            accessxi.escape_probe_log_text(accessxi.last_menu_transition_to or '')));
        return nil;
    end

    local prompt = accessxi.dat_index_row_text('ROM\\97\\40.DAT', 61, 'help');
    if (prompt == '') then
        log_state(('state nativemenu item-use-confirmation quiet menu="%s" title="%s" select=%d count=%d entry=0x%08X reason="missing-prompt-dat" action="%s" item="%s" source="ROM\\97\\40.DAT#61"'):fmt(
            menu_name,
            tostring(title or ''),
            selected,
            count,
            entry,
            accessxi.escape_probe_log_text(context.action_label or ''),
            accessxi.escape_probe_log_text(context.item_name or '')));
        return nil;
    end

    local choice = '';
    local choice_source = '';
    if (selected == 1) then
        choice = accessxi.dat_index_row_text('ROM\\97\\37.DAT', 106, 'label');
        choice_source = 'ROM\\97\\37.DAT#106';
    elseif (selected == 2) then
        choice = accessxi.dat_index_row_text('ROM\\97\\37.DAT', 107, 'label');
        choice_source = 'ROM\\97\\37.DAT#107';
    else
        log_state(('state nativemenu item-use-confirmation unsupported-row menu="%s" title="%s" select=%d count=%d entry=0x%08X action="%s" item="%s" prompt="%s"'):fmt(
            menu_name,
            tostring(title or ''),
            selected,
            count,
            entry,
            accessxi.escape_probe_log_text(context.action_label or ''),
            accessxi.escape_probe_log_text(context.item_name or ''),
            accessxi.escape_probe_log_text(prompt)));
        return nil;
    end
    if (choice == '') then
        log_state(('state nativemenu item-use-confirmation quiet menu="%s" title="%s" select=%d count=%d entry=0x%08X reason="missing-choice-dat" action="%s" item="%s" prompt="%s" source="%s"'):fmt(
            menu_name,
            tostring(title or ''),
            selected,
            count,
            entry,
            accessxi.escape_probe_log_text(context.action_label or ''),
            accessxi.escape_probe_log_text(context.item_name or ''),
            accessxi.escape_probe_log_text(prompt),
            choice_source));
        return nil;
    end

    if (selected == 1) then
        accessxi.current_item_dispose_confirmed_item_name = context.item_name;
        accessxi.current_item_dispose_confirmed_tick = tick();
    elseif (selected == 2) then
        accessxi.current_item_dispose_confirmed_item_name = '';
        accessxi.current_item_dispose_confirmed_tick = 0;
    end

    local speech_parts = T{};
    if (tostring(context.item_name or '') ~= '') then
        speech_parts:append(context.item_name);
    end
    speech_parts:append(prompt);
    speech_parts:append(choice);
    local speech = accessxi.speech_output_text(speech_parts:concat('. '));
    if (speech == '') then
        return nil;
    end

    accessxi.last_native_menu_name = menu_name;
    accessxi.last_native_menu_label = choice;
    accessxi.last_native_menu_selected = selected;
    accessxi.last_native_menu_tick = tick();
    accessxi.current_speech_key = ('native-item-use-confirmation:%s:%d:%d:%s:%s:%s'):fmt(
        menu_name,
        selected,
        count,
        tostring(context.item_name or ''),
        prompt,
        choice);
    log_state(('state nativemenu item-use-confirmation menu="%s" title="%s" select=%d count=%d entry=0x%08X action="%s" actionSelected=%d actionOffset=0x%02X item="%s" choice="%s" prompt="%s" transitionFrom="%s" transitionTo="%s" transitionAge=%d source="ROM\\97\\40.DAT#61; %s"'):fmt(
        menu_name,
        tostring(title or ''),
        selected,
        count,
        entry,
        accessxi.escape_probe_log_text(context.action_label or ''),
        tonumber(context.action_selected) or 0,
        tonumber(context.action_offset) or 0,
        accessxi.escape_probe_log_text(context.item_name or ''),
        accessxi.escape_probe_log_text(choice),
        accessxi.escape_probe_log_text(prompt),
        accessxi.escape_probe_log_text(context.transition_from or ''),
        accessxi.escape_probe_log_text(context.transition_to or ''),
        tonumber(context.transition_age) or 0,
        choice_source));
    return speech;
end

