        log_state(('state nativemenu item-dispose-second-confirmation quiet menu="%s" reason="missing-prompt-dat" item="%s" source="ROM\\97\\38.DAT#48"'):fmt(
            menu_name,
            accessxi.escape_probe_log_text(context.item_name or '')));
        return nil;
    end

    local selected_label, selected, selected_offset, selected_source = accessxi.generic_comyn_selected_label();
    if (selected_label == '') then
        log_state(('state nativemenu item-dispose-second-confirmation quiet menu="%s" reason="missing-selected-label" item="%s" selected=%d selectedOffset=0x%02X selectedSource="%s"'):fmt(
            menu_name,
            accessxi.escape_probe_log_text(context.item_name or ''),
            tonumber(selected) or -1,
            tonumber(selected_offset) or 0,
            accessxi.escape_probe_log_text(selected_source or '')));
        return nil;
    end

    local choice_source = tostring(selected_source or '');
    if (selected_label:eq('Yes', true)) then
        local yes_label = accessxi.dat_index_row_text('ROM\\97\\37.DAT', 106, 'label');
        if (yes_label ~= '') then
            selected_label = yes_label;
            choice_source = ('ROM\\97\\37.DAT#106; %s'):fmt(choice_source);
        end
    elseif (selected_label:eq('No', true)) then
        local no_label = accessxi.dat_index_row_text('ROM\\97\\37.DAT', 107, 'label');
        if (no_label ~= '') then
            selected_label = no_label;
            choice_source = ('ROM\\97\\37.DAT#107; %s'):fmt(choice_source);
        end
    end

    local prompt = prompt_template:gsub('%%s', context.item_name);
    local speech_parts = T{ prompt, selected_label };
    local speech = accessxi.speech_output_text(speech_parts:concat('. '));
    if (speech == '') then
        return nil;
    end

    accessxi.last_native_menu_name = menu_name;
    accessxi.last_native_menu_label = selected_label;
    accessxi.last_native_menu_selected = tonumber(selected) or 0;
    accessxi.last_native_menu_tick = tick();
    accessxi.current_speech_key = ('native-item-dispose-second-confirmation:%s:%s:%d:%d:%s:%s'):fmt(
        menu_name,
        tostring(context.item_name or ''),
        tonumber(selected) or -1,
        tonumber(selected_offset) or 0,
        prompt,
        selected_label);
    log_state(('state nativemenu item-dispose-second-confirmation menu="%s" item="%s" prompt="%s" selected=%d selectedOffset=0x%02X selectedSource="%s" selectedLabel="%s" transitionFrom="%s" transitionTo="%s" transitionAge=%d itemAge=%d source="ROM\\97\\38.DAT#48; %s"'):fmt(
        menu_name,
        accessxi.escape_probe_log_text(context.item_name or ''),
        accessxi.escape_probe_log_text(prompt),
        tonumber(selected) or -1,
        tonumber(selected_offset) or 0,
        accessxi.escape_probe_log_text(selected_source or ''),
        accessxi.escape_probe_log_text(selected_label),
        accessxi.escape_probe_log_text(context.transition_from or ''),
        accessxi.escape_probe_log_text(context.transition_to or ''),
        tonumber(context.transition_age) or 0,
        tonumber(context.item_age) or 0,
        accessxi.escape_probe_log_text(choice_source)));
    return speech;
end

function accessxi.native_known_menu_speech(name)
    local menu_name = tostring(name or '');
    local title = accessxi.native_known_menu_title(menu_name);
    if (title == '') then
        title = accessxi.native_synthesis_menu_title(menu_name);
        if (title == '' and not menu_name:eq('menu    playermo', true)) then
            return nil;
        end
    end
    accessxi.current_menu_speech_title = title;

    local obj = get_current_menu_object_ptr();
    if (obj == 0) then
        return nil;
    end

    local selected, page, raw, child, count = accessxi.survival_guide_query_child_state_for_obj(obj);
    selected = tonumber(selected) or 0;
    count = tonumber(count) or 0;
    if (menu_name:eq('menu    statcom2', true)
        or menu_name:eq('menu    evitem', true)
        or menu_name:eq('menu    jobchang', true)
        or menu_name:eq('menu    jobcselu', true)
        or menu_name:eq('menu    roomlist', true)
        or accessxi.is_macro_live_palette_menu_name(menu_name)
        or menu_name:eq('menu    mogcont', true)
        or menu_name:eq('menu    commenu', true)
        or menu_name:eq('menu    flistmai', true)
