        or menu_name:eq('menu    playermo', true)
        or menu_name:eq('menu    magselec', true)
        or menu_name:eq('menu    abiselec', true)
        or menu_name:eq('menu    chatctrl', true)
        or menu_name:eq('menu    bluequip', true)
        or menu_name:eq('menu    bluinven', true)
        or menu_name:eq('menu    scoption', true)) then
        selected = read_current_native_menu_index(0x4C);
    end
    if (menu_name:eq('menu    itmsort2', true)
        or menu_name:eq('menu    blusortw', true)
        or menu_name:eq('menu    mgcsortw', true)) then
        local sort_selected = read_current_native_menu_index(0x4C);
        if (sort_selected > 0) then
            selected = sort_selected;
        end
    end
    if (menu_name:eq('menu    shopsell', true)) then
        local shop_selected = read_current_native_menu_index(0x4C);
        if (shop_selected > 0) then
            selected = shop_selected;
        end
    end
    if (menu_name:eq('menu    shopbuy', true)) then
        local shop_selected = read_current_native_menu_index(0x4C);
        if (shop_selected > 0) then
            selected = shop_selected;
        end
    end
    if (selected <= 0) then
        selected = read_current_native_menu_index(0x4C);
    end
    if (count <= 0 or count > 64) then
        local count_a = accessxi.native_menu_index(0x24);
        local count_b = accessxi.native_menu_index(0x28);
        count = math.max(tonumber(count_a) or 0, tonumber(count_b) or 0);
