    end

    if (menu_name:eq('menu    miss00', true)) then
        local row, desc_id, desc_tag, desc, desc_rec, category, category_ptr, raw_category = accessxi.missions_menu_descriptor_row(entry);
        local fallback_context = tostring(accessxi.last_missions_menu_context_label or '');
        local index_category, native_category_index, index_source = accessxi.missions_menu_category_index_context(menu_name, title, child, selected, count, page, raw);
        local surface_category, surface_ptr, surface_text = '', 0, '';
        if (accessxi.missions_menu_category_probe_enabled == true) then
