        local pointer_category, pointer_ptr, pointer_source = '', 0, '';
        local signature_category, native_signature, signature_source = '', '', '';
        local header_category, header_source = '', '';
        if (index_category == '') then
            pointer_category, pointer_ptr, pointer_source = accessxi.missions_menu_category_pointer_context(menu_name, title, obj, selected, count, page, raw, child, entry);
            signature_category, native_signature, signature_source = accessxi.missions_menu_native_signature_context(menu_name, title, obj, selected, count, page, raw);
            header_category, header_source = accessxi.missions_menu_header_category_context(menu_name, title, obj, selected, count, page, raw, child, entry, native_signature);
            accessxi.log_missions_menu_native_signal(menu_name, title, obj, selected, count, page, raw, child, entry);
        end
        local context, context_source_detail = accessxi.missions_menu_context_from_runtime(fallback_context, category, raw_category, surface_category, pointer_category, signature_category, header_category, index_category);
        if (context_source_detail == 'mission-category-native-pointer' and tostring(pointer_source or '') ~= '') then
            context_source_detail = pointer_source;
        elseif (context_source_detail == 'mission-category-native-index' and tostring(index_source or '') ~= '') then
            context_source_detail = index_source;
        end
        local context_age = (tonumber(accessxi.last_missions_menu_context_tick) or 0) > 0 and math.floor(tick() - (tonumber(accessxi.last_missions_menu_context_tick) or 0)) or -1;
        local context_row, context_source = accessxi.missions_menu_contextual_row(context, selected, raw, page, child);
        local native_row_label, native_row_mode = accessxi.missions_menu_native_row_label(child, selected, count);
        if (native_row_label ~= '') then
            local native_row_key = ('%s:%s:%d:%d:0x%08X:%s:%s'):fmt(
                menu_name,
                context,
                selected,
                count,
                tonumber(raw) or 0,
                native_row_label,
                tostring(native_row_mode or ''));
            if (native_row_key ~= tostring(accessxi.last_missions_menu_native_row_key or '')) then
                accessxi.last_missions_menu_native_row_key = native_row_key;
                log_state(('state missions native-row menu="%s" title="%s" select=%d count=%d raw=0x%08X rawLo=%d context="%s" label="%s" mode="%s" prefer=%s romLabel="%s" romSource="%s"'):fmt(
                    menu_name,
                    title,
                    selected,
                    count,
                    tonumber(raw) or 0,
                    bit.band(tonumber(raw) or 0, 0xFFFF),
                    accessxi.escape_probe_log_text(context),
                    accessxi.escape_probe_log_text(native_row_label),
                    accessxi.escape_probe_log_text(tostring(native_row_mode or '')),
                    accessxi.missions_menu_should_prefer_native_row(context_row, native_row_label) and 'true' or 'false',
                    context_row ~= nil and accessxi.escape_probe_log_text(tostring(context_row.label or '')) or '',
                    accessxi.escape_probe_log_text(tostring(context_source or ''))));
            end
        end
        accessxi.log_missions_menu_runtime_object_probe(menu_name, title, obj, selected, count, page, raw, child, entry, context, context_source_detail, context_row, native_row_label, native_row_mode);
        accessxi.log_missions_menu_native_text_probe(menu_name, title, obj, selected, count, page, raw, child, entry, context, context_row, native_row_label, native_row_mode, 'selection');
        if (accessxi.missions_menu_should_prefer_native_row(context_row, native_row_label)) then
            context_row = accessxi.missions_menu_native_row(context, native_row_label, native_row_mode, raw);
            context_source = context_row.source;
        end
        if (tostring(context_source_detail or '') ~= 'parent-context' and tostring(context or '') ~= '') then
            accessxi.last_missions_menu_context_label = context;
            accessxi.last_missions_menu_context_tick = tick();
            accessxi.last_missions_menu_context_entry = entry;
            context_age = 0;
        end
        if (context_source ~= nil and tostring(context_source or '') ~= '') then
            context_source = ('%s:%s'):fmt(tostring(context_source_detail or ''), tostring(context_source or ''));
        else
            context_source = tostring(context_source_detail or '');
        end
        accessxi.log_missions_menu_category_signal(menu_name, title, selected, count, raw, entry, context, context_source, fallback_context, category_ptr, category, raw_category, surface_category, surface_ptr, desc_id, desc_rec);
        accessxi.log_missions_menu_category_surface(menu_name, title, selected, count, raw, child, entry, surface_category);
        if (context_row ~= nil and tostring(context_row.label or '') ~= '') then
            local label = tostring(context_row.label or '');
            local status = tostring(context_row.status or '');
            local spoken_label = label;
            accessxi.log_missions_menu_section_signal(menu_name, title, obj, selected, count, page, raw, child, entry, context, context_row, context_source, desc_id, desc_rec);
            if (accessxi.missions_menu_detail_section_active(desc_id, context_row, entry)) then
                local detail_speech = accessxi.missions_menu_detail_speech(title, context, context_row);
                if (detail_speech ~= nil and detail_speech ~= '') then
                    accessxi.begin_mission_detail_summary_surface(
                        menu_name, context, context_row, obj, desc_id);
                    accessxi.last_native_menu_name = menu_name;
                    accessxi.last_native_menu_label = detail_speech;
                    accessxi.last_native_menu_selected = selected;
                    accessxi.last_native_menu_tick = tick();
                    local detail_hold_ms = accessxi.missions_menu_detail_hold_ms(detail_speech);
                    local detail_key = ('mission-detail:%s:%s:%d:%d:%s:%s'):fmt(
                        menu_name,
                        context,
                        selected,
                        count,
                        label,
                        tostring(context_row.orders or ''));
                    local is_current_mission_detail = status:eq('Current', true)
                        or tostring(context_source or ''):find('current-row', 1, true) ~= nil;
                    if (detail_key ~= tostring(accessxi.last_missions_menu_detail_key or '')) then
                        accessxi.last_missions_menu_detail_key = detail_key;
                        log_state(('state nativemenu mission-detail menu="%s" title="%s" select=%d count=%d entry=0x%08X context="%s" source="%s" label="%s" missionId=%d descId=0x%08X ordersSource="%s" orders="%s"'):fmt(
                            menu_name,
                            title,
                            selected,
                            count,
                            tonumber(entry) or 0,
                            accessxi.escape_probe_log_text(context),
                            accessxi.escape_probe_log_text(tostring(context_source or '')),
                            accessxi.escape_probe_log_text(label),
                            tonumber(context_row.mission_id) or 0,
                            tonumber(desc_id) or 0,
                            accessxi.escape_probe_log_text(tostring(context_row.orders_source or '')),
                            accessxi.escape_probe_log_text(tostring(context_row.orders or ''))));
                    end
                    if (tonumber(desc_id) == 0x5A and selected <= count and is_current_mission_detail) then
                        accessxi.clear_missions_menu_detail_deferred_speech();
                        accessxi.clear_missions_menu_detail_hold();
                        accessxi.last_missions_menu_detail_hold_key = '';
                        accessxi.missions_menu_detail_speech_protect_until = math.max(
                            tonumber(accessxi.missions_menu_detail_speech_protect_until) or 0,
