                        if (detail_key ~= tostring(accessxi.last_missions_menu_detail_current_title_key or '')) then
                            accessxi.last_missions_menu_detail_current_title_key = detail_key;
                            log_state(('state nativemenu mission-detail-current-title menu="%s" title="%s" select=%d count=%d entry=0x%08X context="%s" label="%s" key="%s"'):fmt(
                                menu_name,
                                title,
                                selected,
                                count,
                                tonumber(entry) or 0,
                                accessxi.escape_probe_log_text(context),
                                accessxi.escape_probe_log_text(label),
                                accessxi.escape_probe_log_text(detail_key)));
