                        accessxi.missions_menu_detail_hold_until = tick() + detail_hold_ms;
                        accessxi.missions_menu_detail_hold_context = context;
                        accessxi.missions_menu_detail_hold_label = label;
                        accessxi.missions_menu_detail_hold_selected = selected;
                        accessxi.missions_menu_detail_hold_count = count;
                        accessxi.missions_menu_detail_hold_key = detail_key;
                        return detail_speech;
                    end
