            local mix_short_path = mix_path:match('FINAL FANTASY XI\\(.+)$') or mix_path;
            log_state(('state nativemenu magic-mix-row menu="%s" title="%s" select=%d count=%d id=%d skill=%d element=%d mp=%d total=%d path="%s" label="%s"'):fmt(
