                    return accessxi.ability_row_speech(menu_name, title, tostring(anchor_dancer_label or accessxi.ability_dancer_category_label or 'Job Abilities'), 'native-dancer-category-child', selected, count, entry, anchor_dancer_ability, 'native-command-data-0x0AC-dancer-category-child', anchor_dancer_summary, anchor_dancer_known_total);
                end

                local dancer_ability, dancer_summary, dancer_known_total = accessxi.ability_packet_dancer_category_for_selected(selected, count, '');
                if (dancer_ability ~= nil) then
                    return accessxi.ability_row_speech(menu_name, title, tostring(accessxi.ability_dancer_category_label or 'Job Abilities'), 'native-dancer-category', selected, count, entry, dancer_ability, 'native-command-data-0x0AC-dancer-category', dancer_summary, dancer_known_total);
                end

                local packet_ability, packet_summary, packet_known_total = accessxi.ability_packet_job_ability_for_selected(selected, count, child);
                if (packet_ability ~= nil) then
                    accessxi.log_ability_dancer_state_probe(menu_name, title, obj, child, entry, selected, count, tonumber(page) or 0, tonumber(raw) or 0, packet_ability, 'native-packet');
                    return accessxi.ability_row_speech(menu_name, title, 'Job Abilities', 'native-packet', selected, count, entry, packet_ability, 'native-command-data-0x0AC', packet_summary, packet_known_total);
                end
            end

            if (tostring(current_category or ''):eq('Weapon Skills', true)) then
                local aix_ability, aix_summary, aix_known_total = accessxi.ability_aix_weapon_skill_for_selected(selected, child);
                if (aix_ability ~= nil) then
                    return accessxi.ability_row_speech(menu_name, title, 'Weapon Skills', 'native-aix-fast', selected, count, entry, aix_ability, 'native-local-aix-order', aix_summary, aix_known_total);
                end
            end

            local rendered_label = accessxi.magic_rendered_row_text(entry, selected);
            local rendered_label_source = 'rendered-row';
            if (rendered_label == '' and accessxi.is_probe_pointer(child) and accessxi.native_query_label_for_selection ~= nil) then
                local queried_label, queried_mode = accessxi.native_query_label_for_selection(child, selected, count, 'plain');
                queried_label = accessxi.plain_native_menu_label(queried_label or '');
                if (queried_label ~= '') then
                    rendered_label = queried_label;
                    rendered_label_source = tostring(queried_mode or 'native-query');
                end
            end
            local match_category = current_category;
            if (category_source:eq('direct', true)) then
                match_category = '';
            end
            local ability, ability_category, wanted_type, known_total = accessxi.ability_exact_info_from_label(rendered_label, match_category);
            if (ability ~= nil) then
                local source_name = tostring(ability_category or ''):eq('Weapon Skills', true) and 'rendered-exact-weapon-skill' or 'rendered-exact-ability';
                if (rendered_label_source ~= 'rendered-row') then
                    source_name = tostring(ability_category or ''):eq('Weapon Skills', true) and 'native-query-exact-weapon-skill' or 'native-query-exact-ability';
                end
                return accessxi.ability_row_speech(menu_name, title, ability_category, category_source, selected, count, entry, ability, source_name, rendered_label, known_total);
            end

            if (tostring(current_category or ''):eq('Weapon Skills', true)) then
                local aix_ability, aix_summary, aix_known_total = accessxi.ability_aix_weapon_skill_for_selected(selected, child);
                if (aix_ability ~= nil) then
                    return accessxi.ability_row_speech(menu_name, title, 'Weapon Skills', 'native-aix', selected, count, entry, aix_ability, 'native-local-aix-order', aix_summary, aix_known_total);
                end
            end

            local backing_ability, backing_category, backing_summary, backing_known_total = accessxi.ability_from_backing_model(obj, child, entry, selected, current_category);
            if (backing_ability ~= nil) then
                return accessxi.ability_row_speech(menu_name, title, backing_category, 'native-backing', selected, count, entry, backing_ability, 'native-backing-ability-id', backing_summary, backing_known_total);
            end
            if (tostring(current_category or ''):eq('Job Abilities', true)) then
                local dynamic_ability, dynamic_category, dynamic_summary, dynamic_known_total = accessxi.ability_from_backing_model(obj, child, entry, selected, '');
                if (dynamic_ability ~= nil and tostring(dynamic_category or ''):eq('Job Abilities', true)) then
                    return accessxi.ability_row_speech(menu_name, title, dynamic_category, 'native-backing-dynamic', selected, count, entry, dynamic_ability, 'native-backing-ability-id', dynamic_summary, dynamic_known_total);
                end

            end

            local missing_key = ('%s:%s:%s:%d:%d:0x%08X'):fmt(
                menu_name,
                tostring(current_category or ''),
                tostring(category_source or ''),
                selected,
                count,
                tonumber(entry) or 0);
            if (missing_key ~= tostring(accessxi.last_ability_resource_missing_key or '')) then
                accessxi.last_ability_resource_missing_key = missing_key;
                local preview_category = current_category;
                if (preview_category == '') then
                    preview_category = 'Job Abilities';
                end
                local known_abilities = accessxi.ability_known_list_for_category(preview_category);
                local row_kind = tostring(current_category or ''):eq('Weapon Skills', true) and 'weapon-skill' or 'job-ability';
                log_state(('state nativemenu %s-row missing menu="%s" title="%s" category="%s" categorySource="%s" matchCategory="%s" select=%d count=%d entry=0x%08X type=%d known=%d rendered="%s" renderCells="%s" windowHelp="%s" preview="%s" note="no exact native ability label; no ordinal fallback"'):fmt(
                    row_kind,
                    menu_name,
                    title,
                    tostring(current_category or ''),
                    tostring(category_source or ''),
                    tostring(match_category or ''),
                    selected,
                    count,
                    tonumber(entry) or 0,
                    tonumber(wanted_type) or 0,
                    known_abilities ~= nil and known_abilities:len() or 0,
                    accessxi.escape_probe_log_text(rendered_label or ''),
                    accessxi.escape_probe_log_text(accessxi.last_magic_render_cells or ''),
                    accessxi.escape_probe_log_text(accessxi.last_ability_window_help_probe or ''),
                    accessxi.escape_probe_log_text(accessxi.job_ability_known_preview(known_abilities))));
            end
            return nil;
        end

        if (tostring(current_category or '') == '') then
            local title_category = '';
            if (tostring(title or ''):eq('Weapon Skills', true)) then
                title_category = 'Weapon Skills';
            elseif (tostring(title or ''):eq('Job Abilities', true)) then
                title_category = 'Job Abilities';
            end
            local child_menu_type = accessxi.ability_child_menu_type(child);
            local direct_category = '';
            if (child_menu_type == 3) then
                direct_category = 'Weapon Skills';
            elseif (title_category:eq('Job Abilities', true)) then
                direct_category = 'Job Abilities';
            elseif (title_category:eq('Weapon Skills', true)) then
                direct_category = 'Weapon Skills';
            end

            if (direct_category ~= '') then
                if (direct_category:eq('Weapon Skills', true)) then
                    local aix_ability, aix_summary, aix_known_total, aix_reason = accessxi.ability_aix_weapon_skill_for_selected(selected, child);
                    if (aix_ability ~= nil) then
                        return accessxi.ability_row_speech(menu_name, title, direct_category, 'direct-native-aix-fast', selected, count, entry, aix_ability, 'native-local-aix-order', aix_summary, aix_known_total);
                    end
                end

                local native_ability, native_category, native_source, native_label, native_known_total = accessxi.ability_from_native_row_label(entry, child, selected, count, direct_category);
                if (native_ability ~= nil) then
                    return accessxi.ability_row_speech(menu_name, title, native_category, 'direct-native-row-label', selected, count, entry, native_ability, native_source, native_label, native_known_total);
                end

                local help_ability, help_category, help_source, help_label, help_known_total = accessxi.ability_from_window_help(direct_category);
                if (help_ability ~= nil) then
                    return accessxi.ability_row_speech(menu_name, title, help_category, 'direct-native-window-help', selected, count, entry, help_ability, help_source, help_label, help_known_total);
                end

                local job_packet_reason = '';
                if (direct_category:eq('Job Abilities', true)) then
                    accessxi.log_ability_dancer_anchor_signal_probe(menu_name, title, obj, child, entry, selected, count, tonumber(page) or 0, tonumber(raw) or 0, 'direct-job-abilities');
                    local anchor_dancer_ability, anchor_dancer_summary, anchor_dancer_known_total, _, anchor_dancer_label = accessxi.ability_packet_dancer_category_for_anchor_child(child);
                    if (anchor_dancer_ability ~= nil) then
                        return accessxi.ability_row_speech(menu_name, title, tostring(anchor_dancer_label or accessxi.ability_dancer_category_label or direct_category), 'direct-native-dancer-category-child', selected, count, entry, anchor_dancer_ability, 'native-command-data-0x0AC-dancer-category-child', anchor_dancer_summary, anchor_dancer_known_total);
                    end

                    local dancer_ability, dancer_summary, dancer_known_total, dancer_reason = accessxi.ability_packet_dancer_category_for_selected(selected, count, '');
                    if (dancer_ability ~= nil) then
                        return accessxi.ability_row_speech(menu_name, title, tostring(accessxi.ability_dancer_category_label or direct_category), 'direct-native-dancer-category', selected, count, entry, dancer_ability, 'native-command-data-0x0AC-dancer-category', dancer_summary, dancer_known_total);
                    end

                    local packet_ability, packet_summary, packet_known_total, packet_reason = accessxi.ability_packet_job_ability_for_selected(selected, count, child);
                    job_packet_reason = tostring(packet_reason or dancer_reason or '');
                    if (packet_ability ~= nil) then
                        accessxi.log_ability_dancer_state_probe(menu_name, title, obj, child, entry, selected, count, tonumber(page) or 0, tonumber(raw) or 0, packet_ability, 'direct-native-packet');
                        return accessxi.ability_row_speech(menu_name, title, direct_category, 'direct-native-packet', selected, count, entry, packet_ability, 'native-command-data-0x0AC', packet_summary, packet_known_total);
                    end
                end

                if (not direct_category:eq('Weapon Skills', true)) then
                    local backing_ability, backing_category, backing_summary, backing_known_total = accessxi.ability_from_backing_model(obj, child, entry, selected, direct_category);
                    if (backing_ability ~= nil) then
                        return accessxi.ability_row_speech(menu_name, title, backing_category, 'direct-native-backing', selected, count, entry, backing_ability, 'native-backing-ability-id', backing_summary, backing_known_total);
                    end
                end

                local aix_ability = nil;
                local aix_summary = '';
                local aix_known_total = 0;
                local aix_reason = '';
                if (direct_category:eq('Weapon Skills', true)) then
                    aix_ability, aix_summary, aix_known_total, aix_reason = accessxi.ability_aix_weapon_skill_for_selected(selected, child);
                else
                    aix_reason = job_packet_reason ~= '' and ('packet-' .. job_packet_reason) or 'job-aix-disabled-unproved-order';
                end
                if (aix_ability ~= nil) then
                    return accessxi.ability_row_speech(menu_name, title, direct_category, 'direct-native-aix', selected, count, entry, aix_ability, 'native-local-aix-order', aix_summary, aix_known_total);
                end

                local quiet_key = ('%s:%s:%d:%d:%d:0x%08X:%s:%s'):fmt(
                    menu_name,
                    direct_category,
                    selected,
                    count,
                    child_menu_type,
                    tonumber(entry) or 0,
                    tostring(aix_reason or ''),
                    tostring(native_label or ''));
                if (quiet_key ~= tostring(accessxi.last_ability_resource_missing_key or '')) then
                    accessxi.last_ability_resource_missing_key = quiet_key;
                    accessxi.log_ability_direct_state_probe(menu_name, title, obj, child, entry, selected, count, tonumber(page) or 0, tonumber(raw) or 0, direct_category, child_menu_type, tostring(aix_reason or ''), tostring(native_label or ''));
                    log_state(('state nativemenu ability-direct-quiet menu="%s" title="%s" directCategory="%s" titleCategory="%s" select=%d count=%d entry=0x%08X childType=%d reason="%s" nativeLabel="%s" windowHelp="%s" note="direct ability native label, backing, and AIX unavailable; no ordinal fallback"'):fmt(
                        menu_name,
                        title,
                        direct_category,
                        title_category,
                        selected,
                        count,
                        tonumber(entry) or 0,
                        child_menu_type,
                        accessxi.escape_probe_log_text(tostring(aix_reason or '')),
                        accessxi.escape_probe_log_text(tostring(native_label or '')),
                        accessxi.escape_probe_log_text(accessxi.last_ability_window_help_probe or '')));
                end
                return nil;
            end

            local backing_ability, backing_category, backing_summary, backing_known_total = accessxi.ability_from_backing_model(obj, child, entry, selected, '');
            if (backing_ability ~= nil) then
                return accessxi.ability_row_speech(menu_name, title, backing_category, 'direct-native-backing', selected, count, entry, backing_ability, 'native-backing-ability-id', backing_summary, backing_known_total);
            end
            local quiet_key = ('%s:%s:%d:%d:0x%08X'):fmt(menu_name, title_category, selected, count, tonumber(entry) or 0);
            if (quiet_key ~= tostring(accessxi.last_ability_resource_missing_key or '')) then
                accessxi.last_ability_resource_missing_key = quiet_key;
                log_state(('state nativemenu ability-direct-quiet menu="%s" title="%s" select=%d count=%d entry=0x%08X note="skipped heavy raw probes"'):fmt(
                    menu_name,
                    title,
                    selected,
                    count,
                    tonumber(entry) or 0));
            end
        end

        local missing_key = ('%s:%s:%d:%d:0x%08X'):fmt(
            menu_name,
            tostring(current_category or ''),
            selected,
            count,
            tonumber(entry) or 0);
        if (missing_key ~= tostring(accessxi.last_ability_resource_missing_key or '')) then
            accessxi.last_ability_resource_missing_key = missing_key;
            log_state(('state nativemenu ability-dynamic-missing menu="%s" title="%s" category="%s" select=%d count=%d entry=0x%08X note="usable ability list is dynamic; no known-list fallback"'):fmt(
                menu_name,
                title,
                tostring(current_category or ''),
                selected,
                count,
                tonumber(entry) or 0));
        end
        return nil;
    end

    if (menu_name:eq('menu    statcom2', true)) then
        local now = tick();
        local quiet_selected = tonumber(accessxi.status_menu_quiet_selected) or -1;
        if (quiet_selected == selected) then
            log_state(('state nativemenu status-desc quiet menu="%s" select=%d'):fmt(
                menu_name,
                selected));
            return nil;
        elseif (quiet_selected > 0) then
            accessxi.status_menu_quiet_selected = -1;
        end
        if (now < (tonumber(accessxi.status_detail_suppress_status_menu_until) or 0)) then
            log_state(('state nativemenu status-desc suppressed menu="%s" select=%d until=%d'):fmt(
                menu_name,
                selected,
                tonumber(accessxi.status_detail_suppress_status_menu_until) or 0));
            return nil;
        end
        local description, row2, desc = accessxi.status_menu_native_description_for_entry(entry);
        if (description ~= '') then
            local status_label, row0, row_code = accessxi.status_menu_native_label_for_description(description, desc);
            local spoken_description = description;
            if (status_label ~= '') then
                spoken_description = ('%s. %s'):fmt(status_label, description);
            end
            if (status_label:eq('Currencies 2', true)) then
                accessxi.current_currency_menu_page = 2;
                accessxi.current_currency_menu_page_tick = tick();
                accessxi.currency_native_remember_help_bank(row2);
            elseif (status_label:eq('Currencies', true)) then
                accessxi.current_currency_menu_page = 1;
                accessxi.current_currency_menu_page_tick = tick();
                accessxi.currency_native_remember_help_bank(row2);
            elseif (status_label:eq('Unity', true)) then
                accessxi.unity_menu_context_until = tick() + 120000;
            elseif (status_label:eq('Merit Points', true)) then
                accessxi.merit_menu_context_until = tick() + 120000;
            elseif (status_label:eq('Job Points', true)) then
                accessxi.job_point_menu_context_until = tick() + 120000;
            end
            if (description:contains('View your profile', true)) then
                accessxi.status_profile_pending_until = tick() + 2500;
            end
            accessxi.last_native_menu_name = menu_name;
            accessxi.last_native_menu_label = spoken_description;
            accessxi.last_native_menu_selected = selected;
            accessxi.last_native_menu_tick = tick();
            accessxi.current_speech_key = ('native-known-status-desc:%s:%d:0x%08X:0x%08X:0x%08X:%s:%s'):fmt(
                menu_name,
                selected,
                entry,
                tonumber(row0) or 0,
                row2,
                status_label,
                description);
            log_state(('state nativemenu status-desc menu="%s" title="%s" select=%d count=%d entry=0x%08X desc=0x%08X row0=0x%08X rowCode=0x%08X row2=0x%08X label="%s" text="%s"'):fmt(
                menu_name,
                title,
                selected,
                count,
                entry,
                tonumber(desc) or 0,
                tonumber(row0) or 0,
                tonumber(row_code) or 0,
                tonumber(row2) or 0,
                status_label,
                description));
            return ('%s. %s'):fmt(title, accessxi.sentence_fragment(spoken_description));
        end
    end

    if (menu_name:eq('menu    mount', true)) then
        return accessxi.mount_menu_speech(menu_name, title, selected, count, entry);
    end

    local quests_main_resource = accessxi.quests_menu_main_resource_speech(menu_name, title, selected, count, page, raw, child, entry);
    if (quests_main_resource ~= nil) then
        return quests_main_resource;
    end

    local quests_detail_resource = accessxi.quests_menu_detail_resource_speech(menu_name, title, selected, count, page, raw, child, entry);
    if (quests_detail_resource ~= nil) then
        return quests_detail_resource;
    end

    local quests_runtime_resource_row = accessxi.quests_menu_runtime_resource_row(menu_name, title, selected, count, page, raw, child, entry);
    if (quests_runtime_resource_row ~= nil) then
        return quests_runtime_resource_row;
    end

    local records_of_eminence_row = accessxi.records_of_eminence_menu_speech(menu_name, title, selected, count, page, raw, child, entry);
    if (records_of_eminence_row ~= nil) then
        return records_of_eminence_row;
    end
    local records_of_eminence_objective_list_row = accessxi.records_of_eminence_objective_list_speech(menu_name, title, selected, count, page, raw, child, entry);
    if (records_of_eminence_objective_list_row ~= nil) then
        return records_of_eminence_objective_list_row;
    end
    local records_of_eminence_objective_category_row = accessxi.records_of_eminence_objective_category_speech(menu_name, title, selected, count, page, raw, child, entry);
    if (records_of_eminence_objective_category_row ~= nil) then
        return records_of_eminence_objective_category_row;
    end
    local _, records_of_eminence_context = accessxi.quests_menu_effective_mode();
    if (menu_name:eq('menu    quest01', true)
        and (records_of_eminence_context == 'records-of-eminence'
            or records_of_eminence_context == 'records-of-eminence-objective-list'
            or records_of_eminence_context == 'records-of-eminence-objective-category'
            or records_of_eminence_context == 'records-of-eminence-objective-catalog')) then
        return nil;
    end

    if (selected <= 0 or count <= 0 or count > 64 or selected > count or not accessxi.is_probe_pointer(child)) then
        if (menu_name:eq('menu    evitem', true)) then
            accessxi.log_currency_menu_probe(menu_name, title, obj, selected, count, page, raw, child, entry, 'missing-child');
        elseif (accessxi.is_mogpost_menu_name(menu_name)) then
            accessxi.log_mogpost_menu_probe(menu_name, title, obj, selected, count, page, raw, child, entry, 'missing-child');
        elseif (menu_name:eq('menu    miss00', true)) then
            accessxi.log_missions_menu_probe(menu_name, title, obj, selected, count, page, raw, child, entry, 'missing-child');
        elseif (menu_name:eq('menu    quest01', true)) then
            accessxi.log_quests_menu_submenu_probe(menu_name, title, obj, selected, count, page, raw, child, entry, 'missing-child');
        else
            accessxi.log_status_menu_probe(menu_name, 'missing-child');
        end
        log_state(('state nativemenu native-missing menu="%s" title="%s" select=%d count=%d page=%d raw=0x%08X child=0x%08X'):fmt(
            menu_name,
            title,
            selected,
            count,
            tonumber(page) or 0,
            tonumber(raw) or 0,
            tonumber(child) or 0));
        return nil;
    end

    local label, mode = accessxi.native_query_label_for_selection(child, selected, count, 'plain');
    label = accessxi.plain_native_menu_label(label or '');
    if (label == '') then
        if (menu_name:eq('menu    evitem', true)) then
            accessxi.log_currency_menu_probe(menu_name, title, obj, selected, count, page, raw, child, entry, 'missing-label');
        elseif (accessxi.is_mogpost_menu_name(menu_name)) then
            accessxi.log_mogpost_menu_probe(menu_name, title, obj, selected, count, page, raw, child, entry, 'missing-label');
        elseif (menu_name:eq('menu    miss00', true)) then
            if (accessxi.missions_menu_category_probe_enabled == true) then
                accessxi.log_missions_menu_native_signal(menu_name, title, obj, selected, count, page, raw, child, entry);
            end
        elseif (menu_name:eq('menu    quest00', true)) then
            accessxi.log_quests_menu_main_probe(menu_name, title, obj, selected, count, page, raw, child, entry, 'missing-label');
        elseif (menu_name:eq('menu    quest01', true)) then
            accessxi.log_quests_menu_submenu_probe(menu_name, title, obj, selected, count, page, raw, child, entry, 'missing-label');
        elseif (accessxi.is_help_desk_menu_name(menu_name)) then
            accessxi.log_help_desk_menu_probe(menu_name, title, obj, selected, count, page, raw, child, entry, 'missing-label');
        else
            accessxi.log_status_menu_probe(menu_name, 'missing-label');
        end
        log_state(('state nativemenu native-missing-label menu="%s" title="%s" select=%d count=%d page=%d mode="%s" raw=0x%08X child=0x%08X entry=0x%08X'):fmt(
            menu_name,
            title,
            selected,
            count,
            tonumber(page) or 0,
            tostring(mode or ''),
            tonumber(raw) or 0,
            tonumber(child) or 0,
            tonumber(entry) or 0));
        return nil;
    end

    accessxi.last_native_menu_name = menu_name;
    accessxi.last_native_menu_label = label;
    accessxi.last_native_menu_selected = selected;
    accessxi.last_native_menu_tick = tick();
    accessxi.current_speech_key = ('native-known:%s:%d:%d:%d:%s'):fmt(
        menu_name,
        selected,
        tonumber(page) or 0,
        count,
        label);
    log_state(('state nativemenu native menu="%s" title="%s" select=%d page=%d count=%d mode="%s" raw=0x%08X child=0x%08X label="%s"'):fmt(
        menu_name,
        title,
        selected,
        tonumber(page) or 0,
        count,
        tostring(mode or ''),
        tonumber(raw) or 0,
        tonumber(child) or 0,
        label));
    return ('%s. %s.'):fmt(title, label);
end

function accessxi.title_config_menu_focus_record(obj)
    obj = tonumber(obj) or 0;
    if (obj == 0 or not accessxi.is_probe_pointer(obj)) then
        return nil;
    end

    local entry = read_u32(obj + 0x08) or 0;
    if (not accessxi.is_probe_pointer(entry)) then
        return nil;
    end

    local desc0c = read_u32(entry + 0x0C) or 0;
    if (not accessxi.is_probe_pointer(desc0c)) then
        return nil;
    end

    local record = read_u32(desc0c + 0x00) or 0;
    if (not accessxi.is_probe_pointer(record)) then
        return nil;
    end

    local record_y = read_u32(record + 0x04);
    if (record_y == nil or record_y < 0 or record_y > 0x400) then
        return nil;
    end

    local record_x = read_u32(record + 0x00) or 0;
    return T{
        entry = entry,
        desc0c = desc0c,
        record = record,
        record_x = record_x,
        record_y = record_y,
    };
end

function accessxi.title_config_menu_title_music_index(help_row)
    help_row = tonumber(help_row) or 0;
    if (help_row >= 251 and help_row <= 257) then
        return help_row - 251;
    end
    if (help_row == 270) then
        return 7;
    end
    return nil;
end

function accessxi.title_config_menu_logout_index(value)
    value = tonumber(value) or -1;
    if (value == 1) then
        return 9;
    end
    if (value == 2) then
        return 10;
    end
    return nil;
end

function accessxi.title_config_menu_selected(obj)
    obj = tonumber(obj) or 0;
    if (obj == 0 or not accessxi.is_probe_pointer(obj)) then
        return -1, 0;
    end

    local _, _, _, _, query_count = accessxi.survival_guide_query_child_state_for_obj(obj);
    query_count = tonumber(query_count) or 0;

    local selected = -1;
    local count = 0;
    if (query_count > 0 and query_count <= 64) then
        count = query_count;
    end

    if (count <= 0) then
        local count_a = tonumber(read_i32(obj + 0x24)) or 0;
        local count_b = tonumber(read_i32(obj + 0x28)) or 0;
        count = math.max(count_a, count_b);
    end

    local focus = accessxi.title_config_menu_focus_record(obj);
    local record_y = focus ~= nil and (tonumber(focus.record_y) or -1) or -1;
    if (record_y == 0x26) then
        selected = accessxi.title_config_menu_title_music_index(read_i32(obj + 0x6C)) or -1;
    elseif (record_y == 0x4E) then
        selected = 8;
    elseif (record_y == 0x73) then
        selected = accessxi.title_config_menu_logout_index(read_i32(obj + 0x5C)) or -1;
    elseif (record_y == 0x9A) then
        selected = 11;
    elseif (record_y == 0xBF) then
        selected = 14;
    end

    if (selected < 0 or selected > 64) then
        selected = -1;
    end
    if (count < 0 or count > 64) then
        count = 0;
    end
    return selected, count;
end

function accessxi.title_config_menu_entry(index)
    local resources = accessxi.native_menus_data.title_config_menu_resources or T{};
    local rows = resources.focus_rows or T{};
    local spec = rows[tonumber(index) or -1];
    if (spec == nil) then
        return nil;
    end

    local help = accessxi.plain_native_menu_help(tostring(spec.help or ''));
    local help_source = tostring(spec.help_source or '');
    if (spec.help_dat ~= nil) then
        local dat_help = accessxi.dat_index_row_text(spec.help_dat, spec.help_row, 'help');
        if (dat_help ~= '') then
            help = dat_help;
            help_source = ('%s:%d'):fmt(tostring(spec.help_dat or ''), tonumber(spec.help_row) or -1);
        end
    end

    if (help == '') then
        return nil;
    end

    return T{
        help = help,
        help_source = help_source,
        source = ('help=%s'):fmt(help_source),
    };
end

function accessxi.title_config_menu_probe_fields(ptr, prefix, offsets)
    ptr = tonumber(ptr) or 0;
    if (ptr == 0 or not accessxi.is_probe_pointer(ptr)) then
        return ('%s=0x%08X'):fmt(tostring(prefix or 'ptr'), ptr);
    end

    local fields = T{};
    offsets = offsets or T{
        0x00, 0x04, 0x08, 0x0C, 0x10, 0x14, 0x18, 0x1C,
        0x20, 0x24, 0x28, 0x2C, 0x30, 0x34, 0x38, 0x3C,
        0x40, 0x44, 0x48, 0x4C, 0x50, 0x54, 0x58, 0x5C,
        0x60, 0x64, 0x68, 0x6C, 0x70, 0x74, 0x78, 0x7C,
        0x80, 0x84, 0x88, 0x8C, 0x90, 0x94, 0x98, 0x9C,
        0xA0, 0xA4, 0xA8, 0xAC, 0xB0, 0xB4, 0xB8, 0xBC,
        0xC0, 0xC4, 0xC8, 0xCC, 0xD0, 0xD4, 0xD8, 0xDC,
        0xE0, 0xE4, 0xE8, 0xEC, 0xF0, 0xF4, 0xF8, 0xFC };
    for _, offset in ipairs(offsets) do
        local value = read_i32(ptr + offset);
        if (value ~= nil and value >= -1 and value <= 2048) then
            fields:append(('%02X=%d'):fmt(offset, value));
        end
    end

    return ('%s=0x%08X{%s}'):fmt(tostring(prefix or 'ptr'), ptr, fields:concat(','));
end

function accessxi.title_config_menu_probe_field_chunks(ptr, prefix)
    local parts = T{};
    local chunks = T{
        T{ 0x00, 0x04, 0x08, 0x0C, 0x10, 0x14, 0x18, 0x1C, 0x20, 0x24, 0x28, 0x2C, 0x30, 0x34, 0x38, 0x3C },
        T{ 0x40, 0x44, 0x48, 0x4C, 0x50, 0x54, 0x58, 0x5C, 0x60, 0x64, 0x68, 0x6C, 0x70, 0x74, 0x78, 0x7C },
        T{ 0x80, 0x84, 0x88, 0x8C, 0x90, 0x94, 0x98, 0x9C, 0xA0, 0xA4, 0xA8, 0xAC, 0xB0, 0xB4, 0xB8, 0xBC },
        T{ 0xC0, 0xC4, 0xC8, 0xCC, 0xD0, 0xD4, 0xD8, 0xDC, 0xE0, 0xE4, 0xE8, 0xEC, 0xF0, 0xF4, 0xF8, 0xFC },
    };

    for i, offsets in ipairs(chunks) do
        parts:append(T{
            part = i,
            fields = accessxi.title_config_menu_probe_fields(ptr, prefix, offsets),
        });
    end
    return parts;
end

function accessxi.title_config_menu_probe_pointer_texts(ptr, prefix)
    ptr = tonumber(ptr) or 0;
    if (ptr == 0 or not accessxi.is_probe_pointer(ptr)) then
        return '';
    end

    local texts = T{};
    for _, offset in ipairs(T{
        0x04, 0x08, 0x0C, 0x10, 0x14, 0x18, 0x1C, 0x20,
        0x24, 0x28, 0x2C, 0x30, 0x34, 0x38, 0x3C, 0x40,
        0x44, 0x48, 0x4C, 0x50, 0x54, 0x58, 0x5C, 0x60,
        0x64, 0x68, 0x6C, 0x70, 0x74, 0x78, 0x7C, 0x80 }) do
        local value = read_u32(ptr + offset) or 0;
        if (accessxi.is_probe_pointer(value)) then
            local text = accessxi.plain_native_menu_help(read_probe_string(value, 180));
            if (text ~= '') then
                texts:append(('%s+%02X="%s"'):fmt(
                    tostring(prefix or 'ptr'),
                    offset,
                    accessxi.escape_probe_log_text(text)));
            end
        end
    end

    return texts:concat('|');
end

function accessxi.title_config_menu_probe_descriptor(obj, entry)
    obj = tonumber(obj) or 0;
    entry = tonumber(entry) or 0;
    if (obj == 0 or not accessxi.is_probe_pointer(entry)) then
        return;
    end

    local desc04 = read_u32(entry + 0x04) or 0;
    local desc0c = read_u32(entry + 0x0C) or 0;
    local record = accessxi.is_probe_pointer(desc0c) and (read_u32(desc0c + 0x00) or 0) or 0;
    log_state(('state title-config probe-desc obj=0x%08X entry=0x%08X desc04=0x%08X desc0C=0x%08X record=0x%08X entryD="%s" desc04D="%s" desc0CD="%s" recordD="%s"'):fmt(
        obj,
        entry,
        tonumber(desc04) or 0,
        tonumber(desc0c) or 0,
        tonumber(record) or 0,
        accessxi.escape_probe_log_text_wide(accessxi.format_probe_dwords(entry, 0x00, 24)),
        accessxi.escape_probe_log_text_wide(accessxi.format_probe_dwords(desc04, 0x00, 24)),
        accessxi.escape_probe_log_text_wide(accessxi.format_probe_dwords(desc0c, 0x00, 24)),
        accessxi.escape_probe_log_text_wide(accessxi.format_probe_dwords(record, 0x00, 24))));
    log_state(('state title-config probe-desc-text obj=0x%08X entry=0x%08X entryRuns="%s" desc04Runs="%s" desc0CRuns="%s" recordRuns="%s" entryPtrs="%s" desc0CPtrs="%s" recordPtrs="%s"'):fmt(
        obj,
        entry,
        accessxi.escape_probe_log_text_wide(accessxi.status_menu_probe_runs(entry, 0x180)),
        accessxi.escape_probe_log_text_wide(accessxi.status_menu_probe_runs(desc04, 0x180)),
        accessxi.escape_probe_log_text_wide(accessxi.status_menu_probe_runs(desc0c, 0x180)),
        accessxi.escape_probe_log_text_wide(accessxi.status_menu_probe_runs(record, 0x180)),
        accessxi.escape_probe_log_text_wide(accessxi.status_menu_probe_pointer_fields(entry)),
        accessxi.escape_probe_log_text_wide(accessxi.status_menu_probe_pointer_fields(desc0c)),
        accessxi.escape_probe_log_text_wide(accessxi.status_menu_probe_pointer_fields(record))));
end

function accessxi.title_config_menu_probe_signature(obj)
    obj = tonumber(obj) or 0;
    if (obj == 0 or not accessxi.is_probe_pointer(obj)) then
        return '';
    end

    local query_selected, query_page, query_raw, query_child, query_count = accessxi.survival_guide_query_child_state_for_obj(obj);
    local child04 = read_u32(obj + 0x04) or 0;
    local entry = read_u32(obj + 0x08) or 0;
    local child0c = read_u32(obj + 0x0C) or 0;
    local target = safe_call(function () return AshitaCore:GetMemoryManager():GetTarget(); end, nil);
    local focus_index = target ~= nil and (tonumber(safe_call(function () return target:GetFocusTargetIndex(); end, -1)) or -1) or -1;
    local ank_num = target ~= nil and (tonumber(safe_call(function () return target:GetWindowAnkNum(); end, -1)) or -1) or -1;
    local ank_x = target ~= nil and (tonumber(safe_call(function () return target:GetWindowAnkX(); end, -1)) or -1) or -1;
    local ank_y = target ~= nil and (tonumber(safe_call(function () return target:GetWindowAnkY(); end, -1)) or -1) or -1;
    local sub = target ~= nil and (tonumber(safe_call(function () return target:GetWindowSub(); end, -1)) or -1) or -1;
    local sub_x = target ~= nil and (tonumber(safe_call(function () return target:GetWindowSubAnkX(); end, -1)) or -1) or -1;
    local sub_y = target ~= nil and (tonumber(safe_call(function () return target:GetWindowSubAnkY(); end, -1)) or -1) or -1;
    local window_name = target ~= nil and accessxi.plain_native_menu_label(safe_call(function () return target:GetWindowName(); end, '') or '') or '';
    local help_ptr = target ~= nil and (tonumber(safe_call(function () return target:GetWindowHelpString(); end, 0)) or 0) or 0;
    local help_text = accessxi.plain_native_menu_help(read_probe_string(help_ptr, 260));
    local shapes = T{};
    if (target ~= nil) then
        for i = 0, math.min(tonumber(ank_num) or -1, 12) do
            local shape = tonumber(safe_call(function () return target:GetWindowAnkShape(i); end, 0)) or 0;
            if (shape ~= 0) then
                shapes:append(('%d=0x%X'):fmt(i, shape));
            end
        end
    end
    local pointer_texts = T{};
    for _, part in ipairs(T{
        accessxi.title_config_menu_probe_pointer_texts(obj, 'obj'),
        accessxi.title_config_menu_probe_pointer_texts(child04, 'child04'),
        accessxi.title_config_menu_probe_pointer_texts(entry, 'entry'),
        accessxi.title_config_menu_probe_pointer_texts(child0c, 'child0C') }) do
        if (part ~= '') then
            pointer_texts:append(part);
        end
    end

    return ('querySelected=%d queryCount=%d raw=0x%08X child=0x%08X page=%d focus=%d ank=%d,%d,%d sub=%d,%d,%d win="%s" help="%s" shapes="%s" %s %s %s %s texts="%s"'):fmt(
        tonumber(query_selected) or 0,
        tonumber(query_count) or 0,
        tonumber(query_raw) or 0,
        tonumber(query_child) or 0,
        tonumber(query_page) or 0,
        focus_index,
        ank_num,
        ank_x,
        ank_y,
        sub,
        sub_x,
        sub_y,
        accessxi.escape_probe_log_text(window_name),
        accessxi.escape_probe_log_text(help_text),
        accessxi.escape_probe_log_text(shapes:concat(',')),
        accessxi.title_config_menu_probe_fields(obj, 'obj'),
        accessxi.title_config_menu_probe_fields(child04, 'child04'),
        accessxi.title_config_menu_probe_fields(entry, 'entry'),
        accessxi.title_config_menu_probe_fields(child0c, 'child0C'),
        accessxi.escape_probe_log_text_wide(pointer_texts:concat('||')));
end

function accessxi.log_title_config_menu_probe(obj)
    local signature = accessxi.title_config_menu_probe_signature(obj);
    if (signature == '') then
        return;
    end
    local key = ('0x%08X:%s'):fmt(tonumber(obj) or 0, signature);
    if (key == tostring(accessxi.last_title_config_probe_key or '')) then
        return;
    end
    accessxi.last_title_config_probe_key = key;
    log_state(('state title-config probe obj=0x%08X fields="%s"'):fmt(
        tonumber(obj) or 0,
        accessxi.escape_probe_log_text_wide(signature)));

    local child04 = read_u32(obj + 0x04) or 0;
    local entry = read_u32(obj + 0x08) or 0;
    local child0c = read_u32(obj + 0x0C) or 0;
    for _, spec in ipairs(T{
        T{ prefix = 'obj', ptr = obj },
        T{ prefix = 'child04', ptr = child04 },
        T{ prefix = 'entry', ptr = entry },
        T{ prefix = 'child0C', ptr = child0c },
    }) do
        for _, chunk in ipairs(accessxi.title_config_menu_probe_field_chunks(spec.ptr, spec.prefix)) do
            log_state(('state title-config probe-fields obj=0x%08X prefix="%s" part=%d fields="%s"'):fmt(
                tonumber(obj) or 0,
                tostring(spec.prefix or ''),
                tonumber(chunk.part) or 0,
                accessxi.escape_probe_log_text_wide(tostring(chunk.fields or ''))));
        end
    end
    accessxi.title_config_menu_probe_descriptor(obj, entry);
end

function accessxi.log_title_config_menu_focus(obj, selected, count, entry)
    local focus = accessxi.title_config_menu_focus_record(obj);
    local record_y = focus ~= nil and (tonumber(focus.record_y) or -1) or -1;
    local record_x = focus ~= nil and (tonumber(focus.record_x) or 0) or 0;
    local record = focus ~= nil and (tonumber(focus.record) or 0) or 0;
    local entry_ptr = focus ~= nil and (tonumber(focus.entry) or 0) or 0;
    local source = type(entry) == 'table' and tostring(entry.source or '') or '';
    local key = ('%08X:%d:%d:%08X:%08X:%d:%s'):fmt(
        tonumber(obj) or 0,
        tonumber(selected) or -1,
        tonumber(count) or 0,
        record,
        record_x,
        record_y,
        source);
    if (key == tostring(accessxi.last_title_config_focus_log_key or '')) then
        return;
    end
    accessxi.last_title_config_focus_log_key = key;
    log_state(('state title-config focus-record obj=0x%08X focus=%d count=%d entry=0x%08X record=0x%08X x=0x%08X y=0x%X source="%s"'):fmt(
        tonumber(obj) or 0,
        tonumber(selected) or -1,
        tonumber(count) or 0,
        entry_ptr,
        record,
        record_x,
        record_y,
        accessxi.escape_probe_log_text(source)));
end

function accessxi.title_config_menu_speech(obj)
    accessxi.current_menu_speech_title = 'Config';
    local selected, count = accessxi.title_config_menu_selected(obj);
    local entry = accessxi.title_config_menu_entry(selected);
    accessxi.log_title_config_menu_focus(obj, selected, count, entry);
    if (entry == nil or tostring(entry.help or '') == '') then
        log_state(('state title-config quiet focus=%d count=%d reason="unproven-row-signal"'):fmt(selected, count));
        return nil;
    end

    accessxi.current_speech_key = ('title-config:%d:%d:%s'):fmt(
        selected,
        count,
        tostring(entry.source or ''));
    log_state(('state title-config focus=%d count=%d help="%s" source="%s"'):fmt(
        selected,
        count,
        accessxi.escape_probe_log_text(entry.help),
        accessxi.escape_probe_log_text(entry.source or '')));

    return ('Config. %s'):fmt(accessxi.sentence_fragment(entry.help));
end

function accessxi.is_character_creation_menu_name(name)
    return accessxi.menu_name_in_list(name, accessxi.native_menus_data.character_creation_family_menus);
end

function accessxi.character_creation_menu_kind(menu_name)
    menu_name = tostring(menu_name or '');
    if (menu_name:eq('menu    chmkrace', true)) then
        return 'race';
    elseif (menu_name:eq('menu    chmkface', true)) then
        return 'face';
    elseif (menu_name:eq('menu    chmkhair', true)) then
        return 'hair';
    elseif (menu_name:eq('menu    chmksize', true)) then
        return 'size';
    elseif (menu_name:eq('menu    chmkjobs', true)) then
        return 'job';
    elseif (menu_name:eq('menu    chmkname', true)) then
        return 'name';
    elseif (menu_name:eq('menu    chmkserv', true)) then
        return 'server';
    elseif (menu_name:eq('menu    chmktown', true)) then
        return 'nation';
    elseif (menu_name:eq('menu    chmkpass', true)) then
        return 'worldpass';
    elseif (menu_name:eq('menu    worldsel', true)) then
        return 'world';
    end
    return '';
end

function accessxi.is_character_creation_text_input_menu_name(menu_name)
    menu_name = tostring(menu_name or '');
    return menu_name:eq('menu    chmkname', true)
        or menu_name:eq('menu    chmkpass', true);
end

function accessxi.character_creation_focus_record(obj)
    obj = tonumber(obj) or 0;
    if (obj == 0 or not accessxi.is_probe_pointer(obj)) then
        return nil;
    end

    local entry = read_u32(obj + 0x08) or 0;
    local desc04 = accessxi.is_probe_pointer(entry) and (read_u32(entry + 0x04) or 0) or 0;
    local desc0c = accessxi.is_probe_pointer(entry) and (read_u32(entry + 0x0C) or 0) or 0;
    local record = accessxi.is_probe_pointer(desc0c) and (read_u32(desc0c + 0x00) or 0) or 0;
    local record_x = accessxi.is_probe_pointer(record) and (read_u32(record + 0x00) or 0) or 0;
    local record_y = accessxi.is_probe_pointer(record) and (read_u32(record + 0x04) or 0) or 0;

    return T{
        entry = entry,
        desc04 = desc04,
        desc0c = desc0c,
        record = record,
        record_x = record_x,
        record_y = record_y,
    };
end

function accessxi.character_creation_menu_selected(menu_name, obj)
    obj = tonumber(obj) or 0;
    local kind = accessxi.character_creation_menu_kind(menu_name);
    local query_selected, query_page, query_raw, query_child, query_count = accessxi.survival_guide_query_child_state_for_obj(obj);
    local count = tonumber(query_count) or 0;
    if (count <= 0 or count > 64) then
        local count_a = tonumber(read_i32(obj + 0x24)) or 0;
        local count_b = tonumber(read_i32(obj + 0x28)) or 0;
        count = math.max(count_a, count_b);
    end
    if (count < 0 or count > 64) then
        count = 0;
    end

    local focus = accessxi.character_creation_focus_record(obj);
    local state = T{
        reason = 'unproven-row-signal',
        query_selected = tonumber(query_selected) or -1,
        query_page = tonumber(query_page) or 0,
        query_raw = tonumber(query_raw) or 0,
        query_child = tonumber(query_child) or 0,
        query_count = tonumber(query_count) or 0,
        count = count,
        field24 = tonumber(read_i32(obj + 0x24)) or 0,
        field28 = tonumber(read_i32(obj + 0x28)) or 0,
        field30 = tonumber(read_i32(obj + 0x30)) or 0,
        field34 = tonumber(read_i32(obj + 0x34)) or 0,
        field4c = tonumber(read_i32(obj + 0x4C)) or 0,
        field50 = tonumber(read_i32(obj + 0x50)) or 0,
        field58 = tonumber(read_i32(obj + 0x58)) or 0,
        focus = focus,
    };

    if (kind == 'name' or kind == 'worldpass') then
        state.reason = ('%s-window-resource'):fmt(kind);
        return 0, 1, state;
    end

    local selected, source = accessxi.character_creation_race_selected_from_state(kind, state);
    if (selected ~= nil) then
        state.reason = source;
        return selected, count, state;
    end
    selected, source = accessxi.character_creation_face_selected_from_state(kind, state);
    if (selected ~= nil) then
        state.reason = source;
        return selected, count, state;
    end
    selected, source = accessxi.character_creation_hair_selected_from_state(kind, state);
    if (selected ~= nil) then
        state.reason = source;
        return selected, count, state;
    end
    selected, source = accessxi.character_creation_size_selected_from_state(kind, state);
    if (selected ~= nil) then
        state.reason = source;
        return selected, count, state;
    end
    selected, source = accessxi.character_creation_job_selected_from_state(kind, state);
    if (selected ~= nil) then
        state.reason = source;
        return selected, count, state;
    end
    selected, source = accessxi.character_creation_nation_selected_from_state(kind, state);
    if (selected ~= nil) then
        state.reason = source;
        return selected, count, state;
    end
    selected, source = accessxi.character_creation_world_selected_from_state(kind, state);
    if (selected ~= nil) then
        state.reason = source;
        return selected, count, state;
    end

    return -1, count, state;
end

function accessxi.character_creation_race_selected_from_state(kind, state)
    kind = tostring(kind or '');
    state = type(state) == 'table' and state or T{};
    if (kind ~= 'race') then
        return nil, 'not-race';
    end

    local field4c = tonumber(state.field4c) or 0;
    if (field4c < 1 or field4c > 8) then
        return nil, 'race-4c-out-of-range';
    end

    local focus = type(state.focus) == 'table' and state.focus or T{};
    local record_y = tonumber(focus.record_y) or -1;
    local expected_y = 0x06 + ((field4c - 1) * 0x10);
    if (record_y == expected_y) then
        return field4c - 1, 'native-one-4c-record-y';
    end

    return nil, 'race-record-y-mismatch';
end

function accessxi.character_creation_face_selected_from_state(kind, state)
    kind = tostring(kind or '');
    state = type(state) == 'table' and state or T{};
    if (kind ~= 'face') then
        return nil, 'not-face';
    end

    local field4c = tonumber(state.field4c) or 0;
    if (field4c < 1 or field4c > 8) then
        return nil, 'face-4c-out-of-range';
    end

    local focus = type(state.focus) == 'table' and state.focus or T{};
    local record_y = tonumber(focus.record_y) or -1;
    local expected_y = 0x06 + ((field4c - 1) * 0x10);
    if (record_y == expected_y) then
        return field4c - 1, 'native-one-4c-record-y-face';
    end

    return nil, 'face-record-y-mismatch';
end

function accessxi.character_creation_hair_selected_from_state(kind, state)
    kind = tostring(kind or '');
    state = type(state) == 'table' and state or T{};
    if (kind ~= 'hair') then
        return nil, 'not-hair';
    end

    local field4c = tonumber(state.field4c) or 0;
    if (field4c < 1 or field4c > 2) then
        return nil, 'hair-4c-out-of-range';
    end

    local focus = type(state.focus) == 'table' and state.focus or T{};
    local record_y = tonumber(focus.record_y) or -1;
    local expected_y = 0x06 + ((field4c - 1) * 0x10);
    if (record_y == expected_y) then
        return field4c - 1, 'native-one-4c-record-y-hair';
    end

    return nil, 'hair-record-y-mismatch';
end

function accessxi.character_creation_size_selected_from_state(kind, state)
    kind = tostring(kind or '');
    state = type(state) == 'table' and state or T{};
    if (kind ~= 'size') then
        return nil, 'not-size';
    end

    local field4c = tonumber(state.field4c) or 0;
    if (field4c < 1 or field4c > 3) then
        return nil, 'size-4c-out-of-range';
    end

    local focus = type(state.focus) == 'table' and state.focus or T{};
    local record_y = tonumber(focus.record_y) or -1;
    local expected_y = 0x06 + ((field4c - 1) * 0x10);
    if (record_y == expected_y) then
        return field4c - 1, 'native-one-4c-record-y-size';
    end

    return nil, 'size-record-y-mismatch';
end

function accessxi.character_creation_job_selected_from_state(kind, state)
