    if (field4c < 1 or field4c > 3) then
        return nil, 'nation-4c-out-of-range';
    end

    local focus = type(state.focus) == 'table' and state.focus or T{};
    local record_y = tonumber(focus.record_y) or -1;
    local expected_y = 0x06 + ((field4c - 1) * 0x10);
    if (record_y == expected_y) then
        return field4c, 'native-one-4c-record-y-nation';
    end

    return nil, 'nation-record-y-mismatch';
end

function accessxi.character_creation_world_selected_from_state(kind, state)
    kind = tostring(kind or '');
    state = type(state) == 'table' and state or T{};
    if (kind ~= 'world') then
        return nil, 'not-world';
    end

    local count = tonumber(state.count) or 0;
    if (count <= 0 or count > 64) then
        count = math.max(tonumber(state.field24) or 0, tonumber(state.field28) or 0);
    end
    if (count <= 0 or count > 64) then
        return nil, 'world-count-out-of-range';
    end

    local field4c = tonumber(state.field4c) or 0;
    local query_selected = tonumber(state.query_selected) or 0;
    local focus = type(state.focus) == 'table' and state.focus or T{};
    local record_y = tonumber(focus.record_y) or -1;
    local expected_y = field4c > 0 and (0x05 + ((field4c - 1) * 0x10)) or -2;
    if (field4c >= 1 and field4c <= count and record_y == expected_y) then
        return field4c, 'native-one-4c-record-y-world';
    end

    if (query_selected >= 1 and query_selected <= count and query_selected == field4c) then
        return query_selected, 'native-query-4c-agree-world';
    end

    return nil, 'world-unproven-row-signal';
end

function accessxi.character_creation_template_value(value)
    value = accessxi.survival_guide_text(tostring(value or ''):gsub('\r', ''));
    value = value:gsub('^["\']+', ''):gsub('["\']+$', '');
    value = accessxi.survival_guide_text(value);
    if (value == '' or #value > 16) then
        return '';
    end
    if (value:match('^[%p%s]+$') ~= nil) then
        return '';
    end
    return value;
end

function accessxi.character_creation_dat_value_text(dat_path, row)
    dat_path = tostring(dat_path or '');
    row = tonumber(row) or -1;
    if (dat_path == '' or row < 0) then
        return '';
    end

    local path = accessxi.dat_index_path();
    local f = io.open(path, 'rb');
    if (f == nil) then
        return '';
    end

    local text = '';
    for line in f:lines() do
        local _, _, line_dat_path, index, value = line:match('^(%d+)\t([^\t]+)\t([^\t]+)\t(%d+)\t(.*)$');
        if (line_dat_path == dat_path and (tonumber(index) or -1) == row) then
            text = accessxi.character_creation_template_value(value);
            break;
        end
    end
    f:close();
    return text;
end

function accessxi.character_creation_long_prompt_text(text)
    text = accessxi.survival_guide_text(tostring(text or ''):gsub('\r', ''));
    if (text == '') then
        return '';
    end

    text = text:gsub('^["\']+', ''):gsub('["\']+$', '');
    text = accessxi.survival_guide_text(text);
    if (text == '' or #text > 900) then
        return '';
    end
    if (text:match('^[%p%s]+$') ~= nil) then
        return '';
    end
    if (text:find('menu    ', 1, true) ~= nil or text:find('anc     ', 1, true) ~= nil) then
        return '';
    end
    return text;
end

function accessxi.character_creation_dat_long_text(dat_path, row)
    dat_path = tostring(dat_path or '');
    row = tonumber(row) or -1;
    if (dat_path == '' or row < 0) then
        return '';
    end

    accessxi.character_creation_dat_long_text_cache = accessxi.character_creation_dat_long_text_cache or {};
    local key = ('%s:%d'):fmt(dat_path, row);
    local cached = accessxi.character_creation_dat_long_text_cache[key];
    if (cached ~= nil) then
        return cached;
    end

    local text = '';
    local path = accessxi.dat_index_path();
    local f = io.open(path, 'rb');
    if (f ~= nil) then
        for line in f:lines() do
            local _, _, line_dat_path, index, value = line:match('^(%d+)\t([^\t]+)\t([^\t]+)\t(%d+)\t(.*)$');
            if (line_dat_path == dat_path and (tonumber(index) or -1) == row) then
                text = accessxi.character_creation_long_prompt_text(value);
                break;
            end
        end
        f:close();
    end

    accessxi.character_creation_dat_long_text_cache[key] = text;
    return text;
end

function accessxi.character_creation_world_name_resource()
    if (accessxi.character_creation_world_name_resource_cache ~= nil) then
        return accessxi.character_creation_world_name_resource_cache;
    end

    local resource = T{
        by_label = {},
        by_row = {},
        labels = T{},
    };
    local seen_rows = {};

    local path = accessxi.dat_index_path();
    local f = io.open(path, 'rb');
    if (f ~= nil) then
        for line in f:lines() do
            local _, _, line_dat_path, index, value = line:match('^(%d+)\t([^\t]+)\t([^\t]+)\t(%d+)\t(.*)$');
            local row = tonumber(index) or -1;
            if (line_dat_path == 'ROM\\333\\34.DAT' and row >= 98 and row <= 131 and seen_rows[row] ~= true) then
                local label = accessxi.plain_native_menu_label(accessxi.survival_guide_text(tostring(value or ''):gsub('\r', '')));
                if (label ~= '') then
                    seen_rows[row] = true;
                    local entry = T{
                        label = label,
                        row = row,
                        source = ('ROM\\333\\34.DAT:%d'):fmt(row),
                    };
                    resource.by_label[label:lower()] = entry;
                    resource.by_row[row] = entry;
                    resource.labels:append(entry);
                end
            end
        end
        f:close();
    end

    accessxi.character_creation_world_name_resource_cache = resource;
    return resource;
end

function accessxi.character_creation_world_dat_match(label)
    label = accessxi.survival_guide_native_label_for_speech(label or '', 'plain');
    label = accessxi.plain_native_menu_label(label or '');
    if (label == '') then
        return nil;
    end

    local resource = accessxi.character_creation_world_name_resource();
    if (type(resource) ~= 'table' or type(resource.by_label) ~= 'table') then
        return nil;
    end
    return resource.by_label[label:lower()];
end

function accessxi.character_creation_world_packet_name(name)
    name = clean_probe_text(name or '');
    name = accessxi.survival_guide_native_label_for_speech(name, 'plain');
    return accessxi.plain_native_menu_label(name or '');
end

function accessxi.character_creation_world_packet_rows_preview(rows, limit)
    rows = type(rows) == 'table' and rows or T{};
    limit = math.max(1, math.min(tonumber(limit) or 24, 64));
    local parts = T{};
    for index, row in ipairs(rows) do
        parts:append(('%d:%s#%d'):fmt(
            index,
            tostring(row.label or ''),
            tonumber(row.id) or -1));
        if (parts:len() >= limit) then
            break;
        end
    end
    return parts:concat('|');
end

function accessxi.character_creation_world_ascii_bytes(ptr, length)
    ptr = tonumber(ptr) or 0;
    length = tonumber(length) or 0;
    if (not accessxi.is_probe_pointer(ptr) or length <= 0 or length > 0x2000) then
        return '';
    end

    local bytes = T{};
    for off = 0, length - 1 do
        local value = read_u8(ptr + off);
        if (value == nil) then
            break;
        end
        bytes:append(string.char(value));
    end
    return bytes:concat('');
end

function accessxi.character_creation_world_utf16le_pattern(text)
    text = tostring(text or '');
    if (text == '') then
        return '';
    end

    local bytes = T{};
    for i = 1, #text do
        bytes:append(text:sub(i, i));
        bytes:append('\0');
    end
    return bytes:concat('');
end

function accessxi.character_creation_world_name_hits(ptr, length, limit)
    ptr = tonumber(ptr) or 0;
    length = tonumber(length) or 0x400;
    limit = math.max(1, math.min(tonumber(limit) or 16, 64));
    if (not accessxi.is_probe_pointer(ptr)) then
        return T{};
    end

    local blob = accessxi.character_creation_world_ascii_bytes(ptr, length);
    if (blob == '') then
        return T{};
    end

    local resource = accessxi.character_creation_world_name_resource();
    local hits = T{};
    local seen = {};
    for _, entry in ipairs(resource.labels or T{}) do
        local label = tostring(entry.label or '');
        if (#label >= 3) then
            local pos = blob:find(label, 1, true);
            if (pos ~= nil) then
                local key = ('ascii:%s:%d'):fmt(label:lower(), pos);
                if (seen[key] ~= true) then
                    seen[key] = true;
                    hits:append(T{ label = label, row = tonumber(entry.row) or -1, offset = pos - 1, mode = 'ascii' });
                end
            end

            local utf16 = accessxi.character_creation_world_utf16le_pattern(label);
            pos = utf16 ~= '' and blob:find(utf16, 1, true) or nil;
            if (pos ~= nil) then
                local key = ('utf16:%s:%d'):fmt(label:lower(), pos);
                if (seen[key] ~= true) then
                    seen[key] = true;
                    hits:append(T{ label = label, row = tonumber(entry.row) or -1, offset = pos - 1, mode = 'utf16' });
                end
            end
        end

        if (hits:len() >= limit) then
            break;
        end
    end

    table.sort(hits, function (a, b)
        local ao = tonumber(a.offset) or 0;
        local bo = tonumber(b.offset) or 0;
        if (ao == bo) then
            return tostring(a.label or '') < tostring(b.label or '');
        end
        return ao < bo;
    end);
    return hits;
end

function accessxi.character_creation_world_name_hit_summary(roots, length, limit)
    roots = type(roots) == 'table' and roots or T{};
    length = tonumber(length) or 0x400;
    limit = math.max(1, math.min(tonumber(limit) or 24, 64));

    local parts = T{};
    for _, root in ipairs(roots) do
        if (parts:len() >= limit) then
            break;
        end
        local label = tostring(root.label or '');
        local ptr = tonumber(root.ptr) or 0;
        if (accessxi.is_probe_pointer(ptr)) then
            local hits = accessxi.character_creation_world_name_hits(ptr, length, limit);
            for _, hit in ipairs(hits) do
                parts:append(('%s:%s+%03X=%s#%d'):fmt(
                    label,
                    tostring(hit.mode or ''),
                    tonumber(hit.offset) or 0,
                    tostring(hit.label or ''),
                    tonumber(hit.row) or -1));
                if (parts:len() >= limit) then
                    break;
                end
            end
        end
    end
    return parts:concat('|');
end

function accessxi.character_creation_world_hit_record_summary(label, ptr, length, limit)
    label = tostring(label or '');
    ptr = tonumber(ptr) or 0;
    length = tonumber(length) or 0x800;
    limit = math.max(1, math.min(tonumber(limit) or 24, 64));
    if (not accessxi.is_probe_pointer(ptr)) then
        return '';
    end

    local hits = accessxi.character_creation_world_name_hits(ptr, length, limit);
    local parts = T{};
    for _, hit in ipairs(hits) do
        local offset = tonumber(hit.offset) or 0;
        local slot_offset = offset >= 4 and (offset - 4) or offset;
        local slot = ptr + slot_offset;
        local world_id = read_u32(slot) or -1;
        local name = accessxi.character_creation_world_packet_name(read_probe_string(ptr + offset, 16));
        local world = accessxi.character_creation_world_dat_match(name);
        local id_ok = world ~= nil and (tonumber(world.row) or -2) == world_id;
        parts:append(('%s+%03X id=%d name=%s dat=%s d=%s'):fmt(
            label,
            slot_offset,
            world_id,
            tostring(name or ''),
            id_ok and 'yes' or 'no',
            accessxi.format_probe_dwords(slot, 0x00, 5)));
        if (parts:len() >= limit) then
            break;
        end
    end
    return parts:concat('|');
end

function accessxi.character_creation_world_direct_record_hits(ptr, length, limit)
    ptr = tonumber(ptr) or 0;
    length = tonumber(length) or 0x800;
    limit = math.max(1, math.min(tonumber(limit) or 64, 128));
    if (not accessxi.is_probe_pointer(ptr)) then
        return T{};
    end

    local resource = accessxi.character_creation_world_name_resource();
    local by_row = type(resource) == 'table' and type(resource.by_row) == 'table' and resource.by_row or {};
    local hits = T{};
    for offset = 0, math.max(0, length - 0x14), 4 do
        local world_id = read_u32(ptr + offset) or -1;
        if (by_row[world_id] ~= nil) then
            local name = accessxi.character_creation_world_packet_name(read_probe_string(ptr + offset + 0x04, 16));
            local world = accessxi.character_creation_world_dat_match(name);
            if (world ~= nil and (tonumber(world.row) or -2) == world_id) then
                hits:append(T{
                    offset = offset,
                    id = world_id,
                    label = world.label,
                    source = world.source,
                    dwords = accessxi.format_probe_dwords(ptr, offset, 5),
                });
                if (hits:len() >= limit) then
                    break;
                end
            end
        end
    end
    return hits;
end

function accessxi.character_creation_world_direct_record_preview(records, limit)
    records = type(records) == 'table' and records or T{};
    limit = math.max(1, math.min(tonumber(limit) or 64, 128));

    local parts = T{};
    for index, record in ipairs(records) do
        parts:append(('%03X:%d:%s'):fmt(
            tonumber(record.offset) or 0,
            tonumber(record.id) or -1,
            tostring(record.label or '')));
        if (index >= limit) then
            break;
        end
    end
    return parts:concat('|');
end

function accessxi.character_creation_world_direct_record_window_summary(records, expected_count, limit)
    records = type(records) == 'table' and records or T{};
    expected_count = tonumber(expected_count) or 0;
    limit = math.max(1, math.min(tonumber(limit) or 8, 24));
    if (expected_count <= 0 or expected_count > 64 or records:len() < expected_count) then
        return '';
    end

    local sorted = T{};
    for _, record in ipairs(records) do
        sorted:append(record);
    end
    table.sort(sorted, function (a, b)
        return (tonumber(a.offset) or 0) < (tonumber(b.offset) or 0);
    end);

    local windows = T{};
    for start_index = 1, sorted:len() - expected_count + 1 do
        local ok = true;
        local seen = {};
        local labels = T{};
        for inner = 0, expected_count - 1 do
            local record = sorted[start_index + inner];
            local previous = inner > 0 and sorted[start_index + inner - 1] or nil;
            if (previous ~= nil and ((tonumber(record.offset) or 0) - (tonumber(previous.offset) or 0)) ~= 0x14) then
                ok = false;
                break;
            end
            local id = tonumber(record.id) or -1;
            if (seen[id] == true) then
                ok = false;
                break;
            end
            seen[id] = true;
            labels:append(tostring(record.label or ''));
        end
        if (ok) then
            local first = sorted[start_index];
            local last = sorted[start_index + expected_count - 1];
            windows:append(('start=0x%03X end=0x%03X labels=%s'):fmt(
                tonumber(first.offset) or 0,
                tonumber(last.offset) or 0,
                labels:concat(',')));
            if (windows:len() >= limit) then
                break;
            end
        end
    end
    return windows:concat('|');
end

function accessxi.character_creation_world_record_pointer_lookup(records, child0c)
    records = type(records) == 'table' and records or T{};
    child0c = tonumber(child0c) or 0;

    local lookup = {};
    if (not accessxi.is_probe_pointer(child0c)) then
        return lookup;
    end

    for _, record in ipairs(records) do
        local offset = tonumber(record.offset) or -1;
        if (offset >= 0) then
            lookup[child0c + offset] = ('rec+%03X:%s#%d'):fmt(
                offset,
                tostring(record.label or ''),
                tonumber(record.id) or -1);
            lookup[child0c + offset + 0x04] = ('name+%03X:%s#%d'):fmt(
                offset,
                tostring(record.label or ''),
                tonumber(record.id) or -1);
        end
    end
    return lookup;
end

function accessxi.character_creation_world_record_ref_summary(label, ptr, records, child0c, length, limit)
    label = tostring(label or '');
    ptr = tonumber(ptr) or 0;
    length = math.max(0, math.min(tonumber(length) or 0x100, 0x800));
    limit = math.max(1, math.min(tonumber(limit) or 16, 64));
    if (not accessxi.is_probe_pointer(ptr) or length <= 0) then
        return '';
    end

    local lookup = accessxi.character_creation_world_record_pointer_lookup(records, child0c);
    local parts = T{};
    for offset = 0, length - 4, 4 do
        local value = read_u32(ptr + offset) or 0;
        local target = lookup[value];
        if (target ~= nil) then
            parts:append(('%s+%03X->%s@0x%08X'):fmt(
                label,
                offset,
                tostring(target or ''),
                value));
            if (parts:len() >= limit) then
                break;
            end
        end
    end
    return parts:concat('|');
end

function accessxi.character_creation_world_id_array_summary(label, ptr, length, expected_count, limit)
    label = tostring(label or '');
    ptr = tonumber(ptr) or 0;
    length = math.max(0, math.min(tonumber(length) or 0x400, 0x1800));
    expected_count = tonumber(expected_count) or 0;
    limit = math.max(1, math.min(tonumber(limit) or 8, 24));
    if (not accessxi.is_probe_pointer(ptr) or length <= 0) then
        return '';
    end

    local resource = accessxi.character_creation_world_name_resource();
    local by_row = type(resource) == 'table' and type(resource.by_row) == 'table' and resource.by_row or {};
    local max_rows = expected_count > 0 and math.min(expected_count, 32) or 32;
    local min_rows = expected_count > 0 and math.min(expected_count, 32) or 8;
    local parts = T{};
    local seen = {};

    local function append_candidate(width_label, offset, ids, labels, unique_count)
        local key = ('%s:%03X:%s'):fmt(width_label, offset, ids);
        if (seen[key] == true) then
            return;
        end
        seen[key] = true;
        parts:append(('%s:%s+%03X len=%d uniq=%d ids=%s labels=%s'):fmt(
            label,
            width_label,
            offset,
            ids:len(),
            unique_count,
            ids:concat(','),
            labels:concat(',')));
    end

    local function scan_width(width_label, width, reader)
        for offset = 0, math.max(0, length - width) do
            if (parts:len() >= limit) then
                break;
            end

            local ids = T{};
            local labels = T{};
            local row_seen = {};
            local unique_count = 0;
            for index = 0, max_rows - 1 do
                local value = reader(ptr + offset + (index * width));
                local world = by_row[value or -1];
                if (world == nil) then
                    break;
                end
                ids:append(tonumber(value) or -1);
                labels:append(tostring(world.label or ''));
                if (row_seen[value] ~= true) then
                    row_seen[value] = true;
                    unique_count = unique_count + 1;
                end
            end

            if (ids:len() >= min_rows and unique_count == ids:len()) then
                append_candidate(width_label, offset, ids, labels, unique_count);
            end
        end
    end

    scan_width('u8', 1, function (addr) return read_u8(addr); end);
    scan_width('u16', 2, function (addr) return read_u16(addr); end);
    scan_width('u32', 4, function (addr) return read_u32(addr); end);

    return parts:concat('|');
end

function accessxi.character_creation_world_record_pointer_array_summary(label, ptr, records, child0c, length, expected_count, limit)
    label = tostring(label or '');
    ptr = tonumber(ptr) or 0;
    length = math.max(0, math.min(tonumber(length) or 0x400, 0x1800));
    expected_count = tonumber(expected_count) or 0;
    limit = math.max(1, math.min(tonumber(limit) or 8, 24));
    if (not accessxi.is_probe_pointer(ptr) or length <= 0) then
        return '';
    end

    local lookup = accessxi.character_creation_world_record_pointer_lookup(records, child0c);
    local max_rows = expected_count > 0 and math.min(expected_count, 32) or 32;
    local min_rows = expected_count > 0 and math.min(expected_count, 32) or 4;
    local parts = T{};
    local seen = {};

    for offset = 0, math.max(0, length - 4), 4 do
        if (parts:len() >= limit) then
            break;
        end

        local refs = T{};
        local unique_refs = {};
        local unique_count = 0;
        for index = 0, max_rows - 1 do
            local value = read_u32(ptr + offset + (index * 4)) or 0;
            local ref = lookup[value];
            if (ref == nil) then
                break;
            end
            refs:append(ref);
            if (unique_refs[ref] ~= true) then
                unique_refs[ref] = true;
                unique_count = unique_count + 1;
            end
        end

        if (refs:len() >= min_rows and unique_count == refs:len()) then
            local ref_text = refs:concat(',');
            local key = ('%03X:%s'):fmt(offset, ref_text);
            if (seen[key] ~= true) then
                seen[key] = true;
                parts:append(('%s:ptr+%03X len=%d uniq=%d refs=%s'):fmt(
                    label,
                    offset,
                    refs:len(),
                    unique_count,
                    ref_text));
            end
        end
    end

    return parts:concat('|');
end

function accessxi.character_creation_world_store_packet_rows(rows, source, base)
    rows = type(rows) == 'table' and rows or T{};
    if (rows:len() <= 0) then
        return false;
    end

    local key = accessxi.character_creation_world_packet_rows_preview(rows, 64);
    accessxi.character_creation_world_packet_rows = rows;
    accessxi.character_creation_world_packet_source = tostring(source or '');
    accessxi.character_creation_world_packet_base = tonumber(base) or 0;
    accessxi.character_creation_world_packet_tick = tick();

    local log_key = ('%s:%s:%08X'):fmt(
        tostring(source or ''),
        key,
        tonumber(base) or 0);
    if (log_key ~= tostring(accessxi.character_creation_world_packet_log_key or '')) then
        accessxi.character_creation_world_packet_log_key = log_key;
        log_state(('state character-creation world-list source="%s" base=0x%08X count=%d rows="%s"'):fmt(
            accessxi.escape_probe_log_text(tostring(source or '')),
            tonumber(base) or 0,
            rows:len(),
            accessxi.escape_probe_log_text_wide(key)));
    end
    return true;
end

function accessxi.character_creation_world_record_from_memory(ptr, source)
    ptr = tonumber(ptr) or 0;
    if (not accessxi.is_probe_pointer(ptr)) then
        return nil, 'record-pointer-invalid';
    end

    local world_id = read_u32(ptr + 0x00) or -1;
    local label = accessxi.character_creation_world_packet_name(read_probe_string(ptr + 0x04, 16));
    local world = accessxi.character_creation_world_dat_match(label);
    if (world == nil) then
        return nil, ('record-name-not-dat:%s'):fmt(label);
    end
    if ((tonumber(world.row) or -2) ~= world_id) then
        return nil, ('record-id-name-mismatch:%d:%s:%d'):fmt(world_id, world.label, tonumber(world.row) or -1);
    end

    return T{
        id = world_id,
        label = world.label,
        ptr = ptr,
        source = tostring(source or ''),
        world_source = tostring(world.source or ''),
    }, 'ok';
end

function accessxi.character_creation_world_rows_from_memory_records(record_base, count, source)
    record_base = tonumber(record_base) or 0;
    count = tonumber(count) or 0;
    if (not accessxi.is_probe_pointer(record_base) or count <= 0 or count > 64) then
        return nil, 'records-invalid';
    end

    local rows = T{};
    local seen_ids = {};
    local seen_labels = {};
    for index = 1, count do
        local record, reason = accessxi.character_creation_world_record_from_memory(record_base + ((index - 1) * 0x14), source);
        if (record == nil) then
            return nil, ('record-%d-%s'):fmt(index, tostring(reason or 'invalid'));
        end
        local id_key = tostring(record.id or '');
        local label_key = tostring(record.label or ''):lower();
        if (seen_ids[id_key] == true or seen_labels[label_key] == true) then
            return nil, ('record-%d-duplicate'):fmt(index);
        end
        seen_ids[id_key] = true;
        seen_labels[label_key] = true;
        rows:append(record);
    end

    return rows, 'ok';
end

function accessxi.character_creation_world_record_sequence_from_hit(record_ptr, source)
    record_ptr = tonumber(record_ptr) or 0;
    if (not accessxi.is_probe_pointer(record_ptr)) then
        return nil, 'sequence-hit-invalid';
    end

    local base = record_ptr;
    for _ = 1, 63 do
        local prev = base - 0x14;
        local record = accessxi.character_creation_world_record_from_memory(prev, source);
        if (record == nil) then
            break;
        end
        base = prev;
    end

    local rows = T{};
    local seen_ids = {};
    local seen_labels = {};
    local ptr = base;
    for _ = 1, 64 do
        local record = accessxi.character_creation_world_record_from_memory(ptr, source);
        if (record == nil) then
            break;
        end
        local id_key = tostring(record.id or '');
        local label_key = tostring(record.label or ''):lower();
        if (seen_ids[id_key] == true or seen_labels[label_key] == true) then
            break;
        end
        seen_ids[id_key] = true;
        seen_labels[label_key] = true;
        rows:append(record);
        ptr = ptr + 0x14;
    end

    if (rows:len() < 4) then
        return nil, ('sequence-short-%d'):fmt(rows:len());
    end

    return rows, 'ok', base;
end

function accessxi.character_creation_world_packet_rows_at(base, source)
    base = tonumber(base) or 0;
    if (not accessxi.is_probe_pointer(base)) then
        return nil, 'packet-base-invalid';
    end

    local packet_size = read_u32(base + 0x00) or 0;
    local terminator = read_u32(base + 0x04) or 0;
    local command = read_u32(base + 0x08) or 0;
    local count = read_u32(base + 0x1C) or 0;
    if (terminator ~= 0x46465849 or command ~= 0x23) then
        return nil, ('packet-shape-mismatch:%08X:%08X'):fmt(terminator, command);
    end
    if (count <= 0 or count > 64) then
        return nil, ('packet-count-invalid:%d'):fmt(count);
    end

    local expected_size = 0x20 + (count * 0x14);
    if (packet_size ~= expected_size) then
        return nil, ('packet-size-mismatch:%d:%d'):fmt(packet_size, expected_size);
    end

    local rows, reason = accessxi.character_creation_world_rows_from_memory_records(base + 0x20, count, source);
    if (rows == nil or rows:len() ~= count) then
        return nil, ('packet-records-%s'):fmt(tostring(reason or 'invalid'));
    end
    return rows, 'ok';
end

function accessxi.character_creation_world_rows_from_data_records(data, pos, count, source)
    data = tostring(data or '');
    pos = tonumber(pos) or 1;
    count = tonumber(count) or 0;
    if (pos < 1 or count <= 0 or count > 64 or #data < (pos - 1 + (count * 0x14))) then
        return nil, 'data-records-invalid';
    end

    local rows = T{};
    local seen_ids = {};
    local seen_labels = {};
    for index = 1, count do
        local rec_pos = pos + ((index - 1) * 0x14);
        local world_id = accessxi.packet_u32(data, rec_pos);
        local raw_name = data:sub(rec_pos + 4, rec_pos + 4 + 15):gsub('%z.*$', '');
        local label = accessxi.character_creation_world_packet_name(raw_name);
        local world = accessxi.character_creation_world_dat_match(label);
        if (world == nil or (tonumber(world.row) or -2) ~= world_id) then
            return nil, ('data-record-%d-mismatch'):fmt(index);
        end

        local id_key = tostring(world_id);
        local label_key = tostring(world.label or ''):lower();
        if (seen_ids[id_key] == true or seen_labels[label_key] == true) then
            return nil, ('data-record-%d-duplicate'):fmt(index);
        end
        seen_ids[id_key] = true;
        seen_labels[label_key] = true;
        rows:append(T{
            id = world_id,
            label = world.label,
            ptr = 0,
            source = tostring(source or ''),
            world_source = tostring(world.source or ''),
        });
    end

    return rows, 'ok';
end

function accessxi.character_creation_world_packet_rows_from_data(data, source)
    data = tostring(data or '');
    if (#data < 0x20) then
        return nil, 'data-short';
    end

    local function parse_packet_at(pos)
        if (pos < 1 or #data < (pos - 1 + 0x20)) then
            return nil, 'data-packet-short';
        end
        local packet_size = accessxi.packet_u32(data, pos);
        local terminator = accessxi.packet_u32(data, pos + 4);
        local command = accessxi.packet_u32(data, pos + 8);
        local count = accessxi.packet_u32(data, pos + 0x1C);
        if (terminator ~= 0x46465849 or command ~= 0x23 or count <= 0 or count > 64) then
            return nil, 'data-packet-shape';
        end
        local expected_size = 0x20 + (count * 0x14);
        if (packet_size ~= expected_size or #data < (pos - 1 + expected_size)) then
            return nil, 'data-packet-size';
        end
        return accessxi.character_creation_world_rows_from_data_records(data, pos + 0x20, count, source);
    end

    local rows, reason = parse_packet_at(1);
    if (rows ~= nil) then
        return rows, 'data-packet';
    end

    local count = accessxi.packet_u32(data, 1);
    if (count > 0 and count <= 64 and #data >= (4 + (count * 0x14))) then
        rows, reason = accessxi.character_creation_world_rows_from_data_records(data, 5, count, source);
        if (rows ~= nil) then
            return rows, 'data-counted';
        end
    end

    local start_at = 1;
    while true do
        local pos = data:find('IXFF', start_at, true);
        if (pos == nil) then
            break;
        end
        rows, reason = parse_packet_at(pos - 4);
        if (rows ~= nil) then
            return rows, 'data-embedded-packet';
        end
        start_at = pos + 1;
    end

    return nil, reason or 'data-world-list-missing';
end

function accessxi.capture_character_creation_world_packet(e)
    if (e == nil) then
        return false;
    end

    local id = tonumber(e.id) or 0;
    if (id ~= 0x23) then
        return false;
    end

    local data = accessxi.packet_event_string(e, 'data_modified', 'size');
    if (data == '') then
        data = accessxi.packet_event_string(e, 'data', 'size');
    end
    if (data == '') then
        data = e.data_modified or e.data or '';
    end

    local rows, reason = accessxi.character_creation_world_packet_rows_from_data(data, 'packet_in_023');
    if (rows ~= nil and accessxi.character_creation_world_store_packet_rows(rows, 'packet_in_023', 0)) then
        return true;
    end

    local key = ('%d:%s'):fmt(#data, tostring(reason or ''));
    if (key ~= tostring(accessxi.character_creation_world_packet_reject_key or '')) then
        accessxi.character_creation_world_packet_reject_key = key;
        log_state(('state character-creation world-list-packet reject id=0x%03X len=%d reason="%s" hex="%s"'):fmt(
            id,
            #data,
            accessxi.escape_probe_log_text(tostring(reason or '')),
            accessxi.escape_probe_log_text(accessxi.packet_hex_limit(data, 96))));
    end
    return false;
end

function accessxi.arm_character_creation_world_packet_trace(source, duration_ms, limit)
    local now = tick();
    duration_ms = math.max(1000, math.min(tonumber(duration_ms) or 15000, 30000));
    limit = math.max(1, math.min(tonumber(limit) or 80, 160));

    if ((tonumber(accessxi.character_creation_world_packet_trace_until) or 0) <= now) then
        accessxi.character_creation_world_packet_trace_count = 0;
        accessxi.character_creation_world_packet_trace_key = '';
    end

    accessxi.character_creation_world_packet_trace_until = math.max(
        tonumber(accessxi.character_creation_world_packet_trace_until) or 0,
        now + duration_ms);
    accessxi.character_creation_world_packet_trace_limit = limit;

    local arm_key = ('%s:%d:%d'):fmt(tostring(source or ''), duration_ms, limit);
    if (arm_key ~= tostring(accessxi.character_creation_world_packet_trace_arm_key or '')
        or (now - (tonumber(accessxi.character_creation_world_packet_trace_arm_tick) or 0)) > 5000) then
        accessxi.character_creation_world_packet_trace_arm_key = arm_key;
        accessxi.character_creation_world_packet_trace_arm_tick = now;
        log_state(('state character-creation world-packet-trace-arm source="%s" duration=%d limit=%d'):fmt(
            accessxi.escape_probe_log_text(tostring(source or '')),
            duration_ms,
            limit));
    end
end

function accessxi.character_creation_world_packet_trace_active()
    local now = tick();
    if ((tonumber(accessxi.character_creation_world_packet_trace_until) or 0) > now) then
        return true;
    end

    local live_name = tostring(get_menu_name() or '');
    if (live_name:eq('menu    worldsel', true)) then
        return true;
    end

    local current_name = tostring(accessxi.current_menu_name or '');
    return current_name:eq('menu    worldsel', true);
end

function accessxi.character_creation_world_packet_data_name_hit_summary(data, limit)
    data = tostring(data or '');
    limit = math.max(1, math.min(tonumber(limit) or 16, 64));
    if (data == '') then
        return '';
    end

    local resource = accessxi.character_creation_world_name_resource();
    local hits = T{};
    local seen = {};
    for _, entry in ipairs(resource.labels or T{}) do
        local label = tostring(entry.label or '');
        if (#label >= 3) then
            local pos = data:find(label, 1, true);
            if (pos ~= nil) then
                local key = ('ascii:%s:%d'):fmt(label:lower(), pos);
                if (seen[key] ~= true) then
                    seen[key] = true;
                    hits:append(T{
                        mode = 'ascii',
                        offset = pos - 1,
                        label = label,
                        row = tonumber(entry.row) or -1,
                    });
                end
            end

            local utf16 = accessxi.character_creation_world_utf16le_pattern(label);
            pos = utf16 ~= '' and data:find(utf16, 1, true) or nil;
            if (pos ~= nil) then
                local key = ('utf16:%s:%d'):fmt(label:lower(), pos);
                if (seen[key] ~= true) then
                    seen[key] = true;
                    hits:append(T{
                        mode = 'utf16',
                        offset = pos - 1,
                        label = label,
                        row = tonumber(entry.row) or -1,
                    });
                end
            end
        end
    end

    table.sort(hits, function (a, b)
        local ao = tonumber(a.offset) or 0;
        local bo = tonumber(b.offset) or 0;
        if (ao == bo) then
            return tostring(a.label or '') < tostring(b.label or '');
        end
        return ao < bo;
    end);

    local parts = T{};
    for _, hit in ipairs(hits) do
        parts:append(('%s+%03X=%s#%d'):fmt(
            tostring(hit.mode or ''),
            tonumber(hit.offset) or 0,
            tostring(hit.label or ''),
            tonumber(hit.row) or -1));
        if (parts:len() >= limit) then
            break;
        end
    end
    return parts:concat('|');
end

function accessxi.trace_character_creation_world_packet(e, direction)
    if (e == nil or not accessxi.character_creation_world_packet_trace_active()) then
        return false;
    end

    local count = tonumber(accessxi.character_creation_world_packet_trace_count) or 0;
    local limit = tonumber(accessxi.character_creation_world_packet_trace_limit) or 80;
    if (count >= limit) then
        return false;
    end

    local id = tonumber(e.id) or 0;
    local data = accessxi.packet_event_string(e, 'data_modified', 'size');
    if (data == '') then
        data = accessxi.packet_event_string(e, 'data', 'size');
    end
    if (data == '') then
        data = e.data_modified or e.data or '';
    end
    data = tostring(data or '');

    local rows, reason = accessxi.character_creation_world_packet_rows_from_data(data, 'packet-trace');
    local rows_preview = rows ~= nil and accessxi.character_creation_world_packet_rows_preview(rows, 24) or '';
    local world_hits = accessxi.character_creation_world_packet_data_name_hit_summary(data, 16);
    local has_ixff = data:find('IXFF', 1, true) ~= nil;
    local parse_text = rows ~= nil and 'ok' or tostring(reason or '');
    local live_name = tostring(get_menu_name() or accessxi.current_menu_name or '');
    local key = ('%s:%03X:%d:%s:%s:%s'):fmt(
        tostring(direction or 'in'),
        id,
        #data,
        accessxi.packet_hex_limit(data, 24),
        parse_text,
        world_hits);
    if (key == tostring(accessxi.character_creation_world_packet_trace_key or '')) then
        return false;
    end
    accessxi.character_creation_world_packet_trace_key = key;
    accessxi.character_creation_world_packet_trace_count = count + 1;

    log_state(('state character-creation world-packet-trace dir="%s" index=%d limit=%d menu="%s" id=0x%03X len=%d ixff=%s parse="%s" rows="%s" worldHits="%s" ascii="%s" hex="%s"'):fmt(
        accessxi.escape_probe_log_text(tostring(direction or 'in')),
        count + 1,
        limit,
        accessxi.escape_probe_log_text(live_name),
        id,
        #data,
        has_ixff and 'yes' or 'no',
        accessxi.escape_probe_log_text(parse_text),
        accessxi.escape_probe_log_text_wide(rows_preview),
        accessxi.escape_probe_log_text_wide(world_hits),
        accessxi.escape_probe_log_text(accessxi.packet_ascii_preview(data, 160)),
        accessxi.escape_probe_log_text(accessxi.packet_hex_limit(data, 192))));
    return true;
end

function accessxi.character_creation_world_record_scan_terms(anchor_name)
    local resource = accessxi.character_creation_world_name_resource();
    local terms = T{};
    local seen = {};
    local function add(label)
        label = accessxi.character_creation_world_packet_name(label or '');
        local world = accessxi.character_creation_world_dat_match(label);
        if (world == nil) then
            return;
        end
        local key = label:lower();
        if (seen[key] == true or #label < 3) then
            return;
        end
        seen[key] = true;
        terms:append(T{
            label = world.label,
            id = tonumber(world.row) or -1,
            bytes = world.label,
        });
    end

    add(anchor_name);
    if (terms:len() == 0 and type(resource) == 'table' and type(resource.labels) == 'table') then
        for _, entry in ipairs(resource.labels) do
            add(entry.label or '');
        end
    end
    return terms;
end

function accessxi.character_creation_world_scan_memory_for_record_list(reason, anchor_name, expected_count, force)
    if (accessxi.character_creation_world_packet_rows ~= nil
        and type(accessxi.character_creation_world_packet_rows) == 'table'
        and accessxi.character_creation_world_packet_rows:len() > 0
        and force ~= true) then
        return true, 'cached';
    end

    local now = tick();
    expected_count = tonumber(expected_count) or 0;
    if (expected_count < 0 or expected_count > 64) then
        expected_count = 0;
    end
    local scan_key = ('%s:%d'):fmt(tostring(anchor_name or ''):lower(), expected_count);
    if (force ~= true and scan_key ~= '' and scan_key == tostring(accessxi.character_creation_world_record_scan_done_key or '')) then
        return false, 'record-scan-already-missing';
    end
    if (force ~= true and now < (tonumber(accessxi.character_creation_world_record_scan_next) or 0)) then
        return false, 'record-scan-rate-limited';
    end
    accessxi.character_creation_world_record_scan_next = now + 30000;

    local terms = accessxi.character_creation_world_record_scan_terms(anchor_name);
    if (terms:len() == 0) then
        return false, 'record-scan-no-terms';
    end

    local started = now;
    local max_ms = 950;
    local max_bytes = 112 * 1024 * 1024;
    local chunk_size = 0x20000;
    local overlap = 0x80;
    local max_hits = 48;
    local process = kernel32.GetCurrentProcess();
    local mbi = ffi.new('MEMORY_BASIC_INFORMATION[1]');
    local mbi_size = ffi.sizeof('MEMORY_BASIC_INFORMATION');
    local buffer = ffi.new('char[?]', chunk_size);
    local bytes_read = ffi.new('SIZE_T[1]');
    local addr = 0x01000000;
    local scanned = 0;
    local regions = 0;
    local readable = 0;
    local hits = 0;
    local timed_out = false;
    local best = '';
    local seen_hits = {};

    while (addr < 0x7FFF0000 and scanned < max_bytes and hits < max_hits) do
        if ((tick() - started) > max_ms) then
            timed_out = true;
            break;
        end

        local ok, result = pcall(function ()
            return kernel32.VirtualQuery(ffi.cast('const void*', addr), mbi, mbi_size);
        end);
        local queried = ok and tonumber(result) or 0;
        if (queried == 0) then
            addr = addr + 0x10000;
        else
            local base = tonumber(ffi.cast('uintptr_t', mbi[0].BaseAddress)) or addr;
            local size = tonumber(mbi[0].RegionSize) or 0;
            local state = tonumber(mbi[0].State) or 0;
            local protect = tonumber(mbi[0].Protect) or 0;
            local next_addr = base + math.max(size, 0x1000);
            regions = regions + 1;

            if (size > 0 and state == 0x1000 and accessxi.memory_page_search_scan_allowed(base, protect)) then
                readable = readable + 1;
                local region_offset = 0;
                local carry = '';
                while (region_offset < size and scanned < max_bytes and hits < max_hits) do
                    if ((tick() - started) > max_ms) then
                        timed_out = true;
                        break;
                    end

                    local want = math.min(chunk_size, size - region_offset, max_bytes - scanned);
                    if (want <= 0) then
                        break;
                    end
                    local chunk_addr = base + region_offset;
                    bytes_read[0] = 0;
                    local read_ok = kernel32.ReadProcessMemory(process, ffi.cast('const void*', chunk_addr), buffer, want, bytes_read) ~= 0;
                    local got = tonumber(bytes_read[0]) or 0;
                    if (read_ok and got > 0) then
                        local blob = carry .. ffi.string(buffer, got);
                        scanned = scanned + got;
                        for _, term in ipairs(terms) do
                            local start_at = 1;
                            while (hits < max_hits) do
                                local pos = blob:find(term.bytes, start_at, true);
                                if (pos == nil) then
                                    break;
                                end
                                local absolute = chunk_addr + pos - #carry - 1;
                                local record_ptr = absolute - 4;
                                local hit_key = ('%08X'):fmt(record_ptr);
                                if (seen_hits[hit_key] ~= true) then
                                    seen_hits[hit_key] = true;
                                    hits = hits + 1;
                                    local record = accessxi.character_creation_world_record_from_memory(record_ptr, 'memory-record-hit');
                                    if (record ~= nil) then
                                        local rows, seq_reason, seq_base = accessxi.character_creation_world_record_sequence_from_hit(record_ptr, 'memory-record-hit');
                                        local row_count = rows ~= nil and rows:len() or 0;
                                        if (best == '') then
                                            best = ('hit=0x%08X label=%s seq=%s count=%d expected=%d around="%s"'):fmt(
                                                record_ptr,
                                                tostring(record.label or ''),
                                                tostring(seq_reason or ''),
                                                row_count,
                                                expected_count,
                                                accessxi.format_probe_hex_bytes(record_ptr - 0x20, 0, 0x80));
                                        end
                                    end
                                end
                                start_at = pos + 1;
                            end
                        end
                        carry = blob:sub(math.max(1, #blob - overlap + 1));
                    else
                        scanned = scanned + want;
                    end

                    if (want <= overlap) then
                        region_offset = region_offset + want;
                    else
                        region_offset = region_offset + want - overlap;
                    end
                end
            end

            if (next_addr <= addr) then
                addr = addr + 0x1000;
            else
                addr = next_addr;
            end
        end
    end

    if (scan_key ~= '') then
        accessxi.character_creation_world_record_scan_done_key = scan_key;
    end
    log_state(('state character-creation world-list-record-scan result=missing reason="%s" anchor="%s" expected=%d terms=%d regions=%d readable=%d scanned=%d hits=%d timeout=%s best="%s" elapsed=%d'):fmt(
        accessxi.escape_probe_log_text(tostring(reason or '')),
        accessxi.escape_probe_log_text(tostring(anchor_name or '')),
        expected_count,
        terms:len(),
        regions,
        readable,
        scanned,
        hits,
        tostring(timed_out),
        accessxi.escape_probe_log_text_wide(best),
        tick() - started));
    return false, timed_out and 'record-scan-timeout' or 'record-scan-missing';
end

function accessxi.character_creation_world_scan_memory_for_packet_list(reason, force)
    if (accessxi.character_creation_world_packet_rows ~= nil
        and type(accessxi.character_creation_world_packet_rows) == 'table'
        and accessxi.character_creation_world_packet_rows:len() > 0
        and force ~= true) then
        return true, 'cached';
    end

    local now = tick();
    if (force ~= true and now < (tonumber(accessxi.character_creation_world_packet_scan_next) or 0)) then
        return false, 'scan-rate-limited';
    end
    accessxi.character_creation_world_packet_scan_next = now + 30000;

    local started = now;
    local max_ms = 850;
    local max_bytes = 96 * 1024 * 1024;
    local chunk_size = 0x20000;
    local overlap = 0x80;
    local max_hits = 80;
    local process = kernel32.GetCurrentProcess();
    local mbi = ffi.new('MEMORY_BASIC_INFORMATION[1]');
    local mbi_size = ffi.sizeof('MEMORY_BASIC_INFORMATION');
    local buffer = ffi.new('char[?]', chunk_size);
    local bytes_read = ffi.new('SIZE_T[1]');
    local addr = 0x01000000;
    local scanned = 0;
    local regions = 0;
    local readable = 0;
    local hits = 0;
    local timed_out = false;
    local reject = '';

    while (addr < 0x7FFF0000 and scanned < max_bytes and hits < max_hits) do
        if ((tick() - started) > max_ms) then
            timed_out = true;
            break;
        end

        local ok, result = pcall(function ()
            return kernel32.VirtualQuery(ffi.cast('const void*', addr), mbi, mbi_size);
        end);
        local queried = ok and tonumber(result) or 0;
        if (queried == 0) then
            addr = addr + 0x10000;
        else
            local base = tonumber(ffi.cast('uintptr_t', mbi[0].BaseAddress)) or addr;
            local size = tonumber(mbi[0].RegionSize) or 0;
            local state = tonumber(mbi[0].State) or 0;
            local protect = tonumber(mbi[0].Protect) or 0;
            local next_addr = base + math.max(size, 0x1000);
            regions = regions + 1;

            if (size > 0 and state == 0x1000 and accessxi.memory_page_search_scan_allowed(base, protect)) then
                readable = readable + 1;
                local region_offset = 0;
                local carry = '';
                while (region_offset < size and scanned < max_bytes and hits < max_hits) do
                    if ((tick() - started) > max_ms) then
                        timed_out = true;
                        break;
                    end

                    local want = math.min(chunk_size, size - region_offset, max_bytes - scanned);
                    if (want <= 0) then
                        break;
                    end
                    local chunk_addr = base + region_offset;
                    bytes_read[0] = 0;
                    local read_ok = kernel32.ReadProcessMemory(process, ffi.cast('const void*', chunk_addr), buffer, want, bytes_read) ~= 0;
                    local got = tonumber(bytes_read[0]) or 0;
                    if (read_ok and got > 0) then
                        local blob = carry .. ffi.string(buffer, got);
                        scanned = scanned + got;
                        local start_at = 1;
                        while (hits < max_hits) do
                            local pos = blob:find('IXFF', start_at, true);
                            if (pos == nil) then
                                break;
                            end
                            hits = hits + 1;
                            local absolute = chunk_addr + pos - #carry - 1;
                            local packet_base = absolute - 4;
                            local rows, parse_reason = accessxi.character_creation_world_packet_rows_at(packet_base, 'memory-ixff');
                            local row_count = rows ~= nil and rows:len() or 0;
                            if (rows ~= nil) then
                                reject = ('memory-ixff-detached:%d'):fmt(row_count);
                            else
                                reject = tostring(parse_reason or '');
                            end
                            start_at = pos + 1;
                        end
                        carry = blob:sub(math.max(1, #blob - overlap + 1));
                    else
                        scanned = scanned + want;
                    end

                    if (want <= overlap) then
                        region_offset = region_offset + want;
                    else
                        region_offset = region_offset + want - overlap;
                    end
                end
            end

            if (next_addr <= addr) then
                addr = addr + 0x1000;
            else
                addr = next_addr;
            end
        end
    end

    log_state(('state character-creation world-list-scan result=missing reason="%s" regions=%d readable=%d scanned=%d hits=%d timeout=%s reject="%s" elapsed=%d'):fmt(
        accessxi.escape_probe_log_text(tostring(reason or '')),
        regions,
        readable,
        scanned,
        hits,
        tostring(timed_out),
        accessxi.escape_probe_log_text(reject),
        tick() - started));
    return false, timed_out and 'scan-timeout' or 'scan-missing';
end

function accessxi.character_creation_world_packet_label(selected, expected_count)
    selected = tonumber(selected) or 0;
    expected_count = tonumber(expected_count) or 0;
    if (selected <= 0 or selected > 64) then
        return '', 'packet-selected-invalid';
    end

    local anchor_name = '';
    local live_count = 0;
    local obj = get_current_menu_object_ptr();
    local child0c = accessxi.is_probe_pointer(obj) and (read_u32(obj + 0x0C) or 0) or 0;
    if (accessxi.is_probe_pointer(child0c)) then
        anchor_name = accessxi.character_creation_world_packet_name(read_probe_string(child0c + 0x60, 16));
        live_count = read_u32(child0c + 0x18) or 0;
    end
    if (live_count <= 0 or live_count > 64) then
        live_count = expected_count;
    end

    local rows = type(accessxi.character_creation_world_packet_rows) == 'table' and accessxi.character_creation_world_packet_rows or T{};
    local source = tostring(accessxi.character_creation_world_packet_source or '');
    if ((source:eq('memory-records', true) or source:eq('memory-ixff', true)) and rows:len() > 0) then
        local reject_key = ('%s:%d'):fmt(source, rows:len());
        if (reject_key ~= tostring(accessxi.character_creation_world_packet_reject_log_key or '')) then
            accessxi.character_creation_world_packet_reject_log_key = reject_key;
            log_state(('state character-creation world-list-cache-reject source="%s" count=%d reason="detached-memory-source"'):fmt(
                accessxi.escape_probe_log_text(source),
                rows:len()));
        end
        accessxi.character_creation_world_packet_rows = nil;
        accessxi.character_creation_world_packet_source = '';
        accessxi.character_creation_world_packet_base = 0;
        accessxi.character_creation_world_packet_tick = 0;
    end

    rows = type(accessxi.character_creation_world_packet_rows) == 'table' and accessxi.character_creation_world_packet_rows or T{};
    source = tostring(accessxi.character_creation_world_packet_source or '');
    if ((source:eq('memory-records', true) or source:eq('memory-ixff', true)) and rows:len() > 0) then
        local reject_key = ('%s:%d'):fmt(source, rows:len());
        if (reject_key ~= tostring(accessxi.character_creation_world_packet_reject_log_key or '')) then
            accessxi.character_creation_world_packet_reject_log_key = reject_key;
            log_state(('state character-creation world-list-cache-reject source="%s" count=%d reason="detached-memory-source"'):fmt(
                accessxi.escape_probe_log_text(source),
                rows:len()));
        end
        accessxi.character_creation_world_packet_rows = nil;
        accessxi.character_creation_world_packet_source = '';
        accessxi.character_creation_world_packet_base = 0;
        accessxi.character_creation_world_packet_tick = 0;
        rows = T{};
    end
    local count = rows:len();
    if (count <= 0) then
        return '', 'packet-cache-empty';
    end
    if (selected > count) then
        return '', ('packet-selected-out-of-range-%d/%d'):fmt(selected, count);
    end

    local row = rows[selected];
    if (type(row) ~= 'table') then
        return '', 'packet-row-missing';
    end
    local label = accessxi.character_creation_world_packet_name(row.label or '');
    local world = accessxi.character_creation_world_dat_match(label);
    if (world == nil or (tonumber(world.row) or -2) ~= (tonumber(row.id) or -1)) then
        return '', 'packet-row-not-dat';
    end

    return world.label, ('world-list-packet:%s id=%d %d/%d stateCount=%d'):fmt(
        tostring(accessxi.character_creation_world_packet_source or ''),
        tonumber(row.id) or -1,
        selected,
        count,
        expected_count);
end

function accessxi.character_creation_world_runtime_rows(expected_count)
    expected_count = tonumber(expected_count) or 0;
    local global_addr = accessxi.ffximain_rebased_va(0x106364FC);
    local world_obj = accessxi.ffximain_global_ptr(0x106364FC);
    if (not accessxi.is_probe_pointer(world_obj)) then
        return T{}, 0, ('runtime-global-empty addr=0x%08X'):fmt(tonumber(global_addr) or 0);
    end

    local expected_vtable = accessxi.ffximain_rebased_va(0x1033C9B0);
    local vtable = read_u32(world_obj) or 0;
    if (expected_vtable ~= 0 and vtable ~= expected_vtable) then
        return T{}, world_obj, ('runtime-vtable-mismatch got=0x%08X expected=0x%08X'):fmt(vtable, expected_vtable);
    end

    local open_flag = read_u8(world_obj + 0x52) or 0;
    local object_count = read_u16(world_obj + 0x54) or 0;
    if (object_count <= 0 or object_count > 32) then
        return T{}, world_obj, ('runtime-count-invalid-%d flag52=%d'):fmt(object_count, open_flag);
    end

    local rows = T{};
    local preview = T{};
    local seen_ids = {};
    local seen_labels = {};
    for index = 1, object_count do
        local rec = world_obj + 0x5C + ((index - 1) * 0xD4);
        local id = read_i32(rec) or -1;
        local label = accessxi.character_creation_world_packet_name(read_probe_string(rec + 0x04, 200));
        local world = accessxi.character_creation_world_dat_match(label);
        if (id <= 0 or world == nil) then
            return T{}, world_obj, ('runtime-row-invalid row=%d id=%d label=%s'):fmt(
                index,
                id,
                accessxi.escape_probe_log_text(label));
        end
        if ((tonumber(world.row) or -2) ~= id) then
            return T{}, world_obj, ('runtime-id-mismatch row=%d id=%d dat=%d label=%s'):fmt(
                index,
                id,
                tonumber(world.row) or -1,
                accessxi.escape_probe_log_text(world.label));
        end

        local label_key = tostring(world.label or ''):lower();
        if (seen_ids[id] == true or seen_labels[label_key] == true) then
            return T{}, world_obj, ('runtime-duplicate row=%d id=%d label=%s'):fmt(
                index,
                id,
                accessxi.escape_probe_log_text(world.label));
        end
        seen_ids[id] = true;
        seen_labels[label_key] = true;

        accessxi.character_creation_world_add_row_candidate(
            rows,
            index,
            world.label,
            ('runtime-worldsel:id=%d'):fmt(id),
            rec,
            ('obj+%04X'):fmt(0x5C + ((index - 1) * 0xD4)));
        if (preview:len() < 24) then
            preview:append(('%d:%d:%s'):fmt(index, id, world.label));
        end
    end

    local preview_text = preview:concat('|');
    local key = ('%08X:%d:%d:%d:%s'):fmt(world_obj, object_count, expected_count, open_flag, preview_text);
    if (key ~= tostring(accessxi.character_creation_world_runtime_probe_key or '')) then
        accessxi.character_creation_world_runtime_probe_key = key;
        log_state(('state character-creation world-runtime ptr=0x%08X global=0x%08X count=%d visible=%d flag52=%d rows="%s"'):fmt(
            world_obj,
            tonumber(global_addr) or 0,
            object_count,
            expected_count,
            open_flag,
            accessxi.escape_probe_log_text_wide(preview_text)));
    end

    return rows, world_obj, ('runtime-worldsel count=%d visible=%d flag52=%d'):fmt(object_count, expected_count, open_flag);
end

function accessxi.character_creation_world_runtime_label(selected, expected_count)
    selected = tonumber(selected) or 0;
    expected_count = tonumber(expected_count) or 0;
    if (selected <= 0 or selected > 64) then
        return '', 'runtime-selected-invalid', T{}, 0;
    end

    local rows, world_obj, mode = accessxi.character_creation_world_runtime_rows(expected_count);
    local label, row_mode = accessxi.character_creation_world_label_from_rows(rows, selected, expected_count);
    if (label == '') then
        return '', ('%s %s'):fmt(tostring(mode or ''), tostring(row_mode or '')), rows, world_obj;
    end
    return label, ('worldsel-runtime:%s %s'):fmt(tostring(mode or ''), tostring(row_mode or '')), rows, world_obj;
end

function accessxi.character_creation_format_template_label(template, value)
    template = accessxi.plain_native_menu_label(tostring(template or ''));
    value = accessxi.character_creation_template_value(value);
    if (template == '' or value == '') then
        return '';
    end

    local label = template:gsub('%%c', value);
    label = label:gsub('%%s', value);
    label = label:gsub('%%d', value);
    return accessxi.plain_native_menu_label(label);
end

function accessxi.character_creation_menu_entry(kind, selected)
    kind = tostring(kind or '');
    selected = tonumber(selected) or -1;
    local resources = accessxi.native_menus_data.character_creation_menu_resources or T{};
    local group = resources[kind];
    if (type(group) ~= 'table') then
        return nil;
    end

    local spec = (group.rows or T{})[selected];
    if (type(spec) ~= 'table') then
        local label_template_row = tonumber(group.label_template_row) or -1;
        local template_count = tonumber(group.count) or 0;
        if (label_template_row < 0 or template_count <= 0 or selected < 0 or selected >= template_count) then
            return nil;
        end

        local dat_path = tostring(group.label_template_dat or '');
        local template = accessxi.dat_index_row_text(dat_path, label_template_row, 'label');
        local value = selected + (tonumber(group.first_label_value) or 1);
        local label = accessxi.character_creation_format_template_label(template, value);
        if (label == '') then
            return nil;
        end

        return T{
            title = tostring(group.title or 'Character creation'),
            label = label,
            source = ('template=%s:%d value=%d'):fmt(dat_path, label_template_row, value),
        };
    end

    if ((tonumber(group.label_template_row) or -1) >= 0 and spec.value_dat ~= nil and spec.value_row ~= nil) then
        local dat_path = tostring(group.label_template_dat or '');
        local template_row = tonumber(group.label_template_row) or -1;
        local template = accessxi.dat_index_row_text(dat_path, template_row, 'label');
        local value_dat = tostring(spec.value_dat or '');
        local value_row = tonumber(spec.value_row) or -1;
        local value = accessxi.character_creation_dat_value_text(value_dat, value_row);
        local label = accessxi.character_creation_format_template_label(template, value);
        if (label == '') then
            return nil;
        end

        return T{
            title = tostring(group.title or 'Character creation'),
            label = label,
            source = ('template=%s:%d value=%s:%d'):fmt(dat_path, template_row, value_dat, value_row),
        };
    end

    local dat_path = tostring(spec.label_dat or group.label_dat or '');
    local label_row = tonumber(spec.label_row) or -1;
    local label_kind = tostring(spec.label_kind or group.label_kind or 'label');
    local label = accessxi.dat_index_row_text(dat_path, label_row, label_kind);
    if (label_kind == 'prompt') then
        label = accessxi.plain_native_menu_prompt(label or '');
    else
        label = accessxi.plain_native_menu_label(label or '');
    end
    if (label == '') then
        return nil;
    end

    return T{
        title = tostring(group.title or 'Character creation'),
        label = label,
        source = ('%s=%s:%d'):fmt(label_kind, dat_path, label_row),
    };
end

function accessxi.character_creation_nation_menu_entry(selected)
    selected = tonumber(selected) or -1;
    local resources = accessxi.native_menus_data.character_creation_menu_resources or T{};
    local group = resources.nation;
    if (type(group) ~= 'table') then
        return nil;
    end

    local spec = (group.rows or T{})[selected];
    if (type(spec) ~= 'table') then
        return nil;
    end

    local title_dat = tostring(spec.title_dat or group.title_dat or group.prompt_dat or '');
    local title_row = tonumber(spec.title_row) or -1;
    local body_dat = tostring(spec.body_dat or group.body_dat or group.prompt_dat or '');
    local body_row = tonumber(spec.body_row) or -1;
    local prompt_dat = tostring(group.prompt_dat or '');
    local prompt_row = tonumber(group.prompt_row) or -1;
    local heading = accessxi.dat_index_row_text(title_dat, title_row, 'prompt');
    local body = accessxi.character_creation_dat_long_text(body_dat, body_row);
    local prompt = accessxi.dat_index_row_text(prompt_dat, prompt_row, 'prompt');
    if (heading == '' and body == '') then
        return nil;
    end

    return T{
        title = tostring(group.title or 'Starting country'),
        heading = heading,
        body = body,
        prompt = prompt,
        source = ('title=%s:%d body=%s:%d prompt=%s:%d'):fmt(
            title_dat,
            title_row,
            body_dat,
            body_row,
            prompt_dat,
            prompt_row),
    };
end

function accessxi.character_creation_clean_name(name)
    name = accessxi.survival_guide_text(name or '');
    name = name:gsub('^"+', ''):gsub('"+$', ''):trim();
    if (#name < 3 or #name > 15) then
        return '';
    end
    if (name:match('^[A-Za-z][A-Za-z]+$') == nil) then
        return '';
    end
    return name;
end

function accessxi.remember_character_creation_name_from_input(menu_name, name, source)
    if (accessxi.character_creation_menu_kind(menu_name) ~= 'name') then
        return false;
    end

    local clean_name = accessxi.character_creation_clean_name(name);
    if (clean_name == '') then
        return false;
    end

    source = tostring(source or 'chat-input');
    if (clean_name ~= tostring(accessxi.character_creation_candidate_name or '')
        or source ~= tostring(accessxi.character_creation_candidate_name_source or '')) then
        log_state(('state character-creation name-cache name="%s" source="%s"'):fmt(
            accessxi.escape_probe_log_text(clean_name),
            accessxi.escape_probe_log_text(source)));
    end
    accessxi.character_creation_candidate_name = clean_name;
    accessxi.character_creation_candidate_name_tick = tick();
    accessxi.character_creation_candidate_name_source = source;
    return true;
end

function accessxi.character_creation_confirmation_native_name(obj)
    obj = tonumber(obj) or 0;
    if (obj == 0 or not accessxi.is_probe_pointer(obj)) then
        return '', '';
    end

    local now = tick();
    local cache_key = ('0x%08X'):fmt(obj);
    if (cache_key == tostring(accessxi.character_creation_confirmation_name_scan_key or '')
        and (now - (tonumber(accessxi.character_creation_confirmation_name_scan_tick) or 0)) < 1000) then
        return tostring(accessxi.character_creation_confirmation_name_scan_value or ''),
            tostring(accessxi.character_creation_confirmation_name_scan_source or '');
    end

    local function scan_buffer(ptr, source)
        ptr = tonumber(ptr) or 0;
        if (ptr == 0 or not accessxi.is_probe_pointer(ptr)) then
            return '', '';
        end

        local text = accessxi.character_creation_ok_dialog_ascii_buffer(ptr, 220);
        local name = text:match('Register%s+"([A-Za-z][A-Za-z]+)"');
        name = accessxi.character_creation_clean_name(name);
        if (name ~= '') then
            return name, source;
        end
        return '', '';
    end

    local name, source = '', '';
    local seen = {};
    local function scan_range(base, label, max_offset)
        base = tonumber(base) or 0;
        if (base == 0 or not accessxi.is_probe_pointer(base)) then
            return '', '';
        end
        if (seen[base] ~= nil) then
            return '', '';
        end
        seen[base] = true;
        for offset = 0, tonumber(max_offset) or 0x80, 4 do
            local candidate_name, candidate_source = scan_buffer(base + offset, ('%s+%03X'):fmt(label, offset));
            if (candidate_name ~= '') then
                return candidate_name, candidate_source;
            end
        end
        return '', '';
    end

    name, source = scan_range(obj, 'obj', 0x120);
    if (name == '') then
        for _, field in ipairs(T{ 0x04, 0x08, 0x0C, 0x10, 0x14, 0x18, 0x1C, 0x20, 0x24, 0x28, 0x2C, 0x30, 0x34, 0x38, 0x3C, 0x40, 0x44, 0x48, 0x4C, 0x50, 0x60, 0x70, 0x80, 0x90, 0xA0, 0xB0, 0xC0, 0xD0, 0xE0, 0xF0 }) do
            local base = read_u32(obj + field) or 0;
            name, source = scan_range(base, ('obj+%02X'):fmt(field), 0x100);
            if (name ~= '') then
                break;
            end
        end
    end

    accessxi.character_creation_confirmation_name_scan_key = cache_key;
    accessxi.character_creation_confirmation_name_scan_value = name;
    accessxi.character_creation_confirmation_name_scan_source = source;
    accessxi.character_creation_confirmation_name_scan_tick = now;
    return name, source;
end

function accessxi.character_creation_confirmation_choice(selected, spec)
    selected = tonumber(selected) or -1;
    spec = type(spec) == 'table' and spec or T{};
    local dat_path = '';
    local row = -1;
    if (selected == 0) then
        dat_path = tostring(spec.yes_dat or '');
        row = tonumber(spec.yes_row) or -1;
    elseif (selected == 1) then
        dat_path = tostring(spec.no_dat or '');
        row = tonumber(spec.no_row) or -1;
    else
        return '', '';
    end

    local label = accessxi.dat_index_row_text(dat_path, row, 'label');
    label = accessxi.plain_native_menu_label(label or '');
    if (label == '') then
        return '', '';
    end
    return label, ('%s:%d'):fmt(dat_path, row);
end

function accessxi.character_creation_confirmation_prompt_text(text)
    text = accessxi.survival_guide_text(text or '');
    if (text == '' or #text > 260) then
        return '';
    end
    if (text:find('%s', 1, true) == nil) then
        return '';
    end
    if (text:find('menu    ', 1, true) ~= nil or text:find('anc     ', 1, true) ~= nil) then
        return '';
    end
    return text;
end

function accessxi.character_creation_confirmation_dat_template_text(dat_path, row)
    dat_path = tostring(dat_path or '');
    row = tonumber(row) or -1;
    if (dat_path == '' or row < 0) then
        return '';
    end

    accessxi.character_creation_confirmation_dat_template_cache = accessxi.character_creation_confirmation_dat_template_cache or {};
    local key = ('%s:%d'):fmt(dat_path, row);
    local cached = accessxi.character_creation_confirmation_dat_template_cache[key];
    if (cached ~= nil) then
        return cached;
    end

    local text = '';
    local path = accessxi.dat_index_path();
    local f = io.open(path, 'rb');
    if (f ~= nil) then
        for line in f:lines() do
            local _, _, line_dat_path, index, value = line:match('^(%d+)\t([^\t]+)\t([^\t]+)\t(%d+)\t(.*)$');
            if (line_dat_path == dat_path and (tonumber(index) or -1) == row) then
                text = accessxi.character_creation_confirmation_prompt_text(tostring(value or ''):gsub('\r', ''));
                break;
            end
        end
        f:close();
    end

    accessxi.character_creation_confirmation_dat_template_cache[key] = text;
    return text;
end

function accessxi.character_creation_confirmation_selected_from_obj(obj, fallback)
    obj = tonumber(obj) or 0;
    fallback = tonumber(fallback) or -1;
    if (obj ~= 0 and accessxi.is_probe_pointer(obj)) then
        local raw = tonumber(read_i32(obj + 0x4C)) or -1;
        if (raw == 1) then
            return 0, raw, 'native-one-4c-confirm';
        elseif (raw == 2) then
            return 1, raw, 'native-one-4c-confirm';
        end
    end

    if (fallback == 0 or fallback == 1) then
        return fallback, -1, 'IwYesNoMenu.m_select';
    end
    return -1, -1, '';
end

function accessxi.character_creation_confirmation_probe(menu_name, obj, selected, raw_selected, selected_source)
    menu_name = tostring(menu_name or '');
    if (not menu_name:eq('menu    ptc6yesn', true)) then
        return;
    end

    obj = tonumber(obj) or 0;
    selected = tonumber(selected) or -1;
    raw_selected = tonumber(raw_selected) or -1;
    selected_source = tostring(selected_source or '');
    local yesno_root = tonumber(accessxi.ptrs.yesno) or 0;
    local yesno_a = yesno_root ~= 0 and (read_u32(yesno_root) or 0) or 0;
    local yesno_obj = accessxi.is_probe_pointer(yesno_a) and (read_u32(yesno_a) or 0) or 0;
    local yesno_select = selected;
    if (accessxi.is_probe_pointer(yesno_obj)) then
        yesno_select = tonumber(read_i32(yesno_obj + 0x10)) or selected;
    end
    local field4c = accessxi.is_probe_pointer(obj) and (tonumber(read_i32(obj + 0x4C)) or -1) or -1;

    local key = ('%s:%d:%d:%s:%d:0x%08X:0x%08X:%d'):fmt(
        menu_name,
        selected,
        raw_selected,
        selected_source,
        yesno_select,
        obj,
        yesno_obj,
        field4c);
    if (key == tostring(accessxi.character_creation_confirmation_probe_last_key or '')) then
        return;
    end
    accessxi.character_creation_confirmation_probe_last_key = key;
    accessxi.character_creation_confirmation_probe_last_tick = tick();

    log_state(('state character-creation confirm-probe menu="%s" obj=0x%08X yesno=0x%08X selected=%d rawSelected=%d selectedSource="%s" yesnoSelect=%d field4c=%d'):fmt(
        menu_name,
        obj,
        yesno_obj,
        selected,
        raw_selected,
        accessxi.escape_probe_log_text(selected_source),
        yesno_select,
        field4c));
end

function accessxi.character_creation_confirmation_speech(menu_name, obj)
    menu_name = tostring(menu_name or '');
    obj = tonumber(obj) or 0;
    if (not menu_name:eq('menu    ptc6yesn', true)) then
        return nil;
    end

    local menu = get_menu_obj(accessxi.ptrs.yesno, 'IwYesNoMenu');
    local fallback_selected = menu ~= nil and tonumber(menu.m_select) or -1;
    local selected, raw_selected, selected_source = accessxi.character_creation_confirmation_selected_from_obj(obj, fallback_selected);
    accessxi.character_creation_confirmation_probe(menu_name, obj, selected, raw_selected, selected_source);
    local spec = accessxi.native_menus_data.character_creation_confirmation_resource or T{};
    local choice, choice_source = accessxi.character_creation_confirmation_choice(selected, spec);
    if (choice == '') then
        log_state(('state character-creation confirm quiet menu="%s" select=%d rawSelected=%d selectedSource="%s" reason="missing-choice-dat"'):fmt(
            menu_name,
            selected,
            raw_selected,
            accessxi.escape_probe_log_text(selected_source)));
        return nil;
    end

    local register_template = accessxi.character_creation_confirmation_dat_template_text(tostring(spec.register_dat or ''), tonumber(spec.register_row) or -1);
    local begin_text = accessxi.dat_index_row_text(tostring(spec.begin_dat or ''), tonumber(spec.begin_row) or -1, 'prompt');
    begin_text = accessxi.plain_native_menu_prompt(begin_text or '');

    local name, name_source = accessxi.character_creation_confirmation_native_name(obj);
    if (name == '') then
        local cached_name = accessxi.character_creation_clean_name(accessxi.character_creation_candidate_name);
        local cached_age = tick() - (tonumber(accessxi.character_creation_candidate_name_tick) or 0);
        if (cached_name ~= '' and cached_age >= 0 and cached_age < 1200000) then
            name = cached_name;
            name_source = tostring(accessxi.character_creation_candidate_name_source or 'chat-input-cache');
        end
    end

    if (register_template:find('%s', 1, true) ~= nil and name == '') then
        log_state(('state character-creation confirm quiet menu="%s" select=%d rawSelected=%d selectedSource="%s" reason="missing-name" choice="%s" choiceSource="%s"'):fmt(
            menu_name,
            selected,
            raw_selected,
            accessxi.escape_probe_log_text(selected_source),
            accessxi.escape_probe_log_text(choice),
            accessxi.escape_probe_log_text(choice_source)));
        return nil;
    end

    local parts = T{};
    if (name ~= '' and register_template ~= '') then
        local register_text = register_template:gsub('%%s', name);
        parts:append(register_text);
    end
    if (begin_text ~= '') then
        parts:append(begin_text);
    end
    local prompt = accessxi.survival_guide_text(parts:concat(' '));
    if (prompt == '') then
        log_state(('state character-creation confirm quiet menu="%s" select=%d rawSelected=%d selectedSource="%s" reason="missing-prompt-dat" choice="%s" choiceSource="%s"'):fmt(
            menu_name,
            selected,
            raw_selected,
            accessxi.escape_probe_log_text(selected_source),
            accessxi.escape_probe_log_text(choice),
            accessxi.escape_probe_log_text(choice_source)));
        return nil;
    end

    accessxi.current_speech_key = ('character-creation-confirm:%d:%d:%s:%s:%s:%s'):fmt(
        selected,
        raw_selected,
        tostring(selected_source),
        tostring(prompt),
        tostring(choice),
        tostring(name_source or ''));
    log_state(('state character-creation confirm menu="%s" select=%d rawSelected=%d selectedSource="%s" choice="%s" prompt="%s" name="%s" nameSource="%s" promptSource="%s:%d;%s:%d" choiceSource="%s"'):fmt(
        menu_name,
        selected,
        raw_selected,
        accessxi.escape_probe_log_text(selected_source),
        accessxi.escape_probe_log_text(choice),
        accessxi.escape_probe_log_text(prompt),
        accessxi.escape_probe_log_text(name),
        accessxi.escape_probe_log_text(name_source or ''),
        tostring(spec.register_dat or ''),
        tonumber(spec.register_row) or -1,
        tostring(spec.begin_dat or ''),
        tonumber(spec.begin_row) or -1,
        accessxi.escape_probe_log_text(choice_source)));

    return ('%s %s'):fmt(
        accessxi.sentence_fragment(prompt),
        accessxi.sentence_fragment(choice));
end

function accessxi.character_creation_text_input_prompt_speech(menu_name, obj)
    menu_name = tostring(menu_name or '');
    obj = tonumber(obj) or 0;
    if (not accessxi.is_character_creation_text_input_menu_name(menu_name)) then
        return nil, '';
    end

    local kind = accessxi.character_creation_menu_kind(menu_name);
    if (kind ~= 'name' and kind ~= 'worldpass') then
        return nil, '';
    end

    local entry = accessxi.character_creation_menu_entry(kind, 0);
    if (entry == nil or tostring(entry.label or '') == '') then
        log_state(('state character-creation text-input-open quiet menu="%s" kind="%s" obj=0x%08X reason="missing-resource-row"'):fmt(
            menu_name,
            kind,
            obj));
        return nil, '';
    end

    accessxi.character_creation_last_text_input_kind = kind;
    accessxi.character_creation_last_text_input_tick = tick();
    accessxi.character_creation_text_input_prompt_sequence = (tonumber(accessxi.character_creation_text_input_prompt_sequence) or 0) + 1;
    local key = ('character-creation:text-input-open:%s:%d:0x%08X:%s'):fmt(
        kind,
        tonumber(accessxi.character_creation_text_input_prompt_sequence) or 0,
        obj,
        tostring(entry.source or ''));
    log_state(('state character-creation text-input-open menu="%s" kind="%s" obj=0x%08X label="%s" source="%s"'):fmt(
        menu_name,
        kind,
        obj,
        accessxi.escape_probe_log_text(entry.label),
        accessxi.escape_probe_log_text(entry.source or '')));
    return accessxi.sentence_fragment(entry.label), key;
end

function accessxi.character_creation_name_prompt_speech(menu_name, obj)
    return accessxi.character_creation_text_input_prompt_speech(menu_name, obj);
end

function accessxi.character_creation_scan_error_code(ptr, label)
    ptr = tonumber(ptr) or 0;
    if (ptr == 0 or not accessxi.is_probe_pointer(ptr)) then
        return nil, '';
    end

    for offset = 0, 0x1FC, 4 do
        local value = read_i32(ptr + offset);
        if (value ~= nil and value >= 3000 and value <= 3999) then
            return value, ('%s+%03X'):fmt(tostring(label or 'ptr'), offset);
        end
    end
    return nil, '';
end

function accessxi.character_creation_ok_dialog_yesno_error_code()
    local ok, menu = pcall(function ()
        return get_menu_obj(accessxi.ptrs.yesno, 'IwYesNoMenu');
    end);
    if (not ok or menu == nil) then
        return nil, '';
    end

    local error_code = tonumber(menu.m_errcode) or 0;
    if (error_code >= 3000 and error_code <= 3999) then
        return error_code, 'IwYesNoMenu.m_errcode';
    end
    return nil, '';
end

function accessxi.character_creation_ok_dialog_ascii_buffer(ptr, length)
    ptr = tonumber(ptr) or 0;
    if (ptr == 0 or not accessxi.is_probe_pointer(ptr)) then
        return '';
    end

    length = tonumber(length) or 220;
    if (length < 1 or length > 512) then
        length = 220;
    end

    local chars = T{};
    for offset = 0, length - 1 do
        local byte = read_u8(ptr + offset);
        if (byte == nil or byte == 0) then
            break;
        end

        if (byte == 10 or byte == 13) then
            chars:append('. ');
        elseif (byte == 9 or byte == 32) then
            chars:append(' ');
        elseif (byte >= 32 and byte <= 126) then
            chars:append(string.char(byte));
        end
    end

    local text = chars:concat('');
    text = text:gsub('%.%s*%.+', '. ');
    text = text:gsub('%s+', ' '):trim();
    return text;
end

function accessxi.character_creation_ok_dialog_native_text(obj)
    obj = tonumber(obj) or 0;
    if (obj == 0 or not accessxi.is_probe_pointer(obj)) then
        return '', '';
    end

    for _, field in ipairs(T{ 0x0C }) do
        local base = read_u32(obj + field) or 0;
        if (accessxi.is_probe_pointer(base)) then
            for _, offset in ipairs(T{ 0x00, 0x04, 0x08, 0x0C, 0x10, 0x14, 0x18, 0x1C, 0x20, 0x24, 0x28, 0x2C, 0x30 }) do
                local text = accessxi.character_creation_ok_dialog_ascii_buffer(base + offset, 220);
                local has_marker = text:find('FFXI%-%d%d%d%d') ~= nil or text:find('POL%-%d%d%d%d') ~= nil;
                if (has_marker and text ~= '' and #text <= 260 and text:find('menu    ', 1, true) == nil) then
                    return text, ('obj+%02X+%03X'):fmt(field, offset);
                end
            end
        end
    end

    return '', '';
end

function accessxi.character_creation_ok_dialog_error_code(obj)
    obj = tonumber(obj) or 0;
    local code, source = accessxi.character_creation_scan_error_code(obj, 'obj');
    if (code ~= nil) then
        return code, source;
    end

    for _, offset in ipairs(T{ 0x04, 0x08, 0x0C }) do
        local ptr = accessxi.is_probe_pointer(obj) and (read_u32(obj + offset) or 0) or 0;
        code, source = accessxi.character_creation_scan_error_code(ptr, ('obj+%02X'):fmt(offset));
        if (code ~= nil) then
            return code, source;
        end
    end

    code, source = accessxi.character_creation_ok_dialog_yesno_error_code();
    if (code ~= nil) then
        return code, source;
    end
    return nil, '';
end

function accessxi.character_creation_ok_dialog_missing_error_probe(menu_name, obj, reason)
    menu_name = tostring(menu_name or '');
    obj = tonumber(obj) or 0;
    reason = tostring(reason or 'missing-error-code');
    if (obj == 0 or not menu_name:eq('menu    ok', true)) then
        return;
    end

    local last_kind = tostring(accessxi.character_creation_last_text_input_kind or '');
    local transition_from = tostring(accessxi.last_menu_transition_from or '');
    local key = ('%s:0x%08X:%s:%s:%s'):fmt(menu_name, obj, reason, last_kind, transition_from);
    if (key == tostring(accessxi.character_creation_ok_dialog_missing_probe_key or '')) then
        return;
    end
    accessxi.character_creation_ok_dialog_missing_probe_key = key;

    log_state(('state character-creation ok-dialog-probe menu="%s" obj=0x%08X reason="%s" lastTextInput="%s" transitionFrom="%s"'):fmt(
        menu_name,
        obj,
        accessxi.escape_probe_log_text(reason),
        accessxi.escape_probe_log_text(last_kind),
        accessxi.escape_probe_log_text(transition_from)));

    if (type(accessxi.dump_current_menu) == 'function') then
        accessxi.dump_current_menu('character-creation-ok-missing-error-code', true);
    end
end

function accessxi.character_creation_error_dialog_entry(error_code)
    error_code = tonumber(error_code) or 0;
    local resources = accessxi.native_menus_data.character_creation_error_dialog_resources or T{};
    for _, spec in pairs(resources) do
        if ((tonumber(spec.error_code) or -1) == error_code) then
            local error_template = accessxi.dat_index_row_text(spec.error_dat, spec.error_row, 'prompt');
            error_template = accessxi.plain_native_menu_prompt(error_template or '');
            local error_text = error_template:gsub('%%04d', ('%04d'):fmt(error_code)):gsub('%%d', tostring(error_code));
            error_text = accessxi.plain_native_menu_prompt(error_text or '');

            local message_kind = tostring(spec.message_kind or 'prompt');
            local message = accessxi.dat_index_row_text(spec.message_dat, spec.message_row, message_kind);
            if (message_kind == 'prompt') then
                message = accessxi.plain_native_menu_prompt(message or '');
            else
                message = accessxi.plain_native_menu_label(message or '');
            end

            if (message == '') then
                return nil;
            end

            return T{
                title = tostring(spec.title or 'Character creation'),
                error = error_text,
                message = message,
                source = ('code=%d error=%s:%d message=%s:%d'):fmt(
                    error_code,
                    tostring(spec.error_dat or ''),
                    tonumber(spec.error_row) or -1,
                    tostring(spec.message_dat or ''),
                    tonumber(spec.message_row) or -1),
            };
        end
    end
    return nil;
end

function accessxi.character_creation_ok_dialog_speech(menu_name, obj)
    menu_name = tostring(menu_name or '');
    obj = tonumber(obj) or 0;
    if (not menu_name:eq('menu    ok', true)) then
        return nil;
    end

    local native_text, native_source = accessxi.character_creation_ok_dialog_native_text(obj);
    if (native_text ~= '') then
        accessxi.current_speech_key = ('character-creation:ok-native-text:0x%08X:%s:%s'):fmt(
            obj,
            tostring(native_source or ''),
            tostring(native_text or ''));
        log_state(('state character-creation ok-dialog-native-text menu="%s" obj=0x%08X text="%s" source="%s"'):fmt(
            menu_name,
            obj,
            accessxi.escape_probe_log_text(native_text),
            accessxi.escape_probe_log_text(native_source or '')));
        return accessxi.sentence_fragment(native_text);
    end

    local error_code, code_source = accessxi.character_creation_ok_dialog_error_code(obj);
    if (error_code == nil) then
        log_state(('state character-creation ok-dialog quiet menu="%s" obj=0x%08X reason="missing-error-code"'):fmt(
            menu_name,
            obj));
        accessxi.character_creation_ok_dialog_missing_error_probe(menu_name, obj, 'missing-error-code');
        return nil;
    end

    local entry = accessxi.character_creation_error_dialog_entry(error_code);
    if (entry == nil) then
        log_state(('state character-creation ok-dialog quiet menu="%s" obj=0x%08X code=%d codeSource="%s" reason="unsupported-error-code"'):fmt(
            menu_name,
            obj,
            tonumber(error_code) or 0,
            accessxi.escape_probe_log_text(code_source or '')));
        return nil;
    end

    accessxi.current_speech_key = ('character-creation:ok-error:%d:0x%08X:%s'):fmt(
        tonumber(error_code) or 0,
        obj,
        tostring(entry.source or ''));
    log_state(('state character-creation ok-dialog menu="%s" obj=0x%08X code=%d codeSource="%s" message="%s" source="%s"'):fmt(
        menu_name,
        obj,
        tonumber(error_code) or 0,
        accessxi.escape_probe_log_text(code_source or ''),
        accessxi.escape_probe_log_text(entry.message or ''),
        accessxi.escape_probe_log_text(entry.source or '')));

    local pieces = T{};
    if (tostring(entry.title or '') ~= '') then
        pieces:append(accessxi.sentence_fragment(entry.title));
    end
    if (tostring(entry.error or '') ~= '') then
        pieces:append(accessxi.sentence_fragment(entry.error));
    end
    pieces:append(accessxi.sentence_fragment(entry.message));
    return pieces:concat(' ');
end

function accessxi.character_creation_world_add_row_candidate(rows, row, label, source, render, offsets)
    rows = type(rows) == 'table' and rows or T{};
    row = tonumber(row) or 0;
    label = accessxi.survival_guide_native_label_for_speech(label or '', 'plain');
    label = accessxi.plain_native_menu_label(label or '');
    local world = accessxi.character_creation_world_dat_match(label);
    if (row <= 0 or label == '' or world == nil) then
        return false;
    end

    if (rows[row] == nil) then
        rows[row] = T{};
    end
    rows[row]:append(T{
        source = source or '',
        render = tonumber(render) or 0,
        label = world.label,
        world_row = tonumber(world.row) or -1,
        world_source = tostring(world.source or ''),
        offsets = tostring(offsets or ''),
    });
    return true;
end

function accessxi.character_creation_world_merge_rows(dest, src)
    dest = type(dest) == 'table' and dest or T{};
    src = type(src) == 'table' and src or T{};
    for row, entries in pairs(src) do
        local row_number = tonumber(row) or 0;
        if (row_number > 0 and type(entries) == 'table') then
            for _, entry in ipairs(entries) do
                accessxi.character_creation_world_add_row_candidate(
                    dest,
                    row_number,
                    entry.label or entry.text or '',
                    entry.source or '',
                    entry.render or 0,
                    entry.offsets or (entry.offset ~= nil and ('+%03X'):fmt(tonumber(entry.offset) or 0) or ''));
            end
        end
    end
    return dest;
end

function accessxi.character_creation_world_sequential_rows_from_ptr(ptr, source, expected_count, max_rows)
    ptr = tonumber(ptr) or 0;
    expected_count = tonumber(expected_count) or 0;
    max_rows = math.min(math.max(tonumber(max_rows) or expected_count, 4), 32);
    if (not accessxi.is_probe_pointer(ptr) or accessxi.collect_probe_ffxi_utf16_entries == nil) then
        return T{}, 0;
    end

    local rows = T{};
    local matches = T{};
    local seen_offsets = {};
    local entries = accessxi.collect_probe_ffxi_utf16_entries(ptr, 0x900, 2, 160);
    for _, entry in ipairs(entries) do
        local offset = tonumber(entry.offset) or 0;
        local key = tostring(offset);
        if (seen_offsets[key] ~= true) then
            local label = accessxi.survival_guide_native_label_for_speech(entry.text or '', 'plain');
            label = accessxi.plain_native_menu_label(label or '');
            local world = accessxi.character_creation_world_dat_match(label);
            if (world ~= nil) then
                seen_offsets[key] = true;
                matches:append(T{
                    offset = offset,
                    label = world.label,
                    source = tostring(world.source or ''),
                });
            end
        end
    end

    local match_count = matches:len();
    local min_matches = expected_count > 0 and math.min(expected_count, 6) or 6;
    if (match_count < min_matches or match_count > max_rows) then
        return rows, match_count;
    end
    if (expected_count > 0 and match_count > expected_count) then
        return rows, match_count;
    end

    local seen_labels = {};
    for index, match in ipairs(matches) do
        local label_key = tostring(match.label or ''):lower();
        if (seen_labels[label_key] == true) then
            return T{}, match_count;
        end
        seen_labels[label_key] = true;
        accessxi.character_creation_world_add_row_candidate(
            rows,
            index,
            match.label,
            ('%s.sequential:%s'):fmt(tostring(source or ''), tostring(match.source or '')),
            ptr,
            ('+%03X'):fmt(tonumber(match.offset) or 0));
    end

    return rows, match_count;
end

function accessxi.character_creation_world_scan_root(rows, ptr, source, expected_count, max_rows)
    ptr = tonumber(ptr) or 0;
    if (not accessxi.is_probe_pointer(ptr)) then
        return 0;
    end

    local found = 0;
    local render_rows = accessxi.survival_guide_render_row_entries(ptr, source, max_rows);
    for row, entries in pairs(render_rows) do
        if (type(entries) == 'table') then
            for _, entry in ipairs(entries) do
                if (accessxi.character_creation_world_add_row_candidate(
                    rows,
                    row,
                    entry.text or entry.label or '',
                    ('%s.render'):fmt(tostring(source or '')),
                    ptr,
                    ('+%03X'):fmt(tonumber(entry.offset) or 0))) then
                    found = found + 1;
                end
            end
        end
    end

    local sequential_rows, sequential_count = accessxi.character_creation_world_sequential_rows_from_ptr(ptr, source, expected_count, max_rows);
    for row, entries in pairs(sequential_rows) do
        if (type(entries) == 'table') then
            for _, entry in ipairs(entries) do
                if (accessxi.character_creation_world_add_row_candidate(
                    rows,
                    row,
                    entry.label or '',
                    entry.source or '',
                    entry.render or 0,
                    entry.offsets or '')) then
                    found = found + 1;
                end
            end
        end
    end

    return math.max(found, tonumber(sequential_count) or 0);
end

function accessxi.character_creation_world_native_row_candidates(obj, state, max_rows)
    obj = tonumber(obj) or 0;
    state = type(state) == 'table' and state or T{};
    max_rows = math.min(math.max(tonumber(max_rows) or 4, 4), 32);
    local expected_count = tonumber(state.count) or max_rows;
    local focus = type(state.focus) == 'table' and state.focus or T{};
    local child04 = accessxi.is_probe_pointer(obj) and (read_u32(obj + 0x04) or 0) or 0;
    local entry = tonumber(focus.entry) or (accessxi.is_probe_pointer(obj) and (read_u32(obj + 0x08) or 0) or 0);
    local child0c = tonumber(state.query_child) or 0;
    if (not accessxi.is_probe_pointer(child0c)) then
        child0c = accessxi.is_probe_pointer(obj) and (read_u32(obj + 0x0C) or 0) or 0;
    end
    local desc04 = tonumber(focus.desc04) or 0;
    local desc0c = tonumber(focus.desc0c) or 0;
    local record = tonumber(focus.record) or 0;

    local cache_key = ('%08X:%08X:%08X:%08X:%08X:%08X:%08X:%d:%d:%d'):fmt(
        obj,
        child04,
        entry,
        child0c,
        desc04,
        desc0c,
        record,
        tonumber(state.selected) or 0,
        expected_count,
        max_rows);
    if (accessxi.character_creation_world_rows_cache_key == cache_key
        and accessxi.character_creation_world_rows_cache ~= nil) then
        return accessxi.character_creation_world_rows_cache, child0c, accessxi.character_creation_world_rows_probe or '';
    end

    local rows = T{};
    local generic_rows, generic_child = accessxi.survival_guide_native_row_candidates(obj, true, max_rows);
    accessxi.character_creation_world_merge_rows(rows, generic_rows);

    local roots = T{};
    local seen_roots = {};
    local function add_root(label, ptr)
        ptr = tonumber(ptr) or 0;
        if (accessxi.is_probe_pointer(ptr) and seen_roots[ptr] ~= true and roots:len() < 36) then
            seen_roots[ptr] = true;
            roots:append(T{ label = label, ptr = ptr });
        end
    end

    add_root('obj', obj);
    add_root('child04', child04);
    add_root('entry', entry);
    add_root('child0c', child0c);
    add_root('desc04', desc04);
    add_root('desc0c', desc0c);
    add_root('record', record);

    for _, root in ipairs(T{
        T{ label = 'child04', ptr = child04 },
        T{ label = 'child0c', ptr = child0c },
        T{ label = 'entry', ptr = entry },
        T{ label = 'desc0c', ptr = desc0c },
    }) do
        local ptr = tonumber(root.ptr) or 0;
        if (accessxi.is_probe_pointer(ptr)) then
            for off = 0x00, 0x100, 4 do
                add_root(('%s+%03X'):fmt(root.label, off), read_u32(ptr + off) or 0);
            end
        end
    end

    local probe = T{};
    for _, root in ipairs(roots) do
        local found = accessxi.character_creation_world_scan_root(rows, root.ptr, root.label, expected_count, max_rows);
        if ((tonumber(found) or 0) > 0 and probe:len() < 12) then
            probe:append(('%s=0x%08X:%d'):fmt(tostring(root.label or ''), tonumber(root.ptr) or 0, tonumber(found) or 0));
        end
    end

    accessxi.character_creation_world_rows_cache_key = cache_key;
    accessxi.character_creation_world_rows_cache = rows;
    accessxi.character_creation_world_rows_probe = probe:concat(',');
    return rows, child0c ~= 0 and child0c or generic_child, accessxi.character_creation_world_rows_probe;
end

function accessxi.character_creation_world_probe_raw_state(obj, child04, entry, child0c, desc04, desc0c, record)
    local parts = T{};
    local function add_ptr(label, ptr, dword_specs, byte_specs)
        ptr = tonumber(ptr) or 0;
        if (not accessxi.is_probe_pointer(ptr)) then
            return;
        end

        local bits = T{};
        for _, spec in ipairs(dword_specs or T{}) do
            local offset = tonumber(spec.offset) or 0;
            local count = tonumber(spec.count) or 0;
            if (count > 0) then
                bits:append(('d%03X=%s'):fmt(offset, accessxi.format_probe_dwords(ptr, offset, count)));
            end
        end
        for _, spec in ipairs(byte_specs or T{}) do
            local offset = tonumber(spec.offset) or 0;
            local length = tonumber(spec.length) or 0;
            if (length > 0) then
                bits:append(('b%03X=%s'):fmt(offset, accessxi.format_probe_bytes(ptr, offset, length)));
            end
        end

        parts:append(('%s=0x%08X{%s}'):fmt(tostring(label or ''), ptr, bits:concat(' ')));
    end

    add_ptr('obj', obj,
        T{ T{ offset = 0x00, count = 24 }, T{ offset = 0x40, count = 24 }, T{ offset = 0x80, count = 24 } },
        T{ T{ offset = 0x00, length = 0x40 }, T{ offset = 0x80, length = 0x40 } });
    add_ptr('child04', child04,
        T{ T{ offset = 0x00, count = 32 }, T{ offset = 0x80, count = 24 }, T{ offset = 0x100, count = 24 } },
        T{ T{ offset = 0x00, length = 0x80 }, T{ offset = 0x100, length = 0x80 } });
    add_ptr('entry', entry,
        T{ T{ offset = 0x00, count = 32 }, T{ offset = 0x40, count = 32 }, T{ offset = 0x80, count = 32 }, T{ offset = 0x100, count = 24 } },
        T{ T{ offset = 0x00, length = 0x80 }, T{ offset = 0x100, length = 0x80 } });
    add_ptr('child0c', child0c,
        T{ T{ offset = 0x00, count = 32 }, T{ offset = 0x40, count = 32 }, T{ offset = 0x80, count = 32 }, T{ offset = 0xC0, count = 24 } },
        T{ T{ offset = 0x40, length = 0xC0 } });
    add_ptr('desc04', desc04,
        T{ T{ offset = 0x00, count = 24 }, T{ offset = 0x40, count = 24 }, T{ offset = 0x80, count = 24 } },
        T{ T{ offset = 0x00, length = 0x80 } });
    add_ptr('desc0c', desc0c,
        T{ T{ offset = 0x00, count = 24 }, T{ offset = 0x40, count = 24 }, T{ offset = 0x80, count = 24 } },
        T{ T{ offset = 0x00, length = 0x80 } });
    add_ptr('record', record,
        T{ T{ offset = 0x00, count = 16 }, T{ offset = 0x40, count = 16 } },
        T{ T{ offset = 0x00, length = 0x80 } });

    return parts:concat(' || ');
end

function accessxi.character_creation_world_record_window(record, selected, count)
    record = tonumber(record) or 0;
    selected = tonumber(selected) or 0;
    count = tonumber(count) or 0;
    if (not accessxi.is_probe_pointer(record) or selected <= 0 or count <= 0 or selected > count) then
        return '';
    end

    local stride = 0x50;
    local base = record - ((selected - 1) * stride);
    if (not accessxi.is_probe_pointer(base)) then
        return '';
    end

    local parts = T{};
    for row = 1, math.min(count, 16) do
        local ptr = base + ((row - 1) * stride);
        if (accessxi.is_probe_pointer(ptr)) then
            parts:append(('r%02d=0x%08X d=%s b=%s'):fmt(
                row,
                ptr,
                accessxi.format_probe_dwords(ptr, 0x00, 10),
                accessxi.format_probe_bytes(ptr, 0x10, 0x30)));
        end
    end
    return parts:concat(' | ');
end

function accessxi.character_creation_world_compact_record_window(record, selected, count)
    record = tonumber(record) or 0;
    selected = tonumber(selected) or 0;
    count = tonumber(count) or 0;
    if (not accessxi.is_probe_pointer(record) or selected <= 0 or count <= 0 or selected > count) then
        return '';
    end

    local stride = 0x50;
    local base = record - ((selected - 1) * stride);
    if (not accessxi.is_probe_pointer(base)) then
        return '';
    end

    local parts = T{};
    for row = 1, math.min(count, 16) do
        local ptr = base + ((row - 1) * stride);
        if (accessxi.is_probe_pointer(ptr)) then
            parts:append(('r%02d=%s'):fmt(row, accessxi.format_probe_dwords(ptr, 0x00, 8)));
        end
    end
    return parts:concat('|');
end

function accessxi.character_creation_world_compact_raw_state(obj, child04, entry, child0c, desc04, desc0c, record, selected, count)
    return T{
        objD00 = accessxi.is_probe_pointer(obj) and accessxi.format_probe_dwords(obj, 0x00, 24) or '',
        objD40 = accessxi.is_probe_pointer(obj) and accessxi.format_probe_dwords(obj, 0x40, 16) or '',
        child04D00 = accessxi.is_probe_pointer(child04) and accessxi.format_probe_dwords(child04, 0x00, 24) or '',
        entryD00 = accessxi.is_probe_pointer(entry) and accessxi.format_probe_dwords(entry, 0x00, 24) or '',
        entryD40 = accessxi.is_probe_pointer(entry) and accessxi.format_probe_dwords(entry, 0x40, 24) or '',
        child0CD00 = accessxi.is_probe_pointer(child0c) and accessxi.format_probe_dwords(child0c, 0x00, 24) or '',
        child0CD40 = accessxi.is_probe_pointer(child0c) and accessxi.format_probe_dwords(child0c, 0x40, 24) or '',
        child0CD80 = accessxi.is_probe_pointer(child0c) and accessxi.format_probe_dwords(child0c, 0x80, 24) or '',
        child0CD120 = accessxi.is_probe_pointer(child0c) and accessxi.format_probe_dwords(child0c, 0x120, 32) or '',
        child0CB120 = accessxi.is_probe_pointer(child0c) and accessxi.format_probe_bytes(child0c, 0x120, 0xA0) or '',
        child0CD460 = accessxi.is_probe_pointer(child0c) and accessxi.format_probe_dwords(child0c, 0x460, 32) or '',
        child0CB460 = accessxi.is_probe_pointer(child0c) and accessxi.format_probe_bytes(child0c, 0x460, 0xA0) or '',
        desc04D00 = accessxi.is_probe_pointer(desc04) and accessxi.format_probe_dwords(desc04, 0x00, 24) or '',
        desc0CD00 = accessxi.is_probe_pointer(desc0c) and accessxi.format_probe_dwords(desc0c, 0x00, 24) or '',
        desc0CD40 = accessxi.is_probe_pointer(desc0c) and accessxi.format_probe_dwords(desc0c, 0x40, 24) or '',
        recordD00 = accessxi.is_probe_pointer(record) and accessxi.format_probe_dwords(record, 0x00, 16) or '',
        rowWindow = accessxi.character_creation_world_compact_record_window(record, selected, count),
    };
end

function accessxi.character_creation_world_row_descriptor_base(desc0c, selected, count)
    desc0c = tonumber(desc0c) or 0;
    selected = tonumber(selected) or 0;
    count = tonumber(count) or 0;
    if (not accessxi.is_probe_pointer(desc0c) or selected <= 0 or count <= 0 or selected > count) then
        return 0;
    end

    local stride = 0x14;
    local base = desc0c - ((selected - 1) * stride);
    if (not accessxi.is_probe_pointer(base)) then
        return 0;
    end
    return base;
end

function accessxi.log_character_creation_world_row_descriptor_probe(menu_name, desc0c, selected, count)
    if (not tostring(menu_name or ''):eq('menu    worldsel', true)) then
        return;
    end

    selected = tonumber(selected) or 0;
    count = tonumber(count) or 0;
    local base = accessxi.character_creation_world_row_descriptor_base(desc0c, selected, count);
    if (base == 0) then
        return;
    end

    local key = ('%08X:%d'):fmt(base, count);
    if (key == tostring(accessxi.character_creation_world_rowdesc_probe_key or '')) then
        return;
    end
    accessxi.character_creation_world_rowdesc_probe_key = key;

    for row = 1, math.min(count, 16) do
        local slot = base + ((row - 1) * 0x14);
        local rec = read_u32(slot + 0x00) or 0;
        local desc = read_u32(slot + 0x04) or 0;
        local v08 = read_u32(slot + 0x08) or 0;
        local v0c = read_u32(slot + 0x0C) or 0;
        local v10 = read_u32(slot + 0x10) or 0;
        log_state(('state character-creation world-rowdesc menu="%s" selected=%d count=%d row=%d slot=0x%08X rec=0x%08X desc=0x%08X slotD="%08X,%08X,%08X,%08X,%08X" recD="%s" descD="%s" descPtr="%s" descRuns="%s"'):fmt(
            tostring(menu_name or ''),
            selected,
            count,
            row,
            slot,
            rec,
            desc,
            rec,
            desc,
            v08,
            v0c,
            v10,
            accessxi.escape_probe_log_text(accessxi.is_probe_pointer(rec) and accessxi.format_probe_dwords(rec, 0x00, 12) or ''),
            accessxi.escape_probe_log_text(accessxi.is_probe_pointer(desc) and accessxi.format_probe_dwords(desc, 0x00, 16) or ''),
            accessxi.escape_probe_log_text(accessxi.is_probe_pointer(desc) and accessxi.status_menu_probe_pointer_fields(desc) or ''),
            accessxi.escape_probe_log_text(accessxi.is_probe_pointer(desc) and accessxi.status_menu_probe_runs(desc, 0x100) or '')));
    end
end

function accessxi.log_character_creation_world_name_source_probe(menu_name, obj, state)
    if (not tostring(menu_name or ''):eq('menu    worldsel', true)) then
        return;
    end

    obj = tonumber(obj) or 0;
    state = type(state) == 'table' and state or T{};
    local focus = type(state.focus) == 'table' and state.focus or T{};
    local child0c = tonumber(state.query_child) or 0;
    if (not accessxi.is_probe_pointer(child0c) and accessxi.is_probe_pointer(obj)) then
        child0c = read_u32(obj + 0x0C) or 0;
    end
    if (not accessxi.is_probe_pointer(child0c)) then
        return;
    end

    local name_ptr = read_u32(child0c + 0x58) or 0;
    local inline_id = read_u32(child0c + 0x5C) or -1;
    local inline_name = accessxi.character_creation_world_packet_name(read_probe_string(child0c + 0x60, 16));
    local inline_match = accessxi.character_creation_world_dat_match(inline_name);
    local rows = type(accessxi.character_creation_world_packet_rows) == 'table' and accessxi.character_creation_world_packet_rows or T{};
    local packet_preview = accessxi.character_creation_world_packet_rows_preview(rows, 24);
    local child04 = accessxi.is_probe_pointer(obj) and (read_u32(obj + 0x04) or 0) or 0;
    local entry = tonumber(focus.entry) or (accessxi.is_probe_pointer(obj) and (read_u32(obj + 0x08) or 0) or 0);
    local desc04 = tonumber(focus.desc04) or 0;
    local desc0c = tonumber(focus.desc0c) or 0;
    local record = tonumber(focus.record) or 0;
    local world_hits = accessxi.character_creation_world_name_hit_summary(T{
        T{ label = 'obj', ptr = obj },
        T{ label = 'child04', ptr = child04 },
        T{ label = 'entry', ptr = entry },
        T{ label = 'child0c', ptr = child0c },
        T{ label = 'desc04', ptr = desc04 },
        T{ label = 'desc0c', ptr = desc0c },
        T{ label = 'record', ptr = record },
        T{ label = 'namePtr', ptr = name_ptr },
    }, 0x600, 32);
    local child0c_hit_records = accessxi.character_creation_world_hit_record_summary('child0c', child0c, 0x1200, 40);
    local key = ('%08X:%08X:%d:%s:%d:%d:%s'):fmt(
        child0c,
        name_ptr,
        inline_id,
        inline_name,
        tonumber(state.selected) or -1,
        rows:len(),
        tostring(accessxi.character_creation_world_packet_source or ''));
    if (key == tostring(accessxi.character_creation_world_name_source_probe_key or '')) then
        return;
    end
    accessxi.character_creation_world_name_source_probe_key = key;

    log_state(('state character-creation world-name-source menu="%s" selected=%d count=%d child0c=0x%08X namePtr=0x%08X inlineId=%d inlineName="%s" inlineDat=%s packetSource="%s" packetBase=0x%08X packetCount=%d packetRows="%s" namePtrD="%s" namePtrRuns="%s" worldHits="%s" hitRecords="%s"'):fmt(
        tostring(menu_name or ''),
        tonumber(state.selected) or -1,
        tonumber(state.count) or 0,
        child0c,
        name_ptr,
        inline_id,
        accessxi.escape_probe_log_text(inline_name),
        inline_match ~= nil and 'yes' or 'no',
        accessxi.escape_probe_log_text(tostring(accessxi.character_creation_world_packet_source or '')),
        tonumber(accessxi.character_creation_world_packet_base) or 0,
        rows:len(),
        accessxi.escape_probe_log_text_wide(packet_preview),
        accessxi.escape_probe_log_text(accessxi.is_probe_pointer(name_ptr) and accessxi.format_probe_dwords(name_ptr, 0x00, 24) or ''),
        accessxi.escape_probe_log_text(accessxi.is_probe_pointer(name_ptr) and accessxi.status_menu_probe_runs(name_ptr, 0x180) or ''),
        accessxi.escape_probe_log_text_wide(world_hits),
        accessxi.escape_probe_log_text_wide(child0c_hit_records)));
end

function accessxi.log_character_creation_world_child0c_record_probe(menu_name, child0c, selected, count)
    if (not tostring(menu_name or ''):eq('menu    worldsel', true)) then
        return;
    end

    child0c = tonumber(child0c) or 0;
    selected = tonumber(selected) or 0;
    count = tonumber(count) or 0;
    if (not accessxi.is_probe_pointer(child0c)) then
        return;
    end

    local records = accessxi.character_creation_world_direct_record_hits(child0c, 0x1400, 96);
    local preview = accessxi.character_creation_world_direct_record_preview(records, 96);
    local windows = accessxi.character_creation_world_direct_record_window_summary(records, count, 8);
    local key = ('%08X:%d:%s'):fmt(
        child0c,
        records:len(),
        preview);
    if (key == tostring(accessxi.character_creation_world_child0c_record_probe_key or '')) then
        return;
    end
    accessxi.character_creation_world_child0c_record_probe_key = key;

    if (records:len() <= 0) then
        log_state(('state character-creation world-child0c-record menu="%s" selected=%d count=%d records=0 child0c=0x%08X'):fmt(
            tostring(menu_name or ''),
            selected,
            count,
            child0c));
        return;
    end

    log_state(('state character-creation world-record-window menu="%s" selected=%d count=%d child0c=0x%08X records=%d windows="%s"'):fmt(
        tostring(menu_name or ''),
        selected,
        count,
        child0c,
        records:len(),
        accessxi.escape_probe_log_text_wide(windows)));

    for index, record in ipairs(records) do
        log_state(('state character-creation world-child0c-record menu="%s" selected=%d count=%d child0c=0x%08X seq=%d records=%d offset=0x%03X id=%d name="%s" source="%s" d="%s"'):fmt(
            tostring(menu_name or ''),
            selected,
            count,
            child0c,
            index,
            records:len(),
            tonumber(record.offset) or 0,
            tonumber(record.id) or -1,
            accessxi.escape_probe_log_text(tostring(record.label or '')),
            accessxi.escape_probe_log_text(tostring(record.source or '')),
            accessxi.escape_probe_log_text(tostring(record.dwords or ''))));
    end
end

function accessxi.log_character_creation_world_record_ref_probe(menu_name, child0c, entry, desc0c, record, selected, count)
    if (not tostring(menu_name or ''):eq('menu    worldsel', true)) then
        return;
    end

    child0c = tonumber(child0c) or 0;
    entry = tonumber(entry) or 0;
    desc0c = tonumber(desc0c) or 0;
    record = tonumber(record) or 0;
    selected = tonumber(selected) or 0;
    count = tonumber(count) or 0;
    if (not accessxi.is_probe_pointer(child0c)) then
        return;
    end

    local records = accessxi.character_creation_world_direct_record_hits(child0c, 0x1400, 96);
    local desc_slot = accessxi.is_probe_pointer(desc0c) and desc0c or 0;
    local desc_rec = accessxi.is_probe_pointer(desc_slot) and (read_u32(desc_slot + 0x00) or 0) or 0;
    local desc_desc = accessxi.is_probe_pointer(desc_slot) and (read_u32(desc_slot + 0x04) or 0) or 0;
    local refs = T{};

    local function append_refs(text)
        text = tostring(text or '');
        if (text ~= '') then
            refs:append(text);
        end
    end

    append_refs(accessxi.character_creation_world_record_ref_summary('entry', entry, records, child0c, 0x240, 12));
    append_refs(accessxi.character_creation_world_record_ref_summary('desc0c-slot', desc_slot, records, child0c, 0x40, 12));
    append_refs(accessxi.character_creation_world_record_ref_summary('desc0c-rec', desc_rec, records, child0c, 0x180, 12));
    append_refs(accessxi.character_creation_world_record_ref_summary('desc0c-desc', desc_desc, records, child0c, 0x180, 12));
    append_refs(accessxi.character_creation_world_record_ref_summary('selected-rec', record, records, child0c, 0x180, 12));

    local row_context = '';
    if (accessxi.is_probe_pointer(record)) then
        row_context = accessxi.format_probe_dwords(record, 0x00, 12);
    end

    local ref_text = refs:concat('|');
    local key = ('%08X:%08X:%08X:%08X:%08X:%d:%d:%s'):fmt(
        child0c,
        entry,
        desc0c,
        desc_rec,
        record,
        selected,
        count,
        ref_text);
    if (key == tostring(accessxi.character_creation_world_record_ref_probe_key or '')) then
        return;
    end
    accessxi.character_creation_world_record_ref_probe_key = key;

    log_state(('state character-creation world-record-ref menu="%s" selected=%d count=%d child0c=0x%08X records=%d entry=0x%08X descSlot=0x%08X descRec=0x%08X descDesc=0x%08X selectedRec=0x%08X hits=%d refs="%s" rowD="%s"'):fmt(
        tostring(menu_name or ''),
        selected,
        count,
        child0c,
        records:len(),
        entry,
        desc_slot,
        desc_rec,
        desc_desc,
        record,
        refs:len(),
        accessxi.escape_probe_log_text_wide(ref_text),
        accessxi.escape_probe_log_text(row_context)));
end

function accessxi.log_character_creation_world_row_map_probe(menu_name, obj, child04, entry, child0c, desc04, desc0c, record, selected, count)
    if (not tostring(menu_name or ''):eq('menu    worldsel', true)) then
        return;
    end

    obj = tonumber(obj) or 0;
    child04 = tonumber(child04) or 0;
    entry = tonumber(entry) or 0;
    child0c = tonumber(child0c) or 0;
    desc04 = tonumber(desc04) or 0;
    desc0c = tonumber(desc0c) or 0;
    record = tonumber(record) or 0;
    selected = tonumber(selected) or 0;
    count = tonumber(count) or 0;

    local desc_slot = accessxi.is_probe_pointer(desc0c) and desc0c or 0;
    local desc_rec = accessxi.is_probe_pointer(desc_slot) and (read_u32(desc_slot + 0x00) or 0) or 0;
    local desc_desc = accessxi.is_probe_pointer(desc_slot) and (read_u32(desc_slot + 0x04) or 0) or 0;
    local rowdesc_base = accessxi.character_creation_world_row_descriptor_base(desc0c, selected, count);
    local record_base = accessxi.is_probe_pointer(record) and selected > 0 and (record - ((selected - 1) * 0x50)) or 0;

    local key = ('%08X:%08X:%08X:%08X:%08X:%08X:%08X:%08X:%08X:%08X:%d:%d'):fmt(
        obj,
        child04,
        entry,
        child0c,
        desc04,
        desc0c,
        desc_rec,
        desc_desc,
        rowdesc_base,
        record_base,
        selected,
        count);
    if (key == tostring(accessxi.character_creation_world_row_map_probe_key or '')) then
        return;
    end
    accessxi.character_creation_world_row_map_probe_key = key;

    local records = accessxi.character_creation_world_direct_record_hits(child0c, 0x1400, 128);
    local roots = T{};
    local seen_roots = {};
    local function add_root(label, ptr, length)
        ptr = tonumber(ptr) or 0;
        if (accessxi.is_probe_pointer(ptr) and seen_roots[ptr] ~= true and roots:len() < 24) then
            seen_roots[ptr] = true;
            roots:append(T{ label = label, ptr = ptr, length = tonumber(length) or 0x400 });
        end
    end

    add_root('obj', obj, 0x180);
    add_root('child04', child04, 0x300);
    add_root('entry', entry, 0x300);
    add_root('child0c', child0c, 0x1400);
    add_root('desc04', desc04, 0x300);
    add_root('desc0c', desc0c, 0x300);
    add_root('descRec', desc_rec, 0x300);
    add_root('descDesc', desc_desc, 0x300);
    add_root('rowdescBase', rowdesc_base, 0x180);
    add_root('record', record, 0x300);
    add_root('recordBase', record_base, 0x600);

    for _, root in ipairs(T{
        T{ label = 'obj', ptr = obj },
        T{ label = 'child04', ptr = child04 },
        T{ label = 'entry', ptr = entry },
        T{ label = 'child0c', ptr = child0c },
        T{ label = 'desc0c', ptr = desc0c },
    }) do
        local ptr = tonumber(root.ptr) or 0;
        if (accessxi.is_probe_pointer(ptr)) then
            for off = 0x00, 0x80, 4 do
                add_root(('%s+%03X'):fmt(tostring(root.label or ''), off), read_u32(ptr + off) or 0, 0x300);
            end
        end
    end

    local maps = T{};
    for _, root in ipairs(roots) do
        if (maps:len() >= 20) then
            break;
        end
        local id_summary = accessxi.character_creation_world_id_array_summary(
            root.label,
            root.ptr,
            root.length,
            count,
            4);
        if (id_summary ~= '') then
            maps:append(id_summary);
        end
        if (maps:len() >= 20) then
            break;
        end
        local ptr_summary = accessxi.character_creation_world_record_pointer_array_summary(
            root.label,
            root.ptr,
            records,
            child0c,
            root.length,
            count,
            4);
        if (ptr_summary ~= '') then
            maps:append(ptr_summary);
        end
    end

    log_state(('state character-creation world-rowmap menu="%s" selected=%d count=%d child0c=0x%08X records=%d maps="%s"'):fmt(
        tostring(menu_name or ''),
        selected,
        count,
        child0c,
        records:len(),
        accessxi.escape_probe_log_text_wide(maps:concat(' || '))));
end

function accessxi.character_creation_world_global_object_chain(global_ptr)
    global_ptr = tonumber(global_ptr) or 0;
    if (not accessxi.is_probe_pointer(global_ptr)) then
        return 0, 0;
    end

    local first = read_u32(global_ptr) or 0;
    local object = accessxi.is_probe_pointer(first) and (read_u32(first) or 0) or 0;
    return first, object;
end

function accessxi.log_character_creation_world_lobby_probe(menu_name, obj, child0c, selected, count)
    if (not tostring(menu_name or ''):eq('menu    worldsel', true)) then
        return;
    end

    obj = tonumber(obj) or 0;
    child0c = tonumber(child0c) or 0;
    selected = tonumber(selected) or 0;
    count = tonumber(count) or 0;

    local lobby_first, lobby_obj = accessxi.character_creation_world_global_object_chain(accessxi.ptrs.lobby or 0);
    local select_first, select_obj = accessxi.character_creation_world_global_object_chain(accessxi.ptrs.select or 0);

    local key = ('%08X:%08X:%08X:%08X:%08X:%08X:%08X:%d:%d'):fmt(
        obj,
        child0c,
        tonumber(accessxi.ptrs.lobby) or 0,
        lobby_first,
        lobby_obj,
        tonumber(accessxi.ptrs.select) or 0,
        select_obj,
        selected,
        count);
    if (key == tostring(accessxi.character_creation_world_lobby_probe_key or '')) then
        return;
    end
    accessxi.character_creation_world_lobby_probe_key = key;

    local roots = T{};
    local seen_roots = {};
    local function add_root(label, ptr, length)
        ptr = tonumber(ptr) or 0;
        if (accessxi.is_probe_pointer(ptr) and seen_roots[ptr] ~= true and roots:len() < 40) then
            seen_roots[ptr] = true;
            roots:append(T{ label = tostring(label or ''), ptr = ptr, length = tonumber(length) or 0x400 });
        end
    end

    local function add_chain(label, global_ptr, first_ptr, object_ptr)
        add_root(('%s-global'):fmt(label), global_ptr, 0x80);
        add_root(('%s-first'):fmt(label), first_ptr, 0x300);
        add_root(('%s-object'):fmt(label), object_ptr, 0x1000);
        if (accessxi.is_probe_pointer(object_ptr)) then
            for off = 0x00, 0x140, 4 do
                add_root(('%s-object+%03X'):fmt(label, off), read_u32(object_ptr + off) or 0, 0x800);
            end
        end
    end

    add_root('menu-object', obj, 0x300);
    add_root('world-child0c', child0c, 0x1400);
    add_chain('lobby', accessxi.ptrs.lobby or 0, lobby_first, lobby_obj);
    add_chain('select', accessxi.ptrs.select or 0, select_first, select_obj);

    local records = accessxi.character_creation_world_direct_record_hits(child0c, 0x1400, 128);
    local name_hits = T{};
    local map_hits = T{};
    for _, root in ipairs(roots) do
        if (name_hits:len() < 32) then
            local hits = accessxi.character_creation_world_name_hits(root.ptr, root.length, 8);
            for _, hit in ipairs(hits) do
                name_hits:append(('%s:%s+%03X=%s#%d'):fmt(
                    tostring(root.label or ''),
                    tostring(hit.mode or ''),
                    tonumber(hit.offset) or 0,
                    tostring(hit.label or ''),
                    tonumber(hit.row) or -1));
                if (name_hits:len() >= 32) then
                    break;
                end
            end
        end

        if (map_hits:len() < 16) then
            local id_summary = accessxi.character_creation_world_id_array_summary(
                root.label,
                root.ptr,
                root.length,
                count,
                2);
            if (id_summary ~= '') then
                map_hits:append(id_summary);
            end
        end

        if (map_hits:len() < 16) then
            local ptr_summary = accessxi.character_creation_world_record_pointer_array_summary(
                root.label,
                root.ptr,
                records,
                child0c,
                root.length,
                count,
                2);
            if (ptr_summary ~= '') then
                map_hits:append(ptr_summary);
            end
        end

        if (name_hits:len() >= 32 and map_hits:len() >= 16) then
            break;
        end
    end

    local lobby_fields = accessxi.is_probe_pointer(lobby_obj) and accessxi.format_probe_index_fields(lobby_obj, 0x00, 0x140) or '';
    local select_fields = accessxi.is_probe_pointer(select_obj) and accessxi.format_probe_index_fields(select_obj, 0x00, 0x140) or '';
    log_state(('state character-creation world-lobby-probe menu="%s" selected=%d count=%d lobbyGlobal=0x%08X lobbyFirst=0x%08X lobbyObj=0x%08X selectGlobal=0x%08X selectFirst=0x%08X selectObj=0x%08X lobbyD="%s" lobbyFields="%s" selectD="%s" selectFields="%s" roots=%d nameHits="%s" maps="%s"'):fmt(
        tostring(menu_name or ''),
        selected,
        count,
        tonumber(accessxi.ptrs.lobby) or 0,
        lobby_first,
        lobby_obj,
        tonumber(accessxi.ptrs.select) or 0,
        select_first,
        select_obj,
        accessxi.escape_probe_log_text(accessxi.format_probe_dwords(lobby_obj, 0x00, 24)),
        accessxi.escape_probe_log_text(lobby_fields),
        accessxi.escape_probe_log_text(accessxi.format_probe_dwords(select_obj, 0x00, 24)),
        accessxi.escape_probe_log_text(select_fields),
        roots:len(),
        accessxi.escape_probe_log_text_wide(name_hits:concat('|')),
        accessxi.escape_probe_log_text_wide(map_hits:concat(' || '))));
end

function accessxi.log_character_creation_world_select_detail_probe(menu_name, obj, child0c, selected, count)
    if (not tostring(menu_name or ''):eq('menu    worldsel', true)) then
        return;
    end

    obj = tonumber(obj) or 0;
    child0c = tonumber(child0c) or 0;
    selected = tonumber(selected) or 0;
    count = tonumber(count) or 0;

    local lobby_first, lobby_obj = accessxi.character_creation_world_global_object_chain(accessxi.ptrs.lobby or 0);
    local select_first, select_obj = accessxi.character_creation_world_global_object_chain(accessxi.ptrs.select or 0);
    local name_ptr = accessxi.is_probe_pointer(child0c) and (read_u32(child0c + 0x58) or 0) or 0;

    local key = ('%08X:%08X:%08X:%08X:%08X:%08X:%08X:%d:%d'):fmt(
        obj,
        child0c,
        name_ptr,
        lobby_first,
        lobby_obj,
        select_first,
        select_obj,
        selected,
        count);
    if (key == tostring(accessxi.character_creation_world_select_detail_probe_key or '')) then
        return;
    end
    accessxi.character_creation_world_select_detail_probe_key = key;

    local function log_range(root_label, ptr, offset)
        ptr = tonumber(ptr) or 0;
        offset = tonumber(offset) or 0;
        if (not accessxi.is_probe_pointer(ptr)) then
            return;
        end

        log_state(('state character-creation world-select-detail-range menu="%s" selected=%d count=%d root="%s" ptr=0x%08X offset=0x%03X d="%s" hex="%s" s00="%s" s10="%s" s14="%s" runs="%s" fields="%s"'):fmt(
            tostring(menu_name or ''),
            selected,
            count,
            accessxi.escape_probe_log_text(tostring(root_label or '')),
            ptr,
            offset,
            accessxi.escape_probe_log_text(accessxi.format_probe_dwords(ptr, offset, 16)),
            accessxi.escape_probe_log_text_wide(accessxi.format_probe_hex_bytes(ptr, offset, 0x40)),
            accessxi.escape_probe_log_text(read_probe_string(ptr + offset + 0x00, 64)),
            accessxi.escape_probe_log_text(read_probe_string(ptr + offset + 0x10, 64)),
            accessxi.escape_probe_log_text(read_probe_string(ptr + offset + 0x14, 64)),
            accessxi.escape_probe_log_text_wide(accessxi.status_menu_probe_runs(ptr + offset, 0x80)),
            accessxi.escape_probe_log_text_wide(accessxi.format_probe_index_fields(ptr, offset, offset + 0x3C))));
    end

    log_state(('state character-creation world-select-detail menu="%s" selected=%d count=%d obj=0x%08X child0c=0x%08X namePtr=0x%08X lobbyFirst=0x%08X lobbyObj=0x%08X selectFirst=0x%08X selectObj=0x%08X'):fmt(
        tostring(menu_name or ''),
        selected,
        count,
        obj,
        child0c,
        name_ptr,
        lobby_first,
        lobby_obj,
        select_first,
        select_obj));

    for _, spec in ipairs(T{
        T{ label = 'select-object', ptr = select_obj, offsets = T{ 0x00, 0x40, 0x80, 0xC0, 0x100, 0x140, 0x180, 0x1C0, 0x200, 0x240 } },
        T{ label = 'lobby-object', ptr = lobby_obj, offsets = T{ 0x00, 0x40, 0x80, 0xC0, 0x100 } },
        T{ label = 'select-first', ptr = select_first, offsets = T{ 0x00, 0x40, 0x80 } },
        T{ label = 'lobby-first', ptr = lobby_first, offsets = T{ 0x00, 0x40, 0x80 } },
        T{ label = 'name-ptr', ptr = name_ptr, offsets = T{ 0x00, 0x40, 0x80 } },
    }) do
        if (accessxi.is_probe_pointer(spec.ptr)) then
            for _, offset in ipairs(spec.offsets) do
                log_range(spec.label, spec.ptr, offset);
            end
        end
    end

    local roots = T{};
    local seen_roots = {};
    local function add_root(label, ptr, length)
        ptr = tonumber(ptr) or 0;
        if (accessxi.is_probe_pointer(ptr) and seen_roots[ptr] ~= true and roots:len() < 64) then
            seen_roots[ptr] = true;
            roots:append(T{ label = tostring(label or ''), ptr = ptr, length = tonumber(length) or 0x400 });
        end
    end

    add_root('select-object', select_obj, 0x1000);
    add_root('lobby-object', lobby_obj, 0x800);
    add_root('select-first', select_first, 0x300);
    add_root('lobby-first', lobby_first, 0x300);
    add_root('world-child0c', child0c, 0x1400);
    add_root('name-ptr', name_ptr, 0x600);

    if (accessxi.is_probe_pointer(select_obj)) then
        for off = 0x00, 0x300, 4 do
            add_root(('select+%03X'):fmt(off), read_u32(select_obj + off) or 0, 0x800);
        end
    end
    if (accessxi.is_probe_pointer(lobby_obj)) then
        for off = 0x00, 0x200, 4 do
            add_root(('lobby+%03X'):fmt(off), read_u32(lobby_obj + off) or 0, 0x800);
        end
    end

    local logged = 0;
    for _, root in ipairs(roots) do
        if (logged >= 48) then
            break;
        end
        local hits = accessxi.character_creation_world_name_hits(root.ptr, root.length, 12);
        for _, hit in ipairs(hits) do
            local offset = tonumber(hit.offset) or 0;
            local slot = offset >= 4 and (root.ptr + offset - 4) or 0;
            local preceding_id = accessxi.is_probe_pointer(slot) and (read_u32(slot) or -1) or -1;
            log_state(('state character-creation world-select-detail-hit menu="%s" selected=%d count=%d root="%s" ptr=0x%08X mode="%s" offset=0x%03X row=%d label="%s" precedingId=%d idMatch=%s d="%s"'):fmt(
                tostring(menu_name or ''),
                selected,
                count,
                accessxi.escape_probe_log_text(tostring(root.label or '')),
                tonumber(root.ptr) or 0,
                accessxi.escape_probe_log_text(tostring(hit.mode or '')),
                offset,
                tonumber(hit.row) or -1,
                accessxi.escape_probe_log_text(tostring(hit.label or '')),
                preceding_id,
                preceding_id == (tonumber(hit.row) or -2) and 'yes' or 'no',
                accessxi.escape_probe_log_text(accessxi.is_probe_pointer(slot) and accessxi.format_probe_dwords(slot, 0x00, 5) or '')));
            logged = logged + 1;
            if (logged >= 48) then
                break;
            end
        end
    end
end

function accessxi.log_character_creation_world_probe(menu_name, obj, state, rows, probe, reason)
    obj = tonumber(obj) or 0;
    if (not tostring(menu_name or ''):eq('menu    worldsel', true) or not accessxi.is_probe_pointer(obj)) then
        return;
    end
    accessxi.arm_character_creation_world_packet_trace('world-native-missing', 15000, 80);
    state = type(state) == 'table' and state or T{};
    local focus = type(state.focus) == 'table' and state.focus or T{};
    local entry = tonumber(focus.entry) or (read_u32(obj + 0x08) or 0);
    local child04 = read_u32(obj + 0x04) or 0;
    local child0c = tonumber(state.query_child) or (read_u32(obj + 0x0C) or 0);
    local desc04 = tonumber(focus.desc04) or 0;
    local desc0c = tonumber(focus.desc0c) or 0;
    local record = tonumber(focus.record) or 0;
    local key = ('%08X:%08X:%08X:%08X:%08X:%d:%d:%s'):fmt(
        obj,
        child04,
        entry,
        child0c,
        record,
        tonumber(state.selected) or 0,
        tonumber(state.count) or 0,
        tostring(reason or ''));
    if (key == tostring(accessxi.character_creation_world_probe_log_key or '')) then
        return;
    end
    accessxi.character_creation_world_probe_log_key = key;

    local compact = accessxi.character_creation_world_compact_raw_state(
        obj,
        child04,
        entry,
        child0c,
        desc04,
        desc0c,
        record,
        tonumber(state.selected) or 0,
        tonumber(state.count) or 0);

    log_state(('state character-creation world-probe-raw menu="%s" selected=%d count=%d objD00="%s" objD40="%s" child04D00="%s" entryD00="%s" entryD40="%s" child0CD00="%s" child0CD40="%s" child0CD80="%s" child0CD120="%s" child0CB120="%s" child0CD460="%s" child0CB460="%s" desc04D00="%s" desc0CD00="%s" desc0CD40="%s" recordD00="%s" rowWindow="%s"'):fmt(
        tostring(menu_name or ''),
        tonumber(state.selected) or -1,
        tonumber(state.count) or 0,
        accessxi.escape_probe_log_text(tostring(compact.objD00 or '')),
        accessxi.escape_probe_log_text(tostring(compact.objD40 or '')),
        accessxi.escape_probe_log_text(tostring(compact.child04D00 or '')),
        accessxi.escape_probe_log_text(tostring(compact.entryD00 or '')),
        accessxi.escape_probe_log_text(tostring(compact.entryD40 or '')),
        accessxi.escape_probe_log_text(tostring(compact.child0CD00 or '')),
        accessxi.escape_probe_log_text(tostring(compact.child0CD40 or '')),
        accessxi.escape_probe_log_text(tostring(compact.child0CD80 or '')),
        accessxi.escape_probe_log_text(tostring(compact.child0CD120 or '')),
        accessxi.escape_probe_log_text(tostring(compact.child0CB120 or '')),
        accessxi.escape_probe_log_text(tostring(compact.child0CD460 or '')),
        accessxi.escape_probe_log_text(tostring(compact.child0CB460 or '')),
        accessxi.escape_probe_log_text(tostring(compact.desc04D00 or '')),
        accessxi.escape_probe_log_text(tostring(compact.desc0CD00 or '')),
        accessxi.escape_probe_log_text(tostring(compact.desc0CD40 or '')),
        accessxi.escape_probe_log_text(tostring(compact.recordD00 or '')),
        accessxi.escape_probe_log_text(tostring(compact.rowWindow or ''))));

    accessxi.log_character_creation_world_row_descriptor_probe(
        menu_name,
        desc0c,
        tonumber(state.selected) or 0,
        tonumber(state.count) or 0);
    accessxi.log_character_creation_world_name_source_probe(menu_name, obj, state);
    accessxi.log_character_creation_world_child0c_record_probe(
        menu_name,
        child0c,
        tonumber(state.selected) or 0,
        tonumber(state.count) or 0);
    accessxi.log_character_creation_world_record_ref_probe(
        menu_name,
        child0c,
        entry,
        desc0c,
        record,
        tonumber(state.selected) or 0,
        tonumber(state.count) or 0);
    accessxi.log_character_creation_world_lobby_probe(
        menu_name,
        obj,
        child0c,
        tonumber(state.selected) or 0,
        tonumber(state.count) or 0);
    accessxi.log_character_creation_world_select_detail_probe(
        menu_name,
        obj,
        child0c,
        tonumber(state.selected) or 0,
        tonumber(state.count) or 0);
    accessxi.log_character_creation_world_row_map_probe(
        menu_name,
        obj,
        child04,
        entry,
        child0c,
        desc04,
        desc0c,
        record,
        tonumber(state.selected) or 0,
        tonumber(state.count) or 0);

    local root_bits = T{};
    for _, spec in ipairs(T{
        T{ label = 'child04', ptr = child04 },
        T{ label = 'entry', ptr = entry },
        T{ label = 'child0c', ptr = child0c },
        T{ label = 'desc0c', ptr = desc0c },
        T{ label = 'record', ptr = record },
    }) do
        local ptr = tonumber(spec.ptr) or 0;
        if (accessxi.is_probe_pointer(ptr)) then
            root_bits:append(('%s=0x%08X runs="%s" ptrs="%s"'):fmt(
                tostring(spec.label or ''),
                ptr,
                accessxi.escape_probe_log_text(accessxi.status_menu_probe_runs(ptr, 0x180)),
                accessxi.escape_probe_log_text(accessxi.status_menu_probe_pointer_fields(ptr))));
        end
    end

    log_state(('state character-creation world-probe menu="%s" selected=%d count=%d reason="%s" datRows=%d found="%s" rows="%s" roots="%s" worldRaw="%s" recordWindow="%s"'):fmt(
        tostring(menu_name or ''),
        tonumber(state.selected) or -1,
        tonumber(state.count) or 0,
        accessxi.escape_probe_log_text(tostring(reason or '')),
        (accessxi.character_creation_world_name_resource().labels or T{}):len(),
        accessxi.escape_probe_log_text(tostring(probe or '')),
        accessxi.escape_probe_log_text_wide(accessxi.survival_guide_format_native_row_candidates(rows or T{}, tonumber(state.count) or 4)),
        accessxi.escape_probe_log_text_wide(root_bits:concat(' || ')),
        accessxi.escape_probe_log_text_wide(accessxi.character_creation_world_probe_raw_state(obj, child04, entry, child0c, desc04, desc0c, record)),
        accessxi.escape_probe_log_text_wide(accessxi.character_creation_world_record_window(record, tonumber(state.selected) or 0, tonumber(state.count) or 0))));
end

function accessxi.character_creation_world_rows_proof_count(rows)
    rows = type(rows) == 'table' and rows or T{};
    local row_seen = {};
    local count = 0;
    for row, entries in pairs(rows) do
        local row_number = tonumber(row) or 0;
        if (row_number > 0 and row_seen[row_number] ~= true and type(entries) == 'table') then
            for _, entry in ipairs(entries) do
                local label = accessxi.survival_guide_native_label_for_speech(entry.label or '', 'plain');
                if (accessxi.character_creation_world_dat_match(label) ~= nil) then
                    row_seen[row_number] = true;
                    count = count + 1;
                    break;
                end
            end
        end
    end
    return count;
end

function accessxi.character_creation_world_label_from_rows(rows, selected, expected_count)
    rows = type(rows) == 'table' and rows or T{};
    selected = tonumber(selected) or 0;
    expected_count = tonumber(expected_count) or 0;
    local row_entries = rows[selected];
    if (row_entries == nil or row_entries:len() == 0) then
        return '', 'render-row-missing';
    end

    local proof_count = accessxi.character_creation_world_rows_proof_count(rows);
    local min_proof = expected_count > 0 and math.min(expected_count, 4) or 4;
    if (proof_count < min_proof) then
        return '', ('render-row-dat-insufficient-%d'):fmt(proof_count);
    end

    local seen = {};
    local labels = T{};
    local matches = T{};
    for _, entry in ipairs(row_entries) do
        local label = accessxi.survival_guide_native_label_for_speech(entry.label or '', 'plain');
        label = accessxi.plain_native_menu_label(label or '');
        local world = accessxi.character_creation_world_dat_match(label);
        local key = label:lower();
        if (label ~= '' and world ~= nil and seen[key] ~= true) then
            seen[key] = true;
            labels:append(world.label);
            matches:append(world);
        end
    end

    if (labels:len() == 1) then
        local world = matches[1] or T{};
        return labels[1], ('render-row-dat:%s'):fmt(tostring(world.source or ''));
    end
    return '', ('render-row-dat-ambiguous-%d'):fmt(labels:len());
end

function accessxi.character_creation_world_menu_entry(menu_name, obj, state)
    menu_name = tostring(menu_name or '');
    obj = tonumber(obj) or 0;
    state = type(state) == 'table' and state or T{};
    if (not menu_name:eq('menu    worldsel', true) or obj == 0) then
        return nil, 'not-worldsel';
    end

    local selected = tonumber(state.selected) or 0;
    if (selected <= 0) then
        selected = accessxi.character_creation_world_selected_from_state('world', state);
    end
    selected = tonumber(selected) or 0;
    local count = tonumber(state.count) or 0;
    if (count <= 0 or count > 64) then
        count = math.max(tonumber(state.field24) or 0, tonumber(state.field28) or 0);
    end
    if (selected <= 0 or count <= 0 or selected > count or count > 64) then
        return nil, 'world-selection-invalid';
    end

    local child = tonumber(state.query_child) or 0;
    local label = '';
    local mode = '';
    if (accessxi.is_probe_pointer(child)) then
        label, mode = accessxi.native_query_label_for_selection(child, selected, count, 'plain');
        label = accessxi.plain_native_menu_label(label or '');
        local world = accessxi.character_creation_world_dat_match(label);
        if (world ~= nil and tostring(mode or '') ~= '' and not tostring(mode or ''):eq('empty', true)) then
            return T{
                title = 'World',
                label = world.label,
                selected = selected,
                count = count,
                source = ('native-query-dat:%s child=0x%08X %s'):fmt(tostring(mode or ''), child, tostring(world.source or '')),
            }, 'native-query-dat';
        end
    end

    local runtime_label, runtime_mode, runtime_rows, runtime_ptr = accessxi.character_creation_world_runtime_label(selected, count);
    if (runtime_label ~= '') then
        return T{
            title = 'World',
            label = runtime_label,
            selected = selected,
            count = count,
            source = ('%s ptr=0x%08X'):fmt(tostring(runtime_mode or ''), tonumber(runtime_ptr) or 0),
            rows = runtime_rows,
            rows_child = runtime_ptr,
            max_rows = count,
        }, runtime_mode;
    end

    local packet_label, packet_mode = accessxi.character_creation_world_packet_label(selected, count);
    if (packet_label ~= '') then
        return T{
            title = 'World',
            label = packet_label,
            selected = selected,
            count = count,
            source = packet_mode,
        }, packet_mode;
    end

    local max_rows = math.min(math.max(count, 4), 32);
    local rows, rows_child, probe = accessxi.character_creation_world_native_row_candidates(obj, state, max_rows);
    local row_label, row_mode = accessxi.character_creation_world_label_from_rows(rows, selected, count);
    if (row_label ~= '') then
        return T{
            title = 'World',
            label = row_label,
            selected = selected,
            count = count,
            source = ('%s child=0x%08X'):fmt(row_mode, tonumber(rows_child) or 0),
            rows = rows,
            rows_child = rows_child,
            max_rows = max_rows,
        }, row_mode;
    end

    local reason = ('world-native-missing query=%s runtime=%s packet=%s rows=%s'):fmt(
        tostring(mode or ''),
        tostring(runtime_mode or ''),
        tostring(packet_mode or ''),
        tostring(row_mode or ''));
    accessxi.log_character_creation_world_probe(menu_name, obj, state, rows, probe, reason);
    return nil, ('world-native-missing query=%s runtime=%s packet=%s rows=%s'):fmt(
        tostring(mode or ''),
        tostring(runtime_mode or ''),
        tostring(packet_mode or ''),
        tostring(row_mode or ''));
end

function accessxi.log_character_creation_menu_probe(menu_name, kind, obj, state)
    obj = tonumber(obj) or 0;
    if (obj == 0 or not accessxi.is_probe_pointer(obj)) then
        return;
    end
    state = type(state) == 'table' and state or T{};
    local focus = type(state.focus) == 'table' and state.focus or accessxi.character_creation_focus_record(obj);
    focus = type(focus) == 'table' and focus or T{};
    local entry = tonumber(focus.entry) or (read_u32(obj + 0x08) or 0);
    local child04 = read_u32(obj + 0x04) or 0;
    local child0c = read_u32(obj + 0x0C) or 0;
    local record = tonumber(focus.record) or 0;
    local signature = ('menu=%s kind=%s obj=0x%08X qs=%d qc=%d qp=%d raw=0x%08X child=0x%08X count=%d f24=%d f28=%d f30=%d f34=%d f4c=%d f50=%d f58=%d entry=0x%08X desc04=0x%08X desc0c=0x%08X record=0x%08X rx=0x%X ry=0x%X'):fmt(
        tostring(menu_name or ''),
        tostring(kind or ''),
        obj,
        tonumber(state.query_selected) or -1,
        tonumber(state.query_count) or 0,
        tonumber(state.query_page) or 0,
        tonumber(state.query_raw) or 0,
        tonumber(state.query_child) or 0,
        tonumber(state.count) or 0,
        tonumber(state.field24) or 0,
        tonumber(state.field28) or 0,
        tonumber(state.field30) or 0,
        tonumber(state.field34) or 0,
        tonumber(state.field4c) or 0,
        tonumber(state.field50) or 0,
        tonumber(state.field58) or 0,
        entry,
        tonumber(focus.desc04) or 0,
        tonumber(focus.desc0c) or 0,
        record,
        tonumber(focus.record_x) or 0,
        tonumber(focus.record_y) or 0);
    if (signature == tostring(accessxi.last_character_creation_probe_key or '')) then
        return;
    end
    accessxi.last_character_creation_probe_key = signature;

    log_state(('state character-creation probe menu="%s" kind="%s" obj=0x%08X querySelected=%d queryCount=%d page=%d raw=0x%08X child=0x%08X count=%d fields="24=%d,28=%d,30=%d,34=%d,4C=%d,50=%d,58=%d" entry=0x%08X desc04=0x%08X desc0C=0x%08X record=0x%08X recordXY=0x%X,0x%X objFields="%s" child04Fields="%s" entryFields="%s" child0CFields="%s" recordDwords="%s"'):fmt(
        tostring(menu_name or ''),
        tostring(kind or ''),
        obj,
        tonumber(state.query_selected) or -1,
        tonumber(state.query_count) or 0,
        tonumber(state.query_page) or 0,
        tonumber(state.query_raw) or 0,
        tonumber(state.query_child) or 0,
        tonumber(state.count) or 0,
        tonumber(state.field24) or 0,
        tonumber(state.field28) or 0,
        tonumber(state.field30) or 0,
        tonumber(state.field34) or 0,
        tonumber(state.field4c) or 0,
        tonumber(state.field50) or 0,
        tonumber(state.field58) or 0,
        entry,
        tonumber(focus.desc04) or 0,
        tonumber(focus.desc0c) or 0,
        record,
        tonumber(focus.record_x) or 0,
        tonumber(focus.record_y) or 0,
        accessxi.escape_probe_log_text_wide(accessxi.title_config_menu_probe_fields(obj, 'obj')),
        accessxi.escape_probe_log_text_wide(accessxi.title_config_menu_probe_fields(child04, 'child04')),
        accessxi.escape_probe_log_text_wide(accessxi.title_config_menu_probe_fields(entry, 'entry')),
        accessxi.escape_probe_log_text_wide(accessxi.title_config_menu_probe_fields(child0c, 'child0C')),
        accessxi.escape_probe_log_text_wide(record ~= 0 and accessxi.format_probe_dwords(record, 0x00, 16) or '')));
end

function accessxi.character_creation_menu_speech(menu_name, obj)
    local kind = accessxi.character_creation_menu_kind(menu_name);
    local selected, count, state = accessxi.character_creation_menu_selected(menu_name, obj);
    if (type(state) == 'table') then
        state.selected = selected;
        state.count = count;
    end
    accessxi.log_character_creation_menu_probe(menu_name, kind, obj, state);
    if (accessxi.is_character_creation_text_input_menu_name(menu_name) and (is_chat_input_open == nil or not is_chat_input_open())) then
        local closed_reason = kind == 'name' and 'name-input-closed' or 'text-input-closed';
        log_state(('state character-creation quiet menu="%s" kind="%s" reason="%s" select=%d count=%d'):fmt(
            tostring(menu_name or ''),
            tostring(kind or ''),
            closed_reason,
            tonumber(selected) or -1,
            tonumber(count) or 0));
        return nil;
    end
    if (kind == 'nation') then
        local nation_entry = accessxi.character_creation_nation_menu_entry(selected);
        if (nation_entry ~= nil) then
            accessxi.current_speech_key = ('character-creation:%s:%d:%d:%s'):fmt(
                kind,
                tonumber(selected) or -1,
                tonumber(count) or 0,
                tostring(nation_entry.source or ''));
            log_state(('state character-creation nation-native menu="%s" kind="%s" select=%d count=%d heading="%s" body="%s" prompt="%s" source="%s"'):fmt(
                tostring(menu_name or ''),
                kind,
                tonumber(selected) or -1,
                tonumber(count) or 0,
                accessxi.escape_probe_log_text(nation_entry.heading or ''),
                accessxi.escape_probe_log_text_wide(nation_entry.body or ''),
                accessxi.escape_probe_log_text(nation_entry.prompt or ''),
                accessxi.escape_probe_log_text(nation_entry.source or '')));

            local parts = T{};
            local intro = accessxi.plain_native_menu_prompt(nation_entry.prompt or '');
            if (intro == '') then
                intro = accessxi.plain_native_menu_label(nation_entry.title or '');
            end
            local heading = accessxi.plain_native_menu_prompt(nation_entry.heading or '');
            local body = accessxi.character_creation_long_prompt_text(nation_entry.body or '');
            if (intro ~= '') then
                parts:append(accessxi.sentence_fragment(intro));
            end
            if (heading ~= '') then
                parts:append(accessxi.sentence_fragment(heading));
            end
            if (body ~= '') then
                parts:append(accessxi.sentence_fragment(body));
            end
            if (#parts > 0) then
                return parts:concat(' ');
            end
        end

        local reason = type(state) == 'table' and tostring(state.reason or 'missing-nation-resource-row') or 'missing-nation-resource-row';
        log_state(('state character-creation quiet menu="%s" kind="%s" reason="%s" select=%d count=%d'):fmt(
            tostring(menu_name or ''),
            tostring(kind or ''),
            accessxi.escape_probe_log_text(reason),
            tonumber(selected) or -1,
            tonumber(count) or 0));
        return nil;
    end
    if (kind == 'world') then
        local world_entry, world_mode = accessxi.character_creation_world_menu_entry(menu_name, obj, state);
        if (world_entry ~= nil) then
            selected = tonumber(world_entry.selected) or selected;
            count = tonumber(world_entry.count) or count;
            accessxi.current_speech_key = ('character-creation:%s:%d:%d:%s'):fmt(
                kind,
                selected,
                count,
                tostring(world_entry.source or ''));
            log_state(('state character-creation world-native menu="%s" kind="%s" select=%d count=%d label="%s" source="%s" mode="%s" rows="%s"'):fmt(
                tostring(menu_name or ''),
                kind,
                selected,
                count,
                accessxi.escape_probe_log_text(world_entry.label),
                accessxi.escape_probe_log_text(world_entry.source or ''),
                accessxi.escape_probe_log_text(tostring(world_mode or '')),
                accessxi.escape_probe_log_text_wide(accessxi.survival_guide_format_native_row_candidates(world_entry.rows or T{}, tonumber(world_entry.max_rows) or 4))));
            return ('%s. %s.'):fmt(world_entry.title, world_entry.label);
        end

        local reason = tostring(world_mode or 'world-native-missing');
        log_state(('state character-creation quiet menu="%s" kind="%s" reason="%s" select=%d count=%d'):fmt(
            tostring(menu_name or ''),
            tostring(kind or ''),
            accessxi.escape_probe_log_text(reason),
            tonumber(selected) or -1,
            tonumber(count) or 0));
        return nil;
    end
    local entry = accessxi.character_creation_menu_entry(kind, selected);
    if (entry == nil) then
        local reason = type(state) == 'table' and tostring(state.reason or 'missing-resource-row') or 'missing-resource-row';
        log_state(('state character-creation quiet menu="%s" kind="%s" reason="%s" select=%d count=%d'):fmt(
            tostring(menu_name or ''),
            tostring(kind or ''),
            accessxi.escape_probe_log_text(reason),
            tonumber(selected) or -1,
            tonumber(count) or 0));
        return nil;
    end

    accessxi.current_speech_key = ('character-creation:%s:%d:%d:%s'):fmt(
        kind,
        selected,
        count,
        tostring(entry.source or ''));
    log_state(('state character-creation native menu="%s" kind="%s" select=%d count=%d label="%s" source="%s"'):fmt(
        tostring(menu_name or ''),
        kind,
        selected,
        count,
        accessxi.escape_probe_log_text(entry.label),
        accessxi.escape_probe_log_text(entry.source or '')));
    local title = accessxi.plain_native_menu_label(entry.title or '');
    if (title ~= '') then
        return ('%s. %s.'):fmt(title, entry.label);
    end
    return ('%s.'):fmt(entry.label);
end

function accessxi.title_lobby_menu_entry(index)
    local resources = accessxi.native_menus_data.title_lobby_menu_resources or T{};
    local rows = resources.rows or T{};
    local spec = rows[tonumber(index) or -1];
    if (spec == nil) then
        return nil;
    end

    local label = accessxi.plain_native_menu_label(tostring(spec.label or ''));
    local label_source = tostring(spec.label_source or '');
    if (spec.label_dat ~= nil) then
        local dat_label = accessxi.dat_index_row_text(spec.label_dat, spec.label_row, 'label');
        if (dat_label ~= '') then
            label = dat_label;
            label_source = ('%s:%d'):fmt(tostring(spec.label_dat or ''), tonumber(spec.label_row) or -1);
        end
    end

    local help = accessxi.plain_native_menu_help(tostring(spec.help or ''));
    local help_source = tostring(spec.help_source or '');
    if (spec.help_dat ~= nil) then
        local dat_help = accessxi.dat_index_row_text(spec.help_dat, spec.help_row, 'help');
        if (dat_help ~= '') then
            help = dat_help;
            help_source = ('%s:%d'):fmt(tostring(spec.help_dat or ''), tonumber(spec.help_row) or -1);
        end
    end

    if (label == '') then
        return nil;
    end

    return T{
        label = label,
        help = help,
        label_source = label_source,
        help_source = help_source,
        source = ('label=%s help=%s'):fmt(label_source, help_source),
    };
end

function accessxi.title_lobby_menu_speech(index)
    accessxi.current_menu_speech_title = 'Main menu';
    local selected = tonumber(index) or -1;
    local entry = accessxi.title_lobby_menu_entry(selected);
    if (entry == nil or tostring(entry.label or '') == '') then
        log_state(('state title-lobby quiet select=%d reason="missing-resource-backed-row"'):fmt(selected));
        return nil;
    end

    log_state(('state title-lobby select=%d label="%s" help="%s" source="%s"'):fmt(
        selected,
        accessxi.escape_probe_log_text(entry.label),
        accessxi.escape_probe_log_text(entry.help or ''),
        accessxi.escape_probe_log_text(entry.source or '')));

    if (entry.help ~= nil and entry.help ~= '') then
        return ('Main menu. %s. %s.'):fmt(entry.label, entry.help);
    end
    return ('Main menu. %s.'):fmt(entry.label);
end

local function license_speech_from_index(index)
    local selected = option_from_index(T{ 'Decline', 'Accept' }, index);
    if (selected == '') then
        return nil;
    end
    return ('License agreement. %s selected. Choices: Accept, Decline.'):fmt(selected);
end

local function try_load_account_lib()
    if (accessxi.account ~= nil) then
        return accessxi.account;
    end

    local now = tick();
    if (accessxi.account_load_tried and (now - accessxi.account_last_try) < 5000) then
        return nil;
    end

    accessxi.account_load_tried = true;
    accessxi.account_last_try = now;
    local ok, account = pcall(require, 'ffxi.account');
    if (ok and account ~= nil) then
        accessxi.account = account;
        log_line('loaded ffxi.account character table reader');
        return accessxi.account;
    end

    log_line('ffxi.account unavailable: ' .. tostring(account));
    return nil;
end

local function clean_login_text(text)
    if (text == nil) then
        return '';
    end

    text = tostring(text):gsub('%z.*$', ''):trim();
    if (#text == 0) then
        return '';
    end

    text = text:gsub(string.char(0x81) .. string.char(0xA1), '*');
    text = text:gsub(string.char(0xC2) .. string.char(0xA1), '*');
    text = text:gsub('[%c]', ''):trim();
    return text;
end

function accessxi.speech_name(text)
    text = clean_login_text(text);
    if (text:match('^%?+$')) then
        local count = #text;
        if (count == 1) then
            return 'question mark';
        end
        return ('%d question marks'):fmt(count);
    end
    return text;
end

local function clean_chat_input_text(text)
    if (text == nil) then
        return '';
    end

    text = tostring(text):gsub('%z.*$', '');
    text = text:gsub(string.char(0xFF), '');
    text = text:gsub('[\r\n\t]+', ' '):gsub('[%c]', '');
    return text;
end

function accessxi.clean_chat_input_display_text(text)
    if (text == nil) then
        return '';
    end

    text = tostring(text):gsub('%z.*$', '');
    pcall(function ()
        local chat = AshitaCore:GetChatManager();
        if (chat ~= nil) then
            text = chat:ParseAutoTranslate(text, true);
        end
    end);
    pcall(function () text = text:strip_colors(); end);
    pcall(function () text = text:strip_translate(true); end);
    text = tostring(text):gsub(string.char(0x07), ' ');
    text = text:gsub(string.char(0xFF), '');
    text = text:gsub('[\r\n\t]+', ' '):gsub('[%c]', '');
    return text;
end

function accessxi.chat_input_auto_translate_phrase(state)
    if (type(state) ~= 'table') then
        return '';
    end

    local raw = tostring(state.raw or '');
    local display = tostring(state.display or '');
    if (raw == '' or display == '' or display == raw) then
        return '';
    end
    if (raw:sub(1, 1) ~= '/' or raw:match('^/%S+') == nil) then
        return '';
    end
    if (display:sub(1, #raw) ~= raw) then
        return '';
    end

    local text = display:sub(#raw + 1):trim();
    if (text == '') then
        return '';
    end
    text = text:gsub('^f(.+)ffd$', '%1');
    text = text:gsub('%s+', ' '):trim();
    return text;
end

function accessxi.chat_input_auto_translate_speech(previous_state, state)
    local text = accessxi.chat_input_auto_translate_phrase(state);
    if (text == '') then
        return nil, '', false;
    end

    local previous_text = accessxi.chat_input_auto_translate_phrase(previous_state);
    local key = ('auto-translate:%d:%s:%s:%d'):fmt(
        tonumber(state.status) or 0,
        tostring(state.raw or ''),
        tostring(state.display or ''),
        tonumber(state.caret) or 0);
    if (text == previous_text) then
        return nil, key, true;
    end
    return ('Auto translate. %s'):fmt(accessxi.sentence_fragment(text)), key, true;
end

function accessxi.clean_incoming_text(text)
    if (text == nil) then
        return '';
    end

    text = tostring(text):gsub('%z.*$', '');
    pcall(function ()
        local chat = AshitaCore:GetChatManager();
        if (chat ~= nil) then
            text = chat:ParseAutoTranslate(text, true);
        end
    end);
    text = tostring(text):gsub(string.char(0x07), ' ');
    pcall(function () text = text:strip_colors(); end);
    pcall(function () text = text:strip_translate(true); end);
    text = text:gsub('[\r\n\t]+', ' '):gsub('[%c]', '');
    text = text:gsub('^%[%d%d:%d%d:%d%d%]%s*', '');
    text = text:gsub('%s+', ' '):trim();
    return text;
end

accessxi.chat_history_contains_text = function (text)
    text = tostring(text or '');
    if (text == '' or accessxi.chat_history == nil or accessxi.chat_history.len == nil) then
        return false;
    end

    for i = 1, accessxi.chat_history:len() do
        local entry = accessxi.chat_history[i];
        if (entry ~= nil and tostring(entry.text or '') == text) then
            return true;
        end
    end
    return false;
end

accessxi.chat_history_escape = function (text)
    text = tostring(text or '');
    text = text:gsub('\\', '\\\\');
    text = text:gsub('\t', '\\t');
    text = text:gsub('\r', '\\r');
    text = text:gsub('\n', '\\n');
    return text;
end

accessxi.chat_history_unescape = function (text)
    text = tostring(text or '');
    text = text:gsub('\\([\\trn])', function (c)
        if (c == 't') then return '\t'; end
        if (c == 'r') then return '\r'; end
        if (c == 'n') then return '\n'; end
        return '\\';
    end);
    return text;
end

