accessxi.chat_history_entry = function (mode_text, label, text)
    text = accessxi.clean_incoming_text(text or '');
    if (text == '') then
        return nil;
    end

    local mode = bit.band(tonumber(mode_text) or 0, 0xFF);
    return T{
        tick = tick(),
        mode = mode,
        label = accessxi.chat_mode_label(mode),
        category = accessxi.chat_reader_category_key(mode, text),
        text = text,
    };
end

accessxi.chat_history_rebuild_positions = function ()
    accessxi.chat_reader_positions = T{};
    if (accessxi.chat_history:len() <= 0) then
        return;
    end

    local counts = T{ all = accessxi.chat_history:len() };
    for _, entry in ipairs(accessxi.chat_history) do
        local category = tostring(entry.category or 'other');
        counts[category] = (tonumber(counts[category]) or 0) + 1;
    end
    for key, count in pairs(counts) do
        accessxi.chat_reader_positions[tostring(key)] = tonumber(count) or 0;
    end
end

accessxi.chat_history_validate_cache_file = function (path, expected_count)
    local f = io.open(path, 'r');
    if (f == nil) then
        return false;
    end

    local header = f:read('*l');
    local count = 0;
    local valid = header == '#accessxi-chat-history-v2-native-only';
    if (valid) then
        for line in f:lines() do
            local row = tostring(line or '');
            if (row:match('^(%-?%d+)\t.*$') == nil) then
                valid = false;
                break;
            end
            count = count + 1;
        end
    end
    local closed = f:close();
    return valid and closed ~= nil and count == (tonumber(expected_count) or 0);
end

accessxi.chat_history_replace_cache_file = function (temporary_path)
    if (accessxi.chat_history_cache_write_blocked == true) then
        return false;
    end

    local source_wide = utf8_to_wide(temporary_path);
    local destination_wide = utf8_to_wide(accessxi.chat_history_path);
    if (source_wide == nil or destination_wide == nil) then
        return false;
    end

    local ok, moved = pcall(function ()
        -- MOVEFILE_REPLACE_EXISTING | MOVEFILE_WRITE_THROUGH
        return kernel32.MoveFileExW(source_wide, destination_wide, 0x00000009) ~= 0;
    end);
    return ok and moved == true;
end

accessxi.chat_history_preserve_invalid_cache = function ()
    local invalid_path = accessxi.chat_history_path .. '.invalid';
    local existing = io.open(invalid_path, 'r');
    if (existing ~= nil) then
        existing:close();
        invalid_path = invalid_path .. ('-%d-%d'):fmt(os.time(), tick());
    end

    local renamed, rename_error = os.rename(accessxi.chat_history_path, invalid_path);
    if (renamed == nil) then
        accessxi.chat_history_cache_write_blocked = true;
        log_state(('state chatlog cache-invalid-preserve-failed path="%s" error="%s"'):fmt(
            accessxi.escape_probe_log_text(accessxi.chat_history_path),
            accessxi.escape_probe_log_text(rename_error or 'unknown')));
        return false;
    end

    log_state(('state chatlog cache-invalid-preserved path="%s"'):fmt(
        accessxi.escape_probe_log_text(invalid_path)));
    return true;
end

accessxi.chat_history_write_cache = function ()
    if (accessxi.chat_history_cache_write_blocked == true) then
        return false;
    end

    local temporary_path = accessxi.chat_history_path .. '.tmp';
    local f = io.open(temporary_path, 'w');
    if (f == nil) then
        return false;
    end

    local wrote, write_error = pcall(function ()
        assert(f:write('#accessxi-chat-history-v2-native-only\n'));
        for _, entry in ipairs(accessxi.chat_history or T{}) do
            assert(f:write(tostring(entry.mode or 0), '\t',
                accessxi.chat_history_escape(entry.text or ''), '\n'));
        end
        assert(f:close());
    end);
    if (not wrote) then
        pcall(function () f:close(); end);
        os.remove(temporary_path);
        log_state(('state chatlog cache-write-failed error="%s"'):fmt(
            accessxi.escape_probe_log_text(write_error or 'unknown')));
        return false;
    end

    local expected_count = accessxi.chat_history ~= nil and accessxi.chat_history:len() or 0;
    if (not accessxi.chat_history_validate_cache_file(temporary_path, expected_count)) then
        os.remove(temporary_path);
        log_state('state chatlog cache-write-failed error="validation"');
        return false;
    end
    if (not accessxi.chat_history_replace_cache_file(temporary_path)) then
        os.remove(temporary_path);
        log_state('state chatlog cache-write-failed error="replace"');
        return false;
    end

    accessxi.chat_history_cache_ready = true;
    return true;
end

accessxi.chat_history_append_cache = function (entry)
    if (entry == nil) then
        return;
    end
    if (accessxi.chat_history_cache_ready ~= true) then
        accessxi.chat_history_write_cache();
        return;
    end

    local f = io.open(accessxi.chat_history_path, 'a');
    if (f == nil) then
        return;
    end

    local appended, append_error = pcall(function ()
        assert(f:write(tostring(entry.mode or 0), '\t',
            accessxi.chat_history_escape(entry.text or ''), '\n'));
        assert(f:close());
    end);
    if (not appended) then
        pcall(function () f:close(); end);
        accessxi.chat_history_cache_ready = false;
        log_state(('state chatlog cache-append-failed error="%s"'):fmt(
            accessxi.escape_probe_log_text(append_error or 'unknown')));
    end
end

function accessxi.chat_history_legacy_entry_reliable(mode_text, text)
    local mid = bit.band(tonumber(mode_text) or 0, 0xFF);
    -- Old AccessXI/Ashita output used 0 and 1, colliding with the real Say
    -- echo mode. The old cache did not preserve e.injected, so silence is
    -- safer than assigning those rows a native chat category.
    if (mid == 0 or mid == 1) then
        return false;
    end
    return accessxi.clean_incoming_text(text or '') ~= '';
end

accessxi.chat_history_load_cache = function ()
    local max_history = math.max(100, tonumber(accessxi.chat_history_max) or 1000);
    local function parse_cache_file(f, legacy)
        local parsed = {};
        local added = 0;
        local valid = true;
        local first_line = true;
        for line in f:lines() do
            line = tostring(line or ''):gsub('^\239\187\191', '');
            if (first_line and not legacy) then
                first_line = false;
                if (line ~= '#accessxi-chat-history-v2-native-only') then
                    valid = false;
                    break;
                end
            else
                first_line = false;
                local mode_text = nil;
                local label = '';
                local text = nil;
                if (legacy) then
                    mode_text, label, text = line:match('^(%-?%d+)\t([^\t]*)\t(.*)$');
                else
                    mode_text, text = line:match('^(%-?%d+)\t(.*)$');
                end

                if (text == nil) then
                    if (not legacy) then
                        valid = false;
                        break;
                    end
                else
                    text = accessxi.chat_history_unescape(text);
                    local reliable = not legacy or accessxi.chat_history_legacy_entry_reliable(mode_text, text);
                    if (reliable) then
                        local entry = accessxi.chat_history_entry(mode_text, label, text);
                        if (entry == nil and not legacy) then
                            valid = false;
                            break;
                        elseif (entry ~= nil) then
                            added = added + 1;
                            parsed[((added - 1) % max_history) + 1] = entry;
                            if (accessxi.chat_log_remember_apururu_defeated_line ~= nil) then
                                accessxi.chat_log_remember_apururu_defeated_line(entry.text);
                            end
                        end
                    end
                end
            end
        end
        if (first_line) then
            valid = legacy;
        end
        local closed = f:close();
        if (closed == nil) then
            valid = false;
        end
        return added, parsed, valid;
    end

    accessxi.chat_history_cache_load_handled = true;
    local legacy = false;
    local added = 0;
    local parsed = {};
    local valid = false;
    local needs_write = false;
    local f = io.open(accessxi.chat_history_path, 'r');
    if (f ~= nil) then
        added, parsed, valid = parse_cache_file(f, false);
        if (not valid) then
            needs_write = true;
            local preserved = accessxi.chat_history_preserve_invalid_cache();
            local legacy_file = io.open(accessxi.chat_history_legacy_path, 'r');
            if (legacy_file ~= nil) then
                legacy = true;
                added, parsed, valid = parse_cache_file(legacy_file, true);
            else
                added = 0;
                parsed = {};
                valid = preserved;
            end
        end
    else
        needs_write = true;
        local legacy_file = io.open(accessxi.chat_history_legacy_path, 'r');
        if (legacy_file ~= nil) then
            legacy = true;
            added, parsed, valid = parse_cache_file(legacy_file, true);
        else
            valid = true;
        end
    end

    local keep = math.min(added, max_history);
    local start = added - keep + 1;
    for i = start, added do
        local entry = parsed[((i - 1) % max_history) + 1];
        if (entry ~= nil) then
            accessxi.chat_history:append(entry);
        end
    end

    accessxi.chat_history_cache_ready = not legacy and valid;
    if (needs_write or legacy or not valid or added > max_history) then
        accessxi.chat_history_cache_ready = accessxi.chat_history_write_cache();
    end
    return added;
end

accessxi.seed_chat_history_from_log = function ()
    if (accessxi.chat_history_seeded == true) then
        return;
    end
    accessxi.chat_history_seeded = true;

    local cached = accessxi.chat_history_load_cache();
    if (accessxi.chat_history_cache_load_handled == true) then
        accessxi.chat_history_rebuild_positions();
        log_state(('state chatlog history-cache-seeded lines=%d total=%d'):fmt(cached, accessxi.chat_history:len()));
        return;
    end

    local f = io.open(accessxi.log_path, 'r');
    if (f == nil) then
        return;
    end

    local max_history = math.max(100, tonumber(accessxi.chat_history_max) or 1000);
    local parsed = {};
    local added = 0;
    for line in f:lines() do
        local mode_text, label, text = line:match('chat text mode=(%-?%d+) label="([^"]*)" "(.*)"%s*$');
        local entry = accessxi.chat_history_entry(mode_text, label, text);
        if (entry ~= nil) then
            added = added + 1;
            local slot = ((added - 1) % max_history) + 1;
            parsed[slot] = entry;
            if (accessxi.chat_log_remember_apururu_defeated_line ~= nil) then
                accessxi.chat_log_remember_apururu_defeated_line(entry.text);
            end
        end
    end
    f:close();

    local keep = math.min(added, max_history);
    local start = added - keep + 1;
    for i = start, added do
        local slot = ((i - 1) % max_history) + 1;
        if (parsed[slot] ~= nil) then
            accessxi.chat_history:append(parsed[slot]);
        end
    end
    accessxi.chat_history_rebuild_positions();
    accessxi.chat_history_write_cache();
    if (added > 0) then
        log_state(('state chatlog history-seeded lines=%d total=%d'):fmt(added, accessxi.chat_history:len()));
    end
end

accessxi.chat_mode_label = function (mode)
    local mid = bit.band(tonumber(mode) or 0, 0xFF);
    local info = accessxi.chat_mode_metadata[mid];
    if (info ~= nil) then
        return tostring(info.label or 'Chat');
    end
    return 'Chat';
end

accessxi.chat_reader_data = accessxi.load_menu_module_table('chat_log', T{ categories = T{} });
accessxi.chat_reader_categories = accessxi.chat_reader_data.categories or T{};

accessxi.chat_reader_category_key = function (mode, text)
    local mid = bit.band(tonumber(mode) or 0, 0xFF);
    local info = accessxi.chat_mode_metadata[mid];
    if (info ~= nil) then
        return tostring(info.category or 'other');
    end
    return 'other';
end

accessxi.chat_reader_category = function ()
    local categories = accessxi.chat_reader_categories or T{};
    if (categories:len() == 0) then
        return T{ key = 'all', label = 'All' };
    end
    accessxi.chat_reader_category_index = math.max(1, math.min(tonumber(accessxi.chat_reader_category_index) or 1, categories:len()));
    return categories[accessxi.chat_reader_category_index] or categories[1];
end

accessxi.chat_reader_entries = function (category_key)
    category_key = tostring(category_key or 'all');
    local entries = T{};
    for _, entry in ipairs(accessxi.chat_history or T{}) do
        if (category_key == 'all'
            or tostring(entry.category or '') == category_key) then
            entries:append(entry);
        end
    end
    return entries;
end

accessxi.chat_reader_entry_speech = function (category, entries, index, prefix, message_only)
    category = category or T{ key = 'all', label = 'All' };
    entries = entries or T{};
    local count = entries:len();
    if (count == 0) then
        return ('%s log empty.'):fmt(category.label or 'Chat');
    end

    index = math.max(1, math.min(tonumber(index) or count, count));
    local line = accessxi.chat_entry_speech(entries[index], tostring(category.key or 'all') == 'all');
    if (line == '') then
        line = 'Blank line.';
    end
    if (message_only == true) then
        return accessxi.chat_message_speech(line);
    end
    if (prefix ~= nil and prefix ~= '') then
        return ('%s. %s log. %d of %d. %s'):fmt(prefix, category.label or 'Chat', index, count, line);
    end
    return ('%s log. %d of %d. %s'):fmt(category.label or 'Chat', index, count, line);
end

accessxi.chat_reader_current_position = function (category_key, count)
    count = tonumber(count) or 0;
    if (count <= 0) then
        accessxi.chat_reader_positions[category_key] = 0;
        return 0;
    end

    local pos = tonumber(accessxi.chat_reader_positions[category_key]) or count;
    pos = math.max(1, math.min(pos, count));
    accessxi.chat_reader_positions[category_key] = pos;
    return pos;
end

accessxi.chat_reader_update_for_new_entry = function (entry)
    if (entry == nil) then
        return;
    end

    local affected = T{ 'all', tostring(entry.category or 'other') };
    for _, key in ipairs(affected) do
        local entries = accessxi.chat_reader_entries(key);
        local new_count = entries:len();
        local old_count = math.max(0, new_count - 1);
        local pos = tonumber(accessxi.chat_reader_positions[key]) or 0;
        if (pos == 0 or pos >= old_count) then
            accessxi.chat_reader_positions[key] = new_count;
        end
    end
end

accessxi.chat_reader_switch_category = function (delta)
    local categories = accessxi.chat_reader_categories or T{};
    local count = categories:len();
    if (count == 0) then
        return 'No chat categories.';
    end

    local index = (tonumber(accessxi.chat_reader_category_index) or 1) + (tonumber(delta) or 0);
    while (index < 1) do
        index = index + count;
    end
    while (index > count) do
        index = index - count;
    end
    accessxi.chat_reader_category_index = index;

    local category = accessxi.chat_reader_category();
    local entries = accessxi.chat_reader_entries(category.key);
    local pos = accessxi.chat_reader_current_position(category.key, entries:len());
    return accessxi.chat_reader_entry_speech(category, entries, pos, 'Category');
end

accessxi.chat_reader_move = function (delta)
    local category = accessxi.chat_reader_category();
    local entries = accessxi.chat_reader_entries(category.key);
    local count = entries:len();
    if (count == 0) then
        accessxi.chat_reader_positions[category.key] = 0;
        return ('%s log empty.'):fmt(category.label or 'Chat');
    end

    local had_position = (tonumber(accessxi.chat_reader_positions[category.key]) or 0) > 0;
    local pos = accessxi.chat_reader_current_position(category.key, count);
    local next_pos = had_position and (pos + (tonumber(delta) or 0)) or pos;
    local prefix = '';
    if (next_pos < 1) then
        next_pos = 1;
        prefix = 'Top';
    elseif (next_pos > count) then
        next_pos = count;
        prefix = 'Bottom';
    end

    accessxi.chat_reader_positions[category.key] = next_pos;
    return accessxi.chat_reader_entry_speech(category, entries, next_pos, prefix, true);
end

accessxi.chat_reader_native_log_open = function ()
    local menu_name = tostring(get_menu_name() or '');
    return menu_name:eq('menu    logwindo', true)
        or menu_name:eq('menu    fulllog', true)
        or menu_name:find('menu    logwin2', 1, true) == 1;
end

accessxi.chat_reader_handle_key = function (key)
    key = tonumber(key) or 0;
    if (key ~= 0x24 and key ~= 0x23 and key ~= 0x21 and key ~= 0x22) then
        return false;
    end

    if (accessxi.chat_reader_keys_armed ~= true) then
        return true;
    end
    -- One press owns the complete four-key chord until every reader key is up.
    -- Suppression gates must not re-arm a key that is still physically held.
    accessxi.chat_reader_keys_armed = false;
    accessxi.chat_reader_last_key = key;

    if (not accessxi.is_foreground_process()) then
        return false;
    end

    if (is_chat_input_open()) then
        return false;
    end

    if (accessxi.chat_reader_native_log_open()) then
        return false;
    end

    local text = '';
    if (key == 0x24) then
        text = accessxi.chat_reader_switch_category(-1);
    elseif (key == 0x23) then
        text = accessxi.chat_reader_switch_category(1);
    elseif (key == 0x21) then
        text = accessxi.chat_reader_move(-1);
    elseif (key == 0x22) then
        text = accessxi.chat_reader_move(1);
    end

    if (text ~= '') then
        speak(text, true);
        log_line(('chat reader %s'):fmt(text));
    end
    return true;
end

accessxi.poll_chat_reader_hotkeys = function ()
    local key = 0;
    if (bit.band(kernel32.GetAsyncKeyState(0x24), 0x8000) ~= 0) then
        key = 0x24;
    elseif (bit.band(kernel32.GetAsyncKeyState(0x23), 0x8000) ~= 0) then
        key = 0x23;
    elseif (bit.band(kernel32.GetAsyncKeyState(0x21), 0x8000) ~= 0) then
        key = 0x21;
    elseif (bit.band(kernel32.GetAsyncKeyState(0x22), 0x8000) ~= 0) then
        key = 0x22;
    end

    if (key == 0) then
        accessxi.chat_reader_last_key = 0;
        accessxi.chat_reader_keys_armed = true;
        return;
    end

    if (not accessxi.is_foreground_process()
        or is_chat_input_open()
        or accessxi.chat_reader_native_log_open()) then
        accessxi.chat_reader_last_key = key;
        accessxi.chat_reader_keys_armed = false;
        return;
    end

    accessxi.chat_reader_handle_key(key);
end

accessxi.chat_should_speak = function (mode, text)
    if (not accessxi.chat_speak_enabled) then
        return false;
    end

    local mid = bit.band(tonumber(mode) or 0, 0xFF);
    if (mid == 150 or mid == 151) then
        return false;
    end

    if (text == '' or text:contains('[AccessXI]', true)) then
        return false;
    end

    return true;
end

accessxi.chat_add_history = function (mode, text, injected)
    if (injected == true) then
        return nil;
    end
    text = accessxi.clean_incoming_text(text);
    if (text == '') then
        return nil;
    end
    if (accessxi.chat_log_remember_apururu_defeated_line ~= nil) then
        accessxi.chat_log_remember_apururu_defeated_line(text);
    end

    local entry = T{
        tick = tick(),
        mode = bit.band(tonumber(mode) or 0, 0xFF),
        label = accessxi.chat_mode_label(mode),
        category = accessxi.chat_reader_category_key(mode, text),
        text = text,
    };
    accessxi.chat_history:append(entry);
    while (accessxi.chat_history:len() > (tonumber(accessxi.chat_history_max) or 60)) do
        table.remove(accessxi.chat_history, 1);
    end
    accessxi.chat_history_append_cache(entry);
    if (accessxi.chat_reader_update_for_new_entry ~= nil) then
        accessxi.chat_reader_update_for_new_entry(entry);
    end
    return entry;
end

accessxi.chat_entry_speech = function (entry, include_label)
    if (entry == nil or entry.text == nil or entry.text == '') then
        return '';
    end

    local label = clean_login_text(entry.label or 'Chat');
    local text = accessxi.speech_name(entry.text);
    if (include_label == false or label == '' or label == 'Chat') then
        return text;
    end
    return ('%s. %s'):fmt(label, text);
end

accessxi.chat_history_speech = function (count)
    count = math.max(1, math.min(tonumber(count) or 5, 20));
    if (accessxi.chat_history:len() == 0) then
        return 'No chat lines captured yet.';
    end

    local parts = T{};
    local start_index = math.max(1, accessxi.chat_history:len() - count + 1);
    for i = start_index, accessxi.chat_history:len() do
        local text = accessxi.chat_entry_speech(accessxi.chat_history[i]);
        if (text ~= '') then
            parts:append(text);
        end
    end

    if (parts:len() == 0) then
        return 'No chat lines captured yet.';
    end
    return ('Last %d chat lines. %s.'):fmt(parts:len(), parts:concat('. '));
end

function accessxi.combat_is_combat_mode(mode)
    local mid = bit.band(tonumber(mode) or 0, 0xFF);
    return mid == 121 or mid == 122 or mid == 123;
end

function accessxi.combat_clean_name(name)
    name = accessxi.speech_name(clean_login_text(name or ''));
    name = tostring(name or ''):gsub('%s+', ' '):trim();
    return name;
end

function accessxi.combat_name_key(name)
    name = accessxi.combat_clean_name(name);
    name = name:lower():gsub('^the%s+', ''):gsub('^an%s+', ''):gsub('^a%s+', '');
    name = name:gsub('[^%w]+', ' '):gsub('%s+', ' '):trim();
    return name;
end

function accessxi.combat_name_matches(left, right)
    local left_key = accessxi.combat_name_key(left);
    local right_key = accessxi.combat_name_key(right);
    return left_key ~= '' and right_key ~= '' and left_key == right_key;
end

function accessxi.combat_player_name()
    local mm = safe_call(function () return AshitaCore:GetMemoryManager(); end, nil);
    local party = mm ~= nil and safe_call(function () return mm:GetParty(); end, nil) or nil;
    local name = party ~= nil and safe_call(function () return party:GetMemberName(0); end, '') or '';
    return accessxi.combat_clean_name(name);
end

function accessxi.combat_player_server_id()
    local entity = safe_call(function () return GetPlayerEntity(); end, nil);
    local server_id = entity ~= nil and (tonumber(entity.ServerId) or 0) or 0;
    if (server_id > 0) then
        return server_id;
    end

    local mm = safe_call(function () return AshitaCore:GetMemoryManager(); end, nil);
    local party = mm ~= nil and safe_call(function () return mm:GetParty(); end, nil) or nil;
    server_id = party ~= nil and (tonumber(safe_call(function () return party:GetMemberServerId(0); end, 0)) or 0) or 0;
    if (server_id > 0) then
        return server_id;
    end

    local target_index = party ~= nil and (tonumber(safe_call(function () return party:GetMemberTargetIndex(0); end, 0)) or 0) or 0;
    local entity_manager = mm ~= nil and safe_call(function () return mm:GetEntity(); end, nil) or nil;
    if (entity_manager ~= nil and target_index > 0) then
        return tonumber(safe_call(function () return entity_manager:GetServerId(target_index); end, 0)) or 0;
    end

    return 0;
end

function accessxi.combat_target_name()
    local mm = safe_call(function () return AshitaCore:GetMemoryManager(); end, nil);
    local target = mm ~= nil and safe_call(function () return mm:GetTarget(); end, nil) or nil;
    local name = target ~= nil and safe_call(function () return target:GetWindowName(); end, '') or '';
    return accessxi.combat_clean_name(name);
end

function accessxi.combat_current_target_server_id()
    local mm = safe_call(function () return AshitaCore:GetMemoryManager(); end, nil);
    local target = mm ~= nil and safe_call(function () return mm:GetTarget(); end, nil) or nil;
    if (target == nil) then
        return 0;
    end

    local server_id = tonumber(safe_call(function () return target:GetFocusTargetServerId(); end, 0)) or 0;
    if (server_id > 0) then
        return server_id;
    end

    server_id = tonumber(safe_call(function () return target:GetWindowServerId(); end, 0)) or 0;
    if (server_id > 0) then
        return server_id;
    end

    return 0;
end

function accessxi.combat_player_hp_summary()
    local mm = safe_call(function () return AshitaCore:GetMemoryManager(); end, nil);
    if (mm == nil) then
        return '', -1, -1, -1;
    end

    local party = safe_call(function () return mm:GetParty(); end, nil);
    local player = safe_call(function () return mm:GetPlayer(); end, nil);
    local hp = party ~= nil and (tonumber(safe_call(function () return party:GetMemberHP(0); end, -1)) or -1) or -1;
    local max_hp = player ~= nil and (tonumber(safe_call(function () return player:GetHPMax(); end, -1)) or -1) or -1;
    local percent = -1;

    if (party ~= nil) then
        percent = tonumber(safe_call(function () return party:GetMemberHPPercent(0); end, -1)) or -1;
        if (percent < 0 or percent > 100) then
            percent = tonumber(safe_call(function () return party:GetMemberHPP(0); end, -1)) or -1;
        end
    end
    if ((percent < 0 or percent > 100) and hp >= 0 and max_hp > 0) then
        percent = math.floor(((hp * 100) / max_hp) + 0.5);
    end
    if (percent < 0 or percent > 100) then
        return '', hp, max_hp, -1;
    end

    return ('HP %d percent'):fmt(percent), hp, max_hp, percent;
end

function accessxi.combat_target_hp_summary()
    local mm = safe_call(function () return AshitaCore:GetMemoryManager(); end, nil);
    if (mm == nil) then
        return '', -1;
    end

    local target = safe_call(function () return mm:GetTarget(); end, nil);
    local percent = target ~= nil and (tonumber(safe_call(function () return target:GetWindowHPPercent(); end, -1)) or -1) or -1;
    if (percent < 0 or percent > 100) then
        return '', -1;
    end
    return ('Target %d percent'):fmt(percent), percent;
end

function accessxi.combat_entity_hp_summary_for_server(server_id)
    server_id = tonumber(server_id) or 0;
    if (server_id <= 0) then
        return '', -1, '';
    end

    if (server_id == accessxi.combat_current_target_server_id()) then
        local summary, percent = accessxi.combat_target_hp_summary();
        if (summary ~= '') then
            return summary, percent, accessxi.combat_target_name();
        end
    end

    local mm = safe_call(function () return AshitaCore:GetMemoryManager(); end, nil);
    local entity = mm ~= nil and safe_call(function () return mm:GetEntity(); end, nil) or nil;
    if (entity == nil) then
        return '', -1, '';
    end

    local size = tonumber(safe_call(function () return entity:GetEntityMapSize(); end, 0)) or 0;
    for index = 0, math.min(size - 1, 2303) do
        local candidate_id = tonumber(safe_call(function () return entity:GetServerId(index); end, 0)) or 0;
        if (candidate_id == server_id) then
            local percent = tonumber(safe_call(function () return entity:GetHPPercent(index); end, -1)) or -1;
            local name = accessxi.combat_clean_name(safe_call(function () return entity:GetName(index); end, ''));
            if (percent >= 0 and percent <= 100) then
                return ('Target %d percent'):fmt(percent), percent, name;
            end
            return '', -1, name;
        end
    end

    return '', -1, '';
end

function accessxi.combat_damage_amount_patterns(text)
    text = tostring(text or '');
    local actor, target, amount = text:match('^(.+) hits (.+) for (%d+) points of damage%.$');
    if (actor == nil) then
        actor, target, amount = text:match('^(.+) hits (.+) for (%d+) point of damage%.$');
    end
    if (actor ~= nil and target ~= nil and amount ~= nil) then
        return accessxi.combat_clean_name(actor), accessxi.combat_clean_name(target), tonumber(amount) or 0, 'hit';
    end

    local damaged, taken = text:match('^(.+) takes (%d+) points of damage%.$');
    if (damaged == nil) then
        damaged, taken = text:match('^(.+) takes (%d+) point of damage%.$');
    end
    if (damaged ~= nil and taken ~= nil) then
        return '', accessxi.combat_clean_name(damaged), tonumber(taken) or 0, 'takes';
    end

    return '', '', 0, '';
end

function accessxi.combat_damage_speech(entry)
    if (entry == nil or not accessxi.combat_is_combat_mode(entry.mode)) then
        return nil;
    end

    local text = accessxi.clean_incoming_text(entry.text or '');
    if (text == '') then
        return nil;
    end

    local actor, target, amount, kind = accessxi.combat_damage_amount_patterns(text);
    if (amount <= 0 or kind == '') then
        return nil;
    end

    local player_name = accessxi.combat_player_name();
    local target_name = accessxi.combat_target_name();
    local actor_is_player = accessxi.combat_name_matches(actor, player_name) or accessxi.combat_name_key(actor) == 'you';
    local target_is_player = accessxi.combat_name_matches(target, player_name) or accessxi.combat_name_key(target) == 'you';
    local target_is_current = accessxi.combat_name_matches(target, target_name);
    local speech = '';
    local target_hp = '';
    local player_hp = '';

    if (actor_is_player) then
        if (target_is_current) then
            target_hp = accessxi.combat_target_hp_summary();
        end
        speech = ('You deal %d damage'):fmt(amount);
        if (target_hp ~= '') then
            speech = ('%s. %s'):fmt(speech, target_hp);
        elseif (target ~= '') then
            speech = ('%s to %s'):fmt(speech, target);
        end
    elseif (target_is_player) then
        player_hp = accessxi.combat_player_hp_summary();
        speech = ('You take %d damage'):fmt(amount);
        if (player_hp ~= '') then
            speech = ('%s. %s'):fmt(speech, player_hp);
        end
    elseif (kind == 'takes' and target_is_current) then
        target_hp = accessxi.combat_target_hp_summary();
        speech = ('Target takes %d damage'):fmt(amount);
        if (target_hp ~= '') then
            speech = ('%s. %s'):fmt(speech, target_hp);
        end
    else
        return nil;
    end

    log_state(('state combat feedback mode=%d text="%s" speech="%s" player="%s" target="%s" actor="%s" damaged="%s" amount=%d targetHp="%s" playerHp="%s"'):fmt(
        tonumber(entry.mode) or 0,
        accessxi.escape_probe_log_text(text),
        accessxi.escape_probe_log_text(speech),
        accessxi.escape_probe_log_text(player_name),
        accessxi.escape_probe_log_text(target_name),
        accessxi.escape_probe_log_text(actor),
        accessxi.escape_probe_log_text(target),
        amount,
        accessxi.escape_probe_log_text(target_hp),
        accessxi.escape_probe_log_text(player_hp)));

    return speech;
end

function accessxi.combat_action_parse(data)
    if (type(data) ~= 'string' or #data < 24) then
        return nil, 'short';
    end

    local total_bits = #data * 8;
    local bitpos = 8 * 5;
    local function read_bits(width)
        width = tonumber(width) or 0;
        if (width <= 0 or (bitpos + width) > total_bits) then
            return nil;
        end
        local value = accessxi.packet_bits_le(data, bitpos, width);
        bitpos = bitpos + width;
        return value;
    end

    local action = T{};
    action.m_uID = read_bits(32);
    action.trg_sum = read_bits(6);
    action.res_sum = read_bits(4);
    action.cmd_no = read_bits(4);
    action.cmd_arg = read_bits(32);
    action.info = read_bits(32);
    if (action.trg_sum == nil or action.res_sum == nil or action.cmd_no == nil or action.cmd_arg == nil or action.info == nil) then
        return nil, 'truncated-header';
    end

    action.target = T{};
    for _ = 1, math.min(tonumber(action.trg_sum) or 0, 15) do
        local target = T{};
        target.m_uID = read_bits(32);
        target.result_sum = read_bits(4);
        if (target.m_uID == nil or target.result_sum == nil) then
            return nil, 'truncated-target';
        end

        target.result = T{};
        for _ = 1, math.min(tonumber(target.result_sum) or 0, 8) do
            local result = T{};
            result.miss = read_bits(3);
            result.kind = read_bits(2);
            result.sub_kind = read_bits(12);
            result.info = read_bits(5);
            result.scale = read_bits(5);
            result.value = read_bits(17);
            result.message = read_bits(10);
            result.bit = read_bits(31);
            if (result.miss == nil or result.kind == nil or result.sub_kind == nil or result.info == nil or result.scale == nil or result.value == nil or result.message == nil or result.bit == nil) then
                return nil, 'truncated-result';
            end

            result.has_proc = (read_bits(1) or 0) > 0;
            if (result.has_proc) then
                result.proc_kind = read_bits(6);
                result.proc_info = read_bits(4);
                result.proc_value = read_bits(17);
                result.proc_message = read_bits(10);
                if (result.proc_kind == nil or result.proc_info == nil or result.proc_value == nil or result.proc_message == nil) then
                    return nil, 'truncated-proc';
                end
            else
                result.proc_kind = 0;
                result.proc_info = 0;
                result.proc_value = 0;
                result.proc_message = 0;
            end

            result.has_react = (read_bits(1) or 0) > 0;
            if (result.has_react) then
                result.react_kind = read_bits(6);
                result.react_info = read_bits(4);
                result.react_value = read_bits(14);
                result.react_message = read_bits(10);
                if (result.react_kind == nil or result.react_info == nil or result.react_value == nil or result.react_message == nil) then
                    return nil, 'truncated-react';
                end
            else
                result.react_kind = 0;
                result.react_info = 0;
                result.react_value = 0;
                result.react_message = 0;
            end

            target.result:append(result);
        end

        action.target:append(target);
    end

    return action, '';
end

function accessxi.combat_action_result_is_damage(result)
    if (result == nil) then
        return false;
    end

    local message = tonumber(result.message) or 0;
    local amount = tonumber(result.value) or 0;
    local miss = tonumber(result.miss) or 0;
    return miss == 0 and amount > 0 and (message == 1 or message == 67);
end

function accessxi.combat_action_packet_speech(action)
    if (action == nil or action.cmd_no ~= 1) then
        return nil, nil;
    end

    local player_id = accessxi.combat_player_server_id();
    if (player_id <= 0) then
        return nil, nil;
    end

    local actor_id = tonumber(action.m_uID) or 0;
    local outgoing_amount = 0;
    local incoming_amount = 0;
    local outgoing_target = 0;
    local incoming_actor = 0;
    local first_message = 0;

    for _, target in ipairs(action.target or T{}) do
        local target_id = tonumber(target.m_uID) or 0;
        for _, result in ipairs(target.result or T{}) do
            if (accessxi.combat_action_result_is_damage(result)) then
                first_message = first_message ~= 0 and first_message or (tonumber(result.message) or 0);
                if (actor_id == player_id and target_id ~= player_id) then
                    outgoing_amount = outgoing_amount + (tonumber(result.value) or 0);
                    outgoing_target = outgoing_target ~= 0 and outgoing_target or target_id;
                elseif (target_id == player_id and actor_id ~= player_id) then
                    incoming_amount = incoming_amount + (tonumber(result.value) or 0);
                    incoming_actor = incoming_actor ~= 0 and incoming_actor or actor_id;
                end
            end
        end
    end

    local now = tick();
    if (outgoing_amount > 0) then
        local speech = ('You deal %d damage'):fmt(outgoing_amount);

        local key = ('out:%d:%d:%d'):fmt(actor_id, outgoing_target, outgoing_amount);
        if (key == (accessxi.combat_last_packet_damage_key or '') and (now - (tonumber(accessxi.combat_last_packet_damage_tick) or 0)) < 250) then
            return nil, nil;
        end
        accessxi.combat_last_packet_damage_key = key;
        accessxi.combat_last_packet_damage_tick = now;
        return speech, T{
            direction = 'outgoing',
            actor_id = actor_id,
            target_id = outgoing_target,
            amount = outgoing_amount,
            message = first_message,
            target_hp = '',
            target_percent = -1,
            target_name = '',
            player_hp = '',
            player_percent = -1,
        };
    end

    if (incoming_amount > 0) then
        local speech = ('You take %d damage'):fmt(incoming_amount);

        local key = ('in:%d:%d:%d'):fmt(incoming_actor, player_id, incoming_amount);
        if (key == (accessxi.combat_last_packet_damage_key or '') and (now - (tonumber(accessxi.combat_last_packet_damage_tick) or 0)) < 250) then
            return nil, nil;
        end
        accessxi.combat_last_packet_damage_key = key;
        accessxi.combat_last_packet_damage_tick = now;
        return speech, T{
            direction = 'incoming',
            actor_id = incoming_actor,
            target_id = player_id,
            amount = incoming_amount,
            message = first_message,
            target_hp = '',
            target_percent = -1,
            target_name = '',
            player_hp = '',
            player_percent = -1,
        };
    end

    return nil, nil;
end

function accessxi.queue_combat_action_feedback(speech, detail, action)
    if (speech == nil or speech == '' or detail == nil) then
        return;
    end

    local target_hp_before = '';
    local target_percent_before = -1;
    local target_name_before = '';
    if (detail.direction == 'outgoing') then
        target_hp_before, target_percent_before, target_name_before = accessxi.combat_entity_hp_summary_for_server(detail.target_id);
    end

    accessxi.combat_pending_action_feedback = accessxi.combat_pending_action_feedback or {};
    table.insert(accessxi.combat_pending_action_feedback, T{
        speech = speech,
        detail = detail,
        cmd_no = tonumber(action ~= nil and action.cmd_no or 0) or 0,
        ready_tick = tick() + 80,
        hp_ready_tick = tick() + 650,
        hp_deadline_tick = tick() + 1800,
        damage_spoken = false,
        hp_done = detail.direction ~= 'outgoing',
        target_hp_before = target_hp_before or '',
        target_percent_before = tonumber(target_percent_before) or -1,
        target_name_before = target_name_before or '',
    });
end

function accessxi.speak_combat_action_feedback(item)
    if (item == nil or item.detail == nil) then
        return;
    end

    local detail = item.detail;
    local speech = tostring(item.speech or '');
    if (detail.direction == 'outgoing') then
        detail.target_hp = '';
        detail.target_percent = -1;
        detail.target_name = item.target_name_before or detail.target_name or '';
    elseif (detail.direction == 'incoming') then
        local player_hp, _, _, player_percent = accessxi.combat_player_hp_summary();
        detail.player_hp = player_hp;
        detail.player_percent = player_percent;
        if (player_hp ~= '') then
            speech = ('%s. %s'):fmt(speech, player_hp);
        end
    end

    log_state(('state combat action feedback direction=%s actor=0x%08X target=0x%08X cmd=%d amount=%d message=%d speech="%s" targetName="%s" targetHp="%s" targetPercent=%d playerHp="%s" playerPercent=%d'):fmt(
        tostring(detail.direction or ''),
        tonumber(detail.actor_id) or 0,
        tonumber(detail.target_id) or 0,
        tonumber(item.cmd_no) or 0,
        tonumber(detail.amount) or 0,
        tonumber(detail.message) or 0,
        accessxi.escape_probe_log_text(speech),
        accessxi.escape_probe_log_text(detail.target_name or ''),
        accessxi.escape_probe_log_text(detail.target_hp or ''),
        tonumber(detail.target_percent) or -1,
        accessxi.escape_probe_log_text(detail.player_hp or ''),
        tonumber(detail.player_percent) or -1));
    speak(speech, false);
end

function accessxi.speak_combat_action_target_hp_feedback(item)
    if (item == nil or item.detail == nil or item.detail.direction ~= 'outgoing') then
        return true, false;
    end

    local now = tick();
    local detail = item.detail;
    local target_hp, target_percent, target_name = accessxi.combat_entity_hp_summary_for_server(detail.target_id);
    target_percent = tonumber(target_percent) or -1;
    local before_percent = tonumber(item.target_percent_before) or -1;

    if (target_hp == '' or target_percent < 0 or target_percent > 100) then
        if (now < (tonumber(item.hp_deadline_tick) or 0)) then
            return false, false;
        end
        log_state(('state combat action target hp skipped reason="missing" actor=0x%08X target=0x%08X amount=%d beforePercent=%d'):fmt(
            tonumber(detail.actor_id) or 0,
            tonumber(detail.target_id) or 0,
            tonumber(detail.amount) or 0,
            before_percent));
        return true, false;
    end

    if (before_percent >= 0 and target_percent == before_percent) then
        if (now < (tonumber(item.hp_deadline_tick) or 0)) then
            return false, false;
        end
        log_state(('state combat action target hp skipped reason="unchanged" actor=0x%08X target=0x%08X amount=%d beforePercent=%d targetPercent=%d targetName="%s"'):fmt(
            tonumber(detail.actor_id) or 0,
            tonumber(detail.target_id) or 0,
            tonumber(detail.amount) or 0,
            before_percent,
            target_percent,
            accessxi.escape_probe_log_text(target_name or item.target_name_before or '')));
        return true, false;
    end

    detail.target_hp = target_hp;
    detail.target_percent = target_percent;
    detail.target_name = target_name or item.target_name_before or '';
    log_state(('state combat action target hp feedback actor=0x%08X target=0x%08X amount=%d beforePercent=%d targetPercent=%d targetName="%s" speech="%s"'):fmt(
        tonumber(detail.actor_id) or 0,
        tonumber(detail.target_id) or 0,
        tonumber(detail.amount) or 0,
        before_percent,
        target_percent,
        accessxi.escape_probe_log_text(detail.target_name or ''),
        accessxi.escape_probe_log_text(target_hp)));
    speak(target_hp, false);
    return true, true;
end

function accessxi.poll_combat_action_feedback()
    local queue = accessxi.combat_pending_action_feedback;
    if (queue == nil or #queue == 0) then
        return false;
    end

    local now = tick();
    local remaining = {};
    local spoke = false;
    for _, item in ipairs(queue) do
        if (not item.damage_spoken and (tonumber(item.ready_tick) or 0) <= now and not spoke) then
            accessxi.speak_combat_action_feedback(item);
            item.damage_spoken = true;
            spoke = true;
        end

        if (item.damage_spoken and not item.hp_done and (tonumber(item.hp_ready_tick) or 0) <= now and not spoke) then
            local done, hp_spoke = accessxi.speak_combat_action_target_hp_feedback(item);
            item.hp_done = done;
            spoke = hp_spoke or spoke;
        end

        local keep = false;
        if (not item.damage_spoken) then
            keep = ((tonumber(item.ready_tick) or 0) + 3000) >= now;
        elseif (not item.hp_done) then
            keep = ((tonumber(item.hp_deadline_tick) or 0) + 1000) >= now;
        end
        if (keep) then
            table.insert(remaining, item);
        end
    end
    accessxi.combat_pending_action_feedback = remaining;
    return spoke;
end

function accessxi.log_combat_action_diag(action, data, reason)
    accessxi.combat_action_diag_count = tonumber(accessxi.combat_action_diag_count) or 0;
    if (accessxi.combat_action_diag_count >= 32) then
        return;
    end

    local player_id = accessxi.combat_player_server_id();
    local current_target_id = accessxi.combat_current_target_server_id();
    local actor_id = tonumber(action ~= nil and action.m_uID or 0) or 0;
    local cmd_no = tonumber(action ~= nil and action.cmd_no or 0) or 0;
    local trg_sum = tonumber(action ~= nil and action.trg_sum or 0) or 0;
    local first_target = nil;
    if (action ~= nil and action.target ~= nil) then
        first_target = action.target[1];
    end
    local first_target_id = tonumber(first_target ~= nil and first_target.m_uID or 0) or 0;
    local result_sum = tonumber(first_target ~= nil and first_target.result_sum or 0) or 0;
    local first_result = nil;
    if (first_target ~= nil and first_target.result ~= nil) then
        first_result = first_target.result[1];
    end
    local miss = tonumber(first_result ~= nil and first_result.miss or 0) or 0;
    local kind = tonumber(first_result ~= nil and first_result.kind or 0) or 0;
    local value = tonumber(first_result ~= nil and first_result.value or 0) or 0;
    local message = tonumber(first_result ~= nil and first_result.message or 0) or 0;

    local should_log = cmd_no == 1
        or player_id == actor_id
        or player_id == first_target_id
        or current_target_id == actor_id
        or current_target_id == first_target_id
        or accessxi.combat_action_diag_count < 8;
    if (not should_log) then
        return;
    end

    accessxi.combat_action_diag_count = accessxi.combat_action_diag_count + 1;
    log_state(('state combat action diag reason="%s" player=0x%08X current=0x%08X actor=0x%08X cmd=%d trgSum=%d firstTarget=0x%08X resultSum=%d miss=%d kind=%d value=%d message=%d len=%d hex="%s"'):fmt(
        accessxi.escape_probe_log_text(reason or ''),
        player_id,
        current_target_id,
        actor_id,
        cmd_no,
        trg_sum,
        first_target_id,
        result_sum,
        miss,
        kind,
        value,
        message,
        #(data or ''),
        accessxi.packet_hex_limit(data, 48)));
end

function accessxi.capture_combat_action_packet(e)
    if (e == nil) then
        return;
    end

    local packet_id = tonumber(e.id) or -1;
    if (packet_id == 0x029) then
        local data = e.data_modified or e.data
            or accessxi.packet_event_string(e, 'data_modified', 'size')
            or accessxi.packet_event_string(e, 'data', 'size') or '';
        if (#data < 0x1A) then return; end
        local actor_server_id = accessxi.packet_u32(data, 0x04 + 1);
        local target_server_id = accessxi.packet_u32(data, 0x08 + 1);
        local actor_index = accessxi.packet_u16(data, 0x14 + 1);
        local target_index = accessxi.packet_u16(data, 0x16 + 1);
        local message_id = accessxi.packet_u16(data, 0x18 + 1) % 0x8000;
        if ((message_id ~= 6 and message_id ~= 97)
            or actor_server_id <= 0 or target_server_id <= 0) then
            return;
        end
        local actor_ok, actor_kind = false, '';
        if (type(accessxi.combat_actor_is_local_or_party) == 'function') then
            actor_ok, actor_kind = accessxi.combat_actor_is_local_or_party(
                actor_server_id);
        end
        if (actor_ok ~= true) then return; end
        local target_name = '';
        if (type(accessxi.combat_entity_hp_summary_for_server) == 'function') then
            local _, _, name = accessxi.combat_entity_hp_summary_for_server(
                target_server_id);
            target_name = tostring(name or '');
        end
        if (target_name == '' or target_name:lower() == 'unknown') then return; end
        local identity = tostring(accessxi.current_player_identity() or ''):lower();
        local world_id = tonumber(accessxi.current_player_world_id()) or 0;
        local session_epoch = tonumber(accessxi.current_objective_session_epoch()) or 0;
        if (identity == '' or world_id <= 0 or session_epoch <= 0) then return; end
        local now = tick();
        local replay_key = table.concat({ tostring(session_epoch),
            tostring(actor_server_id), tostring(target_server_id),
            tostring(actor_index), tostring(target_index), tostring(message_id) }, ':');
        if (replay_key == tostring(accessxi.objective_kill_replay_key or '')
            and (now - (tonumber(accessxi.objective_kill_replay_tick) or 0)) < 2000) then
            return;
        end
        if (tonumber(accessxi.objective_signal_session_epoch) ~= session_epoch) then
            accessxi.objective_signal_session_epoch = session_epoch;
            accessxi.objective_signal_sequence = 0;
        end
        local sequence = (tonumber(accessxi.objective_signal_sequence) or 0) + 1;
        accessxi.objective_signal_sequence = sequence;
        local zone_id = type(accessxi.current_zone_id) == 'function'
            and (tonumber(accessxi.current_zone_id()) or 0)
            or (tonumber(nav_zone_id()) or 0);
        local signal = {
            kind = 'kill-credit', packet_id = 0x029, message_id = message_id,
            actor_server_id = actor_server_id, actor_index = actor_index,
            actor_is_local = actor_kind == 'local', actor_is_party = actor_kind == 'party',
            target_server_id = target_server_id, target_index = target_index,
            target_name = target_name, zone_id = zone_id,
            character_identity = identity, world_id = world_id,
            session_epoch = session_epoch, sequence = sequence,
            battle_sequence = sequence, tick = now,
            corpus_revision = tonumber(accessxi.nav_catalog_revision) or 0,
            causal_id = ('0x029:%d:%s'):fmt(sequence, replay_key),
        };
        accessxi.objective_kill_replay_key = replay_key;
        accessxi.objective_kill_replay_tick = now;
        if (type(accessxi.nav_mission_quest_reduce_signal) == 'function') then
            pcall(accessxi.nav_mission_quest_reduce_signal, signal);
        end
        return;
    end
    if (packet_id ~= 0x028) then return; end

    local data = e.data_modified or e.data or accessxi.packet_event_string(e, 'data_modified', 'size') or accessxi.packet_event_string(e, 'data', 'size') or '';
    local action, err = accessxi.combat_action_parse(data);
    if (action == nil) then
        local parse_key = ('%s:%d:%s'):fmt(tostring(err or ''), #data, accessxi.packet_hex_limit(data, 24));
        if ((accessxi.combat_last_action_parse_error or '') ~= parse_key) then
            accessxi.combat_last_action_parse_error = parse_key;
            log_state(('state combat action parse skipped reason="%s" len=%d'):fmt(
                accessxi.escape_probe_log_text(err or ''),
                #data));
        end
        accessxi.log_combat_action_diag(nil, data, ('parse-%s'):fmt(tostring(err or '')));
        return;
    end

    local speech, detail = accessxi.combat_action_packet_speech(action);
    if (speech == nil or speech == '') then
        accessxi.log_combat_action_diag(action, data, 'no-speech');
        return;
    end

    accessxi.queue_combat_action_feedback(speech, detail, action);
end

accessxi.handle_chat_text = function (mode, text, injected)
    local entry = accessxi.chat_add_history(mode, text, injected);
    if (entry == nil) then
        return;
    end
    accessxi.auction_price_history_remember_chat_text(entry);

    local speech = accessxi.combat_damage_speech(entry) or accessxi.chat_entry_speech(entry);
    local now = tick();
    local key = ('%d:%s'):fmt(entry.mode or 0, entry.text or '');
    if (key == (accessxi.chat_last_key or '') and (now - (accessxi.chat_last_tick or 0)) < 1500) then
        return;
    end

    accessxi.chat_last_key = key;
    accessxi.chat_last_tick = now;
    log_line(('chat text mode=%d label="%s" "%s"'):fmt(entry.mode or 0, entry.label or 'Chat', entry.text or ''));
    if (accessxi.chat_should_speak(mode, entry.text)) then
        speak(speech, false);
    end
end

accessxi.npc_echo_compare_text = function (text)
    text = accessxi.clean_incoming_text(text or '');
    if (text == '') then
        return '';
    end

    text = text:gsub('%s*%[%d%d:%d%d:%d%d%]%s*', ' ');
    text = text:gsub('%s+', ' '):trim();
    return text;
end

accessxi.chat_text_is_recent_npc_echo = function (mid, text, now)
    mid = tonumber(mid) or 0;
    if (mid ~= 190) then
        return false;
    end

    local compare = accessxi.npc_echo_compare_text(text);
    if (compare == '' or compare ~= tostring(accessxi.last_npc_echo_compare_text or '')) then
        return false;
    end

    now = tonumber(now) or tick();
    return (now - (tonumber(accessxi.last_npc_echo_tick) or 0)) < 2500;
end

accessxi.chat_text_in_diag_hex = function (data, max_bytes)
    if (type(data) ~= 'string') then
        return tostring(data or '');
    end

    max_bytes = math.max(0, math.min(tonumber(max_bytes) or 64, #data));
    local parts = T{};
    for i = 1, max_bytes do
        parts:append(('%02X'):fmt(string.byte(data, i) or 0));
    end
    if (#data > max_bytes) then
        parts:append('...');
    end
    return parts:concat(' ');
end

accessxi.chat_text_in_diag_fields = function (e)
    if (type(e) ~= 'table') then
        return tostring(e or '');
    end

    local parts = T{};
    for key, value in pairs(e) do
        local value_type = type(value);
        if (value_type == 'number' or value_type == 'boolean' or value_type == 'string') then
            local value_text = tostring(value);
            if (value_type == 'string') then
                value_text = ('len=%d hex=%s'):fmt(#value, accessxi.chat_text_in_diag_hex(value, 24));
            end
            parts:append(('%s=%s'):fmt(tostring(key), value_text));
            if (parts:len() >= 16) then
                break;
            end
        end
    end
    return parts:concat(' | ');
end

accessxi.chat_text_in_diag = function (e, mid, text)
    if (not accessxi.debug_probe_logging_active()) then
        return;
    end

    local raw_message = '';
    local raw_modified = '';
    local data = nil;
    pcall(function ()
        raw_message = e.message or '';
        raw_modified = e.message_modified or '';
        data = e.data_modified or e.data;
    end);

    local key = ('%s:%s:%s:%s'):fmt(
        tostring(e ~= nil and e.mode or ''),
        tostring(e ~= nil and e.mode_modified or ''),
        tostring(mid or ''),
        tostring(text or ''));
    local now = tick();
    if (key == (accessxi.chat_text_in_diag_last_key or '') and (now - (accessxi.chat_text_in_diag_last_tick or 0)) < 1000) then
        return;
    end
    accessxi.chat_text_in_diag_last_key = key;
    accessxi.chat_text_in_diag_last_tick = now;

    local data_len = type(data) == 'string' and #data or 0;
    log_line(('chat text diag mode=%s modified=%s mid=%d rawLen=%d modLen=%d dataLen=%d dataType=%s data="%s" raw="%s" modifiedRaw="%s" clean="%s" fields="%s"'):fmt(
        tostring(e ~= nil and e.mode or ''),
        tostring(e ~= nil and e.mode_modified or ''),
        tonumber(mid) or 0,
        type(raw_message) == 'string' and #raw_message or 0,
        type(raw_modified) == 'string' and #raw_modified or 0,
        data_len,
        type(data),
        accessxi.chat_text_in_diag_hex(data, 80),
        accessxi.chat_text_in_diag_hex(raw_message, 80),
        accessxi.chat_text_in_diag_hex(raw_modified, 80),
        accessxi.escape_probe_log_text(text or ''),
        accessxi.escape_probe_log_text(accessxi.chat_text_in_diag_fields(e))));
end

local function is_chat_log_menu_name(name)
    name = tostring(name or '');
    return name:eq('menu    logwindo', true)
        or name:eq('menu    fulllog', true)
        or name:find('menu    logwin2', 1, true) == 1;
end

accessxi.chat_log_clean_native_text = function (text)
    text = tostring(text or '');
    if (text == '') then
        return '';
    end

    text = text:gsub('[\r\n\t]+', ' ');
    text = text:gsub('%s+', ' '):trim();
    if (text == '') then
        return '';
    end

    local start_index = nil;
    local time_patterns = T{
        '%[%d%d:%d%d:%d%d%]',
        '%[%d:%d%d:%d%d%]',
        '%d%d:%d%d:%d%d%]',
        '%d:%d%d:%d%d%]',
    };
    for _, pattern in ipairs(time_patterns) do
        local s = text:find(pattern);
        if (s ~= nil) then
            start_index = s;
            break;
        end
    end
    if (start_index ~= nil and start_index > 1) then
        text = text:sub(start_index):trim();
    end

    if (text:match('^%d%d:%d%d:%d%d%]') ~= nil or text:match('^%d:%d%d:%d%d%]') ~= nil) then
        text = '[' .. text;
    end

    text = text:gsub('^%]+', ''):trim();
    text = text:gsub('^%p+%s*', ''):trim();
    if (text:match('^%d%d:%d%d:%d%d%]') ~= nil or text:match('^%d:%d%d:%d%d%]') ~= nil) then
        text = '[' .. text;
    end

    do
        local _, first_end = text:find('%[%d%d:%d%d:%d%d%]');
        if (first_end == nil) then
            _, first_end = text:find('%[%d:%d%d:%d%d%]');
        end
        if (first_end ~= nil) then
            local second_start = text:find('%[%d%d:%d%d:%d%d%]', first_end + 1);
            if (second_start == nil) then
                second_start = text:find('%[%d:%d%d:%d%d%]', first_end + 1);
            end
            if (second_start == nil) then
                second_start = text:find('%[%d%d:%d%d', first_end + 1);
            end
            if (second_start == nil) then
                second_start = text:find('%[%d:%d%d', first_end + 1);
            end
            if (second_start ~= nil) then
                text = text:sub(1, second_start - 1):trim();
            end
        end
    end

    text = text:gsub('Q%[', '['):gsub('Q%]', ']');
    text = text:gsub('%sjLoaded%s+', ' Loaded ');
    text = text:gsub('jLoaded%s+', 'Loaded ');
    text = text:gsub('accessxi_reade$', 'accessxi_reader');
    text = text:gsub('(Loaded addon:%s+accessxi_reader)%s+@[%w%p]+$', '%1'):trim();
    text = text:gsub('(Loaded addon:%s+accessxi_reader)%s+[%w%p]+$', '%1'):trim();
    text = text:gsub('(Loaded addon:%s+accessxi_reader)%s+.*H%d?#.*$', '%1'):trim();
    text = text:gsub('(Loaded addon:%s+accessxi_reader)%s+.*KI%%.*$', '%1'):trim();
    text = text:gsub('(Loaded addon:%s+accessxi_reader)%s+[%+][%w%(%)&]+$', '%1'):trim();
    text = text:gsub("%s*[\"']?%s*|%s*%+%x%x%x=.*$", ''):trim();
    text = text:gsub("%s*[\"']?%s*|%s*%+%x%x%x%x=.*$", ''):trim();
    text = text:gsub("%s*%+%x%x%x=[\"'].*$", ''):trim();
    text = text:gsub("%s*%+%x%x%x%x=[\"'].*$", ''):trim();
    text = text:gsub('%s+bytes=%x%x.*$', ''):trim();
    text = text:gsub('%sxH#.*$', ''):trim();
    text = text:gsub('%sH%d?#.*$', ''):trim();
    text = text:gsub('%sH#.*$', ''):trim();
    text = text:gsub('%sHH#.*$', ''):trim();
    text = text:gsub('X%[%d+%]j.*$', ''):trim();
    text = text:gsub('%[%d+%]j.*$', ''):trim();
    text = text:gsub('X[%$&]+$', ''):trim();
    text = text:gsub('%*%[j.*$', ''):trim();
    text = text:gsub('Qa%d.*$', ''):trim();
    text = text:gsub('[A-Za-z]+>%s*yar%d.*$', ''):trim();
    text = text:gsub('%s*e%s+%d+>>%d+$', ''):trim();
    text = text:gsub('%s*%d+>>%d+$', ''):trim();
    text = text:gsub('%s*e%s+%d+$', ''):trim();
    -- Full-log rows are fixed-width-ish; stale bytes from older rows can leak
    -- after the live line when no null terminator is present.
    text = text:gsub('%.#N[hH].*$', '.'):trim();
    text = text:gsub('%.N[%w=@#%$&].*$', ''):trim();
    text = text:gsub('#N[hH].*$', ''):trim();
    text = text:gsub('N[hH][%$&%w@=].*$', ''):trim();
    text = text:gsub('(>%s*)>+%d[%w%)%(]+$', '%1'):trim();
    text = text:gsub('(>%s*)>+=?$', '%1'):trim();
    text = text:gsub('%s+===[%=%-]*[%w%$&%[%]%?%*]+$', ''):trim();
    text = text:gsub('%s+===[%=%-]*$', ''):trim();
    text = text:gsub('%s+=+$', ''):trim();
    text = text:gsub('^(%[%d%d:%d%d:%d%d%]%s+[%u%d_%-]+)[A-Z][a-z][A-Za-z%s]*=+$', '%1'):trim();
    text = text:gsub('^(%[%d:%d%d:%d%d%]%s+[%u%d_%-]+)[A-Z][a-z][A-Za-z%s]*=+$', '%1'):trim();
    text = text:gsub('^(%[%d%d:%d%d:%d%d%]%s+[%u%d_%-]+)[%?%(%)][%w%$&%(%)%?]*$', '%1'):trim();
    text = text:gsub('^(%[%d:%d%d:%d%d%]%s+[%u%d_%-]+)[%?%(%)][%w%$&%(%)%?]*$', '%1'):trim();
    text = text:gsub('[=#][A-Za-z]?[A-Za-z]?[%$&%[%]%?%*%s]+$', ''):trim();
    text = text:gsub('(%S)[A-Z][%$&%[%]%?%*]+$', '%1'):trim();
    text = text:gsub('[%$&%[%]%?%*]+$', ''):trim();
    text = text:gsub('%s*%d+["\\]+$', ''):trim();
    text = text:gsub('%.Oi%[?%d*:?.*$', ''):trim();
    text = text:gsub('Oi%[?%d*:?.*$', ''):trim();
    text = text:gsub('>eOj.*$', '>'):trim();
    text = text:gsub('eOj.*$', ''):trim();
    text = text:gsub('=AK.*$', ''):trim();
    text = text:gsub('AKQ#.*$', ''):trim();
    text = text:gsub('AK[%$&].*$', ''):trim();
    text = text:gsub('AK$', ''):trim();
    text = text:gsub('AK%$?$', ''):trim();
    text = text:gsub('%s*[=/][A-Za-z][A-Za-z][%$&]?.*$', ''):trim();
    text = text:gsub('%s*{Q[%$&]?.*$', ''):trim();
    text = text:gsub('%?%^.*$', ''):trim();
    text = text:gsub('%^L.*$', ''):trim();
    text = text:gsub('%s+', ' '):trim();
    local max_len = tonumber(accessxi.chat_log_max_line_len) or 150;
    if (#text > max_len) then
        text = text:sub(1, max_len):trim();
    end
    if (#text < 3 or #text > max_len) then
        return '';
    end
    if (text:match('^[%p%s]+$') ~= nil) then
        return '';
    end
    if (text:lower():find('accessxi%.chat', 1, true) ~= nil
        or text:lower():find('menudump', 1, true) ~= nil
        or text:lower():find('function ', 1, true) ~= nil
        or text:lower():find('state chatlog ', 1, true) ~= nil
        or text:lower():find('chatprobe ', 1, true) ~= nil
        or text:find('%|%s*%+%x%x%x=') ~= nil
        or text:find('%|%s*%+%x%x%x%x=') ~= nil) then
        return '';
    end
    if (text:match('^%x%x?,%x%x?,%x%x?,') ~= nil
        or text:match('^%x%x%x%x%x%x%x%x,') ~= nil) then
        return '';
    end

    return text;
end

accessxi.chat_log_max_line_len = 150;

accessxi.chat_log_temp_clean_text = function (text)
    text = tostring(text or '');
    if (text == '') then
        return '';
    end

    text = text:gsub(string.char(0x7F) .. '1', ' ');
    text = text:gsub(string.char(0x81) .. string.char(0xA1), '*');
    text = text:gsub(string.char(0xC2) .. string.char(0xA1), '*');
    text = text:gsub(string.char(0x81) .. string.char(0x40), ' ');
    pcall(function ()
        local chat = AshitaCore:GetChatManager();
        if (chat ~= nil) then
            text = chat:ParseAutoTranslate(text, true);
        end
    end);
    pcall(function () text = text:strip_colors(); end);
    pcall(function () text = text:strip_translate(true); end);
    text = tostring(text):gsub(string.char(0x07), ' ');
    text = text:gsub('[\r\n\t]+', ' '):gsub('[%c]', ' ');
    local ascii_bytes = T{};
    for i = 1, #text do
        local b = text:byte(i) or 0;
        if (b >= 32 and b <= 126) then
            ascii_bytes:append(string.char(b));
        elseif (b > 0) then
            ascii_bytes:append(' ');
        end
    end
    text = ascii_bytes:concat('');
    text = text:gsub('Q%[%s*Addons%s*Q%s*%]', '[Addons]');
    text = text:gsub('Q%[%s*AccessXI%s*Q%s*%]', '[AccessXI]');
    text = text:gsub('%[%s*Q%s*Addons%s*Q%s*%]', '[Addons]');
    text = text:gsub('%[%s*Q%s*AccessXI%s*Q%s*%]', '[AccessXI]');
    text = text:gsub('^%s*[jQy]+%s*(%[%d%d?:%d%d:?%d*%])', '%1');
    text = text:gsub('^%s*[jQy]+%s*(%[[%a%s]+%])', '%1');
    text = text:gsub('^%s*[jQy]+([A-Za-z])', '%1');
    text = text:gsub('(%])%s*[jQy]+([A-Za-z])', '%1 %2');
    text = text:gsub('%s+[jQy]+%s*%-', ' -');
    text = text:gsub('%s+', ' '):trim();
    while (true) do
        local updated = text:gsub('^%s*%[%d%d?:%d%d:?%d*%]%s*', '');
        if (updated == text) then
            break;
        end
        text = updated:trim();
    end
    return text:gsub('%s+', ' '):trim();
end

accessxi.chat_log_temp_strip_row_tail = function (text)
    text = tostring(text or '');
    text = text:gsub('%.#N[hH].*$', '.'):trim();
    text = text:gsub('%.N[%w=@#%$&].*$', ''):trim();
    text = text:gsub('#N[hH].*$', ''):trim();
    text = text:gsub('N[hH][%$&%w@=].*$', ''):trim();
    text = text:gsub('=%?[%w%p%s]*$', ''):trim();
    text = text:gsub(':%s*[A-Za-z][A-Za-z]?$', ':'):trim();
    return text;
end

accessxi.chat_log_temp_match_key = function (text)
    text = accessxi.chat_log_temp_clean_text(text);
    text = accessxi.chat_log_temp_strip_row_tail(text);
    text = text:gsub('^%s*%[%d%d?:%d%d:?%d*%]%s*', '');
    text = text:gsub('[^%w]+', ' ');
    text = text:lower():gsub('%s+', ' '):trim();
    return text;
end

accessxi.chat_log_temp_match_phrases = function (fragment)
    local key = accessxi.chat_log_temp_match_key(fragment);
    local tokens = {};
    for token in key:gmatch('%S+') do
        tokens[#tokens + 1] = token;
    end

    while (#tokens > 0 and #tokens[#tokens] <= 2) do
        tokens[#tokens] = nil;
    end

    local phrases = T{};
    local seen = {};
    for count = #tokens, 1, -1 do
        local phrase = table.concat(tokens, ' ', 1, count):trim();
        if (phrase ~= '' and seen[phrase] ~= true) then
            if (count >= 2 or #phrase >= 7) then
                phrases:append(phrase);
                seen[phrase] = true;
            end
        end
    end
    return phrases, key;
end

accessxi.chat_log_temp_time_key = function (text)
    text = tostring(text or '');
    local hour, minute = text:match('%[(%d%d?):(%d%d):%d%d%]');
    if (hour == nil) then
        hour, minute = text:match('%[(%d%d?):(%d%d)%]');
    end
    if (hour == nil or minute == nil) then
        return '';
    end
    return ('%02d:%s'):fmt(tonumber(hour) or 0, minute);
end

accessxi.chat_log_temp_dir = function ()
    local player_name = '';
    pcall(function ()
        local party = AshitaCore:GetMemoryManager():GetParty();
        if (party ~= nil) then
            player_name = tostring(party:GetMemberName(0) or '');
        end
    end);
    player_name = player_name:match('^[A-Za-z0-9_%-]+') or '';
    if (player_name == '') then
        return '';
    end

    local install_dir = '';
    pcall(function ()
        local lang = AshitaCore:GetConfigurationManager():GetInt32('boot', 'ashita.language', 'playonline', 2);
        if (lang > 4) then
            lang = 2;
        end
        if (lang == 4) then
            lang = 3;
        end
        install_dir = tostring(ashita.fs.get_install_dir(lang, 1) or '');
    end);
    if (install_dir == '') then
        install_dir = accessxi.ffxi_root;
    end
    install_dir = install_dir:gsub('[\\/]+$', '');

    local function usable_dir(name)
        name = tostring(name or ''):match('^[A-Za-z0-9_%-]+') or '';
        if (name == '') then
            return '';
        end
        local path = ('%s\\TEMP\\%s'):fmt(install_dir, name);
        if (ashita.fs.exists(path)
            or ashita.fs.exists(path .. '\\1_0.log')
            or ashita.fs.exists(path .. '\\2_0.log')) then
            return path;
        end
        return '';
    end

    local seen = {};
    for _, name in ipairs(T{
        player_name,
        player_name:sub(1, 8),
        player_name:sub(1, 7),
        player_name:sub(1, 6),
        player_name:sub(1, 5),
    }) do
        name = tostring(name or '');
        if (name ~= '' and seen[name:lower()] ~= true) then
            seen[name:lower()] = true;
            local path = usable_dir(name);
            if (path ~= '') then
                return path;
            end
        end
    end

    return ('%s\\TEMP\\%s'):fmt(install_dir, player_name);
end

accessxi.chat_log_temp_record = function (record)
    record = tostring(record or '');
    local fields = T{};
    local pos = 1;
    for _ = 1, 21 do
        local comma = record:find(',', pos, true);
        if (comma == nil) then
            return nil;
        end
        fields:append(record:sub(pos, comma - 1));
        pos = comma + 1;
    end
    if (#fields < 21 or fields[5]:match('^%x+$') == nil or fields[6]:match('^%x+$') == nil) then
        return nil;
    end

    local raw_text = record:sub(pos);
    local time_key = accessxi.chat_log_temp_time_key(raw_text);
    local text = accessxi.chat_log_temp_clean_text(raw_text);
    if (text == '') then
        return nil;
    end
    return T{
        message_id = tonumber(fields[5], 16) or 0,
        row_id = tonumber(fields[6], 16) or 0,
        time_key = time_key,
        text = text,
    };
end

accessxi.chat_log_temp_entries = function ()
    local now = tick();
    local dir = accessxi.chat_log_temp_dir();
    if (dir == '') then
        return T{};
    end
    if (accessxi.chat_log_temp_cache_dir == dir
        and accessxi.chat_log_temp_cache_entries ~= nil
        and ((now - (accessxi.chat_log_temp_cache_tick or 0)) < 1000)) then
        return accessxi.chat_log_temp_cache_entries;
    end

    local groups = {};
    local order = T{};
    local rows = T{};
    for index = 0, 31 do
        for _, window_id in ipairs(T{ 1, 2 }) do
            local path = ('%s\\%d_%d.log'):fmt(dir, window_id, index);
            if (ashita.fs.exists(path)) then
                local file = io.open(path, 'rb');
                if (file ~= nil) then
                    local data = file:read('*a') or '';
                    file:close();
                    for record in data:gmatch('[^%z]+') do
                        local row = accessxi.chat_log_temp_record(record);
                        if (row ~= nil) then
                            row.path = path;
                            row.window_id = window_id;
                            row.file_index = index;
                            rows:append(row);
                            local key = ('%s:%08X'):fmt(path, tonumber(row.message_id) or 0);
                            if (groups[key] == nil) then
                                groups[key] = T{ parts = T{}, first_row = row.row_id, path = path, time_key = row.time_key or '' };
                                order:append(key);
                            end
                            if ((groups[key].time_key or '') == '' and (row.time_key or '') ~= '') then
                                groups[key].time_key = row.time_key;
                            end
                            groups[key].parts:append(row.text);
                        end
                    end
                end
            end
        end
    end

    local entries = T{};
    for _, key in ipairs(order) do
        local group = groups[key];
        if (group ~= nil and group.parts ~= nil and #group.parts > 0) then
            local text = accessxi.chat_log_temp_clean_text(group.parts:concat(' '));
            if (#text >= 3) then
                entries:append(T{ text = text, key = key, first_row = group.first_row or 0, time_key = group.time_key or '' });
            end
        end
    end

    accessxi.chat_log_temp_cache_dir = dir;
    accessxi.chat_log_temp_cache_entries = entries;
    accessxi.chat_log_temp_cache_rows = rows;
    accessxi.chat_log_temp_cache_tick = now;
    return entries;
end

accessxi.chat_log_temp_rows = function ()
    local now = tick();
    local dir = accessxi.chat_log_temp_dir();
    if (dir == '') then
        return T{};
    end
    if (accessxi.chat_log_temp_cache_dir == dir
        and accessxi.chat_log_temp_cache_rows ~= nil
        and ((now - (accessxi.chat_log_temp_cache_tick or 0)) < 1000)) then
        return accessxi.chat_log_temp_cache_rows;
    end

    accessxi.chat_log_temp_entries();
    if (accessxi.chat_log_temp_cache_dir == dir and accessxi.chat_log_temp_cache_rows ~= nil) then
        return accessxi.chat_log_temp_cache_rows;
    end
    return T{};
end

accessxi.chat_log_selected_source_ids = function (state)
    if (state == nil or not accessxi.is_probe_pointer(state.data)) then
        return nil;
    end

    local ptr = read_u32(state.data + 0x28) or 0;
    if (not accessxi.is_probe_pointer(ptr)) then
        return nil;
    end

    local message_id = read_u32(ptr + 0x08) or 0;
    local row_id = read_u32(ptr + 0x0C) or 0;
    local length_word = read_u32(ptr + 0x10) or 0;
    local line_len = bit.band(length_word, 0xFFFF);
    if (message_id <= 0 or row_id <= 0 or row_id < message_id or line_len > 0x400) then
        return nil;
    end

    return T{
        ptr = ptr,
        message_id = message_id,
        row_id = row_id,
        line_len = line_len,
    };
end

accessxi.chat_log_native_line_from_temp_row_id = function (state)
    local ids = accessxi.chat_log_selected_source_ids(state);
    if (ids == nil) then
        return nil;
    end

    local rows = accessxi.chat_log_temp_rows();
    local best = nil;
    for _, row in ipairs(rows) do
        if ((tonumber(row.message_id) or 0) == ids.message_id
            and (tonumber(row.row_id) or 0) == ids.row_id) then
            local text = accessxi.chat_log_speech_text(row.text or '');
            if (text ~= ''
                and #text >= 1
                and #text <= (tonumber(accessxi.chat_log_max_line_len) or 150)
                and text:find('%a') ~= nil
                and text:match('^[%p%s]+$') == nil
                and not accessxi.chat_log_has_suspicious_noise(text)) then
                best = T{ row = row, text = text };
                break;
            end
        end
    end

    local log_key = ('%d:%d:%d:%d:%s'):fmt(
        tonumber(state.cursor) or -1,
        tonumber(state.bottom) or -1,
        ids.message_id,
        ids.row_id,
        best ~= nil and best.text or '');
    if (log_key ~= (accessxi.chat_log_temp_exact_last_probe or '')) then
        accessxi.chat_log_temp_exact_last_probe = log_key;
        log_state(('state chatlog temp-exact cursor=%d bottom=%d selectedIndex=%d ptr=0x%08X msg=0x%08X row=0x%08X rows=%d text="%s" path="%s"'):fmt(
            tonumber(state.cursor) or -1,
            tonumber(state.bottom) or -1,
            tonumber(state.selected_index) or -1,
            tonumber(ids.ptr) or 0,
            tonumber(ids.message_id) or 0,
            tonumber(ids.row_id) or 0,
            rows:len(),
            best ~= nil and accessxi.escape_probe_log_text(best.text or '') or '',
            best ~= nil and accessxi.escape_probe_log_text(tostring(best.row.path or '')) or ''));
    end

    if (best == nil) then
        return nil;
    end

    return T{
        text = best.text,
        source = ('fulllog-temp-exact:%08X/%08X'):fmt(ids.message_id, ids.row_id),
        score = 47000,
        chat_log_menu_nav = true,
        chat_log_row_selected = tonumber(state.selected_index) or 0,
        chat_log_row_count = tonumber(state.row_count) or 0,
        chat_log_selection_reason = 'native-fulllog-temp-exact',
        visible_signature = ('%d:%d:%08X:%08X:%s'):fmt(
            tonumber(state.cursor) or -1,
            tonumber(state.bottom) or -1,
            ids.message_id,
            ids.row_id,
            best.text),
    };
end

accessxi.chat_log_resolve_temp_row = function (fragment)
    fragment = accessxi.chat_log_temp_clean_text(fragment);
    if (#fragment < 8) then
        return '';
    end
    fragment = accessxi.chat_log_temp_strip_row_tail(fragment);
    if (#fragment < 8) then
        return '';
    end

    local rows = accessxi.chat_log_temp_rows();
    local phrases, fragment_key = accessxi.chat_log_temp_match_phrases(fragment);
    local best = nil;
    local best_score = 0;
    local best_phrase = '';
    for index, row in ipairs(rows) do
        local text = accessxi.chat_log_temp_strip_row_tail(row.text or '');
        local speech = accessxi.chat_log_speech_text(text);
        if (speech ~= '' and #speech <= (tonumber(accessxi.chat_log_max_line_len) or 150)) then
            local start = text:find(fragment, 1, true);
            if (start ~= nil) then
                local score = (#fragment * 4) + math.min(#speech, 150) - math.min(start, 80) + math.min(index, 128);
                if (score > best_score) then
                    best = speech;
                    best_score = score;
                    best_phrase = fragment;
                end
            end

            local row_key = accessxi.chat_log_temp_match_key(text);
            for _, phrase in ipairs(phrases) do
                local key_start = row_key:find(phrase, 1, true);
                if (key_start ~= nil) then
                    local score = (#phrase * 3) + math.min(#speech, 150) - math.min(key_start, 80) + math.min(index, 128);
                    if (score > best_score) then
                        best = speech;
                        best_score = score;
                        best_phrase = phrase;
                    end
                    break;
                end
            end
        end
    end

    local now = tick();
    local log_key = ('%s:%d:%s:%s'):fmt(fragment, #rows, best_phrase, best or '');
    if (log_key ~= (accessxi.chat_log_temp_row_last_log or '')
        and ((now - (accessxi.chat_log_temp_row_last_tick or 0)) >= 500)) then
        accessxi.chat_log_temp_row_last_log = log_key;
        accessxi.chat_log_temp_row_last_tick = now;
        log_state(('state chatlog temprow rows=%d fragment="%s" key="%s" phrase="%s" match="%s"'):fmt(
            #rows,
            accessxi.escape_probe_log_text(fragment),
            accessxi.escape_probe_log_text(fragment_key or ''),
            accessxi.escape_probe_log_text(best_phrase or ''),
            accessxi.escape_probe_log_text(best or '')));
    end
    return best or '';
end

accessxi.chat_log_resolve_temp_entry = function (fragment)
    local fragment_time = accessxi.chat_log_temp_time_key(fragment);
    fragment = accessxi.chat_log_temp_clean_text(fragment);
    if (#fragment < 8) then
        return '';
    end
    fragment = accessxi.chat_log_temp_strip_row_tail(fragment);
    if (#fragment < 8) then
        return '';
    end

    local entries = accessxi.chat_log_temp_entries();
    local phrases, fragment_key = accessxi.chat_log_temp_match_phrases(fragment);
    local best = nil;
    local best_score = 0;
    local best_phrase = '';
    for index, entry in ipairs(entries) do
        local text = tostring(entry.text or '');
        local time_bonus = 0;
        if (fragment_time ~= '' and tostring(entry.time_key or '') == fragment_time) then
            time_bonus = 400;
        end
        local start = text:find(fragment, 1, true);
        if (start ~= nil) then
            local score = #fragment + math.min(#text, 220) - math.min(start, 80) + math.min(index, 64) + time_bonus;
            if (score > best_score) then
                best = text;
                best_score = score;
                best_phrase = fragment;
            end
        end

        local entry_key = accessxi.chat_log_temp_match_key(text);
        for _, phrase in ipairs(phrases) do
            local key_start = entry_key:find(phrase, 1, true);
            if (key_start ~= nil) then
                local score = (#phrase * 3) + math.min(#text, 220) - math.min(key_start, 80) + math.min(index, 64) + time_bonus;
                if (score > best_score) then
                    best = text;
                    best_score = score;
                    best_phrase = phrase;
                end
                break;
            end
        end
    end

    local now = tick();
    local log_key = ('%s:%d:%s:%s'):fmt(fragment, #entries, best_phrase, best or '');
    if (log_key ~= (accessxi.chat_log_temp_last_log or '')
        and ((now - (accessxi.chat_log_temp_last_tick or 0)) >= 500)) then
        accessxi.chat_log_temp_last_log = log_key;
        accessxi.chat_log_temp_last_tick = now;
        log_state(('state chatlog templog entries=%d time="%s" fragment="%s" key="%s" phrase="%s" match="%s"'):fmt(
            #entries,
            fragment_time,
            accessxi.escape_probe_log_text(fragment),
            accessxi.escape_probe_log_text(fragment_key or ''),
            accessxi.escape_probe_log_text(best_phrase or ''),
            accessxi.escape_probe_log_text(best or '')));
    end
    return best or '';
end

accessxi.chat_log_match_key = function (text)
    text = tostring(text or ''):gsub('%z', ' ');
    text = text:gsub('^%[%d%d?:%d%d:?%d*%]%s*', '');
    text = accessxi.chat_log_repair_selected_source_text(text);
    text = text:gsub('%(MM%)BELIEVEWEVEDEFEATED(%d+)', "Hmm I believe we've defeated %1");
    text = text:gsub('%(MM%)BELIEVEWEVEDEFEAT(%d+)', "Hmm I believe we've defeated %1");
    text = text:gsub('%(MM%)BELIEVEWEVEDEFEATED', "Hmm I believe we've defeated");
    text = text:gsub('%(MM%)BELIEVEWEVEDEFEAT', "Hmm I believe we've defeated");
    text = text:gsub('4HEMOOGLESHAVEPREPAREDALL', 'The moogles have prepared all');
    text = text:gsub('THEMOOGLESHAVEPREPAREDALL', 'The moogles have prepared all');
    text = text:gsub('ADNEWS%(?AVEYOUHEARDOF', 'Bad news Have you heard of');
    text = text:lower();
    text = text:gsub('[^%w]+', '');
    return text;
end

accessxi.chat_log_text_looks_corrupt = function (text)
    text = tostring(text or ''):trim();
    if (text == '') then
        return false;
    end

    if (text:find('??', 1, true) ~= nil
        or text:find('ACCESS8', 1, true) ~= nil
        or text:find('[AccessX', 1, true) ~= nil
        or text:find('PARTICIPATINGIN', 1, true) ~= nil
        or text:find('TRYAGAINLATER', 1, true) ~= nil
        or text:find('5NITY', 1, true) ~= nil
        or text:find('0LEASE', 1, true) ~= nil
        or text:find('1UETZAL', 1, true) ~= nil
        or text:find('ADNEWS', 1, true) ~= nil
        or text:find('AVEYOUHEARDOF', 1, true) ~= nil
        or text:find('(MM)BELIEVE', 1, true) ~= nil
        or text:find('4HEMOOGLES', 1, true) ~= nil) then
        return true;
    end

    local letters = 0;
    local spaces = 0;
    local upper = 0;
    for i = 1, #text do
        local b = text:byte(i) or 0;
        if ((b >= 65 and b <= 90) or (b >= 97 and b <= 122)) then
            letters = letters + 1;
            if (b >= 65 and b <= 90) then
                upper = upper + 1;
            end
        elseif (b == 32) then
            spaces = spaces + 1;
        end
    end

    return letters >= 24 and (spaces <= 1 or upper >= (letters - 2));
end

accessxi.chat_log_text_looks_partial_history_line = function (text)
    text = tostring(text or ''):gsub('%z', ' '):gsub('%s+', ' '):trim();
    if (text == '') then
        return false;
    end

    local lower = text:lower();
    if (lower:find('{apururu}', 1, true) ~= nil) then
        return true;
    end
    if (lower:find('monstersinarow', 1, true) ~= nil
        or lower:find('totalwotal', 1, true) ~= nil
        or lower:match('^%d+monsters%.?$') ~= nil
        or lower:find('monsters in a row', 1, true) ~= nil
        or lower:find('total-wotal', 1, true) ~= nil
        or lower:match('^%d+%s+monsters%.?$') ~= nil
        or lower:find('naughty-waughty', 1, true) ~= nil
        or lower:find('members-wembers', 1, true) ~= nil
        or lower:find('hurry-wurry', 1, true) ~= nil
        or lower:find('alrightaru', 1, true) ~= nil
        or lower:find('upsetaru', 1, true) ~= nil) then
        return true;
    end
    return false;
end

accessxi.chat_log_repair_from_recent_history = function (text)
    text = tostring(text or ''):gsub('%z', ' '):gsub('%s+', ' '):trim();
    -- Do not scan the full chat history while arrowing the native log. It is too
    -- expensive in the hot path and can replace real rows with unrelated history.
    return text;
end

accessxi.chat_log_repair_from_recent_history_disabled = function (text)
    text = tostring(text or ''):gsub('%z', ' '):gsub('%s+', ' '):trim();
    if (accessxi.chat_log_text_looks_partial_history_line(text) == true) then
        return text;
    end

    local should_match = accessxi.chat_log_text_looks_corrupt(text) == true;
    if (text == '' or should_match ~= true) then
        return text;
    end

    local fragment_key = accessxi.chat_log_match_key(text);
    if (#fragment_key < 12 or accessxi.chat_history == nil or accessxi.chat_history.len == nil or accessxi.chat_history:len() == 0) then
        return text;
    end

    for i = accessxi.chat_history:len(), 1, -1 do
        local entry = accessxi.chat_history[i];
        local candidate = entry ~= nil and tostring(entry.text or '') or '';
        candidate = accessxi.chat_log_repair_selected_source_text(accessxi.speech_name(candidate));
        candidate = candidate:gsub('^%[%d%d?:%d%d:?%d*%]%s*', ''):gsub('%s+', ' '):trim();
        if (candidate ~= '' and #candidate <= 320) then
            local candidate_key = accessxi.chat_log_match_key(candidate);
            if (#candidate_key >= #fragment_key and candidate_key:find(fragment_key, 1, true) ~= nil) then
                log_state(('state chatlog history-repair fragment="%s" match="%s"'):fmt(
                    accessxi.escape_probe_log_text(text),
                    accessxi.escape_probe_log_text(candidate)));
                return candidate;
            end
        end
    end

    return text;
end

accessxi.chat_log_find_apururu_defeated_count_for_total = function (total)
    total = tostring(total or ''):match('^(%d+)$') or '';
    if (total == '') then
        return '';
    end

    if (accessxi.chat_log_apururu_defeated_by_total ~= nil
        and accessxi.chat_log_apururu_defeated_by_total[total] ~= nil) then
        return tostring(accessxi.chat_log_apururu_defeated_by_total[total] or '');
    end

    if (accessxi.chat_history == nil or accessxi.chat_history.len == nil) then
        return '';
    end;

    local total_pattern = total .. '%s+monsters';
    for i = accessxi.chat_history:len(), 1, -1 do
        local entry = accessxi.chat_history[i];
        local line = entry ~= nil and tostring(entry.text or '') or '';
        line = accessxi.speech_name(accessxi.clean_incoming_text(line));
        local defeated = line:match("^%{Apururu%}%s+Hmm%.%.%.%s+I believe we've defeated%s+(%d+)%s+monsters in a row%.%s+That makes for a total%-wotal of%s+" .. total_pattern .. '%.?$');
        if (defeated ~= nil and defeated ~= '') then
            return defeated;
        end
    end
    return '';
end

accessxi.chat_log_remember_apururu_defeated_line = function (text)
    text = accessxi.speech_name(accessxi.clean_incoming_text(text or '')):gsub('%s+', ' '):trim();
    local defeated, total = text:match("^%{Apururu%}%s+Hmm%.%.%.%s+I believe we've defeated%s+(%d+)%s+monsters in a row%.%s+That makes for a total%-wotal of%s+(%d+)%s+monsters%.?$");
    if (defeated == nil or total == nil) then
        return false;
    end

    accessxi.chat_log_apururu_defeated_by_total = accessxi.chat_log_apururu_defeated_by_total or T{};
    accessxi.chat_log_apururu_defeated_by_total[tostring(total)] = tostring(defeated);
    return true;
end

accessxi.chat_log_seed_apururu_defeated_counts_from_log = function ()
    if (accessxi.chat_log_apururu_seeded == true) then
        return;
    end
    accessxi.chat_log_apururu_seeded = true;

    local path = accessxi.log_path;
    local file = io.open(path, 'r');
    if (file == nil) then
        return;
    end

    local size = tonumber(file:seek('end')) or 0;
    local tail_size = math.min(size, 262144);
    file:seek('set', math.max(0, size - tail_size));
    local data = file:read('*a') or '';
    file:close();

    local added = 0;
    for line in data:gmatch('[^\r\n]+') do
        local text = line:match('chat text mode=%-?%d+ label="[^"]*" "(.*)"%s*$') or '';
        if (text ~= '' and accessxi.chat_log_remember_apururu_defeated_line(text)) then
            added = added + 1;
        end
    end
    if (added > 0) then
        log_state(('state chatlog apururu-counts-seeded added=%d'):fmt(added));
    end
end

accessxi.chat_log_repair_apururu_defeated_row = function (text, next_text, total_text)
    text = tostring(text or ''):gsub('%s+', ' '):trim();
    if (text:match("^%{Apururu%}%s+Hmm%.%.%.%s+I believe we've defeated$") == nil
        and text:match("^%{Apururu%}%s+Hmm%s+I believe we've defeated$") == nil) then
        return text;
    end

    next_text = tostring(next_text or ''):gsub('%s+', ' '):trim();
    if (next_text:find('monsters in a row. That makes for a total-wotal of', 1, true) == nil) then
        return text;
    end

    local total = tostring(total_text or ''):gsub('%s+', ' '):trim():match('^(%d+)%s+monsters%.?$') or '';
    local defeated = accessxi.chat_log_find_apururu_defeated_count_for_total(total);
    if (defeated == '') then
        return text;
    end

    return text .. ' ' .. defeated;
end

accessxi.chat_log_speech_text = function (text, keep_timestamp)
    text = tostring(text or '');
    text = accessxi.speech_name(text);
    if (accessxi.chat_log_repair_selected_source_text ~= nil) then
        text = accessxi.chat_log_repair_selected_source_text(text);
    end
    if (keep_timestamp ~= true) then
        text = text:gsub('^%[%d%d:%d%d:%d%d%]%s*', '');
        text = text:gsub('^%[%d:%d%d:%d%d%]%s*', '');
        text = text:gsub('^%[%d%d:%d%d%]%s*', '');
        text = text:gsub('^%[%d:%d%d%]%s*', '');
    end
    text = text:gsub('@f.*$', '');
    text = text:gsub('%$[%w%p]*$', '');
    text = text:gsub('Q%d+%s*>>.*$', '');
    text = text:gsub('%s*>>>.*$', '');
    if (text:match('<[^>]+>') == nil) then
        text = text:gsub('%s*>[#%w%.%-=]+.*$', '');
        text = text:gsub('%s*>%s*[%w%.%-=]+.*$', '');
    end
    text = text:gsub('Regional influence:s$', 'Regional influence:');
    text = text:gsub('%[ Addons %]', '[Addons]');
    text = text:gsub('%[ AccessXI %]', '[AccessXI]');
    text = text:gsub('^(%[%d%d:%d%d:%d%d%])%s*%[(%d)%]%s*<([^>]+)>%s*', '%1 Linkshell %2. %3. ');
    text = text:gsub('^%[(%d)%]%s*<([^>]+)>%s*', 'Linkshell %1. %2. ');
    text = text:gsub('(<[^>]+>)(%S)', '%1 %2');
    text = text:gsub('%](%S)', '] %1');
    text = text:gsub('Loadedaddon:', 'Loaded addon:');
    text = text:gsub('Combat%.Youhaveundertaken', 'Combat. You have undertaken');
    text = text:gsub('Youhaveundertaken', 'You have undertaken');
    text = text:gsub('Eminencechallenge', 'Eminence challenge ');
    text = text:gsub('challengeVanquish', 'challenge Vanquish ');
    text = text:gsub('VanquishArcana', 'Vanquish Arcana');
    text = text:gsub('RecordsofEminence', 'Records of Eminence');
    text = text:gsub('%- Minimals$', '- Minimal');
    text = text:gsub('%- MinimalDowns$', '- Minimal');
    text = text:gsub('%- Majora$', '- Major');
    text = text:gsub('%- Minorwns$', '- Minor');
    text = text:gsub('^SAN D ORIA MINOR$', "Sand'Oria - Minor");
    text = text:gsub('^SAN D ORIA MAJOR$', "Sand'Oria - Major");
    text = text:gsub('^SAN D ORIA MINIMAL$', "Sand'Oria - Minimal");
    text = text:gsub('^SAND ORIA MINOR$', "Sand'Oria - Minor");
    text = text:gsub('^SAND ORIA MAJOR$', "Sand'Oria - Major");
    text = text:gsub('^SAND ORIA MINIMAL$', "Sand'Oria - Minimal");
    text = text:gsub('^??r??????r????!$', 'Japanese text: biyobiyo!');
    text = text:gsub('(Loaded addon:%s+accessxi_reader)%s+@[%w%p]+$', '%1');
    text = text:gsub("%s*[\"']?%s*|%s*%+%x%x%x=.*$", '');
    text = text:gsub("%s*[\"']?%s*|%s*%+%x%x%x%x=.*$", '');
    text = text:gsub('%s*[>=%.%-_`]+%s*$', '');
    text = text:gsub('%s+', ' '):trim();
    text = accessxi.chat_log_repair_from_recent_history(text);
    return text;
end

accessxi.chat_log_has_time = function (text)
    text = tostring(text or '');
    return text:find('%[%d%d:%d%d:%d%d%]') ~= nil
        or text:find('%[%d:%d%d:%d%d%]') ~= nil
        or text:find('%d%d:%d%d:%d%d%]') ~= nil
        or text:find('%d:%d%d:%d%d%]') ~= nil
        or text:find('%[%d%d:%d%d%]') ~= nil
        or text:find('%[%d:%d%d%]') ~= nil;
end

accessxi.chat_log_string_text_from_ptr = function (ptr, length)
    ptr = tonumber(ptr) or 0;
    if (not accessxi.is_probe_pointer(ptr)) then
        return '';
    end

    length = math.max(16, math.min(tonumber(length) or (tonumber(accessxi.chat_log_max_line_len) or 150), 160));
    local ok, text = pcall(ashita.memory.read_string, ptr, length);
    if (not ok or text == nil) then
        return '';
    end
    return accessxi.chat_log_clean_native_text(text);
end

accessxi.chat_log_ascii_text_from_ptr = function (ptr, length)
    ptr = tonumber(ptr) or 0;
    if (not accessxi.is_probe_pointer(ptr)) then
        return '';
    end

    length = math.max(16, math.min(tonumber(length) or (tonumber(accessxi.chat_log_max_line_len) or 150), 160));
    local bytes = T{};
    local zero_run = 0;
    for off = 0, length - 1 do
        local byte_value = read_u8(ptr + off);
        if (byte_value == nil) then
            break;
        end

        if (byte_value == 0) then
            zero_run = zero_run + 1;
            if (zero_run >= 8 and #bytes > 0) then
                break;
            end
        else
            zero_run = 0;
        end

        if (accessxi.probe_printable_ascii ~= nil and accessxi.probe_printable_ascii(byte_value)) then
            bytes:append(string.char(byte_value));
        elseif (byte_value == 0x09 or byte_value == 0x0A or byte_value == 0x0D) then
            bytes:append(' ');
        end
    end

    return accessxi.chat_log_clean_native_text(bytes:concat(''));
end

accessxi.chat_log_pair_text_from_ptr = function (ptr, length)
    ptr = tonumber(ptr) or 0;
    if (not accessxi.is_probe_pointer(ptr)) then
        return '';
    end

    length = math.max(16, math.min(tonumber(length) or (tonumber(accessxi.chat_log_max_line_len) or 150), 160));
    local bytes = T{};
    local zero_pairs = 0;
    for off = 0, (length * 2) - 2, 2 do
        local lo = read_u8(ptr + off);
        local hi = read_u8(ptr + off + 1);
        if (lo == nil or hi == nil) then
            break;
        end

        if (lo == 0 and hi == 0) then
            zero_pairs = zero_pairs + 1;
            if (zero_pairs >= 4 and #bytes > 0) then
                break;
            end
        else
            zero_pairs = 0;
        end

        if (lo >= 32 and lo <= 126) then
            bytes:append(string.char(lo));
        elseif (hi >= 32 and hi <= 126 and lo == 0) then
            bytes:append(string.char(hi));
        elseif (lo == 0x09 or lo == 0x0A or lo == 0x0D or hi == 0x09 or hi == 0x0A or hi == 0x0D) then
            bytes:append(' ');
        end
    end

    return accessxi.chat_log_clean_native_text(bytes:concat(''));
end

accessxi.chat_log_builder_resolve = function ()
    local callsite = tonumber(accessxi.ptrs.chatlog_builder_callsite) or 0;
    if (accessxi.is_probe_pointer(callsite)) then
        return callsite;
    end

    callsite = tonumber(ashita.memory.find(0, 0, '85C0753B8B15????????8D4C243C0FBF4232506800020000518D4C2424E8', 0x00, 0)) or 0;
    if (not accessxi.is_probe_pointer(callsite)) then
        return 0;
    end

    accessxi.ptrs.chatlog_builder_callsite = callsite;
    accessxi.ptrs.chatlog_logwindo_global = read_u32(callsite + 0x06) or 0;

    local call_addr = callsite + 0x1D;
    local rel = read_i32(call_addr + 0x01);
    if (rel ~= nil) then
        accessxi.ptrs.chatlog_copy_func = call_addr + 0x05 + rel;
    end

    if ((read_u8(callsite - 0x29) or 0) == 0x68) then
        accessxi.ptrs.chatlog_builder_scratch = read_u32(callsite - 0x28) or 0;
    elseif ((read_u8(callsite - 0x59) or 0) == 0xBF) then
        accessxi.ptrs.chatlog_builder_scratch = read_u32(callsite - 0x58) or 0;
    end

    return callsite;
end

accessxi.chat_log_native_line_from_builder = function (state)
    local callsite = accessxi.chat_log_builder_resolve();
    if (not accessxi.is_probe_pointer(callsite)) then
        return nil;
    end

    local logglobal = tonumber(accessxi.ptrs.chatlog_logwindo_global) or 0;
    local logobj = accessxi.is_probe_pointer(logglobal) and (read_u32(logglobal) or 0) or 0;
    local scratch = tonumber(accessxi.ptrs.chatlog_builder_scratch) or 0;
    if (not accessxi.is_probe_pointer(logobj) or not accessxi.is_probe_pointer(scratch)) then
        return nil;
    end

    local selected = tonumber(read_u16(logobj + 0x32)) or -1;
    local cursor = state ~= nil and (tonumber(state.cursor) or -1) or -1;
    local bottom = state ~= nil and (tonumber(state.bottom) or -1) or -1;
    local ascii = accessxi.chat_log_ascii_text_from_ptr(scratch, accessxi.chat_log_max_line_len);
    local pair = accessxi.chat_log_pair_text_from_ptr(scratch, accessxi.chat_log_max_line_len);
    local text = pair;
    local mode = 'pair';
    if ((accessxi.chat_log_candidate_score(ascii) or 0) > (accessxi.chat_log_candidate_score(pair) or 0)) then
        text = ascii;
        mode = 'ascii';
    end

    local speech = accessxi.chat_log_speech_text(text);
    local quality = accessxi.chat_log_plain_text_quality_ok(speech, false)
        and #speech <= (tonumber(accessxi.chat_log_max_line_len) or 150);
    local log_key = ('0x%08X:0x%08X:0x%08X:%d:%d:%d:%s:%s'):fmt(
        callsite,
        logglobal,
        scratch,
        selected,
        cursor,
        bottom,
        mode,
        text);
    if (log_key ~= (accessxi.chat_log_builder_last_probe or '')) then
        accessxi.chat_log_builder_last_probe = log_key;
        log_state(('state chatlog builder-source callsite=0x%08X logglobal=0x%08X logobj=0x%08X scratch=0x%08X copy=0x%08X selected=%d cursor=%d bottom=%d mode="%s" quality=%d ascii="%s" pair="%s" text="%s" scratchBytes=%s'):fmt(
            callsite,
            logglobal,
            logobj,
            scratch,
            tonumber(accessxi.ptrs.chatlog_copy_func) or 0,
            selected,
            cursor,
            bottom,
            mode,
            quality and 1 or 0,
            accessxi.escape_probe_log_text(ascii),
            accessxi.escape_probe_log_text(pair),
            accessxi.escape_probe_log_text(text),
            accessxi.format_probe_bytes(scratch, 0, 0x80)));
    end

    if (not quality or speech == '') then
        return nil;
    end

    local row = T{
        text = text,
        source = ('fulllog-builder-scratch@0x%08X'):fmt(scratch),
        score = 50000,
        chat_log_menu_nav = true,
        chat_log_row_selected = selected,
        chat_log_row_count = math.max(tonumber(bottom) or 0, selected),
        chat_log_selection_reason = 'native-builder-copy',
        visible_signature = ('builder:%d:%d:%s'):fmt(selected, cursor, speech),
        chat_log_should_speak = true,
    };
    return row;
end

accessxi.chat_log_candidate_score = function (text)
    text = tostring(text or '');
    if (text == '') then
        return 0;
    end

    local score = math.min(#text, 60);
    if (accessxi.chat_log_has_time(text)) then
        score = score + 100;
    end
    if (text:find('%a') ~= nil) then
        score = score + 20;
    end
    if (text:match('^[%w%s%p]+$') ~= nil) then
        score = score + 5;
    end
    if (text:find('%[Addons%]%s+Loaded addon:') ~= nil) then
        score = score - 105;
    end
    if (text:find('%[Ashita%]%s+Bound:') ~= nil) then
        score = score - 80;
    end
    if (#text > (tonumber(accessxi.chat_log_max_line_len) or 150)) then
        score = score - 100;
    end
    return score;
end

accessxi.chat_log_trusted_source = function (source)
    source = tostring(source or '');
    if (source:find('chatnode+fulllogptr+', 1, true) ~= nil
        and source:find('+scan+', 1, true) == nil
        and source:find('+ffxi16', 1, true) == nil) then
        return false;
    end
    return accessxi.chat_log_visible_row_source(source)
        or source:find('obj+0C+18', 1, true) ~= nil
        or source:find('sg.fast.child+018', 1, true) ~= nil
        or source:find('chatnode+', 1, true) ~= nil;
end

accessxi.chat_log_visible_row_source = function (source)
    source = tostring(source or '');
    return source:find('fulllog+obj', 1, true) ~= nil
        or source:find('obj+88', 1, true) ~= nil
        or source:find('obj+8C', 1, true) ~= nil
        or source:find('obj+90', 1, true) ~= nil
        or source:find('obj+94', 1, true) ~= nil
        or source:find('obj+98', 1, true) ~= nil
        or source:find('obj+9C', 1, true) ~= nil
        or source:find('obj+A0', 1, true) ~= nil;
end

accessxi.chat_log_visible_fragment_source = function (source)
    source = tostring(source or '');
    return source:find('rowrun', 1, true) ~= nil
        and accessxi.chat_log_visible_row_source(source);
end

accessxi.chat_log_direct_line_source = function (source)
    source = tostring(source or '');
    return source:find('obj+08@', 1, true) ~= nil
        and source:find('obj+08.chain', 1, true) == nil
        and source:find('obj+08.rel', 1, true) == nil;
end

    accessxi.chat_log_chain_line_source = function (source)
    source = tostring(source or '');
    return source:find('obj+08.chain', 1, true) ~= nil
        and source:find('obj+08.rel', 1, true) == nil;
end

accessxi.chat_log_scan_source = function (source)
    source = tostring(source or '');
    return source:find('scanascii', 1, true) ~= nil
        or source:find('scanrow', 1, true) ~= nil;
end

accessxi.chat_log_plain_text_quality_ok = function (text, require_words)
    text = tostring(text or '');
    if (text == '') then
        return false;
    end

    local printable = 0;
    local bad = 0;
    local letters = 0;
    local spaces = 0;
    for i = 1, #text do
        local b = text:byte(i) or 0;
        if (b >= 32 and b <= 126) then
            printable = printable + 1;
            if (b >= 65 and b <= 90) or (b >= 97 and b <= 122) then
                letters = letters + 1;
            elseif (b == 32) then
                spaces = spaces + 1;
            end
        else
            bad = bad + 1;
        end
    end
    if (printable <= 0 or bad > 0) then
        return false;
    end
    if (letters < 3) then
        return false;
    end
    if (require_words == true) then
        if (spaces <= 0) then
            return false;
        end
        local word_count = 0;
        for _ in text:gmatch('%a%a+') do
            word_count = word_count + 1;
            if (word_count >= 2) then
                break;
            end
        end
        if (word_count < 2) then
            return false;
        end
    end
    if (text:match('^%w+$') ~= nil) then
        return false;
    end
    return true;
end

accessxi.chat_log_visible_scan_text_quality_ok = function (text)
    text = tostring(text or '');
    if (text == '') then
        return false;
    end

    local max_len = tonumber(accessxi.chat_log_max_line_len) or 150;
    if (#text < 3 or #text > max_len) then
        return false;
    end
    if (text:match('^[%p%s]+$') ~= nil) then
        return false;
    end
    if (accessxi.chat_log_has_suspicious_noise(text)) then
        return false;
    end

    local printable = 0;
    local bad = 0;
    local letters = 0;
    for i = 1, #text do
        local b = text:byte(i) or 0;
        if (b >= 32 and b <= 126) then
            printable = printable + 1;
            if ((b >= 65 and b <= 90) or (b >= 97 and b <= 122)) then
                letters = letters + 1;
            end
        else
            bad = bad + 1;
        end
    end
    if (printable <= 0 or bad > 0 or letters < 3) then
        return false;
    end

    local lower = text:lower():trim();
    if (lower == 'menu'
        or lower == 'font'
        or lower == 'fulllog'
        or lower == 'logwindo'
        or lower == 'inline') then
        return false;
    end
    if (text:find('%s') == nil and #text < 5) then
        return false;
    end
    if (text:find('%s') == nil and text:match('^[A-Za-z]+$') == nil) then
        return false;
    end
    if (text:match('^%d+$') ~= nil or text:match('^%x%x%x%x%x%x%x%x$') ~= nil) then
        return false;
    end
    if (lower:find('menu    ', 1, true) ~= nil
        or lower:find('state chatlog ', 1, true) ~= nil
        or lower:find('chatprobe ', 1, true) ~= nil) then
        return false;
    end
    return true;
end

accessxi.chat_log_has_suspicious_noise = function (text)
    text = tostring(text or '');
    if (text == '') then
        return true;
    end

    if (text:find('| +', 1, true) ~= nil
        or text:find('@fq#', 1, true) ~= nil
        or text:find('@oos~v', 1, true) ~= nil
        or text:find('H#', 1, true) ~= nil
        or text:find('H0#', 1, true) ~= nil
        or text:find('KI%', 1, true) ~= nil
        or text:find('edj:', 1, true) ~= nil
        or text:find('ce&', 1, true) ~= nil
        or text:find('AKQ#', 1, true) ~= nil
        or text:find('=AK', 1, true) ~= nil
        or text:match('AK$') ~= nil
        or text:find('=eO', 1, true) ~= nil
        or text:find('=bP', 1, true) ~= nil
        or text:find('/PE', 1, true) ~= nil
        or text:find('eOj', 1, true) ~= nil
        or text:find('{Q', 1, true) ~= nil
        or text:find('?^', 1, true) ~= nil
        or text:find('^L', 1, true) ~= nil
        or text:find('Qa1', 1, true) ~= nil
        or text:find('*[j', 1, true) ~= nil
        or text:find('ar> yar', 1, true) ~= nil
        or text:find('%%', 1, true) ~= nil
        or text:find('&&', 1, true) ~= nil) then
        return true;
    end
    if (text:find('Loaded addon:[^%s]') ~= nil) then
        return true;
    end
    if (text:find('[%+%%@/&][%+%%@/&]') ~= nil) then
        return true;
    end
    return false;
end

accessxi.chat_log_candidate_ok = function (text, source)
    text = tostring(text or '');
    source = tostring(source or '');
    if (text == '') then
        return false;
    end
    if (source:find('chatnode+fulllogptr+', 1, true) ~= nil
        and accessxi.chat_log_has_time(text) == false) then
        return false;
    end
    if (accessxi.chat_log_has_suspicious_noise(text)) then
        return false;
    end
    if (accessxi.chat_log_has_time(text)) then
        return accessxi.chat_log_plain_text_quality_ok(text, false);
    end
    if (accessxi.chat_log_visible_row_source(source) and accessxi.chat_log_scan_source(source)) then
        if (#text < 3 or #text > (tonumber(accessxi.chat_log_max_line_len) or 150)) then
            return false;
        end
        if (text:find('%w') == nil) then
            return false;
        end
        return accessxi.chat_log_visible_scan_text_quality_ok(text);
    end
    if (accessxi.chat_log_visible_fragment_source(source)) then
        if (#text < 8 or #text > (tonumber(accessxi.chat_log_max_line_len) or 150)) then
            return false;
        end
        if (text:find('%a') == nil) then
            return false;
        end
        if (text:find('%s') == nil and text:find('{', 1, true) == nil) then
            return false;
        end
        return accessxi.chat_log_plain_text_quality_ok(text, false);
    end
    if (not accessxi.chat_log_trusted_source(source)) then
        return false;
    end
    if (#text < 3 or #text > (tonumber(accessxi.chat_log_max_line_len) or 150)) then
        return false;
    end
    if (text:find('%a') == nil) then
        return false;
    end
    if (not accessxi.chat_log_plain_text_quality_ok(text, true)) then
        return false;
    end
    local lower = text:lower();
    if (lower:eq('jj jj', true)
        or lower:eq('jjj', true)
        or lower:find('menu    ', 1, true) ~= nil) then
        return false;
    end
    return true;
end

accessxi.chat_log_global_state_from_menu_obj = function (obj, menu_name)
    obj = tonumber(obj) or 0;
    menu_name = tostring(menu_name or '');
    if (not accessxi.is_probe_pointer(obj) or not is_chat_log_menu_name(menu_name)) then
        return nil;
    end
    if (menu_name:lower():find('fulllog', 1, true) == nil) then
        return nil;
    end

    local desc = read_u32(obj + 0x04) or 0;
    local candidates = T{};
    local function add_data_candidate(source, slot, data)
        candidates:append(T{
            source = tostring(source or ''),
            slot = tonumber(slot) or 0,
            data = tonumber(data) or 0,
        });
    end

    add_data_candidate('obj+0C', obj + 0x0C, read_u32(obj + 0x0C) or 0);

    local function count_rows_for_data(data)
        data = tonumber(data) or 0;
        if (not accessxi.is_probe_pointer(data)) then
            return 0, T{};
        end

        local row_count = 0;
        local row_ptrs = T{};
        for i = 0, 29 do
            local row = read_u32(data + 0x80 + (i * 4)) or 0;
            if (not accessxi.is_probe_pointer(row)) then
                break;
            end
            row_count = row_count + 1;
            row_ptrs:append(row);
        end
        return row_count, row_ptrs;
    end

    local chosen = nil;
    local chosen_rows = T{};
    for _, candidate in ipairs(candidates) do
        local row_count, row_ptrs = count_rows_for_data(candidate.data);
        local cursor = tonumber(read_i32(candidate.data + 0x1C)) or -1;
        local bottom = tonumber(read_i32(candidate.data + 0x58)) or -1;
        if (row_count >= 2
            and row_count <= 30
            and cursor >= 0
            and cursor <= 10000
            and bottom >= 0
            and bottom <= 10000) then
            candidate.row_count = row_count;
            candidate.cursor = cursor;
            candidate.bottom = bottom;
            chosen = candidate;
            chosen_rows = row_ptrs;
            break;
        end
    end

    local global_slot = chosen ~= nil and (tonumber(chosen.slot) or 0) or 0;
    local data = chosen ~= nil and (tonumber(chosen.data) or 0) or 0;
    local source = chosen ~= nil and tostring(chosen.source or '') or '';
    if (not accessxi.is_probe_pointer(data)) then
        return T{
            obj = obj,
            desc = desc,
            global_slot = global_slot,
            data = data,
            menu_name = menu_name,
            full_log_menu = true,
            source = source,
            cursor = -1,
            bottom = -1,
            row_count = 0,
            row_window_top = -1,
            row_window_bottom = -1,
            selected_index_unclamped = -1,
            selected_index = -1,
            selected_row = 0,
            row_ptrs = T{},
            cursor_in_row_window = false,
        };
    end

    local row_count = 0;
    local row_ptrs = T{};
    row_count = tonumber(chosen.row_count) or 0;
    row_ptrs = chosen_rows;

    local cursor = tonumber(chosen.cursor) or -1;
    local bottom = tonumber(chosen.bottom) or -1;
    local row_window_top = -1;
    local row_window_bottom = -1;
    local selected_index_unclamped = -1;
    local selected_index = -1;
    local selected_row = 0;
    local cursor_in_row_window = false;
    if (row_count > 0 and cursor >= 0 and bottom >= 0) then
        row_window_bottom = bottom;
        row_window_top = bottom - row_count + 1;
        cursor_in_row_window = cursor >= row_window_top and cursor <= row_window_bottom;
        selected_index_unclamped = row_count - 1 - (bottom - cursor);
        selected_index = selected_index_unclamped;
        if (selected_index < 0) then
            selected_index = 0;
        elseif (selected_index >= row_count) then
            selected_index = row_count - 1;
        end
        selected_row = tonumber(row_ptrs[selected_index + 1]) or 0;
    end

    return T{
        obj = obj,
        desc = desc,
        global_slot = global_slot,
        data = data,
        menu_name = menu_name,
        full_log_menu = true,
        source = source,
        cursor = cursor,
        bottom = bottom,
        row_count = row_count,
        row_window_top = row_window_top,
        row_window_bottom = row_window_bottom,
        selected_index_unclamped = selected_index_unclamped,
        selected_index = selected_index,
        selected_row = selected_row,
        row_ptrs = row_ptrs,
        cursor_in_row_window = cursor_in_row_window,
    };
end

accessxi.chat_log_row_window_signature = function (state)
    if (state == nil or state.row_ptrs == nil) then
        return '';
    end

    local row_count = tonumber(state.row_count) or 0;
    if (row_count <= 0) then
        return '';
    end

    local parts = T{};
    local seen = {};
    local function add_index(index)
        index = tonumber(index) or 0;
        if (index < 1 or index > row_count or seen[index] == true) then
            return;
        end
        seen[index] = true;

        local row = tonumber(state.row_ptrs[index]) or 0;
        if (not accessxi.is_probe_pointer(row)) then
            parts:append(('%02d=0'):fmt(index));
            return;
        end

        local head = read_u32(row + 0x04) or 0;
        local tail = read_u32(row + 0x08) or 0;
        local count_a = read_u32(row + 0x14) or 0;
        local count_b = read_u32(row + 0x18) or 0;
        local head_child = accessxi.is_probe_pointer(head) and (read_u32(head + 0x10) or 0) or 0;
        local tail_child = accessxi.is_probe_pointer(tail) and (read_u32(tail + 0x10) or 0) or 0;
        parts:append(('%02d:%08X:%08X:%08X:%08X:%08X:%08X:%08X'):fmt(
            index,
            row,
            head,
            tail,
            count_a,
            count_b,
            head_child,
            tail_child));
    end

    add_index(1);
    add_index(2);
    add_index(3);
    add_index(row_count - 2);
    add_index(row_count - 1);
    add_index(row_count);

    local data = tonumber(state.data) or 0;
    if (accessxi.is_probe_pointer(data)) then
        for _, off in ipairs(T{ 0x10, 0x14, 0x18, 0x20, 0x24, 0x28, 0x2C, 0x30, 0x34, 0x38, 0x3C, 0x54, 0x5C, 0x60, 0x64, 0x68, 0x6C, 0x70, 0x74, 0x78 }) do
            parts:append(('%02X=%08X'):fmt(off, read_u32(data + off) or 0));
        end
    end

    local obj = tonumber(state.obj) or 0;
    if (accessxi.is_probe_pointer(obj)) then
        for _, off in ipairs(T{ 0x08, 0x10, 0x14, 0x18, 0x20, 0x24, 0x28, 0x2C, 0x30, 0x34, 0x38, 0x3C, 0x40, 0x44, 0x48, 0x4C, 0x50, 0x54, 0x58, 0x5C, 0x80, 0x84, 0x88, 0x8C, 0x90, 0x94 }) do
            parts:append(('o%02X=%08X'):fmt(off, read_u32(obj + off) or 0));
        end
        for _, off in ipairs(T{ 0x08, 0x88, 0x8C, 0x90 }) do
            local ptr = read_u32(obj + off) or 0;
            if (accessxi.is_probe_pointer(ptr)) then
                parts:append(('p%02X=%s'):fmt(off, accessxi.format_probe_dwords(ptr, 0, 8)));
            end
        end
    end

    return parts:concat(',');
end

accessxi.chat_log_cursor_is_in_rendered_row_window = function (state)
    return state ~= nil and state.cursor_in_row_window ~= false;
end

accessxi.chat_log_selected_row_pointer_usable = function (state)
    return state ~= nil and accessxi.is_probe_pointer(state.selected_row);
end

accessxi.chat_log_selected_row_pointer_probe = function (row_ptr)
    row_ptr = tonumber(row_ptr) or 0;
    if (not accessxi.is_probe_pointer(row_ptr)) then
        return '';
    end

    local parts = T{};
    local seen = {};
    for _, off in ipairs(T{ 0x04, 0x08, 0x3C, 0x40, 0x74, 0x78, 0xAC, 0xB0, 0xE0, 0xE4 }) do
        local ptr = read_u32(row_ptr + off) or 0;
        if (accessxi.is_probe_pointer(ptr) and seen[ptr] ~= true) then
            seen[ptr] = true;
            local ascii = accessxi.probe_runs_to_text(accessxi.collect_probe_ascii_runs(ptr, 0x140, 3, 3));
            local utf16 = accessxi.probe_runs_to_text(accessxi.collect_probe_utf16_runs(ptr, 0x140, 3, 3));
            local ffxi16 = accessxi.probe_runs_to_text(accessxi.collect_probe_ffxi_utf16_runs(ptr, 0x140, 3, 3));
            parts:append(('+%02X=0x%08X d=%s ascii="%s" utf16="%s" ffxi16="%s"'):fmt(
                off,
                ptr,
                accessxi.format_probe_dwords(ptr, 0, 8),
                accessxi.escape_probe_log_text(ascii),
                accessxi.escape_probe_log_text(utf16),
                accessxi.escape_probe_log_text(ffxi16)));
            if (#parts >= 8) then
                break;
            end
        end
    end

    return parts:concat(' | ');
end

accessxi.chat_log_selected_row_chain_probe = function (row_ptr)
    row_ptr = tonumber(row_ptr) or 0;
    if (not accessxi.is_probe_pointer(row_ptr)) then
        return '';
    end

    local head = read_u32(row_ptr + 0x04) or 0;
    local tail = read_u32(row_ptr + 0x08) or 0;
    local count_a = read_u32(row_ptr + 0x14) or 0;
    local count_b = read_u32(row_ptr + 0x18) or 0;
    if (not accessxi.is_probe_pointer(head)) then
        return ('head=0x%08X tail=0x%08X count=%d/%d'):fmt(head, tail, count_a, count_b);
    end

    local parts = T{};
    local seen = {};
    local node = head;
    local limit = math.min(math.max(tonumber(count_a) or 0, tonumber(count_b) or 0, 1), 24);
    local index = 0;
    while (accessxi.is_probe_pointer(node) and seen[node] ~= true and index < limit) do
        seen[node] = true;
        local next_node = read_u32(node + 0x00) or 0;
        local f10 = read_u32(node + 0x10) or 0;
        local f14 = read_u32(node + 0x14) or 0;
        local f18 = read_u32(node + 0x18) or 0;
        local f1c = read_u32(node + 0x1C) or 0;
        local f20 = read_u32(node + 0x20) or 0;
        local f24 = read_u32(node + 0x24) or 0;
        parts:append(('%02d@0x%08X n=0x%08X f10=0x%08X f14=0x%08X f18=0x%08X f1C=0x%08X f20=0x%08X f24=0x%08X'):fmt(
            index, node, next_node, f10, f14, f18, f1c, f20, f24));
        node = next_node;
        index = index + 1;
    end

    return ('head=0x%08X tail=0x%08X count=%d/%d nodes=%s'):fmt(
        head,
        tail,
        count_a,
        count_b,
        parts:concat(' ; '));
end

accessxi.chat_log_selected_row_chain_detail = function (state)
    if (state == nil or not accessxi.is_probe_pointer(state.selected_row)) then
        return;
    end
    if (tick() > (accessxi.chat_log_probe_until or 0)) then
        return;
    end

    local row_ptr = tonumber(state.selected_row) or 0;
    local head = read_u32(row_ptr + 0x04) or 0;
    local tail = read_u32(row_ptr + 0x08) or 0;
    local count_a = read_u32(row_ptr + 0x14) or 0;
    local count_b = read_u32(row_ptr + 0x18) or 0;
    if (not accessxi.is_probe_pointer(head)) then
        return;
    end

    local log_key = ('0x%08X:%d:%d:%08X'):fmt(
        row_ptr,
        tonumber(state.cursor) or -1,
        tonumber(state.selected_index) or -1,
        head);
    if (log_key == (accessxi.chat_log_rowchain_detail_last_probe or '')) then
        return;
    end
    accessxi.chat_log_rowchain_detail_last_probe = log_key;

    local nodes = T{};
    local seen = {};
    local node = head;
    local limit = math.min(math.max(tonumber(count_a) or 0, tonumber(count_b) or 0, 1), 24);
    while (accessxi.is_probe_pointer(node) and seen[node] ~= true and #nodes < limit) do
        seen[node] = true;
        nodes:append(node);
        node = read_u32(node + 0x00) or 0;
    end

    local node_parts = T{};
    for i, node_ptr in ipairs(nodes) do
        local next_node = read_u32(node_ptr + 0x00) or 0;
        local child = read_u32(node_ptr + 0x10) or 0;
        local child_dwords = accessxi.is_probe_pointer(child) and accessxi.format_probe_dwords(child, 0, 6) or '';
        local child_ascii = '';
        local child_utf16 = '';
        if (accessxi.is_probe_pointer(child)) then
            child_ascii = accessxi.probe_runs_to_text(accessxi.collect_probe_ascii_runs(child, 0x80, 2, 2));
            child_utf16 = accessxi.probe_runs_to_text(accessxi.collect_probe_utf16_runs(child, 0x80, 2, 2));
        end
        node_parts:append(('%02d@0x%08X n=0x%08X d=%s c10=0x%08X cd=%s ca="%s" cu="%s"'):fmt(
            i - 1,
            node_ptr,
            next_node,
            accessxi.format_probe_dwords(node_ptr, 0, 12),
            child,
            child_dwords,
            accessxi.escape_probe_log_text(child_ascii),
            accessxi.escape_probe_log_text(child_utf16)));
    end

    local byte_parts = T{};
    for off = 0x04, 0x3F do
        local chars = T{};
        local hex = T{};
        local printable = 0;
        for _, node_ptr in ipairs(nodes) do
            local b = read_u8(node_ptr + off) or 0;
            hex:append(('%02X'):fmt(b));
            if (b >= 0x20 and b <= 0x7E) then
                printable = printable + 1;
                chars:append(string.char(b));
            else
                chars:append('.');
            end
        end
        if (printable >= math.max(3, math.floor(#nodes / 2))) then
            byte_parts:append(('+%02X="%s"[%s]'):fmt(off, chars:concat(''), hex:concat(' ')));
        end
    end

    local word_parts = T{};
    for off = 0x04, 0x3E, 2 do
        local chars = T{};
        local hex = T{};
        local printable = 0;
        for _, node_ptr in ipairs(nodes) do
            local w = read_u16(node_ptr + off) or 0;
            hex:append(('%04X'):fmt(w));
            if (w >= 0x20 and w <= 0x7E) then
                printable = printable + 1;
                chars:append(string.char(w));
            else
                chars:append('.');
            end
        end
        if (printable >= math.max(3, math.floor(#nodes / 2))) then
            word_parts:append(('+%02X="%s"[%s]'):fmt(off, chars:concat(''), hex:concat(' ')));
        end
    end

    log_state(('state chatlog rowchain-detail row=0x%08X cursor=%d bottom=%d selectedIndex=%d head=0x%08X tail=0x%08X count=%d/%d nodes=%d bytes="%s" words="%s" nodeDetails="%s"'):fmt(
        row_ptr,
        tonumber(state.cursor) or -1,
        tonumber(state.bottom) or -1,
        tonumber(state.selected_index) or -1,
        head,
        tail,
        count_a,
        count_b,
        #nodes,
        byte_parts:concat(' | '),
        word_parts:concat(' | '),
        node_parts:concat(' || ')));
end

accessxi.chat_log_rendered_glyph_entries_from_ptr = function (ptr, length, min_len, limit)
    ptr = tonumber(ptr) or 0;
    if (not accessxi.is_probe_pointer(ptr)) then
        return T{};
    end

    length = tonumber(length) or 0x28;
    min_len = tonumber(min_len) or 2;
    limit = tonumber(limit) or 8;
    local entries = T{};
    local run = T{};
    local run_start = 0;

    local function flush_run()
        if (#run <= 0) then
            return;
        end

        local text = accessxi.chat_log_clean_native_text(run:concat(''));
        text = accessxi.chat_log_speech_text(text);
        if (#text >= min_len and #text <= (tonumber(accessxi.chat_log_max_line_len) or 150)
            and text:find('%a') ~= nil
            and text:lower():find('menu    ', 1, true) == nil
            and not accessxi.chat_log_has_suspicious_noise(text)) then
            entries:append(T{ offset = run_start, text = text });
        end
        run = T{};
    end

    for off = 0, length - 1 do
        local byte_value = read_u8(ptr + off);
        local decoded = nil;
        if (byte_value ~= nil and byte_value >= 0x40 and byte_value <= 0xFC and (byte_value % 2) == 0) then
            local candidate = byte_value / 2;
            if (candidate >= 0x20 and candidate <= 0x7E) then
                decoded = candidate;
            end
        end

        if (decoded ~= nil) then
            if (#run == 0) then
                run_start = off;
            end
            run:append(string.char(decoded));
        else
            flush_run();
            if (#entries >= limit) then
                return entries;
            end
        end
    end
    flush_run();

    while (#entries > limit) do
        table.remove(entries, #entries);
    end
    return entries;
end

accessxi.chat_log_selected_row_glyph_text = function (state)
    if (state == nil or not accessxi.is_probe_pointer(state.selected_row)) then
        return nil, '';
    end

    local row_ptr = tonumber(state.selected_row) or 0;
    local head = read_u32(row_ptr + 0x04) or 0;
    local count_a = read_u32(row_ptr + 0x14) or 0;
    local count_b = read_u32(row_ptr + 0x18) or 0;
    if (not accessxi.is_probe_pointer(head)) then
        return nil, '';
    end

    local nodes = T{};
    local seen = {};
    local node = head;
    local limit = math.min(math.max(tonumber(count_a) or 0, tonumber(count_b) or 0, 1), 32);
    while (accessxi.is_probe_pointer(node) and seen[node] ~= true and #nodes < limit) do
        seen[node] = true;
        nodes:append(node);
        node = read_u32(node + 0x00) or 0;
    end

    local words = T{};
    local detail = T{};
    for index, node_ptr in ipairs(nodes) do
        local child = read_u32(node_ptr + 0x10) or 0;
        if (accessxi.is_probe_pointer(child)) then
            local entries = accessxi.chat_log_rendered_glyph_entries_from_ptr(child, 0x90, 2, 10);
            local node_words = T{};
            for _, entry in ipairs(entries) do
                local text = tostring(entry.text or ''):trim();
                if (text ~= '') then
                    node_words:append(text);
                end
            end
            if (#node_words > 0) then
                local node_text = node_words:concat(' '):gsub('%s+', ' '):trim();
                words:append(node_text);
                detail:append(('%02d@0x%08X child=0x%08X "%s"'):fmt(
                    index - 1,
                    node_ptr,
                    child,
                    accessxi.escape_probe_log_text(node_text)));
            end
        end
    end

    local text = accessxi.chat_log_clean_native_text(words:concat(' '));
    text = accessxi.chat_log_speech_text(text);
    text = text:gsub('%s+', ' '):trim();
    text = text:gsub('^(%[[^%]]+%])%s+%1%s+', '%1 ');
    if (text == '' or #text > (tonumber(accessxi.chat_log_max_line_len) or 150)) then
        detail:append(('combined="%s"'):fmt(accessxi.escape_probe_log_text(text)));
        return nil, detail:concat(' | ');
    end
    if (not accessxi.chat_log_selected_row_glyph_quality_ok(text)) then
        detail:append(('combined="%s"'):fmt(accessxi.escape_probe_log_text(text)));
        return nil, detail:concat(' | ');
    end

    return T{
        text = text,
        source = ('fulllog-selected-row-glyph@0x%08X'):fmt(row_ptr),
        score = 44500,
        chat_log_menu_nav = true,
        chat_log_row_selected = tonumber(state.selected_index) or 0,
        chat_log_row_count = tonumber(state.row_count) or 0,
        chat_log_selection_reason = 'native-fulllog-selected-row-glyph',
        visible_signature = ('%d:%d:0x%08X:%s'):fmt(
            tonumber(state.cursor) or -1,
            tonumber(state.bottom) or -1,
            row_ptr,
            text),
    }, detail:concat(' | ');
end

accessxi.chat_log_selected_source_record_text = function (ptr)
    ptr = tonumber(ptr) or 0;
    if (not accessxi.is_probe_pointer(ptr)) then
        return nil, '';
    end

    local best = nil;
    local best_detail = T{};
    local seen = {};
    for _, off in ipairs(T{ 0x00, 0x04, 0x08, 0x0C, 0x18, 0x20, 0x28, 0x30, 0x38, 0x40 }) do
        local text_ptr = ptr + off;
        if (seen[text_ptr] ~= true) then
            seen[text_ptr] = true;
            local raw = accessxi.chat_log_string_text_from_ptr(text_ptr, accessxi.chat_log_max_line_len);
            if (raw == '') then
                raw = accessxi.chat_log_ascii_text_from_ptr(text_ptr, accessxi.chat_log_max_line_len);
            end

            local text = accessxi.chat_log_speech_text(raw);
            text = accessxi.chat_log_repair_selected_source_text(text);
            local lower = text:lower();
            local quality = accessxi.chat_log_plain_text_quality_ok(text, false)
                and #text <= (tonumber(accessxi.chat_log_max_line_len) or 150)
                and text:find('%[[^%]]*$') == nil
                and lower:find('menu    ', 1, true) == nil
                and lower:find('chatrecscan', 1, true) == nil
                and lower:find('chatbufscan', 1, true) == nil
                and lower:find('chatptrscan', 1, true) == nil;

            best_detail:append(('+%02X="%s"%s'):fmt(
                off,
                accessxi.escape_probe_log_text(text),
                quality and '*' or ''));

            if (quality and (best == nil or #text > #(best.text or ''))) then
                best = T{
                    text = text,
                    text_ptr = text_ptr,
                    source_offset = off,
                };
            end
        end
    end

    return best, best_detail:concat(' | ');
end

accessxi.chat_log_repair_selected_source_text = function (text)
    text = tostring(text or ''):gsub('%z', ' '):gsub('%s+', ' '):trim();
    if (text == '') then
        return '';
    end

    do
        local marker_start, marker_end = text:find('WW!(j;=;=;', 1, true);
        if (marker_start ~= nil and marker_end ~= nil) then
            text = text:sub(marker_end + 1);
        end
    end
    do
        local marker_start, marker_end = text:find("'?:'?F", 1, true);
        if (marker_start ~= nil and marker_end ~= nil) then
            text = text:sub(marker_end + 1);
        end
    end
    do
        local marker_start, marker_end = text:find(';=', 1, true);
        if (marker_start ~= nil and marker_end ~= nil) then
            local suffix = text:sub(marker_end + 1):gsub('%s+', ' '):trim();
            local letters = 0;
            for _ in suffix:gmatch('%a') do
                letters = letters + 1;
            end
            if (letters >= 4) then
                text = suffix;
            end
        end
    end

    text = text:gsub('^WW!%(j;=;=;', '');
    text = text:gsub("^o%)%?o%)%?", '');
    text = text:gsub('^O,O4O`,wa%s*;=', '');
    text = text:gsub('^O,O4O`,w%s*;=', '');
    text = text:gsub('^OOO`,w%s*;=', '');
    text = text:gsub('^OOO`,w%s+', '');
    text = text:gsub('^PPttAD`', '');
    text = text:gsub('^ttAD`', '');
    text = text:gsub('^hh``', '');
    text = text:gsub('^%w%w%w:%u@%s+', '');
    text = text:gsub('^%w+:%u@%s+', '');
    text = text:gsub('^[Pp]?[Gg][Hh]m3W/%s*7P%?d,%?,%s*AT', 'at');
    text = text:gsub('^[Pp]?[Ee][Ff]m3W/%s*7P%?d,%?,%s*', '');
    text = text:gsub('^[Pp]?%u%um3W/%s*7P%?d,%?,%s*AT', 'at');
    text = text:gsub('^[Pp]?%u%um3W/%s*7P%?d,%?,%s*', '');
    text = text:gsub('^[Gg][Hh]=:%u%s+', '');
    text = text:gsub('^[Ee][Ff]%d*:%u%s+', '');
    text = text:gsub('^%d%d%]%s*', '');
    text = text:gsub('^%s+', '');

    text = text:gsub('!CCESS8%)', 'AccessXI');
    text = text:gsub('!CCESS8', 'AccessX');
    text = text:gsub('!RCANA', 'Arcana');
    text = text:gsub('!DDONS', 'Addons');
    text = text:gsub('!SHITA', 'Ashita');
    text = text:gsub('%[!PURURU%]', '{Apururu}');
