accessxi.chat_log_selected_source_quality_ok = function (text)
    text = tostring(text or ''):trim();
    if (not accessxi.chat_log_plain_text_quality_ok(text, false)) then
        return false;
    end
    local lower = text:lower();
    if (text:find('%[[^%]]*$') ~= nil
        or text:find('o)?', 1, true) ~= nil
        or text:find("'?:'?", 1, true) ~= nil
        or text:find('`', 1, true) ~= nil
        or text:find(';=', 1, true) ~= nil
        or text:find('%MINENCE', 1, true) ~= nil
        or lower:find('menu ', 1, true) ~= nil
        or lower:find('keytop', 1, true) ~= nil
        or lower:find('newtex', 1, true) ~= nil
        or lower:find('gauge', 1, true) ~= nil
        or lower:find('font', 1, true) ~= nil
        or text:match('^P+%pH$') ~= nil
        or text:match('^A+[A-Za-z%s_%-]+$') ~= nil
        or text:match('^ACCESS8[%p%s%dA-Z]*$') ~= nil
        or text:match('^Access8[%p%s%dA-Z]*$') ~= nil
        or text:match('^[A-Z]+[%p]+[A-Z]+$') ~= nil
        or lower:find('!ccess', 1, true) ~= nil
        or lower:find('!ddons', 1, true) ~= nil
        or lower:find('!shita', 1, true) ~= nil
        or lower:find('version by!', 1, true) ~= nil
        or text:find(';=;=', 1, true) ~= nil
        or text:find('@`@', 1, true) ~= nil
        or text:find('WW!(', 1, true) ~= nil) then
        return false;
    end

    local letters = 0;
    local digits = 0;
    local spaces = 0;
    local punctuation = 0;
    for i = 1, #text do
        local b = text:byte(i) or 0;
        if ((b >= 65 and b <= 90) or (b >= 97 and b <= 122)) then
            letters = letters + 1;
        elseif (b >= 48 and b <= 57) then
            digits = digits + 1;
        elseif (b == 32) then
            spaces = spaces + 1;
        else
            punctuation = punctuation + 1;
        end
    end

    if (letters < 3) then
        return false;
    end
    if (spaces <= 0 and punctuation > 0 and #text < 8) then
        return false;
    end
    if (spaces <= 0 and digits > 0 and punctuation > 0 and not accessxi.chat_log_has_time(text)) then
        return false;
    end

    local words = 0;
    local short_words = 0;
    local alpha_words = 0;
    local long_words = 0;
    for word in text:gmatch('%S+') do
        words = words + 1;
        local clean = word:gsub('[^A-Za-z]', '');
        if (#clean > 0) then
            alpha_words = alpha_words + 1;
        end
        if (#clean >= 5) then
            long_words = long_words + 1;
        end
        if (#clean <= 3) then
            short_words = short_words + 1;
        end
    end
    if (words > 0 and words <= 3 and alpha_words == words and long_words <= 0 and not accessxi.chat_log_has_time(text)) then
        return false;
    end

    local useful = letters + digits + spaces;
    if ((useful / math.max(#text, 1)) < 0.70) then
        return false;
    end
    if (punctuation > math.max(4, math.floor((letters + spaces) * 0.35))) then
        return false;
    end

    return true;
end

accessxi.chat_log_native_continuation_word_ok = function (text)
    text = accessxi.chat_log_speech_text(text);
    return text == 'Arcana'
        or text:match('^at%s+%d+:%d+%s*%([A-Z][A-Z][A-Z]%)%s*/%s*%d+:%d+%s*%([A-Z][A-Z][A-Z]%)$') ~= nil
        or text:match('^%([A-Z][A-Z][A-Z]%)%s*/%s*%d+:%d+%s*%([A-Z][A-Z][A-Z]%)$') ~= nil;
end

accessxi.chat_log_selected_row_glyph_quality_ok = function (text)
    text = tostring(text or ''):trim();
    if (not accessxi.chat_log_selected_source_quality_ok(text)) then
        return false;
    end

    local lower = text:lower();
    if (text:find('\\', 1, true) ~= nil
        or (text:find(']', 1, true) ~= nil and text:find('[', 1, true) == nil)
        or lower:find('access8', 1, true) ~= nil
        or lower:find('chatlog.[accessx', 1, true) ~= nil
        or lower:find("k7", 1, true) ~= nil
        or text:match('%s%a$') ~= nil
        or text:match('%s%a%a$') ~= nil
        or text:match('%s%a%a%a$') ~= nil) then
        return false;
    end

    if (accessxi.chat_log_has_time(text)
        or (text:find('%[', 1, true) ~= nil and text:find('%]', 1, true) ~= nil)
        or text:find(':', 1, true) ~= nil
        or text:find('.', 1, true) ~= nil
        or text:find('!', 1, true) ~= nil
        or text:find('?', 1, true) ~= nil) then
        return true;
    end

    local words = 0;
    for _ in text:gmatch('%S+') do
        words = words + 1;
    end
    if (words < 8) then
        return false;
    end

    local shortish = 0;
    for word in text:gmatch('%S+') do
        local clean = word:gsub('[^A-Za-z]', '');
        if (#clean > 0 and #clean <= 3) then
            shortish = shortish + 1;
        end
    end
    if (shortish > math.max(2, math.floor(words * 0.35))) then
        return false;
    end

    return true;
end

accessxi.chat_log_rich_render_text_ok = function (text)
    text = accessxi.chat_log_speech_text(text);
    if (not accessxi.chat_log_selected_source_quality_ok(text)) then
        return false;
    end
    if (accessxi.chat_log_has_time(text)) then
        return true;
    end
    if (text:find(' ', 1, true) ~= nil) then
        return true;
    end
    if (text:find('[', 1, true) ~= nil and text:find(']', 1, true) ~= nil) then
        return true;
    end
    if (#text >= 18 and text:find('%p') == nil) then
        return true;
    end
    return false;
end

accessxi.chat_log_selected_source_pointer_probe = function (ptr)
    ptr = tonumber(ptr) or 0;
    if (not accessxi.is_probe_pointer(ptr)) then
        return '';
    end

    local parts = T{};
    local seen = {};
    for off = 0x00, 0x80, 4 do
        local child = read_u32(ptr + off) or 0;
        if (child >= 0x04000000 and accessxi.is_probe_pointer(child) and seen[child] ~= true) then
            seen[child] = true;
            local ascii = accessxi.probe_runs_to_text(accessxi.collect_probe_ascii_runs(child, 0x120, 3, 4));
            local utf16 = accessxi.probe_runs_to_text(accessxi.collect_probe_utf16_runs(child, 0x120, 3, 4));
            local ffxi16 = accessxi.probe_runs_to_text(accessxi.collect_probe_ffxi_utf16_runs(child, 0x120, 3, 4));
            parts:append(('+%02X=0x%08X d=%s ascii="%s" utf16="%s" ffxi16="%s"'):fmt(
                off,
                child,
                accessxi.format_probe_dwords(child, 0, 8),
                accessxi.escape_probe_log_text(ascii),
                accessxi.escape_probe_log_text(utf16),
                accessxi.escape_probe_log_text(ffxi16)));
            if (#parts >= 8) then
                break;
            end
        end
    end

    return parts:concat(' | ');
end

accessxi.chat_log_selected_source_glyph_probe = function (ptr)
    ptr = tonumber(ptr) or 0;
    if (not accessxi.is_probe_pointer(ptr)) then
        return '';
    end

    local words = T{};
    local glyph_text = T{};
    for off = 0x38, 0x120, 2 do
        local word = read_u16(ptr + off);
        if (word == nil) then
            break;
        end

        if (#words < 72) then
            words:append(('%03X:%04X'):fmt(off, word));
        end

        if (word >= 0x20 and word <= 0x7E) then
            glyph_text:append(string.char(word));
        elseif (word == 0x0000 or word == 0xFEFF or word == 0xFEFE or word == 0xFEAF or word == 0xFEFA or word == 0xFE96) then
            glyph_text:append(' ');
        end
    end

    local compact = glyph_text:concat(''):gsub('%s+', ' '):trim();
    local utf16 = accessxi.probe_runs_to_text(accessxi.collect_probe_utf16_runs(ptr, 0x140, 2, 8));
    local ffxi16 = accessxi.probe_runs_to_text(accessxi.collect_probe_ffxi_utf16_runs(ptr, 0x140, 2, 8));
    return ('glyphWords=%s glyphText="%s" utf16="%s" ffxi16="%s"'):fmt(
        words:concat(','),
        accessxi.escape_probe_log_text(compact),
        accessxi.escape_probe_log_text(utf16),
        accessxi.escape_probe_log_text(ffxi16));
end

accessxi.chat_log_decode_selected_source_glyph_text = function (ptr)
    ptr = tonumber(ptr) or 0;
    if (not accessxi.is_probe_pointer(ptr)) then
        return '';
    end

    local chars = T{};
    local started = false;
    local zero_run = 0;
    for off = 0x38, 0x220, 2 do
        local word = read_u16(ptr + off);
        if (word == nil) then
            break;
        end

        if (word == 0x0000) then
            zero_run = zero_run + 1;
            if (zero_run >= 16 and #chars > 0) then
                break;
            end
        else
            zero_run = 0;
        end

        if (word >= 0x0001 and word <= 0x005E) then
            chars:append(string.char(word + 0x20));
            started = true;
        elseif (word == 0xFEAF or word == 0xFEFA or word == 0xFEFF or word == 0xFEFE or word == 0xFE96) then
            if (started and #chars > 0) then
                chars:append(' ');
            end
        elseif (word >= 0x0020 and word <= 0x007E) then
            chars:append(string.char(word));
            started = true;
        end
    end

    local text = chars:concat('');
    text = text:gsub('%s+', ' '):trim();
    text = text:gsub('^(%[%d%d?:%d%d%])%s+(%[%d%d?:%d%d:%d%d%])', '%2');
    text = accessxi.chat_log_clean_native_text(text);
    text = text:gsub('%s+', ' '):trim();
    text = text:gsub('^(%[%d%d?:%d%d:?%d*%])%s+%1%s+', '%1 ');
    text = text:gsub('^(%[%d%d?:%d%d:?%d*%])%s+(%[%d%d?:%d%d:?%d*%])%s+', '%1 ');
    text = text:gsub('%[ Addons %]', '[Addons]');
    text = text:gsub('%[ AccessXI %]', '[AccessXI]');
    text = text:gsub('%](%S)', '] %1');
    text = text:gsub('Loadedaddon:', 'Loaded addon:');
    text = text:gsub('Combat%.Youhaveundertaken', 'Combat. You have undertaken');
    text = text:gsub('Youhaveundertaken', 'You have undertaken');
    text = text:gsub('^%s*[%p%s]*$', '');
    text = accessxi.chat_log_repair_selected_source_text(text);

    local speech = accessxi.chat_log_speech_text(text);
    if (speech == '' or not accessxi.chat_log_plain_text_quality_ok(speech, false)) then
        return '';
    end

    return text;
end

accessxi.chat_log_cursor_record_stride = 0x800;
accessxi.chat_log_cursor_record_bases = accessxi.chat_log_cursor_record_bases or {};
accessxi.chat_log_cursor_record_base_lists = accessxi.chat_log_cursor_record_base_lists or {};
accessxi.chat_log_record_cache = accessxi.chat_log_record_cache or nil;

accessxi.chat_log_decode_native_record = function (base)
    base = tonumber(base) or 0;
    if (not accessxi.is_scan_address(base)) then
        return nil;
    end

    local owner = read_u32(base + 0x00) or 0;
    local kind = read_u32(base + 0x04) or 0;
    local marker_a = read_u32(base + 0x24) or 0;
    local marker_b = read_u32(base + 0x2C) or 0;
    local text_len = read_u32(base + 0x3C) or -1;
    if (not accessxi.is_scan_address(owner)
        or kind < 0
        or kind > 0x1000
        or marker_a ~= 0x2D
        or marker_b ~= 0x3B
        or text_len < 1
        or text_len > (tonumber(accessxi.chat_log_max_line_len) or 150)) then
        return nil;
    end

    local terminator = read_u8(base + 0x40 + text_len);
    if (terminator ~= 0) then
        return nil;
    end

    local raw = accessxi.chat_log_ascii_text_from_ptr(base + 0x40, text_len + 1);
    local speech = accessxi.chat_log_speech_text(raw);
    if (speech == '' or #speech > (tonumber(accessxi.chat_log_max_line_len) or 150)) then
        return nil;
    end
    if (speech:find('%a') == nil or accessxi.chat_log_has_suspicious_noise(speech)) then
        return nil;
    end

    local lower = speech:lower();
    if (lower:find('/axi ', 1, true) ~= nil
        or lower:find('/addon ', 1, true) ~= nil
        or lower:find('chatbufscan', 1, true) ~= nil
        or lower:find('chatrecscan', 1, true) ~= nil
        or lower:find('chatrowscan', 1, true) ~= nil
        or lower:find('chatownerscan', 1, true) ~= nil) then
        return nil;
    end

    return T{
        base = base,
        owner = owner,
        family = read_u32(base + 0x1C) or 0,
        text_ptr = base + 0x40,
        text_len = text_len,
        flags = read_u32(base + 0x30) or 0,
        hash = read_u32(base + 0x38) or 0,
        text = speech,
    };
end

accessxi.chat_log_record_cache_add_record = function (groups, record)
    if (groups == nil or record == nil) then
        return;
    end

    local key = ('%08X:%08X:%08X'):fmt(
        tonumber(record.owner) or 0,
        tonumber(record.family) or 0,
        tonumber(read_u32((tonumber(record.base) or 0) + 0x34)) or 0);
    local group = groups[key];
    if (group == nil) then
        group = T{ key = key, records = T{}, seen = {} };
        groups[key] = group;
    end

    local base_key = ('%08X'):fmt(tonumber(record.base) or 0);
    if (group.seen[base_key] == true) then
        return;
    end
    group.seen[base_key] = true;
    group.records:append(record);
end

accessxi.chat_log_record_cache_group_list = function (groups)
    local list = T{};
    for _, group in pairs(groups or {}) do
        if (group.records:len() >= 2) then
            table.sort(group.records, function (a, b)
                return (tonumber(a.base) or 0) < (tonumber(b.base) or 0);
            end);
            list:append(group);
        end
    end
    table.sort(list, function (a, b)
        return (a.records:len() or 0) > (b.records:len() or 0);
    end);
    return list;
end

accessxi.chat_log_record_cache_scan_seed_region = function (groups, seed)
    if (seed == nil or not accessxi.is_scan_address(seed.base)) then
        return 0;
    end

    local mbi = ffi.new('MEMORY_BASIC_INFORMATION[1]');
    local mbi_size = ffi.sizeof('MEMORY_BASIC_INFORMATION');
    local queried = kernel32.VirtualQuery(ffi.cast('const void*', seed.base), mbi, mbi_size);
    if (tonumber(queried) == 0) then
        return 0;
    end

    local region_base = tonumber(ffi.cast('uintptr_t', mbi[0].BaseAddress)) or 0;
    local region_size = tonumber(mbi[0].RegionSize) or 0;
    local state = tonumber(mbi[0].State) or 0;
    local protect = tonumber(mbi[0].Protect) or 0;
    if (region_base == 0 or region_size <= 0 or state ~= 0x1000 or not accessxi.memory_page_readable(protect)) then
        return 0;
    end

    local scanned = 0;
    local scan_start = math.max(region_base, (tonumber(seed.base) or 0) - 0x80000);
    local scan_end = math.min(region_base + region_size - 0x90, (tonumber(seed.base) or 0) + 0x80000);
    for pos = scan_start, scan_end, 4 do
        local record = accessxi.chat_log_decode_native_record(pos);
        if (record ~= nil) then
            accessxi.chat_log_record_cache_add_record(groups, record);
        end
        scanned = scanned + 4;
    end
    return scanned;
end

accessxi.chat_log_record_cache_anchor_scan = function (state, anchor_text)
    local anchor = accessxi.chat_log_speech_text(anchor_text or '');
    if (anchor == '' or anchor:find('%a') == nil) then
        return nil;
    end

    local terms = T{};
    local seen_terms = {};
    local function add_term(term)
        term = tostring(term or ''):trim();
        if (term ~= '' and seen_terms[term:lower()] ~= true) then
            seen_terms[term:lower()] = true;
            terms:append(term);
        end
    end

    add_term(anchor);
    add_term(anchor:gsub('^%[Addons%]%s*', ''));
    add_term('Loaded addon: accessxi_reader');
    add_term('accessxi_reader');
    if (terms:len() == 0) then
        return nil;
    end

    local groups = {};
    local seeds = T{};
    local seed_seen = {};
    local mbi = ffi.new('MEMORY_BASIC_INFORMATION[1]');
    local mbi_size = ffi.sizeof('MEMORY_BASIC_INFORMATION');
    local addr = 0x10000;
    local stop_addr = 0x7FFF0000;
    local max_ms = 900;
    local max_bytes = 160 * 1024 * 1024;
    local max_hits = 80;
    local chunk_size = 256 * 1024;
    local process = kernel32.GetCurrentProcess();
    local buffer = ffi.new('char[?]', chunk_size);
    local bytes_read = ffi.new('SIZE_T[1]');
    local started = tick();
    local scanned_bytes = 0;
    local hits = 0;
    local timed_out = false;

    while (addr < stop_addr and scanned_bytes < max_bytes and hits < max_hits) do
        if ((tick() - started) > max_ms) then
            timed_out = true;
            break;
        end

        local ok, result = pcall(function ()
            return kernel32.VirtualQuery(ffi.cast('const void*', addr), mbi, mbi_size);
        end);
        local queried = ok and tonumber(result) or 0;
        if (queried == 0) then
            addr = addr + 0x10000;
        else
            local base = tonumber(ffi.cast('uintptr_t', mbi[0].BaseAddress)) or addr;
            local size = tonumber(mbi[0].RegionSize) or 0;
            local mem_state = tonumber(mbi[0].State) or 0;
            local protect = tonumber(mbi[0].Protect) or 0;
            local next_addr = base + math.max(size, 0x1000);

            if (size > 0 and mem_state == 0x1000 and accessxi.memory_page_readable(protect)) then
                local region_offset = 0;
                while (region_offset < size and scanned_bytes < max_bytes and hits < max_hits) do
                    if ((tick() - started) > max_ms) then
                        timed_out = true;
                        break;
                    end

                    local want = math.min(chunk_size, size - region_offset, max_bytes - scanned_bytes);
                    local chunk_addr = base + region_offset;
                    bytes_read[0] = 0;
                    local read_ok = kernel32.ReadProcessMemory(process, ffi.cast('const void*', chunk_addr), buffer, want, bytes_read) ~= 0;
                    local got = tonumber(bytes_read[0]) or 0;
                    if (read_ok and got > 0) then
                        local blob = ffi.string(buffer, got);
                        scanned_bytes = scanned_bytes + got;
                        for _, term in ipairs(terms) do
                            local start_at = 1;
                            while (hits < max_hits) do
                                local found = blob:find(term, start_at, true);
                                if (found == nil) then
                                    break;
                                end

                                local absolute = chunk_addr + found - 1;
                                hits = hits + 1;
                                for delta = 0x20, 0xE0 do
                                    local candidate_base = absolute - delta;
                                    if (candidate_base % 4 == 0) then
                                        local record = accessxi.chat_log_decode_native_record(candidate_base);
                                        if (record ~= nil) then
                                            local seed_key = ('%08X'):fmt(tonumber(record.base) or 0);
                                            if (seed_seen[seed_key] ~= true) then
                                                seed_seen[seed_key] = true;
                                                seeds:append(record);
                                                accessxi.chat_log_record_cache_add_record(groups, record);
                                            end
                                        end
                                    end
                                end
                                start_at = found + 1;
                            end
                        end
                    else
                        scanned_bytes = scanned_bytes + want;
                    end
                    region_offset = region_offset + want;
                end
            end

            if (next_addr <= addr) then
                addr = addr + 0x1000;
            else
                addr = next_addr;
            end
        end
    end

    local seed_scanned = 0;
    for _, seed in ipairs(seeds) do
        seed_scanned = seed_scanned + accessxi.chat_log_record_cache_scan_seed_region(groups, seed);
    end

    local cache = T{
        tick = tick(),
        groups = accessxi.chat_log_record_cache_group_list(groups),
        scanned = scanned_bytes + seed_scanned,
        anchor_hits = hits,
        seed_hits = seeds:len(),
        timed_out = timed_out,
    };
    accessxi.chat_log_record_cache = cache;
    return cache;
end

accessxi.chat_log_record_cache_refresh = function (state, anchor_text)
    local now = tick();
    local cache = accessxi.chat_log_record_cache;
    local ttl = tostring(accessxi.chat_log_record_cache_key or '') ~= '' and 10000 or 1500;
    if (cache ~= nil and ((now - (tonumber(cache.tick) or 0)) < ttl)) then
        return cache;
    end

    if (anchor_text ~= nil and tostring(anchor_text or '') ~= '') then
        return accessxi.chat_log_record_cache_anchor_scan(state, anchor_text);
    end

    local mbi = ffi.new('MEMORY_BASIC_INFORMATION[1]');
    local mbi_size = ffi.sizeof('MEMORY_BASIC_INFORMATION');
    local addr = 0x10000;
    local stop_addr = 0x7FFF0000;
    local max_ms = 450;
    local max_bytes = 160 * 1024 * 1024;
    local scanned_bytes = 0;
    local groups = {};
    local started = now;

    while (addr < stop_addr and scanned_bytes < max_bytes) do
        if ((tick() - started) > max_ms) then
            break;
        end

        local ok, result = pcall(function ()
            return kernel32.VirtualQuery(ffi.cast('const void*', addr), mbi, mbi_size);
        end);
        local queried = ok and tonumber(result) or 0;
        if (queried == 0) then
            addr = addr + 0x10000;
        else
            local base = tonumber(ffi.cast('uintptr_t', mbi[0].BaseAddress)) or addr;
            local size = tonumber(mbi[0].RegionSize) or 0;
            local state = tonumber(mbi[0].State) or 0;
            local protect = tonumber(mbi[0].Protect) or 0;
            local mem_type = tonumber(mbi[0].Type) or 0;
            local next_addr = base + math.max(size, 0x1000);

            if (size > 0
                and state == 0x1000
                and mem_type == 0x20000
                and accessxi.memory_page_readable(protect)) then
                local scan_end = base + math.min(size - 0x90, max_bytes - scanned_bytes);
                local pos = base;
                while (pos <= scan_end) do
                    local record = accessxi.chat_log_decode_native_record(pos);
                    if (record ~= nil) then
                        accessxi.chat_log_record_cache_add_record(groups, record);
                    end
                    pos = pos + 4;
                end
                scanned_bytes = scanned_bytes + math.max(0, scan_end - base);
            end

            if (next_addr <= addr) then
                addr = addr + 0x1000;
            else
                addr = next_addr;
            end
        end
    end

    cache = T{
        tick = tick(),
        groups = accessxi.chat_log_record_cache_group_list(groups),
        scanned = scanned_bytes,
    };
    accessxi.chat_log_record_cache = cache;
    return cache;
end

accessxi.chat_log_record_cache_learn = function (state, anchor_text)
    if (state == nil) then
        return;
    end

    local cursor = tonumber(state.cursor) or -1;
    local bottom = tonumber(state.bottom) or -1;
    if (cursor < 0 or bottom < 0 or cursor > bottom) then
        return;
    end

    local anchor = accessxi.chat_log_speech_text(anchor_text or ''):lower():trim();
    if (anchor == '' or anchor:find('%a') == nil) then
        return;
    end

    local cache = accessxi.chat_log_record_cache_refresh(state, anchor);
    if (cache == nil or cache.groups == nil) then
        return;
    end

    local best = nil;
    for _, group in ipairs(cache.groups) do
        local records = group.records or T{};
        if (records:len() >= (bottom + 1)) then
            for index, record in ipairs(records) do
                local text = accessxi.chat_log_speech_text(record.text or ''):lower():trim();
                if (text == anchor or text:find(anchor, 1, true) ~= nil or anchor:find(text, 1, true) ~= nil) then
                    local offset = index - 1 - cursor;
                    local score = records:len();
                    if (best == nil or score > (tonumber(best.score) or 0)) then
                        best = T{
                            key = group.key,
                            offset = offset,
                            score = score,
                            index = index - 1,
                            text = record.text,
                        };
                    end
                end
            end
        end
    end

    if (best == nil) then
        local samples = T{};
        for _, group in ipairs(cache.groups) do
            if (samples:len() >= 5) then
                break;
            end

            local records = group.records or T{};
            local first_text = '';
            local last_text = '';
            if (records:len() > 0) then
                first_text = accessxi.chat_log_speech_text(records[1].text or '');
                last_text = accessxi.chat_log_speech_text(records[records:len()].text or '');
            end
            samples:append(('%s:%d:first="%s":last="%s"'):fmt(
                tostring(group.key or ''),
                records:len(),
                accessxi.escape_probe_log_text(first_text),
                accessxi.escape_probe_log_text(last_text)));
        end

        local log_key = ('%d:%d:%s:%d:%d'):fmt(
            cursor,
            bottom,
            anchor,
            tonumber(cache.scanned) or 0,
            cache.groups:len());
        if (log_key ~= (accessxi.chat_log_record_cache_learn_miss_last_probe or '')) then
            accessxi.chat_log_record_cache_learn_miss_last_probe = log_key;
            log_state(('state chatlog record-cache-learn-miss cursor=%d bottom=%d groups=%d scanned=%d anchorHits=%d seedHits=%d timedOut=%s anchor="%s" samples="%s"'):fmt(
                cursor,
                bottom,
                cache.groups:len(),
                tonumber(cache.scanned) or 0,
                tonumber(cache.anchor_hits) or 0,
                tonumber(cache.seed_hits) or 0,
                tostring(cache.timed_out),
                accessxi.escape_probe_log_text(anchor),
                accessxi.escape_probe_log_text(samples:concat(' | '))));
        end
        return;
    end

    accessxi.chat_log_record_cache_key = best.key;
    accessxi.chat_log_record_cache_offset = tonumber(best.offset) or 0;
    accessxi.chat_log_record_cache_bottom = bottom;
    local log_key = ('%s:%d:%d:%s'):fmt(best.key, cursor, best.offset, best.text or '');
    if (log_key ~= (accessxi.chat_log_record_cache_learn_last_probe or '')) then
        accessxi.chat_log_record_cache_learn_last_probe = log_key;
        log_state(('state chatlog record-cache-learn cursor=%d bottom=%d key="%s" offset=%d records=%d anchor="%s" scanned=%d'):fmt(
            cursor,
            bottom,
            tostring(best.key or ''),
            tonumber(best.offset) or 0,
            tonumber(best.score) or 0,
            accessxi.escape_probe_log_text(best.text or ''),
            tonumber(cache.scanned) or 0));
    end
end

accessxi.chat_log_record_cache_maybe_learn = function (state, anchor_text)
    if (state == nil) then
        return;
    end

    local bottom = tonumber(state.bottom) or -1;
    if (bottom < 0) then
        return;
    end

    if (tostring(accessxi.chat_log_record_cache_key or '') ~= ''
        and bottom == (tonumber(accessxi.chat_log_record_cache_bottom) or -99999)) then
        return;
    end

    local anchor = accessxi.chat_log_speech_text(anchor_text or '');
    if (anchor == '' or anchor:find('%[Addons%]%s+Loaded addon:', 1, false) == nil) then
        return;
    end

    local now = tick();
    if ((now - (tonumber(accessxi.chat_log_record_cache_maybe_last_tick) or 0)) < 8000) then
        return;
    end
    accessxi.chat_log_record_cache_maybe_last_tick = now;

    local attempt_key = ('%d:%d:%s'):fmt(
        tonumber(state.cursor) or -1,
        bottom,
        anchor);
    if (attempt_key ~= (accessxi.chat_log_record_cache_maybe_last_probe or '')) then
        accessxi.chat_log_record_cache_maybe_last_probe = attempt_key;
        log_state(('state chatlog record-cache-learn-attempt cursor=%d bottom=%d anchor="%s"'):fmt(
            tonumber(state.cursor) or -1,
            bottom,
            accessxi.escape_probe_log_text(anchor)));
    end

    local ok, err = pcall(function ()
        accessxi.chat_log_record_cache_learn(state, anchor);
    end);
    if (not ok) then
        log_state(('state chatlog record-cache-learn-error cursor=%d bottom=%d err="%s"'):fmt(
            tonumber(state.cursor) or -1,
            bottom,
            accessxi.escape_probe_log_text(tostring(err or ''))));
    end
end

accessxi.chat_log_native_line_from_record_cache = function (state)
    if (state == nil) then
        return nil;
    end

    local key = tostring(accessxi.chat_log_record_cache_key or '');
    local offset = tonumber(accessxi.chat_log_record_cache_offset);
    if (key == '' or offset == nil) then
        return nil;
    end

    local cursor = tonumber(state.cursor) or -1;
    local bottom = tonumber(state.bottom) or -1;
    if (cursor < 0 or bottom < 0 or cursor > bottom) then
        return nil;
    end
    if (bottom ~= (tonumber(accessxi.chat_log_record_cache_bottom) or -99999)) then
        return nil;
    end

    local cache = accessxi.chat_log_record_cache_refresh();
    if (cache == nil or cache.groups == nil) then
        return nil;
    end

    local records = nil;
    for _, group in ipairs(cache.groups) do
        if (tostring(group.key or '') == key) then
            records = group.records;
            break;
        end
    end
    if (records == nil) then
        return nil;
    end

    local index = cursor + offset;
    if (index < 0 or index >= records:len()) then
        return nil;
    end

    local record = records[index + 1];
    local text = accessxi.chat_log_speech_text(record ~= nil and record.text or '');
    if (text == ''
        or #text > (tonumber(accessxi.chat_log_max_line_len) or 150)
        or text:find('%a') == nil
        or accessxi.chat_log_has_suspicious_noise(text)) then
        return nil;
    end

    local log_key = ('%s:%d:%d:%s'):fmt(key, cursor, index, text);
    if (log_key ~= (accessxi.chat_log_record_cache_last_probe or '')) then
        accessxi.chat_log_record_cache_last_probe = log_key;
        log_state(('state chatlog record-cache cursor=%d bottom=%d key="%s" index=%d records=%d text="%s"'):fmt(
            cursor,
            bottom,
            key,
            index,
            records:len(),
            accessxi.escape_probe_log_text(text)));
    end

    return T{
        text = text,
        source = ('fulllog-record-cache@0x%08X'):fmt(tonumber(record.base) or 0),
        score = 44500,
        chat_log_menu_nav = true,
        chat_log_row_selected = tonumber(state.selected_index) or 0,
        chat_log_row_count = tonumber(state.row_count) or 0,
        chat_log_selection_reason = 'native-fulllog-record-cache',
        visible_signature = ('%d:%d:0x%08X:%s'):fmt(
            cursor,
            bottom,
            tonumber(record.base) or 0,
            text),
    };
end

accessxi.chat_log_cursor_record_word_run_text = function (ptr, start_off)
    ptr = tonumber(ptr) or 0;
    start_off = tonumber(start_off) or 0;
    if (not accessxi.is_probe_pointer(ptr)) then
        return '';
    end

    local chars = T{};
    local started = false;
    local zero_run = 0;
    for off = start_off, math.min(start_off + 0xA0, 0x220), 2 do
        local word = read_u16(ptr + off);
        if (word == nil) then
            break;
        end

        if (word == 0x0000) then
            zero_run = zero_run + 1;
            if (zero_run >= 8 and #chars > 0) then
                break;
            end
        else
            zero_run = 0;
        end

        if (word >= 0x0001 and word <= 0x005E) then
            chars:append(string.char(word + 0x20));
            started = true;
        elseif (word >= 0x0020 and word <= 0x007E) then
            chars:append(string.char(word));
            started = true;
        elseif (word == 0xFEAF or word == 0xFEFA or word == 0xFEFF or word == 0xFEFE or word == 0xFE96) then
            if (started and #chars > 0) then
                chars:append(' ');
            end
        elseif (started and #chars > 0 and word > 0xFF00) then
            chars:append(' ');
        end
    end

    return accessxi.chat_log_clean_native_text(chars:concat('')):gsub('%s+', ' '):trim();
end

accessxi.chat_log_cursor_record_ffxi16_run_text = function (ptr)
    ptr = tonumber(ptr) or 0;
    if (not accessxi.is_probe_pointer(ptr)) then
        return '';
    end

    local parts = T{};
    local run = T{};
    local function flush_run()
        if (#run <= 0) then
            return;
        end

        local text = accessxi.decode_ffxi_menu_text_fragment(run:concat(''));
        text = accessxi.chat_log_repair_selected_source_text(text);
        text = text:gsub('^%s*[%p%s]+', ''):gsub('%s+', ' '):trim();
        if (text ~= ''
            and #text <= (tonumber(accessxi.chat_log_max_line_len) or 150)
            and text:find('%a') ~= nil
            and not accessxi.chat_log_has_suspicious_noise(text)) then
            parts:append(text);
        end
        run = T{};
    end

    for off = 0x38, 0x160, 2 do
        local lo = read_u8(ptr + off);
        local hi = read_u8(ptr + off + 1);
        if (lo ~= nil and hi == 0 and accessxi.probe_printable_ascii(lo)) then
            run:append(string.char(lo));
        else
            flush_run();
        end
    end
    flush_run();

    local text = parts:concat(' ');
    text = accessxi.chat_log_repair_selected_source_text(text);
    text = accessxi.chat_log_clean_native_text(text):gsub('%s+', ' '):trim();
    text = accessxi.chat_log_repair_selected_source_text(text);
    return text;
end

accessxi.chat_log_cursor_record_word_run_decode = function (ptr)
    ptr = tonumber(ptr) or 0;
    if (not accessxi.is_probe_pointer(ptr)) then
        return nil, '';
    end

    local best = nil;
    local best_score = -999999;
    local details = T{};
    local seen = {};
    local function score_candidate(speech, text, off, mode)
        speech = tostring(speech or '');
        text = tostring(text or '');

        local letters = 0;
        local spaces = 0;
        local punctuation = 0;
        for i = 1, #speech do
            local b = speech:byte(i) or 0;
            if ((b >= 65 and b <= 90) or (b >= 97 and b <= 122)) then
                letters = letters + 1;
            elseif (b == 32) then
                spaces = spaces + 1;
            elseif (b < 48 or b > 57) then
                punctuation = punctuation + 1;
            end
        end

        local score = (#speech * 2) + (letters * 2) + (spaces * 35) - (punctuation * 18);
        if (mode == 'ffxi16-run') then
            score = score + 600;
        end
        if (accessxi.chat_log_has_time(text)) then
            score = score + 60;
        end
        if (accessxi.chat_log_native_continuation_word_ok(speech)) then
            score = score + 240;
        end
        if (off == 0x00 or off == 0x18 or off == 0x20) then
            score = score + 10;
        end
        if (#speech >= 30) then
            score = score + 120;
        end
        if (spaces >= 2) then
            score = score + 100;
        end
        if (#speech < 12 and not accessxi.chat_log_has_time(speech)) then
            score = score - 500;
        end
        if (#speech > 18 and spaces == 0) then
            score = score - 350;
        end

        -- These are structural artifacts from the cursor record encoding, not
        -- chat phrases. Penalize them so cleaner native chunks win.
        if (speech:find('o)?', 1, true) ~= nil
            or speech:find("'?:'?", 1, true) ~= nil
            or speech:find('@kGw', 1, true) ~= nil
            or speech:find(';=', 1, true) ~= nil
            or speech:find('SsH@', 1, true) ~= nil
            or speech:find('P]', 1, true) ~= nil) then
            score = score - 1200;
        end

        return score;
    end

    for _, off in ipairs(T{ 0x00, 0x18, 0x20, 0x28, 0x30, 0x38, 0x40, 0x50, 0x60, 0x70, 0x80, 0xA0, 0xC0 }) do
        local raw = accessxi.chat_log_cursor_record_word_run_text(ptr, off);
        if (raw ~= '' and seen[raw] ~= true) then
            seen[raw] = true;
            local text = accessxi.decode_ffxi_menu_text_fragment(raw);
            text = accessxi.chat_log_repair_selected_source_text(text);
            text = accessxi.chat_log_clean_native_text(text):gsub('%s+', ' '):trim();
            text = accessxi.chat_log_repair_selected_source_text(text);
            local speech = accessxi.chat_log_speech_text(text);
            local lower = speech:lower();
            local quality = speech ~= ''
                and #speech <= (tonumber(accessxi.chat_log_max_line_len) or 150)
                and (accessxi.chat_log_selected_source_quality_ok(speech)
                    or accessxi.chat_log_native_continuation_word_ok(speech))
                and lower:find('menu    ', 1, true) == nil
                and lower:find('chatrecscan', 1, true) == nil
                and lower:find('chatbufscan', 1, true) == nil
                and lower:find('chatptrscan', 1, true) == nil;

            details:append(('+%02Xw="%s"%s'):fmt(
                off,
                accessxi.escape_probe_log_text(text),
                quality and '*' or ''));

            if (quality) then
                local score = score_candidate(speech, text, off, 'word-run');
                if (score > best_score) then
                    best_score = score;
                    best = T{
                        text = text,
                        text_ptr = ptr + off,
                        source_offset = off,
                        source_mode = 'word-run',
                    };
                end
            end
        end
    end

    local ffxi16 = accessxi.chat_log_cursor_record_ffxi16_run_text(ptr);
    if (ffxi16 ~= '' and seen[ffxi16] ~= true) then
        seen[ffxi16] = true;
        local speech = accessxi.chat_log_speech_text(ffxi16);
        local quality = speech ~= ''
            and #speech <= (tonumber(accessxi.chat_log_max_line_len) or 150)
            and (accessxi.chat_log_rich_render_text_ok(speech)
                or accessxi.chat_log_native_continuation_word_ok(speech));
        details:append(('+38f="%s"%s'):fmt(
            accessxi.escape_probe_log_text(ffxi16),
            quality and '*' or ''));
        if (quality) then
            local score = score_candidate(speech, ffxi16, 0x38, 'ffxi16-run');
            if (score > best_score) then
                best_score = score;
                best = T{
                    text = ffxi16,
                    text_ptr = ptr + 0x38,
                    source_offset = 0x38,
                    source_mode = 'ffxi16-run',
                };
            end
        end
    end

    return best, details:concat(' | ');
end

accessxi.chat_log_cursor_record_decode = function (ptr)
    ptr = tonumber(ptr) or 0;
    if (not accessxi.is_probe_pointer(ptr)) then
        return nil, '';
    end

    local decoded, detail = accessxi.chat_log_selected_source_record_text(ptr);
    local text = decoded ~= nil and tostring(decoded.text or '') or '';
    local word_decoded, word_detail = accessxi.chat_log_cursor_record_word_run_decode(ptr);
    local generic_text = accessxi.chat_log_speech_text(text);
    local word_text = word_decoded ~= nil and accessxi.chat_log_speech_text(word_decoded.text or '') or '';
    local generic_ok = decoded ~= nil and accessxi.chat_log_selected_source_quality_ok(generic_text);
    local word_ok = word_decoded ~= nil
        and (accessxi.chat_log_selected_source_quality_ok(word_text)
            or accessxi.chat_log_native_continuation_word_ok(word_text));
    if (word_ok and (not generic_ok
        or (word_text:find(' ', 1, true) ~= nil and generic_text:find(' ', 1, true) == nil)
        or generic_text:find('undertakenthelimited', 1, true) ~= nil
        or generic_text:find('Eminencechallenge', 1, true) ~= nil
        or generic_text:find('Recordsof', 1, true) ~= nil
        or generic_text:match('^%u@%s+') ~= nil)) then
        return word_decoded, (detail or '') .. ' | wordrun ' .. (word_detail or '');
    end
    if (generic_ok) then
        decoded.text = generic_text;
        decoded.source_mode = decoded.source_mode or 'record';
        return decoded, detail or '';
    end
    if (word_ok) then
        return word_decoded, (detail or '') .. ' | wordrun ' .. (word_detail or '');
    end

    local glyph_text = accessxi.chat_log_decode_selected_source_glyph_text(ptr);
    if (glyph_text ~= '' and accessxi.chat_log_rich_render_text_ok(glyph_text)) then
        return T{
            text = glyph_text,
            text_ptr = ptr + 0x38,
            source_offset = 0x38,
            source_mode = 'glyph-minus-20',
        }, (detail or '') .. ' | glyph';
    end

    return nil, detail or '';
end

accessxi.chat_log_cursor_record_reject_reason = function (text, detail)
    text = tostring(text or ''):trim();
    detail = tostring(detail or '');
    if (text == '') then
        if (detail:find('menu    gauge', 1, true) ~= nil) then
            return 'render-gauge';
        end
        if (detail:find('menu    mesicon', 1, true) ~= nil) then
            return 'render-icon';
        end
        if (detail:find('AccessXI', 1, true) ~= nil and detail:find('Loaded addon', 1, true) == nil) then
            return 'accessxi-fragment';
        end
        if (detail:find('PP/H', 1, true) ~= nil or detail:find('PP)H', 1, true) ~= nil) then
            return 'short-encoded-fragment';
        end
        return 'no-clean-text';
    end
    if (not accessxi.chat_log_selected_source_quality_ok(text)
        and not accessxi.chat_log_native_continuation_word_ok(text)) then
        return 'quality';
    end
    return 'ok';
end

accessxi.chat_log_cursor_record_reject_probe = function (state, ptr, reason, detail)
    ptr = tonumber(ptr) or 0;
    if (state == nil or not accessxi.is_probe_pointer(ptr)) then
        return;
    end

    local cursor = tonumber(state.cursor) or -1;
    local bottom = tonumber(state.bottom) or -1;
    if (state.full_log_menu == true
        and (cursor <= 1 or (bottom > 1 and cursor >= bottom))
        and tostring(reason or '') == 'no-clean-text') then
        local now = tick();
        if ((now - (tonumber(accessxi.chat_log_cursor_record_reject_edge_last_tick) or 0)) < 3000) then
            return;
        end
        accessxi.chat_log_cursor_record_reject_edge_last_tick = now;
    end

    local key = ('0x%08X:%d:%d:%s'):fmt(ptr, cursor, bottom, tostring(reason or ''));
    if (key == (accessxi.chat_log_cursor_record_reject_last_probe or '')) then
        return;
    end
    accessxi.chat_log_cursor_record_reject_last_probe = key;

    local function decode_word_run(start_off)
        local chars = T{};
        local started = false;
        local zero_run = 0;
        for off = start_off, math.min(start_off + 0xA0, 0x220), 2 do
            local word = read_u16(ptr + off);
            if (word == nil) then
                break;
            end

            if (word == 0x0000) then
                zero_run = zero_run + 1;
                if (zero_run >= 8 and #chars > 0) then
                    break;
                end
            else
                zero_run = 0;
            end

            if (word >= 0x0001 and word <= 0x005E) then
                chars:append(string.char(word + 0x20));
                started = true;
            elseif (word >= 0x0020 and word <= 0x007E) then
                chars:append(string.char(word));
                started = true;
            elseif (word == 0xFEAF or word == 0xFEFA or word == 0xFEFF or word == 0xFEFE or word == 0xFE96) then
                if (started and #chars > 0) then
                    chars:append(' ');
                end
            elseif (started and #chars > 0 and word > 0xFF00) then
                chars:append(' ');
            end
        end

        return accessxi.chat_log_clean_native_text(chars:concat('')):gsub('%s+', ' '):trim();
    end

    local function decode_byte_run(start_off)
        local chars = T{};
        local zero_run = 0;
        for off = start_off, math.min(start_off + 0xA0, 0x220) do
            local byte_value = read_u8(ptr + off);
            if (byte_value == nil) then
                break;
            end

            if (byte_value == 0) then
                zero_run = zero_run + 1;
                if (zero_run >= 8 and #chars > 0) then
                    break;
                end
            else
                zero_run = 0;
            end

            if (byte_value >= 0x20 and byte_value <= 0x7E) then
                chars:append(string.char(byte_value));
            elseif (byte_value >= 0x01 and byte_value <= 0x5E) then
                chars:append(string.char(byte_value + 0x20));
            elseif (byte_value == 0x09 or byte_value == 0x0A or byte_value == 0x0D or byte_value >= 0xF0) then
                chars:append(' ');
            end
        end

        return accessxi.chat_log_clean_native_text(chars:concat('')):gsub('%s+', ' '):trim();
    end

    local candidates = T{};
    for _, off in ipairs(T{ 0x00, 0x18, 0x20, 0x28, 0x30, 0x38, 0x40, 0x50, 0x60, 0x80, 0xA0, 0xC0 }) do
        local word_text = decode_word_run(off);
        local byte_text = decode_byte_run(off);
        if (word_text ~= '') then
            candidates:append(('+%02Xw="%s"'):fmt(off, accessxi.escape_probe_log_text(word_text)));
        end
        if (byte_text ~= '' and byte_text ~= word_text) then
            candidates:append(('+%02Xb="%s"'):fmt(off, accessxi.escape_probe_log_text(byte_text)));
        end
        if (#candidates >= 18) then
            break;
        end
    end

    log_state(('state chatlog cursor-record-reject-dump data=0x%08X cursor=%d bottom=%d ptr=0x%08X reason="%s" detail="%s" candidates="%s" bytes=%s words=%s'):fmt(
        tonumber(state.data) or 0,
        cursor,
        bottom,
        ptr,
        accessxi.escape_probe_log_text(tostring(reason or '')),
        accessxi.escape_probe_log_text(tostring(detail or '')),
        accessxi.escape_probe_log_text(candidates:concat(' | ')),
        accessxi.format_probe_bytes(ptr, 0, 0xC0),
        accessxi.chat_log_selected_source_glyph_probe(ptr)));
end

accessxi.chat_log_cursor_record_key = function (state)
    if (state == nil or not accessxi.is_probe_pointer(state.data)) then
        return '';
    end
    return ('0x%08X'):fmt(tonumber(state.data) or 0);
end

accessxi.chat_log_cursor_record_learn_base = function (state, source_ptr, decoded)
    if (state == nil or decoded == nil) then
        return;
    end

    source_ptr = tonumber(source_ptr) or 0;
    local cursor = tonumber(state.cursor) or -1;
    local bottom = tonumber(state.bottom) or -1;
    if (cursor < 0 or cursor > 10000 or not accessxi.is_probe_pointer(source_ptr)) then
        return;
    end

    local text = tostring(decoded.text or '');
    if (text == '' or not accessxi.chat_log_selected_source_quality_ok(text)) then
        return;
    end

    local stride = tonumber(accessxi.chat_log_cursor_record_stride) or 0x800;
    local base = source_ptr - (cursor * stride);
    if (not accessxi.is_probe_pointer(base)) then
        return;
    end

    local key = accessxi.chat_log_cursor_record_key(state);
    if (key == '') then
        return;
    end

    local now = tick();
    local bank20 = read_u32(state.data + 0x20) or 0;
    local bank24 = read_u32(state.data + 0x24) or 0;
    local cache = accessxi.chat_log_cursor_record_bases;
    local entry = cache[key];
    local hits = 1;
    if (entry ~= nil and tonumber(entry.base) == base) then
        hits = (tonumber(entry.hits) or 0) + 1;
    end

    cache[key] = T{
        base = base,
        hits = hits,
        last_cursor = cursor,
        last_bottom = bottom,
        last_ptr = source_ptr,
        last_tick = now,
        last_text = text,
        bank20 = bank20,
        bank24 = bank24,
    };

    local base_list_cache = accessxi.chat_log_cursor_record_base_lists;
    local base_list = base_list_cache[key];
    if (base_list == nil) then
        base_list = T{};
        base_list_cache[key] = base_list;
    end
    local found_base = nil;
    for _, candidate in ipairs(base_list) do
        if (tonumber(candidate.base) == base) then
            found_base = candidate;
            break;
        end
    end
    if (found_base == nil) then
        found_base = T{ base = base, hits = 0 };
        base_list:append(found_base);
    end
    found_base.hits = (tonumber(found_base.hits) or 0) + 1;
    found_base.last_cursor = cursor;
    found_base.last_bottom = bottom;
    found_base.last_ptr = source_ptr;
    found_base.last_tick = now;
    found_base.last_text = text;
    found_base.bank20 = bank20;
    found_base.bank24 = bank24;
    table.sort(base_list, function (a, b)
        local at = tonumber(a.last_tick) or 0;
        local bt = tonumber(b.last_tick) or 0;
        if (at == bt) then
            return (tonumber(a.hits) or 0) > (tonumber(b.hits) or 0);
        end
        return at > bt;
    end);
    while (base_list:len() > 6) do
        table.remove(base_list, base_list:len());
    end

    local log_key = ('%s:%08X:%d:%d:%d:%08X'):fmt(key, base, hits, cursor, bottom, source_ptr);
    if (log_key ~= (accessxi.chat_log_cursor_record_learn_last_probe or '')) then
        accessxi.chat_log_cursor_record_learn_last_probe = log_key;
        log_state(('state chatlog cursor-record-learn data=0x%08X cursor=%d bottom=%d ptr=0x%08X base=0x%08X hits=%d text="%s"'):fmt(
            tonumber(state.data) or 0,
            cursor,
            bottom,
            source_ptr,
            base,
            hits,
            accessxi.escape_probe_log_text(text)));
    end
end

accessxi.chat_log_native_line_from_cursor_record = function (state)
    if (state == nil or not accessxi.is_probe_pointer(state.data)) then
        return nil;
    end

    local current_bank20 = read_u32(state.data + 0x20) or 0;
    local current_bank24 = read_u32(state.data + 0x24) or 0;
    local current_source_ptr = read_u32(state.data + 0x28) or 0;
    local current_source_flag = read_u32(state.data + 0x24) or 0;
    local current_source_meta = read_u32(state.data + 0x2C) or 0;
    local source_is_cursor_only_record =
        current_source_ptr == 0
        and (current_source_flag == 0x65000001 or current_source_flag == 0x00000001 or current_source_flag == 0x00000000)
        and current_source_meta == 0xFFFF0000;
    if (not source_is_cursor_only_record and state.full_log_menu ~= true) then
        return nil;
    end

    local key = accessxi.chat_log_cursor_record_key(state);
    local entry = accessxi.chat_log_cursor_record_bases[key];
    if (entry == nil) then
        return nil;
    end

    local cursor = tonumber(state.cursor) or -1;
    local bottom = tonumber(state.bottom) or -1;
    local last_cursor = tonumber(entry.last_cursor) or -99999;
    local last_bottom = tonumber(entry.last_bottom) or -99999;
    local last_tick = tonumber(entry.last_tick) or 0;
    if (cursor < 0 or cursor > 10000) then
        return nil;
    end
    if (bottom ~= last_bottom) then
        return nil;
    end
    if (math.abs(cursor - last_cursor) > 512) then
        return nil;
    end
    if ((tick() - last_tick) > 300000) then
        return nil;
    end

    local stride = tonumber(accessxi.chat_log_cursor_record_stride) or 0x800;
    local effective_cursor = cursor;
    local edge_name = '';
    if (cursor <= 1 and bottom > 1) then
        edge_name = 'top';
    elseif (cursor >= bottom and bottom > 1) then
        edge_name = 'bottom';
    end
    -- Do not synthesize full-log scroll movement. The native scroll/top-record
    -- field is still unknown; walking guessed record addresses past the visible
    -- row window creates false positives and lag.
    edge_name = '';
    if (edge_name ~= '') then
        local now_edge = tick();
        local up_down = false;
        local down_down = false;
        if (up_down) then
            accessxi.chat_log_cursor_edge_nav_tick = now_edge;
            accessxi.chat_log_cursor_edge_nav_dir = 'top';
        elseif (down_down) then
            accessxi.chat_log_cursor_edge_nav_tick = now_edge;
            accessxi.chat_log_cursor_edge_nav_dir = 'bottom';
        end
        local edge_nav_active = tostring(accessxi.chat_log_cursor_edge_nav_dir or '') == edge_name
            and (now_edge - (tonumber(accessxi.chat_log_cursor_edge_nav_tick) or 0)) <= 900;
        local edge_state_key = ('%s:%s:%d:%d'):fmt(key, edge_name, cursor, bottom);
        local edge_row_signature = accessxi.chat_log_row_window_signature(state);
        local edge_event_key = ('%s:0x%08X:0x%08X:0x%08X:0x%08X:%s'):fmt(
            edge_state_key,
            tonumber(current_source_flag) or 0,
            tonumber(current_source_meta) or 0,
            tonumber(current_source_ptr) or 0,
            tonumber(state.selected_row) or 0,
            edge_row_signature);
        local edge_changed = false;
        if (edge_state_key ~= tostring(accessxi.chat_log_cursor_edge_state_key or '')) then
            accessxi.chat_log_cursor_edge_state_key = edge_state_key;
            accessxi.chat_log_cursor_edge_event_key = edge_event_key;
            accessxi.chat_log_cursor_edge_offset = 0;
            accessxi.chat_log_cursor_edge_success_base = 0;
            accessxi.chat_log_cursor_edge_success_state_key = '';
            accessxi.chat_log_cursor_edge_success_tick = 0;
        elseif (edge_event_key ~= tostring(accessxi.chat_log_cursor_edge_event_key or '')) then
            accessxi.chat_log_cursor_edge_event_key = edge_event_key;
            if (edge_nav_active) then
                if (edge_name == 'top') then
                    accessxi.chat_log_cursor_edge_offset = (tonumber(accessxi.chat_log_cursor_edge_offset) or 0) - 1;
                else
                    accessxi.chat_log_cursor_edge_offset = (tonumber(accessxi.chat_log_cursor_edge_offset) or 0) + 1;
                end
                edge_changed = true;
            end
        end
        local edge_offset = tonumber(accessxi.chat_log_cursor_edge_offset) or 0;
        local edge_log_key = ('%s:%d:%s'):fmt(edge_state_key, edge_offset, edge_row_signature);
        if (edge_changed and edge_log_key ~= tostring(accessxi.chat_log_cursor_edge_last_log or '')) then
            accessxi.chat_log_cursor_edge_last_log = edge_log_key;
            log_state(('state chatlog cursor-edge edge="%s" cursor=%d bottom=%d offset=%d rowSig="%s"'):fmt(
                edge_name,
                cursor,
                bottom,
                edge_offset,
                accessxi.escape_probe_log_text(edge_row_signature)));
        end
        if (math.abs(edge_offset) <= 1000) then
            effective_cursor = cursor + edge_offset;
        end
    else
        accessxi.chat_log_cursor_edge_state_key = '';
        accessxi.chat_log_cursor_edge_event_key = '';
        accessxi.chat_log_cursor_edge_offset = 0;
        accessxi.chat_log_cursor_edge_last_log = '';
        accessxi.chat_log_cursor_edge_nav_tick = 0;
        accessxi.chat_log_cursor_edge_nav_dir = '';
        accessxi.chat_log_cursor_edge_success_base = 0;
        accessxi.chat_log_cursor_edge_success_state_key = '';
        accessxi.chat_log_cursor_edge_success_tick = 0;
    end

    local candidates = T{};
    local seen_bases = {};
    local function add_base_candidate(candidate_entry)
        if (candidate_entry == nil) then
            return;
        end
        local candidate_base = tonumber(candidate_entry.base) or 0;
        if (not accessxi.is_probe_pointer(candidate_base)) then
            return;
        end
        local candidate_key = ('%08X'):fmt(candidate_base);
        if (seen_bases[candidate_key] == true) then
            return;
        end
        seen_bases[candidate_key] = true;
        candidates:append(candidate_entry);
    end
    local function add_native_bank_candidate(candidate_entry)
        if (candidate_entry == nil) then
            return;
        end

        local base = tonumber(candidate_entry.base) or 0;
        if (not accessxi.is_probe_pointer(base)) then
            return;
        end

        local entry_bank20 = tonumber(candidate_entry.bank20);
        local entry_bank24 = tonumber(candidate_entry.bank24);
        local row_delta = nil;
        if (entry_bank20 ~= nil and entry_bank24 ~= nil) then
            if (entry_bank20 == current_bank20 and entry_bank24 == current_bank24) then
                return;
            end
            -- x32 before/after scroll dumps showed the full-log native bank
            -- flip from +20=0,+24=1 to +20=1,+24=0 and the active text bank
            -- moved back four 0x800-byte records.
            if (entry_bank20 == 0 and entry_bank24 == 1 and current_bank20 == 1 and current_bank24 == 0) then
                row_delta = -4;
            elseif (entry_bank20 == 1 and entry_bank24 == 0 and current_bank20 == 0 and current_bank24 == 1) then
                row_delta = 4;
            end
        elseif (current_bank20 == 1 and current_bank24 == 0) then
            row_delta = -4;
        end
        if (row_delta == nil) then
            return;
        end

        local shifted_base = base + (row_delta * stride);
        if (not accessxi.is_probe_pointer(shifted_base)) then
            return;
        end

        add_base_candidate(T{
            base = shifted_base,
            hits = tonumber(candidate_entry.hits) or 0,
            last_cursor = tonumber(candidate_entry.last_cursor) or last_cursor,
            last_bottom = bottom,
            last_tick = tonumber(candidate_entry.last_tick) or last_tick,
            derived = true,
            native_bank = true,
            row_delta = row_delta,
            parent_base = base,
            bank20 = current_bank20,
            bank24 = current_bank24,
            parent_bank20 = entry_bank20,
            parent_bank24 = entry_bank24,
        });
    end
    if (edge_name ~= '') then
        local success_base = tonumber(accessxi.chat_log_cursor_edge_success_base) or 0;
        local success_state_key = tostring(accessxi.chat_log_cursor_edge_success_state_key or '');
        local success_tick = tonumber(accessxi.chat_log_cursor_edge_success_tick) or 0;
        if (success_state_key == tostring(accessxi.chat_log_cursor_edge_state_key or '')
            and accessxi.is_probe_pointer(success_base)
            and (tick() - success_tick) <= 300000) then
            add_base_candidate(T{
                base = success_base,
                hits = 9999,
                last_cursor = last_cursor,
                last_bottom = bottom,
                last_tick = success_tick,
                edge_success = true,
            });
        end
    end
    add_native_bank_candidate(entry);
    add_base_candidate(entry);
    local base_list = accessxi.chat_log_cursor_record_base_lists[key];
    if (base_list ~= nil) then
        for _, candidate_entry in ipairs(base_list) do
            local candidate_bottom = tonumber(candidate_entry.last_bottom) or -99999;
            local candidate_tick = tonumber(candidate_entry.last_tick) or 0;
            if (candidate_bottom == bottom and (tick() - candidate_tick) <= 300000) then
                add_native_bank_candidate(candidate_entry);
                add_base_candidate(candidate_entry);
            end
        end
    end

    local function cursor_record_text_ok(decoded, detail)
        local text = decoded ~= nil and tostring(decoded.text or '') or '';
        local speech_quality = accessxi.chat_log_speech_text(text);
        local speech = accessxi.chat_log_speech_text(text, true);
        local reject_reason = accessxi.chat_log_cursor_record_reject_reason(speech_quality, detail);
        local ok = decoded ~= nil
            and speech_quality ~= ''
            and #speech <= (tonumber(accessxi.chat_log_max_line_len) or 150)
            and (accessxi.chat_log_selected_source_quality_ok(speech_quality)
                or accessxi.chat_log_native_continuation_word_ok(speech_quality))
            and speech_quality:lower():find('access8', 1, true) == nil
            and speech_quality:lower():find('chatlog.[accessx', 1, true) == nil
            and speech_quality:lower():find('participatingin', 1, true) == nil
            and speech_quality:lower():find('unitychatplease', 1, true) == nil
            and reject_reason == 'ok';
        return ok, text, speech, speech_quality, reject_reason;
    end

    local function derived_base_has_neighbor(base, anchor_cursor)
        base = tonumber(base) or 0;
        anchor_cursor = tonumber(anchor_cursor) or cursor;
        if (not accessxi.is_probe_pointer(base)) then
            return false;
        end

        for _, delta in ipairs(T{ -1, 1 }) do
            local neighbor_cursor = anchor_cursor + delta;
            if (neighbor_cursor >= 0 and neighbor_cursor <= 10000) then
                local neighbor_ptr = base + (neighbor_cursor * stride);
                if (accessxi.is_probe_pointer(neighbor_ptr)) then
                    local neighbor_decoded, neighbor_detail = accessxi.chat_log_cursor_record_decode(neighbor_ptr);
                    local neighbor_ok = cursor_record_text_ok(neighbor_decoded, neighbor_detail);
                    if (neighbor_ok) then
                        return true;
                    end
                end
            end
        end
        return false;
    end

    local function edge_cursor_record_quality_ok(text, record_cursor)
        text = accessxi.chat_log_speech_text(text);
        record_cursor = tonumber(record_cursor) or cursor;
        if (record_cursor >= 0 and record_cursor <= bottom) then
            return true;
        end
        if (accessxi.chat_log_native_continuation_word_ok(text)) then
            return true;
        end
        if (text == '' or accessxi.chat_log_has_suspicious_noise(text)) then
            return false;
        end

        local lower = text:lower();
        if (lower:find('jobabi', 1, true) ~= nil
            or lower:find('jobab', 1, true) ~= nil
            or lower:find('menu ', 1, true) ~= nil
            or lower:find('keytop', 1, true) ~= nil
            or lower:find('newtex', 1, true) ~= nil
            or lower:find('gauge', 1, true) ~= nil
            or lower:find('font', 1, true) ~= nil
            or lower == 'white wm'
            or lower:find('white wm', 1, true) ~= nil
            or lower:find('black black', 1, true) ~= nil
            or lower:match('^xp[%w%d%p]+$') ~= nil) then
            return false;
        end

        local words = 0;
        local short_words = 0;
        local letters = 0;
        local digits = 0;
        local spaces = 0;
        local punctuation = 0;
        for _ in text:gmatch('%S+') do
            words = words + 1;
        end
        for word in text:gmatch('%S+') do
            local clean = word:gsub('[^A-Za-z]', '');
            if (#clean <= 3) then
                short_words = short_words + 1;
            end
        end
        for i = 1, #text do
            local b = text:byte(i) or 0;
            if ((b >= 65 and b <= 90) or (b >= 97 and b <= 122)) then
                letters = letters + 1;
            elseif (b >= 48 and b <= 57) then
                digits = digits + 1;
            elseif (b == 32) then
                spaces = spaces + 1;
            else
                punctuation = punctuation + 1;
            end
        end
        if (spaces <= 0 and digits > 0 and punctuation > 0 and not accessxi.chat_log_has_time(text)) then
            return false;
        end
        if (words > 0 and words <= 3 and short_words >= words and not accessxi.chat_log_has_time(text)) then
            return false;
        end
        if (words >= 3) then
            if (words <= 3 and short_words >= words) then
                return false;
            end
            if (digits > math.max(2, math.floor(letters * 0.25))) then
                return false;
            end
            if (punctuation > math.max(4, math.floor(letters * 0.25))) then
                return false;
            end
            if (text:match('^A+') ~= nil) then
                return false;
            end
            return true;
        end
        if (accessxi.chat_log_has_time(text)
            or (text:find('[', 1, true) ~= nil and text:find(']', 1, true) ~= nil)
            or (text:find('{', 1, true) ~= nil and text:find('}', 1, true) ~= nil)) then
            return true;
        end
        if (lower == 'conquest update'
            or lower == 'regional influence'
            or lower == 'version by accessxi') then
            return true;
        end
        if (words == 2 and text:match('^[A-Z][A-Za-z]+%s+[a-z][A-Za-z]+$') ~= nil) then
            return true;
        end
        return false;
    end

    local direct_count = candidates:len();
    if (direct_count > 0) then
        local row_count = tonumber(state.row_count) or 0;
        local page_shifts = T{ -5, 5, -10, 10, -15, 15, -20, 20, -25, 25, -30, 30 };
        if (row_count > 0 and row_count <= 80) then
            page_shifts:append(0 - row_count);
            page_shifts:append(row_count);
        end
        for i = 1, direct_count do
            local parent = candidates[i];
            local parent_base = tonumber(parent ~= nil and parent.base or nil) or 0;
            if (accessxi.is_probe_pointer(parent_base)) then
                for _, row_delta in ipairs(page_shifts) do
                    row_delta = tonumber(row_delta) or 0;
                    if (row_delta ~= 0) then
                        local shifted_base = parent_base + (row_delta * stride);
                        if (accessxi.is_probe_pointer(shifted_base)) then
                            add_base_candidate(T{
                                base = shifted_base,
                                hits = tonumber(parent.hits) or 0,
                                last_cursor = tonumber(parent.last_cursor) or last_cursor,
                                last_bottom = bottom,
                                last_tick = tonumber(parent.last_tick) or last_tick,
                                derived = true,
                                row_delta = row_delta,
                                parent_base = parent_base,
                            });
                        end
                    end
                end
            end
        end
    end

    local chosen = nil;
    local first_reject = nil;
    local reject_summary = T{};
    for index, candidate_entry in ipairs(candidates) do
        local base = tonumber(candidate_entry.base) or 0;
        local cursor_choices = T{};
        if (effective_cursor ~= cursor) then
            cursor_choices:append(T{ cursor = effective_cursor, edge = true });
        elseif (edge_name ~= '') then
            cursor_choices:append(T{ cursor = cursor, edge = true });
        else
            cursor_choices:append(T{ cursor = cursor, edge = false });
        end
        for _, cursor_choice in ipairs(cursor_choices) do
            local record_cursor = tonumber(cursor_choice.cursor) or cursor;
            local ptr = base + (record_cursor * stride);
        if (accessxi.is_probe_pointer(ptr)) then
            local decoded, detail = accessxi.chat_log_cursor_record_decode(ptr);
            local ok, text, speech, speech_quality, reject_reason = cursor_record_text_ok(decoded, detail);
            if (ok and cursor_choice.edge == true and not edge_cursor_record_quality_ok(speech_quality, record_cursor)) then
                ok = false;
                reject_reason = 'edge-quality';
            end
            if (ok and candidate_entry.derived == true and not derived_base_has_neighbor(base, record_cursor)) then
                ok = false;
                reject_reason = 'derived-no-neighbor';
            end
            reject_summary:append(('%d%s%s%s:0x%08X[%d]->0x%08X:%s:%s'):fmt(
                index,
                candidate_entry.derived == true and (':d' .. tostring(candidate_entry.row_delta or 0)) or '',
                candidate_entry.native_bank == true and ':bank' or '',
                cursor_choice.edge == true and ':edge' or '',
                base,
                record_cursor,
                ptr,
                ok and 'ok' or reject_reason,
                accessxi.escape_probe_log_text(text)));
            if (first_reject == nil) then
                first_reject = T{
                    ptr = ptr,
                    reason = reject_reason,
                    detail = detail,
                };
            end
            if (ok) then
                chosen = T{
                    decoded = decoded,
                    detail = detail,
                    text = text,
                    speech = speech,
                    speech_quality = speech_quality,
                    reject_reason = reject_reason,
                    base = base,
                    ptr = ptr,
                    index = index,
                    hits = tonumber(candidate_entry.hits) or tonumber(entry.hits) or 0,
                    last_cursor = tonumber(candidate_entry.last_cursor) or last_cursor,
                    derived = candidate_entry.derived == true,
                    native_bank = candidate_entry.native_bank == true,
                    row_delta = tonumber(candidate_entry.row_delta) or 0,
                    record_cursor = record_cursor,
                    edge = cursor_choice.edge == true,
                    edge_name = edge_name,
                    edge_offset = tonumber(accessxi.chat_log_cursor_edge_offset) or 0,
                };
                break;
            end
        end
        end
        if (chosen ~= nil) then
            break;
        end
    end

    local base = chosen ~= nil and chosen.base or (tonumber(entry.base) or 0);
    local record_cursor = chosen ~= nil and (tonumber(chosen.record_cursor) or cursor) or effective_cursor;
    local ptr = chosen ~= nil and chosen.ptr or (base + (record_cursor * stride));
    local text = chosen ~= nil and chosen.text or '';
    local speech = chosen ~= nil and chosen.speech or '';
    local reject_reason = chosen ~= nil and chosen.reject_reason or (first_reject ~= nil and first_reject.reason or 'no-candidate');
    local ok = chosen ~= nil;

    local log_key = ('%s:%08X:%d:%d:%d:%08X:%s:%s:%s'):fmt(key, base, cursor, record_cursor, bottom, ptr, ok and 'yes' or 'no', text, reject_summary:concat('|'));
    if (log_key ~= (accessxi.chat_log_cursor_record_last_probe or '')) then
        accessxi.chat_log_cursor_record_last_probe = log_key;
        log_state(('state chatlog cursor-record data=0x%08X cursor=%d recordCursor=%d edge="%s" edgeOffset=%d bottom=%d base=0x%08X ptr=0x%08X decoded=%s reason="%s" text="%s" detail="%s" lastCursor=%d hits=%d bases="%s"'):fmt(
            tonumber(state.data) or 0,
            cursor,
            record_cursor,
            tostring(chosen ~= nil and chosen.edge_name or edge_name),
            tonumber(accessxi.chat_log_cursor_edge_offset) or 0,
            bottom,
            base,
            ptr,
            ok and 'yes' or 'no',
            accessxi.escape_probe_log_text(reject_reason),
            accessxi.escape_probe_log_text(text),
            accessxi.escape_probe_log_text(chosen ~= nil and (chosen.detail or '') or ''),
            chosen ~= nil and (tonumber(chosen.last_cursor) or last_cursor) or last_cursor,
            chosen ~= nil and (tonumber(chosen.hits) or 0) or (tonumber(entry.hits) or 0),
            accessxi.escape_probe_log_text(reject_summary:concat(' | '))));
    end

    if (not ok) then
        if (first_reject ~= nil) then
            accessxi.chat_log_cursor_record_reject_probe(state, first_reject.ptr, first_reject.reason, first_reject.detail);
        end
        return nil;
    end

    local decoded = chosen.decoded;
    if (accessxi.chat_log_repair_apururu_defeated_row ~= nil
        and tostring(speech or ''):find("I believe we've defeated", 1, true) ~= nil
        and tostring(speech or ''):find('monsters', 1, true) == nil) then
        local next_decoded = nil;
        local total_decoded = nil;
        if (accessxi.is_probe_pointer(ptr + stride) and accessxi.is_probe_pointer(ptr + (stride * 2))) then
            next_decoded = accessxi.chat_log_cursor_record_decode(ptr + stride);
            total_decoded = accessxi.chat_log_cursor_record_decode(ptr + (stride * 2));
        end
        local next_text = next_decoded ~= nil and accessxi.chat_log_speech_text(next_decoded.text or '') or '';
        local total_text = total_decoded ~= nil and accessxi.chat_log_speech_text(total_decoded.text or '') or '';
        local repaired_speech = accessxi.chat_log_repair_apururu_defeated_row(speech, next_text, total_text);
        log_state(('state chatlog row-repair apururu-defeated row="%s" next="%s" total="%s" repaired="%s" changed=%s'):fmt(
            accessxi.escape_probe_log_text(speech),
            accessxi.escape_probe_log_text(next_text),
            accessxi.escape_probe_log_text(total_text),
            accessxi.escape_probe_log_text(repaired_speech),
            repaired_speech ~= speech and 'yes' or 'no'));
        if (repaired_speech ~= speech) then
            speech = repaired_speech;
        end
    end
    decoded.text = speech;
    if (chosen.edge == true) then
        decoded.source = ('fulllog-cursor-record-edge%s%+d+%02X@0x%08X'):fmt(
            tostring(chosen.edge_name or ''),
            tonumber(chosen.edge_offset) or 0,
            tonumber(decoded.source_offset) or 0,
            ptr);
    elseif (chosen.native_bank == true) then
        decoded.source = ('fulllog-cursor-record-bank%+d+%02X@0x%08X'):fmt(
            tonumber(chosen.row_delta) or 0,
            tonumber(decoded.source_offset) or 0,
            ptr);
    elseif (chosen.derived == true) then
        decoded.source = ('fulllog-cursor-record-shift%+d+%02X@0x%08X'):fmt(
            tonumber(chosen.row_delta) or 0,
            tonumber(decoded.source_offset) or 0,
            ptr);
    else
        decoded.source = ('fulllog-cursor-record+%02X@0x%08X'):fmt(
            tonumber(decoded.source_offset) or 0,
            ptr);
    end
    decoded.score = 44000;
    decoded.chat_log_menu_nav = true;
    decoded.chat_log_row_selected = tonumber(state.selected_index) or 0;
    decoded.chat_log_row_count = tonumber(state.row_count) or 0;
    if (chosen.edge == true) then
        decoded.chat_log_selection_reason = 'native-fulllog-cursor-record-edge';
    else
        decoded.chat_log_selection_reason = chosen.native_bank == true
            and 'native-fulllog-cursor-record-bank'
            or chosen.derived == true
            and 'native-fulllog-cursor-record-shift'
            or 'native-fulllog-cursor-record-strict';
    end
    decoded.visible_signature = ('%d:%d:%d:0x%08X:%s'):fmt(
        cursor,
        record_cursor,
        bottom,
        ptr,
        speech);
    if (chosen.derived == true and chosen.edge ~= true) then
        accessxi.chat_log_cursor_record_learn_base(state, ptr, decoded);
    end
    if (chosen.edge == true) then
        accessxi.chat_log_cursor_edge_success_base = tonumber(chosen.base) or 0;
        accessxi.chat_log_cursor_edge_success_state_key = tostring(accessxi.chat_log_cursor_edge_state_key or '');
        accessxi.chat_log_cursor_edge_success_tick = tick();
    end
    return decoded;
end

accessxi.chat_log_native_line_from_selected_source = function (state)
    if (state == nil or not accessxi.is_probe_pointer(state.data)) then
        return nil;
    end

    local rendered_window_ok = accessxi.chat_log_cursor_is_in_rendered_row_window(state);
    local source_ptr = read_u32(state.data + 0x28) or 0;
    local source_meta = read_u32(state.data + 0x2C) or 0;
    local source_flag = read_u32(state.data + 0x24) or 0;
    local decoded, detail = accessxi.chat_log_selected_source_record_text(source_ptr);
    local text = decoded ~= nil and tostring(decoded.text or '') or '';
    local glyph_text = '';
    if (decoded ~= nil and not accessxi.chat_log_selected_source_quality_ok(text)) then
        decoded = nil;
        text = '';
    end

    if (decoded == nil and rendered_window_ok and accessxi.is_probe_pointer(source_ptr)) then
        glyph_text = accessxi.chat_log_decode_selected_source_glyph_text(source_ptr);
        if (glyph_text ~= '' and accessxi.chat_log_rich_render_text_ok(glyph_text)) then
            decoded = T{
                text = glyph_text,
                source_offset = 0x38,
                source_mode = 'glyph-minus-20',
            };
            text = glyph_text;
        end
    end

    if (decoded == nil and accessxi.is_probe_pointer(source_ptr)) then
        local cursor_decoded, cursor_detail = accessxi.chat_log_cursor_record_decode(source_ptr);
        local cursor_text = cursor_decoded ~= nil and tostring(cursor_decoded.text or '') or '';
        local cursor_speech = accessxi.chat_log_speech_text(cursor_text);
        local cursor_ok = cursor_decoded ~= nil
            and (accessxi.chat_log_selected_source_quality_ok(cursor_speech)
                or accessxi.chat_log_native_continuation_word_ok(cursor_speech));
        local cursor_log_key = ('0x%08X:%d:%d:%s:%s'):fmt(
            source_ptr,
            tonumber(state.cursor) or -1,
            tonumber(state.bottom) or -1,
            cursor_ok and 'yes' or 'no',
            cursor_text);
        if (cursor_log_key ~= (accessxi.chat_log_selectedptr_cursor_last_probe or '')) then
            accessxi.chat_log_selectedptr_cursor_last_probe = cursor_log_key;
            log_state(('state chatlog selectedptr-cursor-record data=0x%08X cursor=%d bottom=%d selectedIndex=%d ptr=0x%08X decoded=%s text="%s" detail="%s"'):fmt(
                tonumber(state.data) or 0,
                tonumber(state.cursor) or -1,
                tonumber(state.bottom) or -1,
                tonumber(state.selected_index) or -1,
                source_ptr,
                cursor_ok and 'yes' or 'no',
                accessxi.escape_probe_log_text(cursor_text),
                accessxi.escape_probe_log_text(cursor_detail or '')));
        end
        if (cursor_ok) then
            decoded = cursor_decoded;
            text = cursor_text;
            detail = (detail or '') .. ' | selectedptr-cursor-record ' .. (cursor_detail or '');
        end
    end

    if (decoded == nil and rendered_window_ok and accessxi.is_probe_pointer(source_ptr)) then
        local raw_glyph = accessxi.chat_log_decode_selected_source_glyph_text(source_ptr);
        local glyph_log_key = ('0x%08X:%d:%d:%s'):fmt(
            source_ptr,
            tonumber(state.cursor) or -1,
            tonumber(state.bottom) or -1,
            raw_glyph);
        if (glyph_log_key ~= (accessxi.chat_log_selected_source_glyph_reject_last_probe or '')) then
            accessxi.chat_log_selected_source_glyph_reject_last_probe = glyph_log_key;
            log_state(('state chatlog selected-source-glyph-reject data=0x%08X cursor=%d bottom=%d selectedIndex=%d ptr=0x%08X text="%s" ok=%d probe="%s"'):fmt(
                tonumber(state.data) or 0,
                tonumber(state.cursor) or -1,
                tonumber(state.bottom) or -1,
                tonumber(state.selected_index) or -1,
                source_ptr,
                accessxi.escape_probe_log_text(raw_glyph),
                accessxi.chat_log_rich_render_text_ok(raw_glyph) and 1 or 0,
                accessxi.escape_probe_log_text(accessxi.chat_log_selected_source_glyph_probe(source_ptr) or '')));
        end
    end

    local log_key = ('0x%08X:%08X:%08X:%d:%d:%s'):fmt(
        source_ptr,
        source_meta,
        source_flag,
        tonumber(state.cursor) or -1,
        tonumber(state.bottom) or -1,
        text);
    if (log_key ~= (accessxi.chat_log_selected_source_last_probe or '')) then
        accessxi.chat_log_selected_source_last_probe = log_key;
        log_state(('state chatlog selected-source data=0x%08X cursor=%d bottom=%d inWindow=%d selectedIndex=%d ptr=0x%08X flag=0x%08X meta=0x%08X decoded=%s text="%s" candidates="%s" ptrDwords=%s ptrBytes=%s glyph="%s" ptrs="%s"'):fmt(
            tonumber(state.data) or 0,
            tonumber(state.cursor) or -1,
            tonumber(state.bottom) or -1,
            rendered_window_ok and 1 or 0,
            tonumber(state.selected_index) or -1,
            source_ptr,
            source_flag,
            source_meta,
            decoded ~= nil and 'yes' or 'no',
            accessxi.escape_probe_log_text(text),
            accessxi.escape_probe_log_text(detail or ''),
            accessxi.is_probe_pointer(source_ptr) and accessxi.format_probe_dwords(source_ptr, 0, 24) or '',
            accessxi.is_probe_pointer(source_ptr) and accessxi.format_probe_bytes(source_ptr, 0, 0x80) or '',
            rendered_window_ok and accessxi.escape_probe_log_text((accessxi.chat_log_selected_source_glyph_probe(source_ptr) or '') .. ' decodedGlyph="' .. (glyph_text or '') .. '"') or '',
            accessxi.escape_probe_log_text(accessxi.chat_log_selected_source_pointer_probe(source_ptr))));
    end

    if (decoded == nil or text == '') then
        return nil;
    end

    decoded.source = ('fulllog-selected-source+%02X@0x%08X'):fmt(
        tonumber(decoded.source_offset) or 0,
        tonumber(source_ptr) or 0);
    decoded.score = decoded.source_mode == 'glyph-minus-20' and 45000 or 30000;
    decoded.chat_log_menu_nav = true;
    decoded.chat_log_row_selected = tonumber(state.selected_index) or 0;
    decoded.chat_log_row_count = tonumber(state.row_count) or 0;
    decoded.chat_log_selection_reason = 'native-fulllog-selected-source';
    decoded.visible_signature = ('%d:%d:0x%08X:%s'):fmt(
        tonumber(state.cursor) or -1,
        tonumber(state.bottom) or -1,
        source_ptr,
        text);
    accessxi.chat_log_cursor_record_learn_base(state, source_ptr, decoded);
    return decoded;
end

accessxi.chat_log_native_line_from_global_state = function (obj, menu_name)
    local state = accessxi.chat_log_global_state_from_menu_obj(obj, menu_name);
    if (state == nil) then
        return nil;
    end
    accessxi.chat_log_selected_row_chain_detail(state);

    local full_log_menu = tostring(menu_name or ''):eq('menu    fulllog', true);
    if (full_log_menu) then
        return nil;
    end

    local source_row = accessxi.chat_log_native_line_from_selected_source(state);
    if (source_row ~= nil) then
        return source_row;
    end

    local cursor_record = accessxi.chat_log_native_line_from_cursor_record(state);
    if (cursor_record ~= nil) then
        return cursor_record;
    end

    local fixedgrid_row = accessxi.chat_log_native_line_from_fixedgrid_fulllog(obj, state);
    if (fixedgrid_row ~= nil) then
        return fixedgrid_row;
    end

    local rendered_row = accessxi.chat_log_native_line_from_rendered_fulllog(obj, state);
    if (rendered_row ~= nil) then
        return rendered_row;
    end

    local rendered_window_ok = accessxi.chat_log_cursor_is_in_rendered_row_window(state);
    local selected_row_ok = accessxi.chat_log_selected_row_pointer_usable(state);
    local glyph_row, glyph_detail = nil, '';
    if (selected_row_ok) then
        glyph_row, glyph_detail = accessxi.chat_log_selected_row_glyph_text(state);
    end
    local glyph_log_key = ('0x%08X:%d:%d:%s'):fmt(
        tonumber(state.selected_row) or 0,
        tonumber(state.cursor) or -1,
        tonumber(state.bottom) or -1,
        glyph_row ~= nil and tostring(glyph_row.text or '') or '');
    if (selected_row_ok and glyph_log_key ~= (accessxi.chat_log_selected_row_glyph_last_probe or '')) then
        accessxi.chat_log_selected_row_glyph_last_probe = glyph_log_key;
        log_state(('state chatlog selected-row-glyph row=0x%08X cursor=%d bottom=%d inWindow=%d decoded=%s text="%s" detail="%s"'):fmt(
            tonumber(state.selected_row) or 0,
            tonumber(state.cursor) or -1,
            tonumber(state.bottom) or -1,
            rendered_window_ok and 1 or 0,
            glyph_row ~= nil and 'yes' or 'no',
            glyph_row ~= nil and accessxi.escape_probe_log_text(glyph_row.text or '') or '',
            accessxi.escape_probe_log_text(glyph_detail or '')));
    end
    if (glyph_row ~= nil) then
        return glyph_row;
    end

    local row = nil;
    local row_base = 0;
    if (selected_row_ok) then
        for _, base_delta in ipairs(T{ 0x00, -0x40, -0x80, -0xC0, -0x100 }) do
            row = accessxi.chat_log_decode_row_record(state.selected_row + base_delta);
            if (row ~= nil) then
                row_base = state.selected_row + base_delta;
                break;
            end
        end
    end

    local row_preview = '';
    if (selected_row_ok and accessxi.collect_probe_ascii_runs ~= nil) then
        row_preview = accessxi.collect_probe_ascii_runs(state.selected_row, 0x180, 5, 8):concat('|');
    end
    local row_dwords = selected_row_ok and accessxi.format_probe_dwords(state.selected_row, 0, 20) or '';
    local row_ptrs = selected_row_ok and accessxi.chat_log_selected_row_pointer_probe(state.selected_row) or '';
    local row_chain = selected_row_ok and accessxi.chat_log_selected_row_chain_probe(state.selected_row) or '';
    local data_dwords = accessxi.is_probe_pointer(state.data) and accessxi.format_probe_dwords(state.data, 0, 64) or '';
    local log_key = ('0x%08X:0x%08X:%d:%d:%d:%08X:%s'):fmt(
        tonumber(state.global_slot) or 0,
        tonumber(state.data) or 0,
        tonumber(state.cursor) or -1,
        tonumber(state.bottom) or -1,
        tonumber(state.selected_index) or -1,
        tonumber(state.selected_row) or 0,
        row ~= nil and tostring(row.text or '') or '');
    if (log_key ~= (accessxi.chat_log_global_state_last_probe or '')) then
        accessxi.chat_log_global_state_last_probe = log_key;
        log_state(('state chatlog strict-global menu="%s" obj=0x%08X desc=0x%08X source="%s" slot=0x%08X data=0x%08X cursor=%d bottom=%d rows=%d windowTop=%d windowBottom=%d inWindow=%d selectedIndexRaw=%d selectedIndex=%d selectedRow=0x%08X decoded=%s rowBase=0x%08X text="%s" rowRuns="%s" rowPtrs="%s" rowChain="%s" data=%s row=%s'):fmt(
            tostring(menu_name or ''),
            tonumber(obj) or 0,
            tonumber(state.desc) or 0,
            accessxi.escape_probe_log_text(tostring(state.source or '')),
            tonumber(state.global_slot) or 0,
            tonumber(state.data) or 0,
            tonumber(state.cursor) or -1,
            tonumber(state.bottom) or -1,
            tonumber(state.row_count) or 0,
            tonumber(state.row_window_top) or -1,
            tonumber(state.row_window_bottom) or -1,
            rendered_window_ok and 1 or 0,
            tonumber(state.selected_index_unclamped) or -1,
            tonumber(state.selected_index) or -1,
            tonumber(state.selected_row) or 0,
            row ~= nil and 'yes' or 'no',
            row_base,
            row ~= nil and accessxi.escape_probe_log_text(row.text or '') or '',
            accessxi.escape_probe_log_text(row_preview),
            accessxi.escape_probe_log_text(row_ptrs),
            accessxi.escape_probe_log_text(row_chain),
            data_dwords,
            row_dwords));
    end

    return nil;
end

accessxi.chat_log_fulllog_text_buffer_diagnostic = function (obj, menu_name, state)
    obj = tonumber(obj) or 0;
    if (not accessxi.is_probe_pointer(obj)) then
        return;
    end

    menu_name = tostring(menu_name or '');
    if (not menu_name:eq('menu    fulllog', true)) then
        return;
    end

    local data = state ~= nil and (tonumber(state.data) or 0) or 0;
    local cursor = state ~= nil and (tonumber(state.cursor) or -1) or -1;
    local bottom = state ~= nil and (tonumber(state.bottom) or -1) or -1;
    local row_count = state ~= nil and (tonumber(state.row_count) or 0) or 0;
    local selected_index_unclamped = state ~= nil and (tonumber(state.selected_index_unclamped) or -1) or -1;
    local selected_index = state ~= nil and (tonumber(state.selected_index) or -1) or -1;
    local selected_row = state ~= nil and (tonumber(state.selected_row) or 0) or 0;
    local source_flag = accessxi.is_probe_pointer(data) and (read_u32(data + 0x24) or 0) or 0;
    local source_ptr = accessxi.is_probe_pointer(data) and (read_u32(data + 0x28) or 0) or 0;
    local source_meta = accessxi.is_probe_pointer(data) and (read_u32(data + 0x2C) or 0) or 0;
    local visible = read_u32(obj + 0x88) or 0;

    local key = ('0x%08X:0x%08X:%d:%d:%d:%d:0x%08X:0x%08X'):fmt(
        obj,
        data,
        cursor,
        bottom,
        selected_index_unclamped,
        selected_index,
        selected_row,
        source_ptr);
    if (key == (accessxi.chat_log_fulllog_buffer_diag_last_probe or '')) then
        return;
    end
    accessxi.chat_log_fulllog_buffer_diag_last_probe = key;

    local function ptr_ascii_summary(label, ptr)
        ptr = tonumber(ptr) or 0;
        if (not accessxi.is_probe_pointer(ptr)) then
            return ('%s=0x%08X'):fmt(label, ptr);
        end

        local runs = T{};
        if (accessxi.collect_probe_ascii_runs ~= nil) then
            runs = accessxi.collect_probe_ascii_runs(ptr, 0x480, 4, 16);
        end

        local direct = T{};
        for _, off in ipairs(T{ 0x00, 0x20, 0x30, 0x40, 0x46, 0x50, 0x60, 0x70, 0x80, 0x8C, 0x90, 0xA0, 0xC0, 0x100, 0x140, 0x180 }) do
            local text = accessxi.chat_log_ascii_text_from_ptr(ptr + off, accessxi.chat_log_max_line_len);
            text = accessxi.chat_log_speech_text(text);
            if (text ~= '' and #text >= 4 and #direct < 10) then
                direct:append(('+%03X="%s"'):fmt(off, accessxi.escape_probe_log_text(text)));
            end
        end

        return ('%s=0x%08X runs="%s" direct="%s" dwords=%s'):fmt(
            label,
            ptr,
            accessxi.escape_probe_log_text(runs:concat(' | ')),
            direct:concat(' | '),
            accessxi.format_probe_dwords(ptr, 0, 12));
    end

    local source_summary = ptr_ascii_summary('selectedSource', source_ptr);
    local rendered_summary = 'none';
    local rendered_count = 0;
    if (accessxi.is_probe_pointer(visible) and accessxi.chat_log_fulllog_rendered_rows ~= nil) then
        local rows = accessxi.chat_log_fulllog_rendered_rows(visible, 0x1800, 32);
        rendered_count = rows:len();
        local parts = T{};
        for i = 1, math.min(rendered_count, 8) do
            local row = rows[i];
            if (row ~= nil) then
                parts:append(('%02d@+%03X="%s"'):fmt(
                    i,
                    tonumber(row.offset) or 0,
                    accessxi.escape_probe_log_text(row.text or '')));
            end
        end
        if (parts:len() > 0) then
            rendered_summary = parts:concat(' | ');
        end
    end

    local data_rows = T{};
    if (accessxi.is_probe_pointer(data)) then
        for i = 0, math.min(math.max(row_count, 0), 10) - 1 do
            data_rows:append(('%02d=0x%08X'):fmt(i, read_u32(data + 0x80 + (i * 4)) or 0));
        end
    end

    local cursor_records = T{};
    local cursor_key = accessxi.chat_log_cursor_record_key ~= nil and accessxi.chat_log_cursor_record_key(state) or '';
    local base_lists = accessxi.chat_log_cursor_record_base_lists or {};
    local bases = base_lists[cursor_key] or T{};
    local stride = tonumber(accessxi.chat_log_cursor_record_stride) or 0x800;
    for i = 1, math.min(#bases, 4) do
        local base_entry = bases[i];
        local base = tonumber(base_entry) or tonumber(base_entry ~= nil and base_entry.base or nil) or 0;
        local ptr = base + ((cursor >= 0 and cursor or 0) * stride);
        local decoded = accessxi.chat_log_cursor_record_decode ~= nil and accessxi.chat_log_cursor_record_decode(ptr) or nil;
        local text = decoded ~= nil and accessxi.chat_log_speech_text(decoded.text or '') or '';
        cursor_records:append(('%d:base=0x%08X ptr=0x%08X text="%s"'):fmt(
            i,
            base,
            ptr,
            accessxi.escape_probe_log_text(text)));
    end
    if (cursor_records:len() <= 0) then
        cursor_records:append('none');
    end

    local parts = T{};
    for _, off in ipairs(T{ 0x88, 0x8C, 0x90, 0x94, 0x98, 0x9C, 0xA0 }) do
        local ptr = read_u32(obj + off) or 0;
        parts:append(ptr_ascii_summary(('obj+%02X'):fmt(off), ptr));
    end

    log_state(('state chatlog fulllog-buffer-diag menu="%s" obj=0x%08X data=0x%08X cursor=%d bottom=%d rows=%d selectedIndexRaw=%d selectedIndex=%d selectedRow=0x%08X sourceFlag=0x%08X sourcePtr=0x%08X sourceMeta=0x%08X visible=0x%08X renderedRows=%d rendered="%s" dataRows="%s" cursorRecords="%s" source="%s" objFields=%s buffers="%s"'):fmt(
        menu_name,
        obj,
        data,
        cursor,
        bottom,
        row_count,
        selected_index_unclamped,
        selected_index,
        selected_row,
        source_flag,
        source_ptr,
        source_meta,
        visible,
        rendered_count,
        accessxi.escape_probe_log_text(rendered_summary),
        accessxi.escape_probe_log_text(data_rows:concat(' | ')),
        accessxi.escape_probe_log_text(cursor_records:concat(' | ')),
        accessxi.escape_probe_log_text(source_summary),
        accessxi.format_probe_dwords(obj, 0x80, 16),
        parts:concat(' || ')));
end

accessxi.chat_log_rendered_timestamp_row_text = function (ptr)
    ptr = tonumber(ptr) or 0;
    if (not accessxi.is_probe_pointer(ptr)) then
        return '';
    end

    local marker_len = 0;
    if (accessxi.chat_log_probe_timestamp_marker_len ~= nil) then
        marker_len = tonumber(accessxi.chat_log_probe_timestamp_marker_len(ptr)) or 0;
    end
    if (marker_len <= 0) then
        return '';
    end

    local bytes = T{};
    local non_printable_run = 0;
    local max_len = math.min(tonumber(accessxi.chat_log_max_line_len) or 150, 150);
    for off = 0, max_len - 1 do
        if (off > 0
            and accessxi.chat_log_probe_timestamp_marker_len ~= nil
            and (tonumber(accessxi.chat_log_probe_timestamp_marker_len(ptr + off)) or 0) > 0) then
            break;
        end

        local byte_value = read_u8(ptr + off);
        if (byte_value == nil) then
            break;
        end
        if (byte_value == 0) then
            if (#bytes >= marker_len) then
                break;
            end
        elseif (accessxi.probe_printable_ascii ~= nil and accessxi.probe_printable_ascii(byte_value)) then
            bytes:append(string.char(byte_value));
            non_printable_run = 0;
        elseif (byte_value == 0x09 or byte_value == 0x0A or byte_value == 0x0D) then
            bytes:append(' ');
            non_printable_run = 0;
        else
            non_printable_run = non_printable_run + 1;
            if (#bytes >= marker_len and non_printable_run >= 3) then
                break;
            end
            if (#bytes > 0 and non_printable_run == 1) then
                bytes:append(' ');
            end
        end
    end

    local text = accessxi.chat_log_clean_native_text(bytes:concat(''));
    text = text:gsub("%s+[\"']?%s*|%s*%+%x%x%x=.*$", ''):trim();
    text = text:gsub('%s+[%.%p%s]*|%s*%+%x%x%x%x=.*$', ''):trim();
    text = text:gsub('%s+bytes=%x%x.*$', ''):trim();
    text = text:gsub('(%[Addons%]%s+Loaded addon:%s+accessxi_reader)%s+@[%w%p]+$', '%1'):trim();
    text = text:gsub('(%[Addons%]%s+Loaded addon:%s+accessxi_reader)%s+[%w%p]+$', '%1'):trim();
    text = text:gsub('(%[Addons%]%s+Loaded addon:%s+accessxi_reader)%s+[%x,]+.*$', '%1'):trim();
    return accessxi.chat_log_clean_native_text(text);
end

accessxi.chat_log_fulllog_rendered_rows = function (ptr, scan_len, max_rows)
    ptr = tonumber(ptr) or 0;
    if (not accessxi.is_probe_pointer(ptr) or accessxi.chat_log_probe_timestamp_marker_len == nil) then
        return T{};
    end

    scan_len = tonumber(scan_len) or 0x1000;
    max_rows = tonumber(max_rows) or 64;
    local rows = T{};
    local off = 0;
    local function rendered_row_quality_ok(text)
        text = tostring(text or ''):trim();
        if (accessxi.chat_log_plain_text_quality_ok(text, false)) then
            return true;
        end
        if (#text < 7 or #text > (tonumber(accessxi.chat_log_max_line_len) or 150)) then
            return false;
        end
        if (text:match('^%w+$') == nil) then
            return false;
        end
        if (text:find('%a') == nil) then
            return false;
        end
        local lower = text:lower();
        return lower:find('menu', 1, true) == nil
            and lower:find('accessxi', 1, true) == nil
            and lower:find('chatprobe', 1, true) == nil
            and lower:find('chatlog', 1, true) == nil;
    end

    while (off < scan_len and rows:len() < max_rows) do
        local marker_len = tonumber(accessxi.chat_log_probe_timestamp_marker_len(ptr + off)) or 0;
        if (marker_len > 0) then
            local text = accessxi.chat_log_rendered_timestamp_row_text(ptr + off);
            local speech = accessxi.chat_log_speech_text(text);
            if (speech ~= '' and #speech <= (tonumber(accessxi.chat_log_max_line_len) or 150)
                and rendered_row_quality_ok(speech)) then
                local entry = T{
                    offset = off,
                    address = ptr + off,
                    text = speech,
                    raw = text,
                };
                local last = rows[rows:len()];
                if (last ~= nil and (off - (tonumber(last.offset) or 0)) <= 0x24) then
                    if (#speech > #(tostring(last.text or ''))) then
                        rows[rows:len()] = entry;
                    end
                else
                    rows:append(entry);
                end
            end
            off = off + math.max(marker_len, 1);
        else
            off = off + 1;
        end
    end

    return rows;
end

accessxi.chat_log_fixedgrid_text_quality_ok = function (text)
    text = tostring(text or ''):trim();
    if (text == '') then
        return false;
    end

    local max_len = tonumber(accessxi.chat_log_max_line_len) or 150;
    if (#text < 3 or #text > max_len) then
        return false;
    end
    if (text:match('^[%p%s]+$') ~= nil or text:match('^%d+$') ~= nil) then
        return false;
    end
    if (text:find('80808080', 1, true) ~= nil
        or text:find('000000', 1, true) ~= nil
        or text:match('^%x%x?,%x%x?,') ~= nil
        or text:match('^%x%x%x%x%x%x%x%x[,%s]') ~= nil
        or text:match('[,{]%u%s+[,{]%u') ~= nil
        or text:match('^[%w_]+$') ~= nil) then
        return false;
    end
    if (accessxi.chat_log_has_suspicious_noise(text)) then
        return false;
    end

    local letters = 0;
    local bad = 0;
    for i = 1, #text do
        local b = text:byte(i) or 0;
        if (b < 32 or b > 126) then
            bad = bad + 1;
        elseif ((b >= 65 and b <= 90) or (b >= 97 and b <= 122)) then
            letters = letters + 1;
        end
    end
    if (bad > 0 or letters < 3) then
        return false;
    end

    local lower = text:lower();
    if (lower == 'menu'
        or lower == 'font'
        or lower == 'fulllog'
        or lower == 'inline'
        or lower:find('menu    ', 1, true) ~= nil
        or lower:find('state chatlog ', 1, true) ~= nil
        or lower:find('chatprobe ', 1, true) ~= nil) then
        return false;
    end

    if (text:find('%s') == nil and #text < 5) then
        return false;
    end

    return true;
end

accessxi.chat_log_fixedgrid_cell_text = function (ptr, stride)
    ptr = tonumber(ptr) or 0;
    stride = tonumber(stride) or 0x70;
    if (not accessxi.is_probe_pointer(ptr) or stride <= 0) then
        return '';
    end

    local max_len = math.min(tonumber(accessxi.chat_log_max_line_len) or 150, stride);
    local parts = T{};
    local run = T{};
    local zero_run = 0;

    local function flush_run()
        if (#run >= 2) then
            parts:append(run:concat(''));
        end
        run = T{};
    end

    for off = 0, max_len - 1 do
        local byte_value = read_u8(ptr + off);
        if (byte_value == nil) then
            break;
        end

        if (byte_value == 0) then
            zero_run = zero_run + 1;
            flush_run();
            if (zero_run >= 4 and #parts > 0) then
                break;
            end
        elseif (accessxi.probe_printable_ascii ~= nil and accessxi.probe_printable_ascii(byte_value)) then
            zero_run = 0;
            run:append(string.char(byte_value));
        elseif (byte_value == 0x09 or byte_value == 0x0A or byte_value == 0x0D) then
            zero_run = 0;
            flush_run();
        else
            zero_run = 0;
            flush_run();
        end
    end
    flush_run();

    local text = accessxi.chat_log_clean_native_text(parts:concat(' '));
    text = accessxi.chat_log_speech_text(text);
    if (not accessxi.chat_log_fixedgrid_text_quality_ok(text)) then
        return '';
    end
    return text;
end

accessxi.chat_log_native_line_from_fixedgrid_fulllog = function (obj, state)
    obj = tonumber(obj) or 0;
    if (not accessxi.is_probe_pointer(obj) or state == nil) then
        return nil;
    end
    if (not accessxi.chat_log_cursor_is_in_rendered_row_window(state)
        and not accessxi.chat_log_selected_row_pointer_usable(state)) then
        return nil;
    end

    local selected_index = tonumber(state.selected_index) or -1;
    local row_count = tonumber(state.row_count) or 0;
    if (selected_index < 0 or row_count <= 0 or row_count > 30) then
        return nil;
    end

    local sources = T{};
    local visible = read_u32(obj + 0x88) or 0;
    if (accessxi.is_probe_pointer(visible)) then
        sources:append(T{ label = 'obj+88', ptr = visible, len = 0x1800 });
    end

    local best = nil;
    for _, source in ipairs(sources) do
        local ptr = tonumber(source.ptr) or 0;
        local scan_len = tonumber(source.len) or 0;
        if (accessxi.is_probe_pointer(ptr) and scan_len > 0) then
            for _, stride in ipairs(T{ 0x70 }) do
                if ((selected_index * stride) < scan_len) then
                    for phase = 0, stride - 1 do
                        local last_row_off = phase + ((row_count - 1) * stride);
                        if ((last_row_off + math.min(stride, tonumber(accessxi.chat_log_max_line_len) or 150)) <= scan_len) then
                            local selected_text = accessxi.chat_log_fixedgrid_cell_text(ptr + phase + (selected_index * stride), stride);
                            if (selected_text ~= '') then
                                local quality_count = 0;
                                local filled_count = 0;
                                for row_index = 0, row_count - 1 do
                                    local text = accessxi.chat_log_fixedgrid_cell_text(ptr + phase + (row_index * stride), stride);
                                    if (text ~= '') then
                                        quality_count = quality_count + 1;
                                        filled_count = filled_count + 1;
                                    end
                                end

                                local min_quality = math.min(row_count, 3);
                                if (quality_count >= min_quality) then
                                    local score = (quality_count * 1000) + math.min(#selected_text, 150);
                                    if (best == nil or score > (tonumber(best.score) or 0)) then
                                        best = T{
                                            label = tostring(source.label or ''),
                                            ptr = ptr,
                                            phase = phase,
                                            stride = stride,
                                            selected_text = selected_text,
                                            quality_count = quality_count,
                                            filled_count = filled_count,
                                            score = score,
                                        };
                                    end
                                end
                            end
                        end
                    end
                end
            end
        end
    end

    if (best == nil) then
        return nil;
    end

    local row_address = (tonumber(best.ptr) or 0) + (tonumber(best.phase) or 0) + (selected_index * (tonumber(best.stride) or 0));
    local log_key = ('%08X:%s:%02X:%02X:%d:%d:%s'):fmt(
        obj,
        tostring(best.label or ''),
        tonumber(best.phase) or 0,
        tonumber(best.stride) or 0,
        selected_index,
        row_count,
        tostring(best.selected_text or ''));
    if (log_key ~= (accessxi.chat_log_fulllog_fixedgrid_last_probe or '')) then
        accessxi.chat_log_fulllog_fixedgrid_last_probe = log_key;
        log_state(('state chatlog fulllog-fixedgrid menu="menu    fulllog" obj=0x%08X source="%s" ptr=0x%08X selectedIndex=%d stateRows=%d phase=0x%02X stride=0x%02X qualityRows=%d rowAddress=0x%08X line="%s"'):fmt(
            obj,
            tostring(best.label or ''),
            tonumber(best.ptr) or 0,
            selected_index,
            row_count,
            tonumber(best.phase) or 0,
            tonumber(best.stride) or 0,
            tonumber(best.quality_count) or 0,
            row_address,
            accessxi.escape_probe_log_text(best.selected_text or '')));
    end

    return T{
        text = tostring(best.selected_text or ''),
        source = ('fulllog-fixedgrid-%s+%03X@0x%08X'):fmt(tostring(best.label or ''), tonumber(best.phase) or 0, row_address),
        score = 43500,
        chat_log_menu_nav = true,
        chat_log_row_selected = selected_index,
        chat_log_row_count = row_count,
        chat_log_selection_reason = 'native-fulllog-fixedgrid-row',
        visible_signature = ('%d:%d:0x%08X:%s'):fmt(
            tonumber(state.cursor) or -1,
            tonumber(state.bottom) or -1,
            row_address,
            tostring(best.selected_text or '')),
    };
end

accessxi.chat_log_native_line_from_rendered_fulllog = function (obj, state)
    obj = tonumber(obj) or 0;
    if (not accessxi.is_probe_pointer(obj) or state == nil) then
        return nil;
    end
    if (not accessxi.chat_log_cursor_is_in_rendered_row_window(state)
        and not accessxi.chat_log_selected_row_pointer_usable(state)) then
        return nil;
    end

    local selected_index = tonumber(state.selected_index) or -1;
    local row_count = tonumber(state.row_count) or 0;
    if (selected_index < 0 or row_count <= 0) then
        return nil;
    end

    local sources = T{};
    local visible = read_u32(obj + 0x88) or 0;
    if (accessxi.is_probe_pointer(visible)) then
        sources:append(T{ label = 'obj+88', ptr = visible, len = 0x1800 });
    end

    for _, source in ipairs(sources) do
        local rows = accessxi.chat_log_fulllog_rendered_rows(source.ptr, source.len, math.max(row_count + 8, 64));
        if (rows:len() > selected_index) then
            local row = rows[selected_index + 1];
            if (row ~= nil and tostring(row.text or '') ~= '') then
                local decoded = T{
                    text = tostring(row.text or ''),
                    source = ('fulllog-rendered-%s+%03X@0x%08X'):fmt(tostring(source.label or ''), tonumber(row.offset) or 0, tonumber(row.address) or 0),
                    score = 43000,
                    chat_log_menu_nav = true,
                    chat_log_row_selected = selected_index,
                    chat_log_row_count = row_count,
                    chat_log_selection_reason = 'native-fulllog-rendered-row',
                    visible_signature = ('%d:%d:%08X:%s'):fmt(
                        tonumber(state.cursor) or -1,
                        tonumber(state.bottom) or -1,
                        tonumber(row.address) or 0,
                        tostring(row.text or '')),
                };

                local log_key = ('%08X:%s:%d:%d:%s'):fmt(obj, tostring(source.label or ''), selected_index, rows:len(), tostring(row.text or ''));
                if (log_key ~= (accessxi.chat_log_fulllog_rendered_last_probe or '')) then
                    accessxi.chat_log_fulllog_rendered_last_probe = log_key;
                    log_state(('state chatlog fulllog-rendered menu="menu    fulllog" obj=0x%08X source="%s" ptr=0x%08X selectedIndex=%d stateRows=%d renderedRows=%d rowOffset=0x%03X line="%s"'):fmt(
                        obj,
                        tostring(source.label or ''),
                        tonumber(source.ptr) or 0,
                        selected_index,
                        row_count,
                        rows:len(),
                        tonumber(row.offset) or 0,
                        accessxi.escape_probe_log_text(row.text or '')));
                end
                return decoded;
            end
        end
    end

    return nil;
end

accessxi.chat_log_native_line_from_obj = function (obj, menu_name)
    obj = tonumber(obj) or 0;
    if (not accessxi.is_probe_pointer(obj)) then
        return nil;
    end

    menu_name = tostring(menu_name or '');
    if (is_chat_log_menu_name(menu_name)) then
        local full_log_menu = menu_name:eq('menu    fulllog', true);
        local state = accessxi.chat_log_global_state_from_menu_obj(obj, menu_name);
        local native = nil;
        if (state ~= nil) then
            accessxi.chat_log_selected_row_chain_detail(state);
            local rendered_window_ok = accessxi.chat_log_cursor_is_in_rendered_row_window(state);
            local selected_row_ok = accessxi.chat_log_selected_row_pointer_usable(state);
            if (full_log_menu) then
                native = accessxi.chat_log_native_line_from_cursor_record(state);
                if (native == nil) then
                    accessxi.chat_log_native_line_from_selected_source(state);
                    native = accessxi.chat_log_native_line_from_cursor_record(state);
                end
            else
            if (native == nil) then
                native = accessxi.chat_log_native_line_from_selected_source(state);
            end
            if (native == nil) then
                native = accessxi.chat_log_native_line_from_cursor_record(state);
            end
            if (native == nil) then
                native = accessxi.chat_log_native_line_from_fixedgrid_fulllog(obj, state);
            end
            if (native == nil) then
                native = accessxi.chat_log_native_line_from_rendered_fulllog(obj, state);
            end
            if (native == nil and not full_log_menu) then
                local glyph_row, glyph_detail = nil, '';
                if (selected_row_ok) then
                    glyph_row, glyph_detail = accessxi.chat_log_selected_row_glyph_text(state);
                end
                local glyph_log_key = ('0x%08X:%d:%d:%s'):fmt(
                    tonumber(state.selected_row) or 0,
                    tonumber(state.cursor) or -1,
                    tonumber(state.bottom) or -1,
                    glyph_row ~= nil and tostring(glyph_row.text or '') or '');
                if (selected_row_ok and glyph_log_key ~= (accessxi.chat_log_selected_row_glyph_last_probe or '')) then
                    accessxi.chat_log_selected_row_glyph_last_probe = glyph_log_key;
                    log_state(('state chatlog selected-row-glyph row=0x%08X cursor=%d bottom=%d inWindow=%d decoded=%s text="%s" detail="%s"'):fmt(
                        tonumber(state.selected_row) or 0,
                        tonumber(state.cursor) or -1,
                        tonumber(state.bottom) or -1,
                        rendered_window_ok and 1 or 0,
                        glyph_row ~= nil and 'yes' or 'no',
                        glyph_row ~= nil and accessxi.escape_probe_log_text(glyph_row.text or '') or '',
                        accessxi.escape_probe_log_text(glyph_detail or '')));
                end
                if (glyph_row ~= nil) then
                    native = glyph_row;
                end
            end
            end
            if (native == nil) then
                local row = nil;
                local row_base = 0;
                if (selected_row_ok) then
                    for _, base_delta in ipairs(T{ 0x00, -0x40, -0x80, -0xC0, -0x100 }) do
                        row = accessxi.chat_log_decode_row_record(state.selected_row + base_delta);
                        if (row ~= nil) then
                            row_base = state.selected_row + base_delta;
                            break;
                        end
                    end
                end

                local row_preview = '';
                if (selected_row_ok and accessxi.collect_probe_ascii_runs ~= nil) then
                    row_preview = accessxi.collect_probe_ascii_runs(state.selected_row, 0x180, 5, 8):concat('|');
                end
                local row_dwords = selected_row_ok and accessxi.format_probe_dwords(state.selected_row, 0, 20) or '';
                local row_ptrs = selected_row_ok and accessxi.chat_log_selected_row_pointer_probe(state.selected_row) or '';
                local row_chain = selected_row_ok and accessxi.chat_log_selected_row_chain_probe(state.selected_row) or '';
                local data_dwords = accessxi.is_probe_pointer(state.data) and accessxi.format_probe_dwords(state.data, 0, 64) or '';
                local log_key = ('0x%08X:0x%08X:%d:%d:%d:%08X:%s'):fmt(
                    tonumber(state.global_slot) or 0,
                    tonumber(state.data) or 0,
                    tonumber(state.cursor) or -1,
                    tonumber(state.bottom) or -1,
                    tonumber(state.selected_index) or -1,
                    tonumber(state.selected_row) or 0,
                    row ~= nil and tostring(row.text or '') or '');
                if (log_key ~= (accessxi.chat_log_global_state_last_probe or '')) then
                    accessxi.chat_log_global_state_last_probe = log_key;
                    log_state(('state chatlog strict-global menu="%s" obj=0x%08X desc=0x%08X source="%s" slot=0x%08X data=0x%08X cursor=%d bottom=%d rows=%d windowTop=%d windowBottom=%d inWindow=%d selectedIndexRaw=%d selectedIndex=%d selectedRow=0x%08X decoded=%s rowBase=0x%08X text="%s" rowRuns="%s" rowPtrs="%s" rowChain="%s" data=%s row=%s'):fmt(
                        tostring(menu_name or ''),
                        tonumber(obj) or 0,
                        tonumber(state.desc) or 0,
                        accessxi.escape_probe_log_text(tostring(state.source or '')),
                        tonumber(state.global_slot) or 0,
                        tonumber(state.data) or 0,
                        tonumber(state.cursor) or -1,
                        tonumber(state.bottom) or -1,
                        tonumber(state.row_count) or 0,
                        tonumber(state.row_window_top) or -1,
                        tonumber(state.row_window_bottom) or -1,
                        rendered_window_ok and 1 or 0,
                        tonumber(state.selected_index_unclamped) or -1,
                        tonumber(state.selected_index) or -1,
                        tonumber(state.selected_row) or 0,
                        row ~= nil and 'yes' or 'no',
                        row_base,
                        row ~= nil and accessxi.escape_probe_log_text(row.text or '') or '',
                        accessxi.escape_probe_log_text(row_preview),
                        accessxi.escape_probe_log_text(row_ptrs),
                        accessxi.escape_probe_log_text(row_chain),
                        data_dwords,
                        row_dwords));
                end
            end
        else
            native = accessxi.chat_log_native_line_from_global_state(obj, menu_name);
        end
        if (native ~= nil) then
            return native;
        end
        if (full_log_menu) then
            return nil;
        else
            accessxi.chat_log_fulllog_text_buffer_diagnostic(obj, menu_name, state);

            local desc = read_u32(obj + 0x04) or 0;
            local global_slot = accessxi.is_probe_pointer(desc) and (read_u32(desc + 0x20) or 0) or 0;
            local native_data = accessxi.is_probe_pointer(global_slot) and (read_u32(global_slot) or 0) or 0;
            local native_cursor = accessxi.is_probe_pointer(native_data) and (tonumber(read_i32(native_data + 0x1C)) or -1) or -1;
            local native_bottom = accessxi.is_probe_pointer(native_data) and (tonumber(read_i32(native_data + 0x58)) or -1) or -1;
            local log_key = ('0x%08X:0x%08X:0x%08X:%d:%d'):fmt(obj, global_slot, native_data, native_cursor, native_bottom);
            if (log_key ~= (accessxi.chat_log_fulllog_strict_last_probe or '')) then
                accessxi.chat_log_fulllog_strict_last_probe = log_key;
                log_state(('state chatlog strict-native-only menu="%s" obj=0x%08X desc=0x%08X slot=0x%08X data=0x%08X cursor=%d bottom=%d reason="no-selected-line-reader"'):fmt(
                    menu_name,
                    obj,
                    desc,
                    global_slot,
                    native_data,
                    native_cursor,
                    native_bottom));
            end
            return nil;
        end
    end

    local candidates = T{};
    local function add_candidate(source, ptr, length, mode)
        local text = '';
        if (mode == 'string') then
            text = accessxi.chat_log_string_text_from_ptr(ptr, length or accessxi.chat_log_max_line_len);
        else
            text = accessxi.chat_log_ascii_text_from_ptr(ptr, length or accessxi.chat_log_max_line_len);
        end
        if (accessxi.chat_log_candidate_ok(text, source)) then
            local score = accessxi.chat_log_candidate_score(text);
            if (mode == 'string') then
                score = score + 25;
            end
            if (not accessxi.chat_log_has_time(text) and accessxi.chat_log_trusted_source(source)) then
                score = score + 90;
            end
            if (source:find('%*', 1, false) ~= nil) then
                score = score + 20;
            end
            if (source:find('obj+0C+18', 1, true) ~= nil) then
                score = score + 250;
            elseif (source:find('obj+0C', 1, true) ~= nil) then
                score = score + 90;
            end
            if (source:find('+8C', 1, true) ~= nil or source:find('+08C', 1, true) ~= nil) then
                score = score + 60;
            end
            if (source:find('+0C0', 1, true) ~= nil) then
                score = score + 50;
            end
            if (source:find('obj+08', 1, true) ~= nil) then
                score = score + 45;
            end
            if (source:find('obj+08.rel', 1, true) ~= nil) then
                score = score - 220;
                if (source:find('+00ascii', 1, true) ~= nil or source:find('+00->', 1, true) ~= nil) then
                    score = score + 5;
                end
            end
            if (menu_name:eq('menu    fulllog', true)) then
                if (source:find('obj+88+40', 1, true) ~= nil or source:find('obj+88+46', 1, true) ~= nil) then
                    score = score + 95;
                elseif (source:find('obj+88+80', 1, true) ~= nil
                    or source:find('obj+88+8C', 1, true) ~= nil
                    or source:find('obj+88+90', 1, true) ~= nil
                    or source:find('obj+88+A0', 1, true) ~= nil
                    or source:find('obj+88+C0', 1, true) ~= nil) then
                    score = score + 75;
                elseif (source:find('obj+18desc+80', 1, true) ~= nil
                    or source:find('obj+14desc+80', 1, true) ~= nil) then
                    score = score + 180;
                elseif (source:find('obj+08.chain', 1, true) ~= nil) then
                    score = score - 145;
                end
                if (source:find('obj+88', 1, true) ~= nil
                    and text:find('%[Addons%]%s+Loaded addon:') == nil
                    and text:find('%[Ashita%]%s+Bound:') == nil) then
                    score = score + 35;
                end
            end
            candidates:append(T{ source = source, text = text, score = score });
        end
    end

    local function add_text_candidate(source, text, base_score)
        text = accessxi.chat_log_clean_native_text(text);
        if (accessxi.chat_log_candidate_ok(text, source)) then
            local score = accessxi.chat_log_candidate_score(text) + (tonumber(base_score) or 0);
            candidates:append(T{ source = source, text = text, score = score });
        end
    end

    local function add_pointer_text_candidates(source, ptr, base_score)
        ptr = tonumber(ptr) or 0;
        if (not accessxi.is_probe_pointer(ptr)) then
            return;
        end

        for _, text_off in ipairs(T{ 0x00, 0x20, 0x30, 0x40, 0x46, 0x50, 0x60, 0x80, 0x8C, 0x90, 0xA0, 0xC0 }) do
            local candidate_ptr = ptr + text_off;
            local before = #candidates;
            add_candidate(('%s+%02X->0x%08X'):fmt(source, text_off, candidate_ptr), candidate_ptr, accessxi.chat_log_max_line_len, 'string');
            add_candidate(('%s+%02Xascii->0x%08X'):fmt(source, text_off, candidate_ptr), candidate_ptr, accessxi.chat_log_max_line_len, 'ascii');
            if (base_score ~= nil and #candidates > before) then
                for i = before + 1, #candidates do
                    candidates[i].score = (tonumber(candidates[i].score) or 0) + (tonumber(base_score) or 0);
                end
            end
        end
    end

    local function add_row_text_candidates(source, ptr, base_score)
        ptr = tonumber(ptr) or 0;
        if (not accessxi.is_probe_pointer(ptr)) then
            return;
        end

        for _, text_off in ipairs(T{ 0x00, 0x04, 0x08, 0x0C, 0x10, 0x14, 0x18, 0x20, 0x30, 0x40, 0x46, 0x50, 0x60, 0x70, 0x78, 0x80, 0x8C, 0x90, 0xA0, 0xB0, 0xC0, 0xD0, 0xE0, 0xF0, 0x100, 0x110, 0x120, 0x130, 0x140, 0x150, 0x160, 0x170, 0x180, 0x190, 0x1A0, 0x1B0, 0x1C0, 0x1D0, 0x1E0, 0x1F0, 0x200, 0x210, 0x220, 0x230, 0x240, 0x250, 0x260, 0x270, 0x280, 0x290, 0x2A0, 0x2B0, 0x2C0, 0x2D0, 0x2E0, 0x2F0, 0x300 }) do
            local candidate_ptr = ptr + text_off;
            local before = #candidates;
            add_candidate(('%s+%02Xascii->0x%08X'):fmt(source, text_off, candidate_ptr), candidate_ptr, accessxi.chat_log_max_line_len, 'ascii');
            if (base_score ~= nil and #candidates > before) then
                for i = before + 1, #candidates do
                    candidates[i].score = (tonumber(candidates[i].score) or 0) + (tonumber(base_score) or 0);
                end
            end
        end
    end

    local function add_row_run_fragment_candidates(source, ptr, base_score)
        ptr = tonumber(ptr) or 0;
        if (not accessxi.is_probe_pointer(ptr)) then
            return;
        end

        local run = T{};
        local run_start = 0;
        local scan_len = 0x300;
        for off = 0, scan_len do
            local byte_value = off < scan_len and read_u8(ptr + off) or nil;
            if (byte_value ~= nil and accessxi.probe_printable_ascii ~= nil and accessxi.probe_printable_ascii(byte_value)) then
                if (#run == 0) then
                    run_start = off;
                end
                run:append(string.char(byte_value));
            else
                if (#run >= 8) then
                    local text = run:concat('');
                    add_text_candidate(('%s+%03Xrowrun->0x%08X'):fmt(source, run_start, ptr + run_start), text, (tonumber(base_score) or 0) + 45 - math.floor(run_start / 0x100));
                end
                run = T{};
            end
        end
    end

    local function add_visible_ascii_scan_candidates(source, ptr, base_score)
        ptr = tonumber(ptr) or 0;
        if (not accessxi.is_probe_pointer(ptr)) then
            return 0;
        end

        local scan_len = 0x800;
        local max_hits = 24;
        local hits = 0;
        local seen_text = {};
        local run = T{};
        local run_start = 0;
        local function visible_temp_fragment_ok(text)
            text = tostring(text or '');
            if (#text < 6 or #text > (tonumber(accessxi.chat_log_max_line_len) or 150)) then
                return false;
            end
            if (text:match('^[%p%s]+$') ~= nil or accessxi.chat_log_has_suspicious_noise(text)) then
                return false;
            end

            local letters = 0;
            for i = 1, #text do
                local b = text:byte(i) or 0;
                if ((b >= 65 and b <= 90) or (b >= 97 and b <= 122)) then
                    letters = letters + 1;
                end
            end
            return letters >= 3;
        end
        local function flush_run()
            if (#run < 3 or hits >= max_hits) then
                run = T{};
                return;
            end

            local text = accessxi.chat_log_clean_native_text(run:concat(''));
            text = accessxi.chat_log_temp_strip_row_tail(text);
            local speech = accessxi.chat_log_speech_text(text);
            local key = speech:lower():trim();
            if (key ~= '' and seen_text[key] ~= true) then
                seen_text[key] = true;
                local row_position = hits + 1;
                local row_address = ptr + run_start;
                local full_text = '';
                if (visible_temp_fragment_ok(text)) then
                    full_text = accessxi.chat_log_resolve_temp_row(text);
                end
                if (full_text ~= '') then
                    candidates:append(T{
                        source = ('%s+%03Xtemplog->0x%08X'):fmt(source, run_start, row_address),
                        text = full_text,
                        score = (tonumber(base_score) or 0) + 980 + math.min(#full_text, 120) - math.floor(run_start / 0x100),
                        row_offset = run_start,
                        row_address = row_address,
                        row_position = row_position,
                        row_kind = 'templog',
                        row_signature = ('%03X:%s'):fmt(run_start, accessxi.chat_log_temp_match_key(full_text)),
                        chat_log_temp_resolved = true,
                        chat_log_visible_ascii_scan = true,
                    });
                    hits = hits + 1;
                end
                if (accessxi.chat_log_visible_scan_text_quality_ok(text)) then
                    local before = #candidates;
                    local row_source = ('%s+%03Xscanascii->0x%08X'):fmt(source, run_start, row_address);
                    add_text_candidate(row_source, text, (tonumber(base_score) or 0) + 15 - math.floor(run_start / 0x100));
                    if (#candidates > before) then
                        for i = before + 1, #candidates do
                            local candidate = candidates[i];
                            candidate.row_offset = run_start;
                            candidate.row_address = row_address;
                            candidate.row_position = row_position;
                            candidate.chat_log_visible_ascii_scan = true;
                        end
                        if (full_text == '') then
                            hits = hits + 1;
                        end
                    end
                end
            end
            run = T{};
        end

        for off = 0, scan_len do
            local byte_value = off < scan_len and read_u8(ptr + off) or nil;
            if (byte_value ~= nil and accessxi.probe_printable_ascii ~= nil and accessxi.probe_printable_ascii(byte_value)) then
                if (#run == 0) then
                    run_start = off;
                end
                run:append(string.char(byte_value));
            elseif (byte_value == 0x09 or byte_value == 0x0A or byte_value == 0x0D) then
                if (#run == 0) then
                    run_start = off;
                end
                run:append(' ');
            else
                flush_run();
            end
        end

        return hits;
    end

    local function add_temp_log_fragment_candidates(source, ptr, base_score)
        ptr = tonumber(ptr) or 0;
        if (not accessxi.is_probe_pointer(ptr)) then
            return;
        end

        local seen_text = {};
        local scan_len = 0x600;
        local hits = 0;
        local run = T{};
        local run_start = 0;
        for off = 0, scan_len do
            local byte_value = off < scan_len and read_u8(ptr + off) or nil;
            if (byte_value ~= nil and accessxi.probe_printable_ascii ~= nil and accessxi.probe_printable_ascii(byte_value)) then
                if (#run == 0) then
                    run_start = off;
                end
                run:append(string.char(byte_value));
            else
                if (#run >= 7 and hits < 18) then
                    local fragment = accessxi.chat_log_clean_native_text(run:concat(''));
                    local fragment_key = accessxi.chat_log_temp_match_key(fragment);
                    if (#fragment_key >= 7
                        and fragment_key:find('%a') ~= nil
                        and seen_text[fragment_key] ~= true) then
                        seen_text[fragment_key] = true;
                        local full_text = accessxi.chat_log_resolve_temp_entry(fragment);
                        if (full_text ~= '') then
                            hits = hits + 1;
                            local score = (tonumber(base_score) or 0)
                                + 120
                                + math.min(#full_text, 90)
                                + math.floor(math.min(run_start, 0x380) / 16);
                            candidates:append(T{
                                source = ('%s+%03Xfrag+templog->0x%08X'):fmt(source, run_start, ptr + run_start),
                                text = full_text,
                                score = score,
                                row_offset = run_start,
                                row_address = ptr + run_start,
                                row_position = hits,
                                row_kind = 'templog',
                                row_signature = ('%03X:%s'):fmt(run_start, accessxi.chat_log_temp_match_key(full_text)),
                                chat_log_temp_resolved = true,
                            });
                        elseif (#fragment >= 12
                            and fragment:find('%a') ~= nil
                            and accessxi.chat_log_plain_text_quality_ok(fragment, false)
                            and not accessxi.chat_log_has_suspicious_noise(fragment)) then
                            hits = hits + 1;
                            local score = (tonumber(base_score) or 0)
                                + 520
                                + math.min(#fragment, 100)
                                + math.floor(math.min(run_start, 0x380) / 8);
                            candidates:append(T{
                                source = ('%s+%03Xfrag->0x%08X'):fmt(source, run_start, ptr + run_start),
                                text = fragment,
                                score = score,
                            });
                        end
                    end
                end
                run = T{};
            end
        end
    end

    local function is_digit_byte(value)
        value = tonumber(value) or 0;
        return value >= 0x30 and value <= 0x39;
    end

    local function chat_time_marker_len(ptr)
        ptr = tonumber(ptr) or 0;
        if (not accessxi.is_probe_pointer(ptr) or (read_u8(ptr) or 0) ~= 0x5B) then
            return 0;
        end

        local b1 = read_u8(ptr + 1);
        if (not is_digit_byte(b1)) then
            return 0;
        end

        local b2 = read_u8(ptr + 2);
        if (b2 == 0x3A) then
            if (is_digit_byte(read_u8(ptr + 3)) and is_digit_byte(read_u8(ptr + 4))) then
                if ((read_u8(ptr + 5) or 0) == 0x3A
                    and is_digit_byte(read_u8(ptr + 6))
                    and is_digit_byte(read_u8(ptr + 7))
                    and ((read_u8(ptr + 8) or 0) == 0x5D)) then
                    return 9;
                end
                if ((read_u8(ptr + 5) or 0) == 0x5D) then
                    return 6;
                end
            end
            return 0;
        end

        if (is_digit_byte(b2) and ((read_u8(ptr + 3) or 0) == 0x3A)
            and is_digit_byte(read_u8(ptr + 4)) and is_digit_byte(read_u8(ptr + 5))) then
            if ((read_u8(ptr + 6) or 0) == 0x3A
                and is_digit_byte(read_u8(ptr + 7))
                and is_digit_byte(read_u8(ptr + 8))
                and ((read_u8(ptr + 9) or 0) == 0x5D)) then
                return 10;
            end
            if ((read_u8(ptr + 6) or 0) == 0x5D) then
                return 7;
            end
        end
        return 0;
    end

    local function chat_timestamp_row_text_from_ptr(ptr)
        ptr = tonumber(ptr) or 0;
        local marker_len = chat_time_marker_len(ptr);
        if (marker_len <= 0) then
            return '';
        end

        local bytes = T{};
        local non_printable_run = 0;
        local max_len = math.min(tonumber(accessxi.chat_log_max_line_len) or 150, 112);
        for off = 0, max_len - 1 do
            if (off > 0 and chat_time_marker_len(ptr + off) > 0) then
                break;
            end

            local byte_value = read_u8(ptr + off);
            if (byte_value == nil) then
                break;
            end
            if (byte_value == 0) then
                if (#bytes >= marker_len) then
                    break;
                end
            elseif (accessxi.probe_printable_ascii ~= nil and accessxi.probe_printable_ascii(byte_value)) then
                bytes:append(string.char(byte_value));
                non_printable_run = 0;
            elseif (byte_value == 0x09 or byte_value == 0x0A or byte_value == 0x0D) then
                bytes:append(' ');
                non_printable_run = 0;
            else
                non_printable_run = non_printable_run + 1;
                if (#bytes >= marker_len and non_printable_run >= 3) then
                    break;
                end
                if (#bytes > 0 and non_printable_run == 1) then
                    bytes:append(' ');
                end
            end
        end

        local text = accessxi.chat_log_clean_native_text(bytes:concat(''));
        text = text:gsub("%s+[\"']?%s*|%s*%+%x%x%x=.*$", ''):trim();
        text = text:gsub('%s+[%.%p%s]*|%s*%+%x%x%x%x=.*$', ''):trim();
        text = text:gsub('%s+bytes=%x%x.*$', ''):trim();
        text = text:gsub('(%[Addons%]%s+Loaded addon:%s+accessxi_reader)%s+@[%w%p]+$', '%1'):trim();
        text = text:gsub('(%[Addons%]%s+Loaded addon:%s+accessxi_reader)%s+[%w%p]+$', '%1'):trim();
        text = text:gsub('(%[Addons%]%s+Loaded addon:%s+accessxi_reader)%s+[%x,]+.*$', '%1'):trim();
        return accessxi.chat_log_clean_native_text(text);
    end

    local function chat_timestamp_row_signature_from_ptr(ptr, row_text)
        ptr = tonumber(ptr) or 0;
        if (not accessxi.is_probe_pointer(ptr) or chat_time_marker_len(ptr) <= 0) then
            return '';
        end

        local prelude = T{};
        for rel = -0x18, -1, 4 do
            local byte_value = read_u8(ptr + rel);
            if (byte_value == nil) then
                prelude:append('??');
            else
                prelude:append(('%02X'):fmt(byte_value));
            end
        end

        local time_text = tostring(row_text or ''):match('^(%[%d%d?:%d%d:?%d*%])') or '';
        local speech_text = accessxi.chat_log_speech_text(row_text or '');
        return ('%s:%s:%s'):fmt(prelude:concat(''), time_text, speech_text);
    end

    local function add_row_timestamp_scan_candidates(source, ptr, base_score)
        ptr = tonumber(ptr) or 0;
        if (not accessxi.is_probe_pointer(ptr)) then
            return T{};
        end

        local source_text = tostring(source or '');
        local scan_len = 0x600;
        local max_hits = 12;
        if (accessxi.chat_log_visible_row_source(source_text)) then
            scan_len = 0x800;
            max_hits = 24;
        end
        if (source_text:find('fulllog+obj', 1, true) ~= nil) then
            scan_len = 0x6000;
            max_hits = 180;
        end
        if (source_text:find('chatnode+fulllogptr+', 1, true) ~= nil) then
            scan_len = 0x1800;
            max_hits = 12;
        end
        local accepted_rows = T{};
        local probe_rows = T{};
        local hits = 0;
        local off = 0;
        while (off < scan_len and hits < max_hits) do
            local marker_len = chat_time_marker_len(ptr + off);
            if (marker_len > 0) then
                local candidate_ptr = ptr + off;
                local before = #candidates;
                local row_source = ('%s+%03Xscanrow->0x%08X'):fmt(source, off, candidate_ptr);
                local row_text = chat_timestamp_row_text_from_ptr(candidate_ptr);
                add_text_candidate(row_source, row_text, 0);
                if (base_score ~= nil and #candidates > before) then
                    for i = before + 1, #candidates do
                        candidates[i].score = (tonumber(candidates[i].score) or 0) + (tonumber(base_score) or 0) + 10 - math.floor(off / 0x80);
                    end
                end
                if (#candidates > before) then
                    for i = before + 1, #candidates do
                        local candidate = candidates[i];
                        candidate.row_offset = off;
                        candidate.row_address = candidate_ptr;
                        candidate.row_position = accepted_rows:len() + 1;
                        candidate.row_signature = chat_timestamp_row_signature_from_ptr(candidate_ptr, row_text);
                        candidate.chat_log_timestamp_scan = true;
                        accepted_rows:append(candidate);
                    end
                end
                if (source_text:find('chatnode+fulllogptr+', 1, true) ~= nil and probe_rows:len() < 8) then
                    probe_rows:append(('+%03X:%s:%s'):fmt(
                        off,
                        (#candidates > before) and 'ok' or 'reject',
                        accessxi.escape_probe_log_text(row_text)));
                end
                hits = hits + 1;
                off = off + marker_len;
            else
                off = off + 1;
            end
        end
        if ((accessxi.chat_log_debug == true or tick() <= (accessxi.chat_log_probe_until or 0))
            and source_text:find('chatnode+fulllogptr+', 1, true) ~= nil) then
            local summary = probe_rows:len() > 0 and probe_rows:concat(' | ') or 'none';
            local log_key = ('%s:0x%08X:%s'):fmt(source_text, ptr, summary);
            if (log_key ~= (accessxi.chat_log_fulllogptr_scan_last_probe or '')) then
                accessxi.chat_log_fulllogptr_scan_last_probe = log_key;
                log_state(('state chatlog fulllogptr-scan source="%s" ptr=0x%08X hits=%d rows="%s"'):fmt(
                    source_text,
                    ptr,
                    hits,
                    summary));
            end
        end
        return accepted_rows;
    end

    if (is_chat_log_menu_name(menu_name)) then
        local seen_rows = T{};
        local native_child_best = nil;
        local native_child_rows = T{};
        local native_object_best = nil;
        local native_object_rows = T{};
        local native_object_timeline_rows = T{};

        local function count_for_ptr(ptr)
            ptr = tonumber(ptr) or 0;
            if (not accessxi.is_probe_pointer(ptr)) then
                return 0;
            end
            local count = math.max(
                tonumber(read_i32(ptr + 0x24)) or 0,
                tonumber(read_i32(ptr + 0x28)) or 0);
            if (count < 0 or count > 256) then
                return 0;
            end
            return count;
        end

        local function best_new_candidate(before)
            local best_candidate = nil;
            for i = before + 1, #candidates do
                local candidate = candidates[i];
                if (candidate ~= nil and candidate.text ~= nil and tostring(candidate.text) ~= '') then
                    if (best_candidate == nil or (tonumber(candidate.score) or 0) > (tonumber(best_candidate.score) or 0)) then
                        best_candidate = candidate;
                    end
                end
            end
            return best_candidate;
        end

        local function add_native_child_row_candidate(source, ptr, base_score)
            ptr = tonumber(ptr) or 0;
            if (not accessxi.is_probe_pointer(ptr)) then
                return nil;
            end

            local before = #candidates;
            add_candidate(source, ptr, accessxi.chat_log_max_line_len, 'string');
            add_candidate(source .. 'ascii', ptr, accessxi.chat_log_max_line_len, 'ascii');
            add_row_timestamp_scan_candidates(source .. '+scan', ptr, (tonumber(base_score) or 0) + 40);
            if (accessxi.collect_probe_ffxi_utf16_entries ~= nil) then
                local entries = accessxi.collect_probe_ffxi_utf16_entries(ptr, 0x180, 2, 16);
                local parts = T{};
                for _, entry in ipairs(entries) do
                    local text = accessxi.chat_log_clean_native_text(entry.text or '');
                    if (text ~= '') then
                        parts:append(text);
                    end
                end
                if (parts:len() > 0) then
                    add_text_candidate(source .. '+ffxi16', parts:concat(' '), (tonumber(base_score) or 0) + 30);
                end
            end

            local best_candidate = best_new_candidate(before);
            if (best_candidate ~= nil) then
                best_candidate.score = (tonumber(best_candidate.score) or 0) + (tonumber(base_score) or 0);
            end
            return best_candidate;
        end

        local function add_native_child_rows()
            local child = read_u32(obj + 0x0C) or 0;
            if (not accessxi.is_probe_pointer(child)) then
                return;
            end

            local selected = tonumber(read_i32(obj + 0x4C)) or 1;
            if (selected <= 0) then
                selected = tonumber(read_i32(child + 0x4C)) or 1;
            end
            if (selected <= 0) then
                selected = 1;
            end

            local count = math.max(count_for_ptr(obj), count_for_ptr(child));
            if (count <= 0 or count > 64) then
                count = 12;
            end

            local first = read_u32(child + 0x14) or 0;
            if (not accessxi.is_probe_pointer(first)) then
                return;
            end

            for _, next_off in ipairs(T{ 0x00, 0x84, 0x88, 0x100, 0x108, 0x10, 0x14, 0x18, 0x1C, 0x20 }) do
                local node = first;
                local seen = {};
                local rows = T{};
                for position = 1, math.min(count, 24) do
                    if (not accessxi.is_probe_pointer(node) or seen[node] == true) then
                        break;
                    end
                    seen[node] = true;

                    local row_best = nil;
                    for _, ptr_off in ipairs(T{ 0x10, 0x38, 0x88, 0x100, 0x00, 0x04, 0x08, 0x0C, 0x14, 0x18, 0x20, 0x28, 0x2C }) do
                        local ptr = read_u32(node + ptr_off) or 0;
                        if (accessxi.is_probe_pointer(ptr)) then
                            local candidate = add_native_child_row_candidate(
                                ('chatnode+%03X[%02d]+%03X->0x%08X'):fmt(next_off, position, ptr_off, ptr),
                                ptr,
                                780 - math.min(position, 24));
                            if (candidate ~= nil and (row_best == nil or (tonumber(candidate.score) or 0) > (tonumber(row_best.score) or 0))) then
                                row_best = candidate;
                            end
                        end
                    end

                    if (row_best ~= nil) then
                        row_best.chat_log_menu_nav = true;
                        row_best.chat_log_native_child = true;
                        row_best.row_position = position;
                        row_best.row_offset = position;
                        rows:append(row_best);
                    end

                    local next_node = read_u32(node + next_off) or 0;
                    if (not accessxi.is_probe_pointer(next_node)) then
                        break;
                    end
                    node = next_node;
                end

                if (rows:len() > 0) then
                    local chosen = rows[selected] or rows[1];
                    if (chosen ~= nil and (native_child_best == nil or rows:len() > native_child_rows:len())) then
                        native_child_best = chosen;
                        native_child_rows = rows;
                    end
                end
            end

            if (native_child_best ~= nil) then
                local signature_parts = T{};
                for i = 1, math.min(native_child_rows:len(), 8) do
                    local row = native_child_rows[i];
                    signature_parts:append(('%02d:%s'):fmt(
                        tonumber(row.row_position) or i,
                        accessxi.escape_probe_log_text(accessxi.chat_log_speech_text(row.text or ''))));
                end
                native_child_best.visible_signature = signature_parts:concat(' | ');
                if (accessxi.chat_log_debug == true) then
                    local log_key = ('%s:0x%08X:%s'):fmt(menu_name, obj, tostring(native_child_best.visible_signature or ''));
                    if (log_key ~= (accessxi.chat_log_native_child_last_probe or '')) then
                        accessxi.chat_log_native_child_last_probe = log_key;
                        log_state(('state chatlog nativechild menu="%s" obj=0x%08X rows=%d selected=%d source="%s" line="%s" signature="%s"'):fmt(
                            menu_name,
                            obj,
                            native_child_rows:len(),
                            selected,
                            tostring(native_child_best.source or ''),
                            accessxi.escape_probe_log_text(native_child_best.text or ''),
                            accessxi.escape_probe_log_text(native_child_best.visible_signature or '')));
                    end
                end
            end
        end

        if (menu_name:find('menu    logwin2', 1, true) == 1) then
            add_native_child_rows();
            if (native_child_best ~= nil) then
                return native_child_best;
            end
        end

        local function add_native_object_rows()
            local selected = tonumber(read_i32(obj + 0x4C)) or 1;
            if (selected <= 0) then
                selected = 1;
            end

            local seen_ptrs = {};
            for off = 0x140, 0x220, 4 do
                local ptr = read_u32(obj + off) or 0;
                if (accessxi.is_probe_pointer(ptr) and seen_ptrs[ptr] ~= true) then
                    seen_ptrs[ptr] = true;
                    local length = tonumber(read_i32(obj + off + 0x04)) or 0;
                    if (length < 8 or length > (tonumber(accessxi.chat_log_max_line_len) or 150)) then
                        length = accessxi.chat_log_max_line_len;
                    end

                    local before = #candidates;
                    local source = ('chatnode+fulllogptr+%03X->0x%08X'):fmt(off, ptr);
                    add_candidate(source, ptr, length, 'string');
                    add_candidate(source .. '+ascii', ptr, length, 'ascii');
                    local scan_rows = add_row_timestamp_scan_candidates(source .. '+scan', ptr, 860 - math.floor((off - 0x140) / 4));
                    if (scan_rows ~= nil and scan_rows:len() > 0 and (off == 0x1B4 or scan_rows:len() >= 3)) then
                        for _, scan_row in ipairs(scan_rows) do
                            scan_row.chat_log_menu_nav = true;
                            scan_row.chat_log_native_object = true;
                            scan_row.chat_log_timeline = true;
                            scan_row.ptr_offset = off;
                            scan_row.row_position = native_object_timeline_rows:len() + 1;
                            scan_row.row_offset = tonumber(scan_row.row_offset) or off;
                            native_object_timeline_rows:append(scan_row);
                        end
                    end
                    if (accessxi.collect_probe_ffxi_utf16_entries ~= nil) then
                        local entries = accessxi.collect_probe_ffxi_utf16_entries(ptr, math.min(math.max(length + 0x20, 0x60), 0x180), 2, 12);
                        local parts = T{};
                        for _, entry in ipairs(entries) do
                            local text = accessxi.chat_log_clean_native_text(entry.text or '');
                            if (text ~= '') then
                                parts:append(text);
                            end
                        end
                        if (parts:len() > 0) then
                            add_text_candidate(source .. '+ffxi16', parts:concat(' '), 830 - math.floor((off - 0x140) / 4));
                        end
                    end

                    local row_best = best_new_candidate(before);
                    if (row_best ~= nil) then
                        row_best.chat_log_menu_nav = true;
                        row_best.chat_log_native_object = true;
                        row_best.row_position = native_object_rows:len() + 1;
                        row_best.row_offset = off;
                        native_object_rows:append(row_best);
                    end
                end
            end

            local rows_for_selection = native_object_timeline_rows:len() > 0 and native_object_timeline_rows or native_object_rows;
            if (rows_for_selection:len() > 0) then
                native_object_best = rows_for_selection[selected] or rows_for_selection[1];
                if (native_object_best ~= nil) then
                    local signature_parts = T{};
                    for i = 1, math.min(rows_for_selection:len(), 8) do
                        local row = rows_for_selection[i];
                        signature_parts:append(('%03X/%03X:%s'):fmt(
                            tonumber(row.ptr_offset) or 0,
                            tonumber(row.row_offset) or 0,
                            accessxi.escape_probe_log_text(accessxi.chat_log_speech_text(row.text or ''))));
                    end
                    native_object_best.visible_signature = signature_parts:concat(' | ');
                    if (accessxi.chat_log_debug == true) then
                        local log_key = ('%s:0x%08X:%s'):fmt(menu_name, obj, tostring(native_object_best.visible_signature or ''));
                        if (log_key ~= (accessxi.chat_log_native_object_last_probe or '')) then
                            accessxi.chat_log_native_object_last_probe = log_key;
                            log_state(('state chatlog nativeobject menu="%s" obj=0x%08X rows=%d selected=%d source="%s" line="%s" signature="%s"'):fmt(
                                menu_name,
                                obj,
                                rows_for_selection:len(),
                                selected,
                                tostring(native_object_best.source or ''),
                                accessxi.escape_probe_log_text(native_object_best.text or ''),
                                accessxi.escape_probe_log_text(native_object_best.visible_signature or '')));
                        end
                    end
                end
            end
        end

        local allow_native_object_fallback = (accessxi.chat_log_slow_object_scan_enabled == true);
        if (allow_native_object_fallback == true and not menu_name:eq('menu    logwindo', true)) then
            add_native_object_rows();
        end

        local slow_visible_scan = (accessxi.chat_log_slow_object_scan_enabled == true);
        if (menu_name:eq('menu    fulllog', true)) then
            add_row_timestamp_scan_candidates('fulllog+obj', obj, 1180);
        end
        local visible_offsets = slow_visible_scan
            and T{ 0x88, 0x8C, 0x90, 0x94, 0x98, 0x9C, 0xA0 }
            or T{ 0x88, 0x8C, 0x90 };
        for _, off in ipairs(visible_offsets) do
            local ptr = read_u32(obj + off) or 0;
            if (accessxi.is_probe_pointer(ptr) and seen_rows[ptr] ~= true) then
                seen_rows[ptr] = true;
                local score = 0;
                if (off == 0x88) then
                    score = 35;
                elseif (off == 0x8C or off == 0x90) then
                    score = 15;
                end
                if (slow_visible_scan == true) then
                    add_row_text_candidates(('obj+%02X'):fmt(off), ptr, score);
                    if (off == 0x88) then
                        add_row_run_fragment_candidates(('obj+%02X'):fmt(off), ptr, score);
                    end
                end
                if (off == 0x88 or off == 0x8C or off == 0x90) then
                    add_row_timestamp_scan_candidates(('obj+%02X'):fmt(off), ptr, score);
                end
                if (off == 0x88) then
                    add_visible_ascii_scan_candidates(('obj+%02X'):fmt(off), ptr, score);
                end
            end
        end

        local visible_best = nil;
        local visible_scan_best = nil;
        for _, candidate in ipairs(candidates) do
            if (accessxi.chat_log_visible_row_source(candidate.source)) then
                if (accessxi.chat_log_scan_source(candidate.source)) then
                    if (visible_scan_best == nil or (candidate.score or 0) > (visible_scan_best.score or 0)) then
                        visible_scan_best = candidate;
                    end
                else
                    if (visible_best == nil or (candidate.score or 0) > (visible_best.score or 0)) then
                        visible_best = candidate;
                    end
                end
            end
        end
        if (visible_best == nil) then
            visible_best = visible_scan_best;
        end
        table.sort(candidates, function (a, b)
            return (tonumber(a.score) or 0) > (tonumber(b.score) or 0);
        end);
        do
            local visible_candidates = T{};
            local menu_rows = T{};
            local seen_menu_row = {};
            visible_best = nil;
            for _, candidate in ipairs(candidates) do
                if (accessxi.chat_log_visible_row_source(candidate.source)) then
                    visible_candidates:append(candidate);
                    local source_text = tostring(candidate.source or '');
                    local row_offset = source_text:match('%+([0-9A-F][0-9A-F][0-9A-F])templog')
                        or source_text:match('%+([0-9A-F][0-9A-F][0-9A-F])scanrow')
                        or source_text:match('%+([0-9A-F][0-9A-F][0-9A-F])scanascii')
                        or source_text:match('%+([0-9A-F][0-9A-F][0-9A-F])rowrun');
                    if (row_offset ~= nil) then
                        local row_kind = 'rowrun';
                        if (source_text:find('templog', 1, true) ~= nil) then
                            row_kind = 'templog';
                        elseif (source_text:find('scanrow', 1, true) ~= nil) then
                            row_kind = 'timestamp';
                        elseif (source_text:find('scanascii', 1, true) ~= nil) then
                            row_kind = 'ascii';
                        end
                        local row_address = tonumber(candidate.row_address) or 0;
                        local row_key = row_address > 0
                            and ('%08X:%s'):fmt(row_address, row_kind)
                            or ('%s:%s'):fmt(row_offset, row_kind);
                        if (seen_menu_row[row_key] ~= true) then
                            local text = accessxi.chat_log_speech_text(candidate.text or '');
                            if (text ~= '') then
                                seen_menu_row[row_key] = true;
                                local score_bonus = 900;
                                if (row_kind == 'templog') then
                                    score_bonus = 1100;
                                elseif (row_kind == 'ascii') then
                                    score_bonus = 650;
                                elseif (row_kind == 'rowrun') then
                                    score_bonus = 580;
                                end
                                menu_rows:append(T{
                                    source = tostring(candidate.source or '') .. '+menunav',
                                    text = text,
                                    score = (tonumber(candidate.score) or 0) + score_bonus,
                                    row_offset = tonumber(row_offset, 16) or 0,
                                    row_address = row_address,
                                    row_kind = row_kind,
                                    row_signature = tostring(candidate.row_signature or ''),
                                });
                            end
                        end
                    end
                end
            end
            local temp_rows = T{};
            local timestamp_rows = T{};
            local fulllog_object_rows = T{};
            local ascii_rows = T{};
            for _, row in ipairs(menu_rows) do
                local row_kind = tostring(row.row_kind or '');
                if (row_kind == 'templog') then
                    temp_rows:append(row);
                elseif (row_kind == 'timestamp') then
                    timestamp_rows:append(row);
                    if (tostring(row.source or ''):find('fulllog+obj', 1, true) ~= nil) then
                        fulllog_object_rows:append(row);
                    end
                elseif (row_kind == 'ascii') then
                    ascii_rows:append(row);
                end
            end
            local full_log_rows = menu_name:eq('menu    fulllog', true);
            if (full_log_rows and #fulllog_object_rows > 0) then
                menu_rows = fulllog_object_rows;
            elseif (#temp_rows > 0) then
                menu_rows = temp_rows;
            elseif (#ascii_rows > 0) then
                if (full_log_rows) then
                    local strong_ascii_rows = T{};
                    for _, row in ipairs(ascii_rows) do
                        local text = tostring(row.text or ''):trim();
                        local score = tonumber(row.score) or 0;
                        if (score >= 850
                            and text:find('%s') ~= nil
                            and text:match('^[a-z]') == nil) then
                            strong_ascii_rows:append(row);
                        end
                    end
                    menu_rows = strong_ascii_rows;
                else
                    menu_rows = ascii_rows;
                end
            elseif (#timestamp_rows > 0) then
                menu_rows = timestamp_rows;
            else
                menu_rows = T{};
            end
            table.sort(menu_rows, function (a, b)
                local function row_sort_kind(row)
                    local kind = tostring(row.row_kind or '');
                    if (kind == 'templog') then
                        return 0;
                    elseif (kind == 'timestamp') then
                        return 1;
                    end
                    return 2;
                end
                local a_kind = row_sort_kind(a);
                local b_kind = row_sort_kind(b);
                if (a_kind ~= b_kind) then
                    return a_kind < b_kind;
                end
                local a_addr = tonumber(a.row_address) or 0;
                local b_addr = tonumber(b.row_address) or 0;
                if (a_addr > 0 and b_addr > 0 and a_addr ~= b_addr) then
                    return a_addr < b_addr;
                end
                return (tonumber(a.row_offset) or 0) < (tonumber(b.row_offset) or 0);
            end);

            if (#menu_rows > 0) then
                local full_log_menu = menu_name:eq('menu    fulllog', true);
                local selected = tonumber(read_i32(obj + 0x4C)) or 1;
                local ank_num = -1;
                local target = AshitaCore:GetMemoryManager():GetTarget();
                if (target ~= nil) then
                    ank_num = tonumber(safe_call(function () return target:GetWindowAnkNum(); end, -1)) or -1;
                end
                local count = math.max(
                    tonumber(read_i32(obj + 0x24)) or 0,
                    tonumber(read_i32(obj + 0x28)) or 0);
                if ((not full_log_menu) and count > 0 and count <= #menu_rows and #menu_rows > count) then
                    local limited_rows = T{};
                    for i = 1, count do
                        limited_rows:append(menu_rows[i]);
                    end
                    menu_rows = limited_rows;
                end
                local full_log_selection_reason = '';
                local full_log_ank_selected = -1;
                if (full_log_menu) then
                    local native_cursor = tonumber(read_i32(obj + 0x1C)) or -1;
                    local native_bottom = tonumber(read_i32(obj + 0x58)) or -1;
                    local current_rows = T{};
                    for i = 1, #menu_rows do
                        local speech_text = accessxi.chat_log_speech_text(menu_rows[i].text or '');
                        local row_signature = tostring(menu_rows[i].row_signature or '');
                        if (row_signature == '') then
                            row_signature = ('%03X:%02d:%s'):fmt(
                                tonumber(menu_rows[i].row_offset) or 0,
                                i,
                                speech_text);
                        end
                        current_rows:append(T{
                            text = speech_text,
                            key = row_signature,
                        });
                    end

                    local previous_rows = accessxi.chat_log_full_visible_rows or T{};
                    local previous_counts = {};
                    for _, row in ipairs(previous_rows) do
                        local key = tostring(row.key or '');
                        if (key ~= '') then
                            previous_counts[key] = (previous_counts[key] or 0) + 1;
                        end
                    end

                    local current_signature_parts = T{};
                    for _, row in ipairs(current_rows) do
                        current_signature_parts:append(tostring(row.key or ''));
                    end
                    local current_signature_key = current_signature_parts:concat('|');
                    local previous_signature_key = tostring(accessxi.chat_log_full_visible_signature_key or '');
                    local visible_changed = current_signature_key ~= '' and current_signature_key ~= previous_signature_key;
                    local position_parts = T{};
                    for _, pos_off in ipairs(T{ 0x10, 0x1C, 0x58, 0x64, 0x108, 0x10C, 0x110, 0x11C }) do
                        local pos_value = read_i32(obj + pos_off);
                        if (pos_value ~= nil and pos_value >= -32768 and pos_value <= 32768) then
                            position_parts:append(('%03X=%d'):fmt(pos_off, pos_value));
                        end
                    end
                    local full_log_position_key = position_parts:concat('|');
                    local previous_position_key = tostring(accessxi.chat_log_full_position_key or '');
                    local position_changed = full_log_position_key ~= ''
                        and previous_position_key ~= ''
                        and full_log_position_key ~= previous_position_key;
                    local inferred = 0;
                    local cursor_selected = -1;
                    if (ank_num > 0 and #current_rows > 0) then
                        -- The full chat log exposes an ank-like cursor, but in
                        -- practice it can stay fixed while the rendered log
                        -- buffer scrolls. Prefer it while the visible buffer
                        -- itself is stable.
                        cursor_selected = math.floor(ank_num / 2) + 1;
                        if (cursor_selected >= 1 and cursor_selected <= #current_rows) then
                            full_log_ank_selected = cursor_selected;
                        end
                    end
                    if (inferred <= 0 and #previous_rows > 0 and #current_rows > 1) then
                        if (tostring(current_rows[2].key or '') ~= ''
                            and tostring(current_rows[2].key or '') == tostring(previous_rows[1].key or '')) then
                            inferred = 1;
                            full_log_selection_reason = 'scroll-up';
                        elseif (tostring(previous_rows[2] ~= nil and previous_rows[2].key or '') ~= ''
                            and tostring(current_rows[1].key or '') == tostring(previous_rows[2].key or '')) then
                            inferred = #current_rows;
                            full_log_selection_reason = 'scroll-down';
                        end
                    end
                    if (inferred <= 0 and (not visible_changed) and full_log_ank_selected >= 1 and full_log_ank_selected <= #current_rows) then
                        inferred = full_log_ank_selected;
                        full_log_selection_reason = 'cursor';
                    end
                    if (inferred <= 0 and (not visible_changed) and native_cursor >= 0 and native_bottom >= 0 and #current_rows > 0) then
                        inferred = #current_rows - ((native_bottom - native_cursor) % #current_rows);
                        if (inferred < 1 or inferred > #current_rows) then
                            inferred = #current_rows;
                        end
                        full_log_selection_reason = 'native-cursor';
                    end
                    if (inferred <= 0) then
                        local current_counts = {};
                        for i, row in ipairs(current_rows) do
                            local key = tostring(row.key or '');
                            if (key ~= '') then
                                current_counts[key] = (current_counts[key] or 0) + 1;
                            end
                            if (key ~= '' and (current_counts[key] or 0) > (previous_counts[key] or 0)) then
                                inferred = i;
                                full_log_selection_reason = 'new-row';
                                break;
                            end
                        end
                    end
                    if (inferred <= 0 and full_log_ank_selected >= 1 and full_log_ank_selected <= #current_rows) then
                        inferred = full_log_ank_selected;
                        full_log_selection_reason = 'cursor';
                    end
                    if (inferred <= 0 and position_changed and #current_rows > 0) then
                        inferred = tonumber(accessxi.chat_log_full_selected_index) or 1;
                        if (inferred < 1 or inferred > #current_rows) then
                            inferred = 1;
                        end
                        full_log_selection_reason = 'position';
                    end
                    if (inferred <= 0 and #previous_rows <= 0 and #current_rows > 0) then
                        inferred = 1;
                        full_log_selection_reason = 'initial';
                    end
                    if (inferred <= 0) then
                        inferred = 1;
                        full_log_selection_reason = 'same';
                    end

                    selected = inferred;
                    count = #menu_rows;
                    local selected_key = '';
                    if (current_rows[selected] ~= nil) then
                        selected_key = tostring(current_rows[selected].key or '');
                    end
                    if (full_log_selection_reason == 'same'
                        and selected_key ~= ''
                        and selected_key ~= tostring(accessxi.chat_log_full_selected_key or '')) then
                        full_log_selection_reason = 'cursor';
                    end
                    if (full_log_selection_reason == 'same' and position_changed) then
                        full_log_selection_reason = 'position';
                    end
                    accessxi.chat_log_full_visible_rows = current_rows;
                    accessxi.chat_log_full_visible_signature_key = current_signature_key;
                    accessxi.chat_log_full_selected_key = selected_key;
                    accessxi.chat_log_full_selected_index = selected;
                    accessxi.chat_log_full_position_key = full_log_position_key;
                elseif (ank_num >= 0 and count > 1 and count <= #menu_rows) then
                    selected = (ank_num % count) + 1;
                end
                if (selected < 1 or selected > #menu_rows) then
                    selected = 1;
                end
                visible_best = menu_rows[selected];
                if (full_log_menu) then
                    accessxi.chat_log_full_last_spoken_text = accessxi.chat_log_speech_text(visible_best.text or '');
                end

                local signature_parts = T{};
                for i = 1, math.min(#menu_rows, 8) do
                    local row = menu_rows[i];
                    local signature_id = tostring(row.row_signature or '');
                    if (#signature_id > 24) then
                        signature_id = signature_id:sub(1, 30);
                    end
                    signature_parts:append(('%03X:%s'):fmt(
                        tonumber(row.row_offset) or 0,
                        accessxi.escape_probe_log_text((row.text or '') .. (signature_id ~= '' and (' #' .. signature_id) or ''))));
                end
                visible_best.visible_signature = signature_parts:concat(' | ');
                visible_best.chat_log_menu_nav = true;
                visible_best.chat_log_ank_num = ank_num;
                visible_best.chat_log_row_selected = selected;
                visible_best.chat_log_row_count = #menu_rows;
                visible_best.chat_log_selection_reason = full_log_selection_reason;
                visible_best.chat_log_ank_selected = full_log_ank_selected;
                visible_best.chat_log_position_key = accessxi.chat_log_full_position_key or '';
                visible_best.chat_log_should_speak = true;
                visible_best.chat_log_queue_immediate = false;
                if (full_log_menu) then
                    local source_text = tostring(visible_best.source or '');
                    local temp_source = source_text:find('templog', 1, true) ~= nil;
                    local ascii_source = source_text:find('scanascii', 1, true) ~= nil and not temp_source;
                    local high_quality_new_row =
                        full_log_selection_reason == 'new-row'
                        and (tonumber(visible_best.score) or 0) >= 1000
                        and not ascii_source
                        and tick() > (accessxi.chat_log_settle_until or 0);
                    visible_best.chat_log_should_speak =
                        (not ascii_source)
                        and (full_log_selection_reason == 'cursor'
                             or full_log_selection_reason == 'position'
                             or full_log_selection_reason == 'scroll-up'
                             or full_log_selection_reason == 'scroll-down'
                             or high_quality_new_row);
                    visible_best.chat_log_queue_immediate = visible_best.chat_log_should_speak;
                end
                if (accessxi.chat_log_debug == true) then
                    local fields = '';
                    if (accessxi.chat_log_probe_small_fields ~= nil) then
                        fields = accessxi.chat_log_probe_small_fields(obj);
                    end
                    local dwords000 = '';
                    local dwords040 = '';
                    local dwords080 = '';
                    local dwords0C0 = '';
                    if (accessxi.format_probe_dwords ~= nil) then
                        dwords000 = accessxi.format_probe_dwords(obj, 0x00, 16);
                        dwords040 = accessxi.format_probe_dwords(obj, 0x40, 16);
                        dwords080 = accessxi.format_probe_dwords(obj, 0x80, 16);
                        dwords0C0 = accessxi.format_probe_dwords(obj, 0xC0, 16);
                    end
                    local log_key = ('%s:0x%08X:%s:%s'):fmt(
                        menu_name,
                        obj,
                        tostring(visible_best.visible_signature or ''),
                        fields);
                    if (log_key ~= (accessxi.chat_log_menu_nav_last_probe or '')) then
                        accessxi.chat_log_menu_nav_last_probe = log_key;
                        log_state(('state chatlog menunav menu="%s" obj=0x%08X selected=%d ank=%d ankSelected=%d reason="%s" count=%d rows=%d source="%s" line="%s" signature="%s" fields="%s" dwords000=%s dwords040=%s dwords080=%s dwords0C0=%s'):fmt(
                            menu_name,
                            obj,
                            selected,
                            ank_num,
                            full_log_ank_selected,
                            accessxi.escape_probe_log_text(full_log_selection_reason),
                            count,
                            #menu_rows,
                            tostring(visible_best.source or ''),
                            accessxi.escape_probe_log_text(visible_best.text or ''),
                            accessxi.escape_probe_log_text(visible_best.visible_signature or ''),
                            accessxi.escape_probe_log_text(fields),
                            dwords000,
                            dwords040,
                            dwords080,
                            dwords0C0));
                    end
                end
            end
        end
        if (accessxi.chat_log_debug == true and #candidates > 0) then
            local parts = T{};
            for i = 1, math.min(#candidates, 8) do
                local candidate = candidates[i];
                parts:append(('%d:%s:%d:"%s"'):fmt(
                    i,
                    tostring(candidate.source or ''),
                    tonumber(candidate.score) or 0,
                    accessxi.escape_probe_log_text(candidate.text or '')));
            end
            local summary = parts:concat(' | ');
            local now = tick();
            local log_key = ('%s:0x%08X:%s'):fmt(menu_name, obj, summary);
            if (log_key ~= (accessxi.chat_log_row_scan_last_log or '')
                and ((now - (accessxi.chat_log_row_scan_last_tick or 0)) >= 250 or visible_best == nil)) then
                accessxi.chat_log_row_scan_last_log = log_key;
                accessxi.chat_log_row_scan_last_tick = now;
                log_state(('state chatlog rowscan menu="%s" obj=0x%08X best="%s" %s'):fmt(
                    menu_name,
                    obj,
                    visible_best ~= nil and tostring(visible_best.source or '') or '',
                    summary));
            end
        elseif (accessxi.chat_log_debug == true) then
            local now = tick();
            local log_key = ('%s:0x%08X:none'):fmt(menu_name, obj);
            if (log_key ~= (accessxi.chat_log_row_scan_last_log or '')
                and ((now - (accessxi.chat_log_row_scan_last_tick or 0)) >= 250)) then
                accessxi.chat_log_row_scan_last_log = log_key;
                accessxi.chat_log_row_scan_last_tick = now;
                local ptr88 = read_u32(obj + 0x88) or 0;
                local ptr8C = read_u32(obj + 0x8C) or 0;
                local ptr90 = read_u32(obj + 0x90) or 0;
                local raw88 = '';
                if (accessxi.collect_probe_ascii_runs ~= nil and accessxi.is_probe_pointer(ptr88)) then
                    raw88 = accessxi.collect_probe_ascii_runs(ptr88, 0x600, 3, 18):concat(' ');
                end
                log_state(('state chatlog rowscan-missing menu="%s" obj=0x%08X ptr88=0x%08X ptr8C=0x%08X ptr90=0x%08X ptr94=0x%08X ptr98=0x%08X ptr9C=0x%08X ptrA0=0x%08X raw88="%s"'):fmt(
                    menu_name,
                    obj,
                    ptr88,
                    ptr8C,
                    ptr90,
                    read_u32(obj + 0x94) or 0,
                    read_u32(obj + 0x98) or 0,
                    read_u32(obj + 0x9C) or 0,
                    read_u32(obj + 0xA0) or 0,
                    accessxi.escape_probe_log_text(raw88)));
            end
        end
        if (visible_best ~= nil) then
            return visible_best;
        end
        if (allow_native_object_fallback == true) then
            return native_child_best or native_object_best;
        end
        return nil;
    end

    local child = read_u32(obj + 0x0C) or 0;
    if (accessxi.is_probe_pointer(child)) then
        add_pointer_text_candidates(('obj+0C@0x%08X'):fmt(child), child, 20);
        for _, off in ipairs(T{ 0x00, 0x08, 0x14, 0x18, 0x1C, 0x20, 0x24, 0x38, 0x40, 0x48, 0x50, 0x60, 0x68, 0x78, 0x88, 0x90, 0xA0, 0xC8 }) do
            local nested = read_u32(child + off) or 0;
            if (accessxi.is_probe_pointer(nested)) then
                local base_score = 40;
                if (off == 0x18) then
                    base_score = 220;
                elseif (off == 0x00 or off == 0x14) then
                    base_score = 80;
                end
                add_pointer_text_candidates(('obj+0C+%02X@0x%08X'):fmt(off, nested), nested, base_score);
            end
        end
    end

    for _, off in ipairs(T{ 0x88, 0x8C, 0x90, 0x94, 0x98, 0x9C, 0xA0 }) do
        local ptr = read_u32(obj + off) or 0;
        add_pointer_text_candidates(('obj+%02X'):fmt(off), ptr, off == 0x88 and 20 or 0);
    end

    for _, off in ipairs(T{ 0x14, 0x18 }) do
        local ptr = read_u32(obj + off) or 0;
        if (accessxi.is_probe_pointer(ptr)) then
            add_pointer_text_candidates(('obj+%02X@0x%08X'):fmt(off, ptr), ptr, 0);
            local desc = read_u32(ptr + 0x04) or 0;
            if (accessxi.is_probe_pointer(desc)) then
                add_pointer_text_candidates(('obj+%02Xdesc@0x%08X'):fmt(off, desc), desc, 40);
            end
        end
    end

    local line_block = read_u32(obj + 0x08) or 0;
    if (accessxi.is_probe_pointer(line_block)) then
        add_pointer_text_candidates(('obj+08@0x%08X'):fmt(line_block), line_block, 5);

        local seen_blocks = T{};
        local queue = T{ line_block };
        local depth = 0;
        while (#queue > 0 and depth < 16) do
            local block = table.remove(queue, 1);
            depth = depth + 1;
            if (accessxi.is_probe_pointer(block) and seen_blocks[block] ~= true) then
                seen_blocks[block] = true;
                add_pointer_text_candidates(('obj+08.chain%d@0x%08X'):fmt(depth, block), block, 15 - math.min(depth, 8));

                for _, link_off in ipairs(T{ 0x5C, 0x60, 0x80, 0xA0, 0xC0, 0xC4, 0xE0 }) do
                    local nested = read_u32(block + link_off) or 0;
                    if (accessxi.is_probe_pointer(nested) and seen_blocks[nested] ~= true and #queue < 24) then
                        queue:append(nested);
                    end
                end
            end
        end
    end

    local embedded = accessxi.chat_log_ascii_text_from_ptr(obj, accessxi.chat_log_max_line_len);
    if (embedded ~= '' and accessxi.chat_log_has_time(embedded)) then
        candidates:append(T{ source = ('obj=0x%08X'):fmt(obj), text = embedded, score = accessxi.chat_log_candidate_score(embedded) - 10 });
    end

    local best = nil;
    table.sort(candidates, function (a, b)
        return (tonumber(a.score) or 0) > (tonumber(b.score) or 0);
    end);
    for _, candidate in ipairs(candidates) do
        if (best == nil or (candidate.score or 0) > (best.score or 0)) then
            best = candidate;
        end
    end
    if (menu_name:eq('menu    logwindo', true)) then
        best = nil;
    elseif (menu_name:eq('menu    fulllog', true) or menu_name:find('menu    logwin2', 1, true) == 1) then
        local visible_best = nil;
        local visible_candidates = T{};
        for _, candidate in ipairs(candidates) do
            if (accessxi.chat_log_visible_row_source(candidate.source)) then
                visible_candidates:append(candidate);
            end
        end
        if (#visible_candidates > 0) then
            visible_best = visible_candidates[1];

            local signature_parts = T{};
            for i = 1, math.min(#visible_candidates, 8) do
                local candidate = visible_candidates[i];
                signature_parts:append(('%s:%s'):fmt(
                    tostring(candidate.source or ''),
                    accessxi.escape_probe_log_text(candidate.text or '')));
            end
            local visible_signature = signature_parts:concat(' | ');
            local last_line = tostring(accessxi.chat_log_last_native_line or '');

            if (visible_signature ~= (accessxi.chat_log_last_visible_signature or '')) then
                for _, candidate in ipairs(visible_candidates) do
                    local candidate_line = accessxi.speech_name(candidate.text or '');
                    if (candidate_line ~= '' and candidate_line ~= last_line) then
                        visible_best = candidate;
                        visible_best.chat_log_alternate = true;
                        break;
                    end
                end
            end

            if (visible_best ~= nil) then
                visible_best.visible_signature = visible_signature;
            end
        end
        best = visible_best;
    end
    if (#candidates > 0) then
        local parts = T{};
        for i = 1, math.min(#candidates, 10) do
            local candidate = candidates[i];
            parts:append(('%d:%s:%d:"%s"'):fmt(
                i,
                tostring(candidate.source or ''),
                tonumber(candidate.score) or 0,
                accessxi.escape_probe_log_text(candidate.text or '')));
        end
        local summary = parts:concat(' | ');
        if (summary ~= (accessxi.chat_log_last_candidate_summary or '')) then
            accessxi.chat_log_last_candidate_summary = summary;
            log_state(('state chatlog candidates menu="%s" obj=0x%08X %s'):fmt(menu_name, obj, summary));
        end
    end
    return best;
end

accessxi.chat_log_desc_name_for_obj = function (obj)
    obj = tonumber(obj) or 0;
    if (not accessxi.is_probe_pointer(obj)) then
        return '';
    end

    local desc = read_u32(obj + 0x04) or 0;
    if (not accessxi.is_probe_pointer(desc)) then
        return '';
    end

    return tostring(read_probe_string(desc + 0x46) or ''):trim();
end

accessxi.chat_log_native_line_from_current_or_siblings = function (obj, menu_name)
    obj = tonumber(obj) or 0;
    menu_name = tostring(menu_name or '');
    if (not accessxi.is_probe_pointer(obj)) then
        return nil, obj, menu_name;
    end

    local seen = {};
    local function try_chat_log_obj(candidate_obj, candidate_name, delta)
        candidate_obj = tonumber(candidate_obj) or 0;
        if (not accessxi.is_probe_pointer(candidate_obj) or seen[candidate_obj] == true) then
            return nil;
        end
        seen[candidate_obj] = true;
        local live_name = accessxi.chat_log_desc_name_for_obj(candidate_obj);
        if (is_chat_log_menu_name(live_name)) then
            candidate_name = live_name;
        else
            candidate_name = tostring(candidate_name or '');
        end
        if (not is_chat_log_menu_name(candidate_name)) then
            return nil;
        end

        local native = accessxi.chat_log_native_line_from_obj(candidate_obj, candidate_name);
        if (native ~= nil and native.text ~= nil and native.text ~= '') then
            accessxi.chat_log_native_sibling_cache_obj = candidate_obj;
            accessxi.chat_log_native_sibling_cache_name = candidate_name;
            accessxi.chat_log_native_sibling_delta = tonumber(delta) or 0;
            return native, candidate_obj, candidate_name;
        end
        return nil;
    end

    local native, native_obj, native_name = try_chat_log_obj(obj, menu_name, 0);
    if (native ~= nil) then
        return native, native_obj, native_name;
    end

    accessxi.chat_log_native_sibling_cache_obj = 0;
    accessxi.chat_log_native_sibling_cache_name = '';
    accessxi.chat_log_native_sibling_delta = 0;
    return nil, obj, menu_name;
end

function accessxi.log_chat_log_native_trace(name, obj, native, native_obj, native_name, selected, visible_count, suppress_initial)
    local now = tick();
    if (now > (accessxi.chat_log_native_trace_until or 0)) then
        return;
    end
    if ((now - (accessxi.chat_log_native_trace_last_tick or 0)) < 120) then
        return;
    end

    obj = tonumber(obj) or 0;
    native_obj = tonumber(native_obj) or 0;
    native = native or {};
    local desc = native_obj ~= 0 and (read_u32(native_obj + 0x04) or 0) or 0;
    local ptr88 = native_obj ~= 0 and (read_u32(native_obj + 0x88) or 0) or 0;
    local line_block = native_obj ~= 0 and (read_u32(native_obj + 0x08) or 0) or 0;
    local base = get_ffximain_base();
    local static_desc = 0;
    if (base ~= 0 and desc >= base) then
        static_desc = (desc - base) + 0x10000000;
    end

    local target = AshitaCore:GetMemoryManager():GetTarget();
    local ank_num = -1;
    local ank_x = -1;
    local ank_y = -1;
    if (target ~= nil) then
        ank_num = tonumber(safe_call(function () return target:GetWindowAnkNum(); end, -1)) or -1;
        ank_x = tonumber(safe_call(function () return target:GetWindowAnkX(); end, -1)) or -1;
        ank_y = tonumber(safe_call(function () return target:GetWindowAnkY(); end, -1)) or -1;
    end

    local fields = '';
    if (accessxi.chat_log_probe_small_fields ~= nil) then
        fields = accessxi.chat_log_probe_small_fields(native_obj);
    end
    local visible_lines = '';
    if (accessxi.chat_log_probe_timestamp_lines ~= nil and accessxi.is_probe_pointer(ptr88)) then
        visible_lines = accessxi.chat_log_probe_timestamp_lines(ptr88, 0x900, 20);
    end
    local line_lines = '';
    if (accessxi.chat_log_probe_timestamp_lines ~= nil and accessxi.is_probe_pointer(line_block)) then
        line_lines = accessxi.chat_log_probe_timestamp_lines(line_block, 0x600, 12);
    end
    local dwords000 = accessxi.format_probe_dwords ~= nil and accessxi.format_probe_dwords(native_obj, 0x00, 16) or '';
    local dwords040 = accessxi.format_probe_dwords ~= nil and accessxi.format_probe_dwords(native_obj, 0x40, 16) or '';
    local dwords080 = accessxi.format_probe_dwords ~= nil and accessxi.format_probe_dwords(native_obj, 0x80, 16) or '';
    local dwords0C0 = accessxi.format_probe_dwords ~= nil and accessxi.format_probe_dwords(native_obj, 0xC0, 16) or '';
    local dwords100 = accessxi.format_probe_dwords ~= nil and accessxi.format_probe_dwords(native_obj, 0x100, 16) or '';
    local dwords140 = accessxi.format_probe_dwords ~= nil and accessxi.format_probe_dwords(native_obj, 0x140, 16) or '';
    local dwords180 = accessxi.format_probe_dwords ~= nil and accessxi.format_probe_dwords(native_obj, 0x180, 16) or '';
    local dwords1C0 = accessxi.format_probe_dwords ~= nil and accessxi.format_probe_dwords(native_obj, 0x1C0, 16) or '';
    local ptrs = accessxi.chat_log_probe_ptr_summary ~= nil and accessxi.chat_log_probe_ptr_summary(native_obj) or '';
    local row_selected = tonumber(native.chat_log_row_selected) or -1;
    local row_count = tonumber(native.chat_log_row_count) or tonumber(visible_count) or 0;
    accessxi.chat_log_native_trace_sequence = (accessxi.chat_log_native_trace_sequence or 0) + 1;
    local trace_seq = accessxi.chat_log_native_trace_sequence;
    accessxi.chat_log_native_trace_last_tick = now;

    log_line(('chattrace seq=%d menu="%s" obj=0x%08X nativeMenu="%s" nativeObj=0x%08X desc=0x%08X staticDesc=0x%08X descName="%s" ffximain=0x%08X selected=%d count=%d rowSelected=%d rowCount=%d ank=%d ankxy=(%d,%d) ankSelected=%d suppress=%d reason="%s" source="%s" score=%d line="%s" sig="%s" fields="%s" visibleLines="%s" lineBlockLines="%s" ptrs="%s" dwords000=%s dwords040=%s dwords080=%s dwords0C0=%s dwords100=%s dwords140=%s dwords180=%s dwords1C0=%s'):fmt(
        trace_seq,
        tostring(name or ''),
        obj,
        tostring(native_name or ''),
        native_obj,
        desc,
        static_desc,
        accessxi.escape_probe_log_text(read_probe_string(desc + 0x46)),
        base,
        tonumber(selected) or 0,
        tonumber(visible_count) or 0,
        row_selected,
        row_count,
        ank_num,
        ank_x,
        ank_y,
        tonumber(native.chat_log_ank_selected) or -1,
        suppress_initial == true and 1 or 0,
        accessxi.escape_probe_log_text(tostring(native.chat_log_selection_reason or '')),
        accessxi.escape_probe_log_text(tostring(native.source or '')),
        tonumber(native.score) or 0,
        accessxi.escape_probe_log_text(tostring(native.text or '')),
        accessxi.escape_probe_log_text(tostring(native.visible_signature or '')),
        accessxi.escape_probe_log_text(fields),
        accessxi.escape_probe_log_text(visible_lines),
        accessxi.escape_probe_log_text(line_lines),
        accessxi.escape_probe_log_text(ptrs),
        dwords000,
        dwords040,
        dwords080,
        dwords0C0,
        dwords100,
        dwords140,
        dwords180,
        dwords1C0));
end

local function chat_log_menu_speech(name, suppress_initial)
    if (not is_chat_log_menu_name(name)) then
        return nil;
    end

    local obj = get_current_menu_object_ptr();
    local native, native_obj, native_name = accessxi.chat_log_native_line_from_current_or_siblings(obj, name);
    native_obj = tonumber(native_obj) or obj;
    native_name = tostring(native_name or name);
    local selected = obj ~= 0 and (tonumber(read_i32(obj + 0x4C)) or 0) or 0;
    local visible_count = 0;
    if (native_obj ~= 0) then
        selected = tonumber(read_i32(native_obj + 0x4C)) or selected;
        visible_count = math.max(
            tonumber(read_i32(native_obj + 0x24)) or 0,
            tonumber(read_i32(native_obj + 0x28)) or 0);
    elseif (obj ~= 0) then
        visible_count = math.max(
            tonumber(read_i32(obj + 0x24)) or 0,
            tonumber(read_i32(obj + 0x28)) or 0);
    end
    if (visible_count <= 0 or visible_count > 12) then
        visible_count = 3;
    end
    if (selected < 0 or selected >= visible_count) then
        selected = 0;
    end

    local now = tick();
    if (native ~= nil and native.text ~= nil and native.text ~= '') then
        accessxi.clear_chat_log_missing_retry();
        accessxi.chat_log_last_live_obj = native_obj;
        accessxi.chat_log_last_live_name = native_name;
        accessxi.chat_log_last_live_tick = now;
        if (native.chat_log_row_selected ~= nil) then
            selected = tonumber(native.chat_log_row_selected) or selected;
        end
        if (native.chat_log_row_count ~= nil) then
            visible_count = tonumber(native.chat_log_row_count) or visible_count;
        end
        accessxi.log_chat_log_native_trace(name, obj, native, native_obj, native_name, selected, visible_count, suppress_initial);
        local line = accessxi.chat_log_speech_text(native.text, native.chat_log_menu_nav == true);
        local visible_signature = tostring(native.visible_signature or '');
        local prior_line = tostring(accessxi.chat_log_last_native_line or '');
        local prior_signature = tostring(accessxi.chat_log_last_visible_signature or '');
        local native_changed = line ~= '' and (line ~= prior_line or visible_signature ~= prior_signature);
        local native_source = tostring(native.source or '');
        local temp_source = native_source:find('templog', 1, true) ~= nil;
        local high_quality_native_change =
            native_changed
            and native.chat_log_menu_nav == true
            and (tonumber(native.score) or 0) >= 1000
            and (temp_source or native_source:find('scanascii', 1, true) == nil);
        if (high_quality_native_change and native.chat_log_should_speak == false) then
            native.chat_log_should_speak = true;
            native.chat_log_queue_immediate = true;
            native.chat_log_selection_reason = 'line-change';
        end
        if (native.chat_log_menu_nav == true
            and native_source:find('fulllog-', 1, true) ~= nil) then
            native.chat_log_queue_immediate = false;
            accessxi.chat_log_pending_delay_override = 95;
            local sig_cursor = tonumber(visible_signature:match('^(%-?%d+):')) or -1;
            if (sig_cursor >= 0 and sig_cursor ~= (tonumber(accessxi.chat_log_full_last_cursor) or -1)) then
                accessxi.chat_log_full_last_cursor = sig_cursor;
                accessxi.chat_log_full_last_cursor_tick = now;
            end
        end
        local speech_key = ('chatlog-native:%s:%d:%s:%s:%s:%s'):fmt(
            native_name,
            selected,
            native.source or '',
            line,
            visible_signature,
            tostring(native.chat_log_position_key or ''));
        if (suppress_initial == true or now < (accessxi.chat_log_settle_until or 0)) then
            accessxi.chat_log_last_native_line = line;
            accessxi.chat_log_last_visible_signature = visible_signature;
            accessxi.current_speech_key = speech_key;
            log_state(('state chatlog initial-suppressed menu="%s" obj=0x%08X nativeMenu="%s" nativeObj=0x%08X select=%d ank=%d ankSelected=%d reason="%s" count=%d source="%s" score=%d line="%s" sig="%s"'):fmt(
                name,
                obj,
                native_name,
                native_obj,
                selected,
                tonumber(native.chat_log_ank_num) or -1,
                tonumber(native.chat_log_ank_selected) or -1,
                accessxi.escape_probe_log_text(tostring(native.chat_log_selection_reason or '')),
                visible_count,
                native.source or '',
                tonumber(native.score) or 0,
                line,
                accessxi.escape_probe_log_text(visible_signature)));
            return '';
        end
        accessxi.chat_log_last_native_line = line;
        accessxi.chat_log_last_visible_signature = visible_signature;
        accessxi.current_speech_key = speech_key;
        log_state(('state chatlog native menu="%s" obj=0x%08X nativeMenu="%s" nativeObj=0x%08X select=%d ank=%d ankSelected=%d reason="%s" count=%d source="%s" score=%d alt=%d menunav=%d line="%s" sig="%s"'):fmt(
            name,
            obj,
            native_name,
            native_obj,
            selected,
            tonumber(native.chat_log_ank_num) or -1,
            tonumber(native.chat_log_ank_selected) or -1,
            accessxi.escape_probe_log_text(tostring(native.chat_log_selection_reason or '')),
            visible_count,
            native.source or '',
            tonumber(native.score) or 0,
            native.chat_log_alternate == true and 1 or 0,
            native.chat_log_menu_nav == true and 1 or 0,
            line,
            accessxi.escape_probe_log_text(visible_signature)));
        if (native.chat_log_should_speak == false) then
            accessxi.chat_log_queue_immediate = false;
            return '';
        end
        accessxi.chat_log_queue_immediate = native.chat_log_queue_immediate == true;
        return accessxi.chat_message_speech(line);
    end

    local missing_ank = -1;
    local target = AshitaCore:GetMemoryManager():GetTarget();
    if (target ~= nil) then
        missing_ank = tonumber(safe_call(function () return target:GetWindowAnkNum(); end, -1)) or -1;
    end
    local missing_state = accessxi.chat_log_global_state_from_menu_obj(native_obj, native_name);
    local missing_cursor = missing_state ~= nil and (tonumber(missing_state.cursor) or -1) or -1;
    local missing_bottom = missing_state ~= nil and (tonumber(missing_state.bottom) or -1) or -1;
    local missing_index_raw = missing_state ~= nil and (tonumber(missing_state.selected_index_unclamped) or -1) or -1;
    local missing_index = missing_state ~= nil and (tonumber(missing_state.selected_index) or -1) or -1;
    local missing_row = missing_state ~= nil and (tonumber(missing_state.selected_row) or 0) or 0;
    local missing_key = ('%s:0x%08X:%d:%d:%d:%d:0x%08X'):fmt(
        native_name,
        native_obj,
        missing_cursor,
        missing_bottom,
        missing_index_raw,
        missing_index,
        missing_row);
    accessxi.current_speech_key = ('chatlog-native-missing:%s'):fmt(missing_key);
    if (tostring(native_name or ''):eq('menu    fulllog', true)) then
        accessxi.clear_chat_log_missing_retry();
    end
    if (not tostring(native_name or ''):eq('menu    fulllog', true)
        and missing_cursor >= 0 and missing_bottom >= 0
        and missing_key ~= tostring(accessxi.chat_log_missing_retry_key or '')) then
        accessxi.chat_log_missing_retry_key = missing_key;
        accessxi.chat_log_missing_retry_due = now + 70;
        accessxi.chat_log_missing_retry_count = 0;
    end
    if (missing_key ~= (accessxi.chat_log_native_missing_last_log or '')) then
        accessxi.chat_log_native_missing_last_log = missing_key;
        log_state(('state chatlog native-missing menu="%s" obj=0x%08X nativeMenu="%s" nativeObj=0x%08X select=%d ank=%d count=%d cursor=%d bottom=%d selectedIndexRaw=%d selectedIndex=%d selectedRow=0x%08X'):fmt(
            name,
            obj,
            native_name,
            native_obj,
            selected,
            missing_ank,
            visible_count,
            missing_cursor,
            missing_bottom,
            missing_index_raw,
            missing_index,
            missing_row));
    end
    return '';
end

local function command_tail(args, start_index)
    local parts = T{};
    for i = start_index, #args do
        parts:append(args[i]);
    end
    return parts:concat(' '):trim();
end

local function nav_clean_field(text)
    if (text == nil) then
        return '';
    end
    return clean_login_text(tostring(text):gsub('[\t\r\n]', ' '));
end

local function nav_tsv_field(text)
    return nav_clean_field(text):gsub('\t', ' '):gsub('[\r\n]', ' ');
end

-- ACCESSXI_OBJECTIVE_ROUTE_INTEGRITY_BEGIN
(function ()
local ACCESSXI_OBJECTIVE_ROUTE_MANIFEST_SHA256 = "0b5965660348e15f129bfc3e4d790f456011ae745932dc14db11bb98b9bd1315";
local accessxi_objective_manifest_rows = nil;
local accessxi_objective_file_hasher = nil;
local accessxi_objective_runtime_attempted = false;
local accessxi_objective_native_observer = {
    trusted = false,
    reason = 'Objective native code has not been observed.',
    dll = nil,
    mesh = nil,
};

local function accessxi_uint32(value)
    value = tonumber(value);
    if (value == nil or value < 0 or value > 4294967295 or value ~= math.floor(value)) then
        return nil;
    end
    return value;
end

function accessxi_file_stat(path)
    path = tostring(path or '');
    if (path == '') then
        return nil, 'File stat path is unavailable.';
    end
    local wide = utf8_to_wide(path);
    if (wide == nil) then
        return nil, 'File stat path conversion failed.';
    end
    local invalid_handle = ffi.cast('void*', -1);
    local open_ok, handle = pcall(function ()
        return kernel32.CreateFileW(wide, 0x80000000, 0x00000001, nil, 3, 0x00000080, nil);
    end);
    if (not open_ok or handle == nil or handle == invalid_handle) then
        return nil, 'File stat open failed.';
    end

    local function close_handle()
        local ok, closed = pcall(function () return kernel32.CloseHandle(handle); end);
        return ok and closed ~= 0;
    end

    local high = ffi.new('DWORD[1]');
    local size_ok, size_low, size_error = pcall(function ()
        kernel32.SetLastError(0);
        local low = kernel32.GetFileSize(handle, high);
        local last_error = kernel32.GetLastError();
        return low, last_error;
    end);
    if (not size_ok) then
        close_handle();
        return nil, 'File size query failed: ' .. tostring(size_low);
    end
    size_low = accessxi_uint32(size_low);
    local size_high = accessxi_uint32(high[0]);
    size_error = accessxi_uint32(size_error);
    if (size_low == nil or size_high == nil or size_error == nil
        or (size_low == 4294967295 and size_error ~= 0)) then
        close_handle();
        return nil, 'File size query failed.';
    end

    local write_time = ffi.new('FILETIME[1]');
    local time_ok, got_time = pcall(function ()
        return kernel32.GetFileTime(handle, nil, nil, write_time);
    end);
    local write_time_low = time_ok and accessxi_uint32(write_time[0].dwLowDateTime) or nil;
    local write_time_high = time_ok and accessxi_uint32(write_time[0].dwHighDateTime) or nil;
    if (not time_ok or got_time == 0 or write_time_low == nil or write_time_high == nil) then
        close_handle();
        return nil, 'File time query failed.';
    end
    if (not close_handle()) then
        return nil, 'File stat close failed.';
    end
    return {
        size_low = size_low,
        size_high = size_high,
        write_time_low = write_time_low,
        write_time_high = write_time_high,
    };
end

local function accessxi_objective_canonical_path(path)
    local value = accessxi_paths.normalize(path);
    local root = accessxi_paths.normalize(accessxi_paths.addon_path());
    if (value == '' or root == ''
        or value:find('\\.\\', 1, true) or value:find('\\..\\', 1, true)
        or value:sub(-2) == '\\.' or value:sub(-3) == '\\..'
        or value:lower():sub(1, #root) ~= root:lower()
        or (#value > #root and value:sub(#root + 1, #root + 1) ~= '\\')) then
        return nil, 'Path is not a canonical child of the addon root.';
    end
    return value;
end

local function accessxi_objective_split_tabs(line)
    local fields = {};
    local start = 1;
    while true do
        local position = line:find('\t', start, true);
        if (position == nil) then
            fields[#fields + 1] = line:sub(start);
            break;
        end
        fields[#fields + 1] = line:sub(start, position - 1);
        start = position + 1;
    end
    return fields;
end

local function accessxi_objective_parse_manifest(bytes)
    if (type(bytes) ~= 'string' or bytes:sub(-1) ~= '\n') then
        return nil, 'Objective route manifest is not newline terminated.';
    end
    local lines = {};
    for line in bytes:gmatch('([^\n]*)\n') do
        if (line:sub(-1) == '\r') then
            line = line:sub(1, -2);
        end
        lines[#lines + 1] = line;
    end
    if (lines[1] ~= 'relative_path\tsha256\tkind\tzone\tmesh_name') then
        return nil, 'Objective route manifest header is invalid.';
    end
    local rows = {};
    local prior = '';
    for index = 2, #lines do
        local fields = accessxi_objective_split_tabs(lines[index]);
        local relative_path = fields[1];
        local digest = fields[2];
        local kind = fields[3];
        local zone_text = fields[4];
        local mesh_name = fields[5];
        local key = type(relative_path) == 'string' and relative_path:lower() or '';
        if (#fields ~= 5 or relative_path == '' or relative_path:find('\\', 1, true)
            or relative_path:sub(1, 1) == '/' or relative_path:find(':', 1, true)
            or relative_path:find('/./', 1, true) or relative_path:find('/../', 1, true)
            or relative_path:sub(1, 2) == './' or relative_path:sub(1, 3) == '../'
            or relative_path:sub(-2) == '/.' or relative_path:sub(-3) == '/..'
            or key <= prior or rows[key] ~= nil
            or type(digest) ~= 'string' or #digest ~= 64
            or digest:find('[^0-9a-f]') ~= nil or kind == '') then
            return nil, 'Objective route manifest row is malformed, duplicated, or unsorted.';
        end
        local zone = nil;
        if (zone_text ~= '') then
            zone = tonumber(zone_text);
            if (zone == nil or zone < 0 or zone ~= math.floor(zone)) then
                return nil, 'Objective route manifest zone is invalid.';
            end
        end
        rows[relative_path] = {
            relative_path = relative_path,
            sha256 = digest,
            kind = kind,
            zone = zone,
            mesh_name = mesh_name,
        };
        prior = key;
    end
    if (rows['modules/mission_quest_route_runtime.lua'] == nil
        or rows['third_party/FFXI-NavMesh-Builder/FFXINAV.dll'] == nil) then
        return nil, 'Objective route manifest is missing a required runtime child.';
    end
    return rows;
end

local function accessxi_objective_identity_copy(identity)
    if (type(identity) ~= 'table') then
        return nil;
    end
    return {
        size_low = identity.size_low,
        size_high = identity.size_high,
        write_time_low = identity.write_time_low,
        write_time_high = identity.write_time_high,
    };
end

local function accessxi_objective_snapshot_copy(snapshot)
    if (type(snapshot) ~= 'table') then
        return nil;
    end
    return {
        path = snapshot.path,
        sha256 = snapshot.sha256,
        identity = accessxi_objective_identity_copy(snapshot.identity),
        mesh_name = snapshot.mesh_name,
        zone = snapshot.zone,
    };
end

local function accessxi_objective_mark_untrusted(reason, clear_mesh)
    accessxi_objective_native_observer.trusted = false;
    accessxi_objective_native_observer.reason = tostring(reason or 'Objective native integrity is unavailable.');
    if (clear_mesh == true) then
        accessxi_objective_native_observer.mesh = nil;
    end
    return false;
end

function accessxi.nav_objective_native_mark_untrusted(reason)
    return accessxi_objective_mark_untrusted(reason, true);
end

local function accessxi_objective_observe_file(relative_path, requested_path)
    local row = accessxi_objective_manifest_rows ~= nil
        and accessxi_objective_manifest_rows[relative_path] or nil;
    local expected_path = accessxi_paths.addon_path(relative_path);
    local canonical = accessxi_objective_canonical_path(requested_path);
    if (row == nil or canonical == nil or canonical ~= expected_path
        or accessxi_objective_file_hasher == nil) then
        return nil, 'The native file is not an exact rooted manifest child.';
    end
    local ok, bytes, digest, identity, reason = pcall(
        accessxi_objective_file_hasher.read_and_hash_file,
        accessxi_objective_file_hasher,
        canonical);
    if (not ok or type(bytes) ~= 'string' or digest ~= row.sha256 or type(identity) ~= 'table') then
        return nil, not ok and tostring(bytes) or tostring(reason or 'Native file hash mismatch.');
    end
    return {
        path = canonical,
        sha256 = digest,
        identity = accessxi_objective_identity_copy(identity),
    };
end

local function accessxi_objective_identity_equal(left, right)
    return type(left) == 'table' and type(right) == 'table'
        and left.size_low == right.size_low and left.size_high == right.size_high
        and left.write_time_low == right.write_time_low
        and left.write_time_high == right.write_time_high;
end

local function accessxi_objective_snapshot_current(relative_path, snapshot)
    local current, reason = accessxi_objective_observe_file(relative_path, snapshot ~= nil and snapshot.path or '');
    if (current == nil or snapshot == nil or current.sha256 ~= snapshot.sha256
        or not accessxi_objective_identity_equal(current.identity, snapshot.identity)) then
        return false, reason or 'The observed native file identity changed.';
    end
    return true;
end

function accessxi.nav_objective_native_before_dll_load(path)
    local snapshot, reason = accessxi_objective_observe_file(
        'third_party/FFXI-NavMesh-Builder/FFXINAV.dll', path);
    if (snapshot == nil) then
        accessxi_objective_native_observer.dll = nil;
        return accessxi_objective_mark_untrusted(reason, true);
    end
    accessxi_objective_native_observer.dll = snapshot;
    accessxi_objective_native_observer.mesh = nil;
    accessxi_objective_native_observer.trusted = false;
    accessxi_objective_native_observer.reason = 'No rooted objective mesh is loaded.';
    return true;
end

function accessxi.nav_objective_native_before_mesh_load(zone, mesh_name, path)
    zone = tonumber(zone);
    mesh_name = tostring(mesh_name or '');
    if (zone == nil or zone < 0 or zone ~= math.floor(zone)
        or mesh_name == '' or mesh_name:find('[\\/]')) then
        return accessxi_objective_mark_untrusted('The objective mesh identity is malformed.', true);
    end
    local relative_path = 'third_party/xiNavmeshes/' .. mesh_name;
    local row = accessxi_objective_manifest_rows ~= nil and accessxi_objective_manifest_rows[relative_path] or nil;
    if (row == nil or row.kind ~= 'mesh' or tonumber(row.zone) ~= zone or row.mesh_name ~= mesh_name) then
        return accessxi_objective_mark_untrusted('The objective mesh is not rooted for this zone.', true);
    end
    local dll_current, dll_reason = accessxi_objective_snapshot_current(
        'third_party/FFXI-NavMesh-Builder/FFXINAV.dll',
        accessxi_objective_native_observer.dll);
    if (not dll_current) then
        return accessxi_objective_mark_untrusted(dll_reason, true);
    end
    local snapshot, reason = accessxi_objective_observe_file(relative_path, path);
    if (snapshot == nil) then
        return accessxi_objective_mark_untrusted(reason, true);
    end
    snapshot.zone = zone;
    snapshot.mesh_name = mesh_name;
    accessxi_objective_native_observer.mesh = snapshot;
    accessxi_objective_native_observer.trusted = true;
    accessxi_objective_native_observer.reason = '';
    return true;
end

function accessxi.nav_objective_native_integrity_state()
    local observer = accessxi_objective_native_observer;
    if (observer.dll == nil or observer.mesh == nil) then
        observer.trusted = false;
    else
        local dll_ok, dll_reason = accessxi_objective_snapshot_current(
            'third_party/FFXI-NavMesh-Builder/FFXINAV.dll', observer.dll);
        local mesh_ok, mesh_reason = accessxi_objective_snapshot_current(
            'third_party/xiNavmeshes/' .. tostring(observer.mesh.mesh_name or ''), observer.mesh);
        if (not dll_ok or not mesh_ok) then
            observer.trusted = false;
            observer.reason = dll_reason or mesh_reason or 'The loaded native file identity changed.';
        end
    end
    return {
        trusted = observer.trusted == true,
        reason = tostring(observer.reason or ''),
        dll = accessxi_objective_snapshot_copy(observer.dll),
        mesh = accessxi_objective_snapshot_copy(observer.mesh),
    };
end

function accessxi.nav_objective_native_revalidate_loaded_mesh(zone)
    local snapshot = accessxi.nav_objective_native_integrity_state();
    if (snapshot.trusted ~= true or snapshot.mesh == nil
        or tonumber(snapshot.mesh.zone) ~= tonumber(zone)) then
        return accessxi_objective_mark_untrusted(
            snapshot.reason ~= '' and snapshot.reason or 'The loaded objective mesh changed.',
            false);
    end
    return true;
end

function accessxi.nav_objective_load_rooted_mesh(zone, mesh_name, path)
    zone = tonumber(zone);
    mesh_name = tostring(mesh_name or '');
    path = accessxi_objective_canonical_path(path);
    local expected = mesh_name ~= ''
        and accessxi_paths.addon_path('third_party', 'xiNavmeshes', mesh_name) or nil;
    if (zone == nil or zone < 0 or zone ~= math.floor(zone)
        or path == nil or path ~= expected) then
        accessxi.nav_objective_native_mark_untrusted('The rooted objective mesh request is malformed.');
        return false;
    end
    if (ffxinav == nil) then
        accessxi.nav_objective_native_before_dll_load(accessxi.nav_mesh_dll_path);
        local ok, library = pcall(ffi.load, accessxi.nav_mesh_dll_path);
        if (not ok or library == nil) then
            accessxi.nav_objective_native_mark_untrusted('FFXINAV DLL load failed.');
            return false;
        end
        ffxinav = library;
        accessxi.nav_mesh_available = true;
    end
    if (accessxi.nav_mesh_handle == nil) then
        local ok, handle = pcall(function () return ffxinav.CreateFFXINavClass(); end);
        if (not ok or handle == nil) then
            accessxi.nav_objective_native_mark_untrusted('FFXINAV handle creation failed.');
            return false;
        end
        accessxi.nav_mesh_handle = handle;
    end
    if (accessxi.nav_mesh_loaded == true and accessxi.nav_mesh_zone == zone
        and accessxi_objective_native_observer.mesh ~= nil
        and accessxi_objective_native_observer.mesh.mesh_name == mesh_name) then
        return accessxi.nav_objective_native_revalidate_loaded_mesh(zone);
    end
    local wide_path = utf8_to_wide(path);
    if (wide_path == nil
        or accessxi.nav_objective_native_before_mesh_load(zone, mesh_name, path) ~= true) then
        return false;
    end
    local ok, loaded = pcall(function ()
        return ffxinav.LoadMesh(accessxi.nav_mesh_handle, wide_path);
    end);
    accessxi.nav_mesh_loaded = ok and loaded == true;
    accessxi.nav_mesh_zone = accessxi.nav_mesh_loaded and zone or 0;
    if (not accessxi.nav_mesh_loaded) then
        accessxi.nav_objective_native_mark_untrusted('FFXINAV LoadMesh failed.');
    end
    return accessxi.nav_mesh_loaded;
end

local function accessxi_objective_runtime_failure(reason)
    accessxi.objective_route_runtime = nil;
    accessxi.objective_route_runtime_failure_reason = tostring(reason or 'Objective route runtime is unavailable.');
    local safe_reason = type(accessxi.escape_probe_log_text) == 'function'
        and accessxi.escape_probe_log_text(accessxi.objective_route_runtime_failure_reason)
        or accessxi.objective_route_runtime_failure_reason;
    log_line('objective route runtime disabled: '
        .. safe_reason);
    return false;
end

local function accessxi_objective_runtime_bootstrap()
    local sha_module = accessxi.load_module_table('accessxi_sha256', nil);
    if (type(sha_module) ~= 'table' or type(sha_module.sha256) ~= 'function'
        or type(sha_module.smoke_test) ~= 'function'
        or type(sha_module.new_file_hasher) ~= 'function') then
        return nil, 'Objective SHA-256 module is unavailable.';
    end
    local smoke_ok, smoke_value, smoke_reason = pcall(sha_module.smoke_test);
    if (not smoke_ok or smoke_value ~= true) then
        return nil, 'Objective SHA-256 smoke test failed: '
            .. tostring(smoke_ok and smoke_reason or smoke_value);
    end
    local hasher_ok, hasher = pcall(sha_module.new_file_hasher, {
        canonicalize = accessxi_objective_canonical_path,
        stat = accessxi_file_stat,
        open = function(path, mode) return io.open(path, mode); end,
    });
    if (not hasher_ok or type(hasher) ~= 'table'
        or type(hasher.read_and_hash_file) ~= 'function') then
        return nil, 'Objective file hasher is unavailable: ' .. tostring(hasher);
    end
    accessxi_objective_file_hasher = hasher;

    local manifest_path = accessxi_paths.addon_path('data', 'mission-quest-route-manifest.tsv');
    local read_ok, manifest_bytes, manifest_digest = pcall(
        hasher.read_and_hash_file, hasher, manifest_path);
    if (not read_ok or type(manifest_bytes) ~= 'string'
        or manifest_digest ~= ACCESSXI_OBJECTIVE_ROUTE_MANIFEST_SHA256) then
        return nil, 'Objective route manifest hash does not match the reader pin.';
    end
    local rows, parse_error = accessxi_objective_parse_manifest(manifest_bytes);
    if (rows == nil) then
        return nil, parse_error;
    end
    accessxi_objective_manifest_rows = rows;

    local runtime_relative = 'modules/mission_quest_route_runtime.lua';
    local runtime_row = rows[runtime_relative];
    if (runtime_row == nil or runtime_row.kind ~= 'runtime') then
        return nil, 'Objective route runtime manifest row is unavailable.';
    end
    local runtime_path = accessxi_paths.addon_path(runtime_relative);
    local runtime_ok, runtime_bytes, runtime_digest = pcall(
        hasher.read_and_hash_file, hasher, runtime_path);
    if (not runtime_ok or type(runtime_bytes) ~= 'string' or runtime_digest ~= runtime_row.sha256) then
        return nil, 'Objective route runtime child hash mismatch.';
    end
    local compile_ok, chunk, compile_error = pcall(loadstring, runtime_bytes, '@' .. runtime_relative);
    if (not compile_ok or type(chunk) ~= 'function') then
        return nil, 'Objective route runtime compilation failed: '
            .. tostring(compile_ok and compile_error or chunk);
    end
    local current_environment = getfenv(1);
    local module_environment = setmetatable({
        EXECUTION_FLAGS = current_environment ~= nil and current_environment.EXECUTION_FLAGS or nil,
    }, { __index = _G });
    setfenv(chunk, module_environment);
    local execute_ok, runtime_module = pcall(chunk);
    if (not execute_ok or type(runtime_module) ~= 'table' or type(runtime_module.new) ~= 'function') then
        return nil, 'Objective route runtime execution failed: ' .. tostring(runtime_module);
    end

    local native_adapter = {
        is_valid_position = function(_, point)
            return accessxi.nav_objective_native_is_valid_position(point);
        end,
        get_distance_to_wall = function(_, point)
            return accessxi.nav_objective_native_get_distance_to_wall(point);
        end,
        find_path = function(_, start_point, end_point)
            return accessxi.nav_objective_native_find_path(start_point, end_point);
        end,
        get_waypoints = function(_, maximum)
            return accessxi.nav_objective_native_get_waypoints(maximum);
        end,
    };
    local options = {
        expected_manifest_sha256 = ACCESSXI_OBJECTIVE_ROUTE_MANIFEST_SHA256,
        manifest_path = manifest_path,
        path_for = function(relative_path)
            if (type(relative_path) ~= 'string' or relative_path == ''
                or relative_path:find('\\', 1, true) or relative_path:find(':', 1, true)
                or relative_path:find('/../', 1, true) or relative_path:sub(1, 1) == '/') then
                return nil;
            end
            return accessxi_paths.addon_path(relative_path);
        end,
        file_hasher = hasher,
        sha256 = sha_module.sha256,
        module_environment = module_environment,
        objective_native = native_adapter,
        objective_mesh_loader = accessxi.nav_objective_load_rooted_mesh,
        native_integrity_state = accessxi.nav_objective_native_integrity_state,
    };
    local new_ok, runtime = pcall(runtime_module.new, options);
    if (not new_ok or type(runtime) ~= 'table') then
        return nil, 'Objective route runtime initialization failed: ' .. tostring(runtime);
    end
    if (type(runtime.is_ready) ~= 'function' or not runtime:is_ready()) then
        local reason = type(runtime.failure_reason) == 'function' and runtime:failure_reason()
            or 'Objective route runtime rejected its rooted inputs.';
        return nil, reason;
    end
    accessxi.objective_route_runtime = runtime;
    accessxi.objective_route_runtime_failure_reason = '';
    return true;
end

function accessxi.ensure_objective_route_runtime()
    if (type(accessxi.objective_route_runtime) == 'table') then
        return true, '';
    end
    if (accessxi_objective_runtime_attempted) then
        local prior_reason = tostring(accessxi.objective_route_runtime_failure_reason or '');
        return false, prior_reason ~= '' and prior_reason
            or 'Objective route runtime is unavailable.';
    end
    accessxi_objective_runtime_attempted = true;
    local bootstrap_ok, ready, reason = pcall(accessxi_objective_runtime_bootstrap);
    if (not bootstrap_ok) then
        accessxi_objective_runtime_failure(ready);
    elseif (ready ~= true) then
        accessxi_objective_runtime_failure(reason);
    else
        return true, '';
    end
    local failure_reason = tostring(accessxi.objective_route_runtime_failure_reason or '');
    return false, failure_reason ~= '' and failure_reason
        or 'Objective route runtime is unavailable.';
end
end)();
-- ACCESSXI_OBJECTIVE_ROUTE_INTEGRITY_END

local function nav_round(value, places)
    local mult = 10 ^ (places or 0);
    if ((tonumber(value) or 0) >= 0) then
        return math.floor((tonumber(value) or 0) * mult + 0.5) / mult;
    end
    return math.ceil((tonumber(value) or 0) * mult - 0.5) / mult;
end

local function nav_axis_delta(value, axis)
    value = tonumber(value) or 0;
    local amount = math.abs(value);
    if (amount < 0.5) then
        return '';
    end

    local sign = value >= 0 and 'plus' or 'minus';
    return ('%s %s %.0f'):fmt(axis, sign, amount);
end

