function accessxi.nav_search_results_available()
    return nav_clean_field(accessxi.nav_menu_search_query or '') ~= ''
        and accessxi.nav_menu_search_results ~= nil
        and accessxi.nav_menu_search_results:len() > 0;
end

function accessxi.nav_menu_categories()
    local categories = T{};
    for _, category in ipairs(accessxi.navigation_data.menu_categories or T{}) do
        categories:append(category);
    end
    if (accessxi.nav_search_results_available()) then
        categories:append(T{ key = 'search-results', label = 'Search Results' });
    end
    return categories;
end

function accessxi.nav_search_category_index()
    local categories = accessxi.nav_menu_categories();
    for i = 1, categories:len() do
        local category = categories[i];
        if (tostring(category ~= nil and category.key or '') == 'search-results') then
            return i;
        end
    end
    return 0;
end

local function nav_current_category()
    local categories = accessxi.nav_menu_categories();
    if (categories:len() == 0) then
        return nil;
    end
    if (accessxi.nav_menu_category < 1) then
        accessxi.nav_menu_category = categories:len();
    elseif (accessxi.nav_menu_category > categories:len()) then
        accessxi.nav_menu_category = 1;
    end
    return categories[accessxi.nav_menu_category];
end

local function nav_normalized_kind(kind)
    kind = tostring(kind or ''):lower();
    if (kind:contains('live-nm') or kind:contains('live nm')) then
        return 'live-nm';
    end
    if (kind:contains('nm') or kind:contains('notorious') or kind:contains('spawn point') or kind:contains('spawnpoint') or kind:contains('nm spawn')) then
        return 'nm';
    end
    if (kind:contains('enemy') or kind:contains('monster') or kind:contains('mob')) then
        return 'enemy';
    end
    if (kind:contains('area') or kind:contains('zone') or kind:contains('transition') or kind:contains('mog house')) then
        return 'area';
    end
    if (kind:contains('player')) then
        return 'player';
    end
    if (kind:contains('npc')) then
        return 'npc';
    end
    if (kind:contains('home') or kind:contains('waypoint') or kind:contains('auction') or kind:contains('guide') or kind:contains('object') or kind:contains('discovered') or kind:contains('target') or kind:contains('nearby')) then
        return 'object';
    end
    return 'object';
end

local function nav_kind_matches_category(kind, category_key)
    if (category_key == nil or category_key == 'all') then
        return true;
    end
    return nav_normalized_kind(kind) == category_key;
end

function accessxi.nav_point_effective_kind(point)
    local kind = nav_normalized_kind(point ~= nil and point.kind or '');
    local name = tostring(point ~= nil and point.name or ''):lower():gsub('%s+', ' ');
    if (name == '???') then
        return 'object';
    end
    if ((kind == 'object' or kind == 'nearby') and accessxi.nav_entity_name_looks_like_enemy ~= nil and accessxi.nav_entity_name_looks_like_enemy(point)) then
        return 'enemy';
    end
    return kind;
end

function accessxi.nav_point_matches_category(point, category_key)
    if (category_key == nil or category_key == 'all') then
        return true;
    end
    local kind = accessxi.nav_point_effective_kind(point);
    if (category_key == 'enemy' and kind == 'live-nm') then
        return true;
    end
    return kind == category_key;
end

local function nav_zone_id()
    local party = safe_call(function () return AshitaCore:GetMemoryManager():GetParty(); end, nil);
    if (party == nil) then
        return 0;
    end

    local zone = tonumber(safe_call(function () return party:GetMemberZone(0); end, 0)) or 0;
    if (zone == 0) then
        zone = tonumber(safe_call(function () return party:GetMemberZone2(0); end, 0)) or 0;
    end
    return zone;
end

local function nav_player_index()
    local party = safe_call(function () return AshitaCore:GetMemoryManager():GetParty(); end, nil);
    if (party == nil) then
        return 0;
    end

    local index = tonumber(safe_call(function () return party:GetMemberTargetIndex(0); end, 0)) or 0;
    if (index <= 0) then
        index = tonumber(safe_call(function () return party:GetMemberIndex(0); end, 0)) or 0;
    end
    return index;
end

local function nav_entity_position(index)
    index = tonumber(index) or -1;
    if (index < 0) then
        return nil;
    end

    local entity = safe_call(function () return AshitaCore:GetMemoryManager():GetEntity(); end, nil);
    if (entity == nil) then
        return nil;
    end

    local name = nav_clean_field(safe_call(function () return entity:GetName(index); end, ''));
    local x = tonumber(safe_call(function () return entity:GetLocalPositionX(index); end, nil));
    local z = tonumber(safe_call(function () return entity:GetLocalPositionY(index); end, nil));
    local y = tonumber(safe_call(function () return entity:GetLocalPositionZ(index); end, nil));
    local yaw = tonumber(safe_call(function () return entity:GetLocalPositionYaw(index); end, nil));
    if (x == nil or z == nil) then
        return nil;
    end

    return T{
        index = index,
        name = name,
        zone = nav_zone_id(),
        x = x,
        z = z,
        y = y or 0,
        yaw = yaw or 0,
        server_id = tonumber(safe_call(function () return entity:GetServerId(index); end, 0)) or 0,
        type = tonumber(safe_call(function () return entity:GetType(index); end, -1)) or -1,
        hp = tonumber(safe_call(function () return entity:GetHPPercent(index); end, -1)) or -1,
        status = tonumber(safe_call(function () return entity:GetStatus(index); end, -1)) or -1,
        claim = tonumber(safe_call(function () return entity:GetClaimStatus(index); end, -1)) or -1,
        spawn_flags = tonumber(safe_call(function () return entity:GetSpawnFlags(index); end, 0)) or 0,
        name_color = tonumber(safe_call(function () return entity:GetNameColor(index); end, 0)) or 0,
    };
end

local function nav_player_position()
    local raw = safe_call(function () return GetPlayerEntity(); end, nil);
    local player_index = nav_player_index();
    local entity = safe_call(function () return AshitaCore:GetMemoryManager():GetEntity(); end, nil);
    local heading = raw ~= nil and tonumber(raw.Heading) or nil;
    if (heading == nil and entity ~= nil and player_index > 0) then
        heading = tonumber(safe_call(function () return entity:GetHeading(player_index); end, nil));
    end
    local pos = nil;
    if (raw ~= nil and raw.Movement ~= nil and raw.Movement.LocalPosition ~= nil) then
        pos = T{
            index = player_index,
            name = nav_clean_field(raw.Name or ''),
            zone = nav_zone_id(),
            x = tonumber(raw.Movement.LocalPosition.X) or 0,
            z = tonumber(raw.Movement.LocalPosition.Y) or 0,
            y = tonumber(raw.Movement.LocalPosition.Z) or 0,
            yaw = heading or tonumber(raw.Movement.LocalPosition.Yaw) or 0,
            server_id = tonumber(raw.ServerId) or 0,
        };
    end

    if (pos == nil or (pos.x == 0 and pos.z == 0)) then
        local fallback = nav_entity_position(player_index);
        if (fallback ~= nil and not (fallback.x == 0 and fallback.z == 0)) then
            fallback.yaw = heading or fallback.yaw;
            pos = fallback;
        elseif (pos ~= nil and pos.x == 0 and pos.z == 0) then
            return nil;
        end
    end
    if (pos ~= nil) then
        accessxi.nav_current_position = pos;
        accessxi.nav_position_seen = true;
    end
    return pos;
end

local function nav_cached_player_position()
    local zone = nav_zone_id();
    if (accessxi.nav_current_position ~= nil) then
        if (zone > 0 and (tonumber(accessxi.nav_current_position.zone) or 0) ~= zone) then
            accessxi.nav_reset_zone_state('cached-zone-mismatch', tonumber(accessxi.nav_current_position.zone) or 0, zone);
            accessxi.nav_current_position = nil;
            return nav_player_position();
        end
        return accessxi.nav_current_position;
    end
    return nav_player_position();
end

local function nav_position_log_key(pos)
    if (pos == nil) then
        return 'none';
    end

    return ('%d:%d:%d'):fmt(
        tonumber(pos.zone) or 0,
        math.floor(((tonumber(pos.x) or 0) + 2.5) / 5),
        math.floor(((tonumber(pos.z) or 0) + 2.5) / 5));
end

function accessxi.nav_collision_quiet(reason, duration_ms, now)
    now = tonumber(now) or tick();
    duration_ms = tonumber(duration_ms) or 4500;
    accessxi.nav_collision_quiet_until = math.max(tonumber(accessxi.nav_collision_quiet_until) or 0, now + duration_ms);
    accessxi.nav_collision_quiet_reason = tostring(reason or '');
    accessxi.nav_collision_require_fresh_movement = true;
    accessxi.nav_collision_freewalk_x = nil;
    accessxi.nav_collision_freewalk_z = nil;
    accessxi.nav_collision_freewalk_yaw = nil;
    accessxi.nav_collision_freewalk_tick = 0;
    accessxi.nav_collision_freewalk_last_sound_tick = 0;
    accessxi.nav_collision_freewalk_last_log_key = '';
    accessxi.nav_collision_route_contact_last_sound_tick = 0;
    accessxi.nav_collision_route_contact_last_log_key = '';
    accessxi.nav_collision_forward_intent_tick = 0;
    accessxi.nav_collision_forward_intent_key = 0;
    accessxi.nav_movement_recent_tick = 0;
    accessxi.nav_movement_last_move_count_tick = 0;
    accessxi.nav_movement_last_x = nil;
    accessxi.nav_movement_last_z = nil;
    accessxi.nav_movement_last_tick = 0;
end

function accessxi.nav_clear_zone_load_settle(reason)
    local had_settle = (tonumber(accessxi.nav_zone_load_settle_until) or 0) > 0;
    if (had_settle) then
        log_line(('nav zone load settle clear reason="%s" from=%d to=%d destination="%s"'):fmt(
            accessxi.escape_probe_log_text(tostring(reason or '')),
            tonumber(accessxi.nav_zone_load_settle_from_zone) or 0,
            tonumber(accessxi.nav_zone_load_settle_to_zone) or 0,
            accessxi.escape_probe_log_text(tostring(accessxi.nav_zone_load_settle_destination or ''))));
    end

    accessxi.nav_zone_load_settle_until = 0;
    accessxi.nav_zone_load_settle_start_tick = 0;
    accessxi.nav_zone_load_settle_reason = '';
    accessxi.nav_zone_load_settle_from_zone = 0;
    accessxi.nav_zone_load_settle_to_zone = 0;
    accessxi.nav_zone_load_settle_destination = '';
end

function accessxi.nav_begin_zone_load_settle(reason, from_zone, to_zone, destination, now)
    now = tonumber(now) or tick();
    local duration = tonumber(accessxi.nav_zone_load_settle_ms) or 8000;
    accessxi.nav_zone_load_settle_until = now + duration;
    accessxi.nav_zone_load_settle_start_tick = now;
    accessxi.nav_zone_load_settle_reason = tostring(reason or '');
    accessxi.nav_zone_load_settle_from_zone = tonumber(from_zone) or 0;
    accessxi.nav_zone_load_settle_to_zone = tonumber(to_zone) or 0;
    accessxi.nav_zone_load_settle_destination = tostring(destination or '');
    log_line(('nav zone load settle start reason="%s" from=%d to=%d destination="%s" ms=%d'):fmt(
        accessxi.escape_probe_log_text(tostring(reason or '')),
        tonumber(from_zone) or 0,
        tonumber(to_zone) or 0,
        accessxi.escape_probe_log_text(tostring(destination or '')),
        duration));
end

function accessxi.nav_clear_zoning_watch(reason)
    local had_watch = (tonumber(accessxi.nav_zoning_watch_until) or 0) > 0;
    local reason_key = tostring(reason or '');
    local from_zone = tonumber(accessxi.nav_zoning_watch_from_zone) or 0;
    local to_zone = tonumber(accessxi.nav_zoning_watch_to_zone) or 0;
    local destination = tostring(accessxi.nav_zoning_watch_destination or '');
    if (had_watch) then
        log_line(('nav zoning watch clear reason="%s" from=%d to=%d destination="%s"'):fmt(
            accessxi.escape_probe_log_text(reason_key),
            from_zone,
            to_zone,
            accessxi.escape_probe_log_text(destination)));
    end
    accessxi.nav_zoning_watch_until = 0;
    accessxi.nav_zoning_watch_reason = '';
    accessxi.nav_zoning_watch_from_zone = 0;
    accessxi.nav_zoning_watch_to_zone = 0;
    accessxi.nav_zoning_watch_destination = '';
    if (had_watch and reason_key == 'zone-change') then
        accessxi.nav_begin_zone_load_settle('zone-change', from_zone, to_zone, destination, tick());
    end
end

function accessxi.nav_begin_zoning_watch(reason, player, destination, now)
    now = tonumber(now) or tick();
    if (destination == nil) then
        return false;
    end

    local name = tostring(destination.name or '');
    local lower_name = name:lower();
    local to_zone = tonumber(destination.to_zone) or 0;
    if (to_zone <= 0 and lower_name:find('zone line', 1, true) == nil) then
        return false;
    end

    local duration = tonumber(accessxi.nav_zoning_watch_ms) or 25000;
    accessxi.nav_zoning_watch_until = now + duration;
    accessxi.nav_zoning_watch_reason = tostring(reason or '');
    accessxi.nav_zoning_watch_from_zone = tonumber(player ~= nil and player.zone or destination.zone) or 0;
    accessxi.nav_zoning_watch_to_zone = to_zone;
    accessxi.nav_zoning_watch_destination = name;
    accessxi.nav_collision_quiet(reason or 'zone-line-arrival', duration, now);
    log_line(('nav zoning watch start reason="%s" from=%d to=%d destination="%s" ms=%d'):fmt(
        accessxi.escape_probe_log_text(tostring(reason or '')),
        tonumber(accessxi.nav_zoning_watch_from_zone) or 0,
        tonumber(accessxi.nav_zoning_watch_to_zone) or 0,
        accessxi.escape_probe_log_text(name),
        duration));
    return true;
end

function accessxi.nav_zoning_watch_active(now)
    now = tonumber(now) or tick();
    local until_tick = tonumber(accessxi.nav_zoning_watch_until) or 0;
    if (until_tick <= 0) then
        return false;
    end
    if (now >= until_tick) then
        accessxi.nav_clear_zoning_watch('timeout');
        return false;
    end
    return true;
end

function accessxi.nav_observe_zone_load_packet(e, now)
    if (type(e) ~= 'table' or tonumber(e.id) ~= 0x00A) then
        return false;
    end
    accessxi.nav_zone_load_packet_tick = tonumber(now) or tick();
    return true;
end

function accessxi.nav_zone_load_settle_active(now)
    now = tonumber(now) or tick();
    local until_tick = tonumber(accessxi.nav_zone_load_settle_until) or 0;
    if (until_tick <= 0) then
        return false;
    end
    local started = tonumber(accessxi.nav_zone_load_settle_start_tick) or 0;
    local zone_packet = tonumber(accessxi.nav_zone_load_packet_tick) or 0;
    local minimum = tonumber(accessxi.nav_zone_load_settle_min_ms) or 750;
    if (started > 0 and zone_packet >= (started - 3000)
        and now >= (started + minimum)) then
        accessxi.nav_clear_zone_load_settle('zone-in-ready');
        return false;
    end
    if (now >= until_tick) then
        accessxi.nav_clear_zone_load_settle('timeout');
        return false;
    end
    return true;
end

function accessxi.nav_reset_zone_state(reason, old_zone, new_zone)
    local from_zone_id = tonumber(old_zone) or 0;
    local zone_id = tonumber(new_zone) or 0;
    local identity = type(accessxi.current_player_identity) == 'function'
        and tostring(accessxi.current_player_identity() or ''):lower() or '';
    local world_id = type(accessxi.current_player_world_id) == 'function'
        and (tonumber(accessxi.current_player_world_id()) or 0) or 0;
    local session_epoch = type(accessxi.current_objective_session_epoch) == 'function'
        and (tonumber(accessxi.current_objective_session_epoch()) or 0) or 0;
    if (from_zone_id > 0 and zone_id > 0 and from_zone_id ~= zone_id
        and identity ~= '' and world_id > 0 and session_epoch > 0
        and type(accessxi.nav_mission_quest_reduce_signal) == 'function') then
        if (tonumber(accessxi.objective_signal_session_epoch) ~= session_epoch) then
            accessxi.objective_signal_session_epoch = session_epoch;
            accessxi.objective_signal_sequence = 0;
        end
        local sequence = (tonumber(accessxi.objective_signal_sequence) or 0) + 1;
        accessxi.objective_signal_sequence = sequence;
        pcall(accessxi.nav_mission_quest_reduce_signal, {
            kind = 'committed-zone', from_zone_id = from_zone_id, zone_id = zone_id,
            target_server_id = tonumber(accessxi.objective_transport_target_server_id) or 0,
            menu_id = tonumber(accessxi.objective_transport_menu_id) or 0,
            transport_sequence = tonumber(accessxi.objective_transport_request_sequence),
            character_identity = identity, world_id = world_id,
            session_epoch = session_epoch, sequence = sequence, tick = tick(),
            corpus_revision = tonumber(accessxi.nav_catalog_revision) or 0,
        });
    end
    accessxi.objective_transport_target_server_id = nil;
    accessxi.objective_transport_menu_id = nil;
    accessxi.objective_transport_request_sequence = nil;
    if ((tonumber(new_zone) or 0) > 0) then
        accessxi.nav_last_seen_zone = tonumber(new_zone);
    end
    accessxi.nav_clear_zoning_watch('zone-change');
    if (type(accessxi.nav_mission_quest_clear_pending_interaction) == 'function') then
        accessxi.nav_mission_quest_clear_pending_interaction('zone-change');
    end
    if (accessxi.nav_dat_collision_state ~= nil) then
        accessxi.nav_dat_collision_state:cancel('zone-change');
    end
    accessxi.nav_dat_collision_pending = nil;
    accessxi.nav_dat_collision_preload_zone = 0;
    accessxi.nav_dat_collision_preload_last_tick = 0;
    if (type(accessxi.nav_transport_clear) == 'function') then
        accessxi.nav_transport_clear('zone-change');
    end
    if (type(accessxi.nav_dangruf_fount_drop_clear) == 'function') then
        accessxi.nav_dangruf_fount_drop_clear('zone-change');
    end
    accessxi.nav_current_position = nil;
    accessxi.nav_position_seen = false;
    accessxi.nav_active = false;
    accessxi.nav_destination = nil;
    accessxi.nav_route_start_point = nil;
    accessxi.nav_position_last_log_key = '';
    accessxi.nav_menu_open = false;
    accessxi.nav_menu_items:clear();
    accessxi.nav_menu_dirty_categories = {};
    accessxi.nav_menu_index = 1;
    accessxi.nav_menu_category = 1;
    accessxi.nav_menu_search_query = '';
    accessxi.nav_menu_search_results:clear();
    accessxi.nav_menu_search_result_query = '';
    accessxi.nav_menu_poll_key = 0;
    accessxi.nav_menu_poll_tick = 0;
    accessxi.nav_menu_open_tick = 0;
    if (type(accessxi.objective_guides) == 'table'
        and type(accessxi.objective_guides.close) == 'function') then
        accessxi.objective_guides:close('zone-change');
    end
    accessxi.nav_route_points:clear();
    accessxi.nav_route_point_index = 1;
    accessxi.nav_route_last_recalc_tick = 0;
    accessxi.nav_last_key = '';
    accessxi.nav_last_log = '';
    accessxi.nav_last_direction_text = '';
    accessxi.nav_beacon_last_key = '';
    accessxi.nav_beacon_last_tick = 0;
    accessxi.nav_beacon_reset_direction_state();
    accessxi.nav_progress_x = nil;
    accessxi.nav_progress_z = nil;
    accessxi.nav_progress_distance = 0;
    accessxi.nav_progress_tick = 0;
    accessxi.nav_progress_last_block_tick = 0;
    accessxi.nav_progress_last_log_key = '';
    accessxi.nav_collision_x = nil;
    accessxi.nav_collision_z = nil;
    accessxi.nav_collision_destination_distance = 0;
    accessxi.nav_collision_route_distance = 0;
    accessxi.nav_collision_tick = 0;
    accessxi.nav_collision_last_sound_tick = 0;
    accessxi.nav_collision_last_key = '';
    accessxi.nav_door_wait_until = 0;
    accessxi.nav_door_pause_until = 0;
    accessxi.nav_door_x = nil;
    accessxi.nav_door_z = nil;
    accessxi.nav_door_route_unit_x = nil;
    accessxi.nav_door_route_unit_z = nil;
    accessxi.nav_door_wait_key = '';
    accessxi.nav_door_wait_name = '';
    accessxi.nav_collision_quiet('zone-change', accessxi.nav_collision_zone_quiet_ms, tick());
    accessxi.nav_last_failure_key = '';
    accessxi.nav_last_failure_tick = 0;
    accessxi.nav_obstacle_last_key = '';
    accessxi.nav_obstacle_last_tick = 0;
    accessxi.nav_movement_blocking_menu_last_key = '';
    accessxi.nav_movement_blocking_menu_last_tick = 0;
    accessxi.nav_last_live_obstacle_tick = 0;
    accessxi.nav_last_live_obstacle_name = '';
    accessxi.nav_live_entity_seen = T{};
    accessxi.nav_wall_avoid_last_key = '';
    accessxi.nav_wall_avoid_last_tick = 0;
    accessxi.nav_mesh_loaded = false;
    accessxi.nav_mesh_zone = 0;
    if (ffxinav ~= nil and accessxi.nav_mesh_handle ~= nil) then
        pcall(function () ffxinav.DisposeFFXINavClass(accessxi.nav_mesh_handle); end);
        accessxi.nav_mesh_handle = nil;
    end
    log_line(('nav zone state reset reason="%s" old=%d new=%d'):fmt(reason or '', tonumber(old_zone) or 0, tonumber(new_zone) or 0));
end

function accessxi.nav_poll_zone_transition_only(now)
    now = tonumber(now) or tick();
    if ((now - (tonumber(accessxi.nav_zone_transition_last_tick) or 0)) < 200) then
        return;
    end
    accessxi.nav_zone_transition_last_tick = now;

    local zone = nav_zone_id();
    if (zone > 0 and accessxi.nav_last_seen_zone ~= 0 and accessxi.nav_last_seen_zone ~= zone) then
        accessxi.nav_reset_zone_state('poll-zone-change', accessxi.nav_last_seen_zone, zone);
    end
    if (zone > 0) then
        accessxi.nav_last_seen_zone = zone;
    end
end

local function poll_nav_position()
    local now = tick();
    if ((now - (accessxi.nav_position_last_tick or 0)) < 200) then
        return;
    end
    accessxi.nav_position_last_tick = now;

    local zone = nav_zone_id();
    if (zone > 0 and accessxi.nav_last_seen_zone ~= 0 and accessxi.nav_last_seen_zone ~= zone) then
        accessxi.nav_reset_zone_state('poll-zone-change', accessxi.nav_last_seen_zone, zone);
    end
    if (zone > 0) then
        accessxi.nav_last_seen_zone = zone;
    end

    local pos = nav_player_position();
    if (pos == nil) then
        if (accessxi.nav_position_seen) then
            accessxi.nav_position_seen = false;
            accessxi.nav_current_position = nil;
            log_line('nav position unavailable');
        end
        return;
    end

    local key = nav_position_log_key(pos);
    if (key ~= accessxi.nav_position_last_log_key and (now - (accessxi.nav_position_last_log_tick or 0)) >= 1500) then
        accessxi.nav_position_last_log_key = key;
        accessxi.nav_position_last_log_tick = now;
        log_line(('nav position zone=%d x=%.3f z=%.3f y=%.3f yaw=%.3f index=%d'):fmt(
            pos.zone or 0,
            pos.x or 0,
            pos.z or 0,
            pos.y or 0,
            pos.yaw or 0,
            pos.index or -1));
    end
end

local function nav_distance(a, b)
    if (a == nil or b == nil) then
        return 0;
    end
    local dx = (tonumber(b.x) or 0) - (tonumber(a.x) or 0);
    local dz = (tonumber(b.z) or 0) - (tonumber(a.z) or 0);
    return math.sqrt((dx * dx) + (dz * dz)), dx, dz;
end

local function nav_vertical_phrase(from_pos, to_pos)
    if (from_pos == nil or to_pos == nil) then
        return '';
    end

    local dy = (tonumber(to_pos.y) or 0) - (tonumber(from_pos.y) or 0);
    if (math.abs(dy) < 2.0) then
        return '';
    end
    if (dy > 0) then
        return (' Height up %.0f.'):fmt(math.abs(dy));
    end
    return (' Height down %.0f.'):fmt(math.abs(dy));
end

function accessxi.nav_normalize_angle(angle)
    local two_pi = math.pi * 2;
    angle = tonumber(angle) or 0;
    while (angle > math.pi) do
        angle = angle - two_pi;
    end
    while (angle < -math.pi) do
        angle = angle + two_pi;
    end
    return angle;
end

function accessxi.nav_atan2(y, x)
    if (math.atan2 ~= nil) then
        return math.atan2(y, x);
    end
    return math.atan(y, x);
end

function accessxi.nav_capitalize(text)
    text = tostring(text or '');
    return (text:gsub('^%l', string.upper));
end

function accessxi.nav_compass_direction(yaw)
    yaw = tonumber(yaw);
    if (yaw == nil) then
        return 'unknown';
    end
    if (math.abs(yaw) > (math.pi * 2.1)) then
        yaw = yaw * math.pi / 180;
    end
    yaw = -yaw;

    local directions = T{
        'east',
        'northeast',
        'north',
        'northwest',
        'west',
        'southwest',
        'south',
        'southeast',
    };
    local two_pi = math.pi * 2;
    local angle = yaw % two_pi;
    local index = math.floor((angle + (math.pi / 8)) / (math.pi / 4)) + 1;
    while (index > directions:len()) do
        index = index - directions:len();
    end
    return directions[index] or 'unknown';
end

function accessxi.nav_heading_to(from_pos, to_pos)
    if (from_pos == nil or to_pos == nil) then
        return nil;
    end

    local dx = (tonumber(to_pos.x) or 0) - (tonumber(from_pos.x) or 0);
    local dz = (tonumber(to_pos.z) or 0) - (tonumber(from_pos.z) or 0);
    if (math.abs(dx) < 0.001 and math.abs(dz) < 0.001) then
        return nil;
    end
    return accessxi.nav_atan2(dz, dx);
end

function accessxi.nav_relative_turn_phrase(delta)
    local degrees = math.abs(delta) * 180 / math.pi;
    if (degrees < 25) then
        return 'go straight';
    end

    local side = delta > 0 and 'left' or 'right';
    if (degrees < 160) then
        return 'turn ' .. side;
    end
    return 'turn around';
end

function accessxi.nav_facing_instruction(from_pos, to_pos)
    if (from_pos == nil or to_pos == nil) then
        return 'Position unavailable';
    end

    local target_heading = accessxi.nav_heading_to(from_pos, to_pos);
    if (target_heading == nil) then
        return 'You are on it';
    end

    local yaw = tonumber(from_pos.yaw);
    if (yaw == nil) then
        return 'Continue';
    end
    if (math.abs(yaw) > (math.pi * 2.1)) then
        yaw = yaw * math.pi / 180;
    end

    return accessxi.nav_relative_turn_phrase(accessxi.nav_normalize_angle(target_heading + yaw));
end

function accessxi.nav_next_turn_phrase(from_pos, route_target, next_target)
    if (from_pos == nil or route_target == nil or next_target == nil) then
        return '';
    end

    local inbound = accessxi.nav_heading_to(from_pos, route_target);
    local outbound = accessxi.nav_heading_to(route_target, next_target);
    if (inbound == nil or outbound == nil) then
        return '';
    end

    local delta = accessxi.nav_normalize_angle(outbound - inbound);
    local instruction = accessxi.nav_relative_turn_phrase(delta);
    if (instruction == 'go straight') then
        return ' Then go straight.';
    end

    return (' Then %s.'):fmt(instruction);
end

function accessxi.nav_guidance_phrase(from_pos, route_target, next_target, allow_on_it)
    if (from_pos == nil or route_target == nil) then
        return 'Position unavailable.', 0, 0, 0;
    end

    local distance, dx, dz = nav_distance(from_pos, route_target);
    if (distance <= 5) then
        if (allow_on_it ~= false) then
            return 'You are on it.', distance, dx, dz;
        end
        if (next_target ~= nil) then
            local next_distance = nav_distance(from_pos, next_target);
            if (next_distance <= 30
                and accessxi.nav_precise_beacon_lookahead_allowed(from_pos, route_target, next_target)) then
                route_target = next_target;
                distance, dx, dz = nav_distance(from_pos, route_target);
            end
        else
            return 'Continue.', distance, dx, dz;
        end
    end

    local instruction = accessxi.nav_facing_instruction(from_pos, route_target);
    local phrase = '';
    if (instruction == 'go straight') then
        phrase = ('Go straight %.0f yalms.'):fmt(distance);
    elseif (instruction == 'You are on it') then
        if (allow_on_it == false) then
            phrase = 'Continue.';
        else
            phrase = 'You are on it.';
        end
    elseif (instruction == 'Position unavailable') then
        phrase = 'Position unavailable.';
    else
        phrase = ('%s. Go straight %.0f yalms.'):fmt(accessxi.nav_capitalize(instruction), distance);
    end
    phrase = phrase .. nav_vertical_phrase(from_pos, route_target);
    return phrase, distance, dx, dz;
end

function accessxi.nav_arrival_radius(destination)
    if (destination == nil) then
        return 8;
    end
    local explicit = tonumber(destination.arrival_radius);
    if (explicit ~= nil and explicit >= 0.5 and explicit <= 20) then
        return explicit;
    end

    local name = tostring(destination.name or ''):lower();
    if (name == 'telepoint' and (tonumber(destination.zone) or 0) == 102) then
        return 3;
    end
    if (name:contains('zone line')) then
        return 8;
    end
    if (name:contains('mog house')) then
        return 2;
    end
    if (name:contains('entrance')) then
        return 4;
    end
    return 8;
end

function accessxi.nav_dat_collision_bootstrap()
    if accessxi.nav_dat_collision_state ~= nil then
        return true;
    end
    local collision_module = accessxi.load_module_table('collision_navigation', nil);
    local sha_module = accessxi.load_module_table('accessxi_sha256', nil);
    if (type(collision_module) ~= 'table' or type(collision_module.new) ~= 'function') then
        accessxi.nav_dat_collision_failure_reason = 'Collision terrain module is unavailable.';
        return false;
    end
    if (type(sha_module) ~= 'table' or type(sha_module.sha256) ~= 'function') then
        accessxi.nav_dat_collision_failure_reason = 'Collision terrain SHA-256 support is unavailable.';
        return false;
    end
    local ok, state, reason = pcall(collision_module.new, T{
        ffi = ffi,
        utf8_to_wide = utf8_to_wide,
        addon_root = accessxi_paths.addon_path(),
        manifest_path = accessxi_paths.addon_path('data', 'collision-native-manifest.tsv'),
        dll_path = accessxi_paths.addon_path('third_party', 'collision', 'accessxi_collision_native.dll'),
        sha256 = sha_module.sha256,
        ffxi_root = accessxi_paths.ffxi_root,
        cache_root = accessxi_paths.addon_path('cache', 'collision'),
        zone_name = function(zone)
            local name = safe_call(function ()
                return AshitaCore:GetResourceManager():GetString('zones.names', tonumber(zone) or 0);
            end, '');
            name = nav_clean_field(name);
            return name ~= '' and name or ('Zone %d'):fmt(tonumber(zone) or 0);
        end,
        arrival_radius = function(destination)
            return accessxi.nav_arrival_radius(destination);
        end,
    });
    if (not ok or type(state) ~= 'table') then
        accessxi.nav_dat_collision_failure_reason = tostring(ok and reason or state);
        log_line('collision terrain disabled: ' .. accessxi.escape_probe_log_text(accessxi.nav_dat_collision_failure_reason));
        return false;
    end
    accessxi.nav_dat_collision_state = state;
    accessxi.nav_dat_collision_failure_reason = '';
    log_line('collision terrain navigation ready');
    return true;
end

function accessxi.poll_nav_dat_collision_preload(now)
    now = tonumber(now) or tick();
    if (accessxi.nav_active == true or accessxi.nav_dat_collision_pending ~= nil) then
        return false;
    end
    if ((now - (tonumber(accessxi.nav_dat_collision_preload_last_tick) or 0)) < 500) then
        return false;
    end

    local player = nav_cached_player_position();
    local zone = tonumber(player ~= nil and player.zone) or 0;
    if (zone <= 0 or zone == 102
        or (tonumber(accessxi.nav_dat_collision_preload_zone) or 0) == zone) then
        return false;
    end
    accessxi.nav_dat_collision_preload_last_tick = now;
    accessxi.nav_dat_collision_preload_zone = zone;

    if (accessxi.nav_dat_collision_state == nil
        and not accessxi.nav_dat_collision_bootstrap()) then
        return false;
    end
    if (type(accessxi.nav_dat_collision_state) ~= 'table'
        or type(accessxi.nav_dat_collision_state.preload) ~= 'function') then
        log_line(('collision terrain preload unavailable zone=%d'):fmt(zone));
        return false;
    end

    local ok, started, mode, message = pcall(
        accessxi.nav_dat_collision_state.preload,
        accessxi.nav_dat_collision_state,
        zone);
    mode = tostring(mode or 'error');
    message = nav_clean_field(message);
    if (not ok) then
        message = tostring(started);
        started = nil;
        mode = 'error';
    end
    if (mode == 'busy') then
        return false;
    end

    if (started ~= true) then
        log_line(('collision terrain preload failed zone=%d reason="%s"'):fmt(
            zone,
            accessxi.escape_probe_log_text(message)));
        return false;
    end
    log_line(('collision terrain preload zone=%d mode=%s'):fmt(
        zone,
        accessxi.escape_probe_log_text(mode)));
    return true;
end

function accessxi.nav_dat_collision_destination_copy(point)
    if (type(accessxi.nav_copy_point) == 'function') then
        return accessxi.nav_copy_point(point);
    end
    return T{
        zone = tonumber(point ~= nil and point.zone) or 0,
        name = tostring(point ~= nil and point.name or ''),
        x = tonumber(point ~= nil and point.x),
        z = tonumber(point ~= nil and point.z),
        y = tonumber(point ~= nil and point.y),
        kind = tostring(point ~= nil and point.kind or ''),
        source = tostring(point ~= nil and point.source or ''),
        arrival_radius = tonumber(point ~= nil and point.arrival_radius),
        to_zone = tonumber(point ~= nil and point.to_zone),
        to_zone_name = tostring(point ~= nil and point.to_zone_name or ''),
        final_zone = tonumber(point ~= nil and point.final_zone),
        final_name = tostring(point ~= nil and point.final_name or ''),
        same_zone_reentry_step = tonumber(point ~= nil and point.same_zone_reentry_step),
        same_zone_reentry_edge_id = tonumber(point ~= nil and point.same_zone_reentry_edge_id),
    };
end

function accessxi.nav_dat_collision_prefer_smoother(player, point, points)
    if (type(accessxi.nav_collision_smoother_route) ~= 'function') then
        return points;
    end
    local ok, selected = pcall(accessxi.nav_collision_smoother_route, player, point, points);
    if (not ok) then
        log_line('collision terrain smoother corridor failed safely: '
            .. accessxi.escape_probe_log_text(selected));
        return points;
    end
    if (type(selected) ~= 'table' or #selected <= 1) then
        return points;
    end
    return selected;
end

function accessxi.nav_dat_collision_route(player, point)
    if (player == nil or point == nil
        or (tonumber(player.zone) or 0) <= 0
        or (tonumber(player.zone) or 0) ~= (tonumber(point.zone) or 0)) then
        return T{}, 'skip', '';
    end
    if (accessxi.nav_dat_collision_state == nil and not accessxi.nav_dat_collision_bootstrap()) then
        local reason = nav_clean_field(accessxi.nav_dat_collision_failure_reason);
        return T{}, 'error', reason ~= '' and reason or 'Collision terrain navigation is unavailable.';
    end
    local ok, points, mode, message = pcall(
        accessxi.nav_dat_collision_state.route,
        accessxi.nav_dat_collision_state,
        player,
        point);
    if (not ok) then
        return T{}, 'error', 'Collision terrain route failed: ' .. tostring(points);
    end
    mode = tostring(mode or 'error');
    message = nav_clean_field(message);
    if (mode == 'ready' and type(points) == 'table' and #points > 1) then
        local copied = T{};
        for _, waypoint in ipairs(points) do
            copied:append(T{
                zone = tonumber(waypoint.zone) or tonumber(point.zone) or 0,
                name = tostring(waypoint.name or 'Terrain waypoint'),
                x = tonumber(waypoint.x),
                z = tonumber(waypoint.z),
                y = tonumber(waypoint.y),
                kind = 'route',
                source = 'dat-collision',
            });
        end
        copied = accessxi.nav_dat_collision_prefer_smoother(player, point, copied);
        accessxi.nav_dat_collision_pending = nil;
        log_line(('collision terrain route destination="%s" zone=%d count=%d'):fmt(
            accessxi.escape_probe_log_text(point.name or ''),
            tonumber(point.zone) or 0,
            copied:len()));
        return copied, 'ready', '';
    end
    if (mode == 'pending') then
        accessxi.nav_dat_collision_pending = T{
            destination = accessxi.nav_dat_collision_destination_copy(point),
            message = message,
        };
        return T{}, 'pending', message;
    end
    accessxi.nav_dat_collision_pending = nil;
    return T{}, 'error', message ~= '' and message or 'No collision-safe route reaches this destination.';
end

function accessxi.nav_dat_collision_zoneline_approach(player, destination)
    if (player == nil or destination == nil
        or type(accessxi.nav_point_is_zoneline) ~= 'function'
        or not accessxi.nav_point_is_zoneline(destination)
        or type(accessxi.nav_zoneline_approach_candidates) ~= 'function'
        or type(accessxi.nav_append_final_zoneline_point) ~= 'function') then
        return T{}, 'skip', '';
    end

    local last_reason = '';
    for _, approach in ipairs(accessxi.nav_zoneline_approach_candidates(destination)) do
        local points, mode, message = accessxi.nav_dat_collision_route(player, approach);
        if (mode == 'ready' and points:len() > 1) then
            accessxi.nav_append_final_zoneline_point(points, destination);
            log_line(('collision terrain zoneline approach destination="%s" approach=(%.3f,%.3f,%.3f) count=%d'):fmt(
                accessxi.escape_probe_log_text(destination.name or ''),
                tonumber(approach.x) or 0,
                tonumber(approach.z) or 0,
                tonumber(approach.y) or 0,
                points:len()));
            return points, 'ready', '';
        end
        if (mode == 'pending') then
            return T{}, 'pending', nav_clean_field(message);
        end
        local reason = nav_clean_field(message);
        if (reason ~= '') then
            last_reason = reason;
        end
        if (reason == 'The generated walkable terrain has no connected corridor.'
            and type(accessxi.nav_dat_collision_state) == 'table'
            and type(accessxi.nav_dat_collision_state.route_zoneline_tail) == 'function') then
            local tail_ok, tail_points, tail_mode = pcall(
                accessxi.nav_dat_collision_state.route_zoneline_tail,
                accessxi.nav_dat_collision_state,
                player,
                approach,
                destination);
            if (tail_ok and tail_mode == 'ready'
                and type(tail_points) == 'table' and #tail_points > 1) then
                local copied = T{};
                for _, waypoint in ipairs(tail_points) do
                    copied:append(T{
                        zone = tonumber(waypoint.zone) or tonumber(destination.zone) or 0,
                        name = tostring(waypoint.name or 'Terrain waypoint'),
                        x = tonumber(waypoint.x),
                        z = tonumber(waypoint.z),
                        y = tonumber(waypoint.y),
                        kind = 'route',
                        source = 'dat-collision-zoneline-tail',
                    });
                end
                accessxi.nav_append_final_zoneline_point(copied, destination);
                log_line(('collision terrain zoneline tail recovered destination="%s" approach=(%.3f,%.3f,%.3f) count=%d'):fmt(
                    accessxi.escape_probe_log_text(destination.name or ''),
                    tonumber(approach.x) or 0,
                    tonumber(approach.z) or 0,
                    tonumber(approach.y) or 0,
                    copied:len()));
                return copied, 'ready', '';
            end
        end
    end

    return T{}, 'error', last_reason;
end

function accessxi.poll_nav_dat_collision(now)
    if (accessxi.nav_dat_collision_pending == nil or accessxi.nav_dat_collision_state == nil) then
        return false;
    end
    now = tonumber(now) or tick();
    if ((now - (tonumber(accessxi.nav_dat_collision_last_poll_tick) or 0)) < 200) then
        return true;
    end
    accessxi.nav_dat_collision_last_poll_tick = now;
    local player = nav_cached_player_position();
    local pending = accessxi.nav_dat_collision_pending;
    local destination = pending ~= nil and pending.destination or nil;
    if (player == nil or destination == nil
        or (tonumber(player.zone) or 0) ~= (tonumber(destination.zone) or 0)) then
        accessxi.nav_dat_collision_state:cancel('zone-change');
        accessxi.nav_dat_collision_pending = nil;
        return false;
    end
    local ok, points, mode, message = pcall(
        accessxi.nav_dat_collision_state.poll,
        accessxi.nav_dat_collision_state,
        player);
    if (not ok) then
        points, mode, message = nil, 'error', tostring(points);
    end
    if mode == 'pending' then
        return true;
    end
    accessxi.nav_dat_collision_pending = nil;
    if (mode ~= 'ready' or type(points) ~= 'table' or #points <= 1) then
        local approach_points, approach_mode, approach_message =
            accessxi.nav_dat_collision_zoneline_approach(player, destination);
        if (approach_mode == 'ready') then
            points, mode, message = approach_points, 'ready', '';
        elseif (approach_mode == 'pending') then
            return true;
        elseif (nav_clean_field(message) == '' and nav_clean_field(approach_message) ~= '') then
            message = approach_message;
        end
    end
    if mode ~= 'ready' or type(points) ~= 'table' or #points <= 1 then
        local text = nav_clean_field(message);
        text = text ~= '' and text or 'No collision-safe route reaches this destination.';
        accessxi.nav_active = false;
        accessxi.nav_destination = nil;
        accessxi.nav_route_points:clear();
        accessxi.nav_last_direction_text = text;
        speak(text);
        log_line('collision terrain route stopped: ' .. accessxi.escape_probe_log_text(text));
        return false;
    end
    local copied = T{};
    for _, waypoint in ipairs(points) do
        copied:append(T{
            zone = tonumber(waypoint.zone) or tonumber(destination.zone) or 0,
            name = tostring(waypoint.name or 'Terrain waypoint'),
            x = tonumber(waypoint.x),
            z = tonumber(waypoint.z),
            y = tonumber(waypoint.y),
            kind = 'route',
            source = 'dat-collision',
        });
    end
    copied = accessxi.nav_dat_collision_prefer_smoother(player, destination, copied);
    accessxi.nav_route_points = copied;
    accessxi.nav_route_point_index = accessxi.nav_first_route_index(player, copied, destination);
    accessxi.nav_route_last_recalc_tick = now;
    accessxi.nav_active = true;
    accessxi.nav_destination = destination;
    local text = ('Terrain map ready. Starting route to %s. %d waypoints.'):fmt(
        destination.name ~= '' and destination.name or 'destination', copied:len());
    accessxi.nav_last_direction_text = text;
    speak(text);
    log_line(('collision terrain automatic start destination="%s" zone=%d count=%d'):fmt(
        accessxi.escape_probe_log_text(destination.name or ''),
        tonumber(destination.zone) or 0,
        copied:len()));
    return false;
end

function accessxi.nav_route_lookahead_distance(player, destination)
    local distance = (player ~= nil and destination ~= nil) and nav_distance(player, destination) or 999999;
    local wall = accessxi.nav_wall_distance(player);
    local name = tostring(destination ~= nil and destination.name or ''):lower();

    if (name:contains('zone line') and distance <= 35) then
        return 5;
    end
    if (wall ~= nil and wall <= 1.5) then
        return 5;
    end
    if (wall ~= nil and wall <= 3.0) then
        return 7;
    end
    return 9;
end

function accessxi.nav_route_waypoint_arrival_radius(destination)
    local name = tostring(destination ~= nil and destination.name or ''):lower();
    if (name:contains('zone line')) then
        return 2;
    end
    return 6;
end

function accessxi.nav_first_route_index(from_pos, points, destination)
    local count = points ~= nil and points:len() or 0;
    if (count <= 1) then
        return 1;
    end

    local first = points[1] or T{};
    local precise_route_id = tostring(first.route_override_id or first.source or '');
    if (precise_route_id == 'dat-collision' or precise_route_id == 'lathine-navmesh') then
        return 2;
    end

    local radius = accessxi.nav_route_waypoint_arrival_radius(destination);
    for i = 2, count do
        local distance = nav_distance(from_pos, points[i]);
        if (distance > radius) then
            return i;
        end
    end

    return count;
end

function accessxi.nav_distance_to_segment(pos, a, b)
    if (pos == nil or a == nil or b == nil) then
        return 999999;
    end

    local px = tonumber(pos.x) or 0;
    local pz = tonumber(pos.z) or 0;
    local ax = tonumber(a.x) or 0;
    local az = tonumber(a.z) or 0;
    local bx = tonumber(b.x) or 0;
    local bz = tonumber(b.z) or 0;
    local vx = bx - ax;
    local vz = bz - az;
    local wx = px - ax;
    local wz = pz - az;
    local len2 = (vx * vx) + (vz * vz);
    local t = 0;
    if (len2 > 0.001) then
        t = ((wx * vx) + (wz * vz)) / len2;
        if (t < 0) then
            t = 0;
        elseif (t > 1) then
            t = 1;
        end
    end

    local cx = ax + (t * vx);
    local cz = az + (t * vz);
    local dx = px - cx;
    local dz = pz - cz;
    return math.sqrt((dx * dx) + (dz * dz));
end

function accessxi.nav_project_to_segment(pos, a, b)
    if (pos == nil or a == nil or b == nil) then
        return nil, 0, 999999;
    end

    local px = tonumber(pos.x) or 0;
    local pz = tonumber(pos.z) or 0;
    local ax = tonumber(a.x) or 0;
    local az = tonumber(a.z) or 0;
    local bx = tonumber(b.x) or 0;
    local bz = tonumber(b.z) or 0;
    local vx = bx - ax;
    local vz = bz - az;
    local wx = px - ax;
    local wz = pz - az;
    local len2 = (vx * vx) + (vz * vz);
    local t = 0;
    if (len2 > 0.001) then
        t = ((wx * vx) + (wz * vz)) / len2;
        if (t < 0) then
            t = 0;
        elseif (t > 1) then
            t = 1;
        end
    end

    local point = T{
        x = ax + (t * vx),
        z = az + (t * vz),
        y = (tonumber(a.y) or 0) + (t * ((tonumber(b.y) or 0) - (tonumber(a.y) or 0))),
        zone = pos.zone,
        name = 'route',
        kind = 'route',
        source = 'lookahead',
    };
    local dx = px - point.x;
    local dz = pz - point.z;
    return point, t, math.sqrt((dx * dx) + (dz * dz));
end

function accessxi.nav_route_live_match(pos, points, preferred_segment, first_segment, last_segment)
    local count = points ~= nil and points:len() or 0;
    if (pos == nil or count < 2) then
        return nil;
    end

    local py = tonumber(pos.y) or 0;
    local best = nil;
    local forward_best = nil;
    local preferred = nil;
    preferred_segment = math.floor(tonumber(preferred_segment) or 0);
    first_segment = math.max(1, math.floor(tonumber(first_segment) or 1));
    last_segment = math.min(count - 1, math.floor(tonumber(last_segment) or (count - 1)));
    for i = first_segment, last_segment do
        local projected, t, horizontal = accessxi.nav_project_to_segment(pos, points[i], points[i + 1]);
        if (projected ~= nil) then
            local vertical = math.abs(py - (tonumber(projected.y) or 0));
            local score = math.sqrt((horizontal * horizontal) + (vertical * vertical * 4));
            local candidate = T{
                segment = i,
                point = projected,
                t = t,
                horizontal = horizontal,
                vertical = vertical,
                score = score,
            };
            if (i == preferred_segment) then
                preferred = candidate;
            end
            if (best == nil
                or score < (best.score - 0.05)
                or (math.abs(score - best.score) <= 0.05 and i > best.segment)) then
                best = candidate;
            end
            if (preferred_segment > 0 and i >= preferred_segment
                and (forward_best == nil
                    or score < (forward_best.score - 0.05)
                    or (math.abs(score - forward_best.score) <= 0.05 and i > forward_best.segment))) then
                forward_best = candidate;
            end
        end
    end
    if (forward_best ~= nil
        and (tonumber(forward_best.horizontal) or 999999) <= 3.25
        and (tonumber(forward_best.vertical) or 999999) <= 2.0) then
        best = forward_best;
    end
    if (preferred ~= nil and best ~= nil and preferred.score <= (best.score + 0.5)) then
        return preferred;
    end
    return best;
end

function accessxi.nav_route_target_from_match(player, points, match, lookahead, smooth_lookahead, segment_bounded)
    local count = points ~= nil and points:len() or 0;
    if (player == nil or match == nil or match.point == nil or count < 2) then
        return nil;
    end
    if ((tonumber(match.horizontal) or 999999) > 6.0
        or (tonumber(match.vertical) or 999999) > 4.5) then
        return nil;
    end

    local segment = math.max(1, math.min(tonumber(match.segment) or 1, count - 1));
    local match_t = tonumber(match.t) or 0;
    if (not segment_bounded and not smooth_lookahead
        and (tonumber(match.horizontal) or 0) > 0.75
        and (match_t <= 0.05 or match_t >= 0.95)) then
        local exit_target = nil;
        if (match_t <= 0.05) then
            exit_target = points[segment + 1];
        else
            exit_target = points[segment + 2];
        end
        if (exit_target ~= nil) then
            local approach_x = (tonumber(match.point.x) or 0) - (tonumber(player.x) or 0);
            local approach_z = (tonumber(match.point.z) or 0) - (tonumber(player.z) or 0);
            local exit_x = (tonumber(exit_target.x) or 0) - (tonumber(match.point.x) or 0);
            local exit_z = (tonumber(exit_target.z) or 0) - (tonumber(match.point.z) or 0);
            local approach_length = math.sqrt((approach_x * approach_x) + (approach_z * approach_z));
            local exit_length = math.sqrt((exit_x * exit_x) + (exit_z * exit_z));
            if (approach_length > 0.001 and exit_length > 0.001) then
                local join_cosine = ((approach_x * exit_x) + (approach_z * exit_z))
                    / (approach_length * exit_length);
                local minimum_join_cosine = (tonumber(match.horizontal) or 0) > 3.25 and 0 or 0.70710678;
                if (join_cosine <= minimum_join_cosine) then
                    match.point.name = 'Recorded route join';
                    match.point.source = 'live-route-return';
                    return match.point;
                end
            end
        end
    end

    local remaining = math.max(0.5, tonumber(lookahead) or 5);
    local current = match.point;
    if (segment_bounded) then
        local target = points[segment + 1];
        local distance = nav_distance(current, target);
        if (distance >= remaining and distance > 0.001) then
            local ratio = remaining / distance;
            return T{
                zone = player.zone,
                name = 'Collision route steering target',
                x = (tonumber(current.x) or 0) + (ratio * ((tonumber(target.x) or 0) - (tonumber(current.x) or 0))),
                z = (tonumber(current.z) or 0) + (ratio * ((tonumber(target.z) or 0) - (tonumber(current.z) or 0))),
                y = (tonumber(current.y) or 0) + (ratio * ((tonumber(target.y) or 0) - (tonumber(current.y) or 0))),
                kind = 'route',
                source = 'dat-collision-segment-steering',
                route_override_id = 'dat-collision',
            };
        end
        return target;
    end
    for i = segment, count - 1 do
        local target = points[i + 1];
        local start_point = (i == segment) and current or points[i];
        local distance = nav_distance(start_point, target);
        if (distance >= remaining and distance > 0.001) then
            local ratio = remaining / distance;
            return T{
                zone = player.zone,
                name = 'Recorded route steering target',
                x = (tonumber(start_point.x) or 0) + (ratio * ((tonumber(target.x) or 0) - (tonumber(start_point.x) or 0))),
                z = (tonumber(start_point.z) or 0) + (ratio * ((tonumber(target.z) or 0) - (tonumber(start_point.z) or 0))),
                y = (tonumber(start_point.y) or 0) + (ratio * ((tonumber(target.y) or 0) - (tonumber(start_point.y) or 0))),
                kind = 'route',
                source = 'live-route-lookahead',
                route_override_id = target.route_override_id,
            };
        end

        remaining = remaining - distance;
        local next_target = points[i + 2];
        if (not smooth_lookahead and next_target ~= nil and nav_distance(player, target) > 0.75) then
            local in_x = (tonumber(target.x) or 0) - (tonumber(start_point.x) or 0);
            local in_z = (tonumber(target.z) or 0) - (tonumber(start_point.z) or 0);
            local out_x = (tonumber(next_target.x) or 0) - (tonumber(target.x) or 0);
            local out_z = (tonumber(next_target.z) or 0) - (tonumber(target.z) or 0);
            local in_length = math.sqrt((in_x * in_x) + (in_z * in_z));
            local out_length = math.sqrt((out_x * out_x) + (out_z * out_z));
            if (in_length > 0.001 and out_length > 0.001) then
                local turn_cosine = ((in_x * out_x) + (in_z * out_z)) / (in_length * out_length);
                if (turn_cosine < 0.70710678) then
                    return target;
                end
            end
        end
        current = target;
    end
    return points[count];
end

function accessxi.nav_precise_route_waypoint_passed(player, current_target, next_target)
    if (player == nil or current_target == nil or next_target == nil) then
        return false;
    end

    local projected, t, horizontal = accessxi.nav_project_to_segment(player, current_target, next_target);
    if (projected == nil or (tonumber(t) or 0) < 0.5 or (tonumber(horizontal) or 999999) > 1.5) then
        return false;
    end

    local vertical = math.abs((tonumber(player.y) or 0) - (tonumber(projected.y) or 0));
    if (vertical > 2.0) then
        return false;
    end

    return nav_distance(player, next_target) < nav_distance(player, current_target);
end

function accessxi.nav_precise_route_track_index(player, now)
    local count = accessxi.nav_route_points ~= nil and accessxi.nav_route_points:len() or 0;
    local index = tonumber(accessxi.nav_route_point_index) or 1;
    if (player == nil or count < 2 or index < 1 or index >= count
        or not accessxi.nav_route_precise_override_active(player, accessxi.nav_route_points)) then
        return false;
    end

    now = tonumber(now) or tick();
    if ((now - (tonumber(accessxi.nav_precise_route_track_tick) or 0)) < 50) then
        return false;
    end
    accessxi.nav_precise_route_track_tick = now;

    local match = accessxi.nav_route_live_match(
        player, accessxi.nav_route_points, math.max(1, index - 1));
    if (match == nil
        or (tonumber(match.horizontal) or 999999) > 6.0
        or (tonumber(match.vertical) or 999999) > 4.5) then
        return false;
    end

    local desired = math.min((tonumber(match.segment) or 1) + 1, count);
    local precise_route_id = accessxi.nav_route_points_override_id(accessxi.nav_route_points);
    if (desired == index and (accessxi.nav_route_points_are_collision(accessxi.nav_route_points)
        or precise_route_id == 'lathine-navmesh')) then
        local current_target = accessxi.nav_route_points[index];
        if (current_target ~= nil) then
            local horizontal = nav_distance(player, current_target);
            local vertical = math.abs((tonumber(player.y) or 0) - (tonumber(current_target.y) or 0));
            if (horizontal <= 1.5 and vertical <= 2.0) then
                desired = math.min(index + 1, count);
                accessxi.nav_precise_route_return_clear();
            end
        end
    end
    if (desired < index) then
        return false;
    end
    if desired == index then
        return false;
    end

    accessxi.nav_route_point_index = desired;
    local target = accessxi.nav_route_points[accessxi.nav_route_point_index];
    log_line(('nav precise match %d/%d player=(%.3f,%.3f,%.3f) target=(%.3f,%.3f,%.3f) off=%.2f vertical=%.2f'):fmt(
        accessxi.nav_route_point_index,
        count,
        tonumber(player.x) or 0,
        tonumber(player.z) or 0,
        tonumber(player.y) or 0,
        tonumber(target ~= nil and target.x) or 0,
        tonumber(target ~= nil and target.z) or 0,
        tonumber(target ~= nil and target.y) or 0,
        tonumber(match.horizontal) or 0,
        tonumber(match.vertical) or 0));
    return true;
end

function accessxi.nav_distance_to_route(pos, points)
    local count = points ~= nil and points:len() or 0;
    if (count == 0) then
        return 999999;
    end
    if (count == 1) then
        return nav_distance(pos, points[1]);
    end

    local best = 999999;
    for i = 1, count - 1 do
        local d = accessxi.nav_distance_to_segment(pos, points[i], points[i + 1]);
        if (d < best) then
            best = d;
        end
    end
    return best;
end

function accessxi.nav_route_position_delta(pos, points)
    local count = points ~= nil and points:len() or 0;
    if (pos == nil or count == 0) then
        return nil;
    end

    local py = tonumber(pos.y) or 0;
    if (count == 1) then
        local point = points[1];
        local horizontal = nav_distance(pos, point);
        local signed_vertical = py - (tonumber(point.y) or 0);
        return T{
            horizontal = horizontal,
            vertical = math.abs(signed_vertical),
            signed_vertical = signed_vertical,
            below = math.max(0, -signed_vertical),
            segment = 0,
            point = point,
        };
    end

    local best = nil;
    for i = 1, count - 1 do
        local projected, _, horizontal = accessxi.nav_project_to_segment(pos, points[i], points[i + 1]);
        if (projected ~= nil and (best == nil or horizontal < best.horizontal)) then
            local signed_vertical = py - (tonumber(projected.y) or 0);
            best = T{
                horizontal = horizontal,
                vertical = math.abs(signed_vertical),
                signed_vertical = signed_vertical,
                below = math.max(0, -signed_vertical),
                segment = i,
                point = projected,
            };
        end
    end

    return best;
end

function accessxi.nav_lathine_lower_ravine_position(pos)
    if (pos == nil or (tonumber(pos.zone) or 0) ~= 102) then
        return false;
    end

    local px = tonumber(pos.x) or 0;
    local pz = tonumber(pos.z) or 0;
    local py = tonumber(pos.y);
    if (py == nil) then
        return false;
    end
    return px >= -670 and px <= -585 and pz >= 200 and pz <= 350 and py <= 12.5;
end

function accessxi.nav_route_live_replan_reason(player, destination, points, delta)
    if (player == nil or destination == nil) then
        return '';
    end

    local route_id = accessxi.nav_route_points_override_id(points);
    if (route_id:startswith('lathine-recorded-survey-')) then
        return '';
    end
    local destination_name = tostring(destination.name or ''):lower();
    local destination_is_west = ((tonumber(destination.zone) or 0) == 102)
        and (destination_name:contains('west ronfaure') or nav_distance(destination, T{ x = -558.569, z = 688.049, y = -7.049, zone = 102 }) <= 6);

    if (destination_is_west and accessxi.nav_lathine_lower_ravine_position(player)
        and route_id ~= 'lathine-fallen-ravine-to-west-ronfaure-zoneline') then
        return 'lathine lower ravine live position';
    end

    local horizontal = delta ~= nil and (tonumber(delta.horizontal) or 0) or 0;
    local vertical = delta ~= nil and (tonumber(delta.vertical) or 0) or 0;
    if (horizontal > 18.0) then
        return 'route drift from live position';
    end

    if (vertical > 7.0 and horizontal <= 28.0) then
        return 'route layer changed';
    end

    return '';
end

function accessxi.nav_route_points_are_collision(points)
    return type(points) == 'table'
        and points[1] ~= nil
        and tostring(points[1].source or '') == 'dat-collision';
end

function accessxi.nav_nearest_route_segment(pos, points, first_segment, last_segment)
    local count = points ~= nil and points:len() or 0;
    if (count < 2) then
        return 0, 999999;
    end

    first_segment = math.max(1, math.floor(tonumber(first_segment) or 1));
    last_segment = math.min(count - 1, math.floor(tonumber(last_segment) or (count - 1)));
    if (first_segment > last_segment) then
        return 0, 999999;
    end

    local best_index = first_segment;
    local best_distance = 999999;
    for i = first_segment, last_segment do
        local distance = accessxi.nav_distance_to_segment(pos, points[i], points[i + 1]);
        if (distance < best_distance) then
            best_distance = distance;
            best_index = i;
        end
    end
    return best_index, best_distance;
end

function accessxi.nav_lookahead_target(pos, points, lookahead)
    local count = points ~= nil and points:len() or 0;
    if (pos == nil or count < 2) then
        return nil, nil;
    end

    local segment = accessxi.nav_nearest_route_segment(pos, points);
    if (segment <= 0) then
        return points[math.min(2, count)], points[math.min(3, count)];
    end

    local projected, t = accessxi.nav_project_to_segment(pos, points[segment], points[segment + 1]);
    if (projected == nil) then
        return points[math.min(segment + 1, count)], points[math.min(segment + 2, count)];
    end

    local remaining = tonumber(lookahead) or 18;
    local current = projected;
    for i = segment, count - 1 do
        local next_point = points[i + 1];
        local start_point = (i == segment) and current or points[i];
        local distance = nav_distance(start_point, next_point);
        if (distance >= remaining or i == count - 1) then
            local ratio = distance > 0.001 and math.min(1, remaining / distance) or 1;
            local target = T{
                x = (tonumber(start_point.x) or 0) + (ratio * ((tonumber(next_point.x) or 0) - (tonumber(start_point.x) or 0))),
                z = (tonumber(start_point.z) or 0) + (ratio * ((tonumber(next_point.z) or 0) - (tonumber(start_point.z) or 0))),
                y = (tonumber(start_point.y) or 0) + (ratio * ((tonumber(next_point.y) or 0) - (tonumber(start_point.y) or 0))),
                zone = pos.zone,
                name = 'route',
                kind = 'route',
                source = 'lookahead',
            };
            return target, next_point;
        end
        remaining = remaining - distance;
    end

    return points[count], nil;
end

function accessxi.nav_indexed_lookahead_target(pos, points, lookahead)
    local count = points ~= nil and points:len() or 0;
    if (pos == nil or count < 2) then
        return nil, nil;
    end

    local index = tonumber(accessxi.nav_route_point_index) or 1;
    if (index < 2) then
        index = 2;
    elseif (index > count) then
        index = count;
    end

    local segment = index - 1;
    local projected = accessxi.nav_project_to_segment(pos, points[segment], points[index]);
    if (projected == nil) then
        projected = pos;
    end

    local remaining = tonumber(lookahead) or 12;
    local current = projected;
    for i = segment, count - 1 do
        local next_point = points[i + 1];
        local start_point = (i == segment) and current or points[i];
        local distance = nav_distance(start_point, next_point);
        if (distance >= remaining or i == count - 1) then
            local ratio = distance > 0.001 and math.min(1, remaining / distance) or 1;
            local target = T{
                x = (tonumber(start_point.x) or 0) + (ratio * ((tonumber(next_point.x) or 0) - (tonumber(start_point.x) or 0))),
                z = (tonumber(start_point.z) or 0) + (ratio * ((tonumber(next_point.z) or 0) - (tonumber(start_point.z) or 0))),
                y = (tonumber(start_point.y) or 0) + (ratio * ((tonumber(next_point.y) or 0) - (tonumber(start_point.y) or 0))),
                zone = pos.zone,
                name = 'route',
                kind = 'route',
                source = 'indexed-lookahead',
            };
            return target, next_point;
        end
        remaining = remaining - distance;
    end

    return points[count], nil;
end

function accessxi.nav_sync_route_index(pos)
    local count = accessxi.nav_route_points ~= nil and accessxi.nav_route_points:len() or 0;
    if (pos == nil or count < 2) then
        return;
    end

    if (accessxi.nav_route_precise_override_active(pos, accessxi.nav_route_points)) then
        return;
    end

    local first_segment = nil;
    local last_segment = nil;
    if (accessxi.nav_route_points_are_collision(accessxi.nav_route_points)) then
        local current = math.max(2, math.min(
            tonumber(accessxi.nav_route_point_index) or 2,
            count));
        first_segment = math.max(1, current - 2);
        last_segment = math.min(count - 1, current + 1);
    end
    local segment, segment_distance = accessxi.nav_nearest_route_segment(
        pos, accessxi.nav_route_points, first_segment, last_segment);
    if (segment <= 0) then
        return;
    end
    if (accessxi.nav_route_points_are_override(accessxi.nav_route_points)
        and (tonumber(segment_distance) or 999999) > 3.0) then
        return;
    end

    local desired = math.min(segment + 1, count);
    if (desired > (accessxi.nav_route_point_index or 1)) then
        accessxi.nav_route_point_index = desired;
    end
end

local function nav_route_phrase(from_pos, to_pos)
    if (from_pos == nil or to_pos == nil) then
        return 'Position unavailable.', 0, 0, 0;
    end

    local distance, dx, dz = nav_distance(from_pos, to_pos);
    local pieces = T{};
    local x_text = nav_axis_delta(dx, 'X');
    local z_text = nav_axis_delta(dz, 'Z');
    if (x_text ~= '') then
        pieces:append(x_text);
    end
    if (z_text ~= '') then
        pieces:append(z_text);
    end

    local offset = pieces:len() > 0 and ('. ' .. pieces:concat(', ') .. '.') or '. You are on it.';
    offset = offset .. nav_vertical_phrase(from_pos, to_pos);
    return ('%.0f yalms%s'):fmt(distance, offset), distance, dx, dz;
end

accessxi.nav_file_exists = function (path)
    local f = io.open(path, 'rb');
    if (f == nil) then
        return false;
    end
    f:close();
    return true;
end

accessxi.nav_zone_resource_name = function (zone)
    zone = tonumber(zone) or 0;
    if (zone <= 0) then
        return '';
    end

    local resource = safe_call(function () return AshitaCore:GetResourceManager():GetString('zones.names', zone); end, '');
    return nav_clean_field(resource);
end

accessxi.nav_mesh_filename_from_zone_name = function (name)
    name = nav_clean_field(name);
    if (name == '') then
        return '';
    end

    local mesh = name:gsub("'", ''):gsub('[^A-Za-z0-9%[%]]+', '_'):gsub('_+', '_'):gsub('^_', ''):gsub('_$', '');
    if (mesh == '') then
        return '';
    end
    return mesh .. '.nav';
end

local function nav_mesh_name_for_zone(zone)
    zone = tonumber(zone) or 0;
    if (zone <= 0) then
        return nil;
    end

    local explicit = accessxi.navigation_data.mesh_names[zone];
    if (explicit ~= nil and explicit ~= '') then
        return explicit;
    end

    local cached = accessxi.nav_mesh_name_cache[zone];
    if (cached ~= nil and cached ~= '') then
        return cached;
    end

    local zone_name = accessxi.nav_zone_resource_name(zone);
    local derived = accessxi.nav_mesh_filename_from_zone_name(zone_name);
    if (derived ~= '' and accessxi.nav_file_exists(accessxi.nav_mesh_dir .. '\\' .. derived)) then
        accessxi.nav_mesh_name_cache[zone] = derived;
        log_line(('navmesh autodetected zone=%d name="%s" mesh="%s"'):fmt(zone, zone_name, derived));
        return derived;
    end

    return nil;
end

local function nav_mesh_position(pos)
    return ffi.new('NavPositionT', {
        X = tonumber(pos.x) or 0,
        Y = tonumber(pos.y) or 0,
        Z = tonumber(pos.z) or 0,
    });
end

local function nav_try_load_mesh(zone)
    local function objective_observe(name, ...)
        local observer = accessxi[name];
        if (type(observer) ~= 'function') then
            if (type(accessxi.nav_objective_native_mark_untrusted) == 'function') then
                pcall(accessxi.nav_objective_native_mark_untrusted,
                    'Objective native observer is unavailable before ' .. name .. '.');
            end
            return false;
        end
        local ok, trusted = pcall(observer, ...);
        if (not ok or trusted ~= true) then
            if (type(accessxi.nav_objective_native_mark_untrusted) == 'function') then
                pcall(accessxi.nav_objective_native_mark_untrusted,
                    not ok and tostring(trusted) or ('Objective native observer rejected ' .. name .. '.'));
            end
            return false;
        end
        return true;
    end

    zone = tonumber(zone) or 0;
    if (zone <= 0) then
        return false;
    end
    if (accessxi.nav_mesh_loaded and accessxi.nav_mesh_zone == zone and accessxi.nav_mesh_handle ~= nil) then
        objective_observe('nav_objective_native_revalidate_loaded_mesh', zone);
        return true;
    end

    local mesh_name = nav_mesh_name_for_zone(zone);
    if (mesh_name == nil) then
        accessxi.nav_mesh_loaded = false;
        accessxi.nav_mesh_zone = 0;
        return false;
    end

    if (ffxinav == nil) then
        objective_observe('nav_objective_native_before_dll_load', accessxi.nav_mesh_dll_path);
        local ok, lib = pcall(ffi.load, accessxi.nav_mesh_dll_path);
        if (not ok or lib == nil) then
            if (type(accessxi.nav_objective_native_mark_untrusted) == 'function') then
                pcall(accessxi.nav_objective_native_mark_untrusted, 'FFXINAV DLL load failed.');
            end
            accessxi.nav_mesh_available = false;
            log_line('navmesh dll unavailable: ' .. tostring(lib));
            return false;
        end
        ffxinav = lib;
        accessxi.nav_mesh_available = true;
    end

    if (accessxi.nav_mesh_handle == nil) then
        local handle = ffxinav.CreateFFXINavClass();
        if (handle == nil) then
            return false;
        end
        accessxi.nav_mesh_handle = handle;
    end

    local path = accessxi.nav_mesh_dir .. '\\' .. mesh_name;
    local wide_path = utf8_to_wide(path);
    if (wide_path == nil) then
        accessxi.nav_mesh_loaded = false;
        accessxi.nav_mesh_zone = 0;
        log_line(('navmesh load zone=%d mesh="%s" failed to convert path'):fmt(zone, path));
        return false;
    end
    objective_observe('nav_objective_native_before_mesh_load', zone, mesh_name, path);
    local ok, loaded = pcall(function () return ffxinav.LoadMesh(accessxi.nav_mesh_handle, wide_path); end);
    accessxi.nav_mesh_loaded = ok and loaded;
    accessxi.nav_mesh_zone = accessxi.nav_mesh_loaded and zone or 0;
    if (not accessxi.nav_mesh_loaded
        and type(accessxi.nav_objective_native_mark_untrusted) == 'function') then
        pcall(accessxi.nav_objective_native_mark_untrusted, 'FFXINAV LoadMesh failed.');
    end
    log_line(('navmesh load zone=%d mesh="%s" ok=%s loaded=%s'):fmt(zone, path, tostring(ok), tostring(loaded)));
    return accessxi.nav_mesh_loaded;
end

function accessxi.nav_objective_native_handle()
    if (ffxinav == nil or accessxi.nav_mesh_handle == nil or accessxi.nav_mesh_loaded ~= true) then
        error('The observer-attested objective navmesh handle is unavailable.');
    end
    return accessxi.nav_mesh_handle;
end

function accessxi.nav_objective_native_is_valid_position(point)
    local handle = accessxi.nav_objective_native_handle();
    local position = nav_mesh_position(point);
    return ffxinav.IsValidPosition(handle, position, false) == true;
end

function accessxi.nav_objective_native_get_distance_to_wall(point)
    local handle = accessxi.nav_objective_native_handle();
    local position = nav_mesh_position(point);
    return tonumber(ffxinav.GetDistanceToWall(handle, position));
end

function accessxi.nav_objective_native_find_path(start_point, end_point)
    local handle = accessxi.nav_objective_native_handle();
    local start_position = nav_mesh_position(start_point);
    local end_position = nav_mesh_position(end_point);
    ffxinav.FindPath(handle, start_position, end_position, false);
    return true;
end

function accessxi.nav_objective_native_get_waypoints(maximum)
    local handle = accessxi.nav_objective_native_handle();
    maximum = tonumber(maximum) or 0;
    if (maximum < 2 or maximum ~= math.floor(maximum)) then
        error('The objective waypoint limit is invalid.');
    end
    local pointer = ffi.new('NavPositionT*[1]');
    local count = tonumber(ffxinav.Get_WayPoints(handle, pointer));
    if (count == nil or count < 0 or count ~= math.floor(count)) then
        error('FFXINAV returned a malformed waypoint count.');
    end
    if (count > maximum) then
        error('FFXINAV returned more waypoints than the rooted policy permits.');
    end
    if (count == 0) then
        return {};
    end
    if (pointer[0] == nil) then
        error('FFXINAV returned a null waypoint pointer.');
    end
    local points = {};
    for index = 0, count - 1 do
        local point = pointer[0][index];
        points[#points + 1] = {
            x = tonumber(point.X),
            y = tonumber(point.Y),
            z = tonumber(point.Z),
        };
    end
    return points;
end

function accessxi.nav_compute_exact_objective_leg(request)
    if (type(request) ~= 'table'
        or nav_clean_field(request.objective_route_contract_id) == '') then
        return nil, 'Verified objective route authorization is incomplete.';
    end
    if (type(accessxi.ensure_objective_route_runtime) ~= 'function') then
        return nil, 'Verified objective route execution is unavailable.';
    end
    local runtime_ready, runtime_reason = accessxi.ensure_objective_route_runtime();
    if (runtime_ready ~= true) then
        return nil, nav_clean_field(runtime_reason) ~= '' and nav_clean_field(runtime_reason)
            or 'Verified objective route execution is unavailable.';
    end
    local runtime = accessxi.objective_route_runtime;
    if (type(runtime) ~= 'table' or type(runtime.compute_exact_objective_leg) ~= 'function') then
        return nil, nav_clean_field(accessxi.objective_route_runtime_failure_reason)
            ~= '' and nav_clean_field(accessxi.objective_route_runtime_failure_reason)
            or 'Verified objective route execution is unavailable.';
    end
    local ok, points, reason, evidence = pcall(
        runtime.compute_exact_objective_leg,
        runtime,
        request);
    if (not ok) then
        return nil, 'Verified objective route execution failed safely.';
    end
    return points, reason, evidence;
end

local function nav_compute_mesh_route(start_pos, end_pos, quiet)
    local points = T{};
    if (start_pos == nil or end_pos == nil or (tonumber(start_pos.zone) or 0) ~= (tonumber(end_pos.zone) or 0)) then
        return points;
    end

    if (not nav_try_load_mesh(start_pos.zone)) then
        return points;
    end

    local start = nav_mesh_position(start_pos);
    local finish = nav_mesh_position(end_pos);
    local ok = pcall(function ()
        ffxinav.FindClosestPath(accessxi.nav_mesh_handle, start, finish, false);
    end);
    if (not ok) then
        return points;
    end

    local ptr = ffi.new('NavPositionT*[1]');
    local count = tonumber(ffxinav.Get_WayPoints(accessxi.nav_mesh_handle, ptr)) or 0;
    if (count <= 0) then
        pcall(function () ffxinav.FindPath(accessxi.nav_mesh_handle, start, finish, false); end);
        count = tonumber(ffxinav.Get_WayPoints(accessxi.nav_mesh_handle, ptr)) or 0;
    end

    if (not quiet) then
        log_line(('navmesh route zone=%d start=(%.3f,%.3f,%.3f) end=(%.3f,%.3f,%.3f) count=%d'):fmt(
            start_pos.zone or 0,
            start_pos.x or 0,
            start_pos.z or 0,
            start_pos.y or 0,
            end_pos.x or 0,
            end_pos.z or 0,
            end_pos.y or 0,
            count));
    end

    if (count <= 0 or ptr[0] == nil) then
        return points;
    end

    for i = 0, math.min(count - 1, 96) do
        local p = ptr[0][i];
        points:append(T{
            zone = start_pos.zone,
            name = ('Waypoint %d'):fmt(i + 1),
            x = tonumber(p.X) or 0,
            y = tonumber(p.Y) or 0,
            z = tonumber(p.Z) or 0,
            kind = 'route',
            source = 'navmesh',
        });
    end

    local quarantine = accessxi.nav_route_quarantine_reason(points, end_pos);
    if (quarantine ~= '') then
        accessxi.nav_route_last_reject_reason = quarantine;
        if (not quiet) then
            log_line(('navmesh route rejected zone=%d destination="%s" quarantine="%s" count=%d'):fmt(
                start_pos.zone or 0,
                end_pos.name or '',
                accessxi.escape_probe_log_text(quarantine),
                points:len()));
        end
        points:clear();
        return points;
    end
    return points;
end

function accessxi.nav_collision_smoother_route(player, destination, collision_points)
    if (type(collision_points) ~= 'table' or #collision_points < 5
        or type(accessxi.nav_dat_collision_state) ~= 'table'
        or type(accessxi.nav_dat_collision_state.validate_direct_route) ~= 'function'
        or (tonumber(player ~= nil and player.zone) or 0) == 102) then
        return collision_points;
    end

    local function copy_point(point)
        return T{
            zone = tonumber(point ~= nil and point.zone) or 0,
            name = tostring(point ~= nil and point.name or 'Terrain waypoint'),
            x = tonumber(point ~= nil and point.x) or 0,
            z = tonumber(point ~= nil and point.z) or 0,
            y = tonumber(point ~= nil and point.y) or 0,
            kind = 'route',
            source = 'dat-collision',
        };
    end

    local function horizontal_distance(first, second)
        local dx = (tonumber(second ~= nil and second.x) or 0)
            - (tonumber(first ~= nil and first.x) or 0);
        local dz = (tonumber(second ~= nil and second.z) or 0)
            - (tonumber(first ~= nil and first.z) or 0);
        return math.sqrt((dx * dx) + (dz * dz));
    end

    local function append_distinct(points, point)
        local copied = copy_point(point);
        local previous = points[#points];
        if (previous == nil or horizontal_distance(previous, copied) >= 0.01) then
            points:append(copied);
        end
    end

    local function normalized(points)
        local result = T{};
        for _, point in ipairs(points or {}) do
            append_distinct(result, point);
        end
        return result;
    end

    local function metrics(points)
        local length = 0;
        local maximum_turn = 0;
        local cumulative_turn = 0;
        for index = 2, #points do
            length = length + horizontal_distance(points[index - 1], points[index]);
        end
        for index = 2, #points - 1 do
            local incoming = accessxi.nav_atan2(
                (tonumber(points[index].z) or 0) - (tonumber(points[index - 1].z) or 0),
                (tonumber(points[index].x) or 0) - (tonumber(points[index - 1].x) or 0));
            local outgoing = accessxi.nav_atan2(
                (tonumber(points[index + 1].z) or 0) - (tonumber(points[index].z) or 0),
                (tonumber(points[index + 1].x) or 0) - (tonumber(points[index].x) or 0));
            local turn = math.abs(accessxi.nav_normalize_angle(outgoing - incoming));
            if (turn > maximum_turn) then maximum_turn = turn; end
            cumulative_turn = cumulative_turn + turn;
        end
        return length, maximum_turn, cumulative_turn;
    end

    local collision = normalized(collision_points);
    local collision_length, collision_turn, collision_cumulative_turn = metrics(collision);
    local severe_turn = 75 * math.pi / 180;
    if (collision_turn < severe_turn) then
        return collision_points;
    end

    local mesh_ok, mesh_points = pcall(nav_compute_mesh_route, player, destination, true);
    if (not mesh_ok or type(mesh_points) ~= 'table' or #mesh_points < 2) then
        return collision_points;
    end
    local mesh = normalized(mesh_points);
    local candidates = {};
    local minimum_turn_gain = 15 * math.pi / 180;
    for collision_index = 2, #collision - 1 do
        for mesh_index = 2, #mesh - 1 do
            local bridge_length = horizontal_distance(
                collision[collision_index], mesh[mesh_index]);
            local vertical_gap = math.abs(
                (tonumber(collision[collision_index].y) or 0)
                - (tonumber(mesh[mesh_index].y) or 0));
            if (bridge_length <= 6.0 and vertical_gap <= 1.5) then
                local candidate = T{};
                for index = 1, collision_index do
                    append_distinct(candidate, collision[index]);
                end
                for index = mesh_index, #mesh do
                    append_distinct(candidate, mesh[index]);
                end
                local length, maximum_turn, cumulative_turn = metrics(candidate);
                if (length <= collision_length - 1.0
                    and maximum_turn <= collision_turn - minimum_turn_gain
                    and cumulative_turn <= collision_cumulative_turn * 0.80) then
                    candidates[#candidates + 1] = {
                        collision_index = collision_index,
                        mesh_index = mesh_index,
                        length = length,
                        maximum_turn = maximum_turn,
                        cumulative_turn = cumulative_turn,
                    };
                end
            end
        end
    end
    table.sort(candidates, function(first, second)
        if (math.abs(first.cumulative_turn - second.cumulative_turn) > 0.0001) then
            return first.cumulative_turn < second.cumulative_turn;
        end
        if (math.abs(first.maximum_turn - second.maximum_turn) > 0.0001) then
            return first.maximum_turn < second.maximum_turn;
        end
        if (math.abs(first.length - second.length) > 0.0001) then
            return first.length < second.length;
        end
        if (first.collision_index ~= second.collision_index) then
            return first.collision_index < second.collision_index;
        end
        return first.mesh_index < second.mesh_index;
    end);

    for _, entry in ipairs(candidates) do
        local bridge_start = collision[entry.collision_index];
        local bridge_end = mesh[entry.mesh_index];
        local bridge_ok, bridge_points = pcall(
            nav_compute_mesh_route, bridge_start, bridge_end, true);
        if (bridge_ok and type(bridge_points) == 'table') then
            local bridge = normalized(bridge_points);
            if (#bridge == 2
                and horizontal_distance(bridge[1], bridge_start) <= 0.25
                and horizontal_distance(bridge[2], bridge_end) <= 0.25) then
                local candidate = T{};
                for index = 1, entry.collision_index do
                    append_distinct(candidate, collision[index]);
                end
                append_distinct(candidate, bridge[2]);
                for index = entry.mesh_index + 1, #mesh do
                    append_distinct(candidate, mesh[index]);
                end
                local length, maximum_turn, cumulative_turn = metrics(candidate);
                local valid_ok, clear, reason = pcall(
                    accessxi.nav_dat_collision_state.validate_direct_route,
                    accessxi.nav_dat_collision_state,
                    candidate);
                if (valid_ok and clear == true
                    and length <= collision_length - 1.0
                    and maximum_turn <= collision_turn - minimum_turn_gain
                    and cumulative_turn <= collision_cumulative_turn * 0.80) then
                    log_line(('collision terrain smoother corridor selected '
                        .. 'collision_count=%d hybrid_count=%d collision_length=%.2f '
                        .. 'hybrid_length=%.2f collision_turn=%.1f hybrid_turn=%.1f '
                        .. 'collision_cumulative_turn=%.1f hybrid_cumulative_turn=%.1f'):fmt(
                        #collision,
                        #candidate,
                        collision_length,
                        length,
                        collision_turn * 180 / math.pi,
                        maximum_turn * 180 / math.pi,
                        collision_cumulative_turn * 180 / math.pi,
                        cumulative_turn * 180 / math.pi));
                    return candidate;
                end
                if (valid_ok and nav_clean_field(reason) ~= '') then
                    accessxi.nav_route_last_reject_reason = nav_clean_field(reason);
                end
            end
        end
    end
    return collision_points;
end

function accessxi.nav_compute_mesh_endpoint_approach(player, point)
    local empty = T{};
    if (player == nil or point == nil or (tonumber(player.zone) or 0) ~= (tonumber(point.zone) or 0)) then
        return empty, nil;
    end

    local arrival_radius = tonumber(accessxi.nav_arrival_radius(point)) or 0;
    local radii = { 1.5, 2.5, 4.0, 6.0 };
    for _, radius in ipairs(radii) do
        if (radius < arrival_radius) then
            local best_route = nil;
            local best_approach = nil;
            local best_length = nil;
            for direction = 0, 7 do
                local angle = (-math.pi / 2) + (direction * (math.pi / 4));
                local candidate = T{
                    zone = tonumber(point.zone) or 0,
                    name = ('%s approach'):fmt(point.name or 'Destination'),
                    x = (tonumber(point.x) or 0) + (math.cos(angle) * radius),
                    z = (tonumber(point.z) or 0) + (math.sin(angle) * radius),
                    y = tonumber(point.y) or 0,
                    kind = point.kind,
                    source = 'navmesh-endpoint-approach',
                };
                local candidate_route = nav_compute_mesh_route(player, candidate);
                if (candidate_route:len() > 1) then
                    local route_length = 0;
                    for i = 2, candidate_route:len() do
                        route_length = route_length + nav_distance(candidate_route[i - 1], candidate_route[i]);
                    end
                    if (best_route == nil or route_length < best_length) then
                        best_route = candidate_route;
                        best_approach = candidate;
                        best_length = route_length;
                    end
                end
            end

            if (best_route ~= nil) then
                for _, route_point in ipairs(best_route) do
                    route_point.source = 'navmesh-endpoint-approach';
                    route_point.endpoint_approach_name = point.name or '';
                end
                accessxi.nav_route_last_reject_reason = '';
                log_line(('navmesh endpoint approach destination="%s" radius=%.1f approach=(%.3f,%.3f,%.3f) count=%d'):fmt(
                    point.name or '',
                    radius,
                    best_approach.x or 0,
                    best_approach.z or 0,
                    best_approach.y or 0,
                    best_route:len()));
                return best_route, best_approach;
            end
        end
    end

    return empty, nil;
end

function accessxi.nav_area_point_reachable(player, point)
    if (player == nil or point == nil) then
        return true;
    end
    if ((tonumber(player.zone) or 0) ~= (tonumber(point.zone) or 0)) then
        return false;
    end
    local distance = nav_distance(player, point);
    if (distance <= accessxi.nav_arrival_radius(point)) then
        return true;
    end

    local route = nav_compute_mesh_route(player, point);
    if (route == nil or route:len() <= 1) then
        return false;
    end

    local last = route[route:len()];
    return nav_distance(last, point) <= math.max(12, accessxi.nav_arrival_radius(point) * 3);
end

function accessxi.nav_area_point_direct_route_allowed(player, point)
    if (player == nil or point == nil) then
        return false;
    end
    if ((tonumber(player.zone) or 0) ~= (tonumber(point.zone) or 0)) then
        return false;
    end
    local name = tostring(point.name or ''):lower();
    local source = tostring(point.source or ''):lower();
    local confidence = tostring(point.confidence or ''):lower();
    local direct_known_area = name:contains('zone line') or source:contains('zoneline')
        or (name:contains('mog house') and source:contains('live-verified') and confidence:contains('proven'));
    if (not direct_known_area) then
        return false;
    end
    return nav_distance(player, point) <= 35;
end

function accessxi.nav_nearby_zoneline_direct_route_allowed(player, point)
    if (not accessxi.nav_point_is_zoneline(point) or not accessxi.nav_area_point_direct_route_allowed(player, point)) then
        return false;
    end

    local wall = accessxi.nav_wall_distance(player);
    if (wall ~= nil and wall <= 1.2) then
        return false;
    end
    return true;
end

local function nav_split_tsv(line)
    local parts = T{};
    for part in (line .. '\t'):gmatch('([^\t]*)\t') do
        parts:append(part);
    end
    return parts;
end

function accessxi.nav_point_is_zoneline(point)
    if (point == nil) then
        return false;
    end
    local name = tostring(point.name or ''):lower();
    local source = tostring(point.source or ''):lower();
    return name:contains('zone line') or source:contains('zoneline');
end

function accessxi.nav_load_route_overrides()
    if (accessxi.nav_route_overrides_loaded) then
        return;
    end
    accessxi.nav_route_overrides_loaded = true;
    accessxi.nav_route_overrides:clear();

    local f = io.open(accessxi.nav_route_overrides_path, 'r');
    if (f == nil) then
        log_line('nav route overrides unavailable: ' .. tostring(accessxi.nav_route_overrides_path));
        return;
    end

    local order = T{};
    local groups = {};
    for line in f:lines() do
        if (line ~= nil and line ~= '' and not line:startswith('#') and not line:startswith('route_id')) then
            local parts = nav_split_tsv(line);
            if (#parts >= 17) then
                local route_id = nav_clean_field(parts[1] or '');
                local zone = tonumber(parts[2]) or 0;
                local sequence = tonumber(parts[12]) or 0;
                if (route_id ~= '' and zone > 0 and sequence > 0) then
                    local override = groups[route_id];
                    if (override == nil) then
                        override = T{
                            id = route_id,
                            zone = zone,
                            destination_name = nav_clean_field(parts[3] or ''),
                            destination = T{
                                zone = zone,
                                x = tonumber(parts[4]) or 0,
                                z = tonumber(parts[5]) or 0,
                                y = tonumber(parts[6]) or 0,
                            },
                            match_radius = tonumber(parts[7]) or 3,
                            min_x = tonumber(parts[8]) or -999999,
                            max_x = tonumber(parts[9]) or 999999,
                            min_z = tonumber(parts[10]) or -999999,
                            max_z = tonumber(parts[11]) or 999999,
                            source = nav_clean_field(parts[16] or ''),
                            confidence = nav_clean_field(parts[17] or ''),
                            waypoints = T{},
                        };
                        groups[route_id] = override;
                        order:append(route_id);
                    end
                    override.waypoints:append(T{
                        order = sequence,
                        zone = zone,
                        name = ('Route override %s %d'):fmt(route_id, sequence),
                        x = tonumber(parts[13]) or 0,
                        z = tonumber(parts[14]) or 0,
                        y = tonumber(parts[15]) or 0,
                        kind = 'route',
                        source = 'route-override:' .. route_id,
                        route_override_id = route_id,
                    });
                end
            end
        end
    end
    f:close();

    for _, route_id in ipairs(order) do
        local override = groups[route_id];
        if (override ~= nil and override.waypoints:len() > 0) then
            table.sort(override.waypoints, function (a, b)
                return (tonumber(a.order) or 0) < (tonumber(b.order) or 0);
            end);
            accessxi.nav_route_overrides:append(override);
        end
    end
    log_line(('nav route overrides loaded %d routes from "%s"'):fmt(accessxi.nav_route_overrides:len(), accessxi.nav_route_overrides_path));
end

function accessxi.nav_route_override_matches(player, point, override)
    if (player == nil or point == nil or override == nil) then
        return false;
    end
    local zone = tonumber(override.zone) or 0;
    if (zone <= 0 or (tonumber(player.zone) or 0) ~= zone or (tonumber(point.zone) or 0) ~= zone) then
        return false;
    end

    local px = tonumber(player.x) or 0;
    local pz = tonumber(player.z) or 0;
    if (px < (tonumber(override.min_x) or -999999) or px > (tonumber(override.max_x) or 999999)
        or pz < (tonumber(override.min_z) or -999999) or pz > (tonumber(override.max_z) or 999999)) then
        return false;
    end

    local route_id = tostring(override.id or '');
    if (route_id == 'lathine-fallen-ravine-to-west-ronfaure-zoneline'
        and not accessxi.nav_lathine_lower_ravine_position(player)) then
        return false;
    end

    if (nav_distance(point, override.destination) > (tonumber(override.match_radius) or 3)) then
        return false;
    end

    local expected_name = tostring(override.destination_name or ''):lower();
    local point_name = tostring(point.name or ''):lower();
    return expected_name == '' or point_name == '' or point_name:contains(expected_name) or expected_name:contains(point_name);
end

function accessxi.nav_route_points_override_id(points)
    local count = points ~= nil and points:len() or 0;
    if (count <= 0) then
        return '';
    end

    for _, point in ipairs(points) do
        if (point ~= nil) then
            local route_id = tostring(point.route_override_id or ''):lower();
            if (route_id ~= '') then
                return route_id;
            end
            local source = tostring(point.source or ''):lower();
            if (source == 'dat-collision') then
                return 'dat-collision';
            end
            local source_id = source:match('route%-override:([^:]+)');
            if (source_id ~= nil and source_id ~= '') then
                return source_id;
            end
        end
    end

    return '';
end

accessxi.nav_route_quarantine_rules = T{
    T{
        zone = 102,
        x = -592.951,
        y = 13.765,
        z = 392.547,
        radius = 4.0,
        y_radius = 3.0,
        destination = '',
        except_destination = "Ordelle's Caves zone line z2u6",
        reason = 'live-disproved lower shelf descent -592.951,392.547 from La Theine pocket on 2026-07-02',
    },
    T{
        zone = 102,
        destination = "Ordelle's Caves zone line z2u6",
        x = -597.806,
        y = 15.582,
        z = 392.732,
        radius = 5.0,
        y_radius = 3.0,
        reason = 'live-disproved La Theine shelf shortcut to Ordelle z2u6; use the F-6 ravine entry before F-7',
    },
    T{
        zone = 102,
        destination = "Ordelle's Caves zone line z2u6",
        x = -592.951,
        y = 13.765,
        z = 392.547,
        radius = 5.0,
        y_radius = 3.0,
        reason = 'live-disproved La Theine shelf descent to Ordelle z2u6; use the F-6 ravine entry before F-7',
    },
