    tick = tick,
});

function accessxi.nav_compute_route_with_zoneline_approach(player, point)
    accessxi.nav_route_last_reject_reason = '';
    local survey_collision_fallback = false;
    if (type(accessxi.nav_recorded_survey_route) == 'function') then
        local recorded_survey, survey_required, collision_required = accessxi.nav_recorded_survey_route(player, point);
        if (recorded_survey:len() > 1) then
            return recorded_survey, nil;
        end
        if (survey_required) then
            return T{}, nil;
        end
        survey_collision_fallback = collision_required == true;
    end

    -- La Theine's installed full-zone navmesh answers immediately and avoids
    -- the synchronous DAT terrain build. The DAT mapper twice produced a
    -- live-disproved loop at the Galaihaurat cliff and the latest build kept
    -- the game silent for more than two minutes. Prefer the existing full
    -- zone mesh for same-zone destinations and keep each returned segment
    -- bounded so steering cannot cut a narrow corner.  Zonelines use the
    -- paired reverse landing as their mesh endpoint, then append only the
    -- nearby proven transition point.  Never fall through to the slow DAT
    -- terrain builder for La Theine when this installed mesh has no path.
    if survey_collision_fallback
        and player ~= nil and point ~= nil
        and (tonumber(player.zone) or 0) == 102
        and (tonumber(point.zone) or 0) == 102 then
        local lathine_mesh_route = T{};
        local is_zoneline = accessxi.nav_point_is_zoneline(point);
        if (is_zoneline) then
            local override_route = accessxi.nav_route_override_points(player, point);
            if (override_route:len() > 1) then
                accessxi.nav_route_last_reject_reason = '';
                return override_route, nil;
            end
            if (accessxi.nav_nearby_zoneline_direct_route_allowed(player, point)) then
                log_line(('nav direct nearby zoneline route destination="%s" distance=%.1f'):fmt(
                    point.name or '',
                    nav_distance(player, point)));
                return T{}, nil;
            end
            for _, approach in ipairs(accessxi.nav_zoneline_approach_candidates(point)) do
                lathine_mesh_route = nav_compute_mesh_route(player, approach);
                if (lathine_mesh_route:len() > 1) then
                    accessxi.nav_append_final_zoneline_point(lathine_mesh_route, point);
                    break;
                end
            end
        else
            lathine_mesh_route = nav_compute_mesh_route(player, point);
        end
        if lathine_mesh_route:len() > 1 then
            for _, waypoint in ipairs(lathine_mesh_route) do
                waypoint.route_override_id = 'lathine-navmesh';
            end
            accessxi.nav_route_last_reject_reason = '';
            log_line(('nav La Theine full-zone navmesh route destination="%s" count=%d'):fmt(
                point.name or '', lathine_mesh_route:len()));
            return lathine_mesh_route, nil;
        end
        if (is_zoneline) then
            accessxi.nav_route_last_reject_reason =
                'installed La Theine navmesh has no route to this zone line';
            log_line(('nav La Theine zoneline navmesh unavailable destination="%s"'):fmt(
                point.name or ''));
            return T{}, nil;
        end
    end

    if (not survey_collision_fallback) then
        local recorded_corridor, corridor_required = accessxi.nav_lathine_recorded_corridor_route(player, point);
        if (recorded_corridor:len() > 1) then
            return recorded_corridor, nil;
        end
        if (corridor_required) then
            return T{}, nil;
        end

        local recorded_ravine_escape = accessxi.nav_lathine_recorded_ravine_escape_route(player, point);
        if (recorded_ravine_escape:len() > 1) then
            return recorded_ravine_escape, nil;
        end
        if (accessxi.nav_lathine_recorded_ravine_escape_required(player, point)) then
            return T{}, nil;
        end

        local lower_ravine_recovery = accessxi.nav_lathine_lower_ravine_recovery_route(player, point);
        if (lower_ravine_recovery:len() > 1) then
            return lower_ravine_recovery, nil;
        end

        local override_route = accessxi.nav_route_override_points(player, point);
        if (override_route:len() > 1) then
            accessxi.nav_route_last_reject_reason = '';
            return override_route, nil;
        end

        if (accessxi.nav_nearby_zoneline_direct_route_allowed(player, point)) then
            log_line(('nav direct nearby zoneline route destination="%s" distance=%.1f'):fmt(
                point.name or '',
                nav_distance(player, point)));
            return T{}, nil;
        end

        local required_transport_id = nav_clean_field(point ~= nil and point.objective_transport_id or '');
        if (required_transport_id ~= '' and type(accessxi.nav_verified_elevator_route) == 'function') then
            local transport_route, transport_required = accessxi.nav_verified_elevator_route(player, point);
            if (transport_route:len() > 1) then
                accessxi.nav_route_last_reject_reason = '';
                return transport_route, nil;
            end
            if (transport_required == true) then
                accessxi.nav_route_last_reject_reason = 'required verified transport route unavailable';
                log_line(('nav required transport unavailable id="%s" destination="%s"'):fmt(
                    accessxi.escape_probe_log_text(required_transport_id),
                    accessxi.escape_probe_log_text(point.name or '')));
                return T{}, nil;
            end
        end
    end

    local collision_route, collision_mode, collision_message = accessxi.nav_dat_collision_route(player, point);
    if (collision_mode == 'ready') then
        accessxi.nav_route_last_reject_reason = '';
        return collision_route, nil;
    end
    if (collision_mode == 'pending') then
        accessxi.nav_route_last_reject_reason = '';
        return T{}, nil;
    end
    if (collision_mode == 'error') then
        local approach_route, approach_mode, approach_message =
            accessxi.nav_dat_collision_zoneline_approach(player, point);
        if (approach_mode == 'ready') then
            accessxi.nav_route_last_reject_reason = '';
            return approach_route, nil;
        end
        if (approach_mode == 'pending') then
            accessxi.nav_route_last_reject_reason = '';
            return T{}, nil;
        end
        accessxi.nav_route_last_reject_reason = nav_clean_field(collision_message);
        if (accessxi.nav_route_last_reject_reason == '') then
            accessxi.nav_route_last_reject_reason = nav_clean_field(approach_message);
        end
        return T{}, nil;
    end

    local route = nav_compute_mesh_route(player, point);
    if (route:len() > 1) then
        if (type(accessxi.nav_transport_clear) == 'function') then
            accessxi.nav_transport_clear('direct-route-verified');
        end
        if (type(accessxi.nav_dangruf_fount_drop_clear) == 'function') then
            accessxi.nav_dangruf_fount_drop_clear('direct-route-verified');
        end
        accessxi.nav_route_last_reject_reason = '';
        return route, nil;
    end
    if (player == nil or point == nil) then
        return route, nil;
    end
    if (type(accessxi.nav_dangruf_fount_drop_route) == 'function') then
        local drop_route = accessxi.nav_dangruf_fount_drop_route(player, point);
        if (drop_route:len() > 1) then
            accessxi.nav_route_last_reject_reason = '';
            return drop_route, nil;
        end
    end
    if (type(accessxi.nav_verified_elevator_route) == 'function') then
        local transport_route = accessxi.nav_verified_elevator_route(player, point);
        if (transport_route:len() > 1) then
            accessxi.nav_route_last_reject_reason = '';
            return transport_route, nil;
        end
    end
    if (not accessxi.nav_point_is_zoneline(point)) then
        local kind = accessxi.nav_point_effective_kind(point);
        if (route:len() == 1
            and kind ~= 'area'
            and nav_distance(player, point) > accessxi.nav_arrival_radius(point)) then
            local approach_route, approach = accessxi.nav_compute_mesh_endpoint_approach(player, point);
            if (approach_route:len() > 1) then
                return approach_route, approach;
            end
            accessxi.nav_route_last_reject_reason = 'navmesh returned no verified walkable path';
            log_line(('navmesh incomplete route rejected destination="%s" distance=%.1f count=%d'):fmt(
                point.name or '',
                nav_distance(player, point),
                route:len()));
            route:clear();
        end
        return route, nil;
    end

    for _, approach in ipairs(accessxi.nav_zoneline_approach_candidates(point)) do
        local approach_route = nav_compute_mesh_route(player, approach);
        if (approach_route:len() > 1) then
            accessxi.nav_route_last_reject_reason = '';
            accessxi.nav_append_final_zoneline_point(approach_route, point);
            log_line(('nav zoneline approach route destination="%s" approach=(%.3f,%.3f,%.3f) count=%d'):fmt(
                point.name or '',
                approach.x or 0,
                approach.z or 0,
                approach.y or 0,
                approach_route:len()));
            return approach_route, approach;
        end
    end

    return route, nil;
end

accessxi.nav_generated_name_is_placeholder = function (name, source)
    local lower_source = tostring(source or ''):lower();
    if (not (lower_source:contains('lsb') or lower_source:contains('generated'))) then
        return false;
    end

    local lower = nav_clean_field(name or ''):lower();
    if (lower == '' or lower == 'blank' or lower == 'fxtest' or lower:startswith('npc[') or lower:startswith('sdoor')) then
        return true;
    end
    return lower:match('^0x%x+$') ~= nil or lower:match('^%a%d+%a$') ~= nil;
end

local function nav_load_points_file(path, default_source)
    local f = io.open(path, 'r');
    if (f == nil) then
        return 0;
    end

    local loaded = 0;
    for line in f:lines() do
        if (line ~= nil and line ~= '' and not line:startswith('#')) then
            local parts = nav_split_tsv(line);
            if (#parts >= 5) then
                local zone = tonumber(parts[1]) or 0;
                local x = tonumber(parts[3]);
                local z = tonumber(parts[4]);
                if (zone > 0 and x ~= nil and z ~= nil) then
                    local name = nav_clean_field(parts[2]);
                    local kind = nav_clean_field(parts[6] or '');
                    local source = nav_clean_field(parts[7] or default_source or 'database');
                    local source_lower = source:lower();
                    local legacy_entity_capture = (default_source == 'manual'
                        and kind:lower() == 'discovered'
                        and source_lower:sub(1, 7) == 'entity:');
                    if (not legacy_entity_capture and not accessxi.nav_generated_name_is_placeholder(name, source)) then
                        local raw_spawn_ids = T{};
                        for value in tostring(parts[12] or ''):gmatch('[^,]+') do
                            local spawn_id = tonumber(nav_clean_field(value));
                            if (spawn_id ~= nil) then raw_spawn_ids:append(spawn_id); end
                        end
                        accessxi.nav_points:append(T{
                            zone = zone,
                            zone_name = accessxi.nav_graph_zone_name(zone),
                            name = name,
                            x = x,
                            z = z,
                            y = tonumber(parts[5]) or 0,
                            kind = kind,
                            source = source,
                            confidence = nav_clean_field(parts[8] or ''),
                            section = nav_clean_field(parts[9] or ''),
                            destination_id = nav_clean_field(parts[10] or ''),
                            raw_identity = nav_clean_field(parts[11] or ''),
                            raw_spawn_ids = raw_spawn_ids,
                            cluster_policy_version = nav_clean_field(parts[13] or ''),
                        });
                        loaded = loaded + 1;
                    end
                end
            end
        end
    end
    f:close();
    return loaded;
end

local function nav_load_points()
    if (accessxi.nav_points_loaded) then
        return;
    end
    accessxi.nav_points_loaded = true;
    accessxi.nav_points:clear();

    local db_count = nav_load_points_file(accessxi.nav_database_path, 'database');
    local discovery_count = nav_load_points_file(accessxi.nav_discoveries_path, 'discoveries');
    local recorded_count = nav_load_points_file(accessxi.nav_recorded_marks_path, 'live-route-recording');
    local user_count = nav_load_points_file(accessxi.nav_points_path, 'manual');
    accessxi.nav_catalog_revision = (tonumber(accessxi.nav_catalog_revision) or 0) + 1;
    log_line(('nav loaded database=%d discoveries=%d recorded=%d user=%d total=%d db="%s" discoveries="%s" recorded_path="%s" user="%s"'):fmt(
        db_count,
        discovery_count,
        recorded_count,
        user_count,
        accessxi.nav_points:len(),
        accessxi.nav_database_path,
        accessxi.nav_discoveries_path,
        accessxi.nav_recorded_marks_path,
        accessxi.nav_points_path));
end

local nav_point_key = nil;
local nav_nearby = nil;

accessxi.nav_save_point_to_path = function (point, path)
    nav_load_points();

    local key = nav_point_key(point);
    for _, existing in ipairs(accessxi.nav_points) do
        if (nav_point_key(existing) == key) then
            return true;
        end
    end

    accessxi.nav_points:append(point);
    accessxi.nav_catalog_revision = (tonumber(accessxi.nav_catalog_revision) or 0) + 1;
    accessxi.nav_live_nm_name_cache = T{};

    local f = io.open(path or accessxi.nav_points_path, 'a');
    if (f == nil) then
        return false;
    end
    f:write(('%d\t%s\t%.3f\t%.3f\t%.3f\t%s\t%s\t%s\t%s\n'):fmt(
        tonumber(point.zone) or 0,
        nav_tsv_field(point.name),
        tonumber(point.x) or 0,
        tonumber(point.z) or 0,
        tonumber(point.y) or 0,
        nav_tsv_field(point.kind),
        nav_tsv_field(point.source),
        nav_tsv_field(point.confidence or ''),
        nav_tsv_field(point.section or '')));
    f:close();
    return true;
end

local function nav_save_point(point)
    return accessxi.nav_save_point_to_path(point, accessxi.nav_points_path);
end

local function nav_point_confidence(point)
    local explicit = nav_clean_field(point ~= nil and point.confidence or ''):lower();
    if (explicit ~= '') then
        return explicit;
    end

    local source = tostring(point ~= nil and point.source or ''):lower();
    local kind = tostring(point ~= nil and point.kind or ''):lower();
    if (source:contains('proven') or source:contains('live-trace') or source:contains('verified')) then
        return 'proven';
    end
    if (source:contains('manual') or source:contains('target') or source:contains('entity')) then
        return 'observed';
    end
    if (kind:contains('area') or kind:contains('transition') or source:contains('database') or source:contains('lsb') or source:contains('wiki')) then
        return 'untested';
    end
    return 'untested';
end

local function nav_point_confidence_rank(point)
    local confidence = nav_point_confidence(point);
    if (confidence == 'proven') then
        return 0;
    elseif (confidence == 'observed') then
        return 1;
    elseif (confidence == 'bad') then
        return 9;
    end
    return 4;
end

local function nav_write_route_evidence(result, player, destination, route_target, extra)
    extra = extra or T{};
    local needs_header = false;
    local existing = io.open(accessxi.nav_route_evidence_path, 'r');
    if (existing == nil) then
        needs_header = true;
    else
        local first = existing:read(1);
        needs_header = first == nil;
        existing:close();
    end

    local f = io.open(accessxi.nav_route_evidence_path, 'a');
    if (f == nil) then
        return false;
    end
    if (needs_header) then
        f:write('time\tresult\tzone\tdestination\tkind\tconfidence\tplayer_x\tplayer_z\tplayer_y\tdest_x\tdest_z\tdest_y\twaypoint_index\twaypoint_count\ttarget_x\ttarget_z\twall_clearance\toff_route\treason\tnearby\n');
    end

    local wall = extra.wall;
    if (wall == nil and player ~= nil) then
        wall = accessxi.nav_wall_distance(player);
    end
    local nearby = '';
    local nearby_results = nav_nearby(5, 25);
    if (nearby_results ~= nil) then
        local parts = T{};
        for i = 1, math.min(5, #nearby_results) do
            local item = nearby_results[i];
            parts:append(('%s %.0f'):fmt(nav_tsv_field(item.name or ''), tonumber(item.distance) or 0));
        end
        nearby = parts:concat('; ');
    end

    f:write(('%s\t%s\t%d\t%s\t%s\t%s\t%.3f\t%.3f\t%.3f\t%.3f\t%.3f\t%.3f\t%d\t%d\t%.3f\t%.3f\t%s\t%s\t%s\t%s\n'):fmt(
        os.date('%Y-%m-%d %H:%M:%S'),
        nav_tsv_field(result or ''),
        tonumber(destination ~= nil and destination.zone or player ~= nil and player.zone or 0) or 0,
        nav_tsv_field(destination ~= nil and destination.name or ''),
        nav_tsv_field(destination ~= nil and destination.kind or ''),
        nav_tsv_field(nav_point_confidence(destination)),
        tonumber(player ~= nil and player.x or 0) or 0,
        tonumber(player ~= nil and player.z or 0) or 0,
        tonumber(player ~= nil and player.y or 0) or 0,
        tonumber(destination ~= nil and destination.x or 0) or 0,
        tonumber(destination ~= nil and destination.z or 0) or 0,
        tonumber(destination ~= nil and destination.y or 0) or 0,
        tonumber(accessxi.nav_route_point_index) or 0,
        accessxi.nav_route_points ~= nil and accessxi.nav_route_points:len() or 0,
        tonumber(route_target ~= nil and route_target.x or 0) or 0,
        tonumber(route_target ~= nil and route_target.z or 0) or 0,
        wall ~= nil and ('%.2f'):fmt(wall) or '',
        extra.off_route ~= nil and ('%.2f'):fmt(extra.off_route) or '',
        nav_tsv_field(extra.reason or ''),
        nav_tsv_field(nearby)));
    f:close();
    return true;
end

local function nav_position_speech(pos)
    if (pos == nil) then
        return 'Position unavailable.';
    end
    return ('Zone %d. X %.1f. Z %.1f. Y %.1f.'):fmt(
        tonumber(pos.zone) or 0,
        nav_round(pos.x, 1),
        nav_round(pos.z, 1),
        nav_round(pos.y, 1));
end

function accessxi.nav_route_recorder_display_name(name, pos)
    local clean = nav_tsv_field(name or ''):trim();
    if (clean ~= '') then
        return clean;
    end
    return ('zone-%d-route'):fmt(tonumber(pos ~= nil and pos.zone or 0) or 0);
end

function accessxi.nav_route_recorder_write(event_name, pos, label, now, distance)
    event_name = nav_tsv_field(event_name or 'point'):lower();
    pos = pos or nav_cached_player_position();
    now = tonumber(now) or tick();
    if (pos == nil) then
        return false;
    end

    local needs_header = false;
    local existing = io.open(accessxi.nav_route_recorder_path, 'r');
    if (existing == nil) then
        needs_header = true;
    else
        local first = existing:read(1);
        needs_header = first == nil;
        existing:close();
    end

    local f = io.open(accessxi.nav_route_recorder_path, 'a');
    if (f == nil) then
        log_line(('nav route recorder write failed path="%s"'):fmt(accessxi.escape_probe_log_text(accessxi.nav_route_recorder_path or '')));
        return false;
    end
    if (needs_header) then
        f:write('timestamp\tsession\tname\tevent\tseq\tzone\tx\tz\ty\tyaw\tindex\tdistance\tlabel\n');
    end

    if (event_name == 'point' or event_name == 'zone-change' or event_name == 'mark' or event_name == 'start' or event_name == 'stop') then
        accessxi.nav_route_recorder_sample_count = (tonumber(accessxi.nav_route_recorder_sample_count) or 0) + 1;
    end

    f:write(('%s\t%s\t%s\t%s\t%d\t%d\t%.3f\t%.3f\t%.3f\t%.3f\t%d\t%.3f\t%s\n'):fmt(
        os.date('%Y-%m-%d %H:%M:%S'),
        nav_tsv_field(accessxi.nav_route_recorder_session or ''),
        nav_tsv_field(accessxi.nav_route_recorder_name or ''),
        nav_tsv_field(event_name),
        tonumber(accessxi.nav_route_recorder_sample_count) or 0,
        tonumber(pos.zone) or 0,
        tonumber(pos.x) or 0,
        tonumber(pos.z) or 0,
        tonumber(pos.y) or 0,
        tonumber(pos.yaw) or 0,
        tonumber(pos.index) or -1,
        tonumber(distance) or 0,
        nav_tsv_field(label or '')));
    f:close();

    accessxi.nav_route_recorder_last_write_tick = now;
    accessxi.nav_route_recorder_last_x = tonumber(pos.x) or 0;
    accessxi.nav_route_recorder_last_z = tonumber(pos.z) or 0;
    accessxi.nav_route_recorder_last_y = tonumber(pos.y) or 0;
    accessxi.nav_route_recorder_last_zone = tonumber(pos.zone) or 0;
    return true;
end

function accessxi.nav_route_recorder_status()
    if (accessxi.nav_route_recorder_active ~= true) then
        return 'Route recorder is not running.';
    end
    return ('Route recorder running. %s. %d points.'):fmt(
        accessxi.nav_route_recorder_name ~= '' and accessxi.nav_route_recorder_name or 'unnamed route',
        tonumber(accessxi.nav_route_recorder_sample_count) or 0);
end

function accessxi.nav_route_recorder_start(name)
    if (accessxi.nav_route_recorder_active == true) then
        return accessxi.nav_route_recorder_status();
    end

    local pos = nav_cached_player_position();
    if (pos == nil) then
        return 'Position unavailable. Route recorder not started.';
    end

    accessxi.nav_route_recorder_active = true;
    accessxi.nav_route_recorder_name = accessxi.nav_route_recorder_display_name(name, pos);
    accessxi.nav_route_recorder_session = ('%s-z%d'):fmt(os.date('%Y%m%d-%H%M%S'), tonumber(pos.zone) or 0);
    accessxi.nav_route_recorder_sample_count = 0;
    accessxi.nav_route_recorder_last_tick = 0;
    accessxi.nav_route_recorder_last_write_tick = 0;
    accessxi.nav_route_recorder_last_x = nil;
    accessxi.nav_route_recorder_last_z = nil;
    accessxi.nav_route_recorder_last_y = nil;
    accessxi.nav_route_recorder_last_zone = 0;

    if (not accessxi.nav_route_recorder_write('start', pos, 'start', tick(), 0)) then
        accessxi.nav_route_recorder_active = false;
        return 'Route recorder could not write the log file.';
    end

    local text = ('Route recorder started. %s. Follow works if your character moves along the route.'):fmt(accessxi.nav_route_recorder_name);
    log_line(('nav route recorder start session="%s" name="%s" path="%s" %s'):fmt(
        accessxi.escape_probe_log_text(accessxi.nav_route_recorder_session or ''),
        accessxi.escape_probe_log_text(accessxi.nav_route_recorder_name or ''),
        accessxi.escape_probe_log_text(accessxi.nav_route_recorder_path or ''),
        nav_position_speech(pos)));
    return text;
end

function accessxi.nav_route_recorder_stop()
    if (accessxi.nav_route_recorder_active ~= true) then
        return 'Route recorder is not running.';
    end

    local pos = nav_cached_player_position();
    if (pos ~= nil) then
        accessxi.nav_route_recorder_write('stop', pos, 'stop', tick(), 0);
    end

    local name = accessxi.nav_route_recorder_name ~= '' and accessxi.nav_route_recorder_name or 'route';
    local count = tonumber(accessxi.nav_route_recorder_sample_count) or 0;
    local path = accessxi.nav_route_recorder_path or '';
    accessxi.nav_route_recorder_active = false;
    accessxi.nav_route_recorder_name = '';
    accessxi.nav_route_recorder_session = '';
    accessxi.nav_route_recorder_last_tick = 0;
    accessxi.nav_route_recorder_last_x = nil;
    accessxi.nav_route_recorder_last_z = nil;
    accessxi.nav_route_recorder_last_y = nil;
    accessxi.nav_route_recorder_last_zone = 0;

    local text = ('Route recorder stopped. %s. %d points saved.'):fmt(name, count);
    log_line(('nav route recorder stop name="%s" points=%d path="%s"'):fmt(
        accessxi.escape_probe_log_text(name),
        count,
        accessxi.escape_probe_log_text(path)));
    return text;
end

function accessxi.nav_route_recorder_mark(label)
    if (accessxi.nav_route_recorder_active ~= true) then
        return 'Route recorder is not running.';
    end

    local pos = nav_cached_player_position();
    if (pos == nil) then
        return 'Position unavailable. Route mark not saved.';
    end

    local clean_label = nav_tsv_field(label or ''):trim();
    if (clean_label == '') then
        clean_label = 'mark';
    end
    accessxi.nav_route_recorder_write('mark', pos, clean_label, tick(), 0);
    return ('Route mark saved. %s.'):fmt(clean_label);
end

function accessxi.nav_route_recorder_poll(now)
    if (accessxi.nav_route_recorder_active ~= true) then
        return false;
    end

    now = tonumber(now) or tick();
    if ((now - (tonumber(accessxi.nav_route_recorder_last_tick) or 0)) < (tonumber(accessxi.nav_route_recorder_min_interval_ms) or 500)) then
        return false;
    end
    accessxi.nav_route_recorder_last_tick = now;

    local pos = nav_cached_player_position();
    if (pos == nil) then
        if ((now - (tonumber(accessxi.nav_route_recorder_last_unavailable_tick) or 0)) >= 3000) then
            accessxi.nav_route_recorder_last_unavailable_tick = now;
            log_line('nav route recorder position unavailable');
        end
        return false;
    end

    local last = nil;
    if (accessxi.nav_route_recorder_last_x ~= nil and accessxi.nav_route_recorder_last_z ~= nil) then
        last = T{
            zone = tonumber(accessxi.nav_route_recorder_last_zone) or 0,
            x = tonumber(accessxi.nav_route_recorder_last_x) or 0,
            z = tonumber(accessxi.nav_route_recorder_last_z) or 0,
            y = tonumber(accessxi.nav_route_recorder_last_y) or 0,
        };
    end

    if (last == nil) then
        return accessxi.nav_route_recorder_write('point', pos, '', now, 0);
    end

    if ((tonumber(pos.zone) or 0) ~= (tonumber(last.zone) or 0)) then
        return accessxi.nav_route_recorder_write('zone-change', pos, '', now, 0);
    end

    local distance = nav_distance(pos, last);
    if (distance >= (tonumber(accessxi.nav_route_recorder_min_distance) or 1.0)) then
        return accessxi.nav_route_recorder_write('point', pos, '', now, distance);
    end

    return false;
end

function accessxi.nav_route_recorder_command(args, verb_index, tail_index)
    local verb = tostring(args[verb_index] or ''):lower();
    if (verb == '' or verb:any('status', 'info')) then
        return accessxi.nav_route_recorder_status();
    elseif (verb:any('start', 'begin', 'on')) then
        return accessxi.nav_route_recorder_start(command_tail(args, tail_index));
    elseif (verb:any('stop', 'end', 'off', 'finish')) then
        return accessxi.nav_route_recorder_stop();
    elseif (verb:any('mark', 'note')) then
        return accessxi.nav_route_recorder_mark(command_tail(args, tail_index));
    end

    return accessxi.nav_route_recorder_start(command_tail(args, verb_index));
end

nav_nearby = function (max_count, max_distance)
    local player = nav_cached_player_position();
    if (player == nil) then
        return nil, 'Position unavailable.';
    end

    local entity = safe_call(function () return AshitaCore:GetMemoryManager():GetEntity(); end, nil);
    if (entity == nil) then
        return nil, 'Entity map unavailable.';
    end

    local player_index = tonumber(player.index) or -1;
    local size = tonumber(safe_call(function () return entity:GetEntityMapSize(); end, 0)) or 0;
    local hard_limit = math.max(tonumber(accessxi.nav_widescan_max_range) or 350, tonumber(accessxi.nav_live_search_max_range) or 9999);
    local distance_limit = math.max(1, math.min(tonumber(max_distance) or 120, hard_limit));
    local results = {};
    for i = 0, math.min(size - 1, 2303) do
        if (i ~= player_index) then
            local pos = nav_entity_position(i);
            if (pos ~= nil and pos.name ~= '' and not (pos.x == 0 and pos.z == 0)) then
                local distance = nav_distance(player, pos);
                if (distance > 0.5 and distance <= distance_limit) then
                    pos.distance = distance;
                    table.insert(results, pos);
                end
            end
        end
    end

    table.sort(results, function (a, b) return (a.distance or 999999) < (b.distance or 999999); end);
    if (#results == 0) then
        return results, 'No nearby named entities found.';
    end

    local parts = T{};
    for i = 1, math.min(max_count or 8, #results) do
        local item = results[i];
        parts:append(('%s %.0f'):fmt(item.name, item.distance or 0));
    end
    return results, 'Nearby. ' .. parts:concat('. ') .. '.';
end

function accessxi.nav_entity_is_player(pos)
    if (pos == nil) then
        return false;
    end

    local flags = tonumber(pos.spawn_flags) or 0;
    return bit.band(flags, 0x0001) == 0x0001 or (tonumber(pos.type) or -1) == 0;
end

function accessxi.nav_entity_is_npc(pos)
    if (pos == nil) then
        return false;
    end

    return bit.band(tonumber(pos.spawn_flags) or 0, 0x0002) == 0x0002;
end

function accessxi.nav_entity_is_obvious_object(pos)
    local name = tostring(pos ~= nil and pos.name or ''):lower():gsub('%s+', ' ');
    if (name == '') then
        return true;
    end
    return name == '???'
        or name:contains('survival guide')
        or name:contains('field manual')
        or name:contains('field parchment')
        or name:contains('home point')
        or name:contains('waypoint')
        or name:contains('conquest banner')
        or name:contains('treasure casket')
        or name:contains('treasure coffer')
        or name:contains('planar rift')
        or name:contains('cavernous maw')
        or name:contains('stone monument')
        or name:contains('luck rune')
        or name:contains('footprint')
        or name:contains('rune')
        or name:contains('fount')
        or name:contains('telepoint')
        or name:contains('ergon locus');
end

function accessxi.nav_entity_is_known_non_hostile(pos)
    local name = tostring(pos ~= nil and pos.name or ''):lower():gsub('%s+', ' ');
    if (name == '') then
        return true;
    end

    return name == 'macro test'
        or name:contains('macro test')
        or name == 'moogle'
        or name:contains('moogle')
        or name == 'couvoullie'
        or name == 'voidwatch officer'
        or name == 'valaineral'
        or name == 'sylvie'
        or name == 'tenzen'
        or name == 'mihli aliapoh'
        or name == 'mihlialiapoh';
end

function accessxi.nav_entity_name_looks_like_enemy(pos)
    local name = tostring(pos ~= nil and pos.name or ''):lower():gsub('%s+', ' ');
    if (name == '') then
        return false;
    end

    return name:contains('goblin')
        or name:contains('orc')
        or name:contains('quadav')
        or name:contains('yagudo')
        or name:contains('demon')
        or name:contains('sapling')
        or name:contains('mandragora')
        or name:contains('funguar')
        or name:contains('crawler')
        or name:contains('wasp')
        or name:contains('hornet')
        or name:contains('beetle')
        or name:contains('bee')
        or name:contains('bat')
        or name:contains('leech')
        or name:contains('crab')
        or name:contains('pugil')
        or name:contains('fly')
        or name:contains('worm')
        or name:contains('lizard')
        or name:contains('raptor')
        or name:contains('sheep')
        or name:contains('ram')
        or name:contains('tiger')
        or name:contains('coeurl')
        or name:contains('dhalmel')
        or name:contains('wivre')
        or name:contains('wyvern')
        or name:contains('skeleton')
        or name:contains('ghost')
        or name:contains('elemental')
        or name:contains('bomb')
        or name:contains('slime')
        or name:contains('crawler')
        or name:contains('flytrap')
        or name:contains('treant')
        or name:contains('malboro')
        or name:contains('goobbue')
        or name:contains('hippogryph');
end

function accessxi.nav_entity_is_enemy(pos)
    if (pos == nil or nav_clean_field(pos.name) == '') then
        return false;
    end
    if (accessxi.nav_entity_is_player(pos) or accessxi.nav_entity_is_obvious_object(pos) or accessxi.nav_entity_is_known_non_hostile(pos)) then
        return false;
    end

    local entity_type = tonumber(pos.type) or -1;
    local flags = tonumber(pos.spawn_flags) or 0;
    local status = tonumber(pos.status) or -1;
    if (status == 2 or status == 3) then
        return false;
    end
    if ((tonumber(pos.x) or 0) == 0 and (tonumber(pos.z) or 0) == 0) then
        return false;
    end

    if (accessxi.nav_entity_name_looks_like_enemy(pos)) then
        return true;
    end

    if (entity_type == 1 or bit.band(flags, 0x1000) ~= 0) then
        return false;
    end

    local hp = tonumber(pos.hp) or -1;
    if (hp > 0) then
        return true;
    end

    return entity_type == 2 or bit.band(flags, 0x0010) ~= 0;
end

function accessxi.nav_entity_kind(pos)
    if (accessxi.nav_entity_is_player(pos)) then
        return 'player';
    end
    if (accessxi.nav_entity_is_enemy(pos)) then
        return 'enemy';
    end
    if (accessxi.nav_entity_is_obvious_object(pos)) then
        return 'object';
    end
    if (accessxi.nav_entity_is_npc(pos)) then
        return 'npc';
    end
    return 'nearby';
end

function accessxi.nav_zone_suppresses_named_npc_obstacles(zone)
    zone = tonumber(zone) or 0;
    return zone == 230 or zone == 231 or zone == 232 or zone == 233
        or zone == 234 or zone == 235 or zone == 236 or zone == 237
        or zone == 238 or zone == 239 or zone == 240 or zone == 241
        or zone == 242 or zone == 243 or zone == 244 or zone == 245
        or zone == 246;
end

function accessxi.nav_entity_is_dynamic_obstacle_candidate(pos)
    if (pos == nil or not accessxi.nav_live_entity_valid(pos)) then
        return false;
    end

    local kind = tostring(pos.live_kind or accessxi.nav_entity_kind(pos));
    if (kind == 'enemy' and accessxi.nav_zone_suppresses_named_npc_obstacles(pos.zone)
        and not accessxi.nav_entity_name_looks_like_enemy(pos)) then
        return false;
    end
    return kind == 'player' or kind == 'enemy' or kind == 'live-nm';
end

function accessxi.nav_live_entity_key(pos)
    if (pos == nil) then
        return '';
    end
    return ('%d:%d:%d:%s'):fmt(
        tonumber(pos.zone) or 0,
        tonumber(pos.index) or -1,
        tonumber(pos.server_id) or 0,
        tostring(pos.name or ''):lower():gsub('%s+', ' '));
end

function accessxi.nav_live_entity_valid(pos)
    if (pos == nil or nav_clean_field(pos.name) == '') then
        return false;
    end
    if ((tonumber(pos.x) or 0) == 0 and (tonumber(pos.z) or 0) == 0) then
        return false;
    end
    local status = tonumber(pos.status) or -1;
    if (status == 2 or status == 3) then
        return false;
    end

    local zone = nav_zone_id();
    return zone <= 0 or (tonumber(pos.zone) or 0) == zone;
end

function accessxi.nav_live_entity_search_range()
    return math.max(tonumber(accessxi.nav_widescan_max_range) or 350, tonumber(accessxi.nav_live_search_max_range) or 9999);
end

function accessxi.nav_live_nm_names_for_zone(zone)
    nav_load_points();
    zone = tonumber(zone) or nav_zone_id();
    if (zone <= 0) then
        return T{};
    end

    if (type(accessxi.nav_live_nm_name_cache) ~= 'table') then
        accessxi.nav_live_nm_name_cache = T{};
    end
    local cache_key = tostring(zone);
    local cached = accessxi.nav_live_nm_name_cache[cache_key];
    if (type(cached) == 'table') then
        return cached;
    end

    local names = T{};
    for _, point in ipairs(accessxi.nav_points or T{}) do
        if ((tonumber(point.zone) or 0) == zone and accessxi.nav_point_effective_kind(point) == 'nm') then
            local name = nav_clean_field(point.name or ''):lower():gsub('%s+', ' ');
            if (name ~= '') then
                names[name] = true;
            end
        end
    end
    accessxi.nav_live_nm_name_cache[cache_key] = names;
    return names;
end

function accessxi.nav_entity_is_live_nm_candidate(pos)
    if (not accessxi.nav_entity_is_enemy(pos)) then
        return false;
    end
    local name = nav_clean_field(pos.name or ''):lower():gsub('%s+', ' ');
    if (name == '') then
        return false;
    end
    local names = accessxi.nav_live_nm_names_for_zone(pos.zone);
    return names[name] == true;
end

function accessxi.nav_stable_destination_duplicate_key(point)
    if (point == nil) then
        return '';
    end

    local kind = accessxi.nav_point_effective_kind(point);
    if (not (kind == 'npc' or kind == 'object' or kind == 'area')) then
        return '';
    end

    local confidence = nav_point_confidence(point);
    if (confidence ~= 'observed' and confidence ~= 'proven') then
        return '';
    end

    local name = nav_clean_field(point.name or ''):lower():gsub('%s+', ' '):trim();
    if (name == '') then
        return '';
    end

    return ('%d:%s'):fmt(tonumber(point.zone) or 0, name);
end

function accessxi.nav_live_entity_duplicate_key(entity_point)
    if (entity_point == nil) then
        return '';
    end

    local name = nav_clean_field(entity_point.name or ''):lower():gsub('%s+', ' '):trim();
    if (name == '') then
        return '';
    end

    local zone = tonumber(entity_point.zone) or nav_zone_id();
    return ('%d:%s'):fmt(zone or 0, name);
end

function accessxi.nav_live_entity_shadowed_by_static_destination(entity_point, static_destination_keys)
    if (entity_point == nil or type(static_destination_keys) ~= 'table') then
        return false;
    end

    local kind = tostring(entity_point.live_kind or accessxi.nav_entity_kind(entity_point));
    if (not (kind == 'npc' or kind == 'object' or kind == 'nearby')) then
        return false;
    end

    local key = accessxi.nav_live_entity_duplicate_key(entity_point);
    return key ~= '' and static_destination_keys[key] == true;
end

function accessxi.nav_live_entity_snapshot(max_count, max_distance)
    local hard_limit = math.max(tonumber(accessxi.nav_widescan_max_range) or 350, tonumber(accessxi.nav_live_search_max_range) or 9999);
    local limit = math.max(1, math.min(tonumber(max_distance) or (tonumber(accessxi.nav_widescan_max_range) or 350), hard_limit));
    local nearby = nav_nearby(max_count or 80, limit);
    local results = {};
    if (nearby == nil) then
        return results;
    end

    local now = tick();
    if (type(accessxi.nav_live_entity_seen) ~= 'table') then
        accessxi.nav_live_entity_seen = T{};
    end

    for _, pos in ipairs(nearby) do
        if (accessxi.nav_live_entity_valid(pos)) then
            pos.live_kind = accessxi.nav_entity_kind(pos);
            pos.live_nm = accessxi.nav_entity_is_live_nm_candidate(pos);
            if (pos.live_nm == true) then
                pos.live_kind = 'live-nm';
            end

            local key = accessxi.nav_live_entity_key(pos);
            if (key ~= '') then
                accessxi.nav_live_entity_seen[key] = T{
                    tick = now,
                    kind = pos.live_kind,
                    name = pos.name,
                    zone = pos.zone,
                };
            end
            table.insert(results, pos);
        end
    end

    table.sort(results, function (a, b) return (a.distance or 999999) < (b.distance or 999999); end);
    return results;
end

function accessxi.nav_live_entities_for_category(category_key, max_distance)
    category_key = tostring(category_key or 'all');
    local entities = accessxi.nav_live_entity_snapshot(80, max_distance or (tonumber(accessxi.nav_widescan_max_range) or 350));
    local filtered = {};
    for _, pos in ipairs(entities) do
        local kind = tostring(pos.live_kind or accessxi.nav_entity_kind(pos));
        if (category_key == 'all'
            or category_key == kind
            or (category_key == 'enemy' and (kind == 'enemy' or kind == 'live-nm'))) then
            table.insert(filtered, pos);
        end
    end
    table.sort(filtered, function (a, b) return (a.distance or 999999) < (b.distance or 999999); end);
    return filtered;
end

function accessxi.nav_live_enemies(max_distance)
    return accessxi.nav_live_entities_for_category('enemy', max_distance);
end

function accessxi.nav_point_is_live_entity(point)
    if (point == nil) then
        return false;
    end

    local source = tostring(point.source or ''):lower();
    if (source:startswith('live-entity:')) then
        return true;
    end

    local live_kind = nav_clean_field(point.live_kind or '');
    return live_kind == 'enemy' or live_kind == 'live-nm' or live_kind == 'player';
end

function accessxi.nav_resolve_live_entity_point(point, player)
    if (point == nil) then
        return nil;
    end

    if (not accessxi.nav_point_is_live_entity(point)) then
        return nil;
    end

    local source = tostring(point.source or ''):lower();
    local expected_name = nav_clean_field(point.name or '');
    local expected_name_key = expected_name:lower():gsub('%s+', ' ');
    local source_index, source_server_id = source:match('live%-entity:(%-?%d+):(%d+)');
    local expected_index = tonumber(point.index) or tonumber(source_index) or -1;
    local expected_server_id = tonumber(point.server_id) or tonumber(source_server_id) or 0;

    local function normalize_candidate(pos)
        if (pos == nil or not accessxi.nav_live_entity_valid(pos)) then
            return nil;
        end
        local name_key = nav_clean_field(pos.name or ''):lower():gsub('%s+', ' ');
        local server_id = tonumber(pos.server_id) or 0;
        if (expected_server_id > 0 and server_id ~= expected_server_id) then
            return nil;
        end
        if (expected_server_id <= 0 and expected_name_key ~= '' and name_key ~= expected_name_key) then
            return nil;
        end

        pos.live_kind = accessxi.nav_entity_kind(pos);
        pos.live_nm = accessxi.nav_entity_is_live_nm_candidate(pos);
        if (pos.live_nm == true) then
            pos.live_kind = 'live-nm';
        end
        pos.distance = player ~= nil and nav_distance(player, pos) or tonumber(pos.distance) or 0;
        return T{
            zone = pos.zone,
            name = pos.name,
            x = pos.x,
            z = pos.z,
            y = pos.y,
            kind = pos.live_kind,
            source = ('live-entity:%d:%d'):fmt(pos.index or -1, pos.server_id or 0),
            confidence = nav_clean_field(point.confidence or ''),
            section = nav_clean_field(point.section or ''),
            distance = pos.distance or 0,
            index = pos.index,
            server_id = pos.server_id,
            live_kind = pos.live_kind,
            live_nm = pos.live_nm,
        };
    end

    if (expected_index >= 0) then
        local direct = normalize_candidate(nav_entity_position(expected_index));
        if (direct ~= nil) then
            return direct;
        end
    end

    local best = nil;
    local best_distance = 999999;
    local candidates = accessxi.nav_live_entity_snapshot(240, accessxi.nav_live_entity_search_range());
    for _, pos in ipairs(candidates) do
        local candidate = normalize_candidate(pos);
        if (candidate ~= nil) then
            local distance = expected_server_id > 0 and (candidate.distance or 0) or nav_distance(point, candidate);
            if (best == nil or distance < best_distance) then
                best = candidate;
                best_distance = distance;
            end
        end
    end
    return best;
end

function accessxi.nav_refresh_live_route_destination(player, now)
    if (not accessxi.nav_active or accessxi.nav_destination == nil) then
        return false;
    end

    local current = accessxi.nav_destination;
    local resolved = accessxi.nav_resolve_live_entity_point(current, player);
    if (resolved == nil) then
        if (accessxi.nav_point_is_live_entity(current)) then
            now = tonumber(now) or tick();
            if ((tonumber(accessxi.nav_live_route_missing_since) or 0) == 0) then
                accessxi.nav_live_route_missing_since = now;
                return false;
            end
            if ((now - (tonumber(accessxi.nav_live_route_missing_since) or now)) >= 3000) then
                local text = ('Route stopped. %s is no longer visible.'):fmt(current.name or 'Target');
                accessxi.nav_active = false;
                accessxi.nav_destination = nil;
                accessxi.nav_route_points:clear();
                accessxi.nav_route_point_index = 1;
                accessxi.nav_last_key = '';
                accessxi.nav_last_direction_text = '';
                accessxi.nav_beacon_last_key = '';
                accessxi.nav_beacon_last_tick = 0;
                accessxi.nav_live_route_missing_since = 0;
                speak(text);
                log_line(('nav live route target lost name="%s"'):fmt(current.name or ''));
                return true;
            end
        end
        return false;
    end

    accessxi.nav_live_route_missing_since = 0;
    local moved = nav_distance(current, resolved);
    if (moved <= 0.15) then
        return false;
    end

    now = tonumber(now) or tick();
    accessxi.nav_destination = resolved;
    local route_count = accessxi.nav_route_points ~= nil and accessxi.nav_route_points:len() or 0;
    if (moved >= 3.0 and route_count > 1 and ((now - (tonumber(accessxi.nav_route_last_recalc_tick) or 0)) > 1800)) then
        accessxi.nav_route_last_recalc_tick = now;
        accessxi.nav_route_points = accessxi.nav_compute_route_with_zoneline_approach(player, resolved);
        if (accessxi.nav_route_points:len() > 1) then
            accessxi.nav_route_point_index = accessxi.nav_first_route_index(player, accessxi.nav_route_points, resolved);
        else
            accessxi.nav_route_point_index = 1;
        end
    end
    log_line(('nav live route retarget name="%s" moved=%.1f x=%.3f z=%.3f'):fmt(
        resolved.name or current.name or '',
        moved,
        resolved.x or 0,
        resolved.z or 0));
    return true;
end

function accessxi.nav_live_category(category_key)
    return category_key == 'all'
        or category_key == 'enemy'
        or category_key == 'player'
        or category_key == 'live-nm'
        or category_key == 'mission'
        or category_key == 'quest';
end

function accessxi.nav_log_entity_candidates(label, count)
    local nearby = nav_nearby(count or 12);
    if (nearby == nil) then
        log_line((label or 'entity candidates') .. ' unavailable');
        return;
    end

    for i = 1, math.min(count or 12, #nearby) do
        local pos = nearby[i];
        log_line(('%s %02d name="%s" kind=%s dist=%.1f hp=%d status=%d claim=%d flags=0x%X color=%d type=%d'):fmt(
            label or 'entity candidate',
            i,
            pos.name or '',
            accessxi.nav_entity_kind(pos),
            tonumber(pos.distance) or 0,
            tonumber(pos.hp) or -1,
            tonumber(pos.status) or -1,
            tonumber(pos.claim) or -1,
            tonumber(pos.spawn_flags) or 0,
            tonumber(pos.name_color) or 0,
            tonumber(pos.type) or -1));
    end
end

local function nav_capture_nearby(max_count)
    local results, message = nav_nearby(max_count or 25);
    if (results == nil or #results == 0) then
        return message or 'No nearby named entities found.';
    end

    local saved = 0;
    local skipped = 0;
    for i = 1, math.min(max_count or 25, #results) do
        local entity_point = results[i];
        if (entity_point.name ~= nil and entity_point.name ~= '') then
            local entity_kind = accessxi.nav_entity_kind(entity_point);
            if (entity_kind == 'object' or entity_kind == 'npc') then
                local before = accessxi.nav_points:len();
                accessxi.nav_save_point_to_path(T{
                    zone = entity_point.zone,
                    name = entity_point.name,
                    x = entity_point.x,
                    z = entity_point.z,
                    y = entity_point.y,
                    kind = entity_kind,
                    source = ('entity:%d:%d'):fmt(entity_point.index or -1, entity_point.server_id or 0),
                    confidence = 'observed',
                    section = 'discovered',
                }, accessxi.nav_discoveries_path);
                if (accessxi.nav_points:len() > before) then
                    saved = saved + 1;
                end
            else
                skipped = skipped + 1;
            end
        end
    end

    if (saved == 0) then
        if (skipped > 0) then
            return ('No new stable destinations captured. Skipped %d live entities.'):fmt(skipped);
        end
        return 'No new nearby destinations captured.';
    end
    if (skipped > 0) then
        return ('Captured %d nearby destinations. Skipped %d live entities.'):fmt(saved, skipped);
    end
    return ('Captured %d nearby destinations.'):fmt(saved);
end

nav_point_key = function (point)
    return ('%d:%s:%d:%d'):fmt(
        tonumber(point.zone) or 0,
        tostring(point.name or ''):lower(),
        math.floor((tonumber(point.x) or 0) * 10 + 0.5),
        math.floor((tonumber(point.z) or 0) * 10 + 0.5));
end

local function nav_point_source_rank(point)
    local confidence_rank = nav_point_confidence_rank(point);
    if (confidence_rank == 9) then
        return 99;
    end

    local source = tostring(point.source or ''):lower();
    local kind = tostring(point.kind or ''):lower();
    local raw_identity = tostring(point.raw_identity or ''):lower();
    local exact_zoneline_bias = 0;
    if ((kind:contains('area') or kind:contains('transition'))
        and tostring(point.destination_id or '') ~= ''
        and (raw_identity:sub(1, 14) == 'lsb:zonelines:'
            or raw_identity:sub(1, 21) == 'lsb:scripted_trigger:')) then
        exact_zoneline_bias = -0.25;
    end
    if (kind:contains('area') or kind:contains('transition')) then
        return confidence_rank + exact_zoneline_bias;
    end
    if (source:contains('database') or kind:contains('home') or kind:contains('waypoint')) then
        return confidence_rank + 1;
    end
    if (kind:contains('nm') or kind:contains('notorious')) then
        return confidence_rank + 2;
    end
    if (kind:contains('enemy') or kind:contains('monster') or kind:contains('mob')) then
        return confidence_rank + 3;
    end
    if (kind:contains('npc')) then
        return confidence_rank + 4;
    end
    if (source:contains('manual')) then
        return confidence_rank + 5;
    end
    if (kind:contains('player')) then
        return confidence_rank + 6;
    end
    return confidence_rank + 7;
end

accessxi.nav_menu_static_key = function (point)
    if (point == nil) then
        return '';
    end

    local kind = accessxi.nav_point_effective_kind(point);
    if (kind == 'enemy' or kind == 'live-nm' or kind == 'player' or kind == 'nearby') then
        return nav_point_key(point);
    end

    return ('%d:%s:%s'):fmt(
        tonumber(point.zone) or 0,
        kind,
        tostring(point.name or ''):lower():gsub('%s+', ' '));
end

accessxi.nav_static_destination_is_better = function (point, previous)
    if (point == nil) then
        return false;
    end
    if (previous == nil) then
        return true;
    end
    local point_rank = nav_point_source_rank(point);
    local previous_rank = nav_point_source_rank(previous);
    return point_rank < previous_rank
        or (point_rank == previous_rank
            and (tonumber(point.distance) or 999999) < (tonumber(previous.distance) or 999999));
end

accessxi.nav_search_text = function (value)
    local text = nav_clean_field(value or ''):lower();
    text = text:gsub("'", '');
    text = text:gsub('[^%w%s]', ' ');
    text = text:gsub('%s+', ' '):trim();
    return text;
end

accessxi.nav_point_matches_search = function (point, query)
    query = accessxi.nav_search_text(query);
    if (query == '') then
        return true;
    end
    if (point == nil) then
        return false;
    end

    local haystack = accessxi.nav_search_text(('%s %s %s %s'):fmt(
        point.name or '',
        point.kind or '',
        point.source or '',
        point.section or ''));
    if (haystack:contains(query)) then
        return true;
    end
    return haystack:gsub('%s+', ''):contains(query:gsub('%s+', ''));
end

local function nav_collect_menu_items(category_key, search_query)
    nav_load_points();

    category_key = tostring(category_key or 'all');
    search_query = nav_clean_field(search_query or '');
    if ((category_key == 'mission' or category_key == 'quest')
        and type(accessxi.nav_mission_quest_active_items) == 'function') then
        local dynamic = {};
        for _, item in ipairs(accessxi.nav_mission_quest_active_items(category_key)) do
            if (accessxi.nav_point_matches_search(item, search_query)) then
                table.insert(dynamic, item);
            end
        end
        return dynamic;
    end

    local player = nav_cached_player_position();
    local zone = nav_zone_id();
    local items = {};
    local static_by_key = {};
    local static_destination_keys = {};

    for _, point in ipairs(accessxi.nav_points) do
        local effective_kind = accessxi.nav_point_effective_kind(point);
        if ((tonumber(point.zone) or 0) == zone and nav_clean_field(point.name) ~= '' and accessxi.nav_point_matches_category(point, category_key) and accessxi.nav_point_matches_search(point, search_query)) then
            local key = accessxi.nav_menu_static_key(point);
            point.distance = player ~= nil and nav_distance(player, point) or 0;
            point.kind = effective_kind;
            local duplicate_key = accessxi.nav_stable_destination_duplicate_key(point);
            if (duplicate_key ~= '') then
                static_destination_keys[duplicate_key] = true;
            end
            local previous = static_by_key[key];
            if (accessxi.nav_static_destination_is_better(point, previous)) then
                static_by_key[key] = point;
            end
        end
    end

    local seen = T{};
    for _, point in pairs(static_by_key) do
        table.insert(items, point);
        seen:append(nav_point_key(point));
    end

    local live_distance = (category_key == 'enemy' or category_key == 'live-nm') and accessxi.nav_live_entity_search_range() or 120;
    if (nav_clean_field(search_query) ~= '') then
        live_distance = accessxi.nav_live_entity_search_range();
    end
    local function append_live_entity_points(nearby)
        for _, entity_point in ipairs(nearby or {}) do
            local entity_kind = tostring(entity_point.live_kind or accessxi.nav_entity_kind(entity_point));
            local point = T{
                zone = zone,
                name = entity_point.name,
                x = entity_point.x,
                z = entity_point.z,
                y = entity_point.y,
                kind = entity_kind,
                source = ('live-entity:%d:%d'):fmt(entity_point.index or -1, entity_point.server_id or 0),
                distance = entity_point.distance or 0,
                index = entity_point.index,
                server_id = entity_point.server_id,
                live_kind = entity_kind,
                live_nm = entity_point.live_nm,
            };
            local key = nav_point_key(point);
            if (accessxi.nav_point_matches_category(point, category_key)
                and accessxi.nav_point_matches_search(point, search_query)
                and not accessxi.nav_live_entity_shadowed_by_static_destination(entity_point, static_destination_keys)
                and not seen:contains(key)) then
                seen:append(key);
                table.insert(items, point);
            end
        end
    end

    append_live_entity_points(accessxi.nav_live_entities_for_category(category_key, live_distance));
    if (search_query ~= '' and category_key == 'all') then
        append_live_entity_points(accessxi.nav_live_entities_for_category('enemy', live_distance));
    end

    table.sort(items, function (a, b)
        local ar = nav_point_source_rank(a);
        local br = nav_point_source_rank(b);
        if (ar ~= br) then
            return ar < br;
        end
        return (tonumber(a.distance) or 999999) < (tonumber(b.distance) or 999999);
    end);

    return items;
end

local function nav_refresh_search_results()
    accessxi.nav_menu_search_results = T{};
    local query = nav_clean_field(accessxi.nav_menu_search_query or '');
    accessxi.nav_menu_search_result_query = query;
    if (query == '') then
        return 0;
    end

    local items = nav_collect_menu_items('all', query);
    for _, item in ipairs(items) do
        accessxi.nav_menu_search_results:append(item);
    end
    if (type(accessxi.nav_zone_search_npc_results) == 'function') then
        local zone_results = accessxi.nav_zone_search_npc_results(query, nav_cached_player_position());
        for _, item in ipairs(zone_results) do
            if (item.zone_search_zone_result == true) then
                accessxi.nav_menu_search_results:append(item);
            end
        end
    end
    return accessxi.nav_menu_search_results:len();
end

local function nav_build_menu_items()
    local category = nav_current_category();
    local category_key = category ~= nil and category.key or 'all';
    if (category_key == 'search-results') then
        local results = {};
        for _, item in ipairs(accessxi.nav_menu_search_results or T{}) do
            table.insert(results, item);
        end
        return results;
    end
    return nav_collect_menu_items(category_key, '');
end

local function nav_menu_item_speech()
    local total = accessxi.nav_menu_items:len();
    local category = nav_current_category();
    local category_key = category ~= nil and category.key or 'all';
    local search_query = nav_clean_field(accessxi.nav_menu_search_query or '');
    if (total == 0) then
        if (category_key == 'mission') then
            return 'No active or startable missions are available from the current native character state.';
        elseif (category_key == 'quest') then
            return 'No active quests are available from the current native character state.';
        end
        return accessxi.navigation_empty_speech(
            category_key == 'search-results' and search_query or '');
    end

    if (accessxi.nav_menu_index < 1) then
        accessxi.nav_menu_index = total;
    elseif (accessxi.nav_menu_index > total) then
        accessxi.nav_menu_index = 1;
    end

    local item = accessxi.nav_menu_items[accessxi.nav_menu_index];
    if (item ~= nil and (item.objective_kind == 'mission' or item.objective_kind == 'quest')
        and type(accessxi.nav_mission_quest_item_speech) == 'function') then
        return accessxi.nav_mission_quest_item_speech(item, accessxi.nav_menu_index, total);
    end
    if (item ~= nil and item.zone_search_result == true) then
        local zone_name = accessxi.nav_graph_zone_name(item.zone);
        local route_text = '';
        if (item.zone_search_reachable == true) then
            local path_len = tonumber(item.zone_search_path_len) or 0;
            if (path_len <= 0) then
                route_text = 'Current zone.';
            elseif (path_len == 1) then
                route_text = 'Route 1 zone.';
            else
                route_text = ('Route %d zones.'):fmt(path_len);
            end
        else
            route_text = 'No zone route known.';
        end
        local confidence = nav_point_confidence(item);
        return accessxi.navigation_zone_search_row_speech(
            accessxi.speech_name(item.name or 'NPC'),
            accessxi.nav_menu_index,
            total,
            zone_name ~= '' and zone_name or ('zone ' .. tostring(item.zone or 0)),
            route_text,
            confidence);
    end

    local player = nav_cached_player_position();
    local phrase = accessxi.nav_guidance_phrase(player, item, nil);
    local kind = nav_clean_field(item.kind);
    local confidence = nav_point_confidence(item);
    local section = nav_clean_field(item.section or '');
    local section_lower = section:lower();
    local note_text = '';
    if (section_lower:startswith('requires:') or section_lower:startswith('note:')) then
        note_text = section;
    end
    return accessxi.navigation_row_speech(
        accessxi.speech_name(item.name or 'destination'),
        accessxi.nav_menu_index,
        total,
        kind,
        confidence,
        phrase,
        note_text);
end

local function nav_open_menu(search_query)
    accessxi.nav_menu_category = 1;
    accessxi.nav_menu_search_query = nav_clean_field(search_query or '');
    local search_count = nav_refresh_search_results();
    if (accessxi.nav_menu_search_query ~= '' and search_count > 0) then
        accessxi.nav_menu_category = accessxi.nav_search_category_index();
    elseif (accessxi.nav_menu_search_query ~= '') then
        accessxi.nav_menu_items = T{};
        accessxi.nav_menu_open = false;
        accessxi.nav_menu_index = 1;
        accessxi.nav_menu_last_key_tick = 0;
        accessxi.nav_menu_poll_key = 0;
        accessxi.nav_menu_poll_tick = 0;
        accessxi.nav_menu_open_tick = tick();
        local text = accessxi.navigation_empty_speech(accessxi.nav_menu_search_query);
        speak(text);
        log_line(('nav browser search empty search="%s"'):fmt(accessxi.escape_probe_log_text(accessxi.nav_menu_search_query or '')));
        return;
    end
    local items = nav_build_menu_items();
    accessxi.nav_menu_items = T{};
    for _, item in ipairs(items) do
        accessxi.nav_menu_items:append(item);
    end

    accessxi.nav_menu_open = false;
    accessxi.nav_menu_index = 1;
    accessxi.nav_menu_last_key_tick = 0;
    accessxi.nav_menu_poll_key = 0;
    accessxi.nav_menu_poll_tick = 0;
    accessxi.nav_menu_open_tick = tick();
    local text = nav_menu_item_speech();
    speak(text .. ' U selects the previous category. O selects the next category. J selects the previous destination. K repeats. L selects the next destination. I starts the selected route or stops active navigation.');
    log_line(('nav browser open search="%s" %s'):fmt(accessxi.escape_probe_log_text(accessxi.nav_menu_search_query or ''), text));
end

local function nav_close_menu()
    accessxi.nav_menu_open = false;
    accessxi.nav_menu_items:clear();
    accessxi.nav_menu_index = 1;
    accessxi.nav_menu_category = 1;
    accessxi.nav_menu_search_query = '';
    accessxi.nav_menu_search_results:clear();
    accessxi.nav_menu_search_result_query = '';
    accessxi.nav_menu_poll_key = 0;
    accessxi.nav_menu_poll_tick = 0;
    accessxi.nav_menu_open_tick = 0;
    if (type(accessxi.objective_guides) == 'table'
        and type(accessxi.objective_guides.close) == 'function') then
        accessxi.objective_guides:close('navigation-menu-closed');
    end
    speak('Navigation menu closed.');
    log_line('nav menu closed');
end

local function nav_close_menu_silent(reason)
    if (not accessxi.nav_menu_open) then
        return;
    end

    accessxi.nav_menu_open = false;
    accessxi.nav_menu_items:clear();
    accessxi.nav_menu_index = 1;
    accessxi.nav_menu_category = 1;
    accessxi.nav_menu_search_query = '';
    accessxi.nav_menu_search_results:clear();
    accessxi.nav_menu_search_result_query = '';
    accessxi.nav_menu_poll_key = 0;
    accessxi.nav_menu_poll_tick = 0;
    accessxi.nav_menu_open_tick = 0;
    if (type(accessxi.objective_guides) == 'table'
        and type(accessxi.objective_guides.close) == 'function') then
        accessxi.objective_guides:close(reason or 'navigation-menu-closed');
    end
    log_line(('nav menu silent close reason="%s"'):fmt(accessxi.escape_probe_log_text(reason or '')));
end

accessxi.nav_menu_selection_key = function (item)
    item = type(item) == 'table' and item or {};
    local kind = nav_clean_field(item.objective_kind or item.kind):lower();
    if (kind == 'mission' or kind == 'quest') then
        return table.concat({
            kind,
            nav_clean_field(item.objective_native_key),
            nav_clean_field(item.objective_guide_step_id or item.guide_step_id),
            nav_clean_field(item.objective_candidate_id),
            nav_clean_field(item.objective_action_id),
            nav_clean_field(item.objective_group_id),
            nav_clean_field(item.objective_destination_id),
            item.objective_instruction_only == true and 'instruction' or 'destination',
        }, '\t');
    end
    return table.concat({
        tostring(item.source or ''),
        tostring(item.name or ''),
    }, '\t');
end

local function nav_menu_rebuild(preserve_selection)
    local previous = preserve_selection and accessxi.nav_menu_items[accessxi.nav_menu_index] or nil;
    local previous_index = accessxi.nav_menu_index;
    local items = nav_build_menu_items();
    local category = nav_current_category();
    local category_key = nav_clean_field(type(category) == 'table' and category.key or ''):lower();
    if (type(accessxi.nav_menu_dirty_categories) == 'table' and category_key ~= '') then
        accessxi.nav_menu_dirty_categories[category_key] = nil;
    end
    accessxi.nav_menu_items = T{};
    for _, item in ipairs(items) do
        accessxi.nav_menu_items:append(item);
    end

    accessxi.nav_menu_index = 1;
    if (preserve_selection and accessxi.nav_menu_items:len() > 0) then
        if (previous ~= nil) then
            local previous_key = accessxi.nav_menu_selection_key(previous);
            for i = 1, accessxi.nav_menu_items:len() do
                local item = accessxi.nav_menu_items[i];
                if (accessxi.nav_menu_selection_key(item) == previous_key) then
                    accessxi.nav_menu_index = i;
                    return;
                end
            end
        end
        accessxi.nav_menu_index = math.max(1, math.min(previous_index or 1, accessxi.nav_menu_items:len()));
    end
end

function accessxi.queue_mission_quest_state_change(kind, reason, now)
    kind = nav_clean_field(kind):lower();
    if (kind ~= 'mission' and kind ~= 'quest' and kind ~= 'objective') then
        return false;
    end
    accessxi.mission_quest_state_pending = accessxi.mission_quest_state_pending or {};
    accessxi.mission_quest_state_pending[kind] = nav_clean_field(reason);
    accessxi.mission_quest_state_pending_tick = tonumber(now) or tick();
    return true;
end

function accessxi.poll_mission_quest_state_changes(now)
    now = tonumber(now) or tick();
    local pending = accessxi.mission_quest_state_pending or {};
    if (next(pending) == nil) then return false; end
    if ((type(accessxi.nav_zoning_watch_active) == 'function'
            and accessxi.nav_zoning_watch_active(now))
        or (type(accessxi.nav_zone_load_settle_active) == 'function'
            and accessxi.nav_zone_load_settle_active(now))) then
        return false;
    end
    local debounce = tonumber(accessxi.mission_quest_state_debounce_ms) or 250;
    if ((now - (tonumber(accessxi.mission_quest_state_pending_tick) or 0)) < debounce) then
        return false;
    end

    accessxi.mission_quest_state_pending = {};
    local kinds = pending.objective ~= nil and T{ 'objective' }
        or T{ 'mission', 'quest' };
    for _, kind in ipairs(kinds) do
        if (pending[kind] ~= nil and type(accessxi.on_mission_quest_state_changed) == 'function') then
            local ok, err = pcall(
                accessxi.on_mission_quest_state_changed,
                kind,
                pending[kind]);
            if (not ok) then
                log_line(('objective state refresh failed kind=%s reason="%s"'):fmt(
                    kind,
                    accessxi.escape_probe_log_text(tostring(err or 'unknown'))));
            end
        end
    end
    return true;
end

function accessxi.on_mission_quest_state_changed(kind, reason)
    kind = nav_clean_field(kind):lower();
    if (kind ~= 'mission' and kind ~= 'quest' and kind ~= 'objective') then
        return false, false;
    end
    accessxi.nav_menu_poll_key = 0;
    accessxi.nav_menu_dirty_categories = accessxi.nav_menu_dirty_categories or {};
    if (kind == 'objective') then
        accessxi.nav_menu_dirty_categories.mission = true;
        accessxi.nav_menu_dirty_categories.quest = true;
    else
        accessxi.nav_menu_dirty_categories[kind] = true;
    end

    local route_point = nil;
    if (type(accessxi.nav_is_mission_quest_point) == 'function'
        and accessxi.nav_is_mission_quest_point(accessxi.nav_destination)) then
        route_point = accessxi.nav_destination;
    elseif (type(accessxi.nav_is_mission_quest_point) == 'function'
        and accessxi.nav_is_mission_quest_point(accessxi.nav_zone_search_target)) then
        route_point = accessxi.nav_zone_search_target;
    end
    local route_kind = nav_clean_field(type(route_point) == 'table'
        and (route_point.objective_kind or route_point.kind) or ''):lower();
    local cancelled = false;
    if (route_point ~= nil and (kind == 'objective' or route_kind == kind)
        and type(accessxi.nav_mission_quest_route_point_is_current) == 'function') then
        local current_ok, current = pcall(
            accessxi.nav_mission_quest_route_point_is_current,
            route_point);
        if (current_ok and current ~= true
            and type(accessxi.nav_cancel_mission_quest_route) == 'function') then
            cancelled = accessxi.nav_cancel_mission_quest_route(
                'objective-state-changed') == true;
        elseif (not current_ok) then
            log_line(('objective state route check failed kind=%s reason="%s"'):fmt(
                kind,
                accessxi.escape_probe_log_text(current or 'unknown')));
        end
    end

    local changed = false;
    local category = type(nav_current_category) == 'function' and nav_current_category() or nil;
    local category_key = nav_clean_field(type(category) == 'table' and category.key or ''):lower();
    if (accessxi.nav_menu_open == true
        and (category_key == 'mission' or category_key == 'quest')
        and (kind == 'objective' or kind == category_key)) then
        local before = accessxi.nav_menu_items[accessxi.nav_menu_index];
        local before_key = before ~= nil and accessxi.nav_menu_selection_key(before) or '';
        local before_count = accessxi.nav_menu_items:len();
        nav_menu_rebuild(true);
        local after = accessxi.nav_menu_items[accessxi.nav_menu_index];
        local after_key = after ~= nil and accessxi.nav_menu_selection_key(after) or '';
        changed = before_count ~= accessxi.nav_menu_items:len() or before_key ~= after_key;
    end

    if (cancelled) then
        local label = route_kind == 'quest' and 'Quest' or 'Mission';
        local text = label .. ' updated. Route stopped. Select the next destination and press I when ready.';
        speak(text);
        log_line(('objective state progression kind=%s reason="%s" route=cancelled'):fmt(
            route_kind,
            accessxi.escape_probe_log_text(reason or 'state-changed')));
    elseif (changed) then
        log_line(('objective state progression kind=%s reason="%s" route=none'):fmt(
            category_key,
            accessxi.escape_probe_log_text(reason or 'state-changed')));
    end
    return changed, cancelled;
end

function accessxi.on_objective_interaction_progress_changed(kind, cancelled)
    kind = nav_clean_field(kind):lower();
    accessxi.nav_menu_dirty_categories = accessxi.nav_menu_dirty_categories or {};
    accessxi.nav_menu_dirty_categories[kind] = true;
    accessxi.nav_menu_poll_key = 0;
    local category = nav_current_category();
    if (accessxi.nav_menu_open == true and type(category) == 'table'
        and tostring(category.key or '') == kind) then
        nav_menu_rebuild(true);
    end
    if (cancelled == true) then
        local label = kind == 'quest' and 'Quest' or 'Mission';
        local text = label .. ' updated. Route stopped. Select the next destination and press I when ready.';
        speak(text);
        log_line(('objective interaction progression kind=%s route=cancelled'):fmt(kind));
    end
end

local function nav_menu_move(delta)
    local category = nav_current_category();
    local category_key = category ~= nil and tostring(category.key or '') or '';
    local refresh_live_rows = category ~= nil
        and accessxi.nav_live_category(category_key)
        and category_key ~= 'enemy'
        and category_key ~= 'mission'
        and category_key ~= 'quest';
    if (accessxi.nav_menu_items:len() == 0 or refresh_live_rows
        or (type(accessxi.nav_menu_dirty_categories) == 'table'
            and accessxi.nav_menu_dirty_categories[nav_clean_field(category_key):lower()] == true)) then
        nav_menu_rebuild(true);
    end

    local total = accessxi.nav_menu_items:len();
    if (total == 0) then
        speak(nav_menu_item_speech());
        return;
    end

    accessxi.nav_menu_index = accessxi.nav_menu_index + delta;
    local text = nav_menu_item_speech();
    speak(text);
    log_line('nav menu move ' .. text);
end

local function nav_menu_category_move(delta)
    accessxi.nav_menu_category = accessxi.nav_menu_category + delta;
    local category = nav_current_category();
    nav_menu_rebuild();
    local text = accessxi.navigation_category_speech(category ~= nil and category.label or '');
    speak(text);
    log_line('nav menu category ' .. text);
end

function accessxi.nav_objective_step_view_open()
    return type(accessxi.objective_guides) == 'table'
        and type(accessxi.objective_guides.is_open) == 'function'
        and accessxi.objective_guides:is_open();
end

local function nav_menu_start_route()
    local category = nav_current_category();
    local category_key = category ~= nil and tostring(category.key or '') or '';
    if (accessxi.nav_menu_items:len() == 0
        or (type(accessxi.nav_menu_dirty_categories) == 'table'
            and accessxi.nav_menu_dirty_categories[nav_clean_field(category_key):lower()] == true)) then
        nav_menu_rebuild(true);
    end

    local item = accessxi.nav_menu_items[accessxi.nav_menu_index];
    if (item == nil) then
        speak('No destination selected.');
        return;
    end

    local objective_kind = nav_clean_field(item.objective_kind or item.kind):lower();
    if (objective_kind == 'mission' or objective_kind == 'quest') then
        if (type(accessxi.nav_mission_quest_prepare_route) ~= 'function') then
            local text = 'Objective route preparation is unavailable.';
            speak(text);
            log_line('nav objective start blocked ' .. text);
            return;
        end
        local objective_player = nav_cached_player_position();
        if (objective_player == nil) then
            speak('Position unavailable.');
            return;
        end
        local prepare_ok, target, objective_message, objective_mode = pcall(
            accessxi.nav_mission_quest_prepare_route,
            item,
            objective_player);
        if (not prepare_ok) then
            local text = 'Objective route preparation is unavailable.';
            speak(text);
            log_line('nav objective start blocked ' .. text);
            return;
        end
        if (objective_mode == 'instruction') then
            local text = nav_clean_field(target or objective_message);
            if (text == '') then
                text = 'No exact source-backed destination is available for this objective.';
            end
            speak(text);
            log_line('nav objective instruction ' .. text);
            return;
        end
        if (objective_mode == 'wiki-ready') then
            local wiki_complete = type(target) == 'table'
                and target.objective_wiki_route == true
                and target.wiki_authoritative == true
                and target.verified ~= true
                and nav_clean_field(target.objective_kind) ~= ''
                and nav_clean_field(target.objective_native_key) ~= ''
                and nav_clean_field(target.objective_guide_step_id) ~= ''
                and nav_clean_field(target.objective_character_identity) ~= ''
                and tonumber(target.objective_world_id) ~= nil
                and tonumber(target.objective_session_epoch) ~= nil
                and nav_clean_field(target.objective_candidate_id) ~= ''
                and nav_clean_field(target.objective_action_id) ~= ''
                and type(target.objective_group_id) == 'string'
                and nav_clean_field(target.objective_destination_id) ~= ''
                and nav_clean_field(target.objective_classification) == 'catalogue-candidate'
                and nav_clean_field(target.objective_action_instruction) ~= '';
            if (not wiki_complete
                or type(accessxi.nav_start_wiki_objective_route) ~= 'function') then
                local text = 'Source-verified objective route execution is unavailable.';
                speak(text);
                log_line('nav objective source route blocked ' .. text);
                return;
            end
            local start_ok, text, started = pcall(
                accessxi.nav_start_wiki_objective_route,
                target,
                objective_player);
            if (not start_ok) then
                text = 'Source-verified objective route execution failed safely.';
                started = false;
            else
                text = nav_clean_field(text);
                if (text == '') then
                    text = started == true
                        and 'Source-verified objective route started.'
                        or 'Source-verified objective route could not start.';
                end
            end
            speak(text);
            log_line((started == true
                and 'nav objective source route start '
                or 'nav objective source route blocked ') .. text);
            return;
        end
        if (objective_mode == 'test-ready') then
            local test_complete = type(target) == 'table'
                and target.objective_test_route == true
                and target.verified ~= true
                and nav_clean_field(target.objective_kind) ~= ''
                and nav_clean_field(target.objective_native_key) ~= ''
                and nav_clean_field(target.objective_guide_step_id) ~= ''
                and nav_clean_field(target.objective_character_identity) ~= ''
                and tonumber(target.objective_world_id) ~= nil
                and tonumber(target.objective_session_epoch) ~= nil
                and nav_clean_field(target.objective_candidate_id) ~= ''
                and nav_clean_field(target.objective_action_id) ~= ''
                and type(target.objective_group_id) == 'string'
                and nav_clean_field(target.objective_destination_id) ~= ''
                and nav_clean_field(target.objective_classification) == 'catalogue-candidate'
                and nav_clean_field(target.objective_action_instruction) ~= ''
                and nav_clean_field(target.objective_route_contract_id) == ''
                and target.objective_contract_snapshot == nil;
            if (not test_complete or type(accessxi.nav_start_test_objective_route) ~= 'function') then
                local text = 'Source-backed objective route execution is unavailable.';
                speak(text);
                log_line('nav objective source route blocked ' .. text);
                return;
            end
            local start_ok, text, started = pcall(
                accessxi.nav_start_test_objective_route,
                target,
                objective_player);
            if (not start_ok) then
                text = 'Source-backed objective route execution failed safely.';
                started = false;
            else
                text = nav_clean_field(text);
                if (text == '') then
                    text = started == true
                        and 'Source-backed objective route started.'
                        or 'Source-backed objective route could not start.';
                end
            end
            local warning = nav_clean_field(objective_message);
            if (warning ~= '') then
                local marker = nav_clean_field(target.objective_kind):lower() == 'quest'
                    and 'Source-verified quest objective.'
                    or 'Source-verified mission objective.';
                local suffix = text;
                if (suffix:sub(1, #marker) == marker) then
                    suffix = nav_clean_field(suffix:sub(#marker + 1));
                end
                text = marker .. ' ' .. warning
                    .. (suffix ~= '' and (' ' .. suffix) or '');
            end
            speak(text);
            log_line((started == true
                and 'nav objective source route start '
                or 'nav objective source route blocked ') .. text);
            return;
        end
        if (objective_mode ~= 'ready' or type(target) ~= 'table') then
            local text = nav_clean_field(objective_message);
            if (text == '') then
                text = 'No exact source-backed destination is available for this objective.';
            end
            speak(text);
            log_line('nav objective start blocked ' .. text);
            return;
        end

        local snapshot = target.objective_contract_snapshot;
        local ready_complete = nav_clean_field(target.objective_kind) ~= ''
            and nav_clean_field(target.objective_native_key) ~= ''
            and nav_clean_field(target.objective_guide_step_id) ~= ''
            and nav_clean_field(target.objective_character_identity) ~= ''
            and tonumber(target.objective_world_id) ~= nil
            and tonumber(target.objective_session_epoch) ~= nil
            and nav_clean_field(target.objective_candidate_id) ~= ''
            and nav_clean_field(target.objective_action_id) ~= ''
            and type(target.objective_group_id) == 'string'
            and nav_clean_field(target.objective_destination_id) ~= ''
            and nav_clean_field(target.objective_classification) ~= ''
            and nav_clean_field(target.objective_action_instruction) ~= ''
            and nav_clean_field(target.objective_route_contract_id) ~= ''
            and type(snapshot) == 'table'
            and snapshot.route_ready == true
            and nav_clean_field(snapshot.contract_id) == nav_clean_field(target.objective_route_contract_id)
            and nav_clean_field(snapshot.candidate_id) == nav_clean_field(target.objective_candidate_id)
            and nav_clean_field(snapshot.action_id) == nav_clean_field(target.objective_action_id)
            and type(snapshot.group_id) == 'string'
            and snapshot.group_id == target.objective_group_id
            and nav_clean_field(snapshot.destination_id) == nav_clean_field(target.objective_destination_id);
        if (not ready_complete) then
            local text = 'Verified objective route authorization is incomplete.';
            speak(text);
            log_line('nav objective start blocked ' .. text);
            return;
        end

        if (type(accessxi.nav_start_authorized_objective_route) ~= 'function') then
            local text = 'Verified objective route execution is unavailable.';
            speak(text);
            log_line('nav objective start blocked ' .. text);
            return;
        end
        local start_ok, text, started = pcall(
            accessxi.nav_start_authorized_objective_route,
            target,
            objective_player);
        if (not start_ok) then
            text = 'Verified objective route execution failed safely.';
            started = false;
        else
            text = nav_clean_field(text);
            if (text == '') then
                text = started == true
                    and 'Starting verified objective route.'
                    or 'No exact current objective leg is proven from here.';
            end
        end
        speak(text);
        log_line((started == true and 'nav objective start ' or 'nav objective start blocked ') .. text);
        return;
    end

    if (item.zone_search_result == true) then
        accessxi.nav_menu_open = false;
        accessxi.nav_menu_poll_key = 0;
        accessxi.nav_menu_poll_tick = 0;
        accessxi.nav_menu_open_tick = 0;
        accessxi.nav_zone_search_target = accessxi.nav_copy_point(item);
        accessxi.nav_zone_search_query = nav_clean_field(item.zone_search_query or accessxi.nav_menu_search_query or item.name or '');
        accessxi.nav_zone_search_waiting_zone = 0;
        accessxi.nav_zone_search_waiting_from_zone = 0;
        accessxi.nav_zone_search_last_replan_tick = 0;
        local text = accessxi.nav_zone_search_start_next_leg('zone-search-selected');
        speak(text);
        log_line('nav zone search selected ' .. text);
        return;
    end

    accessxi.nav_clear_zone_search();
    if (type(accessxi.nav_transport_clear) == 'function') then
        accessxi.nav_transport_clear('menu-route-start');
    end
    if (type(accessxi.nav_dangruf_fount_drop_clear) == 'function') then
        accessxi.nav_dangruf_fount_drop_clear('menu-route-start');
    end
    local player = nav_cached_player_position();
    local live_item = accessxi.nav_resolve_live_entity_point(item, player);
    if (live_item ~= nil) then
        item = live_item;
    end

    accessxi.nav_active = true;
    accessxi.nav_destination = item;
    accessxi.nav_last_key = '';
    accessxi.nav_last_direction_text = '';
    accessxi.nav_beacon_last_key = '';
    accessxi.nav_beacon_last_tick = 0;
    accessxi.nav_beacon_reset_direction_state();
    accessxi.nav_progress_x = nil;
    accessxi.nav_progress_z = nil;
    accessxi.nav_progress_distance = 0;
    accessxi.nav_progress_tick = tick();
    accessxi.nav_progress_last_block_tick = 0;
    accessxi.nav_progress_last_log_key = '';
    accessxi.nav_collision_x = nil;
    accessxi.nav_collision_z = nil;
    accessxi.nav_collision_destination_distance = 0;
    accessxi.nav_collision_route_distance = 0;
    accessxi.nav_collision_tick = 0;
    accessxi.nav_collision_last_sound_tick = 0;
    accessxi.nav_collision_last_key = '';
    accessxi.nav_obstacle_last_key = '';
    accessxi.nav_obstacle_last_tick = 0;
    accessxi.nav_wall_avoid_last_key = '';
    accessxi.nav_wall_avoid_last_tick = 0;
    accessxi.nav_route_point_index = 1;
    accessxi.nav_route_last_recalc_tick = tick();
    accessxi.nav_menu_open = false;
    accessxi.nav_menu_poll_key = 0;
    accessxi.nav_menu_poll_tick = 0;
    accessxi.nav_menu_open_tick = 0;
    accessxi.nav_route_start_point = player ~= nil and T{ zone = player.zone, x = player.x, z = player.z, y = player.y, yaw = player.yaw } or nil;
    accessxi.nav_route_start_tick = tick();
    accessxi.nav_last_failure_key = '';
    accessxi.nav_last_failure_tick = 0;
    accessxi.nav_live_route_missing_since = 0;
    accessxi.nav_route_live_replan_last_key = '';
    accessxi.nav_route_live_replan_last_tick = 0;
    accessxi.nav_route_points = accessxi.nav_compute_route_with_zoneline_approach(player, item);
    if (accessxi.nav_dat_collision_pending ~= nil) then
        local text = 'Safe route is still preparing. Navigation will start automatically.';
        accessxi.nav_last_direction_text = text;
        speak(text);
        log_line('nav menu start pending ' .. text);
        return;
    end
    local unsafe_route_text = accessxi.nav_route_direct_fallback_block_reason(player, item);
    if (accessxi.nav_route_points:len() <= 1
        and unsafe_route_text ~= ''
        and accessxi.nav_zone_search_target == nil
        and not tostring(item.source or ''):startswith('zonesearch:')
        and type(accessxi.nav_same_zone_reentry_start) == 'function') then
        local reentry_text = accessxi.nav_same_zone_reentry_start(player, item, 'menu-route-reentry');
        if reentry_text ~= nil and reentry_text ~= '' then
            if (type(accessxi.nav_mission_quest_start_suffix) == 'function') then
                reentry_text = reentry_text .. accessxi.nav_mission_quest_start_suffix(item);
            end
            speak(reentry_text);
            log_line('nav menu same-zone reentry ' .. reentry_text);
            return;
        end
    end
    if (accessxi.nav_route_points:len() <= 1 and unsafe_route_text ~= '') then
        nav_write_route_evidence('unreachable', player, item, nil, T{ reason = unsafe_route_text });
        accessxi.nav_active = false;
        accessxi.nav_destination = nil;
        accessxi.nav_route_points:clear();
        accessxi.nav_last_direction_text = unsafe_route_text;
        speak(unsafe_route_text);
        log_line('nav menu start blocked ' .. unsafe_route_text);
        return;
    end
    if (accessxi.nav_point_effective_kind(item) == 'area' and accessxi.nav_route_points:len() <= 1 and not accessxi.nav_area_point_direct_route_allowed(player, item) and not accessxi.nav_area_point_reachable(player, item)) then
        nav_write_route_evidence('unreachable', player, item, nil, T{ reason = 'menu start unreachable' });
        accessxi.nav_active = false;
        accessxi.nav_destination = nil;
        accessxi.nav_route_points:clear();
        local text = ('%s is not reachable from here.'):fmt(item.name or 'Destination');
        speak(text);
        log_line('nav menu start blocked ' .. text);
        return;
    end
    local phrase = accessxi.nav_guidance_phrase(player, item, nil);
    local text;
    if (accessxi.nav_beacon_enabled) then
        text = ('Starting route to %s. Beacon active.'):fmt(item.name or 'destination');
    else
        text = ('Starting route to %s. %s'):fmt(item.name or 'destination', phrase);
    end
    if (accessxi.nav_route_points:len() > 1) then
        local first_index = accessxi.nav_first_route_index(player, accessxi.nav_route_points, item);
        local first = accessxi.nav_route_points[first_index];
        local second = accessxi.nav_route_points[math.min(first_index + 1, accessxi.nav_route_points:len())];
        local first_phrase = accessxi.nav_guidance_phrase(player, first, second, false);
        accessxi.nav_route_point_index = first_index;
        if (accessxi.nav_beacon_enabled) then
            text = ('Starting route to %s. %d waypoints. Beacon active.'):fmt(item.name or 'destination', accessxi.nav_route_points:len());
        else
            text = ('Starting route to %s. %d waypoints. Next, %s'):fmt(item.name or 'destination', accessxi.nav_route_points:len(), first_phrase);
        end
    end
    if (type(accessxi.nav_transport_start_suffix) == 'function') then
        text = text .. accessxi.nav_transport_start_suffix();
    end
    if (type(accessxi.nav_dangruf_fount_drop_start_suffix) == 'function') then
        text = text .. accessxi.nav_dangruf_fount_drop_start_suffix();
    end
    if (type(accessxi.nav_mission_quest_start_suffix) == 'function') then
        text = text .. accessxi.nav_mission_quest_start_suffix(item);
    end
    accessxi.nav_last_direction_text = text;
    nav_write_route_evidence('start', player, item, accessxi.nav_route_points[accessxi.nav_route_point_index] or item, T{ reason = 'menu' });
    speak(text);
    log_line('nav menu start ' .. text);
end

local nav_route_stop;

local function nav_menu_handle_action(action)
    if (action == 'start_route') then
        nav_menu_start_route();
    elseif (action == 'stop_route') then
        local text = nav_route_stop();
        speak(text);
        log_line('nav hotkey ' .. text);
    elseif (action == 'previous_category') then
        nav_menu_category_move(-1);
    elseif (action == 'next_category') then
        nav_menu_category_move(1);
    elseif (action == 'previous_item') then
        nav_menu_move(-1);
    elseif (action == 'repeat_item') then
        nav_menu_move(0);
    elseif (action == 'next_item') then
        nav_menu_move(1);
    end
end

accessxi.poll_nav_browser_hotkeys = function ()
    local now = tick();
    local foreground = accessxi.is_foreground_process();
    local chat_open = is_chat_input_open ~= nil and is_chat_input_open() or false;
    if (type(accessxi.navigation_hotkeys) ~= 'table'
        or type(accessxi.navigation_hotkeys.poll) ~= 'function') then
        return false;
    end

    local vk = accessxi.navigation_hotkeys.VK or {};
    local snapshot = {
        foreground = foreground,
        chat_open = chat_open,
        modifier_down = accessxi.accessibility_hotkey_modifier_held(),
        route_active = accessxi.nav_active == true,
        route_pending = accessxi.nav_zone_search_target ~= nil,
        now = now,
        keys = {
            I = accessxi.quick_status_key_down(tonumber(vk.I) or 0x49),
            U = accessxi.quick_status_key_down(tonumber(vk.U) or 0x55),
            O = accessxi.quick_status_key_down(tonumber(vk.O) or 0x4F),
            J = accessxi.quick_status_key_down(tonumber(vk.J) or 0x4A),
            K = accessxi.quick_status_key_down(tonumber(vk.K) or 0x4B),
            L = accessxi.quick_status_key_down(tonumber(vk.L) or 0x4C),
        },
    };
    local action = accessxi.navigation_hotkeys.poll(
        accessxi.navigation_hotkey_state, snapshot);
    if (action == nil) then
        return false;
    end
    nav_menu_handle_action(action);
    return true;
end

local function nav_find_point(query)
    nav_load_points();
    query = nav_clean_field(query):lower();
    local zone = nav_zone_id();
    local first_zone_match = nil;
    for _, point in ipairs(accessxi.nav_points) do
        if ((tonumber(point.zone) or 0) == zone) then
            if (first_zone_match == nil) then
                first_zone_match = point;
            end
            if (query ~= '' and tostring(point.name or ''):lower():contains(query)) then
                return point;
            end
        end
    end

    if (query == '') then
        return first_zone_match;
    end
    return nil;
end

accessxi.nav_clear_zone_search = function ()
    accessxi.nav_zone_search_target = nil;
    accessxi.nav_zone_search_query = '';
    accessxi.nav_zone_search_waiting_zone = 0;
    accessxi.nav_zone_search_waiting_from_zone = 0;
    accessxi.nav_zone_search_last_replan_tick = 0;
    if type(accessxi.nav_same_zone_reentry_clear) == 'function' then
        accessxi.nav_same_zone_reentry_clear();
    else
        accessxi.nav_same_zone_reentry_edges = T{};
        accessxi.nav_same_zone_reentry_index = 0;
        accessxi.nav_same_zone_reentry_origin_zone = 0;
        accessxi.nav_same_zone_reentry_neighbor_zone = 0;
    end
end

function accessxi.nav_copy_point(point)
    if (point == nil) then
        return nil;
    end

    local function copy_nested(value, seen)
        if (type(value) ~= 'table') then
            return value;
        end
        seen = seen or {};
        if (seen[value] ~= nil) then
            return seen[value];
        end
        local result = {};
        seen[value] = result;
        for key, child in pairs(value) do
            result[copy_nested(key, seen)] = copy_nested(child, seen);
        end
        return result;
    end

    return T{
        zone = tonumber(point.zone) or 0,
        name = nav_clean_field(point.name or ''),
        x = tonumber(point.x) or 0,
        z = tonumber(point.z) or 0,
        y = tonumber(point.y) or 0,
        kind = nav_clean_field(point.kind or ''),
        source = nav_clean_field(point.source or ''),
        confidence = nav_clean_field(point.confidence or ''),
        to_zone = tonumber(point.to_zone),
        to_zone_name = nav_clean_field(point.to_zone_name or ''),
        final_zone = tonumber(point.final_zone),
        final_name = nav_clean_field(point.final_name or ''),
        same_zone_reentry_step = tonumber(point.same_zone_reentry_step),
        same_zone_reentry_edge_id = tonumber(point.same_zone_reentry_edge_id),
        section = nav_clean_field(point.section or ''),
        distance = tonumber(point.distance) or 0,
        index = tonumber(point.index),
        server_id = tonumber(point.server_id),
        live_kind = nav_clean_field(point.live_kind or ''),
        live_nm = point.live_nm == true,
        arrival_radius = tonumber(point.arrival_radius),
        objective_kind = nav_clean_field(point.objective_kind or ''),
        objective_context = nav_clean_field(point.objective_context or ''),
        objective_area = nav_clean_field(point.objective_area or ''),
        objective_id = tonumber(point.objective_id),
        objective_stage = nav_clean_field(point.objective_stage or ''),
        objective_title = nav_clean_field(point.objective_title or ''),
        objective_instruction = nav_clean_field(point.objective_instruction or ''),
        arrival_instruction = nav_clean_field(point.arrival_instruction or ''),
        objective_source = nav_clean_field(point.objective_source or ''),
        objective_character_identity = nav_clean_field(point.objective_character_identity or ''),
        objective_world_id = tonumber(point.objective_world_id),
        objective_session_epoch = tonumber(point.objective_session_epoch),
        objective_native_key = nav_clean_field(point.objective_native_key or ''),
        guide_step_id = nav_clean_field(point.guide_step_id or ''),
        objective_guide_step_id = nav_clean_field(point.objective_guide_step_id or point.guide_step_id or ''),
        objective_candidate_id = nav_clean_field(point.objective_candidate_id or ''),
        objective_action_id = nav_clean_field(point.objective_action_id or ''),
        objective_group_id = type(point.objective_group_id) == 'string' and point.objective_group_id or nil,
        objective_destination_id = nav_clean_field(point.objective_destination_id or ''),
        destination_id = nav_clean_field(point.destination_id or ''),
        objective_classification = nav_clean_field(point.objective_classification or ''),
        objective_action_instruction = nav_clean_field(point.objective_action_instruction or ''),
