function accessxi.nav_start_authorized_objective_route(target, player)
    if (type(target) ~= 'table' or type(player) ~= 'table') then
        return 'The current objective target or player position is unavailable.', false;
    end
    local target_zone = tonumber(target.zone);
    local player_zone = tonumber(player.zone);
    local contract_id = nav_clean_field(target.objective_route_contract_id);
    if (target_zone == nil or player_zone == nil or contract_id == '') then
        return 'Verified objective route authorization is incomplete.', false;
    end
    if (type(accessxi.ensure_objective_route_runtime) ~= 'function') then
        return 'Verified objective route execution is unavailable.', false;
    end
    local runtime_ready, runtime_reason = accessxi.ensure_objective_route_runtime();
    if (runtime_ready ~= true) then
        return nav_clean_field(runtime_reason) ~= '' and nav_clean_field(runtime_reason)
            or 'Verified objective route execution is unavailable.', false;
    end
    local runtime = accessxi.objective_route_runtime;
    if (type(runtime) ~= 'table' or type(runtime.compute_exact_objective_leg) ~= 'function') then
        return 'Verified objective route execution is unavailable.', false;
    end
    if (player_zone ~= target_zone) then
        if (type(runtime.prepare_next_objective_prefix_leg) ~= 'function') then
            return 'No exact current objective leg is proven from this zone.', false;
        end
        local ok, descriptor, reason = pcall(
            runtime.prepare_next_objective_prefix_leg,
            runtime,
            contract_id,
            { zone = player_zone, x = player.x, z = player.z, y = player.y });
        if (not ok or type(descriptor) ~= 'table'
            or type(descriptor.waypoints) ~= 'table' or #descriptor.waypoints < 2) then
            return nav_clean_field(ok and reason or '') ~= '' and nav_clean_field(reason)
                or 'No exact current objective leg is proven from this zone.', false;
        end
        if (nav_clean_field(descriptor.objective_route_contract_id) ~= contract_id
            or type(descriptor.objective_contract_snapshot) ~= 'table'
            or descriptor.objective_contract_snapshot.contract_id ~= contract_id
            or tonumber(descriptor.from_zone) ~= player_zone) then
            return 'The rooted objective prefix authorization changed.', false;
        end
        local route = T{};
        for index, point in ipairs(descriptor.waypoints) do
            local x, z, y = tonumber(point.x), tonumber(point.z), tonumber(point.y);
            if (x == nil or z == nil or y == nil
                or x ~= x or z ~= z or y ~= y) then
                return 'The exact objective prefix returned a malformed waypoint.', false;
            end
            route:append(T{
                zone = player_zone,
                name = ('Objective prefix waypoint %d'):fmt(index),
                x = x, z = z, y = y,
                kind = 'route', source = 'objective-prefix-runtime',
            });
        end
        return accessxi.nav_activate_authorized_objective_points(
            target, player, route, nil, descriptor);
    end
    if (not nav_try_load_mesh(target_zone)) then
        return 'The rooted objective navmesh is unavailable for this zone.', false;
    end

    local contract = target.objective_contract_snapshot;
    local required_transitions = type(contract) == 'table'
        and contract.required_transition_ids or nil;
    if (type(required_transitions) == 'table' and #required_transitions > 0) then
        local last_reason = 'No rooted authorized objective transition can start from here.';
        for _, transition_id in ipairs(required_transitions) do
            local authorized_ok, definition, authorization_reason = pcall(
                runtime.authorize_transition,
                runtime,
                contract_id,
                transition_id);
            if (authorized_ok and type(definition) == 'table'
                and tonumber(definition.zone) == target_zone) then
                local authorization = T{
                    objective_kind = target.objective_kind,
                    objective_native_key = target.objective_native_key,
                    objective_guide_step_id = target.objective_guide_step_id,
                    objective_character_identity = target.objective_character_identity,
                    objective_world_id = target.objective_world_id,
                    objective_session_epoch = target.objective_session_epoch,
                    objective_candidate_id = target.objective_candidate_id,
                    objective_action_id = target.objective_action_id,
                    objective_group_id = target.objective_group_id,
                    objective_destination_id = target.objective_destination_id,
                    objective_route_contract_id = contract_id,
                    objective_transition_id = definition.transition_id,
                    objective_transition_revision = definition.transition_revision,
                    objective_transition_registry_sha256 = definition.source_registry_sha256,
                    objective_transition_direction = definition.direction,
                    objective_transition_zone = definition.zone,
                    objective_transition_pre_anchor = T{
                        zone = definition.zone,
                        x = definition.pre_anchor.x,
                        z = definition.pre_anchor.z,
                        y = definition.pre_anchor.y,
                    },
                    objective_transition_post_anchor = T{
                        zone = definition.zone,
                        x = definition.post_anchor.x,
                        z = definition.post_anchor.z,
                        y = definition.post_anchor.y,
                    },
                    objective_transition_expected_live_state = definition.expected_live_state,
                    objective_transition_timeout_seconds = definition.timeout_seconds,
                };
                local transition_route, transition_reason = accessxi.nav_objective_transport_start(
                    player,
                    target,
                    authorization);
                if (type(transition_route) == 'table' and #transition_route > 1) then
                    return accessxi.nav_activate_authorized_objective_points(
                        target,
                        player,
                        transition_route,
                        authorization);
                end
                last_reason = nav_clean_field(transition_reason) ~= ''
                    and nav_clean_field(transition_reason) or last_reason;
            elseif (authorized_ok and nav_clean_field(authorization_reason) ~= '') then
                last_reason = nav_clean_field(authorization_reason);
            end
        end
        return last_reason, false;
    end

    local points, reason = accessxi.nav_compute_exact_objective_leg({
        zone = target_zone,
        objective_route_contract_id = contract_id,
        start = { x = player.x, z = player.z, y = player.y, zone = player_zone },
        ['end'] = { x = target.x, z = target.z, y = target.y, zone = target_zone },
    });
    if (type(points) ~= 'table' or #points < 2) then
        reason = nav_clean_field(reason);
        if (reason == '') then
            reason = 'No exact current objective leg is proven from here.';
        end
        return reason, false;
    end
    local route = T{};
    for index, point in ipairs(points) do
        local x = tonumber(point.x);
        local z = tonumber(point.z);
        local y = tonumber(point.y);
        if (x == nil or z == nil or y == nil
            or x ~= x or z ~= z or y ~= y
            or x == math.huge or x == -math.huge
            or z == math.huge or z == -math.huge
            or y == math.huge or y == -math.huge) then
            return 'The exact objective route returned a malformed waypoint.', false;
        end
        route:append(T{
            zone = target_zone,
            name = ('Objective waypoint %d'):fmt(index),
            x = x,
            z = z,
            y = y,
            kind = 'route',
            source = 'objective-exact-runtime',
        });
    end

    return accessxi.nav_activate_authorized_objective_points(target, player, route, nil);
end

accessxi.load_code_module('same_zone_reentry_navigation', T{
    T = T,
    nav_distance = nav_distance,
    nav_compute_mesh_route = nav_compute_mesh_route,
    nav_clean_field = nav_clean_field,
    log_line = log_line,
});

function accessxi.nav_start_route_to_point(point, reason)
    if (point == nil) then
        return 'No destination selected.';
    end

    accessxi.nav_clear_zoning_watch('route-start');
    if (type(accessxi.nav_transport_clear) == 'function') then
        accessxi.nav_transport_clear('route-start');
    end
    if (type(accessxi.nav_dangruf_fount_drop_clear) == 'function') then
        accessxi.nav_dangruf_fount_drop_clear('route-start');
    end
    local player = nav_cached_player_position();
    local live_point = accessxi.nav_resolve_live_entity_point(point, player);
    if (live_point ~= nil) then
        point = live_point;
    end

    accessxi.nav_active = true;
    accessxi.nav_destination = point;
    accessxi.nav_last_key = '';
    accessxi.nav_last_direction_text = '';
    accessxi.nav_beacon_last_key = '';
    accessxi.nav_beacon_last_tick = 0;
    accessxi.nav_beacon_reset_direction_state();
    accessxi.nav_progress_x = nil;
    accessxi.nav_progress_z = nil;
    accessxi.nav_progress_distance = 0;
    accessxi.nav_progress_tick = tick();
    accessxi.nav_progress_last_block_tick = 0;
    accessxi.nav_progress_last_log_key = '';
    accessxi.nav_collision_x = nil;
    accessxi.nav_collision_z = nil;
    accessxi.nav_collision_destination_distance = 0;
    accessxi.nav_collision_route_distance = 0;
    accessxi.nav_collision_tick = 0;
    accessxi.nav_collision_last_sound_tick = 0;
    accessxi.nav_collision_last_key = '';
    accessxi.nav_door_wait_until = 0;
    accessxi.nav_door_pause_until = 0;
    accessxi.nav_door_x = nil;
    accessxi.nav_door_z = nil;
    accessxi.nav_door_route_unit_x = nil;
    accessxi.nav_door_route_unit_z = nil;
    accessxi.nav_door_wait_key = '';
    accessxi.nav_door_wait_name = '';
    accessxi.nav_obstacle_last_key = '';
    accessxi.nav_obstacle_last_tick = 0;
    accessxi.nav_wall_avoid_last_key = '';
    accessxi.nav_wall_avoid_last_tick = 0;
    accessxi.nav_route_point_index = 1;
    accessxi.nav_route_last_recalc_tick = tick();
    accessxi.nav_route_start_point = player ~= nil and T{ zone = player.zone, x = player.x, z = player.z, y = player.y, yaw = player.yaw } or nil;
    accessxi.nav_route_start_tick = tick();
    accessxi.nav_last_failure_key = '';
    accessxi.nav_last_failure_tick = 0;
    accessxi.nav_live_route_missing_since = 0;
    accessxi.nav_route_live_replan_last_key = '';
    accessxi.nav_route_live_replan_last_tick = 0;
    accessxi.nav_route_points = accessxi.nav_compute_route_with_zoneline_approach(player, point);
    if (accessxi.nav_dat_collision_pending ~= nil) then
        local pending_text = nav_clean_field(accessxi.nav_dat_collision_pending.message);
        pending_text = pending_text ~= '' and pending_text
            or 'Mapping terrain. Navigation will start automatically.';
        accessxi.nav_last_direction_text = pending_text;
        log_line(('collision terrain pending destination="%s" zone=%d'):fmt(
            accessxi.escape_probe_log_text(point.name or ''),
            tonumber(point.zone) or 0));
        return pending_text;
    end
    if (accessxi.nav_route_points:len() <= 1
        and nav_clean_field(accessxi.nav_route_last_reject_reason) ~= '') then
        local collision_text = nav_clean_field(accessxi.nav_route_last_reject_reason);
        accessxi.nav_active = false;
        accessxi.nav_destination = nil;
        accessxi.nav_route_points:clear();
        accessxi.nav_last_direction_text = collision_text;
        return collision_text;
    end
    local unsafe_route_text = accessxi.nav_route_direct_fallback_block_reason(player, point);
    if (accessxi.nav_route_points:len() <= 1
        and unsafe_route_text ~= ''
        and accessxi.nav_zone_search_target == nil
        and not tostring(point.source or ''):startswith('zonesearch:')
        and type(accessxi.nav_same_zone_reentry_start) == 'function') then
        local reentry_text = accessxi.nav_same_zone_reentry_start(player, point, reason or 'route-reentry');
        if reentry_text ~= nil and reentry_text ~= '' then
            if (type(accessxi.nav_mission_quest_start_suffix) == 'function') then
                reentry_text = reentry_text .. accessxi.nav_mission_quest_start_suffix(point);
            end
            return reentry_text;
        end
    end
    if (accessxi.nav_route_points:len() <= 1 and unsafe_route_text ~= '') then
        nav_write_route_evidence('unreachable', player, point, nil, T{ reason = unsafe_route_text });
        accessxi.nav_active = false;
        accessxi.nav_destination = nil;
        accessxi.nav_route_points:clear();
        accessxi.nav_last_direction_text = unsafe_route_text;
        return unsafe_route_text;
    end
    if (accessxi.nav_point_effective_kind(point) == 'area' and accessxi.nav_route_points:len() <= 1 and not accessxi.nav_area_point_direct_route_allowed(player, point) and not accessxi.nav_area_point_reachable(player, point)) then
        nav_write_route_evidence('unreachable', player, point, nil, T{ reason = tostring(reason or 'command') .. ' start unreachable' });
        accessxi.nav_active = false;
        accessxi.nav_destination = nil;
        accessxi.nav_route_points:clear();
        return ('%s is not reachable from here.'):fmt(point.name or 'Destination');
    end
    local phrase = accessxi.nav_guidance_phrase(player, point, nil);
    if (accessxi.nav_route_points:len() > 1) then
        local first_index = accessxi.nav_first_route_index(player, accessxi.nav_route_points, point);
        local first = accessxi.nav_route_points[first_index];
        local second = accessxi.nav_route_points[math.min(first_index + 1, accessxi.nav_route_points:len())];
        local first_phrase = accessxi.nav_guidance_phrase(player, first, second, false);
        accessxi.nav_route_point_index = first_index;
        local text;
        if (accessxi.nav_beacon_enabled) then
            text = ('Starting route to %s. %d waypoints. Beacon active.'):fmt(point.name or 'destination', accessxi.nav_route_points:len());
        else
            text = ('Starting route to %s. %d waypoints. Next, %s'):fmt(point.name or 'destination', accessxi.nav_route_points:len(), first_phrase);
        end
        if (type(accessxi.nav_transport_start_suffix) == 'function') then
            text = text .. accessxi.nav_transport_start_suffix();
        end
        if (type(accessxi.nav_dangruf_fount_drop_start_suffix) == 'function') then
            text = text .. accessxi.nav_dangruf_fount_drop_start_suffix();
        end
        if (type(accessxi.nav_mission_quest_start_suffix) == 'function') then
            text = text .. accessxi.nav_mission_quest_start_suffix(point);
        end
        accessxi.nav_last_direction_text = text;
        nav_write_route_evidence('start', player, point, first, T{ reason = reason or 'command' });
        return text;
    end
    local text;
    if (accessxi.nav_beacon_enabled) then
        text = ('Starting route to %s. Beacon active.'):fmt(point.name or 'destination');
    else
        text = ('Starting route to %s. %s'):fmt(point.name or 'destination', phrase);
    end
    if (type(accessxi.nav_mission_quest_start_suffix) == 'function') then
        text = text .. accessxi.nav_mission_quest_start_suffix(point);
    end
    accessxi.nav_last_direction_text = text;
    nav_write_route_evidence('start', player, point, point, T{ reason = reason or 'command' });
    return text;
end

function accessxi.nav_zone_search_npc_results(query, player)
    nav_load_points();
    if (type(accessxi.nav_load_zoneline_graph) == 'function') then
        accessxi.nav_load_zoneline_graph();
    end
    local graph_edges = type(accessxi.nav_zoneline_edges) == 'table'
        and accessxi.nav_zoneline_edges or T{};
    query = nav_clean_field(query);
    local results = {};
    if (query == '') then
        return results;
    end

    local current_zone = tonumber(player ~= nil and player.zone or nav_zone_id()) or 0;
    local query_key = accessxi.nav_search_text(query);
    local candidates = {};

    local graph_zones = {};
    for _, edge in ipairs(graph_edges) do
        local from_zone = tonumber(edge.from_zone) or 0;
        local to_zone = tonumber(edge.to_zone) or 0;
        if (from_zone > 0 and graph_zones[from_zone] == nil) then
            graph_zones[from_zone] = nav_clean_field(edge.from_name or '');
        end
        if (to_zone > 0 and graph_zones[to_zone] == nil) then
            graph_zones[to_zone] = nav_clean_field(edge.to_name or '');
        end
    end

    for zone, graph_name in pairs(graph_zones) do
        local zone_name = accessxi.nav_graph_zone_name(zone);
        if (zone_name == '' or zone_name == ('zone %d'):fmt(zone)) then
            zone_name = graph_name;
        end
        if (zone_name ~= '' and accessxi.nav_search_text(zone_name) == query_key) then
            local incoming = {};
            for _, edge in ipairs(graph_edges) do
                if ((tonumber(edge.to_zone) or 0) == zone) then
                    local path = T{};
                    local reachable = current_zone > 0 and current_zone == zone;
                    local path_len = reachable and 0 or 999999;
                    if (current_zone > 0 and current_zone ~= zone) then
                        path = accessxi.nav_zoneline_path(current_zone, zone, tonumber(edge.id) or 0);
                        reachable = path:len() > 0;
                        path_len = reachable and path:len() or 999999;
                    end
                    local rank = accessxi.nav_zoneline_edge_rank(edge, player);
                    table.insert(incoming, T{
                        edge = edge,
                        rank = rank,
                        reachable = reachable,
                        path_len = path_len,
                    });
                end
            end
            table.sort(incoming, function (a, b)
                if a.rank ~= b.rank then
                    return a.rank < b.rank;
                end
                if a.reachable ~= b.reachable then
                    return a.reachable == true;
                end
                if a.path_len ~= b.path_len then
                    return a.path_len < b.path_len;
                end
                return (tonumber(a.edge.id) or 0) < (tonumber(b.edge.id) or 0);
            end);

            local representative = incoming[1];
            if (representative ~= nil and representative.edge ~= nil) then
                local edge = representative.edge;
                local candidate = T{
                    zone = zone,
                    name = zone_name,
                    x = tonumber(edge.to_x) or 0,
                    z = tonumber(edge.to_z) or 0,
                    y = tonumber(edge.to_y) or 0,
                    kind = 'area',
                    source = 'zone-search:graph-zone:' .. tostring(zone),
                    confidence = nav_clean_field(edge.confidence or ''),
                    section = 'global zone',
                    zone_search_exact = true,
                    zone_search_reachable = representative.reachable,
                    zone_search_path_len = representative.path_len,
                    zone_search_result = true,
                    zone_search_zone_result = true,
                    zone_search_query = query,
                    zone_search_player_distance = player ~= nil and current_zone == zone
                        and nav_distance(player, T{ x = edge.to_x, z = edge.to_z, y = edge.to_y }) or 999999,
                    zone_search_canonical_edge_id = tonumber(edge.id) or 0,
                    zone_search_canonical_from_zone = tonumber(edge.from_zone) or 0,
                };
                table.insert(candidates, candidate);
            end
        end
    end

    for _, point in ipairs(accessxi.nav_points) do
        if (nav_clean_field(point.name or '') ~= ''
            and accessxi.nav_point_effective_kind(point) == 'npc'
            and accessxi.nav_point_matches_search(point, query)) then
            local candidate = accessxi.nav_copy_point(point);
            local target_zone = tonumber(candidate.zone) or 0;
            local path_len = 999999;
            local reachable = false;
            if (current_zone > 0 and target_zone == current_zone) then
                path_len = 0;
                reachable = true;
            elseif (current_zone > 0 and target_zone > 0) then
                local path = accessxi.nav_zoneline_path(current_zone, target_zone);
                if (path:len() > 0) then
                    path_len = path:len();
                    reachable = true;
                end
            end
            candidate.zone_search_exact = accessxi.nav_search_text(candidate.name or '') == query_key;
            candidate.zone_search_reachable = reachable;
            candidate.zone_search_path_len = path_len;
            candidate.zone_search_result = true;
            candidate.zone_search_query = query;
            candidate.zone_search_player_distance = player ~= nil and nav_distance(player, candidate) or 999999;
            table.insert(candidates, candidate);
        end
    end

    local function representative_less(a, b)
        local ar = nav_point_source_rank(a);
        local br = nav_point_source_rank(b);
        if (ar ~= br) then
            return ar < br;
        end
        local ad = tonumber(a.zone_search_player_distance) or 999999;
        local bd = tonumber(b.zone_search_player_distance) or 999999;
        if (ad ~= bd) then
            return ad < bd;
        end
        local aid = nav_clean_field(a.destination_id or ''):lower();
        local bid = nav_clean_field(b.destination_id or ''):lower();
        if (aid ~= bid) then
            return aid < bid;
        end
        local ari = nav_clean_field(a.raw_identity or ''):lower();
        local bri = nav_clean_field(b.raw_identity or ''):lower();
        if (ari ~= bri) then
            return ari < bri;
        end
        local asource = nav_clean_field(a.source or ''):lower();
        local bsource = nav_clean_field(b.source or ''):lower();
        if (asource ~= bsource) then
            return asource < bsource;
        end
        if ((tonumber(a.zone) or 0) ~= (tonumber(b.zone) or 0)) then
            return (tonumber(a.zone) or 0) < (tonumber(b.zone) or 0);
        end
        local aname = accessxi.nav_search_text(a.name or '');
        local bname = accessxi.nav_search_text(b.name or '');
        if (aname ~= bname) then
            return aname < bname;
        end
        if ((tonumber(a.x) or 0) ~= (tonumber(b.x) or 0)) then
            return (tonumber(a.x) or 0) < (tonumber(b.x) or 0);
        end
        if ((tonumber(a.z) or 0) ~= (tonumber(b.z) or 0)) then
            return (tonumber(a.z) or 0) < (tonumber(b.z) or 0);
        end
        return (tonumber(a.y) or 0) < (tonumber(b.y) or 0);
    end

    table.sort(candidates, representative_less);
    local presented = {};
    for _, candidate in ipairs(candidates) do
        local duplicate = false;
        local candidate_zone = tonumber(candidate.zone) or 0;
        local candidate_kind = accessxi.nav_point_effective_kind(candidate);
        local candidate_name = accessxi.nav_search_text(candidate.name or '');
        for _, representative in ipairs(presented) do
            if ((tonumber(representative.zone) or 0) == candidate_zone
                and accessxi.nav_point_effective_kind(representative) == candidate_kind
                and accessxi.nav_search_text(representative.name or '') == candidate_name) then
                local dx = (tonumber(representative.x) or 0) - (tonumber(candidate.x) or 0);
                local dz = (tonumber(representative.z) or 0) - (tonumber(candidate.z) or 0);
                local dy = math.abs((tonumber(representative.y) or 0) - (tonumber(candidate.y) or 0));
                if (((dx * dx) + (dz * dz)) <= 0.25 and dy <= 0.5) then
                    duplicate = true;
                    break;
                end
            end
        end
        if (not duplicate) then
            table.insert(presented, candidate);
        end
    end
    candidates = presented;

    table.sort(candidates, function (a, b)
        if (a.zone_search_exact ~= b.zone_search_exact) then
            return a.zone_search_exact == true;
        end
        if (a.zone_search_reachable ~= b.zone_search_reachable) then
            return a.zone_search_reachable == true;
        end
        local ap = tonumber(a.zone_search_path_len) or 999999;
        local bp = tonumber(b.zone_search_path_len) or 999999;
        if (ap ~= bp) then
            return ap < bp;
        end
        local ar = nav_point_source_rank(a);
        local br = nav_point_source_rank(b);
        if (ar ~= br) then
            return ar < br;
        end
        if ((tonumber(a.zone) or 0) ~= (tonumber(b.zone) or 0)) then
            return (tonumber(a.zone) or 0) < (tonumber(b.zone) or 0);
        end
        return tostring(a.name or '') < tostring(b.name or '');
    end);

    return candidates;
end

function accessxi.nav_find_zone_search_npc(query, player)
    local results = accessxi.nav_zone_search_npc_results(query, player);
    return results[1], #results;
end

function accessxi.nav_zone_search_start_next_leg(reason)
    local target = accessxi.nav_zone_search_target;
    if (target == nil) then
        return 'No pending zone search target.';
    end

    local player = nav_cached_player_position();
    if (player == nil) then
        return 'Position unavailable.';
    end

    local player_zone = tonumber(player.zone) or 0;
    local target_zone = tonumber(target.zone) or 0;
    local target_zone_name = accessxi.nav_graph_zone_name(target_zone);
    local route_context = type(accessxi.nav_mission_quest_route_context) == 'function'
        and accessxi.nav_mission_quest_route_context(target) or '';
    route_context = nav_clean_field(route_context);
    route_context = route_context ~= '' and route_context or 'Zone search';
    if type(accessxi.nav_same_zone_reentry_active) == 'function' and accessxi.nav_same_zone_reentry_active() then
        local leg, reentry_status = accessxi.nav_same_zone_reentry_current_leg(player);
        if reentry_status == 'complete' then
            accessxi.nav_same_zone_reentry_clear();
        elseif reentry_status == 'waiting' then
            return ('Safe re-entry route to %s is waiting for the zone change.'):fmt(accessxi.speech_name(target.name or 'destination'));
        elseif reentry_status ~= 'leg' or leg == nil then
            local current_zone_name = accessxi.nav_graph_zone_name(player_zone);
            accessxi.nav_clear_zone_search();
            return ('Safe re-entry route stopped after an unexpected zone in %s.'):fmt(current_zone_name);
        else
            accessxi.nav_zone_search_waiting_zone = 0;
            accessxi.nav_zone_search_waiting_from_zone = 0;
            local start_text = accessxi.nav_start_route_to_point(leg, reason or 'same-zone-reentry');
            if not accessxi.nav_active then
                accessxi.nav_clear_zone_search();
                return ('Safe re-entry route to %s stopped. %s'):fmt(accessxi.speech_name(target.name or 'destination'), start_text);
            end
            local step = tonumber(leg.same_zone_reentry_step) or 1;
            local text = ('Safe re-entry route to %s. Crossing %d of 2 through %s. %s'):fmt(
                accessxi.speech_name(target.name or 'destination'),
                step,
                accessxi.nav_graph_zone_name(tonumber(leg.to_zone) or 0),
                start_text);
            accessxi.nav_last_direction_text = text;
            return text;
        end
    end
    if (player_zone == target_zone) then
        accessxi.nav_zone_search_waiting_zone = 0;
        accessxi.nav_zone_search_waiting_from_zone = 0;
        local start_text = accessxi.nav_start_route_to_point(target, reason or 'zone-search-final');
        if (not accessxi.nav_active) then
            accessxi.nav_clear_zone_search();
            return start_text;
        end
        local text = ('%s. Target zone reached. %s is in %s. %s'):fmt(route_context, accessxi.speech_name(target.name or 'NPC'), target_zone_name, start_text);
        accessxi.nav_last_direction_text = text;
        return text;
    end

    local canonical_edge_id = tonumber(target.zone_search_canonical_edge_id
        or target.objective_canonical_edge_id) or 0;
    local canonical_from_zone = tonumber(target.zone_search_canonical_from_zone
        or target.objective_canonical_from_zone) or 0;
    local path = accessxi.nav_zoneline_path(player.zone, target.zone, canonical_edge_id);
    if (canonical_edge_id > 0) then
        local final_edge = path[path:len()];
        if (canonical_from_zone <= 0 or final_edge == nil
            or (tonumber(final_edge.id) or 0) ~= canonical_edge_id
            or (tonumber(final_edge.from_zone) or 0) ~= canonical_from_zone
            or (tonumber(final_edge.to_zone) or 0) ~= target_zone) then
            path = T{};
        end
    elseif (canonical_from_zone > 0) then
        path = T{};
    end
    if (path:len() == 0) then
        accessxi.nav_clear_zone_search();
        local current_zone_name = accessxi.nav_graph_zone_name(player_zone);
        return ('%s is in %s. No zone route known from %s.'):fmt(accessxi.speech_name(target.name or 'NPC'), target_zone_name, current_zone_name);
    end

    local edge = path[1];
    local next_zone = tonumber(edge.to_zone) or 0;
    local next_zone_name = accessxi.nav_graph_zone_name(next_zone);
    local leg = T{
        zone = player_zone,
        name = ('%s zone line'):fmt(next_zone_name ~= '' and next_zone_name or nav_clean_field(edge.to_name or 'next zone')),
        x = tonumber(edge.from_x) or 0,
        z = tonumber(edge.from_z) or 0,
        y = tonumber(edge.from_y) or 0,
        kind = 'area',
        source = ('zonesearch:%d:%d:%d'):fmt(edge.id or 0, player_zone, target_zone),
        confidence = nav_clean_field(edge.confidence or ''),
        section = ('zonesearch to %s'):fmt(target.name or 'NPC'),
        to_zone = next_zone,
        to_zone_name = next_zone_name,
        final_zone = target_zone,
        final_name = target.name or 'NPC',
    };

    accessxi.nav_zone_search_waiting_zone = next_zone;
    accessxi.nav_zone_search_waiting_from_zone = player_zone;
    local start_text = accessxi.nav_start_route_to_point(leg, reason or 'zone-search');
    if (not accessxi.nav_active) then
        accessxi.nav_clear_zone_search();
        return ('%s. %s is in %s. %s'):fmt(route_context, accessxi.speech_name(target.name or 'NPC'), target_zone_name, start_text);
    end
    local text = ('%s. %s is in %s. Route %d zones. First, %s'):fmt(
        route_context,
        accessxi.speech_name(target.name or 'NPC'),
        target_zone_name,
        path:len(),
        start_text);
    accessxi.nav_last_direction_text = text;
    return text;
end

function accessxi.nav_zone_search_start(query)
    query = nav_clean_field(query);
    if (query == '') then
        return 'Zone search needs a destination or zone name.';
    end

    local player = nav_cached_player_position();
    if (player == nil) then
        return 'Position unavailable.';
    end

    local results = accessxi.nav_zone_search_npc_results(query, player);
    if (#results == 0) then
        return ('No destination or zone matched %s.'):fmt(query);
    end

    accessxi.nav_clear_zone_search();
    accessxi.nav_zone_search_query = query;
    accessxi.nav_menu_category = 1;
    accessxi.nav_menu_search_query = query;
    accessxi.nav_menu_search_results = T{};
    accessxi.nav_menu_search_result_query = query;
    accessxi.nav_menu_items = T{};
    for _, item in ipairs(results) do
        accessxi.nav_menu_search_results:append(item);
        accessxi.nav_menu_items:append(item);
    end

    accessxi.nav_menu_category = accessxi.nav_search_category_index();
    if (accessxi.nav_menu_category <= 0) then
        accessxi.nav_menu_category = 1;
    end
    accessxi.nav_menu_open = false;
    accessxi.nav_menu_index = 1;
    accessxi.nav_menu_last_key_tick = 0;
    accessxi.nav_menu_poll_key = 0;
    accessxi.nav_menu_poll_tick = 0;
    accessxi.nav_menu_open_tick = tick();
    local text = nav_menu_item_speech();
    return text .. ' U selects the previous category. O selects the next category. J selects the previous destination. K repeats. L selects the next destination. I starts the selected route or stops active navigation.';
end

function accessxi.poll_nav_zone_search()
    if (accessxi.nav_zone_search_target == nil or accessxi.nav_active) then
        return false;
    end
    if (type(accessxi.nav_mission_quest_route_owner_mismatch) == 'function'
        and accessxi.nav_mission_quest_route_owner_mismatch()) then
        if (accessxi.nav_cancel_mission_quest_route('pending-route-owner-mismatch')) then
            local text = 'Mission or quest route stopped because the active character changed.';
            speak(text);
            log_line('nav objective pending owner mismatch');
        end
        return true;
    end

    local player = nav_cached_player_position();
    if (player == nil) then
        return false;
    end

    local waiting_zone = tonumber(accessxi.nav_zone_search_waiting_zone) or 0;
    local waiting_from_zone = tonumber(accessxi.nav_zone_search_waiting_from_zone) or 0;
    if (waiting_zone > 0 and waiting_from_zone > 0) then
        local player_zone = tonumber(player.zone) or 0;
        if (player_zone == waiting_from_zone) then
            return false;
        end
        if (player_zone ~= waiting_zone) then
            if (type(accessxi.nav_cancel_mission_quest_route) == 'function'
                and accessxi.nav_cancel_mission_quest_route('pending-route-unexpected-zone')) then
                speak('Mission or quest route stopped after an unexpected zone change.');
                log_line('nav objective pending unexpected zone');
                return true;
            end
            return false;
        end
    end

    local now = tick();
    if ((now - (tonumber(accessxi.nav_zone_search_last_replan_tick) or 0)) < 2500) then
        return false;
    end

    accessxi.nav_zone_search_last_replan_tick = now;
    local text = accessxi.nav_zone_search_start_next_leg('zone-search-resume');
    speak(text);
    log_line('nav zone search resume ' .. text);
    return true;
end

local function nav_focus_target_position()
    local target = safe_call(function () return AshitaCore:GetMemoryManager():GetTarget(); end, nil);
    if (target == nil) then
        return nil;
    end

    local index = tonumber(safe_call(function () return target:GetFocusTargetIndex(); end, -1)) or -1;
    return nav_entity_position(index);
end

function accessxi.ashita_console_bool(label, fn, help)
    local ok, value = pcall(fn);
    local text = '';
    if (not ok or value == nil) then
        text = ('%s unavailable from Ashita Lua.'):fmt(label);
    else
        text = ('%s %s.'):fmt(label, (value == true or tonumber(value) == 1) and 'enabled' or 'disabled');
    end

    if (help ~= nil and help ~= '') then
        text = text .. ' ' .. tostring(help);
    end
    return text;
end

function accessxi.ashita_console_count(label, fn)
    local ok, value = pcall(fn);
    if (not ok or value == nil) then
        return ('%s count unavailable from Ashita Lua.'):fmt(label);
    end
    return ('%s loaded: %d.'):fmt(label, tonumber(value) or 0);
end

function accessxi.ashita_console_boot_script_path()
    local install_path = safe_call(function () return AshitaCore:GetInstallPath(); end, accessxi.ashita_root);
    install_path = tostring(install_path or accessxi.ashita_root):gsub('[\\/]*$', '\\');
    return install_path .. 'scripts\\default.txt';
end

function accessxi.ashita_console_bind_key_speech(key)
    key = tostring(key or ''):trim();
    if (key == '') then
        return 'blank key';
    end

    local parts = T{};
    local rest = key;
    if (rest:find('%^', 1, false) ~= nil) then
        parts:append('Control');
        rest = rest:gsub('%^', '');
    end
    if (rest:find('!', 1, true) ~= nil) then
        parts:append('Alt');
        rest = rest:gsub('!', '');
    end
    if (rest:find('%+', 1, false) ~= nil) then
        parts:append('Shift');
        rest = rest:gsub('%+', '');
    end
    if (rest:find('$', 1, true) ~= nil) then
        parts:append('Dollar modifier');
        rest = rest:gsub('%$', '');
    end
    rest = rest:trim();
    if (rest ~= '') then
        parts:append(rest:upper());
    end
    return parts:concat(' ');
end

function accessxi.ashita_console_boot_entries(kind, limit)
    local path = accessxi.ashita_console_boot_script_path();
    local f = io.open(path, 'r');
    if (f == nil) then
        return 'Default Ashita script unavailable.';
    end

    local entries = T{};
    local count = 0;
    limit = tonumber(limit) or 8;
    for line in f:lines() do
        local bind_key, bind_command = line:match('^%s*/bind%s+([^%s]+)%s+(.+)%s*$');
        local alias_name, alias_command = line:match('^%s*/alias%s+([^%s]+)%s+(.+)%s*$');
        local load_command = line:match('^%s*/(addon%s+load%s+.+)%s*$') or line:match('^%s*/(load%s+.+)%s*$');
        if (kind == 'bind' and bind_key ~= nil and bind_command ~= nil) then
            count = count + 1;
            if (entries:len() < limit) then
                entries:append(('%s to %s'):fmt(accessxi.ashita_console_bind_key_speech(bind_key), bind_command));
            end
        elseif (kind == 'alias' and alias_name ~= nil and alias_command ~= nil) then
            count = count + 1;
            if (entries:len() < limit) then
                entries:append(('%s to %s'):fmt(alias_name, alias_command));
            end
        elseif (kind == 'load' and load_command ~= nil) then
            count = count + 1;
            if (entries:len() < limit) then
                entries:append('/' .. load_command);
            end
        end
    end
    f:close();

    if (kind == 'bind') then
        if (count == 0) then
            return 'Current Keybinds. No bind entries found in the default Ashita script.';
        end
        return ('Current Keybinds. Default Ashita script has %d bind entries. First entries: %s.'):fmt(count, entries:concat('; '));
    elseif (kind == 'alias') then
        if (count == 0) then
            return 'Current Aliases. No alias entries found in the default Ashita script.';
        end
        return ('Current Aliases. Default Ashita script has %d alias entries. First entries: %s.'):fmt(count, entries:concat('; '));
    end

    if (count == 0) then
        return 'Plugin and addon startup commands. No load entries found in the default Ashita script.';
    end
    return ('Plugin and addon startup commands. Default Ashita script has %d load entries. First entries: %s.'):fmt(count, entries:concat('; '));
end

function accessxi.ashita_console_logging_level_text()
    local level = safe_call(function () return AshitaCore:GetConfigurationManager():GetInt32('boot', 'ashita.logging', 'level', -1); end, nil);
    local names = T{ [0] = 'None', [1] = 'Critical', [2] = 'Error', [3] = 'Warn', [4] = 'Info', [5] = 'Debug' };
    if (level == nil or tonumber(level) == nil or tonumber(level) < 0) then
        return 'Logging Level unavailable from Ashita Lua.';
    end
    return ('Logging Level %s.'):fmt(names[tonumber(level)] or tostring(level));
end

function accessxi.ashita_console_fill_mode_text()
    local fill_mode = safe_call(function () return AshitaCore:GetProperties():GetD3DFillMode(); end, nil);
    local names = T{ [0] = 'Default', [1] = 'Point', [2] = 'Wireframe', [3] = 'Solid' };
    if (fill_mode == nil or tonumber(fill_mode) == nil) then
        return 'Fill Mode unavailable from Ashita Lua.';
    end
    return ('Fill Mode %s. Sets the overall rendering fill mode.'):fmt(names[tonumber(fill_mode)] or tostring(fill_mode));
end

function accessxi.ashita_console_color_text()
    local color = safe_call(function () return AshitaCore:GetProperties():GetD3DAmbientColor(); end, nil);
    if (color == nil or tonumber(color) == nil) then
        return 'Ambient lighting color unavailable from Ashita Lua.';
    end
    return ('Ambient lighting color 0x%08X.'):fmt(tonumber(color) or 0);
end

