function accessxi.ashita_console_find_category(query)
    query = tostring(query or ''):trim():lower();
    if (query == '') then
        return nil;
    end

    local categories = accessxi.ashita_console_categories();
    for _, category in ipairs(categories) do
        if (query == category.id or tostring(category.label or ''):lower():find(query, 1, true) ~= nil) then
            return category;
        end
        for _, alias in ipairs(category.aliases or T{}) do
            if (query == tostring(alias or ''):lower()) then
                return category;
            end
        end
    end
    return nil;
end

function accessxi.ashita_console_summary()
    local categories = accessxi.ashita_console_categories();
    local labels = T{};
    for _, category in ipairs(categories) do
        labels:append(category.label);
    end
    return ('Ashita Settings. Sections: %s. Use /axi console section name to read a submenu.'):fmt(labels:concat('; '));
end

function accessxi.ashita_console_read_section(query)
    local category = accessxi.ashita_console_find_category(query);
    if (category == nil) then
        return ('Ashita Settings. No section named %s. %s'):fmt(tostring(query or ''), accessxi.ashita_console_summary());
    end

    local ok, text = pcall(category.read);
    if (not ok or text == nil or tostring(text):trim() == '') then
        return ('%s unavailable.'):fmt(category.label);
    end
    return tostring(text);
end

function accessxi.ashita_console_queue_command(command)
    return pcall(function ()
        local chat = AshitaCore:GetChatManager();
        if (chat == nil) then
            error('chat manager unavailable');
        end
        chat:QueueCommand(1, command);
    end);
end

function accessxi.ashita_console_toggle_bool(label, get_fn, set_fn)
    local ok_get, value = pcall(get_fn);
    if (not ok_get or value == nil) then
        return ('%s unavailable from Ashita Lua.'):fmt(label);
    end

    local enabled = (value == true or tonumber(value) == 1);
    local new_value = not enabled;
    local ok_set, err = pcall(function () set_fn(new_value); end);
    if (not ok_set) then
        return ('%s could not be changed. %s'):fmt(label, tostring(err or ''));
    end
    return ('%s %s.'):fmt(label, new_value and 'enabled' or 'disabled');
end

function accessxi.ashita_console_command_action(label, command)
    local ok = accessxi.ashita_console_queue_command(command);
    if (ok) then
        return ('%s command sent.'):fmt(label);
    end
    return ('%s command could not be sent.'):fmt(label);
end

function accessxi.ashita_console_reload_addon()
    accessxi.ashita_console_queue_command('/addon reload accessxi_reader');
    return 'Reloading AccessXI Reader.';
end

function accessxi.ashita_console_row(label, speech_fn, action_fn)
    return T{
        label = label,
        speech = speech_fn,
        action = action_fn,
    };
end

function accessxi.ashita_console_rows_for_category(category)
    local id = tostring(type(category) == 'table' and category.id or category or '');
    if (id == 'about') then
        return T{
            accessxi.ashita_console_row('Version Information', function () return 'Version Information. Ashita v4.'; end),
            accessxi.ashita_console_row('Donations - Say Thanks!', function () return 'Donations - Say Thanks!'; end),
            accessxi.ashita_console_row('Project Links', function () return 'Project Links.'; end),
            accessxi.ashita_console_row('Ashita Credits', function () return 'Ashita Credits.'; end),
        };
    elseif (id == 'chat') then
        return T{
            accessxi.ashita_console_row(
                'Enable Silent Aliases',
                function () return accessxi.ashita_console_bool('Enable Silent Aliases', function () return AshitaCore:GetChatManager():GetSilentAliases(); end, 'When enabled, prevents most chat output from alias commands.'); end,
                function () return accessxi.ashita_console_toggle_bool('Enable Silent Aliases', function () return AshitaCore:GetChatManager():GetSilentAliases(); end, function (value) AshitaCore:GetChatManager():SetSilentAliases(value); end); end),
        };
    elseif (id == 'd3d') then
        return T{
