                function ()
                    local value = tonumber(safe_call(function () return AshitaCore:GetProperties():GetD3DFillMode(); end, 3)) or 3;
                    local next_value = value + 1;
                    if (next_value > 3 or next_value < 1) then
                        next_value = 1;
                    end
