                function () return accessxi.ashita_console_toggle_bool('Block Input', function () return AshitaCore:GetInputManager():GetKeyboard():GetBlockInput(); end, function (value) AshitaCore:GetInputManager():GetKeyboard():SetBlockInput(value); end); end),
