function accessxi.ashita_console_current_category()
    local categories = accessxi.ashita_console_categories();
    local total = categories:len();
    if (total == 0) then
        return nil, categories;
    end
    accessxi.ashita_console_category_index = math.max(1, math.min(tonumber(accessxi.ashita_console_category_index) or 1, total));
    return categories[accessxi.ashita_console_category_index], categories;
end

function accessxi.ashita_console_current_rows()
    local category = accessxi.ashita_console_current_category();
    if (category == nil) then
        return T{};
    end
    return accessxi.ashita_console_rows_for_category(category);
end

function accessxi.ashita_console_current_row()
    local rows = accessxi.ashita_console_current_rows();
    local total = rows:len();
    if (total == 0) then
        accessxi.ashita_console_row_index = 1;
        return nil, rows;
    end
    accessxi.ashita_console_row_index = math.max(1, math.min(tonumber(accessxi.ashita_console_row_index) or 1, total));
    return rows[accessxi.ashita_console_row_index], rows;
end

function accessxi.ashita_console_speech()
    if (accessxi.ashita_console_level == 'submenu') then
        local category = accessxi.ashita_console_current_category();
        local row, rows = accessxi.ashita_console_current_row();
        if (category == nil or row == nil) then
            return 'Ashita Settings. No rows available.';
        end

        local ok, text = pcall(row.speech);
        if (not ok or text == nil or tostring(text):trim() == '') then
            text = tostring(row.label or 'row');
        end
        local action_text = row.action ~= nil and ' Control Shift Numpad 6 toggles or activates. Control Shift Numpad 4 goes back. Control Shift Numpad 0 reloads AccessXI.' or ' Read only. Control Shift Numpad 4 goes back. Control Shift Numpad 0 reloads AccessXI.';
        return ('%s. %s. %d of %d.%s'):fmt(category.label, tostring(text), accessxi.ashita_console_row_index, rows:len(), action_text);
    end

    local category, categories = accessxi.ashita_console_current_category();
    if (category == nil) then
        return 'Ashita Settings. No sections available.';
    end
    return ('Ashita Settings. %s. %d of %d. Control Shift Numpad 8 and 2 move. Control Shift Numpad 6 opens. Control Shift Numpad 0 reloads AccessXI.'):fmt(category.label, accessxi.ashita_console_category_index, categories:len());
end

function accessxi.ashita_console_speak_current(reason)
    local text = accessxi.ashita_console_speech();
    speak(text);
    log_state(('state ashita-console-menu reason="%s" level="%s" category=%d row=%d text="%s"'):fmt(
        accessxi.escape_probe_log_text(reason or ''),
        accessxi.escape_probe_log_text(accessxi.ashita_console_level or ''),
        tonumber(accessxi.ashita_console_category_index) or 0,
        tonumber(accessxi.ashita_console_row_index) or 0,
        accessxi.escape_probe_log_text_wide(text)));
end

function accessxi.ashita_console_open_menu(toggle_window)
    accessxi.ashita_console_open = true;
    accessxi.ashita_console_level = 'main';
    accessxi.ashita_console_category_index = 1;
    accessxi.ashita_console_row_index = 1;
    if (toggle_window ~= false) then
        accessxi.ashita_console_toggle_window();
    end
    accessxi.ashita_console_speak_current('open');
end

function accessxi.ashita_console_close_menu(toggle_window)
    if (not accessxi.ashita_console_open) then
        return;
    end
    accessxi.ashita_console_open = false;
    accessxi.ashita_console_level = 'main';
    accessxi.ashita_console_row_index = 1;
    if (toggle_window ~= false) then
        accessxi.ashita_console_toggle_window();
    end
    speak('Ashita Settings closed.');
    log_state('state ashita-console-menu closed');
end

function accessxi.ashita_console_move(delta)
    delta = tonumber(delta) or 0;
    if (accessxi.ashita_console_level == 'submenu') then
        local rows = accessxi.ashita_console_current_rows();
        local total = rows:len();
        if (total == 0) then
            accessxi.ashita_console_speak_current('move-empty');
            return;
        end
        accessxi.ashita_console_row_index = accessxi.ashita_console_row_index + delta;
        if (accessxi.ashita_console_row_index < 1) then
            accessxi.ashita_console_row_index = total;
        elseif (accessxi.ashita_console_row_index > total) then
            accessxi.ashita_console_row_index = 1;
        end
        accessxi.ashita_console_speak_current('move-row');
        return;
    end

    local categories = accessxi.ashita_console_categories();
    local total = categories:len();
    if (total == 0) then
        accessxi.ashita_console_speak_current('move-empty');
        return;
    end
    accessxi.ashita_console_category_index = accessxi.ashita_console_category_index + delta;
    if (accessxi.ashita_console_category_index < 1) then
        accessxi.ashita_console_category_index = total;
    elseif (accessxi.ashita_console_category_index > total) then
        accessxi.ashita_console_category_index = 1;
    end
    accessxi.ashita_console_speak_current('move-section');
end

function accessxi.ashita_console_open_current()
    if (accessxi.ashita_console_level == 'submenu') then
        accessxi.ashita_console_activate_current();
        return;
    end
    accessxi.ashita_console_level = 'submenu';
    accessxi.ashita_console_row_index = 1;
    accessxi.ashita_console_speak_current('open-section');
end

function accessxi.ashita_console_back()
    if (accessxi.ashita_console_level == 'submenu') then
        accessxi.ashita_console_level = 'main';
        accessxi.ashita_console_row_index = 1;
        accessxi.ashita_console_speak_current('back');
        return;
    end
    accessxi.ashita_console_close_menu();
end

function accessxi.ashita_console_activate_current()
    local row = accessxi.ashita_console_current_row();
    if (row == nil) then
        speak('No Ashita Settings row selected.');
        return;
    end
    if (row.action == nil) then
        accessxi.ashita_console_speak_current('read-only');
        return;
    end

    local ok, text = pcall(row.action);
    if (not ok or text == nil or tostring(text):trim() == '') then
        text = ('%s could not be activated.'):fmt(tostring(row.label or 'row'));
    end
    speak(tostring(text));
    log_state(('state ashita-console-action label="%s" text="%s"'):fmt(
        accessxi.escape_probe_log_text(row.label or ''),
        accessxi.escape_probe_log_text_wide(text)));
end

function accessxi.ashita_console_handle_key(key)
    key = tonumber(key) or 0;
    if (key == VK_UP) then
        accessxi.ashita_console_move(-1);
        return true;
    elseif (key == VK_DOWN) then
        accessxi.ashita_console_move(1);
        return true;
    elseif (key == VK_RIGHT or key == VK_RETURN) then
        accessxi.ashita_console_open_current();
        return true;
    elseif (key == VK_LEFT) then
        accessxi.ashita_console_back();
        return true;
    elseif (key == VK_ESCAPE) then
        accessxi.ashita_console_close_menu();
        return true;
    end
    return false;
end

function accessxi.ashita_console_hotkey_key_name(key)
    key = tonumber(key) or 0;
    if (key == accessxi.VK_NUMPAD8) then
        return 'Control Shift Numpad 8';
    elseif (key == accessxi.VK_NUMPAD2) then
        return 'Control Shift Numpad 2';
    elseif (key == accessxi.VK_NUMPAD6) then
        return 'Control Shift Numpad 6';
    elseif (key == accessxi.VK_NUMPAD4) then
        return 'Control Shift Numpad 4';
    elseif (key == accessxi.VK_NUMPAD5) then
        return 'Control Shift Numpad 5';
    elseif (key == accessxi.VK_NUMPAD0) then
        return 'Control Shift Numpad 0';
    end
    return tostring(key);
end

function accessxi.ashita_console_handle_hotkey(key)
    key = tonumber(key) or 0;
    if (key == accessxi.VK_NUMPAD8) then
        accessxi.ashita_console_move(-1);
        return true;
    elseif (key == accessxi.VK_NUMPAD2) then
        accessxi.ashita_console_move(1);
        return true;
    elseif (key == accessxi.VK_NUMPAD6) then
        accessxi.ashita_console_open_current();
        return true;
    elseif (key == accessxi.VK_NUMPAD4) then
        accessxi.ashita_console_back();
        return true;
    elseif (key == accessxi.VK_NUMPAD5) then
        accessxi.ashita_console_speak_current('hotkey-read');
        return true;
    elseif (key == accessxi.VK_NUMPAD0) then
        local text = accessxi.ashita_console_reload_addon();
        speak(text);
        log_state(('state ashita-console-action label="Reload AccessXI Reader" text="%s"'):fmt(accessxi.escape_probe_log_text_wide(text)));
        return true;
    end
    return false;
end

function accessxi.poll_ashita_console_hotkeys()
    if (not accessxi.ashita_console_open) then
        accessxi.ashita_console_hotkey_key = 0;
        return false;
    end
    if (not accessxi.is_foreground_process()) then
        accessxi.ashita_console_hotkey_key = 0;
        return false;
    end
    if (accessxi.chat_input_open) then
        accessxi.ashita_console_hotkey_key = 0;
        return false;
    end
    if (bit.band(kernel32.GetAsyncKeyState(VK_CONTROL), 0x8000) == 0
        or bit.band(kernel32.GetAsyncKeyState(accessxi.VK_SHIFT), 0x8000) == 0) then
        accessxi.ashita_console_hotkey_key = 0;
        return false;
    end

    local key = 0;
    if (bit.band(kernel32.GetAsyncKeyState(accessxi.VK_NUMPAD8), 0x8000) ~= 0) then
        key = accessxi.VK_NUMPAD8;
    elseif (bit.band(kernel32.GetAsyncKeyState(accessxi.VK_NUMPAD2), 0x8000) ~= 0) then
        key = accessxi.VK_NUMPAD2;
    elseif (bit.band(kernel32.GetAsyncKeyState(accessxi.VK_NUMPAD6), 0x8000) ~= 0) then
        key = accessxi.VK_NUMPAD6;
    elseif (bit.band(kernel32.GetAsyncKeyState(accessxi.VK_NUMPAD4), 0x8000) ~= 0) then
        key = accessxi.VK_NUMPAD4;
    elseif (bit.band(kernel32.GetAsyncKeyState(accessxi.VK_NUMPAD5), 0x8000) ~= 0) then
        key = accessxi.VK_NUMPAD5;
    elseif (bit.band(kernel32.GetAsyncKeyState(accessxi.VK_NUMPAD0), 0x8000) ~= 0) then
        key = accessxi.VK_NUMPAD0;
    end

    if (key == 0) then
        accessxi.ashita_console_hotkey_key = 0;
        return false;
    end

    local now = tick();
    local prior = tonumber(accessxi.ashita_console_hotkey_key) or 0;
    local repeat_delay = (key == accessxi.VK_NUMPAD8 or key == accessxi.VK_NUMPAD2) and 220 or 700;
    if (key == prior and ((now - (tonumber(accessxi.ashita_console_hotkey_tick) or 0)) < repeat_delay)) then
        return false;
    end

    accessxi.ashita_console_hotkey_key = key;
    accessxi.ashita_console_hotkey_tick = now;
    local handled = accessxi.ashita_console_handle_hotkey(key);
    if (handled) then
        log_line(('ashita console hotkey key="%s"'):fmt(accessxi.ashita_console_hotkey_key_name(key)));
    end
    return handled;
end

function accessxi.ashita_console_toggle_window()
    return pcall(function ()
        local chat = AshitaCore:GetChatManager();
        if (chat == nil) then
            error('chat manager unavailable');
        end
        chat:QueueCommand(1, '/ashita');
    end);
end

function accessxi.ashita_console_command(args)
    local subcommand = command_tail(args, 3):trim();
    local lower = subcommand:lower();
    local toggled = false;
    local text = '';
    if (subcommand == '' or lower:any('toggle')) then
        if (accessxi.ashita_console_open) then
            accessxi.ashita_console_close_menu();
        else
            accessxi.ashita_console_open_menu();
        end
        return;
    elseif (lower:any('open')) then
        if (accessxi.ashita_console_open) then
            accessxi.ashita_console_speak_current('open-already');
        else
            accessxi.ashita_console_open_menu();
        end
        return;
    elseif (lower:any('close', 'shut')) then
        accessxi.ashita_console_close_menu();
        return;
    elseif (lower:any('up', 'prev', 'previous')) then
        if (not accessxi.ashita_console_open) then
            accessxi.ashita_console_open_menu(false);
        end
        accessxi.ashita_console_move(-1);
        return;
    elseif (lower:any('down', 'next')) then
        if (not accessxi.ashita_console_open) then
            accessxi.ashita_console_open_menu(false);
        end
        accessxi.ashita_console_move(1);
        return;
    elseif (lower:any('select', 'activate', 'right', 'enter')) then
        if (not accessxi.ashita_console_open) then
            accessxi.ashita_console_open_menu(false);
        end
        accessxi.ashita_console_open_current();
        return;
    elseif (lower:any('back', 'left')) then
        if (accessxi.ashita_console_open) then
            accessxi.ashita_console_back();
        else
            speak('Ashita Settings is not open.');
        end
        return;
    elseif (lower:any('read', 'repeat', 'where')) then
        if (not accessxi.ashita_console_open) then
            accessxi.ashita_console_open_menu(false);
        else
            accessxi.ashita_console_speak_current('command-read');
        end
        return;
    elseif (lower:any('reload', 'reloadaccessxi')) then
        text = accessxi.ashita_console_reload_addon();
    elseif (lower:any('list', 'sections', 'menu', 'summary')) then
        text = accessxi.ashita_console_summary();
    else
        text = accessxi.ashita_console_read_section(subcommand);
    end

    speak(text);
    log_state(('state ashita-console command="%s" toggled=%s text="%s"'):fmt(
        accessxi.escape_probe_log_text(subcommand),
        toggled and 'true' or 'false',
        accessxi.escape_probe_log_text_wide(text)));
end

function accessxi.nav_mark_current_as(name, kind, default_prefix)
    local pos = nav_player_position();
    if (pos == nil) then
        return 'Position unavailable.';
    end

    name = nav_clean_field(name);
    if (name == '') then
        name = ('%s %d %.0f %.0f'):fmt(default_prefix or 'Point', pos.zone or 0, pos.x or 0, pos.z or 0);
    end

    local point = T{
        zone = pos.zone,
        name = name,
        x = pos.x,
        z = pos.z,
        y = pos.y,
        kind = kind or 'point',
        source = 'manual',
        confidence = 'observed',
        section = '',
    };
    if (not nav_save_point(point)) then
        return 'Could not save navigation point.';
    end
    return ('Marked %s. %s'):fmt(name, nav_position_speech(pos));
end

local function nav_mark_current(name)
    return accessxi.nav_mark_current_as(name, 'point', 'Point');
end

function accessxi.nav_mark_target_as(name, kind)
    local pos = nav_focus_target_position();
    if (pos == nil or pos.name == '') then
        return 'No focused target to mark.';
    end

    name = nav_clean_field(name);
    if (name == '') then
        name = pos.name;
    end

    local point = T{
        zone = pos.zone,
        name = name,
        x = pos.x,
        z = pos.z,
        y = pos.y,
        kind = kind or 'target',
        source = ('target:%d:%d'):fmt(pos.index or -1, pos.server_id or 0),
        confidence = 'observed',
        section = '',
    };
    if (not nav_save_point(point)) then
        return 'Could not save target point.';
    end
    return ('Marked target %s.'):fmt(name);
end

local function nav_mark_target(name)
    return accessxi.nav_mark_target_as(name, 'target');
end

local function nav_route_start(query)
    accessxi.nav_clear_zone_search();
    local point = nav_find_point(query);
    if (point == nil) then
        return 'No saved point matched in this zone.';
    end

    return accessxi.nav_start_route_to_point(point, 'command');
end

nav_route_stop = function ()
    accessxi.nav_clear_zone_search();
    accessxi.nav_clear_zoning_watch('route-stop');
    accessxi.nav_beacon_reset_direction_state();
    if (type(accessxi.nav_transport_clear) == 'function') then
        accessxi.nav_transport_clear('route-stop');
    end
    if (type(accessxi.nav_objective_transport_clear) == 'function') then
        accessxi.nav_objective_transport_clear('route-stop');
    else
        accessxi.nav_objective_transport_transition = nil;
    end
    accessxi.nav_objective_route_state = nil;
    if (type(accessxi.nav_dangruf_fount_drop_clear) == 'function') then
        accessxi.nav_dangruf_fount_drop_clear('route-stop');
    end
    accessxi.nav_active = false;
    accessxi.nav_destination = nil;
    accessxi.nav_last_key = '';
    accessxi.nav_last_direction_text = '';
    accessxi.nav_beacon_last_key = '';
    accessxi.nav_beacon_last_tick = 0;
    accessxi.nav_progress_x = nil;
    accessxi.nav_progress_z = nil;
    accessxi.nav_progress_distance = 0;
    accessxi.nav_progress_tick = 0;
    accessxi.nav_progress_last_block_tick = 0;
    accessxi.nav_progress_last_log_key = '';
    accessxi.nav_collision_x = nil;
    accessxi.nav_collision_z = nil;
    accessxi.nav_collision_destination_distance = 0;
    accessxi.nav_collision_route_distance = 0;
    accessxi.nav_collision_tick = 0;
    accessxi.nav_collision_last_sound_tick = 0;
    accessxi.nav_collision_last_key = '';
    accessxi.nav_door_wait_until = 0;
    accessxi.nav_door_pause_until = 0;
    accessxi.nav_door_x = nil;
    accessxi.nav_door_z = nil;
    accessxi.nav_door_route_unit_x = nil;
    accessxi.nav_door_route_unit_z = nil;
    accessxi.nav_door_wait_key = '';
    accessxi.nav_door_wait_name = '';
    accessxi.nav_obstacle_last_key = '';
    accessxi.nav_obstacle_last_tick = 0;
    accessxi.nav_wall_avoid_last_key = '';
    accessxi.nav_wall_avoid_last_tick = 0;
    accessxi.nav_route_points:clear();
    accessxi.nav_route_point_index = 1;
    return 'Route stopped.';
end

function accessxi.nav_is_mission_quest_point(point)
    local kind = nav_clean_field(type(point) == 'table' and (point.objective_kind or point.kind) or ''):lower();
    return kind == 'mission' or kind == 'quest';
end

function accessxi.nav_cancel_mission_quest_route(reason)
    local objective_owned = accessxi.nav_objective_route_state ~= nil
        or accessxi.nav_objective_transport_transition ~= nil;
    if (not objective_owned
        and not accessxi.nav_is_mission_quest_point(accessxi.nav_destination)
        and not accessxi.nav_is_mission_quest_point(accessxi.nav_zone_search_target)) then
        return false;
    end
    if (type(accessxi.nav_objective_transport_clear) == 'function') then
        accessxi.nav_objective_transport_clear(reason or 'objective-route-cancelled');
    else
        accessxi.nav_objective_transport_transition = nil;
    end
    nav_route_stop();
    accessxi.nav_objective_route_state = nil;
    log_line(('nav objective route cancelled reason="%s"'):fmt(nav_clean_field(reason or 'character-changed')));
    return true;
end

local function nav_route_mark_result(result, label)
    local destination = accessxi.nav_destination;
    if (destination == nil) then
        return 'No active route to mark.';
    end

    local player = nav_cached_player_position();
    local route_target = destination;
    if (accessxi.nav_route_points ~= nil and accessxi.nav_route_points:len() > 0) then
        local index = math.max(1, math.min(tonumber(accessxi.nav_route_point_index) or 1, accessxi.nav_route_points:len()));
        route_target = accessxi.nav_route_points[index] or destination;
    end

    nav_write_route_evidence(result, player, destination, route_target, T{ reason = 'manual mark' });
    local extra = '';
    if (result == 'proven' and player ~= nil) then
        local distance = nav_distance(player, destination);
        if (distance <= 30) then
            local point = T{
                zone = player.zone,
                name = destination.name or 'destination',
                x = player.x,
                z = player.z,
                y = player.y,
                kind = destination.kind or 'area',
                source = 'live-verified',
                confidence = 'proven',
                section = 'route-proof',
            };
            if (nav_save_point(point)) then
                accessxi.nav_points_loaded = false;
                extra = ' Updated destination position from where you are standing.';
            end
        end
    end
    return ('Marked route %s for %s.%s'):fmt(label or result or 'result', destination.name or 'destination', extra);
end

accessxi.nav_mark_destination_here = function (query)
    local player = nav_cached_player_position();
    if (player == nil) then
        return 'Position unavailable.';
    end

    local destination = nil;
    query = nav_clean_field(query);
    if (query ~= '') then
        destination = nav_find_point(query);
        if (destination == nil) then
            return 'No saved point matched in this zone.';
        end
    else
        destination = accessxi.nav_destination;
        if (destination == nil) then
            return 'No active route destination to update.';
        end
    end

    local point = T{
        zone = player.zone,
        name = destination.name or 'destination',
        x = player.x,
        z = player.z,
        y = player.y,
        kind = destination.kind or 'area',
        source = 'live-verified',
        confidence = 'proven',
        section = 'verified-here',
    };
    if (not nav_save_point(point)) then
        return 'Could not save verified destination.';
    end

    accessxi.nav_points_loaded = false;
    nav_write_route_evidence('verified-here', player, destination, point, T{ reason = 'manual current position verification' });
    if (accessxi.nav_destination == destination) then
        accessxi.nav_active = false;
        accessxi.nav_destination = nil;
        accessxi.nav_route_points:clear();
        accessxi.nav_route_point_index = 1;
        accessxi.nav_last_key = '';
        accessxi.nav_last_direction_text = '';
        accessxi.nav_beacon_last_key = '';
        accessxi.nav_beacon_last_tick = 0;
    end
    return ('Updated %s to your current position. %s'):fmt(destination.name or 'destination', nav_position_speech(player));
end

accessxi.nav_zone_checklist_speech = function ()
    nav_load_points();
    local zone = nav_zone_id();
    local zone_name = accessxi.nav_zone_resource_name(zone);
    local player = nav_cached_player_position();
    local mesh_name = nav_mesh_name_for_zone(zone);
    local mesh_text = 'mesh missing';
    if (mesh_name ~= nil and mesh_name ~= '') then
        local loaded = nav_try_load_mesh(zone);
        mesh_text = loaded and ('mesh ' .. mesh_name) or ('mesh listed but not loaded ' .. mesh_name);
    end

    local counts = { area = 0, npc = 0, object = 0, enemy = 0, nm = 0, player = 0 };
    local has_home = false;
    local has_guide = false;
    local has_zone_line = false;
    local has_mog = false;
    for _, point in ipairs(accessxi.nav_points) do
        if ((tonumber(point.zone) or 0) == zone) then
            local kind = accessxi.nav_point_effective_kind(point);
            if (counts[kind] ~= nil) then
                counts[kind] = counts[kind] + 1;
            end
            local name = tostring(point.name or ''):lower();
            has_home = has_home or name:contains('home point');
            has_guide = has_guide or name:contains('survival guide') or name:contains('guide stone');
            has_zone_line = has_zone_line or name:contains('zone line');
            has_mog = has_mog or name:contains('mog house');
        end
    end

    local missing = T{};
    if (not has_zone_line) then missing:append('zone lines'); end
    if (not has_home) then missing:append('home points'); end
    if (not has_guide) then missing:append('guide'); end
    local missing_text = missing:len() == 0 and 'Essentials present.' or ('Missing ' .. missing:concat(', ') .. '.');
    local position = player ~= nil and (' You are at X %.0f, Z %.0f, Y %.0f.'):fmt(player.x or 0, player.z or 0, player.y or 0) or '';
    local mog_text = has_mog and ' Mog house listed.' or '';
    return ('Mapping checklist. %s. Zone %d. %s. Areas %d. Objects %d. NPCs %d. NM spawns %d. %s%s%s'):fmt(
        zone_name ~= '' and zone_name or 'Current zone',
        zone,
        mesh_text,
        counts.area or 0,
        counts.object or 0,
        counts.npc or 0,
        counts.nm or 0,
        missing_text,
        mog_text,
        position);
end

accessxi.nav_route_audit_speech = function ()
    local f = io.open(accessxi.nav_route_evidence_path, 'r');
    if (f == nil) then
        return 'No route evidence file found.';
    end

    local zone = nav_zone_id();
    local counts = {};
    local issue_count = 0;
    local latest_issue = '';
    for line in f:lines() do
        if (line ~= nil and line ~= '' and not line:startswith('time\t')) then
            local parts = nav_split_tsv(line);
            local result = nav_clean_field(parts[2] or '');
            local line_zone = tonumber(parts[3]) or 0;
            if (line_zone == zone and result ~= '') then
                counts[result] = (counts[result] or 0) + 1;
                if (result == 'bad' or result == 'unreachable' or result == 'blocked') then
                    issue_count = issue_count + 1;
                    latest_issue = ('%s. %s. %s'):fmt(result, nav_clean_field(parts[4] or ''), nav_clean_field(parts[19] or ''));
                end
            end
        end
    end
    f:close();

    local proven = counts.proven or 0;
    local arrived = counts.arrived or 0;
    local zoned = counts.zoned or 0;
    local blocked = counts.blocked or 0;
    local bad = counts.bad or 0;
    local unreachable = counts.unreachable or 0;
    if ((proven + arrived + zoned + blocked + bad + unreachable) == 0) then
        return 'No route evidence for this zone yet.';
    end
    local tail = latest_issue ~= '' and (' Latest issue. ' .. latest_issue) or '';
    return ('Route audit. Proven %d. Arrived %d. Zoned %d. Blocked %d. Bad %d. Unreachable %d.%s'):fmt(
        proven,
        arrived,
        zoned,
        blocked,
        bad,
        unreachable,
        tail);
end

local function nav_points_speech()
    nav_load_points();
    local zone = nav_zone_id();
    local parts = T{};
    for _, point in ipairs(accessxi.nav_points) do
        if ((tonumber(point.zone) or 0) == zone) then
            parts:append(point.name or 'point');
            if (parts:len() >= 10) then
                break;
            end
        end
    end
    if (parts:len() == 0) then
        return 'No saved points in this zone.';
    end
    return ('Saved points. %s.'):fmt(parts:concat('. '));
end

local function get_character_count(account)
    local ok, count = pcall(account.get_character_count);
    count = tonumber(count);
    if (not ok or count == nil or count < 0 or count > 16) then
        return 0;
    end
    return count;
end

local function get_character_name(account, index)
    local ok, name = pcall(account.get_login_character_name, index);
    if (not ok) then
        return '';
    end
    return clean_login_text(name);
end

local function get_character_world(account, index)
    local ok, world = pcall(account.get_login_world_name, index);
    if (not ok) then
        return '';
    end
    return clean_login_text(world);
end

local function get_character_status(account, index)
    local ok, status = pcall(account.get_login_status, index);
    status = tonumber(status);
    if (not ok or status == nil) then
        return 0;
    end
    return status;
end

local function log_character_snapshot(account, count)
    local parts = T{};
    for i = 0, math.min(count - 1, 15) do
        local name = get_character_name(account, i);
        local world = get_character_world(account, i);
        local status = get_character_status(account, i);
        parts:append(('%d:%s/%s/status=%d'):fmt(i + 1, name ~= '' and name or '<blank>', world ~= '' and world or '<blank>', status));
    end

    local snapshot = ('characters count=%d %s'):fmt(count, parts:concat('|'));
    if (snapshot ~= accessxi.character_snapshot) then
        accessxi.character_snapshot = snapshot;
        log_line(snapshot);
    end
end

local function character_slot_speech(selected)
    local account = try_load_account_lib();
    if (account == nil) then
        return ('Character select. Slot %d.'):fmt(selected + 1);
    end

    local count = get_character_count(account);
    log_character_snapshot(account, count);

    if (selected >= count) then
        return ('Character select. Empty slot %d.'):fmt(selected + 1);
    end

    local name = get_character_name(account, selected);
    local world = get_character_world(account, selected);
    if (name ~= '') then
        if (world ~= '') then
            return ('Character select. %s. %s. Slot %d.'):fmt(name, world, selected + 1);
        end
        return ('Character select. %s. Slot %d.'):fmt(name, selected + 1);
    end

    return ('Character select. Empty slot %d.'):fmt(selected + 1);
end

