    return name ~= nil and name:eq('menu    inventor', true);
end

function accessxi.is_bazaar_item_list_menu_name(name, previous_menu_name)
    if (name == nil or not name:eq('menu    shop', true)) then
        return false;
    end

    previous_menu_name = tostring(previous_menu_name or '');
    if (previous_menu_name:eq('menu    bazaar', true)) then
        return true;
    end

    if (tostring(accessxi.inventory_context or '') == 'bazaar_item_list') then
        return true;
    end

    return tick() < (tonumber(accessxi.bazaar_item_list_context_until) or 0);
end

function accessxi.is_vendor_shop_item_list_menu_name(name, previous_menu_name)
    if (name == nil or not name:eq('menu    shop', true)) then
        return false;
    end

    previous_menu_name = tostring(previous_menu_name or '');
    if (previous_menu_name:eq('menu    shopmain', true)) then
        return true;
    end

    if (tostring(accessxi.inventory_context or '') == 'vendor_shop_item_list') then
        return true;
    end

    return tick() < (tonumber(accessxi.vendor_shop_item_list_context_until) or 0);
end

local function is_storage_bank_menu_name(name)
    return name ~= nil and name:eq('menu    bank', true);
end

function accessxi.is_trade_handover_menu_name(name)
    return name ~= nil and name:eq('menu    handover', true);
end

function accessxi.trade_handover_selected_entry()
    local obj = get_current_menu_object_ptr();
    if (obj == 0) then
        return 0, 0;
    end

    return obj, read_u32(obj + 0x08) or 0;
end

function accessxi.trade_handover_prepare_slot_map(obj)
    obj = tonumber(obj) or 0;
    if (obj == 0) then
        return false;
    end

    if (tonumber(accessxi.trade_handover_slot_obj) ~= obj) then
        accessxi.trade_handover_slot_obj = obj;
        accessxi.trade_handover_slot_by_entry = {};
        accessxi.trade_slots = {};
        accessxi.trade_handover_gil_amount = 0;
        accessxi.trade_handover_gil_amount_tick = 0;
    end
    accessxi.trade_handover_slot_by_entry = accessxi.trade_handover_slot_by_entry or {};
    return true;
end

function accessxi.trade_handover_bind_entry_slot(obj, entry, slot, source)
    obj = tonumber(obj) or 0;
    entry = tonumber(entry) or 0;
    slot = tonumber(slot) or 0;
    if (slot < 1 or slot > 8 or not accessxi.is_probe_pointer(entry)) then
        return;
    end
    if (not accessxi.trade_handover_prepare_slot_map(obj)) then
        return;
    end

    local key = ('%08X'):fmt(entry);
    if (tonumber(accessxi.trade_handover_slot_by_entry[key]) == slot) then
        return;
    end

    accessxi.trade_handover_slot_by_entry[key] = slot;
    log_state(('state trade slot-bind obj=0x%08X entry=0x%08X slot=%d source=%s'):fmt(
        obj,
        entry,
        slot,
        tostring(source or '')));
end

function accessxi.trade_handover_entry_desc(entry)
    entry = tonumber(entry) or 0;
    if (not accessxi.is_probe_pointer(entry)) then
        return 0;
    end
    return read_u32(entry + 0x0C) or 0;
end

function accessxi.trade_handover_slot_for_desc(entry)
    local desc = accessxi.trade_handover_entry_desc(entry);
    if (not accessxi.is_probe_pointer(desc)) then
        return 0;
    end

    local low = desc % 0x1000;
    for _, base in ipairs(T{ 0x1FC, 0x19C }) do
        local offset = low - base;
        if (offset >= 0 and offset <= (0x14 * 7) and (offset % 0x14) == 0) then
            return math.floor(offset / 0x14) + 1;
        end
    end
    return 0;
end

function accessxi.trade_handover_slot_for_geometry(entry)
    entry = tonumber(entry) or 0;
    if (not accessxi.is_probe_pointer(entry)) then
        return 0;
    end

    local row_shape = read_u32(entry + 0x2C) or 0;
    if (row_shape ~= 0x00200046 and row_shape ~= 0x00200068) then
        return 0;
    end

    local row_marker = math.floor((read_u32(entry + 0x38) or 0) / 0x10000);
    if (row_marker >= 1 and row_marker <= 8) then
        return row_marker;
    end

    local geom = accessxi.trade_handover_entry_geometry(entry);
    if (geom == nil) then
        return 0;
    end

    local y = tonumber(geom.y) or -1;
    local slot = 0;
    if (y >= 18 and y <= 28) then
        slot = 1;
    elseif (y >= 52 and y <= 62) then
        slot = 2;
    elseif (y >= 86 and y <= 96) then
        slot = 3;
    elseif (y >= 120 and y <= 130) then
        slot = 4;
    end
    if (slot == 0) then
        return 0;
    end
    if (row_shape == 0x00200068) then
        return slot + 4;
    end
    return slot;
end

function accessxi.trade_handover_control_geometry_label(entry)
    entry = tonumber(entry) or 0;
    if (not accessxi.is_probe_pointer(entry)) then
        return '';
    end

    local geom = accessxi.trade_handover_entry_geometry(entry);
    if (geom == nil) then
        return '';
    end

    local control_shape = read_u32(entry + 0x2C) or 0;
    local control_extent = read_u32(entry + 0x34) or 0;
    local y = tonumber(geom.y) or -1;
    if (y == 92 and control_shape == 0x00540037 and control_extent == 0x00A00007) then
        return 'GilAmount';
    end
    if (y ~= 159) then
        return '';
    end

    if (control_shape == 0x00220068 or control_extent == 0x00B10038) then
        return 'Cancel';
    elseif (control_shape == 0x00220046 or control_extent == 0x00B10016) then
        return 'Okay';
    end
    return '';
end

function accessxi.trade_handover_control_label_for_entry(entry)
    entry = tonumber(entry) or 0;
    if (not accessxi.is_probe_pointer(entry)) then
        return '';
    end

    local label_ptr = read_u32(entry + 0x44) or 0;
    local help_ptr = read_u32(entry + 0x40) or 0;
    local label = accessxi.plain_native_menu_label(read_probe_string(label_ptr));
    if (label ~= '') then
        return label;
    end

    label = accessxi.plain_native_menu_label(read_probe_string(help_ptr));
    if (label ~= '') then
        return label;
    end

    local desc = accessxi.trade_handover_entry_desc(entry);
    if (not accessxi.is_probe_pointer(desc)) then
        return '';
    end

    label = accessxi.plain_native_menu_label(read_probe_string(desc + 0x46));
    if (label ~= '') then
        return label;
    end

    label = accessxi.trade_handover_control_geometry_label(entry);
    if (label ~= '') then
        return label;
    end

    local desc_low = desc % 0x1000;
    if (desc_low == 0x23C or desc_low == 0x29C) then
        return 'Okay';
    elseif (desc_low == 0x250 or desc_low == 0x2B0) then
        return 'Cancel';
    elseif (desc_low == 0x264) then
        return 'Gil';
    elseif (desc_low == 0x2C4) then
        return 'GilAmount';
    end

    -- These are fixed native controls in "menu    handover". POL/FFXI does not
    -- expose their visible captions through the normal row label/help pointers.
    local geom = accessxi.trade_handover_entry_geometry(entry);
    if (geom ~= nil) then
        local x = tonumber(geom.x) or -1;
        local y = tonumber(geom.y) or -1;
        if (x == 57 and y == 92) then
            return 'Gil';
        end
        if (x == 97 and y == 92) then
            return 'GilAmount';
        end
        if (x == 89 and y == 159) then
            return 'Cancel';
        end
        if (x == 55 and y == 159) then
            return 'Cancel';
        end
        if (x == 32 and y == 159) then
            return 'Cancel';
        end
        if (x == 115 and y == 159) then
            return 'Okay';
        end
        if (x == 0 and y == 159) then
            return 'Okay';
        end
    end
    return '';
end

function accessxi.trade_handover_entry_ascii_digits(entry, offset, length)
    entry = tonumber(entry) or 0;
    offset = tonumber(offset) or 0;
    length = tonumber(length) or 0;
    if (not accessxi.is_probe_pointer(entry) or length <= 0) then
        return '';
    end

    local digits = T{};
    for i = 0, length - 1 do
        local byte = read_u8(entry + offset + i) or 0;
        if (byte >= 0x30 and byte <= 0x39) then
            digits:append(string.char(byte));
        elseif (#digits > 0) then
            break;
        end
    end

    return digits:concat('');
end

function accessxi.trade_handover_entry_gil_amount(entry)
    entry = tonumber(entry) or 0;
    local amount = tonumber(accessxi.trade_handover_gil_amount);
    if (amount == nil or amount < 0) then
        return 0;
    end
    return math.floor(amount);
end

function accessxi.log_trade_handover_control_text_probe(obj, entry)
    obj = tonumber(obj) or 0;
    entry = tonumber(entry) or 0;
    if (not accessxi.is_probe_pointer(entry)) then
        return;
    end

    local desc = accessxi.trade_handover_entry_desc(entry);
    local render = read_u32(entry + 0x04) or 0;
    local label_ptr = read_u32(entry + 0x44) or 0;
    local help_ptr = read_u32(entry + 0x40) or 0;
    local geom = accessxi.trade_handover_entry_geometry(entry);
    local geom_x = geom ~= nil and (tonumber(geom.x) or -1) or -1;
    local geom_y = geom ~= nil and (tonumber(geom.y) or -1) or -1;
    local key = ('%08X:%08X:%08X:%08X:%08X:%08X'):fmt(obj, entry, desc, render, label_ptr, help_ptr);
    if (key == tostring(accessxi.trade_handover_control_text_probe_key or '')) then
        return;
    end
    accessxi.trade_handover_control_text_probe_key = key;

    log_state(('state trade control-text-probe base obj=0x%08X entry=0x%08X desc=0x%08X render=0x%08X geom=(%d,%d) labelPtr=0x%08X label="%s" helpPtr=0x%08X help="%s" descName="%s" entryDwords=%s renderDwords=%s descDwords=%s'):fmt(
        obj,
        entry,
        desc,
        render,
        geom_x,
        geom_y,
        label_ptr,
        accessxi.escape_probe_log_text(read_probe_string(label_ptr)),
        help_ptr,
        accessxi.escape_probe_log_text(read_probe_string(help_ptr)),
        accessxi.escape_probe_log_text(read_probe_string(desc + 0x46)),
        accessxi.format_probe_dwords(entry, 0, 24),
        accessxi.format_probe_dwords(render, 0, 16),
        accessxi.format_probe_dwords(desc, 0, 16)));

    local function log_text_target(name, ptr, length)
        ptr = tonumber(ptr) or 0;
        if (not accessxi.is_probe_pointer(ptr)) then
            return;
        end
        length = tonumber(length) or 0x180;
        log_state(('state trade control-text-probe text target=%s ptr=0x%08X strings="%s" ascii="%s" utf16="%s" ffxi16="%s" ptrs="%s"'):fmt(
            tostring(name or ''),
            ptr,
            accessxi.escape_probe_log_text(accessxi.probe_strings_at(ptr)),
            accessxi.escape_probe_log_text(accessxi.probe_runs_to_text(accessxi.collect_probe_ascii_runs(ptr, length, 2, 12))),
            accessxi.escape_probe_log_text(accessxi.probe_runs_to_text(accessxi.collect_probe_utf16_runs(ptr, length, 2, 12))),
            accessxi.escape_probe_log_text(accessxi.probe_runs_to_text(accessxi.collect_probe_ffxi_utf16_runs(ptr, length, 2, 12))),
            accessxi.escape_probe_log_text(accessxi.status_menu_probe_pointer_fields(ptr))));
    end

    log_text_target('entry', entry, 0x180);
    log_text_target('render', render, 0x180);
    log_text_target('desc', desc, 0x180);
    log_text_target('obj', obj, 0x200);
end

function accessxi.log_trade_handover_graph_probe(obj)
    obj = tonumber(obj) or 0;
    if (not accessxi.is_probe_pointer(obj)) then
        return;
    end

    local key = ('%08X'):fmt(obj);
    if (key == tostring(accessxi.trade_handover_graph_probe_key or '')) then
        return;
    end
    accessxi.trade_handover_graph_probe_key = key;

    local function text_summary(ptr)
        ptr = tonumber(ptr) or 0;
        if (not accessxi.is_probe_pointer(ptr)) then
            return '';
        end
        local parts = T{};
        local strings = accessxi.probe_strings_at(ptr);
        local runs = accessxi.status_menu_probe_runs(ptr, 0x180);
        if (strings ~= '') then
            parts:append(('strings="%s"'):fmt(accessxi.escape_probe_log_text(strings)));
        end
        if (runs ~= '') then
            parts:append(('runs="%s"'):fmt(accessxi.escape_probe_log_text(runs)));
        end
        return parts:concat(' ');
    end

    local function ptr_summary(tag, owner, off, ptr)
        ptr = tonumber(ptr) or 0;
        if (not accessxi.is_probe_pointer(ptr)) then
            return;
        end
        local desc04 = read_u32(ptr + 0x04) or 0;
        local desc0c = read_u32(ptr + 0x0C) or 0;
        local geom = accessxi.trade_handover_entry_geometry(ptr);
        local geom_x = geom ~= nil and (tonumber(geom.x) or -1) or -1;
        local geom_y = geom ~= nil and (tonumber(geom.y) or -1) or -1;
        local label_ptr = read_u32(ptr + 0x44) or 0;
        local help_ptr = read_u32(ptr + 0x40) or 0;
        log_state(('state trade graph %s owner=0x%08X off=+%03X ptr=0x%08X desc04=0x%08X desc04Name="%s" desc0C=0x%08X desc0CName="%s" geom=(%d,%d) labelPtr=0x%08X label="%s" helpPtr=0x%08X help="%s" dwords=%s %s'):fmt(
            tostring(tag or ''),
            tonumber(owner) or 0,
            tonumber(off) or 0,
            ptr,
            desc04,
            accessxi.escape_probe_log_text(read_probe_string(desc04 + 0x46)),
            desc0c,
            accessxi.escape_probe_log_text(read_probe_string(desc0c + 0x46)),
            geom_x,
            geom_y,
            label_ptr,
            accessxi.escape_probe_log_text(read_probe_string(label_ptr)),
            help_ptr,
            accessxi.escape_probe_log_text(read_probe_string(help_ptr)),
            accessxi.format_probe_dwords(ptr, 0, 16),
            text_summary(ptr)));
    end

    log_state(('state trade graph begin obj=0x%08X dwords000=%s dwords080=%s dwords100=%s'):fmt(
        obj,
        accessxi.format_probe_dwords(obj, 0x00, 32),
        accessxi.format_probe_dwords(obj, 0x80, 32),
        accessxi.format_probe_dwords(obj, 0x100, 32)));

    local roots = T{};
    for off = 0, 0x1C0, 4 do
        local ptr = read_u32(obj + off) or 0;
        if (accessxi.is_probe_pointer(ptr)) then
            ptr_summary('objfield', obj, off, ptr);
            roots:append(T{ owner = obj, off = off, ptr = ptr });
        end
    end

    local logged = 0;
    for _, root in ipairs(roots) do
        if (logged >= 96) then
            break;
        end
        for off = 0, 0x140, 4 do
            if (logged >= 96) then
                break;
            end
            local ptr = read_u32(root.ptr + off) or 0;
            if (accessxi.is_probe_pointer(ptr) and ptr ~= obj and ptr ~= root.ptr) then
                logged = logged + 1;
                ptr_summary(('childfield+%03X'):fmt(root.off), root.ptr, off, ptr);
            end
        end
    end

    log_state(('state trade graph end obj=0x%08X childFields=%d'):fmt(obj, logged));
end

function accessxi.trade_handover_entry_occupied(entry)
    entry = tonumber(entry) or 0;
    if (not accessxi.is_probe_pointer(entry)) then
        return false;
    end

    local state_a = read_u32(entry + 0x10) or 0;
    local state_b = read_u32(entry + 0x14) or 0;
    return state_a == 1 and state_b == 1;
end

function accessxi.trade_handover_slot_for_entry(obj, entry)
    obj = tonumber(obj) or 0;
    entry = tonumber(entry) or 0;
    if (obj == 0 or not accessxi.is_probe_pointer(entry)) then
        return 0;
    end

    local native_slot = accessxi.trade_handover_slot_for_desc(entry);
    if (native_slot >= 1 and native_slot <= 8) then
        return native_slot;
    end

    local geom_slot = accessxi.trade_handover_slot_for_geometry(entry);
    if (geom_slot >= 1 and geom_slot <= 8) then
        accessxi.trade_handover_bind_entry_slot(obj, entry, geom_slot, 'geometry');
        return geom_slot;
    end

    if (not accessxi.trade_handover_prepare_slot_map(obj)) then
        return 0;
    end

    local key = ('%08X'):fmt(entry);
    local slot = tonumber(accessxi.trade_handover_slot_by_entry[key]) or 0;
    if (slot >= 1 and slot <= 8) then
        return slot;
    end
    return 0;
end

function accessxi.trade_handover_slot_for_cursor()
    local target = AshitaCore:GetMemoryManager():GetTarget();
    local ank_num = target ~= nil and (tonumber(safe_call(function () return target:GetWindowAnkNum(); end, -1)) or -1) or -1;
    return 0, ank_num;
end

function accessxi.log_trade_handover_probe(reason, obj, entry, slot, info)
    local target = AshitaCore:GetMemoryManager():GetTarget();
    local inv = AshitaCore:GetMemoryManager():GetInventory();
    local geom = accessxi.trade_handover_entry_geometry(entry);
    local geom_x = geom ~= nil and (tonumber(geom.x) or -1) or -1;
    local geom_y = geom ~= nil and (tonumber(geom.y) or -1) or -1;
    local desc = accessxi.trade_handover_entry_desc(entry);
    local occupied = accessxi.trade_handover_entry_occupied(entry);
    local ank_num = target ~= nil and (tonumber(safe_call(function () return target:GetWindowAnkNum(); end, -1)) or -1) or -1;
    local ank_x = target ~= nil and (tonumber(safe_call(function () return target:GetWindowAnkX(); end, -1)) or -1) or -1;
    local ank_y = target ~= nil and (tonumber(safe_call(function () return target:GetWindowAnkY(); end, -1)) or -1) or -1;
    local display_slot = inv ~= nil and (tonumber(safe_call(function () return inv:GetDisplayItemSlot(); end, -1)) or -1) or -1;
    local selected_id = inv ~= nil and (tonumber(safe_call(function () return inv:GetSelectedItemId(); end, 0)) or 0) or 0;
    local selected_index = inv ~= nil and (tonumber(safe_call(function () return inv:GetSelectedItemIndex(); end, -1)) or -1) or -1;
    local key_ank_num = 0;
    local key_ank_x = 0;
    local key_ank_y = 0;
    local key = ('%s:%08X:%08X:%d:%d:%d:%d:%d:%d'):fmt(
        tostring(reason or ''),
        tonumber(obj) or 0,
        tonumber(entry) or 0,
        tonumber(slot) or 0,
        key_ank_num,
        key_ank_x,
        key_ank_y,
        selected_id,
        selected_index);
    if (key == tostring(accessxi.trade_handover_probe_last_key or '')) then
        return;
    end
    accessxi.trade_handover_probe_last_key = key;
    log_state(('state trade handover-probe reason="%s" obj=0x%08X entry=0x%08X slot=%d desc=0x%08X occupied=%d geom=(%d,%d) ank=%d ank=(%d,%d) displaySlot=%d selectedId=%d selectedIndex=0x%04X infoName="%s" entryDwords=%s'):fmt(
        tostring(reason or ''),
        tonumber(obj) or 0,
        tonumber(entry) or 0,
        tonumber(slot) or 0,
        desc,
        occupied and 1 or 0,
        geom_x,
        geom_y,
        ank_num,
        ank_x,
        ank_y,
        display_slot,
        selected_id,
        math.max(selected_index, 0),
        accessxi.escape_probe_log_text(info ~= nil and (info.name or '') or ''),
        accessxi.format_probe_dwords(entry, 0, 24)));
end

function accessxi.trade_handover_target_name()
    local target = AshitaCore:GetMemoryManager():GetTarget();
    return accessxi.plain_native_menu_label(clean_login_text(target ~= nil and safe_call(function () return target:GetWindowName(); end, '') or ''));
end

function accessxi.trade_handover_entry_geometry(entry)
    entry = tonumber(entry) or 0;
    if (not accessxi.is_probe_pointer(entry)) then
        return nil;
    end

    local packed_x = read_u32(entry + 0x24) or 0;
    local packed_y = read_u32(entry + 0x28) or 0;
    local x = bit.band(bit.rshift(packed_x, 8), 0xFF);
    local y = bit.band(bit.rshift(packed_y, 16), 0xFF);
    if (x == 0 and y == 0) then
        return nil;
    end

    return T{ x = x, y = y };
end

function accessxi.trade_handover_maybe_dump_layout(menu_name, obj)
    if (accessxi.trade_handover_auto_dump_enabled ~= true) then
        return false;
    end

    obj = tonumber(obj) or 0;
    if (obj == 0) then
        return false;
    end

    local key = ('%s:%08X'):fmt(menu_name or '', obj);
    if (key == tostring(accessxi.trade_handover_layout_dump_key or '')) then
        return false;
    end
    accessxi.trade_handover_layout_dump_key = key;
    return true;
end

local function is_equipment_menu_name(name)
    return name ~= nil and name:eq('menu    equip', true);
end

local function is_equipment_storage_options_menu_name(name)
    return name ~= nil and (name:eq('menu    mnstorag', true) or name:eq('menu    mcrmogc', true));
end

local equipment_slot_names = {
    [0] = 'Main',
    [1] = 'Sub',
    [2] = 'Range',
    [3] = 'Ammo',
    [4] = 'Head',
    [5] = 'Body',
    [6] = 'Hands',
    [7] = 'Legs',
    [8] = 'Feet',
    [9] = 'Neck',
    [10] = 'Waist',
    [11] = 'Left ear',
    [12] = 'Right ear',
    [13] = 'Left ring',
    [14] = 'Right ring',
    [15] = 'Back',
};

local equipment_storage_option_labels = T{
    'Inventory',
    'Wardrobe',
    'Wardrobe 2',
    'Wardrobe 3',
    'Wardrobe 4',
    'Wardrobe 5',
    'Wardrobe 6',
    'Wardrobe 7',
    'Wardrobe 8',
};

local job_abbreviations = T{
    'WAR', 'MNK', 'WHM', 'BLM', 'RDM', 'THF', 'PLD', 'DRK',
    'BST', 'BRD', 'RNG', 'SAM', 'NIN', 'DRG', 'SMN', 'BLU',
    'COR', 'PUP', 'DNC', 'SCH', 'GEO', 'RUN',
};

local race_masks = T{
    T{ mask = 0x0002, label = 'Hume male' },
    T{ mask = 0x0004, label = 'Hume female' },
    T{ mask = 0x0008, label = 'Elvaan male' },
    T{ mask = 0x0010, label = 'Elvaan female' },
    T{ mask = 0x0020, label = 'Tarutaru male' },
    T{ mask = 0x0040, label = 'Tarutaru female' },
    T{ mask = 0x0080, label = 'Mithra' },
    T{ mask = 0x0100, label = 'Galka' },
};

local all_races_mask = 0x01FE;

local function format_seconds(total)
    total = math.max(0, tonumber(total) or 0);
    local hours = math.floor(total / 3600);
    local minutes = math.floor((total % 3600) / 60);
    local seconds = math.floor(total % 60);

    if (hours > 0) then
        if (minutes > 0) then
            return ('%d hours %d minutes'):fmt(hours, minutes);
        end
        return ('%d hours'):fmt(hours);
    end

    if (minutes > 0) then
        if (seconds > 0) then
            return ('%d minutes %d seconds'):fmt(minutes, seconds);
        end
        return ('%d minutes'):fmt(minutes);
    end

    return ('%d seconds'):fmt(seconds);
end

local function equipment_type_from_slots(slots)
    slots = tonumber(slots) or 0;
    if (slots == 0) then
        return '';
    end

    if (bit.band(slots, bit.lshift(1, 13)) ~= 0 or bit.band(slots, bit.lshift(1, 14)) ~= 0) then
        return 'Ring';
    end
    if (bit.band(slots, bit.lshift(1, 11)) ~= 0 or bit.band(slots, bit.lshift(1, 12)) ~= 0) then
        return 'Ear';
    end

    local parts = T{};
    for slot = 0, 15 do
        if (bit.band(slots, bit.lshift(1, slot)) ~= 0) then
            local label = equipment_slot_names[slot] or '';
            label = label:gsub('^Left ', ''):gsub('^Right ', '');
            if (label ~= '' and not parts:contains(label)) then
                parts:append(label);
            end
        end
    end

    return parts:concat(', ');
end

local function races_text(races)
    races = tonumber(races) or 0;
    if (races == 0) then
        return '';
    end

    if (bit.band(races, all_races_mask) == all_races_mask) then
        return 'All Races';
    end

    local parts = T{};
    for _, entry in ipairs(race_masks) do
        if (bit.band(races, entry.mask) ~= 0) then
            parts:append(entry.label);
        end
    end

    return parts:concat(', ');
end

local function jobs_text(jobs)
    jobs = tonumber(jobs) or 0;
    if (jobs == 0) then
        return '';
    end

    local all_jobs_mask = 0;
    for index = 1, #job_abbreviations do
        all_jobs_mask = bit.bor(all_jobs_mask, bit.lshift(1, index));
    end

    if (bit.band(jobs, all_jobs_mask) == all_jobs_mask) then
        return 'All Jobs';
    end

    local parts = T{};
    for index, label in ipairs(job_abbreviations) do
        if (bit.band(jobs, bit.lshift(1, index)) ~= 0) then
            parts:append(label);
        end
    end

    return parts:concat(', ');
end

-- Native FFXiMain.dll table at static VA 0x1036F7E8:
-- triplets 18 <grid-index> <equipment-slot> immediately before "menu    equip".
local equipment_grid_slot_order = {
    [0] = 0,   -- Main
    [1] = 1,   -- Sub
    [2] = 2,   -- Range
    [3] = 3,   -- Ammo
    [4] = 4,   -- Head
    [5] = 9,   -- Neck
    [6] = 11,  -- Left ear
    [7] = 12,  -- Right ear
    [8] = 5,   -- Body
    [9] = 6,   -- Hands
    [10] = 13, -- Left ring
    [11] = 14, -- Right ring
    [12] = 15, -- Back
    [13] = 10, -- Waist
    [14] = 7,  -- Legs
    [15] = 8,  -- Feet
};

local function equipment_grid_from_slot(slot)
    slot = tonumber(slot) or -1;
    for grid, mapped_slot in pairs(equipment_grid_slot_order) do
        if (mapped_slot == slot) then
            return grid;
        end
    end
    return -1;
end

local function equipment_grid_from_native_cursor(value)
    value = tonumber(value) or 0;
    if (value < 1 or value > 16) then
        return -1;
    end

    value = value - 1;
    return (bit.band(value, 0x03) * 4) + math.floor(value / 4);
end

local function is_valid_inventory_item_id(id)
    id = tonumber(id) or 0;
    return id > 0 and id < 65535;
end

local function clean_resource_text(text)
    if (text == nil) then
        return '';
    end

    text = tostring(text):gsub('%z.*$', ''):gsub('[\r\n\t]+', ' '):gsub('[%c]', ''):gsub('%s+', ' '):trim();
    return text;
end

local function normalize_item_level(value)
    value = tonumber(value) or 0;
    if (value > 255) then
        value = value - 256;
    end

    if (value < 0 or value > 119) then
        return 0;
    end

    return value;
end

local function empty_resource_item_info()
    return T{
        name = '',
        long_name = '',
        description = '',
        id = 0,
        flags = 0,
        type = 0,
        slots = 0,
        races = 0,
        jobs = 0,
        level = 0,
        superior_level = 0,
        item_level = 0,
        max_charges = 0,
        cast_time = 0,
        cast_delay = 0,
        recast_delay = 0,
    };
end

function accessxi.load_windower_items_resource()
    if (accessxi.windower_items_resource ~= nil) then
        return accessxi.windower_items_resource;
    end
    if (accessxi.windower_items_resource_load_tried == true) then
        return nil;
    end
    accessxi.windower_items_resource_load_tried = true;

    local paths = T{
        accessxi.resource_path('windower', 'items.lua'),
    };
    for _, path in ipairs(paths) do
        local f = io.open(path, 'rb');
        if (f ~= nil) then
            f:close();
            local ok, data = pcall(function ()
                return loadfile(path)();
            end);
            if (ok and type(data) == 'table') then
                accessxi.windower_items_resource = data;
                accessxi.windower_items_resource_path = path;
                log_line(('loaded Windower items resource path="%s"'):fmt(path));
                return accessxi.windower_items_resource;
            end
            log_line(('Windower items resource load failed path="%s" err="%s"'):fmt(path, tostring(data)));
        end
    end

    log_line('Windower items resource unavailable');
    return nil;
end

function accessxi.windower_item_resource_record(id)
    id = tonumber(id) or 0;
    if (not is_valid_inventory_item_id(id)) then
        return nil;
    end

    local resource = accessxi.load_windower_items_resource();
    if (type(resource) ~= 'table') then
        return nil;
    end

    local record = resource[id];
    if (type(record) ~= 'table') then
        return nil;
    end
    return record;
end

local function resource_item_info(id)
    if (not is_valid_inventory_item_id(id)) then
        return empty_resource_item_info();
    end

    local resources = AshitaCore:GetResourceManager();
    if (resources == nil) then
        return empty_resource_item_info();
    end

    local res = safe_call(function () return resources:GetItemById(id); end, nil);
    if (res == nil) then
        return empty_resource_item_info();
    end

    local name = res.Name ~= nil and clean_resource_text(res.Name[1]) or '';
    local long_name = '';
    local windower_item = accessxi.windower_item_resource_record(id);
    if (windower_item == nil) then
        windower_item = {};
    end
    if (next(windower_item) ~= nil) then
        if (name == '') then
            name = clean_resource_text(windower_item.en or windower_item.name or '');
        end
        long_name = clean_resource_text(windower_item.enl or windower_item.long_name or '');
    end
    local description = res.Description ~= nil and clean_resource_text(res.Description[1]) or '';
    local category = clean_resource_text(windower_item.category or '');
    if (res.Category ~= nil) then
        local live_category = clean_resource_text(res.Category);
        if (live_category ~= '') then
            category = live_category;
        end
    end
    return T{
        name = name,
        long_name = long_name,
        description = description,
        id = tonumber(res.Id) or id,
        flags = tonumber(res.Flags) or 0,
        type = tonumber(res.Type) or tonumber(windower_item.type) or 0,
        category = category,
        skill = tonumber(res.Skill) or tonumber(windower_item.skill) or 0,
        slots = tonumber(res.Slots) or tonumber(windower_item.slots) or 0,
        races = tonumber(res.Races) or 0,
        jobs = tonumber(res.Jobs) or 0,
        level = tonumber(res.Level) or 0,
        superior_level = tonumber(res.SuperiorLevel) or 0,
        item_level = normalize_item_level(res.ItemLevel),
        stack = tonumber(res.Stack) or tonumber(res.StackSize) or tonumber(windower_item.stack) or 0,
        max_charges = tonumber(res.MaxCharges) or 0,
        cast_time = tonumber(res.CastTime) or 0,
        cast_delay = tonumber(res.CastDelay) or 0,
        recast_delay = tonumber(res.RecastDelay) or 0,
    };
end

accessxi.resource_item_info = resource_item_info;

function accessxi.normalized_resource_name(value)
    return clean_resource_text(value):lower():gsub('[%s_%-]+', '');
end

function accessxi.resource_item_info_name_matches(resource_info, name)
    name = tostring(name or ''):trim();
    if (resource_info == nil or name == '') then
        return false;
    end

    local normalized_name = accessxi.normalized_resource_name(name);
    return accessxi.normalized_resource_name(resource_info.name) == normalized_name
        or accessxi.normalized_resource_name(resource_info.long_name) == normalized_name;
end

function accessxi.resource_item_speech_name(resource_info, fallback_name)
    local fallback = clean_resource_text(fallback_name or '');
    if (resource_info ~= nil) then
        local long_name = clean_resource_text(resource_info.long_name or '');
        if (long_name ~= '') then
            return long_name, 'resource-long-name';
        end

        local short_name = clean_resource_text(resource_info.name or '');
        if (short_name ~= '') then
            return short_name, 'resource-short-name';
        end
    end

    if (fallback ~= '') then
        return fallback, 'native-name';
    end
    return '', 'none';
end

function accessxi.resource_item_info_by_name(name)
    name = tostring(name or ''):trim();
    if (name == '') then
        return nil;
    end

    local resources = AshitaCore:GetResourceManager();
    if (resources == nil) then
        return nil;
    end

    for _, lang in ipairs(T{ 0, 1, 2 }) do
        local res = safe_call(function () return resources:GetItemByName(name, lang); end, nil);
        if (res ~= nil) then
            local id = tonumber(res.Id) or 0;
            local info = resource_item_info(id);
            if (accessxi.resource_item_info_name_matches(info, name)) then
                return info;
            end
        end
    end

    local normalized_name = accessxi.normalized_resource_name(name);
    local windower_items = accessxi.load_windower_items_resource();
    if (type(windower_items) == 'table') then
        for id, record in pairs(windower_items) do
            if (type(record) == 'table'
                and (accessxi.normalized_resource_name(record.en) == normalized_name
                    or accessxi.normalized_resource_name(record.enl) == normalized_name)) then
                local info = resource_item_info(id);
                if (accessxi.resource_item_info_name_matches(info, name)) then
                    return info;
                end
            end
        end
    end

    return nil;
end

function accessxi.capture_vendor_shop_list_packet(e)
    if (e == nil or e.id ~= 0x03C) then
        return;
    end

    local data = accessxi.packet_event_string(e, 'data_modified', 'size');
    if (data == '') then
        data = accessxi.packet_event_string(e, 'data', 'size');
    end
    if (#data < 0x08) then
        return;
    end

    local offset = accessxi.packet_u16(data, 0x04 + 1);
    local flags = accessxi.packet_byte(data, 0x06 + 1);
    local rows = accessxi.vendor_shop_packet_rows or {};
    if (offset == 0 or rows.by_item_id == nil) then
        rows = {
            by_item_id = {},
            by_name = {},
            by_shop_index = {},
            ordered = {},
        };
    end

    local row_count = math.floor((#data - 0x08) / 12);
    local preview = T{};
    for i = 0, math.min(row_count, 19) - 1 do
        local base = 0x08 + (i * 12);
        local price = accessxi.packet_u32(data, base + 0x00 + 1); -- GP_SHOP.ItemPrice
        local item_id = accessxi.packet_u16(data, base + 0x04 + 1);
        local shop_index = accessxi.packet_byte(data, base + 0x06 + 1);
        local skill = accessxi.packet_u16(data, base + 0x08 + 1);
        local guild_info = accessxi.packet_u16(data, base + 0x0A + 1);

        if (is_valid_inventory_item_id(item_id) and price > 0) then
            local item_info = resource_item_info(item_id);
            local item_name = item_info ~= nil and tostring(item_info.name or '') or '';
            local row = {
                item_id = item_id,
                price = price,
                shop_index = shop_index,
                offset = offset,
                ordinal = offset + i,
                name = item_name,
                skill = skill,
                guild_info = guild_info,
                tick = tick(),
                source = 'packet_in_03c',
            };
            rows.by_item_id[item_id] = row;
            rows.by_shop_index[shop_index] = row;
            rows.ordered[offset + i] = row;
            if (item_name ~= '') then
                rows.by_name[accessxi.normalized_resource_name(item_name)] = row;
            end
            preview:append(('%d:%s:%dG'):fmt(shop_index, item_name ~= '' and item_name or tostring(item_id), price));
        end
    end

    accessxi.vendor_shop_packet_rows = rows;
    accessxi.vendor_shop_packet_tick = tick();
    local key = ('%d:%d:%s'):fmt(offset, flags, preview:concat('|'));
    if (key ~= tostring(accessxi.vendor_shop_packet_key or '')) then
        accessxi.vendor_shop_packet_key = key;
        log_state(('state vendor-shop packet ItemPrice id=0x03C offset=%d flags=0x%02X rows=%d items="%s"'):fmt(
            offset,
            flags,
            row_count,
            accessxi.escape_probe_log_text(preview:concat('|'))));
    end
end

function accessxi.vendor_shop_price_for_item(item_id, name)
    item_id = tonumber(item_id) or 0;
    local rows = accessxi.vendor_shop_packet_rows or {};
    local age = tick() - (tonumber(accessxi.vendor_shop_packet_tick) or 0);
    if (age > 300000) then
        return nil;
    end

    local row = nil;
    if (is_valid_inventory_item_id(item_id) and rows.by_item_id ~= nil) then
        row = rows.by_item_id[item_id];
    end
    if (row == nil and name ~= nil and tostring(name or '') ~= '' and rows.by_name ~= nil) then
        row = rows.by_name[accessxi.normalized_resource_name(name)];
    end
    if (row == nil) then
        return nil;
    end

    local price = tonumber(row.price) or 0;
    if (price <= 0) then
        return nil;
    end
    return price, tostring(row.source or 'packet_in_03c'), math.floor(age);
end

local function item_static_detail_parts(resource_info)
    local parts = T{};
    if (resource_info == nil) then
        return parts;
    end

    local flags = tonumber(resource_info.flags) or 0;
    if (bit.band(flags, 0x8000) ~= 0) then
        parts:append('Rare');
    end
    if (bit.band(flags, 0x4000) ~= 0) then
        parts:append('Ex');
    end

    local item_type = equipment_type_from_slots(resource_info.slots);
    if (item_type ~= '') then
        parts:append(item_type);
    end

    local race_text = races_text(resource_info.races);
    if (race_text ~= '') then
        parts:append(race_text);
    end

    local level = tonumber(resource_info.level) or 0;
    if (level > 0) then
        parts:append(('Level %d'):fmt(level));
    end

    local job_text = jobs_text(resource_info.jobs);
    if (job_text ~= '') then
        parts:append(job_text);
    end

    local superior_level = tonumber(resource_info.superior_level) or 0;
    if (superior_level > 0) then
        parts:append(('Superior %d'):fmt(superior_level));
    end

    local item_level = tonumber(resource_info.item_level) or 0;
    if (item_level > 0) then
        parts:append(('Item level %d'):fmt(item_level));
    end

    return parts;
end

local function item_fallback_charge_parts(resource_info)
    local parts = T{};
    if (resource_info == nil) then
        return parts;
    end

    local max_charges = tonumber(resource_info.max_charges) or 0;
    if (max_charges == 255) then
        parts:append('Unlimited charges');
    elseif (max_charges > 0) then
        parts:append(('Charges %d max'):fmt(max_charges));
    end

    local recast_delay = tonumber(resource_info.recast_delay) or 0;
    if (recast_delay > 0) then
        parts:append(('Recast %s'):fmt(format_seconds(recast_delay)));
    end

    return parts;
end

local function has_charge_detail(parts)
    if (parts == nil) then
        return false;
    end

    for _, part in ipairs(parts) do
        local text = tostring(part or ''):lower();
        if (text:contains('charge') or text:contains('usable')) then
            return true;
        end
    end

    return false;
end

local function try_load_itemdata_lib()
    if (accessxi.itemdata ~= nil) then
        return accessxi.itemdata;
    end

    local now = tick();
    if (accessxi.itemdata_load_tried and (now - accessxi.itemdata_last_try) < 5000) then
        return nil;
    end

    accessxi.itemdata_load_tried = true;
    accessxi.itemdata_last_try = now;
    local ok, itemdata = pcall(require, 'ffxi.itemdata');
    if (ok and itemdata ~= nil) then
        accessxi.itemdata = itemdata;
        log_line('loaded ffxi.itemdata parser');
        return accessxi.itemdata;
    end

    log_line('ffxi.itemdata unavailable: ' .. tostring(itemdata));
    return nil;
end

local function item_dynamic_detail_parts(item, is_equipped)
    local parts = T{};
    if (item == nil) then
        return parts;
    end

    local itemdata = try_load_itemdata_lib();
    if (itemdata == nil or itemdata.parse == nil) then
        return parts;
    end

    local parsed = safe_call(function () return itemdata.parse(item, is_equipped); end, nil);
    if (parsed == nil) then
        return parts;
    end

    if (parsed.augments ~= nil) then
        local resources = AshitaCore:GetResourceManager();
        for _, augment in ipairs(parsed.augments) do
            local augment_index = tonumber(augment.index) or 0;
            local augment_value = tonumber(augment.value) or 0;
            if (augment_index > 0 and resources ~= nil) then
                local text = clean_resource_text(safe_call(function () return resources:GetString('augments', augment_index); end, '') or '');
                if (text ~= '') then
                    if (text:find('%', 1, true) ~= nil) then
                        local ok_fmt, formatted = pcall(function () return string.format(text, augment_value); end);
                        if (ok_fmt and formatted ~= nil and formatted ~= '') then
                            text = formatted;
                        end
                    end
                    parts:append(text);
                else
                    log_state(('state item augment missing-string id=%d augment=%d value=%d'):fmt(
                        tonumber(item.Id) or 0,
                        augment_index,
                        augment_value));
                end
            end
        end
    end

    local remaining_charges = tonumber(parsed.remaining_charges) or 0;
    local max_charges = tonumber(parsed.max_charges) or 0;
    if (max_charges == 255) then
        parts:append('Unlimited charges');
    elseif (max_charges > 0) then
        parts:append(('Charges %d of %d'):fmt(remaining_charges, max_charges));
    end

    local use_delay = tonumber(parsed.use_delay);
    if (use_delay ~= nil) then
        if (use_delay > 0) then
            parts:append(('Usable in %s'):fmt(format_seconds(use_delay)));
        elseif (max_charges > 0 and max_charges < 255) then
            parts:append('Usable now');
        end
    end

    return parts;
end

local function item_fits_equipment_slot(resource_info, slot)
    slot = tonumber(slot) or -1;
    if (resource_info == nil or slot < 0 or slot > 15) then
        return false;
    end

    local slots = tonumber(resource_info.slots) or 0;
    return bit.band(slots, bit.lshift(1, slot)) ~= 0;
end

local function inventory_item_count(item)
    if (item == nil) then
        return 0;
    end

    local count = tonumber(item.Count) or 0;
    if (count < 0 or count > 99999999) then
        return 0;
    end
    return count;
end

local function raw_table_value(t, key, default)
    if (type(t) ~= 'table') then
        return default;
    end

    local value = rawget(t, key);
    if (value == nil) then
        return default;
    end

    return value;
end

local function join_speech_parts(parts)
    local cleaned = T{};
    for _, part in ipairs(parts) do
        part = clean_resource_text(part);
        if (part ~= '') then
            cleaned:append(part:gsub('[%.%!%?]+$', ''));
        end
    end

    if (#cleaned == 0) then
        return nil;
    end

    return cleaned:concat('. ') .. '.';
end

function accessxi.capture_current_gear_detail(menu_name, info, options)
    local module = accessxi.gear_detail_hotkeys;
    local state = accessxi.gear_detail_hotkey_state;
    if (type(module) ~= 'table'
        or type(module.set_detail) ~= 'function'
        or type(state) ~= 'table'
        or type(info) ~= 'table'
        or info.command == true
        or info.empty == true) then
        return false;
    end

    menu_name = tostring(menu_name or '');
    local context_key = tostring(accessxi.current_speech_key or '');
    local item_id = tonumber(raw_table_value(info, 'id', 0)) or 0;
    local name = tostring(raw_table_value(info, 'name', '') or '');
    if (menu_name == '' or context_key == '' or item_id <= 0 or name == '') then
        return false;
    end

    local resource_info = resource_item_info(item_id);
    if (resource_info == nil or (tonumber(resource_info.slots) or 0) <= 0) then
        return false;
    end

    options = type(options) == 'table' and options or T{};
    local count = raw_table_value(options, 'count', nil);
    if (count == nil) then
        count = raw_table_value(info, 'count', 0);
    end
    local item_index = raw_table_value(options, 'index', nil);
    if (item_index == nil) then
        item_index = raw_table_value(info, 'index', raw_table_value(info, 'slot', -1));
    end
    local detail_parts = raw_table_value(info, 'detail_parts', nil);
    if (type(detail_parts) ~= 'table') then
        detail_parts = item_static_detail_parts(resource_info);
    end
    local captured_detail_parts = T{};
    local price = tonumber(raw_table_value(info, 'price', 0)) or 0;
    if (price > 0) then
        captured_detail_parts:append(('Price %s gil'):fmt(accessxi.format_currency_number(price)));
    end
    for _, part in ipairs(detail_parts) do
        captured_detail_parts:append(part);
    end

    local previous_identity = tostring(state.identity or '');
    local captured = module.set_detail(state, {
        is_gear = true,
        menu = menu_name,
        context_key = context_key,
        id = item_id,
        index = tonumber(item_index) or -1,
        name = name,
        slot_name = tostring(raw_table_value(options, 'slot_name', raw_table_value(info, 'slot_name', '')) or ''),
        count = tonumber(count) or 0,
        detail_parts = captured_detail_parts,
        description = tostring(raw_table_value(info, 'description', '') or ''),
        source = tostring(raw_table_value(options, 'source', '') or ''),
        updated_tick = tick(),
    });
    if (captured and previous_identity ~= tostring(state.identity or '')) then
        log_state(('state gear-detail captured menu="%s" id=%d index=%d name="%s" source="%s" lines=%d contextKey="%s"'):fmt(
            accessxi.escape_probe_log_text(menu_name),
            item_id,
            tonumber(item_index) or -1,
            accessxi.escape_probe_log_text(name),
            accessxi.escape_probe_log_text(tostring(raw_table_value(options, 'source', '') or '')),
            type(state.lines) == 'table' and #state.lines or 0,
            accessxi.escape_probe_log_text(context_key)));
    end
    return captured == true;
end

function accessxi.inspect_check_item_detail_speech(slot_name, item_id, check_item)
    item_id = tonumber(item_id) or 0;
    if (item_id <= 0 or item_id >= 65535) then
        return nil;
    end

    local resource_info = resource_item_info(item_id);
    local label = accessxi.plain_native_menu_label(tostring(resource_info.name or ''));
    if (label == '') then
        label = accessxi.inspect_check_item_label(item_id);
    end
    if (label == '') then
        return nil;
    end

    local detail_parts = item_static_detail_parts(resource_info);
    local item = T{
        Id = item_id,
        Extra = check_item ~= nil and check_item.Extra or nil,
        Count = 1,
    };
    for _, part in ipairs(item_dynamic_detail_parts(item, true)) do
        detail_parts:append(part);
    end
    if (not has_charge_detail(detail_parts)) then
        for _, part in ipairs(item_fallback_charge_parts(resource_info)) do
            detail_parts:append(part);
        end
    end

    local parts = T{ tostring(slot_name or ''), label };
    for _, part in ipairs(detail_parts) do
        if (part ~= nil and part ~= '') then
            parts:append(part);
        end
    end
    if (resource_info.description ~= nil and resource_info.description ~= '') then
        parts:append(resource_info.description);
    end
    return join_speech_parts(parts), T{
        id = item_id,
        index = tonumber(slot_name) or -1,
        name = label,
        slot_name = tostring(slot_name or ''),
        count = 1,
        detail_parts = detail_parts,
        description = tostring(resource_info.description or ''),
        empty = false,
    };
end

local function read_target_ank_num()
    local target = AshitaCore:GetMemoryManager():GetTarget();
    if (target == nil) then
        return -1;
    end

    return tonumber(safe_call(function () return target:GetWindowAnkNum(); end, -1)) or -1;
end

local function valid_equipment_grid_index(index)
    index = tonumber(index) or -1;
    if (index < 0 or index > 15) then
        return -1;
    end
    return index;
end

local function valid_equipment_slot_index(index)
    index = tonumber(index) or -1;
    if (index < 0 or index > 15) then
        return -1;
    end
    return index;
end

local function append_limited(parts, value, limit)
    if (#parts >= limit) then
        return;
    end
    parts:append(value);
end

local function format_runtime_dwords(base, offset, count)
    if (base == 0) then
        return '';
    end

    local parts = T{};
    for i = 0, count - 1 do
        local value = read_u32(base + offset + (i * 4));
        if (value ~= nil) then
            parts:append(('%08X'):fmt(value));
        end
    end
    return parts:concat(',');
end

local function log_menu_dump_dwords(seq, obj, start_offset, end_offset)
    if (obj == 0) then
        return;
    end

    for line_start = start_offset, end_offset, 0x40 do
        local parts = T{};
        for off = line_start, math.min(line_start + 0x3C, end_offset), 4 do
            local value = read_u32(obj + off);
            parts:append(value ~= nil and hex32(value) or '????????');
        end
        log_line(('menudump seq=%d obj+%03X dwords=%s'):fmt(seq, line_start, parts:concat(',')));
    end
end

local function log_menu_dump_candidates(seq, obj, start_offset, end_offset)
    if (obj == 0) then
        return;
    end

    local small32 = T{};
    local bytes = T{};
    local ptrs = T{};

    for off = start_offset, end_offset, 4 do
        local svalue = read_i32(obj + off);
        if (svalue ~= nil and svalue >= -1 and svalue <= 512) then
            append_limited(small32, ('+%03X=%d'):fmt(off, svalue), 96);
        end

        local uvalue = read_u32(obj + off);
        if (uvalue ~= nil) then
            for byte_index = 0, 3 do
                local byte_value = bit.band(bit.rshift(uvalue, byte_index * 8), 0xFF);
                if (byte_value <= 64) then
                    append_limited(bytes, ('+%03X.%d=%d'):fmt(off, byte_index, byte_value), 128);
                end
            end

            if (accessxi.is_probe_pointer(uvalue)) then
                local strings = accessxi.probe_strings_at(uvalue);
                if (strings ~= '') then
                    append_limited(ptrs, ('+%03X->0x%08X strings=%s'):fmt(off, uvalue, strings), 48);
                else
                    append_limited(ptrs, ('+%03X->0x%08X'):fmt(off, uvalue), 48);
                end
            end
        end
    end

    log_line(('menudump seq=%d small32=%s'):fmt(seq, small32:concat(' ')));
    log_line(('menudump seq=%d bytes=%s'):fmt(seq, bytes:concat(' ')));
    log_line(('menudump seq=%d ptrs=%s'):fmt(seq, ptrs:concat(' | ')));
end

local function log_menu_dump_pointer_targets(seq, obj, start_offset, end_offset)
    if (obj == 0) then
        return;
    end

    local seen = {};
    local nested_seen = {};
    local logged = 0;
    local nested_logged = 0;
    for off = start_offset, end_offset, 4 do
        if (logged >= 24) then
            break;
        end

        local ptr = read_u32(obj + off);
        if (ptr ~= nil and accessxi.is_probe_pointer(ptr) and not seen[ptr]) then
            seen[ptr] = true;
            logged = logged + 1;

            local parts = T{};
            for target_off = 0, 0x7C, 4 do
                local value = read_u32(ptr + target_off);
                parts:append(value ~= nil and hex32(value) or '????????');
            end

            local desc = read_u32(ptr + 0x04) or 0;
            log_line(('menudump seq=%d ptrtarget src=+%03X ptr=0x%08X desc=0x%08X strings=%s descStrings=%s dwords=%s'):fmt(
                seq,
                off,
                ptr,
                desc,
                accessxi.probe_strings_at(ptr),
                accessxi.probe_strings_at(desc),
                parts:concat(',')));

            for target_off = 0, 0xFC, 4 do
                if (nested_logged >= 48) then
                    break;
                end

                local nested = read_u32(ptr + target_off);
                if (nested ~= nil and accessxi.is_probe_pointer(nested) and not seen[nested] and not nested_seen[nested]) then
                    local nested_strings = accessxi.probe_strings_at(nested);
                    if (nested_strings ~= '') then
                        nested_seen[nested] = true;
                        nested_logged = nested_logged + 1;
                        log_line(('menudump seq=%d ptrnested src=+%03X ptr=0x%08X +%03X->0x%08X strings=%s'):fmt(
                            seq,
                            off,
                            ptr,
                            target_off,
                            nested,
                            nested_strings));
                    end
                end
            end
        end
    end
end

local function log_menu_dump_shapes(seq)
    local target = AshitaCore:GetMemoryManager():GetTarget();
    if (target == nil) then
        return;
    end

    local shapes = T{};
    for i = 0, 31 do
        local shape = safe_call(function () return target:GetWindowAnkShape(i); end, nil);
        if (shape ~= nil) then
            local numeric_shape = tonumber(shape) or 0;
            append_limited(shapes, ('%d=0x%08X'):fmt(i, numeric_shape), 40);
            if (accessxi.is_probe_pointer(numeric_shape)) then
                log_line(('menudump seq=%d shape index=%d ptr=0x%08X dwords=%s strings=%s'):fmt(
                    seq,
                    i,
                    numeric_shape,
                    accessxi.format_probe_dwords(numeric_shape, 0, 24),
                    accessxi.escape_probe_log_text(accessxi.party_label_probe_text_summary(numeric_shape, 0x180))));
                accessxi.log_probe_ffxi_menu_text(seq, ('shape%d'):fmt(i), numeric_shape, 0x180, 2, 8);
            end
        end
    end

    log_line(('menudump seq=%d shapes=%s'):fmt(seq, shapes:concat(' ')));
end

