function accessxi.chat_log_probe_ptr_summary(obj)
    obj = tonumber(obj) or 0;
    if (not accessxi.is_probe_pointer(obj)) then
        return '';
    end

    local parts = T{};
    for _, off in ipairs(T{ 0x04, 0x08, 0x0C, 0x14, 0x18, 0x58, 0x84, 0x88, 0x8C, 0x90, 0x98, 0x9C, 0xA0, 0xC8, 0xEC, 0xF0, 0x1B0 }) do
        local ptr = read_u32(obj + off) or 0;
        if (ptr ~= 0) then
            local desc = accessxi.is_probe_pointer(ptr) and (read_u32(ptr + 0x04) or 0) or 0;
            local desc_name = accessxi.is_probe_pointer(desc) and read_probe_string(desc + 0x46) or '';
            local text = '';
            if (accessxi.is_probe_pointer(ptr)) then
                text = accessxi.probe_runs_to_text(accessxi.collect_probe_ascii_runs(ptr, 0x180, 3, 4));
                if (text == '') then
                    text = accessxi.probe_runs_to_text(accessxi.collect_probe_utf16_runs(ptr, 0x180, 3, 4));
                end
            end
            parts:append(('+%03X=0x%08X desc=0x%08X name="%s" text="%s"'):fmt(
                off,
                ptr,
                desc,
                accessxi.escape_probe_log_text(desc_name),
                accessxi.escape_probe_log_text(text)));
        end
    end
    return parts:concat(' | ');
end

function accessxi.chat_log_probe_node_summary(ptr)
    ptr = tonumber(ptr) or 0;
    if (not accessxi.is_probe_pointer(ptr)) then
        return '';
    end

    local desc = read_u32(ptr + 0x04) or 0;
    local desc_name = accessxi.is_probe_pointer(desc) and read_probe_string(desc + 0x46) or '';
    local small = T{};
    for off = 0, 0x160, 4 do
        local value = read_i32(ptr + off);
        if (value ~= nil and value >= -4096 and value <= 4096) then
            small:append(('+%03X=%d'):fmt(off, value));
            if (#small >= 18) then
                break;
            end
        end
    end

    local ascii = accessxi.probe_runs_to_text(accessxi.collect_probe_ascii_runs(ptr, 0x240, 3, 5));
    local utf16 = accessxi.probe_runs_to_text(accessxi.collect_probe_utf16_runs(ptr, 0x240, 3, 5));
    local ffxi_utf16 = '';
    if (accessxi.collect_probe_ffxi_utf16_runs ~= nil) then
        ffxi_utf16 = accessxi.probe_runs_to_text(accessxi.collect_probe_ffxi_utf16_runs(ptr, 0x240, 3, 5));
    end

    return ('desc=0x%08X name="%s" small="%s" ascii="%s" utf16="%s" ffxi16="%s"'):fmt(
        desc,
        accessxi.escape_probe_log_text(desc_name),
        accessxi.escape_probe_log_text(small:concat(' ')),
        accessxi.escape_probe_log_text(ascii),
        accessxi.escape_probe_log_text(utf16),
        accessxi.escape_probe_log_text(ffxi_utf16));
end

function accessxi.chat_log_probe_large_list_candidates(obj)
    obj = tonumber(obj) or 0;
    if (not accessxi.is_probe_pointer(obj)) then
        return '';
    end

    local seen = {};
    local seeds = T{};
    local function add_seed(label, ptr)
        ptr = tonumber(ptr) or 0;
        if (accessxi.is_probe_pointer(ptr) and seen[ptr] ~= true and seeds:len() < 160) then
            seen[ptr] = true;
            seeds:append(T{ label = label, ptr = ptr });
        end
    end

    add_seed('obj', obj);
    for _, off in ipairs(T{ 0x08, 0x0C, 0x14, 0x18, 0x58, 0x84, 0x88, 0x8C, 0x90, 0x98, 0x9C, 0xA0, 0xC8, 0xEC, 0xF0, 0x1B0, 0x1B4 }) do
        add_seed(('obj+%03X'):fmt(off), read_u32(obj + off) or 0);
    end
    for step = -24, 24 do
        if (step ~= 0) then
            add_seed(('sib%+d'):fmt(step), obj + (step * 0xE8));
        end
    end

    local seed_count = seeds:len();
    for i = 1, seed_count do
        local seed = seeds[i];
        local ptr = tonumber(seed.ptr) or 0;
        for _, off in ipairs(T{ 0x00, 0x04, 0x08, 0x0C, 0x10, 0x14, 0x18, 0x1C, 0x20, 0x24, 0x28, 0x40, 0x44, 0x58, 0x60, 0x80, 0x84, 0x88, 0x8C, 0x90, 0xA0, 0xC0, 0xC8, 0xE0, 0x100, 0x104, 0x108, 0x140, 0x180, 0x1B0, 0x1B4, 0x1C0 }) do
            add_seed(('%s+%03X'):fmt(seed.label or '', off), read_u32(ptr + off) or 0);
        end
    end

    local parts = T{};
    for _, seed in ipairs(seeds) do
        local ptr = tonumber(seed.ptr) or 0;
        local desc = read_u32(ptr + 0x04) or 0;
        local desc_name = accessxi.is_probe_pointer(desc) and tostring(read_probe_string(desc + 0x46) or '') or '';
        local fields = T{};
        for off = 0, 0x260, 4 do
            local value = read_i32(ptr + off);
            if (value ~= nil and value >= 65 and value <= 256) then
                fields:append(('+%03X=%d'):fmt(off, value));
                if (fields:len() >= 16) then
                    break;
                end
            end
        end

        local desc_lower = desc_name:lower();
        if (fields:len() > 0
            or desc_lower:find('log', 1, true) ~= nil
            or desc_lower:find('chat', 1, true) ~= nil) then
            local ptrs = T{};
            for _, off in ipairs(T{ 0x08, 0x0C, 0x14, 0x18, 0x20, 0x24, 0x28, 0x40, 0x44, 0x88, 0xC8, 0x100, 0x104 }) do
                local p = read_u32(ptr + off) or 0;
                if (accessxi.is_probe_pointer(p)) then
                    ptrs:append(('+%03X=0x%08X'):fmt(off, p));
                end
            end

            local ascii = '';
            if (accessxi.collect_probe_ascii_runs ~= nil and accessxi.probe_runs_to_text ~= nil) then
                ascii = accessxi.probe_runs_to_text(accessxi.collect_probe_ascii_runs(ptr, 0x280, 4, 5));
            end
            local lines = '';
            if (accessxi.chat_log_probe_timestamp_lines ~= nil) then
                lines = accessxi.chat_log_probe_timestamp_lines(ptr, 0x1000, 8);
            end

            parts:append(('%s=0x%08X desc="%s" large="%s" ptrs="%s" lines="%s" ascii="%s"'):fmt(
                tostring(seed.label or ''),
                ptr,
                accessxi.escape_probe_log_text(desc_name),
                fields:len() > 0 and fields:concat(' ') or 'none',
                accessxi.escape_probe_log_text(ptrs:concat(' | ')),
                accessxi.escape_probe_log_text(lines),
                accessxi.escape_probe_log_text(ascii)));
            if (parts:len() >= 24) then
                break;
            end
        end
    end

    return parts:len() > 0 and parts:concat(' || ') or 'none';
end

function accessxi.chat_log_probe_pointer_table_summary(obj, start_off, end_off, limit)
    obj = tonumber(obj) or 0;
    if (not accessxi.is_probe_pointer(obj)) then
        return '';
    end

    start_off = tonumber(start_off) or 0;
    end_off = tonumber(end_off) or start_off;
    limit = tonumber(limit) or 24;
    local parts = T{};
    local seen = {};
    for off = start_off, end_off, 4 do
        local ptr = read_u32(obj + off) or 0;
        if (accessxi.is_probe_pointer(ptr) and seen[ptr] ~= true) then
            seen[ptr] = true;
            parts:append(('+%03X=0x%08X %s'):fmt(
                off,
                ptr,
                accessxi.chat_log_probe_node_summary(ptr)));
            if (#parts >= limit) then
                break;
            end
        end
    end
    return parts:concat(' | ');
end

function accessxi.chat_log_probe_small_fields(obj)
    obj = tonumber(obj) or 0;
    if (not accessxi.is_probe_pointer(obj)) then
        return '';
    end

    local parts = T{};
    for off = 0, 0x1FC, 4 do
        local value = read_i32(obj + off);
        if (value ~= nil and value >= -4 and value <= 512) then
            parts:append(('+%03X=%d'):fmt(off, value));
            if (parts:len() >= 96) then
                break;
            end
        end
    end
    return parts:concat(' ');
end

function accessxi.chat_log_probe_sibling_summary(obj)
    obj = tonumber(obj) or 0;
    if (not accessxi.is_probe_pointer(obj)) then
        return '';
    end

    local parts = T{};
    for step = -10, 10 do
        local ptr = obj + (step * 0xE8);
        if (accessxi.is_probe_pointer(ptr)) then
            local desc_name = accessxi.chat_log_desc_name_for_obj(ptr);
            if (desc_name ~= '') then
                parts:append(('%+d:0x%08X "%s" +24=%d +28=%d +4C=%d +54=%d +5C=%d +88=0x%08X'):fmt(
                    step,
                    ptr,
                    accessxi.escape_probe_log_text(desc_name),
                    tonumber(read_i32(ptr + 0x24)) or -9999,
                    tonumber(read_i32(ptr + 0x28)) or -9999,
                    tonumber(read_i32(ptr + 0x4C)) or -9999,
                    tonumber(read_i32(ptr + 0x54)) or -9999,
                    tonumber(read_i32(ptr + 0x5C)) or -9999,
                    read_u32(ptr + 0x88) or 0));
                if (parts:len() >= 18) then
                    break;
                end
            end
        end
    end
    return parts:concat(' | ');
end

function accessxi.log_chat_log_selection_probe(reason, force)
    local now = tick();
    if (force ~= true and now > (accessxi.chat_log_probe_until or 0)) then
        return;
    end
    if (force ~= true and ((now - (accessxi.chat_log_probe_last_tick or 0)) < 120)) then
        return;
    end
    accessxi.chat_log_probe_last_tick = now;

    local name = get_menu_name() or '';
    local obj = tonumber(get_current_menu_object_ptr()) or 0;
    local source_name = name;
    local source_obj = obj;
    local cached_probe = 0;
    local force_reason = tostring(reason or '');
    local trace_poll = force_reason:eq('trace-poll', true);
    if (not is_chat_log_menu_name(name)) then
        return;
    end

    local target = AshitaCore:GetMemoryManager():GetTarget();
    local window_name = '';
    local ank_num = -1;
    local ank_x = -1;
    local ank_y = -1;
    local sub = -1;
    local sub_x = -1;
    local sub_y = -1;
    if (target ~= nil) then
        window_name = clean_probe_text(safe_call(function () return target:GetWindowName(); end, ''));
        ank_num = tonumber(safe_call(function () return target:GetWindowAnkNum(); end, -1)) or -1;
        ank_x = tonumber(safe_call(function () return target:GetWindowAnkX(); end, -1)) or -1;
        ank_y = tonumber(safe_call(function () return target:GetWindowAnkY(); end, -1)) or -1;
        sub = tonumber(safe_call(function () return target:GetWindowSub(); end, -1)) or -1;
        sub_x = tonumber(safe_call(function () return target:GetWindowSubAnkX(); end, -1)) or -1;
        sub_y = tonumber(safe_call(function () return target:GetWindowSubAnkY(); end, -1)) or -1;
    end

    local desc = obj ~= 0 and (read_u32(obj + 0x04) or 0) or 0;
    local line_block = obj ~= 0 and (read_u32(obj + 0x08) or 0) or 0;
    local child = obj ~= 0 and (read_u32(obj + 0x0C) or 0) or 0;
    local visible = obj ~= 0 and (read_u32(obj + 0x88) or 0) or 0;
    local native = accessxi.chat_log_native_line_from_obj(obj, name);
    local native_source = native ~= nil and tostring(native.source or '') or '';
    local native_score = native ~= nil and (tonumber(native.score) or 0) or 0;
    local native_text = native ~= nil and tostring(native.text or '') or '';

    accessxi.chat_log_probe_sequence = (accessxi.chat_log_probe_sequence or 0) + 1;
    local seq = accessxi.chat_log_probe_sequence;
    local key = ('%s:0x%08X:%s:%s:%s:%s:%s:%s:%s:%s'):fmt(
        name,
        obj,
        accessxi.format_probe_dwords(obj, 0x20, 24),
        accessxi.format_probe_dwords(obj, 0x80, 24),
        accessxi.format_probe_dwords(obj, 0xC0, 24),
        accessxi.format_probe_dwords(line_block, 0x00, 32),
        accessxi.probe_runs_to_text(accessxi.collect_probe_ascii_runs(visible, 0x220, 3, 10)),
        accessxi.probe_runs_to_text(accessxi.collect_probe_ascii_runs(line_block, 0x220, 3, 10)),
        native_source,
        native_text);
    if (force ~= true and key == (accessxi.chat_log_probe_last_log or '')) then
        return;
    end
    accessxi.chat_log_probe_last_log = key;

    log_line(('chatprobe seq=%d reason=%s menu="%s" win="%s" obj=0x%08X desc=0x%08X descName="%s" sourceMenu="%s" sourceObj=0x%08X cached=%d lineBlock=0x%08X child=0x%08X visible=0x%08X ank=%d xy=(%d,%d) sub=%d subxy=(%d,%d) best="%s" source="%s" score=%d'):fmt(
        seq,
        tostring(reason or ''),
        name,
        window_name,
        obj,
        desc,
        accessxi.escape_probe_log_text(read_probe_string(desc + 0x46)),
        accessxi.escape_probe_log_text(source_name),
        source_obj,
        cached_probe,
        line_block,
        child,
        visible,
        ank_num,
        ank_x,
        ank_y,
        sub,
        sub_x,
        sub_y,
        accessxi.escape_probe_log_text(native_text),
        accessxi.escape_probe_log_text(native_source),
        native_score));
    log_line(('chatprobe seq=%d fields small="%s" dwords000=%s dwords040=%s dwords080=%s dwords0C0=%s dwords100=%s dwords140=%s dwords180=%s dwords1C0=%s dwords200=%s'):fmt(
        seq,
        accessxi.chat_log_probe_small_fields(obj),
        accessxi.format_probe_dwords(obj, 0x00, 16),
        accessxi.format_probe_dwords(obj, 0x40, 16),
        accessxi.format_probe_dwords(obj, 0x80, 16),
        accessxi.format_probe_dwords(obj, 0xC0, 16),
        accessxi.format_probe_dwords(obj, 0x100, 16),
        accessxi.format_probe_dwords(obj, 0x140, 16),
        accessxi.format_probe_dwords(obj, 0x180, 16),
        accessxi.format_probe_dwords(obj, 0x1C0, 16),
        accessxi.format_probe_dwords(obj, 0x200, 16)));
    log_line(('chatprobe seq=%d ptrs %s'):fmt(seq, accessxi.chat_log_probe_ptr_summary(obj)));
    if (trace_poll == true or force == true) then
        log_line(('chatprobe seq=%d siblings %s'):fmt(seq, accessxi.chat_log_probe_sibling_summary(obj)));
    end
    log_line(('chatprobe seq=%d lineBlockLines %s'):fmt(seq, accessxi.chat_log_probe_timestamp_lines(line_block, 0x1800, 32)));
    log_line(('chatprobe seq=%d visibleLines %s'):fmt(seq, accessxi.chat_log_probe_timestamp_lines(visible, 0x800, 20)));
    log_line(('chatprobe seq=%d visibleRowContext %s'):fmt(seq, accessxi.chat_log_probe_timestamp_context(visible, 0x800, 8)));
    log_line(('chatprobe seq=%d visibleText ascii="%s" utf16="%s" lineText ascii="%s" utf16="%s" childText ascii="%s" utf16="%s"'):fmt(
        seq,
        accessxi.escape_probe_log_text(accessxi.probe_runs_to_text(accessxi.collect_probe_ascii_runs(visible, 0x300, 2, 16))),
        accessxi.escape_probe_log_text(accessxi.probe_runs_to_text(accessxi.collect_probe_utf16_runs(visible, 0x300, 2, 16))),
        accessxi.escape_probe_log_text(accessxi.probe_runs_to_text(accessxi.collect_probe_ascii_runs(line_block, 0x300, 2, 16))),
        accessxi.escape_probe_log_text(accessxi.probe_runs_to_text(accessxi.collect_probe_utf16_runs(line_block, 0x300, 2, 16))),
        accessxi.escape_probe_log_text(accessxi.probe_runs_to_text(accessxi.collect_probe_ascii_runs(child, 0x300, 2, 16))),
        accessxi.escape_probe_log_text(accessxi.probe_runs_to_text(accessxi.collect_probe_utf16_runs(child, 0x300, 2, 16)))));
    if (force == true and trace_poll ~= true) then
        log_line(('chatprobe seq=%d largeLists %s'):fmt(
            seq,
            accessxi.chat_log_probe_large_list_candidates(obj)));
    end
end

function accessxi.poll_chat_log_native_trace()
    local now = tick();
    if (now > (accessxi.chat_log_native_trace_until or 0)) then
        return;
    end
    if ((now - (accessxi.chat_log_trace_poll_last_tick or 0)) < 250) then
        return;
    end
    accessxi.chat_log_trace_poll_last_tick = now;
    accessxi.log_chat_log_selection_probe('trace-poll', true);
end

function accessxi.enable_chat_log_probe(reason)
    accessxi.chat_log_probe_until = tick() + 30000;
    accessxi.chat_log_probe_last_tick = 0;
    accessxi.chat_log_probe_last_log = '';
    log_line(('chatprobe enabled for 30 seconds reason=%s'):fmt(reason or 'manual'));
    speak('Chat log probe enabled for 30 seconds.');
end

local function log_equipment_native_probe(menu_name)
    local now = tick();
    if (now > (accessxi.equipment_probe_until or 0)) then
        return;
    end

    if ((now - accessxi.last_equipment_native_probe_tick) < 250) then
        return;
    end
    accessxi.last_equipment_native_probe_tick = now;

    local obj = get_current_menu_object_ptr();
    local target = AshitaCore:GetMemoryManager():GetTarget();
    local shapes = T{};
    if (target ~= nil) then
        for i = 0, 15 do
            local shape = safe_call(function () return target:GetWindowAnkShape(i); end, nil);
            if (shape ~= nil) then
                append_limited(shapes, ('%d=%s'):fmt(i, tostring(shape)), 24);
            end
        end
    end

    local small32 = T{};
    local bytes = T{};
    if (obj ~= 0) then
        for off = 0, 0x120, 4 do
            local svalue = read_i32(obj + off);
            if (svalue ~= nil and svalue >= -1 and svalue <= 128) then
                append_limited(small32, ('+%02X=%d'):fmt(off, svalue), 80);
            end

            local uvalue = read_u32(obj + off);
            if (uvalue ~= nil) then
                for byte_index = 0, 3 do
                    local byte_value = bit.band(bit.rshift(uvalue, byte_index * 8), 0xFF);
                    if (byte_value <= 32) then
                        append_limited(bytes, ('+%02X.%d=%d'):fmt(off, byte_index, byte_value), 96);
                    end
                end
            end
        end
    end

    local base = get_ffximain_base();
    local line = ('equipnative menu="%s" obj=0x%08X ffximain=0x%08X layout=%s equipDesc=%s equipRuntime=%s invRuntime=%s shapes=%s small32=%s bytes=%s'):fmt(
        menu_name or '',
        obj,
        base,
        format_runtime_dwords(base, 0x36F7E8, 6),
        format_runtime_dwords(base, 0x3729E4, 6),
        format_runtime_dwords(base, 0x5781A8, 8),
        format_runtime_dwords(base, 0x630C20, 8),
        shapes:concat(' '),
        small32:concat(' '),
        bytes:concat(' '));

    if (line ~= accessxi.last_equipment_native_probe_log) then
        accessxi.last_equipment_native_probe_log = line;
        log_line(line);
    end
end

local function log_equipment_selection_candidates(menu_name)
    local now = tick();
    if ((now - (accessxi.last_equipment_candidate_tick or 0)) < 150) then
        return;
    end
    accessxi.last_equipment_candidate_tick = now;

    local obj = get_current_menu_object_ptr();
    local target = AshitaCore:GetMemoryManager():GetTarget();
    local inv = AshitaCore:GetMemoryManager():GetInventory();

    local d32 = T{};
    local h16 = T{};
    local u8s = T{};
    if (obj ~= 0) then
        for off = 0, 0x1FC, 4 do
            local value = read_i32(obj + off);
            if (value ~= nil and value >= -1 and value <= 32) then
                append_limited(d32, ('+%03X=%d'):fmt(off, value), 80);
            end
        end

        for off = 0, 0x1FE, 2 do
            local value = read_u16(obj + off);
            if (value ~= nil and value <= 32) then
                append_limited(h16, ('+%03X=%d'):fmt(off, value), 96);
            end
        end

        for off = 0, 0x1FF do
            local value = read_u8(obj + off);
            if (value ~= nil and value <= 16) then
                append_limited(u8s, ('+%03X=%d'):fmt(off, value), 96);
            end
        end
    end

    local line = ('equipcandidate menu="%s" obj=0x%08X ank=%s ankXY=(%s,%s) sub=%s subXY=(%s,%s) display=%s selId=%s selIndex=%s selName="%s" d32=%s h16=%s u8=%s'):fmt(
        menu_name or '',
        obj,
        tostring(target ~= nil and safe_call(function () return target:GetWindowAnkNum(); end, -1) or -1),
        tostring(target ~= nil and safe_call(function () return target:GetWindowAnkX(); end, -1) or -1),
        tostring(target ~= nil and safe_call(function () return target:GetWindowAnkY(); end, -1) or -1),
        tostring(target ~= nil and safe_call(function () return target:GetWindowSub(); end, -1) or -1),
        tostring(target ~= nil and safe_call(function () return target:GetWindowSubAnkX(); end, -1) or -1),
        tostring(target ~= nil and safe_call(function () return target:GetWindowSubAnkY(); end, -1) or -1),
        tostring(inv ~= nil and safe_call(function () return inv:GetDisplayItemSlot(); end, -1) or -1),
        tostring(inv ~= nil and safe_call(function () return inv:GetSelectedItemId(); end, -1) or -1),
        tostring(inv ~= nil and safe_call(function () return inv:GetSelectedItemIndex(); end, -1) or -1),
        clean_login_text(inv ~= nil and safe_call(function () return inv:GetSelectedItemName(); end, '') or ''),
        d32:concat(' '),
        h16:concat(' '),
        u8s:concat(' '));

    if (line ~= accessxi.last_equipment_candidate_log) then
        accessxi.last_equipment_candidate_log = line;
        log_line(line);
    end
end

local function enable_equipment_probe(reason)
    accessxi.equipment_probe_until = tick() + 30000;
    accessxi.last_equipment_native_probe_log = '';
    accessxi.last_equipment_native_probe_tick = 0;
    accessxi.last_equipment_transition_probe_log = '';
    accessxi.last_equipment_transition_probe_tick = 0;
