local function poll_equipment_probe_hotkey()
    accessxi.equipment_probe_hotkey_down = false;
end

local function read_native_equipment_grid(native_grid)
    native_grid = valid_equipment_grid_index(native_grid);
    if (native_grid >= 0) then
        accessxi.equipment_cursor_grid = native_grid;
    else
        accessxi.equipment_cursor_grid = -1;
    end

    return accessxi.equipment_cursor_grid;
end

local function read_native_equipment_slot(native_slot)
    native_slot = valid_equipment_slot_index(native_slot);
    if (native_slot >= 0) then
        return native_slot;
    end

    return -1;
end

local function selected_equipment_slot_from_inventory()
    local inv = AshitaCore:GetMemoryManager():GetInventory();
    if (inv == nil) then
        return -1;
    end

    local selected_id = tonumber(safe_call(function () return inv:GetSelectedItemId(); end, 0)) or 0;
    local selected_index = tonumber(safe_call(function () return inv:GetSelectedItemIndex(); end, -1)) or -1;
    if (selected_index < 0 and not is_valid_inventory_item_id(selected_id)) then
        return -1;
    end

    local fallback_slot = -1;
    for slot = 0, 15 do
        local eitem = safe_call(function () return inv:GetEquippedItem(slot); end, nil);
        if (eitem ~= nil and eitem.Index ~= nil and eitem.Index ~= 0) then
            local index = tonumber(eitem.Index) or 0;
            local container = math.floor(bit.band(index, 0xFF00) / 0x0100);
            local container_slot = bit.band(index, 0x00FF);
            local item = safe_call(function () return inv:GetContainerItem(container, container_slot); end, nil);
            local item_id = item ~= nil and tonumber(item.Id) or 0;
            local index_matches = selected_index == container_slot or selected_index == index;
            local id_matches = is_valid_inventory_item_id(selected_id) and item_id == selected_id;

            if (index_matches and id_matches) then
                return slot;
            end

            if (index_matches and fallback_slot < 0) then
                fallback_slot = slot;
            end
        end
    end

    return fallback_slot;
end

local function get_equipped_slot_item(slot, live_name)
    local inv = AshitaCore:GetMemoryManager():GetInventory();
    if (inv == nil or slot < 0 or slot > 15) then
        return nil;
    end

    local eitem = safe_call(function () return inv:GetEquippedItem(slot); end, nil);
    if (eitem == nil or eitem.Index == nil or eitem.Index == 0) then
        return T{
            slot = slot,
            slot_name = equipment_slot_names[slot] or ('Slot %d'):fmt(slot + 1),
            empty = true,
            id = 0,
            index = 0,
            container = -1,
            container_slot = -1,
            count = 0,
            name = '',
            description = '',
        };
    end

    local index = tonumber(eitem.Index) or 0;
    local container = math.floor(bit.band(index, 0xFF00) / 0x0100);
    local container_slot = bit.band(index, 0x00FF);
    local item = safe_call(function () return inv:GetContainerItem(container, container_slot); end, nil);
    local item_id = item ~= nil and tonumber(item.Id) or 0;
    local item_count = tonumber(inventory_item_count(item)) or 0;
    local resource_info = resource_item_info(item_id);
    local name = clean_login_text(live_name or '');
    if (name ~= ''
        and is_valid_inventory_item_id(item_id)
        and not accessxi.resource_item_info_name_matches(resource_info, name)) then
        local named_resource_info = accessxi.resource_item_info_by_name(name);
        if (named_resource_info ~= nil) then
            log_state(('state equipment resource-name-corrected slot=%d oldId=%d oldName="%s" newId=%d visibleName="%s"'):fmt(
                slot,
                item_id,
                resource_info.name or '',
                tonumber(named_resource_info.id) or 0,
                name));
            item_id = tonumber(named_resource_info.id) or item_id;
            resource_info = named_resource_info;
            if (item ~= nil and tonumber(item.Id) ~= item_id) then
                item = nil;
                item_count = 0;
            end
        end
    end
    local detail_parts = item_static_detail_parts(resource_info);
    for _, part in ipairs(item_dynamic_detail_parts(item, true)) do
        detail_parts:append(part);
    end
    if (not has_charge_detail(detail_parts)) then
        for _, part in ipairs(item_fallback_charge_parts(resource_info)) do
            detail_parts:append(part);
        end
    end

    if (name == '' and is_valid_inventory_item_id(item_id)) then
        return nil;
    end

    if (not is_valid_inventory_item_id(item_id)) then
        return T{
            slot = slot,
            slot_name = equipment_slot_names[slot] or ('Slot %d'):fmt(slot + 1),
            empty = true,
            id = item_id,
            index = index,
            container = container,
            container_slot = container_slot,
            count = 0,
            name = '',
            description = '',
        };
    end

    return T{
        slot = slot,
        slot_name = equipment_slot_names[slot] or ('Slot %d'):fmt(slot + 1),
        empty = false,
        id = item_id,
        index = index,
        container = container,
        container_slot = container_slot,
        count = item_count,
        name = name,
        description = resource_info.description,
        detail_parts = detail_parts,
    };
end

local function log_equipment_transition_probe(menu_name, native4c, resolved_slot, resolved_info)
    local now = tick();
    if ((now - (accessxi.last_equipment_transition_probe_tick or 0)) < 100) then
        return;
    end
    accessxi.last_equipment_transition_probe_tick = now;

    local obj = get_current_menu_object_ptr();
    local target = AshitaCore:GetMemoryManager():GetTarget();
    local inv = AshitaCore:GetMemoryManager():GetInventory();

    local cursor_grid = equipment_grid_from_native_cursor(native4c);
    local cursor_slot = cursor_grid >= 0 and (equipment_grid_slot_order[cursor_grid] or -1) or -1;
    local cursor_info = get_equipped_slot_item(cursor_slot);

    local display_slot = inv ~= nil and safe_call(function () return inv:GetDisplayItemSlot(); end, -1) or -1;
    local selected_id = inv ~= nil and safe_call(function () return inv:GetSelectedItemId(); end, -1) or -1;
    local selected_index = inv ~= nil and safe_call(function () return inv:GetSelectedItemIndex(); end, -1) or -1;
    local selected_name = clean_login_text(inv ~= nil and safe_call(function () return inv:GetSelectedItemName(); end, '') or '');

    local line = ('equiptransition menu="%s" obj=0x%08X ank=%s sub=%s select30=%d select34=%d native4c=%d cursorGrid=%d cursorSlot=%d cursorSlotName="%s" cursorEmpty=%d cursorIndex=0x%04X cursorName="%s" resolvedSlot=%d resolvedSlotName="%s" resolvedEmpty=%d resolvedIndex=0x%04X resolvedName="%s" display=%s selId=%s selIndex=%s selName="%s"'):fmt(
        menu_name or '',
        obj,
        tostring(target ~= nil and safe_call(function () return target:GetWindowAnkNum(); end, -1) or -1),
        tostring(target ~= nil and safe_call(function () return target:GetWindowSub(); end, -1) or -1),
        read_current_native_menu_index(0x30),
        read_current_native_menu_index(0x34),
        native4c,
        cursor_grid,
        cursor_slot,
        cursor_slot >= 0 and (equipment_slot_names[cursor_slot] or ('Slot %d'):fmt(cursor_slot + 1)) or '',
        cursor_info ~= nil and cursor_info.empty and 1 or 0,
        cursor_info ~= nil and (cursor_info.index or 0) or 0,
        cursor_info ~= nil and (cursor_info.name or '') or '',
        resolved_slot or -1,
        resolved_info ~= nil and (resolved_info.slot_name or '') or '',
        resolved_info ~= nil and resolved_info.empty and 1 or 0,
        resolved_info ~= nil and (resolved_info.index or 0) or 0,
        resolved_info ~= nil and (resolved_info.name or '') or '',
        tostring(display_slot),
        tostring(selected_id),
        tostring(selected_index),
        selected_name);

    if (line ~= accessxi.last_equipment_transition_probe_log) then
        accessxi.last_equipment_transition_probe_log = line;
        log_line(line);
    end
end

local function remember_equipment_slot(slot, slot_name)
    slot = tonumber(slot) or -1;
    if (slot < 0 or slot > 15) then
        return;
    end

    accessxi.last_equipment_slot = slot;
    accessxi.last_equipment_slot_name = slot_name ~= nil and slot_name ~= '' and slot_name or (equipment_slot_names[slot] or ('Slot %d'):fmt(slot + 1));
end

local function selected_equipment_speech(menu_name, menu_just_opened, full_details)
    local ank_num = read_target_ank_num();
    local select30 = read_current_native_menu_index(0x30);
    local select34 = read_current_native_menu_index(0x34);
    local native4c = read_current_native_menu_index(0x4C);
    local native4c_grid = equipment_grid_from_native_cursor(native4c);
    local inv = AshitaCore:GetMemoryManager():GetInventory();
    local selected_id = inv ~= nil and tonumber(safe_call(function () return inv:GetSelectedItemId(); end, 0)) or 0;
    local selected_index = inv ~= nil and tonumber(safe_call(function () return inv:GetSelectedItemIndex(); end, -1)) or -1;
    local selected_name = clean_login_text(inv ~= nil and safe_call(function () return inv:GetSelectedItemName(); end, '') or '');
    local slot = selected_equipment_slot_from_inventory();
    if (slot < 0 and native4c_grid >= 0) then
        slot = equipment_grid_slot_order[native4c_grid] or -1;
    end
    local info = get_equipped_slot_item(slot, selected_name);
    local info_slot = tonumber(raw_table_value(info, 'slot', -1)) or -1;
    local info_slot_name = tostring(raw_table_value(info, 'slot_name', '') or '');
    local info_id = tonumber(raw_table_value(info, 'id', 0)) or 0;
    local info_index = tonumber(raw_table_value(info, 'index', 0)) or 0;
    local info_container = tonumber(raw_table_value(info, 'container', -1)) or -1;
    local info_container_slot = tonumber(raw_table_value(info, 'container_slot', -1)) or -1;
    local info_name = tostring(raw_table_value(info, 'name', '') or '');
    local info_count = tonumber(raw_table_value(info, 'count', 0)) or 0;
    local info_description = tostring(raw_table_value(info, 'description', '') or '');

    log_state(('state equipment native menu="%s" ank=%d select30=%d select34=%d native4c=%d native4cGrid=%d selId=%d selIndex=0x%04X selName="%s" resolvedSlot=%d slotName="%s" id=%d index=0x%04X container=%d containerSlot=%d name="%s" count=%d descLen=%d'):fmt(
        menu_name or '',
        tonumber(ank_num) or -1,
        tonumber(select30) or -1,
        tonumber(select34) or -1,
        tonumber(native4c) or -1,
        tonumber(native4c_grid) or -1,
        tonumber(selected_id) or 0,
        math.max(selected_index, 0),
        selected_name,
        info_slot,
        info_slot_name,
        info_id,
        info_index,
        info_container,
        info_container_slot,
        info_name,
        info_count,
        #info_description));
    log_equipment_native_probe(menu_name);

    if (info == nil) then
        accessxi.current_speech_key = ('equipment-native-missing:%s:%d:%d:%d:%d:%s'):fmt(
            menu_name or '',
            native4c,
            native4c_grid,
            selected_id,
            math.max(selected_index, 0),
            selected_name);
        log_state(('state equipment native-missing menu="%s" native4c=%d native4cGrid=%d selId=%d selIndex=0x%04X selName="%s"'):fmt(
            menu_name or '',
            native4c,
            native4c_grid,
            selected_id,
            math.max(selected_index, 0),
            selected_name));
        return info_slot_name;
    end

    if (info.empty) then
        accessxi.current_speech_key = ('equipment-native-empty:%s:%d:%d:%d:%s'):fmt(
            menu_name or '',
            info_slot,
            selected_id,
            math.max(selected_index, 0),
            selected_name);
        log_state(('state equipment native-empty menu="%s" slot=%d slotName="%s" selId=%d selIndex=0x%04X selName="%s"'):fmt(
            menu_name or '',
            info_slot,
            info_slot_name,
            selected_id,
            math.max(selected_index, 0),
            selected_name));
        return info_slot_name;
    end

    remember_equipment_slot(info.slot, info.slot_name);
    accessxi.current_speech_key = ('equipment-native:%s:%d:%d:%d:%s'):fmt(
        menu_name or '',
        info.slot or -1,
        info.index or 0,
        info.id or 0,
        info.name or '');
    local parts = T{ info.slot_name, info.name };
    if (info_count > 1) then
        parts:append(('Quantity %d'):fmt(info_count));
    end
    if (info.detail_parts ~= nil) then
        for _, part in ipairs(info.detail_parts) do
            if (part ~= nil and part ~= '') then
                parts:append(part);
            end
        end
    end
    if (info.description ~= nil and info.description ~= '') then
        parts:append(info.description);
    end

    accessxi.capture_current_gear_detail(menu_name, info, T{
        slot_name = info.slot_name,
        source = 'equipment',
    });

    return join_speech_parts(parts);
end

function accessxi.native_vendor_shop_item_info(menu_name, obj, entry, label_ptr, help_ptr, item_id, selected_index, display_slot, name, entry_help)
    item_id = tonumber(item_id) or 0;
    selected_index = tonumber(selected_index) or -1;
    display_slot = tonumber(display_slot) or -1;
    name = tostring(name or '');
    entry_help = tostring(entry_help or '');

    local visible_name = name;
    local selected_item_id = item_id;
    local resource_info = resource_item_info(item_id);
    if ((not is_valid_inventory_item_id(item_id))
        or resource_info == nil
        or (name ~= '' and not accessxi.resource_item_info_name_matches(resource_info, name))) then
        local named_resource_info = accessxi.resource_item_info_by_name(name);
        if (named_resource_info ~= nil and is_valid_inventory_item_id(named_resource_info.id)) then
            item_id = tonumber(named_resource_info.id) or item_id;
            resource_info = named_resource_info;
        end
    end
    local price, price_source, price_age = accessxi.vendor_shop_price_for_item(selected_item_id, name);
    if (price == nil and selected_item_id ~= item_id) then
        price, price_source, price_age = accessxi.vendor_shop_price_for_item(item_id, name);
    end

    local detail_parts = T{};
    if (is_valid_inventory_item_id(item_id)) then
        detail_parts = item_static_detail_parts(resource_info);
        if (not has_charge_detail(detail_parts)) then
            for _, part in ipairs(item_fallback_charge_parts(resource_info)) do
                detail_parts:append(part);
            end
        end
    end

    local description = '';
    if (entry_help ~= '' and not entry_help:eq(visible_name, true)) then
        description = entry_help;
    elseif (resource_info ~= nil and tostring(resource_info.description or '') ~= '') then
        description = resource_info.description;
    end

    local speech_name, speech_name_source = accessxi.resource_item_speech_name(resource_info, name);
    if (speech_name == '') then
        speech_name = visible_name;
        speech_name_source = 'native-name';
    end

    log_state(('state inventory vendor-shop-name menu="%s" obj=0x%08X entry=0x%08X labelPtr=0x%08X helpPtr=0x%08X id=%d index=0x%04X displaySlot=%d name="%s" visibleName="%s" nameSource="%s" price=%d priceSource="%s" priceAge=%d detailCount=%d descSource="%s" desc="%s"'):fmt(
        menu_name or '',
        tonumber(obj) or 0,
        tonumber(entry) or 0,
        tonumber(label_ptr) or 0,
        tonumber(help_ptr) or 0,
        item_id,
        math.max(selected_index, 0),
        display_slot,
        speech_name,
        visible_name,
        speech_name_source,
        tonumber(price) or 0,
        accessxi.escape_probe_log_text(price_source or ''),
        tonumber(price_age) or -1,
        detail_parts:len(),
        entry_help ~= '' and 'entry-help' or 'item-resource-help',
        accessxi.escape_probe_log_text(description)));

    local info = T{
        id = item_id,
        index = selected_index,
        display_slot = display_slot,
        visible_position = display_slot,
        container = -1,
        slot = display_slot,
        container_name = 'Shop',
        count = 0,
        container_count = 0,
        container_max = 0,
        name = speech_name,
        visible_name = visible_name,
        name_source = speech_name_source,
        price = tonumber(price) or 0,
        price_source = price_source or '',
        price_age = price_age or -1,
        description = description,
        detail_parts = detail_parts,
        empty = false,
    };
    accessxi.last_native_inventory_item_info = info;
    accessxi.last_native_inventory_item_tick = tick();
    return info;
end

function accessxi.get_native_selected_inventory_item_info(menu_name)
    local inv = AshitaCore:GetMemoryManager():GetInventory();
    if (inv == nil) then
        return nil;
    end

    local selected_id = tonumber(safe_call(function () return inv:GetSelectedItemId(); end, 0)) or 0;
    local selected_index = tonumber(safe_call(function () return inv:GetSelectedItemIndex(); end, -1)) or -1;
    local display_slot = tonumber(safe_call(function () return inv:GetDisplayItemSlot(); end, -1)) or -1;
    local selected_name = accessxi.plain_native_menu_label(clean_login_text(safe_call(function () return inv:GetSelectedItemName(); end, '')));
    local obj = get_current_menu_object_ptr();
    local entry = obj ~= 0 and (read_u32(obj + 0x08) or 0) or 0;
    local label_ptr = accessxi.is_probe_pointer(entry) and (read_u32(entry + 0x44) or 0) or 0;
    local help_ptr = accessxi.is_probe_pointer(entry) and (read_u32(entry + 0x40) or 0) or 0;
    local entry_label = accessxi.plain_native_menu_label(read_probe_string(label_ptr));
    local entry_help = accessxi.plain_native_menu_label(read_probe_string(help_ptr));

    local name = selected_name;
    if (name == '' and entry_label ~= '') then
        name = entry_label;
    end

    local container = -1;
    local slot = -1;
    local visible_position = -1;
    local item = nil;
    local item_id = selected_id;
    local count = 0;
    local container_count = 0;
    local container_max = 0;

    if (selected_index >= 0) then
        container = math.floor(bit.band(selected_index, 0xFF00) / 0x0100);
        slot = bit.band(selected_index, 0x00FF);
        if (container >= 0 and container <= 17 and slot >= 0 and slot <= 255) then
            item = safe_call(function () return inv:GetContainerItem(container, slot); end, nil);
            if (item ~= nil and is_valid_inventory_item_id(item.Id)) then
                item_id = tonumber(item.Id) or item_id;
            end
            count = tonumber(inventory_item_count(item)) or 0;
            container_count = tonumber(safe_call(function () return inv:GetContainerCount(container); end, 0)) or 0;
            container_max = tonumber(safe_call(function () return inv:GetContainerCountMax(container); end, 0)) or 0;
            if (display_slot >= 0 and display_slot < container_count) then
                visible_position = display_slot;
            end
        end
    end

    if (accessxi.inventory_context == 'vendor_shop_item_list' and name ~= '') then
        return accessxi.native_vendor_shop_item_info(
            menu_name,
            obj,
            entry,
            label_ptr,
            help_ptr,
            item_id,
            selected_index,
            display_slot,
            name,
            entry_help);
    end

    if (name == '' or not is_valid_inventory_item_id(item_id)) then
        if (accessxi.inventory_context == 'equipment_list' and selected_id == 0 and selected_index == 0) then
            local selected = tonumber(read_current_native_menu_index(0x4C)) or 0;
            local rows = accessxi.load_equipment_set_slot_picker_command_rows();
            local label = rows ~= nil and tostring(rows[selected] or '') or '';
            local source = rows ~= nil and rows.sources ~= nil and tostring(rows.sources[selected] or '') or '';
            if (label == '') then
                log_state(('state inventory equipment-command missing menu="%s" obj=0x%08X entry=0x%08X select=%d displaySlot=%d'):fmt(
                    menu_name or '',
                    obj,
                    entry,
                    selected,
                    display_slot));
                return nil;
            end
            log_state(('state inventory equipment-command menu="%s" obj=0x%08X entry=0x%08X select=%d displaySlot=%d command="%s" source="%s"'):fmt(
                menu_name or '',
                obj,
                entry,
                selected,
                display_slot,
                accessxi.escape_probe_log_text(label),
                accessxi.escape_probe_log_text(source)));
            return T{
                id = 0,
                index = selected,
                display_slot = display_slot,
                visible_position = -1,
                container = -1,
                slot = -1,
                container_name = 'Equipment',
                count = 0,
                container_count = container_count,
                container_max = container_max,
                name = label,
                description = '',
                detail_parts = T{},
                empty = false,
                command = true,
            };
        end

        log_state(('state inventory native-missing menu="%s" obj=0x%08X entry=0x%08X labelPtr=0x%08X helpPtr=0x%08X id=%d index=0x%04X displaySlot=%d selectedName="%s" entryLabel="%s" entryHelp="%s"'):fmt(
            menu_name or '',
            obj,
            entry,
            label_ptr,
            help_ptr,
            item_id,
            math.max(selected_index, 0),
            display_slot,
            selected_name,
            entry_label,
            entry_help));
        return nil;
    end

    local resource_info = resource_item_info(item_id);
    if ((accessxi.inventory_context == 'equipment_list'
        or accessxi.inventory_context == 'equipment_set_slot_picker'
        or accessxi.inventory_context == 'vendor_shop_item_list')
        and name ~= ''
        and is_valid_inventory_item_id(item_id)
        and not accessxi.resource_item_info_name_matches(resource_info, name)) then
        local named_resource_info = accessxi.resource_item_info_by_name(name);
        if (named_resource_info ~= nil) then
            log_state(('state inventory resource-name-corrected menu="%s" oldId=%d oldName="%s" newId=%d visibleName="%s"'):fmt(
                menu_name or '',
                item_id,
                resource_info.name or '',
                tonumber(named_resource_info.id) or 0,
                name));
            item_id = tonumber(named_resource_info.id) or item_id;
            resource_info = named_resource_info;
            if (item ~= nil and tonumber(item.Id) ~= item_id) then
                item = nil;
                count = 0;
            end
        end
    end
    local detail_parts = item_static_detail_parts(resource_info);
    for _, part in ipairs(item_dynamic_detail_parts(item, false)) do
        detail_parts:append(part);
    end
    if (not has_charge_detail(detail_parts)) then
        for _, part in ipairs(item_fallback_charge_parts(resource_info)) do
            detail_parts:append(part);
        end
    end

    local description = resource_info.description;
    if (entry_help ~= '' and not entry_help:eq(name, true)) then
        description = entry_help;
    end

    local speech_name, speech_name_source = accessxi.resource_item_speech_name(resource_info, name);
    if (speech_name == '') then
        speech_name = name;
        speech_name_source = 'native-name';
    end

    log_state(('state inventory native menu="%s" obj=0x%08X entry=0x%08X labelPtr=0x%08X helpPtr=0x%08X id=%d index=0x%04X displaySlot=%d visiblePos=%d container=%d slot=%d name="%s" visibleName="%s" nameSource="%s" count=%d containerCount=%d containerMax=%d detailCount=%d descSource="%s" desc="%s"'):fmt(
        menu_name or '',
        obj,
        entry,
        label_ptr,
        help_ptr,
        item_id,
        math.max(selected_index, 0),
        display_slot,
        visible_position,
        container,
        slot,
        speech_name,
        name,
        speech_name_source,
        count,
        container_count,
        container_max,
        detail_parts:len(),
        entry_help ~= '' and 'entry-help' or 'item-resource-help',
        description));

    local info = T{
        id = item_id,
        index = selected_index,
        display_slot = display_slot,
        visible_position = visible_position,
        container = container,
        slot = slot,
        container_name = inventory_container_names[container] or 'Inventory',
        count = count,
        container_count = container_count,
        container_max = container_max,
        name = speech_name,
        visible_name = name,
        name_source = speech_name_source,
        description = description,
        detail_parts = detail_parts,
        empty = false,
    };
    accessxi.last_native_inventory_item_info = info;
    accessxi.last_native_inventory_item_tick = tick();
    return info;
end

function accessxi.remember_delivery_box_slot_text(text)
    text = accessxi.survival_guide_text(text or '');
    if (text == '') then
        return false;
    end

    local slot_text, body = text:match('^%s*Slot%s+(%d+)%s*:%s*(.+)$');
    local slot = tonumber(slot_text) or 0;
    if (slot < 1 or slot > 10 or body == nil or body == '') then
        return false;
    end

    local lower_body = body:lower();
    if (lower_body:find('buyer paid', 1, true) == nil
        and lower_body:find('put on auction', 1, true) == nil
        and lower_body:find('delivery box', 1, true) == nil
        and lower_body:find('returned', 1, true) == nil) then
        return false;
    end

    accessxi.delivery_box_slot_text = accessxi.delivery_box_slot_text or {};
    accessxi.delivery_box_slot_text[slot] = {
        text = text,
        tick = tick(),
    };
    log_state(('state mogpost slot-chat slot=%d text="%s"'):fmt(
        slot,
        accessxi.escape_probe_log_text(text)));
    return true;
end

accessxi.delivery_box_pbx_commands = {
    [0x01] = 'Work',
    [0x02] = 'Set',
    [0x03] = 'Send',
    [0x04] = 'Cancel',
    [0x05] = 'Check',
    [0x06] = 'Recv',
    [0x07] = 'Confirm',
    [0x08] = 'Accept',
    [0x09] = 'Reject',
    [0x0A] = 'Get',
    [0x0B] = 'Clear',
    [0x0C] = 'Query',
    [0x0D] = 'DeliOpen',
    [0x0E] = 'PostOpen',
    [0x0F] = 'PostClose',
};

function accessxi.delivery_box_pbx_command_name(command)
    command = tonumber(command) or 0;
    return accessxi.delivery_box_pbx_commands[command] or ('Command 0x%02X'):fmt(command);
end

function accessxi.delivery_box_pbx_i8(value)
    value = tonumber(value) or 0;
    if (value >= 128) then
        return value - 256;
    end
    return value;
end

function accessxi.delivery_box_pbx_box_name(boxno)
    boxno = tonumber(boxno) or 0;
    if (boxno == 1) then
        return 'incoming';
    elseif (boxno == 2) then
        return 'outgoing';
    elseif (boxno == -1) then
        return 'none';
    end
    return ('box%d'):fmt(boxno);
end

function accessxi.delivery_box_pbx_ascii(data, pos, length)
    local chars = T{};
    for index = 0, (tonumber(length) or 0) - 1 do
        local b = accessxi.packet_byte(data, pos + index);
        if (b == 0) then
            break;
        elseif (b >= 32 and b <= 126) then
            chars:append(string.char(b));
        end
    end
    return clean_resource_text(chars:concat(''));
end

function accessxi.delivery_box_packet_row_text(row)
    if (row == nil) then
        return '';
    end

    local item_id = tonumber(row.item_id) or 0;
    local stack = tonumber(row.stack) or 0;
    local sender = tostring(row.sender or ''):trim();
    local kind = tonumber(row.kind) or 0;
    if (item_id == 65535 and stack > 0 and (kind == 9 or sender:sub(1, 2):upper() == 'AH')) then
        return ('Auction House proceeds. %s gil'):fmt(accessxi.status_number(stack));
    end

    if (not is_valid_inventory_item_id(item_id)) then
        return '';
    end

    local info = resource_item_info(item_id);
    local name = tostring(info.name or '');
    if (name == '') then
        name = ('Item %d'):fmt(item_id);
    end

    local parts = T{ name };
    if (stack > 1) then
        parts:append(('Quantity %s'):fmt(accessxi.status_number(stack)));
    end

    if (sender ~= '') then
        if (sender:sub(1, 2):upper() == 'AH') then
            parts:append('Auction House');
        else
            parts:append(('From %s'):fmt(sender));
        end
    end

    return parts:concat('. ');
end

function accessxi.delivery_box_packet_set_row(boxno, work_slot, row)
    local box_name = accessxi.delivery_box_pbx_box_name(boxno);
    if (box_name ~= 'incoming' and box_name ~= 'outgoing') then
        return;
    end

    work_slot = tonumber(work_slot) or -1;
    if (work_slot < 0 or work_slot > 7) then
        return;
    end

    accessxi.delivery_box_packet_rows = accessxi.delivery_box_packet_rows or {};
    accessxi.delivery_box_packet_rows[box_name] = accessxi.delivery_box_packet_rows[box_name] or {};
    local visible_slot = work_slot + 1;
    local row_text = accessxi.delivery_box_packet_row_text(row);
    if (row == nil or row_text == '') then
        accessxi.delivery_box_packet_rows[box_name][visible_slot] = nil;
        return;
    end

    row.visible_slot = visible_slot;
    row.work_slot = work_slot;
    row.box = box_name;
    row.tick = tick();
    row.text = row_text;
    accessxi.delivery_box_packet_rows[box_name][visible_slot] = row;
    accessxi.delivery_box_packet_tick = tick();
end

function accessxi.capture_delivery_box_packet(e)
    if (e == nil or tonumber(e.id) ~= 0x04B) then
        return;
    end

    local data = e.data_modified or e.data or '';
    if (#data < 0x14) then
        return;
    end

    local command = accessxi.packet_byte(data, 0x04 + 1);
    local boxno = accessxi.delivery_box_pbx_i8(accessxi.packet_byte(data, 0x05 + 1));
    local post_work_no = accessxi.delivery_box_pbx_i8(accessxi.packet_byte(data, 0x06 + 1));
    local item_work_no = accessxi.delivery_box_pbx_i8(accessxi.packet_byte(data, 0x07 + 1));
    local item_stacks = accessxi.packet_i32(data, 0x08 + 1);
    local result = accessxi.delivery_box_pbx_i8(accessxi.packet_byte(data, 0x0C + 1));
    local res1 = accessxi.delivery_box_pbx_i8(accessxi.packet_byte(data, 0x0D + 1));
    local res2 = accessxi.delivery_box_pbx_i8(accessxi.packet_byte(data, 0x0E + 1));
    local res3 = accessxi.delivery_box_pbx_i8(accessxi.packet_byte(data, 0x0F + 1));

    if (command == 0x0E) then
        accessxi.delivery_box_packet_rows = accessxi.delivery_box_packet_rows or {};
        accessxi.delivery_box_packet_rows.incoming = {};
    elseif (command == 0x0D) then
        accessxi.delivery_box_packet_rows = accessxi.delivery_box_packet_rows or {};
        accessxi.delivery_box_packet_rows.outgoing = {};
    elseif (command == 0x0F) then
        accessxi.delivery_box_packet_rows = {};
    end

    local item_id = 0;
    local stack = 0;
    local sender = '';
    local stat = 0;
    local kind = 0;
    if (#data >= 0x58 and post_work_no >= 0 and post_work_no <= 7) then
        stat = accessxi.packet_u32(data, 0x10 + 1);
        sender = accessxi.delivery_box_pbx_ascii(data, 0x14 + 1, 16);
        item_id = accessxi.packet_u16(data, 0x30 + 1);
        kind = accessxi.packet_i32(data, 0x34 + 1);
        stack = accessxi.packet_u32(data, 0x38 + 1);
        local row = {
            command = command,
            item_id = item_id,
            item_work_no = item_work_no,
            item_stacks = item_stacks,
            result = result,
            res1 = res1,
            res2 = res2,
            res3 = res3,
            stat = stat,
            kind = kind,
            stack = stack,
            sender = sender,
            source = 'packet_in_04b',
        };
        local row_text = accessxi.delivery_box_packet_row_text(row);
        if (row_text ~= '') then
            accessxi.delivery_box_packet_set_row(boxno, post_work_no, row);
            local key = ('%d:%d:%d:%d:%d:%s'):fmt(command, boxno, post_work_no, item_id, stack, sender);
            if (key ~= tostring(accessxi.delivery_box_packet_capture_key or '')) then
                accessxi.delivery_box_packet_capture_key = key;
                log_state(('state mogpost packet-row command=%s box=%s workSlot=%d visible=%d itemId=%d item="%s" stack=%d sender="%s" text="%s"'):fmt(
                    accessxi.delivery_box_pbx_command_name(command),
                    accessxi.delivery_box_pbx_box_name(boxno),
                    post_work_no,
                    post_work_no + 1,
                    item_id,
                    accessxi.escape_probe_log_text(resource_item_info(item_id).name or (item_id == 65535 and 'gil' or '')),
                    stack,
                    accessxi.escape_probe_log_text(sender),
                    accessxi.escape_probe_log_text(row_text)));
            end
        elseif (command == 0x01 or command == 0x06 or command == 0x07 or command == 0x0A or command == 0x0B) then
            accessxi.delivery_box_packet_set_row(boxno, post_work_no, nil);
        end
    end
end

function accessxi.trace_delivery_box_packet(e, direction)
    if (e == nil or tick() > (tonumber(accessxi.delivery_box_packet_trace_until) or 0)) then
        return;
    end

    local id = tonumber(e.id) or 0;
    if (id ~= 0x04B and id ~= 0x04D) then
        return;
    end

    local data = e.data_modified or e.data or '';
    local command = #data >= 0x05 and accessxi.packet_byte(data, 0x04 + 1) or 0;
    local boxno = #data >= 0x06 and accessxi.delivery_box_pbx_i8(accessxi.packet_byte(data, 0x05 + 1)) or 0;
    local post_work_no = #data >= 0x07 and accessxi.delivery_box_pbx_i8(accessxi.packet_byte(data, 0x06 + 1)) or 0;
    local item_work_no = #data >= 0x08 and accessxi.delivery_box_pbx_i8(accessxi.packet_byte(data, 0x07 + 1)) or 0;
    local item_stacks = #data >= 0x0C and accessxi.packet_i32(data, 0x08 + 1) or 0;
    local result = #data >= 0x0D and accessxi.delivery_box_pbx_i8(accessxi.packet_byte(data, 0x0C + 1)) or 0;
    local res1 = #data >= 0x0E and accessxi.delivery_box_pbx_i8(accessxi.packet_byte(data, 0x0D + 1)) or 0;
    local res2 = #data >= 0x0F and accessxi.delivery_box_pbx_i8(accessxi.packet_byte(data, 0x0E + 1)) or 0;
    local res3 = #data >= 0x10 and accessxi.delivery_box_pbx_i8(accessxi.packet_byte(data, 0x0F + 1)) or 0;

    local item_id = 0;
    local stack = 0;
    local sender = '';
    local item_name = '';
    local stat = 0;
    local kind = 0;
    if (id == 0x04B and #data >= 0x58) then
        stat = accessxi.packet_u32(data, 0x10 + 1);
        sender = accessxi.delivery_box_pbx_ascii(data, 0x14 + 1, 16);
        item_id = accessxi.packet_u16(data, 0x30 + 1);
        kind = accessxi.packet_i32(data, 0x34 + 1);
        stack = accessxi.packet_u32(data, 0x38 + 1);
        item_name = resource_item_info(item_id).name or '';
        if (item_name == '' and item_id == 65535 and stack > 0) then
            item_name = 'gil';
        end
    end

    local key = ('%s:%03X:%d:%d:%d:%d:%d:%d:%d:%d:%d:%s'):fmt(
        tostring(direction or ''),
        id,
        command,
        boxno,
        post_work_no,
        item_work_no,
        item_stacks,
        result,
        res1,
        res2,
        res3,
        accessxi.packet_hex_limit(data, 0x58));
    if (key == tostring(accessxi.delivery_box_packet_trace_key or '')) then
        return;
    end

    local trace_count = tonumber(accessxi.delivery_box_packet_trace_count) or 0;
    local trace_limit = tonumber(accessxi.delivery_box_packet_trace_limit) or 80;
    if (trace_count >= trace_limit) then
        return;
    end

    accessxi.delivery_box_packet_trace_key = key;
    accessxi.delivery_box_packet_trace_count = trace_count + 1;
    log_line(('delivery packet trace dir=%s n=%d id=0x%03X len=%d command=%s box=%s post=%d visible=%d itemWork=%d stacks=%d result=%d res=(%d,%d,%d) stat=0x%08X kind=%d itemId=%d item="%s" stack=%d sender="%s" ascii="%s" hex="%s"'):fmt(
        tostring(direction or ''),
        trace_count + 1,
        id,
        #data,
        accessxi.delivery_box_pbx_command_name(command),
        accessxi.delivery_box_pbx_box_name(boxno),
        post_work_no,
        post_work_no >= 0 and (post_work_no + 1) or -1,
        item_work_no,
        item_stacks,
        result,
        res1,
        res2,
        res3,
        stat,
        kind,
        item_id,
        accessxi.escape_probe_log_text(item_name),
        stack,
        accessxi.escape_probe_log_text(sender),
        accessxi.escape_probe_log_text(accessxi.packet_ascii_preview(data, 96)),
        accessxi.packet_hex_limit(data, 0x58)));
end

function accessxi.enable_auction_packet_trace(reason)
    local now = tick();
    reason = tostring(reason or '');
    if ((tonumber(accessxi.auction_packet_trace_until) or 0) <= now
        or reason ~= tostring(accessxi.auction_packet_trace_reason or '')) then
        accessxi.auction_packet_trace_count = 0;
        accessxi.auction_packet_trace_key = '';
        accessxi.auction_packet_trace_fields_logged = false;
        accessxi.auction_packet_trace_variant_count = 0;
    end

    accessxi.auction_packet_trace_reason = reason;
    accessxi.auction_packet_trace_until = math.max(tonumber(accessxi.auction_packet_trace_until) or 0, now + 15000);
    accessxi.auction_packet_trace_limit = math.max(tonumber(accessxi.auction_packet_trace_limit) or 0, 80);
    accessxi.auction_packet_trace_variant_limit = math.max(tonumber(accessxi.auction_packet_trace_variant_limit) or 0, 32);
end

function accessxi.trace_auction_packet(e, direction)
    if (e == nil or tick() > (tonumber(accessxi.auction_packet_trace_until) or 0)) then
        return;
    end

    if (not accessxi.auction_packet_trace_fields_logged) then
        accessxi.auction_packet_trace_fields_logged = true;
        local fields = T{};
        pcall(function ()
            for k, v in pairs(e) do
                fields:append(('%s:%s'):fmt(tostring(k), type(v)));
            end
        end);
        log_line(('auction packet event fields "%s"'):fmt(accessxi.escape_probe_log_text(fields:concat(', '))));
    end

    local variants = T{};
    local seen_variants = {};
    local function add_variant(name, value)
        if (type(value) ~= 'string' or #value == 0) then
            return;
        end
        local key = ('%d:%s'):fmt(#value, accessxi.packet_hex_limit(value, 64));
        if (seen_variants[key] == true) then
            return;
        end
        seen_variants[key] = true;
        variants:append(T{ name = name, data = value });
    end

    add_variant('data_modified', e.data_modified);
    add_variant('data', e.data);
    add_variant('data_modified_raw', accessxi.packet_event_string(e, 'data_modified', 'size'));
    add_variant('data_raw', accessxi.packet_event_string(e, 'data', 'size'));
    add_variant('data_chunk', accessxi.packet_event_string(e, 'data_chunk', 'size_chunk'));
    add_variant('dataChunk', accessxi.packet_event_string(e, 'dataChunk', 'sizeChunk'));
    add_variant('chunk', accessxi.packet_event_string(e, 'chunk', 'size'));
    add_variant('packet_chunk', accessxi.packet_event_string(e, 'packet_chunk', 'size_chunk'));

    if (variants:len() == 0) then
        return;
    end

    local data = variants[1].data or '';
    local variant_name = tostring(variants[1].name or '');
    local id = tonumber(e.id) or 0;
    if (id == 0x015) then
        return;
    end
    local ah_search_list_packet = (#data >= 0x18 and data:byte(0x0B + 1) == 0x95);
    if ((id == 0x00D or id == 0x00E) and not ah_search_list_packet) then
        return;
    end

    local trace_count = tonumber(accessxi.auction_packet_trace_count) or 0;
    local trace_limit = tonumber(accessxi.auction_packet_trace_limit) or 80;
    if (trace_count >= trace_limit) then
        return;
    end

    local w04 = #data >= 0x06 and accessxi.packet_u16(data, 0x04 + 1) or 0;
    local w06 = #data >= 0x08 and accessxi.packet_u16(data, 0x06 + 1) or 0;
    local w08 = #data >= 0x0A and accessxi.packet_u16(data, 0x08 + 1) or 0;
    local w0A = #data >= 0x0C and accessxi.packet_u16(data, 0x0A + 1) or 0;
    local ascii_preview = accessxi.packet_ascii_preview(data, 128);
    local ascii_run = ascii_preview:match('[%w][%w][%w][%w][%w]') ~= nil;
    local candidate = (id ~= 0x00D and id ~= 0x00E) or ascii_run;
    if (not candidate and trace_count >= 16) then
        return;
    end

    local hex_key = accessxi.packet_hex_limit(data, candidate and 96 or 24);
    local key = ('%s:%03X:%s:%d:%04X:%04X:%04X:%04X:%s'):fmt(
        tostring(direction or ''),
        id,
        variant_name,
        #data,
        w04,
        w06,
        w08,
        w0A,
        hex_key);
    if (key == tostring(accessxi.auction_packet_trace_key or '')) then
        return;
    end

    accessxi.auction_packet_trace_key = key;
    accessxi.auction_packet_trace_count = trace_count + 1;

    local obj = get_current_menu_object_ptr();
    local cursor4c = obj ~= 0 and read_current_native_menu_index(0x4C) or -1;
    local menu_name = tostring(accessxi.current_menu_name or '');
    if (menu_name == '') then
        menu_name = tostring(get_menu_name() or '');
    end

    log_line(('auction packet trace dir=%s n=%d id=0x%03X variant=%s len=%d candidate=%s reason="%s" menu="%s" cursor4c=%d w04=0x%04X w06=0x%04X w08=0x%04X w0A=0x%04X ascii="%s" hex="%s"'):fmt(
        tostring(direction or ''),
        trace_count + 1,
        id,
        accessxi.escape_probe_log_text(variant_name),
        #data,
        tostring(candidate),
        accessxi.escape_probe_log_text(tostring(accessxi.auction_packet_trace_reason or '')),
        accessxi.escape_probe_log_text(menu_name),
        cursor4c,
        w04,
        w06,
        w08,
        w0A,
        accessxi.escape_probe_log_text(ascii_preview),
        accessxi.packet_hex_limit(data, 160)));

    local variant_count = tonumber(accessxi.auction_packet_trace_variant_count) or 0;
    local variant_limit = tonumber(accessxi.auction_packet_trace_variant_limit) or 32;
    for idx, variant in ipairs(variants) do
        if (idx > 1 and variant_count < variant_limit) then
            variant_count = variant_count + 1;
            accessxi.auction_packet_trace_variant_count = variant_count;
            log_line(('auction packet variant dir=%s n=%d id=0x%03X variant=%s len=%d ascii="%s" hex="%s"'):fmt(
                tostring(direction or ''),
                variant_count,
                id,
                accessxi.escape_probe_log_text(tostring(variant.name or '')),
                #(variant.data or ''),
                accessxi.escape_probe_log_text(accessxi.packet_ascii_preview(variant.data or '', 96)),
                accessxi.packet_hex_limit(variant.data or '', 160)));
        end
    end
end

function accessxi.delivery_box_slot_label(slot)
    slot = tonumber(slot) or 0;
    if (slot >= 1 and slot <= (tonumber(accessxi.delivery_box_menu_data.slot_count) or 8)) then
        return ('Slot %d'):fmt(slot);
    end
    return '';
end

function accessxi.delivery_box_grid_button_label(cursor)
    cursor = tonumber(cursor) or 0;
    return tostring((accessxi.delivery_box_menu_data.grid_buttons or T{})[cursor] or '');
end

function accessxi.delivery_box_receive_slot_speech(menu_name, title, selected, count, entry)
    menu_name = tostring(menu_name or '');
    title = tostring(title or 'Delivery Box');
    selected = tonumber(selected) or 0;
    count = tonumber(count) or 0;
    entry = tonumber(entry) or 0;

    if (not accessxi.is_mogpost_receive_menu_name(menu_name)) then
        return nil;
    end

    if (selected >= 1 and selected <= 8 and accessxi.delivery_box_slot_text ~= nil) then
        local cached = accessxi.delivery_box_slot_text[selected];
        if (cached ~= nil and cached.text ~= nil and cached.text ~= '') then
            accessxi.current_speech_key = ('mogpost-receive-slot-chat:%s:%d:%s'):fmt(
                menu_name,
                selected,
                tostring(cached.text or ''));
            log_state(('state mogpost receive-slot-chat menu="%s" title="%s" select=%d count=%d entry=0x%08X text="%s" age=%d'):fmt(
                menu_name,
                title,
                selected,
                count,
                entry,
                accessxi.escape_probe_log_text(cached.text),
                math.max(0, tick() - (tonumber(cached.tick) or 0))));
            return ('%s. %s'):fmt(title, accessxi.sentence_fragment(cached.text));
        end
    end

    if (selected >= 1 and selected <= 8 and accessxi.delivery_box_packet_rows ~= nil) then
        local incoming = accessxi.delivery_box_packet_rows.incoming or {};
        local row = incoming[selected];
        local text = row ~= nil and tostring(row.text or '') or '';
        if (text ~= '') then
            accessxi.current_speech_key = ('mogpost-receive-packet:%s:%d:%d:%d:%s'):fmt(
                menu_name,
                selected,
                tonumber(row.item_id) or 0,
                tonumber(row.stack) or 0,
                text);
            log_state(('state mogpost receive-slot-packet menu="%s" title="%s" select=%d count=%d entry=0x%08X itemId=%d workSlot=%d text="%s" age=%d'):fmt(
                menu_name,
                title,
                selected,
                count,
                entry,
                tonumber(row.item_id) or 0,
                tonumber(row.work_slot) or -1,
                accessxi.escape_probe_log_text(text),
                math.max(0, tick() - (tonumber(row.tick) or 0))));
            return ('%s. %s. %s'):fmt(title, accessxi.delivery_box_slot_label(selected), accessxi.sentence_fragment(text));
        end
    end

    if (selected >= 1 and selected <= 8) then
        accessxi.current_speech_key = ('mogpost-receive-slot:%s:%d'):fmt(menu_name, selected);
        log_state(('state mogpost receive-slot-empty menu="%s" title="%s" select=%d count=%d entry=0x%08X'):fmt(
            menu_name,
            title,
            selected,
            count,
            entry));
        return ('%s. %s.'):fmt(title, accessxi.delivery_box_slot_label(selected));
    end

    local button = accessxi.delivery_box_grid_button_label(selected);
    if (button ~= '') then
        accessxi.current_speech_key = ('mogpost-receive-button:%s:%d:%s'):fmt(menu_name, selected, button);
        log_state(('state mogpost receive-button menu="%s" title="%s" select=%d count=%d entry=0x%08X label="%s"'):fmt(
            menu_name,
            title,
            selected,
            count,
            entry,
            accessxi.escape_probe_log_text(button)));
        return ('%s. %s.'):fmt(title, button);
    end

    return nil;
end

function accessxi.delivery_box_send_slot_from_selected(selected, count)
    selected = tonumber(selected) or 0;
    count = tonumber(count) or 0;
    if (selected >= 1 and selected <= 8) then
        return selected;
    end
    if (selected >= 0 and selected <= 7 and count >= 8) then
        return selected + 1;
    end
    return 0;
end

function accessxi.delivery_box_send_slot_speech(menu_name, title, selected, count, entry)
    menu_name = tostring(menu_name or '');
    title = tostring(title or 'Delivery Box');
    selected = tonumber(selected) or 0;
    count = tonumber(count) or 0;
    entry = tonumber(entry) or 0;

    if (not accessxi.is_mogpost_send_menu_name(menu_name)) then
        return nil;
    end

    local select30 = read_current_native_menu_index(0x30);
    local select34 = read_current_native_menu_index(0x34);
    local select4c = read_current_native_menu_index(0x4C);
    local cursor = select4c > 0 and select4c or selected;
    local slot = accessxi.delivery_box_send_slot_from_selected(cursor, count);
    log_state(('state mogpost send-grid menu="%s" title="%s" select=%d count=%d slot=%d entry=0x%08X sel30=%d sel34=%d sel4c=%d'):fmt(
        menu_name,
        title,
        cursor,
        count,
        slot,
        entry,
        select30,
        select34,
        select4c));

    local button = accessxi.delivery_box_grid_button_label(cursor);
    if (button ~= '') then
        accessxi.current_speech_key = ('mogpost-send-button:%s:%d:%s'):fmt(menu_name, cursor, button);
        log_state(('state mogpost send-button menu="%s" title="%s" select=%d count=%d entry=0x%08X label="%s" sel30=%d sel34=%d sel4c=%d'):fmt(
            menu_name,
            title,
            cursor,
            count,
            entry,
            accessxi.escape_probe_log_text(button),
            select30,
            select34,
            select4c));
        return ('%s. %s.'):fmt(title, button);
    end

    if (slot < 1 or slot > 8) then
        return nil;
    end

    if (accessxi.delivery_box_packet_rows ~= nil) then
        local outgoing = accessxi.delivery_box_packet_rows.outgoing or {};
        local row = outgoing[slot];
        local text = row ~= nil and tostring(row.text or '') or '';
        if (text ~= '') then
            accessxi.current_speech_key = ('mogpost-send-packet:%s:%d:%d:%d:%s'):fmt(
                menu_name,
                slot,
                tonumber(row.item_id) or 0,
                tonumber(row.stack) or 0,
                text);
            log_state(('state mogpost send-slot-packet menu="%s" title="%s" select=%d count=%d slot=%d entry=0x%08X itemId=%d workSlot=%d text="%s" age=%d'):fmt(
                menu_name,
                title,
                cursor,
                count,
                slot,
                entry,
                tonumber(row.item_id) or 0,
                tonumber(row.work_slot) or -1,
                accessxi.escape_probe_log_text(text),
                math.max(0, tick() - (tonumber(row.tick) or 0))));
            return ('%s. %s. %s'):fmt(title, accessxi.delivery_box_slot_label(slot), accessxi.sentence_fragment(text));
        end
    end

    accessxi.current_speech_key = ('mogpost-send-slot:%s:%d:%d'):fmt(menu_name, slot, cursor);
    return ('%s. %s.'):fmt(title, accessxi.delivery_box_slot_label(slot));
end

local function is_storage_bank_container(container)
    return container ~= nil and container >= 1 and container <= 16;
end

local function storage_bank_counts(container)
    local inv = AshitaCore:GetMemoryManager():GetInventory();
    if (inv == nil or not is_storage_bank_container(container)) then
        return 0, 0;
    end

    local count = tonumber(safe_call(function () return inv:GetContainerCount(container); end, 0)) or 0;
    local max_count = tonumber(safe_call(function () return inv:GetContainerCountMax(container); end, 0)) or 0;
    return count, max_count;
end

local function remember_storage_bank_context(container)
    if (not is_storage_bank_container(container)) then
        return;
    end

    accessxi.storage_bank_context_until = tick() + 6000;
    accessxi.storage_bank_container = container;
    accessxi.storage_bank_container_name = inventory_container_names[container] or ('Container %d'):fmt(container);
end

local function set_storage_bank_context(container)
    remember_storage_bank_context(container);
    if (is_storage_bank_container(container)) then
        accessxi.inventory_context = 'storage_bank';
    end
end

accessxi.view_house_container_order = T{
    1,  -- Safe
    2,  -- Storage
    4,  -- Locker
    5,  -- Satchel
    6,  -- Sack
    7,  -- Case
    8,  -- Wardrobe
    9,  -- Safe 2
    10, -- Wardrobe 2
    11, -- Wardrobe 3
    12, -- Wardrobe 4
    13, -- Wardrobe 5
    14, -- Wardrobe 6
    15, -- Wardrobe 7
    16, -- Wardrobe 8
};

function accessxi.view_house_visible_containers(native_count)
    local inv = AshitaCore:GetMemoryManager():GetInventory();
    local choices = T{};
    native_count = tonumber(native_count) or 0;
    if (inv == nil) then
        return choices;
    end

    for _, container in ipairs(accessxi.view_house_container_order or T{}) do
        local max_count = tonumber(safe_call(function () return inv:GetContainerCountMax(container); end, 0)) or 0;
        if (max_count > 0) then
            choices:append(container);
            if (native_count > 0 and #choices >= native_count) then
                break;
            end
        end
    end

    return choices;
end

function accessxi.view_house_help_is_storage_text(help)
    help = tostring(help or '');
    if (help == '') then
        return false;
    end
    if (not (help:find('View content of ', 1, true) == 1 or help:find('Remove or store items in your ', 1, true) == 1)) then
        return false;
    end

    return help:find('Mog Safe', 1, true) ~= nil
        or help:find('Storage', 1, true) ~= nil
        or help:find('Mog Locker', 1, true) ~= nil
        or help:find('Mog Satchel', 1, true) ~= nil
        or help:find('Mog Sack', 1, true) ~= nil
        or help:find('Mog Case', 1, true) ~= nil
        or help:find('Mog Wardrobe', 1, true) ~= nil;
end

function accessxi.view_house_native_help_text(entry)
    entry = tonumber(entry) or 0;
    if (not accessxi.is_probe_pointer(entry)) then
        return '', 0;
    end

    local help_ptr = tonumber(read_u32(entry + 0x40)) or 0;
    if (not accessxi.is_probe_pointer(help_ptr)) then
        return '', help_ptr;
    end

    local help = accessxi.plain_native_menu_help(read_probe_string(help_ptr, 260));
    if (not accessxi.view_house_help_is_storage_text(help)) then
        return '', help_ptr;
    end

    return help, help_ptr;
end

function accessxi.view_house_label_from_native_help(help)
    help = tostring(help or '');
    local label = help:match('^View content of ([^%.]+)%.') or help:match('^Remove or store items in your ([^%.]+)%.') or '';
    label = accessxi.plain_native_menu_label(label);
    if (label == '') then
        return '';
    end

    if (label:eq('second Mog Wardrobe', true)) then
        return 'Mog Wardrobe 2';
    elseif (label:eq('third Mog Wardrobe', true)) then
        return 'Mog Wardrobe 3';
    elseif (label:eq('fourth Mog Wardrobe', true)) then
        return 'Mog Wardrobe 4';
    elseif (label:eq('fifth Mog Wardrobe', true)) then
        return 'Mog Wardrobe 5';
    elseif (label:eq('sixth Mog Wardrobe', true)) then
        return 'Mog Wardrobe 6';
    elseif (label:eq('seventh Mog Wardrobe', true)) then
        return 'Mog Wardrobe 7';
    elseif (label:eq('eighth Mog Wardrobe', true)) then
        return 'Mog Wardrobe 8';
    end

    return label;
end

function accessxi.view_house_container_from_native_label(label)
    label = accessxi.plain_native_menu_label(label or '');
    if (label:eq('Mog Safe', true)) then
        return 1;
    elseif (label:eq('Storage', true)) then
        return 2;
    elseif (label:eq('Mog Locker', true)) then
        return 4;
    elseif (label:eq('Mog Satchel', true)) then
        return 5;
    elseif (label:eq('Mog Sack', true)) then
        return 6;
    elseif (label:eq('Mog Case', true)) then
        return 7;
    elseif (label:eq('Mog Wardrobe', true)) then
        return 8;
    elseif (label:eq('Mog Safe 2', true)) then
        return 9;
    end

    local wardrobe = tonumber(label:match('^Mog Wardrobe (%d+)$')) or 0;
    if (wardrobe >= 2 and wardrobe <= 8) then
        return wardrobe + 8;
    end

    return -1;
end

function accessxi.bazaar_help_is_native_text(help)
    help = accessxi.plain_native_menu_help(help or '');
    if (help == '') then
        return false;
    end

    return help:eq('Select merchandise to put on sale and set its unit price.', true)
        or help:eq('Edit the message in your comment box.', true);
end

function accessxi.bazaar_menu_speech(menu_name, title, obj, selected, count, page, raw, child, entry)
    menu_name = tostring(menu_name or '');
    if (not menu_name:eq('menu    bazaar', true)) then
        return nil;
    end

    entry = tonumber(entry) or 0;
    if (not accessxi.is_probe_pointer(entry)) then
        return nil;
    end

    local help_ptr = tonumber(read_u32(entry + 0x40)) or 0;
    if (not accessxi.is_probe_pointer(help_ptr)) then
        return nil;
    end

    local help = accessxi.plain_native_menu_help(read_probe_string(help_ptr, 260));
    if (not accessxi.bazaar_help_is_native_text(help)) then
        log_state(('state bazaar native-missing menu="%s" title="%s" select=%d count=%d entry=0x%08X helpPtr=0x%08X help="%s"'):fmt(
            menu_name,
            tostring(title or 'Set Bazaar'),
            tonumber(selected) or 0,
            tonumber(count) or 0,
            entry,
            help_ptr,
            accessxi.escape_probe_log_text(help)));
        return nil;
    end

    if (help:eq('Select merchandise to put on sale and set its unit price.', true)) then
        accessxi.bazaar_item_list_context_until = tick() + 30000;
    end

    accessxi.last_native_menu_name = menu_name;
    accessxi.last_native_menu_label = help;
    accessxi.last_native_menu_selected = tonumber(selected) or 0;
    accessxi.last_native_menu_tick = tick();
    accessxi.current_speech_key = ('bazaar-native-help:%d:0x%08X:0x%08X:%s'):fmt(
        tonumber(selected) or 0,
        entry,
        help_ptr,
        help);
    log_state(('state bazaar native-help menu="%s" title="%s" select=%d count=%d page=%d raw=0x%08X child=0x%08X entry=0x%08X helpPtr=0x%08X help="%s" source="entry+40"'):fmt(
        menu_name,
        tostring(title or 'Set Bazaar'),
        tonumber(selected) or 0,
        tonumber(count) or 0,
        tonumber(page) or 0,
        tonumber(raw) or 0,
        tonumber(child) or 0,
        entry,
        help_ptr,
        accessxi.escape_probe_log_text(help)));
    return ('%s. %s'):fmt(tostring(title or 'Set Bazaar'), accessxi.sentence_fragment(help));
end

function accessxi.enable_bazaar_probe(reason)
    accessxi.bazaar_probe_until = tick() + 12000;
    accessxi.bazaar_probe_last_tick = 0;
    accessxi.bazaar_probe_last_key = '';
    log_line(('bazaar probe enabled reason="%s"'):fmt(accessxi.escape_probe_log_text(reason or '')));
end

function accessxi.log_bazaar_menu_probe(menu_name, title, obj, selected, count, page, raw, child, entry, reason)
    if (tick() > (tonumber(accessxi.bazaar_probe_until) or 0)) then
        return 0;
    end

    local now = tick();
    if ((now - (tonumber(accessxi.bazaar_probe_last_tick) or 0)) < 140) then
        return 0;
    end

    menu_name = tostring(menu_name or '');
    if (not menu_name:eq('menu    bazaar', true)) then
        return 0;
    end

    obj = tonumber(obj) or 0;
    child = tonumber(child) or 0;
    entry = tonumber(entry) or 0;
    selected = tonumber(selected) or 0;
    count = tonumber(count) or 0;
    page = tonumber(page) or 0;
    raw = tonumber(raw) or 0;

    local indices = T{};
    for _, off in ipairs(T{ 0x24, 0x28, 0x2C, 0x30, 0x34, 0x4C, 0x50, 0x58, 0x5C, 0x60, 0x64, 0x68 }) do
        indices:append(('%02X=%d'):fmt(off, tonumber(read_current_native_menu_index(off)) or 0));
    end

    local key = ('%s:%d:%d:%d:0x%08X:0x%08X:0x%08X:%s'):fmt(
        menu_name,
        selected,
        count,
        page,
        raw,
        child,
        entry,
        indices:concat(','));
    if (key == tostring(accessxi.bazaar_probe_last_key or '')) then
        return 0;
    end
    accessxi.bazaar_probe_last_key = key;
    accessxi.bazaar_probe_last_tick = now;
    accessxi.bazaar_probe_sequence = (tonumber(accessxi.bazaar_probe_sequence) or 0) + 1;
    local seq = accessxi.bazaar_probe_sequence;

    log_line(('bazaarprobe seq=%d begin reason="%s" menu="%s" title="%s" selected=%d count=%d page=%d raw=0x%08X obj=0x%08X child=0x%08X entry=0x%08X indices="%s" target="%s"'):fmt(
        seq,
        accessxi.escape_probe_log_text(reason or ''),
        accessxi.escape_probe_log_text(menu_name),
        accessxi.escape_probe_log_text(tostring(title or '')),
        selected,
        count,
        page,
        raw,
        obj,
        child,
        entry,
        accessxi.escape_probe_log_text(indices:concat(',')),
        accessxi.escape_probe_log_text(current_target_snapshot())));

    if (accessxi.is_probe_pointer(obj)) then
        log_line(('bazaarprobe seq=%d obj d00=%s d80=%s'):fmt(seq, accessxi.format_probe_dwords(obj, 0x00, 24), accessxi.format_probe_dwords(obj, 0x80, 24)));
        accessxi.log_probe_short_text_runs(seq, 'bazaar.obj', obj, 0x360, 2, 24);
        accessxi.log_probe_pointer_text_targets(seq, 'bazaar.obj', obj, 0x00, 0x1FC, 32);
    end
    if (accessxi.is_probe_pointer(child)) then
        log_line(('bazaarprobe seq=%d child d00=%s d80=%s'):fmt(seq, accessxi.format_probe_dwords(child, 0x00, 24), accessxi.format_probe_dwords(child, 0x80, 24)));
        accessxi.log_probe_short_text_runs(seq, 'bazaar.child', child, 0x240, 2, 18);
        accessxi.log_probe_pointer_text_targets(seq, 'bazaar.child', child, 0x00, 0x13C, 20);
    end
    if (accessxi.is_probe_pointer(entry)) then
        log_line(('bazaarprobe seq=%d entry d00=%s d40=%s'):fmt(seq, accessxi.format_probe_dwords(entry, 0x00, 24), accessxi.format_probe_dwords(entry, 0x40, 24)));
        accessxi.log_probe_short_text_runs(seq, 'bazaar.entry', entry, 0x240, 2, 18);
        accessxi.log_probe_pointer_text_targets(seq, 'bazaar.entry', entry, 0x00, 0x13C, 20);
    end

    local target = AshitaCore:GetMemoryManager():GetTarget();
    if (target ~= nil) then
        local shape_count = 0;
        for i = 0, 31 do
            if (shape_count >= 8) then
                break;
            end
            local shape = tonumber(safe_call(function () return target:GetWindowAnkShape(i); end, 0)) or 0;
            if (accessxi.is_probe_pointer(shape)) then
                shape_count = shape_count + 1;
                log_line(('bazaarprobe seq=%d shape index=%d ptr=0x%08X dwords=%s strings="%s"'):fmt(
                    seq,
                    i,
                    shape,
                    accessxi.format_probe_dwords(shape, 0, 24),
                    accessxi.escape_probe_log_text(accessxi.party_label_probe_text_summary(shape, 0x200))));
                accessxi.log_probe_short_text_runs(seq, ('bazaar.shape%d'):fmt(i), shape, 0x240, 2, 18);
                accessxi.log_probe_pointer_text_targets(seq, ('bazaar.shape%d'):fmt(i), shape, 0x00, 0x13C, 14);
            end
        end
    end

    log_line(('bazaarprobe seq=%d end'):fmt(seq));
    return seq;
end

function accessxi.enable_shopsell_probe(reason)
    accessxi.shopsell_probe_until = tick() + 12000;
    accessxi.shopsell_probe_last_tick = 0;
    accessxi.shopsell_probe_last_key = '';
    log_line(('shopsell probe enabled reason="%s"'):fmt(accessxi.escape_probe_log_text(reason or '')));
end

