    if (accessxi.is_probe_pointer(obj)) then
        log_line(('shopsellprobe seq=%d obj d00=%s d80=%s'):fmt(seq, accessxi.format_probe_dwords(obj, 0x00, 24), accessxi.format_probe_dwords(obj, 0x80, 24)));
        accessxi.log_probe_short_text_runs(seq, 'shopsell.obj', obj, 0x360, 2, 24);
        accessxi.log_probe_pointer_text_targets(seq, 'shopsell.obj', obj, 0x00, 0x1FC, 32);
    end
    if (accessxi.is_probe_pointer(child)) then
        log_line(('shopsellprobe seq=%d child d00=%s d80=%s'):fmt(seq, accessxi.format_probe_dwords(child, 0x00, 24), accessxi.format_probe_dwords(child, 0x80, 24)));
        accessxi.log_probe_short_text_runs(seq, 'shopsell.child', child, 0x240, 2, 18);
        accessxi.log_probe_pointer_text_targets(seq, 'shopsell.child', child, 0x00, 0x13C, 20);
    end
    if (accessxi.is_probe_pointer(entry)) then
        log_line(('shopsellprobe seq=%d entry d00=%s d40=%s'):fmt(seq, accessxi.format_probe_dwords(entry, 0x00, 24), accessxi.format_probe_dwords(entry, 0x40, 24)));
        accessxi.log_probe_short_text_runs(seq, 'shopsell.entry', entry, 0x240, 2, 18);
        accessxi.log_probe_pointer_text_targets(seq, 'shopsell.entry', entry, 0x00, 0x13C, 20);
    end

    local target = AshitaCore:GetMemoryManager():GetTarget();
    if (target ~= nil) then
        local shape_count = 0;
        for i = 0, 31 do
            if (shape_count >= 8) then
                break;
            end
            local shape = tonumber(safe_call(function () return target:GetWindowAnkShape(i); end, 0)) or 0;
            if (accessxi.is_probe_pointer(shape)) then
                shape_count = shape_count + 1;
                log_line(('shopsellprobe seq=%d shape index=%d ptr=0x%08X dwords=%s strings="%s"'):fmt(
                    seq,
                    i,
                    shape,
                    accessxi.format_probe_dwords(shape, 0, 24),
                    accessxi.escape_probe_log_text(accessxi.party_label_probe_text_summary(shape, 0x200))));
                accessxi.log_probe_short_text_runs(seq, ('shopsell.shape%d'):fmt(i), shape, 0x240, 2, 18);
                accessxi.log_probe_pointer_text_targets(seq, ('shopsell.shape%d'):fmt(i), shape, 0x00, 0x13C, 14);
            end
        end
    end

    log_line(('shopsellprobe seq=%d end'):fmt(seq));
    return seq;
