function accessxi.shopsell_menu_speech(menu_name, title, obj, selected, count, page, raw, child, entry)
    menu_name = tostring(menu_name or '');
    if (not menu_name:eq('menu    shopsell', true)) then
        return nil;
    end

    obj = tonumber(obj) or 0;
    entry = tonumber(entry) or 0;
    if (not accessxi.is_probe_pointer(entry)) then
        return nil;
    end

    local visible_selected = read_current_native_menu_index(0x4C);
    if (visible_selected < 1 or visible_selected > 2) then
        visible_selected = tonumber(selected) or 0;
    end
    if (visible_selected < 1 or visible_selected > 2) then
        return nil;
    end

    local first_entry = 0;
    local text_table = 0;
    local sell_text = '';
    local cancel_text = '';
    local table_offset = 0;
    for i = -8, 8 do
        local candidate_entry = entry + (i * 0x68);
        if (accessxi.is_probe_pointer(candidate_entry)) then
            local candidate_table = tonumber(read_u32(candidate_entry + 0x40)) or 0;
            if (accessxi.is_probe_pointer(candidate_table)) then
                local candidate_sell = accessxi.plain_native_menu_help(read_probe_string(candidate_table, 120));
                local candidate_cancel = accessxi.plain_native_menu_help(read_probe_string(candidate_table + 0x40, 120));
                if (candidate_sell:eq('Sell this merchandise?', true) and candidate_cancel:eq('Cancel sale.', true)) then
                    first_entry = candidate_entry;
                    text_table = candidate_table;
                    sell_text = candidate_sell;
                    cancel_text = candidate_cancel;
                    table_offset = i;
                    break;
                end
            end
        end
    end
    if (not sell_text:eq('Sell this merchandise?', true) or not cancel_text:eq('Cancel sale.', true)) then
        log_state(('state shopsell native-missing menu="%s" title="%s" select=%d count=%d entry=0x%08X firstEntry=0x%08X textTable=0x%08X sell="%s" cancel="%s"'):fmt(
            menu_name,
            tostring(title or 'Set Bazaar'),
            visible_selected,
            tonumber(count) or 0,
            entry,
            first_entry,
            text_table,
            accessxi.escape_probe_log_text(sell_text),
            accessxi.escape_probe_log_text(cancel_text)));
        return nil;
    end

    local text = visible_selected == 1 and sell_text or cancel_text;
    accessxi.last_native_menu_name = menu_name;
    accessxi.last_native_menu_label = text;
    accessxi.last_native_menu_selected = visible_selected;
    accessxi.last_native_menu_tick = tick();
    accessxi.current_speech_key = ('shopsell-native:%d:0x%08X:0x%08X:%s'):fmt(
        visible_selected,
        first_entry,
        text_table,
        text);
    log_state(('state shopsell native menu="%s" title="%s" select=%d count=%d page=%d raw=0x%08X child=0x%08X entry=0x%08X firstEntry=0x%08X textTable=0x%08X tableOffset=%d text="%s" source="nearby-entry+40"'):fmt(
        menu_name,
        tostring(title or 'Set Bazaar'),
        visible_selected,
        tonumber(count) or 0,
        tonumber(page) or 0,
        tonumber(raw) or 0,
        tonumber(child) or 0,
        entry,
        first_entry,
        text_table,
        table_offset,
        accessxi.escape_probe_log_text(text)));
    return ('%s. %s'):fmt(tostring(title or 'Set Bazaar'), accessxi.sentence_fragment(text));
end

function accessxi.scan_native_command_text_table(entry, visible_selected, max_rows)
    entry = tonumber(entry) or 0;
    visible_selected = tonumber(visible_selected) or 0;
    max_rows = math.max(visible_selected, tonumber(max_rows) or visible_selected);
    local scanned = T{};

    if (visible_selected < 1 or max_rows < 1 or not accessxi.is_probe_pointer(entry)) then
        return '', 0, 0, 0, scanned;
    end

    for i = -8, 8 do
        local candidate_entry = entry + (i * 0x68);
        if (accessxi.is_probe_pointer(candidate_entry)) then
            local candidate_table = tonumber(read_u32(candidate_entry + 0x40)) or 0;
            if (accessxi.is_probe_pointer(candidate_table)) then
                local rows = T{};
                local labels = T{};
                local valid = true;
                for row = 1, max_rows do
                    local label = accessxi.plain_native_menu_label(read_probe_string(candidate_table + ((row - 1) * 0x40), 120));
                    if (label == '') then
                        if (row <= visible_selected) then
                            valid = false;
                        end
                        break;
                    end
                    if ((not accessxi.native_query_label_looks_real(label))
                        or accessxi.survival_guide_native_label_is_polluted(label)) then
                        valid = false;
                        break;
                    end
                    rows[row] = label;
                    labels:append(('%d:%s'):fmt(row, label));
                end

                if (labels:len() > 0) then
                    scanned:append(('%d:0x%08X:%s'):fmt(i, candidate_table, accessxi.escape_probe_log_text(labels:concat('|'))));
                end

                if (valid and tostring(rows[visible_selected] or '') ~= '') then
                    return tostring(rows[visible_selected] or ''), candidate_entry, candidate_table, i, scanned;
                end
            end
        end
    end

    return '', 0, 0, 0, scanned;
end

function accessxi.load_shopmain_command_rows()
    if (type(accessxi.shopmain_command_rows) == 'table') then
        return accessxi.shopmain_command_rows;
    end
    if (accessxi.shopmain_command_rows_tried == true) then
        return nil;
    end
    accessxi.shopmain_command_rows_tried = true;

    local rows = T{};
    local sources = T{};
    local path = accessxi.dat_index_path();
    local f = io.open(path, 'rb');
    if (f ~= nil) then
        for line in f:lines() do
            local index, text = line:match('^%d+\tDmsgTable\tROM\\165\\75%.DAT\t(%d+)\t(.*)$');
            if (index ~= nil) then
                local row = tonumber(index) == 47 and 1 or (tonumber(index) == 48 and 2 or 0);
                if (row > 0) then
                    local cleaned = accessxi.plain_native_menu_help(tostring(text or ''):gsub('\r', ''));
                    if (cleaned ~= '') then
                        rows[row] = cleaned;
                        sources[row] = ('ROM\\165\\75.DAT:%d'):fmt(tonumber(index) or 0);
                    end
                end
            end
        end
        f:close();
    end

    if (rows[1] == nil or rows[2] == nil) then
        log_line(('shopmain command resource unavailable path="%s" row1="%s" row2="%s"'):fmt(
            path,
            accessxi.escape_probe_log_text(rows[1] or ''),
            accessxi.escape_probe_log_text(rows[2] or '')));
        return nil;
    end

    rows.sources = sources;
    accessxi.shopmain_command_rows = rows;
    log_line(('loaded shopmain command resource path="%s" row1="%s" row2="%s"'):fmt(
        path,
        accessxi.escape_probe_log_text(rows[1] or ''),
        accessxi.escape_probe_log_text(rows[2] or '')));
    return rows;
end

