function accessxi.load_equipment_set_slot_picker_command_rows()
    if (type(accessxi.equipment_set_slot_picker_command_rows) == 'table') then
        return accessxi.equipment_set_slot_picker_command_rows;
    end
    if (accessxi.equipment_set_slot_picker_command_rows_tried == true) then
        return nil;
    end
    accessxi.equipment_set_slot_picker_command_rows_tried = true;

    local rows = T{};
    local sources = T{};
    local path = accessxi.dat_index_path();
    local f = io.open(path, 'rb');
    if (f ~= nil) then
        for line in f:lines() do
            local index, text = line:match('^%d+\tDmsgTable\tROM\\165\\76%.DAT\t(%d+)\t(.*)$');
            if (index ~= nil and tonumber(index) == 169) then
                local cleaned = accessxi.plain_native_menu_label(tostring(text or ''):gsub('\r', ''));
                if (cleaned ~= '') then
                    rows[1] = cleaned;
                    sources[1] = 'ROM\\165\\76.DAT:169';
                end
            else
                index, text = line:match('^%d+\tDmsgTable\tROM\\165\\72%.DAT\t(%d+)\t(.*)$');
                if (index ~= nil) then
                    local row = tonumber(index) == 275 and 2 or (tonumber(index) == 276 and 3 or 0);
                    if (row > 0) then
                        local cleaned = accessxi.plain_native_menu_label(tostring(text or ''):gsub('\r', ''));
                        if (cleaned ~= '') then
                            rows[row] = cleaned;
                            sources[row] = ('ROM\\165\\72.DAT:%d'):fmt(tonumber(index) or 0);
                        end
                    end
                end
            end
        end
        f:close();
    end

    if (rows[1] == nil or rows[2] == nil or rows[3] == nil) then
        log_line(('equipment set slot picker command resource unavailable path="%s" row1="%s" row2="%s" row3="%s"'):fmt(
            path,
            accessxi.escape_probe_log_text(rows[1] or ''),
            accessxi.escape_probe_log_text(rows[2] or ''),
            accessxi.escape_probe_log_text(rows[3] or '')));
        return nil;
    end

    rows.sources = sources;
    accessxi.equipment_set_slot_picker_command_rows = rows;
    log_line(('loaded equipment set slot picker command resource path="%s" row1="%s" row2="%s" row3="%s"'):fmt(
        path,
        accessxi.escape_probe_log_text(rows[1] or ''),
        accessxi.escape_probe_log_text(rows[2] or ''),
        accessxi.escape_probe_log_text(rows[3] or '')));
    return rows;
end

function accessxi.equipment_set_slot_picker_command_speech(menu_name)
    if (tostring(accessxi.inventory_context or '') ~= 'equipment_set_slot_picker') then
        return nil;
    end
    if (menu_name == nil or not menu_name:eq('menu    inventor', true)) then
        return nil;
    end

    local obj = get_current_menu_object_ptr();
    local expected_obj = tonumber(accessxi.equipment_set_slot_picker_obj) or 0;
    if (expected_obj ~= 0 and obj ~= 0 and expected_obj ~= obj) then
        log_state(('state equipset-slot-picker context-ended oldObj=0x%08X newObj=0x%08X reason="object-changed"'):fmt(expected_obj, obj));
        accessxi.inventory_context = '';
        accessxi.equipment_set_slot_picker_obj = 0;
        return nil;
    end

    local inv = AshitaCore:GetMemoryManager():GetInventory();
    local selected_id = inv ~= nil and (tonumber(safe_call(function () return inv:GetSelectedItemId(); end, 0)) or 0) or 0;
    local selected_index = inv ~= nil and (tonumber(safe_call(function () return inv:GetSelectedItemIndex(); end, -1)) or -1) or -1;
    local selected_name = accessxi.plain_native_menu_label(clean_login_text(inv ~= nil and safe_call(function () return inv:GetSelectedItemName(); end, '') or ''));
    if (selected_id ~= 0 or selected_index ~= 0 or selected_name ~= '') then
        return nil;
    end

    local selected = tonumber(read_current_native_menu_index(0x4C)) or 0;
    if (selected < 1 or selected > 3) then
        return nil;
    end

    local rows = accessxi.load_equipment_set_slot_picker_command_rows();
    local label = rows ~= nil and tostring(rows[selected] or '') or '';
    if (label == '') then
        return nil;
    end

    local source = rows.sources ~= nil and tostring(rows.sources[selected] or '') or '';
    accessxi.last_native_menu_name = menu_name;
    accessxi.last_native_menu_label = label;
    accessxi.last_native_menu_selected = selected;
    accessxi.last_native_menu_tick = tick();
    accessxi.current_speech_key = ('equipset-slot-picker-command:%d:0x%08X:%s'):fmt(
        selected,
        obj,
        label);
    log_state(('state equipset-slot-picker command menu="%s" select=%d obj=0x%08X id=%d index=0x%04X label="%s" source="%s"'):fmt(
        tostring(menu_name or ''),
        selected,
        obj,
        selected_id,
        math.max(selected_index, 0),
        accessxi.escape_probe_log_text(label),
        accessxi.escape_probe_log_text(source)));
    return ('Edit Equipment Set. %s'):fmt(accessxi.sentence_fragment(label));
end

function accessxi.macro_select_menu_label(child)
    child = tonumber(child) or 0;
    if (not accessxi.is_probe_pointer(child)) then
        return '';
    end

    local label = accessxi.survival_guide_text(read_probe_string(child + 0x28, 64));
    label = tostring(label or ''):gsub('%s+', ' '):trim();
    if (label:match('^Macro Book %(#%d+%)$')) then
        return label;
    end

    return '';
end

function accessxi.macro_select_menu_speech(menu_name, title, obj, selected, count, page, raw, child, entry)
    menu_name = tostring(menu_name or '');
    if (not menu_name:eq('menu    mcrselec', true)) then
        return nil;
    end

    local label = accessxi.macro_select_menu_label(child);
    if (label == '') then
        log_state(('state macroselect native-missing menu="%s" title="%s" select=%d count=%d page=%d raw=0x%08X child=0x%08X entry=0x%08X childText="%s"'):fmt(
            menu_name,
            tostring(title or 'Edit Macros'),
            tonumber(selected) or 0,
            tonumber(count) or 0,
            tonumber(page) or 0,
            tonumber(raw) or 0,
            tonumber(child) or 0,
            tonumber(entry) or 0,
            accessxi.escape_probe_log_text(accessxi.is_probe_pointer(tonumber(child) or 0) and accessxi.survival_guide_text(read_probe_string((tonumber(child) or 0) + 0x28, 64)) or '')));
        return nil;
    end

    local book_index = tonumber(label:match('%(#(%d+)%)')) or 0;
    local profile_dir, profile_source = accessxi.macro_active_profile();
    local book_title, title_path, title_source = accessxi.macro_book_title(profile_dir, book_index);
    local spoken_label = label;
    if (book_title ~= '') then
        spoken_label = ('%s. %s'):fmt(label, book_title);
    end

    accessxi.last_native_menu_name = menu_name;
    accessxi.last_native_menu_label = spoken_label;
    accessxi.last_native_menu_selected = tonumber(selected) or 0;
    accessxi.last_native_menu_tick = tick();
    accessxi.current_speech_key = ('macroselect-native:%d:%d:0x%08X:%s:%s'):fmt(
        tonumber(selected) or 0,
        tonumber(book_index) or 0,
        tonumber(child) or 0,
        label,
        book_title);
    log_state(('state macroselect native menu="%s" title="%s" select=%d count=%d page=%d raw=0x%08X child=0x%08X entry=0x%08X bookIndex=%d bookTitle="%s" profile="%s" profileSource="%s" titlePath="%s" titleSource="%s" label="%s" source="child+28+mcr.ttl"'):fmt(
        menu_name,
        tostring(title or 'Edit Macros'),
        tonumber(selected) or 0,
        tonumber(count) or 0,
        tonumber(page) or 0,
        tonumber(raw) or 0,
        tonumber(child) or 0,
        tonumber(entry) or 0,
        tonumber(book_index) or 0,
        accessxi.escape_probe_log_text(book_title),
        accessxi.escape_probe_log_text(profile_dir),
        accessxi.escape_probe_log_text(profile_source),
        accessxi.escape_probe_log_text(title_path),
        accessxi.escape_probe_log_text(title_source),
        accessxi.escape_probe_log_text(spoken_label)));
    return ('%s. %s'):fmt(tostring(title or 'Edit Macros'), accessxi.sentence_fragment(spoken_label));
end

function accessxi.macro_set_header_parts(label)
    label = tostring(label or ''):gsub('%s+', ' '):trim();
    local book_name, set_text = label:match('^Macro Set (.+) %(#(%d+)%)$');
    if (book_name == nil or set_text == nil) then
        book_name, set_text = label:match('^Set (.+) %(#(%d+)%)$');
    end
    if (book_name ~= nil and set_text ~= nil) then
        return tostring(book_name or ''):trim(), tonumber(set_text) or 0;
    end

    set_text = label:match('^Macro Set #(%d+)$') or label:match('^Set #(%d+)$') or label:match('^Set (%d+)$');
    if (set_text ~= nil) then
        return '', tonumber(set_text) or 0;
    end

    return '', 0;
end

function accessxi.macro_edit_menu_header(child)
    child = tonumber(child) or 0;
    if (not accessxi.is_probe_pointer(child)) then
        return '', '', 0;
    end

    local label = accessxi.survival_guide_text(read_probe_string(child + 0x28, 96));
    label = tostring(label or ''):gsub('%s+', ' '):trim();
    local book_name, set_index = accessxi.macro_set_header_parts(label);
    if (set_index > 0) then
        return label, book_name, set_index;
    end

    return '', '', 0;
end

function accessxi.ffxi_install_dir()
    local install_dir = '';
    pcall(function ()
        local lang = AshitaCore:GetConfigurationManager():GetInt32('boot', 'ashita.language', 'playonline', 2);
        if (lang > 4) then
            lang = 2;
        end
        if (lang == 4) then
            lang = 3;
        end
        install_dir = tostring(ashita.fs.get_install_dir(lang, 1) or '');
    end);
    if (install_dir == '') then
        install_dir = accessxi.ffxi_root;
    end
    return install_dir:gsub('[\\/]+$', '');
end

function accessxi.macro_cstring(data, offset, length)
    data = tostring(data or '');
    offset = tonumber(offset) or 0;
    length = tonumber(length) or 0;
    if (length <= 0 or offset < 0 or offset >= #data) then
        return '';
    end

    local raw = data:sub(offset + 1, math.min(#data, offset + length));
    local nul = raw:find('\0', 1, true);
    if (nul ~= nil) then
        raw = raw:sub(1, nul - 1);
    end
    raw = raw:gsub('[%z\001-\031\127]', ' ');
    raw = accessxi.survival_guide_text(raw);
    return tostring(raw or ''):gsub('%s+', ' '):trim();
end

function accessxi.macro_read_file(path)
    path = tostring(path or '');
    if (path == '') then
        return nil;
    end

    local now = tick();
    if (accessxi.macro_file_cache_path == path
        and accessxi.macro_file_cache_data ~= nil
        and ((now - (accessxi.macro_file_cache_tick or 0)) < 1000)) then
        return accessxi.macro_file_cache_data;
    end

    local f = io.open(path, 'rb');
    if (f == nil) then
        return nil;
    end

    local data = f:read('*all') or '';
    f:close();
    accessxi.macro_file_cache_path = path;
    accessxi.macro_file_cache_data = data;
    accessxi.macro_file_cache_tick = now;
    return data;
end

function accessxi.macro_read_file_direct(path)
    path = tostring(path or '');
    if (path == '') then
        return nil;
    end

    local f = io.open(path, 'rb');
    if (f == nil) then
        return nil;
    end

    local data = f:read('*all') or '';
    f:close();
    return data;
end

function accessxi.macro_read_file_shared(path)
    path = tostring(path or '');
    if (path == '') then
        return nil;
    end

    local wide = utf8_to_wide(path);
    if (wide == nil) then
        return nil;
    end

    local handle = kernel32.CreateFileW(
        wide,
        0x80000000,
        0x00000001 + 0x00000002 + 0x00000004,
        nil,
        3,
        0x00000080,
        nil);
    if (handle == nil or handle == ffi.cast('void*', -1)) then
        return nil;
    end

    local size = tonumber(kernel32.GetFileSize(handle, nil)) or 0;
    if (size <= 0 or size >= 0x7FFFFFFF) then
        kernel32.CloseHandle(handle);
        return nil;
    end

    local buffer = ffi.new('uint8_t[?]', size);
    local bytes_read = ffi.new('DWORD[1]');
    bytes_read[0] = 0;
    local ok = kernel32.ReadFile(handle, buffer, size, bytes_read, nil) ~= 0;
    kernel32.CloseHandle(handle);
    local got = tonumber(bytes_read[0]) or 0;
    if (not ok or got <= 0) then
        return nil;
    end
    return ffi.string(buffer, got);
end

function accessxi.file_last_write_time(path)
    path = tostring(path or '');
    if (path == '') then
        return 0;
    end

    local wide = utf8_to_wide(path);
    if (wide == nil) then
        return 0;
    end

    local handle = kernel32.CreateFileW(
        wide,
        0x80000000,
        0x00000001 + 0x00000002 + 0x00000004,
        nil,
        3,
        0x00000080,
        nil);
    if (handle == nil or handle == ffi.cast('void*', -1)) then
        return 0;
    end

    local write_time = ffi.new('FILETIME[1]');
    local ok = kernel32.GetFileTime(handle, nil, nil, write_time) ~= 0;
    kernel32.CloseHandle(handle);
    if (not ok) then
        return 0;
    end

    return ((tonumber(write_time[0].dwHighDateTime) or 0) * 4294967296) + (tonumber(write_time[0].dwLowDateTime) or 0);
end

function accessxi.macro_title_map_from_file(path, first_index)
    path = tostring(path or '');
    first_index = tonumber(first_index) or 1;

    local function parse_title_map(data)
        if (data == nil or #data < (0x18 + (20 * 0x10))) then
            return nil, 0;
        end

        local titles = {};
        local count = 0;
        for i = 0, 19 do
            local index = first_index + i;
            local title = accessxi.macro_cstring(data, 0x18 + (i * 0x10), 0x10);
            titles[index] = title;
            if (title ~= '') then
                count = count + 1;
            end
        end

        return titles, count;
    end

    local best_titles = nil;
    local best_count = 0;
    for _ = 1, 3 do
        local titles, count = parse_title_map(accessxi.macro_read_file_shared(path) or accessxi.macro_read_file_direct(path));
        if (titles ~= nil and count > best_count) then
            best_titles = titles;
            best_count = count;
        end
        if (best_count >= 20) then
            break;
        end
    end

    local cached = accessxi.macro_title_map_cache ~= nil and accessxi.macro_title_map_cache[path] or nil;
    local cached_titles = (cached ~= nil and type(cached.titles) == 'table') and cached.titles or nil;
    if (best_titles ~= nil and best_count > 0) then
        local merged = {};
        local merged_count = 0;
        local used_cached = false;
        for i = 0, 19 do
            local index = first_index + i;
            local title = tostring(best_titles[index] or '');
            if (title == '' and cached_titles ~= nil) then
                local cached_title = tostring(cached_titles[index] or '');
                if (cached_title ~= '') then
                    title = cached_title;
                    used_cached = true;
                end
            end
            merged[index] = title;
            if (title ~= '') then
                merged_count = merged_count + 1;
            end
        end

        accessxi.macro_title_map_cache = accessxi.macro_title_map_cache or {};
        accessxi.macro_title_map_cache[path] = T{
            titles = merged,
            count = merged_count,
            tick = tick(),
        };
        if (used_cached) then
            return merged, ('title-file+cache raw=%d'):fmt(best_count), merged_count;
        end
        return merged, 'title-file', merged_count;
    end

    if (cached_titles ~= nil) then
        return cached_titles, 'cached-title-file', tonumber(cached.count) or 0;
    end

    return nil, 'title-file-unready', 0;
end

function accessxi.macro_book_titles_from_file(path, first_index)
    local title_map = accessxi.macro_title_map_from_file(path, first_index);
    if (type(title_map) ~= 'table') then
        return nil;
    end

    local titles = T{};
    first_index = tonumber(first_index) or 1;
    for i = 0, 19 do
        local title = tostring(title_map[first_index + i] or '');
        if (title ~= '') then
            titles:append(T{ index = first_index + i, title = title });
        end
    end
    return titles;
end

function accessxi.macro_profile_match_book(profile_dir, book_name)
    profile_dir = tostring(profile_dir or ''):gsub('[\\/]+$', '');
    book_name = tostring(book_name or ''):trim();
    if (profile_dir == '' or book_name == '') then
        return nil;
    end

    local all_titles = T{};
    local titles1 = accessxi.macro_book_titles_from_file(profile_dir .. '\\mcr.ttl', 1);
    if (titles1 ~= nil) then
        for _, item in ipairs(titles1) do
            all_titles:append(item);
        end
    end
    local titles2 = accessxi.macro_book_titles_from_file(profile_dir .. '\\mcr_2.ttl', 21);
    if (titles2 ~= nil) then
        for _, item in ipairs(titles2) do
            all_titles:append(item);
        end
    end

    for _, item in ipairs(all_titles) do
        if (tostring(item.title or ''):eq(book_name, true)) then
            return tonumber(item.index) or 0;
        end
    end

    return nil;
end

function accessxi.macro_profile_score(profile_dir)
    profile_dir = tostring(profile_dir or ''):gsub('[\\/]+$', '');
    if (profile_dir == '') then
        return 0;
    end

    local files = safe_call(function () return ashita.fs.get_dir(profile_dir, nil, false); end, nil);
    if (type(files) ~= 'table') then
        return 0;
    end

    local count = 0;
    for _, name in ipairs(files) do
        local leaf = tostring(name or ''):gsub('[\\/]+$', ''):match('([^\\/]+)$') or tostring(name or '');
        leaf = leaf:lower();
        if (leaf:match('^mcr%d*%.dat$') ~= nil) then
            count = count + 1;
        end
    end
    return count;
end

function accessxi.macro_profile_last_write_score(profile_dir)
    profile_dir = tostring(profile_dir or ''):gsub('[\\/]+$', '');
    if (profile_dir == '') then
        return 0, '';
    end

    local best = 0;
    local best_source = '';
    local function note(path, source)
        local value = accessxi.file_last_write_time(path);
        if (value > best) then
            best = value;
            best_source = tostring(source or '');
        end
    end

    note(profile_dir .. '\\mcr.ttl', 'mcr.ttl');
    note(profile_dir .. '\\mcr_2.ttl', 'mcr_2.ttl');
    note(profile_dir .. '\\aix.dat', 'aix.dat');

    local files = safe_call(function () return ashita.fs.get_dir(profile_dir, nil, false); end, nil);
    if (type(files) == 'table') then
        for _, name in ipairs(files) do
            local text = tostring(name or ''):gsub('[\\/]+$', '');
            local leaf = text:match('([^\\/]+)$') or text;
            local lower = leaf:lower();
            if (lower:match('^mcr%d*%.dat$') ~= nil) then
                local path = text:find(':\\', 1, true) and text or (profile_dir .. '\\' .. leaf);
                note(path, lower);
            end
        end
    end

    return best, best_source;
end

function accessxi.macro_active_profile()
    local now = tick();
    if (tostring(accessxi.macro_active_profile_cache_dir or '') ~= ''
        and ((now - (accessxi.macro_active_profile_cache_tick or 0)) < 2000)) then
        return accessxi.macro_active_profile_cache_dir, 'cache';
    end

    local root = accessxi.ffxi_install_dir() .. '\\USER';
    local dirs = safe_call(function () return ashita.fs.get_dir(root, nil, false); end, nil);
    if (type(dirs) ~= 'table') then
        return '', 'no-user-dirs';
    end

    local best_dir = '';
    local best_score = -1;
    local best_write = -1;
    local best_write_source = '';
    for _, name in ipairs(dirs) do
        local text = tostring(name or ''):gsub('[\\/]+$', '');
        local leaf = text:match('([^\\/]+)$') or text;
        local dir = text:find(':\\', 1, true) and text or (root .. '\\' .. leaf);
        local titles = accessxi.macro_book_titles_from_file(dir .. '\\mcr.ttl', 1);
        if (titles ~= nil) then
            local score = accessxi.macro_profile_score(dir);
            local last_write, last_write_source = accessxi.macro_profile_last_write_score(dir);
            if (last_write > best_write or (last_write == best_write and score > best_score)) then
                best_dir = dir;
                best_score = score;
                best_write = last_write;
                best_write_source = last_write_source;
            end
        end
    end

    if (best_dir == '') then
        return '', 'profile-not-found';
    end

    accessxi.macro_title_map_from_file(best_dir .. '\\mcr.ttl', 1);
    accessxi.macro_title_map_from_file(best_dir .. '\\mcr_2.ttl', 21);

    accessxi.macro_active_profile_cache_dir = best_dir;
    accessxi.macro_active_profile_cache_tick = now;
    return best_dir, ('recent=%s score=%d'):fmt(best_write_source ~= '' and best_write_source or 'unknown', best_score);
end

function accessxi.macro_book_title(profile_dir, book_index)
    profile_dir = tostring(profile_dir or ''):gsub('[\\/]+$', '');
    book_index = tonumber(book_index) or 0;
    if (profile_dir == '' or book_index < 1 or book_index > 40) then
        return '', '', 'missing-profile-or-index';
    end

    local first_index = 1;
    local path = profile_dir .. '\\mcr.ttl';
    if (book_index > 20) then
        first_index = 21;
        path = profile_dir .. '\\mcr_2.ttl';
    end

    local title_map, title_source, title_count = accessxi.macro_title_map_from_file(path, first_index);
    if (type(title_map) ~= 'table') then
        return '', path, title_source;
    end

    local title = tostring(title_map[book_index] or '');
    return title, path, ('%s count=%d'):fmt(title_source, tonumber(title_count) or 0);
end

function accessxi.macro_profile_for_book(book_name)
    book_name = tostring(book_name or ''):trim();
    if (book_name == '') then
        return '', 0, 'no-book-name';
    end

    local now = tick();
    local cache_key = book_name;
    if (accessxi.macro_profile_cache_key == cache_key
        and tostring(accessxi.macro_profile_cache_dir or '') ~= ''
        and ((now - (accessxi.macro_profile_cache_tick or 0)) < 2000)) then
        return accessxi.macro_profile_cache_dir, tonumber(accessxi.macro_profile_cache_book_index) or 0, 'cache';
    end

    local root = accessxi.ffxi_install_dir() .. '\\USER';
    local dirs = safe_call(function () return ashita.fs.get_dir(root, nil, false); end, nil);
    if (type(dirs) ~= 'table') then
        return '', 0, 'no-user-dirs';
    end

    local best_dir = '';
    local best_index = 0;
    local best_score = -1;
    for _, name in ipairs(dirs) do
        local text = tostring(name or ''):gsub('[\\/]+$', '');
        local leaf = text:match('([^\\/]+)$') or text;
        local dir = text:find(':\\', 1, true) and text or (root .. '\\' .. leaf);
        local index = accessxi.macro_profile_match_book(dir, book_name);
        if (index ~= nil and index > 0) then
            local score = accessxi.macro_profile_score(dir);
            if (score > best_score) then
                best_dir = dir;
                best_index = index;
                best_score = score;
            end
        end
    end

    if (best_dir == '' or best_index <= 0) then
        return '', 0, 'book-not-found';
    end

    accessxi.macro_profile_cache_key = cache_key;
    accessxi.macro_profile_cache_dir = best_dir;
    accessxi.macro_profile_cache_book_index = best_index;
    accessxi.macro_profile_cache_tick = now;
    return best_dir, best_index, ('title-match score=%d'):fmt(best_score);
end

function accessxi.macro_set_file_path(profile_dir, book_index, set_index)
    profile_dir = tostring(profile_dir or ''):gsub('[\\/]+$', '');
    book_index = tonumber(book_index) or 0;
    set_index = tonumber(set_index) or 0;
    if (profile_dir == '' or book_index <= 0 or set_index <= 0) then
        return '';
    end

    local file_index = ((book_index - 1) * 10) + (set_index - 1);
    if (file_index <= 0) then
        return profile_dir .. '\\mcr.dat';
    end
    return profile_dir .. ('\\mcr%d.dat'):fmt(file_index);
end

function accessxi.macro_slot_from_menu(menu_name, selected)
    menu_name = tostring(menu_name or '');
    selected = tonumber(selected) or 0;
    if (selected < 1 or selected > 10) then
        return 0, '', 0;
    end

    local digit = (selected == 10) and 0 or selected;
    if (menu_name:eq('menu    mcr1edit', true)
        or menu_name:eq('menu    mcr1edlo', true)) then
        return selected, 'Ctrl', digit;
    end
    if (menu_name:eq('menu    mcr2edit', true)
        or menu_name:eq('menu    mcr2edlo', true)) then
        return selected + 10, 'Alt', digit;
    end
    return 0, '', 0;
end

function accessxi.macro_slot_title(profile_dir, book_index, set_index, slot_index)
    local path = accessxi.macro_set_file_path(profile_dir, book_index, set_index);
    local data = accessxi.macro_read_file(path);
    if (data == nil) then
        return '', path, 'file-missing';
    end

    slot_index = tonumber(slot_index) or 0;
    if (slot_index < 1 or slot_index > 20) then
        return '', path, 'slot-out-of-range';
    end

    local base = 0x18 + ((slot_index - 1) * 0x17C);
    local title = accessxi.macro_cstring(data, base + 0x172, 0x08);
    return title, path, 'macro-file';
end

function accessxi.macro_slot_label_from_index(slot_index)
    slot_index = tonumber(slot_index) or 0;
    if (slot_index < 1 or slot_index > 20) then
        return '';
    end

    local prefix = 'Ctrl';
    local digit = slot_index;
    if (slot_index > 10) then
        prefix = 'Alt';
        digit = slot_index - 10;
    end
    if (digit == 10) then
        digit = 0;
    end
    return ('%s %d'):fmt(prefix, digit);
end

function accessxi.macro_slot_detail(profile_dir, book_index, set_index, slot_index)
    local path = accessxi.macro_set_file_path(profile_dir, book_index, set_index);
    local data = accessxi.macro_read_file(path) or accessxi.macro_read_file_shared(path);
    if (data == nil) then
        return nil, path, 'file-missing';
    end

    slot_index = tonumber(slot_index) or 0;
    if (slot_index < 1 or slot_index > 20) then
        return nil, path, 'slot-out-of-range';
    end

    local base = 0x18 + ((slot_index - 1) * 0x17C);
    local detail = T{
        title = accessxi.macro_cstring(data, base + 0x172, 0x08),
        lines = T{},
    };
    for line_index = 1, 6 do
        detail.lines:append(accessxi.macro_cstring(data, base + 0x04 + ((line_index - 1) * 0x3C), 0x3C));
    end
    return detail, path, 'macro-file';
end

function accessxi.macro_detail_context()
    local ctx = accessxi.macro_edit_context;
    if (type(ctx) ~= 'table') then
        return nil;
    end
    if ((tick() - (tonumber(ctx.tick) or 0)) > 300000) then
        return nil;
    end
    if (tostring(ctx.profile_dir or '') == ''
        or (tonumber(ctx.book_index) or 0) <= 0
        or (tonumber(ctx.set_index) or 0) <= 0
        or (tonumber(ctx.slot_index) or 0) <= 0) then
        return nil;
    end
    return ctx;
end

function accessxi.macro_detail_text_matches(detail, text)
    detail = detail or T{};
    text = accessxi.survival_guide_text(text or ''):gsub('%s+', ' '):trim();
    if (text == '') then
        return false;
    end

    local title = tostring(detail.title or ''):gsub('%s+', ' '):trim();
    if (title ~= '' and text:eq(title, true)) then
        return true;
    end

    local lines = detail.lines or T{};
    for line_index = 1, 6 do
        local line = tostring(lines[line_index] or ''):gsub('%s+', ' '):trim();
        if (line ~= '' and text:eq(line, true)) then
            return true;
        end
    end
    return false;
end

function accessxi.macro_detail_refresh_context_for_text(ctx, text)
    if (ctx == nil) then
        return nil, nil, '', '', false;
    end

    local detail, macro_path, macro_source = accessxi.macro_slot_detail(ctx.profile_dir, ctx.book_index, ctx.set_index, ctx.slot_index);
    local clean_text = accessxi.survival_guide_text(text or ''):gsub('%s+', ' '):trim();
    if (detail == nil or clean_text == '' or accessxi.macro_detail_text_matches(detail, clean_text)) then
        return ctx, detail, macro_path, macro_source, false;
    end

    for slot_index = 1, 20 do
        if (slot_index ~= (tonumber(ctx.slot_index) or 0)) then
            local candidate, candidate_path, candidate_source = accessxi.macro_slot_detail(ctx.profile_dir, ctx.book_index, ctx.set_index, slot_index);
            if (accessxi.macro_detail_text_matches(candidate, clean_text)) then
                ctx.slot_index = slot_index;
                ctx.slot_label = accessxi.macro_slot_label_from_index(slot_index);
                ctx.macro_title = tostring(candidate.title or '');
                ctx.macro_path = candidate_path;
                ctx.macro_source = candidate_source;
                ctx.tick = tick();
                return ctx, candidate, candidate_path, candidate_source, true;
            end
        end
    end
    return ctx, detail, macro_path, macro_source, false;
end

function accessxi.macro_detail_row_hint_from_selected(selected)
    selected = tonumber(selected) or 0;
    if (selected == 3) then
        return 'title', 0;
    end
    if (selected >= 4 and selected <= 9) then
        return 'line', selected - 3;
    end
    return '', 0;
end

function accessxi.macro_detail_open_selected_hint(just_opened)
    if (just_opened == true
        and tostring(accessxi.last_native_menu_name or ''):eq('menu    macro', true)
        and (tick() - (tonumber(accessxi.last_native_menu_tick) or 0)) < 3000) then
        local selected = tonumber(accessxi.last_native_menu_selected) or 0;
        local hint_kind = accessxi.macro_detail_row_hint_from_selected(selected);
        if (hint_kind ~= '') then
            return selected, 'open-native';
        end
    end
    return 0, '';
end

function accessxi.macro_detail_same_input_slot(ctx, last)
    if (type(ctx) ~= 'table' or type(last) ~= 'table') then
        return false;
    end
    return (tonumber(ctx.book_index) or 0) == (tonumber(last.book_index) or 0)
        and (tonumber(ctx.set_index) or 0) == (tonumber(last.set_index) or 0)
        and (tonumber(ctx.slot_index) or 0) == (tonumber(last.slot_index) or 0)
        and tostring(ctx.profile_dir or '') == tostring(last.profile_dir or '');
end

function accessxi.macro_detail_inferred_selected_hint(ctx, raw_text)
    raw_text = accessxi.survival_guide_text(raw_text or ''):gsub('%s+', ' '):trim();
    if (raw_text ~= '') then
        return 0, '';
    end

    local last = accessxi.macro_detail_input_last;
    if (not accessxi.macro_detail_same_input_slot(ctx, last)) then
        return 0, '';
    end
    if ((tick() - (tonumber(last.tick) or 0)) > 3000) then
        return 0, '';
    end

    local last_kind = tostring(last.row_kind or '');
    local last_index = tonumber(last.row_index) or 0;
    local last_text = tostring(last.raw_text or '');
    if (last_kind == 'title' and last_text ~= '') then
        return 4, 'after-title';
    end
    if (last_kind == 'line' and last_index >= 1 and last_index < 6 and last_text ~= '') then
        return last_index + 4, 'after-line';
    end
    return 0, '';
end

function accessxi.macro_detail_selected_hint(ctx, raw_text, just_opened)
    local selected, source = accessxi.macro_detail_open_selected_hint(just_opened);
    if (selected > 0) then
        return selected, source;
    end

    return accessxi.macro_detail_inferred_selected_hint(ctx, raw_text);
end

function accessxi.macro_detail_label_for_text(detail, text, selected_hint)
    detail = detail or T{};
    text = accessxi.survival_guide_text(text or ''):gsub('%s+', ' '):trim();
    local title = tostring(detail.title or ''):gsub('%s+', ' '):trim();
    if (text ~= '' and title ~= '' and text:eq(title, true)) then
        return ('Title. %s'):fmt(text), 'title', 0;
    end

    local lines = detail.lines or T{};
    for line_index = 1, 6 do
        local line = tostring(lines[line_index] or ''):gsub('%s+', ' '):trim();
        if (text ~= '' and line ~= '' and text:eq(line, true)) then
            return ('Line %d. %s'):fmt(line_index, text), 'line', line_index;
        end
    end

    if (text == '') then
        local hint_kind, hint_index = accessxi.macro_detail_row_hint_from_selected(selected_hint);
        if (hint_kind == 'title') then
            return 'Title. Blank', 'title', 0;
        end
        if (hint_kind == 'line') then
            return ('Line %d. Blank'):fmt(hint_index), 'line', hint_index;
        end
        return 'Blank macro field.', 'blank', 0;
    end
    return text, 'buffer', 0;
end

function accessxi.macro_detail_char_name(ch)
    ch = tostring(ch or '');
    if (ch == '') then
        return '';
    end
    if (ch == ' ') then
        return 'space';
    end
    if (ch == '"') then
        return 'double quote';
    end
    if (ch == "'") then
        return 'apostrophe';
    end
    if (ch == '/') then
        return 'slash';
    end
    if (ch == '<') then
        return 'less than';
    end
    if (ch == '>') then
        return 'greater than';
    end
    return ch;
end

function accessxi.macro_detail_row_name(row_kind, row_index)
    row_kind = tostring(row_kind or '');
    row_index = tonumber(row_index) or 0;
    if (row_kind == 'title') then
        return 'Title';
    end
    if (row_kind == 'line' and row_index > 0) then
        return ('Line %d'):fmt(row_index);
    end
    return 'Macro field';
end

function accessxi.macro_detail_caret_speech(row_kind, row_index, text, caret, previous_caret)
    text = tostring(text or '');
    caret = tonumber(caret) or 0;
    previous_caret = tonumber(previous_caret);
    local len = #text;
    if (len == 0) then
        return 'blank';
    end

    local char_index = caret;
    if (previous_caret ~= nil and caret < previous_caret) then
        char_index = caret + 1;
    elseif (previous_caret ~= nil and caret > previous_caret) then
        char_index = caret;
    elseif (caret <= 0) then
        char_index = 1;
    elseif (caret > len) then
        char_index = len;
    end

    if (char_index < 1) then
        char_index = 1;
    elseif (char_index > len) then
        char_index = len;
    end

    local ch = accessxi.macro_detail_char_name(text:sub(char_index, char_index));
    if (ch ~= '') then
        return ch;
    end
    return 'blank';
end

function accessxi.macro_detail_row_label(detail, selected)
    selected = tonumber(selected) or 0;
    detail = detail or T{};

    if (selected == 1) then
        return 'Previous macro', 'previous', 0;
    end
    if (selected == 2) then
        return 'Next macro', 'next', 0;
    end
    if (selected == 3) then
        local title = tostring(detail.title or ''):gsub('%s+', ' '):trim();
        if (title == '') then
            return 'Title. Blank', 'title', 0;
        end
        return ('Title. %s'):fmt(title), 'title', 0;
    end
    if (selected >= 4 and selected <= 9) then
        local line_index = selected - 3;
        local line = tostring((detail.lines or T{})[line_index] or ''):gsub('%s+', ' '):trim();
        if (line == '') then
            return ('Line %d. Blank'):fmt(line_index), 'line', line_index;
        end
        return ('Line %d. %s'):fmt(line_index, line), 'line', line_index;
    end
    if (selected == 10) then
        return 'Line Edit', 'option', 1;
    end
    if (selected == 11) then
        return 'Copy Line', 'option', 2;
    end
    return '', '', 0;
end

function accessxi.macro_detail_menu_speech(menu_name, title, obj, selected, count, page, raw, child, entry)
    menu_name = tostring(menu_name or '');
    if (not menu_name:eq('menu    macro', true)) then
        return nil;
    end

    local ctx = accessxi.macro_detail_context();
    if (ctx == nil) then
        return nil;
    end

    local detail, macro_path, macro_source = accessxi.macro_slot_detail(ctx.profile_dir, ctx.book_index, ctx.set_index, ctx.slot_index);
    if (detail == nil) then
        log_state(('state macrodetail native-missing menu="%s" title="%s" select=%d count=%d page=%d raw=0x%08X child=0x%08X entry=0x%08X header="%s" bookIndex=%d set=%d slot=%d macroPath="%s" macroSource="%s"'):fmt(
            menu_name,
            tostring(title or 'Edit Macro'),
            tonumber(selected) or 0,
            tonumber(count) or 0,
            tonumber(page) or 0,
            tonumber(raw) or 0,
            tonumber(child) or 0,
            tonumber(entry) or 0,
            accessxi.escape_probe_log_text(ctx.header or ''),
            tonumber(ctx.book_index) or 0,
            tonumber(ctx.set_index) or 0,
            tonumber(ctx.slot_index) or 0,
            accessxi.escape_probe_log_text(macro_path),
            accessxi.escape_probe_log_text(macro_source)));
        return nil;
    end

    local label, row_kind, row_index = accessxi.macro_detail_row_label(detail, selected);
    if (label == '') then
        log_state(('state macrodetail native-unmapped menu="%s" title="%s" select=%d count=%d page=%d raw=0x%08X child=0x%08X entry=0x%08X header="%s" bookIndex=%d set=%d slot=%d slotLabel="%s" macroTitle="%s" macroPath="%s" macroSource="%s"'):fmt(
            menu_name,
            tostring(title or 'Edit Macro'),
            tonumber(selected) or 0,
            tonumber(count) or 0,
            tonumber(page) or 0,
            tonumber(raw) or 0,
            tonumber(child) or 0,
            tonumber(entry) or 0,
            accessxi.escape_probe_log_text(ctx.header or ''),
            tonumber(ctx.book_index) or 0,
            tonumber(ctx.set_index) or 0,
            tonumber(ctx.slot_index) or 0,
            accessxi.escape_probe_log_text(ctx.slot_label or ''),
            accessxi.escape_probe_log_text(detail.title or ''),
            accessxi.escape_probe_log_text(macro_path),
            accessxi.escape_probe_log_text(macro_source)));
        return nil;
    end

    accessxi.last_native_menu_name = menu_name;
    accessxi.last_native_menu_label = label;
    accessxi.last_native_menu_selected = tonumber(selected) or 0;
    accessxi.last_native_menu_tick = tick();
    accessxi.current_speech_key = ('macrodetail-native:%d:%d:%d:%d:%d:%s:%s'):fmt(
        tonumber(ctx.book_index) or 0,
        tonumber(ctx.set_index) or 0,
        tonumber(ctx.slot_index) or 0,
        tonumber(selected) or 0,
        tonumber(row_index) or 0,
        tostring(row_kind or ''),
        label);
    log_state(('state macrodetail native menu="%s" title="%s" select=%d count=%d page=%d raw=0x%08X child=0x%08X entry=0x%08X header="%s" bookIndex=%d set=%d slot=%d slotLabel="%s" macroTitle="%s" rowKind="%s" rowIndex=%d macroPath="%s" macroSource="%s" label="%s" source="mcr.dat"'):fmt(
        menu_name,
        tostring(title or 'Edit Macro'),
        tonumber(selected) or 0,
        tonumber(count) or 0,
        tonumber(page) or 0,
        tonumber(raw) or 0,
        tonumber(child) or 0,
        tonumber(entry) or 0,
        accessxi.escape_probe_log_text(ctx.header or ''),
        tonumber(ctx.book_index) or 0,
        tonumber(ctx.set_index) or 0,
        tonumber(ctx.slot_index) or 0,
        accessxi.escape_probe_log_text(ctx.slot_label or ''),
        accessxi.escape_probe_log_text(detail.title or ''),
        accessxi.escape_probe_log_text(row_kind or ''),
        tonumber(row_index) or 0,
        accessxi.escape_probe_log_text(macro_path),
        accessxi.escape_probe_log_text(macro_source),
        accessxi.escape_probe_log_text(label)));
    return ('%s. %s. %s'):fmt(tostring(title or 'Edit Macro'), accessxi.sentence_fragment(ctx.slot_label or ''), accessxi.sentence_fragment(label));
end

function accessxi.macro_detail_input_speech(state, just_opened)
    if (state == nil or not tostring(get_menu_name() or ''):eq('menu    macro', true)) then
        return nil, '';
    end

    local ctx = accessxi.macro_detail_context();
    if (ctx == nil) then
        return nil, '';
    end

    local raw_text = accessxi.survival_guide_text(state.spoken or ''):gsub('%s+', ' '):trim();
    local detail, macro_path, macro_source;
    local refreshed = false;
    ctx, detail, macro_path, macro_source, refreshed = accessxi.macro_detail_refresh_context_for_text(ctx, raw_text);
    if (detail == nil) then
        return nil, '';
    end

    local selected_hint, selected_hint_source = accessxi.macro_detail_selected_hint(ctx, raw_text, just_opened);
    local label, row_kind, row_index = accessxi.macro_detail_label_for_text(detail, raw_text, selected_hint);
    local caret_text = tostring((state.raw ~= nil and state.raw ~= '') and state.raw or state.display or '');
    local caret = tonumber(state.caret) or 0;
    local input_identity = ('%s:%d:%d:%d:%s:%d:%s'):fmt(
        tostring(macro_path or ctx.macro_path or ''),
        tonumber(ctx.book_index) or 0,
        tonumber(ctx.set_index) or 0,
        tonumber(ctx.slot_index) or 0,
        tostring(row_kind or ''),
        tonumber(row_index) or 0,
        raw_text);
    local prior_input = accessxi.macro_detail_input_last;
    local same_input = type(prior_input) == 'table' and tostring(prior_input.identity or '') == input_identity;
    local prior_caret = same_input and (tonumber(prior_input.caret) or 0) or nil;
    if (same_input and just_opened ~= true and prior_caret == caret) then
        return '', ('macrodetail-input-duplicate:%s:%d'):fmt(input_identity, caret);
    end

    local mode = 'field';
    if (raw_text ~= ''
        and just_opened ~= true
        and same_input
        and prior_caret ~= caret) then
        label = accessxi.macro_detail_caret_speech(row_kind, row_index, caret_text, caret, prior_caret);
        mode = 'caret';
    end

    local speech = ('Edit Macro. %s. %s'):fmt(accessxi.sentence_fragment(ctx.slot_label or ''), accessxi.sentence_fragment(label));
    local key = ('macrodetail-input:%s:%d:%d:%d:%s:%d:%s'):fmt(
        tostring(macro_path or ctx.macro_path or ''),
        tonumber(ctx.book_index) or 0,
        tonumber(ctx.set_index) or 0,
        tonumber(ctx.slot_index) or 0,
        tostring(row_kind or ''),
        tonumber(row_index) or 0,
        ('%s:%d:%d:%s'):fmt(raw_text, caret, tonumber(selected_hint) or 0, mode));

    accessxi.macro_detail_input_last = T{
        identity = input_identity,
        profile_dir = ctx.profile_dir,
        book_index = tonumber(ctx.book_index) or 0,
        set_index = tonumber(ctx.set_index) or 0,
        slot_index = tonumber(ctx.slot_index) or 0,
        row_kind = row_kind,
        row_index = tonumber(row_index) or 0,
        raw_text = raw_text,
        caret = caret,
        tick = tick(),
    };

    log_state(('state macrodetail input menu="menu    macro" status=0x%02X caret=%d len=%d justOpened=%s refreshed=%s selectedHint=%d selectedHintSource="%s" mode="%s" header="%s" bookIndex=%d set=%d slot=%d slotLabel="%s" rowKind="%s" rowIndex=%d raw="%s" macroPath="%s" macroSource="%s" label="%s"'):fmt(
        tonumber(state.status) or 0,
        tonumber(state.caret) or 0,
        tonumber(state.length) or 0,
        just_opened == true and 'true' or 'false',
        refreshed == true and 'true' or 'false',
        tonumber(selected_hint) or 0,
        accessxi.escape_probe_log_text(selected_hint_source or ''),
        accessxi.escape_probe_log_text(mode),
        accessxi.escape_probe_log_text(ctx.header or ''),
        tonumber(ctx.book_index) or 0,
        tonumber(ctx.set_index) or 0,
        tonumber(ctx.slot_index) or 0,
        accessxi.escape_probe_log_text(ctx.slot_label or ''),
        accessxi.escape_probe_log_text(row_kind or ''),
        tonumber(row_index) or 0,
        accessxi.escape_probe_log_text(raw_text),
        accessxi.escape_probe_log_text(macro_path),
        accessxi.escape_probe_log_text(macro_source),
        accessxi.escape_probe_log_text(label)));
    return speech, key;
end

function accessxi.macro_edit_menu_speech(menu_name, title, obj, selected, count, page, raw, child, entry)
    menu_name = tostring(menu_name or '');
    if (not accessxi.is_macro_edit_menu_name(menu_name)) then
        return nil;
    end

    local header, book_name, set_index = accessxi.macro_edit_menu_header(child);
    if (header == '') then
        log_state(('state macroedit native-missing menu="%s" title="%s" select=%d count=%d page=%d raw=0x%08X child=0x%08X entry=0x%08X childText="%s"'):fmt(
            menu_name,
            tostring(title or 'Edit Macro Book'),
            tonumber(selected) or 0,
            tonumber(count) or 0,
            tonumber(page) or 0,
            tonumber(raw) or 0,
            tonumber(child) or 0,
            tonumber(entry) or 0,
            accessxi.escape_probe_log_text(accessxi.is_probe_pointer(tonumber(child) or 0) and accessxi.survival_guide_text(read_probe_string((tonumber(child) or 0) + 0x28, 96)) or '')));
        return nil;
    end

    local slot_index, slot_prefix, slot_digit = accessxi.macro_slot_from_menu(menu_name, selected);
    if (slot_index <= 0) then
        log_state(('state macroedit slot-missing menu="%s" title="%s" select=%d count=%d page=%d raw=0x%08X child=0x%08X entry=0x%08X header="%s"'):fmt(
            menu_name,
            tostring(title or 'Edit Macro Book'),
            tonumber(selected) or 0,
            tonumber(count) or 0,
            tonumber(page) or 0,
            tonumber(raw) or 0,
            tonumber(child) or 0,
            tonumber(entry) or 0,
            accessxi.escape_probe_log_text(header)));
        return nil;
    end

    local profile_dir, book_index, profile_source = accessxi.macro_profile_for_book(book_name);
    local macro_title, macro_path, macro_source = accessxi.macro_slot_title(profile_dir, book_index, set_index, slot_index);
    local slot_label = ('%s %d'):fmt(slot_prefix, slot_digit);
    local label = slot_label;
    if (macro_title ~= '') then
        label = ('%s. %s'):fmt(slot_label, macro_title);
    end

    accessxi.macro_edit_context = T{
        menu_name = menu_name,
        header = header,
        book_name = book_name,
        book_index = tonumber(book_index) or 0,
        set_index = tonumber(set_index) or 0,
        slot_index = tonumber(slot_index) or 0,
        slot_label = slot_label,
        macro_title = macro_title,
        profile_dir = profile_dir,
        profile_source = profile_source,
        macro_path = macro_path,
        macro_source = macro_source,
        tick = tick(),
    };

    accessxi.last_native_menu_name = menu_name;
    accessxi.last_native_menu_label = label;
    accessxi.last_native_menu_selected = tonumber(selected) or 0;
    accessxi.last_native_menu_tick = tick();
    accessxi.current_speech_key = ('macroedit-native:%s:%d:%d:%d:%d:0x%08X:%s:%s'):fmt(
        menu_name,
        tonumber(selected) or 0,
        tonumber(book_index) or 0,
        tonumber(set_index) or 0,
        tonumber(slot_index) or 0,
        tonumber(child) or 0,
        header,
        label);
    log_state(('state macroedit native menu="%s" title="%s" select=%d count=%d page=%d raw=0x%08X child=0x%08X entry=0x%08X header="%s" book="%s" bookIndex=%d set=%d slot=%d slotLabel="%s" macroTitle="%s" profile="%s" profileSource="%s" macroPath="%s" macroSource="%s" label="%s" source="child+28+mcr.dat"'):fmt(
        menu_name,
        tostring(title or 'Edit Macro Book'),
        tonumber(selected) or 0,
        tonumber(count) or 0,
        tonumber(page) or 0,
        tonumber(raw) or 0,
        tonumber(child) or 0,
        tonumber(entry) or 0,
        accessxi.escape_probe_log_text(header),
        accessxi.escape_probe_log_text(book_name),
        tonumber(book_index) or 0,
        tonumber(set_index) or 0,
        tonumber(slot_index) or 0,
        accessxi.escape_probe_log_text(slot_label),
        accessxi.escape_probe_log_text(macro_title),
        accessxi.escape_probe_log_text(profile_dir),
        accessxi.escape_probe_log_text(profile_source),
        accessxi.escape_probe_log_text(macro_path),
        accessxi.escape_probe_log_text(macro_source),
        accessxi.escape_probe_log_text(label)));
    return ('%s. %s. %s'):fmt(tostring(title or 'Edit Macro Book'), accessxi.sentence_fragment(header), accessxi.sentence_fragment(label));
end

function accessxi.macro_select_option_help_is_native_text(help)
    help = accessxi.survival_guide_text(help or '');
    return help:eq('Edit macro book.', true)
        or help:eq('Edit name of macro book.', true)
        or help:eq('Copy macro book.', true)
        or help:eq('Paste macro book.', true)
        or help:eq('Delete macro book.', true)
        or help:eq('Open your Mog House to party and alliance members.', true)
        or help:eq('Close your Mog House to visitors.', true)
        or help:eq('Copy macro set.', true)
        or help:eq('Paste macro set.', true)
        or help:eq('Delete macro set.', true)
        or help:eq('Automatically sort items as they enter your inventory.', true)
        or help:eq('Disable the autosort function, and opt to manually sort your inventory.', true);
end

function accessxi.macro_select_option_menu_speech(menu_name, title, obj, selected, count, page, raw, child, entry)
    menu_name = tostring(menu_name or '');
    if (not menu_name:eq('menu    mcrselop', true)) then
        return nil;
    end

    entry = tonumber(entry) or 0;
    if (not accessxi.is_probe_pointer(entry)) then
        return nil;
    end

    local help_ptr = read_u32(entry + 0x40) or 0;
    local help = accessxi.survival_guide_text(read_probe_string(help_ptr, 180));
    if (not accessxi.macro_select_option_help_is_native_text(help)) then
        log_state(('state macroselectoption native-missing menu="%s" title="%s" select=%d count=%d page=%d raw=0x%08X child=0x%08X entry=0x%08X helpPtr=0x%08X help="%s"'):fmt(
            menu_name,
            tostring(title or 'Edit Macros'),
            tonumber(selected) or 0,
            tonumber(count) or 0,
            tonumber(page) or 0,
            tonumber(raw) or 0,
            tonumber(child) or 0,
            entry,
            help_ptr,
            accessxi.escape_probe_log_text(help)));
        return nil;
    end

    if (help:eq('Paste macro book.', true)
        or help:eq('Paste macro set.', true)
        or help:eq('Delete macro book.', true)
        or help:eq('Delete macro set.', true)) then
        accessxi.macro_paste_confirm_context = T{
            action = help,
            menu_name = menu_name,
            selected = tonumber(selected) or 0,
            entry = entry,
            tick = tick(),
        };
    else
        accessxi.macro_paste_confirm_context = nil;
    end

    accessxi.last_native_menu_name = menu_name;
    accessxi.last_native_menu_label = help;
    accessxi.last_native_menu_selected = tonumber(selected) or 0;
    accessxi.last_native_menu_tick = tick();
    accessxi.current_speech_key = ('macroselectoption-native-help:%d:0x%08X:0x%08X:%s'):fmt(
        tonumber(selected) or 0,
        entry,
        help_ptr,
        help);
    log_state(('state macroselectoption native menu="%s" title="%s" select=%d count=%d page=%d raw=0x%08X child=0x%08X entry=0x%08X helpPtr=0x%08X help="%s" source="entry+40"'):fmt(
        menu_name,
        tostring(title or 'Edit Macros'),
        tonumber(selected) or 0,
        tonumber(count) or 0,
        tonumber(page) or 0,
        tonumber(raw) or 0,
        tonumber(child) or 0,
        entry,
        help_ptr,
        accessxi.escape_probe_log_text(help)));
    return ('%s. %s'):fmt(tostring(title or 'Edit Macros'), accessxi.sentence_fragment(help));
end

function accessxi.macro_paste_confirmation_selected_label()
    for _, offset in ipairs(T{ 0x4C, 0x50, 0x30, 0x34, 0x64 }) do
        local selected = tonumber(read_current_native_menu_index(offset)) or -1;
        if (selected == 0 or selected == 1) then
            local label = option_from_index(T{ 'Yes', 'No' }, selected);
            if (label ~= '') then
                return label, selected, offset;
            end
        end
    end
    return '', -1, 0;
end

function accessxi.remember_generic_comyn_context(menu_name, previous_menu_name)
    menu_name = tostring(menu_name or '');
    previous_menu_name = tostring(previous_menu_name or '');
    if (not menu_name:eq('menu    comyn', true)) then
        return;
    end
    if (previous_menu_name:eq('menu    comyn', true)) then
        return;
    end

    local now = tick();
    local target = safe_call(function () return AshitaCore:GetMemoryManager():GetTarget(); end, nil);
    local window_name = accessxi.survival_guide_text(target ~= nil and safe_call(function () return target:GetWindowName(); end, '') or '');
    local label = accessxi.survival_guide_text(accessxi.last_native_menu_label or '');
    local source_menu = tostring(accessxi.last_native_menu_name or '');
    local source_selected = tonumber(accessxi.last_native_menu_selected) or 0;
    local source_age = (tonumber(accessxi.last_native_menu_tick) or 0) > 0 and (now - (tonumber(accessxi.last_native_menu_tick) or 0)) or 999999;

    accessxi.generic_comyn_context = T{
        label = label,
        source_menu = source_menu,
        source_selected = source_selected,
        source_age = source_age,
        window_name = window_name,
        transition_from = previous_menu_name,
        tick = now,
    };

    local key = ('%s:%s:%d:%s:%s'):fmt(source_menu, label, source_selected, window_name, previous_menu_name);
    if (key ~= tostring(accessxi.generic_comyn_context_last_key or '')) then
        accessxi.generic_comyn_context_last_key = key;
        log_state(('state generic-comyn context menu="%s" from="%s" sourceMenu="%s" sourceSelect=%d sourceAge=%d label="%s" window="%s"'):fmt(
            menu_name,
            accessxi.escape_probe_log_text(previous_menu_name),
            accessxi.escape_probe_log_text(source_menu),
            source_selected,
            source_age,
            accessxi.escape_probe_log_text(label),
            accessxi.escape_probe_log_text(window_name)));
    end
end

function accessxi.generic_comyn_selected_label()
    local options = T{ 'Yes', 'No' };
    local count = math.max(
        tonumber(accessxi.native_menu_index(0x58)) or 0,
        tonumber(accessxi.native_menu_index(0x24)) or 0,
        tonumber(accessxi.native_menu_index(0x28)) or 0);
    local selected4c = tonumber(read_current_native_menu_index(0x4C)) or -1;
    if (selected4c == 1 or selected4c == 2) then
        return option_from_index(options, selected4c - 1), selected4c, 0x4C, 'native-one';
    end
    if (selected4c == 0 and count == 2) then
        return option_from_index(options, selected4c), selected4c, 0x4C, 'native-zero';
    end

    for _, offset in ipairs(T{ 0x50, 0x30, 0x34, 0x64 }) do
        local selected = tonumber(read_current_native_menu_index(offset)) or -1;
        if (selected == 0 or selected == 1) then
            return option_from_index(options, selected), selected, offset, 'native-zero';
        end
    end
    if (count == 2) then
        for _, offset in ipairs(T{ 0x50, 0x30, 0x34, 0x64 }) do
            local selected = tonumber(read_current_native_menu_index(offset)) or -1;
            if (selected == 1 or selected == 2) then
                return option_from_index(options, selected - 1), selected, offset, 'native-one';
            end
        end
    end

    local ank_num = read_target_ank_num();
    if (ank_num >= 0) then
        local parity = bit.band(ank_num, 1);
        return option_from_index(options, parity), parity, -1, 'ank-parity';
    end

    return '', -1, 0, '';
end

function accessxi.generic_comyn_prompt_from_context(ctx)
    if (type(ctx) ~= 'table') then
        return '', 'Confirmation', '';
    end

    local label = accessxi.survival_guide_text(ctx.label or '');
    local source_menu = tostring(ctx.source_menu or '');
    if (source_menu:eq('menu    socialme', true) or source_menu:eq('menu    menuwind', true)) then
        if (label:eq('Shut Down', true)) then
            return 'Shut down?', 'Shut Down', 'ROM\\97\\42.DAT:614';
        end
        if (label:eq('Log Out', true)) then
            return 'Log out?', 'Log Out', 'ROM\\97\\42.DAT:72';
        end
    end

    local window_name = accessxi.survival_guide_text(ctx.window_name or '');
    if (window_name ~= '') then
        return '', window_name, 'window';
    end
    if (label ~= '') then
        return '', label, 'last-native';
    end
    return '', 'Confirmation', '';
end

function accessxi.generic_comyn_confirmation_speech(menu_name)
    menu_name = tostring(menu_name or '');
    if (not menu_name:eq('menu    comyn', true)) then
        return nil;
    end

    local ctx = accessxi.generic_comyn_context;
    if (type(ctx) ~= 'table') then
        return nil;
    end
    local age = (tonumber(ctx.tick) or 0) > 0 and (tick() - (tonumber(ctx.tick) or 0)) or 999999;
    if (age > 30000) then
        return nil;
    end
    local source_menu = tostring(ctx.source_menu or '');
    if (not source_menu:eq('menu    socialme', true) and not source_menu:eq('menu    menuwind', true)) then
        return nil;
    end

    local prompt, context_label, prompt_source = accessxi.generic_comyn_prompt_from_context(ctx);
    if (context_label == '') then
        return nil;
    end

    local selected_label, selected, selected_offset, selected_source = accessxi.generic_comyn_selected_label();
    local key = ('native-known-generic-comyn:%s:%s:%s:%d:%d:%s'):fmt(
        menu_name,
        context_label,
        prompt,
        tonumber(selected) or -1,
        tonumber(selected_offset) or 0,
        selected_source);

    accessxi.last_native_menu_name = menu_name;
    accessxi.last_native_menu_label = selected_label ~= '' and selected_label or context_label;
    accessxi.last_native_menu_selected = tonumber(selected) or 0;
    accessxi.last_native_menu_tick = tick();
    accessxi.current_speech_key = key;
    if (key ~= tostring(accessxi.generic_comyn_last_key or '')) then
        accessxi.generic_comyn_last_key = key;
        log_state(('state generic-comyn confirm menu="%s" context="%s" prompt="%s" promptSource="%s" selected=%d selectedOffset=0x%02X selectedSource="%s" selectedLabel="%s" idx4C=%d idx50=%d count=%d age=%d'):fmt(
            menu_name,
            accessxi.escape_probe_log_text(context_label),
            accessxi.escape_probe_log_text(prompt),
            accessxi.escape_probe_log_text(prompt_source),
            tonumber(selected) or -1,
            tonumber(selected_offset) or 0,
            accessxi.escape_probe_log_text(selected_source),
            accessxi.escape_probe_log_text(selected_label),
            tonumber(read_current_native_menu_index(0x4C)) or -1,
            tonumber(read_current_native_menu_index(0x50)) or -1,
            math.max(
                tonumber(accessxi.native_menu_index(0x58)) or 0,
                tonumber(accessxi.native_menu_index(0x24)) or 0,
                tonumber(accessxi.native_menu_index(0x28)) or 0),
            age));
    end

    if (prompt ~= '' and selected_label ~= '') then
        return ('%s %s %s'):fmt(
            accessxi.sentence_fragment(context_label),
            accessxi.sentence_fragment(prompt),
            accessxi.sentence_fragment(selected_label));
    elseif (prompt ~= '') then
        return ('%s %s Yes or No.'):fmt(
            accessxi.sentence_fragment(context_label),
            accessxi.sentence_fragment(prompt));
    elseif (selected_label ~= '') then
        return ('Confirmation. %s %s'):fmt(
            accessxi.sentence_fragment(context_label),
            accessxi.sentence_fragment(selected_label));
    end

    return ('Confirmation. %s Yes or No.'):fmt(accessxi.sentence_fragment(context_label));
end

function accessxi.macro_paste_confirmation_speech(menu_name)
    menu_name = tostring(menu_name or '');
    if (not menu_name:eq('menu    comyn', true)) then
        return nil;
    end

    local ctx = accessxi.macro_paste_confirm_context;
    if (type(ctx) ~= 'table') then
        return nil;
    end

    local age = (tonumber(ctx.tick) or 0) > 0 and (tick() - (tonumber(ctx.tick) or 0)) or 999999;
    if (age > 30000) then
        accessxi.macro_paste_confirm_context = nil;
        return nil;
    end

    local action = tostring(ctx.action or '');
    if (not action:eq('Paste macro book.', true)
        and not action:eq('Paste macro set.', true)
        and not action:eq('Delete macro book.', true)
        and not action:eq('Delete macro set.', true)) then
        return nil;
    end

    local selected_label, selected, selected_offset = accessxi.macro_paste_confirmation_selected_label();
    local action_label = action:gsub('%.$', '');
    local action_key = action:lower();
    local item_kind = action_key:find('set', 1, true) ~= nil and 'set' or 'book';
    local prompt = action_key:find('delete', 1, true) ~= nil
        and ('Do you really wish to delete this macro %s?'):fmt(item_kind)
        or ('This macro %s will be overwritten. Do you still wish to paste?'):fmt(item_kind);
    local key = ('native-known-macro-paste-confirm:%s:%s:%d:%d:%s'):fmt(
        menu_name,
        action_label,
        tonumber(selected) or -1,
        tonumber(selected_offset) or 0,
        prompt);

    accessxi.last_native_menu_name = menu_name;
    accessxi.last_native_menu_label = selected_label ~= '' and selected_label or action_label;
    accessxi.last_native_menu_selected = tonumber(selected) or 0;
    accessxi.last_native_menu_tick = tick();
    accessxi.current_speech_key = key;
    if (key ~= tostring(accessxi.macro_paste_confirm_last_key or '')) then
        accessxi.macro_paste_confirm_last_key = key;
        log_state(('state macro-paste-confirm menu="%s" action="%s" prompt="%s" selected=%d selectedOffset=0x%02X selectedLabel="%s" contextAge=%d'):fmt(
            menu_name,
            accessxi.escape_probe_log_text(action),
            accessxi.escape_probe_log_text(prompt),
            tonumber(selected) or -1,
            tonumber(selected_offset) or 0,
            accessxi.escape_probe_log_text(selected_label),
            age));
    end

    if (selected_label ~= '') then
        return ('%s. %s. %s.'):fmt(
            accessxi.sentence_fragment(action_label),
            accessxi.sentence_fragment(prompt),
            accessxi.sentence_fragment(selected_label));
    end

    return ('%s. %s. Yes or No.'):fmt(
        accessxi.sentence_fragment(action_label),
        accessxi.sentence_fragment(prompt));
end

function accessxi.equipment_set_confirmation_prompt(row_id)
    row_id = tonumber(row_id) or 0;
    if (row_id <= 0) then
        return '';
    end

    accessxi.equipment_set_confirmation_prompts = accessxi.equipment_set_confirmation_prompts or {};
    if (accessxi.equipment_set_confirmation_prompts[row_id] ~= nil) then
        return accessxi.equipment_set_confirmation_prompts[row_id];
    end
    if (type(accessxi.equipment_set_confirmation_prompts_tried) ~= 'table') then
        accessxi.equipment_set_confirmation_prompts_tried = {};
    end
    if (accessxi.equipment_set_confirmation_prompts_tried[row_id] == true) then
        return '';
    end
    accessxi.equipment_set_confirmation_prompts_tried[row_id] = true;

    local path = accessxi.dat_index_path();
    local f = io.open(path, 'rb');
    if (f ~= nil) then
        for line in f:lines() do
            local index, text = line:match('^%d+\tDmsgTable\tROM\\165\\72%.DAT\t(%d+)\t(.*)$');
            if (index ~= nil) then
                local id = tonumber(index) or 0;
                if (id == row_id) then
                    local prompt = accessxi.plain_native_menu_help(tostring(text or ''):gsub('\r', ''));
                    if (prompt ~= '') then
                        accessxi.equipment_set_confirmation_prompts[row_id] = prompt;
                    end
                    break;
                end
            end
        end
        f:close();
    end

    local prompt = tostring(accessxi.equipment_set_confirmation_prompts[row_id] or '');
    if (prompt == '') then
        log_line(('equipment set confirmation resource missing path="%s" row=%d'):fmt(path, row_id));
    end
    return prompt;
end

function accessxi.equipment_set_confirmation_speech(menu_name)
