function accessxi.macro_palette_menu_speech(menu_name, title, obj, selected, count, page, raw, child, entry)
    menu_name = tostring(menu_name or '');
    if (not menu_name:eq('menu    mcrmenu', true)) then
        return nil;
    end

    entry = tonumber(entry) or 0;
    if (not accessxi.is_probe_pointer(entry)) then
        return nil;
    end

    local help_ptr = read_u32(entry + 0x40) or 0;
    local help = accessxi.survival_guide_text(read_probe_string(help_ptr, 180));
    if (not accessxi.macro_palette_help_is_native_text(help)) then
        log_state(('state macropalette native-missing menu="%s" title="%s" select=%d count=%d page=%d raw=0x%08X child=0x%08X entry=0x%08X helpPtr=0x%08X help="%s"'):fmt(
            menu_name,
            tostring(title or 'MacroPalette'),
            tonumber(selected) or 0,
            tonumber(count) or 0,
            tonumber(page) or 0,
            tonumber(raw) or 0,
            tonumber(child) or 0,
            entry,
            help_ptr,
            accessxi.escape_probe_log_text(help)));
        return nil;
    end

    accessxi.last_native_menu_name = menu_name;
    accessxi.last_native_menu_label = help;
    accessxi.last_native_menu_selected = tonumber(selected) or 0;
    accessxi.last_native_menu_tick = tick();
    accessxi.current_speech_key = ('macropalette-native-help:%d:0x%08X:0x%08X:%s'):fmt(
        tonumber(selected) or 0,
        entry,
        help_ptr,
        help);
    log_state(('state macropalette native menu="%s" title="%s" select=%d count=%d page=%d raw=0x%08X child=0x%08X entry=0x%08X helpPtr=0x%08X help="%s" source="entry+40"'):fmt(
        menu_name,
        tostring(title or 'MacroPalette'),
        tonumber(selected) or 0,
        tonumber(count) or 0,
        tonumber(page) or 0,
        tonumber(raw) or 0,
        tonumber(child) or 0,
        entry,
        help_ptr,
        accessxi.escape_probe_log_text(help)));
    return ('%s. %s'):fmt(tostring(title or 'MacroPalette'), accessxi.sentence_fragment(help));
end

function accessxi.macro_live_palette_row(menu_name)
    menu_name = tostring(menu_name or '');
    if (menu_name:eq('menu    mcr1pall', true)
        or menu_name:eq('menu    mcr1long', true)) then
        return 'Ctrl', 0;
    end
    if (menu_name:eq('menu    mcr2pall', true)
        or menu_name:eq('menu    mcr2long', true)) then
        return 'Alt', 10;
    end
    return '', 0;
end

function accessxi.macro_live_palette_header(child)
    child = tonumber(child) or 0;
    if (not accessxi.is_probe_pointer(child)) then
        return '', '', 0, '';
    end

    for _, offset in ipairs(T{ 0x28, 0x24, 0x20, 0x2C, 0x30 }) do
        local label = accessxi.survival_guide_text(read_probe_string(child + offset, 96));
        label = tostring(label or ''):gsub('%s+', ' '):trim();
        if (label ~= '') then
            local book_name, set_index = accessxi.macro_set_header_parts(label);
            if (set_index > 0) then
                return label, book_name, set_index, ('child+0x%02X'):fmt(offset);
            end
        end
    end

    return '', '', 0, 'not-found';
end

function accessxi.macro_live_palette_speech(menu_name, title, obj, selected, count, page, raw, child, entry)
    menu_name = tostring(menu_name or '');
    local row_prefix, slot_base = accessxi.macro_live_palette_row(menu_name);
    if (row_prefix == '') then
        return nil;
    end

    selected = tonumber(selected) or 0;
    if (selected < 1 or selected > 10) then
        selected = tonumber(read_current_native_menu_index(0x4C)) or 0;
    end
    if (selected < 1 or selected > 10) then
        return nil;
    end

    local header, book_name, set_index, header_source = accessxi.macro_live_palette_header(child);
    if (set_index <= 0) then
        log_state(('state macropalette live-missing-header menu="%s" title="%s" select=%d count=%d page=%d raw=0x%08X child=0x%08X entry=0x%08X source="%s"'):fmt(
            menu_name,
            tostring(title or 'Macro Palette'),
            selected,
            tonumber(count) or 0,
            tonumber(page) or 0,
            tonumber(raw) or 0,
            tonumber(child) or 0,
            tonumber(entry) or 0,
            accessxi.escape_probe_log_text(header_source)));
        return nil;
    end

    local profile_dir = '';
    local book_index = 0;
    local profile_source = '';
    if (book_name ~= '') then
        profile_dir, book_index, profile_source = accessxi.macro_profile_for_book(book_name);
    end
    if (profile_dir == '' or book_index <= 0) then
        log_state(('state macropalette live-missing-profile menu="%s" header="%s" book="%s" set=%d select=%d source="%s" profileSource="%s"'):fmt(
            menu_name,
            accessxi.escape_probe_log_text(header),
            accessxi.escape_probe_log_text(book_name),
            tonumber(set_index) or 0,
            selected,
            accessxi.escape_probe_log_text(header_source),
            accessxi.escape_probe_log_text(profile_source)));
        return nil;
    end

    local slot_index = slot_base + selected;
    local slot_label = accessxi.macro_slot_label_from_index(slot_index);
    local macro_title, macro_path, macro_source = accessxi.macro_slot_title(profile_dir, book_index, set_index, slot_index);
    local label = slot_label;
    if (macro_title ~= '') then
        label = ('%s. %s'):fmt(slot_label, macro_title);
    end

    accessxi.last_native_menu_name = menu_name;
    accessxi.last_native_menu_label = label;
    accessxi.last_native_menu_selected = selected;
    accessxi.last_native_menu_tick = tick();
    accessxi.current_speech_key = ('macropalette-live:%s:%d:%s:%d:%d:%s'):fmt(
        menu_name,
        selected,
        book_name,
        tonumber(set_index) or 0,
        slot_index,
        macro_title);
    local log_key = ('%s:%d:%s:%d:%d:%s:%s'):fmt(menu_name, selected, book_name, set_index, slot_index, macro_title, macro_source);
    if (log_key ~= tostring(accessxi.macro_live_palette_last_log_key or '')) then
        accessxi.macro_live_palette_last_log_key = log_key;
        log_state(('state macropalette live menu="%s" title="%s" row="%s" select=%d count=%d page=%d raw=0x%08X child=0x%08X entry=0x%08X header="%s" headerSource="%s" book="%s" bookIndex=%d set=%d slot=%d slotLabel="%s" macroTitle="%s" profile="%s" profileSource="%s" macroPath="%s" macroSource="%s" source="mcr.dat"'):fmt(
            menu_name,
            tostring(title or 'Macro Palette'),
            row_prefix,
            selected,
            tonumber(count) or 0,
            tonumber(page) or 0,
            tonumber(raw) or 0,
            tonumber(child) or 0,
            tonumber(entry) or 0,
            accessxi.escape_probe_log_text(header),
            accessxi.escape_probe_log_text(header_source),
            accessxi.escape_probe_log_text(book_name),
            tonumber(book_index) or 0,
            tonumber(set_index) or 0,
            tonumber(slot_index) or 0,
            accessxi.escape_probe_log_text(slot_label),
            accessxi.escape_probe_log_text(macro_title),
            accessxi.escape_probe_log_text(profile_dir),
            accessxi.escape_probe_log_text(profile_source),
            accessxi.escape_probe_log_text(macro_path),
            accessxi.escape_probe_log_text(macro_source)));
    end

    return ('%s. %s. %s'):fmt(
        tostring(title or 'Macro Palette'),
        accessxi.sentence_fragment(header),
        accessxi.sentence_fragment(label));
end

function accessxi.macro_live_palette_current_speech(menu_name)
    menu_name = tostring(menu_name or '');
    if (accessxi.macro_live_palette_row(menu_name) == '') then
        return nil;
    end

    local title = accessxi.native_known_menu_title(menu_name);
    if (title == '') then
        title = 'Macro Palette';
    end
    local obj = get_current_menu_object_ptr();
    if (obj == 0) then
        return nil;
    end
    local selected, page, raw, child, count = accessxi.survival_guide_query_child_state_for_obj(obj);
    selected = read_current_native_menu_index(0x4C);
    local entry = read_u32(obj + 0x08) or 0;
    return accessxi.macro_live_palette_speech(menu_name, title, obj, selected, count, page, raw, child, entry);
end

function accessxi.enable_view_house_probe(reason)
    accessxi.view_house_probe_until = tick() + 12000;
    accessxi.view_house_probe_last_tick = 0;
    accessxi.view_house_probe_last_key = '';
    log_line(('viewhouse probe enabled reason="%s"'):fmt(accessxi.escape_probe_log_text(reason or '')));
end

function accessxi.log_view_house_menu_probe(menu_name, title, obj, selected, count, page, raw, child, entry, reason)
    if (tick() > (tonumber(accessxi.view_house_probe_until) or 0)) then
        return 0;
    end

    local now = tick();
    if ((now - (tonumber(accessxi.view_house_probe_last_tick) or 0)) < 140) then
        return 0;
    end

    menu_name = tostring(menu_name or '');
    if (not menu_name:eq('menu    mogcont', true)) then
        return 0;
    end

    obj = tonumber(obj) or 0;
    child = tonumber(child) or 0;
    entry = tonumber(entry) or 0;
    selected = tonumber(selected) or 0;
    count = tonumber(count) or 0;
    page = tonumber(page) or 0;
    raw = tonumber(raw) or 0;

    local indices = T{};
    for _, off in ipairs(T{ 0x24, 0x28, 0x30, 0x34, 0x4C, 0x50, 0x58, 0x5C, 0x60, 0x64, 0x68 }) do
        indices:append(('%02X=%d'):fmt(off, tonumber(read_current_native_menu_index(off)) or 0));
    end

    local key = ('%s:%d:%d:%d:0x%08X:0x%08X:0x%08X:%s'):fmt(
        menu_name,
        selected,
        count,
        page,
        raw,
        child,
        entry,
        indices:concat(','));
    if (key == tostring(accessxi.view_house_probe_last_key or '')) then
        return 0;
    end
    accessxi.view_house_probe_last_key = key;
    accessxi.view_house_probe_last_tick = now;
    accessxi.view_house_probe_sequence = (tonumber(accessxi.view_house_probe_sequence) or 0) + 1;
    local seq = accessxi.view_house_probe_sequence;

    log_line(('viewhouseprobe seq=%d begin reason="%s" menu="%s" title="%s" selected=%d count=%d page=%d raw=0x%08X obj=0x%08X child=0x%08X entry=0x%08X indices="%s" target="%s"'):fmt(
        seq,
        accessxi.escape_probe_log_text(reason or ''),
        accessxi.escape_probe_log_text(menu_name),
        accessxi.escape_probe_log_text(tostring(title or '')),
        selected,
        count,
        page,
        raw,
        obj,
        child,
        entry,
        accessxi.escape_probe_log_text(indices:concat(',')),
        accessxi.escape_probe_log_text(current_target_snapshot())));

    if (accessxi.is_probe_pointer(obj)) then
        log_line(('viewhouseprobe seq=%d obj d00=%s d80=%s'):fmt(seq, accessxi.format_probe_dwords(obj, 0x00, 24), accessxi.format_probe_dwords(obj, 0x80, 24)));
        accessxi.log_probe_short_text_runs(seq, 'viewhouse.obj', obj, 0x360, 2, 24);
        accessxi.log_probe_pointer_text_targets(seq, 'viewhouse.obj', obj, 0x00, 0x1FC, 32);
    end
    if (accessxi.is_probe_pointer(child)) then
        log_line(('viewhouseprobe seq=%d child d00=%s d80=%s'):fmt(seq, accessxi.format_probe_dwords(child, 0x00, 24), accessxi.format_probe_dwords(child, 0x80, 24)));
        accessxi.log_probe_short_text_runs(seq, 'viewhouse.child', child, 0x360, 2, 24);
        accessxi.log_probe_pointer_text_targets(seq, 'viewhouse.child', child, 0x00, 0x1FC, 32);
    end
    if (accessxi.is_probe_pointer(entry)) then
        log_line(('viewhouseprobe seq=%d entry d00=%s d40=%s'):fmt(seq, accessxi.format_probe_dwords(entry, 0x00, 24), accessxi.format_probe_dwords(entry, 0x40, 24)));
        accessxi.log_probe_short_text_runs(seq, 'viewhouse.entry', entry, 0x240, 2, 18);
        accessxi.log_probe_pointer_text_targets(seq, 'viewhouse.entry', entry, 0x00, 0x13C, 20);
    end

    local target = AshitaCore:GetMemoryManager():GetTarget();
    if (target ~= nil) then
        local shape_count = 0;
        for i = 0, 31 do
            if (shape_count >= 12) then
                break;
            end
            local shape = tonumber(safe_call(function () return target:GetWindowAnkShape(i); end, 0)) or 0;
            if (accessxi.is_probe_pointer(shape)) then
                shape_count = shape_count + 1;
                log_line(('viewhouseprobe seq=%d shape index=%d ptr=0x%08X dwords=%s strings="%s"'):fmt(
                    seq,
                    i,
                    shape,
                    accessxi.format_probe_dwords(shape, 0, 24),
                    accessxi.escape_probe_log_text(accessxi.party_label_probe_text_summary(shape, 0x200))));
                accessxi.log_probe_short_text_runs(seq, ('viewhouse.shape%d'):fmt(i), shape, 0x300, 2, 18);
                accessxi.log_probe_pointer_text_targets(seq, ('viewhouse.shape%d'):fmt(i), shape, 0x00, 0x17C, 18);
            end
        end
    end

    log_line(('viewhouseprobe seq=%d end'):fmt(seq));
    return seq;
end

function accessxi.view_house_menu_speech(menu_name, title, obj, selected, count, page, raw, child, entry)
    menu_name = tostring(menu_name or '');
    if (not menu_name:eq('menu    mogcont', true)) then
        return nil;
    end

    accessxi.log_view_house_menu_probe(menu_name, title, obj, selected, count, page, raw, child, entry, 'native-known');

    local selected_row = tonumber(selected) or 0;
    if (selected_row <= 0) then
        selected_row = read_current_native_menu_index(0x4C);
    end

    local help, help_ptr = accessxi.view_house_native_help_text(entry);
    local label = accessxi.view_house_label_from_native_help(help);
    if (label == '') then
        log_state(('state viewhouse native-missing menu="%s" title="%s" select=%d count=%d page=%d raw=0x%08X child=0x%08X entry=0x%08X helpPtr=0x%08X'):fmt(
            menu_name,
            tostring(title or 'View House'),
            selected_row,
            tonumber(count) or 0,
            tonumber(page) or 0,
            tonumber(raw) or 0,
            tonumber(child) or 0,
            tonumber(entry) or 0,
            tonumber(help_ptr) or 0));
        return nil;
    end

    local container = accessxi.view_house_container_from_native_label(label);
    if (is_storage_bank_container(container)) then
        set_storage_bank_context(container);
    end

    accessxi.last_native_menu_name = menu_name;
    accessxi.last_native_menu_label = label;
    accessxi.last_native_menu_selected = selected_row;
    accessxi.last_native_menu_tick = tick();
    accessxi.current_speech_key = ('view-house-native:%d:0x%08X:0x%08X:%s:%s'):fmt(
        selected_row,
        tonumber(entry) or 0,
        tonumber(help_ptr) or 0,
        label,
        help);
    log_state(('state viewhouse native menu="%s" title="%s" select=%d count=%d container=%d label="%s" help="%s" page=%d raw=0x%08X child=0x%08X entry=0x%08X helpPtr=0x%08X source="entry+40"'):fmt(
        menu_name,
        tostring(title or 'View House'),
        selected_row,
        tonumber(count) or 0,
        container,
        accessxi.escape_probe_log_text(label),
        accessxi.escape_probe_log_text(help),
        tonumber(page) or 0,
        tonumber(raw) or 0,
        tonumber(child) or 0,
        tonumber(entry) or 0,
        tonumber(help_ptr) or 0));
    return ('%s. %s. %s'):fmt(tostring(title or 'View House'), accessxi.sentence_fragment(label), accessxi.sentence_fragment(help));
end

local function storage_bank_summary_speech(container)
    container = is_storage_bank_container(container) and container or accessxi.storage_bank_container;
    if (not is_storage_bank_container(container)) then
        return nil;
    end

    local container_name = inventory_container_names[container] or ('Container %d'):fmt(container);
    local count, max_count = storage_bank_counts(container);
    if (max_count > 0) then
        return ('%s open. %d of %d items.'):fmt(container_name, count, max_count);
    end

    return ('%s open.'):fmt(container_name);
end

local function storage_bank_container_from_selection(selected_index, selected_id)
    local inv = AshitaCore:GetMemoryManager():GetInventory();
    if (inv == nil or selected_index < 0 or not is_valid_inventory_item_id(selected_id)) then
        return -1;
    end

    local matches = T{};
    for container = 1, 16 do
        local max_count = tonumber(safe_call(function () return inv:GetContainerCountMax(container); end, 0)) or 0;
        if (max_count > selected_index) then
            local item = safe_call(function () return inv:GetContainerItem(container, selected_index); end, nil);
            if (item ~= nil and tonumber(item.Id) == selected_id) then
                matches:append(container);
            end
        end
    end

    if (#matches == 0) then
        return -1;
    end

    if (is_storage_bank_container(accessxi.storage_bank_container)) then
        for _, container in ipairs(matches) do
            if (container == accessxi.storage_bank_container) then
                return container;
            end
        end
    end

    return matches[1];
end

local function get_selected_storage_bank_item_info()
    local inv = AshitaCore:GetMemoryManager():GetInventory();
    if (inv == nil) then
        return nil;
    end

    local selected_id = tonumber(safe_call(function () return inv:GetSelectedItemId(); end, 0)) or 0;
    local selected_index = tonumber(safe_call(function () return inv:GetSelectedItemIndex(); end, -1)) or -1;
    local selected_name = clean_login_text(safe_call(function () return inv:GetSelectedItemName(); end, ''));
    if (not is_valid_inventory_item_id(selected_id) or selected_index < 0 or selected_name == '') then
        return nil;
    end

    local container = storage_bank_container_from_selection(selected_index, selected_id);
    if (is_storage_bank_container(container)) then
        set_storage_bank_context(container);
    elseif (is_storage_bank_container(accessxi.storage_bank_container)) then
        container = accessxi.storage_bank_container;
    end

    local item = nil;
    local count = 0;
    local container_count = 0;
    local container_max = 0;
    if (is_storage_bank_container(container)) then
        item = safe_call(function () return inv:GetContainerItem(container, selected_index); end, nil);
        count = tonumber(inventory_item_count(item)) or 0;
        container_count, container_max = storage_bank_counts(container);
    end

    local resource_info = resource_item_info(selected_id);
    local detail_parts = item_static_detail_parts(resource_info);
    for _, part in ipairs(item_dynamic_detail_parts(item, false)) do
        detail_parts:append(part);
    end
    if (not has_charge_detail(detail_parts)) then
        for _, part in ipairs(item_fallback_charge_parts(resource_info)) do
            detail_parts:append(part);
        end
    end

    return T{
        id = selected_id,
        index = selected_index,
        display_slot = -1,
        visible_position = -1,
        container = is_storage_bank_container(container) and container or -1,
        slot = selected_index,
        container_name = is_storage_bank_container(container) and (inventory_container_names[container] or 'Storage') or (accessxi.storage_bank_container_name ~= '' and accessxi.storage_bank_container_name or 'Storage'),
        count = count,
        container_count = container_count,
        container_max = container_max,
        name = selected_name,
        description = resource_info.description,
        detail_parts = detail_parts,
        empty = false,
    };
end

local function log_storage_bank_probe(menu_name, info)
    local now = tick();
    if ((now - (accessxi.last_storage_bank_probe_tick or 0)) < 100) then
        return;
    end
    accessxi.last_storage_bank_probe_tick = now;

    local obj = get_current_menu_object_ptr();
    local inv = AshitaCore:GetMemoryManager():GetInventory();
    local target = AshitaCore:GetMemoryManager():GetTarget();
    local fields = T{};
    if (obj ~= 0) then
        for _, off in ipairs(T{ 0x10, 0x14, 0x18, 0x1C, 0x20, 0x24, 0x28, 0x2C, 0x30, 0x34, 0x38, 0x3C, 0x40, 0x44, 0x48, 0x4C, 0x50, 0x54, 0x58, 0x5C, 0x60, 0x64, 0x68, 0x6C, 0x70, 0x74, 0x78, 0x7C, 0x80 }) do
            local value = read_i32(obj + off);
            if (value ~= nil and value >= -1 and value <= 512) then
                fields:append(('+%02X=%d'):fmt(off, value));
            end
        end
    end

    local selected_id = inv ~= nil and tonumber(safe_call(function () return inv:GetSelectedItemId(); end, 0)) or 0;
    local selected_index = inv ~= nil and tonumber(safe_call(function () return inv:GetSelectedItemIndex(); end, -1)) or -1;
    local selected_name = clean_login_text(inv ~= nil and safe_call(function () return inv:GetSelectedItemName(); end, '') or '');
    local counts = T{};
    if (inv ~= nil) then
        for container = 1, 16 do
            local max_count = tonumber(safe_call(function () return inv:GetContainerCountMax(container); end, 0)) or 0;
            if (max_count > 0) then
                local count = tonumber(safe_call(function () return inv:GetContainerCount(container); end, 0)) or 0;
                counts:append(('%s=%d/%d'):fmt(inventory_container_names[container] or tostring(container), count, max_count));
            end
        end
    end

    local line = ('storage bank probe menu="%s" obj=0x%08X context=%d "%s" ank=%s sub=%s selId=%d selIndex=0x%04X selName="%s" infoContainer=%d infoSlot=%d infoName="%s" counts="%s" fields=%s'):fmt(
        menu_name or '',
        obj,
        accessxi.storage_bank_container or -1,
        accessxi.storage_bank_container_name or '',
        tostring(target ~= nil and safe_call(function () return target:GetWindowAnkNum(); end, -1) or -1),
        tostring(target ~= nil and safe_call(function () return target:GetWindowSub(); end, -1) or -1),
        selected_id,
        math.max(selected_index, 0),
        selected_name,
        info ~= nil and (info.container or -1) or -1,
        info ~= nil and (info.slot or -1) or -1,
        info ~= nil and (info.name or '') or '',
        counts:concat(', '),
        fields:concat(' '));

    if (line ~= accessxi.last_storage_bank_probe_log) then
        accessxi.last_storage_bank_probe_log = line;
        log_line(line);
    end
end

local function selected_storage_option(options)
    for _, off in ipairs(T{ 0x4C, 0x30, 0x34, 0x28, 0x24 }) do
        local selected = read_current_native_menu_index(off);
        if (selected >= 1 and selected <= #options) then
            return selected, off;
        end
    end

    return 0, 0;
end

function accessxi.equipment_storage_option_label_from_help(help)
    help = accessxi.plain_native_menu_help(help or '');
    if (help == '') then
        return '';
    end

    local label = help:match('^Display equipment in your (.+)$') or help:match('^Move an item to your (.+)$') or '';
    label = label:gsub('%.$', '');
    label = accessxi.plain_native_menu_label(label);
    if (label == '') then
        return '';
    end

    if (label:eq('inventory', true)) then
        return 'Inventory';
    elseif (label:eq('Mog Wardrobe', true)) then
        return 'Mog Wardrobe';
    elseif (label:eq('second Mog Wardrobe', true)) then
        return 'Mog Wardrobe 2';
    elseif (label:eq('third Mog Wardrobe', true)) then
        return 'Mog Wardrobe 3';
    elseif (label:eq('fourth Mog Wardrobe', true)) then
        return 'Mog Wardrobe 4';
    elseif (label:eq('fifth Mog Wardrobe', true)) then
        return 'Mog Wardrobe 5';
    elseif (label:eq('sixth Mog Wardrobe', true)) then
        return 'Mog Wardrobe 6';
    elseif (label:eq('seventh Mog Wardrobe', true)) then
        return 'Mog Wardrobe 7';
    elseif (label:eq('eighth Mog Wardrobe', true)) then
        return 'Mog Wardrobe 8';
    end

    return label;
end

function accessxi.equipment_storage_option_resource_ids(menu_name)
    if (menu_name ~= nil and menu_name:eq('menu    mcrmogc', true)) then
        return 'mcrmogc',
            T{ 1069, 1070, 1071, 1072, 1073, 1074, 1075, 1076, 1077, 1078, 1079, 1080, 1081, 1082, 1083, 1084 },
            T{ 1, 2, 9, 3, 4, 5, 6, 7, 8, 10, 11, 12, 13, 14, 15, 16 };
    end

    return 'mnstorag', T{ 803, 804, 993, 994, 995, 1062, 1063, 1064, 1065 };
end

function accessxi.load_equipment_storage_option_rows(menu_name)
    accessxi.equipment_storage_option_rows_by_menu = accessxi.equipment_storage_option_rows_by_menu or {};
    accessxi.equipment_storage_option_rows_tried_by_menu = accessxi.equipment_storage_option_rows_tried_by_menu or {};

    local key, wanted, selected_ids = accessxi.equipment_storage_option_resource_ids(menu_name);
    if (type(accessxi.equipment_storage_option_rows_by_menu[key]) == 'table') then
        return accessxi.equipment_storage_option_rows_by_menu[key];
    end
    if (accessxi.equipment_storage_option_rows_tried_by_menu[key] == true) then
        return nil;
    end
    accessxi.equipment_storage_option_rows_tried_by_menu[key] = true;

    local by_id = {};
    local path = accessxi.dat_index_path();
    local f = io.open(path, 'rb');
    if (f ~= nil) then
        for line in f:lines() do
            local index, text = line:match('^55651\tDmsgTable\tROM\\165\\75%.DAT\t(%d+)\t(.*)$');
            if (index ~= nil) then
                local id = tonumber(index) or -1;
                by_id[id] = tostring(text or ''):gsub('\r', '');
            end
        end
        f:close();
    end

    local rows = T{};
    for row_index, id in ipairs(wanted) do
        local help = accessxi.plain_native_menu_help(by_id[id] or '');
        local label = accessxi.equipment_storage_option_label_from_help(help);
        if (label == '') then
            log_line(('equipment storage option resource missing path="%s" row=%d help="%s"'):fmt(
                path,
                tonumber(id) or -1,
                accessxi.escape_probe_log_text(help)));
            return nil;
        end
        rows:append(T{
            label = label,
            help = help,
            source = ('ROM\\165\\75.DAT:%d'):fmt(tonumber(id) or 0),
            selected_id = selected_ids ~= nil and selected_ids[row_index] or row_index,
        });
    end

    accessxi.equipment_storage_option_rows_by_menu[key] = rows;
    local labels = T{};
    local by_selected = {};
    for _, row in ipairs(rows) do
        labels:append(row.label or '');
        if (row.selected_id ~= nil) then
            by_selected[tonumber(row.selected_id) or -1] = row;
        end
    end
    rows.by_selected = by_selected;
    log_line(('loaded equipment storage option resource key="%s" path="%s" count=%d labels="%s"'):fmt(
        key,
        path,
        #rows,
        accessxi.escape_probe_log_text(labels:concat(', '))));
    return rows;
end

local function equipment_storage_options_speech(menu_name)
    if (not is_equipment_storage_options_menu_name(menu_name)) then
        return nil;
    end

    local obj = get_current_menu_object_ptr();
    local native_count = obj ~= 0 and (tonumber(read_i32(obj + 0x58)) or 0) or 0;
    local struct_count = obj ~= 0 and math.max(tonumber(read_i32(obj + 0x24)) or 0, tonumber(read_i32(obj + 0x28)) or 0, native_count) or native_count;
    local rows = accessxi.load_equipment_storage_option_rows(menu_name);
    if (rows == nil or #rows == 0) then
        return nil;
    end

    local use_selected_ids = menu_name ~= nil and menu_name:eq('menu    mcrmogc', true) and type(rows.by_selected) == 'table';
    local max_options = #rows;
    if (not use_selected_ids and native_count > 0 and native_count < max_options) then
        max_options = native_count;
    end

    local selected = read_current_native_menu_index(0x4C);
    local selected_offset = 0x4C;
    local row = nil;
    if (use_selected_ids) then
        row = rows.by_selected[selected];
        if (row == nil) then
            for _, off in ipairs(T{ 0x30, 0x34, 0x28, 0x24 }) do
                local candidate = read_current_native_menu_index(off);
                if (rows.by_selected[candidate] ~= nil) then
                    selected = candidate;
                    selected_offset = off;
                    row = rows.by_selected[candidate];
                    break;
                end
            end
        end
    elseif (selected >= 1 and selected > max_options and selected <= struct_count) then
        log_state(('state equipment storage-options unproven-row menu="%s" obj=0x%08X selected=%d count=%d structCount=%d proven=%d'):fmt(
            menu_name or '',
            obj,
            selected,
            native_count,
            struct_count,
            max_options));
        return nil;
    elseif (selected < 1 or selected > max_options) then
        selected, selected_offset = selected_storage_option(rows);
    end
    if (selected < 1 or selected > max_options) then
        log_state(('state equipment storage-options missing menu="%s" obj=0x%08X selected=%d count=%d'):fmt(
            menu_name or '',
            obj,
            selected,
            native_count));
        return nil;
    end

    row = row or rows[selected];
    local label = row ~= nil and (row.label or '') or '';
    local help = row ~= nil and (row.help or '') or '';
    local source = row ~= nil and (row.source or '') or '';
    local target = AshitaCore:GetMemoryManager():GetTarget();
    log_state(('state equipment storage-options menu="%s" obj=0x%08X ank=%s sub=%s selected=%d offset=+%02X count=%d structCount=%d proven=%d label="%s" help="%s" source="%s"'):fmt(
        menu_name or '',
        obj,
        tostring(target ~= nil and safe_call(function () return target:GetWindowAnkNum(); end, -1) or -1),
        tostring(target ~= nil and safe_call(function () return target:GetWindowSub(); end, -1) or -1),
        selected,
        selected_offset,
        native_count,
        struct_count,
        #rows,
        accessxi.escape_probe_log_text(label),
        accessxi.escape_probe_log_text(help),
        accessxi.escape_probe_log_text(source)));

    accessxi.current_speech_key = ('equipment-storage-options:%s:%d:%d:%s'):fmt(menu_name or '', selected, native_count, label);
    return ('Storage options. %s.'):fmt(label);
end

local function current_selected_inventory_name()
    local inv = AshitaCore:GetMemoryManager():GetInventory();
    if (inv == nil) then
        return '';
    end

    local selected_id = tonumber(safe_call(function () return inv:GetSelectedItemId(); end, 0)) or 0;
    local selected_name = clean_login_text(safe_call(function () return inv:GetSelectedItemName(); end, ''));
    if (is_valid_inventory_item_id(selected_id)) then
        local resource_info = resource_item_info(selected_id);
        if (resource_info.name ~= '') then
            return resource_info.name;
        end
    end

    return selected_name;
end

local function log_item_use_probe(menu_name, selected, selected_offset, label)
    local now = tick();
    if ((now - (accessxi.last_item_use_probe_tick or 0)) < 100) then
        return;
    end
    accessxi.last_item_use_probe_tick = now;

    local obj = get_current_menu_object_ptr();
    local inv = AshitaCore:GetMemoryManager():GetInventory();
    local target = AshitaCore:GetMemoryManager():GetTarget();
    local fields = T{};
    if (obj ~= 0) then
        for _, off in ipairs(T{ 0x10, 0x14, 0x18, 0x1C, 0x20, 0x24, 0x28, 0x2C, 0x30, 0x34, 0x38, 0x3C, 0x40, 0x44, 0x48, 0x4C, 0x50, 0x54, 0x58, 0x5C, 0x60, 0x64 }) do
            local value = read_i32(obj + off);
            if (value ~= nil and value >= -1 and value <= 512) then
                fields:append(('+%02X=%d'):fmt(off, value));
            end
        end
    end

    local selected_id = inv ~= nil and tonumber(safe_call(function () return inv:GetSelectedItemId(); end, 0)) or 0;
    local selected_index = inv ~= nil and tonumber(safe_call(function () return inv:GetSelectedItemIndex(); end, -1)) or -1;
    local selected_name = clean_login_text(inv ~= nil and safe_call(function () return inv:GetSelectedItemName(); end, '') or '');
    local line = ('item use probe menu="%s" obj=0x%08X ank=%s sub=%s selected=%d offset=+%02X label="%s" selId=%d selIndex=0x%04X selName="%s" fields=%s'):fmt(
        menu_name or '',
        obj,
        tostring(target ~= nil and safe_call(function () return target:GetWindowAnkNum(); end, -1) or -1),
        tostring(target ~= nil and safe_call(function () return target:GetWindowSub(); end, -1) or -1),
        selected or 0,
        selected_offset or 0,
        label or '',
        selected_id,
        math.max(selected_index, 0),
        selected_name,
        fields:concat(' '));

    if (line ~= accessxi.last_item_use_probe_log) then
        accessxi.last_item_use_probe_log = line;
        log_line(line);
    end
end

local function item_use_action_speech(menu_name)
    if (menu_name == nil or not menu_name:eq('menu    iuse', true)) then
        return nil;
    end

    local selected, selected_offset = selected_storage_option(item_use_options);
    local label = selected > 0 and item_use_options[selected] or '';
    log_item_use_probe(menu_name, selected, selected_offset, label);
    if (label == '') then
        accessxi.current_item_use_action_label = '';
        accessxi.current_item_use_action_selected = 0;
        accessxi.current_item_use_action_offset = 0;
        accessxi.current_item_use_item_name = '';
        accessxi.current_item_use_action_tick = 0;
        return nil;
    end

    local item_name = current_selected_inventory_name();
    accessxi.current_item_use_action_label = label;
    accessxi.current_item_use_action_selected = selected;
    accessxi.current_item_use_action_offset = selected_offset;
    accessxi.current_item_use_item_name = item_name;
    accessxi.current_item_use_action_tick = tick();
    if (item_name ~= '') then
        return ('%s. Item menu. %s.'):fmt(item_name, label);
    end

    return ('Item menu. %s.'):fmt(label);
end

local function item_target_options()
    local party = AshitaCore:GetMemoryManager():GetParty();
    local options = T{};
    if (party ~= nil) then
        for i = 0, 17 do
            local active = tonumber(safe_call(function () return party:GetMemberIsActive(i); end, 0)) or 0;
            local name = clean_login_text(safe_call(function () return party:GetMemberName(i); end, ''));
            if (name ~= '' and (active ~= 0 or i == 0)) then
                options:append(name);
            end
        end
    end

    return options;
end

local function log_item_target_probe(menu_name, selected, selected_offset, label, options)
    local now = tick();
    if ((now - (accessxi.last_item_target_probe_tick or 0)) < 100) then
        return;
    end
    accessxi.last_item_target_probe_tick = now;

    local obj = get_current_menu_object_ptr();
    local target = AshitaCore:GetMemoryManager():GetTarget();
    local fields = T{};
    if (obj ~= 0) then
        for _, off in ipairs(T{ 0x10, 0x14, 0x18, 0x1C, 0x20, 0x24, 0x28, 0x2C, 0x30, 0x34, 0x38, 0x3C, 0x40, 0x44, 0x48, 0x4C, 0x50, 0x54, 0x58, 0x5C, 0x60, 0x64 }) do
            local value = read_i32(obj + off);
            if (value ~= nil and value >= -1 and value <= 512) then
                fields:append(('+%02X=%d'):fmt(off, value));
            end
        end
    end

    local line = ('item target probe menu="%s" obj=0x%08X ank=%s sub=%s selected=%d offset=+%02X label="%s" options="%s" fields=%s'):fmt(
        menu_name or '',
        obj,
        tostring(target ~= nil and safe_call(function () return target:GetWindowAnkNum(); end, -1) or -1),
        tostring(target ~= nil and safe_call(function () return target:GetWindowSub(); end, -1) or -1),
        selected or 0,
        selected_offset or 0,
        label or '',
        options ~= nil and options:concat(', ') or '',
        fields:concat(' '));

    if (line ~= accessxi.last_item_target_probe_log) then
        accessxi.last_item_target_probe_log = line;
        log_line(line);
    end
end

local function item_target_speech(menu_name)
    if (menu_name == nil or not menu_name:eq('menu    mcr1pall', true)) then
        return nil;
    end

    local options = item_target_options();
    local selected, selected_offset = selected_storage_option(options);
    local label = selected > 0 and options[selected] or '';
    log_item_target_probe(menu_name, selected, selected_offset, label, options);
    if (label == '') then
        return nil;
    end

    return ('Item target. %s.'):fmt(label);
end

local function inventory_item_info_speech(info, suppress_count)
    if (info == nil) then
        return nil;
    end

    if (info.empty) then
        return ('%s empty.'):fmt(info.container_name);
    end

    local count = tonumber(raw_table_value(info, 'count', 0)) or 0;
    local price = tonumber(raw_table_value(info, 'price', 0)) or 0;
    local parts = T{ info.name };
    if ((not suppress_count) and (not info.empty) and count > 1) then
        parts:append(('Quantity %d'):fmt(count));
    end
    if (price > 0) then
        parts:append(('Price %s gil'):fmt(accessxi.format_currency_number(price)));
    end
    if (info.detail_parts ~= nil) then
        for _, part in ipairs(info.detail_parts) do
            if (part ~= nil and part ~= '') then
                parts:append(part);
            end
        end
    end
    if (info.description ~= nil and info.description ~= '') then
        parts:append(info.description);
    end

    return join_speech_parts(parts);
end

function accessxi.objective_item_name_for_id(item_id)
    item_id = tonumber(item_id) or 0;
    if (item_id <= 0) then return ''; end
    local info = resource_item_info(item_id);
    return type(info) == 'table' and nav_clean_field(info.name or '') or '';
end

function accessxi.refresh_objective_inventory_state(reason)
    local player = type(accessxi.current_player_name) == 'function'
        and tostring(accessxi.current_player_name() or '') or '';
    local identity = type(accessxi.current_player_identity) == 'function'
        and tostring(accessxi.current_player_identity() or ''):lower() or '';
    local epoch = type(accessxi.current_objective_session_epoch) == 'function'
        and (tonumber(accessxi.current_objective_session_epoch()) or 0) or 0;
    if (player == '' or identity == '') then
        return false, false;
    end
    local previous_counts = type(accessxi.objective_inventory_counts) == 'table'
        and accessxi.objective_inventory_counts or {};
    local previous_complete = tostring(accessxi.inventory_packet_source or '')
            == 'native-inventory'
        and tostring(accessxi.inventory_packet_identity or ''):lower() == identity
        and tonumber(accessxi.inventory_packet_session_epoch) == epoch;

    local manager_ok, manager = pcall(function () return AshitaCore:GetMemoryManager(); end);
    local inventory_ok, inventory = false, nil;
    if (manager_ok and manager ~= nil) then
        inventory_ok, inventory = pcall(function () return manager:GetInventory(); end);
    end
    if (not manager_ok or manager == nil or not inventory_ok or inventory == nil) then
        log_line(('objective inventory scan unavailable reason="%s" stage="inventory"'):fmt(
            accessxi.escape_probe_log_text(reason or 'refresh')));
        return false, false;
    end

    local max_ok, max_count = pcall(function () return inventory:GetContainerCountMax(0); end);
    max_count = tonumber(max_count);
    if (not max_ok or max_count == nil or max_count < 0 or max_count > 256
        or max_count ~= math.floor(max_count)) then
        log_line(('objective inventory scan unavailable reason="%s" stage="capacity"'):fmt(
            accessxi.escape_probe_log_text(reason or 'refresh')));
        return false, false;
    end

    local counts = {};
    for slot = 1, max_count do
        local item_ok, item = pcall(function () return inventory:GetContainerItem(0, slot); end);
        if (not item_ok) then
            log_line(('objective inventory scan unavailable reason="%s" stage="slot" slot=%d'):fmt(
                accessxi.escape_probe_log_text(reason or 'refresh'), slot));
            return false, false;
        end
        local id_ok, item_id = pcall(function () return tonumber(item.Id or item.id) or 0; end);
        item_id = id_ok and item_id or 0;
        local count = tonumber(inventory_item_count(item)) or 0;
        if (item_id > 0 and item_id <= 65535 and count > 0) then
            counts[item_id] = (tonumber(counts[item_id]) or 0) + math.floor(count);
        end
    end

    local ids = {};
    for item_id in pairs(counts) do ids[#ids + 1] = item_id; end
    table.sort(ids);
    local key_parts = { identity, tostring(epoch) };
    for _, item_id in ipairs(ids) do
        key_parts[#key_parts + 1] = ('%d=%d'):fmt(item_id, counts[item_id]);
    end
    local key = table.concat(key_parts, ';');
    local changed = key ~= tostring(accessxi.inventory_packet_key or '')
        or tostring(accessxi.inventory_packet_source or '') ~= 'native-inventory'
        or tostring(accessxi.inventory_packet_identity or ''):lower() ~= identity;

    accessxi.objective_inventory_counts = counts;
    accessxi.inventory_packet_player = player;
    accessxi.inventory_packet_identity = identity;
    accessxi.inventory_packet_session_epoch = epoch;
    accessxi.inventory_packet_source = 'native-inventory';
    accessxi.inventory_packet_key = key;
    local now = tick();
    accessxi.inventory_packet_tick = now;
    if (previous_complete and type(accessxi.nav_mission_quest_reduce_signal) == 'function') then
        local world_id = tonumber(accessxi.current_player_world_id()) or 0;
        if (world_id > 0) then
            for _, item_id in ipairs(ids) do
                local before_count = math.max(0,
                    tonumber(previous_counts[item_id]) or 0);
                local after_count = math.max(0, tonumber(counts[item_id]) or 0);
                if (after_count > before_count) then
                    local item_name = type(accessxi.objective_item_name_for_id) == 'function'
                        and tostring(accessxi.objective_item_name_for_id(item_id) or '') or '';
                    if (item_name ~= '') then
                        if (tonumber(accessxi.objective_signal_session_epoch) ~= epoch) then
                            accessxi.objective_signal_session_epoch = epoch;
                            accessxi.objective_signal_sequence = 0;
                        end
                        local sequence = (tonumber(accessxi.objective_signal_sequence) or 0) + 1;
                        accessxi.objective_signal_sequence = sequence;
                        pcall(accessxi.nav_mission_quest_reduce_signal, {
                            kind = 'inventory-delta', item_id = item_id,
                            item_name = item_name, before_count = before_count,
                            after_count = after_count, snapshot_complete = true,
                            character_identity = identity, world_id = world_id,
                            session_epoch = epoch, sequence = sequence,
                            inventory_sequence = sequence, tick = now,
                            corpus_revision = tonumber(accessxi.nav_catalog_revision) or 0,
                        });
                    end
                end
            end
        end
    end
    if (changed) then
        log_line(('objective inventory changed reason="%s" items=%d key="%s"'):fmt(
            accessxi.escape_probe_log_text(reason or 'refresh'),
            #ids,
            accessxi.escape_probe_log_text(key)));
    end
    return changed, true;
end

function accessxi.objective_inventory_count(item_id)
    item_id = tonumber(item_id) or 0;
    local identity = type(accessxi.current_player_identity) == 'function'
        and tostring(accessxi.current_player_identity() or ''):lower() or '';
    local epoch = type(accessxi.current_objective_session_epoch) == 'function'
        and (tonumber(accessxi.current_objective_session_epoch()) or 0) or 0;
    if (item_id <= 0 or identity == ''
        or tostring(accessxi.inventory_packet_source or '') ~= 'native-inventory'
        or tostring(accessxi.inventory_packet_identity or ''):lower() ~= identity
        or tonumber(accessxi.inventory_packet_session_epoch) ~= epoch) then
        return 0;
    end
    return math.max(0, tonumber((accessxi.objective_inventory_counts or {})[item_id]) or 0);
end

function accessxi.objective_inventory_count_by_name(name)
    if (type(accessxi.resource_item_info_by_name) ~= 'function') then
        return 0, nil;
    end
    local ok, info = pcall(accessxi.resource_item_info_by_name, tostring(name or ''));
    local item_id = ok and type(info) == 'table'
        and (tonumber(info.id or info.Id) or 0) or 0;
    if (item_id <= 0) then
        return 0, nil;
    end
    return accessxi.objective_inventory_count(item_id), item_id;
end

function accessxi.schedule_objective_inventory_refresh(reason, delay_ms)
    accessxi.objective_inventory_refresh_pending = true;
    accessxi.objective_inventory_refresh_reason = tostring(reason or 'inventory-packet');
    accessxi.objective_inventory_refresh_tick = tick() + math.max(0, tonumber(delay_ms) or 100);
end

function accessxi.poll_objective_inventory_refresh(now)
    if (accessxi.objective_inventory_refresh_pending ~= true
        or (tonumber(now) or tick()) < (tonumber(accessxi.objective_inventory_refresh_tick) or 0)) then
        return false;
    end
    accessxi.objective_inventory_refresh_pending = false;
    local changed, available = accessxi.refresh_objective_inventory_state(
        accessxi.objective_inventory_refresh_reason or 'inventory-packet');
    if (changed and available and type(accessxi.on_objective_inventory_changed) == 'function') then
        local ok, message = pcall(
            accessxi.on_objective_inventory_changed,
            accessxi.objective_inventory_refresh_reason or 'inventory-packet');
        if (not ok) then
            log_line(('objective inventory refresh handler failed reason="%s"'):fmt(
                accessxi.escape_probe_log_text(message or 'unknown')));
        end
    end
    return changed == true;
end

function accessxi.capture_objective_inventory_packet(e)
    local packet_id = tonumber(type(e) == 'table' and e.id or nil) or -1;
    if (packet_id == 0x001D or packet_id == 0x001E
        or packet_id == 0x001F or packet_id == 0x0020
        or packet_id == 0x0037 or packet_id == 0x0050 or packet_id == 0x0051
        or packet_id == 0x0116 or packet_id == 0x0117) then
        accessxi.schedule_objective_inventory_refresh(('packet-0x%03X'):fmt(packet_id), 100);
    end
end

function accessxi.objective_entity_name_for_server_id(server_id)
    if (type(accessxi.combat_entity_hp_summary_for_server) ~= 'function') then
        return '';
    end
    local _, _, name = accessxi.combat_entity_hp_summary_for_server(server_id);
    return clean_probe_text(name);
end

-- Raw packets are translated directly into one typed reducer signal.  They do
-- not also call accessxi.nav_mission_quest_observe_event_packet, because that
-- legacy compatibility bridge feeds the same reducer and would double count.
function accessxi.capture_mission_quest_event_packet(e, direction)
    if (e == nil or type(accessxi.nav_mission_quest_reduce_signal) ~= 'function') then
        return false;
    end
    local packet_id = tonumber(e.id) or -1;
    local data = e.data_modified or e.data or '';
    direction = tostring(direction or ''):lower();
    local kind = '';
    local target_server_id = 0;
    local target_index = 0;
    local zone_id = 0;
    local event_id = 0;
    local menu_id = 0;
    local destination_x, destination_z, destination_y = nil, nil, nil;
    local function packet_float32(index)
        local bits = accessxi.packet_u32(data, index);
        local sign = bits >= 0x80000000 and -1 or 1;
        if (bits >= 0x80000000) then bits = bits - 0x80000000; end
        local exponent = math.floor(bits / 0x800000);
        local mantissa = bits % 0x800000;
        if (exponent == 0) then
            return sign * (mantissa / 0x800000) * (2 ^ -126);
        end
        if (exponent >= 255) then return nil; end
        return sign * (1 + (mantissa / 0x800000)) * (2 ^ (exponent - 127));
    end
    if (direction == 'in' and packet_id == 0x0034) then
        kind = 'interaction-start';
        target_server_id = accessxi.packet_u32(data, 0x04 + 1);
        zone_id = accessxi.packet_u16(data, 0x2A + 1);
        event_id = accessxi.packet_u16(data, 0x2C + 1);
    elseif (direction == 'in' and packet_id == 0x0032) then
        kind = 'interaction-start';
        target_server_id = accessxi.packet_u32(data, 0x04 + 1);
        zone_id = accessxi.packet_u16(data, 0x0A + 1);
        event_id = accessxi.packet_u16(data, 0x0C + 1);
    elseif (direction == 'out' and packet_id == 0x005B) then
        kind = 'interaction-finish';
        target_server_id = accessxi.packet_u32(data, 0x04 + 1);
        zone_id = accessxi.packet_u16(data, 0x10 + 1);
        event_id = accessxi.packet_u16(data, 0x12 + 1);
    elseif (direction == 'out' and packet_id == 0x005C) then
        kind = 'transport-request';
        target_server_id = accessxi.packet_u32(data, 0x10 + 1);
        zone_id = accessxi.packet_u16(data, 0x18 + 1);
        menu_id = accessxi.packet_u16(data, 0x1A + 1);
        target_index = accessxi.packet_u16(data, 0x1C + 1);
        destination_x = packet_float32(0x04 + 1);
        destination_z = packet_float32(0x08 + 1);
        destination_y = packet_float32(0x0C + 1);
    else
        return false;
    end
    if (menu_id <= 0) then menu_id = event_id; end
    if (target_server_id <= 0 or zone_id <= 0 or menu_id <= 0) then
        return false;
    end
    local identity = tostring(accessxi.current_player_identity() or ''):lower();
    local world_id = tonumber(accessxi.current_player_world_id()) or 0;
    local session_epoch = tonumber(accessxi.current_objective_session_epoch()) or 0;
    if (identity == '' or world_id <= 0 or session_epoch <= 0) then return false; end
    if (tonumber(accessxi.objective_signal_session_epoch) ~= session_epoch) then
        accessxi.objective_signal_session_epoch = session_epoch;
        accessxi.objective_signal_sequence = 0;
    end
    local sequence = (tonumber(accessxi.objective_signal_sequence) or 0) + 1;
    accessxi.objective_signal_sequence = sequence;
    local now = tick();
    local target_name = type(accessxi.objective_entity_name_for_server_id) == 'function'
        and tostring(accessxi.objective_entity_name_for_server_id(target_server_id) or '') or '';
    local signal = {
        kind = kind, packet_id = packet_id, direction = direction,
        target_server_id = target_server_id, target_index = target_index,
        target_name = target_name, zone_id = zone_id,
        event_id = event_id, menu_id = menu_id,
        destination_x = destination_x, destination_z = destination_z,
        destination_y = destination_y,
        character_identity = identity, world_id = world_id,
        session_epoch = session_epoch, sequence = sequence, tick = now,
        corpus_revision = tonumber(accessxi.nav_catalog_revision) or 0,
    };
    local ok, result = pcall(accessxi.nav_mission_quest_reduce_signal, signal);
    if (ok and result == true and kind == 'transport-request') then
        accessxi.objective_transport_target_server_id = target_server_id;
        accessxi.objective_transport_menu_id = menu_id;
        accessxi.objective_transport_request_sequence = sequence;
    end
    if (not ok) then
        log_line(('objective event correlation failed packet=0x%03X reason="%s"'):fmt(
            packet_id,
            accessxi.escape_probe_log_text(tostring(result or 'unknown'))));
        return false;
    end
    return result == true;
end

function accessxi.on_objective_inventory_changed(reason)
    if (type(accessxi.on_mission_quest_state_changed) == 'function') then
        return accessxi.on_mission_quest_state_changed('objective', reason or 'inventory-changed');
    end
    return false, false;
end

function accessxi.current_inventory_gil()
    local inv = AshitaCore:GetMemoryManager():GetInventory();
    if (inv == nil) then
        return nil;
    end

    local item = safe_call(function () return inv:GetContainerItem(0, 0); end, nil);
    if (item == nil) then
        return nil;
    end

    return inventory_item_count(item);
end

function accessxi.trade_moneyctr_shape_summary(target)
    if (target == nil) then
        return '';
    end

    local parts = T{};
    for i = 0, 31 do
        local shape = tonumber(safe_call(function () return target:GetWindowAnkShape(i); end, 0)) or 0;
        if (shape ~= 0) then
            parts:append(('%d=0x%08X'):fmt(i, shape));
        end
    end

    return parts:concat(' | ');
end

function accessxi.trade_moneyctr_runtime_summary(ptr, current_gil)
    ptr = tonumber(ptr) or 0;
    if (not accessxi.is_probe_pointer(ptr)) then
        return '';
    end

    current_gil = tonumber(current_gil) or -1;
    local d32 = T{};
    local h16 = T{};
    local u8s = T{};
    for off = 0, 0x27C, 4 do
        local value = read_u32(ptr + off);
        if (value ~= nil and (value <= 32 or value == current_gil or (value >= 100 and value <= 99999999))) then
            append_limited(d32, ('+%03X=%d'):fmt(off, value), 80);
        end
    end
    for off = 0, 0x27E, 2 do
        local value = read_u16(ptr + off);
        if (value ~= nil and value <= 999) then
            append_limited(h16, ('+%03X=%d'):fmt(off, value), 96);
        end
    end
    for off = 0, 0x27F do
        local value = read_u8(ptr + off);
        if (value ~= nil and value <= 15) then
            append_limited(u8s, ('+%03X=%d'):fmt(off, value), 96);
        end
    end

    return ('d32=%s h16=%s u8=%s raw0=%s raw100=%s raw200=%s'):fmt(
        d32:concat(' '),
        h16:concat(' '),
        u8s:concat(' '),
        accessxi.format_probe_bytes(ptr, 0x00, 0x50),
        accessxi.format_probe_bytes(ptr, 0x100, 0x50),
        accessxi.format_probe_bytes(ptr, 0x200, 0x50));
end

function accessxi.trade_moneyctr_pointer_summary(ptr)
    ptr = tonumber(ptr) or 0;
    if (not accessxi.is_probe_pointer(ptr)) then
        return '';
    end

    local parts = T{};
    for off = 0, 0x1FC, 4 do
        local child = read_u32(ptr + off) or 0;
        if (accessxi.is_probe_pointer(child)) then
            local ascii = accessxi.probe_runs_to_text(accessxi.collect_probe_ascii_runs(child, 0x120, 2, 4));
            append_limited(parts, ('+%03X->0x%08X d=%s b=%s a="%s"'):fmt(
                off,
                child,
                accessxi.format_probe_dwords(child, 0x00, 8),
                accessxi.format_probe_bytes(child, 0x00, 0x30),
                accessxi.escape_probe_log_text(ascii)), 12);
        end
    end
    return parts:concat(' | ');
end

function accessxi.trade_moneyctr_digit_runs(ptr, length, limit)
    ptr = tonumber(ptr) or 0;
    if (not accessxi.is_probe_pointer(ptr)) then
        return '';
    end

    length = tonumber(length) or 0;
    limit = tonumber(limit) or 12;
    local parts = T{};
    local run = T{};
    local run_start = 0;

    for off = 0, length do
        local byte_value = off < length and read_u8(ptr + off) or nil;
        if (byte_value ~= nil and byte_value >= 0x30 and byte_value <= 0x39) then
            if (#run == 0) then
                run_start = off;
            end
            run:append(string.char(byte_value));
        else
            if (#run > 0) then
                parts:append(('+%03X="%s"'):fmt(run_start, run:concat('')));
                if (#parts >= limit) then
                    return parts:concat(' ');
                end
            end
            run = T{};
        end
    end

    return parts:concat(' ');
end

function accessxi.trade_moneyctr_small_values(ptr, current_gil)
    ptr = tonumber(ptr) or 0;
    if (not accessxi.is_probe_pointer(ptr)) then
        return '';
    end

    current_gil = tonumber(current_gil) or -1;
    local parts = T{};
    for off = 0, 0x1FC, 4 do
        local value = read_u32(ptr + off);
        if (value ~= nil and (value == current_gil or (value >= 0 and value <= 99999999))) then
            append_limited(parts, ('+%03X=%d'):fmt(off, value), 64);
        end
    end
    return parts:concat(' ');
end

function accessxi.log_trade_moneyctr_target_probe(label, ptr, current_gil, key_name)
    ptr = tonumber(ptr) or 0;
    if (not accessxi.is_probe_pointer(ptr)) then
        return;
    end

    local ascii = accessxi.probe_runs_to_text(accessxi.collect_probe_ascii_runs(ptr, 0x220, 2, 8));
    local utf16 = accessxi.probe_runs_to_text(accessxi.collect_probe_utf16_runs(ptr, 0x220, 2, 8));
    local ffxi16 = '';
    if (accessxi.collect_probe_ffxi_utf16_runs ~= nil) then
        ffxi16 = accessxi.probe_runs_to_text(accessxi.collect_probe_ffxi_utf16_runs(ptr, 0x220, 2, 8));
    end
    log_state(('state trade moneyctr deep key="%s" label="%s" ptr=0x%08X small="%s" digits="%s" d0="%s" d40="%s" d80="%s" d100="%s" b0="%s" b80="%s" ascii="%s" utf16="%s" ffxi16="%s"'):fmt(
        accessxi.escape_probe_log_text(key_name or ''),
        accessxi.escape_probe_log_text(label or ''),
        ptr,
        accessxi.escape_probe_log_text_wide(accessxi.trade_moneyctr_small_values(ptr, current_gil)),
        accessxi.escape_probe_log_text_wide(accessxi.trade_moneyctr_digit_runs(ptr, 0x220, 16)),
        accessxi.escape_probe_log_text_wide(accessxi.format_probe_dwords(ptr, 0x00, 16)),
        accessxi.escape_probe_log_text_wide(accessxi.format_probe_dwords(ptr, 0x40, 16)),
        accessxi.escape_probe_log_text_wide(accessxi.format_probe_dwords(ptr, 0x80, 16)),
        accessxi.escape_probe_log_text_wide(accessxi.format_probe_dwords(ptr, 0x100, 16)),
        accessxi.escape_probe_log_text_wide(accessxi.format_probe_bytes(ptr, 0x00, 0x40)),
        accessxi.escape_probe_log_text_wide(accessxi.format_probe_bytes(ptr, 0x80, 0x40)),
        accessxi.escape_probe_log_text_wide(ascii),
        accessxi.escape_probe_log_text_wide(utf16),
        accessxi.escape_probe_log_text_wide(ffxi16)));
end

function accessxi.log_trade_moneyctr_deep_probe(menu_name, obj, entry, current_gil, key_name)
    obj = tonumber(obj) or 0;
    entry = tonumber(entry) or 0;
    local seen = T{};
    local count = 0;

    local function add(label, ptr)
        ptr = tonumber(ptr) or 0;
        if (not accessxi.is_probe_pointer(ptr) or seen[ptr] == true) then
            return;
        end
        seen[ptr] = true;
        count = count + 1;
        accessxi.log_trade_moneyctr_target_probe(label, ptr, current_gil, key_name);
    end

    log_state(('state trade moneyctr deep-start key="%s" menu="%s" obj=0x%08X entry=0x%08X currentGil=%d'):fmt(
        accessxi.escape_probe_log_text(key_name or ''),
        accessxi.escape_probe_log_text(menu_name or ''),
        obj,
        entry,
        tonumber(current_gil) or -1));
    add('obj', obj);
    add('entry', entry);

    if (accessxi.is_probe_pointer(obj)) then
        for _, off in ipairs(T{ 0x04, 0x08, 0x0C, 0x10, 0x14, 0x18, 0x1C, 0x20, 0x34, 0x38, 0x3C, 0x40, 0x44, 0x50, 0x58 }) do
            add(('obj+%03X'):fmt(off), read_u32(obj + off) or 0);
        end
    end

    if (accessxi.is_probe_pointer(entry)) then
        for _, off in ipairs(T{ 0x04, 0x08, 0x0C, 0x14, 0x18, 0x38, 0x3C, 0x40, 0x44, 0x4C, 0x50, 0x54 }) do
            add(('entry+%03X'):fmt(off), read_u32(entry + off) or 0);
        end
    end

    log_state(('state trade moneyctr deep-end key="%s" count=%d'):fmt(
        accessxi.escape_probe_log_text(key_name or ''),
        count));
end

function accessxi.trade_moneyctr_native_amount(obj, current_gil)
    obj = tonumber(obj) or 0;
    if (not accessxi.is_probe_pointer(obj)) then
        return nil, '';
    end

    local owner = read_u32(obj + 0x0C) or 0;
    if (not accessxi.is_probe_pointer(owner)) then
        return nil, '';
    end

    local value = read_u32(owner + 0x28);
    if (value == nil) then
        return nil, '';
    end

    value = tonumber(value) or 0;
    current_gil = tonumber(current_gil) or nil;
    if (value < 0 or value > 99999999) then
        return nil, '';
    end
    if (current_gil ~= nil and current_gil >= 0 and value > current_gil) then
        return nil, '';
    end

    return value, ('obj+00C(0x%08X)+028'):fmt(owner);
end

function accessxi.trade_moneyctr_owner_ptr(obj)
    obj = tonumber(obj) or 0;
    if (not accessxi.is_probe_pointer(obj)) then
        return 0;
    end

    local owner = read_u32(obj + 0x0C) or 0;
    if (not accessxi.is_probe_pointer(owner)) then
        return 0;
    end
    return owner;
end

function accessxi.log_trade_moneyctr_owner_probe(obj, key_name)
    local owner = accessxi.trade_moneyctr_owner_ptr(obj);
    if (owner == 0) then
        return;
    end

    local parts = T{};
    for off = 0x00, 0x140, 4 do
        local value = read_u32(owner + off);
        if (value ~= nil and value >= 0 and value <= 99999999) then
            parts:append(('+%03X=%d'):fmt(off, value));
        end
    end
    local key = ('%s:%08X:%s'):fmt(key_name or '', owner, parts:concat(' '));
    if (key == tostring(accessxi.trade_moneyctr_owner_probe_last_key or '')) then
        return;
    end
    accessxi.trade_moneyctr_owner_probe_last_key = key;
    log_state(('state trade moneyctr owner key="%s" ptr=0x%08X values="%s" d0="%s" d40="%s" d80="%s" dC0="%s" d100="%s"'):fmt(
        accessxi.escape_probe_log_text(key_name or ''),
        owner,
        accessxi.escape_probe_log_text_wide(parts:concat(' ')),
        accessxi.escape_probe_log_text_wide(accessxi.format_probe_dwords(owner, 0x00, 16)),
        accessxi.escape_probe_log_text_wide(accessxi.format_probe_dwords(owner, 0x40, 16)),
        accessxi.escape_probe_log_text_wide(accessxi.format_probe_dwords(owner, 0x80, 16)),
        accessxi.escape_probe_log_text_wide(accessxi.format_probe_dwords(owner, 0xC0, 16)),
        accessxi.escape_probe_log_text_wide(accessxi.format_probe_dwords(owner, 0x100, 16))));
end

function accessxi.selected_trade_moneyctr_speech(menu_name)
    local target = AshitaCore:GetMemoryManager():GetTarget();
    local ank_num = target ~= nil and (tonumber(safe_call(function () return target:GetWindowAnkNum(); end, -1)) or -1) or -1;
    local ank_x = target ~= nil and (tonumber(safe_call(function () return target:GetWindowAnkX(); end, -1)) or -1) or -1;
    local ank_y = target ~= nil and (tonumber(safe_call(function () return target:GetWindowAnkY(); end, -1)) or -1) or -1;
    local amount = target ~= nil and (tonumber(safe_call(function () return target:GetWindowSub(); end, 0)) or 0) or 0;
    local sub_x = target ~= nil and (tonumber(safe_call(function () return target:GetWindowSubAnkX(); end, -1)) or -1) or -1;
    local sub_y = target ~= nil and (tonumber(safe_call(function () return target:GetWindowSubAnkY(); end, -1)) or -1) or -1;
    local current_gil = accessxi.current_inventory_gil();
    local window_name = accessxi.trade_handover_target_name();
    local obj = get_current_menu_object_ptr();
    local entry = accessxi.is_probe_pointer(obj) and (read_u32(obj + 0x08) or 0) or 0;
    local native_amount, native_amount_source = accessxi.trade_moneyctr_native_amount(obj, current_gil);
    if (native_amount ~= nil) then
        amount = native_amount;
    end

    if (current_gil ~= nil and amount > current_gil) then
        amount = current_gil;
    end
    accessxi.trade_handover_gil_amount = amount;
    accessxi.trade_handover_gil_amount_tick = tick();

    accessxi.current_speech_key = ('trade-moneyctr:%s:%d:%d:%s'):fmt(
        menu_name or '',
        amount,
        tonumber(current_gil) or -1,
        window_name or '');
    local log_key = ('%s:%d:%d:%s:%s'):fmt(menu_name or '', amount, tonumber(current_gil) or -1, window_name or '', native_amount_source or '');
    if (log_key ~= tostring(accessxi.trade_moneyctr_last_log_key or '')) then
        accessxi.trade_moneyctr_last_log_key = log_key;
        log_state(('state trade moneyctr menu="%s" ank=%d amount=%d source="%s" currentGil=%d target="%s"'):fmt(
            menu_name or '',
            ank_num,
            amount,
            accessxi.escape_probe_log_text(native_amount_source or ''),
            tonumber(current_gil) or -1,
            accessxi.escape_probe_log_text(window_name or '')));
    end
    local parts = T{};
    if (window_name ~= '') then
        parts:append(('Trade with %s'):fmt(window_name));
    else
        parts:append('Trade gil');
    end
    parts:append(('Amount %d gil'):fmt(amount));
    if (current_gil ~= nil) then
        parts:append(('Available %d gil'):fmt(current_gil));
    end

    return join_speech_parts(parts);
end

function accessxi.moneyctr_key_name(key)
    key = tonumber(key) or 0;
    if (key == VK_LEFT) then
        return 'Left';
    elseif (key == VK_RIGHT) then
        return 'Right';
    elseif (key == VK_UP) then
        return 'Up';
    elseif (key == VK_DOWN) then
        return 'Down';
    elseif (key == VK_RETURN) then
        return 'Enter';
    elseif (key == VK_ESCAPE) then
        return 'Escape';
    end
    return '';
end

function accessxi.queue_trade_moneyctr_key_read(key)
    local key_name = accessxi.moneyctr_key_name(key);
    if (key_name == '') then
        return false;
    end
    if (not tostring(get_menu_name() or ''):eq('menu    moneyctr', true)) then
        return false;
    end

    accessxi.trade_moneyctr_key_sequence = (tonumber(accessxi.trade_moneyctr_key_sequence) or 0) + 1;
    accessxi.trade_moneyctr_pending_sequence = accessxi.trade_moneyctr_key_sequence;
    accessxi.trade_moneyctr_pending_key = key_name;
    accessxi.trade_moneyctr_pending_due = tick() + 90;
    return true;
end

function accessxi.poll_trade_moneyctr_keys()
    accessxi.trade_moneyctr_poll_key = 0;
    return false;
end

function accessxi.poll_trade_moneyctr_key_read()
    local due = tonumber(accessxi.trade_moneyctr_pending_due) or 0;
    if (due <= 0) then
        return false;
    end

    local now = tick();
    if (now < due) then
        return false;
    end
    accessxi.trade_moneyctr_pending_due = 0;

    local name = tostring(get_menu_name() or '');
    if (not name:eq('menu    moneyctr', true)) then
        return false;
    end

    local text = accessxi.selected_trade_moneyctr_speech(name);
    if (text == nil or text == '') then
        return false;
    end

    local sequence = tonumber(accessxi.trade_moneyctr_pending_sequence) or 0;
    local key_name = tostring(accessxi.trade_moneyctr_pending_key or '');
    local speech_key = ('moneyctr-key:%d:%s:%s'):fmt(sequence, key_name, accessxi.current_speech_key or '');
    if (speech_key == tostring(accessxi.trade_moneyctr_last_key_speech or '')) then
        return false;
    end
    accessxi.trade_moneyctr_last_key_speech = speech_key;
    accessxi.last = text;
    accessxi.last_key = speech_key;
    local speak_result = speak(text);
    local obj = get_current_menu_object_ptr();
    local entry = accessxi.is_probe_pointer(obj) and (read_u32(obj + 0x08) or 0) or 0;
    local current_gil = accessxi.current_inventory_gil();
    log_state(('state trade moneyctr key-read key="%s" result="%s" obj=0x%08X fields="%s" text="%s"'):fmt(
        accessxi.escape_probe_log_text(key_name),
        accessxi.escape_probe_log_text(speak_result or ''),
        obj,
        accessxi.escape_probe_log_text(obj ~= 0 and accessxi.format_probe_dwords(obj, 0x20, 24) or ''),
        accessxi.escape_probe_log_text(text)));
    accessxi.log_trade_moneyctr_owner_probe(obj, key_name);
    if (accessxi.trade_moneyctr_deep_probe_enabled == true) then
        accessxi.log_trade_moneyctr_deep_probe(name, obj, entry, current_gil, key_name);
    end
    if (text ~= accessxi.last_log or speech_key ~= accessxi.last_log_key) then
        accessxi.last_log = text;
        accessxi.last_log_key = speech_key;
        log_line(text);
    end
    return true;
end

function accessxi.itemctrl_owner_ptr(obj)
    obj = tonumber(obj) or 0;
    if (not accessxi.is_probe_pointer(obj)) then
        return 0;
    end

    local owner = read_u32(obj + 0x0C) or 0;
    if (not accessxi.is_probe_pointer(owner)) then
        return 0;
    end
    return owner;
end

function accessxi.itemctrl_native_quantity(obj)
    obj = tonumber(obj) or 0;
    if (not accessxi.is_probe_pointer(obj)) then
        return nil, nil, '';
    end

    local owner = accessxi.itemctrl_owner_ptr(obj);
    if (owner == 0) then
        return nil, nil, '';
    end

    local packed = read_u32(owner + 0x20);
    if (packed == nil) then
        return nil, nil, '';
    end

    packed = tonumber(packed) or 0;
    local value = math.floor(packed / 0x01000000);
    local max_value = math.floor(packed / 0x00010000) % 0x100;
    local step_or_min = packed % 0x10000;
    if (value < 1 or value > 999 or max_value < 1 or max_value > 999 or value > max_value or step_or_min > 9999) then
        return nil, nil, '';
    end

    return value, max_value, ('owner+020 packed=0x%08X'):fmt(packed);
end

function accessxi.itemctrl_candidate_values(owner)
    owner = tonumber(owner) or 0;
    if (not accessxi.is_probe_pointer(owner)) then
        return '';
    end

    local parts = T{};
    for off = 0x00, 0xA0, 4 do
        local value = read_u32(owner + off);
        if (value ~= nil and value >= 0 and value <= 9999) then
            parts:append(('+%03X=%d'):fmt(off, value));
        end
    end
    return parts:concat(' ');
end

function accessxi.itemctrl_small_values(ptr)
    ptr = tonumber(ptr) or 0;
    if (not accessxi.is_probe_pointer(ptr)) then
        return '';
    end

    local parts = T{};
    for off = 0x00, 0x180, 4 do
        local value = read_i32(ptr + off);
        if (value ~= nil and value >= -1 and value <= 9999) then
            parts:append(('+%03X=%d'):fmt(off, value));
        end
    end
    return parts:concat(' ');
end

function accessxi.itemctrl_pointer_summary(ptr)
    ptr = tonumber(ptr) or 0;
    if (not accessxi.is_probe_pointer(ptr)) then
        return '';
    end

    local parts = T{};
    for off = 0x00, 0x120, 4 do
        local child = read_u32(ptr + off) or 0;
        if (accessxi.is_probe_pointer(child)) then
            local child_values = accessxi.itemctrl_small_values(child);
            if (child_values ~= '') then
                parts:append(('+%03X->0x%08X %s'):fmt(off, child, child_values));
                if (parts:len() >= 8) then
                    break;
                end
            end
        end
    end
    return parts:concat(' | ');
end

function accessxi.last_inventory_item_context()
    local info = accessxi.last_native_inventory_item_info;
    if (info == nil) then
        return nil;
    end
    if ((tick() - (tonumber(accessxi.last_native_inventory_item_tick) or 0)) > 15000) then
        return nil;
    end
    if ((tonumber(info.id) or 0) <= 0 or tostring(info.name or '') == '') then
        return nil;
    end
    return info;
end

function accessxi.log_itemctrl_probe(menu_name, obj, context)
    obj = tonumber(obj) or 0;
    if (not accessxi.is_probe_pointer(obj)) then
        return;
    end

    local owner = accessxi.itemctrl_owner_ptr(obj);
    local quantity, max_quantity, quantity_source = accessxi.itemctrl_native_quantity(obj);
    local packed = owner ~= 0 and (read_u32(owner + 0x20) or 0) or 0;
    local target = AshitaCore:GetMemoryManager():GetTarget();
    local ank = target ~= nil and (tonumber(safe_call(function () return target:GetWindowAnkNum(); end, -1)) or -1) or -1;
    local sub = target ~= nil and (tonumber(safe_call(function () return target:GetWindowSub(); end, -1)) or -1) or -1;
    local obj_values = accessxi.itemctrl_small_values(obj);
    local owner_values = owner ~= 0 and accessxi.itemctrl_small_values(owner) or '';
    local obj_ptrs = accessxi.itemctrl_pointer_summary(obj);
    local owner_ptrs = owner ~= 0 and accessxi.itemctrl_pointer_summary(owner) or '';
    local key = ('%s:%08X:%08X:%08X:%d:%d:%d:%d:%s'):fmt(
        menu_name or '',
        obj,
        owner,
        packed,
        quantity or -1,
        max_quantity or -1,
        context ~= nil and (tonumber(context.id) or 0) or 0,
        context ~= nil and (tonumber(context.count) or 0) or 0,
        context ~= nil and (context.name or '') or '');
    if (key == tostring(accessxi.itemctrl_probe_last_key or '')) then
        return;
    end
    accessxi.itemctrl_probe_last_key = key;

    log_state(('state itemctrl probe menu="%s" obj=0x%08X owner=0x%08X packed=0x%08X quantity=%d max=%d source="%s" ank=%d sub=%d ctxName="%s" ctxCount=%d ctxContainer=%d ctxSlot=%d objVals="%s" ownerVals="%s" objD0="%s" objD80="%s" ownerD0="%s" ownerD80="%s" objPtrs="%s" ownerPtrs="%s"'):fmt(
        menu_name or '',
        obj,
        owner,
        packed,
        quantity or -1,
        max_quantity or -1,
        accessxi.escape_probe_log_text(quantity_source or ''),
        ank,
        sub,
        accessxi.escape_probe_log_text(context ~= nil and (context.name or '') or ''),
        context ~= nil and (tonumber(context.count) or 0) or 0,
        context ~= nil and (tonumber(context.container) or -1) or -1,
        context ~= nil and (tonumber(context.slot) or -1) or -1,
        accessxi.escape_probe_log_text_wide(obj_values),
        accessxi.escape_probe_log_text_wide(owner_values),
        accessxi.escape_probe_log_text_wide(accessxi.format_probe_dwords(obj, 0x00, 32)),
        accessxi.escape_probe_log_text_wide(accessxi.format_probe_dwords(obj, 0x80, 32)),
        accessxi.escape_probe_log_text_wide(owner ~= 0 and accessxi.format_probe_dwords(owner, 0x00, 32) or ''),
        accessxi.escape_probe_log_text_wide(owner ~= 0 and accessxi.format_probe_dwords(owner, 0x80, 32) or ''),
        accessxi.escape_probe_log_text_wide(obj_ptrs),
        accessxi.escape_probe_log_text_wide(owner_ptrs)));
end

function accessxi.log_itemctrl_owner_probe(obj, key_name)
    local owner = accessxi.itemctrl_owner_ptr(obj);
    if (owner == 0) then
        return;
    end

    local values = accessxi.itemctrl_candidate_values(owner);
    local key = ('%s:%08X:%s'):fmt(key_name or '', owner, values);
    if (key == tostring(accessxi.itemctrl_owner_probe_last_key or '')) then
        return;
    end
    accessxi.itemctrl_owner_probe_last_key = key;

    log_state(('state itemctrl owner key="%s" ptr=0x%08X values="%s" d0="%s" d40="%s" d80="%s"'):fmt(
        accessxi.escape_probe_log_text(key_name or ''),
        owner,
        accessxi.escape_probe_log_text_wide(values),
        accessxi.escape_probe_log_text_wide(accessxi.format_probe_dwords(owner, 0x00, 16)),
        accessxi.escape_probe_log_text_wide(accessxi.format_probe_dwords(owner, 0x40, 16)),
        accessxi.escape_probe_log_text_wide(accessxi.format_probe_dwords(owner, 0x80, 16))));
end

function accessxi.selected_itemctrl_speech(menu_name)
    local obj = get_current_menu_object_ptr();
    local window_name = accessxi.trade_handover_target_name();
    local context = accessxi.last_inventory_item_context();
    local quantity, max_quantity, quantity_source = accessxi.itemctrl_native_quantity(obj);
    accessxi.log_itemctrl_probe(menu_name, obj, context);

    accessxi.current_speech_key = ('itemctrl:%s:%08X:%s:%d:%d:%d:%s:%d:%d'):fmt(
        menu_name or '',
        tonumber(obj) or 0,
        window_name or '',
        context ~= nil and (tonumber(context.id) or 0) or 0,
        context ~= nil and (tonumber(context.container) or -1) or -1,
        context ~= nil and (tonumber(context.slot) or -1) or -1,
        context ~= nil and (context.name or '') or '',
        quantity or -1,
        max_quantity or -1);

    local log_key = ('%s:%08X:%s:%d:%d:%d:%s:%d:%d'):fmt(menu_name or '', tonumber(obj) or 0, window_name or '', context ~= nil and (tonumber(context.id) or 0) or 0, context ~= nil and (tonumber(context.container) or -1) or -1, context ~= nil and (tonumber(context.slot) or -1) or -1, context ~= nil and (context.name or '') or '', quantity or -1, max_quantity or -1);
    if (log_key ~= tostring(accessxi.itemctrl_last_log_key or '')) then
        accessxi.itemctrl_last_log_key = log_key;
        log_state(('state itemctrl menu="%s" target="%s" obj=0x%08X quantity=%d max=%d source="%s" contextName="%s" contextCount=%d'):fmt(
            menu_name or '',
            accessxi.escape_probe_log_text(window_name or ''),
            tonumber(obj) or 0,
            quantity or -1,
            max_quantity or -1,
            accessxi.escape_probe_log_text(quantity_source or ''),
            accessxi.escape_probe_log_text(context ~= nil and (context.name or '') or ''),
            context ~= nil and (tonumber(context.count) or 0) or 0));
    end

    if (quantity ~= nil) then
        local name = context ~= nil and (context.name or 'Item') or 'Item';
        if (context ~= nil and (tonumber(context.id) or 0) > 0) then
            accessxi.last_itemctrl_trade_item = T{
                id = tonumber(context.id) or 0,
                container = tonumber(context.container) or -1,
                slot = tonumber(context.slot) or -1,
                name = context.name or '',
                stack_count = tonumber(context.count) or 0,
                quantity = quantity,
                max_quantity = max_quantity or 0,
                tick = tick(),
                source = quantity_source or 'itemctrl',
            };
        end
        if (max_quantity ~= nil and max_quantity > 0) then
            return ('Item quantity. %s. Quantity %d of %d.'):fmt(name, quantity, max_quantity);
        end
        return ('Item quantity. %s. Quantity %d.'):fmt(name, quantity);
    end

    if (context ~= nil) then
        local count = tonumber(context.count) or 0;
        if (count > 0) then
            return ('Item quantity. %s. Available %d.'):fmt(context.name or 'Item', count);
        end
        return ('Item quantity. %s.'):fmt(context.name or 'Item');
    end
    return 'Item quantity.';
end

local function selected_inventory_item_speech(menu_name)
    local command_speech = accessxi.equipment_set_slot_picker_command_speech(menu_name);
    if (command_speech ~= nil) then
        return command_speech;
    end

    local info = accessxi.get_native_selected_inventory_item_info(menu_name);
    if (info ~= nil and info.command) then
        accessxi.current_speech_key = ('inventory-command:%s:%d:%s'):fmt(menu_name or '', info.index or -1, info.name or '');
    elseif (info ~= nil and info.container ~= nil and info.slot ~= nil) then
        local context_token = '';
        if (tostring(accessxi.inventory_context or '') == 'bazaar_item_list') then
            context_token = (':bazaar:%d'):fmt(tonumber(accessxi.bazaar_item_list_generation) or 0);
        elseif (tostring(accessxi.inventory_context or '') == 'vendor_shop_item_list') then
            context_token = (':vendor-shop:%d'):fmt(tonumber(accessxi.vendor_shop_item_list_generation) or 0);
        end
        accessxi.current_speech_key = ('inventory-native:%s:%d:%d:%d:%s%s'):fmt(menu_name or '', info.container or -1, info.slot or -1, info.id or 0, info.name or '', context_token);
    end
    local suppress_count = tostring(accessxi.inventory_context or '') == 'vendor_shop_item_list';
    local speech = inventory_item_info_speech(info, suppress_count);
    if (speech ~= nil and speech ~= '') then
        accessxi.capture_current_gear_detail(menu_name, info, T{
            source = tostring(accessxi.inventory_context or 'inventory'),
        });
    end
    return speech;
end

function accessxi.trade_item_packet_text(slot, item_id, item_num, item_index, source)
    slot = tonumber(slot) or -1;
    item_id = tonumber(item_id) or 0;
    item_num = tonumber(item_num) or 0;
    item_index = tonumber(item_index) or 0;
    source = tostring(source or '');
    if (slot < 0 or slot > 7) then
        return '';
    end

    local user_slot = slot + 1;
    if (item_id == 0 or item_num == 0 or item_index == 0) then
        return ('Trade slot %d cleared.'):fmt(user_slot);
    end

    local resource = resource_item_info(item_id);
    local name = resource ~= nil and tostring(resource.name or '') or '';
    if (name == '') then
        name = ('Item %d'):fmt(item_id);
    end

    local parts = T{ ('Trade slot %d. %s'):fmt(user_slot, name) };
    if (item_num > 1) then
        parts:append(('Quantity %d'):fmt(item_num));
    end
    return join_speech_parts(parts);
end

function accessxi.trade_slot_packet_item(trade_slot, info)
    trade_slot = tonumber(trade_slot) or 0;
    if (trade_slot < 1 or trade_slot > 8) then
        return nil;
    end

    local slot_info = accessxi.trade_slots ~= nil and accessxi.trade_slots[trade_slot - 1] or nil;
    if (slot_info == nil) then
        return nil;
    end

    local count = tonumber(slot_info.count) or 0;
    local id = tonumber(slot_info.id) or 0;
    if (count <= 0 or id <= 0) then
        return nil;
    end

    if (info ~= nil and (tonumber(info.id) or 0) > 0 and id ~= (tonumber(info.id) or 0)) then
        return nil;
    end

    local stack_count = info ~= nil and (tonumber(info.count) or 0) or 0;
    if (stack_count > 0 and count > stack_count) then
        return nil;
    end

    return slot_info;
end

function accessxi.recent_itemctrl_trade_item(info)
    local recent = accessxi.last_itemctrl_trade_item;
    if (recent == nil or info == nil) then
        return nil;
    end

    local recent_tick = tonumber(recent.tick) or 0;
    local age = tick() - recent_tick;
    if (age > 180000) then
        return nil;
    end

    local id = tonumber(recent.id) or 0;
    local count = tonumber(recent.quantity) or 0;
    if (id <= 0 or count <= 0 or id ~= (tonumber(info.id) or 0)) then
        return nil;
    end

    local info_container = tonumber(info.container) or -2;
    local info_slot = tonumber(info.slot) or -2;
    local recent_container = tonumber(recent.container) or -1;
    local recent_slot = tonumber(recent.slot) or -1;
    if (recent_container >= 0 and info_container >= 0 and recent_container ~= info_container) then
        return nil;
    end
    if (recent_slot >= 0 and info_slot >= 0 and recent_slot ~= info_slot) then
        return nil;
    end

    local stack_count = tonumber(info.count) or 0;
    if (stack_count > 0 and count > stack_count) then
        return nil;
    end

    return T{
        id = id,
        count = count,
        item_index = tonumber(info.slot) or 0,
        tick = recent_tick,
        age = age,
        source = 'itemctrl',
    };
end

function accessxi.capture_trade_outgoing_packet(e)
    if (e == nil or e.id ~= 0x0034) then
        return;
    end

    local data = e.data_modified or e.data or '';
    if (#data < 0x0C) then
        return;
    end
    local recent_handover = ((tick() - (tonumber(accessxi.trade_handover_last_seen_tick) or 0)) < 15000);
    if (#data > 0x10 and not accessxi.is_trade_handover_menu_name(get_menu_name()) and not recent_handover) then
        return;
    end

    local item_num = accessxi.packet_u32(data, 0x04 + 1);
    local item_id = accessxi.packet_u16(data, 0x08 + 1);
    local item_index = accessxi.packet_byte(data, 0x0A + 1);
    local trade_index = accessxi.packet_byte(data, 0x0B + 1);
    if (trade_index > 7) then
        if (recent_handover) then
            log_state(('state trade packet_out ignored reason=bad-index parsedSlot=%d len=%d hex=%s'):fmt(
                trade_index,
                #data,
                accessxi.packet_hex(data)));
        end
        return;
    end

    accessxi.trade_slots = accessxi.trade_slots or {};
    accessxi.trade_slots[trade_index] = T{
        id = item_id,
        count = item_num,
        item_index = item_index,
        tick = tick(),
        source = 'packet_out',
    };

    accessxi.trade_handover_bind_entry_slot(
        accessxi.trade_handover_last_obj,
        accessxi.trade_handover_last_entry,
        trade_index + 1,
        'packet_out_034');

    local text = accessxi.trade_item_packet_text(trade_index, item_id, item_num, item_index, 'packet_out_034');
    local key = ('%d:%d:%d:%d'):fmt(trade_index, item_id, item_num, item_index);
    log_state(('state trade packet_out slot=%d userSlot=%d itemId=%d itemIndex=%d count=%d text="%s" hex=%s'):fmt(
        trade_index,
        trade_index + 1,
        item_id,
        item_index,
        item_num,
        accessxi.escape_probe_log_text(text),
        accessxi.packet_hex(data)));
    if (text ~= '' and key ~= tostring(accessxi.trade_packet_last_speech_key or '')) then
        accessxi.trade_packet_last_speech_key = key;
        speak(text);
    end
end

function accessxi.capture_trade_incoming_packet(e)
    if (e == nil or (e.id ~= 0x0023 and e.id ~= 0x0025)) then
        return;
    end

    local data = e.data_modified or e.data or '';
    if ((e.id == 0x0025 and #data < 0x0C) or (e.id == 0x0023 and #data < 0x0E)) then
        return;
    end

    local item_num = accessxi.packet_u32(data, 0x04 + 1);
    local item_id = 0;
    local item_index = 0;
    local trade_index = 0;
    if (e.id == 0x0025) then
        item_id = accessxi.packet_u16(data, 0x08 + 1);
        trade_index = accessxi.packet_byte(data, 0x0A + 1);
        item_index = accessxi.packet_byte(data, 0x0B + 1);
    else
        item_id = accessxi.packet_u16(data, 0x0A + 1);
        trade_index = accessxi.packet_byte(data, 0x0D + 1);
        item_index = 0;
    end
    if (trade_index > 7) then
        return;
    end

    accessxi.trade_slots = accessxi.trade_slots or {};
    accessxi.trade_slots[trade_index] = T{
        id = item_id,
        count = item_num,
        item_index = item_index,
        tick = tick(),
        packet = e.id,
        source = 'packet_in',
    };
    log_state(('state trade packet_in id=0x%03X slot=%d userSlot=%d itemId=%d itemIndex=%d count=%d hex=%s'):fmt(
        e.id,
        trade_index,
        trade_index + 1,
        item_id,
        item_index,
        item_num,
        accessxi.packet_hex(data)));
end

function accessxi.selected_trade_handover_item_speech(menu_name)
    local obj, entry = accessxi.trade_handover_selected_entry();
    accessxi.trade_handover_last_seen_tick = tick();
    if (obj ~= 0 and accessxi.is_probe_pointer(entry)) then
        accessxi.trade_handover_last_obj = obj;
        accessxi.trade_handover_last_entry = entry;
    end
    if (accessxi.trade_handover_maybe_dump_layout(menu_name, obj) == true) then
        dump_current_menu('auto-trade-handover', true);
    end
    local trade_slot, trade_ank = accessxi.trade_handover_slot_for_cursor();
    trade_slot = accessxi.trade_handover_slot_for_entry(obj, entry);
    local info = accessxi.get_native_selected_inventory_item_info(menu_name);
    local occupied = accessxi.trade_handover_entry_occupied(entry);
    local has_item_info = (info ~= nil and info.command ~= true and (tonumber(info.id) or 0) > 0);
    if (trade_slot <= 0) then
        local control_label = accessxi.trade_handover_control_label_for_entry(entry);
        if (control_label ~= '') then
            local window_name = accessxi.trade_handover_target_name();
            local gil_amount = nil;
            local spoken_label = control_label;
            if (control_label:eq('Gil', true)) then
                gil_amount = accessxi.current_inventory_gil();
                if (gil_amount ~= nil) then
                    spoken_label = ('Gil. %d gil'):fmt(gil_amount);
                end
            elseif (control_label:eq('GilAmount', true)) then
                local entry_amount = accessxi.trade_handover_entry_gil_amount(entry);
                local current_gil = accessxi.current_inventory_gil();
                if (entry_amount == nil) then
                    entry_amount = 0;
                end
                if (current_gil ~= nil and entry_amount > current_gil) then
                    entry_amount = current_gil;
                end
                spoken_label = ('Amount %d gil'):fmt(entry_amount);
                if (current_gil ~= nil) then
                    spoken_label = ('%s. Available %d gil'):fmt(spoken_label, current_gil);
                end
            end
            accessxi.current_speech_key = ('trade-control:%s:%08X:%08X:%s:%s'):fmt(
                menu_name or '',
                obj or 0,
                entry or 0,
                spoken_label,
                window_name or '');
            accessxi.log_trade_handover_probe('control-' .. control_label, obj, entry, trade_slot, info);
            if (window_name ~= '') then
                return ('Trade with %s. %s.'):fmt(window_name, spoken_label);
            end
            return ('Trade. %s.'):fmt(spoken_label);
        end
        accessxi.log_trade_handover_control_text_probe(obj, entry);
        accessxi.log_trade_handover_probe(has_item_info and 'non-slot-item-info' or 'non-slot', obj, entry, trade_slot, info);
        return nil;
    end
    if (not has_item_info) then
        accessxi.log_trade_handover_probe(occupied and 'occupied-missing-item' or 'empty-or-slot', obj, entry, trade_slot, info);
        accessxi.current_speech_key = ('trade-slot-empty:%s:%08X:%08X:%d:%d'):fmt(
            menu_name or '',
            obj or 0,
            entry or 0,
            trade_slot,
            occupied and 1 or 0);
        if (occupied) then
            return ('Trade slot %d.'):fmt(trade_slot);
        end
        return ('Trade slot %d. Empty.'):fmt(trade_slot);
    end

    local window_name = accessxi.trade_handover_target_name();
    local packet_item = accessxi.trade_slot_packet_item(trade_slot, info);
    if (packet_item == nil and has_item_info) then
        packet_item = accessxi.recent_itemctrl_trade_item(info);
    end
    local trade_count = packet_item ~= nil and (tonumber(packet_item.count) or 0) or 0;
    accessxi.current_speech_key = ('trade-handover:%s:%08X:%08X:%d:%d:%d:%d:%d:%s:%s'):fmt(
        menu_name or '',
        obj or 0,
        entry or 0,
        trade_slot or 0,
        info.container or -1,
        info.slot or -1,
        info.id or 0,
        trade_count,
        info.name or '',
        window_name or '');
    accessxi.capture_current_gear_detail(menu_name, info, T{
        count = trade_count > 0 and trade_count or info.count,
        slot_name = ('Trade slot %d'):fmt(trade_slot),
        source = 'trade',
    });
    local item_text = inventory_item_info_speech(info, true);
    if (item_text == nil or item_text == '') then
        return nil;
    end
    if (trade_count > 1) then
        item_text = ('%s. Quantity %d'):fmt(item_text, trade_count);
    end

    accessxi.log_trade_handover_probe('item', obj, entry, trade_slot, info);
    local trade_age = packet_item ~= nil and (math.floor(tonumber(packet_item.age) or (tick() - (tonumber(packet_item.tick) or tick())))) or -1;
    log_state(('state trade handover menu="%s" target="%s" container=%d slot=%d id=%d name="%s" count=%d occupied=%d tradeCount=%d tradeSource="%s" tradeAge=%d'):fmt(
        menu_name or '',
        accessxi.escape_probe_log_text(window_name),
        info.container or -1,
        info.slot or -1,
        info.id or 0,
        accessxi.escape_probe_log_text(info.name or ''),
        info.count or 0,
        occupied and 1 or 0,
        trade_count,
        packet_item ~= nil and (packet_item.source or 'packet') or '',
        trade_age));
    if (trade_slot > 0) then
        item_text = ('Slot %d. %s'):fmt(trade_slot, item_text);
    end
    if (window_name ~= '') then
        return ('Trade with %s. %s'):fmt(window_name, item_text);
    end
    return ('Trade. %s'):fmt(item_text);
end

function accessxi.is_synthesis_slot_menu_name(name)
    local slots = accessxi.synthesis_slots;
    return type(slots) == 'table'
        and type(slots.is_menu_name) == 'function'
        and slots.is_menu_name(name) == true;
end

function accessxi.synthesis_slot_selected_entry()
    local obj = get_current_menu_object_ptr();
    if (not accessxi.is_probe_pointer(obj)) then
        return 0, 0;
    end
    return obj, read_u32(obj + 0x08) or 0;
end

function accessxi.log_synthesis_slot_probe(menu_name, obj, entry, cursor, slot, occupied, info, reason)
    if (not accessxi.is_probe_pointer(entry)) then
        return;
    end
    local info_id = info ~= nil and (tonumber(info.id) or 0) or 0;
    local info_name = info ~= nil and tostring(info.name or '') or '';
    local key = ('%s:%08X:%08X:%d:%d:%d:%d:%s'):fmt(
        tostring(menu_name or ''),
        tonumber(obj) or 0,
        tonumber(entry) or 0,
        tonumber(cursor) or 0,
        tonumber(slot) or 0,
        occupied and 1 or 0,
        info_id,
        tostring(reason or ''));
    if (key == tostring(accessxi.synthesis_slot_probe_key or '')) then
        return;
    end
    accessxi.synthesis_slot_probe_key = key;
    log_state(('state synthesis slot menu=%s obj=0x%08X entry=0x%08X cursor=%d slot=%d occupied=%d infoId=%d infoName=%s reason=%s entryDwords=%s'):fmt(
        tostring(menu_name or ''),
        tonumber(obj) or 0,
        tonumber(entry) or 0,
        tonumber(cursor) or 0,
        tonumber(slot) or 0,
        occupied and 1 or 0,
        info_id,
        accessxi.escape_probe_log_text(info_name),
        accessxi.escape_probe_log_text(tostring(reason or '')),
        accessxi.format_probe_dwords(entry, 0, 24)));
end

function accessxi.log_synthesis_control_state(menu_name, obj, entry, cursor, control, native_text, source)
    local key = ('%s:%08X:%08X:%d:%s:%s:%s'):fmt(
        tostring(menu_name or ''),
        tonumber(obj) or 0,
        tonumber(entry) or 0,
        tonumber(cursor) or 0,
        tostring(control or ''),
        tostring(source or ''),
        tostring(native_text or ''));
    if (key == tostring(accessxi.synthesis_control_state_key or '')) then
        return;
    end
    accessxi.synthesis_control_state_key = key;
    log_state(('state synthesis control menu=%s obj=0x%08X entry=0x%08X cursor=%d control=%s source=%s nativeText="%s"'):fmt(
        tostring(menu_name or ''),
        tonumber(obj) or 0,
        tonumber(entry) or 0,
        tonumber(cursor) or 0,
        tostring(control or ''),
        tostring(source or ''),
        accessxi.escape_probe_log_text(tostring(native_text or ''))));
end

function accessxi.selected_synthesis_slot_speech(menu_name)
    local slots = accessxi.synthesis_slots;
    if (type(slots) ~= 'table'
        or type(slots.slot_for_cursor) ~= 'function'
        or type(slots.slot_speech) ~= 'function') then
        return nil;
    end

    local obj, entry = accessxi.synthesis_slot_selected_entry();
    if (not accessxi.is_probe_pointer(entry)) then
        return nil;
    end
    local cursor = read_current_native_menu_index(0x4C);
    local slot = slots.slot_for_cursor(cursor);
    if (slot == nil) then
        if (type(slots.control_for_cursor) ~= 'function'
            or type(slots.control_speech) ~= 'function') then
            return nil;
        end
        local control = slots.control_for_cursor(cursor);
        if (control == nil) then
            return nil;
        end

        local label_ptr = read_u32(entry + 0x44) or 0;
        local help_ptr = read_u32(entry + 0x40) or 0;
        local native_text = accessxi.plain_native_menu_label(read_probe_string(label_ptr));
        local source = 'native-label';
        if (native_text == '') then
            native_text = accessxi.plain_native_menu_help(read_probe_string(help_ptr));
            source = 'native-help';
        end
        local speech = slots.control_speech(cursor, native_text);
        accessxi.log_synthesis_control_state(
            menu_name,
            obj,
            entry,
            cursor,
            control,
            native_text,
            speech ~= nil and source or 'native-text-missing');
        if (speech == nil) then
            return nil;
        end

        accessxi.current_speech_key = ('synthesis-control:%s:%08X:%08X:%d:%s:%s'):fmt(
            tostring(menu_name or ''),
            tonumber(obj) or 0,
            tonumber(entry) or 0,
            tonumber(cursor) or 0,
            tostring(control or ''),
            tostring(native_text or ''));
        return speech;
    end

    local occupied = accessxi.trade_handover_entry_occupied(entry);
    local info = nil;
    local item_text = '';
    if (occupied) then
        info = accessxi.get_native_selected_inventory_item_info(menu_name);
        local has_item_info = info ~= nil
            and info.command ~= true
            and (tonumber(info.id) or 0) > 0;
        if (has_item_info) then
            item_text = inventory_item_info_speech(info, true) or '';
        end
    end

    accessxi.current_speech_key = ('synthesis-slot:%s:%08X:%08X:%d:%d:%d:%d:%s'):fmt(
        tostring(menu_name or ''),
        tonumber(obj) or 0,
        tonumber(entry) or 0,
        tonumber(cursor) or 0,
        tonumber(slot) or 0,
        occupied and 1 or 0,
        info ~= nil and (tonumber(info.id) or 0) or 0,
        tostring(item_text or ''));
    if (info ~= nil) then
        accessxi.capture_current_gear_detail(menu_name, info, T{
            slot_name = ('Synthesis slot %d'):fmt(slot),
            source = 'synthesis',
        });
    end
    accessxi.log_synthesis_slot_probe(
        menu_name,
        obj,
        entry,
        cursor,
        slot,
        occupied,
        info,
        item_text ~= '' and 'native-item' or (occupied and 'occupied-no-item' or 'empty'));
    return slots.slot_speech(slot, occupied, item_text);
end

local function selected_storage_bank_item_speech(menu_name)
    local context_was_unknown = not is_storage_bank_container(accessxi.storage_bank_container);
    local info = get_selected_storage_bank_item_info();
    log_storage_bank_probe(menu_name, info);
    if (info == nil) then
        return nil;
    end

    if (context_was_unknown and is_storage_bank_container(info.container)) then
        accessxi.storage_bank_summary_pending = false;
        local summary = storage_bank_summary_speech(info.container);
        if (summary ~= nil) then
            accessxi.current_speech_key = ('bank-summary:%d'):fmt(info.container);
            return summary;
        end
    end

    accessxi.current_speech_key = ('bank:%d:%d:%d'):fmt(info.container or -1, info.slot or -1, info.id or 0);
    local speech = inventory_item_info_speech(info);
    if (speech ~= nil and speech ~= '') then
        accessxi.capture_current_gear_detail(menu_name, info, T{
            source = 'storage',
        });
    end
    return speech;
end

local function inventory_open_speech(menu_name)
    local container_name = 'Inventory';
    local container_count = 0;
    local container_max = 0;

    local inv = AshitaCore:GetMemoryManager():GetInventory();
    if (inv ~= nil) then
        container_count = tonumber(safe_call(function () return inv:GetContainerCount(0); end, 0)) or 0;
        container_max = tonumber(safe_call(function () return inv:GetContainerCountMax(0); end, 0)) or 0;
    end

    if (container_max > 0) then
        return ('%s open. %d of %d items.'):fmt(container_name, container_count, container_max);
    end
    return ('%s open.'):fmt(container_name);
end

function accessxi.status_overview_speech()
    local text = accessxi.status_overview_native_summary();
    if (text == nil or text == '') then
        return nil;
    end

    accessxi.current_speech_key = ('status-overview:%s'):fmt(accessxi.status_overview_last_key or text);
    return text;
end

function accessxi.speak_manual_status_overview(title, reason)
    local text = accessxi.status_overview_native_summary(title);
    if (text == nil or text == '') then
        return false;
    end

    local speak_result = speak(text);
    log_state(('state manual-status-overview speak reason="%s" result="%s" text="%s"'):fmt(
        reason or '',
        accessxi.escape_probe_log_text(speak_result or ''),
        accessxi.escape_probe_log_text(text)));
    log_line(text);
    return true;
end

function accessxi.check_cache_key_name(name)
    name = accessxi.plain_native_menu_label(clean_login_text(name or ''));
    if (name == '') then
        return '';
    end
    return name:lower();
end

function accessxi.current_check_target_name()
    local mm = safe_call(function () return AshitaCore:GetMemoryManager(); end, nil);
    local target = mm ~= nil and safe_call(function () return mm:GetTarget(); end, nil) or nil;
    if (target == nil) then
        return '';
    end
    return accessxi.plain_native_menu_label(clean_login_text(safe_call(function () return target:GetWindowName(); end, '') or ''));
end

function accessxi.cache_check_title_from_chat(mode, text)
    local mid = bit.band(tonumber(mode) or 0, 0xFF);
    if (mid ~= 0) then
        return false;
    end

    text = accessxi.clean_incoming_text(text or '');
    local name, title = text:match("^([%w%-]+)'s title:%s*(.+)$");
    name = accessxi.plain_native_menu_label(name or '');
    title = accessxi.plain_native_menu_label(title or '');
    local key = accessxi.check_cache_key_name(name);
    if (key == '' or title == '') then
        return false;
    end

    accessxi.check_title_cache[key] = T{
        name = name,
        title = title,
        tick = tick(),
    };
    local log_key = ('%s:%s'):fmt(key, title);
    if (log_key ~= tostring(accessxi.check_title_last_key or '')) then
        accessxi.check_title_last_key = log_key;
        log_state(('state inspect check-title-cache name="%s" title="%s" source="chat-mode-0"'):fmt(
            accessxi.escape_probe_log_text(name),
            accessxi.escape_probe_log_text(title)));
    end
    return true;
end

function accessxi.check_packet_printable_text(data, first_pos, last_pos)
    data = tostring(data or '');
    first_pos = math.max(1, tonumber(first_pos) or 1);
    last_pos = math.min(#data, tonumber(last_pos) or #data);
    local chars = T{};
    local i = first_pos;
    while (i <= last_pos) do
        local b = string.byte(data, i) or 0;
        if (b == 0 or b == 0x0E) then
            break;
        elseif (b >= 32 and b <= 126) then
            chars:append(string.char(b));
        else
            chars:append(' ');
        end
        i = i + 1;
    end
    return accessxi.clean_incoming_text(chars:concat(''));
end

function accessxi.check_packet_comment_text(data, first_pos, last_pos)
    data = tostring(data or '');
    first_pos = math.max(1, tonumber(first_pos) or 1);
    last_pos = math.min(#data, tonumber(last_pos) or #data);
    local stop_pos = last_pos;
    for i = first_pos, last_pos do
        local b = string.byte(data, i) or 0;
        if (b == 0 or b == 0x0E) then
            stop_pos = i - 1;
            break;
        end
    end
    if (stop_pos < first_pos) then
        return '';
    end

    local text = accessxi.clean_incoming_text(data:sub(first_pos, stop_pos));
    text = text:gsub('[\128-\255]+', ' '):gsub('%s+', ' '):trim();
    return text;
end

function accessxi.check_packet_name_after_marker(data, marker_pos)
    data = tostring(data or '');
    marker_pos = tonumber(marker_pos) or 0;
    if (marker_pos <= 0 or marker_pos >= #data) then
        return '';
    end
    local chars = T{};
    for i = marker_pos + 1, math.min(#data, marker_pos + 24) do
        local b = string.byte(data, i) or 0;
        if (b == 0) then
            break;
        end
        if (b >= 32 and b <= 126) then
            chars:append(string.char(b));
        elseif (#chars > 0) then
            break;
        end
    end
    return accessxi.plain_native_menu_label(chars:concat(''));
end

function accessxi.capture_check_comment_packet(e)
    if (e == nil or (tonumber(e.id) or 0) ~= 0x0CA) then
        return false;
    end

    local data = e.data_modified or e.data or accessxi.packet_event_string(e, 'data_modified', 'size') or accessxi.packet_event_string(e, 'data', 'size') or '';
    if (#data < 8) then
        return false;
    end

    local marker = 0;
    for i = 5, math.min(#data, 160) do
        if ((string.byte(data, i) or 0) == 0x0E) then
            marker = i;
            break;
        end
    end

    local name = accessxi.check_packet_name_after_marker(data, marker);
    if (name == '') then
        name = accessxi.current_check_target_name();
    end
    local key = accessxi.check_cache_key_name(name);
    if (key == '') then
        return false;
    end

    local comment = accessxi.plain_native_menu_help(accessxi.check_packet_comment_text(data, 5, marker > 5 and marker - 1 or math.min(#data, 112)));
    if (comment == '') then
        return false;
    end

    accessxi.check_comment_cache[key] = T{
        name = name,
        comment = comment,
        tick = tick(),
    };
    local log_key = ('%s:%s'):fmt(key, comment);
    if (log_key ~= tostring(accessxi.check_comment_last_key or '')) then
        accessxi.check_comment_last_key = log_key;
        log_state(('state inspect check-comment-cache name="%s" comment="%s" source="packet-0x0CA"'):fmt(
            accessxi.escape_probe_log_text(name),
            accessxi.escape_probe_log_text(comment)));
    end
    return true;
end

function accessxi.cached_check_title_for_target(target_name)
    local key = accessxi.check_cache_key_name(target_name or '');
    local record = key ~= '' and (accessxi.check_title_cache or {})[key] or nil;
    if (record == nil or (tick() - (tonumber(record.tick) or 0)) > 300000) then
        return '';
    end
    return accessxi.plain_native_menu_label(record.title or '');
end

function accessxi.cached_check_comment_for_target(target_name)
    local key = accessxi.check_cache_key_name(target_name or '');
    local record = key ~= '' and (accessxi.check_comment_cache or {})[key] or nil;
    if (record == nil or (tick() - (tonumber(record.tick) or 0)) > 300000) then
        return '';
    end
    return accessxi.plain_native_menu_help(record.comment or '');
end

function accessxi.speak_manual_check_summary(reason)
    local text = accessxi.safe_check_character_summary(reason);
    if (text == nil or text == '') then
        return false;
    end

    local key = ('inspect-check-safe-summary:%s'):fmt(accessxi.inspect_check_safe_summary_last_key or text);
    local now = tick();
    local hold_ms = math.min(8000, math.max(1800, #tostring(text) * 45));
    accessxi.inspect_manual_summary_hold_until = now + hold_ms;
    accessxi.inspect_manual_summary_global_hold_until = now + 900;
    accessxi.inspect_manual_summary_native_cursor = tonumber(read_current_native_menu_index(0x4C)) or tonumber(accessxi.last_inspect_native_cursor) or -1;
    accessxi.inspect_manual_summary_menu_obj = get_current_menu_object_ptr();
    accessxi.inspect_manual_summary_suppress_log_key = '';
    accessxi.current_speech_key = key;
    accessxi.last = text;
    accessxi.last_key = key;
    log_state(('state manual-check-summary hold key="%s" native4c=%d obj=0x%08X until=%d globalUntil=%d'):fmt(
        accessxi.escape_probe_log_text(key),
        tonumber(accessxi.inspect_manual_summary_native_cursor) or -1,
        tonumber(accessxi.inspect_manual_summary_menu_obj) or 0,
        tonumber(accessxi.inspect_manual_summary_hold_until) or 0,
        tonumber(accessxi.inspect_manual_summary_global_hold_until) or 0));
    local speak_result = speak(text);
    log_state(('state manual-check-summary speak reason="%s" key="%s" result="%s" text="%s"'):fmt(
        accessxi.escape_probe_log_text(tostring(reason or '')),
        accessxi.escape_probe_log_text(key),
        accessxi.escape_probe_log_text(speak_result or ''),
        accessxi.escape_probe_log_text(text)));
    log_line(text);
    return true;
end

function accessxi.safe_check_character_summary(reason)
    local menu_name = tostring(get_menu_name() or '');
    local inspect_recent_age = (tonumber(accessxi.last_inspect_menu_tick) or 0) > 0
        and (tick() - (tonumber(accessxi.last_inspect_menu_tick) or 0))
        or 999999;
    local current_inspect = menu_name:eq('menu    inspect', true);
    local command_overlay = menu_name:eq('menu    inline', true);
    if ((not current_inspect) and (not (command_overlay and inspect_recent_age < 30000))) then
        log_state(('state inspect check-summary rejected reason="%s" menu="%s" inspectAge=%d'):fmt(
            accessxi.escape_probe_log_text(tostring(reason or '')),
            accessxi.escape_probe_log_text(menu_name),
            inspect_recent_age));
        return nil;
    end

    local mm = safe_call(function () return AshitaCore:GetMemoryManager(); end, nil);
    if (mm == nil) then
        return nil;
    end

    local target = safe_call(function () return mm:GetTarget(); end, nil);
    local target_name = '';
    if (target ~= nil) then
        target_name = accessxi.plain_native_menu_label(clean_login_text(safe_call(function () return target:GetWindowName(); end, '') or ''));
    end

    local inv = safe_call(function () return mm:GetInventory(); end, nil);
    if (inv == nil) then
        return nil;
    end

    log_state('state inspect check-summary before field="mainjob"');
    local main_job = tonumber(safe_call(function () return inv:GetCheckMainJob(); end, 0)) or 0;
    log_state('state inspect check-summary before field="mainlevel"');
    local main_level = tonumber(safe_call(function () return inv:GetCheckMainJobLevel(); end, 0)) or 0;
    log_state('state inspect check-summary before field="subjob"');
    local sub_job = tonumber(safe_call(function () return inv:GetCheckSubJob(); end, 0)) or 0;
    log_state('state inspect check-summary before field="sublevel"');
    local sub_level = tonumber(safe_call(function () return inv:GetCheckSubJobLevel(); end, 0)) or 0;
    log_state('state inspect check-summary before field="masterlevel"');
    local mastery_level = tonumber(safe_call(function () return inv:GetCheckMasteryLevel(); end, 0)) or 0;

    local parts = T{ 'Check' };
    if (target_name ~= '') then
        parts:append(target_name);
    end
    if (main_job > 0 and main_level > 0) then
        parts:append(('Level %d %s'):fmt(main_level, accessxi.job_name(main_job)));
    elseif (main_job > 0) then
        parts:append(accessxi.job_name(main_job));
    end
    if (sub_job > 0 and sub_level > 0) then
        parts:append(('Support job %s level %d'):fmt(accessxi.job_name(sub_job), sub_level));
    elseif (sub_job > 0) then
        parts:append(('Support job %s'):fmt(accessxi.job_name(sub_job)));
    end
    if (mastery_level > 0) then
        parts:append(('Master level %d'):fmt(mastery_level));
    end
    local cached_title = accessxi.cached_check_title_for_target(target_name);
    if (cached_title ~= '') then
        parts:append(('Title %s'):fmt(cached_title));
    end
    local cached_comment = accessxi.cached_check_comment_for_target(target_name);
    if (cached_comment ~= '') then
        parts:append(('Comment. %s'):fmt(cached_comment));
    end

    if (parts:len() <= 1) then
        return nil;
    end

    local text = parts:concat('. ') .. '.';
    accessxi.inspect_check_safe_summary_last_key = ('%s:%d:%d:%d:%d:%d:%s:%s'):fmt(
        target_name,
        main_job,
        main_level,
        sub_job,
        sub_level,
        mastery_level,
        cached_title,
        cached_comment);
    log_state(('state inspect check-summary safe reason="%s" menu="%s" inspectAge=%d target="%s" mainJob=%d mainLevel=%d subJob=%d subLevel=%d masteryLevel=%d title="%s" comment="%s" text="%s"'):fmt(
        accessxi.escape_probe_log_text(tostring(reason or '')),
        accessxi.escape_probe_log_text(menu_name),
        inspect_recent_age,
        accessxi.escape_probe_log_text(target_name),
        main_job,
        main_level,
        sub_job,
        sub_level,
        mastery_level,
        accessxi.escape_probe_log_text(cached_title),
        accessxi.escape_probe_log_text(cached_comment),
        accessxi.escape_probe_log_text(text)));
    return text;
end

function accessxi.manual_check_probe_field(field)
    field = tostring(field or ''):lower():trim();
    if (field == '') then
        field = 'target';
    end

    local menu_name = tostring(get_menu_name() or '');
    local inspect_recent_age = (tonumber(accessxi.last_inspect_menu_tick) or 0) > 0
        and (tick() - (tonumber(accessxi.last_inspect_menu_tick) or 0))
        or 999999;
    local current_inspect = menu_name:eq('menu    inspect', true);
    local command_overlay = menu_name:eq('menu    inline', true);
    if ((not current_inspect) and (not (command_overlay and inspect_recent_age < 30000))) then
        local text = 'Open the Check window before running the Check probe.';
        log_state(('state inspect checkprobe rejected field="%s" menu="%s"'):fmt(
            accessxi.escape_probe_log_text(field),
            accessxi.escape_probe_log_text(menu_name)));
        return text;
    end
    if (not current_inspect) then
        log_state(('state inspect checkprobe recent-context field="%s" menu="%s" inspectAge=%d inspectObj=0x%08X native4c=%d'):fmt(
            accessxi.escape_probe_log_text(field),
            accessxi.escape_probe_log_text(menu_name),
            inspect_recent_age,
            tonumber(accessxi.last_inspect_menu_obj) or 0,
            tonumber(accessxi.last_inspect_native_cursor) or 0));
    end

    local mm = safe_call(function () return AshitaCore:GetMemoryManager(); end, nil);
    if (mm == nil) then
        return 'Check probe unavailable: memory manager missing.';
    end

    local function result_text(label, value, spoken)
        local text = spoken or ('%s %s.'):fmt(label, tostring(value or ''));
        log_state(('state inspect checkprobe field="%s" label="%s" value="%s" text="%s"'):fmt(
            accessxi.escape_probe_log_text(field),
            accessxi.escape_probe_log_text(label),
            accessxi.escape_probe_log_text(tostring(value or '')),
            accessxi.escape_probe_log_text(text)));
        return text;
    end

    if (field:any('target', 'name')) then
        log_state('state inspect checkprobe before field="target"');
        local target = safe_call(function () return mm:GetTarget(); end, nil);
        local target_name = '';
        if (target ~= nil) then
            target_name = accessxi.plain_native_menu_label(clean_login_text(safe_call(function () return target:GetWindowName(); end, '') or ''));
        end
        if (target_name == '') then
            target_name = 'unknown';
        end
        return result_text('Target', target_name, ('Check target. %s.'):fmt(target_name));
    end

    if (field:any('title', 'comment')) then
        local target_name = accessxi.current_check_target_name();
        if (target_name == '') then
            target_name = 'unknown';
        end
        if (field:any('title')) then
            local title = accessxi.cached_check_title_for_target(target_name);
            if (title == '') then
                return result_text('Title', 'none', ('No cached Check title for %s.'):fmt(target_name));
            end
            return result_text('Title', title, ('Title. %s.'):fmt(title));
        end
        local comment = accessxi.cached_check_comment_for_target(target_name);
        if (comment == '') then
            return result_text('Comment', 'none', ('No cached Check comment for %s.'):fmt(target_name));
        end
        return result_text('Comment', comment, ('Comment. %s.'):fmt(comment));
    end

    local inv = safe_call(function () return mm:GetInventory(); end, nil);
    if (inv == nil) then
        return 'Check probe unavailable: inventory missing.';
    end

    if (field:any('selected', 'gear', 'item')) then
        return result_text('Selected gear', 'disabled', 'Selected Check probe disabled. Gear rows already read directly.');
    end

    local probes = T{
        mainjob = T{ label = 'Main job', call = function () return inv:GetCheckMainJob(); end, format = function (v) return accessxi.job_name(v); end },
        mainlevel = T{ label = 'Main level', call = function () return inv:GetCheckMainJobLevel(); end },
        subjob = T{ label = 'Support job', call = function () return inv:GetCheckSubJob(); end, format = function (v) return accessxi.job_name(v); end },
        sublevel = T{ label = 'Support level', call = function () return inv:GetCheckSubJobLevel(); end },
        mainjob2 = T{ label = 'Main job 2', call = function () return inv:GetCheckMainJob2(); end, format = function (v) return accessxi.job_name(v); end },
        masterlevel = T{ label = 'Master level', call = function () return inv:GetCheckMasteryLevel(); end },
        masteryflags = T{ label = 'Mastery flags', call = function () return inv:GetCheckMasteryFlags(); end },
        flags = T{ label = 'Check flags', call = function () return inv:GetCheckFlags(); end, format = function (v) return ('0x%08X'):fmt(tonumber(v) or 0); end },
        serverid = T{ label = 'Server id', call = function () return inv:GetCheckServerId(); end },
        targetindex = T{ label = 'Target index', call = function () return inv:GetCheckTargetIndex(); end },
    };
    if (field:eq('main', true)) then
        field = 'mainjob';
    elseif (field:eq('level', true)) then
        field = 'mainlevel';
    elseif (field:eq('sub', true)) then
        field = 'subjob';
    elseif (field:eq('master', true)) then
        field = 'masterlevel';
    elseif (field:eq('index', true)) then
        field = 'targetindex';
    elseif (field:eq('server', true)) then
        field = 'serverid';
    end

    local probe = probes[field];
    if (probe == nil) then
        local text = 'Unknown Check probe field. Try target, title, comment, mainjob, mainlevel, subjob, sublevel, masterlevel, flags, serverid, or targetindex.';
        log_state(('state inspect checkprobe unknown field="%s"'):fmt(accessxi.escape_probe_log_text(field)));
        return text;
    end

    log_state(('state inspect checkprobe before field="%s"'):fmt(accessxi.escape_probe_log_text(field)));
    local value = safe_call(probe.call, nil);
    if (value == nil) then
        return result_text(probe.label, 'nil', ('%s unavailable.'):fmt(probe.label));
    end
    local spoken_value = tostring(value);
    if (type(probe.format) == 'function') then
        spoken_value = tostring(probe.format(tonumber(value) or 0) or value);
    end
    return result_text(probe.label, value, ('%s. %s.'):fmt(probe.label, spoken_value));
end

function accessxi.poll_status_overview_screen_read()
    local due = tonumber(accessxi.status_overview_pending_due) or 0;
    if (due <= 0) then
        return false;
    end

    local now = tick();
    if (now < due) then
        return false;
    end
    if (now > (tonumber(accessxi.status_overview_pending_until) or 0)) then
        accessxi.status_overview_pending_due = 0;
        accessxi.status_overview_pending_until = 0;
        return false;
    end
    if (not tostring(get_menu_name() or ''):eq('menu    statcom2', true)) then
        accessxi.status_overview_pending_due = 0;
        accessxi.status_overview_pending_until = 0;
        return false;
    end
    if (is_chat_input_open()) then
        accessxi.status_overview_pending_due = now + 150;
        return false;
    end

    accessxi.current_speech_key = '';
    local text = accessxi.status_overview_speech();
    local key = accessxi.current_speech_key or '';
    if (text == nil or text == '' or key == '') then
        accessxi.status_overview_pending_due = now + 150;
        return false;
    end

    accessxi.status_overview_pending_due = 0;
    accessxi.status_overview_pending_until = 0;
    if (key == (accessxi.status_overview_last_spoken_key or '')
        and (now - (tonumber(accessxi.status_overview_last_spoken_tick) or 0)) < 1500) then
        return false;
    end

    accessxi.status_overview_last_spoken_key = key;
    accessxi.status_overview_last_spoken_tick = now;
    accessxi.last = text;
    accessxi.last_key = key;
    local selection = accessxi.current_status_menu_selection();
    if (selection ~= nil) then
        accessxi.status_menu_quiet_selected = tonumber(selection.selected) or -1;
    end
    local speak_result = speak(text);
    log_state(('state status-overview speak reason="%s" result="%s" text="%s"'):fmt(
        accessxi.status_overview_pending_reason or '',
        accessxi.escape_probe_log_text(speak_result or ''),
        accessxi.escape_probe_log_text(text)));
    if (text ~= accessxi.last_log or key ~= accessxi.last_log_key) then
        accessxi.last_log = text;
        accessxi.last_log_key = key;
        log_line(text);
    end
    return true;
end

function accessxi.poll_status_detail_screen_read()
    local due = tonumber(accessxi.status_detail_pending_due) or 0;
    if (due <= 0) then
        return false;
    end

    local now = tick();
    if (now < due) then
        return false;
    end
    if (now > (tonumber(accessxi.status_detail_pending_until) or 0)) then
        accessxi.status_detail_pending_due = 0;
        accessxi.status_detail_pending_until = 0;
        return false;
    end
    if (is_chat_input_open()) then
        accessxi.status_detail_pending_due = now + 150;
        return false;
    end

    local label = tostring(accessxi.status_detail_pending_label or '');
    local row_code = tonumber(accessxi.status_detail_pending_row_code) or 0;
    local text, key = accessxi.status_detail_native_summary(label, row_code);
    if (text == nil or text == '' or key == nil or key == '') then
        accessxi.status_detail_pending_due = now + 150;
        return false;
    end

    accessxi.status_detail_pending_due = 0;
    accessxi.status_detail_pending_until = 0;
    accessxi.status_detail_suppress_status_menu_until = now + 900;
    if (key == (accessxi.status_detail_last_spoken_key or '')
        and (now - (tonumber(accessxi.status_detail_last_spoken_tick) or 0)) < 1500) then
        return false;
    end

    accessxi.status_detail_last_spoken_key = key;
    accessxi.status_detail_last_spoken_tick = now;
    accessxi.last = text;
    accessxi.last_key = key;
    local selection = accessxi.current_status_menu_selection();
    if (selection ~= nil) then
        accessxi.status_menu_quiet_selected = tonumber(selection.selected) or -1;
    end
    local speak_result = speak(text);
    log_state(('state status-detail speak label="%s" rowCode=0x%08X result="%s" text="%s"'):fmt(
        label,
        row_code,
        accessxi.escape_probe_log_text(speak_result or ''),
        accessxi.escape_probe_log_text(text)));
    if (text ~= accessxi.last_log or key ~= accessxi.last_log_key) then
        accessxi.last_log = text;
        accessxi.last_log_key = key;
        log_line(text);
    end
    return true;
end

function accessxi.poll_status_hotkeys()
    local alt = bit.band(tonumber(kernel32.GetAsyncKeyState(VK_MENU)) or 0, 0x8000) ~= 0;
    local shift = bit.band(tonumber(kernel32.GetAsyncKeyState(0x10)) or 0, 0x8000) ~= 0;
    local i_key = bit.band(tonumber(kernel32.GetAsyncKeyState(0x49)) or 0, 0x8000) ~= 0;
    local down = alt and i_key;
    if (not down) then
        accessxi.status_hotkey_down = false;
        return false;
    end
    if (accessxi.status_hotkey_down) then
        return false;
    end
    accessxi.status_hotkey_down = true;
    if (is_chat_input_open()) then
        return false;
    end

    local menu_name = tostring(get_menu_name() or '');
    local status_menu_open = menu_name:eq('menu    statcom2', true);
    local equipment_menu_open = is_equipment_menu_name(menu_name);
    local inspect_menu_open = menu_name:eq('menu    inspect', true);
    if ((not status_menu_open) and (not equipment_menu_open) and (not inspect_menu_open)) then
        log_state(('state status-hotkey unsupported-menu menu="%s"'):fmt(accessxi.escape_probe_log_text(menu_name)));
        return false;
    end

    if (shift) then
        if (not status_menu_open) then
            return false;
        end
        accessxi.status_overview_pending_due = 0;
        accessxi.status_overview_pending_until = 0;
        local selection = accessxi.current_status_menu_selection();
        if (selection == nil) then
            speak('No supported status detail is selected.');
            log_state('state status-detail hotkey no-selection');
            return true;
        end
        return accessxi.schedule_status_detail_screen_read(selection, 'status-detail-hotkey', 0);
    end

    accessxi.status_detail_pending_due = 0;
    accessxi.status_detail_pending_until = 0;
    accessxi.status_detail_suppress_status_menu_until = 0;
    if (inspect_menu_open) then
        return accessxi.speak_manual_check_summary('check-hotkey');
    end
    if (equipment_menu_open) then
        return accessxi.speak_manual_status_overview('Equipment', 'equipment-hotkey');
    end
    return accessxi.speak_manual_status_overview(nil, 'status-hotkey');
end

function accessxi.quick_status_key_down(virtual_key)
    return bit.band(tonumber(kernel32.GetAsyncKeyState(virtual_key)) or 0, 0x8000) ~= 0;
end

function accessxi.accessibility_hotkey_modifier_held()
    return accessxi.quick_status_key_down(VK_MENU)
        or accessxi.quick_status_key_down(VK_CONTROL)
        or accessxi.quick_status_key_down(accessxi.VK_SHIFT);
end

function accessxi.accessibility_hotkey_snapshot()
    return {
        foreground = accessxi.is_foreground_process(),
        chat_open = is_chat_input_open ~= nil and is_chat_input_open() or false,
        modifier_down = accessxi.accessibility_hotkey_modifier_held(),
    };
end

function accessxi.quick_status_pressed_chord(snapshot)
    if type(snapshot) ~= 'table'
        or snapshot.modifier_down == true
        or type(snapshot.keys) ~= 'table' then
        return nil;
    end
    for _, key in ipairs({ 'D', 'B', 'H', 'M', 'X' }) do
        if (snapshot.keys[key] == true) then
            return key;
        end
    end
    return nil;
end

function accessxi.quick_status_live_data(snapshot)
    local mm = safe_call(function () return AshitaCore:GetMemoryManager(); end, nil);
    local player = mm ~= nil and safe_call(function () return mm:GetPlayer(); end, nil) or nil;
    local party = mm ~= nil and safe_call(function () return mm:GetParty(); end, nil) or nil;
    local resources = safe_call(function () return AshitaCore:GetResourceManager(); end, nil);

    snapshot.hp_available = false;
    snapshot.mp_available = false;
    snapshot.experience_available = false;
    snapshot.vitals_available = false;
    if (player ~= nil and party ~= nil) then
        snapshot.hp_current = tonumber(safe_call(function () return party:GetMemberHP(0); end, nil));
        snapshot.hp_max = tonumber(safe_call(function () return player:GetHPMax(); end, nil));
        snapshot.mp_current = tonumber(safe_call(function () return party:GetMemberMP(0); end, nil));
        snapshot.mp_max = tonumber(safe_call(function () return player:GetMPMax(); end, nil));
        snapshot.exp_current = tonumber(safe_call(function () return player:GetExpCurrent(); end, nil));
        snapshot.exp_needed = tonumber(safe_call(function () return player:GetExpNeeded(); end, nil));
        snapshot.hp_available = snapshot.hp_current ~= nil and snapshot.hp_max ~= nil;
        snapshot.mp_available = snapshot.mp_current ~= nil and snapshot.mp_max ~= nil;
        snapshot.experience_available = snapshot.exp_current ~= nil and snapshot.exp_needed ~= nil;
        snapshot.vitals_available = snapshot.hp_available
            and snapshot.mp_available
            and snapshot.experience_available;
    end

    snapshot.statuses_available = false;
    snapshot.statuses = {};
    if (player == nil or resources == nil) then
        return snapshot;
    end

    local buffs = safe_call(function () return player:GetBuffs(); end, nil);
    if (buffs == nil) then
        return snapshot;
    end
    local probe_ok = pcall(function () return tonumber(buffs[0]); end);
    if (not probe_ok) then
        return snapshot;
    end

    snapshot.statuses_available = true;
    for index = 0, 31 do
        local id = tonumber(safe_call(function () return buffs[index]; end, nil));
        if (id ~= nil and id >= 0) then
            local name = safe_call(function ()
                return resources:GetString('buffs.names', id) or '';
            end, '');
            local icon = safe_call(function () return resources:GetStatusIconById(id); end, nil);
            local can_cancel = icon ~= nil
                and (tonumber(safe_call(function () return icon.CanCancel; end, 0)) or 0) ~= 0;
            snapshot.statuses[#snapshot.statuses + 1] = {
                id = id,
                name = tostring(name or ''),
                can_cancel = can_cancel,
            };
        end
    end
    return snapshot;
end

function accessxi.quick_status_log_ids(label, values)
    if type(values) ~= 'table' or #values == 0 then
        return;
    end
    local parts = {};
    for _, value in ipairs(values) do
        parts[#parts + 1] = tostring(tonumber(value) or value);
    end
    log_line(('quick-status %s ids="%s"'):fmt(tostring(label or 'unclassified'), table.concat(parts, ',')));
end

function accessxi.poll_quick_status_hotkeys()
    if (type(accessxi.quick_status_hotkeys) ~= 'table'
        or type(accessxi.quick_status_hotkeys.poll) ~= 'function') then
        return false;
    end

    local snapshot = {
        foreground = accessxi.is_foreground_process(),
        chat_open = is_chat_input_open ~= nil and is_chat_input_open() or false,
        modifier_down = accessxi.accessibility_hotkey_modifier_held(),
        keys = {
            D = accessxi.quick_status_key_down(0x44),
            B = accessxi.quick_status_key_down(0x42),
            H = accessxi.quick_status_key_down(0x48),
            M = accessxi.quick_status_key_down(0x4D),
            X = accessxi.quick_status_key_down(0x58),
        },
    };
    local chord = accessxi.quick_status_pressed_chord(snapshot);
    local last_chord = tostring(accessxi.quick_status_hotkey_state.last_chord or '');
    if (chord ~= nil
        and chord ~= last_chord
        and snapshot.foreground
        and not snapshot.chat_open) then
        accessxi.quick_status_live_data(snapshot);
    end

    local text, action, meta = accessxi.quick_status_hotkeys.poll(
        accessxi.quick_status_hotkey_state, snapshot);
    if (type(meta) == 'table') then
        accessxi.quick_status_log_ids('unclassified', meta.unknown_ids);
        accessxi.quick_status_log_ids('missing-native-name', meta.missing_name_ids);
    end
    text = tostring(text or ''):trim();
    if (text == '') then
        return false;
    end

    local result = speak(text);
    log_state(('state quick-status action="%s" result="%s" text="%s"'):fmt(
        accessxi.escape_probe_log_text(action or ''),
        accessxi.escape_probe_log_text(result or ''),
        accessxi.escape_probe_log_text(text)));
    return true;
end

function accessxi.accessibility_hotkey_owns_vk(vk, snapshot)
    snapshot = snapshot or accessxi.accessibility_hotkey_snapshot();
    if (snapshot.foreground ~= true
        or snapshot.chat_open == true
        or snapshot.modifier_down == true) then
        return false;
    end

    if (type(accessxi.quick_status_hotkeys) == 'table'
        and type(accessxi.quick_status_hotkeys.is_hotkey_vk) == 'function'
        and accessxi.quick_status_hotkeys.is_hotkey_vk(vk)) then
        return true;
    end

    if (type(accessxi.navigation_hotkeys) == 'table'
        and type(accessxi.navigation_hotkeys.should_claim_vk) == 'function') then
        return accessxi.navigation_hotkeys.should_claim_vk(
            accessxi.navigation_hotkey_state, vk, snapshot);
    end
    return false;
end

function accessxi.accessibility_hotkey_directinput_map()
    if (type(accessxi.accessibility_hotkey_dik_map) == 'table') then
        return accessxi.accessibility_hotkey_dik_map;
    end

    local result = { vk_to_dik = {}, dik_to_vk = {} };
    local modules = { accessxi.quick_status_hotkeys, accessxi.navigation_hotkeys };
    local resolved = {};
    for _, module in ipairs(modules) do
        if (type(module) == 'table' and type(module.VK) == 'table') then
            for label, raw_vk in pairs(module.VK) do
                local vk = tonumber(raw_vk) or 0;
                local dik = tonumber(safe_call(function ()
                    return AshitaCore:GetInputManager():GetKeyboard():V2D(vk);
                end, 0)) or 0;
                if ((dik <= 0 or dik > 255) and type(module.DIK_BY_VK) == 'table') then
                    dik = tonumber(module.DIK_BY_VK[vk]) or 0;
                end
                if (vk > 0 and dik > 0 and dik <= 255) then
                    result.vk_to_dik[vk] = dik;
                    result.dik_to_vk[dik] = vk;
                    resolved[#resolved + 1] = ('%s:%d'):fmt(tostring(label), dik);
                end
            end
        end
    end
    table.sort(resolved);
    accessxi.accessibility_hotkey_dik_map = result;
    log_line(('accessibility DirectInput keys %s'):fmt(table.concat(resolved, ',')));
    return result;
end

local function current_menu_speech(full_details)
    if (is_chat_input_open ~= nil and is_chat_input_open()) then
        return nil;
    end

    local name = get_menu_name();
    if (type(accessxi.nav_mission_quest_observe_event_menu) == 'function') then
        pcall(function ()
            accessxi.nav_mission_quest_observe_event_menu(name or '', tick());
        end);
    end
    accessxi.current_menu_speech_title = '';
    if (name == nil or name == '') then
        local blank_speech = accessxi.mog_door_blank_menu_probe('no-menu');
        accessxi.current_menu_name = '';
        accessxi.equipment_active = false;
        accessxi.equipment_cursor_grid = -1;
        accessxi.storage_bank_context_until = 0;
        accessxi.storage_bank_container = -1;
        accessxi.storage_bank_container_name = '';
        accessxi.storage_bank_summary_pending = false;
        if (type(blank_speech) == 'string' and blank_speech ~= '') then
            return blank_speech;
        end
        return nil;
    end

    local previous_menu_name = accessxi.current_menu_name or '';
    accessxi.current_menu_name = name;
    if (previous_menu_name ~= name) then
        local transition_from = previous_menu_name;
        if (transition_from == '') then
            transition_from = tostring(accessxi.last_nonblank_menu_name or '');
        end
        accessxi.last_menu_transition_from = transition_from;
        accessxi.last_menu_transition_to = name;
        accessxi.last_menu_transition_tick = tick();
        if (name:eq('menu    worldsel', true)) then
            accessxi.arm_character_creation_world_packet_trace('worldsel-transition', 15000, 80);
        end
        if (name:eq('menu    magic', true)) then
            if (tostring(transition_from or ''):eq('menu    mgcmenu', true)
                or tostring(transition_from or ''):eq('menu    magselec', true)) then
                accessxi.magic_category_list_active = true;
                accessxi.magic_category_list_label = accessxi.magic_current_category_label();
                accessxi.magic_category_list_tick = tick();
            elseif (tostring(transition_from or ''):eq('menu    blusortw', true)
                or tostring(transition_from or ''):eq('menu    mgcsortw', true)) then
                local blue_magic_sort_category_label = tostring(accessxi.current_blue_magic_sort_category_label or '');
                local blue_magic_sort_category_age = tick() - (tonumber(accessxi.current_blue_magic_sort_category_tick) or 0);
                if (blue_magic_sort_category_label ~= '' and blue_magic_sort_category_age >= 0 and blue_magic_sort_category_age < 10000) then
                    accessxi.magic_category_list_active = true;
                    accessxi.magic_category_list_label = blue_magic_sort_category_label;
                    accessxi.magic_category_list_tick = tick();
                else
                    accessxi.magic_category_list_active = false;
                    accessxi.magic_category_list_label = '';
                    accessxi.magic_category_list_tick = 0;
                end
            elseif (tostring(transition_from or ''):eq('menu    playermo', true)
                and (tostring(accessxi.last_playermo_command_label or ''):eq('Trust', true)
                    or tostring(accessxi.last_playermo_command_label or ''):eq('Trust Magic', true))
                and (tick() - (tonumber(accessxi.last_playermo_command_tick) or 0)) < 2500) then
                accessxi.last_magic_category_label = 'Trust Magic';
                accessxi.current_magic_category_label = 'Trust Magic';
                accessxi.magic_known_cache = nil;
                accessxi.magic_known_cache_key = '';
