            end
            accessxi.magic_selected_unwrap_base = 0;
            accessxi.magic_selected_unwrap_last_raw = 0;
            accessxi.magic_selected_unwrap_last_effective = 0;
            accessxi.magic_selected_unwrap_last_entry = 0;
            accessxi.magic_selected_unwrap_tick = 0;
        elseif ((not name:eq('menu    mgcmenu', true)) and (not name:eq('menu    magselec', true))) then
