        accessxi.equipment_active = true;
        local menu_just_opened = not is_equipment_menu_name(previous_menu_name);
        local ok, equipment_speech = pcall(function ()
            return selected_equipment_speech(name, menu_just_opened, full_details);
        end);
        if (not ok) then
            log_line(('equipment reader error menu="%s" error="%s"'):fmt(name or '', tostring(equipment_speech or '')));
            accessxi.current_speech_key = ('equipment-error:%s'):fmt(name or '');
            return '';
        end
        if (equipment_speech ~= nil) then
            return equipment_speech;
        end
    else
        accessxi.equipment_active = false;
        accessxi.equipment_cursor_grid = -1;
    end

    if (is_storage_bank_menu_name(name)) then
        accessxi.inventory_context = 'storage_bank';
        local bank_just_opened = not is_storage_bank_menu_name(previous_menu_name);
        local info = get_selected_storage_bank_item_info();
        if (info ~= nil and is_storage_bank_container(info.container)) then
            set_storage_bank_context(info.container);
        elseif (tick() < (accessxi.storage_bank_context_until or 0)) then
            accessxi.inventory_context = 'storage_bank';
        end

        if (bank_just_opened) then
            accessxi.inventory_open_summary_until = tick() + 750;
            accessxi.storage_bank_summary_pending = not is_storage_bank_container(accessxi.storage_bank_container);
            log_storage_bank_probe(name, info);
            local storage_summary = storage_bank_summary_speech(info ~= nil and info.container or -1);
            if (storage_summary ~= nil) then
                accessxi.storage_bank_summary_pending = false;
                return storage_summary;
            end
        end

        if (tick() < accessxi.inventory_open_summary_until) then
            return nil;
        end

        local bank_speech = selected_storage_bank_item_speech(name);
        if (bank_speech ~= nil) then
            return bank_speech;
        end

        return nil;
    end

    local bazaar_item_list_menu = accessxi.is_bazaar_item_list_menu_name(name, previous_menu_name);
    local vendor_shop_item_list_menu = accessxi.is_vendor_shop_item_list_menu_name(name, previous_menu_name);
    local inventory_menu = is_inventory_menu_name(name) or bazaar_item_list_menu or vendor_shop_item_list_menu;
    local previous_inventory_menu = is_inventory_menu_name(previous_menu_name)
        or (previous_menu_name:eq('menu    shop', true)
            and (tostring(accessxi.inventory_context or '') == 'bazaar_item_list'
                or tostring(accessxi.inventory_context or '') == 'vendor_shop_item_list'));
    if (inventory_menu) then
        if (bazaar_item_list_menu) then
            if (not previous_menu_name:eq('menu    shop', true)) then
                accessxi.bazaar_item_list_generation = (tonumber(accessxi.bazaar_item_list_generation) or 0) + 1;
            end
            accessxi.inventory_context = 'bazaar_item_list';
            accessxi.inventory_open_summary_until = 0;
        elseif (vendor_shop_item_list_menu) then
            if (not previous_menu_name:eq('menu    shop', true)) then
                accessxi.vendor_shop_item_list_generation = (tonumber(accessxi.vendor_shop_item_list_generation) or 0) + 1;
            end
            accessxi.inventory_context = 'vendor_shop_item_list';
            accessxi.vendor_shop_item_list_context_until = tick() + 30000;
            accessxi.inventory_open_summary_until = 0;
        elseif (not previous_inventory_menu) then
            if (previous_menu_name:eq('menu    mcresed', true)) then
                accessxi.inventory_context = 'equipment_set_slot_picker';
                accessxi.equipment_set_slot_picker_obj = get_current_menu_object_ptr();
                accessxi.inventory_open_summary_until = 0;
                log_state(('state equipset-slot-picker context-start obj=0x%08X previous="%s"'):fmt(
                    tonumber(accessxi.equipment_set_slot_picker_obj) or 0,
                    accessxi.escape_probe_log_text(previous_menu_name or '')));
            elseif (is_equipment_menu_name(previous_menu_name)) then
                accessxi.inventory_context = 'equipment_list';
                accessxi.inventory_open_summary_until = 0;
            elseif (is_equipment_storage_options_menu_name(previous_menu_name)) then
                accessxi.inventory_context = 'equipment_list';
                accessxi.inventory_open_summary_until = 0;
                log_state(('state equipment-storage-filtered-inventory context-start previous="%s" obj=0x%08X'):fmt(
                    accessxi.escape_probe_log_text(previous_menu_name or ''),
                    get_current_menu_object_ptr()));
            else
                accessxi.inventory_context = '';
                accessxi.inventory_open_summary_until = tick() + 750;
                return inventory_open_speech(name);
            end
        end

        if (tick() < accessxi.inventory_open_summary_until) then
            return nil;
        end

        if (tick() < (tonumber(accessxi.macro_palette_probe_until) or 0)) then
            local probe_obj = get_current_menu_object_ptr();
            local probe_selected, probe_page, probe_raw, probe_child, probe_count = accessxi.survival_guide_query_child_state_for_obj(probe_obj);
            probe_selected = tonumber(probe_selected) or 0;
            probe_count = tonumber(probe_count) or 0;
            if (probe_selected <= 0) then
                probe_selected = read_current_native_menu_index(0x4C);
            end
            if (probe_count <= 0 or probe_count > 64) then
                local count_a = accessxi.native_menu_index(0x24);
                local count_b = accessxi.native_menu_index(0x28);
                probe_count = math.max(tonumber(count_a) or 0, tonumber(count_b) or 0);
            end
            local probe_entry = accessxi.is_probe_pointer(probe_obj) and (read_u32(probe_obj + 0x08) or 0) or 0;
            accessxi.log_macro_palette_menu_probe(name, accessxi.native_known_menu_title(name), probe_obj, probe_selected, probe_count, probe_page, probe_raw, probe_child, probe_entry, 'inventory-path');
        end

        local inventory_speech = selected_inventory_item_speech(name);
        if (inventory_speech ~= nil) then
            return inventory_speech;
        end
    else
        if (accessxi.inventory_context ~= 'storage_bank') then
            accessxi.inventory_context = '';
        end
    end

    if (accessxi.is_synthesis_slot_menu_name(name)) then
        accessxi.inventory_context = 'synthesis_slots';
        local synthesis_speech = accessxi.selected_synthesis_slot_speech(name);
        if (synthesis_speech ~= nil) then
            return synthesis_speech;
        end
        return nil;
    end

    if (accessxi.is_trade_handover_menu_name(name)) then
        accessxi.inventory_context = 'trade_handover';
        local trade_speech = accessxi.selected_trade_handover_item_speech(name);
        if (trade_speech ~= nil) then
            return trade_speech;
        end
        return nil;
    end

    if (name:eq('menu    moneyctr', true)) then
        accessxi.inventory_context = 'trade_handover';
        local money_speech = accessxi.selected_trade_moneyctr_speech(name);
        if (money_speech ~= nil) then
            return money_speech;
        end
        return nil;
    end

    if (name:eq('menu    itemctrl', true)) then
        accessxi.inventory_context = 'trade_handover';
        local itemctrl_speech = accessxi.selected_itemctrl_speech(name);
        if (itemctrl_speech ~= nil) then
            return itemctrl_speech;
        end
        return nil;
    end

    maybe_auto_dump_menu(name);
    maybe_auto_dump_chat_log_menu(name);
    if (name:eq('menu    mount', true)) then
        return nil;
    end
    local _, unsupported_records_of_eminence_context = accessxi.quests_menu_effective_mode();
    if (name:eq('menu    quest01', true)
        and (unsupported_records_of_eminence_context == 'records-of-eminence'
            or unsupported_records_of_eminence_context == 'records-of-eminence-objective-list'
            or unsupported_records_of_eminence_context == 'records-of-eminence-objective-category'
            or unsupported_records_of_eminence_context == 'records-of-eminence-objective-catalog')) then
        return nil;
    end
    if (accessxi.is_config_menu_name(name)) then
        return nil;
    end
    if (accessxi.is_help_desk_menu_name(name)) then
        return nil;
    end
    if (name:eq('menu    guide00', true)) then
        return nil;
    end
    if (name:eq('menu    guide01', true)) then
        return nil;
    end
    if (name:eq('menu    inspect', true)) then
        local obj = get_current_menu_object_ptr();
        return accessxi.inspect_menu_probe_speech(name, 'Check', obj, 0, 0, 0, 0, 0, 0, 'unsupported-suppressed');
    end
    if (name:eq('menu    playermo', true)) then
        return nil;
    end
    if (name:eq('menu    ability', true)) then
        return nil;
    end
    log_unknown_menu_probe(name);
    if (not name:eq('menu    magic', true)) then
        log_ingame_target_probe('unsupported-menu-' .. name);
    end
    return nil;
end

function accessxi.poll_gear_detail_hotkeys()
    local module = accessxi.gear_detail_hotkeys;
    local state = accessxi.gear_detail_hotkey_state;
    if (type(module) ~= 'table'
        or type(module.poll) ~= 'function'
        or type(module.needs_refresh) ~= 'function'
        or type(state) ~= 'table') then
        return false;
    end

    local vk = module.VK or {};
    local snapshot = {
        foreground = accessxi.is_foreground_process(),
        chat_open = is_chat_input_open ~= nil and is_chat_input_open() or false,
        modifier_down = accessxi.accessibility_hotkey_modifier_held(),
        current_menu = tostring(get_menu_name() or ''),
        context_key = tostring(accessxi.current_speech_key or ''),
        now = tick(),
        keys = {
            J = accessxi.quick_status_key_down(tonumber(vk.J) or 0x4A),
            K = accessxi.quick_status_key_down(tonumber(vk.K) or 0x4B),
            L = accessxi.quick_status_key_down(tonumber(vk.L) or 0x4C),
        },
    };

    if (module.needs_refresh(state, snapshot)) then
        accessxi.current_speech_key = '';
        local ok_refresh, refresh_error = pcall(current_menu_speech, true);
        if (not ok_refresh) then
            if (type(module.clear) == 'function') then
                module.clear(state);
            end
            log_state(('state gear-detail refresh-error menu="%s" error="%s"'):fmt(
                accessxi.escape_probe_log_text(snapshot.current_menu),
                accessxi.escape_probe_log_text(tostring(refresh_error or ''))));
            return false;
        end
        snapshot.current_menu = tostring(get_menu_name() or '');
        snapshot.context_key = tostring(accessxi.current_speech_key or '');
        snapshot.now = tick();
    end

    local text, handled = module.poll(state, snapshot);
    if (handled ~= true) then
        return false;
    end
    if (text ~= nil and text ~= '') then
        speak(text, true);
        log_line(('gear detail line %d of %d menu="%s" text="%s"'):fmt(
            tonumber(state.index) or 0,
            type(state.lines) == 'table' and #state.lines or 0,
            accessxi.escape_probe_log_text(tostring(state.menu or '')),
            accessxi.escape_probe_log_text(text)));
    end
    return true;
end

function accessxi.clear_chat_log_deferred_speech()
    accessxi.chat_log_deferred_text = '';
    accessxi.chat_log_deferred_key = '';
    accessxi.chat_log_deferred_due = 0;
end

function accessxi.clear_chat_log_missing_retry()
    accessxi.chat_log_missing_retry_key = '';
    accessxi.chat_log_missing_retry_due = 0;
    accessxi.chat_log_missing_retry_count = 0;
end

function accessxi.chat_log_speech_hold_active(now)
    now = now or tick();
    return now < (accessxi.chat_log_speech_hold_until or 0);
end

function accessxi.queue_chat_log_speech(text, key, now)
    if (text == nil or text == '' or key == nil or key == '') then
        accessxi.clear_chat_log_deferred_speech();
        return;
    end

    accessxi.chat_log_deferred_text = text;
    accessxi.chat_log_deferred_key = key;
    accessxi.chat_log_deferred_due = now or tick();
end

function accessxi.clear_missions_menu_detail_deferred_speech()
    accessxi.missions_menu_detail_deferred_text = '';
    accessxi.missions_menu_detail_deferred_key = '';
    accessxi.missions_menu_detail_deferred_due = 0;
    accessxi.missions_menu_detail_deferred_context = '';
    accessxi.missions_menu_detail_deferred_label = '';
    accessxi.missions_menu_detail_deferred_selected = -1;
    accessxi.missions_menu_detail_deferred_count = -1;
end

function accessxi.clear_missions_menu_detail_hold()
    accessxi.missions_menu_detail_hold_until = 0;
    accessxi.missions_menu_detail_hold_context = '';
    accessxi.missions_menu_detail_hold_label = '';
    accessxi.missions_menu_detail_hold_selected = -1;
    accessxi.missions_menu_detail_hold_count = -1;
    accessxi.missions_menu_detail_hold_key = '';
end

function accessxi.missions_menu_detail_row_matches(context, label, selected, count)
    return tostring(context or '') == tostring(accessxi.missions_menu_detail_hold_context or '')
        and tostring(label or '') == tostring(accessxi.missions_menu_detail_hold_label or '')
        and (tonumber(selected) or -1) == (tonumber(accessxi.missions_menu_detail_hold_selected) or -1)
        and (tonumber(count) or -1) == (tonumber(accessxi.missions_menu_detail_hold_count) or -1);
end

function accessxi.missions_menu_detail_deferred_row_is_current()
    local expected_selected = tonumber(accessxi.missions_menu_detail_deferred_selected) or -1;
    local expected_count = tonumber(accessxi.missions_menu_detail_deferred_count) or -1;
    if (expected_selected <= 0) then
        return true;
    end

    local obj = get_current_menu_object_ptr();
    local selected, _, _, _, count = accessxi.survival_guide_query_child_state_for_obj(obj);
    selected = tonumber(selected) or 0;
    if (selected <= 0) then
        selected = read_current_native_menu_index(0x4C);
    end
    count = tonumber(count) or 0;
    if (selected > 0 and selected ~= expected_selected) then
        return false;
    end
    if (expected_count > 0 and count > 0 and count ~= expected_count) then
        return false;
    end
    return true;
end

function accessxi.queue_missions_menu_detail_deferred_speech(text, key, context, label, selected, count, hold_ms)
    text = tostring(text or '');
    key = tostring(key or '');
    if (text == '' or key == '') then
        accessxi.clear_missions_menu_detail_deferred_speech();
        return;
    end

    local now = tick();
    if (key == tostring(accessxi.missions_menu_detail_deferred_spoken_key or '')
        and accessxi.missions_menu_detail_row_matches(context, label, selected, count)) then
        accessxi.missions_menu_detail_hold_until = now + (tonumber(hold_ms) or accessxi.missions_menu_detail_hold_ms(text));
        return;
    end
    if (key ~= tostring(accessxi.missions_menu_detail_deferred_key or '')) then
        accessxi.missions_menu_detail_deferred_text = text;
        accessxi.missions_menu_detail_deferred_key = key;
        accessxi.missions_menu_detail_deferred_due = now + 850;
        accessxi.missions_menu_detail_deferred_context = tostring(context or '');
        accessxi.missions_menu_detail_deferred_label = tostring(label or '');
        accessxi.missions_menu_detail_deferred_selected = tonumber(selected) or -1;
        accessxi.missions_menu_detail_deferred_count = tonumber(count) or -1;
    end
    accessxi.missions_menu_detail_hold_until = now + (tonumber(hold_ms) or accessxi.missions_menu_detail_hold_ms(text));
    accessxi.missions_menu_detail_hold_context = tostring(context or '');
    accessxi.missions_menu_detail_hold_label = tostring(label or '');
    accessxi.missions_menu_detail_hold_selected = tonumber(selected) or -1;
    accessxi.missions_menu_detail_hold_count = tonumber(count) or -1;
    accessxi.missions_menu_detail_hold_key = key;
end

function accessxi.poll_missions_menu_detail_deferred_speech()
    local text = tostring(accessxi.missions_menu_detail_deferred_text or '');
    local key = tostring(accessxi.missions_menu_detail_deferred_key or '');
    if (text == '' or key == '') then
        return false;
    end

    local now = tick();
    if (now < (tonumber(accessxi.missions_menu_detail_deferred_due) or 0)) then
        return false;
    end

    if (not tostring(get_menu_name() or ''):eq('menu    miss00', true)) then
        accessxi.clear_missions_menu_detail_deferred_speech();
        return false;
    end

    if (not accessxi.missions_menu_detail_deferred_row_is_current()) then
        log_state(('state nativemenu mission-detail-deferred-cancel key="%s" selected=%d count=%d'):fmt(
            accessxi.escape_probe_log_text(key),
            tonumber(accessxi.missions_menu_detail_deferred_selected) or -1,
            tonumber(accessxi.missions_menu_detail_deferred_count) or -1));
        accessxi.clear_missions_menu_detail_deferred_speech();
        return false;
    end

    accessxi.clear_missions_menu_detail_deferred_speech();
    if (key == tostring(accessxi.missions_menu_detail_deferred_spoken_key or '')
        and (now - (tonumber(accessxi.missions_menu_detail_deferred_spoken_tick) or 0)) < 1000) then
        return false;
    end

    accessxi.missions_menu_detail_deferred_spoken_key = key;
    accessxi.missions_menu_detail_deferred_spoken_tick = now;
    accessxi.last = text;
    accessxi.last_key = key;
    accessxi.missions_menu_detail_speech_protect_until = now + 1200;
    local speak_result = speak(text, false);
    log_state(('state nativemenu mission-detail-deferred-speak result="%s" text="%s" key="%s"'):fmt(
        accessxi.escape_probe_log_text(speak_result or ''),
        accessxi.escape_probe_log_text(text),
        accessxi.escape_probe_log_text(key)));
    if (text ~= accessxi.last_log or key ~= accessxi.last_log_key) then
        accessxi.last_log = text;
        accessxi.last_log_key = key;
        log_line(text);
    end
    return true;
end

function accessxi.poll_missions_menu_detail_position_speech(menu_name)
    menu_name = tostring(menu_name or get_menu_name() or '');
    if (not menu_name:eq('menu    miss00', true)) then
        accessxi.reset_mission_detail_summary_surface();
        return false;
    end
    if (type(accessxi.detail_summary_navigation) ~= 'table'
        or type(accessxi.detail_summary_navigation.begin_surface) ~= 'function'
        or type(accessxi.detail_summary_navigation.current_line) ~= 'function') then
        accessxi.reset_mission_detail_summary_surface();
        return false;
    end

    local row = accessxi.last_missions_menu_detail_row;
    local cached_obj = tonumber(accessxi.last_missions_menu_detail_summary_obj) or 0;
    local context = tostring(accessxi.last_missions_menu_detail_summary_context or '');
    local row_age = (tonumber(accessxi.last_missions_menu_detail_summary_tick) or 0) > 0
        and (tick() - (tonumber(accessxi.last_missions_menu_detail_summary_tick) or 0))
        or 999999;
    local obj = get_current_menu_object_ptr();
    if (type(row) ~= 'table'
        or row_age > 30000
        or not accessxi.is_probe_pointer(obj)
        or obj ~= cached_obj) then
        accessxi.reset_mission_detail_summary_surface();
        return false;
    end

    local entry = read_u32(obj + 0x08);
    if (not accessxi.is_probe_pointer(entry)) then
        accessxi.reset_mission_detail_summary_surface();
        return false;
    end
    local _, desc_id = accessxi.missions_menu_descriptor_row(entry);
    if (not accessxi.missions_menu_detail_section_active(desc_id, row, entry)) then
        accessxi.reset_mission_detail_summary_surface();
        return false;
    end

    local position = tonumber(read_current_native_menu_index(0x4C)) or 0;
    local lines, lines_reason = accessxi.mission_detail_summary_lines(row);
    local surface_key = accessxi.mission_detail_summary_surface_key(menu_name, context, row, obj);
    if (position <= 0 or type(lines) ~= 'table' or #lines <= 0 or surface_key == '') then
        accessxi.reset_mission_detail_summary_surface();
        return false;
    end
    accessxi.last_missions_menu_detail_summary_tick = tick();

    if (surface_key ~= tostring(accessxi.last_missions_menu_detail_summary_surface_key or '')) then
        accessxi.detail_summary_navigation.begin_surface(
            accessxi.mission_detail_summary_state, surface_key, position);
        accessxi.missions_menu_detail_speech_protect_until = 0;
        return false;
    end

    local text, line_index, reason = accessxi.detail_summary_navigation.current_line(
        accessxi.mission_detail_summary_state, surface_key, position, lines);
    if (text == nil or text == '') then
        if (reason ~= 'unchanged-position') then
            local quiet_key = ('%s:%d:%s:%s'):fmt(surface_key, position, tostring(reason or ''), tostring(lines_reason or ''));
            if (quiet_key ~= tostring(accessxi.last_mission_detail_summary_quiet_key or '')) then
                accessxi.last_mission_detail_summary_quiet_key = quiet_key;
                log_state(('state mission summary-position-quiet menu="%s" position=%d lines=%d reason="%s" source="%s"'):fmt(
                    accessxi.escape_probe_log_text(menu_name),
                    position,
                    #lines,
                    accessxi.escape_probe_log_text(tostring(reason or '')),
                    accessxi.escape_probe_log_text(tostring(lines_reason or ''))));
            end
        end
        return true;
    end

    return accessxi.speak_detail_summary_position_line(
        'mission', menu_name, surface_key, position, line_index, text);
end

function accessxi.poll_chat_log_deferred_speech()
    local text = accessxi.chat_log_deferred_text or '';
    local key = accessxi.chat_log_deferred_key or '';
    if (text == '' or key == '') then
        return false;
    end

    local now = tick();
    if (now < (accessxi.chat_log_deferred_due or 0)) then
        return false;
    end

    if (not is_chat_log_menu_name(get_menu_name())) then
        accessxi.clear_chat_log_deferred_speech();
        return false;
    end

    accessxi.clear_chat_log_deferred_speech();
    if (key == (accessxi.chat_log_pending_spoken_key or '')) then
        return false;
    end

    accessxi.chat_log_pending_spoken_key = key;
    accessxi.last = text;
    accessxi.last_key = key;
    accessxi.chat_log_speech_hold_until = now + 650;
    local speak_result = speak(text);
    log_state(('state chatlog deferred-speak result="%s" text="%s"'):fmt(
        accessxi.escape_probe_log_text(speak_result or ''),
        accessxi.escape_probe_log_text(text)));
    if (text ~= accessxi.last_log or key ~= accessxi.last_log_key) then
        accessxi.last_log = text;
        accessxi.last_log_key = key;
        log_line(text);
    end
    return true;
end

function accessxi.poll_chat_log_missing_retry()
    local retry_key = tostring(accessxi.chat_log_missing_retry_key or '');
    if (retry_key == '') then
        return false;
    end

    local now = tick();
    if (now < (accessxi.chat_log_missing_retry_due or 0)) then
        return false;
    end

    local name = get_menu_name();
    if (not is_chat_log_menu_name(name)) then
        accessxi.clear_chat_log_missing_retry();
        return false;
    end
    if (tostring(name or ''):eq('menu    fulllog', true)) then
        accessxi.clear_chat_log_missing_retry();
        return false;
    end
    accessxi.current_speech_key = '';
    accessxi.chat_log_queue_immediate = false;
    local text = chat_log_menu_speech(name, false);
    local key = tostring(accessxi.current_speech_key or '');
    if (text ~= nil and text ~= '' and key:find('chatlog%-native:', 1, false) == 1) then
        accessxi.clear_chat_log_missing_retry();
        if (key == (accessxi.chat_log_pending_spoken_key or '')) then
            return false;
        end

        accessxi.chat_log_pending_spoken_key = key;
        accessxi.last = text;
        accessxi.last_key = key;
        accessxi.chat_log_speech_hold_until = now + 450;
        local speak_result = speak(text);
        log_state(('state chatlog missing-retry-speak result="%s" text="%s" key="%s"'):fmt(
            accessxi.escape_probe_log_text(speak_result or ''),
            accessxi.escape_probe_log_text(text),
            accessxi.escape_probe_log_text(key)));
        if (text ~= accessxi.last_log or key ~= accessxi.last_log_key) then
            accessxi.last_log = text;
            accessxi.last_log_key = key;
            log_line(text);
        end
        return true;
    end

    local count = (tonumber(accessxi.chat_log_missing_retry_count) or 0) + 1;
    accessxi.chat_log_missing_retry_count = count;
    if (count >= 3 or tostring(accessxi.chat_log_missing_retry_key or '') ~= retry_key) then
        if (tostring(accessxi.chat_log_missing_retry_key or '') == retry_key) then
            accessxi.clear_chat_log_missing_retry();
        end
        return false;
    end

    accessxi.chat_log_missing_retry_due = now + 70;
    return false;
end

function accessxi.poll_records_of_eminence_detail_position_speech()
    if (is_chat_input_open ~= nil and is_chat_input_open()) then
        return false;
    end

    local now = tick();
    local menu_name = tostring(get_menu_name() or '');
    if ((menu_name:eq('menu    quest01', true) or menu_name:eq('menu    quest00', true))
        and accessxi.records_of_eminence_quest01_detail_surface_active(menu_name)) then
        local row, record, reason = accessxi.records_of_eminence_detail_context_for_menu(menu_name);
        if (accessxi.records_of_eminence_summary_open_speech(menu_name, row, record, reason)) then
            return true;
        end
        if ((tonumber(accessxi.records_of_eminence_detail_watch_until) or 0) <= now) then
            accessxi.records_of_eminence_detail_watch_key = '';
        end
    end
    if (accessxi.records_of_eminence_detail_poll_suppressed()) then
        return false;
    end
    local quest00_detail_surface = menu_name:eq('menu    quest00', true)
        and accessxi.records_of_eminence_quest01_detail_surface_active(menu_name);
    if (not (menu_name:eq('menu    inline', true) or menu_name:eq('menu    comyn', true) or menu_name:eq('menu    quest01', true) or quest00_detail_surface)) then
        accessxi.log_records_of_eminence_detail_surface_probe(menu_name, 'unsupported-detail-surface');
        if ((tonumber(accessxi.records_of_eminence_detail_watch_until) or 0) <= now) then
            accessxi.records_of_eminence_detail_watch_key = '';
        end
        return false;
    end

    local row, record, reason = accessxi.records_of_eminence_detail_context_for_menu(menu_name);
    if (type(row) ~= 'table' or type(record) ~= 'table' or tostring(reason or '') == '') then
        if (menu_name:eq('menu    quest01', true)) then
            local signal = accessxi.records_of_eminence_quest01_row_signal();
            if (type(signal) == 'table' and (tonumber(signal.record_id) or 0) > 0 and (tonumber(signal.visible_count) or 0) >= 20) then
                local detail_index = read_current_native_menu_index(0x4C);
                local key = ('%s:%d:%d:%d:%d:0x%04X'):fmt(
                    menu_name,
                    tonumber(signal.record_id) or 0,
                    tonumber(signal.selected) or 0,
                    tonumber(signal.visible_count) or 0,
                    tonumber(detail_index) or 0,
                    tonumber(signal.slot_id) or 0);
                if (key ~= tostring(accessxi.last_records_of_eminence_detail_no_context_key or '')) then
                    accessxi.last_records_of_eminence_detail_no_context_key = key;
                    log_state(('state records-of-eminence detail-watch-no-context menu="%s" recordId=%d selected=%d visible=%d slotId=0x%04X detailIndex=%d surface=%s'):fmt(
                        menu_name,
                        tonumber(signal.record_id) or 0,
                        tonumber(signal.selected) or 0,
                        tonumber(signal.visible_count) or 0,
                        tonumber(signal.slot_id) or 0,
                        tonumber(detail_index) or 0,
                        tostring(accessxi.records_of_eminence_quest01_detail_surface_active(menu_name) == true)));
                end
            end
        end
        return false;
    end
    if (menu_name:eq('menu    quest01', true)
        and accessxi.records_of_eminence_quest01_row_signal_mismatches(row, reason)) then
        accessxi.records_of_eminence_clear_detail_watch('quest01-row-signal-mismatch');
        return false;
    end
    if (accessxi.records_of_eminence_should_hold_detail_lines(row)) then
        return true;
    end

    accessxi.current_speech_key = '';
    local text = accessxi.records_of_eminence_native_detail_surface_speech(menu_name, row, record, reason);
    if (text == nil or text == '') then
        if (tostring(reason or '') == 'direct-detail'
            or tostring(reason or '') == 'inline-detail') then
            return false;
        end
        accessxi.records_of_eminence_row_detail_speech(menu_name, row, record, reason);
        if (menu_name:eq('menu    quest01', true)
            and accessxi.records_of_eminence_quest01_row_signal_mismatches(row, ('empty-line:%s'):fmt(tostring(reason or '')))) then
            accessxi.records_of_eminence_clear_detail_watch('quest01-empty-line-row-signal-mismatch');
            return false;
        end
        return false;
    end

    local key = tostring(accessxi.current_speech_key or '');
    local suppress_cause = '';
    if (key == '') then
        suppress_cause = 'empty-key';
    elseif (key == tostring(accessxi.records_of_eminence_detail_watch_key or '')) then
        suppress_cause = 'watch-key';
    elseif (key == tostring(accessxi.last_key or '')) then
        suppress_cause = 'last-key';
    end
    if (suppress_cause ~= '') then
        local suppress_key = ('%s:%s:%s'):fmt(menu_name, tostring(reason or ''), key);
        if (suppress_key ~= tostring(accessxi.last_records_of_eminence_detail_watch_suppressed_key or '')) then
            accessxi.last_records_of_eminence_detail_watch_suppressed_key = suppress_key;
            log_state(('state records-of-eminence detail-watch-suppressed menu="%s" reason="%s" cause="%s" key="%s" watchKey="%s" lastKey="%s" text="%s"'):fmt(
                menu_name,
                accessxi.escape_probe_log_text(tostring(reason or '')),
                suppress_cause,
                accessxi.escape_probe_log_text(key),
                accessxi.escape_probe_log_text(tostring(accessxi.records_of_eminence_detail_watch_key or '')),
                accessxi.escape_probe_log_text(tostring(accessxi.last_key or '')),
                accessxi.escape_probe_log_text(text)));
        end
        return true;
    end

    accessxi.records_of_eminence_detail_watch_key = key;
    accessxi.last = text;
    accessxi.last_key = key;
    local speak_result = speak(text, false);
    accessxi.records_of_eminence_arm_detail_list_speech_suppression(row, text);
    log_state(('state records-of-eminence detail-watch-speak menu="%s" reason="%s" result="%s" key="%s" text="%s"'):fmt(
        menu_name,
        accessxi.escape_probe_log_text(tostring(reason or '')),
        accessxi.escape_probe_log_text(speak_result or ''),
        accessxi.escape_probe_log_text(key),
        accessxi.escape_probe_log_text(text)));
    if (text ~= accessxi.last_log or key ~= accessxi.last_log_key) then
        accessxi.last_log = text;
        accessxi.last_log_key = key;
        log_line(text);
    end
    return true;
end

local function poll_menu()
    local now = tick();
    if (is_chat_input_open ~= nil and is_chat_input_open()) then
        return;
    end

    local menu_name = get_menu_name();
    accessxi.records_of_eminence_poll_transition_surface_probe(menu_name);
    local poll_interval = is_chat_log_menu_name(menu_name) and 35 or 120;
    if ((tonumber(accessxi.key_items_inline_detail_candidate_until) or 0) >= now) then
        poll_interval = math.min(poll_interval, 35);
    end
    if ((tonumber(accessxi.search_result_packet_focus_until) or 0) >= now) then
        poll_interval = math.min(poll_interval, 35);
    end
    if (menu_name == nil or menu_name == '') then
        local target = safe_call(function () return AshitaCore:GetMemoryManager():GetTarget(); end, nil);
        local window_name = '';
        if (target ~= nil) then
            window_name = accessxi.plain_native_menu_label(safe_call(function () return target:GetWindowName(); end, '') or '');
        end
        local target_name = tostring(accessxi.last_target_name or '');
        if (window_name:eq('Door: Back to Town', true)
            or target_name:eq('Door: Back to Town', true)
            or target_name:eq('Door. Back to Town', true)
            or ((tonumber(accessxi.mog_door_area_pending_until) or 0) > now)
            or ((tonumber(accessxi.mog_door_blank_area_active_until) or 0) > now)) then
            poll_interval = 35;
        end
    end
    if ((now - accessxi.last_tick) < poll_interval) then
        return;
    end
    accessxi.last_tick = now;

    if (now < (accessxi.npc_text_hold_until or 0)) then
        return;
    end

    if (accessxi.poll_key_items_candidate_detail_speech(menu_name)) then
        return;
    end
    if (accessxi.poll_key_items_inline_detail_speech(menu_name)) then
        return;
    end
    if (accessxi.poll_missions_menu_detail_deferred_speech()) then
        return;
    end
    if (accessxi.poll_quests_menu_detail_deferred_speech()) then
        return;
    end
    if (accessxi.poll_missions_menu_detail_position_speech(menu_name)) then
        return;
    end
    if (accessxi.poll_quests_menu_detail_position_speech(menu_name)) then
        return;
    end
    if (tostring(menu_name or ''):eq('menu    miss00', true)
        and now < (tonumber(accessxi.missions_menu_detail_speech_protect_until) or 0)) then
        return;
    end
    if (tostring(menu_name or ''):eq('menu    quest01', true)
        and now < (tonumber(accessxi.quests_menu_detail_speech_protect_until) or 0)) then
        return;
    end

    local roe_context = tostring(accessxi.quests_menu_context or '');
    local roe_context_age = (tonumber(accessxi.quests_menu_context_tick) or 0) > 0
        and (now - (tonumber(accessxi.quests_menu_context_tick) or 0))
        or 999999;
    local roe_list_context = tostring(menu_name or ''):eq('menu    quest01', true)
        and roe_context_age <= 300000
        and (roe_context == 'records-of-eminence'
            or roe_context == 'records-of-eminence-objective-category'
            or roe_context == 'records-of-eminence-objective-catalog');
    if (roe_list_context) then
        accessxi.records_of_eminence_poll_detail_native_signal();
    end
    if (accessxi.poll_records_of_eminence_summary_open_speech(menu_name)) then
        return;
    end
    if (accessxi.poll_records_of_eminence_detail_position_speech()) then
        return;
    end
    local roe_summary_open_blocks_list = false;
    if (roe_list_context) then
        roe_summary_open_blocks_list = accessxi.records_of_eminence_summary_open_blocks_list_row();
    end
    if (roe_list_context
        and not accessxi.records_of_eminence_quest01_detail_surface_active(menu_name)
        and not accessxi.records_of_eminence_native_motion_detail_active(menu_name)
        and not roe_summary_open_blocks_list
        and not accessxi.records_of_eminence_detail_list_speech_suppressed()) then
        accessxi.current_speech_key = '';
        accessxi.chat_log_queue_immediate = false;
        local ok_roe_text, roe_text = pcall(current_menu_speech);
        if (not ok_roe_text) then
            log_state(('state menu-speech-error menu="%s" error="%s"'):fmt(
                accessxi.escape_probe_log_text(tostring(menu_name or '')),
                accessxi.escape_probe_log_text(tostring(roe_text or ''))));
            return;
        end
        local roe_key = tostring(accessxi.current_speech_key or '');
        if (roe_text ~= nil
            and roe_text ~= ''
            and roe_key:find('native-known-records-of-eminence', 1, true) == 1) then
            roe_text = accessxi.menu_row_speech_without_repeated_title(roe_text, menu_name, roe_key);
            accessxi.log_records_of_eminence_transition_list_row(menu_name, roe_text, roe_key);
            if ((tonumber(accessxi.records_of_eminence_detail_watch_until) or 0) > now) then
                accessxi.records_of_eminence_clear_detail_watch('roe-list-fast-path');
            end
            local roe_summary_return = accessxi.records_of_eminence_summary_return_matches_list_row(roe_key);
            local roe_changed = roe_summary_return or roe_text ~= accessxi.last or (roe_key ~= '' and roe_key ~= accessxi.last_key);
            if (roe_changed) then
                accessxi.records_of_eminence_suppress_detail_poll('roe-list-fast-path', 450);
                accessxi.last = roe_text;
                accessxi.last_key = roe_key;
                speak(roe_text);

                if (roe_text ~= accessxi.last_log or (roe_key ~= '' and roe_key ~= accessxi.last_log_key)) then
                    accessxi.last_log = roe_text;
                    accessxi.last_log_key = roe_key;
                    log_line(roe_text);
                end
                return;
            end

            return;
        end
    end

    accessxi.current_speech_key = '';
    accessxi.chat_log_queue_immediate = false;
    local ok_text, text = pcall(current_menu_speech);
    if (not ok_text) then
        log_state(('state menu-speech-error menu="%s" error="%s"'):fmt(
            accessxi.escape_probe_log_text(tostring(menu_name or '')),
            accessxi.escape_probe_log_text(tostring(text or ''))));
        return;
    end
    if (text == nil or text == '') then
        return;
    end

    local key = accessxi.current_speech_key or '';
    if (key:find('native-known-records-of-eminence', 1, true) == 1
        and accessxi.records_of_eminence_detail_list_speech_suppressed()) then
        return;
    end
    if (key:find('chatlog%-native:', 1, false) == 1) then
        if (accessxi.chat_log_queue_immediate == true) then
            accessxi.chat_log_pending_text = text;
            accessxi.chat_log_pending_key = key;
            accessxi.chat_log_pending_due = 0;
            if (key ~= (accessxi.chat_log_pending_spoken_key or '')) then
                accessxi.clear_chat_log_deferred_speech();
                accessxi.chat_log_pending_spoken_key = key;
                accessxi.last = text;
                accessxi.last_key = key;
                accessxi.chat_log_speech_hold_until = now + 450;
                local speak_result = speak(text);
                log_state(('state chatlog immediate-speak result="%s" text="%s"'):fmt(
                    accessxi.escape_probe_log_text(speak_result or ''),
                    accessxi.escape_probe_log_text(text)));
                if (text ~= accessxi.last_log or key ~= accessxi.last_log_key) then
                    accessxi.last_log = text;
                    accessxi.last_log_key = key;
                    log_line(text);
                end
            end
            return;
        end

        if (text ~= (accessxi.chat_log_pending_text or '')
            or key ~= (accessxi.chat_log_pending_key or '')) then
            accessxi.chat_log_pending_text = text;
            accessxi.chat_log_pending_key = key;
            accessxi.clear_chat_log_deferred_speech();
            local pending_delay = tonumber(accessxi.chat_log_pending_delay_override) or 0;
            accessxi.chat_log_pending_delay_override = 0;
            if (pending_delay <= 0) then
                pending_delay = 220;
            end
            accessxi.chat_log_pending_due = now + pending_delay;
            return;
        end

        if (now < (accessxi.chat_log_pending_due or 0)) then
            return;
        end

        if (key == (accessxi.chat_log_pending_spoken_key or '')) then
            return;
        end

        accessxi.queue_chat_log_speech(text, key, now);
        return;
    else
        accessxi.chat_log_pending_text = '';
        accessxi.chat_log_pending_key = '';
        accessxi.chat_log_pending_due = 0;
        accessxi.clear_chat_log_deferred_speech();
    end

    text = accessxi.menu_row_speech_without_repeated_title(text, menu_name, key);
    if (text == nil or text == '') then
        return;
    end

    if (text ~= accessxi.last or (key ~= '' and key ~= accessxi.last_key)) then
        accessxi.last = text;
        accessxi.last_key = key;
        speak(text);
        if (key:find('character%-creation:name:', 1, false) == 1) then
            accessxi.chat_input_speech_hold_until = now + 3200;
        end
    end

    if (text ~= accessxi.last_log or (key ~= '' and key ~= accessxi.last_log_key)) then
        accessxi.last_log = text;
        accessxi.last_log_key = key;
        log_line(text);
    end
end

local function chat_input_status()
    local chat = AshitaCore:GetChatManager();
    if (chat == nil) then
        return 0;
    end

    return tonumber(safe_call(function () return chat:IsInputOpen(); end, 0)) or 0;
end

is_chat_input_open = function ()
    return bit.band(chat_input_status(), 0x01) ~= 0;
end

local function chat_input_char_name(ch)
    if (ch == nil or ch == '') then
        return '';
    end
    if (ch == ' ') then
        return 'space';
    elseif (ch == '"') then
        return 'double quote';
    elseif (ch == "'") then
        return 'apostrophe';
    elseif (ch == '/') then
        return 'slash';
    elseif (ch == '\\') then
        return 'backslash';
    elseif (ch == '<') then
        return 'less than';
    elseif (ch == '>') then
        return 'greater than';
    elseif (ch == '`') then
        return 'backtick';
    elseif (ch == '\t') then
        return 'tab';
    end
    return ch;
end

local function chat_input_caret_speech(text, caret, previous_caret)
    text = tostring(text or '');
    caret = tonumber(caret) or 0;
    previous_caret = tonumber(previous_caret);
    local len = #text;
    if (len == 0) then
        return 'blank';
    end

    local char_index = caret;
    if (previous_caret ~= nil and caret < previous_caret) then
        char_index = caret + 1;
    elseif (previous_caret ~= nil and caret > previous_caret) then
        char_index = caret;
    elseif (caret <= 0) then
        char_index = 1;
    elseif (caret > len) then
        char_index = len;
    end

    if (char_index < 1) then
        char_index = 1;
    elseif (char_index > len) then
        char_index = len;
    end

    local ch = chat_input_char_name(text:sub(char_index, char_index));
    if (ch ~= '') then
        return ch;
    end
    return 'blank';
end

function accessxi.chat_input_edit_speech(previous_state, state)
    if (type(previous_state) ~= 'table' or state == nil) then
        return '';
    end

    local prior_raw = tostring(previous_state.raw or '');
    local current_raw = tostring(state.raw or '');
    local prior_caret = tonumber(previous_state.caret) or 0;
    local caret = tonumber(state.caret) or 0;

    if (#current_raw == (#prior_raw + 1) and caret == (prior_caret + 1)) then
        local ch = chat_input_char_name(current_raw:sub(caret, caret));
        if (ch ~= '') then
            return ch;
        end
    elseif ((#current_raw + 1) == #prior_raw) then
        local deleted = '';
        if (caret == (prior_caret - 1)) then
            deleted = prior_raw:sub(prior_caret, prior_caret);
        elseif (caret == prior_caret) then
            deleted = prior_raw:sub(caret + 1, caret + 1);
        end

        local ch = chat_input_char_name(deleted);
        if (ch ~= '') then
            return ('deleted %s'):fmt(ch);
        end
    end

    return '';
end

local function current_chat_input_state()
    local chat = AshitaCore:GetChatManager();
    if (chat == nil) then
        return nil;
    end

    local status = tonumber(safe_call(function () return chat:IsInputOpen(); end, 0)) or 0;
    if (bit.band(status, 0x01) == 0) then
        return nil;
    end

    local raw = clean_chat_input_text(safe_call(function () return chat:GetInputTextRaw(); end, ''));
    local display = accessxi.clean_chat_input_display_text(safe_call(function () return chat:GetInputTextDisplay(); end, ''));
    local caret = tonumber(safe_call(function () return chat:GetInputTextRawCaretPosition(); end, 0)) or 0;
    local length = tonumber(safe_call(function () return chat:GetInputTextRawLength(); end, #raw)) or #raw;
    local spoken = raw ~= '' and raw or display;
    if (raw == '' and accessxi.is_character_creation_text_input_menu_name(get_menu_name())) then
        spoken = '';
    end
    return T{
        status = status,
        raw = raw,
        display = display,
        spoken = spoken,
        caret = caret,
        length = length,
    };
end

local function chat_input_speech(state, just_opened)
    if (state == nil) then
        return nil, '';
    end

    if (accessxi.macro_detail_input_speech ~= nil) then
        local macro_text, macro_key = accessxi.macro_detail_input_speech(state, just_opened);
        if (macro_text ~= nil) then
            return macro_text, macro_key;
        end
    end

    local prior_text_key = accessxi.chat_input_last_text_key or '';
    local previous_state = accessxi.chat_input_last_state;
    local auto_translate_text, auto_translate_key, auto_translate_active = accessxi.chat_input_auto_translate_speech(previous_state, state);
    if (auto_translate_active) then
        return auto_translate_text, auto_translate_key;
    end

    local key = ('%d:%s:%d'):fmt(state.status or 0, state.raw or '', state.caret or 0);
    local text_key = ('%d:%s'):fmt(state.status or 0, state.raw or '');

    if (just_opened) then
        if (state.spoken == '') then
            return 'Chat input.', key;
        end
        return ('Chat input. %s'):fmt(state.spoken), key;
    end

    if (text_key ~= prior_text_key) then
        local edit_text = accessxi.chat_input_edit_speech(previous_state, state);
        if (edit_text ~= '') then
            return edit_text, key;
        end
        if (state.spoken == '') then
            return 'Chat input empty.', key;
        end
        return state.spoken, key;
    end

    if (key ~= (accessxi.chat_input_last_key or '')) then
        local previous_caret = nil;
        if (type(previous_state) == 'table' and previous_state.raw == state.raw) then
            previous_caret = previous_state.caret;
        end
        return chat_input_caret_speech(state.raw, state.caret, previous_caret), key;
    end

    return nil, key;
end

function accessxi.remember_chat_input_state(state, key)
    state = type(state) == 'table' and state or T{};
    accessxi.chat_input_open = true;
    accessxi.chat_input_last_key = tostring(key or '');
    accessxi.chat_input_last_text_key = ('%d:%s'):fmt(state.status or 0, state.raw or '');
    accessxi.chat_input_last_state = T{
        status = state.status or 0,
        raw = state.raw or '',
        display = state.display or '',
        spoken = state.spoken or '',
        caret = state.caret or 0,
        length = state.length or 0,
    };
end

local function poll_chat_input()
    local now = tick();
    if ((now - (accessxi.chat_input_last_tick or 0)) < 80) then
        return;
    end
    accessxi.chat_input_last_tick = now;

    local menu_name = get_menu_name();
    if (is_chat_log_menu_name(menu_name)) then
        accessxi.chat_input_open = false;
        accessxi.chat_input_last_key = '';
        accessxi.chat_input_last_text_key = '';
        accessxi.chat_input_last_state = nil;
        return;
    end

    local state = current_chat_input_state();
    if (state == nil) then
        if (accessxi.chat_input_open) then
            if (type(accessxi.note_axi_command_input_transition) == 'function') then
                accessxi.note_axi_command_input_transition(accessxi.chat_input_last_state, nil, menu_name, now);
            end
            accessxi.chat_input_open = false;
            accessxi.chat_input_last_key = '';
            accessxi.chat_input_last_text_key = '';
            accessxi.chat_input_last_state = nil;
        end
        return;
    end

    if (accessxi.is_character_creation_text_input_menu_name(menu_name)) then
        accessxi.remember_character_creation_name_from_input(menu_name, state.raw, 'chat-input');
    end

    local just_opened = not accessxi.chat_input_open;
    local previous_state = accessxi.chat_input_last_state;
    if (type(accessxi.note_axi_command_input_transition) == 'function') then
        accessxi.note_axi_command_input_transition(previous_state, state, menu_name, now);
    end
    accessxi.chat_input_open = true;
    if (just_opened) then
        local edge_key = ('%s:%s:%s:%d:%s'):fmt(
            tostring(menu_name or ''),
            tostring(accessxi.current_menu_name or ''),
            tostring(accessxi.last_nonblank_menu_name or ''),
            tonumber(state.status) or 0,
            tostring(state.raw or ''));
        if (edge_key ~= tostring(accessxi.character_creation_text_input_prompt_last_key or '')) then
            accessxi.character_creation_text_input_prompt_last_key = edge_key;
            log_state(('state character-creation text-input-edge menu="%s" current="%s" lastNonblank="%s" status=0x%02X raw="%s"'):fmt(
                accessxi.escape_probe_log_text(tostring(menu_name or '')),
                accessxi.escape_probe_log_text(tostring(accessxi.current_menu_name or '')),
                accessxi.escape_probe_log_text(tostring(accessxi.last_nonblank_menu_name or '')),
                tonumber(state.status) or 0,
                accessxi.escape_probe_log_text(tostring(state.raw or ''))));
        end
        if (accessxi.is_character_creation_text_input_menu_name(menu_name)) then
            local prompt_text, prompt_key = accessxi.character_creation_text_input_prompt_speech(menu_name, get_current_menu_object_ptr());
            if (prompt_text ~= nil and prompt_text ~= '') then
                local input_context = 'Chat input.';
                if (tostring(state.spoken or '') ~= '') then
                    input_context = ('Chat input. %s'):fmt(tostring(state.spoken or ''));
                end
                prompt_text = ('%s %s'):fmt(
                    accessxi.sentence_fragment(prompt_text),
                    accessxi.sentence_fragment(input_context));
                accessxi.current_speech_key = prompt_key;
                accessxi.last = prompt_text;
                accessxi.last_key = prompt_key;
                local input_key = ('%d:%s:%d'):fmt(state.status or 0, state.raw or '', state.caret or 0);
                accessxi.remember_chat_input_state(state, input_key);
                speak(prompt_text);
                if (prompt_text ~= accessxi.last_log or prompt_key ~= accessxi.last_log_key) then
                    accessxi.last_log = prompt_text;
                    accessxi.last_log_key = prompt_key;
                    log_line(prompt_text);
                end
                return;
            end
        end
    end
    local text, key = chat_input_speech(state, just_opened);
    if (now < (tonumber(accessxi.chat_input_speech_hold_until) or 0)) then
        accessxi.remember_chat_input_state(state, key);
        return;
    end

    accessxi.chat_input_last_text_key = ('%d:%s'):fmt(state.status or 0, state.raw or '');
    accessxi.chat_input_last_state = T{
        status = state.status or 0,
        raw = state.raw or '',
        display = state.display or '',
        spoken = state.spoken or '',
        caret = state.caret or 0,
        length = state.length or 0,
    };
    if (text == nil or text == '') then
        return;
    end

    if (key ~= accessxi.chat_input_last_key) then
        accessxi.chat_input_last_key = key;
        speak(text);
    end

    if (key ~= (accessxi.chat_input_last_log_key or '')) then
        accessxi.chat_input_last_log_key = key;
        log_line(('chat input status=0x%02X caret=%d len=%d raw="%s" display="%s" speech="%s"'):fmt(
            state.status or 0,
            state.caret or 0,
            state.length or 0,
            state.raw or '',
            state.display or '',
            text));
    end
end

function accessxi.target_window_only_label(raw_name)
    local name = accessxi.survival_guide_text(clean_login_text(raw_name or ''));
    if (name == '') then
        return '';
    end

    local destination = accessxi.survival_guide_text(name:match('^%s*Door:%s*(.-)%s*$') or '');
    if (destination ~= '') then
        return ('Door. %s'):fmt(destination);
    end
    if (name:eq('Door', true)) then
        return 'Door';
    end

    return '';
end

local function current_focus_target_speech()
    if (is_chat_input_open() or accessxi.nav_menu_open) then
        return nil, '';
    end

    local target = AshitaCore:GetMemoryManager():GetTarget();
    if (target == nil) then
        return nil, '';
    end

    if ((tonumber(safe_call(function () return target:GetIsMenuOpen(); end, 0)) or 0) ~= 0) then
        return nil, '';
    end

    local focus_index = tonumber(safe_call(function () return target:GetFocusTargetIndex(); end, -1)) or -1;
    local server_id = tonumber(safe_call(function () return target:GetFocusTargetServerId(); end, 0)) or 0;
    local window_server_id = tonumber(safe_call(function () return target:GetWindowServerId(); end, 0)) or 0;
    local window_loaded = tonumber(safe_call(function () return target:GetWindowIsWindowLoaded(); end, 0)) or 0;
    local window_hp = tonumber(safe_call(function () return target:GetWindowHPPercent(); end, -1)) or -1;
    local window_death = tonumber(safe_call(function () return target:GetWindowDeathFlag(); end, -1)) or -1;
    local window_name = clean_login_text(safe_call(function () return target:GetWindowName(); end, ''));
    local window_only_label = ((window_loaded ~= 0) and accessxi.target_window_only_label(window_name)) or '';
    local identity_parts = T{
        ('focus=%d:%d'):fmt(focus_index, server_id),
        ('window=%d:%d:%d:%d'):fmt(window_loaded, window_server_id, window_hp, window_death),
    };
    if (focus_index < 0) then
        if (window_only_label ~= '') then
            local key = ('%s:%s'):fmt(window_only_label, identity_parts:concat('|'));
            return ('Target. %s'):fmt(accessxi.sentence_fragment(accessxi.speech_name(window_only_label))), key, window_only_label, focus_index, server_id, window_server_id, window_loaded;
        end
        return nil, '';
    end

    local has_target_slot = false;
    local slot_target_index = -1;
    local slot_target_server_id = 0;
    for i = 0, 7 do
        local active = tonumber(safe_call(function () return target:GetIsActive(i); end, 0)) or 0;
        local arrow = tonumber(safe_call(function () return target:GetIsArrowActive(i); end, 0)) or 0;
        local target_index = tonumber(safe_call(function () return target:GetTargetIndex(i); end, -1)) or -1;
        local target_server_id = tonumber(safe_call(function () return target:GetServerId(i); end, 0)) or 0;
        local checksum = tonumber(safe_call(function () return target:GetChecksum(i); end, 0)) or 0;
        if (active ~= 0 or arrow ~= 0 or target_index > 0 or target_server_id ~= 0 or checksum ~= 0) then
            if ((active ~= 0 or arrow ~= 0) and target_index > 0 and target_server_id ~= 0) then
                has_target_slot = true;
                if (slot_target_index < 0) then
                    slot_target_index = target_index;
                    slot_target_server_id = target_server_id;
                end
            end
            identity_parts:append(('%d:%d:%d:%d:%d:%d'):fmt(
                i,
                active,
                arrow,
                target_index,
                target_server_id,
                checksum));
        end
    end
    local entity = safe_call(function () return AshitaCore:GetMemoryManager():GetEntity(); end, nil);
    local name = '';
    local spoken_index = slot_target_index;
    local spoken_server_id = slot_target_server_id;
    if (entity ~= nil and spoken_index > 0) then
        name = clean_login_text(safe_call(function () return entity:GetName(spoken_index); end, ''));
    end
    if (name == '' and entity ~= nil and focus_index > 0) then
        spoken_index = focus_index;
        spoken_server_id = server_id;
        name = clean_login_text(safe_call(function () return entity:GetName(focus_index); end, ''));
    end
    if (name == '' and has_target_slot and entity ~= nil and slot_target_index > 0) then
        spoken_index = slot_target_index;
        spoken_server_id = slot_target_server_id;
        name = clean_login_text(safe_call(function () return entity:GetName(slot_target_index); end, ''));
    end
    if (name == '') then
        if (window_only_label ~= '') then
            name = window_only_label;
        else
            name = window_name;
        end
    end
    if (name == '') then
        return nil, '';
    end

    local key = ('%s:%s'):fmt(name, identity_parts:concat('|'));
    return ('Target. %s.'):fmt(accessxi.speech_name(name)), key, name, spoken_index, spoken_server_id, window_server_id, window_loaded;
end

function accessxi.current_target_or_nearest_speech()
    local text = current_focus_target_speech();
    if (text ~= nil and text ~= '') then
        return text;
    end

    local nearby = nav_nearby(1, 8);
    if (nearby ~= nil and #nearby > 0) then
        local item = nearby[1];
        local kind = accessxi.nav_entity_kind(item);
        local name = accessxi.speech_name(item.name or '');
        if (name ~= '') then
            return ('Nearby %s. %s. %.0f yalms.'):fmt(kind, name, item.distance or 0);
        end
    end

    return 'No target or nearby object found.';
end

function accessxi.target_same_name_context(name, focus_index, server_id, window_server_id)
    name = nav_clean_field(name);
    if (name == '') then
        return 0, nil;
    end

    local player = nav_cached_player_position();
    local entity = safe_call(function () return AshitaCore:GetMemoryManager():GetEntity(); end, nil);
    if (entity == nil) then
        return 0, nil;
    end

    local size = tonumber(safe_call(function () return entity:GetEntityMapSize(); end, 0)) or 0;
    local matches = {};
    for i = 0, math.min(size - 1, 2303) do
        local entity_name = nav_clean_field(safe_call(function () return entity:GetName(i); end, ''));
        if (entity_name == name) then
            local x = tonumber(safe_call(function () return entity:GetLocalPositionX(i); end, nil));
            local z = tonumber(safe_call(function () return entity:GetLocalPositionY(i); end, nil));
            if (x ~= nil and z ~= nil and not (x == 0 and z == 0)) then
                local y = tonumber(safe_call(function () return entity:GetLocalPositionZ(i); end, 0)) or 0;
                local pos = T{ x = x, z = z, y = y };
                local distance = player ~= nil and nav_distance(player, pos) or 999999;
                if (distance <= 160) then
                    table.insert(matches, T{
                        index = i,
                        server_id = tonumber(safe_call(function () return entity:GetServerId(i); end, 0)) or 0,
                        distance = distance,
                    });
                end
            end
        end
    end

    table.sort(matches, function (a, b) return (a.distance or 999999) < (b.distance or 999999); end);
    if (#matches <= 1) then
        return #matches, nil;
    end

    for i, match in ipairs(matches) do
        if ((tonumber(focus_index) or -1) > 0 and match.index == focus_index)
            or ((tonumber(server_id) or 0) ~= 0 and match.server_id == server_id)
            or ((tonumber(window_server_id) or 0) ~= 0 and match.server_id == window_server_id) then
            return #matches, i;
        end
    end
    return #matches, nil;
end

local function poll_target()
    local now = tick();
    if ((now - accessxi.last_target_tick) < 150) then
        return;
    end
    accessxi.last_target_tick = now;

    local text, key, name, focus_index, server_id, window_server_id, window_loaded = current_focus_target_speech();
    if (text == nil or text == '') then
        return;
    end

    local force_tab_repeat = (now >= (accessxi.target_tab_force_after or 0)) and (now <= (accessxi.target_tab_force_until or 0));
    local player_moving = accessxi.nav_player_moving();
    if ((tonumber(window_loaded) or 0) == 0) then
        accessxi.last_target_key = '';
        return;
    end
    if (player_moving and not force_tab_repeat) then
        accessxi.last_target_key = key;
        return;
    end

    if (key ~= accessxi.last_target_key) then
        accessxi.last_target_key = key;
        accessxi.target_tab_force_until = 0;
        accessxi.target_tab_force_after = 0;
        local duplicate_count, duplicate_index = accessxi.target_same_name_context(name, focus_index, server_id, window_server_id);
        if (duplicate_count > 1) then
            if (duplicate_index == nil) then
                if (name == accessxi.last_target_name) then
                    accessxi.last_target_name_sequence = ((accessxi.last_target_name_sequence or 0) % duplicate_count) + 1;
                else
                    accessxi.last_target_name_sequence = 1;
                end
                duplicate_index = accessxi.last_target_name_sequence;
            end
            text = ('Target. %s. %d of %d.'):fmt(accessxi.speech_name(name), duplicate_index, duplicate_count);
        else
            accessxi.last_target_name_sequence = 0;
        end
        accessxi.last_target_name = name or '';
        speak(text);
    end

    if (key ~= accessxi.last_target_log) then
        accessxi.last_target_log = key;
        log_line(('target focus %s %s'):fmt(key, text));
    end
end

local function nav_route_suppressed()
    if (accessxi.nav_collision_control_interrupt_state ~= nil) then
        local active = accessxi.nav_collision_control_interrupt_state();
        return active == true;
    end

    if (is_chat_input_open() or accessxi.nav_menu_open) then
        return true;
    end

    local target = safe_call(function () return AshitaCore:GetMemoryManager():GetTarget(); end, nil);
    if (target ~= nil and ((tonumber(safe_call(function () return target:GetIsMenuOpen(); end, 0)) or 0) ~= 0)) then
        return true;
    end
    return false;
end

function accessxi.nav_note_movement_blocking_menu(menu_name, now)
    if (accessxi.nav_active ~= true) then
        return false;
    end

    menu_name = tostring(menu_name or '');
    if ((not menu_name:eq('menu    menuwind', true)) and (not menu_name:eq('menu    socialme', true))) then
        return false;
    end

    now = tonumber(now) or tick();
    local key = menu_name;
    if (key == tostring(accessxi.nav_movement_blocking_menu_last_key or '')
        and (now - (tonumber(accessxi.nav_movement_blocking_menu_last_tick) or 0)) < 12000) then
        return false;
    end

    accessxi.nav_movement_blocking_menu_last_key = key;
    accessxi.nav_movement_blocking_menu_last_tick = now;

    local label = tostring(accessxi.last_native_menu_label or '');
    local text = 'Main menu is open. Press Escape to move.';
    if (label ~= '') then
        text = ('Main menu is open on %s. Press Escape to move.'):fmt(accessxi.sentence_fragment(label));
    end

    speak(text, false);
    log_line(('nav movement blocked by main menu menu="%s" label="%s"'):fmt(
        accessxi.escape_probe_log_text(menu_name),
        accessxi.escape_probe_log_text(label)));
    return true;
end

function accessxi.nav_collision_control_interrupt_state()
    if (is_chat_input_open ~= nil and is_chat_input_open()) then
        return true, 'chat-input';
    end
    if (accessxi.nav_menu_open == true) then
        return true, 'nav-menu';
    end

    local menu_name = tostring(safe_call(function () return get_menu_name(); end, '') or '');
    if (menu_name ~= '') then
        accessxi.nav_note_movement_blocking_menu(menu_name, tick());
        return true, ('menu:%s'):fmt(menu_name);
    end

    local target = safe_call(function () return AshitaCore:GetMemoryManager():GetTarget(); end, nil);
    if (target ~= nil) then
        local menu_open = tonumber(safe_call(function () return target:GetIsMenuOpen(); end, 0)) or 0;
        if (menu_open ~= 0) then
            return true, ('target-menu:%d'):fmt(menu_open);
        end

        local menu_lock = tonumber(safe_call(function () return target:GetMenuTargetLock(); end, 0)) or 0;
        if (menu_lock ~= 0) then
            return true, ('target-lock:%d'):fmt(menu_lock);
        end
    end

    return false, '';
end

function accessxi.axi_drive_stop(reason)
    local was_active = (tonumber(accessxi.axi_drive_directinput_key) or 0) > 0;
    local direction = tostring(accessxi.axi_drive_direction or '');
    accessxi.axi_drive_directinput_key = 0;
    accessxi.axi_drive_until = 0;
    accessxi.axi_drive_direction = '';
    if (was_active) then
        log_line(('axi drive stopped direction=%s reason="%s"'):fmt(
            direction,
            accessxi.escape_probe_log_text(tostring(reason or 'stopped'))));
    end
    return was_active;
end

function accessxi.poll_axi_drive(now)
    local directinput_key = tonumber(accessxi.axi_drive_directinput_key) or 0;
    if (directinput_key <= 0) then
        return false;
    end

    now = tonumber(now) or tick();
    if ((type(accessxi.nav_zoning_watch_active) == 'function' and accessxi.nav_zoning_watch_active(now))
        or (type(accessxi.nav_zone_load_settle_active) == 'function' and accessxi.nav_zone_load_settle_active(now))) then
        return accessxi.axi_drive_stop('zoning');
    end
    if (now >= (tonumber(accessxi.axi_drive_until) or 0)) then
        return accessxi.axi_drive_stop('expired');
    end
    if (not accessxi.is_foreground_process()) then
        return accessxi.axi_drive_stop('foreground-lost');
    end

    local interrupted, reason = accessxi.nav_collision_control_interrupt_state();
    if (interrupted == true) then
        return accessxi.axi_drive_stop(('blocked:%s'):fmt(tostring(reason or 'game-input')));
    end
    return false;
end

function accessxi.axi_drive_command(args)
    local direction = tostring(args[3] or ''):trim():lower();
    if (direction:any('stop', 'off', '0')) then
        local stopped = accessxi.axi_drive_stop('manual');
        return stopped and 'Drive stopped.' or 'Drive is already stopped.';
    end
    if (direction ~= '2' and direction ~= '4' and direction ~= '6' and direction ~= '8') then
        return 'Drive needs numpad direction 2, 4, 6, or 8.';
    end
    if (not accessxi.is_foreground_process()) then
        return 'Drive blocked because Final Fantasy XI is not in the foreground.';
    end

    local interrupted, reason = accessxi.nav_collision_control_interrupt_state();
    if (interrupted == true) then
        return ('Drive blocked by %s.'):fmt(tostring(reason or 'game input'));
    end

    local duration = tonumber(args[4]) or 150;
    duration = math.floor(math.max(
        tonumber(accessxi.axi_drive_min_ms) or 50,
        math.min(duration, tonumber(accessxi.axi_drive_max_ms) or 500)));

    local virtual_key = accessxi.VK_NUMPAD2;
    if (direction == '4') then
        virtual_key = accessxi.VK_NUMPAD4;
    elseif (direction == '6') then
        virtual_key = accessxi.VK_NUMPAD6;
    elseif (direction == '8') then
        virtual_key = accessxi.VK_NUMPAD8;
    end

    local directinput_key = tonumber(safe_call(function ()
        return AshitaCore:GetInputManager():GetKeyboard():V2D(virtual_key);
    end, 0)) or 0;
    if (directinput_key <= 0 or directinput_key > 255) then
        return 'Drive blocked because the DirectInput key mapping is unavailable.';
    end

    accessxi.axi_drive_stop('replaced');
    accessxi.axi_drive_directinput_key = directinput_key;
    accessxi.axi_drive_until = tick() + duration;
    accessxi.axi_drive_direction = direction;
    log_line(('axi drive started direction=%s duration_ms=%d directinput_key=%d'):fmt(
        direction,
        duration,
        directinput_key));
    return ('Drive numpad %s for %d milliseconds.'):fmt(direction, duration);
end

function accessxi.nav_collision_update_control_interrupt(now)
    now = tonumber(now) or tick();
    local active, reason = accessxi.nav_collision_control_interrupt_state();
    reason = tostring(reason or '');
    local was_active = accessxi.nav_collision_control_interrupt_active == true;
    local last_reason = tostring(accessxi.nav_collision_control_interrupt_reason or '');

    if (active == true) then
        accessxi.nav_collision_control_interrupt_active = true;
        accessxi.nav_collision_control_interrupt_reason = reason;
        accessxi.nav_collision_control_interrupt_tick = now;
        accessxi.nav_collision_quiet('control-interrupt:' .. reason, accessxi.nav_collision_control_quiet_ms, now);

        local key = 'active:' .. reason;
        if (key ~= accessxi.nav_collision_control_last_log_key) then
            accessxi.nav_collision_control_last_log_key = key;
            log_line(('nav collision quiet control-interrupt reason="%s"'):fmt(accessxi.escape_probe_log_text(reason)));
        end
        return true, reason;
    end

    if (was_active) then
        accessxi.nav_collision_control_interrupt_active = false;
        accessxi.nav_collision_control_interrupt_reason = '';
        accessxi.nav_collision_control_interrupt_tick = now;
        local return_reason = last_reason ~= '' and last_reason or 'unknown';
        if ((return_reason:startswith('menu:') or return_reason:startswith('target-menu:'))
            and type(accessxi.nav_mission_quest_observe_event_menu) == 'function') then
            pcall(accessxi.nav_mission_quest_observe_event_menu, '', now);
        end
        accessxi.nav_collision_quiet('control-return:' .. return_reason, accessxi.nav_collision_control_return_quiet_ms, now);

        local key = 'return:' .. return_reason;
        if (key ~= accessxi.nav_collision_control_last_log_key) then
            accessxi.nav_collision_control_last_log_key = key;
            log_line(('nav collision quiet control-return reason="%s"'):fmt(accessxi.escape_probe_log_text(return_reason)));
        end
        return true, 'control-return:' .. return_reason;
    end

    return false, '';
end

function accessxi.nav_player_moving()
    local target = safe_call(function () return AshitaCore:GetMemoryManager():GetTarget(); end, nil);
    return target ~= nil and ((tonumber(safe_call(function () return target:GetIsPlayerMoving(); end, 0)) or 0) ~= 0);
end

function accessxi.nav_player_movement_signal(player, now)
    now = tonumber(now) or tick();
    local mm = safe_call(function () return AshitaCore:GetMemoryManager(); end, nil);
    local target = mm ~= nil and safe_call(function () return mm:GetTarget(); end, nil) or nil;
    local moving_now = target ~= nil and ((tonumber(safe_call(function () return target:GetIsPlayerMoving(); end, 0)) or 0) ~= 0);

    local auto_follow = mm ~= nil and safe_call(function () return mm:GetAutoFollow(); end, nil) or nil;
    local auto_running = auto_follow ~= nil and ((tonumber(safe_call(function () return auto_follow:GetIsAutoRunning(); end, 0)) or 0) ~= 0);

    local move_count = nil;
    local index = tonumber(player ~= nil and player.index or nil) or nav_player_index();
    local entity = mm ~= nil and safe_call(function () return mm:GetEntity(); end, nil) or nil;
    if (entity ~= nil and index ~= nil and index >= 0) then
        move_count = tonumber(safe_call(function () return entity:GetLocalMoveCount(index); end, nil));
    end
    if (move_count == nil) then
        local raw = safe_call(function () return GetPlayerEntity(); end, nil);
        move_count = tonumber(raw ~= nil and raw.LocalMoveCount or nil);
    end

    local move_count_changed = false;
    if (move_count ~= nil) then
        local previous = tonumber(accessxi.nav_movement_last_move_count);
        if (previous ~= nil and move_count ~= previous) then
            move_count_changed = true;
            accessxi.nav_movement_last_move_count_tick = now;
        end
        accessxi.nav_movement_last_move_count = move_count;
    end

    local actual_moved = false;
    local actual_delta = 0;
    if (player ~= nil and player.x ~= nil and player.z ~= nil) then
        if (accessxi.nav_movement_last_x ~= nil and accessxi.nav_movement_last_z ~= nil) then
            actual_delta = nav_distance(player, T{ x = accessxi.nav_movement_last_x, z = accessxi.nav_movement_last_z, y = player.y, zone = player.zone });
            if (actual_delta >= 0.18) then
                actual_moved = true;
                accessxi.nav_movement_recent_tick = now;
            end
        end
        accessxi.nav_movement_last_x = player.x;
        accessxi.nav_movement_last_z = player.z;
        accessxi.nav_movement_last_tick = now;
    end

    if (moving_now or auto_running or move_count_changed) then
        accessxi.nav_movement_recent_tick = now;
    end

    local recent_ms = tonumber(accessxi.nav_collision_recent_movement_ms) or 4200;
    local recent_tick = tonumber(accessxi.nav_movement_recent_tick) or 0;
    local move_count_recent = ((now - (tonumber(accessxi.nav_movement_last_move_count_tick) or 0)) <= recent_ms);
    local recent_movement = recent_tick > 0 and ((now - recent_tick) <= recent_ms);
    local input_intent = accessxi.nav_collision_forward_input_intent(now);
    local active = moving_now or auto_running or move_count_changed or move_count_recent or input_intent;
    local reason = 'idle';
    if (moving_now) then
        reason = 'moving';
    elseif (auto_running) then
        reason = 'autorun';
    elseif (move_count_changed or move_count_recent) then
        reason = 'move-count';
    elseif (input_intent) then
        reason = 'input-forward';
    elseif (recent_movement) then
        reason = 'recent-movement';
    end

    return T{
        active = active,
        moving = moving_now,
        autorun = auto_running,
        move_count_changed = move_count_changed,
        move_count_recent = move_count_recent,
        recent_movement = recent_movement,
        input_intent = input_intent,
        actual_moved = actual_moved,
        actual_delta = actual_delta,
        move_count = move_count,
        reason = reason,
    };
end

function accessxi.nav_collision_fresh_movement_intent(movement_signal)
    movement_signal = movement_signal or T{};
    return movement_signal.actual_moved == true
        or movement_signal.moving == true
        or movement_signal.autorun == true
        or movement_signal.move_count_changed == true
        or movement_signal.input_intent == true;
end

function accessxi.nav_collision_current_movement_intent(movement_signal)
    movement_signal = movement_signal or T{};
    return movement_signal.moving == true
        or movement_signal.autorun == true
        or movement_signal.move_count_changed == true
        or movement_signal.move_count_recent == true
        or movement_signal.input_intent == true;
end

function accessxi.nav_collision_reset(player, destination_distance, route_distance, now)
    accessxi.nav_collision_x = player ~= nil and player.x or nil;
    accessxi.nav_collision_z = player ~= nil and player.z or nil;
    accessxi.nav_collision_destination_distance = tonumber(destination_distance) or 0;
    accessxi.nav_collision_route_distance = tonumber(route_distance) or 0;
    accessxi.nav_collision_tick = tonumber(now) or tick();
end

function accessxi.nav_collision_forward_key(key)
    key = tonumber(key) or 0;
    return key == VK_UP or key == accessxi.VK_W or key == accessxi.VK_NUMPAD8;
end

function accessxi.nav_collision_note_movement_key(key, down)
    key = tonumber(key) or 0;
    if (not accessxi.nav_collision_forward_key(key)) then
        return false;
    end

    if (down == true) then
        accessxi.nav_collision_forward_intent_tick = tick();
        accessxi.nav_collision_forward_intent_key = key;
    elseif (key == (tonumber(accessxi.nav_collision_forward_intent_key) or 0)) then
        accessxi.nav_collision_forward_intent_tick = 0;
        accessxi.nav_collision_forward_intent_key = 0;
    end
    return true;
end

function accessxi.nav_collision_forward_input_intent(now)
    now = tonumber(now) or tick();
    local last = tonumber(accessxi.nav_collision_forward_intent_tick) or 0;
    local key = tonumber(accessxi.nav_collision_forward_intent_key) or 0;
    local window = tonumber(accessxi.nav_collision_input_intent_ms) or 1200;
    local hold_window = tonumber(accessxi.nav_collision_forward_hold_ms) or 30000;
    if (last <= 0 or key == 0) then
        return false;
    end
    return (now - last) <= math.max(window, hold_window);
end

function accessxi.nav_collision_state(player, destination, route_target, destination_distance, now, movement_signal)
    if (player == nil or destination == nil or route_target == nil) then
        return nil;
    end
    movement_signal = movement_signal or T{};
    if (not accessxi.nav_collision_current_movement_intent(movement_signal)) then
        accessxi.nav_collision_reset(nil, 0, 0, 0);
        return nil;
    end

    now = tonumber(now) or tick();
    destination_distance = tonumber(destination_distance) or nav_distance(player, destination);
    local route_distance = nav_distance(player, route_target);
    if (destination_distance <= accessxi.nav_arrival_radius(destination) or route_distance <= 7) then
        accessxi.nav_collision_reset(player, destination_distance, route_distance, now);
        return nil;
    end

    if (accessxi.nav_collision_x == nil or accessxi.nav_collision_z == nil or (tonumber(accessxi.nav_collision_tick) or 0) == 0) then
        accessxi.nav_collision_reset(player, destination_distance, route_distance, now);
        return nil;
    end

    local anchor = T{ x = accessxi.nav_collision_x, z = accessxi.nav_collision_z, y = player.y, zone = player.zone };
    local moved = nav_distance(player, anchor);
    local destination_improvement = (tonumber(accessxi.nav_collision_destination_distance) or destination_distance) - destination_distance;
    local route_improvement = (tonumber(accessxi.nav_collision_route_distance) or route_distance) - route_distance;
    if (moved >= 0.85 or route_improvement >= 0.65 or destination_improvement >= 0.65) then
        accessxi.nav_collision_reset(player, destination_distance, route_distance, now);
        return nil;
    end

    local elapsed = now - (tonumber(accessxi.nav_collision_tick) or 0);
    if (elapsed < 2600) then
        return nil;
    end

    local target_heading = accessxi.nav_heading_to(player, route_target);
    local yaw = tonumber(player.yaw);
    if (target_heading == nil or yaw == nil) then
        return nil;
    end
    if (math.abs(yaw) > (math.pi * 2.1)) then
        yaw = yaw * math.pi / 180;
    end
    local facing_delta = accessxi.nav_normalize_angle(target_heading + yaw);
    if (math.abs(facing_delta) > (math.pi * 0.42)) then
        return nil;
    end

    local step = math.max(1.8, math.min(3.2, route_distance - 1.0));
    local ahead = T{
        zone = player.zone,
        x = (tonumber(player.x) or 0) + (math.cos(target_heading) * step),
        z = (tonumber(player.z) or 0) + (math.sin(target_heading) * step),
        y = player.y,
    };
    local wall = accessxi.nav_wall_distance(player);
    local player_valid = accessxi.nav_valid_mesh_position(player);
    local ahead_valid = accessxi.nav_valid_mesh_position(ahead);
    if (wall == nil and not player_valid) then
        return nil;
    end
    local ahead_wall = ahead_valid and accessxi.nav_wall_distance(ahead) or nil;
    local route_blocked = (not ahead_valid) or (wall ~= nil and wall <= 1.15);
    local edge_contact = (wall ~= nil and wall <= 2.35) or (ahead_wall ~= nil and ahead_wall <= 1.25);
    if (not route_blocked and not edge_contact) then
        return nil;
    end

    local state = 'scraping';
    if ((moved <= 0.35 and route_improvement <= 0.25 and route_blocked) or (wall ~= nil and wall <= 0.85)) then
        state = 'blocked';
    end

    return T{
        state = state,
        moved = moved,
        route_improvement = route_improvement,
        destination_improvement = destination_improvement,
        elapsed = elapsed,
        wall = wall,
        ahead_valid = ahead_valid,
        ahead_wall = ahead_wall,
        facing_delta = facing_delta,
        route_distance = route_distance,
        intent = movement_signal.reason or '',
    };
end

function accessxi.nav_entity_is_verified_door(pos)
    if (pos == nil or tonumber(pos.type) ~= 3) then
        return false;
    end

    local name = nav_clean_field(pos.name or ''):lower();
    if (name == '' or name == '???') then
        return false;
    end
    return name:contains('door')
        or name:contains('gate')
        or name:contains('entrance')
        or name:contains('hatch')
        or name:contains('postern')
        or name:contains('portcullis')
        or name:contains('flap');
end

function accessxi.nav_verified_door_ahead(player, route_target)
    if (player == nil or route_target == nil) then
        return nil;
    end

    local route_x = (tonumber(route_target.x) or 0) - (tonumber(player.x) or 0);
    local route_z = (tonumber(route_target.z) or 0) - (tonumber(player.z) or 0);
    local route_length = math.sqrt((route_x * route_x) + (route_z * route_z));
    if (route_length < 0.25) then
        return nil;
    end
    local unit_x = route_x / route_length;
    local unit_z = route_z / route_length;
    local best = nil;
    local best_distance = nil;

    for _, pos in ipairs(accessxi.nav_live_entity_snapshot(80, 12)) do
        if (accessxi.nav_entity_is_verified_door(pos)
            and (tonumber(pos.zone) or 0) == (tonumber(player.zone) or 0)) then
            local entity_x = (tonumber(pos.x) or 0) - (tonumber(player.x) or 0);
            local entity_z = (tonumber(pos.z) or 0) - (tonumber(player.z) or 0);
            local ahead = (entity_x * unit_x) + (entity_z * unit_z);
            local side = math.abs((entity_x * unit_z) - (entity_z * unit_x));
            local distance = math.sqrt((entity_x * entity_x) + (entity_z * entity_z));
            if (ahead > 0 and ahead <= 12 and side <= 4.5 and distance <= 12
                and (best == nil or distance < best_distance)) then
                best = pos;
                best_distance = distance;
            end
        end
    end

    return best;
end

function accessxi.nav_door_wait_clear(reason)
    local active = (tonumber(accessxi.nav_door_wait_until) or 0) > 0;
    local name = tostring(accessxi.nav_door_wait_name or '');
    accessxi.nav_door_wait_until = 0;
    accessxi.nav_door_pause_until = 0;
    accessxi.nav_door_x = nil;
    accessxi.nav_door_z = nil;
    accessxi.nav_door_route_unit_x = nil;
    accessxi.nav_door_route_unit_z = nil;
    accessxi.nav_door_wait_key = '';
    accessxi.nav_door_wait_name = '';
    if (active) then
        log_line(('nav door wait clear reason="%s" name="%s"'):fmt(
            accessxi.escape_probe_log_text(reason or ''),
            accessxi.escape_probe_log_text(name)));
    end
end

function accessxi.nav_door_context_active(now)
    now = tonumber(now) or tick();
    return (tonumber(accessxi.nav_door_wait_until) or 0) > now;
end

function accessxi.nav_door_waiting(player, now)
    now = tonumber(now) or tick();
    local until_tick = tonumber(accessxi.nav_door_wait_until) or 0;
    if (until_tick <= 0) then
        return false;
    end
    if (now >= until_tick) then
        accessxi.nav_door_wait_clear('timeout');
        return false;
    end

    if (player ~= nil
        and accessxi.nav_door_x ~= nil
        and accessxi.nav_door_z ~= nil
        and accessxi.nav_door_route_unit_x ~= nil
        and accessxi.nav_door_route_unit_z ~= nil) then
        local dx = (tonumber(player.x) or 0) - (tonumber(accessxi.nav_door_x) or 0);
        local dz = (tonumber(player.z) or 0) - (tonumber(accessxi.nav_door_z) or 0);
        local progress = (dx * (tonumber(accessxi.nav_door_route_unit_x) or 0))
            + (dz * (tonumber(accessxi.nav_door_route_unit_z) or 0));
        if (progress >= 1.25) then
            accessxi.nav_door_wait_clear('crossed-route-plane');
            return false;
        end
    end

    return now < (tonumber(accessxi.nav_door_pause_until) or 0);
end

function accessxi.nav_door_begin_prompt(player, destination, route_target, door, state, now, source)
    if (player == nil or route_target == nil or door == nil) then
        return false, false;
    end

    local route_x = (tonumber(route_target.x) or 0) - (tonumber(player.x) or 0);
    local route_z = (tonumber(route_target.z) or 0) - (tonumber(player.z) or 0);
    local route_length = math.sqrt((route_x * route_x) + (route_z * route_z));
    if (route_length < 0.25) then
        return false, false;
    end

    now = tonumber(now) or tick();
    local key = ('%d:%d:%s'):fmt(
        tonumber(door.index) or -1,
        tonumber(door.server_id) or 0,
        tostring(door.name or ''));
    if (key == tostring(accessxi.nav_door_wait_key or '')
        and now < (tonumber(accessxi.nav_door_wait_until) or 0)) then
        return false, true;
    end

    local name = nav_clean_field(door.name or 'door');
    accessxi.nav_door_wait_until = now + 15000;
    accessxi.nav_door_pause_until = now + 2500;
    accessxi.nav_door_x = tonumber(door.x);
    accessxi.nav_door_z = tonumber(door.z);
    accessxi.nav_door_route_unit_x = route_x / route_length;
    accessxi.nav_door_route_unit_z = route_z / route_length;
    accessxi.nav_door_wait_key = key;
    accessxi.nav_door_wait_name = name;

    local text = ('Door ahead: %s. Press Tab until %s is targeted, then press Enter to open it. Navigation will resume with the beacon through the doorway.'):fmt(name, name);
    nav_write_route_evidence('door', player, destination, door, T{
        wall = state ~= nil and state.wall or nil,
        off_route = state ~= nil and state.route_distance or 0,
        moved = state ~= nil and state.moved or 0,
        improve = state ~= nil and state.route_improvement or 0,
        reason = text,
    });
    speak(text);
    log_line(('nav door prompt source=%s name="%s" index=%d server=%d distance=%.1f route=(%.3f,%.3f) %s'):fmt(
        tostring(source or 'route'),
        accessxi.escape_probe_log_text(name),
        tonumber(door.index) or -1,
        tonumber(door.server_id) or 0,
        nav_distance(player, door),
        accessxi.nav_door_route_unit_x or 0,
        accessxi.nav_door_route_unit_z or 0,
        text));
    return true, true;
end

function accessxi.nav_door_prompt_for_route(player, destination, route_target, now)
    local door = accessxi.nav_verified_door_ahead(player, route_target);
    if (door == nil or nav_distance(player, door) > 6) then
        return false;
    end

    local prompted = accessxi.nav_door_begin_prompt(
        player, destination, route_target, door, nil, now, 'route');
    return prompted == true;
end

function accessxi.nav_door_prompt_for_collision(player, destination, route_target, state, now)
    if (state == nil or state.state ~= 'blocked') then
        return false;
    end

    local door = accessxi.nav_verified_door_ahead(player, route_target);
    if (door == nil) then
        return false;
    end

    local _, handled = accessxi.nav_door_begin_prompt(
        player, destination, route_target, door, state, now, 'collision');
    return handled == true;
end

function accessxi.nav_collision_watch(player, destination, route_target, destination_distance, now, movement_signal)
    now = tonumber(now) or tick();
    if (now < (tonumber(accessxi.nav_collision_quiet_until) or 0)) then
        accessxi.nav_collision_reset(nil, 0, 0, now);
        return false;
    end

    movement_signal = movement_signal or accessxi.nav_player_movement_signal(player, now);
    local state = accessxi.nav_collision_state(player, destination, route_target, destination_distance, now, movement_signal);
    if (state == nil) then
        return false;
    end

    if (accessxi.nav_door_prompt_for_collision(player, destination, route_target, state, now)) then
        accessxi.nav_collision_play_sound(state.state, now);
        accessxi.nav_collision_reset(player, destination_distance, state.route_distance, now);
        return true;
    end

    local key = ('%s:%s:%d:%d'):fmt(
        state.state or '',
        destination ~= nil and destination.name or '',
        math.floor((tonumber(player ~= nil and player.x or 0) or 0) * 2),
        math.floor((tonumber(player ~= nil and player.z or 0) or 0) * 2));
    accessxi.nav_collision_last_sound_tick = now;
    accessxi.nav_collision_last_key = key;

    local text;
    if (state.state == 'blocked') then
        accessxi.nav_wall_escape_begin_recovery(now);
        text = 'Collision detected. You are not moving forward. Turn until the beacon moves off-center, then go forward.';
    else
        text = 'Edge contact. You are scraping a wall. Steer away from the wall, then continue.';
    end
    if (state.wall ~= nil and state.wall <= 3) then
        text = text .. (' Clearance %.0f yalm.'):fmt(state.wall);
    end

    nav_write_route_evidence('collision', player, destination, route_target, T{
        wall = state.wall,
        off_route = state.route_distance,
        moved = state.moved,
        improve = state.route_improvement,
        reason = text,
    });
    local sound_ok = accessxi.nav_collision_play_sound(state.state, now);
    log_line(('nav collision state=%s intent=%s moved=%.2f improve=%.2f elapsed=%d wall=%s ahead=%s facing=%.0f sound=%s %s'):fmt(
        state.state or '',
        state.intent or '',
        state.moved or 0,
        state.route_improvement or 0,
        state.elapsed or 0,
        state.wall ~= nil and ('%.2f'):fmt(state.wall) or 'unknown',
        state.ahead_valid and 'valid' or 'blocked',
        (state.facing_delta or 0) * 180 / math.pi,
        sound_ok and 'ok' or 'failed',
        text));
    accessxi.nav_collision_reset(player, destination_distance, state.route_distance, now);
    return true;
end

function accessxi.nav_freewalk_collision_reset(player, now)
    accessxi.nav_collision_freewalk_x = player ~= nil and player.x or nil;
    accessxi.nav_collision_freewalk_z = player ~= nil and player.z or nil;
    accessxi.nav_collision_freewalk_yaw = player ~= nil and player.yaw or nil;
    accessxi.nav_collision_freewalk_tick = tonumber(now) or tick();
end

function accessxi.nav_freewalk_collision_state(player, now, movement_signal)
    if (player == nil) then
        accessxi.nav_freewalk_collision_reset(nil, now);
        return nil;
    end
    movement_signal = movement_signal or T{};
    if (movement_signal.active ~= true) then
        accessxi.nav_freewalk_collision_reset(nil, now);
        return nil;
    end

    now = tonumber(now) or tick();
    local recent_tick = tonumber(accessxi.nav_movement_recent_tick) or 0;
    local recent_age = recent_tick > 0 and (now - recent_tick) or 999999;
    if (movement_signal.moving ~= true
        and movement_signal.autorun ~= true
        and movement_signal.move_count_recent ~= true
        and movement_signal.input_intent ~= true) then
        accessxi.nav_freewalk_collision_reset(nil, now);
        return nil;
    end

    local yaw = tonumber(player.yaw);
    if (yaw == nil) then
        return nil;
    end
    if (math.abs(yaw) > (math.pi * 2.1)) then
        yaw = yaw * math.pi / 180;
    end
    local heading = -yaw;
    local ahead = T{
        zone = player.zone,
        x = (tonumber(player.x) or 0) + (math.cos(heading) * 2.8),
        z = (tonumber(player.z) or 0) + (math.sin(heading) * 2.8),
        y = player.y,
    };

    local wall = accessxi.nav_wall_distance(player);
    local player_valid = accessxi.nav_valid_mesh_position(player);
    local ahead_valid = accessxi.nav_valid_mesh_position(ahead);
    if (wall == nil and player_valid ~= true and ahead_valid ~= true) then
        return nil;
    end
    local ahead_wall = ahead_valid and accessxi.nav_wall_distance(ahead) or nil;
    local blocked = (ahead_valid == false) or (wall ~= nil and wall <= 1.45);
    local near_wall = (wall ~= nil and wall <= 2.35) or (ahead_wall ~= nil and ahead_wall <= 1.25);
    if (not blocked and not near_wall) then
        accessxi.nav_freewalk_collision_reset(player, now);
        return nil;
    end

    if (accessxi.nav_collision_freewalk_x == nil or accessxi.nav_collision_freewalk_z == nil or (tonumber(accessxi.nav_collision_freewalk_tick) or 0) == 0) then
        accessxi.nav_freewalk_collision_reset(player, now);
        return nil;
    end

    local anchor = T{ zone = player.zone, x = accessxi.nav_collision_freewalk_x, z = accessxi.nav_collision_freewalk_z, y = player.y };
    local moved = nav_distance(player, anchor);
    if (moved >= 0.42) then
        accessxi.nav_freewalk_collision_reset(player, now);
        return nil;
    end
    local anchor_yaw = tonumber(accessxi.nav_collision_freewalk_yaw);
    if (anchor_yaw ~= nil and moved < 0.22) then
        if (math.abs(anchor_yaw) > (math.pi * 2.1)) then
            anchor_yaw = anchor_yaw * math.pi / 180;
        end
        local turn_delta = math.abs(accessxi.nav_normalize_angle(yaw - anchor_yaw));
        if (turn_delta >= (tonumber(accessxi.nav_collision_freewalk_turn_radians) or 0.18)) then
            accessxi.nav_freewalk_collision_reset(player, now);
            return nil;
        end
    end

    local elapsed = now - (tonumber(accessxi.nav_collision_freewalk_tick) or 0);
    if (elapsed < (tonumber(accessxi.nav_collision_freewalk_hold_ms) or 700)) then
        return nil;
    end

    return T{
        state = blocked and 'blocked' or 'scraping',
        moved = moved,
        elapsed = elapsed,
        wall = wall,
        ahead_valid = ahead_valid,
        ahead_wall = ahead_wall,
        intent = movement_signal.reason or '',
        recent_age = recent_age,
    };
end

function accessxi.poll_nav_collision_sound()
    local now = tick();
    if ((now - (tonumber(accessxi.nav_collision_freewalk_last_poll_tick) or 0)) < (tonumber(accessxi.nav_collision_freewalk_poll_ms) or 250)) then
        return false;
    end
    accessxi.nav_collision_freewalk_last_poll_tick = now;

    if (accessxi.nav_collision_update_control_interrupt(now)) then
        accessxi.nav_freewalk_collision_reset(nil, now);
        return false;
    end

    if (now < (tonumber(accessxi.nav_collision_quiet_until) or 0)) then
        accessxi.nav_freewalk_collision_reset(nil, now);
        return false;
    end

    if (nav_route_suppressed()) then
        accessxi.nav_freewalk_collision_reset(nil, now);
        return false;
    end

    if (accessxi.nav_active == true and accessxi.nav_destination ~= nil) then
        accessxi.nav_freewalk_collision_reset(nil, now);
        return false;
    end

    local player = nav_cached_player_position();
    local movement_signal = accessxi.nav_player_movement_signal(player, now);
    if (accessxi.nav_collision_require_fresh_movement == true) then
        if (accessxi.nav_collision_fresh_movement_intent(movement_signal)) then
            accessxi.nav_collision_require_fresh_movement = false;
        else
            accessxi.nav_freewalk_collision_reset(nil, now);
            return false;
        end
    end

    local state = accessxi.nav_freewalk_collision_state(player, now, movement_signal);
    if (state == nil) then
        return false;
    end

    if ((now - (tonumber(accessxi.nav_collision_freewalk_last_sound_tick) or 0)) < (tonumber(accessxi.nav_collision_freewalk_sound_ms) or 900)) then
        return true;
    end
    accessxi.nav_collision_freewalk_last_sound_tick = now;

    local sound_ok = accessxi.nav_collision_play_sound('blocked', now);
    local key = ('%s:%s:%d:%d'):fmt(
        state.state or '',
        state.intent or '',
        math.floor((tonumber(player ~= nil and player.x or 0) or 0) * 2),
        math.floor((tonumber(player ~= nil and player.z or 0) or 0) * 2));
    if (key ~= accessxi.nav_collision_freewalk_last_log_key or sound_ok ~= true) then
        accessxi.nav_collision_freewalk_last_log_key = key;
        log_line(('nav collision freewalk state=%s intent=%s moved=%.2f elapsed=%d wall=%s ahead=%s recent=%d sound=%s'):fmt(
            state.state or '',
            state.intent or '',
            state.moved or 0,
            state.elapsed or 0,
            state.wall ~= nil and ('%.2f'):fmt(state.wall) or 'unknown',
            state.ahead_valid and 'valid' or 'blocked',
            state.recent_age or 0,
            sound_ok and 'ok' or 'failed'));
    end
    accessxi.nav_freewalk_collision_reset(player, now);
    return true;
end

function accessxi.nav_route_contact_sound(player, route_target, now, movement_signal)
    if (player == nil or route_target == nil) then
        return false;
    end
    now = tonumber(now) or tick();
    if (now < (tonumber(accessxi.nav_collision_quiet_until) or 0)) then
        return false;
    end

    movement_signal = movement_signal or T{};
    if (not accessxi.nav_collision_current_movement_intent(movement_signal)) then
        return false;
    end
    if (movement_signal.actual_moved == true) then
        return false;
    end

    local wall = accessxi.nav_wall_distance(player);
    if (wall == nil or wall > 0.8) then
        return false;
    end

    local interval = tonumber(accessxi.nav_collision_route_contact_sound_ms) or 1300;
    if ((now - (tonumber(accessxi.nav_collision_route_contact_last_sound_tick) or 0)) < interval) then
        return true;
    end
    accessxi.nav_collision_route_contact_last_sound_tick = now;

    local route_distance = nav_distance(player, route_target);
    local sound_ok = accessxi.nav_collision_play_sound('blocked', now);
    local key = ('%d:%d:%d'):fmt(
        math.floor((tonumber(player.x) or 0) * 2),
        math.floor((tonumber(player.z) or 0) * 2),
        math.floor((tonumber(wall) or 0) * 10));
    if (key ~= accessxi.nav_collision_route_contact_last_log_key or sound_ok ~= true) then
        accessxi.nav_collision_route_contact_last_log_key = key;
        log_line(('nav collision contact intent=%s route=%.1f wall=%.2f sound=%s'):fmt(
            tostring(movement_signal.reason or ''),
            route_distance,
            wall,
            sound_ok and 'ok' or 'failed'));
    end
    return sound_ok;
end

function accessxi.nav_current_route_instruction()
    if (not accessxi.nav_active or accessxi.nav_destination == nil) then
        return '';
    end

    local player = nav_cached_player_position();
    if (player == nil) then
        return accessxi.nav_last_direction_text or '';
    end

    local destination = accessxi.nav_destination;
    if (accessxi.nav_objective_route_state ~= nil) then
        local objective_state = accessxi.nav_objective_route_state;
        local owner_current, owner_reason = accessxi.nav_objective_route_revalidate_or_cancel(player);
        if (not owner_current) then
            local text = nav_clean_field(owner_reason) ~= '' and nav_clean_field(owner_reason)
                or 'The active objective route changed.';
            speak(text);
            log_line('nav objective owner blocked ' .. text);
            return;
        end
        if (type(accessxi.nav_objective_transport_active) == 'function'
            and accessxi.nav_objective_transport_active()) then
            local authorization = objective_state.objective_transition_authorization;
            if (type(authorization) ~= 'table') then
                accessxi.nav_cancel_mission_quest_route('objective-transition-authorization-missing');
                speak('Objective transition authorization changed.');
                return;
            end
            local live_state = '';
            local post_anchor = authorization.objective_transition_post_anchor;
            if (type(post_anchor) == 'table'
                and tonumber(player.zone) == tonumber(authorization.objective_transition_zone)
                and nav_distance(player, post_anchor) <= 3.5
                and math.abs((tonumber(player.y) or 0) - (tonumber(post_anchor.y) or 0)) <= 3.0) then
                live_state = authorization.objective_transition_expected_live_state;
            end
            local poll_ok, handled, transport_reason = pcall(
                accessxi.nav_objective_transport_poll,
                player,
                destination,
                authorization,
                live_state,
                now);
            if (not poll_ok or handled ~= true) then
                local text = nav_clean_field(poll_ok and transport_reason or '') ~= ''
                    and nav_clean_field(transport_reason)
                    or 'Objective transition changed and was cancelled.';
                accessxi.nav_cancel_mission_quest_route('objective-transition-changed');
                speak(text);
                log_line('nav objective transition blocked ' .. text);
            elseif (not accessxi.nav_objective_transport_active()) then
                objective_state.objective_transition_authorization = nil;
            end
            return;
        end

        local prefix_descriptor = objective_state.objective_prefix_descriptor;
        if ((tonumber(destination.zone) or 0) ~= (tonumber(player.zone) or 0)) then
            if (type(prefix_descriptor) == 'table'
                and nav_clean_field(prefix_descriptor.stage) == 'prefix'
                and tonumber(player.zone) == tonumber(prefix_descriptor.to_zone)) then
                local ok, text, started = pcall(
                    accessxi.nav_start_authorized_objective_route,
                    objective_state,
                    player);
                if (ok and started == true) then
                    speak(nav_clean_field(text) ~= '' and nav_clean_field(text)
                        or 'Continuing verified objective route.');
                    log_line('nav objective zone continuation');
                    return;
                end
                accessxi.nav_cancel_mission_quest_route('objective-zone-continuation-blocked');
                text = nav_clean_field(ok and text or '') ~= '' and nav_clean_field(text)
                    or 'No exact objective route continues from the new zone.';
                speak(text);
                log_line('nav objective zone continuation blocked ' .. text);
                return;
            end
            accessxi.nav_cancel_mission_quest_route('objective-player-left-expected-zone');
            speak('Objective route stopped because the zone change was not authorized.');
            return;
        end
        local arrival_radius = math.max(1.5, tonumber(accessxi.nav_arrival_radius(destination)) or 0);
        if (nav_distance(player, destination) <= arrival_radius
            and math.abs((tonumber(player.y) or 0) - (tonumber(destination.y) or 0)) <= 4.0) then
            if (type(prefix_descriptor) == 'table'
                and nav_clean_field(prefix_descriptor.stage) == 'prefix') then
                accessxi.nav_last_direction_text = 'At the verified zone line. Continue into the next zone.';
                return accessxi.nav_last_direction_text;
            end
            local text = ('Arrived at %s.'):fmt(destination.name or 'objective destination');
            if (type(accessxi.nav_mission_quest_remember_arrival) == 'function') then
                pcall(function ()
                    accessxi.nav_mission_quest_remember_arrival(destination, now);
                end);
            end
            accessxi.nav_active = false;
            accessxi.nav_destination = nil;
            accessxi.nav_objective_route_state = nil;
            accessxi.nav_route_points:clear();
            accessxi.nav_route_point_index = 1;
            accessxi.nav_last_direction_text = text;
            speak(text);
            log_line('nav objective arrived ' .. text);
            return;
        end
        if ((now - (tonumber(accessxi.nav_route_last_recalc_tick) or 0)) >= 1000) then
            accessxi.nav_route_last_recalc_tick = now;
            if (type(prefix_descriptor) == 'table'
                and nav_clean_field(prefix_descriptor.stage) == 'prefix') then
                local ok, _text, started = pcall(
                    accessxi.nav_start_authorized_objective_route,
                    objective_state,
                    player);
                if (not ok or started ~= true) then
                    local text = nav_clean_field(ok and _text or '') ~= '' and nav_clean_field(_text)
                        or 'No exact current objective prefix is proven from here.';
                    accessxi.nav_cancel_mission_quest_route('objective-prefix-leg-changed');
                    speak(text);
                    log_line('nav objective prefix blocked ' .. text);
                end
                return;
            end
            if (not nav_try_load_mesh(player.zone)) then
                accessxi.nav_cancel_mission_quest_route('objective-mesh-unavailable');
                speak('The rooted objective navmesh is unavailable for this zone.');
                return;
            end
            local exact, exact_reason = accessxi.nav_compute_exact_objective_leg({
                zone = player.zone,
                objective_route_contract_id = objective_state.objective_route_contract_id,
                start = { x = player.x, z = player.z, y = player.y, zone = player.zone },
                ['end'] = {
                    x = destination.x,
                    z = destination.z,
                    y = destination.y,
                    zone = destination.zone,
                },
            });
            if (type(exact) ~= 'table' or #exact < 2) then
                local text = nav_clean_field(exact_reason) ~= '' and nav_clean_field(exact_reason)
                    or 'No exact current objective leg is proven from here.';
                accessxi.nav_cancel_mission_quest_route('objective-exact-leg-changed');
                speak(text);
                log_line('nav objective exact leg blocked ' .. text);
                return;
            end
            local refreshed = T{};
            for index, point in ipairs(exact) do
                refreshed:append(T{
                    zone = player.zone,
                    name = ('Objective waypoint %d'):fmt(index),
                    x = tonumber(point.x),
                    z = tonumber(point.z),
                    y = tonumber(point.y),
                    kind = 'route',
                    source = 'objective-exact-runtime-live',
                });
            end
            accessxi.nav_route_points = refreshed;
            accessxi.nav_route_point_index = accessxi.nav_first_route_index(
                player,
                refreshed,
                destination);
        end
        return;
    end
    if ((tonumber(destination.zone) or 0) ~= (tonumber(player.zone) or 0)) then
        return ('Route paused. %s is in zone %d.'):fmt(destination.name or 'Destination', destination.zone or 0);
    end

    local route_target = destination;
    local route_count = accessxi.nav_route_points:len();
    local next_target = nil;
    if (route_count > 1) then
        accessxi.nav_sync_route_index(player);
        if (accessxi.nav_route_point_index < 1) then
            accessxi.nav_route_point_index = 1;
        elseif (accessxi.nav_route_point_index > route_count) then
            accessxi.nav_route_point_index = route_count;
        end
        route_target = accessxi.nav_route_points[accessxi.nav_route_point_index] or destination;
        next_target = (accessxi.nav_route_point_index < route_count) and accessxi.nav_route_points[accessxi.nav_route_point_index + 1] or nil;
        if (not accessxi.nav_route_precise_override_active(player, accessxi.nav_route_points)) then
            route_target, next_target = accessxi.nav_indexed_lookahead_target(player, accessxi.nav_route_points, accessxi.nav_route_lookahead_distance(player, destination));
            route_target = route_target or accessxi.nav_route_points[accessxi.nav_route_point_index] or destination;
        end
    end

    local phrase = accessxi.nav_guidance_phrase(player, route_target, next_target, false);
    return ('To %s. %s'):fmt(destination.name or 'destination', phrase);
end

function accessxi.compass_speech()
    local player = nav_cached_player_position();
    if (player == nil) then
        return 'Facing unknown.';
    end

    local text = ('Facing %s.'):fmt(accessxi.nav_compass_direction(player.yaw));
    if (accessxi.nav_active and accessxi.nav_destination ~= nil) then
        local route_text = accessxi.nav_last_direction_text or '';
        if (route_text == '') then
            route_text = accessxi.nav_current_route_instruction();
        end
        if (route_text ~= '') then
            text = text .. ' ' .. route_text;
        end
    end
    return text;
end

function accessxi.poll_compass_hotkey()
    accessxi.compass_hotkey_down = false;
end

function accessxi.camera_view_speech()
    local follow = safe_call(function () return AshitaCore:GetMemoryManager():GetAutoFollow(); end, nil);
    if (follow == nil) then
        return 'Camera view changed.';
    end

    local first_person = tonumber(safe_call(function () return follow:GetIsFirstPersonCamera(); end, 0)) or 0;
    local locked = tonumber(safe_call(function () return follow:GetIsCameraLocked(); end, 0)) or 0;
    local locked_on = tonumber(safe_call(function () return follow:GetIsCameraLockedOn(); end, 0)) or 0;
    local parts = T{};
    if (first_person ~= 0) then
        parts:append('First person view.');
    else
        parts:append('Third person view.');
    end
    if (locked ~= 0) then
        parts:append('Camera locked.');
    end
    if (locked_on ~= 0) then
        parts:append('Locked on.');
    end
    return parts:concat(' ');
end

function accessxi.camera_view_state_key()
    local follow = safe_call(function () return AshitaCore:GetMemoryManager():GetAutoFollow(); end, nil);
    if (follow == nil) then
        return '';
    end

    local first_person = tonumber(safe_call(function () return follow:GetIsFirstPersonCamera(); end, 0)) or 0;
    local locked = tonumber(safe_call(function () return follow:GetIsCameraLocked(); end, 0)) or 0;
    local locked_on = tonumber(safe_call(function () return follow:GetIsCameraLockedOn(); end, 0)) or 0;
    return ('%d:%d:%d'):fmt(first_person ~= 0 and 1 or 0, locked ~= 0 and 1 or 0, locked_on ~= 0 and 1 or 0);
end

function accessxi.poll_view_hotkey()
    local now = tick();
    if ((now - (tonumber(accessxi.view_poll_last_tick) or 0)) < 100) then
        return false;
    end
    accessxi.view_poll_last_tick = now;

    local key = accessxi.camera_view_state_key();
    if (key == '') then
        accessxi.view_last_state_key = '';
        return false;
    end

    if (accessxi.view_last_state_key == nil or accessxi.view_last_state_key == '') then
        accessxi.view_last_state_key = key;
        return false;
    end

    if (key == accessxi.view_last_state_key) then
        return false;
    end

    accessxi.view_last_state_key = key;
    local text = accessxi.camera_view_speech();
    speak(text);
    log_line('camera ' .. text);
    return true;
end

function accessxi.nav_beacon_u16(value)
    value = math.floor(tonumber(value) or 0);
    return string.char(bit.band(value, 0xFF), bit.band(bit.rshift(value, 8), 0xFF));
end

function accessxi.nav_beacon_u32(value)
    value = math.floor(tonumber(value) or 0);
    return string.char(
        bit.band(value, 0xFF),
        bit.band(bit.rshift(value, 8), 0xFF),
        bit.band(bit.rshift(value, 16), 0xFF),
        bit.band(bit.rshift(value, 24), 0xFF));
end

function accessxi.nav_beacon_s16(value)
    value = math.floor(tonumber(value) or 0);
    if (value < 0) then
        value = value + 65536;
    end
    return accessxi.nav_beacon_u16(value);
end

function accessxi.nav_beacon_write_wav(path, pan, rear)
    local sample_rate = 22050;
    local duration = 0.14;
    local samples = math.floor(sample_rate * duration);
    local frequency = 880;
    local pan_angle = ((pan + 1) * math.pi) / 4;
    local left_gain = math.cos(pan_angle);
    local right_gain = math.sin(pan_angle);
    local data = T{};

    for i = 0, samples - 1 do
        local t = i / sample_rate;
        local envelope = math.sin((math.pi * i) / samples);
        local l_gain = left_gain;
        local r_gain = right_gain;
        if (rear) then
            l_gain = l_gain * 0.82;
            r_gain = r_gain * 0.82;
        end

        local value = math.sin(2 * math.pi * frequency * t) * envelope * 11000;
        data:append(accessxi.nav_beacon_s16(value * l_gain));
        data:append(accessxi.nav_beacon_s16(value * r_gain));
    end

    local body = data:concat('');
    local header = 'RIFF'
        .. accessxi.nav_beacon_u32(36 + #body)
        .. 'WAVEfmt '
        .. accessxi.nav_beacon_u32(16)
        .. accessxi.nav_beacon_u16(1)
        .. accessxi.nav_beacon_u16(2)
        .. accessxi.nav_beacon_u32(sample_rate)
        .. accessxi.nav_beacon_u32(sample_rate * 4)
        .. accessxi.nav_beacon_u16(4)
        .. accessxi.nav_beacon_u16(16)
        .. 'data'
        .. accessxi.nav_beacon_u32(#body);

    local file = io.open(path, 'wb');
    if (file == nil) then
        return false;
    end
    file:write(header);
    file:write(body);
    file:close();
    return true;
end

function accessxi.nav_beacon_normalize_audio_mode(value)
    value = tostring(value or ''):lower():gsub('[^%w]+', '');
    if (value == 'hrtf' or value == 'headphone' or value == 'headphones'
        or value == 'binaural') then
        return 'hrtf';
    end
    if (value == 'compatibility' or value == 'compatible' or value == 'speaker'
        or value == 'speakers' or value == 'stereo') then
        return 'compatibility';
    end
    return nil;
end

function accessxi.nav_beacon_load_audio_mode()
    if (accessxi.nav_beacon_audio_mode_loaded == true) then
        return accessxi.nav_beacon_audio_mode;
    end
    accessxi.nav_beacon_audio_mode_loaded = true;
    local mode = nil;
    local file = io.open(accessxi.nav_beacon_audio_mode_path, 'r');
    if (file ~= nil) then
        mode = accessxi.nav_beacon_normalize_audio_mode(file:read('*l'));
        file:close();
    end
    accessxi.nav_beacon_audio_mode = mode or 'compatibility';
    return accessxi.nav_beacon_audio_mode;
end

function accessxi.nav_beacon_save_audio_mode(value)
    local mode = accessxi.nav_beacon_normalize_audio_mode(value);
    if (mode == nil) then
        return nil, 'Unknown navigation beacon audio mode.';
    end
    local file = io.open(accessxi.nav_beacon_audio_mode_path, 'w');
    if (file == nil) then
        return nil, 'Could not save navigation beacon audio mode.';
    end
    file:write(mode, '\n');
    file:close();
    accessxi.nav_beacon_audio_mode = mode;
    accessxi.nav_beacon_audio_mode_loaded = true;
    accessxi.nav_beacon_files_ready = false;
    accessxi.nav_beacon_last_tick = 0;
    accessxi.nav_beacon_last_key = '';
    return mode, nil;
end

function accessxi.nav_beacon_read_le_u16(data, offset)
    local a, b = data:byte(offset, offset + 1);
    if (a == nil or b == nil) then
        return nil;
    end
    return a + (b * 256);
end

function accessxi.nav_beacon_read_le_u32(data, offset)
    local a, b, c, d = data:byte(offset, offset + 3);
    if (a == nil or b == nil or c == nil or d == nil) then
        return nil;
    end
    return a + (b * 256) + (c * 65536) + (d * 16777216);
end

function accessxi.nav_beacon_hrtf_wav_valid(path)
    local file = io.open(path, 'rb');
    if (file == nil) then
        return false;
    end
    local header = file:read(44) or '';
    local size = file:seek('end') or 0;
    file:close();
    return size == 25136 and #header == 44
        and header:sub(1, 4) == 'RIFF' and header:sub(9, 12) == 'WAVE'
        and header:sub(13, 16) == 'fmt ' and header:sub(37, 40) == 'data'
        and accessxi.nav_beacon_read_le_u32(header, 17) == 16
        and accessxi.nav_beacon_read_le_u16(header, 21) == 1
        and accessxi.nav_beacon_read_le_u16(header, 23) == 2
        and accessxi.nav_beacon_read_le_u32(header, 25) == 48000
        and accessxi.nav_beacon_read_le_u32(header, 29) == 192000
        and accessxi.nav_beacon_read_le_u16(header, 33) == 4
        and accessxi.nav_beacon_read_le_u16(header, 35) == 16
        and accessxi.nav_beacon_read_le_u32(header, 41) == 25092;
end

function accessxi.nav_beacon_hrtf_manifest_valid()
    local path = ('%s\\manifest.tsv'):fmt(accessxi.nav_beacon_hrtf_dir);
    local file = io.open(path, 'r');
    if (file == nil) then
        return false;
    end
    local header = file:read('*l') or '';
    local found = {};
    local count = 0;
    for line in file:lines() do
        local version, name, angle, measurement, azimuth, elevation, digest = line:match(
            '^([^\t]+)\t([^\t]+)\t([^\t]+)\t([^\t]+)\t([^\t]+)\t([^\t]+)\t([^\t]+)$');
        if (version ~= 'accessxi-nav-beacon-hrtf-v2'
            or name == nil or digest == nil or #digest ~= 64
            or not digest:match('^[0-9a-fA-F]+$')) then
            file:close();
            return false;
        end
        if (found[name] == true) then
            file:close();
            return false;
        end
        found[name] = true;
        count = count + 1;
    end
    file:close();
    if (header ~= 'format_version\tfile\tselector_angle_degrees\tsofa_measurement\tsofa_azimuth_degrees\tsofa_elevation_degrees\toutput_sha256'
        or count ~= 26) then
        return false;
    end
    for mode = 0, 1 do
        local prefix = mode == 1 and 'rear' or 'front';
        for bin = 0, 12 do
            if (found[('%s_%02d.wav'):fmt(prefix, bin)] ~= true) then
                return false;
            end
        end
    end
    return true;
end

function accessxi.nav_collision_clamp_sample(value)
    value = math.floor(tonumber(value) or 0);
    if (value > 32767) then
        return 32767;
    end
    if (value < -32768) then
        return -32768;
    end
    return value;
end

function accessxi.nav_collision_write_wav(path, cue)
    local sample_rate = cue == 'bump' and 44100 or 22050;
    local duration = cue == 'bump' and 0.115 or (cue == 'thunk' and 0.26 or 0.18);
    local samples = math.floor(sample_rate * duration);
    local data = T{};

    for i = 0, samples - 1 do
        local t = i / sample_rate;
        local value = 0;
        if (cue == 'bump') then
            local note1 = 0;
            local strike1 = 0;
            if (t < 0.052) then
                local attack = math.min(1, t / 0.005);
                local env = attack * math.exp(-33.0 * t);
                local phase = 2 * math.pi * ((790 * t) - (170 * t * t));
                strike1 = (math.sin(phase) + (math.sin(phase * 2.0) * 0.24) + (math.sin(phase * 3.0) * 0.07)) * env;
                note1 = strike1 * 0.74;
            end
            local note2 = 0;
            if (t >= 0.038) then
                local tt = t - 0.038;
                local attack = math.min(1, tt / 0.004);
                local env = attack * math.exp(-30.0 * tt);
                local phase = 2 * math.pi * ((555 * tt) - (95 * tt * tt));
                note2 = (math.sin(phase) + (math.sin(phase * 2.0) * 0.20) + (math.sin(phase * 3.0) * 0.05)) * env * 0.66;
            end
            local click = 0;
            if (t < 0.009) then
                click = math.sin(2 * math.pi * 2350 * t) * (1 - (t / 0.009)) * 0.075;
            end
            local gloss = 0;
            if (t >= 0.036 and t < 0.048) then
                local gt = t - 0.036;
                gloss = math.sin(2 * math.pi * 1750 * gt) * (1 - (gt / 0.012)) * 0.055;
            end
            value = (note1 + note2 + click + gloss) * 9800;
        elseif (cue == 'thunk') then
            local attack = math.min(1, t / 0.012);
            local envelope = attack * math.exp(-15.0 * t);
            local body = (math.sin(2 * math.pi * 118 * t) * 0.92) + (math.sin(2 * math.pi * 182 * t) * 0.38);
            local click = 0;
            if (t < 0.018) then
                click = math.sin(2 * math.pi * 920 * t) * (1 - (t / 0.018)) * 0.35;
            end
            value = (body + click) * envelope * 15000;
        else
            local envelope = math.sin((math.pi * i) / samples);
            local rasp = math.sin(2 * math.pi * 420 * t) + (math.sin(2 * math.pi * 760 * t) * 0.55);
            local tremolo = 0.55 + (math.sin(2 * math.pi * 24 * t) * 0.25);
            value = rasp * envelope * tremolo * 3200;
        end
        value = accessxi.nav_collision_clamp_sample(value);
        data:append(accessxi.nav_beacon_s16(value));
        data:append(accessxi.nav_beacon_s16(value));
    end

    local body = data:concat('');
    local header = 'RIFF'
        .. accessxi.nav_beacon_u32(36 + #body)
        .. 'WAVEfmt '
        .. accessxi.nav_beacon_u32(16)
        .. accessxi.nav_beacon_u16(1)
        .. accessxi.nav_beacon_u16(2)
        .. accessxi.nav_beacon_u32(sample_rate)
        .. accessxi.nav_beacon_u32(sample_rate * 4)
        .. accessxi.nav_beacon_u16(4)
        .. accessxi.nav_beacon_u16(16)
        .. 'data'
        .. accessxi.nav_beacon_u32(#body);

    local file = io.open(path, 'wb');
    if (file == nil) then
        return false;
    end
    file:write(header);
    file:write(body);
    file:close();
    return true;
end

function accessxi.nav_collision_ensure_sounds()
    if (accessxi.nav_collision_sounds_ready) then
        return accessxi.nav_beacon_winmm ~= nil;
    end
    accessxi.nav_collision_sounds_ready = true;

    pcall(function () kernel32.CreateDirectoryW(utf8_to_wide(accessxi.nav_beacon_parent_dir), nil); end);
    pcall(function () kernel32.CreateDirectoryW(utf8_to_wide(accessxi.nav_collision_sound_dir), nil); end);

    if (accessxi.nav_beacon_winmm == nil) then
        local ok, lib = pcall(ffi.load, 'winmm');
        if (not ok or lib == nil) then
            log_line('nav collision winmm unavailable: ' .. tostring(lib));
            return false;
        end
        accessxi.nav_beacon_winmm = lib;
    end

    local created = 0;
    local cues = {
        { name = 'wall-bump.wav', cue = 'bump' },
        { name = 'thunk.wav', cue = 'thunk' },
        { name = 'scrape.wav', cue = 'scrape' },
    };
    for _, item in ipairs(cues) do
        local path = ('%s\\%s'):fmt(accessxi.nav_collision_sound_dir, item.name);
        local existing = item.always ~= true and io.open(path, 'rb') or nil;
        if (existing ~= nil and item.always ~= true) then
            existing:close();
        elseif (accessxi.nav_collision_write_wav(path, item.cue)) then
            created = created + 1;
        end
    end

    log_line(('nav collision sounds ready created=%d dir="%s"'):fmt(created, accessxi.nav_collision_sound_dir));
    return true;
end

function accessxi.nav_collision_play_sound(state, now)
    if (not accessxi.nav_collision_ensure_sounds()) then
        return false;
    end

    local filename = 'wall-bump.wav';
    local path = ('%s\\%s'):fmt(accessxi.nav_collision_sound_dir, filename);
    local ok = pcall(function () accessxi.nav_beacon_winmm.PlaySoundW(utf8_to_wide(path), nil, 0x00020003); end);
    if (ok) then
        accessxi.beacon_audio_claim('nav_collision', 230, now);
    end
    return ok;
end

function accessxi.nav_beacon_ensure_files()
    if (accessxi.nav_beacon_files_ready) then
        return accessxi.nav_beacon_winmm ~= nil;
    end
    accessxi.nav_beacon_files_ready = true;

    pcall(function () kernel32.CreateDirectoryW(utf8_to_wide(accessxi.nav_beacon_parent_dir), nil); end);
    pcall(function () kernel32.CreateDirectoryW(utf8_to_wide(accessxi.nav_beacon_compat_dir), nil); end);

    local ok, lib = pcall(ffi.load, 'winmm');
    if (not ok or lib == nil) then
        log_line('nav beacon winmm unavailable: ' .. tostring(lib));
        return false;
    end
    accessxi.nav_beacon_winmm = lib;

    local created = 0;
    for mode = 0, 1 do
        local rear = mode == 1;
        local prefix = rear and 'rear' or 'front';
        for bin = 0, 12 do
            local path = ('%s\\%s_%02d.wav'):fmt(accessxi.nav_beacon_compat_dir, prefix, bin);
            local existing = io.open(path, 'rb');
            if (existing ~= nil) then
                existing:close();
            else
                local pan = (bin - 6) / 6;
                if (accessxi.nav_beacon_write_wav(path, pan, rear)) then
                    created = created + 1;
                end
            end
        end
    end

    local requested_mode = accessxi.nav_beacon_load_audio_mode();
    local hrtf_ready = requested_mode == 'hrtf' and accessxi.nav_beacon_hrtf_manifest_valid();
    if (hrtf_ready) then
        for mode = 0, 1 do
            local prefix = mode == 1 and 'rear' or 'front';
            for bin = 0, 12 do
                local path = ('%s\\%s_%02d.wav'):fmt(accessxi.nav_beacon_hrtf_dir, prefix, bin);
                if (not accessxi.nav_beacon_hrtf_wav_valid(path)) then
                    hrtf_ready = false;
                end
            end
        end
    end
    accessxi.nav_beacon_dir = hrtf_ready and accessxi.nav_beacon_hrtf_dir
        or accessxi.nav_beacon_compat_dir;
    accessxi.nav_beacon_bank = hrtf_ready and 'hrtf' or 'compatibility';
    if (requested_mode == 'hrtf' and not hrtf_ready) then
        log_line('nav beacon HRTF bank invalid or incomplete; compatibility audio active');
    end
    log_line(('nav beacon ready created=%d bank=%s dir="%s"'):fmt(
        created, accessxi.nav_beacon_bank, accessxi.nav_beacon_dir));
    return true;
end

function accessxi.nav_beacon_play(path, now, fallback_path)
    now = tonumber(now) or tick();

    local function play_once(candidate)
        if (accessxi.nav_beacon_winmm == nil) then
            return false, 'winmm unavailable';
        end
        local ok, result = pcall(function ()
            return accessxi.nav_beacon_winmm.PlaySoundW(utf8_to_wide(candidate), nil, 0x00020003);
        end);
        if (not ok) then
            return false, tostring(result or 'PlaySoundW call failed');
        end
        if (result == true or (tonumber(result) or 0) ~= 0) then
            return true, '';
        end
        return false, 'PlaySoundW returned false';
    end

    local played, reason = play_once(path);
    if (not played) then
        accessxi.nav_beacon_winmm = nil;
        accessxi.nav_beacon_files_ready = false;
        if (accessxi.nav_beacon_ensure_files()) then
            played, reason = play_once(path);
        else
            reason = 'winmm reload failed';
        end
    end

    if (not played and fallback_path ~= nil and tostring(fallback_path) ~= ''
        and tostring(fallback_path) ~= tostring(path)) then
        played, reason = play_once(fallback_path);
        if (played) then
            accessxi.nav_beacon_dir = accessxi.nav_beacon_compat_dir;
            accessxi.nav_beacon_bank = 'compatibility';
            log_line('nav beacon HRTF playback failed; compatibility audio active');
        end
    end

    if (played) then
        if (accessxi.nav_beacon_last_play_failure_key ~= '') then
            log_line('nav beacon audio recovered');
        end
        accessxi.nav_beacon_last_play_failure_key = '';
        return true;
    end

    local failure_key = tostring(reason or 'unknown');
    if (failure_key ~= tostring(accessxi.nav_beacon_last_play_failure_key or '')
        or (now - (tonumber(accessxi.nav_beacon_last_play_failure_tick) or 0)) >= 5000) then
        accessxi.nav_beacon_last_play_failure_key = failure_key;
        accessxi.nav_beacon_last_play_failure_tick = now;
        local log_reason = type(accessxi.escape_probe_log_text) == 'function'
            and accessxi.escape_probe_log_text(failure_key) or failure_key;
        log_line(('nav beacon audio failed reason="%s"'):fmt(
            log_reason));
    end
    return false;
end

function accessxi.enemy_warning_ensure_audio()
    if (accessxi.nav_beacon_winmm ~= nil) then
        return true;
    end

    local ok, lib = pcall(ffi.load, 'winmm');
    if (not ok or lib == nil) then
        log_line('enemy warning winmm unavailable: ' .. tostring(lib));
        return false;
    end

    accessxi.nav_beacon_winmm = lib;
    return true;
end

function accessxi.enemy_warning_nearest()
    local enemies = accessxi.nav_live_enemies(accessxi.enemy_warning_range or 28);
    if (#enemies == 0) then
        return nil;
    end
    return enemies[1];
end

function accessxi.enemy_beacon_read_u16(data, offset)
    local a, b = data:byte(offset, offset + 1);
    if (a == nil or b == nil) then
        return 0;
    end
    return a + (b * 256);
end

function accessxi.enemy_beacon_read_s16(data, offset)
    local value = accessxi.enemy_beacon_read_u16(data, offset);
    if (value >= 0x8000) then
        return value - 0x10000;
    end
    return value;
end

function accessxi.enemy_beacon_read_u32(data, offset)
    local a, b, c, d = data:byte(offset, offset + 3);
    if (a == nil or b == nil or c == nil or d == nil) then
        return 0;
    end
    return a + (b * 256) + (c * 65536) + (d * 16777216);
end

function accessxi.enemy_beacon_load_source()
    local path = accessxi.enemy_warning_sound_path or '';
    local file = io.open(path, 'rb');
    if (file == nil) then
        return nil, 'missing';
    end

    local data = file:read('*a');
    file:close();
    if (data == nil or data:sub(1, 4) ~= 'RIFF' or data:sub(9, 12) ~= 'WAVE') then
        return nil, 'not-wave';
    end

    local info = T{ data = data, fmt = nil, channels = 0, sample_rate = 0, bits = 0, pcm_start = 0, pcm_size = 0 };
    local pos = 13;
    while ((pos + 7) <= #data) do
        local chunk_id = data:sub(pos, pos + 3);
        local chunk_size = accessxi.enemy_beacon_read_u32(data, pos + 4);
        local chunk_start = pos + 8;
        if (chunk_id == 'fmt ') then
            info.fmt = accessxi.enemy_beacon_read_u16(data, chunk_start);
            info.channels = accessxi.enemy_beacon_read_u16(data, chunk_start + 2);
            info.sample_rate = accessxi.enemy_beacon_read_u32(data, chunk_start + 4);
            info.bits = accessxi.enemy_beacon_read_u16(data, chunk_start + 14);
        elseif (chunk_id == 'data') then
            info.pcm_start = chunk_start;
            info.pcm_size = math.min(chunk_size, #data - chunk_start + 1);
        end

        pos = chunk_start + chunk_size;
        if ((chunk_size % 2) == 1) then
            pos = pos + 1;
        end
    end

    if (info.fmt ~= 1 or info.bits ~= 16 or info.channels < 1 or info.pcm_start <= 0 or info.pcm_size <= 0) then
        return nil, 'unsupported';
    end
    return info, nil;
end

function accessxi.beacon_audio_available(now)
    return (tonumber(now) or tick()) >= (tonumber(accessxi.beacon_audio_busy_until) or 0);
end

function accessxi.beacon_audio_claim(source, duration_ms, now)
    now = tonumber(now) or tick();
    accessxi.beacon_audio_busy_until = now + (tonumber(duration_ms) or 200);
    accessxi.beacon_audio_busy_source = source or '';
end

function accessxi.enemy_beacon_volume_for_distance(distance)
    distance = tonumber(distance) or 999;
    local range = tonumber(accessxi.enemy_warning_range) or 120;
    if (range < 10) then
        range = 10;
    end

    local closeness = 1 - math.max(0, math.min(distance, range)) / range;
    local volume = 0.18 + (closeness * closeness * 0.62);
    if (distance <= 8) then
        volume = 0.88;
    elseif (distance <= 16) then
        volume = math.max(volume, 0.68);
    elseif (distance <= 32) then
        volume = math.max(volume, 0.48);
    end
    if (volume < 0.12) then
        volume = 0.12;
    elseif (volume > 0.90) then
        volume = 0.90;
    end
    return volume;
end

function accessxi.enemy_beacon_volume_bin(volume)
    volume = tonumber(volume) or 0.18;
    local bin = math.floor((volume * 8) + 0.5);
    if (bin < 1) then
        bin = 1;
    elseif (bin > 7) then
        bin = 7;
    end
    return bin, bin / 8;
end

function accessxi.enemy_beacon_write_variant(source, path, pan, rear, volume)
    local pan_angle = ((pan + 1) * math.pi) / 4;
    local left_gain = math.cos(pan_angle) * (tonumber(volume) or 0.35);
    local right_gain = math.sin(pan_angle) * (tonumber(volume) or 0.35);
    if (rear) then
        left_gain = left_gain * 0.82;
        right_gain = right_gain * 0.82;
    end

    local frame_size = (tonumber(source.channels) or 1) * 2;
    local frames = math.floor((tonumber(source.pcm_size) or 0) / frame_size);
    local data = T{};
    for frame = 0, frames - 1 do
        local offset = source.pcm_start + (frame * frame_size);
        local mixed = accessxi.enemy_beacon_read_s16(source.data, offset);
        if ((tonumber(source.channels) or 1) >= 2) then
            mixed = (mixed + accessxi.enemy_beacon_read_s16(source.data, offset + 2)) / 2;
        end

        local left = mixed * left_gain;
        local right = mixed * right_gain;
        data:append(accessxi.nav_beacon_s16(left));
        data:append(accessxi.nav_beacon_s16(right));
    end

    local body = data:concat('');
    local sample_rate = tonumber(source.sample_rate) or 44100;
    local header = 'RIFF'
        .. accessxi.nav_beacon_u32(36 + #body)
        .. 'WAVEfmt '
        .. accessxi.nav_beacon_u32(16)
        .. accessxi.nav_beacon_u16(1)
        .. accessxi.nav_beacon_u16(2)
        .. accessxi.nav_beacon_u32(sample_rate)
        .. accessxi.nav_beacon_u32(sample_rate * 4)
        .. accessxi.nav_beacon_u16(4)
        .. accessxi.nav_beacon_u16(16)
        .. 'data'
        .. accessxi.nav_beacon_u32(#body);

    local file = io.open(path, 'wb');
    if (file == nil) then
        return false;
    end
    file:write(header);
    file:write(body);
    file:close();
    return true;
end

function accessxi.enemy_beacon_ensure_files()
    if (accessxi.enemy_beacon_files_ready) then
        return accessxi.nav_beacon_winmm ~= nil;
    end

    if (not accessxi.enemy_warning_ensure_audio()) then
        return false;
    end

    pcall(function () kernel32.CreateDirectoryW(utf8_to_wide(accessxi.nav_beacon_parent_dir), nil); end);
    pcall(function () kernel32.CreateDirectoryW(utf8_to_wide(accessxi.enemy_beacon_dir), nil); end);

    local source, reason = accessxi.enemy_beacon_load_source();
    if (source == nil) then
        log_line('enemy beacon source unavailable: ' .. tostring(reason));
        return false;
    end

    local created = 0;
    for volume_bin = 1, 7 do
        local volume = volume_bin / 8;
        for mode = 0, 1 do
            local rear = mode == 1;
            local prefix = rear and 'rear' or 'front';
            for bin = 0, 12 do
                local path = ('%s\\v%02d_%s_%02d.wav'):fmt(accessxi.enemy_beacon_dir, volume_bin, prefix, bin);
                local existing = io.open(path, 'rb');
                if (existing ~= nil) then
                    existing:close();
                else
                    local pan = (bin - 6) / 6;
                    if (accessxi.enemy_beacon_write_variant(source, path, pan, rear, volume)) then
                        created = created + 1;
                    end
                end
            end
        end
    end

    accessxi.enemy_beacon_files_ready = true;
    log_line(('enemy beacon ready created=%d dir="%s"'):fmt(created, accessxi.enemy_beacon_dir));
    return true;
end

function accessxi.enemy_beacon_file_for_delta(delta, distance)
    local pan = -math.sin(delta);
    if (pan < -1) then
        pan = -1;
    elseif (pan > 1) then
        pan = 1;
    end

    local bin = math.floor(((pan + 1) * 6) + 0.5);
    if (bin < 0) then
        bin = 0;
    elseif (bin > 12) then
        bin = 12;
    end

    local rear = math.cos(delta) < -0.35;
    local prefix = rear and 'rear' or 'front';
    local volume = accessxi.enemy_beacon_volume_for_distance(distance);
    local volume_bin, quantized_volume = accessxi.enemy_beacon_volume_bin(volume);
    return ('%s\\v%02d_%s_%02d.wav'):fmt(accessxi.enemy_beacon_dir, volume_bin, prefix, bin), prefix, bin, pan, volume_bin, quantized_volume;
end

function accessxi.enemy_beacon_clamp(value)
    value = math.floor(tonumber(value) or 0);
    if (value < -32768) then
        return -32768;
    elseif (value > 32767) then
        return 32767;
    end
    return value;
end

function accessxi.enemy_beacon_source_gains(player, enemy)
    local heading = accessxi.nav_heading_to(player, enemy);
    if (heading == nil) then
        return nil;
    end

    local yaw = tonumber(player.yaw);
    if (yaw == nil) then
        return nil;
    end
    if (math.abs(yaw) > (math.pi * 2.1)) then
        yaw = yaw * math.pi / 180;
    end

    local delta = accessxi.nav_normalize_angle(heading + yaw);
    local pan = -math.sin(delta);
    if (pan < -1) then
        pan = -1;
    elseif (pan > 1) then
        pan = 1;
    end

    local angle = ((pan + 1) * math.pi) / 4;
    local volume = accessxi.enemy_beacon_volume_for_distance(enemy.distance);
    local rear = math.cos(delta) < -0.35;
    if (rear) then
        volume = volume * 0.82;
    end

    return T{
        enemy = enemy,
        delta = delta,
        pan = pan,
        rear = rear,
        volume = volume,
        left = math.cos(angle) * volume,
        right = math.sin(angle) * volume,
    };
end

function accessxi.enemy_beacon_write_mix(path, player, enemies)
    local source, reason = accessxi.enemy_beacon_load_source();
    if (source == nil) then
        log_line('enemy mix source unavailable: ' .. tostring(reason));
        return nil;
    end

    local sample_rate = tonumber(source.sample_rate) or 44100;
    local frame_size = (tonumber(source.channels) or 1) * 2;
    local source_frames = math.floor((tonumber(source.pcm_size) or 0) / frame_size);
    if (source_frames <= 0) then
        return nil;
    end

    local entries = T{};
    local max_sources = math.min(tonumber(accessxi.enemy_beacon_max_sources) or 4, #enemies);
    for i = 1, max_sources do
        local entry = accessxi.enemy_beacon_source_gains(player, enemies[i]);
        if (entry ~= nil) then
            entry.offset = math.floor((i - 1) * sample_rate * 0.075);
            entries:append(entry);
        end
    end
    if (entries:len() == 0) then
        return nil;
    end

    local total_frames = source_frames + math.floor((entries:len() - 1) * sample_rate * 0.075);
    local left = {};
    local right = {};
    for i = 1, total_frames do
        left[i] = 0;
        right[i] = 0;
    end

    local count_scale = 1 / math.sqrt(entries:len());
    for _, entry in ipairs(entries) do
        local lgain = entry.left * count_scale;
        local rgain = entry.right * count_scale;
        for frame = 0, source_frames - 1 do
            local offset = source.pcm_start + (frame * frame_size);
            local mixed = accessxi.enemy_beacon_read_s16(source.data, offset);
            if ((tonumber(source.channels) or 1) >= 2) then
                mixed = (mixed + accessxi.enemy_beacon_read_s16(source.data, offset + 2)) / 2;
            end

            local index = frame + entry.offset + 1;
            left[index] = (left[index] or 0) + (mixed * lgain);
            right[index] = (right[index] or 0) + (mixed * rgain);
        end
    end

    local body_parts = T{};
    for i = 1, total_frames do
        body_parts:append(accessxi.nav_beacon_s16(accessxi.enemy_beacon_clamp(left[i])));
        body_parts:append(accessxi.nav_beacon_s16(accessxi.enemy_beacon_clamp(right[i])));
    end

    local body = body_parts:concat('');
    local header = 'RIFF'
        .. accessxi.nav_beacon_u32(36 + #body)
        .. 'WAVEfmt '
        .. accessxi.nav_beacon_u32(16)
        .. accessxi.nav_beacon_u16(1)
        .. accessxi.nav_beacon_u16(2)
        .. accessxi.nav_beacon_u32(sample_rate)
        .. accessxi.nav_beacon_u32(sample_rate * 4)
        .. accessxi.nav_beacon_u16(4)
        .. accessxi.nav_beacon_u16(16)
        .. 'data'
        .. accessxi.nav_beacon_u32(#body);

    local file = io.open(path, 'wb');
    if (file == nil) then
        return nil;
    end
    file:write(header);
    file:write(body);
    file:close();

    local names = T{};
    for _, entry in ipairs(entries) do
        names:append(('%s %.0f %s %.0f'):fmt(
            entry.enemy.name or 'enemy',
            tonumber(entry.enemy.distance) or 0,
            entry.rear and 'rear' or 'front',
            entry.delta * 180 / math.pi));
    end
    return T{
        count = entries:len(),
        duration = (total_frames / sample_rate) * 1000,
        names = names:concat('; '),
    };
end

function accessxi.poll_enemy_warning()
    if (not accessxi.enemy_warning_enabled) then
        return;
    end

    local now = tick();
    if ((now - (accessxi.enemy_warning_last_tick or 0)) < 850) then
        return;
    end
    if (not accessxi.beacon_audio_available(now)) then
        return;
    end

    local player = nav_cached_player_position();
    if (player == nil) then
        return;
    end

    local enemies = accessxi.nav_live_enemies(accessxi.enemy_warning_range or 35);
    if (#enemies == 0) then
        accessxi.enemy_warning_last_key = '';
        return;
    end

    if (not accessxi.enemy_warning_ensure_audio()) then
        return;
    end

    pcall(function () kernel32.CreateDirectoryW(utf8_to_wide(accessxi.nav_beacon_parent_dir), nil); end);
    pcall(function () kernel32.CreateDirectoryW(utf8_to_wide(accessxi.enemy_beacon_dir), nil); end);
    accessxi.enemy_beacon_mix_sequence = ((accessxi.enemy_beacon_mix_sequence or 0) % 3) + 1;
    local path = ('%s\\enemy_mix_%d.wav'):fmt(accessxi.enemy_beacon_dir, accessxi.enemy_beacon_mix_sequence);
    local mix = accessxi.enemy_beacon_write_mix(path, player, enemies);
    if (mix == nil) then
        return;
    end

    accessxi.enemy_warning_last_tick = now;
    pcall(function () accessxi.nav_beacon_winmm.PlaySoundW(utf8_to_wide(path), nil, 0x00020003); end);
    accessxi.beacon_audio_claim('enemy', math.max(520, math.min(900, tonumber(mix.duration) or 560)), now);

    local key = ('%d:%s'):fmt(mix.count or 0, mix.names or '');
    if (key ~= accessxi.enemy_warning_last_key) then
        accessxi.enemy_warning_last_key = key;
        log_line(('enemy mix count=%d %s'):fmt(mix.count or 0, mix.names or ''));
    end
end

function accessxi.nav_precise_beacon_lookahead_allowed(player, route_target, next_target)
    if (player == nil or route_target == nil or next_target == nil) then
        return false;
    end

    local approach_x = (tonumber(route_target.x) or 0) - (tonumber(player.x) or 0);
    local approach_z = (tonumber(route_target.z) or 0) - (tonumber(player.z) or 0);
    local exit_x = (tonumber(next_target.x) or 0) - (tonumber(route_target.x) or 0);
    local exit_z = (tonumber(next_target.z) or 0) - (tonumber(route_target.z) or 0);
    local approach_length = math.sqrt((approach_x * approach_x) + (approach_z * approach_z));
    local exit_length = math.sqrt((exit_x * exit_x) + (exit_z * exit_z));
    if (approach_length > 5 or exit_length <= 0.25) then
        return false;
    end
    if (approach_length <= 0.75) then
        return true;
    end

    local turn_cosine = ((approach_x * exit_x) + (approach_z * exit_z))
        / (approach_length * exit_length);
    return turn_cosine >= 0.70710678;
end

function accessxi.nav_precise_route_return_clear()
    accessxi.nav_precise_return_target = nil;
    accessxi.nav_precise_return_points = nil;
    accessxi.nav_precise_return_segment = 0;
end

function accessxi.nav_lathine_local_target_cache_clear()
    accessxi.nav_lathine_local_target = nil;
    accessxi.nav_lathine_local_target_points = nil;
    accessxi.nav_lathine_local_target_index = 0;
    accessxi.nav_lathine_local_target_tick = 0;
    accessxi.nav_lathine_local_target_player = nil;
end

function accessxi.nav_lathine_direct_target_safe(player, target)
    if (player == nil or target == nil
        or (tonumber(player.zone) or 0) ~= (tonumber(target.zone) or 0)
        or not accessxi.nav_valid_mesh_position(target)) then
        return false;
    end

    local wall_distance = tonumber(accessxi.nav_wall_distance(target));
    if (wall_distance == nil or wall_distance < 1.2) then
        return false;
    end

    local local_route = nav_compute_mesh_route(player, target, true);
    local count = local_route ~= nil and local_route:len() or 0;
    if (count <= 0) then
        return false;
    end

    -- FFXINAV FindClosestPath can return both the projected endpoint and the
    -- requested endpoint at identical X/Z with a tiny height correction.  It
    -- is still a direct local leg; only a geometrically distinct intermediate
    -- point represents another corner that steering must not cut across.
    local distinct_points = 1;
    local previous = local_route[1];
    for route_index = 2, count do
        local current = local_route[route_index];
        local horizontal = nav_distance(previous, current);
        local vertical = math.abs((tonumber(current ~= nil and current.y) or 0)
            - (tonumber(previous ~= nil and previous.y) or 0));
        if (horizontal > 0.05 or vertical > 2.0) then
            distinct_points = distinct_points + 1;
        end
        previous = current;
    end
    if (distinct_points > 2) then
        return false;
    end

    local finish = local_route[count];
    return finish ~= nil
        and nav_distance(finish, target) <= 1.25
        and math.abs((tonumber(finish.y) or 0) - (tonumber(target.y) or 0)) <= 2.0;
end

function accessxi.nav_lathine_cache_local_target(player, points, index, target)
    accessxi.nav_lathine_local_target = target;
    accessxi.nav_lathine_local_target_points = points;
    accessxi.nav_lathine_local_target_index = tonumber(index) or 1;
    accessxi.nav_lathine_local_target_tick = tick();
    accessxi.nav_lathine_local_target_player = T{
        zone = player.zone,
        x = player.x,
        z = player.z,
        y = player.y,
    };
    return target;
end

function accessxi.nav_lathine_cached_local_target(player, points, index)
    local target = accessxi.nav_lathine_local_target;
    local origin = accessxi.nav_lathine_local_target_player;
    local age = tick() - (tonumber(accessxi.nav_lathine_local_target_tick) or 0);
    if (target ~= nil
        and origin ~= nil
        and accessxi.nav_lathine_local_target_points == points
        and (tonumber(accessxi.nav_lathine_local_target_index) or 0) == (tonumber(index) or 1)
        and age >= 0 and age <= 400
        and nav_distance(player, origin) <= 0.4
        and accessxi.nav_valid_mesh_position(target)
        and (tonumber(accessxi.nav_wall_distance(target)) or -1) >= 1.2) then
        return target;
    end
    accessxi.nav_lathine_local_target_cache_clear();
    return nil;
end

function accessxi.nav_lathine_locally_safe_target(player, points, index, nominal)
    local cached = accessxi.nav_lathine_cached_local_target(player, points, index);
    if (cached ~= nil) then
        return cached;
    end

    if (accessxi.nav_lathine_direct_target_safe(player, nominal)) then
        return accessxi.nav_lathine_cache_local_target(player, points, index, nominal);
    end

    local goal = points ~= nil and points[tonumber(index) or 1] or nil;
    if (goal == nil) then
        return nil;
    end
    local dx = (tonumber(goal.x) or 0) - (tonumber(player.x) or 0);
    local dz = (tonumber(goal.z) or 0) - (tonumber(player.z) or 0);
    local distance = math.sqrt((dx * dx) + (dz * dz));
    if (distance <= 0.35) then
        return nil;
    end

    local unit_x = dx / distance;
    local unit_z = dz / distance;
    local side_x = -unit_z;
    local side_z = unit_x;
    local forward_steps = { math.min(2.0, distance), math.min(1.25, distance), math.min(0.75, distance) };
    local side_steps = { 0, 1.25, -1.25, 2.0, -2.0 };
    for _, forward in ipairs(forward_steps) do
        for _, side in ipairs(side_steps) do
            local candidate = T{
                zone = player.zone,
                name = 'Local safe waypoint',
                x = (tonumber(player.x) or 0) + (unit_x * forward) + (side_x * side),
                z = (tonumber(player.z) or 0) + (unit_z * forward) + (side_z * side),
                y = (tonumber(player.y) or 0)
                    + (((tonumber(goal.y) or 0) - (tonumber(player.y) or 0)) * (forward / distance)),
                kind = 'route',
                source = 'lathine-local-safe',
                route_override_id = 'lathine-navmesh',
            };
            if (nav_distance(candidate, goal) + 0.05 < distance
                and accessxi.nav_lathine_direct_target_safe(player, candidate)) then
                return accessxi.nav_lathine_cache_local_target(player, points, index, candidate);
            end
        end
    end
    return nil;
end

function accessxi.nav_lathine_replan_or_stop(player, points, lookahead, already_replanned)
    local destination = accessxi.nav_destination;
    local owns_active_route = accessxi.nav_active
        and destination ~= nil
        and accessxi.nav_route_points == points
        and (tonumber(destination.zone) or 0) == (tonumber(player.zone) or 0);
    if (owns_active_route and not already_replanned) then
        local refreshed = nav_compute_mesh_route(player, destination, true);
        if (refreshed ~= nil and refreshed:len() > 1) then
            for _, point in ipairs(refreshed) do
                point.route_override_id = 'lathine-navmesh';
            end
            accessxi.nav_route_points = refreshed;
            accessxi.nav_route_point_index = accessxi.nav_first_route_index(player, refreshed, destination);
            accessxi.nav_route_last_recalc_tick = tick();
            accessxi.nav_precise_route_return_clear();
            accessxi.nav_lathine_local_target_cache_clear();
            log_line(('nav lathine local safety replan destination="%s" count=%d'):fmt(
                destination.name or '', refreshed:len()));
            return accessxi.nav_precise_steering_target(
                player, refreshed, accessxi.nav_route_point_index, lookahead, true);
        end
    end

    if (owns_active_route) then
        local name = tostring(destination.name or 'destination');
        nav_route_stop();
        local text = ('Navigation stopped. No locally reachable path to %s.'):fmt(name);
        speak(text);
        log_line(('nav lathine local safety blocked destination="%s"'):fmt(name));
    end
    return nil;
end

function accessxi.nav_precise_steering_target(player, points, index, lookahead, safety_replanned)
    if (player == nil) then
        return nil;
    end

    index = tonumber(index) or 1;
    local preferred_segment = math.max(1, index - 1);
    local route_id = accessxi.nav_route_points_override_id(points);
    local collision_segment = route_id == 'dat-collision' or route_id == 'lathine-navmesh';
    local narrow_collision_segment = route_id == 'lathine-navmesh'
        or (route_id == 'dat-collision' and (tonumber(player.zone) or 0) == 102);
    local match_first = collision_segment and preferred_segment or nil;
    local match_last = collision_segment and preferred_segment or nil;
    local smooth_lookahead = route_id:find('lathine-recorded-survey-', 1, true) == 1;
    local effective_lookahead = smooth_lookahead and math.max(9, tonumber(lookahead) or 0) or lookahead;
    if (narrow_collision_segment) then
        effective_lookahead = math.min(2.0, tonumber(effective_lookahead) or 5);
    elseif (collision_segment) then
        -- Stay on the validated segment, but look far enough ahead that a
        -- small lateral walking wobble does not command a sharp correction.
        effective_lookahead = 9.0;
    end
    local px = tonumber(player.x) or 0;
    local pz = tonumber(player.z) or 0;
    local delicate_recorded_curve = route_id == 'lathine-recorded-corridor-20260712-01'
        or (route_id:find('lathine-recorded-corridor-20260712-west-via-', 1, true) == 1
            and px >= -465 and px <= -430 and pz >= 205 and pz <= 275);
    if (not smooth_lookahead and delicate_recorded_curve) then
        effective_lookahead = math.min(2.25, tonumber(effective_lookahead) or 5);
    end
    local anchor = accessxi.nav_precise_return_target;
    local match = nil;
    if (anchor ~= nil) then
        if (accessxi.nav_precise_return_points ~= points) then
            accessxi.nav_precise_route_return_clear();
        else
            match = accessxi.nav_route_live_match(
                player, points, preferred_segment, match_first, match_last);
            local anchor_segment = tonumber(accessxi.nav_precise_return_segment) or 0;
            local safely_ahead = match ~= nil
                and (tonumber(match.segment) or 0) > anchor_segment
                and (tonumber(match.horizontal) or 999999) <= 3.25
                and (tonumber(match.vertical) or 999999) <= 2.0
                and (not delicate_recorded_curve or nav_distance(player, anchor) >= 1.25);
            if (safely_ahead) then
                accessxi.nav_precise_route_return_clear();
            else
                local horizontal = nav_distance(player, anchor);
                local vertical = math.abs((tonumber(player.y) or 0) - (tonumber(anchor.y) or 0));
                local reached_distance = delicate_recorded_curve and 0.35 or 1.25;
                if (horizontal <= reached_distance and vertical <= 2.0) then
                    accessxi.nav_precise_route_return_clear();
                elseif (horizontal <= 6.0 and vertical <= 4.5) then
                    if (route_id ~= 'lathine-navmesh') then
                        return anchor;
                    end
                    local safe_anchor = accessxi.nav_lathine_locally_safe_target(
                        player, points, index, anchor);
                    if (safe_anchor ~= nil) then
                        return safe_anchor;
                    end
                    return accessxi.nav_lathine_replan_or_stop(
                        player, points, lookahead, safety_replanned == true);
                else
                    accessxi.nav_precise_route_return_clear();
                    match = nil;
                end
            end
        end
    end

    match = match or accessxi.nav_route_live_match(
        player, points, preferred_segment, match_first, match_last);
    local target = accessxi.nav_route_target_from_match(
        player, points, match, effective_lookahead, smooth_lookahead, collision_segment);
    if (target ~= nil and tostring(target.source or '') == 'live-route-return') then
        accessxi.nav_precise_return_target = target;
        accessxi.nav_precise_return_points = points;
        accessxi.nav_precise_return_segment = tonumber(match ~= nil and match.segment) or 0;
    else
        accessxi.nav_precise_route_return_clear();
    end
    if (route_id == 'lathine-navmesh') then
        local safe_target = accessxi.nav_lathine_locally_safe_target(player, points, index, target);
        if (safe_target ~= nil) then
            return safe_target;
        end
        return accessxi.nav_lathine_replan_or_stop(player, points, lookahead, safety_replanned == true);
    end
    return target;
end

function accessxi.nav_precise_route_recover_or_stop(player, destination, points, lookahead)
    if (player == nil or destination == nil or accessxi.nav_dat_collision_pending ~= nil
        or not accessxi.nav_active or accessxi.nav_destination ~= destination
        or accessxi.nav_route_points ~= points) then
        return nil;
    end

    accessxi.nav_route_last_recalc_tick = tick();
    local refreshed = T{};
    if (type(accessxi.nav_compute_route_with_zoneline_approach) == 'function') then
        refreshed = accessxi.nav_compute_route_with_zoneline_approach(player, destination);
    end
    if (accessxi.nav_dat_collision_pending ~= nil) then
        return nil;
    end

    if (refreshed ~= nil and refreshed:len() > 1) then
        accessxi.nav_route_points = refreshed;
        accessxi.nav_route_point_index = accessxi.nav_first_route_index(player, refreshed, destination);
        accessxi.nav_precise_route_return_clear();

        local target = nil;
        if (accessxi.nav_route_precise_override_active(player, refreshed)) then
            target = accessxi.nav_precise_steering_target(
                player, refreshed, accessxi.nav_route_point_index, lookahead, true);
        else
            target = accessxi.nav_indexed_lookahead_target(
                player, refreshed, accessxi.nav_route_lookahead_distance(player, destination));
        end
        if (target ~= nil) then
            log_line(('nav precise target recovered destination="%s" count=%d'):fmt(
                destination.name or '', refreshed:len()));
            return target;
        end
    end

    local name = tostring(destination.name or 'destination');
    local text = ('Navigation stopped. No safe route from the current position to %s.'):fmt(name);
    if (type(nav_write_route_evidence) == 'function') then
        nav_write_route_evidence('unreachable', player, destination, nil, T{
            reason = 'precise route lost its local steering target',
        });
    end
    if (accessxi.nav_active and accessxi.nav_destination == destination) then
        nav_route_stop();
        speak(text);
        log_line(('nav precise target lost destination="%s"'):fmt(name));
    end
    return nil;
end

function accessxi.nav_beacon_route_target(player)
    if (player == nil or not accessxi.nav_active or accessxi.nav_destination == nil) then
        return nil;
    end
    if accessxi.nav_dat_collision_pending ~= nil then
        return nil;
    end

    local destination = accessxi.nav_destination;
    if ((tonumber(destination.zone) or 0) ~= (tonumber(player.zone) or 0)) then
        return nil;
    end

    local route_count = accessxi.nav_route_points:len();
    if (route_count > 1) then
        accessxi.nav_sync_route_index(player);
        if (accessxi.nav_route_point_index < 1) then
            accessxi.nav_route_point_index = 1;
        elseif (accessxi.nav_route_point_index > route_count) then
            accessxi.nav_route_point_index = route_count;
        end

        if (accessxi.nav_route_precise_override_active(player, accessxi.nav_route_points)) then
            local route_points = accessxi.nav_route_points;
            local target = accessxi.nav_precise_steering_target(
                player, route_points, accessxi.nav_route_point_index, 5);
            if (target == nil) then
                return accessxi.nav_precise_route_recover_or_stop(
                    player, destination, route_points, 5);
            end
            return target;
        end

        local route_target, next_target = accessxi.nav_indexed_lookahead_target(player, accessxi.nav_route_points, accessxi.nav_route_lookahead_distance(player, destination));
        if (route_target ~= nil) then
            local distance = nav_distance(player, route_target);
            if (distance <= 5 and next_target ~= nil) then
                return next_target;
            end
            return route_target;
        end
    end

    return destination;
end

function accessxi.nav_beacon_reset_direction_state()
    accessxi.nav_beacon_route_identity = nil;
    accessxi.nav_beacon_route_acquired = false;
    accessxi.nav_beacon_centered = false;
    accessxi.nav_beacon_center_index = nil;
    accessxi.nav_beacon_previous_delta = nil;
    accessxi.nav_beacon_motion_x = nil;
    accessxi.nav_beacon_motion_z = nil;
end

function accessxi.nav_beacon_direction_delta(player, route_target, points, index, route_geometry)
    local target_heading = accessxi.nav_heading_to(player, route_target);
    local yaw = player ~= nil and tonumber(player.yaw) or nil;
    if (target_heading == nil or yaw == nil) then
        return nil;
    end
    if (math.abs(yaw) > (math.pi * 2.1)) then
        yaw = yaw * math.pi / 180;
    end

    local raw_delta = accessxi.nav_normalize_angle(target_heading + yaw);
    local acquired_before = accessxi.nav_beacon_route_acquired == true;
    local source = tostring(route_target ~= nil and route_target.source or '');
    local explicit_correction = source == 'live-route-return'
        or source == 'dynamic-obstacle'
        or source == 'wall-escape'
        or source == 'lathine-local-safe';
    local count = points ~= nil and points:len() or 0;
    if (route_geometry == true and count >= 2 and not explicit_correction
        and not acquired_before
        and math.abs(raw_delta) <= (20 * math.pi / 180)) then
        accessxi.nav_beacon_route_acquired = true;
    end

    local ordinary_tracking = route_geometry == true and count >= 2
        and not explicit_correction and acquired_before;
    if (not ordinary_tracking) then
        accessxi.nav_beacon_centered = false;
        accessxi.nav_beacon_center_index = nil;
        accessxi.nav_beacon_previous_delta = nil;
        return raw_delta;
    end

    local current_index = tonumber(index) or 0;
    if (accessxi.nav_beacon_center_index ~= current_index) then
        accessxi.nav_beacon_centered = false;
        accessxi.nav_beacon_center_index = current_index;
        accessxi.nav_beacon_previous_delta = raw_delta;
        return raw_delta;
    end

    local center_enter = 12 * math.pi / 180;
    local center_exit = 18 * math.pi / 180;
    local magnitude = math.abs(raw_delta);
    local previous_delta = tonumber(accessxi.nav_beacon_previous_delta);
    local center_crossing = previous_delta ~= nil
        and (previous_delta * raw_delta) < 0
        and math.abs(previous_delta) <= center_exit
        and magnitude <= center_exit;
    accessxi.nav_beacon_previous_delta = raw_delta;

    if (accessxi.nav_beacon_centered == true) then
        if (magnitude <= center_exit) then
            return 0;
        end
        accessxi.nav_beacon_centered = false;
    elseif (magnitude <= center_enter or center_crossing) then
        accessxi.nav_beacon_centered = true;
        return 0;
    end
    return raw_delta;
end

function accessxi.nav_beacon_file_for_delta(delta)
    local pan = -math.sin(delta);
    if (pan < -1) then
        pan = -1;
    elseif (pan > 1) then
        pan = 1;
    end

    local bin = math.floor(((pan + 1) * 6) + 0.5);
    if (bin < 0) then
        bin = 0;
    elseif (bin > 12) then
        bin = 12;
    end

    local rear = math.cos(delta) < -0.35;
    local prefix = rear and 'rear' or 'front';
    return ('%s\\%s_%02d.wav'):fmt(accessxi.nav_beacon_dir, prefix, bin), prefix, bin, pan;
end

function accessxi.nav_wall_distance(pos)
    if (pos == nil or not nav_try_load_mesh(pos.zone)) then
        return nil;
    end
    if (ffxinav == nil or accessxi.nav_mesh_handle == nil) then
        return nil;
    end

    local ok, distance = pcall(function () return ffxinav.GetDistanceToWall(accessxi.nav_mesh_handle, nav_mesh_position(pos)); end);
    distance = tonumber(distance);
    if (not ok or distance == nil or distance < 0 or distance > 10000) then
        return nil;
    end
    return distance;
end

function accessxi.nav_valid_mesh_position(pos)
    if (pos == nil or not nav_try_load_mesh(pos.zone)) then
        return false;
    end
    if (ffxinav == nil or accessxi.nav_mesh_handle == nil) then
        return false;
    end

    local ok, valid = pcall(function () return ffxinav.IsValidPosition(accessxi.nav_mesh_handle, nav_mesh_position(pos), false); end);
    return ok and valid == true;
end

function accessxi.nav_segment_obstacle(player, route_target)
    if (player == nil or route_target == nil) then
        return nil;
    end

    local ax = tonumber(player.x) or 0;
    local az = tonumber(player.z) or 0;
    local bx = tonumber(route_target.x) or 0;
    local bz = tonumber(route_target.z) or 0;
    local vx = bx - ax;
    local vz = bz - az;
    local segment_length = math.sqrt((vx * vx) + (vz * vz));
    local len2 = segment_length * segment_length;
    if (len2 < 0.001) then
        return nil;
    end

    local scan_ahead = math.max(5.5, math.min(13.5, segment_length + 2.0));
    local corridor_radius = 2.8;
    local warn_radius = 3.4;
    local player_index = tonumber(player.index) or -1;
    local best = nil;
    local candidates = accessxi.nav_live_entity_snapshot(80, scan_ahead + 8);
    for _, pos in ipairs(candidates) do
        if ((tonumber(pos.index) or -1) ~= player_index and accessxi.nav_live_entity_valid(pos)) then
            if (accessxi.nav_entity_is_dynamic_obstacle_candidate(pos)) then
                local wx = (tonumber(pos.x) or 0) - ax;
                local wz = (tonumber(pos.z) or 0) - az;
                local t = ((wx * vx) + (wz * vz)) / len2;
                if (t >= 0.08 and t <= 1.15) then
                    local cx = ax + (t * vx);
                    local cz = az + (t * vz);
                    local dx = (tonumber(pos.x) or 0) - cx;
                    local dz = (tonumber(pos.z) or 0) - cz;
                    local side_distance = math.sqrt((dx * dx) + (dz * dz));
                    local ahead_distance = math.sqrt(len2) * t;
                    local kind = tostring(pos.live_kind or accessxi.nav_entity_kind(pos));
                    local entity_radius = kind == 'player' and 1.4 or 1.7;
                    local collision_radius = corridor_radius + entity_radius;
                    if (ahead_distance >= 1.8 and ahead_distance <= scan_ahead and side_distance <= collision_radius) then
                        if (best == nil or ahead_distance < best.ahead) then
                            best = T{
                                entity = pos,
                                ahead = ahead_distance,
                                side = side_distance,
                                radius = collision_radius,
                                warn = side_distance <= (warn_radius + entity_radius),
                                t = t,
                                cx = cx,
                                cz = cz,
                            };
                        end
                    end
                end
            end
        end
    end

    return best;
end

function accessxi.nav_obstacle_avoidance_target(player, route_target)
    local obstacle = accessxi.nav_segment_obstacle(player, route_target);
    if (obstacle == nil) then
        accessxi.nav_obstacle_last_key = '';
        return nil, nil;
    end

    local ax = tonumber(player.x) or 0;
    local az = tonumber(player.z) or 0;
    local bx = tonumber(route_target.x) or 0;
    local bz = tonumber(route_target.z) or 0;
    local vx = bx - ax;
    local vz = bz - az;
    local length = math.sqrt((vx * vx) + (vz * vz));
    if (length < 0.001) then
        return nil, obstacle;
    end

    local nx = -vz / length;
    local nz = vx / length;
    local clearance = math.max(3.4, (tonumber(obstacle.radius) or 4.5) + 0.8);
    local left = T{
        zone = player.zone,
        x = (obstacle.cx or bx) + (nx * clearance),
        z = (obstacle.cz or bz) + (nz * clearance),
        y = player.y,
        name = 'obstacle left',
        kind = 'route',
        source = 'dynamic-obstacle',
    };
    local right = T{
        zone = player.zone,
        x = (obstacle.cx or bx) - (nx * clearance),
        z = (obstacle.cz or bz) - (nz * clearance),
        y = player.y,
        name = 'obstacle right',
        kind = 'route',
        source = 'dynamic-obstacle',
    };

    local left_wall = accessxi.nav_wall_distance(left) or 0;
    local right_wall = accessxi.nav_wall_distance(right) or 0;
    local left_valid = accessxi.nav_valid_mesh_position(left);
    local right_valid = accessxi.nav_valid_mesh_position(right);
    if (right_valid and (not left_valid or right_wall > left_wall)) then
        return right, obstacle;
    end
    if (left_valid) then
        return left, obstacle;
    end
    if (right_valid) then
        return right, obstacle;
    end
    return nil, obstacle;
end

function accessxi.nav_apply_dynamic_obstacle(player, route_target)
    if (accessxi.nav_route_points_are_collision(accessxi.nav_route_points)) then
        return route_target, nil;
    end
    local avoid, obstacle = accessxi.nav_obstacle_avoidance_target(player, route_target);
    if (obstacle == nil) then
        return route_target, nil;
    end

    local now = tick();
    local name = obstacle.entity ~= nil and obstacle.entity.name or 'obstacle';
    accessxi.nav_last_live_obstacle_tick = now;
    accessxi.nav_last_live_obstacle_name = name;
    local key = ('%s:%d'):fmt(name, math.floor((tonumber(obstacle.ahead) or 0) + 0.5));
    if ((obstacle.warn == true) and (key ~= accessxi.nav_obstacle_last_key or ((now - (accessxi.nav_obstacle_last_tick or 0)) > 9000))) then
        accessxi.nav_obstacle_last_key = key;
        accessxi.nav_obstacle_last_tick = now;
        log_line(('nav obstacle warn %s side=%.1f radius=%.1f ahead=%.1f avoid=%s'):fmt(
            name,
            obstacle.side or 0,
            obstacle.radius or 0,
            obstacle.ahead or 0,
            avoid ~= nil and 'yes' or 'no'));
    else
        local log_key = ('%s:%d:%d'):fmt(name, math.floor((tonumber(obstacle.side) or 0) * 10), math.floor((tonumber(obstacle.ahead) or 0) + 0.5));
        if (log_key ~= accessxi.nav_obstacle_last_key and ((now - (accessxi.nav_obstacle_last_tick or 0)) > 3000)) then
            accessxi.nav_obstacle_last_key = log_key;
            accessxi.nav_obstacle_last_tick = now;
            log_line(('nav obstacle avoid %s side=%.1f radius=%.1f ahead=%.1f avoid=%s'):fmt(
                name,
                obstacle.side or 0,
                obstacle.radius or 0,
                obstacle.ahead or 0,
                avoid ~= nil and 'yes' or 'no'));
        end
    end

    return avoid or route_target, obstacle;
end

function accessxi.nav_recent_live_obstacle(now)
    now = tonumber(now) or tick();
    return (now - (tonumber(accessxi.nav_last_live_obstacle_tick) or 0)) <= 2500;
end

function accessxi.nav_wall_escape_target(player, route_target)
    if (player == nil or route_target == nil) then
        return nil, nil;
    end

    local wall = accessxi.nav_wall_distance(player);
    if (wall == nil or wall > 1.2) then
        return nil, wall;
    end

    local best = nil;
    local best_score = -999999;
    local target_distance = nav_distance(player, route_target);
    if (target_distance <= 6) then
        return nil, wall;
    end
    local angles = T{ 0, 30, -30, 60, -60, 90, -90, 120, -120, 150, -150, 180 };
    local radii = T{ 3.5, 5.5, 7.5 };
    local yaw = tonumber(player.yaw) or 0;
    if (math.abs(yaw) > (math.pi * 2.1)) then
        yaw = yaw * math.pi / 180;
    end

    for _, radius in ipairs(radii) do
        for _, degrees in ipairs(angles) do
            local heading = -yaw + (degrees * math.pi / 180);
            local candidate = T{
                zone = player.zone,
                x = (tonumber(player.x) or 0) + (math.cos(heading) * radius),
                z = (tonumber(player.z) or 0) + (math.sin(heading) * radius),
                y = player.y,
                name = 'wall escape',
                kind = 'route',
                source = 'wall-escape',
            };
            if (accessxi.nav_valid_mesh_position(candidate)) then
                local clearance = accessxi.nav_wall_distance(candidate) or 0;
                local to_route = nav_distance(candidate, route_target);
                local progress = target_distance - to_route;
                local score = (clearance * 4.0) + (progress * 1.5) - (math.abs(degrees) * 0.02) - (radius * 0.05);
                if (clearance >= 1.2 and progress >= 0.2 and score > best_score) then
                    best = candidate;
                    best.clearance = clearance;
                    best.progress = progress;
                    best.radius = radius;
                    best.degrees = degrees;
                    best_score = score;
                end
            end
        end
    end

    return best, wall;
end

function accessxi.nav_apply_wall_avoidance(player, route_target)
    local now = tick();
    if (not accessxi.nav_wall_escape_recovery_active(now)) then
        accessxi.nav_wall_avoid_last_key = '';
        return route_target, nil;
    end
    local escape, wall = accessxi.nav_wall_escape_target(player, route_target);
    if (escape == nil) then
        if (wall == nil or wall > 1.2) then
            accessxi.nav_wall_avoid_last_key = '';
        end
        return route_target, wall;
    end

    local key = ('%d:%d:%d'):fmt(
        math.floor((tonumber(escape.x) or 0) * 2),
        math.floor((tonumber(escape.z) or 0) * 2),
        math.floor((tonumber(wall) or 0) * 10));
    if (key ~= accessxi.nav_wall_avoid_last_key or ((now - (accessxi.nav_wall_avoid_last_tick or 0)) > 7000)) then
        accessxi.nav_wall_avoid_last_key = key;
        accessxi.nav_wall_avoid_last_tick = now;
        log_line(('nav wall escape wall=%.2f clearance=%.2f radius=%.1f degrees=%d progress=%.1f'):fmt(
            wall or 0,
            escape.clearance or 0,
            escape.radius or 0,
            escape.degrees or 0,
            escape.progress or 0));
    end

    return escape, wall;
end

function accessxi.nav_wall_escape_recovery_active(now)
    now = tonumber(now) or tick();
    local started = tonumber(accessxi.nav_progress_last_block_tick) or 0;
    return started > 0 and now >= started and (now - started) <= 4500;
end

function accessxi.nav_wall_escape_begin_recovery(now)
    accessxi.nav_progress_last_block_tick = tonumber(now) or tick();
end

function accessxi.nav_reset_progress_watch(player, destination_distance, now)
    accessxi.nav_progress_x = player ~= nil and player.x or nil;
    accessxi.nav_progress_z = player ~= nil and player.z or nil;
    accessxi.nav_progress_distance = tonumber(destination_distance) or 0;
    accessxi.nav_progress_tick = tonumber(now) or tick();
end

function accessxi.nav_progress_watch(player, destination, route_target, destination_distance, now, movement_signal)
    if (player == nil or destination == nil or route_target == nil) then
        return false;
    end

    now = tonumber(now) or tick();
    if (now < (tonumber(accessxi.nav_collision_quiet_until) or 0)) then
        accessxi.nav_reset_progress_watch(nil, 0, now);
        return false;
    end

    movement_signal = movement_signal or accessxi.nav_player_movement_signal(player, now);
    if (not accessxi.nav_collision_current_movement_intent(movement_signal)) then
        accessxi.nav_reset_progress_watch(player, destination_distance, now);
        return false;
    end

    if (accessxi.nav_progress_x == nil or accessxi.nav_progress_z == nil or (accessxi.nav_progress_tick or 0) == 0) then
        accessxi.nav_reset_progress_watch(player, destination_distance, now);
        return false;
    end

    local anchor = T{ x = accessxi.nav_progress_x, z = accessxi.nav_progress_z, y = player.y, zone = player.zone };
    local moved = nav_distance(player, anchor);
    local improvement = (tonumber(accessxi.nav_progress_distance) or destination_distance) - destination_distance;
    if (moved >= 3 or improvement >= 3) then
        accessxi.nav_reset_progress_watch(player, destination_distance, now);
        return false;
    end

    if ((now - (accessxi.nav_progress_tick or 0)) < 7000) then
        return false;
    end
    if ((now - (accessxi.nav_progress_last_block_tick or 0)) < 9000) then
        return false;
    end

    accessxi.nav_wall_escape_begin_recovery(now);
    local wall = accessxi.nav_wall_distance(player);
    local route_distance = nav_distance(player, route_target);
    local text = 'No forward progress.';
    if (wall ~= nil and wall <= 2.5) then
        text = ('No forward progress. Near wall. Clearance %.0f yalm.'):fmt(wall);
    elseif (wall ~= nil) then
        text = ('No forward progress. Wall clearance %.0f yalms.'):fmt(wall);
    else
        text = 'No forward progress. Try turning until the beacon moves off-center.';
    end

    accessxi.nav_route_last_recalc_tick = now;
    local new_points = accessxi.nav_compute_route_with_zoneline_approach(player, destination);
    if (new_points:len() > 1) then
        accessxi.nav_route_points = new_points;
        accessxi.nav_route_point_index = accessxi.nav_first_route_index(player, new_points, destination);
        text = text .. ' Route refreshed.';
    else
        local unsafe_route_text = accessxi.nav_route_direct_fallback_block_reason(player, destination);
        if (unsafe_route_text ~= '') then
            nav_write_route_evidence('unreachable', player, destination, nil, T{ wall = wall, off_route = route_distance, reason = unsafe_route_text });
            accessxi.nav_active = false;
            accessxi.nav_destination = nil;
            accessxi.nav_route_points:clear();
            accessxi.nav_route_point_index = 1;
            accessxi.nav_last_key = '';
            accessxi.nav_last_direction_text = unsafe_route_text;
            speak(unsafe_route_text);
            log_line('nav blocked unsafe ' .. unsafe_route_text);
            accessxi.nav_reset_progress_watch(player, destination_distance, now);
            return true;
        end
    end

    local failure_key = ('%s:%d:%d:%d'):fmt(destination.name or '', math.floor(tonumber(player.x) or 0), math.floor(tonumber(player.z) or 0), tonumber(accessxi.nav_route_point_index) or 0);
    if (failure_key ~= accessxi.nav_last_failure_key or (now - (accessxi.nav_last_failure_tick or 0)) > 15000) then
        accessxi.nav_last_failure_key = failure_key;
        accessxi.nav_last_failure_tick = now;
        nav_write_route_evidence('blocked', player, destination, route_target, T{ wall = wall, off_route = route_distance, reason = text });
    end

    accessxi.nav_last_direction_text = text;
    local sound_ok = accessxi.nav_collision_play_sound('blocked', now);
    speak(text);
    log_line(('nav blocked moved=%.1f improve=%.1f route=%.1f wall=%s sound=%s %s'):fmt(
        moved,
        improvement,
        route_distance,
        wall ~= nil and ('%.2f'):fmt(wall) or 'unknown',
        sound_ok and 'ok' or 'failed',
        text));
    accessxi.nav_reset_progress_watch(player, destination_distance, now);
    return true;
end

function accessxi.nav_route_guidance_speech_enabled()
    return not accessxi.nav_beacon_enabled;
end

function accessxi.nav_speak_route_guidance(text)
    if (accessxi.nav_route_guidance_speech_enabled()) then
        speak(text);
    end
end

function accessxi.poll_nav_beacon()
    if (not accessxi.nav_beacon_enabled or not accessxi.nav_active or accessxi.nav_destination == nil) then
        return;
    end

    local now = tick();
    local last_pulse_tick = math.max(
        tonumber(accessxi.nav_beacon_last_tick) or 0,
        tonumber(accessxi.nav_beacon_last_attempt_tick) or 0);
    if ((now - last_pulse_tick) < 520) then
        return;
    end
    if (not accessxi.beacon_audio_available(now)) then
        return;
    end

    if (nav_route_suppressed()) then
        return;
    end

    local player = nav_cached_player_position();
    local route_target = nil;
    local drop_handled = false;
    if (type(accessxi.nav_dangruf_fount_drop_beacon_target) == 'function') then
        route_target, drop_handled = accessxi.nav_dangruf_fount_drop_beacon_target(player, now);
    end
    local transport_waiting = false;
    if (not drop_handled and type(accessxi.nav_transport_waiting_beacon_target) == 'function') then
        route_target, transport_waiting = accessxi.nav_transport_waiting_beacon_target(player, now);
        if (transport_waiting and route_target == nil) then
            return;
        end
    end
    if (not drop_handled and not transport_waiting) then
        if (accessxi.nav_door_waiting(player, now)) then
            return;
        end
        route_target = accessxi.nav_beacon_route_target(player);
    end
    if (player == nil or route_target == nil) then
        return;
    end
    local precise_override = (not drop_handled and not transport_waiting)
        and accessxi.nav_route_precise_override_active(player, accessxi.nav_route_points);
    if (not precise_override and not transport_waiting and not drop_handled) then
        route_target = accessxi.nav_apply_dynamic_obstacle(player, route_target);
        route_target = accessxi.nav_apply_wall_avoidance(player, route_target);
    end

    local destination_distance = nav_distance(player, accessxi.nav_destination);
    if (destination_distance <= accessxi.nav_arrival_radius(accessxi.nav_destination)) then
        return;
    end

    local route_identity = accessxi.nav_route_points;
    if (route_identity == nil or route_identity:len() < 2) then
        route_identity = accessxi.nav_route_start_point or accessxi.nav_destination;
    end
    if (accessxi.nav_beacon_route_identity ~= route_identity) then
        accessxi.nav_beacon_reset_direction_state();
        accessxi.nav_beacon_route_identity = route_identity;
    end
    local route_geometry = not drop_handled and not transport_waiting
        and accessxi.nav_route_points ~= nil and accessxi.nav_route_points:len() > 1;
    local direction_acquired_before = accessxi.nav_beacon_route_acquired;
    local direction_centered_before = accessxi.nav_beacon_centered;
    local direction_center_index_before = accessxi.nav_beacon_center_index;
    local direction_previous_delta_before = accessxi.nav_beacon_previous_delta;
    local direction_motion_x_before = accessxi.nav_beacon_motion_x;
    local direction_motion_z_before = accessxi.nav_beacon_motion_z;
    local function restore_unheard_direction_state()
        accessxi.nav_beacon_route_acquired = direction_acquired_before;
        accessxi.nav_beacon_centered = direction_centered_before;
        accessxi.nav_beacon_center_index = direction_center_index_before;
        accessxi.nav_beacon_previous_delta = direction_previous_delta_before;
        accessxi.nav_beacon_motion_x = direction_motion_x_before;
        accessxi.nav_beacon_motion_z = direction_motion_z_before;
    end
    local delta = accessxi.nav_beacon_direction_delta(
        player, route_target, accessxi.nav_route_points, accessxi.nav_route_point_index, route_geometry);
    if (delta == nil) then
        restore_unheard_direction_state();
        return;
    end
    if (not accessxi.nav_beacon_ensure_files()) then
        restore_unheard_direction_state();
        return;
    end
    local path, prefix, bin, pan = accessxi.nav_beacon_file_for_delta(delta);
    local fallback_path = ('%s\\%s_%02d.wav'):fmt(
        accessxi.nav_beacon_compat_dir, prefix, bin);

    accessxi.nav_beacon_last_attempt_tick = now;
    if (not accessxi.nav_beacon_play(path, now, fallback_path)) then
        restore_unheard_direction_state();
        return;
    end
    accessxi.nav_beacon_last_tick = now;
    accessxi.beacon_audio_claim('nav', 180, now);

    local key = ('%s:%02d'):fmt(prefix, bin);
    if (key ~= accessxi.nav_beacon_last_key) then
        accessxi.nav_beacon_last_key = key;
        log_line(('nav beacon %s pan=%.2f delta=%.0f'):fmt(key, pan, delta * 180 / math.pi));
    end
end

local function poll_nav_route()
    if (not accessxi.nav_active or accessxi.nav_destination == nil) then
        return;
    end
    if (accessxi.nav_dat_collision_pending ~= nil) then
        return;
    end
    if (type(accessxi.nav_mission_quest_route_owner_mismatch) == 'function'
        and accessxi.nav_mission_quest_route_owner_mismatch()) then
        if (accessxi.nav_cancel_mission_quest_route('active-route-owner-mismatch')) then
            local text = 'Mission or quest route stopped because the active character changed.';
            speak(text);
            log_line('nav objective active owner mismatch');
        end
        return;
    end

    local now = tick();
    accessxi.nav_precise_route_track_index(nav_cached_player_position(), now);
    if ((now - (accessxi.nav_last_tick or 0)) < (tonumber(accessxi.nav_route_poll_ms) or 850)) then
        return;
    end
    accessxi.nav_last_tick = now;

    if (accessxi.nav_collision_update_control_interrupt(now)) then
        return;
    end
    if (nav_route_suppressed()) then
        return;
    end

    local player = nav_cached_player_position();
    if (player == nil) then
        return;
    end
    if (accessxi.nav_objective_route_state ~= nil) then
        local current, reason = accessxi.nav_objective_route_revalidate_or_cancel(player);
        if (not current) then
            local text = nav_clean_field(reason) ~= '' and nav_clean_field(reason)
                or 'Mission or quest route stopped because the active objective changed.';
            speak(text);
            log_line('nav objective active state mismatch ' .. text);
            return;
        end
    end
    if (accessxi.nav_door_waiting(player, now)) then
        return;
    end

    local destination = accessxi.nav_destination;
    if ((tonumber(destination.zone) or 0) ~= (tonumber(player.zone) or 0)) then
        local text = ('Zoned. Route to %s complete.'):fmt(destination.name or 'destination');
        nav_write_route_evidence('zoned', player, destination, nil, T{ reason = 'zone change' });
        accessxi.nav_active = false;
        accessxi.nav_destination = nil;
        accessxi.nav_route_points:clear();
        accessxi.nav_route_point_index = 1;
        accessxi.nav_last_key = '';
        accessxi.nav_last_direction_text = '';
        accessxi.nav_beacon_last_key = '';
        accessxi.nav_beacon_last_tick = 0;
        accessxi.nav_progress_x = nil;
        accessxi.nav_progress_z = nil;
        accessxi.nav_progress_distance = 0;
        accessxi.nav_progress_tick = 0;
        accessxi.nav_progress_last_block_tick = 0;
        accessxi.nav_progress_last_log_key = '';
        accessxi.nav_collision_x = nil;
        accessxi.nav_collision_z = nil;
        accessxi.nav_collision_destination_distance = 0;
        accessxi.nav_collision_route_distance = 0;
        accessxi.nav_collision_tick = 0;
        accessxi.nav_collision_last_sound_tick = 0;
        accessxi.nav_collision_last_key = '';
        speak(text);
        log_line(('nav zoned complete name="%s" oldzone=%d newzone=%d x=%.3f z=%.3f'):fmt(destination.name or '', destination.zone or 0, player.zone or 0, player.x or 0, player.z or 0));
        return;
    end

    if (accessxi.nav_refresh_live_route_destination(player, now)) then
        destination = accessxi.nav_destination;
        if (destination == nil) then
            return;
        end
    end

    if (type(accessxi.nav_dangruf_fount_drop_poll) == 'function'
        and accessxi.nav_dangruf_fount_drop_poll(player, destination, now)) then
        return;
    end

    if (type(accessxi.nav_transport_transition_poll) == 'function'
        and accessxi.nav_transport_transition_poll(player, destination, now)) then
        return;
    end

    if ((accessxi.nav_route_points:len() == 0) and ((now - (accessxi.nav_route_last_recalc_tick or 0)) > 3000)) then
        accessxi.nav_route_last_recalc_tick = now;
        accessxi.nav_route_points = accessxi.nav_compute_route_with_zoneline_approach(player, destination);
        if (accessxi.nav_route_points:len() > 1) then
            accessxi.nav_route_point_index = accessxi.nav_first_route_index(player, accessxi.nav_route_points, destination);
        else
            local unsafe_route_text = accessxi.nav_route_direct_fallback_block_reason(player, destination);
            if (unsafe_route_text ~= '') then
                nav_write_route_evidence('unreachable', player, destination, nil, T{ reason = unsafe_route_text });
                accessxi.nav_active = false;
                accessxi.nav_destination = nil;
                accessxi.nav_route_points:clear();
                accessxi.nav_route_point_index = 1;
                accessxi.nav_last_key = '';
                accessxi.nav_last_direction_text = unsafe_route_text;
                speak(unsafe_route_text);
                log_line('nav route blocked ' .. unsafe_route_text);
                return;
            end
        end
    end

    if (accessxi.nav_route_points:len() > 1
        and not accessxi.nav_route_points_are_override(accessxi.nav_route_points)
        and accessxi.nav_nearby_zoneline_direct_route_allowed(player, destination)) then
        accessxi.nav_route_points:clear();
        accessxi.nav_route_point_index = 1;
        log_line(('nav direct nearby zoneline active destination="%s" distance=%.1f'):fmt(
            destination.name or '',
            nav_distance(player, destination)));
    end

    local route_count = accessxi.nav_route_points:len();
    local route_delta = nil;
    if (route_count > 1) then
        local current_id = accessxi.nav_route_points_override_id(accessxi.nav_route_points);
        local current_is_override = accessxi.nav_route_points_are_override(accessxi.nav_route_points);
        local collision_authoritative = current_id == 'dat-collision';
        local survey_authoritative = current_id:startswith('lathine-recorded-survey-');
        local lower_ravine_handoff = (not collision_authoritative)
            and (not survey_authoritative)
            and accessxi.nav_lathine_lower_ravine_position(player)
            and current_id ~= 'lathine-fallen-ravine-to-west-ronfaure-zoneline';
        local override_handoff = T{};
        if ((not current_is_override) or lower_ravine_handoff) then
            override_handoff = accessxi.nav_route_override_points(player, destination);
        end
        local recorded_handoff = accessxi.nav_lathine_live_recorded_corridor_handoff(
            player, destination, accessxi.nav_route_points);
        if (recorded_handoff:len() > 1) then
            override_handoff = recorded_handoff;
        end
        if (override_handoff:len() > 1) then
            local handoff_id = accessxi.nav_route_points_override_id(override_handoff);
            if (override_handoff:len() > 1
                and ((not current_is_override)
                    or (handoff_id ~= '' and handoff_id ~= current_id))) then
                accessxi.nav_route_points = override_handoff;
                accessxi.nav_route_point_index = accessxi.nav_first_route_index(player, override_handoff, destination);
                accessxi.nav_route_last_recalc_tick = now;
                route_count = accessxi.nav_route_points:len();
                log_line(('nav route override handoff destination="%s" id="%s" from="%s" count=%d'):fmt(destination.name or '', handoff_id, current_id, route_count));
            end
        end
    end

    if (route_count > 1 and not accessxi.nav_door_context_active(now)) then
        route_delta = accessxi.nav_route_position_delta(player, accessxi.nav_route_points);
        local live_replan_reason = accessxi.nav_route_live_replan_reason(player, destination, accessxi.nav_route_points, route_delta);
        local live_key = ('%s:%s'):fmt(live_replan_reason, accessxi.nav_route_points_override_id(accessxi.nav_route_points));
        if (live_replan_reason ~= ''
            and ((now - (tonumber(accessxi.nav_route_live_replan_last_tick) or 0)) > 1200
                or live_key ~= tostring(accessxi.nav_route_live_replan_last_key or ''))) then
            accessxi.nav_route_live_replan_last_key = live_key;
            accessxi.nav_route_live_replan_last_tick = now;
            accessxi.nav_route_last_recalc_tick = now;
            local new_points = accessxi.nav_compute_route_with_zoneline_approach(player, destination);
            if (new_points:len() > 1) then
                accessxi.nav_route_points = new_points;
                accessxi.nav_route_point_index = accessxi.nav_first_route_index(player, new_points, destination);
                route_count = accessxi.nav_route_points:len();
                route_delta = accessxi.nav_route_position_delta(player, accessxi.nav_route_points);
                accessxi.nav_reset_progress_watch(player, nav_distance(player, destination), now);
                accessxi.nav_collision_reset(nil, 0, 0, now);
                local new_id = accessxi.nav_route_points_override_id(accessxi.nav_route_points);
                log_line(('nav live replan reason="%s" destination="%s" id="%s" count=%d horizontal=%.1f vertical=%.1f below=%.1f'):fmt(
                    live_replan_reason,
                    destination.name or '',
                    new_id,
                    route_count,
                    route_delta ~= nil and (tonumber(route_delta.horizontal) or 0) or 0,
                    route_delta ~= nil and (tonumber(route_delta.vertical) or 0) or 0,
                    route_delta ~= nil and (tonumber(route_delta.below) or 0) or 0));
                nav_write_route_evidence('replanned', player, destination, accessxi.nav_route_points[accessxi.nav_route_point_index] or destination, T{
                    reason = live_replan_reason,
                    route_id = new_id,
                    off_route = route_delta ~= nil and route_delta.horizontal or 0,
                    below = route_delta ~= nil and route_delta.below or 0,
                });
            end
        end
    end

    local route_target = destination;
    local real_route_target = destination;
    if (route_count > 1) then
        accessxi.nav_sync_route_index(player);
        if (accessxi.nav_route_point_index < 1) then
            accessxi.nav_route_point_index = 1;
        elseif (accessxi.nav_route_point_index > route_count) then
            accessxi.nav_route_point_index = route_count;
        end
        real_route_target = accessxi.nav_route_points[accessxi.nav_route_point_index] or destination;
        route_target = real_route_target;
    end

    local next_target = (route_count > 1 and accessxi.nav_route_point_index < route_count) and accessxi.nav_route_points[accessxi.nav_route_point_index + 1] or nil;
    local precise_override = accessxi.nav_route_precise_override_active(player, accessxi.nav_route_points);
    if (route_count > 1 and precise_override) then
        route_target = accessxi.nav_precise_steering_target(
            player, accessxi.nav_route_points, accessxi.nav_route_point_index, 5);
        next_target = nil;
    elseif (route_count > 1) then
        route_target, next_target = accessxi.nav_indexed_lookahead_target(player, accessxi.nav_route_points, accessxi.nav_route_lookahead_distance(player, destination));
        route_target = route_target or real_route_target;
    end
    if (route_count > 1 and precise_override and route_target == nil) then
        accessxi.nav_last_direction_text = '';
        return;
    end
    if (accessxi.nav_door_prompt_for_route(player, destination, route_target, now)) then
        return;
    end
    if (not precise_override) then
        route_target = accessxi.nav_apply_dynamic_obstacle(player, route_target);
        route_target = accessxi.nav_apply_wall_avoidance(player, route_target);
    end
    local phrase, distance, dx, dz = accessxi.nav_guidance_phrase(player, route_target, next_target, false);
    local real_waypoint_distance = route_count > 1 and nav_distance(player, real_route_target) or distance;
    if (route_count > 1
        and not precise_override
        and real_waypoint_distance <= accessxi.nav_route_waypoint_arrival_radius(destination)
        and accessxi.nav_route_point_index < route_count) then
        accessxi.nav_route_point_index = accessxi.nav_route_point_index + 1;
        real_route_target = accessxi.nav_route_points[accessxi.nav_route_point_index] or destination;
        route_target = real_route_target;
        next_target = (accessxi.nav_route_point_index < route_count) and accessxi.nav_route_points[accessxi.nav_route_point_index + 1] or nil;
        precise_override = accessxi.nav_route_precise_override_active(player, accessxi.nav_route_points);
        if (not precise_override) then
            route_target, next_target = accessxi.nav_indexed_lookahead_target(player, accessxi.nav_route_points, accessxi.nav_route_lookahead_distance(player, destination));
            route_target = route_target or real_route_target;
        end
        if (not precise_override) then
            route_target = accessxi.nav_apply_dynamic_obstacle(player, route_target);
            route_target = accessxi.nav_apply_wall_avoidance(player, route_target);
        end
        phrase, distance, dx, dz = accessxi.nav_guidance_phrase(player, route_target, next_target, false);
        local text = phrase;
        accessxi.nav_last_direction_text = text;
        accessxi.nav_speak_route_guidance(text);
        log_line(('nav waypoint %d/%d %s'):fmt(accessxi.nav_route_point_index, route_count, text));
        return;
    end

    route_delta = route_count > 1 and (route_delta or accessxi.nav_route_position_delta(player, accessxi.nav_route_points)) or nil;
    local off_route_distance = route_delta ~= nil and (tonumber(route_delta.horizontal) or 0) or 0;
    local vertical_route_distance = route_delta ~= nil and (tonumber(route_delta.vertical) or 0) or 0;
    local below_route_distance = route_delta ~= nil and (tonumber(route_delta.below) or 0) or 0;
    if (route_count > 1
        and not accessxi.nav_door_context_active(now)
        and (off_route_distance > 16 or vertical_route_distance > 7.0)
        and ((now - (accessxi.nav_route_last_recalc_tick or 0)) > 6000)) then
        accessxi.nav_route_last_recalc_tick = now;
        local new_points = accessxi.nav_compute_route_with_zoneline_approach(player, destination);
        if (new_points:len() > 1) then
            accessxi.nav_route_points = new_points;
            accessxi.nav_route_point_index = accessxi.nav_first_route_index(player, new_points, destination);
            real_route_target = accessxi.nav_route_points[accessxi.nav_route_point_index];
            route_target = real_route_target;
            route_count = accessxi.nav_route_points:len();
            next_target = (accessxi.nav_route_point_index < route_count) and accessxi.nav_route_points[accessxi.nav_route_point_index + 1] or nil;
            precise_override = accessxi.nav_route_precise_override_active(player, accessxi.nav_route_points);
            if (precise_override) then
                route_target = accessxi.nav_precise_steering_target(
                    player, accessxi.nav_route_points, accessxi.nav_route_point_index, 5);
                next_target = nil;
            else
                route_target, next_target = accessxi.nav_indexed_lookahead_target(player, accessxi.nav_route_points, accessxi.nav_route_lookahead_distance(player, destination));
                route_target = route_target or real_route_target;
            end
            if (precise_override and route_target == nil) then
                accessxi.nav_last_direction_text = '';
                return;
            end
            if (not precise_override) then
                route_target = accessxi.nav_apply_dynamic_obstacle(player, route_target);
                route_target = accessxi.nav_apply_wall_avoidance(player, route_target);
            end
            phrase, distance, dx, dz = accessxi.nav_guidance_phrase(player, route_target, next_target, false);
            local text = ('Route adjusted. %s'):fmt(phrase);
            accessxi.nav_last_direction_text = text;
            accessxi.nav_speak_route_guidance(text);
            log_line(('nav route adjusted offroute=%.1f vertical=%.1f below=%.1f %s'):fmt(off_route_distance, vertical_route_distance, below_route_distance, text));
            return;
        end
    end

    local destination_distance = nav_distance(player, destination);
    if (destination_distance <= accessxi.nav_arrival_radius(destination)) then
        if (accessxi.nav_zone_search_target ~= nil and tostring(destination.source or ''):startswith('zonesearch:')) then
            if tonumber(destination.same_zone_reentry_step) ~= nil
                and (type(accessxi.nav_same_zone_reentry_advance) ~= 'function'
                    or not accessxi.nav_same_zone_reentry_advance(destination)) then
                local failed_name = nav_clean_field(accessxi.nav_zone_search_target.name or destination.final_name or 'destination');
                accessxi.nav_clear_zone_search();
                accessxi.nav_active = false;
                accessxi.nav_destination = nil;
                accessxi.nav_route_points:clear();
                local failed_text = ('Safe re-entry route to %s stopped because the zone step no longer matched.'):fmt(failed_name);
                speak(failed_text);
                log_line('nav same-zone reentry arrival rejected ' .. failed_text);
                return;
            end
            nav_write_route_evidence('zone-leg-arrived', player, destination, route_target, T{ reason = 'zone search leg arrival' });
            accessxi.nav_begin_zoning_watch('zone-search-zoneline-arrival', player, destination, now);
            accessxi.nav_collision_quiet('zone-search-zoneline-arrival', accessxi.nav_collision_zoneline_quiet_ms, now);
            accessxi.nav_zone_search_waiting_zone = tonumber(destination.to_zone) or 0;
            accessxi.nav_zone_search_waiting_from_zone = tonumber(destination.zone) or 0;
            accessxi.nav_active = false;
            accessxi.nav_destination = nil;
            accessxi.nav_route_points:clear();
            accessxi.nav_route_point_index = 1;
            accessxi.nav_last_key = '';
            accessxi.nav_last_direction_text = '';
            accessxi.nav_beacon_last_key = '';
            accessxi.nav_beacon_last_tick = 0;
            accessxi.nav_progress_x = nil;
            accessxi.nav_progress_z = nil;
            accessxi.nav_progress_distance = 0;
            accessxi.nav_progress_tick = 0;
            accessxi.nav_progress_last_block_tick = 0;
            accessxi.nav_progress_last_log_key = '';
            accessxi.nav_collision_x = nil;
            accessxi.nav_collision_z = nil;
            accessxi.nav_collision_destination_distance = 0;
            accessxi.nav_collision_route_distance = 0;
            accessxi.nav_collision_tick = 0;
            accessxi.nav_collision_last_sound_tick = 0;
            accessxi.nav_collision_last_key = '';
            local next_zone_name = nav_clean_field(destination.to_zone_name or accessxi.nav_graph_zone_name(destination.to_zone));
            local final_name = nav_clean_field(destination.final_name or (accessxi.nav_zone_search_target ~= nil and accessxi.nav_zone_search_target.name or 'NPC'));
            local text = ('At %s. Zone into %s to continue to %s.'):fmt(destination.name or 'zone line', next_zone_name ~= '' and next_zone_name or 'the next zone', final_name ~= '' and final_name or 'the NPC');
            speak(text);
            log_line(('nav zone search leg arrived name="%s" from=%d to=%d final="%s"'):fmt(
                destination.name or '',
                destination.zone or 0,
                destination.to_zone or 0,
                final_name));
            return;
        end
        nav_write_route_evidence('arrived', player, destination, route_target, T{ reason = 'arrival' });
        if (type(accessxi.nav_mission_quest_remember_arrival) == 'function') then
            pcall(function ()
                accessxi.nav_mission_quest_remember_arrival(destination, now);
            end);
        end
        local arrival_name = tostring(destination.name or ''):lower();
        if (arrival_name:find('zone line', 1, true) ~= nil) then
            accessxi.nav_begin_zoning_watch('zone-line-arrival', player, destination, now);
            accessxi.nav_collision_quiet('zone-line-arrival', accessxi.nav_collision_zoneline_quiet_ms, now);
        end
        if (accessxi.nav_zone_search_target ~= nil and (tonumber(destination.zone) or 0) == (tonumber(accessxi.nav_zone_search_target.zone) or 0)) then
            accessxi.nav_clear_zone_search();
        end
        accessxi.nav_active = false;
        accessxi.nav_destination = nil;
        accessxi.nav_route_points:clear();
        accessxi.nav_route_point_index = 1;
        accessxi.nav_last_key = '';
        accessxi.nav_last_direction_text = '';
        accessxi.nav_beacon_last_key = '';
        accessxi.nav_beacon_last_tick = 0;
        accessxi.nav_progress_x = nil;
        accessxi.nav_progress_z = nil;
        accessxi.nav_progress_distance = 0;
        accessxi.nav_progress_tick = 0;
        accessxi.nav_progress_last_block_tick = 0;
        accessxi.nav_progress_last_log_key = '';
        accessxi.nav_collision_x = nil;
        accessxi.nav_collision_z = nil;
        accessxi.nav_collision_destination_distance = 0;
        accessxi.nav_collision_route_distance = 0;
        accessxi.nav_collision_tick = 0;
        accessxi.nav_collision_last_sound_tick = 0;
        accessxi.nav_collision_last_key = '';
        local arrival_suffix = '';
        if (type(accessxi.nav_mission_quest_arrival_suffix) == 'function') then
            arrival_suffix = accessxi.nav_mission_quest_arrival_suffix(destination);
        end
        speak(('Arrived at %s.%s'):fmt(destination.name or 'destination', arrival_suffix));
        log_line(('nav arrived name="%s" zone=%d x=%.3f z=%.3f'):fmt(destination.name or '', player.zone or 0, player.x or 0, player.z or 0));
        return;
    end

    local movement_signal = accessxi.nav_player_movement_signal(player, now);
    if (accessxi.nav_collision_watch(player, destination, route_target, destination_distance, now, movement_signal)) then
        return;
    end

    if (accessxi.nav_progress_watch(player, destination, route_target, destination_distance, now, movement_signal)) then
        return;
    end

    accessxi.nav_route_contact_sound(player, route_target, now, movement_signal);

    local key = ('%s:%d:%d:%d:%d'):fmt(destination.name or '', accessxi.nav_route_point_index or 0, math.floor((distance + 2.5) / 5), math.floor((dx + 5) / 10), math.floor((dz + 5) / 10));
    if (key ~= accessxi.nav_last_key) then
        accessxi.nav_last_key = key;
        local prefix = route_count > 1 and '' or ('To %s. '):fmt(destination.name or 'destination');
        local text = prefix .. phrase;
        accessxi.nav_last_direction_text = text;
        accessxi.nav_speak_route_guidance(text);
        if (key ~= accessxi.nav_last_log) then
            accessxi.nav_last_log = key;
            log_line(('nav route %s player=(%.3f,%.3f,%.3f) dest=(%.3f,%.3f,%.3f)'):fmt(
                text,
                player.x or 0,
                player.z or 0,
                player.y or 0,
                destination.x or 0,
                destination.z or 0,
                destination.y or 0));
        end
    end
end

local function load_step(name, fn)
    local ok, result = pcall(fn);
    if (not ok) then
        log_line(('load step failed name=%s error="%s"'):fmt(
            tostring(name or ''),
            accessxi.escape_probe_log_text(tostring(result or ''))));
        return false;
    end
    return true;
end

local function load_find_pointer(name, pattern, offset)
    local value = 0;
    load_step('find-' .. tostring(name or ''), function ()
        value = ashita.memory.find(0, 0, pattern, offset, 0);
    end);
    return value or 0;
end

function accessxi.run_load_startup(reason)
    if (accessxi.load_startup_ran == true) then
        log_line(('load skipped reason=%s already-ran'):fmt(accessxi.escape_probe_log_text(tostring(reason or ''))));
        return;
    end
    accessxi.load_startup_ran = true;
    log_line('load begin');
    load_step('prism-init', function () accessxi.prism_init_speech(true); end);

    load_step('nav-load-points', nav_load_points);
    load_step('nav-beacon-ensure-files', function () accessxi.nav_beacon_ensure_files(); end);
    load_step('nav-collision-ensure-sounds', function () accessxi.nav_collision_ensure_sounds(); end);
    load_step('seed-chat-history', function () accessxi.seed_chat_history_from_log(); end);
    load_step('restore-mission-packet-cache', function () accessxi.restore_mission_packet_cache_if_needed(); end);
    load_step('restore-quest-packet-cache', function () accessxi.restore_quest_packet_cache_if_needed(); end);
    load_step('restore-job-abilities-packet-cache', function () accessxi.restore_job_abilities_packet_cache_if_needed(); end);
    load_step('restore-job-traits-packet-cache', function () accessxi.restore_job_traits_packet_cache_if_needed(); end);
    load_step('restore-merit-packet-cache', function () accessxi.restore_merit_packet_cache_if_needed(); end);
    load_step('restore-key-items-packet-cache', function () accessxi.restore_key_items_packet_cache_if_needed(); end);
    load_step('load-searchhook', function () accessxi.load_searchhook(); end);
    load_step('macro-active-profile', function () accessxi.macro_active_profile(); end);
    load_step('blue-magic-current-set-probe', function ()
        log_state('state blue-magic-current-set-probe ' .. accessxi.blue_magic_current_set_probe_text());
        log_state('state blue-magic-current-cast-probe ' .. accessxi.blue_magic_current_cast_probe_text());
    end);

    accessxi.ptrs.license  = load_find_pointer('license', '895E1C895E14896E1889??????????EB??89??????????68', 0x0B);
    accessxi.ptrs.lobby    = load_find_pointer('lobby', '89412C8B15????????897C2410894230A1', 0x5);
    accessxi.ptrs.select   = load_find_pointer('select', '89412C8B15????????897C2410894230A1', 0x11);
    accessxi.ptrs.selectidx= load_find_pointer('selectidx', 'A1????????8B5108406689424C8B4908668B414C50E8', 0x01);
    accessxi.ptrs.yesno    = load_find_pointer('yesno', '895E1C895E14896E1889??????????EB??89??????????68', 0x47);
    pcall(function ()
        local patchsite = accessxi.magic_shortcut_resolve();
        if (accessxi.is_probe_pointer(patchsite)) then
            log_line(('magicshortcut load patch=0x%08X flag=%d call=0x%08X bytes="%s"'):fmt(
                patchsite,
                read_u8(patchsite + 0x06) or -1,
                tonumber(accessxi.magic_shortcut_call_target) or 0,
                accessxi.escape_probe_log_text(accessxi.format_probe_bytes(patchsite, 0, 0x20))));
        else
            log_line('magicshortcut load patch=missing');
        end
    end);
    log_line(('loaded speech=prism backend=%s prism_error="%s" license=0x%08X lobby=0x%08X select=0x%08X yesno=0x%08X'):fmt(
        speech.backend_name ~= '' and speech.backend_name or 'none',
        tostring(accessxi.prism_last_error or ''):gsub('"', "'"),
        accessxi.ptrs.license or 0,
        accessxi.ptrs.lobby or 0,
        accessxi.ptrs.select or 0,
        accessxi.ptrs.yesno or 0));
    load_step('startup-speak', function () speak('Access XI Final Fantasy XI menu reader loaded.'); end);
end

ashita.events.register('load', 'load_cb', function ()
    accessxi.run_load_startup('load-event');
end);
accessxi.run_load_startup('top-level');

ashita.events.register('unload', 'unload_cb', function ()
    accessxi.axi_drive_stop('unload');
    if (accessxi.nav_dat_collision_state ~= nil) then
        accessxi.nav_dat_collision_state:shutdown();
        accessxi.nav_dat_collision_state = nil;
    end
    local ok, result = pcall(function () return accessxi.unload_searchhook(); end);
    if (not ok) then
        log_line(('searchhook shutdown failed during unload error="%s"'):fmt(
            accessxi.escape_probe_log_text(tostring(result or ''))));
    end
    if (ffxinav ~= nil and accessxi.nav_mesh_handle ~= nil) then
        pcall(function () ffxinav.DisposeFFXINavClass(accessxi.nav_mesh_handle); end);
        accessxi.nav_mesh_handle = nil;
    end
    accessxi.prism_reset_speech();
end);

ashita.events.register('text_in', 'accessxi_reader_text_in_cb', function (e)
    local mode = tonumber(e.mode) or tonumber(e.mode_modified) or 0;
    local mid = bit.band(mode, 0xFF);
    local injected = e.injected == true;

    local text = accessxi.clean_incoming_text(e.message or e.message_modified or '');
    accessxi.chat_text_in_diag(e, mid, text);
    if (text == '' or injected or e.blocked == true) then
        return;
    end
    safe_call(function ()
        accessxi.cache_check_title_from_chat(mid, text);
    end, false);
    safe_call(function ()
        accessxi.search_result_remember_chat_summary(text);
    end, false);
    safe_call(function ()
        accessxi.remember_delivery_box_slot_text(text);
    end, false);

    local now = tick();
    if ((mid == 150 or mid == 151)
        and type(accessxi.nav_mission_quest_observe_interaction_text) == 'function') then
        local target_name = accessxi.combat_target_name();
        if (target_name == '') then target_name = tostring(accessxi.last_target_name or ''); end
        pcall(function ()
            accessxi.nav_mission_quest_observe_interaction_text(
                get_menu_name() or '',
                target_name,
                accessxi.combat_current_target_server_id(),
                text,
                now);
        end);
    end
    if (mid ~= 150 and mid ~= 151) then
        if (accessxi.chat_text_is_recent_npc_echo(mid, text, now)) then
            log_line(('chat text npc echo suppressed mode=%d "%s"'):fmt(mid, accessxi.escape_probe_log_text(text)));
            return;
        end
        accessxi.handle_chat_text(mid, text, injected);
        return;
    end

    if (text:contains('Before you lies a survival guide', true)) then
        accessxi.survival_guide_context = 'chapter';
        accessxi.survival_guide_last_area_category = 0;
        accessxi.survival_guide_last_region_category = 0;
        accessxi.survival_guide_destination_page_index = 0;
        accessxi.survival_guide_destination_start_index = 1;
        accessxi.survival_guide_pending_page_turn = '';
        accessxi.survival_guide_last_query_list_signature = '';
    elseif (text:contains('adventurers may travel to the location', true) or text:contains('requisite amount of tabs', true)) then
        accessxi.survival_guide_context = 'teleport';
        accessxi.survival_guide_last_area_category = 0;
        accessxi.survival_guide_last_region_category = 0;
        accessxi.survival_guide_destination_page_index = 0;
        accessxi.survival_guide_destination_start_index = 1;
        accessxi.survival_guide_pending_page_turn = '';
        accessxi.survival_guide_last_query_list_signature = '';
    elseif (text:contains('change the way you select areas', true)) then
        accessxi.survival_guide_context = 'sort';
        accessxi.survival_guide_last_area_category = 0;
        accessxi.survival_guide_last_region_category = 0;
        accessxi.survival_guide_destination_page_index = 0;
        accessxi.survival_guide_destination_start_index = 1;
        accessxi.survival_guide_pending_page_turn = '';
        accessxi.survival_guide_last_query_list_signature = '';
    elseif (text:contains('Area selection will now be made by region', true)) then
        accessxi.survival_guide_sort_mode = 'region';
        accessxi.survival_guide_context = 'chapter';
        accessxi.survival_guide_last_area_category = 0;
        accessxi.survival_guide_last_region_category = 0;
        accessxi.survival_guide_destination_page_index = 0;
        accessxi.survival_guide_destination_start_index = 1;
        accessxi.survival_guide_pending_page_turn = '';
        accessxi.survival_guide_last_query_list_signature = '';
    elseif (text:contains('Area selection will now be made by content', true) or text:contains('Area selection will now be made by expansion', true)) then
        accessxi.survival_guide_sort_mode = 'content';
        accessxi.survival_guide_context = 'chapter';
        accessxi.survival_guide_last_area_category = 0;
        accessxi.survival_guide_last_region_category = 0;
        accessxi.survival_guide_destination_page_index = 0;
        accessxi.survival_guide_destination_start_index = 1;
        accessxi.survival_guide_pending_page_turn = '';
        accessxi.survival_guide_last_query_list_signature = '';
    end

    local key = ('%d:%s'):fmt(mid, text);
    if (key == accessxi.last_npc_text_key and (now - (accessxi.last_npc_text_tick or 0)) < 2500) then
        return;
    end

    accessxi.last_npc_text_key = key;
    accessxi.last_npc_text_tick = now;
    accessxi.last_npc_echo_compare_text = accessxi.npc_echo_compare_text(text);
    accessxi.last_npc_echo_tick = now;
    accessxi.chat_add_history(mid, text, injected);
    accessxi.npc_text_hold_until = now + 900;
    accessxi.last = '';
    accessxi.last_key = '';
    accessxi.last_log = '';
    accessxi.last_log_key = '';
    speak(text);
    log_line(('npc text mode=%d "%s"'):fmt(mid, text));
end);

