function accessxi.input_flag_text(value)
    if (value == nil) then
        return 'unknown';
    end

    if (type(value) == 'boolean') then
        return value and 'on' or 'off';
    end

    local number = tonumber(value);
    if (number ~= nil) then
        return number ~= 0 and 'on' or 'off';
    end

    local text = tostring(value or ''):lower();
    if (text == 'true' or text == 'on' or text == 'yes') then
        return 'on';
    end
    if (text == 'false' or text == 'off' or text == 'no') then
        return 'off';
    end

    return tostring(value);
end

function accessxi.input_flag_is_on(value)
    if (value == nil) then
        return false;
    end
    if (type(value) == 'boolean') then
        return value;
    end

    local number = tonumber(value);
    if (number ~= nil) then
        return number ~= 0;
    end

    local text = tostring(value or ''):lower();
    return (text == 'true' or text == 'on' or text == 'yes');
end

function accessxi.input_state_text()
    local keyboard = safe_call(function () return AshitaCore:GetInputManager():GetKeyboard(); end, nil);
    local mouse = safe_call(function () return AshitaCore:GetInputManager():GetMouse(); end, nil);
    local target = safe_call(function () return AshitaCore:GetMemoryManager():GetTarget(); end, nil);
    local auto_follow = safe_call(function () return AshitaCore:GetMemoryManager():GetAutoFollow(); end, nil);

    local keyboard_block = keyboard ~= nil and safe_call(function () return keyboard:GetBlockInput(); end, nil) or nil;
    local keyboard_block_binds = keyboard ~= nil and safe_call(function () return keyboard:GetBlockBindsDuringInput(); end, nil) or nil;
    local mouse_block = mouse ~= nil and safe_call(function () return mouse:GetBlockInput(); end, nil) or nil;
    local menu_open = target ~= nil and safe_call(function () return target:GetIsMenuOpen(); end, nil) or nil;
    local default_mode = target ~= nil and safe_call(function () return target:GetDefaultMode(); end, nil) or nil;
    local menu_lock = target ~= nil and safe_call(function () return target:GetMenuTargetLock(); end, nil) or nil;
    local player_moving = target ~= nil and safe_call(function () return target:GetIsPlayerMoving(); end, nil) or nil;
    local focus_index = target ~= nil and safe_call(function () return target:GetFocusTargetIndex(); end, nil) or nil;
    local window_loaded = target ~= nil and safe_call(function () return target:GetWindowIsWindowLoaded(); end, nil) or nil;
    local window_name = target ~= nil and safe_call(function () return target:GetWindowName(); end, '') or '';
    local auto_running = auto_follow ~= nil and safe_call(function () return auto_follow:GetIsAutoRunning(); end, nil) or nil;
    local chat_open = (is_chat_input_open ~= nil) and safe_call(function () return is_chat_input_open(); end, nil) or nil;
    local now = tick();
    local zoning_watch = accessxi.nav_zoning_watch_active(now);
    local zone_settle = accessxi.nav_zone_load_settle_active(now);
    local menu_name = tostring(get_menu_name() or '');
    local position_text = 'Position unavailable during zone transition.';
    if (not zoning_watch and not zone_settle) then
        position_text = nav_position_speech(nav_cached_player_position());
    end
    local nav_text = accessxi.nav_active == true and 'active' or 'inactive';
    if (zoning_watch) then
        nav_text = 'zoning';
    elseif (zone_settle) then
        nav_text = 'settling';
    end

    local text = ('Input state. Keyboard block %s. Binds during input %s. Mouse block %s. Chat input %s. Native menu %s. Target menu %s. Target lock %s. Default mode %s. Moving %s. Auto run %s. Nav %s. Zone watch %s. Zone settle %s. %s'):fmt(
        accessxi.input_flag_text(keyboard_block),
        accessxi.input_flag_text(keyboard_block_binds),
        accessxi.input_flag_text(mouse_block),
        accessxi.input_flag_text(chat_open),
        menu_name ~= '' and accessxi.speech_name(menu_name) or 'none',
        accessxi.input_flag_text(menu_open),
        tostring(menu_lock or 'unknown'),
        tostring(default_mode or 'unknown'),
        accessxi.input_flag_text(player_moving),
        accessxi.input_flag_text(auto_running),
        nav_text,
        accessxi.input_flag_text(zoning_watch),
        accessxi.input_flag_text(zone_settle),
        position_text);

    log_line('input state ' .. ('keyboardBlock=%s keyboardBindsDuringInput=%s mouseBlock=%s chatOpen=%s menu="%s" targetMenu=%s targetLock=%s defaultMode=%s moving=%s autoRun=%s focus=%s winLoaded=%s window="%s" navActive=%s zoneWatch=%s zoneSettle=%s position="%s"'):fmt(
        tostring(keyboard_block),
        tostring(keyboard_block_binds),
        tostring(mouse_block),
        tostring(chat_open),
        accessxi.escape_probe_log_text(menu_name),
        tostring(menu_open),
        tostring(menu_lock),
        tostring(default_mode),
        tostring(player_moving),
        tostring(auto_running),
        tostring(focus_index),
        tostring(window_loaded),
        accessxi.escape_probe_log_text(window_name),
        tostring(accessxi.nav_active == true),
        tostring(zoning_watch),
        tostring(zone_settle),
        accessxi.escape_probe_log_text(position_text)));

    return text;
end

function accessxi.input_fix_text()
    local actions = T{};
    local keyboard = safe_call(function () return AshitaCore:GetInputManager():GetKeyboard(); end, nil);
    if (keyboard ~= nil and accessxi.input_flag_is_on(safe_call(function () return keyboard:GetBlockInput(); end, nil))) then
        safe_call(function () keyboard:SetBlockInput(false); return true; end, false);
        actions:append('keyboard block input');
    end
    if (keyboard ~= nil and accessxi.input_flag_is_on(safe_call(function () return keyboard:GetBlockBindsDuringInput(); end, nil))) then
        safe_call(function () keyboard:SetBlockBindsDuringInput(false); return true; end, false);
        actions:append('keyboard binds during input');
    end

    local mouse = safe_call(function () return AshitaCore:GetInputManager():GetMouse(); end, nil);
    if (mouse ~= nil and accessxi.input_flag_is_on(safe_call(function () return mouse:GetBlockInput(); end, nil))) then
        safe_call(function () mouse:SetBlockInput(false); return true; end, false);
        actions:append('mouse block input');
    end

    if ((tonumber(accessxi.nav_zoning_watch_until) or 0) > 0) then
        accessxi.nav_clear_zoning_watch('inputfix');
        actions:append('nav zoning watch');
    end
    if ((tonumber(accessxi.nav_zone_load_settle_until) or 0) > 0) then
        accessxi.nav_clear_zone_load_settle('inputfix');
        actions:append('nav zone settle');
    end

    local had_nav_collision_quiet = ((tonumber(accessxi.nav_collision_quiet_until) or 0) > tick())
        or accessxi.nav_collision_require_fresh_movement == true
        or accessxi.nav_collision_freewalk_x ~= nil
        or accessxi.nav_collision_freewalk_z ~= nil;
    accessxi.nav_collision_quiet_until = 0;
    accessxi.nav_collision_quiet_reason = '';
    accessxi.nav_collision_require_fresh_movement = false;
    accessxi.nav_collision_freewalk_x = nil;
    accessxi.nav_collision_freewalk_z = nil;
    accessxi.nav_collision_freewalk_yaw = nil;
    accessxi.nav_collision_freewalk_tick = 0;
    accessxi.nav_collision_freewalk_last_sound_tick = 0;
    accessxi.nav_collision_freewalk_last_log_key = '';
    accessxi.nav_collision_route_contact_last_sound_tick = 0;
    accessxi.nav_collision_route_contact_last_log_key = '';
    accessxi.nav_collision_forward_intent_tick = 0;
    accessxi.nav_collision_forward_intent_key = 0;
    accessxi.nav_movement_recent_tick = 0;
    accessxi.nav_movement_last_move_count_tick = 0;
    accessxi.nav_movement_last_x = nil;
    accessxi.nav_movement_last_z = nil;
    accessxi.nav_movement_last_tick = 0;
    if (had_nav_collision_quiet) then
        actions:append('nav collision quiet');
    end

    local prefix = 'No input or nav recovery flags were on.';
    if (#actions > 0) then
        prefix = ('Cleared %s.'):fmt(actions:concat(' and '));
    end

    log_line(('input fix actions="%s"'):fmt(accessxi.escape_probe_log_text(actions:concat(','))));
    return ('%s %s'):fmt(prefix, accessxi.input_state_text());
end

function accessxi.debug_command_context()
    return T{
        accessxi = accessxi,
        speak = speak,
        log_line = log_line,
        tick = tick,
        command_tail = command_tail,
        get_menu_name = get_menu_name,
        safe_call = safe_call,
        enable_equipment_probe = enable_equipment_probe,
        dump_current_menu = dump_current_menu,
    };
end

function accessxi.axi_command_args_from_text(text)
    local args = T{};
    for part in tostring(text or ''):gmatch('%S+') do
        args:append(part);
    end
    return args;
end

function accessxi.axi_command_text_from_args(args)
    local parts = T{};
    if (type(args) ~= 'table') then
        return '';
    end
    for i = 1, #args do
        parts:append(tostring(args[i] or ''));
    end
    return parts:concat(' '):trim();
end

function accessxi.is_axi_command_args(args)
    if (type(args) ~= 'table' or #args == 0) then
        return false;
    end
    local first = tostring(args[1] or ''):lower();
    return first == '/accessxi' or first == '/axi' or first == '/ax';
end

function accessxi.queue_axi_command_replay(command_text, source, menu_name, now)
    now = tonumber(now) or tick();
    local args = accessxi.axi_command_args_from_text(command_text);
    if (not accessxi.is_axi_command_args(args)) then
        return false;
    end

    local normalized = accessxi.axi_command_text_from_args(args);
    if (normalized == '') then
        return false;
    end
    if (normalized == tostring(accessxi.axi_command_last_event_text or '')
        and (now - (tonumber(accessxi.axi_command_last_event_tick) or 0)) < 700) then
        return false;
    end
    if (normalized == tostring(accessxi.axi_command_replay_last_text or '')
        and (now - (tonumber(accessxi.axi_command_replay_last_tick) or 0)) < 1200) then
        return false;
    end

    accessxi.axi_command_pending_text = normalized;
    accessxi.axi_command_pending_due = now + 180;
    accessxi.axi_command_pending_source = tostring(source or 'chat-input-clear');
    accessxi.axi_command_pending_menu = tostring(menu_name or '');
    log_line(('axi command replay queued source=%s menu="%s" command="%s"'):fmt(
        accessxi.escape_probe_log_text(accessxi.axi_command_pending_source),
        accessxi.escape_probe_log_text(accessxi.axi_command_pending_menu),
        accessxi.escape_probe_log_text(normalized)));
    return true;
end

function accessxi.note_axi_command_input_transition(previous_state, state, menu_name, now)
    if (type(previous_state) ~= 'table') then
        return false;
    end

    local previous_raw = clean_chat_input_text(previous_state.raw or previous_state.display or ''):trim();
    local previous_args = accessxi.axi_command_args_from_text(previous_raw);
    if (not accessxi.is_axi_command_args(previous_args)) then
        return false;
    end

    local current_raw = '';
    if (type(state) == 'table') then
        current_raw = clean_chat_input_text(state.raw or state.display or ''):trim();
    end
    if (current_raw ~= '') then
        return false;
    end

    now = tonumber(now) or tick();
    if ((now - (tonumber(accessxi.chat_input_last_enter_tick) or 0)) > 900) then
        return false;
    end

    return accessxi.queue_axi_command_replay(previous_raw, 'chat-input-clear', menu_name, now);
end

function accessxi.handle_axi_command(args, e, source)
    e = e or T{};
    source = tostring(source or 'event');
    if (#args == 0 or (args[1] ~= '/accessxi' and args[1] ~= '/axi' and args[1] ~= '/ax')) then
        return false;
    end

    if (#args >= 2 and type(accessxi.debug_commands.handle) == 'function') then
        local ok, handled = pcall(function ()
            return accessxi.debug_commands.handle(args, accessxi.debug_command_context());
        end);
        if (not ok) then
            e.blocked = true;
            log_line(('debug command failed error="%s"'):fmt(accessxi.escape_probe_log_text(handled)));
            speak('Debug command failed. Error written.');
            return true;
        end
        if (handled == true) then
            e.blocked = true;
            return true;
        end
    end

    if (#args >= 2 and args[2]:any('menu', 'read')) then
        e.blocked = true;
        local text = current_menu_speech() or 'No supported Final Fantasy XI login menu detected.';
        speak(text);
        log_line('manual ' .. text);
    elseif (#args >= 2 and args[2]:any('console', 'ashita', 'sidebar')) then
        e.blocked = true;
        accessxi.ashita_console_command(args);
    elseif (#args >= 2 and args[2]:any('drive', 'move', 'steer')) then
        e.blocked = true;
        local text = accessxi.axi_drive_command(args);
        speak(text);
        log_line('axi drive manual ' .. text);
    elseif (#args >= 2 and args[2]:any('check', 'checksummary', 'checkstats', 'checkinfo')) then
        e.blocked = true;
        local text = accessxi.safe_check_character_summary('check-command') or 'No safe checked character summary is available.';
        speak(text);
        log_line('check manual ' .. text);
    elseif (#args >= 2 and args[2]:any('target', 'look', 'inspect', 'readtarget')) then
        e.blocked = true;
        local text = accessxi.current_target_or_nearest_speech();
        speak(text);
        log_line('target manual ' .. text);
    elseif (#args >= 2 and args[2]:any('zonesearch', 'zsearch')) then
        e.blocked = true;
        local text = accessxi.nav_zone_search_start(command_tail(args, 3));
        speak(text);
        log_line('nav zone search manual ' .. text);
    elseif (#args >= 2 and args[2]:any('record', 'recorder', 'routelog')) then
        e.blocked = true;
        local text = accessxi.nav_route_recorder_command(args, 3, 4);
        speak(text);
        log_line('nav route recorder manual ' .. text);
    elseif (#args >= 3 and args[2]:any('route') and args[3]:any('record', 'recorder', 'routelog')) then
        e.blocked = true;
        local text = accessxi.nav_route_recorder_command(args, 4, 5);
        speak(text);
        log_line('nav route recorder manual ' .. text);
    elseif (#args >= 2 and args[2]:any('nav', 'navigation', 'dest')) then
        e.blocked = true;
        if (#args >= 3 and args[3]:any('capture', 'discover')) then
            local text = nav_capture_nearby(25);
            speak(text);
            log_line('nav manual ' .. text);
        elseif (#args >= 3 and args[3]:any('select', 'start')) then
            nav_menu_start_route();
        elseif (#args >= 3 and args[3]:any('reload', 'refresh')) then
            accessxi.nav_points_loaded = false;
            accessxi.nav_zoneline_edges_loaded = false;
            accessxi.nav_zoneline_edges:clear();
            accessxi.nav_route_overrides_loaded = false;
            accessxi.nav_route_overrides:clear();
            nav_load_points();
            local text = ('Navigation database reloaded. %d destinations.'):fmt(accessxi.nav_points:len());
            speak(text);
            log_line('nav manual ' .. text);
        elseif (#args >= 3 and args[3]:any('record', 'recorder', 'routelog')) then
            local text = accessxi.nav_route_recorder_command(args, 4, 5);
            speak(text);
            log_line('nav route recorder manual ' .. text);
        elseif (#args >= 3 and args[3]:any('stop')) then
            local text = nav_route_stop();
            speak(text);
            log_line('nav manual ' .. text);
        elseif (#args >= 3 and args[3]:any('search', 'find', 'filter')) then
            local query = command_tail(args, 4);
            if (nav_clean_field(query) == '') then
                speak('Navigation search needs a name.');
            else
                nav_open_menu(query);
            end
        elseif (#args >= 3 and args[3]:any('route', 'goto')) then
            local text = nav_route_start(command_tail(args, 4));
            speak(text);
            log_line('nav manual ' .. text);
        elseif (#args >= 3 and args[3]:any('prove', 'proven', 'good')) then
            local text = nav_route_mark_result('proven', 'proven');
            speak(text);
            log_line('nav manual ' .. text);
        elseif (#args >= 3 and args[3]:any('bad', 'fail', 'wrong')) then
            local text = nav_route_mark_result('bad', 'bad');
            speak(text);
            log_line('nav manual ' .. text);
        elseif (#args >= 3 and args[3]:any('here', 'verifyhere', 'correcthere', 'sethere')) then
            local text = accessxi.nav_mark_destination_here(command_tail(args, 4));
            speak(text);
            log_line('nav manual ' .. text);
        elseif (#args >= 3 and args[3]:any('audit', 'evidence')) then
            local text = accessxi.nav_route_audit_speech();
            speak(text);
            log_line('nav manual ' .. text);
        elseif (#args >= 3 and args[3]:any('checklist', 'coverage', 'status')) then
            local text = accessxi.nav_zone_checklist_speech();
            speak(text);
            log_line('nav manual ' .. text);
        elseif (#args >= 3 and args[3]:any('marktarget', 'markt')) then
            local text = nav_mark_target(command_tail(args, 4));
            speak(text);
            log_line('nav manual ' .. text);
        elseif (#args >= 3 and args[3]:any('marktargetnm', 'marktnm')) then
            local text = accessxi.nav_mark_target_as(command_tail(args, 4), 'nm spawn');
            speak(text);
            log_line('nav manual ' .. text);
        elseif (#args >= 3 and args[3]:any('marknm', 'markspawn', 'nmspawn')) then
            local text = accessxi.nav_mark_current_as(command_tail(args, 4), 'nm spawn', 'NM spawn');
            speak(text);
            log_line('nav manual ' .. text);
        elseif (#args >= 3 and args[3]:any('mark', 'markpos')) then
            local text = nav_mark_current(command_tail(args, 4));
            speak(text);
            log_line('nav manual ' .. text);
        elseif (#args >= 3 and args[3]:any('nearby', 'scan')) then
            local _, text = nav_nearby(8);
            speak(text);
            log_line('nav manual ' .. text);
        elseif (#args >= 3 and args[3]:any('points', 'destinations')) then
            local text = nav_points_speech();
            speak(text);
            log_line('nav manual ' .. text);
        elseif (#args >= 3 and args[3]:any('pos', 'position', 'where')) then
            local text = nav_position_speech(nav_cached_player_position());
            speak(text);
            log_line('nav manual ' .. text);
        elseif (#args >= 3 and args[3]:any('clearance', 'wall')) then
            local player = nav_cached_player_position();
            local wall = accessxi.nav_wall_distance(player);
            local text = wall ~= nil and ('Wall clearance %.1f yalms.'):fmt(wall) or 'Wall clearance unavailable.';
            speak(text);
            log_line('nav manual ' .. text);
        else
            nav_open_menu();
        end
    elseif (#args >= 2 and args[2]:any('beacon', 'navbeacon')) then
        e.blocked = true;
        if (#args >= 3 and args[3]:any('off', 'disable', '0')) then
            accessxi.nav_beacon_enabled = false;
            accessxi.nav_beacon_last_key = '';
            speak('Navigation beacon off.');
            log_line('nav beacon off');
        elseif (#args >= 3 and args[3]:any('hrtf', 'headphone', 'headphones', 'binaural')) then
            local mode, reason = accessxi.nav_beacon_save_audio_mode('hrtf');
            local ready = mode ~= nil and accessxi.nav_beacon_ensure_files();
            if (ready and accessxi.nav_beacon_bank == 'hrtf') then
                speak('Navigation beacon headphone H R T F audio on.');
                log_line('nav beacon audio mode hrtf');
            else
                speak(tostring(reason or 'H R T F audio is unavailable. Compatibility stereo is active.'));
                log_line('nav beacon audio mode hrtf unavailable');
            end
        elseif (#args >= 3 and args[3]:any('speaker', 'speakers', 'stereo', 'compatibility')) then
            local mode, reason = accessxi.nav_beacon_save_audio_mode('compatibility');
            local ready = mode ~= nil and accessxi.nav_beacon_ensure_files();
            if (ready) then
                speak('Navigation beacon speaker compatibility stereo on.');
                log_line('nav beacon audio mode compatibility');
            else
                speak(tostring(reason or 'Navigation beacon audio is unavailable.'));
            end
        elseif (#args >= 3 and args[3]:any('status', 'audio')) then
            accessxi.nav_beacon_ensure_files();
            local text = accessxi.nav_beacon_bank == 'hrtf'
                and 'Navigation beacon uses headphone H R T F audio.'
                or 'Navigation beacon uses speaker compatibility stereo.';
            speak(text);
            log_line('nav beacon audio status ' .. tostring(accessxi.nav_beacon_bank));
        else
            accessxi.nav_beacon_enabled = true;
            accessxi.nav_beacon_last_tick = 0;
            accessxi.nav_beacon_last_key = '';
            speak('Navigation beacon on.');
            log_line('nav beacon on');
        end
    elseif (#args >= 2 and args[2]:any('enemywarn', 'aggro')) then
        e.blocked = true;
        if (#args >= 3 and args[3]:any('off', 'disable', '0')) then
            accessxi.enemy_warning_enabled = false;
            accessxi.enemy_warning_last_key = '';
            speak('Enemy warning off.');
            log_line('enemy warning off');
        elseif (#args >= 3 and (args[3]:any('range', 'distance') or tonumber(args[3]) ~= nil)) then
            local value = tonumber(args[3]) or tonumber(args[4]);
            if (value == nil) then
                speak(('Enemy warning range %.0f yalms.'):fmt(accessxi.enemy_warning_range or 35));
            else
                accessxi.enemy_warning_range = math.max(8, math.min(value, tonumber(accessxi.nav_widescan_max_range) or 350));
                accessxi.enemy_warning_last_tick = 0;
                accessxi.enemy_warning_last_key = '';
                speak(('Enemy warning range %.0f yalms.'):fmt(accessxi.enemy_warning_range or 35));
                log_line(('enemy warning range %.0f'):fmt(accessxi.enemy_warning_range or 35));
            end
        else
            accessxi.enemy_warning_enabled = true;
            accessxi.enemy_warning_last_tick = 0;
            accessxi.enemy_warning_last_key = '';
            speak(('Enemy warning on. Range %.0f yalms.'):fmt(accessxi.enemy_warning_range or 35));
            log_line('enemy warning on');
        end
    elseif (#args >= 2 and args[2]:any('enemies', 'mobs')) then
        e.blocked = true;
        local enemies = accessxi.nav_live_enemies(accessxi.nav_live_entity_search_range());
        if (#enemies == 0) then
            speak('No visible enemies in this zone.');
            log_line('nav enemies none');
            accessxi.nav_log_entity_candidates('nav enemies candidate', 12);
        else
            local parts = T{};
            for i = 1, math.min(8, #enemies) do
                local enemy = enemies[i];
                parts:append(('%s %.0f yalms'):fmt(accessxi.speech_name(enemy.name or 'enemy'), enemy.distance or 0));
            end
            local text = ('Visible enemies. %s.'):fmt(parts:concat('. '));
            speak(text);
            log_line('nav enemies ' .. text);
        end
    elseif (#args >= 2 and args[2]:any('pos', 'position', 'where')) then
        e.blocked = true;
        local text = nav_position_speech(nav_cached_player_position());
        speak(text);
        log_line('nav manual ' .. text);
    elseif (#args >= 2 and args[2]:any('clearance', 'wall')) then
        e.blocked = true;
        local player = nav_cached_player_position();
        local wall = accessxi.nav_wall_distance(player);
        local text = wall ~= nil and ('Wall clearance %.1f yalms.'):fmt(wall) or 'Wall clearance unavailable.';
        speak(text);
        log_line('nav manual ' .. text);
    elseif (#args >= 2 and args[2]:any('nearby', 'scan')) then
        e.blocked = true;
        local _, text = nav_nearby(8);
        speak(text);
        log_line('nav manual ' .. text);
    elseif (#args >= 2 and args[2]:any('marktarget', 'markt')) then
        e.blocked = true;
        local text = nav_mark_target(command_tail(args, 3));
        speak(text);
        log_line('nav manual ' .. text);
    elseif (#args >= 2 and args[2]:any('marktargetnm', 'marktnm')) then
        e.blocked = true;
        local text = accessxi.nav_mark_target_as(command_tail(args, 3), 'nm spawn');
        speak(text);
        log_line('nav manual ' .. text);
    elseif (#args >= 2 and args[2]:any('marknm', 'markspawn', 'nmspawn')) then
        e.blocked = true;
        local text = accessxi.nav_mark_current_as(command_tail(args, 3), 'nm spawn', 'NM spawn');
        speak(text);
        log_line('nav manual ' .. text);
    elseif (#args >= 2 and args[2]:any('mark', 'markpos')) then
        e.blocked = true;
        local text = nav_mark_current(command_tail(args, 3));
        speak(text);
        log_line('nav manual ' .. text);
    elseif (#args >= 2 and args[2]:any('points', 'destinations')) then
        e.blocked = true;
        local text = nav_points_speech();
        speak(text);
        log_line('nav manual ' .. text);
    elseif (#args >= 2 and args[2]:any('route', 'goto')) then
        e.blocked = true;
        local text = nav_route_start(command_tail(args, 3));
        speak(text);
        log_line('nav manual ' .. text);
    elseif (#args >= 2 and args[2]:any('stoproute', 'stopnav')) then
        e.blocked = true;
        local text = nav_route_stop();
        speak(text);
        log_line('nav manual ' .. text);
    elseif (#args >= 2 and args[2]:any('navhere', 'verifyhere', 'correcthere')) then
        e.blocked = true;
        local text = accessxi.nav_mark_destination_here(command_tail(args, 3));
        speak(text);
        log_line('nav manual ' .. text);
    elseif (#args >= 2 and args[2]:any('navaudit', 'routeaudit')) then
        e.blocked = true;
        local text = accessxi.nav_route_audit_speech();
        speak(text);
        log_line('nav manual ' .. text);
    elseif (#args >= 2 and args[2]:any('navchecklist', 'mapchecklist')) then
        e.blocked = true;
        local text = accessxi.nav_zone_checklist_speech();
        speak(text);
        log_line('nav manual ' .. text);
    end
    return e.blocked == true;
end

function accessxi.dispatch_axi_command_text(command_text, source)
    local args = accessxi.axi_command_args_from_text(command_text);
    if (not accessxi.is_axi_command_args(args)) then
        return false;
    end
    local fake_event = T{ blocked = false };
    return accessxi.handle_axi_command(args, fake_event, source or 'chat-input-replay') == true;
end

function accessxi.poll_axi_external_control(now)
    now = tonumber(now) or tick();
    if ((now - (tonumber(accessxi.axi_external_control_poll_tick) or 0))
        < (tonumber(accessxi.axi_external_control_poll_ms) or 150)) then
        return false;
    end
    accessxi.axi_external_control_poll_tick = now;

    local f = io.open(accessxi.axi_external_control_path, 'r');
    if (f == nil) then
        return false;
    end

    local command_text = tostring(f:read('*a') or '');
    f:close();
    os.remove(accessxi.axi_external_control_path);
    command_text = command_text:gsub('\r', ''):gsub('\n+$', ''):trim();
    if command_text == '' then
        log_line('axi external control rejected reason="empty"');
        return true;
    end
    if command_text:find('\n', 1, true) ~= nil then
        log_line('axi external control rejected reason="multiple-lines"');
        return true;
    end

    local args = accessxi.axi_command_args_from_text(command_text);
    if not accessxi.is_axi_command_args(args) then
        log_line(('axi external control rejected reason="not-axi" command="%s"'):fmt(
            accessxi.escape_probe_log_text(command_text)));
        return true;
    end

    local ok, handled = pcall(function ()
        return accessxi.dispatch_axi_command_text(command_text, 'external-control-file');
    end);
    if not ok then
        log_line(('axi external control failed command="%s" error="%s"'):fmt(
            accessxi.escape_probe_log_text(command_text),
            accessxi.escape_probe_log_text(tostring(handled or ''))));
        return true;
    end

    log_line(('axi external control handled=%s command="%s"'):fmt(
        tostring(handled == true),
        accessxi.escape_probe_log_text(command_text)));
    return true;
end

function accessxi.poll_pending_axi_command_replay()
    local command_text = tostring(accessxi.axi_command_pending_text or '');
    if (command_text == '') then
        return false;
    end

    local now = tick();
    if (now < (tonumber(accessxi.axi_command_pending_due) or 0)) then
        return false;
    end

    accessxi.axi_command_pending_text = '';
    accessxi.axi_command_pending_due = 0;

    if (command_text == tostring(accessxi.axi_command_last_event_text or '')
        and (now - (tonumber(accessxi.axi_command_last_event_tick) or 0)) < 700) then
        log_line(('axi command replay skipped reason=event-handled command="%s"'):fmt(
            accessxi.escape_probe_log_text(command_text)));
        return false;
    end

    accessxi.axi_command_replay_last_text = command_text;
    accessxi.axi_command_replay_last_tick = now;
    local ok, handled = pcall(function ()
        return accessxi.dispatch_axi_command_text(command_text, accessxi.axi_command_pending_source or 'chat-input-replay');
    end);
    if (not ok) then
        log_line(('axi command replay failed command="%s" error="%s"'):fmt(
            accessxi.escape_probe_log_text(command_text),
            accessxi.escape_probe_log_text(tostring(handled or ''))));
        speak('AXI command replay failed. Error written.');
        return true;
    end

    log_line(('axi command replay handled=%s command="%s"'):fmt(
        tostring(handled == true),
        accessxi.escape_probe_log_text(command_text)));
    return handled == true;
end

ashita.events.register('command', 'command_cb', function (e)
    local args = e.command:args();
    if (not accessxi.is_axi_command_args(args)) then
        return;
    end

    local command_text = accessxi.axi_command_text_from_args(args);
    local now = tick();
    if (command_text == tostring(accessxi.axi_command_replay_last_text or '')
        and (now - (tonumber(accessxi.axi_command_replay_last_tick) or 0)) < 900) then
        e.blocked = true;
        log_line(('axi command event skipped duplicate replay command="%s"'):fmt(
            accessxi.escape_probe_log_text(command_text)));
        return;
    end

    accessxi.axi_command_last_event_text = command_text;
    accessxi.axi_command_last_event_tick = now;
    if (command_text == tostring(accessxi.axi_command_pending_text or '')) then
        accessxi.axi_command_pending_text = '';
        accessxi.axi_command_pending_due = 0;
    end

    accessxi.handle_axi_command(args, e, 'event');
end);
ashita.events.register('key', 'accessxi_reader_key_cb', function (e)
    local key = tonumber(e.wparam) or 0;
    local key_is_up = bit.band(tonumber(e.lparam) or 0, 0x80000000) ~= 0;
    if (key_is_up) then
        accessxi.nav_collision_note_movement_key(key, false);
        accessxi.config_chat_filter_note_confirm_key_up(key);
        accessxi.config_log_window_designation_note_confirm_key_up(key);
        return;
    end
    accessxi.nav_collision_note_movement_key(key, true);

    if (key == VK_RETURN and is_chat_input_open ~= nil and is_chat_input_open()) then
        accessxi.chat_input_last_enter_tick = tick();
    end

    -- Ashita exposes text-entry keys through WNDPROC separately from the
    -- DirectInput game-control events below.  Claim the same guarded bare
    -- letters here before FFXI can open chat with the first character.
    if (accessxi.accessibility_hotkey_owns_vk(
            key, accessxi.accessibility_hotkey_snapshot())) then
        e.blocked = true;
        return;
    end

    if (key == 0x49 and accessxi.quick_status_key_down(VK_MENU)) then
        e.blocked = true;
        return;
    end

    if (accessxi.ashita_console_open and accessxi.ashita_console_handle_key(key)) then
        e.blocked = true;
        return;
    end

    accessxi.config_chat_filter_note_confirm_key(key);
    accessxi.config_log_window_designation_note_confirm_key(key);
    accessxi.queue_trade_moneyctr_key_read(key);
    accessxi.mog_door_note_key(key);
end);

ashita.events.register('key_data', 'accessxi_accessibility_hotkeys_key_data_cb', function (e)
    local mapping = accessxi.accessibility_hotkey_directinput_map();
    local vk = mapping.dik_to_vk[tonumber(e.key) or -1];
    if (vk ~= nil
        and accessxi.accessibility_hotkey_owns_vk(
            vk, accessxi.accessibility_hotkey_snapshot())) then
        e.blocked = true;
    end
end);

ashita.events.register('key_state', 'accessxi_accessibility_hotkeys_key_state_cb', function (e)
    local size = tonumber(e.size) or 0;
    if (e.data_raw == nil or size <= 0) then
        return;
    end

    local mapping = accessxi.accessibility_hotkey_directinput_map();
    local snapshot = accessxi.accessibility_hotkey_snapshot();
    local ptr = ffi.cast('uint8_t*', e.data_raw);
    for vk, dik in pairs(mapping.vk_to_dik) do
        if (dik < size and accessxi.accessibility_hotkey_owns_vk(vk, snapshot)) then
            ptr[dik] = 0;
        end
    end
end);

ashita.events.register('key_state', 'accessxi_drive_key_state_cb', function (e)
    local directinput_key = tonumber(accessxi.axi_drive_directinput_key) or 0;
    if (directinput_key <= 0) then
        return;
    end
    if (accessxi.poll_axi_drive(tick())) then
        return;
    end
    if (e.data_raw == nil or (tonumber(e.size) or 0) <= directinput_key) then
        accessxi.axi_drive_stop('key-state-unavailable');
        return;
    end

    local ptr = ffi.cast('uint8_t*', e.data_raw);
    ptr[directinput_key] = 0x80;
end);

ashita.events.register('d3d_present', 'present_cb', function ()
    local now = tick();
    accessxi.poll_axi_drive(now);
    if (accessxi.poll_axi_external_control(now)) then
        return;
    end
    local zoning_watch = accessxi.nav_zoning_watch_active(now);
    local zone_settle = accessxi.nav_zone_load_settle_active(now);
    if (zoning_watch or zone_settle) then
        accessxi.nav_poll_zone_transition_only(now);
        accessxi.nav_route_recorder_poll(now);
        if (accessxi.nav_zone_load_settle_active(now)) then
            return;
        end
    else
        poll_nav_position();
        accessxi.nav_route_recorder_poll(now);
    end
    accessxi.poll_nav_dat_collision_preload(now);
    accessxi.poll_mission_quest_state_changes(now);
    accessxi.poll_objective_inventory_refresh(now);
    accessxi.poll_compass_hotkey();
    accessxi.poll_view_hotkey();
    accessxi.poll_combat_action_feedback();
    accessxi.poll_chat_reader_hotkeys();
    accessxi.poll_config_chat_filter_confirm_key();
    accessxi.poll_config_log_window_designation_confirm_key();
    accessxi.poll_chat_log_native_trace();
    if (accessxi.poll_chat_log_missing_retry()) then
        return;
    end
    if (accessxi.poll_quick_status_hotkeys()) then
        return;
    end
    if (accessxi.poll_status_hotkeys()) then
        return;
    end
    if (accessxi.poll_status_detail_screen_read()) then
        return;
    end
    if (accessxi.poll_status_overview_screen_read()) then
        return;
    end
    accessxi.poll_trade_moneyctr_keys();
    if (accessxi.poll_trade_moneyctr_key_read()) then
        return;
    end
    poll_menu();
    if (accessxi.poll_chat_log_deferred_speech()) then
        return;
    end
    if (accessxi.chat_log_speech_hold_active()) then
        return;
    end
    poll_chat_input();
    if (accessxi.poll_pending_axi_command_replay()) then
        return;
    end
    if (accessxi.poll_ashita_console_hotkeys()) then
        return;
    end
    if (accessxi.poll_gear_detail_hotkeys()) then
        return;
    end
    accessxi.poll_nav_browser_hotkeys();
    poll_target();
    accessxi.poll_nav_dat_collision(now);
    accessxi.poll_nav_collision_sound();
    if (accessxi.poll_nav_zone_search()) then
        return;
    end
    poll_nav_route();
    accessxi.poll_nav_beacon();
    accessxi.poll_enemy_warning();
end);
